__d(function(a,n,i,l,u,e,k){u.exports=[{title:"Doa Sebelum Tidur",arabic:"\u0628\u0650\u0627\u0633\u0652\u0645\u0650\u0643\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0623\u064e\u0645\u064f\u0648\u0652\u062a\u064f \u0648\u064e\u0623\u064e\u062d\u0652\u064a\u064e\u0627",latin:"Bismika All\u0101humma am\u016btu wa a\u1e25y\u0101",translation:"Dengan menyebut nama-Mu, ya Allah! Aku mati dan dan hidup.",notes:null,fawaid:"Dahulu nabi shallallahu 'alaihi wa sallam senantiasa memulai dan mengakhiri harinya dengan berdzikir.",source:"HR. al-Bukhari"},{title:"Doa Bangun Tidur",arabic:"\u0627\u0644\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0644\u0647\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u062d\u0652\u064a\u064e\u0627\u0646\u064e\u0627 \u0628\u0639\u0652\u062f\u064e \u0645\u064e\u0627 \u0623\u0645\u0627\u062a\u064e\u0646\u064e\u0627 \u0648\u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0627\u0644\u0646\u0651\u064f\u0634\u064f\u0648\u0631\u064f",latin:"Alhamdulill\u0101hilla\u017c\u012b a\u1e25y\u0101n\u0101 ba'da m\u0101 am\u0101tan\u0101 wa ilaihin nusy\u016br",translation:"Segala puji bagi Allah, yang telah membangunkan kami setelah menidurkan kami dan kepada-Nya lah kami dibangkitkan.",notes:null,fawaid:"Dengan membaca doa di atas, seorang hamba memulai harinya dengan memuji nama Allah yang Maha Menghidupkan dan Maha Mematikan.",source:"HR. Bukhari: 6327"},{title:"Doa Masuk Kamar Mandi",arabic:"\u0627\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062e\u064f\u0628\u064f\u062b\u0650 \u0648\u064e\u0627\u0644\u0652\u062e\u064e\u0628\u064e\u0627\u0626\u0650\u062b\u0650",latin:"All\u0101humma inn\u012b a'\u016b\u017cu bika minal khubutsi wal khab\u0101its",translation:"Ya Allah, aku berlindung pada-Mu dari (godaan) syaitan laki-laki dan perempuan.",notes:null,fawaid:"Doa ini menjadi penghalang antara aurat seorang hamba dengan jin ketika memasuki Al-khala' (kamar mandi).",source:"HR. al-Bukhari dan Muslim"},{title:"Doa Keluar Kamar Mandi",arabic:"\u063a\u064f\u0641\u0652\u0631\u064e\u0627\u0646\u064e\u0643\u064e",latin:"Ghufr\u0101naka",translation:"Aku mohon ampunan-Mu (ya Allah).",notes:null,fawaid:"Kamar mandi adalah salah satu rumah jin dan syaitan, maka dianjurkan meminta ampunan dari segala kesalahan yang sengaja maupun tidak sengaja selama di kamar mandi.",source:"HR. at-Tirmidzi"},{title:"Doa Sebelum Makan",arabic:"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650",latin:"Bismill\u0101h",translation:"Dengan nama Allah (aku mulai makan).",notes:null,fawaid:"Manfaat membaca bismillah sebelum makan adalah untuk menghalangi syaitan ikut bergabung makan bersama manusia.",source:"HR. al-Bukari No. 5376 dan Muslim No. 2022"},{title:"Doa Jika Terlupa Basmallah Diawal Makan",arabic:"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0648\u0651\u064e\u0644\u064e\u0647\u064f \u0648\u064e\u0622\u062e\u0650\u0631\u064e\u0647\u064f",latin:"Bismill\u0101hi awwalahu wa \u0101khirahu",translation:"Dengan menyebut nama Allah, untuk awal dan akhir (makan).",notes:null,fawaid:"Islam sangat memperhatikan adab, sekiranya anak adam lupa membaca doa makan di awal tetap dianjurkan membaca doa di pertengahan walaupun tersisa sesendok nasi.",source:"HR. Abu Dawud"},{title:"Doa Sesudah Makan",arabic:"\u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u064e\u0651\u0647\u0650 \u0627\u0644\u064e\u0651\u0630\u0650\u0649 \u0623\u064e\u0637\u0652\u0639\u064e\u0645\u064e\u0646\u0650\u0649 \u0647\u064e\u0630\u064e\u0627 \u0648\u064e\u0631\u064e\u0632\u064e\u0642\u064e\u0646\u0650\u064a\u0647\u0650 \u0645\u0650\u0646\u0652 \u063a\u064e\u064a\u0652\u0631\u0650 \u062d\u064e\u0648\u0652\u0644\u064d \u0645\u0650\u0646\u0650\u0651\u0649 \u0648\u064e\u0644\u0627\u064e \u0642\u064f\u0648\u064e\u0651\u0629\u064d",latin:"Alhamdulill\u0101hilla\u017c\u012b a\u1e6d\u2018aman\u012b h\u0101\u017c\u0101 wa razaqan\u012bhi min ghayri \u1e25awlin minn\u012b wa l\u0101 quwwatin",translation:"Segala puji bagi Allah yang telah memberiku makanan ini, dan memberikan rezeki kepadaku tanpa daya serta kekuatan dariku.",notes:null,fawaid:"Rasulullah \ufdfa bersabda jika seseorang membaca doa tersebut maka diampuni dosanya yang telah lalu.",source:"Shahih at-Tirmidzi"},{title:"Doa Masuk Masjid",arabic:"\u0627\u064e\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0627\u0641\u0652\u062a\u064e\u062d\u0652 \u0644\u0650\u064a\u0652 \u0623\u064e\u0628\u0652\u0648\u064e\u0627\u0628\u064e \u0631\u064e\u062d\u0652\u0645\u064e\u062a\u0650\u0643\u064e",latin:"All\u0101hummafta\u1e25 l\u012b abw\u0101ba ra\u1e25matik",translation:"Ya Allah, bukalah pintu-pintu rahmat-Mu untukku.",notes:null,fawaid:"Masjid adalah rumah Allah, hendaknya seorang hamba mengagungkannya dan berharap rahmat Allah di dalamnya.",source:"HR. Muslim"},{title:"Doa Keluar Masjid",arabic:"\u0627\u064e\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u0650\u064a\u0652 \u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064e \u0645\u0650\u0646\u0652 \u0641\u064e\u0636\u0652\u0644\u0650\u0643\u064e",latin:"All\u0101humma inn\u012b as'aluka min fa\u1e0dlik",translation:"Ya Allah, sesungguhnya aku memohon karunia-Mu.",notes:null,fawaid:"Bumi Allah sangatlah luas, ada banyak jalan mencari rezeki. Hendalkah seorang hamba meminta karunia kepada Allah agar dimudahkan untuk mendapat rezeki yang telah Allah bagikan kepada seluruh hamba-Nya.",source:"HR. Muslim No. 713"},{title:"Doa Sebelum Berwudhu",arabic:"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650",latin:"Bismill\u0101h",translation:"Dengan nama Allah (aku mulai berwudhu).",notes:null,fawaid:"Disyariatkan memulai setiap perkara yang penting dengan mengucapkan bismillah dalam hal ibadah ataupun lainnya.",source:"HR. at-Tirmidzi dan al-Baihaqi"},{title:"Doa Sesudah Berwudhu",arabic:"\u0623\u0634\u0652\u0647\u064e\u062f\u064f \u0623\u0646\u0652 \u0644\u0627 \u0625\u0644\u0647 \u0625\u0650\u0644\u0627\u064e\u0651 \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0648\u064e\u062d\u0652\u062f\u064e\u0647\u064f \u0644\u0627 \u0634\u064e\u0631\u0650\u064a\u0643 \u0644\u064e\u0647\u064f \u060c \u0648\u0623\u0634\u0652\u0647\u064e\u062f\u064f \u0623\u0646\u064e\u0651 \u0645\u064f\u062d\u064e\u0645\u064e\u0651\u062f\u0627\u064b \u0639\u064e\u0628\u0652\u062f\u064f\u0647\u064f \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0647\u064f \u060c \u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0627\u062c\u0652\u0639\u064e\u0644\u0652\u0646\u0650\u064a \u0645\u0650\u0646\u064e \u0627\u0644\u062a\u064e\u0648\u064e\u0651\u0627\u0628\u0650\u064a\u0646\u064e \u060c \u0648\u0627\u062c\u0652\u0639\u064e\u0644\u0652\u0646\u064a \u0645\u0650\u0646\u064e \u0627\u0644\u0645\u064f\u062a\u064e\u0637\u064e\u0647\u0650\u0651\u0631\u0650\u064a\u0646\u064e \u060c \u0633\u064f\u0628\u0652\u062d\u0627\u0646\u064e\u0643\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0648\u0628\u0650\u062d\u064e\u0645\u0652\u062f\u0650\u0643\u064e \u060c \u0623\u0634\u0652\u0647\u064e\u062f\u064f \u0623\u0646\u0652 \u0644\u0627 \u0625\u0644\u0647\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0623\u0646\u0652\u062a\u064e \u060c \u0623\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u064f\u0643\u064e \u0648\u0623\u062a\u064f\u0648\u0628\u064f \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e",latin:"Asyhadu an l\u0101 il\u0101ha ill\u0101ll\u0101h wa\u1e25dahu l\u0101 syar\u012bka lahu, wa asyhadu anna mu\u1e25ammadan 'abduhu wa ras\u016bluh. All\u0101hummaj'aln\u012b minat taww\u0101b\u012bna waj'aln\u012b minal muta\u1e6dahhir\u012bna. Sub\u1e25\u0101nakall\u0101humma wa bi\u1e25amdika asyhadu an l\u0101 il\u0101ha ill\u0101 anta astaghfiruka wa at\u016bbu ilaik",translation:"Aku bersaksi bahwa tidak ada tuhan selain Allah semata yang tidak ada sekutu bagi-Nya dan aku pun bersaksi bahwa Muhammad adalah hamba sekaligus Rasul utusan-Nya. Ya Allah, jadikanlah aku termasuk orang-orang yang bertaubat dan jadikanlah aku termasuk orang-orang yang bersuci. Maha Suci Engkau wahai tuhan kami dan segala puji bagi-Mu. Aku bersaksi bahwa tiada tuhan selain Engkau. Aku memohon ampunan dan bertaubat kepada-Mu.",notes:null,fawaid:"Barang siapa yang mengucapkan doa tersebut maka akan dibukakan baginya delapan pintu Surga. Dia memasukinya dari arah mana saja yang ia kehendaki.",source:"HR. Muslim, at-Tirmidzi dan an-Nasa'i"},{title:"Doa Buka Puasa",arabic:"\u0630\u064e\u0647\u064e\u0628\u064e \u0627\u0644\u0638\u0651\u064e\u0645\u064e\u0623\u064f \u0648\u0627\u0628\u0652\u062a\u064e\u0644\u0651\u064e\u062a\u0650 \u0627\u0644\u0652\u0639\u064f\u0631\u064f\u0648\u0642\u064f \u0648\u062b\u064e\u0628\u064e\u062a\u064e \u0627\u0652\u0644\u0623\u064e\u062c\u0652\u0631\u064f \u0625\u0650\u0646\u0652 \u0634\u064e\u0627\u0621\u064e\u0627\u0644\u0644\u0647\u064f",latin:"\u017bahaba\u1e93\u1e93ama'u wabtallatil 'ur\u016bq wa \u1e61abatal ajru in sy\u0101'a All\u0101h",translation:"Rasa haus telah hilang, urat-urat telah basah, dan pahala telah ditetapkan insya Allah.",notes:null,fawaid:"Sangat dianjurkan bagi orang yang berpuasa untuk memperbanyak doa sebelum dan sesudah berbuka, karena doa orang yang berpuasa adalah salah satu 3 doa yang tak tertolak.",source:"HR. Abu Daud, As-Sunan Al-Kubra Lil Baihaqi, Juz 4, Hal. 239, al-Hakim dalam Mustadrak 'alas Shahihain No. 1484"},{title:"Doa Masuk Rumah #1",arabic:"\u0627\u064e\u0644\u0633\u064e\u0651\u0644\u064e\u0627\u0645\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652",latin:"Assal\u0101mu 'alaykum",translation:"Semoga keselamatan terlimpah untukmu.",notes:null,fawaid:"Salam adalah doa pengharapan, pengharapan agar Anda selamat dari segala macam duka dan derita, serta diliputi rahmat dan keberkahan.",source:"HR. at-Tirmidzi"},{title:"Doa Masuk Rumah #2",arabic:"\u0627\u064e\u0644\u0633\u0651\u064e\u0644\u064e\u0627\u0645\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064f \u0627\u0644\u0644\u0647\u0650 \u0648\u064e\u0628\u064e\u0631\u064e\u0643\u064e\u0627 \u062a\u064f\u0647\u064f",latin:"Assal\u0101mu 'alaykum warahmatull\u0101hi wabarak\u0101tuh",translation:"Semoga keselamatan, rahmat dan keberkahan terlimpah untukmu.",notes:null,fawaid:"Salam adalah doa pengharapan, pengharapan agar Anda selamat dari segala macam duka dan derita, serta diliputi rahmat dan keberkahan.",source:"HR. at-Tirmidzi"},{title:"Doa Keluar Rumah",arabic:"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u0652\u062a\u064f \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650\u060c \u0644\u064e\u0627 \u062d\u064e\u0648\u0652\u0644\u064e \u0648\u064e\u0644\u064e\u0627 \u0642\u064f\u0648\u0651\u064e\u0629\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650",latin:"Bismill\u0101h, tawakkaltu 'alall\u0101h, l\u0101 haula wa l\u0101 quwwata ill\u0101 bill\u0101h",translation:"Dengan nama Allah, aku bertawakkal kepada Allah, tiada daya dan kekuatan kecuali dengan pertolongan Allah.",notes:null,fawaid:"Barang siapa yang membaca doa tersebut maka dikatakan kepadanya: \"Engkau akan diberi petunjuk, dicukupkan dan dijaga\". Syaitan pun akan menyingkir darinya. Syaitan yang lain akan mengatakan: \"Bagaimana mungkin engkau bisa mengganggu seseorang yang telah mendapatkan petunjuk, kecukupan dan penjagaan?!\"",source:"HR. Abu Dawud dan at-Tirmidzi"},{title:"Doa Agar Tidak Menyebabkan Keburukan atau Terkena Keburukan Di luar Rumah",arabic:"\u0627\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u0650\u0649 \u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0643\u064e \u0623\u064e\u0646\u0652 \u0623\u064e\u0636\u0650\u0644\u0651\u064e \u0623\u064e\u0648\u0652 \u0623\u064f\u0636\u064e\u0644\u0651\u064e \u0623\u064e\u0648\u0652 \u0623\u064e\u0632\u0650\u0644\u0651\u064e \u0623\u064e\u0648\u0652 \u0623\u064f\u0632\u064e\u0644\u0651\u064e \u0623\u064e\u0648\u0652 \u0623\u064e\u0638\u0652\u0644\u0650\u0645\u064e \u0623\u064e\u0648\u0652 \u0623\u064f\u0638\u0652\u0644\u064e\u0645\u064e \u0623\u064e\u0648\u0652 \u0623\u064e\u062c\u0652\u0647\u064e\u0644\u064e \u0623\u064e\u0648\u0652 \u064a\u064f\u062c\u0652\u0647\u064e\u0644\u064e \u0639\u064e\u0644\u064e\u0649\u0651\u064e",latin:"All\u0101humma inn\u012b a'\u016b\u017cu bika an adhilla au udholla, au azilla au azulla, au azhlima au uzhlama, au ajhala au yujhala 'alayya",translation:"Ya Allah, aku berlindung kepada-Mu, jangan sampai aku sesat atau disesatkan (setan atau orang yang berwatak setan), berbuat kesalahan atau disalahi, menganiaya atau dianiaya (orang), dan berbuat bodoh atau dibodohi.",notes:null,fawaid:"Ketika seseorang keluar rumah maka ia akan banyak menemui segala macam hal baik maupun buruk, terutama keburukan yang diperbuat oleh dirinya sendiri. Oleh karena itu diperintahkan untuk berlindung dari diri sendiri dan dari orang lain.",source:"HR. Abu Dawud, at-Tirmidzi, Ibnu Majah dan an-Nasa'i"},{title:"Doa Safar",arabic:"\u0627\u0644\u0644\u0647 \u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064f\u060c\u0627\u0644\u0644\u0647 \u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064f\u060c\u0627\u0644\u0644\u0647 \u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064f\u060c\u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0627\u0644\u064e\u0651\u0630\u0650\u0649 \u0633\u064e\u062e\u064e\u0651\u0631\u064e \u0644\u064e\u0646\u064e\u0627 \u0647\u064e\u0630\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u064e\u0651\u0627 \u0644\u064e\u0647\u064f \u0645\u064f\u0642\u0652\u0631\u0650\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0625\u0650\u0646\u064e\u0651\u0627 \u0625\u0650\u0644\u064e\u0649 \u0631\u064e\u0628\u0650\u0651\u0646\u064e\u0627 \u0644\u064e\u0645\u064f\u0646\u0652\u0642\u064e\u0644\u0650\u0628\u064f\u0648\u0646\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0625\u0650\u0646\u064e\u0651\u0627 \u0646\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064e \u0641\u0650\u0649 \u0633\u064e\u0641\u064e\u0631\u0650\u0646\u064e\u0627 \u0647\u064e\u0630\u064e\u0627 \u0627\u0644\u0652\u0628\u0650\u0631\u064e\u0651 \u0648\u064e\u0627\u0644\u062a\u064e\u0651\u0642\u0652\u0648\u064e\u0649 \u0648\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0639\u064e\u0645\u064e\u0644\u0650 \u0645\u064e\u0627 \u062a\u064e\u0631\u0652\u0636\u064e\u0649 \u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0647\u064e\u0648\u0650\u0651\u0646\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0633\u064e\u0641\u064e\u0631\u064e\u0646\u064e\u0627 \u0647\u064e\u0630\u064e\u0627 \u0648\u064e\u0627\u0637\u0652\u0648\u0650 \u0639\u064e\u0646\u064e\u0651\u0627 \u0628\u064f\u0639\u0652\u062f\u064e\u0647\u064f \u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0623\u064e\u0646\u0652\u062a\u064e \u0627\u0644\u0635\u064e\u0651\u0627\u062d\u0650\u0628\u064f \u0641\u0650\u0649 \u0627\u0644\u0633\u064e\u0651\u0641\u064e\u0631\u0650 \u0648\u064e\u0627\u0644\u0652\u062e\u064e\u0644\u0650\u064a\u0641\u064e\u0629\u064f \u0641\u0650\u0649 \u0627\u0644\u0623\u064e\u0647\u0652\u0644\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0625\u0650\u0646\u0650\u0651\u0649 \u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0648\u064e\u0639\u0652\u062b\u064e\u0627\u0621\u0650 \u0627\u0644\u0633\u064e\u0651\u0641\u064e\u0631\u0650 \u0648\u064e\u0643\u064e\u0622\u0628\u064e\u0629\u0650 \u0627\u0644\u0652\u0645\u064e\u0646\u0652\u0638\u064e\u0631\u0650 \u0648\u064e\u0633\u064f\u0648\u0621\u0650 \u0627\u0644\u0652\u0645\u064f\u0646\u0652\u0642\u064e\u0644\u064e\u0628\u0650 \u0641\u0650\u0649 \u0627\u0644\u0652\u0645\u064e\u0627\u0644\u0650 \u0648\u064e\u0627\u0644\u0623\u064e\u0647\u0652\u0644\u0650",latin:"All\u0101hu akbar, All\u0101hu akbar, All\u0101hu akbar. Sub\u1e25\u0101nalla\u017c\u012b sakhkhara lan\u0101 h\u0101\u017c\u0101 wa m\u0101 kunn\u0101 lah\u016b muqrin\u012bn wa inn\u0101 il\u0101 rabbina lamunqalib\u016bn. All\u0101humma inn\u0101 nas'aluka f\u012b safarina ha\u017c\u0101l birra wat taqw\u0101 wa minal 'amali m\u0101 tar\u1e0d\u0101. All\u0101humma hawwin 'alain\u0101 safaran\u0101 h\u0101\u017c\u0101 wa\u1e6dwi 'ann\u0101 bu'dah. All\u0101humma anta \u1e63\u0101\u1e25ibu fis safar wal khal\u012bfatu fil ahli. All\u0101humma inn\u012b a'\u016b\u017cubika min wa'\u1e61\u0101 issafari wa k\u0101batil man\u017cari wa s\u016b'il munqalabi fil m\u0101li wal ahli",translation:"Allah Maha Besar, Allah Maha Besar, Allah Maha Besar. Maha Suci Allah yang telah menundukkan untuk kami kendaraan ini, padahal kami sebelumnya tidak mempunyai kemampuan untuk melakukannya, dan sesungguhnya hanya kepada Rabb kami, kami akan kembali. Ya Allah, sesungguhnya kami memohon kepada-Mu kebaikan, ketakwaan, dan amal yang Engkau ridhai dalam perjalanan kami ini. Ya Allah, mudahkanlah perjalanan kami ini, dekatkanlah bagi kami jarak yang jauh. Ya Allah, Engkau adalah rekan dalam perjalanan dan pengganti di tengah keluarga. Ya Allah, sesungguhnya aku berlindung kepada-Mu dari kesukaran perjalanan, tempat kembali yang menyedihkan, dan pemandangan yang buruk pada harta, keluarga, dan anak.",notes:null,fawaid:"Didalam doa ini ada 2 bagian. Pertama adalah pujian kepada Allah ta'ala dan ketundukan diri hamba, yang kedua adalah permohonan kepada Allah untuk segala kemudahan baik dalam safar maupun urusan hal-hal yang seorang hamba tinggalkan di rumah.",source:"HR. Muslim"},{title:"Doa Orang Mukim Kepada Orang yang Hendak Bersafar",arabic:"\u0623\u064e\u0633\u0652\u062a\u064e\u0648\u0652\u062f\u0650\u0639\u064f \u0627\u0644\u0644\u064e\u0651\u0647\u064e \u062f\u0650\u064a\u0646\u064e\u0643\u064e \u0648\u064e\u0623\u064e\u0645\u064e\u0627\u0646\u064e\u062a\u064e\u0643\u064e \u0648\u064e\u062e\u064e\u0648\u064e\u0627\u062a\u0650\u064a\u0645\u064e \u0639\u064e\u0645\u064e\u0644\u0650\u0643\u064e",latin:"Astawdi'ullaha d\u012bnaka, wa am\u0101nataka, wa khaw\u0101t\u012bma a'm\u0101lik",translation:"Aku menetipkan agamamu, amanahmu, dan amal terakhir kepada Allah.",notes:null,fawaid:"Tiga prioritas seorang hamba yang harus dijaga dimanapun, agama, amanah dan amal, sebab seseorang akan dimatikan sesuai dengan amalnya.",source:"HR. Abu Dawud: 2601"},{title:"Doa Bekal Takwa dari Orang Mukim Kepada yang Hendak Bersafar",arabic:"\u0632\u064e\u0648\u064e\u0651\u062f\u064e\u0643\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0627\u0644\u062a\u064e\u0651\u0642\u0652\u0648\u064e\u0649 \u0648\u064e\u063a\u064e\u0641\u064e\u0631\u064e \u0630\u064e\u0646\u0652\u0628\u064e\u0643\u064e  \u0648\u064e\u064a\u064e\u0633\u064e\u0651\u0631\u064e \u0644\u064e\u0643\u064e \u0627\u0644\u0652\u062e\u064e\u064a\u0652\u0631\u064e \u062d\u064e\u064a\u0652\u062b\u064f\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064e",latin:"Zawwadakall\u0101hut taqw\u0101 wa ghafara \u017canbaka wa yassara lakal khaira \u1e25ay\u1e61um\u0101 kunta",translation:"Semoga Allah membekalimu ketakwaan, mengampuni dosamu, dan memudahkan kebaikan untukmu dimanapun kamu berada.",notes:null,fawaid:"Taqwa adalah sebaik-baik bekal yang harus disiapkan seorang hamba menuju akhirat, sebab tidak ada keselamatan kecuali dengan berbekal dengan ketaqwaan.",source:"HR. at-Tirmidzi"},{title:"Doa Memakai Pakaian Baru",arabic:"\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0644\u064e\u0643\u064e \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0623\u064e\u0646\u0652\u062a\u064e \u0643\u064e\u0633\u064e\u0648\u0652\u062a\u064e\u0646\u0650\u064a\u0647\u0650 \u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064e \u0645\u0650\u0646\u0652 \u062e\u064e\u064a\u0652\u0631\u0650\u0647\u0650 \u0648\u064e\u062e\u064e\u064a\u0652\u0631\u0650 \u0645\u064e\u0627 \u0635\u064f\u0646\u0650\u0639\u064e \u0644\u064e\u0647\u064f \u0648\u064e\u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0634\u064e\u0631\u0650\u0651\u0647\u0650 \u0648\u064e\u0634\u064e\u0631\u0650\u0651 \u0645\u064e\u0627 \u0635\u064f\u0646\u0650\u0639\u064e \u0644\u064e\u0647\u064f",latin:"All\u0101humma lakal \u1e25amdu anta kasautan\u012bh, as'aluka min khairih\u012b wa khairi m\u0101 \u1e63uni'a lah, wa a'\u016bdzu bika min syarrih\u012b wa syarri m\u0101 \u1e63uni'a lah",translation:"Ya Allah, hanya milik-Mu lah segala pujian. Engkaulah yang memberi pakaian ini kepadaku. Aku memohon kepada-Mu agar memperoleh kebaikan dari pakaian ini dan kebaikan yang ia diciptakan karenanya. Aku berlindung kepada-Mu dari kejahatannya dan kejahatan yang diciptakan karenanya.",notes:null,fawaid:"Dengan membaca doa ini, seseorang memohon agar baju yang telah dibeli dapat memberikan kebaikan sekaligus menjadi pelindung bagi berbagai keburukan.",source:"HR. Ahmad, Abu Dawud, at-Tirmidzi dan Al-Hakim"},{title:"Doa Memakai Pakaian",arabic:"\u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u064e\u0651\u0647\u0650 \u0627\u0644\u064e\u0651\u0630\u0650\u0649 \u0643\u064e\u0633\u064e\u0627\u0646\u0650\u0649 \u0647\u064e\u0630\u064e\u0627 \u0627\u0644\u062b\u064e\u0651\u0648\u0652\u0628\u064e \u0648\u064e\u0631\u064e\u0632\u064e\u0642\u064e\u0646\u0650\u064a\u0647\u0650 \u0645\u0650\u0646\u0652 \u063a\u064e\u064a\u0652\u0631\u0650 \u062d\u064e\u0648\u0652\u0644\u064d \u0645\u0650\u0646\u0650\u0651\u0649 \u0648\u064e\u0644\u0627\u064e \u0642\u064f\u0648\u064e\u0651\u0629\u064d",latin:"Alhamdulill\u0101hilla\u017c\u012b kas\u0101n\u012b h\u0101\u017c\u0101 wa razaqan\u012bhi min ghayri \u1e25awlin minn\u012b wa l\u0101 quwwatin",translation:"Segala puji bagi Allah yang memberi pakaian ini kepadaku sebagai rezeki dari-Nya tanpa daya dan kekuatan dariku.",notes:null,fawaid:"Keutamaan membaca doa ini, akan diampuni dosa yang telah lalu, InsyaAllah.",source:"HR. seluruh penyusun kitab Sunan, kecuali Nasa'i"},{title:"Doa Menaiki Kendaraan",arabic:"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u0650\u060c \u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u0650\u060c \u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u0650\u060c \u0627\u0644\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0644\u0650\u0647\u060c \u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0627\u0644\u064e\u0651\u0630\u0650\u0649 \u0633\u064e\u062e\u064e\u0651\u0631\u064e \u0644\u064e\u0646\u064e\u0627 \u0647\u064e\u0630\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u064e\u0651\u0627 \u0644\u064e\u0647\u064f \u0645\u064f\u0642\u0652\u0631\u0650\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0625\u0650\u0646\u064e\u0651\u0627 \u0625\u0650\u0644\u064e\u0649 \u0631\u064e\u0628\u0650\u0651\u0646\u064e\u0627 \u0644\u064e\u0645\u064f\u0646\u0652\u0642\u064e\u0644\u0650\u0628\u064f\u0648\u0646\u064e\u060c \u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e\u0643\u064e \u0625\u0650\u0646\u0650\u0651\u0649 \u0642\u064e\u062f\u0652 \u0638\u064e\u0644\u064e\u0645\u0652\u062a\u064f \u0646\u064e\u0641\u0652\u0633\u0650\u0649 \u0641\u064e\u0627\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u0650\u0649 \u0641\u064e\u0625\u0650\u0646\u064e\u0651\u0647\u064f \u0644\u0627\u064e \u064a\u064e\u063a\u0652\u0641\u0650\u0631\u064f \u0627\u0644\u0630\u064f\u0651\u0646\u064f\u0648\u0628\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0623\u064e\u0646\u0652\u062a\u064e",latin:"Bismill\u0101h, bismill\u0101h, bismill\u0101h. Al\u1e25amdulill\u0101h. Sub\u1e25\u0101nalla\u017c\u012b sakhkhara lan\u0101 h\u0101\u017c\u0101 wa m\u0101 kunn\u0101 lahu muqrin\u012bn wa inn\u0101 il\u0101 rabbin\u0101 lamunqalib\u016bn. Sub\u1e25\u0101naka inn\u012b qad \u1e93alamtu nafs\u012b faghfir l\u012b fa innahu l\u0101 yaghfiru a\u1e93 \u1e93un\u016bba ill\u0101 anta",translation:"Dengan menyebut nama Allah (3x). Segala puji bagi Allah. Maha Suci Allah yang telah menundukkan semua ini bagi kami padahal kami sebelumnya tidak mampu menguasainya, dan sesungguhnya kami akan kembali kepada Rabb kami. Maha Suci Engkau, sesungguhnya aku telah mendzalimi diriku sendiri maka ampunilah aku, karena tidak ada yang mengampuni dosa-dosa selain Engkau.",notes:null,fawaid:"Dengan membaca doa naik kendaraan, perjalanan kita akan senantiasa mendapat perlindungan Allah ta'ala. Selain itu juga akan mendapat pahala, pertolongan dan hati yang lebih tenang.",source:"HR. Abu Dawud dan at-Tirmidzi"},{title:"Doa Ketika Turun Hujan",arabic:"\u0627\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0635\u064e\u064a\u0651\u0650\u0628\u064b\u0627 \u0646\u064e\u0627\u0641\u0650\u0639\u064b\u0627",latin:"Allahumma shayyiban n\u0101fi'\u0101",translation:"Ya Allah turunkanlah pada kami hujan yang bermanfaat.",notes:null,fawaid:"Ajuran untuk berdo'a ketika turun hujan agar kebaikan dan keberkahan semakin bertambah, begitu pula semakin banyak kemanfaatan.",source:"HR. al-Bukhari No. 1032"},{title:"Doa Ketika Hujan Lebat",arabic:"\u0627\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u062d\u064e\u0648\u064e\u0627\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0648\u064e\u0644\u0627\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u060c \u0627\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0622\u0643\u064e\u0627\u0645\u0650 \u0648\u064e\u0627\u0644\u0638\u0651\u0650\u0631\u064e\u0627\u0628\u0650 \u0648\u064e\u0628\u064f\u0637\u064f\u0648\u0646\u0650 \u0627\u0644\u0623\u064e\u0648\u0652\u062f\u0650\u064a\u064e\u0629\u0650 \u0648\u064e\u0645\u064e\u0646\u064e\u0627\u0628\u0650\u062a\u0650 \u0627\u0644\u0634\u0651\u064e\u062c\u064e\u0631\u0650",latin:"Allahumma h\u0101walaina wa l\u0101 'alaina. Allahumma 'alal \u0101kami wal jib\u0101li, wazh zhiroobi, wa buthunil awdiyati, wa man\u0101bitisy syajari",translation:"Ya Allah, turunkanlah hujan di sekitar kami, bukan untuk merusak kami. Ya Allah, turunkanlah hujan ke dataran tinggi, gunung-gunung, bukit-bukit, perut lembah dan tempat tumbuhnya pepohonan.",notes:null,fawaid:"Bahwa do'a di atas dibaca ketika hujan semakin lebat atau khawatir hujan akan membawa dampak bahaya.",source:"HR. al-Bukhari No. 1014"},{title:"Doa Setelah Turun Hujan",arabic:"\u0645\u064f\u0637\u0650\u0631\u0652\u0646\u0627 \u0628\u0641\u064e\u0636\u0652\u0644\u0650 \u0627\u0644\u0644\u0647\u0650 \u0648\u0631\u064e\u062d\u0652\u0645\u064e\u062a\u0650\u0647\u0650",latin:"Muthirna bi fadhlillahi wa rohmatih",translation:"Kita diberi hujan karena karunia dan rahmat Allah.",notes:null,fawaid:"Dengan membaca doa tersebut maka ia telah mengimani bahwasanya hujan turun atas kehendak Allah (keutamaan Allah), bukan dengan bintang-bintang sehingga mereka menjadi kufur kepada Allah.",source:"HR. al-Bukhari No. 846 dan Muslim No. 71"},{title:"Doa Ketika Angin Kencang",arabic:"\u0627\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064e \u062e\u064e\u064a\u0652\u0631\u064e\u0647\u064e\u0627\u060c \u0648\u064e\u0623\u064e\u0639\u064f\u0648\u0652\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0634\u064e\u0631\u0651\u0650\u0647\u064e\u0627",latin:"All\u0101humma inn\u012b as'aluka khoiroh\u0101 wa a'\u016b\u017cubika min syarrih\u0101",translation:"Ya Allah, sesungguhnya aku memohon kepada-Mu kebaikan angin ini dan aku berlindung kepada-Mu dari keburukannya.",notes:null,fawaid:"Diantara tanda kuasa Allah adalah angin yang kencang yang bisa mendatangkan nikmat dan adzab, yakni kebaikan dan keburukan. Maka seyogyanya seorang hamba terus meminta kebaikan dan berlindung dari segala marabahaya.",source:"HR. Abu Dawud dan Ibnu Majah"},{title:"Sayyid al-Istighfar",arabic:"\u0627\u064e\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0623\u064e\u0646\u0652\u062a\u064e \u0631\u064e\u0628\u0651\u0650\u064a\u0652 \u060c \u0644\u064e\u0627 \u0625\u0650\u0644\u0670\u0640\u0647\u064e \u0625\u0650\u0644\u0627\u0651\u064e \u0623\u064e\u0646\u0652\u062a\u064e \u062e\u064e\u0644\u064e\u0642\u0652\u062a\u064e\u0646\u0650\u064a\u0652 \u0648\u064e\u0623\u064e\u0646\u064e\u0627 \u0639\u064e\u0628\u0652\u062f\u064f\u0643\u064e \u060c \u0648\u064e\u0623\u064e\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0639\u064e\u0647\u0652\u062f\u0650\u0643\u064e \u0648\u064e\u0648\u064e\u0639\u0652\u062f\u0650\u0643\u064e \u0645\u064e\u0627 \u0627\u0633\u0652\u062a\u064e\u0637\u064e\u0639\u0652\u062a\u064f \u060c \u0623\u064e\u0639\u064f\u0648\u0652\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0634\u064e\u0631\u0651\u0650 \u0645\u064e\u0627 \u0635\u064e\u0646\u064e\u0639\u0652\u062a\u064f \u060c \u0623\u064e\u0628\u064f\u0648\u0652\u0621\u064f \u0644\u064e\u0643\u064e \u0628\u0650\u0646\u0650\u0639\u0652\u0645\u062a\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u064a\u0651\u064e \u060c \u0648\u064e\u0623\u064e\u0628\u064f\u0648\u0652\u0621\u064f \u0628\u0650\u0630\u064e\u0646\u0652\u0628\u0650\u064a\u0652 \u0641\u064e\u0627\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u0650\u064a\u0652 \u060c \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064e\u063a\u0652\u0641\u0650\u0631\u064f \u0627\u0644\u0630\u0651\u064f\u0646\u064f\u0648\u0628\u064e \u0625\u0650\u0644\u0627\u0651\u064e \u0623\u064e\u0646\u0652\u062a\u064e",latin:"Allahumma anta rabb\u012b l\u0101 il\u0101ha ill\u0101 anta khalaqtan\u012b wa anna 'abduka wa an\u0101 'al\u0101 'ahdika wa wa'dika mastatha'tu a'\u016b\u017cu bika min syarri m\u0101 shana'tu ab\u016b u laka bini' matika 'alayya wa ab\u016b u bi\u017canb\u012b faghfir l\u012b fa innahu l\u0101 yaghfiru\u017c \u017cun\u016bba illa anta",translation:"Ya Allah, Engkau adalah Rabb-ku, tidak ada Ilah (yang berhak diibadahi dengan benar) kecuali Engkau, Engkau-lah yang menciptakanku. Aku adalah hamba-Mu. Aku akan setia pada perjanjianku dengan-Mu semampuku. Aku berlindung kepada-Mu dari kejelekan (apa) yang kuperbuat. Aku mengakui nikmat-Mu (yang diberikan) kepadaku dan aku mengakui dosaku, oleh karena itu, ampunilah aku. Sesungguhnya tidak ada yang dapat mengampuni dosa kecuali Engkau.",notes:null,fawaid:"Barang siapa yang membacanya dengan yakin ketika petang hari, kemudian dia meninggal, maka ia akan masuk surga, demikian juga jika (dibaca) pada pagi hari.",source:"HR. al-Bukhari No. 6306, 6323, Ahmad IV/122-125, an-Nasa'i VIII/279-280"},{title:"Doa Meminta Kemudahan Dalam Segala Urusan",arabic:"\u0627\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0644\u0627\u064e \u0633\u064e\u0647\u0652\u0644\u064e \u0625\u0650\u0644\u0627\u0651\u064e \u0645\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u0652\u062a\u064e\u0647\u064f \u0633\u064e\u0647\u0652\u0644\u0627\u064b \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064e \u062a\u064e\u062c\u0652\u0639\u064e\u0644\u064f \u0627\u0644\u062d\u064e\u0632\u0652\u0646\u064e \u0625\u0650\u0630\u064e\u0627 \u0634\u0650\u0626\u0652\u062a\u064e \u0633\u064e\u0647\u0652\u0644\u0627\u064b",latin:"Allahumma l\u0101 sahla illa m\u0101 ja'altahu sahl\u0101, wa anta taj'alul hazna i\u017ca syi'ta sahl\u0101",translation:"Ya Allah, tidak ada kemudahan kecuali Engkau buat mudah. Dan engkau menjadikan kesedihan (kesulitan), jika Engkau kehendaki pasti akan menjadi mudah.",notes:null,fawaid:"Kemudahan hanya datang dari Allah. Sesuatu yang sulit sekalipun bisa menjadi mudah jika Allah kehendaki.",source:"HR. Ibnu Hibban"},{title:"Doa Tertimpa Musibah",arabic:"\u0625\u0650\u0646\u064e\u0651\u0627 \u0644\u0650\u0644\u064e\u0651\u0647\u0650 \u0648\u064e\u0625\u0650\u0646\u064e\u0651\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0631\u064e\u0627\u062c\u0650\u0639\u064f\u0648\u0646\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0623\u0652\u062c\u064f\u0631\u0652\u0646\u0650\u0649 \u0641\u0650\u0649 \u0645\u064f\u0635\u0650\u064a\u0628\u064e\u062a\u0650\u0649 \u0648\u064e\u0623\u064e\u062e\u0652\u0644\u0650\u0641\u0652 \u0644\u0650\u0649 \u062e\u064e\u064a\u0652\u0631\u064b\u0627 \u0645\u0650\u0646\u0652\u0647\u064e\u0627",latin:"Inna lillahi wa inna ilaihi rooj'un. Allahumma'jurn\u012b f\u012b mushibat\u012b wa akhlif l\u012b khoiron minh\u0101",translation:"Segala sesuatu adalah milik Allah dan akan kembali pada-Nya. Ya Allah, berilah ganjaran terhadap musibah yang menimpaku dan berilah ganti dengan yang lebih baik.",notes:null,fawaid:"Hendaklah seorang hamba membaca doa diatas ketika tertimpa musibah dengan rasa yakin dan harap, InsyaAllah dengan ini akan mendapatkan ganti yang lebih baik.",source:"HR. Muslim"},{title:"Doa Ketika Terlilit Hutang",arabic:"\u0627\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0627\u0643\u0652\u0641\u0650\u0646\u0650\u0649 \u0628\u0650\u062d\u064e\u0644\u0627\u064e\u0644\u0650\u0643\u064e \u0639\u064e\u0646\u0652 \u062d\u064e\u0631\u064e\u0627\u0645\u0650\u0643\u064e \u0648\u064e\u0623\u064e\u063a\u0652\u0646\u0650\u0646\u0650\u0649 \u0628\u0650\u0641\u064e\u0636\u0652\u0644\u0650\u0643\u064e \u0639\u064e\u0645\u0651\u064e\u0646\u0652 \u0633\u0650\u0648\u064e\u0627\u0643\u064e",latin:"Allahumak fin\u012b bi hal\u0101lika 'an haroomik, wa agh niniy bi fadhlika 'amman siw\u0101k",translation:"Ya Allah cukupkanlah aku dengan yang halal dan jauhkanlah aku dari yang haram, dan cukupkanlah aku dengan karunia-Mu dari bergantung pada selain-Mu.",notes:null,fawaid:"Rezeki halal walaupun sedikit lebih baik dari harta haram yang jumlahnya melimpah.",source:"HR. at-Tirmidzi No. 2563"},{title:"Doa Memohon Perlindungan Dari Sifat Malas, Kesedihan, dan Lilitan Hutang",arabic:"\u0627\u064e\u0644\u0644\u0651\u0670\u0647\u064f\u0645\u064e\u0651 \u0625\u0650\u0646\u0650\u0651\u0649 \u0623\u064e\u0639\u064f\u0648\u0652\u0630\u064f\u0628\u0650\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0647\u064e\u0645\u0650\u0651 \u0648\u064e\u0627\u0644\u0652\u062d\u064e\u0632\u0652\u0646\u0650 \u0648\u064e\u0623\u064e\u0639\u064f\u0648\u0652\u0630\u064f\u0628\u0650\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0639\u064e\u062c\u0652\u0632\u0650 \u0648\u064e\u0627\u0644\u0652\u0643\u064e\u0633\u064e\u0644\u0650 \u0648\u064e\u0623\u064e\u0639\u064f\u0648\u0652\u0630\u064f\u0628\u0650\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062c\u064f\u0628\u0652\u0646\u0650 \u0648\u064e\u0627\u0644\u0652\u0628\u064f\u062e\u0652\u0644\u0650 \u0648\u064e\u0623\u064e\u0639\u064f\u0648\u0652\u0630\u064f\u0628\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u063a\u064e\u0644\u064e\u0628\u064e\u062a\u0650 \u0627\u0644\u062f\u064e\u0651\u064a\u0652\u0646\u0650 \u0648\u064e\u0642\u064e\u0647\u0652\u0631\u0650 \u0627\u0644\u0631\u062c\u0627\u0644",latin:"Allahumma inn\u012b a'\u016b\u017cu bika minal hammi wal hazan. Wa a'u\u017cu bika minal 'ajzi wal kasal. Wa a'\u016b\u017cu bika minal jubni wal bukhl. Wa a'\u016b\u017cu bika min ghalabatiddayni wa qahrirrij\u0101l",translation:"Ya Allah, aku berlindung kepada-Mu dari kebingungan dan kesedihan, aku berlindung kepada-Mu dari kelemahan dan kemalasan, aku berlindung kepada-Mu dari ketakutan dan kekikiran, aku berlindung kepada-Mu dari lilitan hutang dan tekanan orang-orang.",notes:null,fawaid:"Abu Umamah lalu menuturkan: Setelah aku mengamalkan doa itu, Allah benar-benar menghilangkan kebingunganku dan memberi kemampuan melunasi hutang.",source:"HR. Abu Dawud No. 1555"},{title:"Doa Setelah Bersin",arabic:"\u0627\u0644\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0644\u0647\u0650",latin:"Al\u1e25amdulill\u0101h",translation:"Segala puji bagi Allah.",notes:null,fawaid:"Sesungguhnya Allah mencintai bersin, sebab bersin menggerakan seseorang untuk beribadah. Dan anjuran membalas pujian atas Allah orang yang memuji Allah, begitu juga sebaliknya.",source:"HR. al-Bukhari"},{title:"Doa Saat Mendengar Orang Bersin",arabic:"\u064a\u064e\u0631\u0652\u062d\u064e\u0645\u064f\u0643\u064e \u0627\u0644\u0644\u0647\u064f",latin:"Yarhamukallah",translation:"Semoga Allah merahmatimu.",notes:null,fawaid:"Sesungguhnya Allah mencintai bersin, sebab bersin menggerakan seseorang untuk beribadah. Dan anjuran membalas pujian atas Allah orang yang memuji Allah, begitu juga sebaliknya.",source:"HR. al-Bukhari"},{title:"Doa Balasan Kepada yang Mendoakan Kamu Bersin",arabic:"\u064a\u064e\u0647\u0652\u062f\u0650\u064a\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0647\u064f \u0648\u064e\u064a\u064f\u0635\u0652\u0644\u0650\u062d\u064f \u0628\u064e\u0627\u0644\u064e\u0643\u064f\u0645\u0652",latin:"Yahdikumullah wa yushlihu b\u0101lakum",translation:"Semoga Allah memberikan petunjuk, dan memperbaiki keadaan kalian.",notes:null,fawaid:"Sesungguhnya Allah mencintai bersin, sebab bersin menggerakan seseorang untuk beribadah. Dan anjuran membalas pujian atas Allah orang yang memuji Allah, begitu juga sebaliknya.",source:"HR. al-Bukhari"},{title:"Doa Meminta Akhlak yang Baik",arabic:"\u0627\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0643\u064e\u0645\u064e\u0627 \u062d\u064e\u0633\u0651\u064e\u0646\u0652\u062a\u064e \u062e\u064e\u0644\u0652\u0642\u0650\u064a \u0641\u064e\u062d\u064e\u0633\u0651\u0650\u0646\u0652 \u062e\u064f\u0644\u064f\u0642\u0650\u064a",latin:"Allahumma kam\u0101 hassanta kholq\u012b fahassin khuluq\u012b",translation:"Ya Allah, sebagaimana Engkau memperbagus badanku maka perbaguslah akhlaku.",notes:null,fawaid:"Paras yang menawan tidaklah cukup sebagai bekal seorang muslim, tapi harus diiringi dengan akhlak yang mulia. Maka hendaklah seorang muslim terus meminta untuk diperbaiki dan diperindah akhlaknya.",source:"HR. Ahmad, dishahihkan al-Albani dalam al-Irwa', 1/115"},{title:"Doa Berlindung dari Syaitan",arabic:"\u0631\u064e\u0628\u0650\u0651 \u0623\u064e\u0639\u064f\u0648\u0652\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0647\u064e\u0645\u064e\u0632\u064e\u0627\u062a\u0650 \u0627\u0644\u0634\u064e\u0651\u064a\u064e\u0627\u0637\u0650\u064a\u0652\u0646\u0650 \u0648\u064e\u0623\u064e\u0639\u064f\u0648\u0652\u0630\u064f \u0628\u0650\u0643\u064e \u0631\u064e\u0628\u0650\u0651 \u0623\u064e\u0646\u0652 \u064a\u064e\u062d\u0652\u0636\u064f\u0631\u064f\u0648\u0652\u0646\u0650",latin:"Rabbi a'\u016b\u017cu bika min hamaz\u0101tisy syay\u0101th\u012bn wa a'\u016b\u017cu bika rabbi ay yahdhur\u016bn",translation:"Ya Tuhanku aku berlindung kepada Engkau dari bisikan-bisikan syaitan dan aku berlindung (pula) kepada Engkau ya Tuhanku, dari kedatangan mereka kepadaku.",notes:null,fawaid:"Sesungguhnya Allah memerintahkan kepada nabi Muhammad dan seluruh ummat nya untuk berlindung dari bisikan syaitan dalam seluruh kegiatan dan terlebih saat menjelang kematian, yang mana syaitan membisikannya melalui hati seorang hamba dan membisikannya untuk melakukan kejelekan.",source:"QS. Al-Mu'minun: 97-98"},{title:"Doa Sesudah Adzan",arabic:"\u0627\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0631\u064e\u0628\u0651\u064e \u0647\u064e\u0630\u0650\u0647\u0650 \u0627\u0644\u062f\u0651\u064e\u0639\u0652\u0648\u064e\u0629\u0650 \u0627\u0644\u062a\u0651\u064e\u0627\u0645\u0651\u064e\u0629\u0650\u060c \u0648\u064e\u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u0650 \u0627\u0644\u0652\u0642\u064e\u0627\u0626\u0650\u0645\u064e\u0629\u0650\u060c \u0622\u062a\u0650 \u0645\u064f\u062d\u064e\u0645\u0651\u064e\u062f\u064b\u0627 \u0627\u0644\u0652\u0648\u064e\u0633\u0650\u064a\u0644\u064e\u0629\u064e \u0648\u064e\u0627\u0644\u0652\u0641\u064e\u0636\u0650\u064a\u0644\u064e\u0629\u064e\u060c \u0648\u064e\u0627\u0628\u0652\u0639\u064e\u062b\u0652\u0647\u064f \u0645\u064e\u0642\u064e\u0627\u0645\u064b\u0627 \u0645\u064e\u062d\u0652\u0645\u064f\u0648\u062f\u064b\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0648\u064e\u0639\u064e\u062f\u0652\u062a\u064e\u0647\u064f",latin:"Allahumma rabba h\u0101\u017cihid da'watit t\u0101mmah, wasshal\u0101til q\u0101aimah, \u0101ti muhammadanil was\u012blata wal fadh\u012bilah, wab'a\u1e61hu maq\u0101man mahm\u016bda alla\u017c\u012b wa'adtah",translation:"Ya Allah, pemilik seruan yang sempurna ini dan sholat yang ditegakkan, anugerahkanlah kepada Nabi Muhammad; wasilah (kedudukan yang tinggi di surga) dan keutamaan (melebihi seluruh makhluk), dan bangkitkanlah beliau dalam kedudukan terpuji (memberi syafa'at) yang telah Engkau janjikan.",notes:null,fawaid:"Doa tersebut adalah doa yang disunnahkan oleh Rasulullah shallallahu alaihi wa sallam bagi orang yang mendengar panggilan shalat. Doa ini memiliki banyak keutamaan, di antaranya adalah mendapatkan syafaat dari Rasulullah shallallahu alaihi wa sallam dihari kiamat, mendapatkan wasilah dan kemuliaan bagi Nabi Muhammad shallallahu alaihi wa sallam di surga, dan mendapatkan pahala yang besar dan terpuji di sisi Allah ta'ala. Doa ini juga merupakan penghormatan dan pengagungan kepada Allah subhanahu wa ta'ala dan Rasul-Nya, serta menunjukkan rasa cinta dan rindu kepada Nabi Muhammad shallallahu alaihi wa sallam yang merupakan suri tauladan bagi umat Islam.",source:"HR. Abu Dawud (529), at-Tirmidzi (211), an-Nasa'i (2:26), Ibnu Majah (722)"},{title:"Doa Memohon Ampunan untuk Kedua Orang Tua",arabic:"\u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0671\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u0650\u0649 \u0648\u064e\u0644\u0650\u0648\u064e\u0670\u0644\u0650\u062f\u064e\u0649\u0651\u064e \u0648\u064e\u0644\u0650\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064e\u0642\u064f\u0648\u0645\u064f \u0671\u0644\u0652\u062d\u0650\u0633\u064e\u0627\u0628\u064f",latin:"Rabbanagfir l\u012b wa liw\u0101lidayya wa lil mu'min\u012bna yauma yaq\u016bmul h\u012bs\u0101b",translation:"Ya Tuhan kami, beri ampunilah aku dan kedua ibu bapaku dan sekalian orang-orang mukmin pada hari terjadinya hisab (hari kiamat)",notes:null,fawaid:"Doa tersebut adalah doa Nabi Ibrahim 'alaihissalam yang mengajarkan kita untuk menghormati dan menyayangi orang tua, mengingat hari akhir, dan peduli terhadap sesama mukmin. Dengan berdoa seperti ini, kita berharap Allah subhanahu wa ta'ala mengampuni dosa-dosa kita dan menjadikan kita orang-orang yang beriman.",source:"QS. Ibrahim: 41"}]},1276,[]);
__d(function(a,i,l,n,u,h,e){u.exports=[{title:"Istighfar",arabic:"\u0623\u064e\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u064f \u0627\u0644\u0644\u064e\u0651\u0647\u064e",latin:"Astaghfirull\u0101h",translation:"Aku minta ampun kepada Allah.",notes:"Dibaca 3x",fawaid:"Rasulullah shallallahu 'alaihi wa sallam jika selesai dari shalatnya beliau beristighfar sebanyak tiga kali dan membaca dzikir di atas. Al Auza'i menyatakan bahwa bacaan istighfar adalah astaghfirullah, astaghfirullah.",source:"HR. Muslim No. 591"},{title:"Allah yang Memberi Keselamatan",arabic:"\u0627\u064e\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0623\u064e\u0646\u0652\u062a\u064e \u0627\u0644\u0633\u064e\u0651\u0644\u0627\u064e\u0645\u064f\u060c \u0648\u064e\u0645\u0650\u0646\u0652\u0643\u064e \u0627\u0644\u0633\u064e\u0651\u0644\u0627\u064e\u0645\u064f\u060c \u062a\u064e\u0628\u064e\u0627\u0631\u064e\u0643\u0652\u062a\u064e \u064a\u064e\u0627 \u0630\u064e\u0627 \u0627\u0644\u0652\u062c\u064e\u0644\u0627\u064e\u0644\u0650 \u0648\u064e\u0627\u0652\u0644\u0625\u0650\u0643\u0652\u0631\u064e\u0627\u0645\u0650",latin:"All\u0101humma antas sal\u0101m wa minkas sal\u0101m tab\u0101rakta y\u0101 \u017cal jal\u0101li wal ikr\u0101m",translation:"Ya Allah, Engkau pemberi keselamatan, dan dari-Mu keselaatan, Maha Suci Engkau, wahai tuhan yang pemilik keagungan dan kemuliaan.",notes:"Dibaca 1x",fawaid:"Rasulullah shallallahu 'alaihi wa sallam jika selesai dari shalatnya beliau beristighfar sebanyak tiga kali dan membaca dzikir di atas. Al Auza'i menyatakan bahwa bacaan istighfar adalah astaghfirullah, astaghfirullah.",source:"HR. Muslim No. 591"},{title:"Allah yang Menghalangi dan yang Memberikan Segala Sesuatu",arabic:"\u0644\u0627\u064e \u0625\u0650\u0644\u064e\u0640\u0647\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0627\u0644\u0644\u0647\u064f \u0648\u064e\u062d\u0652\u062f\u064e\u0647\u064f \u0644\u0627\u064e \u0634\u064e\u0631\u0650\u064a\u0652\u0643\u064e \u0644\u064e\u0647\u064f\u060c \u0644\u064e\u0647\u064f \u0627\u0644\u0652\u0645\u064f\u0644\u0652\u0643\u064f \u0648\u064e\u0644\u064e\u0647\u064f \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0648\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u0649 \u0643\u064f\u0644\u0650\u0651 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0652\u0631\u064f\u060c \u0627\u064e\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0644\u0627\u064e \u0645\u064e\u0627\u0646\u0650\u0639\u064e \u0644\u0650\u0645\u064e\u0627 \u0623\u064e\u0639\u0652\u0637\u064e\u064a\u0652\u062a\u064e\u060c \u0648\u064e\u0644\u0627\u064e \u0645\u064f\u0639\u0652\u0637\u0650\u064a\u064e \u0644\u0650\u0645\u064e\u0627 \u0645\u064e\u0646\u064e\u0639\u0652\u062a\u064e\u060c \u0648\u064e\u0644\u0627\u064e \u064a\u064e\u0646\u0652\u0641\u064e\u0639\u064f \u0630\u064e\u0627 \u0627\u0644\u0652\u062c\u064e\u062f\u0650\u0651 \u0645\u0650\u0646\u0652\u0643\u064e \u0627\u0644\u0652\u062c\u064e\u062f\u064f\u0651",latin:"L\u0101 il\u0101ha ill\u0101ll\u0101h wa\u1e25dahu l\u0101 syar\u012bka lah, lahul mulku wa lahul \u1e25amdu wa huwa 'al\u0101 kulli syai'in qad\u012br. All\u0101humma l\u0101 m\u0101ni'a lim\u0101 a'thaita wa l\u0101 mu'\u1e6diya lim\u0101 mana'ta wa l\u0101 yanfa'u \u017cal jaddi minkaljaddu",translation:"Tiada Rabb yang berhak disembah selain Allah yang Maha Esa, tidak ada sekutu bagi-Nya. Bagi-Nya puji dan bagi-Nya kerajaan. Dia Maha Kuasa atas segala sesuatu. Ya Allah, tidak ada yang mencegah apa yang Engkau berikan dan tidak ada yang memberi apa yang Engkau cegah. Tidak berguna kekayaan dan kemuliaan itu bagi pemiliknya (selain iman dan amal shalihnya yang menyelamatkan dari siksaan). Hanya dari-Mu kekayaan dan kemuliaan.",notes:"Dibaca 1x",fawaid:null,source:"HR. Bukhari No. 844 dan Muslim No. 593"},{title:"Allah yang Memiliki Segalanya dan yang Berhak Diibadahi",arabic:"\u0644\u0627\u064e \u0625\u0650\u0644\u064e\u0640\u0647\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0627\u0644\u0644\u0647\u064f \u0648\u064e\u062d\u0652\u062f\u064e\u0647\u064f \u0644\u0627\u064e \u0634\u064e\u0631\u0650\u064a\u0652\u0643\u064e \u0644\u064e\u0647\u064f\u060c \u0644\u064e\u0647\u064f \u0627\u0644\u0652\u0645\u064f\u0644\u0652\u0643\u064f \u0648\u064e\u0644\u064e\u0647\u064f \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0648\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u0649 \u0643\u064f\u0644\u0650\u0651 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0652\u0631\u064f. \u0644\u0627\u064e \u062d\u064e\u0648\u0652\u0644\u064e \u0648\u064e\u0644\u0627\u064e \u0642\u064f\u0648\u064e\u0651\u0629\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0628\u0650\u0627\u0644\u0644\u0647\u0650\u060c \u0644\u0627\u064e \u0625\u0650\u0644\u064e\u0640\u0647\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0627\u0644\u0644\u0647\u064f\u060c \u0648\u064e\u0644\u0627\u064e \u0646\u064e\u0639\u0652\u0628\u064f\u062f\u064f \u0625\u0650\u0644\u0627\u064e\u0651 \u0625\u0650\u064a\u064e\u0651\u0627\u0647\u064f\u060c \u0644\u064e\u0647\u064f \u0627\u0644\u0646\u0650\u0651\u0639\u0652\u0645\u064e\u0629\u064f \u0648\u064e\u0644\u064e\u0647\u064f \u0627\u0644\u0652\u0641\u064e\u0636\u0652\u0644\u064f \u0648\u064e\u0644\u064e\u0647\u064f \u0627\u0644\u062b\u064e\u0651\u0646\u064e\u0627\u0621\u064f \u0627\u0644\u0652\u062d\u064e\u0633\u064e\u0646\u064f\u060c \u0644\u0627\u064e \u0625\u0650\u0644\u064e\u0640\u0647\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0627\u0644\u0644\u0647\u064f \u0645\u064f\u062e\u0652\u0644\u0650\u0635\u0650\u064a\u0652\u0646\u064e \u0644\u064e\u0647\u064f \u0627\u0644\u062f\u0650\u0651\u064a\u0652\u0646\u064e \u0648\u064e\u0644\u064e\u0648\u0652 \u0643\u064e\u0631\u0650\u0647\u064e \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u064f\u0648\u0652\u0646\u064e",latin:"L\u0101 il\u0101ha ill\u0101ll\u0101h wa\u1e25dahu l\u0101 syar\u012bka lah. Lahul mulku wa lahul \u1e25amdu wa huwa 'al\u0101 kulli syai'in qad\u012br. L\u0101 \u1e25awla wa l\u0101 quwwata ill\u0101 bill\u0101h. L\u0101 il\u0101ha ill\u0101ll\u0101h wa l\u0101 na'budu ill\u0101 iyy\u0101h. Lahun ni'mah wa lahul fa\u1e0dl wa lahu\u1e61 \u1e61an\u0101ul \u1e25asan. L\u0101 il\u0101ha ill\u0101ll\u0101h mukhlish\u012bna lahud d\u012bn wa law karihal k\u0101fir\u016bn",translation:"Tiada Rabb (yang berhak disembah) kecuali Allah, Yang Maha Esa, tidak ada sekutu bagi-Nya. Bagi-Nya kerajaan dan pujaan. Dia Mahakuasa atas segala sesuatu. Tidak ada daya dan kekuatan kecuali (dengan pertolongan) Allah. Tiada Rabb (yang hak disembah) kecuali Allah. Kami tidak menyembah kecuali kepada-Nya. Bagi-Nya nikmat, anugerah dan pujaan yang baik. Tiada Rabb (yang hak disembah) kecuali Allah, dengan memurnikan ibadah kepada-Nya, sekalipun orang-orang kafir sama benci.",notes:"Dibaca 1x",fawaid:"Dikatakan oleh 'Abdull\u0101h bin Zubair, Nabi shallall\u0101hu 'alaihi wa sallam biasa membaca tahlil (l\u0101 il\u0101ha ill\u0101ll\u0101h) di akhir shalat.",source:"HR. Muslim No. 594"},{title:"Tasbih",arabic:"\u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0647\u0650",latin:"Sub\u1e25\u0101nall\u0101h",translation:"Maha Suci Allah",notes:"Dibaca 33x",fawaid:null,source:null},{title:"Tahmid",arabic:"\u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u064e\u0651\u0647\u0650",latin:"Alhamdulill\u0101h",translation:"Segala puji bagi Allah",notes:"Dibaca 33x",fawaid:null,source:null},{title:"Takbir",arabic:"\u0627\u0644\u0644\u0647\u064f \u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064f",latin:"All\u0101hu akbar",translation:"Allah Maha Besar",notes:"Dibaca 33x",fawaid:null,source:null},{title:"Tidak Ada Sekutu Bagi Allah dan Baginyalah Segala Sesuatu",arabic:"\u0644\u0627\u064e \u0625\u0650\u0644\u064e\u0640\u0647\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0627\u0644\u0644\u0647\u064f \u0648\u064e\u062d\u0652\u062f\u064e\u0647\u064f \u0644\u0627\u064e \u0634\u064e\u0631\u0650\u064a\u0652\u0643\u064e \u0644\u064e\u0647\u064f\u060c \u0644\u064e\u0647\u064f \u0627\u0644\u0652\u0645\u064f\u0644\u0652\u0643\u064f \u0648\u064e\u0644\u064e\u0647\u064f \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0648\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u0649 \u0643\u064f\u0644\u0650\u0651 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0652\u0631\u064f",latin:"L\u0101 il\u0101ha ill\u0101ll\u0101h wa\u1e25da, l\u0101 syar\u012bka lah. Lahul mulku wa lahul \u1e25amdu wa huwa 'al\u0101 kulli syai'in qad\u012br",translation:"Tidak ada Rabb (yang berhak disembah) kecuali Allah Yang Maha Esa, tidak ada sekutu bagi-Nya. Bagi-Nya kerajaan. Bagi-Nya pujaan. Dia-lah Yang Mahakuasa atas segala sesuatu.",notes:"Dibaca 1x",fawaid:"Siapa yang membaca dzikir di atas, maka dosa-dosanya diampuni walau sebanyak buih di lautan. Kata Im\u0101m Nawaw\u012b ra\u1e25imahull\u0101h, tekstual hadits menunjukkan bahwa bacaan Sub\u1e25\u0101nall\u0101h, Alhamdulill\u0101h, All\u0101hu akbar, masing-masing dibaca 33 kali secara terpisah.",source:"Syarh Shahih Muslim, 5: 84"},{title:"Ayat al-Kursi",arabic:"\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u0671\u0644\u0652\u062d\u064e\u0649\u0651\u064f \u0671\u0644\u0652\u0642\u064e\u064a\u0651\u064f\u0648\u0645\u064f \u06da \u0644\u064e\u0627 \u062a\u064e\u0623\u0652\u062e\u064f\u0630\u064f\u0647\u064f\u06e5 \u0633\u0650\u0646\u064e\u0629\u064c \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0648\u0652\u0645\u064c \u06da \u0644\u0651\u064e\u0647\u064f\u06e5 \u0645\u064e\u0627 \u0641\u0650\u0649 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u0649 \u0671\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d7 \u0645\u064e\u0646 \u0630\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u0649 \u064a\u064e\u0634\u0652\u0641\u064e\u0639\u064f \u0639\u0650\u0646\u062f\u064e\u0647\u064f\u06e5\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0625\u0650\u0630\u0652\u0646\u0650\u0647\u0650\u06e6 \u06da \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u0652\u0641\u064e\u0647\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u064a\u0637\u064f\u0648\u0646\u064e \u0628\u0650\u0634\u064e\u0649\u0652\u0621\u064d \u0645\u0651\u0650\u0646\u0652 \u0639\u0650\u0644\u0652\u0645\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0645\u064e\u0627 \u0634\u064e\u0627\u0653\u0621\u064e \u06da \u0648\u064e\u0633\u0650\u0639\u064e \u0643\u064f\u0631\u0652\u0633\u0650\u064a\u0651\u064f\u0647\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u06d6 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0640\u0654\u064f\u0648\u062f\u064f\u0647\u064f\u06e5 \u062d\u0650\u0641\u0652\u0638\u064f\u0647\u064f\u0645\u064e\u0627 \u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u0652\u0639\u064e\u0644\u0650\u0649\u0651\u064f \u0671\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u064f",latin:"All\u0101hu l\u0101 il\u0101ha ill\u0101 huwal\u1e25ayyul qayy\u1ee5m, l\u0101 ta`khu\u017cuh\u1ee5 sinatuw wa l\u0101 na`\u1ee5m, lah\u1ee5 m\u0101 fis sam\u0101w\u0101ti wa m\u0101 fil ar\u1e0d, man \u017calla\u017c\u012b yasyfa'u 'indah\u016b ill\u0101 bi`i\u017cnih, ya'lamu m\u0101 baina aid\u012bhim wa m\u0101 khalfahum, wa l\u0101 yu\u1e25\u012b\u1e6d\u1ee5na bisyai`im min 'ilmih\u012b ill\u0101 bim\u0101 sy\u0101`, wasi'a kursiyyuhus sam\u0101w\u0101ti wal ar\u1e0d, wa l\u0101 ya`\u1ee5duh\u1ee5 \u1e25if\u1e93uhum\u0101, wa huwal 'aliyyul 'a\u1e93\u012bm",translation:"Allah, tidak ada Tuhan (yang berhak disembah) melainkan Dia Yang Hidup kekal lagi terus menerus mengurus (makhluk-Nya); tidak mengantuk dan tidak tidur. Kepunyaan-Nya apa yang di langit dan di bumi. Tiada yang dapat memberi syafa'at di sisi Allah tanpa izin-Nya? Allah mengetahui apa-apa yang di hadapan mereka dan di belakang mereka, dan mereka tidak mengetahui apa-apa dari ilmu Allah melainkan apa yang dikehendaki-Nya. Kursi Allah meliputi langit dan bumi. Dan Allah tidak merasa berat memelihara keduanya, dan Allah Maha Tinggi lagi Maha Besar.",notes:"Dibaca 1x",fawaid:"Barang siapa yang membaca ayat kursi setelah selesai shalat, maka tidak ada yang menghalanginya masuk surga kecuali kematian.",source:"HR. an-Nasai dalam Al-Kubro 9: 44. Hadits ini dinyatakan shahih oleh Ibnu Hibban, sebagaimana disebut oleh Ibnu Hajar dalam Bulughul Maram"},{title:"Al-Ikhlas",arabic:"\u0642\u064f\u0644\u0652 \u0647\u064f\u0648\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u062d\u064e\u062f\u064c (1) \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0635\u0651\u064e\u0645\u064e\u062f\u064f (2) \u0644\u064e\u0645\u0652 \u064a\u064e\u0644\u0650\u062f\u0652 \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064f\u0648\u0644\u064e\u062f\u0652 (3) \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0643\u064f\u0646 \u0644\u0651\u064e\u0647\u064f\u06e5 \u0643\u064f\u0641\u064f\u0648\u064b\u0627 \u0623\u064e\u062d\u064e\u062f\u064c\u06e2 (4)",latin:"Qul huwall\u0101hu a\u1e25ad (1) All\u0101hu\u1e63 \u1e63amad (2) lam yalid wa lam y\u1ee5lad (3) wa lam yakul lah\u1ee5 kufuwan a\u1e25ad (4)",translation:"Katakanlah: \"Dialah Allah, Yang Maha Esa. Allah adalah Tuhan yang bergantung kepada-Nya segala sesuatu. Dia tiada beranak dan tidak pula diperanakkan, dan tidak ada seorangpun yang setara dengan Dia\".",notes:"Dibaca 3x",fawaid:"Rasulullah shallallahu 'alaihi wa sallam bersabda: Katakanlah (bacalah surat), Qulhuwallahu ahad, dan Al-Muawwidzatain (Al-Falaq dan An-Naas) ketika petang dan pagi tiga kali, maka dengan ayat ini akan mencukupkanmu (menjagamu) dari segala sesuatu.",source:"HR. Abu Dawud No. 1523 dan an-Nasa'i No. 1337. Al Hafizh Abu Thohir mengatakan bahwa sanad hadits ini hasan"},{title:"Al-Falaq",arabic:"\u0642\u064f\u0644\u0652 \u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0631\u064e\u0628\u0651\u0650 \u0671\u0644\u0652\u0641\u064e\u0644\u064e\u0642\u0650 (1) \u0645\u0650\u0646 \u0634\u064e\u0631\u0651\u0650 \u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u064e (2) \u0648\u064e\u0645\u0650\u0646 \u0634\u064e\u0631\u0651\u0650 \u063a\u064e\u0627\u0633\u0650\u0642\u064d \u0625\u0650\u0630\u064e\u0627 \u0648\u064e\u0642\u064e\u0628\u064e (3) \u0648\u064e\u0645\u0650\u0646 \u0634\u064e\u0631\u0651\u0650 \u0671\u0644\u0646\u0651\u064e\u0641\u0651\u064e\u0670\u062b\u064e\u0670\u062a\u0650 \u0641\u0650\u0649 \u0671\u0644\u0652\u0639\u064f\u0642\u064e\u062f\u0650 (4) \u0648\u064e\u0645\u0650\u0646 \u0634\u064e\u0631\u0651\u0650 \u062d\u064e\u0627\u0633\u0650\u062f\u064d \u0625\u0650\u0630\u064e\u0627 \u062d\u064e\u0633\u064e\u062f\u064e (5)",latin:"Qul a'\u1ee5\u017cu birabbil falaq (1) min syarri m\u0101 khalaq (2) wa min syarri g\u0101siqin i\u017c\u0101 waqab (3) wa min syarrin naff\u0101\u1e61\u0101ti fil 'uqad (4) wa min syarri \u1e25\u0101sidin i\u017c\u0101 \u1e25asad (5)",translation:"Katakanlah: \"Aku berlindung kepada Tuhan Yang Menguasai subuh, dari kejahatan makhluk-Nya, dan dari kejahatan malam apabila telah gelap gulita, dan dari kejahatan wanita-wanita tukang sihir yang menghembus pada buhul-buhul, dan dari kejahatan pendengki bila ia dengki\".",notes:"Dibaca 3x",fawaid:"Rasulullah shallallahu 'alaihi wa sallam bersabda: Katakanlah (bacalah surat), Qulhuwallahu ahad, dan Al-Muawwidzatain (Al-Falaq dan An-Naas) ketika petang dan pagi tiga kali, maka dengan ayat ini akan mencukupkanmu (menjagamu) dari segala sesuatu.",source:"HR. Abu Dawud No. 1523 dan an-Nasa'i No. 1337. Al Hafizh Abu Thohir mengatakan bahwa sanad hadits ini hasan"},{title:"An-Naas",arabic:"\u0642\u064f\u0644\u0652 \u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0631\u064e\u0628\u0651\u0650 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 (1) \u0645\u064e\u0644\u0650\u0643\u0650 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 (2) \u0625\u0650\u0644\u064e\u0670\u0647\u0650 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 (3) \u0645\u0650\u0646 \u0634\u064e\u0631\u0651\u0650 \u0671\u0644\u0652\u0648\u064e\u0633\u0652\u0648\u064e\u0627\u0633\u0650 \u0671\u0644\u0652\u062e\u064e\u0646\u0651\u064e\u0627\u0633\u0650 (4) \u0671\u0644\u0651\u064e\u0630\u0650\u0649 \u064a\u064f\u0648\u064e\u0633\u0652\u0648\u0650\u0633\u064f \u0641\u0650\u0649 \u0635\u064f\u062f\u064f\u0648\u0631\u0650 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 (5) \u0645\u0650\u0646\u064e \u0671\u0644\u0652\u062c\u0650\u0646\u0651\u064e\u0629\u0650 \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 (6)",latin:"Qul a'\u1ee5\u017cu birabbin n\u0101s (1) malikin n\u0101s (2) il\u0101hin n\u0101s (3) min syarril wasw\u0101sil khann\u0101s (4) alla\u017c\u012b yuwaswisu f\u012b \u1e63ud\u1ee5rin n\u0101s (5) minal jinnati wan n\u0101s (6)",translation:"Katakanlah: \u201cAku berlindung kepada Tuhan (yang memelihara dan menguasai) manusia. (1) Raja manusia. (2) Sembahan manusia. (3) Dari kejahatan (bisikan) syaitan yang biasa bersembunyi, (4) yang membisikkan (kejahatan) ke dalam dada manusia, (5) dari (golongan) jin dan manusia. (6)",notes:"Dibaca 3x",fawaid:"Rasulullah shallallahu 'alaihi wa sallam bersabda: Katakanlah (bacalah surat), Qulhuwallahu ahad, dan Al-Muawwidzatain (Al-Falaq dan An-Naas) ketika petang dan pagi tiga kali, maka dengan ayat ini akan mencukupkanmu (menjagamu) dari segala sesuatu.",source:"HR. Abu Dawud No. 1523 dan an-Nasa'i No. 1337. Al Hafizh Abu Thohir mengatakan bahwa sanad hadits ini hasan"},{title:"Doa Meminta Ilmu Yang Bermanfaat, Rezeki yang Baik, dan Amal yang Diterima",arabic:"\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0625\u0650\u0646\u0650\u0651\u0649 \u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064e \u0639\u0650\u0644\u0652\u0645\u064b\u0627 \u0646\u064e\u0627\u0641\u0650\u0639\u064b\u0627 \u0648\u064e\u0631\u0650\u0632\u0652\u0642\u064b\u0627 \u0637\u064e\u064a\u0650\u0651\u0628\u064b\u0627 \u0648\u064e\u0639\u064e\u0645\u064e\u0644\u0627\u064b \u0645\u064f\u062a\u064e\u0642\u064e\u0628\u064e\u0651\u0644\u0627\u064b",latin:"Allahumma inn\u012b as'aluka 'ilman n\u0101fi'a, wa rizqan thayyiba, wa 'amalan mutaqabbala",translation:"Ya Allah, sungguh aku memohon kepada-Mu ilmu yang bermanfaat (bagi diriku dan orang lain), rizki yang halal dan amal yang diterima (di sisi-Mu dan mendapatkan ganjaran yang baik).",notes:"Dibaca 1x setelah salam dari shalat Shubuh",fawaid:"Ilmu yang bermanfaat adalah bekal yang memudahkan kehidupan, mendapatkan rizki yang baik menjadi tujuan seseorang dalam bekerja, dan amalan yang diterima harapan setiap orang yang beramal. Maka seyogyanya seorang hamba senantiasa meminta 3 hal ini pada setiap pagi sebelum memulai berbagai aktivitasnya.",source:"HR. Ibnu Majah No. 925 dan Ahmad 6: 305, 322. Al-Hafizh Abu Thohir mengatakan bahwa hadits ini shahih"}]},1277,[]);
__d(function(a,i,n,l,u,h,d){u.exports=[{title:"Ayat al-Kursi",arabic:"\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u0671\u0644\u0652\u062d\u064e\u0649\u0651\u064f \u0671\u0644\u0652\u0642\u064e\u064a\u0651\u064f\u0648\u0645\u064f \u06da \u0644\u064e\u0627 \u062a\u064e\u0623\u0652\u062e\u064f\u0630\u064f\u0647\u064f\u06e5 \u0633\u0650\u0646\u064e\u0629\u064c \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0648\u0652\u0645\u064c \u06da \u0644\u0651\u064e\u0647\u064f\u06e5 \u0645\u064e\u0627 \u0641\u0650\u0649 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u0649 \u0671\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d7 \u0645\u064e\u0646 \u0630\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u0649 \u064a\u064e\u0634\u0652\u0641\u064e\u0639\u064f \u0639\u0650\u0646\u062f\u064e\u0647\u064f\u06e5\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0625\u0650\u0630\u0652\u0646\u0650\u0647\u0650\u06e6 \u06da \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u0652\u0641\u064e\u0647\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u064a\u0637\u064f\u0648\u0646\u064e \u0628\u0650\u0634\u064e\u0649\u0652\u0621\u064d \u0645\u0651\u0650\u0646\u0652 \u0639\u0650\u0644\u0652\u0645\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0645\u064e\u0627 \u0634\u064e\u0627\u0653\u0621\u064e \u06da \u0648\u064e\u0633\u0650\u0639\u064e \u0643\u064f\u0631\u0652\u0633\u0650\u064a\u0651\u064f\u0647\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u06d6 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0640\u0654\u064f\u0648\u062f\u064f\u0647\u064f\u06e5 \u062d\u0650\u0641\u0652\u0638\u064f\u0647\u064f\u0645\u064e\u0627 \u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u0652\u0639\u064e\u0644\u0650\u0649\u0651\u064f \u0671\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u064f",latin:"All\u0101hu l\u0101 il\u0101ha ill\u0101 huwal\u1e25ayyul qayy\u1ee5m, l\u0101 ta`khu\u017cuh\u1ee5 sinatuw wa l\u0101 na`\u1ee5m, lah\u1ee5 m\u0101 fis sam\u0101w\u0101ti wa m\u0101 fil ar\u1e0d, man \u017calla\u017c\u012b yasyfa'u 'indah\u016b ill\u0101 bi`i\u017cnih, ya'lamu m\u0101 baina aid\u012bhim wa m\u0101 khalfahum, wa l\u0101 yu\u1e25\u012b\u1e6d\u1ee5na bisyai`im min 'ilmih\u012b ill\u0101 bim\u0101 sy\u0101`, wasi'a kursiyyuhus sam\u0101w\u0101ti wal ar\u1e0d, wa l\u0101 ya`\u1ee5duh\u1ee5 \u1e25if\u1e93uhum\u0101, wa huwal 'aliyyul 'a\u1e93\u012bm",translation:"Allah, tidak ada Tuhan (yang berhak disembah) melainkan Dia Yang Hidup kekal lagi terus menerus mengurus (makhluk-Nya); tidak mengantuk dan tidak tidur. Kepunyaan-Nya apa yang di langit dan di bumi. Tiada yang dapat memberi syafa'at di sisi Allah tanpa izin-Nya? Allah mengetahui apa-apa yang di hadapan mereka dan di belakang mereka, dan mereka tidak mengetahui apa-apa dari ilmu Allah melainkan apa yang dikehendaki-Nya. Kursi Allah meliputi langit dan bumi. Dan Allah tidak merasa berat memelihara keduanya, dan Allah Maha Tinggi lagi Maha Besar.",notes:"Dibaca 1x",fawaid:"Barang siapa yang membaca ayat ini ketika pagi, maka ia akan dilindungi hingga petang. Dan barang siapa yang membacanya ketika petang, maka ia akan dilindungi hingga pagi.",source:"HR. at-Tirmidzi: 2879"},{title:"Al-Ikhlas",arabic:"\u0642\u064f\u0644\u0652 \u0647\u064f\u0648\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u062d\u064e\u062f\u064c (1) \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0635\u0651\u064e\u0645\u064e\u062f\u064f (2) \u0644\u064e\u0645\u0652 \u064a\u064e\u0644\u0650\u062f\u0652 \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064f\u0648\u0644\u064e\u062f\u0652 (3) \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0643\u064f\u0646 \u0644\u0651\u064e\u0647\u064f\u06e5 \u0643\u064f\u0641\u064f\u0648\u064b\u0627 \u0623\u064e\u062d\u064e\u062f\u064c\u06e2 (4)",latin:"Qul huwall\u0101hu a\u1e25ad (1) All\u0101hu\u1e63 \u1e63amad (2) lam yalid wa lam y\u1ee5lad (3) wa lam yakul lah\u1ee5 kufuwan a\u1e25ad (4)",translation:"Katakanlah: \"Dialah Allah, Yang Maha Esa. Allah adalah Tuhan yang bergantung kepada-Nya segala sesuatu. Dia tiada beranak dan tidak pula diperanakkan, dan tidak ada seorangpun yang setara dengan Dia\".",notes:"Dibaca 3x",fawaid:"Rasulullah shallallahu 'alaihi wa sallam bersabda: Katakanlah (bacalah surat), Qulhuwallahu ahad, dan Al-Muawwidzatain (Al-Falaq dan An-Naas) ketika petang dan pagi tiga kali, maka dengan ayat ini akan mencukupkanmu (menjagamu) dari segala sesuatu.",source:"HR. Abu Dawud No. 4241"},{title:"Al-Falaq",arabic:"\u0642\u064f\u0644\u0652 \u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0631\u064e\u0628\u0651\u0650 \u0671\u0644\u0652\u0641\u064e\u0644\u064e\u0642\u0650 (1) \u0645\u0650\u0646 \u0634\u064e\u0631\u0651\u0650 \u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u064e (2) \u0648\u064e\u0645\u0650\u0646 \u0634\u064e\u0631\u0651\u0650 \u063a\u064e\u0627\u0633\u0650\u0642\u064d \u0625\u0650\u0630\u064e\u0627 \u0648\u064e\u0642\u064e\u0628\u064e (3) \u0648\u064e\u0645\u0650\u0646 \u0634\u064e\u0631\u0651\u0650 \u0671\u0644\u0646\u0651\u064e\u0641\u0651\u064e\u0670\u062b\u064e\u0670\u062a\u0650 \u0641\u0650\u0649 \u0671\u0644\u0652\u0639\u064f\u0642\u064e\u062f\u0650 (4) \u0648\u064e\u0645\u0650\u0646 \u0634\u064e\u0631\u0651\u0650 \u062d\u064e\u0627\u0633\u0650\u062f\u064d \u0625\u0650\u0630\u064e\u0627 \u062d\u064e\u0633\u064e\u062f\u064e (5)",latin:"Qul a'\u1ee5\u017cu birabbil falaq (1) min syarri m\u0101 khalaq (2) wa min syarri g\u0101siqin i\u017c\u0101 waqab (3) wa min syarrin naff\u0101\u1e61\u0101ti fil 'uqad (4) wa min syarri \u1e25\u0101sidin i\u017c\u0101 \u1e25asad (5)",translation:"Katakanlah: \"Aku berlindung kepada Tuhan Yang Menguasai subuh, dari kejahatan makhluk-Nya, dan dari kejahatan malam apabila telah gelap gulita, dan dari kejahatan wanita-wanita tukang sihir yang menghembus pada buhul-buhul, dan dari kejahatan pendengki bila ia dengki\".",notes:"Dibaca 3x",fawaid:"Rasulullah shallallahu 'alaihi wa sallam bersabda: Katakanlah (bacalah surat), Qulhuwallahu ahad, dan Al-Muawwidzatain (Al-Falaq dan An-Naas) ketika petang dan pagi tiga kali, maka dengan ayat ini akan mencukupkanmu (menjagamu) dari segala sesuatu.",source:"HR. Abu Dawud No. 4241"},{title:"An-Naas",arabic:"\u0642\u064f\u0644\u0652 \u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0631\u064e\u0628\u0651\u0650 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 (1) \u0645\u064e\u0644\u0650\u0643\u0650 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 (2) \u0625\u0650\u0644\u064e\u0670\u0647\u0650 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 (3) \u0645\u0650\u0646 \u0634\u064e\u0631\u0651\u0650 \u0671\u0644\u0652\u0648\u064e\u0633\u0652\u0648\u064e\u0627\u0633\u0650 \u0671\u0644\u0652\u062e\u064e\u0646\u0651\u064e\u0627\u0633\u0650 (4) \u0671\u0644\u0651\u064e\u0630\u0650\u0649 \u064a\u064f\u0648\u064e\u0633\u0652\u0648\u0650\u0633\u064f \u0641\u0650\u0649 \u0635\u064f\u062f\u064f\u0648\u0631\u0650 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 (5) \u0645\u0650\u0646\u064e \u0671\u0644\u0652\u062c\u0650\u0646\u0651\u064e\u0629\u0650 \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 (6)",latin:"Qul a'\u1ee5\u017cu birabbin n\u0101s (1) malikin n\u0101s (2) il\u0101hin n\u0101s (3) min syarril wasw\u0101sil khann\u0101s (4) alla\u017c\u012b yuwaswisu f\u012b \u1e63ud\u1ee5rin n\u0101s (5) minal jinnati wan n\u0101s (6)",translation:"Katakanlah: \u201cAku berlindung kepada Tuhan (yang memelihara dan menguasai) manusia. (1) Raja manusia. (2) Sembahan manusia. (3) Dari kejahatan (bisikan) syaitan yang biasa bersembunyi, (4) yang membisikkan (kejahatan) ke dalam dada manusia, (5) dari (golongan) jin dan manusia. (6)",notes:"Dibaca 3x",fawaid:"Rasulullah shallallahu 'alaihi wa sallam bersabda: Katakanlah (bacalah surat), Qulhuwallahu ahad, dan Al-Muawwidzatain (Al-Falaq dan An-Naas) ketika petang dan pagi tiga kali, maka dengan ayat ini akan mencukupkanmu (menjagamu) dari segala sesuatu.",source:"HR. Abu Dawud No. 4241"},{title:"Memasuki Sore dalam Kerajaan Allah dan Memohon Perlindungan dari-Nya",arabic:"\u0623\u064e\u0645\u0652\u0633\u064e\u064a\u0652\u0646\u064e\u0627 \u0648\u064e\u0623\u064e\u0645\u0652\u0633\u064e\u0649 \u0627\u0644\u0652\u0645\u064f\u0644\u0652\u0643\u064f \u0644\u0644\u0647\u0650\u060c \u0648\u064e\u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0644\u0647\u0650\u060c \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0647\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0627\u0644\u0644\u0647\u064f \u0648\u064e\u062d\u0652\u062f\u064e\u0647\u064f \u0644\u0627\u064e \u0634\u064e\u0631\u0650\u064a\u0643\u064e \u0644\u064e\u0647\u064f\u060c \u0644\u064e\u0647\u064f \u0627\u0644\u0652\u0645\u064f\u0644\u0652\u0643\u064f \u0648\u064e\u0644\u064e\u0647\u064f \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f\u060c \u0648\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u0649 \u0643\u064f\u0644\u0650\u0651 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0631\u064c\u060c \u0631\u064e\u0628\u0650\u0651 \u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064e \u062e\u064e\u064a\u0652\u0631\u064e \u0645\u064e\u0627 \u0641\u0650\u064a \u0647\u064e\u0630\u0650\u0647\u0650 \u0627\u0644\u0644\u064e\u0651\u064a\u0652\u0644\u064e\u0629\u0650 \u0648\u064e\u062e\u064e\u064a\u0652\u0631\u064e \u0645\u064e\u0627 \u0628\u064e\u0639\u0652\u062f\u064e\u0647\u064e\u0627\u060c \u0648\u064e\u0623\u064e\u0639\u064f\u0648\u0630\u064f\u0628\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0634\u064e\u0631\u0650\u0651 \u0645\u064e\u0627 \u0641\u0650\u064a \u0647\u064e\u0630\u0650\u0647\u0650 \u0627\u0644\u0644\u064e\u0651\u064a\u0652\u0644\u064e\u0629\u0650 \u0648\u064e\u0634\u064e\u0631\u0650\u0651 \u0645\u064e\u0627 \u0628\u064e\u0639\u0652\u062f\u064e\u0647\u064e\u0627\u060c \u0631\u064e\u0628\u0650\u0651 \u0623\u064e\u0639\u064f\u0648\u0630\u064f\u0628\u0650\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0643\u064e\u0633\u064e\u0644\u0650 \u0648\u064e\u0633\u064f\u0648\u0621\u0650 \u0627\u0644\u0652\u0643\u0650\u0628\u064e\u0631\u0650\u060c \u0631\u064e\u0628\u0650\u0651 \u0623\u064e\u0639\u064f\u0648\u0630\u064f\u0628\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064d \u0641\u0650\u064a \u0627\u0644\u0646\u064e\u0651\u0627\u0631\u0650 \u0648\u064e\u0639\u064e\u0630\u064e\u0627\u0628\u064d \u0641\u0650\u064a \u0627\u0644\u0652\u0642\u064e\u0628\u0652\u0631\u0650",latin:"Amsayn\u0101 wa amsal mulku lill\u0101h wal\u1e25amdu lill\u0101h, l\u0101 il\u0101ha ill\u0101ll\u0101h wa\u1e25dahu l\u0101 syar\u012bka lah, lahul mulku walahul \u1e25amdu wa huwa 'al\u0101 kulli syai'in qad\u012br. Rabb\u012b as'aluka khaira m\u0101 f\u012b ha\u017cihil lailah wa khaira m\u0101 ba'dah\u0101, wa a'\u016b\u017cu bika min syarri m\u0101 f\u012b ha\u017cihil lailah wa syarri m\u0101 ba'dah\u0101. Rabb\u012b a'\u016b\u017cu bika minal kasali wa s\u016b'il kibar. Rabb\u012b a'\u016b\u017cu bika min 'a\u017c\u0101bin fin n\u0101ri wa 'a\u017c\u0101bin fil qobri",translation:"Kami telah memasuki waktu petang dan kerajaan hanya milik Allah, segala puji bagi Allah. Tidak ada ilah (yang berhak disembah) kecuali Allah semata, tiada sekutu bagi-Nya. Milik Allah kerajaan dan bagi-Nya pujian. Dia-lah Yang Mahakuasa atas segala sesuatu. Wahai Rabbku, aku mohon kepada-Mu kebaikan di malam ini dan kebaikan sesudahnya. Aku berlindung kepada-Mu dari kejahatan malam ini dan kejahatan sesudahnya. Wahai Rabbku, aku berlindung kepada-Mu dari kemalasan dan kejelekan di hari tua. Wahai Rabbku, aku berlindung kepada-Mu dari siksaan di neraka dan siksaan di kubur.",notes:"Dibaca 1x",fawaid:"Memohon perlindungan dari kejahatan lebih diutamakan, kaidah yang menunjukkan pentingnya hal tersebut adalah: \"Mencegah bahaya lebih penting dan didahulukan daripada mendatangkan kebaikan\".",source:"HR. Muslim No. 2723 (75), Abu Dawud No. 5071, dan at-Tirmidzi 3390, shahih dari Abdullah Ibnu Mas'ud"},{title:"Memasuki Sore dengan Memohon Rahmat Allah",arabic:"\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0628\u0650\u0643\u064e \u0623\u064e\u0645\u0652\u0633\u064e\u064a\u0652\u0646\u064e\u0627\u060c \u0648\u064e\u0628\u0650\u0643\u064e \u0623\u064e\u0635\u0652\u0628\u064e\u062d\u0652\u0646\u064e\u0627\u060c\u0648\u064e\u0628\u0650\u0643\u064e \u0646\u064e\u062d\u0652\u064a\u064e\u0627\u060c \u0648\u064e\u0628\u0650\u0643\u064e \u0646\u064e\u0645\u064f\u0648\u062a\u064f\u060c \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0627\u0644\u0652\u0645\u064e\u0635\u0650\u064a\u0652\u0631\u064f",latin:"Allahumma bika amsayn\u0101 wa bika ash bahn\u0101 wa bika nahy\u0101 wa bika nam\u016btu wa ilaikal mash\u012br",translation:"Ya Allah, dengan rahmat dan pertolongan-Mu kami memasuki waktu petang, dan dengan rahmat dan pertolongan-Mu kami memasuki waktu pagi. Dengan rahmat dan pertolongan-Mu kami hidup dan dengan kehendak-Mu kami mati. Dan kepada-Mu tempat kembali (bagi semua makhluk).",notes:"Dibaca 1x",fawaid:"Setiap hal yang kita lakukan dari pagi sampai petang, dari kita memulai kehidupan kita sampai kita mati, semuanya berada dibawah kendali Allah dan kepada-Nya lah kita kembali.",source:"HR. al-Bukhari dalam al-Abadul Mufrad No. 1199, lafadz ini adalah lafadz al-Bukhari at-Tirmidzi No. 3391, Abu Dawud No. 5068, Ahmad 11/354, Ibnu Majah No. 3868"},{title:"Sayyid al-Istighfar",arabic:"\u0627\u064e\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0623\u064e\u0646\u0652\u062a\u064e \u0631\u064e\u0628\u0651\u0650\u064a\u0652 \u060c \u0644\u064e\u0627 \u0625\u0650\u0644\u0670\u0640\u0647\u064e \u0625\u0650\u0644\u0627\u0651\u064e \u0623\u064e\u0646\u0652\u062a\u064e \u062e\u064e\u0644\u064e\u0642\u0652\u062a\u064e\u0646\u0650\u064a\u0652 \u0648\u064e\u0623\u064e\u0646\u064e\u0627 \u0639\u064e\u0628\u0652\u062f\u064f\u0643\u064e \u060c \u0648\u064e\u0623\u064e\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0639\u064e\u0647\u0652\u062f\u0650\u0643\u064e \u0648\u064e\u0648\u064e\u0639\u0652\u062f\u0650\u0643\u064e \u0645\u064e\u0627 \u0627\u0633\u0652\u062a\u064e\u0637\u064e\u0639\u0652\u062a\u064f \u060c \u0623\u064e\u0639\u064f\u0648\u0652\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0634\u064e\u0631\u0651\u0650 \u0645\u064e\u0627 \u0635\u064e\u0646\u064e\u0639\u0652\u062a\u064f \u060c \u0623\u064e\u0628\u064f\u0648\u0652\u0621\u064f \u0644\u064e\u0643\u064e \u0628\u0650\u0646\u0650\u0639\u0652\u0645\u062a\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u064a\u0651\u064e \u060c \u0648\u064e\u0623\u064e\u0628\u064f\u0648\u0652\u0621\u064f \u0628\u0650\u0630\u064e\u0646\u0652\u0628\u0650\u064a\u0652 \u0641\u064e\u0627\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u0650\u064a\u0652 \u060c \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064e\u063a\u0652\u0641\u0650\u0631\u064f \u0627\u0644\u0630\u0651\u064f\u0646\u064f\u0648\u0628\u064e \u0625\u0650\u0644\u0627\u0651\u064e \u0623\u064e\u0646\u0652\u062a\u064e",latin:"Allahumma anta rabb\u012b l\u0101 il\u0101ha ill\u0101 anta khalaqtan\u012b wa anna 'abduka wa an\u0101 'al\u0101 'ahdika wa wa'dika mastatha'tu a'\u016b\u017cu bika min syarri m\u0101 shana'tu ab\u016b u laka bini' matika 'alayya wa ab\u016b u bi\u017canb\u012b faghfir l\u012b fa innahu l\u0101 yaghfiru\u017c \u017cun\u016bba illa anta",translation:"Ya Allah, Engkau adalah Rabb-ku, tidak ada Ilah (yang berhak diibadahi dengan benar) kecuali Engkau, Engkau-lah yang menciptakanku. Aku adalah hamba-Mu. Aku akan setia pada perjanjianku dengan-Mu semampuku. Aku berlindung kepada-Mu dari kejelekan (apa) yang kuperbuat. Aku mengakui nikmat-Mu (yang diberikan) kepadaku dan aku mengakui dosaku, oleh karena itu, ampunilah aku. Sesungguhnya tidak ada yang dapat mengampuni dosa kecuali Engkau.",notes:"Dibaca 1x",fawaid:"Barang siapa yang membacanya dengan yakin ketika petang hari, kemudian dia meninggal, maka ia akan masuk surga, demikian juga jika (dibaca) pada pagi hari.",source:"HR. al-Bukhari No. 6306, 6323, Ahmad IV/122-125, an-Nasa'i VIII/279-280"},{title:"Doa Memohon Kesehatan dan Perlindungan",arabic:"\u0627\u064e\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0639\u064e\u0627\u0641\u0650\u0646\u0650\u064a\u0652 \u0641\u0650\u064a\u0652 \u0628\u064e\u062f\u064e\u0646\u0650\u064a\u0652 \u060c \u0627\u064e\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0639\u064e\u0627\u0641\u0650\u0646\u0650\u064a\u0652 \u0641\u0650\u064a\u0652 \u0633\u064e\u0645\u0652\u0639\u0650\u064a\u0652 \u060c \u0627\u064e\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0639\u064e\u0627\u0641\u0650\u0646\u0650\u064a\u0652 \u0641\u0650\u064a\u0652 \u0628\u064e\u0635\u064e\u0631\u0650\u064a\u0652 \u060c \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064e \u060c \u0627\u064e\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0650\u0651\u064a\u0652 \u0623\u064e\u0639\u064f\u0648\u0652\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0643\u064f\u0641\u0652\u0631\u0650\u0648\u064e\u0627\u0644\u0652\u0641\u064e\u0642\u0652\u0631\u0650 \u060c \u0648\u064e\u0623\u064e\u0639\u064f\u0648\u0652\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0627\u0644\u0652\u0642\u064e\u0628\u0652\u0631\u0650 \u060c \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064e",latin:"All\u0101humma '\u0101fin\u012b f\u012b badan\u012b, All\u0101humma '\u0101fin\u012b f\u012b sam'\u012b, All\u0101humma '\u0101fin\u012b f\u012b bashor\u012b, l\u0101 il\u0101ha ill\u0101 anta. All\u0101humma inni a'\u016b\u017cu bika minal kufri wal faqr, All\u0101humma inni a'\u016b\u017cu bika min 'a\u017c\u0101bil qobr, l\u0101 il\u0101ha ill\u0101 anta",translation:"Ya Allah, selamatkanlah tubuhku (dari penyakit dan dari apa yang tidak aku inginkan). Ya Allah, selamatkanlah pendengaranku (dari penyakit dan maksiat atau dari apa yang tidak aku inginkan). Ya Allah, selamatkanlah penglihatanku, tidak ada Ilah yang berhak diibadahi dengan benar kecuali Engkau. Ya Allah, sesungguhnya aku berlindung kepada-Mu dari kekufuran dan kefakiran. Aku berlindung kepada-Mu dari siksa kubur, tidak ada Ilah yang berhak diibadahi dengan benar kecuali Engkau.",notes:"Dibaca 1x",fawaid:"Dengan memohon kepada Allah agar memberi kita kesejahteraan dalam tubuh kita, kita memohon untuk disembuhkan dari semua penyakit jasmani dan rohani, sehingga kita memiliki tubuh yang sehat dan hati yang murni, dan oleh karena itu gunakanlah tubuh yang sehat ini dengan cara yang diridhai Allah.",source:"HR. al-Bukhari dalam Shahiib al-Adabil Mufrad No. 701, Abu Dawud No. 5090, Ahmad V/42, hasan"},{title:"Doa Memohon Keselamatan di Dunia dan Akhirat",arabic:"\u0627\u064e\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0625\u0650\u0646\u0650\u0651\u064a\u0652 \u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064e \u0627\u0644\u0652\u0639\u064e\u0641\u0652\u0648\u064e \u0648\u064e\u0627\u0644\u0652\u0639\u064e\u0627\u0641\u0650\u064a\u064e\u0629\u064e \u0641\u0650\u064a \u0627\u0644\u062f\u064f\u0651\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0627\u0652\u0644\u0622\u062e\u0650\u0631\u064e\u0629\u0650\u060c \u0627\u064e\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0625\u0650\u0646\u0650\u0651\u064a\u0652 \u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064e \u0627\u0644\u0652\u0639\u064e\u0641\u0652\u0648\u064e \u0648\u064e\u0627\u0644\u0652\u0639\u064e\u0627\u0641\u0650\u064a\u064e\u0629\u064e \u0641\u0650\u064a \u062f\u0650\u064a\u0652\u0646\u0650\u064a\u0652 \u0648\u064e\u062f\u064f\u0646\u0652\u064a\u064e\u0627\u064a\u064e \u0648\u064e\u0623\u064e\u0647\u0652\u0644\u0650\u064a\u0652 \u0648\u064e\u0645\u064e\u0627\u0644\u0650\u064a\u0652 \u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0627\u0633\u0652\u062a\u064f\u0631\u0652 \u0639\u064e\u0648\u0652\u0631\u064e\u0627\u062a\u0650\u0649 \u0648\u064e\u0622\u0645\u0650\u0646\u0652 \u0631\u064e\u0648\u0652\u0639\u064e\u0627\u062a\u0650\u0649. \u0627\u064e\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0627\u062d\u0652\u0641\u064e\u0638\u0652\u0646\u0650\u064a\u0652 \u0645\u0650\u0646\u0652 \u0628\u064e\u064a\u0652\u0646\u0650 \u064a\u064e\u062f\u064e\u064a\u064e\u0651\u060c \u0648\u064e\u0645\u0650\u0646\u0652 \u062e\u064e\u0644\u0652\u0641\u0650\u064a\u0652\u060c \u0648\u064e\u0639\u064e\u0646\u0652 \u064a\u064e\u0645\u0650\u064a\u0652\u0646\u0650\u064a\u0652 \u0648\u064e\u0639\u064e\u0646\u0652 \u0634\u0650\u0645\u064e\u0627\u0644\u0650\u064a\u0652\u060c \u0648\u064e\u0645\u0650\u0646\u0652 \u0641\u064e\u0648\u0652\u0642\u0650\u064a\u0652\u060c \u0648\u064e\u0623\u064e\u0639\u064f\u0648\u0652\u0630\u064f \u0628\u0650\u0639\u064e\u0638\u064e\u0645\u064e\u062a\u0650\u0643\u064e \u0623\u064e\u0646\u0652 \u0623\u064f\u063a\u0652\u062a\u064e\u0627\u0644\u064e \u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650\u064a\u0652",latin:"Allahumma inn\u012b as'alukal 'afwa wal '\u0101fiyah fid duny\u0101 wal \u0101khiroh. Allahumma inn\u012b as'alukal 'afwa wal '\u0101fiyah f\u012b d\u012bn\u012b wa dun y\u0101ya wa ahl\u012b wa m\u0101l\u012b. Allahumas tur 'awroot\u012b wa \u0101min row'\u0101t\u012b. Allahummahfazh n\u012b mim bayni yadayya wa min kholf\u012b wa 'an yam\u012bn\u012b wa 'an syim\u0101l\u012b wa min fawq\u012b wa a'u\u017cu bi 'azhomatik an ugh t\u0101la min taht\u012b",translation:"Ya Allah, sesungguhnya aku memohon kebajikan dan keselamatan di dunia dan akhirat. Ya Allah, sesungguhnya aku memohon kebajikan dan keselamatan dalam agama, dunia, keluarga dan hartaku. Ya Allah, tutupilah auratku (aib dan sesuatu yang tidak layak dilihat orang) dan tenteramkanlah aku dari rasa takut. Ya Allah, peliharalah aku dari muka, belakang, kanan, kiri dan atasku. Aku berlindung dengan kebesaran-Mu, agar aku tidak disambar dari bawahku (oleh ular atau tenggelam dalam bumi dan lain-lain yang membuat aku jatuh).",notes:"Dibaca 1x",fawaid:"Rasulullah shallallahu 'alaihi wa sallam tidaklah pernah meninggalkan do'a ini di pagi dan petang hari. Di dalamnya berisi perlindungan keselamatan pada agama, dunia, keluarga dan harta dari berbagai macam gangguan yang datang dari berbagai arah.",source:"HR. al-Bukhari dalam al-Abadul Mufrad No. 1200, Abu Dawud No. 5074, an-Nasa'i VII/282, Ibnu Majah No. 3871, al-Hakim 1/517-518, dan lainnya dari Ibnu Umar radhiyallahu 'anhumaa"},{title:"Doa Memohon Perlindungan dari Bisikan Syaitan",arabic:"\u0627\u064e\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0639\u064e\u0627\u0644\u0650\u0645\u064e \u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u0650 \u0648\u064e\u0627\u0644\u0634\u064e\u0651\u0647\u064e\u0627\u062f\u064e\u0629\u0650 \u0641\u064e\u0627\u0637\u0650\u0631\u064e \u0627\u0644\u0633\u064e\u0651\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0652\u0644\u0623\u064e\u0631\u0652\u0636\u0650\u060c \u0631\u064e\u0628\u064e\u0651 \u0643\u064f\u0644\u0650\u0651 \u0634\u064e\u064a\u0652\u0621\u064d \u0648\u064e\u0645\u064e\u0644\u0650\u064a\u0652\u0643\u064e\u0647\u064f\u060c \u0623\u064e\u0634\u0652\u0647\u064e\u062f\u064f \u0623\u064e\u0646\u0652 \u0644\u0627\u064e \u0625\u0650\u0644\u064e\u0640\u0647\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0623\u064e\u0646\u0652\u062a\u064e\u060c \u0623\u064e\u0639\u064f\u0648\u0652\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0634\u064e\u0631\u0650\u0651 \u0646\u064e\u0641\u0652\u0633\u0650\u064a\u0652\u060c \u0648\u064e\u0645\u0650\u0646\u0652 \u0634\u064e\u0631\u0650\u0651 \u0627\u0644\u0634\u064e\u0651\u064a\u0652\u0637\u064e\u0627\u0646\u0650 \u0648\u064e\u0634\u0650\u0631\u0652\u0643\u0650\u0647\u0650\u060c \u0648\u064e\u0623\u064e\u0646\u0652 \u0623\u064e\u0642\u0652\u062a\u064e\u0631\u0650\u0641\u064e \u0639\u064e\u0644\u064e\u0649 \u0646\u064e\u0641\u0652\u0633\u0650\u064a\u0652 \u0633\u064f\u0648\u0652\u0621\u064b\u0627 \u0623\u064e\u0648\u0652 \u0623\u064e\u062c\u064f\u0631\u064e\u0651\u0647\u064f \u0625\u0650\u0644\u064e\u0649 \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064d",latin:"Allahumma '\u0101limal ghoybi wasy syah\u0101dah f\u0101thiros sam\u0101w\u0101ti wal ardh. Robba kulli syai in wa mal\u012bkah. Asyhadu alla ilaha illa anta. A'u\u017cu bika min syarri nafs\u012b wa min syarrisy syaythooni wa syirkihi, wa an aqtarifa 'al\u0101 nafs\u012b s\u016b an aw ajurrohu il\u0101 muslim",translation:"Ya Allah, Yang Maha Mengetahui yang ghaib dan yang nyata, wahai Rabb pencipta langit dan bumi, Rabb segala sesuatu dan yang merajainya. Aku bersaksi bahwa tidak ada ilah yang berhak disembah kecuali Engkau. Aku berlindung kepada-Mu dari kejahatan diriku, setan dan balatentaranya (godaan untuk berbuat syirik pada Allah), dan aku (berlindung kepada-Mu) dari berbuat kejelekan terhadap diriku atau menyeretnya kepada seorang muslim.",notes:"Dibaca 1x",fawaid:"Rasulullah shallallahu 'alaihi wa sallam bersabda kepada Abu Bakar ash-Shiddiq radhiyallahu 'anhu \"Ucapkanlah pagi dan petang dan apabila engkau hendak tidur\".",source:"HR. al-Bukhari dalam al-Abadul Mufrad No. 1202, at-Tirmidzi No. 3392 dan Abu Dawud No. 5067"},{title:"Dzikir Agar Terhindar dari Semua Bahaya",arabic:"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0627\u0644\u064e\u0651\u0630\u0650\u0649 \u0644\u0627\u064e \u064a\u064e\u0636\u064f\u0631\u064f\u0651 \u0645\u064e\u0639\u064e \u0627\u0633\u0652\u0645\u0650\u0647\u0650 \u0634\u064e\u0649\u0652\u0621\u064c \u0641\u0650\u0649 \u0627\u0644\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0644\u0627\u064e \u0641\u0650\u0649 \u0627\u0644\u0633\u064e\u0651\u0645\u064e\u0627\u0621\u0650 \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0633\u064e\u0651\u0645\u0650\u064a\u0639\u064f \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0645\u064f",latin:"Bismillahilla\u017ci l\u0101 yadhurru ma'asmihi syai un fil ardhi wa l\u0101 fis sam\u0101' wa huwas sam\u012b'ul 'al\u012bm",translation:"Dengan nama Allah yang bila disebut, segala sesuatu di bumi dan langit tidak akan berbahaya, Dia-lah Yang Maha Mendengar lagi Maha Mengetahui.",notes:"Dibaca 3x",fawaid:"Barang siapa membacanya sebanyak tiga kali ketika pagi dan sore hari, maka tidak ada sesuatu pun yang membahayakan dirinya.",source:"HR. at-Tirmidzi No. 3388, Abu Dawud No. 5088, Ibnu Majah No. 3869, al-Hakim 1/514, dan Ahmad No. 446 dan 474"},{title:"Pernyataan Keridhaan dengan Allah, Islam, dan Nabi Muhammad Shallallaahu 'Alaihi Wa Sallam",arabic:"\u0631\u064e\u0636\u0650\u064a\u0652\u062a\u064f \u0628\u0650\u0627\u0644\u0644\u0647\u0650 \u0631\u064e\u0628\u064b\u0651\u0627\u060c \u0648\u064e\u0628\u0650\u0627\u0652\u0644\u0625\u0650\u0633\u0652\u0644\u0627\u064e\u0645\u0650 \u062f\u0650\u064a\u0652\u0646\u064b\u0627\u060c \u0648\u064e\u0628\u0650\u0645\u064f\u062d\u064e\u0645\u064e\u0651\u062f\u064d \u0635\u064e\u0644\u064e\u0651\u0649 \u0627\u0644\u0644\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0648\u064e\u0633\u064e\u0644\u064e\u0651\u0645\u064e \u0646\u064e\u0628\u0650\u064a\u064b\u0651\u0627",latin:"Rodh\u012btu bill\u0101hi robb\u0101 wa bil isl\u0101mi d\u012bn\u0101, wa bi muhammadin shallall\u0101hu 'alaihi wa sallama nabiyy\u0101",translation:"Aku ridha Allah sebagai Rabb, Islam sebagai agama dan Muhammad shallallahu 'alaihi wa sallam sebagai nabi.",notes:"Dibaca 3x",fawaid:"Barang siapa membacanya sebanyak tiga kali ketika pagi dan sore, maka Allah memberikan keridhaan-Nya kepadanya pada hari kiamat.",source:"HR. Ahmad IV/337, Abu Dawud No. 5072, at-Tirmidzi No. 3389, Ibnu Majah No. 3870, an-Nasa'i dalam 'Amalul Yaum wal Lailah No. 4 dan Ibnus Sunni No. 68"},{title:"Meminta Petunjuk Kepada Allah",arabic:"\u064a\u064e\u0627 \u062d\u064e\u064a\u064f\u0651 \u064a\u064e\u0627 \u0642\u064e\u064a\u064f\u0651\u0648\u0652\u0645\u064f \u0628\u0650\u0631\u064e\u062d\u0652\u0645\u064e\u062a\u0650\u0643\u064e \u0623\u064e\u0633\u0652\u062a\u064e\u063a\u0650\u064a\u0652\u062b\u064f\u060c \u0648\u064e\u0623\u064e\u0635\u0652\u0644\u0650\u062d\u0652 \u0644\u0650\u064a\u0652 \u0634\u064e\u0623\u0652\u0646\u0650\u064a\u0652 \u0643\u064f\u0644\u064e\u0651\u0647\u064f \u0648\u064e\u0644\u0627\u064e \u062a\u064e\u0643\u0650\u0644\u0652\u0646\u0650\u064a\u0652 \u0625\u0650\u0644\u064e\u0649 \u0646\u064e\u0641\u0652\u0633\u0650\u064a\u0652 \u0637\u064e\u0631\u0652\u0641\u064e\u0629\u064e \u0639\u064e\u064a\u0652\u0646\u064d \u0623\u064e\u0628\u064e\u062f\u064b\u0627",latin:"Y\u0101 hayyu y\u0101 qoyyum, bi rohmatika as tagh\u012b\u1e61, wa ash lih l\u012b sya'n\u012b kullahu wa l\u0101 takiln\u012b il\u0101 nafs\u012b thorfata 'ainin abadan",translation:"Wahai Rabb Yang Maha Hidup, wahai Rabb Yang Berdiri Sendiri (tidak butuh segala sesuatu), dengan rahmat-Mu aku minta pertolongan, perbaikilah segala urusanku dan jangan diserahkan kepadaku sekali pun sekejap mata (tanpa mendapat pertolongan dari-Mu).",notes:"Dibaca 1x",fawaid:"Maksud dari do'a ini adalah manusia sangat butuh Allah dan berdo'a agar Allah tidak meninggalkannya walaupun sekejap saja.",source:"HR. an-Nasa'i dalam 'Amalul Yaum wal Lailah No. 575, dan al-Hakim 1/545, lihat Shahiih at-Targhiib wat Tarhiib 1/417 No. 661, Ash-shahiihah No. 227, hasan"},{title:"Memasuki Sore di atas Fitrah Islam",arabic:"\u0623\u064e\u0645\u0652\u0633\u064e\u064a\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0641\u0650\u0637\u0652\u0631\u064e\u0629\u0650 \u0627\u0652\u0644\u0625\u0650\u0633\u0652\u0644\u0627\u064e\u0645\u0650 \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0643\u064e\u0644\u0650\u0645\u064e\u0629\u0650 \u0627\u0652\u0644\u0625\u0650\u062e\u0652\u0644\u0627\u064e\u0635\u0650\u060c \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u062f\u0650\u064a\u0652\u0646\u0650 \u0646\u064e\u0628\u0650\u064a\u0650\u0651\u0646\u064e\u0627 \u0645\u064f\u062d\u064e\u0645\u0651\u064e\u062f\u064d \u0635\u064e\u0644\u0651\u064e\u0649 \u0627\u0644\u0644\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0648\u064e\u0633\u064e\u0644\u0651\u064e\u0645\u064e\u060c \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0645\u0650\u0644\u0651\u064e\u0629\u0650 \u0623\u064e\u0628\u0650\u064a\u0652\u0646\u064e\u0627 \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0652\u0645\u064e\u060c \u062d\u064e\u0646\u0650\u064a\u0652\u0641\u064b\u0627 \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064b\u0627 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0634\u0652\u0631\u0650\u0643\u0650\u064a\u0652\u0646\u064e",latin:"Amsayn\u0101 'ala fithrotil isl\u0101m wa 'al\u0101 kalimatil ikhl\u0101sh, wa 'al\u0101 d\u012bni nabiyyin\u0101 Muhammadin shallallahu 'alaihi wa sallam, wa 'al\u0101 millati ab\u012bna Ibr\u0101h\u012bma han\u012bfam muslim\u0101w wa m\u0101 k\u0101na minal musyrikin",translation:"Di waktu sore kami di atas fithrah agama Islam, kalimat ikhlas (kalimat syahadat), agama Nabi kami Muhammad shallallahu 'alaihi wa sallam, dan agama bapak kami Ibrahim, yang berdiri di atas jalan yang lurus, muslim dan tidak tergolong orang-orang musyrik.",notes:"Dibaca 1x",fawaid:"'Fitratil Islam' maksudnya di atas sunnah, 'kalimatil ikhlas' maksudnya adalah kalimat syahadat dan 'hanifan' maksudnya adalah hati yang condong kepada jalan yang lurus dan kebaikan.",source:"HR. Ahmad III/406, 407, ad-Darimi II/292 dan Ibnus Sunni dalam Amalul Yaum wal Lailah No. 34, Misykaatul Mashaabiih No. 2415, Shahiihal-Jaami'ish Shaghiir No. 4674, shahih"},{title:"Dzikir Tauhid",arabic:"\u0644\u0627\u064e \u0625\u0650\u0644\u064e\u0640\u0647\u064e \u0625\u0650\u0644\u0627\u0651\u064e \u0627\u0644\u0644\u0647\u064f \u0648\u064e\u062d\u0652\u062f\u064e\u0647\u064f \u0644\u0627\u064e \u0634\u064e\u0631\u0650\u064a\u0652\u0643\u064e \u0644\u064e\u0647\u064f\u060c \u0644\u064e\u0647\u064f \u0627\u0644\u0652\u0645\u064f\u0644\u0652\u0643\u064f \u0648\u064e\u0644\u064e\u0647\u064f \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0648\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u0649 \u0643\u064f\u0644\u0650\u0651 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0652\u0631\u064f",latin:"L\u0101 il\u0101ha ill\u0101ll\u0101h wa\u1e25dahu l\u0101 syar\u012bka lah, lahul mulku walahul \u1e25amdu wa huwa 'al\u0101 kulli syai'in qad\u012br",translation:"Tidak ada ilah yang berhak disembah selain Allah semata, tidak ada sekutu bagiNya. Bagi-Nya kerajaan dan segala pujian. Dia-lah yang berkuasa atas segala sesuatu",notes:"Dibaca 1x atau 10x di pagi hari, Dibaca 100x dalam sehari",fawaid:"Barang siapa yang mengucapkan dzikir tersebut dalam sehari sebanyak 100x, maka itu seperti membebaskan 10 orang budak, dicatat baginya 100 kebaikan, dihapus baginya 100 kesalahan, dirinya akan terjaga dari gangguan setan dari pagi hingga petang hari, dan tidak ada seorang pun yang lebih baik dari yang ia lakukan kecuali oleh orang yang mengamalkan lebih dari itu.",source:"HR al-Bukhari No. 3293 dan 6403, Muslim IV/2071 No. 2691 (28), at-Tirmidzi No. 3468, Ibnu Majah No. 3798"},{title:"Membaca Tasbih kepada Allah",arabic:"\u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0647\u0650 \u0648\u064e\u0628\u0650\u062d\u064e\u0645\u0652\u062f\u0650\u0647\u0650 \u0639\u064e\u062f\u064e\u062f\u064e \u062e\u064e\u0644\u0652\u0642\u064e\u0647\u0650 \u0648\u064e\u0631\u0650\u0636\u064e\u0649 \u0646\u064e\u0641\u0652\u0633\u0650\u0647\u0650 \u0648\u064e\u0632\u0650\u0646\u064e\u0629\u064e \u0639\u064e\u0631\u0652\u0634\u0650\u0647\u0650 \u0648\u064e\u0645\u0650\u062f\u064e\u0627\u062f\u064e \u0643\u064e\u0644\u0650\u0645\u064e\u0627\u062a\u0650\u0647\u0650",latin:"Subhanallahi wa bihamdihi 'adada khalqihi wa ridha nafsihi wa zinata 'arsyihi wa midada kalimatihi",translation:"Maha Suci Allah, sebanyak makhluk-Nya, Maha Suci Allah sejauh kerelaan-Nya, Maha Suci Allah seberat timbangan 'Arsy-Nya, dan sebanyak tinta tulisan kalimat-Nya.",notes:"Dibaca 3x",fawaid:"Nabi shallallahu 'alaihi wa sallam mengatakan pada Juwairiyah bahwa dzikir di atas telah mengalahkan dzikir yang dibaca oleh Juwairiyah dari selepas Shubuh sampai waktu Dhuha.",source:"HR. Muslim No. 2726. Syarah Muslim XVII/44. Dari Juwairiyah binti al-Harits radhiyallahu 'anhuma"},{title:"Tasbih dan Tahmid Harian",arabic:"\u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0648\u064e\u0628\u0650\u062d\u064e\u0645\u0652\u062f\u0650\u0647\u0650",latin:"Subh\u0101nallahi wa bihamdihi",translation:"Maha Suci Allah, aku memuji-Nya",notes:"Dibaca 100x",fawaid:"Barang siapa yang mengucapkan kalimat 'subhanallah wa bi hamdih' di pagi dan petang hari sebanyak 100x, maka tidak ada yang datang pada hari kimata yang lebih baik dari yang ia lakukan kecuali orang yang mengucapkan semisal atau lebih dari itu.",source:"HR. Muslim No. 2691 dan No. 2692, dari Abu Hurairah radhiyallahu 'anhu Syarah Muslim XVII/17-18, Shahiih at-Targhiib wat Tarhiib 1/413 No. 653"},{title:"Istighfar 100x Sehari",arabic:"\u0623\u064e\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u064f \u0627\u0644\u0644\u0647 \u0648\u064e\u0623\u064e\u062a\u064f\u0648\u0652\u0628\u064f \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650",latin:"Astaghfirullah wa at\u016bbu ilaih",translation:"Aku memohon ampunan kepada Allah dan bertaubat kepada-Nya",notes:"Dibaca 100x sehari",fawaid:"Dari Ibnu 'Umar ia berkata: Rasulullah shallallahu 'alaihi wa sallam bersabda: 'Wahai manusia, bertaubatlah kalian kepada Allah, sesungguhnya aku bertaubat kepada-Nya dalam sehari seratus kali'.",source:"HR. al-Bukhari/Fat-hul Baari XI/101 dan Muslim No. 2702"},{title:"Doa Memohon Perlindungan dari Keburukan Ciptaan Allah",arabic:"\u0623\u064e\u0639\u064f\u0648\u0652\u0630\u064f \u0628\u0650\u0643\u064e\u0644\u0650\u0645\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0647\u0650 \u0627\u0644\u062a\u0651\u064e\u0622\u0645\u0651\u064e\u0627\u062a\u0650 \u0645\u0650\u0646\u0652 \u0634\u064e\u0631\u0651\u0650 \u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u064e",latin:"'au\u017cu bi kalim\u0101tillahitt\u0101m\u0101ti min syarri ma khalaq",translation:"Aku berlindung dengan kalimat-kalimat Allah yang sempurna, dari kejahatan sesuatu yang diciptakan-Nya.",notes:"Dibaca 3x",fawaid:"Barang siapa yang membacanya pada petang hari tiga kali, maka dia tidak akan tertimpa demam pada malam itu.",source:"HR. Ahmad 11/290, an-Nasa'i dalam 'Amalul Yaum wal Lailah No. 596, Shahiih at-Targhiib wat Tarhiib 1/412 No. 652, Shahiih al-Jaami 'ish Shaghiir No. 6427"}]},1278,[]);
__d(function(a,i,n,l,u,h,d){u.exports=[{title:"Ayat al-Kursi",arabic:"\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u0671\u0644\u0652\u062d\u064e\u0649\u0651\u064f \u0671\u0644\u0652\u0642\u064e\u064a\u0651\u064f\u0648\u0645\u064f \u06da \u0644\u064e\u0627 \u062a\u064e\u0623\u0652\u062e\u064f\u0630\u064f\u0647\u064f\u06e5 \u0633\u0650\u0646\u064e\u0629\u064c \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0648\u0652\u0645\u064c \u06da \u0644\u0651\u064e\u0647\u064f\u06e5 \u0645\u064e\u0627 \u0641\u0650\u0649 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u0649 \u0671\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d7 \u0645\u064e\u0646 \u0630\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u0649 \u064a\u064e\u0634\u0652\u0641\u064e\u0639\u064f \u0639\u0650\u0646\u062f\u064e\u0647\u064f\u06e5\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0625\u0650\u0630\u0652\u0646\u0650\u0647\u0650\u06e6 \u06da \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u0652\u0641\u064e\u0647\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u064a\u0637\u064f\u0648\u0646\u064e \u0628\u0650\u0634\u064e\u0649\u0652\u0621\u064d \u0645\u0651\u0650\u0646\u0652 \u0639\u0650\u0644\u0652\u0645\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0645\u064e\u0627 \u0634\u064e\u0627\u0653\u0621\u064e \u06da \u0648\u064e\u0633\u0650\u0639\u064e \u0643\u064f\u0631\u0652\u0633\u0650\u064a\u0651\u064f\u0647\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u06d6 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0640\u0654\u064f\u0648\u062f\u064f\u0647\u064f\u06e5 \u062d\u0650\u0641\u0652\u0638\u064f\u0647\u064f\u0645\u064e\u0627 \u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u0652\u0639\u064e\u0644\u0650\u0649\u0651\u064f \u0671\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u064f",latin:"All\u0101hu l\u0101 il\u0101ha ill\u0101 huwal\u1e25ayyul qayy\u1ee5m, l\u0101 ta`khu\u017cuh\u1ee5 sinatuw wa l\u0101 na`\u1ee5m, lah\u1ee5 m\u0101 fis sam\u0101w\u0101ti wa m\u0101 fil ar\u1e0d, man \u017calla\u017c\u012b yasyfa'u 'indah\u016b ill\u0101 bi`i\u017cnih, ya'lamu m\u0101 baina aid\u012bhim wa m\u0101 khalfahum, wa l\u0101 yu\u1e25\u012b\u1e6d\u1ee5na bisyai`im min 'ilmih\u012b ill\u0101 bim\u0101 sy\u0101`, wasi'a kursiyyuhus sam\u0101w\u0101ti wal ar\u1e0d, wa l\u0101 ya`\u1ee5duh\u1ee5 \u1e25if\u1e93uhum\u0101, wa huwal 'aliyyul 'a\u1e93\u012bm",translation:"Allah, tidak ada Tuhan (yang berhak disembah) melainkan Dia Yang Hidup kekal lagi terus menerus mengurus (makhluk-Nya); tidak mengantuk dan tidak tidur. Kepunyaan-Nya apa yang di langit dan di bumi. Tiada yang dapat memberi syafa'at di sisi Allah tanpa izin-Nya? Allah mengetahui apa-apa yang di hadapan mereka dan di belakang mereka, dan mereka tidak mengetahui apa-apa dari ilmu Allah melainkan apa yang dikehendaki-Nya. Kursi Allah meliputi langit dan bumi. Dan Allah tidak merasa berat memelihara keduanya, dan Allah Maha Tinggi lagi Maha Besar.",notes:"Dibaca 1x",fawaid:"Barang siapa yang membaca ayat ini ketika pagi, maka ia akan dilindungi hingga petang. Dan barang siapa yang membacanya ketika petang, maka ia akan dilindungi hingga pagi.",source:"HR. at-Tirmidzi: 2879"},{title:"Al-Ikhlas",arabic:"\u0642\u064f\u0644\u0652 \u0647\u064f\u0648\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u062d\u064e\u062f\u064c (1) \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0635\u0651\u064e\u0645\u064e\u062f\u064f (2) \u0644\u064e\u0645\u0652 \u064a\u064e\u0644\u0650\u062f\u0652 \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064f\u0648\u0644\u064e\u062f\u0652 (3) \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0643\u064f\u0646 \u0644\u0651\u064e\u0647\u064f\u06e5 \u0643\u064f\u0641\u064f\u0648\u064b\u0627 \u0623\u064e\u062d\u064e\u062f\u064c\u06e2 (4)",latin:"Qul huwall\u0101hu a\u1e25ad (1) All\u0101hu\u1e63 \u1e63amad (2) lam yalid wa lam y\u1ee5lad (3) wa lam yakul lah\u1ee5 kufuwan a\u1e25ad (4)",translation:"Katakanlah: \"Dialah Allah, Yang Maha Esa. Allah adalah Tuhan yang bergantung kepada-Nya segala sesuatu. Dia tiada beranak dan tidak pula diperanakkan, dan tidak ada seorangpun yang setara dengan Dia\".",notes:"Dibaca 3x",fawaid:"Rasulullah shallallahu 'alaihi wa sallam bersabda: Katakanlah (bacalah surat), Qulhuwallahu ahad, dan Al-Muawwidzatain (Al-Falaq dan An-Naas) ketika petang dan pagi tiga kali, maka dengan ayat ini akan mencukupkanmu (menjagamu) dari segala sesuatu.",source:"HR. Abu Dawud No. 4241"},{title:"Al-Falaq",arabic:"\u0642\u064f\u0644\u0652 \u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0631\u064e\u0628\u0651\u0650 \u0671\u0644\u0652\u0641\u064e\u0644\u064e\u0642\u0650 (1) \u0645\u0650\u0646 \u0634\u064e\u0631\u0651\u0650 \u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u064e (2) \u0648\u064e\u0645\u0650\u0646 \u0634\u064e\u0631\u0651\u0650 \u063a\u064e\u0627\u0633\u0650\u0642\u064d \u0625\u0650\u0630\u064e\u0627 \u0648\u064e\u0642\u064e\u0628\u064e (3) \u0648\u064e\u0645\u0650\u0646 \u0634\u064e\u0631\u0651\u0650 \u0671\u0644\u0646\u0651\u064e\u0641\u0651\u064e\u0670\u062b\u064e\u0670\u062a\u0650 \u0641\u0650\u0649 \u0671\u0644\u0652\u0639\u064f\u0642\u064e\u062f\u0650 (4) \u0648\u064e\u0645\u0650\u0646 \u0634\u064e\u0631\u0651\u0650 \u062d\u064e\u0627\u0633\u0650\u062f\u064d \u0625\u0650\u0630\u064e\u0627 \u062d\u064e\u0633\u064e\u062f\u064e (5)",latin:"Qul a'\u1ee5\u017cu birabbil falaq (1) min syarri m\u0101 khalaq (2) wa min syarri g\u0101siqin i\u017c\u0101 waqab (3) wa min syarrin naff\u0101\u1e61\u0101ti fil 'uqad (4) wa min syarri \u1e25\u0101sidin i\u017c\u0101 \u1e25asad (5)",translation:"Katakanlah: \"Aku berlindung kepada Tuhan Yang Menguasai subuh, dari kejahatan makhluk-Nya, dan dari kejahatan malam apabila telah gelap gulita, dan dari kejahatan wanita-wanita tukang sihir yang menghembus pada buhul-buhul, dan dari kejahatan pendengki bila ia dengki\".",notes:"Dibaca 3x",fawaid:"Rasulullah shallallahu 'alaihi wa sallam bersabda: Katakanlah (bacalah surat), Qulhuwallahu ahad, dan Al-Muawwidzatain (Al-Falaq dan An-Naas) ketika petang dan pagi tiga kali, maka dengan ayat ini akan mencukupkanmu (menjagamu) dari segala sesuatu.",source:"HR. Abu Dawud No. 4241"},{title:"An-Naas",arabic:"\u0642\u064f\u0644\u0652 \u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0631\u064e\u0628\u0651\u0650 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 (1) \u0645\u064e\u0644\u0650\u0643\u0650 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 (2) \u0625\u0650\u0644\u064e\u0670\u0647\u0650 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 (3) \u0645\u0650\u0646 \u0634\u064e\u0631\u0651\u0650 \u0671\u0644\u0652\u0648\u064e\u0633\u0652\u0648\u064e\u0627\u0633\u0650 \u0671\u0644\u0652\u062e\u064e\u0646\u0651\u064e\u0627\u0633\u0650 (4) \u0671\u0644\u0651\u064e\u0630\u0650\u0649 \u064a\u064f\u0648\u064e\u0633\u0652\u0648\u0650\u0633\u064f \u0641\u0650\u0649 \u0635\u064f\u062f\u064f\u0648\u0631\u0650 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 (5) \u0645\u0650\u0646\u064e \u0671\u0644\u0652\u062c\u0650\u0646\u0651\u064e\u0629\u0650 \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 (6)",latin:"Qul a'\u1ee5\u017cu birabbin n\u0101s (1) malikin n\u0101s (2) il\u0101hin n\u0101s (3) min syarril wasw\u0101sil khann\u0101s (4) alla\u017c\u012b yuwaswisu f\u012b \u1e63ud\u1ee5rin n\u0101s (5) minal jinnati wan n\u0101s (6)",translation:"Katakanlah: \u201cAku berlindung kepada Tuhan (yang memelihara dan menguasai) manusia. (1) Raja manusia. (2) Sembahan manusia. (3) Dari kejahatan (bisikan) syaitan yang biasa bersembunyi, (4) yang membisikkan (kejahatan) ke dalam dada manusia, (5) dari (golongan) jin dan manusia. (6)",notes:"Dibaca 3x",fawaid:"Rasulullah shallallahu 'alaihi wa sallam bersabda: Katakanlah (bacalah surat), Qulhuwallahu ahad, dan Al-Muawwidzatain (Al-Falaq dan An-Naas) ketika petang dan pagi tiga kali, maka dengan ayat ini akan mencukupkanmu (menjagamu) dari segala sesuatu.",source:"HR. Abu Dawud No. 4241"},{title:"Memasuki Pagi dalam Kerajaan Allah dan Memohon Perlindungan dari-Nya",arabic:"\u0623\u064e\u0635\u0652\u0628\u064e\u062d\u0652\u0646\u064e\u0627 \u0648\u064e\u0623\u064e\u0635\u0652\u0628\u064e\u062d\u064e \u0627\u0644\u0652\u0645\u064f\u0644\u0652\u0643\u064f \u0644\u0650\u0644\u064e\u0651\u0647\u0650\u060c \u0648\u064e\u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u064e\u0651\u0647\u0650\u060c \u0644\u0627\u064e \u0625\u0650\u0644\u064e\u0640\u0647\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0627\u0644\u0644\u0647\u064f \u0648\u064e\u062d\u0652\u062f\u064e\u0647\u064f \u0644\u0627\u064e \u0634\u064e\u0631\u0650\u064a\u0652\u0643\u064e \u0644\u064e\u0647\u064f\u060c \u0644\u064e\u0647\u064f \u0627\u0644\u0652\u0645\u064f\u0644\u0652\u0643\u064f \u0648\u064e\u0644\u064e\u0647\u064f \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0648\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u0649 \u0643\u064f\u0644\u0650\u0651 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0652\u0631\u064f. \u0631\u064e\u0628\u0650\u0651 \u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064e \u062e\u064e\u064a\u0652\u0631\u064e \u0645\u064e\u0627 \u0641\u0650\u064a\u0652 \u0647\u064e\u0630\u064e\u0627 \u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u0650 \u0648\u064e\u062e\u064e\u064a\u0652\u0631\u064e \u0645\u064e\u0627 \u0628\u064e\u0639\u0652\u062f\u064e\u0647\u064f\u060c \u0648\u064e\u0623\u064e\u0639\u064f\u0648\u0652\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0634\u064e\u0631\u0650\u0651 \u0645\u064e\u0627 \u0641\u0650\u064a\u0652 \u0647\u064e\u0630\u064e\u0627 \u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u0650 \u0648\u064e\u0634\u064e\u0631\u0650\u0651 \u0645\u064e\u0627 \u0628\u064e\u0639\u0652\u062f\u064e\u0647\u064f\u060c \u0631\u064e\u0628\u0650\u0651 \u0623\u064e\u0639\u064f\u0648\u0652\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0643\u064e\u0633\u064e\u0644\u0650 \u0648\u064e\u0633\u064f\u0648\u0652\u0621\u0650 \u0627\u0644\u0652\u0643\u0650\u0628\u064e\u0631\u0650\u060c \u0631\u064e\u0628\u0650\u0651 \u0623\u064e\u0639\u064f\u0648\u0652\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064d \u0641\u0650\u064a \u0627\u0644\u0646\u064e\u0651\u0627\u0631\u0650 \u0648\u064e\u0639\u064e\u0630\u064e\u0627\u0628\u064d \u0641\u0650\u064a \u0627\u0644\u0652\u0642\u064e\u0628\u0652\u0631\u0650",latin:"A\u1e63ba\u1e25n\u0101 wa a\u1e63ba\u1e25al mulku lill\u0101h wal\u1e25amdu lill\u0101h, l\u0101 il\u0101ha ill\u0101ll\u0101h wa\u1e25dahu l\u0101 syar\u012bka lah, lahul mulku walahul \u1e25amdu wa huwa 'al\u0101 kulli syai'in qad\u012br. Rabb\u012b as'aluka khaira m\u0101 f\u012b h\u0101\u017cal yaum wa khaira m\u0101 ba'dahu, wa a'\u016b\u017cu bika min syarri m\u0101 f\u012b h\u0101\u017cal yaum wa syarri m\u0101 ba'dahu. Rabb\u012b a'\u016b\u017cu bika minal kasali wa s\u016b'il kibar. Rabb\u012b a'\u016b\u017cu bika min 'a\u017c\u0101bin fin n\u0101ri wa 'a\u017c\u0101bin fil qobri",translation:"Kami telah memasuki waktu pagi dan kerajaan hanya milik Allah, segala puji bagi Allah. Tidak ada ilah (yang berhak disembah) kecuali Allah semata, tiada sekutu bagi-Nya. Milik Allah kerajaan dan bagi-Nya pujian. Dia-lah Yang Mahakuasa atas segala sesuatu. Wahai Rabbku, aku mohon kepada-Mu kebaikan di hari ini dan kebaikan sesudahnya. Aku berlindung kepada-Mu dari kejahatan hari ini dan kejahatan sesudahnya. Wahai Rabbku, aku berlindung kepada-Mu dari kemalasan dan kejelekan di hari tua. Wahai Rabbku, aku berlindung kepada-Mu dari siksaan di neraka dan siksaan di alam kubur.",notes:"Dibaca 1x",fawaid:"Memohon perlindungan dari kejahatan lebih diutamakan, kaidah yang menunjukkan pentingnya hal tersebut adalah: \"Mencegah bahaya lebih penting dan didahulukan daripada mendatangkan kebaikan\".",source:"HR. Muslim No. 2723 (75), Abu Dawud No. 5071, dan at-Tirmidzi 3390, shahih dari Abdullah Ibnu Mas'ud"},{title:"Memasuki Pagi dengan Memohon Rahmat Allah",arabic:"\u0627\u064e\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0628\u0650\u0643\u064e \u0623\u064e\u0635\u0652\u0628\u064e\u062d\u0652\u0646\u064e\u0627\u060c \u0648\u064e\u0628\u0650\u0643\u064e \u0623\u064e\u0645\u0652\u0633\u064e\u064a\u0652\u0646\u064e\u0627\u060c \u0648\u064e\u0628\u0650\u0643\u064e \u0646\u064e\u062d\u0652\u064a\u064e\u0627\u060c \u0648\u064e\u0628\u0650\u0643\u064e \u0646\u064e\u0645\u064f\u0648\u0652\u062a\u064f \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0627\u0644\u0646\u064f\u0651\u0634\u064f\u0648\u0652\u0631\u064f",latin:"Allahumma bika ash bahn\u0101 wa bika amsayn\u0101 wa bika nahy\u0101 wa bika nam\u016btu wa ilaikan nusy\u016br",translation:"Ya Allah, dengan rahmat dan pertolongan-Mu kami memasuki waktu pagi, dan dengan rahmat dan pertolongan-Mu kami memasuki waktu petang. Dengan rahmat dan pertolongan-Mu kami hidup dan dengan kehendak-Mu kami mati. Dan kepada-Mu kebangkitan (bagi semua makhluk).",notes:"Dibaca 1x",fawaid:"Setiap hal yang kita lakukan dari pagi sampai petang, dari kita memulai kehidupan kita sampai kita mati, semuanya berada dibawah kendali Allah dan kepada-Nya lah kita kembali.",source:"HR. al-Bukhari dalam al-Abadul Mufrad No. 1199, lafadz ini adalah lafadz al-Bukhari, at-Tirmidzi No. 3391, Abu Dawud No. 5068, Ahmad 11/354, Ibnu Majah No. 3868"},{title:"Sayyid al-Istighfar",arabic:"\u0627\u064e\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0623\u064e\u0646\u0652\u062a\u064e \u0631\u064e\u0628\u0651\u0650\u064a\u0652 \u060c \u0644\u064e\u0627 \u0625\u0650\u0644\u0670\u0640\u0647\u064e \u0625\u0650\u0644\u0627\u0651\u064e \u0623\u064e\u0646\u0652\u062a\u064e \u062e\u064e\u0644\u064e\u0642\u0652\u062a\u064e\u0646\u0650\u064a\u0652 \u0648\u064e\u0623\u064e\u0646\u064e\u0627 \u0639\u064e\u0628\u0652\u062f\u064f\u0643\u064e \u060c \u0648\u064e\u0623\u064e\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0639\u064e\u0647\u0652\u062f\u0650\u0643\u064e \u0648\u064e\u0648\u064e\u0639\u0652\u062f\u0650\u0643\u064e \u0645\u064e\u0627 \u0627\u0633\u0652\u062a\u064e\u0637\u064e\u0639\u0652\u062a\u064f \u060c \u0623\u064e\u0639\u064f\u0648\u0652\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0634\u064e\u0631\u0651\u0650 \u0645\u064e\u0627 \u0635\u064e\u0646\u064e\u0639\u0652\u062a\u064f \u060c \u0623\u064e\u0628\u064f\u0648\u0652\u0621\u064f \u0644\u064e\u0643\u064e \u0628\u0650\u0646\u0650\u0639\u0652\u0645\u062a\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u064a\u0651\u064e \u060c \u0648\u064e\u0623\u064e\u0628\u064f\u0648\u0652\u0621\u064f \u0628\u0650\u0630\u064e\u0646\u0652\u0628\u0650\u064a\u0652 \u0641\u064e\u0627\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u0650\u064a\u0652 \u060c \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064e\u063a\u0652\u0641\u0650\u0631\u064f \u0627\u0644\u0630\u0651\u064f\u0646\u064f\u0648\u0628\u064e \u0625\u0650\u0644\u0627\u0651\u064e \u0623\u064e\u0646\u0652\u062a\u064e",latin:"Allahumma anta rabb\u012b l\u0101 il\u0101ha ill\u0101 anta khalaqtan\u012b wa anna 'abduka wa an\u0101 'al\u0101 'ahdika wa wa'dika mastatha'tu a'\u016b\u017cu bika min syarri m\u0101 shana'tu ab\u016b u laka bini' matika 'alayya wa ab\u016b u bi\u017canb\u012b faghfir l\u012b fa innahu l\u0101 yaghfiru\u017c \u017cun\u016bba illa anta",translation:"Ya Allah, Engkau adalah Rabb-ku, tidak ada Ilah (yang berhak diibadahi dengan benar) kecuali Engkau, Engkau-lah yang menciptakanku. Aku adalah hamba-Mu. Aku akan setia pada perjanjianku dengan-Mu semampuku. Aku berlindung kepada-Mu dari kejelekan (apa) yang kuperbuat. Aku mengakui nikmat-Mu (yang diberikan) kepadaku dan aku mengakui dosaku, oleh karena itu, ampunilah aku. Sesungguhnya tidak ada yang dapat mengampuni dosa kecuali Engkau.",notes:"Dibaca 1x",fawaid:"Barang siapa yang membacanya dengan yakin ketika petang hari, kemudian dia meninggal, maka ia akan masuk surga, demikian juga jika (dibaca) pada pagi hari.",source:"HR. al-Bukhari No. 6306, 6323, Ahmad IV/122-125, an-Nasa'i VIII/279-280"},{title:"Doa Memohon Kesehatan dan Perlindungan",arabic:"\u0627\u064e\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0639\u064e\u0627\u0641\u0650\u0646\u0650\u064a\u0652 \u0641\u0650\u064a\u0652 \u0628\u064e\u062f\u064e\u0646\u0650\u064a\u0652 \u060c \u0627\u064e\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0639\u064e\u0627\u0641\u0650\u0646\u0650\u064a\u0652 \u0641\u0650\u064a\u0652 \u0633\u064e\u0645\u0652\u0639\u0650\u064a\u0652 \u060c \u0627\u064e\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0639\u064e\u0627\u0641\u0650\u0646\u0650\u064a\u0652 \u0641\u0650\u064a\u0652 \u0628\u064e\u0635\u064e\u0631\u0650\u064a\u0652 \u060c \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064e \u060c \u0627\u064e\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0650\u0651\u064a\u0652 \u0623\u064e\u0639\u064f\u0648\u0652\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0643\u064f\u0641\u0652\u0631\u0650\u0648\u064e\u0627\u0644\u0652\u0641\u064e\u0642\u0652\u0631\u0650 \u060c \u0648\u064e\u0623\u064e\u0639\u064f\u0648\u0652\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0627\u0644\u0652\u0642\u064e\u0628\u0652\u0631\u0650 \u060c \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0640\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646\u0652\u062a\u064e",latin:"All\u0101humma '\u0101fin\u012b f\u012b badan\u012b, All\u0101humma '\u0101fin\u012b f\u012b sam'\u012b, All\u0101humma '\u0101fin\u012b f\u012b bashor\u012b, l\u0101 il\u0101ha ill\u0101 anta. All\u0101humma inni a'\u016b\u017cu bika minal kufri wal faqr, All\u0101humma inni a'\u016b\u017cu bika min 'a\u017c\u0101bil qobr, l\u0101 il\u0101ha ill\u0101 anta",translation:"Ya Allah, selamatkanlah tubuhku (dari penyakit dan dari apa yang tidak aku inginkan). Ya Allah, selamatkanlah pendengaranku (dari penyakit dan maksiat atau dari apa yang tidak aku inginkan). Ya Allah, selamatkanlah penglihatanku, tidak ada Ilah yang berhak diibadahi dengan benar kecuali Engkau. Ya Allah, sesungguhnya aku berlindung kepada-Mu dari kekufuran dan kefakiran. Aku berlindung kepada-Mu dari siksa kubur, tidak ada Ilah yang berhak diibadahi dengan benar kecuali Engkau.",notes:"Dibaca 1x",fawaid:"Dengan memohon kepada Allah agar memberi kita kesejahteraan dalam tubuh kita, kita memohon untuk disembuhkan dari semua penyakit jasmani dan rohani, sehingga kita memiliki tubuh yang sehat dan hati yang murni, dan oleh karena itu gunakanlah tubuh yang sehat ini dengan cara yang diridhai Allah.",source:"HR. al-Bukhari dalam Shahiib al-Adabil Mufrad No. 701, Abu Dawud No. 5090, Ahmad V/42, hasan"},{title:"Doa Memohon Keselamatan di Dunia dan Akhirat",arabic:"\u0627\u064e\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0625\u0650\u0646\u0650\u0651\u064a\u0652 \u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064e \u0627\u0644\u0652\u0639\u064e\u0641\u0652\u0648\u064e \u0648\u064e\u0627\u0644\u0652\u0639\u064e\u0627\u0641\u0650\u064a\u064e\u0629\u064e \u0641\u0650\u064a \u0627\u0644\u062f\u064f\u0651\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0627\u0652\u0644\u0622\u062e\u0650\u0631\u064e\u0629\u0650\u060c \u0627\u064e\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0625\u0650\u0646\u0650\u0651\u064a\u0652 \u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064e \u0627\u0644\u0652\u0639\u064e\u0641\u0652\u0648\u064e \u0648\u064e\u0627\u0644\u0652\u0639\u064e\u0627\u0641\u0650\u064a\u064e\u0629\u064e \u0641\u0650\u064a \u062f\u0650\u064a\u0652\u0646\u0650\u064a\u0652 \u0648\u064e\u062f\u064f\u0646\u0652\u064a\u064e\u0627\u064a\u064e \u0648\u064e\u0623\u064e\u0647\u0652\u0644\u0650\u064a\u0652 \u0648\u064e\u0645\u064e\u0627\u0644\u0650\u064a\u0652 \u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0627\u0633\u0652\u062a\u064f\u0631\u0652 \u0639\u064e\u0648\u0652\u0631\u064e\u0627\u062a\u0650\u0649 \u0648\u064e\u0622\u0645\u0650\u0646\u0652 \u0631\u064e\u0648\u0652\u0639\u064e\u0627\u062a\u0650\u0649. \u0627\u064e\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0627\u062d\u0652\u0641\u064e\u0638\u0652\u0646\u0650\u064a\u0652 \u0645\u0650\u0646\u0652 \u0628\u064e\u064a\u0652\u0646\u0650 \u064a\u064e\u062f\u064e\u064a\u064e\u0651\u060c \u0648\u064e\u0645\u0650\u0646\u0652 \u062e\u064e\u0644\u0652\u0641\u0650\u064a\u0652\u060c \u0648\u064e\u0639\u064e\u0646\u0652 \u064a\u064e\u0645\u0650\u064a\u0652\u0646\u0650\u064a\u0652 \u0648\u064e\u0639\u064e\u0646\u0652 \u0634\u0650\u0645\u064e\u0627\u0644\u0650\u064a\u0652\u060c \u0648\u064e\u0645\u0650\u0646\u0652 \u0641\u064e\u0648\u0652\u0642\u0650\u064a\u0652\u060c \u0648\u064e\u0623\u064e\u0639\u064f\u0648\u0652\u0630\u064f \u0628\u0650\u0639\u064e\u0638\u064e\u0645\u064e\u062a\u0650\u0643\u064e \u0623\u064e\u0646\u0652 \u0623\u064f\u063a\u0652\u062a\u064e\u0627\u0644\u064e \u0645\u0650\u0646\u0652 \u062a\u064e\u062d\u0652\u062a\u0650\u064a\u0652",latin:"Allahumma inn\u012b as'alukal 'afwa wal '\u0101fiyah fid duny\u0101 wal \u0101khiroh. Allahumma inn\u012b as'alukal 'afwa wal '\u0101fiyah f\u012b d\u012bn\u012b wa dun y\u0101ya wa ahl\u012b wa m\u0101l\u012b. Allahumas tur 'awroot\u012b wa \u0101min row'\u0101t\u012b. Allahummahfazh n\u012b mim bayni yadayya wa min kholf\u012b wa 'an yam\u012bn\u012b wa 'an syim\u0101l\u012b wa min fawq\u012b wa a'u\u017cu bi 'azhomatik an ugh t\u0101la min taht\u012b",translation:"Ya Allah, sesungguhnya aku memohon kebajikan dan keselamatan di dunia dan akhirat. Ya Allah, sesungguhnya aku memohon kebajikan dan keselamatan dalam agama, dunia, keluarga dan hartaku. Ya Allah, tutupilah auratku (aib dan sesuatu yang tidak layak dilihat orang) dan tenteramkanlah aku dari rasa takut. Ya Allah, peliharalah aku dari muka, belakang, kanan, kiri dan atasku. Aku berlindung dengan kebesaran-Mu, agar aku tidak disambar dari bawahku (oleh ular atau tenggelam dalam bumi dan lain-lain yang membuat aku jatuh).",notes:"Dibaca 1x",fawaid:"Rasulullah shallallahu 'alaihi wa sallam tidaklah pernah meninggalkan do'a ini di pagi dan petang hari. Di dalamnya berisi perlindungan keselamatan pada agama, dunia, keluarga dan harta dari berbagai macam gangguan yang datang dari berbagai arah.",source:"HR. al-Bukhari dalam al-Abadul Mufrad No. 1200, Abu Dawud No. 5074, an-Nasa'i VII/282, Ibnu Majah No. 3871, al-Hakim 1/517-518, dan lainnya dari Ibnu Umar radhiyallahu 'anhumaa"},{title:"Doa Memohon Perlindungan dari Bisikan Syaitan",arabic:"\u0627\u064e\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0639\u064e\u0627\u0644\u0650\u0645\u064e \u0627\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u0650 \u0648\u064e\u0627\u0644\u0634\u064e\u0651\u0647\u064e\u0627\u062f\u064e\u0629\u0650 \u0641\u064e\u0627\u0637\u0650\u0631\u064e \u0627\u0644\u0633\u064e\u0651\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0652\u0644\u0623\u064e\u0631\u0652\u0636\u0650\u060c \u0631\u064e\u0628\u064e\u0651 \u0643\u064f\u0644\u0650\u0651 \u0634\u064e\u064a\u0652\u0621\u064d \u0648\u064e\u0645\u064e\u0644\u0650\u064a\u0652\u0643\u064e\u0647\u064f\u060c \u0623\u064e\u0634\u0652\u0647\u064e\u062f\u064f \u0623\u064e\u0646\u0652 \u0644\u0627\u064e \u0625\u0650\u0644\u064e\u0640\u0647\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0623\u064e\u0646\u0652\u062a\u064e\u060c \u0623\u064e\u0639\u064f\u0648\u0652\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0634\u064e\u0631\u0650\u0651 \u0646\u064e\u0641\u0652\u0633\u0650\u064a\u0652\u060c \u0648\u064e\u0645\u0650\u0646\u0652 \u0634\u064e\u0631\u0650\u0651 \u0627\u0644\u0634\u064e\u0651\u064a\u0652\u0637\u064e\u0627\u0646\u0650 \u0648\u064e\u0634\u0650\u0631\u0652\u0643\u0650\u0647\u0650\u060c \u0648\u064e\u0623\u064e\u0646\u0652 \u0623\u064e\u0642\u0652\u062a\u064e\u0631\u0650\u0641\u064e \u0639\u064e\u0644\u064e\u0649 \u0646\u064e\u0641\u0652\u0633\u0650\u064a\u0652 \u0633\u064f\u0648\u0652\u0621\u064b\u0627 \u0623\u064e\u0648\u0652 \u0623\u064e\u062c\u064f\u0631\u064e\u0651\u0647\u064f \u0625\u0650\u0644\u064e\u0649 \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064d",latin:"Allahumma '\u0101limal ghoybi wasy syah\u0101dah f\u0101thiros sam\u0101w\u0101ti wal ardh. Robba kulli syai in wa mal\u012bkah. Asyhadu alla ilaha illa anta. A'u\u017cu bika min syarri nafs\u012b wa min syarrisy syaythooni wa syirkihi, wa an aqtarifa 'al\u0101 nafs\u012b s\u016b an aw ajurrohu il\u0101 muslim",translation:"Ya Allah, Yang Maha Mengetahui yang ghaib dan yang nyata, wahai Rabb pencipta langit dan bumi, Rabb segala sesuatu dan yang merajainya. Aku bersaksi bahwa tidak ada ilah yang berhak disembah kecuali Engkau. Aku berlindung kepada-Mu dari kejahatan diriku, setan dan balatentaranya (godaan untuk berbuat syirik pada Allah), dan aku (berlindung kepada-Mu) dari berbuat kejelekan terhadap diriku atau menyeretnya kepada seorang muslim.",notes:"Dibaca 1x",fawaid:"Rasulullah shallallahu 'alaihi wa sallam bersabda kepada Abu Bakar ash-Shiddiq radhiyallahu 'anhu \"Ucapkanlah pagi dan petang dan apabila engkau hendak tidur\".",source:"HR. al-Bukhari dalam al-Abadul Mufrad No. 1202, at-Tirmidzi No. 3392 dan Abu Dawud No. 5067"},{title:"Dzikir Agar Terhindar dari Semua Bahaya",arabic:"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0627\u0644\u064e\u0651\u0630\u0650\u0649 \u0644\u0627\u064e \u064a\u064e\u0636\u064f\u0631\u064f\u0651 \u0645\u064e\u0639\u064e \u0627\u0633\u0652\u0645\u0650\u0647\u0650 \u0634\u064e\u0649\u0652\u0621\u064c \u0641\u0650\u0649 \u0627\u0644\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0644\u0627\u064e \u0641\u0650\u0649 \u0627\u0644\u0633\u064e\u0651\u0645\u064e\u0627\u0621\u0650 \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0633\u064e\u0651\u0645\u0650\u064a\u0639\u064f \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0645\u064f",latin:"Bismillahilla\u017ci l\u0101 yadhurru ma'asmihi syai un fil ardhi wa l\u0101 fis sam\u0101' wa huwas sam\u012b'ul 'al\u012bm",translation:"Dengan nama Allah yang bila disebut, segala sesuatu di bumi dan langit tidak akan berbahaya, Dia-lah Yang Maha Mendengar lagi Maha Mengetahui.",notes:"Dibaca 3x",fawaid:"Barang siapa membacanya sebanyak tiga kali ketika pagi dan sore hari, maka tidak ada sesuatu pun yang membahayakan dirinya.",source:"HR. at-Tirmidzi No. 3388, Abu Dawud No. 5088, Ibnu Majah No. 3869, al-Hakim 1/514, dan Ahmad No. 446 dan 474"},{title:"Pernyataan Keridhaan dengan Allah, Islam, dan Nabi Muhammad Shallallaahu 'Alaihi Wa Sallam",arabic:"\u0631\u064e\u0636\u0650\u064a\u0652\u062a\u064f \u0628\u0650\u0627\u0644\u0644\u0647\u0650 \u0631\u064e\u0628\u064b\u0651\u0627\u060c \u0648\u064e\u0628\u0650\u0627\u0652\u0644\u0625\u0650\u0633\u0652\u0644\u0627\u064e\u0645\u0650 \u062f\u0650\u064a\u0652\u0646\u064b\u0627\u060c \u0648\u064e\u0628\u0650\u0645\u064f\u062d\u064e\u0645\u064e\u0651\u062f\u064d \u0635\u064e\u0644\u064e\u0651\u0649 \u0627\u0644\u0644\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0648\u064e\u0633\u064e\u0644\u064e\u0651\u0645\u064e \u0646\u064e\u0628\u0650\u064a\u064b\u0651\u0627",latin:"Rodh\u012btu bill\u0101hi robb\u0101 wa bil isl\u0101mi d\u012bn\u0101, wa bi muhammadin shallall\u0101hu 'alaihi wa sallama nabiyy\u0101",translation:"Aku ridha Allah sebagai Rabb, Islam sebagai agama dan Muhammad shallallahu 'alaihi wa sallam sebagai nabi.",notes:"Dibaca 3x",fawaid:"Barang siapa membacanya sebanyak tiga kali ketika pagi dan sore, maka Allah memberikan keridhaan-Nya kepadanya pada hari kiamat.",source:"HR. Ahmad IV/337, Abu Dawud No. 5072, at-Tirmidzi No. 3389, Ibnu Majah No. 3870, an-Nasa'i dalam 'Amalul Yaum wal Lailah No. 4 dan Ibnus Sunni No. 68"},{title:"Meminta Petunjuk Kepada Allah",arabic:"\u064a\u064e\u0627 \u062d\u064e\u064a\u064f\u0651 \u064a\u064e\u0627 \u0642\u064e\u064a\u064f\u0651\u0648\u0652\u0645\u064f \u0628\u0650\u0631\u064e\u062d\u0652\u0645\u064e\u062a\u0650\u0643\u064e \u0623\u064e\u0633\u0652\u062a\u064e\u063a\u0650\u064a\u0652\u062b\u064f\u060c \u0648\u064e\u0623\u064e\u0635\u0652\u0644\u0650\u062d\u0652 \u0644\u0650\u064a\u0652 \u0634\u064e\u0623\u0652\u0646\u0650\u064a\u0652 \u0643\u064f\u0644\u064e\u0651\u0647\u064f \u0648\u064e\u0644\u0627\u064e \u062a\u064e\u0643\u0650\u0644\u0652\u0646\u0650\u064a\u0652 \u0625\u0650\u0644\u064e\u0649 \u0646\u064e\u0641\u0652\u0633\u0650\u064a\u0652 \u0637\u064e\u0631\u0652\u0641\u064e\u0629\u064e \u0639\u064e\u064a\u0652\u0646\u064d \u0623\u064e\u0628\u064e\u062f\u064b\u0627",latin:"Y\u0101 hayyu y\u0101 qoyyum, bi rohmatika as tagh\u012b\u1e61, wa ash lih l\u012b sya'n\u012b kullahu wa l\u0101 takiln\u012b il\u0101 nafs\u012b thorfata 'ainin abadan",translation:"Wahai Rabb Yang Maha Hidup, wahai Rabb Yang Berdiri Sendiri (tidak butuh segala sesuatu), dengan rahmat-Mu aku minta pertolongan, perbaikilah segala urusanku dan jangan diserahkan kepadaku sekali pun sekejap mata (tanpa mendapat pertolongan dari-Mu).",notes:"Dibaca 1x",fawaid:"Maksud dari do'a ini adalah manusia sangat butuh Allah dan berdo'a agar Allah tidak meninggalkannya walaupun sekejap saja.",source:"HR. an-Nasa'i dalam 'Amalul Yaum wal Lailah No. 575, dan al-Hakim 1/545, lihat Shahiih at-Targhiib wat Tarhiib 1/417 No. 661, Ash-shahiihah No. 227, hasan"},{title:"Memasuki Pagi di atas Fitrah Islam",arabic:"\u0623\u064e\u0635\u0652\u0628\u064e\u062d\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0641\u0650\u0637\u0652\u0631\u064e\u0629\u0650 \u0627\u0652\u0644\u0625\u0650\u0633\u0652\u0644\u0627\u064e\u0645\u0650 \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0643\u064e\u0644\u0650\u0645\u064e\u0629\u0650 \u0627\u0652\u0644\u0625\u0650\u062e\u0652\u0644\u0627\u064e\u0635\u0650\u060c \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u062f\u0650\u064a\u0652\u0646\u0650 \u0646\u064e\u0628\u0650\u064a\u0650\u0651\u0646\u064e\u0627 \u0645\u064f\u062d\u064e\u0645\u064e\u0651\u062f\u064d \u0635\u064e\u0644\u064e\u0651\u0649 \u0627\u0644\u0644\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0648\u064e\u0633\u064e\u0644\u064e\u0651\u0645\u064e\u060c \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0645\u0650\u0644\u064e\u0651\u0629\u0650 \u0623\u064e\u0628\u0650\u064a\u0652\u0646\u064e\u0627 \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0652\u0645\u064e\u060c \u062d\u064e\u0646\u0650\u064a\u0652\u0641\u064b\u0627 \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064b\u0627 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0634\u0652\u0631\u0650\u0643\u0650\u064a\u0652\u0646\u064e",latin:"Ash bahn\u0101 'ala fithrotil isl\u0101m wa 'al\u0101 kalimatil ikhl\u0101sh, wa 'al\u0101 d\u012bni nabiyyin\u0101 Muhammadin shallallahu 'alaihi wa sallam, wa 'al\u0101 millati ab\u012bna Ibr\u0101h\u012bma han\u012bfam muslim\u0101w wa m\u0101 k\u0101na minal musyrikin",translation:"Di waktu pagi kami memegang agama Islam, kalimat ikhlas (kalimat syahadat), agama Nabi kami Muhammad shallallahu 'alaihi wa sallam, dan agama bapak kami Ibrahim, yang berdiri di atas jalan yang lurus, muslim dan tidak tergolong orang-orang musyrik.",notes:"Dibaca 1x",fawaid:"'Fitratil Islam' maksudnya di atas sunnah, 'kalimatil ikhlas' maksudnya adalah kalimat syahadat dan 'hanifan' maksudnya adalah hati yang condong kepada jalan yang lurus dan kebaikan.",source:"HR. Ahmad III/406, 407, ad-Darimi II/292 dan Ibnus Sunni dalam Amalul Yaum wal Lailah No. 34, Misykaatul Mashaabiih No. 2415, Shahiihal-Jaami'ish Shaghiir No. 4674, shahih"},{title:"Dzikir Tauhid",arabic:"\u0644\u0627\u064e \u0625\u0650\u0644\u064e\u0640\u0647\u064e \u0625\u0650\u0644\u0627\u0651\u064e \u0627\u0644\u0644\u0647\u064f \u0648\u064e\u062d\u0652\u062f\u064e\u0647\u064f \u0644\u0627\u064e \u0634\u064e\u0631\u0650\u064a\u0652\u0643\u064e \u0644\u064e\u0647\u064f\u060c \u0644\u064e\u0647\u064f \u0627\u0644\u0652\u0645\u064f\u0644\u0652\u0643\u064f \u0648\u064e\u0644\u064e\u0647\u064f \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0648\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u0649 \u0643\u064f\u0644\u0650\u0651 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0652\u0631\u064f",latin:"L\u0101 il\u0101ha ill\u0101ll\u0101h wa\u1e25dahu l\u0101 syar\u012bka lah, lahul mulku walahul \u1e25amdu wa huwa 'al\u0101 kulli syai'in qad\u012br",translation:"Tidak ada ilah yang berhak disembah selain Allah semata, tidak ada sekutu bagiNya. Bagi-Nya kerajaan dan segala pujian. Dia-lah yang berkuasa atas segala sesuatu.",notes:"Dibaca 1x atau 10x di pagi hari, Dibaca 100x dalam sehari",fawaid:"Barang siapa yang mengucapkan dzikir tersebut dalam sehari sebanyak 100x, maka itu seperti membebaskan 10 orang budak, dicatat baginya 100 kebaikan, dihapus baginya 100 kesalahan, dirinya akan terjaga dari gangguan setan dari pagi hingga petang hari, dan tidak ada seorang pun yang lebih baik dari yang ia lakukan kecuali oleh orang yang mengamalkan lebih dari itu.",source:"HR al-Bukhari No. 3293 dan 6403, Muslim IV/2071 No. 2691 (28), at-Tirmidzi No. 3468, Ibnu Majah No. 3798"},{title:"Membaca Tasbih kepada Allah",arabic:"\u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0647\u0650 \u0648\u064e\u0628\u0650\u062d\u064e\u0645\u0652\u062f\u0650\u0647\u0650 \u0639\u064e\u062f\u064e\u062f\u064e \u062e\u064e\u0644\u0652\u0642\u064e\u0647\u0650 \u0648\u064e\u0631\u0650\u0636\u064e\u0649 \u0646\u064e\u0641\u0652\u0633\u0650\u0647\u0650 \u0648\u064e\u0632\u0650\u0646\u064e\u0629\u064e \u0639\u064e\u0631\u0652\u0634\u0650\u0647\u0650 \u0648\u064e\u0645\u0650\u062f\u064e\u0627\u062f\u064e \u0643\u064e\u0644\u0650\u0645\u064e\u0627\u062a\u0650\u0647\u0650",latin:"Subhanallahi wa bihamdihi 'adada khalqihi wa ridha nafsihi wa zinata 'arsyihi wa midada kalimatihi",translation:"Maha Suci Allah, sebanyak makhluk-Nya, Maha Suci Allah sejauh kerelaan-Nya, Maha Suci Allah seberat timbangan 'Arsy-Nya, dan sebanyak tinta tulisan kalimat-Nya.",notes:"Dibaca 3x",fawaid:"Nabi shallallahu 'alaihi wa sallam mengatakan pada Juwairiyah bahwa dzikir di atas telah mengalahkan dzikir yang dibaca oleh Juwairiyah dari selepas Shubuh sampai waktu Dhuha.",source:"HR. Muslim No. 2726. Syarah Muslim XVII/44. Dari Juwairiyah binti al-Harits radhiyallahu 'anhuma"},{title:"Doa Memohon Ilmu yang Bermanfaat, Rezeki yang Baik, dan Amal yang Diterima",arabic:"\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0625\u0650\u0646\u0650\u0651\u0649 \u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064e \u0639\u0650\u0644\u0652\u0645\u064b\u0627 \u0646\u064e\u0627\u0641\u0650\u0639\u064b\u0627 \u0648\u064e\u0631\u0650\u0632\u0652\u0642\u064b\u0627 \u0637\u064e\u064a\u0650\u0651\u0628\u064b\u0627 \u0648\u064e\u0639\u064e\u0645\u064e\u0644\u0627\u064b \u0645\u064f\u062a\u064e\u0642\u064e\u0628\u064e\u0651\u0644\u0627\u064b",latin:"Allahumma inn\u012b as'aluka 'ilman n\u0101fi'a, wa rizqan thayyiba, wa 'amalan mutaqabbala",translation:"Ya Allah, sungguh aku memohon kepada-Mu ilmu yang bermanfaat (bagi diriku dan orang lain), rizki yang halal dan amal yang diterima (di sisi-Mu dan mendapatkan ganjaran yang baik).",notes:"Dibaca 1x",fawaid:"Doa ini dianjurkan dipagi hari sebab waktu pagi memiliki keistimewaan dan keberkahan yang lebih, sebagaimana sabda Rasulullah \"Ya Allah berkahilah ummat ku dipagi hari\".",source:"HR. Ibnu Majah No. 925, Shahiih Ibni Majah 1/152 No. 753 Ibnus Sunni dalam 'Amalul Yaum wal Lailah No. 54, 110, dan Ahmad VI/294, 305, 318, 322. Dari Ummu Salamah, shahih"},{title:"Tasbih dan Tahmid Harian",arabic:"\u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0648\u064e\u0628\u0650\u062d\u064e\u0645\u0652\u062f\u0650\u0647\u0650",latin:"Subh\u0101nallahi wa bihamdihi",translation:"Maha Suci Allah, aku memuji-Nya.",notes:"Dibaca 100x",fawaid:"Barang siapa yang mengucapkan kalimat 'subhanallah wa bi hamdih' di pagi dan petang hari sebanyak 100x, maka tidak ada yang datang pada hari kimata yang lebih baik dari yang ia lakukan kecuali orang yang mengucapkan semisal atau lebih dari itu.",source:"HR. Muslim No. 2691 dan No. 2692, dari Abu Hurairah radhiyallahu 'anhu Syarah Muslim XVII/17-18, Shahiih at-Targhiib wat Tarhiib 1/413 No. 653"},{title:"Istighfar 100x Sehari",arabic:"\u0623\u064e\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u064f \u0627\u0644\u0644\u0647 \u0648\u064e\u0623\u064e\u062a\u064f\u0648\u0652\u0628\u064f \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650",latin:"Astaghfirullah wa at\u016bbu ilaih",translation:"Aku memohon ampunan kepada Allah dan bertaubat kepada-Nya.",notes:"Dibaca 100x sehari",fawaid:"Dari Ibnu 'Umar ia berkata: Rasulullah shallallahu 'alaihi wa sallam bersabda: 'Wahai manusia, bertaubatlah kalian kepada Allah, sesungguhnya aku bertaubat kepada-Nya dalam sehari seratus kali'.",source:"HR. al-Bukhari/Fat-hul Baari XI/101 dan Muslim No. 2702"}]},1279,[]);
__d(function(a,n,i,e,u,k,h){u.exports=[{title:"Doa Ihram",arabic:"\u0627\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064f\u062d\u064e\u0631\u0651\u0650\u0645\u064f \u0646\u064e\u0641\u0652\u0633\u0650\u064a \u0645\u0650\u0646\u0652 \u0643\u064f\u0644\u0651\u0650 \u0645\u064e\u0627 \u062d\u064e\u0631\u0651\u064e\u0645\u0652\u062a\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0645\u064f\u062d\u0652\u0631\u0650\u0645\u0650 \u0641\u064e\u0627\u0631\u0652\u062d\u064e\u0645\u0652\u0646\u0650\u064a \u064a\u064e\u0627 \u0623\u064e\u0631\u0652\u062d\u064e\u0645\u064e \u0627\u0644\u0631\u0651\u064e\u0627\u062d\u0650\u0645\u0650\u064a\u0652\u0646\u064e",latin:"",translation:"Ya Allah, sesungguhnya aku mengharamkan diriku dari segala yang Engkau haramkan kepada orang yang berihram, karena itu rahmatilah aku wahai Allah Yang Maha Pemberi Rahmat.",notes:"",fawaid:"",source:"Kumpulan Doa Sehari-hari, Kemenag Jatim \xb7 kategori Haji/Umroh"},{title:"Doa Ketika Melihat Ka'bah",arabic:"\u0627\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0632\u0650\u062f\u0652 \u0647\u064e\u0630\u064e\u0627 \u0627\u0644\u0652\u0628\u064e\u064a\u0652\u062a\u064e \u062a\u064e\u0634\u0652\u0631\u0650\u064a\u0641\u064b\u0627 \u0648\u064e\u062a\u064e\u0639\u0652\u0638\u0650\u064a\u0645\u064b\u0627 \u0648\u064e\u062a\u064e\u0643\u0652\u0631\u0650\u064a\u0645\u064b\u0627 \u0648\u064e\u0645\u064e\u0647\u064e\u0627\u0628\u064e\u0629\u064b \u0648\u064e\u0632\u0650\u062f\u0652 \u0645\u064e\u0646\u0652 \u0634\u064e\u0631\u0651\u0641\u064e\u0647\u064f \u0648\u064e\u0643\u064e\u0631\u0651\u0645\u064e\u0647\u064f \u0645\u0650\u0645\u0651\u064e\u0646\u0652 \u062d\u064e\u062c\u0651\u064e\u0647\u064f \u0623\u064e\u0648\u0650\u0627\u0639\u0652\u062a\u064e\u0645\u064e\u0631\u064e\u0647\u064f \u062a\u064e\u0634\u0652\u0631\u0650\u064a\u0641\u064b\u0627 \u0648\u064e\u062a\u064e\u0643\u0652\u0631\u0650\u064a\u0645\u064b\u0627 \u0648\u064e\u062a\u064e\u0639\u0652\u0638\u0650\u064a\u0645\u064b\u0627 \u0648\u064e\u0628\u0650\u0631\u0651\u064b\u0627",latin:"",translation:"Ya Allah, tambahkanlah kemuliaan, kehormatan, keagungan dan kehebatan pada Baitullah ini dan tambahkanlah pula pada orang-orang yang memuliakan, menghormati dan mengagungkannya diantara mereka yang berhaji atau yang berumroh padanya dengan kemuliaan, kehormatan, kebesaran dan kebaikan.",notes:"",fawaid:"",source:"Kumpulan Doa Sehari-hari, Kemenag Jatim \xb7 kategori Haji/Umroh"},{title:"Doa Masuk Kota Madinah",arabic:"\u0627\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0647\u064e\u0630\u064e\u0627 \u062d\u064e\u0631\u064e\u0627\u0645\u064f \u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0643\u064e \u0648\u064e\u0627\u062c\u0652\u0639\u064e\u0644\u0652\u0647\u064f \u0648\u0650\u0642\u064e\u0627\u064a\u064e\u0629\u064b \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u064e\u0648\u0623\u064e\u0645\u064e\u0646\u064e\u0629\u064b \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0648\u064e\u0633\u064f\u0648\u0621\u064e \u0627\u0644\u062d\u0650\u0633\u064e\u0627\u0628\u0650",latin:"",translation:"Ya Allah, negeri ini adalah tanah haram Rasul Mu Muhammad SAW, maka jadikanlah penjaga bagiku dari neraka, aman dari siksa dan buruknya hisab (perhitungan di hari kemudian.",notes:"",fawaid:"",source:"Kumpulan Doa Sehari-hari, Kemenag Jatim \xb7 kategori Haji/Umroh"},{title:"Doa Masuk Masjidil Haram",arabic:"\u0627\u064e\u0644\u0644\u0651\u0670\u0647\u064f\u0645\u064e\u0651 \u0623\u064e\u0646\u0652\u062a\u064e \u0627\u0644\u0633\u064e\u0651\u0644\u064e\u0627\u0645\u064f \u0648\u064e\u0645\u0650\u0646\u0652\u0643\u064e \u0627\u0644\u0633\u064e\u0651\u0644\u064e\u0627\u0645\u064f \u0641\u064e\u062d\u064e\u064a\u0650\u0651\u0646\u064e\u0627 \u0631\u064e\u0628\u064e\u0651\u0646\u064e\u0627 \u0628\u0650\u0627\u0644\u0633\u064e\u0651\u0644\u064e\u0627\u0645\u0650 \u0648\u064e\u0623\u064e\u062f\u0652\u062e\u0650\u0644\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u062c\u064e\u0646\u064e\u0651\u0629\u064e \u062f\u064e\u0627\u0631\u064e\u0627\u0644\u0633\u064e\u0651\u0644\u064e\u0627\u0645\u064e \u062a\u064e\u0628\u064e\u0627\u0631\u064e\u0643\u0652\u062a\u064e \u0648\u064e\u062a\u064e\u0639\u064e\u0627\u0644\u064e\u064a\u0652\u062a\u064e \u064a\u064e\u0627 \u0630\u064e\u0627\u0627\u0644\u0652\u062c\u064e\u0644\u064e\u0627\u0644\u0650 \u0648\u064e\u0627\u0652\u0644\u0625\u0650\u0643\u0652\u0631\u064e\u0627\u0645\u0650. \u0627\u064e\u0644\u0644\u0651\u0670\u0647\u064f\u0645\u064e\u0651 \u0627\u0641\u0652\u062a\u064e\u062d\u0652 \u0644\u0650\u064a\u0652 \u0623\u064e\u0628\u0652\u0648\u064e\u0627\u0628\u064e \u0631\u064e\u062d\u0652\u0645\u064e\u062a\u0650\u0643\u064e \u0648\u064e\u0645\u064e\u063a\u0652\u0641\u0650\u0631\u064e\u062a\u0650\u0643\u064e \u0648\u064e\u0623\u064e\u062f\u0652\u062e\u0650\u0644\u0652\u0646\u0650\u064a\u0652 \u0641\u0650\u064a\u0652\u0647\u064e\u0627. \u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0650\u0644\u0644\u0647\u0650 \u0648\u064e\u0627\u0644\u0635\u064e\u0651\u0644\u064e\u0627\u0629\u064f \u0648\u064e\u0627\u0644\u0633\u064e\u0651\u0644\u064e\u0627\u0645\u064f \u0639\u064e\u0644\u0670\u0649 \u0631\u064e\u0633\u064f\u0648\u0652\u0644\u0650 \u0627\u0644\u0644\u0647\u0650",latin:"",translation:"Ya Allah, Engkau sumber keselamatan dan dari-Mulah datangnya keselamatan, hidupkanlah kami wahai Tuhan kami dengan keselamatan, dan tempatkanlah kami pada surga, negeri keselamatan. Maha banyak anugerah-Mu dan Maha Tinggi Engkau wahai Tuhan yang memiliki keagungatan dan kehormatan. Ya Allah ampunilah dosa-dosaku dan bukakanlah pintu-pintu rahmat-Mu. (Aku masuk masjid ini) dengan Nama Allah disertai segala puji bagi Allah, serta salawat dan salamat untuk Rasulullah SAW.",notes:"",fawaid:"",source:"Kumpulan Doa Sehari-hari, Kemenag Jatim \xb7 kategori Haji/Umroh"},{title:"Doa Masuk kota Mekkah",arabic:"\u0627\u064e\u0644\u0644\u0651\u0670\u0647\u064f\u0645\u064e\u0651 \u0647\u0670\u0630\u064e\u0627 \u062d\u064e\u0631\u064e\u0645\u064f\u0643\u064e \u0648\u064e\u0623\u064e\u0645\u0652\u0646\u064f\u0643\u064e \u0641\u064e\u062d\u064e\u0631\u0650\u0651\u0645\u0652 \u0644\u064e\u062d\u0652\u0645\u0650\u064a\u0652 \u0648\u064e\u062f\u064e\u0645\u0650\u064a\u0652 \u0648\u064e\u0634\u064e\u0639\u0652\u0631\u0650\u064a\u0652 \u0648\u064e\u0628\u064e\u0634\u064e\u0631\u0650\u064a\u0652 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0646\u064e\u0651\u0627\u0631\u0650 \u0648\u064e\u0627\u0670\u0645\u0650\u0646\u0650\u0651\u064a\u0652 \u0645\u0650\u0646\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u0650\u0643\u064e \u064a\u064e\u0648\u0652\u0645\u064e \u062a\u064e\u0628\u0652\u0639\u064e\u062b\u064f \u0639\u0650\u0628\u064e\u0627\u062f\u064e\u0643\u064e \u0648\u064e\u0627\u062c\u0652\u0639\u064e\u0644\u0652\u0646\u0650\u064a\u0652 \u0645\u0650\u0646\u0652 \u0623\u064e\u0648\u0652\u0644\u0650\u064a\u064e\u0622\u0626\u0650\u0643\u064e \u0648\u064e\u0623\u064e\u0647\u0652\u0644\u0650 \u0637\u064e\u0627\u0639\u064e\u062a\u0650\u0643\u064e",latin:"",translation:"Ya Allah kota ini adalah tanah Haram-Mu dan tempat yang aman, maka hindarkanlah daging, darah, rambut, bulu dan kulitku dari neraka. Amankanlah aku dari siksa-Mu pada hari Engkau membangkitkan aku ke dalam golongan aulia-Mu dan ahli ta\u2019at pada-Mu.",notes:"",fawaid:"",source:"Kumpulan Doa Sehari-hari, Kemenag Jatim \xb7 kategori Haji/Umroh"},{title:"Doa Sa'i",arabic:"\u0627\u0644\u0644\u0647 \u0627\u0643\u0628\u0631\u060c \u0627\u0644\u0644\u0647 \u0627\u0643\u0628\u0631 \u060c \u0627\u0644\u0644\u0647 \u0627\u0643\u0628\u0631\u060c \u0627\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0627\u0633\u0652\u062a\u064e\u0639\u0652\u0645\u064e\u0644\u0652\u0646\u0650\u064a\u0652 \u0628\u0650\u0633\u064f\u0646\u064e\u0629\u0650 \u0646\u064e\u0628\u0650\u064a\u0650\u0651\u0643\u064e \u0648\u064e\u062a\u064e\u0648\u064e\u0641\u0651\u064e\u0646\u0650\u064a\u0652 \u0639\u064e\u0644\u064e\u0649 \u0645\u0650\u0644\u0651\u064e\u062a\u0650\u0647\u0650 \u0648\u064e\u0623\u0639\u0650\u062f\u0652\u0646\u0650\u064a\u0652 \u0645\u0650\u0646\u0652 \u0645\u064f\u0636\u0650\u0644\u0651\u064e\u0627\u062a\u0650 \u0627\u0644\u0652\u0641\u0650\u062a\u064e\u0646\u0650",latin:"",translation:"Ya Allah, bimbinglah kami untuk beramal sesuai dengan sunnah Nabi-Mu dan matikanlah kami dalam keadaan Islam dan hindarkanlah kami dari fitnah/ujian yang menyesatkan.",notes:"",fawaid:"",source:"Kumpulan Doa Sehari-hari, Kemenag Jatim \xb7 kategori Haji/Umroh"},{title:"Doa Setelah Thawaf",arabic:"\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u064a\u064e\u0627 \u0631\u064e\u0628\u064e\u0651 \u0627\u0644\u0628\u064e\u064a\u0652\u062a\u0650 \u0627\u0644\u0639\u064e\u062a\u0650\u064a\u0652\u0642\u0650\u060c \u0627\u064e\u0639\u0652\u062a\u0650\u0642\u0652 \u0631\u0650\u0642\u064e\u0627\u0628\u064e\u0646\u064e\u0627\u060c \u0648\u064e\u0631\u0650\u0642\u064e\u0627\u0628\u064e \u0622\u0628\u064e\u0627\u0626\u0650\u0646\u064e\u0627\u060c \u0648\u064e\u0623\u064f\u0645\u064e\u0651\u0647\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0648\u064e\u0625\u062e\u0652\u0648\u064e\u0627\u0646\u0650\u0646\u064e\u0627 \u0648\u064e\u0623\u064e\u0648\u0652\u0644\u0627\u064e\u062f\u0650\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0627\u0644\u0646\u064e\u0627\u0631\u0650\u060c \u064a\u064e\u0627 \u0630\u064e\u0627 \u0627\u0644\u062c\u064f\u0648\u0652\u062f\u0650 \u0648\u064e\u0627\u0644\u0643\u064e\u0631\u064e\u0645\u0650 \u0648\u064e\u0627\u0644\u0641\u064e\u0636\u0652\u0644\u0650 \u0648\u064e\u0627\u0644\u0645\u064e\u0646\u0650\u0651 \u0648\u064e\u0627\u0644\u0639\u064e\u0637\u064e\u0627\u0621\u0650 \u0648\u0627\u0644\u0625\u062d\u0652\u0633\u064e\u0627\u0646\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0623\u062d\u0652\u0633\u0650\u0646\u0652 \u0639\u0627\u0642\u0650\u0628\u064e\u062a\u064e\u0646\u0627 \u0641\u064a \u0627\u0644\u0623\u0645\u064f\u0648\u0631\u0650 \u0643\u064f\u0644\u0650\u0651\u0647\u0627\u060c \u0648\u0623\u062c\u0650\u0631\u0652\u0646\u0627 \u0645\u0650\u0646\u0652 \u062e\u064e\u0632\u0652\u064a \u0627\u0644\u062f\u064f\u0651\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0639\u064e\u0630\u0627\u0628\u0650 \u0627\u0644\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0625\u0650\u0646\u0650\u0651\u064a\u0652 \u0639\u064e\u0628\u0652\u062f\u064f\u0643\u064e \u0648\u064e\u0627\u0628\u0652\u0646\u064f \u0639\u064e\u0628\u0652\u062f\u0650\u0643\u064e\u060c \u0648\u064e\u0627\u0642\u0650\u0641\u064c \u062a\u064e\u062d\u0652\u062a\u064e \u0628\u064e\u0627\u0628\u0650\u0643\u064e \u0645\u064f\u0644\u0652\u062a\u064e\u0632\u0650\u0645\u064c \u0628\u0650\u0623\u064e\u0639\u0652\u062a\u064e\u0627\u0628\u0650\u0643\u064e\u060c \u0645\u064f\u062a\u064e\u0630\u064e\u0644\u0650\u0651\u0644\u064c \u0628\u064e\u064a\u0652\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u0652\u0643\u064e\u060c \u0623\u064e\u0631\u0652\u062c\u064f\u0648 \u0631\u064e\u062d\u0652\u0645\u064e\u062a\u064e\u0643\u064e\u060c \u0648\u064e\u0623\u064e\u062e\u0652\u0634\u064e\u0649 \u0639\u064e\u0630\u064e\u0627\u0628\u064e\u0643\u064e\u060c \u064a\u064e\u0627\u0642\u064e\u062f\u0650\u064a\u0652\u0645\u064e \u0627\u0644\u0625\u0650\u062d\u0652\u0633\u064e\u0627\u0646\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0625\u0650\u0646\u0650\u0651\u064a\u0652 \u0623\u064e\u0633\u0652\u0623\u0644\u064f\u0643\u064e \u0623\u064e\u0646\u0652 \u062a\u064e\u0631\u0652\u0641\u064e\u0639\u064e \u0630\u0650\u0643\u0652\u0631\u0650\u064a\u0652 \u0648\u064e\u062a\u064e\u0636\u064e\u0639\u064e \u0648\u0650\u0632\u0652\u0631\u0650\u064a\u0652\u060c \u0648\u064e\u062a\u064f\u0635\u0652\u0644\u0650\u062d\u064e \u0623\u064e\u0645\u0652\u0631\u0650\u064a\u0652\u060c \u0648\u064e\u062a\u064f\u0637\u064e\u0647\u0650\u0651\u0631\u064e \u0642\u064e\u0644\u0652\u0628\u0650\u064a\u0652\u060c \u0648\u064e\u062a\u064f\u0646\u064e\u0648\u0650\u0651\u0631\u064e \u0644\u0650\u064a\u0652 \u0641\u0650\u064a\u0652 \u0642\u064e\u0628\u0652\u0631\u0650\u064a\u0652\u060c \u0648\u064e\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u064e \u0644\u0650\u064a\u0652 \u0630\u064e\u0646\u0652\u0628\u0650\u064a\u0652\u060c \u0648\u064e\u0623\u064e\u0633\u0652\u0623\u0644\u064f\u0643\u064e \u062f\u064e\u0631\u064e\u062c\u064e\u0627\u062a\u0650 \u0627\u0644\u0639\u064f\u0644\u064e\u0649 \u0645\u0650\u0646\u064e \u0627\u0644\u062c\u064e\u0646\u064e\u0651\u0629\u0650",latin:"",translation:"Ya Allah, yang memelihara Ka\u2019bah ini, bebaskanlah dari kami, bapak dan ibu kami, saudara-saudara dan anak-anak kami dari siksa neraka, wahai Tuhan Yang Maha Pemurah, Dermawan dan mempunyai keutamaan, kemulian, kelebihan, anugerah, pemberian dan kebaikan. Ya Allah, perbaikilah kesudahan segenap urusan kami dan jauhkanlah dari kehinaan dunia dan siksa di akhirat. Ya Allah, sesungguhnya aku adalah hamba-Mu, anak dari hamba-Mu, tegak merapat berdiri di bawah pintu Ka\u2019bah-Mu menundukkan diri dihadapan-Mu sambil mengharapkan rahmat-Mu, kasih sayang-Mu, dan takut akan siksa-Mu. Wahai Tuhan pemilik kebaikan abadi, aku mohon pada-Mu agar Engkau tinggikan namaku, hapuskan dosaku, perbaiki segala urusanku, bersihkan hatiku berikan cahaya kelak dalam kuburku. Ampunilah dosaku dan aku mohon pada-Mu martabat yang tinggi didalam surga.",notes:"",fawaid:"",source:"Kumpulan Doa Sehari-hari, Kemenag Jatim \xb7 kategori Haji/Umroh"},{title:"Doa Thawaf",arabic:"\u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u0627\u0650\u0644\u064e\u0647\u064e \u0627\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0644\u0647\u064f \u0648\u064e\u0627\u0644\u0644\u0647\u064f \u0627\u064e\u0643\u0652\u0628\u064e\u0631\u0652 \u0648\u064e\u0644\u064e\u0627 \u062d\u064e\u0648\u0652\u0644\u064e \u0648\u064e\u0644\u064e\u0627 \u0642\u064f\u0648\u0651\u064e\u0629\u064e \u0627\u0650\u0644\u0650\u0651\u0627 \u0628\u0650\u0627\u0627\u0644\u0644\u0647\u0650 \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0650\u0651 \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0652\u0645\u0650",latin:"",translation:"Maha Suci Allah, segala puji milik Allah tidak ada Tuhan melainkan Allah, Allah Maha Besar dan tiada daya dan kekuatan melainkan atas pertolongan Allah yang Maha Tingi dan Maha Agung.",notes:"",fawaid:"",source:"Kumpulan Doa Sehari-hari, Kemenag Jatim \xb7 kategori Haji/Umroh"},{title:"Doa Thawaf 1",arabic:"\u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0644\u0647\u064e \u0627\u0644\u0644\u0647\u064f \u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064f. \u0648\u064e\u0644\u064e\u0627 \u062d\u064e\u0648\u0652\u0644\u064e \u0648\u064e\u0644\u064e\u0627 \u0642\u064f\u0648\u0651\u064e\u0629\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0627\u0644\u0644\u0647\u0650 \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0651\u0650 \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0652\u0645\u0650. \u0648\u064e\u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u064f \u0648\u064e\u0627\u0644\u0633\u0651\u064e\u0644\u0627\u064e\u0645\u064f \u0639\u064e\u0644\u064e\u0649 \u0631\u064e\u0633\u064f\u0648\u0644\u0650 \u0627\u0644\u0644\u0647\u0650 \u0635\u064e\u0644\u0651\u064e\u0649 \u0627\u0644\u0644\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0648\u064e\u0633\u064e\u0644\u0651\u064e\u0645\u064e. \u0627\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0625\u0650\u064a\u0652\u0645\u064e\u0627\u0646\u064b\u0627 \u0628\u0650\u0643\u064e \u0648\u064e\u062a\u064e\u0635\u064e\u062f\u0651\u0650\u064a\u0652\u0642\u064b\u0627 \u0628\u0650\u0643\u0650\u062a\u064e\u0627\u0628\u0650\u0643\u064e \u0648\u064e\u0648\u064e\u0641\u064e\u0627\u0621\u0627\u064b \u0628\u0650\u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0643\u064e \u0648\u064e\u0627\u062a\u0651\u0650\u0628\u064e\u0627\u0639\u064b\u0627 \u0644\u0650\u0633\u064f\u0646\u0651\u064e\u0629\u0650 \u0646\u064e\u0628\u0650\u064a\u0651\u0650\u0643\u064e \u0645\u064f\u062d\u064e\u0645\u0651\u064e\u062f\u064d \u0635\u064e\u0644\u0651\u064e\u0649 \u0627\u0644\u0644\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0648\u064e\u0633\u064e\u0644\u0651\u064e\u0645\u064e. \u0627\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u0633\u0652\u0626\u064e\u0644\u064f\u0643\u064e \u0627\u0644\u0652\u0639\u064e\u0641\u0652\u0648\u064e\u0649 \u0648\u064e\u0627\u0644\u0652\u0639\u064e\u0627\u0641\u0650\u064a\u064e\u0629\u064e \u0627\u0644\u062f\u0651\u064e\u0627\u0626\u0650\u0645\u064e\u0629\u064e \u0641\u0650\u064a \u0627\u0644\u062f\u0651\u0650\u064a\u0652\u0646\u0650 \u0648\u064e\u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u062e\u0650\u0631\u064e\u0629\u064e \u0648\u064e\u0627\u0644\u0652\u0641\u064e\u0648\u0652\u0632\u064e \u0628\u0650\u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u062c\u064e\u0627\u0629\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650",latin:"",translation:"Maha suci Allah, segala bentuk pujian hanya pantas disanjungkan kepada-Nya, sebab tiada Tuhan selain Allah, Dzat Yang Maha Besar. Tidak ada daya dan kekuatan kecuali berasal dari sisi-Nya yang Maha Mulia lagi Maha Agung. Shalawat serta salam semoga senantiasa tertuju kepada Rasulullah, sebagaimana Allah selalu mencurahkan shalawat dan salam kepada beliau. Ya Allah, aku melakukan tawaf ini hanya karena beriman kepada-Mu, membenarkan kitab-Mu, dan memenuhi janjiku pada-Mu, serta mengikuti sunnah Nabi-Mu Muhammad Saw. Ya Allah, sesungguhnya aku memohon ampunan kepada-Mu, kesehatan, danperlindungan yang kekal dalam menjalankan aturan agama, baik urusan dunia maupun akhiratku, juga untuk beroleh kenikmatan surga dan terhindar dari azab neraka.",notes:"",fawaid:"",source:"Kumpulan Doa Sehari-hari, Kemenag Jatim \xb7 kategori Haji/Umroh"},{title:"Doa Thawaf 2",arabic:"\u0627\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u064e\u064e \u0647\u064e\u0630\u064e\u0627 \u0627\u0644\u0652\u0628\u064e\u064a\u0652\u062a\u064e \u0628\u064e\u064a\u0652\u062a\u064f\u0643\u064e \u0648\u064e\u0627\u0644\u0652\u062d\u064e\u0631\u064e\u0627\u064e\u0645 \u062d\u064e\u0631\u064e\u0627\u0645\u064f\u0643\u064e \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0646\u064e \u0623\u064e\u0645\u0652\u0646\u064f\u0643\u064e \u0648\u064e\u0627\u0644\u0652\u0639\u064e\u0628\u0652\u062f\u064e \u0639\u064e\u0628\u0652\u062f\u064f\u0643\u064e \u0648\u064e\u0623\u064e\u0646\u064e\u0627 \u0639\u064e\u0628\u0652\u062f\u064f\u0643\u064e \u0648\u064e\u0627\u0628\u0652\u0646\u064f \u0639\u064e\u0628\u0652\u062f\u0650\u0643\u064e \u0648\u064e\u0647\u064e\u0630\u064e\u0627 \u0645\u064e\u0642\u064e\u0627\u0645\u064f \u0639\u064e\u064a\u0652\u0630\u064f\u0643\u064e \u0628\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0641\u064e\u062d\u064e\u0631\u0651\u0650\u0645\u0652 \u0644\u064f\u062d\u064f\u0648\u0645\u064f\u0646\u064e\u0627 \u0648\u064e\u0628\u064e\u0634\u0651\u0650\u0631\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u062d\u064e\u0628\u0651\u0650\u0628\u0652 \u0625\u0650\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0625\u064a\u0652\u0645\u064e\u0627\u0646\u064e \u0648\u064e\u0632\u064e\u064a\u0651\u0650\u0646\u0652\u0647\u064f \u0641\u0650\u064a \u0642\u064e\u0644\u064f\u0648\u0628\u0650\u0646\u064e\u0627 \u0648\u064e\u0643\u064e\u0631\u0651\u0650\u0647\u0652 \u0625\u0650\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0643\u064f\u0641\u0652\u0631\u064e \u0648\u064e\u0627\u0644\u0652\u0641\u064f\u0633\u064f\u0648\u0642\u064e \u0648\u064e\u0627\u0644\u0652\u0639\u0650\u0635\u0652\u064a\u064e\u0627\u0646\u064e \u0648\u064e\u0627\u062c\u0652\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0631\u0651\u064e\u0627\u0634\u0650\u062f\u0650\u064a\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0642\u0650\u0646\u0650\u064a \u0639\u064e\u0630\u064e\u0627\u0628\u064e\u0643\u064e \u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u064e \u062a\u064e\u0628\u0652\u0639\u064e\u062b\u064f \u0639\u0650\u0628\u064e\u0627\u062f\u064e\u0643\u064e \u0627\u0644\u0644\u0651\u064f\u0647\u064f\u0645\u0651\u064e \u0627\u0631\u0652\u0632\u064f\u0642\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u064e \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u062d\u0650\u0633\u064e\u0627\u0628\u064d",latin:"",translation:"Ya Allah, sesungguh ya Ka\u2019bah ini adalah rumah-Mu, tanah yang mulia di sekitarnya adalah tanah-Mu, negeri yang aman ini adalah negeri-Mu, hamba ini adalah hamba-Mu, anak dari hamba-Mu, dan tempat ini adalah tempat para hamba berlindung kepada-Mu dari siksa api neraka. Haramkanlah daging dan kulit kami dari jilatan api neraka. Ya Allah, cintakanlah kami kepada iman dan biarkanlah keimanan itu menghiasi hati kami. Tanamkanlah kebencian terhadap perbuatan kufur, fasik, dan durhaka kepada-Mu, dan masukkanlah kami ke dalam golongan hamba-Mu yang mendapat petunjuk. Ya Allah, lindungilah aku dari azab-Mu pada hari Engkau kelak membangkitkan hamba-hamba-Mu. Ya Allah, anugerahkanlah surga kepadaku tanpa melalui perhitungan.",notes:"",fawaid:"",source:"Kumpulan Doa Sehari-hari, Kemenag Jatim \xb7 kategori Haji/Umroh"},{title:"Doa Thawaf 3",arabic:"\u0627\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646 \u0627\u0644\u0634\u0651\u064e\u0643\u0651\u0650 \u0648\u064e\u0627\u0644\u0634\u0650\u0631\u0652\u0643\u0650 \u0648\u0627\u0644\u0634\u0651\u0650\u0642\u064e\u0627\u0642\u0650 \u0648\u0627\u0644\u0646\u0651\u0650\u0641\u064e\u0627\u0642\u0650 \u0648\u0633\u064f\u0648\u0621\u0650 \u0627\u0644\u0623\u064e\u062e\u0652\u0644\u0627\u064e\u0642\u0650 \u0648\u064e\u0633\u064f\u0648\u0621\u0650 \u0627\u0644\u0645\u064e\u0646\u0652\u0638\u064e\u0631\u0650 \u0648\u064e\u0627\u0644\u0645\u064f\u0646\u0652\u0642\u064e\u0644\u0650\u0628\u0650 \u0641\u0650\u064a \u0627\u0644\u0645\u064e\u0627\u0644\u0650 \u0648\u0627\u0644\u0623\u064e\u0647\u0652\u0644\u0650 \u0648\u0627\u0644\u0648\u064e\u0644\u064e\u062f\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u0633\u0652\u0623\u0644\u064f\u0643\u064e \u0631\u0650\u0636\u064e\u0627\u0643\u064e \u0648\u0627\u0644\u062c\u064e\u0646\u0651\u064e\u0629\u064e \u0648\u0623\u064e\u0639\u064f\u0648\u0630\u064f\u0628\u0650\u0643\u064e \u0645\u0650\u0646 \u0633\u064e\u062e\u064e\u0637\u0650\u0643\u064e \u0648\u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0648\u064e\u0627\u0627\u0644\u0647\u064e\u0645\u0651\u0650 \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u0639\u064f\u0648\u0630\u064f\u0628\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0641\u0650\u062a\u0652\u0646\u064e\u0629\u0650 \u0627\u0644\u0642\u064f\u0628\u064f\u0631\u0650 \u0648\u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646 \u0641\u0650\u062a\u0652\u0646\u064e\u0629\u0650 \u0627\u0644\u0645\u064e\u062d\u0652\u064a\u064e\u0627 \u0648\u0627\u0644\u0645\u064e\u0645\u064e\u0627\u062a\u0650",latin:"",translation:"Ya Allah, aku berlindung kepada-Mu dari keraguan syirik, bantah-bantahan, kemunafikan, akhlak yang buruk, dan penampilan serta kondisi kembali yang buruk, dalam hubungannya dengan harta benda, keluarga, dan anak-anak. Ya Allah, sesungguhnya aku memohon kepada-Mu keridhaan-Mu dan surga. Aku juga berlindung kepada-Mu dari murka-Mu dan siksa api neraka. Ya Allah, aku berlidung kepada-Mu dari fitnah kehidupan dan derita kematian.",notes:"",fawaid:"",source:"Kumpulan Doa Sehari-hari, Kemenag Jatim \xb7 kategori Haji/Umroh"},{title:"Doa Thawaf 4",arabic:"\u0627\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0627\u062c\u0652\u0639\u064e\u0644\u0652\u0646\u0650\u064a \u062d\u064e\u062c\u0651\u064b\u0627 \u0645\u064e\u0628\u0652\u0631\u064f\u0648\u0631\u064b\u0627 \u0648\u064e\u0633\u064e\u0639\u0652\u064a\u0627\u064b \u0645\u064e\u0634\u0652\u0643\u064f\u0648\u0631\u064b\u0627 \u0648\u064e\u0630\u064f\u0646\u064f\u0628\u0627\u064b \u0645\u064e\u063a\u0652\u0641\u064f\u0648\u0631\u064b\u0627 \u0648\u064e\u0639\u064e\u0645\u064e\u0644\u064b\u0627 \u0635\u064e\u0627\u0644\u0650\u062d\u064b\u0627 \u0645\u064e\u0642\u0652\u0628\u064f\u0648\u0644\u064b\u0627 \u0648\u064e\u062a\u0650\u062c\u064b\u0627\u0631\u064e\u0629\u064b \u0644\u064b\u0646\u0652 \u062a\u064e\u0628\u064f\u0648\u0631\u064b\u0627. \u064a\u064e\u0627 \u0639\u064e\u0627\u0644\u0650\u0645\u064b \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0635\u0651\u064f\u062f\u064f\u0648\u0631\u0650\u0650 \u0623\u064e\u062e\u0652\u0631\u0650\u062c\u0652\u0646\u0650\u064a \u0645\u0650\u0646 \u0627\u0644\u0638\u0651\u064f\u0644\u064f\u0645\u064e\u0627\u062a\u0650 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0646\u064f\u0648\u0631\u0650\u060c \u0627\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064e \u0645\u064f\u0648\u062c\u0650\u0628\u064e\u0627\u062a\u0650 \u0631\u064e\u062d\u0652\u0645\u064e\u062a\u0650\u0643\u064e \u0648\u064e\u0639\u064e\u0632\u064e\u0627\u0626\u0650\u0645\u064e \u0645\u064e\u063a\u0652\u0641\u0650\u0631\u064e\u062a\u0650\u0643\u064e \u0648\u064e\u0627\u0644\u0633\u0651\u064e\u0644\u0627\u064e\u0645\u064e\u0629\u064e \u0645\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u0625\u0650\u062b\u0652\u0645\u064d \u0648\u0627\u0644\u063a\u064e\u0646\u0650\u064a\u0645\u064e\u0629\u064e \u0645\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u0628\u0650\u0631\u0651\u064d \u0648\u0627\u0644\u0641\u064e\u0648\u0652\u0632\u064e \u0628\u0650\u0627\u0644\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u0645\u0650\u0646 \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0631\u064e\u0628\u0651\u0650\u064a \u0642\u064e\u0646\u0651\u0650\u0639\u0652\u0646\u0650\u064a \u0628\u0650\u0645\u064e\u0627 \u0631\u064e\u0632\u064e\u0641\u064e\u0646\u0650\u064a \u0648\u064e\u0628\u064e\u0627\u0631\u0650\u0643\u0652 \u0644\u0650\u064a \u0641\u0650\u064a\u0645\u064e\u0627 \u0623\u064e\u0639\u0652\u0637\u064e\u064a\u0652\u062a\u064e\u0646\u0650\u064a \u0648\u064e\u0627\u062e\u0652\u0644\u064f\u0641\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0643\u064f\u0644\u0651\u064e \u063a\u064e\u064a\u0652\u0628\u064e\u0629\u064d \u0645\u0650\u0646\u0652\u0643\u064e \u0628\u0650\u062e\u064e\u064a\u0652\u0631\u064d",latin:"",translation:"Ya Allah, karunikanlah kepada kami haji yang mabrur, sa\u2019i yang diterima, dosa yang diampuni, amal saleh yang diterima, dan usaha yang tidak mengalami kerugian. Wahai Tuhan Yang Maha Mengetahui segala yang terkandung dalam sanubari, keluarkanlah aku dari kegelapan menuju cahaya yang terang bendenrang. Ya Allah, aku memohon kepada-Mu segala urusan yang mendatangkan kasih sayang-Mu dan keteguhan ampunan-Mu, selamat dari segala desa dan beruntung karena memperoleh surga dan terhindar dari siksa api neraka. Ya Tuhanku, puaskanlah aku dengan anugerah yang telah Engkau berikan dan berkatilah untukku semua yang Engkau anugerahkan anugerahkan kepadaku dan gantilah segala yang terlepas dari pandanganku dengan kebaikan yang berasal dari sisi-Mu.",notes:"",fawaid:"",source:"Kumpulan Doa Sehari-hari, Kemenag Jatim \xb7 kategori Haji/Umroh"},{title:"Doa Thawaf 5",arabic:"\u0623\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0623\u064e\u0638\u0650\u0644\u0651\u064e\u0646\u0650\u064a \u062a\u064e\u062d\u0652\u062a\u064e \u0638\u0650\u0644\u0651\u0650 \u0639\u064e\u0631\u0652\u0634\u0650\u0643\u064e \u064a\u064e\u0648\u0652\u0645\u064e \u0644\u0627\u064e \u0638\u0650\u0644\u0651\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0638\u0650\u0644\u0651\u064e\u0643\u064e \u0648\u064e\u0644\u064e\u0627 \u0628\u064e\u0642\u0650\u064a\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0648\u064e\u062c\u0652\u0647\u064e\u0643\u064e \u0648\u064e\u0623\u064e\u0633\u0652\u0641\u0650\u0646\u0650\u064a \u0645\u0650\u0646\u0652 \u062d\u064e\u0648\u0652\u0636\u0650 \u0646\u064e\u0628\u0650\u064a\u0651\u0650\u0643\u064e \u0645\u064f\u062d\u064e\u0645\u0651\u064e\u062f\u064d \u0635\u064e\u0644\u0651\u064e\u0649 \u0627\u0644\u0644\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0648\u0633\u064e\u0644\u0651\u064e\u0645 \u0634\u064f\u0631\u0652\u0628\u064e\u0629\u064b \u0647\u064e\u0646\u0650\u064a\u0626\u064e\u0629\u064b \u0645\u064e\u0631\u0650\u064a\u0626\u064e\u0629\u064b \u0644\u064e\u0627 \u0623\u064e\u0638\u064e\u0624\u064f \u0628\u064e\u0639\u0652\u062f\u064e\u0647\u064e\u0627 \u0623\u064e\u0628\u064e\u062f\u064b\u0627. \u0623\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064e \u0645\u0650\u0646\u0652 \u062e\u064e\u064a\u0652\u0631\u064d \u0645\u064e\u0627 \u0633\u064e\u0623\u064e\u0644\u064e\u0643\u064e \u0645\u0650\u0646\u0647\u064f \u0646\u064e\u0628\u0650\u064a\u0651\u064f\u0643\u064e \u0645\u064f\u062d\u064e\u0645\u0651\u064e\u062f\u064c \u0635\u064e\u0644\u0651\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0648\u064e\u0633\u064e\u0644\u0651\u064e\u0645\u064e \u0648\u064e\u0623\u064e\u0639\u064f\u0648\u064f\u0630\u064f\u0628\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0634\u064e\u0631\u0651\u0650 \u0645\u064e\u0627 \u0639\u064e\u0627\u0630\u064e\u0643\u064e \u0645\u0650\u0646\u0652\u0647\u064f \u0646\u064e\u0628\u0650\u064a\u0651\u064f\u0643\u064e \u0645\u064f\u062d\u064e\u0645\u0651\u064e\u062f\u064c \u0635\u064e\u0644\u0651\u064e\u0649 \u0627\u0644\u0644\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0648\u064e\u0633\u064e\u0644\u0651\u064e\u0645\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064e \u0627\u0644\u062c\u064e\u0646\u0651\u064e\u0629\u064e \u0648\u064e\u0646\u064e\u0639\u0650\u064a\u0645\u064e\u0647\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0642\u064e\u0631\u0651\u0650\u0628\u064f\u0646\u0650\u064a \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0648\u0652\u0644\u064d \u0623\u064e\u0648\u0652 \u0641\u0650\u0639\u0652\u0644\u064d \u0623\u064e\u0648\u0652 \u0639\u064e\u0645\u064e\u0644\u064d \u0648\u064e\u0623\u064e\u0639\u064f\u0648\u0630\u064f\u0628\u0650\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0642\u064e\u0631\u0651\u0650\u0628\u064f\u0646\u0650\u064a \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u0645\u0650\u0646\u0652 \u0642\u064e\u0648\u0652\u0644\u064d \u0623\u064e\u0652\u0648 \u0641\u0650\u0639\u0652\u0644\u064d \u0623\u064e\u0648\u0652 \u0639\u064e\u0645\u064e\u0644\u064d",latin:"",translation:"Ya Allah, lindungilah aku di bawah naungan singgasana-Mu pada hari ketika tak ada naungan selain naungan-Mu dan tidak ada yang kekal kecuali Dzat-Mu. Berikanlah aku minuman dari telaga Nabi-Mu, Muhammad Saw dengan minuman yang lezat, segar, dan nyaman, yang sesudah itu aku tidak akan merasa kehausan selamanya. Ya Allah, aku memohon kepada-Mu kebaikan yang domohonkan oleh Nabi-Mu, Muhammad Saw dan keburukan yang dimintakan perlindungan kepada-Mu. Ya Allah, aku memohon kepada-Mu surga serta kenikmatannya dan apa saja yang dapat mendekatkan aku kepadanya, baik ucapan maupun perbuatan, dan aku juga berlindung kepada-Mu dari api neraka serta apa saya yang mendekatkan aku kepadanya baik ucapan maupun perbuatan.",notes:"",fawaid:"",source:"Kumpulan Doa Sehari-hari, Kemenag Jatim \xb7 kategori Haji/Umroh"},{title:"Doa Thawaf 6",arabic:"\u0627\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0643\u064e \u0639\u064e\u0644\u064e\u064a\u0651\u064e \u062d\u064f\u0642\u064f\u0648\u0642\u064b\u0627 \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627 \u0641\u0650\u064a\u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u0650\u064a \u0648\u064e\u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064e \u0648\u064e\u062d\u064f\u0642\u064f\u0648\u0642\u064b\u0627 \u0643\u062b\u064a\u0631\u0627 \u0641\u0650\u064a\u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u0650\u064a \u0648\u064e\u0628\u064e\u064a\u0652\u0646\u064e \u062e\u064e\u0644\u0652\u0642\u0650\u0643\u064e \u0627\u0644\u0651\u064e\u0644\u0647\u064f\u0645\u0651\u064e \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0643\u064e \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0641\u064e\u0627\u063a\u0652\u0641\u0650\u0631\u0652\u0647\u064f \u0644\u0650\u064a \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u062e\u064e\u0644\u0652\u0642\u0650\u0643\u064e \u0648\u064e\u062a\u064e\u062d\u064e\u0645\u0651\u064e\u0644\u064e\u0647\u064f \u0639\u064e\u0646\u0651\u0650\u064a \u0648\u064e\u0623\u064e\u063a\u0652\u0646\u0650\u0646\u0650\u064a \u0628\u0650\u062d\u064e\u0644\u064e\u0627\u0644\u0650\u0643\u064e \u0639\u064e\u0646\u0652 \u062d\u064e\u0631\u064e\u0627\u0645\u0650\u0643\u064e \u0648\u064e\u0628\u0650\u0637\u064e\u0627\u0639\u064e\u062a\u0650\u0643\u064e \u0639\u0646\u0652 \u0645\u064e\u0639\u0652\u0635\u0650\u064a\u064e\u062a\u0650\u0643\u064e \u0648\u064e\u0628\u0650\u0641\u064e\u0636\u0652\u0644\u0650\u0643\u064e \u0639\u064e\u0645\u0651\u064e\u0646\u0652 \u0633\u0650\u0648\u064e\u0627\u0643\u064e \u064a\u064e\u0627 \u0648\u064e\u0627\u0633\u0650\u0639\u064e \u0627\u0644\u0645\u064e\u063a\u0652\u0641\u0650\u0631\u064e\u0629\u0650 \u0627\u0644\u0644\u0651\u064e\u064e\u0647\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u064e \u0628\u064e\u064a\u0652\u062a\u064e\u0643\u064e \u0639\u064e\u0638\u0650\u064a\u0645\u064c \u0648\u064e\u0648\u064e\u062c\u0652\u0647\u064e\u0643\u064e \u0643\u064e\u0631\u0650\u064a\u0652\u0645\u064c \u0648\u064e\u0623\u064e\u0646\u0652\u062a\u064e \u064a\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e\u064e \u062d\u064e\u0644\u0650\u064a\u0645\u064c \u0643\u064e\u0631\u0650\u064a\u0645\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u064c \u062a\u064f\u062d\u0650\u0628\u0651\u064f \u0627\u0644\u0639\u064e\u0641\u0652\u0648\u064e \u0641\u064e\u0627\u0639\u0652\u0641\u064f \u0639\u064e\u0646\u0651\u064e\u0627",latin:"",translation:"Ya Allah, sesungguhnya Eanhkau mempunyai banyak sekali hak dalam hubunganku dengan-Mu dan dengan makhluk-Mu. Ya Allah, apa yang menjadi hak-Mu kepadaku maka ampunilah diriku jika melalikannya. dan apa saja yang menjadi hak-Mu kepada makhluk-Mu maka tangguhkanlah dariku. Cukupkanlah aki dengan rezeki darisisi-Mu yang halal, terhindar dari kemaksiatan, dan dengan anugerah-Mu aku terhindar dari harapan terhadap selain Engkau, wahai Zat yang Maha Pengampun. Ya ALlah, sesungguhnya rumah-Mu (Ka\u2019bah) ini sangat agung, Zat-Mu pun Maha Mulia, Engkau penyabar, Maha Pemurah, dan Maha Agung, serta sangat suka memberi ampunan, maafkan dan ampunilah aku.",notes:"",fawaid:"",source:"Kumpulan Doa Sehari-hari, Kemenag Jatim \xb7 kategori Haji/Umroh"},{title:"Doa Thawaf 7",arabic:"\u0627\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064e \u0625\u0650\u064a\u0652\u0645\u064e\u0627\u0646\u0627\u064b \u0643\u064e\u0627\u0645\u0650\u0644\u064b\u0627 \u0648\u064e\u064a\u064e\u0642\u0650\u064a\u0646\u064b\u0627 \u0635\u064e\u0627\u062f\u0650\u0642\u064b\u0627 \u0648\u064e\u0631\u0650\u0632\u0652\u0642\u064b\u0627 \u0648\u064e\u0627\u0633\u0650\u0639\u064b\u0627 \u0648\u064e\u0642\u064e\u0644\u0652\u0628\u064b\u0627 \u062e\u064e\u0627\u0634\u0650\u0639\u064b\u0627 \u0648\u0644\u0650\u0633\u064e\u0627\u0646\u064b\u0627 \u0630\u064e\u0627\u0643\u0650\u0631\u064b\u0627 \u0648\u064e\u062d\u064e\u0644\u064e\u0627\u0644\u064b\u0627 \u0637\u064e\u064a\u0651\u0650\u0628\u064b\u0627 \u0648\u064e\u062a\u064e\u0648\u0652\u0628\u064e\u0629\u064b \u0646\u064e\u0635\u064f\u0648\u062d\u064b\u0627 \u0648\u064e\u062a\u064e\u0648\u0652\u0628\u064e\u0629\u064b \u0642\u064e\u0628\u0652\u0644\u064e \u0627\u0644\u0645\u064e\u0648\u0652\u062a\u0650 \u0648\u064e\u0631\u064e\u0627\u062d\u064e\u0629\u064b \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0645\u064e\u0648\u0652\u062a\u0650 \u0648\u064e\u0645\u064e\u063a\u0652\u0641\u0650\u0631\u064e\u0629\u064b \u0648\u064e\u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064b \u0628\u064e\u0639\u0652\u062f\u064e \u0627\u0644\u064e\u0645\u0648\u0652\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0639\u064e\u0641\u0652\u0648\u064e \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u062d\u0650\u0633\u0627\u064e\u0628\u0650 \u0648\u0627\u064e\u0644\u0641\u064e\u0648\u0652\u0632\u064e \u0628\u0650\u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u062c\u064e\u0627\u0629\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0628\u0650\u0631\u064e\u062d\u0652\u0645\u064e\u062a\u0650\u0643\u064e \u064a\u064e\u0627 \u0639\u064e\u0632\u0650\u064a\u0652\u0632\u064f \u0628\u0650\u0627\u0652\u0644\u0635\u064e\u0627\u0644\u0650\u062d\u0650\u064a\u0646\u064e",latin:"",translation:"Ya Allah, aku memohon kepada-Mu iman yang sempurna, keyakinan yang benar, rezeki yang luas, hati yang khusuk, lisan yang selalu berzikir mengagungkan nama-Mu, rezeki yang halal dan baik, taubat yang diterima, taubat sebelum mati, ampunan pada saat diadakan perhitungan amal, keberuntungan memperoleh surga, rahmat dan kasih sayang-Mu, wahai Tuhan yang Maha Perkasa lagi Maha Pengampun. Ya Allah, berilah aku tambahan ilmu pengetahuan dan gabungkanlah aku ke dalam hamba-hamba-Mu yang saleh.",notes:"",fawaid:"",source:"Kumpulan Doa Sehari-hari, Kemenag Jatim \xb7 kategori Haji/Umroh"},{title:"Doa Wukuf",arabic:"\u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064f \u0645\u064e\u0627 \u062f\u064e\u0639\u064e\u0627 \u0628\u0650\u0647\u0650 \u0631\u064e\u0633\u064f\u0648\u0644\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0635\u064e\u0644\u0651\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0648\u064e\u0633\u064e\u0644\u0651\u064e\u0645\u064e \u0639\u064e\u0634\u0650\u064a\u0651\u064e\u0629\u064e \u0639\u064e\u0631\u064e\u0641\u064e\u0629\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u0642\u0650\u0641\u0650 : \u201d \u0627\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0644\u064e\u0643\u064e \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0643\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0646\u064e\u0642\u064f\u0648\u0644\u064f \u0648\u064e\u062e\u064e\u064a\u0652\u0631\u064b\u0627 \u0645\u0650\u0645\u0651\u064e\u0627 \u0646\u064e\u0642\u064f\u0648\u0644\u064f \u060c \u0627\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0644\u064e\u0643\u064e \u0635\u064e\u0644\u064e\u0627\u062a\u0650\u064a \u0648\u064e\u0646\u064f\u0633\u064f\u0643\u0650\u064a \u0648\u064e\u0645\u064e\u062d\u0652\u064a\u064e\u0627\u064a\u064e \u0648\u064e\u0645\u064e\u0645\u064e\u0627\u062a\u0650\u064a \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0645\u064e\u0622\u0628\u0650\u064a \u0648\u064e\u0644\u064e\u0643\u064e \u0631\u064e\u0628\u0651\u0650 \u062a\u064f\u0631\u064e\u0627\u062b\u0650\u064a \u060c \u0627\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0627\u0644\u0652\u0642\u064e\u0628\u0652\u0631\u0650 \u0648\u064e\u0648\u064e\u0633\u0652\u0648\u064e\u0633\u064e\u0629\u0650 \u0627\u0644\u0635\u0651\u064e\u062f\u0652\u0631\u0650 \u0648\u064e\u0634\u064e\u062a\u064e\u0627\u062a\u0650 \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0631\u0650 \u060c \u0627\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0634\u064e\u0631\u0651\u0650 \u0645\u064e\u0627 \u062a\u064e\u062c\u0650\u064a\u0621\u064f \u0628\u0650\u0647\u0650 \u0627\u0644\u0631\u0651\u0650\u064a\u062d\u064f",latin:"",translation:"Ya Allah, segala puji untukMu, seperti apa yang Engkau firmankan dan yang baik dari apa-apa yang kami ucapkan. Ya Allah, bagi-Mu shalatku, ibadahku, hidupku dan matiku dan kepada-Mu tempat kembaliku dan kepada-Mulah pemeliharaan apa yang aku tinggalkan. Ya Allah, aku berlindung kepadaMu dari siksa kubur, dan keragu-raguan dalam hati serta kesulitan segala urusan. Ya Allah, aku berlindung kepada-Mu dari kejahatan yang dihembuskan oleh angin.",notes:"",fawaid:"",source:"Kumpulan Doa Sehari-hari, Kemenag Jatim \xb7 kategori Haji/Umroh"}]},1280,[]);
__d(function(a,n,i,l,e,t,k){e.exports=[{title:"Doa Sapu Jagat",arabic:"\u0631\u064e\u0628\u064e\u0651\u0646\u064e\u0627 \u0622\u064e\u062a\u0650\u0646\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u062f\u064f\u0651\u0646\u0652\u064a\u064e\u0627 \u062d\u064e\u0633\u064e\u0646\u064e\u0629\u064b \u0648\u064e\u0641\u0650\u064a \u0627\u0644\u0652\u0622\u064e\u062e\u0650\u0631\u064e\u0629\u0650 \u062d\u064e\u0633\u064e\u0646\u064e\u0629\u064b \u0648\u064e\u0642\u0650\u0646\u064e\u0627 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0627\u0644\u0646\u064e\u0651\u0627\u0631\u0650",latin:"Rabban\u0101 \u0101tin\u0101 f\u012bdduny\u0101 \u1e25asanah wa f\u012bl\u0101khirati \u1e25asanah waqin\u0101 'a\u017c\u0101bann\u0101r",translation:"Ya Allah, berikanlah kepada kami kebaikan di dunia, berikan pula kebaikan di akhirat dan lindungilah kami dari siksa neraka.",notes:null,fawaid:"Doa ini adalah doa yang paling sering dipanjatkan oleh Nabi Shallallahu 'alaihi wa sallam, sebagaimana penuturan sahabat Anas bin Malik radhiyallahu 'anhu.",source:"QS. Al-Baqarah: 201, al-Bukhari: 6389, HR. Muslim: 2690"},{title:"Doa Memohon Ketetapan Hati #1",arabic:"\u064a\u064e\u0627 \u0645\u064f\u0642\u064e\u0644\u0651\u0650\u0628\u064e \u0627\u0644\u0652\u0642\u064f\u0644\u064f\u0648\u0628\u0650 \u062b\u064e\u0628\u0651\u0650\u062a\u0652 \u0642\u064e\u0644\u0652\u0628\u0650\u0649 \u0639\u064e\u0644\u064e\u0649 \u062f\u0650\u064a\u0646\u0650\u0643\u064e",latin:"Y\u0101 muqallibal qul\u016bb \u1e61abbit qalb\u012b 'al\u0101 d\u012bnik",translation:"Wahai Dzat yang Maha membolak-balikkan hati, teguhkanlah hatiku di atas agama-Mu.",notes:null,fawaid:"Hati seseorang berada diantara jemari-jemari Allah ta'ala, dan Dia membolak-balikkan sesuai dengan kehendak-Nya. Maka, sudah selayaknya seseorang untuk senantiasa memohon agar Allah tetapkan hatinya di atas kebaikan, dan senantiasa istiqamah dalam kebenaran.",source:"HR. at-Tirmidzi, No. 3522 dan Ahmad, 6: 315"},{title:"Doa Memohon Ketetapan Hati #2",arabic:"\u0627\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0645\u064f\u0635\u064e\u0631\u0651\u0650\u0641\u064e \u0627\u0644\u0652\u0642\u064f\u0644\u064f\u0648\u0628\u0650 \u0635\u064e\u0631\u0651\u0650\u0641\u0652 \u0642\u064f\u0644\u064f\u0648\u0628\u064e\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0637\u064e\u0627\u0639\u064e\u062a\u0650\u0643\u064e",latin:"All\u0101humma mu\u1e63arrifal qul\u016bb \u1e63arrif qul\u016bban\u0101 'al\u0101 \u1e6d\u0101'\u0101tika",translation:"Ya Allah, Dzat yang memalingkan hati, palingkanlah hati kami kepada ketaatan beribadah kepada-Mu.",notes:null,fawaid:"Hati seseorang berada diantara jemari-jemari Allah ta'ala, dan Dia membolak-balikkan sesuai dengan kehendak-Nya. Maka, sudah selayaknya seseorang untuk senantiasa memohon agar Allah tetapkan hatinya di atas kebaikan, dan senantiasa istiqamah dalam kebenaran.",source:"HR. Muslim No. 2654"},{title:"Doa Memohon Ketetapan Hati #3",arabic:"\u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0644\u064e\u0627 \u062a\u064f\u0632\u0650\u063a\u0652 \u0642\u064f\u0644\u064f\u0648\u0628\u064e\u0646\u064e\u0627 \u0628\u064e\u0639\u0652\u062f\u064e \u0625\u0650\u0630\u0652 \u0647\u064e\u062f\u064e\u064a\u0652\u062a\u064e\u0646\u064e\u0627",latin:"Rabban\u0101 l\u0101 tuzigh qul\u016bban\u0101 ba'da i\u017c hadaytan\u0101",translation:"Ya Tuhan kami, janganlah Engkau jadikan hati kami condong kepada kesesatan sesudah Engkau beri petunjuk kepada kami.",notes:null,fawaid:"Hati seseorang berada diantara jemari-jemari Allah ta'ala, dan Dia membolak-balikkan sesuai dengan kehendak-Nya. Maka, sudah selayaknya seseorang untuk senantiasa memohon agar Allah tetapkan hatinya di atas kebaikan, dan senantiasa istiqamah dalam kebenaran.",source:"QS. Ali Imran: 8"},{title:"Doa Berlindung dari Hilangnya Kenikmatan",arabic:"\u0627\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u0650\u0649 \u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0632\u064e\u0648\u064e\u0627\u0644\u0650 \u0646\u0650\u0639\u0652\u0645\u064e\u062a\u0650\u0643\u064e \u0648\u064e\u062a\u064e\u062d\u064e\u0648\u0651\u064f\u0644\u0650 \u0639\u064e\u0627\u0641\u0650\u064a\u064e\u062a\u0650\u0643\u064e \u0648\u064e\u0641\u064f\u062c\u064e\u0627\u0621\u064e\u0629\u0650 \u0646\u0650\u0642\u0652\u0645\u064e\u062a\u0650\u0643\u064e \u0648\u064e\u062c\u064e\u0645\u0650\u064a\u0639\u0650 \u0633\u064e\u062e\u064e\u0637\u0650\u0643\u064e",latin:"All\u0101humma inn\u012b a'\u016b\u017cu bika min zaw\u0101li ni'matika, wa ta\u1e25awwuli '\u0101fiyatika, wa fuj\u0101'ati niqmatik, wa jam\u012b'i sakha\u1e6dik",translation:"Ya Allah, sesungguhnya aku berlindung kepada-Mu dari hilangnya kenikmatan yang telah Engkau berikan, dari berubahnya kesehatan yang telah Engkau anugerahkan, dari siksa-Mu yang datang secara tiba-tiba, dan dari segala kemurkaan-Mu.",notes:null,fawaid:"Kenikmatan yang ada saat ini sangat mungkin hilang, sehatnya jiwa raga dalam sekejap matapun sangat bisa berubah menjadi sakit, dan hanya Allah lah yang mampu mencegah itu terjadi.",source:"HR. Muslim No. 2739"},{title:"Doa Tolak Bala' (Cobaan yang Berat)",arabic:"\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0625\u0650\u0646\u0650\u0651\u064a \u0623\u064e\u0639\u064f\u0648\u0652\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u062c\u064e\u0647\u0652\u062f\u0650 \u0627\u0644\u0628\u064e\u0644\u0627\u064e\u0621\u0650 \u060c \u0648\u064e\u062f\u064e\u0631\u064e\u0643\u0650 \u0627\u0644\u0634\u064e\u0651\u0642\u064e\u0627\u0621\u0650 \u060c \u0648\u064e\u0633\u064f\u0648\u0621\u0650 \u0627\u0644\u0642\u064e\u0636\u064e\u0627\u0621\u0650 \u060c \u0648\u064e\u0634\u064e\u0645\u064e\u0627\u062a\u064e\u0629\u0650 \u0627\u0644\u0623\u064e\u0639\u0652\u062f\u064e\u0627\u0621",latin:"All\u0101humma inn\u012b a'\u016b\u017cu bika min jahdil bal\u0101', wa darakisy syaq\u0101', wa s\u016b'il qa\u1e0d\u0101', wa syam\u0101tatil a'd\u0101'",translation:"Ya Allah, aku berlindung kepada-Mu dari bencana yang sangat berat, kesengsaraan, dan segala faktor penyebabnya, dari buruknya akibat apa yang telah ditakdirkan, serta bahagianya musuh atas musibah yang menimpa diriku.",notes:null,fawaid:"Berlindung dari ketentuan takdir yang berdampak buruk, tidak bertentangan dengan sikap ridha terhadap ketentuan takdir Allah azza wa jalla. Karena meminta perlindungan dari ketentuan takdir yang buruk juga merupakan ketentuan takdir Allah. Allah azza wa jalla bisa saja mentakdirkan suatu bala' kepada seseorang, namun Allah azza wa jalla juga bisa mentakdirkan bahwa bila ia berdoa, Allah akan hilangkan bala' tersebut.",source:"HR. al-Bukhari: 6616, Muslim: 2707"},{title:"Doa Agar Terlepas Dari Lilitan Hutang, Kegundahan, Kelemahan, Rasa Malas, Takut, dan Tekanan Orang Lain",arabic:"\u0627\u064e\u0644\u0644\u0651\u0670\u0647\u064f\u0645\u064e\u0651 \u0625\u0650\u0646\u0650\u0651\u0649 \u0623\u064e\u0639\u064f\u0648\u0652\u0630\u064f\u0628\u0650\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0647\u064e\u0645\u0650\u0651 \u0648\u064e\u0627\u0644\u0652\u062d\u064e\u0632\u0652\u0646\u0650 \u0648\u064e\u0623\u064e\u0639\u064f\u0648\u0652\u0630\u064f\u0628\u0650\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0639\u064e\u062c\u0652\u0632\u0650 \u0648\u064e\u0627\u0644\u0652\u0643\u064e\u0633\u064e\u0644\u0650 \u0648\u064e\u0623\u064e\u0639\u064f\u0648\u0652\u0630\u064f\u0628\u0650\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062c\u064f\u0628\u0652\u0646\u0650 \u0648\u064e\u0627\u0644\u0652\u0628\u064f\u062e\u0652\u0644\u0650 \u0648\u064e\u0623\u064e\u0639\u064f\u0648\u0652\u0630\u064f\u0628\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u063a\u064e\u0644\u064e\u0628\u064e\u062a\u0650 \u0627\u0644\u062f\u064e\u0651\u064a\u0652\u0646\u0650 \u0648\u064e\u0642\u064e\u0647\u0652\u0631\u0650 \u0627\u0644\u0631\u062c\u0627\u0644",latin:"All\u0101humma inn\u012b a'\u016b\u017cu bika minal hammi wal \u1e25azan, wa a'\u016b\u017cu bika minal 'ajzi wal kasal, wa a'\u016b\u017cu bika minal jubni wal bukhl, wa a'\u016b\u017cu bika min ghalabatiddayni wa qahrirrij\u0101l",translation:"Ya Allah, aku berlindung kepada-Mu dari kebingungan dan kesedihan, aku berlindung kepada-Mu dari kelemahan dan kemalasan, aku berlindung kepada-Mu dari ketakutan dan kekikiran, aku berlindung kepada-Mu dari lilitan hutang dan tekanan orang-orang.",notes:null,fawaid:"Sahabat yang mulia Abu Umamah yang meriwayatkan hadits ini menuturkan: setelah aku mengamalkan doa itu, Allah benar-benar menghilangkan kebingunganku dan memberikanku kemampuan melunasi hutang.",source:"HR. Abu Dawud No. 1555"},{title:"Doa Ketika Mendapatkan Sesuatu yang Menyenangkan",arabic:"\u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u0649 \u0628\u0650\u0646\u0650\u0639\u0652\u0645\u064e\u062a\u0650\u0647\u0650 \u062a\u064e\u062a\u0650\u0645\u0651\u064f \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u064f",latin:"Alhamdulill\u0101hilla\u017c\u012b bini'matih\u012b tatimmu\u1e63\u1e63\u0101li\u1e25\u0101t",translation:"Segala puji bagi Allah, dimana dengan nikmatnya kebaikan menjadi sempurna.",notes:null,fawaid:"Aisyah radhiyallahu 'anha mengatakan, Rasulullah shallallahu 'alaihi wa sallam apabila melihat sesuatu yang beliau sukai, beliau membaca kalimat di atas.",source:"HR. Ibnu Majah dalam Sunannya, No. 3803 dan al-Hakim dalam al-Mustadrak (1/499)"}]},1281,[]);
__d(function(a,i,n,l,u,h,e){u.exports=[{title:"Doa Naik Kendaraan",arabic:"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u0650\u060c \u0627\u064e\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u064e\u0651\u0647\u0650 (\u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0627\u0644\u064e\u0651\u0630\u0650\u064a\u0652 \u0633\u064e\u062e\u064e\u0651\u0631\u064e \u0644\u064e\u0646\u064e\u0627 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u064e\u0651\u0627 \u0644\u064e\u0647\u064f \u0645\u064f\u0642\u0652\u0631\u0650\u0646\u0650\u064a\u0652\u0646\u064e. \u0648\u064e\u0625\u0650\u0646\u064e\u0651\u0627 \u0625\u0650\u0644\u064e\u0649 \u0631\u064e\u0628\u0650\u0651\u0646\u064e\u0627 \u0644\u064e\u0645\u064f\u0646\u0652\u0642\u064e\u0644\u0650\u0628\u064f\u0648\u0652\u0646\u064e) \u0627\u064e\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u064e\u0651\u0647\u0650\u060c \u0627\u064e\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u064e\u0651\u0647\u0650\u060c \u0627\u064e\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u064e\u0651\u0647\u0650\u060c \u0627\u064e\u0644\u0644\u064e\u0651\u0647\u064f \u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064f\u060c \u0627\u064e\u0644\u0644\u064e\u0651\u0647\u064f \u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064f\u060c \u0627\u064e\u0644\u0644\u064e\u0651\u0647\u064f \u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064f\u060c \u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e\u0643\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0625\u0650\u0646\u0650\u0651\u064a\u0652 \u0638\u064e\u0644\u064e\u0645\u0652\u062a\u064f \u0646\u064e\u0641\u0652\u0633\u0650\u064a\u0652 \u0641\u064e\u0627\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u0650\u064a\u0652\u060c \u0641\u064e\u0625\u0650\u0646\u064e\u0651\u0647\u064f \u0644\u0627\u064e \u064a\u064e\u063a\u0652\u0641\u0650\u0631\u064f \u0627\u0644\u0630\u064f\u0651\u0646\u064f\u0648\u0652\u0628\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0623\u064e\u0646\u0652\u062a\u064e",latin:"Bismillaah, alhamdulillaah, (subhaanal-ladzii sakh-khoro lanaa haadzaa wa maa kunnaa lahu muqriniin. Wa innaa ilaa robbinaa lamunqolibuun), alhamdulillaah (3x), allaahu akbar (3x), subhaanakallaahumma innii zholamtu nafsii faghfir lii, fa-innahu laa yaghfirudz-dzunuuba illaa anta.",translation:"Dengan nama Allah, segala puji bagi Allah, (Maha Suci Tuhan yang menundukkan kendaraan ini untuk kami, padahal kami sebelumnya tidak mampu menguasainya. Dan sesungguhnya kami akan kembali kepada Tuhan kami (di hari Kiamat)). Segala puji bagi Allah (3x), Allah Maha Besar (3x), Maha Suci Engkau ya Allah, sesungguhnya aku menganiaya diriku, maka ampunilah aku. Sesungguhnya tidak ada yang mengampuni dosa-dosa kecuali Engkau.",notes:"",fawaid:"",source:"HR. Abu Dawud 3/34, At-Tirmidzi 5/501, dan lihat Shahih At-Tirmidzi 3/156. Sumber: Hisnul Muslim"},{title:"Doa Musafir Kepada Orang Yang Ditinggalkan",arabic:"\u0623\u064e\u0633\u0652\u062a\u064e\u0648\u0652\u062f\u0650\u0639\u064f\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0652 \u0644\u0627\u064e \u062a\u064e\u0636\u0650\u064a\u0652\u0639\u064f \u0648\u064e\u062f\u064e\u0627\u0626\u0650\u0639\u064f\u0647\u064f",latin:"Astaudi'ukumullaahal-ladzii laa tadhii'u wa daa-i'uh.",translation:"Aku menitipkan kamu kepada Allah yang tidak akan hilang titipan-Nya.",notes:"",fawaid:"",source:"HR. Ahmad 2/403, Ibnu Majah 2/943, dan lihat Shahih Ibnu Majah 2/133.\n\nSumber: Hisnul Muslim."},{title:"Doa Orang Mukim Kepada Musafir",arabic:"\u0623\u064e\u0633\u0652\u062a\u064e\u0648\u0652\u062f\u0650\u0639\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u062f\u0650\u064a\u0652\u0646\u064e\u0643\u064e \u0648\u064e\u0623\u064e\u0645\u064e\u0627\u0646\u064e\u062a\u064e\u0643\u064e \u0648\u064e\u062e\u064e\u0648\u064e\u0627\u062a\u0650\u064a\u0652\u0645\u064e \u0639\u064e\u0645\u064e\u0644\u0650\u0643\u064e",latin:"Astaudi'ullaaha diinaka wa amaanataka wa khowaatiima 'amalik.",translation:"Aku menitipkan agamamu, amanatmu dan penutup amalmu kepada Allah.",notes:"",fawaid:"",source:"HR. At-Tirmidzi 2/7, At-Tirmidzi 5/499, dan lihat Shahih At-Tirmidzi 2/155.\n\nSumber: Hisnul Muslim."},{title:"Doa Bepergian",arabic:"\u0627\u064e\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064f\u060c \u0627\u064e\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064f\u060c \u0627\u064e\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064f\u060c (\u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0652 \u0633\u064e\u062e\u0651\u064e\u0631\u064e \u0644\u064e\u0646\u064e\u0627 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0644\u064e\u0647\u064f \u0645\u064f\u0642\u0652\u0631\u0650\u0646\u0650\u064a\u0652\u0646\u064e. \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0625\u0650\u0644\u064e\u0649 \u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627 \u0644\u064e\u0645\u064f\u0646\u0652\u0642\u064e\u0644\u0650\u0628\u064f\u0648\u0652\u0646\u064e) \u0627\u064e\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u064e\u0627 \u0646\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064e \u0641\u0650\u064a\u0652 \u0633\u064e\u0641\u064e\u0631\u0650\u0646\u064e\u0627 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0627\u0644\u0652\u0628\u0650\u0631\u0651\u064e \u0648\u064e\u0627\u0644\u062a\u0651\u064e\u0642\u0652\u0648\u064e\u0649\u060c \u0648\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0639\u064e\u0645\u064e\u0644\u0650 \u0645\u064e\u0627 \u062a\u064e\u0631\u0652\u0636\u064e\u0649\u060c \u0627\u064e\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0647\u064e\u0648\u0651\u0650\u0646\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0633\u064e\u0641\u064e\u0631\u064e\u0646\u064e\u0627 \u0647\u064e\u0640\u0670\u0630\u064e\u0627 \u0648\u064e\u0627\u0637\u0652\u0648\u0650 \u0639\u064e\u0646\u0651\u064e\u0627 \u0628\u064f\u0639\u0652\u062f\u064e\u0647\u064f\u060c \u0627\u064e\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0623\u064e\u0646\u0652\u062a\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u062d\u0650\u0628\u064f \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0641\u064e\u0631\u0650 \u0648\u064e\u0627\u0644\u0652\u062e\u064e\u0644\u0650\u064a\u0652\u0641\u064e\u0629\u064f \u0641\u0650\u064a \u0627\u0652\u0644\u0623\u064e\u0647\u0652\u0644\u0650\u060c \u0627\u064e\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u0650\u064a\u0652 \u0623\u064e\u0639\u064f\u0648\u0652\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0648\u064e\u0639\u0652\u062b\u064e\u0627\u0621\u0650 \u0627\u0644\u0633\u0651\u064e\u0641\u064e\u0631\u0650 \u0648\u064e\u0643\u064e\u0622\u0628\u064e\u0629\u0650 \u0627\u0644\u0652\u0645\u064e\u0646\u0652\u0638\u064e\u0631\u0650 \u0648\u064e\u0633\u064f\u0648\u0652\u0621\u0650 \u0627\u0644\u0652\u0645\u064f\u0646\u0652\u0642\u064e\u0644\u064e\u0628\u0650 \u0641\u0650\u064a \u0627\u0644\u0652\u0645\u064e\u0627\u0644\u0650 \u0648\u064e\u0627\u0652\u0644\u0623\u064e\u0647\u0652\u0644\u0650",latin:"Allaahu akbar (3x), (subhaanal-ladzii sakh-khoro lanaa haadzaa wa maa kunnaa lahu muqriniin. Wa innaa ilaa robbinaa lamunqolibuun), allaahumma innaa nas-aluka fii safarinaa haadzal birro wat-taqwaa, wa minal 'amali maa tardhoo, allaahumma hawwin 'alainaa safaronaa haadzaa wathwi 'annaa bu'dah, allaahumma antash-shoohibu fis-safari wal kholiifatu fil ahli, allaahumma innii a'uudzu bika min wa'tsaa-is-safari wa ka-aabatil manzhori wa suu-il munqolabi fil maali wal ahli.",translation:"Allah Maha Besar (3x). (Maha Suci Tuhan yang menundukkan kendaraan ini untuk kami, padahal kami sebelumnya tidak mampu menguasainya. Dan sesungguhnya kami akan kembali kepada Tuhan kami (di hari Kiamat)). Ya Allah, sesungguhnya kami memohon kebaikan dan taqwa dalam bepergian ini, kami mohon perbuatan yang meridhakanMu. Ya Allah, permudahlah perjalanan kami ini, dan dekatkan jaraknya bagi kami. Ya Allah, Engkaulah teman dalam bepergian dan yang mengurusi keluarga(ku). Ya Allah, sesungguhnya aku berlindung kepada-Mu dari kelelahan dalam bepergian, pemandangan yang menyedihkan dan kepulangan yang jelek dalam harta dan keluarga.",notes:"",fawaid:"",source:"Apabila kembali dari bepergian, doa di atas dibaca, dan ditambah:\n\n\u0622\u064a\u0650\u0628\u064f\u0648\u0652\u0646\u064e \u062a\u064e\u0627\u0626\u0650\u0628\u064f\u0648\u0652\u0646\u064e \u0639\u064e\u0627\u0628\u0650\u062f\u064f\u0648\u0652\u0646\u064e \u0644\u0650\u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627 \u062d\u064e\u0627\u0645\u0650\u062f\u064f\u0648\u0652\u0646\u064e\n\nAayibuuna taa-ibuuna 'aabiduuna lirobbinaa haamiduun.\n\nKami kembali dengan bertaubat, tetap beribadah dan selalu memuji kepada Tuhan kami.\n\n\nHR. Muslim 2/998.\n\nSumber: Hisnul Muslim."},{title:"Doa Musafir Menjelang Subuh",arabic:"\u0633\u064e\u0645\u0651\u064e\u0639\u064e \u0633\u064e\u0627\u0645\u0650\u0639\u064c \u0628\u0650\u062d\u064e\u0645\u0652\u062f\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650\u060c \u0648\u064e\u062d\u064f\u0633\u0652\u0646\u0650 \u0628\u064e\u0644\u0627\u064e\u0626\u0650\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627. \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0635\u064e\u0627\u062d\u0650\u0628\u0652\u0646\u064e\u0627\u060c \u0648\u064e\u0623\u064e\u0641\u0652\u0636\u0650\u0644\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0639\u064e\u0627\u0626\u0650\u0630\u064b\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650",latin:"Samma'a saami'un bihamdillaah, wa husni balaa-ihi 'alainaa. robbanaa shoohibnaa, wa afdhil 'alainaa 'aa-idzan billaahi minan-naar.",translation:"Semoga ada yang memperdengarkan puji kami kepada Allah (atas nikmat) dan cobaanNya yang baik bagi kami. Wahai Tuhan kami, temanilah kami (peliharalah kami) dan berilah karunia kepada kami dengan berlindung kepada Allah dari api Neraka.",notes:"",fawaid:"",source:"HR. Muslim 4/2086, Syarah An-Nawawi 17/39.\n\nSumber: Hisnul Muslim."},{title:"Doa Singgah Di Suatu Tempat, Baik Dalam Bepergian Ataupun Tidak",arabic:"\u0623\u064e\u0639\u064f\u0648\u0652\u0630\u064f \u0628\u0650\u0643\u064e\u0644\u0650\u0645\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0627\u0644\u062a\u0651\u064e\u0627\u0645\u0651\u064e\u0627\u062a\u0650 \u0645\u0650\u0646\u0652 \u0634\u064e\u0631\u0651\u0650 \u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u064e",latin:"A'uudzu bikalimaatillaahit-taammaati min syarri maa kholaq.",translation:"Aku berlindung dengan kalimat-kalimat Allah yang sempurna, dari kejahatan apa yang diciptakan-Nya.",notes:"",fawaid:"",source:"HR. Tirmidzi 3437 dan An Nasai 5433.\nDari Khaulah binti Hakim, bahwasanya Rasulullah shallallahu \u2018alaihi wasallam bersabda, \u201cBarang siapa yang singgah di sebuah tempat kemudian ia mengatakan: (doa di atas), niscaya tidak akan ada yang memudharatkannya.\u201d\n\n\nSumber: https://muslim.or.id/19063-dzikir-dan-doa-mohon-perlindungan-dari-bahaya.html"},{title:"Doa Masuk Desa Atau Kota",arabic:"\u0627\u064e\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0631\u064e\u0628\u0651\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0627\u0644\u0633\u0651\u064e\u0628\u0652\u0639\u0650 \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0638\u0652\u0644\u064e\u0644\u0652\u0646\u064e\u060c \u0648\u064e\u0631\u064e\u0628\u0651\u064e \u0627\u0652\u0644\u0623\u064e\u0631\u064e\u0636\u0650\u064a\u0652\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0628\u0652\u0639\u0650 \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0642\u0652\u0644\u064e\u0644\u0652\u0646\u064e\u060c \u0648\u064e\u0631\u064e\u0628\u0651\u064e \u0627\u0644\u0634\u0651\u064e\u064a\u064e\u0627\u0637\u0650\u064a\u0652\u0646\u0650 \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0636\u0652\u0644\u064e\u0644\u0652\u0646\u064e\u060c \u0648\u064e\u0631\u064e\u0628\u0651\u064e \u0627\u0644\u0631\u0651\u0650\u064a\u064e\u0627\u062d\u0650 \u0648\u064e\u0645\u064e\u0627 \u0630\u064e\u0631\u064e\u064a\u0652\u0646\u064e. \u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064e \u062e\u064e\u064a\u0652\u0631\u064e \u0647\u064e\u0640\u0670\u0630\u0650\u0647\u0650 \u0627\u0644\u0652\u0642\u064e\u0631\u0652\u064a\u064e\u0629\u0650 \u0648\u064e\u062e\u064e\u064a\u0652\u0631\u064e \u0623\u064e\u0647\u0652\u0644\u0650\u0647\u064e\u0627\u060c \u0648\u064e\u062e\u064e\u064a\u0652\u0631\u064e \u0645\u064e\u0627 \u0641\u0650\u064a\u0652\u0647\u064e\u0627\u060c \u0648\u064e\u0623\u064e\u0639\u064f\u0648\u0652\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0634\u064e\u0631\u0651\u0650\u0647\u064e\u0627 \u0648\u064e\u0634\u064e\u0631\u0651\u0650 \u0623\u064e\u0647\u0652\u0644\u0650\u0647\u064e\u0627 \u0648\u064e\u0634\u064e\u0631\u0651\u0650 \u0645\u064e\u0627 \u0641\u0650\u064a\u0652\u0647\u064e\u0627",latin:"Allaahumma robbas-samaawaatis-sab'i wa maa azhlalna, wa robbal arodhiinas-sab'i wa maa aqlalna, wa robbasy-syayaathiini wa maa adhlalna, wa robbar-riyaahi wa maa dzaroina. As-aluka khoiro haadzihil quryati wa khoiro ahlihaa, wa khoiro maa fiihaa, wa a'uudzu bika min syarrihaa wa syarri ahlihaa wa syarri maa fiihaa.",translation:"Ya Allah, Tuhan tujuh langit dan apa yang dinaunginya, Tuhan penguasa tujuh bumi dan apa yang di atasnya, Tuhan yang menguasai setan-setan dan apa yang mereka sesatkan, Tuhan yang menguasai angin dan apa yang diterbangkannya. Aku mohon kepadaMu kebaikan desa ini, kebaikan penduduknya dan apa yang ada di dalamnya. Aku berlindung kepadaMu dari kejelekan desa ini, kejelekan penduduknya dan apa yang ada di dalamnya.",notes:"",fawaid:"",source:"HR. Al-Hakim, menurut pendapatnya, hadits tersebut adalah sahih. Imam Adz-Dzahabi menyetujuinya 2/100, Ibnus Sunni, no. 524. Menurut Al-Hafizh Ibnu Hajar dalam Takhrij Adzkar 5/154: \"Hadits tersebut adalah hasan.\" Bin Baz berkata: Hadits itu diriwayatkan pula oleh An-Nasai dengan sanad yang hasan. Lihat Tuhfatul Akhyar, hal. 37.\n\nSumber: Hisnul Muslim."},{title:"Doa Masuk Pasar, Mall, Terminal, Bandara Dan Pusat Keramaian Lainnya",arabic:"\u0644\u0627\u064e \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e \u0625\u0650\u0644\u0627\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u062d\u0652\u062f\u064e\u0647\u064f \u0644\u0627\u064e \u0634\u064e\u0631\u0650\u064a\u0652\u0643\u064e \u0644\u064e\u0647\u064f\u060c \u0644\u064e\u0647\u064f \u0627\u0644\u0652\u0645\u064f\u0644\u0652\u0643\u064f \u0648\u064e\u0644\u064e\u0647\u064f \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u064a\u064f\u062d\u0652\u064a\u0650\u064a\u0652 \u0648\u064e\u064a\u064f\u0645\u0650\u064a\u0652\u062a\u064f \u0648\u064e\u0647\u064f\u0648\u064e \u062d\u064e\u064a\u0651\u064c \u0644\u0627\u064e \u064a\u064e\u0645\u064f\u0648\u0652\u062a\u064f\u060c \u0628\u0650\u064a\u064e\u062f\u0650\u0647\u0650 \u0627\u0644\u0652\u062e\u064e\u064a\u0652\u0631\u064f\u060c \u0648\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u0649 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0652\u0631\u064c",latin:"Laa ilaaha illallaah, wahdahu laa syariika lah, lahul mulku wa lahul hamd, yuhyii wa yumiit, wa huwa hayyun laa yamuut, biyadihil khoir, wa huwa 'alaa kulli syai-in qodiir.",translation:"Tidak ada sesembahan yang berhak disembah kecuali Allah, Yang Maha Esa, tiada sekutu bagiNya. BagiNya kerajaan, bagiNya segala pujian. Dia-lah Yang Menghidupkan dan Yang Mematikan. Dia-lah Yang Hidup, tidak akan mati. Di tanganNya kebaikan. Dia-lah Yang Maha kuasa atas segala sesuatu.",notes:"",fawaid:"",source:"HR. Turmudzi 5/291, Hakim 1/538, dan dihasankan al-Albani dalam shahih Turmudzi 3/152.\nDari Abdullah bin Umar radhiyallahu 'anhuma, bahwa Rasulullah shallallahu 'alaihi wa sallam bersabda: \"Siapa yang masuk pasar, kemudian dia membaca: (doa di atas), maka akan dicatat untuknya satu juta kebaikan, dihapuskan satu juta kesalahan, dan diangkat satu juta derajat.\"\n\nBisa anda bayangkan, dengan hanya membaca dzikir di atas ketika masuk pasar, kita bisa mendapatkan pahala yang sangat besar. Mengapa bisa demikian?\n\nSebagian ulama menjelaskan:\nOrang yang berdzikir ketika masuk pasar menunjukkan kedekatan yang sangat kuat antara orang ini dengan Allah. Di pasar, umumnya orang sibuk dengan dunia, dia masih mengingat Allah. Di pasar, umumnya orang lupa Allah, dia justru berdzikir kepada Allah. Di pasar, umumnya orang bermaksiat, dia justru mendekatkan diri kepada Allah. Dia mengingat Allah di tengah-tengah masyarakat yang lupa Allah. Dia berdzikir, di tengah-tengah orang yang lengah dengan ibadah.\n\nSikap semacam ini tidak mungkin bisa dilakukan kecuali oleh orang yang hatinya merasa diawasi oleh Allah dan rajin dalam membasahi lidahnya dengan dzikir. Karena itu, layaklah orang ini mendapatkan imbalan yang besar di sisi Allah. (Tajridul Ittiba', Ibrahim Ibrahim ar-Ruhaili).\n\nCatatan:\nMemperbanyak dzikir juga berlaku ketika anda memasuki daerah yang umumnya manusia lupa Allah, seperti tempat rekreasi, terminal, bandara, mall, dst.\n\nManfaatkan kesempatan besar di tengah kelengahan masyarakat, untuk mendapatkan pahala yang berharga di sisi Allah. Karena itu, biasakan lisan anda untuk selalu basah dengan dzikir.\n\n\nSumber: http://www.facebook.com/doa.dzikir.shahih.harian/posts/146376235462443"},{title:"Doa Bila Binatang Atau Kendaraan Tergelincir",arabic:"\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650",latin:"Bismillaah.",translation:"Dengan nama Allah.",notes:"",fawaid:"",source:"HR. Abu Dawud 4/296 dan Al-Albani menyatakan, hadits tersebut shahih dalam Shahih Abi Dawud 3/941.\n\nSumber: Hisnul Muslim."},{title:"Doa Pulang Dari Bepergian",arabic:"Di atas tempat yang tinggi, membaca:\n\n\u0627\u064e\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064f\u060c \u0627\u064e\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064f\u060c \u0627\u064e\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064f. \u0644\u0627\u064e \u0625\u0650\u0644\u064e\u0640\u0670\u0647\u064e \u0625\u0650\u0644\u0627\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u062d\u0652\u062f\u064e\u0647\u064f \u0644\u0627\u064e \u0634\u064e\u0631\u0650\u064a\u0652\u0643\u064e \u0644\u064e\u0647\u064f\u060c \u0644\u064e\u0647\u064f \u0627\u0644\u0652\u0645\u064f\u0644\u0652\u0643\u064f \u0648\u064e\u0644\u064e\u0647\u064f \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0648\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u0649 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0652\u0631\u064c. \u0622\u064a\u0650\u0628\u064f\u0648\u0652\u0646\u064e \u062a\u064e\u0627\u0626\u0650\u0628\u064f\u0648\u0652\u0646\u064e \u0639\u064e\u0627\u0628\u0650\u062f\u064f\u0648\u0652\u0646\u064e \u0644\u0650\u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627 \u062d\u064e\u0627\u0645\u0650\u062f\u064f\u0648\u0652\u0646\u064e\u060c \u0635\u064e\u062f\u064e\u0642\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0639\u0652\u062f\u064e\u0647\u064f \u0648\u064e\u0646\u064e\u0635\u064e\u0631\u064e \u0639\u064e\u0628\u0652\u062f\u064e\u0647\u064f \u0648\u064e\u0647\u064e\u0632\u064e\u0645\u064e \u0627\u0652\u0644\u0623\u064e\u062d\u0652\u0632\u064e\u0627\u0628\u064e \u0648\u064e\u062d\u0652\u062f\u064e\u0647\u064f",latin:"Allaahu akbar (3x). Laa ilaaha illallaah, wahdahu laa syariika lah, lahul mulku wa lahul hamdu, wa huwa 'alaa kulli syai-in qodiir. Aayibuuna taa-ibuuna 'aabiduuna lirobbinaa haamiduun, shodaqollaahu wa'dah, wa nashoro 'abdah, wa hazamal ahzaaba wahdah.",translation:"Allah Maha Besar (3x). Tidak ada sesembahan yang berhak disembah kecuali Allah, Yang Maha Esa, tiada sekutu bagiNya. Bagi-Nya kerajaan dan pujaan. Dia-lah Yang Mahakuasa atas segala sesuatu. Kami kembali dengan bertaubat, beribadah dan memuji kepada Tuhan kami. Allah telah menepati janjiNya, membela hambaNya (Muhammad) dan mengalahkan golongan musuh dengan sendirian.",notes:"",fawaid:"",source:"HR. Al-Bukhari 7/163, Muslim 2/980.\n\nSumber: Hisnul Muslim."}]},1282,[]);
__d(function(g,r,i,a,m,_e,d){"use strict";function e(e){return e&&e.__esModule?e:{default:e}}Object.defineProperty(_e,'__esModule',{value:!0}),_e.DuaIconBadge=function({icon:e="book-outline"}){return(0,u.jsx)(t.default,{style:c.outer,children:(0,u.jsx)(t.default,{style:c.inner,children:(0,u.jsx)(o.Ionicons,{name:e,size:21,color:l.colors.navy})})})};var o=r(d[0]),n=e(r(d[1])),t=e(r(d[2])),l=r(d[3]),u=r(d[4]);const c=n.default.create({outer:{width:48,height:48,padding:3,borderRadius:24,borderWidth:1.5,borderColor:l.colors.gold,backgroundColor:"#F8F1DC"},inner:{flex:1,borderRadius:20,borderWidth:1,borderColor:"#E8C967",alignItems:"center",justifyContent:"center"}})},1283,[797,28,109,796,6]);
__d(function(a,n,e,i,t,k,r){t.exports=[{id:1,name:"\u0627\u0644\u0641\u0627\u062a\u062d\u0629",transliteration:"Al-Fatihah",translation:"Pembukaan",type:"meccan",total_verses:7,verses:[{id:1,text:"\u0628\u0650\u0633\u06e1\u0645\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u0650 \u0671\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650",translation:"Dengan nama Allah Yang Maha Pengasih, Maha Penyayang"},{id:2,text:"\u0671\u0644\u06e1\u062d\u064e\u0645\u06e1\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0631\u064e\u0628\u0651\u0650 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Segala puji bagi Allah, Tuhan seluruh alam"},{id:3,text:"\u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u0650 \u0671\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650",translation:"Yang Maha Pengasih, Maha Penyayang"},{id:4,text:"\u0645\u064e\u0670\u0644\u0650\u0643\u0650 \u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u0650",translation:"Pemilik hari pembalasan"},{id:5,text:"\u0625\u0650\u064a\u0651\u064e\u0627\u0643\u064e \u0646\u064e\u0639\u06e1\u0628\u064f\u062f\u064f \u0648\u064e\u0625\u0650\u064a\u0651\u064e\u0627\u0643\u064e \u0646\u064e\u0633\u06e1\u062a\u064e\u0639\u0650\u064a\u0646\u064f",translation:"Hanya kepada Engkaulah kami menyembah dan hanya kepada Engkaulah kami mohon pertolongan"},{id:6,text:"\u0671\u0647\u06e1\u062f\u0650\u0646\u064e\u0627 \u0671\u0644\u0635\u0651\u0650\u0631\u064e\u0670\u0637\u064e \u0671\u0644\u06e1\u0645\u064f\u0633\u06e1\u062a\u064e\u0642\u0650\u064a\u0645\u064e",translation:"Tunjukilah kami jalan yang lurus"},{id:7,text:"\u0635\u0650\u0631\u064e\u0670\u0637\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u0646\u06e1\u0639\u064e\u0645\u06e1\u062a\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u063a\u064e\u064a\u06e1\u0631\u0650 \u0671\u0644\u06e1\u0645\u064e\u063a\u06e1\u0636\u064f\u0648\u0628\u0650 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u0671\u0644\u0636\u0651\u064e\u0627\u0653\u0644\u0651\u0650\u064a\u0646\u064e",translation:"(yaitu) jalan orang-orang yang telah Engkau beri nikmat kepadanya; bukan (jalan) mereka yang dimurkai, dan bukan (pula jalan) mereka yang sesat"}]},{id:2,name:"\u0627\u0644\u0628\u0642\u0631\u0629",transliteration:"Al-Baqarah",translation:"Sapi Betina",type:"medinan",total_verses:286,verses:[{id:1,text:"\u0627\u0644\u0653\u0645\u0653",translation:"Alif L\u0101m M\u012bm"},{id:2,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064f \u0644\u064e\u0627 \u0631\u064e\u064a\u06e1\u0628\u064e\u06db \u0641\u0650\u064a\u0647\u0650\u06db \u0647\u064f\u062f\u0657\u0649 \u0644\u0651\u0650\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",translation:"Kitab (Alquran) ini tidak ada keraguan padanya; petunjuk bagi mereka yang bertakwa"},{id:3,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u0628\u0650 \u0648\u064e\u064a\u064f\u0642\u0650\u064a\u0645\u064f\u0648\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u0645\u0650\u0645\u0651\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u064a\u064f\u0646\u0641\u0650\u0642\u064f\u0648\u0646\u064e",translation:"(Yaitu) mereka yang beriman kepada yang gaib, melaksanakan salat, dan menginfakkan6) sebagian rezeki yang Kami berikan kepada mereka"},{id:4,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0645\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064e \u0648\u064e\u0628\u0650\u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0647\u064f\u0645\u06e1 \u064a\u064f\u0648\u0642\u0650\u0646\u064f\u0648\u0646\u064e",translation:"dan mereka beriman kepada (Alquran) yang diturunkan kepadamu (Muhammad) dan (kitab-kitab) yang telah diturunkan sebelum engkau,7) dan mereka yakin akan adanya akhirat"},{id:5,text:"\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0647\u064f\u062f\u0657\u0649 \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1\u06d6 \u0648\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064f\u0641\u06e1\u0644\u0650\u062d\u064f\u0648\u0646\u064e",translation:"Merekalah yang mendapat petunjuk dari Tuhannya, dan mereka itulah orang-orang yang beruntung"},{id:6,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0633\u064e\u0648\u064e\u0627\u0653\u0621\u064c \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0621\u064e\u0623\u064e\u0646\u0630\u064e\u0631\u06e1\u062a\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u0645\u06e1 \u0644\u064e\u0645\u06e1 \u062a\u064f\u0646\u0630\u0650\u0631\u06e1\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"(Sesungguhnya orang-orang kafir,8) sama saja bagi mereka, engkau (Muhammad) beri peringatan atau tidak engkau beri peringatan, mereka tidak akan beriman"},{id:7,text:"\u062e\u064e\u062a\u064e\u0645\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0639\u064e\u0644\u064e\u0649\u0670 \u0633\u064e\u0645\u06e1\u0639\u0650\u0647\u0650\u0645\u06e1\u06d6 \u0648\u064e\u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0628\u06e1\u0635\u064e\u0670\u0631\u0650\u0647\u0650\u0645\u06e1 \u063a\u0650\u0634\u064e\u0670\u0648\u064e\u0629\u065e\u06d6 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u065e",translation:"(Allah telah mengunci hati dan pendengaran mereka,9) penglihatan mereka telah tertutup, dan mereka akan mendapat azab yang berat"},{id:8,text:"\u0648\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0645\u064e\u0646 \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0621\u064e\u0627\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0628\u0650\u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u0650 \u0648\u064e\u0645\u064e\u0627 \u0647\u064f\u0645 \u0628\u0650\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dan di antara manusia ada yang berkata, \"Kami beriman kepada Allah dan hari akhir,\" padahal sesungguhnya mereka itu bukanlah orang-orang yang beriman"},{id:9,text:"\u064a\u064f\u062e\u064e\u0670\u062f\u0650\u0639\u064f\u0648\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u062e\u06e1\u062f\u064e\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0634\u06e1\u0639\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Mereka menipu Allah dan orang-orang yang beriman, padahal mereka hanyalah menipu diri sendiri tanpa mereka sadari"},{id:10,text:"\u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645 \u0645\u0651\u064e\u0631\u064e\u0636\u065e \u0641\u064e\u0632\u064e\u0627\u062f\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0631\u064e\u0636\u0657\u0627\u06d6 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064f\u06e2 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0643\u06e1\u0630\u0650\u0628\u064f\u0648\u0646\u064e",translation:"(Dalam hati mereka terdapat penyakit,10) lalu Allah menambah penyakitnya itu; dan mereka mendapat azab yang pedih, karena mereka berdusta"},{id:11,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u062a\u064f\u0641\u06e1\u0633\u0650\u062f\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0646\u064e\u062d\u06e1\u0646\u064f \u0645\u064f\u0635\u06e1\u0644\u0650\u062d\u064f\u0648\u0646\u064e",translation:"(Dan apabila dikatakan kepada mereka, \"Janganlah berbuat kerusakan di bumi!\"11) Mereka menjawab, \"Sesungguhnya kami justru orang-orang yang melakukan perbaikan"},{id:12,text:"\u0623\u064e\u0644\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064f\u0641\u06e1\u0633\u0650\u062f\u064f\u0648\u0646\u064e \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u0644\u0651\u064e\u0627 \u064a\u064e\u0634\u06e1\u0639\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Ingatlah, sesungguhnya merekalah yang berbuat kerusakan, tetapi mereka tidak menyadari"},{id:13,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0621\u064e\u0627\u0645\u0650\u0646\u064f\u0648\u0627\u0652 \u0643\u064e\u0645\u064e\u0627\u0653 \u0621\u064e\u0627\u0645\u064e\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u064f\u0624\u06e1\u0645\u0650\u0646\u064f \u0643\u064e\u0645\u064e\u0627\u0653 \u0621\u064e\u0627\u0645\u064e\u0646\u064e \u0671\u0644\u0633\u0651\u064f\u0641\u064e\u0647\u064e\u0627\u0653\u0621\u064f\u06d7 \u0623\u064e\u0644\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0647\u064f\u0645\u064f \u0671\u0644\u0633\u0651\u064f\u0641\u064e\u0647\u064e\u0627\u0653\u0621\u064f \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u0644\u0651\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan apabila dikatakan kepada mereka, \"Berimanlah kamu sebagaimana orang lain yang telah beriman!\" Mereka menjawab, \"Apakah kami akan beriman seperti orang-orang yang kurang akal itu beriman?\" Ingatlah, sesungguhnya mereka itulah orang-orang yang kurang akal, tetapi mereka tidak tahu"},{id:14,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0644\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0621\u064e\u0627\u0645\u064e\u0646\u0651\u064e\u0627 \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062e\u064e\u0644\u064e\u0648\u06e1\u0627\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0634\u064e\u064a\u064e\u0670\u0637\u0650\u064a\u0646\u0650\u0647\u0650\u0645\u06e1 \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e\u0627 \u0645\u064e\u0639\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0646\u064e\u062d\u06e1\u0646\u064f \u0645\u064f\u0633\u06e1\u062a\u064e\u0647\u06e1\u0632\u0650\u0621\u064f\u0648\u0646\u064e",translation:"Dan apabila mereka berjumpa dengan orang yang beriman, mereka berkata, \"Kami telah beriman.\" Tetapi apabila mereka kembali kepada setan-setan (para pemimpin) mereka, mereka berkata, \"Sesungguhnya kami bersama kamu, kami hanya berolok-olok"},{id:15,text:"\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0633\u06e1\u062a\u064e\u0647\u06e1\u0632\u0650\u0626\u064f \u0628\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u064a\u064e\u0645\u064f\u062f\u0651\u064f\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0637\u064f\u063a\u06e1\u064a\u064e\u0670\u0646\u0650\u0647\u0650\u0645\u06e1 \u064a\u064e\u0639\u06e1\u0645\u064e\u0647\u064f\u0648\u0646\u064e",translation:"Allah akan memperolok-olokkan mereka dan membiarkan mereka terombang-ambing dalam kesesatan"},{id:16,text:"\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u0634\u06e1\u062a\u064e\u0631\u064e\u0648\u064f\u0627\u0652 \u0671\u0644\u0636\u0651\u064e\u0644\u064e\u0670\u0644\u064e\u0629\u064e \u0628\u0650\u0671\u0644\u06e1\u0647\u064f\u062f\u064e\u0649\u0670 \u0641\u064e\u0645\u064e\u0627 \u0631\u064e\u0628\u0650\u062d\u064e\u062a \u062a\u0651\u0650\u062c\u064e\u0670\u0631\u064e\u062a\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0645\u064f\u0647\u06e1\u062a\u064e\u062f\u0650\u064a\u0646\u064e",translation:"Mereka itulah yang membeli kesesatan dengan petunjuk. Maka perdagangan mereka itu tidak beruntung dan mereka tidak mendapat petunjuk"},{id:17,text:"\u0645\u064e\u062b\u064e\u0644\u064f\u0647\u064f\u0645\u06e1 \u0643\u064e\u0645\u064e\u062b\u064e\u0644\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0671\u0633\u06e1\u062a\u064e\u0648\u06e1\u0642\u064e\u062f\u064e \u0646\u064e\u0627\u0631\u0657\u0627 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u0636\u064e\u0627\u0653\u0621\u064e\u062a\u06e1 \u0645\u064e\u0627 \u062d\u064e\u0648\u06e1\u0644\u064e\u0647\u064f\u06e5 \u0630\u064e\u0647\u064e\u0628\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0646\u064f\u0648\u0631\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u062a\u064e\u0631\u064e\u0643\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0638\u064f\u0644\u064f\u0645\u064e\u0670\u062a\u0656 \u0644\u0651\u064e\u0627 \u064a\u064f\u0628\u06e1\u0635\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Perumpamaan mereka seperti orang-orang yang menyalakan api, setelah menerangi sekelilingnya, Allah melenyapkan cahaya (yang menyinari) mereka dan membiarkan mereka dalam kegelapan, tidak dapat melihat"},{id:18,text:"\u0635\u064f\u0645\u0651\u064f\u06e2 \u0628\u064f\u0643\u06e1\u0645\u064c \u0639\u064f\u0645\u06e1\u064a\u065e \u0641\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0631\u06e1\u062c\u0650\u0639\u064f\u0648\u0646\u064e",translation:"Mereka tuli, bisu dan buta, sehingga mereka tidak dapat kembali"},{id:19,text:"\u0623\u064e\u0648\u06e1 \u0643\u064e\u0635\u064e\u064a\u0651\u0650\u0628\u0656 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0641\u0650\u064a\u0647\u0650 \u0638\u064f\u0644\u064f\u0645\u064e\u0670\u062a\u065e \u0648\u064e\u0631\u064e\u0639\u06e1\u062f\u065e \u0648\u064e\u0628\u064e\u0631\u06e1\u0642\u065e \u064a\u064e\u062c\u06e1\u0639\u064e\u0644\u064f\u0648\u0646\u064e \u0623\u064e\u0635\u064e\u0670\u0628\u0650\u0639\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0653 \u0621\u064e\u0627\u0630\u064e\u0627\u0646\u0650\u0647\u0650\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0648\u064e\u0670\u0639\u0650\u0642\u0650 \u062d\u064e\u0630\u064e\u0631\u064e \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u0650\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064f\u062d\u0650\u064a\u0637\u064f\u06e2 \u0628\u0650\u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Atau seperti (orang yang ditimpa) hujan lebat dari langit, yang disertai kegelapan, petir dan kilat. Mereka menyumbat telinga dengan jari-jarinya, (menghindari) suara petir itu karena takut mati. Allah meliputi orang-orang yang kafir"},{id:20,text:"\u064a\u064e\u0643\u064e\u0627\u062f\u064f \u0671\u0644\u06e1\u0628\u064e\u0631\u06e1\u0642\u064f \u064a\u064e\u062e\u06e1\u0637\u064e\u0641\u064f \u0623\u064e\u0628\u06e1\u0635\u064e\u0670\u0631\u064e\u0647\u064f\u0645\u06e1\u06d6 \u0643\u064f\u0644\u0651\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0636\u064e\u0627\u0653\u0621\u064e \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u0634\u064e\u0648\u06e1\u0627\u0652 \u0641\u0650\u064a\u0647\u0650 \u0648\u064e\u0625\u0650\u0630\u064e\u0627\u0653 \u0623\u064e\u0638\u06e1\u0644\u064e\u0645\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0642\u064e\u0627\u0645\u064f\u0648\u0627\u0652\u06da \u0648\u064e\u0644\u064e\u0648\u06e1 \u0634\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0630\u064e\u0647\u064e\u0628\u064e \u0628\u0650\u0633\u064e\u0645\u06e1\u0639\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0623\u064e\u0628\u06e1\u0635\u064e\u0670\u0631\u0650\u0647\u0650\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0642\u064e\u062f\u0650\u064a\u0631\u065e",translation:"Hampir saja kilat itu menyambar penglihatan mereka. Setiap kali (kilat itu) menyinari, mereka berjalan di bawah (sinar) itu, dan apabila gelap menerpa mereka, mereka berhenti. Sekiranya Allah menghendaki, niscaya Dia hilangkan pendengaran dan penglihatan mereka. Sungguh, Allah Mahakuasa atas segala sesuatu"},{id:21,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0671\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0627\u0652 \u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064f\u0645\u06e1 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",translation:"Wahai manusia! Sembahlah Tuhanmu yang telah menciptakan kamu dan orang-orang yang sebelum kamu, agar kamu bertakwa"},{id:22,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0641\u0650\u0631\u064e\u0670\u0634\u0657\u0627 \u0648\u064e\u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u064e \u0628\u0650\u0646\u064e\u0627\u0653\u0621\u0657 \u0648\u064e\u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0645\u064e\u0627\u0653\u0621\u0657 \u0641\u064e\u0623\u064e\u062e\u06e1\u0631\u064e\u062c\u064e \u0628\u0650\u0647\u0650\u06e6 \u0645\u0650\u0646\u064e \u0671\u0644\u062b\u0651\u064e\u0645\u064e\u0631\u064e\u0670\u062a\u0650 \u0631\u0650\u0632\u06e1\u0642\u0657\u0627 \u0644\u0651\u064e\u0643\u064f\u0645\u06e1\u06d6 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062c\u06e1\u0639\u064e\u0644\u064f\u0648\u0627\u0652 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0646\u062f\u064e\u0627\u062f\u0657\u0627 \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"(Dialah) yang menjadikan bumi sebagai hamparan bagimu dan langit sebagai atap, dan Dialah yang menurunkan air (hujan) dari langit, lalu Dia hasilkan dengan (hujan) itu buah-buahan sebagai rezeki untukmu. Karena itu janganlah kamu mengadakan tandingan-tandingan bagi Allah, padahal kamu mengetahui"},{id:23,text:"\u0648\u064e\u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0641\u0650\u064a \u0631\u064e\u064a\u06e1\u0628\u0656 \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u0646\u064e\u0632\u0651\u064e\u0644\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0639\u064e\u0628\u06e1\u062f\u0650\u0646\u064e\u0627 \u0641\u064e\u0623\u06e1\u062a\u064f\u0648\u0627\u0652 \u0628\u0650\u0633\u064f\u0648\u0631\u064e\u0629\u0656 \u0645\u0651\u0650\u0646 \u0645\u0651\u0650\u062b\u06e1\u0644\u0650\u0647\u0650\u06e6 \u0648\u064e\u0671\u062f\u06e1\u0639\u064f\u0648\u0627\u0652 \u0634\u064f\u0647\u064e\u062f\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0635\u064e\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Dan jika kamu meragukan (Alquran) yang kami turunkan kepada hamba Kami (Muhammad), maka buatlah satu surah semisal dengannya dan ajaklah penolong-penolongmu selain Allah, jika kamu orang-orang yang benar"},{id:24,text:"\u0641\u064e\u0625\u0650\u0646 \u0644\u0651\u064e\u0645\u06e1 \u062a\u064e\u0641\u06e1\u0639\u064e\u0644\u064f\u0648\u0627\u0652 \u0648\u064e\u0644\u064e\u0646 \u062a\u064e\u0641\u06e1\u0639\u064e\u0644\u064f\u0648\u0627\u0652 \u0641\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u064e \u0671\u0644\u0651\u064e\u062a\u0650\u064a \u0648\u064e\u0642\u064f\u0648\u062f\u064f\u0647\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0648\u064e\u0671\u0644\u06e1\u062d\u0650\u062c\u064e\u0627\u0631\u064e\u0629\u064f\u06d6 \u0623\u064f\u0639\u0650\u062f\u0651\u064e\u062a\u06e1 \u0644\u0650\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Jika kamu tidak mampu membuatnya, dan (pasti) tidak akan mampu, maka takutlah kamu akan api neraka yang bahan bakarnya manusia dan batu yang disediakan bagi orang-orang kafir"},{id:25,text:"\u0648\u064e\u0628\u064e\u0634\u0651\u0650\u0631\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0623\u064e\u0646\u0651\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0656 \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0645\u0650\u0646 \u062a\u064e\u062d\u06e1\u062a\u0650\u0647\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u064f\u06d6 \u0643\u064f\u0644\u0651\u064e\u0645\u064e\u0627 \u0631\u064f\u0632\u0650\u0642\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0645\u0650\u0646 \u062b\u064e\u0645\u064e\u0631\u064e\u0629\u0656 \u0631\u0651\u0650\u0632\u06e1\u0642\u0657\u0627 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0631\u064f\u0632\u0650\u0642\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f\u06d6 \u0648\u064e\u0623\u064f\u062a\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6 \u0645\u064f\u062a\u064e\u0634\u064e\u0670\u0628\u0650\u0647\u0657\u0627\u06d6 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627\u0653 \u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u065e \u0645\u0651\u064f\u0637\u064e\u0647\u0651\u064e\u0631\u064e\u0629\u065e\u06d6 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u0670\u0644\u0650\u062f\u064f\u0648\u0646\u064e",translation:"Dan sampaikanlah kabar gembira kepada orang-orang yang beriman dan berbuat kebajikan, bahwa untuk mereka (disediakan) surga-surga yang mengalir di bawahnya sungai-sungai. Setiap kali mereka diberi rezeki buah-buahan dari surga, mereka berkata, \"Inilah rezeki yang diberikan kepada kami dahulu.\" Mereka telah diberi (buah-buahan) yang serupa. Dan di sana mereka (memperoleh) pasangan-pasangan yang suci. Mereka kekal di dalamnya"},{id:26,text:"\u06de\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u062d\u06e1\u064a\u0650\u06e6\u0653 \u0623\u064e\u0646 \u064a\u064e\u0636\u06e1\u0631\u0650\u0628\u064e \u0645\u064e\u062b\u064e\u0644\u0657\u0627 \u0645\u0651\u064e\u0627 \u0628\u064e\u0639\u064f\u0648\u0636\u064e\u0629\u0657 \u0641\u064e\u0645\u064e\u0627 \u0641\u064e\u0648\u06e1\u0642\u064e\u0647\u064e\u0627\u06da \u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0641\u064e\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1\u06d6 \u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0641\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0645\u064e\u0627\u0630\u064e\u0627\u0653 \u0623\u064e\u0631\u064e\u0627\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0647\u064e\u0670\u0630\u064e\u0627 \u0645\u064e\u062b\u064e\u0644\u0657\u0627\u06d8 \u064a\u064f\u0636\u0650\u0644\u0651\u064f \u0628\u0650\u0647\u0650\u06e6 \u0643\u064e\u062b\u0650\u064a\u0631\u0657\u0627 \u0648\u064e\u064a\u064e\u0647\u06e1\u062f\u0650\u064a \u0628\u0650\u0647\u0650\u06e6 \u0643\u064e\u062b\u0650\u064a\u0631\u0657\u0627\u06da \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0636\u0650\u0644\u0651\u064f \u0628\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u06e1\u0641\u064e\u0670\u0633\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Sesungguhnya Allah tidak segan membuat perumpamaan seekor nyamuk atau yang lebih kecil dari itu. Adapun orang-orang yang beriman, mereka tahu bahwa itu kebenaran dari Tuhan. Tetapi mereka yang kafir berkata, \"Apa maksud Allah dengan perumpamaan ini?\" Dengan (perumpamaan) itu banyak orang yang dibiarkan-Nya sesat,13) dan dengan itu banyak (pula) orang yang diberi-Nya petunjuk. Tetapi tidak ada yang Dia sesatkan dengan (perumpamaan) itu selain orang-orang fasik"},{id:27,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0646\u0642\u064f\u0636\u064f\u0648\u0646\u064e \u0639\u064e\u0647\u06e1\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0645\u0650\u064a\u062b\u064e\u0670\u0642\u0650\u0647\u0650\u06e6 \u0648\u064e\u064a\u064e\u0642\u06e1\u0637\u064e\u0639\u064f\u0648\u0646\u064e \u0645\u064e\u0627\u0653 \u0623\u064e\u0645\u064e\u0631\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0646 \u064a\u064f\u0648\u0635\u064e\u0644\u064e \u0648\u064e\u064a\u064f\u0641\u06e1\u0633\u0650\u062f\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06da \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u062e\u064e\u0670\u0633\u0650\u0631\u064f\u0648\u0646\u064e",translation:"(yaitu) orang\u2013orang yang melanggar perjanjian Allah setelah (perjanjian) itu diteguhkan, dan memutuskan apa yang diperintahkan Allah untuk disambungkan dan berbuat kerusakan di bumi. Mereka itulah orang-orang yang rugi"},{id:28,text:"\u0643\u064e\u064a\u06e1\u0641\u064e \u062a\u064e\u0643\u06e1\u0641\u064f\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u062a\u0657\u0627 \u0641\u064e\u0623\u064e\u062d\u06e1\u064a\u064e\u0670\u0643\u064f\u0645\u06e1\u06d6 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0645\u0650\u064a\u062a\u064f\u0643\u064f\u0645\u06e1 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u062d\u06e1\u064a\u0650\u064a\u0643\u064f\u0645\u06e1 \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u062a\u064f\u0631\u06e1\u062c\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Bagaimana kamu ingkar kepada Allah, padahal kamu (tadinya) mati, lalu dia menghidupkan kamu, kemudian Dia mematikan kamu lalu Dia menghidupkan kamu kembali. Kemudian kepada-Nyalah kamu dikembalikan"},{id:29,text:"\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u062c\u064e\u0645\u0650\u064a\u0639\u0657\u0627 \u062b\u064f\u0645\u0651\u064e \u0671\u0633\u06e1\u062a\u064e\u0648\u064e\u0649\u0670\u0653 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0641\u064e\u0633\u064e\u0648\u0651\u064e\u0649\u0670\u0647\u064f\u0646\u0651\u064e \u0633\u064e\u0628\u06e1\u0639\u064e \u0633\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0656\u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Dialah (Allah) yang menciptakan segala apa yang ada di bumi untuk kalian kemudian Dia menuju ke langit, lalu Dia menyempurnakannya menjadi tujuh langit. Dan Dia Maha Mengetahui segala sesuatu"},{id:30,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0644\u0650\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u0650 \u0625\u0650\u0646\u0651\u0650\u064a \u062c\u064e\u0627\u0639\u0650\u0644\u065e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u062e\u064e\u0644\u0650\u064a\u0641\u064e\u0629\u0657\u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u062a\u064e\u062c\u06e1\u0639\u064e\u0644\u064f \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u064e\u0646 \u064a\u064f\u0641\u06e1\u0633\u0650\u062f\u064f \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u064a\u064e\u0633\u06e1\u0641\u0650\u0643\u064f \u0671\u0644\u062f\u0651\u0650\u0645\u064e\u0627\u0653\u0621\u064e \u0648\u064e\u0646\u064e\u062d\u06e1\u0646\u064f \u0646\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u064f \u0628\u0650\u062d\u064e\u0645\u06e1\u062f\u0650\u0643\u064e \u0648\u064e\u0646\u064f\u0642\u064e\u062f\u0651\u0650\u0633\u064f \u0644\u064e\u0643\u064e\u06d6 \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan (ingatlah) ketika Tuhanmu berfirman kepada para Malaikat, \"Aku hendak menjadikan khalifah15) di bumi\". Mereka berkata, \"Apakah Engkau hendak menjadikan orang yang merusak dan menumpahkan darah di sana, sedangkan kami bertasbih memuji-Mu dan menyucikan nama-Mu?\" Dia berfirman, \"Sungguh, Aku mengetahui apa yang tidak kalian ketahui"},{id:31,text:"\u0648\u064e\u0639\u064e\u0644\u0651\u064e\u0645\u064e \u0621\u064e\u0627\u062f\u064e\u0645\u064e \u0671\u0644\u06e1\u0623\u064e\u0633\u06e1\u0645\u064e\u0627\u0653\u0621\u064e \u0643\u064f\u0644\u0651\u064e\u0647\u064e\u0627 \u062b\u064f\u0645\u0651\u064e \u0639\u064e\u0631\u064e\u0636\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u0650 \u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0646\u06e2\u0628\u0650\u0640\u0654\u064f\u0648\u0646\u0650\u064a \u0628\u0650\u0623\u064e\u0633\u06e1\u0645\u064e\u0627\u0653\u0621\u0650 \u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0635\u064e\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Dan Dia ajarkan kepada Adam nama-nama (benda) semuanya, kemudian Dia perlihatkan kepada para malaikat, seraya berfirman, \"Sebutkan kepada-Ku nama semua benda ini, jika kalian yang benar"},{id:32,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0633\u064f\u0628\u06e1\u062d\u064e\u0670\u0646\u064e\u0643\u064e \u0644\u064e\u0627 \u0639\u0650\u0644\u06e1\u0645\u064e \u0644\u064e\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0639\u064e\u0644\u0651\u064e\u0645\u06e1\u062a\u064e\u0646\u064e\u0627\u0653\u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0623\u064e\u0646\u062a\u064e \u0671\u0644\u06e1\u0639\u064e\u0644\u0650\u064a\u0645\u064f \u0671\u0644\u06e1\u062d\u064e\u0643\u0650\u064a\u0645\u064f",translation:"Mereka menjawab, \"Mahasuci Engkau, tidak ada yang kami ketahui selain apa yang telah Engkau ajarkan kepada kami. Sungguh, Engkaulah Yang Maha Mengetahui, Mahabijaksana"},{id:33,text:"\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0640\u0670\u0653\u0640\u0654\u064e\u0627\u062f\u064e\u0645\u064f \u0623\u064e\u0646\u06e2\u0628\u0650\u0626\u06e1\u0647\u064f\u0645 \u0628\u0650\u0623\u064e\u0633\u06e1\u0645\u064e\u0627\u0653\u0626\u0650\u0647\u0650\u0645\u06e1\u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u0646\u06e2\u0628\u064e\u0623\u064e\u0647\u064f\u0645 \u0628\u0650\u0623\u064e\u0633\u06e1\u0645\u064e\u0627\u0653\u0626\u0650\u0647\u0650\u0645\u06e1 \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0644\u064e\u0645\u06e1 \u0623\u064e\u0642\u064f\u0644 \u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u063a\u064e\u064a\u06e1\u0628\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u062a\u064f\u0628\u06e1\u062f\u064f\u0648\u0646\u064e \u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0643\u06e1\u062a\u064f\u0645\u064f\u0648\u0646\u064e",translation:"Dia (Allah) berfirman, \"Wahai Adam! Beritahukanlah kepada mereka nama-nama itu!\" Setelah dia (Adam) menyebutkan nama-namanya, Dia berfirman, \"Bukankah telah Aku katakan kepada kalian, bahwa Aku mengetahui rahasia langit dan bumi, dan Aku mengetahui apa yang kalian nyatakan dan apa yang kalian sembunyikan"},{id:34,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0642\u064f\u0644\u06e1\u0646\u064e\u0627 \u0644\u0650\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u0650 \u0671\u0633\u06e1\u062c\u064f\u062f\u064f\u0648\u0627\u0652 \u0644\u0650\u0623\u0653\u062f\u064e\u0645\u064e \u0641\u064e\u0633\u064e\u062c\u064e\u062f\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0625\u0650\u0628\u06e1\u0644\u0650\u064a\u0633\u064e \u0623\u064e\u0628\u064e\u0649\u0670 \u0648\u064e\u0671\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u064e\u0631\u064e \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan (ingatlah) ketika Kami berfirman kepada para malaikat, \"Sujudlah kalian kepada Adam!\" Maka mereka pun sujud kecuali Iblis.16) Ia menolak dan menyombongkan diri, dan ia termasuk golongan yang kafir"},{id:35,text:"\u0648\u064e\u0642\u064f\u0644\u06e1\u0646\u064e\u0627 \u064a\u064e\u0640\u0670\u0653\u0640\u0654\u064e\u0627\u062f\u064e\u0645\u064f \u0671\u0633\u06e1\u0643\u064f\u0646\u06e1 \u0623\u064e\u0646\u062a\u064e \u0648\u064e\u0632\u064e\u0648\u06e1\u062c\u064f\u0643\u064e \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u064e \u0648\u064e\u0643\u064f\u0644\u064e\u0627 \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0631\u064e\u063a\u064e\u062f\u064b\u0627 \u062d\u064e\u064a\u06e1\u062b\u064f \u0634\u0650\u0626\u06e1\u062a\u064f\u0645\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u06e1\u0631\u064e\u0628\u064e\u0627 \u0647\u064e\u0670\u0630\u0650\u0647\u0650 \u0671\u0644\u0634\u0651\u064e\u062c\u064e\u0631\u064e\u0629\u064e \u0641\u064e\u062a\u064e\u0643\u064f\u0648\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dan Kami berfirman: \"Wahai Adam! Tinggallah engkau dan istrimu di dalam surga, dan makanlah dengan nikmat (berbagai makanan) yang ada disana sesukamu. (Tetapi) janganlah kamu dekati pohon ini,17) nanti kamu termasuk orang-orang yang zalim"},{id:36,text:"\u0641\u064e\u0623\u064e\u0632\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u064e\u0627 \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u064f \u0639\u064e\u0646\u06e1\u0647\u064e\u0627 \u0641\u064e\u0623\u064e\u062e\u06e1\u0631\u064e\u062c\u064e\u0647\u064f\u0645\u064e\u0627 \u0645\u0650\u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u0650\u06d6 \u0648\u064e\u0642\u064f\u0644\u06e1\u0646\u064e\u0627 \u0671\u0647\u06e1\u0628\u0650\u0637\u064f\u0648\u0627\u0652 \u0628\u064e\u0639\u06e1\u0636\u064f\u0643\u064f\u0645\u06e1 \u0644\u0650\u0628\u064e\u0639\u06e1\u0636\u064d \u0639\u064e\u062f\u064f\u0648\u0651\u065e\u06d6 \u0648\u064e\u0644\u064e\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0645\u064f\u0633\u06e1\u062a\u064e\u0642\u064e\u0631\u0651\u065e \u0648\u064e\u0645\u064e\u062a\u064e\u0670\u0639\u064c \u0625\u0650\u0644\u064e\u0649\u0670 \u062d\u0650\u064a\u0646\u0656",translation:"(Lalu setan menggelincirkan keduanya dari surga19) sehingga keduanya dikeluarkan dari (segala kenikmatan) ketika keduanya di sana (surga). Dan Kami berfirman,\"Turunlah kalian! Sebagian kalian menjadi musuh bagi yang lain. Dan bagi kalian ada tempat tinggal dan kesenangan di bumi sampai waktu yang ditentukan"},{id:37,text:"\u0641\u064e\u062a\u064e\u0644\u064e\u0642\u0651\u064e\u0649\u0670\u0653 \u0621\u064e\u0627\u062f\u064e\u0645\u064f \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0647\u0650\u06e6 \u0643\u064e\u0644\u0650\u0645\u064e\u0670\u062a\u0656 \u0641\u064e\u062a\u064e\u0627\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0647\u064f\u0648\u064e \u0671\u0644\u062a\u0651\u064e\u0648\u0651\u064e\u0627\u0628\u064f \u0671\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",translation:"(Kemudian Adam menerima beberapa kalimat20) dari Tuhannya, lalu Dia pun menerima tobatnya. Sungguh, Allah Maha Penerima tobat, Maha Penyayang"},{id:38,text:"\u0642\u064f\u0644\u06e1\u0646\u064e\u0627 \u0671\u0647\u06e1\u0628\u0650\u0637\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u062c\u064e\u0645\u0650\u064a\u0639\u0657\u0627\u06d6 \u0641\u064e\u0625\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e\u0646\u0651\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u0651\u0650\u064a \u0647\u064f\u062f\u0657\u0649 \u0641\u064e\u0645\u064e\u0646 \u062a\u064e\u0628\u0650\u0639\u064e \u0647\u064f\u062f\u064e\u0627\u064a\u064e \u0641\u064e\u0644\u064e\u0627 \u062e\u064e\u0648\u06e1\u0641\u064c \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u06e1 \u064a\u064e\u062d\u06e1\u0632\u064e\u0646\u064f\u0648\u0646\u064e",translation:"Kami berfirman, \"Turunlah kalian semua dari surga! Kemudian jika benar-benar datang petunjuk-Ku kepada kalian, maka barang siapa mengikuti petunjuk-Ku, tidak ada rasa takut bagi mereka dan mereka tidak bersedih hati"},{id:39,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627\u0653 \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650\u06d6 \u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u0670\u0644\u0650\u062f\u064f\u0648\u0646\u064e",translation:"Adapun orang-orang yang kafir dan mendustakan ayat-ayat Kami, mereka itu penghuni neraka. Mereka kekal di dalamnya"},{id:40,text:"\u064a\u064e\u0670\u0628\u064e\u0646\u0650\u064a\u0653 \u0625\u0650\u0633\u06e1\u0631\u064e\u0640\u0670\u0653\u0621\u0650\u064a\u0644\u064e \u0671\u0630\u06e1\u0643\u064f\u0631\u064f\u0648\u0627\u0652 \u0646\u0650\u0639\u06e1\u0645\u064e\u062a\u0650\u064a\u064e \u0671\u0644\u0651\u064e\u062a\u0650\u064a\u0653 \u0623\u064e\u0646\u06e1\u0639\u064e\u0645\u06e1\u062a\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0648\u06e1\u0641\u064f\u0648\u0627\u0652 \u0628\u0650\u0639\u064e\u0647\u06e1\u062f\u0650\u064a\u0653 \u0623\u064f\u0648\u0641\u0650 \u0628\u0650\u0639\u064e\u0647\u06e1\u062f\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0625\u0650\u064a\u0651\u064e\u0640\u0670\u064a\u064e \u0641\u064e\u0671\u0631\u06e1\u0647\u064e\u0628\u064f\u0648\u0646\u0650",translation:"(Wahai Bani Israil!21) Ingatlah nikmat-Ku yang telah Aku berikan kepadamu. Dan penuhilah janjimu kepada-Ku,22) niscaya Aku penuhi janji-Ku kepadamu, dan takutlah kepada-Ku saja"},{id:41,text:"\u0648\u064e\u0621\u064e\u0627\u0645\u0650\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u062a\u064f \u0645\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u0657\u0627 \u0644\u0651\u0650\u0645\u064e\u0627 \u0645\u064e\u0639\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0648\u0651\u064e\u0644\u064e \u0643\u064e\u0627\u0641\u0650\u0631\u0650\u06ed \u0628\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0634\u06e1\u062a\u064e\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u064a \u062b\u064e\u0645\u064e\u0646\u0657\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u0657\u0627 \u0648\u064e\u0625\u0650\u064a\u0651\u064e\u0640\u0670\u064a\u064e \u0641\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u0650",translation:"Dan berimanlah kalian kepada apa (Alquran) yang telah Aku turunkan yang membenarkan apa (Taurat) yang ada pada kalian, dan janganlah kalian menjadi orang yang pertama kafir kepadanya. Janganlah kalian jual ayat-ayat-Ku dengan harga yang murah, dan bertakwalah hanya kepada-Ku"},{id:42,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0644\u06e1\u0628\u0650\u0633\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064e \u0628\u0650\u0671\u0644\u06e1\u0628\u064e\u0670\u0637\u0650\u0644\u0650 \u0648\u064e\u062a\u064e\u0643\u06e1\u062a\u064f\u0645\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064e \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"(Dan janganlah kalian campuradukkan kebenaran dengan kebatilan23) dan (janganlah) kalian sembunyikan kebenaran, sedangkan kalian mengetahuinya"},{id:43,text:"\u0648\u064e\u0623\u064e\u0642\u0650\u064a\u0645\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u0621\u064e\u0627\u062a\u064f\u0648\u0627\u0652 \u0671\u0644\u0632\u0651\u064e\u0643\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u0671\u0631\u06e1\u0643\u064e\u0639\u064f\u0648\u0627\u0652 \u0645\u064e\u0639\u064e \u0671\u0644\u0631\u0651\u064e\u0640\u0670\u0643\u0650\u0639\u0650\u064a\u0646\u064e",translation:"Dan laksanakanlah salat, tunaikanlah zakat dan rukuklah beserta orang yang rukuk"},{id:44,text:"\u06de\u0623\u064e\u062a\u064e\u0623\u06e1\u0645\u064f\u0631\u064f\u0648\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0628\u0650\u0671\u0644\u06e1\u0628\u0650\u0631\u0651\u0650 \u0648\u064e\u062a\u064e\u0646\u0633\u064e\u0648\u06e1\u0646\u064e \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u062a\u06e1\u0644\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e\u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Mengapa kalian menyuruh orang lain (mengerjakan) kebajikan, sedangkan kalian melupakan diri kalian sendiri, padahal kalian membaca Kitab (Taurat)? Tidakkah kalian mengerti"},{id:45,text:"\u0648\u064e\u0671\u0633\u06e1\u062a\u064e\u0639\u0650\u064a\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u0635\u0651\u064e\u0628\u06e1\u0631\u0650 \u0648\u064e\u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u0650\u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064e\u0627 \u0644\u064e\u0643\u064e\u0628\u0650\u064a\u0631\u064e\u0629\u064c \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u062e\u064e\u0670\u0634\u0650\u0639\u0650\u064a\u0646\u064e",translation:"Dan mohonlah pertolongan (kepada Allah) dengan sabar dan salat. Dan (salat) itu sungguh berat, kecuali bagi orang-orang yang khusyuk"},{id:46,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0638\u064f\u0646\u0651\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645 \u0645\u0651\u064f\u0644\u064e\u0670\u0642\u064f\u0648\u0627\u0652 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0631\u064e\u0670\u062c\u0650\u0639\u064f\u0648\u0646\u064e",translation:"(yaitu) mereka yang yakin, bahwa mereka akan menemui Tuhannya, dan bahwa mereka akan kembali kepada-Nya"},{id:47,text:"\u064a\u064e\u0670\u0628\u064e\u0646\u0650\u064a\u0653 \u0625\u0650\u0633\u06e1\u0631\u064e\u0640\u0670\u0653\u0621\u0650\u064a\u0644\u064e \u0671\u0630\u06e1\u0643\u064f\u0631\u064f\u0648\u0627\u0652 \u0646\u0650\u0639\u06e1\u0645\u064e\u062a\u0650\u064a\u064e \u0671\u0644\u0651\u064e\u062a\u0650\u064a\u0653 \u0623\u064e\u0646\u06e1\u0639\u064e\u0645\u06e1\u062a\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0646\u0651\u0650\u064a \u0641\u064e\u0636\u0651\u064e\u0644\u06e1\u062a\u064f\u0643\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Wahai Bani Israil! Ingatlah nikmat-Ku yang telah aku berikan kepadamu, dan Aku telah melebihkan kamu dari semua umat yang lain di alam ini (pada masa itu)"},{id:48,text:"\u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u064a\u064e\u0648\u06e1\u0645\u0657\u0627 \u0644\u0651\u064e\u0627 \u062a\u064e\u062c\u06e1\u0632\u0650\u064a \u0646\u064e\u0641\u06e1\u0633\u064c \u0639\u064e\u0646 \u0646\u0651\u064e\u0641\u06e1\u0633\u0656 \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0642\u06e1\u0628\u064e\u0644\u064f \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0634\u064e\u0641\u064e\u0670\u0639\u064e\u0629\u065e \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u062e\u064e\u0630\u064f \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0639\u064e\u062f\u06e1\u0644\u065e \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u06e1 \u064a\u064f\u0646\u0635\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan takutlah kamu pada hari, (ketika) tidak seorang pun dapat membela orang lain sedikit pun. Sedangkan syafaat24) dan tebusan apa pun darinya tidak diterima dan mereka tidak akan ditolong"},{id:49,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0646\u064e\u062c\u0651\u064e\u064a\u06e1\u0646\u064e\u0670\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0621\u064e\u0627\u0644\u0650 \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u064a\u064e\u0633\u064f\u0648\u0645\u064f\u0648\u0646\u064e\u0643\u064f\u0645\u06e1 \u0633\u064f\u0648\u0653\u0621\u064e \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u064a\u064f\u0630\u064e\u0628\u0651\u0650\u062d\u064f\u0648\u0646\u064e \u0623\u064e\u0628\u06e1\u0646\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u064a\u064e\u0633\u06e1\u062a\u064e\u062d\u06e1\u064a\u064f\u0648\u0646\u064e \u0646\u0650\u0633\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645 \u0628\u064e\u0644\u064e\u0627\u0653\u0621\u065e \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1 \u0639\u064e\u0638\u0650\u064a\u0645\u065e",translation:"Dan (ingatlah) ketika Kami menyelamatkan kamu dari (Fir'aun dan) pengikut-pengikut Fir'aun.25) Mereka menimpakan siksaan yang sangat berat kepadamu. Mereka menyembelih anak-anak laki-lakimu dan membiarkan hidup anak-anak perempuanmu. Dan pada yang demikian itu merupakan cobaan yang besar dari Tuhanmu"},{id:50,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0641\u064e\u0631\u064e\u0642\u06e1\u0646\u064e\u0627 \u0628\u0650\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0628\u064e\u062d\u06e1\u0631\u064e \u0641\u064e\u0623\u064e\u0646\u062c\u064e\u064a\u06e1\u0646\u064e\u0670\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u063a\u06e1\u0631\u064e\u0642\u06e1\u0646\u064e\u0627\u0653 \u0621\u064e\u0627\u0644\u064e \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0646\u0638\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Dan (ingatlah) ketika Kami membelah laut untukmu, sehingga kamu dapat Kami selamatkan dan Kami tenggelamkan (Fir'aun dan) pengikut-pengikut Fir'aun sedang kamu menyaksikan"},{id:51,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0648\u064e\u0670\u0639\u064e\u062f\u06e1\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670\u0653 \u0623\u064e\u0631\u06e1\u0628\u064e\u0639\u0650\u064a\u0646\u064e \u0644\u064e\u064a\u06e1\u0644\u064e\u0629\u0657 \u062b\u064f\u0645\u0651\u064e \u0671\u062a\u0651\u064e\u062e\u064e\u0630\u06e1\u062a\u064f\u0645\u064f \u0671\u0644\u06e1\u0639\u0650\u062c\u06e1\u0644\u064e \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u0647\u0650\u06e6 \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0638\u064e\u0670\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Dan (ingatlah) ketika Kami menjanjikan kepada Musa empat puluh malam.26) Kemudian kamu (Bani Israil) menjadikan (patung) anak sapi (sebagai sesembahan) setelah (kepergian)nya, dan kamu (menjadi) orang yang zalim"},{id:52,text:"\u062b\u064f\u0645\u0651\u064e \u0639\u064e\u0641\u064e\u0648\u06e1\u0646\u064e\u0627 \u0639\u064e\u0646\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u0634\u06e1\u0643\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Kemudian Kami memaafkan kamu setelah itu, agar kamu bersyukur"},{id:53,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0648\u064e\u0671\u0644\u06e1\u0641\u064f\u0631\u06e1\u0642\u064e\u0627\u0646\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u0647\u06e1\u062a\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Dan (ingatlah), ketika Kami memberikan kepada Musa Kitab dan Furqan, agar kamu memperoleh petunjuk"},{id:54,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0644\u0650\u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u06e6 \u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0638\u064e\u0644\u064e\u0645\u06e1\u062a\u064f\u0645\u06e1 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0643\u064f\u0645 \u0628\u0650\u0671\u062a\u0651\u0650\u062e\u064e\u0627\u0630\u0650\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0639\u0650\u062c\u06e1\u0644\u064e \u0641\u064e\u062a\u064f\u0648\u0628\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0628\u064e\u0627\u0631\u0650\u0626\u0650\u0643\u064f\u0645\u06e1 \u0641\u064e\u0671\u0642\u06e1\u062a\u064f\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0643\u064f\u0645\u06e1 \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u06e1 \u062e\u064e\u064a\u06e1\u0631\u065e \u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u0639\u0650\u0646\u062f\u064e \u0628\u064e\u0627\u0631\u0650\u0626\u0650\u0643\u064f\u0645\u06e1 \u0641\u064e\u062a\u064e\u0627\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0647\u064f\u0648\u064e \u0671\u0644\u062a\u0651\u064e\u0648\u0651\u064e\u0627\u0628\u064f \u0671\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",translation:"Dan (ingatlah) ketika Musa berkata kepada kaumnya, \"Wahai kaumku! Kamu benar-benar telah menzalimi dirimu sendiri dengan menjadikan (patung) anak sapi (sebagai sesembahan), karena itu bertobatlah kepada Penciptamu dan bunuhlah dirimu.28) Itu lebih baik bagimu di sisi Penciptamu. Dia akan menerima tobatmu. Sungguh, Dialah Yang Maha Penerima tobat, Maha Penyayang"},{id:55,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0642\u064f\u0644\u06e1\u062a\u064f\u0645\u06e1 \u064a\u064e\u0670\u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0644\u064e\u0646 \u0646\u0651\u064f\u0624\u06e1\u0645\u0650\u0646\u064e \u0644\u064e\u0643\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0646\u064e\u0631\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u062c\u064e\u0647\u06e1\u0631\u064e\u0629\u0657 \u0641\u064e\u0623\u064e\u062e\u064e\u0630\u064e\u062a\u06e1\u0643\u064f\u0645\u064f \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0639\u0650\u0642\u064e\u0629\u064f \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0646\u0638\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Dan (ingatlah) ketika kamu berkata, \"Wahai Musa! Kami tidak akan beriman kepadamu sebelum kami melihat Allah dengan jelas,\" maka halilintar menyambarmu, sedang kamu menyaksikannya"},{id:56,text:"\u062b\u064f\u0645\u0651\u064e \u0628\u064e\u0639\u064e\u062b\u06e1\u0646\u064e\u0670\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0645\u064e\u0648\u06e1\u062a\u0650\u0643\u064f\u0645\u06e1 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u0634\u06e1\u0643\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Kemudian, Kami membangkitkan kamu setelah kamu mati, agar kamu bersyukur"},{id:57,text:"\u0648\u064e\u0638\u064e\u0644\u0651\u064e\u0644\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u063a\u064e\u0645\u064e\u0627\u0645\u064e \u0648\u064e\u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064e\u0646\u0651\u064e \u0648\u064e\u0671\u0644\u0633\u0651\u064e\u0644\u06e1\u0648\u064e\u0649\u0670\u06d6 \u0643\u064f\u0644\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0637\u064e\u064a\u0651\u0650\u0628\u064e\u0670\u062a\u0650 \u0645\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u06e1\u0646\u064e\u0670\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0645\u064e\u0627 \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u0643\u064e\u0627\u0646\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0638\u06e1\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"(Dan Kami menaungi kamu dengan awan, dan Kami menurunkan kepadamu manna dan salwa.29) Makanlah (makanan) yang baik-baik dari rezeki yang telah Kami berikan kepadamu. Mereka tidak menzalimi Kami, tetapi justru merekalah yang menzalimi diri sendiri"},{id:58,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0642\u064f\u0644\u06e1\u0646\u064e\u0627 \u0671\u062f\u06e1\u062e\u064f\u0644\u064f\u0648\u0627\u0652 \u0647\u064e\u0670\u0630\u0650\u0647\u0650 \u0671\u0644\u06e1\u0642\u064e\u0631\u06e1\u064a\u064e\u0629\u064e \u0641\u064e\u0643\u064f\u0644\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u062d\u064e\u064a\u06e1\u062b\u064f \u0634\u0650\u0626\u06e1\u062a\u064f\u0645\u06e1 \u0631\u064e\u063a\u064e\u062f\u0657\u0627 \u0648\u064e\u0671\u062f\u06e1\u062e\u064f\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0628\u064e\u0627\u0628\u064e \u0633\u064f\u062c\u0651\u064e\u062f\u0657\u0627 \u0648\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627\u0652 \u062d\u0650\u0637\u0651\u064e\u0629\u065e \u0646\u0651\u064e\u063a\u06e1\u0641\u0650\u0631\u06e1 \u0644\u064e\u0643\u064f\u0645\u06e1 \u062e\u064e\u0637\u064e\u0670\u064a\u064e\u0670\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0633\u064e\u0646\u064e\u0632\u0650\u064a\u062f\u064f \u0671\u0644\u06e1\u0645\u064f\u062d\u06e1\u0633\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dan (ingatlah) ketika Kami berfirman, \"Masuklah kamu ke negeri ini (Baitulmaqdis), maka makanlah dengan nikmat (berbagai makanan) yang ada di sana sesukamu. Dan masukilah pintu gerbangnya sambil membungkuk, dan katakanlah, \"Bebaskanlah kami (dari dosa-dosa kami),\" niscaya Kami ampuni kesalahan-kesalahanmu. Dan Kami akan menambah (karunia) bagi orang-orang yang berbuat kebaikan"},{id:59,text:"\u0641\u064e\u0628\u064e\u062f\u0651\u064e\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627\u0652 \u0642\u064e\u0648\u06e1\u0644\u064b\u0627 \u063a\u064e\u064a\u06e1\u0631\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0641\u064e\u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627\u0652 \u0631\u0650\u062c\u06e1\u0632\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0641\u06e1\u0633\u064f\u0642\u064f\u0648\u0646\u064e",translation:"Lalu orang-orang yang zalim mengganti perintah dengan (perintah lain) yang tidak diperintahkan kepada mereka. Maka Kami turunkan malapetaka dari langit kepada orang-orang yang zalim itu, karena mereka (selalu) berbuat fasik"},{id:60,text:"\u06de\u0648\u064e\u0625\u0650\u0630\u0650 \u0671\u0633\u06e1\u062a\u064e\u0633\u06e1\u0642\u064e\u0649\u0670 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0644\u0650\u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u06e6 \u0641\u064e\u0642\u064f\u0644\u06e1\u0646\u064e\u0627 \u0671\u0636\u06e1\u0631\u0650\u0628 \u0628\u0651\u0650\u0639\u064e\u0635\u064e\u0627\u0643\u064e \u0671\u0644\u06e1\u062d\u064e\u062c\u064e\u0631\u064e\u06d6 \u0641\u064e\u0671\u0646\u0641\u064e\u062c\u064e\u0631\u064e\u062a\u06e1 \u0645\u0650\u0646\u06e1\u0647\u064f \u0671\u062b\u06e1\u0646\u064e\u062a\u064e\u0627 \u0639\u064e\u0634\u06e1\u0631\u064e\u0629\u064e \u0639\u064e\u064a\u06e1\u0646\u0657\u0627\u06d6 \u0642\u064e\u062f\u06e1 \u0639\u064e\u0644\u0650\u0645\u064e \u0643\u064f\u0644\u0651\u064f \u0623\u064f\u0646\u064e\u0627\u0633\u0656 \u0645\u0651\u064e\u0634\u06e1\u0631\u064e\u0628\u064e\u0647\u064f\u0645\u06e1\u06d6 \u0643\u064f\u0644\u064f\u0648\u0627\u0652 \u0648\u064e\u0671\u0634\u06e1\u0631\u064e\u0628\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0631\u0651\u0650\u0632\u06e1\u0642\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u062b\u064e\u0648\u06e1\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0645\u064f\u0641\u06e1\u0633\u0650\u062f\u0650\u064a\u0646\u064e",translation:"Dan (ingatlah) ketika Musa memohon air untuk kaumnya, lalu Kami berfirman, \"Pukullah batu itu dengan tongkatmu!\" Maka memacarlah darinya dua belas mata air. Setiap suku telah mengetahui tempat minumnya (masing-masing).30) Makan dan minumlah dari rezeki (yang diberikan) Allah, dan janganlah kamu melakukan kejahatan di bumi dengan berbuat kerusakan"},{id:61,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0642\u064f\u0644\u06e1\u062a\u064f\u0645\u06e1 \u064a\u064e\u0670\u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0644\u064e\u0646 \u0646\u0651\u064e\u0635\u06e1\u0628\u0650\u0631\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0637\u064e\u0639\u064e\u0627\u0645\u0656 \u0648\u064e\u0670\u062d\u0650\u062f\u0656 \u0641\u064e\u0671\u062f\u06e1\u0639\u064f \u0644\u064e\u0646\u064e\u0627 \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u064a\u064f\u062e\u06e1\u0631\u0650\u062c\u06e1 \u0644\u064e\u0646\u064e\u0627 \u0645\u0650\u0645\u0651\u064e\u0627 \u062a\u064f\u0646\u06e2\u0628\u0650\u062a\u064f \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064f \u0645\u0650\u0646\u06e2 \u0628\u064e\u0642\u06e1\u0644\u0650\u0647\u064e\u0627 \u0648\u064e\u0642\u0650\u062b\u0651\u064e\u0627\u0653\u0626\u0650\u0647\u064e\u0627 \u0648\u064e\u0641\u064f\u0648\u0645\u0650\u0647\u064e\u0627 \u0648\u064e\u0639\u064e\u062f\u064e\u0633\u0650\u0647\u064e\u0627 \u0648\u064e\u0628\u064e\u0635\u064e\u0644\u0650\u0647\u064e\u0627\u06d6 \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u062a\u064e\u0633\u06e1\u062a\u064e\u0628\u06e1\u062f\u0650\u0644\u064f\u0648\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0647\u064f\u0648\u064e \u0623\u064e\u062f\u06e1\u0646\u064e\u0649\u0670 \u0628\u0650\u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0647\u064f\u0648\u064e \u062e\u064e\u064a\u06e1\u0631\u064c\u06da \u0671\u0647\u06e1\u0628\u0650\u0637\u064f\u0648\u0627\u0652 \u0645\u0650\u0635\u06e1\u0631\u0657\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u064e\u0627 \u0633\u064e\u0623\u064e\u0644\u06e1\u062a\u064f\u0645\u06e1\u06d7 \u0648\u064e\u0636\u064f\u0631\u0650\u0628\u064e\u062a\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u064f \u0671\u0644\u0630\u0651\u0650\u0644\u0651\u064e\u0629\u064f \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u0633\u06e1\u0643\u064e\u0646\u064e\u0629\u064f \u0648\u064e\u0628\u064e\u0627\u0653\u0621\u064f\u0648 \u0628\u0650\u063a\u064e\u0636\u064e\u0628\u0656 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0643\u06e1\u0641\u064f\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u064a\u064e\u0642\u06e1\u062a\u064f\u0644\u064f\u0648\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650\u0640\u06e7\u0646\u064e \u0628\u0650\u063a\u064e\u064a\u06e1\u0631\u0650 \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0645\u064e\u0627 \u0639\u064e\u0635\u064e\u0648\u0627\u0652 \u0648\u0651\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u062a\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Dan (ingatlah), ketika kamu berkata, \"Wahai Musa! Kami tidak tahan hanya (makan) dengan satu macam makanan saja, maka mohonkanlah kepada Tuhanmu untuk kami, agar Dia memberi kami apa yang ditumbuhkan bumi, seperti: sayur-mayur, mentimun, bawang putih, kacang adas dan bawang merah.\" Dia (Musa) menjawab, \"Apakah kamu meminta sesuatu yang buruk sebagai ganti dari sesuatu yang baik? Pergilah ke suatu kota, pasti kamu memperoleh apa yang kamu minta.\" Kemudian mereka ditimpa kenistaan dan kemiskinan, dan mereka (kembali) mendapat kemurkaan dari Allah. Hal itu (terjadi) karena mereka mengingkari ayat-ayat Allah dan membunuh para nabi tanpa hak (alasan yang benar). Yang demikian itu karena mereka durhaka dan melampaui batas"},{id:62,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064e\u0627\u062f\u064f\u0648\u0627\u0652 \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0635\u064e\u0670\u0631\u064e\u0649\u0670 \u0648\u064e\u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0628\u0650\u0640\u0654\u0650\u064a\u0646\u064e \u0645\u064e\u0646\u06e1 \u0621\u064e\u0627\u0645\u064e\u0646\u064e \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u0650 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064e \u0635\u064e\u0670\u0644\u0650\u062d\u0657\u0627 \u0641\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u062c\u06e1\u0631\u064f\u0647\u064f\u0645\u06e1 \u0639\u0650\u0646\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u062e\u064e\u0648\u06e1\u0641\u064c \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u06e1 \u064a\u064e\u062d\u06e1\u0632\u064e\u0646\u064f\u0648\u0646\u064e",translation:"(Sesungguhnya orang-orang yang beriman, orang-orang Yahudi, orang-orang Nasrani dan orang-orang \u1e63\u0101bi\u012bn,31) siapa saja (diantara mereka) yang beriman kepada Allah dan hari akhir, dan melakukan kebajikan, mereka mendapat pahala dari Tuhannya, tidak ada rasa takut pada mereka, dan mereka tidak bersedih hati"},{id:63,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0623\u064e\u062e\u064e\u0630\u06e1\u0646\u064e\u0627 \u0645\u0650\u064a\u062b\u064e\u0670\u0642\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0631\u064e\u0641\u064e\u0639\u06e1\u0646\u064e\u0627 \u0641\u064e\u0648\u06e1\u0642\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0637\u0651\u064f\u0648\u0631\u064e \u062e\u064f\u0630\u064f\u0648\u0627\u0652 \u0645\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0670\u0643\u064f\u0645 \u0628\u0650\u0642\u064f\u0648\u0651\u064e\u0629\u0656 \u0648\u064e\u0671\u0630\u06e1\u0643\u064f\u0631\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u0641\u0650\u064a\u0647\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",translation:"Dan (ingatlah) ketika Kami mengambil janji kamu dan Kami angkat gunung (Sinai) di atasmu (seraya berfirman), \"Pegang teguhlah apa yang telah Kami berikan kepadamu dan ingatlah apa yang ada di dalamnya, agar kamu bertakwa"},{id:64,text:"\u062b\u064f\u0645\u0651\u064e \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u064a\u06e1\u062a\u064f\u0645 \u0645\u0651\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0630\u064e\u0670\u0644\u0650\u0643\u064e\u06d6 \u0641\u064e\u0644\u064e\u0648\u06e1\u0644\u064e\u0627 \u0641\u064e\u0636\u06e1\u0644\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0648\u064e\u0631\u064e\u062d\u06e1\u0645\u064e\u062a\u064f\u0647\u064f\u06e5 \u0644\u064e\u0643\u064f\u0646\u062a\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u062e\u064e\u0670\u0633\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Kemudian setelah itu kamu berpaling. Maka sekiranya bukan karena karunia Allah dan rahmat-Nya kepadamu, pasti kamu termasuk orang yang rugi"},{id:65,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0639\u064e\u0644\u0650\u0645\u06e1\u062a\u064f\u0645\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u0639\u06e1\u062a\u064e\u062f\u064e\u0648\u06e1\u0627\u0652 \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0628\u06e1\u062a\u0650 \u0641\u064e\u0642\u064f\u0644\u06e1\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u0642\u0650\u0631\u064e\u062f\u064e\u0629\u064b \u062e\u064e\u0670\u0633\u0650\u0640\u0654\u0650\u064a\u0646\u064e",translation:"(Dan sungguh, kamu telah mengetahui orang-orang yang melakukan pelanggaran di antara kamu pada hari Sabat,32) lalu Kami katakan kepada mereka, \"Jadilah kamu kera yang hina"},{id:66,text:"\u0641\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064e\u0627 \u0646\u064e\u0643\u064e\u0670\u0644\u0657\u0627 \u0644\u0651\u0650\u0645\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u06e1\u0647\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u06e1\u0641\u064e\u0647\u064e\u0627 \u0648\u064e\u0645\u064e\u0648\u06e1\u0639\u0650\u0638\u064e\u0629\u0657 \u0644\u0651\u0650\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",translation:"Maka Kami jadikan (yang demikian) itu peringatan bagi orang-orang pada masa itu, dan bagi mereka yang datang kemudian, serta menjadi pelajaran bagi orang-orang yang bertakwa"},{id:67,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0644\u0650\u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0623\u06e1\u0645\u064f\u0631\u064f\u0643\u064f\u0645\u06e1 \u0623\u064e\u0646 \u062a\u064e\u0630\u06e1\u0628\u064e\u062d\u064f\u0648\u0627\u0652 \u0628\u064e\u0642\u064e\u0631\u064e\u0629\u0657\u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0646\u064e\u0627 \u0647\u064f\u0632\u064f\u0648\u0657\u0627\u06d6 \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0646\u06e1 \u0623\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u062c\u064e\u0670\u0647\u0650\u0644\u0650\u064a\u0646\u064e",translation:"Dan (ingatlah) ketika Musa berkata kepada kaumnya, \"Allah memerintahkan kamu agar menyembelih seekor sapi betina.\" Mereka bertanya, \"Apakah engkau akan menjadikan kami sebagai ejekan?\" 34) Dia (Musa) menjawab, \"Aku berlindung kepada Allah agar tidak menjadi orang-orang yang bodoh"},{id:68,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0671\u062f\u06e1\u0639\u064f \u0644\u064e\u0646\u064e\u0627 \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646 \u0644\u0651\u064e\u0646\u064e\u0627 \u0645\u064e\u0627 \u0647\u0650\u064a\u064e\u06da \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0625\u0650\u0646\u0651\u064e\u0647\u064e\u0627 \u0628\u064e\u0642\u064e\u0631\u064e\u0629\u065e \u0644\u0651\u064e\u0627 \u0641\u064e\u0627\u0631\u0650\u0636\u065e \u0648\u064e\u0644\u064e\u0627 \u0628\u0650\u0643\u06e1\u0631\u064c \u0639\u064e\u0648\u064e\u0627\u0646\u064f\u06e2 \u0628\u064e\u064a\u06e1\u0646\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e\u06d6 \u0641\u064e\u0671\u0641\u06e1\u0639\u064e\u0644\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u062a\u064f\u0624\u06e1\u0645\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Mereka berkata, \"Mohonkanlah kepada Tuhanmu untuk kami agar Dia menjelaskan kepada kami tentang (sapi betina) itu.\" Dia (Musa) menjawab, \"Dia (Allah) berfirman, bahwa sapi betina itu tidak tua dan tidak muda, (tetapi) pertengahan antara itu. Maka kerjakanlah apa yang diperintahkan kepadamu"},{id:69,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0671\u062f\u06e1\u0639\u064f \u0644\u064e\u0646\u064e\u0627 \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646 \u0644\u0651\u064e\u0646\u064e\u0627 \u0645\u064e\u0627 \u0644\u064e\u0648\u06e1\u0646\u064f\u0647\u064e\u0627\u06da \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0625\u0650\u0646\u0651\u064e\u0647\u064e\u0627 \u0628\u064e\u0642\u064e\u0631\u064e\u0629\u065e \u0635\u064e\u0641\u06e1\u0631\u064e\u0627\u0653\u0621\u064f \u0641\u064e\u0627\u0642\u0650\u0639\u065e \u0644\u0651\u064e\u0648\u06e1\u0646\u064f\u0647\u064e\u0627 \u062a\u064e\u0633\u064f\u0631\u0651\u064f \u0671\u0644\u0646\u0651\u064e\u0640\u0670\u0638\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Mereka berkata, \"Mohonkanlah kepada Tuhanmu untuk kami agar Dia menjelaskan kepada kami apa warnanya.\" Dia (Musa) menjawab, \"Dia Allah berfirman, bahwa (sapi) itu adalah sapi betina yang kuning cerah warnanya, yang menyenangkan orang-orang yang memandang(nya)"},{id:70,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0671\u062f\u06e1\u0639\u064f \u0644\u064e\u0646\u064e\u0627 \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646 \u0644\u0651\u064e\u0646\u064e\u0627 \u0645\u064e\u0627 \u0647\u0650\u064a\u064e \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0628\u064e\u0642\u064e\u0631\u064e \u062a\u064e\u0634\u064e\u0670\u0628\u064e\u0647\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0625\u0650\u0646 \u0634\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0645\u064f\u0647\u06e1\u062a\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Mereka berkata, \"Mohonkanlah kepada Tuhanmu untuk kami agar Dia menjelaskan kepada kami tentang (sapi betina) itu. (Karena) sesungguhnya sapi itu belum jelas bagi kami, dan jika Allah menghendaki, niscaya kami mendapat petunjuk"},{id:71,text:"\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0625\u0650\u0646\u0651\u064e\u0647\u064e\u0627 \u0628\u064e\u0642\u064e\u0631\u064e\u0629\u065e \u0644\u0651\u064e\u0627 \u0630\u064e\u0644\u064f\u0648\u0644\u065e \u062a\u064f\u062b\u0650\u064a\u0631\u064f \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0633\u06e1\u0642\u0650\u064a \u0671\u0644\u06e1\u062d\u064e\u0631\u06e1\u062b\u064e \u0645\u064f\u0633\u064e\u0644\u0651\u064e\u0645\u064e\u0629\u065e \u0644\u0651\u064e\u0627 \u0634\u0650\u064a\u064e\u0629\u064e \u0641\u0650\u064a\u0647\u064e\u0627\u06da \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0640\u0654\u064e\u0670\u0646\u064e \u062c\u0650\u0626\u06e1\u062a\u064e \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650\u06da \u0641\u064e\u0630\u064e\u0628\u064e\u062d\u064f\u0648\u0647\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u062f\u064f\u0648\u0627\u0652 \u064a\u064e\u0641\u06e1\u0639\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dia (Musa) menjawab, \"Dia (Allah) berfirman, (sapi) itu adalah sapi betina yang belum pernah dipakai untuk membajak tanah dan tidak (pula) untuk mengairi tanaman, sehat, dan tidak belang.\" Mereka berkata, \"Sekarang barulah engkau menerangkan (hal) yang sebenarnya.\" Lalu mereka menyembelihnya, dan nyaris mereka tidak melaksanakan (perintah) itu"},{id:72,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0642\u064e\u062a\u064e\u0644\u06e1\u062a\u064f\u0645\u06e1 \u0646\u064e\u0641\u06e1\u0633\u0657\u0627 \u0641\u064e\u0671\u062f\u0651\u064e\u0640\u0670\u0631\u064e\u2009\u0670\u0654\u062a\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627\u06d6 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064f\u062e\u06e1\u0631\u0650\u062c\u065e \u0645\u0651\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0643\u06e1\u062a\u064f\u0645\u064f\u0648\u0646\u064e",translation:"Dan (ingatlah) ketika kamu membunuh seseorang, lalu kamu tuduh-menuduh tentang itu. Tetapi Allah menyingkapkan apa yang kamu sembunyikan"},{id:73,text:"\u0641\u064e\u0642\u064f\u0644\u06e1\u0646\u064e\u0627 \u0671\u0636\u06e1\u0631\u0650\u0628\u064f\u0648\u0647\u064f \u0628\u0650\u0628\u064e\u0639\u06e1\u0636\u0650\u0647\u064e\u0627\u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064f\u062d\u06e1\u064a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u064e\u0649\u0670 \u0648\u064e\u064a\u064f\u0631\u0650\u064a\u0643\u064f\u0645\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0647\u0650\u06e6 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Lalu Kami berfirman, \"Pukullah (mayat) itu dengan bagian dari (sapi) itu!\" Demikianlah Allah menghidupkan (orang) yang telah mati, dan Dia memperlihatkan kepadamu tanda-tanda (kekuasaan-Nya) agar kamu mengerti"},{id:74,text:"\u062b\u064f\u0645\u0651\u064e \u0642\u064e\u0633\u064e\u062a\u06e1 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u0647\u0650\u064a\u064e \u0643\u064e\u0671\u0644\u06e1\u062d\u0650\u062c\u064e\u0627\u0631\u064e\u0629\u0650 \u0623\u064e\u0648\u06e1 \u0623\u064e\u0634\u064e\u062f\u0651\u064f \u0642\u064e\u0633\u06e1\u0648\u064e\u0629\u0657\u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u062d\u0650\u062c\u064e\u0627\u0631\u064e\u0629\u0650 \u0644\u064e\u0645\u064e\u0627 \u064a\u064e\u062a\u064e\u0641\u064e\u062c\u0651\u064e\u0631\u064f \u0645\u0650\u0646\u06e1\u0647\u064f \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u064f\u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0644\u064e\u0645\u064e\u0627 \u064a\u064e\u0634\u0651\u064e\u0642\u0651\u064e\u0642\u064f \u0641\u064e\u064a\u064e\u062e\u06e1\u0631\u064f\u062c\u064f \u0645\u0650\u0646\u06e1\u0647\u064f \u0671\u0644\u06e1\u0645\u064e\u0627\u0653\u0621\u064f\u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0644\u064e\u0645\u064e\u0627 \u064a\u064e\u0647\u06e1\u0628\u0650\u0637\u064f \u0645\u0650\u0646\u06e1 \u062e\u064e\u0634\u06e1\u064a\u064e\u0629\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d7 \u0648\u064e\u0645\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u063a\u064e\u0670\u0641\u0650\u0644\u064d \u0639\u064e\u0645\u0651\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Kemudian setelah itu hatimu menjadi keras, sehingga (hatimu) seperti batu, bahkan lebih keras. Padahal dari batu-batu itu pasti ada sungai-sungai yang (airnya) memancar darinya. Ada pula yang terbelah lalu keluarlah mata air darinya. Dan ada pula yang meluncur jatuh karena takut kepada Allah. Dan Allah tidaklah lengah terhadap apa yang kamu kerjakan"},{id:75,text:"\u06de\u0623\u064e\u0641\u064e\u062a\u064e\u0637\u06e1\u0645\u064e\u0639\u064f\u0648\u0646\u064e \u0623\u064e\u0646 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0642\u064e\u062f\u06e1 \u0643\u064e\u0627\u0646\u064e \u0641\u064e\u0631\u0650\u064a\u0642\u065e \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u064a\u064e\u0633\u06e1\u0645\u064e\u0639\u064f\u0648\u0646\u064e \u0643\u064e\u0644\u064e\u0670\u0645\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u062d\u064e\u0631\u0651\u0650\u0641\u064f\u0648\u0646\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0645\u064e\u0627 \u0639\u064e\u0642\u064e\u0644\u064f\u0648\u0647\u064f \u0648\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Maka apakah kamu (muslimin) sangat mengharapkan mereka akan percaya kepadamu, sedangkan segolongan dari mereka mendengar firman Allah, lalu mereka mengubahnya setelah memahaminya, padahal mereka mengetahuinya"},{id:76,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0644\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0621\u064e\u0627\u0645\u064e\u0646\u0651\u064e\u0627 \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062e\u064e\u0644\u064e\u0627 \u0628\u064e\u0639\u06e1\u0636\u064f\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u06e1\u0636\u0656 \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u062a\u064f\u062d\u064e\u062f\u0651\u0650\u062b\u064f\u0648\u0646\u064e\u0647\u064f\u0645 \u0628\u0650\u0645\u064e\u0627 \u0641\u064e\u062a\u064e\u062d\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0644\u0650\u064a\u064f\u062d\u064e\u0627\u0653\u062c\u0651\u064f\u0648\u0643\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6 \u0639\u0650\u0646\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1\u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Dan apabila mereka berjumpa dengan orang-orang yang beriman, mereka berkata, \"Kami telah beriman.\" Tetapi apabila kembali kepada sesamanya, mereka bertanya, \"Apakah akan kamu ceritakan kepada mereka apa yang telah diterangkan Allah kepadamu, sehingga mereka dapat menyanggah kamu di hadapan Tuhanmu? Tidakkah kamu mengerti"},{id:77,text:"\u0623\u064e\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u064a\u064f\u0633\u0650\u0631\u0651\u064f\u0648\u0646\u064e \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0639\u06e1\u0644\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Dan tidakkah mereka tahu bahwa Allah mengetahui apa yang mereka sembunyikan dan apa yang mereka tampakkan"},{id:78,text:"\u0648\u064e\u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0623\u064f\u0645\u0651\u0650\u064a\u0651\u064f\u0648\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0645\u064e\u0627\u0646\u0650\u064a\u0651\u064e \u0648\u064e\u0625\u0650\u0646\u06e1 \u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u064a\u064e\u0638\u064f\u0646\u0651\u064f\u0648\u0646\u064e",translation:"Dan di antara mereka ada yang buta huruf, tidak memahami Kitab (Taurat), kecuali hanya berangan-angan dan mereka hanya menduga-duga"},{id:79,text:"\u0641\u064e\u0648\u064e\u064a\u06e1\u0644\u065e \u0644\u0651\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0643\u06e1\u062a\u064f\u0628\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0628\u0650\u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u0647\u0650\u0645\u06e1 \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0645\u0650\u0646\u06e1 \u0639\u0650\u0646\u062f\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u0650\u064a\u064e\u0634\u06e1\u062a\u064e\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6 \u062b\u064e\u0645\u064e\u0646\u0657\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u0657\u0627\u06d6 \u0641\u064e\u0648\u064e\u064a\u06e1\u0644\u065e \u0644\u0651\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u0643\u064e\u062a\u064e\u0628\u064e\u062a\u06e1 \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u0647\u0650\u0645\u06e1 \u0648\u064e\u0648\u064e\u064a\u06e1\u0644\u065e \u0644\u0651\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u0643\u06e1\u0633\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Maka celakalah orang-orang yang menulis kitab dengan tangan mereka (sendiri), kemudian berkata, \"Ini dari Allah,\" (dengan maksud) untuk menjualnya dengan harga murah. Maka celakalah mereka, karena tulisan tangan mereka, dan celakalah mereka karena apa yang mereka perbuat"},{id:80,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0646 \u062a\u064e\u0645\u064e\u0633\u0651\u064e\u0646\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u064f \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u0657\u0627 \u0645\u0651\u064e\u0639\u06e1\u062f\u064f\u0648\u062f\u064e\u0629\u0657\u06da \u0642\u064f\u0644\u06e1 \u0623\u064e\u062a\u0651\u064e\u062e\u064e\u0630\u06e1\u062a\u064f\u0645\u06e1 \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0647\u06e1\u062f\u0657\u0627 \u0641\u064e\u0644\u064e\u0646 \u064a\u064f\u062e\u06e1\u0644\u0650\u0641\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0647\u06e1\u062f\u064e\u0647\u064f\u06e5\u0653\u06d6 \u0623\u064e\u0645\u06e1 \u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan mereka berkata, \"Neraka tidak akan menyentuh kami, kecuali beberapa hari saja.\" Katakanlah, \"Sudahkah kamu menerima janji dari Allah, sehingga Allah tidak akan mengingkari janji-Nya, ataukah kamu mengatakan tentang Allah, sesuatu yang tidak kamu ketahui"},{id:81,text:"\u0628\u064e\u0644\u064e\u0649\u0670\u06da \u0645\u064e\u0646 \u0643\u064e\u0633\u064e\u0628\u064e \u0633\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u0657 \u0648\u064e\u0623\u064e\u062d\u064e\u0670\u0637\u064e\u062a\u06e1 \u0628\u0650\u0647\u0650\u06e6 \u062e\u064e\u0637\u0650\u064a\u0653\u0640\u0654\u064e\u062a\u064f\u0647\u064f\u06e5 \u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650\u06d6 \u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u0670\u0644\u0650\u062f\u064f\u0648\u0646\u064e",translation:"Tidaklah demikian! Barang siapa berbuat keburukan dan dosanya telah menenggelamkannya, maka mereka itu penghuni neraka. Mereka kekal di dalamnya"},{id:82,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u0650\u06d6 \u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u0670\u0644\u0650\u062f\u064f\u0648\u0646\u064e",translation:"Dan orang-orang yang beriman dan mengerjakan kebajikan, mereka itu penghuni surga. Mereka kekal di dalamnya"},{id:83,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0623\u064e\u062e\u064e\u0630\u06e1\u0646\u064e\u0627 \u0645\u0650\u064a\u062b\u064e\u0670\u0642\u064e \u0628\u064e\u0646\u0650\u064a\u0653 \u0625\u0650\u0633\u06e1\u0631\u064e\u0640\u0670\u0653\u0621\u0650\u064a\u0644\u064e \u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0628\u0650\u0671\u0644\u06e1\u0648\u064e\u0670\u0644\u0650\u062f\u064e\u064a\u06e1\u0646\u0650 \u0625\u0650\u062d\u06e1\u0633\u064e\u0627\u0646\u0657\u0627 \u0648\u064e\u0630\u0650\u064a \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0628\u064e\u0649\u0670 \u0648\u064e\u0671\u0644\u06e1\u064a\u064e\u062a\u064e\u0670\u0645\u064e\u0649\u0670 \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u0633\u064e\u0670\u0643\u0650\u064a\u0646\u0650 \u0648\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627\u0652 \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u062d\u064f\u0633\u06e1\u0646\u0657\u0627 \u0648\u064e\u0623\u064e\u0642\u0650\u064a\u0645\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u0621\u064e\u0627\u062a\u064f\u0648\u0627\u0652 \u0671\u0644\u0632\u0651\u064e\u0643\u064e\u0648\u0670\u0629\u064e \u062b\u064f\u0645\u0651\u064e \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u064a\u06e1\u062a\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u0657\u0627 \u0645\u0651\u0650\u0646\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645 \u0645\u0651\u064f\u0639\u06e1\u0631\u0650\u0636\u064f\u0648\u0646\u064e",translation:"Dan (ingatlah) ketika Kami mengambil janji dari Bani Israil, \"Janganlah kamu menyembah selain Allah, dan berbuat baiklah kepada kedua orang tua, kerabat, anak-anak yatim, dan orang-orang miskin. Dan bertutur katalah yang baik kepada manusia, laksanakan salat dan tunaikanlah zakat.\" Tetapi kemudian kamu berpaling (mengingkari), kecuali sebagian kecil dari kamu, dan kamu (masih menjadi) pembangkang"},{id:84,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0623\u064e\u062e\u064e\u0630\u06e1\u0646\u064e\u0627 \u0645\u0650\u064a\u062b\u064e\u0670\u0642\u064e\u0643\u064f\u0645\u06e1 \u0644\u064e\u0627 \u062a\u064e\u0633\u06e1\u0641\u0650\u0643\u064f\u0648\u0646\u064e \u062f\u0650\u0645\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u062e\u06e1\u0631\u0650\u062c\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u062f\u0650\u064a\u064e\u0670\u0631\u0650\u0643\u064f\u0645\u06e1 \u062b\u064f\u0645\u0651\u064e \u0623\u064e\u0642\u06e1\u0631\u064e\u0631\u06e1\u062a\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0634\u06e1\u0647\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Dan (ingatlah) ketika Kami mengambil janji kamu, \"Janganlah kamu menumpahkan darahmu (membunuh orang), dan mengusir dirimu (saudara sebangsamu) dari kampung halamanmu.\" kemudian kamu berikrar dan bersaksi"},{id:85,text:"\u062b\u064f\u0645\u0651\u064e \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650 \u062a\u064e\u0642\u06e1\u062a\u064f\u0644\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u062a\u064f\u062e\u06e1\u0631\u0650\u062c\u064f\u0648\u0646\u064e \u0641\u064e\u0631\u0650\u064a\u0642\u0657\u0627 \u0645\u0651\u0650\u0646\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u062f\u0650\u064a\u064e\u0670\u0631\u0650\u0647\u0650\u0645\u06e1 \u062a\u064e\u0638\u064e\u0670\u0647\u064e\u0631\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0628\u0650\u0671\u0644\u06e1\u0625\u0650\u062b\u06e1\u0645\u0650 \u0648\u064e\u0671\u0644\u06e1\u0639\u064f\u062f\u06e1\u0648\u064e\u0670\u0646\u0650 \u0648\u064e\u0625\u0650\u0646 \u064a\u064e\u0623\u06e1\u062a\u064f\u0648\u0643\u064f\u0645\u06e1 \u0623\u064f\u0633\u064e\u0670\u0631\u064e\u0649\u0670 \u062a\u064f\u0641\u064e\u0670\u062f\u064f\u0648\u0647\u064f\u0645\u06e1 \u0648\u064e\u0647\u064f\u0648\u064e \u0645\u064f\u062d\u064e\u0631\u0651\u064e\u0645\u064c \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0625\u0650\u062e\u06e1\u0631\u064e\u0627\u062c\u064f\u0647\u064f\u0645\u06e1\u06da \u0623\u064e\u0641\u064e\u062a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0628\u064e\u0639\u06e1\u0636\u0650 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0648\u064e\u062a\u064e\u0643\u06e1\u0641\u064f\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0628\u064e\u0639\u06e1\u0636\u0656\u06da \u0641\u064e\u0645\u064e\u0627 \u062c\u064e\u0632\u064e\u0627\u0653\u0621\u064f \u0645\u064e\u0646 \u064a\u064e\u0641\u06e1\u0639\u064e\u0644\u064f \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u062e\u0650\u0632\u06e1\u064a\u065e \u0641\u0650\u064a \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u0650 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627\u06d6 \u0648\u064e\u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u064a\u064f\u0631\u064e\u062f\u0651\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0634\u064e\u062f\u0651\u0650 \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u0650\u06d7 \u0648\u064e\u0645\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u063a\u064e\u0670\u0641\u0650\u0644\u064d \u0639\u064e\u0645\u0651\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Kemudian kamu (Bani Israil) membunuh dirimu (sesamamu), dan mengusir segolongan dari kamu dari kampung halamannya. Kamu saling membantu (menghadapi) mereka dalam kejahatan dan permusuhan. Dan jika mereka datang kepadamu sebagai tawanan, kamu tebus mereka, padahal kamu dilarang mengusir mereka. Apakah kamu beriman kepada sebagian Kitab (Taurat) dan ingkar kepada sebagian (yang lain)? Maka tidak ada balasan (yang pantas) bagi orang yang berbuat demikian di antara kamu selain kenistaan dalam kehidupan dunia, dan pada hari Kiamat mereka dikembalikan kepada azab yang paling berat. Dan Allah tidak lengah terhadap apa yang kamu kerjakan"},{id:86,text:"\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u0634\u06e1\u062a\u064e\u0631\u064e\u0648\u064f\u0627\u0652 \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u064e \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0628\u0650\u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650\u06d6 \u0641\u064e\u0644\u064e\u0627 \u064a\u064f\u062e\u064e\u0641\u0651\u064e\u0641\u064f \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u06e1 \u064a\u064f\u0646\u0635\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Mereka itulah orang-orang yang membeli kehidupan dunia dengan (kehidupan) akhirat. Maka tidak akan diringankan azabnya dan mereka tidak akan ditolong"},{id:87,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0648\u064e\u0642\u064e\u0641\u0651\u064e\u064a\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u0647\u0650\u06e6 \u0628\u0650\u0671\u0644\u0631\u0651\u064f\u0633\u064f\u0644\u0650\u06d6 \u0648\u064e\u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0627 \u0639\u0650\u064a\u0633\u064e\u0649 \u0671\u0628\u06e1\u0646\u064e \u0645\u064e\u0631\u06e1\u064a\u064e\u0645\u064e \u0671\u0644\u06e1\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0650 \u0648\u064e\u0623\u064e\u064a\u0651\u064e\u062f\u06e1\u0646\u064e\u0670\u0647\u064f \u0628\u0650\u0631\u064f\u0648\u062d\u0650 \u0671\u0644\u06e1\u0642\u064f\u062f\u064f\u0633\u0650\u06d7 \u0623\u064e\u0641\u064e\u0643\u064f\u0644\u0651\u064e\u0645\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u06e1 \u0631\u064e\u0633\u064f\u0648\u0644\u064f\u06e2 \u0628\u0650\u0645\u064e\u0627 \u0644\u064e\u0627 \u062a\u064e\u0647\u06e1\u0648\u064e\u0649\u0670\u0653 \u0623\u064e\u0646\u0641\u064f\u0633\u064f\u0643\u064f\u0645\u064f \u0671\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u064e\u0631\u06e1\u062a\u064f\u0645\u06e1 \u0641\u064e\u0641\u064e\u0631\u0650\u064a\u0642\u0657\u0627 \u0643\u064e\u0630\u0651\u064e\u0628\u06e1\u062a\u064f\u0645\u06e1 \u0648\u064e\u0641\u064e\u0631\u0650\u064a\u0642\u0657\u0627 \u062a\u064e\u0642\u06e1\u062a\u064f\u0644\u064f\u0648\u0646\u064e",translation:"Dan sungguh, Kami telah memberikan Kitab (Taurat) kepada Musa, dan Kami susulkan setelahnya dengan Rasul-rasul, dan kami telah berikan kepada Isa putra Maryam bukti-bukti kebenaran serta Kami perkuat dia dengan Ruhulkudus (Jibril). Mengapa setiap Rasul yang datang kepadamu (membawa) sesuatu (pelajaran) yang tidak kamu inginkan, kamu menyombongkan diri, lalu sebagian kamu dustakan dan sebagian kamu bunuh"},{id:88,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0646\u064e\u0627 \u063a\u064f\u0644\u06e1\u0641\u064f\u06e2\u06da \u0628\u064e\u0644 \u0644\u0651\u064e\u0639\u064e\u0646\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0643\u064f\u0641\u06e1\u0631\u0650\u0647\u0650\u0645\u06e1 \u0641\u064e\u0642\u064e\u0644\u0650\u064a\u0644\u0657\u0627 \u0645\u0651\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Dan mereka berkata, \"Hati kami tertutup.\" Tidak! Allah telah melaknat mereka itu karena keingkaran mereka, tetapi sedikit sekali mereka yang beriman"},{id:89,text:"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u06e1 \u0643\u0650\u062a\u064e\u0670\u0628\u065e \u0645\u0651\u0650\u0646\u06e1 \u0639\u0650\u0646\u062f\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u065e \u0644\u0651\u0650\u0645\u064e\u0627 \u0645\u064e\u0639\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f \u064a\u064e\u0633\u06e1\u062a\u064e\u0641\u06e1\u062a\u0650\u062d\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u0627 \u0639\u064e\u0631\u064e\u0641\u064f\u0648\u0627\u0652 \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6\u06da \u0641\u064e\u0644\u064e\u0639\u06e1\u0646\u064e\u0629\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan setelah sampai kepada mereka Kitab (Alquran) dari Allah yang membenarkan apa yang ada pada mereka39) sedangkan sebelumnya mereka memohon kemenangan atas orang-orang kafir, ternyata setelah sampai kepada mereka apa yang telah mereka ketahui itu, mereka mengingkarinya. Maka laknat Allah bagi orang-orang yang ingkar"},{id:90,text:"\u0628\u0650\u0626\u06e1\u0633\u064e\u0645\u064e\u0627 \u0671\u0634\u06e1\u062a\u064e\u0631\u064e\u0648\u06e1\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u0646 \u064a\u064e\u0643\u06e1\u0641\u064f\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u064e\u063a\u06e1\u064a\u064b\u0627 \u0623\u064e\u0646 \u064a\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646 \u0641\u064e\u0636\u06e1\u0644\u0650\u0647\u0650\u06e6 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0645\u0650\u0646\u06e1 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650\u06e6\u06d6 \u0641\u064e\u0628\u064e\u0627\u0653\u0621\u064f\u0648 \u0628\u0650\u063a\u064e\u0636\u064e\u0628\u064d \u0639\u064e\u0644\u064e\u0649\u0670 \u063a\u064e\u0636\u064e\u0628\u0656\u06da \u0648\u064e\u0644\u0650\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u065e \u0645\u0651\u064f\u0647\u0650\u064a\u0646\u065e",translation:"Sangatlah buruk (perbuatan) mereka menjual dirinya, dengan mengingkari apa yang diturunkan Allah karena dengki, bahwa Allah menurunkan karunia-Nya kepada siapa yang Dia kehendaki di antara hamba-hamba-Nya.40) Karena itulah mereka menanggung kemurkaan demi kemurkaan.41) Dan kepada orang-orang kafir (ditimpakan) azab yang menghinakan"},{id:91,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0621\u064e\u0627\u0645\u0650\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0646\u064f\u0624\u06e1\u0645\u0650\u0646\u064f \u0628\u0650\u0645\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0648\u064e\u064a\u064e\u0643\u06e1\u0641\u064f\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0645\u064e\u0627 \u0648\u064e\u0631\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u06e5 \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f \u0645\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u0657\u0627 \u0644\u0651\u0650\u0645\u064e\u0627 \u0645\u064e\u0639\u064e\u0647\u064f\u0645\u06e1\u06d7 \u0642\u064f\u0644\u06e1 \u0641\u064e\u0644\u0650\u0645\u064e \u062a\u064e\u0642\u06e1\u062a\u064f\u0644\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u06e2\u0628\u0650\u064a\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645 \u0645\u0651\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dan apabila dikatakan kepada mereka, \"Berimanlah kepada apa yang diturunkan Allah (Alquran),\" mereka menjawab, \"Kami beriman kepada apa yang diturunkan kepada kami.\"Dan mereka ingkar kepada apa yang setelahnya, padahal (Alquran) itu adalah hak yang membenarkan apa yang ada pada mereka. Katakanlah (Muhammad), \"Mengapa kamu dahulu membunuh nabi-nabi Allah jika kamu orang-orang beriman"},{id:92,text:"\u06de\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645 \u0645\u0651\u064f\u0648\u0633\u064e\u0649\u0670 \u0628\u0650\u0671\u0644\u06e1\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0650 \u062b\u064f\u0645\u0651\u064e \u0671\u062a\u0651\u064e\u062e\u064e\u0630\u06e1\u062a\u064f\u0645\u064f \u0671\u0644\u06e1\u0639\u0650\u062c\u06e1\u0644\u064e \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u0647\u0650\u06e6 \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0638\u064e\u0670\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Dan sungguh, Musa telah datang kepadamu dengan bukti-bukti kebenaran, kemudian kamu mengambil (patung) anak sapi (sebagai sesembahan) setelah (kepergian) nya, dan kamu (menjadi) orang-orang zalim"},{id:93,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0623\u064e\u062e\u064e\u0630\u06e1\u0646\u064e\u0627 \u0645\u0650\u064a\u062b\u064e\u0670\u0642\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0631\u064e\u0641\u064e\u0639\u06e1\u0646\u064e\u0627 \u0641\u064e\u0648\u06e1\u0642\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0637\u0651\u064f\u0648\u0631\u064e \u062e\u064f\u0630\u064f\u0648\u0627\u0652 \u0645\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0670\u0643\u064f\u0645 \u0628\u0650\u0642\u064f\u0648\u0651\u064e\u0629\u0656 \u0648\u064e\u0671\u0633\u06e1\u0645\u064e\u0639\u064f\u0648\u0627\u0652\u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0633\u064e\u0645\u0650\u0639\u06e1\u0646\u064e\u0627 \u0648\u064e\u0639\u064e\u0635\u064e\u064a\u06e1\u0646\u064e\u0627 \u0648\u064e\u0623\u064f\u0634\u06e1\u0631\u0650\u0628\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u064f \u0671\u0644\u06e1\u0639\u0650\u062c\u06e1\u0644\u064e \u0628\u0650\u0643\u064f\u0641\u06e1\u0631\u0650\u0647\u0650\u0645\u06e1\u06da \u0642\u064f\u0644\u06e1 \u0628\u0650\u0626\u06e1\u0633\u064e\u0645\u064e\u0627 \u064a\u064e\u0623\u06e1\u0645\u064f\u0631\u064f\u0643\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u064a\u0645\u064e\u0670\u0646\u064f\u0643\u064f\u0645\u06e1 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645 \u0645\u0651\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dan (ingatlah) ketika Kami mengambil janji kamu dan Kami angkat gunung (Sinai) di atasmu (seraya berfirman), \"Pegang teguhlah apa yang Kami berikan kepadamu dan dengarkanlah!\" Mereka menjawab, \"Kami mendengarkan tetapi kami tidak menaati.\" Dan diresapkanlah ke dalam hati mereka itu (kecintaan menyembah patung) anak sapi karena kekafiran mereka. Katakanlah, \"Sangat buruk apa yang diperintahkan oleh kepercayaanmu kepadamu jika kamu orang-orang beriman"},{id:94,text:"\u0642\u064f\u0644\u06e1 \u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064e\u062a\u06e1 \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u062f\u0651\u064e\u0627\u0631\u064f \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u064f \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062e\u064e\u0627\u0644\u0650\u0635\u064e\u0629\u0657 \u0645\u0651\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0641\u064e\u062a\u064e\u0645\u064e\u0646\u0651\u064e\u0648\u064f\u0627\u0652 \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u064e \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0635\u064e\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Katakanlah (Muhammad), \"Jika negeri akhirat di sisi Allah, khusus untukmu saja bukan untuk orang lain, maka mintalah kematian jika kamu orang yang benar"},{id:95,text:"\u0648\u064e\u0644\u064e\u0646 \u064a\u064e\u062a\u064e\u0645\u064e\u0646\u0651\u064e\u0648\u06e1\u0647\u064f \u0623\u064e\u0628\u064e\u062f\u064e\u06e2\u0627 \u0628\u0650\u0645\u064e\u0627 \u0642\u064e\u062f\u0651\u064e\u0645\u064e\u062a\u06e1 \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u0647\u0650\u0645\u06e1\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064f\u06e2 \u0628\u0650\u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Tetapi mereka tidak akan menginginkan kematian itu sama sekali, karena dosa-dosa yang telah dilakukan tangan-tangan mereka. Dan Allah Maha Mengetahui orang-orang zalim"},{id:96,text:"\u0648\u064e\u0644\u064e\u062a\u064e\u062c\u0650\u062f\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u062d\u06e1\u0631\u064e\u0635\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0639\u064e\u0644\u064e\u0649\u0670 \u062d\u064e\u064a\u064e\u0648\u0670\u0629\u0656 \u0648\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u0634\u06e1\u0631\u064e\u0643\u064f\u0648\u0627\u0652\u06da \u064a\u064e\u0648\u064e\u062f\u0651\u064f \u0623\u064e\u062d\u064e\u062f\u064f\u0647\u064f\u0645\u06e1 \u0644\u064e\u0648\u06e1 \u064a\u064f\u0639\u064e\u0645\u0651\u064e\u0631\u064f \u0623\u064e\u0644\u06e1\u0641\u064e \u0633\u064e\u0646\u064e\u0629\u0656 \u0648\u064e\u0645\u064e\u0627 \u0647\u064f\u0648\u064e \u0628\u0650\u0645\u064f\u0632\u064e\u062d\u06e1\u0632\u0650\u062d\u0650\u0647\u0650\u06e6 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0623\u064e\u0646 \u064a\u064f\u0639\u064e\u0645\u0651\u064e\u0631\u064e\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u064e\u0635\u0650\u064a\u0631\u064f\u06e2 \u0628\u0650\u0645\u064e\u0627 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan sungguh, engkau (Muhammad) akan mendapati mereka (orang-orang Yahudi), manusia yang paling tamak akan kehidupan (dunia), bahkan (lebih tamak) dari orang-orang musyrik.42) Masing-masing dari mereka, ingin diberi umur seribu tahun, padahal umur panjang itu tidak akan menjauhkan mereka dari azab. Dan Allah Maha melihat apa yang mereka kerjakan"},{id:97,text:"\u0642\u064f\u0644\u06e1 \u0645\u064e\u0646 \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u062f\u064f\u0648\u0651\u0657\u0627 \u0644\u0651\u0650\u0640\u062c\u0650\u0628\u06e1\u0631\u0650\u064a\u0644\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0646\u064e\u0632\u0651\u064e\u0644\u064e\u0647\u064f\u06e5 \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064e\u0644\u06e1\u0628\u0650\u0643\u064e \u0628\u0650\u0625\u0650\u0630\u06e1\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u0657\u0627 \u0644\u0651\u0650\u0645\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u06e1\u0647\u0650 \u0648\u064e\u0647\u064f\u062f\u0657\u0649 \u0648\u064e\u0628\u064f\u0634\u06e1\u0631\u064e\u0649\u0670 \u0644\u0650\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Katakanlah (Muhammad), \"Barang siapa menjadi musuh Jibril, maka (ketahuilah) bahwa dialah yang telah menurunkan (Alquran) ke dalam hatimu dengan izin Allah membenarkan apa (kitab-kitab) yang terdahulu, dan menjadi petunjuk serta berita gembira bagi orang-orang beriman"},{id:98,text:"\u0645\u064e\u0646 \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u062f\u064f\u0648\u0651\u0657\u0627 \u0644\u0651\u0650\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u062a\u0650\u0647\u0650\u06e6 \u0648\u064e\u0631\u064f\u0633\u064f\u0644\u0650\u0647\u0650\u06e6 \u0648\u064e\u062c\u0650\u0628\u06e1\u0631\u0650\u064a\u0644\u064e \u0648\u064e\u0645\u0650\u064a\u0643\u064e\u0649\u0670\u0644\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u062f\u064f\u0648\u0651\u065e \u0644\u0651\u0650\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Barang siapa menjadi musuh Allah, malaikat-malaikat-Nya, rasul-rasul-Nya, Jibril dan Mikail, maka sesungguhnya Allah musuh bagi orang-orang kafir"},{id:99,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u06ed \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0656\u06d6 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0643\u06e1\u0641\u064f\u0631\u064f \u0628\u0650\u0647\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u06e1\u0641\u064e\u0670\u0633\u0650\u0642\u064f\u0648\u0646\u064e",translation:"Dan sungguh, Kami telah menurunkan ayat-ayat yang jelas kepadamu (Muhammad), dan tidaklah ada yang mengingkarinya selain orang-orang fasik"},{id:100,text:"\u0623\u064e\u0648\u064e\u0643\u064f\u0644\u0651\u064e\u0645\u064e\u0627 \u0639\u064e\u0670\u0647\u064e\u062f\u064f\u0648\u0627\u0652 \u0639\u064e\u0647\u06e1\u062f\u0657\u0627 \u0646\u0651\u064e\u0628\u064e\u0630\u064e\u0647\u064f\u06e5 \u0641\u064e\u0631\u0650\u064a\u0642\u065e \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06da \u0628\u064e\u0644\u06e1 \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064f\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Dan mengapa setiap kali mereka mengikat janji, sekelompok mereka melanggarnya? Sedangkan sebagian besar mereka tidak beriman"},{id:101,text:"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u06e1 \u0631\u064e\u0633\u064f\u0648\u0644\u065e \u0645\u0651\u0650\u0646\u06e1 \u0639\u0650\u0646\u062f\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u065e \u0644\u0651\u0650\u0645\u064e\u0627 \u0645\u064e\u0639\u064e\u0647\u064f\u0645\u06e1 \u0646\u064e\u0628\u064e\u0630\u064e \u0641\u064e\u0631\u0650\u064a\u0642\u065e \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0627\u0653\u0621\u064e \u0638\u064f\u0647\u064f\u0648\u0631\u0650\u0647\u0650\u0645\u06e1 \u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan setelah datang kepada mereka seorang Rasul (Muhammad) dari Allah yang membenarkan apa yang ada pada mereka, sebagian dari orang-orang yang diberi Kitab (Taurat) melemparkan Kitab Allah itu ke belakang (punggung), seakan-akan mereka tidak tahu"},{id:102,text:"\u0648\u064e\u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u062a\u064e\u062a\u06e1\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0634\u0651\u064e\u064a\u064e\u0670\u0637\u0650\u064a\u0646\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064f\u0644\u06e1\u0643\u0650 \u0633\u064f\u0644\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u064e\u06d6 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0641\u064e\u0631\u064e \u0633\u064f\u0644\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u064f \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0671\u0644\u0634\u0651\u064e\u064a\u064e\u0670\u0637\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u064a\u064f\u0639\u064e\u0644\u0651\u0650\u0645\u064f\u0648\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0671\u0644\u0633\u0651\u0650\u062d\u06e1\u0631\u064e \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0643\u064e\u064a\u06e1\u0646\u0650 \u0628\u0650\u0628\u064e\u0627\u0628\u0650\u0644\u064e \u0647\u064e\u0670\u0631\u064f\u0648\u062a\u064e \u0648\u064e\u0645\u064e\u0670\u0631\u064f\u0648\u062a\u064e\u06da \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0639\u064e\u0644\u0651\u0650\u0645\u064e\u0627\u0646\u0650 \u0645\u0650\u0646\u06e1 \u0623\u064e\u062d\u064e\u062f\u064d \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0642\u064f\u0648\u0644\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0646\u064e\u062d\u06e1\u0646\u064f \u0641\u0650\u062a\u06e1\u0646\u064e\u0629\u065e \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u06e1\u0641\u064f\u0631\u06e1\u06d6 \u0641\u064e\u064a\u064e\u062a\u064e\u0639\u064e\u0644\u0651\u064e\u0645\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u064e\u0627 \u0645\u064e\u0627 \u064a\u064f\u0641\u064e\u0631\u0651\u0650\u0642\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u0650\u06e6 \u0628\u064e\u064a\u06e1\u0646\u064e \u0671\u0644\u06e1\u0645\u064e\u0631\u06e1\u0621\u0650 \u0648\u064e\u0632\u064e\u0648\u06e1\u062c\u0650\u0647\u0650\u06e6\u06da \u0648\u064e\u0645\u064e\u0627 \u0647\u064f\u0645 \u0628\u0650\u0636\u064e\u0627\u0653\u0631\u0651\u0650\u064a\u0646\u064e \u0628\u0650\u0647\u0650\u06e6 \u0645\u0650\u0646\u06e1 \u0623\u064e\u062d\u064e\u062f\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0625\u0650\u0630\u06e1\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0648\u064e\u064a\u064e\u062a\u064e\u0639\u064e\u0644\u0651\u064e\u0645\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u064a\u064e\u0636\u064f\u0631\u0651\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0646\u0641\u064e\u0639\u064f\u0647\u064f\u0645\u06e1\u06da \u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0639\u064e\u0644\u0650\u0645\u064f\u0648\u0627\u0652 \u0644\u064e\u0645\u064e\u0646\u0650 \u0671\u0634\u06e1\u062a\u064e\u0631\u064e\u0649\u0670\u0647\u064f \u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u06e5 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0645\u0650\u0646\u06e1 \u062e\u064e\u0644\u064e\u0670\u0642\u0656\u06da \u0648\u064e\u0644\u064e\u0628\u0650\u0626\u06e1\u0633\u064e \u0645\u064e\u0627 \u0634\u064e\u0631\u064e\u0648\u06e1\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u06e1\u06da \u0644\u064e\u0648\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan mereka mengikuti apa yang dibaca oleh setan-setan pada masa kerajaan Sulaiman. Sulaiman itu tidak kafir tetapi setan-setan itulah yang kafir, mereka mengajarkan sihir kepada manusia dan apa yang diturunkan kepada dua malaikat di negeri Babilonia yaitu Harut dan Marut. Padahal keduanya tidak mengajarkan sesuatu kepada seseorang sebelum mengatakan, \"Sesungguhnya kami hanyalah cobaan (bagimu), sebab itu janganlah kafir!\" Maka mereka mempelajari dari keduanya (malaikat itu) apa yang (dapat) memisahkan antara seorang (suami) dengan isterinya. Mereka tidak akan dapat mencelakakan seseorang dengan sihirnya kecuali dengan izin Allah. Mereka mempelajari sesuatu yang mencelakakan, dan tidak memberi manfaat kepada mereka. Dan sungguh, mereka sudah tahu, barang siapa membeli (menggunakan sihir) itu, niscaya tidak akan mendapat keuntungan di akhirat. Dan sungguh, sangatlah buruk perbuatan mereka yang menjual dirinya dengan sihir, sekiranya mereka tahu"},{id:103,text:"\u0648\u064e\u0644\u064e\u0648\u06e1 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064e\u0648\u06e1\u0627\u0652 \u0644\u064e\u0645\u064e\u062b\u064f\u0648\u0628\u064e\u0629\u065e \u0645\u0651\u0650\u0646\u06e1 \u0639\u0650\u0646\u062f\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062e\u064e\u064a\u06e1\u0631\u065e\u06da \u0644\u0651\u064e\u0648\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan jika mereka beriman dan bertakwa, pahala dari Allah pasti lebih baik, sekiranya mereka tahu"},{id:104,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627\u0652 \u0631\u064e\u0670\u0639\u0650\u0646\u064e\u0627 \u0648\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627\u0652 \u0671\u0646\u0638\u064f\u0631\u06e1\u0646\u064e\u0627 \u0648\u064e\u0671\u0633\u06e1\u0645\u064e\u0639\u064f\u0648\u0627\u0652\u06d7 \u0648\u064e\u0644\u0650\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u065e",translation:"(Wahai orang-orang yang beriman! Janganlah kamu katakan, R\u0101'in\u0101,43) tetapi katakanlah, \"Un\u1e93urn\u0101,\" dan \"dengarkanlah. Dan orang-orang kafir akan mendapat azab yang pedih"},{id:105,text:"\u0645\u0651\u064e\u0627 \u064a\u064e\u0648\u064e\u062f\u0651\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1 \u0623\u064e\u0647\u06e1\u0644\u0650 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0648\u064e\u0644\u064e\u0627 \u0671\u0644\u06e1\u0645\u064f\u0634\u06e1\u0631\u0650\u0643\u0650\u064a\u0646\u064e \u0623\u064e\u0646 \u064a\u064f\u0646\u064e\u0632\u0651\u064e\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u062e\u064e\u064a\u06e1\u0631\u0656 \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u062e\u06e1\u062a\u064e\u0635\u0651\u064f \u0628\u0650\u0631\u064e\u062d\u06e1\u0645\u064e\u062a\u0650\u0647\u0650\u06e6 \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0630\u064f\u0648 \u0671\u0644\u06e1\u0641\u064e\u0636\u06e1\u0644\u0650 \u0671\u0644\u06e1\u0639\u064e\u0638\u0650\u064a\u0645\u0650",translation:"Orang-orang yang kafir dari Ahli Kitab dan orang-orang musyrik tidak menginginkan diturunkannya kepadamu suatu kebaikan dari Tuhanmu. Tetapi secara khusus Allah memberikan rahmat-Nya kepada orang yang Dia kehendaki. Dan Allah pemilik karunia yang besar"},{id:106,text:"\u06de\u0645\u064e\u0627 \u0646\u064e\u0646\u0633\u064e\u062e\u06e1 \u0645\u0650\u0646\u06e1 \u0621\u064e\u0627\u064a\u064e\u0629\u064d \u0623\u064e\u0648\u06e1 \u0646\u064f\u0646\u0633\u0650\u0647\u064e\u0627 \u0646\u064e\u0623\u06e1\u062a\u0650 \u0628\u0650\u062e\u064e\u064a\u06e1\u0631\u0656 \u0645\u0651\u0650\u0646\u06e1\u0647\u064e\u0627\u0653 \u0623\u064e\u0648\u06e1 \u0645\u0650\u062b\u06e1\u0644\u0650\u0647\u064e\u0627\u0653\u06d7 \u0623\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u06e1 \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0642\u064e\u062f\u0650\u064a\u0631\u064c",translation:"Ayat yang Kami batalkan atau Kami hilangkan dari ingatan, pasti Kami ganti dengan yang lebih baik atau yang sebanding dengannya. Tidakkah kamu tahu bahwa Allah Mahakuasa atas segala sesuatu"},{id:107,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u06e1 \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0647\u064f\u06e5 \u0645\u064f\u0644\u06e1\u0643\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d7 \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646 \u0648\u064e\u0644\u0650\u064a\u0651\u0656 \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0635\u0650\u064a\u0631\u064d",translation:"Tidakkah kamu tahu bahwa Allah memiliki kerajaan langit dan bumi? Dan tidak ada bagimu pelindung dan penolong selain Allah"},{id:108,text:"\u0623\u064e\u0645\u06e1 \u062a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0623\u064e\u0646 \u062a\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0648\u0627\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0643\u064f\u0645\u06e1 \u0643\u064e\u0645\u064e\u0627 \u0633\u064f\u0626\u0650\u0644\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f\u06d7 \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u062a\u064e\u0628\u064e\u062f\u0651\u064e\u0644\u0650 \u0671\u0644\u06e1\u0643\u064f\u0641\u06e1\u0631\u064e \u0628\u0650\u0671\u0644\u06e1\u0625\u0650\u064a\u0645\u064e\u0670\u0646\u0650 \u0641\u064e\u0642\u064e\u062f\u06e1 \u0636\u064e\u0644\u0651\u064e \u0633\u064e\u0648\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u0650",translation:"Ataukah kamu hendak meminta kepada Rasulmu (Muhammad) seperti halnya Musa (pernah) diminta (Bani Israil) dahulu? Barang siapa mengganti iman dengan kekafiran, maka sungguh, dia telah tersesat dari jalan yang lurus"},{id:109,text:"\u0648\u064e\u062f\u0651\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u065e \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u0647\u06e1\u0644\u0650 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0644\u064e\u0648\u06e1 \u064a\u064e\u0631\u064f\u062f\u0651\u064f\u0648\u0646\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0625\u0650\u064a\u0645\u064e\u0670\u0646\u0650\u0643\u064f\u0645\u06e1 \u0643\u064f\u0641\u0651\u064e\u0627\u0631\u064b\u0627 \u062d\u064e\u0633\u064e\u062f\u0657\u0627 \u0645\u0651\u0650\u0646\u06e1 \u0639\u0650\u0646\u062f\u0650 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645 \u0645\u0651\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0645\u064e\u0627 \u062a\u064e\u0628\u064e\u064a\u0651\u064e\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f\u06d6 \u0641\u064e\u0671\u0639\u06e1\u0641\u064f\u0648\u0627\u0652 \u0648\u064e\u0671\u0635\u06e1\u0641\u064e\u062d\u064f\u0648\u0627\u0652 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0623\u064e\u0645\u06e1\u0631\u0650\u0647\u0650\u06e6\u0653\u06d7 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0642\u064e\u062f\u0650\u064a\u0631\u065e",translation:"Banyak di antara Ahli Kitab menginginkan sekiranya mereka dapat mengembalikan kamu setelah kamu beriman, menjadi kafir kembali, karena rasa dengki dalam diri mereka, setelah kebenaran jelas bagi mereka. Maka maafkanlah dan berlapang dadalah, sampai Allah memberikan perintah-Nya. Sungguh, Allah Mahakuasa atas segala sesuatu"},{id:110,text:"\u0648\u064e\u0623\u064e\u0642\u0650\u064a\u0645\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u0621\u064e\u0627\u062a\u064f\u0648\u0627\u0652 \u0671\u0644\u0632\u0651\u064e\u0643\u064e\u0648\u0670\u0629\u064e\u06da \u0648\u064e\u0645\u064e\u0627 \u062a\u064f\u0642\u064e\u062f\u0651\u0650\u0645\u064f\u0648\u0627\u0652 \u0644\u0650\u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u062e\u064e\u064a\u06e1\u0631\u0656 \u062a\u064e\u062c\u0650\u062f\u064f\u0648\u0647\u064f \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d7 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0628\u064e\u0635\u0650\u064a\u0631\u065e",translation:"Dan laksanakanlah salat dan tunaikanlah zakat. Dan segala kebaikan yang kamu kerjakan untuk dirimu, kamu akan mendapatkannya (pahala) di sisi Allah. Sungguh, Allah Maha Melihat apa yang kamu kerjakan"},{id:111,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0646 \u064a\u064e\u062f\u06e1\u062e\u064f\u0644\u064e \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646 \u0643\u064e\u0627\u0646\u064e \u0647\u064f\u0648\u062f\u064b\u0627 \u0623\u064e\u0648\u06e1 \u0646\u064e\u0635\u064e\u0670\u0631\u064e\u0649\u0670\u06d7 \u062a\u0650\u0644\u06e1\u0643\u064e \u0623\u064e\u0645\u064e\u0627\u0646\u0650\u064a\u0651\u064f\u0647\u064f\u0645\u06e1\u06d7 \u0642\u064f\u0644\u06e1 \u0647\u064e\u0627\u062a\u064f\u0648\u0627\u0652 \u0628\u064f\u0631\u06e1\u0647\u064e\u0670\u0646\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0635\u064e\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Dan mereka (Yahudi dan Nasrani) berkata, \"Tidak akan masuk surga kecuali orang Yahudi atau Nasrani.\"44) Itu (hanya) angan-angan mereka. Katakanlah, \"Tunjukkan bukti kebenaranmu jika kamu orang yang benar"},{id:112,text:"\u0628\u064e\u0644\u064e\u0649\u0670\u06da \u0645\u064e\u0646\u06e1 \u0623\u064e\u0633\u06e1\u0644\u064e\u0645\u064e \u0648\u064e\u062c\u06e1\u0647\u064e\u0647\u064f\u06e5 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0647\u064f\u0648\u064e \u0645\u064f\u062d\u06e1\u0633\u0650\u0646\u065e \u0641\u064e\u0644\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u062c\u06e1\u0631\u064f\u0647\u064f\u06e5 \u0639\u0650\u0646\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u06e6 \u0648\u064e\u0644\u064e\u0627 \u062e\u064e\u0648\u06e1\u0641\u064c \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u06e1 \u064a\u064e\u062d\u06e1\u0632\u064e\u0646\u064f\u0648\u0646\u064e",translation:"Tidak! Barang siapa menyerahkan diri sepenuhnya kepada Allah, dan dia berbuat baik, dia mendapat pahala di sisi Tuhannya dan tidak ada rasa takut pada mereka dan mereka tidak bersedih hati"},{id:113,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e\u062a\u0650 \u0671\u0644\u06e1\u064a\u064e\u0647\u064f\u0648\u062f\u064f \u0644\u064e\u064a\u06e1\u0633\u064e\u062a\u0650 \u0671\u0644\u0646\u0651\u064e\u0635\u064e\u0670\u0631\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649\u0670 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0648\u064e\u0642\u064e\u0627\u0644\u064e\u062a\u0650 \u0671\u0644\u0646\u0651\u064e\u0635\u064e\u0670\u0631\u064e\u0649\u0670 \u0644\u064e\u064a\u06e1\u0633\u064e\u062a\u0650 \u0671\u0644\u06e1\u064a\u064e\u0647\u064f\u0648\u062f\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0648\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u062a\u06e1\u0644\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e\u06d7 \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0645\u0650\u062b\u06e1\u0644\u064e \u0642\u064e\u0648\u06e1\u0644\u0650\u0647\u0650\u0645\u06e1\u06da \u0641\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u062d\u06e1\u0643\u064f\u0645\u064f \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u0641\u0650\u064a\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0647\u0650 \u064a\u064e\u062e\u06e1\u062a\u064e\u0644\u0650\u0641\u064f\u0648\u0646\u064e",translation:"Dan orang Yahudi berkata, \"Orang Nasrani itu tidak memiliki sesuatu (pegangan),\" dan orang-orang Nasrani (juga) berkata, \"Orang-orang Yahudi tidak memiliki sesuatu (pegangan),\" padahal mereka membaca Kitab. Demikian pula orang-orang yang tidak berilmu, berkata seperti ucapan mereka itu. Maka Allah akan mengadili mereka pada hari Kiamat, tentang apa yang mereka perselisihkan"},{id:114,text:"\u0648\u064e\u0645\u064e\u0646\u06e1 \u0623\u064e\u0638\u06e1\u0644\u064e\u0645\u064f \u0645\u0650\u0645\u0651\u064e\u0646 \u0645\u0651\u064e\u0646\u064e\u0639\u064e \u0645\u064e\u0633\u064e\u0670\u062c\u0650\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0646 \u064a\u064f\u0630\u06e1\u0643\u064e\u0631\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0671\u0633\u06e1\u0645\u064f\u0647\u064f\u06e5 \u0648\u064e\u0633\u064e\u0639\u064e\u0649\u0670 \u0641\u0650\u064a \u062e\u064e\u0631\u064e\u0627\u0628\u0650\u0647\u064e\u0627\u0653\u06da \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u0646 \u064a\u064e\u062f\u06e1\u062e\u064f\u0644\u064f\u0648\u0647\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u062e\u064e\u0627\u0653\u0626\u0650\u0641\u0650\u064a\u0646\u064e\u06da \u0644\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u062e\u0650\u0632\u06e1\u064a\u065e \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u065e",translation:"Dan siapakah yang lebih zalim daripada orang yang melarang di dalam masjid-masjid Allah untuk menyebut nama-Nya, dan berusaha merobohkannya? Mereka itu tidak pantas memasukinya kecuali dengan rasa takut (kepada Allah). Mereka mendapat kehinaan di dunia dan di akhirat mendapat azab yang berat"},{id:115,text:"\u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u0645\u064e\u0634\u06e1\u0631\u0650\u0642\u064f \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u063a\u06e1\u0631\u0650\u0628\u064f\u06da \u0641\u064e\u0623\u064e\u064a\u06e1\u0646\u064e\u0645\u064e\u0627 \u062a\u064f\u0648\u064e\u0644\u0651\u064f\u0648\u0627\u0652 \u0641\u064e\u062b\u064e\u0645\u0651\u064e \u0648\u064e\u062c\u06e1\u0647\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0670\u0633\u0650\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Dan milik Allah timur dan barat. Ke manapun kamu menghadap di sanalah wajah Allah. Sungguh, Allah Mahaluas, Maha Mengetahui"},{id:116,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0644\u064e\u062f\u0657\u0627\u06d7 \u0633\u064f\u0628\u06e1\u062d\u064e\u0670\u0646\u064e\u0647\u064f\u06e5\u06d6 \u0628\u064e\u0644 \u0644\u0651\u064e\u0647\u064f\u06e5 \u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d6 \u0643\u064f\u0644\u0651\u065e \u0644\u0651\u064e\u0647\u064f\u06e5 \u0642\u064e\u0670\u0646\u0650\u062a\u064f\u0648\u0646\u064e",translation:"Dan mereka berkata, \"Allah mempunyai anak.\" Mahasuci Allah, bahkan milik-Nyalah apa yang di langit dan di bumi. Semua tunduk kepada-Nya"},{id:117,text:"\u0628\u064e\u062f\u0650\u064a\u0639\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d6 \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u064e\u0636\u064e\u0649\u0670\u0653 \u0623\u064e\u0645\u06e1\u0631\u0657\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0644\u064e\u0647\u064f\u06e5 \u0643\u064f\u0646 \u0641\u064e\u064a\u064e\u0643\u064f\u0648\u0646\u064f",translation:"(Allah) Pencipta langit dan bumi. Apabila Dia hendak menetapkan sesuatu, Dia hanya berkata kepadanya, \"Jadilah!\" Maka jadilah sesuatu itu"},{id:118,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0644\u064e\u0648\u06e1\u0644\u064e\u0627 \u064a\u064f\u0643\u064e\u0644\u0651\u0650\u0645\u064f\u0646\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0648\u06e1 \u062a\u064e\u0623\u06e1\u062a\u0650\u064a\u0646\u064e\u0627\u0653 \u0621\u064e\u0627\u064a\u064e\u0629\u065e\u06d7 \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u0645 \u0645\u0651\u0650\u062b\u06e1\u0644\u064e \u0642\u064e\u0648\u06e1\u0644\u0650\u0647\u0650\u0645\u06e1\u06d8 \u062a\u064e\u0634\u064e\u0670\u0628\u064e\u0647\u064e\u062a\u06e1 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u06e1\u06d7 \u0642\u064e\u062f\u06e1 \u0628\u064e\u064a\u0651\u064e\u0646\u0651\u064e\u0627 \u0671\u0644\u06e1\u0623\u0653\u064a\u064e\u0670\u062a\u0650 \u0644\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064f\u0648\u0642\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Dan orang-orang yang tidak mengetahui berkata, \"Mengapa Allah tidak berbicara dengan kita atau datang tanda-tanda (kekuasaan-Nya) kepada kita?\" Demikian pula orang-orang yang sebelum mereka telah berkata seperti ucapan mereka itu. Hati mereka serupa. Sesungguhnya telah Kami jelaskan tanda-tanda (kekuasaan Kami) kepada orang-orang yang yakin"},{id:119,text:"\u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0670\u0643\u064e \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0628\u064e\u0634\u0650\u064a\u0631\u0657\u0627 \u0648\u064e\u0646\u064e\u0630\u0650\u064a\u0631\u0657\u0627\u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0633\u06e1\u0640\u0654\u064e\u0644\u064f \u0639\u064e\u0646\u06e1 \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u0650 \u0671\u0644\u06e1\u062c\u064e\u062d\u0650\u064a\u0645\u0650",translation:"Sungguh, Kami telah mengutusmu (Muhammad) dengan kebenaran, sebagai pembawa berita gembira dan pemberi peringatan. Dan engkau tidak akan diminta (pertang\xad\xad\xadgung\xad\xad\xad\xad\xad jawaban) tentang penghuni-penghuni neraka"},{id:120,text:"\u0648\u064e\u0644\u064e\u0646 \u062a\u064e\u0631\u06e1\u0636\u064e\u0649\u0670 \u0639\u064e\u0646\u0643\u064e \u0671\u0644\u06e1\u064a\u064e\u0647\u064f\u0648\u062f\u064f \u0648\u064e\u0644\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0635\u064e\u0670\u0631\u064e\u0649\u0670 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064e \u0645\u0650\u0644\u0651\u064e\u062a\u064e\u0647\u064f\u0645\u06e1\u06d7 \u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u064e \u0647\u064f\u062f\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0647\u064f\u062f\u064e\u0649\u0670\u06d7 \u0648\u064e\u0644\u064e\u0626\u0650\u0646\u0650 \u0671\u062a\u0651\u064e\u0628\u064e\u0639\u06e1\u062a\u064e \u0623\u064e\u0647\u06e1\u0648\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645 \u0628\u064e\u0639\u06e1\u062f\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0627\u0653\u0621\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0639\u0650\u0644\u06e1\u0645\u0650 \u0645\u064e\u0627 \u0644\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646 \u0648\u064e\u0644\u0650\u064a\u0651\u0656 \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0635\u0650\u064a\u0631\u064d",translation:"Dan orang-orang Yahudi dan Nasrani tidak akan rela kepadamu (Muhammad) sebelum engkau mengikuti agama mereka. Katakanlah, \"Sesungguhnya petunjuk Allah itulah petunjuk (yang sebenarnya).\" Dan jika engkau mengikuti keinginan mereka setelah ilmu (kebenaran) sampai kepadamu, tidak akan ada bagimu pelindung dan penolong dari Allah"},{id:121,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u064a\u064e\u062a\u06e1\u0644\u064f\u0648\u0646\u064e\u0647\u064f\u06e5 \u062d\u064e\u0642\u0651\u064e \u062a\u0650\u0644\u064e\u0627\u0648\u064e\u062a\u0650\u0647\u0650\u06e6\u0653 \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u0650\u06e6\u06d7 \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0643\u06e1\u0641\u064f\u0631\u06e1 \u0628\u0650\u0647\u0650\u06e6 \u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u062e\u064e\u0670\u0633\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Orang-orang yang telah Kami beri Kitab, mereka membacanya sebagaimana mestinya, mereka itulah yang beriman kepadanya. Dan barang siapa ingkar kepadanya, mereka itulah orang-orang yang rugi"},{id:122,text:"\u064a\u064e\u0670\u0628\u064e\u0646\u0650\u064a\u0653 \u0625\u0650\u0633\u06e1\u0631\u064e\u0640\u0670\u0653\u0621\u0650\u064a\u0644\u064e \u0671\u0630\u06e1\u0643\u064f\u0631\u064f\u0648\u0627\u0652 \u0646\u0650\u0639\u06e1\u0645\u064e\u062a\u0650\u064a\u064e \u0671\u0644\u0651\u064e\u062a\u0650\u064a\u0653 \u0623\u064e\u0646\u06e1\u0639\u064e\u0645\u06e1\u062a\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0646\u0651\u0650\u064a \u0641\u064e\u0636\u0651\u064e\u0644\u06e1\u062a\u064f\u0643\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Wahai Bani Israil! Ingatlah nikmat-Ku yang telah Aku berikan kepadamu dan Aku telah melebihkan kamu dari semua umat yang lain di alam ini (pada masa itu)"},{id:123,text:"\u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u064a\u064e\u0648\u06e1\u0645\u0657\u0627 \u0644\u0651\u064e\u0627 \u062a\u064e\u062c\u06e1\u0632\u0650\u064a \u0646\u064e\u0641\u06e1\u0633\u064c \u0639\u064e\u0646 \u0646\u0651\u064e\u0641\u06e1\u0633\u0656 \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0642\u06e1\u0628\u064e\u0644\u064f \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0639\u064e\u062f\u06e1\u0644\u065e \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0646\u0641\u064e\u0639\u064f\u0647\u064e\u0627 \u0634\u064e\u0641\u064e\u0670\u0639\u064e\u0629\u065e \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u06e1 \u064a\u064f\u0646\u0635\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan takutlah kamu pada hari, (ketika) tidak seorangpun dapat menggantikan (membela) orang lain sedikit pun, tebusan tidak diterima, bantuan tidak berguna baginya, dan mereka tidak akan ditolong"},{id:124,text:"\u06de\u0648\u064e\u0625\u0650\u0630\u0650 \u0671\u0628\u06e1\u062a\u064e\u0644\u064e\u0649\u0670\u0653 \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u0640\u06e7\u0645\u064e \u0631\u064e\u0628\u0651\u064f\u0647\u064f\u06e5 \u0628\u0650\u0643\u064e\u0644\u0650\u0645\u064e\u0670\u062a\u0656 \u0641\u064e\u0623\u064e\u062a\u064e\u0645\u0651\u064e\u0647\u064f\u0646\u0651\u064e\u06d6 \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u062c\u064e\u0627\u0639\u0650\u0644\u064f\u0643\u064e \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0625\u0650\u0645\u064e\u0627\u0645\u0657\u0627\u06d6 \u0642\u064e\u0627\u0644\u064e \u0648\u064e\u0645\u0650\u0646 \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u062a\u0650\u064a\u06d6 \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0627 \u064a\u064e\u0646\u064e\u0627\u0644\u064f \u0639\u064e\u0647\u06e1\u062f\u0650\u064a \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dan (ingatlah), ketika Ibrahim diuji Tuhannya dengan beberapa kalimat, lalu dia melaksanakannya dengan sempurna. Dia (Allah) berfirman, \"Sesungguhnya Aku menjadikan engkau sebagai pemimpin bagi seluruh manusia.\" Dia (Ibrahim) berkata, \"Dan (juga) dari anak cucuku?\" Allah berfirman, \"(Benar, tetapi) janji-Ku tidak berlaku bagi orang-orang zalim"},{id:125,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0628\u064e\u064a\u06e1\u062a\u064e \u0645\u064e\u062b\u064e\u0627\u0628\u064e\u0629\u0657 \u0644\u0651\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0623\u064e\u0645\u06e1\u0646\u0657\u0627 \u0648\u064e\u0671\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0645\u0651\u064e\u0642\u064e\u0627\u0645\u0650 \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u0640\u06e7\u0645\u064e \u0645\u064f\u0635\u064e\u0644\u0651\u0657\u0649\u06d6 \u0648\u064e\u0639\u064e\u0647\u0650\u062f\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u0640\u06e7\u0645\u064e \u0648\u064e\u0625\u0650\u0633\u06e1\u0645\u064e\u0670\u0639\u0650\u064a\u0644\u064e \u0623\u064e\u0646 \u0637\u064e\u0647\u0651\u0650\u0631\u064e\u0627 \u0628\u064e\u064a\u06e1\u062a\u0650\u064a\u064e \u0644\u0650\u0644\u0637\u0651\u064e\u0627\u0653\u0626\u0650\u0641\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u0639\u064e\u0670\u0643\u0650\u0641\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u0631\u0651\u064f\u0643\u0651\u064e\u0639\u0650 \u0671\u0644\u0633\u0651\u064f\u062c\u064f\u0648\u062f\u0650",translation:"Dan (ingatlah), ketika Kami menjadikan rumah (Ka'bah) tempat berkumpul dan tempat yang aman bagi manusia. Dan jadikanlah maqam Ibrahim 45) itu tempat salat. Dan telah Kami perintahkan kepada Ibrahim dan Ismail, \"Bersihkanlah rumah-Ku untuk orang-orang yang tawaf, orang yang itikaf, orang yang rukuk dan orang yang sujud"},{id:126,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u0640\u06e7\u0645\u064f \u0631\u064e\u0628\u0651\u0650 \u0671\u062c\u06e1\u0639\u064e\u0644\u06e1 \u0647\u064e\u0670\u0630\u064e\u0627 \u0628\u064e\u0644\u064e\u062f\u064b\u0627 \u0621\u064e\u0627\u0645\u0650\u0646\u0657\u0627 \u0648\u064e\u0671\u0631\u06e1\u0632\u064f\u0642\u06e1 \u0623\u064e\u0647\u06e1\u0644\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646\u064e \u0671\u0644\u062b\u0651\u064e\u0645\u064e\u0631\u064e\u0670\u062a\u0650 \u0645\u064e\u0646\u06e1 \u0621\u064e\u0627\u0645\u064e\u0646\u064e \u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u0650\u06da \u0642\u064e\u0627\u0644\u064e \u0648\u064e\u0645\u064e\u0646 \u0643\u064e\u0641\u064e\u0631\u064e \u0641\u064e\u0623\u064f\u0645\u064e\u062a\u0651\u0650\u0639\u064f\u0647\u064f\u06e5 \u0642\u064e\u0644\u0650\u064a\u0644\u0657\u0627 \u062b\u064f\u0645\u0651\u064e \u0623\u064e\u0636\u06e1\u0637\u064e\u0631\u0651\u064f\u0647\u064f\u06e5\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650\u06d6 \u0648\u064e\u0628\u0650\u0626\u06e1\u0633\u064e \u0671\u0644\u06e1\u0645\u064e\u0635\u0650\u064a\u0631\u064f",translation:"Dan (ingatlah), ketika Ibrahim berdoa, \"Ya Tuhanku, jadikanlah (negeri Mekkah) ini negeri yang aman dan berilah rezeki berupa buah-buahan kepada penduduknya, yaitu diantara mereka yang beriman kepada Allah dan hari kemudian,\" Dia (Allah) berfirman, \"Dan kepada orang yang kafir akan Aku beri kesenangan sementara, kemudian akan Aku paksa dia ke dalam azab neraka dan itulah seburuk-buruk tempat kembali"},{id:127,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u064a\u064e\u0631\u06e1\u0641\u064e\u0639\u064f \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u0640\u06e7\u0645\u064f \u0671\u0644\u06e1\u0642\u064e\u0648\u064e\u0627\u0639\u0650\u062f\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0628\u064e\u064a\u06e1\u062a\u0650 \u0648\u064e\u0625\u0650\u0633\u06e1\u0645\u064e\u0670\u0639\u0650\u064a\u0644\u064f \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u062a\u064e\u0642\u064e\u0628\u0651\u064e\u0644\u06e1 \u0645\u0650\u0646\u0651\u064e\u0627\u0653\u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0623\u064e\u0646\u062a\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u0650\u064a\u0639\u064f \u0671\u0644\u06e1\u0639\u064e\u0644\u0650\u064a\u0645\u064f",translation:"Dan (ingatlah) ketika Ibrahim meninggikan pondasi Baitullah bersama Ismail (seraya berdoa), \"Ya Tuhan kami, terimalah (amal) dari kami. Sungguh, Engkaulah Yang Maha Mendengar, Maha Mengetahui"},{id:128,text:"\u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0648\u064e\u0671\u062c\u06e1\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0645\u064f\u0633\u06e1\u0644\u0650\u0645\u064e\u064a\u06e1\u0646\u0650 \u0644\u064e\u0643\u064e \u0648\u064e\u0645\u0650\u0646 \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u062a\u0650\u0646\u064e\u0627\u0653 \u0623\u064f\u0645\u0651\u064e\u0629\u0657 \u0645\u0651\u064f\u0633\u06e1\u0644\u0650\u0645\u064e\u0629\u0657 \u0644\u0651\u064e\u0643\u064e \u0648\u064e\u0623\u064e\u0631\u0650\u0646\u064e\u0627 \u0645\u064e\u0646\u064e\u0627\u0633\u0650\u0643\u064e\u0646\u064e\u0627 \u0648\u064e\u062a\u064f\u0628\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627\u0653\u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0623\u064e\u0646\u062a\u064e \u0671\u0644\u062a\u0651\u064e\u0648\u0651\u064e\u0627\u0628\u064f \u0671\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",translation:"Ya Tuhan kami, jadikanlah kami orang yang berserah diri kepada-Mu, dan anak cucu kami (juga) umat yang berserah diri kepada-Mu dan tunjukkanlah kepada kami cara-cara melakukan (ibadah) haji kami, dan terimalah tobat kami. Sungguh, Engkaulah Yang Maha Penerima tobat, Maha Penyayang"},{id:129,text:"\u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0648\u064e\u0671\u0628\u06e1\u0639\u064e\u062b\u06e1 \u0641\u0650\u064a\u0647\u0650\u0645\u06e1 \u0631\u064e\u0633\u064f\u0648\u0644\u0657\u0627 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u064a\u064e\u062a\u06e1\u0644\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0643\u064e \u0648\u064e\u064a\u064f\u0639\u064e\u0644\u0651\u0650\u0645\u064f\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0648\u064e\u0671\u0644\u06e1\u062d\u0650\u0643\u06e1\u0645\u064e\u0629\u064e \u0648\u064e\u064a\u064f\u0632\u064e\u0643\u0651\u0650\u064a\u0647\u0650\u0645\u06e1\u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0623\u064e\u0646\u062a\u064e \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0671\u0644\u06e1\u062d\u064e\u0643\u0650\u064a\u0645\u064f",translation:"Ya Tuhan kami, utuslah di tengah mereka seorang rasul dari kalangan mereka sendiri, yang akan membacakan kepada mereka ayat-ayat-Mu, dan mengajarkan Kitab dan Hikmah kepada mereka, dan menyucikan mereka. Sungguh, Engkaulah Yang Mahaperkasa, Mahabijaksana"},{id:130,text:"\u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0631\u06e1\u063a\u064e\u0628\u064f \u0639\u064e\u0646 \u0645\u0651\u0650\u0644\u0651\u064e\u0629\u0650 \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u0640\u06e7\u0645\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646 \u0633\u064e\u0641\u0650\u0647\u064e \u0646\u064e\u0641\u06e1\u0633\u064e\u0647\u064f\u06e5\u06da \u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0650 \u0671\u0635\u06e1\u0637\u064e\u0641\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f \u0641\u0650\u064a \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627\u06d6 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0644\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u0650\u064a\u0646\u064e",translation:"Dan orang yang membenci agama Ibrahim, hanyalah orang yang memperbodoh dirinya sendiri. Dan sungguh, Kami telah memilihnya (Ibrahim) di dunia ini. Dan sesungguhnya di akhirat dia termasuk orang-orang yang saleh"},{id:131,text:"\u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f\u06e5 \u0631\u064e\u0628\u0651\u064f\u0647\u064f\u06e5\u0653 \u0623\u064e\u0633\u06e1\u0644\u0650\u0645\u06e1\u06d6 \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0633\u06e1\u0644\u064e\u0645\u06e1\u062a\u064f \u0644\u0650\u0631\u064e\u0628\u0651\u0650 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"(Ingatlah) ketika Tuhan berfirman kepadanya (Ibrahim), \"Berserah dirilah!\" Dia menjawab, \"Aku berserah diri kepada Tuhan seluruh alam"},{id:132,text:"\u0648\u064e\u0648\u064e\u0635\u0651\u064e\u0649\u0670 \u0628\u0650\u0647\u064e\u0627\u0653 \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u0640\u06e7\u0645\u064f \u0628\u064e\u0646\u0650\u064a\u0647\u0650 \u0648\u064e\u064a\u064e\u0639\u06e1\u0642\u064f\u0648\u0628\u064f \u064a\u064e\u0670\u0628\u064e\u0646\u0650\u064a\u0651\u064e \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0671\u0635\u06e1\u0637\u064e\u0641\u064e\u0649\u0670 \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u064e \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0645\u064f\u0648\u062a\u064f\u0646\u0651\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645 \u0645\u0651\u064f\u0633\u06e1\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Dan Ibrahim mewasiatkan (ucapan) itu kepada anak-anaknya, demikian pula Yakub. \"Wahai anak-anakku! Sesungguhnya Allah telah memilih agama ini untukmu, maka janganlah kamu mati kecuali dalam keadaan muslim"},{id:133,text:"\u0623\u064e\u0645\u06e1 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0634\u064f\u0647\u064e\u062f\u064e\u0627\u0653\u0621\u064e \u0625\u0650\u0630\u06e1 \u062d\u064e\u0636\u064e\u0631\u064e \u064a\u064e\u0639\u06e1\u0642\u064f\u0648\u0628\u064e \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u064f \u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0628\u064e\u0646\u0650\u064a\u0647\u0650 \u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u064a\u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0646\u064e\u0639\u06e1\u0628\u064f\u062f\u064f \u0625\u0650\u0644\u064e\u0670\u0647\u064e\u0643\u064e \u0648\u064e\u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0626\u0650\u0643\u064e \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u0640\u06e7\u0645\u064e \u0648\u064e\u0625\u0650\u0633\u06e1\u0645\u064e\u0670\u0639\u0650\u064a\u0644\u064e \u0648\u064e\u0625\u0650\u0633\u06e1\u062d\u064e\u0670\u0642\u064e \u0625\u0650\u0644\u064e\u0670\u0647\u0657\u0627 \u0648\u064e\u0670\u062d\u0650\u062f\u0657\u0627 \u0648\u064e\u0646\u064e\u062d\u06e1\u0646\u064f \u0644\u064e\u0647\u064f\u06e5 \u0645\u064f\u0633\u06e1\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Apakah kamu menjadi saksi saat maut akan menjemput Yakub, ketika dia berkata kepada anak-anaknya, \"Apa yang kamu sembah sepeninggalku?\" Mereka menjawab, \"Kami akan menyembah Tuhanmu dan Tuhan nenek moyangmu yaitu Ibrahim, Ismail dan Ishak, (yaitu) Tuhan Yang Mahaesa dan kami (hanya) berserah diri kepada-Nya"},{id:134,text:"\u062a\u0650\u0644\u06e1\u0643\u064e \u0623\u064f\u0645\u0651\u064e\u0629\u065e \u0642\u064e\u062f\u06e1 \u062e\u064e\u0644\u064e\u062a\u06e1\u06d6 \u0644\u064e\u0647\u064e\u0627 \u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064e\u062a\u06e1 \u0648\u064e\u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u06e1\u062a\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0648\u0646\u064e \u0639\u064e\u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Itulah umat yang telah lalu. Baginya apa yang telah mereka usahakan dan bagimu apa yang telah kamu usahakan. Dan kamu tidak akan diminta (pertanggungjawaban) tentang apa yang dahulu mereka kerjakan"},{id:135,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u0647\u064f\u0648\u062f\u064b\u0627 \u0623\u064e\u0648\u06e1 \u0646\u064e\u0635\u064e\u0670\u0631\u064e\u0649\u0670 \u062a\u064e\u0647\u06e1\u062a\u064e\u062f\u064f\u0648\u0627\u0652\u06d7 \u0642\u064f\u0644\u06e1 \u0628\u064e\u0644\u06e1 \u0645\u0650\u0644\u0651\u064e\u0629\u064e \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u0640\u06e7\u0645\u064e \u062d\u064e\u0646\u0650\u064a\u0641\u0657\u0627\u06d6 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0634\u06e1\u0631\u0650\u0643\u0650\u064a\u0646\u064e",translation:"Dan mereka berkata, \"Jadilah kamu (penganut) Yahudi atau Nasrani, niscaya kamu mendapat petunjuk.\" Katakanlah, \"(Tidak!) Tetapi (kami mengikuti) agama Ibrahim yang lurus dan dia termasuk golongan orang yang mempersekutukan Tuhan"},{id:136,text:"\u0642\u064f\u0648\u0644\u064f\u0648\u0653\u0627\u0652 \u0621\u064e\u0627\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u0640\u06e7\u0645\u064e \u0648\u064e\u0625\u0650\u0633\u06e1\u0645\u064e\u0670\u0639\u0650\u064a\u0644\u064e \u0648\u064e\u0625\u0650\u0633\u06e1\u062d\u064e\u0670\u0642\u064e \u0648\u064e\u064a\u064e\u0639\u06e1\u0642\u064f\u0648\u0628\u064e \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0633\u06e1\u0628\u064e\u0627\u0637\u0650 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0648\u062a\u0650\u064a\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u0639\u0650\u064a\u0633\u064e\u0649\u0670 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0648\u062a\u0650\u064a\u064e \u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0644\u064e\u0627 \u0646\u064f\u0641\u064e\u0631\u0651\u0650\u0642\u064f \u0628\u064e\u064a\u06e1\u0646\u064e \u0623\u064e\u062d\u064e\u062f\u0656 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0648\u064e\u0646\u064e\u062d\u06e1\u0646\u064f \u0644\u064e\u0647\u064f\u06e5 \u0645\u064f\u0633\u06e1\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Katakanlah, \"Kami beriman kepada Allah dan kepada apa yang diturunkan kepada kami, dan kepada apa yang diturunkan kepada Ibrahim, Ismail, Ishak, Yakub dan anak cucunya, dan kepada apa yang diberikan kepada Musa dan Isa serta kepada apa yang diberikan kepada nabi-nabi dari Tuhan mereka. Kami tidak membeda-bedakan seorang pun di antara mereka dan kami berserah diri kepada-Nya"},{id:137,text:"\u0641\u064e\u0625\u0650\u0646\u06e1 \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0645\u0650\u062b\u06e1\u0644\u0650 \u0645\u064e\u0627\u0653 \u0621\u064e\u0627\u0645\u064e\u0646\u062a\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6 \u0641\u064e\u0642\u064e\u062f\u0650 \u0671\u0647\u06e1\u062a\u064e\u062f\u064e\u0648\u0627\u0652\u06d6 \u0648\u0651\u064e\u0625\u0650\u0646 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u06e1\u0627\u0652 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0634\u0650\u0642\u064e\u0627\u0642\u0656\u06d6 \u0641\u064e\u0633\u064e\u064a\u064e\u0643\u06e1\u0641\u0650\u064a\u0643\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u0650\u064a\u0639\u064f \u0671\u0644\u06e1\u0639\u064e\u0644\u0650\u064a\u0645\u064f",translation:"Maka jika mereka telah beriman sebagaimana yang kamu imani, sungguh, mereka telah mendapat petunjuk. Tetapi jika mereka berpaling, sesungguhnya mereka berada dalam permusuhan (denganmu), maka Allah mencukupkan engkau (Muhammad) terhadap mereka (dengan pertolongan-Nya). Dan Dia Maha Mendengar, Maha Mengetahui"},{id:138,text:"\u0635\u0650\u0628\u06e1\u063a\u064e\u0629\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u064e\u0646\u06e1 \u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0635\u0650\u0628\u06e1\u063a\u064e\u0629\u0657\u06d6 \u0648\u064e\u0646\u064e\u062d\u06e1\u0646\u064f \u0644\u064e\u0647\u064f\u06e5 \u0639\u064e\u0670\u0628\u0650\u062f\u064f\u0648\u0646\u064e",translation:"(\u1e62ibgah Allah\"46) Siapa yang lebih baik \u1e63ibgah-nya daripada Allah? Dan kepada-Nya kami menyembah"},{id:139,text:"\u0642\u064f\u0644\u06e1 \u0623\u064e\u062a\u064f\u062d\u064e\u0627\u0653\u062c\u0651\u064f\u0648\u0646\u064e\u0646\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0647\u064f\u0648\u064e \u0631\u064e\u0628\u0651\u064f\u0646\u064e\u0627 \u0648\u064e\u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0646\u064e\u0627\u0653 \u0623\u064e\u0639\u06e1\u0645\u064e\u0670\u0644\u064f\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u0639\u06e1\u0645\u064e\u0670\u0644\u064f\u0643\u064f\u0645\u06e1 \u0648\u064e\u0646\u064e\u062d\u06e1\u0646\u064f \u0644\u064e\u0647\u064f\u06e5 \u0645\u064f\u062e\u06e1\u0644\u0650\u0635\u064f\u0648\u0646\u064e",translation:"Katakanlah (Muhammad), \"Apakah kamu hendak berdebat dengan kami tentang Allah, padahal Dia adalah Tuhan kami dan Tuhan kamu. Bagi kami amalan kami, bagi kamu amalan kamu, dan hanya kepada-Nya kami dengan tulus mengabdikan diri"},{id:140,text:"\u0623\u064e\u0645\u06e1 \u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0625\u0650\u0646\u0651\u064e \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u0640\u06e7\u0645\u064e \u0648\u064e\u0625\u0650\u0633\u06e1\u0645\u064e\u0670\u0639\u0650\u064a\u0644\u064e \u0648\u064e\u0625\u0650\u0633\u06e1\u062d\u064e\u0670\u0642\u064e \u0648\u064e\u064a\u064e\u0639\u06e1\u0642\u064f\u0648\u0628\u064e \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0633\u06e1\u0628\u064e\u0627\u0637\u064e \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0647\u064f\u0648\u062f\u064b\u0627 \u0623\u064e\u0648\u06e1 \u0646\u064e\u0635\u064e\u0670\u0631\u064e\u0649\u0670\u06d7 \u0642\u064f\u0644\u06e1 \u0621\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0623\u064e\u0645\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06d7 \u0648\u064e\u0645\u064e\u0646\u06e1 \u0623\u064e\u0638\u06e1\u0644\u064e\u0645\u064f \u0645\u0650\u0645\u0651\u064e\u0646 \u0643\u064e\u062a\u064e\u0645\u064e \u0634\u064e\u0647\u064e\u0670\u062f\u064e\u0629\u064b \u0639\u0650\u0646\u062f\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d7 \u0648\u064e\u0645\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u063a\u064e\u0670\u0641\u0650\u0644\u064d \u0639\u064e\u0645\u0651\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Ataukah kamu (orang-orang Yahudi dan Nasrani) berkata bahwa Ibrahim, Ismail, Ishak, Yakub dan anak cucunya adalah penganut Yahudi atau Nasrani? Katakanlah, \"Kamukah yang lebih tahu atau Allah, dan siapakah yang lebih zalim daripada orang yang menyembunyikan kesaksian dari Allah47) yang ada padanya?\" Allah tidak lengah terhadap apa yang kamu kerjakan"},{id:141,text:"\u062a\u0650\u0644\u06e1\u0643\u064e \u0623\u064f\u0645\u0651\u064e\u0629\u065e \u0642\u064e\u062f\u06e1 \u062e\u064e\u0644\u064e\u062a\u06e1\u06d6 \u0644\u064e\u0647\u064e\u0627 \u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064e\u062a\u06e1 \u0648\u064e\u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u06e1\u062a\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0648\u0646\u064e \u0639\u064e\u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Itulah umat yang telah lalu. Baginya apa yang telah mereka usahakan dan bagimu apa yang telah kamu usahakan. Dan kamu tidak akan diminta (pertanggungjawaban) tentang apa yang dahulu mereka kerjakan"},{id:142,text:"\u06de\u0633\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0671\u0644\u0633\u0651\u064f\u0641\u064e\u0647\u064e\u0627\u0653\u0621\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0645\u064e\u0627 \u0648\u064e\u0644\u0651\u064e\u0649\u0670\u0647\u064f\u0645\u06e1 \u0639\u064e\u0646 \u0642\u0650\u0628\u06e1\u0644\u064e\u062a\u0650\u0647\u0650\u0645\u064f \u0671\u0644\u0651\u064e\u062a\u0650\u064a \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627\u06da \u0642\u064f\u0644 \u0644\u0651\u0650\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u0645\u064e\u0634\u06e1\u0631\u0650\u0642\u064f \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u063a\u06e1\u0631\u0650\u0628\u064f\u06da \u064a\u064e\u0647\u06e1\u062f\u0650\u064a \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0670\u0637\u0656 \u0645\u0651\u064f\u0633\u06e1\u062a\u064e\u0642\u0650\u064a\u0645\u0656",translation:"Orang-orang yang kurang akal di antara manusia akan berkata, \"Apakah yang memalingkan mereka (muslim) dari kiblat yang dahulu mereka (berkiblat) kepadanya?\" Katakanlah (Muhammad), \"Milik Allah-lah timur dan barat; Dia memberi petunjuk kepada siapa yang Dia kehendaki ke jalan yang lurus"},{id:143,text:"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0670\u0643\u064f\u0645\u06e1 \u0623\u064f\u0645\u0651\u064e\u0629\u0657 \u0648\u064e\u0633\u064e\u0637\u0657\u0627 \u0644\u0651\u0650\u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u0634\u064f\u0647\u064e\u062f\u064e\u0627\u0653\u0621\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0634\u064e\u0647\u0650\u064a\u062f\u0657\u0627\u06d7 \u0648\u064e\u0645\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0642\u0650\u0628\u06e1\u0644\u064e\u0629\u064e \u0671\u0644\u0651\u064e\u062a\u0650\u064a \u0643\u064f\u0646\u062a\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0644\u0650\u0646\u064e\u0639\u06e1\u0644\u064e\u0645\u064e \u0645\u064e\u0646 \u064a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e \u0645\u0650\u0645\u0651\u064e\u0646 \u064a\u064e\u0646\u0642\u064e\u0644\u0650\u0628\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0639\u064e\u0642\u0650\u0628\u064e\u064a\u06e1\u0647\u0650\u06da \u0648\u064e\u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064e\u062a\u06e1 \u0644\u064e\u0643\u064e\u0628\u0650\u064a\u0631\u064e\u0629\u064b \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064e\u062f\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06d7 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u064a\u064f\u0636\u0650\u064a\u0639\u064e \u0625\u0650\u064a\u0645\u064e\u0670\u0646\u064e\u0643\u064f\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0631\u064e\u0621\u064f\u0648\u0641\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u065e",translation:"Dan demikian pula Kami telah menjadikan kamu (umat Islam) \"umat pertengahan\"48) agar kamu menjadi saksi atas (perbuatan) manusia dan agar Rasul (Muhammad) menjadi saksi atas (perbuatan) kamu. Kami tidak menjadikan kiblat yang (dahulu) kamu (berkiblat) kepadanya melainkan agar kami mengetahui siapa yang mengikuti Rasul dan siapa yang berbalik ke belakang. Sungguh, (pemindahan kiblat) itu sangat berat, kecuali bagi orang yang telah diberi petunjuk oleh Allah. Dan Allah tidak akan menyia-nyiakan imanmu. Sungguh, Allah Maha Pengasih, Maha Penyayang kepada manusia"},{id:144,text:"\u0642\u064e\u062f\u06e1 \u0646\u064e\u0631\u064e\u0649\u0670 \u062a\u064e\u0642\u064e\u0644\u0651\u064f\u0628\u064e \u0648\u064e\u062c\u06e1\u0647\u0650\u0643\u064e \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650\u06d6 \u0641\u064e\u0644\u064e\u0646\u064f\u0648\u064e\u0644\u0651\u0650\u064a\u064e\u0646\u0651\u064e\u0643\u064e \u0642\u0650\u0628\u06e1\u0644\u064e\u0629\u0657 \u062a\u064e\u0631\u06e1\u0636\u064e\u0649\u0670\u0647\u064e\u0627\u06da \u0641\u064e\u0648\u064e\u0644\u0651\u0650 \u0648\u064e\u062c\u06e1\u0647\u064e\u0643\u064e \u0634\u064e\u0637\u06e1\u0631\u064e \u0671\u0644\u06e1\u0645\u064e\u0633\u06e1\u062c\u0650\u062f\u0650 \u0671\u0644\u06e1\u062d\u064e\u0631\u064e\u0627\u0645\u0650\u06da \u0648\u064e\u062d\u064e\u064a\u06e1\u062b\u064f \u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0641\u064e\u0648\u064e\u0644\u0651\u064f\u0648\u0627\u0652 \u0648\u064f\u062c\u064f\u0648\u0647\u064e\u0643\u064f\u0645\u06e1 \u0634\u064e\u0637\u06e1\u0631\u064e\u0647\u064f\u06e5\u06d7 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0644\u064e\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1\u06d7 \u0648\u064e\u0645\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u063a\u064e\u0670\u0641\u0650\u0644\u064d \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Kami melihat wajahmu (Muhammad) sering menengadah ke langit, maka akan Kami palingkan engkau ke kiblat yang engkau senangi. Maka hadapkanlah wajahmu ke arah Masjidilharam. Dan di mana saja engkau berada, hadapkanlah wajahmu ke arah itu. Dan sesungguhnya orang-orang yang diberi Kitab (Taurat dan Injil) tahu, bahwa (pemindahan kiblat) itu adalah kebenaran dari Tuhan mereka. Dan Allah tidak lengah terhadap apa yang mereka kerjakan"},{id:145,text:"\u0648\u064e\u0644\u064e\u0626\u0650\u0646\u06e1 \u0623\u064e\u062a\u064e\u064a\u06e1\u062a\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0621\u064e\u0627\u064a\u064e\u0629\u0656 \u0645\u0651\u064e\u0627 \u062a\u064e\u0628\u0650\u0639\u064f\u0648\u0627\u0652 \u0642\u0650\u0628\u06e1\u0644\u064e\u062a\u064e\u0643\u064e\u06da \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064e \u0628\u0650\u062a\u064e\u0627\u0628\u0650\u0639\u0656 \u0642\u0650\u0628\u06e1\u0644\u064e\u062a\u064e\u0647\u064f\u0645\u06e1\u06da \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u0639\u06e1\u0636\u064f\u0647\u064f\u0645 \u0628\u0650\u062a\u064e\u0627\u0628\u0650\u0639\u0656 \u0642\u0650\u0628\u06e1\u0644\u064e\u0629\u064e \u0628\u064e\u0639\u06e1\u0636\u0656\u06da \u0648\u064e\u0644\u064e\u0626\u0650\u0646\u0650 \u0671\u062a\u0651\u064e\u0628\u064e\u0639\u06e1\u062a\u064e \u0623\u064e\u0647\u06e1\u0648\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0645\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0639\u0650\u0644\u06e1\u0645\u0650 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0625\u0650\u0630\u0657\u0627 \u0644\u0651\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dan walaupun engkau (Muhammad) memberikan semua ayat (keterangan) kepada orang-orang yang diberi kitab itu, mereka tidak akan mengikuti kiblatmu, dan engkau pun tidak akan mengikuti kiblat mereka. Sebagian mereka tidak akan mengikuti kiblat sebagian yang lain. Dan jika engkau mengikuti keinginan mereka setelah sampai ilmu kepadamu, niscaya engkau termasuk orang-orang zalim"},{id:146,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u064a\u064e\u0639\u06e1\u0631\u0650\u0641\u064f\u0648\u0646\u064e\u0647\u064f\u06e5 \u0643\u064e\u0645\u064e\u0627 \u064a\u064e\u0639\u06e1\u0631\u0650\u0641\u064f\u0648\u0646\u064e \u0623\u064e\u0628\u06e1\u0646\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0641\u064e\u0631\u0650\u064a\u0642\u0657\u0627 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0644\u064e\u064a\u064e\u0643\u06e1\u062a\u064f\u0645\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064e \u0648\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Orang-orang yang telah Kami beri Kitab (Taurat dan Injil) mengenalnya (Muhammad)49) seperti mereka mengenal anak-anak mereka sendiri. Sesungguhnya sebagian mereka pasti menyembunyikan kebenaran, padahal mereka mengetahui(nya)"},{id:147,text:"\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064e \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0645\u06e1\u062a\u064e\u0631\u0650\u064a\u0646\u064e",translation:"Kebenaran itu dari Tuhanmu, maka janganlah sekali-kali engkau (Muhammad) termasuk orang-orang yang ragu"},{id:148,text:"\u0648\u064e\u0644\u0650\u0643\u064f\u0644\u0651\u0656 \u0648\u0650\u062c\u06e1\u0647\u064e\u0629\u064c \u0647\u064f\u0648\u064e \u0645\u064f\u0648\u064e\u0644\u0651\u0650\u064a\u0647\u064e\u0627\u06d6 \u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u0628\u0650\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u062e\u064e\u064a\u06e1\u0631\u064e\u0670\u062a\u0650\u06da \u0623\u064e\u064a\u06e1\u0646\u064e \u0645\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0623\u06e1\u062a\u0650 \u0628\u0650\u0643\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0642\u064e\u062f\u0650\u064a\u0631\u065e",translation:"Dan setiap umat mempunyai kiblat yang dia menghadap kepadanya. Maka berlomba-lombalah kamu dalam kebaikan. Di mana saja kamu berada pasti Allah akan mengumpulkan kamu semuanya. Sungguh, Allah Mahakuasa atas segala sesuatu"},{id:149,text:"\u0648\u064e\u0645\u0650\u0646\u06e1 \u062d\u064e\u064a\u06e1\u062b\u064f \u062e\u064e\u0631\u064e\u062c\u06e1\u062a\u064e \u0641\u064e\u0648\u064e\u0644\u0651\u0650 \u0648\u064e\u062c\u06e1\u0647\u064e\u0643\u064e \u0634\u064e\u0637\u06e1\u0631\u064e \u0671\u0644\u06e1\u0645\u064e\u0633\u06e1\u062c\u0650\u062f\u0650 \u0671\u0644\u06e1\u062d\u064e\u0631\u064e\u0627\u0645\u0650\u06d6 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0644\u06e1\u062d\u064e\u0642\u0651\u064f \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064e\u06d7 \u0648\u064e\u0645\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u063a\u064e\u0670\u0641\u0650\u0644\u064d \u0639\u064e\u0645\u0651\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan dari mana pun engkau (Muhammad) keluar, hadapkanlah wajahmu ke arah Masjidilharam, sesungguhnya itu benar-benar ketentuan dari Tuhanmu. Allah tidak lengah terhadap apa yang kamu kerjakan"},{id:150,text:"\u0648\u064e\u0645\u0650\u0646\u06e1 \u062d\u064e\u064a\u06e1\u062b\u064f \u062e\u064e\u0631\u064e\u062c\u06e1\u062a\u064e \u0641\u064e\u0648\u064e\u0644\u0651\u0650 \u0648\u064e\u062c\u06e1\u0647\u064e\u0643\u064e \u0634\u064e\u0637\u06e1\u0631\u064e \u0671\u0644\u06e1\u0645\u064e\u0633\u06e1\u062c\u0650\u062f\u0650 \u0671\u0644\u06e1\u062d\u064e\u0631\u064e\u0627\u0645\u0650\u06da \u0648\u064e\u062d\u064e\u064a\u06e1\u062b\u064f \u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0641\u064e\u0648\u064e\u0644\u0651\u064f\u0648\u0627\u0652 \u0648\u064f\u062c\u064f\u0648\u0647\u064e\u0643\u064f\u0645\u06e1 \u0634\u064e\u0637\u06e1\u0631\u064e\u0647\u064f\u06e5 \u0644\u0650\u0626\u064e\u0644\u0651\u064e\u0627 \u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u062d\u064f\u062c\u0651\u064e\u0629\u064c \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062e\u06e1\u0634\u064e\u0648\u06e1\u0647\u064f\u0645\u06e1 \u0648\u064e\u0671\u062e\u06e1\u0634\u064e\u0648\u06e1\u0646\u0650\u064a \u0648\u064e\u0644\u0650\u0623\u064f\u062a\u0650\u0645\u0651\u064e \u0646\u0650\u0639\u06e1\u0645\u064e\u062a\u0650\u064a \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u0647\u06e1\u062a\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Dan dari mana pun engkau (Muhammad) keluar, maka hadapkanlah wajahmu ke arah Masjidilharam. Dan di mana saja kamu berada, maka hadapkanlah wajahmu ke arah itu, agar tidak ada alasan bagi manusia (untuk menentangmu), kecuali orang-orang yang zalim di antara mereka. Janganlah kamu takut kepada mereka, tetapi takutlah kepada-Ku, agar Aku sempurnakan nikmat-Ku kepadamu, dan agar kamu mendapat petunjuk"},{id:151,text:"\u0643\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a\u0643\u064f\u0645\u06e1 \u0631\u064e\u0633\u064f\u0648\u0644\u0657\u0627 \u0645\u0651\u0650\u0646\u0643\u064f\u0645\u06e1 \u064a\u064e\u062a\u06e1\u0644\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0648\u064e\u064a\u064f\u0632\u064e\u0643\u0651\u0650\u064a\u0643\u064f\u0645\u06e1 \u0648\u064e\u064a\u064f\u0639\u064e\u0644\u0651\u0650\u0645\u064f\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0648\u064e\u0671\u0644\u06e1\u062d\u0650\u0643\u06e1\u0645\u064e\u0629\u064e \u0648\u064e\u064a\u064f\u0639\u064e\u0644\u0651\u0650\u0645\u064f\u0643\u064f\u0645 \u0645\u0651\u064e\u0627 \u0644\u064e\u0645\u06e1 \u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Sebagaimana Kami telah mengutus kepadamu seorang Rasul (Muhammad) dari (kalangan) kamu yang membacakan ayat-ayat Kami, menyucikan kamu dan mengajarkan kepadamu Kitab (Alquran) dan Hikmah (Sunah), serta mengajarkan apa yang belum kamu ketahui"},{id:152,text:"\u0641\u064e\u0671\u0630\u06e1\u0643\u064f\u0631\u064f\u0648\u0646\u0650\u064a\u0653 \u0623\u064e\u0630\u06e1\u0643\u064f\u0631\u06e1\u0643\u064f\u0645\u06e1 \u0648\u064e\u0671\u0634\u06e1\u0643\u064f\u0631\u064f\u0648\u0627\u0652 \u0644\u0650\u064a \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u06e1\u0641\u064f\u0631\u064f\u0648\u0646\u0650",translation:"(Maka ingatlah kepada-Ku, Aku pun akan ingat kepadamu.50) Bersyukurlah kepada-Ku, dan janganlah kamu ingkar kepada-Ku"},{id:153,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0671\u0633\u06e1\u062a\u064e\u0639\u0650\u064a\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u0635\u0651\u064e\u0628\u06e1\u0631\u0650 \u0648\u064e\u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u0650\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064e\u0639\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0628\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Wahai orang-orang yang beriman! Mohonlah pertolongan (kepada Allah) dengan sabar dan salat. Sungguh, Allah beserta orang-orang yang sabar"},{id:154,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627\u0652 \u0644\u0650\u0645\u064e\u0646 \u064a\u064f\u0642\u06e1\u062a\u064e\u0644\u064f \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u062a\u064f\u06e2\u06da \u0628\u064e\u0644\u06e1 \u0623\u064e\u062d\u06e1\u064a\u064e\u0627\u0653\u0621\u065e \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u0644\u0651\u064e\u0627 \u062a\u064e\u0634\u06e1\u0639\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Dan janganlah kamu mengatakan orang-orang yang terbunuh di jalan Allah (mereka) telah mati. Sebenarnya (mereka) hidup, 51) tetapi kamu tidak menyadarinya"},{id:155,text:"\u0648\u064e\u0644\u064e\u0646\u064e\u0628\u06e1\u0644\u064f\u0648\u064e\u0646\u0651\u064e\u0643\u064f\u0645 \u0628\u0650\u0634\u064e\u064a\u06e1\u0621\u0656 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u062e\u064e\u0648\u06e1\u0641\u0650 \u0648\u064e\u0671\u0644\u06e1\u062c\u064f\u0648\u0639\u0650 \u0648\u064e\u0646\u064e\u0642\u06e1\u0635\u0656 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0646\u0641\u064f\u0633\u0650 \u0648\u064e\u0671\u0644\u062b\u0651\u064e\u0645\u064e\u0631\u064e\u0670\u062a\u0650\u06d7 \u0648\u064e\u0628\u064e\u0634\u0651\u0650\u0631\u0650 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0628\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan Kami pasti akan menguji kamu dengan sedikit ketakutan, kelaparan, kekurangan harta, jiwa, dan buah-buahan. Dan sampaikanlah kabar gembira kepada orang-orang yang sabar"},{id:156,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0625\u0650\u0630\u064e\u0627\u0653 \u0623\u064e\u0635\u064e\u0670\u0628\u064e\u062a\u06e1\u0647\u064f\u0645 \u0645\u0651\u064f\u0635\u0650\u064a\u0628\u064e\u0629\u065e \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0631\u064e\u0670\u062c\u0650\u0639\u064f\u0648\u0646\u064e",translation:"(yaitu) orang-orang yang apabila ditimpa musibah, mereka berkata \"Inn\u0101 lill\u0101hi wa inn\u0101 ilaihi r\u0101ji'\u016bn\" 52) (sesungguhnya kami milik Allah dan kepada-Nyalah kami kembali)"},{id:157,text:"\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0635\u064e\u0644\u064e\u0648\u064e\u0670\u062a\u065e \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u065e\u06d6 \u0648\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064f\u0647\u06e1\u062a\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Mereka itulah yang memperoleh ampunan dan rahmat dari Tuhannya, dan mereka itulah orang-orang yang mendapat petunjuk"},{id:158,text:"\u06de\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0635\u0651\u064e\u0641\u064e\u0627 \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u0631\u06e1\u0648\u064e\u0629\u064e \u0645\u0650\u0646 \u0634\u064e\u0639\u064e\u0627\u0653\u0626\u0650\u0631\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0641\u064e\u0645\u064e\u0646\u06e1 \u062d\u064e\u062c\u0651\u064e \u0671\u0644\u06e1\u0628\u064e\u064a\u06e1\u062a\u064e \u0623\u064e\u0648\u0650 \u0671\u0639\u06e1\u062a\u064e\u0645\u064e\u0631\u064e \u0641\u064e\u0644\u064e\u0627 \u062c\u064f\u0646\u064e\u0627\u062d\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0623\u064e\u0646 \u064a\u064e\u0637\u0651\u064e\u0648\u0651\u064e\u0641\u064e \u0628\u0650\u0647\u0650\u0645\u064e\u0627\u06da \u0648\u064e\u0645\u064e\u0646 \u062a\u064e\u0637\u064e\u0648\u0651\u064e\u0639\u064e \u062e\u064e\u064a\u06e1\u0631\u0657\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0634\u064e\u0627\u0643\u0650\u0631\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u064c",translation:"Sesungguhnya Safa dan Marwah merupakan sebagian syiar (agama) Allah.53) Maka barang siapa beribadah haji ke Baitullah atau berumrah, tidak ada dosa baginya mengerjakan sai54) antara keduanya. Dan barang siapa dengan kerelaan hati mengerjakan kebajikan, maka Allah Maha Mensyukuri, 55) Maha Mengetahui"},{id:159,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0643\u06e1\u062a\u064f\u0645\u064f\u0648\u0646\u064e \u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0647\u064f\u062f\u064e\u0649\u0670 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0645\u064e\u0627 \u0628\u064e\u064a\u0651\u064e\u0646\u0651\u064e\u0640\u0670\u0647\u064f \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0641\u0650\u064a \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u064a\u064e\u0644\u06e1\u0639\u064e\u0646\u064f\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u064a\u064e\u0644\u06e1\u0639\u064e\u0646\u064f\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0640\u0670\u0639\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Sungguh, orang-orang yang menyembunyikan apa yang telah Kami turunkan berupa keterangan-keterangan dan petunjuk, setelah Kami jelaskan kepada manusia dalam Kitab (Alquran), mereka itulah yang dilaknat Allah dan dilaknat (pula) oleh orang-orang yang melaknat"},{id:160,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u0627\u0628\u064f\u0648\u0627\u0652 \u0648\u064e\u0623\u064e\u0635\u06e1\u0644\u064e\u062d\u064f\u0648\u0627\u0652 \u0648\u064e\u0628\u064e\u064a\u0651\u064e\u0646\u064f\u0648\u0627\u0652 \u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0623\u064e\u062a\u064f\u0648\u0628\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0648\u064e\u0623\u064e\u0646\u064e\u0627 \u0671\u0644\u062a\u0651\u064e\u0648\u0651\u064e\u0627\u0628\u064f \u0671\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",translation:"kecuali mereka yang telah bertobat, mengadakan perbaikan dan menjelaskan(nya),56) mereka itulah yang Aku terima tobatnya dan Akulah Yang Maha Penerima tobat, Maha Penyayang"},{id:161,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u0645\u064e\u0627\u062a\u064f\u0648\u0627\u0652 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0643\u064f\u0641\u0651\u064e\u0627\u0631\u064c \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0644\u064e\u0639\u06e1\u0646\u064e\u0629\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u0650 \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0623\u064e\u062c\u06e1\u0645\u064e\u0639\u0650\u064a\u0646\u064e",translation:"Sungguh, orang-orang yang kafir dan mati dalam keadaan kafir, mereka itu mendapat laknat Allah, para malaikat dan manusia seluruhnya"},{id:162,text:"\u062e\u064e\u0670\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0644\u064e\u0627 \u064a\u064f\u062e\u064e\u0641\u0651\u064e\u0641\u064f \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u06e1 \u064a\u064f\u0646\u0638\u064e\u0631\u064f\u0648\u0646\u064e",translation:"mereka kekal di dalamnya (laknat), tidak akan diringankan azabnya, dan mereka tidak diberi penangguhan"},{id:163,text:"\u0648\u064e\u0625\u0650\u0644\u064e\u0670\u0647\u064f\u0643\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0670\u0647\u065e \u0648\u064e\u0670\u062d\u0650\u062f\u065e\u06d6 \u0644\u0651\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u064f \u0671\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",translation:"Dan Tuhan kamu adalah Tuhan Yang Maha Esa, tidak ada tuhan selain Dia, Yang Maha Pengasih, Maha Penyayang"},{id:164,text:"\u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u062e\u064e\u0644\u06e1\u0642\u0650 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0671\u062e\u06e1\u062a\u0650\u0644\u064e\u0670\u0641\u0650 \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u0650 \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u0648\u064e\u0671\u0644\u06e1\u0641\u064f\u0644\u06e1\u0643\u0650 \u0671\u0644\u0651\u064e\u062a\u0650\u064a \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0641\u0650\u064a \u0671\u0644\u06e1\u0628\u064e\u062d\u06e1\u0631\u0650 \u0628\u0650\u0645\u064e\u0627 \u064a\u064e\u0646\u0641\u064e\u0639\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0645\u0650\u0646 \u0645\u0651\u064e\u0627\u0653\u0621\u0656 \u0641\u064e\u0623\u064e\u062d\u06e1\u064a\u064e\u0627 \u0628\u0650\u0647\u0650 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0628\u064e\u0639\u06e1\u062f\u064e \u0645\u064e\u0648\u06e1\u062a\u0650\u0647\u064e\u0627 \u0648\u064e\u0628\u064e\u062b\u0651\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u062f\u064e\u0627\u0653\u0628\u0651\u064e\u0629\u0656 \u0648\u064e\u062a\u064e\u0635\u06e1\u0631\u0650\u064a\u0641\u0650 \u0671\u0644\u0631\u0651\u0650\u064a\u064e\u0670\u062d\u0650 \u0648\u064e\u0671\u0644\u0633\u0651\u064e\u062d\u064e\u0627\u0628\u0650 \u0671\u0644\u06e1\u0645\u064f\u0633\u064e\u062e\u0651\u064e\u0631\u0650 \u0628\u064e\u064a\u06e1\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0644\u064e\u0623\u0653\u064a\u064e\u0670\u062a\u0656 \u0644\u0651\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Sesungguhnya pada penciptaan langit dan bumi, pergantian malam dan siang, kapal yang berlayar di laut dengan (muatan) yang bermanfaat bagi manusia, apa yang diturunkan Allah dari langit berupa air, lalu dengan itu dihidupkan-Nya bumi setelah mati (kering), dan Dia tebarkan di dalamnya bermacam-macam binatang, dan perkisaran angin dan awan yang dikendalikan antara langit dan bumi, (semua itu) sungguh, merupakan tanda-tanda (kebesaran Allah) bagi orang-orang yang mengerti"},{id:165,text:"\u0648\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0645\u064e\u0646 \u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0646\u062f\u064e\u0627\u062f\u0657\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f\u0648\u0646\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u062d\u064f\u0628\u0651\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0634\u064e\u062f\u0651\u064f \u062d\u064f\u0628\u0651\u0657\u0627 \u0644\u0651\u0650\u0644\u0651\u064e\u0647\u0650\u06d7 \u0648\u064e\u0644\u064e\u0648\u06e1 \u064a\u064e\u0631\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0630\u06e1 \u064a\u064e\u0631\u064e\u0648\u06e1\u0646\u064e \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u06e1\u0642\u064f\u0648\u0651\u064e\u0629\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u062c\u064e\u0645\u0650\u064a\u0639\u0657\u0627 \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0634\u064e\u062f\u0650\u064a\u062f\u064f \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u0650",translation:"(Dan di antara manusia ada orang yang menyembah tuhan selain Allah sebagai tandingan, yang mereka cintai seperti mencintai Allah. Adapun orang-orang yang beriman sangat besar cintanya kepada Allah. Sekiranya orang-orang yang berbuat zalim itu57) melihat, ketika mereka melihat azab (pada hari Kiamat), bahwa kekuatan itu semuanya milik Allah dan bahwa Allah sangat berat azab-Nya (niscaya mereka menyesal)"},{id:166,text:"\u0625\u0650\u0630\u06e1 \u062a\u064e\u0628\u064e\u0631\u0651\u064e\u0623\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u062a\u0651\u064f\u0628\u0650\u0639\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0627\u0652 \u0648\u064e\u0631\u064e\u0623\u064e\u0648\u064f\u0627\u0652 \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0648\u064e\u062a\u064e\u0642\u064e\u0637\u0651\u064e\u0639\u064e\u062a\u06e1 \u0628\u0650\u0647\u0650\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u0633\u06e1\u0628\u064e\u0627\u0628\u064f",translation:"(Yaitu) ketika orang-orang yang diikuti berlepas tangan dari orang-orang yang mengikuti, dan mereka melihat azab, dan (ketika) segala hubungan antara mereka terputus"},{id:167,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0627\u0652 \u0644\u064e\u0648\u06e1 \u0623\u064e\u0646\u0651\u064e \u0644\u064e\u0646\u064e\u0627 \u0643\u064e\u0631\u0651\u064e\u0629\u0657 \u0641\u064e\u0646\u064e\u062a\u064e\u0628\u064e\u0631\u0651\u064e\u0623\u064e \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0643\u064e\u0645\u064e\u0627 \u062a\u064e\u0628\u064e\u0631\u0651\u064e\u0621\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u0651\u064e\u0627\u06d7 \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064f\u0631\u0650\u064a\u0647\u0650\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0639\u06e1\u0645\u064e\u0670\u0644\u064e\u0647\u064f\u0645\u06e1 \u062d\u064e\u0633\u064e\u0631\u064e\u0670\u062a\u064d \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1\u06d6 \u0648\u064e\u0645\u064e\u0627 \u0647\u064f\u0645 \u0628\u0650\u062e\u064e\u0670\u0631\u0650\u062c\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650",translation:"Dan orang-orang yang mengikuti berkata, \"Sekiranya kami mendapat kesempatan (kembali ke dunia), tentu kami akan berlepas tangan dari mereka, sebagaimana mereka berlepas tangan dari kami.\" Demikianlah Allah memperlihatkan kepada mereka perbuatan mereka yang menjadi penyesalan mereka. Dan mereka tidak akan ke luar dari api neraka"},{id:168,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0643\u064f\u0644\u064f\u0648\u0627\u0652 \u0645\u0650\u0645\u0651\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u062d\u064e\u0644\u064e\u0670\u0644\u0657\u0627 \u0637\u064e\u064a\u0651\u0650\u0628\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0627\u0652 \u062e\u064f\u0637\u064f\u0648\u064e\u0670\u062a\u0650 \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u0650\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0639\u064e\u062f\u064f\u0648\u0651\u065e \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u064c",translation:"Wahai manusia! Makanlah dari (makanan) yang halal dan baik yang terdapat di bumi, dan janganlah kamu mengikuti langkah-langkah setan. Sungguh, setan itu musuh yang nyata bagimu"},{id:169,text:"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0623\u06e1\u0645\u064f\u0631\u064f\u0643\u064f\u0645 \u0628\u0650\u0671\u0644\u0633\u0651\u064f\u0648\u0653\u0621\u0650 \u0648\u064e\u0671\u0644\u06e1\u0641\u064e\u062d\u06e1\u0634\u064e\u0627\u0653\u0621\u0650 \u0648\u064e\u0623\u064e\u0646 \u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Sesungguhnya (setan) itu hanya menyuruh kamu agar berbuat jahat dan keji, dan mengatakan apa yang tidak kamu ketahui tentang Allah"},{id:170,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0671\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0627\u0652 \u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0628\u064e\u0644\u06e1 \u0646\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f \u0645\u064e\u0627\u0653 \u0623\u064e\u0644\u06e1\u0641\u064e\u064a\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0621\u064e\u0646\u064e\u0627\u0653\u06da \u0623\u064e\u0648\u064e\u0644\u064e\u0648\u06e1 \u0643\u064e\u0627\u0646\u064e \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0624\u064f\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0647\u06e1\u062a\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Dan apabila dikatakan kepada mereka, \"Ikutilah apa yang telah diturunkan Allah,\" mereka menjawab, \"(Tidak!) Kami mengikuti apa yang kami dapati pada nenek moyang kami (melakukannya).\" Padahal, nenek moyang mereka itu tidak mengetahui apa pun, dan tidak mendapat petunjuk"},{id:171,text:"\u0648\u064e\u0645\u064e\u062b\u064e\u0644\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0643\u064e\u0645\u064e\u062b\u064e\u0644\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064e\u0646\u06e1\u0639\u0650\u0642\u064f \u0628\u0650\u0645\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u0645\u064e\u0639\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u062f\u064f\u0639\u064e\u0627\u0653\u0621\u0657 \u0648\u064e\u0646\u0650\u062f\u064e\u0627\u0653\u0621\u0657\u06da \u0635\u064f\u0645\u0651\u064f\u06e2 \u0628\u064f\u0643\u06e1\u0645\u064c \u0639\u064f\u0645\u06e1\u064a\u065e \u0641\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Dan perumpamaan bagi (penyeru) orang yang kafir adalah seperti (penggembala) yang meneriaki (binatang) yang tidak mendengar selain panggilan dan teriakan. (Mereka) tuli, bisu dan buta, maka mereka tidak mengerti"},{id:172,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0643\u064f\u0644\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0637\u064e\u064a\u0651\u0650\u0628\u064e\u0670\u062a\u0650 \u0645\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u06e1\u0646\u064e\u0670\u0643\u064f\u0645\u06e1 \u0648\u064e\u0671\u0634\u06e1\u0643\u064f\u0631\u064f\u0648\u0627\u0652 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0625\u0650\u064a\u0651\u064e\u0627\u0647\u064f \u062a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0646\u064e",translation:"Wahai orang-orang yang beriman! Makanlah dari rezeki yang baik yang Kami berikan kepada kamu dan bersyukurlah kepada Allah, jika kamu hanya menyembah kepada-Nya"},{id:173,text:"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u062d\u064e\u0631\u0651\u064e\u0645\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064e\u064a\u06e1\u062a\u064e\u0629\u064e \u0648\u064e\u0671\u0644\u062f\u0651\u064e\u0645\u064e \u0648\u064e\u0644\u064e\u062d\u06e1\u0645\u064e \u0671\u0644\u06e1\u062e\u0650\u0646\u0632\u0650\u064a\u0631\u0650 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0647\u0650\u0644\u0651\u064e \u0628\u0650\u0647\u0650\u06e6 \u0644\u0650\u063a\u064e\u064a\u06e1\u0631\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0641\u064e\u0645\u064e\u0646\u0650 \u0671\u0636\u06e1\u0637\u064f\u0631\u0651\u064e \u063a\u064e\u064a\u06e1\u0631\u064e \u0628\u064e\u0627\u063a\u0656 \u0648\u064e\u0644\u064e\u0627 \u0639\u064e\u0627\u062f\u0656 \u0641\u064e\u0644\u064e\u0627\u0653 \u0625\u0650\u062b\u06e1\u0645\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064c",translation:"Sesungguhnya Dia hanya mengharamkan atasmu bangkai, darah, daging babi, dan (daging) hewan yang disembelih dengan (menyebut nama) selain Allah. Tetapi barang siapa terpaksa (memakannya), bukan karena menginginkannya dan tidak (pula) melampaui batas, maka tidak ada dosa baginya. Sungguh, Allah Maha Pengampun, Maha Penyayang"},{id:174,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0643\u06e1\u062a\u064f\u0645\u064f\u0648\u0646\u064e \u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0648\u064e\u064a\u064e\u0634\u06e1\u062a\u064e\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u0650\u06e6 \u062b\u064e\u0645\u064e\u0646\u0657\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0645\u064e\u0627 \u064a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0628\u064f\u0637\u064f\u0648\u0646\u0650\u0647\u0650\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u064e \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0643\u064e\u0644\u0651\u0650\u0645\u064f\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0632\u064e\u0643\u0651\u0650\u064a\u0647\u0650\u0645\u06e1 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064c",translation:"(Sungguh, orang-orang yang menyembunyikan apa yang telah diturunkan Allah, yaitu Kitab, dan menjualnya dengan harga murah, mereka hanya menelan api neraka ke dalam perutnya,58) dan Allah tidak akan menyapa mereka pada hari Kiamat dan tidak akan menyucikan mereka. Mereka akan mendapat azab yang sangat pedih"},{id:175,text:"\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u0634\u06e1\u062a\u064e\u0631\u064e\u0648\u064f\u0627\u0652 \u0671\u0644\u0636\u0651\u064e\u0644\u064e\u0670\u0644\u064e\u0629\u064e \u0628\u0650\u0671\u0644\u06e1\u0647\u064f\u062f\u064e\u0649\u0670 \u0648\u064e\u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0628\u0650\u0671\u0644\u06e1\u0645\u064e\u063a\u06e1\u0641\u0650\u0631\u064e\u0629\u0650\u06da \u0641\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0635\u06e1\u0628\u064e\u0631\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650",translation:"Mereka itulah yang membeli kesesatan dengan petunjuk dan azab dengan ampunan. Maka alangkah beraninya mereka menentang api neraka"},{id:176,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0646\u064e\u0632\u0651\u064e\u0644\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650\u06d7 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u062e\u06e1\u062a\u064e\u0644\u064e\u0641\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0644\u064e\u0641\u0650\u064a \u0634\u0650\u0642\u064e\u0627\u0642\u0650\u06ed \u0628\u064e\u0639\u0650\u064a\u062f\u0656",translation:"Yang demikian itu karena Allah telah menurunkan Kitab (Alquran) dengan (membawa) kebenaran, dan sesungguhnya orang-orang yang berselisih paham tentang (kebenaran) Kitab itu, mereka dalam perpecahan yang parah"},{id:177,text:"\u06de\u0644\u0651\u064e\u064a\u06e1\u0633\u064e \u0671\u0644\u06e1\u0628\u0650\u0631\u0651\u064e \u0623\u064e\u0646 \u062a\u064f\u0648\u064e\u0644\u0651\u064f\u0648\u0627\u0652 \u0648\u064f\u062c\u064f\u0648\u0647\u064e\u0643\u064f\u0645\u06e1 \u0642\u0650\u0628\u064e\u0644\u064e \u0671\u0644\u06e1\u0645\u064e\u0634\u06e1\u0631\u0650\u0642\u0650 \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u063a\u06e1\u0631\u0650\u0628\u0650 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0628\u0650\u0631\u0651\u064e \u0645\u064e\u0646\u06e1 \u0621\u064e\u0627\u0645\u064e\u0646\u064e \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u0650 \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u0650 \u0648\u064e\u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650\u0640\u06e7\u0646\u064e \u0648\u064e\u0621\u064e\u0627\u062a\u064e\u0649 \u0671\u0644\u06e1\u0645\u064e\u0627\u0644\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u062d\u064f\u0628\u0651\u0650\u0647\u0650\u06e6 \u0630\u064e\u0648\u0650\u064a \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0628\u064e\u0649\u0670 \u0648\u064e\u0671\u0644\u06e1\u064a\u064e\u062a\u064e\u0670\u0645\u064e\u0649\u0670 \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u0633\u064e\u0670\u0643\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0628\u06e1\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u0650 \u0648\u064e\u0671\u0644\u0633\u0651\u064e\u0627\u0653\u0626\u0650\u0644\u0650\u064a\u0646\u064e \u0648\u064e\u0641\u0650\u064a \u0671\u0644\u0631\u0651\u0650\u0642\u064e\u0627\u0628\u0650 \u0648\u064e\u0623\u064e\u0642\u064e\u0627\u0645\u064e \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u0621\u064e\u0627\u062a\u064e\u0649 \u0671\u0644\u0632\u0651\u064e\u0643\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0648\u0641\u064f\u0648\u0646\u064e \u0628\u0650\u0639\u064e\u0647\u06e1\u062f\u0650\u0647\u0650\u0645\u06e1 \u0625\u0650\u0630\u064e\u0627 \u0639\u064e\u0670\u0647\u064e\u062f\u064f\u0648\u0627\u0652\u06d6 \u0648\u064e\u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0628\u0650\u0631\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0628\u064e\u0623\u06e1\u0633\u064e\u0627\u0653\u0621\u0650 \u0648\u064e\u0671\u0644\u0636\u0651\u064e\u0631\u0651\u064e\u0627\u0653\u0621\u0650 \u0648\u064e\u062d\u0650\u064a\u0646\u064e \u0671\u0644\u06e1\u0628\u064e\u0623\u06e1\u0633\u0650\u06d7 \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0635\u064e\u062f\u064e\u0642\u064f\u0648\u0627\u0652\u06d6 \u0648\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",translation:"Kebajikan itu bukanlah mengahadapkan wajahmu ke arah timur dan ke barat, tetapi kebajikan itu ialah (kebajikan) orang yang beriman kepada Allah, hari akhir, malaikat-malaikat, kitab-kitab, dan nabi-nabi dan memberikan harta yang dicintainya kepada kerabat, anak yatim, orang-orang miskin, orang-orang yang dalam perjalanan (musafir), peminta-minta, dan untuk memerdekakan hamba sahaya, yang melaksanakan salat dan menunaikan zakat, orang-orang yang menepati janji apabila berjanji, dan orang yang sabar dalam kemelaratan, penderitaan dan pada masa peperangan. Mereka itulah orang-orang yang benar, dan mereka itulah orang-orang yang bertakwa"},{id:178,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0643\u064f\u062a\u0650\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0642\u0650\u0635\u064e\u0627\u0635\u064f \u0641\u0650\u064a \u0671\u0644\u06e1\u0642\u064e\u062a\u06e1\u0644\u064e\u0649\u06d6 \u0671\u0644\u06e1\u062d\u064f\u0631\u0651\u064f \u0628\u0650\u0671\u0644\u06e1\u062d\u064f\u0631\u0651\u0650 \u0648\u064e\u0671\u0644\u06e1\u0639\u064e\u0628\u06e1\u062f\u064f \u0628\u0650\u0671\u0644\u06e1\u0639\u064e\u0628\u06e1\u062f\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064f\u0646\u062b\u064e\u0649\u0670 \u0628\u0650\u0671\u0644\u06e1\u0623\u064f\u0646\u062b\u064e\u0649\u0670\u06da \u0641\u064e\u0645\u064e\u0646\u06e1 \u0639\u064f\u0641\u0650\u064a\u064e \u0644\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646\u06e1 \u0623\u064e\u062e\u0650\u064a\u0647\u0650 \u0634\u064e\u064a\u06e1\u0621\u065e \u0641\u064e\u0671\u062a\u0651\u0650\u0628\u064e\u0627\u0639\u064f\u06e2 \u0628\u0650\u0671\u0644\u06e1\u0645\u064e\u0639\u06e1\u0631\u064f\u0648\u0641\u0650 \u0648\u064e\u0623\u064e\u062f\u064e\u0627\u0653\u0621\u064c \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0628\u0650\u0625\u0650\u062d\u06e1\u0633\u064e\u0670\u0646\u0656\u06d7 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062a\u064e\u062e\u06e1\u0641\u0650\u064a\u0641\u065e \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u065e\u06d7 \u0641\u064e\u0645\u064e\u0646\u0650 \u0671\u0639\u06e1\u062a\u064e\u062f\u064e\u0649\u0670 \u0628\u064e\u0639\u06e1\u062f\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u0644\u064e\u0647\u064f\u06e5 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Wahai orang-orang yang beriman! Diwajibkan atas kamu (melaksanakan) kisas59) berkenaan dengan orang yang dibunuh. Orang merdeka dengan orang merdeka, hamba sahaya dengan hamba sahaya, perempuan dengan perempuan. Tetapi barang siapa memperoleh maaf dari saudaranya, hendaklah dia mengikutinya dengan baik, dan membayar diat (tebusan) kepadanya dengan baik (pula). Yang demikian itu adalah keringanan dan rahmat dari Tuhanmu. Barang siapa melampaui batas setelah itu, maka ia akan mendapat azab yang sangat pedih"},{id:179,text:"\u0648\u064e\u0644\u064e\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0642\u0650\u0635\u064e\u0627\u0635\u0650 \u062d\u064e\u064a\u064e\u0648\u0670\u0629\u065e \u064a\u064e\u0640\u0670\u0653\u0623\u064f\u0648\u0652\u0644\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0644\u06e1\u0628\u064e\u0670\u0628\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",translation:"Dan dalam kisas itu ada (jaminan) kehidupan bagimu, wahai orang-orang yang berakal, agar kamu bertakwa"},{id:180,text:"\u0643\u064f\u062a\u0650\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0625\u0650\u0630\u064e\u0627 \u062d\u064e\u0636\u064e\u0631\u064e \u0623\u064e\u062d\u064e\u062f\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u064f \u0625\u0650\u0646 \u062a\u064e\u0631\u064e\u0643\u064e \u062e\u064e\u064a\u06e1\u0631\u064b\u0627 \u0671\u0644\u06e1\u0648\u064e\u0635\u0650\u064a\u0651\u064e\u0629\u064f \u0644\u0650\u0644\u06e1\u0648\u064e\u0670\u0644\u0650\u062f\u064e\u064a\u06e1\u0646\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0642\u06e1\u0631\u064e\u0628\u0650\u064a\u0646\u064e \u0628\u0650\u0671\u0644\u06e1\u0645\u064e\u0639\u06e1\u0631\u064f\u0648\u0641\u0650\u06d6 \u062d\u064e\u0642\u0651\u064b\u0627 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",translation:"(Diwajibkan atas kamu, apabila maut hendak menjemput seseorang diantara kamu, jika dia meninggalkan harta, berwasiat untuk kedua orang tua dan karib kerabat dengan cara yang baik,60) (sebagai) kewajiban bagi orang-orang yang bertakwa"},{id:181,text:"\u0641\u064e\u0645\u064e\u0646\u06e2 \u0628\u064e\u062f\u0651\u064e\u0644\u064e\u0647\u064f\u06e5 \u0628\u064e\u0639\u06e1\u062f\u064e \u0645\u064e\u0627 \u0633\u064e\u0645\u0650\u0639\u064e\u0647\u064f\u06e5 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627\u0653 \u0625\u0650\u062b\u06e1\u0645\u064f\u0647\u064f\u06e5 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0628\u064e\u062f\u0651\u0650\u0644\u064f\u0648\u0646\u064e\u0647\u064f\u06e5\u0653\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0633\u064e\u0645\u0650\u064a\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Barang siapa mengubahnya (wasiat itu), setelah mendengarnya, maka sesungguhnya dosanya hanya bagi orang yang mengubahnya. Sungguh, Allah Maha Mendengar, Maha Mengetahui"},{id:182,text:"\u0641\u064e\u0645\u064e\u0646\u06e1 \u062e\u064e\u0627\u0641\u064e \u0645\u0650\u0646 \u0645\u0651\u064f\u0648\u0635\u0656 \u062c\u064e\u0646\u064e\u0641\u064b\u0627 \u0623\u064e\u0648\u06e1 \u0625\u0650\u062b\u06e1\u0645\u0657\u0627 \u0641\u064e\u0623\u064e\u0635\u06e1\u0644\u064e\u062d\u064e \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1 \u0641\u064e\u0644\u064e\u0627\u0653 \u0625\u0650\u062b\u06e1\u0645\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u065e",translation:"Tetapi barang siapa khawatir bahwa pemberi wasiat (berlaku) berat sebelah atau berbuat salah, lalu dia mendamaikan61) antara mereka, maka dia tidak berdosa. Sungguh, Allah Maha Pengampun, Maha Penyayang"},{id:183,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0643\u064f\u062a\u0650\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u064f \u0671\u0644\u0635\u0651\u0650\u064a\u064e\u0627\u0645\u064f \u0643\u064e\u0645\u064e\u0627 \u0643\u064f\u062a\u0650\u0628\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064f\u0645\u06e1 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",translation:"Wahai orang-orang yang beriman! Diwajibkan atas kamu berpuasa sebagaimana diwajibkan atas orang sebelum kamu agar kamu bertakwa"},{id:184,text:"\u0623\u064e\u064a\u0651\u064e\u0627\u0645\u0657\u0627 \u0645\u0651\u064e\u0639\u06e1\u062f\u064f\u0648\u062f\u064e\u0670\u062a\u0656\u06da \u0641\u064e\u0645\u064e\u0646 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u0643\u064f\u0645 \u0645\u0651\u064e\u0631\u0650\u064a\u0636\u064b\u0627 \u0623\u064e\u0648\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0633\u064e\u0641\u064e\u0631\u0656 \u0641\u064e\u0639\u0650\u062f\u0651\u064e\u0629\u065e \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u064d \u0623\u064f\u062e\u064e\u0631\u064e\u06da \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0637\u0650\u064a\u0642\u064f\u0648\u0646\u064e\u0647\u064f\u06e5 \u0641\u0650\u062f\u06e1\u064a\u064e\u0629\u065e \u0637\u064e\u0639\u064e\u0627\u0645\u064f \u0645\u0650\u0633\u06e1\u0643\u0650\u064a\u0646\u0656\u06d6 \u0641\u064e\u0645\u064e\u0646 \u062a\u064e\u0637\u064e\u0648\u0651\u064e\u0639\u064e \u062e\u064e\u064a\u06e1\u0631\u0657\u0627 \u0641\u064e\u0647\u064f\u0648\u064e \u062e\u064e\u064a\u06e1\u0631\u065e \u0644\u0651\u064e\u0647\u064f\u06e5\u06da \u0648\u064e\u0623\u064e\u0646 \u062a\u064e\u0635\u064f\u0648\u0645\u064f\u0648\u0627\u0652 \u062e\u064e\u064a\u06e1\u0631\u065e \u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"(Yaitu) beberapa hari tertentu. Maka barang siapa di antara kamu sakit atau dalam perjalanan (lalu tidak berpuasa), maka (wajib mengganti) sebanyak hari (yang dia tidak berpuasa itu) pada hari-hari yang lain. Dan bagi orang yang berat menjalankannya,62) wajib membayar fidyah, yaitu memberi makan seorang miskin. Tetapi barang siapa dengan kerelaan hati mengerjakan kebajikan,63) maka itu lebih baik baginya, dan puasamu itu lebih baik bagimu jika kamu mengetahui"},{id:185,text:"\u0634\u064e\u0647\u06e1\u0631\u064f \u0631\u064e\u0645\u064e\u0636\u064e\u0627\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0641\u0650\u064a\u0647\u0650 \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u064f \u0647\u064f\u062f\u0657\u0649 \u0644\u0651\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0656 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0647\u064f\u062f\u064e\u0649\u0670 \u0648\u064e\u0671\u0644\u06e1\u0641\u064f\u0631\u06e1\u0642\u064e\u0627\u0646\u0650\u06da \u0641\u064e\u0645\u064e\u0646 \u0634\u064e\u0647\u0650\u062f\u064e \u0645\u0650\u0646\u0643\u064f\u0645\u064f \u0671\u0644\u0634\u0651\u064e\u0647\u06e1\u0631\u064e \u0641\u064e\u0644\u06e1\u064a\u064e\u0635\u064f\u0645\u06e1\u0647\u064f\u06d6 \u0648\u064e\u0645\u064e\u0646 \u0643\u064e\u0627\u0646\u064e \u0645\u064e\u0631\u0650\u064a\u0636\u064b\u0627 \u0623\u064e\u0648\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0633\u064e\u0641\u064e\u0631\u0656 \u0641\u064e\u0639\u0650\u062f\u0651\u064e\u0629\u065e \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u064d \u0623\u064f\u062e\u064e\u0631\u064e\u06d7 \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u064a\u064f\u0633\u06e1\u0631\u064e \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0628\u0650\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0639\u064f\u0633\u06e1\u0631\u064e \u0648\u064e\u0644\u0650\u062a\u064f\u0643\u06e1\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0639\u0650\u062f\u0651\u064e\u0629\u064e \u0648\u064e\u0644\u0650\u062a\u064f\u0643\u064e\u0628\u0651\u0650\u0631\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0647\u064e\u062f\u064e\u0649\u0670\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u0634\u06e1\u0643\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Bulan Ramadan adalah (bulan) yang di dalamnya diturunkan Alquran, sebagai petunjuk bagi manusia dan penjelasan-penjelasan mengenai petunjuk itu dan pembeda (antara yang benar dan yang batil). Karena itu, barang siapa di antara kamu mendapati bulan itu, maka berpuasalah. Dan barang siapa sakit atau dalam perjalanan (dia tidak berpuasa), maka (wajib menggantinya), sebanyak hari yang ditinggalkannya, pada hari-hari yang lain. Allah menghendaki kemudahan bagimu, dan tidak menghendaki kesukaran bagimu. Hendaklah kamu mencukupkan bilangannya dan mengagungkan Allah atas petunjuk-Nya yang diberikan kepadamu, agar kamu bersyukur"},{id:186,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0633\u064e\u0623\u064e\u0644\u064e\u0643\u064e \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a \u0639\u064e\u0646\u0651\u0650\u064a \u0641\u064e\u0625\u0650\u0646\u0651\u0650\u064a \u0642\u064e\u0631\u0650\u064a\u0628\u064c\u06d6 \u0623\u064f\u062c\u0650\u064a\u0628\u064f \u062f\u064e\u0639\u06e1\u0648\u064e\u0629\u064e \u0671\u0644\u062f\u0651\u064e\u0627\u0639\u0650 \u0625\u0650\u0630\u064e\u0627 \u062f\u064e\u0639\u064e\u0627\u0646\u0650\u06d6 \u0641\u064e\u0644\u06e1\u064a\u064e\u0633\u06e1\u062a\u064e\u062c\u0650\u064a\u0628\u064f\u0648\u0627\u0652 \u0644\u0650\u064a \u0648\u064e\u0644\u06e1\u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u064a \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0631\u06e1\u0634\u064f\u062f\u064f\u0648\u0646\u064e",translation:"Dan apabila hamba-hamba-Ku bertanya kepadamu (Muhammad) tentang Aku, maka sesungguhnya Aku dekat. Aku kabulkan permohonan orang yang berdoa apabila dia berdoa kepada-Ku. Hendaklah mereka itu memenuhi (perintah)-Ku dan beriman kepada-Ku, agar mereka memperoleh kebenaran"},{id:187,text:"\u0623\u064f\u062d\u0650\u0644\u0651\u064e \u0644\u064e\u0643\u064f\u0645\u06e1 \u0644\u064e\u064a\u06e1\u0644\u064e\u0629\u064e \u0671\u0644\u0635\u0651\u0650\u064a\u064e\u0627\u0645\u0650 \u0671\u0644\u0631\u0651\u064e\u0641\u064e\u062b\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0646\u0650\u0633\u064e\u0627\u0653\u0626\u0650\u0643\u064f\u0645\u06e1\u06da \u0647\u064f\u0646\u0651\u064e \u0644\u0650\u0628\u064e\u0627\u0633\u065e \u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0644\u0650\u0628\u064e\u0627\u0633\u065e \u0644\u0651\u064e\u0647\u064f\u0646\u0651\u064e\u06d7 \u0639\u064e\u0644\u0650\u0645\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u062e\u06e1\u062a\u064e\u0627\u0646\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0643\u064f\u0645\u06e1 \u0641\u064e\u062a\u064e\u0627\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0648\u064e\u0639\u064e\u0641\u064e\u0627 \u0639\u064e\u0646\u0643\u064f\u0645\u06e1\u06d6 \u0641\u064e\u0671\u0644\u06e1\u0640\u0654\u064e\u0670\u0646\u064e \u0628\u064e\u0670\u0634\u0650\u0631\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0648\u064e\u0671\u0628\u06e1\u062a\u064e\u063a\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u0643\u064e\u062a\u064e\u0628\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0643\u064f\u0644\u064f\u0648\u0627\u0652 \u0648\u064e\u0671\u0634\u06e1\u0631\u064e\u0628\u064f\u0648\u0627\u0652 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u062a\u064e\u0628\u064e\u064a\u0651\u064e\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u062e\u064e\u064a\u06e1\u0637\u064f \u0671\u0644\u06e1\u0623\u064e\u0628\u06e1\u064a\u064e\u0636\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u062e\u064e\u064a\u06e1\u0637\u0650 \u0671\u0644\u06e1\u0623\u064e\u0633\u06e1\u0648\u064e\u062f\u0650 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0641\u064e\u062c\u06e1\u0631\u0650\u06d6 \u062b\u064f\u0645\u0651\u064e \u0623\u064e\u062a\u0650\u0645\u0651\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u0650\u064a\u064e\u0627\u0645\u064e \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u0650\u06da \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0628\u064e\u0670\u0634\u0650\u0631\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0639\u064e\u0670\u0643\u0650\u0641\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0645\u064e\u0633\u064e\u0670\u062c\u0650\u062f\u0650\u06d7 \u062a\u0650\u0644\u06e1\u0643\u064e \u062d\u064f\u062f\u064f\u0648\u062f\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u06e1\u0631\u064e\u0628\u064f\u0648\u0647\u064e\u0627\u06d7 \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0647\u0650\u06e6 \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",translation:"Dihalalkan bagimu pada malam hari puasa bercampur dengan isterimu. Mereka adalah pakaian bagimu, dan kamu adalah pakaian bagi mereka. Allah mengetahui bahwa kamu tidak dapat menahan dirimu sendiri, tetapi Dia menerima tobatmu dan memaafkanmu. Maka sekarang campurilah mereka dan carilah apa yang telah ditetapkan Allah bagimu. Makan dan minumlah hingga jelas bagimu (perbedaan) antara benang putih dan benang hitam, yaitu fajar. Kemudian sempurnakanlah puasa sampai (datang) malam. Tetapi jangan kamu campuri mereka, ketika kamu beriktikaf64) dalam masjid. Itulah ketentuan Allah, maka janganlah kamu mendekatinya. Demikianlah Allah menerangkan ayat-ayat-Nya kepada manusia, agar mereka bertakwa"},{id:188,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u064e\u0643\u064f\u0645 \u0628\u064e\u064a\u06e1\u0646\u064e\u0643\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0628\u064e\u0670\u0637\u0650\u0644\u0650 \u0648\u064e\u062a\u064f\u062f\u06e1\u0644\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u062d\u064f\u0643\u0651\u064e\u0627\u0645\u0650 \u0644\u0650\u062a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f\u0648\u0627\u0652 \u0641\u064e\u0631\u0650\u064a\u0642\u0657\u0627 \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u0650 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0628\u0650\u0671\u0644\u06e1\u0625\u0650\u062b\u06e1\u0645\u0650 \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan janganlah kamu makan harta di antara kamu dengan jalan yang batil, dan (janganlah) kamu menyuap dengan harta itu kepada para hakim, dengan maksud agar kamu dapat memakan sebagian harta orang lain itu dengan jalan dosa, padahal kamu mengetahui"},{id:189,text:"\u06de\u064a\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u0639\u064e\u0646\u0650 \u0671\u0644\u06e1\u0623\u064e\u0647\u0650\u0644\u0651\u064e\u0629\u0650\u06d6 \u0642\u064f\u0644\u06e1 \u0647\u0650\u064a\u064e \u0645\u064e\u0648\u064e\u0670\u0642\u0650\u064a\u062a\u064f \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0671\u0644\u06e1\u062d\u064e\u062c\u0651\u0650\u06d7 \u0648\u064e\u0644\u064e\u064a\u06e1\u0633\u064e \u0671\u0644\u06e1\u0628\u0650\u0631\u0651\u064f \u0628\u0650\u0623\u064e\u0646 \u062a\u064e\u0623\u06e1\u062a\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0628\u064f\u064a\u064f\u0648\u062a\u064e \u0645\u0650\u0646 \u0638\u064f\u0647\u064f\u0648\u0631\u0650\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0628\u0650\u0631\u0651\u064e \u0645\u064e\u0646\u0650 \u0671\u062a\u0651\u064e\u0642\u064e\u0649\u0670\u06d7 \u0648\u064e\u0623\u06e1\u062a\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0628\u064f\u064a\u064f\u0648\u062a\u064e \u0645\u0650\u0646\u06e1 \u0623\u064e\u0628\u06e1\u0648\u064e\u0670\u0628\u0650\u0647\u064e\u0627\u06da \u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064f\u0641\u06e1\u0644\u0650\u062d\u064f\u0648\u0646\u064e",translation:"Mereka bertanya kepadamu (Muhammad) tentang bulan sabit. Katakanlah, \"itu adalah (penunjuk) waktu bagi manusia dan (ibadah) haji.\" Dan bukanlah suatu kebajikan memasuki rumah dari atasnya,65) tetapi kebajikan adalah (kebajikan) orang yang bertakwa. Masukilah rumah-rumah dari pintu-pintunya, dan bertakwalah kepada Allah agar kamu beruntung"},{id:190,text:"\u0648\u064e\u0642\u064e\u0670\u062a\u0650\u0644\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0642\u064e\u0670\u062a\u0650\u0644\u064f\u0648\u0646\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u062a\u064e\u062f\u064f\u0648\u0653\u0627\u0652\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0671\u0644\u06e1\u0645\u064f\u0639\u06e1\u062a\u064e\u062f\u0650\u064a\u0646\u064e",translation:"Dan perangilah di jalan Allah orang-orang yang memerangi kamu, tetapi jangan melampaui batas. Sungguh, Allah tidak menyukai orang-orang yang melampaui batas"},{id:191,text:"\u0648\u064e\u0671\u0642\u06e1\u062a\u064f\u0644\u064f\u0648\u0647\u064f\u0645\u06e1 \u062d\u064e\u064a\u06e1\u062b\u064f \u062b\u064e\u0642\u0650\u0641\u06e1\u062a\u064f\u0645\u064f\u0648\u0647\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u062e\u06e1\u0631\u0650\u062c\u064f\u0648\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u062d\u064e\u064a\u06e1\u062b\u064f \u0623\u064e\u062e\u06e1\u0631\u064e\u062c\u064f\u0648\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0671\u0644\u06e1\u0641\u0650\u062a\u06e1\u0646\u064e\u0629\u064f \u0623\u064e\u0634\u064e\u062f\u0651\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0642\u064e\u062a\u06e1\u0644\u0650\u06da \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0642\u064e\u0670\u062a\u0650\u0644\u064f\u0648\u0647\u064f\u0645\u06e1 \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u06e1\u0645\u064e\u0633\u06e1\u062c\u0650\u062f\u0650 \u0671\u0644\u06e1\u062d\u064e\u0631\u064e\u0627\u0645\u0650 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064f\u0642\u064e\u0670\u062a\u0650\u0644\u064f\u0648\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u0650\u06d6 \u0641\u064e\u0625\u0650\u0646 \u0642\u064e\u0670\u062a\u064e\u0644\u064f\u0648\u0643\u064f\u0645\u06e1 \u0641\u064e\u0671\u0642\u06e1\u062a\u064f\u0644\u064f\u0648\u0647\u064f\u0645\u06e1\u06d7 \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062c\u064e\u0632\u064e\u0627\u0653\u0621\u064f \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"(Dan bunuhlah mereka di mana kamu temui mereka, dan usirlah mereka dari mana mereka telah mengusir kamu. Dan fitnah66) itu lebih kejam daripada pembunuhan. Dan janganlah kamu perangi mereka di Masjidilharam, kecuali jika mereka memerangi kamu di tempat itu. Jika mereka memerangi kamu, maka perangilah mereka. Demikianlah balasan bagi orang kafir"},{id:192,text:"\u0641\u064e\u0625\u0650\u0646\u0650 \u0671\u0646\u062a\u064e\u0647\u064e\u0648\u06e1\u0627\u0652 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u065e",translation:"Tetapi jika mereka berhenti, maka sungguh, Allah Maha Pengampun, Maha Penyayang"},{id:193,text:"\u0648\u064e\u0642\u064e\u0670\u062a\u0650\u0644\u064f\u0648\u0647\u064f\u0645\u06e1 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0641\u0650\u062a\u06e1\u0646\u064e\u0629\u065e \u0648\u064e\u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650\u06d6 \u0641\u064e\u0625\u0650\u0646\u0650 \u0671\u0646\u062a\u064e\u0647\u064e\u0648\u06e1\u0627\u0652 \u0641\u064e\u0644\u064e\u0627 \u0639\u064f\u062f\u06e1\u0648\u064e\u0670\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dan perangilah mereka itu sampai tidak ada lagi fitnah, dan agama hanya bagi Allah semata. Jika mereka berhenti, maka tidak ada (lagi) permusuhan, kecuali terhadap orang-orang zalim"},{id:194,text:"\u0671\u0644\u0634\u0651\u064e\u0647\u06e1\u0631\u064f \u0671\u0644\u06e1\u062d\u064e\u0631\u064e\u0627\u0645\u064f \u0628\u0650\u0671\u0644\u0634\u0651\u064e\u0647\u06e1\u0631\u0650 \u0671\u0644\u06e1\u062d\u064e\u0631\u064e\u0627\u0645\u0650 \u0648\u064e\u0671\u0644\u06e1\u062d\u064f\u0631\u064f\u0645\u064e\u0670\u062a\u064f \u0642\u0650\u0635\u064e\u0627\u0635\u065e\u06da \u0641\u064e\u0645\u064e\u0646\u0650 \u0671\u0639\u06e1\u062a\u064e\u062f\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0641\u064e\u0671\u0639\u06e1\u062a\u064e\u062f\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0628\u0650\u0645\u0650\u062b\u06e1\u0644\u0650 \u0645\u064e\u0627 \u0671\u0639\u06e1\u062a\u064e\u062f\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0671\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064e\u0639\u064e \u0671\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",translation:"(Bulan haram dengan bulan haram,67) dan (terhadap) sesuatu yang dihormati68) berlaku (hukum) kisas. Oleh sebab itu barang siapa menyerang kamu, maka seranglah dia setimpal dengan serangannya terhadap kamu. Bertakwalah kepada Allah dan ketahuilah bahwa Allah beserta orang-orang yang bertakwa"},{id:195,text:"\u0648\u064e\u0623\u064e\u0646\u0641\u0650\u0642\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0644\u06e1\u0642\u064f\u0648\u0627\u0652 \u0628\u0650\u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u0643\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u062a\u0651\u064e\u0647\u06e1\u0644\u064f\u0643\u064e\u0629\u0650 \u0648\u064e\u0623\u064e\u062d\u06e1\u0633\u0650\u0646\u064f\u0648\u0653\u0627\u0652\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0671\u0644\u06e1\u0645\u064f\u062d\u06e1\u0633\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dan infakkanlah (hartamu) di jalan Allah, dan janganlah kamu jatuhkan (diri sendiri) ke dalam kebinasaan dengan tangan sendiri, dan berbuat baiklah. Sungguh, Allah menyukai orang-orang yang berbuat baik"},{id:196,text:"\u0648\u064e\u0623\u064e\u062a\u0650\u0645\u0651\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u062d\u064e\u062c\u0651\u064e \u0648\u064e\u0671\u0644\u06e1\u0639\u064f\u0645\u06e1\u0631\u064e\u0629\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650\u06da \u0641\u064e\u0625\u0650\u0646\u06e1 \u0623\u064f\u062d\u06e1\u0635\u0650\u0631\u06e1\u062a\u064f\u0645\u06e1 \u0641\u064e\u0645\u064e\u0627 \u0671\u0633\u06e1\u062a\u064e\u064a\u06e1\u0633\u064e\u0631\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0647\u064e\u062f\u06e1\u064a\u0650\u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062d\u06e1\u0644\u0650\u0642\u064f\u0648\u0627\u0652 \u0631\u064f\u0621\u064f\u0648\u0633\u064e\u0643\u064f\u0645\u06e1 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0628\u06e1\u0644\u064f\u063a\u064e \u0671\u0644\u06e1\u0647\u064e\u062f\u06e1\u064a\u064f \u0645\u064e\u062d\u0650\u0644\u0651\u064e\u0647\u064f\u06e5\u06da \u0641\u064e\u0645\u064e\u0646 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u0643\u064f\u0645 \u0645\u0651\u064e\u0631\u0650\u064a\u0636\u064b\u0627 \u0623\u064e\u0648\u06e1 \u0628\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0630\u0657\u0649 \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0623\u06e1\u0633\u0650\u0647\u0650\u06e6 \u0641\u064e\u0641\u0650\u062f\u06e1\u064a\u064e\u0629\u065e \u0645\u0651\u0650\u0646 \u0635\u0650\u064a\u064e\u0627\u0645\u064d \u0623\u064e\u0648\u06e1 \u0635\u064e\u062f\u064e\u0642\u064e\u0629\u064d \u0623\u064e\u0648\u06e1 \u0646\u064f\u0633\u064f\u0643\u0656\u06da \u0641\u064e\u0625\u0650\u0630\u064e\u0627\u0653 \u0623\u064e\u0645\u0650\u0646\u062a\u064f\u0645\u06e1 \u0641\u064e\u0645\u064e\u0646 \u062a\u064e\u0645\u064e\u062a\u0651\u064e\u0639\u064e \u0628\u0650\u0671\u0644\u06e1\u0639\u064f\u0645\u06e1\u0631\u064e\u0629\u0650 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u062d\u064e\u062c\u0651\u0650 \u0641\u064e\u0645\u064e\u0627 \u0671\u0633\u06e1\u062a\u064e\u064a\u06e1\u0633\u064e\u0631\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0647\u064e\u062f\u06e1\u064a\u0650\u06da \u0641\u064e\u0645\u064e\u0646 \u0644\u0651\u064e\u0645\u06e1 \u064a\u064e\u062c\u0650\u062f\u06e1 \u0641\u064e\u0635\u0650\u064a\u064e\u0627\u0645\u064f \u062b\u064e\u0644\u064e\u0670\u062b\u064e\u0629\u0650 \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u0656 \u0641\u0650\u064a \u0671\u0644\u06e1\u062d\u064e\u062c\u0651\u0650 \u0648\u064e\u0633\u064e\u0628\u06e1\u0639\u064e\u0629\u064d \u0625\u0650\u0630\u064e\u0627 \u0631\u064e\u062c\u064e\u0639\u06e1\u062a\u064f\u0645\u06e1\u06d7 \u062a\u0650\u0644\u06e1\u0643\u064e \u0639\u064e\u0634\u064e\u0631\u064e\u0629\u065e \u0643\u064e\u0627\u0645\u0650\u0644\u064e\u0629\u065e\u06d7 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u0650\u0645\u064e\u0646 \u0644\u0651\u064e\u0645\u06e1 \u064a\u064e\u0643\u064f\u0646\u06e1 \u0623\u064e\u0647\u06e1\u0644\u064f\u0647\u064f\u06e5 \u062d\u064e\u0627\u0636\u0650\u0631\u0650\u064a \u0671\u0644\u06e1\u0645\u064e\u0633\u06e1\u062c\u0650\u062f\u0650 \u0671\u0644\u06e1\u062d\u064e\u0631\u064e\u0627\u0645\u0650\u06da \u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0671\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0634\u064e\u062f\u0650\u064a\u062f\u064f \u0671\u0644\u06e1\u0639\u0650\u0642\u064e\u0627\u0628\u0650",translation:"Dan sempurnakanlah ibadah haji dan umrah karena Allah. Tetapi jika kamu terkepung (oleh musuh), maka (sembelihlah) hadyu69) yang mudah didapat, dan jangan kamu mencukur kepalamu, sebelum hadyu sampai di tempat penyembelihannya. Jika ada di antara kamu yang sakit atau ada gangguan di kepalanya (lalu dia bercukur), maka dia wajib berfidyah, yaitu berpuasa, bersedekah atau berkurban. Apabila kamu dalam keadaan aman, maka barang siapa mengerjakan umrah sebelum haji, dia (wajib menyembelih) hadyu yang mudah didapat. Tetapi jika dia tidak mendapatkannya, maka dia (wajib) berpuasa tiga hari dalam (musim) haji dan tujuh (hari) setelah kamu kembali. Itulah sepuluh (hari) yang lengkap. Demikian itu, bagi orang yang keluarganya tidak ada (tinggal) disekitar Masjidilharam. Bertakwalah kepada Allah dan ketahuilah bahwa Allah sangat keras hukuman-Nya"},{id:197,text:"\u0671\u0644\u06e1\u062d\u064e\u062c\u0651\u064f \u0623\u064e\u0634\u06e1\u0647\u064f\u0631\u065e \u0645\u0651\u064e\u0639\u06e1\u0644\u064f\u0648\u0645\u064e\u0670\u062a\u065e\u06da \u0641\u064e\u0645\u064e\u0646 \u0641\u064e\u0631\u064e\u0636\u064e \u0641\u0650\u064a\u0647\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u062d\u064e\u062c\u0651\u064e \u0641\u064e\u0644\u064e\u0627 \u0631\u064e\u0641\u064e\u062b\u064e \u0648\u064e\u0644\u064e\u0627 \u0641\u064f\u0633\u064f\u0648\u0642\u064e \u0648\u064e\u0644\u064e\u0627 \u062c\u0650\u062f\u064e\u0627\u0644\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u062d\u064e\u062c\u0651\u0650\u06d7 \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0641\u06e1\u0639\u064e\u0644\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1 \u062e\u064e\u064a\u06e1\u0631\u0656 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u06e1\u0647\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06d7 \u0648\u064e\u062a\u064e\u0632\u064e\u0648\u0651\u064e\u062f\u064f\u0648\u0627\u0652 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u062e\u064e\u064a\u06e1\u0631\u064e \u0671\u0644\u0632\u0651\u064e\u0627\u062f\u0650 \u0671\u0644\u062a\u0651\u064e\u0642\u06e1\u0648\u064e\u0649\u0670\u06d6 \u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u0650 \u064a\u064e\u0640\u0670\u0653\u0623\u064f\u0648\u0652\u0644\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0644\u06e1\u0628\u064e\u0670\u0628\u0650",translation:"(Musim) haji itu (pada) bulan-bulan yang telah dimaklumi.70) Barang siapa mengerjakan (ibadah) haji dalam (bulan-bulan) itu, maka janganlah dia berkata jorok (rafa\u1e61),71) berbuat maksiat dan bertengkar dalam (melakukan ibadah) haji. Segala yang baik yang kamu kerjakan, Allah mengetahuinya. Bawalah bekal, karena sesungguhnya sebaik-baik bekal adalah takwa. Dan bertakwalah kepada-Ku Wahai orang-orang yang mempunyai akal sehat"},{id:198,text:"\u0644\u064e\u064a\u06e1\u0633\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u062c\u064f\u0646\u064e\u0627\u062d\u064c \u0623\u064e\u0646 \u062a\u064e\u0628\u06e1\u062a\u064e\u063a\u064f\u0648\u0627\u0652 \u0641\u064e\u0636\u06e1\u0644\u0657\u0627 \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1\u06da \u0641\u064e\u0625\u0650\u0630\u064e\u0627\u0653 \u0623\u064e\u0641\u064e\u0636\u06e1\u062a\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0639\u064e\u0631\u064e\u0641\u064e\u0670\u062a\u0656 \u0641\u064e\u0671\u0630\u06e1\u0643\u064f\u0631\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u06e1\u0645\u064e\u0634\u06e1\u0639\u064e\u0631\u0650 \u0671\u0644\u06e1\u062d\u064e\u0631\u064e\u0627\u0645\u0650\u06d6 \u0648\u064e\u0671\u0630\u06e1\u0643\u064f\u0631\u064f\u0648\u0647\u064f \u0643\u064e\u0645\u064e\u0627 \u0647\u064e\u062f\u064e\u0649\u0670\u0643\u064f\u0645\u06e1 \u0648\u064e\u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645 \u0645\u0651\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u06e6 \u0644\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u0636\u0651\u064e\u0627\u0653\u0644\u0651\u0650\u064a\u0646\u064e",translation:"Bukanlah suatu dosa bagimu mencari karunia dari Tuhanmu. Maka apabila kamu bertolak dari Arafah, berzikirlah kepada Allah di Masy'arilharam. Dan berzikirlah kepada-Nya sebagaimana Dia telah memberi petunjuk kepadamu, sekalipun sebelumnya kamu benar-benar termasuk orang yang tidak tahu"},{id:199,text:"\u062b\u064f\u0645\u0651\u064e \u0623\u064e\u0641\u0650\u064a\u0636\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1 \u062d\u064e\u064a\u06e1\u062b\u064f \u0623\u064e\u0641\u064e\u0627\u0636\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0648\u064e\u0671\u0633\u06e1\u062a\u064e\u063a\u06e1\u0641\u0650\u0631\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u065e",translation:"Kemudian bertolaklah kamu dari tempat orang banyak bertolak (Arafah) dan mohonlah ampunan kepada Allah. Sungguh, Allah Maha Pengampun, Maha Penyayang"},{id:200,text:"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u064e\u0636\u064e\u064a\u06e1\u062a\u064f\u0645 \u0645\u0651\u064e\u0646\u064e\u0670\u0633\u0650\u0643\u064e\u0643\u064f\u0645\u06e1 \u0641\u064e\u0671\u0630\u06e1\u0643\u064f\u0631\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0630\u0650\u0643\u06e1\u0631\u0650\u0643\u064f\u0645\u06e1 \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1 \u0623\u064e\u0634\u064e\u062f\u0651\u064e \u0630\u0650\u0643\u06e1\u0631\u0657\u0627\u06d7 \u0641\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0645\u064e\u0646 \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u06e5 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0645\u0650\u0646\u06e1 \u062e\u064e\u0644\u064e\u0670\u0642\u0656",translation:"(Apabila kamu telah menyelesaikan ibadah haji, maka berzikirlah kepada Allah, sebagaimana kamu menyebut-nyebut nenek moyang kamu,72) bahkan berzikirlah lebih dari itu. Maka di antara manusia ada orang berdoa, \"Ya Tuhan Kami, berilah kami (kebaikan) di dunia,\" dan di akhirat dia tidak memperoleh bagian apa pun"},{id:201,text:"\u0648\u064e\u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0646 \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u062d\u064e\u0633\u064e\u0646\u064e\u0629\u0657 \u0648\u064e\u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u062d\u064e\u0633\u064e\u0646\u064e\u0629\u0657 \u0648\u064e\u0642\u0650\u0646\u064e\u0627 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650",translation:"Dan di antara mereka ada orang yang berdoa, \"Ya Tuhan kami, berilah kami kebaikan di dunia dan kebaikan di akhirat, dan lindungilah kami dari azab neraka"},{id:202,text:"\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0646\u064e\u0635\u0650\u064a\u0628\u065e \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064f\u0648\u0627\u0652\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0633\u064e\u0631\u0650\u064a\u0639\u064f \u0671\u0644\u06e1\u062d\u0650\u0633\u064e\u0627\u0628\u0650",translation:"Mereka itulah orang yang memperoleh bagian dari apa yang telah mereka kerjakan, dan Allah Mahacepat perhitungan-Nya"},{id:203,text:"\u06de\u0648\u064e\u0671\u0630\u06e1\u0643\u064f\u0631\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0641\u0650\u064a\u0653 \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u0656 \u0645\u0651\u064e\u0639\u06e1\u062f\u064f\u0648\u062f\u064e\u0670\u062a\u0656\u06da \u0641\u064e\u0645\u064e\u0646 \u062a\u064e\u0639\u064e\u062c\u0651\u064e\u0644\u064e \u0641\u0650\u064a \u064a\u064e\u0648\u06e1\u0645\u064e\u064a\u06e1\u0646\u0650 \u0641\u064e\u0644\u064e\u0627\u0653 \u0625\u0650\u062b\u06e1\u0645\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0648\u064e\u0645\u064e\u0646 \u062a\u064e\u0623\u064e\u062e\u0651\u064e\u0631\u064e \u0641\u064e\u0644\u064e\u0627\u0653 \u0625\u0650\u062b\u06e1\u0645\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u06d6 \u0644\u0650\u0645\u064e\u0646\u0650 \u0671\u062a\u0651\u064e\u0642\u064e\u0649\u0670\u06d7 \u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0671\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u062a\u064f\u062d\u06e1\u0634\u064e\u0631\u064f\u0648\u0646\u064e",translation:"(Dan berzikirlah kepada Allah pada hari yang telah ditentukan jumlahnya.73) Barang siapa mempercepat (meninggalkan Mina) setelah dua hari, maka ia tak berdosa. Dan barang siapa mengakhirkannya tidak ada dosa (pula) baginya, (yakni) bagi orang yang bertakwa. Dan bertakwalah kepada Allah, dan ketahuilah bahwa kamu akan dikumpulkan pada-Nya"},{id:204,text:"\u0648\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0645\u064e\u0646 \u064a\u064f\u0639\u06e1\u062c\u0650\u0628\u064f\u0643\u064e \u0642\u064e\u0648\u06e1\u0644\u064f\u0647\u064f\u06e5 \u0641\u0650\u064a \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u0650 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0648\u064e\u064a\u064f\u0634\u06e1\u0647\u0650\u062f\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0641\u0650\u064a \u0642\u064e\u0644\u06e1\u0628\u0650\u0647\u0650\u06e6 \u0648\u064e\u0647\u064f\u0648\u064e \u0623\u064e\u0644\u064e\u062f\u0651\u064f \u0671\u0644\u06e1\u062e\u0650\u0635\u064e\u0627\u0645\u0650",translation:"Dan di antara manusia ada yang pembicaraannya tentang kehidupan dunia mengagumkan engkau (Muhammad), dan dia bersaksi kepada Allah mengenai isi hatinya, padahal dia adalah penentang yang paling keras"},{id:205,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649\u0670 \u0633\u064e\u0639\u064e\u0649\u0670 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0644\u0650\u064a\u064f\u0641\u06e1\u0633\u0650\u062f\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u064a\u064f\u0647\u06e1\u0644\u0650\u0643\u064e \u0671\u0644\u06e1\u062d\u064e\u0631\u06e1\u062b\u064e \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0633\u06e1\u0644\u064e\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0671\u0644\u06e1\u0641\u064e\u0633\u064e\u0627\u062f\u064e",translation:"Dan apabila dia berpaling (dari engkau), dia berusaha untuk berbuat kerusakan di bumi, serta merusak tanam-tanaman dan ternak, sedang Allah tidak menyukai kerusakan"},{id:206,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f \u0671\u062a\u0651\u064e\u0642\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0623\u064e\u062e\u064e\u0630\u064e\u062a\u06e1\u0647\u064f \u0671\u0644\u06e1\u0639\u0650\u0632\u0651\u064e\u0629\u064f \u0628\u0650\u0671\u0644\u06e1\u0625\u0650\u062b\u06e1\u0645\u0650\u06da \u0641\u064e\u062d\u064e\u0633\u06e1\u0628\u064f\u0647\u064f\u06e5 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064f\u06d6 \u0648\u064e\u0644\u064e\u0628\u0650\u0626\u06e1\u0633\u064e \u0671\u0644\u06e1\u0645\u0650\u0647\u064e\u0627\u062f\u064f",translation:"Dan apabila dikatakan kepadanya, \"Bertakwalah kepada Allah,\" bangkitlah kesom\xadbongannya untuk berbuat dosa. Maka pantaslah baginya neraka Jahanam, dan sungguh (Jahanam itu) tempat tinggal yang terburuk"},{id:207,text:"\u0648\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0645\u064e\u0646 \u064a\u064e\u0634\u06e1\u0631\u0650\u064a \u0646\u064e\u0641\u06e1\u0633\u064e\u0647\u064f \u0671\u0628\u06e1\u062a\u0650\u063a\u064e\u0627\u0653\u0621\u064e \u0645\u064e\u0631\u06e1\u0636\u064e\u0627\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0631\u064e\u0621\u064f\u0648\u0641\u064f\u06e2 \u0628\u0650\u0671\u0644\u06e1\u0639\u0650\u0628\u064e\u0627\u062f\u0650",translation:"Dan di antara manusia ada orang yang mengorbankan dirinya untuk mencari keridaan Allah. Dan Allah Maha Penyantun kepada hamba-hamba-Nya"},{id:208,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0671\u062f\u06e1\u062e\u064f\u0644\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u0650\u0644\u06e1\u0645\u0650 \u0643\u064e\u0627\u0653\u0641\u0651\u064e\u0629\u0657 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0627\u0652 \u062e\u064f\u0637\u064f\u0648\u064e\u0670\u062a\u0650 \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u0650\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0639\u064e\u062f\u064f\u0648\u0651\u065e \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u065e",translation:"Wahai orang-orang yang beriman! Masuklah ke dalam Islam secara keseluruhan, dan janganlah kamu ikuti langkah-langkah setan. Sungguh, ia musuh yang nyata bagimu"},{id:209,text:"\u0641\u064e\u0625\u0650\u0646 \u0632\u064e\u0644\u064e\u0644\u06e1\u062a\u064f\u0645 \u0645\u0651\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0645\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u062a\u06e1\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u064f \u0641\u064e\u0671\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0632\u0650\u064a\u0632\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u064c",translation:"Tetapi jika kamu tergelincir setelah bukti-bukti yang nyata sampai kepadamu, ketahuilah bahwa Allah Mahaperkasa, Mahabijaksana"},{id:210,text:"\u0647\u064e\u0644\u06e1 \u064a\u064e\u0646\u0638\u064f\u0631\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u0650\u064a \u0638\u064f\u0644\u064e\u0644\u0656 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u063a\u064e\u0645\u064e\u0627\u0645\u0650 \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u064f \u0648\u064e\u0642\u064f\u0636\u0650\u064a\u064e \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0631\u064f\u06da \u0648\u064e\u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064f\u0631\u06e1\u062c\u064e\u0639\u064f \u0671\u0644\u06e1\u0623\u064f\u0645\u064f\u0648\u0631\u064f",translation:"Tidak ada yang mereka tunggu-tunggu kecuali datangnya (azab) Allah bersama malaikat dalam naungan awan, sedangkan perkara (mereka) telah diputuskan. Dan kepada Allahlah segala perkara dikembalikan"},{id:211,text:"\u0633\u064e\u0644\u06e1 \u0628\u064e\u0646\u0650\u064a\u0653 \u0625\u0650\u0633\u06e1\u0631\u064e\u0640\u0670\u0653\u0621\u0650\u064a\u0644\u064e \u0643\u064e\u0645\u06e1 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0621\u064e\u0627\u064a\u064e\u0629\u0650\u06ed \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0629\u0656\u06d7 \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0628\u064e\u062f\u0651\u0650\u0644\u06e1 \u0646\u0650\u0639\u06e1\u0645\u064e\u0629\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0645\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u062a\u06e1\u0647\u064f \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0634\u064e\u062f\u0650\u064a\u062f\u064f \u0671\u0644\u06e1\u0639\u0650\u0642\u064e\u0627\u0628\u0650",translation:"Tanyakanlah kepada Bani Israil, berapa banyak bukti nyata yang telah Kami berikan kepada mereka. Barang siapa menukar nikmat Allah setelah (nikmat itu) datang kepadanya, maka sungguh, Allah sangat keras hukuman-Nya"},{id:212,text:"\u0632\u064f\u064a\u0651\u0650\u0646\u064e \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u064f \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0648\u064e\u064a\u064e\u0633\u06e1\u062e\u064e\u0631\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652\u06d8 \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u062a\u0651\u064e\u0642\u064e\u0648\u06e1\u0627\u0652 \u0641\u064e\u0648\u06e1\u0642\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0631\u06e1\u0632\u064f\u0642\u064f \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0628\u0650\u063a\u064e\u064a\u06e1\u0631\u0650 \u062d\u0650\u0633\u064e\u0627\u0628\u0656",translation:"Kehidupan dunia dijadikan terasa indah dalam pandangan orang-orang yang kafir, dan mereka menghina orang-orang yang beriman. Padahal orang-orang yang bertakwa itu berada di atas mereka pada hari Kiamat. Dan Allah memberi rezeki kepada orang yang Dia kehendaki tanpa perhitungan"},{id:213,text:"\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0623\u064f\u0645\u0651\u064e\u0629\u0657 \u0648\u064e\u0670\u062d\u0650\u062f\u064e\u0629\u0657 \u0641\u064e\u0628\u064e\u0639\u064e\u062b\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650\u0640\u06e7\u0646\u064e \u0645\u064f\u0628\u064e\u0634\u0651\u0650\u0631\u0650\u064a\u0646\u064e \u0648\u064e\u0645\u064f\u0646\u0630\u0650\u0631\u0650\u064a\u0646\u064e \u0648\u064e\u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0645\u064e\u0639\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0644\u0650\u064a\u064e\u062d\u06e1\u0643\u064f\u0645\u064e \u0628\u064e\u064a\u06e1\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0641\u0650\u064a\u0645\u064e\u0627 \u0671\u062e\u06e1\u062a\u064e\u0644\u064e\u0641\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0647\u0650\u06da \u0648\u064e\u0645\u064e\u0627 \u0671\u062e\u06e1\u062a\u064e\u0644\u064e\u0641\u064e \u0641\u0650\u064a\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0647\u064f \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0645\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u062a\u06e1\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u064f \u0628\u064e\u063a\u06e1\u064a\u064e\u06e2\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1\u06d6 \u0641\u064e\u0647\u064e\u062f\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0644\u0650\u0645\u064e\u0627 \u0671\u062e\u06e1\u062a\u064e\u0644\u064e\u0641\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0647\u0650 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0628\u0650\u0625\u0650\u0630\u06e1\u0646\u0650\u0647\u0650\u06e6\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0647\u06e1\u062f\u0650\u064a \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0670\u0637\u0656 \u0645\u0651\u064f\u0633\u06e1\u062a\u064e\u0642\u0650\u064a\u0645\u064d",translation:"Manusia itu (dahulunya) satu umat. Lalu Allah mengutus para nabi (untuk) menyampaikan kabar gembira dan peringatan. Dan diturunkan-Nya bersama mereka Kitab yang mengandung kebenaran, untuk memberi keputusan di antara manusia tentang perkara yang mereka perselisihkan. Dan yang berselisih hanyalah orang-orang yang telah diberi (Kitab), setelah bukti-bukti yang nyata sampai kepada mereka, karena kedengkian di antara mereka sendiri. Maka dengan kehendak-Nya, Allah memberi petunjuk kepada mereka yang beriman tentang kebenaran yang mereka perselisihkan. Allah memberi petunjuk kepada siapa yang Dia kehendaki ke jalan yang lurus"},{id:214,text:"\u0623\u064e\u0645\u06e1 \u062d\u064e\u0633\u0650\u0628\u06e1\u062a\u064f\u0645\u06e1 \u0623\u064e\u0646 \u062a\u064e\u062f\u06e1\u062e\u064f\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u064e \u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u064a\u064e\u0623\u06e1\u062a\u0650\u0643\u064f\u0645 \u0645\u0651\u064e\u062b\u064e\u0644\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062e\u064e\u0644\u064e\u0648\u06e1\u0627\u0652 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064f\u0645\u06d6 \u0645\u0651\u064e\u0633\u0651\u064e\u062a\u06e1\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0628\u064e\u0623\u06e1\u0633\u064e\u0627\u0653\u0621\u064f \u0648\u064e\u0671\u0644\u0636\u0651\u064e\u0631\u0651\u064e\u0627\u0653\u0621\u064f \u0648\u064e\u0632\u064f\u0644\u06e1\u0632\u0650\u0644\u064f\u0648\u0627\u0652 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0642\u064f\u0648\u0644\u064e \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064f \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0645\u064e\u0639\u064e\u0647\u064f\u06e5 \u0645\u064e\u062a\u064e\u0649\u0670 \u0646\u064e\u0635\u06e1\u0631\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d7 \u0623\u064e\u0644\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e \u0646\u064e\u0635\u06e1\u0631\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0642\u064e\u0631\u0650\u064a\u0628\u065e",translation:"Ataukah kamu mengira bahwa kamu akan masuk surga, padahal belum datang kepadamu (cobaan) seperti (yang dialami) orang-orang terdahulu sebelum kamu. Mereka ditimpa kemelaratan, penderitaan dan diguncang (dengan berbagai cobaan), sehingga Rasul dan orang-orang yang beriman bersamanya berkata, \"Kapankah datang pertolongan Allah?\" Ingatlah, sesungguhnya pertolongan Allah itu dekat"},{id:215,text:"\u064a\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u0645\u064e\u0627\u0630\u064e\u0627 \u064a\u064f\u0646\u0641\u0650\u0642\u064f\u0648\u0646\u064e\u06d6 \u0642\u064f\u0644\u06e1 \u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0641\u064e\u0642\u06e1\u062a\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u062e\u064e\u064a\u06e1\u0631\u0656 \u0641\u064e\u0644\u0650\u0644\u06e1\u0648\u064e\u0670\u0644\u0650\u062f\u064e\u064a\u06e1\u0646\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0642\u06e1\u0631\u064e\u0628\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u064a\u064e\u062a\u064e\u0670\u0645\u064e\u0649\u0670 \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u0633\u064e\u0670\u0643\u0650\u064a\u0646\u0650 \u0648\u064e\u0671\u0628\u06e1\u0646\u0650 \u0671\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u0650\u06d7 \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0641\u06e1\u0639\u064e\u0644\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1 \u062e\u064e\u064a\u06e1\u0631\u0656 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u0647\u0650\u06e6 \u0639\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Mereka bertanya kepadamu (Muhammad) tentang apa yang harus mereka infakkan. Katakanlah, \"Harta apa saja yang kamu infakkan, hendaknya diperuntukkan bagi kedua orang tua, kerabat, anak yatim, orang miskin dan orang yang dalam perjalanan.\" Dan kebaikan apa saja yang kamu kerjakan, maka sesungguhnya Allah Maha Mengetahui"},{id:216,text:"\u0643\u064f\u062a\u0650\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0642\u0650\u062a\u064e\u0627\u0644\u064f \u0648\u064e\u0647\u064f\u0648\u064e \u0643\u064f\u0631\u06e1\u0647\u065e \u0644\u0651\u064e\u0643\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0639\u064e\u0633\u064e\u0649\u0670\u0653 \u0623\u064e\u0646 \u062a\u064e\u0643\u06e1\u0631\u064e\u0647\u064f\u0648\u0627\u0652 \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627 \u0648\u064e\u0647\u064f\u0648\u064e \u062e\u064e\u064a\u06e1\u0631\u065e \u0644\u0651\u064e\u0643\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0639\u064e\u0633\u064e\u0649\u0670\u0653 \u0623\u064e\u0646 \u062a\u064f\u062d\u0650\u0628\u0651\u064f\u0648\u0627\u0652 \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627 \u0648\u064e\u0647\u064f\u0648\u064e \u0634\u064e\u0631\u0651\u065e \u0644\u0651\u064e\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Diwajibkan atas kamu berperang, padahal itu tidak menyenangkan bagimu. Tetapi boleh jadi kamu tidak menyenangi sesuatu, padahal itu baik bagimu, dan boleh jadi kamu menyukai sesuatu, padahal itu tidak baik bagimu. Allah mengetahui, sedang kamu tidak mengetahui"},{id:217,text:"\u064a\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u0639\u064e\u0646\u0650 \u0671\u0644\u0634\u0651\u064e\u0647\u06e1\u0631\u0650 \u0671\u0644\u06e1\u062d\u064e\u0631\u064e\u0627\u0645\u0650 \u0642\u0650\u062a\u064e\u0627\u0644\u0656 \u0641\u0650\u064a\u0647\u0650\u06d6 \u0642\u064f\u0644\u06e1 \u0642\u0650\u062a\u064e\u0627\u0644\u065e \u0641\u0650\u064a\u0647\u0650 \u0643\u064e\u0628\u0650\u064a\u0631\u065e\u06da \u0648\u064e\u0635\u064e\u062f\u0651\u064c \u0639\u064e\u0646 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0643\u064f\u0641\u06e1\u0631\u064f\u06e2 \u0628\u0650\u0647\u0650\u06e6 \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u0633\u06e1\u062c\u0650\u062f\u0650 \u0671\u0644\u06e1\u062d\u064e\u0631\u064e\u0627\u0645\u0650 \u0648\u064e\u0625\u0650\u062e\u06e1\u0631\u064e\u0627\u062c\u064f \u0623\u064e\u0647\u06e1\u0644\u0650\u0647\u0650\u06e6 \u0645\u0650\u0646\u06e1\u0647\u064f \u0623\u064e\u0643\u06e1\u0628\u064e\u0631\u064f \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0648\u064e\u0671\u0644\u06e1\u0641\u0650\u062a\u06e1\u0646\u064e\u0629\u064f \u0623\u064e\u0643\u06e1\u0628\u064e\u0631\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0642\u064e\u062a\u06e1\u0644\u0650\u06d7 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0632\u064e\u0627\u0644\u064f\u0648\u0646\u064e \u064a\u064f\u0642\u064e\u0670\u062a\u0650\u0644\u064f\u0648\u0646\u064e\u0643\u064f\u0645\u06e1 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0631\u064f\u062f\u0651\u064f\u0648\u0643\u064f\u0645\u06e1 \u0639\u064e\u0646 \u062f\u0650\u064a\u0646\u0650\u0643\u064f\u0645\u06e1 \u0625\u0650\u0646\u0650 \u0671\u0633\u06e1\u062a\u064e\u0637\u064e\u0670\u0639\u064f\u0648\u0627\u0652\u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0631\u06e1\u062a\u064e\u062f\u0650\u062f\u06e1 \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u0639\u064e\u0646 \u062f\u0650\u064a\u0646\u0650\u0647\u0650\u06e6 \u0641\u064e\u064a\u064e\u0645\u064f\u062a\u06e1 \u0648\u064e\u0647\u064f\u0648\u064e \u0643\u064e\u0627\u0641\u0650\u0631\u065e \u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u062d\u064e\u0628\u0650\u0637\u064e\u062a\u06e1 \u0623\u064e\u0639\u06e1\u0645\u064e\u0670\u0644\u064f\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0648\u064e\u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650\u06d6 \u0648\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650\u06d6 \u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u0670\u0644\u0650\u062f\u064f\u0648\u0646\u064e",translation:"Mereka bertanya kepadamu (Muhammad) tentang berperang pada bulan haram. Katakanlah, \"Berperang dalam bulan itu adalah (dosa) besar. Tetapi menghalangi (orang) dari jalan Allah, ingkar kepada-Nya, (menghalangi orang masuk) Masjidilharam, dan mengusir penduduk dari sekitarnya, lebih besar (dosanya) dalam pandangan Allah. Sedangkan fitnah74) lebih kejam daripada pembunuhan. Mereka tidak akan berhenti memerangi kamu sampai kamu murtad (keluar) dari agamamu, jika mereka sanggup. Barang siapa yang murtad di antara kamu dari agamanya, lalu dia mati dalam kekafiran, maka mereka itu sia-sia amalnya di dunia dan di akhirat, dan mereka itulah penghuni neraka, mereka kekal di dalamnya"},{id:218,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064e\u0627\u062c\u064e\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u062c\u064e\u0670\u0647\u064e\u062f\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u064a\u064e\u0631\u06e1\u062c\u064f\u0648\u0646\u064e \u0631\u064e\u062d\u06e1\u0645\u064e\u062a\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u065e",translation:"Sesungguhnya orang-orang yang beriman, dan orang-orang yang berhijrah dan berjihad di jalan Allah, mereka itulah yang mengharapkan rahmat Allah. Allah Maha Pengampun, Maha Penyayang"},{id:219,text:"\u06de\u064a\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u0639\u064e\u0646\u0650 \u0671\u0644\u06e1\u062e\u064e\u0645\u06e1\u0631\u0650 \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u064a\u06e1\u0633\u0650\u0631\u0650\u06d6 \u0642\u064f\u0644\u06e1 \u0641\u0650\u064a\u0647\u0650\u0645\u064e\u0627\u0653 \u0625\u0650\u062b\u06e1\u0645\u065e \u0643\u064e\u0628\u0650\u064a\u0631\u065e \u0648\u064e\u0645\u064e\u0646\u064e\u0670\u0641\u0650\u0639\u064f \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0625\u0650\u062b\u06e1\u0645\u064f\u0647\u064f\u0645\u064e\u0627\u0653 \u0623\u064e\u0643\u06e1\u0628\u064e\u0631\u064f \u0645\u0650\u0646 \u0646\u0651\u064e\u0641\u06e1\u0639\u0650\u0647\u0650\u0645\u064e\u0627\u06d7 \u0648\u064e\u064a\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u0645\u064e\u0627\u0630\u064e\u0627 \u064a\u064f\u0646\u0641\u0650\u0642\u064f\u0648\u0646\u064e\u06d6 \u0642\u064f\u0644\u0650 \u0671\u0644\u06e1\u0639\u064e\u0641\u06e1\u0648\u064e\u06d7 \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0623\u0653\u064a\u064e\u0670\u062a\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u062a\u064e\u0641\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Mereka menanyakan kepadamu (Muhammad) tentang khamar75) dan judi. Katakanlah, \"Pada keduanya terdapat dosa besar dan beberapa manfaat bagi manusia. Tetapi dosanya lebih besar daripada manfaatnya.\" Dan mereka menanyakan kepadamu (tentang) apa yang (harus) mereka infakkan. Katakanlah, \"Kelebihan (dari apa yang diperlukan).\" Demikianlah Allah menerangkan ayat-ayat-Nya kepadamu agar kamu memikirkan"},{id:220,text:"\u0641\u0650\u064a \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0648\u064e\u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650\u06d7 \u0648\u064e\u064a\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u0639\u064e\u0646\u0650 \u0671\u0644\u06e1\u064a\u064e\u062a\u064e\u0670\u0645\u064e\u0649\u0670\u06d6 \u0642\u064f\u0644\u06e1 \u0625\u0650\u0635\u06e1\u0644\u064e\u0627\u062d\u065e \u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u062e\u064e\u064a\u06e1\u0631\u065e\u06d6 \u0648\u064e\u0625\u0650\u0646 \u062a\u064f\u062e\u064e\u0627\u0644\u0650\u0637\u064f\u0648\u0647\u064f\u0645\u06e1 \u0641\u064e\u0625\u0650\u062e\u06e1\u0648\u064e\u0670\u0646\u064f\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0671\u0644\u06e1\u0645\u064f\u0641\u06e1\u0633\u0650\u062f\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0635\u06e1\u0644\u0650\u062d\u0650\u06da \u0648\u064e\u0644\u064e\u0648\u06e1 \u0634\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0623\u064e\u0639\u06e1\u0646\u064e\u062a\u064e\u0643\u064f\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0632\u0650\u064a\u0632\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u065e",translation:"tentang dunia dan akhirat. Mereka menanyakan kepadamu (Muhammad) tentang anak-anak yatim. Katakanlah, \"Memperbaiki keadaan mereka adalah baik!\" Dan jika kamu mempergauli mereka, maka mereka adalah saudara-saudaramu. Allah mengetahui orang yang berbuat kerusakan dan yang berbuat kebaikan. Dan jika Allah menghendaki, niscaya Dia datangkan kesulitan kepadamu. Sungguh, Allah Mahaperkasa, Mahabijaksana"},{id:221,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0646\u0643\u0650\u062d\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0645\u064f\u0634\u06e1\u0631\u0650\u0643\u064e\u0670\u062a\u0650 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u0651\u064e\u06da \u0648\u064e\u0644\u064e\u0623\u064e\u0645\u064e\u0629\u065e \u0645\u0651\u064f\u0624\u06e1\u0645\u0650\u0646\u064e\u0629\u064c \u062e\u064e\u064a\u06e1\u0631\u065e \u0645\u0651\u0650\u0646 \u0645\u0651\u064f\u0634\u06e1\u0631\u0650\u0643\u064e\u0629\u0656 \u0648\u064e\u0644\u064e\u0648\u06e1 \u0623\u064e\u0639\u06e1\u062c\u064e\u0628\u064e\u062a\u06e1\u0643\u064f\u0645\u06e1\u06d7 \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0646\u0643\u0650\u062d\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0645\u064f\u0634\u06e1\u0631\u0650\u0643\u0650\u064a\u0646\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0627\u0652\u06da \u0648\u064e\u0644\u064e\u0639\u064e\u0628\u06e1\u062f\u065e \u0645\u0651\u064f\u0624\u06e1\u0645\u0650\u0646\u064c \u062e\u064e\u064a\u06e1\u0631\u065e \u0645\u0651\u0650\u0646 \u0645\u0651\u064f\u0634\u06e1\u0631\u0650\u0643\u0656 \u0648\u064e\u0644\u064e\u0648\u06e1 \u0623\u064e\u0639\u06e1\u062c\u064e\u0628\u064e\u0643\u064f\u0645\u06e1\u06d7 \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u064a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650\u06d6 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u062f\u06e1\u0639\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u063a\u06e1\u0641\u0650\u0631\u064e\u0629\u0650 \u0628\u0650\u0625\u0650\u0630\u06e1\u0646\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064f \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0647\u0650\u06e6 \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan janganlah kamu nikahi perempuan musyrik, sebelum mereka beriman. Sungguh, hamba sahaya perempuan yang beriman lebih baik daripada perempuan musyrik meskipun dia menarik hatimu. Dan janganlah kamu nikahkan orang (laki-laki) musyrik (dengan perempuan yang beriman) sebelum mereka beriman. Sungguh, hamba sahaya laki-laki yang beriman lebih baik daripada laki-laki musyrik meskipun dia menarik hatimu. Mereka mengajak ke neraka, sedangkan Allah mengajak ke surga dan ampunan dengan izin-Nya. (Allah) menerangkan ayat-ayat-Nya kepada manusia agar mereka mengambil pelajaran"},{id:222,text:"\u0648\u064e\u064a\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u0639\u064e\u0646\u0650 \u0671\u0644\u06e1\u0645\u064e\u062d\u0650\u064a\u0636\u0650\u06d6 \u0642\u064f\u0644\u06e1 \u0647\u064f\u0648\u064e \u0623\u064e\u0630\u0657\u0649 \u0641\u064e\u0671\u0639\u06e1\u062a\u064e\u0632\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0653\u0621\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0645\u064e\u062d\u0650\u064a\u0636\u0650 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u06e1\u0631\u064e\u0628\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0637\u06e1\u0647\u064f\u0631\u06e1\u0646\u064e\u06d6 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u062a\u064e\u0637\u064e\u0647\u0651\u064e\u0631\u06e1\u0646\u064e \u0641\u064e\u0623\u06e1\u062a\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0645\u0650\u0646\u06e1 \u062d\u064e\u064a\u06e1\u062b\u064f \u0623\u064e\u0645\u064e\u0631\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0671\u0644\u062a\u0651\u064e\u0648\u0651\u064e\u0640\u0670\u0628\u0650\u064a\u0646\u064e \u0648\u064e\u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0671\u0644\u06e1\u0645\u064f\u062a\u064e\u0637\u064e\u0647\u0651\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan mereka menanyakan kepadamu (Muhammad) tentang haid. Katakanlah, \"Itu adalah gangguan (sesuatu yang kotor).\" Karena itu jauhilah76) istri pada waktu haid; dan jangan kamu dekati mereka sebelum mereka suci.77) Apabila mereka telah suci, campurilah mereka sesuai dengan (ketentuan) yang diperintahkan Allah kepadamu. Sungguh, Allah menyukai orang yang tobat dan menyukai orang yang menyucikan diri"},{id:223,text:"\u0646\u0650\u0633\u064e\u0627\u0653\u0624\u064f\u0643\u064f\u0645\u06e1 \u062d\u064e\u0631\u06e1\u062b\u065e \u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u0641\u064e\u0623\u06e1\u062a\u064f\u0648\u0627\u0652 \u062d\u064e\u0631\u06e1\u062b\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u0634\u0650\u0626\u06e1\u062a\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0642\u064e\u062f\u0651\u0650\u0645\u064f\u0648\u0627\u0652 \u0644\u0650\u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0671\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e\u0643\u064f\u0645 \u0645\u0651\u064f\u0644\u064e\u0670\u0642\u064f\u0648\u0647\u064f\u06d7 \u0648\u064e\u0628\u064e\u0634\u0651\u0650\u0631\u0650 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Istri-istrimu adalah ladang bagimu, maka datangilah ladangmu itu kapan saja dengan cara yang kamu sukai. Dan utamakanlah (yang baik) untuk dirimu. Bertakwalah kepada Allah dan ketahuilah bahwa kamu (kelak) akan menemui-Nya. Dan sampaikanlah kabar gembira kepada orang yang beriman"},{id:224,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062c\u06e1\u0639\u064e\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064f\u0631\u06e1\u0636\u064e\u0629\u0657 \u0644\u0651\u0650\u0623\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u0650\u0643\u064f\u0645\u06e1 \u0623\u064e\u0646 \u062a\u064e\u0628\u064e\u0631\u0651\u064f\u0648\u0627\u0652 \u0648\u064e\u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0648\u064e\u062a\u064f\u0635\u06e1\u0644\u0650\u062d\u064f\u0648\u0627\u0652 \u0628\u064e\u064a\u06e1\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0633\u064e\u0645\u0650\u064a\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Dan janganlah kamu jadikan (nama) Allah dalam sumpahmu sebagai penghalang untuk berbuat kebajikan, bertakwa dan menciptakan kedamaian di antara manusia.78) Allah Maha Mendengar, Maha Mengetahui"},{id:225,text:"\u0644\u0651\u064e\u0627 \u064a\u064f\u0624\u064e\u0627\u062e\u0650\u0630\u064f\u0643\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u063a\u06e1\u0648\u0650 \u0641\u0650\u064a\u0653 \u0623\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u064a\u064f\u0624\u064e\u0627\u062e\u0650\u0630\u064f\u0643\u064f\u0645 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064e\u062a\u06e1 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0643\u064f\u0645\u06e1\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u062d\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Allah tidak menghukum kamu karena sumpahmu yang tidak kamu sengaja, tetapi Dia menghukum kamu karena niat yang terkandung dalam hatimu. Allah Maha Pengampun, Maha Penyantun"},{id:226,text:"\u0644\u0651\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0624\u06e1\u0644\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u0646\u0651\u0650\u0633\u064e\u0627\u0653\u0626\u0650\u0647\u0650\u0645\u06e1 \u062a\u064e\u0631\u064e\u0628\u0651\u064f\u0635\u064f \u0623\u064e\u0631\u06e1\u0628\u064e\u0639\u064e\u0629\u0650 \u0623\u064e\u0634\u06e1\u0647\u064f\u0631\u0656\u06d6 \u0641\u064e\u0625\u0650\u0646 \u0641\u064e\u0627\u0653\u0621\u064f\u0648 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u065e",translation:"(Bagi orang yang meng-ila` istrinya80) harus menunggu empat bulan. Kemudian jika mereka kembali (kepada istrinya), maka sungguh, Allah Maha Pengampun, Maha Penyayang"},{id:227,text:"\u0648\u064e\u0625\u0650\u0646\u06e1 \u0639\u064e\u0632\u064e\u0645\u064f\u0648\u0627\u0652 \u0671\u0644\u0637\u0651\u064e\u0644\u064e\u0670\u0642\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0633\u064e\u0645\u0650\u064a\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Dan jika mereka berketetapan hati hendak menceraikan, maka sungguh, Allah Maha Mendengar, Maha Mengetahui"},{id:228,text:"\u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0637\u064e\u0644\u0651\u064e\u0642\u064e\u0670\u062a\u064f \u064a\u064e\u062a\u064e\u0631\u064e\u0628\u0651\u064e\u0635\u06e1\u0646\u064e \u0628\u0650\u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0646\u0651\u064e \u062b\u064e\u0644\u064e\u0670\u062b\u064e\u0629\u064e \u0642\u064f\u0631\u064f\u0648\u0653\u0621\u0656\u06da \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062d\u0650\u0644\u0651\u064f \u0644\u064e\u0647\u064f\u0646\u0651\u064e \u0623\u064e\u0646 \u064a\u064e\u0643\u06e1\u062a\u064f\u0645\u06e1\u0646\u064e \u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u0650\u064a\u0653 \u0623\u064e\u0631\u06e1\u062d\u064e\u0627\u0645\u0650\u0647\u0650\u0646\u0651\u064e \u0625\u0650\u0646 \u0643\u064f\u0646\u0651\u064e \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u0651\u064e \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u0650\u06da \u0648\u064e\u0628\u064f\u0639\u064f\u0648\u0644\u064e\u062a\u064f\u0647\u064f\u0646\u0651\u064e \u0623\u064e\u062d\u064e\u0642\u0651\u064f \u0628\u0650\u0631\u064e\u062f\u0651\u0650\u0647\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0625\u0650\u0646\u06e1 \u0623\u064e\u0631\u064e\u0627\u062f\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0635\u06e1\u0644\u064e\u0670\u062d\u0657\u0627\u06da \u0648\u064e\u0644\u064e\u0647\u064f\u0646\u0651\u064e \u0645\u0650\u062b\u06e1\u0644\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0646\u0651\u064e \u0628\u0650\u0671\u0644\u06e1\u0645\u064e\u0639\u06e1\u0631\u064f\u0648\u0641\u0650\u06da \u0648\u064e\u0644\u0650\u0644\u0631\u0651\u0650\u062c\u064e\u0627\u0644\u0650 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0646\u0651\u064e \u062f\u064e\u0631\u064e\u062c\u064e\u0629\u065e\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0632\u0650\u064a\u0632\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u064c",translation:"Dan para istri yang diceraikan (wajib) menahan diri mereka (menunggu) tiga kali quru`.81) Mereka tidak boleh menyembunyikan apa yang diciptakan Allah dalam rahim mereka, jika mereka beriman kepada Allah dan hari akhir. Dan para suami mereka lebih berhak kembali kepada mereka dalam (masa) itu, jika mereka menghendaki perbaikan. Dan mereka (para perempuan) mempunyai hak seimbang dengan kewajibannya menurut cara yang patut. Tetapi para suami, mempunyai kelebihan di atas mereka.82) Allah Mahaperkasa, Mahabijaksana"},{id:229,text:"\u0671\u0644\u0637\u0651\u064e\u0644\u064e\u0670\u0642\u064f \u0645\u064e\u0631\u0651\u064e\u062a\u064e\u0627\u0646\u0650\u06d6 \u0641\u064e\u0625\u0650\u0645\u06e1\u0633\u064e\u0627\u0643\u064f\u06e2 \u0628\u0650\u0645\u064e\u0639\u06e1\u0631\u064f\u0648\u0641\u064d \u0623\u064e\u0648\u06e1 \u062a\u064e\u0633\u06e1\u0631\u0650\u064a\u062d\u064f\u06e2 \u0628\u0650\u0625\u0650\u062d\u06e1\u0633\u064e\u0670\u0646\u0656\u06d7 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062d\u0650\u0644\u0651\u064f \u0644\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u0646 \u062a\u064e\u0623\u06e1\u062e\u064f\u0630\u064f\u0648\u0627\u0652 \u0645\u0650\u0645\u0651\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u062a\u064f\u0645\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0634\u064e\u064a\u06e1\u0640\u0654\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u064a\u064e\u062e\u064e\u0627\u0641\u064e\u0627\u0653 \u0623\u064e\u0644\u0651\u064e\u0627 \u064a\u064f\u0642\u0650\u064a\u0645\u064e\u0627 \u062d\u064f\u062f\u064f\u0648\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0641\u064e\u0625\u0650\u0646\u06e1 \u062e\u0650\u0641\u06e1\u062a\u064f\u0645\u06e1 \u0623\u064e\u0644\u0651\u064e\u0627 \u064a\u064f\u0642\u0650\u064a\u0645\u064e\u0627 \u062d\u064f\u062f\u064f\u0648\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0644\u064e\u0627 \u062c\u064f\u0646\u064e\u0627\u062d\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u064e\u0627 \u0641\u0650\u064a\u0645\u064e\u0627 \u0671\u0641\u06e1\u062a\u064e\u062f\u064e\u062a\u06e1 \u0628\u0650\u0647\u0650\u06e6\u06d7 \u062a\u0650\u0644\u06e1\u0643\u064e \u062d\u064f\u062f\u064f\u0648\u062f\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u062a\u064e\u062f\u064f\u0648\u0647\u064e\u0627\u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u062a\u064e\u0639\u064e\u062f\u0651\u064e \u062d\u064f\u062f\u064f\u0648\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Talak (yang dapat dirujuk) itu dua kali. (Setelah itu suami dapat) menahan dengan baik, atau melepaskan dengan baik. Tidak halal bagi kamu mengambil kembali sesuatu yang telah kamu berikan kepada mereka, kecuali keduanya (suami dan istri) khawatir tidak mampu menjalankan hukum-hukum Allah. Jika kamu (wali) Khawatir bahwa keduanya tidak mampu menjalankan hukum Allah, maka keduanya tidak berdosa atas bayaran yang (harus) diberikan (oleh istri) untuk menebus dirinya.83) Itulah hukum-hukum Allah, maka janganlah kamu melanggarnya. Barangsiapa melanggar hukum-hukum Allah, mereka itulah orang-orang yang zalim"},{id:230,text:"\u0641\u064e\u0625\u0650\u0646 \u0637\u064e\u0644\u0651\u064e\u0642\u064e\u0647\u064e\u0627 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062d\u0650\u0644\u0651\u064f \u0644\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u064f \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062a\u064e\u0646\u0643\u0650\u062d\u064e \u0632\u064e\u0648\u06e1\u062c\u064b\u0627 \u063a\u064e\u064a\u06e1\u0631\u064e\u0647\u064f\u06e5\u06d7 \u0641\u064e\u0625\u0650\u0646 \u0637\u064e\u0644\u0651\u064e\u0642\u064e\u0647\u064e\u0627 \u0641\u064e\u0644\u064e\u0627 \u062c\u064f\u0646\u064e\u0627\u062d\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u064e\u0627\u0653 \u0623\u064e\u0646 \u064a\u064e\u062a\u064e\u0631\u064e\u0627\u062c\u064e\u0639\u064e\u0627\u0653 \u0625\u0650\u0646 \u0638\u064e\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u064a\u064f\u0642\u0650\u064a\u0645\u064e\u0627 \u062d\u064f\u062f\u064f\u0648\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d7 \u0648\u064e\u062a\u0650\u0644\u06e1\u0643\u064e \u062d\u064f\u062f\u064f\u0648\u062f\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064f\u0647\u064e\u0627 \u0644\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Kemudian jika dia menceraikannya (setelah talak yang kedua), maka perempuan itu tidak halal lagi baginya sebelum dia menikah dengan suami yang lain. Kemudian jika suami yang lain itu menceraikannya, maka tidak ada dosa bagi keduanya (suami pertama dan bekas istri) untuk menikah kembali jika keduanya berpendapat akan dapat menjalankan hukum-hukum Allah. Itulah ketentuan-ketentuan Allah yang diterangkan-Nya kepada orang-orang yang berpengetahuan"},{id:231,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0637\u064e\u0644\u0651\u064e\u0642\u06e1\u062a\u064f\u0645\u064f \u0671\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0653\u0621\u064e \u0641\u064e\u0628\u064e\u0644\u064e\u063a\u06e1\u0646\u064e \u0623\u064e\u062c\u064e\u0644\u064e\u0647\u064f\u0646\u0651\u064e \u0641\u064e\u0623\u064e\u0645\u06e1\u0633\u0650\u0643\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0628\u0650\u0645\u064e\u0639\u06e1\u0631\u064f\u0648\u0641\u064d \u0623\u064e\u0648\u06e1 \u0633\u064e\u0631\u0651\u0650\u062d\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0628\u0650\u0645\u064e\u0639\u06e1\u0631\u064f\u0648\u0641\u0656\u06da \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0645\u06e1\u0633\u0650\u0643\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0636\u0650\u0631\u064e\u0627\u0631\u0657\u0627 \u0644\u0651\u0650\u062a\u064e\u0639\u06e1\u062a\u064e\u062f\u064f\u0648\u0627\u0652\u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0641\u06e1\u0639\u064e\u0644\u06e1 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u0642\u064e\u062f\u06e1 \u0638\u064e\u0644\u064e\u0645\u064e \u0646\u064e\u0641\u06e1\u0633\u064e\u0647\u064f\u06e5\u06da \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0653\u0627\u0652 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0647\u064f\u0632\u064f\u0648\u0657\u0627\u06da \u0648\u064e\u0671\u0630\u06e1\u0643\u064f\u0631\u064f\u0648\u0627\u0652 \u0646\u0650\u0639\u06e1\u0645\u064e\u062a\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0648\u064e\u0671\u0644\u06e1\u062d\u0650\u0643\u06e1\u0645\u064e\u0629\u0650 \u064a\u064e\u0639\u0650\u0638\u064f\u0643\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6\u06da \u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0671\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Dan apabila kamu menceraikan istri-istri (kamu), lalu sampai (akhir) idahnya,84) maka tahanlah mereka dengan cara yang baik, atau ceraikanlah mereka dengan cara yang baik (pula). Dan janganlah kamu tahan mereka dengan maksud jahat untuk menzalimi mereka. Barang siapa melakukan demikian, maka dia telah menzalimi dirinya sendiri. Dan janganlah kamu jadikan ayat-ayat Allah sebagai bahan ejekan. Ingatlah nikmat Allah kepada kamu, dan apa yang telah diturunkan Allah kepada kamu yaitu kitab (Alquran) dan Hikmah (Sunah), untuk memberi pengajaran kepadamu. Dan bertakwalah kepada Allah dan ketahuilah bahwa Allah Maha Mengetahui segala sesuatu"},{id:232,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0637\u064e\u0644\u0651\u064e\u0642\u06e1\u062a\u064f\u0645\u064f \u0671\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0653\u0621\u064e \u0641\u064e\u0628\u064e\u0644\u064e\u063a\u06e1\u0646\u064e \u0623\u064e\u062c\u064e\u0644\u064e\u0647\u064f\u0646\u0651\u064e \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u0636\u064f\u0644\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0623\u064e\u0646 \u064a\u064e\u0646\u0643\u0650\u062d\u06e1\u0646\u064e \u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u064e\u0647\u064f\u0646\u0651\u064e \u0625\u0650\u0630\u064e\u0627 \u062a\u064e\u0631\u064e\u0670\u0636\u064e\u0648\u06e1\u0627\u0652 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0645\u064e\u0639\u06e1\u0631\u064f\u0648\u0641\u0650\u06d7 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064f\u0648\u0639\u064e\u0638\u064f \u0628\u0650\u0647\u0650\u06e6 \u0645\u064e\u0646 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u0650\u06d7 \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u06e1 \u0623\u064e\u0632\u06e1\u0643\u064e\u0649\u0670 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0637\u06e1\u0647\u064e\u0631\u064f\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan apabila kamu menceraikan istri-istri (kamu), lalu sampai idahnya, maka jangan kamu halangi mereka menikah (lagi) dengan calon suaminya,85) apabila telah terjalin kecocokan di antara mereka dengan cara yang baik. Itulah yang dinasihatkan kepada orang-orang di antara kamu yang beriman kepada Allah dan hari akhir. Itu lebih suci bagimu dan lebih bersih. Dan Allah mengetahui, sedangkan kamu tidak mengetahui"},{id:233,text:"\u06de\u0648\u064e\u0671\u0644\u06e1\u0648\u064e\u0670\u0644\u0650\u062f\u064e\u0670\u062a\u064f \u064a\u064f\u0631\u06e1\u0636\u0650\u0639\u06e1\u0646\u064e \u0623\u064e\u0648\u06e1\u0644\u064e\u0670\u062f\u064e\u0647\u064f\u0646\u0651\u064e \u062d\u064e\u0648\u06e1\u0644\u064e\u064a\u06e1\u0646\u0650 \u0643\u064e\u0627\u0645\u0650\u0644\u064e\u064a\u06e1\u0646\u0650\u06d6 \u0644\u0650\u0645\u064e\u0646\u06e1 \u0623\u064e\u0631\u064e\u0627\u062f\u064e \u0623\u064e\u0646 \u064a\u064f\u062a\u0650\u0645\u0651\u064e \u0671\u0644\u0631\u0651\u064e\u0636\u064e\u0627\u0639\u064e\u0629\u064e\u06da \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u0644\u064f\u0648\u062f\u0650 \u0644\u064e\u0647\u064f\u06e5 \u0631\u0650\u0632\u06e1\u0642\u064f\u0647\u064f\u0646\u0651\u064e \u0648\u064e\u0643\u0650\u0633\u06e1\u0648\u064e\u062a\u064f\u0647\u064f\u0646\u0651\u064e \u0628\u0650\u0671\u0644\u06e1\u0645\u064e\u0639\u06e1\u0631\u064f\u0648\u0641\u0650\u06da \u0644\u064e\u0627 \u062a\u064f\u0643\u064e\u0644\u0651\u064e\u0641\u064f \u0646\u064e\u0641\u06e1\u0633\u064c \u0625\u0650\u0644\u0651\u064e\u0627 \u0648\u064f\u0633\u06e1\u0639\u064e\u0647\u064e\u0627\u06da \u0644\u064e\u0627 \u062a\u064f\u0636\u064e\u0627\u0653\u0631\u0651\u064e \u0648\u064e\u0670\u0644\u0650\u062f\u064e\u0629\u064f\u06e2 \u0628\u0650\u0648\u064e\u0644\u064e\u062f\u0650\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u0645\u064e\u0648\u06e1\u0644\u064f\u0648\u062f\u065e \u0644\u0651\u064e\u0647\u064f\u06e5 \u0628\u0650\u0648\u064e\u0644\u064e\u062f\u0650\u0647\u0650\u06e6\u06da \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0648\u064e\u0627\u0631\u0650\u062b\u0650 \u0645\u0650\u062b\u06e1\u0644\u064f \u0630\u064e\u0670\u0644\u0650\u0643\u064e\u06d7 \u0641\u064e\u0625\u0650\u0646\u06e1 \u0623\u064e\u0631\u064e\u0627\u062f\u064e\u0627 \u0641\u0650\u0635\u064e\u0627\u0644\u064b\u0627 \u0639\u064e\u0646 \u062a\u064e\u0631\u064e\u0627\u0636\u0656 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u064e\u0627 \u0648\u064e\u062a\u064e\u0634\u064e\u0627\u0648\u064f\u0631\u0656 \u0641\u064e\u0644\u064e\u0627 \u062c\u064f\u0646\u064e\u0627\u062d\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u064e\u0627\u06d7 \u0648\u064e\u0625\u0650\u0646\u06e1 \u0623\u064e\u0631\u064e\u062f\u062a\u0651\u064f\u0645\u06e1 \u0623\u064e\u0646 \u062a\u064e\u0633\u06e1\u062a\u064e\u0631\u06e1\u0636\u0650\u0639\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0648\u06e1\u0644\u064e\u0670\u062f\u064e\u0643\u064f\u0645\u06e1 \u0641\u064e\u0644\u064e\u0627 \u062c\u064f\u0646\u064e\u0627\u062d\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0625\u0650\u0630\u064e\u0627 \u0633\u064e\u0644\u0651\u064e\u0645\u06e1\u062a\u064f\u0645 \u0645\u0651\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u062a\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0645\u064e\u0639\u06e1\u0631\u064f\u0648\u0641\u0650\u06d7 \u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0671\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0628\u064e\u0635\u0650\u064a\u0631\u065e",translation:"Dan ibu-ibu hendaklah menyusui anak-anaknya selama dua tahun penuh, bagi yang ingin menyusui secara sempurna. Dan kewajiban ayah menanggung nafkah dan pakaian mereka dengan cara yang patut. Seseorang tidak dibebani lebih dari kesanggupannya. Janganlah seorang ibu menderita karena anaknya dan jangan pula seorang ayah (menderita) karena anaknya. Ahli waris pun (berkewajiban) seperti itu pula. Apabila keduanya ingin menyapih dengan persetujuan dan permusyawaratan antara keduanya, maka tidak ada dosa atas keduanya. Dan jika kamu ingin menyusukan anakmu kepada orang lain, maka tidak ada dosa bagimu memberikan bayaran dengan cara yang patut. Bertakwalah kepada Allah dan ketahuilah bahwa Allah Maha Melihat apa yang kamu kerjakan"},{id:234,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u062a\u064e\u0648\u064e\u0641\u0651\u064e\u0648\u06e1\u0646\u064e \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u0648\u064e\u064a\u064e\u0630\u064e\u0631\u064f\u0648\u0646\u064e \u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u0657\u0627 \u064a\u064e\u062a\u064e\u0631\u064e\u0628\u0651\u064e\u0635\u06e1\u0646\u064e \u0628\u0650\u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0646\u0651\u064e \u0623\u064e\u0631\u06e1\u0628\u064e\u0639\u064e\u0629\u064e \u0623\u064e\u0634\u06e1\u0647\u064f\u0631\u0656 \u0648\u064e\u0639\u064e\u0634\u06e1\u0631\u0657\u0627\u06d6 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0628\u064e\u0644\u064e\u063a\u06e1\u0646\u064e \u0623\u064e\u062c\u064e\u0644\u064e\u0647\u064f\u0646\u0651\u064e \u0641\u064e\u0644\u064e\u0627 \u062c\u064f\u0646\u064e\u0627\u062d\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a\u0645\u064e\u0627 \u0641\u064e\u0639\u064e\u0644\u06e1\u0646\u064e \u0641\u0650\u064a\u0653 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0646\u0651\u064e \u0628\u0650\u0671\u0644\u06e1\u0645\u064e\u0639\u06e1\u0631\u064f\u0648\u0641\u0650\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u062e\u064e\u0628\u0650\u064a\u0631\u065e",translation:"Dan Orang-orang yang mati di antara kamu serta meninggalkan istri-istri hendaklah mereka (istri-istri) menunggu empat bulan sepuluh hari. Kemudian apabila telah sampai (akhir) idah mereka, maka tidak ada dosa bagimu mengenai apa yang mereka lakukan terhadap diri mereka 86) menurut cara yang patut. Dan Allah Maha Mengetahui apa yang kamu kerjakan"},{id:235,text:"\u0648\u064e\u0644\u064e\u0627 \u062c\u064f\u0646\u064e\u0627\u062d\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a\u0645\u064e\u0627 \u0639\u064e\u0631\u0651\u064e\u0636\u06e1\u062a\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6 \u0645\u0650\u0646\u06e1 \u062e\u0650\u0637\u06e1\u0628\u064e\u0629\u0650 \u0671\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0653\u0621\u0650 \u0623\u064e\u0648\u06e1 \u0623\u064e\u0643\u06e1\u0646\u064e\u0646\u062a\u064f\u0645\u06e1 \u0641\u0650\u064a\u0653 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u06e1\u06da \u0639\u064e\u0644\u0650\u0645\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0633\u064e\u062a\u064e\u0630\u06e1\u0643\u064f\u0631\u064f\u0648\u0646\u064e\u0647\u064f\u0646\u0651\u064e \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u0644\u0651\u064e\u0627 \u062a\u064f\u0648\u064e\u0627\u0639\u0650\u062f\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0633\u0650\u0631\u0651\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627\u0652 \u0642\u064e\u0648\u06e1\u0644\u0657\u0627 \u0645\u0651\u064e\u0639\u06e1\u0631\u064f\u0648\u0641\u0657\u0627\u06da \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u0632\u0650\u0645\u064f\u0648\u0627\u0652 \u0639\u064f\u0642\u06e1\u062f\u064e\u0629\u064e \u0671\u0644\u0646\u0651\u0650\u0643\u064e\u0627\u062d\u0650 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0628\u06e1\u0644\u064f\u063a\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064f \u0623\u064e\u062c\u064e\u0644\u064e\u0647\u064f\u06e5\u06da \u0648\u064e\u0671\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0641\u0650\u064a\u0653 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u06e1 \u0641\u064e\u0671\u062d\u06e1\u0630\u064e\u0631\u064f\u0648\u0647\u064f\u06da \u0648\u064e\u0671\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u062d\u064e\u0644\u0650\u064a\u0645\u065e",translation:"(Dan tidak ada dosa bagimu meminang perempuan-perempuan itu dengan sindiran87) atau kamu sembunyikan (keinginanmu) dalam hati. Allah mengetahui bahwa kamu akan menyebut-nyebut kepada mereka. Tetapi janganlah kamu membuat perjanjian (untuk menikah) dengan mereka secara rahasia, kecuali sekedar mengucapkan kata-kata yang baik.88) Dan janganlah kamu menetapkan akad nikah, sebelum habis masa idahnya. Ketahuilah bahwa Allah mengetahui apa yang ada dalam hatimu, maka takutlah kepada-Nya. Dan ketahuilah bahwa Allah Maha Pengampun, Maha Penyantun"},{id:236,text:"\u0644\u0651\u064e\u0627 \u062c\u064f\u0646\u064e\u0627\u062d\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0625\u0650\u0646 \u0637\u064e\u0644\u0651\u064e\u0642\u06e1\u062a\u064f\u0645\u064f \u0671\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0653\u0621\u064e \u0645\u064e\u0627 \u0644\u064e\u0645\u06e1 \u062a\u064e\u0645\u064e\u0633\u0651\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0623\u064e\u0648\u06e1 \u062a\u064e\u0641\u06e1\u0631\u0650\u0636\u064f\u0648\u0627\u0652 \u0644\u064e\u0647\u064f\u0646\u0651\u064e \u0641\u064e\u0631\u0650\u064a\u0636\u064e\u0629\u0657\u06da \u0648\u064e\u0645\u064e\u062a\u0651\u0650\u0639\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0645\u064f\u0648\u0633\u0650\u0639\u0650 \u0642\u064e\u062f\u064e\u0631\u064f\u0647\u064f\u06e5 \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0645\u064f\u0642\u06e1\u062a\u0650\u0631\u0650 \u0642\u064e\u062f\u064e\u0631\u064f\u0647\u064f\u06e5 \u0645\u064e\u062a\u064e\u0670\u0639\u064e\u06e2\u0627 \u0628\u0650\u0671\u0644\u06e1\u0645\u064e\u0639\u06e1\u0631\u064f\u0648\u0641\u0650\u06d6 \u062d\u064e\u0642\u0651\u064b\u0627 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0645\u064f\u062d\u06e1\u0633\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Tidak ada dosa bagimu jika kamu menceraikan istri-istri kamu yang belum kamu sentuh (campuri) atau belum kamu tentukan maharnya. Dan hendaklah kamu beri mereka mut'ah,89) bagi yang mampu menurut kemampuannya dan bagi yang tidak mampu menurut kesanggupannya, yaitu pemberian dengan cara yang patut, yang merupakan kewajiban bagi orang-orang yang berbuat kebaikan"},{id:237,text:"\u0648\u064e\u0625\u0650\u0646 \u0637\u064e\u0644\u0651\u064e\u0642\u06e1\u062a\u064f\u0645\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650 \u0623\u064e\u0646 \u062a\u064e\u0645\u064e\u0633\u0651\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0648\u064e\u0642\u064e\u062f\u06e1 \u0641\u064e\u0631\u064e\u0636\u06e1\u062a\u064f\u0645\u06e1 \u0644\u064e\u0647\u064f\u0646\u0651\u064e \u0641\u064e\u0631\u0650\u064a\u0636\u064e\u0629\u0657 \u0641\u064e\u0646\u0650\u0635\u06e1\u0641\u064f \u0645\u064e\u0627 \u0641\u064e\u0631\u064e\u0636\u06e1\u062a\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u064a\u064e\u0639\u06e1\u0641\u064f\u0648\u0646\u064e \u0623\u064e\u0648\u06e1 \u064a\u064e\u0639\u06e1\u0641\u064f\u0648\u064e\u0627\u0652 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0628\u0650\u064a\u064e\u062f\u0650\u0647\u0650\u06e6 \u0639\u064f\u0642\u06e1\u062f\u064e\u0629\u064f \u0671\u0644\u0646\u0651\u0650\u0643\u064e\u0627\u062d\u0650\u06da \u0648\u064e\u0623\u064e\u0646 \u062a\u064e\u0639\u06e1\u0641\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0642\u06e1\u0631\u064e\u0628\u064f \u0644\u0650\u0644\u062a\u0651\u064e\u0642\u06e1\u0648\u064e\u0649\u0670\u06da \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0646\u0633\u064e\u0648\u064f\u0627\u0652 \u0671\u0644\u06e1\u0641\u064e\u0636\u06e1\u0644\u064e \u0628\u064e\u064a\u06e1\u0646\u064e\u0643\u064f\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0628\u064e\u0635\u0650\u064a\u0631\u064c",translation:"Dan jika kamu menceraikan mereka sebelum kamu sentuh (campuri), padahal kamu sudah menentukan maharnya, maka (bayarlah) seperdua dari yang telah kamu tentukan, kecuali jika mereka (membebaskan) atau dibebaskan oleh orang yang akad nikah ada ditangannya.90) Pembebasan itu lebih dekat kepada takwa. Dan janganlah kamu lupa kebaikan di antara kamu. Sungguh, Allah Maha Melihat apa yang kamu kerjakan"},{id:238,text:"\u062d\u064e\u0670\u0641\u0650\u0638\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u0650 \u0671\u0644\u06e1\u0648\u064f\u0633\u06e1\u0637\u064e\u0649\u0670 \u0648\u064e\u0642\u064f\u0648\u0645\u064f\u0648\u0627\u0652 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0642\u064e\u0670\u0646\u0650\u062a\u0650\u064a\u0646\u064e",translation:"(Peliharalah semua salat dan salat wus\u1e6da.91) Dan laksanakanlah (salat) karena Allah dengan khusyuk"},{id:239,text:"\u0641\u064e\u0625\u0650\u0646\u06e1 \u062e\u0650\u0641\u06e1\u062a\u064f\u0645\u06e1 \u0641\u064e\u0631\u0650\u062c\u064e\u0627\u0644\u064b\u0627 \u0623\u064e\u0648\u06e1 \u0631\u064f\u0643\u06e1\u0628\u064e\u0627\u0646\u0657\u0627\u06d6 \u0641\u064e\u0625\u0650\u0630\u064e\u0627\u0653 \u0623\u064e\u0645\u0650\u0646\u062a\u064f\u0645\u06e1 \u0641\u064e\u0671\u0630\u06e1\u0643\u064f\u0631\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0645\u064e\u0627 \u0639\u064e\u0644\u0651\u064e\u0645\u064e\u0643\u064f\u0645 \u0645\u0651\u064e\u0627 \u0644\u064e\u0645\u06e1 \u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Jika kamu takut (ada bahaya), salatlah sambil berjalan kaki atau berkendaraan. Kemudian apabila telah aman, maka ingatlah Allah (salatlah), sebagaimana Dia telah mengajarkan kepadamu apa yang tidak kamu ketahui"},{id:240,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u062a\u064e\u0648\u064e\u0641\u0651\u064e\u0648\u06e1\u0646\u064e \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u0648\u064e\u064a\u064e\u0630\u064e\u0631\u064f\u0648\u0646\u064e \u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u0657\u0627 \u0648\u064e\u0635\u0650\u064a\u0651\u064e\u0629\u0657 \u0644\u0651\u0650\u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u0650\u0647\u0650\u0645 \u0645\u0651\u064e\u062a\u064e\u0670\u0639\u064b\u0627 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u062d\u064e\u0648\u06e1\u0644\u0650 \u063a\u064e\u064a\u06e1\u0631\u064e \u0625\u0650\u062e\u06e1\u0631\u064e\u0627\u062c\u0656\u06da \u0641\u064e\u0625\u0650\u0646\u06e1 \u062e\u064e\u0631\u064e\u062c\u06e1\u0646\u064e \u0641\u064e\u0644\u064e\u0627 \u062c\u064f\u0646\u064e\u0627\u062d\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u0645\u064e\u0627 \u0641\u064e\u0639\u064e\u0644\u06e1\u0646\u064e \u0641\u0650\u064a\u0653 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0646\u0651\u064e \u0645\u0650\u0646 \u0645\u0651\u064e\u0639\u06e1\u0631\u064f\u0648\u0641\u0656\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0632\u0650\u064a\u0632\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u065e",translation:"Dan orang-orang yang akan mati di antara kamu dan meninggalkan istri-istri, hendaklah membuat wasiat untuk istri-istrinya, (yaitu) nafkah sampai setahun tanpa mengeluarkannya (dari rumah). Tetapi jika mereka keluar (sendiri), maka tidak ada dosa bagimu (mengenai apa) yang mereka lakukan terhadap diri mereka sendiri dalam hal-hal yang baik. Allah Mahaperkasa, Mahabijaksana"},{id:241,text:"\u0648\u064e\u0644\u0650\u0644\u06e1\u0645\u064f\u0637\u064e\u0644\u0651\u064e\u0642\u064e\u0670\u062a\u0650 \u0645\u064e\u062a\u064e\u0670\u0639\u064f\u06e2 \u0628\u0650\u0671\u0644\u06e1\u0645\u064e\u0639\u06e1\u0631\u064f\u0648\u0641\u0650\u06d6 \u062d\u064e\u0642\u0651\u064b\u0627 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",translation:"Dan bagi perempuan-perempuan yang diceraikan hendaklah diberi mut'ah menurut cara yang patut, sebagai suatu kewajiban bagi orang yang bertakwa"},{id:242,text:"\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0647\u0650\u06e6 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Demikianlah Allah menerangkan kepadamu ayat-ayat-Nya agar kamu mengerti"},{id:243,text:"\u06de\u0623\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0631\u064e \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062e\u064e\u0631\u064e\u062c\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u062f\u0650\u064a\u064e\u0670\u0631\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0623\u064f\u0644\u064f\u0648\u0641\u064c \u062d\u064e\u0630\u064e\u0631\u064e \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u0650 \u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064f\u0648\u062a\u064f\u0648\u0627\u0652 \u062b\u064f\u0645\u0651\u064e \u0623\u064e\u062d\u06e1\u064a\u064e\u0670\u0647\u064f\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0630\u064f\u0648 \u0641\u064e\u0636\u06e1\u0644\u064d \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0627 \u064a\u064e\u0634\u06e1\u0643\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Tidakkah kamu memperhatikan orang-orang yang keluar dari kampung halamannya, sedang jumlahnya ribuan karena takut mati? Lalu Allah berfirman kepada mereka, \"Matilah kamu!\" Kemudian Allah menghidupkan mereka. Sesungguhnya Allah memberikan karunia kepada manusia, tetapi kebanyakan manusia tidak bersyukur"},{id:244,text:"\u0648\u064e\u0642\u064e\u0670\u062a\u0650\u0644\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0671\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0633\u064e\u0645\u0650\u064a\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Dan berperanglah kamu di jalan Allah, dan ketahuilah bahwa Allah Maha Mendengar, Maha Mengetahui"},{id:245,text:"\u0645\u0651\u064e\u0646 \u0630\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u0642\u06e1\u0631\u0650\u0636\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0642\u064e\u0631\u06e1\u0636\u064b\u0627 \u062d\u064e\u0633\u064e\u0646\u0657\u0627 \u0641\u064e\u064a\u064f\u0636\u064e\u0670\u0639\u0650\u0641\u064e\u0647\u064f\u06e5 \u0644\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u0636\u06e1\u0639\u064e\u0627\u0641\u0657\u0627 \u0643\u064e\u062b\u0650\u064a\u0631\u064e\u0629\u0657\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0642\u06e1\u0628\u0650\u0636\u064f \u0648\u064e\u064a\u064e\u0628\u06e1\u0635\u06dc\u064f\u0637\u064f \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u062a\u064f\u0631\u06e1\u062c\u064e\u0639\u064f\u0648\u0646\u064e",translation:"(Barang siapa meminjami92) Allah dengan pinjaman yang baik maka Allah melipat gandakan ganti kepadanya dengan banyak. Allah menahan dan melapangkan (rezeki) dan kepada-Nyalah kamu dikembalikan"},{id:246,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0631\u064e \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0625\u0650 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0646\u0650\u064a\u0653 \u0625\u0650\u0633\u06e1\u0631\u064e\u0640\u0670\u0653\u0621\u0650\u064a\u0644\u064e \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0645\u064f\u0648\u0633\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u0650\u0646\u064e\u0628\u0650\u064a\u0651\u0656 \u0644\u0651\u064e\u0647\u064f\u0645\u064f \u0671\u0628\u06e1\u0639\u064e\u062b\u06e1 \u0644\u064e\u0646\u064e\u0627 \u0645\u064e\u0644\u0650\u0643\u0657\u0627 \u0646\u0651\u064f\u0642\u064e\u0670\u062a\u0650\u0644\u06e1 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0642\u064e\u0627\u0644\u064e \u0647\u064e\u0644\u06e1 \u0639\u064e\u0633\u064e\u064a\u06e1\u062a\u064f\u0645\u06e1 \u0625\u0650\u0646 \u0643\u064f\u062a\u0650\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0642\u0650\u062a\u064e\u0627\u0644\u064f \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064f\u0642\u064e\u0670\u062a\u0650\u0644\u064f\u0648\u0627\u0652\u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0646\u064e\u0627\u0653 \u0623\u064e\u0644\u0651\u064e\u0627 \u0646\u064f\u0642\u064e\u0670\u062a\u0650\u0644\u064e \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0642\u064e\u062f\u06e1 \u0623\u064f\u062e\u06e1\u0631\u0650\u062c\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646 \u062f\u0650\u064a\u064e\u0670\u0631\u0650\u0646\u064e\u0627 \u0648\u064e\u0623\u064e\u0628\u06e1\u0646\u064e\u0627\u0653\u0626\u0650\u0646\u064e\u0627\u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0643\u064f\u062a\u0650\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u064f \u0671\u0644\u06e1\u0642\u0650\u062a\u064e\u0627\u0644\u064f \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u06e1\u0627\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u0657\u0627 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064f\u06e2 \u0628\u0650\u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Tidakkah kamu perhatikan para pemuka Bani Israil setelah Musa wafat ketika mereka berkata kepada seorang nabi mereka, \"Angkatlah seorang raja untuk kami, niscaya kami berperang di jalan Allah.\" Nabi mereka menjawab, \"Jangan-jangan jika diwajibkan atasmu berperang, kamu tidak akan berperang juga?\" Mereka menjawab, \"Mengapa kami tidak akan berperang di jalan Allah, sedangkan kami telah diusir dari kampung halaman kami dan (dipisahkan dari) anak-anak kami?\"93) Tetapi ketika perang itu diwajibkan atas mereka, mereka berpaling, kecuali sebagian kecil dari mereka. Dan Allah Maha Mengetahui orang-orang yang zalim"},{id:247,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0646\u064e\u0628\u0650\u064a\u0651\u064f\u0647\u064f\u0645\u06e1 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0642\u064e\u062f\u06e1 \u0628\u064e\u0639\u064e\u062b\u064e \u0644\u064e\u0643\u064f\u0645\u06e1 \u0637\u064e\u0627\u0644\u064f\u0648\u062a\u064e \u0645\u064e\u0644\u0650\u0643\u0657\u0627\u06da \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u064a\u064e\u0643\u064f\u0648\u0646\u064f \u0644\u064e\u0647\u064f \u0671\u0644\u06e1\u0645\u064f\u0644\u06e1\u0643\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0648\u064e\u0646\u064e\u062d\u06e1\u0646\u064f \u0623\u064e\u062d\u064e\u0642\u0651\u064f \u0628\u0650\u0671\u0644\u06e1\u0645\u064f\u0644\u06e1\u0643\u0650 \u0645\u0650\u0646\u06e1\u0647\u064f \u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064f\u0624\u06e1\u062a\u064e \u0633\u064e\u0639\u064e\u0629\u0657 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064e\u0627\u0644\u0650\u06da \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0671\u0635\u06e1\u0637\u064e\u0641\u064e\u0649\u0670\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0648\u064e\u0632\u064e\u0627\u062f\u064e\u0647\u064f\u06e5 \u0628\u064e\u0633\u06e1\u0637\u064e\u0629\u0657 \u0641\u0650\u064a \u0671\u0644\u06e1\u0639\u0650\u0644\u06e1\u0645\u0650 \u0648\u064e\u0671\u0644\u06e1\u062c\u0650\u0633\u06e1\u0645\u0650\u06d6 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064f\u0624\u06e1\u062a\u0650\u064a \u0645\u064f\u0644\u06e1\u0643\u064e\u0647\u064f\u06e5 \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0670\u0633\u0650\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Dan nabi mereka berkata kepada mereka, \"Sesungguhnya Allah telah mengangkat Talut menjadi rajamu.\" Mereka menjawab, \"Bagaimana Talut memperoleh kerajaan atas kami, sedangkan kami lebih berhak atas kerajaan itu daripadanya, dan dia tidak diberi kekayaan yang banyak?\" (Nabi) menjawab, \"Allah telah memilihnya (menjadi raja) kamu dan memberikan kelebihan ilmu dan fisik.\" Allah memberikan kerajaan-Nya kepada siapa yang Dia kehendaki, dan Allah Mahaluas, Maha Mengetahui"},{id:248,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0646\u064e\u0628\u0650\u064a\u0651\u064f\u0647\u064f\u0645\u06e1 \u0625\u0650\u0646\u0651\u064e \u0621\u064e\u0627\u064a\u064e\u0629\u064e \u0645\u064f\u0644\u06e1\u0643\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0646 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u062a\u0651\u064e\u0627\u0628\u064f\u0648\u062a\u064f \u0641\u0650\u064a\u0647\u0650 \u0633\u064e\u0643\u0650\u064a\u0646\u064e\u0629\u065e \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0628\u064e\u0642\u0650\u064a\u0651\u064e\u0629\u065e \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0631\u064e\u0643\u064e \u0621\u064e\u0627\u0644\u064f \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u0621\u064e\u0627\u0644\u064f \u0647\u064e\u0670\u0631\u064f\u0648\u0646\u064e \u062a\u064e\u062d\u06e1\u0645\u0650\u0644\u064f\u0647\u064f \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u064f\u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0623\u0653\u064a\u064e\u0629\u0657 \u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645 \u0645\u0651\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"(Dan nabi mereka berkata kepada mereka, \"Sesungguhnya tanda kerajaannya ialah datangnya Tabut94) kepadamu, yang di dalamnya terdapat ketenangan dari Tuhanmu dan sisa peninggalan keluarga Musa dan keluarga Harun, yang dibawa oleh malaikat.\" Sungguh, pada yang demikian itu terdapat tanda (kebesaran Allah) bagimu, jika kamu orang beriman"},{id:249,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0641\u064e\u0635\u064e\u0644\u064e \u0637\u064e\u0627\u0644\u064f\u0648\u062a\u064f \u0628\u0650\u0671\u0644\u06e1\u062c\u064f\u0646\u064f\u0648\u062f\u0650 \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064f\u0628\u06e1\u062a\u064e\u0644\u0650\u064a\u0643\u064f\u0645 \u0628\u0650\u0646\u064e\u0647\u064e\u0631\u0656 \u0641\u064e\u0645\u064e\u0646 \u0634\u064e\u0631\u0650\u0628\u064e \u0645\u0650\u0646\u06e1\u0647\u064f \u0641\u064e\u0644\u064e\u064a\u06e1\u0633\u064e \u0645\u0650\u0646\u0651\u0650\u064a \u0648\u064e\u0645\u064e\u0646 \u0644\u0651\u064e\u0645\u06e1 \u064a\u064e\u0637\u06e1\u0639\u064e\u0645\u06e1\u0647\u064f \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646\u0651\u0650\u064a\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u0650 \u0671\u063a\u06e1\u062a\u064e\u0631\u064e\u0641\u064e \u063a\u064f\u0631\u06e1\u0641\u064e\u0629\u064e\u06e2 \u0628\u0650\u064a\u064e\u062f\u0650\u0647\u0650\u06e6\u06da \u0641\u064e\u0634\u064e\u0631\u0650\u0628\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1\u0647\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u0657\u0627 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1\u06da \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0648\u064e\u0632\u064e\u0647\u064f\u06e5 \u0647\u064f\u0648\u064e \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0645\u064e\u0639\u064e\u0647\u064f\u06e5 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u0637\u064e\u0627\u0642\u064e\u0629\u064e \u0644\u064e\u0646\u064e\u0627 \u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e \u0628\u0650\u062c\u064e\u0627\u0644\u064f\u0648\u062a\u064e \u0648\u064e\u062c\u064f\u0646\u064f\u0648\u062f\u0650\u0647\u0650\u06e6\u06da \u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0638\u064f\u0646\u0651\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645 \u0645\u0651\u064f\u0644\u064e\u0670\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u0645 \u0645\u0651\u0650\u0646 \u0641\u0650\u0626\u064e\u0629\u0656 \u0642\u064e\u0644\u0650\u064a\u0644\u064e\u0629\u064d \u063a\u064e\u0644\u064e\u0628\u064e\u062a\u06e1 \u0641\u0650\u0626\u064e\u0629\u0657 \u0643\u064e\u062b\u0650\u064a\u0631\u064e\u0629\u064e\u06e2 \u0628\u0650\u0625\u0650\u0630\u06e1\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0639\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0628\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Maka ketika Talut membawa bala tentaranya, dia berkata, \"Allah akan menguji kamu dengan satu sungai. Maka barang siapa meminum (airnya), dia bukanlah pengikutku. Dan barang siapa tidak meminumnya, maka dia adalah pengikutku kecuali menciduk seciduk dengan tangan.\" Tetapi mereka meminumnya kecuali sebagian kecil dari mereka. Ketika dia (Talut) dan orang-orang yang beriman bersamanya menyeberangi sungai itu, mereka berkata, \"Kami tidak kuat lagi pada hari ini melawan Jalut dan bala tentaranya.\" Mereka yang meyakini bahwa mereka akan menemui Allah berkata, \"Betapa banyak kelompok kecil mengalahkan kelompok besar dengan izin Allah.\" Dan Allah beserta orang-orang yang sabar"},{id:250,text:"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0628\u064e\u0631\u064e\u0632\u064f\u0648\u0627\u0652 \u0644\u0650\u062c\u064e\u0627\u0644\u064f\u0648\u062a\u064e \u0648\u064e\u062c\u064f\u0646\u064f\u0648\u062f\u0650\u0647\u0650\u06e6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627\u0653 \u0623\u064e\u0641\u06e1\u0631\u0650\u063a\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0635\u064e\u0628\u06e1\u0631\u0657\u0627 \u0648\u064e\u062b\u064e\u0628\u0651\u0650\u062a\u06e1 \u0623\u064e\u0642\u06e1\u062f\u064e\u0627\u0645\u064e\u0646\u064e\u0627 \u0648\u064e\u0671\u0646\u0635\u064f\u0631\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan ketika mereka maju melawan Jalut dan tentaranya, mereka berdoa, \"Ya Tuhan kami, limpahkanlah kesabaran kepada kami, kokohkanlah langkah kami dan tolonglah kami menghadapi orang-orang kafir"},{id:251,text:"\u0641\u064e\u0647\u064e\u0632\u064e\u0645\u064f\u0648\u0647\u064f\u0645 \u0628\u0650\u0625\u0650\u0630\u06e1\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0642\u064e\u062a\u064e\u0644\u064e \u062f\u064e\u0627\u0648\u064f\u06e5\u062f\u064f \u062c\u064e\u0627\u0644\u064f\u0648\u062a\u064e \u0648\u064e\u0621\u064e\u0627\u062a\u064e\u0649\u0670\u0647\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u0645\u064f\u0644\u06e1\u0643\u064e \u0648\u064e\u0671\u0644\u06e1\u062d\u0650\u0643\u06e1\u0645\u064e\u0629\u064e \u0648\u064e\u0639\u064e\u0644\u0651\u064e\u0645\u064e\u0647\u064f\u06e5 \u0645\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06d7 \u0648\u064e\u0644\u064e\u0648\u06e1\u0644\u064e\u0627 \u062f\u064e\u0641\u06e1\u0639\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0628\u064e\u0639\u06e1\u0636\u064e\u0647\u064f\u0645 \u0628\u0650\u0628\u064e\u0639\u06e1\u0636\u0656 \u0644\u0651\u064e\u0641\u064e\u0633\u064e\u062f\u064e\u062a\u0650 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064f \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0630\u064f\u0648 \u0641\u064e\u0636\u06e1\u0644\u064d \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Maka mereka mengalahkannya dengan izin Allah, dan Dawud membunuh Jalut. Kemudian Allah memberinya (Dawud) kerajaan, dan hikmah, dan mengajarinya apa yang Dia kehendaki. Dan kalau Allah tidak melindungi sebagian manusia dengan sebagian yang lain, niscaya rusaklah bumi ini. Tetapi Allah mempunyai karunia (yang dilimpahkan-Nya) atas seluruh alam"},{id:252,text:"\u062a\u0650\u0644\u06e1\u0643\u064e \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0646\u064e\u062a\u06e1\u0644\u064f\u0648\u0647\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650\u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0631\u06e1\u0633\u064e\u0644\u0650\u064a\u0646\u064e",translation:"Itulah ayat-ayat Allah, Kami bacakan kepadamu dengan benar dan engkau (Muhammad) adalah benar-benar seorang rasul"},{id:253,text:"\u06de\u062a\u0650\u0644\u06e1\u0643\u064e \u0671\u0644\u0631\u0651\u064f\u0633\u064f\u0644\u064f \u0641\u064e\u0636\u0651\u064e\u0644\u06e1\u0646\u064e\u0627 \u0628\u064e\u0639\u06e1\u0636\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u06e1\u0636\u0656\u06d8 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0646 \u0643\u064e\u0644\u0651\u064e\u0645\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06d6 \u0648\u064e\u0631\u064e\u0641\u064e\u0639\u064e \u0628\u064e\u0639\u06e1\u0636\u064e\u0647\u064f\u0645\u06e1 \u062f\u064e\u0631\u064e\u062c\u064e\u0670\u062a\u0656\u06da \u0648\u064e\u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0627 \u0639\u0650\u064a\u0633\u064e\u0649 \u0671\u0628\u06e1\u0646\u064e \u0645\u064e\u0631\u06e1\u064a\u064e\u0645\u064e \u0671\u0644\u06e1\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0650 \u0648\u064e\u0623\u064e\u064a\u0651\u064e\u062f\u06e1\u0646\u064e\u0670\u0647\u064f \u0628\u0650\u0631\u064f\u0648\u062d\u0650 \u0671\u0644\u06e1\u0642\u064f\u062f\u064f\u0633\u0650\u06d7 \u0648\u064e\u0644\u064e\u0648\u06e1 \u0634\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0627 \u0671\u0642\u06e1\u062a\u064e\u062a\u064e\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u0647\u0650\u0645 \u0645\u0651\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0645\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u062a\u06e1\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u064f \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0650 \u0671\u062e\u06e1\u062a\u064e\u0644\u064e\u0641\u064f\u0648\u0627\u0652 \u0641\u064e\u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0646\u06e1 \u0621\u064e\u0627\u0645\u064e\u0646\u064e \u0648\u064e\u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0646 \u0643\u064e\u0641\u064e\u0631\u064e\u06da \u0648\u064e\u0644\u064e\u0648\u06e1 \u0634\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0627 \u0671\u0642\u06e1\u062a\u064e\u062a\u064e\u0644\u064f\u0648\u0627\u0652 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0641\u06e1\u0639\u064e\u0644\u064f \u0645\u064e\u0627 \u064a\u064f\u0631\u0650\u064a\u062f\u064f",translation:"Rasul-rasul itu Kami lebihkan sebagian mereka dari sebagian yang lain. Di antara mereka ada yang (langsung) Allah berfirman dengannya dan sebagian lagi ada yang ditinggikan-Nya beberapa derajat. Dan Kami beri Isa putra Maryam beberapa mukjizat dan Kami perkuat dia dengan Rohulkudus.95) Kalau Allah menghendaki, niscaya orang-orang setelah mereka tidak akan berbunuh-bunuhan, setelah bukti-bukti sampai kepada mereka. Tetapi mereka berselisih, maka ada di antara mereka yang beriman dan ada (pula) yang kafir. Kalau Allah menghendaki, tidaklah mereka berbunuh-bunuhan. Tetapi Allah berbuat menurut kahendak-Nya"},{id:254,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0641\u0650\u0642\u064f\u0648\u0627\u0652 \u0645\u0650\u0645\u0651\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u06e1\u0646\u064e\u0670\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650 \u0623\u064e\u0646 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e \u064a\u064e\u0648\u06e1\u0645\u065e \u0644\u0651\u064e\u0627 \u0628\u064e\u064a\u06e1\u0639\u065e \u0641\u0650\u064a\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u062e\u064f\u0644\u0651\u064e\u0629\u065e \u0648\u064e\u0644\u064e\u0627 \u0634\u064e\u0641\u064e\u0670\u0639\u064e\u0629\u065e\u06d7 \u0648\u064e\u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u064f\u0648\u0646\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Wahai orang-orang yang beriman! Infakkanlah sebagian dari rezeki yang telah Kami berikan kepadamu sebelum datang hari ketika tidak ada lagi jual beli, tidak ada lagi persahabatan dan tidak ada lagi syafaat. Orang-orang kafir itulah orang yang zalim"},{id:255,text:"\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u062d\u064e\u064a\u0651\u064f \u0671\u0644\u06e1\u0642\u064e\u064a\u0651\u064f\u0648\u0645\u064f\u06da \u0644\u064e\u0627 \u062a\u064e\u0623\u06e1\u062e\u064f\u0630\u064f\u0647\u064f\u06e5 \u0633\u0650\u0646\u064e\u0629\u065e \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0648\u06e1\u0645\u065e\u06da \u0644\u0651\u064e\u0647\u064f\u06e5 \u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d7 \u0645\u064e\u0646 \u0630\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064e\u0634\u06e1\u0641\u064e\u0639\u064f \u0639\u0650\u0646\u062f\u064e\u0647\u064f\u06e5\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0625\u0650\u0630\u06e1\u0646\u0650\u0647\u0650\u06e6\u06da \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u0647\u0650\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u06e1\u0641\u064e\u0647\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u064a\u0637\u064f\u0648\u0646\u064e \u0628\u0650\u0634\u064e\u064a\u06e1\u0621\u0656 \u0645\u0651\u0650\u0646\u06e1 \u0639\u0650\u0644\u06e1\u0645\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0645\u064e\u0627 \u0634\u064e\u0627\u0653\u0621\u064e\u06da \u0648\u064e\u0633\u0650\u0639\u064e \u0643\u064f\u0631\u06e1\u0633\u0650\u064a\u0651\u064f\u0647\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e\u06d6 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0640\u0654\u064f\u0648\u062f\u064f\u0647\u064f\u06e5 \u062d\u0650\u0641\u06e1\u0638\u064f\u0647\u064f\u0645\u064e\u0627\u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0639\u064e\u0644\u0650\u064a\u0651\u064f \u0671\u0644\u06e1\u0639\u064e\u0638\u0650\u064a\u0645\u064f",translation:"Allah, tidak ada tuhan selain Dia. Yang Mahahidup, Yang terus menerus mengurus (makhluk-Nya), tidak mengantuk dan tidak tidur. Milik-Nya apa yang ada di langit dan apa yang ada di bumi. Tidak ada yang dapat memberi syafaat di sisi-Nya tanpa izin-Nya. Dia mengetahui apa yang dihadapan mereka dan apa yang di belakang mereka, dan mereka tidak mengetahui sesuatu apa pun tentang ilmu-Nya melainkan apa yang Dia kehendaki. Kursi-Nya96) meliputi langit dan bumi. Dan Dia tidak merasa berat memelihara keduanya, dan Dia Mahatinggi, Mahabesar"},{id:256,text:"\u0644\u064e\u0627\u0653 \u0625\u0650\u0643\u06e1\u0631\u064e\u0627\u0647\u064e \u0641\u0650\u064a \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u0650\u06d6 \u0642\u064e\u062f \u062a\u0651\u064e\u0628\u064e\u064a\u0651\u064e\u0646\u064e \u0671\u0644\u0631\u0651\u064f\u0634\u06e1\u062f\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u063a\u064e\u064a\u0651\u0650\u06da \u0641\u064e\u0645\u064e\u0646 \u064a\u064e\u0643\u06e1\u0641\u064f\u0631\u06e1 \u0628\u0650\u0671\u0644\u0637\u0651\u064e\u0640\u0670\u063a\u064f\u0648\u062a\u0650 \u0648\u064e\u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u06e2 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0642\u064e\u062f\u0650 \u0671\u0633\u06e1\u062a\u064e\u0645\u06e1\u0633\u064e\u0643\u064e \u0628\u0650\u0671\u0644\u06e1\u0639\u064f\u0631\u06e1\u0648\u064e\u0629\u0650 \u0671\u0644\u06e1\u0648\u064f\u062b\u06e1\u0642\u064e\u0649\u0670 \u0644\u064e\u0627 \u0671\u0646\u0641\u0650\u0635\u064e\u0627\u0645\u064e \u0644\u064e\u0647\u064e\u0627\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0633\u064e\u0645\u0650\u064a\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u064c",translation:"Tidak ada paksaan dalam (menganut) agama (Islam), sesungguhnya telah jelas (perbedaan) antara jalan yang benar dengan jalan yang sesat. Barang siapa ingkar kepada Tagut97) dan beriman kepada Allah, maka sungguh, dia telah berpegang (teguh) pada tali yang sangat kuat yang tidak akan putus. Allah Maha Mendengar, Maha Mengetahui"},{id:257,text:"\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0644\u0650\u064a\u0651\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u064a\u064f\u062e\u06e1\u0631\u0650\u062c\u064f\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0638\u0651\u064f\u0644\u064f\u0645\u064e\u0670\u062a\u0650 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0646\u0651\u064f\u0648\u0631\u0650\u06d6 \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0648\u06e1\u0644\u0650\u064a\u064e\u0627\u0653\u0624\u064f\u0647\u064f\u0645\u064f \u0671\u0644\u0637\u0651\u064e\u0640\u0670\u063a\u064f\u0648\u062a\u064f \u064a\u064f\u062e\u06e1\u0631\u0650\u062c\u064f\u0648\u0646\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064f\u0648\u0631\u0650 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0638\u0651\u064f\u0644\u064f\u0645\u064e\u0670\u062a\u0650\u06d7 \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650\u06d6 \u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u0670\u0644\u0650\u062f\u064f\u0648\u0646\u064e",translation:"Allah pelindung orang yang beriman. Dia mengeluarkan mereka dari kegelapan kepada cahaya (iman). Dan orang-orang yang kafir, pelindung-pelindungnya adalah setan, yang mengeluarkan mereka dari cahaya kepada kegelapan. Mereka adalah penghuni neraka. Mereka kekal di dalamnya"},{id:258,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0631\u064e \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062d\u064e\u0627\u0653\u062c\u0651\u064e \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u0640\u06e7\u0645\u064e \u0641\u0650\u064a \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0646\u06e1 \u0621\u064e\u0627\u062a\u064e\u0649\u0670\u0647\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u0645\u064f\u0644\u06e1\u0643\u064e \u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u0640\u06e7\u0645\u064f \u0631\u064e\u0628\u0651\u0650\u064a\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u062d\u06e1\u064a\u0650\u06e6 \u0648\u064e\u064a\u064f\u0645\u0650\u064a\u062a\u064f \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0646\u064e\u0627\u06e0 \u0623\u064f\u062d\u06e1\u064a\u0650\u06e6 \u0648\u064e\u0623\u064f\u0645\u0650\u064a\u062a\u064f\u06d6 \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u0640\u06e7\u0645\u064f \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0623\u06e1\u062a\u0650\u064a \u0628\u0650\u0671\u0644\u0634\u0651\u064e\u0645\u06e1\u0633\u0650 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064e\u0634\u06e1\u0631\u0650\u0642\u0650 \u0641\u064e\u0623\u06e1\u062a\u0650 \u0628\u0650\u0647\u064e\u0627 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064e\u063a\u06e1\u0631\u0650\u0628\u0650 \u0641\u064e\u0628\u064f\u0647\u0650\u062a\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0643\u064e\u0641\u064e\u0631\u064e\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064e\u0647\u06e1\u062f\u0650\u064a \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"(Tidakkah kamu memperhatikan orang98) yang mendebat Ibrahim mengenai Tuhannya, karena Allah telah memberinya kerajaan (kekuasaan). Ketika Ibrahim berkata, \"Tuhanku ialah Yang menghidupkan dan mematikan,\" dia berkata, \"Aku pun dapat menghidupkan dan mematikan.\"99) Ibrahim berkata, \"Allah menerbitkan matahari dari timur, maka terbitkanlah ia dari barat.\" Maka bingunglah orang yang kafir itu. Allah tidak memberi petunjuk kepada orang-orang yang zalim"},{id:259,text:"\u0623\u064e\u0648\u06e1 \u0643\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0645\u064e\u0631\u0651\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064e\u0631\u06e1\u064a\u064e\u0629\u0656 \u0648\u064e\u0647\u0650\u064a\u064e \u062e\u064e\u0627\u0648\u0650\u064a\u064e\u0629\u064c \u0639\u064e\u0644\u064e\u0649\u0670 \u0639\u064f\u0631\u064f\u0648\u0634\u0650\u0647\u064e\u0627 \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u064a\u064f\u062d\u06e1\u064a\u0650\u06e6 \u0647\u064e\u0670\u0630\u0650\u0647\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u064e\u0639\u06e1\u062f\u064e \u0645\u064e\u0648\u06e1\u062a\u0650\u0647\u064e\u0627\u06d6 \u0641\u064e\u0623\u064e\u0645\u064e\u0627\u062a\u064e\u0647\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0627\u0652\u0626\u064e\u0629\u064e \u0639\u064e\u0627\u0645\u0656 \u062b\u064f\u0645\u0651\u064e \u0628\u064e\u0639\u064e\u062b\u064e\u0647\u064f\u06e5\u06d6 \u0642\u064e\u0627\u0644\u064e \u0643\u064e\u0645\u06e1 \u0644\u064e\u0628\u0650\u062b\u06e1\u062a\u064e\u06d6 \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0628\u0650\u062b\u06e1\u062a\u064f \u064a\u064e\u0648\u06e1\u0645\u064b\u0627 \u0623\u064e\u0648\u06e1 \u0628\u064e\u0639\u06e1\u0636\u064e \u064a\u064e\u0648\u06e1\u0645\u0656\u06d6 \u0642\u064e\u0627\u0644\u064e \u0628\u064e\u0644 \u0644\u0651\u064e\u0628\u0650\u062b\u06e1\u062a\u064e \u0645\u0650\u0627\u0652\u0626\u064e\u0629\u064e \u0639\u064e\u0627\u0645\u0656 \u0641\u064e\u0671\u0646\u0638\u064f\u0631\u06e1 \u0625\u0650\u0644\u064e\u0649\u0670 \u0637\u064e\u0639\u064e\u0627\u0645\u0650\u0643\u064e \u0648\u064e\u0634\u064e\u0631\u064e\u0627\u0628\u0650\u0643\u064e \u0644\u064e\u0645\u06e1 \u064a\u064e\u062a\u064e\u0633\u064e\u0646\u0651\u064e\u0647\u06e1\u06d6 \u0648\u064e\u0671\u0646\u0638\u064f\u0631\u06e1 \u0625\u0650\u0644\u064e\u0649\u0670 \u062d\u0650\u0645\u064e\u0627\u0631\u0650\u0643\u064e \u0648\u064e\u0644\u0650\u0646\u064e\u062c\u06e1\u0639\u064e\u0644\u064e\u0643\u064e \u0621\u064e\u0627\u064a\u064e\u0629\u0657 \u0644\u0651\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650\u06d6 \u0648\u064e\u0671\u0646\u0638\u064f\u0631\u06e1 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u0639\u0650\u0638\u064e\u0627\u0645\u0650 \u0643\u064e\u064a\u06e1\u0641\u064e \u0646\u064f\u0646\u0634\u0650\u0632\u064f\u0647\u064e\u0627 \u062b\u064f\u0645\u0651\u064e \u0646\u064e\u0643\u06e1\u0633\u064f\u0648\u0647\u064e\u0627 \u0644\u064e\u062d\u06e1\u0645\u0657\u0627\u06da \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062a\u064e\u0628\u064e\u064a\u0651\u064e\u0646\u064e \u0644\u064e\u0647\u064f\u06e5 \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0642\u064e\u062f\u0650\u064a\u0631\u065e",translation:"Atau seperti orang yang melewati suatu negeri yang (bangunan-bangunannya) telah runtuh hingga menutupi (puing-puing) atap-atapnya, dia berkata, \"Bagaimana Allah menghidupkan kembali (negeri) ini setelah hancur?\" Lalu Allah mematikannya (orang itu) selama seratus tahun, kemudian membangkitkannya (menghidupkannya) kembali. Dan (Allah) bertanya, \"Berapa lama engkau tinggal (disini)?\" Dia (orang itu) menjawab, \"Aku tinggal (disini) sehari atau setengah hari.\" Allah berfirman, \"Tidak! Engkau telah tinggal seratus tahun. Lihatlah makanan dan minumanmu yang belum berubah, tetapi lihatlah keledaimu (yang telah menjadi tulang belulang). Dan agar Kami jadikan engkau tanda kekuasaan Kami bagi manusia. Lihatlah tulang belulang (keledai itu), bagaimana Kami menyusunnya kembali, kemudian Kami membalutnya dengan daging.\" Maka ketika telah nyata baginya, dia pun berkata, \"Saya mengetahui (yakin) bahwa Allah Mahakuasa atas segala sesuatu"},{id:260,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u0640\u06e7\u0645\u064f \u0631\u064e\u0628\u0651\u0650 \u0623\u064e\u0631\u0650\u0646\u0650\u064a \u0643\u064e\u064a\u06e1\u0641\u064e \u062a\u064f\u062d\u06e1\u064a\u0650 \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u064e\u0649\u0670\u06d6 \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0648\u064e\u0644\u064e\u0645\u06e1 \u062a\u064f\u0624\u06e1\u0645\u0650\u0646\u06d6 \u0642\u064e\u0627\u0644\u064e \u0628\u064e\u0644\u064e\u0649\u0670 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u0644\u0651\u0650\u064a\u064e\u0637\u06e1\u0645\u064e\u0626\u0650\u0646\u0651\u064e \u0642\u064e\u0644\u06e1\u0628\u0650\u064a\u06d6 \u0642\u064e\u0627\u0644\u064e \u0641\u064e\u062e\u064f\u0630\u06e1 \u0623\u064e\u0631\u06e1\u0628\u064e\u0639\u064e\u0629\u0657 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0637\u0651\u064e\u064a\u06e1\u0631\u0650 \u0641\u064e\u0635\u064f\u0631\u06e1\u0647\u064f\u0646\u0651\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u062b\u064f\u0645\u0651\u064e \u0671\u062c\u06e1\u0639\u064e\u0644\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u062c\u064e\u0628\u064e\u0644\u0656 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0646\u0651\u064e \u062c\u064f\u0632\u06e1\u0621\u0657\u0627 \u062b\u064f\u0645\u0651\u064e \u0671\u062f\u06e1\u0639\u064f\u0647\u064f\u0646\u0651\u064e \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u0646\u064e\u0643\u064e \u0633\u064e\u0639\u06e1\u064a\u0657\u0627\u06da \u0648\u064e\u0671\u0639\u06e1\u0644\u064e\u0645\u06e1 \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0632\u0650\u064a\u0632\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u065e",translation:"Dan (ingatlah) ketika Ibrahim berkata, \"Ya Tuhanku, perlihatkanlah kepadaku bagaimana Engkau menghidupkan orang mati.\" Allah berfirman, \"Belum percayakah engkau?\" Dia (Ibrahim) menjawab, \"Aku percaya, tetapi agar hatiku tenang (mantap).\" Dia (Allah) berfirman, \"Kalau begitu ambillah empat ekor burung, lalu cincanglah olehmu kemudian letakkan di atas masing-masing bukit satu bagian, kemudian panggillah mereka, niscaya mereka datang kepadamu dengan segera.\" Ketahuilah bahwa Allah Mahaperkasa, Mahabijaksana"},{id:261,text:"\u0645\u0651\u064e\u062b\u064e\u0644\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0646\u0641\u0650\u0642\u064f\u0648\u0646\u064e \u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u0645\u064e\u062b\u064e\u0644\u0650 \u062d\u064e\u0628\u0651\u064e\u0629\u064d \u0623\u064e\u0646\u06e2\u0628\u064e\u062a\u064e\u062a\u06e1 \u0633\u064e\u0628\u06e1\u0639\u064e \u0633\u064e\u0646\u064e\u0627\u0628\u0650\u0644\u064e \u0641\u0650\u064a \u0643\u064f\u0644\u0651\u0650 \u0633\u064f\u0646\u06e2\u0628\u064f\u0644\u064e\u0629\u0656 \u0645\u0651\u0650\u0627\u0652\u0626\u064e\u0629\u064f \u062d\u064e\u0628\u0651\u064e\u0629\u0656\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064f\u0636\u064e\u0670\u0639\u0650\u0641\u064f \u0644\u0650\u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0670\u0633\u0650\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u064c",translation:"Perumpamaan orang yang menginfakkan hartanya di jalan Allah seperti sebutir biji yang menumbuhkan tujuh tangkai, pada setiap tangkai ada seratus biji. Allah melipatgandakan bagi siapa yang Dia kehendaki, Dan Allah Mahaluas, Maha Mengetahui"},{id:262,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0646\u0641\u0650\u0642\u064f\u0648\u0646\u064e \u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0627 \u064a\u064f\u062a\u06e1\u0628\u0650\u0639\u064f\u0648\u0646\u064e \u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0641\u064e\u0642\u064f\u0648\u0627\u0652 \u0645\u064e\u0646\u0651\u0657\u0627 \u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064e\u0630\u0657\u0649 \u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u062c\u06e1\u0631\u064f\u0647\u064f\u0645\u06e1 \u0639\u0650\u0646\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u062e\u064e\u0648\u06e1\u0641\u064c \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u06e1 \u064a\u064e\u062d\u06e1\u0632\u064e\u0646\u064f\u0648\u0646\u064e",translation:"Orang yang menginfakkan hartanya di jalan Allah, kemudian tidak mengiringi apa yang dia infakkan itu dengan menyebut-nyebutnya dan menyakiti (perasaan penerima), mereka memperoleh pahala di sisi Tuhan mereka. Tidak ada rasa takut pada mereka dan mereka tidak bersedih hati"},{id:263,text:"\u06de\u0642\u064e\u0648\u06e1\u0644\u065e \u0645\u0651\u064e\u0639\u06e1\u0631\u064f\u0648\u0641\u065e \u0648\u064e\u0645\u064e\u063a\u06e1\u0641\u0650\u0631\u064e\u0629\u064c \u062e\u064e\u064a\u06e1\u0631\u065e \u0645\u0651\u0650\u0646 \u0635\u064e\u062f\u064e\u0642\u064e\u0629\u0656 \u064a\u064e\u062a\u06e1\u0628\u064e\u0639\u064f\u0647\u064e\u0627\u0653 \u0623\u064e\u0630\u0657\u0649\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0646\u0650\u064a\u0651\u064c \u062d\u064e\u0644\u0650\u064a\u0645\u065e",translation:"(Perkataan yang baik dan pemberian maaf 100) lebih baik daripada sedekah yang diiringi tindakan yang menyakiti. Allah Mahakaya, Maha Penyantun"},{id:264,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u062a\u064f\u0628\u06e1\u0637\u0650\u0644\u064f\u0648\u0627\u0652 \u0635\u064e\u062f\u064e\u0642\u064e\u0670\u062a\u0650\u0643\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0645\u064e\u0646\u0651\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0630\u064e\u0649\u0670 \u0643\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u0646\u0641\u0650\u0642\u064f \u0645\u064e\u0627\u0644\u064e\u0647\u064f\u06e5 \u0631\u0650\u0626\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u0650\u06d6 \u0641\u064e\u0645\u064e\u062b\u064e\u0644\u064f\u0647\u064f\u06e5 \u0643\u064e\u0645\u064e\u062b\u064e\u0644\u0650 \u0635\u064e\u0641\u06e1\u0648\u064e\u0627\u0646\u064d \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u062a\u064f\u0631\u064e\u0627\u0628\u065e \u0641\u064e\u0623\u064e\u0635\u064e\u0627\u0628\u064e\u0647\u064f\u06e5 \u0648\u064e\u0627\u0628\u0650\u0644\u065e \u0641\u064e\u062a\u064e\u0631\u064e\u0643\u064e\u0647\u064f\u06e5 \u0635\u064e\u0644\u06e1\u062f\u0657\u0627\u06d6 \u0644\u0651\u064e\u0627 \u064a\u064e\u0642\u06e1\u062f\u0650\u0631\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064f\u0648\u0627\u0652\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064e\u0647\u06e1\u062f\u0650\u064a \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Wahai orang-orang yang beriman! Janganlah kamu merusak sedekahmu dengan menyebut-nyebutnya dan menyakiti (perasaan penerima), seperti orang yang menginfakkan hartanya karena riya` (pamer) kepada manusia dan dia tidak beriman kepada Allah dan hari akhir. Perumpaannya (orang itu) seperti batu licin yang di atasnya ada debu, kemudian batu itu ditimpa hujan lebat, maka tinggallah batu itu licin lagi. Mereka tidak memperoleh sesuatu apa pun dari apa yang mereka kerjakan. Dan Allah tidak memberi petunjuk kepada orang-orang kafir"},{id:265,text:"\u0648\u064e\u0645\u064e\u062b\u064e\u0644\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0646\u0641\u0650\u0642\u064f\u0648\u0646\u064e \u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0628\u06e1\u062a\u0650\u063a\u064e\u0627\u0653\u0621\u064e \u0645\u064e\u0631\u06e1\u0636\u064e\u0627\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u062a\u064e\u062b\u06e1\u0628\u0650\u064a\u062a\u0657\u0627 \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u06e1 \u0643\u064e\u0645\u064e\u062b\u064e\u0644\u0650 \u062c\u064e\u0646\u0651\u064e\u0629\u0650\u06ed \u0628\u0650\u0631\u064e\u0628\u06e1\u0648\u064e\u0629\u064d \u0623\u064e\u0635\u064e\u0627\u0628\u064e\u0647\u064e\u0627 \u0648\u064e\u0627\u0628\u0650\u0644\u065e \u0641\u064e\u0640\u0654\u064e\u0627\u062a\u064e\u062a\u06e1 \u0623\u064f\u0643\u064f\u0644\u064e\u0647\u064e\u0627 \u0636\u0650\u0639\u06e1\u0641\u064e\u064a\u06e1\u0646\u0650 \u0641\u064e\u0625\u0650\u0646 \u0644\u0651\u064e\u0645\u06e1 \u064a\u064f\u0635\u0650\u0628\u06e1\u0647\u064e\u0627 \u0648\u064e\u0627\u0628\u0650\u0644\u065e \u0641\u064e\u0637\u064e\u0644\u0651\u065e\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0628\u064e\u0635\u0650\u064a\u0631\u064c",translation:"Dan perumpamaan orang yang menginfakkan hartanya untuk mencari rida Allah dan untuk memperteguh jiwa mereka, seperti sebuah kebun yang terletak di dataran tinggi yang di siram oleh hujan lebat, maka kebun itu menghasilkan buah-buahan dua kali lipat. Jika hujan lebat tidak menyiraminya, maka embun (pun memadai). Allah Maha Melihat apa yang kamu kerjakan"},{id:266,text:"\u0623\u064e\u064a\u064e\u0648\u064e\u062f\u0651\u064f \u0623\u064e\u062d\u064e\u062f\u064f\u0643\u064f\u0645\u06e1 \u0623\u064e\u0646 \u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0644\u064e\u0647\u064f\u06e5 \u062c\u064e\u0646\u0651\u064e\u0629\u065e \u0645\u0651\u0650\u0646 \u0646\u0651\u064e\u062e\u0650\u064a\u0644\u0656 \u0648\u064e\u0623\u064e\u0639\u06e1\u0646\u064e\u0627\u0628\u0656 \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0645\u0650\u0646 \u062a\u064e\u062d\u06e1\u062a\u0650\u0647\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u064f \u0644\u064e\u0647\u064f\u06e5 \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u0671\u0644\u062b\u0651\u064e\u0645\u064e\u0631\u064e\u0670\u062a\u0650 \u0648\u064e\u0623\u064e\u0635\u064e\u0627\u0628\u064e\u0647\u064f \u0671\u0644\u06e1\u0643\u0650\u0628\u064e\u0631\u064f \u0648\u064e\u0644\u064e\u0647\u064f\u06e5 \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u0629\u065e \u0636\u064f\u0639\u064e\u0641\u064e\u0627\u0653\u0621\u064f \u0641\u064e\u0623\u064e\u0635\u064e\u0627\u0628\u064e\u0647\u064e\u0627\u0653 \u0625\u0650\u0639\u06e1\u0635\u064e\u0627\u0631\u065e \u0641\u0650\u064a\u0647\u0650 \u0646\u064e\u0627\u0631\u065e \u0641\u064e\u0671\u062d\u06e1\u062a\u064e\u0631\u064e\u0642\u064e\u062a\u06e1\u06d7 \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0623\u0653\u064a\u064e\u0670\u062a\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u062a\u064e\u0641\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"(Adakah salah seorang di antara kamu yang ingin memiliki kebun kurma dan anggur yang mengalir di bawahnya sungai-sungai, di sana dia memiliki segala macam buah-buahan, kemudian datanglah masa tuanya sedang dia memiliki keturunan yang masih kecil-kecil. Lalu kebun itu ditiup angin keras yang mengandung api, sehingga terbakar.101) Demikianlah Allah menerangkan ayat-ayat-Nya kepadamu agar kamu memikirkannya"},{id:267,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0641\u0650\u0642\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0637\u064e\u064a\u0651\u0650\u0628\u064e\u0670\u062a\u0650 \u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u06e1\u062a\u064f\u0645\u06e1 \u0648\u064e\u0645\u0650\u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u062e\u06e1\u0631\u064e\u062c\u06e1\u0646\u064e\u0627 \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u064a\u064e\u0645\u0651\u064e\u0645\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u062e\u064e\u0628\u0650\u064a\u062b\u064e \u0645\u0650\u0646\u06e1\u0647\u064f \u062a\u064f\u0646\u0641\u0650\u0642\u064f\u0648\u0646\u064e \u0648\u064e\u0644\u064e\u0633\u06e1\u062a\u064f\u0645 \u0628\u0650\u0640\u0654\u064e\u0627\u062e\u0650\u0630\u0650\u064a\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u062a\u064f\u063a\u06e1\u0645\u0650\u0636\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0647\u0650\u06da \u0648\u064e\u0671\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0646\u0650\u064a\u0651\u064c \u062d\u064e\u0645\u0650\u064a\u062f\u064c",translation:"Wahai orang-orang yang beriman! Infakkanlah sebagian dari hasil usahamu yang baik-baik dan sebagian dari apa yang Kami keluarkan dari bumi untukmu. Janganlah kamu memilih yang buruk untuk kamu keluarkan, padahal kamu sendiri tidak mau mengambilnya melainkan dengan memicingkan mata (enggan) terhadapnya. Dan ketahuilah bahwa Allah Mahakaya, Maha Terpuji"},{id:268,text:"\u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u064f \u064a\u064e\u0639\u0650\u062f\u064f\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0641\u064e\u0642\u06e1\u0631\u064e \u0648\u064e\u064a\u064e\u0623\u06e1\u0645\u064f\u0631\u064f\u0643\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0641\u064e\u062d\u06e1\u0634\u064e\u0627\u0653\u0621\u0650\u06d6 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0639\u0650\u062f\u064f\u0643\u064f\u0645 \u0645\u0651\u064e\u063a\u06e1\u0641\u0650\u0631\u064e\u0629\u0657 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f \u0648\u064e\u0641\u064e\u0636\u06e1\u0644\u0657\u0627\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0670\u0633\u0650\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Setan menjanjikan (menakut-nakuti) kemiskinan kepadamu dan menyuruh kamu berbuat keji (kikir), sedangkan Allah menjanjikan ampunan dan karunia-Nya kepadamu. Dan Allah Mahaluas, Maha Mengetahui"},{id:269,text:"\u064a\u064f\u0624\u06e1\u062a\u0650\u064a \u0671\u0644\u06e1\u062d\u0650\u0643\u06e1\u0645\u064e\u0629\u064e \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0624\u06e1\u062a\u064e \u0671\u0644\u06e1\u062d\u0650\u0643\u06e1\u0645\u064e\u0629\u064e \u0641\u064e\u0642\u064e\u062f\u06e1 \u0623\u064f\u0648\u062a\u0650\u064a\u064e \u062e\u064e\u064a\u06e1\u0631\u0657\u0627 \u0643\u064e\u062b\u0650\u064a\u0631\u0657\u0627\u06d7 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0630\u0651\u064e\u0643\u0651\u064e\u0631\u064f \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064f\u0648\u0652\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0623\u064e\u0644\u06e1\u0628\u064e\u0670\u0628\u0650",translation:"(Dia memberikan hikmah102) kepada siapa yang Dia kehendaki. Barang siapa diberi hikmah, sesungguhnya dia telah diberi kebaikan yang banyak. Dan tidak ada yang dapat mengambil pelajaran kecuali orang-orang yang mempunyai akal sehat"},{id:270,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0641\u064e\u0642\u06e1\u062a\u064f\u0645 \u0645\u0651\u0650\u0646 \u0646\u0651\u064e\u0641\u064e\u0642\u064e\u0629\u064d \u0623\u064e\u0648\u06e1 \u0646\u064e\u0630\u064e\u0631\u06e1\u062a\u064f\u0645 \u0645\u0651\u0650\u0646 \u0646\u0651\u064e\u0630\u06e1\u0631\u0656 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0647\u064f\u06e5\u06d7 \u0648\u064e\u0645\u064e\u0627 \u0644\u0650\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u06e1 \u0623\u064e\u0646\u0635\u064e\u0627\u0631\u064d",translation:"(Dan apa pun infak yang kamu berikan atau nazar103) yang kamu janjikan maka sungguh, Allah mengetahuinya. Dan bagi orang zalim tidak ada seorang penolong pun"},{id:271,text:"\u0625\u0650\u0646 \u062a\u064f\u0628\u06e1\u062f\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u062f\u064e\u0642\u064e\u0670\u062a\u0650 \u0641\u064e\u0646\u0650\u0639\u0650\u0645\u0651\u064e\u0627 \u0647\u0650\u064a\u064e\u06d6 \u0648\u064e\u0625\u0650\u0646 \u062a\u064f\u062e\u06e1\u0641\u064f\u0648\u0647\u064e\u0627 \u0648\u064e\u062a\u064f\u0624\u06e1\u062a\u064f\u0648\u0647\u064e\u0627 \u0671\u0644\u06e1\u0641\u064f\u0642\u064e\u0631\u064e\u0627\u0653\u0621\u064e \u0641\u064e\u0647\u064f\u0648\u064e \u062e\u064e\u064a\u06e1\u0631\u065e \u0644\u0651\u064e\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u064a\u064f\u0643\u064e\u0641\u0651\u0650\u0631\u064f \u0639\u064e\u0646\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0633\u064e\u064a\u0651\u0650\u0640\u0654\u064e\u0627\u062a\u0650\u0643\u064f\u0645\u06e1\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u062e\u064e\u0628\u0650\u064a\u0631\u065e",translation:"(Jika kamu menampakkan sedekah-sedekahmu,104) maka itu baik. Dan jika kamu menyembunyikannya dan memberikannya kepada orang-orang fakir, maka itu lebih baik bagimu dan Allah akan menghapus sebagian kesalahan-kesalahanmu. Dan Allah Mahateliti atas apa yang kamu kerjakan"},{id:272,text:"\u06de\u0644\u0651\u064e\u064a\u06e1\u0633\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0647\u064f\u062f\u064e\u0649\u0670\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0647\u06e1\u062f\u0650\u064a \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06d7 \u0648\u064e\u0645\u064e\u0627 \u062a\u064f\u0646\u0641\u0650\u0642\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1 \u062e\u064e\u064a\u06e1\u0631\u0656 \u0641\u064e\u0644\u0650\u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0645\u064e\u0627 \u062a\u064f\u0646\u0641\u0650\u0642\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0628\u06e1\u062a\u0650\u063a\u064e\u0627\u0653\u0621\u064e \u0648\u064e\u062c\u06e1\u0647\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0648\u064e\u0645\u064e\u0627 \u062a\u064f\u0646\u0641\u0650\u0642\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1 \u062e\u064e\u064a\u06e1\u0631\u0656 \u064a\u064f\u0648\u064e\u0641\u0651\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0644\u064e\u0627 \u062a\u064f\u0638\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Bukanlah kewajibanmu (Muhammad) menjadikan mereka mendapat petunjuk, tetapi Allahlah yang memberi petunjuk kepada siapa yang Dia kehendaki. Apa pun harta yang kamu infakkan, maka (kebaikannya) untuk dirimu sendiri. Dan janganlah kamu berinfak melainkan karena mencari rida Allah. Dan apa pun harta yang kamu infakkan, niscaya kamu akan diberi (pahala) secara penuh dan kamu tidak akan dizalimi (dirugikan)"},{id:273,text:"\u0644\u0650\u0644\u06e1\u0641\u064f\u0642\u064e\u0631\u064e\u0627\u0653\u0621\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u062d\u06e1\u0635\u0650\u0631\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u064e \u0636\u064e\u0631\u06e1\u0628\u0657\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u064a\u064e\u062d\u06e1\u0633\u064e\u0628\u064f\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u062c\u064e\u0627\u0647\u0650\u0644\u064f \u0623\u064e\u063a\u06e1\u0646\u0650\u064a\u064e\u0627\u0653\u0621\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u062a\u0651\u064e\u0639\u064e\u0641\u0651\u064f\u0641\u0650 \u062a\u064e\u0639\u06e1\u0631\u0650\u0641\u064f\u0647\u064f\u0645 \u0628\u0650\u0633\u0650\u064a\u0645\u064e\u0670\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0648\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0625\u0650\u0644\u06e1\u062d\u064e\u0627\u0641\u0657\u0627\u06d7 \u0648\u064e\u0645\u064e\u0627 \u062a\u064f\u0646\u0641\u0650\u0642\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1 \u062e\u064e\u064a\u06e1\u0631\u0656 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u0647\u0650\u06e6 \u0639\u064e\u0644\u0650\u064a\u0645\u064c",translation:"(Apa yang kamu infakkan) adalah untuk orang-orang fakir yang terhalang (usahanya karena jihad) di jalan Allah, sehingga dia yang tidak dapat berusaha di bumi; (orang lain) yang tidak tahu, menyangka bahwa mereka adalah orang-orang kaya karena mereka menjaga diri (dari meminta-minta). Engkau (Muhammad) mengenal mereka dari ciri-cirinya, mereka tidak meminta secara paksa kepada orang lain. Apa pun harta yang baik yang kamu infakkan, sungguh Allah Maha Mengetahui"},{id:274,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0646\u0641\u0650\u0642\u064f\u0648\u0646\u064e \u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u064e\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u0650 \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u0633\u0650\u0631\u0651\u0657\u0627 \u0648\u064e\u0639\u064e\u0644\u064e\u0627\u0646\u0650\u064a\u064e\u0629\u0657 \u0641\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u062c\u06e1\u0631\u064f\u0647\u064f\u0645\u06e1 \u0639\u0650\u0646\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u062e\u064e\u0648\u06e1\u0641\u064c \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u06e1 \u064a\u064e\u062d\u06e1\u0632\u064e\u0646\u064f\u0648\u0646\u064e",translation:"Orang-orang yang menginfakkan hartanya malam dan siang hari (secara) sembunyi-sembunyi maupun terang-terangan, mereka mendapat pahala di sisi Tuhannya. Tidak ada rasa takut pada mereka dan mereka tidak bersedih hati"},{id:275,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f\u0648\u0646\u064e \u0671\u0644\u0631\u0651\u0650\u0628\u064e\u0648\u0670\u0627\u0652 \u0644\u064e\u0627 \u064a\u064e\u0642\u064f\u0648\u0645\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064e\u0645\u064e\u0627 \u064a\u064e\u0642\u064f\u0648\u0645\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064e\u062a\u064e\u062e\u064e\u0628\u0651\u064e\u0637\u064f\u0647\u064f \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064e\u0633\u0651\u0650\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0671\u0644\u06e1\u0628\u064e\u064a\u06e1\u0639\u064f \u0645\u0650\u062b\u06e1\u0644\u064f \u0671\u0644\u0631\u0651\u0650\u0628\u064e\u0648\u0670\u0627\u0652\u06d7 \u0648\u064e\u0623\u064e\u062d\u064e\u0644\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u0628\u064e\u064a\u06e1\u0639\u064e \u0648\u064e\u062d\u064e\u0631\u0651\u064e\u0645\u064e \u0671\u0644\u0631\u0651\u0650\u0628\u064e\u0648\u0670\u0627\u0652\u06da \u0641\u064e\u0645\u064e\u0646 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u06e5 \u0645\u064e\u0648\u06e1\u0639\u0650\u0638\u064e\u0629\u065e \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0647\u0650\u06e6 \u0641\u064e\u0671\u0646\u062a\u064e\u0647\u064e\u0649\u0670 \u0641\u064e\u0644\u064e\u0647\u064f\u06e5 \u0645\u064e\u0627 \u0633\u064e\u0644\u064e\u0641\u064e \u0648\u064e\u0623\u064e\u0645\u06e1\u0631\u064f\u0647\u064f\u06e5\u0653 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0648\u064e\u0645\u064e\u0646\u06e1 \u0639\u064e\u0627\u062f\u064e \u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650\u06d6 \u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u0670\u0644\u0650\u062f\u064f\u0648\u0646\u064e",translation:"(Orang-orang yang memakan riba tidak dapat berdiri melainkan seperti berdirinya orang yang kesurupan setan karena gila.105) Yang demikian itu karena mereka berkata bahwa jual beli itu sama dengan riba. Padahal Allah telah menghalalkan jual beli dan mengharamkan riba. Barang siapa mendapat peringatan dari Tuhannya, lalu dia berhenti, maka apa yang telah di perolehnya dahulu menjadi miliknya106) dan urusannya (terserah) kepada Allah. Barang siapa mengulangi, maka mereka itu penghuni neraka, mereka kekal di dalamnya"},{id:276,text:"\u064a\u064e\u0645\u06e1\u062d\u064e\u0642\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0631\u0651\u0650\u0628\u064e\u0648\u0670\u0627\u0652 \u0648\u064e\u064a\u064f\u0631\u06e1\u0628\u0650\u064a \u0671\u0644\u0635\u0651\u064e\u062f\u064e\u0642\u064e\u0670\u062a\u0650\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0643\u064f\u0644\u0651\u064e \u0643\u064e\u0641\u0651\u064e\u0627\u0631\u064d \u0623\u064e\u062b\u0650\u064a\u0645\u064d",translation:"(Allah memusnahkan riba dan menyuburkan sedekah.107)Allah tidak menyukai setiap orang yang tetap dalam kekafiran dan bergelimang dosa"},{id:277,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0648\u064e\u0623\u064e\u0642\u064e\u0627\u0645\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u0621\u064e\u0627\u062a\u064e\u0648\u064f\u0627\u0652 \u0671\u0644\u0632\u0651\u064e\u0643\u064e\u0648\u0670\u0629\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u062c\u06e1\u0631\u064f\u0647\u064f\u0645\u06e1 \u0639\u0650\u0646\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u062e\u064e\u0648\u06e1\u0641\u064c \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u06e1 \u064a\u064e\u062d\u06e1\u0632\u064e\u0646\u064f\u0648\u0646\u064e",translation:"Sungguh, orang-orang yang beriman, mengerjakan kebajikan, melaksanakan salat dan menunaikan zakat, mereka mendapat pahala di sisi Tuhannya. Tidak ada rasa takut pada mereka dan mereka tidak bersedih hati"},{id:278,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0630\u064e\u0631\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u0628\u064e\u0642\u0650\u064a\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0631\u0651\u0650\u0628\u064e\u0648\u0670\u0653\u0627\u0652 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645 \u0645\u0651\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Wahai orang-orang yang beriman! Bertakwalah kepada Allah dan tinggalkan sisa riba (yang belum dipungut) jika kamu orang beriman"},{id:279,text:"\u0641\u064e\u0625\u0650\u0646 \u0644\u0651\u064e\u0645\u06e1 \u062a\u064e\u0641\u06e1\u0639\u064e\u0644\u064f\u0648\u0627\u0652 \u0641\u064e\u0623\u06e1\u0630\u064e\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u062d\u064e\u0631\u06e1\u0628\u0656 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u0625\u0650\u0646 \u062a\u064f\u0628\u06e1\u062a\u064f\u0645\u06e1 \u0641\u064e\u0644\u064e\u0643\u064f\u0645\u06e1 \u0631\u064f\u0621\u064f\u0648\u0633\u064f \u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u06e1 \u0644\u064e\u0627 \u062a\u064e\u0638\u06e1\u0644\u0650\u0645\u064f\u0648\u0646\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0638\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Jika kamu tidak melaksanakannya, maka umumkanlah perang dari Allah dan Rasul-Nya. Tetapi jika kamu bertobat, maka kamu berhak atas pokok hartamu. Kamu tidak berbuat zalim (merugikan) dan tidak dizalimi (dirugikan)"},{id:280,text:"\u0648\u064e\u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064e \u0630\u064f\u0648 \u0639\u064f\u0633\u06e1\u0631\u064e\u0629\u0656 \u0641\u064e\u0646\u064e\u0638\u0650\u0631\u064e\u0629\u064c \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064e\u064a\u06e1\u0633\u064e\u0631\u064e\u0629\u0656\u06da \u0648\u064e\u0623\u064e\u0646 \u062a\u064e\u0635\u064e\u062f\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u062e\u064e\u064a\u06e1\u0631\u065e \u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan jika (orang berutang itu) dalam kesulitan, maka berilah tenggang waktu sampai dia memperoleh kelapangan. Dan jika kamu menyedekahkan, itu lebih baik bagimu, jika kamu mengetahui"},{id:281,text:"\u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u064a\u064e\u0648\u06e1\u0645\u0657\u0627 \u062a\u064f\u0631\u06e1\u062c\u064e\u0639\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0647\u0650 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u062b\u064f\u0645\u0651\u064e \u062a\u064f\u0648\u064e\u0641\u0651\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u064f \u0646\u064e\u0641\u06e1\u0633\u0656 \u0645\u0651\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064e\u062a\u06e1 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064f\u0638\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan takutlah pada hari (ketika) kamu semua dikembalikan kepada Allah. Kemudian setiap orang diberi balasan yang sempurna sesuai dengan apa yang telah dilakukannya, dan mereka tidak dizalimi (dirugikan)"},{id:282,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0630\u064e\u0627 \u062a\u064e\u062f\u064e\u0627\u064a\u064e\u0646\u062a\u064f\u0645 \u0628\u0650\u062f\u064e\u064a\u06e1\u0646\u064d \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u062c\u064e\u0644\u0656 \u0645\u0651\u064f\u0633\u064e\u0645\u0651\u0657\u0649 \u0641\u064e\u0671\u0643\u06e1\u062a\u064f\u0628\u064f\u0648\u0647\u064f\u06da \u0648\u064e\u0644\u06e1\u064a\u064e\u0643\u06e1\u062a\u064f\u0628 \u0628\u0651\u064e\u064a\u06e1\u0646\u064e\u0643\u064f\u0645\u06e1 \u0643\u064e\u0627\u062a\u0650\u0628\u064f\u06e2 \u0628\u0650\u0671\u0644\u06e1\u0639\u064e\u062f\u06e1\u0644\u0650\u06da \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0623\u06e1\u0628\u064e \u0643\u064e\u0627\u062a\u0650\u0628\u064c \u0623\u064e\u0646 \u064a\u064e\u0643\u06e1\u062a\u064f\u0628\u064e \u0643\u064e\u0645\u064e\u0627 \u0639\u064e\u0644\u0651\u064e\u0645\u064e\u0647\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06da \u0641\u064e\u0644\u06e1\u064a\u064e\u0643\u06e1\u062a\u064f\u0628\u06e1 \u0648\u064e\u0644\u06e1\u064a\u064f\u0645\u06e1\u0644\u0650\u0644\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f \u0648\u064e\u0644\u06e1\u064a\u064e\u062a\u0651\u064e\u0642\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u06e5 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0628\u06e1\u062e\u064e\u0633\u06e1 \u0645\u0650\u0646\u06e1\u0647\u064f \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627\u06da \u0641\u064e\u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f \u0633\u064e\u0641\u0650\u064a\u0647\u064b\u0627 \u0623\u064e\u0648\u06e1 \u0636\u064e\u0639\u0650\u064a\u0641\u064b\u0627 \u0623\u064e\u0648\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0637\u0650\u064a\u0639\u064f \u0623\u064e\u0646 \u064a\u064f\u0645\u0650\u0644\u0651\u064e \u0647\u064f\u0648\u064e \u0641\u064e\u0644\u06e1\u064a\u064f\u0645\u06e1\u0644\u0650\u0644\u06e1 \u0648\u064e\u0644\u0650\u064a\u0651\u064f\u0647\u064f\u06e5 \u0628\u0650\u0671\u0644\u06e1\u0639\u064e\u062f\u06e1\u0644\u0650\u06da \u0648\u064e\u0671\u0633\u06e1\u062a\u064e\u0634\u06e1\u0647\u0650\u062f\u064f\u0648\u0627\u0652 \u0634\u064e\u0647\u0650\u064a\u062f\u064e\u064a\u06e1\u0646\u0650 \u0645\u0650\u0646 \u0631\u0651\u0650\u062c\u064e\u0627\u0644\u0650\u0643\u064f\u0645\u06e1\u06d6 \u0641\u064e\u0625\u0650\u0646 \u0644\u0651\u064e\u0645\u06e1 \u064a\u064e\u0643\u064f\u0648\u0646\u064e\u0627 \u0631\u064e\u062c\u064f\u0644\u064e\u064a\u06e1\u0646\u0650 \u0641\u064e\u0631\u064e\u062c\u064f\u0644\u065e \u0648\u064e\u0671\u0645\u06e1\u0631\u064e\u0623\u064e\u062a\u064e\u0627\u0646\u0650 \u0645\u0650\u0645\u0651\u064e\u0646 \u062a\u064e\u0631\u06e1\u0636\u064e\u0648\u06e1\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0634\u0651\u064f\u0647\u064e\u062f\u064e\u0627\u0653\u0621\u0650 \u0623\u064e\u0646 \u062a\u064e\u0636\u0650\u0644\u0651\u064e \u0625\u0650\u062d\u06e1\u062f\u064e\u0649\u0670\u0647\u064f\u0645\u064e\u0627 \u0641\u064e\u062a\u064f\u0630\u064e\u0643\u0651\u0650\u0631\u064e \u0625\u0650\u062d\u06e1\u062f\u064e\u0649\u0670\u0647\u064f\u0645\u064e\u0627 \u0671\u0644\u06e1\u0623\u064f\u062e\u06e1\u0631\u064e\u0649\u0670\u06da \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0623\u06e1\u0628\u064e \u0671\u0644\u0634\u0651\u064f\u0647\u064e\u062f\u064e\u0627\u0653\u0621\u064f \u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0627 \u062f\u064f\u0639\u064f\u0648\u0627\u0652\u06da \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0633\u06e1\u0640\u0654\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646 \u062a\u064e\u0643\u06e1\u062a\u064f\u0628\u064f\u0648\u0647\u064f \u0635\u064e\u063a\u0650\u064a\u0631\u064b\u0627 \u0623\u064e\u0648\u06e1 \u0643\u064e\u0628\u0650\u064a\u0631\u064b\u0627 \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u062c\u064e\u0644\u0650\u0647\u0650\u06e6\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u06e1 \u0623\u064e\u0642\u06e1\u0633\u064e\u0637\u064f \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0623\u064e\u0642\u06e1\u0648\u064e\u0645\u064f \u0644\u0650\u0644\u0634\u0651\u064e\u0647\u064e\u0670\u062f\u064e\u0629\u0650 \u0648\u064e\u0623\u064e\u062f\u06e1\u0646\u064e\u0649\u0670\u0653 \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064e\u0631\u06e1\u062a\u064e\u0627\u0628\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u062a\u064e\u0643\u064f\u0648\u0646\u064e \u062a\u0650\u062c\u064e\u0670\u0631\u064e\u0629\u064b \u062d\u064e\u0627\u0636\u0650\u0631\u064e\u0629\u0657 \u062a\u064f\u062f\u0650\u064a\u0631\u064f\u0648\u0646\u064e\u0647\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e\u0643\u064f\u0645\u06e1 \u0641\u064e\u0644\u064e\u064a\u06e1\u0633\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u062c\u064f\u0646\u064e\u0627\u062d\u064c \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064e\u0643\u06e1\u062a\u064f\u0628\u064f\u0648\u0647\u064e\u0627\u06d7 \u0648\u064e\u0623\u064e\u0634\u06e1\u0647\u0650\u062f\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0630\u064e\u0627 \u062a\u064e\u0628\u064e\u0627\u064a\u064e\u0639\u06e1\u062a\u064f\u0645\u06e1\u06da \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0636\u064e\u0627\u0653\u0631\u0651\u064e \u0643\u064e\u0627\u062a\u0650\u0628\u065e \u0648\u064e\u0644\u064e\u0627 \u0634\u064e\u0647\u0650\u064a\u062f\u065e\u06da \u0648\u064e\u0625\u0650\u0646 \u062a\u064e\u0641\u06e1\u0639\u064e\u0644\u064f\u0648\u0627\u0652 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0641\u064f\u0633\u064f\u0648\u0642\u064f\u06e2 \u0628\u0650\u0643\u064f\u0645\u06e1\u06d7 \u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e\u06d6 \u0648\u064e\u064a\u064f\u0639\u064e\u0644\u0651\u0650\u0645\u064f\u0643\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Wahai orang-orang yang beriman! Apabila kamu melakukan utang piutang untuk waktu yang ditentukan, hendaklah kamu menuliskannya. Dan hendaklah seorang penulis di antara kamu menuliskannya dengan benar. Janganlah penulis menolak untuk menuliskannya sebagaimana Allah telah mengajarkan kepadanya, maka hendaklah dia menuliskan. Dan hendaklah orang yang berutang itu mendiktekan, dan hendaklah dia bertakwa kepada Allah, Tuhannya, dan janganlah dia mengurangi sedikitpun daripadanya. Jika yang berutang itu orang yang kurang akalnya atau lemah (keadaannya), atau tidak mampu mendiktekan sendiri, maka hendaklah walinya mendiktekannya dengan benar. Dan persaksikanlah dengan dua orang saksi laki-laki diantara kamu. Jika tidak ada (saksi) dua orang laki-laki, maka (boleh) seorang laki-laki dan dua orang perempuan diantara orang-orang yang kamu sukai dari para saksi (yang ada), agar jika yang seorang lupa maka yang lain mengingatkannya. Dan janganlah saksi-saksi itu menolak apabila dipanggil. Dan janganlah kamu bosan menuliskannya, untuk batas waktunya baik (utang itu) kecil maupun besar. Yang demikian itu, lebih adil di sisi Allah, lebih dapat menguatkan kesaksian, dan lebih mendekatkan kamu kepada ketidakraguan, kecuali jika hal itu merupakan perdagangan tunai yang kamu jalankan diantara kamu, maka tidak ada dosa bagi kamu jika kamu tidak menuliskannya. Dan ambillah saksi apabila kamu berjual beli, dan janganlah menulis dipersulit dan begitu juga saksi. Jika kamu lakukan (yang demikian), maka sungguh, hal itu suatu kefasikan pada kamu. Dan bertakwalah kepada Allah, Allah memberikan pengajaran kepadamu, dan Allah Maha Mengetahui segala sesuatu"},{id:283,text:"\u06de\u0648\u064e\u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0633\u064e\u0641\u064e\u0631\u0656 \u0648\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u062c\u0650\u062f\u064f\u0648\u0627\u0652 \u0643\u064e\u0627\u062a\u0650\u0628\u0657\u0627 \u0641\u064e\u0631\u0650\u0647\u064e\u0670\u0646\u065e \u0645\u0651\u064e\u0642\u06e1\u0628\u064f\u0648\u0636\u064e\u0629\u065e\u06d6 \u0641\u064e\u0625\u0650\u0646\u06e1 \u0623\u064e\u0645\u0650\u0646\u064e \u0628\u064e\u0639\u06e1\u0636\u064f\u0643\u064f\u0645 \u0628\u064e\u0639\u06e1\u0636\u0657\u0627 \u0641\u064e\u0644\u06e1\u064a\u064f\u0624\u064e\u062f\u0651\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0671\u0624\u06e1\u062a\u064f\u0645\u0650\u0646\u064e \u0623\u064e\u0645\u064e\u0670\u0646\u064e\u062a\u064e\u0647\u064f\u06e5 \u0648\u064e\u0644\u06e1\u064a\u064e\u062a\u0651\u064e\u0642\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u06e5\u06d7 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u06e1\u062a\u064f\u0645\u064f\u0648\u0627\u0652 \u0671\u0644\u0634\u0651\u064e\u0647\u064e\u0670\u062f\u064e\u0629\u064e\u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0643\u06e1\u062a\u064f\u0645\u06e1\u0647\u064e\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5\u0653 \u0621\u064e\u0627\u062b\u0650\u0645\u065e \u0642\u064e\u0644\u06e1\u0628\u064f\u0647\u064f\u06e5\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Dan jika kamu dalam perjalanan sedang kamu tidak mendapat seorang penulis, maka hendaklah ada barang jaminan yang dipegang. Tetapi, jika sebagian kamu mempercayai sebagian yang lain, hendaklah yang dipercayai itu menunaikan amanatnya (utangnya) dan hendaklah dia bertakwa kepada Allah, Tuhannya. Dan janganlah kamu menyembunyikan kesaksian, karena barang siapa menyembunyikannya, sungguh, hatinya kotor (berdosa). Allah Maha Mengetahui apa yang kamu kerjakan"},{id:284,text:"\u0644\u0651\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d7 \u0648\u064e\u0625\u0650\u0646 \u062a\u064f\u0628\u06e1\u062f\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u0641\u0650\u064a\u0653 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1 \u062a\u064f\u062e\u06e1\u0641\u064f\u0648\u0647\u064f \u064a\u064f\u062d\u064e\u0627\u0633\u0650\u0628\u06e1\u0643\u064f\u0645 \u0628\u0650\u0647\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06d6 \u0641\u064e\u064a\u064e\u063a\u06e1\u0641\u0650\u0631\u064f \u0644\u0650\u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0648\u064e\u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064f \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0642\u064e\u062f\u0650\u064a\u0631\u064c",translation:"Milik Allahlah apa yang ada di langit dan apa yang ada di bumi. Jika kamu nyatakan apa yang ada di dalam hatimu atau kamu sembunyikan, niscaya Allah memperhitungankannya (tentang perbuatan itu) bagimu. Dia mengampuni siapa yang Dia kehendaki dan mengazab siapa yang Dia kehendaki. Allah Mahakuasa atas segala sesuatu"},{id:285,text:"\u0621\u064e\u0627\u0645\u064e\u0646\u064e \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064f \u0628\u0650\u0645\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0647\u0650\u06e6 \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e\u06da \u0643\u064f\u0644\u0651\u064c \u0621\u064e\u0627\u0645\u064e\u0646\u064e \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u062a\u0650\u0647\u0650\u06e6 \u0648\u064e\u0643\u064f\u062a\u064f\u0628\u0650\u0647\u0650\u06e6 \u0648\u064e\u0631\u064f\u0633\u064f\u0644\u0650\u0647\u0650\u06e6 \u0644\u064e\u0627 \u0646\u064f\u0641\u064e\u0631\u0651\u0650\u0642\u064f \u0628\u064e\u064a\u06e1\u0646\u064e \u0623\u064e\u062d\u064e\u062f\u0656 \u0645\u0651\u0650\u0646 \u0631\u0651\u064f\u0633\u064f\u0644\u0650\u0647\u0650\u06e6\u06da \u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0633\u064e\u0645\u0650\u0639\u06e1\u0646\u064e\u0627 \u0648\u064e\u0623\u064e\u0637\u064e\u0639\u06e1\u0646\u064e\u0627\u06d6 \u063a\u064f\u0641\u06e1\u0631\u064e\u0627\u0646\u064e\u0643\u064e \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0671\u0644\u06e1\u0645\u064e\u0635\u0650\u064a\u0631\u064f",translation:"Rasul (Muhammad) beriman kepada apa yang diturunkan kepadanya (Alquran) dari Tuhannya, demikian pula orang-orang yang beriman. Semua beriman kepada Allah, malaikat-malaikat-Nya, kitab-kitab-Nya, dan rasul-rasul-Nya. (Mereka berkata), \"Kami tidak membeda-bedakan seorang pun dari rasul-rasul-Nya.\" Dan mereka berkata, \"Kami dengar dan kami taat. Ampunilah kami Ya Tuhan kami, dan kepada-Mu tempat (kami) kembali"},{id:286,text:"\u0644\u064e\u0627 \u064a\u064f\u0643\u064e\u0644\u0651\u0650\u0641\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0646\u064e\u0641\u06e1\u0633\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0648\u064f\u0633\u06e1\u0639\u064e\u0647\u064e\u0627\u06da \u0644\u064e\u0647\u064e\u0627 \u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064e\u062a\u06e1 \u0648\u064e\u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627 \u0645\u064e\u0627 \u0671\u0643\u06e1\u062a\u064e\u0633\u064e\u0628\u064e\u062a\u06e1\u06d7 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0644\u064e\u0627 \u062a\u064f\u0624\u064e\u0627\u062e\u0650\u0630\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0646 \u0646\u0651\u064e\u0633\u0650\u064a\u0646\u064e\u0627\u0653 \u0623\u064e\u0648\u06e1 \u0623\u064e\u062e\u06e1\u0637\u064e\u0623\u06e1\u0646\u064e\u0627\u06da \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062d\u06e1\u0645\u0650\u0644\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0635\u06e1\u0631\u0657\u0627 \u0643\u064e\u0645\u064e\u0627 \u062d\u064e\u0645\u064e\u0644\u06e1\u062a\u064e\u0647\u064f\u06e5 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0646\u064e\u0627\u06da \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u062d\u064e\u0645\u0651\u0650\u0644\u06e1\u0646\u064e\u0627 \u0645\u064e\u0627 \u0644\u064e\u0627 \u0637\u064e\u0627\u0642\u064e\u0629\u064e \u0644\u064e\u0646\u064e\u0627 \u0628\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u0671\u0639\u06e1\u0641\u064f \u0639\u064e\u0646\u0651\u064e\u0627 \u0648\u064e\u0671\u063a\u06e1\u0641\u0650\u0631\u06e1 \u0644\u064e\u0646\u064e\u0627 \u0648\u064e\u0671\u0631\u06e1\u062d\u064e\u0645\u06e1\u0646\u064e\u0627\u0653\u06da \u0623\u064e\u0646\u062a\u064e \u0645\u064e\u0648\u06e1\u0644\u064e\u0649\u0670\u0646\u064e\u0627 \u0641\u064e\u0671\u0646\u0635\u064f\u0631\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Allah tidak membebani seseorang melainkan sesuai dengan kesanggupannya. Dia mendapat (pahala) dari kebajikan yang dikerjakannya dan dia mendapat (siksa) dari (kejahatan) yang diperbuatnya. (Mereka berdoa), \"Ya Tuhan kami, janganlah Engkau hukum kami jika kami lupa atau kami melakukan kesalahan. Ya Tuhan kami, janganlah Engkau bebani kami dengan beban yang berat sebagaimana Engkau bebankan kepada orang-orang sebelum kami. Ya Tuhan kami, janganlah Engkau pikulkan kepada kami apa yang tidak sanggup kami memikulnya. Maafkanlah kami, ampunilah kami, dan rahmatilah kami. Engkaulah pelindung kami, maka tolonglah kami menghadapi orang-orang kafir"}]},{id:3,name:"\u0622\u0644 \u0639\u0645\u0631\u0627\u0646",transliteration:"Ali 'Imran",translation:"Keluarga Imran",type:"medinan",total_verses:200,verses:[{id:1,text:"\u0627\u0644\u0653\u0645\u0653",translation:"Alif l\u0101m M\u012bm"},{id:2,text:"\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u062d\u064e\u064a\u0651\u064f \u0671\u0644\u06e1\u0642\u064e\u064a\u0651\u064f\u0648\u0645\u064f",translation:"Allah, tidak ada tuhan selain Dia. Yang Mahahidup, Yang terus menerus mengurus (makhluk-Nya)"},{id:3,text:"\u0646\u064e\u0632\u0651\u064e\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0645\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u0657\u0627 \u0644\u0651\u0650\u0645\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u06e1\u0647\u0650 \u0648\u064e\u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0671\u0644\u062a\u0651\u064e\u0648\u06e1\u0631\u064e\u0649\u0670\u0629\u064e \u0648\u064e\u0671\u0644\u06e1\u0625\u0650\u0646\u062c\u0650\u064a\u0644\u064e",translation:"Dia menurunkan Kitab (Alquran) kepadamu (Muhammad) yang mengandung kebenaran, membenarkan (kitab-kitab) sebelumnya, dan Dia menurunkan Taurat dan Injil"},{id:4,text:"\u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f \u0647\u064f\u062f\u0657\u0649 \u0644\u0651\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0671\u0644\u06e1\u0641\u064f\u0631\u06e1\u0642\u064e\u0627\u0646\u064e\u06d7 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u065e \u0634\u064e\u062f\u0650\u064a\u062f\u065e\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0632\u0650\u064a\u0632\u065e \u0630\u064f\u0648 \u0671\u0646\u062a\u0650\u0642\u064e\u0627\u0645\u064d",translation:"(sebelumnya, sebagai petunjuk bagi manusia, dan Dia menurunkan Al-Furqan.110) Sungguh, orang-orang yang ingkar terhadap ayat-ayat Allah akan memperoleh azab yang berat. Allah Mahaperkasa lagi mempunyai balasan (siksa)"},{id:5,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064e\u062e\u06e1\u0641\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0634\u064e\u064a\u06e1\u0621\u065e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0644\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650",translation:"Bagi Allah tidak ada sesuatu pun yang tersembunyi di bumi dan di langit"},{id:6,text:"\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u0635\u064e\u0648\u0651\u0650\u0631\u064f\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u062d\u064e\u0627\u0645\u0650 \u0643\u064e\u064a\u06e1\u0641\u064e \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06da \u0644\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0671\u0644\u06e1\u062d\u064e\u0643\u0650\u064a\u0645\u064f",translation:"Dialah yang membentuk kamu dalam rahim menurut yang Dia kehendaki. Tidak ada tuhan selain Dia. Yang Mahaperkasa, Mahabijaksana"},{id:7,text:"\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0645\u0650\u0646\u06e1\u0647\u064f \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u065e \u0645\u0651\u064f\u062d\u06e1\u0643\u064e\u0645\u064e\u0670\u062a\u064c \u0647\u064f\u0646\u0651\u064e \u0623\u064f\u0645\u0651\u064f \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0648\u064e\u0623\u064f\u062e\u064e\u0631\u064f \u0645\u064f\u062a\u064e\u0634\u064e\u0670\u0628\u0650\u0647\u064e\u0670\u062a\u065e\u06d6 \u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u06e1 \u0632\u064e\u064a\u06e1\u063a\u065e \u0641\u064e\u064a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u062a\u064e\u0634\u064e\u0670\u0628\u064e\u0647\u064e \u0645\u0650\u0646\u06e1\u0647\u064f \u0671\u0628\u06e1\u062a\u0650\u063a\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u06e1\u0641\u0650\u062a\u06e1\u0646\u064e\u0629\u0650 \u0648\u064e\u0671\u0628\u06e1\u062a\u0650\u063a\u064e\u0627\u0653\u0621\u064e \u062a\u064e\u0623\u06e1\u0648\u0650\u064a\u0644\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u062a\u064e\u0623\u06e1\u0648\u0650\u064a\u0644\u064e\u0647\u064f\u06e5\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06d7 \u0648\u064e\u0671\u0644\u0631\u0651\u064e\u0640\u0670\u0633\u0650\u062e\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0639\u0650\u0644\u06e1\u0645\u0650 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0647\u0650\u06e6 \u0643\u064f\u0644\u0651\u065e \u0645\u0651\u0650\u0646\u06e1 \u0639\u0650\u0646\u062f\u0650 \u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627\u06d7 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0630\u0651\u064e\u0643\u0651\u064e\u0631\u064f \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064f\u0648\u0652\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0623\u064e\u0644\u06e1\u0628\u064e\u0670\u0628\u0650",translation:"Dialah yang menurunkan Kitab (Alquran) kepadamu (Muhammad). Di antaranya ada ayat-ayat yang mu\u1e25kam\u0101t,111) itulah pokok-pokok Kitab (Alquran) dan yang lain mutasy\u0101bih\u0101t.112) Adapun orang-orang yang dalam hatinya condong pada kesesatan, mereka mengikuti yang mutasy\u0101bih\u0101t untuk mencari-cari fitnah dan untuk mencari-cari takwilnya, padahal tidak ada yang mengetahui takwilnya kecuali Allah. Dan orang-orang yang ilmunya mendalam berkata, \"Kami beriman kepadanya (Alquran), semuanya dari sisi Tuhan kami.\" Tidak ada yang dapat mengambil pelajaran kecuali orang yang berakal"},{id:8,text:"\u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0644\u064e\u0627 \u062a\u064f\u0632\u0650\u063a\u06e1 \u0642\u064f\u0644\u064f\u0648\u0628\u064e\u0646\u064e\u0627 \u0628\u064e\u0639\u06e1\u062f\u064e \u0625\u0650\u0630\u06e1 \u0647\u064e\u062f\u064e\u064a\u06e1\u062a\u064e\u0646\u064e\u0627 \u0648\u064e\u0647\u064e\u0628\u06e1 \u0644\u064e\u0646\u064e\u0627 \u0645\u0650\u0646 \u0644\u0651\u064e\u062f\u064f\u0646\u0643\u064e \u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u064b\u06da \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0623\u064e\u0646\u062a\u064e \u0671\u0644\u06e1\u0648\u064e\u0647\u0651\u064e\u0627\u0628\u064f",translation:"(Mereka berdoa), \"Ya Tuhan kami, janganlah Engkau condongkan hati kami kepada kesesatan setelah Engkau berikan petunjuk kepada kami, dan karuniakanlah kepada kami rahmat dari sisi-Mu, sesungguhnya Engkau Maha Pemberi"},{id:9,text:"\u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u062c\u064e\u0627\u0645\u0650\u0639\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u0650\u064a\u064e\u0648\u06e1\u0645\u0656 \u0644\u0651\u064e\u0627 \u0631\u064e\u064a\u06e1\u0628\u064e \u0641\u0650\u064a\u0647\u0650\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064f\u062e\u06e1\u0644\u0650\u0641\u064f \u0671\u0644\u06e1\u0645\u0650\u064a\u0639\u064e\u0627\u062f\u064e",translation:"Ya Tuhan kami, Engkaulah yang mengumpulkan manusia pada hari yang tidak ada keraguan padanya.\" Sungguh, Allah tidak menyalahi janji"},{id:10,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0644\u064e\u0646 \u062a\u064f\u063a\u06e1\u0646\u0650\u064a\u064e \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064e\u0648\u06e1\u0644\u064e\u0670\u062f\u064f\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627\u06d6 \u0648\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u06e1 \u0648\u064e\u0642\u064f\u0648\u062f\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650",translation:"Sesungguhnya orang-orang yang kafir, bagi mereka tidak akan berguna sedikit pun harta benda dan anak-anak mereka terhadap (azab) Allah. Dan mereka itu (menjadi) bahan bakar api neraka"},{id:11,text:"\u0643\u064e\u062f\u064e\u0623\u06e1\u0628\u0650 \u0621\u064e\u0627\u0644\u0650 \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u0645\u06e1\u06da \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0641\u064e\u0623\u064e\u062e\u064e\u0630\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0630\u064f\u0646\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u06e1\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0634\u064e\u062f\u0650\u064a\u062f\u064f \u0671\u0644\u06e1\u0639\u0650\u0642\u064e\u0627\u0628\u0650",translation:"(Keadaan mereka) seperti keadaan pengikut Fir'aun dan orang-orang yang sebelum mereka. Mereka mendustakan ayat-ayat Kami, maka Allah menyiksa mereka disebabkan dosa-dosanya. Allah sangat berat hukuman-Nya"},{id:12,text:"\u0642\u064f\u0644 \u0644\u0651\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0633\u064e\u062a\u064f\u063a\u06e1\u0644\u064e\u0628\u064f\u0648\u0646\u064e \u0648\u064e\u062a\u064f\u062d\u06e1\u0634\u064e\u0631\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e\u06d6 \u0648\u064e\u0628\u0650\u0626\u06e1\u0633\u064e \u0671\u0644\u06e1\u0645\u0650\u0647\u064e\u0627\u062f\u064f",translation:"Katakanlah (Muhammad) kepada orang-orang yang kafir, \"Kamu (pasti) akan dikalahkan dan digiring ke dalam neraka Jahanam. Dan itulah seburuk-buruk tempat tinggal"},{id:13,text:"\u0642\u064e\u062f\u06e1 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u06e1 \u0621\u064e\u0627\u064a\u064e\u0629\u065e \u0641\u0650\u064a \u0641\u0650\u0626\u064e\u062a\u064e\u064a\u06e1\u0646\u0650 \u0671\u0644\u06e1\u062a\u064e\u0642\u064e\u062a\u064e\u0627\u06d6 \u0641\u0650\u0626\u064e\u0629\u065e \u062a\u064f\u0642\u064e\u0670\u062a\u0650\u0644\u064f \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0623\u064f\u062e\u06e1\u0631\u064e\u0649\u0670 \u0643\u064e\u0627\u0641\u0650\u0631\u064e\u0629\u065e \u064a\u064e\u0631\u064e\u0648\u06e1\u0646\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u062b\u06e1\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0631\u064e\u0623\u06e1\u064a\u064e \u0671\u0644\u06e1\u0639\u064e\u064a\u06e1\u0646\u0650\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064f\u0624\u064e\u064a\u0651\u0650\u062f\u064f \u0628\u0650\u0646\u064e\u0635\u06e1\u0631\u0650\u0647\u0650\u06e6 \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0639\u0650\u0628\u06e1\u0631\u064e\u0629\u0657 \u0644\u0651\u0650\u0623\u064f\u0648\u0652\u0644\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0628\u06e1\u0635\u064e\u0670\u0631\u0650",translation:"(Sungguh, telah ada tanda bagi kamu pada dua golongan yang berhadap-hadapan.113) Satu golongan berperang di jalan Allah dan yang lain (golongan) kafir yang melihat dengan mata kepala, bahwa mereka (golongan muslim) dua kali lipat mereka. Allah menguatkan dengan pertolongan-Nya siapa saja yang Dia kehendaki. Sungguh, pada yang demikian itu terdapat pelajaran bagi orang-orang yang mempunyai penglihatan (mata hati)"},{id:14,text:"\u0632\u064f\u064a\u0651\u0650\u0646\u064e \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u062d\u064f\u0628\u0651\u064f \u0671\u0644\u0634\u0651\u064e\u0647\u064e\u0648\u064e\u0670\u062a\u0650 \u0645\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0653\u0621\u0650 \u0648\u064e\u0671\u0644\u06e1\u0628\u064e\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u0642\u064e\u0646\u064e\u0670\u0637\u0650\u064a\u0631\u0650 \u0671\u0644\u06e1\u0645\u064f\u0642\u064e\u0646\u0637\u064e\u0631\u064e\u0629\u0650 \u0645\u0650\u0646\u064e \u0671\u0644\u0630\u0651\u064e\u0647\u064e\u0628\u0650 \u0648\u064e\u0671\u0644\u06e1\u0641\u0650\u0636\u0651\u064e\u0629\u0650 \u0648\u064e\u0671\u0644\u06e1\u062e\u064e\u064a\u06e1\u0644\u0650 \u0671\u0644\u06e1\u0645\u064f\u0633\u064e\u0648\u0651\u064e\u0645\u064e\u0629\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0639\u064e\u0670\u0645\u0650 \u0648\u064e\u0671\u0644\u06e1\u062d\u064e\u0631\u06e1\u062b\u0650\u06d7 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u064e\u062a\u064e\u0670\u0639\u064f \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u0650 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627\u06d6 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u0650\u0646\u062f\u064e\u0647\u064f\u06e5 \u062d\u064f\u0633\u06e1\u0646\u064f \u0671\u0644\u06e1\u0645\u064e\u0640\u0654\u064e\u0627\u0628\u0650",translation:"(Dijadikan tampak indah dalam pandangan manusia cinta terhadap nafsu, berupa wanita-wanita, anak-anak, harta benda yang bertumpuk dalam bentuk emas dan perak, kuda pilihan, hewan ternak114) dan sawah ladang. Itulah kesenangan hidup di dunia, dan di sisi Allahlah tempat kembali yang baik"},{id:15,text:"\u06de\u0642\u064f\u0644\u06e1 \u0623\u064e\u0624\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0643\u064f\u0645 \u0628\u0650\u062e\u064e\u064a\u06e1\u0631\u0656 \u0645\u0651\u0650\u0646 \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u06e1\u06d6 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u062a\u0651\u064e\u0642\u064e\u0648\u06e1\u0627\u0652 \u0639\u0650\u0646\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u065e \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0645\u0650\u0646 \u062a\u064e\u062d\u06e1\u062a\u0650\u0647\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u064f \u062e\u064e\u0670\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u065e \u0645\u0651\u064f\u0637\u064e\u0647\u0651\u064e\u0631\u064e\u0629\u065e \u0648\u064e\u0631\u0650\u0636\u06e1\u0648\u064e\u0670\u0646\u065e \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u064e\u0635\u0650\u064a\u0631\u064f\u06e2 \u0628\u0650\u0671\u0644\u06e1\u0639\u0650\u0628\u064e\u0627\u062f\u0650",translation:"Katakanlah, \"Maukah aku kabarkan kepadamu apa yang lebih baik dari yang demikian itu?\" Bagi orang-orang yang bertakwa (tersedia) di sisi Tuhan mereka surga-surga yang mengalir di bawahnya sungai-sungai, mereka kekal di dalamnya, dan pasangan-pasangan yang suci, serta rida Allah. Dan Allah Maha Melihat hamba-hamba-Nya"},{id:16,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0646\u064e\u0627\u0653 \u0621\u064e\u0627\u0645\u064e\u0646\u0651\u064e\u0627 \u0641\u064e\u0671\u063a\u06e1\u0641\u0650\u0631\u06e1 \u0644\u064e\u0646\u064e\u0627 \u0630\u064f\u0646\u064f\u0648\u0628\u064e\u0646\u064e\u0627 \u0648\u064e\u0642\u0650\u0646\u064e\u0627 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650",translation:"(Yaitu) orang-orang yang berdoa, \"Ya Tuhan kami, kami benar-benar beriman, maka ampunilah dosa-dosa kami dan lindungilah kami dari azab neraka"},{id:17,text:"\u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0628\u0650\u0631\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u0635\u0651\u064e\u0640\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u0642\u064e\u0670\u0646\u0650\u062a\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0646\u0641\u0650\u0642\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0633\u06e1\u062a\u064e\u063a\u06e1\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0628\u0650\u0671\u0644\u06e1\u0623\u064e\u0633\u06e1\u062d\u064e\u0627\u0631\u0650",translation:"(Juga) orang yang sabar, orang yang jujur, orang yang taat, orang yang menginfakkan hartanya, dan orang yang memohon ampunan pada waktu sebelum fajar"},{id:18,text:"\u0634\u064e\u0647\u0650\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u064f \u0648\u064e\u0623\u064f\u0648\u0652\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0639\u0650\u0644\u06e1\u0645\u0650 \u0642\u064e\u0627\u0653\u0626\u0650\u0645\u064e\u06e2\u0627 \u0628\u0650\u0671\u0644\u06e1\u0642\u0650\u0633\u06e1\u0637\u0650\u06da \u0644\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0671\u0644\u06e1\u062d\u064e\u0643\u0650\u064a\u0645\u064f",translation:"Allah menyatakan bahwa tidak ada tuhan selain Dia; (demikian pula) para malaikat dan orang berilmu yang menegakkan keadilan, tidak ada tuhan selain Dia,Yang Mahaperkasa, Mahabijaksana"},{id:19,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u064e \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u0625\u0650\u0633\u06e1\u0644\u064e\u0670\u0645\u064f\u06d7 \u0648\u064e\u0645\u064e\u0627 \u0671\u062e\u06e1\u062a\u064e\u0644\u064e\u0641\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0645\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0639\u0650\u0644\u06e1\u0645\u064f \u0628\u064e\u063a\u06e1\u064a\u064e\u06e2\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1\u06d7 \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0643\u06e1\u0641\u064f\u0631\u06e1 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0633\u064e\u0631\u0650\u064a\u0639\u064f \u0671\u0644\u06e1\u062d\u0650\u0633\u064e\u0627\u0628\u0650",translation:"(Sesungguhnya agama di sisi Allah ialah Islam. Tidaklah berselisih orang-orang yang telah diberi Kitab115) kecuali setelah mereka memperoleh ilmu, karena kedengkian di antara mereka. Barang siapa ingkar terhadap ayat-ayat Allah, maka sungguh, Allah sangat cepat perhitungan-Nya"},{id:20,text:"\u0641\u064e\u0625\u0650\u0646\u06e1 \u062d\u064e\u0627\u0653\u062c\u0651\u064f\u0648\u0643\u064e \u0641\u064e\u0642\u064f\u0644\u06e1 \u0623\u064e\u0633\u06e1\u0644\u064e\u0645\u06e1\u062a\u064f \u0648\u064e\u062c\u06e1\u0647\u0650\u064a\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u064e\u0646\u0650 \u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064e\u0646\u0650\u06d7 \u0648\u064e\u0642\u064f\u0644 \u0644\u0651\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0648\u064e\u0671\u0644\u06e1\u0623\u064f\u0645\u0651\u0650\u064a\u0651\u0650\u0640\u06e7\u0646\u064e \u0621\u064e\u0623\u064e\u0633\u06e1\u0644\u064e\u0645\u06e1\u062a\u064f\u0645\u06e1\u06da \u0641\u064e\u0625\u0650\u0646\u06e1 \u0623\u064e\u0633\u06e1\u0644\u064e\u0645\u064f\u0648\u0627\u0652 \u0641\u064e\u0642\u064e\u062f\u0650 \u0671\u0647\u06e1\u062a\u064e\u062f\u064e\u0648\u0627\u0652\u06d6 \u0648\u0651\u064e\u0625\u0650\u0646 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u06e1\u0627\u0652 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0671\u0644\u06e1\u0628\u064e\u0644\u064e\u0670\u063a\u064f\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u064e\u0635\u0650\u064a\u0631\u064f\u06e2 \u0628\u0650\u0671\u0644\u06e1\u0639\u0650\u0628\u064e\u0627\u062f\u0650",translation:"Kemudian jika mereka membantah engkau (Muhammad) katakanlah, \"Aku berserah diri kepada Allah dan (demikian pula) orang-orang yang mengikutiku.\" Dan katakanlah kepada orang-orang yang telah diberi Kitab dan kepada orang-orang buta huruf,116) \"Sudahkah kamu masuk Islam?\" Jika mereka masuk Islam, berarti mereka telah mendapat petunjuk, tetapi jika mereka berpaling, maka kewajibanmu hanyalah menyampaikan. Dan Allah Maha Melihat hamba-hamba-Nya"},{id:21,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0643\u06e1\u0641\u064f\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u064a\u064e\u0642\u06e1\u062a\u064f\u0644\u064f\u0648\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650\u0640\u06e7\u0646\u064e \u0628\u0650\u063a\u064e\u064a\u06e1\u0631\u0650 \u062d\u064e\u0642\u0651\u0656 \u0648\u064e\u064a\u064e\u0642\u06e1\u062a\u064f\u0644\u064f\u0648\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0623\u06e1\u0645\u064f\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u06e1\u0642\u0650\u0633\u06e1\u0637\u0650 \u0645\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0641\u064e\u0628\u064e\u0634\u0651\u0650\u0631\u06e1\u0647\u064f\u0645 \u0628\u0650\u0639\u064e\u0630\u064e\u0627\u0628\u064d \u0623\u064e\u0644\u0650\u064a\u0645\u064d",translation:"Sesungguhnya orang-orang yang mengingkari ayat-ayat Allah dan membunuh para nabi tanpa hak (alasan yang benar) dan membunuh orang-orang yang menyuruh manusia berbuat adil, sampaikanlah kepada mereka kabar gembira yaitu azab yang pedih"},{id:22,text:"\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062d\u064e\u0628\u0650\u0637\u064e\u062a\u06e1 \u0623\u064e\u0639\u06e1\u0645\u064e\u0670\u0644\u064f\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0648\u064e\u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0646\u0651\u064e\u0640\u0670\u0635\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Mereka itulah orang-orang yang sia-sia pekerjaannya di dunia dan di akhirat, dan mereka tidak punya penolong"},{id:23,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0631\u064e \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627\u0652 \u0646\u064e\u0635\u0650\u064a\u0628\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u064a\u064f\u062f\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u0650\u064a\u064e\u062d\u06e1\u0643\u064f\u0645\u064e \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1 \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649\u0670 \u0641\u064e\u0631\u0650\u064a\u0642\u065e \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0648\u064e\u0647\u064f\u0645 \u0645\u0651\u064f\u0639\u06e1\u0631\u0650\u0636\u064f\u0648\u0646\u064e",translation:"Tidaklah engkau memperhatikan orang-orang yang telah diberi bagian Kitab (Taurat)? Mereka diajak (berpegang) pada Kitab Allah untuk memutuskan (perkara) di antara mereka. Kemudian sebagian dari mereka berpaling seraya menolak (kebenaran)"},{id:24,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0646 \u062a\u064e\u0645\u064e\u0633\u0651\u064e\u0646\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u064f \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u0657\u0627 \u0645\u0651\u064e\u0639\u06e1\u062f\u064f\u0648\u062f\u064e\u0670\u062a\u0656\u06d6 \u0648\u064e\u063a\u064e\u0631\u0651\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u062f\u0650\u064a\u0646\u0650\u0647\u0650\u0645 \u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0641\u06e1\u062a\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Hal itu adalah karena mereka berkata, \"Api neraka tidak akan menyentuh kami kecuali beberapa hari saja.\" Mereka terpedaya dalam agama mereka oleh apa yang mereka ada-adakan"},{id:25,text:"\u0641\u064e\u0643\u064e\u064a\u06e1\u0641\u064e \u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0645\u064e\u0639\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0644\u0650\u064a\u064e\u0648\u06e1\u0645\u0656 \u0644\u0651\u064e\u0627 \u0631\u064e\u064a\u06e1\u0628\u064e \u0641\u0650\u064a\u0647\u0650 \u0648\u064e\u0648\u064f\u0641\u0651\u0650\u064a\u064e\u062a\u06e1 \u0643\u064f\u0644\u0651\u064f \u0646\u064e\u0641\u06e1\u0633\u0656 \u0645\u0651\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064e\u062a\u06e1 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064f\u0638\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Bagaimana jika (nanti) mereka Kami kumpulkan pada hari (Kiamat) yang tidak diragukan kejadiannya dan kepada setiap jiwa diberi balasan yang sempurna sesuai dengan apa yang telah dikerjakannya dan mereka tidak dizalimi (dirugikan)"},{id:26,text:"\u0642\u064f\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0645\u064e\u0670\u0644\u0650\u0643\u064e \u0671\u0644\u06e1\u0645\u064f\u0644\u06e1\u0643\u0650 \u062a\u064f\u0624\u06e1\u062a\u0650\u064a \u0671\u0644\u06e1\u0645\u064f\u0644\u06e1\u0643\u064e \u0645\u064e\u0646 \u062a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0648\u064e\u062a\u064e\u0646\u0632\u0650\u0639\u064f \u0671\u0644\u06e1\u0645\u064f\u0644\u06e1\u0643\u064e \u0645\u0650\u0645\u0651\u064e\u0646 \u062a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0648\u064e\u062a\u064f\u0639\u0650\u0632\u0651\u064f \u0645\u064e\u0646 \u062a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0648\u064e\u062a\u064f\u0630\u0650\u0644\u0651\u064f \u0645\u064e\u0646 \u062a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06d6 \u0628\u0650\u064a\u064e\u062f\u0650\u0643\u064e \u0671\u0644\u06e1\u062e\u064e\u064a\u06e1\u0631\u064f\u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0642\u064e\u062f\u0650\u064a\u0631\u065e",translation:"Katakanlah (Muhammad), \"Wahai Tuhan pemilik kekuasaan, Engkau berikan kekuasaan kapada siapa pun yang Engkau kehendaki, dan Engkau cabut kekuasaan dari siapa pun yang Engkau kehendaki. Engkau muliakan siapa pun yang Engkau kehendaki dan Engkau hinakan siapa pun yang Engkau kehendaki. Di tangan-Mu lah segala kebajikan. Sungguh, Engkau Mahakuasa atas segala sesuatu"},{id:27,text:"\u062a\u064f\u0648\u0644\u0650\u062c\u064f \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u064e \u0641\u0650\u064a \u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u0648\u064e\u062a\u064f\u0648\u0644\u0650\u062c\u064f \u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u0641\u0650\u064a \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u0650\u06d6 \u0648\u064e\u062a\u064f\u062e\u06e1\u0631\u0650\u062c\u064f \u0671\u0644\u06e1\u062d\u064e\u064a\u0651\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064e\u064a\u0651\u0650\u062a\u0650 \u0648\u064e\u062a\u064f\u062e\u06e1\u0631\u0650\u062c\u064f \u0671\u0644\u06e1\u0645\u064e\u064a\u0651\u0650\u062a\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u062d\u064e\u064a\u0651\u0650\u06d6 \u0648\u064e\u062a\u064e\u0631\u06e1\u0632\u064f\u0642\u064f \u0645\u064e\u0646 \u062a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0628\u0650\u063a\u064e\u064a\u06e1\u0631\u0650 \u062d\u0650\u0633\u064e\u0627\u0628\u0656",translation:"(Engkau masukkan malam ke dalam siang dan Engkau masukkan siang ke dalam malam. Dan Engkau keluarkan yang hidup dari yang mati, dan Engkau keluarkan yang mati dari yang hidup.117) Dan Engkau berikan rezeki kepada siapa yang Engkau kehendaki tanpa perhitungan"},{id:28,text:"\u0644\u0651\u064e\u0627 \u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u0650 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0623\u064e\u0648\u06e1\u0644\u0650\u064a\u064e\u0627\u0653\u0621\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e\u06d6 \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0641\u06e1\u0639\u064e\u0644\u06e1 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u0644\u064e\u064a\u06e1\u0633\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u0650\u064a \u0634\u064e\u064a\u06e1\u0621\u064d \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u062a\u064f\u0642\u064e\u0649\u0670\u0629\u0657\u06d7 \u0648\u064e\u064a\u064f\u062d\u064e\u0630\u0651\u0650\u0631\u064f\u0643\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0646\u064e\u0641\u06e1\u0633\u064e\u0647\u064f\u06e5\u06d7 \u0648\u064e\u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u0645\u064e\u0635\u0650\u064a\u0631\u064f",translation:"Janganlah orang-orang beriman menjadikan orang kafir sebagai pemimpin, melainkan orang-orang beriman. Barang siapa berbuat demikian, niscaya dia tidak akan memperoleh apa pun dari Allah, kecuali karena (siasat) menjaga diri dari sesuatu yang kamu takuti dari mereka. Dan Allah memperingatkan kamu akan diri (siksa)-Nya dan hanya kepada Allah tempat kembali"},{id:29,text:"\u0642\u064f\u0644\u06e1 \u0625\u0650\u0646 \u062a\u064f\u062e\u06e1\u0641\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u0641\u0650\u064a \u0635\u064f\u062f\u064f\u0648\u0631\u0650\u0643\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1 \u062a\u064f\u0628\u06e1\u062f\u064f\u0648\u0647\u064f \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u06e1\u0647\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06d7 \u0648\u064e\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0642\u064e\u062f\u0650\u064a\u0631\u065e",translation:"Katakanlah, \"Jika kamu sembunyikan apa yang ada dalam hatimu atau kamu nyatakan, Allah pasti mengetahuinya.\" Dia mengetahui apa yang ada di langit dan apa yang ada di bumi. Allah Mahakuasa atas segala sesuatu"},{id:30,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u062a\u064e\u062c\u0650\u062f\u064f \u0643\u064f\u0644\u0651\u064f \u0646\u064e\u0641\u06e1\u0633\u0656 \u0645\u0651\u064e\u0627 \u0639\u064e\u0645\u0650\u0644\u064e\u062a\u06e1 \u0645\u0650\u0646\u06e1 \u062e\u064e\u064a\u06e1\u0631\u0656 \u0645\u0651\u064f\u062d\u06e1\u0636\u064e\u0631\u0657\u0627 \u0648\u064e\u0645\u064e\u0627 \u0639\u064e\u0645\u0650\u0644\u064e\u062a\u06e1 \u0645\u0650\u0646 \u0633\u064f\u0648\u0653\u0621\u0656 \u062a\u064e\u0648\u064e\u062f\u0651\u064f \u0644\u064e\u0648\u06e1 \u0623\u064e\u0646\u0651\u064e \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064e\u0627 \u0648\u064e\u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u0645\u064e\u062f\u064e\u06e2\u0627 \u0628\u064e\u0639\u0650\u064a\u062f\u0657\u0627\u06d7 \u0648\u064e\u064a\u064f\u062d\u064e\u0630\u0651\u0650\u0631\u064f\u0643\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0646\u064e\u0641\u06e1\u0633\u064e\u0647\u064f\u06e5\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0631\u064e\u0621\u064f\u0648\u0641\u064f\u06e2 \u0628\u0650\u0671\u0644\u06e1\u0639\u0650\u0628\u064e\u0627\u062f\u0650",translation:"(Ingatlah) pada hari (ketika) setiap jiwa mendapatkan (balasan) atas kebajikan yang telah dikerjakan ada dihadapannya, (begitu juga balasan) atas kejahatan yang telah dia kerjakan. Dia berharap sekiranya ada jarak yang jauh antara dia dengan (hari) itu. Dan Allah memperingatkan kamu akan diri (siksa)-Nya. Allah Maha Penyayang terhadap hamba-hamba-Nya"},{id:31,text:"\u0642\u064f\u0644\u06e1 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064f\u062d\u0650\u0628\u0651\u064f\u0648\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0641\u064e\u0671\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0646\u0650\u064a \u064a\u064f\u062d\u06e1\u0628\u0650\u0628\u06e1\u0643\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u064a\u064e\u063a\u06e1\u0641\u0650\u0631\u06e1 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0630\u064f\u0646\u064f\u0648\u0628\u064e\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u065e",translation:"Katakanlah (Muhammad), \"Jika kamu mencintai Allah, ikutilah aku, niscaya Allah mencintaimu dan mengampuni dosa-dosamu.\" Allah Maha Pengampun, Maha Penyayang"},{id:32,text:"\u0642\u064f\u0644\u06e1 \u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e\u06d6 \u0641\u064e\u0625\u0650\u0646 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u06e1\u0627\u0652 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Katakanlah (Muhammad), \"Taatilah Allah dan Rasul. Jika kamu berpaling, ketahuilah bahwa Allah tidak menyukai orang-orang kafir"},{id:33,text:"\u06de\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0671\u0635\u06e1\u0637\u064e\u0641\u064e\u0649\u0670\u0653 \u0621\u064e\u0627\u062f\u064e\u0645\u064e \u0648\u064e\u0646\u064f\u0648\u062d\u0657\u0627 \u0648\u064e\u0621\u064e\u0627\u0644\u064e \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064e \u0648\u064e\u0621\u064e\u0627\u0644\u064e \u0639\u0650\u0645\u06e1\u0631\u064e\u0670\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Sesungguhnya Allah telah memilih Adam, Nuh, keluarga Ibrahim dan keluarga Imran melebihi segala umat (pada masa masing-masing)"},{id:34,text:"\u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u0629\u064e\u06e2 \u0628\u064e\u0639\u06e1\u0636\u064f\u0647\u064e\u0627 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u0636\u0656\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0633\u064e\u0645\u0650\u064a\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u064c",translation:"(sebagai) satu keturunan, sebagiannya adalah (keturunan) dari sebagian yang lain. Allah Maha Mendengar, Maha Mengetahui"},{id:35,text:"\u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e\u062a\u0650 \u0671\u0645\u06e1\u0631\u064e\u0623\u064e\u062a\u064f \u0639\u0650\u0645\u06e1\u0631\u064e\u0670\u0646\u064e \u0631\u064e\u0628\u0651\u0650 \u0625\u0650\u0646\u0651\u0650\u064a \u0646\u064e\u0630\u064e\u0631\u06e1\u062a\u064f \u0644\u064e\u0643\u064e \u0645\u064e\u0627 \u0641\u0650\u064a \u0628\u064e\u0637\u06e1\u0646\u0650\u064a \u0645\u064f\u062d\u064e\u0631\u0651\u064e\u0631\u0657\u0627 \u0641\u064e\u062a\u064e\u0642\u064e\u0628\u0651\u064e\u0644\u06e1 \u0645\u0650\u0646\u0651\u0650\u064a\u0653\u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0623\u064e\u0646\u062a\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u0650\u064a\u0639\u064f \u0671\u0644\u06e1\u0639\u064e\u0644\u0650\u064a\u0645\u064f",translation:"(Ingatlah), ketika istri Imran berkata, \"Ya Tuhanku, sesungguhnya aku bernazar kepada-Mu, agar (janin) yang dalam kandunganku (kelak) menjadi hamba yang mengabdi (kepada-Mu), maka terimalah (nazar itu) dariku. Sungguh, Engkaulah Yang Maha Mendengar, Maha Mengetahui"},{id:36,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0648\u064e\u0636\u064e\u0639\u064e\u062a\u06e1\u0647\u064e\u0627 \u0642\u064e\u0627\u0644\u064e\u062a\u06e1 \u0631\u064e\u0628\u0651\u0650 \u0625\u0650\u0646\u0651\u0650\u064a \u0648\u064e\u0636\u064e\u0639\u06e1\u062a\u064f\u0647\u064e\u0627\u0653 \u0623\u064f\u0646\u062b\u064e\u0649\u0670 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u0648\u064e\u0636\u064e\u0639\u064e\u062a\u06e1 \u0648\u064e\u0644\u064e\u064a\u06e1\u0633\u064e \u0671\u0644\u0630\u0651\u064e\u0643\u064e\u0631\u064f \u0643\u064e\u0671\u0644\u06e1\u0623\u064f\u0646\u062b\u064e\u0649\u0670\u06d6 \u0648\u064e\u0625\u0650\u0646\u0651\u0650\u064a \u0633\u064e\u0645\u0651\u064e\u064a\u06e1\u062a\u064f\u0647\u064e\u0627 \u0645\u064e\u0631\u06e1\u064a\u064e\u0645\u064e \u0648\u064e\u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064f\u0639\u0650\u064a\u0630\u064f\u0647\u064e\u0627 \u0628\u0650\u0643\u064e \u0648\u064e\u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u062a\u064e\u0647\u064e\u0627 \u0645\u0650\u0646\u064e \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u0650 \u0671\u0644\u0631\u0651\u064e\u062c\u0650\u064a\u0645\u0650",translation:"Maka ketika melahirkannya, dia berkata, \"Ya Tuhanku, aku telah melahirkan anak perempuan.\" Padahal Allah lebih tahu apa yang dia lahirkan, dan laki-laki tidak sama dengan perempuan. \"Dan aku memberinya nama Maryam, dan aku mohon perlindungan-Mu untuknya dan anak cucunya dari (gangguan) setan yang terkutuk"},{id:37,text:"\u0641\u064e\u062a\u064e\u0642\u064e\u0628\u0651\u064e\u0644\u064e\u0647\u064e\u0627 \u0631\u064e\u0628\u0651\u064f\u0647\u064e\u0627 \u0628\u0650\u0642\u064e\u0628\u064f\u0648\u0644\u064d \u062d\u064e\u0633\u064e\u0646\u0656 \u0648\u064e\u0623\u064e\u0646\u06e2\u0628\u064e\u062a\u064e\u0647\u064e\u0627 \u0646\u064e\u0628\u064e\u0627\u062a\u064b\u0627 \u062d\u064e\u0633\u064e\u0646\u0657\u0627 \u0648\u064e\u0643\u064e\u0641\u0651\u064e\u0644\u064e\u0647\u064e\u0627 \u0632\u064e\u0643\u064e\u0631\u0650\u064a\u0651\u064e\u0627\u06d6 \u0643\u064f\u0644\u0651\u064e\u0645\u064e\u0627 \u062f\u064e\u062e\u064e\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627 \u0632\u064e\u0643\u064e\u0631\u0650\u064a\u0651\u064e\u0627 \u0671\u0644\u06e1\u0645\u0650\u062d\u06e1\u0631\u064e\u0627\u0628\u064e \u0648\u064e\u062c\u064e\u062f\u064e \u0639\u0650\u0646\u062f\u064e\u0647\u064e\u0627 \u0631\u0650\u0632\u06e1\u0642\u0657\u0627\u06d6 \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0670\u0645\u064e\u0631\u06e1\u064a\u064e\u0645\u064f \u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u0644\u064e\u0643\u0650 \u0647\u064e\u0670\u0630\u064e\u0627\u06d6 \u0642\u064e\u0627\u0644\u064e\u062a\u06e1 \u0647\u064f\u0648\u064e \u0645\u0650\u0646\u06e1 \u0639\u0650\u0646\u062f\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0631\u06e1\u0632\u064f\u0642\u064f \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0628\u0650\u063a\u064e\u064a\u06e1\u0631\u0650 \u062d\u0650\u0633\u064e\u0627\u0628\u064d",translation:"Maka Dia (Allah) menerimanya dengan penerimaan yang baik, membesarkannya dengan pertumbuhan yang baik dan menyerahkan pemeliharaannya kepada Zakaria. Setiap kali Zakaria masuk menemuinya di mihrab (kamar khusus ibadah), dia dapati makanan di sisinya. Dia berkata, \"Wahai Maryam! Dari mana ini engkau peroleh?\" Dia (Maryam) menjawab, \"Itu dari Allah.\" Sesungguhnya Allah memberi rezeki kepada siapa yang Dia kehendaki tanpa perhitungan"},{id:38,text:"\u0647\u064f\u0646\u064e\u0627\u0644\u0650\u0643\u064e \u062f\u064e\u0639\u064e\u0627 \u0632\u064e\u0643\u064e\u0631\u0650\u064a\u0651\u064e\u0627 \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u06e5\u06d6 \u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0647\u064e\u0628\u06e1 \u0644\u0650\u064a \u0645\u0650\u0646 \u0644\u0651\u064e\u062f\u064f\u0646\u0643\u064e \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u0629\u0657 \u0637\u064e\u064a\u0651\u0650\u0628\u064e\u0629\u064b\u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0633\u064e\u0645\u0650\u064a\u0639\u064f \u0671\u0644\u062f\u0651\u064f\u0639\u064e\u0627\u0653\u0621\u0650",translation:"Di sanalah Zakaria berdoa kepada Tuhannya. Dia berkata, \"Ya Tuhanku, berilah aku keturunan yang baik dari sisi-Mu, sesungguhnya Engkau Maha Mendengar doa"},{id:39,text:"\u0641\u064e\u0646\u064e\u0627\u062f\u064e\u062a\u06e1\u0647\u064f \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u064f \u0648\u064e\u0647\u064f\u0648\u064e \u0642\u064e\u0627\u0653\u0626\u0650\u0645\u065e \u064a\u064f\u0635\u064e\u0644\u0651\u0650\u064a \u0641\u0650\u064a \u0671\u0644\u06e1\u0645\u0650\u062d\u06e1\u0631\u064e\u0627\u0628\u0650 \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u0628\u064e\u0634\u0651\u0650\u0631\u064f\u0643\u064e \u0628\u0650\u064a\u064e\u062d\u06e1\u064a\u064e\u0649\u0670 \u0645\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u064e\u06e2\u0627 \u0628\u0650\u0643\u064e\u0644\u0650\u0645\u064e\u0629\u0656 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0633\u064e\u064a\u0651\u0650\u062f\u0657\u0627 \u0648\u064e\u062d\u064e\u0635\u064f\u0648\u0631\u0657\u0627 \u0648\u064e\u0646\u064e\u0628\u0650\u064a\u0651\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u0650\u064a\u0646\u064e",translation:"Kemudian para malaikat memanggilnya, ketika dia berdiri melaksanakan salat di mihrab, \"Allah menyampaikan kabar gembira kepadamu dengan (kelahiran) Yahya, yang membenarkan suatu kalimat (firman)118) dari Allah, panutan, berkemampuan menahan diri (dari hawa nafsu) dan seorang nabi diantara orang-orang saleh"},{id:40,text:"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u064a\u064e\u0643\u064f\u0648\u0646\u064f \u0644\u0650\u064a \u063a\u064f\u0644\u064e\u0670\u0645\u065e \u0648\u064e\u0642\u064e\u062f\u06e1 \u0628\u064e\u0644\u064e\u063a\u064e\u0646\u0650\u064a\u064e \u0671\u0644\u06e1\u0643\u0650\u0628\u064e\u0631\u064f \u0648\u064e\u0671\u0645\u06e1\u0631\u064e\u0623\u064e\u062a\u0650\u064a \u0639\u064e\u0627\u0642\u0650\u0631\u065e\u06d6 \u0642\u064e\u0627\u0644\u064e \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0641\u06e1\u0639\u064e\u0644\u064f \u0645\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f",translation:"Dia (Zakaria) berkata, \"Ya Tuhanku, bagaimana aku bisa mendapat anak, sedang aku sudah sangat tua dan istriku pun mandul?\" Dia (Allah) berfirman, \"Demikianlah, Allah berbuat apa yang Dia kehendaki"},{id:41,text:"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0671\u062c\u06e1\u0639\u064e\u0644 \u0644\u0651\u0650\u064a\u0653 \u0621\u064e\u0627\u064a\u064e\u0629\u0657\u06d6 \u0642\u064e\u0627\u0644\u064e \u0621\u064e\u0627\u064a\u064e\u062a\u064f\u0643\u064e \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064f\u0643\u064e\u0644\u0651\u0650\u0645\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u062b\u064e\u0644\u064e\u0670\u062b\u064e\u0629\u064e \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0631\u064e\u0645\u06e1\u0632\u0657\u0627\u06d7 \u0648\u064e\u0671\u0630\u06e1\u0643\u064f\u0631 \u0631\u0651\u064e\u0628\u0651\u064e\u0643\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u0657\u0627 \u0648\u064e\u0633\u064e\u0628\u0651\u0650\u062d\u06e1 \u0628\u0650\u0671\u0644\u06e1\u0639\u064e\u0634\u0650\u064a\u0651\u0650 \u0648\u064e\u0671\u0644\u06e1\u0625\u0650\u0628\u06e1\u0643\u064e\u0670\u0631\u0650",translation:"Dia (Zakaria) berkata, \"Ya Tuhanku berilah aku suatu tanda.\" Allah berfirman, \" Tanda bagimu, adalah engkau tidak dapat berbicara dengan manusia selama tiga hari, kecuali dengan isyarat. Dan sebutlah (nama) Tuhanmu banyak-banyak, dan bertasbihlah (memuji-Nya) pada waktu petang dan pagi hari"},{id:42,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e\u062a\u0650 \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u064f \u064a\u064e\u0670\u0645\u064e\u0631\u06e1\u064a\u064e\u0645\u064f \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0671\u0635\u06e1\u0637\u064e\u0641\u064e\u0649\u0670\u0643\u0650 \u0648\u064e\u0637\u064e\u0647\u0651\u064e\u0631\u064e\u0643\u0650 \u0648\u064e\u0671\u0635\u06e1\u0637\u064e\u0641\u064e\u0649\u0670\u0643\u0650 \u0639\u064e\u0644\u064e\u0649\u0670 \u0646\u0650\u0633\u064e\u0627\u0653\u0621\u0650 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Dan (ingatlah) ketika para malaikat berkata, \"Wahai Maryam! Sesungguhnya Allah telah memilihmu, menyucikanmu, dan melebihkanmu di atas segala wanita di seluruh alam (pada masa itu)"},{id:43,text:"\u064a\u064e\u0670\u0645\u064e\u0631\u06e1\u064a\u064e\u0645\u064f \u0671\u0642\u06e1\u0646\u064f\u062a\u0650\u064a \u0644\u0650\u0631\u064e\u0628\u0651\u0650\u0643\u0650 \u0648\u064e\u0671\u0633\u06e1\u062c\u064f\u062f\u0650\u064a \u0648\u064e\u0671\u0631\u06e1\u0643\u064e\u0639\u0650\u064a \u0645\u064e\u0639\u064e \u0671\u0644\u0631\u0651\u064e\u0640\u0670\u0643\u0650\u0639\u0650\u064a\u0646\u064e",translation:"Wahai Maryam! Taatilah Tuhanmu, sujud dan rukuklah bersama orang-orang yang rukuk"},{id:44,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u0650\u0646\u06e1 \u0623\u064e\u0646\u06e2\u0628\u064e\u0627\u0653\u0621\u0650 \u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u0628\u0650 \u0646\u064f\u0648\u062d\u0650\u064a\u0647\u0650 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e\u06da \u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064e \u0644\u064e\u062f\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0625\u0650\u0630\u06e1 \u064a\u064f\u0644\u06e1\u0642\u064f\u0648\u0646\u064e \u0623\u064e\u0642\u06e1\u0644\u064e\u0670\u0645\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u064a\u0651\u064f\u0647\u064f\u0645\u06e1 \u064a\u064e\u0643\u06e1\u0641\u064f\u0644\u064f \u0645\u064e\u0631\u06e1\u064a\u064e\u0645\u064e \u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064e \u0644\u064e\u062f\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0625\u0650\u0630\u06e1 \u064a\u064e\u062e\u06e1\u062a\u064e\u0635\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Itulah sebagian dari berita-berita gaib yang Kami wahyukan kepadamu (Muhammad), padahal engkau tidak bersama mereka ketika mereka melemparkan pena119) mereka (untuk mengundi) siapa di antara mereka yang akan memelihara Maryam. Dan engkau pun tidak bersama mereka ketika mereka bertengkar"},{id:45,text:"\u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e\u062a\u0650 \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u064f \u064a\u064e\u0670\u0645\u064e\u0631\u06e1\u064a\u064e\u0645\u064f \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u0628\u064e\u0634\u0651\u0650\u0631\u064f\u0643\u0650 \u0628\u0650\u0643\u064e\u0644\u0650\u0645\u064e\u0629\u0656 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f \u0671\u0633\u06e1\u0645\u064f\u0647\u064f \u0671\u0644\u06e1\u0645\u064e\u0633\u0650\u064a\u062d\u064f \u0639\u0650\u064a\u0633\u064e\u0649 \u0671\u0628\u06e1\u0646\u064f \u0645\u064e\u0631\u06e1\u064a\u064e\u0645\u064e \u0648\u064e\u062c\u0650\u064a\u0647\u0657\u0627 \u0641\u0650\u064a \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0648\u064e\u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0648\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0642\u064e\u0631\u0651\u064e\u0628\u0650\u064a\u0646\u064e",translation:"(Ingatlah), ketika para malaikat berkata, \"Wahai Maryam! Sesungguhnya Allah menyampaikan kabar gembira kepadamu tentang suatu kalimat (firman) dari-Nya (yaitu seorang putera) namanya Al-Masih Isa putra Maryam, seorang terkemuka di dunia dan di akhirat, dan termasuk orang-orang yang didekatkan (kepada Allah)"},{id:46,text:"\u0648\u064e\u064a\u064f\u0643\u064e\u0644\u0651\u0650\u0645\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0645\u064e\u0647\u06e1\u062f\u0650 \u0648\u064e\u0643\u064e\u0647\u06e1\u0644\u0657\u0627 \u0648\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u0650\u064a\u0646\u064e",translation:"dan dia berbicara dengan manusia (sewaktu) dalam buaian dan ketika sudah dewasa, dan dia termasuk di antara orang-orang yang saleh"},{id:47,text:"\u0642\u064e\u0627\u0644\u064e\u062a\u06e1 \u0631\u064e\u0628\u0651\u0650 \u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u064a\u064e\u0643\u064f\u0648\u0646\u064f \u0644\u0650\u064a \u0648\u064e\u0644\u064e\u062f\u065e \u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0645\u06e1\u0633\u064e\u0633\u06e1\u0646\u0650\u064a \u0628\u064e\u0634\u064e\u0631\u065e\u06d6 \u0642\u064e\u0627\u0644\u064e \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u062e\u06e1\u0644\u064f\u0642\u064f \u0645\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06da \u0625\u0650\u0630\u064e\u0627 \u0642\u064e\u0636\u064e\u0649\u0670\u0653 \u0623\u064e\u0645\u06e1\u0631\u0657\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0644\u064e\u0647\u064f\u06e5 \u0643\u064f\u0646 \u0641\u064e\u064a\u064e\u0643\u064f\u0648\u0646\u064f",translation:"Dia (Maryam) berkata, \"Ya Tuhanku, bagaimana mungkin aku akan mempunyai anak, padahal tidak ada seorang laki-laki pun yang menyentuhku?\" Dia (Allah) berfirman, \"Demikianlah Allah menciptakan apa yang Dia kehendaki. Apabila Dia hendak menetapkan sesuatu, Dia hanya berkata kepadanya, \"Jadilah!\" Maka jadilah sesuatu itu"},{id:48,text:"\u0648\u064e\u064a\u064f\u0639\u064e\u0644\u0651\u0650\u0645\u064f\u0647\u064f \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0648\u064e\u0671\u0644\u06e1\u062d\u0650\u0643\u06e1\u0645\u064e\u0629\u064e \u0648\u064e\u0671\u0644\u062a\u0651\u064e\u0648\u06e1\u0631\u064e\u0649\u0670\u0629\u064e \u0648\u064e\u0671\u0644\u06e1\u0625\u0650\u0646\u062c\u0650\u064a\u0644\u064e",translation:"Dan Dia (Allah) mengajarkan kepadanya (Isa) Kitab,120) Hikmah, Taurat, dan Injil"},{id:49,text:"\u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064b\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0628\u064e\u0646\u0650\u064a\u0653 \u0625\u0650\u0633\u06e1\u0631\u064e\u0640\u0670\u0653\u0621\u0650\u064a\u0644\u064e \u0623\u064e\u0646\u0651\u0650\u064a \u0642\u064e\u062f\u06e1 \u062c\u0650\u0626\u06e1\u062a\u064f\u0643\u064f\u0645 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0629\u0656 \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1 \u0623\u064e\u0646\u0651\u0650\u064a\u0653 \u0623\u064e\u062e\u06e1\u0644\u064f\u0642\u064f \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0637\u0651\u0650\u064a\u0646\u0650 \u0643\u064e\u0647\u064e\u064a\u06e1\u0640\u0654\u064e\u0629\u0650 \u0671\u0644\u0637\u0651\u064e\u064a\u06e1\u0631\u0650 \u0641\u064e\u0623\u064e\u0646\u0641\u064f\u062e\u064f \u0641\u0650\u064a\u0647\u0650 \u0641\u064e\u064a\u064e\u0643\u064f\u0648\u0646\u064f \u0637\u064e\u064a\u06e1\u0631\u064e\u06e2\u0627 \u0628\u0650\u0625\u0650\u0630\u06e1\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0648\u064e\u0623\u064f\u0628\u06e1\u0631\u0650\u0626\u064f \u0671\u0644\u06e1\u0623\u064e\u0643\u06e1\u0645\u064e\u0647\u064e \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0628\u06e1\u0631\u064e\u0635\u064e \u0648\u064e\u0623\u064f\u062d\u06e1\u064a\u0650 \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u064e\u0649\u0670 \u0628\u0650\u0625\u0650\u0630\u06e1\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0648\u064e\u0623\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0643\u064f\u0645 \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f\u0648\u0646\u064e \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u062f\u0651\u064e\u062e\u0650\u0631\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0628\u064f\u064a\u064f\u0648\u062a\u0650\u0643\u064f\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0623\u0653\u064a\u064e\u0629\u0657 \u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645 \u0645\u0651\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dan sebagai Rasul kepada Bani Israil (dia berkata), \"Aku telah datang kepada kamu dengan satu tanda (mukjizat) dari Tuhanmu, yaitu aku membuatkan bagimu (sesuatu) dari tanah berbentuk seperti burung, lalu aku meniupnya, maka ia menjadi seekor burung dengan izin Allah. Dan aku menyembuhkan orang yang buta sejak dari lahir dan orang yang berpenyakit kusta. Dan aku menghidupkan orang mati dengan izin Allah, dan aku beritahukan kepadamu apa yang kamu makan dan apa yang kamu simpan di rumahmu. Sesungguhnya pada yang demikian itu terdapat suatu tanda (kebenaran tentang kerasulanku) bagimu, jika kamu orang beriman"},{id:50,text:"\u0648\u064e\u0645\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u0657\u0627 \u0644\u0651\u0650\u0645\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u0651\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u062a\u0651\u064e\u0648\u06e1\u0631\u064e\u0649\u0670\u0629\u0650 \u0648\u064e\u0644\u0650\u0623\u064f\u062d\u0650\u0644\u0651\u064e \u0644\u064e\u0643\u064f\u0645 \u0628\u064e\u0639\u06e1\u0636\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062d\u064f\u0631\u0651\u0650\u0645\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u062c\u0650\u0626\u06e1\u062a\u064f\u0643\u064f\u0645 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0629\u0656 \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1 \u0641\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u0650",translation:"Dan sebagai seorang yang membenarkan Taurat yang datang sebelumku, dan agar aku menghalalkan bagi kamu sebagian dari yang telah diharamkan untukmu. Dan aku datang kepadamu membawa suatu tanda (mukjizat) dari Tuhanmu. Karena itu, bertakwalah kepada Allah dan taatlah kepadaku"},{id:51,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u06e1 \u0641\u064e\u0671\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0647\u064f\u06da \u0647\u064e\u0670\u0630\u064e\u0627 \u0635\u0650\u0631\u064e\u0670\u0637\u065e \u0645\u0651\u064f\u0633\u06e1\u062a\u064e\u0642\u0650\u064a\u0645\u065e",translation:"Sesungguhnya Allah itu Tuhanku dan Tuhanmu, karena itu sembahlah Dia. Inilah jalan yang lurus"},{id:52,text:"\u06de\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u062d\u064e\u0633\u0651\u064e \u0639\u0650\u064a\u0633\u064e\u0649\u0670 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0643\u064f\u0641\u06e1\u0631\u064e \u0642\u064e\u0627\u0644\u064e \u0645\u064e\u0646\u06e1 \u0623\u064e\u0646\u0635\u064e\u0627\u0631\u0650\u064a\u0653 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0642\u064e\u0627\u0644\u064e \u0671\u0644\u06e1\u062d\u064e\u0648\u064e\u0627\u0631\u0650\u064a\u0651\u064f\u0648\u0646\u064e \u0646\u064e\u062d\u06e1\u0646\u064f \u0623\u064e\u0646\u0635\u064e\u0627\u0631\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0621\u064e\u0627\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0671\u0634\u06e1\u0647\u064e\u062f\u06e1 \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0627 \u0645\u064f\u0633\u06e1\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Maka ketika Isa merasakan keingkaran mereka (Bani Israil), dia berkata, \"Siapakah yang akan menjadi penolongku untuk (menegakkan agama) Allah?\" Para \u1e24aw\u0101riyy\u016bn (sahabat setianya) menjawab, \"Kamilah penolong (agama) Allah. Kami beriman kepada Allah, dan saksikanlah, bahwa kami adalah orang-orang Muslim"},{id:53,text:"\u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627\u0653 \u0621\u064e\u0627\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u062a\u064e \u0648\u064e\u0671\u062a\u0651\u064e\u0628\u064e\u0639\u06e1\u0646\u064e\u0627 \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e \u0641\u064e\u0671\u0643\u06e1\u062a\u064f\u0628\u06e1\u0646\u064e\u0627 \u0645\u064e\u0639\u064e \u0671\u0644\u0634\u0651\u064e\u0640\u0670\u0647\u0650\u062f\u0650\u064a\u0646\u064e",translation:"Ya Tuhan kami, kami telah beriman kepada apa yang Engkau turunkan dan kami telah mengikuti Rasul, karena itu tetapkanlah kami bersama golongan orang yang memberikan kesaksian"},{id:54,text:"\u0648\u064e\u0645\u064e\u0643\u064e\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u0645\u064e\u0643\u064e\u0631\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06d6 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u062e\u064e\u064a\u06e1\u0631\u064f \u0671\u0644\u06e1\u0645\u064e\u0670\u0643\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan mereka (orang-orang kafir) membuat tipu daya, maka Allah pun membalas tipu daya. Dan Allah sebaik-baik pembalas tipu daya"},{id:55,text:"\u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0670\u0639\u0650\u064a\u0633\u064e\u0649\u0670\u0653 \u0625\u0650\u0646\u0651\u0650\u064a \u0645\u064f\u062a\u064e\u0648\u064e\u0641\u0651\u0650\u064a\u0643\u064e \u0648\u064e\u0631\u064e\u0627\u0641\u0650\u0639\u064f\u0643\u064e \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0648\u064e\u0645\u064f\u0637\u064e\u0647\u0651\u0650\u0631\u064f\u0643\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u062c\u064e\u0627\u0639\u0650\u0644\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0643\u064e \u0641\u064e\u0648\u06e1\u0642\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650\u06d6 \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0645\u064e\u0631\u06e1\u062c\u0650\u0639\u064f\u0643\u064f\u0645\u06e1 \u0641\u064e\u0623\u064e\u062d\u06e1\u0643\u064f\u0645\u064f \u0628\u064e\u064a\u06e1\u0646\u064e\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u0650 \u062a\u064e\u062e\u06e1\u062a\u064e\u0644\u0650\u0641\u064f\u0648\u0646\u064e",translation:"(Ingatlah), ketika Allah berfirman, \"Wahai Isa! Aku mengambilmu dan mengangkatmu kepada-Ku, serta menyucikanmu dari orang-orang yang kafir, dan menjadikan orang-orang yang mengikutimu di atas orang-orang yang kafir hingga hari Kiamat. Kemudian kepada-Ku engkau kembali, lalu Aku beri keputusan tentang apa yang kamu perselisihkan"},{id:56,text:"\u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0641\u064e\u0623\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064f\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u0657\u0627 \u0634\u064e\u062f\u0650\u064a\u062f\u0657\u0627 \u0641\u0650\u064a \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0648\u064e\u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0646\u0651\u064e\u0640\u0670\u0635\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Maka adapun orang-orang yang kafir, maka akan Aku azab mereka dengan azab yang sangat keras di dunia dan di akhirat, sedang mereka tidak memperoleh penolong"},{id:57,text:"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0641\u064e\u064a\u064f\u0648\u064e\u0641\u0651\u0650\u064a\u0647\u0650\u0645\u06e1 \u0623\u064f\u062c\u064f\u0648\u0631\u064e\u0647\u064f\u0645\u06e1\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dan adapun orang yang beriman dan melakukan kebajikan, maka Dia akan memberikan pahala kepada mereka dengan sempurna. Dan Allah tidak menyukai orang zalim"},{id:58,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u062a\u06e1\u0644\u064f\u0648\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u0653\u064a\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u0630\u0651\u0650\u0643\u06e1\u0631\u0650 \u0671\u0644\u06e1\u062d\u064e\u0643\u0650\u064a\u0645\u0650",translation:"Demikianlah Kami bacakan kepadamu (Muhammad) sebagian ayat-ayat dan peringatan yang penuh hikmah"},{id:59,text:"\u0625\u0650\u0646\u0651\u064e \u0645\u064e\u062b\u064e\u0644\u064e \u0639\u0650\u064a\u0633\u064e\u0649\u0670 \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u0645\u064e\u062b\u064e\u0644\u0650 \u0621\u064e\u0627\u062f\u064e\u0645\u064e\u06d6 \u062e\u064e\u0644\u064e\u0642\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646 \u062a\u064f\u0631\u064e\u0627\u0628\u0656 \u062b\u064f\u0645\u0651\u064e \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f\u06e5 \u0643\u064f\u0646 \u0641\u064e\u064a\u064e\u0643\u064f\u0648\u0646\u064f",translation:"Sesungguhnya perumpamaan (penciptaan) Isa bagi Allah, seperti (penciptaan) Adam. Dia menciptakannya dari tanah, kemudian Dia berkata kepadanya, \"Jadilah!\" Maka jadilah ia"},{id:60,text:"\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064e \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0646 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0645\u06e1\u062a\u064e\u0631\u0650\u064a\u0646\u064e",translation:"Kebenaran itu dari Tuhanmu, karena itu janganlah engkau (Muhammad) termasuk orang-orang yang ragu"},{id:61,text:"\u0641\u064e\u0645\u064e\u0646\u06e1 \u062d\u064e\u0627\u0653\u062c\u0651\u064e\u0643\u064e \u0641\u0650\u064a\u0647\u0650 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0645\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0639\u0650\u0644\u06e1\u0645\u0650 \u0641\u064e\u0642\u064f\u0644\u06e1 \u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0648\u06e1\u0627\u0652 \u0646\u064e\u062f\u06e1\u0639\u064f \u0623\u064e\u0628\u06e1\u0646\u064e\u0627\u0653\u0621\u064e\u0646\u064e\u0627 \u0648\u064e\u0623\u064e\u0628\u06e1\u0646\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0646\u0650\u0633\u064e\u0627\u0653\u0621\u064e\u0646\u064e\u0627 \u0648\u064e\u0646\u0650\u0633\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0646\u064e\u0627 \u0648\u064e\u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0643\u064f\u0645\u06e1 \u062b\u064f\u0645\u0651\u064e \u0646\u064e\u0628\u06e1\u062a\u064e\u0647\u0650\u0644\u06e1 \u0641\u064e\u0646\u064e\u062c\u06e1\u0639\u064e\u0644 \u0644\u0651\u064e\u0639\u06e1\u0646\u064e\u062a\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0643\u064e\u0670\u0630\u0650\u0628\u0650\u064a\u0646\u064e",translation:"Siapa yang membantahmu dalam hal ini setelah engkau memperoleh ilmu, katakanlah (Muhammad), \"Marilah kita panggil anak-anak kami dan anak-anak kamu, istri-istri kami dan istri-istrimu, kami sendiri dan diri kamu, kemudian marilah kita ber-mubahalah 121) agar laknat Allah ditimpakan kepada orang-orang yang dusta (di antara kita)"},{id:62,text:"\u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0644\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0642\u064e\u0635\u064e\u0635\u064f \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f\u06da \u0648\u064e\u0645\u064e\u0627 \u0645\u0650\u0646\u06e1 \u0625\u0650\u0644\u064e\u0670\u0647\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0671\u0644\u06e1\u062d\u064e\u0643\u0650\u064a\u0645\u064f",translation:"Sungguh, ini adalah kisah yang benar. Tidak ada tuhan selain Allah, dan sungguh, Allah Mahaperkasa, Mahabijaksana"},{id:63,text:"\u0641\u064e\u0625\u0650\u0646 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u06e1\u0627\u0652 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u064f\u06e2 \u0628\u0650\u0671\u0644\u06e1\u0645\u064f\u0641\u06e1\u0633\u0650\u062f\u0650\u064a\u0646\u064e",translation:"Kemudian jika mereka berpaling, maka (ketahuilah) bahwa Allah Maha Mengetahui orang-orang yang berbuat kerusakan"},{id:64,text:"\u0642\u064f\u0644\u06e1 \u064a\u064e\u0640\u0670\u0653\u0623\u064e\u0647\u06e1\u0644\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0648\u06e1\u0627\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0643\u064e\u0644\u0650\u0645\u064e\u0629\u0656 \u0633\u064e\u0648\u064e\u0627\u0653\u0621\u0650\u06ed \u0628\u064e\u064a\u06e1\u0646\u064e\u0646\u064e\u0627 \u0648\u064e\u0628\u064e\u064a\u06e1\u0646\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u0644\u0651\u064e\u0627 \u0646\u064e\u0639\u06e1\u0628\u064f\u062f\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0644\u064e\u0627 \u0646\u064f\u0634\u06e1\u0631\u0650\u0643\u064e \u0628\u0650\u0647\u0650\u06e6 \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064e \u0628\u064e\u0639\u06e1\u0636\u064f\u0646\u064e\u0627 \u0628\u064e\u0639\u06e1\u0636\u064b\u0627 \u0623\u064e\u0631\u06e1\u0628\u064e\u0627\u0628\u0657\u0627 \u0645\u0651\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0641\u064e\u0625\u0650\u0646 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u06e1\u0627\u0652 \u0641\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627\u0652 \u0671\u0634\u06e1\u0647\u064e\u062f\u064f\u0648\u0627\u0652 \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0627 \u0645\u064f\u0633\u06e1\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Katakanlah (Muhammad), \"Wahai Ahli Kitab! Marilah (kita) menuju kepada satu kalimat (pegangan) yang sama antara kami dan kamu, bahwa kita tidak menyembah selain Allah dan kita tidak mempersekutukan-Nya dengan sesuatu pun, dan bahwa kita tidak menjadikan satu sama lain tuhan-tuhan selain Allah. Jika mereka berpaling maka katakanlah (kepada mereka), \"Saksikanlah, bahwa kami adalah orang Muslim"},{id:65,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u0647\u06e1\u0644\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0644\u0650\u0645\u064e \u062a\u064f\u062d\u064e\u0627\u0653\u062c\u0651\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0653 \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064e \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e\u062a\u0650 \u0671\u0644\u062a\u0651\u064e\u0648\u06e1\u0631\u064e\u0649\u0670\u0629\u064f \u0648\u064e\u0671\u0644\u06e1\u0625\u0650\u0646\u062c\u0650\u064a\u0644\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u0647\u0650\u06e6\u0653\u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e",translation:"(Wahai Ahli Kitab! Mengapa kamu berbantah-bantahan122) tentang Ibrahim, padahal Taurat dan Injil diturunkan setelah dia (Ibrahim)? Apakah kamu tidak mengerti"},{id:66,text:"\u0647\u064e\u0640\u0670\u0653\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650 \u062d\u064e\u0670\u062c\u064e\u062c\u06e1\u062a\u064f\u0645\u06e1 \u0641\u0650\u064a\u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6 \u0639\u0650\u0644\u06e1\u0645\u065e \u0641\u064e\u0644\u0650\u0645\u064e \u062a\u064f\u062d\u064e\u0627\u0653\u062c\u0651\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0645\u064e\u0627 \u0644\u064e\u064a\u06e1\u0633\u064e \u0644\u064e\u0643\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6 \u0639\u0650\u0644\u06e1\u0645\u065e\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"(Begitulah kamu! Kamu berbantah-bantahan tentang apa yang kamu ketahui,123) tetapi mengapa kamu berbantah-bantahan juga tentang apa yang tidak kamu ketahui?124) Allah mengetahui sedang kamu tidak mengetahui"},{id:67,text:"\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064f \u064a\u064e\u0647\u064f\u0648\u062f\u0650\u064a\u0651\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0635\u06e1\u0631\u064e\u0627\u0646\u0650\u064a\u0651\u0657\u0627 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u0643\u064e\u0627\u0646\u064e \u062d\u064e\u0646\u0650\u064a\u0641\u0657\u0627 \u0645\u0651\u064f\u0633\u06e1\u0644\u0650\u0645\u0657\u0627 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0634\u06e1\u0631\u0650\u0643\u0650\u064a\u0646\u064e",translation:"Ibrahim bukanlah seorang Yahudi dan bukan (pula) seorang Nasrani, tetapi dia adalah seorang yang lurus,125) muslim dan dia tidaklah termasuk orang-orang musyrik"},{id:68,text:"\u0625\u0650\u0646\u0651\u064e \u0623\u064e\u0648\u06e1\u0644\u064e\u0649 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0628\u0650\u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064e \u0644\u064e\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0647\u064f \u0648\u064e\u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064f \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0644\u0650\u064a\u0651\u064f \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Orang yang paling dekat kepada Ibrahim ialah orang yang mengikutinya, dan Nabi ini (Muhammad), dan orang yang beriman. Allah adalah pelindung orang-orang yang beriman"},{id:69,text:"\u0648\u064e\u062f\u0651\u064e\u062a \u0637\u0651\u064e\u0627\u0653\u0626\u0650\u0641\u064e\u0629\u065e \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u0647\u06e1\u0644\u0650 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0644\u064e\u0648\u06e1 \u064a\u064f\u0636\u0650\u0644\u0651\u064f\u0648\u0646\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0636\u0650\u0644\u0651\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0634\u06e1\u0639\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Segolongan Ahli Kitab ingin menyesatkan kamu. Padahal (sesungguhnya), mereka tidak menyesatkan melainkan diri mereka sendiri, tetapi mereka tidak menyadari"},{id:70,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u0647\u06e1\u0644\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0644\u0650\u0645\u064e \u062a\u064e\u0643\u06e1\u0641\u064f\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0634\u06e1\u0647\u064e\u062f\u064f\u0648\u0646\u064e",translation:"(Wahai Ahli Kitab! Mengapa kamu mengingkari ayat-ayat Allah,126) padahal kamu mengetahui (kebenarannya)"},{id:71,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u0647\u06e1\u0644\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0644\u0650\u0645\u064e \u062a\u064e\u0644\u06e1\u0628\u0650\u0633\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064e \u0628\u0650\u0671\u0644\u06e1\u0628\u064e\u0670\u0637\u0650\u0644\u0650 \u0648\u064e\u062a\u064e\u0643\u06e1\u062a\u064f\u0645\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064e \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"(Wahai Ahli Kitab! Mengapa kamu mencampuradukkan kebenaran dengan kebatilan,127) dan kamu menyembunyikan kebenaran,128) padahal kamu mengetahui"},{id:72,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e\u062a \u0637\u0651\u064e\u0627\u0653\u0626\u0650\u0641\u064e\u0629\u065e \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u0647\u06e1\u0644\u0650 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0621\u064e\u0627\u0645\u0650\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u062c\u06e1\u0647\u064e \u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u0648\u064e\u0671\u0643\u06e1\u0641\u064f\u0631\u064f\u0648\u0653\u0627\u0652 \u0621\u064e\u0627\u062e\u0650\u0631\u064e\u0647\u064f\u06e5 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0631\u06e1\u062c\u0650\u0639\u064f\u0648\u0646\u064e",translation:"Dan segolongan Ahli Kitab berkata (kepada sesamanya), \"Berimanlah kamu kepada apa yang diturunkan kepada orang-orang beriman pada awal siang dan ingkarilah di akhirnya, agar mereka kembali (kepada kekafiran)"},{id:73,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0644\u0650\u0645\u064e\u0646 \u062a\u064e\u0628\u0650\u0639\u064e \u062f\u0650\u064a\u0646\u064e\u0643\u064f\u0645\u06e1 \u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0647\u064f\u062f\u064e\u0649\u0670 \u0647\u064f\u062f\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0646 \u064a\u064f\u0624\u06e1\u062a\u064e\u0649\u0670\u0653 \u0623\u064e\u062d\u064e\u062f\u065e \u0645\u0651\u0650\u062b\u06e1\u0644\u064e \u0645\u064e\u0627\u0653 \u0623\u064f\u0648\u062a\u0650\u064a\u062a\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1 \u064a\u064f\u062d\u064e\u0627\u0653\u062c\u0651\u064f\u0648\u0643\u064f\u0645\u06e1 \u0639\u0650\u0646\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1\u06d7 \u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0641\u064e\u0636\u06e1\u0644\u064e \u0628\u0650\u064a\u064e\u062f\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064f\u0624\u06e1\u062a\u0650\u064a\u0647\u0650 \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0670\u0633\u0650\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u065e",translation:"(Dan janganlah kamu percaya selain kepada orang yang mengikuti agamamu.129) Katakanlah (Muhammad), \"Sesungguhnya petunjuk itu hanyalah petunjuk Allah. (Janganlah kamu percaya) bahwa seseorang akan diberi seperti apa yang diberikan kepada kamu atau bahwa mereka akan menyanggah kamu di hadapan Tuhanmu.\" Katakanlah (Muhammad), \"Sesungguhnya karunia itu di tangan Allah, Dia memberikannya kepada siapa yang Dia kehendaki. Allah Mahaluas, Maha Mengetahui"},{id:74,text:"\u064a\u064e\u062e\u06e1\u062a\u064e\u0635\u0651\u064f \u0628\u0650\u0631\u064e\u062d\u06e1\u0645\u064e\u062a\u0650\u0647\u0650\u06e6 \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0630\u064f\u0648 \u0671\u0644\u06e1\u0641\u064e\u0636\u06e1\u0644\u0650 \u0671\u0644\u06e1\u0639\u064e\u0638\u0650\u064a\u0645\u0650",translation:"Dia menentukan rahmat-Nya kepada siapa yang Dia kehendaki. Dan Allah memiliki karunia yang besar"},{id:75,text:"\u06de\u0648\u064e\u0645\u0650\u0646\u06e1 \u0623\u064e\u0647\u06e1\u0644\u0650 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0645\u064e\u0646\u06e1 \u0625\u0650\u0646 \u062a\u064e\u0623\u06e1\u0645\u064e\u0646\u06e1\u0647\u064f \u0628\u0650\u0642\u0650\u0646\u0637\u064e\u0627\u0631\u0656 \u064a\u064f\u0624\u064e\u062f\u0651\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0648\u064e\u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0646\u06e1 \u0625\u0650\u0646 \u062a\u064e\u0623\u06e1\u0645\u064e\u0646\u06e1\u0647\u064f \u0628\u0650\u062f\u0650\u064a\u0646\u064e\u0627\u0631\u0656 \u0644\u0651\u064e\u0627 \u064a\u064f\u0624\u064e\u062f\u0651\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u062f\u064f\u0645\u06e1\u062a\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0642\u064e\u0627\u0653\u0626\u0650\u0645\u0657\u0627\u06d7 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u064a\u06e1\u0633\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064f\u0645\u0651\u0650\u064a\u0651\u0650\u0640\u06e7\u0646\u064e \u0633\u064e\u0628\u0650\u064a\u0644\u065e \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u0643\u064e\u0630\u0650\u0628\u064e \u0648\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan di antara Ahli Kitab ada yang jika engkau percayakan kepadanya harta yang banyak, niscaya dia mengembalikannya kepadamu. Tetapi ada (pula) di antara mereka yang jika engkau percayakan kepadanya satu dinar, dia tidak mengembalikannya kepadamu, kecuali jika engkau selalu menagihnya. Yang demikian itu disebabkan mereka berkata, \"Tidak ada dosa bagi kami terhadap orang-orang yang buta huruf.\" Mereka mengatakan hal yang dusta terhadap Allah, padahal mereka mengetahui"},{id:76,text:"\u0628\u064e\u0644\u064e\u0649\u0670\u06da \u0645\u064e\u0646\u06e1 \u0623\u064e\u0648\u06e1\u0641\u064e\u0649\u0670 \u0628\u0650\u0639\u064e\u0647\u06e1\u062f\u0650\u0647\u0650\u06e6 \u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064e\u0649\u0670 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0671\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",translation:"Sebenarnya barang siapa menepati janji dan bertakwa, maka sungguh, Allah mencintai orang-orang yang bertakwa"},{id:77,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0634\u06e1\u062a\u064e\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0639\u064e\u0647\u06e1\u062f\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0623\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u0650\u0647\u0650\u0645\u06e1 \u062b\u064e\u0645\u064e\u0646\u0657\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0644\u064e\u0627 \u062e\u064e\u0644\u064e\u0670\u0642\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0643\u064e\u0644\u0651\u0650\u0645\u064f\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0646\u0638\u064f\u0631\u064f \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0632\u064e\u0643\u0651\u0650\u064a\u0647\u0650\u0645\u06e1 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Sesungguhnya orang-orang yang memperjual belikan janji Allah dan sumpah-sumpah mereka dengan harga murah, mereka itu tidak memperoleh bagian di akhirat, Allah tidak akan menyapa mereka, tidak akan memperhatikan mereka pada hari Kiamat, dan tidak akan menyucikan mereka. Bagi mereka azab yang pedih"},{id:78,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0644\u064e\u0641\u064e\u0631\u0650\u064a\u0642\u0657\u0627 \u064a\u064e\u0644\u06e1\u0648\u064f\u06e5\u0646\u064e \u0623\u064e\u0644\u06e1\u0633\u0650\u0646\u064e\u062a\u064e\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0644\u0650\u062a\u064e\u062d\u06e1\u0633\u064e\u0628\u064f\u0648\u0647\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0648\u064e\u0645\u064e\u0627 \u0647\u064f\u0648\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0647\u064f\u0648\u064e \u0645\u0650\u0646\u06e1 \u0639\u0650\u0646\u062f\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u064e\u0627 \u0647\u064f\u0648\u064e \u0645\u0650\u0646\u06e1 \u0639\u0650\u0646\u062f\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u0643\u064e\u0630\u0650\u0628\u064e \u0648\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan sungguh, di antara mereka niscaya ada segolongan yang memutarbalikkan lidahnya hanya membaca Kitab, agar kamu menyangka (yang mereka baca) itu sebagian dari Kitab, padahal itu bukan dari Kitab dan mereka berkata, \"Itu dari Allah,\" padahal itu bukan dari Allah. Mereka mengatakan hal yang dusta terhadap Allah, padahal mereka mengetahui"},{id:79,text:"\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0628\u064e\u0634\u064e\u0631\u064d \u0623\u064e\u0646 \u064a\u064f\u0624\u06e1\u062a\u0650\u064a\u064e\u0647\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0648\u064e\u0671\u0644\u06e1\u062d\u064f\u0643\u06e1\u0645\u064e \u0648\u064e\u0671\u0644\u0646\u0651\u064f\u0628\u064f\u0648\u0651\u064e\u0629\u064e \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u0642\u064f\u0648\u0644\u064e \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u0657\u0627 \u0644\u0651\u0650\u064a \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u0631\u064e\u0628\u0651\u064e\u0640\u0670\u0646\u0650\u064a\u0651\u0650\u0640\u06e7\u0646\u064e \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064f\u0639\u064e\u0644\u0651\u0650\u0645\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0648\u064e\u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u062f\u06e1\u0631\u064f\u0633\u064f\u0648\u0646\u064e",translation:"Tidak mungkin bagi seseorang yang telah diberi kitab oleh Allah, serta hikmah dan kenabian, kemudian dia berkata kepada manusia, \"Jadilah kamu penyembahku, bukan penyembah Allah,\" tetapi (dia berkata), \"Jadilah kamu pengabdi-pengabdi Allah, karena kamu mengajarkan kitab dan karena kamu mempelajarinya"},{id:80,text:"\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0623\u06e1\u0645\u064f\u0631\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u0646 \u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u064e \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650\u0640\u06e7\u0646\u064e \u0623\u064e\u0631\u06e1\u0628\u064e\u0627\u0628\u064b\u0627\u06da \u0623\u064e\u064a\u064e\u0623\u06e1\u0645\u064f\u0631\u064f\u0643\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0643\u064f\u0641\u06e1\u0631\u0650 \u0628\u064e\u0639\u06e1\u062f\u064e \u0625\u0650\u0630\u06e1 \u0623\u064e\u0646\u062a\u064f\u0645 \u0645\u0651\u064f\u0633\u06e1\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"dan tidak (mungkin pula baginya) menyuruh kamu menjadikan para malaikat dan para nabi sebagai Tuhan. Apakah (patut) dia menyuruh kamu menjadi kafir setelah kamu menjadi muslim"},{id:81,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0623\u064e\u062e\u064e\u0630\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u064a\u062b\u064e\u0670\u0642\u064e \u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650\u0640\u06e7\u0646\u064e \u0644\u064e\u0645\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u062a\u064f\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0643\u0650\u062a\u064e\u0670\u0628\u0656 \u0648\u064e\u062d\u0650\u0643\u06e1\u0645\u064e\u0629\u0656 \u062b\u064f\u0645\u0651\u064e \u062c\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u06e1 \u0631\u064e\u0633\u064f\u0648\u0644\u065e \u0645\u0651\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u065e \u0644\u0651\u0650\u0645\u064e\u0627 \u0645\u064e\u0639\u064e\u0643\u064f\u0645\u06e1 \u0644\u064e\u062a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0646\u0651\u064e \u0628\u0650\u0647\u0650\u06e6 \u0648\u064e\u0644\u064e\u062a\u064e\u0646\u0635\u064f\u0631\u064f\u0646\u0651\u064e\u0647\u064f\u06e5\u06da \u0642\u064e\u0627\u0644\u064e \u0621\u064e\u0623\u064e\u0642\u06e1\u0631\u064e\u0631\u06e1\u062a\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u062e\u064e\u0630\u06e1\u062a\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u06e1 \u0625\u0650\u0635\u06e1\u0631\u0650\u064a\u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0642\u06e1\u0631\u064e\u0631\u06e1\u0646\u064e\u0627\u06da \u0642\u064e\u0627\u0644\u064e \u0641\u064e\u0671\u0634\u06e1\u0647\u064e\u062f\u064f\u0648\u0627\u0652 \u0648\u064e\u0623\u064e\u0646\u064e\u0627\u06e0 \u0645\u064e\u0639\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0634\u0651\u064e\u0640\u0670\u0647\u0650\u062f\u0650\u064a\u0646\u064e",translation:"Dan (ingatlah), ketika Allah mengambil perjanjian dari para nabi, \"Manakala Aku memberikan kitab dan hikmah kepadamu lalu datang kepada kamu seorang Rasul yang membenarkan apa yang ada pada kamu, niscaya kamu akan sungguh-sungguh beriman kepadanya dan menolongnya.\"130) Allah berfirman, \"Apakah kamu setuju dan menerima perjanjian dengan-Ku atas yang demikian itu?\" Mereka menjawab, \"Kami setuju.\" Allah berfirman, \"Kalau begitu bersaksilah kamu (para nabi) dan Aku menjadi saksi bersama kamu"},{id:82,text:"\u0641\u064e\u0645\u064e\u0646 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649\u0670 \u0628\u064e\u0639\u06e1\u062f\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0641\u064e\u0670\u0633\u0650\u0642\u064f\u0648\u0646\u064e",translation:"Maka barang siapa berpaling setelah itu, mereka itulah orang yang fasik"},{id:83,text:"\u0623\u064e\u0641\u064e\u063a\u064e\u064a\u06e1\u0631\u064e \u062f\u0650\u064a\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u0628\u06e1\u063a\u064f\u0648\u0646\u064e \u0648\u064e\u0644\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u0633\u06e1\u0644\u064e\u0645\u064e \u0645\u064e\u0646 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0637\u064e\u0648\u06e1\u0639\u0657\u0627 \u0648\u064e\u0643\u064e\u0631\u06e1\u0647\u0657\u0627 \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u064a\u064f\u0631\u06e1\u062c\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Maka mengapa mereka mencari agama yang lain selain agama Allah, padahal apa yang di langit dan di bumi berserah diri kepada-Nya (baik) dengan suka maupun terpaksa, dan hanya kepada-Nya mereka dikembalikan"},{id:84,text:"\u0642\u064f\u0644\u06e1 \u0621\u064e\u0627\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064e \u0648\u064e\u0625\u0650\u0633\u06e1\u0645\u064e\u0670\u0639\u0650\u064a\u0644\u064e \u0648\u064e\u0625\u0650\u0633\u06e1\u062d\u064e\u0670\u0642\u064e \u0648\u064e\u064a\u064e\u0639\u06e1\u0642\u064f\u0648\u0628\u064e \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0633\u06e1\u0628\u064e\u0627\u0637\u0650 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0648\u062a\u0650\u064a\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u0639\u0650\u064a\u0633\u064e\u0649\u0670 \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0644\u064e\u0627 \u0646\u064f\u0641\u064e\u0631\u0651\u0650\u0642\u064f \u0628\u064e\u064a\u06e1\u0646\u064e \u0623\u064e\u062d\u064e\u062f\u0656 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0648\u064e\u0646\u064e\u062d\u06e1\u0646\u064f \u0644\u064e\u0647\u064f\u06e5 \u0645\u064f\u0633\u06e1\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Katakanlah (Muhammad), \"Kami beriman kepada Allah dan kepada apa yang diturunkan kepada kami dan yang diturunkan kepada Ibrahim, Ismail, Ishak, Yakub, dan anak cucunya, dan apa yang diberikan kepada Musa, Isa dan para Nabi dari Tuhan mereka. Kami tidak membeda-bedakan seorang pun diantara mereka dan hanya kepada-Nya kami berserah diri"},{id:85,text:"\u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0628\u06e1\u062a\u064e\u063a\u0650 \u063a\u064e\u064a\u06e1\u0631\u064e \u0671\u0644\u06e1\u0625\u0650\u0633\u06e1\u0644\u064e\u0670\u0645\u0650 \u062f\u0650\u064a\u0646\u0657\u0627 \u0641\u064e\u0644\u064e\u0646 \u064a\u064f\u0642\u06e1\u0628\u064e\u0644\u064e \u0645\u0650\u0646\u06e1\u0647\u064f \u0648\u064e\u0647\u064f\u0648\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u062e\u064e\u0670\u0633\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan barang siapa mencari agama selain Islam, dia tidak akan diterima, dan di akhirat dia termasuk orang yang rugi"},{id:86,text:"\u0643\u064e\u064a\u06e1\u0641\u064e \u064a\u064e\u0647\u06e1\u062f\u0650\u064a \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0642\u064e\u0648\u06e1\u0645\u0657\u0627 \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0628\u064e\u0639\u06e1\u062f\u064e \u0625\u0650\u064a\u0645\u064e\u0670\u0646\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0634\u064e\u0647\u0650\u062f\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e \u062d\u064e\u0642\u0651\u065e \u0648\u064e\u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u064f\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064e\u0647\u06e1\u062f\u0650\u064a \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Bagaimana Allah akan memberi petunjuk kepada suatu kaum yang kafir setelah mereka beriman, serta mengakui bahwa Rasul (Muhammad) itu benar-benar (rasul), dan bukti-bukti yang jelas telah sampai kepada mereka? Allah tidak memberi petunjuk kepada orang zalim"},{id:87,text:"\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u062c\u064e\u0632\u064e\u0627\u0653\u0624\u064f\u0647\u064f\u0645\u06e1 \u0623\u064e\u0646\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0644\u064e\u0639\u06e1\u0646\u064e\u0629\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u0650 \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0623\u064e\u062c\u06e1\u0645\u064e\u0639\u0650\u064a\u0646\u064e",translation:"Mereka itu, balasannya ialah ditimpa laknat Allah, para malaikat, dan manusia seluruhnya"},{id:88,text:"\u062e\u064e\u0670\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0644\u064e\u0627 \u064a\u064f\u062e\u064e\u0641\u0651\u064e\u0641\u064f \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u06e1 \u064a\u064f\u0646\u0638\u064e\u0631\u064f\u0648\u0646\u064e",translation:"mereka kekal di dalamnya, tidak akan diringankan azabnya, dan mereka tidak diberi penangguhan"},{id:89,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u0627\u0628\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0648\u064e\u0623\u064e\u0635\u06e1\u0644\u064e\u062d\u064f\u0648\u0627\u0652 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064c",translation:"kecuali orang-orang yang bertobat setelah itu, dan melakukan perbaikan, maka sungguh, Allah Maha Pengampun, Maha Penyayang"},{id:90,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0628\u064e\u0639\u06e1\u062f\u064e \u0625\u0650\u064a\u0645\u064e\u0670\u0646\u0650\u0647\u0650\u0645\u06e1 \u062b\u064f\u0645\u0651\u064e \u0671\u0632\u06e1\u062f\u064e\u0627\u062f\u064f\u0648\u0627\u0652 \u0643\u064f\u0641\u06e1\u0631\u0657\u0627 \u0644\u0651\u064e\u0646 \u062a\u064f\u0642\u06e1\u0628\u064e\u0644\u064e \u062a\u064e\u0648\u06e1\u0628\u064e\u062a\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u0636\u0651\u064e\u0627\u0653\u0644\u0651\u064f\u0648\u0646\u064e",translation:"Sungguh, orang-orang yang kafir setelah beriman, kemudian bertambah kekafirannya, tidak akan diterima tobatnya, dan mereka itulah orang-orang yang sesat"},{id:91,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u0645\u064e\u0627\u062a\u064f\u0648\u0627\u0652 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0643\u064f\u0641\u0651\u064e\u0627\u0631\u065e \u0641\u064e\u0644\u064e\u0646 \u064a\u064f\u0642\u06e1\u0628\u064e\u0644\u064e \u0645\u0650\u0646\u06e1 \u0623\u064e\u062d\u064e\u062f\u0650\u0647\u0650\u0645 \u0645\u0651\u0650\u0644\u06e1\u0621\u064f \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0630\u064e\u0647\u064e\u0628\u0657\u0627 \u0648\u064e\u0644\u064e\u0648\u0650 \u0671\u0641\u06e1\u062a\u064e\u062f\u064e\u0649\u0670 \u0628\u0650\u0647\u0650\u06e6\u0653\u06d7 \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u065e \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0646\u0651\u064e\u0640\u0670\u0635\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Sungguh, orang-orang yang kafir dan mati dalam kekafiran, tidak akan diterima (tebusan) dari seseorang di antara mereka sekalipun (berupa) emas sepenuh bumi, sekiranya dia hendak menebus diri dengannya. Mereka itulah orang-orang yang mendapat azab yang pedih dan tidak memperoleh penolong"},{id:92,text:"\u0644\u064e\u0646 \u062a\u064e\u0646\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0628\u0650\u0631\u0651\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062a\u064f\u0646\u0641\u0650\u0642\u064f\u0648\u0627\u0652 \u0645\u0650\u0645\u0651\u064e\u0627 \u062a\u064f\u062d\u0650\u0628\u0651\u064f\u0648\u0646\u064e\u06da \u0648\u064e\u0645\u064e\u0627 \u062a\u064f\u0646\u0641\u0650\u0642\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u0647\u0650\u06e6 \u0639\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Kamu tidak akan memperoleh kebajikan, sebelum kamu menginfakkan sebagian harta yang kamu cintai. Dan apa pun yang kamu infakkan, tentang hal itu sungguh, Allah Maha Mengetahui"},{id:93,text:"\u06de\u0643\u064f\u0644\u0651\u064f \u0671\u0644\u0637\u0651\u064e\u0639\u064e\u0627\u0645\u0650 \u0643\u064e\u0627\u0646\u064e \u062d\u0650\u0644\u0651\u0657\u0627 \u0644\u0651\u0650\u0628\u064e\u0646\u0650\u064a\u0653 \u0625\u0650\u0633\u06e1\u0631\u064e\u0640\u0670\u0653\u0621\u0650\u064a\u0644\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u062d\u064e\u0631\u0651\u064e\u0645\u064e \u0625\u0650\u0633\u06e1\u0631\u064e\u0640\u0670\u0653\u0621\u0650\u064a\u0644\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0646\u064e\u0641\u06e1\u0633\u0650\u0647\u0650\u06e6 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650 \u0623\u064e\u0646 \u062a\u064f\u0646\u064e\u0632\u0651\u064e\u0644\u064e \u0671\u0644\u062a\u0651\u064e\u0648\u06e1\u0631\u064e\u0649\u0670\u0629\u064f\u06da \u0642\u064f\u0644\u06e1 \u0641\u064e\u0623\u06e1\u062a\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u062a\u0651\u064e\u0648\u06e1\u0631\u064e\u0649\u0670\u0629\u0650 \u0641\u064e\u0671\u062a\u06e1\u0644\u064f\u0648\u0647\u064e\u0627\u0653 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0635\u064e\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Semua makanan itu halal bagi Bani Israil, kecuali makanan yang diharamkan oleh Israil (Yakub) atas dirinya sebelum Taurat diturunkan.131) Katakanlah (Muhammad), \"Maka bawalah Taurat lalu bacalah, jika kamu orang-orang yang benar"},{id:94,text:"\u0641\u064e\u0645\u064e\u0646\u0650 \u0671\u0641\u06e1\u062a\u064e\u0631\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u0643\u064e\u0630\u0650\u0628\u064e \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"(Maka barang siapa mengada-adakan kebohongan terhadap Allah132) setelah itu, maka mereka itulah orang-orang zalim"},{id:95,text:"\u0642\u064f\u0644\u06e1 \u0635\u064e\u062f\u064e\u0642\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06d7 \u0641\u064e\u0671\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0627\u0652 \u0645\u0650\u0644\u0651\u064e\u0629\u064e \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064e \u062d\u064e\u0646\u0650\u064a\u0641\u0657\u0627\u06d6 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0634\u06e1\u0631\u0650\u0643\u0650\u064a\u0646\u064e",translation:"Katakanlah (Muhammad), \"Benarlah (segala yang difirmankan) Allah.\" Maka ikutilah agama Ibrahim yang lurus, dan dia tidaklah termasuk orang musyrik"},{id:96,text:"\u0625\u0650\u0646\u0651\u064e \u0623\u064e\u0648\u0651\u064e\u0644\u064e \u0628\u064e\u064a\u06e1\u062a\u0656 \u0648\u064f\u0636\u0650\u0639\u064e \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0644\u0651\u064e\u0630\u0650\u064a \u0628\u0650\u0628\u064e\u0643\u0651\u064e\u0629\u064e \u0645\u064f\u0628\u064e\u0627\u0631\u064e\u0643\u0657\u0627 \u0648\u064e\u0647\u064f\u062f\u0657\u0649 \u0644\u0651\u0650\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Sesungguhnya rumah (ibadah) pertama yang dibangun untuk manusia, ialah (Baitullah) yang di Bakkah (Mekah)133) yang diberkahi dan menjadi petunjuk bagi seluruh alam"},{id:97,text:"\u0641\u0650\u064a\u0647\u0650 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u064f\u06e2 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u065e \u0645\u0651\u064e\u0642\u064e\u0627\u0645\u064f \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064e\u06d6 \u0648\u064e\u0645\u064e\u0646 \u062f\u064e\u062e\u064e\u0644\u064e\u0647\u064f\u06e5 \u0643\u064e\u0627\u0646\u064e \u0621\u064e\u0627\u0645\u0650\u0646\u0657\u0627\u06d7 \u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u062d\u0650\u062c\u0651\u064f \u0671\u0644\u06e1\u0628\u064e\u064a\u06e1\u062a\u0650 \u0645\u064e\u0646\u0650 \u0671\u0633\u06e1\u062a\u064e\u0637\u064e\u0627\u0639\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0633\u064e\u0628\u0650\u064a\u0644\u0657\u0627\u06da \u0648\u064e\u0645\u064e\u0646 \u0643\u064e\u0641\u064e\u0631\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0646\u0650\u064a\u0651\u064c \u0639\u064e\u0646\u0650 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Di sana terdapat tanda-tanda yang jelas, (di antaranya) maqam Ibrahim.134) Barang siapa memasukinya (Baitullah) amanlah dia. Dan (di antara) kewajiban manusia terhadap Allah adalah melaksanakan ibadah haji ke Baitullah, yaitu bagi orang-orang yang mampu135) mengadakan perjalanan ke sana. Barang siapa mengingkari (kewajiban) haji, maka ketahuilah bahwa Allah Mahakaya (tidak memerlukan sesuatu) dari seluruh alam"},{id:98,text:"\u0642\u064f\u0644\u06e1 \u064a\u064e\u0640\u0670\u0653\u0623\u064e\u0647\u06e1\u0644\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0644\u0650\u0645\u064e \u062a\u064e\u0643\u06e1\u0641\u064f\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0634\u064e\u0647\u0650\u064a\u062f\u064c \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Katakanlah (Muhammad), \"Wahai Ahli Kitab! Mengapa kamu mengingkari ayat-ayat Allah, padahal Allah Maha Menyaksikan apa yang kamu kerjakan"},{id:99,text:"\u0642\u064f\u0644\u06e1 \u064a\u064e\u0640\u0670\u0653\u0623\u064e\u0647\u06e1\u0644\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0644\u0650\u0645\u064e \u062a\u064e\u0635\u064f\u062f\u0651\u064f\u0648\u0646\u064e \u0639\u064e\u0646 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0646\u06e1 \u0621\u064e\u0627\u0645\u064e\u0646\u064e \u062a\u064e\u0628\u06e1\u063a\u064f\u0648\u0646\u064e\u0647\u064e\u0627 \u0639\u0650\u0648\u064e\u062c\u0657\u0627 \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0634\u064f\u0647\u064e\u062f\u064e\u0627\u0653\u0621\u064f\u06d7 \u0648\u064e\u0645\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u063a\u064e\u0670\u0641\u0650\u0644\u064d \u0639\u064e\u0645\u0651\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Katakanlah (Muhammad), \"Wahai Ahli Kitab! Mengapa kamu menghalang-halangi orang-orang yang beriman dari jalan Allah, kamu menghendakinya (jalan Allah) bengkok, padahal kamu menyaksikan?\"136) Dan Allah tidak lengah terhadap apa yang kamu kerjakan"},{id:100,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646 \u062a\u064f\u0637\u0650\u064a\u0639\u064f\u0648\u0627\u0652 \u0641\u064e\u0631\u0650\u064a\u0642\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u064a\u064e\u0631\u064f\u062f\u0651\u064f\u0648\u0643\u064f\u0645 \u0628\u064e\u0639\u06e1\u062f\u064e \u0625\u0650\u064a\u0645\u064e\u0670\u0646\u0650\u0643\u064f\u0645\u06e1 \u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Wahai orang-orang yang beriman! Jika kamu mengikuti sebagian dari orang yang diberi Kitab, niscaya mereka akan mengembalikan kamu menjadi orang kafir setelah beriman"},{id:101,text:"\u0648\u064e\u0643\u064e\u064a\u06e1\u0641\u064e \u062a\u064e\u0643\u06e1\u0641\u064f\u0631\u064f\u0648\u0646\u064e \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u062a\u064f\u062a\u06e1\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0641\u0650\u064a\u0643\u064f\u0645\u06e1 \u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0647\u064f\u06e5\u06d7 \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0639\u06e1\u062a\u064e\u0635\u0650\u0645 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0642\u064e\u062f\u06e1 \u0647\u064f\u062f\u0650\u064a\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0670\u0637\u0656 \u0645\u0651\u064f\u0633\u06e1\u062a\u064e\u0642\u0650\u064a\u0645\u0656",translation:"Dan bagaimana kamu (sampai) menjadi kafir, padahal ayat-ayat Allah dibacakan kepada kamu, dan Rasul-Nya (Muhammad) pun berada di tengah-tengah kamu? Barang siapa berpegang teguh kepada (agama) Allah, maka sungguh, dia diberi petunjuk ke jalan yang lurus"},{id:102,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u062d\u064e\u0642\u0651\u064e \u062a\u064f\u0642\u064e\u0627\u062a\u0650\u0647\u0650\u06e6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0645\u064f\u0648\u062a\u064f\u0646\u0651\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645 \u0645\u0651\u064f\u0633\u06e1\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Wahai orang-orang yang beriman! Bertakwalah kepada Allah sebenar-benar takwa kepada-Nya dan janganlah kamu mati kecuali dalam keadaan Muslim"},{id:103,text:"\u0648\u064e\u0671\u0639\u06e1\u062a\u064e\u0635\u0650\u0645\u064f\u0648\u0627\u0652 \u0628\u0650\u062d\u064e\u0628\u06e1\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062c\u064e\u0645\u0650\u064a\u0639\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0641\u064e\u0631\u0651\u064e\u0642\u064f\u0648\u0627\u0652\u06da \u0648\u064e\u0671\u0630\u06e1\u0643\u064f\u0631\u064f\u0648\u0627\u0652 \u0646\u0650\u0639\u06e1\u0645\u064e\u062a\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0625\u0650\u0630\u06e1 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0623\u064e\u0639\u06e1\u062f\u064e\u0627\u0653\u0621\u0657 \u0641\u064e\u0623\u064e\u0644\u0651\u064e\u0641\u064e \u0628\u064e\u064a\u06e1\u0646\u064e \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0643\u064f\u0645\u06e1 \u0641\u064e\u0623\u064e\u0635\u06e1\u0628\u064e\u062d\u06e1\u062a\u064f\u0645 \u0628\u0650\u0646\u0650\u0639\u06e1\u0645\u064e\u062a\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u062e\u06e1\u0648\u064e\u0670\u0646\u0657\u0627 \u0648\u064e\u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0634\u064e\u0641\u064e\u0627 \u062d\u064f\u0641\u06e1\u0631\u064e\u0629\u0656 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0641\u064e\u0623\u064e\u0646\u0642\u064e\u0630\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1\u0647\u064e\u0627\u06d7 \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0647\u0650\u06e6 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u0647\u06e1\u062a\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Dan berpegangteguhlah kamu semuanya pada tali (agama) Allah, dan janganlah kamu bercerai berai, dan ingatlah nikmat Allah kepadamu ketika kamu dahulu (masa jahiliah) bermusuhan, lalu Allah mempersatukan hatimu, sehingga dengan karunia-Nya kamu menjadi bersaudara, sedangkan (ketika itu) kamu berada di tepi jurang neraka, lalu Allah menyelamatkan kamu dari sana. Demikianlah, Allah menerangkan ayat-ayat-Nya kepadamu agar kamu mendapat petunjuk"},{id:104,text:"\u0648\u064e\u0644\u06e1\u062a\u064e\u0643\u064f\u0646 \u0645\u0651\u0650\u0646\u0643\u064f\u0645\u06e1 \u0623\u064f\u0645\u0651\u064e\u0629\u065e \u064a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u062e\u064e\u064a\u06e1\u0631\u0650 \u0648\u064e\u064a\u064e\u0623\u06e1\u0645\u064f\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u06e1\u0645\u064e\u0639\u06e1\u0631\u064f\u0648\u0641\u0650 \u0648\u064e\u064a\u064e\u0646\u06e1\u0647\u064e\u0648\u06e1\u0646\u064e \u0639\u064e\u0646\u0650 \u0671\u0644\u06e1\u0645\u064f\u0646\u0643\u064e\u0631\u0650\u06da \u0648\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064f\u0641\u06e1\u0644\u0650\u062d\u064f\u0648\u0646\u064e",translation:"Dan hendaklah di antara kamu ada segolongan orang yang menyeru kepada kebajikan, menyuruh (berbuat) yang makruf, dan mencegah dari yang mungkar. 137) Dan mereka itulah orang-orang yang beruntung"},{id:105,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u0643\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u0641\u064e\u0631\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0648\u064e\u0671\u062e\u06e1\u062a\u064e\u0644\u064e\u0641\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0645\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u064f\u06da \u0648\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u065e",translation:"Dan janganlah kamu menjadi seperti orang-orang yang bercerai berai dan berselisih setelah sampai kepada mereka keterangan yang jelas. Dan mereka itulah orang-orang yang mendapat azab yang berat"},{id:106,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u062a\u064e\u0628\u06e1\u064a\u064e\u0636\u0651\u064f \u0648\u064f\u062c\u064f\u0648\u0647\u065e \u0648\u064e\u062a\u064e\u0633\u06e1\u0648\u064e\u062f\u0651\u064f \u0648\u064f\u062c\u064f\u0648\u0647\u065e\u06da \u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u0633\u06e1\u0648\u064e\u062f\u0651\u064e\u062a\u06e1 \u0648\u064f\u062c\u064f\u0648\u0647\u064f\u0647\u064f\u0645\u06e1 \u0623\u064e\u0643\u064e\u0641\u064e\u0631\u06e1\u062a\u064f\u0645 \u0628\u064e\u0639\u06e1\u062f\u064e \u0625\u0650\u064a\u0645\u064e\u0670\u0646\u0650\u0643\u064f\u0645\u06e1 \u0641\u064e\u0630\u064f\u0648\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0643\u06e1\u0641\u064f\u0631\u064f\u0648\u0646\u064e",translation:"pada hari itu ada wajah yang putih berseri, dan ada pula wajah yang hitam muram. Adapun orang-orang yang berwajah hitam muram (kepada mereka dikatakan), \"Mengapa kamu kafir setelah beriman? Karena itu rasakanlah azab akibat kekafiranmu itu"},{id:107,text:"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u0628\u06e1\u064a\u064e\u0636\u0651\u064e\u062a\u06e1 \u0648\u064f\u062c\u064f\u0648\u0647\u064f\u0647\u064f\u0645\u06e1 \u0641\u064e\u0641\u0650\u064a \u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u0670\u0644\u0650\u062f\u064f\u0648\u0646\u064e",translation:"Dan adapun orang-orang yang berwajah putih berseri, mereka berada dalam rahmat Allah (surga); mereka kekal di dalamnya"},{id:108,text:"\u062a\u0650\u0644\u06e1\u0643\u064e \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0646\u064e\u062a\u06e1\u0644\u064f\u0648\u0647\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650\u06d7 \u0648\u064e\u0645\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0638\u064f\u0644\u06e1\u0645\u0657\u0627 \u0644\u0651\u0650\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Itulah ayat-ayat Allah yang Kami bacakan kepada kamu dengan benar, dan Allah tidaklah berkehendak menzalimi (siapa pun) di seluruh alam"},{id:109,text:"\u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06da \u0648\u064e\u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064f\u0631\u06e1\u062c\u064e\u0639\u064f \u0671\u0644\u06e1\u0623\u064f\u0645\u064f\u0648\u0631\u064f",translation:"Dan milik Allahlah apa yang ada di langit dan apa yang ada di bumi, dan hanya kepada Allah segala urusan dikembalikan"},{id:110,text:"\u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062e\u064e\u064a\u06e1\u0631\u064e \u0623\u064f\u0645\u0651\u064e\u0629\u064d \u0623\u064f\u062e\u06e1\u0631\u0650\u062c\u064e\u062a\u06e1 \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u062a\u064e\u0623\u06e1\u0645\u064f\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u06e1\u0645\u064e\u0639\u06e1\u0631\u064f\u0648\u0641\u0650 \u0648\u064e\u062a\u064e\u0646\u06e1\u0647\u064e\u0648\u06e1\u0646\u064e \u0639\u064e\u0646\u0650 \u0671\u0644\u06e1\u0645\u064f\u0646\u0643\u064e\u0631\u0650 \u0648\u064e\u062a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d7 \u0648\u064e\u0644\u064e\u0648\u06e1 \u0621\u064e\u0627\u0645\u064e\u0646\u064e \u0623\u064e\u0647\u06e1\u0644\u064f \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0644\u064e\u0643\u064e\u0627\u0646\u064e \u062e\u064e\u064a\u06e1\u0631\u0657\u0627 \u0644\u0651\u064e\u0647\u064f\u0645\u06da \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0648\u064e\u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064f\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0641\u064e\u0670\u0633\u0650\u0642\u064f\u0648\u0646\u064e",translation:"Kamu (umat Islam) adalah umat terbaik yang dilahirkan untuk manusia, (karena kamu) menyuruh (berbuat) yang makruf, dan mencegah dari yang mungkar, dan beriman kepada Allah. Sekiranya Ahli Kitab beriman, tentulah itu lebih baik bagi mereka. Di antara mereka ada yang beriman, namun kebanyakan mereka adalah orang-orang fasik"},{id:111,text:"\u0644\u064e\u0646 \u064a\u064e\u0636\u064f\u0631\u0651\u064f\u0648\u0643\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0630\u0657\u0649\u06d6 \u0648\u064e\u0625\u0650\u0646 \u064a\u064f\u0642\u064e\u0670\u062a\u0650\u0644\u064f\u0648\u0643\u064f\u0645\u06e1 \u064a\u064f\u0648\u064e\u0644\u0651\u064f\u0648\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u062f\u06e1\u0628\u064e\u0627\u0631\u064e \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0627 \u064a\u064f\u0646\u0635\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Mereka tidak akan membahayakan kamu, kecuali gangguan-gangguan kecil saja, dan jika mereka memerangi kamu, niscaya mereka mundur berbalik ke belakang (kalah). Selanjutnya mereka tidak mendapat pertolongan"},{id:112,text:"\u0636\u064f\u0631\u0650\u0628\u064e\u062a\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u064f \u0671\u0644\u0630\u0651\u0650\u0644\u0651\u064e\u0629\u064f \u0623\u064e\u064a\u06e1\u0646\u064e \u0645\u064e\u0627 \u062b\u064f\u0642\u0650\u0641\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u062d\u064e\u0628\u06e1\u0644\u0656 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u062d\u064e\u0628\u06e1\u0644\u0656 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0628\u064e\u0627\u0653\u0621\u064f\u0648 \u0628\u0650\u063a\u064e\u0636\u064e\u0628\u0656 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0636\u064f\u0631\u0650\u0628\u064e\u062a\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u064f \u0671\u0644\u06e1\u0645\u064e\u0633\u06e1\u0643\u064e\u0646\u064e\u0629\u064f\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0643\u06e1\u0641\u064f\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u064a\u064e\u0642\u06e1\u062a\u064f\u0644\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u0646\u06e2\u0628\u0650\u064a\u064e\u0627\u0653\u0621\u064e \u0628\u0650\u063a\u064e\u064a\u06e1\u0631\u0650 \u062d\u064e\u0642\u0651\u0656\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0645\u064e\u0627 \u0639\u064e\u0635\u064e\u0648\u0627\u0652 \u0648\u0651\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u062a\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Mereka diliputi kehinaan di mana saja mereka berada, kecuali jika mereka (berpegang) pada tali (agama) Allah dan tali (perjanjian) dengan manusia. Mereka mendapat murka dari Allah dan (selalu) diliputi kesengsaraan. Yang demikian itu karena mereka mengingkari ayat-ayat Allah dan membunuh para nabi, tanpa hak (alasan yang benar). Yang demikian itu karena mereka durhaka dan melampaui batas"},{id:113,text:"\u06de\u0644\u064e\u064a\u06e1\u0633\u064f\u0648\u0627\u0652 \u0633\u064e\u0648\u064e\u0627\u0653\u0621\u0657\u06d7 \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u0647\u06e1\u0644\u0650 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0623\u064f\u0645\u0651\u064e\u0629\u065e \u0642\u064e\u0627\u0653\u0626\u0650\u0645\u064e\u0629\u065e \u064a\u064e\u062a\u06e1\u0644\u064f\u0648\u0646\u064e \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0621\u064e\u0627\u0646\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u0650 \u0648\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0633\u06e1\u062c\u064f\u062f\u064f\u0648\u0646\u064e",translation:"Mereka itu tidak (seluruhnya) sama. Di antara Ahli Kitab ada golongan yang jujur,138) mereka membaca ayat-ayat Allah pada malam hari, dan mereka (juga) bersujud (salat)"},{id:114,text:"\u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u0650 \u0648\u064e\u064a\u064e\u0623\u06e1\u0645\u064f\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u06e1\u0645\u064e\u0639\u06e1\u0631\u064f\u0648\u0641\u0650 \u0648\u064e\u064a\u064e\u0646\u06e1\u0647\u064e\u0648\u06e1\u0646\u064e \u0639\u064e\u0646\u0650 \u0671\u0644\u06e1\u0645\u064f\u0646\u0643\u064e\u0631\u0650 \u0648\u064e\u064a\u064f\u0633\u064e\u0670\u0631\u0650\u0639\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u062e\u064e\u064a\u06e1\u0631\u064e\u0670\u062a\u0650\u06d6 \u0648\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u0650\u064a\u0646\u064e",translation:"Mereka beriman kepada Allah dan hari akhir, menyuruh (berbuat) yang makruf, dan mencegah dari yang mungkar dan bersegera (mengerjakan) berbagai kebajikan. Mereka termasuk orang-orang saleh"},{id:115,text:"\u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0641\u06e1\u0639\u064e\u0644\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1 \u062e\u064e\u064a\u06e1\u0631\u0656 \u0641\u064e\u0644\u064e\u0646 \u064a\u064f\u0643\u06e1\u0641\u064e\u0631\u064f\u0648\u0647\u064f\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064f\u06e2 \u0628\u0650\u0671\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",translation:"Dan kebajikan apa pun yang mereka kerjakan, tidak ada yang mengingkarinya. Dan Allah Maha Mengetahui orang-orang yang bertakwa"},{id:116,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0644\u064e\u0646 \u062a\u064f\u063a\u06e1\u0646\u0650\u064a\u064e \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064e\u0648\u06e1\u0644\u064e\u0670\u062f\u064f\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627\u06d6 \u0648\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650\u06d6 \u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u0670\u0644\u0650\u062f\u064f\u0648\u0646\u064e",translation:"Sesungguhnya orang-orang kafir, baik harta maupun anak-anak mereka, sedikit pun tidak dapat menolak azab Allah. Mereka itu penghuni neraka, (dan) mereka kekal di dalamnya"},{id:117,text:"\u0645\u064e\u062b\u064e\u0644\u064f \u0645\u064e\u0627 \u064a\u064f\u0646\u0641\u0650\u0642\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0647\u064e\u0670\u0630\u0650\u0647\u0650 \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u0650 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0643\u064e\u0645\u064e\u062b\u064e\u0644\u0650 \u0631\u0650\u064a\u062d\u0656 \u0641\u0650\u064a\u0647\u064e\u0627 \u0635\u0650\u0631\u0651\u064c \u0623\u064e\u0635\u064e\u0627\u0628\u064e\u062a\u06e1 \u062d\u064e\u0631\u06e1\u062b\u064e \u0642\u064e\u0648\u06e1\u0645\u0656 \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u06e1 \u0641\u064e\u0623\u064e\u0647\u06e1\u0644\u064e\u0643\u064e\u062a\u06e1\u0647\u064f\u06da \u0648\u064e\u0645\u064e\u0627 \u0638\u064e\u0644\u064e\u0645\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u06e1 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0638\u06e1\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Perumpamaan harta yang mereka infakkan di dalam kehidupan dunia ini, ibarat angin yang mengandung hawa yang sangat dingin, yang menimpa tanaman (milik) suatu kaum yang menzalimi diri sendiri, lalu angin itu merusaknya. Allah tidak menzalimi mereka, tetapi mereka yang menzalimi diri sendiri"},{id:118,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0627\u0652 \u0628\u0650\u0637\u064e\u0627\u0646\u064e\u0629\u0657 \u0645\u0651\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0643\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0623\u06e1\u0644\u064f\u0648\u0646\u064e\u0643\u064f\u0645\u06e1 \u062e\u064e\u0628\u064e\u0627\u0644\u0657\u0627 \u0648\u064e\u062f\u0651\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u0639\u064e\u0646\u0650\u062a\u0651\u064f\u0645\u06e1 \u0642\u064e\u062f\u06e1 \u0628\u064e\u062f\u064e\u062a\u0650 \u0671\u0644\u06e1\u0628\u064e\u063a\u06e1\u0636\u064e\u0627\u0653\u0621\u064f \u0645\u0650\u0646\u06e1 \u0623\u064e\u0641\u06e1\u0648\u064e\u0670\u0647\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627 \u062a\u064f\u062e\u06e1\u0641\u0650\u064a \u0635\u064f\u062f\u064f\u0648\u0631\u064f\u0647\u064f\u0645\u06e1 \u0623\u064e\u0643\u06e1\u0628\u064e\u0631\u064f\u06da \u0642\u064e\u062f\u06e1 \u0628\u064e\u064a\u0651\u064e\u0646\u0651\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0623\u0653\u064a\u064e\u0670\u062a\u0650\u06d6 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Wahai orang-orang yang beriman! Janganlah kamu menjadikan teman orang-orang yang di luar kalanganmu (seagama) sebagai teman kepercayaanmu, (karena) mereka tidak henti-hentinya menyusahkan kamu. Mereka mengharapkan kehancuranmu. Sungguh, telah nyata kebencian dari mulut mereka, dan apa yang tersembunyi di hati mereka lebih jahat. Sungguh, telah Kami terangkan kepadamu ayat-ayat (Kami), jika kamu mengerti"},{id:119,text:"\u0647\u064e\u0640\u0670\u0653\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0623\u064f\u0648\u0652\u0644\u064e\u0627\u0653\u0621\u0650 \u062a\u064f\u062d\u0650\u0628\u0651\u064f\u0648\u0646\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f\u0648\u0646\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u062a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0643\u064f\u0644\u0651\u0650\u0647\u0650\u06e6 \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0644\u064e\u0642\u064f\u0648\u0643\u064f\u0645\u06e1 \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0621\u064e\u0627\u0645\u064e\u0646\u0651\u064e\u0627 \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062e\u064e\u0644\u064e\u0648\u06e1\u0627\u0652 \u0639\u064e\u0636\u0651\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u0646\u064e\u0627\u0645\u0650\u0644\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u0638\u0650\u06da \u0642\u064f\u0644\u06e1 \u0645\u064f\u0648\u062a\u064f\u0648\u0627\u0652 \u0628\u0650\u063a\u064e\u064a\u06e1\u0638\u0650\u0643\u064f\u0645\u06e1\u06d7 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u064f\u06e2 \u0628\u0650\u0630\u064e\u0627\u062a\u0650 \u0671\u0644\u0635\u0651\u064f\u062f\u064f\u0648\u0631\u0650",translation:"Beginilah kamu! Kamu menyukai mereka, padahal mereka tidak menyukaimu, dan kamu beriman kepada semua kitab. Apabila mereka berjumpa denganmu, mereka berkata, \"Kami beriman,\" dan apabila mereka menyendiri, mereka menggigit ujung jari karena marah dan benci kepadamu. Katakanlah, \"Matilah kamu karena kemarahanmu itu!\" Sungguh, Allah Maha Mengetahui segala isi hati"},{id:120,text:"\u0625\u0650\u0646 \u062a\u064e\u0645\u06e1\u0633\u064e\u0633\u06e1\u0643\u064f\u0645\u06e1 \u062d\u064e\u0633\u064e\u0646\u064e\u0629\u065e \u062a\u064e\u0633\u064f\u0624\u06e1\u0647\u064f\u0645\u06e1 \u0648\u064e\u0625\u0650\u0646 \u062a\u064f\u0635\u0650\u0628\u06e1\u0643\u064f\u0645\u06e1 \u0633\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u065e \u064a\u064e\u0641\u06e1\u0631\u064e\u062d\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u064e\u0627\u06d6 \u0648\u064e\u0625\u0650\u0646 \u062a\u064e\u0635\u06e1\u0628\u0650\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u064a\u064e\u0636\u064f\u0631\u0651\u064f\u0643\u064f\u0645\u06e1 \u0643\u064e\u064a\u06e1\u062f\u064f\u0647\u064f\u0645\u06e1 \u0634\u064e\u064a\u06e1\u0640\u0654\u064b\u0627\u06d7 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u0645\u064e\u0627 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0645\u064f\u062d\u0650\u064a\u0637\u065e",translation:"Jika kamu memperoleh kebaikan, (niscaya) mereka bersedih hati, tetapi jika kamu tertimpa bencana, mereka bergembira karenanya. Jika kamu bersabar dan bertakwa, tipu daya mereka tidak akan menyusahkan kamu sedikit pun. Sungguh, Allah Maha Meliputi segala apa yang mereka kerjakan"},{id:121,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u063a\u064e\u062f\u064e\u0648\u06e1\u062a\u064e \u0645\u0650\u0646\u06e1 \u0623\u064e\u0647\u06e1\u0644\u0650\u0643\u064e \u062a\u064f\u0628\u064e\u0648\u0651\u0650\u0626\u064f \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0645\u064e\u0642\u064e\u0670\u0639\u0650\u062f\u064e \u0644\u0650\u0644\u06e1\u0642\u0650\u062a\u064e\u0627\u0644\u0650\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0633\u064e\u0645\u0650\u064a\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u064c",translation:"Dan (ingatlah), ketika engkau (Muhammad) berangkat pada pagi hari meninggalkan keluargamu untuk mengatur orang-orang beriman pada pos-pos pertempuran.139) Allah Maha Mendengar, Maha Mengetahui"},{id:122,text:"\u0625\u0650\u0630\u06e1 \u0647\u064e\u0645\u0651\u064e\u062a \u0637\u0651\u064e\u0627\u0653\u0626\u0650\u0641\u064e\u062a\u064e\u0627\u0646\u0650 \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u0623\u064e\u0646 \u062a\u064e\u0641\u06e1\u0634\u064e\u0644\u064e\u0627 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0644\u0650\u064a\u0651\u064f\u0647\u064f\u0645\u064e\u0627\u06d7 \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0644\u06e1\u064a\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u0650 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"(ketika dua golongan dari pihak kamu140) ingin (mundur) karena takut, padahal Allah adalah penolong mereka. Karena itu, hendaklah kepada Allah saja orang-orang mukmin bertawakal"},{id:123,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0646\u064e\u0635\u064e\u0631\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0628\u064e\u062f\u06e1\u0631\u0656 \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0623\u064e\u0630\u0650\u0644\u0651\u064e\u0629\u065e\u06d6 \u0641\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u0634\u06e1\u0643\u064f\u0631\u064f\u0648\u0646\u064e",translation:"(Dan sungguh, Allah telah menolong kamu dalam Perang Badar, padahal kamu dalam keadaan lemah.141) Karena itu bertakwalah kepada Allah, agar kamu mensyukuri-Nya"},{id:124,text:"\u0625\u0650\u0630\u06e1 \u062a\u064e\u0642\u064f\u0648\u0644\u064f \u0644\u0650\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0623\u064e\u0644\u064e\u0646 \u064a\u064e\u0643\u06e1\u0641\u0650\u064a\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u0646 \u064a\u064f\u0645\u0650\u062f\u0651\u064e\u0643\u064f\u0645\u06e1 \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645 \u0628\u0650\u062b\u064e\u0644\u064e\u0670\u062b\u064e\u0629\u0650 \u0621\u064e\u0627\u0644\u064e\u0670\u0641\u0656 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u0650 \u0645\u064f\u0646\u0632\u064e\u0644\u0650\u064a\u0646\u064e",translation:"(Ingatlah), ketika engkau (Muhammad) mengatakan kepada orang-orang beriman, \"Apakah tidak cukup bagimu bahwa Allah membantu kamu dengan tiga ribu malaikat yang diturunkan (dari langit)"},{id:125,text:"\u0628\u064e\u0644\u064e\u0649\u0670\u0653\u06da \u0625\u0650\u0646 \u062a\u064e\u0635\u06e1\u0628\u0650\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0648\u064e\u064a\u064e\u0623\u06e1\u062a\u064f\u0648\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0641\u064e\u0648\u06e1\u0631\u0650\u0647\u0650\u0645\u06e1 \u0647\u064e\u0670\u0630\u064e\u0627 \u064a\u064f\u0645\u06e1\u062f\u0650\u062f\u06e1\u0643\u064f\u0645\u06e1 \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645 \u0628\u0650\u062e\u064e\u0645\u06e1\u0633\u064e\u0629\u0650 \u0621\u064e\u0627\u0644\u064e\u0670\u0641\u0656 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u0650 \u0645\u064f\u0633\u064e\u0648\u0651\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Ya\" (cukup). Jika kamu bersabar dan bertakwa ketika mereka datang menyerang kamu dengan tiba-tiba, niscaya Allah menolongmu dengan lima ribu malaikat yang memakai tanda"},{id:126,text:"\u0648\u064e\u0645\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u064e\u0647\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u064f\u0634\u06e1\u0631\u064e\u0649\u0670 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u0650\u062a\u064e\u0637\u06e1\u0645\u064e\u0626\u0650\u0646\u0651\u064e \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0643\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6\u06d7 \u0648\u064e\u0645\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0635\u06e1\u0631\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u0650\u0646\u06e1 \u0639\u0650\u0646\u062f\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u0650 \u0671\u0644\u06e1\u062d\u064e\u0643\u0650\u064a\u0645\u0650",translation:"Dan Allah tidak menjadikannya (pemberian bala-bantuan itu) melainkan sebagai kabar gembira bagi (kemenangan)mu, dan agar hatimu tenang karenanya. Dan tidak ada kemenangan itu, selain dari Allah Yang Mahaperkasa, Mahabijaksana"},{id:127,text:"\u0644\u0650\u064a\u064e\u0642\u06e1\u0637\u064e\u0639\u064e \u0637\u064e\u0631\u064e\u0641\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0648\u06e1 \u064a\u064e\u0643\u06e1\u0628\u0650\u062a\u064e\u0647\u064f\u0645\u06e1 \u0641\u064e\u064a\u064e\u0646\u0642\u064e\u0644\u0650\u0628\u064f\u0648\u0627\u0652 \u062e\u064e\u0627\u0653\u0626\u0650\u0628\u0650\u064a\u0646\u064e",translation:"(Allah menolong kamu dalam perang Badar dan memberi bantuan) adalah untuk membinasakan segolongan orang kafir,142) atau untuk menjadikan mereka hina, sehingga mereka kembali tanpa memperoleh apa pun"},{id:128,text:"\u0644\u064e\u064a\u06e1\u0633\u064e \u0644\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0631\u0650 \u0634\u064e\u064a\u06e1\u0621\u064c \u0623\u064e\u0648\u06e1 \u064a\u064e\u062a\u064f\u0648\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0623\u064e\u0648\u06e1 \u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064e\u0647\u064f\u0645\u06e1 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0638\u064e\u0670\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Itu bukan menjadi urusanmu (Muhammad)143) apakah Allah menerima tobat mereka, atau mengazabnya, karena sesungguhnya mereka orang-orang zalim"},{id:129,text:"\u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06da \u064a\u064e\u063a\u06e1\u0641\u0650\u0631\u064f \u0644\u0650\u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0648\u064e\u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064f \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u065e",translation:"Dan milik Allahlah apa yang ada di langit dan apa yang ada di bumi. Dia mengampuni siapa yang Dia kehendaki, dan mengazab siapa yang Dia kehendaki. Dan Allah Maha Pengampun, Maha Penyayang"},{id:130,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u062a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0631\u0651\u0650\u0628\u064e\u0648\u0670\u0653\u0627\u0652 \u0623\u064e\u0636\u06e1\u0639\u064e\u0670\u0641\u0657\u0627 \u0645\u0651\u064f\u0636\u064e\u0670\u0639\u064e\u0641\u064e\u0629\u0657\u06d6 \u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064f\u0641\u06e1\u0644\u0650\u062d\u064f\u0648\u0646\u064e",translation:"(Wahai orang-orang yang beriman! Janganlah kamu memakan riba dengan berlipat ganda 144) dan bertakwalah kepada Allah agar kamu beruntung"},{id:131,text:"\u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u064e \u0671\u0644\u0651\u064e\u062a\u0650\u064a\u0653 \u0623\u064f\u0639\u0650\u062f\u0651\u064e\u062a\u06e1 \u0644\u0650\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan peliharalah dirimu dari api neraka, yang telah disiapkan untuk orang-orang kafir"},{id:132,text:"\u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064f\u0631\u06e1\u062d\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan taatlah kepada Allah dan Rasul (Muhammad), agar kamu diberi rahmat"},{id:133,text:"\u06de\u0648\u064e\u0633\u064e\u0627\u0631\u0650\u0639\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064e\u063a\u06e1\u0641\u0650\u0631\u064e\u0629\u0656 \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u062c\u064e\u0646\u0651\u064e\u0629\u064d \u0639\u064e\u0631\u06e1\u0636\u064f\u0647\u064e\u0627 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u064f \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064f \u0623\u064f\u0639\u0650\u062f\u0651\u064e\u062a\u06e1 \u0644\u0650\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",translation:"Dan bersegeralah kamu mencari ampunan dari Tuhanmu dan mendapatkan surga yang luasnya seluas langit dan bumi yang disediakan bagi orang-orang yang bertakwa"},{id:134,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0646\u0641\u0650\u0642\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0631\u0651\u064e\u0627\u0653\u0621\u0650 \u0648\u064e\u0671\u0644\u0636\u0651\u064e\u0631\u0651\u064e\u0627\u0653\u0621\u0650 \u0648\u064e\u0671\u0644\u06e1\u0643\u064e\u0670\u0638\u0650\u0645\u0650\u064a\u0646\u064e \u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u0638\u064e \u0648\u064e\u0671\u0644\u06e1\u0639\u064e\u0627\u0641\u0650\u064a\u0646\u064e \u0639\u064e\u0646\u0650 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0671\u0644\u06e1\u0645\u064f\u062d\u06e1\u0633\u0650\u0646\u0650\u064a\u0646\u064e",translation:"(yaitu) orang yang berinfak, baik di waktu lapang maupun sempit, dan orang-orang yang menahan amarahnya dan memaafkan (kesalahan) orang lain. Dan Allah mencintai orang yang berbuat kebaikan"},{id:135,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0625\u0650\u0630\u064e\u0627 \u0641\u064e\u0639\u064e\u0644\u064f\u0648\u0627\u0652 \u0641\u064e\u0670\u062d\u0650\u0634\u064e\u0629\u064b \u0623\u064e\u0648\u06e1 \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u06e1 \u0630\u064e\u0643\u064e\u0631\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u063a\u06e1\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0644\u0650\u0630\u064f\u0646\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u063a\u06e1\u0641\u0650\u0631\u064f \u0671\u0644\u0630\u0651\u064f\u0646\u064f\u0648\u0628\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064f\u0635\u0650\u0631\u0651\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0641\u064e\u0639\u064e\u0644\u064f\u0648\u0627\u0652 \u0648\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"dan (juga) orang-orang yang apabila mengerjakan perbuatan keji atau menzalimi diri sendiri,145) (segera) mengingat Allah, lalu memohon ampun atas dosa-dosanya, dan siapa (lagi) yang dapat mengampuni dosa-dosa selain Allah? Dan mereka tidak meneruskan perbuatan dosa itu, sedang mereka mengetahui"},{id:136,text:"\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u062c\u064e\u0632\u064e\u0627\u0653\u0624\u064f\u0647\u064f\u0645 \u0645\u0651\u064e\u063a\u06e1\u0641\u0650\u0631\u064e\u0629\u065e \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u065e \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0645\u0650\u0646 \u062a\u064e\u062d\u06e1\u062a\u0650\u0647\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u064f \u062e\u064e\u0670\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627\u06da \u0648\u064e\u0646\u0650\u0639\u06e1\u0645\u064e \u0623\u064e\u062c\u06e1\u0631\u064f \u0671\u0644\u06e1\u0639\u064e\u0670\u0645\u0650\u0644\u0650\u064a\u0646\u064e",translation:"Balasan bagi mereka ialah ampunan dari Tuhan mereka dan surga-surga yang mengalir di bawahnya sungai-sungai, mereka kekal di dalamnya. Dan (itulah) sebaik-baik pahala bagi orang-orang yang beramal"},{id:137,text:"\u0642\u064e\u062f\u06e1 \u062e\u064e\u0644\u064e\u062a\u06e1 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064f\u0645\u06e1 \u0633\u064f\u0646\u064e\u0646\u065e \u0641\u064e\u0633\u0650\u064a\u0631\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0641\u064e\u0671\u0646\u0638\u064f\u0631\u064f\u0648\u0627\u0652 \u0643\u064e\u064a\u06e1\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0670\u0642\u0650\u0628\u064e\u0629\u064f \u0671\u0644\u06e1\u0645\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u0650\u064a\u0646\u064e",translation:"Sungguh, telah berlalu sebelum kamu sunah-sunah (Allah),146) karena itu berjalanlah kamu ke (segenap penjuru) bumi dan perhatikanlah bagaimana kesudahan orang yang mendustakan (rasul-rasul)"},{id:138,text:"\u0647\u064e\u0670\u0630\u064e\u0627 \u0628\u064e\u064a\u064e\u0627\u0646\u065e \u0644\u0651\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0647\u064f\u062f\u0657\u0649 \u0648\u064e\u0645\u064e\u0648\u06e1\u0639\u0650\u0638\u064e\u0629\u065e \u0644\u0651\u0650\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",translation:"Inilah (Alquran) suatu keterangan yang jelas untuk semua manusia, dan menjadi petunjuk serta pelajaran bagi orang-orang yang bertakwa"},{id:139,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0647\u0650\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062d\u06e1\u0632\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u0639\u06e1\u0644\u064e\u0648\u06e1\u0646\u064e \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645 \u0645\u0651\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dan janganlah kamu (merasa) lemah, dan jangan (pula) bersedih hati, sebab kamu paling tinggi (derajatnya), jika kamu orang beriman"},{id:140,text:"\u0625\u0650\u0646 \u064a\u064e\u0645\u06e1\u0633\u064e\u0633\u06e1\u0643\u064f\u0645\u06e1 \u0642\u064e\u0631\u06e1\u062d\u065e \u0641\u064e\u0642\u064e\u062f\u06e1 \u0645\u064e\u0633\u0651\u064e \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u064e \u0642\u064e\u0631\u06e1\u062d\u065e \u0645\u0651\u0650\u062b\u06e1\u0644\u064f\u0647\u064f\u06e5\u06da \u0648\u064e\u062a\u0650\u0644\u06e1\u0643\u064e \u0671\u0644\u06e1\u0623\u064e\u064a\u0651\u064e\u0627\u0645\u064f \u0646\u064f\u062f\u064e\u0627\u0648\u0650\u0644\u064f\u0647\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0644\u0650\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064e \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u0634\u064f\u0647\u064e\u062f\u064e\u0627\u0653\u0621\u064e\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Jika kamu (pada perang Uhud) mendapat luka, maka mereka pun (pada perang Badar) mendapat luka yang serupa. Dan masa (kejayaan dan kehancuran) itu, Kami pergilirkan di antara manusia (agar mereka mendapat pelajaran), dan agar Allah membedakan orang-orang yang beriman (dengan orang-orang kafir) dan agar sebagian kamu dijadikan-Nya (gugur sebagai) syuhada. Dan Allah tidak menyukai orang-orang zalim"},{id:141,text:"\u0648\u064e\u0644\u0650\u064a\u064f\u0645\u064e\u062d\u0651\u0650\u0635\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u064a\u064e\u0645\u06e1\u062d\u064e\u0642\u064e \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"dan agar Allah membersihkan orang-orang yang beriman (dari dosa mereka) dan membinasakan orang-orang kafir"},{id:142,text:"\u0623\u064e\u0645\u06e1 \u062d\u064e\u0633\u0650\u0628\u06e1\u062a\u064f\u0645\u06e1 \u0623\u064e\u0646 \u062a\u064e\u062f\u06e1\u062e\u064f\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u064e \u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062c\u064e\u0670\u0647\u064e\u062f\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u0648\u064e\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0628\u0650\u0631\u0650\u064a\u0646\u064e",translation:"(Apakah kamu mengira bahwa kamu akan masuk surga, padahal belum nyata bagi Allah orang-orang yang berjihad147) di antara kamu, dan belum nyata orang-orang yang sabar"},{id:143,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0645\u064e\u0646\u0651\u064e\u0648\u06e1\u0646\u064e \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650 \u0623\u064e\u0646 \u062a\u064e\u0644\u06e1\u0642\u064e\u0648\u06e1\u0647\u064f \u0641\u064e\u0642\u064e\u062f\u06e1 \u0631\u064e\u0623\u064e\u064a\u06e1\u062a\u064f\u0645\u064f\u0648\u0647\u064f \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0646\u0638\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Dan kamu benar-benar mengharapkan mati (syahid) sebelum kamu menghadapinya; maka (sekarang) kamu sungguh, telah melihatnya dan kamu menyaksikannya"},{id:144,text:"\u0648\u064e\u0645\u064e\u0627 \u0645\u064f\u062d\u064e\u0645\u0651\u064e\u062f\u064c \u0625\u0650\u0644\u0651\u064e\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u065e \u0642\u064e\u062f\u06e1 \u062e\u064e\u0644\u064e\u062a\u06e1 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650 \u0671\u0644\u0631\u0651\u064f\u0633\u064f\u0644\u064f\u06da \u0623\u064e\u0641\u064e\u0625\u0650\u064a\u0652\u0646 \u0645\u0651\u064e\u0627\u062a\u064e \u0623\u064e\u0648\u06e1 \u0642\u064f\u062a\u0650\u0644\u064e \u0671\u0646\u0642\u064e\u0644\u064e\u0628\u06e1\u062a\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0639\u06e1\u0642\u064e\u0670\u0628\u0650\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0646\u0642\u064e\u0644\u0650\u0628\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0639\u064e\u0642\u0650\u0628\u064e\u064a\u06e1\u0647\u0650 \u0641\u064e\u0644\u064e\u0646 \u064a\u064e\u0636\u064f\u0631\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627\u06da \u0648\u064e\u0633\u064e\u064a\u064e\u062c\u06e1\u0632\u0650\u064a \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0634\u0651\u064e\u0640\u0670\u0643\u0650\u0631\u0650\u064a\u0646\u064e",translation:"(Dan Muhammad hanyalah seorang Rasul; sebelumnya telah berlalu beberapa Rasul.148) Apakah jika dia wafat atau dibunuh, kamu berbalik ke belakang (murtad)? Barang siapa berbalik ke belakang, maka ia tidak akan merugikan Allah sedikit pun. Allah akan memberi balasan kepada orang yang bersyukur"},{id:145,text:"\u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0646\u064e\u0641\u06e1\u0633\u064d \u0623\u064e\u0646 \u062a\u064e\u0645\u064f\u0648\u062a\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0625\u0650\u0630\u06e1\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u0650\u062a\u064e\u0670\u0628\u0657\u0627 \u0645\u0651\u064f\u0624\u064e\u062c\u0651\u064e\u0644\u0657\u0627\u06d7 \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0631\u0650\u062f\u06e1 \u062b\u064e\u0648\u064e\u0627\u0628\u064e \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0646\u064f\u0624\u06e1\u062a\u0650\u0647\u0650\u06e6 \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0631\u0650\u062f\u06e1 \u062b\u064e\u0648\u064e\u0627\u0628\u064e \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0646\u064f\u0624\u06e1\u062a\u0650\u0647\u0650\u06e6 \u0645\u0650\u0646\u06e1\u0647\u064e\u0627\u06da \u0648\u064e\u0633\u064e\u0646\u064e\u062c\u06e1\u0632\u0650\u064a \u0671\u0644\u0634\u0651\u064e\u0640\u0670\u0643\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan setiap yang bernyawa tidak akan mati kecuali dengan izin Allah, sebagai ketetapan yang telah ditentukan waktunya. Barang siapa menghendaki pahala dunia, niscaya Kami berikan kepadanya pahala (dunia) itu, dan barang siapa menghendaki pahala akhirat, Kami berikan (pula) kepadanya pahala (akhirat) itu, dan Kami akan memberi balasan kepada orang-orang yang bersyukur"},{id:146,text:"\u0648\u064e\u0643\u064e\u0623\u064e\u064a\u0651\u0650\u0646 \u0645\u0651\u0650\u0646 \u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0656 \u0642\u064e\u0670\u062a\u064e\u0644\u064e \u0645\u064e\u0639\u064e\u0647\u064f\u06e5 \u0631\u0650\u0628\u0651\u0650\u064a\u0651\u064f\u0648\u0646\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u065e \u0641\u064e\u0645\u064e\u0627 \u0648\u064e\u0647\u064e\u0646\u064f\u0648\u0627\u0652 \u0644\u0650\u0645\u064e\u0627\u0653 \u0623\u064e\u0635\u064e\u0627\u0628\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u064e\u0627 \u0636\u064e\u0639\u064f\u0641\u064f\u0648\u0627\u0652 \u0648\u064e\u0645\u064e\u0627 \u0671\u0633\u06e1\u062a\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0628\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan betapa banyak nabi yang berperang didampingi sejumlah besar dari pengikut(nya) yang bertakwa. Mereka tidak (menjadi) lemah karena bencana yang menimpanya di jalan Allah, tidak patah semangat dan tidak (pula) menyerah (kepada musuh). Dan Allah mencitai orang-orang yang sabar"},{id:147,text:"\u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0642\u064e\u0648\u06e1\u0644\u064e\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0671\u063a\u06e1\u0641\u0650\u0631\u06e1 \u0644\u064e\u0646\u064e\u0627 \u0630\u064f\u0646\u064f\u0648\u0628\u064e\u0646\u064e\u0627 \u0648\u064e\u0625\u0650\u0633\u06e1\u0631\u064e\u0627\u0641\u064e\u0646\u064e\u0627 \u0641\u0650\u064a\u0653 \u0623\u064e\u0645\u06e1\u0631\u0650\u0646\u064e\u0627 \u0648\u064e\u062b\u064e\u0628\u0651\u0650\u062a\u06e1 \u0623\u064e\u0642\u06e1\u062f\u064e\u0627\u0645\u064e\u0646\u064e\u0627 \u0648\u064e\u0671\u0646\u0635\u064f\u0631\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan tidak lain ucapan mereka hanyalah doa, \"Ya Tuhan kami, ampunilah dosa-dosa kami dan tindakan-tindakan kami yang berlebihan (dalam) urusan kami149) dan tetapkanlah pendirian kami, dan tolonglah kami terhadap orang-orang kafir"},{id:148,text:"\u0641\u064e\u0640\u0654\u064e\u0627\u062a\u064e\u0649\u0670\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u062b\u064e\u0648\u064e\u0627\u0628\u064e \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0648\u064e\u062d\u064f\u0633\u06e1\u0646\u064e \u062b\u064e\u0648\u064e\u0627\u0628\u0650 \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0671\u0644\u06e1\u0645\u064f\u062d\u06e1\u0633\u0650\u0646\u0650\u064a\u0646\u064e",translation:"(Maka Allah memberi mereka pahala di dunia150) dan pahala yang baik di akhirat. Dan Allah mencintai orang-orang yang berbuat kebaikan"},{id:149,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646 \u062a\u064f\u0637\u0650\u064a\u0639\u064f\u0648\u0627\u0652 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u064a\u064e\u0631\u064f\u062f\u0651\u064f\u0648\u0643\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0639\u06e1\u0642\u064e\u0670\u0628\u0650\u0643\u064f\u0645\u06e1 \u0641\u064e\u062a\u064e\u0646\u0642\u064e\u0644\u0650\u0628\u064f\u0648\u0627\u0652 \u062e\u064e\u0670\u0633\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Wahai orang-orang yang beriman! Jika kamu menaati orang-orang yang kafir, niscaya mereka akan mengembalikan kamu ke belakang (murtad), maka kamu akan kembali menjadi orang yang rugi"},{id:150,text:"\u0628\u064e\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0648\u06e1\u0644\u064e\u0649\u0670\u0643\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u062e\u064e\u064a\u06e1\u0631\u064f \u0671\u0644\u0646\u0651\u064e\u0640\u0670\u0635\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Tetapi hanya Allahlah pelindungmu, dan Dia Penolong yang terbaik"},{id:151,text:"\u0633\u064e\u0646\u064f\u0644\u06e1\u0642\u0650\u064a \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0671\u0644\u0631\u0651\u064f\u0639\u06e1\u0628\u064e \u0628\u0650\u0645\u064e\u0627\u0653 \u0623\u064e\u0634\u06e1\u0631\u064e\u0643\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0645\u06e1 \u064a\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u06e1 \u0628\u0650\u0647\u0650\u06e6 \u0633\u064f\u0644\u06e1\u0637\u064e\u0670\u0646\u0657\u0627\u06d6 \u0648\u064e\u0645\u064e\u0623\u06e1\u0648\u064e\u0649\u0670\u0647\u064f\u0645\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u064f\u06d6 \u0648\u064e\u0628\u0650\u0626\u06e1\u0633\u064e \u0645\u064e\u062b\u06e1\u0648\u064e\u0649 \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Akan Kami masukkan rasa takut ke dalam hati orang-orang kafir, karena mereka mempersekutukan Allah dengan sesuatu yang Allah tidak menurunkan keterangan tentang itu. Dan tempat kembali mereka ialah neraka. Dan (itulah) seburuk-buruk tempat tinggal (bagi) orang-orang zalim"},{id:152,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0635\u064e\u062f\u064e\u0642\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0639\u06e1\u062f\u064e\u0647\u064f\u06e5\u0653 \u0625\u0650\u0630\u06e1 \u062a\u064e\u062d\u064f\u0633\u0651\u064f\u0648\u0646\u064e\u0647\u064f\u0645 \u0628\u0650\u0625\u0650\u0630\u06e1\u0646\u0650\u0647\u0650\u06e6\u06d6 \u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u064e\u0627 \u0641\u064e\u0634\u0650\u0644\u06e1\u062a\u064f\u0645\u06e1 \u0648\u064e\u062a\u064e\u0646\u064e\u0670\u0632\u064e\u0639\u06e1\u062a\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0631\u0650 \u0648\u064e\u0639\u064e\u0635\u064e\u064a\u06e1\u062a\u064f\u0645 \u0645\u0651\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0645\u064e\u0627\u0653 \u0623\u064e\u0631\u064e\u0649\u0670\u0643\u064f\u0645 \u0645\u0651\u064e\u0627 \u062a\u064f\u062d\u0650\u0628\u0651\u064f\u0648\u0646\u064e\u06da \u0645\u0650\u0646\u0643\u064f\u0645 \u0645\u0651\u064e\u0646 \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0648\u064e\u0645\u0650\u0646\u0643\u064f\u0645 \u0645\u0651\u064e\u0646 \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u064e\u06da \u062b\u064f\u0645\u0651\u064e \u0635\u064e\u0631\u064e\u0641\u064e\u0643\u064f\u0645\u06e1 \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0644\u0650\u064a\u064e\u0628\u06e1\u062a\u064e\u0644\u0650\u064a\u064e\u0643\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0639\u064e\u0641\u064e\u0627 \u0639\u064e\u0646\u0643\u064f\u0645\u06e1\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0630\u064f\u0648 \u0641\u064e\u0636\u06e1\u0644\u064d \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"(Dan sungguh, Allah telah memenuhi janji-Nya kepadamu, ketika kamu membunuh mereka dengan izin-Nya sampai pada saat kamu lemah dan berselisih dalam urusan itu151) dan mengabaikan perintah Rasul setelah Allah memperlihatkan kepadamu apa yang kamu sukai.152) Di antara kamu ada orang yang menghendaki dunia dan di antara kamu ada (pula) orang yang menghendaki akhirat. Kemudian Allah memalingkan kamu dari mereka153) untuk mengujimu, tetapi Dia benar-benar telah memaafkan kamu. Dan Allah mempunyai karunia (yang diberikan) kepada orang-orang mukmin"},{id:153,text:"\u06de\u0625\u0650\u0630\u06e1 \u062a\u064f\u0635\u06e1\u0639\u0650\u062f\u064f\u0648\u0646\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0644\u06e1\u0648\u064f\u06e5\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u062d\u064e\u062f\u0656 \u0648\u064e\u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064f \u064a\u064e\u062f\u06e1\u0639\u064f\u0648\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a\u0653 \u0623\u064f\u062e\u06e1\u0631\u064e\u0649\u0670\u0643\u064f\u0645\u06e1 \u0641\u064e\u0623\u064e\u062b\u064e\u0670\u0628\u064e\u0643\u064f\u0645\u06e1 \u063a\u064e\u0645\u0651\u064e\u06e2\u0627 \u0628\u0650\u063a\u064e\u0645\u0651\u0656 \u0644\u0651\u0650\u0643\u064e\u064a\u06e1\u0644\u064e\u0627 \u062a\u064e\u062d\u06e1\u0632\u064e\u0646\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0641\u064e\u0627\u062a\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u0645\u064e\u0627\u0653 \u0623\u064e\u0635\u064e\u0670\u0628\u064e\u0643\u064f\u0645\u06e1\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u062e\u064e\u0628\u0650\u064a\u0631\u064f\u06e2 \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"(Ingatlah) ketika kamu lari dan tidak menoleh kepada siapa pun, sedang Rasul (Muhammad) yang berada di antara (kawan-kawan)mu yang lain memanggil kamu (kelompok yang lari), karena itu Allah menimpakan kepadamu kesedihan demi kesedihan,154) agar kamu tidak bersedih hati (lagi) terhadap apa yang luput dari kamu dan terhadap apa yang menimpamu. Dan Allah Mahateliti atas apa yang kamu kerjakan"},{id:154,text:"\u062b\u064f\u0645\u0651\u064e \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0671\u0644\u06e1\u063a\u064e\u0645\u0651\u0650 \u0623\u064e\u0645\u064e\u0646\u064e\u0629\u0657 \u0646\u0651\u064f\u0639\u064e\u0627\u0633\u0657\u0627 \u064a\u064e\u063a\u06e1\u0634\u064e\u0649\u0670 \u0637\u064e\u0627\u0653\u0626\u0650\u0641\u064e\u0629\u0657 \u0645\u0651\u0650\u0646\u0643\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0637\u064e\u0627\u0653\u0626\u0650\u0641\u064e\u0629\u065e \u0642\u064e\u062f\u06e1 \u0623\u064e\u0647\u064e\u0645\u0651\u064e\u062a\u06e1\u0647\u064f\u0645\u06e1 \u0623\u064e\u0646\u0641\u064f\u0633\u064f\u0647\u064f\u0645\u06e1 \u064a\u064e\u0638\u064f\u0646\u0651\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u063a\u064e\u064a\u06e1\u0631\u064e \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0638\u064e\u0646\u0651\u064e \u0671\u0644\u06e1\u062c\u064e\u0670\u0647\u0650\u0644\u0650\u064a\u0651\u064e\u0629\u0650\u06d6 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0647\u064e\u0644 \u0644\u0651\u064e\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0631\u0650 \u0645\u0650\u0646 \u0634\u064e\u064a\u06e1\u0621\u0656\u06d7 \u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0631\u064e \u0643\u064f\u0644\u0651\u064e\u0647\u064f\u06e5 \u0644\u0650\u0644\u0651\u064e\u0647\u0650\u06d7 \u064a\u064f\u062e\u06e1\u0641\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0653 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645 \u0645\u0651\u064e\u0627 \u0644\u064e\u0627 \u064a\u064f\u0628\u06e1\u062f\u064f\u0648\u0646\u064e \u0644\u064e\u0643\u064e\u06d6 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0644\u064e\u0648\u06e1 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0631\u0650 \u0634\u064e\u064a\u06e1\u0621\u065e \u0645\u0651\u064e\u0627 \u0642\u064f\u062a\u0650\u0644\u06e1\u0646\u064e\u0627 \u0647\u064e\u0670\u0647\u064f\u0646\u064e\u0627\u06d7 \u0642\u064f\u0644 \u0644\u0651\u064e\u0648\u06e1 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0641\u0650\u064a \u0628\u064f\u064a\u064f\u0648\u062a\u0650\u0643\u064f\u0645\u06e1 \u0644\u064e\u0628\u064e\u0631\u064e\u0632\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064f\u062a\u0650\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u064f \u0671\u0644\u06e1\u0642\u064e\u062a\u06e1\u0644\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064e\u0636\u064e\u0627\u062c\u0650\u0639\u0650\u0647\u0650\u0645\u06e1\u06d6 \u0648\u064e\u0644\u0650\u064a\u064e\u0628\u06e1\u062a\u064e\u0644\u0650\u064a\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0635\u064f\u062f\u064f\u0648\u0631\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u0650\u064a\u064f\u0645\u064e\u062d\u0651\u0650\u0635\u064e \u0645\u064e\u0627 \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064f\u06e2 \u0628\u0650\u0630\u064e\u0627\u062a\u0650 \u0671\u0644\u0635\u0651\u064f\u062f\u064f\u0648\u0631\u0650",translation:"Kemudian setelah kamu ditimpa kesedihan, Dia menurunkan rasa aman kepadamu (berupa) kantuk yang meliputi segolongan dari kamu,155) sedangkan segolongan lagi156) telah dicemaskan oleh diri mereka sendiri; mereka menyangka yang tidak benar terhadap Allah seperti sangkaan jahiliah.157) Mereka berkata, \"Adakah sesuatu yang dapat kita perbuat dalam urusan ini?\" Katakanlah (Muhammad), \"Sesungguhnya segala urusan itu di tangan Allah.\" Mereka menyembunyikan dalam hatinya apa yang tidak mereka terangkan kepadamu. Mereka berkata, \"Sekiranya ada sesuatu yang dapat kita perbuat dalam urusan ini, niscaya kita tidak akan dibunuh (dikalahkan) di sini.\" Katakanlah (Muhammad), \"Meskipun kamu ada di rumahmu, niscaya orang-orang yang telah ditetapkan akan mati terbunuh itu keluar (juga) ke tempat mereka terbunuh.\" Allah (berbuat demikian) untuk menguji apa yang ada dalam dadamu dan untuk membersihkan apa yang ada dalam hatimu. Dan Allah Maha Mengetahui isi hati"},{id:155,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u06e1\u0627\u0652 \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u062a\u064e\u0642\u064e\u0649 \u0671\u0644\u06e1\u062c\u064e\u0645\u06e1\u0639\u064e\u0627\u0646\u0650 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0671\u0633\u06e1\u062a\u064e\u0632\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u064f \u0628\u0650\u0628\u064e\u0639\u06e1\u0636\u0650 \u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064f\u0648\u0627\u0652\u06d6 \u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0639\u064e\u0641\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1\u06d7 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u062d\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Sesungguhnya orang-orang yang berpaling di antara kamu ketika terjadi pertemuan (pertempuran) antara dua pasukan itu,158) sesungguhnya mereka digelincirkan oleh setan, disebabkan sebagian kesalahan (dosa) yang telah mereka perbuat (pada masa lampau), tetapi Allah benar-benar telah memaafkan mereka. Sungguh, Allah Maha Pengampun, Maha Penyantun"},{id:156,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u0643\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u0650\u0625\u0650\u062e\u06e1\u0648\u064e\u0670\u0646\u0650\u0647\u0650\u0645\u06e1 \u0625\u0650\u0630\u064e\u0627 \u0636\u064e\u0631\u064e\u0628\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0623\u064e\u0648\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u063a\u064f\u0632\u0651\u0657\u0649 \u0644\u0651\u064e\u0648\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0639\u0650\u0646\u062f\u064e\u0646\u064e\u0627 \u0645\u064e\u0627 \u0645\u064e\u0627\u062a\u064f\u0648\u0627\u0652 \u0648\u064e\u0645\u064e\u0627 \u0642\u064f\u062a\u0650\u0644\u064f\u0648\u0627\u0652 \u0644\u0650\u064a\u064e\u062c\u06e1\u0639\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062d\u064e\u0633\u06e1\u0631\u064e\u0629\u0657 \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u06e1\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064f\u062d\u06e1\u064a\u0650\u06e6 \u0648\u064e\u064a\u064f\u0645\u0650\u064a\u062a\u064f\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0628\u064e\u0635\u0650\u064a\u0631\u065e",translation:"Wahai orang-orang yang beriman! Janganlah kamu seperti orang-orang kafir yang mengatakan kepada saudara-saudaranya apabila mereka mengadakan perjalanan di bumi atau berperang, \"Sekiranya mereka tetap bersama kita, tentulah mereka tidak mati dan tidak terbunuh.\" (Dengan perkataan) yang demikian itu, karena Allah hendak menimbulkan rasa penyesalan di hati mereka. Allah menghidupkan dan mematikan, dan Allah Maha Melihat apa yang kamu kerjakan"},{id:157,text:"\u0648\u064e\u0644\u064e\u0626\u0650\u0646 \u0642\u064f\u062a\u0650\u0644\u06e1\u062a\u064f\u0645\u06e1 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0648\u06e1 \u0645\u064f\u062a\u0651\u064f\u0645\u06e1 \u0644\u064e\u0645\u064e\u063a\u06e1\u0641\u0650\u0631\u064e\u0629\u065e \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u064c \u062e\u064e\u064a\u06e1\u0631\u065e \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u062c\u06e1\u0645\u064e\u0639\u064f\u0648\u0646\u064e",translation:"(Dan sungguh, sekiranya kamu gugur di jalan Allah atau mati,159) sungguh, pastilah ampunan Allah dan rahmat-Nya lebih baik (bagimu) daripada apa (harta rampasan) yang mereka kumpulkan"},{id:158,text:"\u0648\u064e\u0644\u064e\u0626\u0650\u0646 \u0645\u0651\u064f\u062a\u0651\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1 \u0642\u064f\u062a\u0650\u0644\u06e1\u062a\u064f\u0645\u06e1 \u0644\u064e\u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064f\u062d\u06e1\u0634\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan sungguh, sekiranya kamu mati atau gugur, pastilah kepada Allah kamu dikumpulkan"},{id:159,text:"\u0641\u064e\u0628\u0650\u0645\u064e\u0627 \u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u0656 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u0650\u0646\u062a\u064e \u0644\u064e\u0647\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0644\u064e\u0648\u06e1 \u0643\u064f\u0646\u062a\u064e \u0641\u064e\u0638\u0651\u064b\u0627 \u063a\u064e\u0644\u0650\u064a\u0638\u064e \u0671\u0644\u06e1\u0642\u064e\u0644\u06e1\u0628\u0650 \u0644\u064e\u0671\u0646\u0641\u064e\u0636\u0651\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1 \u062d\u064e\u0648\u06e1\u0644\u0650\u0643\u064e\u06d6 \u0641\u064e\u0671\u0639\u06e1\u0641\u064f \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0648\u064e\u0671\u0633\u06e1\u062a\u064e\u063a\u06e1\u0641\u0650\u0631\u06e1 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0634\u064e\u0627\u0648\u0650\u0631\u06e1\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0631\u0650\u06d6 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0639\u064e\u0632\u064e\u0645\u06e1\u062a\u064e \u0641\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u06e1 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0671\u0644\u06e1\u0645\u064f\u062a\u064e\u0648\u064e\u0643\u0651\u0650\u0644\u0650\u064a\u0646\u064e",translation:"Maka berkat rahmat Allah engkau (Muhammad) berlaku lemah lembut terhadap mereka. Sekiranya engkau bersikap keras dan berhati kasar, tentulah mereka menjauhkan diri dari sekitarmu. Karena itu maafkanlah mereka dan mohonkanlah ampunan untuk mereka, dan bermusyawarahlah dengan mereka dalam urusan itu.160) Kemudian, apabila engkau telah membulatkan tekad, maka bertawakallah kepada Allah. Sungguh, Allah mencintai orang yang bertawakal"},{id:160,text:"\u0625\u0650\u0646 \u064a\u064e\u0646\u0635\u064f\u0631\u06e1\u0643\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0644\u064e\u0627 \u063a\u064e\u0627\u0644\u0650\u0628\u064e \u0644\u064e\u0643\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0625\u0650\u0646 \u064a\u064e\u062e\u06e1\u0630\u064f\u0644\u06e1\u0643\u064f\u0645\u06e1 \u0641\u064e\u0645\u064e\u0646 \u0630\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064e\u0646\u0635\u064f\u0631\u064f\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u0647\u0650\u06e6\u06d7 \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0644\u06e1\u064a\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u0650 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Jika Allah menolong kamu, maka tidak ada yang dapat mengalahkanmu, tetapi jika Allah membiarkan kamu (tidak memberi pertolongan), maka siapa yang dapat menolongmu setelah itu? Karena itu, hendaklah kepada Allah saja orang-orang mukmin bertawakal"},{id:161,text:"\u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0646\u064e\u0628\u0650\u064a\u0651\u064d \u0623\u064e\u0646 \u064a\u064e\u063a\u064f\u0644\u0651\u064e\u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u063a\u06e1\u0644\u064f\u0644\u06e1 \u064a\u064e\u0623\u06e1\u062a\u0650 \u0628\u0650\u0645\u064e\u0627 \u063a\u064e\u0644\u0651\u064e \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650\u06da \u062b\u064f\u0645\u0651\u064e \u062a\u064f\u0648\u064e\u0641\u0651\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u064f \u0646\u064e\u0641\u06e1\u0633\u0656 \u0645\u0651\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064e\u062a\u06e1 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064f\u0638\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan tidak mungkin seorang Nabi berkhianat (dalam urusan harta rampasan perang). Barang siapa berkhianat, niscaya pada hari Kiamat dia akan datang membawa apa yang dikhianatkannya. Kemudian setiap orang akan diberi balasan yang sempurna sesuai dengan apa yang dilakukannya, dan mereka tidak dizalimi"},{id:162,text:"\u0623\u064e\u0641\u064e\u0645\u064e\u0646\u0650 \u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064e \u0631\u0650\u0636\u06e1\u0648\u064e\u0670\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u0645\u064e\u0646\u06e2 \u0628\u064e\u0627\u0653\u0621\u064e \u0628\u0650\u0633\u064e\u062e\u064e\u0637\u0656 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u064e\u0623\u06e1\u0648\u064e\u0649\u0670\u0647\u064f \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064f\u06d6 \u0648\u064e\u0628\u0650\u0626\u06e1\u0633\u064e \u0671\u0644\u06e1\u0645\u064e\u0635\u0650\u064a\u0631\u064f",translation:"Maka adakah orang yang mengikuti keridaan Allah sama dengan orang yang kembali membawa kemurkaan dari Allah dan tempatnya di neraka Jahanam? Itulah seburuk-buruk tempat kembali"},{id:163,text:"\u0647\u064f\u0645\u06e1 \u062f\u064e\u0631\u064e\u062c\u064e\u0670\u062a\u064c \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u064e\u0635\u0650\u064a\u0631\u064f\u06e2 \u0628\u0650\u0645\u064e\u0627 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"(Kedudukan) mereka itu bertingkat-tingkat di sisi Allah, dan Allah Maha Melihat apa yang mereka kerjakan"},{id:164,text:"\u0644\u064e\u0642\u064e\u062f\u06e1 \u0645\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0625\u0650\u0630\u06e1 \u0628\u064e\u0639\u064e\u062b\u064e \u0641\u0650\u064a\u0647\u0650\u0645\u06e1 \u0631\u064e\u0633\u064f\u0648\u0644\u0657\u0627 \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u06e1 \u064a\u064e\u062a\u06e1\u0644\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0647\u0650\u06e6 \u0648\u064e\u064a\u064f\u0632\u064e\u0643\u0651\u0650\u064a\u0647\u0650\u0645\u06e1 \u0648\u064e\u064a\u064f\u0639\u064e\u0644\u0651\u0650\u0645\u064f\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0648\u064e\u0671\u0644\u06e1\u062d\u0650\u0643\u06e1\u0645\u064e\u0629\u064e \u0648\u064e\u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f \u0644\u064e\u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0670\u0644\u0656 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u064d",translation:"Sungguh, Allah telah memberi karunia kepada orang-orang beriman ketika (Allah) mengutus seorang Rasul (Muhammad) di tengah-tengah mereka dari kalangan mereka sendiri, yang membacakan kepada mereka ayat-ayat-Nya, menyucikan (jiwa) mereka, dan mengajarkan kepada mereka Kitab (Alquran) dan Hikmah (Sunah), meskipun sebelumnya, mereka benar-benar dalam kesesatan yang nyata"},{id:165,text:"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u0635\u064e\u0670\u0628\u064e\u062a\u06e1\u0643\u064f\u0645 \u0645\u0651\u064f\u0635\u0650\u064a\u0628\u064e\u0629\u065e \u0642\u064e\u062f\u06e1 \u0623\u064e\u0635\u064e\u0628\u06e1\u062a\u064f\u0645 \u0645\u0651\u0650\u062b\u06e1\u0644\u064e\u064a\u06e1\u0647\u064e\u0627 \u0642\u064f\u0644\u06e1\u062a\u064f\u0645\u06e1 \u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u0647\u064e\u0670\u0630\u064e\u0627\u06d6 \u0642\u064f\u0644\u06e1 \u0647\u064f\u0648\u064e \u0645\u0650\u0646\u06e1 \u0639\u0650\u0646\u062f\u0650 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u06e1\u06d7 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0642\u064e\u062f\u0650\u064a\u0631\u065e",translation:"Dan mengapa kamu (heran) ketika ditimpa musibah (kekalahan pada Perang Uhud), padahal kamu telah menimpakan musibah dua kali lipat (kepada musuh-musuhmu pada Perang Badar) kamu berkata, \"Dari mana datangnya (kekalahan) ini?\" Katakanlah, \"Itu dari (kesalahan) dirimu sendiri.\" Sungguh, Allah Mahakuasa atas segala sesuatu"},{id:166,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0635\u064e\u0670\u0628\u064e\u0643\u064f\u0645\u06e1 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u062a\u064e\u0642\u064e\u0649 \u0671\u0644\u06e1\u062c\u064e\u0645\u06e1\u0639\u064e\u0627\u0646\u0650 \u0641\u064e\u0628\u0650\u0625\u0650\u0630\u06e1\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u0650\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064e \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dan apa yang menimpa kamu ketika terjadi pertemuan (pertempuran) antara dua pasukan itu adalah dengan izin Allah, dan agar Allah menguji siapa orang (yang benar-benar) beriman"},{id:167,text:"\u0648\u064e\u0644\u0650\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0646\u064e\u0627\u0641\u064e\u0642\u064f\u0648\u0627\u0652\u06da \u0648\u064e\u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0648\u06e1\u0627\u0652 \u0642\u064e\u0670\u062a\u0650\u0644\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0648\u0650 \u0671\u062f\u06e1\u0641\u064e\u0639\u064f\u0648\u0627\u0652\u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0648\u06e1 \u0646\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0642\u0650\u062a\u064e\u0627\u0644\u0657\u0627 \u0644\u0651\u064e\u0671\u062a\u0651\u064e\u0628\u064e\u0639\u06e1\u0646\u064e\u0670\u0643\u064f\u0645\u06e1\u06d7 \u0647\u064f\u0645\u06e1 \u0644\u0650\u0644\u06e1\u0643\u064f\u0641\u06e1\u0631\u0650 \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u064d \u0623\u064e\u0642\u06e1\u0631\u064e\u0628\u064f \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0644\u0650\u0644\u06e1\u0625\u0650\u064a\u0645\u064e\u0670\u0646\u0650\u06da \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0628\u0650\u0623\u064e\u0641\u06e1\u0648\u064e\u0670\u0647\u0650\u0647\u0650\u0645 \u0645\u0651\u064e\u0627 \u0644\u064e\u064a\u06e1\u0633\u064e \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u06e1\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u064a\u064e\u0643\u06e1\u062a\u064f\u0645\u064f\u0648\u0646\u064e",translation:"dan untuk menguji orang-orang yang munafik, kepada mereka dikatakan,\"Marilah berperang di jalan Allah atau pertahankanlah (dirimu).\" Mereka berkata, \"Sekiranya kami mengetahui (bagaimana cara) berperang, tentulah kami mengikuti kamu.\"161) Mereka pada hari itu lebih dekat kepada kekafiran dari pada keimanan. Mereka mengatakan dengan mulutnya apa yang tidak sesuai dengan isi hatinya. Dan Allah lebih mengetahui apa yang mereka sembunyikan"},{id:168,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u0650\u0625\u0650\u062e\u06e1\u0648\u064e\u0670\u0646\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0642\u064e\u0639\u064e\u062f\u064f\u0648\u0627\u0652 \u0644\u064e\u0648\u06e1 \u0623\u064e\u0637\u064e\u0627\u0639\u064f\u0648\u0646\u064e\u0627 \u0645\u064e\u0627 \u0642\u064f\u062a\u0650\u0644\u064f\u0648\u0627\u0652\u06d7 \u0642\u064f\u0644\u06e1 \u0641\u064e\u0671\u062f\u06e1\u0631\u064e\u0621\u064f\u0648\u0627\u0652 \u0639\u064e\u0646\u06e1 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u064e \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0635\u064e\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e",translation:"(Mereka itu adalah) orang-orang yang berkata kepada saudara-saudaranya dan mereka tidak turut pergi berperang, \"Sekiranya mereka mengikuti kita, tentulah mereka tidak terbunuh.\" Katakanlah, \"Cegahlah kematian itu dari dirimu, jika kamu orang yang benar"},{id:169,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062d\u06e1\u0633\u064e\u0628\u064e\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0642\u064f\u062a\u0650\u0644\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u062a\u064e\u06e2\u0627\u06da \u0628\u064e\u0644\u06e1 \u0623\u064e\u062d\u06e1\u064a\u064e\u0627\u0653\u0621\u064c \u0639\u0650\u0646\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u064a\u064f\u0631\u06e1\u0632\u064e\u0642\u064f\u0648\u0646\u064e",translation:"Dan jangan sekali-kali kamu mengira bahwa orang-orang yang gugur di jalan Allah itu mati; sebenarnya mereka itu hidup, di sisi Tuhannya mendapat rezeki"},{id:170,text:"\u0641\u064e\u0631\u0650\u062d\u0650\u064a\u0646\u064e \u0628\u0650\u0645\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u064e\u0649\u0670\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646 \u0641\u064e\u0636\u06e1\u0644\u0650\u0647\u0650\u06e6 \u0648\u064e\u064a\u064e\u0633\u06e1\u062a\u064e\u0628\u06e1\u0634\u0650\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0645\u06e1 \u064a\u064e\u0644\u06e1\u062d\u064e\u0642\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u0645 \u0645\u0651\u0650\u0646\u06e1 \u062e\u064e\u0644\u06e1\u0641\u0650\u0647\u0650\u0645\u06e1 \u0623\u064e\u0644\u0651\u064e\u0627 \u062e\u064e\u0648\u06e1\u0641\u064c \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u06e1 \u064a\u064e\u062d\u06e1\u0632\u064e\u0646\u064f\u0648\u0646\u064e",translation:"(mereka bergembira dengan karunia yang diberikan Allah kepadanya, dan senang hati terhadap orang yang masih tinggal di belakang yang belum menyusul mereka,163) bahwa tidak ada rasa takut pada mereka dan mereka tidak bersedih hati"},{id:171,text:"\u06de\u064a\u064e\u0633\u06e1\u062a\u064e\u0628\u06e1\u0634\u0650\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0646\u0650\u0639\u06e1\u0645\u064e\u0629\u0656 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0641\u064e\u0636\u06e1\u0644\u0656 \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064f\u0636\u0650\u064a\u0639\u064f \u0623\u064e\u062c\u06e1\u0631\u064e \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Mereka bergembira ria dengan nikmat dan karunia dari Allah. Dan sungguh, Allah tidak menyia-nyiakan pahala orang-orang yang beriman"},{id:172,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u0633\u06e1\u062a\u064e\u062c\u064e\u0627\u0628\u064f\u0648\u0627\u0652 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0650 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0645\u064e\u0627\u0653 \u0623\u064e\u0635\u064e\u0627\u0628\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0642\u064e\u0631\u06e1\u062d\u064f\u06da \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064e\u0648\u06e1\u0627\u0652 \u0623\u064e\u062c\u06e1\u0631\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u064c",translation:"(yaitu) orang-orang yang menaati (perintah) Allah dan Rasul setelah mereka mendapat luka (dalam Perang Uhud). Orang-orang yang berbuat kebajikan dan bertakwa di antara mereka mendapat pahala yang besar"},{id:173,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0642\u064e\u062f\u06e1 \u062c\u064e\u0645\u064e\u0639\u064f\u0648\u0627\u0652 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0641\u064e\u0671\u062e\u06e1\u0634\u064e\u0648\u06e1\u0647\u064f\u0645\u06e1 \u0641\u064e\u0632\u064e\u0627\u062f\u064e\u0647\u064f\u0645\u06e1 \u0625\u0650\u064a\u0645\u064e\u0670\u0646\u0657\u0627 \u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u062d\u064e\u0633\u06e1\u0628\u064f\u0646\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0646\u0650\u0639\u06e1\u0645\u064e \u0671\u0644\u06e1\u0648\u064e\u0643\u0650\u064a\u0644\u064f",translation:"(Yaitu) orang-orang (yang menaati Allah dan Rasul) yang ketika ada orang-orang mengatakan kepadanya, \"Orang-orang (Quraisy) telah mengumpulkan pasukan untuk menyerang kamu, karena itu takutlah kepada mereka,\" ternyata (ucapan) itu menambah (kuat) iman mereka dan mereka menjawab, \"Cukuplah Allah (menjadi penolong) bagi kami dan Dia sebaik-baik pelindung"},{id:174,text:"\u0641\u064e\u0671\u0646\u0642\u064e\u0644\u064e\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0646\u0650\u0639\u06e1\u0645\u064e\u0629\u0656 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0641\u064e\u0636\u06e1\u0644\u0656 \u0644\u0651\u064e\u0645\u06e1 \u064a\u064e\u0645\u06e1\u0633\u064e\u0633\u06e1\u0647\u064f\u0645\u06e1 \u0633\u064f\u0648\u0653\u0621\u065e \u0648\u064e\u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0627\u0652 \u0631\u0650\u0636\u06e1\u0648\u064e\u0670\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0630\u064f\u0648 \u0641\u064e\u0636\u06e1\u0644\u064d \u0639\u064e\u0638\u0650\u064a\u0645\u064d",translation:"Maka mereka kembali dengan nikmat dan karunia (yang besar) dari Allah, mereka tidak ditimpa suatu bencana dan mereka mengikuti keridaan Allah. Allah mempunyai karunia yang besar"},{id:175,text:"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u064f \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u064f \u064a\u064f\u062e\u064e\u0648\u0651\u0650\u0641\u064f \u0623\u064e\u0648\u06e1\u0644\u0650\u064a\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u06e5 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062e\u064e\u0627\u0641\u064f\u0648\u0647\u064f\u0645\u06e1 \u0648\u064e\u062e\u064e\u0627\u0641\u064f\u0648\u0646\u0650 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645 \u0645\u0651\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Sesungguhnya mereka hanyalah setan yang menakut-nakuti (kamu) dengan teman-teman setianya, karena itu janganlah kamu takut kepada mereka, tetapi takutlah kepada-Ku, jika kamu orang-orang beriman"},{id:176,text:"\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062d\u06e1\u0632\u064f\u0646\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0633\u064e\u0670\u0631\u0650\u0639\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0643\u064f\u0641\u06e1\u0631\u0650\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0646 \u064a\u064e\u0636\u064f\u0631\u0651\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627\u06da \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0644\u0651\u064e\u0627 \u064a\u064e\u062c\u06e1\u0639\u064e\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u062d\u064e\u0638\u0651\u0657\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650\u06d6 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u064c",translation:"Dan janganlah engkau (Muhammad) dirisaukan oleh orang-orang yang dengan mudah kembali menjadi kafir;164) sesungguhnya sedikit pun mereka tidak merugikan Allah. Allah tidak akan memberi bagian (pahala) kepada mereka di akhirat, dan mereka akan mendapat azab yang besar"},{id:177,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u0634\u06e1\u062a\u064e\u0631\u064e\u0648\u064f\u0627\u0652 \u0671\u0644\u06e1\u0643\u064f\u0641\u06e1\u0631\u064e \u0628\u0650\u0671\u0644\u06e1\u0625\u0650\u064a\u0645\u064e\u0670\u0646\u0650 \u0644\u064e\u0646 \u064a\u064e\u0636\u064f\u0631\u0651\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627\u06d6 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Sesungguhnya orang-orang yang membeli kekafiran dengan iman, sedikit pun tidak merugikan Allah; dan mereka akan mendapat azab yang pedih"},{id:178,text:"\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062d\u06e1\u0633\u064e\u0628\u064e\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u0646\u064f\u0645\u06e1\u0644\u0650\u064a \u0644\u064e\u0647\u064f\u0645\u06e1 \u062e\u064e\u064a\u06e1\u0631\u065e \u0644\u0651\u0650\u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0646\u064f\u0645\u06e1\u0644\u0650\u064a \u0644\u064e\u0647\u064f\u0645\u06e1 \u0644\u0650\u064a\u064e\u0632\u06e1\u062f\u064e\u0627\u062f\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u062b\u06e1\u0645\u0657\u0627\u06d6 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u065e \u0645\u0651\u064f\u0647\u0650\u064a\u0646\u065e",translation:"(Dan jangan sekali-kali orang-orang kafir itu mengira bahwa tenggang waktu yang Kami berikan kepada mereka165) lebih baik baginya. Sesungguhnya tenggang waktu yang Kami berikan kepada mereka hanyalah agar dosa mereka semakin bertambah; dan mereka akan mendapat azab yang menghinakan"},{id:179,text:"\u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u064a\u064e\u0630\u064e\u0631\u064e \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0645\u0650\u064a\u0632\u064e \u0671\u0644\u06e1\u062e\u064e\u0628\u0650\u064a\u062b\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0637\u0651\u064e\u064a\u0651\u0650\u0628\u0650\u06d7 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u064a\u064f\u0637\u06e1\u0644\u0650\u0639\u064e\u0643\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u0628\u0650 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u062c\u06e1\u062a\u064e\u0628\u0650\u064a \u0645\u0650\u0646 \u0631\u0651\u064f\u0633\u064f\u0644\u0650\u0647\u0650\u06e6 \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06d6 \u0641\u064e\u0640\u0654\u064e\u0627\u0645\u0650\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064f\u0633\u064f\u0644\u0650\u0647\u0650\u06e6\u06da \u0648\u064e\u0625\u0650\u0646 \u062a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0641\u064e\u0644\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u062c\u06e1\u0631\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u065e",translation:"(Allah tidak akan membiarkan orang-orang yang beriman sebagaimana dalam keadaan kamu sekarang ini,166) sehingga Dia membedakan yang buruk dari yang baik. Allah tidak akan memperlihatkan kepadamu hal-hal yang gaib, tetapi Allah memilih siapa yang Dia kehendaki di antara Rasul-rasul-Nya.167) Karena itu, berimanlah kepada Allah dan Rasul-rasul-Nya. Jika kamu beriman dan bertakwa, maka kamu akan mendapat pahala yang besar"},{id:180,text:"\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062d\u06e1\u0633\u064e\u0628\u064e\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0628\u06e1\u062e\u064e\u0644\u064f\u0648\u0646\u064e \u0628\u0650\u0645\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u064e\u0649\u0670\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646 \u0641\u064e\u0636\u06e1\u0644\u0650\u0647\u0650\u06e6 \u0647\u064f\u0648\u064e \u062e\u064e\u064a\u06e1\u0631\u0657\u0627 \u0644\u0651\u064e\u0647\u064f\u0645\u06d6 \u0628\u064e\u0644\u06e1 \u0647\u064f\u0648\u064e \u0634\u064e\u0631\u0651\u065e \u0644\u0651\u064e\u0647\u064f\u0645\u06e1\u06d6 \u0633\u064e\u064a\u064f\u0637\u064e\u0648\u0651\u064e\u0642\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u0628\u064e\u062e\u0650\u0644\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650\u06d7 \u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u064a\u0631\u064e\u0670\u062b\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u062e\u064e\u0628\u0650\u064a\u0631\u065e",translation:"Dan jangan sekali-kali orang-orang yang kikir dengan apa yang diberikan Allah kepada mereka dari karunia-Nya, mengira bahwa (kikir) itu baik bagi mereka, padahal (kikir) itu buruk bagi mereka. Apa (harta) yang mereka kikirkan itu akan dikalungkan (di lehernya) pada hari Kiamat. Milik Allahlah warisan (apa yang ada) di langit dan di bumi. Allah Mahateliti terhadap apa yang kamu kerjakan"},{id:181,text:"\u0644\u0651\u064e\u0642\u064e\u062f\u06e1 \u0633\u064e\u0645\u0650\u0639\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0642\u064e\u0648\u06e1\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0641\u064e\u0642\u0650\u064a\u0631\u065e \u0648\u064e\u0646\u064e\u062d\u06e1\u0646\u064f \u0623\u064e\u063a\u06e1\u0646\u0650\u064a\u064e\u0627\u0653\u0621\u064f\u06d8 \u0633\u064e\u0646\u064e\u0643\u06e1\u062a\u064f\u0628\u064f \u0645\u064e\u0627 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0648\u064e\u0642\u064e\u062a\u06e1\u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u0646\u06e2\u0628\u0650\u064a\u064e\u0627\u0653\u0621\u064e \u0628\u0650\u063a\u064e\u064a\u06e1\u0631\u0650 \u062d\u064e\u0642\u0651\u0656 \u0648\u064e\u0646\u064e\u0642\u064f\u0648\u0644\u064f \u0630\u064f\u0648\u0642\u064f\u0648\u0627\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0671\u0644\u06e1\u062d\u064e\u0631\u0650\u064a\u0642\u0650",translation:"Sungguh, Allah telah mendengar perkataan orang-orang (Yahudi) yang mengatakan, \"Sesungguhnya Allah itu miskin dan kami kaya.\" Kami akan mencatat perkataan mereka dan perbuatan mereka membunuh Nabi-nabi tanpa hak (alasan yang benar), dan Kami akan mengatakan (kepada mereka), \"Rasakanlah olehmu azab yang membakar"},{id:182,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0645\u064e\u0627 \u0642\u064e\u062f\u0651\u064e\u0645\u064e\u062a\u06e1 \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u064a\u06e1\u0633\u064e \u0628\u0650\u0638\u064e\u0644\u0651\u064e\u0627\u0645\u0656 \u0644\u0651\u0650\u0644\u06e1\u0639\u064e\u0628\u0650\u064a\u062f\u0650",translation:"Demikian itu disebabkan oleh perbuatan tanganmu sendiri, dan sesungguhnya Allah tidak menzalimi hamba-hamba-Nya"},{id:183,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0647\u0650\u062f\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0646\u064e\u0627\u0653 \u0623\u064e\u0644\u0651\u064e\u0627 \u0646\u064f\u0624\u06e1\u0645\u0650\u0646\u064e \u0644\u0650\u0631\u064e\u0633\u064f\u0648\u0644\u064d \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e\u0646\u064e\u0627 \u0628\u0650\u0642\u064f\u0631\u06e1\u0628\u064e\u0627\u0646\u0656 \u062a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f\u0647\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u064f\u06d7 \u0642\u064f\u0644\u06e1 \u0642\u064e\u062f\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u06e1 \u0631\u064f\u0633\u064f\u0644\u065e \u0645\u0651\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u064a \u0628\u0650\u0671\u0644\u06e1\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0650 \u0648\u064e\u0628\u0650\u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0642\u064f\u0644\u06e1\u062a\u064f\u0645\u06e1 \u0641\u064e\u0644\u0650\u0645\u064e \u0642\u064e\u062a\u064e\u0644\u06e1\u062a\u064f\u0645\u064f\u0648\u0647\u064f\u0645\u06e1 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0635\u064e\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e",translation:"(Yaitu) orang-orang (Yahudi) yang mengatakan, \"Sesungguhnya Allah telah memerintahkan kepada kami, agar kami tidak beriman kepada seorang rasul, sebelum dia mendatangkan kepada kami kurban yang dimakan api.\" Katakanlah (Muhammad), \"Sungguh, beberapa orang Rasul sebelumku telah datang kepadamu, (dengan) membawa bukti-bukti yang nyata dan membawa apa yang kamu sebutkan, tetapi mengapa kamu membunuhnya jika kamu orang-orang yang benar"},{id:184,text:"\u0641\u064e\u0625\u0650\u0646 \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0643\u064e \u0641\u064e\u0642\u064e\u062f\u06e1 \u0643\u064f\u0630\u0651\u0650\u0628\u064e \u0631\u064f\u0633\u064f\u0644\u065e \u0645\u0651\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064e \u062c\u064e\u0627\u0653\u0621\u064f\u0648 \u0628\u0650\u0671\u0644\u06e1\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u0632\u0651\u064f\u0628\u064f\u0631\u0650 \u0648\u064e\u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0671\u0644\u06e1\u0645\u064f\u0646\u0650\u064a\u0631\u0650",translation:"Maka jika mereka mendustakan engkau (Muhammad), maka (ketahuilah) Rasul-rasul sebelum engkau pun telah didustakan (pula), mereka membawa mukjizat-mukjizat yang nyata, Zubur168) dan Kitab yang memberi penjelasan yang sempurna"},{id:185,text:"\u0643\u064f\u0644\u0651\u064f \u0646\u064e\u0641\u06e1\u0633\u0656 \u0630\u064e\u0627\u0653\u0626\u0650\u0642\u064e\u0629\u064f \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u0650\u06d7 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u062a\u064f\u0648\u064e\u0641\u0651\u064e\u0648\u06e1\u0646\u064e \u0623\u064f\u062c\u064f\u0648\u0631\u064e\u0643\u064f\u0645\u06e1 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650\u06d6 \u0641\u064e\u0645\u064e\u0646 \u0632\u064f\u062d\u06e1\u0632\u0650\u062d\u064e \u0639\u064e\u0646\u0650 \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0648\u064e\u0623\u064f\u062f\u06e1\u062e\u0650\u0644\u064e \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u064e \u0641\u064e\u0642\u064e\u062f\u06e1 \u0641\u064e\u0627\u0632\u064e\u06d7 \u0648\u064e\u0645\u064e\u0627 \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u064f \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u062a\u064e\u0670\u0639\u064f \u0671\u0644\u06e1\u063a\u064f\u0631\u064f\u0648\u0631\u0650",translation:"Setiap yang bernyawa akan merasakan mati. Dan hanya pada hari Kiamat sajalah diberikan dengan sempurna balasanmu. Barang siapa dijauhkan dari neraka dan dimasukkan ke dalam surga, sungguh, dia memperoleh kemenangan. Kehidupan dunia hanyalah kesenangan yang memperdaya"},{id:186,text:"\u06de\u0644\u064e\u062a\u064f\u0628\u06e1\u0644\u064e\u0648\u064f\u0646\u0651\u064e \u0641\u0650\u064a\u0653 \u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u062a\u064e\u0633\u06e1\u0645\u064e\u0639\u064f\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u0634\u06e1\u0631\u064e\u0643\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0630\u0657\u0649 \u0643\u064e\u062b\u0650\u064a\u0631\u0657\u0627\u06da \u0648\u064e\u0625\u0650\u0646 \u062a\u064e\u0635\u06e1\u0628\u0650\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u0650\u0646\u06e1 \u0639\u064e\u0632\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0623\u064f\u0645\u064f\u0648\u0631\u0650",translation:"Kamu pasti akan diuji dengan hartamu dan dirimu. Dan pasti kamu akan mendengar banyak hal yang sangat menyakitkan hati dari orang-orang yang diberi Kitab sebelum kamu dan dari orang-orang musyrik. Jika kamu bersabar dan bertakwa, maka sesungguhnya yang demikian itu termasuk urusan yang (patut) diutamakan"},{id:187,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0623\u064e\u062e\u064e\u0630\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u064a\u062b\u064e\u0670\u0642\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0644\u064e\u062a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064f\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u06e1\u062a\u064f\u0645\u064f\u0648\u0646\u064e\u0647\u064f\u06e5 \u0641\u064e\u0646\u064e\u0628\u064e\u0630\u064f\u0648\u0647\u064f \u0648\u064e\u0631\u064e\u0627\u0653\u0621\u064e \u0638\u064f\u0647\u064f\u0648\u0631\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0671\u0634\u06e1\u062a\u064e\u0631\u064e\u0648\u06e1\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6 \u062b\u064e\u0645\u064e\u0646\u0657\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u0657\u0627\u06d6 \u0641\u064e\u0628\u0650\u0626\u06e1\u0633\u064e \u0645\u064e\u0627 \u064a\u064e\u0634\u06e1\u062a\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan (ingatlah), ketika Allah mengambil janji dari orang-orang yang telah diberi Kitab (yaitu), \"Hendaklah kamu benar-benar menerangkannya (isi Kitab itu) kepada manusia, dan janganlah kamu menyembunyikannya,\"170) lalu mereka melemparkan (janji itu) ke belakang punggung mereka dan menjualnya dengan harga murah. Maka itulah seburuk-buruk jual-beli yang mereka lakukan"},{id:188,text:"\u0644\u064e\u0627 \u062a\u064e\u062d\u06e1\u0633\u064e\u0628\u064e\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0641\u06e1\u0631\u064e\u062d\u064f\u0648\u0646\u064e \u0628\u0650\u0645\u064e\u0627\u0653 \u0623\u064e\u062a\u064e\u0648\u0627\u0652 \u0648\u0651\u064e\u064a\u064f\u062d\u0650\u0628\u0651\u064f\u0648\u0646\u064e \u0623\u064e\u0646 \u064a\u064f\u062d\u06e1\u0645\u064e\u062f\u064f\u0648\u0627\u0652 \u0628\u0650\u0645\u064e\u0627 \u0644\u064e\u0645\u06e1 \u064a\u064e\u0641\u06e1\u0639\u064e\u0644\u064f\u0648\u0627\u0652 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062d\u06e1\u0633\u064e\u0628\u064e\u0646\u0651\u064e\u0647\u064f\u0645 \u0628\u0650\u0645\u064e\u0641\u064e\u0627\u0632\u064e\u0629\u0656 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u0650\u06d6 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Jangan sekali-kali kamu mengira bahwa orang yang gembira dengan apa yang telah mereka kerjakan dan mereka suka dipuji atas perbuatan yang tidak mereka lakukan, jangan sekali-kali kamu mengira bahwa mereka akan lolos dari azab. Mereka akan mendapat azab yang pedih"},{id:189,text:"\u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064f\u0644\u06e1\u0643\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0642\u064e\u062f\u0650\u064a\u0631\u064c",translation:"Dan milik Allahlah kerajaan langit dan bumi; dan Allah Mahakuasa atas segala sesuatu"},{id:190,text:"\u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u062e\u064e\u0644\u06e1\u0642\u0650 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0671\u062e\u06e1\u062a\u0650\u0644\u064e\u0670\u0641\u0650 \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u0650 \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u0644\u064e\u0623\u0653\u064a\u064e\u0670\u062a\u0656 \u0644\u0651\u0650\u0623\u064f\u0648\u0652\u0644\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0644\u06e1\u0628\u064e\u0670\u0628\u0650",translation:"Sesungguhnya dalam penciptaan langit dan bumi, dan pergantian malam dan siang terdapat tanda-tanda (kebesaran Allah) bagi orang yang berakal"},{id:191,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0630\u06e1\u0643\u064f\u0631\u064f\u0648\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0642\u0650\u064a\u064e\u0670\u0645\u0657\u0627 \u0648\u064e\u0642\u064f\u0639\u064f\u0648\u062f\u0657\u0627 \u0648\u064e\u0639\u064e\u0644\u064e\u0649\u0670 \u062c\u064f\u0646\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u064a\u064e\u062a\u064e\u0641\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u062e\u064e\u0644\u06e1\u0642\u0650 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u06e1\u062a\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0628\u064e\u0670\u0637\u0650\u0644\u0657\u0627 \u0633\u064f\u0628\u06e1\u062d\u064e\u0670\u0646\u064e\u0643\u064e \u0641\u064e\u0642\u0650\u0646\u064e\u0627 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650",translation:"(yaitu) orang-orang yang mengingat Allah sambil berdiri, duduk atau dalam keadaan berbaring, dan mereka memikirkan tentang penciptaan langit dan bumi (seraya berkata), \"Ya Tuhan kami, tidaklah Engkau menciptakan semua ini sia-sia; Mahasuci Engkau, lindungilah kami dari azab neraka"},{id:192,text:"\u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0645\u064e\u0646 \u062a\u064f\u062f\u06e1\u062e\u0650\u0644\u0650 \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u064e \u0641\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u062e\u06e1\u0632\u064e\u064a\u06e1\u062a\u064e\u0647\u064f\u06e5\u06d6 \u0648\u064e\u0645\u064e\u0627 \u0644\u0650\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u06e1 \u0623\u064e\u0646\u0635\u064e\u0627\u0631\u0656",translation:"Ya Tuhan kami, sesungguhnya orang yang Engkau masukkan ke dalam neraka, maka sungguh, Engkau telah menghinakannya, dan tidak ada seorang penolong pun bagi orang yang zalim"},{id:193,text:"\u0631\u0651\u064e\u0628\u0651\u064e\u0646\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0646\u064e\u0627 \u0633\u064e\u0645\u0650\u0639\u06e1\u0646\u064e\u0627 \u0645\u064f\u0646\u064e\u0627\u062f\u0650\u064a\u0657\u0627 \u064a\u064f\u0646\u064e\u0627\u062f\u0650\u064a \u0644\u0650\u0644\u06e1\u0625\u0650\u064a\u0645\u064e\u0670\u0646\u0650 \u0623\u064e\u0646\u06e1 \u0621\u064e\u0627\u0645\u0650\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1 \u0641\u064e\u0640\u0654\u064e\u0627\u0645\u064e\u0646\u0651\u064e\u0627\u06da \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0641\u064e\u0671\u063a\u06e1\u0641\u0650\u0631\u06e1 \u0644\u064e\u0646\u064e\u0627 \u0630\u064f\u0646\u064f\u0648\u0628\u064e\u0646\u064e\u0627 \u0648\u064e\u0643\u064e\u0641\u0651\u0650\u0631\u06e1 \u0639\u064e\u0646\u0651\u064e\u0627 \u0633\u064e\u064a\u0651\u0650\u0640\u0654\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0648\u064e\u062a\u064e\u0648\u064e\u0641\u0651\u064e\u0646\u064e\u0627 \u0645\u064e\u0639\u064e \u0671\u0644\u06e1\u0623\u064e\u0628\u06e1\u0631\u064e\u0627\u0631\u0650",translation:"Ya Tuhan kami, sesungguhnya kami mendengar orang yang menyeru kepada iman, (yaitu), \"Berimanlah kamu kepada Tuhanmu,\" maka kami pun beriman. Ya Tuhan kami, ampunilah dosa-dosa kami dan hapuskanlah kesalahan-kesalahan kami, dan matikanlah kami bersama orang-orang yang berbakti"},{id:194,text:"\u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0648\u064e\u0621\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0645\u064e\u0627 \u0648\u064e\u0639\u064e\u062f\u062a\u0651\u064e\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064f\u0633\u064f\u0644\u0650\u0643\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u062e\u06e1\u0632\u0650\u0646\u064e\u0627 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650\u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u0627 \u062a\u064f\u062e\u06e1\u0644\u0650\u0641\u064f \u0671\u0644\u06e1\u0645\u0650\u064a\u0639\u064e\u0627\u062f\u064e",translation:"Ya Tuhan kami, berilah kami apa yang telah Engkau janjikan kepada kami melalui Rasul-rasul-Mu. Dan janganlah Engkau hinakan kami pada hari Kiamat. Sungguh, Engkau tidak pernah mengingkari janji"},{id:195,text:"\u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u062c\u064e\u0627\u0628\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0631\u064e\u0628\u0651\u064f\u0647\u064f\u0645\u06e1 \u0623\u064e\u0646\u0651\u0650\u064a \u0644\u064e\u0627\u0653 \u0623\u064f\u0636\u0650\u064a\u0639\u064f \u0639\u064e\u0645\u064e\u0644\u064e \u0639\u064e\u0670\u0645\u0650\u0644\u0656 \u0645\u0651\u0650\u0646\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0630\u064e\u0643\u064e\u0631\u064d \u0623\u064e\u0648\u06e1 \u0623\u064f\u0646\u062b\u064e\u0649\u0670\u06d6 \u0628\u064e\u0639\u06e1\u0636\u064f\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u0636\u0656\u06d6 \u0641\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064e\u0627\u062c\u064e\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u0623\u064f\u062e\u06e1\u0631\u0650\u062c\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u062f\u0650\u064a\u064e\u0670\u0631\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0623\u064f\u0648\u0630\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650\u064a \u0648\u064e\u0642\u064e\u0670\u062a\u064e\u0644\u064f\u0648\u0627\u0652 \u0648\u064e\u0642\u064f\u062a\u0650\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0623\u064f\u0643\u064e\u0641\u0651\u0650\u0631\u064e\u0646\u0651\u064e \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0633\u064e\u064a\u0651\u0650\u0640\u0654\u064e\u0627\u062a\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0644\u064e\u0623\u064f\u062f\u06e1\u062e\u0650\u0644\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0656 \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0645\u0650\u0646 \u062a\u064e\u062d\u06e1\u062a\u0650\u0647\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u064f \u062b\u064e\u0648\u064e\u0627\u0628\u0657\u0627 \u0645\u0651\u0650\u0646\u06e1 \u0639\u0650\u0646\u062f\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u0650\u0646\u062f\u064e\u0647\u064f\u06e5 \u062d\u064f\u0633\u06e1\u0646\u064f \u0671\u0644\u062b\u0651\u064e\u0648\u064e\u0627\u0628\u0650",translation:"Maka Tuhan mereka memperkenankan permohonannya (dengan berfirman), \"Sesungguhnya Aku tidak menyia-nyiakan amal orang yang beramal di antara kamu, baik laki-laki maupun perempuan, (karena) sebagian kamu adalah (keturunan) dari sebagian yang lain.171) Maka orang yang berhijrah, yang diusir dari kampung halamannya, yang disakiti pada jalan-Ku, yang berperang dan yang terbunuh, pasti akan Aku hapus kesalahan mereka dan pasti Aku masukkan mereka ke dalam surga-surga yang mengalir di bawahnya sungai-sungai, sebagai pahala dari Allah. Dan di sisi Allah ada pahala yang baik"},{id:196,text:"\u0644\u064e\u0627 \u064a\u064e\u063a\u064f\u0631\u0651\u064e\u0646\u0651\u064e\u0643\u064e \u062a\u064e\u0642\u064e\u0644\u0651\u064f\u0628\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u06e1\u0628\u0650\u0644\u064e\u0670\u062f\u0650",translation:"Jangan sekali-kali kamu terpedaya oleh kegiatan orang-orang kafir (yang bergerak) di seluruh negeri"},{id:197,text:"\u0645\u064e\u062a\u064e\u0670\u0639\u065e \u0642\u064e\u0644\u0650\u064a\u0644\u065e \u062b\u064f\u0645\u0651\u064e \u0645\u064e\u0623\u06e1\u0648\u064e\u0649\u0670\u0647\u064f\u0645\u06e1 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064f\u06d6 \u0648\u064e\u0628\u0650\u0626\u06e1\u0633\u064e \u0671\u0644\u06e1\u0645\u0650\u0647\u064e\u0627\u062f\u064f",translation:"Itu hanyalah kesenangan sementara, kemudian tempat kembali mereka ialah neraka Jahanam. (Jahanam) itu seburuk-buruk tempat tinggal"},{id:198,text:"\u0644\u064e\u0670\u0643\u0650\u0646\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u062a\u0651\u064e\u0642\u064e\u0648\u06e1\u0627\u0652 \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0647\u064f\u0645\u06e1 \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u065e \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0645\u0650\u0646 \u062a\u064e\u062d\u06e1\u062a\u0650\u0647\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u064f \u062e\u064e\u0670\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0646\u064f\u0632\u064f\u0644\u0657\u0627 \u0645\u0651\u0650\u0646\u06e1 \u0639\u0650\u0646\u062f\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d7 \u0648\u064e\u0645\u064e\u0627 \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062e\u064e\u064a\u06e1\u0631\u065e \u0644\u0651\u0650\u0644\u06e1\u0623\u064e\u0628\u06e1\u0631\u064e\u0627\u0631\u0650",translation:"Tetapi orang-orang yang bertakwa kepada Tuhannya, mereka akan mendapat surga-surga yang mengalir di bawahnya sungai-sungai, mereka kekal di dalamnya sebagai karunia dari Allah. Dan apa yang di sisi Allah lebih baik bagi orang-orang yang berbakti"},{id:199,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0645\u0650\u0646\u06e1 \u0623\u064e\u0647\u06e1\u0644\u0650 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0644\u064e\u0645\u064e\u0646 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u062e\u064e\u0670\u0634\u0650\u0639\u0650\u064a\u0646\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0627 \u064a\u064e\u0634\u06e1\u062a\u064e\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062b\u064e\u0645\u064e\u0646\u0657\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627\u06da \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u062c\u06e1\u0631\u064f\u0647\u064f\u0645\u06e1 \u0639\u0650\u0646\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1\u06d7 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0633\u064e\u0631\u0650\u064a\u0639\u064f \u0671\u0644\u06e1\u062d\u0650\u0633\u064e\u0627\u0628\u0650",translation:"Dan sesungguhnya di antara Ahli Kitab ada yang beriman kepada Allah, dan kepada apa yang diturunkan kepada kamu, dan yang diturunkan kepada mereka, karena mereka berendah hati kepada Allah, dan mereka tidak memperjualbelikan ayat-ayat Allah dengan harga murah. Mereka memperoleh pahala di sisi Tuhannya. Sungguh, Allah sangat cepat perhitungan-Nya"},{id:200,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0671\u0635\u06e1\u0628\u0650\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u0635\u064e\u0627\u0628\u0650\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u0631\u064e\u0627\u0628\u0650\u0637\u064f\u0648\u0627\u0652 \u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064f\u0641\u06e1\u0644\u0650\u062d\u064f\u0648\u0646\u064e",translation:"Wahai orang-orang yang beriman! Bersabarlah kamu dan kuatkanlah kesabaranmu dan tetaplah bersiap-siaga (di perbatasan negerimu) dan bertakwalah kepada Allah agar kamu beruntung"}]},{id:4,name:"\u0627\u0644\u0646\u0633\u0627\u0621",transliteration:"An-Nisa",translation:"Wanita",type:"medinan",total_verses:176,verses:[{id:1,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0646\u0651\u064e\u0641\u06e1\u0633\u0656 \u0648\u064e\u0670\u062d\u0650\u062f\u064e\u0629\u0656 \u0648\u064e\u062e\u064e\u0644\u064e\u0642\u064e \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0632\u064e\u0648\u06e1\u062c\u064e\u0647\u064e\u0627 \u0648\u064e\u0628\u064e\u062b\u0651\u064e \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u064e\u0627 \u0631\u0650\u062c\u064e\u0627\u0644\u0657\u0627 \u0643\u064e\u062b\u0650\u064a\u0631\u0657\u0627 \u0648\u064e\u0646\u0650\u0633\u064e\u0627\u0653\u0621\u0657\u06da \u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062a\u064e\u0633\u064e\u0627\u0653\u0621\u064e\u0644\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u0650\u06e6 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u062d\u064e\u0627\u0645\u064e\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0631\u064e\u0642\u0650\u064a\u0628\u0657\u0627",translation:"Wahai manusia! Bertakwalah kepada Tuhanmu yang telah menciptakan kamu dari diri yang satu (Adam), dan (Allah) menciptakan pasangannya (Hawa) dari (diri)nya; dan dari keduanya Allah mengembangbiakkan laki-laki dan perempuan yang banyak. Bertakwalah kepada Allah yang dengan nama-Nya kamu saling meminta,172) dan (peliharalah) hubungan kekeluargaan. Sesungguhnya Allah selalu menjaga dan mengawasimu"},{id:2,text:"\u0648\u064e\u0621\u064e\u0627\u062a\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u064a\u064e\u062a\u064e\u0670\u0645\u064e\u0649\u0670\u0653 \u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u064e\u0647\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u064e\u0628\u064e\u062f\u0651\u064e\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u062e\u064e\u0628\u0650\u064a\u062b\u064e \u0628\u0650\u0671\u0644\u0637\u0651\u064e\u064a\u0651\u0650\u0628\u0650\u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u064e\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0643\u064e\u0627\u0646\u064e \u062d\u064f\u0648\u0628\u0657\u0627 \u0643\u064e\u0628\u0650\u064a\u0631\u0657\u0627",translation:"Dan berikanlah kepada anak-anak yatim (yang sudah dewasa) harta mereka, janganlah kamu menukar yang baik dengan yang buruk, dan janganlah kamu makan harta mereka bersama hartamu. Sungguh, (tindakan menukar dan memakan) itu adalah dosa yang besar"},{id:3,text:"\u0648\u064e\u0625\u0650\u0646\u06e1 \u062e\u0650\u0641\u06e1\u062a\u064f\u0645\u06e1 \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064f\u0642\u06e1\u0633\u0650\u0637\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u06e1\u064a\u064e\u062a\u064e\u0670\u0645\u064e\u0649\u0670 \u0641\u064e\u0671\u0646\u0643\u0650\u062d\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u0637\u064e\u0627\u0628\u064e \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0653\u0621\u0650 \u0645\u064e\u062b\u06e1\u0646\u064e\u0649\u0670 \u0648\u064e\u062b\u064f\u0644\u064e\u0670\u062b\u064e \u0648\u064e\u0631\u064f\u0628\u064e\u0670\u0639\u064e\u06d6 \u0641\u064e\u0625\u0650\u0646\u06e1 \u062e\u0650\u0641\u06e1\u062a\u064f\u0645\u06e1 \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064e\u0639\u06e1\u062f\u0650\u0644\u064f\u0648\u0627\u0652 \u0641\u064e\u0648\u064e\u0670\u062d\u0650\u062f\u064e\u0629\u064b \u0623\u064e\u0648\u06e1 \u0645\u064e\u0627 \u0645\u064e\u0644\u064e\u0643\u064e\u062a\u06e1 \u0623\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u064f\u0643\u064f\u0645\u06e1\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0623\u064e\u062f\u06e1\u0646\u064e\u0649\u0670\u0653 \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064e\u0639\u064f\u0648\u0644\u064f\u0648\u0627\u0652",translation:"Dan jika kamu khawatir tidak akan mampu berlaku adil terhadap (hak-hak) perempuan yatim (bilamana kamu menikahinya), maka nikahilah perempuan (lain) yang kamu senangi: dua, tiga atau empat. Tetapi jika kamu khawatir tidak akan mampu berlaku adil,173) maka (nikahilah) seorang saja,174) atau hamba sahaya perempuan yang kamu miliki.175) Yang demikian itu lebih dekat agar kamu tidak berbuat zalim"},{id:4,text:"\u0648\u064e\u0621\u064e\u0627\u062a\u064f\u0648\u0627\u0652 \u0671\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0653\u0621\u064e \u0635\u064e\u062f\u064f\u0642\u064e\u0670\u062a\u0650\u0647\u0650\u0646\u0651\u064e \u0646\u0650\u062d\u06e1\u0644\u064e\u0629\u0657\u06da \u0641\u064e\u0625\u0650\u0646 \u0637\u0650\u0628\u06e1\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u06e1 \u0639\u064e\u0646 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f \u0646\u064e\u0641\u06e1\u0633\u0657\u0627 \u0641\u064e\u0643\u064f\u0644\u064f\u0648\u0647\u064f \u0647\u064e\u0646\u0650\u064a\u0653\u0640\u0654\u0657\u0627 \u0645\u0651\u064e\u0631\u0650\u064a\u0653\u0640\u0654\u0657\u0627",translation:"Dan berikanlah maskawin (mahar) kepada perempuan (yang kamu nikahi) sebagai pemberian yang penuh kerelaan.176) Kemudian, jika mereka menyerahkan kepada kamu sebagian dari (maskawin) itu dengan senang hati, maka terimalah dan nikmatillah pemberian itu dengan senang hati"},{id:5,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0624\u06e1\u062a\u064f\u0648\u0627\u0652 \u0671\u0644\u0633\u0651\u064f\u0641\u064e\u0647\u064e\u0627\u0653\u0621\u064e \u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0651\u064e\u062a\u0650\u064a \u062c\u064e\u0639\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u06e1 \u0642\u0650\u064a\u064e\u0670\u0645\u0657\u0627 \u0648\u064e\u0671\u0631\u06e1\u0632\u064f\u0642\u064f\u0648\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0671\u0643\u06e1\u0633\u064f\u0648\u0647\u064f\u0645\u06e1 \u0648\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0642\u064e\u0648\u06e1\u0644\u0657\u0627 \u0645\u0651\u064e\u0639\u06e1\u0631\u064f\u0648\u0641\u0657\u0627",translation:"(Dan janganlah kamu serahkan kepada orang yang belum sempurna akalnya,177) harta (mereka yang ada dalam kekuasaan) kamu yang dijadikan Allah sebagai pokok kehidupan. Berilah mereka belanja dan pakaian (dari hasil harta itu) dan ucapkanlah kepada mereka perkataan yang baik"},{id:6,text:"\u0648\u064e\u0671\u0628\u06e1\u062a\u064e\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u064a\u064e\u062a\u064e\u0670\u0645\u064e\u0649\u0670 \u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u064e\u0627 \u0628\u064e\u0644\u064e\u063a\u064f\u0648\u0627\u0652 \u0671\u0644\u0646\u0651\u0650\u0643\u064e\u0627\u062d\u064e \u0641\u064e\u0625\u0650\u0646\u06e1 \u0621\u064e\u0627\u0646\u064e\u0633\u06e1\u062a\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0631\u064f\u0634\u06e1\u062f\u0657\u0627 \u0641\u064e\u0671\u062f\u06e1\u0641\u064e\u0639\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u064e\u0647\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f\u0648\u0647\u064e\u0627\u0653 \u0625\u0650\u0633\u06e1\u0631\u064e\u0627\u0641\u0657\u0627 \u0648\u064e\u0628\u0650\u062f\u064e\u0627\u0631\u064b\u0627 \u0623\u064e\u0646 \u064a\u064e\u0643\u06e1\u0628\u064e\u0631\u064f\u0648\u0627\u0652\u06da \u0648\u064e\u0645\u064e\u0646 \u0643\u064e\u0627\u0646\u064e \u063a\u064e\u0646\u0650\u064a\u0651\u0657\u0627 \u0641\u064e\u0644\u06e1\u064a\u064e\u0633\u06e1\u062a\u064e\u0639\u06e1\u0641\u0650\u0641\u06e1\u06d6 \u0648\u064e\u0645\u064e\u0646 \u0643\u064e\u0627\u0646\u064e \u0641\u064e\u0642\u0650\u064a\u0631\u0657\u0627 \u0641\u064e\u0644\u06e1\u064a\u064e\u0623\u06e1\u0643\u064f\u0644\u06e1 \u0628\u0650\u0671\u0644\u06e1\u0645\u064e\u0639\u06e1\u0631\u064f\u0648\u0641\u0650\u06da \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u062f\u064e\u0641\u064e\u0639\u06e1\u062a\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u064e\u0647\u064f\u0645\u06e1 \u0641\u064e\u0623\u064e\u0634\u06e1\u0647\u0650\u062f\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1\u06da \u0648\u064e\u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u064e\u0633\u0650\u064a\u0628\u0657\u0627",translation:"(Dan ujilah178) anak-anak yatim itu sampai mereka cukup umur untuk menikah. Kemudian jika menurut pendapatmu mereka telah cerdas (pandai memelihara harta), maka serahkanlah kepada mereka hartanya. Dan janganlah kamu memakannya (harta anak yatim) melebihi batas kepatutan dan (janganlah kamu) tergesa-gesa (menyerahkannya) sebelum mereka dewasa. Barang siapa (di antara pemelihara itu) mampu, maka hendaklah dia menahan diri (dari memakan harta anak yatim itu) dan barang siapa miskin, maka bolehlah dia makan harta itu menurut cara yang patut. Kemudian, apabila kamu menyerahkan harta itu kepada mereka, maka hendaklah kamu adakan saksi-saksi. Dan cukuplah Allah sebagai pengawas"},{id:7,text:"\u0644\u0651\u0650\u0644\u0631\u0651\u0650\u062c\u064e\u0627\u0644\u0650 \u0646\u064e\u0635\u0650\u064a\u0628\u065e \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0631\u064e\u0643\u064e \u0671\u0644\u06e1\u0648\u064e\u0670\u0644\u0650\u062f\u064e\u0627\u0646\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0642\u06e1\u0631\u064e\u0628\u064f\u0648\u0646\u064e \u0648\u064e\u0644\u0650\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0653\u0621\u0650 \u0646\u064e\u0635\u0650\u064a\u0628\u065e \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0631\u064e\u0643\u064e \u0671\u0644\u06e1\u0648\u064e\u0670\u0644\u0650\u062f\u064e\u0627\u0646\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0642\u06e1\u0631\u064e\u0628\u064f\u0648\u0646\u064e \u0645\u0650\u0645\u0651\u064e\u0627 \u0642\u064e\u0644\u0651\u064e \u0645\u0650\u0646\u06e1\u0647\u064f \u0623\u064e\u0648\u06e1 \u0643\u064e\u062b\u064f\u0631\u064e\u06da \u0646\u064e\u0635\u0650\u064a\u0628\u0657\u0627 \u0645\u0651\u064e\u0641\u06e1\u0631\u064f\u0648\u0636\u0657\u0627",translation:"Bagi laki-laki ada hak bagian dari harta peninggalan kedua orang tua dan kerabatnya, dan bagi perempuan ada hak bagian (pula) dari harta peninggalan kedua orang tua dan kerabatnya, baik sedikit atau banyak menurut bagian yang telah ditetapkan"},{id:8,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062d\u064e\u0636\u064e\u0631\u064e \u0671\u0644\u06e1\u0642\u0650\u0633\u06e1\u0645\u064e\u0629\u064e \u0623\u064f\u0648\u0652\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0628\u064e\u0649\u0670 \u0648\u064e\u0671\u0644\u06e1\u064a\u064e\u062a\u064e\u0670\u0645\u064e\u0649\u0670 \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u0633\u064e\u0670\u0643\u0650\u064a\u0646\u064f \u0641\u064e\u0671\u0631\u06e1\u0632\u064f\u0642\u064f\u0648\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f \u0648\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0642\u064e\u0648\u06e1\u0644\u0657\u0627 \u0645\u0651\u064e\u0639\u06e1\u0631\u064f\u0648\u0641\u0657\u0627",translation:"(Dan apabila sewaktu pembagian itu hadir beberapa kerabat,179) anak-anak yatim dan orang-orang miskin, maka berilah mereka dari harta itu180) (sekedarnya) dan ucapkanlah kepada mereka perkataan yang baik"},{id:9,text:"\u0648\u064e\u0644\u06e1\u064a\u064e\u062e\u06e1\u0634\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0648\u06e1 \u062a\u064e\u0631\u064e\u0643\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1 \u062e\u064e\u0644\u06e1\u0641\u0650\u0647\u0650\u0645\u06e1 \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u0629\u0657 \u0636\u0650\u0639\u064e\u0670\u0641\u064b\u0627 \u062e\u064e\u0627\u0641\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0641\u064e\u0644\u06e1\u064a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0644\u06e1\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627\u0652 \u0642\u064e\u0648\u06e1\u0644\u0657\u0627 \u0633\u064e\u062f\u0650\u064a\u062f\u064b\u0627",translation:"Dan hendaklah takut (kepada Allah) orang-orang yang sekiranya mereka meninggalkan keturunan yang lemah di belakang mereka yang mereka khawatir terhadap (kesejahteraan)nya. Oleh sebab itu, hendaklah mereka bertakwa kepada Allah, dan hendaklah mereka berbicara dengan tutur kata yang benar"},{id:10,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f\u0648\u0646\u064e \u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u064e \u0671\u0644\u06e1\u064a\u064e\u062a\u064e\u0670\u0645\u064e\u0649\u0670 \u0638\u064f\u0644\u06e1\u0645\u064b\u0627 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0628\u064f\u0637\u064f\u0648\u0646\u0650\u0647\u0650\u0645\u06e1 \u0646\u064e\u0627\u0631\u0657\u0627\u06d6 \u0648\u064e\u0633\u064e\u064a\u064e\u0635\u06e1\u0644\u064e\u0648\u06e1\u0646\u064e \u0633\u064e\u0639\u0650\u064a\u0631\u0657\u0627",translation:"Sesungguhnya orang-orang yang memakan harta anak yatim secara zalim, sebenarnya mereka itu menelan api dalam perutnya dan mereka akan masuk ke dalam api yang menyala-nyala (neraka)"},{id:11,text:"\u064a\u064f\u0648\u0635\u0650\u064a\u0643\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u0650\u064a\u0653 \u0623\u064e\u0648\u06e1\u0644\u064e\u0670\u062f\u0650\u0643\u064f\u0645\u06e1\u06d6 \u0644\u0650\u0644\u0630\u0651\u064e\u0643\u064e\u0631\u0650 \u0645\u0650\u062b\u06e1\u0644\u064f \u062d\u064e\u0638\u0651\u0650 \u0671\u0644\u06e1\u0623\u064f\u0646\u062b\u064e\u064a\u064e\u064a\u06e1\u0646\u0650\u06da \u0641\u064e\u0625\u0650\u0646 \u0643\u064f\u0646\u0651\u064e \u0646\u0650\u0633\u064e\u0627\u0653\u0621\u0657 \u0641\u064e\u0648\u06e1\u0642\u064e \u0671\u062b\u06e1\u0646\u064e\u062a\u064e\u064a\u06e1\u0646\u0650 \u0641\u064e\u0644\u064e\u0647\u064f\u0646\u0651\u064e \u062b\u064f\u0644\u064f\u062b\u064e\u0627 \u0645\u064e\u0627 \u062a\u064e\u0631\u064e\u0643\u064e\u06d6 \u0648\u064e\u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064e\u062a\u06e1 \u0648\u064e\u0670\u062d\u0650\u062f\u064e\u0629\u0657 \u0641\u064e\u0644\u064e\u0647\u064e\u0627 \u0671\u0644\u0646\u0651\u0650\u0635\u06e1\u0641\u064f\u06da \u0648\u064e\u0644\u0650\u0623\u064e\u0628\u064e\u0648\u064e\u064a\u06e1\u0647\u0650 \u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0648\u064e\u0670\u062d\u0650\u062f\u0656 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u064e\u0627 \u0671\u0644\u0633\u0651\u064f\u062f\u064f\u0633\u064f \u0645\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0631\u064e\u0643\u064e \u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0647\u064f\u06e5 \u0648\u064e\u0644\u064e\u062f\u065e\u06da \u0641\u064e\u0625\u0650\u0646 \u0644\u0651\u064e\u0645\u06e1 \u064a\u064e\u0643\u064f\u0646 \u0644\u0651\u064e\u0647\u064f\u06e5 \u0648\u064e\u0644\u064e\u062f\u065e \u0648\u064e\u0648\u064e\u0631\u0650\u062b\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u0628\u064e\u0648\u064e\u0627\u0647\u064f \u0641\u064e\u0644\u0650\u0623\u064f\u0645\u0651\u0650\u0647\u0650 \u0671\u0644\u062b\u0651\u064f\u0644\u064f\u062b\u064f\u06da \u0641\u064e\u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0647\u064f\u06e5\u0653 \u0625\u0650\u062e\u06e1\u0648\u064e\u0629\u065e \u0641\u064e\u0644\u0650\u0623\u064f\u0645\u0651\u0650\u0647\u0650 \u0671\u0644\u0633\u0651\u064f\u062f\u064f\u0633\u064f\u06da \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0648\u064e\u0635\u0650\u064a\u0651\u064e\u0629\u0656 \u064a\u064f\u0648\u0635\u0650\u064a \u0628\u0650\u0647\u064e\u0627\u0653 \u0623\u064e\u0648\u06e1 \u062f\u064e\u064a\u06e1\u0646\u064d\u06d7 \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0624\u064f\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0628\u06e1\u0646\u064e\u0627\u0653\u0624\u064f\u0643\u064f\u0645\u06e1 \u0644\u064e\u0627 \u062a\u064e\u062f\u06e1\u0631\u064f\u0648\u0646\u064e \u0623\u064e\u064a\u0651\u064f\u0647\u064f\u0645\u06e1 \u0623\u064e\u0642\u06e1\u0631\u064e\u0628\u064f \u0644\u064e\u0643\u064f\u0645\u06e1 \u0646\u064e\u0641\u06e1\u0639\u0657\u0627\u06da \u0641\u064e\u0631\u0650\u064a\u0636\u064e\u0629\u0657 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d7 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u064b\u0627 \u062d\u064e\u0643\u0650\u064a\u0645\u0657\u0627",translation:"Allah mensyariatkan (mewajibkan) kepadamu tentang (pembagian warisan untuk) anak-anakmu, (yaitu) bagian seorang anak laki-laki sama dengan bagian dua orang anak perempuan.181) Dan jika anak itu semuanya perempuan yang jumlahnya lebih dari dua, maka bagian mereka dua pertiga dari harta yang ditinggalkan. Jika dia (anak perempuan) itu seorang saja, maka dia memperoleh setengah (harta yang ditinggalkan). Dan untuk kedua ibu-bapak, bagian masing-masing seperenam dari harta yang ditinggalkan, jika dia (yang meninggal) mempunyai anak. Jika dia (yang meninggal) tidak mempunyai anak dan dia diwarisi oleh kedua ibu-bapaknya (saja), maka ibunya mendapat sepertiga. Jika dia (yang meninggal) mempunyai beberapa saudara, maka ibunya mendapat seperenam. (Pembagian-pembagian tersebut di atas) setelah (dipenuhi) wasiat yang dibuatnya atau (dan setelah dibayar) hutangnya. (Tentang) orang tuamu dan anak-anakmu, kamu tidak mengetahui siapa di antara mereka yang lebih banyak manfaatnya bagimu. Ini adalah ketetapan Allah. Sungguh, Allah Maha Mengetahui, Mahabijaksana"},{id:12,text:"\u06de\u0648\u064e\u0644\u064e\u0643\u064f\u0645\u06e1 \u0646\u0650\u0635\u06e1\u0641\u064f \u0645\u064e\u0627 \u062a\u064e\u0631\u064e\u0643\u064e \u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u064f\u0643\u064f\u0645\u06e1 \u0625\u0650\u0646 \u0644\u0651\u064e\u0645\u06e1 \u064a\u064e\u0643\u064f\u0646 \u0644\u0651\u064e\u0647\u064f\u0646\u0651\u064e \u0648\u064e\u0644\u064e\u062f\u065e\u06da \u0641\u064e\u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0647\u064f\u0646\u0651\u064e \u0648\u064e\u0644\u064e\u062f\u065e \u0641\u064e\u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0631\u0651\u064f\u0628\u064f\u0639\u064f \u0645\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0631\u064e\u0643\u06e1\u0646\u064e\u06da \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0648\u064e\u0635\u0650\u064a\u0651\u064e\u0629\u0656 \u064a\u064f\u0648\u0635\u0650\u064a\u0646\u064e \u0628\u0650\u0647\u064e\u0627\u0653 \u0623\u064e\u0648\u06e1 \u062f\u064e\u064a\u06e1\u0646\u0656\u06da \u0648\u064e\u0644\u064e\u0647\u064f\u0646\u0651\u064e \u0671\u0644\u0631\u0651\u064f\u0628\u064f\u0639\u064f \u0645\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0631\u064e\u0643\u06e1\u062a\u064f\u0645\u06e1 \u0625\u0650\u0646 \u0644\u0651\u064e\u0645\u06e1 \u064a\u064e\u0643\u064f\u0646 \u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u062f\u065e\u06da \u0641\u064e\u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u062f\u065e \u0641\u064e\u0644\u064e\u0647\u064f\u0646\u0651\u064e \u0671\u0644\u062b\u0651\u064f\u0645\u064f\u0646\u064f \u0645\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0631\u064e\u0643\u06e1\u062a\u064f\u0645\u06da \u0645\u0651\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0648\u064e\u0635\u0650\u064a\u0651\u064e\u0629\u0656 \u062a\u064f\u0648\u0635\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u064e\u0627\u0653 \u0623\u064e\u0648\u06e1 \u062f\u064e\u064a\u06e1\u0646\u0656\u06d7 \u0648\u064e\u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064e \u0631\u064e\u062c\u064f\u0644\u065e \u064a\u064f\u0648\u0631\u064e\u062b\u064f \u0643\u064e\u0644\u064e\u0670\u0644\u064e\u0629\u064b \u0623\u064e\u0648\u0650 \u0671\u0645\u06e1\u0631\u064e\u0623\u064e\u0629\u065e \u0648\u064e\u0644\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u062e\u064c \u0623\u064e\u0648\u06e1 \u0623\u064f\u062e\u06e1\u062a\u065e \u0641\u064e\u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0648\u064e\u0670\u062d\u0650\u062f\u0656 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u064e\u0627 \u0671\u0644\u0633\u0651\u064f\u062f\u064f\u0633\u064f\u06da \u0641\u064e\u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064e \u0645\u0650\u0646 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u0647\u064f\u0645\u06e1 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0653\u0621\u064f \u0641\u0650\u064a \u0671\u0644\u062b\u0651\u064f\u0644\u064f\u062b\u0650\u06da \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0648\u064e\u0635\u0650\u064a\u0651\u064e\u0629\u0656 \u064a\u064f\u0648\u0635\u064e\u0649\u0670 \u0628\u0650\u0647\u064e\u0627\u0653 \u0623\u064e\u0648\u06e1 \u062f\u064e\u064a\u06e1\u0646\u064d \u063a\u064e\u064a\u06e1\u0631\u064e \u0645\u064f\u0636\u064e\u0627\u0653\u0631\u0651\u0656\u06da \u0648\u064e\u0635\u0650\u064a\u0651\u064e\u0629\u0657 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u062d\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Dan bagianmu (suami-suami) adalah seperdua dari harta yang ditinggalkan oleh istri-istrimu, jika mereka tidak mempunyai anak. Jika mereka (istri-istrimu) itu mempunyai anak, maka kamu mendapat seperempat dari harta yang ditinggalkannya setelah (dipenuhi) wasiat yang mereka buat atau (dan setelah dibayar) hutangnya. Para istri memperoleh seperempat harta yang kamu tinggalkan jika kamu tidak mempunyai anak. Jika kamu mempunyai anak, maka para istri memperoleh seperdelapan dari harta yang kamu tinggalkan (setelah dipenuhi) wasiat yang kamu buat atau (dan setelah dibayar) hutang-hutangmu. Jika seseorang meninggal, baik laki-laki maupun perempuan yang tidak meninggalkan ayah dan tidak meninggalkan anak, tetapi mempunyai seorang saudara laki-laki (seibu) atau seorang saudara perempuan (seibu), maka bagi masing-masing dari kedua jenis saudara itu seperenam harta. Tetapi jika saudara-saudara seibu itu lebih dari seorang, maka mereka bersama-sama dalam bagian yang sepertiga itu, setelah (dipenuhi wasiat) yang dibuatnya atau (dan setelah dibayar) hutangnya dengan tidak menyusahkan (kepada ahli waris).182) Demikianlah ketentuan Allah. Allah Maha Mengetahui, Maha Penyantun"},{id:13,text:"\u062a\u0650\u0644\u06e1\u0643\u064e \u062d\u064f\u062f\u064f\u0648\u062f\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0637\u0650\u0639\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f\u06e5 \u064a\u064f\u062f\u06e1\u062e\u0650\u0644\u06e1\u0647\u064f \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0656 \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0645\u0650\u0646 \u062a\u064e\u062d\u06e1\u062a\u0650\u0647\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u064f \u062e\u064e\u0670\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627\u06da \u0648\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0671\u0644\u06e1\u0641\u064e\u0648\u06e1\u0632\u064f \u0671\u0644\u06e1\u0639\u064e\u0638\u0650\u064a\u0645\u064f",translation:"Itulah batas-batas (hukum) Allah. Barang siapa taat kepada Allah dan Rasul-Nya, Dia akan memasukkannya ke dalam surga-surga yang mengalir di bawahnya sungai-sungai, mereka kekal di dalamnya. Dan itulah kemenangan yang agung"},{id:14,text:"\u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0639\u06e1\u0635\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f\u06e5 \u0648\u064e\u064a\u064e\u062a\u064e\u0639\u064e\u062f\u0651\u064e \u062d\u064f\u062f\u064f\u0648\u062f\u064e\u0647\u064f\u06e5 \u064a\u064f\u062f\u06e1\u062e\u0650\u0644\u06e1\u0647\u064f \u0646\u064e\u0627\u0631\u064b\u0627 \u062e\u064e\u0670\u0644\u0650\u062f\u0657\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0647\u064f\u06e5 \u0639\u064e\u0630\u064e\u0627\u0628\u065e \u0645\u0651\u064f\u0647\u0650\u064a\u0646\u065e",translation:"Dan barang siapa mendurhakai Allah dan Rasul-Nya dan melanggar batas-batas hukum-Nya, niscaya Allah memasukkannya ke dalam api neraka, dia kekal di dalamnya dan dia akan mendapat azab yang menghinakan"},{id:15,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0640\u0670\u062a\u0650\u064a \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u0646\u064e \u0671\u0644\u06e1\u0641\u064e\u0670\u062d\u0650\u0634\u064e\u0629\u064e \u0645\u0650\u0646 \u0646\u0651\u0650\u0633\u064e\u0627\u0653\u0626\u0650\u0643\u064f\u0645\u06e1 \u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u0634\u06e1\u0647\u0650\u062f\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0646\u0651\u064e \u0623\u064e\u0631\u06e1\u0628\u064e\u0639\u064e\u0629\u0657 \u0645\u0651\u0650\u0646\u0643\u064f\u0645\u06e1\u06d6 \u0641\u064e\u0625\u0650\u0646 \u0634\u064e\u0647\u0650\u062f\u064f\u0648\u0627\u0652 \u0641\u064e\u0623\u064e\u0645\u06e1\u0633\u0650\u0643\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0628\u064f\u064a\u064f\u0648\u062a\u0650 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u062a\u064e\u0648\u064e\u0641\u0651\u064e\u0649\u0670\u0647\u064f\u0646\u0651\u064e \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u064f \u0623\u064e\u0648\u06e1 \u064a\u064e\u062c\u06e1\u0639\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0647\u064f\u0646\u0651\u064e \u0633\u064e\u0628\u0650\u064a\u0644\u0657\u0627",translation:"(Dan para perempuan yang melakukan perbuatan keji183) di antara perempuan-perempuan kamu, hendaklah terhadap mereka ada empat orang saksi di antara kamu (yang menyaksikannya). Apabila mereka telah memberi kesaksian, maka kurunglah mereka (perempuan itu) dalam rumah sampai mereka menemui ajalnya, atau sampai Allah memberi jalan (yang lain) kepadanya"},{id:16,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u064e\u0627\u0646\u0650 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e\u0670\u0646\u0650\u0647\u064e\u0627 \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u0641\u064e\u0640\u0654\u064e\u0627\u0630\u064f\u0648\u0647\u064f\u0645\u064e\u0627\u06d6 \u0641\u064e\u0625\u0650\u0646 \u062a\u064e\u0627\u0628\u064e\u0627 \u0648\u064e\u0623\u064e\u0635\u06e1\u0644\u064e\u062d\u064e\u0627 \u0641\u064e\u0623\u064e\u0639\u06e1\u0631\u0650\u0636\u064f\u0648\u0627\u0652 \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u064e\u0627\u0653\u06d7 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u062a\u064e\u0648\u0651\u064e\u0627\u0628\u0657\u0627 \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064b\u0627",translation:"Dan terhadap dua orang yang melakukan perbuatan keji di antara kamu, maka berilah hukuman kepada keduanya. Jika keduanya tobat dan memperbaiki diri, maka biarkanlah mereka. Sungguh, Allah Maha Penerima tobat, Maha Penyayang"},{id:17,text:"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0671\u0644\u062a\u0651\u064e\u0648\u06e1\u0628\u064e\u0629\u064f \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0671\u0644\u0633\u0651\u064f\u0648\u0653\u0621\u064e \u0628\u0650\u062c\u064e\u0647\u064e\u0670\u0644\u064e\u0629\u0656 \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u062a\u064f\u0648\u0628\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0631\u0650\u064a\u0628\u0656 \u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u064a\u064e\u062a\u064f\u0648\u0628\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1\u06d7 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064b\u0627 \u062d\u064e\u0643\u0650\u064a\u0645\u0657\u0627",translation:"Sesungguhnya bertobat kepada Allah itu hanya (pantas) bagi mereka yang melakukan kejahatan karena tidak mengerti, kemudian segera bertobat. Tobat mereka itulah yang diterima Allah. Allah Maha Mengetahui, Mahabijaksana"},{id:18,text:"\u0648\u064e\u0644\u064e\u064a\u06e1\u0633\u064e\u062a\u0650 \u0671\u0644\u062a\u0651\u064e\u0648\u06e1\u0628\u064e\u0629\u064f \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0640\u0654\u064e\u0627\u062a\u0650 \u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u064e\u0627 \u062d\u064e\u0636\u064e\u0631\u064e \u0623\u064e\u062d\u064e\u062f\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u064f \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u062a\u064f\u0628\u06e1\u062a\u064f \u0671\u0644\u06e1\u0640\u0654\u064e\u0670\u0646\u064e \u0648\u064e\u0644\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0645\u064f\u0648\u062a\u064f\u0648\u0646\u064e \u0648\u064e\u0647\u064f\u0645\u06e1 \u0643\u064f\u0641\u0651\u064e\u0627\u0631\u064c\u06da \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0623\u064e\u0639\u06e1\u062a\u064e\u062f\u06e1\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0623\u064e\u0644\u0650\u064a\u0645\u0657\u0627",translation:"Dan tobat itu tidaklah (diterima Allah) dari mereka yang melakukan kejahatan hingga apabila datang ajal kepada seseorang di antara mereka, (barulah) dia mengatakan, \"Saya benar-benar bertobat sekarang.\" Dan tidak (pula diterima tobat) dari orang-orang yang meninggal sedang mereka di dalam kekafiran. Bagi orang-orang itu telah Kami sediakan azab yang pedih"},{id:19,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u064a\u064e\u062d\u0650\u0644\u0651\u064f \u0644\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u0646 \u062a\u064e\u0631\u0650\u062b\u064f\u0648\u0627\u0652 \u0671\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0653\u0621\u064e \u0643\u064e\u0631\u06e1\u0647\u0657\u0627\u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u0636\u064f\u0644\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0644\u0650\u062a\u064e\u0630\u06e1\u0647\u064e\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0628\u064e\u0639\u06e1\u0636\u0650 \u0645\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u062a\u064f\u0645\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u0646\u064e \u0628\u0650\u0641\u064e\u0670\u062d\u0650\u0634\u064e\u0629\u0656 \u0645\u0651\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0629\u0656\u06da \u0648\u064e\u0639\u064e\u0627\u0634\u0650\u0631\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0628\u0650\u0671\u0644\u06e1\u0645\u064e\u0639\u06e1\u0631\u064f\u0648\u0641\u0650\u06da \u0641\u064e\u0625\u0650\u0646 \u0643\u064e\u0631\u0650\u0647\u06e1\u062a\u064f\u0645\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0641\u064e\u0639\u064e\u0633\u064e\u0649\u0670\u0653 \u0623\u064e\u0646 \u062a\u064e\u0643\u06e1\u0631\u064e\u0647\u064f\u0648\u0627\u0652 \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627 \u0648\u064e\u064a\u064e\u062c\u06e1\u0639\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u0650\u064a\u0647\u0650 \u062e\u064e\u064a\u06e1\u0631\u0657\u0627 \u0643\u064e\u062b\u0650\u064a\u0631\u0657\u0627",translation:"(Wahai orang-orang yang beriman! Tidak halal bagi kamu mewarisi perempuan dengan jalan paksa185) dan janganlah kamu menyusahkan mereka karena hendak mengambil kembali sebagian dari apa yang telah kamu berikan kepadanya, kecuali apabila mereka melakukan perbuatan keji yang nyata. Dan bergaullah dengan mereka menurut cara yang patut. Jika kamu tidak menyukai mereka, (maka bersabarlah) karena boleh jadi kamu tidak menyukai sesuatu, padahal Allah menjadikan kebaikan yang banyak padanya"},{id:20,text:"\u0648\u064e\u0625\u0650\u0646\u06e1 \u0623\u064e\u0631\u064e\u062f\u062a\u0651\u064f\u0645\u064f \u0671\u0633\u06e1\u062a\u0650\u0628\u06e1\u062f\u064e\u0627\u0644\u064e \u0632\u064e\u0648\u06e1\u062c\u0656 \u0645\u0651\u064e\u0643\u064e\u0627\u0646\u064e \u0632\u064e\u0648\u06e1\u062c\u0656 \u0648\u064e\u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u062a\u064f\u0645\u06e1 \u0625\u0650\u062d\u06e1\u062f\u064e\u0649\u0670\u0647\u064f\u0646\u0651\u064e \u0642\u0650\u0646\u0637\u064e\u0627\u0631\u0657\u0627 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0623\u06e1\u062e\u064f\u0630\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1\u0647\u064f \u0634\u064e\u064a\u06e1\u0640\u0654\u064b\u0627\u06da \u0623\u064e\u062a\u064e\u0623\u06e1\u062e\u064f\u0630\u064f\u0648\u0646\u064e\u0647\u064f\u06e5 \u0628\u064f\u0647\u06e1\u062a\u064e\u0670\u0646\u0657\u0627 \u0648\u064e\u0625\u0650\u062b\u06e1\u0645\u0657\u0627 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u0657\u0627",translation:"Dan jika kamu ingin mengganti istrimu dengan istri yang lain, sedang kamu telah memberikan kepada seorang di antara mereka harta yang banyak, maka janganlah kamu mengambil kembali sedikit pun darinya. Apakah kamu akan mengambilnya kembali dengan jalan tuduhan yang dusta dan dengan (menanggung) dosa yang nyata"},{id:21,text:"\u0648\u064e\u0643\u064e\u064a\u06e1\u0641\u064e \u062a\u064e\u0623\u06e1\u062e\u064f\u0630\u064f\u0648\u0646\u064e\u0647\u064f\u06e5 \u0648\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u0641\u06e1\u0636\u064e\u0649\u0670 \u0628\u064e\u0639\u06e1\u0636\u064f\u0643\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u06e1\u0636\u0656 \u0648\u064e\u0623\u064e\u062e\u064e\u0630\u06e1\u0646\u064e \u0645\u0650\u0646\u0643\u064f\u0645 \u0645\u0651\u0650\u064a\u062b\u064e\u0670\u0642\u064b\u0627 \u063a\u064e\u0644\u0650\u064a\u0638\u0657\u0627",translation:"Dan bagaimana kamu akan mengambilnya kembali, padahal kamu telah bergaul satu sama lain (sebagai suami-istri). Dan mereka (istri-istrimu) telah mengambil perjanjian yang kuat (ikatan pernikahan) dari kamu"},{id:22,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0646\u0643\u0650\u062d\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u0646\u064e\u0643\u064e\u062d\u064e \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0624\u064f\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0653\u0621\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0642\u064e\u062f\u06e1 \u0633\u064e\u0644\u064e\u0641\u064e\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0643\u064e\u0627\u0646\u064e \u0641\u064e\u0670\u062d\u0650\u0634\u064e\u0629\u0657 \u0648\u064e\u0645\u064e\u0642\u06e1\u062a\u0657\u0627 \u0648\u064e\u0633\u064e\u0627\u0653\u0621\u064e \u0633\u064e\u0628\u0650\u064a\u0644\u064b\u0627",translation:"Dan janganlah kamu menikahi perempuan-perempuan yang telah dinikahi oleh ayahmu, kecuali (kejadian pada masa) yang telah lampau. Sungguh, perbuatan itu sangat keji dan dibenci (oleh Allah) dan seburuk-buruk jalan (yang ditempuh)"},{id:23,text:"\u062d\u064f\u0631\u0651\u0650\u0645\u064e\u062a\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0623\u064f\u0645\u0651\u064e\u0647\u064e\u0670\u062a\u064f\u0643\u064f\u0645\u06e1 \u0648\u064e\u0628\u064e\u0646\u064e\u0627\u062a\u064f\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u062e\u064e\u0648\u064e\u0670\u062a\u064f\u0643\u064f\u0645\u06e1 \u0648\u064e\u0639\u064e\u0645\u0651\u064e\u0640\u0670\u062a\u064f\u0643\u064f\u0645\u06e1 \u0648\u064e\u062e\u064e\u0670\u0644\u064e\u0670\u062a\u064f\u0643\u064f\u0645\u06e1 \u0648\u064e\u0628\u064e\u0646\u064e\u0627\u062a\u064f \u0671\u0644\u06e1\u0623\u064e\u062e\u0650 \u0648\u064e\u0628\u064e\u0646\u064e\u0627\u062a\u064f \u0671\u0644\u06e1\u0623\u064f\u062e\u06e1\u062a\u0650 \u0648\u064e\u0623\u064f\u0645\u0651\u064e\u0647\u064e\u0670\u062a\u064f\u0643\u064f\u0645\u064f \u0671\u0644\u0651\u064e\u0640\u0670\u062a\u0650\u064a\u0653 \u0623\u064e\u0631\u06e1\u0636\u064e\u0639\u06e1\u0646\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u062e\u064e\u0648\u064e\u0670\u062a\u064f\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0631\u0651\u064e\u0636\u064e\u0670\u0639\u064e\u0629\u0650 \u0648\u064e\u0623\u064f\u0645\u0651\u064e\u0647\u064e\u0670\u062a\u064f \u0646\u0650\u0633\u064e\u0627\u0653\u0626\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0631\u064e\u0628\u064e\u0640\u0670\u0653\u0626\u0650\u0628\u064f\u0643\u064f\u0645\u064f \u0671\u0644\u0651\u064e\u0640\u0670\u062a\u0650\u064a \u0641\u0650\u064a \u062d\u064f\u062c\u064f\u0648\u0631\u0650\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0646\u0651\u0650\u0633\u064e\u0627\u0653\u0626\u0650\u0643\u064f\u0645\u064f \u0671\u0644\u0651\u064e\u0640\u0670\u062a\u0650\u064a \u062f\u064e\u062e\u064e\u0644\u06e1\u062a\u064f\u0645 \u0628\u0650\u0647\u0650\u0646\u0651\u064e \u0641\u064e\u0625\u0650\u0646 \u0644\u0651\u064e\u0645\u06e1 \u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u062f\u064e\u062e\u064e\u0644\u06e1\u062a\u064f\u0645 \u0628\u0650\u0647\u0650\u0646\u0651\u064e \u0641\u064e\u0644\u064e\u0627 \u062c\u064f\u0646\u064e\u0627\u062d\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0648\u064e\u062d\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0644\u064f \u0623\u064e\u0628\u06e1\u0646\u064e\u0627\u0653\u0626\u0650\u0643\u064f\u0645\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u06e1 \u0623\u064e\u0635\u06e1\u0644\u064e\u0670\u0628\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0646 \u062a\u064e\u062c\u06e1\u0645\u064e\u0639\u064f\u0648\u0627\u0652 \u0628\u064e\u064a\u06e1\u0646\u064e \u0671\u0644\u06e1\u0623\u064f\u062e\u06e1\u062a\u064e\u064a\u06e1\u0646\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0642\u064e\u062f\u06e1 \u0633\u064e\u0644\u064e\u0641\u064e\u06d7 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u0657\u0627 \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0657\u0627",translation:"Diharamkan atas kamu (menikahi) ibu-ibumu, anak-anakmu yang perempuan, saudara-saudaramu yang perempuan, saudara-saudara ayahmu yang perempuan, saudara-saudara ibumu yang perempuan, anak-anak perempuan dari saudara-saudaramu yang laki-laki, anak-anak perempuan dari saudara-saudaramu yang perempuan, ibu-ibumu yang menyusui kamu, saudara-saudara perempuanmu sesusuan, ibu-ibu istrimu (mertua), anak-anak perempuan dari istrimu (anak tiri) yang dalam pemeliharaanmu186) dari istri yang telah kamu campuri, tetapi jika kamu belum campur dengan istrimu itu (dan sudah kamu ceraikan), maka tidak berdosa kamu (menikahinya), (dan diharamkan bagimu) istri-istri anak kandungmu (menantu), dan (diharamkan) mengumpulkan (dalam pernikahan) dua perempuan yang bersaudara, kecuali yang telah terjadi pada masa lampau. Sungguh, Allah Maha Pengampun, Maha Penyayang"},{id:24,text:"\u06de\u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u062d\u06e1\u0635\u064e\u0646\u064e\u0670\u062a\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0653\u0621\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0645\u064e\u0644\u064e\u0643\u064e\u062a\u06e1 \u0623\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u064f\u0643\u064f\u0645\u06e1\u06d6 \u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0623\u064f\u062d\u0650\u0644\u0651\u064e \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u064e\u0627 \u0648\u064e\u0631\u064e\u0627\u0653\u0621\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u06e1 \u0623\u064e\u0646 \u062a\u064e\u0628\u06e1\u062a\u064e\u063a\u064f\u0648\u0627\u0652 \u0628\u0650\u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u0650\u0643\u064f\u0645 \u0645\u0651\u064f\u062d\u06e1\u0635\u0650\u0646\u0650\u064a\u0646\u064e \u063a\u064e\u064a\u06e1\u0631\u064e \u0645\u064f\u0633\u064e\u0670\u0641\u0650\u062d\u0650\u064a\u0646\u064e\u06da \u0641\u064e\u0645\u064e\u0627 \u0671\u0633\u06e1\u062a\u064e\u0645\u06e1\u062a\u064e\u0639\u06e1\u062a\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6 \u0645\u0650\u0646\u06e1\u0647\u064f\u0646\u0651\u064e \u0641\u064e\u0640\u0654\u064e\u0627\u062a\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0623\u064f\u062c\u064f\u0648\u0631\u064e\u0647\u064f\u0646\u0651\u064e \u0641\u064e\u0631\u0650\u064a\u0636\u064e\u0629\u0657\u06da \u0648\u064e\u0644\u064e\u0627 \u062c\u064f\u0646\u064e\u0627\u062d\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a\u0645\u064e\u0627 \u062a\u064e\u0631\u064e\u0670\u0636\u064e\u064a\u06e1\u062a\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0671\u0644\u06e1\u0641\u064e\u0631\u0650\u064a\u0636\u064e\u0629\u0650\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u064b\u0627 \u062d\u064e\u0643\u0650\u064a\u0645\u0657\u0627",translation:"Dan (diharamkan juga kamu menikahi) perempuan yang bersuami, kecuali hamba sahaya perempuan (tawanan perang) yang kamu miliki187) sebagai ketetapan Allah atas kamu. Dan dihalalkan bagimu selain (perempuan-perempuan) yang demikian itu188) jika kamu berusaha dengan hartamu untuk menikahinya bukan untuk berzina. Maka karena kenikmatan yang telah kamu dapatkan dari mereka, berikanlah maskawinnya kepada mereka sebagai suatu kewajiban. Tetapi tidak mengapa jika ternyata di antara kamu telah saling merelakannya, setelah ditetapkan.189) Sungguh, Allah Maha Mengetahui, Mahabijaksana"},{id:25,text:"\u0648\u064e\u0645\u064e\u0646 \u0644\u0651\u064e\u0645\u06e1 \u064a\u064e\u0633\u06e1\u062a\u064e\u0637\u0650\u0639\u06e1 \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u0637\u064e\u0648\u06e1\u0644\u064b\u0627 \u0623\u064e\u0646 \u064a\u064e\u0646\u0643\u0650\u062d\u064e \u0671\u0644\u06e1\u0645\u064f\u062d\u06e1\u0635\u064e\u0646\u064e\u0670\u062a\u0650 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064e\u0670\u062a\u0650 \u0641\u064e\u0645\u0650\u0646 \u0645\u0651\u064e\u0627 \u0645\u064e\u0644\u064e\u0643\u064e\u062a\u06e1 \u0623\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u064f\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0641\u064e\u062a\u064e\u064a\u064e\u0670\u062a\u0650\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064e\u0670\u062a\u0650\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0628\u0650\u0625\u0650\u064a\u0645\u064e\u0670\u0646\u0650\u0643\u064f\u0645\u06da \u0628\u064e\u0639\u06e1\u0636\u064f\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u0636\u0656\u06da \u0641\u064e\u0671\u0646\u0643\u0650\u062d\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0628\u0650\u0625\u0650\u0630\u06e1\u0646\u0650 \u0623\u064e\u0647\u06e1\u0644\u0650\u0647\u0650\u0646\u0651\u064e \u0648\u064e\u0621\u064e\u0627\u062a\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0623\u064f\u062c\u064f\u0648\u0631\u064e\u0647\u064f\u0646\u0651\u064e \u0628\u0650\u0671\u0644\u06e1\u0645\u064e\u0639\u06e1\u0631\u064f\u0648\u0641\u0650 \u0645\u064f\u062d\u06e1\u0635\u064e\u0646\u064e\u0670\u062a\u064d \u063a\u064e\u064a\u06e1\u0631\u064e \u0645\u064f\u0633\u064e\u0670\u0641\u0650\u062d\u064e\u0670\u062a\u0656 \u0648\u064e\u0644\u064e\u0627 \u0645\u064f\u062a\u0651\u064e\u062e\u0650\u0630\u064e\u0670\u062a\u0650 \u0623\u064e\u062e\u06e1\u062f\u064e\u0627\u0646\u0656\u06da \u0641\u064e\u0625\u0650\u0630\u064e\u0627\u0653 \u0623\u064f\u062d\u06e1\u0635\u0650\u0646\u0651\u064e \u0641\u064e\u0625\u0650\u0646\u06e1 \u0623\u064e\u062a\u064e\u064a\u06e1\u0646\u064e \u0628\u0650\u0641\u064e\u0670\u062d\u0650\u0634\u064e\u0629\u0656 \u0641\u064e\u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0646\u0651\u064e \u0646\u0650\u0635\u06e1\u0641\u064f \u0645\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0645\u064f\u062d\u06e1\u0635\u064e\u0646\u064e\u0670\u062a\u0650 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u0650\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u0650\u0645\u064e\u0646\u06e1 \u062e\u064e\u0634\u0650\u064a\u064e \u0671\u0644\u06e1\u0639\u064e\u0646\u064e\u062a\u064e \u0645\u0650\u0646\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0623\u064e\u0646 \u062a\u064e\u0635\u06e1\u0628\u0650\u0631\u064f\u0648\u0627\u0652 \u062e\u064e\u064a\u06e1\u0631\u065e \u0644\u0651\u064e\u0643\u064f\u0645\u06e1\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u065e",translation:"Dan barang siapa di antara kamu tidak mempunyai biaya untuk menikahi perempuan merdeka yang beriman, maka (dihalalkan menikahi perempuan) yang beriman dari hamba sahaya yang kamu miliki. Allah mengetahui keimananmu. Sebagian dari kamu adalah dari sebagian yang lain (sama-sama keturunan Adam-Hawa), karena itu nikahilah mereka dengan izin tuannya dan berilah mereka maskawin yang pantas, karena mereka adalah perempuan-perempuan yang memelihara diri, bukan pezina dan bukan (pula) perempuan yang mengambil laki-laki lain sebagai piaraannya. Apabila mereka telah berumah tangga (bersuami), tetapi melakukan perbuatan keji (zina), maka (hukuman) bagi mereka setengah dari apa (hukuman) perempuan-perempuan merdeka (yang tidak bersuami). (Kebolehan menikahi hamba sahaya) itu, adalah bagi orang-orang yang takut terhadap kesulitan dalam menjaga diri (dari perbuatan zina). Tetapi jika kamu bersabar itu lebih baik bagimu. Allah Maha Pengampun, Maha Penyayang"},{id:26,text:"\u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u064a\u064e\u0647\u06e1\u062f\u0650\u064a\u064e\u0643\u064f\u0645\u06e1 \u0633\u064f\u0646\u064e\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u064a\u064e\u062a\u064f\u0648\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u065e",translation:"Allah hendak menerangkan (syariat-Nya) kepadamu, dan menunjukkan jalan-jalan (kehidupan) orang yang sebelum kamu (para nabi dan orang-orang saleh) dan Dia menerima tobatmu. Allah Maha Mengetahui, Mahabijaksana"},{id:27,text:"\u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0623\u064e\u0646 \u064a\u064e\u062a\u064f\u0648\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0648\u064e\u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0646\u064e \u0671\u0644\u0634\u0651\u064e\u0647\u064e\u0648\u064e\u0670\u062a\u0650 \u0623\u064e\u0646 \u062a\u064e\u0645\u0650\u064a\u0644\u064f\u0648\u0627\u0652 \u0645\u064e\u064a\u06e1\u0644\u064b\u0627 \u0639\u064e\u0638\u0650\u064a\u0645\u0657\u0627",translation:"Dan Allah hendak menerima tobatmu, sedang orang-orang yang mengikuti keinginannya menghendaki agar kamu berpaling sejauh-jauhnya (dari kebenaran)"},{id:28,text:"\u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0646 \u064a\u064f\u062e\u064e\u0641\u0651\u0650\u0641\u064e \u0639\u064e\u0646\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u062e\u064f\u0644\u0650\u0642\u064e \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064f \u0636\u064e\u0639\u0650\u064a\u0641\u0657\u0627",translation:"(Allah hendak memberikan keringanan kepadamu,190) karena manusia diciptakan (bersifat) lemah"},{id:29,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u062a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u064e\u0643\u064f\u0645 \u0628\u064e\u064a\u06e1\u0646\u064e\u0643\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0628\u064e\u0670\u0637\u0650\u0644\u0650 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u062a\u064e\u0643\u064f\u0648\u0646\u064e \u062a\u0650\u062c\u064e\u0670\u0631\u064e\u0629\u064b \u0639\u064e\u0646 \u062a\u064e\u0631\u064e\u0627\u0636\u0656 \u0645\u0651\u0650\u0646\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u06e1\u062a\u064f\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0643\u064f\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0628\u0650\u0643\u064f\u0645\u06e1 \u0631\u064e\u062d\u0650\u064a\u0645\u0657\u0627",translation:"Wahai orang-orang yang beriman! Janganlah kamu saling memakan harta sesamamu dengan jalan yang batil (tidak benar), kecuali dalam perdagangan yang berlaku atas dasar suka sama suka di antara kamu. Dan janganlah kamu membunuh dirimu. Sungguh, Allah Maha Penyayang kepadamu"},{id:30,text:"\u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0641\u06e1\u0639\u064e\u0644\u06e1 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0639\u064f\u062f\u06e1\u0648\u064e\u0670\u0646\u0657\u0627 \u0648\u064e\u0638\u064f\u0644\u06e1\u0645\u0657\u0627 \u0641\u064e\u0633\u064e\u0648\u06e1\u0641\u064e \u0646\u064f\u0635\u06e1\u0644\u0650\u064a\u0647\u0650 \u0646\u064e\u0627\u0631\u0657\u0627\u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u0633\u0650\u064a\u0631\u064b\u0627",translation:"Dan barang siapa berbuat demikian dengan cara melanggar hukum dan zalim, akan Kami masukkan dia ke dalam neraka. Yang demikian itu mudah bagi Allah"},{id:31,text:"\u0625\u0650\u0646 \u062a\u064e\u062c\u06e1\u062a\u064e\u0646\u0650\u0628\u064f\u0648\u0627\u0652 \u0643\u064e\u0628\u064e\u0627\u0653\u0626\u0650\u0631\u064e \u0645\u064e\u0627 \u062a\u064f\u0646\u06e1\u0647\u064e\u0648\u06e1\u0646\u064e \u0639\u064e\u0646\u06e1\u0647\u064f \u0646\u064f\u0643\u064e\u0641\u0651\u0650\u0631\u06e1 \u0639\u064e\u0646\u0643\u064f\u0645\u06e1 \u0633\u064e\u064a\u0651\u0650\u0640\u0654\u064e\u0627\u062a\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0646\u064f\u062f\u06e1\u062e\u0650\u0644\u06e1\u0643\u064f\u0645 \u0645\u0651\u064f\u062f\u06e1\u062e\u064e\u0644\u0657\u0627 \u0643\u064e\u0631\u0650\u064a\u0645\u0657\u0627",translation:"Jika kamu menjauhi dosa-dosa besar di antara dosa-dosa yang dilarang mengerjakannya, niscaya Kami hapus kesalahan-kesalahanmu dan akan Kami masukkan kamu ke tempat yang mulia (surga)"},{id:32,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u064e\u0645\u064e\u0646\u0651\u064e\u0648\u06e1\u0627\u0652 \u0645\u064e\u0627 \u0641\u064e\u0636\u0651\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0647\u0650\u06e6 \u0628\u064e\u0639\u06e1\u0636\u064e\u0643\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u06e1\u0636\u0656\u06da \u0644\u0651\u0650\u0644\u0631\u0651\u0650\u062c\u064e\u0627\u0644\u0650 \u0646\u064e\u0635\u0650\u064a\u0628\u065e \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u0671\u0643\u06e1\u062a\u064e\u0633\u064e\u0628\u064f\u0648\u0627\u0652\u06d6 \u0648\u064e\u0644\u0650\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0653\u0621\u0650 \u0646\u064e\u0635\u0650\u064a\u0628\u065e \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u0671\u0643\u06e1\u062a\u064e\u0633\u064e\u0628\u06e1\u0646\u064e\u06da \u0648\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u0650\u0646 \u0641\u064e\u0636\u06e1\u0644\u0650\u0647\u0650\u06e6\u0653\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u0657\u0627",translation:"Dan janganlah kamu iri hati terhadap karunia yang telah dilebihkan Allah kepada sebagian kamu atas sebagian yang lain. (Karena) bagi laki-laki ada bagian dari apa yang mereka usahakan, dan bagi perempuan (pun) ada bagian dari apa yang mereka usahakan. Mohonlah kepada Allah sebagian dari karunia-Nya. Sungguh, Allah Maha Mengetahui segala sesuatu"},{id:33,text:"\u0648\u064e\u0644\u0650\u0643\u064f\u0644\u0651\u0656 \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0645\u064e\u0648\u064e\u0670\u0644\u0650\u064a\u064e \u0645\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0631\u064e\u0643\u064e \u0671\u0644\u06e1\u0648\u064e\u0670\u0644\u0650\u062f\u064e\u0627\u0646\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0642\u06e1\u0631\u064e\u0628\u064f\u0648\u0646\u064e\u06da \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0639\u064e\u0642\u064e\u062f\u064e\u062a\u06e1 \u0623\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u064f\u0643\u064f\u0645\u06e1 \u0641\u064e\u0640\u0654\u064e\u0627\u062a\u064f\u0648\u0647\u064f\u0645\u06e1 \u0646\u064e\u0635\u0650\u064a\u0628\u064e\u0647\u064f\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0634\u064e\u0647\u0650\u064a\u062f\u064b\u0627",translation:"Dan untuk masing-masing (laki-laki dan perempuan) Kami telah menetapkan para ahli waris atas apa yang ditinggalkan oleh kedua orang tuanya dan karib kerabatnya. Dan orang-orang yang kamu telah bersumpah setia dengan mereka, maka berikanlah kepada mereka bagiannya. Sungguh, Allah Maha Menyaksikan segala sesuatu"},{id:34,text:"\u0671\u0644\u0631\u0651\u0650\u062c\u064e\u0627\u0644\u064f \u0642\u064e\u0648\u0651\u064e\u0640\u0670\u0645\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0653\u0621\u0650 \u0628\u0650\u0645\u064e\u0627 \u0641\u064e\u0636\u0651\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u064e\u0639\u06e1\u0636\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u06e1\u0636\u0656 \u0648\u064e\u0628\u0650\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0641\u064e\u0642\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1 \u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u0650\u0647\u0650\u0645\u06e1\u06da \u0641\u064e\u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u064f \u0642\u064e\u0670\u0646\u0650\u062a\u064e\u0670\u062a\u064c \u062d\u064e\u0670\u0641\u0650\u0638\u064e\u0670\u062a\u065e \u0644\u0651\u0650\u0644\u06e1\u063a\u064e\u064a\u06e1\u0628\u0650 \u0628\u0650\u0645\u064e\u0627 \u062d\u064e\u0641\u0650\u0638\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06da \u0648\u064e\u0671\u0644\u0651\u064e\u0640\u0670\u062a\u0650\u064a \u062a\u064e\u062e\u064e\u0627\u0641\u064f\u0648\u0646\u064e \u0646\u064f\u0634\u064f\u0648\u0632\u064e\u0647\u064f\u0646\u0651\u064e \u0641\u064e\u0639\u0650\u0638\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0648\u064e\u0671\u0647\u06e1\u062c\u064f\u0631\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0645\u064e\u0636\u064e\u0627\u062c\u0650\u0639\u0650 \u0648\u064e\u0671\u0636\u06e1\u0631\u0650\u0628\u064f\u0648\u0647\u064f\u0646\u0651\u064e\u06d6 \u0641\u064e\u0625\u0650\u0646\u06e1 \u0623\u064e\u0637\u064e\u0639\u06e1\u0646\u064e\u0643\u064f\u0645\u06e1 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0628\u06e1\u063a\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0646\u0651\u064e \u0633\u064e\u0628\u0650\u064a\u0644\u064b\u0627\u06d7 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u0650\u064a\u0651\u0657\u0627 \u0643\u064e\u0628\u0650\u064a\u0631\u0657\u0627",translation:"Laki-laki (suami) itu pelindung bagi perempuan (istri), karena Allah telah melebihkan sebagian mereka (laki-laki) atas sebagian yang lain (perempuan), dan karena mereka (laki-laki) telah memberikan nafkah dari hartanya. Maka perempuan-perempuan yang saleh, adalah mereka yang taat (kepada Allah) dan menjaga diri ketika (suaminya) tidak ada, karena Allah telah menjaga (mereka).191) Perempuan-perempuan yang kamu khawatirkan akan nusyuz,192) hendaklah kamu beri nasihat kepada mereka, tinggalkanlah mereka di tempat tidur (pisah ranjang), dan (kalau perlu) pukullah mereka. Tetapi jika mereka menaatimu, maka janganlah kamu mencari-cari alasan untuk menyusahkannya. Sungguh, Allah Mahatinggi, Mahabesar"},{id:35,text:"\u0648\u064e\u0625\u0650\u0646\u06e1 \u062e\u0650\u0641\u06e1\u062a\u064f\u0645\u06e1 \u0634\u0650\u0642\u064e\u0627\u0642\u064e \u0628\u064e\u064a\u06e1\u0646\u0650\u0647\u0650\u0645\u064e\u0627 \u0641\u064e\u0671\u0628\u06e1\u0639\u064e\u062b\u064f\u0648\u0627\u0652 \u062d\u064e\u0643\u064e\u0645\u0657\u0627 \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u0647\u06e1\u0644\u0650\u0647\u0650\u06e6 \u0648\u064e\u062d\u064e\u0643\u064e\u0645\u0657\u0627 \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u0647\u06e1\u0644\u0650\u0647\u064e\u0627\u0653 \u0625\u0650\u0646 \u064a\u064f\u0631\u0650\u064a\u062f\u064e\u0627\u0653 \u0625\u0650\u0635\u06e1\u0644\u064e\u0670\u062d\u0657\u0627 \u064a\u064f\u0648\u064e\u0641\u0651\u0650\u0642\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u064e\u0627\u0653\u06d7 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u064b\u0627 \u062e\u064e\u0628\u0650\u064a\u0631\u0657\u0627",translation:"Dan jika kamu khawatir terjadi persengketaan antara keduanya, maka kirimlah seorang juru damai dari keluarga laki-laki dan seorang juru damai dari keluarga perempuan. Jika keduanya (juru damai itu) bermaksud mengadakan perbaikan, niscaya Allah memberi taufik kepada suami-istri itu. Sungguh, Allah Maha Mengetahui, Mahateliti"},{id:36,text:"\u06de\u0648\u064e\u0671\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0634\u06e1\u0631\u0650\u0643\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6 \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627\u06d6 \u0648\u064e\u0628\u0650\u0671\u0644\u06e1\u0648\u064e\u0670\u0644\u0650\u062f\u064e\u064a\u06e1\u0646\u0650 \u0625\u0650\u062d\u06e1\u0633\u064e\u0670\u0646\u0657\u0627 \u0648\u064e\u0628\u0650\u0630\u0650\u064a \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0628\u064e\u0649\u0670 \u0648\u064e\u0671\u0644\u06e1\u064a\u064e\u062a\u064e\u0670\u0645\u064e\u0649\u0670 \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u0633\u064e\u0670\u0643\u0650\u064a\u0646\u0650 \u0648\u064e\u0671\u0644\u06e1\u062c\u064e\u0627\u0631\u0650 \u0630\u0650\u064a \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0628\u064e\u0649\u0670 \u0648\u064e\u0671\u0644\u06e1\u062c\u064e\u0627\u0631\u0650 \u0671\u0644\u06e1\u062c\u064f\u0646\u064f\u0628\u0650 \u0648\u064e\u0671\u0644\u0635\u0651\u064e\u0627\u062d\u0650\u0628\u0650 \u0628\u0650\u0671\u0644\u06e1\u062c\u064e\u0646\u06e2\u0628\u0650 \u0648\u064e\u0671\u0628\u06e1\u0646\u0650 \u0671\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u0650 \u0648\u064e\u0645\u064e\u0627 \u0645\u064e\u0644\u064e\u0643\u064e\u062a\u06e1 \u0623\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u064f\u0643\u064f\u0645\u06e1\u06d7 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0645\u064e\u0646 \u0643\u064e\u0627\u0646\u064e \u0645\u064f\u062e\u06e1\u062a\u064e\u0627\u0644\u0657\u0627 \u0641\u064e\u062e\u064f\u0648\u0631\u064b\u0627",translation:"(Dan sembahlah Allah dan janganlah kamu mempersekutukan-Nya dengan sesuatu apa pun. Dan berbuat baiklah kepada kedua orang tua, karib-kerabat, anak-anak yatim, orang-orang miskin, tetangga dekat dan tetangga jauh,193) teman sejawat, ibnu sab\u012bl194) dan hamba sahaya yang kamu miliki. Sungguh, Allah tidak menyukai orang yang sombong dan membanggakan diri"},{id:37,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0628\u06e1\u062e\u064e\u0644\u064f\u0648\u0646\u064e \u0648\u064e\u064a\u064e\u0623\u06e1\u0645\u064f\u0631\u064f\u0648\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0628\u0650\u0671\u0644\u06e1\u0628\u064f\u062e\u06e1\u0644\u0650 \u0648\u064e\u064a\u064e\u0643\u06e1\u062a\u064f\u0645\u064f\u0648\u0646\u064e \u0645\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u064e\u0649\u0670\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646 \u0641\u064e\u0636\u06e1\u0644\u0650\u0647\u0650\u06e6\u06d7 \u0648\u064e\u0623\u064e\u0639\u06e1\u062a\u064e\u062f\u06e1\u0646\u064e\u0627 \u0644\u0650\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u0657\u0627 \u0645\u0651\u064f\u0647\u0650\u064a\u0646\u0657\u0627",translation:"(yaitu) orang yang kikir, dan menyuruh orang lain berbuat kikir, dan menyembunyikan karunia yang telah diberikan Allah kepadanya. Kami telah menyediakan untuk orang-orang kafir azab yang menghinakan"},{id:38,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0646\u0641\u0650\u0642\u064f\u0648\u0646\u064e \u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u064e\u0647\u064f\u0645\u06e1 \u0631\u0650\u0626\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u0628\u0650\u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u0650\u06d7 \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0643\u064f\u0646\u0650 \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u064f \u0644\u064e\u0647\u064f\u06e5 \u0642\u064e\u0631\u0650\u064a\u0646\u0657\u0627 \u0641\u064e\u0633\u064e\u0627\u0653\u0621\u064e \u0642\u064e\u0631\u0650\u064a\u0646\u0657\u0627",translation:"Dan (juga) orang-orang yang menginfakkan hartanya karena riya` kepada orang lain (ingin dilihat dan dipuji), dan orang-orang yang tidak beriman kepada Allah dan kepada hari kemudian. Barang siapa menjadikan setan sebagai temannya, maka (ketahuilah) dia (setan itu) adalah teman yang sangat jahat"},{id:39,text:"\u0648\u064e\u0645\u064e\u0627\u0630\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0644\u064e\u0648\u06e1 \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u0650 \u0648\u064e\u0623\u064e\u0646\u0641\u064e\u0642\u064f\u0648\u0627\u0652 \u0645\u0650\u0645\u0651\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0647\u0650\u0645\u06e1 \u0639\u064e\u0644\u0650\u064a\u0645\u064b\u0627",translation:"Dan apa (keberatan) bagi mereka jika mereka beriman kepada Allah dan hari kemudian dan menginfakkan sebagian rezeki yang telah diberikan Allah kepadanya? Dan Allah Maha Mengetahui keadaan mereka"},{id:40,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064e\u0638\u06e1\u0644\u0650\u0645\u064f \u0645\u0650\u062b\u06e1\u0642\u064e\u0627\u0644\u064e \u0630\u064e\u0631\u0651\u064e\u0629\u0656\u06d6 \u0648\u064e\u0625\u0650\u0646 \u062a\u064e\u0643\u064f \u062d\u064e\u0633\u064e\u0646\u064e\u0629\u0657 \u064a\u064f\u0636\u064e\u0670\u0639\u0650\u0641\u06e1\u0647\u064e\u0627 \u0648\u064e\u064a\u064f\u0624\u06e1\u062a\u0650 \u0645\u0650\u0646 \u0644\u0651\u064e\u062f\u064f\u0646\u06e1\u0647\u064f \u0623\u064e\u062c\u06e1\u0631\u064b\u0627 \u0639\u064e\u0638\u0650\u064a\u0645\u0657\u0627",translation:"(Sungguh, Allah tidak akan menzalimi seseorang walaupun sebesar zarah,195) dan jika ada kebajikan (sekecil zarah), niscaya Allah akan melipatgandakannya dan memberikan pahala yang besar dari sisi-Nya"},{id:41,text:"\u0641\u064e\u0643\u064e\u064a\u06e1\u0641\u064e \u0625\u0650\u0630\u064e\u0627 \u062c\u0650\u0626\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u0623\u064f\u0645\u0651\u064e\u0629\u0650\u06ed \u0628\u0650\u0634\u064e\u0647\u0650\u064a\u062f\u0656 \u0648\u064e\u062c\u0650\u0626\u06e1\u0646\u064e\u0627 \u0628\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650 \u0634\u064e\u0647\u0650\u064a\u062f\u0657\u0627",translation:"Dan bagaimanakah (keadaan orang kafir nanti), jika Kami mendatangkan seorang saksi (Rasul) dari setiap umat dan Kami mendatangkan engkau (Muhammad) sebagai saksi atas mereka"},{id:42,text:"\u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u064a\u064e\u0648\u064e\u062f\u0651\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0635\u064e\u0648\u064f\u0627\u0652 \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e \u0644\u064e\u0648\u06e1 \u062a\u064f\u0633\u064e\u0648\u0651\u064e\u0649\u0670 \u0628\u0650\u0647\u0650\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064f \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0643\u06e1\u062a\u064f\u0645\u064f\u0648\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u062d\u064e\u062f\u0650\u064a\u062b\u0657\u0627",translation:"Pada hari itu, orang yang kafir dan orang yang mendurhakai Rasul (Muhammad), berharap sekiranya mereka diratakan dengan tanah (dikubur atau hancur luluh menjadi tanah), padahal mereka tidak dapat menyembunyikan sesuatu kejadian apa pun dari Allah"},{id:43,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u062a\u064e\u0642\u06e1\u0631\u064e\u0628\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0633\u064f\u0643\u064e\u0670\u0631\u064e\u0649\u0670 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0648\u064e\u0644\u064e\u0627 \u062c\u064f\u0646\u064f\u0628\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0627\u0628\u0650\u0631\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u064d \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062a\u064e\u063a\u06e1\u062a\u064e\u0633\u0650\u0644\u064f\u0648\u0627\u0652\u06da \u0648\u064e\u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645 \u0645\u0651\u064e\u0631\u06e1\u0636\u064e\u0649\u0670\u0653 \u0623\u064e\u0648\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0633\u064e\u0641\u064e\u0631\u064d \u0623\u064e\u0648\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e \u0623\u064e\u062d\u064e\u062f\u065e \u0645\u0651\u0650\u0646\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u063a\u064e\u0627\u0653\u0626\u0650\u0637\u0650 \u0623\u064e\u0648\u06e1 \u0644\u064e\u0670\u0645\u064e\u0633\u06e1\u062a\u064f\u0645\u064f \u0671\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0653\u0621\u064e \u0641\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u062c\u0650\u062f\u064f\u0648\u0627\u0652 \u0645\u064e\u0627\u0653\u0621\u0657 \u0641\u064e\u062a\u064e\u064a\u064e\u0645\u0651\u064e\u0645\u064f\u0648\u0627\u0652 \u0635\u064e\u0639\u0650\u064a\u062f\u0657\u0627 \u0637\u064e\u064a\u0651\u0650\u0628\u0657\u0627 \u0641\u064e\u0671\u0645\u06e1\u0633\u064e\u062d\u064f\u0648\u0627\u0652 \u0628\u0650\u0648\u064f\u062c\u064f\u0648\u0647\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u0643\u064f\u0645\u06e1\u06d7 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0641\u064f\u0648\u0651\u064b\u0627 \u063a\u064e\u0641\u064f\u0648\u0631\u064b\u0627",translation:"Wahai orang yang beriman! Janganlah kamu mendekati salat, ketika kamu dalam keadaan mabuk, sampai kamu sadar apa yang kamu ucapkan, dan jangan pula (kamu hampiri masjid ketika kamu) dalam keadaan junub kecuali sekedar melewati jalan saja, sebelum kamu mandi (mandi junub). Adapun jika kamu sakit atau sedang dalam perjalanan atau sehabis buang air atau kamu telah menyentuh perempuan,196) sedangkan kamu tidak mendapat air, maka bertayamumlah kamu dengan debu yang baik (suci); usaplah wajahmu dan tanganmu dengan debu itu. Sungguh, Allah Maha Pemaaf, Maha Pengampun"},{id:44,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0631\u064e \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627\u0652 \u0646\u064e\u0635\u0650\u064a\u0628\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u064a\u064e\u0634\u06e1\u062a\u064e\u0631\u064f\u0648\u0646\u064e \u0671\u0644\u0636\u0651\u064e\u0644\u064e\u0670\u0644\u064e\u0629\u064e \u0648\u064e\u064a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0623\u064e\u0646 \u062a\u064e\u0636\u0650\u0644\u0651\u064f\u0648\u0627\u0652 \u0671\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u064e",translation:"Tidakkah kamu memperhatikan orang yang telah diberi bagian Kitab (Taurat)? Mereka membeli kesesatan dan mereka menghendaki agar kamu tersesat (menyimpang) dari jalan (yang benar)"},{id:45,text:"\u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0628\u0650\u0623\u064e\u0639\u06e1\u062f\u064e\u0627\u0653\u0626\u0650\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u0650\u064a\u0651\u0657\u0627 \u0648\u064e\u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0646\u064e\u0635\u0650\u064a\u0631\u0657\u0627",translation:"Dan Allah lebih mengetahui tentang musuh-musuhmu. Cukuplah Allah menjadi pelindung dan cukuplah Allah menjadi penolong (bagimu)"},{id:46,text:"\u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064e\u0627\u062f\u064f\u0648\u0627\u0652 \u064a\u064f\u062d\u064e\u0631\u0651\u0650\u0641\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0643\u064e\u0644\u0650\u0645\u064e \u0639\u064e\u0646 \u0645\u0651\u064e\u0648\u064e\u0627\u0636\u0650\u0639\u0650\u0647\u0650\u06e6 \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0633\u064e\u0645\u0650\u0639\u06e1\u0646\u064e\u0627 \u0648\u064e\u0639\u064e\u0635\u064e\u064a\u06e1\u0646\u064e\u0627 \u0648\u064e\u0671\u0633\u06e1\u0645\u064e\u0639\u06e1 \u063a\u064e\u064a\u06e1\u0631\u064e \u0645\u064f\u0633\u06e1\u0645\u064e\u0639\u0656 \u0648\u064e\u0631\u064e\u0670\u0639\u0650\u0646\u064e\u0627 \u0644\u064e\u064a\u0651\u064e\u06e2\u0627 \u0628\u0650\u0623\u064e\u0644\u06e1\u0633\u0650\u0646\u064e\u062a\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0637\u064e\u0639\u06e1\u0646\u0657\u0627 \u0641\u0650\u064a \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u0650\u06da \u0648\u064e\u0644\u064e\u0648\u06e1 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0633\u064e\u0645\u0650\u0639\u06e1\u0646\u064e\u0627 \u0648\u064e\u0623\u064e\u0637\u064e\u0639\u06e1\u0646\u064e\u0627 \u0648\u064e\u0671\u0633\u06e1\u0645\u064e\u0639\u06e1 \u0648\u064e\u0671\u0646\u0638\u064f\u0631\u06e1\u0646\u064e\u0627 \u0644\u064e\u0643\u064e\u0627\u0646\u064e \u062e\u064e\u064a\u06e1\u0631\u0657\u0627 \u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0642\u06e1\u0648\u064e\u0645\u064e \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u0644\u0651\u064e\u0639\u064e\u0646\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0643\u064f\u0641\u06e1\u0631\u0650\u0647\u0650\u0645\u06e1 \u0641\u064e\u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u0657\u0627",translation:"(Yaitu) di antara orang Yahudi, yang mengubah perkataan dari tempat-tempatnya.197) Dan mereka berkata, \"Kami mendengar, tetapi kami tidak mau menurutinya.\" Dan (mereka mengatakan pula), \"Dengarlah,\" sedang (engkau Muhammad sebenarnya) tidak mendengar apa pun.\"198) Dan (mereka mengatakan), \"R\u0101'in\u0101\"199) dengan memutarbalikkan lidahnya dan mencela agama. Sekiranya mereka mengatakan, \"Kami mendengar dan patuh, dan dengarlah, dan perhatikanlah kami,\" tentulah itu lebih baik bagi mereka dan lebih tepat, tetapi Allah melaknat mereka, karena kekafiran mereka. Mereka tidak beriman kecuali sedikit sekali"},{id:47,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0621\u064e\u0627\u0645\u0650\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0645\u064e\u0627 \u0646\u064e\u0632\u0651\u064e\u0644\u06e1\u0646\u064e\u0627 \u0645\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u0657\u0627 \u0644\u0651\u0650\u0645\u064e\u0627 \u0645\u064e\u0639\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650 \u0623\u064e\u0646 \u0646\u0651\u064e\u0637\u06e1\u0645\u0650\u0633\u064e \u0648\u064f\u062c\u064f\u0648\u0647\u0657\u0627 \u0641\u064e\u0646\u064e\u0631\u064f\u062f\u0651\u064e\u0647\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u062f\u06e1\u0628\u064e\u0627\u0631\u0650\u0647\u064e\u0627\u0653 \u0623\u064e\u0648\u06e1 \u0646\u064e\u0644\u06e1\u0639\u064e\u0646\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0645\u064e\u0627 \u0644\u064e\u0639\u064e\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064e \u0671\u0644\u0633\u0651\u064e\u0628\u06e1\u062a\u0650\u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0623\u064e\u0645\u06e1\u0631\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0641\u06e1\u0639\u064f\u0648\u0644\u064b\u0627",translation:"Wahai orang-orang yang telah diberi Kitab! Berimanlah kamu kepada apa yang telah Kami turunkan (Alquran) yang membenarkan Kitab yang ada pada kamu, sebelum Kami mengubah wajah-wajah(mu), lalu Kami putar ke belakang 201) atau Kami laknat mereka sebagaimana Kami melaknat orang-orang (yang berbuat maksiat) pada hari Sabat (sabtu). Dan ketetapan Allah pasti berlaku"},{id:48,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064e\u063a\u06e1\u0641\u0650\u0631\u064f \u0623\u064e\u0646 \u064a\u064f\u0634\u06e1\u0631\u064e\u0643\u064e \u0628\u0650\u0647\u0650\u06e6 \u0648\u064e\u064a\u064e\u063a\u06e1\u0641\u0650\u0631\u064f \u0645\u064e\u0627 \u062f\u064f\u0648\u0646\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u0650\u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0634\u06e1\u0631\u0650\u0643\u06e1 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0642\u064e\u062f\u0650 \u0671\u0641\u06e1\u062a\u064e\u0631\u064e\u0649\u0670\u0653 \u0625\u0650\u062b\u06e1\u0645\u064b\u0627 \u0639\u064e\u0638\u0650\u064a\u0645\u064b\u0627",translation:"Sesungguhnya Allah tidak akan mengampuni (dosa) karena mempersekutukan-Nya (syirik), dan Dia mengampuni apa (dosa) yang selain (syirik) itu bagi siapa yang Dia kehendaki. Barang siapa mempersekutukan Allah, maka sungguh, dia telah berbuat dosa yang besar"},{id:49,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0631\u064e \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0632\u064e\u0643\u0651\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u06da \u0628\u064e\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064f\u0632\u064e\u0643\u0651\u0650\u064a \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0638\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0641\u064e\u062a\u0650\u064a\u0644\u064b\u0627",translation:"Tidakkah engkau memperhatikan orang-orang yang menganggap dirinya suci (orang Yahudi dan Nasrani)? Sebenarnya Allah menyucikan siapa yang Dia kehendaki dan mereka tidak dizalimi sedikit pun"},{id:50,text:"\u0671\u0646\u0638\u064f\u0631\u06e1 \u0643\u064e\u064a\u06e1\u0641\u064e \u064a\u064e\u0641\u06e1\u062a\u064e\u0631\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u0643\u064e\u0630\u0650\u0628\u064e\u06d6 \u0648\u064e\u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u062b\u06e1\u0645\u0657\u0627 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u064b\u0627",translation:"Perhatikanlah, betapa mereka mengada-adakan kebohongan terhadap Allah? Dan cukuplah perbuatan itu menjadi dosa yang nyata (bagi mereka)"},{id:51,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0631\u064e \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627\u0652 \u0646\u064e\u0635\u0650\u064a\u0628\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u06e1\u062c\u0650\u0628\u06e1\u062a\u0650 \u0648\u064e\u0671\u0644\u0637\u0651\u064e\u0640\u0670\u063a\u064f\u0648\u062a\u0650 \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650 \u0623\u064e\u0647\u06e1\u062f\u064e\u0649\u0670 \u0645\u0650\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u064b\u0627",translation:"Tidakkah engkau memperhatikan orang-orang yang diberi bagian dari Kitab (Taurat)? Mereka percaya kepada Jibt dan \u1e6c\u0101g\u016bt,202) dan mengatakan kepada orang-orang kafir (musyrik Mekkah), bahwa mereka itu lebih benar jalannya daripada orang-orang yang beriman"},{id:52,text:"\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0639\u064e\u0646\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06d6 \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0644\u06e1\u0639\u064e\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0644\u064e\u0646 \u062a\u064e\u062c\u0650\u062f\u064e \u0644\u064e\u0647\u064f\u06e5 \u0646\u064e\u0635\u0650\u064a\u0631\u064b\u0627",translation:"Mereka itulah orang-orang yang dilaknat Allah. Dan barang siapa dilaknat Allah, niscaya engkau tidak akan mendapatkan penolong baginya"},{id:53,text:"\u0623\u064e\u0645\u06e1 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0646\u064e\u0635\u0650\u064a\u0628\u065e \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0644\u06e1\u0643\u0650 \u0641\u064e\u0625\u0650\u0630\u0657\u0627 \u0644\u0651\u064e\u0627 \u064a\u064f\u0624\u06e1\u062a\u064f\u0648\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0646\u064e\u0642\u0650\u064a\u0631\u064b\u0627",translation:"Ataukah mereka mempunyai bagian dari kerajaan (kekuasaan), meskipun mereka tidak akan memberikan sedikit pun (kebajikan) kepada manusia"},{id:54,text:"\u0623\u064e\u0645\u06e1 \u064a\u064e\u062d\u06e1\u0633\u064f\u062f\u064f\u0648\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u064e\u0649\u0670\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646 \u0641\u064e\u0636\u06e1\u0644\u0650\u0647\u0650\u06e6\u06d6 \u0641\u064e\u0642\u064e\u062f\u06e1 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0627\u0653 \u0621\u064e\u0627\u0644\u064e \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0648\u064e\u0671\u0644\u06e1\u062d\u0650\u0643\u06e1\u0645\u064e\u0629\u064e \u0648\u064e\u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f\u0645 \u0645\u0651\u064f\u0644\u06e1\u0643\u064b\u0627 \u0639\u064e\u0638\u0650\u064a\u0645\u0657\u0627",translation:"ataukah mereka dengki kepada manusia (Muhammad) karena karunia yang telah diberikan Allah kepadanya? Sungguh, Kami telah memberikan Kitab dan Hikmah kepada keluarga Ibrahim, dan Kami telah memberikan kepada mereka kerajaan (kekuasaan) yang besar"},{id:55,text:"\u0641\u064e\u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0646\u06e1 \u0621\u064e\u0627\u0645\u064e\u0646\u064e \u0628\u0650\u0647\u0650\u06e6 \u0648\u064e\u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0646 \u0635\u064e\u062f\u0651\u064e \u0639\u064e\u0646\u06e1\u0647\u064f\u06da \u0648\u064e\u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0633\u064e\u0639\u0650\u064a\u0631\u064b\u0627",translation:"Maka di antara mereka (yang dengki itu), ada yang beriman kepadanya dan ada pula yang menghalangi (manusia beriman) kepadanya. Cukuplah (bagi mereka) neraka Jahanam yang menyala-nyala apinya"},{id:56,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0633\u064e\u0648\u06e1\u0641\u064e \u0646\u064f\u0635\u06e1\u0644\u0650\u064a\u0647\u0650\u0645\u06e1 \u0646\u064e\u0627\u0631\u0657\u0627 \u0643\u064f\u0644\u0651\u064e\u0645\u064e\u0627 \u0646\u064e\u0636\u0650\u062c\u064e\u062a\u06e1 \u062c\u064f\u0644\u064f\u0648\u062f\u064f\u0647\u064f\u0645 \u0628\u064e\u062f\u0651\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u062c\u064f\u0644\u064f\u0648\u062f\u064b\u0627 \u063a\u064e\u064a\u06e1\u0631\u064e\u0647\u064e\u0627 \u0644\u0650\u064a\u064e\u0630\u064f\u0648\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064e\u06d7 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0632\u0650\u064a\u0632\u064b\u0627 \u062d\u064e\u0643\u0650\u064a\u0645\u0657\u0627",translation:"Sungguh, orang-orang yang kafir kepada ayat-ayat Kami, kelak akan Kami masukkan ke dalam neraka. Setiap kali kulit mereka hangus, Kami ganti dengan kulit yang lain, agar mereka merasakan azab. Sungguh, Allah Mahaperkasa, Mahabijaksana"},{id:57,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0633\u064e\u0646\u064f\u062f\u06e1\u062e\u0650\u0644\u064f\u0647\u064f\u0645\u06e1 \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0656 \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0645\u0650\u0646 \u062a\u064e\u062d\u06e1\u062a\u0650\u0647\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u064f \u062e\u064e\u0670\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627\u0653 \u0623\u064e\u0628\u064e\u062f\u0657\u0627\u06d6 \u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627\u0653 \u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u065e \u0645\u0651\u064f\u0637\u064e\u0647\u0651\u064e\u0631\u064e\u0629\u065e\u06d6 \u0648\u064e\u0646\u064f\u062f\u06e1\u062e\u0650\u0644\u064f\u0647\u064f\u0645\u06e1 \u0638\u0650\u0644\u0651\u0657\u0627 \u0638\u064e\u0644\u0650\u064a\u0644\u064b\u0627",translation:"Adapun orang-orang yang beriman dan mengerjakan kebajikan, kelak akan Kami masukkan ke dalam surga yang mengalir di bawahnya sungai-sungai, mereka kekal di dalamnya selama-lamanya. Di sana mereka mempunyai pasangan-pasangan yang suci, dan Kami masukkan mereka ke tempat yang teduh lagi nyaman"},{id:58,text:"\u06de\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0623\u06e1\u0645\u064f\u0631\u064f\u0643\u064f\u0645\u06e1 \u0623\u064e\u0646 \u062a\u064f\u0624\u064e\u062f\u0651\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0623\u064e\u0645\u064e\u0670\u0646\u064e\u0670\u062a\u0650 \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0647\u06e1\u0644\u0650\u0647\u064e\u0627 \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062d\u064e\u0643\u064e\u0645\u06e1\u062a\u064f\u0645 \u0628\u064e\u064a\u06e1\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0623\u064e\u0646 \u062a\u064e\u062d\u06e1\u0643\u064f\u0645\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u06e1\u0639\u064e\u062f\u06e1\u0644\u0650\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0646\u0650\u0639\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u0639\u0650\u0638\u064f\u0643\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6\u0653\u06d7 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0633\u064e\u0645\u0650\u064a\u0639\u064e\u06e2\u0627 \u0628\u064e\u0635\u0650\u064a\u0631\u0657\u0627",translation:"Sungguh, Allah menyuruhmu menyampaikan amanat kepada yang berhak menerimanya, dan apabila kamu menetapkan hukum di antara manusia hendaknya kamu menetapkannya dengan adil. Sungguh, Allah sebaik-baik yang memberi pengajaran kepadamu. Sungguh, Allah Maha Mendengar, Maha Melihat"},{id:59,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0627\u0652 \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e \u0648\u064e\u0623\u064f\u0648\u0652\u0644\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0631\u0650 \u0645\u0650\u0646\u0643\u064f\u0645\u06e1\u06d6 \u0641\u064e\u0625\u0650\u0646 \u062a\u064e\u0646\u064e\u0670\u0632\u064e\u0639\u06e1\u062a\u064f\u0645\u06e1 \u0641\u0650\u064a \u0634\u064e\u064a\u06e1\u0621\u0656 \u0641\u064e\u0631\u064f\u062f\u0651\u064f\u0648\u0647\u064f \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0650 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u0650\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062e\u064e\u064a\u06e1\u0631\u065e \u0648\u064e\u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064f \u062a\u064e\u0623\u06e1\u0648\u0650\u064a\u0644\u064b\u0627",translation:"Wahai orang-orang yang beriman! Taatilah Allah dan taatilah Rasul (Muhammad), dan Ulil Amri (pemegang kekuasaan)203) di antara kamu. Kemudian, jika kamu berbeda pendapat tentang sesuatu, maka kembalikanlah kepada Allah (Alquran) dan Rasul (sunahnya), jika kamu beriman kepada Allah dan hari kemudian. Yang demikian itu, lebih utama (bagimu) dan lebih baik akibatnya"},{id:60,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0631\u064e \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0632\u06e1\u0639\u064f\u0645\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0645\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064e \u064a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0623\u064e\u0646 \u064a\u064e\u062a\u064e\u062d\u064e\u0627\u0643\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0637\u0651\u064e\u0640\u0670\u063a\u064f\u0648\u062a\u0650 \u0648\u064e\u0642\u064e\u062f\u06e1 \u0623\u064f\u0645\u0650\u0631\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646 \u064a\u064e\u0643\u06e1\u0641\u064f\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u064f \u0623\u064e\u0646 \u064a\u064f\u0636\u0650\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u0636\u064e\u0644\u064e\u0670\u0644\u064e\u06e2\u0627 \u0628\u064e\u0639\u0650\u064a\u062f\u0657\u0627",translation:"Tidakkah engkau (Muhammad) memperhatikan orang-orang yang mengaku bahwa mereka telah beriman kepada apa yang diturunkan kepadamu dan kepada apa yang diturunkan sebelummu? Tetapi mereka204) masih menginginkan ketetapan hukum kepada Tagut, padahal mereka telah diperintahkan untuk mengingkari Tagut itu. Dan setan bermaksud menyesatkan mereka (dengan) kesesatan yang sejauh-jauhnya"},{id:61,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0648\u06e1\u0627\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0650 \u0631\u064e\u0623\u064e\u064a\u06e1\u062a\u064e \u0671\u0644\u06e1\u0645\u064f\u0646\u064e\u0670\u0641\u0650\u0642\u0650\u064a\u0646\u064e \u064a\u064e\u0635\u064f\u062f\u0651\u064f\u0648\u0646\u064e \u0639\u064e\u0646\u0643\u064e \u0635\u064f\u062f\u064f\u0648\u062f\u0657\u0627",translation:"Dan apabila dikatakan kepada mereka, \"Marilah (patuh) kepada apa yang diturunkan Allah dan (patuh) kepada Rasul,\" (niscaya) engkau (Muhammad) melihat orang munafik menghalangi dengan keras darimu"},{id:62,text:"\u0641\u064e\u0643\u064e\u064a\u06e1\u0641\u064e \u0625\u0650\u0630\u064e\u0627\u0653 \u0623\u064e\u0635\u064e\u0670\u0628\u064e\u062a\u06e1\u0647\u064f\u0645 \u0645\u0651\u064f\u0635\u0650\u064a\u0628\u064e\u0629\u064f\u06e2 \u0628\u0650\u0645\u064e\u0627 \u0642\u064e\u062f\u0651\u064e\u0645\u064e\u062a\u06e1 \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u0647\u0650\u0645\u06e1 \u062b\u064f\u0645\u0651\u064e \u062c\u064e\u0627\u0653\u0621\u064f\u0648\u0643\u064e \u064a\u064e\u062d\u06e1\u0644\u0650\u0641\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0646\u06e1 \u0623\u064e\u0631\u064e\u062f\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0625\u0650\u062d\u06e1\u0633\u064e\u0670\u0646\u0657\u0627 \u0648\u064e\u062a\u064e\u0648\u06e1\u0641\u0650\u064a\u0642\u064b\u0627",translation:"Maka bagaimana halnya apabila (kelak) musibah menimpa mereka (orang munafik) di sebabkan perbuatan tangannya sendiri, kemudian mereka datang kepadamu (Muhammad) sambil bersumpah, \"Demi Allah, kami sekali-kali tidak menghendaki selain kebaikan dan kedamaian"},{id:63,text:"\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u06e1 \u0641\u064e\u0623\u064e\u0639\u06e1\u0631\u0650\u0636\u06e1 \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0648\u064e\u0639\u0650\u0638\u06e1\u0647\u064f\u0645\u06e1 \u0648\u064e\u0642\u064f\u0644 \u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0653 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u06e1 \u0642\u064e\u0648\u06e1\u0644\u064e\u06e2\u0627 \u0628\u064e\u0644\u0650\u064a\u063a\u0657\u0627",translation:"Mereka itu adalah orang-orang yang (sesungguhnya) Allah mengetahui apa yang ada di dalam hatinya. Karena itu berpalinglah kamu dari mereka, dan berilah mereka nasihat, dan katakanlah kepada mereka perkataan yang membekas pada jiwanya"},{id:64,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646 \u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0644\u0650\u064a\u064f\u0637\u064e\u0627\u0639\u064e \u0628\u0650\u0625\u0650\u0630\u06e1\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0648\u064e\u0644\u064e\u0648\u06e1 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0625\u0650\u0630 \u0638\u0651\u064e\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u06e1 \u062c\u064e\u0627\u0653\u0621\u064f\u0648\u0643\u064e \u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u063a\u06e1\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0671\u0633\u06e1\u062a\u064e\u063a\u06e1\u0641\u064e\u0631\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064f \u0644\u064e\u0648\u064e\u062c\u064e\u062f\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u062a\u064e\u0648\u0651\u064e\u0627\u0628\u0657\u0627 \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0657\u0627",translation:"(Dan Kami tidak mengutus seorang rasul melainkan untuk ditaati dengan izin Allah. Dan sungguh, sekiranya mereka setelah menzalimi dirinya205) datang kepadamu (Muhammad), lalu memohon ampunan kepada Allah, dan Rasul pun memohonkan ampunan untuk mereka, niscaya mereka mendapati Allah Maha Penerima tobat, Maha Penyayang"},{id:65,text:"\u0641\u064e\u0644\u064e\u0627 \u0648\u064e\u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064f\u062d\u064e\u0643\u0651\u0650\u0645\u064f\u0648\u0643\u064e \u0641\u0650\u064a\u0645\u064e\u0627 \u0634\u064e\u062c\u064e\u0631\u064e \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1 \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0627 \u064a\u064e\u062c\u0650\u062f\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0653 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u06e1 \u062d\u064e\u0631\u064e\u062c\u0657\u0627 \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u0642\u064e\u0636\u064e\u064a\u06e1\u062a\u064e \u0648\u064e\u064a\u064f\u0633\u064e\u0644\u0651\u0650\u0645\u064f\u0648\u0627\u0652 \u062a\u064e\u0633\u06e1\u0644\u0650\u064a\u0645\u0657\u0627",translation:"Maka demi Tuhanmu, mereka tidak beriman sebelum mereka menjadikan engkau (Muhammad) sebagai hakim dalam perkara yang mereka perselisihkan, (sehingga) kemudian tidak ada rasa keberatan dalam hati mereka terhadap putusan yang engkau berikan, dan mereka menerima dengan sepenuhnya"},{id:66,text:"\u0648\u064e\u0644\u064e\u0648\u06e1 \u0623\u064e\u0646\u0651\u064e\u0627 \u0643\u064e\u062a\u064e\u0628\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0623\u064e\u0646\u0650 \u0671\u0642\u06e1\u062a\u064f\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u0648\u0650 \u0671\u062e\u06e1\u0631\u064f\u062c\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u062f\u0650\u064a\u064e\u0670\u0631\u0650\u0643\u064f\u0645 \u0645\u0651\u064e\u0627 \u0641\u064e\u0639\u064e\u0644\u064f\u0648\u0647\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u065e \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0644\u064e\u0648\u06e1 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0641\u064e\u0639\u064e\u0644\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u064a\u064f\u0648\u0639\u064e\u0638\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u0650\u06e6 \u0644\u064e\u0643\u064e\u0627\u0646\u064e \u062e\u064e\u064a\u06e1\u0631\u0657\u0627 \u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0634\u064e\u062f\u0651\u064e \u062a\u064e\u062b\u06e1\u0628\u0650\u064a\u062a\u0657\u0627",translation:"Dan sekalipun telah Kami perintahkan kepada mereka, \"Bunuhlah dirimu atau keluarlah kamu dari kampung halamanmu,\" ternyata mereka tidak akan melakukannya, kecuali sebagian kecil dari mereka. Dan sekiranya mereka benar-benar melaksanakan perintah yang diberikan, niscaya itu lebih baik bagi mereka dan lebih menguatkan (iman mereka)"},{id:67,text:"\u0648\u064e\u0625\u0650\u0630\u0657\u0627 \u0644\u0651\u064e\u0623\u0653\u062a\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0644\u0651\u064e\u062f\u064f\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u062c\u06e1\u0631\u064b\u0627 \u0639\u064e\u0638\u0650\u064a\u0645\u0657\u0627",translation:"dan dengan demikian, pasti Kami berikan kepada mereka pahala yang besar dari sisi Kami"},{id:68,text:"\u0648\u064e\u0644\u064e\u0647\u064e\u062f\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0635\u0650\u0631\u064e\u0670\u0637\u0657\u0627 \u0645\u0651\u064f\u0633\u06e1\u062a\u064e\u0642\u0650\u064a\u0645\u0657\u0627",translation:"dan pasti Kami tunjukan kepada mereka jalan yang lurus"},{id:69,text:"\u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0637\u0650\u0639\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e \u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0645\u064e\u0639\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u0646\u06e1\u0639\u064e\u0645\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650\u0640\u06e7\u0646\u064e \u0648\u064e\u0671\u0644\u0635\u0651\u0650\u062f\u0651\u0650\u064a\u0642\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u0634\u0651\u064f\u0647\u064e\u062f\u064e\u0627\u0653\u0621\u0650 \u0648\u064e\u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u0650\u064a\u0646\u064e\u06da \u0648\u064e\u062d\u064e\u0633\u064f\u0646\u064e \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0631\u064e\u0641\u0650\u064a\u0642\u0657\u0627",translation:"Dan barang siapa menaati Allah dan Rasul (Muhammad), maka mereka itu akan bersama-sama dengan orang yang diberikan nikmat oleh Allah, (yaitu) para nabi, para pecinta kebenaran, orang-orang yang mati syahid dan orang-orang saleh. Mereka itulah teman yang sebaik-baiknya"},{id:70,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0671\u0644\u06e1\u0641\u064e\u0636\u06e1\u0644\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0648\u064e\u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u0650\u064a\u0645\u0657\u0627",translation:"Yang demikian itu adalah karunia dari Allah, dan cukuplah Allah yang Maha Mengetahui"},{id:71,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u062e\u064f\u0630\u064f\u0648\u0627\u0652 \u062d\u0650\u0630\u06e1\u0631\u064e\u0643\u064f\u0645\u06e1 \u0641\u064e\u0671\u0646\u0641\u0650\u0631\u064f\u0648\u0627\u0652 \u062b\u064f\u0628\u064e\u0627\u062a\u064d \u0623\u064e\u0648\u0650 \u0671\u0646\u0641\u0650\u0631\u064f\u0648\u0627\u0652 \u062c\u064e\u0645\u0650\u064a\u0639\u0657\u0627",translation:"Wahai orang-orang yang beriman! Bersiap-siagalah kamu, dan majulah (ke medan pertempuran) secara berkelompok, atau majulah bersama-sama (serentak)"},{id:72,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u0644\u064e\u0645\u064e\u0646 \u0644\u0651\u064e\u064a\u064f\u0628\u064e\u0637\u0651\u0650\u0626\u064e\u0646\u0651\u064e \u0641\u064e\u0625\u0650\u0646\u06e1 \u0623\u064e\u0635\u064e\u0670\u0628\u064e\u062a\u06e1\u0643\u064f\u0645 \u0645\u0651\u064f\u0635\u0650\u064a\u0628\u064e\u0629\u065e \u0642\u064e\u0627\u0644\u064e \u0642\u064e\u062f\u06e1 \u0623\u064e\u0646\u06e1\u0639\u064e\u0645\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0651\u064e \u0625\u0650\u0630\u06e1 \u0644\u064e\u0645\u06e1 \u0623\u064e\u0643\u064f\u0646 \u0645\u0651\u064e\u0639\u064e\u0647\u064f\u0645\u06e1 \u0634\u064e\u0647\u0650\u064a\u062f\u0657\u0627",translation:"Dan sesungguhnya di antara kamu pasti ada orang yang sangat enggan (ke medan pertempuran). Lalu jika kamu ditimpa musibah dia berkata, \"Sungguh, Allah telah memberikan nikmat kepadaku karena aku tidak ikut berperang bersama mereka"},{id:73,text:"\u0648\u064e\u0644\u064e\u0626\u0650\u0646\u06e1 \u0623\u064e\u0635\u064e\u0670\u0628\u064e\u0643\u064f\u0645\u06e1 \u0641\u064e\u0636\u06e1\u0644\u065e \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064e\u0646\u0651\u064e \u0643\u064e\u0623\u064e\u0646 \u0644\u0651\u064e\u0645\u06e1 \u062a\u064e\u0643\u064f\u0646\u06e2 \u0628\u064e\u064a\u06e1\u0646\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u06e5 \u0645\u064e\u0648\u064e\u062f\u0651\u064e\u0629\u065e \u064a\u064e\u0670\u0644\u064e\u064a\u06e1\u062a\u064e\u0646\u0650\u064a \u0643\u064f\u0646\u062a\u064f \u0645\u064e\u0639\u064e\u0647\u064f\u0645\u06e1 \u0641\u064e\u0623\u064e\u0641\u064f\u0648\u0632\u064e \u0641\u064e\u0648\u06e1\u0632\u064b\u0627 \u0639\u064e\u0638\u0650\u064a\u0645\u0657\u0627",translation:"Dan sungguh, jika kamu mendapat karunia (kemenangan) dari Allah, tentulah dia mengatakan seakan-akan belum pernah ada hubungan kasih sayang antara kamu dengan dia, \"Wahai, sekiranya aku bersama mereka, tentu aku akan memperoleh kemenangan yang agung (pula)"},{id:74,text:"\u06de\u0641\u064e\u0644\u06e1\u064a\u064f\u0642\u064e\u0670\u062a\u0650\u0644\u06e1 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0634\u06e1\u0631\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u064e \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0628\u0650\u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650\u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0642\u064e\u0670\u062a\u0650\u0644\u06e1 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u064a\u064f\u0642\u06e1\u062a\u064e\u0644\u06e1 \u0623\u064e\u0648\u06e1 \u064a\u064e\u063a\u06e1\u0644\u0650\u0628\u06e1 \u0641\u064e\u0633\u064e\u0648\u06e1\u0641\u064e \u0646\u064f\u0624\u06e1\u062a\u0650\u064a\u0647\u0650 \u0623\u064e\u062c\u06e1\u0631\u064b\u0627 \u0639\u064e\u0638\u0650\u064a\u0645\u0657\u0627",translation:"Karena itu, hendaklah orang-orang yang menjual kehidupan dunia untuk (kehidupan) akhirat berperang di jalan Allah. Dan barang siapa berperang di jalan Allah, lalu gugur atau memperoleh kemenangan maka akan Kami berikan pahala yang besar kepadanya"},{id:75,text:"\u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0644\u064e\u0627 \u062a\u064f\u0642\u064e\u0670\u062a\u0650\u0644\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0633\u06e1\u062a\u064e\u0636\u06e1\u0639\u064e\u0641\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0631\u0651\u0650\u062c\u064e\u0627\u0644\u0650 \u0648\u064e\u0671\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0653\u0621\u0650 \u0648\u064e\u0671\u0644\u06e1\u0648\u0650\u0644\u06e1\u062f\u064e\u0670\u0646\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627\u0653 \u0623\u064e\u062e\u06e1\u0631\u0650\u062c\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646\u06e1 \u0647\u064e\u0670\u0630\u0650\u0647\u0650 \u0671\u0644\u06e1\u0642\u064e\u0631\u06e1\u064a\u064e\u0629\u0650 \u0671\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650 \u0623\u064e\u0647\u06e1\u0644\u064f\u0647\u064e\u0627 \u0648\u064e\u0671\u062c\u06e1\u0639\u064e\u0644 \u0644\u0651\u064e\u0646\u064e\u0627 \u0645\u0650\u0646 \u0644\u0651\u064e\u062f\u064f\u0646\u0643\u064e \u0648\u064e\u0644\u0650\u064a\u0651\u0657\u0627 \u0648\u064e\u0671\u062c\u06e1\u0639\u064e\u0644 \u0644\u0651\u064e\u0646\u064e\u0627 \u0645\u0650\u0646 \u0644\u0651\u064e\u062f\u064f\u0646\u0643\u064e \u0646\u064e\u0635\u0650\u064a\u0631\u064b\u0627",translation:"Dan mengapa kamu tidak mau berperang di jalan Allah dan (membela) orang yang lemah, baik laki-laki, perempuan maupun anak-anak yang berdoa, \"Ya Tuhan kami, keluarkanlah kami dari negeri ini (Mekkah) yang penduduknya zalim. Berilah kami pelindung dari sisi-Mu, dan berilah kami penolong dari sisi-Mu"},{id:76,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u064a\u064f\u0642\u064e\u0670\u062a\u0650\u0644\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u064a\u064f\u0642\u064e\u0670\u062a\u0650\u0644\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0637\u0651\u064e\u0640\u0670\u063a\u064f\u0648\u062a\u0650 \u0641\u064e\u0642\u064e\u0670\u062a\u0650\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0648\u06e1\u0644\u0650\u064a\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u0650\u06d6 \u0625\u0650\u0646\u0651\u064e \u0643\u064e\u064a\u06e1\u062f\u064e \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u0650 \u0643\u064e\u0627\u0646\u064e \u0636\u064e\u0639\u0650\u064a\u0641\u064b\u0627",translation:"Orang-orang yang beriman, mereka berperang di jalan Allah, dan orang-orang yang kafir berperang di jalan Tagut, maka perangilah kawan-kawan setan itu, (karena) sesungguhnya tipu daya setan itu lemah"},{id:77,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0631\u064e \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0643\u064f\u0641\u0651\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0642\u0650\u064a\u0645\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u0621\u064e\u0627\u062a\u064f\u0648\u0627\u0652 \u0671\u0644\u0632\u0651\u064e\u0643\u064e\u0648\u0670\u0629\u064e \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0643\u064f\u062a\u0650\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u064f \u0671\u0644\u06e1\u0642\u0650\u062a\u064e\u0627\u0644\u064f \u0625\u0650\u0630\u064e\u0627 \u0641\u064e\u0631\u0650\u064a\u0642\u065e \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u064a\u064e\u062e\u06e1\u0634\u064e\u0648\u06e1\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0643\u064e\u062e\u064e\u0634\u06e1\u064a\u064e\u0629\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0648\u06e1 \u0623\u064e\u0634\u064e\u062f\u0651\u064e \u062e\u064e\u0634\u06e1\u064a\u064e\u0629\u0657\u06da \u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0644\u0650\u0645\u064e \u0643\u064e\u062a\u064e\u0628\u06e1\u062a\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0642\u0650\u062a\u064e\u0627\u0644\u064e \u0644\u064e\u0648\u06e1\u0644\u064e\u0627\u0653 \u0623\u064e\u062e\u0651\u064e\u0631\u06e1\u062a\u064e\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u062c\u064e\u0644\u0656 \u0642\u064e\u0631\u0650\u064a\u0628\u0656\u06d7 \u0642\u064f\u0644\u06e1 \u0645\u064e\u062a\u064e\u0670\u0639\u064f \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u065e \u0648\u064e\u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u064f \u062e\u064e\u064a\u06e1\u0631\u065e \u0644\u0651\u0650\u0645\u064e\u0646\u0650 \u0671\u062a\u0651\u064e\u0642\u064e\u0649\u0670 \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0638\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0641\u064e\u062a\u0650\u064a\u0644\u064b\u0627",translation:"(Tidakkah engkau memperhatikan orang-orang yang dikatakan kepada mereka,206) \"Tahanlah tanganmu (dari berperang), laksanakanlah salat dan tunaikanlah zakat!\" Ketika mereka diwajibkan berperang, tiba-tiba sebagian mereka (golongan munafik) takut kepada manusia (musuh), seperti takutnya kepada Allah, bahkan lebih takut (dari itu). Mereka berkata, \"Ya Tuhan kami, mengapa Engkau wajibkan berperang kepada kami? Mengapa tidak Engkau tunda (kewajiban berperang) kepada kami beberapa waktu lagi?\" Katakanlah, \"Kesenangan di dunia ini hanya sedikit dan di akhirat itu lebih baik bagi orang-orang yang bertakwa (mendapat pahala turut berperang) dan kamu tidak akan dizalimi sedikit pun"},{id:78,text:"\u0623\u064e\u064a\u06e1\u0646\u064e\u0645\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u064a\u064f\u062f\u06e1\u0631\u0650\u0643\u0643\u0651\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u064f \u0648\u064e\u0644\u064e\u0648\u06e1 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0641\u0650\u064a \u0628\u064f\u0631\u064f\u0648\u062c\u0656 \u0645\u0651\u064f\u0634\u064e\u064a\u0651\u064e\u062f\u064e\u0629\u0656\u06d7 \u0648\u064e\u0625\u0650\u0646 \u062a\u064f\u0635\u0650\u0628\u06e1\u0647\u064f\u0645\u06e1 \u062d\u064e\u0633\u064e\u0646\u064e\u0629\u065e \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627\u0652 \u0647\u064e\u0670\u0630\u0650\u0647\u0650\u06e6 \u0645\u0650\u0646\u06e1 \u0639\u0650\u0646\u062f\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0648\u064e\u0625\u0650\u0646 \u062a\u064f\u0635\u0650\u0628\u06e1\u0647\u064f\u0645\u06e1 \u0633\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u065e \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627\u0652 \u0647\u064e\u0670\u0630\u0650\u0647\u0650\u06e6 \u0645\u0650\u0646\u06e1 \u0639\u0650\u0646\u062f\u0650\u0643\u064e\u06da \u0642\u064f\u0644\u06e1 \u0643\u064f\u0644\u0651\u065e \u0645\u0651\u0650\u0646\u06e1 \u0639\u0650\u0646\u062f\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0641\u064e\u0645\u064e\u0627\u0644\u0650 \u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650 \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u0650 \u0644\u064e\u0627 \u064a\u064e\u0643\u064e\u0627\u062f\u064f\u0648\u0646\u064e \u064a\u064e\u0641\u06e1\u0642\u064e\u0647\u064f\u0648\u0646\u064e \u062d\u064e\u062f\u0650\u064a\u062b\u0657\u0627",translation:"Dimanapun kamu berada, kematian akan mendapatkan kamu, kendatipun kamu berada di dalam benteng yang tinggi dan kokoh. Jika mereka memperoleh kebaikan, mereka mengatakan, \"Ini dari sisi Allah\", dan jika mereka ditimpa suatu keburukan mereka mengatakan, \"Ini dari engkau (Muhammad).\" Katakanlah, \"Semuanya (datang) dari sisi Allah.\" Maka mengapa orang-orang itu (orang-orang munafik) hampir-hampir tidak memahami pembicaraan (sedikit pun)"},{id:79,text:"\u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u0635\u064e\u0627\u0628\u064e\u0643\u064e \u0645\u0650\u0646\u06e1 \u062d\u064e\u0633\u064e\u0646\u064e\u0629\u0656 \u0641\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0635\u064e\u0627\u0628\u064e\u0643\u064e \u0645\u0650\u0646 \u0633\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u0656 \u0641\u064e\u0645\u0650\u0646 \u0646\u0651\u064e\u0641\u06e1\u0633\u0650\u0643\u064e\u06da \u0648\u064e\u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0670\u0643\u064e \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0631\u064e\u0633\u064f\u0648\u0644\u0657\u0627\u06da \u0648\u064e\u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0634\u064e\u0647\u0650\u064a\u062f\u0657\u0627",translation:"Kebajikan apa pun yang kamu peroleh, adalah dari sisi Allah, dan keburukan apa pun yang menimpamu, itu dari (kesalahan) dirimu sendiri. Kami mengutusmu (Muhammad) menjadi Rasul kepada (seluruh) manusia. Dan cukuplah Allah yang menjadi saksi"},{id:80,text:"\u0645\u0651\u064e\u0646 \u064a\u064f\u0637\u0650\u0639\u0650 \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e \u0641\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u0637\u064e\u0627\u0639\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e\u06d6 \u0648\u064e\u0645\u064e\u0646 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649\u0670 \u0641\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0670\u0643\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u062d\u064e\u0641\u0650\u064a\u0638\u0657\u0627",translation:"Barang siapa menaati Rasul (Muhammad), maka sesungguhnya dia telah menaati Allah. Dan barang siapa berpaling (dari ketaatan itu), maka (ketahuilah) Kami tidak mengutusmu (Muhammad) untuk menjadi pemelihara mereka"},{id:81,text:"\u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0637\u064e\u0627\u0639\u064e\u0629\u065e \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0628\u064e\u0631\u064e\u0632\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1 \u0639\u0650\u0646\u062f\u0650\u0643\u064e \u0628\u064e\u064a\u0651\u064e\u062a\u064e \u0637\u064e\u0627\u0653\u0626\u0650\u0641\u064e\u0629\u065e \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u063a\u064e\u064a\u06e1\u0631\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062a\u064e\u0642\u064f\u0648\u0644\u064f\u06d6 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0643\u06e1\u062a\u064f\u0628\u064f \u0645\u064e\u0627 \u064a\u064f\u0628\u064e\u064a\u0651\u0650\u062a\u064f\u0648\u0646\u064e\u06d6 \u0641\u064e\u0623\u064e\u0639\u06e1\u0631\u0650\u0636\u06e1 \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0648\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u06e1 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0648\u064e\u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0643\u0650\u064a\u0644\u064b\u0627",translation:"Dan mereka (orang-orang munafik) mengatakan, \"(Kewajiban kami hanyalah) taat.\" Tetapi, apabila mereka telah pergi dari sisimu (Muhammad), sebagian dari mereka mengatur siasat di malam hari (mengambil keputusan) lain dari yang telah mereka katakan tadi. Allah mencatat siasat yang mereka atur di malam hari itu, maka berpalinglah dari mereka dan bertawakallah kepada Allah. Cukuplah Allah yang menjadi pelindung"},{id:82,text:"\u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u062a\u064e\u062f\u064e\u0628\u0651\u064e\u0631\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u064e\u06da \u0648\u064e\u0644\u064e\u0648\u06e1 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u06e1 \u0639\u0650\u0646\u062f\u0650 \u063a\u064e\u064a\u06e1\u0631\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0648\u064e\u062c\u064e\u062f\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0647\u0650 \u0671\u062e\u06e1\u062a\u0650\u0644\u064e\u0670\u0641\u0657\u0627 \u0643\u064e\u062b\u0650\u064a\u0631\u0657\u0627",translation:"Maka tidakkah mereka menghayati (mendalami) Alquran? Sekiranya (Alquran) itu bukan dari Allah, pastilah mereka menemukan banyak hal yang bertentangan di dalamnya"},{id:83,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u0645\u06e1\u0631\u065e \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0646\u0650 \u0623\u064e\u0648\u0650 \u0671\u0644\u06e1\u062e\u064e\u0648\u06e1\u0641\u0650 \u0623\u064e\u0630\u064e\u0627\u0639\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u0644\u064e\u0648\u06e1 \u0631\u064e\u062f\u0651\u064f\u0648\u0647\u064f \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0650 \u0648\u064e\u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064f\u0648\u0652\u0644\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0631\u0650 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0644\u064e\u0639\u064e\u0644\u0650\u0645\u064e\u0647\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0633\u06e1\u062a\u064e\u0646\u06e2\u0628\u0650\u0637\u064f\u0648\u0646\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1\u06d7 \u0648\u064e\u0644\u064e\u0648\u06e1\u0644\u064e\u0627 \u0641\u064e\u0636\u06e1\u0644\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0648\u064e\u0631\u064e\u062d\u06e1\u0645\u064e\u062a\u064f\u0647\u064f\u06e5 \u0644\u064e\u0671\u062a\u0651\u064e\u0628\u064e\u0639\u06e1\u062a\u064f\u0645\u064f \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u0657\u0627",translation:"Dan apabila sampai kepada mereka suatu berita tentang keamanan ataupun ketakutan, mereka (langsung) menyiarkannya. (Padahal) apabila mereka menyerahkannya kepada Rasul dan Ulil Amri 208) di antara mereka, tentulah orang-orang yang ingin mengetahui kebenarannya (akan dapat) mengetahuinya (secara resmi) dari mereka (Rasul dan Ulil Amri).209) Sekiranya bukan karena karunia dan rahmat Allah kepadamu, tentulah kamu mengikut setan, kecuali sebagian kecil saja (di antara kamu)"},{id:84,text:"\u0641\u064e\u0642\u064e\u0670\u062a\u0650\u0644\u06e1 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0627 \u062a\u064f\u0643\u064e\u0644\u0651\u064e\u0641\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0646\u064e\u0641\u06e1\u0633\u064e\u0643\u064e\u06da \u0648\u064e\u062d\u064e\u0631\u0651\u0650\u0636\u0650 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e\u06d6 \u0639\u064e\u0633\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0646 \u064a\u064e\u0643\u064f\u0641\u0651\u064e \u0628\u064e\u0623\u06e1\u0633\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0634\u064e\u062f\u0651\u064f \u0628\u064e\u0623\u06e1\u0633\u0657\u0627 \u0648\u064e\u0623\u064e\u0634\u064e\u062f\u0651\u064f \u062a\u064e\u0646\u0643\u0650\u064a\u0644\u0657\u0627",translation:"Maka berperanglah engkau (Muhammad) di jalan Allah, engkau tidaklah dibebani melainkan atas dirimu sendiri.210) Kobarkanlah (semangat) orang-orang beriman (untuk berperang). Mudah-mudahan Allah menolak (mematahkan) serangan orang-orang yang kafir itu. Allah sangat besar kekuatan(-Nya) dan sangat keras siksa(-Nya)"},{id:85,text:"\u0645\u0651\u064e\u0646 \u064a\u064e\u0634\u06e1\u0641\u064e\u0639\u06e1 \u0634\u064e\u0641\u064e\u0670\u0639\u064e\u0629\u064b \u062d\u064e\u0633\u064e\u0646\u064e\u0629\u0657 \u064a\u064e\u0643\u064f\u0646 \u0644\u0651\u064e\u0647\u064f\u06e5 \u0646\u064e\u0635\u0650\u064a\u0628\u065e \u0645\u0651\u0650\u0646\u06e1\u0647\u064e\u0627\u06d6 \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0634\u06e1\u0641\u064e\u0639\u06e1 \u0634\u064e\u0641\u064e\u0670\u0639\u064e\u0629\u0657 \u0633\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u0657 \u064a\u064e\u0643\u064f\u0646 \u0644\u0651\u064e\u0647\u064f\u06e5 \u0643\u0650\u0641\u06e1\u0644\u065e \u0645\u0651\u0650\u0646\u06e1\u0647\u064e\u0627\u06d7 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0645\u0651\u064f\u0642\u0650\u064a\u062a\u0657\u0627",translation:"Barang siapa memberi pertolongan dengan pertolongan yang baik, niscaya dia akan memperoleh bagian (pahala)-nya. Dan barang siapa memberi pertolongan dengan pertolongan yang buruk, niscaya dia akan memikul bagian dari (dosa)nya. Allah Maha Kuasa atas segala sesuatu"},{id:86,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062d\u064f\u064a\u0651\u0650\u064a\u062a\u064f\u0645 \u0628\u0650\u062a\u064e\u062d\u0650\u064a\u0651\u064e\u0629\u0656 \u0641\u064e\u062d\u064e\u064a\u0651\u064f\u0648\u0627\u0652 \u0628\u0650\u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064e \u0645\u0650\u0646\u06e1\u0647\u064e\u0627\u0653 \u0623\u064e\u0648\u06e1 \u0631\u064f\u062f\u0651\u064f\u0648\u0647\u064e\u0627\u0653\u06d7 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u064d \u062d\u064e\u0633\u0650\u064a\u0628\u064b\u0627",translation:"Dan apabila kamu dihormati dengan suatu (salam) penghormatan, maka balaslah penghormatan itu dengan yang lebih baik, atau balaslah (penghormatan itu, yang sepadan) dengannya. Sungguh, Allah memperhitungkan segala sesuatu"},{id:87,text:"\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e\u06da \u0644\u064e\u064a\u064e\u062c\u06e1\u0645\u064e\u0639\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u0644\u064e\u0627 \u0631\u064e\u064a\u06e1\u0628\u064e \u0641\u0650\u064a\u0647\u0650\u06d7 \u0648\u064e\u0645\u064e\u0646\u06e1 \u0623\u064e\u0635\u06e1\u062f\u064e\u0642\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u064e\u062f\u0650\u064a\u062b\u0657\u0627",translation:"Allah, tidak ada tuhan selain Dia. Dia pasti akan mengumpulkan kamu pada hari Kiamat yang tidak diragukan kejadiannya. Siapakah yang lebih benar perkataan(nya) daripada Allah"},{id:88,text:"\u06de\u0641\u064e\u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0645\u064f\u0646\u064e\u0670\u0641\u0650\u0642\u0650\u064a\u0646\u064e \u0641\u0650\u0626\u064e\u062a\u064e\u064a\u06e1\u0646\u0650 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0631\u06e1\u0643\u064e\u0633\u064e\u0647\u064f\u0645 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064f\u0648\u0653\u0627\u0652\u06da \u0623\u064e\u062a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0623\u064e\u0646 \u062a\u064e\u0647\u06e1\u062f\u064f\u0648\u0627\u0652 \u0645\u064e\u0646\u06e1 \u0623\u064e\u0636\u064e\u0644\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06d6 \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0636\u06e1\u0644\u0650\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0644\u064e\u0646 \u062a\u064e\u062c\u0650\u062f\u064e \u0644\u064e\u0647\u064f\u06e5 \u0633\u064e\u0628\u0650\u064a\u0644\u0657\u0627",translation:"Maka mengapa kamu (terpecah) menjadi dua golongan211) dalam (menghadapi) orang-orang munafik, padahal Allah telah mengembalikan mereka (kepada kekafiran), disebabkan usaha mereka sendiri? Apakah kamu bermaksud memberi petunjuk kepada orang yang telah dibiarkan sesat oleh Allah? Barang siapa dibiarkan sesat oleh Allah, kamu tidak akan mendapatkan jalan (untuk memberi petunjuk) baginya"},{id:89,text:"\u0648\u064e\u062f\u0651\u064f\u0648\u0627\u0652 \u0644\u064e\u0648\u06e1 \u062a\u064e\u0643\u06e1\u0641\u064f\u0631\u064f\u0648\u0646\u064e \u0643\u064e\u0645\u064e\u0627 \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0641\u064e\u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0646\u064e \u0633\u064e\u0648\u064e\u0627\u0653\u0621\u0657\u06d6 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1\u0644\u0650\u064a\u064e\u0627\u0653\u0621\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064f\u0647\u064e\u0627\u062c\u0650\u0631\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0641\u064e\u0625\u0650\u0646 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u06e1\u0627\u0652 \u0641\u064e\u062e\u064f\u0630\u064f\u0648\u0647\u064f\u0645\u06e1 \u0648\u064e\u0671\u0642\u06e1\u062a\u064f\u0644\u064f\u0648\u0647\u064f\u0645\u06e1 \u062d\u064e\u064a\u06e1\u062b\u064f \u0648\u064e\u062c\u064e\u062f\u062a\u0651\u064f\u0645\u064f\u0648\u0647\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u0650\u064a\u0651\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0635\u0650\u064a\u0631\u064b\u0627",translation:"Mereka ingin agar kamu menjadi kafir sebagaimana mereka telah menjadi kafir, sehingga kamu menjadi sama (dengan mereka). Janganlah kamu jadikan dari antara mereka sebagai teman-teman(mu), sebelum mereka berpindah pada jalan Allah. Apabila mereka berpaling,212) maka tawanlah mereka dan bunuhlah mereka dimanapun mereka kamu temukan, dan janganlah kamu jadikan seorang pun di antara mereka sebagai teman setia dan penolong"},{id:90,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0635\u0650\u0644\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u06e1\u0645\u0650\u06ed \u0628\u064e\u064a\u06e1\u0646\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u064a\u062b\u064e\u0670\u0642\u064c \u0623\u064e\u0648\u06e1 \u062c\u064e\u0627\u0653\u0621\u064f\u0648\u0643\u064f\u0645\u06e1 \u062d\u064e\u0635\u0650\u0631\u064e\u062a\u06e1 \u0635\u064f\u062f\u064f\u0648\u0631\u064f\u0647\u064f\u0645\u06e1 \u0623\u064e\u0646 \u064a\u064f\u0642\u064e\u0670\u062a\u0650\u0644\u064f\u0648\u0643\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1 \u064a\u064f\u0642\u064e\u0670\u062a\u0650\u0644\u064f\u0648\u0627\u0652 \u0642\u064e\u0648\u06e1\u0645\u064e\u0647\u064f\u0645\u06e1\u06da \u0648\u064e\u0644\u064e\u0648\u06e1 \u0634\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0633\u064e\u0644\u0651\u064e\u0637\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0641\u064e\u0644\u064e\u0642\u064e\u0670\u062a\u064e\u0644\u064f\u0648\u0643\u064f\u0645\u06e1\u06da \u0641\u064e\u0625\u0650\u0646\u0650 \u0671\u0639\u06e1\u062a\u064e\u0632\u064e\u0644\u064f\u0648\u0643\u064f\u0645\u06e1 \u0641\u064e\u0644\u064e\u0645\u06e1 \u064a\u064f\u0642\u064e\u0670\u062a\u0650\u0644\u064f\u0648\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0644\u06e1\u0642\u064e\u0648\u06e1\u0627\u0652 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u064f \u0671\u0644\u0633\u0651\u064e\u0644\u064e\u0645\u064e \u0641\u064e\u0645\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0633\u064e\u0628\u0650\u064a\u0644\u0657\u0627",translation:"kecuali orang-orang yang meminta perlindungan kepada sesuatu kaum, yang antara kamu dan kaum itu telah ada perjanjian (damai)213) atau orang yang datang kepadamu sedang hati mereka merasa keberatan untuk memerangi kamu atau memerangi kaumnya.214) Sekiranya Allah menghendaki, niscaya diberikan-Nya kekuasaan kepada mereka (dalam) menghadapi kamu, maka pastilah mereka memerangimu. Tetapi jika mereka membiarkan kamu, dan tidak memerangimu serta menawarkan perdamaian kepadamu (menyerah) maka Allah tidak memberi jalan bagimu (untuk menawan dan membunuh) mereka"},{id:91,text:"\u0633\u064e\u062a\u064e\u062c\u0650\u062f\u064f\u0648\u0646\u064e \u0621\u064e\u0627\u062e\u064e\u0631\u0650\u064a\u0646\u064e \u064a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0623\u064e\u0646 \u064a\u064e\u0623\u06e1\u0645\u064e\u0646\u064f\u0648\u0643\u064f\u0645\u06e1 \u0648\u064e\u064a\u064e\u0623\u06e1\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0642\u064e\u0648\u06e1\u0645\u064e\u0647\u064f\u0645\u06e1 \u0643\u064f\u0644\u0651\u064e \u0645\u064e\u0627 \u0631\u064f\u062f\u0651\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u0641\u0650\u062a\u06e1\u0646\u064e\u0629\u0650 \u0623\u064f\u0631\u06e1\u0643\u0650\u0633\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0647\u064e\u0627\u06da \u0641\u064e\u0625\u0650\u0646 \u0644\u0651\u064e\u0645\u06e1 \u064a\u064e\u0639\u06e1\u062a\u064e\u0632\u0650\u0644\u064f\u0648\u0643\u064f\u0645\u06e1 \u0648\u064e\u064a\u064f\u0644\u06e1\u0642\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u064f \u0671\u0644\u0633\u0651\u064e\u0644\u064e\u0645\u064e \u0648\u064e\u064a\u064e\u0643\u064f\u0641\u0651\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u064e\u0647\u064f\u0645\u06e1 \u0641\u064e\u062e\u064f\u0630\u064f\u0648\u0647\u064f\u0645\u06e1 \u0648\u064e\u0671\u0642\u06e1\u062a\u064f\u0644\u064f\u0648\u0647\u064f\u0645\u06e1 \u062d\u064e\u064a\u06e1\u062b\u064f \u062b\u064e\u0642\u0650\u0641\u06e1\u062a\u064f\u0645\u064f\u0648\u0647\u064f\u0645\u06e1\u06da \u0648\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064f\u0645\u06e1 \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0633\u064f\u0644\u06e1\u0637\u064e\u0670\u0646\u0657\u0627 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u0657\u0627",translation:"Kelak akan kamu dapati (golongan-golongan) yang lain, yang menginginkan agar mereka hidup aman bersamamu dan aman (pula) bersama kaumnya. Setiap kali mereka diajak kembali kepada fitnah (syirik), mereka pun terjun ke dalamnya. Karena itu jika mereka tidak membiarkan kamu dan tidak mau menawarkan perdamaian kepadamu, serta tidak menahan tangan mereka (dari memerangimu), maka tawanlah mereka dan bunuhlah mereka dimana saja kamu temui, dan merekalah orang yang Kami berikan kepadamu alasan yang nyata (untuk memerangi, menawan dan membunuh) mereka"},{id:92,text:"\u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064d \u0623\u064e\u0646 \u064a\u064e\u0642\u06e1\u062a\u064f\u0644\u064e \u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u062e\u064e\u0637\u064e\u0640\u0654\u0657\u0627\u06da \u0648\u064e\u0645\u064e\u0646 \u0642\u064e\u062a\u064e\u0644\u064e \u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064b\u0627 \u062e\u064e\u0637\u064e\u0640\u0654\u0657\u0627 \u0641\u064e\u062a\u064e\u062d\u06e1\u0631\u0650\u064a\u0631\u064f \u0631\u064e\u0642\u064e\u0628\u064e\u0629\u0656 \u0645\u0651\u064f\u0624\u06e1\u0645\u0650\u0646\u064e\u0629\u0656 \u0648\u064e\u062f\u0650\u064a\u064e\u0629\u065e \u0645\u0651\u064f\u0633\u064e\u0644\u0651\u064e\u0645\u064e\u0629\u064c \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0647\u06e1\u0644\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u064a\u064e\u0635\u0651\u064e\u062f\u0651\u064e\u0642\u064f\u0648\u0627\u0652\u06da \u0641\u064e\u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0648\u06e1\u0645\u064d \u0639\u064e\u062f\u064f\u0648\u0651\u0656 \u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0647\u064f\u0648\u064e \u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u065e \u0641\u064e\u062a\u064e\u062d\u06e1\u0631\u0650\u064a\u0631\u064f \u0631\u064e\u0642\u064e\u0628\u064e\u0629\u0656 \u0645\u0651\u064f\u0624\u06e1\u0645\u0650\u0646\u064e\u0629\u0656\u06d6 \u0648\u064e\u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0648\u06e1\u0645\u0650\u06ed \u0628\u064e\u064a\u06e1\u0646\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u064a\u062b\u064e\u0670\u0642\u065e \u0641\u064e\u062f\u0650\u064a\u064e\u0629\u065e \u0645\u0651\u064f\u0633\u064e\u0644\u0651\u064e\u0645\u064e\u0629\u064c \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0647\u06e1\u0644\u0650\u0647\u0650\u06e6 \u0648\u064e\u062a\u064e\u062d\u06e1\u0631\u0650\u064a\u0631\u064f \u0631\u064e\u0642\u064e\u0628\u064e\u0629\u0656 \u0645\u0651\u064f\u0624\u06e1\u0645\u0650\u0646\u064e\u0629\u0656\u06d6 \u0641\u064e\u0645\u064e\u0646 \u0644\u0651\u064e\u0645\u06e1 \u064a\u064e\u062c\u0650\u062f\u06e1 \u0641\u064e\u0635\u0650\u064a\u064e\u0627\u0645\u064f \u0634\u064e\u0647\u06e1\u0631\u064e\u064a\u06e1\u0646\u0650 \u0645\u064f\u062a\u064e\u062a\u064e\u0627\u0628\u0650\u0639\u064e\u064a\u06e1\u0646\u0650 \u062a\u064e\u0648\u06e1\u0628\u064e\u0629\u0657 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d7 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064b\u0627 \u062d\u064e\u0643\u0650\u064a\u0645\u0657\u0627",translation:"Dan tidak patut bagi seorang yang beriman membunuh seorang yang beriman (yang lain), kecuali karena kesalahan (tidak sengaja). Barang siapa membunuh seorang yang beriman karena kesalahan (hendaklah) dia memerdekakan seorang hamba sahaya yang beriman serta (membayar) tebusan yang diserahkan kepada keluarganya (si terbunuh itu), kecuali jika mereka (keluarga terbunuh) membebaskan pembayaran. Jika dia (si terbunuh) dari kaum yang memusuhimu, padahal dia orang beriman, maka (hendaklah si pembunuh) memerdekakan hamba sahaya yang beriman. Dan jika dia (si terbunuh) dari kaum (kafir) yang ada perjanjian (damai) antara mereka dengan kamu, maka (hendaklah si pembunuh) membayar tebusan yang diserahkan kepada keluarganya (si terbunuh) serta memerdekakan hamba sahaya yang beriman. Barang siapa tidak mendapatkan (hamba sahaya), maka hendaklah dia (si pembunuh) berpuasa dua bulan berturut-turut sebagai tobat kepada Allah. Dan Allah Maha Mengetahui, Mahabijaksana"},{id:93,text:"\u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0642\u06e1\u062a\u064f\u0644\u06e1 \u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0657\u0627 \u0645\u0651\u064f\u062a\u064e\u0639\u064e\u0645\u0651\u0650\u062f\u0657\u0627 \u0641\u064e\u062c\u064e\u0632\u064e\u0627\u0653\u0624\u064f\u0647\u064f\u06e5 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064f \u062e\u064e\u0670\u0644\u0650\u062f\u0657\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u063a\u064e\u0636\u0650\u0628\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0648\u064e\u0644\u064e\u0639\u064e\u0646\u064e\u0647\u064f\u06e5 \u0648\u064e\u0623\u064e\u0639\u064e\u062f\u0651\u064e \u0644\u064e\u0647\u064f\u06e5 \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0639\u064e\u0638\u0650\u064a\u0645\u0657\u0627",translation:"Dan barang siapa membunuh seorang yang beriman dengan sengaja, maka balasannya ialah neraka Jahanam, dia kekal di dalamnya. Allah murka kepadanya, dan melaknatnya serta menyediakan azab yang besar baginya"},{id:94,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0630\u064e\u0627 \u0636\u064e\u0631\u064e\u0628\u06e1\u062a\u064f\u0645\u06e1 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u062a\u064e\u0628\u064e\u064a\u0651\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627\u0652 \u0644\u0650\u0645\u064e\u0646\u06e1 \u0623\u064e\u0644\u06e1\u0642\u064e\u0649\u0670\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u064f \u0671\u0644\u0633\u0651\u064e\u0644\u064e\u0670\u0645\u064e \u0644\u064e\u0633\u06e1\u062a\u064e \u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0657\u0627 \u062a\u064e\u0628\u06e1\u062a\u064e\u063a\u064f\u0648\u0646\u064e \u0639\u064e\u0631\u064e\u0636\u064e \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u0650 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0641\u064e\u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u063a\u064e\u0627\u0646\u0650\u0645\u064f \u0643\u064e\u062b\u0650\u064a\u0631\u064e\u0629\u065e\u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0643\u064f\u0646\u062a\u064f\u0645 \u0645\u0651\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f \u0641\u064e\u0645\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0641\u064e\u062a\u064e\u0628\u064e\u064a\u0651\u064e\u0646\u064f\u0648\u0653\u0627\u0652\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u062e\u064e\u0628\u0650\u064a\u0631\u0657\u0627",translation:"Wahai orang-orang yang beriman! Apabila kamu pergi (berperang) di jalan Allah, maka telitilah (carilah keterangan) dan janganlah kamu mengatakan kepada orang yang mengucapkan \"salam\" kepadamu,215) \"Kamu bukan seorang yang beriman\", (lalu kamu membunuhnya), dengan maksud mencari harta benda kehidupan dunia, padahal di sisi Allah ada harta yang banyak. Begitu jugalah keadaan kamu dahulu,216) lalu Allah memberikan nikmat-Nya kepadamu, maka telitilah! Sungguh, Allah Mahateliti terhadap apa yang kamu kerjakan"},{id:95,text:"\u0644\u0651\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0648\u0650\u064a \u0671\u0644\u06e1\u0642\u064e\u0670\u0639\u0650\u062f\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u063a\u064e\u064a\u06e1\u0631\u064f \u0623\u064f\u0648\u0652\u0644\u0650\u064a \u0671\u0644\u0636\u0651\u064e\u0631\u064e\u0631\u0650 \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u062c\u064e\u0670\u0647\u0650\u062f\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u0650\u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u06e1\u06da \u0641\u064e\u0636\u0651\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u0645\u064f\u062c\u064e\u0670\u0647\u0650\u062f\u0650\u064a\u0646\u064e \u0628\u0650\u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0642\u064e\u0670\u0639\u0650\u062f\u0650\u064a\u0646\u064e \u062f\u064e\u0631\u064e\u062c\u064e\u0629\u0657\u06da \u0648\u064e\u0643\u064f\u0644\u0651\u0657\u0627 \u0648\u064e\u0639\u064e\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u062d\u064f\u0633\u06e1\u0646\u064e\u0649\u0670\u06da \u0648\u064e\u0641\u064e\u0636\u0651\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u0645\u064f\u062c\u064e\u0670\u0647\u0650\u062f\u0650\u064a\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0642\u064e\u0670\u0639\u0650\u062f\u0650\u064a\u0646\u064e \u0623\u064e\u062c\u06e1\u0631\u064b\u0627 \u0639\u064e\u0638\u0650\u064a\u0645\u0657\u0627",translation:"Tidaklah sama antara orang beriman yang duduk (yang tidak turut berperang) tanpa mempunyai uzur (halangan) dengan orang yang berjihad di jalan Allah dengan harta dan jiwanya. Allah melebihkan derajat orang-orang yang berjihad dengan harta dan jiwanya atas orang-orang yang duduk (tidak ikut berperang tanpa halangan). Kepada masing-masing, Allah menjanjikan (pahala) yang baik (surga) dan Allah melebihkan orang-orang yang berjihad atas orang yang duduk dengan pahala yang besar"},{id:96,text:"\u062f\u064e\u0631\u064e\u062c\u064e\u0670\u062a\u0656 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f \u0648\u064e\u0645\u064e\u063a\u06e1\u0641\u0650\u0631\u064e\u0629\u0657 \u0648\u064e\u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u0657\u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u0657\u0627 \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064b\u0627",translation:"(yaitu) beberapa derajat dari pada-Nya, serta ampunan dan rahmat. Allah Maha Pengampun, Maha Penyayang"},{id:97,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u0648\u064e\u0641\u0651\u064e\u0649\u0670\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u064f \u0638\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0653 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u06e1 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0645\u064e \u0643\u064f\u0646\u062a\u064f\u0645\u06e1\u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0643\u064f\u0646\u0651\u064e\u0627 \u0645\u064f\u0633\u06e1\u062a\u064e\u0636\u06e1\u0639\u064e\u0641\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06da \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0643\u064f\u0646\u06e1 \u0623\u064e\u0631\u06e1\u0636\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0670\u0633\u0650\u0639\u064e\u0629\u0657 \u0641\u064e\u062a\u064f\u0647\u064e\u0627\u062c\u0650\u0631\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0647\u064e\u0627\u06da \u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0645\u064e\u0623\u06e1\u0648\u064e\u0649\u0670\u0647\u064f\u0645\u06e1 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064f\u06d6 \u0648\u064e\u0633\u064e\u0627\u0653\u0621\u064e\u062a\u06e1 \u0645\u064e\u0635\u0650\u064a\u0631\u064b\u0627",translation:"(Sesungguhnya orang-orang yang dicabut nyawanya oleh malaikat dalam keadaan menzalimi sendiri,217) mereka (para malaikat) bertanya, \"Bagaimana kamu ini?\" Mereka menjawab, \"Kami orang-orang yang tertindas di bumi (Mekkah).\" Mereka (para malaikat) bertanya, \"Bukankah bumi Allah itu luas, sehingga kamu dapat berhijrah (berpindah-pindah) di bumi itu?\" Maka orang-orang itu tempatnya di neraka Jahanam, dan (Jahanam) itu seburuk-buruk tempat kembali"},{id:98,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u06e1\u0645\u064f\u0633\u06e1\u062a\u064e\u0636\u06e1\u0639\u064e\u0641\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0631\u0651\u0650\u062c\u064e\u0627\u0644\u0650 \u0648\u064e\u0671\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0653\u0621\u0650 \u0648\u064e\u0671\u0644\u06e1\u0648\u0650\u0644\u06e1\u062f\u064e\u0670\u0646\u0650 \u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u064e \u062d\u0650\u064a\u0644\u064e\u0629\u0657 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0647\u06e1\u062a\u064e\u062f\u064f\u0648\u0646\u064e \u0633\u064e\u0628\u0650\u064a\u0644\u0657\u0627",translation:"Kecuali mereka yang tertindas baik laki-laki atau perempuan dan anak-anak yang tidak berdaya dan tidak mengetahui jalan (untuk berhijrah)"},{id:99,text:"\u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0639\u064e\u0633\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0646 \u064a\u064e\u0639\u06e1\u0641\u064f\u0648\u064e \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1\u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0641\u064f\u0648\u0651\u064b\u0627 \u063a\u064e\u0641\u064f\u0648\u0631\u0657\u0627",translation:"maka mereka itu, mudah-mudahan Allah memaafkannya. Allah Maha Pemaaf, Maha Pengampun"},{id:100,text:"\u06de\u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0647\u064e\u0627\u062c\u0650\u0631\u06e1 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u062c\u0650\u062f\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0645\u064f\u0631\u064e\u0670\u063a\u064e\u0645\u0657\u0627 \u0643\u064e\u062b\u0650\u064a\u0631\u0657\u0627 \u0648\u064e\u0633\u064e\u0639\u064e\u0629\u0657\u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u062e\u06e1\u0631\u064f\u062c\u06e1 \u0645\u0650\u0646\u06e2 \u0628\u064e\u064a\u06e1\u062a\u0650\u0647\u0650\u06e6 \u0645\u064f\u0647\u064e\u0627\u062c\u0650\u0631\u064b\u0627 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650\u06e6 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u062f\u06e1\u0631\u0650\u0643\u06e1\u0647\u064f \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u064f \u0641\u064e\u0642\u064e\u062f\u06e1 \u0648\u064e\u0642\u064e\u0639\u064e \u0623\u064e\u062c\u06e1\u0631\u064f\u0647\u064f\u06e5 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d7 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u0657\u0627 \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0657\u0627",translation:"Dan barang siapa berhijrah di jalan Allah, niscaya mereka akan mendapatkan di bumi ini tempat hijrah yang luas dan (rezeki) yang banyak. Barang siapa keluar dari rumahnya dengan maksud berhijrah karena Allah dan Rasul-Nya, kemudian kematian menimpanya (sebelum sampai ke tempat yang dituju), maka sungguh, pahalanya telah ditetapkan di sisi Allah. Dan Allah Maha Pengampun, Maha Penyayang"},{id:101,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0636\u064e\u0631\u064e\u0628\u06e1\u062a\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0641\u064e\u0644\u064e\u064a\u06e1\u0633\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u062c\u064f\u0646\u064e\u0627\u062d\u064c \u0623\u064e\u0646 \u062a\u064e\u0642\u06e1\u0635\u064f\u0631\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u0650 \u0625\u0650\u0646\u06e1 \u062e\u0650\u0641\u06e1\u062a\u064f\u0645\u06e1 \u0623\u064e\u0646 \u064a\u064e\u0641\u06e1\u062a\u0650\u0646\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0653\u0627\u0652\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0639\u064e\u062f\u064f\u0648\u0651\u0657\u0627 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u0657\u0627",translation:"(Dan apabila kamu bepergian di bumi, maka tidaklah berdosa kamu meng-qasar218) salat, jika kamu takut diserang orang kafir. Sesungguhnya orang kafir itu adalah musuh yang nyata bagimu"},{id:102,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0643\u064f\u0646\u062a\u064e \u0641\u0650\u064a\u0647\u0650\u0645\u06e1 \u0641\u064e\u0623\u064e\u0642\u064e\u0645\u06e1\u062a\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e \u0641\u064e\u0644\u06e1\u062a\u064e\u0642\u064f\u0645\u06e1 \u0637\u064e\u0627\u0653\u0626\u0650\u0641\u064e\u0629\u065e \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0639\u064e\u0643\u064e \u0648\u064e\u0644\u06e1\u064a\u064e\u0623\u06e1\u062e\u064f\u0630\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0633\u06e1\u0644\u0650\u062d\u064e\u062a\u064e\u0647\u064f\u0645\u06e1\u06d6 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0633\u064e\u062c\u064e\u062f\u064f\u0648\u0627\u0652 \u0641\u064e\u0644\u06e1\u064a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0648\u064e\u0631\u064e\u0627\u0653\u0626\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u06e1\u062a\u064e\u0623\u06e1\u062a\u0650 \u0637\u064e\u0627\u0653\u0626\u0650\u0641\u064e\u0629\u064c \u0623\u064f\u062e\u06e1\u0631\u064e\u0649\u0670 \u0644\u064e\u0645\u06e1 \u064a\u064f\u0635\u064e\u0644\u0651\u064f\u0648\u0627\u0652 \u0641\u064e\u0644\u06e1\u064a\u064f\u0635\u064e\u0644\u0651\u064f\u0648\u0627\u0652 \u0645\u064e\u0639\u064e\u0643\u064e \u0648\u064e\u0644\u06e1\u064a\u064e\u0623\u06e1\u062e\u064f\u0630\u064f\u0648\u0627\u0652 \u062d\u0650\u0630\u06e1\u0631\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0633\u06e1\u0644\u0650\u062d\u064e\u062a\u064e\u0647\u064f\u0645\u06e1\u06d7 \u0648\u064e\u062f\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0644\u064e\u0648\u06e1 \u062a\u064e\u063a\u06e1\u0641\u064f\u0644\u064f\u0648\u0646\u064e \u0639\u064e\u0646\u06e1 \u0623\u064e\u0633\u06e1\u0644\u0650\u062d\u064e\u062a\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0645\u06e1\u062a\u0650\u0639\u064e\u062a\u0650\u0643\u064f\u0645\u06e1 \u0641\u064e\u064a\u064e\u0645\u0650\u064a\u0644\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645 \u0645\u0651\u064e\u064a\u06e1\u0644\u064e\u0629\u0657 \u0648\u064e\u0670\u062d\u0650\u062f\u064e\u0629\u0657\u06da \u0648\u064e\u0644\u064e\u0627 \u062c\u064f\u0646\u064e\u0627\u062d\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064e \u0628\u0650\u0643\u064f\u0645\u06e1 \u0623\u064e\u0630\u0657\u0649 \u0645\u0651\u0650\u0646 \u0645\u0651\u064e\u0637\u064e\u0631\u064d \u0623\u064e\u0648\u06e1 \u0643\u064f\u0646\u062a\u064f\u0645 \u0645\u0651\u064e\u0631\u06e1\u0636\u064e\u0649\u0670\u0653 \u0623\u064e\u0646 \u062a\u064e\u0636\u064e\u0639\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0633\u06e1\u0644\u0650\u062d\u064e\u062a\u064e\u0643\u064f\u0645\u06e1\u06d6 \u0648\u064e\u062e\u064f\u0630\u064f\u0648\u0627\u0652 \u062d\u0650\u0630\u06e1\u0631\u064e\u0643\u064f\u0645\u06e1\u06d7 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0623\u064e\u0639\u064e\u062f\u0651\u064e \u0644\u0650\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u0657\u0627 \u0645\u0651\u064f\u0647\u0650\u064a\u0646\u0657\u0627",translation:"Dan apabila engkau (Muhammad) berada di tengah-tengah mereka (sahabatmu) lalu engkau hendak melaksanakan salat bersama-sama mereka, maka hendaklah segolongan dari mereka berdiri (salat) bersamamu dan menyandang senjata mereka, kemudian apabila mereka (yang salat bersamamu) sujud (telah menyempurnakan satu rakaat),219) maka hendaklah mereka pindah dari belakangmu (untuk menghadapi musuh) dan hendaklah datang golongan yang lain yang belum salat, lalu mereka salat denganmu,220) dan hendaklah mereka bersiap siaga dan menyandang senjata mereka. Orang-orang kafir ingin agar kamu lengah terhadap senjatamu dan harta bendamu, lalu mereka menyerbu kamu sekaligus. Dan tidak mengapa kamu meletakkan senjata-senjatamu, jika kamu mendapat suatu kesusahan karena hujan atau karena kamu sakit, dan bersiapsiagalah kamu.221) Sungguh, Allah telah menyediakan azab yang menghinakan bagi orang-orang kafir"},{id:103,text:"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u064e\u0636\u064e\u064a\u06e1\u062a\u064f\u0645\u064f \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e \u0641\u064e\u0671\u0630\u06e1\u0643\u064f\u0631\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0642\u0650\u064a\u064e\u0670\u0645\u0657\u0627 \u0648\u064e\u0642\u064f\u0639\u064f\u0648\u062f\u0657\u0627 \u0648\u064e\u0639\u064e\u0644\u064e\u0649\u0670 \u062c\u064f\u0646\u064f\u0648\u0628\u0650\u0643\u064f\u0645\u06e1\u06da \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0671\u0637\u06e1\u0645\u064e\u0623\u06e1\u0646\u064e\u0646\u062a\u064f\u0645\u06e1 \u0641\u064e\u0623\u064e\u0642\u0650\u064a\u0645\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e \u0643\u064e\u0627\u0646\u064e\u062a\u06e1 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0643\u0650\u062a\u064e\u0670\u0628\u0657\u0627 \u0645\u0651\u064e\u0648\u06e1\u0642\u064f\u0648\u062a\u0657\u0627",translation:"Selanjutnya, apabila kamu telah menyelesaikan salat(mu), ingatlah Allah ketika kamu berdiri, pada waktu duduk dan ketika berbaring. Kemudian, apabila kamu telah merasa aman, maka laksanakanlah salat itu (sebagaimana biasa). Sungguh, salat itu adalah kewajiban yang ditentukan waktunya bagi orang-orang yang beriman"},{id:104,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0647\u0650\u0646\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0671\u0628\u06e1\u062a\u0650\u063a\u064e\u0627\u0653\u0621\u0650 \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u0650\u06d6 \u0625\u0650\u0646 \u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u062a\u064e\u0623\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0623\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0643\u064e\u0645\u064e\u0627 \u062a\u064e\u0623\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e\u06d6 \u0648\u064e\u062a\u064e\u0631\u06e1\u062c\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0631\u06e1\u062c\u064f\u0648\u0646\u064e\u06d7 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064b\u0627 \u062d\u064e\u0643\u0650\u064a\u0645\u064b\u0627",translation:"Dan janganlah kamu berhati lemah dalam mengejar mereka (musuhmu). Jika kamu menderita kesakitan, maka ketahuilah mereka pun menderita kesakitan (pula), sebagaimana kamu rasakan, sedang kamu masih dapat mengharapkan dari Allah apa yang tidak dapat mereka harapkan. Allah Maha Mengetahui, Mahabijaksana"},{id:105,text:"\u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0644\u0650\u062a\u064e\u062d\u06e1\u0643\u064f\u0645\u064e \u0628\u064e\u064a\u06e1\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0628\u0650\u0645\u064e\u0627\u0653 \u0623\u064e\u0631\u064e\u0649\u0670\u0643\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06da \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0646 \u0644\u0651\u0650\u0644\u06e1\u062e\u064e\u0627\u0653\u0626\u0650\u0646\u0650\u064a\u0646\u064e \u062e\u064e\u0635\u0650\u064a\u0645\u0657\u0627",translation:"Sungguh, Kami telah menurunkan Kitab (Alquran) kepadamu (Muhammad) membawa kebenaran, agar engkau mengadili antara manusia dengan apa yang telah diajarkan Allah kepadamu, dan janganlah engkau menjadi penentang (orang yang tidak bersalah), karena (membela) orang yang berkhianat"},{id:106,text:"\u0648\u064e\u0671\u0633\u06e1\u062a\u064e\u063a\u06e1\u0641\u0650\u0631\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064e\u06d6 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u0657\u0627 \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0657\u0627",translation:"dan mohonkanlah ampunan kepada Allah. Sungguh, Allah Maha Pengampun, Maha Penyayang"},{id:107,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u062c\u064e\u0670\u062f\u0650\u0644\u06e1 \u0639\u064e\u0646\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062e\u06e1\u062a\u064e\u0627\u0646\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0645\u064e\u0646 \u0643\u064e\u0627\u0646\u064e \u062e\u064e\u0648\u0651\u064e\u0627\u0646\u064b\u0627 \u0623\u064e\u062b\u0650\u064a\u0645\u0657\u0627",translation:"Dan janganlah kamu berdebat untuk (membela) orang-orang yang mengkhianati dirinya. Sungguh, Allah tidak menyukai orang-orang yang selalu berkhianat dan bergelimang dosa"},{id:108,text:"\u064a\u064e\u0633\u06e1\u062a\u064e\u062e\u06e1\u0641\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u062e\u06e1\u0641\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0647\u064f\u0648\u064e \u0645\u064e\u0639\u064e\u0647\u064f\u0645\u06e1 \u0625\u0650\u0630\u06e1 \u064a\u064f\u0628\u064e\u064a\u0651\u0650\u062a\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0631\u06e1\u0636\u064e\u0649\u0670 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0644\u0650\u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0645\u064f\u062d\u0650\u064a\u0637\u064b\u0627",translation:"mereka dapat bersembunyi dari manusia, tetapi mereka tidak dapat bersembunyi dari Allah, karena Allah bersama mereka, ketika pada suatu malam mereka menetapkan keputusan rahasia yang tidak diridai-Nya. Dan Allah Maha Meliputi terhadap apa yang mereka kerjakan"},{id:109,text:"\u0647\u064e\u0640\u0670\u0653\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650 \u062c\u064e\u0670\u062f\u064e\u0644\u06e1\u062a\u064f\u0645\u06e1 \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u0650 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0641\u064e\u0645\u064e\u0646 \u064a\u064f\u062c\u064e\u0670\u062f\u0650\u0644\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u0623\u064e\u0645 \u0645\u0651\u064e\u0646 \u064a\u064e\u0643\u064f\u0648\u0646\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0648\u064e\u0643\u0650\u064a\u0644\u0657\u0627",translation:"Itulah kamu! Kamu berdebat untuk (membela) mereka dalam kehidupan dunia ini, tetapi siapa yang akan menentang Allah untuk (membela) mereka pada hari Kiamat? Atau siapakah yang menjadi pelindung mereka (terhadap azab Allah)"},{id:110,text:"\u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u06e1 \u0633\u064f\u0648\u0653\u0621\u064b\u0627 \u0623\u064e\u0648\u06e1 \u064a\u064e\u0638\u06e1\u0644\u0650\u0645\u06e1 \u0646\u064e\u0641\u06e1\u0633\u064e\u0647\u064f\u06e5 \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u0633\u06e1\u062a\u064e\u063a\u06e1\u0641\u0650\u0631\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u062c\u0650\u062f\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u0657\u0627 \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0657\u0627",translation:"Dan barang siapa berbuat kejahatan dan menganiaya dirinya, kemudian dia memohon ampunan kepada Allah, niscaya dia akan mendapatkan Allah Maha Pengampun, Maha Penyayang"},{id:111,text:"\u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0643\u06e1\u0633\u0650\u0628\u06e1 \u0625\u0650\u062b\u06e1\u0645\u0657\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0643\u06e1\u0633\u0650\u0628\u064f\u0647\u064f\u06e5 \u0639\u064e\u0644\u064e\u0649\u0670 \u0646\u064e\u0641\u06e1\u0633\u0650\u0647\u0650\u06e6\u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064b\u0627 \u062d\u064e\u0643\u0650\u064a\u0645\u0657\u0627",translation:"Dan barang siapa berbuat dosa, maka sesungguhnya dia mengerjakannya untuk (kesulitan) dirinya sendiri. Dan Allah Maha Mengetahui, Mahabijaksana"},{id:112,text:"\u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0643\u06e1\u0633\u0650\u0628\u06e1 \u062e\u064e\u0637\u0650\u064a\u0653\u0640\u0654\u064e\u0629\u064b \u0623\u064e\u0648\u06e1 \u0625\u0650\u062b\u06e1\u0645\u0657\u0627 \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u0631\u06e1\u0645\u0650 \u0628\u0650\u0647\u0650\u06e6 \u0628\u064e\u0631\u0650\u064a\u0653\u0640\u0654\u0657\u0627 \u0641\u064e\u0642\u064e\u062f\u0650 \u0671\u062d\u06e1\u062a\u064e\u0645\u064e\u0644\u064e \u0628\u064f\u0647\u06e1\u062a\u064e\u0670\u0646\u0657\u0627 \u0648\u064e\u0625\u0650\u062b\u06e1\u0645\u0657\u0627 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u0657\u0627",translation:"Dan barang siapa berbuat kesalahan atau dosa, kemudian dia tuduhkan kepada orang yang tidak bersalah, maka sungguh, dia telah memikul suatu kebohongan dan dosa yang nyata"},{id:113,text:"\u0648\u064e\u0644\u064e\u0648\u06e1\u0644\u064e\u0627 \u0641\u064e\u0636\u06e1\u0644\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0648\u064e\u0631\u064e\u062d\u06e1\u0645\u064e\u062a\u064f\u0647\u064f\u06e5 \u0644\u064e\u0647\u064e\u0645\u0651\u064e\u062a \u0637\u0651\u064e\u0627\u0653\u0626\u0650\u0641\u064e\u0629\u065e \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0623\u064e\u0646 \u064a\u064f\u0636\u0650\u0644\u0651\u064f\u0648\u0643\u064e \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0636\u0650\u0644\u0651\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0636\u064f\u0631\u0651\u064f\u0648\u0646\u064e\u0643\u064e \u0645\u0650\u0646 \u0634\u064e\u064a\u06e1\u0621\u0656\u06da \u0648\u064e\u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0648\u064e\u0671\u0644\u06e1\u062d\u0650\u0643\u06e1\u0645\u064e\u0629\u064e \u0648\u064e\u0639\u064e\u0644\u0651\u064e\u0645\u064e\u0643\u064e \u0645\u064e\u0627 \u0644\u064e\u0645\u06e1 \u062a\u064e\u0643\u064f\u0646 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0641\u064e\u0636\u06e1\u0644\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0639\u064e\u0638\u0650\u064a\u0645\u0657\u0627",translation:"Dan kalau bukan karena karunia Allah dan rahmat-Nya kepadamu (Muhammad), tentulah segolongan dari mereka berkeinginan keras untuk menyesatkanmu. Tetapi mereka hanya menyesatkan dirinya sendiri, dan tidak membahayakanmu sedikit pun. Dan (juga karena) Allah telah menurunkan Kitab (Alquran) dan Hikmah (Sunah) kepadamu, dan telah mengajarkan kepadamu apa yang belum engkau ketahui. Karunia Allah yang dilimpahkan kepadamu itu sangat besar"},{id:114,text:"\u06de\u0644\u0651\u064e\u0627 \u062e\u064e\u064a\u06e1\u0631\u064e \u0641\u0650\u064a \u0643\u064e\u062b\u0650\u064a\u0631\u0656 \u0645\u0651\u0650\u0646 \u0646\u0651\u064e\u062c\u06e1\u0648\u064e\u0649\u0670\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u06e1 \u0623\u064e\u0645\u064e\u0631\u064e \u0628\u0650\u0635\u064e\u062f\u064e\u0642\u064e\u0629\u064d \u0623\u064e\u0648\u06e1 \u0645\u064e\u0639\u06e1\u0631\u064f\u0648\u0641\u064d \u0623\u064e\u0648\u06e1 \u0625\u0650\u0635\u06e1\u0644\u064e\u0670\u062d\u0650\u06ed \u0628\u064e\u064a\u06e1\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650\u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0641\u06e1\u0639\u064e\u0644\u06e1 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0671\u0628\u06e1\u062a\u0650\u063a\u064e\u0627\u0653\u0621\u064e \u0645\u064e\u0631\u06e1\u0636\u064e\u0627\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0633\u064e\u0648\u06e1\u0641\u064e \u0646\u064f\u0624\u06e1\u062a\u0650\u064a\u0647\u0650 \u0623\u064e\u062c\u06e1\u0631\u064b\u0627 \u0639\u064e\u0638\u0650\u064a\u0645\u0657\u0627",translation:"Tidak ada kebaikan dari banyak pembicaraan rahasia mereka, kecuali pembicaraan rahasia dari orang yang menyuruh (orang) bersedekah, atau berbuat kebaikan, atau mengadakan perdamaian di antara manusia. Barang siapa berbuat demikian karena mencari keridaan Allah, maka kelak Kami akan memberinya pahala yang besar"},{id:115,text:"\u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0634\u064e\u0627\u0642\u0650\u0642\u0650 \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0645\u064e\u0627 \u062a\u064e\u0628\u064e\u064a\u0651\u064e\u0646\u064e \u0644\u064e\u0647\u064f \u0671\u0644\u06e1\u0647\u064f\u062f\u064e\u0649\u0670 \u0648\u064e\u064a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u06e1 \u063a\u064e\u064a\u06e1\u0631\u064e \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0646\u064f\u0648\u064e\u0644\u0651\u0650\u0647\u0650\u06e6 \u0645\u064e\u0627 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649\u0670 \u0648\u064e\u0646\u064f\u0635\u06e1\u0644\u0650\u0647\u0650\u06e6 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e\u06d6 \u0648\u064e\u0633\u064e\u0627\u0653\u0621\u064e\u062a\u06e1 \u0645\u064e\u0635\u0650\u064a\u0631\u064b\u0627",translation:"Dan barang siapa menentang Rasul (Muhammad) setelah jelas kebenaran baginya, dan mengikuti jalan yang bukan jalan orang-orang mukmin, Kami biarkan dia dalam kesesatan yang telah dilakukannya itu dan akan Kami masukkan dia ke dalam neraka Jahanam, dan itu seburuk-buruk tempat kembali"},{id:116,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064e\u063a\u06e1\u0641\u0650\u0631\u064f \u0623\u064e\u0646 \u064a\u064f\u0634\u06e1\u0631\u064e\u0643\u064e \u0628\u0650\u0647\u0650\u06e6 \u0648\u064e\u064a\u064e\u063a\u06e1\u0641\u0650\u0631\u064f \u0645\u064e\u0627 \u062f\u064f\u0648\u0646\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u0650\u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0634\u06e1\u0631\u0650\u0643\u06e1 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0642\u064e\u062f\u06e1 \u0636\u064e\u0644\u0651\u064e \u0636\u064e\u0644\u064e\u0670\u0644\u064e\u06e2\u0627 \u0628\u064e\u0639\u0650\u064a\u062f\u064b\u0627",translation:"Allah tidak akan mengampuni dosa syirik (mempersekutukan Allah dengan sesuatu), dan Dia mengampuni dosa selain itu bagi siapa yang Dia kehendaki. Dan barang siapa mempersekutukan (sesuatu) dengan Allah, maka sungguh, dia telah tersesat jauh sekali"},{id:117,text:"\u0625\u0650\u0646 \u064a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0625\u0650\u0646\u064e\u0670\u062b\u0657\u0627 \u0648\u064e\u0625\u0650\u0646 \u064a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0634\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u0657\u0627 \u0645\u0651\u064e\u0631\u0650\u064a\u062f\u0657\u0627",translation:"Yang mereka sembah selain Allah itu tidak lain hanyalah in\u0101\u1e61an (berhala),223) dan mereka tidak lain hanyalah menyembah setan yang durhaka"},{id:118,text:"\u0644\u0651\u064e\u0639\u064e\u0646\u064e\u0647\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06d8 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0623\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u06e1 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0643\u064e \u0646\u064e\u0635\u0650\u064a\u0628\u0657\u0627 \u0645\u0651\u064e\u0641\u06e1\u0631\u064f\u0648\u0636\u0657\u0627",translation:"yang dilaknati Allah, dan (setan) itu mengatakan, \"Aku pasti akan mengambil bagian tertentu dari hamba-hamba-Mu"},{id:119,text:"\u0648\u064e\u0644\u064e\u0623\u064f\u0636\u0650\u0644\u0651\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0623\u064f\u0645\u064e\u0646\u0651\u0650\u064a\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0623\u0653\u0645\u064f\u0631\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0641\u064e\u0644\u064e\u064a\u064f\u0628\u064e\u062a\u0651\u0650\u0643\u064f\u0646\u0651\u064e \u0621\u064e\u0627\u0630\u064e\u0627\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0639\u064e\u0670\u0645\u0650 \u0648\u064e\u0644\u064e\u0623\u0653\u0645\u064f\u0631\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0641\u064e\u0644\u064e\u064a\u064f\u063a\u064e\u064a\u0651\u0650\u0631\u064f\u0646\u0651\u064e \u062e\u064e\u0644\u06e1\u0642\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u0650 \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u064e \u0648\u064e\u0644\u0650\u064a\u0651\u0657\u0627 \u0645\u0651\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0642\u064e\u062f\u06e1 \u062e\u064e\u0633\u0650\u0631\u064e \u062e\u064f\u0633\u06e1\u0631\u064e\u0627\u0646\u0657\u0627 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u0657\u0627",translation:"dan pasti akan kusesatkan mereka, dan akan kubangkitkan angan-angan kosong pada mereka dan akan kusuruh mereka memotong telinga-telinga binatang ternak, (lalu mereka benar-benar memotongnya),225) dan akan aku suruh mereka mengubah ciptaan Allah, (lalu mereka benar-benar mengubahnya).\"226) Barang siapa menjadikan setan sebagai pelindung selain Allah, maka sungguh, dia menderita kerugian yang nyata"},{id:120,text:"\u064a\u064e\u0639\u0650\u062f\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u064a\u064f\u0645\u064e\u0646\u0651\u0650\u064a\u0647\u0650\u0645\u06e1\u06d6 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0639\u0650\u062f\u064f\u0647\u064f\u0645\u064f \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u063a\u064f\u0631\u064f\u0648\u0631\u064b\u0627",translation:"(Setan itu) memberikan janji-janji kepada mereka dan membangkitkan angan-angan kosong pada mereka, padahal setan itu hanya menjanjikan tipuan belaka kepada mereka"},{id:121,text:"\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0645\u064e\u0623\u06e1\u0648\u064e\u0649\u0670\u0647\u064f\u0645\u06e1 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064f \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062c\u0650\u062f\u064f\u0648\u0646\u064e \u0639\u064e\u0646\u06e1\u0647\u064e\u0627 \u0645\u064e\u062d\u0650\u064a\u0635\u0657\u0627",translation:"Mereka (yang tertipu) itu tempatnya di neraka Jahanam dan mereka tidak akan mendapat tempat (lain untuk) lari darinya"},{id:122,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0633\u064e\u0646\u064f\u062f\u06e1\u062e\u0650\u0644\u064f\u0647\u064f\u0645\u06e1 \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0656 \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0645\u0650\u0646 \u062a\u064e\u062d\u06e1\u062a\u0650\u0647\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u064f \u062e\u064e\u0670\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627\u0653 \u0623\u064e\u0628\u064e\u062f\u0657\u0627\u06d6 \u0648\u064e\u0639\u06e1\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u064e\u0642\u0651\u0657\u0627\u06da \u0648\u064e\u0645\u064e\u0646\u06e1 \u0623\u064e\u0635\u06e1\u062f\u064e\u0642\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0642\u0650\u064a\u0644\u0657\u0627",translation:"Dan orang yang beriman dan mengerjakan amal kebajikan, kelak akan Kami masukkan ke dalam surga yang mengalir di bawahnya sungai-sungai, mereka kekal di dalamnya selama-lamanya. Dan janji Allah itu benar. Siapakah yang lebih benar perkataannya daripada Allah"},{id:123,text:"\u0644\u0651\u064e\u064a\u06e1\u0633\u064e \u0628\u0650\u0623\u064e\u0645\u064e\u0627\u0646\u0650\u064a\u0651\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064e\u0645\u064e\u0627\u0646\u0650\u064a\u0651\u0650 \u0623\u064e\u0647\u06e1\u0644\u0650 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650\u06d7 \u0645\u064e\u0646 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u06e1 \u0633\u064f\u0648\u0653\u0621\u0657\u0627 \u064a\u064f\u062c\u06e1\u0632\u064e \u0628\u0650\u0647\u0650\u06e6 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062c\u0650\u062f\u06e1 \u0644\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u0650\u064a\u0651\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0635\u0650\u064a\u0631\u0657\u0627",translation:"(Pahala dari Allah) itu bukanlah angan-anganmu227) dan bukan (pula) angan-angan Ahli Kitab. Barang siapa mengerjakan kejahatan, niscaya akan dibalas sesuai dengan kejahatan itu, dan dia tidak akan mendapatkan pelindung dan penolong selain Allah"},{id:124,text:"\u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u06e1 \u0645\u0650\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0645\u0650\u0646 \u0630\u064e\u0643\u064e\u0631\u064d \u0623\u064e\u0648\u06e1 \u0623\u064f\u0646\u062b\u064e\u0649\u0670 \u0648\u064e\u0647\u064f\u0648\u064e \u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u065e \u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u064a\u064e\u062f\u06e1\u062e\u064f\u0644\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u064e \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0638\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0646\u064e\u0642\u0650\u064a\u0631\u0657\u0627",translation:"Dan barang siapa mengerjakan amal kebajikan, baik laki-laki maupun perempuan sedang dia beriman, maka mereka itu akan masuk ke dalam surga dan mereka tidak dizalimi sedikit pun"},{id:125,text:"\u0648\u064e\u0645\u064e\u0646\u06e1 \u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064f \u062f\u0650\u064a\u0646\u0657\u0627 \u0645\u0651\u0650\u0645\u0651\u064e\u0646\u06e1 \u0623\u064e\u0633\u06e1\u0644\u064e\u0645\u064e \u0648\u064e\u062c\u06e1\u0647\u064e\u0647\u064f\u06e5 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0647\u064f\u0648\u064e \u0645\u064f\u062d\u06e1\u0633\u0650\u0646\u065e \u0648\u064e\u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064e \u0645\u0650\u0644\u0651\u064e\u0629\u064e \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064e \u062d\u064e\u0646\u0650\u064a\u0641\u0657\u0627\u06d7 \u0648\u064e\u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064e \u062e\u064e\u0644\u0650\u064a\u0644\u0657\u0627",translation:"Dan siapakah yang lebih baik agamanya daripada orang yang dengan ikhlas berserah diri kepada Allah, sedang dia mengerjakan kebaikan, dan mengikuti agama Ibrahim yang lurus? Dan Allah telah memilih Ibrahim menjadi kesayangan (-Nya)"},{id:126,text:"\u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0645\u0651\u064f\u062d\u0650\u064a\u0637\u0657\u0627",translation:"Dan milik Allahlah apa yang ada di langit dan apa yang ada di bumi, dan (pengetahuan) Allah meliputi segala sesuatu"},{id:127,text:"\u0648\u064e\u064a\u064e\u0633\u06e1\u062a\u064e\u0641\u06e1\u062a\u064f\u0648\u0646\u064e\u0643\u064e \u0641\u0650\u064a \u0671\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0653\u0621\u0650\u06d6 \u0642\u064f\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064f\u0641\u06e1\u062a\u0650\u064a\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u0650\u0646\u0651\u064e \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u062a\u06e1\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0641\u0650\u064a \u064a\u064e\u062a\u064e\u0670\u0645\u064e\u0649 \u0671\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0653\u0621\u0650 \u0671\u0644\u0651\u064e\u0640\u0670\u062a\u0650\u064a \u0644\u064e\u0627 \u062a\u064f\u0624\u06e1\u062a\u064f\u0648\u0646\u064e\u0647\u064f\u0646\u0651\u064e \u0645\u064e\u0627 \u0643\u064f\u062a\u0650\u0628\u064e \u0644\u064e\u0647\u064f\u0646\u0651\u064e \u0648\u064e\u062a\u064e\u0631\u06e1\u063a\u064e\u0628\u064f\u0648\u0646\u064e \u0623\u064e\u0646 \u062a\u064e\u0646\u0643\u0650\u062d\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0633\u06e1\u062a\u064e\u0636\u06e1\u0639\u064e\u0641\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0648\u0650\u0644\u06e1\u062f\u064e\u0670\u0646\u0650 \u0648\u064e\u0623\u064e\u0646 \u062a\u064e\u0642\u064f\u0648\u0645\u064f\u0648\u0627\u0652 \u0644\u0650\u0644\u06e1\u064a\u064e\u062a\u064e\u0670\u0645\u064e\u0649\u0670 \u0628\u0650\u0671\u0644\u06e1\u0642\u0650\u0633\u06e1\u0637\u0650\u06da \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0641\u06e1\u0639\u064e\u0644\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1 \u062e\u064e\u064a\u06e1\u0631\u0656 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0628\u0650\u0647\u0650\u06e6 \u0639\u064e\u0644\u0650\u064a\u0645\u0657\u0627",translation:"(Dan mereka meminta fatwa kepadamu tentang perempuan. Katakanlah, \"Allah memberi fatwa kepadamu tentang mereka,228) dan apa yang dibacakan kepadamu dalam Alquran (juga memfatwakan) tentang para perempuan yatim yang tidak kamu berikan sesuatu (maskawin) yang ditetapkan untuk mereka, sedang kamu ingin menikahi mereka229) dan (tentang) anak-anak yang masih dipandang lemah. Dan (Allah menyuruh kamu) agar mengurus anak-anak yatim secara adil. Dan kebajikan apa pun yang kamu kerjakan, sesungguhnya Allah Maha Mengetahui"},{id:128,text:"\u0648\u064e\u0625\u0650\u0646\u0650 \u0671\u0645\u06e1\u0631\u064e\u0623\u064e\u0629\u064c \u062e\u064e\u0627\u0641\u064e\u062a\u06e1 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u0644\u0650\u0647\u064e\u0627 \u0646\u064f\u0634\u064f\u0648\u0632\u064b\u0627 \u0623\u064e\u0648\u06e1 \u0625\u0650\u0639\u06e1\u0631\u064e\u0627\u0636\u0657\u0627 \u0641\u064e\u0644\u064e\u0627 \u062c\u064f\u0646\u064e\u0627\u062d\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u064e\u0627\u0653 \u0623\u064e\u0646 \u064a\u064f\u0635\u06e1\u0644\u0650\u062d\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0635\u064f\u0644\u06e1\u062d\u0657\u0627\u06da \u0648\u064e\u0671\u0644\u0635\u0651\u064f\u0644\u06e1\u062d\u064f \u062e\u064e\u064a\u06e1\u0631\u065e\u06d7 \u0648\u064e\u0623\u064f\u062d\u06e1\u0636\u0650\u0631\u064e\u062a\u0650 \u0671\u0644\u06e1\u0623\u064e\u0646\u0641\u064f\u0633\u064f \u0671\u0644\u0634\u0651\u064f\u062d\u0651\u064e\u06da \u0648\u064e\u0625\u0650\u0646 \u062a\u064f\u062d\u06e1\u0633\u0650\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u062e\u064e\u0628\u0650\u064a\u0631\u0657\u0627",translation:"(Dan jika seorang perempuan khawatir suaminya akan nusyuz230) atau bersikap tidak acuh, maka keduanya dapat mengadakan perdamaian yang sebenarnya,231) dan perdamaian itu lebih baik (bagi mereka) walaupun manusia itu menurut tabiatnya kikir.232) Dan jika kamu memperbaiki (pergaulan dengan istrimu) dan memelihara dirimu (dari nusyuz dan sikap acuh tak acuh), maka sungguh, Allah Mahateliti terhadap apa yang kamu kerjakan"},{id:129,text:"\u0648\u064e\u0644\u064e\u0646 \u062a\u064e\u0633\u06e1\u062a\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646 \u062a\u064e\u0639\u06e1\u062f\u0650\u0644\u064f\u0648\u0627\u0652 \u0628\u064e\u064a\u06e1\u0646\u064e \u0671\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0653\u0621\u0650 \u0648\u064e\u0644\u064e\u0648\u06e1 \u062d\u064e\u0631\u064e\u0635\u06e1\u062a\u064f\u0645\u06e1\u06d6 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0645\u0650\u064a\u0644\u064f\u0648\u0627\u0652 \u0643\u064f\u0644\u0651\u064e \u0671\u0644\u06e1\u0645\u064e\u064a\u06e1\u0644\u0650 \u0641\u064e\u062a\u064e\u0630\u064e\u0631\u064f\u0648\u0647\u064e\u0627 \u0643\u064e\u0671\u0644\u06e1\u0645\u064f\u0639\u064e\u0644\u0651\u064e\u0642\u064e\u0629\u0650\u06da \u0648\u064e\u0625\u0650\u0646 \u062a\u064f\u0635\u06e1\u0644\u0650\u062d\u064f\u0648\u0627\u0652 \u0648\u064e\u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u0657\u0627 \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0657\u0627",translation:"Dan kamu tidak akan dapat berlaku adil di antara istri-istri(mu), walaupun kamu sangat ingin berbuat demikian, karena itu janganlah kamu terlalu cenderung (kepada yang kamu cintai), sehingga kamu biarkan yang lain terkatung-katung. Dan jika kamu mengadakan perbaikan dan memelihara diri (dari kecurangan), maka sungguh, Allah Maha Pengampun, Maha Penyayang"},{id:130,text:"\u0648\u064e\u0625\u0650\u0646 \u064a\u064e\u062a\u064e\u0641\u064e\u0631\u0651\u064e\u0642\u064e\u0627 \u064a\u064f\u063a\u06e1\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0643\u064f\u0644\u0651\u0657\u0627 \u0645\u0651\u0650\u0646 \u0633\u064e\u0639\u064e\u062a\u0650\u0647\u0650\u06e6\u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0670\u0633\u0650\u0639\u064b\u0627 \u062d\u064e\u0643\u0650\u064a\u0645\u0657\u0627",translation:"Dan jika keduanya bercerai, maka Allah akan memberi kecukupan kepada masing-masing dari karunia-Nya. Dan Allah Maha luas (karunia-Nya), Mahabijaksana"},{id:131,text:"\u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d7 \u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0648\u064e\u0635\u0651\u064e\u064a\u06e1\u0646\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0625\u0650\u064a\u0651\u064e\u0627\u0643\u064f\u0645\u06e1 \u0623\u064e\u0646\u0650 \u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e\u06da \u0648\u064e\u0625\u0650\u0646 \u062a\u064e\u0643\u06e1\u0641\u064f\u0631\u064f\u0648\u0627\u0652 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0646\u0650\u064a\u0651\u064b\u0627 \u062d\u064e\u0645\u0650\u064a\u062f\u0657\u0627",translation:"Dan milik Allahlah apa yang ada di langit dan apa yang ada di bumi, dan sungguh, Kami telah memerintahkan kepada orang yang diberi Kitab suci sebelum kamu dan (juga) kepadamu agar bertakwalah kepada Allah. Tetapi jika kamu ingkar maka (ketahuilah), milik Allahlah apa yang ada di langit dan apa yang ada di bumi dan Allah Mahakaya, Maha Terpuji"},{id:132,text:"\u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06da \u0648\u064e\u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0643\u0650\u064a\u0644\u064b\u0627",translation:"Dan milik Allahlah apa yang ada di langit dan apa yang ada di bumi. Cukuplah Allah sebagai Pemeliharanya"},{id:133,text:"\u0625\u0650\u0646 \u064a\u064e\u0634\u064e\u0623\u06e1 \u064a\u064f\u0630\u06e1\u0647\u0650\u0628\u06e1\u0643\u064f\u0645\u06e1 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0648\u064e\u064a\u064e\u0623\u06e1\u062a\u0650 \u0628\u0650\u0640\u0654\u064e\u0627\u062e\u064e\u0631\u0650\u064a\u0646\u064e\u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0642\u064e\u062f\u0650\u064a\u0631\u0657\u0627",translation:"Kalau Allah menghendaki, niscaya dimusnahkan-Nya kamu semua wahai manusia! Kemudian Dia datangkan (umat) yang lain (sebagai penggantimu). Dan Allah Mahakuasa berbuat demikian"},{id:134,text:"\u0645\u0651\u064e\u0646 \u0643\u064e\u0627\u0646\u064e \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u062b\u064e\u0648\u064e\u0627\u0628\u064e \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0641\u064e\u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062b\u064e\u0648\u064e\u0627\u0628\u064f \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0648\u064e\u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650\u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0633\u064e\u0645\u0650\u064a\u0639\u064e\u06e2\u0627 \u0628\u064e\u0635\u0650\u064a\u0631\u0657\u0627",translation:"Barang siapa menghendaki pahala di dunia maka ketahuilah bahwa di sisi Allah ada pahala dunia dan akhirat. Dan Allah Maha Mendengar, Maha Melihat"},{id:135,text:"\u06de\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u0642\u064e\u0648\u0651\u064e\u0640\u0670\u0645\u0650\u064a\u0646\u064e \u0628\u0650\u0671\u0644\u06e1\u0642\u0650\u0633\u06e1\u0637\u0650 \u0634\u064f\u0647\u064e\u062f\u064e\u0627\u0653\u0621\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0648\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u06e1 \u0623\u064e\u0648\u0650 \u0671\u0644\u06e1\u0648\u064e\u0670\u0644\u0650\u062f\u064e\u064a\u06e1\u0646\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0642\u06e1\u0631\u064e\u0628\u0650\u064a\u0646\u064e\u06da \u0625\u0650\u0646 \u064a\u064e\u0643\u064f\u0646\u06e1 \u063a\u064e\u0646\u0650\u064a\u0651\u064b\u0627 \u0623\u064e\u0648\u06e1 \u0641\u064e\u0642\u0650\u064a\u0631\u0657\u0627 \u0641\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0648\u06e1\u0644\u064e\u0649\u0670 \u0628\u0650\u0647\u0650\u0645\u064e\u0627\u06d6 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0647\u064e\u0648\u064e\u0649\u0670\u0653 \u0623\u064e\u0646 \u062a\u064e\u0639\u06e1\u062f\u0650\u0644\u064f\u0648\u0627\u0652\u06da \u0648\u064e\u0625\u0650\u0646 \u062a\u064e\u0644\u06e1\u0648\u064f\u06e5\u0653\u0627\u0652 \u0623\u064e\u0648\u06e1 \u062a\u064f\u0639\u06e1\u0631\u0650\u0636\u064f\u0648\u0627\u0652 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u062e\u064e\u0628\u0650\u064a\u0631\u0657\u0627",translation:"Wahai orang-orang yang beriman! Jadilah kamu penegak keadilan, menjadi saksi karena Allah, walaupun terhadap dirimu sendiri atau terhadap ibu bapak dan kaum kerabatmu. Jika dia (yang terdakwa) kaya ataupun miskin, maka Allah lebih tahu kemaslahatan (kebaikannya). Maka janganlah kamu mengikuti hawa nafsu karena ingin menyimpang dari kebenaran. Dan jika kamu memutarbalikkan (kata-kata) atau enggan menjadi saksi, maka ketahuilah Allah Mahateliti terhadap segala apa yang kamu kerjakan"},{id:136,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0653\u0627\u0652 \u0621\u064e\u0627\u0645\u0650\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650\u06e6 \u0648\u064e\u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0646\u064e\u0632\u0651\u064e\u0644\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650\u06e6 \u0648\u064e\u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f\u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0643\u06e1\u0641\u064f\u0631\u06e1 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u062a\u0650\u0647\u0650\u06e6 \u0648\u064e\u0643\u064f\u062a\u064f\u0628\u0650\u0647\u0650\u06e6 \u0648\u064e\u0631\u064f\u0633\u064f\u0644\u0650\u0647\u0650\u06e6 \u0648\u064e\u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u0650 \u0641\u064e\u0642\u064e\u062f\u06e1 \u0636\u064e\u0644\u0651\u064e \u0636\u064e\u0644\u064e\u0670\u0644\u064e\u06e2\u0627 \u0628\u064e\u0639\u0650\u064a\u062f\u064b\u0627",translation:"Wahai orang-orang yang beriman! Tetaplah beriman kepada Allah dan Rasul-Nya (Muhammad) dan kepada kitab (Alquran) yang diturunkan kepada Rasul-Nya, serta kitab yang diturunkan sebelumnya. Barang siapa ingkar kepada Allah, malaikat-malaikat-Nya, kitab-kitab-Nya, rasul-rasul-Nya, dan hari kemudian, maka sungguh, orang itu telah tersesat sangat jauh"},{id:137,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u062b\u064f\u0645\u0651\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u062b\u064f\u0645\u0651\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u062b\u064f\u0645\u0651\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u062b\u064f\u0645\u0651\u064e \u0671\u0632\u06e1\u062f\u064e\u0627\u062f\u064f\u0648\u0627\u0652 \u0643\u064f\u0641\u06e1\u0631\u0657\u0627 \u0644\u0651\u064e\u0645\u06e1 \u064a\u064e\u0643\u064f\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u064a\u064e\u063a\u06e1\u0641\u0650\u0631\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u0644\u0650\u064a\u064e\u0647\u06e1\u062f\u0650\u064a\u064e\u0647\u064f\u0645\u06e1 \u0633\u064e\u0628\u0650\u064a\u0644\u064e\u06e2\u0627",translation:"Sesungguhnya orang-orang yang beriman lalu kafir, kemudian beriman (lagi), kemudian kafir lagi, lalu bertambah kekafirannya, maka Allah tidak akan mengampuni mereka, dan tidak (pula) menunjukkan kepada mereka jalan (yang lurus)"},{id:138,text:"\u0628\u064e\u0634\u0651\u0650\u0631\u0650 \u0671\u0644\u06e1\u0645\u064f\u0646\u064e\u0670\u0641\u0650\u0642\u0650\u064a\u0646\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0623\u064e\u0644\u0650\u064a\u0645\u064b\u0627",translation:"Kabarkanlah kepada orang-orang munafik bahwa mereka akan mendapat siksaan yang pedih"},{id:139,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0623\u064e\u0648\u06e1\u0644\u0650\u064a\u064e\u0627\u0653\u0621\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e\u06da \u0623\u064e\u064a\u064e\u0628\u06e1\u062a\u064e\u063a\u064f\u0648\u0646\u064e \u0639\u0650\u0646\u062f\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0639\u0650\u0632\u0651\u064e\u0629\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0639\u0650\u0632\u0651\u064e\u0629\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u062c\u064e\u0645\u0650\u064a\u0639\u0657\u0627",translation:"(yaitu) orang-orang yang menjadikan orang-orang kafir sebagai pemimpin dengan meninggalkan orang-orang mukmin. Apakah mereka mencari kekuatan di sisi orang kafir itu? Ketahuilah bahwa semua kekuatan itu milik Allah"},{id:140,text:"\u0648\u064e\u0642\u064e\u062f\u06e1 \u0646\u064e\u0632\u0651\u064e\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0623\u064e\u0646\u06e1 \u0625\u0650\u0630\u064e\u0627 \u0633\u064e\u0645\u0650\u0639\u06e1\u062a\u064f\u0645\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064f\u0643\u06e1\u0641\u064e\u0631\u064f \u0628\u0650\u0647\u064e\u0627 \u0648\u064e\u064a\u064f\u0633\u06e1\u062a\u064e\u0647\u06e1\u0632\u064e\u0623\u064f \u0628\u0650\u0647\u064e\u0627 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u06e1\u0639\u064f\u062f\u064f\u0648\u0627\u0652 \u0645\u064e\u0639\u064e\u0647\u064f\u0645\u06e1 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u062e\u064f\u0648\u0636\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u062d\u064e\u062f\u0650\u064a\u062b\u064d \u063a\u064e\u064a\u06e1\u0631\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0630\u0657\u0627 \u0645\u0651\u0650\u062b\u06e1\u0644\u064f\u0647\u064f\u0645\u06e1\u06d7 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u062c\u064e\u0627\u0645\u0650\u0639\u064f \u0671\u0644\u06e1\u0645\u064f\u0646\u064e\u0670\u0641\u0650\u0642\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627",translation:"Dan sungguh, Allah telah menurunkan (ketentuan) bagimu di dalam Kitab (Alquran) bahwa apabila kamu mendengar ayat-ayat Allah diingkari dan diperolok-olokkan (oleh orang-orang kafir), maka janganlah kamu duduk bersama mereka, sebelum mereka memasuki pembicaraan yang lain. Karena (kalau tetap duduk dengan mereka), tentulah kamu serupa dengan mereka. Sungguh, Allah akan mengumpulkan semua orang-orang munafik dan orang-orang kafir di neraka Jahanam"},{id:141,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062a\u064e\u0631\u064e\u0628\u0651\u064e\u0635\u064f\u0648\u0646\u064e \u0628\u0650\u0643\u064f\u0645\u06e1 \u0641\u064e\u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u06e1 \u0641\u064e\u062a\u06e1\u062d\u065e \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0644\u064e\u0645\u06e1 \u0646\u064e\u0643\u064f\u0646 \u0645\u0651\u064e\u0639\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0646\u064e\u0635\u0650\u064a\u0628\u065e \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0644\u064e\u0645\u06e1 \u0646\u064e\u0633\u06e1\u062a\u064e\u062d\u06e1\u0648\u0650\u0630\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0648\u064e\u0646\u064e\u0645\u06e1\u0646\u064e\u0639\u06e1\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e\u06da \u0641\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u062d\u06e1\u0643\u064f\u0645\u064f \u0628\u064e\u064a\u06e1\u0646\u064e\u0643\u064f\u0645\u06e1 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650\u06da \u0648\u064e\u0644\u064e\u0646 \u064a\u064e\u062c\u06e1\u0639\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0633\u064e\u0628\u0650\u064a\u0644\u064b\u0627",translation:"(yaitu) orang yang menunggu-nunggu (peristiwa) yang akan terjadi pada dirimu. Apabila kamu mendapat kemenangan dari Allah mereka berkata, \"Bukankah kami (turut berperang) bersama kamu?\" Dan jika orang kafir mendapat bagian mereka berkata, \"Bukankah kami turut memenangkanmu,233) dan membela kamu dari orang mukmin?\" Maka Allah akan memberi keputusan di antara kamu pada hari Kiamat. Allah tidak akan memberi jalan kepada orang kafir untuk mengalahkan orang-orang beriman"},{id:142,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0645\u064f\u0646\u064e\u0670\u0641\u0650\u0642\u0650\u064a\u0646\u064e \u064a\u064f\u062e\u064e\u0670\u062f\u0650\u0639\u064f\u0648\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0647\u064f\u0648\u064e \u062e\u064e\u0670\u062f\u0650\u0639\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u064e\u0627\u0645\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u0650 \u0642\u064e\u0627\u0645\u064f\u0648\u0627\u0652 \u0643\u064f\u0633\u064e\u0627\u0644\u064e\u0649\u0670 \u064a\u064f\u0631\u064e\u0627\u0653\u0621\u064f\u0648\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0630\u06e1\u0643\u064f\u0631\u064f\u0648\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u0657\u0627",translation:"(Sesungguhnya orang munafik itu hendak menipu Allah, tetapi Allahlah yang menipu mereka. 234) Apabila mereka berdiri untuk salat mereka lakukan dengan malas. Mereka bermaksud riya` (ingin dipuji) di hadapan manusia. Dan mereka tidak mengingat Allah kecuali sedikit sekali"},{id:143,text:"\u0645\u0651\u064f\u0630\u064e\u0628\u06e1\u0630\u064e\u0628\u0650\u064a\u0646\u064e \u0628\u064e\u064a\u06e1\u0646\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650 \u0648\u064e\u0644\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650\u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0636\u06e1\u0644\u0650\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0644\u064e\u0646 \u062a\u064e\u062c\u0650\u062f\u064e \u0644\u064e\u0647\u064f\u06e5 \u0633\u064e\u0628\u0650\u064a\u0644\u0657\u0627",translation:"Mereka dalam keadaan ragu antara yang demikian (iman atau kafir) tidak termasuk kepada golongan ini (orang beriman) dan tidak (pula) kepada golongan itu (orang kafir). Barang siapa dibiarkan sesat oleh Allah, maka kamu tidak akan mendapatkan jalan (untuk memberi petunjuk) baginya"},{id:144,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0623\u064e\u0648\u06e1\u0644\u0650\u064a\u064e\u0627\u0653\u0621\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e\u06da \u0623\u064e\u062a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0623\u064e\u0646 \u062a\u064e\u062c\u06e1\u0639\u064e\u0644\u064f\u0648\u0627\u0652 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0633\u064f\u0644\u06e1\u0637\u064e\u0670\u0646\u0657\u0627 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u064b\u0627",translation:"Wahai orang-orang yang beriman! Janganlah kamu menjadikan orang-orang kafir sebagai pemimpin selain dari orang-orang mukmin. Apakah kamu ingin memberi alasan yang jelas bagi Allah (untuk menghukummu)"},{id:145,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0645\u064f\u0646\u064e\u0670\u0641\u0650\u0642\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u062f\u0651\u064e\u0631\u06e1\u0643\u0650 \u0671\u0644\u06e1\u0623\u064e\u0633\u06e1\u0641\u064e\u0644\u0650 \u0645\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0648\u064e\u0644\u064e\u0646 \u062a\u064e\u062c\u0650\u062f\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0646\u064e\u0635\u0650\u064a\u0631\u064b\u0627",translation:"Sungguh, orang-orang munafik itu (ditempatkan) pada tingkatan yang paling bawah dari neraka. Dan kamu tidak akan mendapat seorang penolong pun bagi mereka"},{id:146,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u0627\u0628\u064f\u0648\u0627\u0652 \u0648\u064e\u0623\u064e\u0635\u06e1\u0644\u064e\u062d\u064f\u0648\u0627\u0652 \u0648\u064e\u0671\u0639\u06e1\u062a\u064e\u0635\u064e\u0645\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0623\u064e\u062e\u06e1\u0644\u064e\u0635\u064f\u0648\u0627\u0652 \u062f\u0650\u064a\u0646\u064e\u0647\u064f\u0645\u06e1 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0645\u064e\u0639\u064e \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e\u06d6 \u0648\u064e\u0633\u064e\u0648\u06e1\u0641\u064e \u064a\u064f\u0624\u06e1\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0623\u064e\u062c\u06e1\u0631\u064b\u0627 \u0639\u064e\u0638\u0650\u064a\u0645\u0657\u0627",translation:"(kecuali orang-orang yang bertobat dan memperbaiki diri236) dan berpegang teguh pada (agama) Allah dan dengan tulus ikhlas (menjalankan) agama mereka karena Allah. Maka mereka itu bersama-sama orang-orang yang beriman dan kelak Allah akan memberikan pahala yang besar kepada orang-orang yang beriman"},{id:147,text:"\u0645\u0651\u064e\u0627 \u064a\u064e\u0641\u06e1\u0639\u064e\u0644\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0639\u064e\u0630\u064e\u0627\u0628\u0650\u0643\u064f\u0645\u06e1 \u0625\u0650\u0646 \u0634\u064e\u0643\u064e\u0631\u06e1\u062a\u064f\u0645\u06e1 \u0648\u064e\u0621\u064e\u0627\u0645\u064e\u0646\u062a\u064f\u0645\u06e1\u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0634\u064e\u0627\u0643\u0650\u0631\u064b\u0627 \u0639\u064e\u0644\u0650\u064a\u0645\u0657\u0627",translation:"(Allah tidak akan menyiksamu, jika kamu bersyukur dan beriman. Dan Allah Maha Mensyukuri,237) Maha Mengetahui"},{id:148,text:"\u06de\u0644\u0651\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u062c\u064e\u0647\u06e1\u0631\u064e \u0628\u0650\u0671\u0644\u0633\u0651\u064f\u0648\u0653\u0621\u0650 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0644\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646 \u0638\u064f\u0644\u0650\u0645\u064e\u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0633\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u0639\u064e\u0644\u0650\u064a\u0645\u064b\u0627",translation:"Allah tidak menyukai perkataan buruk, (yang diucapkan) secara terus terang kecuali oleh orang yang dizalimi.238) Dan Allah Maha Mendengar, Maha Mengetahui"},{id:149,text:"\u0625\u0650\u0646 \u062a\u064f\u0628\u06e1\u062f\u064f\u0648\u0627\u0652 \u062e\u064e\u064a\u06e1\u0631\u064b\u0627 \u0623\u064e\u0648\u06e1 \u062a\u064f\u062e\u06e1\u0641\u064f\u0648\u0647\u064f \u0623\u064e\u0648\u06e1 \u062a\u064e\u0639\u06e1\u0641\u064f\u0648\u0627\u0652 \u0639\u064e\u0646 \u0633\u064f\u0648\u0653\u0621\u0656 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0641\u064f\u0648\u0651\u0657\u0627 \u0642\u064e\u062f\u0650\u064a\u0631\u064b\u0627",translation:"Jika kamu menyatakan sesuatu kebajikan, menyembunyikannya atau memaafkan sesuatu kesalahan (orang lain), maka sungguh, Allah Maha Pemaaf, Mahakuasa"},{id:150,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0643\u06e1\u0641\u064f\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064f\u0633\u064f\u0644\u0650\u0647\u0650\u06e6 \u0648\u064e\u064a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0623\u064e\u0646 \u064a\u064f\u0641\u064e\u0631\u0651\u0650\u0642\u064f\u0648\u0627\u0652 \u0628\u064e\u064a\u06e1\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064f\u0633\u064f\u0644\u0650\u0647\u0650\u06e6 \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0646\u064f\u0624\u06e1\u0645\u0650\u0646\u064f \u0628\u0650\u0628\u064e\u0639\u06e1\u0636\u0656 \u0648\u064e\u0646\u064e\u0643\u06e1\u0641\u064f\u0631\u064f \u0628\u0650\u0628\u064e\u0639\u06e1\u0636\u0656 \u0648\u064e\u064a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0623\u064e\u0646 \u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0627\u0652 \u0628\u064e\u064a\u06e1\u0646\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0633\u064e\u0628\u0650\u064a\u0644\u064b\u0627",translation:"(Sesungguhnya orang-orang yang ingkar kepada Allah dan Rasul-rasul-Nya, dan bermaksud membeda-bedakan239) antara (keimanan kepada) Allah dan Rasul-rasul-Nya, dengan mengatakan, \"Kami beriman kepada sebagian dan kami mengingkari sebagian (yang lain),\" serta bermaksud mengambil jalan tengah (iman atau kafir)"},{id:151,text:"\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u064f\u0648\u0646\u064e \u062d\u064e\u0642\u0651\u0657\u0627\u06da \u0648\u064e\u0623\u064e\u0639\u06e1\u062a\u064e\u062f\u06e1\u0646\u064e\u0627 \u0644\u0650\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u0657\u0627 \u0645\u0651\u064f\u0647\u0650\u064a\u0646\u0657\u0627",translation:"merekalah orang-orang kafir yang sebenarnya. Dan Kami sediakan untuk orang-orang kafir itu azab yang menghinakan"},{id:152,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064f\u0633\u064f\u0644\u0650\u0647\u0650\u06e6 \u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064f\u0641\u064e\u0631\u0651\u0650\u0642\u064f\u0648\u0627\u0652 \u0628\u064e\u064a\u06e1\u0646\u064e \u0623\u064e\u062d\u064e\u062f\u0656 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0633\u064e\u0648\u06e1\u0641\u064e \u064a\u064f\u0624\u06e1\u062a\u0650\u064a\u0647\u0650\u0645\u06e1 \u0623\u064f\u062c\u064f\u0648\u0631\u064e\u0647\u064f\u0645\u06e1\u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u0657\u0627 \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0657\u0627",translation:"Adapun orang-orang yang beriman kepada Allah dan Rasul-rasul-Nya dan tidak membeda-bedakan di antara mereka (para Rasul), kelak Allah akan memberikan pahala kepada mereka. Allah Maha Pengampun, Maha Penyayang"},{id:153,text:"\u064a\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0643\u064e \u0623\u064e\u0647\u06e1\u0644\u064f \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0623\u064e\u0646 \u062a\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0643\u0650\u062a\u064e\u0670\u0628\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650\u06da \u0641\u064e\u0642\u064e\u062f\u06e1 \u0633\u064e\u0623\u064e\u0644\u064f\u0648\u0627\u0652 \u0645\u064f\u0648\u0633\u064e\u0649\u0670\u0653 \u0623\u064e\u0643\u06e1\u0628\u064e\u0631\u064e \u0645\u0650\u0646 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0631\u0650\u0646\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u062c\u064e\u0647\u06e1\u0631\u064e\u0629\u0657 \u0641\u064e\u0623\u064e\u062e\u064e\u0630\u064e\u062a\u06e1\u0647\u064f\u0645\u064f \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0639\u0650\u0642\u064e\u0629\u064f \u0628\u0650\u0638\u064f\u0644\u06e1\u0645\u0650\u0647\u0650\u0645\u06e1\u06da \u062b\u064f\u0645\u0651\u064e \u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0639\u0650\u062c\u06e1\u0644\u064e \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0645\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u062a\u06e1\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u064f \u0641\u064e\u0639\u064e\u0641\u064e\u0648\u06e1\u0646\u064e\u0627 \u0639\u064e\u0646 \u0630\u064e\u0670\u0644\u0650\u0643\u064e\u06da \u0648\u064e\u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0633\u064f\u0644\u06e1\u0637\u064e\u0670\u0646\u0657\u0627 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u0657\u0627",translation:"(Orang-orang) Ahli Kitab meminta kepadamu (Muhammad) agar engkau menurunkan suatu Kitab dari langit kepada mereka. Sesungguhnya mereka telah meminta kepada Musa yang lebih besar dari itu. Mereka berkata, \"Perlihatkanlah Allah kepada kami secara nyata.\" Maka mereka disambar petir karena kezalimannya. Kemudian mereka menyembah anak sapi,240) setelah mereka melihat bukti-bukti yang nyata, namun demikian Kami maafkan mereka, dan telah Kami berikan kepada Musa kekuasaan yang nyata"},{id:154,text:"\u0648\u064e\u0631\u064e\u0641\u064e\u0639\u06e1\u0646\u064e\u0627 \u0641\u064e\u0648\u06e1\u0642\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0637\u0651\u064f\u0648\u0631\u064e \u0628\u0650\u0645\u0650\u064a\u062b\u064e\u0670\u0642\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0642\u064f\u0644\u06e1\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u064f \u0671\u062f\u06e1\u062e\u064f\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0628\u064e\u0627\u0628\u064e \u0633\u064f\u062c\u0651\u064e\u062f\u0657\u0627 \u0648\u064e\u0642\u064f\u0644\u06e1\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u062f\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0628\u06e1\u062a\u0650 \u0648\u064e\u0623\u064e\u062e\u064e\u0630\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u0650\u064a\u062b\u064e\u0670\u0642\u064b\u0627 \u063a\u064e\u0644\u0650\u064a\u0638\u0657\u0627",translation:"Dan Kami angkat gunung (Sinai) di atas mereka untuk (menguatkan) perjanjian mereka. Dan Kami perintahkan kepada mereka, \"Masukilah pintu gerbang (Baitulmaqdis) itu sambil bersujud,\" dan Kami perintahkan (pula), kepada mereka, \"Janganlah kamu melanggar peraturan mengenai hari Sabat.241) Dan Kami telah mengambil dari mereka perjanjian yang kokoh"},{id:155,text:"\u0641\u064e\u0628\u0650\u0645\u064e\u0627 \u0646\u064e\u0642\u06e1\u0636\u0650\u0647\u0650\u0645 \u0645\u0651\u0650\u064a\u062b\u064e\u0670\u0642\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0643\u064f\u0641\u06e1\u0631\u0650\u0647\u0650\u0645 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0642\u064e\u062a\u06e1\u0644\u0650\u0647\u0650\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u0646\u06e2\u0628\u0650\u064a\u064e\u0627\u0653\u0621\u064e \u0628\u0650\u063a\u064e\u064a\u06e1\u0631\u0650 \u062d\u064e\u0642\u0651\u0656 \u0648\u064e\u0642\u064e\u0648\u06e1\u0644\u0650\u0647\u0650\u0645\u06e1 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0646\u064e\u0627 \u063a\u064f\u0644\u06e1\u0641\u064f\u06e2\u06da \u0628\u064e\u0644\u06e1 \u0637\u064e\u0628\u064e\u0639\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627 \u0628\u0650\u0643\u064f\u0641\u06e1\u0631\u0650\u0647\u0650\u0645\u06e1 \u0641\u064e\u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u0657\u0627",translation:"Maka (Kami hukum mereka),242) karena mereka melanggar perjanjian itu, dan karena kekafiran mereka terhadap keterangan-keterangan Allah, serta karena mereka telah membunuh Nabi-nabi tanpa hak (alasan yang benar) dan karena mereka mengatakan, \"Hati kami tertutup.\" Sebenarnya, Allah telah mengunci hati mereka karena kekafirannya, karena itu hanya sebagian kecil dari mereka yang beriman"},{id:156,text:"\u0648\u064e\u0628\u0650\u0643\u064f\u0641\u06e1\u0631\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0642\u064e\u0648\u06e1\u0644\u0650\u0647\u0650\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0631\u06e1\u064a\u064e\u0645\u064e \u0628\u064f\u0647\u06e1\u062a\u064e\u0670\u0646\u064b\u0627 \u0639\u064e\u0638\u0650\u064a\u0645\u0657\u0627",translation:"dan (Kami hukum juga) karena kekafiran mereka (terhadap Isa), dan tuduhan mereka yang sangat keji terhadap Maryam"},{id:157,text:"\u0648\u064e\u0642\u064e\u0648\u06e1\u0644\u0650\u0647\u0650\u0645\u06e1 \u0625\u0650\u0646\u0651\u064e\u0627 \u0642\u064e\u062a\u064e\u0644\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0645\u064e\u0633\u0650\u064a\u062d\u064e \u0639\u0650\u064a\u0633\u064e\u0649 \u0671\u0628\u06e1\u0646\u064e \u0645\u064e\u0631\u06e1\u064a\u064e\u0645\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u064e\u0627 \u0642\u064e\u062a\u064e\u0644\u064f\u0648\u0647\u064f \u0648\u064e\u0645\u064e\u0627 \u0635\u064e\u0644\u064e\u0628\u064f\u0648\u0647\u064f \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u0634\u064f\u0628\u0651\u0650\u0647\u064e \u0644\u064e\u0647\u064f\u0645\u06e1\u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u062e\u06e1\u062a\u064e\u0644\u064e\u0641\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0647\u0650 \u0644\u064e\u0641\u0650\u064a \u0634\u064e\u0643\u0651\u0656 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u06da \u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6 \u0645\u0650\u0646\u06e1 \u0639\u0650\u0644\u06e1\u0645\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u062a\u0651\u0650\u0628\u064e\u0627\u0639\u064e \u0671\u0644\u0638\u0651\u064e\u0646\u0651\u0650\u06da \u0648\u064e\u0645\u064e\u0627 \u0642\u064e\u062a\u064e\u0644\u064f\u0648\u0647\u064f \u064a\u064e\u0642\u0650\u064a\u0646\u064e\u06e2\u0627",translation:"dan (Kami hukum juga) karena ucapan mereka, \"Sesungguhnya kami telah membunuh Al-Masih, Isa putra Maryam, Rasul Allah,243) padahal mereka tidak membunuhnya dan tidak (pula) menyalibnya, tetapi (yang mereka bunuh adalah) orang yang diserupakan dengan Isa. Sesungguhnya mereka yang berselisih pendapat tentang (pembunuhan) Isa, selalu dalam keragu-raguan tentang siapa yang dibunuh. Mereka benar-benar tidak tahu (siapa sebenarnya yang dibunuh), melainkan mengikuti persangkaan belaka, jadi mereka tidak yakin telah membunuhnya"},{id:158,text:"\u0628\u064e\u0644 \u0631\u0651\u064e\u0641\u064e\u0639\u064e\u0647\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0632\u0650\u064a\u0632\u064b\u0627 \u062d\u064e\u0643\u0650\u064a\u0645\u0657\u0627",translation:"(tetapi Allah telah mengangkat Isa kehadirat-Nya.244) Allah Mahaperkasa, Mahabijaksana"},{id:159,text:"\u0648\u064e\u0625\u0650\u0646 \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u0647\u06e1\u0644\u0650 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0644\u064e\u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064e\u0646\u0651\u064e \u0628\u0650\u0647\u0650\u06e6 \u0642\u064e\u0628\u06e1\u0644\u064e \u0645\u064e\u0648\u06e1\u062a\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u064a\u064e\u0643\u064f\u0648\u0646\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0634\u064e\u0647\u0650\u064a\u062f\u0657\u0627",translation:"Tidak ada seorang pun di antara Ahli Kitab yang tidak beriman kepadanya (Isa) menjelang kematiannya.245) Dan pada hari Kiamat dia (Isa) akan menjadi saksi atas mereka"},{id:160,text:"\u0641\u064e\u0628\u0650\u0638\u064f\u0644\u06e1\u0645\u0656 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064e\u0627\u062f\u064f\u0648\u0627\u0652 \u062d\u064e\u0631\u0651\u064e\u0645\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0637\u064e\u064a\u0651\u0650\u0628\u064e\u0670\u062a\u064d \u0623\u064f\u062d\u0650\u0644\u0651\u064e\u062a\u06e1 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0628\u0650\u0635\u064e\u062f\u0651\u0650\u0647\u0650\u0645\u06e1 \u0639\u064e\u0646 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u062b\u0650\u064a\u0631\u0657\u0627",translation:"Karena kezaliman orang-orang Yahudi, Kami haramkan bagi mereka makanan yang baik-baik yang (dahulu) pernah dihalalkan; dan karena mereka sering menghalangi (orang lain) dari jalan Allah"},{id:161,text:"\u0648\u064e\u0623\u064e\u062e\u06e1\u0630\u0650\u0647\u0650\u0645\u064f \u0671\u0644\u0631\u0651\u0650\u0628\u064e\u0648\u0670\u0627\u0652 \u0648\u064e\u0642\u064e\u062f\u06e1 \u0646\u064f\u0647\u064f\u0648\u0627\u0652 \u0639\u064e\u0646\u06e1\u0647\u064f \u0648\u064e\u0623\u064e\u0643\u06e1\u0644\u0650\u0647\u0650\u0645\u06e1 \u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0628\u0650\u0671\u0644\u06e1\u0628\u064e\u0670\u0637\u0650\u0644\u0650\u06da \u0648\u064e\u0623\u064e\u0639\u06e1\u062a\u064e\u062f\u06e1\u0646\u064e\u0627 \u0644\u0650\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0623\u064e\u0644\u0650\u064a\u0645\u0657\u0627",translation:"dan karena mereka menjalankan riba, padahal sungguh mereka telah dilarang darinya, dan karena mereka memakan harta orang dengan cara tidak sah (batil). Dan Kami sediakan untuk orang-orang kafir di antara mereka azab yang pedih"},{id:162,text:"\u0644\u0651\u064e\u0640\u0670\u0643\u0650\u0646\u0650 \u0671\u0644\u0631\u0651\u064e\u0640\u0670\u0633\u0650\u062e\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0639\u0650\u0644\u06e1\u0645\u0650 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0645\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064e\u06da \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0642\u0650\u064a\u0645\u0650\u064a\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e\u06da \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u062a\u064f\u0648\u0646\u064e \u0671\u0644\u0632\u0651\u064e\u0643\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u0650 \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0633\u064e\u0646\u064f\u0624\u06e1\u062a\u0650\u064a\u0647\u0650\u0645\u06e1 \u0623\u064e\u062c\u06e1\u0631\u064b\u0627 \u0639\u064e\u0638\u0650\u064a\u0645\u064b\u0627",translation:"Tetapi orang-orang yang ilmunya mendalam di antara mereka, dan orang-orang yang beriman, mereka beriman kepada (Alquran) yang diturunkan kepadamu (Muhammad), dan kepada (kitab-kitab) yang diturunkan sebelummu, begitu pula mereka yang melaksanakan salat dan menunaikan zakat dan beriman kepada Allah dan hari kemudian. Kepada mereka akan Kami berikan pahala yang besar"},{id:163,text:"\u06de\u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u0648\u06e1\u062d\u064e\u064a\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0643\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0648\u06e1\u062d\u064e\u064a\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u0646\u064f\u0648\u062d\u0656 \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650\u0640\u06e7\u0646\u064e \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u0647\u0650\u06e6\u06da \u0648\u064e\u0623\u064e\u0648\u06e1\u062d\u064e\u064a\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064e \u0648\u064e\u0625\u0650\u0633\u06e1\u0645\u064e\u0670\u0639\u0650\u064a\u0644\u064e \u0648\u064e\u0625\u0650\u0633\u06e1\u062d\u064e\u0670\u0642\u064e \u0648\u064e\u064a\u064e\u0639\u06e1\u0642\u064f\u0648\u0628\u064e \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0633\u06e1\u0628\u064e\u0627\u0637\u0650 \u0648\u064e\u0639\u0650\u064a\u0633\u064e\u0649\u0670 \u0648\u064e\u0623\u064e\u064a\u0651\u064f\u0648\u0628\u064e \u0648\u064e\u064a\u064f\u0648\u0646\u064f\u0633\u064e \u0648\u064e\u0647\u064e\u0670\u0631\u064f\u0648\u0646\u064e \u0648\u064e\u0633\u064f\u0644\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u064e\u06da \u0648\u064e\u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0627 \u062f\u064e\u0627\u0648\u064f\u06e5\u062f\u064e \u0632\u064e\u0628\u064f\u0648\u0631\u0657\u0627",translation:"Sesungguhnya Kami mewahyukan kepadamu (Muhammad) sebagaimana Kami telah mewahyukan kepada Nuh, dan Nabi-nabi setelahnya, dan Kami telah mewahyukan (pula) kepada Ibrahim, Ismail, Ishak, Yakub dan anak cucunya; Isa, Ayub, Yunus, Harun dan Sulaiman. Dan Kami telah memberikan Kitab Zabur kepada Dawud"},{id:164,text:"\u0648\u064e\u0631\u064f\u0633\u064f\u0644\u0657\u0627 \u0642\u064e\u062f\u06e1 \u0642\u064e\u0635\u064e\u0635\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f \u0648\u064e\u0631\u064f\u0633\u064f\u0644\u0657\u0627 \u0644\u0651\u064e\u0645\u06e1 \u0646\u064e\u0642\u06e1\u0635\u064f\u0635\u06e1\u0647\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e\u06da \u0648\u064e\u0643\u064e\u0644\u0651\u064e\u0645\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u062a\u064e\u0643\u06e1\u0644\u0650\u064a\u0645\u0657\u0627",translation:"Dan ada beberapa Rasul yang telah Kami kisahkan mereka kepadamu sebelumnya dan ada beberapa Rasul (lain) yang tidak Kami kisahkan mereka kepadamu. Dan kepada Musa, Allah berfirman langsung"},{id:165,text:"\u0631\u0651\u064f\u0633\u064f\u0644\u0657\u0627 \u0645\u0651\u064f\u0628\u064e\u0634\u0651\u0650\u0631\u0650\u064a\u0646\u064e \u0648\u064e\u0645\u064f\u0646\u0630\u0650\u0631\u0650\u064a\u0646\u064e \u0644\u0650\u0626\u064e\u0644\u0651\u064e\u0627 \u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u064f\u062c\u0651\u064e\u0629\u064f\u06e2 \u0628\u064e\u0639\u06e1\u062f\u064e \u0671\u0644\u0631\u0651\u064f\u0633\u064f\u0644\u0650\u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0632\u0650\u064a\u0632\u064b\u0627 \u062d\u064e\u0643\u0650\u064a\u0645\u0657\u0627",translation:"Rasul-rasul itu adalah sebagai pembawa berita gembira dan pemberi peringatan, agar tidak ada alasan bagi manusia untuk membantah Allah setelah Rasul-rasul itu diutus. Allah Mahaperkasa, Mahabijaksana"},{id:166,text:"\u0644\u0651\u064e\u0640\u0670\u0643\u0650\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0634\u06e1\u0647\u064e\u062f\u064f \u0628\u0650\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e\u06d6 \u0623\u064e\u0646\u0632\u064e\u0644\u064e\u0647\u064f\u06e5 \u0628\u0650\u0639\u0650\u0644\u06e1\u0645\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u064f \u064a\u064e\u0634\u06e1\u0647\u064e\u062f\u064f\u0648\u0646\u064e\u06da \u0648\u064e\u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0634\u064e\u0647\u0650\u064a\u062f\u064b\u0627",translation:"Tetapi Allah menjadi saksi atas (Alquran) yang diturunkan-Nya kepadamu (Muhammad). Dia menurunkannya dengan ilmu-Nya, dan para malaikat pun menyaksikan. Dan cukuplah Allah yang menjadi saksi"},{id:167,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u0635\u064e\u062f\u0651\u064f\u0648\u0627\u0652 \u0639\u064e\u0646 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0642\u064e\u062f\u06e1 \u0636\u064e\u0644\u0651\u064f\u0648\u0627\u0652 \u0636\u064e\u0644\u064e\u0670\u0644\u064e\u06e2\u0627 \u0628\u064e\u0639\u0650\u064a\u062f\u064b\u0627",translation:"Sesungguhnya orang-orang yang kafir dan menghalang-halangi (orang lain) dari jalan Allah, benar-benar telah sesat sejauh-jauhnya"},{id:168,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627\u0652 \u0644\u064e\u0645\u06e1 \u064a\u064e\u0643\u064f\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u064a\u064e\u063a\u06e1\u0641\u0650\u0631\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u0644\u0650\u064a\u064e\u0647\u06e1\u062f\u0650\u064a\u064e\u0647\u064f\u0645\u06e1 \u0637\u064e\u0631\u0650\u064a\u0642\u064b\u0627",translation:"Sesungguhnya orang-orang yang kafir dan melakukan kezaliman, Allah tidak akan mengampuni mereka, dan tidak (pula) akan menunjukkan kepada mereka jalan (yang lurus)"},{id:169,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u0637\u064e\u0631\u0650\u064a\u0642\u064e \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u062e\u064e\u0670\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627\u0653 \u0623\u064e\u0628\u064e\u062f\u0657\u0627\u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u0633\u0650\u064a\u0631\u0657\u0627",translation:"Kecuali jalan ke neraka Jahanam; mereka kekal di dalamnya selama-lamanya. Dan hal itu (sangat) mudah bagi Allah"},{id:170,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0642\u064e\u062f\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064f \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1 \u0641\u064e\u0640\u0654\u064e\u0627\u0645\u0650\u0646\u064f\u0648\u0627\u0652 \u062e\u064e\u064a\u06e1\u0631\u0657\u0627 \u0644\u0651\u064e\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0625\u0650\u0646 \u062a\u064e\u0643\u06e1\u0641\u064f\u0631\u064f\u0648\u0627\u0652 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064b\u0627 \u062d\u064e\u0643\u0650\u064a\u0645\u0657\u0627",translation:"Wahai manusia! Sungguh, telah datang Rasul (Muhammad) kepadamu dengan (membawa) kebenaran dari Tuhanmu, maka berimanlah (kepadanya), itu lebih baik bagimu. Dan jika kamu kafir, (itu tidak merugikan Allah sedikit pun) karena sesungguhnya milik Allahlah apa yang di langit dan di bumi. Allah Maha Mengetahui, Mahabijaksana"},{id:171,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u0647\u06e1\u0644\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0644\u064e\u0627 \u062a\u064e\u063a\u06e1\u0644\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u062f\u0650\u064a\u0646\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064e\u06da \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0671\u0644\u06e1\u0645\u064e\u0633\u0650\u064a\u062d\u064f \u0639\u0650\u064a\u0633\u064e\u0649 \u0671\u0628\u06e1\u0646\u064f \u0645\u064e\u0631\u06e1\u064a\u064e\u0645\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0643\u064e\u0644\u0650\u0645\u064e\u062a\u064f\u0647\u064f\u06e5\u0653 \u0623\u064e\u0644\u06e1\u0642\u064e\u0649\u0670\u0647\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064e\u0631\u06e1\u064a\u064e\u0645\u064e \u0648\u064e\u0631\u064f\u0648\u062d\u065e \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u06d6 \u0641\u064e\u0640\u0654\u064e\u0627\u0645\u0650\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064f\u0633\u064f\u0644\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627\u0652 \u062b\u064e\u0644\u064e\u0670\u062b\u064e\u0629\u064c\u06da \u0671\u0646\u062a\u064e\u0647\u064f\u0648\u0627\u0652 \u062e\u064e\u064a\u06e1\u0631\u0657\u0627 \u0644\u0651\u064e\u0643\u064f\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0625\u0650\u0644\u064e\u0670\u0647\u065e \u0648\u064e\u0670\u062d\u0650\u062f\u065e\u06d6 \u0633\u064f\u0628\u06e1\u062d\u064e\u0670\u0646\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u0646 \u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0644\u064e\u0647\u064f\u06e5 \u0648\u064e\u0644\u064e\u062f\u065e\u06d8 \u0644\u0651\u064e\u0647\u064f\u06e5 \u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d7 \u0648\u064e\u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0643\u0650\u064a\u0644\u0657\u0627",translation:"(Wahai Ahli Kitab! Janganlah kamu melampaui batas dalam agamamu,247) dan janganlah kamu mengatakan terhadap Allah kecuali yang benar. Sungguh, Al-Masih Isa putra Maryam itu, adalah utusan Allah dan (yang diciptakan dengan) kalimat-Nya248) yang disampaikan-Nya kepada Maryam, dan (dengan tiupan) roh dari-Nya.249) Maka berimanlah kepada Allah dan Rasul-rasul-Nya dan janganlah kamu mengatakan, \"(Tuhan itu) tiga,\" berhentilah (dari ucapan itu). (Itu) lebih baik bagimu. Sesungguhnya Allah Tuhan Yang Maha Esa, Mahasuci Dia dari (anggapan) mempunyai anak. Milik-Nyalah apa yang ada di langit dan apa yang ada di bumi. Dan cukuplah Allah sebagai pelindung"},{id:172,text:"\u0644\u0651\u064e\u0646 \u064a\u064e\u0633\u06e1\u062a\u064e\u0646\u0643\u0650\u0641\u064e \u0671\u0644\u06e1\u0645\u064e\u0633\u0650\u064a\u062d\u064f \u0623\u064e\u0646 \u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0639\u064e\u0628\u06e1\u062f\u0657\u0627 \u0644\u0651\u0650\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u064f \u0671\u0644\u06e1\u0645\u064f\u0642\u064e\u0631\u0651\u064e\u0628\u064f\u0648\u0646\u064e\u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0633\u06e1\u062a\u064e\u0646\u0643\u0650\u0641\u06e1 \u0639\u064e\u0646\u06e1 \u0639\u0650\u0628\u064e\u0627\u062f\u064e\u062a\u0650\u0647\u0650\u06e6 \u0648\u064e\u064a\u064e\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u0650\u0631\u06e1 \u0641\u064e\u0633\u064e\u064a\u064e\u062d\u06e1\u0634\u064f\u0631\u064f\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u062c\u064e\u0645\u0650\u064a\u0639\u0657\u0627",translation:"Al-Mas\u012bh sama sekali tidak enggan menjadi hamba Allah, dan begitu pula para malaikat yang terdekat (kepada Allah).250) Dan barang siapa enggan menyembah-Nya dan menyombongkan diri, maka Allah akan mengumpulkan mereka semua kepada-Nya"},{id:173,text:"\u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0641\u064e\u064a\u064f\u0648\u064e\u0641\u0651\u0650\u064a\u0647\u0650\u0645\u06e1 \u0623\u064f\u062c\u064f\u0648\u0631\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u064a\u064e\u0632\u0650\u064a\u062f\u064f\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0641\u064e\u0636\u06e1\u0644\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u0633\u06e1\u062a\u064e\u0646\u0643\u064e\u0641\u064f\u0648\u0627\u0652 \u0648\u064e\u0671\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u064e\u0631\u064f\u0648\u0627\u0652 \u0641\u064e\u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064f\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0623\u064e\u0644\u0650\u064a\u0645\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062c\u0650\u062f\u064f\u0648\u0646\u064e \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u0650\u064a\u0651\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0635\u0650\u064a\u0631\u0657\u0627",translation:"Adapun orang-orang yang beriman dan mengerjakan kebajikan, Allah akan menyempurnakan pahala bagi mereka dan menambah sebagian dari karunia-Nya. Sedangkan orang-orang yang enggan (menyembah Allah) dan menyombongkan diri, maka Allah akan mengazab mereka dengan azab yang pedih. Dan mereka tidak akan mendapatkan pelindung dan penolong selain Allah"},{id:174,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0642\u064e\u062f\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645 \u0628\u064f\u0631\u06e1\u0647\u064e\u0670\u0646\u065e \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0646\u064f\u0648\u0631\u0657\u0627 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u0657\u0627",translation:"Wahai manusia! Sesungguhnya telah sampai kepadamu bukti kebenaran dari Tuhanmu, (Muhammad dengan mukjizatnya) dan telah Kami turunkan kepadamu cahaya yang terang benderang (Alquran)"},{id:175,text:"\u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0671\u0639\u06e1\u062a\u064e\u0635\u064e\u0645\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6 \u0641\u064e\u0633\u064e\u064a\u064f\u062f\u06e1\u062e\u0650\u0644\u064f\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u0656 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f \u0648\u064e\u0641\u064e\u0636\u06e1\u0644\u0656 \u0648\u064e\u064a\u064e\u0647\u06e1\u062f\u0650\u064a\u0647\u0650\u0645\u06e1 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0635\u0650\u0631\u064e\u0670\u0637\u0657\u0627 \u0645\u0651\u064f\u0633\u06e1\u062a\u064e\u0642\u0650\u064a\u0645\u0657\u0627",translation:"Adapun orang-orang yang beriman kepada Allah dan berpegang teguh kepada (agama)Nya, maka Allah akan memasukkan mereka ke dalam rahmat dan karunia dari-Nya (surga), dan menunjukkan mereka jalan yang lurus kepada-Nya"},{id:176,text:"\u064a\u064e\u0633\u06e1\u062a\u064e\u0641\u06e1\u062a\u064f\u0648\u0646\u064e\u0643\u064e \u0642\u064f\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064f\u0641\u06e1\u062a\u0650\u064a\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0643\u064e\u0644\u064e\u0670\u0644\u064e\u0629\u0650\u06da \u0625\u0650\u0646\u0650 \u0671\u0645\u06e1\u0631\u064f\u0624\u064c\u0627\u0652 \u0647\u064e\u0644\u064e\u0643\u064e \u0644\u064e\u064a\u06e1\u0633\u064e \u0644\u064e\u0647\u064f\u06e5 \u0648\u064e\u0644\u064e\u062f\u065e \u0648\u064e\u0644\u064e\u0647\u064f\u06e5\u0653 \u0623\u064f\u062e\u06e1\u062a\u065e \u0641\u064e\u0644\u064e\u0647\u064e\u0627 \u0646\u0650\u0635\u06e1\u0641\u064f \u0645\u064e\u0627 \u062a\u064e\u0631\u064e\u0643\u064e\u06da \u0648\u064e\u0647\u064f\u0648\u064e \u064a\u064e\u0631\u0650\u062b\u064f\u0647\u064e\u0627\u0653 \u0625\u0650\u0646 \u0644\u0651\u064e\u0645\u06e1 \u064a\u064e\u0643\u064f\u0646 \u0644\u0651\u064e\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u062f\u065e\u06da \u0641\u064e\u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064e\u062a\u064e\u0627 \u0671\u062b\u06e1\u0646\u064e\u062a\u064e\u064a\u06e1\u0646\u0650 \u0641\u064e\u0644\u064e\u0647\u064f\u0645\u064e\u0627 \u0671\u0644\u062b\u0651\u064f\u0644\u064f\u062b\u064e\u0627\u0646\u0650 \u0645\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0631\u064e\u0643\u064e\u06da \u0648\u064e\u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u062e\u06e1\u0648\u064e\u0629\u0657 \u0631\u0651\u0650\u062c\u064e\u0627\u0644\u0657\u0627 \u0648\u064e\u0646\u0650\u0633\u064e\u0627\u0653\u0621\u0657 \u0641\u064e\u0644\u0650\u0644\u0630\u0651\u064e\u0643\u064e\u0631\u0650 \u0645\u0650\u062b\u06e1\u0644\u064f \u062d\u064e\u0638\u0651\u0650 \u0671\u0644\u06e1\u0623\u064f\u0646\u062b\u064e\u064a\u064e\u064a\u06e1\u0646\u0650\u06d7 \u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u0646 \u062a\u064e\u0636\u0650\u0644\u0651\u064f\u0648\u0627\u0652\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u064f\u06e2",translation:"Mereka meminta fatwa kepadamu (tentang kal\u0101lah).251) Katakanlah, \"Allah memberi fatwa kepadamu tentang kal\u0101lah (yaitu), jika seseorang mati dan dia tidak mempunyai anak tetapi mempunyai saudara perempuan, maka bagiannya (saudara perempuannya itu) separuh dari harta yang ditinggalkannya, dan saudaranya yang laki-laki mewarisi (seluruh harta saudara perempuan), jika dia tidak mempunyai anak. Tetapi jika saudara perempuan itu dua orang, maka bagi keduanya dua pertiga dari harta yang ditinggalkan. Dan jika mereka (ahli waris itu terdiri dari) saudara-saudara laki-laki dan perempuan, maka bagian seorang saudara laki-laki sama dengan bagian dua saudari perempuan. Allah menerangkan (hukum ini) kepadamu, agar kamu tidak sesat. Allah Maha Mengetahui segala sesuatu"}]},{id:5,name:"\u0627\u0644\u0645\u0627\u0626\u062f\u0629",transliteration:"Al-Ma'idah",translation:"Jamuan (Hidangan Makanan)",type:"medinan",total_verses:120,verses:[{id:1,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0648\u06e1\u0641\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u06e1\u0639\u064f\u0642\u064f\u0648\u062f\u0650\u06da \u0623\u064f\u062d\u0650\u0644\u0651\u064e\u062a\u06e1 \u0644\u064e\u0643\u064f\u0645 \u0628\u064e\u0647\u0650\u064a\u0645\u064e\u0629\u064f \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0639\u064e\u0670\u0645\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u064a\u064f\u062a\u06e1\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u063a\u064e\u064a\u06e1\u0631\u064e \u0645\u064f\u062d\u0650\u0644\u0651\u0650\u064a \u0671\u0644\u0635\u0651\u064e\u064a\u06e1\u062f\u0650 \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u062d\u064f\u0631\u064f\u0645\u064c\u06d7 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u062d\u06e1\u0643\u064f\u0645\u064f \u0645\u064e\u0627 \u064a\u064f\u0631\u0650\u064a\u062f\u064f",translation:"(Wahai orang-orang yang beriman! Penuhilah janji-janji! 252) Hewan ternak dihalalkan bagimu, kecuali yang akan disebutkan kepadamu, dengan tidak menghalalkan berburu ketika kamu sedang berihram (haji atau umrah). Sesungguhnya Allah menetapkan hukum sesuai dengan yang Dia kehendaki"},{id:2,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u062a\u064f\u062d\u0650\u0644\u0651\u064f\u0648\u0627\u0652 \u0634\u064e\u0639\u064e\u0640\u0670\u0653\u0626\u0650\u0631\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u0671\u0644\u0634\u0651\u064e\u0647\u06e1\u0631\u064e \u0671\u0644\u06e1\u062d\u064e\u0631\u064e\u0627\u0645\u064e \u0648\u064e\u0644\u064e\u0627 \u0671\u0644\u06e1\u0647\u064e\u062f\u06e1\u064a\u064e \u0648\u064e\u0644\u064e\u0627 \u0671\u0644\u06e1\u0642\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u062f\u064e \u0648\u064e\u0644\u064e\u0627\u0653 \u0621\u064e\u0627\u0653\u0645\u0651\u0650\u064a\u0646\u064e \u0671\u0644\u06e1\u0628\u064e\u064a\u06e1\u062a\u064e \u0671\u0644\u06e1\u062d\u064e\u0631\u064e\u0627\u0645\u064e \u064a\u064e\u0628\u06e1\u062a\u064e\u063a\u064f\u0648\u0646\u064e \u0641\u064e\u0636\u06e1\u0644\u0657\u0627 \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0631\u0650\u0636\u06e1\u0648\u064e\u0670\u0646\u0657\u0627\u06da \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062d\u064e\u0644\u064e\u0644\u06e1\u062a\u064f\u0645\u06e1 \u0641\u064e\u0671\u0635\u06e1\u0637\u064e\u0627\u062f\u064f\u0648\u0627\u0652\u06da \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062c\u06e1\u0631\u0650\u0645\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0634\u064e\u0646\u064e\u0640\u0654\u064e\u0627\u0646\u064f \u0642\u064e\u0648\u06e1\u0645\u064d \u0623\u064e\u0646 \u0635\u064e\u062f\u0651\u064f\u0648\u0643\u064f\u0645\u06e1 \u0639\u064e\u0646\u0650 \u0671\u0644\u06e1\u0645\u064e\u0633\u06e1\u062c\u0650\u062f\u0650 \u0671\u0644\u06e1\u062d\u064e\u0631\u064e\u0627\u0645\u0650 \u0623\u064e\u0646 \u062a\u064e\u0639\u06e1\u062a\u064e\u062f\u064f\u0648\u0627\u0652\u06d8 \u0648\u064e\u062a\u064e\u0639\u064e\u0627\u0648\u064e\u0646\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0628\u0650\u0631\u0651\u0650 \u0648\u064e\u0671\u0644\u062a\u0651\u064e\u0642\u06e1\u0648\u064e\u0649\u0670\u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u064e\u0627\u0648\u064e\u0646\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0625\u0650\u062b\u06e1\u0645\u0650 \u0648\u064e\u0671\u0644\u06e1\u0639\u064f\u062f\u06e1\u0648\u064e\u0670\u0646\u0650\u06da \u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e\u06d6 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0634\u064e\u062f\u0650\u064a\u062f\u064f \u0671\u0644\u06e1\u0639\u0650\u0642\u064e\u0627\u0628\u0650",translation:"(Wahai orang-orang yang beriman! Janganlah kamu melanggar syiar-syiar kesucian Allah,253) dan jangan (melanggar kehormatan) bulan-bulan haram,254) jangan (mengganggu) hadyu (hewan-hewan kurban)255) dan qal\u0101id (hewan-hewan kurban yang diberi tanda),256) dan jangan (pula) mengganggu orang-orang yang mengunjungi Baitulharam; mereka mencari karunia dan keridaan Tuhannya.257) Tetapi apabila kamu telah menyelesaikan ihram, maka bolehlah kamu berburu. Jangan sampai kebencian (mu) kepada suatu kaum karena mereka menghalang-halangimu dari Masjidilharam, mendorongmu berbuat melampaui batas (kepada mereka). Dan tolong-menolonglah kamu dalam (mengerjakan) kebajikan dan takwa, dan jangan tolong-menolong dalam berbuat dosa dan permusuhan. Bertakwalah kepada Allah, sungguh, Allah sangat berat siksa-Nya"},{id:3,text:"\u062d\u064f\u0631\u0651\u0650\u0645\u064e\u062a\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064e\u064a\u06e1\u062a\u064e\u0629\u064f \u0648\u064e\u0671\u0644\u062f\u0651\u064e\u0645\u064f \u0648\u064e\u0644\u064e\u062d\u06e1\u0645\u064f \u0671\u0644\u06e1\u062e\u0650\u0646\u0632\u0650\u064a\u0631\u0650 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0647\u0650\u0644\u0651\u064e \u0644\u0650\u063a\u064e\u064a\u06e1\u0631\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u0650\u0647\u0650\u06e6 \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0646\u06e1\u062e\u064e\u0646\u0650\u0642\u064e\u0629\u064f \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u0642\u064f\u0648\u0630\u064e\u0629\u064f \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u062a\u064e\u0631\u064e\u062f\u0651\u0650\u064a\u064e\u0629\u064f \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0637\u0650\u064a\u062d\u064e\u0629\u064f \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0643\u064e\u0644\u064e \u0671\u0644\u0633\u0651\u064e\u0628\u064f\u0639\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0630\u064e\u0643\u0651\u064e\u064a\u06e1\u062a\u064f\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627 \u0630\u064f\u0628\u0650\u062d\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0646\u0651\u064f\u0635\u064f\u0628\u0650 \u0648\u064e\u0623\u064e\u0646 \u062a\u064e\u0633\u06e1\u062a\u064e\u0642\u06e1\u0633\u0650\u0645\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u06e1\u0623\u064e\u0632\u06e1\u0644\u064e\u0670\u0645\u0650\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u06e1 \u0641\u0650\u0633\u06e1\u0642\u064c\u06d7 \u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064e\u0626\u0650\u0633\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u062f\u0650\u064a\u0646\u0650\u0643\u064f\u0645\u06e1 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062e\u06e1\u0634\u064e\u0648\u06e1\u0647\u064f\u0645\u06e1 \u0648\u064e\u0671\u062e\u06e1\u0634\u064e\u0648\u06e1\u0646\u0650\u06da \u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e \u0623\u064e\u0643\u06e1\u0645\u064e\u0644\u06e1\u062a\u064f \u0644\u064e\u0643\u064f\u0645\u06e1 \u062f\u0650\u064a\u0646\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u062a\u06e1\u0645\u064e\u0645\u06e1\u062a\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0646\u0650\u0639\u06e1\u0645\u064e\u062a\u0650\u064a \u0648\u064e\u0631\u064e\u0636\u0650\u064a\u062a\u064f \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0625\u0650\u0633\u06e1\u0644\u064e\u0670\u0645\u064e \u062f\u0650\u064a\u0646\u0657\u0627\u06da \u0641\u064e\u0645\u064e\u0646\u0650 \u0671\u0636\u06e1\u0637\u064f\u0631\u0651\u064e \u0641\u0650\u064a \u0645\u064e\u062e\u06e1\u0645\u064e\u0635\u064e\u0629\u064d \u063a\u064e\u064a\u06e1\u0631\u064e \u0645\u064f\u062a\u064e\u062c\u064e\u0627\u0646\u0650\u0641\u0656 \u0644\u0651\u0650\u0625\u0650\u062b\u06e1\u0645\u0656 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u065e",translation:"Diharamkan bagimu (memakan) bangkai, darah,258) daging babi, dan (daging) hewan yang disembelih bukan atas (nama) Allah, yang tercekik, yang dipukul, yang jatuh, yang ditanduk, dan yang diterkam binatang buas, kecuali yang sempat kamu sembelih.259) Dan (diharamkan pula) yang disembelih untuk berhala. Dan (diharamkan pula) mengundi nasib dengan azl\u0101m (anak panah),260) (karena) itu suatu perbuatan fasik. Pada hari ini261) orang-orang kafir telah putus asa untuk (mengalahkan) agamamu, sebab itu janganlah kamu takut kepada mereka, tetapi takutlah kepada-Ku. Pada hari ini telah Aku sempurnakan agamamu untukmu, dan telah Aku cukupkan nikmat-Ku bagimu, dan telah Aku ridai Islam sebagai agamamu. Tetapi barang siapa terpaksa262) karena lapar bukan karena ingin berbuat dosa, maka sungguh, Allah Maha Pengampun, Maha Penyayang"},{id:4,text:"\u064a\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u0645\u064e\u0627\u0630\u064e\u0627\u0653 \u0623\u064f\u062d\u0650\u0644\u0651\u064e \u0644\u064e\u0647\u064f\u0645\u06e1\u06d6 \u0642\u064f\u0644\u06e1 \u0623\u064f\u062d\u0650\u0644\u0651\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0637\u0651\u064e\u064a\u0651\u0650\u0628\u064e\u0670\u062a\u064f \u0648\u064e\u0645\u064e\u0627 \u0639\u064e\u0644\u0651\u064e\u0645\u06e1\u062a\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u062c\u064e\u0648\u064e\u0627\u0631\u0650\u062d\u0650 \u0645\u064f\u0643\u064e\u0644\u0651\u0650\u0628\u0650\u064a\u0646\u064e \u062a\u064f\u0639\u064e\u0644\u0651\u0650\u0645\u064f\u0648\u0646\u064e\u0647\u064f\u0646\u0651\u064e \u0645\u0650\u0645\u0651\u064e\u0627 \u0639\u064e\u0644\u0651\u064e\u0645\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06d6 \u0641\u064e\u0643\u064f\u0644\u064f\u0648\u0627\u0652 \u0645\u0650\u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u0645\u06e1\u0633\u064e\u0643\u06e1\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0648\u064e\u0671\u0630\u06e1\u0643\u064f\u0631\u064f\u0648\u0627\u0652 \u0671\u0633\u06e1\u0645\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u06d6 \u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0633\u064e\u0631\u0650\u064a\u0639\u064f \u0671\u0644\u06e1\u062d\u0650\u0633\u064e\u0627\u0628\u0650",translation:"Mereka bertanya kepadamu (Muhammad), \"Apakah yang dihalalkan bagi mereka?\" Katakanlah, \"Yang dihalalkan bagimu (adalah makanan) yang baik-baik dan (buruan yang ditangkap) oleh binatang pemburu yang telah kamu latih untuk berburu, yang kamu latih menurut apa yang telah diajarkan Allah kepadamu. Maka makanlah apa yang ditangkapnya untukmu,263) dan sebutlah nama Allah (waktu melepasnya). Dan bertakwalah kepada Allah, sungguh, Allah sangat cepat perhitungan-Nya"},{id:5,text:"\u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e \u0623\u064f\u062d\u0650\u0644\u0651\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0637\u0651\u064e\u064a\u0651\u0650\u0628\u064e\u0670\u062a\u064f\u06d6 \u0648\u064e\u0637\u064e\u0639\u064e\u0627\u0645\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u062d\u0650\u0644\u0651\u065e \u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0637\u064e\u0639\u064e\u0627\u0645\u064f\u0643\u064f\u0645\u06e1 \u062d\u0650\u0644\u0651\u065e \u0644\u0651\u064e\u0647\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u062d\u06e1\u0635\u064e\u0646\u064e\u0670\u062a\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u062d\u06e1\u0635\u064e\u0646\u064e\u0670\u062a\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064f\u0645\u06e1 \u0625\u0650\u0630\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u062a\u064f\u0645\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0623\u064f\u062c\u064f\u0648\u0631\u064e\u0647\u064f\u0646\u0651\u064e \u0645\u064f\u062d\u06e1\u0635\u0650\u0646\u0650\u064a\u0646\u064e \u063a\u064e\u064a\u06e1\u0631\u064e \u0645\u064f\u0633\u064e\u0670\u0641\u0650\u062d\u0650\u064a\u0646\u064e \u0648\u064e\u0644\u064e\u0627 \u0645\u064f\u062a\u0651\u064e\u062e\u0650\u0630\u0650\u064a\u0653 \u0623\u064e\u062e\u06e1\u062f\u064e\u0627\u0646\u0656\u06d7 \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0643\u06e1\u0641\u064f\u0631\u06e1 \u0628\u0650\u0671\u0644\u06e1\u0625\u0650\u064a\u0645\u064e\u0670\u0646\u0650 \u0641\u064e\u0642\u064e\u062f\u06e1 \u062d\u064e\u0628\u0650\u0637\u064e \u0639\u064e\u0645\u064e\u0644\u064f\u0647\u064f\u06e5 \u0648\u064e\u0647\u064f\u0648\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u062e\u064e\u0670\u0633\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Pada hari ini dihalalkan bagimu segala yang baik-baik. Makanan (sembelihan) Ahli Kitab itu halal bagimu, dan makananmu halal bagi mereka. Dan (dihalalkan bagimu menikahi) perempuan-perempuan yang menjaga kehormatan264) di antara perempuan-perempuan yang beriman dan perempuan-perempuan yang menjaga kehormatan di antara orang-orang yang diberi kitab sebelum kamu, apabila kamu membayar maskawin mereka untuk menikahinya, tidak dengan maksud berzina dan bukan untuk menjadikan perempuan piaraan. Barang siapa kafir setelah beriman maka sungguh, sia-sia amal mereka dan di akhirat dia termasuk orang-orang yang rugi"},{id:6,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0630\u064e\u0627 \u0642\u064f\u0645\u06e1\u062a\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u0650 \u0641\u064e\u0671\u063a\u06e1\u0633\u0650\u0644\u064f\u0648\u0627\u0652 \u0648\u064f\u062c\u064f\u0648\u0647\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u0645\u064e\u0631\u064e\u0627\u0641\u0650\u0642\u0650 \u0648\u064e\u0671\u0645\u06e1\u0633\u064e\u062d\u064f\u0648\u0627\u0652 \u0628\u0650\u0631\u064f\u0621\u064f\u0648\u0633\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0631\u06e1\u062c\u064f\u0644\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u0643\u064e\u0639\u06e1\u0628\u064e\u064a\u06e1\u0646\u0650\u06da \u0648\u064e\u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062c\u064f\u0646\u064f\u0628\u0657\u0627 \u0641\u064e\u0671\u0637\u0651\u064e\u0647\u0651\u064e\u0631\u064f\u0648\u0627\u0652\u06da \u0648\u064e\u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645 \u0645\u0651\u064e\u0631\u06e1\u0636\u064e\u0649\u0670\u0653 \u0623\u064e\u0648\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0633\u064e\u0641\u064e\u0631\u064d \u0623\u064e\u0648\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e \u0623\u064e\u062d\u064e\u062f\u065e \u0645\u0651\u0650\u0646\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u063a\u064e\u0627\u0653\u0626\u0650\u0637\u0650 \u0623\u064e\u0648\u06e1 \u0644\u064e\u0670\u0645\u064e\u0633\u06e1\u062a\u064f\u0645\u064f \u0671\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0653\u0621\u064e \u0641\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u062c\u0650\u062f\u064f\u0648\u0627\u0652 \u0645\u064e\u0627\u0653\u0621\u0657 \u0641\u064e\u062a\u064e\u064a\u064e\u0645\u0651\u064e\u0645\u064f\u0648\u0627\u0652 \u0635\u064e\u0639\u0650\u064a\u062f\u0657\u0627 \u0637\u064e\u064a\u0651\u0650\u0628\u0657\u0627 \u0641\u064e\u0671\u0645\u06e1\u0633\u064e\u062d\u064f\u0648\u0627\u0652 \u0628\u0650\u0648\u064f\u062c\u064f\u0648\u0647\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u06da \u0645\u064e\u0627 \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u064a\u064e\u062c\u06e1\u0639\u064e\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u062d\u064e\u0631\u064e\u062c\u0656 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0644\u0650\u064a\u064f\u0637\u064e\u0647\u0651\u0650\u0631\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u0650\u064a\u064f\u062a\u0650\u0645\u0651\u064e \u0646\u0650\u0639\u06e1\u0645\u064e\u062a\u064e\u0647\u064f\u06e5 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u0634\u06e1\u0643\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Wahai orang-orang yang beriman! Apabila kamu hendak melaksanakan salat, maka basuhlah wajahmu dan tanganmu sampai ke siku, dan sapulah kepalamu dan (basuh) kedua kakimu sampai ke kedua mata kaki. Jika kamu junub maka mandilah. Dan jika kamu sakit265) atau dalam perjalanan atau kembali dari tempat buang air (kakus) atau menyentuh266) perempuan, lalu kamu tidak memperoleh air, maka bertayamumlah dengan debu yang baik (suci); usaplah wajahmu dan tanganmu dengan (debu) itu. Allah tidak ingin menyulitkan kamu, tetapi Dia hendak membersihkan kamu dan menyempurnakan nikmat-Nya bagimu, agar kamu bersyukur"},{id:7,text:"\u0648\u064e\u0671\u0630\u06e1\u0643\u064f\u0631\u064f\u0648\u0627\u0652 \u0646\u0650\u0639\u06e1\u0645\u064e\u0629\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0648\u064e\u0645\u0650\u064a\u062b\u064e\u0670\u0642\u064e\u0647\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0648\u064e\u0627\u062b\u064e\u0642\u064e\u0643\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0630\u06e1 \u0642\u064f\u0644\u06e1\u062a\u064f\u0645\u06e1 \u0633\u064e\u0645\u0650\u0639\u06e1\u0646\u064e\u0627 \u0648\u064e\u0623\u064e\u0637\u064e\u0639\u06e1\u0646\u064e\u0627\u06d6 \u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u064f\u06e2 \u0628\u0650\u0630\u064e\u0627\u062a\u0650 \u0671\u0644\u0635\u0651\u064f\u062f\u064f\u0648\u0631\u0650",translation:"(Dan ingatlah akan karunia Allah kepadamu dan perjanjian-Nya267) yang telah diikatkan kepadamu, ketika kamu mengatakan, \"Kami mendengar dan kami menaati.\" Dan bertakwalah kepada Allah, sungguh, Allah Maha Mengetahui segala isi hati"},{id:8,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u0642\u064e\u0648\u0651\u064e\u0640\u0670\u0645\u0650\u064a\u0646\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0634\u064f\u0647\u064e\u062f\u064e\u0627\u0653\u0621\u064e \u0628\u0650\u0671\u0644\u06e1\u0642\u0650\u0633\u06e1\u0637\u0650\u06d6 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062c\u06e1\u0631\u0650\u0645\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0634\u064e\u0646\u064e\u0640\u0654\u064e\u0627\u0646\u064f \u0642\u064e\u0648\u06e1\u0645\u064d \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064e\u0639\u06e1\u062f\u0650\u0644\u064f\u0648\u0627\u0652\u06da \u0671\u0639\u06e1\u062f\u0650\u0644\u064f\u0648\u0627\u0652 \u0647\u064f\u0648\u064e \u0623\u064e\u0642\u06e1\u0631\u064e\u0628\u064f \u0644\u0650\u0644\u062a\u0651\u064e\u0642\u06e1\u0648\u064e\u0649\u0670\u06d6 \u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u062e\u064e\u0628\u0650\u064a\u0631\u064f\u06e2 \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Wahai orang-orang yang beriman! Jadilah kamu sebagai penegak keadilan karena Allah, (ketika) menjadi saksi dengan adil. Dan janganlah kebencianmu terhadap suatu kaum, mendorong kamu untuk berlaku tidak adil. Berlaku adillah. Karena (adil) itu lebih dekat kepada takwa. Dan bertakwalah kepada Allah, sungguh, Allah Mahateliti atas apa yang kamu kerjakan"},{id:9,text:"\u0648\u064e\u0639\u064e\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u063a\u06e1\u0641\u0650\u0631\u064e\u0629\u065e \u0648\u064e\u0623\u064e\u062c\u06e1\u0631\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u065e",translation:"Allah telah menjanjikan kepada orang-orang yang beriman dan beramal saleh, (bahwa) mereka akan mendapat ampunan dan pahala yang besar"},{id:10,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627\u0653 \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u06e1\u062c\u064e\u062d\u0650\u064a\u0645\u0650",translation:"Adapun orang-orang yang kafir dan mendustakan ayat-ayat Kami, mereka itulah penghuni neraka"},{id:11,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0671\u0630\u06e1\u0643\u064f\u0631\u064f\u0648\u0627\u0652 \u0646\u0650\u0639\u06e1\u0645\u064e\u062a\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0625\u0650\u0630\u06e1 \u0647\u064e\u0645\u0651\u064e \u0642\u064e\u0648\u06e1\u0645\u064c \u0623\u064e\u0646 \u064a\u064e\u0628\u06e1\u0633\u064f\u0637\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u064e\u0647\u064f\u0645\u06e1 \u0641\u064e\u0643\u064e\u0641\u0651\u064e \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0646\u0643\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e\u06da \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0644\u06e1\u064a\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u0650 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Wahai orang-orang yang beriman! Ingatlah nikmat Allah (yang diberikan) kepadamu, ketika suatu kaum bermaksud hendak menyerangmu dengan tangannya, lalu Allah menahan tangan mereka dari kamu. Dan bertakwalah kepada Allah, dan hanya kepada Allahlah hendaknya orang-orang beriman itu bertawakal"},{id:12,text:"\u06de\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u062e\u064e\u0630\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u064a\u062b\u064e\u0670\u0642\u064e \u0628\u064e\u0646\u0650\u064a\u0653 \u0625\u0650\u0633\u06e1\u0631\u064e\u0640\u0670\u0653\u0621\u0650\u064a\u0644\u064e \u0648\u064e\u0628\u064e\u0639\u064e\u062b\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u064f \u0671\u062b\u06e1\u0646\u064e\u064a\u06e1 \u0639\u064e\u0634\u064e\u0631\u064e \u0646\u064e\u0642\u0650\u064a\u0628\u0657\u0627\u06d6 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0625\u0650\u0646\u0651\u0650\u064a \u0645\u064e\u0639\u064e\u0643\u064f\u0645\u06e1\u06d6 \u0644\u064e\u0626\u0650\u0646\u06e1 \u0623\u064e\u0642\u064e\u0645\u06e1\u062a\u064f\u0645\u064f \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u062a\u064f\u0645\u064f \u0671\u0644\u0632\u0651\u064e\u0643\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u0621\u064e\u0627\u0645\u064e\u0646\u062a\u064f\u0645 \u0628\u0650\u0631\u064f\u0633\u064f\u0644\u0650\u064a \u0648\u064e\u0639\u064e\u0632\u0651\u064e\u0631\u06e1\u062a\u064f\u0645\u064f\u0648\u0647\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0642\u06e1\u0631\u064e\u0636\u06e1\u062a\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0642\u064e\u0631\u06e1\u0636\u064b\u0627 \u062d\u064e\u0633\u064e\u0646\u0657\u0627 \u0644\u0651\u064e\u0623\u064f\u0643\u064e\u0641\u0651\u0650\u0631\u064e\u0646\u0651\u064e \u0639\u064e\u0646\u0643\u064f\u0645\u06e1 \u0633\u064e\u064a\u0651\u0650\u0640\u0654\u064e\u0627\u062a\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0623\u064f\u062f\u06e1\u062e\u0650\u0644\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0656 \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0645\u0650\u0646 \u062a\u064e\u062d\u06e1\u062a\u0650\u0647\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u064f\u06da \u0641\u064e\u0645\u064e\u0646 \u0643\u064e\u0641\u064e\u0631\u064e \u0628\u064e\u0639\u06e1\u062f\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u0641\u064e\u0642\u064e\u062f\u06e1 \u0636\u064e\u0644\u0651\u064e \u0633\u064e\u0648\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u0650",translation:"(Dan sungguh, Allah telah mengambil perjanjian dari Bani Israil dan Kami telah mengangkat dua belas orang pemimpin diantara mereka. Dan Allah berfirman, \"Aku bersamamu.\" Sungguh, jika kamu melaksanakan salat dan menunaikan zakat serta beriman kepada rasul-rasul-Ku dan kamu bantu mereka dan kamu pinjamkan kepada Allah pinjaman yang baik,268) pasti akan Aku hapus kesalahan-kesalahanmu, dan pasti, akan Aku masukkan ke dalam surga yang mengalir di bawahnya sungai-sungai. Tetapi barang siapa kafir di antaramu setelah itu, maka sesungguhnya dia telah tersesat dari jalan yang lurus"},{id:13,text:"\u0641\u064e\u0628\u0650\u0645\u064e\u0627 \u0646\u064e\u0642\u06e1\u0636\u0650\u0647\u0650\u0645 \u0645\u0651\u0650\u064a\u062b\u064e\u0670\u0642\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0639\u064e\u0646\u0651\u064e\u0640\u0670\u0647\u064f\u0645\u06e1 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0642\u064f\u0644\u064f\u0648\u0628\u064e\u0647\u064f\u0645\u06e1 \u0642\u064e\u0670\u0633\u0650\u064a\u064e\u0629\u0657\u06d6 \u064a\u064f\u062d\u064e\u0631\u0651\u0650\u0641\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0643\u064e\u0644\u0650\u0645\u064e \u0639\u064e\u0646 \u0645\u0651\u064e\u0648\u064e\u0627\u0636\u0650\u0639\u0650\u0647\u0650\u06e6 \u0648\u064e\u0646\u064e\u0633\u064f\u0648\u0627\u0652 \u062d\u064e\u0638\u0651\u0657\u0627 \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u0630\u064f\u0643\u0651\u0650\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6\u06da \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0632\u064e\u0627\u0644\u064f \u062a\u064e\u0637\u0651\u064e\u0644\u0650\u0639\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u062e\u064e\u0627\u0653\u0626\u0650\u0646\u064e\u0629\u0656 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u0657\u0627 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1\u06d6 \u0641\u064e\u0671\u0639\u06e1\u0641\u064f \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0648\u064e\u0671\u0635\u06e1\u0641\u064e\u062d\u06e1\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0671\u0644\u06e1\u0645\u064f\u062d\u06e1\u0633\u0650\u0646\u0650\u064a\u0646\u064e",translation:"(Tetapi) karena mereka melanggar janjinya, maka Kami melaknat mereka, dan Kami jadikan hati mereka keras membatu. Mereka suka mengubah firman (Allah) dari tempatnya,269) dan mereka (sengaja) melupakan sebagian pesan yang telah diperingatkan kepada mereka. Engkau (Muhammad) senantiasa akan melihat pengkhianatan dari mereka kecuali sekelompok kecil di antara mereka (yang tidak berkhianat), maka maafkanlah mereka dan biarkan mereka. Sungguh, Allah menyukai orang-orang yang berbuat baik"},{id:14,text:"\u0648\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e\u0627 \u0646\u064e\u0635\u064e\u0670\u0631\u064e\u0649\u0670\u0653 \u0623\u064e\u062e\u064e\u0630\u06e1\u0646\u064e\u0627 \u0645\u0650\u064a\u062b\u064e\u0670\u0642\u064e\u0647\u064f\u0645\u06e1 \u0641\u064e\u0646\u064e\u0633\u064f\u0648\u0627\u0652 \u062d\u064e\u0638\u0651\u0657\u0627 \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u0630\u064f\u0643\u0651\u0650\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6 \u0641\u064e\u0623\u064e\u063a\u06e1\u0631\u064e\u064a\u06e1\u0646\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0639\u064e\u062f\u064e\u0627\u0648\u064e\u0629\u064e \u0648\u064e\u0671\u0644\u06e1\u0628\u064e\u063a\u06e1\u0636\u064e\u0627\u0653\u0621\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650\u06da \u0648\u064e\u0633\u064e\u0648\u06e1\u0641\u064e \u064a\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0635\u06e1\u0646\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Dan di antara orang-orang yang mengatakan, \"Kami ini orang Nasrani,\" Kami telah mengambil perjanjian mereka, tetapi mereka (sengaja) melupakan sebagian pesan yang telah diperingatkan kepada mereka, maka Kami timbulkan permusuhan dan kebencian di antara mereka hingga hari Kiamat. Dan kelak Allah akan memberitakan kepada mereka apa yang telah mereka kerjakan"},{id:15,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u0647\u06e1\u0644\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0642\u064e\u062f\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u06e1 \u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0646\u064e\u0627 \u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064f \u0644\u064e\u0643\u064f\u0645\u06e1 \u0643\u064e\u062b\u0650\u064a\u0631\u0657\u0627 \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064f\u062e\u06e1\u0641\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0648\u064e\u064a\u064e\u0639\u06e1\u0641\u064f\u0648\u0627\u0652 \u0639\u064e\u0646 \u0643\u064e\u062b\u0650\u064a\u0631\u0656\u06da \u0642\u064e\u062f\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0646\u064f\u0648\u0631\u065e \u0648\u064e\u0643\u0650\u062a\u064e\u0670\u0628\u065e \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u065e",translation:"Wahai Ahli Kitab! Sungguh, Rasul Kami telah datang kepadamu, menjelaskan kepadamu banyak hal dari (isi) kitab yang kamu sembunyikan, dan banyak (pula) yang dibiarkannya. Sungguh, telah datang kepadamu cahaya dari Allah, dan Kitab270) yang menjelaskan"},{id:16,text:"\u064a\u064e\u0647\u06e1\u062f\u0650\u064a \u0628\u0650\u0647\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0646\u0650 \u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064e \u0631\u0650\u0636\u06e1\u0648\u064e\u0670\u0646\u064e\u0647\u064f\u06e5 \u0633\u064f\u0628\u064f\u0644\u064e \u0671\u0644\u0633\u0651\u064e\u0644\u064e\u0670\u0645\u0650 \u0648\u064e\u064a\u064f\u062e\u06e1\u0631\u0650\u062c\u064f\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0638\u0651\u064f\u0644\u064f\u0645\u064e\u0670\u062a\u0650 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0646\u0651\u064f\u0648\u0631\u0650 \u0628\u0650\u0625\u0650\u0630\u06e1\u0646\u0650\u0647\u0650\u06e6 \u0648\u064e\u064a\u064e\u0647\u06e1\u062f\u0650\u064a\u0647\u0650\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0670\u0637\u0656 \u0645\u0651\u064f\u0633\u06e1\u062a\u064e\u0642\u0650\u064a\u0645\u0656",translation:"Dengan Kitab itulah Allah memberi petunjuk kepada orang yang mengikuti keridaan-Nya ke jalan keselamatan, dan (dengan Kitab itu pula) Allah mengeluarkan orang itu dari gelap gulita kepada cahaya dengan izin-Nya, dan menunjukkan ke jalan yang lurus"},{id:17,text:"\u0644\u0651\u064e\u0642\u064e\u062f\u06e1 \u0643\u064e\u0641\u064e\u0631\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0645\u064e\u0633\u0650\u064a\u062d\u064f \u0671\u0628\u06e1\u0646\u064f \u0645\u064e\u0631\u06e1\u064a\u064e\u0645\u064e\u06da \u0642\u064f\u0644\u06e1 \u0641\u064e\u0645\u064e\u0646 \u064a\u064e\u0645\u06e1\u0644\u0650\u0643\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0634\u064e\u064a\u06e1\u0640\u0654\u064b\u0627 \u0625\u0650\u0646\u06e1 \u0623\u064e\u0631\u064e\u0627\u062f\u064e \u0623\u064e\u0646 \u064a\u064f\u0647\u06e1\u0644\u0650\u0643\u064e \u0671\u0644\u06e1\u0645\u064e\u0633\u0650\u064a\u062d\u064e \u0671\u0628\u06e1\u0646\u064e \u0645\u064e\u0631\u06e1\u064a\u064e\u0645\u064e \u0648\u064e\u0623\u064f\u0645\u0651\u064e\u0647\u064f\u06e5 \u0648\u064e\u0645\u064e\u0646 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u062c\u064e\u0645\u0650\u064a\u0639\u0657\u0627\u06d7 \u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064f\u0644\u06e1\u0643\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u064e\u0627\u06da \u064a\u064e\u062e\u06e1\u0644\u064f\u0642\u064f \u0645\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0642\u064e\u062f\u0650\u064a\u0631\u065e",translation:"Sungguh, telah kafir orang yang berkata, \"Sesungguhnya Allah itu adalah Al-Masih putra Maryam.\" Katakanlah (Muhammad), \"Siapakah yang dapat menghalang-halangi kehendak Allah, jika Dia hendak membinasakan Al-Masih putra Maryam beserta ibunya dan seluruh (manusia) yang berada di bumi?\" dan milik Allahlah kerajaan langit dan bumi dan apa yang ada di antara keduanya. Dia menciptakan apa yang Dia kehendaki. Dan Allah Maha Kuasa atas segala sesuatu"},{id:18,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e\u062a\u0650 \u0671\u0644\u06e1\u064a\u064e\u0647\u064f\u0648\u062f\u064f \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0635\u064e\u0670\u0631\u064e\u0649\u0670 \u0646\u064e\u062d\u06e1\u0646\u064f \u0623\u064e\u0628\u06e1\u0646\u064e\u0640\u0670\u0653\u0624\u064f\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0623\u064e\u062d\u0650\u0628\u0651\u064e\u0640\u0670\u0653\u0624\u064f\u0647\u064f\u06e5\u06da \u0642\u064f\u0644\u06e1 \u0641\u064e\u0644\u0650\u0645\u064e \u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064f\u0643\u064f\u0645 \u0628\u0650\u0630\u064f\u0646\u064f\u0648\u0628\u0650\u0643\u064f\u0645\u06d6 \u0628\u064e\u0644\u06e1 \u0623\u064e\u0646\u062a\u064f\u0645 \u0628\u064e\u0634\u064e\u0631\u065e \u0645\u0651\u0650\u0645\u0651\u064e\u0646\u06e1 \u062e\u064e\u0644\u064e\u0642\u064e\u06da \u064a\u064e\u063a\u06e1\u0641\u0650\u0631\u064f \u0644\u0650\u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0648\u064e\u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064f \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06da \u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064f\u0644\u06e1\u0643\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u064e\u0627\u06d6 \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0671\u0644\u06e1\u0645\u064e\u0635\u0650\u064a\u0631\u064f",translation:"Orang Yahudi dan Nasrani berkata, \"Kami adalah anak-anak Allah dan kekasih-kekasih-Nya.\" Katakanlah, \"Mengapa Allah menyiksa kamu karena dosa-dosamu? Tidak kamu adalah manusia (biasa) di antara orang-orang yang Dia ciptakan. Dia mengampuni siapa yang Dia kehendaki dan menyiksa siapa yang Dia kehendaki. Dan milik Allah seluruh kerajaan langit dan bumi serta apa yang ada di antara keduanya. Dan kepada-Nya semua akan kembali"},{id:19,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u0647\u06e1\u0644\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0642\u064e\u062f\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u06e1 \u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0646\u064e\u0627 \u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064f \u0644\u064e\u0643\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0641\u064e\u062a\u06e1\u0631\u064e\u0629\u0656 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0631\u0651\u064f\u0633\u064f\u0644\u0650 \u0623\u064e\u0646 \u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u0646\u064e\u0627 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0634\u0650\u064a\u0631\u0656 \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0630\u0650\u064a\u0631\u0656\u06d6 \u0641\u064e\u0642\u064e\u062f\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645 \u0628\u064e\u0634\u0650\u064a\u0631\u065e \u0648\u064e\u0646\u064e\u0630\u0650\u064a\u0631\u065e\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0642\u064e\u062f\u0650\u064a\u0631\u065e",translation:"Wahai Ahli Kitab! Sungguh, Rasul Kami telah datang kepadamu, menjelaskan (syariat Kami) kepadamu ketika terputus (pengiriman) Rasul-rasul, agar kamu tidak mengatakan, \"Tidak ada yang datang kepada kami baik seorang pembawa berita gembira maupun seorang pemberi peringatan.\" Sungguh, telah datang kepadamu pembawa berita gembira dan pemberi peringatan. Dan Allah Mahakuasa atas segala sesuatu"},{id:20,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0644\u0650\u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u06e6 \u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u0630\u06e1\u0643\u064f\u0631\u064f\u0648\u0627\u0652 \u0646\u0650\u0639\u06e1\u0645\u064e\u0629\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0625\u0650\u0630\u06e1 \u062c\u064e\u0639\u064e\u0644\u064e \u0641\u0650\u064a\u0643\u064f\u0645\u06e1 \u0623\u064e\u0646\u06e2\u0628\u0650\u064a\u064e\u0627\u0653\u0621\u064e \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u064f\u0644\u064f\u0648\u0643\u0657\u0627 \u0648\u064e\u0621\u064e\u0627\u062a\u064e\u0649\u0670\u0643\u064f\u0645 \u0645\u0651\u064e\u0627 \u0644\u064e\u0645\u06e1 \u064a\u064f\u0624\u06e1\u062a\u0650 \u0623\u064e\u062d\u064e\u062f\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Dan (ingatlah), ketika Musa berkata kepada kaumnya, \"Wahai kaumku! Ingatlah akan nikmat Allah kepadamu ketika Dia mengangkat Nabi-nabi di antaramu, dan menjadikan kamu sebagai orang-orang merdeka, dan memberikan kepada kamu apa yang belum pernah diberikan kepada seorang pun di antara umat yang lain"},{id:21,text:"\u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u062f\u06e1\u062e\u064f\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0671\u0644\u06e1\u0645\u064f\u0642\u064e\u062f\u0651\u064e\u0633\u064e\u0629\u064e \u0671\u0644\u0651\u064e\u062a\u0650\u064a \u0643\u064e\u062a\u064e\u0628\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0631\u06e1\u062a\u064e\u062f\u0651\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u062f\u06e1\u0628\u064e\u0627\u0631\u0650\u0643\u064f\u0645\u06e1 \u0641\u064e\u062a\u064e\u0646\u0642\u064e\u0644\u0650\u0628\u064f\u0648\u0627\u0652 \u062e\u064e\u0670\u0633\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Wahai kaumku! Masuklah ke tanah suci (Palestina) yang telah ditentukan Allah bagimu,271) dan janganlah kamu berbalik ke belakang (karena takut kepada musuh), nanti kamu menjadi orang yang rugi"},{id:22,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u064a\u064e\u0670\u0645\u064f\u0648\u0633\u064e\u0649\u0670\u0653 \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0642\u064e\u0648\u06e1\u0645\u0657\u0627 \u062c\u064e\u0628\u0651\u064e\u0627\u0631\u0650\u064a\u0646\u064e \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0646 \u0646\u0651\u064e\u062f\u06e1\u062e\u064f\u0644\u064e\u0647\u064e\u0627 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u062e\u06e1\u0631\u064f\u062c\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0641\u064e\u0625\u0650\u0646 \u064a\u064e\u062e\u06e1\u0631\u064f\u062c\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u062f\u064e\u0670\u062e\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Mereka berkata, \"Wahai Musa! Sesungguhnya di dalam negeri itu ada orang-orang yang sangat kuat dan kejam, kami tidak akan memasukinya sebelum mereka keluar darinya. Jika mereka keluar dari sana, niscaya kami akan masuk"},{id:23,text:"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u062c\u064f\u0644\u064e\u0627\u0646\u0650 \u0645\u0650\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062e\u064e\u0627\u0641\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u06e1\u0639\u064e\u0645\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u064e\u0627 \u0671\u062f\u06e1\u062e\u064f\u0644\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u064f \u0671\u0644\u06e1\u0628\u064e\u0627\u0628\u064e \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u062f\u064e\u062e\u064e\u0644\u06e1\u062a\u064f\u0645\u064f\u0648\u0647\u064f \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u063a\u064e\u0670\u0644\u0650\u0628\u064f\u0648\u0646\u064e\u06da \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645 \u0645\u0651\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Berkatalah dua orang laki-laki di antara mereka yang bertakwa, yang telah diberi nikmat oleh Allah, \"Serbulah mereka melalui pintu gerbang (negeri) itu. Jika kamu memasukinya niscaya kamu akan menang. Dan bertawakallah kamu hanya kepada Allah, jika kamu benar-benar orang-orang beriman"},{id:24,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u064a\u064e\u0670\u0645\u064f\u0648\u0633\u064e\u0649\u0670\u0653 \u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0646 \u0646\u0651\u064e\u062f\u06e1\u062e\u064f\u0644\u064e\u0647\u064e\u0627\u0653 \u0623\u064e\u0628\u064e\u062f\u0657\u0627 \u0645\u0651\u064e\u0627 \u062f\u064e\u0627\u0645\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0641\u064e\u0671\u0630\u06e1\u0647\u064e\u0628\u06e1 \u0623\u064e\u0646\u062a\u064e \u0648\u064e\u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0641\u064e\u0642\u064e\u0670\u062a\u0650\u0644\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0627 \u0647\u064e\u0670\u0647\u064f\u0646\u064e\u0627 \u0642\u064e\u0670\u0639\u0650\u062f\u064f\u0648\u0646\u064e",translation:"Mereka berkata, \"Wahai Musa! Sampai kapan pun kami tidak akan memasukinya selama mereka masih ada di dalamnya, karena itu pergilah engkau bersama Tuhanmu, dan berperanglah kamu berdua. Biarlah kami tetap (menanti) di sini saja"},{id:25,text:"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0627\u0653 \u0623\u064e\u0645\u06e1\u0644\u0650\u0643\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0646\u064e\u0641\u06e1\u0633\u0650\u064a \u0648\u064e\u0623\u064e\u062e\u0650\u064a\u06d6 \u0641\u064e\u0671\u0641\u06e1\u0631\u064f\u0642\u06e1 \u0628\u064e\u064a\u06e1\u0646\u064e\u0646\u064e\u0627 \u0648\u064e\u0628\u064e\u064a\u06e1\u0646\u064e \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0641\u064e\u0670\u0633\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Dia (Musa) berkata, \"Ya Tuhanku, aku hanya menguasai diriku sendiri dan saudaraku. Sebab itu pisahkanlah antara kami dengan orang-orang yang fasik itu"},{id:26,text:"\u0642\u064e\u0627\u0644\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064e\u0627 \u0645\u064f\u062d\u064e\u0631\u0651\u064e\u0645\u064e\u0629\u064c \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1\u06db \u0623\u064e\u0631\u06e1\u0628\u064e\u0639\u0650\u064a\u0646\u064e \u0633\u064e\u0646\u064e\u0629\u0657\u06db \u064a\u064e\u062a\u0650\u064a\u0647\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06da \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0623\u06e1\u0633\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0641\u064e\u0670\u0633\u0650\u0642\u0650\u064a\u0646\u064e",translation:"(Allah) berfirman, \"(Jika demikian), maka (negeri) itu terlarang buat mereka selama empat puluh tahun, (selama itu) mereka akan mengembara kebingungan di bumi. Maka janganlah engkau (Musa) bersedih hati (memikirkan nasib) orang-orang yang fasik itu"},{id:27,text:"\u06de\u0648\u064e\u0671\u062a\u06e1\u0644\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0646\u064e\u0628\u064e\u0623\u064e \u0671\u0628\u06e1\u0646\u064e\u064a\u06e1 \u0621\u064e\u0627\u062f\u064e\u0645\u064e \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0625\u0650\u0630\u06e1 \u0642\u064e\u0631\u0651\u064e\u0628\u064e\u0627 \u0642\u064f\u0631\u06e1\u0628\u064e\u0627\u0646\u0657\u0627 \u0641\u064e\u062a\u064f\u0642\u064f\u0628\u0651\u0650\u0644\u064e \u0645\u0650\u0646\u06e1 \u0623\u064e\u062d\u064e\u062f\u0650\u0647\u0650\u0645\u064e\u0627 \u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064f\u062a\u064e\u0642\u064e\u0628\u0651\u064e\u0644\u06e1 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u0653\u062e\u064e\u0631\u0650 \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0623\u064e\u0642\u06e1\u062a\u064f\u0644\u064e\u0646\u0651\u064e\u0643\u064e\u06d6 \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u062a\u064e\u0642\u064e\u0628\u0651\u064e\u0644\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",translation:"Dan ceritakanlah (Muhammad) yang sebenarnya kepada mereka tentang kisah kedua putra Adam,272) ketika keduanya mempersembahkan kurban, maka (kurban) salah seorang dari mereka berdua (Habil) diterima dan dari yang lain (Qabil) tidak diterima. Dia (Qabil) berkata, \"Sungguh, aku pasti membunuhmu!\" Dia (Habil) berkata, \"Sesungguhnya Allah hanya menerima (amal) dari orang yang bertakwa"},{id:28,text:"\u0644\u064e\u0626\u0650\u0646\u06e2 \u0628\u064e\u0633\u064e\u0637\u062a\u064e \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u064a\u064e\u062f\u064e\u0643\u064e \u0644\u0650\u062a\u064e\u0642\u06e1\u062a\u064f\u0644\u064e\u0646\u0650\u064a \u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u064e\u0627\u06e0 \u0628\u0650\u0628\u064e\u0627\u0633\u0650\u0637\u0656 \u064a\u064e\u062f\u0650\u064a\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0644\u0650\u0623\u064e\u0642\u06e1\u062a\u064f\u0644\u064e\u0643\u064e\u06d6 \u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0631\u064e\u0628\u0651\u064e \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Sungguh, jika engkau (Qabil) menggerakkan tanganmu kepadaku untuk membunuhku, aku tidak akan menggerakkan tanganku kepadamu untuk membunuhmu. Aku takut kepada Allah, Tuhan seluruh alam"},{id:29,text:"\u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064f\u0631\u0650\u064a\u062f\u064f \u0623\u064e\u0646 \u062a\u064e\u0628\u064f\u0648\u0653\u0623\u064e \u0628\u0650\u0625\u0650\u062b\u06e1\u0645\u0650\u064a \u0648\u064e\u0625\u0650\u062b\u06e1\u0645\u0650\u0643\u064e \u0641\u064e\u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u06e1 \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u0650 \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650\u06da \u0648\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062c\u064e\u0632\u064e\u0640\u0670\u0653\u0624\u064f\u0627\u0652 \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Sesungguhnya aku ingin agar engkau kembali dengan (membawa) dosa (membunuh)ku dan dosamu sendiri, maka engkau akan menjadi penghuni neraka; dan itulah balasan bagi orang yang zalim"},{id:30,text:"\u0641\u064e\u0637\u064e\u0648\u0651\u064e\u0639\u064e\u062a\u06e1 \u0644\u064e\u0647\u064f\u06e5 \u0646\u064e\u0641\u06e1\u0633\u064f\u0647\u064f\u06e5 \u0642\u064e\u062a\u06e1\u0644\u064e \u0623\u064e\u062e\u0650\u064a\u0647\u0650 \u0641\u064e\u0642\u064e\u062a\u064e\u0644\u064e\u0647\u064f\u06e5 \u0641\u064e\u0623\u064e\u0635\u06e1\u0628\u064e\u062d\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u062e\u064e\u0670\u0633\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Maka nafsu (Qabil) mendorongnya untuk membunuh saudaranya, kemudian dia pun (benar-benar) membunuhnya, maka jadilah dia termasuk orang yang rugi"},{id:31,text:"\u0641\u064e\u0628\u064e\u0639\u064e\u062b\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064f\u0631\u064e\u0627\u0628\u0657\u0627 \u064a\u064e\u0628\u06e1\u062d\u064e\u062b\u064f \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0644\u0650\u064a\u064f\u0631\u0650\u064a\u064e\u0647\u064f\u06e5 \u0643\u064e\u064a\u06e1\u0641\u064e \u064a\u064f\u0648\u064e\u0670\u0631\u0650\u064a \u0633\u064e\u0648\u06e1\u0621\u064e\u0629\u064e \u0623\u064e\u062e\u0650\u064a\u0647\u0650\u06da \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0670\u0648\u064e\u064a\u06e1\u0644\u064e\u062a\u064e\u0649\u0670\u0653 \u0623\u064e\u0639\u064e\u062c\u064e\u0632\u06e1\u062a\u064f \u0623\u064e\u0646\u06e1 \u0623\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u062b\u06e1\u0644\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u06e1\u063a\u064f\u0631\u064e\u0627\u0628\u0650 \u0641\u064e\u0623\u064f\u0648\u064e\u0670\u0631\u0650\u064a\u064e \u0633\u064e\u0648\u06e1\u0621\u064e\u0629\u064e \u0623\u064e\u062e\u0650\u064a\u06d6 \u0641\u064e\u0623\u064e\u0635\u06e1\u0628\u064e\u062d\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0640\u0670\u062f\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Kemudian Allah mengutus seekor burung gagak menggali tanah untuk diperlihatkan kepadanya. (Qabil) bagaimana dia seharusnya menguburkan mayat saudaranya. Qabil berkata, \"Oh, celaka aku! Mengapa aku tidak mampu berbuat seperti burung gagak ini, sehingga aku dapat menguburkan mayat saudaraku ini?\" Maka jadilah dia termasuk orang yang menyesal"},{id:32,text:"\u0645\u0650\u0646\u06e1 \u0623\u064e\u062c\u06e1\u0644\u0650 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0643\u064e\u062a\u064e\u0628\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0646\u0650\u064a\u0653 \u0625\u0650\u0633\u06e1\u0631\u064e\u0640\u0670\u0653\u0621\u0650\u064a\u0644\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u06e5 \u0645\u064e\u0646 \u0642\u064e\u062a\u064e\u0644\u064e \u0646\u064e\u0641\u06e1\u0633\u064e\u06e2\u0627 \u0628\u0650\u063a\u064e\u064a\u06e1\u0631\u0650 \u0646\u064e\u0641\u06e1\u0633\u064d \u0623\u064e\u0648\u06e1 \u0641\u064e\u0633\u064e\u0627\u062f\u0656 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0641\u064e\u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u0642\u064e\u062a\u064e\u0644\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u062c\u064e\u0645\u0650\u064a\u0639\u0657\u0627 \u0648\u064e\u0645\u064e\u0646\u06e1 \u0623\u064e\u062d\u06e1\u064a\u064e\u0627\u0647\u064e\u0627 \u0641\u064e\u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u062d\u06e1\u064a\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u062c\u064e\u0645\u0650\u064a\u0639\u0657\u0627\u06da \u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u062a\u06e1\u0647\u064f\u0645\u06e1 \u0631\u064f\u0633\u064f\u0644\u064f\u0646\u064e\u0627 \u0628\u0650\u0671\u0644\u06e1\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0650 \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u0657\u0627 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645 \u0628\u064e\u0639\u06e1\u062f\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0644\u064e\u0645\u064f\u0633\u06e1\u0631\u0650\u0641\u064f\u0648\u0646\u064e",translation:"Oleh karena itu Kami tetapkan (suatu hukum) bagi Bani Israil, bahwa barang siapa membunuh seseorang, bukan karena orang itu membunuh orang lain,273) atau bukan karena berbuat kerusakan di bumi, maka seakan-akan dia telah membunuh semua manusia.274) Barang siapa memelihara kehidupan seorang manusia, maka seakan-akan dia telah memelihara kehidupan semua manusia. Sesungguhnya Rasul Kami telah datang kepada mereka dengan (membawa) keterangan-keterangan yang jelas. Tetapi kemudian banyak di antara mereka setelah itu melampaui batas di bumi"},{id:33,text:"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u062c\u064e\u0632\u064e\u0640\u0670\u0653\u0624\u064f\u0627\u0652 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u062d\u064e\u0627\u0631\u0650\u0628\u064f\u0648\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f\u06e5 \u0648\u064e\u064a\u064e\u0633\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0641\u064e\u0633\u064e\u0627\u062f\u064b\u0627 \u0623\u064e\u0646 \u064a\u064f\u0642\u064e\u062a\u0651\u064e\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0648\u06e1 \u064a\u064f\u0635\u064e\u0644\u0651\u064e\u0628\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0648\u06e1 \u062a\u064f\u0642\u064e\u0637\u0651\u064e\u0639\u064e \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u0647\u0650\u0645\u06e1 \u0648\u064e\u0623\u064e\u0631\u06e1\u062c\u064f\u0644\u064f\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u062e\u0650\u0644\u064e\u0670\u0641\u064d \u0623\u064e\u0648\u06e1 \u064a\u064f\u0646\u0641\u064e\u0648\u06e1\u0627\u0652 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u062e\u0650\u0632\u06e1\u064a\u065e \u0641\u0650\u064a \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627\u06d6 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u064c",translation:"(Hukuman bagi orang-orang yang memerangi Allah dan Rasul-Nya dan membuat kerusakan di bumi, hanyalah dibunuh atau disalib, atau dipotong tangan dan kaki mereka secara silang,275) atau diasingkan dari tempat kediamannya. Yang demikian itu kehinaan bagi mereka di dunia, dan di akhirat mereka mendapat azab yang besar"},{id:34,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u0627\u0628\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650 \u0623\u064e\u0646 \u062a\u064e\u0642\u06e1\u062f\u0650\u0631\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1\u06d6 \u0641\u064e\u0671\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u065e",translation:"Kecuali orang-orang yang bertobat sebelum kamu dapat menguasai mereka; maka ketahuilah, bahwa Allah Maha Pengampun, Maha Penyayang"},{id:35,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0671\u0628\u06e1\u062a\u064e\u063a\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0671\u0644\u06e1\u0648\u064e\u0633\u0650\u064a\u0644\u064e\u0629\u064e \u0648\u064e\u062c\u064e\u0670\u0647\u0650\u062f\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650\u0647\u0650\u06e6 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064f\u0641\u06e1\u0644\u0650\u062d\u064f\u0648\u0646\u064e",translation:"Wahai orang-orang yang beriman! Bertakwalah kepada Allah dan carilah wasilah (jalan) untuk mendekatkan diri kepada-Nya, dan berjihadlah (berjuanglah) di jalan-Nya, agar kamu beruntung"},{id:36,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0644\u064e\u0648\u06e1 \u0623\u064e\u0646\u0651\u064e \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u062c\u064e\u0645\u0650\u064a\u0639\u0657\u0627 \u0648\u064e\u0645\u0650\u062b\u06e1\u0644\u064e\u0647\u064f\u06e5 \u0645\u064e\u0639\u064e\u0647\u064f\u06e5 \u0644\u0650\u064a\u064e\u0641\u06e1\u062a\u064e\u062f\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6 \u0645\u0650\u0646\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u0645\u064e\u0627 \u062a\u064f\u0642\u064f\u0628\u0651\u0650\u0644\u064e \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Sesungguhnya orang-orang yang kafir, seandainya mereka memilki segala apa yang ada di bumi dan ditambah dengan sebanyak itu (lagi) untuk menebus diri mereka dari azab pada hari Kiamat, niscaya semua (tebusan) itu tidak akan diterima dari mereka. Mereka (tetap) mendapat azab yang pedih"},{id:37,text:"\u064a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0623\u064e\u0646 \u064a\u064e\u062e\u06e1\u0631\u064f\u062c\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0648\u064e\u0645\u064e\u0627 \u0647\u064f\u0645 \u0628\u0650\u062e\u064e\u0670\u0631\u0650\u062c\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u06e1\u0647\u064e\u0627\u06d6 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u065e \u0645\u0651\u064f\u0642\u0650\u064a\u0645\u065e",translation:"Mereka ingin keluar dari neraka, tetapi tidak akan dapat keluar dari sana. Dan mereka mendapat azab yang kekal"},{id:38,text:"\u0648\u064e\u0671\u0644\u0633\u0651\u064e\u0627\u0631\u0650\u0642\u064f \u0648\u064e\u0671\u0644\u0633\u0651\u064e\u0627\u0631\u0650\u0642\u064e\u0629\u064f \u0641\u064e\u0671\u0642\u06e1\u0637\u064e\u0639\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u064e\u0647\u064f\u0645\u064e\u0627 \u062c\u064e\u0632\u064e\u0627\u0653\u0621\u064e\u06e2 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064e\u0627 \u0646\u064e\u0643\u064e\u0670\u0644\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0632\u0650\u064a\u0632\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u065e",translation:"Adapun orang laki-laki maupun perempuan yang mencuri, potonglah tangan keduanya (sebagai) balasan atas perbuatan yang mereka lakukan dan sebagai siksaan dari Allah. Dan Allah Mahaperkasa, Mahabijaksana"},{id:39,text:"\u0641\u064e\u0645\u064e\u0646 \u062a\u064e\u0627\u0628\u064e \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0638\u064f\u0644\u06e1\u0645\u0650\u0647\u0650\u06e6 \u0648\u064e\u0623\u064e\u0635\u06e1\u0644\u064e\u062d\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u062a\u064f\u0648\u0628\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064c",translation:"Tetapi barang siapa bertobat setelah melakukan kejahatan itu dan memperbaiki diri, maka sesungguhnya Allah menerima tobatnya. Sungguh, Allah Maha Pengampun, Maha Penyayang"},{id:40,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u06e1 \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0647\u064f\u06e5 \u0645\u064f\u0644\u06e1\u0643\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064f \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0648\u064e\u064a\u064e\u063a\u06e1\u0641\u0650\u0631\u064f \u0644\u0650\u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0642\u064e\u062f\u0650\u064a\u0631\u065e",translation:"Tidakkah kamu tahu, bahwa Allah memiliki seluruh kerajaan langit dan bumi, Dia menyiksa siapa yang Dia kehendaki dan mengampuni siapa yang Dia kehendaki. Allah Mahakuasa atas segala sesuatu"},{id:41,text:"\u06de\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064f \u0644\u064e\u0627 \u064a\u064e\u062d\u06e1\u0632\u064f\u0646\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0633\u064e\u0670\u0631\u0650\u0639\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0643\u064f\u0641\u06e1\u0631\u0650 \u0645\u0650\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0621\u064e\u0627\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0623\u064e\u0641\u06e1\u0648\u064e\u0670\u0647\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0644\u064e\u0645\u06e1 \u062a\u064f\u0624\u06e1\u0645\u0650\u0646 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u06e1\u06db \u0648\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064e\u0627\u062f\u064f\u0648\u0627\u0652\u06db \u0633\u064e\u0645\u0651\u064e\u0640\u0670\u0639\u064f\u0648\u0646\u064e \u0644\u0650\u0644\u06e1\u0643\u064e\u0630\u0650\u0628\u0650 \u0633\u064e\u0645\u0651\u064e\u0640\u0670\u0639\u064f\u0648\u0646\u064e \u0644\u0650\u0642\u064e\u0648\u06e1\u0645\u064d \u0621\u064e\u0627\u062e\u064e\u0631\u0650\u064a\u0646\u064e \u0644\u064e\u0645\u06e1 \u064a\u064e\u0623\u06e1\u062a\u064f\u0648\u0643\u064e\u06d6 \u064a\u064f\u062d\u064e\u0631\u0651\u0650\u0641\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0643\u064e\u0644\u0650\u0645\u064e \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0645\u064e\u0648\u064e\u0627\u0636\u0650\u0639\u0650\u0647\u0650\u06e6\u06d6 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0625\u0650\u0646\u06e1 \u0623\u064f\u0648\u062a\u0650\u064a\u062a\u064f\u0645\u06e1 \u0647\u064e\u0670\u0630\u064e\u0627 \u0641\u064e\u062e\u064f\u0630\u064f\u0648\u0647\u064f \u0648\u064e\u0625\u0650\u0646 \u0644\u0651\u064e\u0645\u06e1 \u062a\u064f\u0624\u06e1\u062a\u064e\u0648\u06e1\u0647\u064f \u0641\u064e\u0671\u062d\u06e1\u0630\u064e\u0631\u064f\u0648\u0627\u0652\u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0631\u0650\u062f\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u0650\u062a\u06e1\u0646\u064e\u062a\u064e\u0647\u064f\u06e5 \u0641\u064e\u0644\u064e\u0646 \u062a\u064e\u0645\u06e1\u0644\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0634\u064e\u064a\u06e1\u0640\u0654\u064b\u0627\u06da \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0645\u06e1 \u064a\u064f\u0631\u0650\u062f\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0646 \u064a\u064f\u0637\u064e\u0647\u0651\u0650\u0631\u064e \u0642\u064f\u0644\u064f\u0648\u0628\u064e\u0647\u064f\u0645\u06e1\u06da \u0644\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u062e\u0650\u0632\u06e1\u064a\u065e\u06d6 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u065e",translation:"Wahai Rasul (Muhammad)! Janganlah engkau disedihkan karena mereka berlomba-lomba dalam kekafirannya. Yaitu orang-orang (munafik) yang mengatakan dengan mulut mereka, \"Kami telah beriman,\" padahal hati mereka belum beriman; dan juga orang-orang Yahudi yang sangat suka mendengar (berita-berita) bohong276) dan sangat suka mendengar (perkataan-perkataan) orang lain yang belum pernah datang kepadamu.277) Mereka mengubah kata-kata (Taurat) dari makna yang sebenarnya. Mereka mengatakan, \"Jika ini yang diberikan kepadamu (yang sudah diubah) terimalah, dan jika kamu diberi yang bukan ini, maka hati-hatilah.\" Barang siapa dikehendaki Allah untuk dibiarkan sesat, sedikit pun engkau tidak akan mampu menolak sesuatu pun dari Allah (untuk menolongnya). Mereka itu adalah orang-orang yang sudah tidak dikehendaki Allah untuk menyucikan hati mereka. Di dunia mereka mendapat kehinaan dan di akhirat akan mendapat azab yang besar"},{id:42,text:"\u0633\u064e\u0645\u0651\u064e\u0640\u0670\u0639\u064f\u0648\u0646\u064e \u0644\u0650\u0644\u06e1\u0643\u064e\u0630\u0650\u0628\u0650 \u0623\u064e\u0643\u0651\u064e\u0640\u0670\u0644\u064f\u0648\u0646\u064e \u0644\u0650\u0644\u0633\u0651\u064f\u062d\u06e1\u062a\u0650\u06da \u0641\u064e\u0625\u0650\u0646 \u062c\u064e\u0627\u0653\u0621\u064f\u0648\u0643\u064e \u0641\u064e\u0671\u062d\u06e1\u0643\u064f\u0645 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1 \u0623\u064e\u0639\u06e1\u0631\u0650\u0636\u06e1 \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0625\u0650\u0646 \u062a\u064f\u0639\u06e1\u0631\u0650\u0636\u06e1 \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0641\u064e\u0644\u064e\u0646 \u064a\u064e\u0636\u064f\u0631\u0651\u064f\u0648\u0643\u064e \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627\u06d6 \u0648\u064e\u0625\u0650\u0646\u06e1 \u062d\u064e\u0643\u064e\u0645\u06e1\u062a\u064e \u0641\u064e\u0671\u062d\u06e1\u0643\u064f\u0645 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0642\u0650\u0633\u06e1\u0637\u0650\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0671\u0644\u06e1\u0645\u064f\u0642\u06e1\u0633\u0650\u0637\u0650\u064a\u0646\u064e",translation:"Mereka sangat suka mendengar berita bohong, banyak memakan (makanan) yang haram.278) Jika mereka (orang Yahudi) datang kepadamu (Muhammad untuk meminta putusan), maka berilah putusan di antara mereka atau berpalinglah dari mereka, dan jika engkau berpaling dari mereka maka mereka tidak akan membahayakanmu sedikit pun. Tetapi jika engkau memutuskan (perkara mereka), maka putuskanlah dengan adil. Sesungguhnya Allah menyukai orang-orang yang adil"},{id:43,text:"\u0648\u064e\u0643\u064e\u064a\u06e1\u0641\u064e \u064a\u064f\u062d\u064e\u0643\u0651\u0650\u0645\u064f\u0648\u0646\u064e\u0643\u064e \u0648\u064e\u0639\u0650\u0646\u062f\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u062a\u0651\u064e\u0648\u06e1\u0631\u064e\u0649\u0670\u0629\u064f \u0641\u0650\u064a\u0647\u064e\u0627 \u062d\u064f\u0643\u06e1\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u06e1\u0646\u064e \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0630\u064e\u0670\u0644\u0650\u0643\u064e\u06da \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0628\u0650\u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dan bagaimana mereka akan mengangkatmu menjadi hakim mereka, padahal mereka mempunyai Taurat yang di dalamnya (ada) hukum Allah, nanti mereka berpaling (dari putusanmu) setelah itu? Sungguh, mereka bukan orang-orang yang beriman"},{id:44,text:"\u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0627 \u0671\u0644\u062a\u0651\u064e\u0648\u06e1\u0631\u064e\u0649\u0670\u0629\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0647\u064f\u062f\u0657\u0649 \u0648\u064e\u0646\u064f\u0648\u0631\u065e\u06da \u064a\u064e\u062d\u06e1\u0643\u064f\u0645\u064f \u0628\u0650\u0647\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064f\u0648\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u0633\u06e1\u0644\u064e\u0645\u064f\u0648\u0627\u0652 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064e\u0627\u062f\u064f\u0648\u0627\u0652 \u0648\u064e\u0671\u0644\u0631\u0651\u064e\u0628\u0651\u064e\u0640\u0670\u0646\u0650\u064a\u0651\u064f\u0648\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u062d\u06e1\u0628\u064e\u0627\u0631\u064f \u0628\u0650\u0645\u064e\u0627 \u0671\u0633\u06e1\u062a\u064f\u062d\u06e1\u0641\u0650\u0638\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0634\u064f\u0647\u064e\u062f\u064e\u0627\u0653\u0621\u064e\u06da \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062e\u06e1\u0634\u064e\u0648\u064f\u0627\u0652 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0648\u064e\u0671\u062e\u06e1\u0634\u064e\u0648\u06e1\u0646\u0650 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0634\u06e1\u062a\u064e\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u064a \u062b\u064e\u0645\u064e\u0646\u0657\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u0657\u0627\u06da \u0648\u064e\u0645\u064e\u0646 \u0644\u0651\u064e\u0645\u06e1 \u064a\u064e\u062d\u06e1\u0643\u064f\u0645 \u0628\u0650\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Sungguh, Kami yang menurunkan Kitab Taurat; di dalamnya (ada) petunjuk dan cahaya. Yang dengan Kitab itu para nabi yang berserah diri kepada Allah memberi putusan atas perkara orang Yahudi, demikian juga para ulama dan pendeta-pendeta mereka, sebab mereka diperintahkan memelihara kitab-kitab Allah dan mereka menjadi saksi terhadapnya. Karena itu janganlah kamu takut kepada manusia, (tetapi) takutlah kepada-Ku. Dan janganlah kamu jual ayat-ayat-Ku dengan harga murah. Barang siapa tidak memutuskan dengan apa yang diturunkan Allah, maka mereka itulah orang-orang kafir"},{id:45,text:"\u0648\u064e\u0643\u064e\u062a\u064e\u0628\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627\u0653 \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0646\u0651\u064e\u0641\u06e1\u0633\u064e \u0628\u0650\u0671\u0644\u0646\u0651\u064e\u0641\u06e1\u0633\u0650 \u0648\u064e\u0671\u0644\u06e1\u0639\u064e\u064a\u06e1\u0646\u064e \u0628\u0650\u0671\u0644\u06e1\u0639\u064e\u064a\u06e1\u0646\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0646\u0641\u064e \u0628\u0650\u0671\u0644\u06e1\u0623\u064e\u0646\u0641\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064f\u0630\u064f\u0646\u064e \u0628\u0650\u0671\u0644\u06e1\u0623\u064f\u0630\u064f\u0646\u0650 \u0648\u064e\u0671\u0644\u0633\u0651\u0650\u0646\u0651\u064e \u0628\u0650\u0671\u0644\u0633\u0651\u0650\u0646\u0651\u0650 \u0648\u064e\u0671\u0644\u06e1\u062c\u064f\u0631\u064f\u0648\u062d\u064e \u0642\u0650\u0635\u064e\u0627\u0635\u065e\u06da \u0641\u064e\u0645\u064e\u0646 \u062a\u064e\u0635\u064e\u062f\u0651\u064e\u0642\u064e \u0628\u0650\u0647\u0650\u06e6 \u0641\u064e\u0647\u064f\u0648\u064e \u0643\u064e\u0641\u0651\u064e\u0627\u0631\u064e\u0629\u065e \u0644\u0651\u064e\u0647\u064f\u06e5\u06da \u0648\u064e\u0645\u064e\u0646 \u0644\u0651\u064e\u0645\u06e1 \u064a\u064e\u062d\u06e1\u0643\u064f\u0645 \u0628\u0650\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Kami telah menetapkan bagi mereka di dalamnya (Taurat) bahwa nyawa (dibalas) dengan nyawa, mata dengan mata, hidung dengan hidung, telinga dengan telinga, gigi dengan gigi, dan luka-luka (pun) ada kisasnya (balasan yang sama). Barang siapa melepaskan (hak kisas)nya, maka itu (menjadi) penebus dosa baginya. Barang siapa tidak memutuskan perkara menurut apa yang diturunkan Allah, maka mereka itulah orang-orang zalim"},{id:46,text:"\u0648\u064e\u0642\u064e\u0641\u0651\u064e\u064a\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0621\u064e\u0627\u062b\u064e\u0670\u0631\u0650\u0647\u0650\u0645 \u0628\u0650\u0639\u0650\u064a\u0633\u064e\u0649 \u0671\u0628\u06e1\u0646\u0650 \u0645\u064e\u0631\u06e1\u064a\u064e\u0645\u064e \u0645\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u0657\u0627 \u0644\u0651\u0650\u0645\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u06e1\u0647\u0650 \u0645\u0650\u0646\u064e \u0671\u0644\u062a\u0651\u064e\u0648\u06e1\u0631\u064e\u0649\u0670\u0629\u0650\u06d6 \u0648\u064e\u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f \u0671\u0644\u06e1\u0625\u0650\u0646\u062c\u0650\u064a\u0644\u064e \u0641\u0650\u064a\u0647\u0650 \u0647\u064f\u062f\u0657\u0649 \u0648\u064e\u0646\u064f\u0648\u0631\u065e \u0648\u064e\u0645\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u0657\u0627 \u0644\u0651\u0650\u0645\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u06e1\u0647\u0650 \u0645\u0650\u0646\u064e \u0671\u0644\u062a\u0651\u064e\u0648\u06e1\u0631\u064e\u0649\u0670\u0629\u0650 \u0648\u064e\u0647\u064f\u062f\u0657\u0649 \u0648\u064e\u0645\u064e\u0648\u06e1\u0639\u0650\u0638\u064e\u0629\u0657 \u0644\u0651\u0650\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",translation:"Dan Kami teruskan jejak mereka dengan mengutus Isa putra Maryam, membenarkan Kitab yang sebelumnya, yaitu Taurat. Dan Kami menurunkan Injil kepadanya, di dalamnya terdapat petunjuk dan cahaya, dan membenarkan Kitab yang sebelumnya yaitu Taurat, dan sebagai petunjuk serta pengajaran untuk orang-orang yang bertakwa"},{id:47,text:"\u0648\u064e\u0644\u06e1\u064a\u064e\u062d\u06e1\u0643\u064f\u0645\u06e1 \u0623\u064e\u0647\u06e1\u0644\u064f \u0671\u0644\u06e1\u0625\u0650\u0646\u062c\u0650\u064a\u0644\u0650 \u0628\u0650\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u0650\u064a\u0647\u0650\u06da \u0648\u064e\u0645\u064e\u0646 \u0644\u0651\u064e\u0645\u06e1 \u064a\u064e\u062d\u06e1\u0643\u064f\u0645 \u0628\u0650\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0641\u064e\u0670\u0633\u0650\u0642\u064f\u0648\u0646\u064e",translation:"(Dan hendaklah pengikut Injil memutuskan perkara menurut apa yang diturunkan Allah di dalamnya.279) Barang siapa tidak memutuskan perkara menurut apa yang diturunkan Allah, maka mereka itulah orang-orang fasik"},{id:48,text:"\u0648\u064e\u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0645\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u0657\u0627 \u0644\u0651\u0650\u0645\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u06e1\u0647\u0650 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0648\u064e\u0645\u064f\u0647\u064e\u064a\u06e1\u0645\u0650\u0646\u064b\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u06d6 \u0641\u064e\u0671\u062d\u06e1\u0643\u064f\u0645 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645 \u0628\u0650\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u06e1 \u0623\u064e\u0647\u06e1\u0648\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650\u06da \u0644\u0650\u0643\u064f\u0644\u0651\u0656 \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u0634\u0650\u0631\u06e1\u0639\u064e\u0629\u0657 \u0648\u064e\u0645\u0650\u0646\u06e1\u0647\u064e\u0627\u062c\u0657\u0627\u06da \u0648\u064e\u0644\u064e\u0648\u06e1 \u0634\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u062c\u064e\u0639\u064e\u0644\u064e\u0643\u064f\u0645\u06e1 \u0623\u064f\u0645\u0651\u064e\u0629\u0657 \u0648\u064e\u0670\u062d\u0650\u062f\u064e\u0629\u0657 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u0644\u0651\u0650\u064a\u064e\u0628\u06e1\u0644\u064f\u0648\u064e\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u0645\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u064e\u0649\u0670\u0643\u064f\u0645\u06e1\u06d6 \u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u0628\u0650\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u062e\u064e\u064a\u06e1\u0631\u064e\u0670\u062a\u0650\u06da \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0631\u06e1\u062c\u0650\u0639\u064f\u0643\u064f\u0645\u06e1 \u062c\u064e\u0645\u0650\u064a\u0639\u0657\u0627 \u0641\u064e\u064a\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0643\u064f\u0645 \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u0650 \u062a\u064e\u062e\u06e1\u062a\u064e\u0644\u0650\u0641\u064f\u0648\u0646\u064e",translation:"Dan Kami telah menurunkan Kitab (Alquran) kepadamu (Muhammad) dengan membawa kebenaran, yang membenarkan kitab-kitab yang diturunkan sebelumnya dan menjaganya, 281) maka putuskanlah perkara mereka menurut apa yang di turunkan Allah dan janganlah engkau mengikuti keinginan mereka dengan meninggalkan kebenaran yang telah datang kepadamu. Untuk setiap umat di antara kamu,282) Kami berikan aturan dan jalan yang terang. Kalau Allah menghendaki, niscaya kamu dijadikan-Nya satu umat (saja), tetapi Allah hendak menguji kamu terhadap karunia yang telah di berikan-Nya kepadamu, maka berlomba-lombalah berbuat kebajikan. Hanya kepada Allah kamu semua kembali, lalu diberitahukan-Nya kepadamu terhadap apa yang dahulu kamu perselisihkan"},{id:49,text:"\u0648\u064e\u0623\u064e\u0646\u0650 \u0671\u062d\u06e1\u0643\u064f\u0645 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645 \u0628\u0650\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u06e1 \u0623\u064e\u0647\u06e1\u0648\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0671\u062d\u06e1\u0630\u064e\u0631\u06e1\u0647\u064f\u0645\u06e1 \u0623\u064e\u0646 \u064a\u064e\u0641\u06e1\u062a\u0650\u0646\u064f\u0648\u0643\u064e \u0639\u064e\u0646\u06e2 \u0628\u064e\u0639\u06e1\u0636\u0650 \u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e\u06d6 \u0641\u064e\u0625\u0650\u0646 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u06e1\u0627\u0652 \u0641\u064e\u0671\u0639\u06e1\u0644\u064e\u0645\u06e1 \u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0646 \u064a\u064f\u0635\u0650\u064a\u0628\u064e\u0647\u064f\u0645 \u0628\u0650\u0628\u064e\u0639\u06e1\u0636\u0650 \u0630\u064f\u0646\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u06e1\u06d7 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0641\u064e\u0670\u0633\u0650\u0642\u064f\u0648\u0646\u064e",translation:"dan hendaklah engkau memutuskan perkara di antara mereka menurut apa yang diturunkan Allah, dan janganlah engkau mengikuti keinginan mereka. Dan waspadalah terhadap mereka, jangan sampai mereka memperdayakan engkau terhadap sebagian apa yang telah diturunkan Allah kepadamu. Jika mereka berpaling (dari hukum yang telah diturunkan Allah), maka ketahuilah bahwa sesungguhnya Allah berkehendak menimpakan musibah kepada mereka disebabkan dosa-dosa mereka. Dan sungguh, kebanyakan manusia adalah orang-orang yang fasik"},{id:50,text:"\u0623\u064e\u0641\u064e\u062d\u064f\u0643\u06e1\u0645\u064e \u0671\u0644\u06e1\u062c\u064e\u0670\u0647\u0650\u0644\u0650\u064a\u0651\u064e\u0629\u0650 \u064a\u064e\u0628\u06e1\u063a\u064f\u0648\u0646\u064e\u06da \u0648\u064e\u0645\u064e\u0646\u06e1 \u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u064f\u0643\u06e1\u0645\u0657\u0627 \u0644\u0651\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064f\u0648\u0642\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Apakah hukum Jahiliah yang mereka kehendaki? (Hukum) siapakah yang lebih baik daripada (hukum) Allah bagi orang-orang yang meyakini (agamanya)"},{id:51,text:"\u06de\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u064a\u064e\u0647\u064f\u0648\u062f\u064e \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0635\u064e\u0670\u0631\u064e\u0649\u0670\u0653 \u0623\u064e\u0648\u06e1\u0644\u0650\u064a\u064e\u0627\u0653\u0621\u064e\u06d8 \u0628\u064e\u0639\u06e1\u0636\u064f\u0647\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1\u0644\u0650\u064a\u064e\u0627\u0653\u0621\u064f \u0628\u064e\u0639\u06e1\u0636\u0656\u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u0643\u064f\u0645\u06e1 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1\u06d7 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064e\u0647\u06e1\u062f\u0650\u064a \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Wahai orang-orang yang beriman! Janganlah kamu menjadikan orang Yahudi dan Nasrani sebagai teman setia(mu); mereka satu sama lain saling melindungi. Barang siapa di antara kamu yang menjadikan mereka teman setia, maka sesungguhnya dia termasuk golongan mereka. Sungguh, Allah tidak memberi petunjuk kepada orang yang zalim"},{id:52,text:"\u0641\u064e\u062a\u064e\u0631\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645 \u0645\u0651\u064e\u0631\u064e\u0636\u065e \u064a\u064f\u0633\u064e\u0670\u0631\u0650\u0639\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0647\u0650\u0645\u06e1 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0646\u064e\u062e\u06e1\u0634\u064e\u0649\u0670\u0653 \u0623\u064e\u0646 \u062a\u064f\u0635\u0650\u064a\u0628\u064e\u0646\u064e\u0627 \u062f\u064e\u0627\u0653\u0626\u0650\u0631\u064e\u0629\u065e\u06da \u0641\u064e\u0639\u064e\u0633\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0646 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e \u0628\u0650\u0671\u0644\u06e1\u0641\u064e\u062a\u06e1\u062d\u0650 \u0623\u064e\u0648\u06e1 \u0623\u064e\u0645\u06e1\u0631\u0656 \u0645\u0651\u0650\u0646\u06e1 \u0639\u0650\u0646\u062f\u0650\u0647\u0650\u06e6 \u0641\u064e\u064a\u064f\u0635\u06e1\u0628\u0650\u062d\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627\u0653 \u0623\u064e\u0633\u064e\u0631\u0651\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0653 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u06e1 \u0646\u064e\u0670\u062f\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Maka kamu akan melihat orang-orang yang hatinya berpenyakit segera mendekati mereka (Yahudi dan Nasrani), seraya berkata, \"Kami takut akan mendapat bencana.\" Mudah-mudahan Allah akan mendatangkan kemenangan (kepada Rasul-Nya), atau sesuatu keputusan dari sisi-Nya, sehingga mereka menjadi menyesal terhadap apa yang mereka rahasiakan dalam diri mereka"},{id:53,text:"\u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u0642\u06e1\u0633\u064e\u0645\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062c\u064e\u0647\u06e1\u062f\u064e \u0623\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u0650\u0647\u0650\u0645\u06e1 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0645\u064e\u0639\u064e\u0643\u064f\u0645\u06e1\u06da \u062d\u064e\u0628\u0650\u0637\u064e\u062a\u06e1 \u0623\u064e\u0639\u06e1\u0645\u064e\u0670\u0644\u064f\u0647\u064f\u0645\u06e1 \u0641\u064e\u0623\u064e\u0635\u06e1\u0628\u064e\u062d\u064f\u0648\u0627\u0652 \u062e\u064e\u0670\u0633\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan orang-orang yang beriman akan berkata, \"Inikah orang yang bersumpah secara sungguh-sungguh dengan (nama) Allah, bahwa mereka benar-benar bersama kamu?\" Segala amal mereka menjadi sia-sia, sehingga mereka menjadi orang-orang yang rugi"},{id:54,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0645\u064e\u0646 \u064a\u064e\u0631\u06e1\u062a\u064e\u062f\u0651\u064e \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u0639\u064e\u0646 \u062f\u0650\u064a\u0646\u0650\u0647\u0650\u06e6 \u0641\u064e\u0633\u064e\u0648\u06e1\u0641\u064e \u064a\u064e\u0623\u06e1\u062a\u0650\u064a \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064f\u062d\u0650\u0628\u0651\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u064a\u064f\u062d\u0650\u0628\u0651\u064f\u0648\u0646\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u0630\u0650\u0644\u0651\u064e\u0629\u064d \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0623\u064e\u0639\u0650\u0632\u0651\u064e\u0629\u064d \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u064a\u064f\u062c\u064e\u0670\u0647\u0650\u062f\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062e\u064e\u0627\u0641\u064f\u0648\u0646\u064e \u0644\u064e\u0648\u06e1\u0645\u064e\u0629\u064e \u0644\u064e\u0627\u0653\u0626\u0650\u0645\u0656\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u0636\u06e1\u0644\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064f\u0624\u06e1\u062a\u0650\u064a\u0647\u0650 \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0670\u0633\u0650\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u064c",translation:"Wahai orang-orang yang beriman! Barang siapa di antara kamu yang murtad (keluar) dari agamanya, maka kelak Allah akan mendatangkan suatu kaum, Dia mencintai mereka dan mereka pun mencintai-Nya, dan bersikap lemah lembut terhadap orang-orang yang beriman, tetapi bersikap keras terhadap orang-orang kafir, yang berjihad di jalan Allah, dan yang tidak takut kepada celaan orang yang suka mencela. Itulah karunia Allah yang diberikan-Nya kepada siapa yang Dia kehendaki. Dan Allah Mahaluas (pemberian-Nya), Maha Mengetahui"},{id:55,text:"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0648\u064e\u0644\u0650\u064a\u0651\u064f\u0643\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0647\u064f\u06e5 \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0642\u0650\u064a\u0645\u064f\u0648\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u064a\u064f\u0624\u06e1\u062a\u064f\u0648\u0646\u064e \u0671\u0644\u0632\u0651\u064e\u0643\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u0647\u064f\u0645\u06e1 \u0631\u064e\u0670\u0643\u0650\u0639\u064f\u0648\u0646\u064e",translation:"Sesungguhnya penolongmu hanyalah Allah, Rasul-Nya, dan orang-orang yang beriman, yang melaksanakan salat dan menunaikan zakat, seraya tunduk (kepada Allah)"},{id:56,text:"\u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f\u06e5 \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u062d\u0650\u0632\u06e1\u0628\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u063a\u064e\u0670\u0644\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Dan barang siapa menjadikan Allah, Rasul-Nya dan orang-orang yang beriman sebagai penolongnya, maka sungguh, pengikut (agama) Allah itulah yang menang"},{id:57,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0627\u0652 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627\u0652 \u062f\u0650\u064a\u0646\u064e\u0643\u064f\u0645\u06e1 \u0647\u064f\u0632\u064f\u0648\u0657\u0627 \u0648\u064e\u0644\u064e\u0639\u0650\u0628\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0671\u0644\u06e1\u0643\u064f\u0641\u0651\u064e\u0627\u0631\u064e \u0623\u064e\u0648\u06e1\u0644\u0650\u064a\u064e\u0627\u0653\u0621\u064e\u06da \u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645 \u0645\u0651\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Wahai orang-orang yang beriman! Janganlah kamu menjadikan pemimpinmu orang-orang yang membuat agamamu jadi bahan ejekan dan permainan, (yaitu) di antara orang-orang yang telah diberi kitab sebelummu, dan orang-orang kafir (orang musyrik). Dan bertakwalah kepada Allah jika kamu orang-orang beriman"},{id:58,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0646\u064e\u0627\u062f\u064e\u064a\u06e1\u062a\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u0650 \u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0647\u064e\u0627 \u0647\u064f\u0632\u064f\u0648\u0657\u0627 \u0648\u064e\u0644\u064e\u0639\u0650\u0628\u0657\u0627\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0642\u064e\u0648\u06e1\u0645\u065e \u0644\u0651\u064e\u0627 \u064a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Dan apabila kamu menyeru (mereka) untuk (melaksanakan) salat, mereka menjadikannya bahan ejekan dan permainan. Yang demikian itu adalah karena mereka orang-orang yang tidak mengerti"},{id:59,text:"\u0642\u064f\u0644\u06e1 \u064a\u064e\u0640\u0670\u0653\u0623\u064e\u0647\u06e1\u0644\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0647\u064e\u0644\u06e1 \u062a\u064e\u0646\u0642\u0650\u0645\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0651\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646\u06e1 \u0621\u064e\u0627\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064e\u0643\u064f\u0645\u06e1 \u0641\u064e\u0670\u0633\u0650\u0642\u064f\u0648\u0646\u064e",translation:"Katakanlah, \"Wahai Ahli Kitab! Apakah kamu memandang kami salah, hanya karena kami beriman kepada Allah, kepada apa yang diturunkan kepada kami dan kepada apa yang diturunkan sebelumnya? Sungguh, kebanyakan dari kamu adalah orang-orang yang fasik"},{id:60,text:"\u0642\u064f\u0644\u06e1 \u0647\u064e\u0644\u06e1 \u0623\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0643\u064f\u0645 \u0628\u0650\u0634\u064e\u0631\u0651\u0656 \u0645\u0651\u0650\u0646 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u064e\u062b\u064f\u0648\u0628\u064e\u0629\u064b \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0645\u064e\u0646 \u0644\u0651\u064e\u0639\u064e\u0646\u064e\u0647\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u063a\u064e\u0636\u0650\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0642\u0650\u0631\u064e\u062f\u064e\u0629\u064e \u0648\u064e\u0671\u0644\u06e1\u062e\u064e\u0646\u064e\u0627\u0632\u0650\u064a\u0631\u064e \u0648\u064e\u0639\u064e\u0628\u064e\u062f\u064e \u0671\u0644\u0637\u0651\u064e\u0640\u0670\u063a\u064f\u0648\u062a\u064e\u06da \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0634\u064e\u0631\u0651\u065e \u0645\u0651\u064e\u0643\u064e\u0627\u0646\u0657\u0627 \u0648\u064e\u0623\u064e\u0636\u064e\u0644\u0651\u064f \u0639\u064e\u0646 \u0633\u064e\u0648\u064e\u0627\u0653\u0621\u0650 \u0671\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u0650",translation:"Katakanlah (Muhammad), \"Apakah akan aku beritakan kepadamu tentang orang yang lebih buruk pembalasannya dari (orang fasik) di sisi Allah? Yaitu, orang yang dilaknat dan dimurkai Allah, di antara mereka (ada) yang dijadikan kera dan babi283) dan (orang yang) menyembah Tagut.\" Mereka itu lebih buruk tempatnya dan lebih tersesat dari jalan yang lurus"},{id:61,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064f\u0648\u0643\u064f\u0645\u06e1 \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0621\u064e\u0627\u0645\u064e\u0646\u0651\u064e\u0627 \u0648\u064e\u0642\u064e\u062f \u062f\u0651\u064e\u062e\u064e\u0644\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u06e1\u0643\u064f\u0641\u06e1\u0631\u0650 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0642\u064e\u062f\u06e1 \u062e\u064e\u0631\u064e\u062c\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0643\u06e1\u062a\u064f\u0645\u064f\u0648\u0646\u064e",translation:"Dan apabila mereka (Yahudi atau munafik) datang kepadamu, mereka mengatakan, \"Kami telah beriman,\" padahal mereka datang kepadamu dengan kekafiran dan mereka pergi pun demikian; dan Allah lebih mengetahui apa yang mereka sembunyikan"},{id:62,text:"\u0648\u064e\u062a\u064e\u0631\u064e\u0649\u0670 \u0643\u064e\u062b\u0650\u064a\u0631\u0657\u0627 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u064a\u064f\u0633\u064e\u0670\u0631\u0650\u0639\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0625\u0650\u062b\u06e1\u0645\u0650 \u0648\u064e\u0671\u0644\u06e1\u0639\u064f\u062f\u06e1\u0648\u064e\u0670\u0646\u0650 \u0648\u064e\u0623\u064e\u0643\u06e1\u0644\u0650\u0647\u0650\u0645\u064f \u0671\u0644\u0633\u0651\u064f\u062d\u06e1\u062a\u064e\u06da \u0644\u064e\u0628\u0650\u0626\u06e1\u0633\u064e \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan kamu akan melihat banyak di antara mereka (orang Yahudi) berlomba dalam berbuat dosa, permusuhan dan memakan yang haram. Sungguh, sangat buruk apa yang mereka perbuat"},{id:63,text:"\u0644\u064e\u0648\u06e1\u0644\u064e\u0627 \u064a\u064e\u0646\u06e1\u0647\u064e\u0649\u0670\u0647\u064f\u0645\u064f \u0671\u0644\u0631\u0651\u064e\u0628\u0651\u064e\u0640\u0670\u0646\u0650\u064a\u0651\u064f\u0648\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u062d\u06e1\u0628\u064e\u0627\u0631\u064f \u0639\u064e\u0646 \u0642\u064e\u0648\u06e1\u0644\u0650\u0647\u0650\u0645\u064f \u0671\u0644\u06e1\u0625\u0650\u062b\u06e1\u0645\u064e \u0648\u064e\u0623\u064e\u0643\u06e1\u0644\u0650\u0647\u0650\u0645\u064f \u0671\u0644\u0633\u0651\u064f\u062d\u06e1\u062a\u064e\u06da \u0644\u064e\u0628\u0650\u0626\u06e1\u0633\u064e \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0635\u06e1\u0646\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Mengapa para ulama dan para pendeta mereka tidak melarang mereka mengucapkan perkataan bohong dan memakan yang haram? Sungguh, sangat buruk apa yang mereka perbuat"},{id:64,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e\u062a\u0650 \u0671\u0644\u06e1\u064a\u064e\u0647\u064f\u0648\u062f\u064f \u064a\u064e\u062f\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u063a\u06e1\u0644\u064f\u0648\u0644\u064e\u0629\u064c\u06da \u063a\u064f\u0644\u0651\u064e\u062a\u06e1 \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u0647\u0650\u0645\u06e1 \u0648\u064e\u0644\u064f\u0639\u0650\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0645\u064e\u0627 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652\u06d8 \u0628\u064e\u0644\u06e1 \u064a\u064e\u062f\u064e\u0627\u0647\u064f \u0645\u064e\u0628\u06e1\u0633\u064f\u0648\u0637\u064e\u062a\u064e\u0627\u0646\u0650 \u064a\u064f\u0646\u0641\u0650\u0642\u064f \u0643\u064e\u064a\u06e1\u0641\u064e \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06da \u0648\u064e\u0644\u064e\u064a\u064e\u0632\u0650\u064a\u062f\u064e\u0646\u0651\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u0657\u0627 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064e \u0637\u064f\u063a\u06e1\u064a\u064e\u0670\u0646\u0657\u0627 \u0648\u064e\u0643\u064f\u0641\u06e1\u0631\u0657\u0627\u06da \u0648\u064e\u0623\u064e\u0644\u06e1\u0642\u064e\u064a\u06e1\u0646\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0639\u064e\u062f\u064e\u0670\u0648\u064e\u0629\u064e \u0648\u064e\u0671\u0644\u06e1\u0628\u064e\u063a\u06e1\u0636\u064e\u0627\u0653\u0621\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650\u06da \u0643\u064f\u0644\u0651\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0648\u06e1\u0642\u064e\u062f\u064f\u0648\u0627\u0652 \u0646\u064e\u0627\u0631\u0657\u0627 \u0644\u0651\u0650\u0644\u06e1\u062d\u064e\u0631\u06e1\u0628\u0650 \u0623\u064e\u0637\u06e1\u0641\u064e\u0623\u064e\u0647\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06da \u0648\u064e\u064a\u064e\u0633\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0641\u064e\u0633\u064e\u0627\u062f\u0657\u0627\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0671\u0644\u06e1\u0645\u064f\u0641\u06e1\u0633\u0650\u062f\u0650\u064a\u0646\u064e",translation:"(Dan orang-orang Yahudi berkata, \"Tangan Allah terbelenggu.\"284) Sebenarnya tangan merekalah yang dibelenggu dan merekalah yang dilaknat disebabkan apa yang telah mereka katakan itu, padahal kedua tangan Allah285) terbuka; Dia memberi rezeki sebagaimana Dia kehendaki. Dan (Alquran) yang diturunkan kepadamu dari Tuhanmu itu pasti akan menambah kedurhakaan dan kekafiran bagi kebanyakan mereka. Dan Kami timbulkan permusuhan dan kebencian di antara mereka sampai hari Kiamat. Setiap mereka menyalakan api peperangan, Allah memadamkannya. Dan mereka berusaha (menimbulkan) kerusakan di bumi. Dan Allah tidak menyukai orang-orang yang berbuat kerusakan"},{id:65,text:"\u0648\u064e\u0644\u064e\u0648\u06e1 \u0623\u064e\u0646\u0651\u064e \u0623\u064e\u0647\u06e1\u0644\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064e\u0648\u06e1\u0627\u0652 \u0644\u064e\u0643\u064e\u0641\u0651\u064e\u0631\u06e1\u0646\u064e\u0627 \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0633\u064e\u064a\u0651\u0650\u0640\u0654\u064e\u0627\u062a\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0644\u064e\u0623\u064e\u062f\u06e1\u062e\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0650 \u0671\u0644\u0646\u0651\u064e\u0639\u0650\u064a\u0645\u0650",translation:"Dan sekiranya Ahli Kitab itu beriman dan bertakwa; niscaya Kami hapus kesalahan-kesalahan mereka dan mereka tentu Kami masukkan ke dalam surga-surga yang penuh kenikmatan"},{id:66,text:"\u0648\u064e\u0644\u064e\u0648\u06e1 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u0642\u064e\u0627\u0645\u064f\u0648\u0627\u0652 \u0671\u0644\u062a\u0651\u064e\u0648\u06e1\u0631\u064e\u0649\u0670\u0629\u064e \u0648\u064e\u0671\u0644\u06e1\u0625\u0650\u0646\u062c\u0650\u064a\u0644\u064e \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0644\u064e\u0623\u064e\u0643\u064e\u0644\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0641\u064e\u0648\u06e1\u0642\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0645\u0650\u0646 \u062a\u064e\u062d\u06e1\u062a\u0650 \u0623\u064e\u0631\u06e1\u062c\u064f\u0644\u0650\u0647\u0650\u0645\u06da \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0623\u064f\u0645\u0651\u064e\u0629\u065e \u0645\u0651\u064f\u0642\u06e1\u062a\u064e\u0635\u0650\u062f\u064e\u0629\u065e\u06d6 \u0648\u064e\u0643\u064e\u062b\u0650\u064a\u0631\u065e \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0633\u064e\u0627\u0653\u0621\u064e \u0645\u064e\u0627 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan sekiranya mereka sungguh-sungguh menjalankan (hukum) Taurat, Injil dan (Alquran) yang diturunkan kepada mereka dari Tuhannya, niscaya mereka akan mendapat makanan dari atas mereka dan dari bawah kaki mereka.286) Di antara mereka ada sekelompok yang jujur dan taat. Dan banyak di antara mereka sangat buruk apa yang mereka kerjakan"},{id:67,text:"\u06de\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064f \u0628\u064e\u0644\u0651\u0650\u063a\u06e1 \u0645\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064e\u06d6 \u0648\u064e\u0625\u0650\u0646 \u0644\u0651\u064e\u0645\u06e1 \u062a\u064e\u0641\u06e1\u0639\u064e\u0644\u06e1 \u0641\u064e\u0645\u064e\u0627 \u0628\u064e\u0644\u0651\u064e\u063a\u06e1\u062a\u064e \u0631\u0650\u0633\u064e\u0627\u0644\u064e\u062a\u064e\u0647\u064f\u06e5\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0639\u06e1\u0635\u0650\u0645\u064f\u0643\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650\u06d7 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064e\u0647\u06e1\u062f\u0650\u064a \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Wahai Rasul! Sampaikanlah apa yang diturunkan Tuhanmu kepadamu. Jika tidak engkau lakukan (apa yang diperintahkan itu) berarti engkau tidak menyampaikan amanat-Nya. Dan Allah memelihara engkau dari (gangguan) manusia.287) Sungguh, Allah tidak memberi petunjuk kepada orang-orang kafir"},{id:68,text:"\u0642\u064f\u0644\u06e1 \u064a\u064e\u0640\u0670\u0653\u0623\u064e\u0647\u06e1\u0644\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0644\u064e\u0633\u06e1\u062a\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0634\u064e\u064a\u06e1\u0621\u064d \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062a\u064f\u0642\u0650\u064a\u0645\u064f\u0648\u0627\u0652 \u0671\u0644\u062a\u0651\u064e\u0648\u06e1\u0631\u064e\u0649\u0670\u0629\u064e \u0648\u064e\u0671\u0644\u06e1\u0625\u0650\u0646\u062c\u0650\u064a\u0644\u064e \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1\u06d7 \u0648\u064e\u0644\u064e\u064a\u064e\u0632\u0650\u064a\u062f\u064e\u0646\u0651\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u0657\u0627 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064e \u0637\u064f\u063a\u06e1\u064a\u064e\u0670\u0646\u0657\u0627 \u0648\u064e\u0643\u064f\u0641\u06e1\u0631\u0657\u0627\u06d6 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0623\u06e1\u0633\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Katakanlah (Muhammad), \"Wahai Ahli Kitab! Kamu tidak dipandang beragama sedikit pun hingga kamu menegakkan ajaran-ajaran Taurat, Injil dan (Alquran) yang diturunkan Tuhanmu kepadamu.\" Dan apa yang diturunkan Tuhanmu kepadamu pasti akan membuat banyak di antara mereka lebih durhaka dan lebih ingkar, maka janganlah engkau berputus asa terhadap orang-orang kafir itu"},{id:69,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064e\u0627\u062f\u064f\u0648\u0627\u0652 \u0648\u064e\u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0628\u0650\u0640\u0654\u064f\u0648\u0646\u064e \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0635\u064e\u0670\u0631\u064e\u0649\u0670 \u0645\u064e\u0646\u06e1 \u0621\u064e\u0627\u0645\u064e\u0646\u064e \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u0650 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064e \u0635\u064e\u0670\u0644\u0650\u062d\u0657\u0627 \u0641\u064e\u0644\u064e\u0627 \u062e\u064e\u0648\u06e1\u0641\u064c \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u06e1 \u064a\u064e\u062d\u06e1\u0632\u064e\u0646\u064f\u0648\u0646\u064e",translation:"Sesungguhnya orang-orang yang beriman, orang-orang Yahudi, \u1e62\u0101bi\u012bn dan orang-orang Nasrani, barang siapa beriman kepada Allah, kepada hari kemudian dan berbuat kebajikan, maka tidak ada rasa khawatir padanya dan mereka tidak bersedih hati"},{id:70,text:"\u0644\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u062e\u064e\u0630\u06e1\u0646\u064e\u0627 \u0645\u0650\u064a\u062b\u064e\u0670\u0642\u064e \u0628\u064e\u0646\u0650\u064a\u0653 \u0625\u0650\u0633\u06e1\u0631\u064e\u0640\u0670\u0653\u0621\u0650\u064a\u0644\u064e \u0648\u064e\u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0631\u064f\u0633\u064f\u0644\u0657\u0627\u06d6 \u0643\u064f\u0644\u0651\u064e\u0645\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u06e1 \u0631\u064e\u0633\u064f\u0648\u0644\u064f\u06e2 \u0628\u0650\u0645\u064e\u0627 \u0644\u064e\u0627 \u062a\u064e\u0647\u06e1\u0648\u064e\u0649\u0670\u0653 \u0623\u064e\u0646\u0641\u064f\u0633\u064f\u0647\u064f\u0645\u06e1 \u0641\u064e\u0631\u0650\u064a\u0642\u0657\u0627 \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0648\u064e\u0641\u064e\u0631\u0650\u064a\u0642\u0657\u0627 \u064a\u064e\u0642\u06e1\u062a\u064f\u0644\u064f\u0648\u0646\u064e",translation:"(Sesungguhnya Kami telah mengambil perjanjian dari Bani Israil,288) dan telah Kami utus kepada mereka Rasul-rasul. Tetapi setiap rasul datang kepada mereka dengan membawa apa yang tidak sesuai dengan keinginan mereka, (maka) sebagian (dari Rasul itu) mereka dustakan dan sebagian yang lain mereka bunuh"},{id:71,text:"\u0648\u064e\u062d\u064e\u0633\u0650\u0628\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0641\u0650\u062a\u06e1\u0646\u064e\u0629\u065e \u0641\u064e\u0639\u064e\u0645\u064f\u0648\u0627\u0652 \u0648\u064e\u0635\u064e\u0645\u0651\u064f\u0648\u0627\u0652 \u062b\u064f\u0645\u0651\u064e \u062a\u064e\u0627\u0628\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u062b\u064f\u0645\u0651\u064e \u0639\u064e\u0645\u064f\u0648\u0627\u0652 \u0648\u064e\u0635\u064e\u0645\u0651\u064f\u0648\u0627\u0652 \u0643\u064e\u062b\u0650\u064a\u0631\u065e \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u064e\u0635\u0650\u064a\u0631\u064f\u06e2 \u0628\u0650\u0645\u064e\u0627 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan mereka mengira bahwa tidak akan terjadi bencana apa pun (terhadap mereka dengan membunuh Nabi-nabi itu), karena itu mereka menjadi buta dan tuli, kemudian Allah menerima tobat mereka, lalu banyak di antara mereka buta dan tuli. Dan Allah Maha Melihat apa yang mereka kerjakan"},{id:72,text:"\u0644\u064e\u0642\u064e\u062f\u06e1 \u0643\u064e\u0641\u064e\u0631\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0645\u064e\u0633\u0650\u064a\u062d\u064f \u0671\u0628\u06e1\u0646\u064f \u0645\u064e\u0631\u06e1\u064a\u064e\u0645\u064e\u06d6 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u06e1\u0645\u064e\u0633\u0650\u064a\u062d\u064f \u064a\u064e\u0670\u0628\u064e\u0646\u0650\u064a\u0653 \u0625\u0650\u0633\u06e1\u0631\u064e\u0640\u0670\u0653\u0621\u0650\u064a\u0644\u064e \u0671\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u06e1\u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0645\u064e\u0646 \u064a\u064f\u0634\u06e1\u0631\u0650\u0643\u06e1 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0642\u064e\u062f\u06e1 \u062d\u064e\u0631\u0651\u064e\u0645\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u064e \u0648\u064e\u0645\u064e\u0623\u06e1\u0648\u064e\u0649\u0670\u0647\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u064f\u06d6 \u0648\u064e\u0645\u064e\u0627 \u0644\u0650\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u06e1 \u0623\u064e\u0646\u0635\u064e\u0627\u0631\u0656",translation:"Sungguh, telah kafir orang-orang yang berkata, \"Sesungguhnya Allah itulah Al-Masih putra Maryam.\" padahal Al-Masih (sendiri) berkata, \"Wahai Bani Israil! Sembahlah Allah, Tuhanku dan Tuhanmu.\" Sesungguhnya barang siapa mempersekutukan (sesuatu dengan) Allah, maka sungguh, Allah mengharamkan surga baginya, dan tempatnya ialah neraka. Dan tidak ada seorang penolong pun bagi orang-orang zalim itu"},{id:73,text:"\u0644\u0651\u064e\u0642\u064e\u062f\u06e1 \u0643\u064e\u0641\u064e\u0631\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u062b\u064e\u0627\u0644\u0650\u062b\u064f \u062b\u064e\u0644\u064e\u0670\u062b\u064e\u0629\u0656\u06d8 \u0648\u064e\u0645\u064e\u0627 \u0645\u0650\u0646\u06e1 \u0625\u0650\u0644\u064e\u0670\u0647\u064d \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u065e \u0648\u064e\u0670\u062d\u0650\u062f\u065e\u06da \u0648\u064e\u0625\u0650\u0646 \u0644\u0651\u064e\u0645\u06e1 \u064a\u064e\u0646\u062a\u064e\u0647\u064f\u0648\u0627\u0652 \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0644\u064e\u064a\u064e\u0645\u064e\u0633\u0651\u064e\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064c",translation:"Sungguh, telah kafir orang-orang yang mengatakan bahwa Allah adalah salah satu dari yang tiga, padahal tidak ada tuhan (yang berhak disembah) selain Tuhan Yang Esa. Jika mereka tidak berhenti dari apa yang mereka katakan, pasti orang-orang yang kafir di antara mereka akan ditimpa azab yang pedih"},{id:74,text:"\u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u062a\u064f\u0648\u0628\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u064a\u064e\u0633\u06e1\u062a\u064e\u063a\u06e1\u0641\u0650\u0631\u064f\u0648\u0646\u064e\u0647\u064f\u06e5\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u065e",translation:"Mengapa mereka tidak bertobat kepada Allah dan memohon ampunan kepada-Nya? Allah Maha Pengampun, Maha Penyayang"},{id:75,text:"\u0645\u0651\u064e\u0627 \u0671\u0644\u06e1\u0645\u064e\u0633\u0650\u064a\u062d\u064f \u0671\u0628\u06e1\u0646\u064f \u0645\u064e\u0631\u06e1\u064a\u064e\u0645\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u065e \u0642\u064e\u062f\u06e1 \u062e\u064e\u0644\u064e\u062a\u06e1 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650 \u0671\u0644\u0631\u0651\u064f\u0633\u064f\u0644\u064f \u0648\u064e\u0623\u064f\u0645\u0651\u064f\u0647\u064f\u06e5 \u0635\u0650\u062f\u0651\u0650\u064a\u0642\u064e\u0629\u065e\u06d6 \u0643\u064e\u0627\u0646\u064e\u0627 \u064a\u064e\u0623\u06e1\u0643\u064f\u0644\u064e\u0627\u0646\u0650 \u0671\u0644\u0637\u0651\u064e\u0639\u064e\u0627\u0645\u064e\u06d7 \u0671\u0646\u0638\u064f\u0631\u06e1 \u0643\u064e\u064a\u06e1\u0641\u064e \u0646\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064f \u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0623\u0653\u064a\u064e\u0670\u062a\u0650 \u062b\u064f\u0645\u0651\u064e \u0671\u0646\u0638\u064f\u0631\u06e1 \u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u064a\u064f\u0624\u06e1\u0641\u064e\u0643\u064f\u0648\u0646\u064e",translation:"(Al-Masih putra Maryam hanyalah seorang Rasul. Sebelumnya pun sudah berlalu beberapa Rasul. Dan ibunya seorang yang berpegang teguh pada kebenaran. Keduanya biasa memakan makanan.289) Perhatikanlah bagaimana Kami menjelaskan ayat-ayat (tanda-tanda kekuasaan) kepada mereka (Ahli Kitab), kemudian perhatikanlah bagaimana mereka dipalingkan (oleh keinginan mereka)"},{id:76,text:"\u0642\u064f\u0644\u06e1 \u0623\u064e\u062a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0645\u06e1\u0644\u0650\u0643\u064f \u0644\u064e\u0643\u064f\u0645\u06e1 \u0636\u064e\u0631\u0651\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0641\u06e1\u0639\u0657\u0627\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0647\u064f\u0648\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u0650\u064a\u0639\u064f \u0671\u0644\u06e1\u0639\u064e\u0644\u0650\u064a\u0645\u064f",translation:"Katakanlah (Muhammad), \"Mengapa kamu menyembah makhluk selain Allah, sesuatu yang tidak dapat menimbulkan bencana kepadamu dan tidak (pula) memberi manfaat?\" Dan Allah Maha Mendengar, Maha Mengetahui"},{id:77,text:"\u0642\u064f\u0644\u06e1 \u064a\u064e\u0640\u0670\u0653\u0623\u064e\u0647\u06e1\u0644\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0644\u064e\u0627 \u062a\u064e\u063a\u06e1\u0644\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u062f\u0650\u064a\u0646\u0650\u0643\u064f\u0645\u06e1 \u063a\u064e\u064a\u06e1\u0631\u064e \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0647\u06e1\u0648\u064e\u0627\u0653\u0621\u064e \u0642\u064e\u0648\u06e1\u0645\u0656 \u0642\u064e\u062f\u06e1 \u0636\u064e\u0644\u0651\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f \u0648\u064e\u0623\u064e\u0636\u064e\u0644\u0651\u064f\u0648\u0627\u0652 \u0643\u064e\u062b\u0650\u064a\u0631\u0657\u0627 \u0648\u064e\u0636\u064e\u0644\u0651\u064f\u0648\u0627\u0652 \u0639\u064e\u0646 \u0633\u064e\u0648\u064e\u0627\u0653\u0621\u0650 \u0671\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u0650",translation:"Katakanlah (Muhammad), \"Wahai Ahli Kitab! Janganlah kamu berlebih-lebihan dengan cara tidak benar dalam agamamu. Dan janganlah kamu mengikuti keinginan orang-orang yang telah tersesat dahulu dan (telah) menyesatkan banyak (manusia), dan mereka sendiri tersesat dari jalan yang lurus"},{id:78,text:"\u0644\u064f\u0639\u0650\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0646\u0650\u064a\u0653 \u0625\u0650\u0633\u06e1\u0631\u064e\u0640\u0670\u0653\u0621\u0650\u064a\u0644\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0644\u0650\u0633\u064e\u0627\u0646\u0650 \u062f\u064e\u0627\u0648\u064f\u06e5\u062f\u064e \u0648\u064e\u0639\u0650\u064a\u0633\u064e\u0649 \u0671\u0628\u06e1\u0646\u0650 \u0645\u064e\u0631\u06e1\u064a\u064e\u0645\u064e\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0645\u064e\u0627 \u0639\u064e\u0635\u064e\u0648\u0627\u0652 \u0648\u0651\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u062a\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Orang-orang kafir dari Bani Israil telah dilaknat melalui lisan (ucapan) Dawud dan Isa putra Maryam. Yang demikian itu karena mereka durhaka dan selalu melampaui batas"},{id:79,text:"\u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u064a\u064e\u062a\u064e\u0646\u064e\u0627\u0647\u064e\u0648\u06e1\u0646\u064e \u0639\u064e\u0646 \u0645\u0651\u064f\u0646\u0643\u064e\u0631\u0656 \u0641\u064e\u0639\u064e\u0644\u064f\u0648\u0647\u064f\u06da \u0644\u064e\u0628\u0650\u0626\u06e1\u0633\u064e \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0641\u06e1\u0639\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Mereka tidak saling mencegah perbuatan mungkar yang selalu mereka perbuat. Sungguh, sangat buruk apa yang mereka perbuat"},{id:80,text:"\u062a\u064e\u0631\u064e\u0649\u0670 \u0643\u064e\u062b\u0650\u064a\u0631\u0657\u0627 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u064a\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u06e1\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652\u06da \u0644\u064e\u0628\u0650\u0626\u06e1\u0633\u064e \u0645\u064e\u0627 \u0642\u064e\u062f\u0651\u064e\u0645\u064e\u062a\u06e1 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u0646\u0641\u064f\u0633\u064f\u0647\u064f\u0645\u06e1 \u0623\u064e\u0646 \u0633\u064e\u062e\u0650\u0637\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0648\u064e\u0641\u0650\u064a \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0647\u064f\u0645\u06e1 \u062e\u064e\u0670\u0644\u0650\u062f\u064f\u0648\u0646\u064e",translation:"Kamu melihat banyak di antara mereka tolong menolong dengan orang-orang kafir (musyrik). Sungguh, sangat buruk apa yang mereka lakukan untuk diri mereka sendiri, yaitu kemurkaan Allah, dan mereka akan kekal dalam azab"},{id:81,text:"\u0648\u064e\u0644\u064e\u0648\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0645\u064e\u0627 \u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0647\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1\u0644\u0650\u064a\u064e\u0627\u0653\u0621\u064e \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u0657\u0627 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0641\u064e\u0670\u0633\u0650\u0642\u064f\u0648\u0646\u064e",translation:"Dan sekiranya mereka beriman kepada Allah, kepada Nabi (Muhammad) dan kepada apa yang diturunkan kepadanya, niscaya mereka tidak akan menjadikan orang musyrik itu sebagai teman setia. Tetapi banyak di antara mereka, orang-orang fasik"},{id:82,text:"\u06de\u0644\u064e\u062a\u064e\u062c\u0650\u062f\u064e\u0646\u0651\u064e \u0623\u064e\u0634\u064e\u062f\u0651\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0639\u064e\u062f\u064e\u0670\u0648\u064e\u0629\u0657 \u0644\u0651\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u064a\u064e\u0647\u064f\u0648\u062f\u064e \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u0634\u06e1\u0631\u064e\u0643\u064f\u0648\u0627\u0652\u06d6 \u0648\u064e\u0644\u064e\u062a\u064e\u062c\u0650\u062f\u064e\u0646\u0651\u064e \u0623\u064e\u0642\u06e1\u0631\u064e\u0628\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u0648\u064e\u062f\u0651\u064e\u0629\u0657 \u0644\u0651\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e\u0627 \u0646\u064e\u0635\u064e\u0670\u0631\u064e\u0649\u0670\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0642\u0650\u0633\u0651\u0650\u064a\u0633\u0650\u064a\u0646\u064e \u0648\u064e\u0631\u064f\u0647\u06e1\u0628\u064e\u0627\u0646\u0657\u0627 \u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Pasti akan kamu dapati orang yang paling keras permusuhannya terhadap orang-orang yang beriman, ialah orang-orang Yahudi dan orang-orang musyrik. Dan pasti akan kamu dapati orang yang paling dekat persahabatannya dengan orang-orang yang beriman ialah orang-orang yang berkata, \"Sesungguhnya kami adalah orang Nasrani.\" Yang demikian itu karena di antara mereka terdapat para pendeta dan para rahib, (juga) karena mereka tidak menyombongkan diri"},{id:83,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0633\u064e\u0645\u0650\u0639\u064f\u0648\u0627\u0652 \u0645\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0650 \u062a\u064e\u0631\u064e\u0649\u0670\u0653 \u0623\u064e\u0639\u06e1\u064a\u064f\u0646\u064e\u0647\u064f\u0645\u06e1 \u062a\u064e\u0641\u0650\u064a\u0636\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u062f\u0651\u064e\u0645\u06e1\u0639\u0650 \u0645\u0650\u0645\u0651\u064e\u0627 \u0639\u064e\u0631\u064e\u0641\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650\u06d6 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627\u0653 \u0621\u064e\u0627\u0645\u064e\u0646\u0651\u064e\u0627 \u0641\u064e\u0671\u0643\u06e1\u062a\u064f\u0628\u06e1\u0646\u064e\u0627 \u0645\u064e\u0639\u064e \u0671\u0644\u0634\u0651\u064e\u0640\u0670\u0647\u0650\u062f\u0650\u064a\u0646\u064e",translation:"Dan apabila mereka mendengarkan apa (Alquran) yang diturunkan kepada Rasul (Muhammad), kamu lihat mata mereka mencucurkan air mata disebabkan kebenaran yang telah mereka ketahui (dari kitab-kitab mereka sendiri), seraya berkata, \"Ya Tuhan, kami telah beriman, maka catatlah kami bersama orang-orang yang menjadi saksi (atas kebenaran Alquran dan kenabian Muhammad)"},{id:84,text:"\u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0646\u064e\u0627 \u0644\u064e\u0627 \u0646\u064f\u0624\u06e1\u0645\u0650\u0646\u064f \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0646\u064e\u0637\u06e1\u0645\u064e\u0639\u064f \u0623\u064e\u0646 \u064a\u064f\u062f\u06e1\u062e\u0650\u0644\u064e\u0646\u064e\u0627 \u0631\u064e\u0628\u0651\u064f\u0646\u064e\u0627 \u0645\u064e\u0639\u064e \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u0650\u064a\u0646\u064e",translation:"Dan mengapa kami tidak akan beriman kepada Allah dan kepada kebenaran yang datang kepada kami, padahal kami sangat ingin agar Tuhan kami memasukkan kami ke dalam golongan orang-orang yang saleh"},{id:85,text:"\u0641\u064e\u0623\u064e\u062b\u064e\u0670\u0628\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0656 \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0645\u0650\u0646 \u062a\u064e\u062d\u06e1\u062a\u0650\u0647\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u064f \u062e\u064e\u0670\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627\u06da \u0648\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062c\u064e\u0632\u064e\u0627\u0653\u0621\u064f \u0671\u0644\u06e1\u0645\u064f\u062d\u06e1\u0633\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Maka Allah memberi pahala kepada mereka atas perkataan yang telah mereka ucapkan, (yaitu) surga yang mengalir di bawahnya sungai-sungai, mereka kekal di dalamnya. Dan itulah balasan (bagi) orang-orang yang berbuat kebaikan"},{id:86,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627\u0653 \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u06e1\u062c\u064e\u062d\u0650\u064a\u0645\u0650",translation:"Dan orang-orang yang kafir serta mendustakan ayat-ayat Kami, mereka itulah penghuni neraka"},{id:87,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u062a\u064f\u062d\u064e\u0631\u0651\u0650\u0645\u064f\u0648\u0627\u0652 \u0637\u064e\u064a\u0651\u0650\u0628\u064e\u0670\u062a\u0650 \u0645\u064e\u0627\u0653 \u0623\u064e\u062d\u064e\u0644\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u062a\u064e\u062f\u064f\u0648\u0653\u0627\u0652\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0671\u0644\u06e1\u0645\u064f\u0639\u06e1\u062a\u064e\u062f\u0650\u064a\u0646\u064e",translation:"Wahai orang-orang yang beriman! Janganlah kamu mengharamkan apa yang baik yang telah dihalalkan Allah kepadamu, dan janganlah kamu melampaui batas. Sesungguhnya Allah tidak menyukai orang-orang yang melampaui batas"},{id:88,text:"\u0648\u064e\u0643\u064f\u0644\u064f\u0648\u0627\u0652 \u0645\u0650\u0645\u0651\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u062d\u064e\u0644\u064e\u0670\u0644\u0657\u0627 \u0637\u064e\u064a\u0651\u0650\u0628\u0657\u0627\u06da \u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064e\u0646\u062a\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6 \u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Dan makanlah dari apa yang telah diberikan Allah kepadamu sebagai rezeki yang halal dan baik, dan bertakwalah kepada Allah yang kamu beriman kepada-Nya"},{id:89,text:"\u0644\u064e\u0627 \u064a\u064f\u0624\u064e\u0627\u062e\u0650\u0630\u064f\u0643\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u063a\u06e1\u0648\u0650 \u0641\u0650\u064a\u0653 \u0623\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u064a\u064f\u0624\u064e\u0627\u062e\u0650\u0630\u064f\u0643\u064f\u0645 \u0628\u0650\u0645\u064e\u0627 \u0639\u064e\u0642\u0651\u064e\u062f\u062a\u0651\u064f\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u064e\u06d6 \u0641\u064e\u0643\u064e\u0641\u0651\u064e\u0640\u0670\u0631\u064e\u062a\u064f\u0647\u064f\u06e5\u0653 \u0625\u0650\u0637\u06e1\u0639\u064e\u0627\u0645\u064f \u0639\u064e\u0634\u064e\u0631\u064e\u0629\u0650 \u0645\u064e\u0633\u064e\u0670\u0643\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u06e1 \u0623\u064e\u0648\u06e1\u0633\u064e\u0637\u0650 \u0645\u064e\u0627 \u062a\u064f\u0637\u06e1\u0639\u0650\u0645\u064f\u0648\u0646\u064e \u0623\u064e\u0647\u06e1\u0644\u0650\u064a\u0643\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1 \u0643\u0650\u0633\u06e1\u0648\u064e\u062a\u064f\u0647\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1 \u062a\u064e\u062d\u06e1\u0631\u0650\u064a\u0631\u064f \u0631\u064e\u0642\u064e\u0628\u064e\u0629\u0656\u06d6 \u0641\u064e\u0645\u064e\u0646 \u0644\u0651\u064e\u0645\u06e1 \u064a\u064e\u062c\u0650\u062f\u06e1 \u0641\u064e\u0635\u0650\u064a\u064e\u0627\u0645\u064f \u062b\u064e\u0644\u064e\u0670\u062b\u064e\u0629\u0650 \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u0656\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0643\u064e\u0641\u0651\u064e\u0640\u0670\u0631\u064e\u0629\u064f \u0623\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u0650\u0643\u064f\u0645\u06e1 \u0625\u0650\u0630\u064e\u0627 \u062d\u064e\u0644\u064e\u0641\u06e1\u062a\u064f\u0645\u06e1\u06da \u0648\u064e\u0671\u062d\u06e1\u0641\u064e\u0638\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u064e\u0643\u064f\u0645\u06e1\u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0647\u0650\u06e6 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u0634\u06e1\u0643\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Allah tidak menghukum kamu disebabkan sumpah-sumpahmu yang tidak disengaja (untuk bersumpah), tetapi Dia menghukum kamu disebabkan sumpah-sumpah yang kamu sengaja, maka kafaratnya (denda pelanggaran sumpah) ialah memberi makan sepuluh orang miskin, yaitu dari makanan yang biasa kamu berikan kepada keluargamu, atau memberi mereka pakaian atau memerdekakan seorang hamba sahaya. Barang siapa tidak mampu melakukannya, maka (kafaratnya) berpuasalah tiga hari. Itulah kafarat sumpah-sumpahmu apabila kamu bersumpah. Dan jagalah sumpahmu. Demikianlah Allah menerangkan hukum-hukum-Nya kepadamu agar kamu bersyukur (kepada-Nya)"},{id:90,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0671\u0644\u06e1\u062e\u064e\u0645\u06e1\u0631\u064f \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u064a\u06e1\u0633\u0650\u0631\u064f \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0646\u0635\u064e\u0627\u0628\u064f \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0632\u06e1\u0644\u064e\u0670\u0645\u064f \u0631\u0650\u062c\u06e1\u0633\u065e \u0645\u0651\u0650\u0646\u06e1 \u0639\u064e\u0645\u064e\u0644\u0650 \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u0650 \u0641\u064e\u0671\u062c\u06e1\u062a\u064e\u0646\u0650\u0628\u064f\u0648\u0647\u064f \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064f\u0641\u06e1\u0644\u0650\u062d\u064f\u0648\u0646\u064e",translation:"Wahai orang-orang yang beriman! Sesungguhnya minuman keras, berjudi, (berkurban untuk) berhala, dan mengundi nasib dengan anak panah, adalah perbuatan keji dan termasuk perbuatan setan. Maka jauhilah (perbuatan-perbuatan) itu agar kamu beruntung"},{id:91,text:"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u064f \u0623\u064e\u0646 \u064a\u064f\u0648\u0642\u0650\u0639\u064e \u0628\u064e\u064a\u06e1\u0646\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0639\u064e\u062f\u064e\u0670\u0648\u064e\u0629\u064e \u0648\u064e\u0671\u0644\u06e1\u0628\u064e\u063a\u06e1\u0636\u064e\u0627\u0653\u0621\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u062e\u064e\u0645\u06e1\u0631\u0650 \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u064a\u06e1\u0633\u0650\u0631\u0650 \u0648\u064e\u064a\u064e\u0635\u064f\u062f\u0651\u064e\u0643\u064f\u0645\u06e1 \u0639\u064e\u0646 \u0630\u0650\u0643\u06e1\u0631\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0639\u064e\u0646\u0650 \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u0650\u06d6 \u0641\u064e\u0647\u064e\u0644\u06e1 \u0623\u064e\u0646\u062a\u064f\u0645 \u0645\u0651\u064f\u0646\u062a\u064e\u0647\u064f\u0648\u0646\u064e",translation:"Dengan minuman keras dan judi itu, setan hanyalah bermaksud menimbulkan permusuhan dan kebencian di antara kamu, dan menghalang-halangi kamu dari mengingat Allah dan melaksanakan salat maka tidakkah kamu mau berhenti"},{id:92,text:"\u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0627\u0652 \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e \u0648\u064e\u0671\u062d\u06e1\u0630\u064e\u0631\u064f\u0648\u0627\u0652\u06da \u0641\u064e\u0625\u0650\u0646 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u064a\u06e1\u062a\u064f\u0645\u06e1 \u0641\u064e\u0671\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0646\u064e\u0627 \u0671\u0644\u06e1\u0628\u064e\u0644\u064e\u0670\u063a\u064f \u0671\u0644\u06e1\u0645\u064f\u0628\u0650\u064a\u0646\u064f",translation:"Dan taatlah kamu kepada Allah dan taatlah kamu kepada Rasul serta berhati-hatilah. Jika kamu berpaling, maka ketahuilah bahwa kewajiban Rasul Kami, hanyalah menyampaikan (amanat) dengan jelas"},{id:93,text:"\u0644\u064e\u064a\u06e1\u0633\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u062c\u064f\u0646\u064e\u0627\u062d\u065e \u0641\u0650\u064a\u0645\u064e\u0627 \u0637\u064e\u0639\u0650\u0645\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0627 \u0671\u062a\u0651\u064e\u0642\u064e\u0648\u0627\u0652 \u0648\u0651\u064e\u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u062b\u064f\u0645\u0651\u064e \u0671\u062a\u0651\u064e\u0642\u064e\u0648\u0627\u0652 \u0648\u0651\u064e\u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u062b\u064f\u0645\u0651\u064e \u0671\u062a\u0651\u064e\u0642\u064e\u0648\u0627\u0652 \u0648\u0651\u064e\u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064f\u0648\u0627\u0652\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0671\u0644\u06e1\u0645\u064f\u062d\u06e1\u0633\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Tidak berdosa bagi orang-orang yang beriman dan mengerjakan kebajikan tentang apa yang mereka makan (dahulu), apabila mereka bertakwa dan beriman, serta mengerjakan kebajikan, kemudian mereka tetap bertakwa dan beriman, selanjutnya mereka (tetap juga) bertakwa dan berbuat kebajikan. Dan Allah menyukai orang-orang yang berbuat kebajikan"},{id:94,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u064a\u064e\u0628\u06e1\u0644\u064f\u0648\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0634\u064e\u064a\u06e1\u0621\u0656 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u064a\u06e1\u062f\u0650 \u062a\u064e\u0646\u064e\u0627\u0644\u064f\u0647\u064f\u06e5\u0653 \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u0643\u064f\u0645\u06e1 \u0648\u064e\u0631\u0650\u0645\u064e\u0627\u062d\u064f\u0643\u064f\u0645\u06e1 \u0644\u0650\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0646 \u064a\u064e\u062e\u064e\u0627\u0641\u064f\u0647\u064f\u06e5 \u0628\u0650\u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u0628\u0650\u06da \u0641\u064e\u0645\u064e\u0646\u0650 \u0671\u0639\u06e1\u062a\u064e\u062f\u064e\u0649\u0670 \u0628\u064e\u0639\u06e1\u062f\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u0644\u064e\u0647\u064f\u06e5 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Wahai orang-orang yang beriman! Allah pasti akan menguji kamu dengan hewan buruan yang dengan mudah kamu peroleh dengan tangan dan tombakmu agar Allah mengetahui siapa yang takut kepada-Nya, meskipun dia tidak melihat-Nya. Barang siapa melampaui batas setelah itu, maka dia akan mendapat azab yang pedih"},{id:95,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u062a\u064e\u0642\u06e1\u062a\u064f\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u064a\u06e1\u062f\u064e \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u062d\u064f\u0631\u064f\u0645\u065e\u06da \u0648\u064e\u0645\u064e\u0646 \u0642\u064e\u062a\u064e\u0644\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646\u0643\u064f\u0645 \u0645\u0651\u064f\u062a\u064e\u0639\u064e\u0645\u0651\u0650\u062f\u0657\u0627 \u0641\u064e\u062c\u064e\u0632\u064e\u0627\u0653\u0621\u065e \u0645\u0651\u0650\u062b\u06e1\u0644\u064f \u0645\u064e\u0627 \u0642\u064e\u062a\u064e\u0644\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0639\u064e\u0645\u0650 \u064a\u064e\u062d\u06e1\u0643\u064f\u0645\u064f \u0628\u0650\u0647\u0650\u06e6 \u0630\u064e\u0648\u064e\u0627 \u0639\u064e\u062f\u06e1\u0644\u0656 \u0645\u0651\u0650\u0646\u0643\u064f\u0645\u06e1 \u0647\u064e\u062f\u06e1\u064a\u064e\u06e2\u0627 \u0628\u064e\u0670\u0644\u0650\u063a\u064e \u0671\u0644\u06e1\u0643\u064e\u0639\u06e1\u0628\u064e\u0629\u0650 \u0623\u064e\u0648\u06e1 \u0643\u064e\u0641\u0651\u064e\u0640\u0670\u0631\u064e\u0629\u065e \u0637\u064e\u0639\u064e\u0627\u0645\u064f \u0645\u064e\u0633\u064e\u0670\u0643\u0650\u064a\u0646\u064e \u0623\u064e\u0648\u06e1 \u0639\u064e\u062f\u06e1\u0644\u064f \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0635\u0650\u064a\u064e\u0627\u0645\u0657\u0627 \u0644\u0651\u0650\u064a\u064e\u0630\u064f\u0648\u0642\u064e \u0648\u064e\u0628\u064e\u0627\u0644\u064e \u0623\u064e\u0645\u06e1\u0631\u0650\u0647\u0650\u06e6\u06d7 \u0639\u064e\u0641\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0645\u0651\u064e\u0627 \u0633\u064e\u0644\u064e\u0641\u064e\u06da \u0648\u064e\u0645\u064e\u0646\u06e1 \u0639\u064e\u0627\u062f\u064e \u0641\u064e\u064a\u064e\u0646\u062a\u064e\u0642\u0650\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u06e1\u0647\u064f\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0632\u0650\u064a\u0632\u065e \u0630\u064f\u0648 \u0671\u0646\u062a\u0650\u0642\u064e\u0627\u0645\u064d",translation:"(Wahai orang-orang yang beriman! Janganlah kamu membunuh hewan buruan,290) ketika kamu sedang ihram (haji atau umrah). Barang siapa di antara kamu membunuhnya dengan sengaja, maka dendanya ialah mengganti dengan hewan ternak yang sepadan dengan buruan yang dibunuhnya, menurut putusan dua orang yang adil di antara kamu sebagai hadyu yang dibawa ke Ka'bah,291) atau kafarat (membayar tebusan dengan) memberi makan kepada orang-orang miskin,292) atau berpuasa, seimbang dengan makanan yang dikeluarkan itu,293) agar dia merasakan akibat buruk dari perbuatannya. Allah telah memaafkan apa yang telah lalu.294) Dan barang siapa kembali mengerjakannya, niscaya Allah akan menyiksanya. Dan Allah Mahaperkasa, memiliki (kekuasaan untuk) menyiksa"},{id:96,text:"\u0623\u064f\u062d\u0650\u0644\u0651\u064e \u0644\u064e\u0643\u064f\u0645\u06e1 \u0635\u064e\u064a\u06e1\u062f\u064f \u0671\u0644\u06e1\u0628\u064e\u062d\u06e1\u0631\u0650 \u0648\u064e\u0637\u064e\u0639\u064e\u0627\u0645\u064f\u0647\u064f\u06e5 \u0645\u064e\u062a\u064e\u0670\u0639\u0657\u0627 \u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u0650\u0644\u0633\u0651\u064e\u064a\u0651\u064e\u0627\u0631\u064e\u0629\u0650\u06d6 \u0648\u064e\u062d\u064f\u0631\u0651\u0650\u0645\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0635\u064e\u064a\u06e1\u062f\u064f \u0671\u0644\u06e1\u0628\u064e\u0631\u0651\u0650 \u0645\u064e\u0627 \u062f\u064f\u0645\u06e1\u062a\u064f\u0645\u06e1 \u062d\u064f\u0631\u064f\u0645\u0657\u0627\u06d7 \u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u062a\u064f\u062d\u06e1\u0634\u064e\u0631\u064f\u0648\u0646\u064e",translation:"(Dihalalkan bagimu hewan buruan laut295) dan makanan (yang berasal) dari laut296) sebagai makanan yang lezat bagimu, dan bagi orang-orang yang dalam perjalanan; dan diharamkan atasmu (menangkap) hewan darat, selama kamu sedang ihram. Dan bertakwalah kepada Allah yang kepada-Nya kamu akan dikumpulkan (kembali)"},{id:97,text:"\u06de\u062c\u064e\u0639\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u0643\u064e\u0639\u06e1\u0628\u064e\u0629\u064e \u0671\u0644\u06e1\u0628\u064e\u064a\u06e1\u062a\u064e \u0671\u0644\u06e1\u062d\u064e\u0631\u064e\u0627\u0645\u064e \u0642\u0650\u064a\u064e\u0670\u0645\u0657\u0627 \u0644\u0651\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0671\u0644\u0634\u0651\u064e\u0647\u06e1\u0631\u064e \u0671\u0644\u06e1\u062d\u064e\u0631\u064e\u0627\u0645\u064e \u0648\u064e\u0671\u0644\u06e1\u0647\u064e\u062f\u06e1\u064a\u064e \u0648\u064e\u0671\u0644\u06e1\u0642\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u062f\u064e\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u0650\u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u064c",translation:"(Allah telah menjadikan Ka'bah, rumah suci tempat manusia berkumpul.297) Demikian pula bulan haram hadyu dan qal\u0101id. Yang demikian itu agar kamu mengetahui, bahwa Allah mengetahui apa yang ada di langit dan apa yang ada di bumi dan bahwa Allah Maha Mengetahui segala sesuatu"},{id:98,text:"\u0671\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0634\u064e\u062f\u0650\u064a\u062f\u064f \u0671\u0644\u06e1\u0639\u0650\u0642\u064e\u0627\u0628\u0650 \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u065e",translation:"Ketahuilah, bahwa Allah sangat keras siksaan-Nya dan bahwa Allah Maha Pengampun, Maha Penyayang"},{id:99,text:"\u0645\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u06e1\u0628\u064e\u0644\u064e\u0670\u063a\u064f\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u062a\u064f\u0628\u06e1\u062f\u064f\u0648\u0646\u064e \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0643\u06e1\u062a\u064f\u0645\u064f\u0648\u0646\u064e",translation:"Kewajiban Rasul tidak lain hanyalah menyampaikan (amanat Allah), dan Allah mengetahui apa yang kamu tampakkan dan apa yang kamu sembunyikan"},{id:100,text:"\u0642\u064f\u0644 \u0644\u0651\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0648\u0650\u064a \u0671\u0644\u06e1\u062e\u064e\u0628\u0650\u064a\u062b\u064f \u0648\u064e\u0671\u0644\u0637\u0651\u064e\u064a\u0651\u0650\u0628\u064f \u0648\u064e\u0644\u064e\u0648\u06e1 \u0623\u064e\u0639\u06e1\u062c\u064e\u0628\u064e\u0643\u064e \u0643\u064e\u062b\u06e1\u0631\u064e\u0629\u064f \u0671\u0644\u06e1\u062e\u064e\u0628\u0650\u064a\u062b\u0650\u06da \u0641\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0640\u0670\u0653\u0623\u064f\u0648\u0652\u0644\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0644\u06e1\u0628\u064e\u0670\u0628\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064f\u0641\u06e1\u0644\u0650\u062d\u064f\u0648\u0646\u064e",translation:"Katakanlah (Muhammad), \"Tidaklah sama yang buruk dengan yang baik, meskipun banyaknya keburukan itu menarik hatimu, maka bertakwalah kepada Allah wahai orang-orang yang mempunyai akal sehat, agar kamu beruntung"},{id:101,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u062a\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0648\u0627\u0652 \u0639\u064e\u0646\u06e1 \u0623\u064e\u0634\u06e1\u064a\u064e\u0627\u0653\u0621\u064e \u0625\u0650\u0646 \u062a\u064f\u0628\u06e1\u062f\u064e \u0644\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u0633\u064f\u0624\u06e1\u0643\u064f\u0645\u06e1 \u0648\u064e\u0625\u0650\u0646 \u062a\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0648\u0627\u0652 \u0639\u064e\u0646\u06e1\u0647\u064e\u0627 \u062d\u0650\u064a\u0646\u064e \u064a\u064f\u0646\u064e\u0632\u0651\u064e\u0644\u064f \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u064f \u062a\u064f\u0628\u06e1\u062f\u064e \u0644\u064e\u0643\u064f\u0645\u06e1 \u0639\u064e\u0641\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0646\u06e1\u0647\u064e\u0627\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u064c \u062d\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Wahai orang-orang yang beriman! Janganlah kamu menanyakan (kepada Nabimu) hal-hal yang jika diterangkan kepadamu, (justru) menyusahkan kamu. Jika kamu menanyakannya ketika Alquran sedang diturunkan, (niscaya) akan diterangkan kepadamu. Allah telah memaafkan (kamu) tentang hal itu. Dan Allah Maha Pengampun, Maha Penyantun"},{id:102,text:"\u0642\u064e\u062f\u06e1 \u0633\u064e\u0623\u064e\u0644\u064e\u0647\u064e\u0627 \u0642\u064e\u0648\u06e1\u0645\u065e \u0645\u0651\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064f\u0645\u06e1 \u062b\u064f\u0645\u0651\u064e \u0623\u064e\u0635\u06e1\u0628\u064e\u062d\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u064e\u0627 \u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Sesungguhnya sebelum kamu telah ada segolongan manusia yang menanyakan hal-hal serupa itu (kepada nabi mereka), kemudian mereka menjadi kafir"},{id:103,text:"\u0645\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u06e2 \u0628\u064e\u062d\u0650\u064a\u0631\u064e\u0629\u0656 \u0648\u064e\u0644\u064e\u0627 \u0633\u064e\u0627\u0653\u0626\u0650\u0628\u064e\u0629\u0656 \u0648\u064e\u0644\u064e\u0627 \u0648\u064e\u0635\u0650\u064a\u0644\u064e\u0629\u0656 \u0648\u064e\u0644\u064e\u0627 \u062d\u064e\u0627\u0645\u0656 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u064a\u064e\u0641\u06e1\u062a\u064e\u0631\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u0643\u064e\u0630\u0650\u0628\u064e\u06d6 \u0648\u064e\u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064f\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e",translation:"(Allah tidak pernah mensyariatkan adanya Ba\u1e25\u012brah,298) S\u0101ibah,299) Wa\u1e63\u012blah300) dan \u1e24\u0101m.301) Tetapi orang-orang kafir membuat-buat kedustaan terhadap Allah, dan kebanyakan mereka tidak mengerti"},{id:104,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0648\u06e1\u0627\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0650 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u062d\u064e\u0633\u06e1\u0628\u064f\u0646\u064e\u0627 \u0645\u064e\u0627 \u0648\u064e\u062c\u064e\u062f\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0621\u064e\u0646\u064e\u0627\u0653\u06da \u0623\u064e\u0648\u064e\u0644\u064e\u0648\u06e1 \u0643\u064e\u0627\u0646\u064e \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0624\u064f\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0647\u06e1\u062a\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Dan apabila dikatakan kepada mereka, \"Marilah (mengikuti) apa yang diturunkan Allah dan (mengikuti) Rasul.\" Mereka menjawab, \"Cukuplah bagi kami apa yang kami dapati nenek moyang kami (mengerjakannya).\" Apakah (mereka akan mengikuti) juga nenek moyang mereka walaupun nenek moyang mereka itu tidak mengetahui apa-apa dan tidak (pula) mendapat petunjuk"},{id:105,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0643\u064f\u0645\u06e1\u06d6 \u0644\u064e\u0627 \u064a\u064e\u0636\u064f\u0631\u0651\u064f\u0643\u064f\u0645 \u0645\u0651\u064e\u0646 \u0636\u064e\u0644\u0651\u064e \u0625\u0650\u0630\u064e\u0627 \u0671\u0647\u06e1\u062a\u064e\u062f\u064e\u064a\u06e1\u062a\u064f\u0645\u06e1\u06da \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0631\u06e1\u062c\u0650\u0639\u064f\u0643\u064f\u0645\u06e1 \u062c\u064e\u0645\u0650\u064a\u0639\u0657\u0627 \u0641\u064e\u064a\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0643\u064f\u0645 \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Wahai orang-orang yang beriman! Jagalah dirimu; (karena) orang yang sesat itu tidak akan membahayakanmu apabila kamu telah mendapat petunjuk. Hanya kepada Allah kamu semua akan kembali, kemudian Dia akan menerangkan kepadamu apa yang telah kamu kerjakan"},{id:106,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0634\u064e\u0647\u064e\u0670\u062f\u064e\u0629\u064f \u0628\u064e\u064a\u06e1\u0646\u0650\u0643\u064f\u0645\u06e1 \u0625\u0650\u0630\u064e\u0627 \u062d\u064e\u0636\u064e\u0631\u064e \u0623\u064e\u062d\u064e\u062f\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u064f \u062d\u0650\u064a\u0646\u064e \u0671\u0644\u06e1\u0648\u064e\u0635\u0650\u064a\u0651\u064e\u0629\u0650 \u0671\u062b\u06e1\u0646\u064e\u0627\u0646\u0650 \u0630\u064e\u0648\u064e\u0627 \u0639\u064e\u062f\u06e1\u0644\u0656 \u0645\u0651\u0650\u0646\u0643\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1 \u0621\u064e\u0627\u062e\u064e\u0631\u064e\u0627\u0646\u0650 \u0645\u0650\u0646\u06e1 \u063a\u064e\u064a\u06e1\u0631\u0650\u0643\u064f\u0645\u06e1 \u0625\u0650\u0646\u06e1 \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0636\u064e\u0631\u064e\u0628\u06e1\u062a\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0641\u064e\u0623\u064e\u0635\u064e\u0670\u0628\u064e\u062a\u06e1\u0643\u064f\u0645 \u0645\u0651\u064f\u0635\u0650\u064a\u0628\u064e\u0629\u064f \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u0650\u06da \u062a\u064e\u062d\u06e1\u0628\u0650\u0633\u064f\u0648\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u0650 \u0641\u064e\u064a\u064f\u0642\u06e1\u0633\u0650\u0645\u064e\u0627\u0646\u0650 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0646\u0650 \u0671\u0631\u06e1\u062a\u064e\u0628\u06e1\u062a\u064f\u0645\u06e1 \u0644\u064e\u0627 \u0646\u064e\u0634\u06e1\u062a\u064e\u0631\u0650\u064a \u0628\u0650\u0647\u0650\u06e6 \u062b\u064e\u0645\u064e\u0646\u0657\u0627 \u0648\u064e\u0644\u064e\u0648\u06e1 \u0643\u064e\u0627\u0646\u064e \u0630\u064e\u0627 \u0642\u064f\u0631\u06e1\u0628\u064e\u0649\u0670 \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0643\u06e1\u062a\u064f\u0645\u064f \u0634\u064e\u0647\u064e\u0670\u062f\u064e\u0629\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0625\u0650\u0630\u0657\u0627 \u0644\u0651\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u0653\u062b\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Wahai orang-orang yang beriman! Apabila salah seorang (di antara) kamu menghadapi kematian, sedang dia akan berwasiat, maka hendaklah (wasiat itu) disaksikan oleh dua orang yang adil di antara kamu, atau dua orang yang berlainan (agama) dengan kamu. Jika kamu dalam perjalanan di bumi lalu kamu ditimpa bahaya kematian, hendaklah kamu tahan kedua saksi itu setelah salat, agar keduanya bersumpah dengan nama Allah jika kamu ragu-ragu, \"Demi Allah kami tidak akan mengambil keuntungan dengan sumpah ini, walaupun dia karib kerabat, dan kami tidak menyembunyikan kesaksian Allah; sesungguhnya jika demikian tentu kami termasuk orang-orang yang berdosa"},{id:107,text:"\u0641\u064e\u0625\u0650\u0646\u06e1 \u0639\u064f\u062b\u0650\u0631\u064e \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u064e\u0627 \u0671\u0633\u06e1\u062a\u064e\u062d\u064e\u0642\u0651\u064e\u0627\u0653 \u0625\u0650\u062b\u06e1\u0645\u0657\u0627 \u0641\u064e\u0640\u0654\u064e\u0627\u062e\u064e\u0631\u064e\u0627\u0646\u0650 \u064a\u064e\u0642\u064f\u0648\u0645\u064e\u0627\u0646\u0650 \u0645\u064e\u0642\u064e\u0627\u0645\u064e\u0647\u064f\u0645\u064e\u0627 \u0645\u0650\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u0633\u06e1\u062a\u064e\u062d\u064e\u0642\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u0648\u06e1\u0644\u064e\u064a\u064e\u0670\u0646\u0650 \u0641\u064e\u064a\u064f\u0642\u06e1\u0633\u0650\u0645\u064e\u0627\u0646\u0650 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0634\u064e\u0647\u064e\u0670\u062f\u064e\u062a\u064f\u0646\u064e\u0627\u0653 \u0623\u064e\u062d\u064e\u0642\u0651\u064f \u0645\u0650\u0646 \u0634\u064e\u0647\u064e\u0670\u062f\u064e\u062a\u0650\u0647\u0650\u0645\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u0671\u0639\u06e1\u062a\u064e\u062f\u064e\u064a\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0625\u0650\u0630\u0657\u0627 \u0644\u0651\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"(Jika terbukti kedua saksi itu berbuat dosa,302) maka dua orang yang lain menggantikan kedudukannya, yaitu di antara ahli waris yang berhak dan lebih dekat kepada orang yang mati, lalu keduanya bersumpah dengan nama Allah, \"Sungguh, kesaksian kami lebih layak diterima daripada kesaksian kedua saksi itu, dan kami tidak melanggar batas. Sesungguhnya jika kami berbuat demikian tentu kami termasuk orang-orang zalim"},{id:108,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0623\u064e\u062f\u06e1\u0646\u064e\u0649\u0670\u0653 \u0623\u064e\u0646 \u064a\u064e\u0623\u06e1\u062a\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u0634\u0651\u064e\u0647\u064e\u0670\u062f\u064e\u0629\u0650 \u0639\u064e\u0644\u064e\u0649\u0670 \u0648\u064e\u062c\u06e1\u0647\u0650\u0647\u064e\u0627\u0653 \u0623\u064e\u0648\u06e1 \u064a\u064e\u062e\u064e\u0627\u0641\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646 \u062a\u064f\u0631\u064e\u062f\u0651\u064e \u0623\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u064f\u06e2 \u0628\u064e\u0639\u06e1\u062f\u064e \u0623\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u0650\u0647\u0650\u0645\u06e1\u06d7 \u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0671\u0633\u06e1\u0645\u064e\u0639\u064f\u0648\u0627\u0652\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064e\u0647\u06e1\u062f\u0650\u064a \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0641\u064e\u0670\u0633\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Dengan cara itu mereka lebih patut memberikan kesaksiannya menurut yang sebenarnya, dan mereka merasa takut akan dikembalikan sumpahnya (kepada ahli waris) setelah mereka bersumpah.303) Bertakwalah kepada Allah dan dengarkanlah (perintah-Nya). Dan Allah tidak memberi petunjuk kepada orang-orang yang fasik"},{id:109,text:"\u06de\u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064e\u062c\u06e1\u0645\u064e\u0639\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0631\u0651\u064f\u0633\u064f\u0644\u064e \u0641\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0645\u064e\u0627\u0630\u064e\u0627\u0653 \u0623\u064f\u062c\u0650\u0628\u06e1\u062a\u064f\u0645\u06e1\u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u0639\u0650\u0644\u06e1\u0645\u064e \u0644\u064e\u0646\u064e\u0627\u0653\u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0623\u064e\u0646\u062a\u064e \u0639\u064e\u0644\u0651\u064e\u0640\u0670\u0645\u064f \u0671\u0644\u06e1\u063a\u064f\u064a\u064f\u0648\u0628\u0650",translation:"(Ingatlah), pada hari ketika Allah mengumpulkan para rasul, lalu Dia bertanya (kepada mereka), \"Apa jawaban (kaummu) terhadap (seruan)mu?\" Mereka (para rasul) menjawab, \"Kami tidak tahu (tentang itu). Sesungguhnya Engkaulah Yang Maha Mengetahui segala yang gaib"},{id:110,text:"\u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0670\u0639\u0650\u064a\u0633\u064e\u0649 \u0671\u0628\u06e1\u0646\u064e \u0645\u064e\u0631\u06e1\u064a\u064e\u0645\u064e \u0671\u0630\u06e1\u0643\u064f\u0631\u06e1 \u0646\u0650\u0639\u06e1\u0645\u064e\u062a\u0650\u064a \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0648\u064e\u0639\u064e\u0644\u064e\u0649\u0670 \u0648\u064e\u0670\u0644\u0650\u062f\u064e\u062a\u0650\u0643\u064e \u0625\u0650\u0630\u06e1 \u0623\u064e\u064a\u0651\u064e\u062f\u062a\u0651\u064f\u0643\u064e \u0628\u0650\u0631\u064f\u0648\u062d\u0650 \u0671\u0644\u06e1\u0642\u064f\u062f\u064f\u0633\u0650 \u062a\u064f\u0643\u064e\u0644\u0651\u0650\u0645\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0645\u064e\u0647\u06e1\u062f\u0650 \u0648\u064e\u0643\u064e\u0647\u06e1\u0644\u0657\u0627\u06d6 \u0648\u064e\u0625\u0650\u0630\u06e1 \u0639\u064e\u0644\u0651\u064e\u0645\u06e1\u062a\u064f\u0643\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0648\u064e\u0671\u0644\u06e1\u062d\u0650\u0643\u06e1\u0645\u064e\u0629\u064e \u0648\u064e\u0671\u0644\u062a\u0651\u064e\u0648\u06e1\u0631\u064e\u0649\u0670\u0629\u064e \u0648\u064e\u0671\u0644\u06e1\u0625\u0650\u0646\u062c\u0650\u064a\u0644\u064e\u06d6 \u0648\u064e\u0625\u0650\u0630\u06e1 \u062a\u064e\u062e\u06e1\u0644\u064f\u0642\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u0637\u0651\u0650\u064a\u0646\u0650 \u0643\u064e\u0647\u064e\u064a\u06e1\u0640\u0654\u064e\u0629\u0650 \u0671\u0644\u0637\u0651\u064e\u064a\u06e1\u0631\u0650 \u0628\u0650\u0625\u0650\u0630\u06e1\u0646\u0650\u064a \u0641\u064e\u062a\u064e\u0646\u0641\u064f\u062e\u064f \u0641\u0650\u064a\u0647\u064e\u0627 \u0641\u064e\u062a\u064e\u0643\u064f\u0648\u0646\u064f \u0637\u064e\u064a\u06e1\u0631\u064e\u06e2\u0627 \u0628\u0650\u0625\u0650\u0630\u06e1\u0646\u0650\u064a\u06d6 \u0648\u064e\u062a\u064f\u0628\u06e1\u0631\u0650\u0626\u064f \u0671\u0644\u06e1\u0623\u064e\u0643\u06e1\u0645\u064e\u0647\u064e \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0628\u06e1\u0631\u064e\u0635\u064e \u0628\u0650\u0625\u0650\u0630\u06e1\u0646\u0650\u064a\u06d6 \u0648\u064e\u0625\u0650\u0630\u06e1 \u062a\u064f\u062e\u06e1\u0631\u0650\u062c\u064f \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u064e\u0649\u0670 \u0628\u0650\u0625\u0650\u0630\u06e1\u0646\u0650\u064a\u06d6 \u0648\u064e\u0625\u0650\u0630\u06e1 \u0643\u064e\u0641\u064e\u0641\u06e1\u062a\u064f \u0628\u064e\u0646\u0650\u064a\u0653 \u0625\u0650\u0633\u06e1\u0631\u064e\u0640\u0670\u0653\u0621\u0650\u064a\u0644\u064e \u0639\u064e\u0646\u0643\u064e \u0625\u0650\u0630\u06e1 \u062c\u0650\u0626\u06e1\u062a\u064e\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0650 \u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0625\u0650\u0646\u06e1 \u0647\u064e\u0670\u0630\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0633\u0650\u062d\u06e1\u0631\u065e \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u065e",translation:"Dan Ingatlah, ketika Allah berfirman, \"Wahai Isa putra Maryam! Ingatlah nikmat-Ku kepadamu dan kepada ibumu sewaktu Aku menguatkanmu dengan Rohulkudus. Engkau dapat berbicara dengan manusia di waktu masih dalam buaian dan setelah dewasa. Dan ingatlah ketika Aku mengajarkan menulis kepadamu, (juga) Hikmah, Taurat dan Injil. Dan ingatlah ketika engkau membentuk dari tanah berupa burung dengan seizin-Ku, kemudian engkau meniupnya, lalu menjadi seekor burung (yang sebenarnya) dengan seizin-Ku. Dan ingatlah, ketika engkau menyembuhkan orang yang buta sejak lahir dan orang yang berpenyakit kusta dengan seizin-Ku. Dan ingatlah ketika engkau mengeluarkan orang mati (dari kubur menjadi hidup) dengan seizin-Ku. Dan ingatlah ketika Aku menghalangi Bani Israil (dari keinginan mereka membunuhmu) dikala engkau mengemukakan kepada mereka keterangan-keterangan yang nyata, lalu orang-orang kafir di antara mereka berkata, \"Ini tidak lain hanyalah sihir yang nyata"},{id:111,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0623\u064e\u0648\u06e1\u062d\u064e\u064a\u06e1\u062a\u064f \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u062d\u064e\u0648\u064e\u0627\u0631\u0650\u064a\u0651\u0650\u0640\u06e7\u0646\u064e \u0623\u064e\u0646\u06e1 \u0621\u064e\u0627\u0645\u0650\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u064a \u0648\u064e\u0628\u0650\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u064a \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0621\u064e\u0627\u0645\u064e\u0646\u0651\u064e\u0627 \u0648\u064e\u0671\u0634\u06e1\u0647\u064e\u062f\u06e1 \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0646\u064e\u0627 \u0645\u064f\u0633\u06e1\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Dan (ingatlah), ketika Aku ilhamkan kepada pengikut-pengikut Isa yang setia, \"Berimanlah kamu kepada-Ku dan kepada Rasul-Ku.\" Mereka menjawab, \"Kami telah beriman dan saksikanlah (wahai Rasul) bahwa kami adalah orang-orang yang berserah diri (muslim)"},{id:112,text:"\u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e \u0671\u0644\u06e1\u062d\u064e\u0648\u064e\u0627\u0631\u0650\u064a\u0651\u064f\u0648\u0646\u064e \u064a\u064e\u0670\u0639\u0650\u064a\u0633\u064e\u0649 \u0671\u0628\u06e1\u0646\u064e \u0645\u064e\u0631\u06e1\u064a\u064e\u0645\u064e \u0647\u064e\u0644\u06e1 \u064a\u064e\u0633\u06e1\u062a\u064e\u0637\u0650\u064a\u0639\u064f \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0623\u064e\u0646 \u064a\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0645\u064e\u0627\u0653\u0626\u0650\u062f\u064e\u0629\u0657 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650\u06d6 \u0642\u064e\u0627\u0644\u064e \u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645 \u0645\u0651\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"(Ingatlah), ketika pengikut-pengikut Isa yang setia berkata, \"Wahai Isa putra Maryam! Bersediakah Tuhanmu menurunkan hidangan dari langit kepada kami?\" Isa menjawab, \"Bertakwalah kepada Allah jika kamu orang-orang beriman"},{id:113,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0646\u064f\u0631\u0650\u064a\u062f\u064f \u0623\u064e\u0646 \u0646\u0651\u064e\u0623\u06e1\u0643\u064f\u0644\u064e \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0648\u064e\u062a\u064e\u0637\u06e1\u0645\u064e\u0626\u0650\u0646\u0651\u064e \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0646\u064e\u0627 \u0648\u064e\u0646\u064e\u0639\u06e1\u0644\u064e\u0645\u064e \u0623\u064e\u0646 \u0642\u064e\u062f\u06e1 \u0635\u064e\u062f\u064e\u0642\u06e1\u062a\u064e\u0646\u064e\u0627 \u0648\u064e\u0646\u064e\u0643\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627 \u0645\u0650\u0646\u064e \u0671\u0644\u0634\u0651\u064e\u0640\u0670\u0647\u0650\u062f\u0650\u064a\u0646\u064e",translation:"Mereka berkata, \"Kami ingin memakan hidangan itu agar tenteram hati kami dan agar kami yakin bahwa engkau telah berkata benar kepada kami, dan kami menjadi orang-orang yang menyaksikan (hidangan itu)"},{id:114,text:"\u0642\u064e\u0627\u0644\u064e \u0639\u0650\u064a\u0633\u064e\u0649 \u0671\u0628\u06e1\u0646\u064f \u0645\u064e\u0631\u06e1\u064a\u064e\u0645\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u0650\u0644\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0645\u064e\u0627\u0653\u0626\u0650\u062f\u064e\u0629\u0657 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u062a\u064e\u0643\u064f\u0648\u0646\u064f \u0644\u064e\u0646\u064e\u0627 \u0639\u0650\u064a\u062f\u0657\u0627 \u0644\u0651\u0650\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u0646\u064e\u0627 \u0648\u064e\u0621\u064e\u0627\u062e\u0650\u0631\u0650\u0646\u064e\u0627 \u0648\u064e\u0621\u064e\u0627\u064a\u064e\u0629\u0657 \u0645\u0651\u0650\u0646\u0643\u064e\u06d6 \u0648\u064e\u0671\u0631\u06e1\u0632\u064f\u0642\u06e1\u0646\u064e\u0627 \u0648\u064e\u0623\u064e\u0646\u062a\u064e \u062e\u064e\u064a\u06e1\u0631\u064f \u0671\u0644\u0631\u0651\u064e\u0640\u0670\u0632\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Isa putra Maryam berdoa, \"Ya Tuhan kami, turunkanlah kepada kami hidangan dari langit (yang hari turunnya) akan menjadi hari raya bagi kami, yaitu bagi orang-orang yang sekarang bersama kami maupun yang datang setelah kami, dan menjadi tanda bagi kekuasaan Engkau; berilah kami rezeki, dan Engkaulah sebaik-baik pemberi rezeki"},{id:115,text:"\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0625\u0650\u0646\u0651\u0650\u064a \u0645\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u064f\u0647\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1\u06d6 \u0641\u064e\u0645\u064e\u0646 \u064a\u064e\u0643\u06e1\u0641\u064f\u0631\u06e1 \u0628\u064e\u0639\u06e1\u062f\u064f \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u0641\u064e\u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064f\u0647\u064f\u06e5 \u0639\u064e\u0630\u064e\u0627\u0628\u0657\u0627 \u0644\u0651\u064e\u0627\u0653 \u0623\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064f\u0647\u064f\u06e5\u0653 \u0623\u064e\u062d\u064e\u062f\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Allah berfirman, \"Sungguh, Aku akan menurunkan hidangan itu kepadamu, tetapi barang siapa kafir di antaramu setelah (turun hidangan) itu, maka sungguh, Aku akan mengazabnya dengan azab yang tidak pernah Aku timpakan kepada seorang pun di antara umat manusia (seluruh alam)"},{id:116,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0670\u0639\u0650\u064a\u0633\u064e\u0649 \u0671\u0628\u06e1\u0646\u064e \u0645\u064e\u0631\u06e1\u064a\u064e\u0645\u064e \u0621\u064e\u0623\u064e\u0646\u062a\u064e \u0642\u064f\u0644\u06e1\u062a\u064e \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0671\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0646\u0650\u064a \u0648\u064e\u0623\u064f\u0645\u0651\u0650\u064a\u064e \u0625\u0650\u0644\u064e\u0670\u0647\u064e\u064a\u06e1\u0646\u0650 \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0642\u064e\u0627\u0644\u064e \u0633\u064f\u0628\u06e1\u062d\u064e\u0670\u0646\u064e\u0643\u064e \u0645\u064e\u0627 \u064a\u064e\u0643\u064f\u0648\u0646\u064f \u0644\u0650\u064a\u0653 \u0623\u064e\u0646\u06e1 \u0623\u064e\u0642\u064f\u0648\u0644\u064e \u0645\u064e\u0627 \u0644\u064e\u064a\u06e1\u0633\u064e \u0644\u0650\u064a \u0628\u0650\u062d\u064e\u0642\u0651\u064d\u06da \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f \u0642\u064f\u0644\u06e1\u062a\u064f\u0647\u064f\u06e5 \u0641\u064e\u0642\u064e\u062f\u06e1 \u0639\u064e\u0644\u0650\u0645\u06e1\u062a\u064e\u0647\u064f\u06e5\u06da \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0646\u064e\u0641\u06e1\u0633\u0650\u064a \u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0646\u064e\u0641\u06e1\u0633\u0650\u0643\u064e\u06da \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0623\u064e\u0646\u062a\u064e \u0639\u064e\u0644\u0651\u064e\u0640\u0670\u0645\u064f \u0671\u0644\u06e1\u063a\u064f\u064a\u064f\u0648\u0628\u0650",translation:"Dan (ingatlah) ketika Allah berfirman, \"Wahai Isa putra Maryam! Engkaukah yang mengatakan kepada orang-orang, Jadikanlah aku dan ibuku sebagai dua Tuhan selain Allah?\" (Isa) menjawab, \"Maha Suci Engkau, tidak patut bagiku mengatakan apa yang bukan hakku. Jika aku pernah mengatakannya tentulah Engkau telah mengetahuinya. Engkau mengetahui apa yang ada pada diriku dan aku tidak mengetahui apa yang ada pada-Mu. Sungguh, Engkaulah Yang Maha Mengetahui segala yang gaib"},{id:117,text:"\u0645\u064e\u0627 \u0642\u064f\u0644\u06e1\u062a\u064f \u0644\u064e\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627\u0653 \u0623\u064e\u0645\u064e\u0631\u06e1\u062a\u064e\u0646\u0650\u064a \u0628\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0646\u0650 \u0671\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0643\u064f\u0646\u062a\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0634\u064e\u0647\u0650\u064a\u062f\u0657\u0627 \u0645\u0651\u064e\u0627 \u062f\u064f\u0645\u06e1\u062a\u064f \u0641\u0650\u064a\u0647\u0650\u0645\u06e1\u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062a\u064e\u0648\u064e\u0641\u0651\u064e\u064a\u06e1\u062a\u064e\u0646\u0650\u064a \u0643\u064f\u0646\u062a\u064e \u0623\u064e\u0646\u062a\u064e \u0671\u0644\u0631\u0651\u064e\u0642\u0650\u064a\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1\u06da \u0648\u064e\u0623\u064e\u0646\u062a\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0634\u064e\u0647\u0650\u064a\u062f\u064c",translation:"Aku tidak pernah mengatakan kepada mereka kecuali apa yang Engkau perintahkan kepadaku (yaitu), \"Sembahlah Allah, Tuhanku dan Tuhanmu,\" dan aku menjadi saksi terhadap mereka, selama aku berada di tengah-tengah mereka. Maka setelah Engkau mewafatkan aku, Engkaulah yang mengawasi mereka. Dan Engkaulah Yang Maha Menyaksikan atas segala sesuatu"},{id:118,text:"\u0625\u0650\u0646 \u062a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u06e1\u0647\u064f\u0645\u06e1 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0639\u0650\u0628\u064e\u0627\u062f\u064f\u0643\u064e\u06d6 \u0648\u064e\u0625\u0650\u0646 \u062a\u064e\u063a\u06e1\u0641\u0650\u0631\u06e1 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0623\u064e\u0646\u062a\u064e \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0671\u0644\u06e1\u062d\u064e\u0643\u0650\u064a\u0645\u064f",translation:"Jika Engkau menyiksa mereka, maka sesungguhnya mereka adalah hamba-hamba-Mu, dan jika Engkau mengampuni mereka, sesungguhnya Engkaulah Yang Mahaperkasa, Mahabijaksana"},{id:119,text:"\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0647\u064e\u0670\u0630\u064e\u0627 \u064a\u064e\u0648\u06e1\u0645\u064f \u064a\u064e\u0646\u0641\u064e\u0639\u064f \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e \u0635\u0650\u062f\u06e1\u0642\u064f\u0647\u064f\u0645\u06e1\u06da \u0644\u064e\u0647\u064f\u0645\u06e1 \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u065e \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0645\u0650\u0646 \u062a\u064e\u062d\u06e1\u062a\u0650\u0647\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u064f \u062e\u064e\u0670\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627\u0653 \u0623\u064e\u0628\u064e\u062f\u0657\u0627\u06d6 \u0631\u0651\u064e\u0636\u0650\u064a\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0648\u064e\u0631\u064e\u0636\u064f\u0648\u0627\u0652 \u0639\u064e\u0646\u06e1\u0647\u064f\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0671\u0644\u06e1\u0641\u064e\u0648\u06e1\u0632\u064f \u0671\u0644\u06e1\u0639\u064e\u0638\u0650\u064a\u0645\u064f",translation:"Allah berfirman, \"Inilah saat orang yang benar memperoleh manfaat dari kebenarannya. Mereka memperoleh surga yang mengalir di bawahnya sungai-sungai, mereka kekal di dalamnya selama-lamanya. Allah rida kepada mereka dan mereka pun rida kepada-Nya. Itulah kemenangan yang agung"},{id:120,text:"\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064f\u0644\u06e1\u0643\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a\u0647\u0650\u0646\u0651\u064e\u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0642\u064e\u062f\u0650\u064a\u0631\u064f\u06e2",translation:"Milik Allah kerajaan langit dan bumi dan apa yang ada di dalamnya; dan Dia Mahakuasa atas segala sesuatu"}]},{id:6,name:"\u0627\u0644\u0623\u0646\u0639\u0627\u0645",transliteration:"Al-An'am",translation:"Binatang Ternak",type:"meccan",total_verses:165,verses:[{id:1,text:"\u0671\u0644\u06e1\u062d\u064e\u0645\u06e1\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0671\u0644\u0638\u0651\u064f\u0644\u064f\u0645\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u0646\u0651\u064f\u0648\u0631\u064e\u06d6 \u062b\u064f\u0645\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u064a\u064e\u0639\u06e1\u062f\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Segala puji bagi Allah yang telah menciptakan langit dan bumi, dan menjadikan gelap dan terang, namun demikian orang-orang kafir masih mempersekutukan Tuhan mereka dengan sesuatu"},{id:2,text:"\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0637\u0650\u064a\u0646\u0656 \u062b\u064f\u0645\u0651\u064e \u0642\u064e\u0636\u064e\u0649\u0670\u0653 \u0623\u064e\u062c\u064e\u0644\u0657\u0627\u06d6 \u0648\u064e\u0623\u064e\u062c\u064e\u0644\u065e \u0645\u0651\u064f\u0633\u064e\u0645\u0651\u064b\u0649 \u0639\u0650\u0646\u062f\u064e\u0647\u064f\u06e5\u06d6 \u062b\u064f\u0645\u0651\u064e \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0645\u06e1\u062a\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dialah yang menciptakan kamu dari tanah, kemudian Dia menetapkan ajal (kematianmu), dan batas waktu tertentu yang hanya diketahui oleh-Nya. Namun demikian kamu masih meragukannya"},{id:3,text:"\u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0633\u0650\u0631\u0651\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u062c\u064e\u0647\u06e1\u0631\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u062a\u064e\u0643\u06e1\u0633\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Dan Dialah Allah (yang disembah), di langit maupun di bumi; Dia mengetahui apa yang kamu rahasiakan dan apa yang kamu nyatakan dan mengetahui (pula) apa yang kamu kerjakan"},{id:4,text:"\u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0623\u06e1\u062a\u0650\u064a\u0647\u0650\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0621\u064e\u0627\u064a\u064e\u0629\u0656 \u0645\u0651\u0650\u0646\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0639\u064e\u0646\u06e1\u0647\u064e\u0627 \u0645\u064f\u0639\u06e1\u0631\u0650\u0636\u0650\u064a\u0646\u064e",translation:"(Dan setiap ayat dari ayat-ayat304) Tuhan yang sampai kepada mereka (orang kafir), semuanya selalu diingkarinya"},{id:5,text:"\u0641\u064e\u0642\u064e\u062f\u06e1 \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u06e1 \u0641\u064e\u0633\u064e\u0648\u06e1\u0641\u064e \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u0647\u0650\u0645\u06e1 \u0623\u064e\u0646\u06e2\u0628\u064e\u0640\u0670\u0653\u0624\u064f\u0627\u0652 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6 \u064a\u064e\u0633\u06e1\u062a\u064e\u0647\u06e1\u0632\u0650\u0621\u064f\u0648\u0646\u064e",translation:"Sungguh, mereka telah mendustakan kebenaran (Alquran) ketika sampai kepada mereka, maka kelak akan sampai kepada mereka (kenyataan dari) berita-berita yang selalu mereka perolok-olokkan"},{id:6,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0631\u064e\u0648\u06e1\u0627\u0652 \u0643\u064e\u0645\u06e1 \u0623\u064e\u0647\u06e1\u0644\u064e\u0643\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u0645 \u0645\u0651\u0650\u0646 \u0642\u064e\u0631\u06e1\u0646\u0656 \u0645\u0651\u064e\u0643\u0651\u064e\u0646\u0651\u064e\u0640\u0670\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0645\u064e\u0627 \u0644\u064e\u0645\u06e1 \u0646\u064f\u0645\u064e\u0643\u0651\u0650\u0646 \u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0645\u0651\u0650\u062f\u06e1\u0631\u064e\u0627\u0631\u0657\u0627 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u064e \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0645\u0650\u0646 \u062a\u064e\u062d\u06e1\u062a\u0650\u0647\u0650\u0645\u06e1 \u0641\u064e\u0623\u064e\u0647\u06e1\u0644\u064e\u0643\u06e1\u0646\u064e\u0670\u0647\u064f\u0645 \u0628\u0650\u0630\u064f\u0646\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0623\u064e\u0646\u0634\u064e\u0623\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u0647\u0650\u0645\u06e1 \u0642\u064e\u0631\u06e1\u0646\u064b\u0627 \u0621\u064e\u0627\u062e\u064e\u0631\u0650\u064a\u0646\u064e",translation:"Tidakkah mereka memperhatikan berapa banyak generasi sebelum mereka yang telah Kami binasakan, padahal (generasi itu), telah Kami teguhkan kedudukannya di bumi, yaitu keteguhan yang belum pernah Kami berikan kepadamu. Kami curahkan hujan yang lebat untuk mereka dan Kami jadikan sungai-sungai mengalir di bawah mereka, kemudian Kami binasakan mereka karena dosa-dosa mereka sendiri, dan Kami ciptakan generasi yang lain setelah generasi mereka"},{id:7,text:"\u0648\u064e\u0644\u064e\u0648\u06e1 \u0646\u064e\u0632\u0651\u064e\u0644\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0643\u0650\u062a\u064e\u0670\u0628\u0657\u0627 \u0641\u0650\u064a \u0642\u0650\u0631\u06e1\u0637\u064e\u0627\u0633\u0656 \u0641\u064e\u0644\u064e\u0645\u064e\u0633\u064f\u0648\u0647\u064f \u0628\u0650\u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u0647\u0650\u0645\u06e1 \u0644\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u06e1 \u0647\u064e\u0670\u0630\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0633\u0650\u062d\u06e1\u0631\u065e \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u065e",translation:"Dan sekiranya Kami turunkan kepadamu (Muhammad) tulisan di atas kertas, lalu mereka dapat memegangnya dengan tangan mereka sendiri, niscaya orang-orang kafir itu akan berkata, \"Ini tidak lain hanyalah sihir yang nyata"},{id:8,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0648\u06e1\u0644\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0645\u064e\u0644\u064e\u0643\u065e\u06d6 \u0648\u064e\u0644\u064e\u0648\u06e1 \u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0627 \u0645\u064e\u0644\u064e\u0643\u0657\u0627 \u0644\u0651\u064e\u0642\u064f\u0636\u0650\u064a\u064e \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0631\u064f \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0627 \u064a\u064f\u0646\u0638\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan mereka berkata, \"Mengapa tidak diturunkan malaikat kepadanya (Muhammad)?\"305) Jika Kami turunkan malaikat (kepadanya), tentu selesailah urusan itu,306) tetapi mereka tidak diberi penangguhan (sedikit pun)"},{id:9,text:"\u0648\u064e\u0644\u064e\u0648\u06e1 \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f \u0645\u064e\u0644\u064e\u0643\u0657\u0627 \u0644\u0651\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f \u0631\u064e\u062c\u064f\u0644\u0657\u0627 \u0648\u064e\u0644\u064e\u0644\u064e\u0628\u064e\u0633\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0645\u0651\u064e\u0627 \u064a\u064e\u0644\u06e1\u0628\u0650\u0633\u064f\u0648\u0646\u064e",translation:"Dan sekiranya Rasul itu Kami jadikan (dari) malaikat, pastilah Kami jadikan dia (berwujud) laki-laki, dan (dengan demikian) pasti Kami akan menjadikan mereka tetap ragu sebagaimana kini mereka ragu"},{id:10,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0650 \u0671\u0633\u06e1\u062a\u064f\u0647\u06e1\u0632\u0650\u0626\u064e \u0628\u0650\u0631\u064f\u0633\u064f\u0644\u0656 \u0645\u0651\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064e \u0641\u064e\u062d\u064e\u0627\u0642\u064e \u0628\u0650\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0633\u064e\u062e\u0650\u0631\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6 \u064a\u064e\u0633\u06e1\u062a\u064e\u0647\u06e1\u0632\u0650\u0621\u064f\u0648\u0646\u064e",translation:"Dan sungguh, beberapa Rasul sebelum engkau (Muhammad) telah diperolok-olokkan, sehingga turunlah azab kepada orang-orang yang mencemoohkan itu sebagai balasan atas olok-olokan mereka"},{id:11,text:"\u0642\u064f\u0644\u06e1 \u0633\u0650\u064a\u0631\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u062b\u064f\u0645\u0651\u064e \u0671\u0646\u0638\u064f\u0631\u064f\u0648\u0627\u0652 \u0643\u064e\u064a\u06e1\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0670\u0642\u0650\u0628\u064e\u0629\u064f \u0671\u0644\u06e1\u0645\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u0650\u064a\u0646\u064e",translation:"Katakanlah (Muhammad), \"Jelajahilah bumi, kemudian perhatikanlah bagaimana kesudahan orang-orang yang mendustakan itu"},{id:12,text:"\u0642\u064f\u0644 \u0644\u0651\u0650\u0645\u064e\u0646 \u0645\u0651\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d6 \u0642\u064f\u0644 \u0644\u0651\u0650\u0644\u0651\u064e\u0647\u0650\u06da \u0643\u064e\u062a\u064e\u0628\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0646\u064e\u0641\u06e1\u0633\u0650\u0647\u0650 \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0629\u064e\u06da \u0644\u064e\u064a\u064e\u062c\u06e1\u0645\u064e\u0639\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u0644\u064e\u0627 \u0631\u064e\u064a\u06e1\u0628\u064e \u0641\u0650\u064a\u0647\u0650\u06da \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062e\u064e\u0633\u0650\u0631\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u06e1 \u0641\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Katakanlah (Muhammad), \"Milik siapakah apa yang di langit dan di bumi?\" Katakanlah, \"Milik Allah.\" Dia telah menetapkan (sifat) kasih sayang pada diri-Nya.308) Dia sungguh akan mengumpulkan kamu pada hari Kiamat yang tidak diragukan lagi. Orang-orang yang merugikan dirinya, mereka itu tidak beriman"},{id:13,text:"\u06de\u0648\u064e\u0644\u064e\u0647\u064f\u06e5 \u0645\u064e\u0627 \u0633\u064e\u0643\u064e\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u0650 \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650\u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u0650\u064a\u0639\u064f \u0671\u0644\u06e1\u0639\u064e\u0644\u0650\u064a\u0645\u064f",translation:"Dan milik-Nyalah segala apa yang ada pada malam dan siang hari. Dan Dialah Yang Maha Mendengar, Maha Mengetahui"},{id:14,text:"\u0642\u064f\u0644\u06e1 \u0623\u064e\u063a\u064e\u064a\u06e1\u0631\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f \u0648\u064e\u0644\u0650\u064a\u0651\u0657\u0627 \u0641\u064e\u0627\u0637\u0650\u0631\u0650 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0647\u064f\u0648\u064e \u064a\u064f\u0637\u06e1\u0639\u0650\u0645\u064f \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0637\u06e1\u0639\u064e\u0645\u064f\u06d7 \u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064f\u0645\u0650\u0631\u06e1\u062a\u064f \u0623\u064e\u0646\u06e1 \u0623\u064e\u0643\u064f\u0648\u0646\u064e \u0623\u064e\u0648\u0651\u064e\u0644\u064e \u0645\u064e\u0646\u06e1 \u0623\u064e\u0633\u06e1\u0644\u064e\u0645\u064e\u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0634\u06e1\u0631\u0650\u0643\u0650\u064a\u0646\u064e",translation:"Katakanlah (Muhammad), \"Apakah aku akan menjadikan pelindung selain Allah yang menjadikan langit dan bumi, padahal Dia memberi makan dan tidak diberi makan?\" Katakanlah, \"Sesungguhnya aku diperintahkan agar aku menjadi orang yang pertama berserah diri (kepada Allah), dan jangan sekali-kali kamu masuk golongan orang-orang musyrik"},{id:15,text:"\u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0625\u0650\u0646\u06e1 \u0639\u064e\u0635\u064e\u064a\u06e1\u062a\u064f \u0631\u064e\u0628\u0651\u0650\u064a \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u064a\u064e\u0648\u06e1\u0645\u064d \u0639\u064e\u0638\u0650\u064a\u0645\u0656",translation:"Katakanlah (Muhammad), \"Aku benar-benar takut akan azab hari yang besar (hari Kiamat), jika aku mendurhakai Tuhanku"},{id:16,text:"\u0645\u0651\u064e\u0646 \u064a\u064f\u0635\u06e1\u0631\u064e\u0641\u06e1 \u0639\u064e\u0646\u06e1\u0647\u064f \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u0641\u064e\u0642\u064e\u062f\u06e1 \u0631\u064e\u062d\u0650\u0645\u064e\u0647\u064f\u06e5\u06da \u0648\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0671\u0644\u06e1\u0641\u064e\u0648\u06e1\u0632\u064f \u0671\u0644\u06e1\u0645\u064f\u0628\u0650\u064a\u0646\u064f",translation:"Barang siapa yang dijauhkan dari azab atas dirinya pada hari itu, maka sungguh, Allah telah memberikan rahmat kepadanya. Dan itulah kemenangan yang nyata"},{id:17,text:"\u0648\u064e\u0625\u0650\u0646 \u064a\u064e\u0645\u06e1\u0633\u064e\u0633\u06e1\u0643\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0636\u064f\u0631\u0651\u0656 \u0641\u064e\u0644\u064e\u0627 \u0643\u064e\u0627\u0634\u0650\u0641\u064e \u0644\u064e\u0647\u064f\u06e5\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e\u06d6 \u0648\u064e\u0625\u0650\u0646 \u064a\u064e\u0645\u06e1\u0633\u064e\u0633\u06e1\u0643\u064e \u0628\u0650\u062e\u064e\u064a\u06e1\u0631\u0656 \u0641\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0642\u064e\u062f\u0650\u064a\u0631\u065e",translation:"Dan jika Allah menimpakan suatu bencana kepadamu, tidak ada yang dapat menghilangkannya selain Dia. Dan jika Dia mendatangkan kebaikan kepadamu, maka Dia Maha Kuasa atas segala sesuatu"},{id:18,text:"\u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0642\u064e\u0627\u0647\u0650\u0631\u064f \u0641\u064e\u0648\u06e1\u0642\u064e \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650\u06e6\u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u062d\u064e\u0643\u0650\u064a\u0645\u064f \u0671\u0644\u06e1\u062e\u064e\u0628\u0650\u064a\u0631\u064f",translation:"Dan Dialah yang berkuasa atas hamba-hamba-Nya. Dan Dia Mahabijaksana, Maha Mengetahui"},{id:19,text:"\u0642\u064f\u0644\u06e1 \u0623\u064e\u064a\u0651\u064f \u0634\u064e\u064a\u06e1\u0621\u064d \u0623\u064e\u0643\u06e1\u0628\u064e\u0631\u064f \u0634\u064e\u0647\u064e\u0670\u062f\u064e\u0629\u0657\u06d6 \u0642\u064f\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06d6 \u0634\u064e\u0647\u0650\u064a\u062f\u064f\u06e2 \u0628\u064e\u064a\u06e1\u0646\u0650\u064a \u0648\u064e\u0628\u064e\u064a\u06e1\u0646\u064e\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0623\u064f\u0648\u062d\u0650\u064a\u064e \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u064f \u0644\u0650\u0623\u064f\u0646\u0630\u0650\u0631\u064e\u0643\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6 \u0648\u064e\u0645\u064e\u0646\u06e2 \u0628\u064e\u0644\u064e\u063a\u064e\u06da \u0623\u064e\u0626\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0644\u064e\u062a\u064e\u0634\u06e1\u0647\u064e\u062f\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0651\u064e \u0645\u064e\u0639\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0621\u064e\u0627\u0644\u0650\u0647\u064e\u0629\u064b \u0623\u064f\u062e\u06e1\u0631\u064e\u0649\u0670\u06da \u0642\u064f\u0644 \u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0634\u06e1\u0647\u064e\u062f\u064f\u06da \u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0647\u064f\u0648\u064e \u0625\u0650\u0644\u064e\u0670\u0647\u065e \u0648\u064e\u0670\u062d\u0650\u062f\u065e \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0646\u0650\u064a \u0628\u064e\u0631\u0650\u064a\u0653\u0621\u065e \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u062a\u064f\u0634\u06e1\u0631\u0650\u0643\u064f\u0648\u0646\u064e",translation:"Katakanlah (Muhammad), \"Siapakah yang lebih kuat kesaksiannya?\" Katakanlah, \"Allah, Dia menjadi saksi antara aku dan kamu. Alquran ini diwahyukan kepadaku agar dengan itu aku memberi peringatan kepadamu dan kepada orang yang sampai (Alquran kepadanya). Dapatkah kamu benar-benar bersaksi bahwa ada tuhan-tuhan lain bersama Allah?\" Katakanlah, \"Aku tidak dapat bersaksi.\" Katakanlah, \"Sesungguhnya hanya Dialah Tuhan Yang Maha Esa dan aku berlepas diri dari apa yang kamu persekutukan (dengan Allah)"},{id:20,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u064a\u064e\u0639\u06e1\u0631\u0650\u0641\u064f\u0648\u0646\u064e\u0647\u064f\u06e5 \u0643\u064e\u0645\u064e\u0627 \u064a\u064e\u0639\u06e1\u0631\u0650\u0641\u064f\u0648\u0646\u064e \u0623\u064e\u0628\u06e1\u0646\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u064f\u06d8 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062e\u064e\u0633\u0650\u0631\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u06e1 \u0641\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Orang-orang yang telah Kami berikan kitab kepadanya, mereka mengenalnya (Muhammad) seperti mereka mengenal anak-anaknya sendiri. Orang-orang yang merugikan dirinya, mereka itu tidak beriman (kepada Allah)"},{id:21,text:"\u0648\u064e\u0645\u064e\u0646\u06e1 \u0623\u064e\u0638\u06e1\u0644\u064e\u0645\u064f \u0645\u0650\u0645\u0651\u064e\u0646\u0650 \u0671\u0641\u06e1\u062a\u064e\u0631\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u0630\u0650\u0628\u064b\u0627 \u0623\u064e\u0648\u06e1 \u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0647\u0650\u06e6\u0653\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0627 \u064a\u064f\u0641\u06e1\u0644\u0650\u062d\u064f \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Dan siapakah yang lebih zalim daripada orang yang mengada-adakan suatu kebohongan terhadap Allah, atau yang mendustakan ayat-ayat-Nya? Sesungguhnya orang-orang yang zalim itu tidak beruntung"},{id:22,text:"\u0648\u064e\u064a\u064e\u0648\u06e1\u0645\u064e \u0646\u064e\u062d\u06e1\u0634\u064f\u0631\u064f\u0647\u064f\u0645\u06e1 \u062c\u064e\u0645\u0650\u064a\u0639\u0657\u0627 \u062b\u064f\u0645\u0651\u064e \u0646\u064e\u0642\u064f\u0648\u0644\u064f \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u0634\u06e1\u0631\u064e\u0643\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u064a\u06e1\u0646\u064e \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0653\u0624\u064f\u0643\u064f\u0645\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0632\u06e1\u0639\u064f\u0645\u064f\u0648\u0646\u064e",translation:"Dan (ingatlah), pada hari ketika Kami mengumpulkan mereka semua kemudian Kami berfirman kepada orang-orang yang menyekutukan Allah, \"Dimanakah sembahan-sembahanmu yang dahulu kamu klaim (sebagai sekutu-sekutu Kami)"},{id:23,text:"\u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0645\u06e1 \u062a\u064e\u0643\u064f\u0646 \u0641\u0650\u062a\u06e1\u0646\u064e\u062a\u064f\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627 \u0645\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0645\u064f\u0634\u06e1\u0631\u0650\u0643\u0650\u064a\u0646\u064e",translation:"Kemudian tidaklah ada jawaban bohong mereka, kecuali mengatakan, \"Demi Allah, ya Tuhan kami, tidaklah kami mempersekutukan Allah"},{id:24,text:"\u0671\u0646\u0638\u064f\u0631\u06e1 \u0643\u064e\u064a\u06e1\u0641\u064e \u0643\u064e\u0630\u064e\u0628\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u06e1\u06da \u0648\u064e\u0636\u064e\u0644\u0651\u064e \u0639\u064e\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0641\u06e1\u062a\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Lihatlah, bagaimana mereka berbohong terhadap diri mereka sendiri. Dan sesembahan yang mereka ada-adakan dahulu akan hilang dari mereka"},{id:25,text:"\u0648\u064e\u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0646 \u064a\u064e\u0633\u06e1\u062a\u064e\u0645\u0650\u0639\u064f \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e\u06d6 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u06e1 \u0623\u064e\u0643\u0650\u0646\u0651\u064e\u0629\u064b \u0623\u064e\u0646 \u064a\u064e\u0641\u06e1\u0642\u064e\u0647\u064f\u0648\u0647\u064f \u0648\u064e\u0641\u0650\u064a\u0653 \u0621\u064e\u0627\u0630\u064e\u0627\u0646\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0642\u06e1\u0631\u0657\u0627\u06da \u0648\u064e\u0625\u0650\u0646 \u064a\u064e\u0631\u064e\u0648\u06e1\u0627\u0652 \u0643\u064f\u0644\u0651\u064e \u0621\u064e\u0627\u064a\u064e\u0629\u0656 \u0644\u0651\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u064e\u0627\u06d6 \u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064f\u0648\u0643\u064e \u064a\u064f\u062c\u064e\u0670\u062f\u0650\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u06e1 \u0647\u064e\u0670\u0630\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0633\u064e\u0670\u0637\u0650\u064a\u0631\u064f \u0671\u0644\u06e1\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",translation:"Dan di antara mereka ada yang mendengarkan bacaanmu (Muhammad), dan Kami telah menjadikan hati mereka tertutup (sehingga mereka tidak) memahaminya, dan telinganya tersumbat. Dan kalaupun mereka melihat segala tanda (kebenaran), mereka tetap tidak mau beriman kepadanya. Sehingga apabila mereka datang kepadamu untuk membantahmu, orang-orang kafir itu berkata, \"Ini (Alquran) tidak lain hanyalah dongengan orang-orang terdahulu"},{id:26,text:"\u0648\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0646\u06e1\u0647\u064e\u0648\u06e1\u0646\u064e \u0639\u064e\u0646\u06e1\u0647\u064f \u0648\u064e\u064a\u064e\u0646\u06e1\u0640\u0654\u064e\u0648\u06e1\u0646\u064e \u0639\u064e\u0646\u06e1\u0647\u064f\u06d6 \u0648\u064e\u0625\u0650\u0646 \u064a\u064f\u0647\u06e1\u0644\u0650\u0643\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0634\u06e1\u0639\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Dan mereka melarang (orang lain) mendengarkan (Alquran) dan mereka sendiri menjauhkan diri daripadanya, dan mereka hanyalah membinasakan diri mereka sendiri, sedang mereka tidak menyadari"},{id:27,text:"\u0648\u064e\u0644\u064e\u0648\u06e1 \u062a\u064e\u0631\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u06e1 \u0648\u064f\u0642\u0650\u0641\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0641\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u064a\u064e\u0670\u0644\u064e\u064a\u06e1\u062a\u064e\u0646\u064e\u0627 \u0646\u064f\u0631\u064e\u062f\u0651\u064f \u0648\u064e\u0644\u064e\u0627 \u0646\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627 \u0648\u064e\u0646\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dan seandainya engkau (Muhammad) melihat ketika mereka dihadapkan ke neraka, mereka berkata, \"Seandainya kami dikembalikan (ke dunia) tentu kami tidak akan mendustakan ayat-ayat Tuhan kami, serta menjadi orang-orang yang beriman"},{id:28,text:"\u0628\u064e\u0644\u06e1 \u0628\u064e\u062f\u064e\u0627 \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064f\u062e\u06e1\u0641\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f\u06d6 \u0648\u064e\u0644\u064e\u0648\u06e1 \u0631\u064f\u062f\u0651\u064f\u0648\u0627\u0652 \u0644\u064e\u0639\u064e\u0627\u062f\u064f\u0648\u0627\u0652 \u0644\u0650\u0645\u064e\u0627 \u0646\u064f\u0647\u064f\u0648\u0627\u0652 \u0639\u064e\u0646\u06e1\u0647\u064f \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0643\u064e\u0670\u0630\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Tetapi (sebenarnya) bagi mereka telah nyata kejahatan yang mereka sembunyikan dahulu. Seandainya mereka dikembalikan ke dunia, tentu mereka akan mengulang kembali apa yang telah dilarang mengerjakannya. Mereka itu sungguh pendusta"},{id:29,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u06e1 \u0647\u0650\u064a\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u062d\u064e\u064a\u064e\u0627\u062a\u064f\u0646\u064e\u0627 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u0646\u064e\u062d\u06e1\u0646\u064f \u0628\u0650\u0645\u064e\u0628\u06e1\u0639\u064f\u0648\u062b\u0650\u064a\u0646\u064e",translation:"Dan tentu mereka akan mengatakan (pula), \"Hidup hanyalah di dunia ini, dan kita tidak akan dibangkitkan"},{id:30,text:"\u0648\u064e\u0644\u064e\u0648\u06e1 \u062a\u064e\u0631\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u06e1 \u0648\u064f\u0642\u0650\u0641\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1\u06da \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0644\u064e\u064a\u06e1\u0633\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650\u06da \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0628\u064e\u0644\u064e\u0649\u0670 \u0648\u064e\u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627\u06da \u0642\u064e\u0627\u0644\u064e \u0641\u064e\u0630\u064f\u0648\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0643\u06e1\u0641\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Dan seandainya engkau (Muhammad) melihat ketika mereka dihadapkan kepada Tuhannya (tentulah engkau melihat peristiwa yang mengharukan). Dia Berfirman, \"Bukankah (kebangkitan) ini benar?\" Mereka menjawab, \"Sungguh benar, demi Tuhan kami.\" Dia berfirman, \"Rasakanlah azab ini, karena dahulu kamu mengingkarinya"},{id:31,text:"\u0642\u064e\u062f\u06e1 \u062e\u064e\u0633\u0650\u0631\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0644\u0650\u0642\u064e\u0627\u0653\u0621\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u062a\u06e1\u0647\u064f\u0645\u064f \u0671\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064f \u0628\u064e\u063a\u06e1\u062a\u064e\u0629\u0657 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u064a\u064e\u0670\u062d\u064e\u0633\u06e1\u0631\u064e\u062a\u064e\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0641\u064e\u0631\u0651\u064e\u0637\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u062d\u06e1\u0645\u0650\u0644\u064f\u0648\u0646\u064e \u0623\u064e\u0648\u06e1\u0632\u064e\u0627\u0631\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0638\u064f\u0647\u064f\u0648\u0631\u0650\u0647\u0650\u0645\u06e1\u06da \u0623\u064e\u0644\u064e\u0627 \u0633\u064e\u0627\u0653\u0621\u064e \u0645\u064e\u0627 \u064a\u064e\u0632\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Sungguh rugi orang-orang yang mendustakan pertemuan dengan Allah; sehingga apabila Kiamat datang kepada mereka secara tiba-tiba, mereka berkata, \"Alangkah besarnya penyesalan kami terhadap kelalaian kami tentang Kiamat itu,\" sambil mereka memikul dosa-dosa di atas punggungnya. Alangkah buruknya apa yang mereka pikul"},{id:32,text:"\u0648\u064e\u0645\u064e\u0627 \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u064f \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0644\u064e\u0639\u0650\u0628\u065e \u0648\u064e\u0644\u064e\u0647\u06e1\u0648\u065e\u06d6 \u0648\u064e\u0644\u064e\u0644\u062f\u0651\u064e\u0627\u0631\u064f \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u064f \u062e\u064e\u064a\u06e1\u0631\u065e \u0644\u0651\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e\u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Dan kehidupan dunia ini, hanyalah permainan dan senda gurau. Sedangkan negeri akhirat itu, sungguh lebih baik bagi orang-orang yang bertakwa. Tidakkah kamu mengerti"},{id:33,text:"\u0642\u064e\u062f\u06e1 \u0646\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u064a\u064e\u062d\u06e1\u0632\u064f\u0646\u064f\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e\u06d6 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f\u0648\u0646\u064e\u0643\u064e \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u062c\u06e1\u062d\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Sungguh, Kami mengetahui bahwa apa yang mereka katakan itu menyedihkan hatimu (Muhammad), (janganlah bersedih hati) karena sebenarnya mereka bukan mendustakanmu, tetapi orang zalim itu mengingkari ayat-ayat Allah"},{id:34,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0643\u064f\u0630\u0651\u0650\u0628\u064e\u062a\u06e1 \u0631\u064f\u0633\u064f\u0644\u065e \u0645\u0651\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064e \u0641\u064e\u0635\u064e\u0628\u064e\u0631\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0643\u064f\u0630\u0651\u0650\u0628\u064f\u0648\u0627\u0652 \u0648\u064e\u0623\u064f\u0648\u0630\u064f\u0648\u0627\u0652 \u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0623\u064e\u062a\u064e\u0649\u0670\u0647\u064f\u0645\u06e1 \u0646\u064e\u0635\u06e1\u0631\u064f\u0646\u064e\u0627\u06da \u0648\u064e\u0644\u064e\u0627 \u0645\u064f\u0628\u064e\u062f\u0651\u0650\u0644\u064e \u0644\u0650\u0643\u064e\u0644\u0650\u0645\u064e\u0670\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u0643\u064e \u0645\u0650\u0646 \u0646\u0651\u064e\u0628\u064e\u0625\u0650\u064a\u0652 \u0671\u0644\u06e1\u0645\u064f\u0631\u06e1\u0633\u064e\u0644\u0650\u064a\u0646\u064e",translation:"Dan sesungguhnya Rasul-rasul sebelum engkau pun telah didustakan, tetapi mereka sabar terhadap pendustaan dan penganiayaan (yang dilakukan) terhadap mereka, sampai datang pertolongan Kami kepada mereka. Dan tidak ada yang dapat mengubah kalimat-kalimat (ketetapan) Allah. Dan sungguh, telah datang kepadamu sebagian dari berita Rasul-rasul itu"},{id:35,text:"\u0648\u064e\u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064e \u0643\u064e\u0628\u064f\u0631\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0625\u0650\u0639\u06e1\u0631\u064e\u0627\u0636\u064f\u0647\u064f\u0645\u06e1 \u0641\u064e\u0625\u0650\u0646\u0650 \u0671\u0633\u06e1\u062a\u064e\u0637\u064e\u0639\u06e1\u062a\u064e \u0623\u064e\u0646 \u062a\u064e\u0628\u06e1\u062a\u064e\u063a\u0650\u064a\u064e \u0646\u064e\u0641\u064e\u0642\u0657\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0623\u064e\u0648\u06e1 \u0633\u064f\u0644\u0651\u064e\u0645\u0657\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0641\u064e\u062a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e\u0647\u064f\u0645 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0629\u0656\u06da \u0648\u064e\u0644\u064e\u0648\u06e1 \u0634\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u062c\u064e\u0645\u064e\u0639\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0647\u064f\u062f\u064e\u0649\u0670\u06da \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u062c\u064e\u0670\u0647\u0650\u0644\u0650\u064a\u0646\u064e",translation:"Dan jika keberpalingan mereka terasa berat bagimu (Muhammad), maka sekiranya engkau dapat membuat lubang di bumi atau tangga ke langit lalu engkau dapat mendatangkan mukjizat kepada mereka, (maka buatlah). Dan sekiranya Allah menghendaki, tentu Dia jadikan mereka semua mengikuti petunjuk, sebab itu janganlah sekali-kali engkau termasuk orang-orang yang bodoh"},{id:36,text:"\u06de\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u062c\u0650\u064a\u0628\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0633\u06e1\u0645\u064e\u0639\u064f\u0648\u0646\u064e\u06d8 \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u064e\u0649\u0670 \u064a\u064e\u0628\u06e1\u0639\u064e\u062b\u064f\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u064a\u064f\u0631\u06e1\u062c\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Hanya orang-orang yang mendengar sajalah yang mematuhi (seruan Allah), dan orang-orang yang mati, kelak akan dibangkitkan oleh Allah, kemudian kepada-Nya mereka dikembalikan"},{id:37,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0648\u06e1\u0644\u064e\u0627 \u0646\u064f\u0632\u0651\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0621\u064e\u0627\u064a\u064e\u0629\u065e \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0647\u0650\u06e6\u06da \u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0642\u064e\u0627\u062f\u0650\u0631\u064c \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0646 \u064a\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u064e \u0621\u064e\u0627\u064a\u064e\u0629\u0657 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan mereka (orang-orang musyrik) berkata, \"Mengapa tidak diturunkan kepadanya (Muhammad) suatu mukjizat dari Tuhannya?\" Katakanlah, \"Sesungguhnya Allah berkuasa menurunkan suatu mukjizat, tetapi kebanyakan mereka tidak mengetahui"},{id:38,text:"\u0648\u064e\u0645\u064e\u0627 \u0645\u0650\u0646 \u062f\u064e\u0627\u0653\u0628\u0651\u064e\u0629\u0656 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0644\u064e\u0627 \u0637\u064e\u0640\u0670\u0653\u0626\u0650\u0631\u0656 \u064a\u064e\u0637\u0650\u064a\u0631\u064f \u0628\u0650\u062c\u064e\u0646\u064e\u0627\u062d\u064e\u064a\u06e1\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064f\u0645\u064e\u0645\u064c \u0623\u064e\u0645\u06e1\u062b\u064e\u0627\u0644\u064f\u0643\u064f\u0645\u06da \u0645\u0651\u064e\u0627 \u0641\u064e\u0631\u0651\u064e\u0637\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0645\u0650\u0646 \u0634\u064e\u064a\u06e1\u0621\u0656\u06da \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u064a\u064f\u062d\u06e1\u0634\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan tidak ada seekor binatang pun yang ada di bumi dan burung-burung yang terbang dengan kedua sayapnya, melainkan semuanya merupakan umat-umat (juga) seperti kamu. Tidak ada sesuatu pun yang Kami luputkan di dalam Kitab,309) kemudian kepada Tuhan mereka dikumpulkan"},{id:39,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0635\u064f\u0645\u0651\u065e \u0648\u064e\u0628\u064f\u0643\u06e1\u0645\u065e \u0641\u0650\u064a \u0671\u0644\u0638\u0651\u064f\u0644\u064f\u0645\u064e\u0670\u062a\u0650\u06d7 \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0625\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064f\u0636\u06e1\u0644\u0650\u0644\u06e1\u0647\u064f \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0623\u06e1 \u064a\u064e\u062c\u06e1\u0639\u064e\u0644\u06e1\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0670\u0637\u0656 \u0645\u0651\u064f\u0633\u06e1\u062a\u064e\u0642\u0650\u064a\u0645\u0656",translation:"Dan orang-orang yang mendustakan ayat-ayat Kami adalah tuli, bisu dan berada dalam gelap gulita. Barang siapa yang dikehendaki Allah (dalam kesesatan), niscaya disesatkan-Nya. Dan barang siapa dikehendaki Allah (untuk diberi petunjuk), niscaya Dia menjadikannya berada di atas jalan yang lurus"},{id:40,text:"\u0642\u064f\u0644\u06e1 \u0623\u064e\u0631\u064e\u0621\u064e\u064a\u06e1\u062a\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0646\u06e1 \u0623\u064e\u062a\u064e\u0649\u0670\u0643\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0648\u06e1 \u0623\u064e\u062a\u064e\u062a\u06e1\u0643\u064f\u0645\u064f \u0671\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064f \u0623\u064e\u063a\u064e\u064a\u06e1\u0631\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0635\u064e\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Katakanlah (Muhammad), \"Terangkanlah kepadaku jika siksaan Allah sampai kepadamu, atau hari Kiamat sampai kepadamu, apakah kamu akan menyeru (tuhan) selain Allah, jika kamu orang yang benar"},{id:41,text:"\u0628\u064e\u0644\u06e1 \u0625\u0650\u064a\u0651\u064e\u0627\u0647\u064f \u062a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e \u0641\u064e\u064a\u064e\u0643\u06e1\u0634\u0650\u0641\u064f \u0645\u064e\u0627 \u062a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0625\u0650\u0646 \u0634\u064e\u0627\u0653\u0621\u064e \u0648\u064e\u062a\u064e\u0646\u0633\u064e\u0648\u06e1\u0646\u064e \u0645\u064e\u0627 \u062a\u064f\u0634\u06e1\u0631\u0650\u0643\u064f\u0648\u0646\u064e",translation:"(Tidak), hanya kepada-Nya kamu minta tolong. Jika Dia menghendaki, Dia hilangkan apa (bahaya) yang kamu mohonkan kepada-Nya, dan kamu tinggalkan apa yang kamu persekutukan (dengan Allah)"},{id:42,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064f\u0645\u064e\u0645\u0656 \u0645\u0651\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064e \u0641\u064e\u0623\u064e\u062e\u064e\u0630\u06e1\u0646\u064e\u0670\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0628\u064e\u0623\u06e1\u0633\u064e\u0627\u0653\u0621\u0650 \u0648\u064e\u0671\u0644\u0636\u0651\u064e\u0631\u0651\u064e\u0627\u0653\u0621\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u062a\u064e\u0636\u064e\u0631\u0651\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Dan sungguh, Kami telah mengutus (Rasul-rasul) kepada umat-umat sebelum engkau, kemudian Kami siksa mereka dengan (menimpakan) kemelaratan dan kesengsaraan, agar mereka memohon (kepada Allah) dengan kerendahan hati"},{id:43,text:"\u0641\u064e\u0644\u064e\u0648\u06e1\u0644\u064e\u0627\u0653 \u0625\u0650\u0630\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645 \u0628\u064e\u0623\u06e1\u0633\u064f\u0646\u064e\u0627 \u062a\u064e\u0636\u064e\u0631\u0651\u064e\u0639\u064f\u0648\u0627\u0652 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u0642\u064e\u0633\u064e\u062a\u06e1 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0632\u064e\u064a\u0651\u064e\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u064f \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Tetapi mengapa mereka tidak memohon (kepada Allah) dengan kerendahan hati ketika siksaan Kami datang menimpa mereka? Bahkan hati mereka telah menjadi keras dan setan pun menjadikan terasa indah bagi mereka apa yang selalu mereka kerjakan"},{id:44,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0646\u064e\u0633\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u0630\u064f\u0643\u0651\u0650\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6 \u0641\u064e\u062a\u064e\u062d\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0623\u064e\u0628\u06e1\u0648\u064e\u0670\u0628\u064e \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u064d \u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u064e\u0627 \u0641\u064e\u0631\u0650\u062d\u064f\u0648\u0627\u0652 \u0628\u0650\u0645\u064e\u0627\u0653 \u0623\u064f\u0648\u062a\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u062e\u064e\u0630\u06e1\u0646\u064e\u0670\u0647\u064f\u0645 \u0628\u064e\u063a\u06e1\u062a\u064e\u0629\u0657 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0645 \u0645\u0651\u064f\u0628\u06e1\u0644\u0650\u0633\u064f\u0648\u0646\u064e",translation:"Maka ketika mereka melupakan peringatan yang telah diberikan kepada mereka, Kami pun membukakan semua pintu (kesenangan) untuk mereka. Sehingga ketika mereka bergembira dengan apa yang telah diberikan kepada mereka, Kami siksa mereka secara tiba-tiba, maka ketika itu mereka terdiam putus asa"},{id:45,text:"\u0641\u064e\u0642\u064f\u0637\u0650\u0639\u064e \u062f\u064e\u0627\u0628\u0650\u0631\u064f \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627\u0652\u06da \u0648\u064e\u0671\u0644\u06e1\u062d\u064e\u0645\u06e1\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0631\u064e\u0628\u0651\u0650 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Maka orang-orang yang zalim itu dimusnahkan sampai ke akar-akarnya. Dan segala puji bagi Allah, Tuhan seluruh alam"},{id:46,text:"\u0642\u064f\u0644\u06e1 \u0623\u064e\u0631\u064e\u0621\u064e\u064a\u06e1\u062a\u064f\u0645\u06e1 \u0625\u0650\u0646\u06e1 \u0623\u064e\u062e\u064e\u0630\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0633\u064e\u0645\u06e1\u0639\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0628\u06e1\u0635\u064e\u0670\u0631\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u062e\u064e\u062a\u064e\u0645\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0643\u064f\u0645 \u0645\u0651\u064e\u0646\u06e1 \u0625\u0650\u0644\u064e\u0670\u0647\u064c \u063a\u064e\u064a\u06e1\u0631\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u0643\u064f\u0645 \u0628\u0650\u0647\u0650\u06d7 \u0671\u0646\u0638\u064f\u0631\u06e1 \u0643\u064e\u064a\u06e1\u0641\u064e \u0646\u064f\u0635\u064e\u0631\u0651\u0650\u0641\u064f \u0671\u0644\u06e1\u0623\u0653\u064a\u064e\u0670\u062a\u0650 \u062b\u064f\u0645\u0651\u064e \u0647\u064f\u0645\u06e1 \u064a\u064e\u0635\u06e1\u062f\u0650\u0641\u064f\u0648\u0646\u064e",translation:"Katakanlah (Muhammad), \"Terangkanlah kepadaku jika Allah mencabut pendengaran dan penglihatan serta menutup hatimu, siapakah tuhan selain Allah yang kuasa mengembalikannya kepadamu?\" Perhatikanlah, bagaimana Kami menjelaskan berulang-ulang (kepada mereka) tanda-tanda kekuasaan (Kami), tetapi mereka tetap berpaling"},{id:47,text:"\u0642\u064f\u0644\u06e1 \u0623\u064e\u0631\u064e\u0621\u064e\u064a\u06e1\u062a\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0646\u06e1 \u0623\u064e\u062a\u064e\u0649\u0670\u0643\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u064e\u063a\u06e1\u062a\u064e\u0629\u064b \u0623\u064e\u0648\u06e1 \u062c\u064e\u0647\u06e1\u0631\u064e\u0629\u064b \u0647\u064e\u0644\u06e1 \u064a\u064f\u0647\u06e1\u0644\u064e\u0643\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u064f \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Katakanlah (Muhammad), \"Terangkanlah kepadaku jika siksaan Allah sampai kepadamu secara tiba-tiba atau terang-terangan, maka adakah yang dibinasakan (Allah) selain orang-orang yang zalim"},{id:48,text:"\u0648\u064e\u0645\u064e\u0627 \u0646\u064f\u0631\u06e1\u0633\u0650\u0644\u064f \u0671\u0644\u06e1\u0645\u064f\u0631\u06e1\u0633\u064e\u0644\u0650\u064a\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064f\u0628\u064e\u0634\u0651\u0650\u0631\u0650\u064a\u0646\u064e \u0648\u064e\u0645\u064f\u0646\u0630\u0650\u0631\u0650\u064a\u0646\u064e\u06d6 \u0641\u064e\u0645\u064e\u0646\u06e1 \u0621\u064e\u0627\u0645\u064e\u0646\u064e \u0648\u064e\u0623\u064e\u0635\u06e1\u0644\u064e\u062d\u064e \u0641\u064e\u0644\u064e\u0627 \u062e\u064e\u0648\u06e1\u0641\u064c \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u06e1 \u064a\u064e\u062d\u06e1\u0632\u064e\u0646\u064f\u0648\u0646\u064e",translation:"Para Rasul yang Kami utus itu adalah untuk memberi kabar gembira dan memberi peringatan. Barang siapa beriman dan mengadakan perbaikan, maka tidak ada rasa takut pada mereka dan mereka tidak bersedih hati"},{id:49,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u064a\u064e\u0645\u064e\u0633\u0651\u064f\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0641\u06e1\u0633\u064f\u0642\u064f\u0648\u0646\u064e",translation:"Dan orang-orang yang mendustakan ayat-ayat Kami, akan ditimpa azab karena mereka selalu berbuat fasik (berbuat dosa)"},{id:50,text:"\u0642\u064f\u0644 \u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0642\u064f\u0648\u0644\u064f \u0644\u064e\u0643\u064f\u0645\u06e1 \u0639\u0650\u0646\u062f\u0650\u064a \u062e\u064e\u0632\u064e\u0627\u0653\u0626\u0650\u0646\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u0628\u064e \u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064e\u0642\u064f\u0648\u0644\u064f \u0644\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0646\u0651\u0650\u064a \u0645\u064e\u0644\u064e\u0643\u064c\u06d6 \u0625\u0650\u0646\u06e1 \u0623\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u064a\u064f\u0648\u062d\u064e\u0649\u0670\u0653 \u0625\u0650\u0644\u064e\u064a\u0651\u064e\u06da \u0642\u064f\u0644\u06e1 \u0647\u064e\u0644\u06e1 \u064a\u064e\u0633\u06e1\u062a\u064e\u0648\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0639\u06e1\u0645\u064e\u0649\u0670 \u0648\u064e\u0671\u0644\u06e1\u0628\u064e\u0635\u0650\u064a\u0631\u064f\u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u064e\u0641\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Katakanlah (Muhammad), \"Aku tidak mengatakan kepadamu, bahwa perbendaharaan Allah ada padaku, dan aku tidak mengetahui yang gaib dan aku tidak (pula) mengatakan kepadamu bahwa aku malaikat. Aku hanya mengikuti apa yang diwahyukan kepadaku.\" Katakanlah, \"Apakah sama antara orang yang buta dengan orang yang melihat? Apakah kamu tidak memikirkan (nya)"},{id:51,text:"\u0648\u064e\u0623\u064e\u0646\u0630\u0650\u0631\u06e1 \u0628\u0650\u0647\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062e\u064e\u0627\u0641\u064f\u0648\u0646\u064e \u0623\u064e\u0646 \u064a\u064f\u062d\u06e1\u0634\u064e\u0631\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0644\u064e\u064a\u06e1\u0633\u064e \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u06e6 \u0648\u064e\u0644\u0650\u064a\u0651\u065e \u0648\u064e\u0644\u064e\u0627 \u0634\u064e\u0641\u0650\u064a\u0639\u065e \u0644\u0651\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",translation:"Peringatkanlah dengannya (Alquran) itu orang yang takut akan dikumpulkan menghadap Tuhannya (pada hari Kiamat), tidak ada bagi mereka pelindung dan pemberi syafaat (pertolongan) selain Allah, agar mereka bertakwa"},{id:52,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0637\u06e1\u0631\u064f\u062f\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u063a\u064e\u062f\u064e\u0648\u0670\u0629\u0650 \u0648\u064e\u0671\u0644\u06e1\u0639\u064e\u0634\u0650\u064a\u0651\u0650 \u064a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0648\u064e\u062c\u06e1\u0647\u064e\u0647\u064f\u06e5\u06d6 \u0645\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0645\u0650\u0646\u06e1 \u062d\u0650\u0633\u064e\u0627\u0628\u0650\u0647\u0650\u0645 \u0645\u0651\u0650\u0646 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0648\u064e\u0645\u064e\u0627 \u0645\u0650\u0646\u06e1 \u062d\u0650\u0633\u064e\u0627\u0628\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0645\u0651\u0650\u0646 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0641\u064e\u062a\u064e\u0637\u06e1\u0631\u064f\u062f\u064e\u0647\u064f\u0645\u06e1 \u0641\u064e\u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Janganlah engkau mengusir orang-orang yang menyeru Tuhannya di pagi hari dan petang hari, mereka mengharapkan keridaan-Nya. Engkau tidak memikul tanggung jawab sedikit pun terhadap perbuatan mereka dan mereka tidak memikul tanggung jawab sedikit pun terhadap perbuatanmu, yang menyebabkan engkau (berhak) mengusir mereka, sehingga engkau termasuk orang-orang yang zalim"},{id:53,text:"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u062a\u064e\u0646\u0651\u064e\u0627 \u0628\u064e\u0639\u06e1\u0636\u064e\u0647\u064f\u0645 \u0628\u0650\u0628\u064e\u0639\u06e1\u0636\u0656 \u0644\u0651\u0650\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650 \u0645\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0645\u0651\u0650\u0646\u06e2 \u0628\u064e\u064a\u06e1\u0646\u0650\u0646\u064e\u0627\u0653\u06d7 \u0623\u064e\u0644\u064e\u064a\u06e1\u0633\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064e \u0628\u0650\u0671\u0644\u0634\u0651\u064e\u0640\u0670\u0643\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Demikianlah, Kami telah menguji sebagian mereka (orang yang kaya) dengan sebagian yang lain (orang yang miskin), agar mereka (orang yang kaya itu) berkata, \"Orang-orang semacam inikah di antara kita yang diberi anugerah oleh Allah?\" (Allah berfirman), \"Tidakkah Allah lebih mengetahui tentang mereka yang bersyukur (kepada-Nya)"},{id:54,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0641\u064e\u0642\u064f\u0644\u06e1 \u0633\u064e\u0644\u064e\u0670\u0645\u064c \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1\u06d6 \u0643\u064e\u062a\u064e\u0628\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0646\u064e\u0641\u06e1\u0633\u0650\u0647\u0650 \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0629\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u06e5 \u0645\u064e\u0646\u06e1 \u0639\u064e\u0645\u0650\u0644\u064e \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u0633\u064f\u0648\u0653\u0621\u064e\u06e2\u0627 \u0628\u0650\u062c\u064e\u0647\u064e\u0670\u0644\u064e\u0629\u0656 \u062b\u064f\u0645\u0651\u064e \u062a\u064e\u0627\u0628\u064e \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u0647\u0650\u06e6 \u0648\u064e\u0623\u064e\u0635\u06e1\u0644\u064e\u062d\u064e \u0641\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u06e5 \u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u065e",translation:"Dan apabila orang-orang yang beriman kepada ayat-ayat Kami datang kepadamu, maka katakanlah, \"Sal\u0101mun 'alaikum\" (selamat sejahtera untuk kamu).\" Tuhanmu telah menetapkan sifat kasih sayang pada diri-Nya, (yaitu) barang siapa berbuat kejahatan di antara kamu karena kebodohan, kemudian dia bertobat setelah itu dan memperbaiki diri, maka Dia Maha Pengampun, Maha Penyayang"},{id:55,text:"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064f\u0641\u064e\u0635\u0651\u0650\u0644\u064f \u0671\u0644\u06e1\u0623\u0653\u064a\u064e\u0670\u062a\u0650 \u0648\u064e\u0644\u0650\u062a\u064e\u0633\u06e1\u062a\u064e\u0628\u0650\u064a\u0646\u064e \u0633\u064e\u0628\u0650\u064a\u0644\u064f \u0671\u0644\u06e1\u0645\u064f\u062c\u06e1\u0631\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dan Demikianlah Kami terangkan ayat-ayat Alquran, (agar terlihat jelas jalan orang-orang yang saleh) dan agar terlihat jelas (pula) jalan orang-orang yang berdosa"},{id:56,text:"\u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u0650\u064a \u0646\u064f\u0647\u0650\u064a\u062a\u064f \u0623\u064e\u0646\u06e1 \u0623\u064e\u0639\u06e1\u0628\u064f\u062f\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0642\u064f\u0644 \u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f \u0623\u064e\u0647\u06e1\u0648\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u06e1 \u0642\u064e\u062f\u06e1 \u0636\u064e\u0644\u064e\u0644\u06e1\u062a\u064f \u0625\u0650\u0630\u0657\u0627 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u064e\u0627\u06e0 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0647\u06e1\u062a\u064e\u062f\u0650\u064a\u0646\u064e",translation:"Katakanlah (Muhammad), \"Aku dilarang menyembah tuhan-tuhan yang kamu sembah selain Allah.\" Katakanlah, \"Aku tidak akan mengikuti keinginanmu. Jika berbuat demikian, sungguh tersesatlah aku dan aku tidak termasuk orang yang mendapat petunjuk"},{id:57,text:"\u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u0650\u064a \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0629\u0656 \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u06e1\u062a\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6\u06da \u0645\u064e\u0627 \u0639\u0650\u0646\u062f\u0650\u064a \u0645\u064e\u0627 \u062a\u064e\u0633\u06e1\u062a\u064e\u0639\u06e1\u062c\u0650\u0644\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u0650\u06e6\u0653\u06da \u0625\u0650\u0646\u0650 \u0671\u0644\u06e1\u062d\u064f\u0643\u06e1\u0645\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0644\u0650\u0644\u0651\u064e\u0647\u0650\u06d6 \u064a\u064e\u0642\u064f\u0635\u0651\u064f \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064e\u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u062e\u064e\u064a\u06e1\u0631\u064f \u0671\u0644\u06e1\u0641\u064e\u0670\u0635\u0650\u0644\u0650\u064a\u0646\u064e",translation:"Katakanlah (Muhammad), \"Aku (berada) di atas keterangan yang nyata (Alquran) dari Tuhanku sedang kamu mendustakannya. Bukanlah kewenanganku (untuk menurunkan azab) yang kamu tuntut untuk disegerakan kedatangannya. Menetapkan (hukum itu) hanyalah hak Allah. Dia menerangkan kebenaran dan Dia Pemberi keputusan yang terbaik"},{id:58,text:"\u0642\u064f\u0644 \u0644\u0651\u064e\u0648\u06e1 \u0623\u064e\u0646\u0651\u064e \u0639\u0650\u0646\u062f\u0650\u064a \u0645\u064e\u0627 \u062a\u064e\u0633\u06e1\u062a\u064e\u0639\u06e1\u062c\u0650\u0644\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u0650\u06e6 \u0644\u064e\u0642\u064f\u0636\u0650\u064a\u064e \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0631\u064f \u0628\u064e\u064a\u06e1\u0646\u0650\u064a \u0648\u064e\u0628\u064e\u064a\u06e1\u0646\u064e\u0643\u064f\u0645\u06e1\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0628\u0650\u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Katakanlah (Muhammad) \"Seandainya ada padaku apa (azab) yang kamu minta agar disegerakan kedatangannya, tentu selesailah segala perkara antara aku dan kamu.\"311) Dan Allah lebih mengetahui tentang orang-orang yang zalim"},{id:59,text:"\u06de\u0648\u064e\u0639\u0650\u0646\u062f\u064e\u0647\u064f\u06e5 \u0645\u064e\u0641\u064e\u0627\u062a\u0650\u062d\u064f \u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u0628\u0650 \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0647\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e\u06da \u0648\u064e\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0628\u064e\u0631\u0651\u0650 \u0648\u064e\u0671\u0644\u06e1\u0628\u064e\u062d\u06e1\u0631\u0650\u06da \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0633\u06e1\u0642\u064f\u0637\u064f \u0645\u0650\u0646 \u0648\u064e\u0631\u064e\u0642\u064e\u0629\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u062d\u064e\u0628\u0651\u064e\u0629\u0656 \u0641\u0650\u064a \u0638\u064f\u0644\u064f\u0645\u064e\u0670\u062a\u0650 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0644\u064e\u0627 \u0631\u064e\u0637\u06e1\u0628\u0656 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0627\u0628\u0650\u0633\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0641\u0650\u064a \u0643\u0650\u062a\u064e\u0670\u0628\u0656 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u0656",translation:"Dan kunci-kunci semua yang gaib ada pada-Nya; tidak ada yang mengetahui selain Dia. Dia mengetahui apa yang ada di darat dan di laut. Tidak ada sehelai daun pun yang gugur yang tidak diketahui-Nya, tidak ada sebutir biji pun dalam kegelapan bumi dan tidak pula sesuatu yang basah atau yang kering, yang tidak tertulis dalam kitab yang nyata (Lau\u1e25 Ma\u1e25f\u016b\u1e93)"},{id:60,text:"\u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064e\u062a\u064e\u0648\u064e\u0641\u0651\u064e\u0649\u0670\u0643\u064f\u0645 \u0628\u0650\u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u0650 \u0648\u064e\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u062c\u064e\u0631\u064e\u062d\u06e1\u062a\u064f\u0645 \u0628\u0650\u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u0628\u06e1\u0639\u064e\u062b\u064f\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u0650 \u0644\u0650\u064a\u064f\u0642\u06e1\u0636\u064e\u0649\u0670\u0653 \u0623\u064e\u062c\u064e\u0644\u065e \u0645\u0651\u064f\u0633\u064e\u0645\u0651\u0657\u0649\u06d6 \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0645\u064e\u0631\u06e1\u062c\u0650\u0639\u064f\u0643\u064f\u0645\u06e1 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0643\u064f\u0645 \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan Dialah yang menidurkan kamu pada malam hari dan Dia mengetahui apa yang kamu kerjakan pada siang hari. Kemudian Dia membangunkan kamu pada siang hari untuk disempurnakan umurmu yang telah ditetapkan. Kemudian kepada-Nya tempat kamu kembali, lalu Dia memberitahukan kepadamu apa yang telah kamu kerjakan"},{id:61,text:"\u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0642\u064e\u0627\u0647\u0650\u0631\u064f \u0641\u064e\u0648\u06e1\u0642\u064e \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u064a\u064f\u0631\u06e1\u0633\u0650\u0644\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u062d\u064e\u0641\u064e\u0638\u064e\u0629\u064b \u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e \u0623\u064e\u062d\u064e\u062f\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u064f \u062a\u064e\u0648\u064e\u0641\u0651\u064e\u062a\u06e1\u0647\u064f \u0631\u064f\u0633\u064f\u0644\u064f\u0646\u064e\u0627 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064f\u0641\u064e\u0631\u0651\u0650\u0637\u064f\u0648\u0646\u064e",translation:"Dan Dialah Penguasa mutlak atas semua hamba-Nya, dan di utus-Nya kepadamu malaikat-malaikat penjaga, sehingga apabila kematian datang kepada salah seorang di antara kamu malaikat-malaikat Kami mencabut nyawanya dan mereka tidak melalaikan tugasnya"},{id:62,text:"\u062b\u064f\u0645\u0651\u064e \u0631\u064f\u062f\u0651\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0648\u06e1\u0644\u064e\u0649\u0670\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650\u06da \u0623\u064e\u0644\u064e\u0627 \u0644\u064e\u0647\u064f \u0671\u0644\u06e1\u062d\u064f\u0643\u06e1\u0645\u064f \u0648\u064e\u0647\u064f\u0648\u064e \u0623\u064e\u0633\u06e1\u0631\u064e\u0639\u064f \u0671\u0644\u06e1\u062d\u064e\u0670\u0633\u0650\u0628\u0650\u064a\u0646\u064e",translation:"Kemudian mereka (hamba-hamba Allah) dikembalikan kepada Allah, penguasa mereka yang sebenarnya. Ketahuilah bahwa segala hukum (pada hari itu) ada pada-Nya. Dan Dialah pembuat perhitungan yang paling cepat"},{id:63,text:"\u0642\u064f\u0644\u06e1 \u0645\u064e\u0646 \u064a\u064f\u0646\u064e\u062c\u0651\u0650\u064a\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0638\u064f\u0644\u064f\u0645\u064e\u0670\u062a\u0650 \u0671\u0644\u06e1\u0628\u064e\u0631\u0651\u0650 \u0648\u064e\u0671\u0644\u06e1\u0628\u064e\u062d\u06e1\u0631\u0650 \u062a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e\u0647\u064f\u06e5 \u062a\u064e\u0636\u064e\u0631\u0651\u064f\u0639\u0657\u0627 \u0648\u064e\u062e\u064f\u0641\u06e1\u064a\u064e\u0629\u0657 \u0644\u0651\u064e\u0626\u0650\u0646\u06e1 \u0623\u064e\u0646\u062c\u064e\u0649\u0670\u0646\u064e\u0627 \u0645\u0650\u0646\u06e1 \u0647\u064e\u0670\u0630\u0650\u0647\u0650\u06e6 \u0644\u064e\u0646\u064e\u0643\u064f\u0648\u0646\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0634\u0651\u064e\u0640\u0670\u0643\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Katakanlah (Muhammad), \"Siapakah yang dapat menyelamatkan kamu dari bencana di darat dan di laut, ketika kamu berdoa kepada-Nya dengan rendah hati dan dengan suara yang lembut?\" (Dengan mengatakan), \"Sekiranya Dia menyelamatkan kami dari (bencana) ini, tentulah kami menjadi orang-orang yang bersyukur"},{id:64,text:"\u0642\u064f\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064f\u0646\u064e\u062c\u0651\u0650\u064a\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1\u0647\u064e\u0627 \u0648\u064e\u0645\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u0643\u064e\u0631\u06e1\u0628\u0656 \u062b\u064f\u0645\u0651\u064e \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u062a\u064f\u0634\u06e1\u0631\u0650\u0643\u064f\u0648\u0646\u064e",translation:"Katakanlah (Muhammad), \"Allah yang menyelamatkan kamu dari bencana itu dan dari segala macam kesusahan, namun kemudian kamu (kembali) mempersekutukan-Nya"},{id:65,text:"\u0642\u064f\u0644\u06e1 \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0642\u064e\u0627\u062f\u0650\u0631\u064f \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0646 \u064a\u064e\u0628\u06e1\u0639\u064e\u062b\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u0657\u0627 \u0645\u0651\u0650\u0646 \u0641\u064e\u0648\u06e1\u0642\u0650\u0643\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1 \u0645\u0650\u0646 \u062a\u064e\u062d\u06e1\u062a\u0650 \u0623\u064e\u0631\u06e1\u062c\u064f\u0644\u0650\u0643\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1 \u064a\u064e\u0644\u06e1\u0628\u0650\u0633\u064e\u0643\u064f\u0645\u06e1 \u0634\u0650\u064a\u064e\u0639\u0657\u0627 \u0648\u064e\u064a\u064f\u0630\u0650\u064a\u0642\u064e \u0628\u064e\u0639\u06e1\u0636\u064e\u0643\u064f\u0645 \u0628\u064e\u0623\u06e1\u0633\u064e \u0628\u064e\u0639\u06e1\u0636\u064d\u06d7 \u0671\u0646\u0638\u064f\u0631\u06e1 \u0643\u064e\u064a\u06e1\u0641\u064e \u0646\u064f\u0635\u064e\u0631\u0651\u0650\u0641\u064f \u0671\u0644\u06e1\u0623\u0653\u064a\u064e\u0670\u062a\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0641\u06e1\u0642\u064e\u0647\u064f\u0648\u0646\u064e",translation:"Katakanlah (Muhammad), \"Dialah yang berkuasa mengirimkan azab kepadamu, dari atas atau dari bawah kakimu312) atau Dia mencampurkan kamu dalam golongan-golongan (yang saling bertentangan) dan merasakan kepada sebagian kamu keganasan sebagian yang lain.\" Perhatikanlah, bagaimana Kami menjelaskan berulang-ulang tanda-tanda (kekuasaan Kami)313) agar mereka memahami (nya)"},{id:66,text:"\u0648\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0628\u0650\u0647\u0650\u06e6 \u0642\u064e\u0648\u06e1\u0645\u064f\u0643\u064e \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f\u06da \u0642\u064f\u0644 \u0644\u0651\u064e\u0633\u06e1\u062a\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645 \u0628\u0650\u0648\u064e\u0643\u0650\u064a\u0644\u0656",translation:"Dan kaummu mendustakannya (azab)314) padahal (azab) itu benar adanya. Katakanlah (Muhammad), \"Aku ini bukanlah penanggung jawab kamu"},{id:67,text:"\u0644\u0651\u0650\u0643\u064f\u0644\u0651\u0650 \u0646\u064e\u0628\u064e\u0625\u0656 \u0645\u0651\u064f\u0633\u06e1\u062a\u064e\u0642\u064e\u0631\u0651\u065e\u06da \u0648\u064e\u0633\u064e\u0648\u06e1\u0641\u064e \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Setiap berita (yang dibawa oleh Rasul) ada (waktu) terjadinya dan kelak kamu akan mengetahui"},{id:68,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0631\u064e\u0623\u064e\u064a\u06e1\u062a\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062e\u064f\u0648\u0636\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0653 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0641\u064e\u0623\u064e\u0639\u06e1\u0631\u0650\u0636\u06e1 \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u062e\u064f\u0648\u0636\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u062d\u064e\u062f\u0650\u064a\u062b\u064d \u063a\u064e\u064a\u06e1\u0631\u0650\u0647\u0650\u06e6\u06da \u0648\u064e\u0625\u0650\u0645\u0651\u064e\u0627 \u064a\u064f\u0646\u0633\u0650\u064a\u064e\u0646\u0651\u064e\u0643\u064e \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u064f \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u06e1\u0639\u064f\u062f\u06e1 \u0628\u064e\u0639\u06e1\u062f\u064e \u0671\u0644\u0630\u0651\u0650\u0643\u06e1\u0631\u064e\u0649\u0670 \u0645\u064e\u0639\u064e \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Apabila engkau (Muhammad) melihat orang-orang memperolok-olokkan ayat-ayat Kami, maka tinggalkanlah mereka hingga mereka beralih ke pembicaraan lain. Dan jika setan benar-benar menjadikan engkau lupa (akan larangan ini), setelah ingat kembali janganlah engkau duduk bersama orang-orang yang zalim"},{id:69,text:"\u0648\u064e\u0645\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u06e1 \u062d\u0650\u0633\u064e\u0627\u0628\u0650\u0647\u0650\u0645 \u0645\u0651\u0650\u0646 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u0630\u0650\u0643\u06e1\u0631\u064e\u0649\u0670 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",translation:"Orang-orang yang bertakwa tidak bertanggung jawab sedikit pun atas (dosa-dosa) mereka; tetapi (berkewajiban) mengingatkan agar mereka (juga) bertakwa"},{id:70,text:"\u0648\u064e\u0630\u064e\u0631\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627\u0652 \u062f\u0650\u064a\u0646\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0639\u0650\u0628\u0657\u0627 \u0648\u064e\u0644\u064e\u0647\u06e1\u0648\u0657\u0627 \u0648\u064e\u063a\u064e\u0631\u0651\u064e\u062a\u06e1\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u064f \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627\u06da \u0648\u064e\u0630\u064e\u0643\u0651\u0650\u0631\u06e1 \u0628\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0646 \u062a\u064f\u0628\u06e1\u0633\u064e\u0644\u064e \u0646\u064e\u0641\u06e1\u0633\u064f\u06e2 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064e\u062a\u06e1 \u0644\u064e\u064a\u06e1\u0633\u064e \u0644\u064e\u0647\u064e\u0627 \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u0650\u064a\u0651\u065e \u0648\u064e\u0644\u064e\u0627 \u0634\u064e\u0641\u0650\u064a\u0639\u065e \u0648\u064e\u0625\u0650\u0646 \u062a\u064e\u0639\u06e1\u062f\u0650\u0644\u06e1 \u0643\u064f\u0644\u0651\u064e \u0639\u064e\u062f\u06e1\u0644\u0656 \u0644\u0651\u064e\u0627 \u064a\u064f\u0624\u06e1\u062e\u064e\u0630\u06e1 \u0645\u0650\u0646\u06e1\u0647\u064e\u0627\u0653\u06d7 \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0628\u06e1\u0633\u0650\u0644\u064f\u0648\u0627\u0652 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064f\u0648\u0627\u0652\u06d6 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0634\u064e\u0631\u064e\u0627\u0628\u065e \u0645\u0651\u0650\u0646\u06e1 \u062d\u064e\u0645\u0650\u064a\u0645\u0656 \u0648\u064e\u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064f\u06e2 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0643\u06e1\u0641\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Tinggalkanlah orang-orang yang menjadikan agamanya sebagai permainan dan senda gurau, dan mereka telah tertipu oleh kehidupan dunia. Peringatkanlah (mereka) dengan Alquran agar setiap orang tidak terjerumus (ke dalam neraka), karena perbuatannya sendiri. Tidak ada baginya pelindung dan pemberi syafaat (pertolongan) selain Allah. Dan jika dia hendak menebus dengan segala macam tebusan apa pun, niscaya tidak akan diterima. Mereka itulah orang-orang yang dijerumuskan (ke dalam neraka), disebabkan perbuatan mereka sendiri. Mereka mendapat minuman dari air yang mendidih dan azab yang pedih disebabkan kekafiran mereka dahulu"},{id:71,text:"\u0642\u064f\u0644\u06e1 \u0623\u064e\u0646\u064e\u062f\u06e1\u0639\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0646\u0641\u064e\u0639\u064f\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0636\u064f\u0631\u0651\u064f\u0646\u064e\u0627 \u0648\u064e\u0646\u064f\u0631\u064e\u062f\u0651\u064f \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0639\u06e1\u0642\u064e\u0627\u0628\u0650\u0646\u064e\u0627 \u0628\u064e\u0639\u06e1\u062f\u064e \u0625\u0650\u0630\u06e1 \u0647\u064e\u062f\u064e\u0649\u0670\u0646\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0643\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0671\u0633\u06e1\u062a\u064e\u0647\u06e1\u0648\u064e\u062a\u06e1\u0647\u064f \u0671\u0644\u0634\u0651\u064e\u064a\u064e\u0670\u0637\u0650\u064a\u0646\u064f \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u062d\u064e\u064a\u06e1\u0631\u064e\u0627\u0646\u064e \u0644\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u065e \u064a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e\u0647\u064f\u06e5\u0653 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u0647\u064f\u062f\u064e\u0649 \u0671\u0626\u06e1\u062a\u0650\u0646\u064e\u0627\u06d7 \u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u064e \u0647\u064f\u062f\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0647\u064f\u062f\u064e\u0649\u0670\u06d6 \u0648\u064e\u0623\u064f\u0645\u0650\u0631\u06e1\u0646\u064e\u0627 \u0644\u0650\u0646\u064f\u0633\u06e1\u0644\u0650\u0645\u064e \u0644\u0650\u0631\u064e\u0628\u0651\u0650 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Katakanlah (Muhammad), \"Apakah kita akan memohon kepada sesuatu selain Allah, yang tidak dapat memberi manfaat dan tidak (pula) mendatangkan mudarat kepada kita, dan (apakah) kita akan dikembalikan ke belakang,315) setelah Allah memberi petunjuk kepada kita, seperti orang yang telah disesatkan oleh setan di bumi, dalam keadaan kebingungan.\"Kawan-kawannya mengajaknya ke jalan yang lurus (dengan mengatakan), \"Ikutilah kami.\" Katakanlah, \"Sesungguhnya petunjuk Allah itulah petunjuk (yang sebenarnya); dan kita diperintahkan agar berserah diri kepada Tuhan seluruh alam"},{id:72,text:"\u0648\u064e\u0623\u064e\u0646\u06e1 \u0623\u064e\u0642\u0650\u064a\u0645\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0647\u064f\u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u062a\u064f\u062d\u06e1\u0634\u064e\u0631\u064f\u0648\u0646\u064e",translation:"dan agar melaksanakan salat serta bertakwa kepada-Nya.\" Dan Dialah Tuhan yang kepada-Nya kamu semua akan dihimpun"},{id:73,text:"\u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650\u06d6 \u0648\u064e\u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0643\u064f\u0646 \u0641\u064e\u064a\u064e\u0643\u064f\u0648\u0646\u064f\u06da \u0642\u064e\u0648\u06e1\u0644\u064f\u0647\u064f \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f\u06da \u0648\u064e\u0644\u064e\u0647\u064f \u0671\u0644\u06e1\u0645\u064f\u0644\u06e1\u0643\u064f \u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064f\u0646\u0641\u064e\u062e\u064f \u0641\u0650\u064a \u0671\u0644\u0635\u0651\u064f\u0648\u0631\u0650\u06da \u0639\u064e\u0670\u0644\u0650\u0645\u064f \u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u0628\u0650 \u0648\u064e\u0671\u0644\u0634\u0651\u064e\u0647\u064e\u0670\u062f\u064e\u0629\u0650\u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u062d\u064e\u0643\u0650\u064a\u0645\u064f \u0671\u0644\u06e1\u062e\u064e\u0628\u0650\u064a\u0631\u064f",translation:"Dialah yang menciptakan langit dan bumi dengan hak (benar), ketika Dia berkata, \"Jadilah!\" Maka jadilah sesuatu itu. Firman-Nya adalah benar, dan milik-Nyalah segala kekuasaan pada waktu sangkakala ditiup. Dia mengetahui yang gaib dan yang nyata. Dialah Yang Mahabijaksana, Mahateliti"},{id:74,text:"\u06de\u0648\u064e\u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064f \u0644\u0650\u0623\u064e\u0628\u0650\u064a\u0647\u0650 \u0621\u064e\u0627\u0632\u064e\u0631\u064e \u0623\u064e\u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f \u0623\u064e\u0635\u06e1\u0646\u064e\u0627\u0645\u064b\u0627 \u0621\u064e\u0627\u0644\u0650\u0647\u064e\u0629\u064b \u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064e\u0631\u064e\u0649\u0670\u0643\u064e \u0648\u064e\u0642\u064e\u0648\u06e1\u0645\u064e\u0643\u064e \u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0670\u0644\u0656 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u0656",translation:"Dan (ingatlah) ketika Ibrahim berkata kepada ayahnya Azar,316) \"Pantaskah engkau menjadikan berhala-berhala itu sebagai tuhan? Sesungguhnya aku melihat engkau dan kaummu dalam kesesatan yang nyata"},{id:75,text:"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064f\u0631\u0650\u064a\u0653 \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064e \u0645\u064e\u0644\u064e\u0643\u064f\u0648\u062a\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0644\u0650\u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0648\u0642\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dan demikianlah Kami memperlihatkan kepada Ibrahim kekuasaan (Kami yang terdapat) di langit dan di bumi, dan agar dia termasuk orang-orang yang yakin"},{id:76,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0646\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u064f \u0631\u064e\u0621\u064e\u0627 \u0643\u064e\u0648\u06e1\u0643\u064e\u0628\u0657\u0627\u06d6 \u0642\u064e\u0627\u0644\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0631\u064e\u0628\u0651\u0650\u064a\u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u0641\u064e\u0644\u064e \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0627\u0653 \u0623\u064f\u062d\u0650\u0628\u0651\u064f \u0671\u0644\u06e1\u0623\u0653\u0641\u0650\u0644\u0650\u064a\u0646\u064e",translation:"Ketika malam telah menjadi gelap, dia (Ibrahim) melihat sebuah bintang (lalu) dia berkata, \"Inilah Tuhanku.\" Maka ketika bintang itu terbenam dia berkata, \"Aku tidak suka kepada yang terbenam"},{id:77,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0631\u064e\u0621\u064e\u0627 \u0671\u0644\u06e1\u0642\u064e\u0645\u064e\u0631\u064e \u0628\u064e\u0627\u0632\u0650\u063a\u0657\u0627 \u0642\u064e\u0627\u0644\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0631\u064e\u0628\u0651\u0650\u064a\u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u0641\u064e\u0644\u064e \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0626\u0650\u0646 \u0644\u0651\u064e\u0645\u06e1 \u064a\u064e\u0647\u06e1\u062f\u0650\u0646\u0650\u064a \u0631\u064e\u0628\u0651\u0650\u064a \u0644\u064e\u0623\u064e\u0643\u064f\u0648\u0646\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u0636\u0651\u064e\u0627\u0653\u0644\u0651\u0650\u064a\u0646\u064e",translation:"Lalu ketika dia melihat bulan terbit dia berkata, \"Inilah Tuhanku.\" Tetapi ketika bulan itu terbenam dia berkata, \"Sungguh, jika Tuhanku tidak memberi petunjuk kepadaku, pastilah aku termasuk orang-orang yang sesat"},{id:78,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0631\u064e\u0621\u064e\u0627 \u0671\u0644\u0634\u0651\u064e\u0645\u06e1\u0633\u064e \u0628\u064e\u0627\u0632\u0650\u063a\u064e\u0629\u0657 \u0642\u064e\u0627\u0644\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0631\u064e\u0628\u0651\u0650\u064a \u0647\u064e\u0670\u0630\u064e\u0627\u0653 \u0623\u064e\u0643\u06e1\u0628\u064e\u0631\u064f\u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u0641\u064e\u0644\u064e\u062a\u06e1 \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0625\u0650\u0646\u0651\u0650\u064a \u0628\u064e\u0631\u0650\u064a\u0653\u0621\u065e \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u062a\u064f\u0634\u06e1\u0631\u0650\u0643\u064f\u0648\u0646\u064e",translation:"Kemudian ketika dia melihat matahari terbit, dia berkata, \"Inilah Tuhanku, ini lebih besar.\"Tetapi ketika matahari terbenam, dia berkata, \"Wahai kaumku! Sungguh, aku berlepas diri dari apa yang kamu persekutukan"},{id:79,text:"\u0625\u0650\u0646\u0651\u0650\u064a \u0648\u064e\u062c\u0651\u064e\u0647\u06e1\u062a\u064f \u0648\u064e\u062c\u06e1\u0647\u0650\u064a\u064e \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a \u0641\u064e\u0637\u064e\u0631\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u062d\u064e\u0646\u0650\u064a\u0641\u0657\u0627\u06d6 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u064e\u0627\u06e0 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0634\u06e1\u0631\u0650\u0643\u0650\u064a\u0646\u064e",translation:"Aku hadapkan wajahku kepada (Allah) yang menciptakan langit dan bumi dengan penuh kepasrahan (mengikuti) agama yang benar, dan aku bukanlah termasuk orang-orang musyrik"},{id:80,text:"\u0648\u064e\u062d\u064e\u0627\u0653\u062c\u0651\u064e\u0647\u064f\u06e5 \u0642\u064e\u0648\u06e1\u0645\u064f\u0647\u064f\u06e5\u06da \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u062a\u064f\u062d\u064e\u0640\u0670\u0653\u062c\u0651\u064f\u0648\u0653\u0646\u0651\u0650\u064a \u0641\u0650\u064a \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0642\u064e\u062f\u06e1 \u0647\u064e\u062f\u064e\u0649\u0670\u0646\u0650\u06da \u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0645\u064e\u0627 \u062a\u064f\u0634\u06e1\u0631\u0650\u0643\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627\u06da \u0648\u064e\u0633\u0650\u0639\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0643\u064f\u0644\u0651\u064e \u0634\u064e\u064a\u06e1\u0621\u064d \u0639\u0650\u0644\u06e1\u0645\u064b\u0627\u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan kaumnya membantahnya. Dia (Ibrahim) berkata, \"Apakah kamu hendak membantahku tentang Allah, padahal Dia benar-benar telah memberi petunjuk kepadaku? Aku tidak takut kepada (malapetaka dari) apa yang kamu persekutukan dengan Allah, kecuali Tuhanku menghendaki sesuatu. Ilmu Tuhanku meliputi segala sesuatu. Tidakkah kamu dapat mengambil pelajaran"},{id:81,text:"\u0648\u064e\u0643\u064e\u064a\u06e1\u0641\u064e \u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0645\u064e\u0627\u0653 \u0623\u064e\u0634\u06e1\u0631\u064e\u0643\u06e1\u062a\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062e\u064e\u0627\u0641\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u0634\u06e1\u0631\u064e\u0643\u06e1\u062a\u064f\u0645 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0645\u06e1 \u064a\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u06e1 \u0628\u0650\u0647\u0650\u06e6 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0633\u064f\u0644\u06e1\u0637\u064e\u0670\u0646\u0657\u0627\u06da \u0641\u064e\u0623\u064e\u064a\u0651\u064f \u0671\u0644\u06e1\u0641\u064e\u0631\u0650\u064a\u0642\u064e\u064a\u06e1\u0646\u0650 \u0623\u064e\u062d\u064e\u0642\u0651\u064f \u0628\u0650\u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0646\u0650\u06d6 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Bagaimana aku takut kepada apa yang kamu persekutukan (dengan Allah), padahal kamu tidak takut dengan apa yang Allah sendiri tidak menurunkan keterangan kepadamu untuk mempersekutukan-Nya. Manakah dari kedua golongan itu yang lebih berhak mendapat keamanan (dari malapetaka), jika kamu mengetahui"},{id:82,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0644\u06e1\u0628\u0650\u0633\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u064a\u0645\u064e\u0670\u0646\u064e\u0647\u064f\u0645 \u0628\u0650\u0638\u064f\u0644\u06e1\u0645\u064d \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0646\u064f \u0648\u064e\u0647\u064f\u0645 \u0645\u0651\u064f\u0647\u06e1\u062a\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Orang-orang yang beriman dan tidak mencampuradukkan iman mereka dengan syirik, mereka itulah orang-orang yang mendapat rasa aman dan mereka mendapat petunjuk"},{id:83,text:"\u0648\u064e\u062a\u0650\u0644\u06e1\u0643\u064e \u062d\u064f\u062c\u0651\u064e\u062a\u064f\u0646\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064e\u0627\u0653 \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u06e6\u06da \u0646\u064e\u0631\u06e1\u0641\u064e\u0639\u064f \u062f\u064e\u0631\u064e\u062c\u064e\u0670\u062a\u0656 \u0645\u0651\u064e\u0646 \u0646\u0651\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06d7 \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u062d\u064e\u0643\u0650\u064a\u0645\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Dan itulah keterangan Kami yang Kami berikan kepada Ibrahim untuk menghadapi kaumnya. Kami tinggikan derajat siapa yang Kami kehendaki. Sesungguhnya Tuhanmu Mahabijaksana, Maha Mengetahui"},{id:84,text:"\u0648\u064e\u0648\u064e\u0647\u064e\u0628\u06e1\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u06e5\u0653 \u0625\u0650\u0633\u06e1\u062d\u064e\u0670\u0642\u064e \u0648\u064e\u064a\u064e\u0639\u06e1\u0642\u064f\u0648\u0628\u064e\u06da \u0643\u064f\u0644\u0651\u064b\u0627 \u0647\u064e\u062f\u064e\u064a\u06e1\u0646\u064e\u0627\u06da \u0648\u064e\u0646\u064f\u0648\u062d\u064b\u0627 \u0647\u064e\u062f\u064e\u064a\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f\u06d6 \u0648\u064e\u0645\u0650\u0646 \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u062a\u0650\u0647\u0650\u06e6 \u062f\u064e\u0627\u0648\u064f\u06e5\u062f\u064e \u0648\u064e\u0633\u064f\u0644\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u064e \u0648\u064e\u0623\u064e\u064a\u0651\u064f\u0648\u0628\u064e \u0648\u064e\u064a\u064f\u0648\u0633\u064f\u0641\u064e \u0648\u064e\u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u0647\u064e\u0670\u0631\u064f\u0648\u0646\u064e\u06da \u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u062c\u06e1\u0632\u0650\u064a \u0671\u0644\u06e1\u0645\u064f\u062d\u06e1\u0633\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dan Kami telah menganugerahkan Ishak dan Yakub kepadanya. Kepada masing-masing telah Kami beri petunjuk; dan sebelum itu Kami telah memberi petunjuk kepada Nuh dan kepada sebagian dari keturunannya (Ibrahim) yaitu Dawud, Sulaiman, Ayub, Yusuf, Musa, dan Harun. Dan demikianlah kami memberi balasan kepada orang-orang yang berbuat baik"},{id:85,text:"\u0648\u064e\u0632\u064e\u0643\u064e\u0631\u0650\u064a\u0651\u064e\u0627 \u0648\u064e\u064a\u064e\u062d\u06e1\u064a\u064e\u0649\u0670 \u0648\u064e\u0639\u0650\u064a\u0633\u064e\u0649\u0670 \u0648\u064e\u0625\u0650\u0644\u06e1\u064a\u064e\u0627\u0633\u064e\u06d6 \u0643\u064f\u0644\u0651\u065e \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u0650\u064a\u0646\u064e",translation:"dan Zakaria, Yahya, Isa dan Ilyas. Semuanya termasuk orang-orang yang saleh"},{id:86,text:"\u0648\u064e\u0625\u0650\u0633\u06e1\u0645\u064e\u0670\u0639\u0650\u064a\u0644\u064e \u0648\u064e\u0671\u0644\u06e1\u064a\u064e\u0633\u064e\u0639\u064e \u0648\u064e\u064a\u064f\u0648\u0646\u064f\u0633\u064e \u0648\u064e\u0644\u064f\u0648\u0637\u0657\u0627\u06da \u0648\u064e\u0643\u064f\u0644\u0651\u0657\u0627 \u0641\u064e\u0636\u0651\u064e\u0644\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Dan Ismail, Alyasa', Yunus dan Lut. Masing-masing Kami lebihkan (derajatnya) di atas umat lain (pada masanya)"},{id:87,text:"\u0648\u064e\u0645\u0650\u0646\u06e1 \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0626\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u0640\u0670\u062a\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0625\u0650\u062e\u06e1\u0648\u064e\u0670\u0646\u0650\u0647\u0650\u0645\u06e1\u06d6 \u0648\u064e\u0671\u062c\u06e1\u062a\u064e\u0628\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0648\u064e\u0647\u064e\u062f\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0670\u0637\u0656 \u0645\u0651\u064f\u0633\u06e1\u062a\u064e\u0642\u0650\u064a\u0645\u0656",translation:"(dan Kami lebihkan pula derajat) sebagian dari nenek moyang mereka, keturunan mereka dan saudara-saudara mereka. Kami telah memilih mereka (menjadi Nabi dan Rasul) dan mereka Kami beri petunjuk ke jalan yang lurus"},{id:88,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0647\u064f\u062f\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u0647\u06e1\u062f\u0650\u064a \u0628\u0650\u0647\u0650\u06e6 \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0645\u0650\u0646\u06e1 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650\u06e6\u06da \u0648\u064e\u0644\u064e\u0648\u06e1 \u0623\u064e\u0634\u06e1\u0631\u064e\u0643\u064f\u0648\u0627\u0652 \u0644\u064e\u062d\u064e\u0628\u0650\u0637\u064e \u0639\u064e\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Itulah petunjuk Allah, dengan itu Dia memberi petunjuk kepada siapa saja di antara hamba-hamba-Nya yang Dia kehendaki. Sekiranya mereka mempersekutukan Allah, pasti lenyaplah amalan yang telah mereka kerjakan"},{id:89,text:"\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0648\u064e\u0671\u0644\u06e1\u062d\u064f\u0643\u06e1\u0645\u064e \u0648\u064e\u0671\u0644\u0646\u0651\u064f\u0628\u064f\u0648\u0651\u064e\u0629\u064e\u06da \u0641\u064e\u0625\u0650\u0646 \u064a\u064e\u0643\u06e1\u0641\u064f\u0631\u06e1 \u0628\u0650\u0647\u064e\u0627 \u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650 \u0641\u064e\u0642\u064e\u062f\u06e1 \u0648\u064e\u0643\u0651\u064e\u0644\u06e1\u0646\u064e\u0627 \u0628\u0650\u0647\u064e\u0627 \u0642\u064e\u0648\u06e1\u0645\u0657\u0627 \u0644\u0651\u064e\u064a\u06e1\u0633\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u064e\u0627 \u0628\u0650\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Mereka itulah orang-orang yang telah Kami berikan kitab, hikmah dan kenabian. Jika orang-orang (Quraisy) itu mengingkarinya, maka Kami akan menyerahkannya kepada kaum yang tidak mengingkarinya"},{id:90,text:"\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064e\u062f\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06d6 \u0641\u064e\u0628\u0650\u0647\u064f\u062f\u064e\u0649\u0670\u0647\u064f\u0645\u064f \u0671\u0642\u06e1\u062a\u064e\u062f\u0650\u0647\u06e1\u06d7 \u0642\u064f\u0644 \u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0643\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0623\u064e\u062c\u06e1\u0631\u064b\u0627\u06d6 \u0625\u0650\u0646\u06e1 \u0647\u064f\u0648\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0630\u0650\u0643\u06e1\u0631\u064e\u0649\u0670 \u0644\u0650\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Mereka itulah (para nabi) yang telah diberi petunjuk oleh Allah, maka ikutlah petunjuk mereka. Katakanlah (Muhammad), \"Aku tidak meminta imbalan kepadamu dalam menyampaikan (Alquran).\" Alquran itu tidak lain hanyalah peringatan untuk (segala umat) seluruh alam"},{id:91,text:"\u0648\u064e\u0645\u064e\u0627 \u0642\u064e\u062f\u064e\u0631\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u062d\u064e\u0642\u0651\u064e \u0642\u064e\u062f\u06e1\u0631\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0634\u064e\u0631\u0656 \u0645\u0651\u0650\u0646 \u0634\u064e\u064a\u06e1\u0621\u0656\u06d7 \u0642\u064f\u0644\u06e1 \u0645\u064e\u0646\u06e1 \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0627\u0653\u0621\u064e \u0628\u0650\u0647\u0650\u06e6 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0646\u064f\u0648\u0631\u0657\u0627 \u0648\u064e\u0647\u064f\u062f\u0657\u0649 \u0644\u0651\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650\u06d6 \u062a\u064e\u062c\u06e1\u0639\u064e\u0644\u064f\u0648\u0646\u064e\u0647\u064f\u06e5 \u0642\u064e\u0631\u064e\u0627\u0637\u0650\u064a\u0633\u064e \u062a\u064f\u0628\u06e1\u062f\u064f\u0648\u0646\u064e\u0647\u064e\u0627 \u0648\u064e\u062a\u064f\u062e\u06e1\u0641\u064f\u0648\u0646\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u0657\u0627\u06d6 \u0648\u064e\u0639\u064f\u0644\u0651\u0650\u0645\u06e1\u062a\u064f\u0645 \u0645\u0651\u064e\u0627 \u0644\u064e\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627\u0653 \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0624\u064f\u0643\u064f\u0645\u06e1\u06d6 \u0642\u064f\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06d6 \u062b\u064f\u0645\u0651\u064e \u0630\u064e\u0631\u06e1\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u062e\u064e\u0648\u06e1\u0636\u0650\u0647\u0650\u0645\u06e1 \u064a\u064e\u0644\u06e1\u0639\u064e\u0628\u064f\u0648\u0646\u064e",translation:"Mereka tidak mengagungkan Allah sebagaimana mestinya ketika mereka berkata, \"Allah tidak menurunkan sesuatu pun kepada manusia.\" Katakanlah (Muhammad) \"Siapakah yang menurunkan kitab (Taurat) yang dibawa Musa sebagai cahaya dan petunjuk bagi manusia, kamu jadikan Kitab itu lembaran-lembaran kertas yang bercerai-berai, kamu memperlihatkan (sebagiannya) dan banyak yang kamu sembunyikan, padahal telah diajarkan kepadamu apa yang tidak diketahui, baik olehmu maupun oleh nenek moyangmu.\" Katakanlah, \"Allahlah (yang menurunkannya),\" kemudian (setelah itu), biarkanlah mereka bermain-main dalam kesesatannya"},{id:92,text:"\u0648\u064e\u0647\u064e\u0670\u0630\u064e\u0627 \u0643\u0650\u062a\u064e\u0670\u0628\u064c \u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f \u0645\u064f\u0628\u064e\u0627\u0631\u064e\u0643\u065e \u0645\u0651\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0628\u064e\u064a\u06e1\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u06e1\u0647\u0650 \u0648\u064e\u0644\u0650\u062a\u064f\u0646\u0630\u0650\u0631\u064e \u0623\u064f\u0645\u0651\u064e \u0671\u0644\u06e1\u0642\u064f\u0631\u064e\u0649\u0670 \u0648\u064e\u0645\u064e\u0646\u06e1 \u062d\u064e\u0648\u06e1\u0644\u064e\u0647\u064e\u0627\u06da \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0635\u064e\u0644\u064e\u0627\u062a\u0650\u0647\u0650\u0645\u06e1 \u064a\u064f\u062d\u064e\u0627\u0641\u0650\u0638\u064f\u0648\u0646\u064e",translation:"Dan ini (Alquran), Kitab yang telah Kami turunkan dengan penuh berkah; membenarkan kitab-kitab yang (diturunkan) sebelumnya dan agar engkau memberi peringatan kepada (penduduk) Ummul Qura (Mekkah) dan orang-orang yang ada di sekitarnya. Orang-orang yang beriman kepada (kehidupan) akhirat tentu beriman kepadanya (Alquran), dan mereka selalu memelihara salatnya"},{id:93,text:"\u0648\u064e\u0645\u064e\u0646\u06e1 \u0623\u064e\u0638\u06e1\u0644\u064e\u0645\u064f \u0645\u0650\u0645\u0651\u064e\u0646\u0650 \u0671\u0641\u06e1\u062a\u064e\u0631\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u0630\u0650\u0628\u064b\u0627 \u0623\u064e\u0648\u06e1 \u0642\u064e\u0627\u0644\u064e \u0623\u064f\u0648\u062d\u0650\u064a\u064e \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064f\u0648\u062d\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0634\u064e\u064a\u06e1\u0621\u065e \u0648\u064e\u0645\u064e\u0646 \u0642\u064e\u0627\u0644\u064e \u0633\u064e\u0623\u064f\u0646\u0632\u0650\u0644\u064f \u0645\u0650\u062b\u06e1\u0644\u064e \u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06d7 \u0648\u064e\u0644\u064e\u0648\u06e1 \u062a\u064e\u0631\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u0650 \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u063a\u064e\u0645\u064e\u0631\u064e\u0670\u062a\u0650 \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u064f \u0628\u064e\u0627\u0633\u0650\u0637\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u0647\u0650\u0645\u06e1 \u0623\u064e\u062e\u06e1\u0631\u0650\u062c\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0643\u064f\u0645\u064f\u06d6 \u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e \u062a\u064f\u062c\u06e1\u0632\u064e\u0648\u06e1\u0646\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0671\u0644\u06e1\u0647\u064f\u0648\u0646\u0650 \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u063a\u064e\u064a\u06e1\u0631\u064e \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0639\u064e\u0646\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0647\u0650\u06e6 \u062a\u064e\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Siapakah yang lebih zalim daripada orang-orang yang mengada-adakan dusta terhadap Allah atau yang berkata, \"Telah diwahyukan kepadaku,\" padahal tidak diwahyukan sesuatu pun kepadanya, dan orang yang berkata, \"Aku akan menurunkan seperti apa yang diturunkan Allah.\" (Alangkah ngerinya) sekiranya engkau melihat pada waktu orang-orang zalim (berada) dalam sakitnya sekarat, sedang para malaikat memukul dengan tangannya, (sambil berkata), \"Keluarkanlah nyawamu.\" pada hari ini kamu akan dibalas dengan azab yang sangat menghinakan, karena kamu mengatakan terhadap Allah (perkataan) yang tidak benar dan (karena) kamu menyombongkan diri terhadap ayat-ayat-Nya"},{id:94,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u062c\u0650\u0626\u06e1\u062a\u064f\u0645\u064f\u0648\u0646\u064e\u0627 \u0641\u064f\u0631\u064e\u0670\u062f\u064e\u0649\u0670 \u0643\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u06e1\u0646\u064e\u0670\u0643\u064f\u0645\u06e1 \u0623\u064e\u0648\u0651\u064e\u0644\u064e \u0645\u064e\u0631\u0651\u064e\u0629\u0656 \u0648\u064e\u062a\u064e\u0631\u064e\u0643\u06e1\u062a\u064f\u0645 \u0645\u0651\u064e\u0627 \u062e\u064e\u0648\u0651\u064e\u0644\u06e1\u0646\u064e\u0670\u0643\u064f\u0645\u06e1 \u0648\u064e\u0631\u064e\u0627\u0653\u0621\u064e \u0638\u064f\u0647\u064f\u0648\u0631\u0650\u0643\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0645\u064e\u0627 \u0646\u064e\u0631\u064e\u0649\u0670 \u0645\u064e\u0639\u064e\u0643\u064f\u0645\u06e1 \u0634\u064f\u0641\u064e\u0639\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0632\u064e\u0639\u064e\u0645\u06e1\u062a\u064f\u0645\u06e1 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0643\u064f\u0645\u06e1 \u0634\u064f\u0631\u064e\u0643\u064e\u0640\u0670\u0653\u0624\u064f\u0627\u0652\u06da \u0644\u064e\u0642\u064e\u062f \u062a\u0651\u064e\u0642\u064e\u0637\u0651\u064e\u0639\u064e \u0628\u064e\u064a\u06e1\u0646\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0636\u064e\u0644\u0651\u064e \u0639\u064e\u0646\u0643\u064f\u0645 \u0645\u0651\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0632\u06e1\u0639\u064f\u0645\u064f\u0648\u0646\u064e",translation:"Dan kamu benar-benar datang sendiri-sendiri kepada Kami sebagaimana Kami ciptakan kamu pada mulanya, dan apa yang telah Kami karuniakan kepadamu, kamu tinggalkan di belakangmu (di dunia). Kami tidak melihat pemberi syafaat (pertolongan) besertamu yang kamu anggap bahwa mereka itu sekutu-sekutu (bagi Allah). Sungguh, telah terputuslah (semua pertalian) antara kamu dan telah lenyap dari kamu apa yang dahulu kamu sangka (sebagai sekutu Allah)"},{id:95,text:"\u06de\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0641\u064e\u0627\u0644\u0650\u0642\u064f \u0671\u0644\u06e1\u062d\u064e\u0628\u0651\u0650 \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0648\u064e\u0649\u0670\u06d6 \u064a\u064f\u062e\u06e1\u0631\u0650\u062c\u064f \u0671\u0644\u06e1\u062d\u064e\u064a\u0651\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064e\u064a\u0651\u0650\u062a\u0650 \u0648\u064e\u0645\u064f\u062e\u06e1\u0631\u0650\u062c\u064f \u0671\u0644\u06e1\u0645\u064e\u064a\u0651\u0650\u062a\u0650 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u062d\u064e\u064a\u0651\u0650\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06d6 \u0641\u064e\u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u062a\u064f\u0624\u06e1\u0641\u064e\u0643\u064f\u0648\u0646\u064e",translation:"Sungguh, Allah menumbuhkan butir (padi-padian) dan biji (kurma). Dia mengeluarkan yang hidup dari yang mati dan mengeluarkan yang mati dari yang hidup. Itulah (kekuasaan) Allah, maka mengapa kamu masih berpaling"},{id:96,text:"\u0641\u064e\u0627\u0644\u0650\u0642\u064f \u0671\u0644\u06e1\u0625\u0650\u0635\u06e1\u0628\u064e\u0627\u062d\u0650 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u064e \u0633\u064e\u0643\u064e\u0646\u0657\u0627 \u0648\u064e\u0671\u0644\u0634\u0651\u064e\u0645\u06e1\u0633\u064e \u0648\u064e\u0671\u0644\u06e1\u0642\u064e\u0645\u064e\u0631\u064e \u062d\u064f\u0633\u06e1\u0628\u064e\u0627\u0646\u0657\u0627\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062a\u064e\u0642\u06e1\u062f\u0650\u064a\u0631\u064f \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u0650 \u0671\u0644\u06e1\u0639\u064e\u0644\u0650\u064a\u0645\u0650",translation:"Dia menyingsingkan pagi dan menjadikan malam untuk beristirahat, dan (menjadikan) matahari dan bulan untuk perhitungan. Itulah ketetapan Allah Yang Mahaperkasa, Maha Mengetahui"},{id:97,text:"\u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0646\u0651\u064f\u062c\u064f\u0648\u0645\u064e \u0644\u0650\u062a\u064e\u0647\u06e1\u062a\u064e\u062f\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u064e\u0627 \u0641\u0650\u064a \u0638\u064f\u0644\u064f\u0645\u064e\u0670\u062a\u0650 \u0671\u0644\u06e1\u0628\u064e\u0631\u0651\u0650 \u0648\u064e\u0671\u0644\u06e1\u0628\u064e\u062d\u06e1\u0631\u0650\u06d7 \u0642\u064e\u062f\u06e1 \u0641\u064e\u0635\u0651\u064e\u0644\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0623\u0653\u064a\u064e\u0670\u062a\u0650 \u0644\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan Dialah yang menjadikan bintang-bintang bagimu, agar kamu menjadikannya petunjuk dalam kegelapan di darat dan di laut. Kami telah menjelaskan tanda-tanda (kekuasaan Kami) kepada orang-orang yang mengetahui"},{id:98,text:"\u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064e\u0646\u0634\u064e\u0623\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0646\u0651\u064e\u0641\u06e1\u0633\u0656 \u0648\u064e\u0670\u062d\u0650\u062f\u064e\u0629\u0656 \u0641\u064e\u0645\u064f\u0633\u06e1\u062a\u064e\u0642\u064e\u0631\u0651\u065e \u0648\u064e\u0645\u064f\u0633\u06e1\u062a\u064e\u0648\u06e1\u062f\u064e\u0639\u065e\u06d7 \u0642\u064e\u062f\u06e1 \u0641\u064e\u0635\u0651\u064e\u0644\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0623\u0653\u064a\u064e\u0670\u062a\u0650 \u0644\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064e\u0641\u06e1\u0642\u064e\u0647\u064f\u0648\u0646\u064e",translation:"Dan Dialah yang menciptakan kamu dari diri yang satu (Adam), maka (bagimu) ada tempat menetap dan tempat simpanan.319) Sesungguhnya telah Kami jelaskan tanda-tanda (kebesaran Kami) kepada orang-orang yang mengetahui"},{id:99,text:"\u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0645\u064e\u0627\u0653\u0621\u0657 \u0641\u064e\u0623\u064e\u062e\u06e1\u0631\u064e\u062c\u06e1\u0646\u064e\u0627 \u0628\u0650\u0647\u0650\u06e6 \u0646\u064e\u0628\u064e\u0627\u062a\u064e \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0641\u064e\u0623\u064e\u062e\u06e1\u0631\u064e\u062c\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646\u06e1\u0647\u064f \u062e\u064e\u0636\u0650\u0631\u0657\u0627 \u0646\u0651\u064f\u062e\u06e1\u0631\u0650\u062c\u064f \u0645\u0650\u0646\u06e1\u0647\u064f \u062d\u064e\u0628\u0651\u0657\u0627 \u0645\u0651\u064f\u062a\u064e\u0631\u064e\u0627\u0643\u0650\u0628\u0657\u0627 \u0648\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u062e\u06e1\u0644\u0650 \u0645\u0650\u0646 \u0637\u064e\u0644\u06e1\u0639\u0650\u0647\u064e\u0627 \u0642\u0650\u0646\u06e1\u0648\u064e\u0627\u0646\u065e \u062f\u064e\u0627\u0646\u0650\u064a\u064e\u0629\u065e \u0648\u064e\u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0656 \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u0639\u06e1\u0646\u064e\u0627\u0628\u0656 \u0648\u064e\u0671\u0644\u0632\u0651\u064e\u064a\u06e1\u062a\u064f\u0648\u0646\u064e \u0648\u064e\u0671\u0644\u0631\u0651\u064f\u0645\u0651\u064e\u0627\u0646\u064e \u0645\u064f\u0634\u06e1\u062a\u064e\u0628\u0650\u0647\u0657\u0627 \u0648\u064e\u063a\u064e\u064a\u06e1\u0631\u064e \u0645\u064f\u062a\u064e\u0634\u064e\u0670\u0628\u0650\u0647\u064d\u06d7 \u0671\u0646\u0638\u064f\u0631\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u062b\u064e\u0645\u064e\u0631\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0630\u064e\u0627\u0653 \u0623\u064e\u062b\u06e1\u0645\u064e\u0631\u064e \u0648\u064e\u064a\u064e\u0646\u06e1\u0639\u0650\u0647\u0650\u06e6\u0653\u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u06e1 \u0644\u064e\u0623\u0653\u064a\u064e\u0670\u062a\u0656 \u0644\u0651\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Dan Dialah yang menurunkan air dari langit, lalu Kami tumbuhkan dengan air itu segala macam tumbuh-tumbuhan, maka Kami keluarkan dari tumbuh-tumbuhan itu tanaman yang menghijau, Kami keluarkan dari tanaman yang menghijau itu butir yang banyak; dan dari mayang kurma, mengurai tangkai-tangkai yang menjulai, dan kebun-kebun anggur, dan (Kami keluarkan pula) zaitun dan delima yang serupa dan yang tidak serupa. Perhatikanlah buahnya pada waktu berbuah, dan menjadi masak. Sungguh, pada yang demikian itu ada tanda-tanda (kekuasaan Allah) bagi orang-orang yang beriman"},{id:100,text:"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064f\u0648\u0627\u0652 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u06e1\u062c\u0650\u0646\u0651\u064e \u0648\u064e\u062e\u064e\u0644\u064e\u0642\u064e\u0647\u064f\u0645\u06e1\u06d6 \u0648\u064e\u062e\u064e\u0631\u064e\u0642\u064f\u0648\u0627\u0652 \u0644\u064e\u0647\u064f\u06e5 \u0628\u064e\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0628\u064e\u0646\u064e\u0670\u062a\u0650\u06ed \u0628\u0650\u063a\u064e\u064a\u06e1\u0631\u0650 \u0639\u0650\u0644\u06e1\u0645\u0656\u06da \u0633\u064f\u0628\u06e1\u062d\u064e\u0670\u0646\u064e\u0647\u064f\u06e5 \u0648\u064e\u062a\u064e\u0639\u064e\u0670\u0644\u064e\u0649\u0670 \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064e\u0635\u0650\u0641\u064f\u0648\u0646\u064e",translation:"Dan mereka (orang-orang musyrik) menjadikan Jin itu sekutu-sekutu Allah, padahal Dia yang menciptakannya (jin-jin itu), dan mereka berbohong (dengan mengatakan), \"Allah mempunyai anak laki-laki dan anak perempuan,\" tanpa (dasar) pengetahuan.320) Maha Suci Allah dan Mahatinggi dari sifat-sifat yang mereka gambarkan"},{id:101,text:"\u0628\u064e\u062f\u0650\u064a\u0639\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d6 \u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u064a\u064e\u0643\u064f\u0648\u0646\u064f \u0644\u064e\u0647\u064f\u06e5 \u0648\u064e\u0644\u064e\u062f\u065e \u0648\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0643\u064f\u0646 \u0644\u0651\u064e\u0647\u064f\u06e5 \u0635\u064e\u0670\u062d\u0650\u0628\u064e\u0629\u065e\u06d6 \u0648\u064e\u062e\u064e\u0644\u064e\u0642\u064e \u0643\u064f\u0644\u0651\u064e \u0634\u064e\u064a\u06e1\u0621\u0656\u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Dia (Allah) Pencipta langit dan bumi. Bagaimana (mungkin) Dia mempunyai anak padahal Dia tidak mempunyai istri. Dia menciptakan segala sesuatu; dan Dia mengetahui segala sesuatu"},{id:102,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u06e1\u06d6 \u0644\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e\u06d6 \u062e\u064e\u0670\u0644\u0650\u0642\u064f \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0641\u064e\u0671\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0647\u064f\u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0648\u064e\u0643\u0650\u064a\u0644\u065e",translation:"Itulah Allah, Tuhan kamu; tidak ada tuhan selain Dia; Pencipta segala sesuatu, maka sembahlah Dia; Dialah Pemelihara segala sesuatu"},{id:103,text:"\u0644\u0651\u064e\u0627 \u062a\u064f\u062f\u06e1\u0631\u0650\u0643\u064f\u0647\u064f \u0671\u0644\u06e1\u0623\u064e\u0628\u06e1\u0635\u064e\u0670\u0631\u064f \u0648\u064e\u0647\u064f\u0648\u064e \u064a\u064f\u062f\u06e1\u0631\u0650\u0643\u064f \u0671\u0644\u06e1\u0623\u064e\u0628\u06e1\u0635\u064e\u0670\u0631\u064e\u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u0644\u0651\u064e\u0637\u0650\u064a\u0641\u064f \u0671\u0644\u06e1\u062e\u064e\u0628\u0650\u064a\u0631\u064f",translation:"Dia tidak dapat dicapai oleh penglihatan mata, sedang Dia dapat melihat segala penglihatan itu dan Dialah Yang Mahahalus, Mahateliti"},{id:104,text:"\u0642\u064e\u062f\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645 \u0628\u064e\u0635\u064e\u0627\u0653\u0626\u0650\u0631\u064f \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1\u06d6 \u0641\u064e\u0645\u064e\u0646\u06e1 \u0623\u064e\u0628\u06e1\u0635\u064e\u0631\u064e \u0641\u064e\u0644\u0650\u0646\u064e\u0641\u06e1\u0633\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u0645\u064e\u0646\u06e1 \u0639\u064e\u0645\u0650\u064a\u064e \u0641\u064e\u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627\u06da \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u064e\u0627\u06e0 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645 \u0628\u0650\u062d\u064e\u0641\u0650\u064a\u0638\u0656",translation:"Sungguh, bukti-bukti yang nyata telah datang dari Tuhanmu. Barang siapa melihat (kebenaran itu),321) maka (manfaatnya) bagi dirinya sendiri; dan barang siapa buta (tidak melihat kebenaran itu), maka dialah yang rugi. Dan aku (Muhammad) bukanlah penjaga(mu)"},{id:105,text:"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064f\u0635\u064e\u0631\u0651\u0650\u0641\u064f \u0671\u0644\u06e1\u0623\u0653\u064a\u064e\u0670\u062a\u0650 \u0648\u064e\u0644\u0650\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627\u0652 \u062f\u064e\u0631\u064e\u0633\u06e1\u062a\u064e \u0648\u064e\u0644\u0650\u0646\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0647\u064f\u06e5 \u0644\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan demikianlah Kami menjelaskan berulang-ulang ayat-ayat Kami agar orang-orang musyrik mengatakan, \"Engkau telah mempelajari ayat-ayat itu (dari Ahli Kitab).\" dan agar Kami menjelaskan Alquran itu kepada orang-orang yang mengetahui"},{id:106,text:"\u0671\u062a\u0651\u064e\u0628\u0650\u0639\u06e1 \u0645\u064e\u0627\u0653 \u0623\u064f\u0648\u062d\u0650\u064a\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064e\u06d6 \u0644\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e\u06d6 \u0648\u064e\u0623\u064e\u0639\u06e1\u0631\u0650\u0636\u06e1 \u0639\u064e\u0646\u0650 \u0671\u0644\u06e1\u0645\u064f\u0634\u06e1\u0631\u0650\u0643\u0650\u064a\u0646\u064e",translation:"Ikutilah apa yang telah diwahyukan Tuhanmu kepadamu (Muhammad); tidak ada tuhan selain Dia; dan berpalinglah dari orang-orang musyrik"},{id:107,text:"\u0648\u064e\u0644\u064e\u0648\u06e1 \u0634\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0627\u0653 \u0623\u064e\u0634\u06e1\u0631\u064e\u0643\u064f\u0648\u0627\u0652\u06d7 \u0648\u064e\u0645\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0670\u0643\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u062d\u064e\u0641\u0650\u064a\u0638\u0657\u0627\u06d6 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0628\u0650\u0648\u064e\u0643\u0650\u064a\u0644\u0656",translation:"Dan sekiranya Allah menghendaki, niscaya mereka tidak mempersekutukan (-Nya). Dan Kami tidak menjadikan engkau penjaga mereka; dan engkau bukan pula pemelihara mereka"},{id:108,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0633\u064f\u0628\u0651\u064f\u0648\u0627\u0652 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u064a\u064e\u0633\u064f\u0628\u0651\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u062f\u06e1\u0648\u064e\u06e2\u0627 \u0628\u0650\u063a\u064e\u064a\u06e1\u0631\u0650 \u0639\u0650\u0644\u06e1\u0645\u0656\u06d7 \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0632\u064e\u064a\u0651\u064e\u0646\u0651\u064e\u0627 \u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0623\u064f\u0645\u0651\u064e\u0629\u064d \u0639\u064e\u0645\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645 \u0645\u0651\u064e\u0631\u06e1\u062c\u0650\u0639\u064f\u0647\u064f\u0645\u06e1 \u0641\u064e\u064a\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0647\u064f\u0645 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan Janganlah kamu memaki sesembahan yang mereka sembah selain Allah, karena mereka nanti akan memaki Allah dengan melampaui batas tanpa dasar pengetahuan. Demikianlah, Kami jadikan setiap umat menganggap baik pekerjaan mereka. Kemudian kepada Tuhan, tempat kembali mereka, lalu Dia akan memberitahukan kepada mereka apa yang telah mereka kerjakan"},{id:109,text:"\u0648\u064e\u0623\u064e\u0642\u06e1\u0633\u064e\u0645\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062c\u064e\u0647\u06e1\u062f\u064e \u0623\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u0650\u0647\u0650\u0645\u06e1 \u0644\u064e\u0626\u0650\u0646 \u062c\u064e\u0627\u0653\u0621\u064e\u062a\u06e1\u0647\u064f\u0645\u06e1 \u0621\u064e\u0627\u064a\u064e\u0629\u065e \u0644\u0651\u064e\u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0646\u0651\u064e \u0628\u0650\u0647\u064e\u0627\u06da \u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0671\u0644\u06e1\u0623\u0653\u064a\u064e\u0670\u062a\u064f \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0634\u06e1\u0639\u0650\u0631\u064f\u0643\u064f\u0645\u06e1 \u0623\u064e\u0646\u0651\u064e\u0647\u064e\u0627\u0653 \u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u062a\u06e1 \u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Dan Mereka bersumpah atas nama Allah dengan segala kesungguhan, bahwa jika datang suatu mukjizat kepada mereka, pastilah mereka akan beriman kepada-Nya. Katakanlah, \"mukjizat-mukjizat itu hanya ada pada sisi Allah.\" Dan tahukah kamu, bahwa apabila mukjizat (ayat-ayat) datang, mereka tidak juga akan beriman"},{id:110,text:"\u0648\u064e\u0646\u064f\u0642\u064e\u0644\u0651\u0650\u0628\u064f \u0623\u064e\u0641\u06e1\u0640\u0654\u0650\u062f\u064e\u062a\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0628\u06e1\u0635\u064e\u0670\u0631\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0645\u064e\u0627 \u0644\u064e\u0645\u06e1 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0648\u0651\u064e\u0644\u064e \u0645\u064e\u0631\u0651\u064e\u0629\u0656 \u0648\u064e\u0646\u064e\u0630\u064e\u0631\u064f\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0637\u064f\u063a\u06e1\u064a\u064e\u0670\u0646\u0650\u0647\u0650\u0645\u06e1 \u064a\u064e\u0639\u06e1\u0645\u064e\u0647\u064f\u0648\u0646\u064e",translation:"Dan (begitu pula) Kami memalingkan hati dan penglihatan mereka seperti pertama kali mereka tidak beriman kepadanya (Alquran), dan Kami biarkan mereka bingung dalam kesesatan"},{id:111,text:"\u06de\u0648\u064e\u0644\u064e\u0648\u06e1 \u0623\u064e\u0646\u0651\u064e\u0646\u064e\u0627 \u0646\u064e\u0632\u0651\u064e\u0644\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u064f \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u064e \u0648\u064e\u0643\u064e\u0644\u0651\u064e\u0645\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u064e\u0649\u0670 \u0648\u064e\u062d\u064e\u0634\u064e\u0631\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0643\u064f\u0644\u0651\u064e \u0634\u064e\u064a\u06e1\u0621\u0656 \u0642\u064f\u0628\u064f\u0644\u0657\u0627 \u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0644\u0650\u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u062c\u06e1\u0647\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan sekalipun Kami benar-benar menurunkan malaikat kepada mereka, dan orang yang telah mati berbicara dengan mereka dan Kami kumpulkan (pula) di hadapan mereka segala sesuatu (yang mereka inginkan), mereka tidak juga akan beriman, kecuali jika Allah menghendaki. Tapi kebanyakan mereka tidak mengetahui (arti kebenaran)"},{id:112,text:"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0646\u064e\u0628\u0650\u064a\u0651\u064d \u0639\u064e\u062f\u064f\u0648\u0651\u0657\u0627 \u0634\u064e\u064a\u064e\u0670\u0637\u0650\u064a\u0646\u064e \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u0650 \u0648\u064e\u0671\u0644\u06e1\u062c\u0650\u0646\u0651\u0650 \u064a\u064f\u0648\u062d\u0650\u064a \u0628\u064e\u0639\u06e1\u0636\u064f\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u06e1\u0636\u0656 \u0632\u064f\u062e\u06e1\u0631\u064f\u0641\u064e \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0644\u0650 \u063a\u064f\u0631\u064f\u0648\u0631\u0657\u0627\u06da \u0648\u064e\u0644\u064e\u0648\u06e1 \u0634\u064e\u0627\u0653\u0621\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0645\u064e\u0627 \u0641\u064e\u0639\u064e\u0644\u064f\u0648\u0647\u064f\u06d6 \u0641\u064e\u0630\u064e\u0631\u06e1\u0647\u064f\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0641\u06e1\u062a\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan demikianlah untuk setiap Nabi Kami menjadikan musuh, yang terdiri dari setan-setan manusia dan jin, sebagian mereka membisikkan kepada sebagian yang lain perkataan yang indah sebagai tipuan. Dan kalau Tuhanmu menghendaki, niscaya mereka tidak akan melakukannya, maka biarkanlah mereka bersama (kebohongan) yang mereka ada-adakan"},{id:113,text:"\u0648\u064e\u0644\u0650\u062a\u064e\u0635\u06e1\u063a\u064e\u0649\u0670\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0623\u064e\u0641\u06e1\u0640\u0654\u0650\u062f\u064e\u0629\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0648\u064e\u0644\u0650\u064a\u064e\u0631\u06e1\u0636\u064e\u0648\u06e1\u0647\u064f \u0648\u064e\u0644\u0650\u064a\u064e\u0642\u06e1\u062a\u064e\u0631\u0650\u0641\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u0647\u064f\u0645 \u0645\u0651\u064f\u0642\u06e1\u062a\u064e\u0631\u0650\u0641\u064f\u0648\u0646\u064e",translation:"Dan agar hati kecil orang-orang yang tidak beriman kepada akhirat, tertarik kepada bisikan itu, dan menyenanginya, dan agar mereka melakukan apa yang biasa mereka lakukan"},{id:114,text:"\u0623\u064e\u0641\u064e\u063a\u064e\u064a\u06e1\u0631\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0628\u06e1\u062a\u064e\u063a\u0650\u064a \u062d\u064e\u0643\u064e\u0645\u0657\u0627 \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0645\u064f\u0641\u064e\u0635\u0651\u064e\u0644\u0657\u0627\u06da \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u06e5 \u0645\u064f\u0646\u064e\u0632\u0651\u064e\u0644\u065e \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064e \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650\u06d6 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0645\u06e1\u062a\u064e\u0631\u0650\u064a\u0646\u064e",translation:"Pantaskah aku mencari hakim selain Allah, padahal Dialah yang menurunkan Kitab (Alquran) kepadamu secara rinci? Orang-orang yang telah Kami beri Kitab tahu betul bahwa (Alquran) itu diturunkan dari Tuhanmu dengan benar. Maka janganlah kamu termasuk orang-orang yang ragu"},{id:115,text:"\u0648\u064e\u062a\u064e\u0645\u0651\u064e\u062a\u06e1 \u0643\u064e\u0644\u0650\u0645\u064e\u062a\u064f \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0635\u0650\u062f\u06e1\u0642\u0657\u0627 \u0648\u064e\u0639\u064e\u062f\u06e1\u0644\u0657\u0627\u06da \u0644\u0651\u064e\u0627 \u0645\u064f\u0628\u064e\u062f\u0651\u0650\u0644\u064e \u0644\u0650\u0643\u064e\u0644\u0650\u0645\u064e\u0670\u062a\u0650\u0647\u0650\u06e6\u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u0650\u064a\u0639\u064f \u0671\u0644\u06e1\u0639\u064e\u0644\u0650\u064a\u0645\u064f",translation:"Dan telah sempurna firman Tuhanmu (Alquran) dengan benar dan adil. Tidak ada yang dapat mengubah firman-Nya. Dan Dia Maha Mendengar, Maha Mengetahui"},{id:116,text:"\u0648\u064e\u0625\u0650\u0646 \u062a\u064f\u0637\u0650\u0639\u06e1 \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064e \u0645\u064e\u0646 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u064a\u064f\u0636\u0650\u0644\u0651\u064f\u0648\u0643\u064e \u0639\u064e\u0646 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0625\u0650\u0646 \u064a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0638\u0651\u064e\u0646\u0651\u064e \u0648\u064e\u0625\u0650\u0646\u06e1 \u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u064a\u064e\u062e\u06e1\u0631\u064f\u0635\u064f\u0648\u0646\u064e",translation:"Dan jika kamu mengikuti kebanyakan orang di bumi ini, niscaya mereka akan menyesatkanmu dari jalan Allah. Yang mereka ikuti hanya persangkaan belaka dan mereka hanyalah membuat kebohongan"},{id:117,text:"\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0647\u064f\u0648\u064e \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0646 \u064a\u064e\u0636\u0650\u0644\u0651\u064f \u0639\u064e\u0646 \u0633\u064e\u0628\u0650\u064a\u0644\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0628\u0650\u0671\u0644\u06e1\u0645\u064f\u0647\u06e1\u062a\u064e\u062f\u0650\u064a\u0646\u064e",translation:"Sesungguhnya Tuhanmu, Dialah yang lebih mengetahui siapa yang tersesat dari jalan-Nya, dan Dia lebih mengetahui orang-orang yang mendapat petunjuk"},{id:118,text:"\u0641\u064e\u0643\u064f\u0644\u064f\u0648\u0627\u0652 \u0645\u0650\u0645\u0651\u064e\u0627 \u0630\u064f\u0643\u0650\u0631\u064e \u0671\u0633\u06e1\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0647\u0650\u06e6 \u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Maka makanlah dari apa (daging hewan) yang (ketika disembelih) disebut nama Allah, jika kamu beriman kepada ayat-ayat-Nya"},{id:119,text:"\u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f\u0648\u0627\u0652 \u0645\u0650\u0645\u0651\u064e\u0627 \u0630\u064f\u0643\u0650\u0631\u064e \u0671\u0633\u06e1\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0648\u064e\u0642\u064e\u062f\u06e1 \u0641\u064e\u0635\u0651\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u064e\u0627 \u062d\u064e\u0631\u0651\u064e\u0645\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0671\u0636\u06e1\u0637\u064f\u0631\u0650\u0631\u06e1\u062a\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u06d7 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u0657\u0627 \u0644\u0651\u064e\u064a\u064f\u0636\u0650\u0644\u0651\u064f\u0648\u0646\u064e \u0628\u0650\u0623\u064e\u0647\u06e1\u0648\u064e\u0627\u0653\u0626\u0650\u0647\u0650\u0645 \u0628\u0650\u063a\u064e\u064a\u06e1\u0631\u0650 \u0639\u0650\u0644\u06e1\u0645\u064d\u06da \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0647\u064f\u0648\u064e \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0628\u0650\u0671\u0644\u06e1\u0645\u064f\u0639\u06e1\u062a\u064e\u062f\u0650\u064a\u0646\u064e",translation:"Dan mengapa kamu tidak mau memakan dari apa (daging hewan) yang (ketika disembelih) disebut nama Allah, padahal Allah telah menjelaskan kepadamu apa yang diharamkan-Nya kepadamu, kecuali jika kamu dalam keadaan terpaksa. Dan sungguh, banyak yang menyesatkan orang dengan keinginannya tanpa dasar pengetahuan. Tuhanmu lebih mengetahui orang-orang yang melampaui batas"},{id:120,text:"\u0648\u064e\u0630\u064e\u0631\u064f\u0648\u0627\u0652 \u0638\u064e\u0670\u0647\u0650\u0631\u064e \u0671\u0644\u06e1\u0625\u0650\u062b\u06e1\u0645\u0650 \u0648\u064e\u0628\u064e\u0627\u0637\u0650\u0646\u064e\u0647\u064f\u06e5\u0653\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0643\u06e1\u0633\u0650\u0628\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0625\u0650\u062b\u06e1\u0645\u064e \u0633\u064e\u064a\u064f\u062c\u06e1\u0632\u064e\u0648\u06e1\u0646\u064e \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0642\u06e1\u062a\u064e\u0631\u0650\u0641\u064f\u0648\u0646\u064e",translation:"Dan tinggalkanlah dosa yang terlihat ataupun yang tersembunyi. Sungguh, orang-orang yang mengerjakan (perbuatan) dosa kelak akan diberi balasan sesuai dengan apa yang mereka kerjakan"},{id:121,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f\u0648\u0627\u0652 \u0645\u0650\u0645\u0651\u064e\u0627 \u0644\u064e\u0645\u06e1 \u064a\u064f\u0630\u06e1\u0643\u064e\u0631\u0650 \u0671\u0633\u06e1\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0641\u0650\u0633\u06e1\u0642\u065e\u06d7 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0634\u0651\u064e\u064a\u064e\u0670\u0637\u0650\u064a\u0646\u064e \u0644\u064e\u064a\u064f\u0648\u062d\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0648\u06e1\u0644\u0650\u064a\u064e\u0627\u0653\u0626\u0650\u0647\u0650\u0645\u06e1 \u0644\u0650\u064a\u064f\u062c\u064e\u0670\u062f\u0650\u0644\u064f\u0648\u0643\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0625\u0650\u0646\u06e1 \u0623\u064e\u0637\u064e\u0639\u06e1\u062a\u064f\u0645\u064f\u0648\u0647\u064f\u0645\u06e1 \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0644\u064e\u0645\u064f\u0634\u06e1\u0631\u0650\u0643\u064f\u0648\u0646\u064e",translation:"Dan janganlah kamu memakan dari apa (daging hewan) yang (ketika disembelih) tidak disebut nama Allah, perbuatan itu benar-benar suatu kefasikan. Sesungguhnya setan-setan akan membisikkan kepada kawan-kawannya agar mereka membantah kamu. Dan jika kamu menuruti mereka, tentu kamu telah menjadi orang musyrik"},{id:122,text:"\u0623\u064e\u0648\u064e\u0645\u064e\u0646 \u0643\u064e\u0627\u0646\u064e \u0645\u064e\u064a\u06e1\u062a\u0657\u0627 \u0641\u064e\u0623\u064e\u062d\u06e1\u064a\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u06e5 \u0646\u064f\u0648\u0631\u0657\u0627 \u064a\u064e\u0645\u06e1\u0634\u0650\u064a \u0628\u0650\u0647\u0650\u06e6 \u0641\u0650\u064a \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0643\u064e\u0645\u064e\u0646 \u0645\u0651\u064e\u062b\u064e\u0644\u064f\u0647\u064f\u06e5 \u0641\u0650\u064a \u0671\u0644\u0638\u0651\u064f\u0644\u064f\u0645\u064e\u0670\u062a\u0650 \u0644\u064e\u064a\u06e1\u0633\u064e \u0628\u0650\u062e\u064e\u0627\u0631\u0650\u062c\u0656 \u0645\u0651\u0650\u0646\u06e1\u0647\u064e\u0627\u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0632\u064f\u064a\u0651\u0650\u0646\u064e \u0644\u0650\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan apakah orang yang sudah mati lalu Kami hidupkan dan Kami beri dia cahaya yang membuatnya dapat berjalan di tengah-tengah orang banyak, sama dengan orang yang berada dalam kegelapan, sehingga dia tidak dapat ke luar dari sana? Demikianlah dijadikan terasa indah bagi orang-orang kafir apa yang mereka kerjakan"},{id:123,text:"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a \u0643\u064f\u0644\u0651\u0650 \u0642\u064e\u0631\u06e1\u064a\u064e\u0629\u064d \u0623\u064e\u0643\u064e\u0670\u0628\u0650\u0631\u064e \u0645\u064f\u062c\u06e1\u0631\u0650\u0645\u0650\u064a\u0647\u064e\u0627 \u0644\u0650\u064a\u064e\u0645\u06e1\u0643\u064f\u0631\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0647\u064e\u0627\u06d6 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0645\u06e1\u0643\u064f\u0631\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0634\u06e1\u0639\u064f\u0631\u064f\u0648\u0646\u064e",translation:"(Dan demikianlah pada setiap negeri Kami jadikan pembesar-pembesar yang jahat323) agar melakukan tipu daya di negeri itu. Tapi mereka hanya menipu diri sendiri tanpa menyadarinya"},{id:124,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u062a\u06e1\u0647\u064f\u0645\u06e1 \u0621\u064e\u0627\u064a\u064e\u0629\u065e \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0646 \u0646\u0651\u064f\u0624\u06e1\u0645\u0650\u0646\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0646\u064f\u0624\u06e1\u062a\u064e\u0649\u0670 \u0645\u0650\u062b\u06e1\u0644\u064e \u0645\u064e\u0627\u0653 \u0623\u064f\u0648\u062a\u0650\u064a\u064e \u0631\u064f\u0633\u064f\u0644\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d8 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u062d\u064e\u064a\u06e1\u062b\u064f \u064a\u064e\u062c\u06e1\u0639\u064e\u0644\u064f \u0631\u0650\u0633\u064e\u0627\u0644\u064e\u062a\u064e\u0647\u064f\u06e5\u06d7 \u0633\u064e\u064a\u064f\u0635\u0650\u064a\u0628\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u062c\u06e1\u0631\u064e\u0645\u064f\u0648\u0627\u0652 \u0635\u064e\u063a\u064e\u0627\u0631\u064c \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0639\u064e\u0630\u064e\u0627\u0628\u065e \u0634\u064e\u062f\u0650\u064a\u062f\u064f\u06e2 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0645\u06e1\u0643\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Dan apabila datang suatu ayat kepada mereka, tentu mereka berkata, \"Kami tidak akan percaya (beriman) sebelum diberikan kepada kami seperti yang diberikan kepada Rasul-rasul Allah.\" Allah lebih mengetahui di mana Dia menempatkan tugas kerasulan-Nya. Orang-orang yang berdosa, nanti akan ditimpa kehinaan di sisi Allah dan azab yang keras karena tipu daya yang mereka lakukan"},{id:125,text:"\u0641\u064e\u0645\u064e\u0646 \u064a\u064f\u0631\u0650\u062f\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0646 \u064a\u064e\u0647\u06e1\u062f\u0650\u064a\u064e\u0647\u064f\u06e5 \u064a\u064e\u0634\u06e1\u0631\u064e\u062d\u06e1 \u0635\u064e\u062f\u06e1\u0631\u064e\u0647\u064f\u06e5 \u0644\u0650\u0644\u06e1\u0625\u0650\u0633\u06e1\u0644\u064e\u0670\u0645\u0650\u06d6 \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0631\u0650\u062f\u06e1 \u0623\u064e\u0646 \u064a\u064f\u0636\u0650\u0644\u0651\u064e\u0647\u064f\u06e5 \u064a\u064e\u062c\u06e1\u0639\u064e\u0644\u06e1 \u0635\u064e\u062f\u06e1\u0631\u064e\u0647\u064f\u06e5 \u0636\u064e\u064a\u0651\u0650\u0642\u064b\u0627 \u062d\u064e\u0631\u064e\u062c\u0657\u0627 \u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0635\u0651\u064e\u0639\u0651\u064e\u062f\u064f \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650\u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064e\u062c\u06e1\u0639\u064e\u0644\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0631\u0651\u0650\u062c\u06e1\u0633\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Barang siapa yang dikehendaki Allah akan mendapat hidayah (petunjuk), Dia akan membukakan dadanya untuk (menerima) Islam. Dan barang siapa dikehendaki-Nya menjadi sesat, Dia jadikan dadanya sempit dan sesak, seakan-akan dia (sedang) mendaki ke langit. Demikianlah Allah menimpakan siksa kepada orang-orang yang tidak beriman"},{id:126,text:"\u0648\u064e\u0647\u064e\u0670\u0630\u064e\u0627 \u0635\u0650\u0631\u064e\u0670\u0637\u064f \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0645\u064f\u0633\u06e1\u062a\u064e\u0642\u0650\u064a\u0645\u0657\u0627\u06d7 \u0642\u064e\u062f\u06e1 \u0641\u064e\u0635\u0651\u064e\u0644\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0623\u0653\u064a\u064e\u0670\u062a\u0650 \u0644\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064e\u0630\u0651\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan inilah jalan Tuhanmu yang lurus. Kami telah menjelaskan ayat-ayat (Kami) kepada orang-orang yang menerima peringatan"},{id:127,text:"\u06de\u0644\u064e\u0647\u064f\u0645\u06e1 \u062f\u064e\u0627\u0631\u064f \u0671\u0644\u0633\u0651\u064e\u0644\u064e\u0670\u0645\u0650 \u0639\u0650\u0646\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1\u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0648\u064e\u0644\u0650\u064a\u0651\u064f\u0647\u064f\u0645 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Bagi mereka (disediakan) tempat yang damai (surga) di sisi Tuhannya. Dan Dialah pelindung mereka karena amal kebajikan yang mereka kerjakan"},{id:128,text:"\u0648\u064e\u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064e\u062d\u06e1\u0634\u064f\u0631\u064f\u0647\u064f\u0645\u06e1 \u062c\u064e\u0645\u0650\u064a\u0639\u0657\u0627 \u064a\u064e\u0670\u0645\u064e\u0639\u06e1\u0634\u064e\u0631\u064e \u0671\u0644\u06e1\u062c\u0650\u0646\u0651\u0650 \u0642\u064e\u062f\u0650 \u0671\u0633\u06e1\u062a\u064e\u0643\u06e1\u062b\u064e\u0631\u06e1\u062a\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u0650\u06d6 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0648\u06e1\u0644\u0650\u064a\u064e\u0627\u0653\u0624\u064f\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u0650 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0671\u0633\u06e1\u062a\u064e\u0645\u06e1\u062a\u064e\u0639\u064e \u0628\u064e\u0639\u06e1\u0636\u064f\u0646\u064e\u0627 \u0628\u0650\u0628\u064e\u0639\u06e1\u0636\u0656 \u0648\u064e\u0628\u064e\u0644\u064e\u063a\u06e1\u0646\u064e\u0627\u0653 \u0623\u064e\u062c\u064e\u0644\u064e\u0646\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064e\u062c\u0651\u064e\u0644\u06e1\u062a\u064e \u0644\u064e\u0646\u064e\u0627\u06da \u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u064f \u0645\u064e\u062b\u06e1\u0648\u064e\u0649\u0670\u0643\u064f\u0645\u06e1 \u062e\u064e\u0670\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0634\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06da \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u062d\u064e\u0643\u0650\u064a\u0645\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Dan (ingatlah) pada hari ketika Dia mengumpulkan mereka semua (dan Allah berfirman), \"Wahai golongan jin! Kamu telah banyak (menyesatkan) manusia.\" Dan kawan-kawan mereka dari golongan manusia berkata, \"Ya Tuhan, kami telah saling mendapatkan kesenangan324) dan sekarang waktu yang telah Engkau tentukan buat kami telah datang.\" Allah berfirman, \"Nerakalah tempat kamu selama-lamanya, kecuali jika Allah menghendaki lain.\" Sungguh, Tuhanmu Mahabijaksana, Maha Mengetahui"},{id:129,text:"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064f\u0648\u064e\u0644\u0651\u0650\u064a \u0628\u064e\u0639\u06e1\u0636\u064e \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0628\u064e\u0639\u06e1\u0636\u064e\u06e2\u0627 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0643\u06e1\u0633\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Dan demikianlah Kami jadikan sebagian orang-orang zalim berteman dengan sesamanya, sesuai dengan apa yang mereka kerjakan"},{id:130,text:"\u064a\u064e\u0670\u0645\u064e\u0639\u06e1\u0634\u064e\u0631\u064e \u0671\u0644\u06e1\u062c\u0650\u0646\u0651\u0650 \u0648\u064e\u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u0650 \u0623\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0623\u06e1\u062a\u0650\u0643\u064f\u0645\u06e1 \u0631\u064f\u0633\u064f\u0644\u065e \u0645\u0651\u0650\u0646\u0643\u064f\u0645\u06e1 \u064a\u064e\u0642\u064f\u0635\u0651\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u064a \u0648\u064e\u064a\u064f\u0646\u0630\u0650\u0631\u064f\u0648\u0646\u064e\u0643\u064f\u0645\u06e1 \u0644\u0650\u0642\u064e\u0627\u0653\u0621\u064e \u064a\u064e\u0648\u06e1\u0645\u0650\u0643\u064f\u0645\u06e1 \u0647\u064e\u0670\u0630\u064e\u0627\u06da \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0634\u064e\u0647\u0650\u062f\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0646\u064e\u0627\u06d6 \u0648\u064e\u063a\u064e\u0631\u0651\u064e\u062a\u06e1\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u064f \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0648\u064e\u0634\u064e\u0647\u0650\u062f\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u06e1 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Wahai golongan jin dan manusia! Bukankah sudah datang kepadamu Rasul-rasul dari kalanganmu sendiri, mereka menyampaikan ayat-ayat-Ku kepadamu dan memperingat\xadkanmu tentang pertemuan pada hari ini? Mereka menjawab, \"(Ya), kami menjadi saksi atas diri kami sendiri.\" Tetapi mereka tertipu oleh kehidupan dunia dan mereka telah menjadi saksi atas diri mereka sendiri, bahwa mereka adalah orang-orang kafir"},{id:131,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0623\u064e\u0646 \u0644\u0651\u064e\u0645\u06e1 \u064a\u064e\u0643\u064f\u0646 \u0631\u0651\u064e\u0628\u0651\u064f\u0643\u064e \u0645\u064f\u0647\u06e1\u0644\u0650\u0643\u064e \u0671\u0644\u06e1\u0642\u064f\u0631\u064e\u0649\u0670 \u0628\u0650\u0638\u064f\u0644\u06e1\u0645\u0656 \u0648\u064e\u0623\u064e\u0647\u06e1\u0644\u064f\u0647\u064e\u0627 \u063a\u064e\u0670\u0641\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Demikianlah (para rasul diutus) karena Tuhanmu tidak akan membinasakan suatu negeri secara zalim, sedang penduduknya dalam lengah (belum tahu)"},{id:132,text:"\u0648\u064e\u0644\u0650\u0643\u064f\u0644\u0651\u0656 \u062f\u064e\u0631\u064e\u062c\u064e\u0670\u062a\u065e \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652\u06da \u0648\u064e\u0645\u064e\u0627 \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0628\u0650\u063a\u064e\u0670\u0641\u0650\u0644\u064d \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan masing-masing orang ada tingkatannya, (sesuai) dengan apa yang mereka kerjakan. Dan Tuhanmu tidak lengah terhadap apa yang mereka kerjakan"},{id:133,text:"\u0648\u064e\u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0671\u0644\u06e1\u063a\u064e\u0646\u0650\u064a\u0651\u064f \u0630\u064f\u0648 \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0629\u0650\u06da \u0625\u0650\u0646 \u064a\u064e\u0634\u064e\u0623\u06e1 \u064a\u064f\u0630\u06e1\u0647\u0650\u0628\u06e1\u0643\u064f\u0645\u06e1 \u0648\u064e\u064a\u064e\u0633\u06e1\u062a\u064e\u062e\u06e1\u0644\u0650\u0641\u06e1 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u0643\u064f\u0645 \u0645\u0651\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0643\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0634\u064e\u0623\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u0629\u0650 \u0642\u064e\u0648\u06e1\u0645\u064d \u0621\u064e\u0627\u062e\u064e\u0631\u0650\u064a\u0646\u064e",translation:"Dan Tuhanmu Mahakaya, penuh rahmat. Jika Dia menghendaki, Dia akan memusnahkan kamu dan setelah kamu (musnah) akan Dia ganti dengan yang Dia kehendaki, sebagaimana Dia menjadikan kamu dari keturunan golongan lain"},{id:134,text:"\u0625\u0650\u0646\u0651\u064e \u0645\u064e\u0627 \u062a\u064f\u0648\u0639\u064e\u062f\u064f\u0648\u0646\u064e \u0644\u064e\u0623\u0653\u062a\u0656\u06d6 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064f\u0645 \u0628\u0650\u0645\u064f\u0639\u06e1\u062c\u0650\u0632\u0650\u064a\u0646\u064e",translation:"Sesungguhnya apa pun yang dijanjikan kepadamu pasti datang dan kamu tidak mampu menolaknya"},{id:135,text:"\u0642\u064f\u0644\u06e1 \u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0643\u064e\u0627\u0646\u064e\u062a\u0650\u0643\u064f\u0645\u06e1 \u0625\u0650\u0646\u0651\u0650\u064a \u0639\u064e\u0627\u0645\u0650\u0644\u065e\u06d6 \u0641\u064e\u0633\u064e\u0648\u06e1\u0641\u064e \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0645\u064e\u0646 \u062a\u064e\u0643\u064f\u0648\u0646\u064f \u0644\u064e\u0647\u064f\u06e5 \u0639\u064e\u0670\u0642\u0650\u0628\u064e\u0629\u064f \u0671\u0644\u062f\u0651\u064e\u0627\u0631\u0650\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0627 \u064a\u064f\u0641\u06e1\u0644\u0650\u062d\u064f \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Katakanlah (Muhammad), \"Wahai kaumku! Berbuatlah menurut kedudukanmu, akupun berbuat (demikian). Kelak kamu akan mengetahui, siapa yang akan memperoleh tempat (terbaik) di akhirat (nanti). Sesungguhnya orang-orang yang zalim itu tidak akan beruntung"},{id:136,text:"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064f\u0648\u0627\u0652 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0645\u0651\u064e\u0627 \u0630\u064e\u0631\u064e\u0623\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u062d\u064e\u0631\u06e1\u062b\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0639\u064e\u0670\u0645\u0650 \u0646\u064e\u0635\u0650\u064a\u0628\u0657\u0627 \u0641\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0647\u064e\u0670\u0630\u064e\u0627 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0628\u0650\u0632\u064e\u0639\u06e1\u0645\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0647\u064e\u0670\u0630\u064e\u0627 \u0644\u0650\u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0653\u0626\u0650\u0646\u064e\u0627\u06d6 \u0641\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0653\u0626\u0650\u0647\u0650\u0645\u06e1 \u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0635\u0650\u0644\u064f \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0647\u064f\u0648\u064e \u064a\u064e\u0635\u0650\u0644\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0653\u0626\u0650\u0647\u0650\u0645\u06e1\u06d7 \u0633\u064e\u0627\u0653\u0621\u064e \u0645\u064e\u0627 \u064a\u064e\u062d\u06e1\u0643\u064f\u0645\u064f\u0648\u0646\u064e",translation:"Dan mereka menyediakan sebagian hasil tanaman dan hewan (bagian) untuk Allah sambil berkata menurut persangkaan mereka, \"Ini untuk Allah dan yang ini untuk berhala-berhala kami.\" Bagian yang untuk berhala-berhala mereka tidak akan sampai kepada Allah, dan bagian yang untuk Allah akan sampai kepada berhala-berhala mereka.325) Sangat buruk ketetapan mereka itu"},{id:137,text:"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0632\u064e\u064a\u0651\u064e\u0646\u064e \u0644\u0650\u0643\u064e\u062b\u0650\u064a\u0631\u0656 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0634\u06e1\u0631\u0650\u0643\u0650\u064a\u0646\u064e \u0642\u064e\u062a\u06e1\u0644\u064e \u0623\u064e\u0648\u06e1\u0644\u064e\u0670\u062f\u0650\u0647\u0650\u0645\u06e1 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0653\u0624\u064f\u0647\u064f\u0645\u06e1 \u0644\u0650\u064a\u064f\u0631\u06e1\u062f\u064f\u0648\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u0650\u064a\u064e\u0644\u06e1\u0628\u0650\u0633\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u062f\u0650\u064a\u0646\u064e\u0647\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0644\u064e\u0648\u06e1 \u0634\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0627 \u0641\u064e\u0639\u064e\u0644\u064f\u0648\u0647\u064f\u06d6 \u0641\u064e\u0630\u064e\u0631\u06e1\u0647\u064f\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0641\u06e1\u062a\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan demikianlah berhala-berhala mereka (setan) menjadikan tampak indah bagi banyak orang-orang musyrik membunuh anak-anak mereka, untuk membinasakan mereka dan mengacaukan agama mereka sendiri.326) Dan kalau Allah menghendaki, niscaya mereka tidak akan mengerjakannya. Biarkanlah mereka bersama apa (kebohongan) yang mereka ada-adakan"},{id:138,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0647\u064e\u0670\u0630\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0646\u06e1\u0639\u064e\u0670\u0645\u065e \u0648\u064e\u062d\u064e\u0631\u06e1\u062b\u064c \u062d\u0650\u062c\u06e1\u0631\u065e \u0644\u0651\u064e\u0627 \u064a\u064e\u0637\u06e1\u0639\u064e\u0645\u064f\u0647\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646 \u0646\u0651\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0628\u0650\u0632\u064e\u0639\u06e1\u0645\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0623\u064e\u0646\u06e1\u0639\u064e\u0670\u0645\u064c \u062d\u064f\u0631\u0651\u0650\u0645\u064e\u062a\u06e1 \u0638\u064f\u0647\u064f\u0648\u0631\u064f\u0647\u064e\u0627 \u0648\u064e\u0623\u064e\u0646\u06e1\u0639\u064e\u0670\u0645\u065e \u0644\u0651\u064e\u0627 \u064a\u064e\u0630\u06e1\u0643\u064f\u0631\u064f\u0648\u0646\u064e \u0671\u0633\u06e1\u0645\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627 \u0671\u0641\u06e1\u062a\u0650\u0631\u064e\u0627\u0653\u0621\u064b \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u06da \u0633\u064e\u064a\u064e\u062c\u06e1\u0632\u0650\u064a\u0647\u0650\u0645 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0641\u06e1\u062a\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan mereka berkata (menurut anggapan mereka), \"Inilah hewan ternak dan hasil bumi yang dilarang, tidak boleh dimakan, kecuali oleh orang yang kami kehendaki.\" Dan ada pula hewan yang diharamkan (tidak boleh) ditunggangi, dan ada hewan ternak yang (ketika disembelih) boleh tidak menyebut nama Allah, itu sebagai kebohongan terhadap Allah. Kelak Allah akan membalas semua yang mereka ada-adakan"},{id:139,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u0641\u0650\u064a \u0628\u064f\u0637\u064f\u0648\u0646\u0650 \u0647\u064e\u0670\u0630\u0650\u0647\u0650 \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0639\u064e\u0670\u0645\u0650 \u062e\u064e\u0627\u0644\u0650\u0635\u064e\u0629\u065e \u0644\u0651\u0650\u0630\u064f\u0643\u064f\u0648\u0631\u0650\u0646\u064e\u0627 \u0648\u064e\u0645\u064f\u062d\u064e\u0631\u0651\u064e\u0645\u064c \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u0650\u0646\u064e\u0627\u06d6 \u0648\u064e\u0625\u0650\u0646 \u064a\u064e\u0643\u064f\u0646 \u0645\u0651\u064e\u064a\u06e1\u062a\u064e\u0629\u0657 \u0641\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u0650 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0653\u0621\u064f\u06da \u0633\u064e\u064a\u064e\u062c\u06e1\u0632\u0650\u064a\u0647\u0650\u0645\u06e1 \u0648\u064e\u0635\u06e1\u0641\u064e\u0647\u064f\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u062d\u064e\u0643\u0650\u064a\u0645\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Dan mereka berkata (pula), \"Apa yang ada di dalam perut hewan ternak ini khusus untuk kaum laki-laki kami, haram bagi istri-istri kami.\" Dan Jika yang dalam perut itu (dilahirkan) mati, maka semua boleh (memakannya). Kelak Allah akan membalas atas ketetapan mereka. Sesungguhnya Allah Mahabijaksana, Maha Mengetahui"},{id:140,text:"\u0642\u064e\u062f\u06e1 \u062e\u064e\u0633\u0650\u0631\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0642\u064e\u062a\u064e\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0648\u06e1\u0644\u064e\u0670\u062f\u064e\u0647\u064f\u0645\u06e1 \u0633\u064e\u0641\u064e\u0647\u064e\u06e2\u0627 \u0628\u0650\u063a\u064e\u064a\u06e1\u0631\u0650 \u0639\u0650\u0644\u06e1\u0645\u0656 \u0648\u064e\u062d\u064e\u0631\u0651\u064e\u0645\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0641\u06e1\u062a\u0650\u0631\u064e\u0627\u0653\u0621\u064b \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0642\u064e\u062f\u06e1 \u0636\u064e\u0644\u0651\u064f\u0648\u0627\u0652 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0645\u064f\u0647\u06e1\u062a\u064e\u062f\u0650\u064a\u0646\u064e",translation:"Sungguh rugi mereka yang membunuh anak-anaknya karena kebodohan tanpa pengetahuan, dan mengharamkan rezeki yang dikaruniakan Allah kepada mereka dengan semata-mata membuat-buat kebohongan terhadap Allah. Sungguh, mereka telah sesat dan tidak mendapat petunjuk"},{id:141,text:"\u06de\u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064e\u0646\u0634\u064e\u0623\u064e \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0656 \u0645\u0651\u064e\u0639\u06e1\u0631\u064f\u0648\u0634\u064e\u0670\u062a\u0656 \u0648\u064e\u063a\u064e\u064a\u06e1\u0631\u064e \u0645\u064e\u0639\u06e1\u0631\u064f\u0648\u0634\u064e\u0670\u062a\u0656 \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u062e\u06e1\u0644\u064e \u0648\u064e\u0671\u0644\u0632\u0651\u064e\u0631\u06e1\u0639\u064e \u0645\u064f\u062e\u06e1\u062a\u064e\u0644\u0650\u0641\u064b\u0627 \u0623\u064f\u0643\u064f\u0644\u064f\u0647\u064f\u06e5 \u0648\u064e\u0671\u0644\u0632\u0651\u064e\u064a\u06e1\u062a\u064f\u0648\u0646\u064e \u0648\u064e\u0671\u0644\u0631\u0651\u064f\u0645\u0651\u064e\u0627\u0646\u064e \u0645\u064f\u062a\u064e\u0634\u064e\u0670\u0628\u0650\u0647\u0657\u0627 \u0648\u064e\u063a\u064e\u064a\u06e1\u0631\u064e \u0645\u064f\u062a\u064e\u0634\u064e\u0670\u0628\u0650\u0647\u0656\u06da \u0643\u064f\u0644\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u062b\u064e\u0645\u064e\u0631\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0630\u064e\u0627\u0653 \u0623\u064e\u062b\u06e1\u0645\u064e\u0631\u064e \u0648\u064e\u0621\u064e\u0627\u062a\u064f\u0648\u0627\u0652 \u062d\u064e\u0642\u0651\u064e\u0647\u064f\u06e5 \u064a\u064e\u0648\u06e1\u0645\u064e \u062d\u064e\u0635\u064e\u0627\u062f\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0633\u06e1\u0631\u0650\u0641\u064f\u0648\u0653\u0627\u0652\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0671\u0644\u06e1\u0645\u064f\u0633\u06e1\u0631\u0650\u0641\u0650\u064a\u0646\u064e",translation:"Dan Dialah yang menjadikan tanaman-tanaman yang merambat dan yang tidak merambat, pohon kurma, tanaman yang beraneka ragam rasanya, zaitun dan delima yang serupa (bentuk dan warnanya) dan tidak serupa (rasanya). Makanlah buahnya apabila ia berbuah dan berikanlah haknya (zakatnya) pada waktu memetik hasilnya, tapi janganlah berlebih-lebihan. Sesungguhnya Allah tidak menyukai orang-orang yang berlebih-lebihan"},{id:142,text:"\u0648\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0639\u064e\u0670\u0645\u0650 \u062d\u064e\u0645\u064f\u0648\u0644\u064e\u0629\u0657 \u0648\u064e\u0641\u064e\u0631\u06e1\u0634\u0657\u0627\u06da \u0643\u064f\u0644\u064f\u0648\u0627\u0652 \u0645\u0650\u0645\u0651\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0627\u0652 \u062e\u064f\u0637\u064f\u0648\u064e\u0670\u062a\u0650 \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u0650\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0639\u064e\u062f\u064f\u0648\u0651\u065e \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u065e",translation:"dan di antara hewan-hewan itu ada yang dijadikan pengangkut beban dan ada (pula) yang untuk disembelih. Makanlah rezeki yang diberikan Allah kepadamu, dan janganlah kamu mengikuti langkah-langkah setan. Sesungguhnya setan itu musuh yang nyata bagimu"},{id:143,text:"\u062b\u064e\u0645\u064e\u0670\u0646\u0650\u064a\u064e\u0629\u064e \u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u0656\u06d6 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0636\u0651\u064e\u0623\u06e1\u0646\u0650 \u0671\u062b\u06e1\u0646\u064e\u064a\u06e1\u0646\u0650 \u0648\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064e\u0639\u06e1\u0632\u0650 \u0671\u062b\u06e1\u0646\u064e\u064a\u06e1\u0646\u0650\u06d7 \u0642\u064f\u0644\u06e1 \u0621\u064e\u0627\u0653\u0644\u0630\u0651\u064e\u0643\u064e\u0631\u064e\u064a\u06e1\u0646\u0650 \u062d\u064e\u0631\u0651\u064e\u0645\u064e \u0623\u064e\u0645\u0650 \u0671\u0644\u06e1\u0623\u064f\u0646\u062b\u064e\u064a\u064e\u064a\u06e1\u0646\u0650 \u0623\u064e\u0645\u0651\u064e\u0627 \u0671\u0634\u06e1\u062a\u064e\u0645\u064e\u0644\u064e\u062a\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0623\u064e\u0631\u06e1\u062d\u064e\u0627\u0645\u064f \u0671\u0644\u06e1\u0623\u064f\u0646\u062b\u064e\u064a\u064e\u064a\u06e1\u0646\u0650\u06d6 \u0646\u064e\u0628\u0651\u0650\u0640\u0654\u064f\u0648\u0646\u0650\u064a \u0628\u0650\u0639\u0650\u0644\u06e1\u0645\u064d \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0635\u064e\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Ada delapan hewan ternak yang berpasangan (empat pasang); sepasang domba dan sepasang kambing. Katakanlah, \"Apakah yang diharamkan Allah dua yang jantan atau dua yang betina atau yang ada dalam kandungan kedua betinanya? Terangkanlah kepadaku berdasar pengetahuan jika kamu orang yang benar"},{id:144,text:"\u0648\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0625\u0650\u0628\u0650\u0644\u0650 \u0671\u062b\u06e1\u0646\u064e\u064a\u06e1\u0646\u0650 \u0648\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0628\u064e\u0642\u064e\u0631\u0650 \u0671\u062b\u06e1\u0646\u064e\u064a\u06e1\u0646\u0650\u06d7 \u0642\u064f\u0644\u06e1 \u0621\u064e\u0627\u0653\u0644\u0630\u0651\u064e\u0643\u064e\u0631\u064e\u064a\u06e1\u0646\u0650 \u062d\u064e\u0631\u0651\u064e\u0645\u064e \u0623\u064e\u0645\u0650 \u0671\u0644\u06e1\u0623\u064f\u0646\u062b\u064e\u064a\u064e\u064a\u06e1\u0646\u0650 \u0623\u064e\u0645\u0651\u064e\u0627 \u0671\u0634\u06e1\u062a\u064e\u0645\u064e\u0644\u064e\u062a\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0623\u064e\u0631\u06e1\u062d\u064e\u0627\u0645\u064f \u0671\u0644\u06e1\u0623\u064f\u0646\u062b\u064e\u064a\u064e\u064a\u06e1\u0646\u0650\u06d6 \u0623\u064e\u0645\u06e1 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0634\u064f\u0647\u064e\u062f\u064e\u0627\u0653\u0621\u064e \u0625\u0650\u0630\u06e1 \u0648\u064e\u0635\u0651\u064e\u0649\u0670\u0643\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0647\u064e\u0670\u0630\u064e\u0627\u06da \u0641\u064e\u0645\u064e\u0646\u06e1 \u0623\u064e\u0638\u06e1\u0644\u064e\u0645\u064f \u0645\u0650\u0645\u0651\u064e\u0646\u0650 \u0671\u0641\u06e1\u062a\u064e\u0631\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u0630\u0650\u0628\u0657\u0627 \u0644\u0651\u0650\u064a\u064f\u0636\u0650\u0644\u0651\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0628\u0650\u063a\u064e\u064a\u06e1\u0631\u0650 \u0639\u0650\u0644\u06e1\u0645\u064d\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064e\u0647\u06e1\u062f\u0650\u064a \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dan dari unta sepasang dan dari sapi sepasang. Katakanlah, \"Apakah yang diharamkan dua yang jantan atau dua yang betina, atau yang ada dalam kandungan kedua betinanya? Apakah kamu menjadi saksi ketika Allah menetapkan ini bagimu? Siapakah yang lebih zalim daripada orang-orang yang mengada-adakan kebohongan terhadap Allah untuk menyesatkan orang-orang tanpa pengetahuan?\" Sesungguhnya Allah tidak akan memberi petunjuk kepada orang-orang yang zalim"},{id:145,text:"\u0642\u064f\u0644 \u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u062c\u0650\u062f\u064f \u0641\u0650\u064a \u0645\u064e\u0627\u0653 \u0623\u064f\u0648\u062d\u0650\u064a\u064e \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0645\u064f\u062d\u064e\u0631\u0651\u064e\u0645\u064b\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0637\u064e\u0627\u0639\u0650\u0645\u0656 \u064a\u064e\u0637\u06e1\u0639\u064e\u0645\u064f\u0647\u064f\u06e5\u0653 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u064e\u064a\u06e1\u062a\u064e\u0629\u064b \u0623\u064e\u0648\u06e1 \u062f\u064e\u0645\u0657\u0627 \u0645\u0651\u064e\u0633\u06e1\u0641\u064f\u0648\u062d\u064b\u0627 \u0623\u064e\u0648\u06e1 \u0644\u064e\u062d\u06e1\u0645\u064e \u062e\u0650\u0646\u0632\u0650\u064a\u0631\u0656 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0631\u0650\u062c\u06e1\u0633\u064c \u0623\u064e\u0648\u06e1 \u0641\u0650\u0633\u06e1\u0642\u064b\u0627 \u0623\u064f\u0647\u0650\u0644\u0651\u064e \u0644\u0650\u063a\u064e\u064a\u06e1\u0631\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u0650\u0647\u0650\u06e6\u06da \u0641\u064e\u0645\u064e\u0646\u0650 \u0671\u0636\u06e1\u0637\u064f\u0631\u0651\u064e \u063a\u064e\u064a\u06e1\u0631\u064e \u0628\u064e\u0627\u063a\u0656 \u0648\u064e\u0644\u064e\u0627 \u0639\u064e\u0627\u062f\u0656 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u065e",translation:"Katakanlah, \"Tidak kudapati di dalam apa yang diwahyukan kepadaku, sesuatu yang diharamkan memakannya bagi yang ingin memakannya, kecuali daging hewan yang mati (bangkai), darah yang mengalir, daging babi \u2013 karena semua itu kotor \u2013 atau hewan yang disembelih bukan atas (nama) Allah. Tetapi barang siapa terpaksa bukan karena menginginkan dan tidak melebihi (batas darurat) maka sungguh, Tuhanmu Maha Pengampun, Maha Penyayang"},{id:146,text:"\u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064e\u0627\u062f\u064f\u0648\u0627\u0652 \u062d\u064e\u0631\u0651\u064e\u0645\u06e1\u0646\u064e\u0627 \u0643\u064f\u0644\u0651\u064e \u0630\u0650\u064a \u0638\u064f\u0641\u064f\u0631\u0656\u06d6 \u0648\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0628\u064e\u0642\u064e\u0631\u0650 \u0648\u064e\u0671\u0644\u06e1\u063a\u064e\u0646\u064e\u0645\u0650 \u062d\u064e\u0631\u0651\u064e\u0645\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0634\u064f\u062d\u064f\u0648\u0645\u064e\u0647\u064f\u0645\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u062d\u064e\u0645\u064e\u0644\u064e\u062a\u06e1 \u0638\u064f\u0647\u064f\u0648\u0631\u064f\u0647\u064f\u0645\u064e\u0627\u0653 \u0623\u064e\u0648\u0650 \u0671\u0644\u06e1\u062d\u064e\u0648\u064e\u0627\u064a\u064e\u0627\u0653 \u0623\u064e\u0648\u06e1 \u0645\u064e\u0627 \u0671\u062e\u06e1\u062a\u064e\u0644\u064e\u0637\u064e \u0628\u0650\u0639\u064e\u0638\u06e1\u0645\u0656\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062c\u064e\u0632\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f\u0645 \u0628\u0650\u0628\u064e\u063a\u06e1\u064a\u0650\u0647\u0650\u0645\u06e1\u06d6 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0635\u064e\u0670\u062f\u0650\u0642\u064f\u0648\u0646\u064e",translation:"Dan kepada orang-orang Yahudi, Kami haramkan semua (hewan) yang berkuku,327) dan Kami haramkan kepada mereka lemak sapi dan domba, kecuali yang melekat di punggungnya, atau yang dalam isi perutnya, atau yang bercampur dengan tulang. Demikianlah Kami menghukum mereka karena kedurhakaannya. Dan sungguh, Kami Mahabenar"},{id:147,text:"\u0641\u064e\u0625\u0650\u0646 \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0643\u064e \u0641\u064e\u0642\u064f\u0644 \u0631\u0651\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u06e1 \u0630\u064f\u0648 \u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u0656 \u0648\u064e\u0670\u0633\u0650\u0639\u064e\u0629\u0656 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0631\u064e\u062f\u0651\u064f \u0628\u064e\u0623\u06e1\u0633\u064f\u0647\u064f\u06e5 \u0639\u064e\u0646\u0650 \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0645\u064f\u062c\u06e1\u0631\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Maka jika mereka mendustakan kamu, katakanlah, \"Tuhanmu mempunyai rahmat yang luas, dan siksa-Nya kepada orang-orang yang berdosa tidak dapat dielakkan"},{id:148,text:"\u0633\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u0634\u06e1\u0631\u064e\u0643\u064f\u0648\u0627\u0652 \u0644\u064e\u0648\u06e1 \u0634\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0627\u0653 \u0623\u064e\u0634\u06e1\u0631\u064e\u0643\u06e1\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0627\u0653 \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0624\u064f\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u062d\u064e\u0631\u0651\u064e\u0645\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646 \u0634\u064e\u064a\u06e1\u0621\u0656\u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u0645\u06e1 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0630\u064e\u0627\u0642\u064f\u0648\u0627\u0652 \u0628\u064e\u0623\u06e1\u0633\u064e\u0646\u064e\u0627\u06d7 \u0642\u064f\u0644\u06e1 \u0647\u064e\u0644\u06e1 \u0639\u0650\u0646\u062f\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0639\u0650\u0644\u06e1\u0645\u0656 \u0641\u064e\u062a\u064f\u062e\u06e1\u0631\u0650\u062c\u064f\u0648\u0647\u064f \u0644\u064e\u0646\u064e\u0627\u0653\u06d6 \u0625\u0650\u0646 \u062a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0638\u0651\u064e\u0646\u0651\u064e \u0648\u064e\u0625\u0650\u0646\u06e1 \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u062a\u064e\u062e\u06e1\u0631\u064f\u0635\u064f\u0648\u0646\u064e",translation:"Orang-orang musyrik akan berkata, \"Jika Allah menghendaki, tentu kami tidak akan mempersekutukan-Nya, begitu pula nenek moyang kami, dan kami tidak akan mengharamkan apa pun.\" Demikian pula orang-orang sebelum mereka yang telah mendustakan (para Rasul) sampai mereka merasakan azab Kami. Katakanlah (Muhammad), \"Apakah kamu mempunyai pengetahuan yang dapat kamu kemukakan kepada kami? Yang kamu ikuti hanya persangkaan belaka, dan kamu hanya mengira"},{id:149,text:"\u0642\u064f\u0644\u06e1 \u0641\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u062d\u064f\u062c\u0651\u064e\u0629\u064f \u0671\u0644\u06e1\u0628\u064e\u0670\u0644\u0650\u063a\u064e\u0629\u064f\u06d6 \u0641\u064e\u0644\u064e\u0648\u06e1 \u0634\u064e\u0627\u0653\u0621\u064e \u0644\u064e\u0647\u064e\u062f\u064e\u0649\u0670\u0643\u064f\u0645\u06e1 \u0623\u064e\u062c\u06e1\u0645\u064e\u0639\u0650\u064a\u0646\u064e",translation:"Katakanlah (Muhammad), \"Alasan yang kuat hanya pada Allah. Maka kalau Dia menghendaki, niscaya kamu semua mendapat petunjuk"},{id:150,text:"\u0642\u064f\u0644\u06e1 \u0647\u064e\u0644\u064f\u0645\u0651\u064e \u0634\u064f\u0647\u064e\u062f\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0634\u06e1\u0647\u064e\u062f\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u062d\u064e\u0631\u0651\u064e\u0645\u064e \u0647\u064e\u0670\u0630\u064e\u0627\u06d6 \u0641\u064e\u0625\u0650\u0646 \u0634\u064e\u0647\u0650\u062f\u064f\u0648\u0627\u0652 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0634\u06e1\u0647\u064e\u062f\u06e1 \u0645\u064e\u0639\u064e\u0647\u064f\u0645\u06e1\u06da \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u06e1 \u0623\u064e\u0647\u06e1\u0648\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0648\u064e\u0647\u064f\u0645 \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u064a\u064e\u0639\u06e1\u062f\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Katakanlah (Muhammad), \"Bawalah saksi-saksimu yang dapat membuktikan bahwa Allah mengharamkan ini.\" Jika mereka memberikan kesaksian, engkau jangan (ikut pula) memberikan kesaksian bersama mereka. Jangan engkau ikuti keinginan orang-orang yang mendustakan ayat-ayat Kami dan orang-orang yang tidak beriman kepada akhirat, dan mereka mempersekutukan Tuhan"},{id:151,text:"\u06de\u0642\u064f\u0644\u06e1 \u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0648\u06e1\u0627\u0652 \u0623\u064e\u062a\u06e1\u0644\u064f \u0645\u064e\u0627 \u062d\u064e\u0631\u0651\u064e\u0645\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1\u06d6 \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064f\u0634\u06e1\u0631\u0650\u0643\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6 \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627\u06d6 \u0648\u064e\u0628\u0650\u0671\u0644\u06e1\u0648\u064e\u0670\u0644\u0650\u062f\u064e\u064a\u06e1\u0646\u0650 \u0625\u0650\u062d\u06e1\u0633\u064e\u0670\u0646\u0657\u0627\u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u06e1\u062a\u064f\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0648\u06e1\u0644\u064e\u0670\u062f\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0625\u0650\u0645\u06e1\u0644\u064e\u0670\u0642\u0656 \u0646\u0651\u064e\u062d\u06e1\u0646\u064f \u0646\u064e\u0631\u06e1\u0632\u064f\u0642\u064f\u0643\u064f\u0645\u06e1 \u0648\u064e\u0625\u0650\u064a\u0651\u064e\u0627\u0647\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u06e1\u0631\u064e\u0628\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0641\u064e\u0648\u064e\u0670\u062d\u0650\u0634\u064e \u0645\u064e\u0627 \u0638\u064e\u0647\u064e\u0631\u064e \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u0637\u064e\u0646\u064e\u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u06e1\u062a\u064f\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0646\u0651\u064e\u0641\u06e1\u0633\u064e \u0671\u0644\u0651\u064e\u062a\u0650\u064a \u062d\u064e\u0631\u0651\u064e\u0645\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0635\u0651\u064e\u0649\u0670\u0643\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Katakanlah (Muhammad), \"Marilah aku bacakan apa yang diharamkan Tuhan kepadamu. Jangan mempersekutukan-Nya dengan apa pun, berbuat baik kepada ibu bapak, janganlah membunuh anak-anakmu karena miskin. Kamilah yang memberi rezeki kepadamu dan kepada mereka; janganlah kamu mendekati perbuatan keji, baik yang terlihat ataupun yang tersembunyi, janganlah kamu membunuh orang yang diharamkan Allah kecuali dengan alasan yang benar.328) Demikianlah Dia memerintahkan kepadamu agar kamu mengerti"},{id:152,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u06e1\u0631\u064e\u0628\u064f\u0648\u0627\u0652 \u0645\u064e\u0627\u0644\u064e \u0671\u0644\u06e1\u064a\u064e\u062a\u0650\u064a\u0645\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0671\u0644\u0651\u064e\u062a\u0650\u064a \u0647\u0650\u064a\u064e \u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064f \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0628\u06e1\u0644\u064f\u063a\u064e \u0623\u064e\u0634\u064f\u062f\u0651\u064e\u0647\u064f\u06e5\u06da \u0648\u064e\u0623\u064e\u0648\u06e1\u0641\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0643\u064e\u064a\u06e1\u0644\u064e \u0648\u064e\u0671\u0644\u06e1\u0645\u0650\u064a\u0632\u064e\u0627\u0646\u064e \u0628\u0650\u0671\u0644\u06e1\u0642\u0650\u0633\u06e1\u0637\u0650\u06d6 \u0644\u064e\u0627 \u0646\u064f\u0643\u064e\u0644\u0651\u0650\u0641\u064f \u0646\u064e\u0641\u06e1\u0633\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0648\u064f\u0633\u06e1\u0639\u064e\u0647\u064e\u0627\u06d6 \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u064f\u0644\u06e1\u062a\u064f\u0645\u06e1 \u0641\u064e\u0671\u0639\u06e1\u062f\u0650\u0644\u064f\u0648\u0627\u0652 \u0648\u064e\u0644\u064e\u0648\u06e1 \u0643\u064e\u0627\u0646\u064e \u0630\u064e\u0627 \u0642\u064f\u0631\u06e1\u0628\u064e\u0649\u0670\u06d6 \u0648\u064e\u0628\u0650\u0639\u064e\u0647\u06e1\u062f\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0648\u06e1\u0641\u064f\u0648\u0627\u0652\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0635\u0651\u064e\u0649\u0670\u0643\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan janganlah kamu mendekati harta anak yatim, kecuali dengan cara yang lebih bermanfaat, sampai dia mencapai (usia) dewasa. Dan sempurnakanlah takaran dan timbangan dengan adil. Kami tidak membebani seseorang melainkan menurut kesanggupannya. Apabila kamu berbicara, bicaralah sejujurnya, sekalipun dia kerabat (mu) dan penuhilah janji Allah. Demikianlah Dia memerintahkan kepadamu agar kamu ingat"},{id:153,text:"\u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0635\u0650\u0631\u064e\u0670\u0637\u0650\u064a \u0645\u064f\u0633\u06e1\u062a\u064e\u0642\u0650\u064a\u0645\u0657\u0627 \u0641\u064e\u0671\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0647\u064f\u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0627\u0652 \u0671\u0644\u0633\u0651\u064f\u0628\u064f\u0644\u064e \u0641\u064e\u062a\u064e\u0641\u064e\u0631\u0651\u064e\u0642\u064e \u0628\u0650\u0643\u064f\u0645\u06e1 \u0639\u064e\u0646 \u0633\u064e\u0628\u0650\u064a\u0644\u0650\u0647\u0650\u06e6\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0635\u0651\u064e\u0649\u0670\u0643\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",translation:"Dan sungguh, inilah jalan-Ku yang lurus. Maka ikutilah! Jangan kamu ikuti jalan-jalan (yang lain) yang akan mencerai-beraikan kamu dari jalan-Nya. Demikianlah Dia memerintahkan kepadamu agar kamu bertakwa"},{id:154,text:"\u062b\u064f\u0645\u0651\u064e \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u062a\u064e\u0645\u064e\u0627\u0645\u064b\u0627 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064e \u0648\u064e\u062a\u064e\u0641\u06e1\u0635\u0650\u064a\u0644\u0657\u0627 \u0644\u0651\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0648\u064e\u0647\u064f\u062f\u0657\u0649 \u0648\u064e\u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u0657 \u0644\u0651\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645 \u0628\u0650\u0644\u0650\u0642\u064e\u0627\u0653\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Kemudian Kami telah memberikan kepada Musa Kitab (Taurat) untuk meyempurnakan (nikmat Kami) kepada orang yang berbuat kebaikan, untuk menjelaskan segala sesuatu, dan sebagai petunjuk dan rahmat, agar mereka beriman akan adanya pertemuan dengan Tuhannya"},{id:155,text:"\u0648\u064e\u0647\u064e\u0670\u0630\u064e\u0627 \u0643\u0650\u062a\u064e\u0670\u0628\u064c \u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f \u0645\u064f\u0628\u064e\u0627\u0631\u064e\u0643\u065e \u0641\u064e\u0671\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0647\u064f \u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064f\u0631\u06e1\u062d\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan ini adalah Kitab (Alquran) yang Kami turunkan dengan penuh berkah. Ikutilah, dan bertakwalah agar kamu mendapat rahmat"},{id:156,text:"\u0623\u064e\u0646 \u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0637\u064e\u0627\u0653\u0626\u0650\u0641\u064e\u062a\u064e\u064a\u06e1\u0646\u0650 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0646\u064e\u0627 \u0648\u064e\u0625\u0650\u0646 \u0643\u064f\u0646\u0651\u064e\u0627 \u0639\u064e\u0646 \u062f\u0650\u0631\u064e\u0627\u0633\u064e\u062a\u0650\u0647\u0650\u0645\u06e1 \u0644\u064e\u063a\u064e\u0670\u0641\u0650\u0644\u0650\u064a\u0646\u064e",translation:"(Kami turunkan Alquran itu) agar kamu (tidak) mengatakan, \"Kitab itu hanya diturunkan kepada dua golongan sebelum kami (Yahudi dan Nasrani) dan sungguh, kami tidak memperhatikan apa yang mereka baca"},{id:157,text:"\u0623\u064e\u0648\u06e1 \u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0648\u06e1 \u0623\u064e\u0646\u0651\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064f \u0644\u064e\u0643\u064f\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u0647\u06e1\u062f\u064e\u0649\u0670 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1\u06da \u0641\u064e\u0642\u064e\u062f\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0629\u065e \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0647\u064f\u062f\u0657\u0649 \u0648\u064e\u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u065e\u06da \u0641\u064e\u0645\u064e\u0646\u06e1 \u0623\u064e\u0638\u06e1\u0644\u064e\u0645\u064f \u0645\u0650\u0645\u0651\u064e\u0646 \u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0635\u064e\u062f\u064e\u0641\u064e \u0639\u064e\u0646\u06e1\u0647\u064e\u0627\u06d7 \u0633\u064e\u0646\u064e\u062c\u06e1\u0632\u0650\u064a \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0635\u06e1\u062f\u0650\u0641\u064f\u0648\u0646\u064e \u0639\u064e\u0646\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0633\u064f\u0648\u0653\u0621\u064e \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0635\u06e1\u062f\u0650\u0641\u064f\u0648\u0646\u064e",translation:"atau agar kamu (tidak) mengatakan, \"Jikalau Kitab itu diturunkan kepada kami, tentulah kami lebih mendapat petunjuk daripada mereka.\" Sungguh, telah datang kepadamu penjelasan yang nyata, petunjuk dan rahmat dari Tuhanmu. Siapakah yang lebih zalim daripada orang yang mendustakan ayat-ayat Allah dan berpaling daripadanya? Kelak, Kami akan memberi balasan kepada orang-orang yang berpaling dari ayat-ayat Kami dengan azab yang keras, karena mereka selalu berpaling"},{id:158,text:"\u0647\u064e\u0644\u06e1 \u064a\u064e\u0646\u0638\u064f\u0631\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u062a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u064f \u0623\u064e\u0648\u06e1 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0623\u064e\u0648\u06e1 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e \u0628\u064e\u0639\u06e1\u0636\u064f \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e\u06d7 \u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064e\u0623\u06e1\u062a\u0650\u064a \u0628\u064e\u0639\u06e1\u0636\u064f \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0644\u064e\u0627 \u064a\u064e\u0646\u0641\u064e\u0639\u064f \u0646\u064e\u0641\u06e1\u0633\u064b\u0627 \u0625\u0650\u064a\u0645\u064e\u0670\u0646\u064f\u0647\u064e\u0627 \u0644\u064e\u0645\u06e1 \u062a\u064e\u0643\u064f\u0646\u06e1 \u0621\u064e\u0627\u0645\u064e\u0646\u064e\u062a\u06e1 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f \u0623\u064e\u0648\u06e1 \u0643\u064e\u0633\u064e\u0628\u064e\u062a\u06e1 \u0641\u0650\u064a\u0653 \u0625\u0650\u064a\u0645\u064e\u0670\u0646\u0650\u0647\u064e\u0627 \u062e\u064e\u064a\u06e1\u0631\u0657\u0627\u06d7 \u0642\u064f\u0644\u0650 \u0671\u0646\u062a\u064e\u0638\u0650\u0631\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e\u0627 \u0645\u064f\u0646\u062a\u064e\u0638\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Yang mereka nanti-nantikan hanyalah kedatangan malaikat kepada mereka, atau kedatangan Tuhanmu, atau sebagian tanda-tanda dari Tuhanmu. Pada hari datangnya sebagian tanda-tanda Tuhanmu tidak berguna lagi iman seseorang yang belum beriman sebelum itu, atau (belum) berusaha berbuat kebajikan dengan imannya itu. Katakanlah, \"Tunggulah! Kami pun menunggu"},{id:159,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0641\u064e\u0631\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u062f\u0650\u064a\u0646\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0634\u0650\u064a\u064e\u0639\u0657\u0627 \u0644\u0651\u064e\u0633\u06e1\u062a\u064e \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0634\u064e\u064a\u06e1\u0621\u064d\u06da \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0645\u06e1\u0631\u064f\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0647\u064f\u0645 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0641\u06e1\u0639\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Sesungguhnya orang-orang yang memecah belah agamanya dan mereka menjadi (terpecah) dalam golongan-golongan, sedikit pun bukan tanggung jawabmu (Muhammad) atas mereka. Sesungguhnya urusan mereka (terserah) kepada Allah. Kemudian Dia akan memberitahukan kepada mereka apa yang telah mereka perbuat"},{id:160,text:"\u0645\u064e\u0646 \u062c\u064e\u0627\u0653\u0621\u064e \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0633\u064e\u0646\u064e\u0629\u0650 \u0641\u064e\u0644\u064e\u0647\u064f\u06e5 \u0639\u064e\u0634\u06e1\u0631\u064f \u0623\u064e\u0645\u06e1\u062b\u064e\u0627\u0644\u0650\u0647\u064e\u0627\u06d6 \u0648\u064e\u0645\u064e\u0646 \u062c\u064e\u0627\u0653\u0621\u064e \u0628\u0650\u0671\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u0650 \u0641\u064e\u0644\u064e\u0627 \u064a\u064f\u062c\u06e1\u0632\u064e\u0649\u0670\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u0650\u062b\u06e1\u0644\u064e\u0647\u064e\u0627 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064f\u0638\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Barang siapa berbuat kebaikan mendapat balasan sepuluh kali lipat amalnya. Dan barang siapa berbuat kejahatan dibalas seimbang dengan kejahatannya. Mereka sedikit pun tidak dirugikan (dizalimi)"},{id:161,text:"\u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u064e\u0646\u0650\u064a \u0647\u064e\u062f\u064e\u0649\u0670\u0646\u0650\u064a \u0631\u064e\u0628\u0651\u0650\u064a\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0670\u0637\u0656 \u0645\u0651\u064f\u0633\u06e1\u062a\u064e\u0642\u0650\u064a\u0645\u0656 \u062f\u0650\u064a\u0646\u0657\u0627 \u0642\u0650\u064a\u064e\u0645\u0657\u0627 \u0645\u0651\u0650\u0644\u0651\u064e\u0629\u064e \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064e \u062d\u064e\u0646\u0650\u064a\u0641\u0657\u0627\u06da \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0634\u06e1\u0631\u0650\u0643\u0650\u064a\u0646\u064e",translation:"Katakanlah (Muhammad), \"Sesungguhnya Tuhanku telah memberiku petunjuk ke jalan yang lurus, agama yang benar, agama Ibrahim yang lurus. Dia (Ibrahim) tidak termasuk orang-orang musyrik"},{id:162,text:"\u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u064e \u0635\u064e\u0644\u064e\u0627\u062a\u0650\u064a \u0648\u064e\u0646\u064f\u0633\u064f\u0643\u0650\u064a \u0648\u064e\u0645\u064e\u062d\u06e1\u064a\u064e\u0627\u064a\u064e \u0648\u064e\u0645\u064e\u0645\u064e\u0627\u062a\u0650\u064a \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0631\u064e\u0628\u0651\u0650 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Katakanlah (Muhammad), \"Sesungguhnya salatku, ibadahku, hidupku dan matiku hanyalah untuk Allah, Tuhan seluruh alam"},{id:163,text:"\u0644\u064e\u0627 \u0634\u064e\u0631\u0650\u064a\u0643\u064e \u0644\u064e\u0647\u064f\u06e5\u06d6 \u0648\u064e\u0628\u0650\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0623\u064f\u0645\u0650\u0631\u06e1\u062a\u064f \u0648\u064e\u0623\u064e\u0646\u064e\u0627\u06e0 \u0623\u064e\u0648\u0651\u064e\u0644\u064f \u0671\u0644\u06e1\u0645\u064f\u0633\u06e1\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"tidak ada sekutu bagi-Nya; dan demikianlah yang diperintahkan kepadaku dan aku adalah orang yang pertama-tama berserah diri (muslim)"},{id:164,text:"\u0642\u064f\u0644\u06e1 \u0623\u064e\u063a\u064e\u064a\u06e1\u0631\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0628\u06e1\u063a\u0650\u064a \u0631\u064e\u0628\u0651\u0657\u0627 \u0648\u064e\u0647\u064f\u0648\u064e \u0631\u064e\u0628\u0651\u064f \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656\u06da \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u06e1\u0633\u0650\u0628\u064f \u0643\u064f\u0644\u0651\u064f \u0646\u064e\u0641\u06e1\u0633\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627\u06da \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0632\u0650\u0631\u064f \u0648\u064e\u0627\u0632\u0650\u0631\u064e\u0629\u065e \u0648\u0650\u0632\u06e1\u0631\u064e \u0623\u064f\u062e\u06e1\u0631\u064e\u0649\u0670\u06da \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645 \u0645\u0651\u064e\u0631\u06e1\u062c\u0650\u0639\u064f\u0643\u064f\u0645\u06e1 \u0641\u064e\u064a\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0643\u064f\u0645 \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u0650 \u062a\u064e\u062e\u06e1\u062a\u064e\u0644\u0650\u0641\u064f\u0648\u0646\u064e",translation:"Katakanlah (Muhammad), \"Apakah (patut) aku mencari tuhan selain Allah, padahal Dialah Tuhan bagi segala sesuatu. Setiap perbuatan dosa seseorang, dirinya sendiri yang bertanggung jawab. Dan seseorang tidak akan memikul beban dosa orang lain. Kemudian kepada Tuhanmulah kamu kembali, dan akan diberitahukan-Nya kepadamu apa yang dahulu kamu perselisihkan"},{id:165,text:"\u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0639\u064e\u0644\u064e\u0643\u064f\u0645\u06e1 \u062e\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0641\u064e \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0631\u064e\u0641\u064e\u0639\u064e \u0628\u064e\u0639\u06e1\u0636\u064e\u0643\u064f\u0645\u06e1 \u0641\u064e\u0648\u06e1\u0642\u064e \u0628\u064e\u0639\u06e1\u0636\u0656 \u062f\u064e\u0631\u064e\u062c\u064e\u0670\u062a\u0656 \u0644\u0651\u0650\u064a\u064e\u0628\u06e1\u0644\u064f\u0648\u064e\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u0645\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u064e\u0649\u0670\u0643\u064f\u0645\u06e1\u06d7 \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0633\u064e\u0631\u0650\u064a\u0639\u064f \u0671\u0644\u06e1\u0639\u0650\u0642\u064e\u0627\u0628\u0650 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f\u06e2",translation:"Dan Dialah yang menjadikan kamu sebagai khalifah-khalifah di bumi dan Dia mengangkat (derajat) sebagian kamu di atas yang lain, untuk mengujimu atas (karunia) yang diberikan-Nya kepadamu. Sesungguhnya Tuhanmu sangat cepat memberi hukuman dan sungguh, Dia Maha Pengampun, Maha Penyayang"}]},{id:7,name:"\u0627\u0644\u0623\u0639\u0631\u0627\u0641",transliteration:"Al-A'raf",translation:"Tempat-tempat Tinggi",type:"meccan",total_verses:206,verses:[{id:1,text:"\u0627\u0644\u0653\u0645\u0653\u0635\u0653",translation:"Alif L\u0101m M\u012bm \u1e63\u0101d"},{id:2,text:"\u0643\u0650\u062a\u064e\u0670\u0628\u064c \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0643\u064f\u0646 \u0641\u0650\u064a \u0635\u064e\u062f\u06e1\u0631\u0650\u0643\u064e \u062d\u064e\u0631\u064e\u062c\u065e \u0645\u0651\u0650\u0646\u06e1\u0647\u064f \u0644\u0650\u062a\u064f\u0646\u0630\u0650\u0631\u064e \u0628\u0650\u0647\u0650\u06e6 \u0648\u064e\u0630\u0650\u0643\u06e1\u0631\u064e\u0649\u0670 \u0644\u0650\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"(Inilah) Kitab yang diturunkan kepadamu (Muhammad); maka janganlah engkau sesak dada karenanya, agar engkau memberi peringatan dengan (Kitab) itu dan menjadi pelajaran bagi orang yang beriman"},{id:3,text:"\u0671\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0627\u0652 \u0645\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0648\u06e1\u0644\u0650\u064a\u064e\u0627\u0653\u0621\u064e\u06d7 \u0642\u064e\u0644\u0650\u064a\u0644\u0657\u0627 \u0645\u0651\u064e\u0627 \u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Ikutilah apa yang diturunkan kepadamu dari Tuhanmu, dan janganlah kamu ikuti selain Dia sebagai pemimpin. Sedikit sekali kamu mengambil pelajaran"},{id:4,text:"\u0648\u064e\u0643\u064e\u0645 \u0645\u0651\u0650\u0646 \u0642\u064e\u0631\u06e1\u064a\u064e\u0629\u064d \u0623\u064e\u0647\u06e1\u0644\u064e\u0643\u06e1\u0646\u064e\u0670\u0647\u064e\u0627 \u0641\u064e\u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064e\u0627 \u0628\u064e\u0623\u06e1\u0633\u064f\u0646\u064e\u0627 \u0628\u064e\u064a\u064e\u0670\u062a\u064b\u0627 \u0623\u064e\u0648\u06e1 \u0647\u064f\u0645\u06e1 \u0642\u064e\u0627\u0653\u0626\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Betapa banyak negeri yang telah Kami binasakan, siksaan Kami datang (menimpa penduduk)nya pada malam hari, atau pada saat mereka beristirahat pada siang hari"},{id:5,text:"\u0641\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u062f\u064e\u0639\u06e1\u0648\u064e\u0649\u0670\u0647\u064f\u0645\u06e1 \u0625\u0650\u0630\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645 \u0628\u064e\u0623\u06e1\u0633\u064f\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0638\u064e\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Maka ketika siksaan Kami datang menimpa mereka, keluhan mereka tidak lain, hanya mengucap, \"Sesungguhnya kami adalah orang-orang yang zalim"},{id:6,text:"\u0641\u064e\u0644\u064e\u0646\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064e\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0631\u06e1\u0633\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0648\u064e\u0644\u064e\u0646\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064e\u0646\u0651\u064e \u0671\u0644\u06e1\u0645\u064f\u0631\u06e1\u0633\u064e\u0644\u0650\u064a\u0646\u064e",translation:"Maka pasti akan Kami tanyakan kepada umat yang telah mendapat seruan (dari Rasul-rasul) dan Kami akan tanyai (pula) para rasul"},{id:7,text:"\u0641\u064e\u0644\u064e\u0646\u064e\u0642\u064f\u0635\u0651\u064e\u0646\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0628\u0650\u0639\u0650\u0644\u06e1\u0645\u0656\u06d6 \u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u063a\u064e\u0627\u0653\u0626\u0650\u0628\u0650\u064a\u0646\u064e",translation:"dan pasti akan Kami beritakan kepada mereka dengan ilmu (Kami) dan Kami tidak jauh (dari mereka)"},{id:8,text:"\u0648\u064e\u0671\u0644\u06e1\u0648\u064e\u0632\u06e1\u0646\u064f \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u064d \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f\u06da \u0641\u064e\u0645\u064e\u0646 \u062b\u064e\u0642\u064f\u0644\u064e\u062a\u06e1 \u0645\u064e\u0648\u064e\u0670\u0632\u0650\u064a\u0646\u064f\u0647\u064f\u06e5 \u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064f\u0641\u06e1\u0644\u0650\u062d\u064f\u0648\u0646\u064e",translation:"Timbangan pada hari itu (menjadi ukuran) kebenaran. Maka barang siapa berat timbangan (kebaikan) nya, mereka itulah orang yang beruntung"},{id:9,text:"\u0648\u064e\u0645\u064e\u0646\u06e1 \u062e\u064e\u0641\u0651\u064e\u062a\u06e1 \u0645\u064e\u0648\u064e\u0670\u0632\u0650\u064a\u0646\u064f\u0647\u064f\u06e5 \u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062e\u064e\u0633\u0650\u0631\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0647\u064f\u0645 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u064a\u064e\u0638\u06e1\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"dan barang siapa ringan timbangan (kebaikan)nya, maka mereka itulah orang yang telah merugikan dirinya sendiri, karena mereka mengingkari ayat-ayat Kami"},{id:10,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0645\u064e\u0643\u0651\u064e\u0646\u0651\u064e\u0640\u0670\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u064e\u0639\u064e\u0670\u064a\u0650\u0634\u064e\u06d7 \u0642\u064e\u0644\u0650\u064a\u0644\u0657\u0627 \u0645\u0651\u064e\u0627 \u062a\u064e\u0634\u06e1\u0643\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Dan sungguh, Kami telah menempatkan kamu di bumi dan di sana Kami sediakan (sumber) penghidupan untukmu. (Tetapi) sedikit sekali kamu yang bersyukur"},{id:11,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u062e\u064e\u0644\u064e\u0642\u06e1\u0646\u064e\u0670\u0643\u064f\u0645\u06e1 \u062b\u064f\u0645\u0651\u064e \u0635\u064e\u0648\u0651\u064e\u0631\u06e1\u0646\u064e\u0670\u0643\u064f\u0645\u06e1 \u062b\u064f\u0645\u0651\u064e \u0642\u064f\u0644\u06e1\u0646\u064e\u0627 \u0644\u0650\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u0650 \u0671\u0633\u06e1\u062c\u064f\u062f\u064f\u0648\u0627\u0652 \u0644\u0650\u0623\u0653\u062f\u064e\u0645\u064e \u0641\u064e\u0633\u064e\u062c\u064e\u062f\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0625\u0650\u0628\u06e1\u0644\u0650\u064a\u0633\u064e \u0644\u064e\u0645\u06e1 \u064a\u064e\u0643\u064f\u0646 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0640\u0670\u062c\u0650\u062f\u0650\u064a\u0646\u064e",translation:"Dan sungguh, Kami telah menciptakan kamu, kemudian membentuk (tubuh)mu, kemudian Kami berfirman kepada para malaikat. \"Bersujudlah kamu kepada Adam,\" maka mereka pun sujud kecuali Iblis. Ia (Iblis) tidak termasuk mereka yang bersujud"},{id:12,text:"\u0642\u064e\u0627\u0644\u064e \u0645\u064e\u0627 \u0645\u064e\u0646\u064e\u0639\u064e\u0643\u064e \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064e\u0633\u06e1\u062c\u064f\u062f\u064e \u0625\u0650\u0630\u06e1 \u0623\u064e\u0645\u064e\u0631\u06e1\u062a\u064f\u0643\u064e\u06d6 \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0646\u064e\u0627\u06e0 \u062e\u064e\u064a\u06e1\u0631\u065e \u0645\u0651\u0650\u0646\u06e1\u0647\u064f \u062e\u064e\u0644\u064e\u0642\u06e1\u062a\u064e\u0646\u0650\u064a \u0645\u0650\u0646 \u0646\u0651\u064e\u0627\u0631\u0656 \u0648\u064e\u062e\u064e\u0644\u064e\u0642\u06e1\u062a\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646 \u0637\u0650\u064a\u0646\u0656",translation:"(Allah) berfirman, \"Apakah yang menghalangimu (sehingga) kamu tidak bersujud (kepada Adam) ketika Aku menyuruhmu?\" (Iblis) menjawab, \"Aku lebih baik daripada dia. Engkau ciptakan aku dari api, sedangkan dia Engkau ciptakan dari tanah"},{id:13,text:"\u0642\u064e\u0627\u0644\u064e \u0641\u064e\u0671\u0647\u06e1\u0628\u0650\u0637\u06e1 \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0641\u064e\u0645\u064e\u0627 \u064a\u064e\u0643\u064f\u0648\u0646\u064f \u0644\u064e\u0643\u064e \u0623\u064e\u0646 \u062a\u064e\u062a\u064e\u0643\u064e\u0628\u0651\u064e\u0631\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0641\u064e\u0671\u062e\u06e1\u0631\u064f\u062c\u06e1 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u063a\u0650\u0631\u0650\u064a\u0646\u064e",translation:"(Allah) berfirman, \"Maka turunlah kamu darinya (surga); karena kamu tidak sepatutnya menyombongkan diri di dalamnya. Keluarlah! Sesungguhnya kamu termasuk makhluk yang hina"},{id:14,text:"\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0646\u0638\u0650\u0631\u06e1\u0646\u0650\u064a\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u06e1\u0645\u0650 \u064a\u064f\u0628\u06e1\u0639\u064e\u062b\u064f\u0648\u0646\u064e",translation:"(Iblis) menjawab, \"Berilah aku penangguhan waktu, sampai hari mereka dibangkitkan"},{id:15,text:"\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0646\u0638\u064e\u0631\u0650\u064a\u0646\u064e",translation:"(Allah) berfirman, \"Benar, kamu termasuk yang diberi penangguhan waktu"},{id:16,text:"\u0642\u064e\u0627\u0644\u064e \u0641\u064e\u0628\u0650\u0645\u064e\u0627\u0653 \u0623\u064e\u063a\u06e1\u0648\u064e\u064a\u06e1\u062a\u064e\u0646\u0650\u064a \u0644\u064e\u0623\u064e\u0642\u06e1\u0639\u064f\u062f\u064e\u0646\u0651\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0635\u0650\u0631\u064e\u0670\u0637\u064e\u0643\u064e \u0671\u0644\u06e1\u0645\u064f\u0633\u06e1\u062a\u064e\u0642\u0650\u064a\u0645\u064e",translation:"(Iblis) menjawab, \"Karena Engkau telah menyesatkan aku, pasti aku akan selalu menghalangi mereka dari jalan-Mu yang lurus"},{id:17,text:"\u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0623\u0653\u062a\u0650\u064a\u064e\u0646\u0651\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u06e2 \u0628\u064e\u064a\u06e1\u0646\u0650 \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u0647\u0650\u0645\u06e1 \u0648\u064e\u0645\u0650\u0646\u06e1 \u062e\u064e\u0644\u06e1\u0641\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0639\u064e\u0646\u06e1 \u0623\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0639\u064e\u0646 \u0634\u064e\u0645\u064e\u0627\u0653\u0626\u0650\u0644\u0650\u0647\u0650\u0645\u06e1\u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062c\u0650\u062f\u064f \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064e\u0647\u064f\u0645\u06e1 \u0634\u064e\u0670\u0643\u0650\u0631\u0650\u064a\u0646\u064e",translation:"kemudian pasti aku akan mendatangi mereka dari depan, dari belakang, dari kanan dan dari kiri mereka. Dan Engkau tidak akan mendapati kebanyakan mereka bersyukur"},{id:18,text:"\u0642\u064e\u0627\u0644\u064e \u0671\u062e\u06e1\u0631\u064f\u062c\u06e1 \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0645\u064e\u0630\u06e1\u0621\u064f\u0648\u0645\u0657\u0627 \u0645\u0651\u064e\u062f\u06e1\u062d\u064f\u0648\u0631\u0657\u0627\u06d6 \u0644\u0651\u064e\u0645\u064e\u0646 \u062a\u064e\u0628\u0650\u0639\u064e\u0643\u064e \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0644\u064e\u0623\u064e\u0645\u06e1\u0644\u064e\u0623\u064e\u0646\u0651\u064e \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u0623\u064e\u062c\u06e1\u0645\u064e\u0639\u0650\u064a\u0646\u064e",translation:"(Allah) berfirman, \"Keluarlah kamu dari sana (surga) dalam keadaan terhina dan terusir! Sesungguhnya barang siapa di antara mereka ada yang mengikutimu, pasti akan Aku isi neraka Jahanam dengan kamu semua"},{id:19,text:"\u0648\u064e\u064a\u064e\u0640\u0670\u0653\u0640\u0654\u064e\u0627\u062f\u064e\u0645\u064f \u0671\u0633\u06e1\u0643\u064f\u0646\u06e1 \u0623\u064e\u0646\u062a\u064e \u0648\u064e\u0632\u064e\u0648\u06e1\u062c\u064f\u0643\u064e \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u064e \u0641\u064e\u0643\u064f\u0644\u064e\u0627 \u0645\u0650\u0646\u06e1 \u062d\u064e\u064a\u06e1\u062b\u064f \u0634\u0650\u0626\u06e1\u062a\u064f\u0645\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u06e1\u0631\u064e\u0628\u064e\u0627 \u0647\u064e\u0670\u0630\u0650\u0647\u0650 \u0671\u0644\u0634\u0651\u064e\u062c\u064e\u0631\u064e\u0629\u064e \u0641\u064e\u062a\u064e\u0643\u064f\u0648\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dan (Allah berfirman), \"Wahai Adam! Tinggallah engkau bersama istrimu dalam surga dan makanlah apa saja yang kamu berdua sukai. Tetapi janganlah kamu berdua dekati pohon yang satu ini. (Apabila didekati) kamu berdua akan termasuk orang-orang yang zalim"},{id:20,text:"\u0641\u064e\u0648\u064e\u0633\u06e1\u0648\u064e\u0633\u064e \u0644\u064e\u0647\u064f\u0645\u064e\u0627 \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u064f \u0644\u0650\u064a\u064f\u0628\u06e1\u062f\u0650\u064a\u064e \u0644\u064e\u0647\u064f\u0645\u064e\u0627 \u0645\u064e\u0627 \u0648\u064f\u06e5\u0631\u0650\u064a\u064e \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u064e\u0627 \u0645\u0650\u0646 \u0633\u064e\u0648\u06e1\u0621\u064e\u0670\u062a\u0650\u0647\u0650\u0645\u064e\u0627 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0645\u064e\u0627 \u0646\u064e\u0647\u064e\u0649\u0670\u0643\u064f\u0645\u064e\u0627 \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u064e\u0627 \u0639\u064e\u0646\u06e1 \u0647\u064e\u0670\u0630\u0650\u0647\u0650 \u0671\u0644\u0634\u0651\u064e\u062c\u064e\u0631\u064e\u0629\u0650 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u062a\u064e\u0643\u064f\u0648\u0646\u064e\u0627 \u0645\u064e\u0644\u064e\u0643\u064e\u064a\u06e1\u0646\u0650 \u0623\u064e\u0648\u06e1 \u062a\u064e\u0643\u064f\u0648\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u062e\u064e\u0670\u0644\u0650\u062f\u0650\u064a\u0646\u064e",translation:"Kemudian setan membisikkan pikiran jahat kepada mereka agar menampakkan aurat mereka (yang selama ini) tertutup. Dan (setan) berkata, \"Tuhanmu hanya melarang kamu berdua mendekati pohon ini, agar kamu berdua tidak menjadi malaikat atau tidak menjadi orang yang kekal (dalam surga)"},{id:21,text:"\u0648\u064e\u0642\u064e\u0627\u0633\u064e\u0645\u064e\u0647\u064f\u0645\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0643\u064f\u0645\u064e\u0627 \u0644\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0640\u0670\u0635\u0650\u062d\u0650\u064a\u0646\u064e",translation:"Dan dia (setan) bersumpah kepada keduanya, \"Sesungguhnya aku ini benar-benar termasuk para penasihatmu"},{id:22,text:"\u0641\u064e\u062f\u064e\u0644\u0651\u064e\u0649\u0670\u0647\u064f\u0645\u064e\u0627 \u0628\u0650\u063a\u064f\u0631\u064f\u0648\u0631\u0656\u06da \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0630\u064e\u0627\u0642\u064e\u0627 \u0671\u0644\u0634\u0651\u064e\u062c\u064e\u0631\u064e\u0629\u064e \u0628\u064e\u062f\u064e\u062a\u06e1 \u0644\u064e\u0647\u064f\u0645\u064e\u0627 \u0633\u064e\u0648\u06e1\u0621\u064e\u0670\u062a\u064f\u0647\u064f\u0645\u064e\u0627 \u0648\u064e\u0637\u064e\u0641\u0650\u0642\u064e\u0627 \u064a\u064e\u062e\u06e1\u0635\u0650\u0641\u064e\u0627\u0646\u0650 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u064e\u0627 \u0645\u0650\u0646 \u0648\u064e\u0631\u064e\u0642\u0650 \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u0650\u06d6 \u0648\u064e\u0646\u064e\u0627\u062f\u064e\u0649\u0670\u0647\u064f\u0645\u064e\u0627 \u0631\u064e\u0628\u0651\u064f\u0647\u064f\u0645\u064e\u0627\u0653 \u0623\u064e\u0644\u064e\u0645\u06e1 \u0623\u064e\u0646\u06e1\u0647\u064e\u0643\u064f\u0645\u064e\u0627 \u0639\u064e\u0646 \u062a\u0650\u0644\u06e1\u0643\u064f\u0645\u064e\u0627 \u0671\u0644\u0634\u0651\u064e\u062c\u064e\u0631\u064e\u0629\u0650 \u0648\u064e\u0623\u064e\u0642\u064f\u0644 \u0644\u0651\u064e\u0643\u064f\u0645\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u064e\u0627 \u0639\u064e\u062f\u064f\u0648\u0651\u065e \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u065e",translation:"dia (setan) membujuk mereka dengan tipu daya. Ketika mereka mencicipi (buah) pohon itu, tampaklah oleh mereka auratnya, maka mulailah mereka menutupinya dengan daun-daun surga. Tuhan menyeru mereka, \"Bukankah Aku telah melarang kamu dari pohon itu dan Aku telah mengatakan bahwa sesungguhnya setan adalah musuh yang nyata bagi kamu berdua"},{id:23,text:"\u0642\u064e\u0627\u0644\u064e\u0627 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0638\u064e\u0644\u064e\u0645\u06e1\u0646\u064e\u0627\u0653 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0646\u064e\u0627 \u0648\u064e\u0625\u0650\u0646 \u0644\u0651\u064e\u0645\u06e1 \u062a\u064e\u063a\u06e1\u0641\u0650\u0631\u06e1 \u0644\u064e\u0646\u064e\u0627 \u0648\u064e\u062a\u064e\u0631\u06e1\u062d\u064e\u0645\u06e1\u0646\u064e\u0627 \u0644\u064e\u0646\u064e\u0643\u064f\u0648\u0646\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u062e\u064e\u0670\u0633\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Keduanya berkata, \"Ya Tuhan kami, kami telah menzalimi diri kami sendiri. Jika Engkau tidak mengampuni kami dan memberi rahmat kepada kami, niscaya kami termasuk orang-orang yang rugi"},{id:24,text:"\u0642\u064e\u0627\u0644\u064e \u0671\u0647\u06e1\u0628\u0650\u0637\u064f\u0648\u0627\u0652 \u0628\u064e\u0639\u06e1\u0636\u064f\u0643\u064f\u0645\u06e1 \u0644\u0650\u0628\u064e\u0639\u06e1\u0636\u064d \u0639\u064e\u062f\u064f\u0648\u0651\u065e\u06d6 \u0648\u064e\u0644\u064e\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0645\u064f\u0633\u06e1\u062a\u064e\u0642\u064e\u0631\u0651\u065e \u0648\u064e\u0645\u064e\u062a\u064e\u0670\u0639\u064c \u0625\u0650\u0644\u064e\u0649\u0670 \u062d\u0650\u064a\u0646\u0656",translation:"(Allah) berfirman, \"Turunlah kamu! Kamu akan saling bermusuhan satu sama lain. Bumi adalah tempat kediaman dan kesenanganmu sampai waktu yang telah ditentukan"},{id:25,text:"\u0642\u064e\u0627\u0644\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u062a\u064e\u062d\u06e1\u064a\u064e\u0648\u06e1\u0646\u064e \u0648\u064e\u0641\u0650\u064a\u0647\u064e\u0627 \u062a\u064e\u0645\u064f\u0648\u062a\u064f\u0648\u0646\u064e \u0648\u064e\u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u062a\u064f\u062e\u06e1\u0631\u064e\u062c\u064f\u0648\u0646\u064e",translation:"(Allah) berfirman, \"Di sana kamu hidup, di sana kamu mati, dan dari sana (pula) kamu akan dibangkitkan"},{id:26,text:"\u064a\u064e\u0670\u0628\u064e\u0646\u0650\u064a\u0653 \u0621\u064e\u0627\u062f\u064e\u0645\u064e \u0642\u064e\u062f\u06e1 \u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0644\u0650\u0628\u064e\u0627\u0633\u0657\u0627 \u064a\u064f\u0648\u064e\u0670\u0631\u0650\u064a \u0633\u064e\u0648\u06e1\u0621\u064e\u0670\u062a\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0631\u0650\u064a\u0634\u0657\u0627\u06d6 \u0648\u064e\u0644\u0650\u0628\u064e\u0627\u0633\u064f \u0671\u0644\u062a\u0651\u064e\u0642\u06e1\u0648\u064e\u0649\u0670 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062e\u064e\u064a\u06e1\u0631\u065e\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u0650\u0646\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0630\u0651\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Wahai anak cucu Adam! Sesungguhnya Kami telah menyediakan pakaian untuk menutupi auratmu dan untuk perhiasan bagimu. Tetapi pakaian takwa, itulah yang lebih baik. Demikianlah sebagian tanda-tanda kekuasaan Allah, mudah-mudahan mereka ingat"},{id:27,text:"\u064a\u064e\u0670\u0628\u064e\u0646\u0650\u064a\u0653 \u0621\u064e\u0627\u062f\u064e\u0645\u064e \u0644\u064e\u0627 \u064a\u064e\u0641\u06e1\u062a\u0650\u0646\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u064f \u0643\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u062e\u06e1\u0631\u064e\u062c\u064e \u0623\u064e\u0628\u064e\u0648\u064e\u064a\u06e1\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u064a\u064e\u0646\u0632\u0650\u0639\u064f \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u064e\u0627 \u0644\u0650\u0628\u064e\u0627\u0633\u064e\u0647\u064f\u0645\u064e\u0627 \u0644\u0650\u064a\u064f\u0631\u0650\u064a\u064e\u0647\u064f\u0645\u064e\u0627 \u0633\u064e\u0648\u06e1\u0621\u064e\u0670\u062a\u0650\u0647\u0650\u0645\u064e\u0627\u0653\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u064a\u064e\u0631\u064e\u0649\u0670\u0643\u064f\u0645\u06e1 \u0647\u064f\u0648\u064e \u0648\u064e\u0642\u064e\u0628\u0650\u064a\u0644\u064f\u0647\u064f\u06e5 \u0645\u0650\u0646\u06e1 \u062d\u064e\u064a\u06e1\u062b\u064f \u0644\u064e\u0627 \u062a\u064e\u0631\u064e\u0648\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1\u06d7 \u0625\u0650\u0646\u0651\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0671\u0644\u0634\u0651\u064e\u064a\u064e\u0670\u0637\u0650\u064a\u0646\u064e \u0623\u064e\u0648\u06e1\u0644\u0650\u064a\u064e\u0627\u0653\u0621\u064e \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Wahai anak cucu Adam! Janganlah sampai kamu tertipu oleh setan sebagaimana halnya dia (setan) telah mengeluarkan ibu bapakmu dari surga, dengan menanggalkan pakaian keduanya untuk memperlihatkan aurat keduanya. Sesungguhnya dia dan pengikutnya dapat melihat kamu dari suatu tempat yang kamu tidak bisa melihat mereka. Sesungguhnya Kami telah menjadikan setan-setan itu pemimpin bagi orang-orang yang tidak beriman"},{id:28,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0641\u064e\u0639\u064e\u0644\u064f\u0648\u0627\u0652 \u0641\u064e\u0670\u062d\u0650\u0634\u064e\u0629\u0657 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0648\u064e\u062c\u064e\u062f\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627\u0653 \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0621\u064e\u0646\u064e\u0627 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0645\u064e\u0631\u064e\u0646\u064e\u0627 \u0628\u0650\u0647\u064e\u0627\u06d7 \u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064e\u0623\u06e1\u0645\u064f\u0631\u064f \u0628\u0650\u0671\u0644\u06e1\u0641\u064e\u062d\u06e1\u0634\u064e\u0627\u0653\u0621\u0650\u06d6 \u0623\u064e\u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"(Dan apabila mereka melakukan perbuatan keji, mereka berkata, \"Kami mendapati nenek moyang kami melakukan yang demikian, dan Allah menyuruh kami mengerjakannya.\" Katakanlah, \"Sesungguhnya Allah tidak pernah menyuruh berbuat keji.329) Mengapa kamu membicarakan tentang Allah apa yang tidak kamu ketahui"},{id:29,text:"\u0642\u064f\u0644\u06e1 \u0623\u064e\u0645\u064e\u0631\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0628\u0650\u0671\u0644\u06e1\u0642\u0650\u0633\u06e1\u0637\u0650\u06d6 \u0648\u064e\u0623\u064e\u0642\u0650\u064a\u0645\u064f\u0648\u0627\u0652 \u0648\u064f\u062c\u064f\u0648\u0647\u064e\u0643\u064f\u0645\u06e1 \u0639\u0650\u0646\u062f\u064e \u0643\u064f\u0644\u0651\u0650 \u0645\u064e\u0633\u06e1\u062c\u0650\u062f\u0656 \u0648\u064e\u0671\u062f\u06e1\u0639\u064f\u0648\u0647\u064f \u0645\u064f\u062e\u06e1\u0644\u0650\u0635\u0650\u064a\u0646\u064e \u0644\u064e\u0647\u064f \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u064e\u06da \u0643\u064e\u0645\u064e\u0627 \u0628\u064e\u062f\u064e\u0623\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u0639\u064f\u0648\u062f\u064f\u0648\u0646\u064e",translation:"Katakanlah, \"Tuhanku menyuruhku berlaku adil. Hadapkanlah wajahmu (kepada Allah) pada setiap salat, dan sembahlah Dia dengan mengikhlaskan ibadah semata-mata hanya kepada-Nya. Kamu akan dikembalikan kepadanya sebagaimana kamu diciptakan semula"},{id:30,text:"\u0641\u064e\u0631\u0650\u064a\u0642\u064b\u0627 \u0647\u064e\u062f\u064e\u0649\u0670 \u0648\u064e\u0641\u064e\u0631\u0650\u064a\u0642\u064b\u0627 \u062d\u064e\u0642\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u064f \u0671\u0644\u0636\u0651\u064e\u0644\u064e\u0670\u0644\u064e\u0629\u064f\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u064f \u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627\u0652 \u0671\u0644\u0634\u0651\u064e\u064a\u064e\u0670\u0637\u0650\u064a\u0646\u064e \u0623\u064e\u0648\u06e1\u0644\u0650\u064a\u064e\u0627\u0653\u0621\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u064a\u064e\u062d\u06e1\u0633\u064e\u0628\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645 \u0645\u0651\u064f\u0647\u06e1\u062a\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Sebagian diberi-Nya petunjuk dan sebagian lagi sepantasnya menjadi sesat. Mereka menjadikan setan-setan sebagai pelindung selain Allah. Mereka mengira bahwa mereka mendapat petunjuk"},{id:31,text:"\u06de\u064a\u064e\u0670\u0628\u064e\u0646\u0650\u064a\u0653 \u0621\u064e\u0627\u062f\u064e\u0645\u064e \u062e\u064f\u0630\u064f\u0648\u0627\u0652 \u0632\u0650\u064a\u0646\u064e\u062a\u064e\u0643\u064f\u0645\u06e1 \u0639\u0650\u0646\u062f\u064e \u0643\u064f\u0644\u0651\u0650 \u0645\u064e\u0633\u06e1\u062c\u0650\u062f\u0656 \u0648\u064e\u0643\u064f\u0644\u064f\u0648\u0627\u0652 \u0648\u064e\u0671\u0634\u06e1\u0631\u064e\u0628\u064f\u0648\u0627\u0652 \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0633\u06e1\u0631\u0650\u0641\u064f\u0648\u0653\u0627\u0652\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0671\u0644\u06e1\u0645\u064f\u0633\u06e1\u0631\u0650\u0641\u0650\u064a\u0646\u064e",translation:"Wahai anak cucu Adam! Pakailah pakaianmu yang bagus pada setiap (memasuki) masjid, makan dan minumlah, tetapi jangan berlebihan! Sesungguhnya, Allah tidak menyukai orang yang berlebih-lebihan"},{id:32,text:"\u0642\u064f\u0644\u06e1 \u0645\u064e\u0646\u06e1 \u062d\u064e\u0631\u0651\u064e\u0645\u064e \u0632\u0650\u064a\u0646\u064e\u0629\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u0651\u064e\u062a\u0650\u064a\u0653 \u0623\u064e\u062e\u06e1\u0631\u064e\u062c\u064e \u0644\u0650\u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650\u06e6 \u0648\u064e\u0671\u0644\u0637\u0651\u064e\u064a\u0651\u0650\u0628\u064e\u0670\u062a\u0650 \u0645\u0650\u0646\u064e \u0671\u0644\u0631\u0651\u0650\u0632\u06e1\u0642\u0650\u06da \u0642\u064f\u0644\u06e1 \u0647\u0650\u064a\u064e \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u0650 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u062e\u064e\u0627\u0644\u0650\u0635\u064e\u0629\u0657 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650\u06d7 \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064f\u0641\u064e\u0635\u0651\u0650\u0644\u064f \u0671\u0644\u06e1\u0623\u0653\u064a\u064e\u0670\u062a\u0650 \u0644\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Katakanlah (Muhammad), \"Siapakah yang mengharamkan perhiasan dari Allah yang telah disediakan untuk hamba-hamba-Nya dan rezeki yang baik-baik? Katakanlah, \"Semua itu untuk orang-orang yang beriman dalam kehidupan dunia, dan khusus (untuk mereka saja) pada hari kiamat.330) Demikianlah Kami menjelaskan ayat-ayat itu untuk orang-orang yang mengetahui"},{id:33,text:"\u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u062d\u064e\u0631\u0651\u064e\u0645\u064e \u0631\u064e\u0628\u0651\u0650\u064a\u064e \u0671\u0644\u06e1\u0641\u064e\u0648\u064e\u0670\u062d\u0650\u0634\u064e \u0645\u064e\u0627 \u0638\u064e\u0647\u064e\u0631\u064e \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u0637\u064e\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u0625\u0650\u062b\u06e1\u0645\u064e \u0648\u064e\u0671\u0644\u06e1\u0628\u064e\u063a\u06e1\u064a\u064e \u0628\u0650\u063a\u064e\u064a\u06e1\u0631\u0650 \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0623\u064e\u0646 \u062a\u064f\u0634\u06e1\u0631\u0650\u0643\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0645\u06e1 \u064a\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u06e1 \u0628\u0650\u0647\u0650\u06e6 \u0633\u064f\u0644\u06e1\u0637\u064e\u0670\u0646\u0657\u0627 \u0648\u064e\u0623\u064e\u0646 \u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Katakanlah (Muhammad), \"Tuhanku hanya mengharamkan segala perbuatan keji yang terlihat dan yang tersembunyi, perbuatan dosa, perbuatan zalim tanpa alasan yang benar, dan (mengharamkan) kamu mempersekutukan Allah dengan sesuatu sedangkan Dia tidak menurunkan alasan untuk itu, dan (mengharamkan) kamu membicarakan tentang Allah apa yang tidak kamu ketahui"},{id:34,text:"\u0648\u064e\u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0623\u064f\u0645\u0651\u064e\u0629\u064d \u0623\u064e\u062c\u064e\u0644\u065e\u06d6 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e \u0623\u064e\u062c\u064e\u0644\u064f\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0623\u06e1\u062e\u0650\u0631\u064f\u0648\u0646\u064e \u0633\u064e\u0627\u0639\u064e\u0629\u0657 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0642\u06e1\u062f\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Dan setiap umat mempunyai ajal (batas waktu). Apabila ajalnya tiba, mereka tidak dapat meminta penundaan atau percepatan sesaat pun"},{id:35,text:"\u064a\u064e\u0670\u0628\u064e\u0646\u0650\u064a\u0653 \u0621\u064e\u0627\u062f\u064e\u0645\u064e \u0625\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0631\u064f\u0633\u064f\u0644\u065e \u0645\u0651\u0650\u0646\u0643\u064f\u0645\u06e1 \u064a\u064e\u0642\u064f\u0635\u0651\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u064a \u0641\u064e\u0645\u064e\u0646\u0650 \u0671\u062a\u0651\u064e\u0642\u064e\u0649\u0670 \u0648\u064e\u0623\u064e\u0635\u06e1\u0644\u064e\u062d\u064e \u0641\u064e\u0644\u064e\u0627 \u062e\u064e\u0648\u06e1\u0641\u064c \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u06e1 \u064a\u064e\u062d\u06e1\u0632\u064e\u0646\u064f\u0648\u0646\u064e",translation:"Wahai anak cucu Adam! Jika datang kepadamu Rasul-rasul dari kalanganmu sendiri, yang menceritakan ayat-ayat-Ku kepadamu, maka barang siapa bertakwa dan mengadakan perbaikan, maka tidak ada rasa takut pada mereka, dan mereka tidak bersedih hati"},{id:36,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0648\u064e\u0671\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u064e\u0631\u064f\u0648\u0627\u0652 \u0639\u064e\u0646\u06e1\u0647\u064e\u0627\u0653 \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650\u06d6 \u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u0670\u0644\u0650\u062f\u064f\u0648\u0646\u064e",translation:"Tetapi orang-orang yang mendustakan ayat-ayat Kami dan menyombongkan diri terhadapnya, mereka itulah penghuni neraka; mereka kekal di dalamnya"},{id:37,text:"\u0641\u064e\u0645\u064e\u0646\u06e1 \u0623\u064e\u0638\u06e1\u0644\u064e\u0645\u064f \u0645\u0650\u0645\u0651\u064e\u0646\u0650 \u0671\u0641\u06e1\u062a\u064e\u0631\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u0630\u0650\u0628\u064b\u0627 \u0623\u064e\u0648\u06e1 \u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0647\u0650\u06e6\u0653\u06da \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u064a\u064e\u0646\u064e\u0627\u0644\u064f\u0647\u064f\u0645\u06e1 \u0646\u064e\u0635\u0650\u064a\u0628\u064f\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650\u06d6 \u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u062a\u06e1\u0647\u064f\u0645\u06e1 \u0631\u064f\u0633\u064f\u0644\u064f\u0646\u064e\u0627 \u064a\u064e\u062a\u064e\u0648\u064e\u0641\u0651\u064e\u0648\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1 \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u064a\u06e1\u0646\u064e \u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0636\u064e\u0644\u0651\u064f\u0648\u0627\u0652 \u0639\u064e\u0646\u0651\u064e\u0627 \u0648\u064e\u0634\u064e\u0647\u0650\u062f\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u06e1 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Siapakah yang lebih zalim daripada orang yang mengada-adakan kebohongan terhadap Allah atau yang mendustakan ayat-ayat-Nya? Mereka itu akan memperoleh bagian yang telah ditentukan dalam Kitab sampai datang para utusan (malaikat) Kami kepada mereka untuk mencabut nyawanya. Mereka (para malaikat) berkata, Manakah sembahan yang biasa kamu sembah selain Allah?\" Mereka (orang musyrik) menjawab, \"Semuanya telah lenyap dari kami,\" dan mereka memberikan kesaksian diri mereka sendiri bahwa mereka adalah orang-orang kafir"},{id:38,text:"\u0642\u064e\u0627\u0644\u064e \u0671\u062f\u06e1\u062e\u064f\u0644\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0653 \u0623\u064f\u0645\u064e\u0645\u0656 \u0642\u064e\u062f\u06e1 \u062e\u064e\u0644\u064e\u062a\u06e1 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u062c\u0650\u0646\u0651\u0650 \u0648\u064e\u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u0650 \u0641\u0650\u064a \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650\u06d6 \u0643\u064f\u0644\u0651\u064e\u0645\u064e\u0627 \u062f\u064e\u062e\u064e\u0644\u064e\u062a\u06e1 \u0623\u064f\u0645\u0651\u064e\u0629\u065e \u0644\u0651\u064e\u0639\u064e\u0646\u064e\u062a\u06e1 \u0623\u064f\u062e\u06e1\u062a\u064e\u0647\u064e\u0627\u06d6 \u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u064e\u0627 \u0671\u062f\u0651\u064e\u0627\u0631\u064e\u0643\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u062c\u064e\u0645\u0650\u064a\u0639\u0657\u0627 \u0642\u064e\u0627\u0644\u064e\u062a\u06e1 \u0623\u064f\u062e\u06e1\u0631\u064e\u0649\u0670\u0647\u064f\u0645\u06e1 \u0644\u0650\u0623\u064f\u0648\u0644\u064e\u0649\u0670\u0647\u064f\u0645\u06e1 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650 \u0623\u064e\u0636\u064e\u0644\u0651\u064f\u0648\u0646\u064e\u0627 \u0641\u064e\u0640\u0654\u064e\u0627\u062a\u0650\u0647\u0650\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u0657\u0627 \u0636\u0650\u0639\u06e1\u0641\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650\u06d6 \u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0643\u064f\u0644\u0651\u0656 \u0636\u0650\u0639\u06e1\u0641\u065e \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u0644\u0651\u064e\u0627 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Allah berfirman, \"Masuklah kamu ke dalam api neraka bersama golongan jin dan manusia yang telah lebih dahulu dari kamu. Setiap kali suatu umat masuk, dia melaknat saudaranya, sehingga apabila mereka telah masuk semuanya, berkatalah orang yang (masuk) belakangan (kepada) orang yang (masuk) terlebih dahulu, \"Ya Tuhan kami, Mereka telah menyesatkan kami. Datangkanlah siksaan api neraka yang berlipat ganda kepada mereka\" Allah berfirman, \"Masing-masing mendapatkan (siksaan) yang berlipat ganda, tetapi kamu tidak mengetahui"},{id:39,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e\u062a\u06e1 \u0623\u064f\u0648\u0644\u064e\u0649\u0670\u0647\u064f\u0645\u06e1 \u0644\u0650\u0623\u064f\u062e\u06e1\u0631\u064e\u0649\u0670\u0647\u064f\u0645\u06e1 \u0641\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646 \u0641\u064e\u0636\u06e1\u0644\u0656 \u0641\u064e\u0630\u064f\u0648\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0643\u06e1\u0633\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Dan orang-orang yang (masuk) terlebih dahulu berkata kepada yang (masuk) belakangan,\" Kamu tidak mempunyai kelebihan sedikit pun atas kami. Maka rasakanlah azab itu karena perbuatan yang telah kamu lakukan"},{id:40,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0648\u064e\u0671\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u064e\u0631\u064f\u0648\u0627\u0652 \u0639\u064e\u0646\u06e1\u0647\u064e\u0627 \u0644\u064e\u0627 \u062a\u064f\u0641\u064e\u062a\u0651\u064e\u062d\u064f \u0644\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u0628\u06e1\u0648\u064e\u0670\u0628\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062f\u06e1\u062e\u064f\u0644\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0644\u0650\u062c\u064e \u0671\u0644\u06e1\u062c\u064e\u0645\u064e\u0644\u064f \u0641\u0650\u064a \u0633\u064e\u0645\u0651\u0650 \u0671\u0644\u06e1\u062e\u0650\u064a\u064e\u0627\u0637\u0650\u06da \u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u062c\u06e1\u0632\u0650\u064a \u0671\u0644\u06e1\u0645\u064f\u062c\u06e1\u0631\u0650\u0645\u0650\u064a\u0646\u064e",translation:"(Sesungguhnya orang-orang yang mendustakan ayat-ayat Kami dan menyombongkan diri terhadapnya, tidak akan dibukakan pintu-pintu langit bagi mereka,331) dan mereka tidak akan masuk surga, sebelum unta masuk ke dalam lubang jarum.332) Demikianlah Kami memberi balasan kepada orang-orang yang berbuat jahat"},{id:41,text:"\u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0645\u0650\u0647\u064e\u0627\u062f\u065e \u0648\u064e\u0645\u0650\u0646 \u0641\u064e\u0648\u06e1\u0642\u0650\u0647\u0650\u0645\u06e1 \u063a\u064e\u0648\u064e\u0627\u0634\u0656\u06da \u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u062c\u06e1\u0632\u0650\u064a \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Bagi mereka tikar tidur dari api neraka dan di atas mereka ada selimut (api neraka). Demikianlah Kami memberi balasan kepada orang-orang yang zalim"},{id:42,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0644\u064e\u0627 \u0646\u064f\u0643\u064e\u0644\u0651\u0650\u0641\u064f \u0646\u064e\u0641\u06e1\u0633\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0648\u064f\u0633\u06e1\u0639\u064e\u0647\u064e\u0627\u0653 \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u0650\u06d6 \u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u0670\u0644\u0650\u062f\u064f\u0648\u0646\u064e",translation:"Dan orang-orang yang beriman serta mengerjakan kebajikan, Kami tidak akan membebani seseorang melainkan menurut kesanggupannya. Mereka itulah penghuni surga; mereka kekal di dalamnya"},{id:43,text:"\u0648\u064e\u0646\u064e\u0632\u064e\u0639\u06e1\u0646\u064e\u0627 \u0645\u064e\u0627 \u0641\u0650\u064a \u0635\u064f\u062f\u064f\u0648\u0631\u0650\u0647\u0650\u0645 \u0645\u0651\u0650\u0646\u06e1 \u063a\u0650\u0644\u0651\u0656 \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0645\u0650\u0646 \u062a\u064e\u062d\u06e1\u062a\u0650\u0647\u0650\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u064f\u06d6 \u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u062d\u064e\u0645\u06e1\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0647\u064e\u062f\u064e\u0649\u0670\u0646\u064e\u0627 \u0644\u0650\u0647\u064e\u0670\u0630\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0644\u0650\u0646\u064e\u0647\u06e1\u062a\u064e\u062f\u0650\u064a\u064e \u0644\u064e\u0648\u06e1\u0644\u064e\u0627\u0653 \u0623\u064e\u0646\u06e1 \u0647\u064e\u062f\u064e\u0649\u0670\u0646\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06d6 \u0644\u064e\u0642\u064e\u062f\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u062a\u06e1 \u0631\u064f\u0633\u064f\u0644\u064f \u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627 \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650\u06d6 \u0648\u064e\u0646\u064f\u0648\u062f\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646 \u062a\u0650\u0644\u06e1\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u064f \u0623\u064f\u0648\u0631\u0650\u062b\u06e1\u062a\u064f\u0645\u064f\u0648\u0647\u064e\u0627 \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"dan kami mencabut rasa dendam dari dalam dada mereka, di bawahnya mengalir sungai-sungai. Mereka berkata, \"Segala puji bagi Allah yang telah menunjukan kami ke (surga) ini. Kami tidak akan mendapat petunjuk sekiranya Allah tidak menunjukan kami. Sesungguhnya Rasul-rasul Tuhan kami telah datang membawa kebenaran.\" Diserukan kepada mereka, \"Itulah surga yang telah diwariskan kepadamu, karena apa yang telah kamu kerjakan"},{id:44,text:"\u0648\u064e\u0646\u064e\u0627\u062f\u064e\u0649\u0670\u0653 \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0623\u064e\u0646 \u0642\u064e\u062f\u06e1 \u0648\u064e\u062c\u064e\u062f\u06e1\u0646\u064e\u0627 \u0645\u064e\u0627 \u0648\u064e\u0639\u064e\u062f\u064e\u0646\u064e\u0627 \u0631\u064e\u0628\u0651\u064f\u0646\u064e\u0627 \u062d\u064e\u0642\u0651\u0657\u0627 \u0641\u064e\u0647\u064e\u0644\u06e1 \u0648\u064e\u062c\u064e\u062f\u062a\u0651\u064f\u0645 \u0645\u0651\u064e\u0627 \u0648\u064e\u0639\u064e\u062f\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u06e1 \u062d\u064e\u0642\u0651\u0657\u0627\u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0646\u064e\u0639\u064e\u0645\u06e1\u06da \u0641\u064e\u0623\u064e\u0630\u0651\u064e\u0646\u064e \u0645\u064f\u0624\u064e\u0630\u0651\u0650\u0646\u064f\u06e2 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u0646 \u0644\u0651\u064e\u0639\u06e1\u0646\u064e\u0629\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dan para penghuni surga menyeru penghuni-penghuni neraka, \"Sungguh, Kami telah memperoleh apa yang dijanjikan Tuhan kepada kami itu benar. Apakah kamu telah memperoleh apa yang dijanjikan Tuhan kepadamu itu benar?\" Mereka menjawab, \"Benar.\" Kemudian penyeru (malaikat) mengumumkan di antara mereka, \"Laknat Allah bagi orang-orang zalim"},{id:45,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0635\u064f\u062f\u0651\u064f\u0648\u0646\u064e \u0639\u064e\u0646 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u064a\u064e\u0628\u06e1\u063a\u064f\u0648\u0646\u064e\u0647\u064e\u0627 \u0639\u0650\u0648\u064e\u062c\u0657\u0627 \u0648\u064e\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0643\u064e\u0670\u0641\u0650\u0631\u064f\u0648\u0646\u064e",translation:"(yaitu) orang-orang yang menghalang-halangi (orang lain) dari jalan Allah dan ingin membelokkannya. Mereka itulah yang mengingkari kehidupan akhirat"},{id:46,text:"\u0648\u064e\u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u062d\u0650\u062c\u064e\u0627\u0628\u065e\u06da \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0623\u064e\u0639\u06e1\u0631\u064e\u0627\u0641\u0650 \u0631\u0650\u062c\u064e\u0627\u0644\u065e \u064a\u064e\u0639\u06e1\u0631\u0650\u0641\u064f\u0648\u0646\u064e \u0643\u064f\u0644\u0651\u064e\u06e2\u0627 \u0628\u0650\u0633\u0650\u064a\u0645\u064e\u0649\u0670\u0647\u064f\u0645\u06e1\u06da \u0648\u064e\u0646\u064e\u0627\u062f\u064e\u0648\u06e1\u0627\u0652 \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064e \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u0623\u064e\u0646 \u0633\u064e\u0644\u064e\u0670\u0645\u064c \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1\u06da \u0644\u064e\u0645\u06e1 \u064a\u064e\u062f\u06e1\u062e\u064f\u0644\u064f\u0648\u0647\u064e\u0627 \u0648\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0637\u06e1\u0645\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Dan di antara keduanya (penghuni surga dan nereka) ada tabir dan di atas A'r\u0101f (tempat yang tertinggi) ada orang-orang yang saling mengenal, masing-masing dengan tanda-tandanya. Mereka menyeru penghuni surga, \"Sal\u0101mun 'alaikum\" (salam sejahtera bagimu). Mereka belum dapat masuk, tetapi mereka ingin segera (masuk)"},{id:47,text:"\u06de\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0635\u064f\u0631\u0650\u0641\u064e\u062a\u06e1 \u0623\u064e\u0628\u06e1\u0635\u064e\u0670\u0631\u064f\u0647\u064f\u0645\u06e1 \u062a\u0650\u0644\u06e1\u0642\u064e\u0627\u0653\u0621\u064e \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u0650 \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0644\u064e\u0627 \u062a\u064e\u062c\u06e1\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0645\u064e\u0639\u064e \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dan apabila pandangan mereka dialihkan ke arah penghuni neraka, mereka berkata, \"Ya Tuhan kami, janganlah Engkau tempatkan kami bersama-sama orang-orang zalim itu"},{id:48,text:"\u0648\u064e\u0646\u064e\u0627\u062f\u064e\u0649\u0670\u0653 \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u06e1\u0623\u064e\u0639\u06e1\u0631\u064e\u0627\u0641\u0650 \u0631\u0650\u062c\u064e\u0627\u0644\u0657\u0627 \u064a\u064e\u0639\u06e1\u0631\u0650\u0641\u064f\u0648\u0646\u064e\u0647\u064f\u0645 \u0628\u0650\u0633\u0650\u064a\u0645\u064e\u0649\u0670\u0647\u064f\u0645\u06e1 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0645\u064e\u0627\u0653 \u0623\u064e\u063a\u06e1\u0646\u064e\u0649\u0670 \u0639\u064e\u0646\u0643\u064f\u0645\u06e1 \u062c\u064e\u0645\u06e1\u0639\u064f\u0643\u064f\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Dan orang-orang di atas A'r\u0101f (tempat yang tertinggi) menyeru orang-orang yang mereka kenal dengan tanda-tandanya sambil berkata, \"Harta yang kamu kumpulkan dan apa yang kamu sombongkan, (ternyata) tidak ada manfaatnya buat kamu"},{id:49,text:"\u0623\u064e\u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u0642\u06e1\u0633\u064e\u0645\u06e1\u062a\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0646\u064e\u0627\u0644\u064f\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u064d\u06da \u0671\u062f\u06e1\u062e\u064f\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u064e \u0644\u064e\u0627 \u062e\u064e\u0648\u06e1\u0641\u064c \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u062d\u06e1\u0632\u064e\u0646\u064f\u0648\u0646\u064e",translation:"Itukah orang-orang yang kamu telah bersumpah, bahwa mereka tidak akan mendapat rahmat Allah?\" (Allah berfirman), \"Masuklah kamu ke dalam surga! Tidak ada rasa takut padamu dan kamu tidak pula akan bersedih hati"},{id:50,text:"\u0648\u064e\u0646\u064e\u0627\u062f\u064e\u0649\u0670\u0653 \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064e \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u0623\u064e\u0646\u06e1 \u0623\u064e\u0641\u0650\u064a\u0636\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064e\u0627\u0653\u0621\u0650 \u0623\u064e\u0648\u06e1 \u0645\u0650\u0645\u0651\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06da \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u062d\u064e\u0631\u0651\u064e\u0645\u064e\u0647\u064f\u0645\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Para penghuni neraka menyeru para penghuni surga, \"Tuangkanlah (sedikit) air kepada kami atau rezeki apa saja yang telah dikaruniakan Allah kepadamu.\" Mereka menjawab, \"Sungguh, Allah telah mengharamkan keduanya bagi orang-orang kafir"},{id:51,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627\u0652 \u062f\u0650\u064a\u0646\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0647\u06e1\u0648\u0657\u0627 \u0648\u064e\u0644\u064e\u0639\u0650\u0628\u0657\u0627 \u0648\u064e\u063a\u064e\u0631\u0651\u064e\u062a\u06e1\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u064f \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627\u06da \u0641\u064e\u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e \u0646\u064e\u0646\u0633\u064e\u0649\u0670\u0647\u064f\u0645\u06e1 \u0643\u064e\u0645\u064e\u0627 \u0646\u064e\u0633\u064f\u0648\u0627\u0652 \u0644\u0650\u0642\u064e\u0627\u0653\u0621\u064e \u064a\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u0645\u06e1 \u0647\u064e\u0670\u0630\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u064a\u064e\u062c\u06e1\u062d\u064e\u062f\u064f\u0648\u0646\u064e",translation:"(yaitu) orang-orang yang menjadikan agamanya sebagai permainan dan sendagurau, dan mereka telah tertipu oleh kehidupan dunia. Maka pada hari ini (Kiamat), Kami melupakan mereka sebagaimana mereka dahulu melupakan pertemuan hari ini, dan karena mereka mengingkari ayat-ayat Kami"},{id:52,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u062c\u0650\u0626\u06e1\u0646\u064e\u0670\u0647\u064f\u0645 \u0628\u0650\u0643\u0650\u062a\u064e\u0670\u0628\u0656 \u0641\u064e\u0635\u0651\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0639\u0650\u0644\u06e1\u0645\u064d \u0647\u064f\u062f\u0657\u0649 \u0648\u064e\u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u0657 \u0644\u0651\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Sungguh, Kami telah mendatangkan Kitab (Alquran) kepada mereka, yang Kami jelaskan atas dasar pengetahuan, sebagai petunjuk dan rahmat bagi orang-orang yang beriman"},{id:53,text:"\u0647\u064e\u0644\u06e1 \u064a\u064e\u0646\u0638\u064f\u0631\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u062a\u064e\u0623\u06e1\u0648\u0650\u064a\u0644\u064e\u0647\u064f\u06e5\u06da \u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064e\u0623\u06e1\u062a\u0650\u064a \u062a\u064e\u0623\u06e1\u0648\u0650\u064a\u0644\u064f\u0647\u064f\u06e5 \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0646\u064e\u0633\u064f\u0648\u0647\u064f \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f \u0642\u064e\u062f\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u062a\u06e1 \u0631\u064f\u0633\u064f\u0644\u064f \u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627 \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0641\u064e\u0647\u064e\u0644 \u0644\u0651\u064e\u0646\u064e\u0627 \u0645\u0650\u0646 \u0634\u064f\u0641\u064e\u0639\u064e\u0627\u0653\u0621\u064e \u0641\u064e\u064a\u064e\u0634\u06e1\u0641\u064e\u0639\u064f\u0648\u0627\u0652 \u0644\u064e\u0646\u064e\u0627\u0653 \u0623\u064e\u0648\u06e1 \u0646\u064f\u0631\u064e\u062f\u0651\u064f \u0641\u064e\u0646\u064e\u0639\u06e1\u0645\u064e\u0644\u064e \u063a\u064e\u064a\u06e1\u0631\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0643\u064f\u0646\u0651\u064e\u0627 \u0646\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u06da \u0642\u064e\u062f\u06e1 \u062e\u064e\u0633\u0650\u0631\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0636\u064e\u0644\u0651\u064e \u0639\u064e\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0641\u06e1\u062a\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Tidakkah mereka hanya menanti-nanti bukti kebenaran (Alquran) itu. Pada hari bukti kebenaran itu tiba, orang-orang yang sebelum itu mengabaikannya berkata, \"Sungguh, Rasul-rasul Tuhan kami telah datang membawa kebenaran. Maka adakah pemberi syafaat bagi kami yang akan memberikan pertolongan kepada kami atau agar kami dikembalikan (ke dunia) sehingga kami akan beramal tidak seperti perbuatan yang pernah kami lakukan dahulu?\" Mereka sebenarnya telah merugikan dirinya sendiri dan apa yang mereka ada-adakan dahulu telah hilang lenyap dari mereka"},{id:54,text:"\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0641\u0650\u064a \u0633\u0650\u062a\u0651\u064e\u0629\u0650 \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u0656 \u062b\u064f\u0645\u0651\u064e \u0671\u0633\u06e1\u062a\u064e\u0648\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0639\u064e\u0631\u06e1\u0634\u0650\u06d6 \u064a\u064f\u063a\u06e1\u0634\u0650\u064a \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u064e \u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u064a\u064e\u0637\u06e1\u0644\u064f\u0628\u064f\u0647\u064f\u06e5 \u062d\u064e\u062b\u0650\u064a\u062b\u0657\u0627 \u0648\u064e\u0671\u0644\u0634\u0651\u064e\u0645\u06e1\u0633\u064e \u0648\u064e\u0671\u0644\u06e1\u0642\u064e\u0645\u064e\u0631\u064e \u0648\u064e\u0671\u0644\u0646\u0651\u064f\u062c\u064f\u0648\u0645\u064e \u0645\u064f\u0633\u064e\u062e\u0651\u064e\u0631\u064e\u0670\u062a\u0650\u06ed \u0628\u0650\u0623\u064e\u0645\u06e1\u0631\u0650\u0647\u0650\u06e6\u0653\u06d7 \u0623\u064e\u0644\u064e\u0627 \u0644\u064e\u0647\u064f \u0671\u0644\u06e1\u062e\u064e\u0644\u06e1\u0642\u064f \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0631\u064f\u06d7 \u062a\u064e\u0628\u064e\u0627\u0631\u064e\u0643\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0631\u064e\u0628\u0651\u064f \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Sungguh, Tuhanmu (adalah) Allah yang menciptakan langit dan bumi dalam enam masa, lalu Dia bersemayam di atas Arasy.333) Dia menutupkan malam kepada siang yang mengikutinya dengan cepat. (Dia ciptakan) matahari, bulan dan bintang-bintang tunduk kepada perintah-Nya. Ingatlah! Segala penciptaan dan urusan menjadi hak-Nya. Mahasuci Allah, Tuhan seluruh alam"},{id:55,text:"\u0671\u062f\u06e1\u0639\u064f\u0648\u0627\u0652 \u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u0636\u064e\u0631\u0651\u064f\u0639\u0657\u0627 \u0648\u064e\u062e\u064f\u0641\u06e1\u064a\u064e\u0629\u064b\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0671\u0644\u06e1\u0645\u064f\u0639\u06e1\u062a\u064e\u062f\u0650\u064a\u0646\u064e",translation:"Berdoalah kepada Tuhanmu dengan rendah hati dan suara yang lembut. Sungguh, Dia tidak menyukai orang-orang yang melampaui batas"},{id:56,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0641\u06e1\u0633\u0650\u062f\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0628\u064e\u0639\u06e1\u062f\u064e \u0625\u0650\u0635\u06e1\u0644\u064e\u0670\u062d\u0650\u0647\u064e\u0627 \u0648\u064e\u0671\u062f\u06e1\u0639\u064f\u0648\u0647\u064f \u062e\u064e\u0648\u06e1\u0641\u0657\u0627 \u0648\u064e\u0637\u064e\u0645\u064e\u0639\u064b\u0627\u06da \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u062d\u06e1\u0645\u064e\u062a\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0642\u064e\u0631\u0650\u064a\u0628\u065e \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u062d\u06e1\u0633\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dan janganlah kamu berbuat kerusakan di bumi setelah (diciptakan) dengan baik. Berdoalah kepada-Nya dengan rasa takut dan penuh harap. Sesungguhnya rahmat Allah sangat dekat kepada orang yang berbuat kebaikan"},{id:57,text:"\u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u0631\u06e1\u0633\u0650\u0644\u064f \u0671\u0644\u0631\u0651\u0650\u064a\u064e\u0670\u062d\u064e \u0628\u064f\u0634\u06e1\u0631\u064e\u06e2\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u06e1 \u0631\u064e\u062d\u06e1\u0645\u064e\u062a\u0650\u0647\u0650\u06e6\u06d6 \u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u064e\u0627\u0653 \u0623\u064e\u0642\u064e\u0644\u0651\u064e\u062a\u06e1 \u0633\u064e\u062d\u064e\u0627\u0628\u0657\u0627 \u062b\u0650\u0642\u064e\u0627\u0644\u0657\u0627 \u0633\u064f\u0642\u06e1\u0646\u064e\u0670\u0647\u064f \u0644\u0650\u0628\u064e\u0644\u064e\u062f\u0656 \u0645\u0651\u064e\u064a\u0651\u0650\u062a\u0656 \u0641\u064e\u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0627 \u0628\u0650\u0647\u0650 \u0671\u0644\u06e1\u0645\u064e\u0627\u0653\u0621\u064e \u0641\u064e\u0623\u064e\u062e\u06e1\u0631\u064e\u062c\u06e1\u0646\u064e\u0627 \u0628\u0650\u0647\u0650\u06e6 \u0645\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u0671\u0644\u062b\u0651\u064e\u0645\u064e\u0631\u064e\u0670\u062a\u0650\u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064f\u062e\u06e1\u0631\u0650\u062c\u064f \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u064e\u0649\u0670 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dialah yang meniupkan angin sebagai pembawa kabar gembira, mendahului kedatangan rahmat-Nya (hujan), sehingga apabila angin itu membawa awan mendung, Kami halau ke suatu daerah yang tandus, lalu Kami turunkan hujan di daerah itu. Kemudian Kami tumbuhkan dengan hujan itu berbagai macam buah-buahan. Seperti itulah Kami membangkitkan orang yang telah mati, mudah-mudahan kamu mengambil pelajaran"},{id:58,text:"\u0648\u064e\u0671\u0644\u06e1\u0628\u064e\u0644\u064e\u062f\u064f \u0671\u0644\u0637\u0651\u064e\u064a\u0651\u0650\u0628\u064f \u064a\u064e\u062e\u06e1\u0631\u064f\u062c\u064f \u0646\u064e\u0628\u064e\u0627\u062a\u064f\u0647\u064f\u06e5 \u0628\u0650\u0625\u0650\u0630\u06e1\u0646\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0628\u064f\u062b\u064e \u0644\u064e\u0627 \u064a\u064e\u062e\u06e1\u0631\u064f\u062c\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0646\u064e\u0643\u0650\u062f\u0657\u0627\u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064f\u0635\u064e\u0631\u0651\u0650\u0641\u064f \u0671\u0644\u06e1\u0623\u0653\u064a\u064e\u0670\u062a\u0650 \u0644\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064e\u0634\u06e1\u0643\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Dan tanah yang baik, tanaman-tanamannya tumbuh subur dengan izin Tuhan; dan tanah yang buruk, tanaman-tanamannya hanya tumbuh merana. Demikianlah Kami menjelaskan berulang-ulang tanda-tanda (kebesaran Kami) bagi orang-orang yang bersyukur"},{id:59,text:"\u0644\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0646\u064f\u0648\u062d\u064b\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u06e6 \u0641\u064e\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0625\u0650\u0644\u064e\u0670\u0647\u064d \u063a\u064e\u064a\u06e1\u0631\u064f\u0647\u064f\u06e5\u0653 \u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u064a\u064e\u0648\u06e1\u0645\u064d \u0639\u064e\u0638\u0650\u064a\u0645\u0656",translation:"Sungguh, Kami benar-benar telah mengutus Nuh kepada kaumnya, lalu dia berkata, \"Wahai kaumku! Sembahlah Allah! Tidak ada Tuhan (sembahan) bagimu selain Dia. Sesungguhnya aku takut kamu akan ditimpa azab pada hari yang dahsyat (Kiamat)"},{id:60,text:"\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0623\u064f \u0645\u0650\u0646 \u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0646\u064e\u0631\u064e\u0649\u0670\u0643\u064e \u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0670\u0644\u0656 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u0656",translation:"Pemuka-pemuka kaumnya berkata, \" Sesungguhnya kami memandang kamu benar-benar berada dalam kesesatan yang nyata"},{id:61,text:"\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0644\u064e\u064a\u06e1\u0633\u064e \u0628\u0650\u064a \u0636\u064e\u0644\u064e\u0670\u0644\u064e\u0629\u065e \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u0650\u064a \u0631\u064e\u0633\u064f\u0648\u0644\u065e \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Dia (Nuh) menjawab, \"Wahai kaumku! Aku tidak sesat; tetapi aku ini seorang Rasul dari Tuhan seluruh alam"},{id:62,text:"\u0623\u064f\u0628\u064e\u0644\u0651\u0650\u063a\u064f\u0643\u064f\u0645\u06e1 \u0631\u0650\u0633\u064e\u0670\u0644\u064e\u0670\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u0623\u064e\u0646\u0635\u064e\u062d\u064f \u0644\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Aku menyampaikan kepadamu amanat Tuhanku, memberi nasehat kepadamu, dan aku mengetahui dari Allah apa yang tidak kamu ketahui"},{id:63,text:"\u0623\u064e\u0648\u064e\u0639\u064e\u062c\u0650\u0628\u06e1\u062a\u064f\u0645\u06e1 \u0623\u064e\u0646 \u062c\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u06e1 \u0630\u0650\u0643\u06e1\u0631\u065e \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u062c\u064f\u0644\u0656 \u0645\u0651\u0650\u0646\u0643\u064f\u0645\u06e1 \u0644\u0650\u064a\u064f\u0646\u0630\u0650\u0631\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u0650\u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0648\u064e\u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064f\u0631\u06e1\u062d\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan herankah kamu bahwa ada peringatan yang datang dari Tuhanmu melalui seorang laki-laki dari kalanganmu sendiri, untuk memberi peringatan kepadamu dan agar kamu bertakwa, sehingga kamu mendapat rahmat"},{id:64,text:"\u0641\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0647\u064f \u0641\u064e\u0623\u064e\u0646\u062c\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u064e\u0639\u064e\u0647\u064f\u06e5 \u0641\u0650\u064a \u0671\u0644\u06e1\u0641\u064f\u0644\u06e1\u0643\u0650 \u0648\u064e\u0623\u064e\u063a\u06e1\u0631\u064e\u0642\u06e1\u0646\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627\u0653\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0642\u064e\u0648\u06e1\u0645\u064b\u0627 \u0639\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Maka mereka mendustakan (Nuh). Lalu Kami selamatkan dia dan orang-orang yang bersamanya di dalam kapal. Kami tenggelamkan orang-orang yang mendustakan ayat-ayat Kami. Sesungguhnya mereka adalah kaum yang buta (mata hatinya)"},{id:65,text:"\u06de\u0648\u064e\u0625\u0650\u0644\u064e\u0649\u0670 \u0639\u064e\u0627\u062f\u064d \u0623\u064e\u062e\u064e\u0627\u0647\u064f\u0645\u06e1 \u0647\u064f\u0648\u062f\u0657\u0627\u06da \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0625\u0650\u0644\u064e\u0670\u0647\u064d \u063a\u064e\u064a\u06e1\u0631\u064f\u0647\u064f\u06e5\u0653\u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",translation:"Dan kepada kaum '\u0100d (Kami utus) Hud, saudara mereka. Dia berkata, \"Wahai kaumku! Sembahlah Allah! Tidak ada tuhan (sesembahan) bagimu selain Dia. Maka mengapa kamu tidak bertakwa"},{id:66,text:"\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0623\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0646\u064e\u0631\u064e\u0649\u0670\u0643\u064e \u0641\u0650\u064a \u0633\u064e\u0641\u064e\u0627\u0647\u064e\u0629\u0656 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0646\u064e\u0638\u064f\u0646\u0651\u064f\u0643\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0643\u064e\u0670\u0630\u0650\u0628\u0650\u064a\u0646\u064e",translation:"Pemuka-pemuka orang-orang yang kafir dari kaumnya berkata, \"Sesungguhnya Kami memandang kamu benar-benar kurang waras dan kami kira kamu termasuk orang-orang yang berdusta"},{id:67,text:"\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0644\u064e\u064a\u06e1\u0633\u064e \u0628\u0650\u064a \u0633\u064e\u0641\u064e\u0627\u0647\u064e\u0629\u065e \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u0650\u064a \u0631\u064e\u0633\u064f\u0648\u0644\u065e \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Dia (Hud) menjawab, \"Wahai kaumku! Bukan aku kurang waras, Tetapi aku ini adalah Rasul dari Tuhan seluruh alam"},{id:68,text:"\u0623\u064f\u0628\u064e\u0644\u0651\u0650\u063a\u064f\u0643\u064f\u0645\u06e1 \u0631\u0650\u0633\u064e\u0670\u0644\u064e\u0670\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u0623\u064e\u0646\u064e\u0627\u06e0 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0646\u064e\u0627\u0635\u0650\u062d\u064c \u0623\u064e\u0645\u0650\u064a\u0646\u064c",translation:"Aku menyampaikan kepadamu amanat Tuhanku dan pemberi nasehat yang terpercaya kepada kamu"},{id:69,text:"\u0623\u064e\u0648\u064e\u0639\u064e\u062c\u0650\u0628\u06e1\u062a\u064f\u0645\u06e1 \u0623\u064e\u0646 \u062c\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u06e1 \u0630\u0650\u0643\u06e1\u0631\u065e \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u062c\u064f\u0644\u0656 \u0645\u0651\u0650\u0646\u0643\u064f\u0645\u06e1 \u0644\u0650\u064a\u064f\u0646\u0630\u0650\u0631\u064e\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0671\u0630\u06e1\u0643\u064f\u0631\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0630\u06e1 \u062c\u064e\u0639\u064e\u0644\u064e\u0643\u064f\u0645\u06e1 \u062e\u064f\u0644\u064e\u0641\u064e\u0627\u0653\u0621\u064e \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0642\u064e\u0648\u06e1\u0645\u0650 \u0646\u064f\u0648\u062d\u0656 \u0648\u064e\u0632\u064e\u0627\u062f\u064e\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u062e\u064e\u0644\u06e1\u0642\u0650 \u0628\u064e\u0635\u06dc\u06e1\u0637\u064e\u0629\u0657\u06d6 \u0641\u064e\u0671\u0630\u06e1\u0643\u064f\u0631\u064f\u0648\u0653\u0627\u0652 \u0621\u064e\u0627\u0644\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064f\u0641\u06e1\u0644\u0650\u062d\u064f\u0648\u0646\u064e",translation:"Dan herankah kamu bahwa ada peringatan yang datang dari Tuhanmu melalui seorang laki-laki dari kalanganmu sendiri, untuk memberi peringatan kepadamu? Ingatlah ketika Dia menjadikan kamu sebagai khalifah-khalifah setelah kaum Nuh, dan Dia lebihkan kamu dalam kekuatan tubuh dan perawakan. Maka ingatlah akan nikmat-nikmat Allah agar kamu beruntung"},{id:70,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u062c\u0650\u0626\u06e1\u062a\u064e\u0646\u064e\u0627 \u0644\u0650\u0646\u064e\u0639\u06e1\u0628\u064f\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u062d\u06e1\u062f\u064e\u0647\u064f\u06e5 \u0648\u064e\u0646\u064e\u0630\u064e\u0631\u064e \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u064a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0624\u064f\u0646\u064e\u0627 \u0641\u064e\u0623\u06e1\u062a\u0650\u0646\u064e\u0627 \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0650\u062f\u064f\u0646\u064e\u0627\u0653 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Mereka berkata, \"Apakah kedatanganmu kepada kami, agar kami hanya menyembah Allah saja dan meninggalkan apa yang biasa disembah oleh nenek moyang kami? Maka buktikanlah ancamanmu kepada kami, jika kamu benar"},{id:71,text:"\u0642\u064e\u0627\u0644\u064e \u0642\u064e\u062f\u06e1 \u0648\u064e\u0642\u064e\u0639\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1 \u0631\u0650\u062c\u06e1\u0633\u065e \u0648\u064e\u063a\u064e\u0636\u064e\u0628\u064c\u06d6 \u0623\u064e\u062a\u064f\u062c\u064e\u0670\u062f\u0650\u0644\u064f\u0648\u0646\u064e\u0646\u0650\u064a \u0641\u0650\u064a\u0653 \u0623\u064e\u0633\u06e1\u0645\u064e\u0627\u0653\u0621\u0656 \u0633\u064e\u0645\u0651\u064e\u064a\u06e1\u062a\u064f\u0645\u064f\u0648\u0647\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0648\u064e\u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0624\u064f\u0643\u064f\u0645 \u0645\u0651\u064e\u0627 \u0646\u064e\u0632\u0651\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0647\u064e\u0627 \u0645\u0650\u0646 \u0633\u064f\u0644\u06e1\u0637\u064e\u0670\u0646\u0656\u06da \u0641\u064e\u0671\u0646\u062a\u064e\u0638\u0650\u0631\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u0650\u064a \u0645\u064e\u0639\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0646\u062a\u064e\u0638\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dia (Hud) menjawab, \"Sungguh, kebencian dan kemurkaan dari Tuhan akan menimpa kamu. Apakah kamu hendak berbantah denganku tentang nama-nama (berhala) yang kamu dan nenek moyangmu buat sendiri, padahal Allah tidak menurunkan keterangan untuk itu? Jika demikian tunggulah! Sesungguhnya aku pun bersamamu termasuk yang menunggu"},{id:72,text:"\u0641\u064e\u0623\u064e\u0646\u062c\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u064e\u0639\u064e\u0647\u064f\u06e5 \u0628\u0650\u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u0656 \u0645\u0651\u0650\u0646\u0651\u064e\u0627 \u0648\u064e\u0642\u064e\u0637\u064e\u0639\u06e1\u0646\u064e\u0627 \u062f\u064e\u0627\u0628\u0650\u0631\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627\u06d6 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Maka Kami selamatkan dia (Hud) dan orang-orang yang bersamanya dengan rahmat Kami dan Kami musnahkan sampai ke akar-akarnya orang-orang yang mendustakan ayat-ayat Kami. Mereka bukanlah orang-orang beriman"},{id:73,text:"\u0648\u064e\u0625\u0650\u0644\u064e\u0649\u0670 \u062b\u064e\u0645\u064f\u0648\u062f\u064e \u0623\u064e\u062e\u064e\u0627\u0647\u064f\u0645\u06e1 \u0635\u064e\u0670\u0644\u0650\u062d\u0657\u0627\u06da \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0625\u0650\u0644\u064e\u0670\u0647\u064d \u063a\u064e\u064a\u06e1\u0631\u064f\u0647\u064f\u06e5\u06d6 \u0642\u064e\u062f\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u062a\u06e1\u0643\u064f\u0645 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0629\u065e \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1\u06d6 \u0647\u064e\u0670\u0630\u0650\u0647\u0650\u06e6 \u0646\u064e\u0627\u0642\u064e\u0629\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0621\u064e\u0627\u064a\u064e\u0629\u0657\u06d6 \u0641\u064e\u0630\u064e\u0631\u064f\u0648\u0647\u064e\u0627 \u062a\u064e\u0623\u06e1\u0643\u064f\u0644\u06e1 \u0641\u0650\u064a\u0653 \u0623\u064e\u0631\u06e1\u0636\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0645\u064e\u0633\u0651\u064f\u0648\u0647\u064e\u0627 \u0628\u0650\u0633\u064f\u0648\u0653\u0621\u0656 \u0641\u064e\u064a\u064e\u0623\u06e1\u062e\u064f\u0630\u064e\u0643\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Dan kepada kaum Samud (Kami utus) saudara mereka Saleh. Dia berkata, \"Wahai kaumku! Sembahlah Allah! Tidak ada tuhan (sembahan) bagimu selain Dia. Sesungguhnya telah datang kepadamu bukti yang nyata dari Tuhanmu. Ini (seekor) Unta betina dari Allah sebagai tanda untukmu. Biarkanlah ia makan di bumi Allah, janganlah disakiti, nanti akibatnya kamu akan mendapatkan siksaan yang pedih"},{id:74,text:"\u0648\u064e\u0671\u0630\u06e1\u0643\u064f\u0631\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0630\u06e1 \u062c\u064e\u0639\u064e\u0644\u064e\u0643\u064f\u0645\u06e1 \u062e\u064f\u0644\u064e\u0641\u064e\u0627\u0653\u0621\u064e \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0639\u064e\u0627\u062f\u0656 \u0648\u064e\u0628\u064e\u0648\u0651\u064e\u0623\u064e\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u0633\u064f\u0647\u064f\u0648\u0644\u0650\u0647\u064e\u0627 \u0642\u064f\u0635\u064f\u0648\u0631\u0657\u0627 \u0648\u064e\u062a\u064e\u0646\u06e1\u062d\u0650\u062a\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u062c\u0650\u0628\u064e\u0627\u0644\u064e \u0628\u064f\u064a\u064f\u0648\u062a\u0657\u0627\u06d6 \u0641\u064e\u0671\u0630\u06e1\u0643\u064f\u0631\u064f\u0648\u0653\u0627\u0652 \u0621\u064e\u0627\u0644\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u062b\u064e\u0648\u06e1\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0645\u064f\u0641\u06e1\u0633\u0650\u062f\u0650\u064a\u0646\u064e",translation:"Dan ingatlah ketika Dia menjadikan kamu khalifah-khalifah setelah kaum 'Ad dan menempatkan kamu di bumi. Di tempat yang datar kamu dirikan istana-istana dan di bukit-bukit kamu pahat menjadi rumah-rumah. Maka ingatlah nikmat-nikmat Allah dan janganlah kamu membuat kerusakan di bumi"},{id:75,text:"\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0623\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u064e\u0631\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u06e6 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u0633\u06e1\u062a\u064f\u0636\u06e1\u0639\u0650\u0641\u064f\u0648\u0627\u0652 \u0644\u0650\u0645\u064e\u0646\u06e1 \u0621\u064e\u0627\u0645\u064e\u0646\u064e \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0623\u064e\u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0651\u064e \u0635\u064e\u0670\u0644\u0650\u062d\u0657\u0627 \u0645\u0651\u064f\u0631\u06e1\u0633\u064e\u0644\u065e \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0647\u0650\u06e6\u06da \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e\u0627 \u0628\u0650\u0645\u064e\u0627\u0653 \u0623\u064f\u0631\u06e1\u0633\u0650\u0644\u064e \u0628\u0650\u0647\u0650\u06e6 \u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Pemuka-pemuka yang menyombongkan diri berkata kepada orang-orang yang dianggap lemah, yaitu orang-orang yang telah beriman di antara kaumnya, \"Tahukah kamu bahwa Saleh adalah seorang Rasul dari Tuhannya?\" Mereka menjawab, \"Sesungguhnya kami percaya kepada apa yang disampaikannya"},{id:76,text:"\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u064e\u0631\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e\u0627 \u0628\u0650\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0621\u064e\u0627\u0645\u064e\u0646\u062a\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6 \u0643\u064e\u0670\u0641\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Orang-orang yang menyombongkan diri berkata, \"Sesungguhnya kami mengingkari apa yang kamu percayai"},{id:77,text:"\u0641\u064e\u0639\u064e\u0642\u064e\u0631\u064f\u0648\u0627\u0652 \u0671\u0644\u0646\u0651\u064e\u0627\u0642\u064e\u0629\u064e \u0648\u064e\u0639\u064e\u062a\u064e\u0648\u06e1\u0627\u0652 \u0639\u064e\u0646\u06e1 \u0623\u064e\u0645\u06e1\u0631\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u064a\u064e\u0670\u0635\u064e\u0670\u0644\u0650\u062d\u064f \u0671\u0626\u06e1\u062a\u0650\u0646\u064e\u0627 \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0650\u062f\u064f\u0646\u064e\u0627\u0653 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0631\u06e1\u0633\u064e\u0644\u0650\u064a\u0646\u064e",translation:"Kemudian mereka sembelih unta betina itu, dan berlaku angkuh terhadap perintah Tuhannya. Mereka berkata, \"Wahai Saleh! Buktikanlah ancaman kamu kepada kami, jika benar engkau termasuk salah seorang rasul"},{id:78,text:"\u0641\u064e\u0623\u064e\u062e\u064e\u0630\u064e\u062a\u06e1\u0647\u064f\u0645\u064f \u0671\u0644\u0631\u0651\u064e\u062c\u06e1\u0641\u064e\u0629\u064f \u0641\u064e\u0623\u064e\u0635\u06e1\u0628\u064e\u062d\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u062f\u064e\u0627\u0631\u0650\u0647\u0650\u0645\u06e1 \u062c\u064e\u0670\u062b\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Lalu datanglah gempa menimpa mereka, dan mereka pun mati bergelimpangan di dalam reruntuhan rumah mereka"},{id:79,text:"\u0641\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649\u0670 \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0644\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u0628\u06e1\u0644\u064e\u063a\u06e1\u062a\u064f\u0643\u064f\u0645\u06e1 \u0631\u0650\u0633\u064e\u0627\u0644\u064e\u0629\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u0646\u064e\u0635\u064e\u062d\u06e1\u062a\u064f \u0644\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u0644\u0651\u064e\u0627 \u062a\u064f\u062d\u0650\u0628\u0651\u064f\u0648\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0640\u0670\u0635\u0650\u062d\u0650\u064a\u0646\u064e",translation:"Kemudian dia (Saleh) pergi meninggalkan mereka sambil berkata, \"Wahai kaumku! Sungguh, aku telah menyampaikan amanat Tuhanku kepadamu dan aku telah menasihati kamu. Tetapi kamu tidak menyukai orang yang memberi nasehat"},{id:80,text:"\u0648\u064e\u0644\u064f\u0648\u0637\u064b\u0627 \u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u062a\u064e\u0623\u06e1\u062a\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0641\u064e\u0670\u062d\u0650\u0634\u064e\u0629\u064e \u0645\u064e\u0627 \u0633\u064e\u0628\u064e\u0642\u064e\u0643\u064f\u0645 \u0628\u0650\u0647\u064e\u0627 \u0645\u0650\u0646\u06e1 \u0623\u064e\u062d\u064e\u062f\u0656 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Dan (Kami juga telah mengutus) Lut, ketika dia berkata kepada kaumnya, \"Mengapa kamu melakukan perbuatan keji, yang belum pernah dilakukan oleh seorang pun sebelum kamu (di dunia ini)"},{id:81,text:"\u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0644\u064e\u062a\u064e\u0623\u06e1\u062a\u064f\u0648\u0646\u064e \u0671\u0644\u0631\u0651\u0650\u062c\u064e\u0627\u0644\u064e \u0634\u064e\u0647\u06e1\u0648\u064e\u0629\u0657 \u0645\u0651\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0653\u0621\u0650\u06da \u0628\u064e\u0644\u06e1 \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0642\u064e\u0648\u06e1\u0645\u065e \u0645\u0651\u064f\u0633\u06e1\u0631\u0650\u0641\u064f\u0648\u0646\u064e",translation:"Sungguh, kamu telah melampiaskan syahwatmu kepada sesama lelaki bukan kepada perempuan. Kamu benar-benar kaum yang melampaui batas"},{id:82,text:"\u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u062c\u064e\u0648\u064e\u0627\u0628\u064e \u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u062e\u06e1\u0631\u0650\u062c\u064f\u0648\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0642\u064e\u0631\u06e1\u064a\u064e\u062a\u0650\u0643\u064f\u0645\u06e1\u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0623\u064f\u0646\u064e\u0627\u0633\u065e \u064a\u064e\u062a\u064e\u0637\u064e\u0647\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan jawaban kaumnya tidak lain hanya berkata, \"Usirlah mereka (Lut dan pengikutnya) dari negerimu ini, mereka adalah orang yang menganggap dirinya suci"},{id:83,text:"\u0641\u064e\u0623\u064e\u0646\u062c\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f \u0648\u064e\u0623\u064e\u0647\u06e1\u0644\u064e\u0647\u064f\u06e5\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0645\u06e1\u0631\u064e\u0623\u064e\u062a\u064e\u0647\u064f\u06e5 \u0643\u064e\u0627\u0646\u064e\u062a\u06e1 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u063a\u064e\u0670\u0628\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Kemudian Kami selamatkan dia dan pengikutnya, kecuali istrinya. Dia (istrinya) termasuk orang-orang yang tertinggal"},{id:84,text:"\u0648\u064e\u0623\u064e\u0645\u06e1\u0637\u064e\u0631\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0645\u0651\u064e\u0637\u064e\u0631\u0657\u0627\u06d6 \u0641\u064e\u0671\u0646\u0638\u064f\u0631\u06e1 \u0643\u064e\u064a\u06e1\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0670\u0642\u0650\u0628\u064e\u0629\u064f \u0671\u0644\u06e1\u0645\u064f\u062c\u06e1\u0631\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dan Kami hujani mereka dengan hujan (batu). Maka perhatikanlah bagaimana kesudahan orang yang berbuat dosa itu"},{id:85,text:"\u0648\u064e\u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064e\u062f\u06e1\u064a\u064e\u0646\u064e \u0623\u064e\u062e\u064e\u0627\u0647\u064f\u0645\u06e1 \u0634\u064f\u0639\u064e\u064a\u06e1\u0628\u0657\u0627\u06da \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0625\u0650\u0644\u064e\u0670\u0647\u064d \u063a\u064e\u064a\u06e1\u0631\u064f\u0647\u064f\u06e5\u06d6 \u0642\u064e\u062f\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u062a\u06e1\u0643\u064f\u0645 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0629\u065e \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1\u06d6 \u0641\u064e\u0623\u064e\u0648\u06e1\u0641\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0643\u064e\u064a\u06e1\u0644\u064e \u0648\u064e\u0671\u0644\u06e1\u0645\u0650\u064a\u0632\u064e\u0627\u0646\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0628\u06e1\u062e\u064e\u0633\u064f\u0648\u0627\u0652 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0623\u064e\u0634\u06e1\u064a\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0641\u06e1\u0633\u0650\u062f\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0628\u064e\u0639\u06e1\u062f\u064e \u0625\u0650\u0635\u06e1\u0644\u064e\u0670\u062d\u0650\u0647\u064e\u0627\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u06e1 \u062e\u064e\u064a\u06e1\u0631\u065e \u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645 \u0645\u0651\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dan kepada penduduk Madyan, Kami (utus) Syu'aib, saudara mereka sendiri. Dia berkata, \"Wahai kaumku! Sembahlah Allah. Tidak ada tuhan (sembahan) bagimu selain Dia. Sesungguhnya telah datang kepadamu bukti yang nyata dari Tuhanmu. Sempurnakanlah takaran dan timbangan, dan jangan kamu merugikan orang sedikit pun. Janganlah kamu berbuat kerusakan di bumi setelah (diciptakan) dengan baik. Itulah yang lebih baik bagimu jika kamu orang beriman"},{id:86,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u06e1\u0639\u064f\u062f\u064f\u0648\u0627\u0652 \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0635\u0650\u0631\u064e\u0670\u0637\u0656 \u062a\u064f\u0648\u0639\u0650\u062f\u064f\u0648\u0646\u064e \u0648\u064e\u062a\u064e\u0635\u064f\u062f\u0651\u064f\u0648\u0646\u064e \u0639\u064e\u0646 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0646\u06e1 \u0621\u064e\u0627\u0645\u064e\u0646\u064e \u0628\u0650\u0647\u0650\u06e6 \u0648\u064e\u062a\u064e\u0628\u06e1\u063a\u064f\u0648\u0646\u064e\u0647\u064e\u0627 \u0639\u0650\u0648\u064e\u062c\u0657\u0627\u06da \u0648\u064e\u0671\u0630\u06e1\u0643\u064f\u0631\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0630\u06e1 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0642\u064e\u0644\u0650\u064a\u0644\u0657\u0627 \u0641\u064e\u0643\u064e\u062b\u0651\u064e\u0631\u064e\u0643\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0671\u0646\u0638\u064f\u0631\u064f\u0648\u0627\u0652 \u0643\u064e\u064a\u06e1\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0670\u0642\u0650\u0628\u064e\u0629\u064f \u0671\u0644\u06e1\u0645\u064f\u0641\u06e1\u0633\u0650\u062f\u0650\u064a\u0646\u064e",translation:"Dan janganlah kamu duduk di setiap jalan dengan menakut-nakuti dan menghalang-halangi orang-orang yang beriman dari jalan Allah dan ingin membelokkannya. Ingatlah ketika kamu dahulunya sedikit, lalu Allah memperbanyak jumlah kamu. Dan perhatikanlah bagaimana kesudahan orang-orang yang berbuat kerusakan"},{id:87,text:"\u0648\u064e\u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064e \u0637\u064e\u0627\u0653\u0626\u0650\u0641\u064e\u0629\u065e \u0645\u0651\u0650\u0646\u0643\u064f\u0645\u06e1 \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064f\u0631\u06e1\u0633\u0650\u0644\u06e1\u062a\u064f \u0628\u0650\u0647\u0650\u06e6 \u0648\u064e\u0637\u064e\u0627\u0653\u0626\u0650\u0641\u064e\u0629\u065e \u0644\u0651\u064e\u0645\u06e1 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0627\u0652 \u0641\u064e\u0671\u0635\u06e1\u0628\u0650\u0631\u064f\u0648\u0627\u0652 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u062d\u06e1\u0643\u064f\u0645\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u064e\u064a\u06e1\u0646\u064e\u0646\u064e\u0627\u06da \u0648\u064e\u0647\u064f\u0648\u064e \u062e\u064e\u064a\u06e1\u0631\u064f \u0671\u0644\u06e1\u062d\u064e\u0670\u0643\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Jika ada segolongan di antara kamu yang beriman kepada (ajaran) yang aku diutus menyampaikannya, dan ada (pula) segolongan yang tidak beriman, maka bersabarlah sampai Allah menetapkan keputusan di antara kita. Dialah hakim yang terbaik"},{id:88,text:"\u06de\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0623\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u064e\u0631\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u06e6 \u0644\u064e\u0646\u064f\u062e\u06e1\u0631\u0650\u062c\u064e\u0646\u0651\u064e\u0643\u064e \u064a\u064e\u0670\u0634\u064f\u0639\u064e\u064a\u06e1\u0628\u064f \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0645\u064e\u0639\u064e\u0643\u064e \u0645\u0650\u0646 \u0642\u064e\u0631\u06e1\u064a\u064e\u062a\u0650\u0646\u064e\u0627\u0653 \u0623\u064e\u0648\u06e1 \u0644\u064e\u062a\u064e\u0639\u064f\u0648\u062f\u064f\u0646\u0651\u064e \u0641\u0650\u064a \u0645\u0650\u0644\u0651\u064e\u062a\u0650\u0646\u064e\u0627\u06da \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0648\u064e\u0644\u064e\u0648\u06e1 \u0643\u064f\u0646\u0651\u064e\u0627 \u0643\u064e\u0670\u0631\u0650\u0647\u0650\u064a\u0646\u064e",translation:"Pemuka-pemuka yang meyombongkan diri dari kaum Syu'aib berkata, \"Wahai Syu'aib! Pasti kami usir engkau bersama orang-orang yang beriman dari negeri kami, kecuali engkau kembali kepada agama kami.\"Syu'aib berkata. \"Apakah (kamu akan mengusir kami), kendatipun kami tidak suka"},{id:89,text:"\u0642\u064e\u062f\u0650 \u0671\u0641\u06e1\u062a\u064e\u0631\u064e\u064a\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u0630\u0650\u0628\u064b\u0627 \u0625\u0650\u0646\u06e1 \u0639\u064f\u062f\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a \u0645\u0650\u0644\u0651\u064e\u062a\u0650\u0643\u064f\u0645 \u0628\u064e\u0639\u06e1\u062f\u064e \u0625\u0650\u0630\u06e1 \u0646\u064e\u062c\u0651\u064e\u0649\u0670\u0646\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u06e1\u0647\u064e\u0627\u06da \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0643\u064f\u0648\u0646\u064f \u0644\u064e\u0646\u064e\u0627\u0653 \u0623\u064e\u0646 \u0646\u0651\u064e\u0639\u064f\u0648\u062f\u064e \u0641\u0650\u064a\u0647\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0631\u064e\u0628\u0651\u064f\u0646\u064e\u0627\u06da \u0648\u064e\u0633\u0650\u0639\u064e \u0631\u064e\u0628\u0651\u064f\u0646\u064e\u0627 \u0643\u064f\u0644\u0651\u064e \u0634\u064e\u064a\u06e1\u0621\u064d \u0639\u0650\u0644\u06e1\u0645\u064b\u0627\u06da \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u06e1\u0646\u064e\u0627\u06da \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0671\u0641\u06e1\u062a\u064e\u062d\u06e1 \u0628\u064e\u064a\u06e1\u0646\u064e\u0646\u064e\u0627 \u0648\u064e\u0628\u064e\u064a\u06e1\u0646\u064e \u0642\u064e\u0648\u06e1\u0645\u0650\u0646\u064e\u0627 \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0623\u064e\u0646\u062a\u064e \u062e\u064e\u064a\u06e1\u0631\u064f \u0671\u0644\u06e1\u0641\u064e\u0670\u062a\u0650\u062d\u0650\u064a\u0646\u064e",translation:"Sungguh, kami telah mengada-adakan kebohongan yang besar terhadap Allah, jika kami kembali kepada agamamu, setelah Allah melepaskan kami darinya. Dan tidaklah pantas kami kembali kepadanya, kecuali jika Allah, Tuhan kami menghendaki. Pengetahuan Tuhan kami meliputi segala sesuatu. Hanya kepada Allah kami bertawakal. Ya Tuhan kami, berilah keputusan antara kami dan kaum kami dengan hak (adil). Engkaulah Pemberi keputusan terbaik"},{id:90,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0623\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u06e6 \u0644\u064e\u0626\u0650\u0646\u0650 \u0671\u062a\u0651\u064e\u0628\u064e\u0639\u06e1\u062a\u064f\u0645\u06e1 \u0634\u064f\u0639\u064e\u064a\u06e1\u0628\u064b\u0627 \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0630\u0657\u0627 \u0644\u0651\u064e\u062e\u064e\u0670\u0633\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Dan pemuka-pemuka dari kaumnya (Syu'aib) yang kafir berkata (kepada sesamanya), \"Sesungguhnya jika kamu mengikuti Syu'aib, tentu kamu menjadi orang-orang yang rugi"},{id:91,text:"\u0641\u064e\u0623\u064e\u062e\u064e\u0630\u064e\u062a\u06e1\u0647\u064f\u0645\u064f \u0671\u0644\u0631\u0651\u064e\u062c\u06e1\u0641\u064e\u0629\u064f \u0641\u064e\u0623\u064e\u0635\u06e1\u0628\u064e\u062d\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u062f\u064e\u0627\u0631\u0650\u0647\u0650\u0645\u06e1 \u062c\u064e\u0670\u062b\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Lalu datanglah gempa menimpa mereka, dan mereka pun mati bergelimpangan di dalam reruntuhan rumah mereka"},{id:92,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0634\u064f\u0639\u064e\u064a\u06e1\u0628\u0657\u0627 \u0643\u064e\u0623\u064e\u0646 \u0644\u0651\u064e\u0645\u06e1 \u064a\u064e\u063a\u06e1\u0646\u064e\u0648\u06e1\u0627\u0652 \u0641\u0650\u064a\u0647\u064e\u0627\u06da \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0634\u064f\u0639\u064e\u064a\u06e1\u0628\u0657\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u062e\u064e\u0670\u0633\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Orang-orang yang mendustakan Syu'aib seakan-akan mereka belum pernah tinggal di (negeri) itu. Mereka yang mendustakan Syu'aib, itulah orang-orang yang rugi"},{id:93,text:"\u0641\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649\u0670 \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0644\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u0628\u06e1\u0644\u064e\u063a\u06e1\u062a\u064f\u0643\u064f\u0645\u06e1 \u0631\u0650\u0633\u064e\u0670\u0644\u064e\u0670\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u0646\u064e\u0635\u064e\u062d\u06e1\u062a\u064f \u0644\u064e\u0643\u064f\u0645\u06e1\u06d6 \u0641\u064e\u0643\u064e\u064a\u06e1\u0641\u064e \u0621\u064e\u0627\u0633\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u06e1\u0645\u0656 \u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Maka Syu'aib meninggalkan mereka seraya berkata, \"Wahai kaumku! Sungguh, aku telah menyampaikan amanat Tuhanku kepadamu dan aku telah menasihati kamu. Maka bagaimana aku akan bersedih hati terhadap orang-orang kafir"},{id:94,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a \u0642\u064e\u0631\u06e1\u064a\u064e\u0629\u0656 \u0645\u0651\u0650\u0646 \u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064d \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u062e\u064e\u0630\u06e1\u0646\u064e\u0627\u0653 \u0623\u064e\u0647\u06e1\u0644\u064e\u0647\u064e\u0627 \u0628\u0650\u0671\u0644\u06e1\u0628\u064e\u0623\u06e1\u0633\u064e\u0627\u0653\u0621\u0650 \u0648\u064e\u0671\u0644\u0636\u0651\u064e\u0631\u0651\u064e\u0627\u0653\u0621\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0636\u0651\u064e\u0631\u0651\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Dan Kami tidak mengutus seorang Nabi pun kepada sesuatu negeri, (lalu penduduknya mendustakan Nabi itu), melainkan Kami timpakan kepada penduduknya kesempitan dan penderitaan agar mereka (tunduk dengan) merendahkan diri"},{id:95,text:"\u062b\u064f\u0645\u0651\u064e \u0628\u064e\u062f\u0651\u064e\u0644\u06e1\u0646\u064e\u0627 \u0645\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u0650 \u0671\u0644\u06e1\u062d\u064e\u0633\u064e\u0646\u064e\u0629\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0639\u064e\u0641\u064e\u0648\u0627\u0652 \u0648\u0651\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0642\u064e\u062f\u06e1 \u0645\u064e\u0633\u0651\u064e \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0621\u064e\u0646\u064e\u0627 \u0671\u0644\u0636\u0651\u064e\u0631\u0651\u064e\u0627\u0653\u0621\u064f \u0648\u064e\u0671\u0644\u0633\u0651\u064e\u0631\u0651\u064e\u0627\u0653\u0621\u064f \u0641\u064e\u0623\u064e\u062e\u064e\u0630\u06e1\u0646\u064e\u0670\u0647\u064f\u0645 \u0628\u064e\u063a\u06e1\u062a\u064e\u0629\u0657 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0634\u06e1\u0639\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Kemudian Kami ganti penderitaan itu dengan kesenangan sehingga (keturunan dan harta mereka) bertambah banyak, lalu mereka berkata, \"Sungguh, nenek moyang kami telah merasakan penderitaan dan kesenangan,\" maka Kami timpakan siksaan atas mereka dengan tiba-tiba tanpa mereka sadari"},{id:96,text:"\u0648\u064e\u0644\u064e\u0648\u06e1 \u0623\u064e\u0646\u0651\u064e \u0623\u064e\u0647\u06e1\u0644\u064e \u0671\u0644\u06e1\u0642\u064f\u0631\u064e\u0649\u0670\u0653 \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064e\u0648\u06e1\u0627\u0652 \u0644\u064e\u0641\u064e\u062a\u064e\u062d\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0628\u064e\u0631\u064e\u0643\u064e\u0670\u062a\u0656 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0641\u064e\u0623\u064e\u062e\u064e\u0630\u06e1\u0646\u064e\u0670\u0647\u064f\u0645 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0643\u06e1\u0633\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Dan sekiranya penduduk negeri beriman dan bertakwa, pasti Kami akan melimpahkan kepada mereka berkah dari langit dan bumi, tetapi ternyata mereka mendustakan (ayat-ayat Kami), maka Kami siksa mereka sesuai apa yang telah mereka kerjakan"},{id:97,text:"\u0623\u064e\u0641\u064e\u0623\u064e\u0645\u0650\u0646\u064e \u0623\u064e\u0647\u06e1\u0644\u064f \u0671\u0644\u06e1\u0642\u064f\u0631\u064e\u0649\u0670\u0653 \u0623\u064e\u0646 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e\u0647\u064f\u0645 \u0628\u064e\u0623\u06e1\u0633\u064f\u0646\u064e\u0627 \u0628\u064e\u064a\u064e\u0670\u062a\u0657\u0627 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0646\u064e\u0627\u0653\u0626\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Maka apakah penduduk negeri itu merasa aman dari siksaan Kami yang datang malam hari ketika mereka sedang tidur"},{id:98,text:"\u0623\u064e\u0648\u064e\u0623\u064e\u0645\u0650\u0646\u064e \u0623\u064e\u0647\u06e1\u0644\u064f \u0671\u0644\u06e1\u0642\u064f\u0631\u064e\u0649\u0670\u0653 \u0623\u064e\u0646 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e\u0647\u064f\u0645 \u0628\u064e\u0623\u06e1\u0633\u064f\u0646\u064e\u0627 \u0636\u064f\u062d\u0657\u0649 \u0648\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0644\u06e1\u0639\u064e\u0628\u064f\u0648\u0646\u064e",translation:"Atau apakah penduduk negeri itu merasa aman dari siksaan Kami yang datang pada pagi hari ketika mereka sedang bermain"},{id:99,text:"\u0623\u064e\u0641\u064e\u0623\u064e\u0645\u0650\u0646\u064f\u0648\u0627\u0652 \u0645\u064e\u0643\u06e1\u0631\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0623\u06e1\u0645\u064e\u0646\u064f \u0645\u064e\u0643\u06e1\u0631\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u064f \u0671\u0644\u06e1\u062e\u064e\u0670\u0633\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Atau apakah mereka merasa aman dari siksaan Allah (yang tidak terduga-duga)? Tidak ada yang merasa aman dari siksaan Allah selain orang-orang yang rugi"},{id:100,text:"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0647\u06e1\u062f\u0650 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0631\u0650\u062b\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0623\u064e\u0647\u06e1\u0644\u0650\u0647\u064e\u0627\u0653 \u0623\u064e\u0646 \u0644\u0651\u064e\u0648\u06e1 \u0646\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0623\u064e\u0635\u064e\u0628\u06e1\u0646\u064e\u0670\u0647\u064f\u0645 \u0628\u0650\u0630\u064f\u0646\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u06e1\u06da \u0648\u064e\u0646\u064e\u0637\u06e1\u0628\u064e\u0639\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u06e1 \u0641\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u0645\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Atau apakah belum jelas bagi orang-orang yang mewarisi suatu negeri setelah (lenyap) penduduknya? Bahwa kalau Kami menghendaki pasti Kami siksa mereka karena dengan dosa-dosanya; dan Kami mengunci hati mereka sehingga mereka tidak dapat mendengar (pelajaran)"},{id:101,text:"\u062a\u0650\u0644\u06e1\u0643\u064e \u0671\u0644\u06e1\u0642\u064f\u0631\u064e\u0649\u0670 \u0646\u064e\u0642\u064f\u0635\u0651\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0645\u0650\u0646\u06e1 \u0623\u064e\u0646\u06e2\u0628\u064e\u0627\u0653\u0626\u0650\u0647\u064e\u0627\u06da \u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u062a\u06e1\u0647\u064f\u0645\u06e1 \u0631\u064f\u0633\u064f\u0644\u064f\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0650 \u0641\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0644\u0650\u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f\u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064e\u0637\u06e1\u0628\u064e\u0639\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064f\u0644\u064f\u0648\u0628\u0650 \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Itulah negeri-negeri (yang telah Kami binasakan), Kami ceritakan sebagian kisahnya kepadamu. Rasul-rasul mereka benar-benar telah datang kepada mereka dengan membawa bukti-bukti yang nyata. Tetapi mereka tidak beriman (juga) kepada apa yang telah mereka dustakan sebelumnya. Demikianlah Allah mengunci hati orang-orang kafir"},{id:102,text:"\u0648\u064e\u0645\u064e\u0627 \u0648\u064e\u062c\u064e\u062f\u06e1\u0646\u064e\u0627 \u0644\u0650\u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u0650\u0647\u0650\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0639\u064e\u0647\u06e1\u062f\u0656\u06d6 \u0648\u064e\u0625\u0650\u0646 \u0648\u064e\u062c\u064e\u062f\u06e1\u0646\u064e\u0627\u0653 \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0641\u064e\u0670\u0633\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Dan Kami tidak mendapati kebanyakan mereka memenuhi janji. Sebaliknya yang Kami dapati kebanyakan mereka adalah orang-orang yang benar-benar fasik"},{id:103,text:"\u062b\u064f\u0645\u0651\u064e \u0628\u064e\u0639\u064e\u062b\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u0647\u0650\u0645 \u0645\u0651\u064f\u0648\u0633\u064e\u0649\u0670 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0648\u064e\u0645\u064e\u0644\u064e\u0625\u0650\u064a\u0652\u0647\u0650\u06e6 \u0641\u064e\u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u064e\u0627\u06d6 \u0641\u064e\u0671\u0646\u0638\u064f\u0631\u06e1 \u0643\u064e\u064a\u06e1\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0670\u0642\u0650\u0628\u064e\u0629\u064f \u0671\u0644\u06e1\u0645\u064f\u0641\u06e1\u0633\u0650\u062f\u0650\u064a\u0646\u064e",translation:"Setelah mereka, kemudian Kami utus Musa dengan membawa bukti-bukti Kami kepada Fir'aun dan pemuka-pemuka kaumnya, lalu mereka mengingkari bukti-bukti itu. Maka perhatikanlah bagaimana kesudahan orang-orang yang berbuat kerusakan"},{id:104,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u064a\u064e\u0670\u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064f \u0625\u0650\u0646\u0651\u0650\u064a \u0631\u064e\u0633\u064f\u0648\u0644\u065e \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Dan Musa berkata, \"Wahai Fir'aun! Sungguh, aku adalah seorang utusan dari Tuhan seluruh alam"},{id:105,text:"\u062d\u064e\u0642\u0650\u064a\u0642\u064c \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0646 \u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0642\u064f\u0648\u0644\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064e\u06da \u0642\u064e\u062f\u06e1 \u062c\u0650\u0626\u06e1\u062a\u064f\u0643\u064f\u0645 \u0628\u0650\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0629\u0656 \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1 \u0641\u064e\u0623\u064e\u0631\u06e1\u0633\u0650\u0644\u06e1 \u0645\u064e\u0639\u0650\u064a\u064e \u0628\u064e\u0646\u0650\u064a\u0653 \u0625\u0650\u0633\u06e1\u0631\u064e\u0640\u0670\u0653\u0621\u0650\u064a\u0644\u064e",translation:"aku wajib mengatakan yang sebenarnya tentang Allah. Sungguh, aku datang kepadamu dengan membawa bukti yang nyata dari Tuhanmu, maka lepaskanlah Bani Israil (pergi) bersamaku"},{id:106,text:"\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064e \u062c\u0650\u0626\u06e1\u062a\u064e \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0629\u0656 \u0641\u064e\u0623\u06e1\u062a\u0650 \u0628\u0650\u0647\u064e\u0627\u0653 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Dia (Fir'aun) menjawab, \"Jika benar engkau membawa sesuatu bukti, maka tunjukkanlah, kalau kamu termasuk orang-orang yang benar"},{id:107,text:"\u0641\u064e\u0623\u064e\u0644\u06e1\u0642\u064e\u0649\u0670 \u0639\u064e\u0635\u064e\u0627\u0647\u064f \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0647\u0650\u064a\u064e \u062b\u064f\u0639\u06e1\u0628\u064e\u0627\u0646\u065e \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u065e",translation:"Lalu (Musa) melemparkan tongkatnya, tiba-tiba tongkat itu menjadi ular yang sebenarnya"},{id:108,text:"\u0648\u064e\u0646\u064e\u0632\u064e\u0639\u064e \u064a\u064e\u062f\u064e\u0647\u064f\u06e5 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0647\u0650\u064a\u064e \u0628\u064e\u064a\u06e1\u0636\u064e\u0627\u0653\u0621\u064f \u0644\u0650\u0644\u0646\u0651\u064e\u0640\u0670\u0638\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan dia mengeluarkan tangannya, tiba-tiba tangan itu menjadi putih (bercahaya) bagi orang-orang yang melihatnya"},{id:109,text:"\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0623\u064f \u0645\u0650\u0646 \u0642\u064e\u0648\u06e1\u0645\u0650 \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0644\u064e\u0633\u064e\u0670\u062d\u0650\u0631\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Pemuka-pemuka kaum Fir'aun berkata, \"Orang ini benar-benar pesihir yang pandai"},{id:110,text:"\u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0623\u064e\u0646 \u064a\u064f\u062e\u06e1\u0631\u0650\u062c\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u0631\u06e1\u0636\u0650\u0643\u064f\u0645\u06e1\u06d6 \u0641\u064e\u0645\u064e\u0627\u0630\u064e\u0627 \u062a\u064e\u0623\u06e1\u0645\u064f\u0631\u064f\u0648\u0646\u064e",translation:"yang hendak mengusir kamu dari negerimu.\" (Fir'aun berkata), \"Maka apa saran kamu"},{id:111,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0631\u06e1\u062c\u0650\u0647\u06e1 \u0648\u064e\u0623\u064e\u062e\u064e\u0627\u0647\u064f \u0648\u064e\u0623\u064e\u0631\u06e1\u0633\u0650\u0644\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0645\u064e\u062f\u064e\u0627\u0653\u0626\u0650\u0646\u0650 \u062d\u064e\u0670\u0634\u0650\u0631\u0650\u064a\u0646\u064e",translation:"(Pemuka-pemuka) itu menjawab, \"Tahanlah (untuk sementara) dia dan saudaranya dan utuslah ke kota-kota beberapa orang untuk mengumpulkan (para pesihir)"},{id:112,text:"\u064a\u064e\u0623\u06e1\u062a\u064f\u0648\u0643\u064e \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0633\u064e\u0670\u062d\u0650\u0631\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u0656",translation:"agar mereka membawa semua pesihir yang pandai kepadamu"},{id:113,text:"\u0648\u064e\u062c\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0633\u0651\u064e\u062d\u064e\u0631\u064e\u0629\u064f \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e \u0644\u064e\u0646\u064e\u0627 \u0644\u064e\u0623\u064e\u062c\u06e1\u0631\u064b\u0627 \u0625\u0650\u0646 \u0643\u064f\u0646\u0651\u064e\u0627 \u0646\u064e\u062d\u06e1\u0646\u064f \u0671\u0644\u06e1\u063a\u064e\u0670\u0644\u0650\u0628\u0650\u064a\u0646\u064e",translation:"Dan para pesihir datang kepada Fir'aun. Mereka berkata, \"(Apakah) kami akan mendapat imbalan, jika kami menang"},{id:114,text:"\u0642\u064e\u0627\u0644\u064e \u0646\u064e\u0639\u064e\u0645\u06e1 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0644\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0642\u064e\u0631\u0651\u064e\u0628\u0650\u064a\u0646\u064e",translation:"Dia (Fir'aun) menjawab, \"Ya, bahkan kamu pasti termasuk orang-orang yang dekat (kepadaku)"},{id:115,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u064a\u064e\u0670\u0645\u064f\u0648\u0633\u064e\u0649\u0670\u0653 \u0625\u0650\u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u062a\u064f\u0644\u06e1\u0642\u0650\u064a\u064e \u0648\u064e\u0625\u0650\u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u0646\u0651\u064e\u0643\u064f\u0648\u0646\u064e \u0646\u064e\u062d\u06e1\u0646\u064f \u0671\u0644\u06e1\u0645\u064f\u0644\u06e1\u0642\u0650\u064a\u0646\u064e",translation:"Mereka (para pesihir) berkata, \"Wahai Musa! Engkaukah yang akan melemparkan lebih dahulu, atau kami yang melemparkan"},{id:116,text:"\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0644\u06e1\u0642\u064f\u0648\u0627\u0652\u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u0644\u06e1\u0642\u064e\u0648\u06e1\u0627\u0652 \u0633\u064e\u062d\u064e\u0631\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0639\u06e1\u064a\u064f\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0671\u0633\u06e1\u062a\u064e\u0631\u06e1\u0647\u064e\u0628\u064f\u0648\u0647\u064f\u0645\u06e1 \u0648\u064e\u062c\u064e\u0627\u0653\u0621\u064f\u0648 \u0628\u0650\u0633\u0650\u062d\u06e1\u0631\u064d \u0639\u064e\u0638\u0650\u064a\u0645\u0656",translation:"Dia (Musa) menjawab, \"Lemparkanlah (lebih dahulu)!\" Maka setelah mereka melemparkan, mereka menyihir mata orang banyak dan menjadikan orang banyak itu takut, karena mereka memperlihatkan sihir yang hebat (menakjubkan)"},{id:117,text:"\u06de\u0648\u064e\u0623\u064e\u0648\u06e1\u062d\u064e\u064a\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064f\u0648\u0633\u064e\u0649\u0670\u0653 \u0623\u064e\u0646\u06e1 \u0623\u064e\u0644\u06e1\u0642\u0650 \u0639\u064e\u0635\u064e\u0627\u0643\u064e\u06d6 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0647\u0650\u064a\u064e \u062a\u064e\u0644\u06e1\u0642\u064e\u0641\u064f \u0645\u064e\u0627 \u064a\u064e\u0623\u06e1\u0641\u0650\u0643\u064f\u0648\u0646\u064e",translation:"Dan Kami wahyukan kepada Musa, \"Lemparkanlah tongkatmu!\" Maka tiba-tiba ia menelan (habis) segala kepalsuan mereka"},{id:118,text:"\u0641\u064e\u0648\u064e\u0642\u064e\u0639\u064e \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f \u0648\u064e\u0628\u064e\u0637\u064e\u0644\u064e \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Maka terbuktilah kebenaran, dan segala yang mereka kerjakan jadi sia-sia"},{id:119,text:"\u0641\u064e\u063a\u064f\u0644\u0650\u0628\u064f\u0648\u0627\u0652 \u0647\u064f\u0646\u064e\u0627\u0644\u0650\u0643\u064e \u0648\u064e\u0671\u0646\u0642\u064e\u0644\u064e\u0628\u064f\u0648\u0627\u0652 \u0635\u064e\u0670\u063a\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Maka mereka dikalahkan di tempat itu dan jadilah mereka orang-orang yang hina"},{id:120,text:"\u0648\u064e\u0623\u064f\u0644\u06e1\u0642\u0650\u064a\u064e \u0671\u0644\u0633\u0651\u064e\u062d\u064e\u0631\u064e\u0629\u064f \u0633\u064e\u0670\u062c\u0650\u062f\u0650\u064a\u0646\u064e",translation:"Dan para pesihir itu serta merta menjatuhkan diri dengan bersujud"},{id:121,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0621\u064e\u0627\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0631\u064e\u0628\u0651\u0650 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"mereka berkata, \"Kami beriman kepada Tuhan seluruh alam"},{id:122,text:"\u0631\u064e\u0628\u0651\u0650 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u0647\u064e\u0670\u0631\u064f\u0648\u0646\u064e",translation:"(yaitu) Tuhannya Musa dan Harun"},{id:123,text:"\u0642\u064e\u0627\u0644\u064e \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064f \u0621\u064e\u0627\u0645\u064e\u0646\u062a\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6 \u0642\u064e\u0628\u06e1\u0644\u064e \u0623\u064e\u0646\u06e1 \u0621\u064e\u0627\u0630\u064e\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u06e1\u06d6 \u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0644\u064e\u0645\u064e\u0643\u06e1\u0631\u065e \u0645\u0651\u064e\u0643\u064e\u0631\u06e1\u062a\u064f\u0645\u064f\u0648\u0647\u064f \u0641\u0650\u064a \u0671\u0644\u06e1\u0645\u064e\u062f\u0650\u064a\u0646\u064e\u0629\u0650 \u0644\u0650\u062a\u064f\u062e\u06e1\u0631\u0650\u062c\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1\u0647\u064e\u0627\u0653 \u0623\u064e\u0647\u06e1\u0644\u064e\u0647\u064e\u0627\u06d6 \u0641\u064e\u0633\u064e\u0648\u06e1\u0641\u064e \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Fir'aun berkata, \"Mengapa kamu beriman kepadanya sebelum aku memberi izin kepadamu? Sesungguhnya ini benar-benar tipu muslihat yang telah kamu rencanakan di kota ini, untuk mengusir penduduknya. Kelak kamu akan mengetahui (akibat perbuatanmu ini)"},{id:124,text:"\u0644\u064e\u0623\u064f\u0642\u064e\u0637\u0651\u0650\u0639\u064e\u0646\u0651\u064e \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0631\u06e1\u062c\u064f\u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u062e\u0650\u0644\u064e\u0670\u0641\u0656 \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0623\u064f\u0635\u064e\u0644\u0651\u0650\u0628\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u062c\u06e1\u0645\u064e\u0639\u0650\u064a\u0646\u064e",translation:"Pasti akan aku potong tangan dan kakimu dengan bersilang (tangan kanan dan kaki kiri atau sebaliknya), kemudian aku akan menyalib kamu semua"},{id:125,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627 \u0645\u064f\u0646\u0642\u064e\u0644\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Mereka (para pesihir) menjawab, \"Sesungguhnya kami akan kembali kepada Tuhan kami"},{id:126,text:"\u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0646\u0642\u0650\u0645\u064f \u0645\u0650\u0646\u0651\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646\u06e1 \u0621\u064e\u0627\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627 \u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u062a\u06e1\u0646\u064e\u0627\u06da \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627\u0653 \u0623\u064e\u0641\u06e1\u0631\u0650\u063a\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0635\u064e\u0628\u06e1\u0631\u0657\u0627 \u0648\u064e\u062a\u064e\u0648\u064e\u0641\u0651\u064e\u0646\u064e\u0627 \u0645\u064f\u0633\u06e1\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"dan engkau tidak melakukan balas dendam kepada kami, melainkan karena kami beriman kepada ayat-ayat Tuhan kami ketika ayat-ayat itu datang kepada kami.\" (Mereka berdoa), \"Ya Tuhan kami, limpahkanlah kesabaran kepada kami dan matikanlah kami dalam keadaan muslim (berserah diri kepada-Mu)"},{id:127,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0623\u064f \u0645\u0650\u0646 \u0642\u064e\u0648\u06e1\u0645\u0650 \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0623\u064e\u062a\u064e\u0630\u064e\u0631\u064f \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u0642\u064e\u0648\u06e1\u0645\u064e\u0647\u064f\u06e5 \u0644\u0650\u064a\u064f\u0641\u06e1\u0633\u0650\u062f\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u064a\u064e\u0630\u064e\u0631\u064e\u0643\u064e \u0648\u064e\u0621\u064e\u0627\u0644\u0650\u0647\u064e\u062a\u064e\u0643\u064e\u06da \u0642\u064e\u0627\u0644\u064e \u0633\u064e\u0646\u064f\u0642\u064e\u062a\u0651\u0650\u0644\u064f \u0623\u064e\u0628\u06e1\u0646\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0646\u064e\u0633\u06e1\u062a\u064e\u062d\u06e1\u064a\u0650\u06e6 \u0646\u0650\u0633\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0641\u064e\u0648\u06e1\u0642\u064e\u0647\u064f\u0645\u06e1 \u0642\u064e\u0670\u0647\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Dan para pemuka dari kaum Fir'aun berkata, \"Apakah engkau akan membiarkan Musa dan kaumnya untuk berbuat kerusakan di negeri ini (Mesir) dan meninggalkanmu dan tuhan-tuhanmu?\" (Fir'aun) menjawab, \"Akan kita bunuh anak-anak laki-laki mereka dan kita biarkan hidup anak-anak perempuan mereka dan sesungguhnya kita berkuasa penuh atas mereka"},{id:128,text:"\u0642\u064e\u0627\u0644\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0644\u0650\u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650 \u0671\u0633\u06e1\u062a\u064e\u0639\u0650\u064a\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0671\u0635\u06e1\u0628\u0650\u0631\u064f\u0648\u0653\u0627\u0652\u06d6 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u064a\u064f\u0648\u0631\u0650\u062b\u064f\u0647\u064e\u0627 \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0645\u0650\u0646\u06e1 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u0671\u0644\u06e1\u0639\u064e\u0670\u0642\u0650\u0628\u064e\u0629\u064f \u0644\u0650\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",translation:"Musa berkata kepada kaumnya, \"Mohonlah pertolongan kepada Allah dan bersabarlah. Sesungguhnya bumi (ini) milik Allah; diwariskan-Nya kepada siapa saja yang Dia kehendaki di antara hamba-hamba-Nya. Dan kesudahan (yang baik) adalah bagi orang-orang yang bertakwa"},{id:129,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064f\u0648\u0630\u0650\u064a\u0646\u064e\u0627 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650 \u0623\u064e\u0646 \u062a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e\u0646\u064e\u0627 \u0648\u064e\u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0645\u064e\u0627 \u062c\u0650\u0626\u06e1\u062a\u064e\u0646\u064e\u0627\u06da \u0642\u064e\u0627\u0644\u064e \u0639\u064e\u0633\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u06e1 \u0623\u064e\u0646 \u064a\u064f\u0647\u06e1\u0644\u0650\u0643\u064e \u0639\u064e\u062f\u064f\u0648\u0651\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u064a\u064e\u0633\u06e1\u062a\u064e\u062e\u06e1\u0644\u0650\u0641\u064e\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0641\u064e\u064a\u064e\u0646\u0638\u064f\u0631\u064e \u0643\u064e\u064a\u06e1\u0641\u064e \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Mereka (kaum Musa) berkata, \"Kami telah ditindas (oleh Fir'aun) sebelum engkau datang kepada kami dan setelah engkau datang.\" (Musa) menjawab, \"Mudah-mudahan Tuhanmu membinasakan musuhmu dan menjadikan kamu khalifah di bumi; maka Dia akan melihat bagaimana perbuatanmu"},{id:130,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u062e\u064e\u0630\u06e1\u0646\u064e\u0627\u0653 \u0621\u064e\u0627\u0644\u064e \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0628\u0650\u0671\u0644\u0633\u0651\u0650\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0646\u064e\u0642\u06e1\u0635\u0656 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u062b\u0651\u064e\u0645\u064e\u0631\u064e\u0670\u062a\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0630\u0651\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan sungguh, Kami telah menghukum Fir'aun dan kaumnya dengan (mendatangkan musim kemarau) bertahun-tahun dan kekurangan buah-buahan, agar mereka mengambil pelajaran"},{id:131,text:"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u062a\u06e1\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u062d\u064e\u0633\u064e\u0646\u064e\u0629\u064f \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0646\u064e\u0627 \u0647\u064e\u0670\u0630\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u0625\u0650\u0646 \u062a\u064f\u0635\u0650\u0628\u06e1\u0647\u064f\u0645\u06e1 \u0633\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u065e \u064a\u064e\u0637\u0651\u064e\u064a\u0651\u064e\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u0645\u064e\u0646 \u0645\u0651\u064e\u0639\u064e\u0647\u064f\u06e5\u0653\u06d7 \u0623\u064e\u0644\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0637\u064e\u0640\u0670\u0653\u0626\u0650\u0631\u064f\u0647\u064f\u0645\u06e1 \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Kemudian apabila kebaikan (kemakmuran) datang kepada mereka, mereka berkata, \"Ini adalah karena (usaha) kami.\" Dan jika mereka ditimpa kesusahan, mereka lemparkan sebab kesialan itu kepada Musa dan pengikutnya. Ketahuilah, sesungguhnya nasib mereka di tangan Allah, namun kebanyakan mereka tidak mengetahui"},{id:132,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0645\u064e\u0647\u06e1\u0645\u064e\u0627 \u062a\u064e\u0623\u06e1\u062a\u0650\u0646\u064e\u0627 \u0628\u0650\u0647\u0650\u06e6 \u0645\u0650\u0646\u06e1 \u0621\u064e\u0627\u064a\u064e\u0629\u0656 \u0644\u0651\u0650\u062a\u064e\u0633\u06e1\u062d\u064e\u0631\u064e\u0646\u064e\u0627 \u0628\u0650\u0647\u064e\u0627 \u0641\u064e\u0645\u064e\u0627 \u0646\u064e\u062d\u06e1\u0646\u064f \u0644\u064e\u0643\u064e \u0628\u0650\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dan mereka berkata (kepada Musa), \"Bukti apa pun yang engkau bawa kepada kami untuk menyihir kami, kami tidak akan beriman kepadamu"},{id:133,text:"\u0641\u064e\u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u064f \u0671\u0644\u0637\u0651\u064f\u0648\u0641\u064e\u0627\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u062c\u064e\u0631\u064e\u0627\u062f\u064e \u0648\u064e\u0671\u0644\u06e1\u0642\u064f\u0645\u0651\u064e\u0644\u064e \u0648\u064e\u0671\u0644\u0636\u0651\u064e\u0641\u064e\u0627\u062f\u0650\u0639\u064e \u0648\u064e\u0671\u0644\u062f\u0651\u064e\u0645\u064e \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0656 \u0645\u0651\u064f\u0641\u064e\u0635\u0651\u064e\u0644\u064e\u0670\u062a\u0656 \u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u064e\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0642\u064e\u0648\u06e1\u0645\u0657\u0627 \u0645\u0651\u064f\u062c\u06e1\u0631\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Maka Kami kirimkan kepada mereka topan, belalang, kutu, katak dan darah (air minum berubah menjadi darah) sebagai bukti-bukti yang jelas, tetapi mereka tetap menyombongkan diri dan mereka adalah kaum yang berdosa"},{id:134,text:"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0648\u064e\u0642\u064e\u0639\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u064f \u0671\u0644\u0631\u0651\u0650\u062c\u06e1\u0632\u064f \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u064a\u064e\u0670\u0645\u064f\u0648\u0633\u064e\u0649 \u0671\u062f\u06e1\u0639\u064f \u0644\u064e\u0646\u064e\u0627 \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0628\u0650\u0645\u064e\u0627 \u0639\u064e\u0647\u0650\u062f\u064e \u0639\u0650\u0646\u062f\u064e\u0643\u064e\u06d6 \u0644\u064e\u0626\u0650\u0646 \u0643\u064e\u0634\u064e\u0641\u06e1\u062a\u064e \u0639\u064e\u0646\u0651\u064e\u0627 \u0671\u0644\u0631\u0651\u0650\u062c\u06e1\u0632\u064e \u0644\u064e\u0646\u064f\u0624\u06e1\u0645\u0650\u0646\u064e\u0646\u0651\u064e \u0644\u064e\u0643\u064e \u0648\u064e\u0644\u064e\u0646\u064f\u0631\u06e1\u0633\u0650\u0644\u064e\u0646\u0651\u064e \u0645\u064e\u0639\u064e\u0643\u064e \u0628\u064e\u0646\u0650\u064a\u0653 \u0625\u0650\u0633\u06e1\u0631\u064e\u0640\u0670\u0653\u0621\u0650\u064a\u0644\u064e",translation:"Dan ketika mereka ditimpa azab (yang telah diterangkan itu) mereka pun berkata, \"Wahai Musa! Mohonkanlah untuk kami kepada Tuhanmu sesuai dengan janji-Nya kepadamu. Jika engkau dapat menghilangkan azab itu dari kami, niscaya kami akan beriman kepadamu dan pasti akan kami biarkan Bani Israil pergi bersamamu"},{id:135,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0643\u064e\u0634\u064e\u0641\u06e1\u0646\u064e\u0627 \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u064f \u0671\u0644\u0631\u0651\u0650\u062c\u06e1\u0632\u064e \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u062c\u064e\u0644\u064d \u0647\u064f\u0645 \u0628\u064e\u0670\u0644\u0650\u063a\u064f\u0648\u0647\u064f \u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0645\u06e1 \u064a\u064e\u0646\u0643\u064f\u062b\u064f\u0648\u0646\u064e",translation:"Tetapi setelah Kami hilangkan azab itu dari mereka hingga batas waktu yang harus mereka penuhi ternyata mereka ingkar janji"},{id:136,text:"\u0641\u064e\u0671\u0646\u062a\u064e\u0642\u064e\u0645\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0641\u064e\u0623\u064e\u063a\u06e1\u0631\u064e\u0642\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u064a\u064e\u0645\u0651\u0650 \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0639\u064e\u0646\u06e1\u0647\u064e\u0627 \u063a\u064e\u0670\u0641\u0650\u0644\u0650\u064a\u0646\u064e",translation:"Maka Kami hukum sebagian di antara mereka, lalu Kami tenggelamkan mereka di laut karena mereka telah mendustakan ayat-ayat Kami dan melalaikan ayat-ayat Kami"},{id:137,text:"\u0648\u064e\u0623\u064e\u0648\u06e1\u0631\u064e\u062b\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064f\u0633\u06e1\u062a\u064e\u0636\u06e1\u0639\u064e\u0641\u064f\u0648\u0646\u064e \u0645\u064e\u0634\u064e\u0670\u0631\u0650\u0642\u064e \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0645\u064e\u063a\u064e\u0670\u0631\u0650\u0628\u064e\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u062a\u0650\u064a \u0628\u064e\u0670\u0631\u064e\u0643\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627\u06d6 \u0648\u064e\u062a\u064e\u0645\u0651\u064e\u062a\u06e1 \u0643\u064e\u0644\u0650\u0645\u064e\u062a\u064f \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0671\u0644\u06e1\u062d\u064f\u0633\u06e1\u0646\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0646\u0650\u064a\u0653 \u0625\u0650\u0633\u06e1\u0631\u064e\u0640\u0670\u0653\u0621\u0650\u064a\u0644\u064e \u0628\u0650\u0645\u064e\u0627 \u0635\u064e\u0628\u064e\u0631\u064f\u0648\u0627\u0652\u06d6 \u0648\u064e\u062f\u064e\u0645\u0651\u064e\u0631\u06e1\u0646\u064e\u0627 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u064a\u064e\u0635\u06e1\u0646\u064e\u0639\u064f \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064f \u0648\u064e\u0642\u064e\u0648\u06e1\u0645\u064f\u0647\u064f\u06e5 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0631\u0650\u0634\u064f\u0648\u0646\u064e",translation:"(Dan Kami wariskan kepada kaum yang tertindas itu, bumi bagian timur dan bagian baratnya335) yang telah Kami berkahi. Dan telah sempurnalah firman Tuhanmu yang baik itu (sebagai janji) untuk Bani Israil disebabkan kesabaran mereka. Dan Kami hancurkan apa yang telah dibuat Fir'aun dan kaumnya dan apa yang telah mereka bangun"},{id:138,text:"\u0648\u064e\u062c\u064e\u0670\u0648\u064e\u0632\u06e1\u0646\u064e\u0627 \u0628\u0650\u0628\u064e\u0646\u0650\u064a\u0653 \u0625\u0650\u0633\u06e1\u0631\u064e\u0640\u0670\u0653\u0621\u0650\u064a\u0644\u064e \u0671\u0644\u06e1\u0628\u064e\u062d\u06e1\u0631\u064e \u0641\u064e\u0623\u064e\u062a\u064e\u0648\u06e1\u0627\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064e\u0639\u06e1\u0643\u064f\u0641\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0635\u06e1\u0646\u064e\u0627\u0645\u0656 \u0644\u0651\u064e\u0647\u064f\u0645\u06e1\u06da \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u064a\u064e\u0670\u0645\u064f\u0648\u0633\u064e\u0649 \u0671\u062c\u06e1\u0639\u064e\u0644 \u0644\u0651\u064e\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u0657\u0627 \u0643\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0621\u064e\u0627\u0644\u0650\u0647\u064e\u0629\u065e\u06da \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0642\u064e\u0648\u06e1\u0645\u065e \u062a\u064e\u062c\u06e1\u0647\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan Kami selamatkan Bani Israil menyeberangi laut itu (bagian utara dari Laut Merah). Ketika mereka sampai kepada suatu kaum yang tetap menyembah berhala, mereka (Bani israil) berkata, \"Wahai Musa! Buatlah untuk kami satu tuhan (berhala) sebagaimana mereka mempunyai beberapa tuhan (berhala).\" (Musa) menjawab, \"Sungguh, kamu orang-orang yang bodoh"},{id:139,text:"\u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650 \u0645\u064f\u062a\u064e\u0628\u0651\u064e\u0631\u065e \u0645\u0651\u064e\u0627 \u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u0650 \u0648\u064e\u0628\u064e\u0670\u0637\u0650\u0644\u065e \u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Sesungguhnya mereka akan dihancurkan (oleh kepercayaan) yang dianutnya dan akan sia-sia apa yang telah mereka kerjakan"},{id:140,text:"\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u063a\u064e\u064a\u06e1\u0631\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0628\u06e1\u063a\u0650\u064a\u0643\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0670\u0647\u0657\u0627 \u0648\u064e\u0647\u064f\u0648\u064e \u0641\u064e\u0636\u0651\u064e\u0644\u064e\u0643\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Dia (Musa) berkata, \"Pantaskah aku mencari tuhan untukmu selain Allah, padahal Dia yang telah melebihkan kamu atas segala umat (pada masa itu)"},{id:141,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0623\u064e\u0646\u062c\u064e\u064a\u06e1\u0646\u064e\u0670\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0621\u064e\u0627\u0644\u0650 \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u064a\u064e\u0633\u064f\u0648\u0645\u064f\u0648\u0646\u064e\u0643\u064f\u0645\u06e1 \u0633\u064f\u0648\u0653\u0621\u064e \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u064a\u064f\u0642\u064e\u062a\u0651\u0650\u0644\u064f\u0648\u0646\u064e \u0623\u064e\u0628\u06e1\u0646\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u064a\u064e\u0633\u06e1\u062a\u064e\u062d\u06e1\u064a\u064f\u0648\u0646\u064e \u0646\u0650\u0633\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645 \u0628\u064e\u0644\u064e\u0627\u0653\u0621\u065e \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1 \u0639\u064e\u0638\u0650\u064a\u0645\u065e",translation:"Dan (ingatlah Wahai Bani Israil) ketika Kami menyelamatkan kamu dari (Fir'aun) dan kaumnya, yang menyiksa kamu dengan siksaan yang sangat berat, mereka membunuh anak-anak laki-lakimu dan membiarkan hidup anak-anak perempuanmu. Dan itu merupakan cobaan yang besar dari Tuhanmu"},{id:142,text:"\u06de\u0648\u064e\u0648\u064e\u0670\u0639\u064e\u062f\u06e1\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u062b\u064e\u0644\u064e\u0670\u062b\u0650\u064a\u0646\u064e \u0644\u064e\u064a\u06e1\u0644\u064e\u0629\u0657 \u0648\u064e\u0623\u064e\u062a\u06e1\u0645\u064e\u0645\u06e1\u0646\u064e\u0670\u0647\u064e\u0627 \u0628\u0650\u0639\u064e\u0634\u06e1\u0631\u0656 \u0641\u064e\u062a\u064e\u0645\u0651\u064e \u0645\u0650\u064a\u0642\u064e\u0670\u062a\u064f \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0631\u06e1\u0628\u064e\u0639\u0650\u064a\u0646\u064e \u0644\u064e\u064a\u06e1\u0644\u064e\u0629\u0657\u06da \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0644\u0650\u0623\u064e\u062e\u0650\u064a\u0647\u0650 \u0647\u064e\u0670\u0631\u064f\u0648\u0646\u064e \u0671\u062e\u06e1\u0644\u064f\u0641\u06e1\u0646\u0650\u064a \u0641\u0650\u064a \u0642\u064e\u0648\u06e1\u0645\u0650\u064a \u0648\u064e\u0623\u064e\u0635\u06e1\u0644\u0650\u062d\u06e1 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u06e1 \u0633\u064e\u0628\u0650\u064a\u0644\u064e \u0671\u0644\u06e1\u0645\u064f\u0641\u06e1\u0633\u0650\u062f\u0650\u064a\u0646\u064e",translation:"Dan Kami telah menjanjikan kepada Musa (memberikan Taurat) tiga puluh malam, dan Kami sempurnakan jumlah malam itu dengan sepuluh (malam lagi), maka sempurnalah waktu yang telah ditentukan Tuhannya empat puluh malam. Dan Musa berkata kepada saudaranya (yaitu) Harun, \"Gantikanlah aku dalam (memimpin) kaumku, dan perbaikilah (dirimu dan kaummu), dan janganlah engkau mengikuti jalan orang-orang yang berbuat kerusakan"},{id:143,text:"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0644\u0650\u0645\u0650\u064a\u0642\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0648\u064e\u0643\u064e\u0644\u0651\u064e\u0645\u064e\u0647\u064f\u06e5 \u0631\u064e\u0628\u0651\u064f\u0647\u064f\u06e5 \u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0623\u064e\u0631\u0650\u0646\u0650\u064a\u0653 \u0623\u064e\u0646\u0638\u064f\u0631\u06e1 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e\u06da \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0646 \u062a\u064e\u0631\u064e\u0649\u0670\u0646\u0650\u064a \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0650 \u0671\u0646\u0638\u064f\u0631\u06e1 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u062c\u064e\u0628\u064e\u0644\u0650 \u0641\u064e\u0625\u0650\u0646\u0650 \u0671\u0633\u06e1\u062a\u064e\u0642\u064e\u0631\u0651\u064e \u0645\u064e\u0643\u064e\u0627\u0646\u064e\u0647\u064f\u06e5 \u0641\u064e\u0633\u064e\u0648\u06e1\u0641\u064e \u062a\u064e\u0631\u064e\u0649\u0670\u0646\u0650\u064a\u06da \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062a\u064e\u062c\u064e\u0644\u0651\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u064f\u0647\u064f\u06e5 \u0644\u0650\u0644\u06e1\u062c\u064e\u0628\u064e\u0644\u0650 \u062c\u064e\u0639\u064e\u0644\u064e\u0647\u064f\u06e5 \u062f\u064e\u0643\u0651\u0657\u0627 \u0648\u064e\u062e\u064e\u0631\u0651\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0635\u064e\u0639\u0650\u0642\u0657\u0627\u06da \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u0641\u064e\u0627\u0642\u064e \u0642\u064e\u0627\u0644\u064e \u0633\u064f\u0628\u06e1\u062d\u064e\u0670\u0646\u064e\u0643\u064e \u062a\u064f\u0628\u06e1\u062a\u064f \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0648\u064e\u0623\u064e\u0646\u064e\u0627\u06e0 \u0623\u064e\u0648\u0651\u064e\u0644\u064f \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dan ketika Musa datang untuk (munajat) pada waktu yang telah Kami tentukan dan Tuhan telah berfirman (langsung) kepadanya, (Musa) berkata, \"Ya Tuhanku, tampakkanlah (diri-Mu) kepadaku agar aku dapat melihat Engkau.\" (Allah) berfirman, \"Engkau tidak akan (sanggup) melihat-Ku, namun lihatlah ke gunung itu, jika ia tetap di tempatnya (sebagai sediakala) niscaya engkau dapat melihat-Ku.\" Maka ketika Tuhannya menampakkan (keagungan-Nya) kepada gunung itu,337) gunung itu hancur luluh dan Musa pun jatuh pingsan. Setelah Musa sadar, dia berkata, \" Mahasuci Engkau, aku bertobat kepada Engkau dan aku adalah orang yang pertama-tama beriman"},{id:144,text:"\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0670\u0645\u064f\u0648\u0633\u064e\u0649\u0670\u0653 \u0625\u0650\u0646\u0651\u0650\u064a \u0671\u0635\u06e1\u0637\u064e\u0641\u064e\u064a\u06e1\u062a\u064f\u0643\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0628\u0650\u0631\u0650\u0633\u064e\u0670\u0644\u064e\u0670\u062a\u0650\u064a \u0648\u064e\u0628\u0650\u0643\u064e\u0644\u064e\u0670\u0645\u0650\u064a \u0641\u064e\u062e\u064f\u0630\u06e1 \u0645\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u062a\u064f\u0643\u064e \u0648\u064e\u0643\u064f\u0646 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0634\u0651\u064e\u0640\u0670\u0643\u0650\u0631\u0650\u064a\u0646\u064e",translation:"(Allah) berfirman, \"Wahai Musa! Sesungguhnya Aku memilih (melebihkan) engkau dari manusia yang lain (pada masamu) untuk membawa risalah-Ku dan firman-Ku, sebab itu berpegangteguhlah kepada apa yang Aku berikan kepadamu dan hendaklah engkau termasuk orang-orang yang bersyukur"},{id:145,text:"\u0648\u064e\u0643\u064e\u062a\u064e\u0628\u06e1\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u06e5 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0644\u06e1\u0648\u064e\u0627\u062d\u0650 \u0645\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0645\u0651\u064e\u0648\u06e1\u0639\u0650\u0638\u064e\u0629\u0657 \u0648\u064e\u062a\u064e\u0641\u06e1\u0635\u0650\u064a\u0644\u0657\u0627 \u0644\u0651\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0641\u064e\u062e\u064f\u0630\u06e1\u0647\u064e\u0627 \u0628\u0650\u0642\u064f\u0648\u0651\u064e\u0629\u0656 \u0648\u064e\u0623\u06e1\u0645\u064f\u0631\u06e1 \u0642\u064e\u0648\u06e1\u0645\u064e\u0643\u064e \u064a\u064e\u0623\u06e1\u062e\u064f\u0630\u064f\u0648\u0627\u0652 \u0628\u0650\u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u0650\u0647\u064e\u0627\u06da \u0633\u064e\u0623\u064f\u0648\u0652\u0631\u0650\u064a\u0643\u064f\u0645\u06e1 \u062f\u064e\u0627\u0631\u064e \u0671\u0644\u06e1\u0641\u064e\u0670\u0633\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Dan telah Kami tuliskan untuk Musa pada lauh-lauh (Taurat)338) segala sesuatu sebagai pelajaran dan penjelasan untuk segala hal; maka (Kami berfirman), \"Berpegangteguhlah kepadanya dan suruhlah kaummu berpegang kepadanya dan sebaik-baiknya,339) Aku akan memperlihatkan kepadamu negeri orang-orang fasik"},{id:146,text:"\u0633\u064e\u0623\u064e\u0635\u06e1\u0631\u0650\u0641\u064f \u0639\u064e\u0646\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u064a\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062a\u064e\u0643\u064e\u0628\u0651\u064e\u0631\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0628\u0650\u063a\u064e\u064a\u06e1\u0631\u0650 \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0625\u0650\u0646 \u064a\u064e\u0631\u064e\u0648\u06e1\u0627\u0652 \u0643\u064f\u0644\u0651\u064e \u0621\u064e\u0627\u064a\u064e\u0629\u0656 \u0644\u0651\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u064e\u0627 \u0648\u064e\u0625\u0650\u0646 \u064a\u064e\u0631\u064e\u0648\u06e1\u0627\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u064e \u0671\u0644\u0631\u0651\u064f\u0634\u06e1\u062f\u0650 \u0644\u064e\u0627 \u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0647\u064f \u0633\u064e\u0628\u0650\u064a\u0644\u0657\u0627 \u0648\u064e\u0625\u0650\u0646 \u064a\u064e\u0631\u064e\u0648\u06e1\u0627\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u064e \u0671\u0644\u06e1\u063a\u064e\u064a\u0651\u0650 \u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0647\u064f \u0633\u064e\u0628\u0650\u064a\u0644\u0657\u0627\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0639\u064e\u0646\u06e1\u0647\u064e\u0627 \u063a\u064e\u0670\u0641\u0650\u0644\u0650\u064a\u0646\u064e",translation:"Akan Aku palingkan dari tanda-tanda (kekuasaan-Ku) orang-orang yang menyombongkan diri di bumi tanpa alasan yang benar. Kalaupun mereka melihat setiap tanda (kekuasaan-Ku) mereka tetap tidak akan beriman kepadanya. Dan jika mereka melihat jalan yang membawa kepada petunjuk, mereka tidak (akan) menempuhnya, tetapi jika mereka melihat jalan kesesatan, mereka menempuhnya. Yang demikian adalah karena mereka mendustakan ayat-ayat Kami dan mereka selalu lengah terhadapnya"},{id:147,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0648\u064e\u0644\u0650\u0642\u064e\u0627\u0653\u0621\u0650 \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u062d\u064e\u0628\u0650\u0637\u064e\u062a\u06e1 \u0623\u064e\u0639\u06e1\u0645\u064e\u0670\u0644\u064f\u0647\u064f\u0645\u06e1\u06da \u0647\u064e\u0644\u06e1 \u064a\u064f\u062c\u06e1\u0632\u064e\u0648\u06e1\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan orang-orang yang mendustakan tanda-tanda (kekuasaan) Kami dan (mendustakan) adanya pertemuan akhirat, sia-sialah amal mereka. Mereka diberi balasan sesuai dengan apa yang telah mereka kerjakan"},{id:148,text:"\u0648\u064e\u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064e \u0642\u064e\u0648\u06e1\u0645\u064f \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u0647\u0650\u06e6 \u0645\u0650\u0646\u06e1 \u062d\u064f\u0644\u0650\u064a\u0651\u0650\u0647\u0650\u0645\u06e1 \u0639\u0650\u062c\u06e1\u0644\u0657\u0627 \u062c\u064e\u0633\u064e\u062f\u0657\u0627 \u0644\u0651\u064e\u0647\u064f\u06e5 \u062e\u064f\u0648\u064e\u0627\u0631\u064c\u06da \u0623\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0631\u064e\u0648\u06e1\u0627\u0652 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0627 \u064a\u064f\u0643\u064e\u0644\u0651\u0650\u0645\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0647\u06e1\u062f\u0650\u064a\u0647\u0650\u0645\u06e1 \u0633\u064e\u0628\u0650\u064a\u0644\u064b\u0627\u06d8 \u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0647\u064f \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0638\u064e\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dan kaum Musa, setelah kepergian (Musa ke Gunung Sinai) mereka membuat patung anak sapi yang bertubuh dan dapat melenguh (bersuara) dari perhiasan (emas).341) Apakah mereka tidak mengetahui bahwa (patung) anak sapi itu tidak dapat berbicara dengan mereka dan tidak dapat (pula) menunjukkan jalan kepada mereka? Mereka menjadikannya (sebagai sembahan). Mereka adalah orang-orang yang zalim"},{id:149,text:"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0633\u064f\u0642\u0650\u0637\u064e \u0641\u0650\u064a\u0653 \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u0647\u0650\u0645\u06e1 \u0648\u064e\u0631\u064e\u0623\u064e\u0648\u06e1\u0627\u0652 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0642\u064e\u062f\u06e1 \u0636\u064e\u0644\u0651\u064f\u0648\u0627\u0652 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0626\u0650\u0646 \u0644\u0651\u064e\u0645\u06e1 \u064a\u064e\u0631\u06e1\u062d\u064e\u0645\u06e1\u0646\u064e\u0627 \u0631\u064e\u0628\u0651\u064f\u0646\u064e\u0627 \u0648\u064e\u064a\u064e\u063a\u06e1\u0641\u0650\u0631\u06e1 \u0644\u064e\u0646\u064e\u0627 \u0644\u064e\u0646\u064e\u0643\u064f\u0648\u0646\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u062e\u064e\u0670\u0633\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan setelah mereka menyesali perbuatannya dan mengetahui bahwa telah sesat, mereka pun berkata, \"Sungguh, jika Tuhan kami tidak memberi rahmat kepada kami dan tidak mengampuni kami, pastilah kami menjadi orang-orang yang rugi"},{id:150,text:"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0631\u064e\u062c\u064e\u0639\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u06e6 \u063a\u064e\u0636\u06e1\u0628\u064e\u0670\u0646\u064e \u0623\u064e\u0633\u0650\u0641\u0657\u0627 \u0642\u064e\u0627\u0644\u064e \u0628\u0650\u0626\u06e1\u0633\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0641\u06e1\u062a\u064f\u0645\u064f\u0648\u0646\u0650\u064a \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u064a\u0653\u06d6 \u0623\u064e\u0639\u064e\u062c\u0650\u0644\u06e1\u062a\u064f\u0645\u06e1 \u0623\u064e\u0645\u06e1\u0631\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0623\u064e\u0644\u06e1\u0642\u064e\u0649 \u0671\u0644\u06e1\u0623\u064e\u0644\u06e1\u0648\u064e\u0627\u062d\u064e \u0648\u064e\u0623\u064e\u062e\u064e\u0630\u064e \u0628\u0650\u0631\u064e\u0623\u06e1\u0633\u0650 \u0623\u064e\u062e\u0650\u064a\u0647\u0650 \u064a\u064e\u062c\u064f\u0631\u0651\u064f\u0647\u064f\u06e5\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u06da \u0642\u064e\u0627\u0644\u064e \u0671\u0628\u06e1\u0646\u064e \u0623\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u064e \u0671\u0633\u06e1\u062a\u064e\u0636\u06e1\u0639\u064e\u0641\u064f\u0648\u0646\u0650\u064a \u0648\u064e\u0643\u064e\u0627\u062f\u064f\u0648\u0627\u0652 \u064a\u064e\u0642\u06e1\u062a\u064f\u0644\u064f\u0648\u0646\u064e\u0646\u0650\u064a \u0641\u064e\u0644\u064e\u0627 \u062a\u064f\u0634\u06e1\u0645\u0650\u062a\u06e1 \u0628\u0650\u064a\u064e \u0671\u0644\u06e1\u0623\u064e\u0639\u06e1\u062f\u064e\u0627\u0653\u0621\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062c\u06e1\u0639\u064e\u0644\u06e1\u0646\u0650\u064a \u0645\u064e\u0639\u064e \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"(Dan ketika Musa telah kembali kepada kaumnya, dengan marah dan sedih hati dia berkata, \"Alangkah buruknya perbuatan yang kamu kerjakan selama kepergianku! Apakah kamu hendak mendahului janji Tuhanmu?\"342) Musa pun melemparkan lauh-lauh (Taurat) itu dan memegang kepala saudaranya (Harun) sambil menarik ke arahnya. (Harun) berkata, \"Wahai anak ibuku! Kaum ini telah menganggapku lemah dan hampir saja mereka membunuhku, sebab itu janganlah engkau menjadikan musuh-musuh menyoraki melihat kemalanganku, dan janganlah engkau jadikan aku sebagai orang-orang yang zalim"},{id:151,text:"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0671\u063a\u06e1\u0641\u0650\u0631\u06e1 \u0644\u0650\u064a \u0648\u064e\u0644\u0650\u0623\u064e\u062e\u0650\u064a \u0648\u064e\u0623\u064e\u062f\u06e1\u062e\u0650\u0644\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a \u0631\u064e\u062d\u06e1\u0645\u064e\u062a\u0650\u0643\u064e\u06d6 \u0648\u064e\u0623\u064e\u0646\u062a\u064e \u0623\u064e\u0631\u06e1\u062d\u064e\u0645\u064f \u0671\u0644\u0631\u0651\u064e\u0640\u0670\u062d\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dia (Musa) berdoa, \"Ya Tuhanku, ampunilah aku dan saudaraku dan masukkanlah kami ke dalam rahmat Engkau, dan Engkau adalah Maha Penyayang dari semua penyayang"},{id:152,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0639\u0650\u062c\u06e1\u0644\u064e \u0633\u064e\u064a\u064e\u0646\u064e\u0627\u0644\u064f\u0647\u064f\u0645\u06e1 \u063a\u064e\u0636\u064e\u0628\u065e \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0630\u0650\u0644\u0651\u064e\u0629\u065e \u0641\u0650\u064a \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u0650 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627\u06da \u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u062c\u06e1\u0632\u0650\u064a \u0671\u0644\u06e1\u0645\u064f\u0641\u06e1\u062a\u064e\u0631\u0650\u064a\u0646\u064e",translation:"Sesungguhnya orang-orang yang menjadikan (patung) anak sapi (sebagai sembahannya), kelak akan menerima kemurkaan dari Tuhan mereka dan kehinaan dalam kehidupan di dunia. Demikianlah Kami memberi balasan kepada orang-orang yang berbuat kebohongan"},{id:153,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0640\u0654\u064e\u0627\u062a\u0650 \u062b\u064f\u0645\u0651\u064e \u062a\u064e\u0627\u0628\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u0647\u064e\u0627 \u0648\u064e\u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u0647\u064e\u0627 \u0644\u064e\u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u065e",translation:"Dan orang-orang yang telah mengerjakan kejahatan, kemudian bertobat dan beriman niscaya setelah itu Tuhanmu Maha Pengampun, Maha Penyayang"},{id:154,text:"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0633\u064e\u0643\u064e\u062a\u064e \u0639\u064e\u0646 \u0645\u0651\u064f\u0648\u0633\u064e\u0649 \u0671\u0644\u06e1\u063a\u064e\u0636\u064e\u0628\u064f \u0623\u064e\u062e\u064e\u0630\u064e \u0671\u0644\u06e1\u0623\u064e\u0644\u06e1\u0648\u064e\u0627\u062d\u064e\u06d6 \u0648\u064e\u0641\u0650\u064a \u0646\u064f\u0633\u06e1\u062e\u064e\u062a\u0650\u0647\u064e\u0627 \u0647\u064f\u062f\u0657\u0649 \u0648\u064e\u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u065e \u0644\u0651\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645\u06e1 \u0644\u0650\u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u064a\u064e\u0631\u06e1\u0647\u064e\u0628\u064f\u0648\u0646\u064e",translation:"Dan setelah amarah Musa mereda, diambilnya (kembali) lauh-lauh (Taurat) itu, di dalam tulisannya terdapat petunjuk dan rahmat bagi orang-orang yang takut kepada Tuhannya"},{id:155,text:"\u0648\u064e\u0671\u062e\u06e1\u062a\u064e\u0627\u0631\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0642\u064e\u0648\u06e1\u0645\u064e\u0647\u064f\u06e5 \u0633\u064e\u0628\u06e1\u0639\u0650\u064a\u0646\u064e \u0631\u064e\u062c\u064f\u0644\u0657\u0627 \u0644\u0651\u0650\u0645\u0650\u064a\u0642\u064e\u0670\u062a\u0650\u0646\u064e\u0627\u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u062e\u064e\u0630\u064e\u062a\u06e1\u0647\u064f\u0645\u064f \u0671\u0644\u0631\u0651\u064e\u062c\u06e1\u0641\u064e\u0629\u064f \u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0644\u064e\u0648\u06e1 \u0634\u0650\u0626\u06e1\u062a\u064e \u0623\u064e\u0647\u06e1\u0644\u064e\u0643\u06e1\u062a\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f \u0648\u064e\u0625\u0650\u064a\u0651\u064e\u0640\u0670\u064a\u064e\u06d6 \u0623\u064e\u062a\u064f\u0647\u06e1\u0644\u0650\u0643\u064f\u0646\u064e\u0627 \u0628\u0650\u0645\u064e\u0627 \u0641\u064e\u0639\u064e\u0644\u064e \u0671\u0644\u0633\u0651\u064f\u0641\u064e\u0647\u064e\u0627\u0653\u0621\u064f \u0645\u0650\u0646\u0651\u064e\u0627\u0653\u06d6 \u0625\u0650\u0646\u06e1 \u0647\u0650\u064a\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0641\u0650\u062a\u06e1\u0646\u064e\u062a\u064f\u0643\u064e \u062a\u064f\u0636\u0650\u0644\u0651\u064f \u0628\u0650\u0647\u064e\u0627 \u0645\u064e\u0646 \u062a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0648\u064e\u062a\u064e\u0647\u06e1\u062f\u0650\u064a \u0645\u064e\u0646 \u062a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06d6 \u0623\u064e\u0646\u062a\u064e \u0648\u064e\u0644\u0650\u064a\u0651\u064f\u0646\u064e\u0627 \u0641\u064e\u0671\u063a\u06e1\u0641\u0650\u0631\u06e1 \u0644\u064e\u0646\u064e\u0627 \u0648\u064e\u0671\u0631\u06e1\u062d\u064e\u0645\u06e1\u0646\u064e\u0627\u06d6 \u0648\u064e\u0623\u064e\u0646\u062a\u064e \u062e\u064e\u064a\u06e1\u0631\u064f \u0671\u0644\u06e1\u063a\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan Musa memilih tujuh puluh orang dari kaumnya untuk (memohon tobat kepada Kami) pada waktu yang telah Kami tentukan. Ketika mereka ditimpa gempa bumi, Musa berkata, \"Ya Tuhanku, jika Engkau kehendaki, tentulah Engkau binasakan mereka dan aku sebelum ini. Apakah Engkau akan membinasakan kami karena perbuatan orang-orang yang kurang berakal di antara kami? Itu hanyalah cobaan dari-Mu, Engkau sesatkan dengan cobaan itu siapa yang Engkau kehendaki dan Engkau beri petunjuk kepada siapa yang Engkau kehendaki.343) Engkaulah pemimpin kami, maka ampunilah kami dan berilah kami rahmat. Engkaulah Pemberi ampun yang terbaik"},{id:156,text:"\u06de\u0648\u064e\u0671\u0643\u06e1\u062a\u064f\u0628\u06e1 \u0644\u064e\u0646\u064e\u0627 \u0641\u0650\u064a \u0647\u064e\u0670\u0630\u0650\u0647\u0650 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u062d\u064e\u0633\u064e\u0646\u064e\u0629\u0657 \u0648\u064e\u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0625\u0650\u0646\u0651\u064e\u0627 \u0647\u064f\u062f\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e\u06da \u0642\u064e\u0627\u0644\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u0650\u064a\u0653 \u0623\u064f\u0635\u0650\u064a\u0628\u064f \u0628\u0650\u0647\u0650\u06e6 \u0645\u064e\u0646\u06e1 \u0623\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06d6 \u0648\u064e\u0631\u064e\u062d\u06e1\u0645\u064e\u062a\u0650\u064a \u0648\u064e\u0633\u0650\u0639\u064e\u062a\u06e1 \u0643\u064f\u0644\u0651\u064e \u0634\u064e\u064a\u06e1\u0621\u0656\u06da \u0641\u064e\u0633\u064e\u0623\u064e\u0643\u06e1\u062a\u064f\u0628\u064f\u0647\u064e\u0627 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e \u0648\u064e\u064a\u064f\u0624\u06e1\u062a\u064f\u0648\u0646\u064e \u0671\u0644\u0632\u0651\u064e\u0643\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Dan tetapkanlah untuk kami kebaikan di dunia ini dan di akhirat. Sungguh, kami kembali (bertobat) kepada Engkau. (Allah) berfirman, \"Siksa-Ku akan Aku timpakan kepada siapa yang Aku kehendaki dan rahmat-Ku meliputi segala sesuatu. Maka akan Aku tetapkan rahmat-Ku bagi orang-orang yang bertakwa, yang menunaikan zakat dan orang-orang yang beriman kepada ayat-ayat Kami"},{id:157,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0646\u064e \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e \u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064e \u0671\u0644\u06e1\u0623\u064f\u0645\u0651\u0650\u064a\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064e\u062c\u0650\u062f\u064f\u0648\u0646\u064e\u0647\u064f\u06e5 \u0645\u064e\u0643\u06e1\u062a\u064f\u0648\u0628\u064b\u0627 \u0639\u0650\u0646\u062f\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u062a\u0651\u064e\u0648\u06e1\u0631\u064e\u0649\u0670\u0629\u0650 \u0648\u064e\u0671\u0644\u06e1\u0625\u0650\u0646\u062c\u0650\u064a\u0644\u0650 \u064a\u064e\u0623\u06e1\u0645\u064f\u0631\u064f\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0645\u064e\u0639\u06e1\u0631\u064f\u0648\u0641\u0650 \u0648\u064e\u064a\u064e\u0646\u06e1\u0647\u064e\u0649\u0670\u0647\u064f\u0645\u06e1 \u0639\u064e\u0646\u0650 \u0671\u0644\u06e1\u0645\u064f\u0646\u0643\u064e\u0631\u0650 \u0648\u064e\u064a\u064f\u062d\u0650\u0644\u0651\u064f \u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0637\u0651\u064e\u064a\u0651\u0650\u0628\u064e\u0670\u062a\u0650 \u0648\u064e\u064a\u064f\u062d\u064e\u0631\u0651\u0650\u0645\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u064f \u0671\u0644\u06e1\u062e\u064e\u0628\u064e\u0640\u0670\u0653\u0626\u0650\u062b\u064e \u0648\u064e\u064a\u064e\u0636\u064e\u0639\u064f \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0625\u0650\u0635\u06e1\u0631\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u063a\u06e1\u0644\u064e\u0670\u0644\u064e \u0671\u0644\u0651\u064e\u062a\u0650\u064a \u0643\u064e\u0627\u0646\u064e\u062a\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1\u06da \u0641\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6 \u0648\u064e\u0639\u064e\u0632\u0651\u064e\u0631\u064f\u0648\u0647\u064f \u0648\u064e\u0646\u064e\u0635\u064e\u0631\u064f\u0648\u0647\u064f \u0648\u064e\u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0627\u0652 \u0671\u0644\u0646\u0651\u064f\u0648\u0631\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0645\u064e\u0639\u064e\u0647\u064f\u06e5\u0653 \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064f\u0641\u06e1\u0644\u0650\u062d\u064f\u0648\u0646\u064e",translation:"(Yaitu) orang-orang yang mengikuti Rasul, Nabi yang ummi (tidak bisa baca tulis) yang (namanya) mereka dapati tertulis di dalam Taurat dan Injil yang ada pada mereka, yang menyuruh mereka berbuat yang makruf dan mencegah dari yang mungkar, dan yang menghalalkan segala yang baik bagi mereka dan mengharamkan segala yang buruk bagi mereka, dan membebaskan beban-beban dan belenggu-belenggu yang ada pada mereka.344) Adapun orang-orang yang beriman kepadanya, memuliakannya, menolongnya dan mengikuti cahaya yang terang yang diturunkan kepadanya (Alquran), mereka itulah orang-orang yang beruntung"},{id:158,text:"\u0642\u064f\u0644\u06e1 \u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0625\u0650\u0646\u0651\u0650\u064a \u0631\u064e\u0633\u064f\u0648\u0644\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0644\u064e\u0647\u064f\u06e5 \u0645\u064f\u0644\u06e1\u0643\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d6 \u0644\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u064a\u064f\u062d\u06e1\u064a\u0650\u06e6 \u0648\u064e\u064a\u064f\u0645\u0650\u064a\u062a\u064f\u06d6 \u0641\u064e\u0640\u0654\u064e\u0627\u0645\u0650\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650 \u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650 \u0671\u0644\u06e1\u0623\u064f\u0645\u0651\u0650\u064a\u0651\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0643\u064e\u0644\u0650\u0645\u064e\u0670\u062a\u0650\u0647\u0650\u06e6 \u0648\u064e\u0671\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0647\u064f \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u0647\u06e1\u062a\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Katakanlah (Muhammad), \"Wahai manusia! Sesungguhnya aku ini utusan Allah bagi kamu semua, Yang memiliki kerajaan langit dan bumi; tidak ada tuhan (yang berhak disembah) selain Dia, Yang menghidupkan dan mematikan, maka berimanlah kamu kepada Allah dan Rasul-Nya, (yaitu) Nabi yang ummi yang beriman kepada Allah dan kepada kalimat-kalimat-Nya (kitab-kitab-Nya). Ikutilah dia, agar kamu mendapat petunjuk"},{id:159,text:"\u0648\u064e\u0645\u0650\u0646 \u0642\u064e\u0648\u06e1\u0645\u0650 \u0645\u064f\u0648\u0633\u064e\u0649\u0670\u0653 \u0623\u064f\u0645\u0651\u064e\u0629\u065e \u064a\u064e\u0647\u06e1\u062f\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0628\u0650\u0647\u0650\u06e6 \u064a\u064e\u0639\u06e1\u062f\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Dan di antara kaum Musa itu terdapat suatu umat yang memberi petunjuk (kepada manusia) dengan (dasar) kebenaran dan dengan itu (pula) mereka berlaku adil"},{id:160,text:"\u0648\u064e\u0642\u064e\u0637\u0651\u064e\u0639\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u064f \u0671\u062b\u06e1\u0646\u064e\u062a\u064e\u064a\u06e1 \u0639\u064e\u0634\u06e1\u0631\u064e\u0629\u064e \u0623\u064e\u0633\u06e1\u0628\u064e\u0627\u0637\u064b\u0627 \u0623\u064f\u0645\u064e\u0645\u0657\u0627\u06da \u0648\u064e\u0623\u064e\u0648\u06e1\u062d\u064e\u064a\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064f\u0648\u0633\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u0650 \u0671\u0633\u06e1\u062a\u064e\u0633\u06e1\u0642\u064e\u0649\u0670\u0647\u064f \u0642\u064e\u0648\u06e1\u0645\u064f\u0647\u064f\u06e5\u0653 \u0623\u064e\u0646\u0650 \u0671\u0636\u06e1\u0631\u0650\u0628 \u0628\u0651\u0650\u0639\u064e\u0635\u064e\u0627\u0643\u064e \u0671\u0644\u06e1\u062d\u064e\u062c\u064e\u0631\u064e\u06d6 \u0641\u064e\u0671\u0646\u06e2\u0628\u064e\u062c\u064e\u0633\u064e\u062a\u06e1 \u0645\u0650\u0646\u06e1\u0647\u064f \u0671\u062b\u06e1\u0646\u064e\u062a\u064e\u0627 \u0639\u064e\u0634\u06e1\u0631\u064e\u0629\u064e \u0639\u064e\u064a\u06e1\u0646\u0657\u0627\u06d6 \u0642\u064e\u062f\u06e1 \u0639\u064e\u0644\u0650\u0645\u064e \u0643\u064f\u0644\u0651\u064f \u0623\u064f\u0646\u064e\u0627\u0633\u0656 \u0645\u0651\u064e\u0634\u06e1\u0631\u064e\u0628\u064e\u0647\u064f\u0645\u06e1\u06da \u0648\u064e\u0638\u064e\u0644\u0651\u064e\u0644\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u064f \u0671\u0644\u06e1\u063a\u064e\u0645\u064e\u0670\u0645\u064e \u0648\u064e\u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u064f \u0671\u0644\u06e1\u0645\u064e\u0646\u0651\u064e \u0648\u064e\u0671\u0644\u0633\u0651\u064e\u0644\u06e1\u0648\u064e\u0649\u0670\u06d6 \u0643\u064f\u0644\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0637\u064e\u064a\u0651\u0650\u0628\u064e\u0670\u062a\u0650 \u0645\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u06e1\u0646\u064e\u0670\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0645\u064e\u0627 \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u0643\u064e\u0627\u0646\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0638\u06e1\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Dan Kami membagi menjadi dua belas suku yang masing-masing berjumlah besar, dan Kami wahyukan kepada Musa ketika kaumnya meminta air kepadanya, \"Pukullah batu itu dengan tongkatmu!\" Maka memancarlah dari (batu) itu dua belas mata air. Setiap suku telah mengetahui tempat minumnya masing-masing. Dan Kami naungi mereka dengan awan dan Kami turunkan kepada mereka mann dan salwa. (Kami berfirman), \"Makanlah yang baik-baik dari rezeki yang telah Kami berikan kepadamu.\" Mereka tidak menzalimi Kami, tetapi merekalah yang selalu menzalimi dirinya sendiri"},{id:161,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0633\u06e1\u0643\u064f\u0646\u064f\u0648\u0627\u0652 \u0647\u064e\u0670\u0630\u0650\u0647\u0650 \u0671\u0644\u06e1\u0642\u064e\u0631\u06e1\u064a\u064e\u0629\u064e \u0648\u064e\u0643\u064f\u0644\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u062d\u064e\u064a\u06e1\u062b\u064f \u0634\u0650\u0626\u06e1\u062a\u064f\u0645\u06e1 \u0648\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627\u0652 \u062d\u0650\u0637\u0651\u064e\u0629\u065e \u0648\u064e\u0671\u062f\u06e1\u062e\u064f\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0628\u064e\u0627\u0628\u064e \u0633\u064f\u062c\u0651\u064e\u062f\u0657\u0627 \u0646\u0651\u064e\u063a\u06e1\u0641\u0650\u0631\u06e1 \u0644\u064e\u0643\u064f\u0645\u06e1 \u062e\u064e\u0637\u0650\u064a\u0653\u0640\u0654\u064e\u0670\u062a\u0650\u0643\u064f\u0645\u06e1\u06da \u0633\u064e\u0646\u064e\u0632\u0650\u064a\u062f\u064f \u0671\u0644\u06e1\u0645\u064f\u062d\u06e1\u0633\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dan (ingatlah), ketika dikatakan kepada mereka (Bani Israil), \"Diamlah di negeri ini (Baitulmaqdis) dan makanlah dari (hasil bumi)nya di mana saja kamu kehendaki.\" Dan katakanlah, \"Bebaskanlah kami dari dosa kami, dan masukilah pintu gerbangnya sambil membungkuk, niscaya Kami ampuni kesalahan-kesalahanmu.\" Kelak akan Kami tambah (pahala) kepada orang-orang yang berbuat baik"},{id:162,text:"\u0641\u064e\u0628\u064e\u062f\u0651\u064e\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0642\u064e\u0648\u06e1\u0644\u064b\u0627 \u063a\u064e\u064a\u06e1\u0631\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0641\u064e\u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0631\u0650\u062c\u06e1\u0632\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0638\u06e1\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Maka orang-orang yang zalim di antara mereka mengganti (perkataan itu) dengan perkataan yang tidak dikatakan kepada mereka,346) maka Kami timpakan kepada mereka azab dari langit disebabkan kezaliman mereka"},{id:163,text:"\u0648\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u06e1\u0647\u064f\u0645\u06e1 \u0639\u064e\u0646\u0650 \u0671\u0644\u06e1\u0642\u064e\u0631\u06e1\u064a\u064e\u0629\u0650 \u0671\u0644\u0651\u064e\u062a\u0650\u064a \u0643\u064e\u0627\u0646\u064e\u062a\u06e1 \u062d\u064e\u0627\u0636\u0650\u0631\u064e\u0629\u064e \u0671\u0644\u06e1\u0628\u064e\u062d\u06e1\u0631\u0650 \u0625\u0650\u0630\u06e1 \u064a\u064e\u0639\u06e1\u062f\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0628\u06e1\u062a\u0650 \u0625\u0650\u0630\u06e1 \u062a\u064e\u0623\u06e1\u062a\u0650\u064a\u0647\u0650\u0645\u06e1 \u062d\u0650\u064a\u062a\u064e\u0627\u0646\u064f\u0647\u064f\u0645\u06e1 \u064a\u064e\u0648\u06e1\u0645\u064e \u0633\u064e\u0628\u06e1\u062a\u0650\u0647\u0650\u0645\u06e1 \u0634\u064f\u0631\u0651\u064e\u0639\u0657\u0627 \u0648\u064e\u064a\u064e\u0648\u06e1\u0645\u064e \u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u0628\u0650\u062a\u064f\u0648\u0646\u064e \u0644\u064e\u0627 \u062a\u064e\u0623\u06e1\u062a\u0650\u064a\u0647\u0650\u0645\u06e1\u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u0628\u06e1\u0644\u064f\u0648\u0647\u064f\u0645 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0641\u06e1\u0633\u064f\u0642\u064f\u0648\u0646\u064e",translation:"(Dan tanyakanlah kepada Bani Israil tentang negeri347) yang terletak di dekat laut ketika mereka melanggar aturan pada hari Sabat,348) (yaitu) ketika datang kepada mereka ikan-ikan (yang berada di sekitar) mereka terapung-apung di permukaan air, padahal pada hari-hari yang bukan Sabat ikan-ikan itu tidak datang kepada mereka. Demikianlah Kami menguji mereka disebabkan mereka berlaku fasik"},{id:164,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e\u062a\u06e1 \u0623\u064f\u0645\u0651\u064e\u0629\u065e \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0644\u0650\u0645\u064e \u062a\u064e\u0639\u0650\u0638\u064f\u0648\u0646\u064e \u0642\u064e\u0648\u06e1\u0645\u064b\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064f\u0647\u06e1\u0644\u0650\u0643\u064f\u0647\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1 \u0645\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064f\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u0657\u0627 \u0634\u064e\u062f\u0650\u064a\u062f\u0657\u0627\u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0645\u064e\u0639\u06e1\u0630\u0650\u0631\u064e\u0629\u064b \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",translation:"Dan (ingatlah) ketika suatu umat di antara mereka berkata, \"Mengapa kamu menasihati kaum yang akan dibinasakan atau diazab Allah dengan azab yang sangat keras?\" Mereka menjawab, \"Agar Kami mempunyai alasan (lepas tanggung jawab) kepada Tuhanmu,349) dan agar mereka bertakwa"},{id:165,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0646\u064e\u0633\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u0630\u064f\u0643\u0651\u0650\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0646\u062c\u064e\u064a\u06e1\u0646\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0646\u06e1\u0647\u064e\u0648\u06e1\u0646\u064e \u0639\u064e\u0646\u0650 \u0671\u0644\u0633\u0651\u064f\u0648\u0653\u0621\u0650 \u0648\u064e\u0623\u064e\u062e\u064e\u0630\u06e1\u0646\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627\u0652 \u0628\u0650\u0639\u064e\u0630\u064e\u0627\u0628\u0650\u06ed \u0628\u064e\u0640\u0654\u0650\u064a\u0633\u0650\u06ed \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0641\u06e1\u0633\u064f\u0642\u064f\u0648\u0646\u064e",translation:"Maka setelah mereka melupakan apa yang diperingatkan kepada mereka, Kami selamatkan orang-orang yang melarang orang yang berbuat jahat dan Kami timpakan kepada orang-orang yang zalim siksaan yang keras, disebabkan mereka selalu berbuat fasik"},{id:166,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0639\u064e\u062a\u064e\u0648\u06e1\u0627\u0652 \u0639\u064e\u0646 \u0645\u0651\u064e\u0627 \u0646\u064f\u0647\u064f\u0648\u0627\u0652 \u0639\u064e\u0646\u06e1\u0647\u064f \u0642\u064f\u0644\u06e1\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u0642\u0650\u0631\u064e\u062f\u064e\u0629\u064b \u062e\u064e\u0670\u0633\u0650\u0640\u0654\u0650\u064a\u0646\u064e",translation:"Maka setelah mereka bersikap sombong terhadap segala apa yang dilarang. Kami katakan kepada mereka, \"Jadilah kamu kera yang hina"},{id:167,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u062a\u064e\u0623\u064e\u0630\u0651\u064e\u0646\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0644\u064e\u064a\u064e\u0628\u06e1\u0639\u064e\u062b\u064e\u0646\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u0645\u064e\u0646 \u064a\u064e\u0633\u064f\u0648\u0645\u064f\u0647\u064f\u0645\u06e1 \u0633\u064f\u0648\u0653\u0621\u064e \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u0650\u06d7 \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0644\u064e\u0633\u064e\u0631\u0650\u064a\u0639\u064f \u0671\u0644\u06e1\u0639\u0650\u0642\u064e\u0627\u0628\u0650 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u065e",translation:"Dan (ingatlah), ketika Tuhanmu memberitahukan, bahwa sungguh, Dia akan mengirim orang-orang yang akan menimpakan azab yang seburuk-buruknya kepada mereka (orang Yahudi) sampai hari Kiamat. Sesungguhnya Tuhanmu sangat cepat siksa-Nya, dan sesungguhnya Dia Maha Pengampun, Maha Penyayang"},{id:168,text:"\u0648\u064e\u0642\u064e\u0637\u0651\u064e\u0639\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0623\u064f\u0645\u064e\u0645\u0657\u0627\u06d6 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u064f \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064f\u0648\u0646\u064e \u0648\u064e\u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u062f\u064f\u0648\u0646\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e\u06d6 \u0648\u064e\u0628\u064e\u0644\u064e\u0648\u06e1\u0646\u064e\u0670\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0633\u064e\u0646\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0640\u0654\u064e\u0627\u062a\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0631\u06e1\u062c\u0650\u0639\u064f\u0648\u0646\u064e",translation:"Dan Kami pecahkan mereka di dunia ini menjadi beberapa golongan; diantaranya ada orang-orang yang saleh dan ada yang tidak demikian. Dan Kami uji mereka dengan (nikmat) yang baik-baik dan (bencana) yang buruk-buruk, agar mereka kembali (kepada kebenaran)"},{id:169,text:"\u0641\u064e\u062e\u064e\u0644\u064e\u0641\u064e \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u0647\u0650\u0645\u06e1 \u062e\u064e\u0644\u06e1\u0641\u065e \u0648\u064e\u0631\u0650\u062b\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u064a\u064e\u0623\u06e1\u062e\u064f\u0630\u064f\u0648\u0646\u064e \u0639\u064e\u0631\u064e\u0636\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u062f\u06e1\u0646\u064e\u0649\u0670 \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0633\u064e\u064a\u064f\u063a\u06e1\u0641\u064e\u0631\u064f \u0644\u064e\u0646\u064e\u0627 \u0648\u064e\u0625\u0650\u0646 \u064a\u064e\u0623\u06e1\u062a\u0650\u0647\u0650\u0645\u06e1 \u0639\u064e\u0631\u064e\u0636\u065e \u0645\u0651\u0650\u062b\u06e1\u0644\u064f\u0647\u064f\u06e5 \u064a\u064e\u0623\u06e1\u062e\u064f\u0630\u064f\u0648\u0647\u064f\u06da \u0623\u064e\u0644\u064e\u0645\u06e1 \u064a\u064f\u0624\u06e1\u062e\u064e\u0630\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0645\u0651\u0650\u064a\u062b\u064e\u0670\u0642\u064f \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0623\u064e\u0646 \u0644\u0651\u064e\u0627 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064e \u0648\u064e\u062f\u064e\u0631\u064e\u0633\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u0641\u0650\u064a\u0647\u0650\u06d7 \u0648\u064e\u0671\u0644\u062f\u0651\u064e\u0627\u0631\u064f \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u064f \u062e\u064e\u064a\u06e1\u0631\u065e \u0644\u0651\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e\u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Maka setelah mereka, datanglah generasi (yang jahat) yang mewarisi Taurat, yang mengambil harta benda dunia yang rendah ini. Lalu mereka berkata,\"Kami akan diberi ampun.\" Dan kelak jika harta benda dunia datang kepada mereka sebanyak itu (pula), niscaya mereka akan mengambilnya (juga). Bukankah mereka sudah terikat perjanjian dalam Kitab (Taurat) bahwa mereka tidak akan mengatakan terhadap Allah, kecuali yang benar, padahal mereka telah mempelajari apa yang tersebut di dalamnya? Negeri akhirat itu lebih baik bagi mereka yang bertakwa. Maka tidakkah kamu mengerti"},{id:170,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0645\u064e\u0633\u0651\u0650\u0643\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0648\u064e\u0623\u064e\u0642\u064e\u0627\u0645\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e \u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0627 \u0646\u064f\u0636\u0650\u064a\u0639\u064f \u0623\u064e\u062c\u06e1\u0631\u064e \u0671\u0644\u06e1\u0645\u064f\u0635\u06e1\u0644\u0650\u062d\u0650\u064a\u0646\u064e",translation:"Dan orang-orang yang berpegang teguh pada Kitab (Taurat) serta melaksanakan salat, (akan diberi pahala). Sungguh, Kami tidak akan menghilangkan pahala orang-orang saleh"},{id:171,text:"\u06de\u0648\u064e\u0625\u0650\u0630\u06e1 \u0646\u064e\u062a\u064e\u0642\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u062c\u064e\u0628\u064e\u0644\u064e \u0641\u064e\u0648\u06e1\u0642\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u06e5 \u0638\u064f\u0644\u0651\u064e\u0629\u065e \u0648\u064e\u0638\u064e\u0646\u0651\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u06e5 \u0648\u064e\u0627\u0642\u0650\u0639\u064f\u06e2 \u0628\u0650\u0647\u0650\u0645\u06e1 \u062e\u064f\u0630\u064f\u0648\u0627\u0652 \u0645\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0670\u0643\u064f\u0645 \u0628\u0650\u0642\u064f\u0648\u0651\u064e\u0629\u0656 \u0648\u064e\u0671\u0630\u06e1\u0643\u064f\u0631\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u0641\u0650\u064a\u0647\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",translation:"Dan (ingatlah) ketika Kami mengangkat gunung ke atas mereka, seakan-akan (gunung) itu naungan awan dan mereka yakin bahwa (gunung) itu akan jatuh menimpa mereka. (Dan Kami firmankan kepada mereka), \"Peganglah dengan teguh apa yang telah Kami berikan kepadamu, serta ingatlah selalu (amalkanlah) apa yang tersebut di dalamnya agar kamu menjadi orang-orang yang bertakwa"},{id:172,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0623\u064e\u062e\u064e\u0630\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0645\u0650\u0646\u06e2 \u0628\u064e\u0646\u0650\u064a\u0653 \u0621\u064e\u0627\u062f\u064e\u0645\u064e \u0645\u0650\u0646 \u0638\u064f\u0647\u064f\u0648\u0631\u0650\u0647\u0650\u0645\u06e1 \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u062a\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0634\u06e1\u0647\u064e\u062f\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u06e1 \u0623\u064e\u0644\u064e\u0633\u06e1\u062a\u064f \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1\u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0628\u064e\u0644\u064e\u0649\u0670 \u0634\u064e\u0647\u0650\u062f\u06e1\u0646\u064e\u0627\u0653\u06da \u0623\u064e\u0646 \u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627\u0652 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0639\u064e\u0646\u06e1 \u0647\u064e\u0670\u0630\u064e\u0627 \u063a\u064e\u0670\u0641\u0650\u0644\u0650\u064a\u0646\u064e",translation:"Dan (ingatlah) ketika Tuhanmu mengeluarkan dari sulbi (tulang belakang) anak cucu Adam keturunan mereka dan Allah mengambil kesaksian terhadap roh mereka (seraya berfirman), \"Bukanlah Aku ini Tuhanmu?\" Mereka menjawab, \"Betul (Engkau Tuhan kami), kami bersaksi.\" (Kami lakukan yang demikian itu) agar di hari Kiamat kamu tidak mengatakan, \"Sesungguhnya ketika itu kami lengah terhadap ini"},{id:173,text:"\u0623\u064e\u0648\u06e1 \u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0634\u06e1\u0631\u064e\u0643\u064e \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0624\u064f\u0646\u064e\u0627 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f \u0648\u064e\u0643\u064f\u0646\u0651\u064e\u0627 \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u0629\u0657 \u0645\u0651\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u0647\u0650\u0645\u06e1\u06d6 \u0623\u064e\u0641\u064e\u062a\u064f\u0647\u06e1\u0644\u0650\u0643\u064f\u0646\u064e\u0627 \u0628\u0650\u0645\u064e\u0627 \u0641\u064e\u0639\u064e\u0644\u064e \u0671\u0644\u06e1\u0645\u064f\u0628\u06e1\u0637\u0650\u0644\u064f\u0648\u0646\u064e",translation:"atau agar kamu tidak mengatakan, \"Sesungguhnya nenek moyang kami telah memper\xadsekutukan Tuhan sejak dahulu, sedang kami adalah keturunan yang (datang) setelah mereka. Maka apakah Engkau akan membinasakan kami karena perbuatan orang-orang (dahulu) yang sesat"},{id:174,text:"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064f\u0641\u064e\u0635\u0651\u0650\u0644\u064f \u0671\u0644\u06e1\u0623\u0653\u064a\u064e\u0670\u062a\u0650 \u0648\u064e\u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0631\u06e1\u062c\u0650\u0639\u064f\u0648\u0646\u064e",translation:"Dan demikianlah Kami menjelaskan ayat-ayat itu, agar mereka kembali (kepada kebenaran)"},{id:175,text:"\u0648\u064e\u0671\u062a\u06e1\u0644\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0646\u064e\u0628\u064e\u0623\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0641\u064e\u0671\u0646\u0633\u064e\u0644\u064e\u062e\u064e \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0641\u064e\u0623\u064e\u062a\u06e1\u0628\u064e\u0639\u064e\u0647\u064f \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u064f \u0641\u064e\u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u063a\u064e\u0627\u0648\u0650\u064a\u0646\u064e",translation:"Dan bacakanlah (Muhammad) kepada mereka, berita orang yang telah Kami berikan ayat-ayat Kami kepadanya, kemudian dia melepaskan diri dari ayat-ayat itu, lalu dia diikuti oleh setan (sampai dia tergoda), lalu jadilah dia termasuk orang yang sesat"},{id:176,text:"\u0648\u064e\u0644\u064e\u0648\u06e1 \u0634\u0650\u0626\u06e1\u0646\u064e\u0627 \u0644\u064e\u0631\u064e\u0641\u064e\u0639\u06e1\u0646\u064e\u0670\u0647\u064f \u0628\u0650\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u062e\u06e1\u0644\u064e\u062f\u064e \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064e \u0647\u064e\u0648\u064e\u0649\u0670\u0647\u064f\u06da \u0641\u064e\u0645\u064e\u062b\u064e\u0644\u064f\u0647\u064f\u06e5 \u0643\u064e\u0645\u064e\u062b\u064e\u0644\u0650 \u0671\u0644\u06e1\u0643\u064e\u0644\u06e1\u0628\u0650 \u0625\u0650\u0646 \u062a\u064e\u062d\u06e1\u0645\u0650\u0644\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u064a\u064e\u0644\u06e1\u0647\u064e\u062b\u06e1 \u0623\u064e\u0648\u06e1 \u062a\u064e\u062a\u06e1\u0631\u064f\u0643\u06e1\u0647\u064f \u064a\u064e\u0644\u06e1\u0647\u064e\u062b\u06da \u0630\u0651\u064e\u0640\u0670\u0644\u0650\u0643\u064e \u0645\u064e\u062b\u064e\u0644\u064f \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627\u06da \u0641\u064e\u0671\u0642\u06e1\u0635\u064f\u0635\u0650 \u0671\u0644\u06e1\u0642\u064e\u0635\u064e\u0635\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u062a\u064e\u0641\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan sekiranya Kami menghendaki niscaya Kami tinggikan (derajat)nya dengan (ayat-ayat) itu, tetapi dia cenderung kepada dunia dan mengikuti keinginannya (yang rendah), maka perumpamaannya seperti anjing, jika kamu menghalaunya dijulurkan lidahnya dan jika kamu membiarkannya ia menjulurkan lidahnya (juga). Demikianlah perumpamaan orang-orang yang mendustakan ayat-ayat Kami. Maka ceritakanlah kisah-kisah itu agar mereka berpikir"},{id:177,text:"\u0633\u064e\u0627\u0653\u0621\u064e \u0645\u064e\u062b\u064e\u0644\u064b\u0627 \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0648\u064e\u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0638\u06e1\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Sangat buruk perumpamaan orang-orang yang mendustakan ayat-ayat Kami; mereka menzalimi diri sendiri"},{id:178,text:"\u0645\u064e\u0646 \u064a\u064e\u0647\u06e1\u062f\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0645\u064f\u0647\u06e1\u062a\u064e\u062f\u0650\u064a\u06d6 \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0636\u06e1\u0644\u0650\u0644\u06e1 \u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u062e\u064e\u0670\u0633\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Barang siapa diberi petunjuk oleh Allah, maka dialah yang mendapat petunjuk; dan barang siapa disesatkan Allah, maka merekalah orang-orang yang rugi"},{id:179,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0630\u064e\u0631\u064e\u0623\u06e1\u0646\u064e\u0627 \u0644\u0650\u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u062c\u0650\u0646\u0651\u0650 \u0648\u064e\u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u0650\u06d6 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0642\u064f\u0644\u064f\u0648\u0628\u065e \u0644\u0651\u064e\u0627 \u064a\u064e\u0641\u06e1\u0642\u064e\u0647\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u0639\u06e1\u064a\u064f\u0646\u065e \u0644\u0651\u064e\u0627 \u064a\u064f\u0628\u06e1\u0635\u0650\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0621\u064e\u0627\u0630\u064e\u0627\u0646\u065e \u0644\u0651\u064e\u0627 \u064a\u064e\u0633\u06e1\u0645\u064e\u0639\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u064e\u0627\u0653\u06da \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0643\u064e\u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0639\u064e\u0670\u0645\u0650 \u0628\u064e\u0644\u06e1 \u0647\u064f\u0645\u06e1 \u0623\u064e\u0636\u064e\u0644\u0651\u064f\u06da \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u063a\u064e\u0670\u0641\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Dan Sungguh, akan Kami isi neraka Jahanam banyak dari kalangan jin dan manusia. Mereka memiliki hati, tetapi tidak dipergunakannya untuk memahami (ayat-ayat Allah) dan mereka memiliki mata (tetapi) tidak dipergunakannya untuk melihat (tanda-tanda kekuasaan Allah), dan mereka mempunyai telinga (tetapi) tidak dipergunakannya untuk mendengarkan (ayat-ayat Allah). Mereka seperti hewan ternak, bahkan lebih sesat lagi. Mereka itulah orang-orang yang lengah"},{id:180,text:"\u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u0623\u064e\u0633\u06e1\u0645\u064e\u0627\u0653\u0621\u064f \u0671\u0644\u06e1\u062d\u064f\u0633\u06e1\u0646\u064e\u0649\u0670 \u0641\u064e\u0671\u062f\u06e1\u0639\u064f\u0648\u0647\u064f \u0628\u0650\u0647\u064e\u0627\u06d6 \u0648\u064e\u0630\u064e\u0631\u064f\u0648\u0627\u0652 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0644\u06e1\u062d\u0650\u062f\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0653 \u0623\u064e\u0633\u06e1\u0645\u064e\u0640\u0670\u0653\u0626\u0650\u0647\u0650\u06e6\u06da \u0633\u064e\u064a\u064f\u062c\u06e1\u0632\u064e\u0648\u06e1\u0646\u064e \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan Allah memiliki Asm\u0101ul \u1e24usn\u0101 (nama-nama yang terbaik), maka bermohonlah kepada-Nya dengan menyebut Asm\u0101ul \u1e24usn\u0101 itu dan tinggalkanlah orang-orang yang menyalahartikan nama-nama-Nya351) Mereka kelak akan mendapat balasan terhadap apa yang telah mereka kerjakan"},{id:181,text:"\u0648\u064e\u0645\u0650\u0645\u0651\u064e\u0646\u06e1 \u062e\u064e\u0644\u064e\u0642\u06e1\u0646\u064e\u0627\u0653 \u0623\u064f\u0645\u0651\u064e\u0629\u065e \u064a\u064e\u0647\u06e1\u062f\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0628\u0650\u0647\u0650\u06e6 \u064a\u064e\u0639\u06e1\u062f\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Dan di antara orang-orang yang telah Kami ciptakan ada umat yang memberi petunjuk dengan (dasar) kebenaran, dan dengan itu (pula) mereka berlaku adil"},{id:182,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0633\u064e\u0646\u064e\u0633\u06e1\u062a\u064e\u062f\u06e1\u0631\u0650\u062c\u064f\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u062d\u064e\u064a\u06e1\u062b\u064f \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan orang-orang yang mendustakan ayat-ayat Kami, akan Kami biarkan mereka berangsur-angsur (ke arah kebinasaan), dengan cara yang tidak mereka ketahui"},{id:183,text:"\u0648\u064e\u0623\u064f\u0645\u06e1\u0644\u0650\u064a \u0644\u064e\u0647\u064f\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e \u0643\u064e\u064a\u06e1\u062f\u0650\u064a \u0645\u064e\u062a\u0650\u064a\u0646\u064c",translation:"Dan Aku akan memberikan tenggang waktu kepada mereka. Sungguh, rencana-Ku sangat teguh"},{id:184,text:"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u062a\u064e\u0641\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0627\u0652\u06d7 \u0645\u064e\u0627 \u0628\u0650\u0635\u064e\u0627\u062d\u0650\u0628\u0650\u0647\u0650\u0645 \u0645\u0651\u0650\u0646 \u062c\u0650\u0646\u0651\u064e\u0629\u064d\u06da \u0625\u0650\u0646\u06e1 \u0647\u064f\u0648\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0646\u064e\u0630\u0650\u064a\u0631\u065e \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u064c",translation:"Dan apakah mereka tidak merenungkan bahwa teman mereka (Muhammad) tidak gila. Dia (Muhammad) tidak lain hanyalah seorang pemberi peringatan yang jelas"},{id:185,text:"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0646\u0638\u064f\u0631\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0645\u064e\u0644\u064e\u0643\u064f\u0648\u062a\u0650 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0648\u064e\u0623\u064e\u0646\u06e1 \u0639\u064e\u0633\u064e\u0649\u0670\u0653 \u0623\u064e\u0646 \u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0642\u064e\u062f\u0650 \u0671\u0642\u06e1\u062a\u064e\u0631\u064e\u0628\u064e \u0623\u064e\u062c\u064e\u0644\u064f\u0647\u064f\u0645\u06e1\u06d6 \u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u062d\u064e\u062f\u0650\u064a\u062b\u0650\u06ed \u0628\u064e\u0639\u06e1\u062f\u064e\u0647\u064f\u06e5 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Dan apakah mereka tidak memperhatikan kerajaan langit dan bumi dan segala apa yang diciptakan Allah, dan kemungkinan telah dekatnya waktu (kebinasaan) mereka? Lalu berita mana lagi setelah ini yang mereka percayai"},{id:186,text:"\u0645\u064e\u0646 \u064a\u064f\u0636\u06e1\u0644\u0650\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0644\u064e\u0627 \u0647\u064e\u0627\u062f\u0650\u064a\u064e \u0644\u064e\u0647\u064f\u06e5\u06da \u0648\u064e\u064a\u064e\u0630\u064e\u0631\u064f\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0637\u064f\u063a\u06e1\u064a\u064e\u0670\u0646\u0650\u0647\u0650\u0645\u06e1 \u064a\u064e\u0639\u06e1\u0645\u064e\u0647\u064f\u0648\u0646\u064e",translation:"Barang siapa dibiarkan sesat oleh Allah, maka tidak ada yang mampu memberi petunjuk. Allah membiarkannya terombang-ambing dalam kesesatan"},{id:187,text:"\u064a\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u0639\u064e\u0646\u0650 \u0671\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u0650 \u0623\u064e\u064a\u0651\u064e\u0627\u0646\u064e \u0645\u064f\u0631\u06e1\u0633\u064e\u0649\u0670\u0647\u064e\u0627\u06d6 \u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0639\u0650\u0644\u06e1\u0645\u064f\u0647\u064e\u0627 \u0639\u0650\u0646\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u064a\u06d6 \u0644\u064e\u0627 \u064a\u064f\u062c\u064e\u0644\u0651\u0650\u064a\u0647\u064e\u0627 \u0644\u0650\u0648\u064e\u0642\u06e1\u062a\u0650\u0647\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e\u06da \u062b\u064e\u0642\u064f\u0644\u064e\u062a\u06e1 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06da \u0644\u064e\u0627 \u062a\u064e\u0623\u06e1\u062a\u0650\u064a\u0643\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u064e\u063a\u06e1\u062a\u064e\u0629\u0657\u06d7 \u064a\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0643\u064e \u062d\u064e\u0641\u0650\u064a\u0651\u064c \u0639\u064e\u0646\u06e1\u0647\u064e\u0627\u06d6 \u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0639\u0650\u0644\u06e1\u0645\u064f\u0647\u064e\u0627 \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Mereka menanyakan kepadamu (Muhammad) tentang Kiamat, \"Kapan terjadi?\" Katakanlah, \"Sesungguhnya pengetahuan tentang Kiamat itu ada pada Tuhanku; tidak ada (seorang pun) yang dapat menjelaskan waktu terjadinya selain Dia. (Kiamat) itu sangat berat (huru haranya bagi makhluk) yang di langit dan di bumi, tidak akan datang kepadamu kecuali secara tiba-tiba.\" Mereka bertanya kepadamu seakan-akan engkau mengetahuinya. Katakanlah (Muhammad), \"Sesungguhnya pengetahuan tentang (hari Kiamat) ada pada Allah, tetapi kebanyakan manusia tidak mengetahui"},{id:188,text:"\u0642\u064f\u0644 \u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0645\u06e1\u0644\u0650\u0643\u064f \u0644\u0650\u0646\u064e\u0641\u06e1\u0633\u0650\u064a \u0646\u064e\u0641\u06e1\u0639\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u0636\u064e\u0631\u0651\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0634\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06da \u0648\u064e\u0644\u064e\u0648\u06e1 \u0643\u064f\u0646\u062a\u064f \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u0628\u064e \u0644\u064e\u0671\u0633\u06e1\u062a\u064e\u0643\u06e1\u062b\u064e\u0631\u06e1\u062a\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u062e\u064e\u064a\u06e1\u0631\u0650 \u0648\u064e\u0645\u064e\u0627 \u0645\u064e\u0633\u0651\u064e\u0646\u0650\u064a\u064e \u0671\u0644\u0633\u0651\u064f\u0648\u0653\u0621\u064f\u06da \u0625\u0650\u0646\u06e1 \u0623\u064e\u0646\u064e\u0627\u06e0 \u0625\u0650\u0644\u0651\u064e\u0627 \u0646\u064e\u0630\u0650\u064a\u0631\u065e \u0648\u064e\u0628\u064e\u0634\u0650\u064a\u0631\u065e \u0644\u0651\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Katakanlah (Muhammad), \"Aku tidak kuasa mendatangkan manfaat maupun menolak mudarat bagi diriku kecuali apa yang dikehendaki Allah. Sekiranya aku mengetahui yang gaib, niscaya aku membuat kebajikan sebanyak-banyaknya dan tidak akan ditimpa bahaya. Aku hanyalah pemberi peringatan, dan pembawa berita gembira bagi orang-orang yang beriman"},{id:189,text:"\u06de\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0646\u0651\u064e\u0641\u06e1\u0633\u0656 \u0648\u064e\u0670\u062d\u0650\u062f\u064e\u0629\u0656 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0632\u064e\u0648\u06e1\u062c\u064e\u0647\u064e\u0627 \u0644\u0650\u064a\u064e\u0633\u06e1\u0643\u064f\u0646\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u064e\u0627\u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062a\u064e\u063a\u064e\u0634\u0651\u064e\u0649\u0670\u0647\u064e\u0627 \u062d\u064e\u0645\u064e\u0644\u064e\u062a\u06e1 \u062d\u064e\u0645\u06e1\u0644\u064b\u0627 \u062e\u064e\u0641\u0650\u064a\u0641\u0657\u0627 \u0641\u064e\u0645\u064e\u0631\u0651\u064e\u062a\u06e1 \u0628\u0650\u0647\u0650\u06e6\u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u062b\u06e1\u0642\u064e\u0644\u064e\u062a \u062f\u0651\u064e\u0639\u064e\u0648\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u0645\u064e\u0627 \u0644\u064e\u0626\u0650\u0646\u06e1 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u062a\u064e\u0646\u064e\u0627 \u0635\u064e\u0670\u0644\u0650\u062d\u0657\u0627 \u0644\u0651\u064e\u0646\u064e\u0643\u064f\u0648\u0646\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0634\u0651\u064e\u0640\u0670\u0643\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dialah yang menciptakan kamu dari jiwa yang satu (Adam) dan daripadanya Dia menciptakan pasangannya, agar dia merasa senang kepadanya. Maka setelah dicampurinya, (istrinya) mengandung kandungan yang ringan, dan teruslah dia merasa ringan (beberapa waktu). Kemudian ketika dia merasa berat, keduanya (suami-istri) bermohon kepada Allah, Tuhan mereka (seraya berkata), \"Jika Engkau memberi kami anak yang saleh, tentulah kami akan selalu bersyukur"},{id:190,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u064e\u0649\u0670\u0647\u064f\u0645\u064e\u0627 \u0635\u064e\u0670\u0644\u0650\u062d\u0657\u0627 \u062c\u064e\u0639\u064e\u0644\u064e\u0627 \u0644\u064e\u0647\u064f\u06e5 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0653\u0621\u064e \u0641\u0650\u064a\u0645\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u064e\u0649\u0670\u0647\u064f\u0645\u064e\u0627\u06da \u0641\u064e\u062a\u064e\u0639\u064e\u0670\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064f\u0634\u06e1\u0631\u0650\u0643\u064f\u0648\u0646\u064e",translation:"(Maka setelah Dia memberi kepada keduanya seorang anak yang saleh, mereka352) menjadikan sekutu bagi Allah terhadap anak yang telah dianugerahkan-Nya itu. Maka Mahatinggi Allah dari apa yang mereka persekutukan"},{id:191,text:"\u0623\u064e\u064a\u064f\u0634\u06e1\u0631\u0650\u0643\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u062e\u06e1\u0644\u064f\u0642\u064f \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627 \u0648\u064e\u0647\u064f\u0645\u06e1 \u064a\u064f\u062e\u06e1\u0644\u064e\u0642\u064f\u0648\u0646\u064e",translation:"Mengapa mereka mempersekutukan (Allah dengan) berhala yang tidak dapat menciptakan sesuatu apa pun? Padahal (berhala) itu sendiri diciptakan"},{id:192,text:"\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0646\u064e\u0635\u06e1\u0631\u0657\u0627 \u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0646\u0635\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Dan (berhala) itu tidak dapat memberikan pertolongan kepada penyembahnya, dan kepada dirinya sendiri pun mereka tidak dapat memberi pertolongan"},{id:193,text:"\u0648\u064e\u0625\u0650\u0646 \u062a\u064e\u062f\u06e1\u0639\u064f\u0648\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u0647\u064f\u062f\u064e\u0649\u0670 \u0644\u064e\u0627 \u064a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0643\u064f\u0645\u06e1\u06da \u0633\u064e\u0648\u064e\u0627\u0653\u0621\u064c \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0623\u064e\u062f\u064e\u0639\u064e\u0648\u06e1\u062a\u064f\u0645\u064f\u0648\u0647\u064f\u0645\u06e1 \u0623\u064e\u0645\u06e1 \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0635\u064e\u0670\u0645\u0650\u062a\u064f\u0648\u0646\u064e",translation:"Dan jika kamu (Wahai orang-orang musyrik) menyerunya (berhala-berhala) untuk memberi petunjuk kepadamu, tidaklah berhala-berhala itu dapat memperkenankan seruanmu; sama saja (hasilnya) buat kamu menyeru mereka atau berdiam diri"},{id:194,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u0650\u0628\u064e\u0627\u062f\u064c \u0623\u064e\u0645\u06e1\u062b\u064e\u0627\u0644\u064f\u0643\u064f\u0645\u06e1\u06d6 \u0641\u064e\u0671\u062f\u06e1\u0639\u064f\u0648\u0647\u064f\u0645\u06e1 \u0641\u064e\u0644\u06e1\u064a\u064e\u0633\u06e1\u062a\u064e\u062c\u0650\u064a\u0628\u064f\u0648\u0627\u0652 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0635\u064e\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Sesungguhnya mereka (berhala-berhala) yang kamu seru selain Allah adalah makhluk (yang lemah) yang serupa juga dengan kamu. Maka serulah mereka lalu biarkanlah mereka memperkenankan permintaanmu, jika kamu orang yang benar"},{id:195,text:"\u0623\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u0631\u06e1\u062c\u064f\u0644\u065e \u064a\u064e\u0645\u06e1\u0634\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u064e\u0627\u0653\u06d6 \u0623\u064e\u0645\u06e1 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u064a\u06e1\u062f\u0656 \u064a\u064e\u0628\u06e1\u0637\u0650\u0634\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u064e\u0627\u0653\u06d6 \u0623\u064e\u0645\u06e1 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u0639\u06e1\u064a\u064f\u0646\u065e \u064a\u064f\u0628\u06e1\u0635\u0650\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u064e\u0627\u0653\u06d6 \u0623\u064e\u0645\u06e1 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0621\u064e\u0627\u0630\u064e\u0627\u0646\u065e \u064a\u064e\u0633\u06e1\u0645\u064e\u0639\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u064e\u0627\u06d7 \u0642\u064f\u0644\u0650 \u0671\u062f\u06e1\u0639\u064f\u0648\u0627\u0652 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u06e1 \u062b\u064f\u0645\u0651\u064e \u0643\u0650\u064a\u062f\u064f\u0648\u0646\u0650 \u0641\u064e\u0644\u064e\u0627 \u062a\u064f\u0646\u0638\u0650\u0631\u064f\u0648\u0646\u0650",translation:"Apakah mereka (berhala-berhala) mempunyai kaki untuk berjalan, atau mempunyai tangan untuk memegang dengan keras,353) atau mempunyai mata untuk melihat, atau mempunyai telinga untuk mendengar? Katakanlah (Muhammad) \"Panggillah berhala-berhalamu yang kamu anggap sekutu Allah, kemudian lakukanlah tipu daya (untuk mencelakakan)ku, dan jangan kamu tunda lagi"},{id:196,text:"\u0625\u0650\u0646\u0651\u064e \u0648\u064e\u0644\u0650\u0640\u06e7\u0651\u0650\u064a\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0646\u064e\u0632\u0651\u064e\u0644\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e\u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u064a\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u0650\u064a\u0646\u064e",translation:"Sesungguhnya pelindungku adalah Allah yang telah menurunkan Kitab (Alquran). Dia melindungi orang-orang saleh"},{id:197,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u06e6 \u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u064e \u0646\u064e\u0635\u06e1\u0631\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0646\u0635\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Dan berhala-berhala yang kamu seru selain Allah tidaklah sanggup menolongmu, bahkan tidak dapat menolong dirinya sendiri"},{id:198,text:"\u0648\u064e\u0625\u0650\u0646 \u062a\u064e\u062f\u06e1\u0639\u064f\u0648\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u0647\u064f\u062f\u064e\u0649\u0670 \u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u0645\u064e\u0639\u064f\u0648\u0627\u0652\u06d6 \u0648\u064e\u062a\u064e\u0631\u064e\u0649\u0670\u0647\u064f\u0645\u06e1 \u064a\u064e\u0646\u0638\u064f\u0631\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0648\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064f\u0628\u06e1\u0635\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Dan jika kamu menyeru mereka (berhala-berhala) untuk memberi petunjuk, mereka tidak dapat mendengarnya. Dan kamu lihat mereka memandangmu padahal mereka tidak melihat"},{id:199,text:"\u062e\u064f\u0630\u0650 \u0671\u0644\u06e1\u0639\u064e\u0641\u06e1\u0648\u064e \u0648\u064e\u0623\u06e1\u0645\u064f\u0631\u06e1 \u0628\u0650\u0671\u0644\u06e1\u0639\u064f\u0631\u06e1\u0641\u0650 \u0648\u064e\u0623\u064e\u0639\u06e1\u0631\u0650\u0636\u06e1 \u0639\u064e\u0646\u0650 \u0671\u0644\u06e1\u062c\u064e\u0670\u0647\u0650\u0644\u0650\u064a\u0646\u064e",translation:"Jadilah pemaaf dan suruhlah orang mengerjakan yang makruf, serta jangan pedulikan orang-orang yang bodoh"},{id:200,text:"\u0648\u064e\u0625\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u0646\u0632\u064e\u063a\u064e\u0646\u0651\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u0650 \u0646\u064e\u0632\u06e1\u063a\u065e \u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u0639\u0650\u0630\u06e1 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0633\u064e\u0645\u0650\u064a\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u064c",translation:"(Dan jika setan datang menggodamu, maka berlindunglah kepada Allah354) Sungguh, Dia Maha Mendengar, Maha Mengetahui"},{id:201,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u062a\u0651\u064e\u0642\u064e\u0648\u06e1\u0627\u0652 \u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0633\u0651\u064e\u0647\u064f\u0645\u06e1 \u0637\u064e\u0640\u0670\u0653\u0626\u0650\u0641\u065e \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u0650 \u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0627\u0652 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0645 \u0645\u0651\u064f\u0628\u06e1\u0635\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Sesungguhnya orang-orang yang bertakwa apabila mereka dibayang-bayangi pikiran jahat (berbuat dosa) dari setan, mereka pun segera ingat kepada Allah, maka ketika itu juga mereka melihat (kesalahan-kesalahannya)"},{id:202,text:"\u0648\u064e\u0625\u0650\u062e\u06e1\u0648\u064e\u0670\u0646\u064f\u0647\u064f\u0645\u06e1 \u064a\u064e\u0645\u064f\u062f\u0651\u064f\u0648\u0646\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u063a\u064e\u064a\u0651\u0650 \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0627 \u064a\u064f\u0642\u06e1\u0635\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Dan teman-teman mereka (orang kafir dan fasik) membantu setan-setan dalam menyesatkan dan mereka tidak henti-hentinya (menyesatkan)"},{id:203,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0644\u064e\u0645\u06e1 \u062a\u064e\u0623\u06e1\u062a\u0650\u0647\u0650\u0645 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0629\u0656 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0648\u06e1\u0644\u064e\u0627 \u0671\u062c\u06e1\u062a\u064e\u0628\u064e\u064a\u06e1\u062a\u064e\u0647\u064e\u0627\u06da \u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f \u0645\u064e\u0627 \u064a\u064f\u0648\u062d\u064e\u0649\u0670\u0653 \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u064a\u06da \u0647\u064e\u0670\u0630\u064e\u0627 \u0628\u064e\u0635\u064e\u0627\u0653\u0626\u0650\u0631\u064f \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0647\u064f\u062f\u0657\u0649 \u0648\u064e\u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u065e \u0644\u0651\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Dan apabila engkau (Muhammad) tidak membacakan suatu ayat kepada mereka, mereka berkata, \"Mengapa tidak engkau buat sendiri ayat itu?\" Katakanlah (Muhammad), \"Sesungguhnya aku hanya mengikuti apa yang diwahyukan Tuhanku kepadaku. (Alquran) ini adalah bukti-bukti yang nyata dari Tuhanmu, petunjuk dan rahmat bagi orang-orang yang beriman"},{id:204,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u064f\u0631\u0650\u0626\u064e \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u064f \u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u0645\u0650\u0639\u064f\u0648\u0627\u0652 \u0644\u064e\u0647\u064f\u06e5 \u0648\u064e\u0623\u064e\u0646\u0635\u0650\u062a\u064f\u0648\u0627\u0652 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064f\u0631\u06e1\u062d\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan apabila dibacakan Alquran, maka dengarkanlah dan diamlah, agar kamu mendapat rahmat"},{id:205,text:"\u0648\u064e\u0671\u0630\u06e1\u0643\u064f\u0631 \u0631\u0651\u064e\u0628\u0651\u064e\u0643\u064e \u0641\u0650\u064a \u0646\u064e\u0641\u06e1\u0633\u0650\u0643\u064e \u062a\u064e\u0636\u064e\u0631\u0651\u064f\u0639\u0657\u0627 \u0648\u064e\u062e\u0650\u064a\u0641\u064e\u0629\u0657 \u0648\u064e\u062f\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u062c\u064e\u0647\u06e1\u0631\u0650 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0644\u0650 \u0628\u0650\u0671\u0644\u06e1\u063a\u064f\u062f\u064f\u0648\u0651\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u0653\u0635\u064e\u0627\u0644\u0650 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0646 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u063a\u064e\u0670\u0641\u0650\u0644\u0650\u064a\u0646\u064e",translation:"Dan ingatlah Tuhanmu dalam hatimu dengan rendah hati dan rasa takut, dan dengan tidak mengeraskan suara, pada waktu pagi dan petang, dan janganlah kamu termasuk orang-orang yang lengah"},{id:206,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0639\u0650\u0646\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u0650\u0631\u064f\u0648\u0646\u064e \u0639\u064e\u0646\u06e1 \u0639\u0650\u0628\u064e\u0627\u062f\u064e\u062a\u0650\u0647\u0650\u06e6 \u0648\u064e\u064a\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u064f\u0648\u0646\u064e\u0647\u064f\u06e5 \u0648\u064e\u0644\u064e\u0647\u064f\u06e5 \u064a\u064e\u0633\u06e1\u062c\u064f\u062f\u064f\u0648\u0646\u064e\u06e4\u06e9",translation:"Sesungguhnya orang-orang yang ada di sisi Tuhanmu tidak merasa enggan untuk menyembah Allah dan mereka menyucikan-Nya dan hanya kepada-Nya mereka bersujud"}]},{id:8,name:"\u0627\u0644\u0623\u0646\u0641\u0627\u0644",transliteration:"Al-Anfal",translation:"Rampasan Perang",type:"medinan",total_verses:75,verses:[{id:1,text:"\u064a\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u0639\u064e\u0646\u0650 \u0671\u0644\u06e1\u0623\u064e\u0646\u0641\u064e\u0627\u0644\u0650\u06d6 \u0642\u064f\u0644\u0650 \u0671\u0644\u06e1\u0623\u064e\u0646\u0641\u064e\u0627\u0644\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0650\u06d6 \u0641\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0623\u064e\u0635\u06e1\u0644\u0650\u062d\u064f\u0648\u0627\u0652 \u0630\u064e\u0627\u062a\u064e \u0628\u064e\u064a\u06e1\u0646\u0650\u0643\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f\u06e5\u0653 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645 \u0645\u0651\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Mereka menanyakan kepadamu (Muhammad) tentang (pembagian) harta rampasan perang. Katakanlah, \"Harta rampasan perang itu milik Allah dan Rasul (menurut ketentuan Allah dan Rasul-Nya), maka bertakwalah kepada Allah dan perbaikilah hubungan di antara sesamamu, dan taatlah kepada Allah dan Rasul-Nya jika kamu orang-orang yang beriman"},{id:2,text:"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0625\u0650\u0630\u064e\u0627 \u0630\u064f\u0643\u0650\u0631\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u062c\u0650\u0644\u064e\u062a\u06e1 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062a\u064f\u0644\u0650\u064a\u064e\u062a\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u064f\u0647\u064f\u06e5 \u0632\u064e\u0627\u062f\u064e\u062a\u06e1\u0647\u064f\u0645\u06e1 \u0625\u0650\u064a\u0645\u064e\u0670\u0646\u0657\u0627 \u0648\u064e\u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u064a\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u064f\u0648\u0646\u064e",translation:"(Sesungguhnya orang-orang yang beriman adalah mereka yang apabila disebut nama Allah357) gemetar hatinya, dan apabila dibacakan ayat-ayat-Nya kepada mereka, bertambah (kuat) imannya dan hanya kepada Tuhan mereka bertawakal"},{id:3,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0642\u0650\u064a\u0645\u064f\u0648\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u0645\u0650\u0645\u0651\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u064a\u064f\u0646\u0641\u0650\u0642\u064f\u0648\u0646\u064e",translation:"(yaitu) orang-orang yang melaksanakan salat dan yang menginfakkan sebagian dari rezeki yang Kami berikan kepada mereka"},{id:4,text:"\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u062d\u064e\u0642\u0651\u0657\u0627\u06da \u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u062f\u064e\u0631\u064e\u062c\u064e\u0670\u062a\u064c \u0639\u0650\u0646\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0645\u064e\u063a\u06e1\u0641\u0650\u0631\u064e\u0629\u065e \u0648\u064e\u0631\u0650\u0632\u06e1\u0642\u065e \u0643\u064e\u0631\u0650\u064a\u0645\u065e",translation:"Mereka itulah orang-orang yang benar-benar beriman. Mereka akan memperoleh derajat (tinggi) di sisi Tuhannya dan ampunan serta rezeki (nikmat) yang mulia"},{id:5,text:"\u0643\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u062e\u06e1\u0631\u064e\u062c\u064e\u0643\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0645\u0650\u0646\u06e2 \u0628\u064e\u064a\u06e1\u062a\u0650\u0643\u064e \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0641\u064e\u0631\u0650\u064a\u0642\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0644\u064e\u0643\u064e\u0670\u0631\u0650\u0647\u064f\u0648\u0646\u064e",translation:"(Sebagaimana Tuhanmu menyuruhmu pergi dari rumahmu dengan kebenaran,358) meskipun sesungguhnya sebagian dari orang-orang yang beriman itu tidak menyukainya"},{id:6,text:"\u064a\u064f\u062c\u064e\u0670\u062f\u0650\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0628\u064e\u0639\u06e1\u062f\u064e \u0645\u064e\u0627 \u062a\u064e\u0628\u064e\u064a\u0651\u064e\u0646\u064e \u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064f\u0633\u064e\u0627\u0642\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u0650 \u0648\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0646\u0638\u064f\u0631\u064f\u0648\u0646\u064e",translation:"mereka membantahmu (Muhammad) tentang kebenaran setelah nyata (bahwa mereka pasti menang), seakan-akan mereka dihalau kepada kematian, sedang mereka melihat (sebab kematian itu)"},{id:7,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u064a\u064e\u0639\u0650\u062f\u064f\u0643\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0625\u0650\u062d\u06e1\u062f\u064e\u0649 \u0671\u0644\u0637\u0651\u064e\u0627\u0653\u0626\u0650\u0641\u064e\u062a\u064e\u064a\u06e1\u0646\u0650 \u0623\u064e\u0646\u0651\u064e\u0647\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u062a\u064e\u0648\u064e\u062f\u0651\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0651\u064e \u063a\u064e\u064a\u06e1\u0631\u064e \u0630\u064e\u0627\u062a\u0650 \u0671\u0644\u0634\u0651\u064e\u0648\u06e1\u0643\u064e\u0629\u0650 \u062a\u064e\u0643\u064f\u0648\u0646\u064f \u0644\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0646 \u064a\u064f\u062d\u0650\u0642\u0651\u064e \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064e \u0628\u0650\u0643\u064e\u0644\u0650\u0645\u064e\u0670\u062a\u0650\u0647\u0650\u06e6 \u0648\u064e\u064a\u064e\u0642\u06e1\u0637\u064e\u0639\u064e \u062f\u064e\u0627\u0628\u0650\u0631\u064e \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan (ingatlah) ketika Allah menjanjikan kepadamu bahwa salah satu dari dua golongan (yang kamu hadapi) adalah untukmu, sedang kamu menginginkan bahwa yang tidak mempunyai kekuatan senjatalah359) untukmu. Tetapi Allah hendak membenarkan yang benar dengan ayat-ayat-Nya dan memusnahkan orang-orang kafir sampai ke akar-akarnya"},{id:8,text:"\u0644\u0650\u064a\u064f\u062d\u0650\u0642\u0651\u064e \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064e \u0648\u064e\u064a\u064f\u0628\u06e1\u0637\u0650\u0644\u064e \u0671\u0644\u06e1\u0628\u064e\u0670\u0637\u0650\u0644\u064e \u0648\u064e\u0644\u064e\u0648\u06e1 \u0643\u064e\u0631\u0650\u0647\u064e \u0671\u0644\u06e1\u0645\u064f\u062c\u06e1\u0631\u0650\u0645\u064f\u0648\u0646\u064e",translation:"agar Allah memperkuat yang hak (Islam) dan menghilangkan yang batil (syirik) walaupun orang-orang yang berdosa (musyrik) itu tidak menyukainya"},{id:9,text:"\u0625\u0650\u0630\u06e1 \u062a\u064e\u0633\u06e1\u062a\u064e\u063a\u0650\u064a\u062b\u064f\u0648\u0646\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u06e1 \u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u062c\u064e\u0627\u0628\u064e \u0644\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u0646\u0651\u0650\u064a \u0645\u064f\u0645\u0650\u062f\u0651\u064f\u0643\u064f\u0645 \u0628\u0650\u0623\u064e\u0644\u06e1\u0641\u0656 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u0650 \u0645\u064f\u0631\u06e1\u062f\u0650\u0641\u0650\u064a\u0646\u064e",translation:"(Ingatlah), ketika kamu memohon pertolongan kepada tuhanmu, lalu diperkenankan-Nya bagimu, \"Sungguh, aku akan mendatangkan bala bantuan kepadamu dengan seribu malaikat yang datang berturut-turut"},{id:10,text:"\u0648\u064e\u0645\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u064e\u0647\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u064f\u0634\u06e1\u0631\u064e\u0649\u0670 \u0648\u064e\u0644\u0650\u062a\u064e\u0637\u06e1\u0645\u064e\u0626\u0650\u0646\u0651\u064e \u0628\u0650\u0647\u0650\u06e6 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0645\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0635\u06e1\u0631\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u0650\u0646\u06e1 \u0639\u0650\u0646\u062f\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0632\u0650\u064a\u0632\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u064c",translation:"Dan tidaklah Allah menjadikannya melainkan sebagai kabar gembira agar hatimu menjadi tenteram karenanya. Dan kemenangan itu hanyalah dari sisi Allah. Sungguh, Allah Mahaperkasa, Mahabijaksana"},{id:11,text:"\u0625\u0650\u0630\u06e1 \u064a\u064f\u063a\u064e\u0634\u0651\u0650\u064a\u0643\u064f\u0645\u064f \u0671\u0644\u0646\u0651\u064f\u0639\u064e\u0627\u0633\u064e \u0623\u064e\u0645\u064e\u0646\u064e\u0629\u0657 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f \u0648\u064e\u064a\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0645\u064e\u0627\u0653\u0621\u0657 \u0644\u0651\u0650\u064a\u064f\u0637\u064e\u0647\u0651\u0650\u0631\u064e\u0643\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6 \u0648\u064e\u064a\u064f\u0630\u06e1\u0647\u0650\u0628\u064e \u0639\u064e\u0646\u0643\u064f\u0645\u06e1 \u0631\u0650\u062c\u06e1\u0632\u064e \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u0650 \u0648\u064e\u0644\u0650\u064a\u064e\u0631\u06e1\u0628\u0650\u0637\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u064a\u064f\u062b\u064e\u0628\u0651\u0650\u062a\u064e \u0628\u0650\u0647\u0650 \u0671\u0644\u06e1\u0623\u064e\u0642\u06e1\u062f\u064e\u0627\u0645\u064e",translation:"(Ingatlah), ketika Allah membuat kamu mengantuk untuk memberi ketentraman dari-Nya, dan Allah menurunkan air (hujan) dari langit kepadamu untuk menyucikan kamu dengan (hujan) itu dan menghilangkan gangguan-gangguan setan dari dirimu dan untuk menguatkan hatimu serta memperteguh telapak kakimu (teguh pendirian)"},{id:12,text:"\u0625\u0650\u0630\u06e1 \u064a\u064f\u0648\u062d\u0650\u064a \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u0650 \u0623\u064e\u0646\u0651\u0650\u064a \u0645\u064e\u0639\u064e\u0643\u064f\u0645\u06e1 \u0641\u064e\u062b\u064e\u0628\u0651\u0650\u062a\u064f\u0648\u0627\u0652 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652\u06da \u0633\u064e\u0623\u064f\u0644\u06e1\u0642\u0650\u064a \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0671\u0644\u0631\u0651\u064f\u0639\u06e1\u0628\u064e \u0641\u064e\u0671\u0636\u06e1\u0631\u0650\u0628\u064f\u0648\u0627\u0652 \u0641\u064e\u0648\u06e1\u0642\u064e \u0671\u0644\u06e1\u0623\u064e\u0639\u06e1\u0646\u064e\u0627\u0642\u0650 \u0648\u064e\u0671\u0636\u06e1\u0631\u0650\u0628\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0643\u064f\u0644\u0651\u064e \u0628\u064e\u0646\u064e\u0627\u0646\u0656",translation:"(Ingatlah), ketika Tuhanmu mewahyukan kepada para malaikat, \"Sesungguhnya Aku bersama kamu, maka teguhkanlah (pendirian) orang-orang yang telah beriman.\" Kelak akan Aku berikan rasa ketakutan ke dalam hati orang-orang kafir, maka pukullah di atas leher mereka dan pukullah tiap-tiap ujung jari mereka"},{id:13,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0634\u064e\u0627\u0653\u0642\u0651\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f\u06e5\u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0634\u064e\u0627\u0642\u0650\u0642\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f\u06e5 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0634\u064e\u062f\u0650\u064a\u062f\u064f \u0671\u0644\u06e1\u0639\u0650\u0642\u064e\u0627\u0628\u0650",translation:"(Ketentuan) yang demikian itu adalah karena sesungguhnya mereka menentang Allah dan Rasul-Nya; dan barang siapa menentang Allah dan Rasul-Nya, sungguh, Allah sangat keras siksa-Nya"},{id:14,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u06e1 \u0641\u064e\u0630\u064f\u0648\u0642\u064f\u0648\u0647\u064f \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0644\u0650\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650",translation:"Demikianlah (hukuman dunia yang ditimpakan atasmu), maka rasakanlah hukuman itu. Sesungguhnya bagi orang-orang kafir itu ada (lagi) azab neraka"},{id:15,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0630\u064e\u0627 \u0644\u064e\u0642\u0650\u064a\u062a\u064f\u0645\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0632\u064e\u062d\u06e1\u0641\u0657\u0627 \u0641\u064e\u0644\u064e\u0627 \u062a\u064f\u0648\u064e\u0644\u0651\u064f\u0648\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u062f\u06e1\u0628\u064e\u0627\u0631\u064e",translation:"Wahai orang yang beriman! Apabila kamu bertemu dengan orang-orang kafir yang akan menyerangmu, maka janganlah kamu membelakangi mereka (mundur)"},{id:16,text:"\u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0648\u064e\u0644\u0651\u0650\u0647\u0650\u0645\u06e1 \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u062f\u064f\u0628\u064f\u0631\u064e\u0647\u064f\u06e5\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064f\u062a\u064e\u062d\u064e\u0631\u0651\u0650\u0641\u0657\u0627 \u0644\u0651\u0650\u0642\u0650\u062a\u064e\u0627\u0644\u064d \u0623\u064e\u0648\u06e1 \u0645\u064f\u062a\u064e\u062d\u064e\u064a\u0651\u0650\u0632\u064b\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0641\u0650\u0626\u064e\u0629\u0656 \u0641\u064e\u0642\u064e\u062f\u06e1 \u0628\u064e\u0627\u0653\u0621\u064e \u0628\u0650\u063a\u064e\u0636\u064e\u0628\u0656 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u064e\u0623\u06e1\u0648\u064e\u0649\u0670\u0647\u064f \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064f\u06d6 \u0648\u064e\u0628\u0650\u0626\u06e1\u0633\u064e \u0671\u0644\u06e1\u0645\u064e\u0635\u0650\u064a\u0631\u064f",translation:"Dan barang siapa mundur pada waktu itu, kecuali berbelok untuk (siasat) perang atau hendak menggabungkan diri dengan pasukan lain, maka sungguh, orang itu kembali dengan membawa kemurkaan dari Allah. Tempatnya ialah neraka Jahanam, dan seburuk-buruknya tempat kembali"},{id:17,text:"\u0641\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0642\u06e1\u062a\u064f\u0644\u064f\u0648\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0642\u064e\u062a\u064e\u0644\u064e\u0647\u064f\u0645\u06e1\u06da \u0648\u064e\u0645\u064e\u0627 \u0631\u064e\u0645\u064e\u064a\u06e1\u062a\u064e \u0625\u0650\u0630\u06e1 \u0631\u064e\u0645\u064e\u064a\u06e1\u062a\u064e \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0631\u064e\u0645\u064e\u0649\u0670 \u0648\u064e\u0644\u0650\u064a\u064f\u0628\u06e1\u0644\u0650\u064a\u064e \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u06e1\u0647\u064f \u0628\u064e\u0644\u064e\u0627\u0653\u0621\u064b \u062d\u064e\u0633\u064e\u0646\u064b\u0627\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0633\u064e\u0645\u0650\u064a\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Maka (sebenarnya) bukan kamu yang membunuh mereka, melainkan Allah yang membunuh mereka, dan bukan engkau yang melempar ketika engkau melempar, tetapi Allah yang melempar. (Allah berbuat demikian untuk membinasakan mereka) dan untuk memberi kemenangan kepada orang-orang mukmin, dengan kemenangan yang baik. Sungguh, Allah Maha Mendengar, Maha Mengetahui"},{id:18,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064f\u0648\u0647\u0650\u0646\u064f \u0643\u064e\u064a\u06e1\u062f\u0650 \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Demikianlah (karunia Allah yang dilimpahkan kepadamu), dan sungguh, Allah melemahkan tipu daya orang-orang kafir"},{id:19,text:"\u0625\u0650\u0646 \u062a\u064e\u0633\u06e1\u062a\u064e\u0641\u06e1\u062a\u0650\u062d\u064f\u0648\u0627\u0652 \u0641\u064e\u0642\u064e\u062f\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0641\u064e\u062a\u06e1\u062d\u064f\u06d6 \u0648\u064e\u0625\u0650\u0646 \u062a\u064e\u0646\u062a\u064e\u0647\u064f\u0648\u0627\u0652 \u0641\u064e\u0647\u064f\u0648\u064e \u062e\u064e\u064a\u06e1\u0631\u065e \u0644\u0651\u064e\u0643\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0625\u0650\u0646 \u062a\u064e\u0639\u064f\u0648\u062f\u064f\u0648\u0627\u0652 \u0646\u064e\u0639\u064f\u062f\u06e1 \u0648\u064e\u0644\u064e\u0646 \u062a\u064f\u063a\u06e1\u0646\u0650\u064a\u064e \u0639\u064e\u0646\u0643\u064f\u0645\u06e1 \u0641\u0650\u0626\u064e\u062a\u064f\u0643\u064f\u0645\u06e1 \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627 \u0648\u064e\u0644\u064e\u0648\u06e1 \u0643\u064e\u062b\u064f\u0631\u064e\u062a\u06e1 \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064e\u0639\u064e \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Jika kamu meminta keputusan, maka sesungguhnya keputusan telah datang kepadamu; dan jika kamu berhenti (memusuhi rasul), maka itulah yang lebih baik bagimu; dan jika kamu kembali, niscaya Kami kembali (memberi pertolongan); dan pasukanmu tidak akan dapat menolak sesuatu bahaya sedikit pun darimu, biarpun jumlahnya (pasukan) banyak. Sungguh, Allah beserta orang-orang beriman"},{id:20,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f\u06e5 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u06e1\u0627\u0652 \u0639\u064e\u0646\u06e1\u0647\u064f \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0633\u06e1\u0645\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Wahai orang-orang yang beriman! Taatlah kepada Allah dan Rasul-Nya, dan janganlah kamu berpaling dari-Nya, padahal kamu mendengar (perintah-perintah-Nya)"},{id:21,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u0643\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0633\u064e\u0645\u0650\u0639\u06e1\u0646\u064e\u0627 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u0645\u064e\u0639\u064f\u0648\u0646\u064e",translation:"dan janganlah kamu menjadi seperti orang-orang (munafik) yang berkata, \"Kami men\xaddengarkan,\" padahal mereka tidak mendengarkan (karena hati mereka menging\xadka\xadrinya)"},{id:22,text:"\u06de\u0625\u0650\u0646\u0651\u064e \u0634\u064e\u0631\u0651\u064e \u0671\u0644\u062f\u0651\u064e\u0648\u064e\u0627\u0653\u0628\u0651\u0650 \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u0635\u0651\u064f\u0645\u0651\u064f \u0671\u0644\u06e1\u0628\u064f\u0643\u06e1\u0645\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Sesungguhnya makhluk bergerak yang bernyawa yang paling buruk dalam pandangan Allah ialah mereka yang tuli dan bisu (tidak mendengar dan memahami kebenaran) yaitu orang-orang yang tidak mengerti"},{id:23,text:"\u0648\u064e\u0644\u064e\u0648\u06e1 \u0639\u064e\u0644\u0650\u0645\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u0650\u064a\u0647\u0650\u0645\u06e1 \u062e\u064e\u064a\u06e1\u0631\u0657\u0627 \u0644\u0651\u064e\u0623\u064e\u0633\u06e1\u0645\u064e\u0639\u064e\u0647\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0644\u064e\u0648\u06e1 \u0623\u064e\u0633\u06e1\u0645\u064e\u0639\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u0627\u0652 \u0648\u0651\u064e\u0647\u064f\u0645 \u0645\u0651\u064f\u0639\u06e1\u0631\u0650\u0636\u064f\u0648\u0646\u064e",translation:"(Dan sekiranya Allah mengetahui ada kebaikan pada mereka, tentu Dia jadikan mereka dapat mendengar.361) Dan jika Allah menjadikan mereka dapat mendengar, niscaya mereka berpaling, sedang mereka memalingkan diri"},{id:24,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0671\u0633\u06e1\u062a\u064e\u062c\u0650\u064a\u0628\u064f\u0648\u0627\u0652 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u0650\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0650 \u0625\u0650\u0630\u064e\u0627 \u062f\u064e\u0639\u064e\u0627\u0643\u064f\u0645\u06e1 \u0644\u0650\u0645\u064e\u0627 \u064a\u064f\u062d\u06e1\u064a\u0650\u064a\u0643\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0671\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u062d\u064f\u0648\u0644\u064f \u0628\u064e\u064a\u06e1\u0646\u064e \u0671\u0644\u06e1\u0645\u064e\u0631\u06e1\u0621\u0650 \u0648\u064e\u0642\u064e\u0644\u06e1\u0628\u0650\u0647\u0650\u06e6 \u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u06e5\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u062a\u064f\u062d\u06e1\u0634\u064e\u0631\u064f\u0648\u0646\u064e",translation:"(Wahai orang-orang yang beriman! Penuhilah seruan Allah dan Rasul apabila dia menyerumu kepada sesuatu yang memberi kehidupan kepadamu,362) dan ketahuilah bahwa sesungguhnya Allah membatasi antara manusia dan hatinya dan sesungguhnya kepada-Nyalah kamu akan dikumpulkan"},{id:25,text:"\u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0641\u0650\u062a\u06e1\u0646\u064e\u0629\u0657 \u0644\u0651\u064e\u0627 \u062a\u064f\u0635\u0650\u064a\u0628\u064e\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u062e\u064e\u0627\u0653\u0635\u0651\u064e\u0629\u0657\u06d6 \u0648\u064e\u0671\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0634\u064e\u062f\u0650\u064a\u062f\u064f \u0671\u0644\u06e1\u0639\u0650\u0642\u064e\u0627\u0628\u0650",translation:"Dan peliharalah dirimu dari siksaan yang tidak hanya menimpa orang-orang yang zalim saja di antara kamu. Dan ketahuilah bahwa Allah sangat keras siksaan-Nya"},{id:26,text:"\u0648\u064e\u0671\u0630\u06e1\u0643\u064f\u0631\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0630\u06e1 \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0642\u064e\u0644\u0650\u064a\u0644\u065e \u0645\u0651\u064f\u0633\u06e1\u062a\u064e\u0636\u06e1\u0639\u064e\u0641\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u062a\u064e\u062e\u064e\u0627\u0641\u064f\u0648\u0646\u064e \u0623\u064e\u0646 \u064a\u064e\u062a\u064e\u062e\u064e\u0637\u0651\u064e\u0641\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0641\u064e\u0640\u0654\u064e\u0627\u0648\u064e\u0649\u0670\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u064a\u0651\u064e\u062f\u064e\u0643\u064f\u0645 \u0628\u0650\u0646\u064e\u0635\u06e1\u0631\u0650\u0647\u0650\u06e6 \u0648\u064e\u0631\u064e\u0632\u064e\u0642\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0637\u0651\u064e\u064a\u0651\u0650\u0628\u064e\u0670\u062a\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u0634\u06e1\u0643\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Dan ingatlah ketika kamu (para Muhajirin) masih (berjumlah) sedikit, lagi tertindas di bumi (Mekkah), dan kamu takut orang-orang (Mekkah) akan menculik kamu, maka Dia memberi kamu tempat menetap (Madinah) dan dijadikan-Nya kamu kuat dengan pertolongan-Nya dan diberi-Nya kamu rezeki yang baik agar kamu bersyukur"},{id:27,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u062a\u064e\u062e\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e \u0648\u064e\u062a\u064e\u062e\u064f\u0648\u0646\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0645\u064e\u0670\u0646\u064e\u0670\u062a\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Wahai orang-orang yang beriman! Janganlah kamu mengkhianati Allah dan Rasul dan (juga) janganlah kamu mengkhianati amanat yang dipercayakan kepadamu, sedang kamu mengetahui"},{id:28,text:"\u0648\u064e\u0671\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u064f\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0648\u06e1\u0644\u064e\u0670\u062f\u064f\u0643\u064f\u0645\u06e1 \u0641\u0650\u062a\u06e1\u0646\u064e\u0629\u065e \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u0650\u0646\u062f\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u062c\u06e1\u0631\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u065e",translation:"Dan ketahuilah bahwa hartamu dan anak-anakmu itu hanyalah sebagai cobaan dan sesungguhnya di sisi Allah ada pahala yang besar"},{id:29,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u062c\u06e1\u0639\u064e\u0644 \u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u0641\u064f\u0631\u06e1\u0642\u064e\u0627\u0646\u0657\u0627 \u0648\u064e\u064a\u064f\u0643\u064e\u0641\u0651\u0650\u0631\u06e1 \u0639\u064e\u0646\u0643\u064f\u0645\u06e1 \u0633\u064e\u064a\u0651\u0650\u0640\u0654\u064e\u0627\u062a\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u064a\u064e\u063a\u06e1\u0641\u0650\u0631\u06e1 \u0644\u064e\u0643\u064f\u0645\u06e1\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0630\u064f\u0648 \u0671\u0644\u06e1\u0641\u064e\u0636\u06e1\u0644\u0650 \u0671\u0644\u06e1\u0639\u064e\u0638\u0650\u064a\u0645\u0650",translation:"Wahai orang-orang yang beriman! Jika kamu bertakwa kepada Allah, niscaya Dia akan memberikan furq\u0101n (kemampuan membedakan antara yang hak dan batil) kepadamu dan menghapus segala kesalahanmu dan mengampuni (dosa-dosa)mu. Allah memiliki karunia yang besar"},{id:30,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u064a\u064e\u0645\u06e1\u0643\u064f\u0631\u064f \u0628\u0650\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0644\u0650\u064a\u064f\u062b\u06e1\u0628\u0650\u062a\u064f\u0648\u0643\u064e \u0623\u064e\u0648\u06e1 \u064a\u064e\u0642\u06e1\u062a\u064f\u0644\u064f\u0648\u0643\u064e \u0623\u064e\u0648\u06e1 \u064a\u064f\u062e\u06e1\u0631\u0650\u062c\u064f\u0648\u0643\u064e\u06da \u0648\u064e\u064a\u064e\u0645\u06e1\u0643\u064f\u0631\u064f\u0648\u0646\u064e \u0648\u064e\u064a\u064e\u0645\u06e1\u0643\u064f\u0631\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06d6 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u062e\u064e\u064a\u06e1\u0631\u064f \u0671\u0644\u06e1\u0645\u064e\u0670\u0643\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan (ingatlah), ketika orang-orang kafir (Quraisy) memikirkan tipu daya terhadapmu (Muhammad) untuk menangkap dan memenjarakanmu atau membunuhmu, atau mengusirmu. Mereka membuat tipu daya dan Allah menggagalkan tipu daya itu. Allah adalah sebaik-baik pembalas tipu daya"},{id:31,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062a\u064f\u062a\u06e1\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u064f\u0646\u064e\u0627 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0642\u064e\u062f\u06e1 \u0633\u064e\u0645\u0650\u0639\u06e1\u0646\u064e\u0627 \u0644\u064e\u0648\u06e1 \u0646\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0644\u064e\u0642\u064f\u0644\u06e1\u0646\u064e\u0627 \u0645\u0650\u062b\u06e1\u0644\u064e \u0647\u064e\u0670\u0630\u064e\u0627\u0653 \u0625\u0650\u0646\u06e1 \u0647\u064e\u0670\u0630\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0633\u064e\u0670\u0637\u0650\u064a\u0631\u064f \u0671\u0644\u06e1\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",translation:"Dan apabila ayat-ayat Kami dibacakan kepada mereka, mereka berkata, \"Sesungguhnya kami telah mendengar (ayat-ayat seperti ini), jika kami menghendaki niscaya kami dapat membacakan yang seperti ini. (Alquran) ini tidak lain hanyalah dongeng orang-orang terdahulu"},{id:32,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064e \u0645\u0650\u0646\u06e1 \u0639\u0650\u0646\u062f\u0650\u0643\u064e \u0641\u064e\u0623\u064e\u0645\u06e1\u0637\u0650\u0631\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u062d\u0650\u062c\u064e\u0627\u0631\u064e\u0629\u0657 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0623\u064e\u0648\u0650 \u0671\u0626\u06e1\u062a\u0650\u0646\u064e\u0627 \u0628\u0650\u0639\u064e\u0630\u064e\u0627\u0628\u064d \u0623\u064e\u0644\u0650\u064a\u0645\u0656",translation:"Dan (ingatlah), ketika mereka (orang-orang musyrik) berkata, \"Ya Allah, jika (Alquran) ini benar (wahyu) dari Engkau, maka hujanilah kami dengan batu dari langit, atau datangkanlah kepada kami azab yang pedih"},{id:33,text:"\u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0646\u062a\u064e \u0641\u0650\u064a\u0647\u0650\u0645\u06e1\u06da \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0633\u06e1\u062a\u064e\u063a\u06e1\u0641\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Tetapi Allah tidak akan menghukum mereka, selama engkau (Muhammad) berada di antara mereka. Dan tidaklah (pula) Allah akan menghukum mereka, sedang mereka (masih) memohon ampunan"},{id:34,text:"\u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u0644\u0651\u064e\u0627 \u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0635\u064f\u062f\u0651\u064f\u0648\u0646\u064e \u0639\u064e\u0646\u0650 \u0671\u0644\u06e1\u0645\u064e\u0633\u06e1\u062c\u0650\u062f\u0650 \u0671\u0644\u06e1\u062d\u064e\u0631\u064e\u0627\u0645\u0650 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0648\u06e1\u0644\u0650\u064a\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u06e5\u0653\u06da \u0625\u0650\u0646\u06e1 \u0623\u064e\u0648\u06e1\u0644\u0650\u064a\u064e\u0627\u0653\u0624\u064f\u0647\u064f\u06e5\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan mengapa Allah tidak menghukum mereka padahal mereka menghalang-halangi (orang) untuk (mendatangi) Masjidilharam dan mereka bukanlah orang-orang yang berhak menguasainya? Orang yang berhak menguasai(nya), hanyalah orang-orang yang bertakwa, tetapi kebanyakan mereka tidak mengetahui"},{id:35,text:"\u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0635\u064e\u0644\u064e\u0627\u062a\u064f\u0647\u064f\u0645\u06e1 \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u06e1\u0628\u064e\u064a\u06e1\u062a\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064f\u0643\u064e\u0627\u0653\u0621\u0657 \u0648\u064e\u062a\u064e\u0635\u06e1\u062f\u0650\u064a\u064e\u0629\u0657\u06da \u0641\u064e\u0630\u064f\u0648\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0643\u06e1\u0641\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Dan salat mereka di sekitar Baitullah itu, tidak lain hanyalah siulan dan tepuk tangan. Maka rasakanlah azab disebabkan kekafiranmu itu"},{id:36,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u064a\u064f\u0646\u0641\u0650\u0642\u064f\u0648\u0646\u064e \u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u064e\u0647\u064f\u0645\u06e1 \u0644\u0650\u064a\u064e\u0635\u064f\u062f\u0651\u064f\u0648\u0627\u0652 \u0639\u064e\u0646 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0641\u064e\u0633\u064e\u064a\u064f\u0646\u0641\u0650\u0642\u064f\u0648\u0646\u064e\u0647\u064e\u0627 \u062b\u064f\u0645\u0651\u064e \u062a\u064e\u0643\u064f\u0648\u0646\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u062d\u064e\u0633\u06e1\u0631\u064e\u0629\u0657 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u063a\u06e1\u0644\u064e\u0628\u064f\u0648\u0646\u064e\u06d7 \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u064a\u064f\u062d\u06e1\u0634\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Sesungguhnya orang-orang kafir itu, menginfakkan harta mereka untuk menghalang-halangi (orang) dari jalan Allah. Mereka akan (terus) menginfakkan harta itu, kemudian mereka akan menyesal sendiri, dan akhirnya mereka akan dikalahkan. Ke dalam neraka Jahanamlah orang-orang kafir itu akan dikumpulkan"},{id:37,text:"\u0644\u0650\u064a\u064e\u0645\u0650\u064a\u0632\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u062e\u064e\u0628\u0650\u064a\u062b\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0637\u0651\u064e\u064a\u0651\u0650\u0628\u0650 \u0648\u064e\u064a\u064e\u062c\u06e1\u0639\u064e\u0644\u064e \u0671\u0644\u06e1\u062e\u064e\u0628\u0650\u064a\u062b\u064e \u0628\u064e\u0639\u06e1\u0636\u064e\u0647\u064f\u06e5 \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u06e1\u0636\u0656 \u0641\u064e\u064a\u064e\u0631\u06e1\u0643\u064f\u0645\u064e\u0647\u064f\u06e5 \u062c\u064e\u0645\u0650\u064a\u0639\u0657\u0627 \u0641\u064e\u064a\u064e\u062c\u06e1\u0639\u064e\u0644\u064e\u0647\u064f\u06e5 \u0641\u0650\u064a \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e\u06da \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u062e\u064e\u0670\u0633\u0650\u0631\u064f\u0648\u0646\u064e",translation:"agar Allah memisahkan (golongan) yang buruk dari yang baik dan menjadikan (golongan) yang buruk itu sebagiannya di atas yang lain, lalu kesemuanya ditumpukkan-Nya, dan dimasukkan-Nya ke dalam neraka Jahanam. Mereka itulah orang-orang yang rugi"},{id:38,text:"\u0642\u064f\u0644 \u0644\u0651\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646 \u064a\u064e\u0646\u062a\u064e\u0647\u064f\u0648\u0627\u0652 \u064a\u064f\u063a\u06e1\u0641\u064e\u0631\u06e1 \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u0627 \u0642\u064e\u062f\u06e1 \u0633\u064e\u0644\u064e\u0641\u064e \u0648\u064e\u0625\u0650\u0646 \u064a\u064e\u0639\u064f\u0648\u062f\u064f\u0648\u0627\u0652 \u0641\u064e\u0642\u064e\u062f\u06e1 \u0645\u064e\u0636\u064e\u062a\u06e1 \u0633\u064f\u0646\u0651\u064e\u062a\u064f \u0671\u0644\u06e1\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",translation:"Katakanlah kepada orang-orang yang kafir itu (Abu Sufyan dan kawan-kawannya), \"Jika mereka berhenti (dari kekafirannya), niscaya Allah akan mengampuni dosa-dosa mereka yang telah lalu; dan jika mereka kembali lagi (memerangi Nabi) sungguh, berlaku (kepada mereka) sunah (Allah terhadap) orang-orang dahulu (dibinasakan)"},{id:39,text:"\u0648\u064e\u0642\u064e\u0670\u062a\u0650\u0644\u064f\u0648\u0647\u064f\u0645\u06e1 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0641\u0650\u062a\u06e1\u0646\u064e\u0629\u065e \u0648\u064e\u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u064f \u0643\u064f\u0644\u0651\u064f\u0647\u064f\u06e5 \u0644\u0650\u0644\u0651\u064e\u0647\u0650\u06da \u0641\u064e\u0625\u0650\u0646\u0650 \u0671\u0646\u062a\u064e\u0647\u064e\u0648\u06e1\u0627\u0652 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u0645\u064e\u0627 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0628\u064e\u0635\u0650\u064a\u0631\u065e",translation:"Dan perangilah mereka itu sampai tidak ada lagi fitnah dan agama hanya bagi Allah semata. Jika mereka berhenti (dari kekafiran), maka sesungguhnya Allah Maha Melihat apa yang mereka kerjakan"},{id:40,text:"\u0648\u064e\u0625\u0650\u0646 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u06e1\u0627\u0652 \u0641\u064e\u0671\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064e\u0648\u06e1\u0644\u064e\u0649\u0670\u0643\u064f\u0645\u06e1\u06da \u0646\u0650\u0639\u06e1\u0645\u064e \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u0644\u064e\u0649\u0670 \u0648\u064e\u0646\u0650\u0639\u06e1\u0645\u064e \u0671\u0644\u0646\u0651\u064e\u0635\u0650\u064a\u0631\u064f",translation:"Dan jika mereka berpaling, maka ketahuilah bahwa sesungguhnya Allah Pelindungmu. Dia adalah sebaik-baik Pelindung dan sebaik-baik Penolong"},{id:41,text:"\u06de\u0648\u064e\u0671\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u063a\u064e\u0646\u0650\u0645\u06e1\u062a\u064f\u0645 \u0645\u0651\u0650\u0646 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0641\u064e\u0623\u064e\u0646\u0651\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u062e\u064f\u0645\u064f\u0633\u064e\u0647\u064f\u06e5 \u0648\u064e\u0644\u0650\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0650 \u0648\u064e\u0644\u0650\u0630\u0650\u064a \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0628\u064e\u0649\u0670 \u0648\u064e\u0671\u0644\u06e1\u064a\u064e\u062a\u064e\u0670\u0645\u064e\u0649\u0670 \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u0633\u064e\u0670\u0643\u0650\u064a\u0646\u0650 \u0648\u064e\u0671\u0628\u06e1\u0646\u0650 \u0671\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u0650 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0621\u064e\u0627\u0645\u064e\u0646\u062a\u064f\u0645 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0639\u064e\u0628\u06e1\u062f\u0650\u0646\u064e\u0627 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0641\u064f\u0631\u06e1\u0642\u064e\u0627\u0646\u0650 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u062a\u064e\u0642\u064e\u0649 \u0671\u0644\u06e1\u062c\u064e\u0645\u06e1\u0639\u064e\u0627\u0646\u0650\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0642\u064e\u062f\u0650\u064a\u0631\u064c",translation:"(Dan ketahuilah, sesungguhnya segala yang kamu peroleh sebagai rampasan perang,363) maka seperlima untuk Allah, Rasul, kerabat Rasul, anak yatim, orang miskin dan ibnu sabil,364) (demikian) jika kamu beriman kepada Allah dan kepada apa yang Kami turunkan kepada hamba Kami (Muhammad) di hari furqan,365) yaitu pada hari bertemunya dua pasukan. Dan Allah Mahakuasa atas segala sesuatu"},{id:42,text:"\u0625\u0650\u0630\u06e1 \u0623\u064e\u0646\u062a\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0639\u064f\u062f\u06e1\u0648\u064e\u0629\u0650 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0648\u064e\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0639\u064f\u062f\u06e1\u0648\u064e\u0629\u0650 \u0671\u0644\u06e1\u0642\u064f\u0635\u06e1\u0648\u064e\u0649\u0670 \u0648\u064e\u0671\u0644\u0631\u0651\u064e\u0643\u06e1\u0628\u064f \u0623\u064e\u0633\u06e1\u0641\u064e\u0644\u064e \u0645\u0650\u0646\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0644\u064e\u0648\u06e1 \u062a\u064e\u0648\u064e\u0627\u0639\u064e\u062f\u062a\u0651\u064f\u0645\u06e1 \u0644\u064e\u0671\u062e\u06e1\u062a\u064e\u0644\u064e\u0641\u06e1\u062a\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0645\u0650\u064a\u0639\u064e\u0670\u062f\u0650 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u0644\u0651\u0650\u064a\u064e\u0642\u06e1\u0636\u0650\u064a\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0645\u06e1\u0631\u0657\u0627 \u0643\u064e\u0627\u0646\u064e \u0645\u064e\u0641\u06e1\u0639\u064f\u0648\u0644\u0657\u0627 \u0644\u0651\u0650\u064a\u064e\u0647\u06e1\u0644\u0650\u0643\u064e \u0645\u064e\u0646\u06e1 \u0647\u064e\u0644\u064e\u0643\u064e \u0639\u064e\u0646\u06e2 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0629\u0656 \u0648\u064e\u064a\u064e\u062d\u06e1\u064a\u064e\u0649\u0670 \u0645\u064e\u0646\u06e1 \u062d\u064e\u064a\u0651\u064e \u0639\u064e\u0646\u06e2 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0629\u0656\u06d7 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0633\u064e\u0645\u0650\u064a\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u064c",translation:"(Yaitu) ketika kamu berada di pinggir lembah yang dekat dan mereka berada di pinggir lembah yang jauh sedang kafilah itu berada lebih rendah dari kamu.366) Sekiranya kamu mengadakan persetujuan (untuk menentukan hari pertempuran), niscaya kamu berbeda pendapat dalam menentukan (hari pertempuran itu), tetapi Allah berkehendak melaksanakan suatu urusan yang harus dilaksanakan,367) yaitu agar orang yang binasa itu binasa dengan bukti yang nyata dan agar orang yang hidup itu hidup dengan bukti yang nyata. Sungguh, Allah Maha Mendengar, Maha Mengetahui"},{id:43,text:"\u0625\u0650\u0630\u06e1 \u064a\u064f\u0631\u0650\u064a\u0643\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u0650\u064a \u0645\u064e\u0646\u064e\u0627\u0645\u0650\u0643\u064e \u0642\u064e\u0644\u0650\u064a\u0644\u0657\u0627\u06d6 \u0648\u064e\u0644\u064e\u0648\u06e1 \u0623\u064e\u0631\u064e\u0649\u0670\u0643\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u062b\u0650\u064a\u0631\u0657\u0627 \u0644\u0651\u064e\u0641\u064e\u0634\u0650\u0644\u06e1\u062a\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u062a\u064e\u0646\u064e\u0670\u0632\u064e\u0639\u06e1\u062a\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0631\u0650 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0633\u064e\u0644\u0651\u064e\u0645\u064e\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0639\u064e\u0644\u0650\u064a\u0645\u064f\u06e2 \u0628\u0650\u0630\u064e\u0627\u062a\u0650 \u0671\u0644\u0635\u0651\u064f\u062f\u064f\u0648\u0631\u0650",translation:"(ingatlah) ketika Allah memperlihatkan mereka di dalam mimpimu (berjumlah) sedikit. Dan sekiranya Allah memperlihatkan mereka (berjumlah) banyak tentu kamu menjadi gentar dan tentu kamu akan berbantah-bantahan dalam urusan itu, tetapi Allah telah menyelamatkan kamu. Sungguh, Allah Maha Mengetahui apa yang ada dalam hatimu"},{id:44,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u064a\u064f\u0631\u0650\u064a\u0643\u064f\u0645\u064f\u0648\u0647\u064f\u0645\u06e1 \u0625\u0650\u0630\u0650 \u0671\u0644\u06e1\u062a\u064e\u0642\u064e\u064a\u06e1\u062a\u064f\u0645\u06e1 \u0641\u0650\u064a\u0653 \u0623\u064e\u0639\u06e1\u064a\u064f\u0646\u0650\u0643\u064f\u0645\u06e1 \u0642\u064e\u0644\u0650\u064a\u0644\u0657\u0627 \u0648\u064e\u064a\u064f\u0642\u064e\u0644\u0651\u0650\u0644\u064f\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a\u0653 \u0623\u064e\u0639\u06e1\u064a\u064f\u0646\u0650\u0647\u0650\u0645\u06e1 \u0644\u0650\u064a\u064e\u0642\u06e1\u0636\u0650\u064a\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0645\u06e1\u0631\u0657\u0627 \u0643\u064e\u0627\u0646\u064e \u0645\u064e\u0641\u06e1\u0639\u064f\u0648\u0644\u0657\u0627\u06d7 \u0648\u064e\u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064f\u0631\u06e1\u062c\u064e\u0639\u064f \u0671\u0644\u06e1\u0623\u064f\u0645\u064f\u0648\u0631\u064f",translation:"Dan ketika Allah memperlihatkan mereka kepadamu, ketika kamu berjumpa dengan mereka berjumlah sedikit menurut penglihatan matamu dan kamu diperlihatkan-Nya berjumlah sedikit menurut penglihatan mereka, itu karena Allah hendak melakukan suatu urusan yang harus dilaksanakan. Hanya kepada Allah segala urusan dikembalikan"},{id:45,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0630\u064e\u0627 \u0644\u064e\u0642\u0650\u064a\u062a\u064f\u0645\u06e1 \u0641\u0650\u0626\u064e\u0629\u0657 \u0641\u064e\u0671\u062b\u06e1\u0628\u064f\u062a\u064f\u0648\u0627\u0652 \u0648\u064e\u0671\u0630\u06e1\u0643\u064f\u0631\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u0657\u0627 \u0644\u0651\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064f\u0641\u06e1\u0644\u0650\u062d\u064f\u0648\u0646\u064e",translation:"Wahai orang-orang yang beriman! Apabila kamu bertemu pasukan (musuh), maka berteguh hatilah dan sebutlah (nama) Allah banyak-banyak (berzikir dan berdoa) agar kamu beruntung"},{id:46,text:"\u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f\u06e5 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0646\u064e\u0670\u0632\u064e\u0639\u064f\u0648\u0627\u0652 \u0641\u064e\u062a\u064e\u0641\u06e1\u0634\u064e\u0644\u064f\u0648\u0627\u0652 \u0648\u064e\u062a\u064e\u0630\u06e1\u0647\u064e\u0628\u064e \u0631\u0650\u064a\u062d\u064f\u0643\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0671\u0635\u06e1\u0628\u0650\u0631\u064f\u0648\u0653\u0627\u0652\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064e\u0639\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0628\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan taatilah Allah dan Rasul-Nya dan janganlah kamu berselisih, yang menyebabkan kamu menjadi gentar dan kekuatanmu hilang dan bersabarlah. Sungguh, Allah bersama orang-orang sabar"},{id:47,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u0643\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062e\u064e\u0631\u064e\u062c\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u062f\u0650\u064a\u064e\u0670\u0631\u0650\u0647\u0650\u0645 \u0628\u064e\u0637\u064e\u0631\u0657\u0627 \u0648\u064e\u0631\u0650\u0626\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u064a\u064e\u0635\u064f\u062f\u0651\u064f\u0648\u0646\u064e \u0639\u064e\u0646 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0645\u064f\u062d\u0650\u064a\u0637\u065e",translation:"Dan janganlah kamu seperti orang-orang yang keluar dari kampung halamannya dengan rasa angkuh dan ingin dipuji orang (ria) serta menghalang-halangi (orang) dari jalan Allah. Allah meliputi segala yang mereka kerjakan"},{id:48,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0632\u064e\u064a\u0651\u064e\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u064f \u0623\u064e\u0639\u06e1\u0645\u064e\u0670\u0644\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0627 \u063a\u064e\u0627\u0644\u0650\u0628\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0625\u0650\u0646\u0651\u0650\u064a \u062c\u064e\u0627\u0631\u065e \u0644\u0651\u064e\u0643\u064f\u0645\u06e1\u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062a\u064e\u0631\u064e\u0627\u0653\u0621\u064e\u062a\u0650 \u0671\u0644\u06e1\u0641\u0650\u0626\u064e\u062a\u064e\u0627\u0646\u0650 \u0646\u064e\u0643\u064e\u0635\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0639\u064e\u0642\u0650\u0628\u064e\u064a\u06e1\u0647\u0650 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0628\u064e\u0631\u0650\u064a\u0653\u0621\u065e \u0645\u0651\u0650\u0646\u0643\u064f\u0645\u06e1 \u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064e\u0631\u064e\u0649\u0670 \u0645\u064e\u0627 \u0644\u064e\u0627 \u062a\u064e\u0631\u064e\u0648\u06e1\u0646\u064e \u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064e\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0634\u064e\u062f\u0650\u064a\u062f\u064f \u0671\u0644\u06e1\u0639\u0650\u0642\u064e\u0627\u0628\u0650",translation:"Dan (ingatlah) ketika setan menjadikan terasa indah bagi mereka perbuatan (dosa) mereka dan mengatakan, \"Tidak ada (orang) yang dapat mengalahkan kamu pada hari ini, dan sungguh, aku adalah penolongmu\". Maka ketika kedua pasukan itu telah saling melihat (berhadapan), setan balik ke belakang seraya berkata, \"Sesungguhnya aku berlepas diri dari kamu; aku dapat melihat apa yang kamu tidak dapat melihat; sesungguhnya aku takut kepada Allah.\" Allah sangat keras siksa-Nya"},{id:49,text:"\u0625\u0650\u0630\u06e1 \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0671\u0644\u06e1\u0645\u064f\u0646\u064e\u0670\u0641\u0650\u0642\u064f\u0648\u0646\u064e \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645 \u0645\u0651\u064e\u0631\u064e\u0636\u064c \u063a\u064e\u0631\u0651\u064e \u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650 \u062f\u0650\u064a\u0646\u064f\u0647\u064f\u0645\u06e1\u06d7 \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u06e1 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0632\u0650\u064a\u0632\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u065e",translation:"(Ingatlah), ketika orang-orang munafik dan orang-orang yang ada penyakit di dalam hatinya berkata, \"Mereka itu (orang mukmin) ditipu agamanya.\" (Allah berfirman), \"Barang siapa bertawakal kepada Allah, ketahuilah bahwa Allah Mahaperkasa, Mahabijaksana"},{id:50,text:"\u0648\u064e\u0644\u064e\u0648\u06e1 \u062a\u064e\u0631\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u06e1 \u064a\u064e\u062a\u064e\u0648\u064e\u0641\u0651\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u064f \u064a\u064e\u0636\u06e1\u0631\u0650\u0628\u064f\u0648\u0646\u064e \u0648\u064f\u062c\u064f\u0648\u0647\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u062f\u06e1\u0628\u064e\u0670\u0631\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0630\u064f\u0648\u0642\u064f\u0648\u0627\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0671\u0644\u06e1\u062d\u064e\u0631\u0650\u064a\u0642\u0650",translation:"Dan sekiranya kamu melihat ketika para malaikat mencabut nyawa orang-orang yang kafir sambil memukul wajah dan punggung mereka (dan berkata), \"Rasakanlah olehmu siksa neraka yang membakar"},{id:51,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0645\u064e\u0627 \u0642\u064e\u062f\u0651\u064e\u0645\u064e\u062a\u06e1 \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u064a\u06e1\u0633\u064e \u0628\u0650\u0638\u064e\u0644\u0651\u064e\u0640\u0670\u0645\u0656 \u0644\u0651\u0650\u0644\u06e1\u0639\u064e\u0628\u0650\u064a\u062f\u0650",translation:"Demikian itu disebabkan oleh perbuatan tanganmu sendiri. Dan sesungguhnya Allah tidak menzalimi hamba-hamba-Nya"},{id:52,text:"\u0643\u064e\u062f\u064e\u0623\u06e1\u0628\u0650 \u0621\u064e\u0627\u0644\u0650 \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u0645\u06e1\u06da \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0623\u064e\u062e\u064e\u0630\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0630\u064f\u0646\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0642\u064e\u0648\u0650\u064a\u0651\u065e \u0634\u064e\u062f\u0650\u064a\u062f\u064f \u0671\u0644\u06e1\u0639\u0650\u0642\u064e\u0627\u0628\u0650",translation:"(Keadaan mereka) serupa dengan keadaan pengikut Fir'aun dan orang-orang yang sebelum mereka. Mereka mengingkari ayat-ayat Allah, maka Allah menyiksa mereka disebabkan dosa-dosanya. Sungguh, Allah Maha Kuat lagi sangat keras siksa-Nya"},{id:53,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0645\u06e1 \u064a\u064e\u0643\u064f \u0645\u064f\u063a\u064e\u064a\u0651\u0650\u0631\u0657\u0627 \u0646\u0651\u0650\u0639\u06e1\u0645\u064e\u0629\u064b \u0623\u064e\u0646\u06e1\u0639\u064e\u0645\u064e\u0647\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u06e1\u0645\u064d \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064f\u063a\u064e\u064a\u0651\u0650\u0631\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u0628\u0650\u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0633\u064e\u0645\u0650\u064a\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Yang demikian itu karena sesungguhnya Allah tidak akan mengubah suatu nikmat yang telah diberikan-Nya kepada suatu kaum, hingga kaum itu mengubah apa yang ada pada diri mereka sendiri. Sungguh, Allah Maha Mendengar, Maha Mengetahui"},{id:54,text:"\u0643\u064e\u062f\u064e\u0623\u06e1\u0628\u0650 \u0621\u064e\u0627\u0644\u0650 \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u0645\u06e1\u06da \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0641\u064e\u0623\u064e\u0647\u06e1\u0644\u064e\u0643\u06e1\u0646\u064e\u0670\u0647\u064f\u0645 \u0628\u0650\u0630\u064f\u0646\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0623\u064e\u063a\u06e1\u0631\u064e\u0642\u06e1\u0646\u064e\u0627\u0653 \u0621\u064e\u0627\u0644\u064e \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e\u06da \u0648\u064e\u0643\u064f\u0644\u0651\u065e \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0638\u064e\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"(Keadaan mereka) serupa dengan keadaan pengikut Fir'aun dan orang-orang yang sebelum mereka. Mereka mendustakan ayat-ayat Tuhannya, maka Kami membinasakan mereka disebabkan oleh dosa-dosanya dan Kami tenggelamkan Fir'aun dan pengikut-pengikutnya; karena mereka adalah orang-orang yang zalim"},{id:55,text:"\u0625\u0650\u0646\u0651\u064e \u0634\u064e\u0631\u0651\u064e \u0671\u0644\u062f\u0651\u064e\u0648\u064e\u0627\u0653\u0628\u0651\u0650 \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0641\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Sesungguhnya makhluk paling buruk di sisi Allah ialah orang-orang kafir, karena mereka tidak beriman"},{id:56,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0639\u064e\u0670\u0647\u064e\u062f\u062a\u0651\u064e \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u0646\u0642\u064f\u0636\u064f\u0648\u0646\u064e \u0639\u064e\u0647\u06e1\u062f\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0643\u064f\u0644\u0651\u0650 \u0645\u064e\u0631\u0651\u064e\u0629\u0656 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",translation:"(Yaitu) orang-orang yang terikat perjanjian dengan kamu, kemudian setiap kali berjanji mereka mengkhianati janjinya, sedang mereka tidak takut (kepada Allah)"},{id:57,text:"\u0641\u064e\u0625\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u062b\u06e1\u0642\u064e\u0641\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u062d\u064e\u0631\u06e1\u0628\u0650 \u0641\u064e\u0634\u064e\u0631\u0651\u0650\u062f\u06e1 \u0628\u0650\u0647\u0650\u0645 \u0645\u0651\u064e\u0646\u06e1 \u062e\u064e\u0644\u06e1\u0641\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0630\u0651\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Jika engkau (Muhammad) mengungguli mereka dalam peperangan, maka cerai-beraikanlah orang-orang yang di belakang mereka dengan (menumpas) mereka, agar mereka mengambil pelajaran"},{id:58,text:"\u0648\u064e\u0625\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u062e\u064e\u0627\u0641\u064e\u0646\u0651\u064e \u0645\u0650\u0646 \u0642\u064e\u0648\u06e1\u0645\u064d \u062e\u0650\u064a\u064e\u0627\u0646\u064e\u0629\u0657 \u0641\u064e\u0671\u0646\u06e2\u0628\u0650\u0630\u06e1 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0633\u064e\u0648\u064e\u0627\u0653\u0621\u064d\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0671\u0644\u06e1\u062e\u064e\u0627\u0653\u0626\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dan jika engkau (Muhammad) khawatir akan (terjadinya) pengkhianatan dari suatu golongan, maka kembalikanlah perjanjian itu kepada mereka dengan cara yang jujur. Sungguh, Allah tidak menyukai orang yang berkhianat"},{id:59,text:"\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062d\u06e1\u0633\u064e\u0628\u064e\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0633\u064e\u0628\u064e\u0642\u064f\u0648\u0653\u0627\u0652\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064f\u0639\u06e1\u062c\u0650\u0632\u064f\u0648\u0646\u064e",translation:"Dan janganlah orang-orang kafir mengira, bahwa mereka akan dapat lolos (dari kekuasaan Allah). Sungguh, mereka tidak dapat melemahkan (Allah)"},{id:60,text:"\u0648\u064e\u0623\u064e\u0639\u0650\u062f\u0651\u064f\u0648\u0627\u0652 \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u0627 \u0671\u0633\u06e1\u062a\u064e\u0637\u064e\u0639\u06e1\u062a\u064f\u0645 \u0645\u0651\u0650\u0646 \u0642\u064f\u0648\u0651\u064e\u0629\u0656 \u0648\u064e\u0645\u0650\u0646 \u0631\u0651\u0650\u0628\u064e\u0627\u0637\u0650 \u0671\u0644\u06e1\u062e\u064e\u064a\u06e1\u0644\u0650 \u062a\u064f\u0631\u06e1\u0647\u0650\u0628\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u0650\u06e6 \u0639\u064e\u062f\u064f\u0648\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0639\u064e\u062f\u064f\u0648\u0651\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0621\u064e\u0627\u062e\u064e\u0631\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u0645\u06e1 \u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0647\u064f\u0645\u06e1\u06da \u0648\u064e\u0645\u064e\u0627 \u062a\u064f\u0646\u0641\u0650\u0642\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064f\u0648\u064e\u0641\u0651\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0644\u064e\u0627 \u062a\u064f\u0638\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan persiapkanlah dengan segala kemampuan untuk menghadapi mereka dengan kekuatan yang kamu miliki dan dari pasukan berkuda yang dapat menggentarkan musuh Allah, musuhmu dan orang-orang selain mereka yang kamu tidak mengetahuinya; tetapi Allah mengetahuinya. Apa saja yang kamu infakkan di jalan Allah niscaya akan dibalas dengan cukup kepadamu dan kamu tidak akan dizalimi (dirugikan)"},{id:61,text:"\u06de\u0648\u064e\u0625\u0650\u0646 \u062c\u064e\u0646\u064e\u062d\u064f\u0648\u0627\u0652 \u0644\u0650\u0644\u0633\u0651\u064e\u0644\u06e1\u0645\u0650 \u0641\u064e\u0671\u062c\u06e1\u0646\u064e\u062d\u06e1 \u0644\u064e\u0647\u064e\u0627 \u0648\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u06e1 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0647\u064f\u0648\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u0650\u064a\u0639\u064f \u0671\u0644\u06e1\u0639\u064e\u0644\u0650\u064a\u0645\u064f",translation:"Tetapi jika mereka condong kepada perdamaian, maka terimalah dan bertawakallah kepada Allah. Sungguh, Dia Maha Mendengar, Maha Mengetahui"},{id:62,text:"\u0648\u064e\u0625\u0650\u0646 \u064a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646 \u064a\u064e\u062e\u06e1\u062f\u064e\u0639\u064f\u0648\u0643\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u062d\u064e\u0633\u06e1\u0628\u064e\u0643\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06da \u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064e\u064a\u0651\u064e\u062f\u064e\u0643\u064e \u0628\u0650\u0646\u064e\u0635\u06e1\u0631\u0650\u0647\u0650\u06e6 \u0648\u064e\u0628\u0650\u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dan jika mereka hendak menipumu, maka sesungguhnya cukuplah Allah (menjadi pelindung) bagimu. Dialah yang memberikan kekuatan kepadamu dengan pertolongan-Nya dan dengan (dukungan) orang-orang mukmin"},{id:63,text:"\u0648\u064e\u0623\u064e\u0644\u0651\u064e\u0641\u064e \u0628\u064e\u064a\u06e1\u0646\u064e \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u06e1\u06da \u0644\u064e\u0648\u06e1 \u0623\u064e\u0646\u0641\u064e\u0642\u06e1\u062a\u064e \u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u062c\u064e\u0645\u0650\u064a\u0639\u0657\u0627 \u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u0644\u0651\u064e\u0641\u06e1\u062a\u064e \u0628\u064e\u064a\u06e1\u0646\u064e \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0623\u064e\u0644\u0651\u064e\u0641\u064e \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0639\u064e\u0632\u0650\u064a\u0632\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u065e",translation:"dan Dia (Allah) yang mempersatukan hati mereka (orang yang beriman). Walaupun kamu menginfakkan semua (kekayaan) yang berada di bumi, niscaya kamu tidak dapat mempersatukan hati mereka, tetapi Allah telah mempersatukan hati mereka. Sungguh, Dia Mahaperkasa, Mahabijaksana"},{id:64,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064f \u062d\u064e\u0633\u06e1\u0628\u064f\u0643\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0645\u064e\u0646\u0650 \u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Wahai Nabi (Muhammad)! Cukuplah Allah (menjadi pelindung) bagimu dan bagi orang-orang mukmin yang mengikutimu"},{id:65,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064f \u062d\u064e\u0631\u0651\u0650\u0636\u0650 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0642\u0650\u062a\u064e\u0627\u0644\u0650\u06da \u0625\u0650\u0646 \u064a\u064e\u0643\u064f\u0646 \u0645\u0651\u0650\u0646\u0643\u064f\u0645\u06e1 \u0639\u0650\u0634\u06e1\u0631\u064f\u0648\u0646\u064e \u0635\u064e\u0670\u0628\u0650\u0631\u064f\u0648\u0646\u064e \u064a\u064e\u063a\u06e1\u0644\u0650\u0628\u064f\u0648\u0627\u0652 \u0645\u0650\u0627\u0652\u0626\u064e\u062a\u064e\u064a\u06e1\u0646\u0650\u06da \u0648\u064e\u0625\u0650\u0646 \u064a\u064e\u0643\u064f\u0646 \u0645\u0651\u0650\u0646\u0643\u064f\u0645 \u0645\u0651\u0650\u0627\u0652\u0626\u064e\u0629\u065e \u064a\u064e\u063a\u06e1\u0644\u0650\u0628\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0644\u06e1\u0641\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0642\u064e\u0648\u06e1\u0645\u065e \u0644\u0651\u064e\u0627 \u064a\u064e\u0641\u06e1\u0642\u064e\u0647\u064f\u0648\u0646\u064e",translation:"Wahai Nabi (Muhammad)! Kobarkanlah semangat para mukmin untuk berperang. Jika ada dua puluh orang yang sabar di antara kamu, niscaya mereka dapat mengalahkan dua ratus orang musuh. Dan jika ada seratus orang (yang sabar) di antara kamu, niscaya mereka dapat mengalahkan seribu orang kafir, karena orang-orang kafir itu adalah kaum yang tidak mengerti"},{id:66,text:"\u0671\u0644\u06e1\u0640\u0654\u064e\u0670\u0646\u064e \u062e\u064e\u0641\u0651\u064e\u0641\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0646\u0643\u064f\u0645\u06e1 \u0648\u064e\u0639\u064e\u0644\u0650\u0645\u064e \u0623\u064e\u0646\u0651\u064e \u0641\u0650\u064a\u0643\u064f\u0645\u06e1 \u0636\u064e\u0639\u06e1\u0641\u0657\u0627\u06da \u0641\u064e\u0625\u0650\u0646 \u064a\u064e\u0643\u064f\u0646 \u0645\u0651\u0650\u0646\u0643\u064f\u0645 \u0645\u0651\u0650\u0627\u0652\u0626\u064e\u0629\u065e \u0635\u064e\u0627\u0628\u0650\u0631\u064e\u0629\u065e \u064a\u064e\u063a\u06e1\u0644\u0650\u0628\u064f\u0648\u0627\u0652 \u0645\u0650\u0627\u0652\u0626\u064e\u062a\u064e\u064a\u06e1\u0646\u0650\u06da \u0648\u064e\u0625\u0650\u0646 \u064a\u064e\u0643\u064f\u0646 \u0645\u0651\u0650\u0646\u0643\u064f\u0645\u06e1 \u0623\u064e\u0644\u06e1\u0641\u065e \u064a\u064e\u063a\u06e1\u0644\u0650\u0628\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0644\u06e1\u0641\u064e\u064a\u06e1\u0646\u0650 \u0628\u0650\u0625\u0650\u0630\u06e1\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0639\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0628\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Sekarang Allah telah meringankan kamu karena Dia mengetahui bahwa ada kelemahan padamu. Maka jika di antara kamu ada seratus orang yang sabar, niscaya mereka dapat mengalahkan dua ratus (orang musuh); dan jika di antara kamu ada seribu orang (yang sabar), niscaya mereka dapat mengalahkan dua ribu orang dengan izin Allah. Dan Allah beserta orang-orang yang sabar"},{id:67,text:"\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0646\u064e\u0628\u0650\u064a\u0651\u064d \u0623\u064e\u0646 \u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0644\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u0633\u06e1\u0631\u064e\u0649\u0670 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064f\u062b\u06e1\u062e\u0650\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06da \u062a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0639\u064e\u0631\u064e\u0636\u064e \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u064e\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0632\u0650\u064a\u0632\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u065e",translation:"Tidaklah pantas, bagi seorang Nabi mempunyai tawanan sebelum dia dapat melumpuhkan musuhnya di bumi. Kamu menghendaki harta benda duniawi sedangkan Allah menghendaki (pahala) akhirat (untukmu). Allah Mahaperkasa, Mahabijaksana"},{id:68,text:"\u0644\u0651\u064e\u0648\u06e1\u0644\u064e\u0627 \u0643\u0650\u062a\u064e\u0670\u0628\u065e \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0633\u064e\u0628\u064e\u0642\u064e \u0644\u064e\u0645\u064e\u0633\u0651\u064e\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a\u0645\u064e\u0627\u0653 \u0623\u064e\u062e\u064e\u0630\u06e1\u062a\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u065e",translation:"Sekiranya tidak ada ketetapan terdahulu dari Allah, niscaya kamu ditimpa siksaan yang besar karena (tebusan) yang kamu ambil"},{id:69,text:"\u0641\u064e\u0643\u064f\u0644\u064f\u0648\u0627\u0652 \u0645\u0650\u0645\u0651\u064e\u0627 \u063a\u064e\u0646\u0650\u0645\u06e1\u062a\u064f\u0645\u06e1 \u062d\u064e\u0644\u064e\u0670\u0644\u0657\u0627 \u0637\u064e\u064a\u0651\u0650\u0628\u0657\u0627\u06da \u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u065e",translation:"Maka makanlah dari sebagian rampasan perang yang telah kamu peroleh itu, sebagai makanan yang halal lagi baik, dan bertakwalah kepada Allah. Sungguh, Allah Maha Pengampun, Maha Penyayang"},{id:70,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064f \u0642\u064f\u0644 \u0644\u0651\u0650\u0645\u064e\u0646 \u0641\u0650\u064a\u0653 \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u0633\u06e1\u0631\u064e\u0649\u0670\u0653 \u0625\u0650\u0646 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0643\u064f\u0645\u06e1 \u062e\u064e\u064a\u06e1\u0631\u0657\u0627 \u064a\u064f\u0624\u06e1\u062a\u0650\u0643\u064f\u0645\u06e1 \u062e\u064e\u064a\u06e1\u0631\u0657\u0627 \u0645\u0651\u0650\u0645\u0651\u064e\u0627\u0653 \u0623\u064f\u062e\u0650\u0630\u064e \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u0648\u064e\u064a\u064e\u063a\u06e1\u0641\u0650\u0631\u06e1 \u0644\u064e\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u065e",translation:"Wahai Nabi (Muhammad)! Katakanlah kepada para tawanan perang yang ada di tanganmu, \"Jika Allah mengetahui ada kebaikan di dalam hatimu, niscaya Dia akan memberikan yang lebih baik dari apa yang telah diambil darimu dan Dia akan mengampuni kamu.\" Allah Maha Pengampun, Maha Penyayang"},{id:71,text:"\u0648\u064e\u0625\u0650\u0646 \u064a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0627\u0652 \u062e\u0650\u064a\u064e\u0627\u0646\u064e\u062a\u064e\u0643\u064e \u0641\u064e\u0642\u064e\u062f\u06e1 \u062e\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f \u0641\u064e\u0623\u064e\u0645\u06e1\u0643\u064e\u0646\u064e \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u064c",translation:"Tetapi jika mereka (tawanan itu) hendak mengkhianatimu (Muhammad) maka sesungguhnya sebelum itu pun mereka telah berkhianat kepada Allah, maka Dia memberikan kekuasaan kepadamu atas mereka. Allah Maha Mengetahui, Mahabijaksana"},{id:72,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0647\u064e\u0627\u062c\u064e\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u062c\u064e\u0670\u0647\u064e\u062f\u064f\u0648\u0627\u0652 \u0628\u0650\u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u06e1 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0648\u064e\u0648\u0627\u0652 \u0648\u0651\u064e\u0646\u064e\u0635\u064e\u0631\u064f\u0648\u0653\u0627\u0652 \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0628\u064e\u0639\u06e1\u0636\u064f\u0647\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1\u0644\u0650\u064a\u064e\u0627\u0653\u0621\u064f \u0628\u064e\u0639\u06e1\u0636\u0656\u06da \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064f\u0647\u064e\u0627\u062c\u0650\u0631\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0648\u064e\u0644\u064e\u0670\u064a\u064e\u062a\u0650\u0647\u0650\u0645 \u0645\u0651\u0650\u0646 \u0634\u064e\u064a\u06e1\u0621\u064d \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064f\u0647\u064e\u0627\u062c\u0650\u0631\u064f\u0648\u0627\u0652\u06da \u0648\u064e\u0625\u0650\u0646\u0650 \u0671\u0633\u06e1\u062a\u064e\u0646\u0635\u064e\u0631\u064f\u0648\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u0650 \u0641\u064e\u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u064f \u0671\u0644\u0646\u0651\u064e\u0635\u06e1\u0631\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u06e1\u0645\u0650\u06ed \u0628\u064e\u064a\u06e1\u0646\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u064a\u062b\u064e\u0670\u0642\u065e\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0628\u064e\u0635\u0650\u064a\u0631\u065e",translation:"Sesungguhnya orang-orang yang beriman dan berhijrah serta berjihad dengan harta dan jiwanya di jalan Allah dan orang-orang yang memberikan tempat kediaman dan memberi pertolongan (kepada Muhajirin), mereka itu satu sama lain saling melindungi. Dan (terhadap) orang-orang yang beriman tetapi belum berhijrah, maka tidak ada kewajiban sedikit pun bagimu melindungi mereka, sampai mereka berhijrah. (Tetapi) jika mereka meminta pertolongan kepadamu dalam (urusan pembelaan) agama, maka kamu wajib memberikan pertolongan kecuali terhadap kaum yang telah terikat perjanjian antara kamu dengan mereka. Dan Allah Maha Melihat apa yang kamu kerjakan"},{id:73,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0628\u064e\u0639\u06e1\u0636\u064f\u0647\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1\u0644\u0650\u064a\u064e\u0627\u0653\u0621\u064f \u0628\u064e\u0639\u06e1\u0636\u064d\u06da \u0625\u0650\u0644\u0651\u064e\u0627 \u062a\u064e\u0641\u06e1\u0639\u064e\u0644\u064f\u0648\u0647\u064f \u062a\u064e\u0643\u064f\u0646 \u0641\u0650\u062a\u06e1\u0646\u064e\u0629\u065e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0641\u064e\u0633\u064e\u0627\u062f\u065e \u0643\u064e\u0628\u0650\u064a\u0631\u065e",translation:"Dan orang-orang yang kafir, sebagian mereka melindungi sebagian yang lain. Jika kamu tidak melaksanakan apa yang telah diperintahkan Allah (saling melindungi), niscaya akan terjadi kekacauan di bumi dan kerusakan yang besar"},{id:74,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0647\u064e\u0627\u062c\u064e\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u062c\u064e\u0670\u0647\u064e\u062f\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0648\u064e\u0648\u0627\u0652 \u0648\u0651\u064e\u0646\u064e\u0635\u064e\u0631\u064f\u0648\u0653\u0627\u0652 \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u062d\u064e\u0642\u0651\u0657\u0627\u06da \u0644\u0651\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u063a\u06e1\u0641\u0650\u0631\u064e\u0629\u065e \u0648\u064e\u0631\u0650\u0632\u06e1\u0642\u065e \u0643\u064e\u0631\u0650\u064a\u0645\u065e",translation:"Dan orang-orang yang beriman dan berhijrah serta berjihad di jalan Allah, dan orang-orang yang memberi tempat kediaman dan memberi pertolongan (kepada orang Muhajirin), mereka itulah orang yang benar-benar beriman. Mereka memperoleh ampunan dan rezeki (nikmat) yang mulia"},{id:75,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u064f \u0648\u064e\u0647\u064e\u0627\u062c\u064e\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u062c\u064e\u0670\u0647\u064e\u062f\u064f\u0648\u0627\u0652 \u0645\u064e\u0639\u064e\u0643\u064f\u0645\u06e1 \u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0645\u0650\u0646\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0623\u064f\u0648\u0652\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u062d\u064e\u0627\u0645\u0650 \u0628\u064e\u0639\u06e1\u0636\u064f\u0647\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1\u0644\u064e\u0649\u0670 \u0628\u0650\u0628\u064e\u0639\u06e1\u0636\u0656 \u0641\u0650\u064a \u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u064f\u06e2",translation:"Dan orang-orang yang beriman setelah itu, kemudian berhijrah dan berjihad bersamamu maka mereka termasuk golonganmu. Orang-orang yang mempunyai hubungan kerabat itu sebagiannya lebih berhak terhadap sesamanya (daripada yang bukan kerabat) menurut Kitab Allah. Sungguh, Allah Maha Mengetahui segala sesuatu"}]},{id:9,name:"\u0627\u0644\u062a\u0648\u0628\u0629",transliteration:"At-Tawbah",translation:"Pengampunan",type:"medinan",total_verses:129,verses:[{id:1,text:"\u0628\u064e\u0631\u064e\u0627\u0653\u0621\u064e\u0629\u065e \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0639\u064e\u0670\u0647\u064e\u062f\u062a\u0651\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0634\u06e1\u0631\u0650\u0643\u0650\u064a\u0646\u064e",translation:"(Inilah pernyataan) pemutusan hubungan dari Allah dan Rasul-Nya kepada orang-orang musyrik yang kamu telah mengadakan perjanjian (dengan mereka)"},{id:2,text:"\u0641\u064e\u0633\u0650\u064a\u062d\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0623\u064e\u0631\u06e1\u0628\u064e\u0639\u064e\u0629\u064e \u0623\u064e\u0634\u06e1\u0647\u064f\u0631\u0656 \u0648\u064e\u0671\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u063a\u064e\u064a\u06e1\u0631\u064f \u0645\u064f\u0639\u06e1\u062c\u0650\u0632\u0650\u064a \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064f\u062e\u06e1\u0632\u0650\u064a \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Maka berjalanlah kamu (kaum musyrikin) di bumi selama empat bulan dan ketahuilah bahwa kamu tidak dapat melemahkan Allah, dan sesungguhnya Allah menghinakan orang-orang kafir"},{id:3,text:"\u0648\u064e\u0623\u064e\u0630\u064e\u0670\u0646\u065e \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u062d\u064e\u062c\u0651\u0650 \u0671\u0644\u06e1\u0623\u064e\u0643\u06e1\u0628\u064e\u0631\u0650 \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u064e\u0631\u0650\u064a\u0653\u0621\u065e \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0634\u06e1\u0631\u0650\u0643\u0650\u064a\u0646\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0647\u064f\u06e5\u06da \u0641\u064e\u0625\u0650\u0646 \u062a\u064f\u0628\u06e1\u062a\u064f\u0645\u06e1 \u0641\u064e\u0647\u064f\u0648\u064e \u062e\u064e\u064a\u06e1\u0631\u065e \u0644\u0651\u064e\u0643\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0625\u0650\u0646 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u064a\u06e1\u062a\u064f\u0645\u06e1 \u0641\u064e\u0671\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u063a\u064e\u064a\u06e1\u0631\u064f \u0645\u064f\u0639\u06e1\u062c\u0650\u0632\u0650\u064a \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d7 \u0648\u064e\u0628\u064e\u0634\u0651\u0650\u0631\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0639\u064e\u0630\u064e\u0627\u0628\u064d \u0623\u064e\u0644\u0650\u064a\u0645\u064d",translation:"Dan satu maklumat (pemberitahuan) dari Allah dan Rasul-Nya kepada umat manusia pada hari haji akbar,369) bahwa sesungguhnya Allah dan Rasul-Nya berlepas diri dari orang-orang musyrik. Kemudian jika kamu (kaum musyrikin) bertobat, maka itu lebih baik bagimu; dan jika kamu berpaling, maka ketahuilah bahwa kamu tidak dapat melemahkan Allah. Dan berilah kabar gembira kepada orang-orang kafir (bahwa mereka akan mendapat) azab yang pedih"},{id:4,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0639\u064e\u0670\u0647\u064e\u062f\u062a\u0651\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0634\u06e1\u0631\u0650\u0643\u0650\u064a\u0646\u064e \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0645\u06e1 \u064a\u064e\u0646\u0642\u064f\u0635\u064f\u0648\u0643\u064f\u0645\u06e1 \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627 \u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064f\u0638\u064e\u0670\u0647\u0650\u0631\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0623\u064e\u062d\u064e\u062f\u0657\u0627 \u0641\u064e\u0623\u064e\u062a\u0650\u0645\u0651\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0639\u064e\u0647\u06e1\u062f\u064e\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064f\u062f\u0651\u064e\u062a\u0650\u0647\u0650\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0671\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",translation:"kecuali orang-orang musyrik yang telah mengadakan perjanjian dengan kamu dan mereka sedikit pun tidak mengurangi (isi perjanjian) dan tidak (pula) mereka membantu seorang pun yang memusuhi kamu, maka terhadap mereka itu penuhilah janjinya sampai batas waktunya. Sungguh, Allah menyukai orang-orang yang bertakwa"},{id:5,text:"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0671\u0646\u0633\u064e\u0644\u064e\u062e\u064e \u0671\u0644\u06e1\u0623\u064e\u0634\u06e1\u0647\u064f\u0631\u064f \u0671\u0644\u06e1\u062d\u064f\u0631\u064f\u0645\u064f \u0641\u064e\u0671\u0642\u06e1\u062a\u064f\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0645\u064f\u0634\u06e1\u0631\u0650\u0643\u0650\u064a\u0646\u064e \u062d\u064e\u064a\u06e1\u062b\u064f \u0648\u064e\u062c\u064e\u062f\u062a\u0651\u064f\u0645\u064f\u0648\u0647\u064f\u0645\u06e1 \u0648\u064e\u062e\u064f\u0630\u064f\u0648\u0647\u064f\u0645\u06e1 \u0648\u064e\u0671\u062d\u06e1\u0635\u064f\u0631\u064f\u0648\u0647\u064f\u0645\u06e1 \u0648\u064e\u0671\u0642\u06e1\u0639\u064f\u062f\u064f\u0648\u0627\u0652 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0643\u064f\u0644\u0651\u064e \u0645\u064e\u0631\u06e1\u0635\u064e\u062f\u0656\u06da \u0641\u064e\u0625\u0650\u0646 \u062a\u064e\u0627\u0628\u064f\u0648\u0627\u0652 \u0648\u064e\u0623\u064e\u0642\u064e\u0627\u0645\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u0621\u064e\u0627\u062a\u064e\u0648\u064f\u0627\u0652 \u0671\u0644\u0632\u0651\u064e\u0643\u064e\u0648\u0670\u0629\u064e \u0641\u064e\u062e\u064e\u0644\u0651\u064f\u0648\u0627\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u064e\u0647\u064f\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u065e",translation:"(Apabila telah habis bulan-bulan haram,370) maka perangilah orang-orang musyrik di mana saja kamu temui, tangkaplah dan kepunglah mereka, dan awasilah di tempat pengintaian. Jika mereka bertobat dan melaksanakan salat serta menunaikan zakat, maka berilah kebebasan kepada mereka. Sungguh, Allah Maha Pengampun, Maha Penyayang"},{id:6,text:"\u0648\u064e\u0625\u0650\u0646\u06e1 \u0623\u064e\u062d\u064e\u062f\u065e \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0634\u06e1\u0631\u0650\u0643\u0650\u064a\u0646\u064e \u0671\u0633\u06e1\u062a\u064e\u062c\u064e\u0627\u0631\u064e\u0643\u064e \u0641\u064e\u0623\u064e\u062c\u0650\u0631\u06e1\u0647\u064f \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0633\u06e1\u0645\u064e\u0639\u064e \u0643\u064e\u0644\u064e\u0670\u0645\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062b\u064f\u0645\u0651\u064e \u0623\u064e\u0628\u06e1\u0644\u0650\u063a\u06e1\u0647\u064f \u0645\u064e\u0623\u06e1\u0645\u064e\u0646\u064e\u0647\u064f\u06e5\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0642\u064e\u0648\u06e1\u0645\u065e \u0644\u0651\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan jika di antara kaum musyrikin ada yang meminta perlindungan kepadamu, maka lindungilah agar dia dapat mendengar firman Allah, kemudian antarkanlah dia ke tempat yang aman baginya. (Demikian) itu karena sesungguhnya mereka kaum yang tidak mengetahui"},{id:7,text:"\u0643\u064e\u064a\u06e1\u0641\u064e \u064a\u064e\u0643\u064f\u0648\u0646\u064f \u0644\u0650\u0644\u06e1\u0645\u064f\u0634\u06e1\u0631\u0650\u0643\u0650\u064a\u0646\u064e \u0639\u064e\u0647\u06e1\u062f\u064c \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0639\u0650\u0646\u062f\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0639\u064e\u0670\u0647\u064e\u062f\u062a\u0651\u064f\u0645\u06e1 \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u06e1\u0645\u064e\u0633\u06e1\u062c\u0650\u062f\u0650 \u0671\u0644\u06e1\u062d\u064e\u0631\u064e\u0627\u0645\u0650\u06d6 \u0641\u064e\u0645\u064e\u0627 \u0671\u0633\u06e1\u062a\u064e\u0642\u064e\u0670\u0645\u064f\u0648\u0627\u0652 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u0642\u0650\u064a\u0645\u064f\u0648\u0627\u0652 \u0644\u064e\u0647\u064f\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0671\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",translation:"Bagaimana mungkin ada perjanjian (aman) di sisi Allah dan Rasul-Nya dengan orang-orang musyrik, kecuali dengan orang-orang yang kamu telah mengadakan perjanjian (dengan mereka) di dekat Masjidilharam (Hudaibiyah), maka selama mereka berlaku jujur terhadapmu, hendaklah kamu berlaku jujur (pula) terhadap mereka. Sungguh, Allah menyukai orang-orang yang bertakwa"},{id:8,text:"\u0643\u064e\u064a\u06e1\u0641\u064e \u0648\u064e\u0625\u0650\u0646 \u064a\u064e\u0638\u06e1\u0647\u064e\u0631\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0631\u06e1\u0642\u064f\u0628\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0643\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u0630\u0650\u0645\u0651\u064e\u0629\u0657\u06da \u064a\u064f\u0631\u06e1\u0636\u064f\u0648\u0646\u064e\u0643\u064f\u0645 \u0628\u0650\u0623\u064e\u0641\u06e1\u0648\u064e\u0670\u0647\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u062a\u064e\u0623\u06e1\u0628\u064e\u0649\u0670 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064f\u0647\u064f\u0645\u06e1 \u0641\u064e\u0670\u0633\u0650\u0642\u064f\u0648\u0646\u064e",translation:"Bagaimana mungkin (ada perjanjian demikian), padahal jika mereka memperoleh kemenangan atas kamu, mereka tidak memelihara hubungan kekerabatan denganmu dan tidak (pula mengindahkan) perjanjian. Mereka menyenangkan hatimu dengan mulutnya, sedang hatinya menolak. Kebanyakan mereka adalah orang-orang fasik (tidak menepati janji)"},{id:9,text:"\u0671\u0634\u06e1\u062a\u064e\u0631\u064e\u0648\u06e1\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062b\u064e\u0645\u064e\u0646\u0657\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u0657\u0627 \u0641\u064e\u0635\u064e\u062f\u0651\u064f\u0648\u0627\u0652 \u0639\u064e\u0646 \u0633\u064e\u0628\u0650\u064a\u0644\u0650\u0647\u0650\u06e6\u0653\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0633\u064e\u0627\u0653\u0621\u064e \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Mereka memperjualbelikan ayat-ayat Allah dengan harga murah, lalu mereka menghalang-halangi (orang) dari jalan Allah. Sungguh, betapa buruknya apa yang mereka kerjakan"},{id:10,text:"\u0644\u064e\u0627 \u064a\u064e\u0631\u06e1\u0642\u064f\u0628\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064d \u0625\u0650\u0644\u0651\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u0630\u0650\u0645\u0651\u064e\u0629\u0657\u06da \u0648\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064f\u0639\u06e1\u062a\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Mereka tidak memelihara (hubungan) kekerabatan dengan orang mukmin dan tidak (pula mengindahkan) perjanjian. Dan mereka itulah orang-orang yang melampaui batas"},{id:11,text:"\u0641\u064e\u0625\u0650\u0646 \u062a\u064e\u0627\u0628\u064f\u0648\u0627\u0652 \u0648\u064e\u0623\u064e\u0642\u064e\u0627\u0645\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u0621\u064e\u0627\u062a\u064e\u0648\u064f\u0627\u0652 \u0671\u0644\u0632\u0651\u064e\u0643\u064e\u0648\u0670\u0629\u064e \u0641\u064e\u0625\u0650\u062e\u06e1\u0648\u064e\u0670\u0646\u064f\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u0650\u06d7 \u0648\u064e\u0646\u064f\u0641\u064e\u0635\u0651\u0650\u0644\u064f \u0671\u0644\u06e1\u0623\u0653\u064a\u064e\u0670\u062a\u0650 \u0644\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan jika mereka bertobat, melaksanakan salat dan menunaikan zakat, maka (berarti mereka itu) adalah saudara-saudaramu seagama. Kami menjelaskan ayat-ayat itu bagi orang-orang yang mengetahui"},{id:12,text:"\u0648\u064e\u0625\u0650\u0646 \u0646\u0651\u064e\u0643\u064e\u062b\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0639\u064e\u0647\u06e1\u062f\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0637\u064e\u0639\u064e\u0646\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u062f\u0650\u064a\u0646\u0650\u0643\u064f\u0645\u06e1 \u0641\u064e\u0642\u064e\u0670\u062a\u0650\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0626\u0650\u0645\u0651\u064e\u0629\u064e \u0671\u0644\u06e1\u0643\u064f\u0641\u06e1\u0631\u0650 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627\u0653 \u0623\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0646\u062a\u064e\u0647\u064f\u0648\u0646\u064e",translation:"Dan jika mereka melanggar sumpah setelah ada perjanjian, dan mencerca agamamu, maka perangilah pemimpin-pemimpin kafir itu. Sesungguhnya mereka adalah orang-orang yang tidak dapat dipegang janjinya, mudah-mudahan mereka berhenti"},{id:13,text:"\u0623\u064e\u0644\u064e\u0627 \u062a\u064f\u0642\u064e\u0670\u062a\u0650\u0644\u064f\u0648\u0646\u064e \u0642\u064e\u0648\u06e1\u0645\u0657\u0627 \u0646\u0651\u064e\u0643\u064e\u062b\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0647\u064e\u0645\u0651\u064f\u0648\u0627\u0652 \u0628\u0650\u0625\u0650\u062e\u06e1\u0631\u064e\u0627\u062c\u0650 \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0650 \u0648\u064e\u0647\u064f\u0645 \u0628\u064e\u062f\u064e\u0621\u064f\u0648\u0643\u064f\u0645\u06e1 \u0623\u064e\u0648\u0651\u064e\u0644\u064e \u0645\u064e\u0631\u0651\u064e\u0629\u064d\u06da \u0623\u064e\u062a\u064e\u062e\u06e1\u0634\u064e\u0648\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1\u06da \u0641\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u062d\u064e\u0642\u0651\u064f \u0623\u064e\u0646 \u062a\u064e\u062e\u06e1\u0634\u064e\u0648\u06e1\u0647\u064f \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645 \u0645\u0651\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Mengapa kamu tidak memerangi orang-orang yang melanggar sumpah (janjinya), dan telah merencanakan untuk mengusir Rasul, dan mereka yang pertama kali memerangi kamu? Apakah kamu takut kepada mereka, padahal Allahlah yang lebih berhak untuk kamu takuti, jika kamu orang-orang beriman"},{id:14,text:"\u0642\u064e\u0670\u062a\u0650\u0644\u064f\u0648\u0647\u064f\u0645\u06e1 \u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u06e1\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u0643\u064f\u0645\u06e1 \u0648\u064e\u064a\u064f\u062e\u06e1\u0632\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u064a\u064e\u0646\u0635\u064f\u0631\u06e1\u0643\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0648\u064e\u064a\u064e\u0634\u06e1\u0641\u0650 \u0635\u064f\u062f\u064f\u0648\u0631\u064e \u0642\u064e\u0648\u06e1\u0645\u0656 \u0645\u0651\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Perangilah mereka, niscaya Allah akan menyiksa mereka dengan (perantaraan) tanganmu dan Dia akan menghina mereka dan menolongmu (dengan kemenangan) atas mereka, serta melegakan hati orang-orang yang beriman"},{id:15,text:"\u0648\u064e\u064a\u064f\u0630\u06e1\u0647\u0650\u0628\u06e1 \u063a\u064e\u064a\u06e1\u0638\u064e \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u06e1\u06d7 \u0648\u064e\u064a\u064e\u062a\u064f\u0648\u0628\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u064c",translation:"dan Dia menghilangkan kemarahan hati mereka (orang mukmin). Dan Allah menerima tobat orang yang Dia kehendaki. Allah Maha Mengetahui, Mahabijaksana"},{id:16,text:"\u0623\u064e\u0645\u06e1 \u062d\u064e\u0633\u0650\u0628\u06e1\u062a\u064f\u0645\u06e1 \u0623\u064e\u0646 \u062a\u064f\u062a\u06e1\u0631\u064e\u0643\u064f\u0648\u0627\u0652 \u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062c\u064e\u0670\u0647\u064e\u062f\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650\u06e6 \u0648\u064e\u0644\u064e\u0627 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0644\u0650\u064a\u062c\u064e\u0629\u0657\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u062e\u064e\u0628\u0650\u064a\u0631\u064f\u06e2 \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Apakah kamu mengira bahwa kamu akan dibiarkan (begitu saja), padahal Allah belum mengetahui orang-orang yang berjihad di antara kamu dan tidak mengambil teman yang setia selain Allah, Rasul-Nya dan orang-orang yang beriman. Allah Mahateliti terhadap apa yang kamu kerjakan"},{id:17,text:"\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0644\u06e1\u0645\u064f\u0634\u06e1\u0631\u0650\u0643\u0650\u064a\u0646\u064e \u0623\u064e\u0646 \u064a\u064e\u0639\u06e1\u0645\u064f\u0631\u064f\u0648\u0627\u0652 \u0645\u064e\u0633\u064e\u0670\u062c\u0650\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0634\u064e\u0670\u0647\u0650\u062f\u0650\u064a\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645 \u0628\u0650\u0671\u0644\u06e1\u0643\u064f\u0641\u06e1\u0631\u0650\u06da \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u062d\u064e\u0628\u0650\u0637\u064e\u062a\u06e1 \u0623\u064e\u0639\u06e1\u0645\u064e\u0670\u0644\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0641\u0650\u064a \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0647\u064f\u0645\u06e1 \u062e\u064e\u0670\u0644\u0650\u062f\u064f\u0648\u0646\u064e",translation:"Tidaklah pantas orang-orang musyrik memakmurkan masjid Allah, padahal mereka mengakui bahwa mereka sendiri kafir. Mereka itu sia-sia amal-amalnya, dan mereka kekal di dalam neraka"},{id:18,text:"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0639\u06e1\u0645\u064f\u0631\u064f \u0645\u064e\u0633\u064e\u0670\u062c\u0650\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0646\u06e1 \u0621\u064e\u0627\u0645\u064e\u0646\u064e \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u0650 \u0648\u064e\u0623\u064e\u0642\u064e\u0627\u0645\u064e \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u0621\u064e\u0627\u062a\u064e\u0649 \u0671\u0644\u0632\u0651\u064e\u0643\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u062e\u06e1\u0634\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064e\u06d6 \u0641\u064e\u0639\u064e\u0633\u064e\u0649\u0670\u0653 \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0623\u064e\u0646 \u064a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0647\u06e1\u062a\u064e\u062f\u0650\u064a\u0646\u064e",translation:"Sesungguhnya yang memakmurkan masjid Allah hanyalah orang-orang yang beriman kepada Allah dan hari kemudian, serta (tetap) melaksanakan salat, menunaikan zakat dan tidak takut (kepada apa pun) kecuali kepada Allah. Maka mudah-mudahan mereka termasuk orang-orang yang mendapat petunjuk"},{id:19,text:"\u06de\u0623\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u062a\u064f\u0645\u06e1 \u0633\u0650\u0642\u064e\u0627\u064a\u064e\u0629\u064e \u0671\u0644\u06e1\u062d\u064e\u0627\u0653\u062c\u0651\u0650 \u0648\u064e\u0639\u0650\u0645\u064e\u0627\u0631\u064e\u0629\u064e \u0671\u0644\u06e1\u0645\u064e\u0633\u06e1\u062c\u0650\u062f\u0650 \u0671\u0644\u06e1\u062d\u064e\u0631\u064e\u0627\u0645\u0650 \u0643\u064e\u0645\u064e\u0646\u06e1 \u0621\u064e\u0627\u0645\u064e\u0646\u064e \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u0650 \u0648\u064e\u062c\u064e\u0670\u0647\u064e\u062f\u064e \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0648\u064f\u06e5\u0646\u064e \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064e\u0647\u06e1\u062f\u0650\u064a \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Apakah (orang-orang) yang memberi minuman kepada orang-orang yang mengerjakan haji dan mengurus Masjidilharam, kamu samakan dengan orang-orang yang beriman kepada Allah dan hari kemudian serta berjihad di jalan Allah? Mereka tidak sama di sisi Allah. Dan Allah tidak memberi petunjuk kepada orang-orang zalim"},{id:20,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0647\u064e\u0627\u062c\u064e\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u062c\u064e\u0670\u0647\u064e\u062f\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u0650\u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u06e1 \u0623\u064e\u0639\u06e1\u0638\u064e\u0645\u064f \u062f\u064e\u0631\u064e\u062c\u064e\u0629\u064b \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0648\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0641\u064e\u0627\u0653\u0626\u0650\u0632\u064f\u0648\u0646\u064e",translation:"Orang-orang yang beriman dan berhijrah serta berjihad di jalan Allah, dengan harta dan jiwa mereka, adalah lebih tinggi derajatnya di sisi Allah. Mereka itulah orang-orang yang memperoleh kemenangan"},{id:21,text:"\u064a\u064f\u0628\u064e\u0634\u0651\u0650\u0631\u064f\u0647\u064f\u0645\u06e1 \u0631\u064e\u0628\u0651\u064f\u0647\u064f\u0645 \u0628\u0650\u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u0656 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f \u0648\u064e\u0631\u0650\u0636\u06e1\u0648\u064e\u0670\u0646\u0656 \u0648\u064e\u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0656 \u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u0646\u064e\u0639\u0650\u064a\u0645\u065e \u0645\u0651\u064f\u0642\u0650\u064a\u0645\u064c",translation:"Tuhan menggembirakan mereka dengan memberikan rahmat, keridaan dan surga, mereka memperoleh kesenangan yang kekal di dalamnya"},{id:22,text:"\u062e\u064e\u0670\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627\u0653 \u0623\u064e\u0628\u064e\u062f\u064b\u0627\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u0650\u0646\u062f\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u062c\u06e1\u0631\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u065e",translation:"mereka kekal di dalamnya selama-lamanya. Sungguh, di sisi Allah terdapat pahala yang besar"},{id:23,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0653\u0627\u0652 \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0625\u0650\u062e\u06e1\u0648\u064e\u0670\u0646\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1\u0644\u0650\u064a\u064e\u0627\u0653\u0621\u064e \u0625\u0650\u0646\u0650 \u0671\u0633\u06e1\u062a\u064e\u062d\u064e\u0628\u0651\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0643\u064f\u0641\u06e1\u0631\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0625\u0650\u064a\u0645\u064e\u0670\u0646\u0650\u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u0643\u064f\u0645\u06e1 \u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Wahai orang-orang yang beriman! Janganlah kamu jadikan bapak-bapakmu dan saudara-saudaramu sebagai pelindung, jika mereka lebih menyukai kekafiran daripada keimanan. Barang siapa di antara kamu yang menjadikan mereka pelindung, maka mereka itulah orang-orang yang zalim"},{id:24,text:"\u0642\u064f\u0644\u06e1 \u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064e \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0624\u064f\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0628\u06e1\u0646\u064e\u0627\u0653\u0624\u064f\u0643\u064f\u0645\u06e1 \u0648\u064e\u0625\u0650\u062e\u06e1\u0648\u064e\u0670\u0646\u064f\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u064f\u0643\u064f\u0645\u06e1 \u0648\u064e\u0639\u064e\u0634\u0650\u064a\u0631\u064e\u062a\u064f\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u064c \u0671\u0642\u06e1\u062a\u064e\u0631\u064e\u0641\u06e1\u062a\u064f\u0645\u064f\u0648\u0647\u064e\u0627 \u0648\u064e\u062a\u0650\u062c\u064e\u0670\u0631\u064e\u0629\u065e \u062a\u064e\u062e\u06e1\u0634\u064e\u0648\u06e1\u0646\u064e \u0643\u064e\u0633\u064e\u0627\u062f\u064e\u0647\u064e\u0627 \u0648\u064e\u0645\u064e\u0633\u064e\u0670\u0643\u0650\u0646\u064f \u062a\u064e\u0631\u06e1\u0636\u064e\u0648\u06e1\u0646\u064e\u0647\u064e\u0627\u0653 \u0623\u064e\u062d\u064e\u0628\u0651\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650\u06e6 \u0648\u064e\u062c\u0650\u0647\u064e\u0627\u062f\u0656 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650\u0647\u0650\u06e6 \u0641\u064e\u062a\u064e\u0631\u064e\u0628\u0651\u064e\u0635\u064f\u0648\u0627\u0652 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0623\u064e\u0645\u06e1\u0631\u0650\u0647\u0650\u06e6\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064e\u0647\u06e1\u062f\u0650\u064a \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0641\u064e\u0670\u0633\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Katakanlah, \"Jika bapak-bapakmu, anak-anakmu, saudara-saudaramu, istri-istrimu, keluargamu, harta kekayaan yang kamu usahakan, perdagangan yang kamu khawatirkan kerugiannya, dan rumah-rumah tempat tinggal yang kamu sukai, lebih kamu cintai dari pada Allah dan rasul-Nya serta berjihad di jalan-Nya, maka tunggulah sampai Allah memberikan keputusan-Nya.\" Dan Allah tidak memberi petunjuk kepada orang-orang fasik"},{id:25,text:"\u0644\u064e\u0642\u064e\u062f\u06e1 \u0646\u064e\u0635\u064e\u0631\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u0650\u064a \u0645\u064e\u0648\u064e\u0627\u0637\u0650\u0646\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u064e\u0629\u0656 \u0648\u064e\u064a\u064e\u0648\u06e1\u0645\u064e \u062d\u064f\u0646\u064e\u064a\u06e1\u0646\u064d \u0625\u0650\u0630\u06e1 \u0623\u064e\u0639\u06e1\u062c\u064e\u0628\u064e\u062a\u06e1\u0643\u064f\u0645\u06e1 \u0643\u064e\u062b\u06e1\u0631\u064e\u062a\u064f\u0643\u064f\u0645\u06e1 \u0641\u064e\u0644\u064e\u0645\u06e1 \u062a\u064f\u063a\u06e1\u0646\u0650 \u0639\u064e\u0646\u0643\u064f\u0645\u06e1 \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627 \u0648\u064e\u0636\u064e\u0627\u0642\u064e\u062a\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064f \u0628\u0650\u0645\u064e\u0627 \u0631\u064e\u062d\u064f\u0628\u064e\u062a\u06e1 \u062b\u064f\u0645\u0651\u064e \u0648\u064e\u0644\u0651\u064e\u064a\u06e1\u062a\u064f\u0645 \u0645\u0651\u064f\u062f\u06e1\u0628\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Sungguh, Allah telah menolong kamu (mukminin) di banyak medan perang, dan (ingatlah) Perang Hunain, ketika jumlahmu yang besar itu membanggakan kamu, tetapi (jumlah yang banyak itu) sama sekali tidak berguna bagimu, dan bumi yang luas itu terasa sempit bagimu, kemudian kamu berbalik ke belakang dan lari tunggang langgang"},{id:26,text:"\u062b\u064f\u0645\u0651\u064e \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0633\u064e\u0643\u0650\u064a\u0646\u064e\u062a\u064e\u0647\u064f\u06e5 \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650\u06e6 \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0623\u064e\u0646\u0632\u064e\u0644\u064e \u062c\u064f\u0646\u064f\u0648\u062f\u0657\u0627 \u0644\u0651\u064e\u0645\u06e1 \u062a\u064e\u0631\u064e\u0648\u06e1\u0647\u064e\u0627 \u0648\u064e\u0639\u064e\u0630\u0651\u064e\u0628\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652\u06da \u0648\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062c\u064e\u0632\u064e\u0627\u0653\u0621\u064f \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Kemudian Allah menurunkan ketenangan kepada Rasul-Nya dan kepada orang-orang yang beriman, dan Dia menurunkan bala tentara (para malaikat) yang tidak terlihat olehmu, dan Dia menimpakan azab kepada orang-orang kafir. Itulah balasan bagi orang-orang yang kafir"},{id:27,text:"\u062b\u064f\u0645\u0651\u064e \u064a\u064e\u062a\u064f\u0648\u0628\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u065e",translation:"Setelah itu Allah menerima tobat orang yang Dia kehendaki. Allah Maha Pengampun, Maha Penyayang"},{id:28,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0671\u0644\u06e1\u0645\u064f\u0634\u06e1\u0631\u0650\u0643\u064f\u0648\u0646\u064e \u0646\u064e\u062c\u064e\u0633\u065e \u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0642\u06e1\u0631\u064e\u0628\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0645\u064e\u0633\u06e1\u062c\u0650\u062f\u064e \u0671\u0644\u06e1\u062d\u064e\u0631\u064e\u0627\u0645\u064e \u0628\u064e\u0639\u06e1\u062f\u064e \u0639\u064e\u0627\u0645\u0650\u0647\u0650\u0645\u06e1 \u0647\u064e\u0670\u0630\u064e\u0627\u06da \u0648\u064e\u0625\u0650\u0646\u06e1 \u062e\u0650\u0641\u06e1\u062a\u064f\u0645\u06e1 \u0639\u064e\u064a\u06e1\u0644\u064e\u0629\u0657 \u0641\u064e\u0633\u064e\u0648\u06e1\u0641\u064e \u064a\u064f\u063a\u06e1\u0646\u0650\u064a\u0643\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646 \u0641\u064e\u0636\u06e1\u0644\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0646 \u0634\u064e\u0627\u0653\u0621\u064e\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u065e",translation:"Wahai orang-orang yang beriman! Sesungguhnya orang-orang musyrik itu najis (kotor jiwa), karena itu janganlah mereka mendekati Masjidilharam setelah tahun ini.371) Dan jika kamu khawatir menjadi miskin (karena orang kafir tidak datang), maka Allah nanti akan memberikan kekayaan kepadamu dari karunia-Nya, jika Dia menghendaki. Sesungguhnya Allah Maha Mengetahui, Mahabijaksana"},{id:29,text:"\u0642\u064e\u0670\u062a\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u0628\u0650\u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u0650 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u062d\u064e\u0631\u0651\u0650\u0645\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u062d\u064e\u0631\u0651\u064e\u0645\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0647\u064f\u06e5 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062f\u0650\u064a\u0646\u064f\u0648\u0646\u064e \u062f\u0650\u064a\u0646\u064e \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0645\u0650\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064f\u0639\u06e1\u0637\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u062c\u0650\u0632\u06e1\u064a\u064e\u0629\u064e \u0639\u064e\u0646 \u064a\u064e\u062f\u0656 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0635\u064e\u0670\u063a\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Perangilah orang-orang yang tidak beriman kepada Allah dan hari kemudian, mereka yang tidak mengharamkan apa yang telah diharamkan Allah dan Rasul-Nya dan mereka yang tidak beragama dengan agama yang benar (agama Allah), (yaitu orang-orang) yang telah diberikan Kitab, hingga mereka membayar jizyah (pajak) dengan patuh sedang mereka dalam keadaan tunduk"},{id:30,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e\u062a\u0650 \u0671\u0644\u06e1\u064a\u064e\u0647\u064f\u0648\u062f\u064f \u0639\u064f\u0632\u064e\u064a\u06e1\u0631\u064c \u0671\u0628\u06e1\u0646\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0642\u064e\u0627\u0644\u064e\u062a\u0650 \u0671\u0644\u0646\u0651\u064e\u0635\u064e\u0670\u0631\u064e\u0649 \u0671\u0644\u06e1\u0645\u064e\u0633\u0650\u064a\u062d\u064f \u0671\u0628\u06e1\u0646\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0642\u064e\u0648\u06e1\u0644\u064f\u0647\u064f\u0645 \u0628\u0650\u0623\u064e\u0641\u06e1\u0648\u064e\u0670\u0647\u0650\u0647\u0650\u0645\u06e1\u06d6 \u064a\u064f\u0636\u064e\u0670\u0647\u0650\u0640\u0654\u064f\u0648\u0646\u064e \u0642\u064e\u0648\u06e1\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f\u06da \u0642\u064e\u0670\u062a\u064e\u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06d6 \u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u064a\u064f\u0624\u06e1\u0641\u064e\u0643\u064f\u0648\u0646\u064e",translation:"Dan orang-orang Yahudi berkata, \"Uzair putera Allah,\" dan orang-orang Nasrani berkata, \"Al-masih putra Allah.\" Itulah ucapan yang keluar dari mulut mereka. Mereka meniru ucapan orang-orang kafir yang terdahulu. Allah melaknat mereka; bagaimana mereka sampai berpaling"},{id:31,text:"\u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u062d\u06e1\u0628\u064e\u0627\u0631\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0631\u064f\u0647\u06e1\u0628\u064e\u0670\u0646\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u0631\u06e1\u0628\u064e\u0627\u0628\u0657\u0627 \u0645\u0651\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u0633\u0650\u064a\u062d\u064e \u0671\u0628\u06e1\u0646\u064e \u0645\u064e\u0631\u06e1\u064a\u064e\u0645\u064e \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0645\u0650\u0631\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0644\u0650\u064a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u0670\u0647\u0657\u0627 \u0648\u064e\u0670\u062d\u0650\u062f\u0657\u0627\u06d6 \u0644\u0651\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e\u06da \u0633\u064f\u0628\u06e1\u062d\u064e\u0670\u0646\u064e\u0647\u064f\u06e5 \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064f\u0634\u06e1\u0631\u0650\u0643\u064f\u0648\u0646\u064e",translation:"Mereka menjadikan orang-orang alim (Yahudi) dan rahib-rahibnya (Nasrani) sebagai tuhan selain Allah,372) dan (juga) Al-Masih putra Maryam; padahal mereka hanya disuruh menyembah Tuhan Yang Maha Esa; tidak ada tuhan selain Dia. Mahasuci Dia dari apa yang mereka persekutukan"},{id:32,text:"\u064a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0623\u064e\u0646 \u064a\u064f\u0637\u06e1\u0641\u0650\u0640\u0654\u064f\u0648\u0627\u0652 \u0646\u064f\u0648\u0631\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u0650\u0623\u064e\u0641\u06e1\u0648\u064e\u0670\u0647\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u064a\u064e\u0623\u06e1\u0628\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u064a\u064f\u062a\u0650\u0645\u0651\u064e \u0646\u064f\u0648\u0631\u064e\u0647\u064f\u06e5 \u0648\u064e\u0644\u064e\u0648\u06e1 \u0643\u064e\u0631\u0650\u0647\u064e \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Mereka hendak memadamkan cahaya (agama) Allah dengan mulut (ucapan-ucapan) mereka, tetapi Allah menolaknya, malah berkehendak menyempurnakan cahaya-Nya, walaupun orang-orang kafir itu tidak menyukai"},{id:33,text:"\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f\u06e5 \u0628\u0650\u0671\u0644\u06e1\u0647\u064f\u062f\u064e\u0649\u0670 \u0648\u064e\u062f\u0650\u064a\u0646\u0650 \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0644\u0650\u064a\u064f\u0638\u06e1\u0647\u0650\u0631\u064e\u0647\u064f\u06e5 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u0650 \u0643\u064f\u0644\u0651\u0650\u0647\u0650\u06e6 \u0648\u064e\u0644\u064e\u0648\u06e1 \u0643\u064e\u0631\u0650\u0647\u064e \u0671\u0644\u06e1\u0645\u064f\u0634\u06e1\u0631\u0650\u0643\u064f\u0648\u0646\u064e",translation:"Dialah yang telah mengutus Rasul-Nya dengan petunjuk (Alquran) dan agama yang benar untuk diunggulkan atas segala agama, walaupun orang-orang musyrik tidak menyukai"},{id:34,text:"\u06de\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u062d\u06e1\u0628\u064e\u0627\u0631\u0650 \u0648\u064e\u0671\u0644\u0631\u0651\u064f\u0647\u06e1\u0628\u064e\u0627\u0646\u0650 \u0644\u064e\u064a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f\u0648\u0646\u064e \u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0628\u0650\u0671\u0644\u06e1\u0628\u064e\u0670\u0637\u0650\u0644\u0650 \u0648\u064e\u064a\u064e\u0635\u064f\u062f\u0651\u064f\u0648\u0646\u064e \u0639\u064e\u0646 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d7 \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0643\u06e1\u0646\u0650\u0632\u064f\u0648\u0646\u064e \u0671\u0644\u0630\u0651\u064e\u0647\u064e\u0628\u064e \u0648\u064e\u0671\u0644\u06e1\u0641\u0650\u0636\u0651\u064e\u0629\u064e \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0646\u0641\u0650\u0642\u064f\u0648\u0646\u064e\u0647\u064e\u0627 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0628\u064e\u0634\u0651\u0650\u0631\u06e1\u0647\u064f\u0645 \u0628\u0650\u0639\u064e\u0630\u064e\u0627\u0628\u064d \u0623\u064e\u0644\u0650\u064a\u0645\u0656",translation:"Wahai orang-orang yang beriman! Sesungguhnya banyak dari orang-orang alim dan rahib-rahib mereka benar-benar memakan harta orang dengan jalan yang batil, dan (mereka) menghalang-halangi (manusia) dari jalan Allah. Dan orang-orang yang menyimpan emas dan perak dan tidak menginfakkannya di jalan Allah, maka berikanlah kabar gembira kepada mereka, (bahwa mereka akan mendapat) azab yang pedih"},{id:35,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064f\u062d\u06e1\u0645\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627 \u0641\u0650\u064a \u0646\u064e\u0627\u0631\u0650 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0641\u064e\u062a\u064f\u0643\u06e1\u0648\u064e\u0649\u0670 \u0628\u0650\u0647\u064e\u0627 \u062c\u0650\u0628\u064e\u0627\u0647\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u062c\u064f\u0646\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0638\u064f\u0647\u064f\u0648\u0631\u064f\u0647\u064f\u0645\u06e1\u06d6 \u0647\u064e\u0670\u0630\u064e\u0627 \u0645\u064e\u0627 \u0643\u064e\u0646\u064e\u0632\u06e1\u062a\u064f\u0645\u06e1 \u0644\u0650\u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u06e1 \u0641\u064e\u0630\u064f\u0648\u0642\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0643\u06e1\u0646\u0650\u0632\u064f\u0648\u0646\u064e",translation:"(Ingatlah) Pada hari ketika emas dan perak di panaskan dalam neraka Jahanam, lalu dengan itu disetrika dahi, lambung dan punggung mereka (seraya dikatakan) kepada mereka, \"Inilah harta bendamu yang kamu simpan untuk dirimu sendiri, maka rasakanlah (akibat dari) apa yang kamu simpan itu"},{id:36,text:"\u0625\u0650\u0646\u0651\u064e \u0639\u0650\u062f\u0651\u064e\u0629\u064e \u0671\u0644\u0634\u0651\u064f\u0647\u064f\u0648\u0631\u0650 \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u062b\u06e1\u0646\u064e\u0627 \u0639\u064e\u0634\u064e\u0631\u064e \u0634\u064e\u0647\u06e1\u0631\u0657\u0627 \u0641\u0650\u064a \u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u0648\u06e1\u0645\u064e \u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0645\u0650\u0646\u06e1\u0647\u064e\u0627\u0653 \u0623\u064e\u0631\u06e1\u0628\u064e\u0639\u064e\u0629\u064c \u062d\u064f\u0631\u064f\u0645\u065e\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u064f \u0671\u0644\u06e1\u0642\u064e\u064a\u0651\u0650\u0645\u064f\u06da \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0638\u06e1\u0644\u0650\u0645\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0647\u0650\u0646\u0651\u064e \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0642\u064e\u0670\u062a\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0645\u064f\u0634\u06e1\u0631\u0650\u0643\u0650\u064a\u0646\u064e \u0643\u064e\u0627\u0653\u0641\u0651\u064e\u0629\u0657 \u0643\u064e\u0645\u064e\u0627 \u064a\u064f\u0642\u064e\u0670\u062a\u0650\u0644\u064f\u0648\u0646\u064e\u0643\u064f\u0645\u06e1 \u0643\u064e\u0627\u0653\u0641\u0651\u064e\u0629\u0657\u06da \u0648\u064e\u0671\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064e\u0639\u064e \u0671\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",translation:"Sesungguhnya jumlah bulan menurut Allah ialah dua belas bulan, (sebagimana) dalam ketetapan Allah pada waktu Dia menciptakan langit dan bumi, di antaranya ada empat bulan haram. Itulah (ketetapan) agama yang lurus, maka janganlah kamu menzalimi dirimu dalam (bulan yang empat) itu, dan perangilah kaum musyrikin semuanya sebagaimana mereka pun memerangi kamu semuanya. Dan ketahuilah bahwa Allah beserta orang-orang yang takwa"},{id:37,text:"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0633\u0650\u064a\u0653\u0621\u064f \u0632\u0650\u064a\u064e\u0627\u062f\u064e\u0629\u065e \u0641\u0650\u064a \u0671\u0644\u06e1\u0643\u064f\u0641\u06e1\u0631\u0650\u06d6 \u064a\u064f\u0636\u064e\u0644\u0651\u064f \u0628\u0650\u0647\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u064a\u064f\u062d\u0650\u0644\u0651\u064f\u0648\u0646\u064e\u0647\u064f\u06e5 \u0639\u064e\u0627\u0645\u0657\u0627 \u0648\u064e\u064a\u064f\u062d\u064e\u0631\u0651\u0650\u0645\u064f\u0648\u0646\u064e\u0647\u064f\u06e5 \u0639\u064e\u0627\u0645\u0657\u0627 \u0644\u0651\u0650\u064a\u064f\u0648\u064e\u0627\u0637\u0650\u0640\u0654\u064f\u0648\u0627\u0652 \u0639\u0650\u062f\u0651\u064e\u0629\u064e \u0645\u064e\u0627 \u062d\u064e\u0631\u0651\u064e\u0645\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u064a\u064f\u062d\u0650\u0644\u0651\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u062d\u064e\u0631\u0651\u064e\u0645\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06da \u0632\u064f\u064a\u0651\u0650\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0633\u064f\u0648\u0653\u0621\u064f \u0623\u064e\u0639\u06e1\u0645\u064e\u0670\u0644\u0650\u0647\u0650\u0645\u06e1\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064e\u0647\u06e1\u062f\u0650\u064a \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Sesungguhnya pengunduran (bulan haram) itu hanya menambah kekafiran. Orang-orang kafir disesatkan dengan (pengunduran) itu, mereka menghalalkannya satu tahun dan mengharamkannya pada tahun yang lain, agar mereka dapat menyesuaikan dengan bilangan yang diharamkan Allah, sekaligus mereka menghalalkan apa yang diharamkan Allah. (Oleh Setan) dijadikan terasa indah bagi mereka perbuatan-perbuatan buruk mereka. Dan Allah tidak memberi petunjuk kepada orang-orang yang kafir"},{id:38,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0630\u064e\u0627 \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0646\u0641\u0650\u0631\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u062b\u0651\u064e\u0627\u0642\u064e\u0644\u06e1\u062a\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06da \u0623\u064e\u0631\u064e\u0636\u0650\u064a\u062a\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u0650 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650\u06da \u0641\u064e\u0645\u064e\u0627 \u0645\u064e\u062a\u064e\u0670\u0639\u064f \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u0650 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064c",translation:"Wahai orang-orang yang beriman! Mengapa apabila dikatakan kepada kamu, \"Berangkatlah (untuk berperang) di jalan Allah,\" kamu merasa berat dan ingin tinggal di tempatmu? Apakah kamu lebih menyenangi kehidupan dunia daripada kehidupan akhirat? Padahal kenikmatan hidup di dunia ini (dibandingkan dengan kehidupan) di akhirat hanyalah sedikit"},{id:39,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u062a\u064e\u0646\u0641\u0650\u0631\u064f\u0648\u0627\u0652 \u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u06e1\u0643\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0623\u064e\u0644\u0650\u064a\u0645\u0657\u0627 \u0648\u064e\u064a\u064e\u0633\u06e1\u062a\u064e\u0628\u06e1\u062f\u0650\u0644\u06e1 \u0642\u064e\u0648\u06e1\u0645\u064b\u0627 \u063a\u064e\u064a\u06e1\u0631\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0636\u064f\u0631\u0651\u064f\u0648\u0647\u064f \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0642\u064e\u062f\u0650\u064a\u0631\u064c",translation:"Jika kamu tidak berangkat (untuk berperang), niscaya Allah akan menghukum kamu dengan azab yang pedih dan menggantikan kamu dengan kaum yang lain, dan kamu tidak akan merugikan-Nya sedikit pun. Dan Allah Mahakuasa atas segala sesuatu"},{id:40,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u062a\u064e\u0646\u0635\u064f\u0631\u064f\u0648\u0647\u064f \u0641\u064e\u0642\u064e\u062f\u06e1 \u0646\u064e\u0635\u064e\u0631\u064e\u0647\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0625\u0650\u0630\u06e1 \u0623\u064e\u062e\u06e1\u0631\u064e\u062c\u064e\u0647\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u062b\u064e\u0627\u0646\u0650\u064a\u064e \u0671\u062b\u06e1\u0646\u064e\u064a\u06e1\u0646\u0650 \u0625\u0650\u0630\u06e1 \u0647\u064f\u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u063a\u064e\u0627\u0631\u0650 \u0625\u0650\u0630\u06e1 \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0644\u0650\u0635\u064e\u0670\u062d\u0650\u0628\u0650\u0647\u0650\u06e6 \u0644\u064e\u0627 \u062a\u064e\u062d\u06e1\u0632\u064e\u0646\u06e1 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064e\u0639\u064e\u0646\u064e\u0627\u06d6 \u0641\u064e\u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0633\u064e\u0643\u0650\u064a\u0646\u064e\u062a\u064e\u0647\u064f\u06e5 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0648\u064e\u0623\u064e\u064a\u0651\u064e\u062f\u064e\u0647\u064f\u06e5 \u0628\u0650\u062c\u064f\u0646\u064f\u0648\u062f\u0656 \u0644\u0651\u064e\u0645\u06e1 \u062a\u064e\u0631\u064e\u0648\u06e1\u0647\u064e\u0627 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0643\u064e\u0644\u0650\u0645\u064e\u0629\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0671\u0644\u0633\u0651\u064f\u0641\u06e1\u0644\u064e\u0649\u0670\u06d7 \u0648\u064e\u0643\u064e\u0644\u0650\u0645\u064e\u0629\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0647\u0650\u064a\u064e \u0671\u0644\u06e1\u0639\u064f\u0644\u06e1\u064a\u064e\u0627\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0632\u0650\u064a\u0632\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u064c",translation:"Jika kamu tidak menolongnya (Muhammad), sesungguhnya Allah telah menolongnya (yaitu) ketika orang-orang kafir mengusirnya (dari Mekkah); sedang dia salah seorang dari dua orang ketika keduanya berada dalam gua, ketika itu dia berkata kepada sahabatnya, \"Janganlah engkau bersedih, sesungguhnya Allah bersama kita.\" Maka Allah menurunkan ketenangan kepadanya (Muhammad) dan membantu dengan bala tentara (malaikat-malaikat) yang tidak terlihat olehmu, dan Dia menjadikan seruan orang-orang kafir itu rendah. Dan firman Allah itulah yang tinggi. Allah Mahaperkasa, Mahabijaksana"},{id:41,text:"\u0671\u0646\u0641\u0650\u0631\u064f\u0648\u0627\u0652 \u062e\u0650\u0641\u064e\u0627\u0641\u0657\u0627 \u0648\u064e\u062b\u0650\u0642\u064e\u0627\u0644\u0657\u0627 \u0648\u064e\u062c\u064e\u0670\u0647\u0650\u062f\u064f\u0648\u0627\u0652 \u0628\u0650\u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u06e1 \u062e\u064e\u064a\u06e1\u0631\u065e \u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Berangkatlah kamu baik dengan rasa ringan maupun dengan rasa berat, dan berjihadlah dengan harta dan jiwamu di jalan Allah. Yang demikian itu adalah lebih baik bagimu jika kamu mengetahui"},{id:42,text:"\u0644\u064e\u0648\u06e1 \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0631\u064e\u0636\u0657\u0627 \u0642\u064e\u0631\u0650\u064a\u0628\u0657\u0627 \u0648\u064e\u0633\u064e\u0641\u064e\u0631\u0657\u0627 \u0642\u064e\u0627\u0635\u0650\u062f\u0657\u0627 \u0644\u0651\u064e\u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0643\u064e \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u06e2 \u0628\u064e\u0639\u064f\u062f\u064e\u062a\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u064f \u0671\u0644\u0634\u0651\u064f\u0642\u0651\u064e\u0629\u064f\u06da \u0648\u064e\u0633\u064e\u064a\u064e\u062d\u06e1\u0644\u0650\u0641\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0648\u0650 \u0671\u0633\u06e1\u062a\u064e\u0637\u064e\u0639\u06e1\u0646\u064e\u0627 \u0644\u064e\u062e\u064e\u0631\u064e\u062c\u06e1\u0646\u064e\u0627 \u0645\u064e\u0639\u064e\u0643\u064f\u0645\u06e1 \u064a\u064f\u0647\u06e1\u0644\u0650\u0643\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0643\u064e\u0670\u0630\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Sekiranya (yang kamu serukan kepada mereka) ada keuntungan yang mudah diperoleh dan perjalanan yang tidak seberapa jauh, niscaya mereka mengikutimu, tetapi tempat yang dituju itu terasa sangat jauh bagi mereka. Mereka akan bersumpah dengan (nama) Allah, \"Jikalau kami sanggup niscaya kami berangkat bersamamu.\" Mereka membinasakan diri sendiri373) dan Allah mengetahui bahwa mereka benar-benar orang-orang yang berdusta"},{id:43,text:"\u0639\u064e\u0641\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0646\u0643\u064e \u0644\u0650\u0645\u064e \u0623\u064e\u0630\u0650\u0646\u062a\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u062a\u064e\u0628\u064e\u064a\u0651\u064e\u0646\u064e \u0644\u064e\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0635\u064e\u062f\u064e\u0642\u064f\u0648\u0627\u0652 \u0648\u064e\u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064e \u0671\u0644\u06e1\u0643\u064e\u0670\u0630\u0650\u0628\u0650\u064a\u0646\u064e",translation:"Allah memaafkanmu (Muhammad). Mengapa engkau memberi izin kepada mereka (untuk tidak pergi berperang), sebelum jelas bagimu orang-orang yang benar-benar (berhalangan) dan sebelum engkau mengetahui orang-orang yang berdusta"},{id:44,text:"\u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0640\u0654\u06e1\u0630\u0650\u0646\u064f\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u0650 \u0623\u064e\u0646 \u064a\u064f\u062c\u064e\u0670\u0647\u0650\u062f\u064f\u0648\u0627\u0652 \u0628\u0650\u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u06e1\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064f\u06e2 \u0628\u0650\u0671\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",translation:"Orang-orang yang beriman kepada Allah dan hari kemudian, tidak akan meminta izin (tidak ikut) kepadamu untuk berjihad dengan harta dan jiwa mereka. Allah mengetahui orang-orang yang bertakwa"},{id:45,text:"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0640\u0654\u06e1\u0630\u0650\u0646\u064f\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u0650 \u0648\u064e\u0671\u0631\u06e1\u062a\u064e\u0627\u0628\u064e\u062a\u06e1 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u06e1 \u0641\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0631\u064e\u064a\u06e1\u0628\u0650\u0647\u0650\u0645\u06e1 \u064a\u064e\u062a\u064e\u0631\u064e\u062f\u0651\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Sesungguhnya yang akan meminta izin kepadamu (Muhammad), hanyalah orang-orang yang tidak beriman kepada Allah dan hari kemudian, dan hati mereka ragu, karena itu mereka selalu bimbang dalam keraguan"},{id:46,text:"\u06de\u0648\u064e\u0644\u064e\u0648\u06e1 \u0623\u064e\u0631\u064e\u0627\u062f\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u062e\u064f\u0631\u064f\u0648\u062c\u064e \u0644\u064e\u0623\u064e\u0639\u064e\u062f\u0651\u064f\u0648\u0627\u0652 \u0644\u064e\u0647\u064f\u06e5 \u0639\u064f\u062f\u0651\u064e\u0629\u0657 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u0643\u064e\u0631\u0650\u0647\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0646\u06e2\u0628\u0650\u0639\u064e\u0627\u062b\u064e\u0647\u064f\u0645\u06e1 \u0641\u064e\u062b\u064e\u0628\u0651\u064e\u0637\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0642\u0650\u064a\u0644\u064e \u0671\u0642\u06e1\u0639\u064f\u062f\u064f\u0648\u0627\u0652 \u0645\u064e\u0639\u064e \u0671\u0644\u06e1\u0642\u064e\u0670\u0639\u0650\u062f\u0650\u064a\u0646\u064e",translation:"Dan jika mereka mau berangkat, niscaya mereka menyiapkan persiapan untuk keberangkatan itu, tetapi Allah tidak menyukai keberangkatan mereka, maka Dia melemahkan keinginan mereka, dan dikatakan (kepada mereka), \"Tinggallah kamu bersama orang-orang yang tinggal"},{id:47,text:"\u0644\u064e\u0648\u06e1 \u062e\u064e\u0631\u064e\u062c\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0643\u064f\u0645 \u0645\u0651\u064e\u0627 \u0632\u064e\u0627\u062f\u064f\u0648\u0643\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u062e\u064e\u0628\u064e\u0627\u0644\u0657\u0627 \u0648\u064e\u0644\u064e\u0623\u064e\u0648\u06e1\u0636\u064e\u0639\u064f\u0648\u0627\u0652 \u062e\u0650\u0644\u064e\u0670\u0644\u064e\u0643\u064f\u0645\u06e1 \u064a\u064e\u0628\u06e1\u063a\u064f\u0648\u0646\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0641\u0650\u062a\u06e1\u0646\u064e\u0629\u064e \u0648\u064e\u0641\u0650\u064a\u0643\u064f\u0645\u06e1 \u0633\u064e\u0645\u0651\u064e\u0640\u0670\u0639\u064f\u0648\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u06e1\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064f\u06e2 \u0628\u0650\u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Jika (mereka berangkat bersamamu), niscaya mereka tidak akan menambah (kekuatan)mu, malah hanya akan membuat kekacauan, dan mereka tentu bergegas maju ke depan di celah-celah barisanmu untuk mengadakan kekacauan (di barisanmu); sedang di antara kamu ada orang-orang yang sangat suka mendengarkan (perkataan) mereka. Allah mengetahui orang-orang yang zalim"},{id:48,text:"\u0644\u064e\u0642\u064e\u062f\u0650 \u0671\u0628\u06e1\u062a\u064e\u063a\u064e\u0648\u064f\u0627\u0652 \u0671\u0644\u06e1\u0641\u0650\u062a\u06e1\u0646\u064e\u0629\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f \u0648\u064e\u0642\u064e\u0644\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0644\u064e\u0643\u064e \u0671\u0644\u06e1\u0623\u064f\u0645\u064f\u0648\u0631\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062c\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f \u0648\u064e\u0638\u064e\u0647\u064e\u0631\u064e \u0623\u064e\u0645\u06e1\u0631\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0670\u0631\u0650\u0647\u064f\u0648\u0646\u064e",translation:"Sesungguhnya, sebelum itu mereka memang sudah berusaha membuat kekacauan dan mengatur berbagai macam tipu daya bagimu (memutarbalikkan persoalan), hingga datanglah kebenaran (pertolongan Allah), dan menanglah urusan (agama) Allah, padahal mereka tidak menyukainya"},{id:49,text:"\u0648\u064e\u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0646 \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0671\u0626\u06e1\u0630\u064e\u0646 \u0644\u0651\u0650\u064a \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0641\u06e1\u062a\u0650\u0646\u0651\u0650\u064a\u0653\u06da \u0623\u064e\u0644\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0641\u0650\u062a\u06e1\u0646\u064e\u0629\u0650 \u0633\u064e\u0642\u064e\u0637\u064f\u0648\u0627\u0652\u06d7 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0644\u064e\u0645\u064f\u062d\u0650\u064a\u0637\u064e\u0629\u064f\u06e2 \u0628\u0650\u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan di antara mereka ada orang yang berkata, \"Berilah aku izin (tidak pergi berperang) dan janganlah engkau (Muhammad) menjadikan aku terjerumus ke dalam fitnah.\" Ketahuilah, bahwa mereka telah terjerumus ke dalam fitnah. Dan sungguh, Jahanam meliputi orang-orang yang kafir"},{id:50,text:"\u0625\u0650\u0646 \u062a\u064f\u0635\u0650\u0628\u06e1\u0643\u064e \u062d\u064e\u0633\u064e\u0646\u064e\u0629\u065e \u062a\u064e\u0633\u064f\u0624\u06e1\u0647\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0625\u0650\u0646 \u062a\u064f\u0635\u0650\u0628\u06e1\u0643\u064e \u0645\u064f\u0635\u0650\u064a\u0628\u064e\u0629\u065e \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627\u0652 \u0642\u064e\u062f\u06e1 \u0623\u064e\u062e\u064e\u0630\u06e1\u0646\u064e\u0627\u0653 \u0623\u064e\u0645\u06e1\u0631\u064e\u0646\u064e\u0627 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f \u0648\u064e\u064a\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u0627\u0652 \u0648\u0651\u064e\u0647\u064f\u0645\u06e1 \u0641\u064e\u0631\u0650\u062d\u064f\u0648\u0646\u064e",translation:"Jika engkau (Muhammad) mendapat kebaikan, mereka tidak senang; tetapi jika engkau ditimpa bencana, mereka berkata, \"Sungguh, sejak semula kami telah berhati-hati (tidak pergi berperang),\" dan mereka berpaling dengan (perasaan) gembira"},{id:51,text:"\u0642\u064f\u0644 \u0644\u0651\u064e\u0646 \u064a\u064f\u0635\u0650\u064a\u0628\u064e\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0643\u064e\u062a\u064e\u0628\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0646\u064e\u0627 \u0647\u064f\u0648\u064e \u0645\u064e\u0648\u06e1\u0644\u064e\u0649\u0670\u0646\u064e\u0627\u06da \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0644\u06e1\u064a\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u0650 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Katakanlah (Muhammad), \"Tidak akan menimpa kami melainkan apa yang telah ditetapkan Allah bagi kami. Dialah Pelindung kami, dan hanya kepada Allah bertawakallah orang-orang yang beriman"},{id:52,text:"\u0642\u064f\u0644\u06e1 \u0647\u064e\u0644\u06e1 \u062a\u064e\u0631\u064e\u0628\u0651\u064e\u0635\u064f\u0648\u0646\u064e \u0628\u0650\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0625\u0650\u062d\u06e1\u062f\u064e\u0649 \u0671\u0644\u06e1\u062d\u064f\u0633\u06e1\u0646\u064e\u064a\u064e\u064a\u06e1\u0646\u0650\u06d6 \u0648\u064e\u0646\u064e\u062d\u06e1\u0646\u064f \u0646\u064e\u062a\u064e\u0631\u064e\u0628\u0651\u064e\u0635\u064f \u0628\u0650\u0643\u064f\u0645\u06e1 \u0623\u064e\u0646 \u064a\u064f\u0635\u0650\u064a\u0628\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0639\u064e\u0630\u064e\u0627\u0628\u0656 \u0645\u0651\u0650\u0646\u06e1 \u0639\u0650\u0646\u062f\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0648\u06e1 \u0628\u0650\u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u0646\u064e\u0627\u06d6 \u0641\u064e\u062a\u064e\u0631\u064e\u0628\u0651\u064e\u0635\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e\u0627 \u0645\u064e\u0639\u064e\u0643\u064f\u0645 \u0645\u0651\u064f\u062a\u064e\u0631\u064e\u0628\u0651\u0650\u0635\u064f\u0648\u0646\u064e",translation:"Katakanlah (Muhammad), \"Tidak ada yang kamu tunggu-tunggu bagi kami, kecuali salah satu dari dua kebaikan (menang atau mati syahid). Dan kami menunggu-nunggu bagi kamu bahwa Allah akan menimpakan azab kepadamu dari sisi-Nya, atau (azab) melalui tangan kami. Maka tunggulah, sesungguhnya kami menunggu (pula) bersamamu"},{id:53,text:"\u0642\u064f\u0644\u06e1 \u0623\u064e\u0646\u0641\u0650\u0642\u064f\u0648\u0627\u0652 \u0637\u064e\u0648\u06e1\u0639\u064b\u0627 \u0623\u064e\u0648\u06e1 \u0643\u064e\u0631\u06e1\u0647\u0657\u0627 \u0644\u0651\u064e\u0646 \u064a\u064f\u062a\u064e\u0642\u064e\u0628\u0651\u064e\u0644\u064e \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0642\u064e\u0648\u06e1\u0645\u0657\u0627 \u0641\u064e\u0670\u0633\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Katakanlah (Muhammad), \"Infakkanlah hartamu baik dengan sukarela maupun dengan terpaksa, namun (infakmu) tidak akan diterima. Sesungguhnya kamu sekalian adalah orang-orang yang fasik"},{id:54,text:"\u0648\u064e\u0645\u064e\u0627 \u0645\u064e\u0646\u064e\u0639\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u0646 \u062a\u064f\u0642\u06e1\u0628\u064e\u0644\u064e \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0646\u064e\u0641\u064e\u0642\u064e\u0670\u062a\u064f\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0628\u0650\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650\u06e6 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0623\u06e1\u062a\u064f\u0648\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0643\u064f\u0633\u064e\u0627\u0644\u064e\u0649\u0670 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0646\u0641\u0650\u0642\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0670\u0631\u0650\u0647\u064f\u0648\u0646\u064e",translation:"Dan yang menghalang-halangi infak mereka untuk diterima adalah karena mereka kafir (ingkar) kepada Allah dan Rasul-Nya dan mereka tidak melaksanakan salat, melainkan dengan malas dan tidak (pula) menginfakkan (harta) mereka, melainkan dengan rasa enggan (terpaksa)"},{id:55,text:"\u0641\u064e\u0644\u064e\u0627 \u062a\u064f\u0639\u06e1\u062c\u0650\u0628\u06e1\u0643\u064e \u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064e\u0648\u06e1\u0644\u064e\u0670\u062f\u064f\u0647\u064f\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064e\u0647\u064f\u0645 \u0628\u0650\u0647\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u0650 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0648\u064e\u062a\u064e\u0632\u06e1\u0647\u064e\u0642\u064e \u0623\u064e\u0646\u0641\u064f\u0633\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0670\u0641\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Maka janganlah harta dan anak-anak mereka membuatmu kagum. Sesungguhnya maksud Allah dengan itu adalah untuk menyiksa mereka dalam kehidupan dunia dan kelak akan mati dalam keadaan kafir"},{id:56,text:"\u0648\u064e\u064a\u064e\u062d\u06e1\u0644\u0650\u0641\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627 \u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0642\u064e\u0648\u06e1\u0645\u065e \u064a\u064e\u0641\u06e1\u0631\u064e\u0642\u064f\u0648\u0646\u064e",translation:"Dan mereka (orang-orang munafik) bersumpah dengan (nama) Allah, bahwa sesungguhnya mereka termasuk golonganmu; namun mereka bukanlah dari golonganmu, tetapi mereka adalah orang-orang yang sangat takut (kepadamu)"},{id:57,text:"\u0644\u064e\u0648\u06e1 \u064a\u064e\u062c\u0650\u062f\u064f\u0648\u0646\u064e \u0645\u064e\u0644\u06e1\u062c\u064e\u0640\u0654\u064b\u0627 \u0623\u064e\u0648\u06e1 \u0645\u064e\u063a\u064e\u0670\u0631\u064e\u0670\u062a\u064d \u0623\u064e\u0648\u06e1 \u0645\u064f\u062f\u0651\u064e\u062e\u064e\u0644\u0657\u0627 \u0644\u0651\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u06e1\u0627\u0652 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0648\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u062c\u06e1\u0645\u064e\u062d\u064f\u0648\u0646\u064e",translation:"Sekiranya mereka memperoleh tempat perlindungan, gua-gua atau lubang-lubang (dalam tanah) niscaya mereka pergi (lari) ke sana dengan secepat-cepatnya"},{id:58,text:"\u0648\u064e\u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0646 \u064a\u064e\u0644\u06e1\u0645\u0650\u0632\u064f\u0643\u064e \u0641\u0650\u064a \u0671\u0644\u0635\u0651\u064e\u062f\u064e\u0642\u064e\u0670\u062a\u0650 \u0641\u064e\u0625\u0650\u0646\u06e1 \u0623\u064f\u0639\u06e1\u0637\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0631\u064e\u0636\u064f\u0648\u0627\u0652 \u0648\u064e\u0625\u0650\u0646 \u0644\u0651\u064e\u0645\u06e1 \u064a\u064f\u0639\u06e1\u0637\u064e\u0648\u06e1\u0627\u0652 \u0645\u0650\u0646\u06e1\u0647\u064e\u0627\u0653 \u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0645\u06e1 \u064a\u064e\u0633\u06e1\u062e\u064e\u0637\u064f\u0648\u0646\u064e",translation:"Dan di antara mereka ada yang mencelamu tentang (pembagian) sedekah (zakat); jika mereka diberi bagian, mereka bersenang hati, dan jika mereka tidak diberi bagian, tiba-tiba mereka marah"},{id:59,text:"\u0648\u064e\u0644\u064e\u0648\u06e1 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0631\u064e\u0636\u064f\u0648\u0627\u0652 \u0645\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u064e\u0649\u0670\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0647\u064f\u06e5 \u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u062d\u064e\u0633\u06e1\u0628\u064f\u0646\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0633\u064e\u064a\u064f\u0624\u06e1\u062a\u0650\u064a\u0646\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646 \u0641\u064e\u0636\u06e1\u0644\u0650\u0647\u0650\u06e6 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0647\u064f\u06e5\u0653 \u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0631\u064e\u0670\u063a\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Dan Sekiranya mereka benar-benar rida dengan apa yang diberikan kepada mereka oleh Allah dan Rasul-Nya, dan berkata, \"Cukuplah Allah bagi kami, Allah dan Rasul-Nya akan memberikan kepada kami sebagian dari karunia-Nya. Sesungguhnya kami orang-orang yang berharap kepada Allah"},{id:60,text:"\u06de\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0671\u0644\u0635\u0651\u064e\u062f\u064e\u0642\u064e\u0670\u062a\u064f \u0644\u0650\u0644\u06e1\u0641\u064f\u0642\u064e\u0631\u064e\u0627\u0653\u0621\u0650 \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u0633\u064e\u0670\u0643\u0650\u064a\u0646\u0650 \u0648\u064e\u0671\u0644\u06e1\u0639\u064e\u0670\u0645\u0650\u0644\u0650\u064a\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627 \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0624\u064e\u0644\u0651\u064e\u0641\u064e\u0629\u0650 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0641\u0650\u064a \u0671\u0644\u0631\u0651\u0650\u0642\u064e\u0627\u0628\u0650 \u0648\u064e\u0671\u0644\u06e1\u063a\u064e\u0670\u0631\u0650\u0645\u0650\u064a\u0646\u064e \u0648\u064e\u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0671\u0628\u06e1\u0646\u0650 \u0671\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u0650\u06d6 \u0641\u064e\u0631\u0650\u064a\u0636\u064e\u0629\u0657 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u065e",translation:"Sesungguhnya zakat itu hanyalah untuk orang-orang fakir, orang miskin, amil zakat, orang yang dilunakkan hatinya (mualaf), untuk (memerdekakan) hamba sahaya, untuk (membebaskan) orang yang berhutang, untuk jalan Allah dan untuk orang yang sedang dalam perjalanan, sebagai kewajiban dari Allah. Allah Maha Mengetahui, Mahabijaksana"},{id:61,text:"\u0648\u064e\u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0624\u06e1\u0630\u064f\u0648\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064e \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0647\u064f\u0648\u064e \u0623\u064f\u0630\u064f\u0646\u065e\u06da \u0642\u064f\u0644\u06e1 \u0623\u064f\u0630\u064f\u0646\u064f \u062e\u064e\u064a\u06e1\u0631\u0656 \u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f \u0644\u0650\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u065e \u0644\u0651\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0624\u06e1\u0630\u064f\u0648\u0646\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Dan di antara mereka (orang munafik) ada orang-orang yang menyakiti hati Nabi (Muhammad) dan mengatakan, \"Nabi mempercayai semua apa yang didengarnya.\" Katakanlah, \"Dia mempercayai semua yang baik bagi kamu, dia beriman kepada Allah, mempercayai orang-orang mukmin, dan menjadi rahmat bagi orang-orang yang beriman di antara kamu.\" Dan orang-orang yang menyakiti Rasulullah akan mendapat azab yang pedih"},{id:62,text:"\u064a\u064e\u062d\u06e1\u0644\u0650\u0641\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0644\u0650\u064a\u064f\u0631\u06e1\u0636\u064f\u0648\u0643\u064f\u0645\u06e1 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0647\u064f\u06e5\u0653 \u0623\u064e\u062d\u064e\u0642\u0651\u064f \u0623\u064e\u0646 \u064a\u064f\u0631\u06e1\u0636\u064f\u0648\u0647\u064f \u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Mereka bersumpah kepadamu dengan (nama) Allah untuk menyenangkan kamu, padahal Allah dan Rasul-Nya lebih pantas mereka cari keridaan-Nya jika mereka orang mukmin"},{id:63,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u06e5 \u0645\u064e\u0646 \u064a\u064f\u062d\u064e\u0627\u062f\u0650\u062f\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f\u06e5 \u0641\u064e\u0623\u064e\u0646\u0651\u064e \u0644\u064e\u0647\u064f\u06e5 \u0646\u064e\u0627\u0631\u064e \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u062e\u064e\u0670\u0644\u0650\u062f\u0657\u0627 \u0641\u0650\u064a\u0647\u064e\u0627\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0671\u0644\u06e1\u062e\u0650\u0632\u06e1\u064a\u064f \u0671\u0644\u06e1\u0639\u064e\u0638\u0650\u064a\u0645\u064f",translation:"Tidakkah mereka (orang munafik) mengetahui bahwa barang siapa menentang Allah dan Rasul-Nya, maka sesungguhnya neraka Jahanamlah bagiannya, dia kekal di dalamnya. Itulah kehinaan yang besar"},{id:64,text:"\u064a\u064e\u062d\u06e1\u0630\u064e\u0631\u064f \u0671\u0644\u06e1\u0645\u064f\u0646\u064e\u0670\u0641\u0650\u0642\u064f\u0648\u0646\u064e \u0623\u064e\u0646 \u062a\u064f\u0646\u064e\u0632\u0651\u064e\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0633\u064f\u0648\u0631\u064e\u0629\u065e \u062a\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0647\u064f\u0645 \u0628\u0650\u0645\u064e\u0627 \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u06e1\u06da \u0642\u064f\u0644\u0650 \u0671\u0633\u06e1\u062a\u064e\u0647\u06e1\u0632\u0650\u0621\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064f\u062e\u06e1\u0631\u0650\u062c\u065e \u0645\u0651\u064e\u0627 \u062a\u064e\u062d\u06e1\u0630\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Orang-orang munafik itu takut jika diturunkan suatu surah yang menerangkan apa yang tersembunyi di dalam hati mereka. Katakanlah (kepada mereka), \"Teruskanlah berolok-olok (terhadap Allah dan Rasul-Nya).\" Sesungguhnya Allah akan mengungkapkan apa yang kamu takuti itu"},{id:65,text:"\u0648\u064e\u0644\u064e\u0626\u0650\u0646 \u0633\u064e\u0623\u064e\u0644\u06e1\u062a\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0646\u0651\u064e \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0646\u064e\u062e\u064f\u0648\u0636\u064f \u0648\u064e\u0646\u064e\u0644\u06e1\u0639\u064e\u0628\u064f\u06da \u0642\u064f\u0644\u06e1 \u0623\u064e\u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0647\u0650\u06e6 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650\u06e6 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0633\u06e1\u062a\u064e\u0647\u06e1\u0632\u0650\u0621\u064f\u0648\u0646\u064e",translation:"Dan jika kamu tanyakan kepada mereka, niscaya mereka akan menjawab, \"Sesungguhnya kami hanya bersenda gurau dan bermain-main saja.\" Katakanlah, \"Mengapa kepada Allah, dan ayat-ayat-Nya serta Rasul-Nya kamu selalu berolok-olok"},{id:66,text:"\u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u062a\u064e\u0630\u0650\u0631\u064f\u0648\u0627\u0652 \u0642\u064e\u062f\u06e1 \u0643\u064e\u0641\u064e\u0631\u06e1\u062a\u064f\u0645 \u0628\u064e\u0639\u06e1\u062f\u064e \u0625\u0650\u064a\u0645\u064e\u0670\u0646\u0650\u0643\u064f\u0645\u06e1\u06da \u0625\u0650\u0646 \u0646\u0651\u064e\u0639\u06e1\u0641\u064f \u0639\u064e\u0646 \u0637\u064e\u0627\u0653\u0626\u0650\u0641\u064e\u0629\u0656 \u0645\u0651\u0650\u0646\u0643\u064f\u0645\u06e1 \u0646\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u06e1 \u0637\u064e\u0627\u0653\u0626\u0650\u0641\u064e\u0629\u064e\u06e2 \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0645\u064f\u062c\u06e1\u0631\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Tidak perlu kamu meminta maaf, karena kamu telah kafir setelah beriman. Jika Kami memaafkan sebagian dari kamu (karena telah tobat), niscaya Kami akan mengazab golongan (yang lain) karena sesungguhnya mereka adalah orang-orang yang (selalu) berbuat dosa"},{id:67,text:"\u0671\u0644\u06e1\u0645\u064f\u0646\u064e\u0670\u0641\u0650\u0642\u064f\u0648\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0646\u064e\u0670\u0641\u0650\u0642\u064e\u0670\u062a\u064f \u0628\u064e\u0639\u06e1\u0636\u064f\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u0636\u0656\u06da \u064a\u064e\u0623\u06e1\u0645\u064f\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u06e1\u0645\u064f\u0646\u0643\u064e\u0631\u0650 \u0648\u064e\u064a\u064e\u0646\u06e1\u0647\u064e\u0648\u06e1\u0646\u064e \u0639\u064e\u0646\u0650 \u0671\u0644\u06e1\u0645\u064e\u0639\u06e1\u0631\u064f\u0648\u0641\u0650 \u0648\u064e\u064a\u064e\u0642\u06e1\u0628\u0650\u0636\u064f\u0648\u0646\u064e \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u064e\u0647\u064f\u0645\u06e1\u06da \u0646\u064e\u0633\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0641\u064e\u0646\u064e\u0633\u0650\u064a\u064e\u0647\u064f\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0645\u064f\u0646\u064e\u0670\u0641\u0650\u0642\u0650\u064a\u0646\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0641\u064e\u0670\u0633\u0650\u0642\u064f\u0648\u0646\u064e",translation:"Orang-orang munafik laki-laki dan perempuan, satu dengan yang lain adalah (sama), mereka menyuruh (berbuat) yang mungkar dan mencegah (perbuatan) yang makruf dan mereka menggenggamkan tangannya (kikir). Mereka telah melupakan kepada Allah, maka Allah melupakan mereka (pula). Sesungguhnya orang-orang munafik itulah orang-orang yang fasik"},{id:68,text:"\u0648\u064e\u0639\u064e\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u0645\u064f\u0646\u064e\u0670\u0641\u0650\u0642\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0646\u064e\u0670\u0641\u0650\u0642\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0643\u064f\u0641\u0651\u064e\u0627\u0631\u064e \u0646\u064e\u0627\u0631\u064e \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u062e\u064e\u0670\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627\u06da \u0647\u0650\u064a\u064e \u062d\u064e\u0633\u06e1\u0628\u064f\u0647\u064f\u0645\u06e1\u06da \u0648\u064e\u0644\u064e\u0639\u064e\u0646\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06d6 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u065e \u0645\u0651\u064f\u0642\u0650\u064a\u0645\u065e",translation:"Allah menjanjikan (mengancam) orang-orang munafik laki-laki dan perempuan dan orang-orang kafir dengan neraka Jahanam. Mereka kekal di dalamnya. Cukuplah (neraka) itu bagi mereka. Allah melaknat mereka; dan mereka mendapat azab yang kekal"},{id:69,text:"\u0643\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064f\u0645\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0634\u064e\u062f\u0651\u064e \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u0642\u064f\u0648\u0651\u064e\u0629\u0657 \u0648\u064e\u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064e \u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u0657\u0627 \u0648\u064e\u0623\u064e\u0648\u06e1\u0644\u064e\u0670\u062f\u0657\u0627 \u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u0645\u06e1\u062a\u064e\u0639\u064f\u0648\u0627\u0652 \u0628\u0650\u062e\u064e\u0644\u064e\u0670\u0642\u0650\u0647\u0650\u0645\u06e1 \u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u0645\u06e1\u062a\u064e\u0639\u06e1\u062a\u064f\u0645 \u0628\u0650\u062e\u064e\u0644\u064e\u0670\u0642\u0650\u0643\u064f\u0645\u06e1 \u0643\u064e\u0645\u064e\u0627 \u0671\u0633\u06e1\u062a\u064e\u0645\u06e1\u062a\u064e\u0639\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064f\u0645 \u0628\u0650\u062e\u064e\u0644\u064e\u0670\u0642\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u062e\u064f\u0636\u06e1\u062a\u064f\u0645\u06e1 \u0643\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0627\u0636\u064f\u0648\u0653\u0627\u0652\u06da \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u062d\u064e\u0628\u0650\u0637\u064e\u062a\u06e1 \u0623\u064e\u0639\u06e1\u0645\u064e\u0670\u0644\u064f\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0648\u064e\u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650\u06d6 \u0648\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u062e\u064e\u0670\u0633\u0650\u0631\u064f\u0648\u0646\u064e",translation:"(keadaan kamu kaum munafik dan musyrikin) seperti orang-orang sebelum kamu, mereka lebih kuat daripada kamu, dan lebih banyak harta dan anak-anaknya. Maka mereka telah menikmati bagiannya, dan kamu telah menikmati bagianmu sebagaimana orang-orang yang sebelummu menikmati bagiannya, dan kamu mempercakapkan (hal-hal yang batil) sebagaimana mereka mempercakapkannya. Mereka itu sia-sia amalnya di dunia dan di akhirat. Mereka itulah orang-orang yang rugi"},{id:70,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0623\u06e1\u062a\u0650\u0647\u0650\u0645\u06e1 \u0646\u064e\u0628\u064e\u0623\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u0645\u06e1 \u0642\u064e\u0648\u06e1\u0645\u0650 \u0646\u064f\u0648\u062d\u0656 \u0648\u064e\u0639\u064e\u0627\u062f\u0656 \u0648\u064e\u062b\u064e\u0645\u064f\u0648\u062f\u064e \u0648\u064e\u0642\u064e\u0648\u06e1\u0645\u0650 \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064e \u0648\u064e\u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u0650 \u0645\u064e\u062f\u06e1\u064a\u064e\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u062a\u064e\u0641\u0650\u0643\u064e\u0670\u062a\u0650\u06da \u0623\u064e\u062a\u064e\u062a\u06e1\u0647\u064f\u0645\u06e1 \u0631\u064f\u0633\u064f\u0644\u064f\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0650\u06d6 \u0641\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u064a\u064e\u0638\u06e1\u0644\u0650\u0645\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u0643\u064e\u0627\u0646\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0638\u06e1\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Apakah tidak sampai kepada mereka berita (tentang) orang-orang yang sebelum mereka, (yaitu) kaum Nuh, '\u0100d, Samud, kaum Ibrahim, penduduk Madyan, dan (penduduk) negeri-negeri yang telah musnah? Telah datang kepada mereka Rasul-rasul dengan membawa bukti-bukti yang nyata; Allah tidak menzalimi mereka, tetapi merekalah yang menzalimi diri mereka sendiri"},{id:71,text:"\u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064e\u0670\u062a\u064f \u0628\u064e\u0639\u06e1\u0636\u064f\u0647\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1\u0644\u0650\u064a\u064e\u0627\u0653\u0621\u064f \u0628\u064e\u0639\u06e1\u0636\u0656\u06da \u064a\u064e\u0623\u06e1\u0645\u064f\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u06e1\u0645\u064e\u0639\u06e1\u0631\u064f\u0648\u0641\u0650 \u0648\u064e\u064a\u064e\u0646\u06e1\u0647\u064e\u0648\u06e1\u0646\u064e \u0639\u064e\u0646\u0650 \u0671\u0644\u06e1\u0645\u064f\u0646\u0643\u064e\u0631\u0650 \u0648\u064e\u064a\u064f\u0642\u0650\u064a\u0645\u064f\u0648\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u064a\u064f\u0624\u06e1\u062a\u064f\u0648\u0646\u064e \u0671\u0644\u0632\u0651\u064e\u0643\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u064a\u064f\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f\u06e5\u0653\u06da \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0633\u064e\u064a\u064e\u0631\u06e1\u062d\u064e\u0645\u064f\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06d7 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0632\u0650\u064a\u0632\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u065e",translation:"Dan orang-orang yang beriman, laki-laki dan perempuan, sebagian mereka menjadi penolong bagi sebagian yang lain. Mereka menyuruh (berbuat) yang makruf, dan mencegah dari yang mungkar, melaksanakan salat, menunaikan zakat, dan taat kepada Allah dan Rasul-Nya. Mereka akan diberi rahmat oleh Allah. Sungguh, Allah Mahaperkasa, Mahabijaksana"},{id:72,text:"\u0648\u064e\u0639\u064e\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064e\u0670\u062a\u0650 \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0656 \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0645\u0650\u0646 \u062a\u064e\u062d\u06e1\u062a\u0650\u0647\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u064f \u062e\u064e\u0670\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0645\u064e\u0633\u064e\u0670\u0643\u0650\u0646\u064e \u0637\u064e\u064a\u0651\u0650\u0628\u064e\u0629\u0657 \u0641\u0650\u064a \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0650 \u0639\u064e\u062f\u06e1\u0646\u0656\u06da \u0648\u064e\u0631\u0650\u0636\u06e1\u0648\u064e\u0670\u0646\u065e \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0643\u06e1\u0628\u064e\u0631\u064f\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0641\u064e\u0648\u06e1\u0632\u064f \u0671\u0644\u06e1\u0639\u064e\u0638\u0650\u064a\u0645\u064f",translation:"Allah menjanjikan kepada orang-orang mukmin laki-laki dan perempuan, (akan mendapat) surga yang mengalir di bawahnya sungai-sungai, mereka kekal di dalamnya, dan (mendapat) tempat yang baik di surga 'Adn. Dan keridaan Allah lebih besar. Itulah kemenangan yang agung"},{id:73,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064f \u062c\u064e\u0670\u0647\u0650\u062f\u0650 \u0671\u0644\u06e1\u0643\u064f\u0641\u0651\u064e\u0627\u0631\u064e \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0646\u064e\u0670\u0641\u0650\u0642\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u063a\u06e1\u0644\u064f\u0638\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1\u06da \u0648\u064e\u0645\u064e\u0623\u06e1\u0648\u064e\u0649\u0670\u0647\u064f\u0645\u06e1 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064f\u06d6 \u0648\u064e\u0628\u0650\u0626\u06e1\u0633\u064e \u0671\u0644\u06e1\u0645\u064e\u0635\u0650\u064a\u0631\u064f",translation:"Wahai Nabi! Berjihadlah (melawan) orang-orang kafir dan orang-orang munafik, dan bersikap keraslah terhadap mereka. Tempat mereka adalah neraka Jahanam. Dan itulah seburuk-buruk tempat kembali"},{id:74,text:"\u064a\u064e\u062d\u06e1\u0644\u0650\u0641\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0643\u064e\u0644\u0650\u0645\u064e\u0629\u064e \u0671\u0644\u06e1\u0643\u064f\u0641\u06e1\u0631\u0650 \u0648\u064e\u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0628\u064e\u0639\u06e1\u062f\u064e \u0625\u0650\u0633\u06e1\u0644\u064e\u0670\u0645\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0647\u064e\u0645\u0651\u064f\u0648\u0627\u0652 \u0628\u0650\u0645\u064e\u0627 \u0644\u064e\u0645\u06e1 \u064a\u064e\u0646\u064e\u0627\u0644\u064f\u0648\u0627\u0652\u06da \u0648\u064e\u0645\u064e\u0627 \u0646\u064e\u0642\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646\u06e1 \u0623\u064e\u063a\u06e1\u0646\u064e\u0649\u0670\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0647\u064f\u06e5 \u0645\u0650\u0646 \u0641\u064e\u0636\u06e1\u0644\u0650\u0647\u0650\u06e6\u06da \u0641\u064e\u0625\u0650\u0646 \u064a\u064e\u062a\u064f\u0648\u0628\u064f\u0648\u0627\u0652 \u064a\u064e\u0643\u064f \u062e\u064e\u064a\u06e1\u0631\u0657\u0627 \u0644\u0651\u064e\u0647\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0625\u0650\u0646 \u064a\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u06e1\u0627\u0652 \u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u06e1\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0623\u064e\u0644\u0650\u064a\u0645\u0657\u0627 \u0641\u0650\u064a \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0648\u064e\u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650\u06da \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0645\u0650\u0646 \u0648\u064e\u0644\u0650\u064a\u0651\u0656 \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0635\u0650\u064a\u0631\u0656",translation:"Mereka (orang munafik) bersumpah dengan (nama) Allah, bahwa mereka tidak mengatakan (sesuatu yang menyakiti Muhammad). Sungguh, mereka telah mengucapkan perkataan kekafiran, dan telah menjadi kafir setelah Islam, dan menginginkan apa yang mereka tidak mencapainya;374) dan mereka tidak mencela (Allah dan Rasul-Nya), sekiranya Allah dan Rasul-Nya telah melimpahkan karunia-Nya kepada mereka. Maka jika mereka bertobat, itu adalah lebih baik bagi mereka, dan jika mereka berpaling, niscaya Allah akan mengazab mereka dengan azab yang pedih di dunia dan akhirat; dan mereka tidak mempunyai pelindung dan tidak (pula) penolong di bumi"},{id:75,text:"\u06de\u0648\u064e\u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0646\u06e1 \u0639\u064e\u0670\u0647\u064e\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0626\u0650\u0646\u06e1 \u0621\u064e\u0627\u062a\u064e\u0649\u0670\u0646\u064e\u0627 \u0645\u0650\u0646 \u0641\u064e\u0636\u06e1\u0644\u0650\u0647\u0650\u06e6 \u0644\u064e\u0646\u064e\u0635\u0651\u064e\u062f\u0651\u064e\u0642\u064e\u0646\u0651\u064e \u0648\u064e\u0644\u064e\u0646\u064e\u0643\u064f\u0648\u0646\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u0650\u064a\u0646\u064e",translation:"Dan di antara mereka ada orang yang telah berjanji kepada Allah, \"Sesungguhnya jika Allah memberikan sebagian dari karunia-Nya kepada kami, niscaya kami akan bersedekah dan niscaya kami termasuk orang-orang yang saleh"},{id:76,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u064e\u0649\u0670\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0641\u064e\u0636\u06e1\u0644\u0650\u0647\u0650\u06e6 \u0628\u064e\u062e\u0650\u0644\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6 \u0648\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u0627\u0652 \u0648\u0651\u064e\u0647\u064f\u0645 \u0645\u0651\u064f\u0639\u06e1\u0631\u0650\u0636\u064f\u0648\u0646\u064e",translation:"Ketika Allah memberikan kepada mereka sebagian dari karunia-Nya, mereka menjadi kikir dan berpaling, dan selalu menentang (kebenaran)"},{id:77,text:"\u0641\u064e\u0623\u064e\u0639\u06e1\u0642\u064e\u0628\u064e\u0647\u064f\u0645\u06e1 \u0646\u0650\u0641\u064e\u0627\u0642\u0657\u0627 \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u06e1\u0645\u0650 \u064a\u064e\u0644\u06e1\u0642\u064e\u0648\u06e1\u0646\u064e\u0647\u064f\u06e5 \u0628\u0650\u0645\u064e\u0627\u0653 \u0623\u064e\u062e\u06e1\u0644\u064e\u0641\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064e\u0627 \u0648\u064e\u0639\u064e\u062f\u064f\u0648\u0647\u064f \u0648\u064e\u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0643\u06e1\u0630\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Maka Allah menanamkan kemunafikan dalam hati mereka sampai pada waktu mereka menemui-Nya, karena mereka telah mengingkari janji yang telah mereka ikrarkan kepada-Nya dan (juga) karena mereka selalu berdusta"},{id:78,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0633\u0650\u0631\u0651\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0646\u064e\u062c\u06e1\u0648\u064e\u0649\u0670\u0647\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u0651\u064e\u0640\u0670\u0645\u064f \u0671\u0644\u06e1\u063a\u064f\u064a\u064f\u0648\u0628\u0650",translation:"Tidakkah mereka mengetahui bahwa Allah mengetahui rahasia dan bisikan mereka, dan bahwa Allah mengetahui segala yang gaib"},{id:79,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0644\u06e1\u0645\u0650\u0632\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0637\u0651\u064e\u0648\u0651\u0650\u0639\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u0635\u0651\u064e\u062f\u064e\u0642\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u062c\u0650\u062f\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u062c\u064f\u0647\u06e1\u062f\u064e\u0647\u064f\u0645\u06e1 \u0641\u064e\u064a\u064e\u0633\u06e1\u062e\u064e\u0631\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0633\u064e\u062e\u0650\u0631\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064c",translation:"(Orang munafik) yaitu mereka yang mencela orang-orang beriman yang memberikan sedekah dengan sukarela dan yang (mencela) orang-orang yang hanya punya (untuk disedekahkan) sekedar kesanggupannya, maka orang-orang munafik itu menghina mereka. Allah akan membalas penghinaan mereka, dan mereka akan mendapat azab yang pedih"},{id:80,text:"\u0671\u0633\u06e1\u062a\u064e\u063a\u06e1\u0641\u0650\u0631\u06e1 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1 \u0644\u064e\u0627 \u062a\u064e\u0633\u06e1\u062a\u064e\u063a\u06e1\u0641\u0650\u0631\u06e1 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0625\u0650\u0646 \u062a\u064e\u0633\u06e1\u062a\u064e\u063a\u06e1\u0641\u0650\u0631\u06e1 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0633\u064e\u0628\u06e1\u0639\u0650\u064a\u0646\u064e \u0645\u064e\u0631\u0651\u064e\u0629\u0657 \u0641\u064e\u0644\u064e\u0646 \u064a\u064e\u063a\u06e1\u0641\u0650\u0631\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0647\u064f\u0645\u06e1\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650\u06e6\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064e\u0647\u06e1\u062f\u0650\u064a \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0641\u064e\u0670\u0633\u0650\u0642\u0650\u064a\u0646\u064e",translation:"(Sama saja) engkau (Muhammad) memohonkan ampunan bagi mereka atau tidak memohonkan ampunan bagi mereka. Walaupun engkau memohonkan ampunan bagi mereka tujuh puluh kali, Allah tidak akan memberi ampunan kepada mereka. Yang demikian itu, karena mereka ingkar (kafir) kepada Allah dan Rasul-Nya. Dan Allah tidak memberi petunjuk kepada orang-orang yang fasik"},{id:81,text:"\u0641\u064e\u0631\u0650\u062d\u064e \u0671\u0644\u06e1\u0645\u064f\u062e\u064e\u0644\u0651\u064e\u0641\u064f\u0648\u0646\u064e \u0628\u0650\u0645\u064e\u0642\u06e1\u0639\u064e\u062f\u0650\u0647\u0650\u0645\u06e1 \u062e\u0650\u0644\u064e\u0670\u0641\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0643\u064e\u0631\u0650\u0647\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646 \u064a\u064f\u062c\u064e\u0670\u0647\u0650\u062f\u064f\u0648\u0627\u0652 \u0628\u0650\u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u06e1 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u062a\u064e\u0646\u0641\u0650\u0631\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u06e1\u062d\u064e\u0631\u0651\u0650\u06d7 \u0642\u064f\u0644\u06e1 \u0646\u064e\u0627\u0631\u064f \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0623\u064e\u0634\u064e\u062f\u0651\u064f \u062d\u064e\u0631\u0651\u0657\u0627\u06da \u0644\u0651\u064e\u0648\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0641\u06e1\u0642\u064e\u0647\u064f\u0648\u0646\u064e",translation:"Orang-orang yang ditinggalkan (tidak ikut berperang), merasa gembira duduk-duduk diam sepeninggal Rasulullah. Mereka tidak suka berjihad dengan harta dan jiwa mereka di jalan Allah dan mereka berkata, \"Janganlah kamu berangkat (pergi berperang) dalam panas terik ini.\" Katakanlah (Muhammad), \"Api neraka Jahanam lebih panas,\" jika mereka mengetahui"},{id:82,text:"\u0641\u064e\u0644\u06e1\u064a\u064e\u0636\u06e1\u062d\u064e\u0643\u064f\u0648\u0627\u0652 \u0642\u064e\u0644\u0650\u064a\u0644\u0657\u0627 \u0648\u064e\u0644\u06e1\u064a\u064e\u0628\u06e1\u0643\u064f\u0648\u0627\u0652 \u0643\u064e\u062b\u0650\u064a\u0631\u0657\u0627 \u062c\u064e\u0632\u064e\u0627\u0653\u0621\u064e\u06e2 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0643\u06e1\u0633\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Maka biarkanlah mereka tertawa sedikit dan menangis yang banyak, sebagai balasan terhadap apa yang selalu mereka perbuat"},{id:83,text:"\u0641\u064e\u0625\u0650\u0646 \u0631\u0651\u064e\u062c\u064e\u0639\u064e\u0643\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0637\u064e\u0627\u0653\u0626\u0650\u0641\u064e\u0629\u0656 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u0640\u0654\u06e1\u0630\u064e\u0646\u064f\u0648\u0643\u064e \u0644\u0650\u0644\u06e1\u062e\u064f\u0631\u064f\u0648\u062c\u0650 \u0641\u064e\u0642\u064f\u0644 \u0644\u0651\u064e\u0646 \u062a\u064e\u062e\u06e1\u0631\u064f\u062c\u064f\u0648\u0627\u0652 \u0645\u064e\u0639\u0650\u064a\u064e \u0623\u064e\u0628\u064e\u062f\u0657\u0627 \u0648\u064e\u0644\u064e\u0646 \u062a\u064f\u0642\u064e\u0670\u062a\u0650\u0644\u064f\u0648\u0627\u0652 \u0645\u064e\u0639\u0650\u064a\u064e \u0639\u064e\u062f\u064f\u0648\u0651\u064b\u0627\u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0631\u064e\u0636\u0650\u064a\u062a\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0642\u064f\u0639\u064f\u0648\u062f\u0650 \u0623\u064e\u0648\u0651\u064e\u0644\u064e \u0645\u064e\u0631\u0651\u064e\u0629\u0656 \u0641\u064e\u0671\u0642\u06e1\u0639\u064f\u062f\u064f\u0648\u0627\u0652 \u0645\u064e\u0639\u064e \u0671\u0644\u06e1\u062e\u064e\u0670\u0644\u0650\u0641\u0650\u064a\u0646\u064e",translation:"Maka jika Allah mengembalikanmu (Muhammad) kepada suatu golongan dari mereka (orang-orang munafik), kemudian mereka meminta izin kepadamu untuk keluar (pergi berperang), maka katakanlah, \"Kamu tidak boleh keluar bersamaku selama-lamanya dan tidak boleh memerangi musuh bersamaku. Sesungguhnya kamu telah rela tidak pergi (berperang) sejak semula. Karena itu duduklah (tinggallah) bersama orang-orang yang tidak ikut (berperang)"},{id:84,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0635\u064e\u0644\u0651\u0650 \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u062d\u064e\u062f\u0656 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0627\u062a\u064e \u0623\u064e\u0628\u064e\u062f\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064e\u0628\u06e1\u0631\u0650\u0647\u0650\u06e6\u0653\u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650\u06e6 \u0648\u064e\u0645\u064e\u0627\u062a\u064f\u0648\u0627\u0652 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0641\u064e\u0670\u0633\u0650\u0642\u064f\u0648\u0646\u064e",translation:"Dan janganlah engkau (Muhammad) melaksanakan salat untuk seseorang yang mati di antara mereka (orang-orang munafik), selama-lamanya dan janganlah engkau berdiri (mendoakan) di atas kuburnya. Sesungguhnya mereka ingkar kepada Allah dan Rasul-Nya dan mereka mati dalam keadaan fasik"},{id:85,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0639\u06e1\u062c\u0650\u0628\u06e1\u0643\u064e \u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0648\u06e1\u0644\u064e\u0670\u062f\u064f\u0647\u064f\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0646 \u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064e\u0647\u064f\u0645 \u0628\u0650\u0647\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0648\u064e\u062a\u064e\u0632\u06e1\u0647\u064e\u0642\u064e \u0623\u064e\u0646\u0641\u064f\u0633\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0670\u0641\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Dan janganlah engkau (Muhammad) kagum terhadap harta dan anak-anak mereka. Sesungguhnya dengan itu Allah hendak menyiksa mereka di dunia dan agar nyawa mereka melayang, sedang mereka dalam keadaan kafir"},{id:86,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e\u062a\u06e1 \u0633\u064f\u0648\u0631\u064e\u0629\u064c \u0623\u064e\u0646\u06e1 \u0621\u064e\u0627\u0645\u0650\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u062c\u064e\u0670\u0647\u0650\u062f\u064f\u0648\u0627\u0652 \u0645\u064e\u0639\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650 \u0671\u0633\u06e1\u062a\u064e\u0640\u0654\u06e1\u0630\u064e\u0646\u064e\u0643\u064e \u0623\u064f\u0648\u0652\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0637\u0651\u064e\u0648\u06e1\u0644\u0650 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0630\u064e\u0631\u06e1\u0646\u064e\u0627 \u0646\u064e\u0643\u064f\u0646 \u0645\u0651\u064e\u0639\u064e \u0671\u0644\u06e1\u0642\u064e\u0670\u0639\u0650\u062f\u0650\u064a\u0646\u064e",translation:"Dan apabila diturunkan suatu surah (yang memerintahkan kepada orang-orang munafik), \"Berimanlah kepada Allah dan berjihadlah bersama rasul-Nya, \"niscaya orang-orang yang kaya dan berpengaruh di antara mereka meminta izin kepadamu (untuk tidak berjihad) dan mereka berkata, \"Biarkanlah kami berada bersama orang-orang yang duduk (tinggal di rumah)"},{id:87,text:"\u0631\u064e\u0636\u064f\u0648\u0627\u0652 \u0628\u0650\u0623\u064e\u0646 \u064a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u0645\u064e\u0639\u064e \u0671\u0644\u06e1\u062e\u064e\u0648\u064e\u0627\u0644\u0650\u0641\u0650 \u0648\u064e\u0637\u064f\u0628\u0650\u0639\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u06e1 \u0641\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0641\u06e1\u0642\u064e\u0647\u064f\u0648\u0646\u064e",translation:"(Mereka rela berada bersama orang-orang yang tidak pergi berperang,375) dan hati mereka telah tertutup, sehingga mereka tidak memahami (kebahagiaan beriman dan berjihad)"},{id:88,text:"\u0644\u064e\u0670\u0643\u0650\u0646\u0650 \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064f \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0645\u064e\u0639\u064e\u0647\u064f\u06e5 \u062c\u064e\u0670\u0647\u064e\u062f\u064f\u0648\u0627\u0652 \u0628\u0650\u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u06e1\u06da \u0648\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u062e\u064e\u064a\u06e1\u0631\u064e\u0670\u062a\u064f\u06d6 \u0648\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064f\u0641\u06e1\u0644\u0650\u062d\u064f\u0648\u0646\u064e",translation:"Tetapi Rasul dan orang-orang yang beriman bersama dia, (mereka) berjihad dengan harta dan jiwa. Mereka itu memperoleh kebaikan. Mereka itulah orang-orang yang beruntung"},{id:89,text:"\u0623\u064e\u0639\u064e\u062f\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0647\u064f\u0645\u06e1 \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0656 \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0645\u0650\u0646 \u062a\u064e\u062d\u06e1\u062a\u0650\u0647\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u064f \u062e\u064e\u0670\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0671\u0644\u06e1\u0641\u064e\u0648\u06e1\u0632\u064f \u0671\u0644\u06e1\u0639\u064e\u0638\u0650\u064a\u0645\u064f",translation:"Allah telah menyediakan bagi mereka surga yang mengalir di bawahnya sungai-sungai, mereka kekal di dalamnya. Itulah kemenangan yang agung"},{id:90,text:"\u0648\u064e\u062c\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u06e1\u0645\u064f\u0639\u064e\u0630\u0651\u0650\u0631\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u0639\u06e1\u0631\u064e\u0627\u0628\u0650 \u0644\u0650\u064a\u064f\u0624\u06e1\u0630\u064e\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0642\u064e\u0639\u064e\u062f\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u064e\u0628\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f\u06e5\u06da \u0633\u064e\u064a\u064f\u0635\u0650\u064a\u0628\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Dan di antara orang-orang Arab Badui datang (kepada Nabi) mengemukakan alasan, agar diberi izin (untuk tidak pergi berperang), sedang orang-orang yang mendustakan Allah dan Rasul-Nya, duduk berdiam. Kelak orang-orang yang kafir di antara mereka akan ditimpa azab yang pedih"},{id:91,text:"\u0644\u0651\u064e\u064a\u06e1\u0633\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0636\u0651\u064f\u0639\u064e\u0641\u064e\u0627\u0653\u0621\u0650 \u0648\u064e\u0644\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0645\u064e\u0631\u06e1\u0636\u064e\u0649\u0670 \u0648\u064e\u0644\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u062c\u0650\u062f\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u064a\u064f\u0646\u0641\u0650\u0642\u064f\u0648\u0646\u064e \u062d\u064e\u0631\u064e\u062c\u064c \u0625\u0650\u0630\u064e\u0627 \u0646\u064e\u0635\u064e\u062d\u064f\u0648\u0627\u0652 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650\u06e6\u06da \u0645\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0645\u064f\u062d\u06e1\u0633\u0650\u0646\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0633\u064e\u0628\u0650\u064a\u0644\u0656\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u065e",translation:"Tidak ada dosa (karena tidak pergi berperang) atas orang yang lemah, orang yang sakit dan orang-orang yang tidak memperoleh apa yang akan mereka infakkan, apabila mereka berlaku ikhlas kepada Allah dan Rasul-Nya. Tidak ada alasan apa pun untuk menyalahkan orang-orang yang berbuat baik. Dan Allah Maha Pengampun, Maha Penyayang"},{id:92,text:"\u0648\u064e\u0644\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0627\u0653 \u0623\u064e\u062a\u064e\u0648\u06e1\u0643\u064e \u0644\u0650\u062a\u064e\u062d\u06e1\u0645\u0650\u0644\u064e\u0647\u064f\u0645\u06e1 \u0642\u064f\u0644\u06e1\u062a\u064e \u0644\u064e\u0627\u0653 \u0623\u064e\u062c\u0650\u062f\u064f \u0645\u064e\u0627\u0653 \u0623\u064e\u062d\u06e1\u0645\u0650\u0644\u064f\u0643\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u0627\u0652 \u0648\u0651\u064e\u0623\u064e\u0639\u06e1\u064a\u064f\u0646\u064f\u0647\u064f\u0645\u06e1 \u062a\u064e\u0641\u0650\u064a\u0636\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u062f\u0651\u064e\u0645\u06e1\u0639\u0650 \u062d\u064e\u0632\u064e\u0646\u064b\u0627 \u0623\u064e\u0644\u0651\u064e\u0627 \u064a\u064e\u062c\u0650\u062f\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u064a\u064f\u0646\u0641\u0650\u0642\u064f\u0648\u0646\u064e",translation:"dan tidak ada (pula dosa) atas orang-orang yang datang kepadamu (Muhammad), agar engkau memberi kendaraan kepada mereka, lalu engkau berkata, \"Aku tidak memperoleh kendaraan untuk membawamu,\" lalu mereka kembali, sedang mata mereka bercucuran air mata karena sedih, disebabkan mereka tidak memperoleh apa yang akan mereka infakkan (untuk ikut berperang)"},{id:93,text:"\u06de\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0671\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u064f \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0633\u06e1\u062a\u064e\u0640\u0654\u06e1\u0630\u0650\u0646\u064f\u0648\u0646\u064e\u0643\u064e \u0648\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u063a\u06e1\u0646\u0650\u064a\u064e\u0627\u0653\u0621\u064f\u06da \u0631\u064e\u0636\u064f\u0648\u0627\u0652 \u0628\u0650\u0623\u064e\u0646 \u064a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u0645\u064e\u0639\u064e \u0671\u0644\u06e1\u062e\u064e\u0648\u064e\u0627\u0644\u0650\u0641\u0650 \u0648\u064e\u0637\u064e\u0628\u064e\u0639\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u06e1 \u0641\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Sesungguhnya alasan (untuk menyalahkan) hanyalah terhadap orang-orang yang meminta izin kepadamu, (untuk tidak ikut berperang), padahal mereka orang kaya. Mereka rela berada bersama orang-orang yang tidak ikut berperang dan Allah telah mengunci hati mereka, sehingga mereka tidak mengetahui (akibat perbuatan mereka)"},{id:94,text:"\u064a\u064e\u0639\u06e1\u062a\u064e\u0630\u0650\u0631\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0625\u0650\u0630\u064e\u0627 \u0631\u064e\u062c\u064e\u0639\u06e1\u062a\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1\u06da \u0642\u064f\u0644 \u0644\u0651\u064e\u0627 \u062a\u064e\u0639\u06e1\u062a\u064e\u0630\u0650\u0631\u064f\u0648\u0627\u0652 \u0644\u064e\u0646 \u0646\u0651\u064f\u0624\u06e1\u0645\u0650\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u06e1 \u0642\u064e\u062f\u06e1 \u0646\u064e\u0628\u0651\u064e\u0623\u064e\u0646\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u06e1 \u0623\u064e\u062e\u06e1\u0628\u064e\u0627\u0631\u0650\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0633\u064e\u064a\u064e\u0631\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0645\u064e\u0644\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0647\u064f\u06e5 \u062b\u064f\u0645\u0651\u064e \u062a\u064f\u0631\u064e\u062f\u0651\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0639\u064e\u0670\u0644\u0650\u0645\u0650 \u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u0628\u0650 \u0648\u064e\u0671\u0644\u0634\u0651\u064e\u0647\u064e\u0670\u062f\u064e\u0629\u0650 \u0641\u064e\u064a\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0643\u064f\u0645 \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Mereka (orang-orang munafik yang tidak ikut berperang) akan mengemukakan alasannya kepadamu ketika kamu telah kembali kepada mereka. Katakanlah (Muhammad), \"Janganlah kamu mengemukakan alasan; kami tidak percaya lagi kepadamu, sungguh, Allah telah memberitahukan kepada kami tentang beritamu. Dan Allah akan melihat pekerjaanmu, (demikian pula) Rasul-Nya, kemudian kamu dikembalikan kepada (Allah) Yang Maha Mengetahui segala yang gaib dan yang nyata, lalu Dia memberitakan kepadamu apa yang telah kamu kerjakan"},{id:95,text:"\u0633\u064e\u064a\u064e\u062d\u06e1\u0644\u0650\u0641\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0630\u064e\u0627 \u0671\u0646\u0642\u064e\u0644\u064e\u0628\u06e1\u062a\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0644\u0650\u062a\u064f\u0639\u06e1\u0631\u0650\u0636\u064f\u0648\u0627\u0652 \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1\u06d6 \u0641\u064e\u0623\u064e\u0639\u06e1\u0631\u0650\u0636\u064f\u0648\u0627\u0652 \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1\u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0631\u0650\u062c\u06e1\u0633\u065e\u06d6 \u0648\u064e\u0645\u064e\u0623\u06e1\u0648\u064e\u0649\u0670\u0647\u064f\u0645\u06e1 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064f \u062c\u064e\u0632\u064e\u0627\u0653\u0621\u064e\u06e2 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0643\u06e1\u0633\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Mereka akan bersumpah kepadamu dengan nama Allah, ketika kamu kembali kepada mereka, agar kamu berpaling dari mereka. Maka berpalinglah dari mereka; karena sesungguhnya mereka itu berjiwa kotor dan tempat mereka neraka Jahanam, sebagai balasan atas apa yang telah mereka kerjakan"},{id:96,text:"\u064a\u064e\u062d\u06e1\u0644\u0650\u0641\u064f\u0648\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u06e1 \u0644\u0650\u062a\u064e\u0631\u06e1\u0636\u064e\u0648\u06e1\u0627\u0652 \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1\u06d6 \u0641\u064e\u0625\u0650\u0646 \u062a\u064e\u0631\u06e1\u0636\u064e\u0648\u06e1\u0627\u0652 \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064e\u0631\u06e1\u0636\u064e\u0649\u0670 \u0639\u064e\u0646\u0650 \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0641\u064e\u0670\u0633\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Mereka akan bersumpah kepadamu, agar kamu bersedia menerima mereka. Tetapi sekalipun kamu menerima mereka, Allah tidak akan rida kepada orang-orang yang fasik"},{id:97,text:"\u0671\u0644\u06e1\u0623\u064e\u0639\u06e1\u0631\u064e\u0627\u0628\u064f \u0623\u064e\u0634\u064e\u062f\u0651\u064f \u0643\u064f\u0641\u06e1\u0631\u0657\u0627 \u0648\u064e\u0646\u0650\u0641\u064e\u0627\u0642\u0657\u0627 \u0648\u064e\u0623\u064e\u062c\u06e1\u062f\u064e\u0631\u064f \u0623\u064e\u0644\u0651\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0627\u0652 \u062d\u064f\u062f\u064f\u0648\u062f\u064e \u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650\u06e6\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u065e",translation:"Orang-orang Arab Badui itu lebih kuat kekafiran dan kemunafikannya, dan sangat wajar tidak mengetahui hukum-hukum yang diturunkan Allah kepada Rasul-Nya. Allah Maha Mengetahui, Mahabijaksana"},{id:98,text:"\u0648\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u0639\u06e1\u0631\u064e\u0627\u0628\u0650 \u0645\u064e\u0646 \u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f \u0645\u064e\u0627 \u064a\u064f\u0646\u0641\u0650\u0642\u064f \u0645\u064e\u063a\u06e1\u0631\u064e\u0645\u0657\u0627 \u0648\u064e\u064a\u064e\u062a\u064e\u0631\u064e\u0628\u0651\u064e\u0635\u064f \u0628\u0650\u0643\u064f\u0645\u064f \u0671\u0644\u062f\u0651\u064e\u0648\u064e\u0627\u0653\u0626\u0650\u0631\u064e\u06da \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u062f\u064e\u0627\u0653\u0626\u0650\u0631\u064e\u0629\u064f \u0671\u0644\u0633\u0651\u064e\u0648\u06e1\u0621\u0650\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0633\u064e\u0645\u0650\u064a\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Dan di antara orang-orang Arab Badui itu ada yang memandang apa yang diinfakkannya (di jalan Allah) sebagai suatu kerugian; dia menanti-nanti marabahaya menimpamu, merekalah yang akan ditimpa marabahaya. Allah Maha Mendengar, Maha Mengetahui"},{id:99,text:"\u0648\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u0639\u06e1\u0631\u064e\u0627\u0628\u0650 \u0645\u064e\u0646 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u0650 \u0648\u064e\u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f \u0645\u064e\u0627 \u064a\u064f\u0646\u0641\u0650\u0642\u064f \u0642\u064f\u0631\u064f\u0628\u064e\u0670\u062a\u064d \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0635\u064e\u0644\u064e\u0648\u064e\u0670\u062a\u0650 \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0650\u06da \u0623\u064e\u0644\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0647\u064e\u0627 \u0642\u064f\u0631\u06e1\u0628\u064e\u0629\u065e \u0644\u0651\u064e\u0647\u064f\u0645\u06e1\u06da \u0633\u064e\u064a\u064f\u062f\u06e1\u062e\u0650\u0644\u064f\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u0650\u064a \u0631\u064e\u062d\u06e1\u0645\u064e\u062a\u0650\u0647\u0650\u06e6\u0653\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u065e",translation:"Dan di antara orang-orang Arab Badui itu ada yang beriman kepada Allah dan hari kemudian, dan memandang apa yang diinfakkannya (di jalan Allah) sebagai jalan mendekatkan diri kepada Allah dan sebagai jalan untuk (memperoleh) doa Rasul. Ketahuilah, sesungguhnya infak itu suatu jalan bagi mereka untuk mendekatkan diri (kepada Allah). Kelak Allah akan memasukkan mereka ke dalam rahmat (surga)-Nya; sesungguhnya Allah Maha Pengampun, Maha penyayang"},{id:100,text:"\u0648\u064e\u0671\u0644\u0633\u0651\u064e\u0640\u0670\u0628\u0650\u0642\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u0648\u0651\u064e\u0644\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0647\u064e\u0670\u062c\u0650\u0631\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0646\u0635\u064e\u0627\u0631\u0650 \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0647\u064f\u0645 \u0628\u0650\u0625\u0650\u062d\u06e1\u0633\u064e\u0670\u0646\u0656 \u0631\u0651\u064e\u0636\u0650\u064a\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0648\u064e\u0631\u064e\u0636\u064f\u0648\u0627\u0652 \u0639\u064e\u0646\u06e1\u0647\u064f \u0648\u064e\u0623\u064e\u0639\u064e\u062f\u0651\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0656 \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u062a\u064e\u062d\u06e1\u062a\u064e\u0647\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u064f \u062e\u064e\u0670\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627\u0653 \u0623\u064e\u0628\u064e\u062f\u0657\u0627\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0671\u0644\u06e1\u0641\u064e\u0648\u06e1\u0632\u064f \u0671\u0644\u06e1\u0639\u064e\u0638\u0650\u064a\u0645\u064f",translation:"Dan orang-orang yang terdahulu lagi yang pertama-tama (masuk Islam) di antara orang-orang Muhajirin dan Ansar dan orang-orang yang mengikuti mereka dengan baik, Allah rida kepada mereka dan mereka pun rida kepada Allah. Allah menyediakan bagi mereka surga-surga yang mengalir di bawahnya sungai-sungai. Mereka kekal di dalamnya selama-lamanya. Itulah kemenangan yang agung"},{id:101,text:"\u0648\u064e\u0645\u0650\u0645\u0651\u064e\u0646\u06e1 \u062d\u064e\u0648\u06e1\u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u0639\u06e1\u0631\u064e\u0627\u0628\u0650 \u0645\u064f\u0646\u064e\u0670\u0641\u0650\u0642\u064f\u0648\u0646\u064e\u06d6 \u0648\u064e\u0645\u0650\u0646\u06e1 \u0623\u064e\u0647\u06e1\u0644\u0650 \u0671\u0644\u06e1\u0645\u064e\u062f\u0650\u064a\u0646\u064e\u0629\u0650 \u0645\u064e\u0631\u064e\u062f\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0646\u0651\u0650\u0641\u064e\u0627\u0642\u0650 \u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0647\u064f\u0645\u06e1\u06d6 \u0646\u064e\u062d\u06e1\u0646\u064f \u0646\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0647\u064f\u0645\u06e1\u06da \u0633\u064e\u0646\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064f\u0647\u064f\u0645 \u0645\u0651\u064e\u0631\u0651\u064e\u062a\u064e\u064a\u06e1\u0646\u0650 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0631\u064e\u062f\u0651\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0639\u064e\u0630\u064e\u0627\u0628\u064d \u0639\u064e\u0638\u0650\u064a\u0645\u0656",translation:"Dan di antara orang-orang Arab Badui yang (tinggal) di sekitarmu, ada orang-orang munafik. Dan di antara penduduk Madinah (ada juga orang-orang munafik), mereka keterlaluan dalam kemunafikannya. Engkau (Muhammad) tidak mengetahui mereka, tetapi Kami mengetahuinya. Nanti mereka akan Kami siksa dua kali, kemudian mereka akan dikembalikan kepada azab yang besar"},{id:102,text:"\u0648\u064e\u0621\u064e\u0627\u062e\u064e\u0631\u064f\u0648\u0646\u064e \u0671\u0639\u06e1\u062a\u064e\u0631\u064e\u0641\u064f\u0648\u0627\u0652 \u0628\u0650\u0630\u064f\u0646\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u06e1 \u062e\u064e\u0644\u064e\u0637\u064f\u0648\u0627\u0652 \u0639\u064e\u0645\u064e\u0644\u0657\u0627 \u0635\u064e\u0670\u0644\u0650\u062d\u0657\u0627 \u0648\u064e\u0621\u064e\u0627\u062e\u064e\u0631\u064e \u0633\u064e\u064a\u0651\u0650\u0626\u064b\u0627 \u0639\u064e\u0633\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0646 \u064a\u064e\u062a\u064f\u0648\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064c",translation:"Dan (ada pula) orang lain yang mengakui dosa-dosa mereka, mereka mencampuradukkan pekerjaan yang baik dengan pekerjaan lain yang buruk. Mudah-mudahan Allah menerima tobat mereka. Sesungguhnya Allah Maha Pengampun, Maha Penyayang"},{id:103,text:"\u062e\u064f\u0630\u06e1 \u0645\u0650\u0646\u06e1 \u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u0650\u0647\u0650\u0645\u06e1 \u0635\u064e\u062f\u064e\u0642\u064e\u0629\u0657 \u062a\u064f\u0637\u064e\u0647\u0651\u0650\u0631\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u062a\u064f\u0632\u064e\u0643\u0651\u0650\u064a\u0647\u0650\u0645 \u0628\u0650\u0647\u064e\u0627 \u0648\u064e\u0635\u064e\u0644\u0651\u0650 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1\u06d6 \u0625\u0650\u0646\u0651\u064e \u0635\u064e\u0644\u064e\u0648\u0670\u062a\u064e\u0643\u064e \u0633\u064e\u0643\u064e\u0646\u065e \u0644\u0651\u064e\u0647\u064f\u0645\u06e1\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0633\u064e\u0645\u0650\u064a\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u064c",translation:"(Ambillah zakat dari harta mereka, guna membersihkan376) dan menyucikan377) mereka, dan berdoalah untuk mereka. Sesungguhnya doamu itu (menumbuhkan) ketenteraman jiwa bagi mereka. Allah Maha Mendengar, Maha Mengetahui"},{id:104,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0647\u064f\u0648\u064e \u064a\u064e\u0642\u06e1\u0628\u064e\u0644\u064f \u0671\u0644\u062a\u0651\u064e\u0648\u06e1\u0628\u064e\u0629\u064e \u0639\u064e\u0646\u06e1 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650\u06e6 \u0648\u064e\u064a\u064e\u0623\u06e1\u062e\u064f\u0630\u064f \u0671\u0644\u0635\u0651\u064e\u062f\u064e\u0642\u064e\u0670\u062a\u0650 \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0647\u064f\u0648\u064e \u0671\u0644\u062a\u0651\u064e\u0648\u0651\u064e\u0627\u0628\u064f \u0671\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",translation:"Tidakkah mereka mengetahui, bahwa Allah menerima tobat hamba-hamba-Nya dan menerima zakat(nya), dan bahwa Allah Maha Penerima tobat, Maha Penyayang"},{id:105,text:"\u0648\u064e\u0642\u064f\u0644\u0650 \u0671\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0627\u0652 \u0641\u064e\u0633\u064e\u064a\u064e\u0631\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0645\u064e\u0644\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0647\u064f\u06e5 \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e\u06d6 \u0648\u064e\u0633\u064e\u062a\u064f\u0631\u064e\u062f\u0651\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0639\u064e\u0670\u0644\u0650\u0645\u0650 \u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u0628\u0650 \u0648\u064e\u0671\u0644\u0634\u0651\u064e\u0647\u064e\u0670\u062f\u064e\u0629\u0650 \u0641\u064e\u064a\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0643\u064f\u0645 \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan katakanlah, \"Bekerjalah kamu, maka Allah akan melihat pekerjaanmu, begitu juga Rasul-Nya dan orang-orang mukmin, dan kamu akan dikembalikan kepada (Allah) Yang Mengetahui yang gaib dan yang nyata, lalu diberitakan-Nya kepada kamu apa yang telah kamu kerjakan"},{id:106,text:"\u0648\u064e\u0621\u064e\u0627\u062e\u064e\u0631\u064f\u0648\u0646\u064e \u0645\u064f\u0631\u06e1\u062c\u064e\u0648\u06e1\u0646\u064e \u0644\u0650\u0623\u064e\u0645\u06e1\u0631\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0645\u0651\u064e\u0627 \u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0625\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u062a\u064f\u0648\u0628\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u065e",translation:"Dan ada (pula) orang-orang lain yang ditangguhkan sampai ada keputusan Allah; mungkin Allah akan mengazab mereka dan mungkin Allah akan menerima tobat mereka. Allah Maha Mengetahui, Mahabijaksana"},{id:107,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627\u0652 \u0645\u064e\u0633\u06e1\u062c\u0650\u062f\u0657\u0627 \u0636\u0650\u0631\u064e\u0627\u0631\u0657\u0627 \u0648\u064e\u0643\u064f\u0641\u06e1\u0631\u0657\u0627 \u0648\u064e\u062a\u064e\u0641\u06e1\u0631\u0650\u064a\u0642\u064e\u06e2\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0625\u0650\u0631\u06e1\u0635\u064e\u0627\u062f\u0657\u0627 \u0644\u0651\u0650\u0645\u064e\u0646\u06e1 \u062d\u064e\u0627\u0631\u064e\u0628\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f\u06da \u0648\u064e\u0644\u064e\u064a\u064e\u062d\u06e1\u0644\u0650\u0641\u064f\u0646\u0651\u064e \u0625\u0650\u0646\u06e1 \u0623\u064e\u0631\u064e\u062f\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u06e1\u062d\u064f\u0633\u06e1\u0646\u064e\u0649\u0670\u06d6 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0634\u06e1\u0647\u064e\u062f\u064f \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0643\u064e\u0670\u0630\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Dan (di antara orang-orang munafik itu) ada yang mendirikan masjid untuk menimbulkan bencana (pada orang-orang yang beriman), untuk kekafiran dan untuk memecah belah di antara orang-orang yang beriman, serta untuk menunggu kedatangan orang-orang yang telah memerangi Allah dan Rasul-Nya sejak dahulu.378) Mereka dengan pasti bersumpah, \"Kami hanya menghendaki kebaikan.\" Dan Allah menjadi saksi bahwa mereka itu pendusta (dalam sumpahnya)"},{id:108,text:"\u0644\u064e\u0627 \u062a\u064e\u0642\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u0650 \u0623\u064e\u0628\u064e\u062f\u0657\u0627\u06da \u0644\u0651\u064e\u0645\u064e\u0633\u06e1\u062c\u0650\u062f\u064c \u0623\u064f\u0633\u0651\u0650\u0633\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u062a\u0651\u064e\u0642\u06e1\u0648\u064e\u0649\u0670 \u0645\u0650\u0646\u06e1 \u0623\u064e\u0648\u0651\u064e\u0644\u0650 \u064a\u064e\u0648\u06e1\u0645\u064d \u0623\u064e\u062d\u064e\u0642\u0651\u064f \u0623\u064e\u0646 \u062a\u064e\u0642\u064f\u0648\u0645\u064e \u0641\u0650\u064a\u0647\u0650\u06da \u0641\u0650\u064a\u0647\u0650 \u0631\u0650\u062c\u064e\u0627\u0644\u065e \u064a\u064f\u062d\u0650\u0628\u0651\u064f\u0648\u0646\u064e \u0623\u064e\u0646 \u064a\u064e\u062a\u064e\u0637\u064e\u0647\u0651\u064e\u0631\u064f\u0648\u0627\u0652\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0671\u0644\u06e1\u0645\u064f\u0637\u0651\u064e\u0647\u0651\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Janganlah engkau melaksanakan salat dalam masjid itu selama-lamanya. Sungguh, masjid yang didirikan atas dasar takwa, sejak hari pertama adalah lebih pantas engkau melaksanakan salat di dalamnya. Di sana ada orang-orang yang ingin membersihkan diri. Allah menyukai orang-orang yang bersih"},{id:109,text:"\u0623\u064e\u0641\u064e\u0645\u064e\u0646\u06e1 \u0623\u064e\u0633\u0651\u064e\u0633\u064e \u0628\u064f\u0646\u06e1\u064a\u064e\u0670\u0646\u064e\u0647\u064f\u06e5 \u0639\u064e\u0644\u064e\u0649\u0670 \u062a\u064e\u0642\u06e1\u0648\u064e\u0649\u0670 \u0645\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u0650\u0636\u06e1\u0648\u064e\u0670\u0646\u064d \u062e\u064e\u064a\u06e1\u0631\u064c \u0623\u064e\u0645 \u0645\u0651\u064e\u0646\u06e1 \u0623\u064e\u0633\u0651\u064e\u0633\u064e \u0628\u064f\u0646\u06e1\u064a\u064e\u0670\u0646\u064e\u0647\u064f\u06e5 \u0639\u064e\u0644\u064e\u0649\u0670 \u0634\u064e\u0641\u064e\u0627 \u062c\u064f\u0631\u064f\u0641\u064d \u0647\u064e\u0627\u0631\u0656 \u0641\u064e\u0671\u0646\u06e1\u0647\u064e\u0627\u0631\u064e \u0628\u0650\u0647\u0650\u06e6 \u0641\u0650\u064a \u0646\u064e\u0627\u0631\u0650 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064e\u0647\u06e1\u062f\u0650\u064a \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Maka apakah orang-orang yang mendirikan bangunan (masjid) atas dasar takwa kepada Allah dan keridaan(-Nya) itu lebih baik, ataukah orang-orang yang mendirikan bangunannya di tepi jurang yang runtuh, lalu (bangunan) itu roboh bersama-sama dengan dia ke dalam neraka Jahanam? Allah tidak memberi petunjuk kepada orang-orang yang zalim"},{id:110,text:"\u0644\u064e\u0627 \u064a\u064e\u0632\u064e\u0627\u0644\u064f \u0628\u064f\u0646\u06e1\u064a\u064e\u0670\u0646\u064f\u0647\u064f\u0645\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0628\u064e\u0646\u064e\u0648\u06e1\u0627\u0652 \u0631\u0650\u064a\u0628\u064e\u0629\u0657 \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u062a\u064e\u0642\u064e\u0637\u0651\u064e\u0639\u064e \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u06e1\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u064c",translation:"(Bangunan yang mereka dirikan itu senantiasa menjadi penyebab keraguan dalam hati mereka, sampai hati mereka hancur.379) Dan Allah Maha Mengetahui, Mahabijaksana"},{id:111,text:"\u06de\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0671\u0634\u06e1\u062a\u064e\u0631\u064e\u0649\u0670 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u064e\u0647\u064f\u0645 \u0628\u0650\u0623\u064e\u0646\u0651\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u064e\u06da \u064a\u064f\u0642\u064e\u0670\u062a\u0650\u0644\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u064a\u064e\u0642\u06e1\u062a\u064f\u0644\u064f\u0648\u0646\u064e \u0648\u064e\u064a\u064f\u0642\u06e1\u062a\u064e\u0644\u064f\u0648\u0646\u064e\u06d6 \u0648\u064e\u0639\u06e1\u062f\u064b\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u062d\u064e\u0642\u0651\u0657\u0627 \u0641\u0650\u064a \u0671\u0644\u062a\u0651\u064e\u0648\u06e1\u0631\u064e\u0649\u0670\u0629\u0650 \u0648\u064e\u0671\u0644\u06e1\u0625\u0650\u0646\u062c\u0650\u064a\u0644\u0650 \u0648\u064e\u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u0650\u06da \u0648\u064e\u0645\u064e\u0646\u06e1 \u0623\u064e\u0648\u06e1\u0641\u064e\u0649\u0670 \u0628\u0650\u0639\u064e\u0647\u06e1\u062f\u0650\u0647\u0650\u06e6 \u0645\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u0628\u06e1\u0634\u0650\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0628\u064e\u064a\u06e1\u0639\u0650\u0643\u064f\u0645\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0628\u064e\u0627\u064a\u064e\u0639\u06e1\u062a\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6\u06da \u0648\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0641\u064e\u0648\u06e1\u0632\u064f \u0671\u0644\u06e1\u0639\u064e\u0638\u0650\u064a\u0645\u064f",translation:"Sesungguhnya Allah membeli dari orang-orang mukmin, baik diri maupun harta mereka dengan memberikan surga untuk mereka. Mereka berperang di jalan Allah; sehingga mereka membunuh atau terbunuh, (sebagai) janji yang benar dari Allah di dalam Taurat, Injil dan Alquran. Dan siapakah yang lebih menepati janjinya selain Allah? Maka bergembiralah dengan jual beli yang telah kamu lakukan itu, dan demikian itulah kemenangan yang agung"},{id:112,text:"\u0671\u0644\u062a\u0651\u064e\u0640\u0670\u0653\u0626\u0650\u0628\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0639\u064e\u0670\u0628\u0650\u062f\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u062d\u064e\u0670\u0645\u0650\u062f\u064f\u0648\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0640\u0670\u0653\u0626\u0650\u062d\u064f\u0648\u0646\u064e \u0671\u0644\u0631\u0651\u064e\u0640\u0670\u0643\u0650\u0639\u064f\u0648\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0640\u0670\u062c\u0650\u062f\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0623\u0653\u0645\u0650\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u06e1\u0645\u064e\u0639\u06e1\u0631\u064f\u0648\u0641\u0650 \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0627\u0647\u064f\u0648\u0646\u064e \u0639\u064e\u0646\u0650 \u0671\u0644\u06e1\u0645\u064f\u0646\u0643\u064e\u0631\u0650 \u0648\u064e\u0671\u0644\u06e1\u062d\u064e\u0670\u0641\u0650\u0638\u064f\u0648\u0646\u064e \u0644\u0650\u062d\u064f\u062f\u064f\u0648\u062f\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d7 \u0648\u064e\u0628\u064e\u0634\u0651\u0650\u0631\u0650 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Mereka itu adalah orang-orang yang bertobat, beribadah, memuji (Allah), mengembara (demi ilmu dan agama),380) rukuk, sujud, menyuruh berbuat makruf dan mencegah dari yang mungkar dan yang memelihara hukum-hukum Allah. Dan gembirakanlah orang-orang yang beriman"},{id:113,text:"\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650 \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646 \u064a\u064e\u0633\u06e1\u062a\u064e\u063a\u06e1\u0641\u0650\u0631\u064f\u0648\u0627\u0652 \u0644\u0650\u0644\u06e1\u0645\u064f\u0634\u06e1\u0631\u0650\u0643\u0650\u064a\u0646\u064e \u0648\u064e\u0644\u064e\u0648\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0653\u0627\u0652 \u0623\u064f\u0648\u0652\u0644\u0650\u064a \u0642\u064f\u0631\u06e1\u0628\u064e\u0649\u0670 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0645\u064e\u0627 \u062a\u064e\u0628\u064e\u064a\u0651\u064e\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u06e1\u062c\u064e\u062d\u0650\u064a\u0645\u0650",translation:"Tidak pantas bagi Nabi dan orang-orang yang beriman memohonkan ampunan (kepada Allah) bagi orang-orang musyrik, sekalipun orang-orang itu kaum kerabat-(nya), setelah jelas bagi mereka, bahwa orang-orang musyrik itu penghuni neraka Jahanam"},{id:114,text:"\u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0671\u0633\u06e1\u062a\u0650\u063a\u06e1\u0641\u064e\u0627\u0631\u064f \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064e \u0644\u0650\u0623\u064e\u0628\u0650\u064a\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0646 \u0645\u0651\u064e\u0648\u06e1\u0639\u0650\u062f\u064e\u0629\u0656 \u0648\u064e\u0639\u064e\u062f\u064e\u0647\u064e\u0627\u0653 \u0625\u0650\u064a\u0651\u064e\u0627\u0647\u064f \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062a\u064e\u0628\u064e\u064a\u0651\u064e\u0646\u064e \u0644\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u06e5 \u0639\u064e\u062f\u064f\u0648\u0651\u065e \u0644\u0651\u0650\u0644\u0651\u064e\u0647\u0650 \u062a\u064e\u0628\u064e\u0631\u0651\u064e\u0623\u064e \u0645\u0650\u0646\u06e1\u0647\u064f\u06da \u0625\u0650\u0646\u0651\u064e \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064e \u0644\u064e\u0623\u064e\u0648\u0651\u064e\u0640\u0670\u0647\u064c \u062d\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Adapun permohonan ampunan Ibrahim (kepada Allah) untuk bapaknya, tidak lain hanyalah karena suatu janji yang telah diikrarkannya kepada bapaknya. Maka ketika jelas bagi Ibrahim bahwa bapaknya adalah musuh Allah, maka Ibrahim berlepas diri darinya. Sungguh, Ibrahim itu seorang yang sangat lembut hatinya lagi penyantun"},{id:115,text:"\u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u064a\u064f\u0636\u0650\u0644\u0651\u064e \u0642\u064e\u0648\u06e1\u0645\u064e\u06e2\u0627 \u0628\u064e\u0639\u06e1\u062f\u064e \u0625\u0650\u0630\u06e1 \u0647\u064e\u062f\u064e\u0649\u0670\u0647\u064f\u0645\u06e1 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064e \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u0627 \u064a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u064c",translation:"(Dan Allah sekali-kali tidak akan menyesatkan suatu kaum, setelah mereka diberi-Nya petunjuk, sehingga dapat dijelaskan kepada mereka apa yang harus mereka jauhi.381) Sungguh, Allah Maha Mengetahui segala sesuatu"},{id:116,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0647\u064f\u06e5 \u0645\u064f\u0644\u06e1\u0643\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d6 \u064a\u064f\u062d\u06e1\u064a\u0650\u06e6 \u0648\u064e\u064a\u064f\u0645\u0650\u064a\u062a\u064f\u06da \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646 \u0648\u064e\u0644\u0650\u064a\u0651\u0656 \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0635\u0650\u064a\u0631\u0656",translation:"Sesungguhnya Allah memiliki kekuasaan langit dan bumi. Dia menghidupkan dan mematikan. Tidak ada pelindung dan penolong bagimu selain Allah"},{id:117,text:"\u0644\u0651\u064e\u0642\u064e\u062f \u062a\u0651\u064e\u0627\u0628\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650 \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0647\u064e\u0670\u062c\u0650\u0631\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0646\u0635\u064e\u0627\u0631\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0647\u064f \u0641\u0650\u064a \u0633\u064e\u0627\u0639\u064e\u0629\u0650 \u0671\u0644\u06e1\u0639\u064f\u0633\u06e1\u0631\u064e\u0629\u0650 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0645\u064e\u0627 \u0643\u064e\u0627\u062f\u064e \u064a\u064e\u0632\u0650\u064a\u063a\u064f \u0642\u064f\u0644\u064f\u0648\u0628\u064f \u0641\u064e\u0631\u0650\u064a\u0642\u0656 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u062b\u064f\u0645\u0651\u064e \u062a\u064e\u0627\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0628\u0650\u0647\u0650\u0645\u06e1 \u0631\u064e\u0621\u064f\u0648\u0641\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u065e",translation:"Sungguh, Allah telah menerima tobat Nabi, orang-orang Muhajirin dan orang-orang Ansar, yang mengikuti Nabi pada masa-masa sulit, setelah hati segolongan dari mereka hampir berpaling, kemudian Allah menerima tobat mereka. Sesungguhnya Allah Maha Pengasih, Maha Penyayang kepada mereka"},{id:118,text:"\u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u062b\u0651\u064e\u0644\u064e\u0670\u062b\u064e\u0629\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062e\u064f\u0644\u0651\u0650\u0641\u064f\u0648\u0627\u0652 \u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u064e\u0627 \u0636\u064e\u0627\u0642\u064e\u062a\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064f \u0628\u0650\u0645\u064e\u0627 \u0631\u064e\u062d\u064f\u0628\u064e\u062a\u06e1 \u0648\u064e\u0636\u064e\u0627\u0642\u064e\u062a\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0623\u064e\u0646\u0641\u064f\u0633\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0638\u064e\u0646\u0651\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646 \u0644\u0651\u064e\u0627 \u0645\u064e\u0644\u06e1\u062c\u064e\u0623\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u062b\u064f\u0645\u0651\u064e \u062a\u064e\u0627\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0644\u0650\u064a\u064e\u062a\u064f\u0648\u0628\u064f\u0648\u0653\u0627\u0652\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0647\u064f\u0648\u064e \u0671\u0644\u062a\u0651\u064e\u0648\u0651\u064e\u0627\u0628\u064f \u0671\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",translation:"(dan terhadap tiga orang382) yang ditinggalkan. Hingga ketika bumi terasa sempit bagi mereka, padahal bumi itu luas dan jiwa mereka pun telah (pula terasa) sempit bagi mereka, serta mereka telah mengetahui bahwa tidak ada tempat lari dari (siksaan) Allah, melainkan kepada-Nya saja, kemudian Allah menerima tobat mereka agar mereka tetap dalam tobatnya. Sesungguhnya Allah Maha Penerima tobat, Maha Penyayang"},{id:119,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u0645\u064e\u0639\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Wahai orang-orang yang beriman! Bertakwalah kepada Allah, dan bersamalah kamu dengan orang-orang yang benar"},{id:120,text:"\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0623\u064e\u0647\u06e1\u0644\u0650 \u0671\u0644\u06e1\u0645\u064e\u062f\u0650\u064a\u0646\u064e\u0629\u0650 \u0648\u064e\u0645\u064e\u0646\u06e1 \u062d\u064e\u0648\u06e1\u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u0639\u06e1\u0631\u064e\u0627\u0628\u0650 \u0623\u064e\u0646 \u064a\u064e\u062a\u064e\u062e\u064e\u0644\u0651\u064e\u0641\u064f\u0648\u0627\u0652 \u0639\u064e\u0646 \u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0631\u06e1\u063a\u064e\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u06e1 \u0639\u064e\u0646 \u0646\u0651\u064e\u0641\u06e1\u0633\u0650\u0647\u0650\u06e6\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064f\u0635\u0650\u064a\u0628\u064f\u0647\u064f\u0645\u06e1 \u0638\u064e\u0645\u064e\u0623\u065e \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0635\u064e\u0628\u065e \u0648\u064e\u0644\u064e\u0627 \u0645\u064e\u062e\u06e1\u0645\u064e\u0635\u064e\u0629\u065e \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0637\u064e\u0640\u0654\u064f\u0648\u0646\u064e \u0645\u064e\u0648\u06e1\u0637\u0650\u0626\u0657\u0627 \u064a\u064e\u063a\u0650\u064a\u0638\u064f \u0671\u0644\u06e1\u0643\u064f\u0641\u0651\u064e\u0627\u0631\u064e \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0646\u064e\u0627\u0644\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u06e1 \u0639\u064e\u062f\u064f\u0648\u0651\u0656 \u0646\u0651\u064e\u064a\u06e1\u0644\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064f\u062a\u0650\u0628\u064e \u0644\u064e\u0647\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6 \u0639\u064e\u0645\u064e\u0644\u065e \u0635\u064e\u0670\u0644\u0650\u062d\u064c\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064f\u0636\u0650\u064a\u0639\u064f \u0623\u064e\u062c\u06e1\u0631\u064e \u0671\u0644\u06e1\u0645\u064f\u062d\u06e1\u0633\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Tidak pantas bagi penduduk Madinah dan orang-orang Arab Badui yang berdiam di sekitar mereka, tidak turut menyertai Rasulullah (pergi berperang) dan tidak pantas (pula) bagi mereka lebih mencintai diri mereka daripada (mencintai) diri Rasul. Yang demikian itu karena mereka tidak ditimpa kehausan, kepayahan dan kelaparan di jalan Allah, dan tidak (pula) menginjak suatu tempat yang membangkitkan amarah orang-orang kafir, dan tidak menimpakan suatu bencana kepada musuh, kecuali (semua) itu dituliskan bagi mereka sebagai suatu amal kebajikan. Sungguh, Allah tidak menyia-nyiakan pahala orang-orang yang berbuat baik"},{id:121,text:"\u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0646\u0641\u0650\u0642\u064f\u0648\u0646\u064e \u0646\u064e\u0641\u064e\u0642\u064e\u0629\u0657 \u0635\u064e\u063a\u0650\u064a\u0631\u064e\u0629\u0657 \u0648\u064e\u0644\u064e\u0627 \u0643\u064e\u0628\u0650\u064a\u0631\u064e\u0629\u0657 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0642\u06e1\u0637\u064e\u0639\u064f\u0648\u0646\u064e \u0648\u064e\u0627\u062f\u0650\u064a\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064f\u062a\u0650\u0628\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0644\u0650\u064a\u064e\u062c\u06e1\u0632\u0650\u064a\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064e \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"dan tidaklah mereka memberikan infak, baik yang kecil maupun yang besar dan tidak (pula) melintasi suatu lembah (berjihad), kecuali akan dituliskan bagi mereka (sebagai amal kebajikan), untuk diberi balasan oleh Allah (dengan) yang lebih baik daripada apa yang telah mereka kerjakan"},{id:122,text:"\u06de\u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0644\u0650\u064a\u064e\u0646\u0641\u0650\u0631\u064f\u0648\u0627\u0652 \u0643\u064e\u0627\u0653\u0641\u0651\u064e\u0629\u0657\u06da \u0641\u064e\u0644\u064e\u0648\u06e1\u0644\u064e\u0627 \u0646\u064e\u0641\u064e\u0631\u064e \u0645\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u0641\u0650\u0631\u06e1\u0642\u064e\u0629\u0656 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0637\u064e\u0627\u0653\u0626\u0650\u0641\u064e\u0629\u065e \u0644\u0651\u0650\u064a\u064e\u062a\u064e\u0641\u064e\u0642\u0651\u064e\u0647\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u0650 \u0648\u064e\u0644\u0650\u064a\u064f\u0646\u0630\u0650\u0631\u064f\u0648\u0627\u0652 \u0642\u064e\u0648\u06e1\u0645\u064e\u0647\u064f\u0645\u06e1 \u0625\u0650\u0630\u064e\u0627 \u0631\u064e\u062c\u064e\u0639\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u062d\u06e1\u0630\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan tidak sepatutnya orang-orang mukmin itu semuanya pergi (ke medan perang). Mengapa sebagian dari setiap golongan di antara mereka tidak pergi untuk memperdalam pengetahuan agama mereka dan untuk memberi peringatan kepada kaumnya apabila mereka telah kembali, agar mereka dapat menjaga dirinya"},{id:123,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0642\u064e\u0670\u062a\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0644\u064f\u0648\u0646\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0643\u064f\u0641\u0651\u064e\u0627\u0631\u0650 \u0648\u064e\u0644\u06e1\u064a\u064e\u062c\u0650\u062f\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0643\u064f\u0645\u06e1 \u063a\u0650\u0644\u06e1\u0638\u064e\u0629\u0657\u06da \u0648\u064e\u0671\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064e\u0639\u064e \u0671\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",translation:"Wahai orang-orang beriman! Perangilah orang-orang kafir yang di sekitar kamu, dan hendaklah mereka merasakan sikap tegas darimu, dan ketahuilah bahwa Allah bersama orang yang bertakwa"},{id:124,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e\u062a\u06e1 \u0633\u064f\u0648\u0631\u064e\u0629\u065e \u0641\u064e\u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0646 \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0623\u064e\u064a\u0651\u064f\u0643\u064f\u0645\u06e1 \u0632\u064e\u0627\u062f\u064e\u062a\u06e1\u0647\u064f \u0647\u064e\u0670\u0630\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u064a\u0645\u064e\u0670\u0646\u0657\u0627\u06da \u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0641\u064e\u0632\u064e\u0627\u062f\u064e\u062a\u06e1\u0647\u064f\u0645\u06e1 \u0625\u0650\u064a\u0645\u064e\u0670\u0646\u0657\u0627 \u0648\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0633\u06e1\u062a\u064e\u0628\u06e1\u0634\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Dan apabila diturunkan suatu surah, maka di antara mereka (orang-orang munafik) ada yang berkata, \"Siapakah di antara kamu yang bertambah imannya dengan (turunnya) surah ini?\" Adapun orang-orang yang beriman, maka surah ini menambah imannya, dan mereka merasa gembira"},{id:125,text:"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645 \u0645\u0651\u064e\u0631\u064e\u0636\u065e \u0641\u064e\u0632\u064e\u0627\u062f\u064e\u062a\u06e1\u0647\u064f\u0645\u06e1 \u0631\u0650\u062c\u06e1\u0633\u064b\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u0650\u062c\u06e1\u0633\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627\u062a\u064f\u0648\u0627\u0652 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0670\u0641\u0650\u0631\u064f\u0648\u0646\u064e",translation:"(Dan adapun orang-orang yang di dalam hatinya ada penyakit,383) maka (dengan surah itu) akan menambah kekafiran mereka yang telah ada dan mereka akan mati dalam keadaan kafir"},{id:126,text:"\u0623\u064e\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0631\u064e\u0648\u06e1\u0646\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064f\u0641\u06e1\u062a\u064e\u0646\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0643\u064f\u0644\u0651\u0650 \u0639\u064e\u0627\u0645\u0656 \u0645\u0651\u064e\u0631\u0651\u064e\u0629\u064b \u0623\u064e\u0648\u06e1 \u0645\u064e\u0631\u0651\u064e\u062a\u064e\u064a\u06e1\u0646\u0650 \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0627 \u064a\u064e\u062a\u064f\u0648\u0628\u064f\u0648\u0646\u064e \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u06e1 \u064a\u064e\u0630\u0651\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan tidaklah mereka (orang-orang munafik) memperhatikan bahwa mereka diuji sekali atau dua kali setiap tahun, namun mereka tidak (juga) bertobat dan tidak (pula) mengambil pelajaran"},{id:127,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e\u062a\u06e1 \u0633\u064f\u0648\u0631\u064e\u0629\u065e \u0646\u0651\u064e\u0638\u064e\u0631\u064e \u0628\u064e\u0639\u06e1\u0636\u064f\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u06e1\u0636\u064d \u0647\u064e\u0644\u06e1 \u064a\u064e\u0631\u064e\u0649\u0670\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u062d\u064e\u062f\u0656 \u062b\u064f\u0645\u0651\u064e \u0671\u0646\u0635\u064e\u0631\u064e\u0641\u064f\u0648\u0627\u0652\u06da \u0635\u064e\u0631\u064e\u0641\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0642\u064f\u0644\u064f\u0648\u0628\u064e\u0647\u064f\u0645 \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0642\u064e\u0648\u06e1\u0645\u065e \u0644\u0651\u064e\u0627 \u064a\u064e\u0641\u06e1\u0642\u064e\u0647\u064f\u0648\u0646\u064e",translation:"Dan apabila diturunkan suatu surah, satu sama lain di antara mereka saling berpandangan (sambil berkata), \"Adakah seseorang (dari kaum muslimin) yang melihat kamu?\" Setelah itu mereka pun pergi. Allah memalingkan hati mereka disebabkan mereka adalah kaum yang tidak memahami"},{id:128,text:"\u0644\u064e\u0642\u064e\u062f\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u06e1 \u0631\u064e\u0633\u064f\u0648\u0644\u065e \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u06e1 \u0639\u064e\u0632\u0650\u064a\u0632\u064c \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0645\u064e\u0627 \u0639\u064e\u0646\u0650\u062a\u0651\u064f\u0645\u06e1 \u062d\u064e\u0631\u0650\u064a\u0635\u064c \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0631\u064e\u0621\u064f\u0648\u0641\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u065e",translation:"Sungguh, telah datang kepadamu seorang rasul dari kaummu sendiri, berat terasa olehnya penderitaan yang kamu alami, (dia) sangat menginginkan (keimanan dan keselamatan) bagimu, penyantun dan penyayang terhadap orang-orang yang beriman"},{id:129,text:"\u0641\u064e\u0625\u0650\u0646 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u06e1\u0627\u0652 \u0641\u064e\u0642\u064f\u0644\u06e1 \u062d\u064e\u0633\u06e1\u0628\u0650\u064a\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e\u06d6 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u06e1\u062a\u064f\u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0631\u064e\u0628\u0651\u064f \u0671\u0644\u06e1\u0639\u064e\u0631\u06e1\u0634\u0650 \u0671\u0644\u06e1\u0639\u064e\u0638\u0650\u064a\u0645\u0650",translation:"Maka jika mereka berpaling (dari keimanan), maka katakanlah (Muhammad), \"Cukuplah Allah bagiku; tidak ada tuhan selain Dia. Hanya kepada-Nya aku bertawakal, dan Dia adalah Tuhan yang memiliki Arasy (singgasana) yang agung"}]},{id:10,name:"\u064a\u0648\u0646\u0633",transliteration:"Yunus",translation:"Yunus",type:"meccan",total_verses:109,verses:[{id:1,text:"\u0627\u0644\u0653\u0631\u06da \u062a\u0650\u0644\u06e1\u0643\u064e \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u064f \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0671\u0644\u06e1\u062d\u064e\u0643\u0650\u064a\u0645\u0650",translation:"Alif L\u0101m R\u0101`. Inilah ayat-ayat Alquran yang penuh hikmah"},{id:2,text:"\u0623\u064e\u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0639\u064e\u062c\u064e\u0628\u064b\u0627 \u0623\u064e\u0646\u06e1 \u0623\u064e\u0648\u06e1\u062d\u064e\u064a\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u062c\u064f\u0644\u0656 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0623\u064e\u0646\u06e1 \u0623\u064e\u0646\u0630\u0650\u0631\u0650 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0648\u064e\u0628\u064e\u0634\u0651\u0650\u0631\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0642\u064e\u062f\u064e\u0645\u064e \u0635\u0650\u062f\u06e1\u0642\u064d \u0639\u0650\u0646\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1\u06d7 \u0642\u064e\u0627\u0644\u064e \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u064f\u0648\u0646\u064e \u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0644\u064e\u0633\u064e\u0670\u062d\u0650\u0631\u065e \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u064c",translation:"Pantaskah manusia menjadi heran bahwa Kami memberi wahyu kepada seorang laki-laki di antara mereka, \"Berilah peringatan kepada manusia dan gembirakanlah orang-orang beriman bahwa mereka mempunyai kedudukan yang tinggi di sisi Tuhan mereka.\" Orang-orang kafir berkata, \"Orang ini (Muhammad) benar-benar pesihir"},{id:3,text:"\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0641\u0650\u064a \u0633\u0650\u062a\u0651\u064e\u0629\u0650 \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u0656 \u062b\u064f\u0645\u0651\u064e \u0671\u0633\u06e1\u062a\u064e\u0648\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0639\u064e\u0631\u06e1\u0634\u0650\u06d6 \u064a\u064f\u062f\u064e\u0628\u0651\u0650\u0631\u064f \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0631\u064e\u06d6 \u0645\u064e\u0627 \u0645\u0650\u0646 \u0634\u064e\u0641\u0650\u064a\u0639\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0625\u0650\u0630\u06e1\u0646\u0650\u0647\u0650\u06e6\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u06e1 \u0641\u064e\u0671\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0647\u064f\u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Sesungguhnya Tuhan kamu Dialah Allah yang menciptakan langit dan bumi dalam enam masa, kemudian Dia bersemayam di atas Arasy (singgasana) untuk mengatur segala urusan. Tidak ada yang dapat memberi syafaat kecuali setelah ada izin-Nya. Itulah Allah, Tuhanmu, maka sembahlah Dia. Apakah kamu tidak mengambil pelajaran"},{id:4,text:"\u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0645\u064e\u0631\u06e1\u062c\u0650\u0639\u064f\u0643\u064f\u0645\u06e1 \u062c\u064e\u0645\u0650\u064a\u0639\u0657\u0627\u06d6 \u0648\u064e\u0639\u06e1\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u064e\u0642\u0651\u064b\u0627\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u064a\u064e\u0628\u06e1\u062f\u064e\u0624\u064f\u0627\u0652 \u0671\u0644\u06e1\u062e\u064e\u0644\u06e1\u0642\u064e \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0639\u0650\u064a\u062f\u064f\u0647\u064f\u06e5 \u0644\u0650\u064a\u064e\u062c\u06e1\u0632\u0650\u064a\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0628\u0650\u0671\u0644\u06e1\u0642\u0650\u0633\u06e1\u0637\u0650\u06da \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0634\u064e\u0631\u064e\u0627\u0628\u065e \u0645\u0651\u0650\u0646\u06e1 \u062d\u064e\u0645\u0650\u064a\u0645\u0656 \u0648\u064e\u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064f\u06e2 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0643\u06e1\u0641\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Hanya kepada-Nya kamu semua akan kembali. Itu merupakan janji Allah yang benar dan pasti. Sesungguhnya Dialah yang memulai penciptaan makhluk kemudian mengulanginya (menghidupkannya kembali setelah berbangkit), agar Dia memberi balasan kepada orang-orang yang beriman dan mengerjakan kebajikan dengan adil. Sedangkan untuk orang-orang kafir (disediakan) minuman air yang mendidih dan siksaan yang pedih karena kekafiran mereka"},{id:5,text:"\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0639\u064e\u0644\u064e \u0671\u0644\u0634\u0651\u064e\u0645\u06e1\u0633\u064e \u0636\u0650\u064a\u064e\u0627\u0653\u0621\u0657 \u0648\u064e\u0671\u0644\u06e1\u0642\u064e\u0645\u064e\u0631\u064e \u0646\u064f\u0648\u0631\u0657\u0627 \u0648\u064e\u0642\u064e\u062f\u0651\u064e\u0631\u064e\u0647\u064f\u06e5 \u0645\u064e\u0646\u064e\u0627\u0632\u0650\u0644\u064e \u0644\u0650\u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0627\u0652 \u0639\u064e\u062f\u064e\u062f\u064e \u0671\u0644\u0633\u0651\u0650\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u062d\u0650\u0633\u064e\u0627\u0628\u064e\u06da \u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650\u06da \u064a\u064f\u0641\u064e\u0635\u0651\u0650\u0644\u064f \u0671\u0644\u06e1\u0623\u0653\u064a\u064e\u0670\u062a\u0650 \u0644\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dialah yang menjadikan matahari bersinar dan bulan bercahaya, dan Dialah yang menetapkan tempat-tempat orbitnya, agar kamu mengetahui bilangan tahun, dan perhitungan (waktu). Allah tidak menciptakan demikian itu melainkan dengan benar. Dia menjelaskan tanda-tanda (kebesaran-Nya) kepada orang-orang yang mengetahui"},{id:6,text:"\u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0671\u062e\u06e1\u062a\u0650\u0644\u064e\u0670\u0641\u0650 \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u0650 \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u0648\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0644\u064e\u0623\u0653\u064a\u064e\u0670\u062a\u0656 \u0644\u0651\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",translation:"Sesungguhnya pada pergantian malam dan siang, dan pada apa yang diciptakan Allah di langit dan di bumi, pasti terdapat tanda-tanda (kebesaran-Nya) bagi orang-orang yang bertakwa"},{id:7,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u0631\u06e1\u062c\u064f\u0648\u0646\u064e \u0644\u0650\u0642\u064e\u0627\u0653\u0621\u064e\u0646\u064e\u0627 \u0648\u064e\u0631\u064e\u0636\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u0650 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0648\u064e\u0671\u0637\u06e1\u0645\u064e\u0623\u064e\u0646\u0651\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u064e\u0627 \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645\u06e1 \u0639\u064e\u0646\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u063a\u064e\u0670\u0641\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Sesungguhnya orang-orang yang tidak mengharapkan (tidak percaya akan) pertemuan dengan Kami, dan merasa puas dengan kehidupan dunia serta merasa tenteram dengan (kehidupan) itu, dan orang-orang yang melalaikan ayat-ayat Kami"},{id:8,text:"\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0645\u064e\u0623\u06e1\u0648\u064e\u0649\u0670\u0647\u064f\u0645\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u064f \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0643\u06e1\u0633\u0650\u0628\u064f\u0648\u0646\u064e",translation:"mereka itu tempatnya di neraka, karena apa yang telah mereka lakukan"},{id:9,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u064a\u064e\u0647\u06e1\u062f\u0650\u064a\u0647\u0650\u0645\u06e1 \u0631\u064e\u0628\u0651\u064f\u0647\u064f\u0645 \u0628\u0650\u0625\u0650\u064a\u0645\u064e\u0670\u0646\u0650\u0647\u0650\u0645\u06e1\u06d6 \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0645\u0650\u0646 \u062a\u064e\u062d\u06e1\u062a\u0650\u0647\u0650\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u064f \u0641\u0650\u064a \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0650 \u0671\u0644\u0646\u0651\u064e\u0639\u0650\u064a\u0645\u0650",translation:"Sesungguhnya orang-orang yang beriman dan mengerjakan kebajikan, niscaya diberi petunjuk oleh Tuhan karena keimanannya. Mereka di dalam surga yang penuh kenikmatan, mengalir di bawahnya sungai-sungai"},{id:10,text:"\u062f\u064e\u0639\u06e1\u0648\u064e\u0649\u0670\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u0633\u064f\u0628\u06e1\u062d\u064e\u0670\u0646\u064e\u0643\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0648\u064e\u062a\u064e\u062d\u0650\u064a\u0651\u064e\u062a\u064f\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u0633\u064e\u0644\u064e\u0670\u0645\u065e\u06da \u0648\u064e\u0621\u064e\u0627\u062e\u0650\u0631\u064f \u062f\u064e\u0639\u06e1\u0648\u064e\u0649\u0670\u0647\u064f\u0645\u06e1 \u0623\u064e\u0646\u0650 \u0671\u0644\u06e1\u062d\u064e\u0645\u06e1\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0631\u064e\u0628\u0651\u0650 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Doa mereka di dalamnya ialah, \"Sub\u1e25\u0101nakall\u0101humma\" (Mahasuci Engkau, ya Tuhan kami), dan salam penghormatan mereka ialah, \"Sal\u0101m\" (salam sejahtera). Dan penutup doa mereka ialah, \"Al-\u1e24amdu lill\u0101hi Rabbil '\u0101lam\u012bn\". (segala puji bagi Allah Tuhan seluruh alam)"},{id:11,text:"\u06de\u0648\u064e\u0644\u064e\u0648\u06e1 \u064a\u064f\u0639\u064e\u062c\u0651\u0650\u0644\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0671\u0644\u0634\u0651\u064e\u0631\u0651\u064e \u0671\u0633\u06e1\u062a\u0650\u0639\u06e1\u062c\u064e\u0627\u0644\u064e\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u062e\u064e\u064a\u06e1\u0631\u0650 \u0644\u064e\u0642\u064f\u0636\u0650\u064a\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0623\u064e\u062c\u064e\u0644\u064f\u0647\u064f\u0645\u06e1\u06d6 \u0641\u064e\u0646\u064e\u0630\u064e\u0631\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u0631\u06e1\u062c\u064f\u0648\u0646\u064e \u0644\u0650\u0642\u064e\u0627\u0653\u0621\u064e\u0646\u064e\u0627 \u0641\u0650\u064a \u0637\u064f\u063a\u06e1\u064a\u064e\u0670\u0646\u0650\u0647\u0650\u0645\u06e1 \u064a\u064e\u0639\u06e1\u0645\u064e\u0647\u064f\u0648\u0646\u064e",translation:"Dan kalau Allah menyegerakan keburukan bagi manusia seperti permintaan mereka untuk menyegerakan kebaikan, pasti diakhiri umur mereka. Namun Kami biarkan orang-orang yang tidak mengharapkan pertemuan dengan Kami, bingung di dalam kesesatan mereka"},{id:12,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0633\u0651\u064e \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064e \u0671\u0644\u0636\u0651\u064f\u0631\u0651\u064f \u062f\u064e\u0639\u064e\u0627\u0646\u064e\u0627 \u0644\u0650\u062c\u064e\u0646\u06e2\u0628\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0648\u06e1 \u0642\u064e\u0627\u0639\u0650\u062f\u064b\u0627 \u0623\u064e\u0648\u06e1 \u0642\u064e\u0627\u0653\u0626\u0650\u0645\u0657\u0627 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0643\u064e\u0634\u064e\u0641\u06e1\u0646\u064e\u0627 \u0639\u064e\u0646\u06e1\u0647\u064f \u0636\u064f\u0631\u0651\u064e\u0647\u064f\u06e5 \u0645\u064e\u0631\u0651\u064e \u0643\u064e\u0623\u064e\u0646 \u0644\u0651\u064e\u0645\u06e1 \u064a\u064e\u062f\u06e1\u0639\u064f\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u0636\u064f\u0631\u0651\u0656 \u0645\u0651\u064e\u0633\u0651\u064e\u0647\u064f\u06e5\u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0632\u064f\u064a\u0651\u0650\u0646\u064e \u0644\u0650\u0644\u06e1\u0645\u064f\u0633\u06e1\u0631\u0650\u0641\u0650\u064a\u0646\u064e \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan apabila manusia ditimpa bahaya dia berdoa kepada Kami dalam keadaan berbaring, duduk atau berdiri, tetapi setelah Kami hilangkan bahaya itu darinya, dia kembali (ke jalan yang sesat), seolah-olah dia tidak pernah berdoa kepada Kami untuk (menghilangkan) bahaya yang telah menimpanya. Demikianlah dijadikan terasa indah bagi orang-orang yang melampaui batas apa yang mereka kerjakan"},{id:13,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u0647\u06e1\u0644\u064e\u0643\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0642\u064f\u0631\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064f\u0645\u06e1 \u0644\u064e\u0645\u0651\u064e\u0627 \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627\u0652 \u0648\u064e\u062c\u064e\u0627\u0653\u0621\u064e\u062a\u06e1\u0647\u064f\u0645\u06e1 \u0631\u064f\u0633\u064f\u0644\u064f\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0644\u0650\u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0627\u0652\u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u062c\u06e1\u0632\u0650\u064a \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0645\u064f\u062c\u06e1\u0631\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dan sungguh, Kami telah membinasakan umat-umat sebelum kamu, ketika mereka berbuat zalim, padahal para rasul mereka telah datang membawa keterangan-keterangan (yang nyata), tetapi mereka sama sekali tidak mau beriman. Demikianlah Kami memberi balasan kepada orang-orang yang berbuat dosa"},{id:14,text:"\u062b\u064f\u0645\u0651\u064e \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0670\u0643\u064f\u0645\u06e1 \u062e\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0641\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u0647\u0650\u0645\u06e1 \u0644\u0650\u0646\u064e\u0646\u0638\u064f\u0631\u064e \u0643\u064e\u064a\u06e1\u0641\u064e \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Kemudian Kami jadikan kamu sebagai pengganti-pengganti (mereka) di bumi setelah mereka, untuk Kami lihat bagaimana kamu berbuat"},{id:15,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062a\u064f\u062a\u06e1\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0621\u064e\u0627\u064a\u064e\u0627\u062a\u064f\u0646\u064e\u0627 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0656 \u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u0631\u06e1\u062c\u064f\u0648\u0646\u064e \u0644\u0650\u0642\u064e\u0627\u0653\u0621\u064e\u0646\u064e\u0627 \u0671\u0626\u06e1\u062a\u0650 \u0628\u0650\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u064d \u063a\u064e\u064a\u06e1\u0631\u0650 \u0647\u064e\u0670\u0630\u064e\u0627\u0653 \u0623\u064e\u0648\u06e1 \u0628\u064e\u062f\u0651\u0650\u0644\u06e1\u0647\u064f\u06da \u0642\u064f\u0644\u06e1 \u0645\u064e\u0627 \u064a\u064e\u0643\u064f\u0648\u0646\u064f \u0644\u0650\u064a\u0653 \u0623\u064e\u0646\u06e1 \u0623\u064f\u0628\u064e\u062f\u0651\u0650\u0644\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646 \u062a\u0650\u0644\u06e1\u0642\u064e\u0627\u0653\u064a\u0655\u0650 \u0646\u064e\u0641\u06e1\u0633\u0650\u064a\u0653\u06d6 \u0625\u0650\u0646\u06e1 \u0623\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u064a\u064f\u0648\u062d\u064e\u0649\u0670\u0653 \u0625\u0650\u0644\u064e\u064a\u0651\u064e\u06d6 \u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0625\u0650\u0646\u06e1 \u0639\u064e\u0635\u064e\u064a\u06e1\u062a\u064f \u0631\u064e\u0628\u0651\u0650\u064a \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u064a\u064e\u0648\u06e1\u0645\u064d \u0639\u064e\u0638\u0650\u064a\u0645\u0656",translation:"Dan apabila dibacakan kepada mereka ayat-ayat Kami dengan jelas, orang-orang yang tidak mengharapkan pertemuan dengan kami berkata, \"Datangkanlah kitab selain Alquran ini atau gantilah.\" Katakanlah (Muhammad), \"Tidaklah pantas bagiku menggantinya atas kemauanku sendiri. Aku hanya mengikuti apa yang diwahyukan kepadaku. Aku benar-benar takut akan azab hari yang besar (Kiamat) jika mendurhakai Tuhanku"},{id:16,text:"\u0642\u064f\u0644 \u0644\u0651\u064e\u0648\u06e1 \u0634\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0627 \u062a\u064e\u0644\u064e\u0648\u06e1\u062a\u064f\u0647\u064f\u06e5 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064e\u062f\u06e1\u0631\u064e\u0649\u0670\u0643\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6\u06d6 \u0641\u064e\u0642\u064e\u062f\u06e1 \u0644\u064e\u0628\u0650\u062b\u06e1\u062a\u064f \u0641\u0650\u064a\u0643\u064f\u0645\u06e1 \u0639\u064f\u0645\u064f\u0631\u0657\u0627 \u0645\u0651\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u06e6\u0653\u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Katakanlah (Muhammad), \"Jika Allah menghendaki, niscaya aku tidak membacakannya kepadamu dan Allah tidak (pula) memberitahukannya kepadamu.\"Aku telah tinggal bersamamu beberapa lama sebelumnya (sebelum turun Alquran). Apakah kamu tidak mengerti"},{id:17,text:"\u0641\u064e\u0645\u064e\u0646\u06e1 \u0623\u064e\u0638\u06e1\u0644\u064e\u0645\u064f \u0645\u0650\u0645\u0651\u064e\u0646\u0650 \u0671\u0641\u06e1\u062a\u064e\u0631\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u0630\u0650\u0628\u064b\u0627 \u0623\u064e\u0648\u06e1 \u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0647\u0650\u06e6\u0653\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0627 \u064a\u064f\u0641\u06e1\u0644\u0650\u062d\u064f \u0671\u0644\u06e1\u0645\u064f\u062c\u06e1\u0631\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Maka siapakah yang lebih zalim daripada orang yang mengada-adakan kebohongan terhadap Allah atau mendustakan ayat-ayat-Nya? Sesungguhnya orang-orang yang berbuat dosa itu tidak akan beruntung"},{id:18,text:"\u0648\u064e\u064a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0636\u064f\u0631\u0651\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0646\u0641\u064e\u0639\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650 \u0634\u064f\u0641\u064e\u0639\u064e\u0640\u0670\u0653\u0624\u064f\u0646\u064e\u0627 \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0642\u064f\u0644\u06e1 \u0623\u064e\u062a\u064f\u0646\u064e\u0628\u0651\u0650\u0640\u0654\u064f\u0648\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u0645\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0644\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06da \u0633\u064f\u0628\u06e1\u062d\u064e\u0670\u0646\u064e\u0647\u064f\u06e5 \u0648\u064e\u062a\u064e\u0639\u064e\u0670\u0644\u064e\u0649\u0670 \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064f\u0634\u06e1\u0631\u0650\u0643\u064f\u0648\u0646\u064e",translation:"Dan mereka menyembah selain Allah, sesuatu yang tidak dapat mendatangkan bencana kepada mereka dan tidak (pula) memberi manfaat, dan mereka berkata, \"Mereka itu adalah pemberi syafaat kami di hadapan Allah.\" Katakanlah, \"Apakah kamu akan memberitahu kepada Allah sesuatu yang tidak diketahui-Nya apa yang di langit dan tidak (pula) yang di bumi?\"384) Mahasuci Allah dan Mahatinggi Dia dari apa yang mereka persekutukan itu"},{id:19,text:"\u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064f\u0645\u0651\u064e\u0629\u0657 \u0648\u064e\u0670\u062d\u0650\u062f\u064e\u0629\u0657 \u0641\u064e\u0671\u062e\u06e1\u062a\u064e\u0644\u064e\u0641\u064f\u0648\u0627\u0652\u06da \u0648\u064e\u0644\u064e\u0648\u06e1\u0644\u064e\u0627 \u0643\u064e\u0644\u0650\u0645\u064e\u0629\u065e \u0633\u064e\u0628\u064e\u0642\u064e\u062a\u06e1 \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064e \u0644\u064e\u0642\u064f\u0636\u0650\u064a\u064e \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0645\u064e\u0627 \u0641\u0650\u064a\u0647\u0650 \u064a\u064e\u062e\u06e1\u062a\u064e\u0644\u0650\u0641\u064f\u0648\u0646\u064e",translation:"(Dan manusia dahulunya satu umat, kemudian mereka berselisih. Kalau tidak karena suatu ketetapan yang telah ada dari Tuhanmu,385) pastilah telah diberi keputusan (di dunia) di antara mereka, tentang apa yang mereka perselisihkan itu"},{id:20,text:"\u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0644\u064e\u0648\u06e1\u0644\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0621\u064e\u0627\u064a\u064e\u0629\u065e \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0647\u0650\u06e6\u06d6 \u0641\u064e\u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u0628\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0671\u0646\u062a\u064e\u0638\u0650\u0631\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u0650\u064a \u0645\u064e\u0639\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0646\u062a\u064e\u0638\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan mereka berkata, \"Mengapa tidak diturunkan kepadanya (Muhammad) suatu bukti (mukjizat) dari Tuhannya?\" Katakanlah, \"Sungguh, segala yang gaib itu hanya milik Allah; sebab itu tunggu (sajalah) olehmu. Ketahuilah aku juga menunggu bersama kamu"},{id:21,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627\u0653 \u0623\u064e\u0630\u064e\u0642\u06e1\u0646\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u0657 \u0645\u0651\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0636\u064e\u0631\u0651\u064e\u0627\u0653\u0621\u064e \u0645\u064e\u0633\u0651\u064e\u062a\u06e1\u0647\u064f\u0645\u06e1 \u0625\u0650\u0630\u064e\u0627 \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u0643\u06e1\u0631\u065e \u0641\u0650\u064a\u0653 \u0621\u064e\u0627\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627\u06da \u0642\u064f\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0633\u06e1\u0631\u064e\u0639\u064f \u0645\u064e\u0643\u06e1\u0631\u064b\u0627\u06da \u0625\u0650\u0646\u0651\u064e \u0631\u064f\u0633\u064f\u0644\u064e\u0646\u064e\u0627 \u064a\u064e\u0643\u06e1\u062a\u064f\u0628\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u062a\u064e\u0645\u06e1\u0643\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Dan apabila Kami memberikan suatu rahmat kepada manusia, setelah mereka ditimpa bencana, mereka segera melakukan segala tipu daya (menentang) ayat-ayat Kami. Katakanlah, \"Allah lebih cepat pembalasannya (atas tipu daya itu).\" Sesungguhnya malaikat-malaikat Kami mencatat tipu dayamu"},{id:22,text:"\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u0633\u064e\u064a\u0651\u0650\u0631\u064f\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0628\u064e\u0631\u0651\u0650 \u0648\u064e\u0671\u0644\u06e1\u0628\u064e\u062d\u06e1\u0631\u0650\u06d6 \u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0641\u064f\u0644\u06e1\u0643\u0650 \u0648\u064e\u062c\u064e\u0631\u064e\u064a\u06e1\u0646\u064e \u0628\u0650\u0647\u0650\u0645 \u0628\u0650\u0631\u0650\u064a\u062d\u0656 \u0637\u064e\u064a\u0651\u0650\u0628\u064e\u0629\u0656 \u0648\u064e\u0641\u064e\u0631\u0650\u062d\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u062a\u06e1\u0647\u064e\u0627 \u0631\u0650\u064a\u062d\u064c \u0639\u064e\u0627\u0635\u0650\u0641\u065e \u0648\u064e\u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062c\u064f \u0645\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u0645\u064e\u0643\u064e\u0627\u0646\u0656 \u0648\u064e\u0638\u064e\u0646\u0651\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0623\u064f\u062d\u0650\u064a\u0637\u064e \u0628\u0650\u0647\u0650\u0645\u06e1 \u062f\u064e\u0639\u064e\u0648\u064f\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064f\u062e\u06e1\u0644\u0650\u0635\u0650\u064a\u0646\u064e \u0644\u064e\u0647\u064f \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u064e \u0644\u064e\u0626\u0650\u0646\u06e1 \u0623\u064e\u0646\u062c\u064e\u064a\u06e1\u062a\u064e\u0646\u064e\u0627 \u0645\u0650\u0646\u06e1 \u0647\u064e\u0670\u0630\u0650\u0647\u0650\u06e6 \u0644\u064e\u0646\u064e\u0643\u064f\u0648\u0646\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0634\u0651\u064e\u0640\u0670\u0643\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dialah Tuhan yang menjadikan kamu dapat berjalan di daratan, (dan berlayar) di lautan. Sehingga ketika kamu berada di dalam kapal, dan meluncurlah (kapal) itu membawa mereka (orang-orang yang ada di dalamnya) dengan tiupan angin yang baik, dan mereka bergembira karenanya; tiba-tiba datanglah badai dan gelombang menimpanya dari segenap penjuru, dan mereka mengira telah terkepung (bahaya), maka mereka berdoa dengan tulus ikhlas kepada Allah semata. (Seraya berkata), \"Sekiranya Engkau menyelamatkan kami dari (bahaya) ini, pasti kami termasuk orang-orang yang bersyukur"},{id:23,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u0646\u062c\u064e\u0649\u0670\u0647\u064f\u0645\u06e1 \u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0645\u06e1 \u064a\u064e\u0628\u06e1\u063a\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0628\u0650\u063a\u064e\u064a\u06e1\u0631\u0650 \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650\u06d7 \u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0628\u064e\u063a\u06e1\u064a\u064f\u0643\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u06d6 \u0645\u0651\u064e\u062a\u064e\u0670\u0639\u064e \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u0650 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627\u06d6 \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0645\u064e\u0631\u06e1\u062c\u0650\u0639\u064f\u0643\u064f\u0645\u06e1 \u0641\u064e\u0646\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0643\u064f\u0645 \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Tetapi ketika Allah menyelamatkan mereka, malah mereka berbuat kezaliman di bumi tanpa (alasan) yang benar. Wahai manusia! Sesungguhnya kezalimanmu bahayanya akan menimpa dirimu sendiri; itu hanya kenikmatan hidup duniawi, selanjutnya kepada Kamilah kembalimu, kelak akan Kami kabarkan kepadamu apa yang telah kamu kerjakan"},{id:24,text:"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0645\u064e\u062b\u064e\u0644\u064f \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u0650 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0643\u064e\u0645\u064e\u0627\u0653\u0621\u064d \u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0641\u064e\u0671\u062e\u06e1\u062a\u064e\u0644\u064e\u0637\u064e \u0628\u0650\u0647\u0650\u06e6 \u0646\u064e\u0628\u064e\u0627\u062a\u064f \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0645\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0639\u064e\u0670\u0645\u064f \u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u064e\u0627\u0653 \u0623\u064e\u062e\u064e\u0630\u064e\u062a\u0650 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064f \u0632\u064f\u062e\u06e1\u0631\u064f\u0641\u064e\u0647\u064e\u0627 \u0648\u064e\u0671\u0632\u0651\u064e\u064a\u0651\u064e\u0646\u064e\u062a\u06e1 \u0648\u064e\u0638\u064e\u0646\u0651\u064e \u0623\u064e\u0647\u06e1\u0644\u064f\u0647\u064e\u0627\u0653 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0642\u064e\u0670\u062f\u0650\u0631\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627\u0653 \u0623\u064e\u062a\u064e\u0649\u0670\u0647\u064e\u0627\u0653 \u0623\u064e\u0645\u06e1\u0631\u064f\u0646\u064e\u0627 \u0644\u064e\u064a\u06e1\u0644\u064b\u0627 \u0623\u064e\u0648\u06e1 \u0646\u064e\u0647\u064e\u0627\u0631\u0657\u0627 \u0641\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064e\u0627 \u062d\u064e\u0635\u0650\u064a\u062f\u0657\u0627 \u0643\u064e\u0623\u064e\u0646 \u0644\u0651\u064e\u0645\u06e1 \u062a\u064e\u063a\u06e1\u0646\u064e \u0628\u0650\u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0633\u0650\u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064f\u0641\u064e\u0635\u0651\u0650\u0644\u064f \u0671\u0644\u06e1\u0623\u0653\u064a\u064e\u0670\u062a\u0650 \u0644\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064e\u062a\u064e\u0641\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Sesungguhnya perumpamaan kehidupan duniawi itu hanya seperti air (hujan) yang Kami turunkan dari langit, lalu tumbuhlah tanaman-tanaman bumi dengan subur (karena air itu), di antaranya ada yang dimakan manusia dan hewan ternak. Hingga apabila bumi itu telah sempurna keindahannya, dan berhias,386) dan pemiliknya mengira bahwa mereka pasti menguasainya (memetik hasilnya), datanglah kepadanya azab Kami pada waktu malam atau siang, lalu Kami jadikan (tanaman)nya seperti tanaman yang sudah disabit, seakan-akan belum pernah tumbuh kemarin. Demikianlah Kami menjelaskan tanda-tanda (kekuasaan Kami) kepada kaum yang berpikir"},{id:25,text:"\u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u062f\u06e1\u0639\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u062f\u064e\u0627\u0631\u0650 \u0671\u0644\u0633\u0651\u064e\u0644\u064e\u0670\u0645\u0650 \u0648\u064e\u064a\u064e\u0647\u06e1\u062f\u0650\u064a \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0670\u0637\u0656 \u0645\u0651\u064f\u0633\u06e1\u062a\u064e\u0642\u0650\u064a\u0645\u0656",translation:"Dan Allah menyeru (manusia) ke D\u0101russal\u0101m (surga), dan memberikan petunjuk kepada orang yang Dia kehendaki ke jalan yang lurus (Islam)"},{id:26,text:"\u06de\u0644\u0651\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u062d\u064f\u0633\u06e1\u0646\u064e\u0649\u0670 \u0648\u064e\u0632\u0650\u064a\u064e\u0627\u062f\u064e\u0629\u065e\u06d6 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0631\u06e1\u0647\u064e\u0642\u064f \u0648\u064f\u062c\u064f\u0648\u0647\u064e\u0647\u064f\u0645\u06e1 \u0642\u064e\u062a\u064e\u0631\u065e \u0648\u064e\u0644\u064e\u0627 \u0630\u0650\u0644\u0651\u064e\u0629\u064c\u06da \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u0650\u06d6 \u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u0670\u0644\u0650\u062f\u064f\u0648\u0646\u064e",translation:"Bagi orang-orang yang berbuat baik, ada pahala yang terbaik (surga) dan tambahannya (kenikmatan melihat Allah). Dan wajah mereka tidak ditutupi debu hitam dan tidak (pula) dalam kehinaan. Mereka itulah penghuni surga, mereka kekal di dalamnya"},{id:27,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0633\u064e\u0628\u064f\u0648\u0627\u0652 \u0671\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0640\u0654\u064e\u0627\u062a\u0650 \u062c\u064e\u0632\u064e\u0627\u0653\u0621\u064f \u0633\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u0650\u06ed \u0628\u0650\u0645\u0650\u062b\u06e1\u0644\u0650\u0647\u064e\u0627 \u0648\u064e\u062a\u064e\u0631\u06e1\u0647\u064e\u0642\u064f\u0647\u064f\u0645\u06e1 \u0630\u0650\u0644\u0651\u064e\u0629\u065e\u06d6 \u0645\u0651\u064e\u0627 \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646\u06e1 \u0639\u064e\u0627\u0635\u0650\u0645\u0656\u06d6 \u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u063a\u06e1\u0634\u0650\u064a\u064e\u062a\u06e1 \u0648\u064f\u062c\u064f\u0648\u0647\u064f\u0647\u064f\u0645\u06e1 \u0642\u0650\u0637\u064e\u0639\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u0650 \u0645\u064f\u0638\u06e1\u0644\u0650\u0645\u064b\u0627\u06da \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650\u06d6 \u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u0670\u0644\u0650\u062f\u064f\u0648\u0646\u064e",translation:"Adapun orang-orang yang berbuat kejahatan (akan mendapat) balasan kejahatan yang setimpal dan mereka diselubungi kehinaan. Tidak ada bagi mereka seorang pelindung pun dari (azab) Allah, seakan-akan wajah mereka ditutupi dengan kepingan-kepingan malam yang gelap gulita. Mereka itulah penghuni neraka, mereka kekal di dalamnya"},{id:28,text:"\u0648\u064e\u064a\u064e\u0648\u06e1\u0645\u064e \u0646\u064e\u062d\u06e1\u0634\u064f\u0631\u064f\u0647\u064f\u0645\u06e1 \u062c\u064e\u0645\u0650\u064a\u0639\u0657\u0627 \u062b\u064f\u0645\u0651\u064e \u0646\u064e\u0642\u064f\u0648\u0644\u064f \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u0634\u06e1\u0631\u064e\u0643\u064f\u0648\u0627\u0652 \u0645\u064e\u0643\u064e\u0627\u0646\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0648\u064e\u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0653\u0624\u064f\u0643\u064f\u0645\u06e1\u06da \u0641\u064e\u0632\u064e\u064a\u0651\u064e\u0644\u06e1\u0646\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0653\u0624\u064f\u0647\u064f\u0645 \u0645\u0651\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0625\u0650\u064a\u0651\u064e\u0627\u0646\u064e\u0627 \u062a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0646\u064e",translation:"Dan (ingatlah) pada hari (ketika) itu Kami mengumpulkan mereka semuanya, kemudian Kami berkata kepada orang yang mempersekutukan (Allah), \"Tetaplah di tempatmu, kamu dan para sekutumu.\" Lalu Kami pisahkan mereka, dan berkatalah sekutu-sekutu mereka, \"kamu sekali-kali tidak pernah menyembah kami"},{id:29,text:"\u0641\u064e\u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0634\u064e\u0647\u0650\u064a\u062f\u064e\u06e2\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e\u0646\u064e\u0627 \u0648\u064e\u0628\u064e\u064a\u06e1\u0646\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0646 \u0643\u064f\u0646\u0651\u064e\u0627 \u0639\u064e\u0646\u06e1 \u0639\u0650\u0628\u064e\u0627\u062f\u064e\u062a\u0650\u0643\u064f\u0645\u06e1 \u0644\u064e\u063a\u064e\u0670\u0641\u0650\u0644\u0650\u064a\u0646\u064e",translation:"Maka cukuplah Allah menjadi saksi antara kami dengan kamu, sebab kami tidak tahu-menahu tentang penyembahan kamu (kepada kami)"},{id:30,text:"\u0647\u064f\u0646\u064e\u0627\u0644\u0650\u0643\u064e \u062a\u064e\u0628\u06e1\u0644\u064f\u0648\u0627\u0652 \u0643\u064f\u0644\u0651\u064f \u0646\u064e\u0641\u06e1\u0633\u0656 \u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u0633\u06e1\u0644\u064e\u0641\u064e\u062a\u06e1\u06da \u0648\u064e\u0631\u064f\u062f\u0651\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0648\u06e1\u0644\u064e\u0649\u0670\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650\u06d6 \u0648\u064e\u0636\u064e\u0644\u0651\u064e \u0639\u064e\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0641\u06e1\u062a\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Di tempat itu (padang Mahsyar), setiap jiwa merasakan pembalasan dari apa yang telah dikerjakannya (dahulu) dan mereka dikembalikan kepada Allah, Pelindung mereka yang sebenarnya, dan lenyaplah dari mereka apa (pelindung palsu) yang mereka ada-adakan"},{id:31,text:"\u0642\u064f\u0644\u06e1 \u0645\u064e\u0646 \u064a\u064e\u0631\u06e1\u0632\u064f\u0642\u064f\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0623\u064e\u0645\u0651\u064e\u0646 \u064a\u064e\u0645\u06e1\u0644\u0650\u0643\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u06e1\u0639\u064e \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0628\u06e1\u0635\u064e\u0670\u0631\u064e \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u062e\u06e1\u0631\u0650\u062c\u064f \u0671\u0644\u06e1\u062d\u064e\u064a\u0651\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064e\u064a\u0651\u0650\u062a\u0650 \u0648\u064e\u064a\u064f\u062e\u06e1\u0631\u0650\u062c\u064f \u0671\u0644\u06e1\u0645\u064e\u064a\u0651\u0650\u062a\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u062d\u064e\u064a\u0651\u0650 \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u062f\u064e\u0628\u0651\u0650\u0631\u064f \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0631\u064e\u06da \u0641\u064e\u0633\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06da \u0641\u064e\u0642\u064f\u0644\u06e1 \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",translation:"Katakanlah (Muhammad), \"Siapakah yang memberi rezeki kepadamu dari langit dan bumi, atau siapakah yang kuasa (menciptakan) pendengaran dan penglihatan, dan siapakah yang mengeluarkan yang hidup dari yang mati, dan mengeluarkan yang mati dari yang hidup, dan siapakah yang mengatur segala urusan?\" Maka mereka akan menjawab, \"Allah.\" Maka katakanlah, \"Mengapa kamu tidak bertakwa (kepada-Nya)"},{id:32,text:"\u0641\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f\u06d6 \u0641\u064e\u0645\u064e\u0627\u0630\u064e\u0627 \u0628\u064e\u0639\u06e1\u062f\u064e \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0636\u0651\u064e\u0644\u064e\u0670\u0644\u064f\u06d6 \u0641\u064e\u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u062a\u064f\u0635\u06e1\u0631\u064e\u0641\u064f\u0648\u0646\u064e",translation:"Maka itulah Allah, Tuhan kamu yang sebenarnya; maka tidak ada setelah kebenaran itu melainkan kesesatan. Maka mengapa kamu berpaling (dari kebenaran)"},{id:33,text:"\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062d\u064e\u0642\u0651\u064e\u062a\u06e1 \u0643\u064e\u0644\u0650\u0645\u064e\u062a\u064f \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0641\u064e\u0633\u064e\u0642\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Demikianlah telah tetap (hukuman) Tuhanmu terhadap orang-orang yang fasik, karena sesungguhnya mereka tidak beriman"},{id:34,text:"\u0642\u064f\u0644\u06e1 \u0647\u064e\u0644\u06e1 \u0645\u0650\u0646 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0653\u0626\u0650\u0643\u064f\u0645 \u0645\u0651\u064e\u0646 \u064a\u064e\u0628\u06e1\u062f\u064e\u0624\u064f\u0627\u0652 \u0671\u0644\u06e1\u062e\u064e\u0644\u06e1\u0642\u064e \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0639\u0650\u064a\u062f\u064f\u0647\u064f\u06e5\u06da \u0642\u064f\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0628\u06e1\u062f\u064e\u0624\u064f\u0627\u0652 \u0671\u0644\u06e1\u062e\u064e\u0644\u06e1\u0642\u064e \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0639\u0650\u064a\u062f\u064f\u0647\u064f\u06e5\u06d6 \u0641\u064e\u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u062a\u064f\u0624\u06e1\u0641\u064e\u0643\u064f\u0648\u0646\u064e",translation:"Katakanlah, \"Adakah di antara sekutumu yang dapat memulai penciptaan (makhluk), kemudian mengulanginya (menghidupkannya) kembali?\" Katakanlah, \"Allah memulai (penciptaan) makhluk, kemudian mengulanginya. Maka bagaimana kamu dipalingkan (menyembah selain Allah)"},{id:35,text:"\u0642\u064f\u0644\u06e1 \u0647\u064e\u0644\u06e1 \u0645\u0650\u0646 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0653\u0626\u0650\u0643\u064f\u0645 \u0645\u0651\u064e\u0646 \u064a\u064e\u0647\u06e1\u062f\u0650\u064a\u0653 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650\u06da \u0642\u064f\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0647\u06e1\u062f\u0650\u064a \u0644\u0650\u0644\u06e1\u062d\u064e\u0642\u0651\u0650\u06d7 \u0623\u064e\u0641\u064e\u0645\u064e\u0646 \u064a\u064e\u0647\u06e1\u062f\u0650\u064a\u0653 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0623\u064e\u062d\u064e\u0642\u0651\u064f \u0623\u064e\u0646 \u064a\u064f\u062a\u0651\u064e\u0628\u064e\u0639\u064e \u0623\u064e\u0645\u0651\u064e\u0646 \u0644\u0651\u064e\u0627 \u064a\u064e\u0647\u0650\u062f\u0651\u0650\u064a\u0653 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u064a\u064f\u0647\u06e1\u062f\u064e\u0649\u0670\u06d6 \u0641\u064e\u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0643\u064e\u064a\u06e1\u0641\u064e \u062a\u064e\u062d\u06e1\u0643\u064f\u0645\u064f\u0648\u0646\u064e",translation:"Katakanlah, \"Apakah di antara sekutumu ada yang membimbing kepada kebenaran?\" Katakanlah, \"Allahlah yang membimbing kepada kebenaran.\" Maka manakah yang lebih berhak diikuti, Tuhan yang membimbing kepada kebenaran, ataukah orang yang tidak mampu membimbing bahkan perlu dibimbing? Maka mengapa kamu (berbuat demikian)? Bagaimanakah kamu mengambil keputusan"},{id:36,text:"\u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064f\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u0638\u064e\u0646\u0651\u064b\u0627\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0638\u0651\u064e\u0646\u0651\u064e \u0644\u064e\u0627 \u064a\u064f\u063a\u06e1\u0646\u0650\u064a \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0634\u064e\u064a\u06e1\u0640\u0654\u064b\u0627\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u064f\u06e2 \u0628\u0650\u0645\u064e\u0627 \u064a\u064e\u0641\u06e1\u0639\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan kebanyakan mereka hanya mengikuti dugaan. Sesungguhnya dugaan itu tidak sedikit pun berguna untuk mencapai kebenaran. Sungguh, Allah Maha Mengetahui apa yang mereka kerjakan"},{id:37,text:"\u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u064f \u0623\u064e\u0646 \u064a\u064f\u0641\u06e1\u062a\u064e\u0631\u064e\u0649\u0670 \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u062a\u064e\u0635\u06e1\u062f\u0650\u064a\u0642\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0628\u064e\u064a\u06e1\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u06e1\u0647\u0650 \u0648\u064e\u062a\u064e\u0641\u06e1\u0635\u0650\u064a\u0644\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0644\u064e\u0627 \u0631\u064e\u064a\u06e1\u0628\u064e \u0641\u0650\u064a\u0647\u0650 \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Dan tidak mungkin Alquran ini dibuat-buat oleh selain Allah; tetapi (Alquran) membenarkan (kitab-kitab) yang sebelumnya dan menjelaskan hukum-hukum yang telah ditetapkannya,388) tidak ada keraguan di dalamnya, (diturunkan) dari Tuhan seluruh alam"},{id:38,text:"\u0623\u064e\u0645\u06e1 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0671\u0641\u06e1\u062a\u064e\u0631\u064e\u0649\u0670\u0647\u064f\u06d6 \u0642\u064f\u0644\u06e1 \u0641\u064e\u0623\u06e1\u062a\u064f\u0648\u0627\u0652 \u0628\u0650\u0633\u064f\u0648\u0631\u064e\u0629\u0656 \u0645\u0651\u0650\u062b\u06e1\u0644\u0650\u0647\u0650\u06e6 \u0648\u064e\u0671\u062f\u06e1\u0639\u064f\u0648\u0627\u0652 \u0645\u064e\u0646\u0650 \u0671\u0633\u06e1\u062a\u064e\u0637\u064e\u0639\u06e1\u062a\u064f\u0645 \u0645\u0651\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0635\u064e\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Apakah pantas mereka mengatakan dia (Muhammad) yang telah membuat-buatnya? Katakanlah, \"Buatlah satu surah yang semisal dengan surah (Alquran), dan ajaklah siapa saja diantara kamu orang yang mampu (membuatnya) selain Allah, jika kamu orang-orang yang benar"},{id:39,text:"\u0628\u064e\u0644\u06e1 \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0645\u064e\u0627 \u0644\u064e\u0645\u06e1 \u064a\u064f\u062d\u0650\u064a\u0637\u064f\u0648\u0627\u0652 \u0628\u0650\u0639\u0650\u0644\u06e1\u0645\u0650\u0647\u0650\u06e6 \u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u064a\u064e\u0623\u06e1\u062a\u0650\u0647\u0650\u0645\u06e1 \u062a\u064e\u0623\u06e1\u0648\u0650\u064a\u0644\u064f\u0647\u064f\u06e5\u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u0645\u06e1\u06d6 \u0641\u064e\u0671\u0646\u0638\u064f\u0631\u06e1 \u0643\u064e\u064a\u06e1\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0670\u0642\u0650\u0628\u064e\u0629\u064f \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Bahkan (yang sebenarnya), mereka mendustakan apa yang mereka belum mengetahuinya dengan sempurna dan belum mereka peroleh penjelasannya. Demikianlah halnya umat-umat yang ada sebelum mereka telah mendustakan (Rasul). Maka perhatikanlah bagaimana akibat orang yang zalim"},{id:40,text:"\u0648\u064e\u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0646 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f \u0628\u0650\u0647\u0650\u06e6 \u0648\u064e\u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0646 \u0644\u0651\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f \u0628\u0650\u0647\u0650\u06e6\u06da \u0648\u064e\u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0628\u0650\u0671\u0644\u06e1\u0645\u064f\u0641\u06e1\u0633\u0650\u062f\u0650\u064a\u0646\u064e",translation:"Dan di antara mereka ada orang-orang yang beriman kepadanya (Alquran), dan di antaranya ada (pula) orang-orang yang tidak beriman kepadanya. Sedangkan Tuhanmu lebih mengetahui tentang orang-orang yang berbuat kerusakan"},{id:41,text:"\u0648\u064e\u0625\u0650\u0646 \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0643\u064e \u0641\u064e\u0642\u064f\u0644 \u0644\u0651\u0650\u064a \u0639\u064e\u0645\u064e\u0644\u0650\u064a \u0648\u064e\u0644\u064e\u0643\u064f\u0645\u06e1 \u0639\u064e\u0645\u064e\u0644\u064f\u0643\u064f\u0645\u06e1\u06d6 \u0623\u064e\u0646\u062a\u064f\u0645 \u0628\u064e\u0631\u0650\u064a\u0653\u0640\u0654\u064f\u0648\u0646\u064e \u0645\u0650\u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u0639\u06e1\u0645\u064e\u0644\u064f \u0648\u064e\u0623\u064e\u0646\u064e\u0627\u06e0 \u0628\u064e\u0631\u0650\u064a\u0653\u0621\u065e \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan jika mereka (tetap) mendustakanmu (Muhammad), maka katakanlah, \"Bagiku pekerjaanku dan bagimu pekerjaanmu. Kamu tidak bertanggung jawab terhadap apa yang aku kerjakan dan aku pun tidak bertanggung jawab terhadap apa yang kamu kerjakan"},{id:42,text:"\u0648\u064e\u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0646 \u064a\u064e\u0633\u06e1\u062a\u064e\u0645\u0650\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e\u06da \u0623\u064e\u0641\u064e\u0623\u064e\u0646\u062a\u064e \u062a\u064f\u0633\u06e1\u0645\u0650\u0639\u064f \u0671\u0644\u0635\u0651\u064f\u0645\u0651\u064e \u0648\u064e\u0644\u064e\u0648\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Dan di antara mereka ada yang mendengarkan engkau (Muhammad).389) Tetapi apakah engkau dapat menjadikan orang yang tuli itu mendengar, walaupun mereka tidak mengerti"},{id:43,text:"\u0648\u064e\u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0646 \u064a\u064e\u0646\u0638\u064f\u0631\u064f \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e\u06da \u0623\u064e\u0641\u064e\u0623\u064e\u0646\u062a\u064e \u062a\u064e\u0647\u06e1\u062f\u0650\u064a \u0671\u0644\u06e1\u0639\u064f\u0645\u06e1\u064a\u064e \u0648\u064e\u0644\u064e\u0648\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u064a\u064f\u0628\u06e1\u0635\u0650\u0631\u064f\u0648\u0646\u064e",translation:"(Dan di antara mereka ada yang melihat kepada engkau.390) Tetapi apakah engkau dapat memberi petunjuk kepada orang yang buta, walaupun mereka tidak memperhatikan"},{id:44,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064e\u0638\u06e1\u0644\u0650\u0645\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0638\u06e1\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Sesungguhnya Allah tidak menzalimi manusia sedikit pun, tetapi manusia itulah yang menzalimi dirinya sendiri"},{id:45,text:"\u0648\u064e\u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064e\u062d\u06e1\u0634\u064f\u0631\u064f\u0647\u064f\u0645\u06e1 \u0643\u064e\u0623\u064e\u0646 \u0644\u0651\u064e\u0645\u06e1 \u064a\u064e\u0644\u06e1\u0628\u064e\u062b\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0633\u064e\u0627\u0639\u064e\u0629\u0657 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u064a\u064e\u062a\u064e\u0639\u064e\u0627\u0631\u064e\u0641\u064f\u0648\u0646\u064e \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1\u06da \u0642\u064e\u062f\u06e1 \u062e\u064e\u0633\u0650\u0631\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0644\u0650\u0642\u064e\u0627\u0653\u0621\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0645\u064f\u0647\u06e1\u062a\u064e\u062f\u0650\u064a\u0646\u064e",translation:"Dan (ingatlah) pada hari (ketika) Allah mengumpulkan mereka, (mereka merasa) seakan-akan tidak pernah berdiam (di dunia) kecuali sesaat saja pada siang hari, (pada waktu) mereka saling berkenalan. Sungguh, rugi orang yang mendustakan pertemuan mereka dengan Allah, dan mereka tidak mendapat petunjuk"},{id:46,text:"\u0648\u064e\u0625\u0650\u0645\u0651\u064e\u0627 \u0646\u064f\u0631\u0650\u064a\u064e\u0646\u0651\u064e\u0643\u064e \u0628\u064e\u0639\u06e1\u0636\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0646\u064e\u0639\u0650\u062f\u064f\u0647\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1 \u0646\u064e\u062a\u064e\u0648\u064e\u0641\u0651\u064e\u064a\u064e\u0646\u0651\u064e\u0643\u064e \u0641\u064e\u0625\u0650\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0645\u064e\u0631\u06e1\u062c\u0650\u0639\u064f\u0647\u064f\u0645\u06e1 \u062b\u064f\u0645\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0634\u064e\u0647\u0650\u064a\u062f\u064c \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u064a\u064e\u0641\u06e1\u0639\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan jika Kami perlihatkan kepadamu (Muhammad) sebagian dari (siksaan) yang Kami janjikan kepada mereka, (tentulah engkau akan melihatnya) atau (jika) Kami wafatkan engkau (sebelum itu), maka kepada Kami (jualah) mereka kembali, dan Allah menjadi saksi atas apa yang mereka kerjakan"},{id:47,text:"\u0648\u064e\u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0623\u064f\u0645\u0651\u064e\u0629\u0656 \u0631\u0651\u064e\u0633\u064f\u0648\u0644\u065e\u06d6 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0647\u064f\u0645\u06e1 \u0642\u064f\u0636\u0650\u064a\u064e \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0642\u0650\u0633\u06e1\u0637\u0650 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064f\u0638\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan setiap umat (mempunyai) Rasul. Maka apabila rasul mereka telah datang, diberlakukanlah hukum bagi mereka dengan adil dan (sedikit pun) tidak dizalimi"},{id:48,text:"\u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0645\u064e\u062a\u064e\u0649\u0670 \u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u06e1\u0648\u064e\u0639\u06e1\u062f\u064f \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0635\u064e\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Dan mereka mengatakan, \"Bilakah (datangnya) ancaman itu, jika kamu orang-orang yang benar"},{id:49,text:"\u0642\u064f\u0644 \u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0645\u06e1\u0644\u0650\u0643\u064f \u0644\u0650\u0646\u064e\u0641\u06e1\u0633\u0650\u064a \u0636\u064e\u0631\u0651\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0641\u06e1\u0639\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0634\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06d7 \u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0623\u064f\u0645\u0651\u064e\u0629\u064d \u0623\u064e\u062c\u064e\u0644\u064c\u06da \u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e \u0623\u064e\u062c\u064e\u0644\u064f\u0647\u064f\u0645\u06e1 \u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0640\u0654\u06e1\u062e\u0650\u0631\u064f\u0648\u0646\u064e \u0633\u064e\u0627\u0639\u064e\u0629\u0657 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0642\u06e1\u062f\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Katakanlah (Muhammad), \"Aku tidak kuasa menolak mudarat maupun mendatangkan manfaat kepada diriku, kecuali apa yang Allah kehendaki.\" Bagi setiap umat punya ajal (batas waktu). Apabila ajalnya tiba, mereka tidak dapat meminta penundaan atau percepatan sesaat pun"},{id:50,text:"\u0642\u064f\u0644\u06e1 \u0623\u064e\u0631\u064e\u0621\u064e\u064a\u06e1\u062a\u064f\u0645\u06e1 \u0625\u0650\u0646\u06e1 \u0623\u064e\u062a\u064e\u0649\u0670\u0643\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064f\u0647\u064f\u06e5 \u0628\u064e\u064a\u064e\u0670\u062a\u064b\u0627 \u0623\u064e\u0648\u06e1 \u0646\u064e\u0647\u064e\u0627\u0631\u0657\u0627 \u0645\u0651\u064e\u0627\u0630\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0639\u06e1\u062c\u0650\u0644\u064f \u0645\u0650\u0646\u06e1\u0647\u064f \u0671\u0644\u06e1\u0645\u064f\u062c\u06e1\u0631\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Katakanlah, \"Terangkanlah kepadaku, jika datang kepada kamu siksaan-Nya pada waktu malam atau siang hari, manakah yang diminta untuk disegerakan oleh orang-orang yang berdosa itu"},{id:51,text:"\u0623\u064e\u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0627 \u0648\u064e\u0642\u064e\u0639\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u062a\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6\u0653\u06da \u0621\u064e\u0627\u0653\u0644\u06e1\u0640\u0654\u064e\u0670\u0646\u064e \u0648\u064e\u0642\u064e\u062f\u06e1 \u0643\u064f\u0646\u062a\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6 \u062a\u064e\u0633\u06e1\u062a\u064e\u0639\u06e1\u062c\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Kemudian apakah setelah azab itu terjadi, kamu baru mempercayainya? Apakah (baru) sekarang, padahal sebelumnya kamu selalu meminta agar di segerakan"},{id:52,text:"\u062b\u064f\u0645\u0651\u064e \u0642\u0650\u064a\u0644\u064e \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627\u0652 \u0630\u064f\u0648\u0642\u064f\u0648\u0627\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0671\u0644\u06e1\u062e\u064f\u0644\u06e1\u062f\u0650 \u0647\u064e\u0644\u06e1 \u062a\u064f\u062c\u06e1\u0632\u064e\u0648\u06e1\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0643\u06e1\u0633\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Kemudian dikatakan kepada orang-orang yang zalim itu, \"Rasakanlah olehmu siksaan yang kekal. Kamu tidak diberi balasan, melainkan (sesuai) dengan apa yang telah kamu lakukan"},{id:53,text:"\u06de\u0648\u064e\u064a\u064e\u0633\u06e1\u062a\u064e\u0646\u06e2\u0628\u0650\u0640\u0654\u064f\u0648\u0646\u064e\u0643\u064e \u0623\u064e\u062d\u064e\u0642\u0651\u064c \u0647\u064f\u0648\u064e\u06d6 \u0642\u064f\u0644\u06e1 \u0625\u0650\u064a \u0648\u064e\u0631\u064e\u0628\u0651\u0650\u064a\u0653 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u062d\u064e\u0642\u0651\u065e\u06d6 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064f\u0645 \u0628\u0650\u0645\u064f\u0639\u06e1\u062c\u0650\u0632\u0650\u064a\u0646\u064e",translation:"Dan mereka menanyakan kepadamu (Muhammad), \"Benarkah (azab yang dijanjikan) itu?\" Katakanlah, \"Ya, demi Tuhanku, sesungguhnya (azab) itu pasti benar dan kamu sekali-kali tidak dapat menghindar"},{id:54,text:"\u0648\u064e\u0644\u064e\u0648\u06e1 \u0623\u064e\u0646\u0651\u064e \u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0646\u064e\u0641\u06e1\u0633\u0656 \u0638\u064e\u0644\u064e\u0645\u064e\u062a\u06e1 \u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0644\u064e\u0671\u0641\u06e1\u062a\u064e\u062f\u064e\u062a\u06e1 \u0628\u0650\u0647\u0650\u06e6\u06d7 \u0648\u064e\u0623\u064e\u0633\u064e\u0631\u0651\u064f\u0648\u0627\u0652 \u0671\u0644\u0646\u0651\u064e\u062f\u064e\u0627\u0645\u064e\u0629\u064e \u0644\u064e\u0645\u0651\u064e\u0627 \u0631\u064e\u0623\u064e\u0648\u064f\u0627\u0652 \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064e\u06d6 \u0648\u064e\u0642\u064f\u0636\u0650\u064a\u064e \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0642\u0650\u0633\u06e1\u0637\u0650 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064f\u0638\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan kalau setiap orang yang zalim itu (mempunyai) segala apa yang ada di bumi, tentu dia menebus dirinya dengan itu, dan mereka menyembunyikan391) penyesalannya ketika mereka telah menyaksikan azab. Kemudian diberi keputusan di antara mereka dengan adil, dan mereka tidak dizalimi"},{id:55,text:"\u0623\u064e\u0644\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d7 \u0623\u064e\u0644\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e \u0648\u064e\u0639\u06e1\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u064e\u0642\u0651\u065e \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Ketahuilah sesungguhnya milik Allahlah apa yang ada di langit dan di bumi. Bukankah janji Allah itu benar? Tetapi kebanyakan mereka tidak mengetahui"},{id:56,text:"\u0647\u064f\u0648\u064e \u064a\u064f\u062d\u06e1\u064a\u0650\u06e6 \u0648\u064e\u064a\u064f\u0645\u0650\u064a\u062a\u064f \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u062a\u064f\u0631\u06e1\u062c\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Dialah yang menghidupkan dan mematikan, dan hanya kepada-Nyalah kamu dikembalikan"},{id:57,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0642\u064e\u062f\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u062a\u06e1\u0643\u064f\u0645 \u0645\u0651\u064e\u0648\u06e1\u0639\u0650\u0638\u064e\u0629\u065e \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0634\u0650\u0641\u064e\u0627\u0653\u0621\u065e \u0644\u0651\u0650\u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0635\u0651\u064f\u062f\u064f\u0648\u0631\u0650 \u0648\u064e\u0647\u064f\u062f\u0657\u0649 \u0648\u064e\u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u065e \u0644\u0651\u0650\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Wahai manusia! Sungguh, telah datang kepadamu pelajaran (Alquran) dari Tuhanmu, penyembuh bagi penyakit yang ada dalam dada, dan petunjuk serta rahmat bagi orang yang beriman"},{id:58,text:"\u0642\u064f\u0644\u06e1 \u0628\u0650\u0641\u064e\u0636\u06e1\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0628\u0650\u0631\u064e\u062d\u06e1\u0645\u064e\u062a\u0650\u0647\u0650\u06e6 \u0641\u064e\u0628\u0650\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u0644\u06e1\u064a\u064e\u0641\u06e1\u0631\u064e\u062d\u064f\u0648\u0627\u0652 \u0647\u064f\u0648\u064e \u062e\u064e\u064a\u06e1\u0631\u065e \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u062c\u06e1\u0645\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Katakanlah (Muhammad), \"Dengan karunia Allah dan rahmat-Nya, hendaknya dengan itu mereka bergembira. Itu lebih baik daripada apa yang mereka kumpulkan"},{id:59,text:"\u0642\u064f\u0644\u06e1 \u0623\u064e\u0631\u064e\u0621\u064e\u064a\u06e1\u062a\u064f\u0645 \u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0631\u0651\u0650\u0632\u06e1\u0642\u0656 \u0641\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u062a\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f \u062d\u064e\u0631\u064e\u0627\u0645\u0657\u0627 \u0648\u064e\u062d\u064e\u0644\u064e\u0670\u0644\u0657\u0627 \u0642\u064f\u0644\u06e1 \u0621\u064e\u0627\u0653\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0630\u0650\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u06e1\u06d6 \u0623\u064e\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064e\u0641\u06e1\u062a\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Katakanlah (Muhammad), \"Terangkanlah kepadaku tentang rezeki yang diturunkan Allah kepadamu, lalu kamu jadikan sebagiannya haram dan sebagiannya halal.\" Katakanlah, \"Apakah Allah telah memberikan izin kepadamu (tentang ini), ataukah kamu mengada-ada atas nama Allah"},{id:60,text:"\u0648\u064e\u0645\u064e\u0627 \u0638\u064e\u0646\u0651\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0641\u06e1\u062a\u064e\u0631\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u0643\u064e\u0630\u0650\u0628\u064e \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650\u06d7 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0630\u064f\u0648 \u0641\u064e\u0636\u06e1\u0644\u064d \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0634\u06e1\u0643\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Dan apakah dugaan orang-orang yang mengada-adakan kebohongan terhadap Allah pada hari Kiamat? Sesungguhnya Allah benar-benar mempunyai karunia (yang dilimpahkan) kepada manusia, tetapi kebanyakan mereka tidak bersyukur"},{id:61,text:"\u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064f \u0641\u0650\u064a \u0634\u064e\u0623\u06e1\u0646\u0656 \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u062a\u06e1\u0644\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1\u0647\u064f \u0645\u0650\u0646 \u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u0656 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u06e1 \u0639\u064e\u0645\u064e\u0644\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0634\u064f\u0647\u064f\u0648\u062f\u064b\u0627 \u0625\u0650\u0630\u06e1 \u062a\u064f\u0641\u0650\u064a\u0636\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0647\u0650\u06da \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0639\u06e1\u0632\u064f\u0628\u064f \u0639\u064e\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064e \u0645\u0650\u0646 \u0645\u0651\u0650\u062b\u06e1\u0642\u064e\u0627\u0644\u0650 \u0630\u064e\u0631\u0651\u064e\u0629\u0656 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0644\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064e\u0635\u06e1\u063a\u064e\u0631\u064e \u0645\u0650\u0646 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064e\u0643\u06e1\u0628\u064e\u0631\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0641\u0650\u064a \u0643\u0650\u062a\u064e\u0670\u0628\u0656 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u064d",translation:"Dan tidakkah engkau (Muhammad) berada dalam suatu urusan, dan tidak membaca suatu ayat Alquran serta tidak pula kamu melakukan suatu pekerjaan, melainkan Kami menjadi saksi atasmu ketika kamu melakukannya. Tidak lengah sedikit pun dari pengetahuan Tuhanmu biarpun sebesar zarrah, baik di bumi ataupun di langit. Tidak ada sesuatu yang lebih kecil dan yang lebih besar daripada itu, melainkan semua tercatat dalam Kitab yang nyata (Lau\u1e25 Ma\u1e25f\u016b\u1e93)"},{id:62,text:"\u0623\u064e\u0644\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e \u0623\u064e\u0648\u06e1\u0644\u0650\u064a\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0627 \u062e\u064e\u0648\u06e1\u0641\u064c \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u06e1 \u064a\u064e\u062d\u06e1\u0632\u064e\u0646\u064f\u0648\u0646\u064e",translation:"Ingatlah wali-wali Allah itu, tidak ada rasa takut pada mereka dan mereka tidak bersedih hati"},{id:63,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",translation:"(Yaitu) orang-orang yang beriman dan senantiasa bertakwa"},{id:64,text:"\u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0628\u064f\u0634\u06e1\u0631\u064e\u0649\u0670 \u0641\u0650\u064a \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u0650 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0648\u064e\u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650\u06da \u0644\u064e\u0627 \u062a\u064e\u0628\u06e1\u062f\u0650\u064a\u0644\u064e \u0644\u0650\u0643\u064e\u0644\u0650\u0645\u064e\u0670\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0641\u064e\u0648\u06e1\u0632\u064f \u0671\u0644\u06e1\u0639\u064e\u0638\u0650\u064a\u0645\u064f",translation:"Bagi mereka berita gembira di dalam kehidupan di dunia dan di akhirat. Tidak ada perubahan bagi janji-janji Allah. Demikian itulah kemenangan yang agung"},{id:65,text:"\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062d\u06e1\u0632\u064f\u0646\u0643\u064e \u0642\u064e\u0648\u06e1\u0644\u064f\u0647\u064f\u0645\u06e1\u06d8 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0639\u0650\u0632\u0651\u064e\u0629\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627\u06da \u0647\u064f\u0648\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u0650\u064a\u0639\u064f \u0671\u0644\u06e1\u0639\u064e\u0644\u0650\u064a\u0645\u064f",translation:"Dan janganlah engkau (Muhammad) sedih oleh perkataan mereka. Sungguh, kekuasaan itu seluruhnya milik Allah. Dia Maha Mendengar, Maha Mengetahui"},{id:66,text:"\u0623\u064e\u0644\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0646 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0645\u064e\u0646 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d7 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0653\u0621\u064e\u06da \u0625\u0650\u0646 \u064a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0638\u0651\u064e\u0646\u0651\u064e \u0648\u064e\u0625\u0650\u0646\u06e1 \u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u064a\u064e\u062e\u06e1\u0631\u064f\u0635\u064f\u0648\u0646\u064e",translation:"Ingatlah, milik Allah meliputi semua yang ada di langit dan semua yang ada di bumi. Dan orang-orang yang menyeru sekutu-sekutu selain Allah, tidaklah mengikuti (suatu keyakinan). Mereka hanya mengikuti persangkaan belaka, dan mereka hanyalah menduga-duga"},{id:67,text:"\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u064e \u0644\u0650\u062a\u064e\u0633\u06e1\u0643\u064f\u0646\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0647\u0650 \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u0645\u064f\u0628\u06e1\u0635\u0650\u0631\u064b\u0627\u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0623\u0653\u064a\u064e\u0670\u062a\u0656 \u0644\u0651\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064e\u0633\u06e1\u0645\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Dialah yang menjadikan malam bagimu agar kamu beristirahat padanya dan menjadikan siang terang benderang. Sungguh, yang demikian itu terdapat tanda-tanda (kekuasaan Allah) bagi orang-orang yang mendengar"},{id:68,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0644\u064e\u062f\u0657\u0627\u06d7 \u0633\u064f\u0628\u06e1\u062d\u064e\u0670\u0646\u064e\u0647\u064f\u06e5\u06d6 \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u063a\u064e\u0646\u0650\u064a\u0651\u064f\u06d6 \u0644\u064e\u0647\u064f\u06e5 \u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06da \u0625\u0650\u0646\u06e1 \u0639\u0650\u0646\u062f\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0633\u064f\u0644\u06e1\u0637\u064e\u0670\u0646\u0650\u06ed \u0628\u0650\u0647\u064e\u0670\u0630\u064e\u0627\u0653\u06da \u0623\u064e\u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Mereka (orang-orang Yahudi dan Nasrani) berkata, \"Allah mempunyai anak.\" Mahasuci Dia, Dialah Yang Mahakaya; milik-Nyalah apa yang ada di langit dan apa yang ada di bumi. Kamu tidak mempunyai alasan yang kuat tentang ini. Pantaskah kamu mengatakan tentang Allah apa yang kamu tidak ketahui"},{id:69,text:"\u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0641\u06e1\u062a\u064e\u0631\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u0643\u064e\u0630\u0650\u0628\u064e \u0644\u064e\u0627 \u064a\u064f\u0641\u06e1\u0644\u0650\u062d\u064f\u0648\u0646\u064e",translation:"Katakanlah, \"Sesungguhnya orang-orang yang mengada-adakan kebohongan terhadap Allah tidak akan beruntung"},{id:70,text:"\u0645\u064e\u062a\u064e\u0670\u0639\u065e \u0641\u0650\u064a \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0645\u064e\u0631\u06e1\u062c\u0650\u0639\u064f\u0647\u064f\u0645\u06e1 \u062b\u064f\u0645\u0651\u064e \u0646\u064f\u0630\u0650\u064a\u0642\u064f\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0671\u0644\u0634\u0651\u064e\u062f\u0650\u064a\u062f\u064e \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0643\u06e1\u0641\u064f\u0631\u064f\u0648\u0646\u064e",translation:"(Bagi mereka) kesenangan (sesaat) ketika di dunia, selanjutnya kepada Kamilah mereka kembali, kemudian Kami rasakan kepada mereka azab yang berat, karena kekafiran mereka"},{id:71,text:"\u06de\u0648\u064e\u0671\u062a\u06e1\u0644\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0646\u064e\u0628\u064e\u0623\u064e \u0646\u064f\u0648\u062d\u064d \u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u06e6 \u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064e \u0643\u064e\u0628\u064f\u0631\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645 \u0645\u0651\u064e\u0642\u064e\u0627\u0645\u0650\u064a \u0648\u064e\u062a\u064e\u0630\u06e1\u0643\u0650\u064a\u0631\u0650\u064a \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u06e1\u062a\u064f \u0641\u064e\u0623\u064e\u062c\u06e1\u0645\u0650\u0639\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0645\u06e1\u0631\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u06e1 \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0627 \u064a\u064e\u0643\u064f\u0646\u06e1 \u0623\u064e\u0645\u06e1\u0631\u064f\u0643\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u063a\u064f\u0645\u0651\u064e\u0629\u0657 \u062b\u064f\u0645\u0651\u064e \u0671\u0642\u06e1\u0636\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0646\u0638\u0650\u0631\u064f\u0648\u0646\u0650",translation:"Dan bacakanlah kepada mereka berita penting (tentang) Nuh ketika (dia) berkata kepada kaumnya, \"Wahai kaumku! Jika terasa berat bagimu aku tinggal (bersamamu) dan peringatanku dengan ayat-ayat Allah, maka kepada Allah aku bertawakal. Karena itu bulatkanlah keputusanmu dan kumpulkanlah sekutu-sekutumu (untuk membinasakanku), dan janganlah keputusanmu itu dirahasiakan. Kemudian bertindaklah terhadap diriku, dan janganlah kamu tunda lagi"},{id:72,text:"\u0641\u064e\u0625\u0650\u0646 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u064a\u06e1\u062a\u064f\u0645\u06e1 \u0641\u064e\u0645\u064e\u0627 \u0633\u064e\u0623\u064e\u0644\u06e1\u062a\u064f\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u062c\u06e1\u0631\u064d\u06d6 \u0625\u0650\u0646\u06e1 \u0623\u064e\u062c\u06e1\u0631\u0650\u064a\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0648\u064e\u0623\u064f\u0645\u0650\u0631\u06e1\u062a\u064f \u0623\u064e\u0646\u06e1 \u0623\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0633\u06e1\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Maka jika kamu berpaling (dari peringatanku), aku tidak meminta imbalan sedikit pun darimu. Imbalanku tidak lain hanyalah dari Allah, dan aku diperintah agar aku termasuk golongan orang-orang muslim (berserah diri)"},{id:73,text:"\u0641\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0647\u064f \u0641\u064e\u0646\u064e\u062c\u0651\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f \u0648\u064e\u0645\u064e\u0646 \u0645\u0651\u064e\u0639\u064e\u0647\u064f\u06e5 \u0641\u0650\u064a \u0671\u0644\u06e1\u0641\u064f\u0644\u06e1\u0643\u0650 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u062e\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0641\u064e \u0648\u064e\u0623\u064e\u063a\u06e1\u0631\u064e\u0642\u06e1\u0646\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627\u06d6 \u0641\u064e\u0671\u0646\u0638\u064f\u0631\u06e1 \u0643\u064e\u064a\u06e1\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0670\u0642\u0650\u0628\u064e\u0629\u064f \u0671\u0644\u06e1\u0645\u064f\u0646\u0630\u064e\u0631\u0650\u064a\u0646\u064e",translation:"Kemudian mereka mendustakannya (Nuh), lalu Kami selamatkan dia dan orang yang bersamanya di dalam kapal, dan Kami jadikan mereka itu khalifah dan Kami tenggelamkan orang yang mendustakan ayat-ayat Kami. Maka perhatikanlah bagaimana kesudahan orang-orang yang diberi peringatan itu"},{id:74,text:"\u062b\u064f\u0645\u0651\u064e \u0628\u064e\u0639\u064e\u062b\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u0647\u0650\u06e6 \u0631\u064f\u0633\u064f\u0644\u064b\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u0645\u06e1 \u0641\u064e\u062c\u064e\u0627\u0653\u0621\u064f\u0648\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0650 \u0641\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0644\u0650\u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f\u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u0637\u06e1\u0628\u064e\u0639\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064f\u0644\u064f\u0648\u0628\u0650 \u0671\u0644\u06e1\u0645\u064f\u0639\u06e1\u062a\u064e\u062f\u0650\u064a\u0646\u064e",translation:"Kemudian setelahnya (Nuh), Kami utus beberapa rasul kepada kaum mereka (masing-masing), maka rasul-rasul itu datang kepada mereka dengan membawa keterangan yang jelas, tetapi mereka tidak mau beriman karena mereka dahulu telah (biasa) mendustakannya. Demikianlah Kami mengunci hati orang-orang yang melampaui batas"},{id:75,text:"\u062b\u064f\u0645\u0651\u064e \u0628\u064e\u0639\u064e\u062b\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u0647\u0650\u0645 \u0645\u0651\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u0647\u064e\u0670\u0631\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0648\u064e\u0645\u064e\u0644\u064e\u0625\u0650\u064a\u0652\u0647\u0650\u06e6 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u064e\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0642\u064e\u0648\u06e1\u0645\u0657\u0627 \u0645\u0651\u064f\u062c\u06e1\u0631\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Kemudian setelah mereka, Kami utus Musa dan Harun kepada Fir'aun dan para pemuka kaumnya, dengan membawa tanda-tanda (kekuasaan) Kami. Ternyata mereka menyombongkan diri dan mereka adalah orang-orang yang berdosa"},{id:76,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f \u0645\u0650\u0646\u06e1 \u0639\u0650\u0646\u062f\u0650\u0646\u064e\u0627 \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0644\u064e\u0633\u0650\u062d\u06e1\u0631\u065e \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u065e",translation:"Maka ketika telah datang kepada mereka kebenaran dari sisi Kami, mereka berkata, \"Ini benar-benar sihir yang nyata"},{id:77,text:"\u0642\u064e\u0627\u0644\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670\u0653 \u0623\u064e\u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0644\u0650\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u06e1\u06d6 \u0623\u064e\u0633\u0650\u062d\u06e1\u0631\u064c \u0647\u064e\u0670\u0630\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0641\u06e1\u0644\u0650\u062d\u064f \u0671\u0644\u0633\u0651\u064e\u0640\u0670\u062d\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Musa berkata, \"Pantaskah kamu mengatakan terhadap kebenaran ketika ia datang kepadamu, 'sihirkah ini?' Padahal para penyihir itu tidaklah mendapat kemenangan"},{id:78,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u062c\u0650\u0626\u06e1\u062a\u064e\u0646\u064e\u0627 \u0644\u0650\u062a\u064e\u0644\u06e1\u0641\u0650\u062a\u064e\u0646\u064e\u0627 \u0639\u064e\u0645\u0651\u064e\u0627 \u0648\u064e\u062c\u064e\u062f\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0621\u064e\u0646\u064e\u0627 \u0648\u064e\u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u064e\u0627 \u0671\u0644\u06e1\u0643\u0650\u0628\u06e1\u0631\u0650\u064a\u064e\u0627\u0653\u0621\u064f \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u0646\u064e\u062d\u06e1\u0646\u064f \u0644\u064e\u0643\u064f\u0645\u064e\u0627 \u0628\u0650\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Mereka berkata, \"Apakah engkau datang kepada kami untuk memalingkan kami dari apa (kepercayaan) yang kami dapati nenek moyang kami mengerjakannya (menyembah berhala), dan agar kamu berdua mempunyai kekuasaan di bumi (negeri Mesir)? Kami tidak akan mempercayai kamu berdua"},{id:79,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064f \u0671\u0626\u06e1\u062a\u064f\u0648\u0646\u0650\u064a \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0633\u064e\u0670\u062d\u0650\u0631\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u0656",translation:"Dan Fir'aun berkata (kepada pemuka kaumnya), \"Datangkanlah kepadaku semua penyihir yang ulung"},{id:80,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0633\u0651\u064e\u062d\u064e\u0631\u064e\u0629\u064f \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u064f\u0648\u0633\u064e\u0649\u0670\u0653 \u0623\u064e\u0644\u06e1\u0642\u064f\u0648\u0627\u0652 \u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064f\u0645 \u0645\u0651\u064f\u0644\u06e1\u0642\u064f\u0648\u0646\u064e",translation:"Maka ketika para penyihir itu datang, Musa berkata kepada mereka, \"Lemparkanlah apa yang hendak kamu lemparkan"},{id:81,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u0644\u06e1\u0642\u064e\u0648\u06e1\u0627\u0652 \u0642\u064e\u0627\u0644\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0645\u064e\u0627 \u062c\u0650\u0626\u06e1\u062a\u064f\u0645 \u0628\u0650\u0647\u0650 \u0671\u0644\u0633\u0651\u0650\u062d\u06e1\u0631\u064f\u06d6 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0633\u064e\u064a\u064f\u0628\u06e1\u0637\u0650\u0644\u064f\u0647\u064f\u06e5\u0653 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064f\u0635\u06e1\u0644\u0650\u062d\u064f \u0639\u064e\u0645\u064e\u0644\u064e \u0671\u0644\u06e1\u0645\u064f\u0641\u06e1\u0633\u0650\u062f\u0650\u064a\u0646\u064e",translation:"Setelah mereka melemparkan, Musa berkata, \"Apa yang kamu lakukan, itulah sihir, sesungguhnya Allah akan menampakkan kepalsuan sihir. Sungguh, Allah tidak akan membiarkan terus berlangsungnya pekerjaan orang yang berbuat kerusakan"},{id:82,text:"\u0648\u064e\u064a\u064f\u062d\u0650\u0642\u0651\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064e \u0628\u0650\u0643\u064e\u0644\u0650\u0645\u064e\u0670\u062a\u0650\u0647\u0650\u06e6 \u0648\u064e\u0644\u064e\u0648\u06e1 \u0643\u064e\u0631\u0650\u0647\u064e \u0671\u0644\u06e1\u0645\u064f\u062c\u06e1\u0631\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Dan Allah akan mengokohkan yang benar dengan ketetapan-Nya, walaupun orang-orang yang berbuat dosa tidak menyukainya"},{id:83,text:"\u0641\u064e\u0645\u064e\u0627\u0653 \u0621\u064e\u0627\u0645\u064e\u0646\u064e \u0644\u0650\u0645\u064f\u0648\u0633\u064e\u0649\u0670\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u0629\u065e \u0645\u0651\u0650\u0646 \u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u06e6 \u0639\u064e\u0644\u064e\u0649\u0670 \u062e\u064e\u0648\u06e1\u0641\u0656 \u0645\u0651\u0650\u0646 \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0648\u064e\u0645\u064e\u0644\u064e\u0625\u0650\u064a\u0652\u0647\u0650\u0645\u06e1 \u0623\u064e\u0646 \u064a\u064e\u0641\u06e1\u062a\u0650\u0646\u064e\u0647\u064f\u0645\u06e1\u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0644\u064e\u0639\u064e\u0627\u0644\u0656 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0633\u06e1\u0631\u0650\u0641\u0650\u064a\u0646\u064e",translation:"Maka tidak ada yang beriman kepada Musa, selain keturunan dari kaumnya dalam keadaan takut bahwa Fir'aun dan para pemuka (kaum)nya akan menyiksa mereka. Dan Sungguh, Fir'aun itu benar-benar telah berbuat sewenang-wenang di bumi, dan benar-benar termasuk orang yang melampaui batas"},{id:84,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0621\u064e\u0627\u0645\u064e\u0646\u062a\u064f\u0645 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645 \u0645\u0651\u064f\u0633\u06e1\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dan Musa berkata, \"Wahai kaumku! Apabila kamu beriman kepada Allah, maka bertawakallah kepada-Nya, jika kamu benar-benar orang muslim (berserah diri)"},{id:85,text:"\u0641\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u06e1\u0646\u064e\u0627 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0644\u064e\u0627 \u062a\u064e\u062c\u06e1\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0641\u0650\u062a\u06e1\u0646\u064e\u0629\u0657 \u0644\u0651\u0650\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Lalu mereka berkata, \"Kepada Allahlah kami bertawakal. Ya Tuhan kami, janganlah Engkau jadikan kami (sasaran) fitnah bagi kaum yang zalim"},{id:86,text:"\u0648\u064e\u0646\u064e\u062c\u0651\u0650\u0646\u064e\u0627 \u0628\u0650\u0631\u064e\u062d\u06e1\u0645\u064e\u062a\u0650\u0643\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"dan selamatkanlah kami dengan rahmat-Mu dari orang-orang kafir"},{id:87,text:"\u0648\u064e\u0623\u064e\u0648\u06e1\u062d\u064e\u064a\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u0623\u064e\u062e\u0650\u064a\u0647\u0650 \u0623\u064e\u0646 \u062a\u064e\u0628\u064e\u0648\u0651\u064e\u0621\u064e\u0627 \u0644\u0650\u0642\u064e\u0648\u06e1\u0645\u0650\u0643\u064f\u0645\u064e\u0627 \u0628\u0650\u0645\u0650\u0635\u06e1\u0631\u064e \u0628\u064f\u064a\u064f\u0648\u062a\u0657\u0627 \u0648\u064e\u0671\u062c\u06e1\u0639\u064e\u0644\u064f\u0648\u0627\u0652 \u0628\u064f\u064a\u064f\u0648\u062a\u064e\u0643\u064f\u0645\u06e1 \u0642\u0650\u0628\u06e1\u0644\u064e\u0629\u0657 \u0648\u064e\u0623\u064e\u0642\u0650\u064a\u0645\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e\u06d7 \u0648\u064e\u0628\u064e\u0634\u0651\u0650\u0631\u0650 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dan Kami wahyukan kepada Musa dan saudaranya, \"Ambillah beberapa rumah di Mesir untuk (tempat tinggal) kaummu dan jadikanlah rumah-rumahmu itu tempat ibadah dan laksanakanlah salat serta gembirakanlah orang-orang mukmin"},{id:88,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u062a\u064e \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0648\u064e\u0645\u064e\u0644\u064e\u0623\u064e\u0647\u064f\u06e5 \u0632\u0650\u064a\u0646\u064e\u0629\u0657 \u0648\u064e\u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u0657\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u0650 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0644\u0650\u064a\u064f\u0636\u0650\u0644\u0651\u064f\u0648\u0627\u0652 \u0639\u064e\u0646 \u0633\u064e\u0628\u0650\u064a\u0644\u0650\u0643\u064e\u06d6 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0671\u0637\u06e1\u0645\u0650\u0633\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0671\u0634\u06e1\u062f\u064f\u062f\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u06e1 \u0641\u064e\u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0627\u0652 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0631\u064e\u0648\u064f\u0627\u0652 \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0671\u0644\u06e1\u0623\u064e\u0644\u0650\u064a\u0645\u064e",translation:"Dan Musa berkata, \"Ya Tuhan kami, Engkau telah memberi kepada Fir'aun dan para pemuka kaumnya perhiasan dan harta kekayaan dalam kehidupan dunia. Ya Tuhan kami, (akibatnya) mereka menyesatkan (manusia) dari jalan-Mu. Ya Tuhan, binasakanlah harta mereka, dan kuncilah hati mereka, sehingga mereka tidak beriman sampai mereka melihat azab yang pedih"},{id:89,text:"\u0642\u064e\u0627\u0644\u064e \u0642\u064e\u062f\u06e1 \u0623\u064f\u062c\u0650\u064a\u0628\u064e\u062a \u062f\u0651\u064e\u0639\u06e1\u0648\u064e\u062a\u064f\u0643\u064f\u0645\u064e\u0627 \u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u0642\u0650\u064a\u0645\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064e\u0627\u0653\u0646\u0651\u0650 \u0633\u064e\u0628\u0650\u064a\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dia Allah berfirman, \"Sungguh, telah diperkenankan permohonan kamu berdua, sebab itu tetaplah kamu berdua pada jalan yang lurus dan jangan sekali-kali kamu mengikuti jalan orang yang tidak mengetahui"},{id:90,text:"\u06de\u0648\u064e\u062c\u064e\u0670\u0648\u064e\u0632\u06e1\u0646\u064e\u0627 \u0628\u0650\u0628\u064e\u0646\u0650\u064a\u0653 \u0625\u0650\u0633\u06e1\u0631\u064e\u0640\u0670\u0653\u0621\u0650\u064a\u0644\u064e \u0671\u0644\u06e1\u0628\u064e\u062d\u06e1\u0631\u064e \u0641\u064e\u0623\u064e\u062a\u06e1\u0628\u064e\u0639\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064f \u0648\u064e\u062c\u064f\u0646\u064f\u0648\u062f\u064f\u0647\u064f\u06e5 \u0628\u064e\u063a\u06e1\u064a\u0657\u0627 \u0648\u064e\u0639\u064e\u062f\u06e1\u0648\u064b\u0627\u06d6 \u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u064e\u0627\u0653 \u0623\u064e\u062f\u06e1\u0631\u064e\u0643\u064e\u0647\u064f \u0671\u0644\u06e1\u063a\u064e\u0631\u064e\u0642\u064f \u0642\u064e\u0627\u0644\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u062a\u064f \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0621\u064e\u0627\u0645\u064e\u0646\u064e\u062a\u06e1 \u0628\u0650\u0647\u0650\u06e6 \u0628\u064e\u0646\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0633\u06e1\u0631\u064e\u0640\u0670\u0653\u0621\u0650\u064a\u0644\u064e \u0648\u064e\u0623\u064e\u0646\u064e\u0627\u06e0 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0633\u06e1\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dan Kami selamatkan Bani Israil melintasi laut, kemudian Fir'aun dan bala tentaranya mengikuti mereka, untuk menzalimi dan menindas (mereka). Sehingga ketika Fir'aun hampir tenggelam dia berkata, \"Aku percaya bahwa tidak ada tuhan melainkan Tuhan yang dipercayai oleh Bani Israil, dan aku termasuk orang-orang muslim (berserah diri)"},{id:91,text:"\u0621\u064e\u0627\u0653\u0644\u06e1\u0640\u0654\u064e\u0670\u0646\u064e \u0648\u064e\u0642\u064e\u062f\u06e1 \u0639\u064e\u0635\u064e\u064a\u06e1\u062a\u064e \u0642\u064e\u0628\u06e1\u0644\u064f \u0648\u064e\u0643\u064f\u0646\u062a\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0641\u06e1\u0633\u0650\u062f\u0650\u064a\u0646\u064e",translation:"Mengapa baru sekarang (kamu beriman), padahal sesungguhnya engkau telah durhaka sejak dahulu, dan engkau termasuk orang yang berbuat kerusakan"},{id:92,text:"\u0641\u064e\u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e \u0646\u064f\u0646\u064e\u062c\u0651\u0650\u064a\u0643\u064e \u0628\u0650\u0628\u064e\u062f\u064e\u0646\u0650\u0643\u064e \u0644\u0650\u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0644\u0650\u0645\u064e\u0646\u06e1 \u062e\u064e\u0644\u06e1\u0641\u064e\u0643\u064e \u0621\u064e\u0627\u064a\u064e\u0629\u0657\u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0639\u064e\u0646\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0644\u064e\u063a\u064e\u0670\u0641\u0650\u0644\u064f\u0648\u0646\u064e",translation:"(Maka pada hari ini Kami selamatkan jasadmu392) agar engkau dapat menjadi pelajaran bagi orang-orang yang datang setelahmu, tetapi kebanyakan manusia tidak mengindahkan tanda-tanda (kekuasaan) Kami"},{id:93,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0628\u064e\u0648\u0651\u064e\u0623\u06e1\u0646\u064e\u0627 \u0628\u064e\u0646\u0650\u064a\u0653 \u0625\u0650\u0633\u06e1\u0631\u064e\u0640\u0670\u0653\u0621\u0650\u064a\u0644\u064e \u0645\u064f\u0628\u064e\u0648\u0651\u064e\u0623\u064e \u0635\u0650\u062f\u06e1\u0642\u0656 \u0648\u064e\u0631\u064e\u0632\u064e\u0642\u06e1\u0646\u064e\u0670\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0637\u0651\u064e\u064a\u0651\u0650\u0628\u064e\u0670\u062a\u0650 \u0641\u064e\u0645\u064e\u0627 \u0671\u062e\u06e1\u062a\u064e\u0644\u064e\u0641\u064f\u0648\u0627\u0652 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0639\u0650\u0644\u06e1\u0645\u064f\u06da \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u064a\u064e\u0642\u06e1\u0636\u0650\u064a \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u0641\u0650\u064a\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0647\u0650 \u064a\u064e\u062e\u06e1\u062a\u064e\u0644\u0650\u0641\u064f\u0648\u0646\u064e",translation:"Dan sungguh, Kami telah menempatkan Bani Israil di tempat kediaman yang bagus dan Kami beri mereka rezeki yang baik. Maka mereka tidak berselisih, kecuali setelah datang kepada mereka pengetahuan (yang tersebut dalam Taurat). Sesungguhnya Tuhan kamu akan memberi keputusan antara mereka pada hari Kiamat tentang apa yang mereka perselisihkan itu"},{id:94,text:"\u0641\u064e\u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064e \u0641\u0650\u064a \u0634\u064e\u0643\u0651\u0656 \u0645\u0651\u0650\u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0641\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0642\u06e1\u0631\u064e\u0621\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064e\u06da \u0644\u064e\u0642\u064e\u062f\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u0643\u064e \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064e \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0645\u06e1\u062a\u064e\u0631\u0650\u064a\u0646\u064e",translation:"Maka jika engkau (Muhammad) berada dalam keragu-raguan tentang apa yang Kami turunkan kepadamu, maka tanyakanlah kepada orang yang membaca kitab sebelummu. Sungguh, telah datang kebenaran kepadamu dari Tuhanmu, maka janganlah sekali-kali engkau termasuk orang yang ragu"},{id:95,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u062e\u064e\u0670\u0633\u0650\u0631\u0650\u064a\u0646\u064e",translation:"dan janganlah sekali-kali engkau termasuk orang yang mendustakan ayat-ayat Allah, nanti engkau termasuk orang yang rugi"},{id:96,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062d\u064e\u0642\u0651\u064e\u062a\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0643\u064e\u0644\u0650\u0645\u064e\u062a\u064f \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Sungguh, orang-orang yang telah dipastikan mendapat ketetapan Tuhanmu, tidaklah akan beriman"},{id:97,text:"\u0648\u064e\u0644\u064e\u0648\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u062a\u06e1\u0647\u064f\u0645\u06e1 \u0643\u064f\u0644\u0651\u064f \u0621\u064e\u0627\u064a\u064e\u0629\u064d \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0631\u064e\u0648\u064f\u0627\u0652 \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0671\u0644\u06e1\u0623\u064e\u0644\u0650\u064a\u0645\u064e",translation:"meskipun mereka mendapat tanda-tanda (kebesaran Allah), hingga mereka menyaksikan azab yang pedih"},{id:98,text:"\u0641\u064e\u0644\u064e\u0648\u06e1\u0644\u064e\u0627 \u0643\u064e\u0627\u0646\u064e\u062a\u06e1 \u0642\u064e\u0631\u06e1\u064a\u064e\u0629\u064c \u0621\u064e\u0627\u0645\u064e\u0646\u064e\u062a\u06e1 \u0641\u064e\u0646\u064e\u0641\u064e\u0639\u064e\u0647\u064e\u0627\u0653 \u0625\u0650\u064a\u0645\u064e\u0670\u0646\u064f\u0647\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0648\u06e1\u0645\u064e \u064a\u064f\u0648\u0646\u064f\u0633\u064e \u0644\u064e\u0645\u0651\u064e\u0627\u0653 \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0643\u064e\u0634\u064e\u0641\u06e1\u0646\u064e\u0627 \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0671\u0644\u06e1\u062e\u0650\u0632\u06e1\u064a\u0650 \u0641\u0650\u064a \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u0650 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0648\u064e\u0645\u064e\u062a\u0651\u064e\u0639\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649\u0670 \u062d\u0650\u064a\u0646\u0656",translation:"Maka mengapa tidak ada (penduduk) suatu negeri pun yang beriman, lalu imannya itu bermanfaat baginya selain kaum Yunus. Ketika mereka (kaum Yunus itu) beriman, Kami hilangkan dari mereka azab yang menghinakan dalam kehidupan dunia, dan Kami beri kesenangan kepada mereka sampai waktu tertentu"},{id:99,text:"\u0648\u064e\u0644\u064e\u0648\u06e1 \u0634\u064e\u0627\u0653\u0621\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0644\u064e\u0623\u0653\u0645\u064e\u0646\u064e \u0645\u064e\u0646 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0643\u064f\u0644\u0651\u064f\u0647\u064f\u0645\u06e1 \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627\u06da \u0623\u064e\u0641\u064e\u0623\u064e\u0646\u062a\u064e \u062a\u064f\u0643\u06e1\u0631\u0650\u0647\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dan jika Tuhanmu menghendaki, tentulah beriman semua orang di bumi seluruhnya. Tetapi apakah kamu (hendak) memaksa manusia agar mereka menjadi orang-orang yang beriman"},{id:100,text:"\u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0646\u064e\u0641\u06e1\u0633\u064d \u0623\u064e\u0646 \u062a\u064f\u0624\u06e1\u0645\u0650\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0625\u0650\u0630\u06e1\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0648\u064e\u064a\u064e\u062c\u06e1\u0639\u064e\u0644\u064f \u0671\u0644\u0631\u0651\u0650\u062c\u06e1\u0633\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Dan tidak seorang pun akan beriman kecuali dengan izin Allah, dan Allah menimpakan azab kepada orang yang tidak berakal"},{id:101,text:"\u0642\u064f\u0644\u0650 \u0671\u0646\u0638\u064f\u0631\u064f\u0648\u0627\u0652 \u0645\u064e\u0627\u0630\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06da \u0648\u064e\u0645\u064e\u0627 \u062a\u064f\u063a\u06e1\u0646\u0650\u064a \u0671\u0644\u06e1\u0623\u0653\u064a\u064e\u0670\u062a\u064f \u0648\u064e\u0671\u0644\u0646\u0651\u064f\u0630\u064f\u0631\u064f \u0639\u064e\u0646 \u0642\u064e\u0648\u06e1\u0645\u0656 \u0644\u0651\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Katakanlah, \"Perhatikanlah apa yang ada di langit dan di bumi!\" Tidaklah bermanfaat tanda-tanda (kebesaran Allah) dan rasul-rasul yang memberi peringatan bagi orang yang tidak beriman"},{id:102,text:"\u0641\u064e\u0647\u064e\u0644\u06e1 \u064a\u064e\u0646\u062a\u064e\u0638\u0650\u0631\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u0650\u062b\u06e1\u0644\u064e \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062e\u064e\u0644\u064e\u0648\u06e1\u0627\u0652 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u0645\u06e1\u06da \u0642\u064f\u0644\u06e1 \u0641\u064e\u0671\u0646\u062a\u064e\u0638\u0650\u0631\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u0650\u064a \u0645\u064e\u0639\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0646\u062a\u064e\u0638\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Maka mereka tidak menunggu-nunggu kecuali (kejadian-kejadian) yang sama dengan kejadian-kejadian (yang menimpa) orang-orang terdahulu sebelum mereka. Katakanlah, \"Maka tunggulah, aku pun termasuk orang yang menunggu bersama kamu"},{id:103,text:"\u062b\u064f\u0645\u0651\u064e \u0646\u064f\u0646\u064e\u062c\u0651\u0650\u064a \u0631\u064f\u0633\u064f\u0644\u064e\u0646\u064e\u0627 \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652\u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062d\u064e\u0642\u0651\u064b\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0646\u064f\u0646\u062c\u0650 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Kemudian Kami selamatkan rasul-rasul Kami dan orang-orang yang beriman, demikianlah menjadi kewajiban Kami menyelamatkan orang yang beriman"},{id:104,text:"\u0642\u064f\u0644\u06e1 \u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0641\u0650\u064a \u0634\u064e\u0643\u0651\u0656 \u0645\u0651\u0650\u0646 \u062f\u0650\u064a\u0646\u0650\u064a \u0641\u064e\u0644\u064e\u0627\u0653 \u0623\u064e\u0639\u06e1\u0628\u064f\u062f\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u06e1 \u0623\u064e\u0639\u06e1\u0628\u064f\u062f\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064e\u062a\u064e\u0648\u064e\u0641\u0651\u064e\u0649\u0670\u0643\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0623\u064f\u0645\u0650\u0631\u06e1\u062a\u064f \u0623\u064e\u0646\u06e1 \u0623\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Katakanlah (Muhammad), \"Wahai manusia! Jika kamu masih dalam keragu-raguan tentang agamaku, maka (ketahuilah) aku tidak menyembah yang kamu sembah selain Allah, tetapi aku menyembah Allah yang akan mematikan kamu dan aku telah diperintah agar termasuk orang yang beriman"},{id:105,text:"\u0648\u064e\u0623\u064e\u0646\u06e1 \u0623\u064e\u0642\u0650\u0645\u06e1 \u0648\u064e\u062c\u06e1\u0647\u064e\u0643\u064e \u0644\u0650\u0644\u062f\u0651\u0650\u064a\u0646\u0650 \u062d\u064e\u0646\u0650\u064a\u0641\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0634\u06e1\u0631\u0650\u0643\u0650\u064a\u0646\u064e",translation:"dan (aku telah diperintah), \"Hadapkanlah wajahmu kepada agama dengan tulus dan ikhlas, dan jangan sekali-kali engkau termasuk orang yang musyrik"},{id:106,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062f\u06e1\u0639\u064f \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0646\u0641\u064e\u0639\u064f\u0643\u064e \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0636\u064f\u0631\u0651\u064f\u0643\u064e\u06d6 \u0641\u064e\u0625\u0650\u0646 \u0641\u064e\u0639\u064e\u0644\u06e1\u062a\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0625\u0650\u0630\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dan jangan engkau menyembah sesuatu yang tidak memberi manfaat dan tidak (pula) memberi bencana kepadamu selain Allah, sebab jika engkau lakukan (yang demikian), maka sesungguhnya engkau termasuk orang-orang zalim"},{id:107,text:"\u0648\u064e\u0625\u0650\u0646 \u064a\u064e\u0645\u06e1\u0633\u064e\u0633\u06e1\u0643\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0636\u064f\u0631\u0651\u0656 \u0641\u064e\u0644\u064e\u0627 \u0643\u064e\u0627\u0634\u0650\u0641\u064e \u0644\u064e\u0647\u064f\u06e5\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e\u06d6 \u0648\u064e\u0625\u0650\u0646 \u064a\u064f\u0631\u0650\u062f\u06e1\u0643\u064e \u0628\u0650\u062e\u064e\u064a\u06e1\u0631\u0656 \u0641\u064e\u0644\u064e\u0627 \u0631\u064e\u0627\u0653\u062f\u0651\u064e \u0644\u0650\u0641\u064e\u0636\u06e1\u0644\u0650\u0647\u0650\u06e6\u06da \u064a\u064f\u0635\u0650\u064a\u0628\u064f \u0628\u0650\u0647\u0650\u06e6 \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0645\u0650\u0646\u06e1 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650\u06e6\u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u063a\u064e\u0641\u064f\u0648\u0631\u064f \u0671\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",translation:"Dan jika Allah menimpakan suatu bencana kepadamu, maka tidak ada yang dapat menghilangkannya kecuali Dia. Dan jika Allah menghendaki kebaikan bagi kamu, maka tidak ada yang dapat menolak karunia-Nya. Dia memberikan kebaikan kepada siapa saja yang Dia kehendaki di antara hamba-hamba-Nya. Dia Maha Pengampun, Maha Penyayang"},{id:108,text:"\u0642\u064f\u0644\u06e1 \u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0642\u064e\u062f\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1\u06d6 \u0641\u064e\u0645\u064e\u0646\u0650 \u0671\u0647\u06e1\u062a\u064e\u062f\u064e\u0649\u0670 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0647\u06e1\u062a\u064e\u062f\u0650\u064a \u0644\u0650\u0646\u064e\u0641\u06e1\u0633\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u0645\u064e\u0646 \u0636\u064e\u0644\u0651\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0636\u0650\u0644\u0651\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627\u06d6 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u064e\u0627\u06e0 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645 \u0628\u0650\u0648\u064e\u0643\u0650\u064a\u0644\u0656",translation:"Katakanlah (Muhammad), \"Wahai manusia! Telah datang kepadamu kebenaran (Alquran) dari Tuhanmu, sebab itu barang siapa mendapat petunjuk, maka sebenarnya (petunjuk itu) untuk (kebaikan) dirinya sendiri. Dan barang siapa sesat, sesungguhnya kesesatannya itu (mencelakakan) dirinya sendiri. Dan Aku bukanlah pemelihara dirimu"},{id:109,text:"\u0648\u064e\u0671\u062a\u0651\u064e\u0628\u0650\u0639\u06e1 \u0645\u064e\u0627 \u064a\u064f\u0648\u062d\u064e\u0649\u0670\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0648\u064e\u0671\u0635\u06e1\u0628\u0650\u0631\u06e1 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u062d\u06e1\u0643\u064f\u0645\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06da \u0648\u064e\u0647\u064f\u0648\u064e \u062e\u064e\u064a\u06e1\u0631\u064f \u0671\u0644\u06e1\u062d\u064e\u0670\u0643\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dan ikutilah apa yang diwahyukan kepadamu, dan bersabarlah hingga Allah memberi keputusan. Dialah hakim yang terbaik"}]},{id:11,name:"\u0647\u0648\u062f",transliteration:"Hud",translation:"Hud",type:"meccan",total_verses:123,verses:[{id:1,text:"\u0627\u0644\u0653\u0631\u06da \u0643\u0650\u062a\u064e\u0670\u0628\u064c \u0623\u064f\u062d\u06e1\u0643\u0650\u0645\u064e\u062a\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u064f\u0647\u064f\u06e5 \u062b\u064f\u0645\u0651\u064e \u0641\u064f\u0635\u0651\u0650\u0644\u064e\u062a\u06e1 \u0645\u0650\u0646 \u0644\u0651\u064e\u062f\u064f\u0646\u06e1 \u062d\u064e\u0643\u0650\u064a\u0645\u064d \u062e\u064e\u0628\u0650\u064a\u0631\u064d",translation:"Alif l\u0101m R\u0101`. (Inilah) Kitab yang ayat-ayatnya disusun dengan rapi kemudian dijelaskan secara terperinci,393) (yang diturunkan) dari sisi (Allah) Yang Mahabijaksana, Mahateliti"},{id:2,text:"\u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064e\u06da \u0625\u0650\u0646\u0651\u064e\u0646\u0650\u064a \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f \u0646\u064e\u0630\u0650\u064a\u0631\u065e \u0648\u064e\u0628\u064e\u0634\u0650\u064a\u0631\u065e",translation:"agar kamu tidak menyembah selain Allah. Sesungguhnya aku (Muhammad) adalah pemberi peringatan dan pembawa berita gembira dari-Nya untukmu"},{id:3,text:"\u0648\u064e\u0623\u064e\u0646\u0650 \u0671\u0633\u06e1\u062a\u064e\u063a\u06e1\u0641\u0650\u0631\u064f\u0648\u0627\u0652 \u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u06e1 \u062b\u064f\u0645\u0651\u064e \u062a\u064f\u0648\u0628\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u064a\u064f\u0645\u064e\u062a\u0651\u0650\u0639\u06e1\u0643\u064f\u0645 \u0645\u0651\u064e\u062a\u064e\u0670\u0639\u064b\u0627 \u062d\u064e\u0633\u064e\u0646\u064b\u0627 \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u062c\u064e\u0644\u0656 \u0645\u0651\u064f\u0633\u064e\u0645\u0651\u0657\u0649 \u0648\u064e\u064a\u064f\u0624\u06e1\u062a\u0650 \u0643\u064f\u0644\u0651\u064e \u0630\u0650\u064a \u0641\u064e\u0636\u06e1\u0644\u0656 \u0641\u064e\u0636\u06e1\u0644\u064e\u0647\u064f\u06e5\u06d6 \u0648\u064e\u0625\u0650\u0646 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u06e1\u0627\u0652 \u0641\u064e\u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u064a\u064e\u0648\u06e1\u0645\u0656 \u0643\u064e\u0628\u0650\u064a\u0631\u064d",translation:"dan hendaklah kamu memohon ampunan kepada Tuhanmu dan bertobat kepada-Nya, niscaya Dia akan memberi kenikmatan yang baik kepadamu sampai waktu yang telah ditentukan. Dan Dia akan memberikan karunia-Nya kepada setiap orang yang berbuat baik. Dan jika kamu berpaling, maka sungguh, aku takut kamu akan ditimpa azab pada hari yang besar (Kiamat)"},{id:4,text:"\u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0631\u06e1\u062c\u0650\u0639\u064f\u0643\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0642\u064e\u062f\u0650\u064a\u0631\u064c",translation:"Kepada Allahlah kamu kembali. Dia Mahakuasa atas segala sesuatu"},{id:5,text:"\u0623\u064e\u0644\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u062b\u06e1\u0646\u064f\u0648\u0646\u064e \u0635\u064f\u062f\u064f\u0648\u0631\u064e\u0647\u064f\u0645\u06e1 \u0644\u0650\u064a\u064e\u0633\u06e1\u062a\u064e\u062e\u06e1\u0641\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1\u0647\u064f\u06da \u0623\u064e\u0644\u064e\u0627 \u062d\u0650\u064a\u0646\u064e \u064a\u064e\u0633\u06e1\u062a\u064e\u063a\u06e1\u0634\u064f\u0648\u0646\u064e \u062b\u0650\u064a\u064e\u0627\u0628\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u064a\u064f\u0633\u0650\u0631\u0651\u064f\u0648\u0646\u064e \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0639\u06e1\u0644\u0650\u0646\u064f\u0648\u0646\u064e\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0639\u064e\u0644\u0650\u064a\u0645\u064f\u06e2 \u0628\u0650\u0630\u064e\u0627\u062a\u0650 \u0671\u0644\u0635\u0651\u064f\u062f\u064f\u0648\u0631\u0650",translation:"Ingatlah, sesungguhnya mereka (orang-orang munafik) memalingkan dada untuk menyembunyikan diri dari dia (Muhammad).394) Ingatlah, ketika mereka menyelimuti dirinya dengan kain, Allah mengetahui apa yang mereka sembunyikan dan apa yang mereka nyatakan, sungguh, Allah Maha Mengetahui (segala) isi hati"},{id:6,text:"\u06de\u0648\u064e\u0645\u064e\u0627 \u0645\u0650\u0646 \u062f\u064e\u0627\u0653\u0628\u0651\u064e\u0629\u0656 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0631\u0650\u0632\u06e1\u0642\u064f\u0647\u064e\u0627 \u0648\u064e\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064f\u0633\u06e1\u062a\u064e\u0642\u064e\u0631\u0651\u064e\u0647\u064e\u0627 \u0648\u064e\u0645\u064f\u0633\u06e1\u062a\u064e\u0648\u06e1\u062f\u064e\u0639\u064e\u0647\u064e\u0627\u06da \u0643\u064f\u0644\u0651\u065e \u0641\u0650\u064a \u0643\u0650\u062a\u064e\u0670\u0628\u0656 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u0656",translation:"Dan tidak satu pun makhluk bergerak (bernyawa) di bumi melainkan semuanya dijamin Allah rezekinya. Dia mengetahui tempat kediamannya dan tempat penyimpanannya.395) Semua (tertulis) dalam Kitab yang nyata (Lau\u1e25 Ma\u1e25f\u016b\u1e93)"},{id:7,text:"\u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0641\u0650\u064a \u0633\u0650\u062a\u0651\u064e\u0629\u0650 \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u0656 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0631\u06e1\u0634\u064f\u0647\u064f\u06e5 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0645\u064e\u0627\u0653\u0621\u0650 \u0644\u0650\u064a\u064e\u0628\u06e1\u0644\u064f\u0648\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u064a\u0651\u064f\u0643\u064f\u0645\u06e1 \u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064f \u0639\u064e\u0645\u064e\u0644\u0657\u0627\u06d7 \u0648\u064e\u0644\u064e\u0626\u0650\u0646 \u0642\u064f\u0644\u06e1\u062a\u064e \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645 \u0645\u0651\u064e\u0628\u06e1\u0639\u064f\u0648\u062b\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u0650 \u0644\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064e\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u06e1 \u0647\u064e\u0670\u0630\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0633\u0650\u062d\u06e1\u0631\u065e \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u065e",translation:"Dan Dialah yang menciptakan langit dan bumi dalam enam masa, dan Arasy-Nya di atas air, agar Dia menguji siapakah diantara kamu yang lebih baik amalnya. Jika engkau berkata (kepada penduduk Mekkah), \"Sesungguhnya kamu akan dibangkitkan setelah mati,\" niscaya orang kafir itu akan berkata, \"Ini hanyalah sihir yang nyata"},{id:8,text:"\u0648\u064e\u0644\u064e\u0626\u0650\u0646\u06e1 \u0623\u064e\u062e\u0651\u064e\u0631\u06e1\u0646\u064e\u0627 \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064f\u0645\u0651\u064e\u0629\u0656 \u0645\u0651\u064e\u0639\u06e1\u062f\u064f\u0648\u062f\u064e\u0629\u0656 \u0644\u0651\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0646\u0651\u064e \u0645\u064e\u0627 \u064a\u064e\u062d\u06e1\u0628\u0650\u0633\u064f\u0647\u064f\u06e5\u0653\u06d7 \u0623\u064e\u0644\u064e\u0627 \u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u0647\u0650\u0645\u06e1 \u0644\u064e\u064a\u06e1\u0633\u064e \u0645\u064e\u0635\u06e1\u0631\u064f\u0648\u0641\u064b\u0627 \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0648\u064e\u062d\u064e\u0627\u0642\u064e \u0628\u0650\u0647\u0650\u0645 \u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6 \u064a\u064e\u0633\u06e1\u062a\u064e\u0647\u06e1\u0632\u0650\u0621\u064f\u0648\u0646\u064e",translation:"Dan sungguh, jika Kami tangguhkan azab terhadap mereka sampai waktu yang ditentukan, niscaya mereka akan berkata, \"Apakah yang menghalanginya?\" Ketahuilah, ketika azab itu datang kepada mereka, tidaklah dapat dielakkan oleh mereka. Mereka dikepung oleh (azab) yang dahulu mereka memperolok-olokkannya"},{id:9,text:"\u0648\u064e\u0644\u064e\u0626\u0650\u0646\u06e1 \u0623\u064e\u0630\u064e\u0642\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064e \u0645\u0650\u0646\u0651\u064e\u0627 \u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u0657 \u062b\u064f\u0645\u0651\u064e \u0646\u064e\u0632\u064e\u0639\u06e1\u0646\u064e\u0670\u0647\u064e\u0627 \u0645\u0650\u0646\u06e1\u0647\u064f \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u064a\u064e\u0640\u0654\u064f\u0648\u0633\u065e \u0643\u064e\u0641\u064f\u0648\u0631\u065e",translation:"Dan jika Kami berikan rahmat Kami kepada manusia, kemudian (rahmat itu) Kami cabut kembali, pastilah dia menjadi putus asa dan tidak berterima kasih"},{id:10,text:"\u0648\u064e\u0644\u064e\u0626\u0650\u0646\u06e1 \u0623\u064e\u0630\u064e\u0642\u06e1\u0646\u064e\u0670\u0647\u064f \u0646\u064e\u0639\u06e1\u0645\u064e\u0627\u0653\u0621\u064e \u0628\u064e\u0639\u06e1\u062f\u064e \u0636\u064e\u0631\u0651\u064e\u0627\u0653\u0621\u064e \u0645\u064e\u0633\u0651\u064e\u062a\u06e1\u0647\u064f \u0644\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064e\u0646\u0651\u064e \u0630\u064e\u0647\u064e\u0628\u064e \u0671\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0640\u0654\u064e\u0627\u062a\u064f \u0639\u064e\u0646\u0651\u0650\u064a\u0653\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0641\u064e\u0631\u0650\u062d\u065e \u0641\u064e\u062e\u064f\u0648\u0631\u064c",translation:"Dan jika Kami berikan kebahagiaan kepadanya setelah ditimpa bencana yang menimpanya, niscaya dia akan berkata, \"Telah hilang bencana itu dariku.\" Sesungguhnya dia (merasa) sangat gembira dan bangga"},{id:11,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0635\u064e\u0628\u064e\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u063a\u06e1\u0641\u0650\u0631\u064e\u0629\u065e \u0648\u064e\u0623\u064e\u062c\u06e1\u0631\u065e \u0643\u064e\u0628\u0650\u064a\u0631\u065e",translation:"Kecuali orang-orang yang sabar, dan mengerjakan kebajikan, mereka memperoleh ampunan dan pahala yang besar"},{id:12,text:"\u0641\u064e\u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064e \u062a\u064e\u0627\u0631\u0650\u0643\u064f\u06e2 \u0628\u064e\u0639\u06e1\u0636\u064e \u0645\u064e\u0627 \u064a\u064f\u0648\u062d\u064e\u0649\u0670\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0648\u064e\u0636\u064e\u0627\u0653\u0626\u0650\u0642\u064f\u06e2 \u0628\u0650\u0647\u0650\u06e6 \u0635\u064e\u062f\u06e1\u0631\u064f\u0643\u064e \u0623\u064e\u0646 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0648\u06e1\u0644\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0643\u064e\u0646\u0632\u064c \u0623\u064e\u0648\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e \u0645\u064e\u0639\u064e\u0647\u064f\u06e5 \u0645\u064e\u0644\u064e\u0643\u064c\u06da \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064e \u0646\u064e\u0630\u0650\u064a\u0631\u065e\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0648\u064e\u0643\u0650\u064a\u0644\u064c",translation:"Maka boleh jadi engkau (Muhammad) hendak meninggalkan sebagian dari apa yang diwahyukan kepadamu dan dadamu sempit karenanya, karena mereka akan mengatakan, \"Mengapa tidak diturunkan kepadanya harta (kekayaan) atau datang bersamanya malaikat?\" Sungguh, engkau hanyalah seorang pemberi peringatan dan Allah pemelihara segala sesuatu"},{id:13,text:"\u0623\u064e\u0645\u06e1 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0671\u0641\u06e1\u062a\u064e\u0631\u064e\u0649\u0670\u0647\u064f\u06d6 \u0642\u064f\u0644\u06e1 \u0641\u064e\u0623\u06e1\u062a\u064f\u0648\u0627\u0652 \u0628\u0650\u0639\u064e\u0634\u06e1\u0631\u0650 \u0633\u064f\u0648\u064e\u0631\u0656 \u0645\u0651\u0650\u062b\u06e1\u0644\u0650\u0647\u0650\u06e6 \u0645\u064f\u0641\u06e1\u062a\u064e\u0631\u064e\u064a\u064e\u0670\u062a\u0656 \u0648\u064e\u0671\u062f\u06e1\u0639\u064f\u0648\u0627\u0652 \u0645\u064e\u0646\u0650 \u0671\u0633\u06e1\u062a\u064e\u0637\u064e\u0639\u06e1\u062a\u064f\u0645 \u0645\u0651\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0635\u064e\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Bahkan mereka mengatakan, \"Dia (Muhammad) telah membuat-buat Alquran itu.\" Katakanlah, \"(Kalau demikian), datangkanlah sepuluh surah semisal dengannya (Alquran) yang dibuat-buat, dan ajaklah siapa saja di antara kamu yang sanggup selain Allah, jika kamu orang-orang yang benar"},{id:14,text:"\u0641\u064e\u0625\u0650\u0644\u0651\u064e\u0645\u06e1 \u064a\u064e\u0633\u06e1\u062a\u064e\u062c\u0650\u064a\u0628\u064f\u0648\u0627\u0652 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0641\u064e\u0671\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0628\u0650\u0639\u0650\u0644\u06e1\u0645\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0623\u064e\u0646 \u0644\u0651\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e\u06d6 \u0641\u064e\u0647\u064e\u0644\u06e1 \u0623\u064e\u0646\u062a\u064f\u0645 \u0645\u0651\u064f\u0633\u06e1\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Maka jika mereka tidak memenuhi tantanganmu, maka (katakanlah), \"Ketahuilah, bahwa (Alquran) itu diturunkan dengan ilmu Allah, dan bahwa tidak ada tuhan selain Dia, maka maukah kamu berserah diri (masuk Islam)"},{id:15,text:"\u0645\u064e\u0646 \u0643\u064e\u0627\u0646\u064e \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u064e \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0648\u064e\u0632\u0650\u064a\u0646\u064e\u062a\u064e\u0647\u064e\u0627 \u0646\u064f\u0648\u064e\u0641\u0651\u0650 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0623\u064e\u0639\u06e1\u0645\u064e\u0670\u0644\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u0644\u064e\u0627 \u064a\u064f\u0628\u06e1\u062e\u064e\u0633\u064f\u0648\u0646\u064e",translation:"Barang siapa menghendaki kehidupan dunia dan perhiasannya, pasti Kami berikan (balasan) penuh atas pekerjaan mereka di dunia (dengan sempurna) dan mereka di dunia tidak akan dirugikan"},{id:16,text:"\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u064a\u06e1\u0633\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u064f\u06d6 \u0648\u064e\u062d\u064e\u0628\u0650\u0637\u064e \u0645\u064e\u0627 \u0635\u064e\u0646\u064e\u0639\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0628\u064e\u0670\u0637\u0650\u0644\u065e \u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Itulah orang-orang yang tidak memperoleh (sesuatu) di akhirat kecuali neraka, dan sia-sialah di sana apa yang telah mereka usahakan (di dunia) dan terhapuslah apa yang telah mereka kerjakan"},{id:17,text:"\u0623\u064e\u0641\u064e\u0645\u064e\u0646 \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0629\u0656 \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0647\u0650\u06e6 \u0648\u064e\u064a\u064e\u062a\u06e1\u0644\u064f\u0648\u0647\u064f \u0634\u064e\u0627\u0647\u0650\u062f\u065e \u0645\u0651\u0650\u0646\u06e1\u0647\u064f \u0648\u064e\u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u06e6 \u0643\u0650\u062a\u064e\u0670\u0628\u064f \u0645\u064f\u0648\u0633\u064e\u0649\u0670\u0653 \u0625\u0650\u0645\u064e\u0627\u0645\u0657\u0627 \u0648\u064e\u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u064b\u06da \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u0650\u06e6\u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0643\u06e1\u0641\u064f\u0631\u06e1 \u0628\u0650\u0647\u0650\u06e6 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u062d\u06e1\u0632\u064e\u0627\u0628\u0650 \u0641\u064e\u0671\u0644\u0646\u0651\u064e\u0627\u0631\u064f \u0645\u064e\u0648\u06e1\u0639\u0650\u062f\u064f\u0647\u064f\u06e5\u06da \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f \u0641\u0650\u064a \u0645\u0650\u0631\u06e1\u064a\u064e\u0629\u0656 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064e \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Maka apakah (orang-orang kafir itu sama dengan) orang yang sudah mempunyai bukti yang nyata (Alquran) dari Tuhannya, dan diikuti oleh saksi396) dari-Nya dan sebelumnya sudah ada pula Kitab Musa yang menjadi pedoman dan rahmat? Mereka beriman kepadanya (Alquran). Barang siapa mengingkarinya (Alquran) di antara kelompok-kelompok (orang Quraisy), maka nerakalah tempat yang diancamkan baginya, karena itu janganlah engkau ragu terhadap Alquran. Sungguh, Alquran itu benar-benar dari Tuhanmu, tetapi kebanyakan manusia tidak beriman"},{id:18,text:"\u0648\u064e\u0645\u064e\u0646\u06e1 \u0623\u064e\u0638\u06e1\u0644\u064e\u0645\u064f \u0645\u0650\u0645\u0651\u064e\u0646\u0650 \u0671\u0641\u06e1\u062a\u064e\u0631\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u0630\u0650\u0628\u064b\u0627\u06da \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u064a\u064f\u0639\u06e1\u0631\u064e\u0636\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0671\u0644\u06e1\u0623\u064e\u0634\u06e1\u0647\u064e\u0670\u062f\u064f \u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u064e\u0628\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1\u06da \u0623\u064e\u0644\u064e\u0627 \u0644\u064e\u0639\u06e1\u0646\u064e\u0629\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"(Dan siapakah yang lebih zalim daripada orang yang mengada-adakan suatu kebohongan terhadap Allah? Mereka itu akan dihadapkan kepada Tuhan mereka, dan para saksi397) akan berkata, \"Orang-orang inilah yang telah berbohong terhadap Tuhan mereka.\" Ingatlah, laknat Allah (ditimpakan) kepada orang yang zalim"},{id:19,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0635\u064f\u062f\u0651\u064f\u0648\u0646\u064e \u0639\u064e\u0646 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u064a\u064e\u0628\u06e1\u063a\u064f\u0648\u0646\u064e\u0647\u064e\u0627 \u0639\u0650\u0648\u064e\u062c\u0657\u0627 \u0648\u064e\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0647\u064f\u0645\u06e1 \u0643\u064e\u0670\u0641\u0650\u0631\u064f\u0648\u0646\u064e",translation:"(yaitu) mereka yang menghalangi dari jalan Allah dan menghendaki agar jalan itu bengkok.398) Dan mereka itulah orang yang tidak percaya adanya hari akhirat"},{id:20,text:"\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0644\u064e\u0645\u06e1 \u064a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u0645\u064f\u0639\u06e1\u062c\u0650\u0632\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646\u06e1 \u0623\u064e\u0648\u06e1\u0644\u0650\u064a\u064e\u0627\u0653\u0621\u064e\u06d8 \u064a\u064f\u0636\u064e\u0670\u0639\u064e\u0641\u064f \u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064f\u06da \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0633\u06e1\u062a\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u06e1\u0639\u064e \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064f\u0628\u06e1\u0635\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Mereka tidak mampu menghalangi (siksaan Allah) di bumi, dan tidak akan ada bagi mereka penolong selain Allah. Azab itu dilipatgandakan kepada mereka. Mereka tidak mampu mendengar (kebenaran) dan tidak dapat melihat(nya)"},{id:21,text:"\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062e\u064e\u0633\u0650\u0631\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0636\u064e\u0644\u0651\u064e \u0639\u064e\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0641\u06e1\u062a\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Mereka itulah orang yang merugikan dirinya sendiri, dan lenyaplah dari mereka apa yang selalu mereka ada-adakan"},{id:22,text:"\u0644\u064e\u0627 \u062c\u064e\u0631\u064e\u0645\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u062e\u06e1\u0633\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Pasti mereka itu (menjadi) orang yang paling rugi di akhirat"},{id:23,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0648\u064e\u0623\u064e\u062e\u06e1\u0628\u064e\u062a\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u0650\u06d6 \u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u0670\u0644\u0650\u062f\u064f\u0648\u0646\u064e",translation:"Sesungguhnya orang-orang yang beriman dan mengerjakan kebajikan dan merendahkan diri kepada Tuhan, mereka itu penghuni surga, mereka kekal di dalamnya"},{id:24,text:"\u06de\u0645\u064e\u062b\u064e\u0644\u064f \u0671\u0644\u06e1\u0641\u064e\u0631\u0650\u064a\u0642\u064e\u064a\u06e1\u0646\u0650 \u0643\u064e\u0671\u0644\u06e1\u0623\u064e\u0639\u06e1\u0645\u064e\u0649\u0670 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0635\u064e\u0645\u0651\u0650 \u0648\u064e\u0671\u0644\u06e1\u0628\u064e\u0635\u0650\u064a\u0631\u0650 \u0648\u064e\u0671\u0644\u0633\u0651\u064e\u0645\u0650\u064a\u0639\u0650\u06da \u0647\u064e\u0644\u06e1 \u064a\u064e\u0633\u06e1\u062a\u064e\u0648\u0650\u064a\u064e\u0627\u0646\u0650 \u0645\u064e\u062b\u064e\u0644\u064b\u0627\u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Perumpamaan kedua golongan (orang kafir dan mukmin), seperti orang buta dan tuli dengan orang yang dapat melihat dan dapat mendengar. Samakah kedua golongan itu? Maka tidakkah kamu mengambil pelajaran"},{id:25,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0646\u064f\u0648\u062d\u064b\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0643\u064f\u0645\u06e1 \u0646\u064e\u0630\u0650\u064a\u0631\u065e \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u064c",translation:"Dan sungguh, Kami telah mengutus Nuh kepada kaumnya, (dia berkata), \"Sungguh, aku ini adalah pemberi peringatan yang nyata bagi kamu"},{id:26,text:"\u0623\u064e\u0646 \u0644\u0651\u064e\u0627 \u062a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064e\u06d6 \u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u064a\u064e\u0648\u06e1\u0645\u064d \u0623\u064e\u0644\u0650\u064a\u0645\u0656",translation:"agar kamu tidak menyembah selain Allah. Aku benar-benar khawatir kamu akan ditimpa azab (pada) hari yang sangat pedih"},{id:27,text:"\u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0623\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u06e6 \u0645\u064e\u0627 \u0646\u064e\u0631\u064e\u0649\u0670\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u064e\u0634\u064e\u0631\u0657\u0627 \u0645\u0651\u0650\u062b\u06e1\u0644\u064e\u0646\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u0646\u064e\u0631\u064e\u0649\u0670\u0643\u064e \u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064e\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645\u06e1 \u0623\u064e\u0631\u064e\u0627\u0630\u0650\u0644\u064f\u0646\u064e\u0627 \u0628\u064e\u0627\u062f\u0650\u064a\u064e \u0671\u0644\u0631\u0651\u064e\u0623\u06e1\u064a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0646\u064e\u0631\u064e\u0649\u0670 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646 \u0641\u064e\u0636\u06e1\u0644\u0650\u06ed \u0628\u064e\u0644\u06e1 \u0646\u064e\u0638\u064f\u0646\u0651\u064f\u0643\u064f\u0645\u06e1 \u0643\u064e\u0670\u0630\u0650\u0628\u0650\u064a\u0646\u064e",translation:"Maka berkatalah para pemuka yang kafir dari kaumnya, \"Kami tidak melihat engkau, melainkan hanyalah seorang manusia (biasa) seperti kami, dan kami tidak melihat orang yang mengikuti engkau, melainkan orang yang hina dina di antara kami yang lekas percaya. Kami tidak melihat kalian memiliki suatu kelebihan apa pun atas kami, bahkan kami menganggap kalian adalah para pendusta"},{id:28,text:"\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0623\u064e\u0631\u064e\u0621\u064e\u064a\u06e1\u062a\u064f\u0645\u06e1 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0629\u0656 \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u0621\u064e\u0627\u062a\u064e\u0649\u0670\u0646\u0650\u064a \u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u0657 \u0645\u0651\u0650\u0646\u06e1 \u0639\u0650\u0646\u062f\u0650\u0647\u0650\u06e6 \u0641\u064e\u0639\u064f\u0645\u0651\u0650\u064a\u064e\u062a\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0623\u064e\u0646\u064f\u0644\u06e1\u0632\u0650\u0645\u064f\u0643\u064f\u0645\u064f\u0648\u0647\u064e\u0627 \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0644\u064e\u0647\u064e\u0627 \u0643\u064e\u0670\u0631\u0650\u0647\u064f\u0648\u0646\u064e",translation:"Dia (Nuh) berkata, \"Wahai kaumku! Apa pendapatmu jika aku mempunyai bukti yang nyata dari Tuhanku, dan aku diberi rahmat dari sisi-Nya, sedangkan (rahmat itu) disamarkan bagimu. Apa kami akan memaksa kamu untuk menerimanya, padahal kamu tidak menyukainya"},{id:29,text:"\u0648\u064e\u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0644\u064e\u0627\u0653 \u0623\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0643\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0645\u064e\u0627\u0644\u064b\u0627\u06d6 \u0625\u0650\u0646\u06e1 \u0623\u064e\u062c\u06e1\u0631\u0650\u064a\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u064e\u0627\u06e0 \u0628\u0650\u0637\u064e\u0627\u0631\u0650\u062f\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0653\u0627\u0652\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645 \u0645\u0651\u064f\u0644\u064e\u0670\u0642\u064f\u0648\u0627\u0652 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064e\u0631\u064e\u0649\u0670\u0643\u064f\u0645\u06e1 \u0642\u064e\u0648\u06e1\u0645\u0657\u0627 \u062a\u064e\u062c\u06e1\u0647\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan wahai kaumku! Aku tidak meminta harta kepada kamu (sebagai imbalan) atas seruanku. Imbalanku hanyalah dari Allah dan aku sekali-kali tidak akan mengusir orang yang telah beriman. Sungguh, mereka akan bertemu dengan Tuhannya, dan sebaliknya aku memandangmu sebagai kaum yang bodoh"},{id:30,text:"\u0648\u064e\u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0645\u064e\u0646 \u064a\u064e\u0646\u0635\u064f\u0631\u064f\u0646\u0650\u064a \u0645\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0646 \u0637\u064e\u0631\u064e\u062f\u062a\u0651\u064f\u0647\u064f\u0645\u06e1\u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan wahai kaumku! Siapakah yang akan menolongku dari (azab) Allah jika aku mengusir mereka? Tidakkah kamu mengambil pelajaran"},{id:31,text:"\u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064e\u0642\u064f\u0648\u0644\u064f \u0644\u064e\u0643\u064f\u0645\u06e1 \u0639\u0650\u0646\u062f\u0650\u064a \u062e\u064e\u0632\u064e\u0627\u0653\u0626\u0650\u0646\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u0628\u064e \u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064e\u0642\u064f\u0648\u0644\u064f \u0625\u0650\u0646\u0651\u0650\u064a \u0645\u064e\u0644\u064e\u0643\u065e \u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064e\u0642\u064f\u0648\u0644\u064f \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u0632\u06e1\u062f\u064e\u0631\u0650\u064a\u0653 \u0623\u064e\u0639\u06e1\u064a\u064f\u0646\u064f\u0643\u064f\u0645\u06e1 \u0644\u064e\u0646 \u064a\u064f\u0624\u06e1\u062a\u0650\u064a\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u062e\u064e\u064a\u06e1\u0631\u064b\u0627\u06d6 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u0641\u0650\u064a\u0653 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u06e1 \u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0625\u0650\u0630\u0657\u0627 \u0644\u0651\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dan aku tidak mengatakan kepadamu, bahwa aku mempunyai gudang-gudang rezeki dan kekayaan dari Allah, dan aku tidak mengetahui yang gaib, dan tidak (pula) mengatakan bahwa sesungguhnya aku adalah malaikat, dan aku tidak (juga) mengatakan kepada orang yang dipandang hina oleh penglihatanmu, \"Bahwa Allah tidak akan memberikan kebaikan kepada mereka. Allah lebih mengetahui apa yang ada pada diri mereka. Sungguh, jika demikian aku benar-benar termasuk orang-orang yang zalim"},{id:32,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u064a\u064e\u0670\u0646\u064f\u0648\u062d\u064f \u0642\u064e\u062f\u06e1 \u062c\u064e\u0670\u062f\u064e\u0644\u06e1\u062a\u064e\u0646\u064e\u0627 \u0641\u064e\u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u06e1\u062a\u064e \u062c\u0650\u062f\u064e\u0670\u0644\u064e\u0646\u064e\u0627 \u0641\u064e\u0623\u06e1\u062a\u0650\u0646\u064e\u0627 \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0650\u062f\u064f\u0646\u064e\u0627\u0653 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Mereka berkata, \"Wahai Nuh! Sungguh, engkau telah berbantah dengan kami, dan engkau telah memperpanjang bantahanmu terhadap kami, maka datangkanlah kepada kami azab yang engkau ancamkan, jika kamu termasuk orang yang benar"},{id:33,text:"\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u0643\u064f\u0645 \u0628\u0650\u0647\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0625\u0650\u0646 \u0634\u064e\u0627\u0653\u0621\u064e \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064f\u0645 \u0628\u0650\u0645\u064f\u0639\u06e1\u062c\u0650\u0632\u0650\u064a\u0646\u064e",translation:"Dia (Nuh) menjawab, \"Hanya Allah yang akan mendatangkan azab kepadamu jika Dia menghendaki, dan kamu tidak akan dapat melepaskan diri"},{id:34,text:"\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0646\u0641\u064e\u0639\u064f\u0643\u064f\u0645\u06e1 \u0646\u064f\u0635\u06e1\u062d\u0650\u064a\u0653 \u0625\u0650\u0646\u06e1 \u0623\u064e\u0631\u064e\u062f\u062a\u0651\u064f \u0623\u064e\u0646\u06e1 \u0623\u064e\u0646\u0635\u064e\u062d\u064e \u0644\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0623\u064e\u0646 \u064a\u064f\u063a\u06e1\u0648\u0650\u064a\u064e\u0643\u064f\u0645\u06e1\u06da \u0647\u064f\u0648\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u06e1 \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u062a\u064f\u0631\u06e1\u062c\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Dan nasihatku tidak akan bermanfaat bagimu sekalipun aku ingin memberi nasihat kepadamu, kalau Allah hendak menyesatkan kamu. Dia adalah Tuhanmu, dan kepada-Nyalah kamu dikembalikan"},{id:35,text:"\u0623\u064e\u0645\u06e1 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0671\u0641\u06e1\u062a\u064e\u0631\u064e\u0649\u0670\u0647\u064f\u06d6 \u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0650 \u0671\u0641\u06e1\u062a\u064e\u0631\u064e\u064a\u06e1\u062a\u064f\u0647\u064f\u06e5 \u0641\u064e\u0639\u064e\u0644\u064e\u064a\u0651\u064e \u0625\u0650\u062c\u06e1\u0631\u064e\u0627\u0645\u0650\u064a \u0648\u064e\u0623\u064e\u0646\u064e\u0627\u06e0 \u0628\u064e\u0631\u0650\u064a\u0653\u0621\u065e \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u062a\u064f\u062c\u06e1\u0631\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Bahkan mereka (orang kafir) berkata, \"Dia cuma mengada-ada saja.\" Katakanlah (Muhammad), \"Jika aku mengada-ada, akulah yang akan memikul dosanya, dan aku bebas dari dosa yang kamu perbuat"},{id:36,text:"\u0648\u064e\u0623\u064f\u0648\u062d\u0650\u064a\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0646\u064f\u0648\u062d\u064d \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0646 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0648\u06e1\u0645\u0650\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646 \u0642\u064e\u062f\u06e1 \u0621\u064e\u0627\u0645\u064e\u0646\u064e \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0628\u06e1\u062a\u064e\u0626\u0650\u0633\u06e1 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0641\u06e1\u0639\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan diwahyukan kepadanya (Nuh), \"Ketahuilah, tidak akan beriman di antara kaummu, kecuali orang yang benar-benar beriman (saja), karena itu janganlah engkau bersedih hati tentang apa yang mereka perbuat"},{id:37,text:"\u0648\u064e\u0671\u0635\u06e1\u0646\u064e\u0639\u0650 \u0671\u0644\u06e1\u0641\u064f\u0644\u06e1\u0643\u064e \u0628\u0650\u0623\u064e\u0639\u06e1\u064a\u064f\u0646\u0650\u0646\u064e\u0627 \u0648\u064e\u0648\u064e\u062d\u06e1\u064a\u0650\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u062e\u064e\u0670\u0637\u0650\u0628\u06e1\u0646\u0650\u064a \u0641\u0650\u064a \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645 \u0645\u0651\u064f\u063a\u06e1\u0631\u064e\u0642\u064f\u0648\u0646\u064e",translation:"Dan buatlah kapal itu dengan pengawasan dan petunjuk wahyu Kami, dan janganlah engkau bicara dengan Aku tentang orang-orang yang zalim. Sesungguhnya mereka itu akan ditenggelamkan"},{id:38,text:"\u0648\u064e\u064a\u064e\u0635\u06e1\u0646\u064e\u0639\u064f \u0671\u0644\u06e1\u0641\u064f\u0644\u06e1\u0643\u064e \u0648\u064e\u0643\u064f\u0644\u0651\u064e\u0645\u064e\u0627 \u0645\u064e\u0631\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0645\u064e\u0644\u064e\u0623\u065e \u0645\u0651\u0650\u0646 \u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u06e6 \u0633\u064e\u062e\u0650\u0631\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1\u0647\u064f\u06da \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646 \u062a\u064e\u0633\u06e1\u062e\u064e\u0631\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u0651\u064e\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0646\u064e\u0633\u06e1\u062e\u064e\u0631\u064f \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u0643\u064e\u0645\u064e\u0627 \u062a\u064e\u0633\u06e1\u062e\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan mulailah dia (Nuh) membuat kapal. Setiap kali pemimpin kaumnya berjalan melewatinya, mereka mengejeknya. Dia (Nuh) berkata, \"Jika kamu mengejek kami, maka kami (pun) akan mengejekmu sebagaimana kamu mengejek (kami)"},{id:39,text:"\u0641\u064e\u0633\u064e\u0648\u06e1\u0641\u064e \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0645\u064e\u0646 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u0647\u0650 \u0639\u064e\u0630\u064e\u0627\u0628\u065e \u064a\u064f\u062e\u06e1\u0632\u0650\u064a\u0647\u0650 \u0648\u064e\u064a\u064e\u062d\u0650\u0644\u0651\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0639\u064e\u0630\u064e\u0627\u0628\u065e \u0645\u0651\u064f\u0642\u0650\u064a\u0645\u064c",translation:"Maka kelak kamu akan mengetahui siapa yang akan ditimpa azab yang menghinakan dan (siapa) yang akan ditimpa azab yang kekal"},{id:40,text:"\u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e \u0623\u064e\u0645\u06e1\u0631\u064f\u0646\u064e\u0627 \u0648\u064e\u0641\u064e\u0627\u0631\u064e \u0671\u0644\u062a\u0651\u064e\u0646\u0651\u064f\u0648\u0631\u064f \u0642\u064f\u0644\u06e1\u0646\u064e\u0627 \u0671\u062d\u06e1\u0645\u0650\u0644\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u0650\u0646 \u0643\u064f\u0644\u0651\u0656 \u0632\u064e\u0648\u06e1\u062c\u064e\u064a\u06e1\u0646\u0650 \u0671\u062b\u06e1\u0646\u064e\u064a\u06e1\u0646\u0650 \u0648\u064e\u0623\u064e\u0647\u06e1\u0644\u064e\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646 \u0633\u064e\u0628\u064e\u0642\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0644\u064f \u0648\u064e\u0645\u064e\u0646\u06e1 \u0621\u064e\u0627\u0645\u064e\u0646\u064e\u06da \u0648\u064e\u0645\u064e\u0627\u0653 \u0621\u064e\u0627\u0645\u064e\u0646\u064e \u0645\u064e\u0639\u064e\u0647\u064f\u06e5\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u065e",translation:"Hingga apabila perintah Kami datang dan tanur (dapur) telah memancarkan air, Kami berfirman, \"Muatkanlah ke dalamnya (kapal itu) dari masing-masing (hewan) sepasang (jantan dan betina), dan (juga) keluargamu kecuali orang yang telah terkena ketetapan terdahulu dan (muatkan pula) orang yang beriman.\" Ternyata orang-orang beriman yang bersama dengan Nuh hanya sedikit"},{id:41,text:"\u06de\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0631\u06e1\u0643\u064e\u0628\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0628\u0650\u0633\u06e1\u0645\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u062c\u06e1\u0631\u065c\u0649\u0670\u0647\u064e\u0627 \u0648\u064e\u0645\u064f\u0631\u06e1\u0633\u064e\u0649\u0670\u0647\u064e\u0627\u0653\u06da \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0644\u064e\u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u065e",translation:"Dan dia berkata, \"Naiklah kamu semua ke dalamnya (kapal) dengan (menyebut) nama Allah pada waktu berlayar dan berlabuhnya. Sesungguhnya Tuhanku Maha Pengampun, Maha Penyayang"},{id:42,text:"\u0648\u064e\u0647\u0650\u064a\u064e \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0628\u0650\u0647\u0650\u0645\u06e1 \u0641\u0650\u064a \u0645\u064e\u0648\u06e1\u062c\u0656 \u0643\u064e\u0671\u0644\u06e1\u062c\u0650\u0628\u064e\u0627\u0644\u0650 \u0648\u064e\u0646\u064e\u0627\u062f\u064e\u0649\u0670 \u0646\u064f\u0648\u062d\u064c \u0671\u0628\u06e1\u0646\u064e\u0647\u064f\u06e5 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0641\u0650\u064a \u0645\u064e\u0639\u06e1\u0632\u0650\u0644\u0656 \u064a\u064e\u0670\u0628\u064f\u0646\u064e\u064a\u0651\u064e \u0671\u0631\u06e1\u0643\u064e\u0628 \u0645\u0651\u064e\u0639\u064e\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0646 \u0645\u0651\u064e\u0639\u064e \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"(Dan kapal itu berlayar membawa mereka ke dalam gelombang laksana gunung-gunung. Dan Nuh memanggil anaknya,399) ketika dia (anak itu) berada di tempat yang jauh terpencil, \"Wahai anakku! Naiklah (ke kapal) bersama kami dan janganlah engkau bersama orang-orang kafir"},{id:43,text:"\u0642\u064e\u0627\u0644\u064e \u0633\u064e\u0640\u0654\u064e\u0627\u0648\u0650\u064a\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u062c\u064e\u0628\u064e\u0644\u0656 \u064a\u064e\u0639\u06e1\u0635\u0650\u0645\u064f\u0646\u0650\u064a \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064e\u0627\u0653\u0621\u0650\u06da \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0627 \u0639\u064e\u0627\u0635\u0650\u0645\u064e \u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e \u0645\u0650\u0646\u06e1 \u0623\u064e\u0645\u06e1\u0631\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646 \u0631\u0651\u064e\u062d\u0650\u0645\u064e\u06da \u0648\u064e\u062d\u064e\u0627\u0644\u064e \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062c\u064f \u0641\u064e\u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u063a\u06e1\u0631\u064e\u0642\u0650\u064a\u0646\u064e",translation:"Dia (anaknya) menjawab, \"Aku akan mencari perlindungan ke gunung yang dapat menghindarkan aku dari air bah!\" (Nuh) berkata, \"Tidak ada yang melindungi dari siksaan Allah pada hari ini selain Allah yang Maha Penyayang.\" Dan gelombang menjadi penghalang antara keduanya; maka dia (anak itu) termasuk orang yang ditenggelamkan"},{id:44,text:"\u0648\u064e\u0642\u0650\u064a\u0644\u064e \u064a\u064e\u0640\u0670\u0653\u0623\u064e\u0631\u06e1\u0636\u064f \u0671\u0628\u06e1\u0644\u064e\u0639\u0650\u064a \u0645\u064e\u0627\u0653\u0621\u064e\u0643\u0650 \u0648\u064e\u064a\u064e\u0670\u0633\u064e\u0645\u064e\u0627\u0653\u0621\u064f \u0623\u064e\u0642\u06e1\u0644\u0650\u0639\u0650\u064a \u0648\u064e\u063a\u0650\u064a\u0636\u064e \u0671\u0644\u06e1\u0645\u064e\u0627\u0653\u0621\u064f \u0648\u064e\u0642\u064f\u0636\u0650\u064a\u064e \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0631\u064f \u0648\u064e\u0671\u0633\u06e1\u062a\u064e\u0648\u064e\u062a\u06e1 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u062c\u064f\u0648\u062f\u0650\u064a\u0651\u0650\u06d6 \u0648\u064e\u0642\u0650\u064a\u0644\u064e \u0628\u064f\u0639\u06e1\u062f\u0657\u0627 \u0644\u0651\u0650\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dan difirmankan, \"Wahai bumi! Telanlah airmu dan wahai langit (hujan!) berhentilah.\" Dan air pun disurutkan, dan perintah pun diselesaikan,400) dan kapal itu pun berlabuh di atas gunung Judi,401) dan dikatakan, \"binasalah orang-orang zalim"},{id:45,text:"\u0648\u064e\u0646\u064e\u0627\u062f\u064e\u0649\u0670 \u0646\u064f\u0648\u062d\u065e \u0631\u0651\u064e\u0628\u0651\u064e\u0647\u064f\u06e5 \u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0625\u0650\u0646\u0651\u064e \u0671\u0628\u06e1\u0646\u0650\u064a \u0645\u0650\u0646\u06e1 \u0623\u064e\u0647\u06e1\u0644\u0650\u064a \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0648\u064e\u0639\u06e1\u062f\u064e\u0643\u064e \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f \u0648\u064e\u0623\u064e\u0646\u062a\u064e \u0623\u064e\u062d\u06e1\u0643\u064e\u0645\u064f \u0671\u0644\u06e1\u062d\u064e\u0670\u0643\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dan Nuh memohon kepada Tuhannya sambil berkata, \"Ya Tuhanku, sesungguhnya anakku adalah termasuk keluargaku, dan janji-Mu itu pasti benar. Engkau adalah hakim yang paling adil"},{id:46,text:"\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0670\u0646\u064f\u0648\u062d\u064f \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u064a\u06e1\u0633\u064e \u0645\u0650\u0646\u06e1 \u0623\u064e\u0647\u06e1\u0644\u0650\u0643\u064e\u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0639\u064e\u0645\u064e\u0644\u064c \u063a\u064e\u064a\u06e1\u0631\u064f \u0635\u064e\u0670\u0644\u0650\u062d\u0656\u06d6 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u06e1\u0646\u0650 \u0645\u064e\u0627 \u0644\u064e\u064a\u06e1\u0633\u064e \u0644\u064e\u0643\u064e \u0628\u0650\u0647\u0650\u06e6 \u0639\u0650\u0644\u06e1\u0645\u064c\u06d6 \u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064e\u0639\u0650\u0638\u064f\u0643\u064e \u0623\u064e\u0646 \u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u062c\u064e\u0670\u0647\u0650\u0644\u0650\u064a\u0646\u064e",translation:"Dia (Allah) berfirman, \"Wahai Nuh! Sesungguhnya dia bukanlah termasuk keluargamu, karena perbuatannya sungguh tidak baik, sebab itu jangan engkau memohon kepada-Ku sesuatu yang tidak engkau ketahui (hakikatnya). Aku menasihatimu agar (engkau) tidak termasuk orang yang bodoh"},{id:47,text:"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0643\u064e \u0623\u064e\u0646\u06e1 \u0623\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064e\u0643\u064e \u0645\u064e\u0627 \u0644\u064e\u064a\u06e1\u0633\u064e \u0644\u0650\u064a \u0628\u0650\u0647\u0650\u06e6 \u0639\u0650\u0644\u06e1\u0645\u065e\u06d6 \u0648\u064e\u0625\u0650\u0644\u0651\u064e\u0627 \u062a\u064e\u063a\u06e1\u0641\u0650\u0631\u06e1 \u0644\u0650\u064a \u0648\u064e\u062a\u064e\u0631\u06e1\u062d\u064e\u0645\u06e1\u0646\u0650\u064a\u0653 \u0623\u064e\u0643\u064f\u0646 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u062e\u064e\u0670\u0633\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dia (Nuh) berkata, \"Ya Tuhanku, sesungguhnya aku berlindung kepada-Mu untuk memohon kepada-Mu sesuatu yang aku tidak mengetahui (hakikatnya). Kalau Engkau tidak mengampuniku, dan (tidak) menaruh belas kasihan kepadaku, niscaya aku termasuk orang yang rugi"},{id:48,text:"\u0642\u0650\u064a\u0644\u064e \u064a\u064e\u0670\u0646\u064f\u0648\u062d\u064f \u0671\u0647\u06e1\u0628\u0650\u0637\u06e1 \u0628\u0650\u0633\u064e\u0644\u064e\u0670\u0645\u0656 \u0645\u0651\u0650\u0646\u0651\u064e\u0627 \u0648\u064e\u0628\u064e\u0631\u064e\u0643\u064e\u0670\u062a\u064d \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0648\u064e\u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064f\u0645\u064e\u0645\u0656 \u0645\u0651\u0650\u0645\u0651\u064e\u0646 \u0645\u0651\u064e\u0639\u064e\u0643\u064e\u06da \u0648\u064e\u0623\u064f\u0645\u064e\u0645\u065e \u0633\u064e\u0646\u064f\u0645\u064e\u062a\u0651\u0650\u0639\u064f\u0647\u064f\u0645\u06e1 \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u0645\u064e\u0633\u0651\u064f\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u0651\u064e\u0627 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Difirmankan, \"Wahai Nuh! Turunlah dengan selamat sejahtera dan penuh keberkahan dari Kami, bagimu dan bagi semua umat (mukmin) yang bersamamu. Dan ada umat-umat yang Kami beri kesenangan (dalam kehidupan dunia), kemudian mereka akan ditimpa azab Kami yang pedih"},{id:49,text:"\u062a\u0650\u0644\u06e1\u0643\u064e \u0645\u0650\u0646\u06e1 \u0623\u064e\u0646\u06e2\u0628\u064e\u0627\u0653\u0621\u0650 \u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u0628\u0650 \u0646\u064f\u0648\u062d\u0650\u064a\u0647\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e\u06d6 \u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064e \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0647\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064e \u0648\u064e\u0644\u064e\u0627 \u0642\u064e\u0648\u06e1\u0645\u064f\u0643\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650 \u0647\u064e\u0670\u0630\u064e\u0627\u06d6 \u0641\u064e\u0671\u0635\u06e1\u0628\u0650\u0631\u06e1\u06d6 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0639\u064e\u0670\u0642\u0650\u0628\u064e\u0629\u064e \u0644\u0650\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",translation:"Itulah sebagian dari berita-berita gaib yang Kami wahyukan kepadamu (Muhammad); tidak pernah engkau mengetahuinya dan tidak (pula) kaummu sebelum ini. Maka bersabarlah, sungguh, kesudahan (yang baik) adalah bagi orang yang bertakwa"},{id:50,text:"\u0648\u064e\u0625\u0650\u0644\u064e\u0649\u0670 \u0639\u064e\u0627\u062f\u064d \u0623\u064e\u062e\u064e\u0627\u0647\u064f\u0645\u06e1 \u0647\u064f\u0648\u062f\u0657\u0627\u06da \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0625\u0650\u0644\u064e\u0670\u0647\u064d \u063a\u064e\u064a\u06e1\u0631\u064f\u0647\u064f\u06e5\u0653\u06d6 \u0625\u0650\u0646\u06e1 \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064f\u0641\u06e1\u062a\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan kepada kaum '\u0100d (Kami utus) saudara mereka, Hud. Dia berkata, \"Wahai kaumku! Sembahlah Allah, tidak ada tuhan bagimu selain Dia. (selama ini) kamu hanyalah mengada-ada"},{id:51,text:"\u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0644\u064e\u0627\u0653 \u0623\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0643\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0623\u064e\u062c\u06e1\u0631\u064b\u0627\u06d6 \u0625\u0650\u0646\u06e1 \u0623\u064e\u062c\u06e1\u0631\u0650\u064a\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0641\u064e\u0637\u064e\u0631\u064e\u0646\u0650\u064a\u0653\u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Wahai kaumku! Aku tidak meminta imbalan kepadamu atas (seruanku) ini. Imbalanku hanyalah dari Allah yang telah menciptakanku. Tidakkah kamu mengerti"},{id:52,text:"\u0648\u064e\u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u0633\u06e1\u062a\u064e\u063a\u06e1\u0641\u0650\u0631\u064f\u0648\u0627\u0652 \u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u06e1 \u062b\u064f\u0645\u0651\u064e \u062a\u064f\u0648\u0628\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u064a\u064f\u0631\u06e1\u0633\u0650\u0644\u0650 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645 \u0645\u0651\u0650\u062f\u06e1\u0631\u064e\u0627\u0631\u0657\u0627 \u0648\u064e\u064a\u064e\u0632\u0650\u062f\u06e1\u0643\u064f\u0645\u06e1 \u0642\u064f\u0648\u0651\u064e\u0629\u064b \u0625\u0650\u0644\u064e\u0649\u0670 \u0642\u064f\u0648\u0651\u064e\u062a\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u06e1\u0627\u0652 \u0645\u064f\u062c\u06e1\u0631\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dan (Hud berkata), \"Wahai kaumku! Mohonlah ampunan kepada Tuhanmu lalu bertobatlah kepada-Nya, niscaya Dia menurunkan hujan yang sangat deras, Dia akan menambahkan kekuatan di atas kekuatanmu, dan janganlah kamu berpaling menjadi orang yang berdosa"},{id:53,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u064a\u064e\u0670\u0647\u064f\u0648\u062f\u064f \u0645\u064e\u0627 \u062c\u0650\u0626\u06e1\u062a\u064e\u0646\u064e\u0627 \u0628\u0650\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0629\u0656 \u0648\u064e\u0645\u064e\u0627 \u0646\u064e\u062d\u06e1\u0646\u064f \u0628\u0650\u062a\u064e\u0627\u0631\u0650\u0643\u0650\u064a\u0653 \u0621\u064e\u0627\u0644\u0650\u0647\u064e\u062a\u0650\u0646\u064e\u0627 \u0639\u064e\u0646 \u0642\u064e\u0648\u06e1\u0644\u0650\u0643\u064e \u0648\u064e\u0645\u064e\u0627 \u0646\u064e\u062d\u06e1\u0646\u064f \u0644\u064e\u0643\u064e \u0628\u0650\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Mereka (kaum '\u0100d) berkata, \"Wahai Hud! Engkau tidak mendatangkan suatu bukti yang nyata kepada kami, dan kami tidak akan meninggalkan sesembahan kami karena perkataanmu dan kami tidak akan mempercayaimu"},{id:54,text:"\u0625\u0650\u0646 \u0646\u0651\u064e\u0642\u064f\u0648\u0644\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0639\u06e1\u062a\u064e\u0631\u064e\u0649\u0670\u0643\u064e \u0628\u064e\u0639\u06e1\u0636\u064f \u0621\u064e\u0627\u0644\u0650\u0647\u064e\u062a\u0650\u0646\u064e\u0627 \u0628\u0650\u0633\u064f\u0648\u0653\u0621\u0656\u06d7 \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064f\u0634\u06e1\u0647\u0650\u062f\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0671\u0634\u06e1\u0647\u064e\u062f\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u0650\u064a \u0628\u064e\u0631\u0650\u064a\u0653\u0621\u065e \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u062a\u064f\u0634\u06e1\u0631\u0650\u0643\u064f\u0648\u0646\u064e",translation:"kami hanya mengatakan bahwa sebagian sesembahan kami telah menimpakan penyakit gila atas dirimu.\" Dia (Hud) menjawab, \"Sesungguhnya aku bersaksi kepada Allah dan saksikanlah bahwa aku berlepas diri dari apa yang kamu persekutukan"},{id:55,text:"\u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u06e6\u06d6 \u0641\u064e\u0643\u0650\u064a\u062f\u064f\u0648\u0646\u0650\u064a \u062c\u064e\u0645\u0650\u064a\u0639\u0657\u0627 \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0627 \u062a\u064f\u0646\u0638\u0650\u0631\u064f\u0648\u0646\u0650",translation:"dengan selain-Nya, sebab itu jalankanlah semua tipu dayamu terhadapku dan jangan kamu tunda lagi"},{id:56,text:"\u0625\u0650\u0646\u0651\u0650\u064a \u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u06e1\u062a\u064f \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0631\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06da \u0645\u0651\u064e\u0627 \u0645\u0650\u0646 \u062f\u064e\u0627\u0653\u0628\u0651\u064e\u0629\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u0621\u064e\u0627\u062e\u0650\u0630\u064f\u06e2 \u0628\u0650\u0646\u064e\u0627\u0635\u0650\u064a\u064e\u062a\u0650\u0647\u064e\u0627\u0653\u06da \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0639\u064e\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0670\u0637\u0656 \u0645\u0651\u064f\u0633\u06e1\u062a\u064e\u0642\u0650\u064a\u0645\u0656",translation:"Sesungguhnya aku bertawakal kepada Allah Tuhanku dan Tuhanmu. Tidak satu pun makhluk bergerak (bernyawa) melainkan Dialah yang memegang ubun-ubunnya (menguasainya). Sungguh, Tuhanku di jalan yang lurus (adil)"},{id:57,text:"\u0641\u064e\u0625\u0650\u0646 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u06e1\u0627\u0652 \u0641\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u0628\u06e1\u0644\u064e\u063a\u06e1\u062a\u064f\u0643\u064f\u0645 \u0645\u0651\u064e\u0627\u0653 \u0623\u064f\u0631\u06e1\u0633\u0650\u0644\u06e1\u062a\u064f \u0628\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u064a\u064e\u0633\u06e1\u062a\u064e\u062e\u06e1\u0644\u0650\u0641\u064f \u0631\u064e\u0628\u0651\u0650\u064a \u0642\u064e\u0648\u06e1\u0645\u064b\u0627 \u063a\u064e\u064a\u06e1\u0631\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0636\u064f\u0631\u0651\u064f\u0648\u0646\u064e\u0647\u064f\u06e5 \u0634\u064e\u064a\u06e1\u0640\u0654\u064b\u0627\u06da \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u064d \u062d\u064e\u0641\u0650\u064a\u0638\u065e",translation:"Maka jika kamu berpaling, maka sungguh, aku telah menyampaikan kepadamu apa yang menjadi tugasku sebagai rasul kepadamu. Dan Tuhanku akan mengganti kamu dengan kaum yang lain, sedang kamu tidak dapat mendatangkan mudarat kepada-Nya sedikit pun. Sesungguhnya Tuhanku Maha Pemelihara segala sesuatu"},{id:58,text:"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e \u0623\u064e\u0645\u06e1\u0631\u064f\u0646\u064e\u0627 \u0646\u064e\u062c\u0651\u064e\u064a\u06e1\u0646\u064e\u0627 \u0647\u064f\u0648\u062f\u0657\u0627 \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0645\u064e\u0639\u064e\u0647\u064f\u06e5 \u0628\u0650\u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u0656 \u0645\u0651\u0650\u0646\u0651\u064e\u0627 \u0648\u064e\u0646\u064e\u062c\u0651\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064d \u063a\u064e\u0644\u0650\u064a\u0638\u0656",translation:"Dan ketika azab Kami datang, Kami selamatkan Hud dan orang-orang yang beriman bersama dia dengan rahmat Kami. Kami selamatkan (pula) mereka (di akhirat) dari azab yang berat"},{id:59,text:"\u0648\u064e\u062a\u0650\u0644\u06e1\u0643\u064e \u0639\u064e\u0627\u062f\u065e\u06d6 \u062c\u064e\u062d\u064e\u062f\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0639\u064e\u0635\u064e\u0648\u06e1\u0627\u0652 \u0631\u064f\u0633\u064f\u0644\u064e\u0647\u064f\u06e5 \u0648\u064e\u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0645\u06e1\u0631\u064e \u0643\u064f\u0644\u0651\u0650 \u062c\u064e\u0628\u0651\u064e\u0627\u0631\u064d \u0639\u064e\u0646\u0650\u064a\u062f\u0656",translation:"Dan itulah (kisah) kaum '\u0100d yang mengingkari tanda-tanda (kekuasaan) Tuhan. Mereka mendurhakai rasul-rasul-Nya dan menuruti perintah semua penguasa yang sewenang-wenang lagi durhaka"},{id:60,text:"\u0648\u064e\u0623\u064f\u062a\u06e1\u0628\u0650\u0639\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0647\u064e\u0670\u0630\u0650\u0647\u0650 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0644\u064e\u0639\u06e1\u0646\u064e\u0629\u0657 \u0648\u064e\u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650\u06d7 \u0623\u064e\u0644\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e \u0639\u064e\u0627\u062f\u0657\u0627 \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u0645\u06e1\u06d7 \u0623\u064e\u0644\u064e\u0627 \u0628\u064f\u0639\u06e1\u062f\u0657\u0627 \u0644\u0651\u0650\u0639\u064e\u0627\u062f\u0656 \u0642\u064e\u0648\u06e1\u0645\u0650 \u0647\u064f\u0648\u062f\u0656",translation:"Dan mereka selalu diikuti dengan laknat di dunia ini dan (begitu pula) di hari Kiamat. Ingatlah, kaum '\u0100d itu ingkar kepada Tuhan mereka. Sungguh, binasalah kaum '\u0100d, umat Hud itu"},{id:61,text:"\u06de\u0648\u064e\u0625\u0650\u0644\u064e\u0649\u0670 \u062b\u064e\u0645\u064f\u0648\u062f\u064e \u0623\u064e\u062e\u064e\u0627\u0647\u064f\u0645\u06e1 \u0635\u064e\u0670\u0644\u0650\u062d\u0657\u0627\u06da \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0625\u0650\u0644\u064e\u0670\u0647\u064d \u063a\u064e\u064a\u06e1\u0631\u064f\u0647\u064f\u06e5\u06d6 \u0647\u064f\u0648\u064e \u0623\u064e\u0646\u0634\u064e\u0623\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0671\u0633\u06e1\u062a\u064e\u0639\u06e1\u0645\u064e\u0631\u064e\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u063a\u06e1\u0641\u0650\u0631\u064f\u0648\u0647\u064f \u062b\u064f\u0645\u0651\u064e \u062a\u064f\u0648\u0628\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u06da \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0642\u064e\u0631\u0650\u064a\u0628\u065e \u0645\u0651\u064f\u062c\u0650\u064a\u0628\u065e",translation:"dan kepada kaum Samud (Kami utus) saudara mereka, Saleh. Dia berkata, \"Wahai kaumku! Sembahlah Allah, tidak ada tuhan bagimu selain Dia. Dia telah menciptakanmu dari bumi (tanah) dan menjadikanmu pemakmurnya,402) karena itu mohonlah ampunan kepada-Nya, kemudian bertobatlah kepada-Nya. Sesungguhnya Tuhanku sangat dekat (rahmat-Nya) dan memperkenankan (doa hamba-Nya)"},{id:62,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u064a\u064e\u0670\u0635\u064e\u0670\u0644\u0650\u062d\u064f \u0642\u064e\u062f\u06e1 \u0643\u064f\u0646\u062a\u064e \u0641\u0650\u064a\u0646\u064e\u0627 \u0645\u064e\u0631\u06e1\u062c\u064f\u0648\u0651\u0657\u0627 \u0642\u064e\u0628\u06e1\u0644\u064e \u0647\u064e\u0670\u0630\u064e\u0627\u0653\u06d6 \u0623\u064e\u062a\u064e\u0646\u06e1\u0647\u064e\u0649\u0670\u0646\u064e\u0627\u0653 \u0623\u064e\u0646 \u0646\u0651\u064e\u0639\u06e1\u0628\u064f\u062f\u064e \u0645\u064e\u0627 \u064a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0624\u064f\u0646\u064e\u0627 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0646\u064e\u0627 \u0644\u064e\u0641\u0650\u064a \u0634\u064e\u0643\u0651\u0656 \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0645\u064f\u0631\u0650\u064a\u0628\u0656",translation:"Mereka (kaum Samud) berkata, \"Wahai Saleh! Sungguh, engkau sebelum ini berada di tengah-tengah kami sebagai orang yang diharapkan, mengapa engkau melarang kami menyembah apa yang disembah oleh nenek moyang kami? Sungguh, kami benar-benar dalam keraguan dan kegelisahan terhadap apa (agama) yang engkau serukan kepada kami"},{id:63,text:"\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0623\u064e\u0631\u064e\u0621\u064e\u064a\u06e1\u062a\u064f\u0645\u06e1 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0629\u0656 \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u0621\u064e\u0627\u062a\u064e\u0649\u0670\u0646\u0650\u064a \u0645\u0650\u0646\u06e1\u0647\u064f \u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u0657 \u0641\u064e\u0645\u064e\u0646 \u064a\u064e\u0646\u0635\u064f\u0631\u064f\u0646\u0650\u064a \u0645\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0646\u06e1 \u0639\u064e\u0635\u064e\u064a\u06e1\u062a\u064f\u0647\u064f\u06e5\u06d6 \u0641\u064e\u0645\u064e\u0627 \u062a\u064e\u0632\u0650\u064a\u062f\u064f\u0648\u0646\u064e\u0646\u0650\u064a \u063a\u064e\u064a\u06e1\u0631\u064e \u062a\u064e\u062e\u06e1\u0633\u0650\u064a\u0631\u0656",translation:"Dia (Saleh) berkata, \"Wahai kaumku! Terangkanlah kepadaku jika aku mempunyai bukti yang nyata dari Tuhanku dan diberi-Nya aku rahmat (kenabian) dari-Nya, maka siapa yang akan menolongku dari (azab) Allah jika aku mendurhakai-Nya? Maka kamu hanya akan menambah kerugian kepadaku"},{id:64,text:"\u0648\u064e\u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0647\u064e\u0670\u0630\u0650\u0647\u0650\u06e6 \u0646\u064e\u0627\u0642\u064e\u0629\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0621\u064e\u0627\u064a\u064e\u0629\u0657\u06d6 \u0641\u064e\u0630\u064e\u0631\u064f\u0648\u0647\u064e\u0627 \u062a\u064e\u0623\u06e1\u0643\u064f\u0644\u06e1 \u0641\u0650\u064a\u0653 \u0623\u064e\u0631\u06e1\u0636\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0645\u064e\u0633\u0651\u064f\u0648\u0647\u064e\u0627 \u0628\u0650\u0633\u064f\u0648\u0653\u0621\u0656 \u0641\u064e\u064a\u064e\u0623\u06e1\u062e\u064f\u0630\u064e\u0643\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u065e \u0642\u064e\u0631\u0650\u064a\u0628\u065e",translation:"Dan wahai kaumku! Inilah unta betina dari Allah, sebagai mukjizat untukmu, sebab itu biarkanlah dia makan di bumi Allah, dan janganlah kamu mengganggunya dengan gangguan apa pun yang akan menyebabkan kamu segera ditimpa (azab)"},{id:65,text:"\u0641\u064e\u0639\u064e\u0642\u064e\u0631\u064f\u0648\u0647\u064e\u0627 \u0641\u064e\u0642\u064e\u0627\u0644\u064e \u062a\u064e\u0645\u064e\u062a\u0651\u064e\u0639\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u062f\u064e\u0627\u0631\u0650\u0643\u064f\u0645\u06e1 \u062b\u064e\u0644\u064e\u0670\u062b\u064e\u0629\u064e \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u0656\u06d6 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0648\u064e\u0639\u06e1\u062f\u064c \u063a\u064e\u064a\u06e1\u0631\u064f \u0645\u064e\u0643\u06e1\u0630\u064f\u0648\u0628\u0656",translation:"Maka mereka menyembelih unta itu, kemudian dia (Saleh) berkata, \"Bersukarialah kamu semua di rumahmu selama tiga hari.403) Itu adalah janji yang tidak dapat didustakan"},{id:66,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e \u0623\u064e\u0645\u06e1\u0631\u064f\u0646\u064e\u0627 \u0646\u064e\u062c\u0651\u064e\u064a\u06e1\u0646\u064e\u0627 \u0635\u064e\u0670\u0644\u0650\u062d\u0657\u0627 \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0645\u064e\u0639\u064e\u0647\u064f\u06e5 \u0628\u0650\u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u0656 \u0645\u0651\u0650\u0646\u0651\u064e\u0627 \u0648\u064e\u0645\u0650\u0646\u06e1 \u062e\u0650\u0632\u06e1\u064a\u0650 \u064a\u064e\u0648\u06e1\u0645\u0650\u0626\u0650\u0630\u064d\u06da \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0642\u064e\u0648\u0650\u064a\u0651\u064f \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f",translation:"Maka ketika keputusan Kami datang, Kami selamatkan Saleh dan orang-orang yang beriman bersamanya dengan rahmat Kami dan (Kami selamatkan) dari kehinaan pada hari itu. Sungguh, Tuhanmu, Dia Mahakuat, Mahaperkasa"},{id:67,text:"\u0648\u064e\u0623\u064e\u062e\u064e\u0630\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u064a\u06e1\u062d\u064e\u0629\u064f \u0641\u064e\u0623\u064e\u0635\u06e1\u0628\u064e\u062d\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u062f\u0650\u064a\u064e\u0670\u0631\u0650\u0647\u0650\u0645\u06e1 \u062c\u064e\u0670\u062b\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Kemudian suara yang mengguntur menimpa orang-orang zalim itu, sehingga mereka mati bergelimpangan di rumahnya"},{id:68,text:"\u0643\u064e\u0623\u064e\u0646 \u0644\u0651\u064e\u0645\u06e1 \u064a\u064e\u063a\u06e1\u0646\u064e\u0648\u06e1\u0627\u0652 \u0641\u0650\u064a\u0647\u064e\u0627\u0653\u06d7 \u0623\u064e\u0644\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e \u062b\u064e\u0645\u064f\u0648\u062f\u064e\u0627\u0652 \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u0645\u06e1\u06d7 \u0623\u064e\u0644\u064e\u0627 \u0628\u064f\u0639\u06e1\u062f\u0657\u0627 \u0644\u0651\u0650\u062b\u064e\u0645\u064f\u0648\u062f\u064e",translation:"(seolah-olah mereka belum pernah tinggal404) di tempat itu. Ingatlah, kaum Samud mengingkari Tuhan mereka. Ingatlah, binasalah kaum Samud"},{id:69,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u062a\u06e1 \u0631\u064f\u0633\u064f\u0644\u064f\u0646\u064e\u0627\u0653 \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064e \u0628\u0650\u0671\u0644\u06e1\u0628\u064f\u0634\u06e1\u0631\u064e\u0649\u0670 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0633\u064e\u0644\u064e\u0670\u0645\u0657\u0627\u06d6 \u0642\u064e\u0627\u0644\u064e \u0633\u064e\u0644\u064e\u0670\u0645\u065e\u06d6 \u0641\u064e\u0645\u064e\u0627 \u0644\u064e\u0628\u0650\u062b\u064e \u0623\u064e\u0646 \u062c\u064e\u0627\u0653\u0621\u064e \u0628\u0650\u0639\u0650\u062c\u06e1\u0644\u064d \u062d\u064e\u0646\u0650\u064a\u0630\u0656",translation:"Dan para utusan Kami (para malaikat) telah datang kepada Ibrahim dengan membawa kabar gembira, mereka mengucapkan, \"Selamat.\" Dia (Ibrahim) menjawab, \"Selamat (atas kamu).\" Maka tidak lama kemudian Ibrahim menyuguhkan daging anak sapi yang dipanggang"},{id:70,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0631\u064e\u0621\u064e\u0627\u0653 \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u062a\u064e\u0635\u0650\u0644\u064f \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0646\u064e\u0643\u0650\u0631\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0648\u06e1\u062c\u064e\u0633\u064e \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u062e\u0650\u064a\u0641\u064e\u0629\u0657\u06da \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u062a\u064e\u062e\u064e\u0641\u06e1 \u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0623\u064f\u0631\u06e1\u0633\u0650\u0644\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u06e1\u0645\u0650 \u0644\u064f\u0648\u0637\u0656",translation:"Maka ketika dilihatnya tangan mereka tidak menjamahnya, dia (Ibrahim) mencurigai mereka, dan merasa takut kepada mereka. Mereka (malaikat) berkata, \"Jangan takut, sesungguhnya kami diutus kepada kaum Lu\u1e6d"},{id:71,text:"\u0648\u064e\u0671\u0645\u06e1\u0631\u064e\u0623\u064e\u062a\u064f\u0647\u064f\u06e5 \u0642\u064e\u0627\u0653\u0626\u0650\u0645\u064e\u0629\u065e \u0641\u064e\u0636\u064e\u062d\u0650\u0643\u064e\u062a\u06e1 \u0641\u064e\u0628\u064e\u0634\u0651\u064e\u0631\u06e1\u0646\u064e\u0670\u0647\u064e\u0627 \u0628\u0650\u0625\u0650\u0633\u06e1\u062d\u064e\u0670\u0642\u064e \u0648\u064e\u0645\u0650\u0646 \u0648\u064e\u0631\u064e\u0627\u0653\u0621\u0650 \u0625\u0650\u0633\u06e1\u062d\u064e\u0670\u0642\u064e \u064a\u064e\u0639\u06e1\u0642\u064f\u0648\u0628\u064e",translation:"Dan istrinya berdiri lalu dia tersenyum. Maka Kami sampaikan kepadanya kabar gembira tentang (kelahiran) Ishak dan setelah Ishak (akan lahir) Yakub"},{id:72,text:"\u0642\u064e\u0627\u0644\u064e\u062a\u06e1 \u064a\u064e\u0670\u0648\u064e\u064a\u06e1\u0644\u064e\u062a\u064e\u0649\u0670\u0653 \u0621\u064e\u0623\u064e\u0644\u0650\u062f\u064f \u0648\u064e\u0623\u064e\u0646\u064e\u0627\u06e0 \u0639\u064e\u062c\u064f\u0648\u0632\u065e \u0648\u064e\u0647\u064e\u0670\u0630\u064e\u0627 \u0628\u064e\u0639\u06e1\u0644\u0650\u064a \u0634\u064e\u064a\u06e1\u062e\u064b\u0627\u06d6 \u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0644\u064e\u0634\u064e\u064a\u06e1\u0621\u064c \u0639\u064e\u062c\u0650\u064a\u0628\u065e",translation:"Dia (istrinya) berkata, \"Sungguh ajaib, mungkinkah aku akan melahirkan anak padahal aku sudah tua, dan suamiku ini sudah sangat tua? Ini benar-benar sesuatu yang ajaib"},{id:73,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u062a\u064e\u0639\u06e1\u062c\u064e\u0628\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u06e1 \u0623\u064e\u0645\u06e1\u0631\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0631\u064e\u062d\u06e1\u0645\u064e\u062a\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0628\u064e\u0631\u064e\u0643\u064e\u0670\u062a\u064f\u0647\u064f\u06e5 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0623\u064e\u0647\u06e1\u0644\u064e \u0671\u0644\u06e1\u0628\u064e\u064a\u06e1\u062a\u0650\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u062d\u064e\u0645\u0650\u064a\u062f\u065e \u0645\u0651\u064e\u062c\u0650\u064a\u062f\u065e",translation:"Mereka (para malaikat) berkata, \"Mengapa engkau merasa heran tentang ketetapan Allah? (Itu adalah) rahmat dan berkah Allah, dicurahkan kepada kamu, wahai ahlulbait! Sesungguhnya Allah Maha Terpuji, Maha Pengasih"},{id:74,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0630\u064e\u0647\u064e\u0628\u064e \u0639\u064e\u0646\u06e1 \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064e \u0671\u0644\u0631\u0651\u064e\u0648\u06e1\u0639\u064f \u0648\u064e\u062c\u064e\u0627\u0653\u0621\u064e\u062a\u06e1\u0647\u064f \u0671\u0644\u06e1\u0628\u064f\u0634\u06e1\u0631\u064e\u0649\u0670 \u064a\u064f\u062c\u064e\u0670\u062f\u0650\u0644\u064f\u0646\u064e\u0627 \u0641\u0650\u064a \u0642\u064e\u0648\u06e1\u0645\u0650 \u0644\u064f\u0648\u0637\u064d",translation:"Maka ketika rasa takut hilang dari Ibrahim dan kabar gembira telah datang kepadanya, dia pun bersoal jawab dengan (para malaikat) Kami tentang kaum Lu\u1e6d"},{id:75,text:"\u0625\u0650\u0646\u0651\u064e \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064e \u0644\u064e\u062d\u064e\u0644\u0650\u064a\u0645\u064c \u0623\u064e\u0648\u0651\u064e\u0640\u0670\u0647\u065e \u0645\u0651\u064f\u0646\u0650\u064a\u0628\u065e",translation:"Ibrahim sungguh penyantun, lembut hati dan suka kembali (kepada Allah)"},{id:76,text:"\u064a\u064e\u0640\u0670\u0653\u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064f \u0623\u064e\u0639\u06e1\u0631\u0650\u0636\u06e1 \u0639\u064e\u0646\u06e1 \u0647\u064e\u0670\u0630\u064e\u0627\u0653\u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0642\u064e\u062f\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e \u0623\u064e\u0645\u06e1\u0631\u064f \u0631\u064e\u0628\u0651\u0650\u0643\u064e\u06d6 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0621\u064e\u0627\u062a\u0650\u064a\u0647\u0650\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u063a\u064e\u064a\u06e1\u0631\u064f \u0645\u064e\u0631\u06e1\u062f\u064f\u0648\u062f\u0656",translation:"Wahai Ibrahim! Tinggalkanlah (perbincangan) ini, sungguh, ketetapan Tuhanmu telah datang, dan mereka itu akan ditimpa azab yang tidak dapat ditolak"},{id:77,text:"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u062a\u06e1 \u0631\u064f\u0633\u064f\u0644\u064f\u0646\u064e\u0627 \u0644\u064f\u0648\u0637\u0657\u0627 \u0633\u0650\u064a\u0653\u0621\u064e \u0628\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0636\u064e\u0627\u0642\u064e \u0628\u0650\u0647\u0650\u0645\u06e1 \u0630\u064e\u0631\u06e1\u0639\u0657\u0627 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u064a\u064e\u0648\u06e1\u0645\u064c \u0639\u064e\u0635\u0650\u064a\u0628\u065e",translation:"Dan ketika para utusan Kami (para malaikat) itu datang kepada Lu\u1e6d, dia merasa curiga dan dadanya merasa sempit karena (kedatangan)nya. Dia (Lu\u1e6d) berkata, \"Ini hari yang sangat sulit"},{id:78,text:"\u0648\u064e\u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u06e5 \u0642\u064e\u0648\u06e1\u0645\u064f\u0647\u064f\u06e5 \u064a\u064f\u0647\u06e1\u0631\u064e\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0648\u064e\u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0640\u0654\u064e\u0627\u062a\u0650\u06da \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650 \u0628\u064e\u0646\u064e\u0627\u062a\u0650\u064a \u0647\u064f\u0646\u0651\u064e \u0623\u064e\u0637\u06e1\u0647\u064e\u0631\u064f \u0644\u064e\u0643\u064f\u0645\u06e1\u06d6 \u0641\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u062e\u06e1\u0632\u064f\u0648\u0646\u0650 \u0641\u0650\u064a \u0636\u064e\u064a\u06e1\u0641\u0650\u064a\u0653\u06d6 \u0623\u064e\u0644\u064e\u064a\u06e1\u0633\u064e \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u0631\u064e\u062c\u064f\u0644\u065e \u0631\u0651\u064e\u0634\u0650\u064a\u062f\u065e",translation:"Dan kaumnya segera datang kepadanya. Dan sejak dahulu mereka selalu melakukan perbuatan keji. Lu\u1e6d berkata, \"Wahai kaumku! Inilah puteri-puteri (negeri)ku mereka lebih suci bagimu, maka bertakwalah kepada Allah dan janganlah kamu mencemarkan (nama)ku terhadap tamuku ini. Tidak adakah di antaramu orang yang berakal"},{id:79,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0642\u064e\u062f\u06e1 \u0639\u064e\u0644\u0650\u0645\u06e1\u062a\u064e \u0645\u064e\u0627 \u0644\u064e\u0646\u064e\u0627 \u0641\u0650\u064a \u0628\u064e\u0646\u064e\u0627\u062a\u0650\u0643\u064e \u0645\u0650\u0646\u06e1 \u062d\u064e\u0642\u0651\u0656 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0646\u064f\u0631\u0650\u064a\u062f\u064f",translation:"Mereka menjawab, \"Sesungguhnya engkau pasti tahu bahwa kami tidak mempunyai hasrat (syahwat) terhadap puteri-puterimu; dan engkau tentu mengetahui apa yang (sebenarnya) kami kehendaki"},{id:80,text:"\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0648\u06e1 \u0623\u064e\u0646\u0651\u064e \u0644\u0650\u064a \u0628\u0650\u0643\u064f\u0645\u06e1 \u0642\u064f\u0648\u0651\u064e\u0629\u064b \u0623\u064e\u0648\u06e1 \u0621\u064e\u0627\u0648\u0650\u064a\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064f\u0643\u06e1\u0646\u0656 \u0634\u064e\u062f\u0650\u064a\u062f\u0656",translation:"Dia (Lu\u1e6d) berkata, \"Sekiranya aku mempunyai kekuatan (untuk menolakmu) atau aku dapat berlindung kepada keluarga yang kuat (tentu aku lakukan)"},{id:81,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u064a\u064e\u0670\u0644\u064f\u0648\u0637\u064f \u0625\u0650\u0646\u0651\u064e\u0627 \u0631\u064f\u0633\u064f\u0644\u064f \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0644\u064e\u0646 \u064a\u064e\u0635\u0650\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e\u06d6 \u0641\u064e\u0623\u064e\u0633\u06e1\u0631\u0650 \u0628\u0650\u0623\u064e\u0647\u06e1\u0644\u0650\u0643\u064e \u0628\u0650\u0642\u0650\u0637\u06e1\u0639\u0656 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u0650 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0644\u06e1\u062a\u064e\u0641\u0650\u062a\u06e1 \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u0623\u064e\u062d\u064e\u062f\u064c \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0645\u06e1\u0631\u064e\u0623\u064e\u062a\u064e\u0643\u064e\u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0645\u064f\u0635\u0650\u064a\u0628\u064f\u0647\u064e\u0627 \u0645\u064e\u0627\u0653 \u0623\u064e\u0635\u064e\u0627\u0628\u064e\u0647\u064f\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e \u0645\u064e\u0648\u06e1\u0639\u0650\u062f\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0635\u0651\u064f\u0628\u06e1\u062d\u064f\u06da \u0623\u064e\u0644\u064e\u064a\u06e1\u0633\u064e \u0671\u0644\u0635\u0651\u064f\u0628\u06e1\u062d\u064f \u0628\u0650\u0642\u064e\u0631\u0650\u064a\u0628\u0656",translation:"Mereka (para malaikat) berkata, \"Wahai Lu\u1e6d! Sesungguhnya kami adalah para utusan Tuhanmu, mereka tidak akan dapat mengganggu kamu, sebab itu pergilah bersama keluargamu pada akhir malam dan jangan ada seorang pun di antara kamu yang menoleh ke belakang, kecuali istrimu. Sesungguhnya dia (juga) akan ditimpa (siksaan) yang menimpa mereka. Sesungguhnya saat terjadinya siksaan bagi mereka itu pada waktu subuh. Bukankah subuh itu sudah dekat"},{id:82,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e \u0623\u064e\u0645\u06e1\u0631\u064f\u0646\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0639\u064e\u0670\u0644\u0650\u064a\u064e\u0647\u064e\u0627 \u0633\u064e\u0627\u0641\u0650\u0644\u064e\u0647\u064e\u0627 \u0648\u064e\u0623\u064e\u0645\u06e1\u0637\u064e\u0631\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627 \u062d\u0650\u062c\u064e\u0627\u0631\u064e\u0629\u0657 \u0645\u0651\u0650\u0646 \u0633\u0650\u062c\u0651\u0650\u064a\u0644\u0656 \u0645\u0651\u064e\u0646\u0636\u064f\u0648\u062f\u0656",translation:"Maka ketika keputusan Kami datang, Kami menjungkirbalikkan negeri kaum Lu\u1e6d, dan Kami hujani mereka bertubi-tubi dengan batu dari tanah yang terbakar"},{id:83,text:"\u0645\u0651\u064f\u0633\u064e\u0648\u0651\u064e\u0645\u064e\u0629\u064b \u0639\u0650\u0646\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064e\u06d6 \u0648\u064e\u0645\u064e\u0627 \u0647\u0650\u064a\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0628\u0650\u0628\u064e\u0639\u0650\u064a\u062f\u0656",translation:"yang diberi tanda oleh Tuhanmu. Dan siksaan itu tiadalah jauh dari orang yang zalim"},{id:84,text:"\u06de\u0648\u064e\u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064e\u062f\u06e1\u064a\u064e\u0646\u064e \u0623\u064e\u062e\u064e\u0627\u0647\u064f\u0645\u06e1 \u0634\u064f\u0639\u064e\u064a\u06e1\u0628\u0657\u0627\u06da \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0625\u0650\u0644\u064e\u0670\u0647\u064d \u063a\u064e\u064a\u06e1\u0631\u064f\u0647\u064f\u06e5\u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0646\u0642\u064f\u0635\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0645\u0650\u0643\u06e1\u064a\u064e\u0627\u0644\u064e \u0648\u064e\u0671\u0644\u06e1\u0645\u0650\u064a\u0632\u064e\u0627\u0646\u064e\u06d6 \u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064e\u0631\u064e\u0649\u0670\u0643\u064f\u0645 \u0628\u0650\u062e\u064e\u064a\u06e1\u0631\u0656 \u0648\u064e\u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u064a\u064e\u0648\u06e1\u0645\u0656 \u0645\u0651\u064f\u062d\u0650\u064a\u0637\u0656",translation:"Dan kepada (penduduk) Madyan (Kami utus) saudara mereka, Syu'aib. Dia berkata, \"Wahai kaumku! Sembahlah Allah, tidak ada tuhan bagimu selain Dia. Dan janganlah kamu kurangi takaran dan timbangan. Sesungguhnya aku melihat kamu dalam keadaan yang baik (makmur). Dan sesungguhnya aku khawatir kamu akan ditimpa azab pada hari yang membinasakan (Kiamat)"},{id:85,text:"\u0648\u064e\u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0623\u064e\u0648\u06e1\u0641\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0645\u0650\u0643\u06e1\u064a\u064e\u0627\u0644\u064e \u0648\u064e\u0671\u0644\u06e1\u0645\u0650\u064a\u0632\u064e\u0627\u0646\u064e \u0628\u0650\u0671\u0644\u06e1\u0642\u0650\u0633\u06e1\u0637\u0650\u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0628\u06e1\u062e\u064e\u0633\u064f\u0648\u0627\u0652 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0623\u064e\u0634\u06e1\u064a\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u062b\u064e\u0648\u06e1\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0645\u064f\u0641\u06e1\u0633\u0650\u062f\u0650\u064a\u0646\u064e",translation:"Dan wahai kaumku! Penuhilah takaran dan timbangan dengan adil, dan janganlah kamu merugikan manusia terhadap hak-hak mereka dan jangan kamu membuat kejahatan di bumi dengan berbuat kerusakan"},{id:86,text:"\u0628\u064e\u0642\u0650\u064a\u0651\u064e\u062a\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062e\u064e\u064a\u06e1\u0631\u065e \u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645 \u0645\u0651\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e\u06da \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u064e\u0627\u06e0 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645 \u0628\u0650\u062d\u064e\u0641\u0650\u064a\u0638\u0656",translation:"Sisa (yang halal) dari Allah adalah lebih baik bagimu jika kamu orang yang beriman. Dan aku bukanlah seorang penjaga atas dirimu"},{id:87,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u064a\u064e\u0670\u0634\u064f\u0639\u064e\u064a\u06e1\u0628\u064f \u0623\u064e\u0635\u064e\u0644\u064e\u0648\u0670\u062a\u064f\u0643\u064e \u062a\u064e\u0623\u06e1\u0645\u064f\u0631\u064f\u0643\u064e \u0623\u064e\u0646 \u0646\u0651\u064e\u062a\u06e1\u0631\u064f\u0643\u064e \u0645\u064e\u0627 \u064a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0624\u064f\u0646\u064e\u0627\u0653 \u0623\u064e\u0648\u06e1 \u0623\u064e\u0646 \u0646\u0651\u064e\u0641\u06e1\u0639\u064e\u0644\u064e \u0641\u0650\u064a\u0653 \u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u0650\u0646\u064e\u0627 \u0645\u064e\u0627 \u0646\u064e\u0634\u064e\u0640\u0670\u0653\u0624\u064f\u0627\u0652\u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u0623\u064e\u0646\u062a\u064e \u0671\u0644\u06e1\u062d\u064e\u0644\u0650\u064a\u0645\u064f \u0671\u0644\u0631\u0651\u064e\u0634\u0650\u064a\u062f\u064f",translation:"Mereka berkata, \"Wahai Syu'aib! Apakah agamamu yang menyuruhmu agar kami meninggalkan apa yang disembah nenek moyang kami atau melarang kami mengelola harta kami menurut cara yang kami kehendaki? Sesungguhnya engkau benar-benar orang yang sangat penyantun dan pandai"},{id:88,text:"\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0623\u064e\u0631\u064e\u0621\u064e\u064a\u06e1\u062a\u064f\u0645\u06e1 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0629\u0656 \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u0631\u064e\u0632\u064e\u0642\u064e\u0646\u0650\u064a \u0645\u0650\u0646\u06e1\u0647\u064f \u0631\u0650\u0632\u06e1\u0642\u064b\u0627 \u062d\u064e\u0633\u064e\u0646\u0657\u0627\u06da \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0631\u0650\u064a\u062f\u064f \u0623\u064e\u0646\u06e1 \u0623\u064f\u062e\u064e\u0627\u0644\u0650\u0641\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u06e1\u0647\u064e\u0649\u0670\u0643\u064f\u0645\u06e1 \u0639\u064e\u0646\u06e1\u0647\u064f\u06da \u0625\u0650\u0646\u06e1 \u0623\u064f\u0631\u0650\u064a\u062f\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u06e1\u0625\u0650\u0635\u06e1\u0644\u064e\u0670\u062d\u064e \u0645\u064e\u0627 \u0671\u0633\u06e1\u062a\u064e\u0637\u064e\u0639\u06e1\u062a\u064f\u06da \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0648\u06e1\u0641\u0650\u064a\u0642\u0650\u064a\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u06e1\u062a\u064f \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0623\u064f\u0646\u0650\u064a\u0628\u064f",translation:"Dia (Syu'aib) berkata, \"Wahai kaumku! Terangkan padaku jika aku mempunyai bukti yang nyata dari Tuhanku dan aku dianugerahi-Nya rezeki yang baik (pantaskah aku menyalahi perintah-Nya)? Aku tidak bermaksud menyalahi kamu terhadap apa yang aku larang darinya. Aku hanya bermaksud (mendatangkan) perbaikan selama aku masih sanggup. Dan petunjuk yang aku ikuti hanya dari Allah. Kepada-Nya aku bertawakal dan kepada-Nya (pula) aku kembali"},{id:89,text:"\u0648\u064e\u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0644\u064e\u0627 \u064a\u064e\u062c\u06e1\u0631\u0650\u0645\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0634\u0650\u0642\u064e\u0627\u0642\u0650\u064a\u0653 \u0623\u064e\u0646 \u064a\u064f\u0635\u0650\u064a\u0628\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u062b\u06e1\u0644\u064f \u0645\u064e\u0627\u0653 \u0623\u064e\u0635\u064e\u0627\u0628\u064e \u0642\u064e\u0648\u06e1\u0645\u064e \u0646\u064f\u0648\u062d\u064d \u0623\u064e\u0648\u06e1 \u0642\u064e\u0648\u06e1\u0645\u064e \u0647\u064f\u0648\u062f\u064d \u0623\u064e\u0648\u06e1 \u0642\u064e\u0648\u06e1\u0645\u064e \u0635\u064e\u0670\u0644\u0650\u062d\u0656\u06da \u0648\u064e\u0645\u064e\u0627 \u0642\u064e\u0648\u06e1\u0645\u064f \u0644\u064f\u0648\u0637\u0656 \u0645\u0651\u0650\u0646\u0643\u064f\u0645 \u0628\u0650\u0628\u064e\u0639\u0650\u064a\u062f\u0656",translation:"Dan wahai kaumku! Janganlah pertentangan antara aku (dengan kamu) menyebabkan kamu berbuat dosa, sehingga kamu ditimpa siksaan seperti yang menimpa kaum Nuh, kaum Hud atau kaum Saleh, sedang kaum Lu\u1e6d tidak jauh dari kamu"},{id:90,text:"\u0648\u064e\u0671\u0633\u06e1\u062a\u064e\u063a\u06e1\u0641\u0650\u0631\u064f\u0648\u0627\u0652 \u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u06e1 \u062b\u064f\u0645\u0651\u064e \u062a\u064f\u0648\u0628\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u06da \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0631\u064e\u062d\u0650\u064a\u0645\u065e \u0648\u064e\u062f\u064f\u0648\u062f\u065e",translation:"Dan mohonlah ampunan kepada Tuhanmu, kemudian bertobatlah kepada-Nya. Sungguh, Tuhanku Maha Penyayang, Maha Pengasih"},{id:91,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u064a\u064e\u0670\u0634\u064f\u0639\u064e\u064a\u06e1\u0628\u064f \u0645\u064e\u0627 \u0646\u064e\u0641\u06e1\u0642\u064e\u0647\u064f \u0643\u064e\u062b\u0650\u064a\u0631\u0657\u0627 \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0642\u064f\u0648\u0644\u064f \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0646\u064e\u0631\u064e\u0649\u0670\u0643\u064e \u0641\u0650\u064a\u0646\u064e\u0627 \u0636\u064e\u0639\u0650\u064a\u0641\u0657\u0627\u06d6 \u0648\u064e\u0644\u064e\u0648\u06e1\u0644\u064e\u0627 \u0631\u064e\u0647\u06e1\u0637\u064f\u0643\u064e \u0644\u064e\u0631\u064e\u062c\u064e\u0645\u06e1\u0646\u064e\u0670\u0643\u064e\u06d6 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0628\u0650\u0639\u064e\u0632\u0650\u064a\u0632\u0656",translation:"Mereka berkata, \"Wahai Syu'aib! Kami tidak banyak mengerti tentang apa yang engkau katakan itu, sedang kenyataannya kami memandang engkau seorang yang lemah di antara kami. Kalau tidak karena keluargamu, tentu kami telah merajam engkau, sedang engkau pun bukan seorang yang berpengaruh di lingkungan kami"},{id:92,text:"\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0623\u064e\u0631\u064e\u0647\u06e1\u0637\u0650\u064a\u0653 \u0623\u064e\u0639\u064e\u0632\u0651\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0671\u062a\u0651\u064e\u062e\u064e\u0630\u06e1\u062a\u064f\u0645\u064f\u0648\u0647\u064f \u0648\u064e\u0631\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u06e1 \u0638\u0650\u0647\u06e1\u0631\u0650\u064a\u0651\u064b\u0627\u06d6 \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0645\u064f\u062d\u0650\u064a\u0637\u065e",translation:"Dia (Syu'aib) menjawab, \"Wahai kaumku! Apakah keluargaku lebih terhormat menurut pandanganmu daripada Allah, bahkan Dia kamu tempatkan di belakangmu (diabaikan)? Ketahuilah (pengetahuan) Tuhanku meliputi apa yang kamu kerjakan"},{id:93,text:"\u0648\u064e\u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0643\u064e\u0627\u0646\u064e\u062a\u0650\u0643\u064f\u0645\u06e1 \u0625\u0650\u0646\u0651\u0650\u064a \u0639\u064e\u0670\u0645\u0650\u0644\u065e\u06d6 \u0633\u064e\u0648\u06e1\u0641\u064e \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0645\u064e\u0646 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u0647\u0650 \u0639\u064e\u0630\u064e\u0627\u0628\u065e \u064a\u064f\u062e\u06e1\u0632\u0650\u064a\u0647\u0650 \u0648\u064e\u0645\u064e\u0646\u06e1 \u0647\u064f\u0648\u064e \u0643\u064e\u0670\u0630\u0650\u0628\u065e\u06d6 \u0648\u064e\u0671\u0631\u06e1\u062a\u064e\u0642\u0650\u0628\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u0650\u064a \u0645\u064e\u0639\u064e\u0643\u064f\u0645\u06e1 \u0631\u064e\u0642\u0650\u064a\u0628\u065e",translation:"Dan wahai kaumku! Berbuatlah menurut kemampuanmu, sesungguhnya aku pun berbuat (pula). Kelak kamu akan mengetahui siapa yang akan ditimpa azab yang menghinakan dan siapa yang berdusta. Dan tunggulah! Sesungguhnya aku bersamamu adalah orang yang menunggu"},{id:94,text:"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e \u0623\u064e\u0645\u06e1\u0631\u064f\u0646\u064e\u0627 \u0646\u064e\u062c\u0651\u064e\u064a\u06e1\u0646\u064e\u0627 \u0634\u064f\u0639\u064e\u064a\u06e1\u0628\u0657\u0627 \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0645\u064e\u0639\u064e\u0647\u064f\u06e5 \u0628\u0650\u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u0656 \u0645\u0651\u0650\u0646\u0651\u064e\u0627 \u0648\u064e\u0623\u064e\u062e\u064e\u0630\u064e\u062a\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u064a\u06e1\u062d\u064e\u0629\u064f \u0641\u064e\u0623\u064e\u0635\u06e1\u0628\u064e\u062d\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u062f\u0650\u064a\u064e\u0670\u0631\u0650\u0647\u0650\u0645\u06e1 \u062c\u064e\u0670\u062b\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Maka ketika keputusan Kami datang, Kami selamatkan Syu'aib dan orang-orang yang beriman bersamanya dengan rahmat Kami. Sedang orang yang zalim dibinasakan oleh suara yang mengguntur, sehingga mereka mati bergelimpangan di rumahnya"},{id:95,text:"\u0643\u064e\u0623\u064e\u0646 \u0644\u0651\u064e\u0645\u06e1 \u064a\u064e\u063a\u06e1\u0646\u064e\u0648\u06e1\u0627\u0652 \u0641\u0650\u064a\u0647\u064e\u0627\u0653\u06d7 \u0623\u064e\u0644\u064e\u0627 \u0628\u064f\u0639\u06e1\u062f\u0657\u0627 \u0644\u0651\u0650\u0645\u064e\u062f\u06e1\u064a\u064e\u0646\u064e \u0643\u064e\u0645\u064e\u0627 \u0628\u064e\u0639\u0650\u062f\u064e\u062a\u06e1 \u062b\u064e\u0645\u064f\u0648\u062f\u064f",translation:"Seolah-olah mereka belum pernah tinggal di tempat itu. Ingatlah, binasalah penduduk Madyan sebagaimana kaum Samud (juga) telah binasa"},{id:96,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0648\u064e\u0633\u064f\u0644\u06e1\u0637\u064e\u0670\u0646\u0656 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u064d",translation:"Dan sungguh, Kami telah mengutus Musa dengan tanda-tanda (kekuasaan) Kami dan bukti yang nyata"},{id:97,text:"\u0625\u0650\u0644\u064e\u0649\u0670 \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0648\u064e\u0645\u064e\u0644\u064e\u0625\u0650\u064a\u0652\u0647\u0650\u06e6 \u0641\u064e\u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0645\u06e1\u0631\u064e \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e\u06d6 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0645\u06e1\u0631\u064f \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0628\u0650\u0631\u064e\u0634\u0650\u064a\u062f\u0656",translation:"kepada Fir'aun dan para pemuka kaumnya, tetapi mereka mengikuti perintah Fir'aun, padahal perintah Fir'aun bukanlah (perintah) yang benar"},{id:98,text:"\u064a\u064e\u0642\u06e1\u062f\u064f\u0645\u064f \u0642\u064e\u0648\u06e1\u0645\u064e\u0647\u064f\u06e5 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u0641\u064e\u0623\u064e\u0648\u06e1\u0631\u064e\u062f\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u064e\u06d6 \u0648\u064e\u0628\u0650\u0626\u06e1\u0633\u064e \u0671\u0644\u06e1\u0648\u0650\u0631\u06e1\u062f\u064f \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u0631\u064f\u0648\u062f\u064f",translation:"Dia (Fir'aun) berjalan di depan kaumnya di hari Kiamat, lalu membawa mereka masuk ke dalam neraka. Neraka itu seburuk-buruk tempat yang dimasuki"},{id:99,text:"\u0648\u064e\u0623\u064f\u062a\u06e1\u0628\u0650\u0639\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0647\u064e\u0670\u0630\u0650\u0647\u0650\u06e6 \u0644\u064e\u0639\u06e1\u0646\u064e\u0629\u0657 \u0648\u064e\u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650\u06da \u0628\u0650\u0626\u06e1\u0633\u064e \u0671\u0644\u0631\u0651\u0650\u0641\u06e1\u062f\u064f \u0671\u0644\u06e1\u0645\u064e\u0631\u06e1\u0641\u064f\u0648\u062f\u064f",translation:"Dan mereka diikuti dengan laknat di sini (dunia) dan (begitu pula) pada hari Kiamat. (Laknat) itu seburuk-buruk pemberian yang diberikan"},{id:100,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u0650\u0646\u06e1 \u0623\u064e\u0646\u06e2\u0628\u064e\u0627\u0653\u0621\u0650 \u0671\u0644\u06e1\u0642\u064f\u0631\u064e\u0649\u0670 \u0646\u064e\u0642\u064f\u0635\u0651\u064f\u0647\u064f\u06e5 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e\u06d6 \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0642\u064e\u0627\u0653\u0626\u0650\u0645\u065e \u0648\u064e\u062d\u064e\u0635\u0650\u064a\u062f\u065e",translation:"Itulah beberapa berita tentang negeri-negeri (yang telah dibinasakan) yang Kami ceritakan kepadamu (Muhammad). Di antara negeri-negeri itu sebagian masih ada bekas-bekasnya dan ada (pula) yang telah musnah"},{id:101,text:"\u0648\u064e\u0645\u064e\u0627 \u0638\u064e\u0644\u064e\u0645\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u06e1\u06d6 \u0641\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u063a\u06e1\u0646\u064e\u062a\u06e1 \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0621\u064e\u0627\u0644\u0650\u0647\u064e\u062a\u064f\u0647\u064f\u0645\u064f \u0671\u0644\u0651\u064e\u062a\u0650\u064a \u064a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0644\u0651\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e \u0623\u064e\u0645\u06e1\u0631\u064f \u0631\u064e\u0628\u0651\u0650\u0643\u064e\u06d6 \u0648\u064e\u0645\u064e\u0627 \u0632\u064e\u0627\u062f\u064f\u0648\u0647\u064f\u0645\u06e1 \u063a\u064e\u064a\u06e1\u0631\u064e \u062a\u064e\u062a\u06e1\u0628\u0650\u064a\u0628\u0656",translation:"Dan Kami tidak menzalimi mereka, tetapi merekalah yang menzalimi diri mereka sendiri, karena itu tidak bermanfaat sedikit pun bagi mereka sesembahan yang mereka sembah selain Allah, ketika siksaan Tuhanmu datang. Sesembahan itu hanya menambah kebinasaan bagi mereka"},{id:102,text:"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0623\u064e\u062e\u06e1\u0630\u064f \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0625\u0650\u0630\u064e\u0627\u0653 \u0623\u064e\u062e\u064e\u0630\u064e \u0671\u0644\u06e1\u0642\u064f\u0631\u064e\u0649\u0670 \u0648\u064e\u0647\u0650\u064a\u064e \u0638\u064e\u0670\u0644\u0650\u0645\u064e\u0629\u064c\u06da \u0625\u0650\u0646\u0651\u064e \u0623\u064e\u062e\u06e1\u0630\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u0644\u0650\u064a\u0645\u065e \u0634\u064e\u062f\u0650\u064a\u062f\u064c",translation:"Dan begitulah siksa Tuhanmu apabila Dia menyiksa (penduduk) negeri-negeri yang berbuat zalim. Sungguh, siksa-Nya sangat pedih, sangat berat"},{id:103,text:"\u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0623\u0653\u064a\u064e\u0629\u0657 \u0644\u0651\u0650\u0645\u064e\u0646\u06e1 \u062e\u064e\u0627\u0641\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064e\u0648\u06e1\u0645\u065e \u0645\u0651\u064e\u062c\u06e1\u0645\u064f\u0648\u0639\u065e \u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0648\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064e\u0648\u06e1\u0645\u065e \u0645\u0651\u064e\u0634\u06e1\u0647\u064f\u0648\u062f\u065e",translation:"Sesungguhnya pada yang demikian itu pasti terdapat pelajaran bagi orang-orang yang takut kepada azab akhirat. Itulah hari ketika semua manusia dikumpulkan (untuk dihisab), dan itulah hari yang disaksikan (oleh semua makhluk)"},{id:104,text:"\u0648\u064e\u0645\u064e\u0627 \u0646\u064f\u0624\u064e\u062e\u0651\u0650\u0631\u064f\u0647\u064f\u06e5\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0644\u0650\u0623\u064e\u062c\u064e\u0644\u0656 \u0645\u0651\u064e\u0639\u06e1\u062f\u064f\u0648\u062f\u0656",translation:"Dan Kami tidak akan menunda, kecuali sampai waktu yang sudah ditentukan"},{id:105,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064e\u0623\u06e1\u062a\u0650 \u0644\u064e\u0627 \u062a\u064e\u0643\u064e\u0644\u0651\u064e\u0645\u064f \u0646\u064e\u0641\u06e1\u0633\u064c \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0625\u0650\u0630\u06e1\u0646\u0650\u0647\u0650\u06e6\u06da \u0641\u064e\u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0634\u064e\u0642\u0650\u064a\u0651\u065e \u0648\u064e\u0633\u064e\u0639\u0650\u064a\u062f\u065e",translation:"Ketika hari itu datang, tidak seorang pun yang berbicara, kecuali dengan izin-Nya; maka di antara mereka ada yang sengsara dan ada yang berbahagia"},{id:106,text:"\u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0634\u064e\u0642\u064f\u0648\u0627\u0652 \u0641\u064e\u0641\u0650\u064a \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u0632\u064e\u0641\u0650\u064a\u0631\u065e \u0648\u064e\u0634\u064e\u0647\u0650\u064a\u0642\u064c",translation:"Maka adapun orang-orang yang sengsara, maka (tempatnya) di dalam neraka, di sana mereka mengeluarkan dan menarik nafas dengan merintih"},{id:107,text:"\u062e\u064e\u0670\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u064e\u0627 \u062f\u064e\u0627\u0645\u064e\u062a\u0650 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u064f \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0634\u064e\u0627\u0653\u0621\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e\u06da \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0641\u064e\u0639\u0651\u064e\u0627\u0644\u065e \u0644\u0651\u0650\u0645\u064e\u0627 \u064a\u064f\u0631\u0650\u064a\u062f\u064f",translation:"(mereka kekal di dalamnya selama ada langit dan bumi,407) kecuali jika Tuhanmu menghendaki (yang lain). Sungguh, Tuhanmu Maha Pelaksana terhadap apa yang Dia kehendaki"},{id:108,text:"\u06de\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0633\u064f\u0639\u0650\u062f\u064f\u0648\u0627\u0652 \u0641\u064e\u0641\u0650\u064a \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u062e\u064e\u0670\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u064e\u0627 \u062f\u064e\u0627\u0645\u064e\u062a\u0650 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u064f \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0634\u064e\u0627\u0653\u0621\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e\u06d6 \u0639\u064e\u0637\u064e\u0627\u0653\u0621\u064b \u063a\u064e\u064a\u06e1\u0631\u064e \u0645\u064e\u062c\u06e1\u0630\u064f\u0648\u0630\u0656",translation:"Dan adapun orang-orang yang berbahagia, maka (tempatnya) di dalam surga; mereka kekal di dalamnya selama ada langit dan bumi, kecuali jika Tuhanmu menghendaki (yang lain); sebagai karunia yang tidak ada putus-putusnya"},{id:109,text:"\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f \u0641\u0650\u064a \u0645\u0650\u0631\u06e1\u064a\u064e\u0629\u0656 \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f \u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650\u06da \u0645\u064e\u0627 \u064a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064e\u0645\u064e\u0627 \u064a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0624\u064f\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f\u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0645\u064f\u0648\u064e\u0641\u0651\u064f\u0648\u0647\u064f\u0645\u06e1 \u0646\u064e\u0635\u0650\u064a\u0628\u064e\u0647\u064f\u0645\u06e1 \u063a\u064e\u064a\u06e1\u0631\u064e \u0645\u064e\u0646\u0642\u064f\u0648\u0635\u0656",translation:"Maka janganlah engkau (Muhammad) ragu-ragu tentang apa yang mereka sembah. Mereka menyembah sebagaimana nenek moyang mereka dahulu menyembah. Kami pasti akan menyempurnakan pembalasan (terhadap) mereka tanpa dikurangi sedikit pun"},{id:110,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0641\u064e\u0671\u062e\u06e1\u062a\u064f\u0644\u0650\u0641\u064e \u0641\u0650\u064a\u0647\u0650\u06da \u0648\u064e\u0644\u064e\u0648\u06e1\u0644\u064e\u0627 \u0643\u064e\u0644\u0650\u0645\u064e\u0629\u065e \u0633\u064e\u0628\u064e\u0642\u064e\u062a\u06e1 \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064e \u0644\u064e\u0642\u064f\u0636\u0650\u064a\u064e \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1\u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0641\u0650\u064a \u0634\u064e\u0643\u0651\u0656 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f \u0645\u064f\u0631\u0650\u064a\u0628\u0656",translation:"Dan sungguh, Kami telah memberikan Kitab (Taurat) kepada Musa, lalu diperselisihkannya. Dan kalau tidak ada ketetapan yang terdahulu dari Tuhanmu, niscaya telah dilaksanakan hukuman di antara mereka.408) Sungguh, mereka (orang kafir Mekah) benar-benar dalam kebimbangan dan keraguan terhadapnya (Alquran)"},{id:111,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0643\u064f\u0644\u0651\u0657\u0627 \u0644\u0651\u064e\u0645\u0651\u064e\u0627 \u0644\u064e\u064a\u064f\u0648\u064e\u0641\u0651\u0650\u064a\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0623\u064e\u0639\u06e1\u0645\u064e\u0670\u0644\u064e\u0647\u064f\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0628\u0650\u0645\u064e\u0627 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u062e\u064e\u0628\u0650\u064a\u0631\u065e",translation:"Dan sesungguhnya kepada masing-masing (yang berselisih itu) pasti Tuhanmu akan memberi balasan secara penuh atas perbuatan mereka. Sungguh, Dia Mahateliti atas apa yang mereka kerjakan"},{id:112,text:"\u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u0642\u0650\u0645\u06e1 \u0643\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0645\u0650\u0631\u06e1\u062a\u064e \u0648\u064e\u0645\u064e\u0646 \u062a\u064e\u0627\u0628\u064e \u0645\u064e\u0639\u064e\u0643\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0637\u06e1\u063a\u064e\u0648\u06e1\u0627\u0652\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0628\u064e\u0635\u0650\u064a\u0631\u065e",translation:"Maka tetaplah engkau (Muhammad) (di jalan yang benar), sebagaimana telah diperintahkan kepadamu dan (juga) orang yang bertobat bersamamu, dan janganlah kamu melampaui batas. Sungguh, Dia Maha Melihat apa yang kamu kerjakan"},{id:113,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0631\u06e1\u0643\u064e\u0646\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627\u0652 \u0641\u064e\u062a\u064e\u0645\u064e\u0633\u0651\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u064f \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646\u06e1 \u0623\u064e\u0648\u06e1\u0644\u0650\u064a\u064e\u0627\u0653\u0621\u064e \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0627 \u062a\u064f\u0646\u0635\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan janganlah kamu cenderung kepada orang zalim yang menyebabkan kamu disentuh api neraka, sedangkan kamu tidak mempunyai seorang penolong pun selain Allah, sehingga kamu tidak akan diberi pertolongan"},{id:114,text:"\u0648\u064e\u0623\u064e\u0642\u0650\u0645\u0650 \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e \u0637\u064e\u0631\u064e\u0641\u064e\u064a\u0650 \u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u0648\u064e\u0632\u064f\u0644\u064e\u0641\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u0650\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u062d\u064e\u0633\u064e\u0646\u064e\u0670\u062a\u0650 \u064a\u064f\u0630\u06e1\u0647\u0650\u0628\u06e1\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0640\u0654\u064e\u0627\u062a\u0650\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0630\u0650\u0643\u06e1\u0631\u064e\u0649\u0670 \u0644\u0650\u0644\u0630\u0651\u064e\u0640\u0670\u0643\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan laksanakanlah salat pada kedua ujung siang (pagi dan petang) dan pada bagian permulaan malam. Perbuatan-perbuatan baik itu menghapus kesalahan-kesalahan. Itulah peringatan bagi orang-orang yang selalu mengingat (Allah)"},{id:115,text:"\u0648\u064e\u0671\u0635\u06e1\u0628\u0650\u0631\u06e1 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064f\u0636\u0650\u064a\u0639\u064f \u0623\u064e\u062c\u06e1\u0631\u064e \u0671\u0644\u06e1\u0645\u064f\u062d\u06e1\u0633\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dan bersabarlah, karena sesungguhnya Allah tidak menyia-nyiakan pahala orang yang berbuat kebaikan"},{id:116,text:"\u0641\u064e\u0644\u064e\u0648\u06e1\u0644\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0642\u064f\u0631\u064f\u0648\u0646\u0650 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064f\u0645\u06e1 \u0623\u064f\u0648\u0652\u0644\u064f\u0648\u0627\u0652 \u0628\u064e\u0642\u0650\u064a\u0651\u064e\u0629\u0656 \u064a\u064e\u0646\u06e1\u0647\u064e\u0648\u06e1\u0646\u064e \u0639\u064e\u0646\u0650 \u0671\u0644\u06e1\u0641\u064e\u0633\u064e\u0627\u062f\u0650 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u0657\u0627 \u0645\u0651\u0650\u0645\u0651\u064e\u0646\u06e1 \u0623\u064e\u0646\u062c\u064e\u064a\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1\u06d7 \u0648\u064e\u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627\u0652 \u0645\u064e\u0627\u0653 \u0623\u064f\u062a\u06e1\u0631\u0650\u0641\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0647\u0650 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0645\u064f\u062c\u06e1\u0631\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Maka mengapa tidak ada di antara umat-umat sebelum kamu orang yang mempunyai keutamaan yang melarang (berbuat) kerusakan di bumi, kecuali sebagian kecil di antara orang yang telah Kami selamatkan. Dan orang-orang yang zalim hanya mementingkan kenikmatan dan kemewahan. Dan mereka adalah orang-orang yang berdosa"},{id:117,text:"\u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0644\u0650\u064a\u064f\u0647\u06e1\u0644\u0650\u0643\u064e \u0671\u0644\u06e1\u0642\u064f\u0631\u064e\u0649\u0670 \u0628\u0650\u0638\u064f\u0644\u06e1\u0645\u0656 \u0648\u064e\u0623\u064e\u0647\u06e1\u0644\u064f\u0647\u064e\u0627 \u0645\u064f\u0635\u06e1\u0644\u0650\u062d\u064f\u0648\u0646\u064e",translation:"Dan Tuhanmu tidak akan membinasakan negeri-negeri secara zalim, selama penduduknya orang-orang yang berbuat kebaikan"},{id:118,text:"\u0648\u064e\u0644\u064e\u0648\u06e1 \u0634\u064e\u0627\u0653\u0621\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0644\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0623\u064f\u0645\u0651\u064e\u0629\u0657 \u0648\u064e\u0670\u062d\u0650\u062f\u064e\u0629\u0657\u06d6 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0632\u064e\u0627\u0644\u064f\u0648\u0646\u064e \u0645\u064f\u062e\u06e1\u062a\u064e\u0644\u0650\u0641\u0650\u064a\u0646\u064e",translation:"Dan jika Tuhanmu menghendaki, tentu Dia jadikan manusia umat yang satu, tetapi mereka senantiasa berselisih (pendapat)"},{id:119,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646 \u0631\u0651\u064e\u062d\u0650\u0645\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e\u06da \u0648\u064e\u0644\u0650\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062e\u064e\u0644\u064e\u0642\u064e\u0647\u064f\u0645\u06e1\u06d7 \u0648\u064e\u062a\u064e\u0645\u0651\u064e\u062a\u06e1 \u0643\u064e\u0644\u0650\u0645\u064e\u0629\u064f \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0644\u064e\u0623\u064e\u0645\u06e1\u0644\u064e\u0623\u064e\u0646\u0651\u064e \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u062c\u0650\u0646\u0651\u064e\u0629\u0650 \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0623\u064e\u062c\u06e1\u0645\u064e\u0639\u0650\u064a\u0646\u064e",translation:"kecuali orang yang diberi rahmat oleh Tuhanmu. Dan untuk itulah Allah menciptakan mereka. Kalimat (keputusan) Tuhanmu telah tetap, \"Aku pasti akan memenuhi neraka Jahanam dengan jin dan manusia (yang durhaka) semuanya"},{id:120,text:"\u0648\u064e\u0643\u064f\u0644\u0651\u0657\u0627 \u0646\u0651\u064e\u0642\u064f\u0635\u0651\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0645\u0650\u0646\u06e1 \u0623\u064e\u0646\u06e2\u0628\u064e\u0627\u0653\u0621\u0650 \u0671\u0644\u0631\u0651\u064f\u0633\u064f\u0644\u0650 \u0645\u064e\u0627 \u0646\u064f\u062b\u064e\u0628\u0651\u0650\u062a\u064f \u0628\u0650\u0647\u0650\u06e6 \u0641\u064f\u0624\u064e\u0627\u062f\u064e\u0643\u064e\u06da \u0648\u064e\u062c\u064e\u0627\u0653\u0621\u064e\u0643\u064e \u0641\u0650\u064a \u0647\u064e\u0670\u0630\u0650\u0647\u0650 \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f \u0648\u064e\u0645\u064e\u0648\u06e1\u0639\u0650\u0638\u064e\u0629\u065e \u0648\u064e\u0630\u0650\u0643\u06e1\u0631\u064e\u0649\u0670 \u0644\u0650\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dan semua kisah rasul-rasul, Kami ceritakan kepadamu (Muhammad), agar dengan kisah itu Kami teguhkan hatimu; dan di dalamnya telah diberikan kepadamu (segala) kebenaran, nasihat dan peringatan bagi orang yang beriman"},{id:121,text:"\u0648\u064e\u0642\u064f\u0644 \u0644\u0651\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0671\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0643\u064e\u0627\u0646\u064e\u062a\u0650\u0643\u064f\u0645\u06e1 \u0625\u0650\u0646\u0651\u064e\u0627 \u0639\u064e\u0670\u0645\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Dan katakanlah (Muhammad) kepada orang yang tidak beriman, \"Berbuatlah menurut kedudukanmu, kami pun benar-benar akan berbuat"},{id:122,text:"\u0648\u064e\u0671\u0646\u062a\u064e\u0638\u0650\u0631\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e\u0627 \u0645\u064f\u0646\u062a\u064e\u0638\u0650\u0631\u064f\u0648\u0646\u064e",translation:"dan tunggulah, sesungguhnya kami pun termasuk yang menunggu"},{id:123,text:"\u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u063a\u064e\u064a\u06e1\u0628\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u064a\u064f\u0631\u06e1\u062c\u064e\u0639\u064f \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0631\u064f \u0643\u064f\u0644\u0651\u064f\u0647\u064f\u06e5 \u0641\u064e\u0671\u0639\u06e1\u0628\u064f\u062f\u06e1\u0647\u064f \u0648\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u06da \u0648\u064e\u0645\u064e\u0627 \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0628\u0650\u063a\u064e\u0670\u0641\u0650\u0644\u064d \u0639\u064e\u0645\u0651\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan milik Allah meliputi rahasia langit dan bumi dan kepada-Nya segala urusan dikembalikan. Maka sembahlah Dia dan bertawakallah kepada-Nya. Dan Tuhanmu tidak akan lengah terhadap apa yang kamu kerjakan"}]},{id:12,name:"\u064a\u0648\u0633\u0641",transliteration:"Yusuf",translation:"Yusuf",type:"meccan",total_verses:111,verses:[{id:1,text:"\u0627\u0644\u0653\u0631\u06da \u062a\u0650\u0644\u06e1\u0643\u064e \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u064f \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0671\u0644\u06e1\u0645\u064f\u0628\u0650\u064a\u0646\u0650",translation:"Alif L\u0101m R\u0101`. Ini adalah ayat-ayat Kitab (Alquran) yang jelas"},{id:2,text:"\u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f \u0642\u064f\u0631\u06e1\u0621\u064e\u0670\u0646\u064b\u0627 \u0639\u064e\u0631\u064e\u0628\u0650\u064a\u0651\u0657\u0627 \u0644\u0651\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Sesungguhnya Kami menurunkannya berupa Quran berbahasa Arab, agar kamu mengerti"},{id:3,text:"\u0646\u064e\u062d\u06e1\u0646\u064f \u0646\u064e\u0642\u064f\u0635\u0651\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064e \u0671\u0644\u06e1\u0642\u064e\u0635\u064e\u0635\u0650 \u0628\u0650\u0645\u064e\u0627\u0653 \u0623\u064e\u0648\u06e1\u062d\u064e\u064a\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u064e \u0648\u064e\u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u06e6 \u0644\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u063a\u064e\u0670\u0641\u0650\u0644\u0650\u064a\u0646\u064e",translation:"Kami menceritakan kepadamu (Muhammad) kisah yang paling baik dengan mewahyukan Alquran ini kepadamu, dan sesungguhnya engkau sebelum itu termasuk orang yang tidak mengetahui"},{id:4,text:"\u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e \u064a\u064f\u0648\u0633\u064f\u0641\u064f \u0644\u0650\u0623\u064e\u0628\u0650\u064a\u0647\u0650 \u064a\u064e\u0640\u0670\u0653\u0623\u064e\u0628\u064e\u062a\u0650 \u0625\u0650\u0646\u0651\u0650\u064a \u0631\u064e\u0623\u064e\u064a\u06e1\u062a\u064f \u0623\u064e\u062d\u064e\u062f\u064e \u0639\u064e\u0634\u064e\u0631\u064e \u0643\u064e\u0648\u06e1\u0643\u064e\u0628\u0657\u0627 \u0648\u064e\u0671\u0644\u0634\u0651\u064e\u0645\u06e1\u0633\u064e \u0648\u064e\u0671\u0644\u06e1\u0642\u064e\u0645\u064e\u0631\u064e \u0631\u064e\u0623\u064e\u064a\u06e1\u062a\u064f\u0647\u064f\u0645\u06e1 \u0644\u0650\u064a \u0633\u064e\u0670\u062c\u0650\u062f\u0650\u064a\u0646\u064e",translation:"(Ingatlah), ketika Yusuf berkata kepada ayahnya, \"Wahai ayahku! Sungguh, aku (bermimpi) melihat sebelas bintang, matahari dan bulan; kulihat semuanya sujud kepadaku"},{id:5,text:"\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0670\u0628\u064f\u0646\u064e\u064a\u0651\u064e \u0644\u064e\u0627 \u062a\u064e\u0642\u06e1\u0635\u064f\u0635\u06e1 \u0631\u064f\u0621\u06e1\u064a\u064e\u0627\u0643\u064e \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0625\u0650\u062e\u06e1\u0648\u064e\u062a\u0650\u0643\u064e \u0641\u064e\u064a\u064e\u0643\u0650\u064a\u062f\u064f\u0648\u0627\u0652 \u0644\u064e\u0643\u064e \u0643\u064e\u064a\u06e1\u062f\u064b\u0627\u06d6 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u064e \u0644\u0650\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u0650 \u0639\u064e\u062f\u064f\u0648\u0651\u065e \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u065e",translation:"Dia (ayahnya) berkata, \"Wahai anakku! Janganlah engkau ceritakan mimpimu kepada saudara-saudaramu, mereka akan membuat tipu daya (untuk membinasakan)mu. Sungguh, setan itu musuh yang jelas bagi manusia"},{id:6,text:"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064e\u062c\u06e1\u062a\u064e\u0628\u0650\u064a\u0643\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0648\u064e\u064a\u064f\u0639\u064e\u0644\u0651\u0650\u0645\u064f\u0643\u064e \u0645\u0650\u0646 \u062a\u064e\u0623\u06e1\u0648\u0650\u064a\u0644\u0650 \u0671\u0644\u06e1\u0623\u064e\u062d\u064e\u0627\u062f\u0650\u064a\u062b\u0650 \u0648\u064e\u064a\u064f\u062a\u0650\u0645\u0651\u064f \u0646\u0650\u0639\u06e1\u0645\u064e\u062a\u064e\u0647\u064f\u06e5 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0648\u064e\u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0621\u064e\u0627\u0644\u0650 \u064a\u064e\u0639\u06e1\u0642\u064f\u0648\u0628\u064e \u0643\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u062a\u064e\u0645\u0651\u064e\u0647\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0628\u064e\u0648\u064e\u064a\u06e1\u0643\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064e \u0648\u064e\u0625\u0650\u0633\u06e1\u062d\u064e\u0670\u0642\u064e\u06da \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u065e",translation:"Dan demikianlah, Tuhan memilih engkau (untuk menjadi Nabi) dan mengajarkan kepadamu sebagian dari takwil mimpi dan menyempurnakan (nikmat-Nya) kepadamu dan kepada keluarga Yakub, sebagaimana Dia telah menyempurnakan nikmat-Nya kepada kedua orang kakekmu sebelum itu, (yaitu) Ibrahim dan Ishak. Sungguh, Tuhanmu Maha Mengetahui, Mahabijaksana"},{id:7,text:"\u06de\u0644\u0651\u064e\u0642\u064e\u062f\u06e1 \u0643\u064e\u0627\u0646\u064e \u0641\u0650\u064a \u064a\u064f\u0648\u0633\u064f\u0641\u064e \u0648\u064e\u0625\u0650\u062e\u06e1\u0648\u064e\u062a\u0650\u0647\u0650\u06e6\u0653 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u065e \u0644\u0651\u0650\u0644\u0633\u0651\u064e\u0627\u0653\u0626\u0650\u0644\u0650\u064a\u0646\u064e",translation:"Sungguh, dalam (kisah) Yusuf dan saudara-saudaranya terdapat tanda-tanda (kekuasaan Allah) bagi orang yang bertanya"},{id:8,text:"\u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u064a\u064f\u0648\u0633\u064f\u0641\u064f \u0648\u064e\u0623\u064e\u062e\u064f\u0648\u0647\u064f \u0623\u064e\u062d\u064e\u0628\u0651\u064f \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0628\u0650\u064a\u0646\u064e\u0627 \u0645\u0650\u0646\u0651\u064e\u0627 \u0648\u064e\u0646\u064e\u062d\u06e1\u0646\u064f \u0639\u064f\u0635\u06e1\u0628\u064e\u0629\u064c \u0625\u0650\u0646\u0651\u064e \u0623\u064e\u0628\u064e\u0627\u0646\u064e\u0627 \u0644\u064e\u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0670\u0644\u0656 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u064d",translation:"Ketika mereka berkata, \"Sesungguhnya Yusuf dan saudaranya (Bunyamin) lebih dicintai ayah daripada kita, padahal kita adalah satu golongan (yang kuat). Sungguh, ayah kita dalam kekeliruan yang nyata"},{id:9,text:"\u0671\u0642\u06e1\u062a\u064f\u0644\u064f\u0648\u0627\u0652 \u064a\u064f\u0648\u0633\u064f\u0641\u064e \u0623\u064e\u0648\u0650 \u0671\u0637\u06e1\u0631\u064e\u062d\u064f\u0648\u0647\u064f \u0623\u064e\u0631\u06e1\u0636\u0657\u0627 \u064a\u064e\u062e\u06e1\u0644\u064f \u0644\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u062c\u06e1\u0647\u064f \u0623\u064e\u0628\u0650\u064a\u0643\u064f\u0645\u06e1 \u0648\u064e\u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u0647\u0650\u06e6 \u0642\u064e\u0648\u06e1\u0645\u0657\u0627 \u0635\u064e\u0670\u0644\u0650\u062d\u0650\u064a\u0646\u064e",translation:"bunuhlah Yusuf atau buanglah dia ke suatu tempat agar perhatian ayah tercurah kepadamu, dan setelah itu kamu menjadi orang yang baik"},{id:10,text:"\u0642\u064e\u0627\u0644\u064e \u0642\u064e\u0627\u0653\u0626\u0650\u0644\u065e \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u062a\u064e\u0642\u06e1\u062a\u064f\u0644\u064f\u0648\u0627\u0652 \u064a\u064f\u0648\u0633\u064f\u0641\u064e \u0648\u064e\u0623\u064e\u0644\u06e1\u0642\u064f\u0648\u0647\u064f \u0641\u0650\u064a \u063a\u064e\u064a\u064e\u0670\u0628\u064e\u062a\u0650 \u0671\u0644\u06e1\u062c\u064f\u0628\u0651\u0650 \u064a\u064e\u0644\u06e1\u062a\u064e\u0642\u0650\u0637\u06e1\u0647\u064f \u0628\u064e\u0639\u06e1\u0636\u064f \u0671\u0644\u0633\u0651\u064e\u064a\u0651\u064e\u0627\u0631\u064e\u0629\u0650 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0641\u064e\u0670\u0639\u0650\u0644\u0650\u064a\u0646\u064e",translation:"Seorang di antara mereka berkata, \"Janganlah kamu membunuh Yusuf, tetapi jebloskan saja dia ke dasar sumur agar dia dipungut oleh sebagian musafir, jika kamu hendak berbuat"},{id:11,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u064a\u064e\u0640\u0670\u0653\u0623\u064e\u0628\u064e\u0627\u0646\u064e\u0627 \u0645\u064e\u0627 \u0644\u064e\u0643\u064e \u0644\u064e\u0627 \u062a\u064e\u0623\u06e1\u0645\u064e\u06ec\u0646\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u064a\u064f\u0648\u0633\u064f\u0641\u064e \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0647\u064f\u06e5 \u0644\u064e\u0646\u064e\u0670\u0635\u0650\u062d\u064f\u0648\u0646\u064e",translation:"Mereka berkata, \"Wahai ayah kami! Mengapa engkau tidak mempercayai kami terhadap Yusuf, padahal sesungguhnya kami semua menginginkan kebaikan baginya"},{id:12,text:"\u0623\u064e\u0631\u06e1\u0633\u0650\u0644\u06e1\u0647\u064f \u0645\u064e\u0639\u064e\u0646\u064e\u0627 \u063a\u064e\u062f\u0657\u0627 \u064a\u064e\u0631\u06e1\u062a\u064e\u0639\u06e1 \u0648\u064e\u064a\u064e\u0644\u06e1\u0639\u064e\u0628\u06e1 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0647\u064f\u06e5 \u0644\u064e\u062d\u064e\u0670\u0641\u0650\u0638\u064f\u0648\u0646\u064e",translation:"Biarkanlah dia pergi bersama kami besok pagi, agar dia bersenang-senang dan bermain-main, dan kami pasti menjaganya"},{id:13,text:"\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u064a\u064e\u062d\u06e1\u0632\u064f\u0646\u064f\u0646\u0650\u064a\u0653 \u0623\u064e\u0646 \u062a\u064e\u0630\u06e1\u0647\u064e\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6 \u0648\u064e\u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0623\u064e\u0646 \u064a\u064e\u0623\u06e1\u0643\u064f\u0644\u064e\u0647\u064f \u0671\u0644\u0630\u0651\u0650\u0626\u06e1\u0628\u064f \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0639\u064e\u0646\u06e1\u0647\u064f \u063a\u064e\u0670\u0641\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Dia (Yakub) berkata, \"Sesungguhnya kepergian kamu bersama dia (Yusuf) sangat menyedihkanku dan aku khawatir dia dimakan serigala, sedang kamu lengah darinya"},{id:14,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0626\u0650\u0646\u06e1 \u0623\u064e\u0643\u064e\u0644\u064e\u0647\u064f \u0671\u0644\u0630\u0651\u0650\u0626\u06e1\u0628\u064f \u0648\u064e\u0646\u064e\u062d\u06e1\u0646\u064f \u0639\u064f\u0635\u06e1\u0628\u064e\u0629\u064c \u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0625\u0650\u0630\u0657\u0627 \u0644\u0651\u064e\u062e\u064e\u0670\u0633\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Sesungguhnya mereka berkata, \"Jika dia dimakan serigala, padahal kami kelompok (yang kuat), maka tentu kami menjadi orang-orang yang merugi"},{id:15,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0630\u064e\u0647\u064e\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6 \u0648\u064e\u0623\u064e\u062c\u06e1\u0645\u064e\u0639\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646 \u064a\u064e\u062c\u06e1\u0639\u064e\u0644\u064f\u0648\u0647\u064f \u0641\u0650\u064a \u063a\u064e\u064a\u064e\u0670\u0628\u064e\u062a\u0650 \u0671\u0644\u06e1\u062c\u064f\u0628\u0651\u0650\u06da \u0648\u064e\u0623\u064e\u0648\u06e1\u062d\u064e\u064a\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0644\u064e\u062a\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064e\u0646\u0651\u064e\u0647\u064f\u0645 \u0628\u0650\u0623\u064e\u0645\u06e1\u0631\u0650\u0647\u0650\u0645\u06e1 \u0647\u064e\u0670\u0630\u064e\u0627 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0634\u06e1\u0639\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Maka ketika mereka membawanya dan sepakat memasukkan dia ke dasar sumur, Kami wahyukan kepadanya, \"Engkau kelak pasti akan menceritakan perbuatan ini kepada mereka, sedang mereka tidak menyadari"},{id:16,text:"\u0648\u064e\u062c\u064e\u0627\u0653\u0621\u064f\u0648\u0653 \u0623\u064e\u0628\u064e\u0627\u0647\u064f\u0645\u06e1 \u0639\u0650\u0634\u064e\u0627\u0653\u0621\u0657 \u064a\u064e\u0628\u06e1\u0643\u064f\u0648\u0646\u064e",translation:"Kemudian mereka datang kepada ayah mereka pada petang hari sambil menangis"},{id:17,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u064a\u064e\u0640\u0670\u0653\u0623\u064e\u0628\u064e\u0627\u0646\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0627 \u0630\u064e\u0647\u064e\u0628\u06e1\u0646\u064e\u0627 \u0646\u064e\u0633\u06e1\u062a\u064e\u0628\u0650\u0642\u064f \u0648\u064e\u062a\u064e\u0631\u064e\u0643\u06e1\u0646\u064e\u0627 \u064a\u064f\u0648\u0633\u064f\u0641\u064e \u0639\u0650\u0646\u062f\u064e \u0645\u064e\u062a\u064e\u0670\u0639\u0650\u0646\u064e\u0627 \u0641\u064e\u0623\u064e\u0643\u064e\u0644\u064e\u0647\u064f \u0671\u0644\u0630\u0651\u0650\u0626\u06e1\u0628\u064f\u06d6 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064e \u0628\u0650\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0656 \u0644\u0651\u064e\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0648\u06e1 \u0643\u064f\u0646\u0651\u064e\u0627 \u0635\u064e\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Mereka berkata, \"Wahai ayah kami! Sesungguhnya kami pergi berlomba dan kami tinggalkan Yusuf di dekat barang-barang kami, lalu dia dimakan serigala; dan engkau tentu tidak akan percaya kepada kami, sekalipun kami berkata benar"},{id:18,text:"\u0648\u064e\u062c\u064e\u0627\u0653\u0621\u064f\u0648 \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064e\u0645\u0650\u064a\u0635\u0650\u0647\u0650\u06e6 \u0628\u0650\u062f\u064e\u0645\u0656 \u0643\u064e\u0630\u0650\u0628\u0656\u06da \u0642\u064e\u0627\u0644\u064e \u0628\u064e\u0644\u06e1 \u0633\u064e\u0648\u0651\u064e\u0644\u064e\u062a\u06e1 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u0646\u0641\u064f\u0633\u064f\u0643\u064f\u0645\u06e1 \u0623\u064e\u0645\u06e1\u0631\u0657\u0627\u06d6 \u0641\u064e\u0635\u064e\u0628\u06e1\u0631\u065e \u062c\u064e\u0645\u0650\u064a\u0644\u065e\u06d6 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u0645\u064f\u0633\u06e1\u062a\u064e\u0639\u064e\u0627\u0646\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u062a\u064e\u0635\u0650\u0641\u064f\u0648\u0646\u064e",translation:"Dan mereka datang membawa baju gamisnya (yang berlumuran) darah palsu. Dia (Yakub) berkata, \"Sebenarnya hanya dirimu sendirilah yang memandang baik urusan yang buruk itu; maka hanya bersabar itulah yang terbaik (bagiku). Dan kepada Allah saja tempat memohon pertolongan-Nya terhadap apa yang kamu ceritakan"},{id:19,text:"\u0648\u064e\u062c\u064e\u0627\u0653\u0621\u064e\u062a\u06e1 \u0633\u064e\u064a\u0651\u064e\u0627\u0631\u064e\u0629\u065e \u0641\u064e\u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u064f\u0648\u0627\u0652 \u0648\u064e\u0627\u0631\u0650\u062f\u064e\u0647\u064f\u0645\u06e1 \u0641\u064e\u0623\u064e\u062f\u06e1\u0644\u064e\u0649\u0670 \u062f\u064e\u0644\u06e1\u0648\u064e\u0647\u064f\u06e5\u06d6 \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0670\u0628\u064f\u0634\u06e1\u0631\u064e\u0649\u0670 \u0647\u064e\u0670\u0630\u064e\u0627 \u063a\u064f\u0644\u064e\u0670\u0645\u065e\u06da \u0648\u064e\u0623\u064e\u0633\u064e\u0631\u0651\u064f\u0648\u0647\u064f \u0628\u0650\u0636\u064e\u0670\u0639\u064e\u0629\u0657\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064f\u06e2 \u0628\u0650\u0645\u064e\u0627 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan datanglah sekelompok musafir, mereka menyuruh seorang pengambil air. Lalu dia menurunkan timbanya. Dia berkata, \"Oh, senangnya, ini ada seorang anak muda!\" Kemudian mereka menyembunyikannya sebagai barang dagangan. Dan Allah Maha Mengetahui apa yang mereka kerjakan"},{id:20,text:"\u0648\u064e\u0634\u064e\u0631\u064e\u0648\u06e1\u0647\u064f \u0628\u0650\u062b\u064e\u0645\u064e\u0646\u0650\u06ed \u0628\u064e\u062e\u06e1\u0633\u0656 \u062f\u064e\u0631\u064e\u0670\u0647\u0650\u0645\u064e \u0645\u064e\u0639\u06e1\u062f\u064f\u0648\u062f\u064e\u0629\u0656 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0647\u0650 \u0645\u0650\u0646\u064e \u0671\u0644\u0632\u0651\u064e\u0640\u0670\u0647\u0650\u062f\u0650\u064a\u0646\u064e",translation:"Dan mereka menjualnya (Yusuf) dengan harga murah, yaitu beberapa dirham saja, sebab mereka tidak tertarik kepadanya"},{id:21,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0671\u0634\u06e1\u062a\u064e\u0631\u064e\u0649\u0670\u0647\u064f \u0645\u0650\u0646 \u0645\u0651\u0650\u0635\u06e1\u0631\u064e \u0644\u0650\u0671\u0645\u06e1\u0631\u064e\u0623\u064e\u062a\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0643\u06e1\u0631\u0650\u0645\u0650\u064a \u0645\u064e\u062b\u06e1\u0648\u064e\u0649\u0670\u0647\u064f \u0639\u064e\u0633\u064e\u0649\u0670\u0653 \u0623\u064e\u0646 \u064a\u064e\u0646\u0641\u064e\u0639\u064e\u0646\u064e\u0627\u0653 \u0623\u064e\u0648\u06e1 \u0646\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064e\u0647\u064f\u06e5 \u0648\u064e\u0644\u064e\u062f\u0657\u0627\u06da \u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u064e\u0643\u0651\u064e\u0646\u0651\u064e\u0627 \u0644\u0650\u064a\u064f\u0648\u0633\u064f\u0641\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0644\u0650\u0646\u064f\u0639\u064e\u0644\u0651\u0650\u0645\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646 \u062a\u064e\u0623\u06e1\u0648\u0650\u064a\u0644\u0650 \u0671\u0644\u06e1\u0623\u064e\u062d\u064e\u0627\u062f\u0650\u064a\u062b\u0650\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0627\u0644\u0650\u0628\u064c \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0645\u06e1\u0631\u0650\u0647\u0650\u06e6 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"(Dan orang dari Mesir yang membelinya berkata kepada istrinya,410) \"Berikanlah kepadanya tempat (dan layanan) yang baik, mudah-mudahan dia bermanfaat bagi kita atau kita pungut dia sebagai anak.\" Dan demikianlah Kami memberikan kedudukan yang baik kepada Yusuf di negeri (Mesir), dan agar Kami ajarkan kepadanya takwil mimpi. Dan Allah berkuasa terhadap urusan-Nya, tetapi kebanyakan manusia tidak mengerti"},{id:22,text:"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0628\u064e\u0644\u064e\u063a\u064e \u0623\u064e\u0634\u064f\u062f\u0651\u064e\u0647\u064f\u06e5\u0653 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f \u062d\u064f\u0643\u06e1\u0645\u0657\u0627 \u0648\u064e\u0639\u0650\u0644\u06e1\u0645\u0657\u0627\u06da \u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u062c\u06e1\u0632\u0650\u064a \u0671\u0644\u06e1\u0645\u064f\u062d\u06e1\u0633\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dan ketika dia telah cukup dewasa Kami berikan kepadanya kekuasaan dan ilmu. Demikianlah Kami memberi balasan kepada orang-orang yang berbuat baik"},{id:23,text:"\u0648\u064e\u0631\u064e\u0670\u0648\u064e\u062f\u064e\u062a\u06e1\u0647\u064f \u0671\u0644\u0651\u064e\u062a\u0650\u064a \u0647\u064f\u0648\u064e \u0641\u0650\u064a \u0628\u064e\u064a\u06e1\u062a\u0650\u0647\u064e\u0627 \u0639\u064e\u0646 \u0646\u0651\u064e\u0641\u06e1\u0633\u0650\u0647\u0650\u06e6 \u0648\u064e\u063a\u064e\u0644\u0651\u064e\u0642\u064e\u062a\u0650 \u0671\u0644\u06e1\u0623\u064e\u0628\u06e1\u0648\u064e\u0670\u0628\u064e \u0648\u064e\u0642\u064e\u0627\u0644\u064e\u062a\u06e1 \u0647\u064e\u064a\u06e1\u062a\u064e \u0644\u064e\u0643\u064e\u06da \u0642\u064e\u0627\u0644\u064e \u0645\u064e\u0639\u064e\u0627\u0630\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0631\u064e\u0628\u0651\u0650\u064a\u0653 \u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064e \u0645\u064e\u062b\u06e1\u0648\u064e\u0627\u064a\u064e\u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0627 \u064a\u064f\u0641\u06e1\u0644\u0650\u062d\u064f \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Dan perempuan yang dia (Yusuf) tinggal di rumahnya menggoda dirinya. Lalu dia menutup pintu-pintu, seraya berkata, \"Marilah mendekat kepadaku.\" Yusuf berkata, \"Aku berlindung kepada Allah, sungguh, tuanku telah memperlakukan aku dengan baik.\" Sesungguhnya orang yang zalim itu tidak akan beruntung"},{id:24,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0647\u064e\u0645\u0651\u064e\u062a\u06e1 \u0628\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u0647\u064e\u0645\u0651\u064e \u0628\u0650\u0647\u064e\u0627 \u0644\u064e\u0648\u06e1\u0644\u064e\u0627\u0653 \u0623\u064e\u0646 \u0631\u0651\u064e\u0621\u064e\u0627 \u0628\u064f\u0631\u06e1\u0647\u064e\u0670\u0646\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u06e6\u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u0650\u0646\u064e\u0635\u06e1\u0631\u0650\u0641\u064e \u0639\u064e\u0646\u06e1\u0647\u064f \u0671\u0644\u0633\u0651\u064f\u0648\u0653\u0621\u064e \u0648\u064e\u0671\u0644\u06e1\u0641\u064e\u062d\u06e1\u0634\u064e\u0627\u0653\u0621\u064e\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646\u06e1 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0646\u064e\u0627 \u0671\u0644\u06e1\u0645\u064f\u062e\u06e1\u0644\u064e\u0635\u0650\u064a\u0646\u064e",translation:"Dan Sungguh, perempuan itu telah berhasrat kepadanya (Yusuf). Dan Yusuf pun berkehendak kepadanya, sekiranya dia tidak melihat tanda (dari) Tuhannya.411) Demikianlah, Kami palingkan darinya keburukan dan kekejian. Sungguh, dia (Yusuf) termasuk hamba Kami yang terpilih"},{id:25,text:"\u0648\u064e\u0671\u0633\u06e1\u062a\u064e\u0628\u064e\u0642\u064e\u0627 \u0671\u0644\u06e1\u0628\u064e\u0627\u0628\u064e \u0648\u064e\u0642\u064e\u062f\u0651\u064e\u062a\u06e1 \u0642\u064e\u0645\u0650\u064a\u0635\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646 \u062f\u064f\u0628\u064f\u0631\u0656 \u0648\u064e\u0623\u064e\u0644\u06e1\u0641\u064e\u064a\u064e\u0627 \u0633\u064e\u064a\u0651\u0650\u062f\u064e\u0647\u064e\u0627 \u0644\u064e\u062f\u064e\u0627 \u0671\u0644\u06e1\u0628\u064e\u0627\u0628\u0650\u06da \u0642\u064e\u0627\u0644\u064e\u062a\u06e1 \u0645\u064e\u0627 \u062c\u064e\u0632\u064e\u0627\u0653\u0621\u064f \u0645\u064e\u0646\u06e1 \u0623\u064e\u0631\u064e\u0627\u062f\u064e \u0628\u0650\u0623\u064e\u0647\u06e1\u0644\u0650\u0643\u064e \u0633\u064f\u0648\u0653\u0621\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u064a\u064f\u0633\u06e1\u062c\u064e\u0646\u064e \u0623\u064e\u0648\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Dan keduanya berlomba menuju pintu dan perempuan itu menarik baju gamisnya (Yusuf) dari belakang hingga koyak dan keduanya mendapati suami perempuan itu di depan pintu. Dia (perempuan itu) berkata, \"Apakah balasan (yang pantas) terhadap orang yang bermaksud buruk terhadap istrimu, selain dipenjarakan atau (dihukum) dengan siksa yang pedih"},{id:26,text:"\u0642\u064e\u0627\u0644\u064e \u0647\u0650\u064a\u064e \u0631\u064e\u0670\u0648\u064e\u062f\u064e\u062a\u06e1\u0646\u0650\u064a \u0639\u064e\u0646 \u0646\u0651\u064e\u0641\u06e1\u0633\u0650\u064a\u06da \u0648\u064e\u0634\u064e\u0647\u0650\u062f\u064e \u0634\u064e\u0627\u0647\u0650\u062f\u065e \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u0647\u06e1\u0644\u0650\u0647\u064e\u0627\u0653 \u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064e \u0642\u064e\u0645\u0650\u064a\u0635\u064f\u0647\u064f\u06e5 \u0642\u064f\u062f\u0651\u064e \u0645\u0650\u0646 \u0642\u064f\u0628\u064f\u0644\u0656 \u0641\u064e\u0635\u064e\u062f\u064e\u0642\u064e\u062a\u06e1 \u0648\u064e\u0647\u064f\u0648\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0643\u064e\u0670\u0630\u0650\u0628\u0650\u064a\u0646\u064e",translation:"Dia (Yusuf) berkata, \"Dia yang menggodaku dan merayu diriku.\" seorang saksi dari keluarga perempuan itu memberikan kesaksian, \"Jika baju gamisnya koyak di bagian depan, maka peerempuan itu benar, dan dia (Yusuf) termasuk orang yang dusta"},{id:27,text:"\u0648\u064e\u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064e \u0642\u064e\u0645\u0650\u064a\u0635\u064f\u0647\u064f\u06e5 \u0642\u064f\u062f\u0651\u064e \u0645\u0650\u0646 \u062f\u064f\u0628\u064f\u0631\u0656 \u0641\u064e\u0643\u064e\u0630\u064e\u0628\u064e\u062a\u06e1 \u0648\u064e\u0647\u064f\u0648\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Dan jika baju gamisnya koyak di bagian belakang, maka perempuan itulah yang dusta, dan dia (Yusuf) termasuk orang yang benar"},{id:28,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0631\u064e\u0621\u064e\u0627 \u0642\u064e\u0645\u0650\u064a\u0635\u064e\u0647\u064f\u06e5 \u0642\u064f\u062f\u0651\u064e \u0645\u0650\u0646 \u062f\u064f\u0628\u064f\u0631\u0656 \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646 \u0643\u064e\u064a\u06e1\u062f\u0650\u0643\u064f\u0646\u0651\u064e\u06d6 \u0625\u0650\u0646\u0651\u064e \u0643\u064e\u064a\u06e1\u062f\u064e\u0643\u064f\u0646\u0651\u064e \u0639\u064e\u0638\u0650\u064a\u0645\u065e",translation:"Maka ketika dia (suami perempuan itu) melihat baju gamisnya (Yusuf) koyak di bagian belakang, dia berkata, \"Sesungguhnya ini adalah tipu dayamu. Tipu dayamu benar-benar hebat"},{id:29,text:"\u064a\u064f\u0648\u0633\u064f\u0641\u064f \u0623\u064e\u0639\u06e1\u0631\u0650\u0636\u06e1 \u0639\u064e\u0646\u06e1 \u0647\u064e\u0670\u0630\u064e\u0627\u06da \u0648\u064e\u0671\u0633\u06e1\u062a\u064e\u063a\u06e1\u0641\u0650\u0631\u0650\u064a \u0644\u0650\u0630\u064e\u0646\u06e2\u0628\u0650\u0643\u0650\u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u0650 \u0643\u064f\u0646\u062a\u0650 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u062e\u064e\u0627\u0637\u0650\u0640\u0654\u0650\u064a\u0646\u064e",translation:"Wahai Yusuf! \"Lupakanlah ini, dan (istriku) mohonlah ampunan atas dosamu, karena engkau termasuk orang yang bersalah"},{id:30,text:"\u06de\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0646\u0650\u0633\u06e1\u0648\u064e\u0629\u065e \u0641\u0650\u064a \u0671\u0644\u06e1\u0645\u064e\u062f\u0650\u064a\u0646\u064e\u0629\u0650 \u0671\u0645\u06e1\u0631\u064e\u0623\u064e\u062a\u064f \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u0650 \u062a\u064f\u0631\u064e\u0670\u0648\u0650\u062f\u064f \u0641\u064e\u062a\u064e\u0649\u0670\u0647\u064e\u0627 \u0639\u064e\u0646 \u0646\u0651\u064e\u0641\u06e1\u0633\u0650\u0647\u0650\u06e6\u06d6 \u0642\u064e\u062f\u06e1 \u0634\u064e\u063a\u064e\u0641\u064e\u0647\u064e\u0627 \u062d\u064f\u0628\u0651\u064b\u0627\u06d6 \u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0646\u064e\u0631\u064e\u0649\u0670\u0647\u064e\u0627 \u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0670\u0644\u0656 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u0656",translation:"Dan perempuan-perempuan di kota berkata, \"Istri Al-Aziz menggoda dan merayu pelayannya untuk menundukkan dirinya, pelayannya benar-benar membuatnya mabuk cinta. Kami pasti memandang dia dalam kesesatan yang nyata"},{id:31,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0633\u064e\u0645\u0650\u0639\u064e\u062a\u06e1 \u0628\u0650\u0645\u064e\u0643\u06e1\u0631\u0650\u0647\u0650\u0646\u0651\u064e \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u064e\u062a\u06e1 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u0646\u0651\u064e \u0648\u064e\u0623\u064e\u0639\u06e1\u062a\u064e\u062f\u064e\u062a\u06e1 \u0644\u064e\u0647\u064f\u0646\u0651\u064e \u0645\u064f\u062a\u0651\u064e\u0643\u064e\u0640\u0654\u0657\u0627 \u0648\u064e\u0621\u064e\u0627\u062a\u064e\u062a\u06e1 \u0643\u064f\u0644\u0651\u064e \u0648\u064e\u0670\u062d\u0650\u062f\u064e\u0629\u0656 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0646\u0651\u064e \u0633\u0650\u0643\u0651\u0650\u064a\u0646\u0657\u0627 \u0648\u064e\u0642\u064e\u0627\u0644\u064e\u062a\u0650 \u0671\u062e\u06e1\u0631\u064f\u062c\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0646\u0651\u064e\u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0631\u064e\u0623\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u0643\u06e1\u0628\u064e\u0631\u06e1\u0646\u064e\u0647\u064f\u06e5 \u0648\u064e\u0642\u064e\u0637\u0651\u064e\u0639\u06e1\u0646\u064e \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u064e\u0647\u064f\u0646\u0651\u064e \u0648\u064e\u0642\u064f\u0644\u06e1\u0646\u064e \u062d\u064e\u0670\u0634\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0647\u064e\u0670\u0630\u064e\u0627 \u0628\u064e\u0634\u064e\u0631\u064b\u0627 \u0625\u0650\u0646\u06e1 \u0647\u064e\u0670\u0630\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0644\u064e\u0643\u065e \u0643\u064e\u0631\u0650\u064a\u0645\u065e",translation:"Maka ketika perempuan itu mendengar cercaan mereka, diundangnyalah perempuan-perempuan itu dan disediakannya tempat duduk bagi mereka, dan kepada masing-masing mereka diberikan sebilah pisau (untuk memotong jamuan), kemudian dia berkata (kepada Yusuf), \"Keluarlah (tampakkanlah dirimu) kepada mereka.\" Ketika perempuan-perempuan itu melihatnya, mereka terpesona kepada (keelokan rupa)nya, dan mereka (tanpa sadar) melukai tangannya sendiri. Seraya berkata, \"Mahasempurna Allah, ini bukanlah manusia. Ini benar-benar malaikat yang mulia"},{id:32,text:"\u0642\u064e\u0627\u0644\u064e\u062a\u06e1 \u0641\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0644\u064f\u0645\u06e1\u062a\u064f\u0646\u0651\u064e\u0646\u0650\u064a \u0641\u0650\u064a\u0647\u0650\u06d6 \u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0631\u064e\u0670\u0648\u064e\u062f\u062a\u0651\u064f\u0647\u064f\u06e5 \u0639\u064e\u0646 \u0646\u0651\u064e\u0641\u06e1\u0633\u0650\u0647\u0650\u06e6 \u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u0639\u06e1\u0635\u064e\u0645\u064e\u06d6 \u0648\u064e\u0644\u064e\u0626\u0650\u0646 \u0644\u0651\u064e\u0645\u06e1 \u064a\u064e\u0641\u06e1\u0639\u064e\u0644\u06e1 \u0645\u064e\u0627\u0653 \u0621\u064e\u0627\u0645\u064f\u0631\u064f\u0647\u064f\u06e5 \u0644\u064e\u064a\u064f\u0633\u06e1\u062c\u064e\u0646\u064e\u0646\u0651\u064e \u0648\u064e\u0644\u064e\u064a\u064e\u0643\u064f\u0648\u0646\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u063a\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dia (istri Al-Aziz) berkata, \"Itulah orangnya yang menyebabkan kamu mencela aku karena (aku tertarik) kepadanya, dan sungguh, aku telah menggoda untuk menundukkan dirinya tetapi dia menolak. Jika dia tidak melakukan apa yang aku perintahkan kepadanya, niscaya dia akan dipenjarakan, dan dia akan menjadi orang yang hina"},{id:33,text:"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0671\u0644\u0633\u0651\u0650\u062c\u06e1\u0646\u064f \u0623\u064e\u062d\u064e\u0628\u0651\u064f \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0645\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e\u0646\u0650\u064a\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u06d6 \u0648\u064e\u0625\u0650\u0644\u0651\u064e\u0627 \u062a\u064e\u0635\u06e1\u0631\u0650\u0641\u06e1 \u0639\u064e\u0646\u0651\u0650\u064a \u0643\u064e\u064a\u06e1\u062f\u064e\u0647\u064f\u0646\u0651\u064e \u0623\u064e\u0635\u06e1\u0628\u064f \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u0646\u0651\u064e \u0648\u064e\u0623\u064e\u0643\u064f\u0646 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u062c\u064e\u0670\u0647\u0650\u0644\u0650\u064a\u0646\u064e",translation:"Yusuf berkata, \"Wahai Tuhanku! Penjara lebih aku sukai daripada memenuhi ajakan mereka. Jika aku tidak Engkau hindarkan dari tipu daya mereka, niscaya aku akan cenderung untuk (memenuhi keinginan mereka) dan tentu aku termasuk orang yang bodoh"},{id:34,text:"\u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u062c\u064e\u0627\u0628\u064e \u0644\u064e\u0647\u064f\u06e5 \u0631\u064e\u0628\u0651\u064f\u0647\u064f\u06e5 \u0641\u064e\u0635\u064e\u0631\u064e\u0641\u064e \u0639\u064e\u0646\u06e1\u0647\u064f \u0643\u064e\u064a\u06e1\u062f\u064e\u0647\u064f\u0646\u0651\u064e\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0647\u064f\u0648\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u0650\u064a\u0639\u064f \u0671\u0644\u06e1\u0639\u064e\u0644\u0650\u064a\u0645\u064f",translation:"Maka Tuhan memperkenankan doa Yusuf, dan Dia menghindarkan Yusuf dari tipu daya mereka. Dialah Yang Maha Mendengar, Maha Mengetahui"},{id:35,text:"\u062b\u064f\u0645\u0651\u064e \u0628\u064e\u062f\u064e\u0627 \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0645\u064e\u0627 \u0631\u064e\u0623\u064e\u0648\u064f\u0627\u0652 \u0671\u0644\u06e1\u0623\u0653\u064a\u064e\u0670\u062a\u0650 \u0644\u064e\u064a\u064e\u0633\u06e1\u062c\u064f\u0646\u064f\u0646\u0651\u064e\u0647\u064f\u06e5 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062d\u0650\u064a\u0646\u0656",translation:"Kemudian timbul pikiran pada mereka setelah melihat tanda-tanda (kebenaran Yusuf) bahwa mereka harus memenjarakannya sampai waktu tertentu"},{id:36,text:"\u0648\u064e\u062f\u064e\u062e\u064e\u0644\u064e \u0645\u064e\u0639\u064e\u0647\u064f \u0671\u0644\u0633\u0651\u0650\u062c\u06e1\u0646\u064e \u0641\u064e\u062a\u064e\u064a\u064e\u0627\u0646\u0650\u06d6 \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u062d\u064e\u062f\u064f\u0647\u064f\u0645\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064e\u0631\u064e\u0649\u0670\u0646\u0650\u064a\u0653 \u0623\u064e\u0639\u06e1\u0635\u0650\u0631\u064f \u062e\u064e\u0645\u06e1\u0631\u0657\u0627\u06d6 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u06e1\u0623\u0653\u062e\u064e\u0631\u064f \u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064e\u0631\u064e\u0649\u0670\u0646\u0650\u064a\u0653 \u0623\u064e\u062d\u06e1\u0645\u0650\u0644\u064f \u0641\u064e\u0648\u06e1\u0642\u064e \u0631\u064e\u0623\u06e1\u0633\u0650\u064a \u062e\u064f\u0628\u06e1\u0632\u0657\u0627 \u062a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f \u0671\u0644\u0637\u0651\u064e\u064a\u06e1\u0631\u064f \u0645\u0650\u0646\u06e1\u0647\u064f\u06d6 \u0646\u064e\u0628\u0651\u0650\u0626\u06e1\u0646\u064e\u0627 \u0628\u0650\u062a\u064e\u0623\u06e1\u0648\u0650\u064a\u0644\u0650\u0647\u0650\u06e6\u0653\u06d6 \u0625\u0650\u0646\u0651\u064e\u0627 \u0646\u064e\u0631\u064e\u0649\u0670\u0643\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u062d\u06e1\u0633\u0650\u0646\u0650\u064a\u0646\u064e",translation:"(Dan bersama dia masuk pula dua orang pemuda ke dalam penjara.412) Salah satunya berkata, \"Sesungguhnya aku bermimpi memeras anggur,\" dan yang lainnya berkata, \"Aku bermimpi, membawa roti di atas kepalaku, sebagiannya dimakan burung.\" Berikanlah kepada kami takwilnya. Sesungguhnya kami memandangmu termasuk orang yang berbuat baik"},{id:37,text:"\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0627 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u0643\u064f\u0645\u064e\u0627 \u0637\u064e\u0639\u064e\u0627\u0645\u065e \u062a\u064f\u0631\u06e1\u0632\u064e\u0642\u064e\u0627\u0646\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0646\u064e\u0628\u0651\u064e\u0623\u06e1\u062a\u064f\u0643\u064f\u0645\u064e\u0627 \u0628\u0650\u062a\u064e\u0623\u06e1\u0648\u0650\u064a\u0644\u0650\u0647\u0650\u06e6 \u0642\u064e\u0628\u06e1\u0644\u064e \u0623\u064e\u0646 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e\u0643\u064f\u0645\u064e\u0627\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u064e\u0627 \u0645\u0650\u0645\u0651\u064e\u0627 \u0639\u064e\u0644\u0651\u064e\u0645\u064e\u0646\u0650\u064a \u0631\u064e\u0628\u0651\u0650\u064a\u0653\u06da \u0625\u0650\u0646\u0651\u0650\u064a \u062a\u064e\u0631\u064e\u0643\u06e1\u062a\u064f \u0645\u0650\u0644\u0651\u064e\u0629\u064e \u0642\u064e\u0648\u06e1\u0645\u0656 \u0644\u0651\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0647\u064f\u0645\u06e1 \u0643\u064e\u0670\u0641\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Dia (Yusuf) berkata, \"Makanan apa pun yang akan diberikan kepadamu berdua aku telah dapat menerangkan takwilnya, sebelum (makanan) itu sampai kepadamu. Itu sebagian dari yang diajarkan Tuhan kepadaku. Sesungguhnya aku telah meninggalkan agama orang-orang yang tidak beriman kepada Allah, bahkan mereka tidak percaya kepada hari akhirat"},{id:38,text:"\u0648\u064e\u0671\u062a\u0651\u064e\u0628\u064e\u0639\u06e1\u062a\u064f \u0645\u0650\u0644\u0651\u064e\u0629\u064e \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0621\u0650\u064a\u0653 \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064e \u0648\u064e\u0625\u0650\u0633\u06e1\u062d\u064e\u0670\u0642\u064e \u0648\u064e\u064a\u064e\u0639\u06e1\u0642\u064f\u0648\u0628\u064e\u06da \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0646\u064e\u0627\u0653 \u0623\u064e\u0646 \u0646\u0651\u064f\u0634\u06e1\u0631\u0650\u0643\u064e \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646 \u0634\u064e\u064a\u06e1\u0621\u0656\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u0650\u0646 \u0641\u064e\u0636\u06e1\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0627 \u064a\u064e\u0634\u06e1\u0643\u064f\u0631\u064f\u0648\u0646\u064e",translation:"dan aku mengikuti agama nenek moyangku: Ibrahim, Ishak dan Yakub. Tidak pantas bagi kami (para nabi) mempersekutukan sesuatu apa pun dengan Allah. Itu adalah karunia dari Allah kepada kami dan kepada manusia (semuanya); tetapi kebanyakan manusia tidak bersyukur"},{id:39,text:"\u064a\u064e\u0670\u0635\u064e\u0670\u062d\u0650\u0628\u064e\u064a\u0650 \u0671\u0644\u0633\u0651\u0650\u062c\u06e1\u0646\u0650 \u0621\u064e\u0623\u064e\u0631\u06e1\u0628\u064e\u0627\u0628\u065e \u0645\u0651\u064f\u062a\u064e\u0641\u064e\u0631\u0651\u0650\u0642\u064f\u0648\u0646\u064e \u062e\u064e\u064a\u06e1\u0631\u064c \u0623\u064e\u0645\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u0648\u064e\u0670\u062d\u0650\u062f\u064f \u0671\u0644\u06e1\u0642\u064e\u0647\u0651\u064e\u0627\u0631\u064f",translation:"Wahai kedua penghuni penjara! Manakah yang baik, tuhan-tuhan yang bermacam-macam itu ataukah Allah Yang Maha Esa, Mahaperkasa"},{id:40,text:"\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0633\u06e1\u0645\u064e\u0627\u0653\u0621\u0657 \u0633\u064e\u0645\u0651\u064e\u064a\u06e1\u062a\u064f\u0645\u064f\u0648\u0647\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0648\u064e\u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0624\u064f\u0643\u064f\u0645 \u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0647\u064e\u0627 \u0645\u0650\u0646 \u0633\u064f\u0644\u06e1\u0637\u064e\u0670\u0646\u064d\u06da \u0625\u0650\u0646\u0650 \u0671\u0644\u06e1\u062d\u064f\u0643\u06e1\u0645\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0645\u064e\u0631\u064e \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0625\u0650\u064a\u0651\u064e\u0627\u0647\u064f\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u064f \u0671\u0644\u06e1\u0642\u064e\u064a\u0651\u0650\u0645\u064f \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Apa yang kamu sembah selain Dia, hanyalah nama-nama yang kamu buat-buat, baik oleh kamu sendiri maupun oleh nenek moyangmu. Allah tidak menurunkan suatu keterangan pun tentang hal (nama-nama) itu. Keputusan itu hanyalah milik Allah. Dia telah memerintahkan agar kamu tidak menyembah selain Dia. Itulah agama yang lurus, tetapi kebanyakan manusia tidak mengetahui"},{id:41,text:"\u064a\u064e\u0670\u0635\u064e\u0670\u062d\u0650\u0628\u064e\u064a\u0650 \u0671\u0644\u0633\u0651\u0650\u062c\u06e1\u0646\u0650 \u0623\u064e\u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u062d\u064e\u062f\u064f\u0643\u064f\u0645\u064e\u0627 \u0641\u064e\u064a\u064e\u0633\u06e1\u0642\u0650\u064a \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u06e5 \u062e\u064e\u0645\u06e1\u0631\u0657\u0627\u06d6 \u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0671\u0644\u06e1\u0623\u0653\u062e\u064e\u0631\u064f \u0641\u064e\u064a\u064f\u0635\u06e1\u0644\u064e\u0628\u064f \u0641\u064e\u062a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f \u0671\u0644\u0637\u0651\u064e\u064a\u06e1\u0631\u064f \u0645\u0650\u0646 \u0631\u0651\u064e\u0623\u06e1\u0633\u0650\u0647\u0650\u06e6\u06da \u0642\u064f\u0636\u0650\u064a\u064e \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0631\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0641\u0650\u064a\u0647\u0650 \u062a\u064e\u0633\u06e1\u062a\u064e\u0641\u06e1\u062a\u0650\u064a\u064e\u0627\u0646\u0650",translation:"Wahai kedua penghuni penjara, \"Salah seorang di antara kamu, akan bertugas menyediakan minuman khamar bagi tuannya. Adapun yang seorang lagi dia akan disalib, lalu burung memakan sebagian kepalanya. Telah terjawab perkara yang kamu tanyakan (kepadaku)"},{id:42,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a \u0638\u064e\u0646\u0651\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u06e5 \u0646\u064e\u0627\u062c\u0656 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u064e\u0627 \u0671\u0630\u06e1\u0643\u064f\u0631\u06e1\u0646\u0650\u064a \u0639\u0650\u0646\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0641\u064e\u0623\u064e\u0646\u0633\u064e\u0649\u0670\u0647\u064f \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u064f \u0630\u0650\u0643\u06e1\u0631\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u06e6 \u0641\u064e\u0644\u064e\u0628\u0650\u062b\u064e \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u0650\u062c\u06e1\u0646\u0650 \u0628\u0650\u0636\u06e1\u0639\u064e \u0633\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dan dia (Yusuf) berkata kepada orang yang diketahuinya akan selamat di antara mereka berdua, \"Terangkanlah keadaanku kepada tuanmu.\" Maka setan menjadikan dia lupa untuk menerangkan (keadaan Yusuf) kepada tuannya. Karena itu dia (Yusuf) tetap dalam penjara beberapa tahun lamanya"},{id:43,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u06e1\u0645\u064e\u0644\u0650\u0643\u064f \u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064e\u0631\u064e\u0649\u0670 \u0633\u064e\u0628\u06e1\u0639\u064e \u0628\u064e\u0642\u064e\u0631\u064e\u0670\u062a\u0656 \u0633\u0650\u0645\u064e\u0627\u0646\u0656 \u064a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f\u0647\u064f\u0646\u0651\u064e \u0633\u064e\u0628\u06e1\u0639\u064c \u0639\u0650\u062c\u064e\u0627\u0641\u065e \u0648\u064e\u0633\u064e\u0628\u06e1\u0639\u064e \u0633\u064f\u0646\u06e2\u0628\u064f\u0644\u064e\u0670\u062a\u064d \u062e\u064f\u0636\u06e1\u0631\u0656 \u0648\u064e\u0623\u064f\u062e\u064e\u0631\u064e \u064a\u064e\u0627\u0628\u0650\u0633\u064e\u0670\u062a\u0656\u06d6 \u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0623\u064f \u0623\u064e\u0641\u06e1\u062a\u064f\u0648\u0646\u0650\u064a \u0641\u0650\u064a \u0631\u064f\u0621\u06e1\u064a\u064e\u0670\u064a\u064e \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0644\u0650\u0644\u0631\u0651\u064f\u0621\u06e1\u064a\u064e\u0627 \u062a\u064e\u0639\u06e1\u0628\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Dan raja berkata (kepada para pemuka kaumnya), \"Sesungguhnya aku bermimpi melihat tujuh ekor sapi betina yang gemuk dimakan oleh tujuh ekor sapi betina yang kurus; tujuh tangkai (gandum) yang hijau dan (tujuh tangkai) lainnya yang kering. Wahai orang yang terkemuka! Terangkanlah kepadaku tentang takwil mimpiku itu jika kamu dapat menakwilkan mimpi"},{id:44,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0636\u06e1\u063a\u064e\u0670\u062b\u064f \u0623\u064e\u062d\u06e1\u0644\u064e\u0670\u0645\u0656\u06d6 \u0648\u064e\u0645\u064e\u0627 \u0646\u064e\u062d\u06e1\u0646\u064f \u0628\u0650\u062a\u064e\u0623\u06e1\u0648\u0650\u064a\u0644\u0650 \u0671\u0644\u06e1\u0623\u064e\u062d\u06e1\u0644\u064e\u0670\u0645\u0650 \u0628\u0650\u0639\u064e\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Mereka menjawab, \"(Itu) mimpi-mimpi yang kosong dan kami tidak mampu menakwilkan mimpi itu"},{id:45,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0646\u064e\u062c\u064e\u0627 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u064e\u0627 \u0648\u064e\u0671\u062f\u0651\u064e\u0643\u064e\u0631\u064e \u0628\u064e\u0639\u06e1\u062f\u064e \u0623\u064f\u0645\u0651\u064e\u0629\u064d \u0623\u064e\u0646\u064e\u0627\u06e0 \u0623\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0643\u064f\u0645 \u0628\u0650\u062a\u064e\u0623\u06e1\u0648\u0650\u064a\u0644\u0650\u0647\u0650\u06e6 \u0641\u064e\u0623\u064e\u0631\u06e1\u0633\u0650\u0644\u064f\u0648\u0646\u0650",translation:"Dan berkatalah orang yang selamat di antara mereka berdua dan teringat (kepada Yusuf) setelah beberapa waktu lamanya, \"Aku akan memberitahukan kepadamu tentang (orang yang pandai) menakwilkan mimpi itu, maka utuslah aku (kepadanya)"},{id:46,text:"\u064a\u064f\u0648\u0633\u064f\u0641\u064f \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0635\u0651\u0650\u062f\u0651\u0650\u064a\u0642\u064f \u0623\u064e\u0641\u06e1\u062a\u0650\u0646\u064e\u0627 \u0641\u0650\u064a \u0633\u064e\u0628\u06e1\u0639\u0650 \u0628\u064e\u0642\u064e\u0631\u064e\u0670\u062a\u0656 \u0633\u0650\u0645\u064e\u0627\u0646\u0656 \u064a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f\u0647\u064f\u0646\u0651\u064e \u0633\u064e\u0628\u06e1\u0639\u064c \u0639\u0650\u062c\u064e\u0627\u0641\u065e \u0648\u064e\u0633\u064e\u0628\u06e1\u0639\u0650 \u0633\u064f\u0646\u06e2\u0628\u064f\u0644\u064e\u0670\u062a\u064d \u062e\u064f\u0636\u06e1\u0631\u0656 \u0648\u064e\u0623\u064f\u062e\u064e\u0631\u064e \u064a\u064e\u0627\u0628\u0650\u0633\u064e\u0670\u062a\u0656 \u0644\u0651\u064e\u0639\u064e\u0644\u0651\u0650\u064a\u0653 \u0623\u064e\u0631\u06e1\u062c\u0650\u0639\u064f \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Yusuf, wahai orang yang sangat dipercaya! Terangkanlah kepada kami (takwil mimpi) tentang tujuh ekor sapi betina yang gemuk yang dimakan oleh tujuh (ekor sapi betina) yang kurus, tujuh tangkai (gandum) yang hijau dan (tujuh tangkai) lainnya yang kering agar aku kembali kepada orang-orang itu, agar mereka mengetahuinya"},{id:47,text:"\u0642\u064e\u0627\u0644\u064e \u062a\u064e\u0632\u06e1\u0631\u064e\u0639\u064f\u0648\u0646\u064e \u0633\u064e\u0628\u06e1\u0639\u064e \u0633\u0650\u0646\u0650\u064a\u0646\u064e \u062f\u064e\u0623\u064e\u0628\u0657\u0627 \u0641\u064e\u0645\u064e\u0627 \u062d\u064e\u0635\u064e\u062f\u062a\u0651\u064f\u0645\u06e1 \u0641\u064e\u0630\u064e\u0631\u064f\u0648\u0647\u064f \u0641\u0650\u064a \u0633\u064f\u0646\u06e2\u0628\u064f\u0644\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u0657\u0627 \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f\u0648\u0646\u064e",translation:"Dia (Yusuf) berkata, \"Agar kamu bercocok tanam tujuh tahun (berturut-turut) sebagaimana biasa; kemudian apa yang kamu tuai hendaklah kamu biarkan ditangkainya kecuali sedikit untuk kamu makan"},{id:48,text:"\u062b\u064f\u0645\u0651\u064e \u064a\u064e\u0623\u06e1\u062a\u0650\u064a \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0633\u064e\u0628\u06e1\u0639\u065e \u0634\u0650\u062f\u064e\u0627\u062f\u065e \u064a\u064e\u0623\u06e1\u0643\u064f\u0644\u06e1\u0646\u064e \u0645\u064e\u0627 \u0642\u064e\u062f\u0651\u064e\u0645\u06e1\u062a\u064f\u0645\u06e1 \u0644\u064e\u0647\u064f\u0646\u0651\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u0657\u0627 \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u062a\u064f\u062d\u06e1\u0635\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Kemudian setelah itu akan datang tujuh (tahun) yang sangat sulit, yang menghabiskan apa yang kamu simpan untuk menghadapinya (tahun sulit), kecuali sedikit dari apa (bibit gandum) yang kamu simpan"},{id:49,text:"\u062b\u064f\u0645\u0651\u064e \u064a\u064e\u0623\u06e1\u062a\u0650\u064a \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0639\u064e\u0627\u0645\u065e \u0641\u0650\u064a\u0647\u0650 \u064a\u064f\u063a\u064e\u0627\u062b\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0648\u064e\u0641\u0650\u064a\u0647\u0650 \u064a\u064e\u0639\u06e1\u0635\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Setelah itu akan datang tahun, dimana manusia diberi hujan (dengan cukup) dan pada masa itu mereka memeras (anggur)"},{id:50,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u06e1\u0645\u064e\u0644\u0650\u0643\u064f \u0671\u0626\u06e1\u062a\u064f\u0648\u0646\u0650\u064a \u0628\u0650\u0647\u0650\u06e6\u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064f \u0642\u064e\u0627\u0644\u064e \u0671\u0631\u06e1\u062c\u0650\u0639\u06e1 \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0641\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u06e1\u0647\u064f \u0645\u064e\u0627 \u0628\u064e\u0627\u0644\u064f \u0671\u0644\u0646\u0651\u0650\u0633\u06e1\u0648\u064e\u0629\u0650 \u0671\u0644\u0651\u064e\u0640\u0670\u062a\u0650\u064a \u0642\u064e\u0637\u0651\u064e\u0639\u06e1\u0646\u064e \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u064e\u0647\u064f\u0646\u0651\u064e\u06da \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0628\u0650\u0643\u064e\u064a\u06e1\u062f\u0650\u0647\u0650\u0646\u0651\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Dan raja berkata, \"Bawalah dia kepadaku.\" Ketika utusan itu datang kepadanya, dia (Yusuf) berkata, \"Kembalilah kepada tuanmu dan tanyakan kepadanya bagaimana halnya perempuan-perempuan yang telah melukai tangannya. Sungguh, Tuhanku Maha Mengetahui tipu daya mereka"},{id:51,text:"\u0642\u064e\u0627\u0644\u064e \u0645\u064e\u0627 \u062e\u064e\u0637\u06e1\u0628\u064f\u0643\u064f\u0646\u0651\u064e \u0625\u0650\u0630\u06e1 \u0631\u064e\u0670\u0648\u064e\u062f\u062a\u0651\u064f\u0646\u0651\u064e \u064a\u064f\u0648\u0633\u064f\u0641\u064e \u0639\u064e\u0646 \u0646\u0651\u064e\u0641\u06e1\u0633\u0650\u0647\u0650\u06e6\u06da \u0642\u064f\u0644\u06e1\u0646\u064e \u062d\u064e\u0670\u0634\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0639\u064e\u0644\u0650\u0645\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0645\u0650\u0646 \u0633\u064f\u0648\u0653\u0621\u0656\u06da \u0642\u064e\u0627\u0644\u064e\u062a\u0650 \u0671\u0645\u06e1\u0631\u064e\u0623\u064e\u062a\u064f \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u0650 \u0671\u0644\u06e1\u0640\u0654\u064e\u0670\u0646\u064e \u062d\u064e\u0635\u06e1\u062d\u064e\u0635\u064e \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f \u0623\u064e\u0646\u064e\u0627\u06e0 \u0631\u064e\u0670\u0648\u064e\u062f\u062a\u0651\u064f\u0647\u064f\u06e5 \u0639\u064e\u0646 \u0646\u0651\u064e\u0641\u06e1\u0633\u0650\u0647\u0650\u06e6 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Dia (raja) berkata (kepada perempuan-perempuan itu), \"Bagaimana keadaanmu413) ketika kamu menggoda Yusuf untuk menundukkan dirinya?\" Mereka berkata, \"Mahasempurna Allah, kami tidak mengetahui sesuatu keburukan darinya.\" Istri Al-Aziz berkata, \"Sekarang jelaslah kebenaran itu, akulah yang menggoda dan merayunya, dan sesungguhnya dia termasuk orang yang benar"},{id:52,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u0650\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064e \u0623\u064e\u0646\u0651\u0650\u064a \u0644\u064e\u0645\u06e1 \u0623\u064e\u062e\u064f\u0646\u06e1\u0647\u064f \u0628\u0650\u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u0628\u0650 \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064e\u0647\u06e1\u062f\u0650\u064a \u0643\u064e\u064a\u06e1\u062f\u064e \u0671\u0644\u06e1\u062e\u064e\u0627\u0653\u0626\u0650\u0646\u0650\u064a\u0646\u064e",translation:"(Yusuf berkata), \"Yang demikian itu agar dia (Al-Aziz) mengetahui bahwa aku benar-benar tidak mengkhianatinya ketika dia tidak ada (di rumah), dan bahwa Allah tidak meridai tipu daya orang-orang yang berkhianat"},{id:53,text:"\u06de\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0628\u064e\u0631\u0651\u0650\u0626\u064f \u0646\u064e\u0641\u06e1\u0633\u0650\u064a\u0653\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0646\u0651\u064e\u0641\u06e1\u0633\u064e \u0644\u064e\u0623\u064e\u0645\u0651\u064e\u0627\u0631\u064e\u0629\u064f\u06e2 \u0628\u0650\u0671\u0644\u0633\u0651\u064f\u0648\u0653\u0621\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0631\u064e\u062d\u0650\u0645\u064e \u0631\u064e\u0628\u0651\u0650\u064a\u0653\u06da \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u065e",translation:"Dan aku tidak (menyatakan) diriku bebas (dari kesalahan), karena sesungguhnya nafsu itu selalu mendorong kepada kejahatan, kecuali (nafsu) yang diberi rahmat oleh Tuhanku. Sesungguhnya Tuhanku Maha Pengampun, Maha Penyayang"},{id:54,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u06e1\u0645\u064e\u0644\u0650\u0643\u064f \u0671\u0626\u06e1\u062a\u064f\u0648\u0646\u0650\u064a \u0628\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0633\u06e1\u062a\u064e\u062e\u06e1\u0644\u0650\u0635\u06e1\u0647\u064f \u0644\u0650\u0646\u064e\u0641\u06e1\u0633\u0650\u064a\u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0643\u064e\u0644\u0651\u064e\u0645\u064e\u0647\u064f\u06e5 \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e \u0644\u064e\u062f\u064e\u064a\u06e1\u0646\u064e\u0627 \u0645\u064e\u0643\u0650\u064a\u0646\u064c \u0623\u064e\u0645\u0650\u064a\u0646\u065e",translation:"Dan raja berkata, \"Bawalah dia (Yusuf) kepadaku, agar aku memilih dia (sebagai orang yang dekat) kepadaku.\" Ketika dia (raja) telah bercakap-cakap dengan dia, maka dia (raja) berkata, \"Sesungguhnya kamu (mulai) hari ini menjadi seorang yang berkedudukan tinggi di lingkungan kami dan terpercaya"},{id:55,text:"\u0642\u064e\u0627\u0644\u064e \u0671\u062c\u06e1\u0639\u064e\u0644\u06e1\u0646\u0650\u064a \u0639\u064e\u0644\u064e\u0649\u0670 \u062e\u064e\u0632\u064e\u0627\u0653\u0626\u0650\u0646\u0650 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d6 \u0625\u0650\u0646\u0651\u0650\u064a \u062d\u064e\u0641\u0650\u064a\u0638\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Dia (Yusuf) berkata, \"Jadikanlah aku bendaharawan negeri (Mesir); karena sesungguhnya aku adalah orang yang pandai menjaga dan berpengetahuan"},{id:56,text:"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u064e\u0643\u0651\u064e\u0646\u0651\u064e\u0627 \u0644\u0650\u064a\u064f\u0648\u0633\u064f\u0641\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u064a\u064e\u062a\u064e\u0628\u064e\u0648\u0651\u064e\u0623\u064f \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u062d\u064e\u064a\u06e1\u062b\u064f \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06da \u0646\u064f\u0635\u0650\u064a\u0628\u064f \u0628\u0650\u0631\u064e\u062d\u06e1\u0645\u064e\u062a\u0650\u0646\u064e\u0627 \u0645\u064e\u0646 \u0646\u0651\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06d6 \u0648\u064e\u0644\u064e\u0627 \u0646\u064f\u0636\u0650\u064a\u0639\u064f \u0623\u064e\u062c\u06e1\u0631\u064e \u0671\u0644\u06e1\u0645\u064f\u062d\u06e1\u0633\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dan demikianlah Kami memberi kedudukan kepada Yusuf di negeri ini (Mesir); untuk tinggal dimana saja yang dia kehendaki. Kami melimpahkan rahmat kepada siapa yang Kami kehendaki dan Kami tidak menyia-nyiakan pahala orang-orang yang berbuat baik"},{id:57,text:"\u0648\u064e\u0644\u064e\u0623\u064e\u062c\u06e1\u0631\u064f \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u062e\u064e\u064a\u06e1\u0631\u065e \u0644\u0651\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",translation:"Dan sungguh, pahala akhirat itu lebih baik bagi orang-orang yang beriman dan selalu bertakwa"},{id:58,text:"\u0648\u064e\u062c\u064e\u0627\u0653\u0621\u064e \u0625\u0650\u062e\u06e1\u0648\u064e\u0629\u064f \u064a\u064f\u0648\u0633\u064f\u0641\u064e \u0641\u064e\u062f\u064e\u062e\u064e\u0644\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0641\u064e\u0639\u064e\u0631\u064e\u0641\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0647\u064f\u06e5 \u0645\u064f\u0646\u0643\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Dan saudara-saudara Yusuf datang (ke Mesir) lalu mereka masuk ke (tempat)nya. Maka dia (Yusuf) mengenal mereka, sedangkan mereka tidak kenal (lagi) kepadanya"},{id:59,text:"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0647\u0651\u064e\u0632\u064e\u0647\u064f\u0645 \u0628\u0650\u062c\u064e\u0647\u064e\u0627\u0632\u0650\u0647\u0650\u0645\u06e1 \u0642\u064e\u0627\u0644\u064e \u0671\u0626\u06e1\u062a\u064f\u0648\u0646\u0650\u064a \u0628\u0650\u0623\u064e\u062e\u0656 \u0644\u0651\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u0628\u0650\u064a\u0643\u064f\u0645\u06e1\u06da \u0623\u064e\u0644\u064e\u0627 \u062a\u064e\u0631\u064e\u0648\u06e1\u0646\u064e \u0623\u064e\u0646\u0651\u0650\u064a\u0653 \u0623\u064f\u0648\u0641\u0650\u064a \u0671\u0644\u06e1\u0643\u064e\u064a\u06e1\u0644\u064e \u0648\u064e\u0623\u064e\u0646\u064e\u0627\u06e0 \u062e\u064e\u064a\u06e1\u0631\u064f \u0671\u0644\u06e1\u0645\u064f\u0646\u0632\u0650\u0644\u0650\u064a\u0646\u064e",translation:"Dan ketika dia (Yusuf) menyiapkan bahan makanan untuk mereka, dia berkata, \"Bawalah kepadaku saudaramu yang seayah dengan kamu (Bunyamin), tidakkah kamu melihat bahwa aku menyempurnakan takaran dan aku adalah penerima tamu yang terbaik"},{id:60,text:"\u0641\u064e\u0625\u0650\u0646 \u0644\u0651\u064e\u0645\u06e1 \u062a\u064e\u0623\u06e1\u062a\u064f\u0648\u0646\u0650\u064a \u0628\u0650\u0647\u0650\u06e6 \u0641\u064e\u0644\u064e\u0627 \u0643\u064e\u064a\u06e1\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u06e1 \u0639\u0650\u0646\u062f\u0650\u064a \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u06e1\u0631\u064e\u0628\u064f\u0648\u0646\u0650",translation:"Maka jika kamu tidak membawanya kepadaku, maka kamu tidak akan mendapat jatah (gandum) lagi dariku dan jangan kamu mendekatiku"},{id:61,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0633\u064e\u0646\u064f\u0631\u064e\u0670\u0648\u0650\u062f\u064f \u0639\u064e\u0646\u06e1\u0647\u064f \u0623\u064e\u0628\u064e\u0627\u0647\u064f \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0641\u064e\u0670\u0639\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Mereka berkata, \"Kami akan membujuk ayahnya (untuk membawanya) dan kami benar-benar akan melaksanakannya"},{id:62,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0641\u0650\u062a\u06e1\u064a\u064e\u0670\u0646\u0650\u0647\u0650 \u0671\u062c\u06e1\u0639\u064e\u0644\u064f\u0648\u0627\u0652 \u0628\u0650\u0636\u064e\u0670\u0639\u064e\u062a\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0631\u0650\u062d\u064e\u0627\u0644\u0650\u0647\u0650\u0645\u06e1 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0639\u06e1\u0631\u0650\u0641\u064f\u0648\u0646\u064e\u0647\u064e\u0627\u0653 \u0625\u0650\u0630\u064e\u0627 \u0671\u0646\u0642\u064e\u0644\u064e\u0628\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0647\u06e1\u0644\u0650\u0647\u0650\u0645\u06e1 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0631\u06e1\u062c\u0650\u0639\u064f\u0648\u0646\u064e",translation:"Dan dia (Yusuf) berkata kepada pelayan-pelayannya, \"Masukkanlah barang-barang (penukar) mereka415) ke dalam karung-karungnya, agar mereka mengetahuinya apabila telah kembali kepada keluarganya, mudah-mudahan mereka kembali lagi"},{id:63,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0631\u064e\u062c\u064e\u0639\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0628\u0650\u064a\u0647\u0650\u0645\u06e1 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u064a\u064e\u0640\u0670\u0653\u0623\u064e\u0628\u064e\u0627\u0646\u064e\u0627 \u0645\u064f\u0646\u0650\u0639\u064e \u0645\u0650\u0646\u0651\u064e\u0627 \u0671\u0644\u06e1\u0643\u064e\u064a\u06e1\u0644\u064f \u0641\u064e\u0623\u064e\u0631\u06e1\u0633\u0650\u0644\u06e1 \u0645\u064e\u0639\u064e\u0646\u064e\u0627\u0653 \u0623\u064e\u062e\u064e\u0627\u0646\u064e\u0627 \u0646\u064e\u0643\u06e1\u062a\u064e\u0644\u06e1 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0647\u064f\u06e5 \u0644\u064e\u062d\u064e\u0670\u0641\u0650\u0638\u064f\u0648\u0646\u064e",translation:"Maka ketika mereka telah kembali kepada ayahnya (Yakub) mereka berkata, \"Wahai ayah kami! Kami tidak akan mendapat jatah (gandum) lagi, (jika tidak membawa saudara kami), sebab itu biarkanlah saudara kami pergi bersama kami agar kami mendapat jatah, dan kami benar-benar akan menjaganya"},{id:64,text:"\u0642\u064e\u0627\u0644\u064e \u0647\u064e\u0644\u06e1 \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0643\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0645\u0650\u0646\u062a\u064f\u0643\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u062e\u0650\u064a\u0647\u0650 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f \u0641\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u062e\u064e\u064a\u06e1\u0631\u064c \u062d\u064e\u0670\u0641\u0650\u0638\u0657\u0627\u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0623\u064e\u0631\u06e1\u062d\u064e\u0645\u064f \u0671\u0644\u0631\u0651\u064e\u0640\u0670\u062d\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dia (Yakub) berkata, \"Bagaimana aku akan mempercayakannya (Bunyamin) kepadamu, seperti aku telah mempercayakan saudaranya (Yusuf) kepada kamu dahulu?\" Maka Allah adalah Penjaga yang terbaik dan Dia Maha Penyayang di antara para penyayang"},{id:65,text:"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0641\u064e\u062a\u064e\u062d\u064f\u0648\u0627\u0652 \u0645\u064e\u062a\u064e\u0670\u0639\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u062c\u064e\u062f\u064f\u0648\u0627\u0652 \u0628\u0650\u0636\u064e\u0670\u0639\u064e\u062a\u064e\u0647\u064f\u0645\u06e1 \u0631\u064f\u062f\u0651\u064e\u062a\u06e1 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1\u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u064a\u064e\u0640\u0670\u0653\u0623\u064e\u0628\u064e\u0627\u0646\u064e\u0627 \u0645\u064e\u0627 \u0646\u064e\u0628\u06e1\u063a\u0650\u064a\u06d6 \u0647\u064e\u0670\u0630\u0650\u0647\u0650\u06e6 \u0628\u0650\u0636\u064e\u0670\u0639\u064e\u062a\u064f\u0646\u064e\u0627 \u0631\u064f\u062f\u0651\u064e\u062a\u06e1 \u0625\u0650\u0644\u064e\u064a\u06e1\u0646\u064e\u0627\u06d6 \u0648\u064e\u0646\u064e\u0645\u0650\u064a\u0631\u064f \u0623\u064e\u0647\u06e1\u0644\u064e\u0646\u064e\u0627 \u0648\u064e\u0646\u064e\u062d\u06e1\u0641\u064e\u0638\u064f \u0623\u064e\u062e\u064e\u0627\u0646\u064e\u0627 \u0648\u064e\u0646\u064e\u0632\u06e1\u062f\u064e\u0627\u062f\u064f \u0643\u064e\u064a\u06e1\u0644\u064e \u0628\u064e\u0639\u0650\u064a\u0631\u0656\u06d6 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0643\u064e\u064a\u06e1\u0644\u065e \u064a\u064e\u0633\u0650\u064a\u0631\u065e",translation:"Dan ketika mereka membuka barang-barangnya, mereka menemukan barang-barang (penukar) mereka dikembalikan kepada mereka. Mereka berkata, \"Wahai ayah kami! Apalagi yang kita inginkan. Ini barang-barang kita dikembalikan kepada kita, dan kita akan dapat memberi makan keluarga kita, dan kami akan memelihara saudara kami, dan kita akan mendapat tambahan jatah (gandum) seberat beban seekor unta. Itu suatu hal yang mudah (bagi raja Mesir)"},{id:66,text:"\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0646\u06e1 \u0623\u064f\u0631\u06e1\u0633\u0650\u0644\u064e\u0647\u064f\u06e5 \u0645\u064e\u0639\u064e\u0643\u064f\u0645\u06e1 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062a\u064f\u0624\u06e1\u062a\u064f\u0648\u0646\u0650 \u0645\u064e\u0648\u06e1\u062b\u0650\u0642\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u062a\u064e\u0623\u06e1\u062a\u064f\u0646\u0651\u064e\u0646\u0650\u064a \u0628\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u064a\u064f\u062d\u064e\u0627\u0637\u064e \u0628\u0650\u0643\u064f\u0645\u06e1\u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u064e\u0648\u06e1\u0647\u064f \u0645\u064e\u0648\u06e1\u062b\u0650\u0642\u064e\u0647\u064f\u0645\u06e1 \u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0646\u064e\u0642\u064f\u0648\u0644\u064f \u0648\u064e\u0643\u0650\u064a\u0644\u065e",translation:"Dia (Yakub) berkata, \"Aku tidak akan melepaskannya (pergi) bersama kamu, sebelum kamu bersumpah kepadaku atas (nama) Allah, bahwa kamu pasti akan membawanya kepadaku kembali, kecuali jika kamu dikepung (musuh).\" Setelah mereka mengucapkan sumpah, dia (Yakub) berkata, \"Allah adalah saksi terhadap apa yang kita ucapkan"},{id:67,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0670\u0628\u064e\u0646\u0650\u064a\u0651\u064e \u0644\u064e\u0627 \u062a\u064e\u062f\u06e1\u062e\u064f\u0644\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0627\u0628\u0656 \u0648\u064e\u0670\u062d\u0650\u062f\u0656 \u0648\u064e\u0671\u062f\u06e1\u062e\u064f\u0644\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1 \u0623\u064e\u0628\u06e1\u0648\u064e\u0670\u0628\u0656 \u0645\u0651\u064f\u062a\u064e\u0641\u064e\u0631\u0651\u0650\u0642\u064e\u0629\u0656\u06d6 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u063a\u06e1\u0646\u0650\u064a \u0639\u064e\u0646\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646 \u0634\u064e\u064a\u06e1\u0621\u064d\u06d6 \u0625\u0650\u0646\u0650 \u0671\u0644\u06e1\u062d\u064f\u0643\u06e1\u0645\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0644\u0650\u0644\u0651\u064e\u0647\u0650\u06d6 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u06e1\u062a\u064f\u06d6 \u0648\u064e\u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0641\u064e\u0644\u06e1\u064a\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u0650 \u0671\u0644\u06e1\u0645\u064f\u062a\u064e\u0648\u064e\u0643\u0651\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Dan dia (Yakub) berkata, \"Wahai anak-anakku! Janganlah kamu masuk dari satu pintu gerbang, dan masuklah dari pintu-pintu gerbang yang berbeda; namun demikian aku tidak dapat mempertahankan kamu sedikit pun dari (takdir) Allah. Keputusan itu hanyalah bagi Allah. Kepada-Nya aku bertawakal dan kepada-Nya pula bertawakallah orang-orang yang bertawakal"},{id:68,text:"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062f\u064e\u062e\u064e\u0644\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1 \u062d\u064e\u064a\u06e1\u062b\u064f \u0623\u064e\u0645\u064e\u0631\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u0628\u064f\u0648\u0647\u064f\u0645 \u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u064a\u064f\u063a\u06e1\u0646\u0650\u064a \u0639\u064e\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646 \u0634\u064e\u064a\u06e1\u0621\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u062d\u064e\u0627\u062c\u064e\u0629\u0657 \u0641\u0650\u064a \u0646\u064e\u0641\u06e1\u0633\u0650 \u064a\u064e\u0639\u06e1\u0642\u064f\u0648\u0628\u064e \u0642\u064e\u0636\u064e\u0649\u0670\u0647\u064e\u0627\u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0630\u064f\u0648 \u0639\u0650\u0644\u06e1\u0645\u0656 \u0644\u0651\u0650\u0645\u064e\u0627 \u0639\u064e\u0644\u0651\u064e\u0645\u06e1\u0646\u064e\u0670\u0647\u064f \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan ketika mereka masuk sesuai dengan perintah ayah mereka, (masuknya mereka itu) tidak dapat menolak sedikit pun keputusan Allah, (tetapi itu) hanya suatu keinginan pada diri Yakub yang telah ditetapkannya. Dan sesungguhnya dia mempunyai pengetahuan, karena Kami telah mengajarkan kepadanya. Tetapi kebanyakan manusia tidak mengetahui"},{id:69,text:"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062f\u064e\u062e\u064e\u0644\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u064a\u064f\u0648\u0633\u064f\u0641\u064e \u0621\u064e\u0627\u0648\u064e\u0649\u0670\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0623\u064e\u062e\u064e\u0627\u0647\u064f\u06d6 \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064e\u0646\u064e\u0627\u06e0 \u0623\u064e\u062e\u064f\u0648\u0643\u064e \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0628\u06e1\u062a\u064e\u0626\u0650\u0633\u06e1 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan ketika mereka masuk ke (tempat) Yusuf, dia menempatkan saudaranya (Bunyamin) di tempatnya, dia (Yusuf) berkata, \"Sesungguhnya aku adalah saudaramu, jangan engkau bersedih hati atas apa yang telah mereka kerjakan"},{id:70,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0647\u0651\u064e\u0632\u064e\u0647\u064f\u0645 \u0628\u0650\u062c\u064e\u0647\u064e\u0627\u0632\u0650\u0647\u0650\u0645\u06e1 \u062c\u064e\u0639\u064e\u0644\u064e \u0671\u0644\u0633\u0651\u0650\u0642\u064e\u0627\u064a\u064e\u0629\u064e \u0641\u0650\u064a \u0631\u064e\u062d\u06e1\u0644\u0650 \u0623\u064e\u062e\u0650\u064a\u0647\u0650 \u062b\u064f\u0645\u0651\u064e \u0623\u064e\u0630\u0651\u064e\u0646\u064e \u0645\u064f\u0624\u064e\u0630\u0651\u0650\u0646\u064c \u0623\u064e\u064a\u0651\u064e\u062a\u064f\u0647\u064e\u0627 \u0671\u0644\u06e1\u0639\u0650\u064a\u0631\u064f \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0644\u064e\u0633\u064e\u0670\u0631\u0650\u0642\u064f\u0648\u0646\u064e",translation:"Maka ketika telah disiapkan bahan makanan untuk mereka, dia (Yusuf) memasukkan piala417) ke dalam karung saudaranya. Kemudian berteriaklah seseorang yang menyerukan, \"Wahai kafilah! Sesungguhnya kamu pasti pencuri"},{id:71,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0648\u064e\u0623\u064e\u0642\u06e1\u0628\u064e\u0644\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0645\u0651\u064e\u0627\u0630\u064e\u0627 \u062a\u064e\u0641\u06e1\u0642\u0650\u062f\u064f\u0648\u0646\u064e",translation:"Mereka bertanya, sambil menghadap kepada mereka (yang menuduh), \" Kamu kehilangan apa"},{id:72,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0646\u064e\u0641\u06e1\u0642\u0650\u062f\u064f \u0635\u064f\u0648\u064e\u0627\u0639\u064e \u0671\u0644\u06e1\u0645\u064e\u0644\u0650\u0643\u0650 \u0648\u064e\u0644\u0650\u0645\u064e\u0646 \u062c\u064e\u0627\u0653\u0621\u064e \u0628\u0650\u0647\u0650\u06e6 \u062d\u0650\u0645\u06e1\u0644\u064f \u0628\u064e\u0639\u0650\u064a\u0631\u0656 \u0648\u064e\u0623\u064e\u0646\u064e\u0627\u06e0 \u0628\u0650\u0647\u0650\u06e6 \u0632\u064e\u0639\u0650\u064a\u0645\u065e",translation:"Mereka menjawab, \"Kami kehilangan piala raja, dan siapa yang dapat mengembalikannya akan memperoleh (bahan makanan seberat) beban unta, dan aku jamin itu"},{id:73,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u062a\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0642\u064e\u062f\u06e1 \u0639\u064e\u0644\u0650\u0645\u06e1\u062a\u064f\u0645 \u0645\u0651\u064e\u0627 \u062c\u0650\u0626\u06e1\u0646\u064e\u0627 \u0644\u0650\u0646\u064f\u0641\u06e1\u0633\u0650\u062f\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0633\u064e\u0670\u0631\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Mereka (saudara-saudara Yusuf) menjawab, \"Demi Allah, sungguh, kamu mengetahui bahwa kami datang bukan untuk berbuat kerusakan di negeri ini dan kami bukanlah para pencuri"},{id:74,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0641\u064e\u0645\u064e\u0627 \u062c\u064e\u0632\u064e\u0640\u0670\u0653\u0624\u064f\u0647\u064f\u06e5\u0653 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0643\u064e\u0670\u0630\u0650\u0628\u0650\u064a\u0646\u064e",translation:"Mereka berkata, \"Tetapi apa hukumannya jika kamu dusta"},{id:75,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u062c\u064e\u0632\u064e\u0640\u0670\u0653\u0624\u064f\u0647\u064f\u06e5 \u0645\u064e\u0646 \u0648\u064f\u062c\u0650\u062f\u064e \u0641\u0650\u064a \u0631\u064e\u062d\u06e1\u0644\u0650\u0647\u0650\u06e6 \u0641\u064e\u0647\u064f\u0648\u064e \u062c\u064e\u0632\u064e\u0640\u0670\u0653\u0624\u064f\u0647\u064f\u06e5\u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u062c\u06e1\u0632\u0650\u064a \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Mereka menjawab, \"Hukumannya ialah pada siapa yang ditemukan dalam karungnya (barang yang hilang itu), maka dia sendirilah yang menerima hukumannya.418) Demikianlah kami memberi hukuman kepada orang-orang zalim"},{id:76,text:"\u0641\u064e\u0628\u064e\u062f\u064e\u0623\u064e \u0628\u0650\u0623\u064e\u0648\u06e1\u0639\u0650\u064a\u064e\u062a\u0650\u0647\u0650\u0645\u06e1 \u0642\u064e\u0628\u06e1\u0644\u064e \u0648\u0650\u0639\u064e\u0627\u0653\u0621\u0650 \u0623\u064e\u062e\u0650\u064a\u0647\u0650 \u062b\u064f\u0645\u0651\u064e \u0671\u0633\u06e1\u062a\u064e\u062e\u06e1\u0631\u064e\u062c\u064e\u0647\u064e\u0627 \u0645\u0650\u0646 \u0648\u0650\u0639\u064e\u0627\u0653\u0621\u0650 \u0623\u064e\u062e\u0650\u064a\u0647\u0650\u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0643\u0650\u062f\u06e1\u0646\u064e\u0627 \u0644\u0650\u064a\u064f\u0648\u0633\u064f\u0641\u064e\u06d6 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u064a\u064e\u0623\u06e1\u062e\u064f\u0630\u064e \u0623\u064e\u062e\u064e\u0627\u0647\u064f \u0641\u0650\u064a \u062f\u0650\u064a\u0646\u0650 \u0671\u0644\u06e1\u0645\u064e\u0644\u0650\u0643\u0650 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06da \u0646\u064e\u0631\u06e1\u0641\u064e\u0639\u064f \u062f\u064e\u0631\u064e\u062c\u064e\u0670\u062a\u0656 \u0645\u0651\u064e\u0646 \u0646\u0651\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06d7 \u0648\u064e\u0641\u064e\u0648\u06e1\u0642\u064e \u0643\u064f\u0644\u0651\u0650 \u0630\u0650\u064a \u0639\u0650\u0644\u06e1\u0645\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Maka mulailah dia (memeriksa) karung-karung mereka sebelum (memeriksa) karung saudaranya sendiri, kemudian dia mengeluarkan (piala raja) itu dari karung saudaranya. Demikianlah Kami mengatur (rencana) untuk Yusuf. Dia tidak dapat menghukum saudaranya menurut undang-undang raja, kecuali Allah menghendakinya. Kami angkat derajat orang yang Kami kehendaki; dan di atas setiap orang yang berpengetahuan ada yang lebih mengetahui"},{id:77,text:"\u06de\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646 \u064a\u064e\u0633\u06e1\u0631\u0650\u0642\u06e1 \u0641\u064e\u0642\u064e\u062f\u06e1 \u0633\u064e\u0631\u064e\u0642\u064e \u0623\u064e\u062e\u065e \u0644\u0651\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f\u06da \u0641\u064e\u0623\u064e\u0633\u064e\u0631\u0651\u064e\u0647\u064e\u0627 \u064a\u064f\u0648\u0633\u064f\u0641\u064f \u0641\u0650\u064a \u0646\u064e\u0641\u06e1\u0633\u0650\u0647\u0650\u06e6 \u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064f\u0628\u06e1\u062f\u0650\u0647\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u06e1\u06da \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0634\u064e\u0631\u0651\u065e \u0645\u0651\u064e\u0643\u064e\u0627\u0646\u0657\u0627\u06d6 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0635\u0650\u0641\u064f\u0648\u0646\u064e",translation:"Mereka berkata, \"Jika dia mencuri, maka sungguh sebelum itu saudaranya pun pernah pula mencuri.\" Maka Yusuf menyembunyikan (kejengkelan) dalam hatinya dan tidak ditampakkannya kepada mereka. Dia berkata (dalam hatinya), \"Kedudukanmu justru lebih buruk. Dan Allah Maha Mengetahui apa yang kamu terangkan"},{id:78,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0625\u0650\u0646\u0651\u064e \u0644\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u0628\u0657\u0627 \u0634\u064e\u064a\u06e1\u062e\u0657\u0627 \u0643\u064e\u0628\u0650\u064a\u0631\u0657\u0627 \u0641\u064e\u062e\u064f\u0630\u06e1 \u0623\u064e\u062d\u064e\u062f\u064e\u0646\u064e\u0627 \u0645\u064e\u0643\u064e\u0627\u0646\u064e\u0647\u064f\u06e5\u0653\u06d6 \u0625\u0650\u0646\u0651\u064e\u0627 \u0646\u064e\u0631\u064e\u0649\u0670\u0643\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u062d\u06e1\u0633\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Mereka berkata, \"Wahai Al-Aziz! Dia mempunyai ayah yang sudah lanjut usia, karena itu ambillah salah seorang di antara kami sebagai gantinya, sesungguhnya kami melihat engkau termasuk orang-orang yang berbuat baik"},{id:79,text:"\u0642\u064e\u0627\u0644\u064e \u0645\u064e\u0639\u064e\u0627\u0630\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0646 \u0646\u0651\u064e\u0623\u06e1\u062e\u064f\u0630\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646 \u0648\u064e\u062c\u064e\u062f\u06e1\u0646\u064e\u0627 \u0645\u064e\u062a\u064e\u0670\u0639\u064e\u0646\u064e\u0627 \u0639\u0650\u0646\u062f\u064e\u0647\u064f\u06e5\u0653 \u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0625\u0650\u0630\u0657\u0627 \u0644\u0651\u064e\u0638\u064e\u0670\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Dia (Yusuf) berkata, \"Aku memohon perlindungan kepada Allah dari menahan (seseorang), kecuali orang yang kami temukan harta kami padanya, jika kami (berbuat) demikian, berarti kami orang yang zalim"},{id:80,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0671\u0633\u06e1\u062a\u064e\u064a\u06e1\u0640\u0654\u064e\u0633\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1\u0647\u064f \u062e\u064e\u0644\u064e\u0635\u064f\u0648\u0627\u0652 \u0646\u064e\u062c\u0650\u064a\u0651\u0657\u0627\u06d6 \u0642\u064e\u0627\u0644\u064e \u0643\u064e\u0628\u0650\u064a\u0631\u064f\u0647\u064f\u0645\u06e1 \u0623\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e \u0623\u064e\u0628\u064e\u0627\u0643\u064f\u0645\u06e1 \u0642\u064e\u062f\u06e1 \u0623\u064e\u062e\u064e\u0630\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645 \u0645\u0651\u064e\u0648\u06e1\u062b\u0650\u0642\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f \u0645\u064e\u0627 \u0641\u064e\u0631\u0651\u064e\u0637\u062a\u064f\u0645\u06e1 \u0641\u0650\u064a \u064a\u064f\u0648\u0633\u064f\u0641\u064e\u06d6 \u0641\u064e\u0644\u064e\u0646\u06e1 \u0623\u064e\u0628\u06e1\u0631\u064e\u062d\u064e \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0623\u06e1\u0630\u064e\u0646\u064e \u0644\u0650\u064a\u0653 \u0623\u064e\u0628\u0650\u064a\u0653 \u0623\u064e\u0648\u06e1 \u064a\u064e\u062d\u06e1\u0643\u064f\u0645\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u064a\u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u062e\u064e\u064a\u06e1\u0631\u064f \u0671\u0644\u06e1\u062d\u064e\u0670\u0643\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Maka ketika mereka berputus asa darinya (putusan Yusuf) mereka menyendiri (sambil berunding) dengan berbisik-bisik. Yang tertua di antara mereka berkata, \"Tidakkah kamu ketahui bahwa ayahmu telah mengambil janji dari kamu dengan (nama) Allah dan sebelum itu kamu telah menyia-nyiakan Yusuf? Sebab itu aku tidak akan meninggalkan negeri ini (Mesir), sampai ayahku mengizinkan (untuk kembali), atau Allah memberi keputusan terhadapku. Dan Dia adalah hakim yang terbaik"},{id:81,text:"\u0671\u0631\u06e1\u062c\u0650\u0639\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0628\u0650\u064a\u0643\u064f\u0645\u06e1 \u0641\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627\u0652 \u064a\u064e\u0640\u0670\u0653\u0623\u064e\u0628\u064e\u0627\u0646\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e \u0671\u0628\u06e1\u0646\u064e\u0643\u064e \u0633\u064e\u0631\u064e\u0642\u064e \u0648\u064e\u0645\u064e\u0627 \u0634\u064e\u0647\u0650\u062f\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0645\u064e\u0627 \u0639\u064e\u0644\u0650\u0645\u06e1\u0646\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0644\u0650\u0644\u06e1\u063a\u064e\u064a\u06e1\u0628\u0650 \u062d\u064e\u0670\u0641\u0650\u0638\u0650\u064a\u0646\u064e",translation:"Kembalilah kepada ayahmu dan katakanlah, \"Wahai ayah kami! Sesungguhnya anakmu telah mencuri dan kami hanya menyaksikan apa yang kami ketahui dan kami tidak mengetahui apa yang dibalik itu"},{id:82,text:"\u0648\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u0650 \u0671\u0644\u06e1\u0642\u064e\u0631\u06e1\u064a\u064e\u0629\u064e \u0671\u0644\u0651\u064e\u062a\u0650\u064a \u0643\u064f\u0646\u0651\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0671\u0644\u06e1\u0639\u0650\u064a\u0631\u064e \u0671\u0644\u0651\u064e\u062a\u0650\u064a\u0653 \u0623\u064e\u0642\u06e1\u0628\u064e\u0644\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627\u06d6 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0635\u064e\u0670\u062f\u0650\u0642\u064f\u0648\u0646\u064e",translation:"Dan tanyalah (penduduk) negeri tempat kami berada, dan kafilah yang datang bersama kami. Dan kami adalah orang yang benar"},{id:83,text:"\u0642\u064e\u0627\u0644\u064e \u0628\u064e\u0644\u06e1 \u0633\u064e\u0648\u0651\u064e\u0644\u064e\u062a\u06e1 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u0646\u0641\u064f\u0633\u064f\u0643\u064f\u0645\u06e1 \u0623\u064e\u0645\u06e1\u0631\u0657\u0627\u06d6 \u0641\u064e\u0635\u064e\u0628\u06e1\u0631\u065e \u062c\u064e\u0645\u0650\u064a\u0644\u064c\u06d6 \u0639\u064e\u0633\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0646 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e\u0646\u0650\u064a \u0628\u0650\u0647\u0650\u0645\u06e1 \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0639\u064e\u0644\u0650\u064a\u0645\u064f \u0671\u0644\u06e1\u062d\u064e\u0643\u0650\u064a\u0645\u064f",translation:"Dia (Yakub) berkata, \"Sebenarnya hanya dirimu sendiri yang memandang baik urusan (yang buruk) itu. Maka (kesabaranku) adalah kesabaran yang baik. Mudah-mudahan Allah mendatangkan mereka semuanya kepadaku. Sungguh, Dialah Yang Maha Mengetahui, Mahabijaksana"},{id:84,text:"\u0648\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649\u0670 \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0640\u0670\u0653\u0623\u064e\u0633\u064e\u0641\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649\u0670 \u064a\u064f\u0648\u0633\u064f\u0641\u064e \u0648\u064e\u0671\u0628\u06e1\u064a\u064e\u0636\u0651\u064e\u062a\u06e1 \u0639\u064e\u064a\u06e1\u0646\u064e\u0627\u0647\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u062d\u064f\u0632\u06e1\u0646\u0650 \u0641\u064e\u0647\u064f\u0648\u064e \u0643\u064e\u0638\u0650\u064a\u0645\u065e",translation:"Dan dia (Yakub) berpaling dari mereka (anak-anaknya) seraya berkata, \"Aduhai dukacitaku terhadap Yusuf,\" dan kedua matanya menjadi putih karena sedih Dia diam menahan amarah (terhadap anak-anaknya)"},{id:85,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u062a\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064e\u0641\u06e1\u062a\u064e\u0624\u064f\u0627\u0652 \u062a\u064e\u0630\u06e1\u0643\u064f\u0631\u064f \u064a\u064f\u0648\u0633\u064f\u0641\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062a\u064e\u0643\u064f\u0648\u0646\u064e \u062d\u064e\u0631\u064e\u0636\u064b\u0627 \u0623\u064e\u0648\u06e1 \u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0647\u064e\u0670\u0644\u0650\u0643\u0650\u064a\u0646\u064e",translation:"Mereka berkata, \"Demi Allah, engkau tidak henti-hentinya mengingat Yusuf, sehingga engkau (mengidapkan penyakit) berat atau engkau termasuk orang-orang yang akan binasa"},{id:86,text:"\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0634\u06e1\u0643\u064f\u0648\u0627\u0652 \u0628\u064e\u062b\u0651\u0650\u064a \u0648\u064e\u062d\u064f\u0632\u06e1\u0646\u0650\u064a\u0653 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dia (Yakub) menjawab, \"Hanya kepada Allah aku mengadukan kesusahan dan kesedihanku. Dan aku mengetahui dari Allah apa yang tidak kamu ketahui"},{id:87,text:"\u064a\u064e\u0670\u0628\u064e\u0646\u0650\u064a\u0651\u064e \u0671\u0630\u06e1\u0647\u064e\u0628\u064f\u0648\u0627\u0652 \u0641\u064e\u062a\u064e\u062d\u064e\u0633\u0651\u064e\u0633\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u064a\u064f\u0648\u0633\u064f\u0641\u064e \u0648\u064e\u0623\u064e\u062e\u0650\u064a\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0627\u0652\u064a\u06e1\u0640\u0654\u064e\u0633\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0631\u0651\u064e\u0648\u06e1\u062d\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0627 \u064a\u064e\u0627\u0652\u064a\u06e1\u0640\u0654\u064e\u0633\u064f \u0645\u0650\u0646 \u0631\u0651\u064e\u0648\u06e1\u062d\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u064f \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Wahai anak-anakku! Pergilah kamu, carilah (berita) tentang Yusuf dan saudaranya dan jangan kamu berputus asa dari rahmat Allah. Sesungguhnya yang berputus asa dari rahmat Allah, hanyalah orang-orang yang kafir"},{id:88,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062f\u064e\u062e\u064e\u0644\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0645\u064e\u0633\u0651\u064e\u0646\u064e\u0627 \u0648\u064e\u0623\u064e\u0647\u06e1\u0644\u064e\u0646\u064e\u0627 \u0671\u0644\u0636\u0651\u064f\u0631\u0651\u064f \u0648\u064e\u062c\u0650\u0626\u06e1\u0646\u064e\u0627 \u0628\u0650\u0628\u0650\u0636\u064e\u0670\u0639\u064e\u0629\u0656 \u0645\u0651\u064f\u0632\u06e1\u062c\u064e\u0649\u0670\u0629\u0656 \u0641\u064e\u0623\u064e\u0648\u06e1\u0641\u0650 \u0644\u064e\u0646\u064e\u0627 \u0671\u0644\u06e1\u0643\u064e\u064a\u06e1\u0644\u064e \u0648\u064e\u062a\u064e\u0635\u064e\u062f\u0651\u064e\u0642\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627\u0653\u06d6 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u062c\u06e1\u0632\u0650\u064a \u0671\u0644\u06e1\u0645\u064f\u062a\u064e\u0635\u064e\u062f\u0651\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Maka ketika mereka masuk ke (tempat) Yusuf, mereka berkata, \"Wahai Al-Aziz! Kami dan keluarga kami telah ditimpa kesengsaraan dan kami datang membawa barang-barang yang tidak berharga, maka penuhilah jatah (gandum) untuk kami, dan bersedekahlah kepada kami. Sesungguhnya Allah memberi balasan kepada orang yang bersedekah"},{id:89,text:"\u0642\u064e\u0627\u0644\u064e \u0647\u064e\u0644\u06e1 \u0639\u064e\u0644\u0650\u0645\u06e1\u062a\u064f\u0645 \u0645\u0651\u064e\u0627 \u0641\u064e\u0639\u064e\u0644\u06e1\u062a\u064f\u0645 \u0628\u0650\u064a\u064f\u0648\u0633\u064f\u0641\u064e \u0648\u064e\u0623\u064e\u062e\u0650\u064a\u0647\u0650 \u0625\u0650\u0630\u06e1 \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u062c\u064e\u0670\u0647\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Dia (Yusuf) berkata, \"Tahukah kamu (kejelekan) apa yang telah kamu perbuat terhadap Yusuf dan saudaranya karena kamu tidak menyadari (akibat) perbuatanmu itu"},{id:90,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0621\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u0623\u064e\u0646\u062a\u064e \u064a\u064f\u0648\u0633\u064f\u0641\u064f\u06d6 \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0646\u064e\u0627\u06e0 \u064a\u064f\u0648\u0633\u064f\u0641\u064f \u0648\u064e\u0647\u064e\u0670\u0630\u064e\u0627\u0653 \u0623\u064e\u062e\u0650\u064a\u06d6 \u0642\u064e\u062f\u06e1 \u0645\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627\u0653\u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0645\u064e\u0646 \u064a\u064e\u062a\u0651\u064e\u0642\u0650 \u0648\u064e\u064a\u064e\u0635\u06e1\u0628\u0650\u0631\u06e1 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064f\u0636\u0650\u064a\u0639\u064f \u0623\u064e\u062c\u06e1\u0631\u064e \u0671\u0644\u06e1\u0645\u064f\u062d\u06e1\u0633\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Mereka berkata, \"Apakah engkau benar-benar Yusuf?\" Dia (Yusuf) menjawab, \"Aku Yusuf dan ini saudaraku. Sungguh, Allah telah melimpahkan karunia-Nya kepada kami.\" Sesungguhnya barang siapa bertakwa dan bersabar, maka sungguh, Allah tidak menyia-nyiakan pahala orang yang berbuat baik"},{id:91,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u062a\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0642\u064e\u062f\u06e1 \u0621\u064e\u0627\u062b\u064e\u0631\u064e\u0643\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0648\u064e\u0625\u0650\u0646 \u0643\u064f\u0646\u0651\u064e\u0627 \u0644\u064e\u062e\u064e\u0670\u0637\u0650\u0640\u0654\u0650\u064a\u0646\u064e",translation:"Mereka berkata, \"Demi Allah, sungguh Allah telah melebihkan engkau di atas kami, dan sesungguhnya kami adalah orang yang bersalah (berdosa)"},{id:92,text:"\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0627 \u062a\u064e\u062b\u06e1\u0631\u0650\u064a\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e\u06d6 \u064a\u064e\u063a\u06e1\u0641\u0650\u0631\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0623\u064e\u0631\u06e1\u062d\u064e\u0645\u064f \u0671\u0644\u0631\u0651\u064e\u0640\u0670\u062d\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dia (Yusuf) berkata, \"Pada hari ini tidak ada cercaan terhadap kamu, mudah-mudahan Allah mengampuni kamu. Dan Dia Maha Penyayang di antara para penyayang"},{id:93,text:"\u0671\u0630\u06e1\u0647\u064e\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0642\u064e\u0645\u0650\u064a\u0635\u0650\u064a \u0647\u064e\u0670\u0630\u064e\u0627 \u0641\u064e\u0623\u064e\u0644\u06e1\u0642\u064f\u0648\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0648\u064e\u062c\u06e1\u0647\u0650 \u0623\u064e\u0628\u0650\u064a \u064a\u064e\u0623\u06e1\u062a\u0650 \u0628\u064e\u0635\u0650\u064a\u0631\u0657\u0627 \u0648\u064e\u0623\u06e1\u062a\u064f\u0648\u0646\u0650\u064a \u0628\u0650\u0623\u064e\u0647\u06e1\u0644\u0650\u0643\u064f\u0645\u06e1 \u0623\u064e\u062c\u06e1\u0645\u064e\u0639\u0650\u064a\u0646\u064e",translation:"Pergilah kamu dengan membawa bajuku ini, lalu usapkan ke wajah ayahku, nanti dia akan melihat kembali; dan bawalah seluruh keluargamu kepadaku"},{id:94,text:"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0641\u064e\u0635\u064e\u0644\u064e\u062a\u0650 \u0671\u0644\u06e1\u0639\u0650\u064a\u0631\u064f \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0628\u064f\u0648\u0647\u064f\u0645\u06e1 \u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0623\u064e\u062c\u0650\u062f\u064f \u0631\u0650\u064a\u062d\u064e \u064a\u064f\u0648\u0633\u064f\u0641\u064e\u06d6 \u0644\u064e\u0648\u06e1\u0644\u064e\u0627\u0653 \u0623\u064e\u0646 \u062a\u064f\u0641\u064e\u0646\u0651\u0650\u062f\u064f\u0648\u0646\u0650",translation:"Dan ketika kafilah itu telah keluar (dari negeri Mesir), ayah mereka berkata, \"Sesungguhnya aku mencium bau Yusuf, sekiranya kamu tidak menuduhku lemah akal (tentu kamu membenarkan aku)"},{id:95,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u062a\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0670\u0644\u0650\u0643\u064e \u0671\u0644\u06e1\u0642\u064e\u062f\u0650\u064a\u0645\u0650",translation:"Mereka (keluarganya) berkata, \"Demi Allah, sesungguhnya engkau masih dalam kekeliruanmu yang dahulu"},{id:96,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u062c\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u06e1\u0628\u064e\u0634\u0650\u064a\u0631\u064f \u0623\u064e\u0644\u06e1\u0642\u064e\u0649\u0670\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0648\u064e\u062c\u06e1\u0647\u0650\u0647\u0650\u06e6 \u0641\u064e\u0671\u0631\u06e1\u062a\u064e\u062f\u0651\u064e \u0628\u064e\u0635\u0650\u064a\u0631\u0657\u0627\u06d6 \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0644\u064e\u0645\u06e1 \u0623\u064e\u0642\u064f\u0644 \u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Maka ketika telah tiba pembawa kabar gembira itu, maka diusapkannya (baju itu) ke wajahnya (Yakub), lalu dia dapat melihat kembali. Dia (Yakub) berkata, \"Bukankah telah aku katakan kepadamu, bahwa aku mengetahui dari Allah apa yang tidak kamu ketahui"},{id:97,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u064a\u064e\u0640\u0670\u0653\u0623\u064e\u0628\u064e\u0627\u0646\u064e\u0627 \u0671\u0633\u06e1\u062a\u064e\u063a\u06e1\u0641\u0650\u0631\u06e1 \u0644\u064e\u0646\u064e\u0627 \u0630\u064f\u0646\u064f\u0648\u0628\u064e\u0646\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u062e\u064e\u0670\u0637\u0650\u0640\u0654\u0650\u064a\u0646\u064e",translation:"Mereka berkata, \"Wahai ayah kami! Mohonkanlah ampunan untuk kami atas dosa-dosa kami, sesungguhnya kami adalah orang yang bersalah (berdosa)"},{id:98,text:"\u0642\u064e\u0627\u0644\u064e \u0633\u064e\u0648\u06e1\u0641\u064e \u0623\u064e\u0633\u06e1\u062a\u064e\u063a\u06e1\u0641\u0650\u0631\u064f \u0644\u064e\u0643\u064f\u0645\u06e1 \u0631\u064e\u0628\u0651\u0650\u064a\u0653\u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u063a\u064e\u0641\u064f\u0648\u0631\u064f \u0671\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",translation:"Dia (Yakub) berkata, \"Aku akan memohonkan ampunan bagimu kepada Tuhanku. Sungguh, Dia Yang Maha Pengampun, Maha Penyayang"},{id:99,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062f\u064e\u062e\u064e\u0644\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u064a\u064f\u0648\u0633\u064f\u0641\u064e \u0621\u064e\u0627\u0648\u064e\u0649\u0670\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0623\u064e\u0628\u064e\u0648\u064e\u064a\u06e1\u0647\u0650 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u062f\u06e1\u062e\u064f\u0644\u064f\u0648\u0627\u0652 \u0645\u0650\u0635\u06e1\u0631\u064e \u0625\u0650\u0646 \u0634\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0621\u064e\u0627\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Maka ketika mereka masuk ke (tempat) Yusuf, dia merangkul (dan menyiapkan tempat untuk) kedua orang tuanya seraya berkata, \"Masuklah kamu ke negeri Mesir, insya Allah dalam keadaan aman"},{id:100,text:"\u0648\u064e\u0631\u064e\u0641\u064e\u0639\u064e \u0623\u064e\u0628\u064e\u0648\u064e\u064a\u06e1\u0647\u0650 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0639\u064e\u0631\u06e1\u0634\u0650 \u0648\u064e\u062e\u064e\u0631\u0651\u064f\u0648\u0627\u0652 \u0644\u064e\u0647\u064f\u06e5 \u0633\u064f\u062c\u0651\u064e\u062f\u0657\u0627\u06d6 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0640\u0670\u0653\u0623\u064e\u0628\u064e\u062a\u0650 \u0647\u064e\u0670\u0630\u064e\u0627 \u062a\u064e\u0623\u06e1\u0648\u0650\u064a\u0644\u064f \u0631\u064f\u0621\u06e1\u064a\u064e\u0670\u064a\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f \u0642\u064e\u062f\u06e1 \u062c\u064e\u0639\u064e\u0644\u064e\u0647\u064e\u0627 \u0631\u064e\u0628\u0651\u0650\u064a \u062d\u064e\u0642\u0651\u0657\u0627\u06d6 \u0648\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064e \u0628\u0650\u064a\u0653 \u0625\u0650\u0630\u06e1 \u0623\u064e\u062e\u06e1\u0631\u064e\u062c\u064e\u0646\u0650\u064a \u0645\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u0650\u062c\u06e1\u0646\u0650 \u0648\u064e\u062c\u064e\u0627\u0653\u0621\u064e \u0628\u0650\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0628\u064e\u062f\u06e1\u0648\u0650 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0623\u064e\u0646 \u0646\u0651\u064e\u0632\u064e\u063a\u064e \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u064f \u0628\u064e\u064a\u06e1\u0646\u0650\u064a \u0648\u064e\u0628\u064e\u064a\u06e1\u0646\u064e \u0625\u0650\u062e\u06e1\u0648\u064e\u062a\u0650\u064a\u0653\u06da \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0644\u064e\u0637\u0650\u064a\u0641\u065e \u0644\u0651\u0650\u0645\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0639\u064e\u0644\u0650\u064a\u0645\u064f \u0671\u0644\u06e1\u062d\u064e\u0643\u0650\u064a\u0645\u064f",translation:"Dan dia menaikkan kedua orang tuanya ke atas singgasana. Dan mereka (semua) tunduk bersujud kepadanya (Yusuf). Dan dia (Yusuf) berkata, \"Wahai ayahku! Inilah takwil mimpiku yang dahulu. Dan sesungguhnya Tuhanku telah menjadikannya kenyataan. Sesungguhnya Tuhanku telah berbuat baik kepadaku, ketika Dia membebaskan aku dari penjara dan ketika membawa kamu dari dusun, setelah setan merusak (hubungan) antara aku dengan saudara-saudaraku. Sungguh, Tuhanku Mahalembut terhadap apa yang Dia kehendaki. Sungguh, Dia Yang Maha Mengetahui, Mahabijaksana"},{id:101,text:"\u06de\u0631\u064e\u0628\u0651\u0650 \u0642\u064e\u062f\u06e1 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u062a\u064e\u0646\u0650\u064a \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0644\u06e1\u0643\u0650 \u0648\u064e\u0639\u064e\u0644\u0651\u064e\u0645\u06e1\u062a\u064e\u0646\u0650\u064a \u0645\u0650\u0646 \u062a\u064e\u0623\u06e1\u0648\u0650\u064a\u0644\u0650 \u0671\u0644\u06e1\u0623\u064e\u062d\u064e\u0627\u062f\u0650\u064a\u062b\u0650\u06da \u0641\u064e\u0627\u0637\u0650\u0631\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0623\u064e\u0646\u062a\u064e \u0648\u064e\u0644\u0650\u064a\u0651\u0650\u06e6 \u0641\u0650\u064a \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0648\u064e\u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650\u06d6 \u062a\u064e\u0648\u064e\u0641\u0651\u064e\u0646\u0650\u064a \u0645\u064f\u0633\u06e1\u0644\u0650\u0645\u0657\u0627 \u0648\u064e\u0623\u064e\u0644\u06e1\u062d\u0650\u0642\u06e1\u0646\u0650\u064a \u0628\u0650\u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u0650\u064a\u0646\u064e",translation:"Tuhanku, sesungguhnya Engkau telah menganugerahkan kepadaku sebagian kekuasaan dan telah mengajarkan kepadaku sebagian takwil mimpi. (Wahai Tuhan) pencipta langit dan bumi, Engkaulah pelindungku di dunia dan di akhirat, wafatkanlah aku dalam keadaan muslim dan gabungkanlah aku dengan orang yang saleh"},{id:102,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u0650\u0646\u06e1 \u0623\u064e\u0646\u06e2\u0628\u064e\u0627\u0653\u0621\u0650 \u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u0628\u0650 \u0646\u064f\u0648\u062d\u0650\u064a\u0647\u0650 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e\u06d6 \u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064e \u0644\u064e\u062f\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0625\u0650\u0630\u06e1 \u0623\u064e\u062c\u06e1\u0645\u064e\u0639\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0645\u06e1\u0631\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0645\u06e1\u0643\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Itulah sebagian berita gaib yang Kami wahyukan kepadamu (Muhammad); padahal engkau tidak berada di samping mereka, ketika mereka bersepakat mengatur tipu muslihat (untuk memasukan Yusuf ke dalam sumur)"},{id:103,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0644\u064e\u0648\u06e1 \u062d\u064e\u0631\u064e\u0635\u06e1\u062a\u064e \u0628\u0650\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dan kebanyakan manusia tidak akan beriman walaupun engkau sangat menginginkannya"},{id:104,text:"\u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0647\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0645\u0650\u0646\u06e1 \u0623\u064e\u062c\u06e1\u0631\u064d\u06da \u0625\u0650\u0646\u06e1 \u0647\u064f\u0648\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0630\u0650\u0643\u06e1\u0631\u065e \u0644\u0651\u0650\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Dan engkau tidak meminta imbalan apa pun kepada mereka (terhadap seruanmu ini), sebab (seruan) itu adalah pengajaran bagi seluruh alam"},{id:105,text:"\u0648\u064e\u0643\u064e\u0623\u064e\u064a\u0651\u0650\u0646 \u0645\u0651\u0650\u0646\u06e1 \u0621\u064e\u0627\u064a\u064e\u0629\u0656 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u064a\u064e\u0645\u064f\u0631\u0651\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0646\u06e1\u0647\u064e\u0627 \u0645\u064f\u0639\u06e1\u0631\u0650\u0636\u064f\u0648\u0646\u064e",translation:"Dan berapa banyak tanda-tanda (kebesaran Allah) di langit dan di bumi yang mereka lalui, namun mereka berpaling darinya"},{id:106,text:"\u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064f\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0648\u064e\u0647\u064f\u0645 \u0645\u0651\u064f\u0634\u06e1\u0631\u0650\u0643\u064f\u0648\u0646\u064e",translation:"Dan kebanyakan mereka tidak beriman kepada Allah, bahkan mereka mempersekutukan-Nya"},{id:107,text:"\u0623\u064e\u0641\u064e\u0623\u064e\u0645\u0650\u0646\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646 \u062a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e\u0647\u064f\u0645\u06e1 \u063a\u064e\u0670\u0634\u0650\u064a\u064e\u0629\u065e \u0645\u0651\u0650\u0646\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0648\u06e1 \u062a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064f \u0628\u064e\u063a\u06e1\u062a\u064e\u0629\u0657 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0634\u06e1\u0639\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Apakah mereka merasa aman dari kedatangan siksa Allah yang meliputi mereka, atau kedatangan kiamat kepada mereka secara mendadak, sedangkan mereka tidak menyadarinya"},{id:108,text:"\u0642\u064f\u0644\u06e1 \u0647\u064e\u0670\u0630\u0650\u0647\u0650\u06e6 \u0633\u064e\u0628\u0650\u064a\u0644\u0650\u064a\u0653 \u0623\u064e\u062f\u06e1\u0639\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0635\u0650\u064a\u0631\u064e\u0629\u064d \u0623\u064e\u0646\u064e\u0627\u06e0 \u0648\u064e\u0645\u064e\u0646\u0650 \u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064e\u0646\u0650\u064a\u06d6 \u0648\u064e\u0633\u064f\u0628\u06e1\u062d\u064e\u0670\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u064e\u0627\u06e0 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0634\u06e1\u0631\u0650\u0643\u0650\u064a\u0646\u064e",translation:"Katakanlah (Muhammad), \"Inilah jalanku, aku dan orang-orang yang mengikutiku mengajak (kamu) kepada Allah dengan yakin, Mahasuci Allah, dan aku tidak termasuk orang-orang musyrik"},{id:109,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0631\u0650\u062c\u064e\u0627\u0644\u0657\u0627 \u0646\u0651\u064f\u0648\u062d\u0650\u064a\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u0647\u06e1\u0644\u0650 \u0671\u0644\u06e1\u0642\u064f\u0631\u064e\u0649\u0670\u0653\u06d7 \u0623\u064e\u0641\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0633\u0650\u064a\u0631\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0641\u064e\u064a\u064e\u0646\u0638\u064f\u0631\u064f\u0648\u0627\u0652 \u0643\u064e\u064a\u06e1\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0670\u0642\u0650\u0628\u064e\u0629\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u0645\u06e1\u06d7 \u0648\u064e\u0644\u064e\u062f\u064e\u0627\u0631\u064f \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u062e\u064e\u064a\u06e1\u0631\u065e \u0644\u0651\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u062a\u0651\u064e\u0642\u064e\u0648\u06e1\u0627\u0652\u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Dan Kami tidak mengutus sebelummu (Muhammad), melainkan orang laki-laki yang Kami berikan wahyu kepadanya di antara penduduk negeri. Tidakkah mereka bepergian di bumi lalu melihat bagaimana kesudahan orang-orang sebelum mereka (yang mendustakan rasul). Dan sungguh, negeri akhirat itu lebih baik bagi orang yang bertakwa. Tidakkah kamu mengerti"},{id:110,text:"\u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u064e\u0627 \u0671\u0633\u06e1\u062a\u064e\u064a\u06e1\u0640\u0654\u064e\u0633\u064e \u0671\u0644\u0631\u0651\u064f\u0633\u064f\u0644\u064f \u0648\u064e\u0638\u064e\u0646\u0651\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0642\u064e\u062f\u06e1 \u0643\u064f\u0630\u0650\u0628\u064f\u0648\u0627\u0652 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u06e1 \u0646\u064e\u0635\u06e1\u0631\u064f\u0646\u064e\u0627 \u0641\u064e\u0646\u064f\u062c\u0651\u0650\u064a\u064e \u0645\u064e\u0646 \u0646\u0651\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06d6 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0631\u064e\u062f\u0651\u064f \u0628\u064e\u0623\u06e1\u0633\u064f\u0646\u064e\u0627 \u0639\u064e\u0646\u0650 \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0645\u064f\u062c\u06e1\u0631\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Sehingga apabila para rasul tidak mempunyai harapan lagi (tentang keimanan kaumnya) dan telah meyakini bahwa mereka telah didustakan, datanglah kepada mereka (para rasul) itu pertolongan Kami, lalu diselamatkan orang yang Kami kehendaki. Dan siksa Kami tidak dapat ditolak dari orang yang berdosa"},{id:111,text:"\u0644\u064e\u0642\u064e\u062f\u06e1 \u0643\u064e\u0627\u0646\u064e \u0641\u0650\u064a \u0642\u064e\u0635\u064e\u0635\u0650\u0647\u0650\u0645\u06e1 \u0639\u0650\u0628\u06e1\u0631\u064e\u0629\u065e \u0644\u0651\u0650\u0623\u064f\u0648\u0652\u0644\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0644\u06e1\u0628\u064e\u0670\u0628\u0650\u06d7 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u062d\u064e\u062f\u0650\u064a\u062b\u0657\u0627 \u064a\u064f\u0641\u06e1\u062a\u064e\u0631\u064e\u0649\u0670 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u062a\u064e\u0635\u06e1\u062f\u0650\u064a\u0642\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0628\u064e\u064a\u06e1\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u06e1\u0647\u0650 \u0648\u064e\u062a\u064e\u0641\u06e1\u0635\u0650\u064a\u0644\u064e \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0648\u064e\u0647\u064f\u062f\u0657\u0649 \u0648\u064e\u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u0657 \u0644\u0651\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Sungguh, pada kisah-kisah mereka itu terdapat pengajaran bagi orang yang mempunyai akal. (Alquran) itu bukanlah cerita yang dibuat-buat, tetapi membenarkan (kitab-kitab) yang sebelumnya, menjelaskan segala sesuatu, dan (sebagai) petunjuk dan rahmat bagi orang-orang yang beriman"}]},{id:13,name:"\u0627\u0644\u0631\u0639\u062f",transliteration:"Ar-Ra'd",translation:"Guruh (Petir)",type:"medinan",total_verses:43,verses:[{id:1,text:"\u0627\u0644\u0653\u0645\u0653\u0631\u06da \u062a\u0650\u0644\u06e1\u0643\u064e \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u064f \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650\u06d7 \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064e \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Alif L\u0101m M\u012bm R\u0101`. Ini adalah ayat-ayat Kitab (Alquran). Dan (Kitab) yang diturunkan kepadamu (Muhammad) dari Tuhanmu itu adalah benar; tetapi kebanyakan manusia tidak beriman (kepadanya)"},{id:2,text:"\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0631\u064e\u0641\u064e\u0639\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0628\u0650\u063a\u064e\u064a\u06e1\u0631\u0650 \u0639\u064e\u0645\u064e\u062f\u0656 \u062a\u064e\u0631\u064e\u0648\u06e1\u0646\u064e\u0647\u064e\u0627\u06d6 \u062b\u064f\u0645\u0651\u064e \u0671\u0633\u06e1\u062a\u064e\u0648\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0639\u064e\u0631\u06e1\u0634\u0650\u06d6 \u0648\u064e\u0633\u064e\u062e\u0651\u064e\u0631\u064e \u0671\u0644\u0634\u0651\u064e\u0645\u06e1\u0633\u064e \u0648\u064e\u0671\u0644\u06e1\u0642\u064e\u0645\u064e\u0631\u064e\u06d6 \u0643\u064f\u0644\u0651\u065e \u064a\u064e\u062c\u06e1\u0631\u0650\u064a \u0644\u0650\u0623\u064e\u062c\u064e\u0644\u0656 \u0645\u0651\u064f\u0633\u064e\u0645\u0651\u0657\u0649\u06da \u064a\u064f\u062f\u064e\u0628\u0651\u0650\u0631\u064f \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0631\u064e \u064a\u064f\u0641\u064e\u0635\u0651\u0650\u0644\u064f \u0671\u0644\u06e1\u0623\u0653\u064a\u064e\u0670\u062a\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645 \u0628\u0650\u0644\u0650\u0642\u064e\u0627\u0653\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1 \u062a\u064f\u0648\u0642\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Allah yang meninggikan langit tanpa tiang (sebagaimana) yang kamu lihat, kemudian Dia bersemayam di atas Arasy. Dia menundukkan matahari dan bulan; masing-masing beredar menurut waktu yang telah ditentukan. Dia mengatur urusan (makhluk-Nya), dan menjelaskan tanda-tanda (kebesaran-Nya), agar kamu yakin akan pertemuan dengan Tuhanmu"},{id:3,text:"\u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0645\u064e\u062f\u0651\u064e \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0631\u064e\u0648\u064e\u0670\u0633\u0650\u064a\u064e \u0648\u064e\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u0657\u0627\u06d6 \u0648\u064e\u0645\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u0671\u0644\u062b\u0651\u064e\u0645\u064e\u0631\u064e\u0670\u062a\u0650 \u062c\u064e\u0639\u064e\u0644\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0632\u064e\u0648\u06e1\u062c\u064e\u064a\u06e1\u0646\u0650 \u0671\u062b\u06e1\u0646\u064e\u064a\u06e1\u0646\u0650\u06d6 \u064a\u064f\u063a\u06e1\u0634\u0650\u064a \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u064e \u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e\u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0623\u0653\u064a\u064e\u0670\u062a\u0656 \u0644\u0651\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064e\u062a\u064e\u0641\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan Dia yang menghamparkan bumi dan menjadikan gunung-gunung dan sungai-sungai di atasnya. Dan padanya Dia menjadikan semua buah-buahan berpasang-pasangan; Dia menutupkan malam kepada siang. Sungguh, pada yang demikian itu terdapat tanda-tanda (kebesaran Allah) bagi orang-orang yang berpikir"},{id:4,text:"\u0648\u064e\u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0642\u0650\u0637\u064e\u0639\u065e \u0645\u0651\u064f\u062a\u064e\u062c\u064e\u0670\u0648\u0650\u0631\u064e\u0670\u062a\u065e \u0648\u064e\u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u065e \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u0639\u06e1\u0646\u064e\u0670\u0628\u0656 \u0648\u064e\u0632\u064e\u0631\u06e1\u0639\u065e \u0648\u064e\u0646\u064e\u062e\u0650\u064a\u0644\u065e \u0635\u0650\u0646\u06e1\u0648\u064e\u0627\u0646\u065e \u0648\u064e\u063a\u064e\u064a\u06e1\u0631\u064f \u0635\u0650\u0646\u06e1\u0648\u064e\u0627\u0646\u0656 \u064a\u064f\u0633\u06e1\u0642\u064e\u0649\u0670 \u0628\u0650\u0645\u064e\u0627\u0653\u0621\u0656 \u0648\u064e\u0670\u062d\u0650\u062f\u0656 \u0648\u064e\u0646\u064f\u0641\u064e\u0636\u0651\u0650\u0644\u064f \u0628\u064e\u0639\u06e1\u0636\u064e\u0647\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u06e1\u0636\u0656 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064f\u0643\u064f\u0644\u0650\u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0623\u0653\u064a\u064e\u0670\u062a\u0656 \u0644\u0651\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Dan di bumi terdapat bagian-bagian yang berdampingan, kebun-kebun anggur, tanaman-tanaman, pohon kurma yang bercabang, dan yang tidak bercabang; disirami dengan air yang sama, tetapi Kami lebihkan tanaman yang satu dari yang lainnya dalam hal rasanya. Sungguh, pada yang demikian itu terdapat tanda-tanda (kebesaran Allah) bagi orang-orang yang berakal"},{id:5,text:"\u06de\u0648\u064e\u0625\u0650\u0646 \u062a\u064e\u0639\u06e1\u062c\u064e\u0628\u06e1 \u0641\u064e\u0639\u064e\u062c\u064e\u0628\u065e \u0642\u064e\u0648\u06e1\u0644\u064f\u0647\u064f\u0645\u06e1 \u0623\u064e\u0621\u0650\u0630\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u062a\u064f\u0631\u064e\u0670\u0628\u064b\u0627 \u0623\u064e\u0621\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0641\u0650\u064a \u062e\u064e\u0644\u06e1\u0642\u0656 \u062c\u064e\u062f\u0650\u064a\u062f\u064d\u06d7 \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1\u06d6 \u0648\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0671\u0644\u06e1\u0623\u064e\u063a\u06e1\u0644\u064e\u0670\u0644\u064f \u0641\u0650\u064a\u0653 \u0623\u064e\u0639\u06e1\u0646\u064e\u0627\u0642\u0650\u0647\u0650\u0645\u06e1\u06d6 \u0648\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650\u06d6 \u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u0670\u0644\u0650\u062f\u064f\u0648\u0646\u064e",translation:"Dan jika engkau merasa heran, maka yang mengherankan adalah ucapan mereka, \" Apabila kami telah menjadi tanah, apakah kami akan (dikembalikan) menjadi makhluk yang baru?\" Mereka itulah yang ingkar kepada Tuhannya; dan mereka itulah (yang dilekatkan) belenggu di lehernya. Mereka adalah penghuni neraka, mereka kekal di dalamnya"},{id:6,text:"\u0648\u064e\u064a\u064e\u0633\u06e1\u062a\u064e\u0639\u06e1\u062c\u0650\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u0628\u0650\u0671\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u0650 \u0642\u064e\u0628\u06e1\u0644\u064e \u0671\u0644\u06e1\u062d\u064e\u0633\u064e\u0646\u064e\u0629\u0650 \u0648\u064e\u0642\u064e\u062f\u06e1 \u062e\u064e\u0644\u064e\u062a\u06e1 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u0645\u064f \u0671\u0644\u06e1\u0645\u064e\u062b\u064f\u0644\u064e\u0670\u062a\u064f\u06d7 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0644\u064e\u0630\u064f\u0648 \u0645\u064e\u063a\u06e1\u0641\u0650\u0631\u064e\u0629\u0656 \u0644\u0651\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0639\u064e\u0644\u064e\u0649\u0670 \u0638\u064f\u0644\u06e1\u0645\u0650\u0647\u0650\u0645\u06e1\u06d6 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0644\u064e\u0634\u064e\u062f\u0650\u064a\u062f\u064f \u0671\u0644\u06e1\u0639\u0650\u0642\u064e\u0627\u0628\u0650",translation:"Dan mereka meminta kepadamu agar dipercepat (datangnya) siksaan, sebelum (mereka meminta) kebaikan, padahal telah terjadi bermacam-macam contoh siksaan sebelum mereka. Sungguh, Tuhanmu benar-benar memiliki ampunan bagi manusia atas kezaliman mereka, dan sungguh, Tuhanmu sangat keras siksaan-Nya"},{id:7,text:"\u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0644\u064e\u0648\u06e1\u0644\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0621\u064e\u0627\u064a\u064e\u0629\u065e \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0647\u0650\u06e6\u0653\u06d7 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064e \u0645\u064f\u0646\u0630\u0650\u0631\u065e\u06d6 \u0648\u064e\u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0642\u064e\u0648\u06e1\u0645\u064d \u0647\u064e\u0627\u062f\u064d",translation:"Dan orang-orang kafir berkata, \"Mengapa tidak diturunkan kepadanya (Muhammad) suatu tanda (mukjizat) dari Tuhannya?\" Sesungguhnya engkau hanyalah seorang pemberi peringatan; dan bagi setiap kaum ada orang yang memberi petunjuk"},{id:8,text:"\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u062a\u064e\u062d\u06e1\u0645\u0650\u0644\u064f \u0643\u064f\u0644\u0651\u064f \u0623\u064f\u0646\u062b\u064e\u0649\u0670 \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u063a\u0650\u064a\u0636\u064f \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u062d\u064e\u0627\u0645\u064f \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0632\u06e1\u062f\u064e\u0627\u062f\u064f\u06da \u0648\u064e\u0643\u064f\u0644\u0651\u064f \u0634\u064e\u064a\u06e1\u0621\u064d \u0639\u0650\u0646\u062f\u064e\u0647\u064f\u06e5 \u0628\u0650\u0645\u0650\u0642\u06e1\u062f\u064e\u0627\u0631\u064d",translation:"Allah mengetahui apa yang dikandung oleh setiap perempuan, apa yang kurang sempurna dan apa yang bertambah dalam rahim. Dan segala sesuatu ada ukuran di sisi-Nya"},{id:9,text:"\u0639\u064e\u0670\u0644\u0650\u0645\u064f \u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u0628\u0650 \u0648\u064e\u0671\u0644\u0634\u0651\u064e\u0647\u064e\u0670\u062f\u064e\u0629\u0650 \u0671\u0644\u06e1\u0643\u064e\u0628\u0650\u064a\u0631\u064f \u0671\u0644\u06e1\u0645\u064f\u062a\u064e\u0639\u064e\u0627\u0644\u0650",translation:"(Allah) Yang mengetahui semua yang gaib dan yang nyata; Yang Mahabesar, Mahatinggi"},{id:10,text:"\u0633\u064e\u0648\u064e\u0627\u0653\u0621\u065e \u0645\u0651\u0650\u0646\u0643\u064f\u0645 \u0645\u0651\u064e\u0646\u06e1 \u0623\u064e\u0633\u064e\u0631\u0651\u064e \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0644\u064e \u0648\u064e\u0645\u064e\u0646 \u062c\u064e\u0647\u064e\u0631\u064e \u0628\u0650\u0647\u0650\u06e6 \u0648\u064e\u0645\u064e\u0646\u06e1 \u0647\u064f\u0648\u064e \u0645\u064f\u0633\u06e1\u062a\u064e\u062e\u06e1\u0641\u0650\u06ed \u0628\u0650\u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u0650 \u0648\u064e\u0633\u064e\u0627\u0631\u0650\u0628\u064f\u06e2 \u0628\u0650\u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650",translation:"Sama saja (bagi Allah), siapa di antaramu yang merahasiakan ucapannya dan siapa yang berterus terang dengannya; dan siapa yang bersembunyi pada malam hari dan yang berjalan pada siang hari"},{id:11,text:"\u0644\u064e\u0647\u064f\u06e5 \u0645\u064f\u0639\u064e\u0642\u0651\u0650\u0628\u064e\u0670\u062a\u065e \u0645\u0651\u0650\u0646\u06e2 \u0628\u064e\u064a\u06e1\u0646\u0650 \u064a\u064e\u062f\u064e\u064a\u06e1\u0647\u0650 \u0648\u064e\u0645\u0650\u0646\u06e1 \u062e\u064e\u0644\u06e1\u0641\u0650\u0647\u0650\u06e6 \u064a\u064e\u062d\u06e1\u0641\u064e\u0638\u064f\u0648\u0646\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646\u06e1 \u0623\u064e\u0645\u06e1\u0631\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d7 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064f\u063a\u064e\u064a\u0651\u0650\u0631\u064f \u0645\u064e\u0627 \u0628\u0650\u0642\u064e\u0648\u06e1\u0645\u064d \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064f\u063a\u064e\u064a\u0651\u0650\u0631\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u0628\u0650\u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u06e1\u06d7 \u0648\u064e\u0625\u0650\u0630\u064e\u0627\u0653 \u0623\u064e\u0631\u064e\u0627\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u0633\u064f\u0648\u0653\u0621\u0657\u0627 \u0641\u064e\u0644\u064e\u0627 \u0645\u064e\u0631\u064e\u062f\u0651\u064e \u0644\u064e\u0647\u064f\u06e5\u06da \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u06e6 \u0645\u0650\u0646 \u0648\u064e\u0627\u0644\u064d",translation:"Baginya (manusia) ada malaikat-malaikat yang selalu menjaganya bergiliran, dari depan dan belakangnya. Mereka menjaganya atas perintah Allah. Sesungguhnya Allah tidak mengubah keadaan suatu kaum sebelum mereka mengubah keadaan diri mereka sendiri. Dan apabila Allah menghendaki keburukan terhadap suatu kaum, maka tak ada yang dapat menolaknya dan tidak ada pelindung bagi mereka selain Dia"},{id:12,text:"\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u0631\u0650\u064a\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0628\u064e\u0631\u06e1\u0642\u064e \u062e\u064e\u0648\u06e1\u0641\u0657\u0627 \u0648\u064e\u0637\u064e\u0645\u064e\u0639\u0657\u0627 \u0648\u064e\u064a\u064f\u0646\u0634\u0650\u0626\u064f \u0671\u0644\u0633\u0651\u064e\u062d\u064e\u0627\u0628\u064e \u0671\u0644\u062b\u0651\u0650\u0642\u064e\u0627\u0644\u064e",translation:"Dialah yang memperlihatkan kilat kepadamu yang menimbulkan ketakutan dan harapan, dan Dia menjadikan awan mendung"},{id:13,text:"\u0648\u064e\u064a\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u064f \u0671\u0644\u0631\u0651\u064e\u0639\u06e1\u062f\u064f \u0628\u0650\u062d\u064e\u0645\u06e1\u062f\u0650\u0647\u0650\u06e6 \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u064f \u0645\u0650\u0646\u06e1 \u062e\u0650\u064a\u0641\u064e\u062a\u0650\u0647\u0650\u06e6 \u0648\u064e\u064a\u064f\u0631\u06e1\u0633\u0650\u0644\u064f \u0671\u0644\u0635\u0651\u064e\u0648\u064e\u0670\u0639\u0650\u0642\u064e \u0641\u064e\u064a\u064f\u0635\u0650\u064a\u0628\u064f \u0628\u0650\u0647\u064e\u0627 \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0648\u064e\u0647\u064f\u0645\u06e1 \u064a\u064f\u062c\u064e\u0670\u062f\u0650\u0644\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0647\u064f\u0648\u064e \u0634\u064e\u062f\u0650\u064a\u062f\u064f \u0671\u0644\u06e1\u0645\u0650\u062d\u064e\u0627\u0644\u0650",translation:"Dan guruh bertasbih memuji-Nya, (demikian pula) para malaikat karena takut kepada-Nya, dan Allah melepaskan halilintar, lalu menimpakannya kepada siapa yang Dia kehendaki, sementara mereka berbantah-bantahan tentang Allah, dan Dia Mahakeras siksaan-Nya"},{id:14,text:"\u0644\u064e\u0647\u064f\u06e5 \u062f\u064e\u0639\u06e1\u0648\u064e\u0629\u064f \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650\u06da \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u06e6 \u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u062c\u0650\u064a\u0628\u064f\u0648\u0646\u064e \u0644\u064e\u0647\u064f\u0645 \u0628\u0650\u0634\u064e\u064a\u06e1\u0621\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064e\u0628\u064e\u0670\u0633\u0650\u0637\u0650 \u0643\u064e\u0641\u0651\u064e\u064a\u06e1\u0647\u0650 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u0645\u064e\u0627\u0653\u0621\u0650 \u0644\u0650\u064a\u064e\u0628\u06e1\u0644\u064f\u063a\u064e \u0641\u064e\u0627\u0647\u064f \u0648\u064e\u0645\u064e\u0627 \u0647\u064f\u0648\u064e \u0628\u0650\u0628\u064e\u0670\u0644\u0650\u063a\u0650\u0647\u0650\u06e6\u06da \u0648\u064e\u0645\u064e\u0627 \u062f\u064f\u0639\u064e\u0627\u0653\u0621\u064f \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0670\u0644\u0656",translation:"Hanya kepada Allah doa yang benar. Berhala-berhala yang mereka sembah selain Allah tidak dapat mengabulkan apa pun bagi mereka, tidak ubahnya seperti orang yang membukakan kedua telapak tangannya ke dalam air agar (air) sampai ke mulutnya. Padahal air itu tidak akan sampai ke mulutnya. Dan doa orang-orang kafir itu, hanyalah sia-sia belaka"},{id:15,text:"\u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650\u06e4 \u064a\u064e\u0633\u06e1\u062c\u064f\u062f\u064f\u06e4 \u0645\u064e\u0646 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0637\u064e\u0648\u06e1\u0639\u0657\u0627 \u0648\u064e\u0643\u064e\u0631\u06e1\u0647\u0657\u0627 \u0648\u064e\u0638\u0650\u0644\u064e\u0670\u0644\u064f\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u063a\u064f\u062f\u064f\u0648\u0651\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u0653\u0635\u064e\u0627\u0644\u0650\u06e9",translation:"Dan semua sujud kepada Allah baik yang di langit maupun yang di bumi, baik dengan kemauan sendiri maupun terpaksa (dan sujud pula) bayang-bayang mereka, pada waktu pagi dan petang hari"},{id:16,text:"\u0642\u064f\u0644\u06e1 \u0645\u064e\u0646 \u0631\u0651\u064e\u0628\u0651\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0642\u064f\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06da \u0642\u064f\u0644\u06e1 \u0623\u064e\u0641\u064e\u0671\u062a\u0651\u064e\u062e\u064e\u0630\u06e1\u062a\u064f\u0645 \u0645\u0651\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0648\u06e1\u0644\u0650\u064a\u064e\u0627\u0653\u0621\u064e \u0644\u064e\u0627 \u064a\u064e\u0645\u06e1\u0644\u0650\u0643\u064f\u0648\u0646\u064e \u0644\u0650\u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u06e1 \u0646\u064e\u0641\u06e1\u0639\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u0636\u064e\u0631\u0651\u0657\u0627\u06da \u0642\u064f\u0644\u06e1 \u0647\u064e\u0644\u06e1 \u064a\u064e\u0633\u06e1\u062a\u064e\u0648\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0639\u06e1\u0645\u064e\u0649\u0670 \u0648\u064e\u0671\u0644\u06e1\u0628\u064e\u0635\u0650\u064a\u0631\u064f \u0623\u064e\u0645\u06e1 \u0647\u064e\u0644\u06e1 \u062a\u064e\u0633\u06e1\u062a\u064e\u0648\u0650\u064a \u0671\u0644\u0638\u0651\u064f\u0644\u064f\u0645\u064e\u0670\u062a\u064f \u0648\u064e\u0671\u0644\u0646\u0651\u064f\u0648\u0631\u064f\u06d7 \u0623\u064e\u0645\u06e1 \u062c\u064e\u0639\u064e\u0644\u064f\u0648\u0627\u0652 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0653\u0621\u064e \u062e\u064e\u0644\u064e\u0642\u064f\u0648\u0627\u0652 \u0643\u064e\u062e\u064e\u0644\u06e1\u0642\u0650\u0647\u0650\u06e6 \u0641\u064e\u062a\u064e\u0634\u064e\u0670\u0628\u064e\u0647\u064e \u0671\u0644\u06e1\u062e\u064e\u0644\u06e1\u0642\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1\u06da \u0642\u064f\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u062e\u064e\u0670\u0644\u0650\u0642\u064f \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0648\u064e\u0670\u062d\u0650\u062f\u064f \u0671\u0644\u06e1\u0642\u064e\u0647\u0651\u064e\u0640\u0670\u0631\u064f",translation:"Katakanlah (Muhammad), \"Siapakah Tuhan langit dan bumi?\" katakanlah, \"Allah.\" Katakanlah, \"Pantaskah kamu mengambil pelindung-pelindung selain Allah, padahal mereka tidak kuasa mendatangkan manfaat maupun menolak mudarat bagi dirinya sendiri?\" Katakanlah, \"Samakah orang yang buta dengan yang dapat melihat? Atau samakah yang gelap dengan yang terang? Apakah mereka menjadikan sekutu-sekutu bagi Allah yang dapat menciptakan seperti ciptaan-Nya sehingga kedua ciptaan itu serupa menurut pandangan mereka?\" Katakanlah, \"Allah adalah Pencipta segala sesuatu dan Dia Tuhan Yang Maha Esa, Mahaperkasa"},{id:17,text:"\u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0645\u064e\u0627\u0653\u0621\u0657 \u0641\u064e\u0633\u064e\u0627\u0644\u064e\u062a\u06e1 \u0623\u064e\u0648\u06e1\u062f\u0650\u064a\u064e\u0629\u064f\u06e2 \u0628\u0650\u0642\u064e\u062f\u064e\u0631\u0650\u0647\u064e\u0627 \u0641\u064e\u0671\u062d\u06e1\u062a\u064e\u0645\u064e\u0644\u064e \u0671\u0644\u0633\u0651\u064e\u064a\u06e1\u0644\u064f \u0632\u064e\u0628\u064e\u062f\u0657\u0627 \u0631\u0651\u064e\u0627\u0628\u0650\u064a\u0657\u0627\u06d6 \u0648\u064e\u0645\u0650\u0645\u0651\u064e\u0627 \u064a\u064f\u0648\u0642\u0650\u062f\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0641\u0650\u064a \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0671\u0628\u06e1\u062a\u0650\u063a\u064e\u0627\u0653\u0621\u064e \u062d\u0650\u0644\u06e1\u064a\u064e\u0629\u064d \u0623\u064e\u0648\u06e1 \u0645\u064e\u062a\u064e\u0670\u0639\u0656 \u0632\u064e\u0628\u064e\u062f\u065e \u0645\u0651\u0650\u062b\u06e1\u0644\u064f\u0647\u064f\u06e5\u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064e\u0636\u06e1\u0631\u0650\u0628\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064e \u0648\u064e\u0671\u0644\u06e1\u0628\u064e\u0670\u0637\u0650\u0644\u064e\u06da \u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0671\u0644\u0632\u0651\u064e\u0628\u064e\u062f\u064f \u0641\u064e\u064a\u064e\u0630\u06e1\u0647\u064e\u0628\u064f \u062c\u064f\u0641\u064e\u0627\u0653\u0621\u0657\u06d6 \u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0645\u064e\u0627 \u064a\u064e\u0646\u0641\u064e\u0639\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0641\u064e\u064a\u064e\u0645\u06e1\u0643\u064f\u062b\u064f \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064e\u0636\u06e1\u0631\u0650\u0628\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u062b\u064e\u0627\u0644\u064e",translation:"Allah telah menurunkan air (hujan) dari langit, maka mengalirlah ia (air) di lembah-lembah menurut ukurannya, maka arus itu membawa buih yang mengambang. Dan dari apa (logam) yang mereka lebur dalam api untuk membuat perhiasan atau alat-alat, ada (pula) buihnya seperti (buih arus) itu. Demikianlah Allah membuat perumpamaan (tentang) yang benar dan yang batil. Adapun buih, akan hilang sebagai sesuatu yang tidak ada gunanya; tetapi yang bermanfaat bagi manusia, akan tetap ada di bumi. Demikianlah Allah membuat perumpamaan"},{id:18,text:"\u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u0633\u06e1\u062a\u064e\u062c\u064e\u0627\u0628\u064f\u0648\u0627\u0652 \u0644\u0650\u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u064f \u0671\u0644\u06e1\u062d\u064f\u0633\u06e1\u0646\u064e\u0649\u0670\u06da \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0645\u06e1 \u064a\u064e\u0633\u06e1\u062a\u064e\u062c\u0650\u064a\u0628\u064f\u0648\u0627\u0652 \u0644\u064e\u0647\u064f\u06e5 \u0644\u064e\u0648\u06e1 \u0623\u064e\u0646\u0651\u064e \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u062c\u064e\u0645\u0650\u064a\u0639\u0657\u0627 \u0648\u064e\u0645\u0650\u062b\u06e1\u0644\u064e\u0647\u064f\u06e5 \u0645\u064e\u0639\u064e\u0647\u064f\u06e5 \u0644\u064e\u0671\u0641\u06e1\u062a\u064e\u062f\u064e\u0648\u06e1\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6\u0653\u06da \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0633\u064f\u0648\u0653\u0621\u064f \u0671\u0644\u06e1\u062d\u0650\u0633\u064e\u0627\u0628\u0650 \u0648\u064e\u0645\u064e\u0623\u06e1\u0648\u064e\u0649\u0670\u0647\u064f\u0645\u06e1 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064f\u06d6 \u0648\u064e\u0628\u0650\u0626\u06e1\u0633\u064e \u0671\u0644\u06e1\u0645\u0650\u0647\u064e\u0627\u062f\u064f",translation:"Bagi orang-orang yang memenuhi seruan Tuhan, mereka (disediakan) balasan yang baik. Dan orang-orang yang tidak memenuhi seruan-Nya, sekiranya mereka memiliki semua yang ada di bumi dan (ditambah) sebanyak itu lagi, niscaya mereka akan menebus dirinya dengan itu. Orang-orang itu mendapat hisab (perhitungan) yang buruk dan tempat kediaman mereka Jahanam, dan itulah seburuk-buruk tempat kediaman"},{id:19,text:"\u06de\u0623\u064e\u0641\u064e\u0645\u064e\u0646 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064e \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f \u0643\u064e\u0645\u064e\u0646\u06e1 \u0647\u064f\u0648\u064e \u0623\u064e\u0639\u06e1\u0645\u064e\u0649\u0670\u0653\u06da \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f \u0623\u064f\u0648\u0652\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0623\u064e\u0644\u06e1\u0628\u064e\u0670\u0628\u0650",translation:"Maka apakah orang yang mengetahui bahwa apa yang diturunkan Tuhan kepadamu adalah kebenaran, sama dengan orang yang buta? Hanya orang berakal saja yang dapat mengambil pelajaran"},{id:20,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0648\u0641\u064f\u0648\u0646\u064e \u0628\u0650\u0639\u064e\u0647\u06e1\u062f\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0646\u0642\u064f\u0636\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0645\u0650\u064a\u062b\u064e\u0670\u0642\u064e",translation:"(yaitu) orang yang memenuhi janji Allah dan tidak melanggar perjanjian"},{id:21,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0635\u0650\u0644\u064f\u0648\u0646\u064e \u0645\u064e\u0627\u0653 \u0623\u064e\u0645\u064e\u0631\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0646 \u064a\u064f\u0648\u0635\u064e\u0644\u064e \u0648\u064e\u064a\u064e\u062e\u06e1\u0634\u064e\u0648\u06e1\u0646\u064e \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u064a\u064e\u062e\u064e\u0627\u0641\u064f\u0648\u0646\u064e \u0633\u064f\u0648\u0653\u0621\u064e \u0671\u0644\u06e1\u062d\u0650\u0633\u064e\u0627\u0628\u0650",translation:"(dan orang-orang yang menghubungkan apa yang diperintahkan Allah agar dihubungkan,419) dan mereka takut kepada Tuhannya dan takut kepada hisab yang buruk"},{id:22,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0635\u064e\u0628\u064e\u0631\u064f\u0648\u0627\u0652 \u0671\u0628\u06e1\u062a\u0650\u063a\u064e\u0627\u0653\u0621\u064e \u0648\u064e\u062c\u06e1\u0647\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0623\u064e\u0642\u064e\u0627\u0645\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u0623\u064e\u0646\u0641\u064e\u0642\u064f\u0648\u0627\u0652 \u0645\u0650\u0645\u0651\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0633\u0650\u0631\u0651\u0657\u0627 \u0648\u064e\u0639\u064e\u0644\u064e\u0627\u0646\u0650\u064a\u064e\u0629\u0657 \u0648\u064e\u064a\u064e\u062f\u06e1\u0631\u064e\u0621\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0633\u064e\u0646\u064e\u0629\u0650 \u0671\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u064e \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064f\u0642\u06e1\u0628\u064e\u0649 \u0671\u0644\u062f\u0651\u064e\u0627\u0631\u0650",translation:"Dan orang yang sabar karena mengharap keridaan Tuhannya, melaksanakan salat, dan menginfakkan sebagian rezeki yang Kami berikan kepada mereka, secara sembunyi atau terang-terangan serta menolak kejahatan dengan kebaikan; orang itulah yang mendapat tempat kesudahan (yang baik)"},{id:23,text:"\u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u064f \u0639\u064e\u062f\u06e1\u0646\u0656 \u064a\u064e\u062f\u06e1\u062e\u064f\u0644\u064f\u0648\u0646\u064e\u0647\u064e\u0627 \u0648\u064e\u0645\u064e\u0646 \u0635\u064e\u0644\u064e\u062d\u064e \u0645\u0650\u0646\u06e1 \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0626\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u0640\u0670\u062a\u0650\u0647\u0650\u0645\u06e1\u06d6 \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u064f \u064a\u064e\u062f\u06e1\u062e\u064f\u0644\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0645\u0651\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u0628\u064e\u0627\u0628\u0656",translation:"(yaitu) surga-surga '\u0100dn, mereka masuk ke dalamnya bersama dengan orang yang saleh dari nenek moyangnya, pasangan-pasangannya dan anak cucunya, sedangkan para malaikat masuk ke tempat-tempat mereka dari semua pintu"},{id:24,text:"\u0633\u064e\u0644\u064e\u0670\u0645\u064c \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645 \u0628\u0650\u0645\u064e\u0627 \u0635\u064e\u0628\u064e\u0631\u06e1\u062a\u064f\u0645\u06e1\u06da \u0641\u064e\u0646\u0650\u0639\u06e1\u0645\u064e \u0639\u064f\u0642\u06e1\u0628\u064e\u0649 \u0671\u0644\u062f\u0651\u064e\u0627\u0631\u0650",translation:"(sambil mengucapkan), \"Selamat sejahtera atasmu karena kesabaranmu.\" Maka alangkah nikmatnya tempat kesudahan itu"},{id:25,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0646\u0642\u064f\u0636\u064f\u0648\u0646\u064e \u0639\u064e\u0647\u06e1\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0645\u0650\u064a\u062b\u064e\u0670\u0642\u0650\u0647\u0650\u06e6 \u0648\u064e\u064a\u064e\u0642\u06e1\u0637\u064e\u0639\u064f\u0648\u0646\u064e \u0645\u064e\u0627\u0653 \u0623\u064e\u0645\u064e\u0631\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0646 \u064a\u064f\u0648\u0635\u064e\u0644\u064e \u0648\u064e\u064a\u064f\u0641\u06e1\u0633\u0650\u062f\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0639\u06e1\u0646\u064e\u0629\u064f \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0633\u064f\u0648\u0653\u0621\u064f \u0671\u0644\u062f\u0651\u064e\u0627\u0631\u0650",translation:"Dan orang-orang yang melanggar janji Allah setelah diikrarkannya, dan memutuskan apa yang Allah perintahkan agar disambung dan berbuat kerusakan di bumi; mereka itu memperoleh kutukan dan tempat kediaman yang buruk (Jahanam)"},{id:26,text:"\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0628\u06e1\u0633\u064f\u0637\u064f \u0671\u0644\u0631\u0651\u0650\u0632\u06e1\u0642\u064e \u0644\u0650\u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0648\u064e\u064a\u064e\u0642\u06e1\u062f\u0650\u0631\u064f\u06da \u0648\u064e\u0641\u064e\u0631\u0650\u062d\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u0650 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u064f \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u062a\u064e\u0670\u0639\u065e",translation:"Allah melapangkan rezeki bagi siapa yang Dia kehendaki dan membatasi (bagi siapa yang Dia kehendaki). Mereka bergembira dengan kehidupan dunia, padahal kehidupan dunia hanyalah kesenangan (yang sedikit) dibanding kehidupan akhirat"},{id:27,text:"\u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0644\u064e\u0648\u06e1\u0644\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0621\u064e\u0627\u064a\u064e\u0629\u065e \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0647\u0650\u06e6\u06da \u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u0636\u0650\u0644\u0651\u064f \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0648\u064e\u064a\u064e\u0647\u06e1\u062f\u0650\u064a\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0645\u064e\u0646\u06e1 \u0623\u064e\u0646\u064e\u0627\u0628\u064e",translation:"Dan orang-orang kafir berkata, \"Mengapa tidak diturunkan kepadanya (Muhammad) tanda (mukjizat) dari Tuhannya?\" Katakanlah (Muhammad), \"Sesungguhnya Allah menyesatkan420) siapa yang Dia kehendaki dan memberi petunjuk orang yang bertobat kepada-Nya"},{id:28,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u062a\u064e\u0637\u06e1\u0645\u064e\u0626\u0650\u0646\u0651\u064f \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645 \u0628\u0650\u0630\u0650\u0643\u06e1\u0631\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d7 \u0623\u064e\u0644\u064e\u0627 \u0628\u0650\u0630\u0650\u0643\u06e1\u0631\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064e\u0637\u06e1\u0645\u064e\u0626\u0650\u0646\u0651\u064f \u0671\u0644\u06e1\u0642\u064f\u0644\u064f\u0648\u0628\u064f",translation:"(yaitu) orang-orang yang beriman dan hati mereka menjadi tenteram dengan mengingat Allah. Ingatlah, hanya dengan mengingat Allah hati menjadi tenteram"},{id:29,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0637\u064f\u0648\u0628\u064e\u0649\u0670 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u062d\u064f\u0633\u06e1\u0646\u064f \u0645\u064e\u0640\u0654\u064e\u0627\u0628\u0656",translation:"Orang-orang yang beriman dan mengerjakan kebajikan, mereka mendapat kebahagiaan dan tempat kembali yang baik"},{id:30,text:"\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0670\u0643\u064e \u0641\u0650\u064a\u0653 \u0623\u064f\u0645\u0651\u064e\u0629\u0656 \u0642\u064e\u062f\u06e1 \u062e\u064e\u0644\u064e\u062a\u06e1 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u064e\u0627\u0653 \u0623\u064f\u0645\u064e\u0645\u065e \u0644\u0651\u0650\u062a\u064e\u062a\u06e1\u0644\u064f\u0648\u064e\u0627\u0652 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064e\u0648\u06e1\u062d\u064e\u064a\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0648\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0643\u06e1\u0641\u064f\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u0650\u06da \u0642\u064f\u0644\u06e1 \u0647\u064f\u0648\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0644\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u06e1\u062a\u064f \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0645\u064e\u062a\u064e\u0627\u0628\u0650",translation:"Demikianlah, Kami telah mengutus engkau (Muhammad) kepada suatu umat yang sungguh sebelumnya telah berlalu beberapa umat, agar engkau bacakan kepada mereka (Alquran) yang Kami wahyukan kepadamu, padahal mereka ingkar kepada Tuhan Yang Maha Pengasih. Katakanlah, \"Dia Tuhanku, tidak ada tuhan selain Dia; hanya kepada-Nya aku bertawakal dan hanya kepada-Nya aku bertobat"},{id:31,text:"\u0648\u064e\u0644\u064e\u0648\u06e1 \u0623\u064e\u0646\u0651\u064e \u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u0657\u0627 \u0633\u064f\u064a\u0651\u0650\u0631\u064e\u062a\u06e1 \u0628\u0650\u0647\u0650 \u0671\u0644\u06e1\u062c\u0650\u0628\u064e\u0627\u0644\u064f \u0623\u064e\u0648\u06e1 \u0642\u064f\u0637\u0651\u0650\u0639\u064e\u062a\u06e1 \u0628\u0650\u0647\u0650 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064f \u0623\u064e\u0648\u06e1 \u0643\u064f\u0644\u0651\u0650\u0645\u064e \u0628\u0650\u0647\u0650 \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u064e\u0649\u0670\u06d7 \u0628\u064e\u0644 \u0644\u0651\u0650\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0631\u064f \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627\u06d7 \u0623\u064e\u0641\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0627\u0652\u064a\u06e1\u0640\u0654\u064e\u0633\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646 \u0644\u0651\u064e\u0648\u06e1 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0647\u064e\u062f\u064e\u0649 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u062c\u064e\u0645\u0650\u064a\u0639\u0657\u0627\u06d7 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0632\u064e\u0627\u0644\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u062a\u064f\u0635\u0650\u064a\u0628\u064f\u0647\u064f\u0645 \u0628\u0650\u0645\u064e\u0627 \u0635\u064e\u0646\u064e\u0639\u064f\u0648\u0627\u0652 \u0642\u064e\u0627\u0631\u0650\u0639\u064e\u0629\u064c \u0623\u064e\u0648\u06e1 \u062a\u064e\u062d\u064f\u0644\u0651\u064f \u0642\u064e\u0631\u0650\u064a\u0628\u0657\u0627 \u0645\u0651\u0650\u0646 \u062f\u064e\u0627\u0631\u0650\u0647\u0650\u0645\u06e1 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e \u0648\u064e\u0639\u06e1\u062f\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064f\u062e\u06e1\u0644\u0650\u0641\u064f \u0671\u0644\u06e1\u0645\u0650\u064a\u0639\u064e\u0627\u062f\u064e",translation:"Dan sekiranya ada suatu bacaan (Kitab Suci) yang dengan itu gunung-gunung dapat digoncangkan, atau bumi jadi terbelah, atau orang yang sudah mati dapat berbicara, (itulah Alquran). Sebenarnya segala urusan itu milik Allah. Maka tidakkah orang-orang yang beriman mengetahui bahwa sekiranya Allah menghendaki (semua manusia beriman), tentu Allah memberi petunjuk kepada manusia semuanya. Dan orang-orang kafir senantiasa ditimpa bencana disebabkan perbuatan mereka sendiri atau bencana itu terjadi dekat tempat kediaman mereka, sampai datang janji Allah (penaklukan Mekkah). Sungguh, Allah tidak menyalahi janji"},{id:32,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0650 \u0671\u0633\u06e1\u062a\u064f\u0647\u06e1\u0632\u0650\u0626\u064e \u0628\u0650\u0631\u064f\u0633\u064f\u0644\u0656 \u0645\u0651\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064e \u0641\u064e\u0623\u064e\u0645\u06e1\u0644\u064e\u064a\u06e1\u062a\u064f \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u062b\u064f\u0645\u0651\u064e \u0623\u064e\u062e\u064e\u0630\u06e1\u062a\u064f\u0647\u064f\u0645\u06e1\u06d6 \u0641\u064e\u0643\u064e\u064a\u06e1\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u0650\u0642\u064e\u0627\u0628\u0650",translation:"Dan sesungguhnya beberapa rasul sebelum engkau (Muhammad) telah diperolok-olokan, maka Aku beri tenggang waktu kepada orang-orang kafir itu, kemudian Aku binasakan mereka. Maka alangkah hebatnya siksaan-Ku itu"},{id:33,text:"\u0623\u064e\u0641\u064e\u0645\u064e\u0646\u06e1 \u0647\u064f\u0648\u064e \u0642\u064e\u0627\u0653\u0626\u0650\u0645\u064c \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0646\u064e\u0641\u06e1\u0633\u0650\u06ed \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064e\u062a\u06e1\u06d7 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064f\u0648\u0627\u0652 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0653\u0621\u064e \u0642\u064f\u0644\u06e1 \u0633\u064e\u0645\u0651\u064f\u0648\u0647\u064f\u0645\u06e1\u06da \u0623\u064e\u0645\u06e1 \u062a\u064f\u0646\u064e\u0628\u0651\u0650\u0640\u0654\u064f\u0648\u0646\u064e\u0647\u064f\u06e5 \u0628\u0650\u0645\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0623\u064e\u0645 \u0628\u0650\u0638\u064e\u0670\u0647\u0650\u0631\u0656 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0644\u0650\u06d7 \u0628\u064e\u0644\u06e1 \u0632\u064f\u064a\u0651\u0650\u0646\u064e \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0645\u064e\u0643\u06e1\u0631\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0635\u064f\u062f\u0651\u064f\u0648\u0627\u0652 \u0639\u064e\u0646\u0650 \u0671\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u0650\u06d7 \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0636\u06e1\u0644\u0650\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646\u06e1 \u0647\u064e\u0627\u062f\u0656",translation:"Maka apakah Tuhan yang menjaga setiap jiwa terhadap apa yang diperbuatnya (sama dengan yang lain)? Mereka menjadikan sekutu-sekutu bagi Allah. Katakanlah, \"Sebutkanlah sifat-sifat mereka itu!\" Atau apakah kamu hendak memberitahukan kepada Allah apa yang tidak diketahui-Nya di bumi, atau (mengatakan tentang hal itu) sekedar perkataan pada lahirnya saja. Sebenarnya bagi orang kafir, tipu daya mereka itu dijadikan terasa indah, dan mereka dihalangi dari jalan (yang benar). Dan barang siapa disesatkan Allah, maka tidak ada seorang pun yang memberi petunjuk baginya"},{id:34,text:"\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u065e \u0641\u0650\u064a \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u0650 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627\u06d6 \u0648\u064e\u0644\u064e\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0623\u064e\u0634\u064e\u0642\u0651\u064f\u06d6 \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646 \u0648\u064e\u0627\u0642\u0656",translation:"Mereka mendapat siksaan dalam kehidupan dunia, dan azab akhirat pasti lebih keras. Tidak ada seorang pun yang melindungi mereka dari (azab) Allah"},{id:35,text:"\u06de\u0645\u0651\u064e\u062b\u064e\u0644\u064f \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u0671\u0644\u0651\u064e\u062a\u0650\u064a \u0648\u064f\u0639\u0650\u062f\u064e \u0671\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e\u06d6 \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0645\u0650\u0646 \u062a\u064e\u062d\u06e1\u062a\u0650\u0647\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u064f\u06d6 \u0623\u064f\u0643\u064f\u0644\u064f\u0647\u064e\u0627 \u062f\u064e\u0627\u0653\u0626\u0650\u0645\u065e \u0648\u064e\u0638\u0650\u0644\u0651\u064f\u0647\u064e\u0627\u06da \u062a\u0650\u0644\u06e1\u0643\u064e \u0639\u064f\u0642\u06e1\u0628\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u062a\u0651\u064e\u0642\u064e\u0648\u0627\u0652\u06da \u0648\u0651\u064e\u0639\u064f\u0642\u06e1\u0628\u064e\u0649 \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u064f",translation:"Perumpamaan surga yang dijanjikan kepada orang yang bertakwa (ialah seperti taman), mengalir di bawahnya sungai-sungai; senantiasa berbuah dan teduh. Itulah tempat kesudahan bagi orang yang bertakwa; sedangkan tempat kesudahan bagi orang yang ingkar kepada Tuhan ialah neraka"},{id:36,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u064a\u064e\u0641\u06e1\u0631\u064e\u062d\u064f\u0648\u0646\u064e \u0628\u0650\u0645\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e\u06d6 \u0648\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u062d\u06e1\u0632\u064e\u0627\u0628\u0650 \u0645\u064e\u0646 \u064a\u064f\u0646\u0643\u0650\u0631\u064f \u0628\u064e\u0639\u06e1\u0636\u064e\u0647\u064f\u06e5\u06da \u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0645\u0650\u0631\u06e1\u062a\u064f \u0623\u064e\u0646\u06e1 \u0623\u064e\u0639\u06e1\u0628\u064f\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064f\u0634\u06e1\u0631\u0650\u0643\u064e \u0628\u0650\u0647\u0650\u06e6\u0653\u06da \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0623\u064e\u062f\u06e1\u0639\u064f\u0648\u0627\u0652 \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0645\u064e\u0640\u0654\u064e\u0627\u0628\u0650",translation:"(Dan orang yang telah Kami berikan kitab kepada mereka421) bergembira dengan apa (Kitab) yang diturunkan kepadamu (Muhammad), dan ada di antara golongan (Yahudi dan Nasrani), yang mengingkari sebagiannya. Katakanlah, \"Aku hanya diperintah untuk menyembah Allah dan tidak mempersekutukan-Nya. Hanya kepada-Nya aku seru (manusia) dan hanya kepada-Nya aku kembali"},{id:37,text:"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f \u062d\u064f\u0643\u06e1\u0645\u064b\u0627 \u0639\u064e\u0631\u064e\u0628\u0650\u064a\u0651\u0657\u0627\u06da \u0648\u064e\u0644\u064e\u0626\u0650\u0646\u0650 \u0671\u062a\u0651\u064e\u0628\u064e\u0639\u06e1\u062a\u064e \u0623\u064e\u0647\u06e1\u0648\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645 \u0628\u064e\u0639\u06e1\u062f\u064e \u0645\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0639\u0650\u0644\u06e1\u0645\u0650 \u0645\u064e\u0627 \u0644\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646 \u0648\u064e\u0644\u0650\u064a\u0651\u0656 \u0648\u064e\u0644\u064e\u0627 \u0648\u064e\u0627\u0642\u0656",translation:"Dan demikianlah Kami telah menurunkannya (Alquran) sebagai peraturan (yang benar) dalam bahasa Arab. Sekiranya engkau mengikuti keinginan mereka setelah datang pengetahuan kepadamu, maka tidak ada yang melindungi dan yang menolong engkau dari (siksaan) Allah"},{id:38,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0631\u064f\u0633\u064f\u0644\u0657\u0627 \u0645\u0651\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064e \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u0657\u0627 \u0648\u064e\u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u0629\u0657\u06da \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0631\u064e\u0633\u064f\u0648\u0644\u064d \u0623\u064e\u0646 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0629\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0625\u0650\u0630\u06e1\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d7 \u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0623\u064e\u062c\u064e\u0644\u0656 \u0643\u0650\u062a\u064e\u0627\u0628\u065e",translation:"Dan sungguh, Kami telah mengutus beberapa rasul sebelum engkau (Muhammad) dan Kami berikan kepada mereka istri-istri dan keturunan. Tidak ada hak bagi seorang rasul mendatangkan sesuatu bukti (mukjizat) melainkan dengan izin Allah. Untuk setiap masa ada Kitab (tertentu)"},{id:39,text:"\u064a\u064e\u0645\u06e1\u062d\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0648\u064e\u064a\u064f\u062b\u06e1\u0628\u0650\u062a\u064f\u06d6 \u0648\u064e\u0639\u0650\u0646\u062f\u064e\u0647\u064f\u06e5\u0653 \u0623\u064f\u0645\u0651\u064f \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650",translation:"Allah menghapus dan menetapkan apa yang Dia kehendaki. Dan di sisi-Nya terdapat Ummul-Kit\u0101b (Lau\u1e25 Ma\u1e25f\u016b\u1e93)"},{id:40,text:"\u0648\u064e\u0625\u0650\u0646 \u0645\u0651\u064e\u0627 \u0646\u064f\u0631\u0650\u064a\u064e\u0646\u0651\u064e\u0643\u064e \u0628\u064e\u0639\u06e1\u0636\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0646\u064e\u0639\u0650\u062f\u064f\u0647\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1 \u0646\u064e\u062a\u064e\u0648\u064e\u0641\u0651\u064e\u064a\u064e\u0646\u0651\u064e\u0643\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0671\u0644\u06e1\u0628\u064e\u0644\u064e\u0670\u063a\u064f \u0648\u064e\u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u062d\u0650\u0633\u064e\u0627\u0628\u064f",translation:"Dan sungguh jika Kami perlihatkan kepadamu (Muhammad) sebagian (siksaan) yang Kami ancamkan kepada mereka atau Kami wafatkan engkau, maka sesungguhnya tugasmu hanya menyampaikan saja, dan Kamilah yang memperhitungkan (amal mereka)"},{id:41,text:"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0631\u064e\u0648\u06e1\u0627\u0652 \u0623\u064e\u0646\u0651\u064e\u0627 \u0646\u064e\u0623\u06e1\u062a\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0646\u064e\u0646\u0642\u064f\u0635\u064f\u0647\u064e\u0627 \u0645\u0650\u0646\u06e1 \u0623\u064e\u0637\u06e1\u0631\u064e\u0627\u0641\u0650\u0647\u064e\u0627\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u062d\u06e1\u0643\u064f\u0645\u064f \u0644\u064e\u0627 \u0645\u064f\u0639\u064e\u0642\u0651\u0650\u0628\u064e \u0644\u0650\u062d\u064f\u0643\u06e1\u0645\u0650\u0647\u0650\u06e6\u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0633\u064e\u0631\u0650\u064a\u0639\u064f \u0671\u0644\u06e1\u062d\u0650\u0633\u064e\u0627\u0628\u0650",translation:"Dan apakah mereka tidak melihat bahwa Kami mendatangi daerah-daerah (orang yang ingkar kepada Allah), lalu Kami kurangi (daerah-daerah) itu (sedikit demi sedikit) dari tepi-tepinya? Dan Allah menetapkan hukum (menurut kehendak-Nya), tidak ada yang dapat menolak ketetapan-Nya; Dia Mahacepat perhitungan-Nya"},{id:42,text:"\u0648\u064e\u0642\u064e\u062f\u06e1 \u0645\u064e\u0643\u064e\u0631\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u0645\u06e1 \u0641\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u0645\u064e\u0643\u06e1\u0631\u064f \u062c\u064e\u0645\u0650\u064a\u0639\u0657\u0627\u06d6 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u062a\u064e\u0643\u06e1\u0633\u0650\u0628\u064f \u0643\u064f\u0644\u0651\u064f \u0646\u064e\u0641\u06e1\u0633\u0656\u06d7 \u0648\u064e\u0633\u064e\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0671\u0644\u06e1\u0643\u064f\u0641\u0651\u064e\u0640\u0670\u0631\u064f \u0644\u0650\u0645\u064e\u0646\u06e1 \u0639\u064f\u0642\u06e1\u0628\u064e\u0649 \u0671\u0644\u062f\u0651\u064e\u0627\u0631\u0650",translation:"Dan sungguh orang sebelum mereka (kafir Mekkah) telah mengadakan tipu daya, tetapi semua tipu daya itu dalam kekuasaan Allah. Dia mengetahui apa yang diusahakan oleh setiap orang, dan orang yang ingkar kepada Tuhan akan mengetahui untuk siapa tempat kesudahan (yang baik)"},{id:43,text:"\u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0644\u064e\u0633\u06e1\u062a\u064e \u0645\u064f\u0631\u06e1\u0633\u064e\u0644\u0657\u0627\u06da \u0642\u064f\u0644\u06e1 \u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0634\u064e\u0647\u0650\u064a\u062f\u064e\u06e2\u0627 \u0628\u064e\u064a\u06e1\u0646\u0650\u064a \u0648\u064e\u0628\u064e\u064a\u06e1\u0646\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0645\u064e\u0646\u06e1 \u0639\u0650\u0646\u062f\u064e\u0647\u064f\u06e5 \u0639\u0650\u0644\u06e1\u0645\u064f \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650",translation:"Dan orang-orang kafir berkata, \"Engkau (Muhammad) bukanlah seorang Rasul.\" Katakanlah, \"Cukuplah Allah dan orang yang menguasai ilmu Al-Kitab423) menjadi saksi antara aku dan kamu"}]},{id:14,name:"\u0627\u0628\u0631\u0627\u0647\u064a\u0645",transliteration:"Ibrahim",translation:"Ibrahim",type:"meccan",total_verses:52,verses:[{id:1,text:"\u0627\u0644\u0653\u0631\u06da \u0643\u0650\u062a\u064e\u0670\u0628\u064c \u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0644\u0650\u062a\u064f\u062e\u06e1\u0631\u0650\u062c\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0638\u0651\u064f\u0644\u064f\u0645\u064e\u0670\u062a\u0650 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0646\u0651\u064f\u0648\u0631\u0650 \u0628\u0650\u0625\u0650\u0630\u06e1\u0646\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0670\u0637\u0650 \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u0650 \u0671\u0644\u06e1\u062d\u064e\u0645\u0650\u064a\u062f\u0650",translation:"Alif L\u0101m R\u0101`. (Ini adalah) Kitab yang Kami turunkan kepadamu (Muhammad) agar engkau mengeluarkan manusia dari kegelapan kepada cahaya terang-benderang dengan izin Tuhan, (yaitu) menuju jalan Tuhan Yang Mahaperkasa, Maha Terpuji"},{id:2,text:"\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0644\u064e\u0647\u064f\u06e5 \u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d7 \u0648\u064e\u0648\u064e\u064a\u06e1\u0644\u065e \u0644\u0651\u0650\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u0656 \u0634\u064e\u062f\u0650\u064a\u062f\u064d",translation:"Allah yang memiliki apa yang ada di langit dan apa yang ada di bumi. Celakalah bagi orang yang ingkar kepada Tuhan karena siksaan yang sangat berat"},{id:3,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0633\u06e1\u062a\u064e\u062d\u0650\u0628\u0651\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u064e \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0648\u064e\u064a\u064e\u0635\u064f\u062f\u0651\u064f\u0648\u0646\u064e \u0639\u064e\u0646 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u064a\u064e\u0628\u06e1\u063a\u064f\u0648\u0646\u064e\u0647\u064e\u0627 \u0639\u0650\u0648\u064e\u062c\u064b\u0627\u06da \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0670\u0644\u0650\u06ed \u0628\u064e\u0639\u0650\u064a\u062f\u0656",translation:"(yaitu) orang yang lebih menyukai kehidupan dunia daripada (kehidupan) akhirat, dan menghalang-halangi (manusia) dari jalan Allah dan menginginkan (jalan yang) bengkok. Mereka itu berada dalam kesesatan yang jauh"},{id:4,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646 \u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0644\u0650\u0633\u064e\u0627\u0646\u0650 \u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u06e6 \u0644\u0650\u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u06e1\u06d6 \u0641\u064e\u064a\u064f\u0636\u0650\u0644\u0651\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0648\u064e\u064a\u064e\u0647\u06e1\u062f\u0650\u064a \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0671\u0644\u06e1\u062d\u064e\u0643\u0650\u064a\u0645\u064f",translation:"(Dan Kami tidak mengutus seorang rasul pun, melainkan dengan bahasa kaumnya,424) agar dia dapat memberi penjelasan kepada mereka. Maka Allah menyesatkan siapa yang Dia kehendaki, dan memberi petunjuk kepada siapa yang Dia kehendaki. Dia Yang Mahaperkasa, Mahabijaksana"},{id:5,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627\u0653 \u0623\u064e\u0646\u06e1 \u0623\u064e\u062e\u06e1\u0631\u0650\u062c\u06e1 \u0642\u064e\u0648\u06e1\u0645\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0638\u0651\u064f\u0644\u064f\u0645\u064e\u0670\u062a\u0650 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0646\u0651\u064f\u0648\u0631\u0650 \u0648\u064e\u0630\u064e\u0643\u0651\u0650\u0631\u06e1\u0647\u064f\u0645 \u0628\u0650\u0623\u064e\u064a\u0651\u064e\u0649\u0670\u0645\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0623\u0653\u064a\u064e\u0670\u062a\u0656 \u0644\u0651\u0650\u0643\u064f\u0644\u0651\u0650 \u0635\u064e\u0628\u0651\u064e\u0627\u0631\u0656 \u0634\u064e\u0643\u064f\u0648\u0631\u0656",translation:"Dan sungguh, Kami telah mengutus Musa dengan membawa tanda-tanda (kekuasaan) Kami, (dan Kami perintahkan kepadanya), \"Keluarkanlah kaummu dari kegelapan kepada cahaya terang-benderang dan ingatkanlah mereka kepada hari-hari Allah.\"425) Sungguh, pada yang demikian itu terdapat tanda-tanda (kekuasaan Allah) bagi setiap orang penyabar dan banyak bersyukur"},{id:6,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0644\u0650\u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650 \u0671\u0630\u06e1\u0643\u064f\u0631\u064f\u0648\u0627\u0652 \u0646\u0650\u0639\u06e1\u0645\u064e\u0629\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0625\u0650\u0630\u06e1 \u0623\u064e\u0646\u062c\u064e\u0649\u0670\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0621\u064e\u0627\u0644\u0650 \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u064a\u064e\u0633\u064f\u0648\u0645\u064f\u0648\u0646\u064e\u0643\u064f\u0645\u06e1 \u0633\u064f\u0648\u0653\u0621\u064e \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0648\u064e\u064a\u064f\u0630\u064e\u0628\u0651\u0650\u062d\u064f\u0648\u0646\u064e \u0623\u064e\u0628\u06e1\u0646\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u064a\u064e\u0633\u06e1\u062a\u064e\u062d\u06e1\u064a\u064f\u0648\u0646\u064e \u0646\u0650\u0633\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645 \u0628\u064e\u0644\u064e\u0627\u0653\u0621\u065e \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1 \u0639\u064e\u0638\u0650\u064a\u0645\u065e",translation:"Dan (ingatlah) ketika Musa berkata kepada kaumnya, \"Ingatlah nikmat Allah atasmu ketika Dia menyelamatkan kamu dari pengikut-pengikut Fir'aun; mereka menyiksa kamu dengan siksa yang pedih, dan menyembelih anak-anakmu yang laki-laki, dan membiarkan hidup anak-anak perempuanmu; pada yang demikian itu terdapat suatu cobaan yang besar dari Tuhanmu"},{id:7,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u062a\u064e\u0623\u064e\u0630\u0651\u064e\u0646\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u06e1 \u0644\u064e\u0626\u0650\u0646 \u0634\u064e\u0643\u064e\u0631\u06e1\u062a\u064f\u0645\u06e1 \u0644\u064e\u0623\u064e\u0632\u0650\u064a\u062f\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0644\u064e\u0626\u0650\u0646 \u0643\u064e\u0641\u064e\u0631\u06e1\u062a\u064f\u0645\u06e1 \u0625\u0650\u0646\u0651\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u0650\u064a \u0644\u064e\u0634\u064e\u062f\u0650\u064a\u062f\u065e",translation:"Dan (ingatlah) ketika Tuhanmu memaklumkan, \"Sesungguhnya jika kamu bersyukur, niscaya Aku akan menambah (nikmat) kepadamu, tetapi jika kamu mengingkari (nikmat-Ku), maka pasti azab-Ku sangat berat"},{id:8,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670\u0653 \u0625\u0650\u0646 \u062a\u064e\u0643\u06e1\u0641\u064f\u0631\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0648\u064e\u0645\u064e\u0646 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u062c\u064e\u0645\u0650\u064a\u0639\u0657\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u063a\u064e\u0646\u0650\u064a\u0651\u064c \u062d\u064e\u0645\u0650\u064a\u062f\u064c",translation:"Dan Musa berkata, \"Jika kamu dan orang yang ada di bumi semuanya mengingkari (nikmat Allah), maka sesungguhnya Allah Mahakaya, Maha Terpuji"},{id:9,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0623\u06e1\u062a\u0650\u0643\u064f\u0645\u06e1 \u0646\u064e\u0628\u064e\u0624\u064f\u0627\u0652 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064f\u0645\u06e1 \u0642\u064e\u0648\u06e1\u0645\u0650 \u0646\u064f\u0648\u062d\u0656 \u0648\u064e\u0639\u064e\u0627\u062f\u0656 \u0648\u064e\u062b\u064e\u0645\u064f\u0648\u062f\u064e \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u0647\u0650\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06da \u062c\u064e\u0627\u0653\u0621\u064e\u062a\u06e1\u0647\u064f\u0645\u06e1 \u0631\u064f\u0633\u064f\u0644\u064f\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0650 \u0641\u064e\u0631\u064e\u062f\u0651\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0653 \u0623\u064e\u0641\u06e1\u0648\u064e\u0670\u0647\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064e\u0641\u064e\u0631\u06e1\u0646\u064e\u0627 \u0628\u0650\u0645\u064e\u0627\u0653 \u0623\u064f\u0631\u06e1\u0633\u0650\u0644\u06e1\u062a\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0641\u0650\u064a \u0634\u064e\u0643\u0651\u0656 \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0645\u064f\u0631\u0650\u064a\u0628\u0656",translation:"Apakah belum sampai kepadamu berita orang-orang sebelum kamu (yaitu) kaum Nuh, '\u0100d, Samud dan orang-orang setelah mereka. Tidak ada yang mengetahui mereka selain Allah. Rasul-rasul telah datang kepada mereka membawa bukti-bukti (yang nyata), namun mereka menutupkan tangannya ke mulutnya (karena kebencian), dan berkata, \"Sesungguhnya kami tidak percaya akan (bukti bahwa) kamu diutus (kepada kami), dan kami benar-benar dalam keraguan yang menggelisahkan terhadap apa yang kamu serukan kepada kami"},{id:10,text:"\u06de\u0642\u064e\u0627\u0644\u064e\u062a\u06e1 \u0631\u064f\u0633\u064f\u0644\u064f\u0647\u064f\u0645\u06e1 \u0623\u064e\u0641\u0650\u064a \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0634\u064e\u0643\u0651\u065e \u0641\u064e\u0627\u0637\u0650\u0631\u0650 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d6 \u064a\u064e\u062f\u06e1\u0639\u064f\u0648\u0643\u064f\u0645\u06e1 \u0644\u0650\u064a\u064e\u063a\u06e1\u0641\u0650\u0631\u064e \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0630\u064f\u0646\u064f\u0648\u0628\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u064a\u064f\u0624\u064e\u062e\u0651\u0650\u0631\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u062c\u064e\u0644\u0656 \u0645\u0651\u064f\u0633\u064e\u0645\u0651\u0657\u0649\u06da \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u06e1 \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u064e\u0634\u064e\u0631\u065e \u0645\u0651\u0650\u062b\u06e1\u0644\u064f\u0646\u064e\u0627 \u062a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0623\u064e\u0646 \u062a\u064e\u0635\u064f\u062f\u0651\u064f\u0648\u0646\u064e\u0627 \u0639\u064e\u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u064a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0624\u064f\u0646\u064e\u0627 \u0641\u064e\u0623\u06e1\u062a\u064f\u0648\u0646\u064e\u0627 \u0628\u0650\u0633\u064f\u0644\u06e1\u0637\u064e\u0670\u0646\u0656 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u0656",translation:"Rasul-rasul mereka berkata, \"Apakah ada keraguan terhadap Allah, Pencipta langit dan bumi? Dia menyeru kamu (untuk beriman) agar Dia mengampuni sebagian dosa-dosamu dan menangguhkan (siksaan)mu sampai waktu yang ditentukan?\" Mereka berkata, \"Kamu hanyalah manusia seperti kami juga. Kamu ingin menghalangi kami (menyembah) apa yang dari dahulu disembah nenek moyang kami, karena itu datangkanlah kepada kami bukti yang nyata"},{id:11,text:"\u0642\u064e\u0627\u0644\u064e\u062a\u06e1 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0631\u064f\u0633\u064f\u0644\u064f\u0647\u064f\u0645\u06e1 \u0625\u0650\u0646 \u0646\u0651\u064e\u062d\u06e1\u0646\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u064e\u0634\u064e\u0631\u065e \u0645\u0651\u0650\u062b\u06e1\u0644\u064f\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0645\u064f\u0646\u0651\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0645\u0650\u0646\u06e1 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0646\u064e\u0627\u0653 \u0623\u064e\u0646 \u0646\u0651\u064e\u0623\u06e1\u062a\u0650\u064a\u064e\u0643\u064f\u0645 \u0628\u0650\u0633\u064f\u0644\u06e1\u0637\u064e\u0670\u0646\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0625\u0650\u0630\u06e1\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0644\u06e1\u064a\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u0650 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Rasul-rasul mereka berkata kepada mereka, \"Kami hanyalah manusia seperti kamu, tetapi Allah memberi karunia kepada siapa yang Dia kehendaki di antara hamba-hamba-Nya. Tidak pantas bagi kami mendatangkan suatu bukti kepada kamu melainkan dengan izin Allah. Dan hanya kepada Allah saja hendaknya orang yang beriman itu bertawakal"},{id:12,text:"\u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0646\u064e\u0627\u0653 \u0623\u064e\u0644\u0651\u064e\u0627 \u0646\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0642\u064e\u062f\u06e1 \u0647\u064e\u062f\u064e\u0649\u0670\u0646\u064e\u0627 \u0633\u064f\u0628\u064f\u0644\u064e\u0646\u064e\u0627\u06da \u0648\u064e\u0644\u064e\u0646\u064e\u0635\u06e1\u0628\u0650\u0631\u064e\u0646\u0651\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627\u0653 \u0621\u064e\u0627\u0630\u064e\u064a\u06e1\u062a\u064f\u0645\u064f\u0648\u0646\u064e\u0627\u06da \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0644\u06e1\u064a\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u0650 \u0671\u0644\u06e1\u0645\u064f\u062a\u064e\u0648\u064e\u0643\u0651\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Dan mengapa kami tidak akan bertawakal kepada Allah, sedangkan Dia telah menunjukkan jalan kepada kami, dan kami sungguh, akan tetap bersabar terhadap gangguan yang kamu lakukan kepada kami. Dan hanya kepada Allah saja orang yang bertawakal itu berserah diri"},{id:13,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0644\u0650\u0631\u064f\u0633\u064f\u0644\u0650\u0647\u0650\u0645\u06e1 \u0644\u064e\u0646\u064f\u062e\u06e1\u0631\u0650\u062c\u064e\u0646\u0651\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u0631\u06e1\u0636\u0650\u0646\u064e\u0627\u0653 \u0623\u064e\u0648\u06e1 \u0644\u064e\u062a\u064e\u0639\u064f\u0648\u062f\u064f\u0646\u0651\u064e \u0641\u0650\u064a \u0645\u0650\u0644\u0651\u064e\u062a\u0650\u0646\u064e\u0627\u06d6 \u0641\u064e\u0623\u064e\u0648\u06e1\u062d\u064e\u0649\u0670\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0631\u064e\u0628\u0651\u064f\u0647\u064f\u0645\u06e1 \u0644\u064e\u0646\u064f\u0647\u06e1\u0644\u0650\u0643\u064e\u0646\u0651\u064e \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dan orang-orang kafir berkata kepada rasul-rasul mereka, \"Kami pasti akan mengusir kamu dari negeri kami atau kamu benar-benar kembali kepada agama kami.\" Maka Tuhan mewahyukan kepada mereka, \"Kami pasti akan membinasakan orang yang zalim itu"},{id:14,text:"\u0648\u064e\u0644\u064e\u0646\u064f\u0633\u06e1\u0643\u0650\u0646\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u0647\u0650\u0645\u06e1\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u0650\u0645\u064e\u0646\u06e1 \u062e\u064e\u0627\u0641\u064e \u0645\u064e\u0642\u064e\u0627\u0645\u0650\u064a \u0648\u064e\u062e\u064e\u0627\u0641\u064e \u0648\u064e\u0639\u0650\u064a\u062f\u0650",translation:"Dan Kami pasti akan menempatkan kamu di negeri-negeri itu setelah mereka. Yang demikian itu (adalah untuk) orang-orang yang takut (menghadap) ke hadirat-Ku dan takut akan ancaman-Ku"},{id:15,text:"\u0648\u064e\u0671\u0633\u06e1\u062a\u064e\u0641\u06e1\u062a\u064e\u062d\u064f\u0648\u0627\u0652 \u0648\u064e\u062e\u064e\u0627\u0628\u064e \u0643\u064f\u0644\u0651\u064f \u062c\u064e\u0628\u0651\u064e\u0627\u0631\u064d \u0639\u064e\u0646\u0650\u064a\u062f\u0656",translation:"Dan mereka memohon diberi kemenangan dan binasalah semua orang yang berlaku sewenang-wenang lagi keras kepala"},{id:16,text:"\u0645\u0651\u0650\u0646 \u0648\u064e\u0631\u064e\u0627\u0653\u0626\u0650\u0647\u0650\u06e6 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064f \u0648\u064e\u064a\u064f\u0633\u06e1\u0642\u064e\u0649\u0670 \u0645\u0650\u0646 \u0645\u0651\u064e\u0627\u0653\u0621\u0656 \u0635\u064e\u062f\u0650\u064a\u062f\u0656",translation:"dihadapannya ada neraka Jahanam dan dia akan diberi minuman dengan air nanah"},{id:17,text:"\u064a\u064e\u062a\u064e\u062c\u064e\u0631\u0651\u064e\u0639\u064f\u0647\u064f\u06e5 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0643\u064e\u0627\u062f\u064f \u064a\u064f\u0633\u0650\u064a\u063a\u064f\u0647\u064f\u06e5 \u0648\u064e\u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u0647\u0650 \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u064f \u0645\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u0645\u064e\u0643\u064e\u0627\u0646\u0656 \u0648\u064e\u0645\u064e\u0627 \u0647\u064f\u0648\u064e \u0628\u0650\u0645\u064e\u064a\u0651\u0650\u062a\u0656\u06d6 \u0648\u064e\u0645\u0650\u0646 \u0648\u064e\u0631\u064e\u0627\u0653\u0626\u0650\u0647\u0650\u06e6 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u063a\u064e\u0644\u0650\u064a\u0638\u065e",translation:"direguknya (air nanah itu) dan dia hampir tidak bisa menelannya dan datanglah (bahaya) maut kepadanya dari segenap penjuru, tetapi dia tidak juga mati; dan dihadapannya (masih ada) azab yang berat"},{id:18,text:"\u0645\u0651\u064e\u062b\u064e\u0644\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1\u06d6 \u0623\u064e\u0639\u06e1\u0645\u064e\u0670\u0644\u064f\u0647\u064f\u0645\u06e1 \u0643\u064e\u0631\u064e\u0645\u064e\u0627\u062f\u064d \u0671\u0634\u06e1\u062a\u064e\u062f\u0651\u064e\u062a\u06e1 \u0628\u0650\u0647\u0650 \u0671\u0644\u0631\u0651\u0650\u064a\u062d\u064f \u0641\u0650\u064a \u064a\u064e\u0648\u06e1\u0645\u064d \u0639\u064e\u0627\u0635\u0650\u0641\u0656\u06d6 \u0644\u0651\u064e\u0627 \u064a\u064e\u0642\u06e1\u062f\u0650\u0631\u064f\u0648\u0646\u064e \u0645\u0650\u0645\u0651\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0634\u064e\u064a\u06e1\u0621\u0656\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0647\u064f\u0648\u064e \u0671\u0644\u0636\u0651\u064e\u0644\u064e\u0670\u0644\u064f \u0671\u0644\u06e1\u0628\u064e\u0639\u0650\u064a\u062f\u064f",translation:"Perumpamaan orang yang ingkar kepada Tuhannya, perbuatan mereka seperti abu yang ditiup oleh angin keras pada suatu hari yang berangin kencang. Mereka tidak kuasa (mendatangkan manfaat) sama sekali dari apa yang telah mereka usahakan (di dunia). Yang demikian itu adalah kesesatan yang jauh"},{id:19,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0631\u064e \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650\u06da \u0625\u0650\u0646 \u064a\u064e\u0634\u064e\u0623\u06e1 \u064a\u064f\u0630\u06e1\u0647\u0650\u0628\u06e1\u0643\u064f\u0645\u06e1 \u0648\u064e\u064a\u064e\u0623\u06e1\u062a\u0650 \u0628\u0650\u062e\u064e\u0644\u06e1\u0642\u0656 \u062c\u064e\u062f\u0650\u064a\u062f\u0656",translation:"Tidakkah kamu memperhatikan, bahwa sesungguhnya Allah telah menciptakan langit dan bumi dengan hak (benar)? Jika Dia menghendaki, niscaya Dia membinasakan kamu dan mendatangkan makhluk yang baru (untuk menggantikan kamu)"},{id:20,text:"\u0648\u064e\u0645\u064e\u0627 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u0650\u0639\u064e\u0632\u0650\u064a\u0632\u0656",translation:"dan yang demikian itu tidak sukar bagi Allah"},{id:21,text:"\u0648\u064e\u0628\u064e\u0631\u064e\u0632\u064f\u0648\u0627\u0652 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u062c\u064e\u0645\u0650\u064a\u0639\u0657\u0627 \u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0636\u0651\u064f\u0639\u064e\u0641\u064e\u0640\u0670\u0653\u0624\u064f\u0627\u0652 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u064e\u0631\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u0628\u064e\u0639\u0657\u0627 \u0641\u064e\u0647\u064e\u0644\u06e1 \u0623\u064e\u0646\u062a\u064f\u0645 \u0645\u0651\u064f\u063a\u06e1\u0646\u064f\u0648\u0646\u064e \u0639\u064e\u0646\u0651\u064e\u0627 \u0645\u0650\u0646\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646 \u0634\u064e\u064a\u06e1\u0621\u0656\u06da \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0648\u06e1 \u0647\u064e\u062f\u064e\u0649\u0670\u0646\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0647\u064e\u062f\u064e\u064a\u06e1\u0646\u064e\u0670\u0643\u064f\u0645\u06e1\u06d6 \u0633\u064e\u0648\u064e\u0627\u0653\u0621\u064c \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627\u0653 \u0623\u064e\u062c\u064e\u0632\u0650\u0639\u06e1\u0646\u064e\u0627\u0653 \u0623\u064e\u0645\u06e1 \u0635\u064e\u0628\u064e\u0631\u06e1\u0646\u064e\u0627 \u0645\u064e\u0627 \u0644\u064e\u0646\u064e\u0627 \u0645\u0650\u0646 \u0645\u0651\u064e\u062d\u0650\u064a\u0635\u0656",translation:"Dan mereka semua (di padang Mahsyar) berkumpul untuk menghadap ke hadirat Allah, lalu orang yang lemah berkata kepada orang yang sombong, \"Sesungguhnya kami dahulu adalah pengikut-pengikutmu, maka dapatkah kamu menghindarkan kami dari azab Allah (walaupun) sedikit saja?\" Mereka menjawab, \"Sekiranya Allah memberi petunjuk kepada kami, niscaya kami dapat memberi petunjuk kepadamu. Sama saja bagi kita, apakah kita mengeluh atau bersabar. Kita tidak mempunyai tempat untuk melarikan diri"},{id:22,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u064f \u0644\u064e\u0645\u0651\u064e\u0627 \u0642\u064f\u0636\u0650\u064a\u064e \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0631\u064f \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0639\u064e\u062f\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0639\u06e1\u062f\u064e \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0648\u064e\u0639\u064e\u062f\u062a\u0651\u064f\u0643\u064f\u0645\u06e1 \u0641\u064e\u0623\u064e\u062e\u06e1\u0644\u064e\u0641\u06e1\u062a\u064f\u0643\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u064a\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0633\u064f\u0644\u06e1\u0637\u064e\u0670\u0646\u064d \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u062f\u064e\u0639\u064e\u0648\u06e1\u062a\u064f\u0643\u064f\u0645\u06e1 \u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u062c\u064e\u0628\u06e1\u062a\u064f\u0645\u06e1 \u0644\u0650\u064a\u06d6 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0644\u064f\u0648\u0645\u064f\u0648\u0646\u0650\u064a \u0648\u064e\u0644\u064f\u0648\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0643\u064f\u0645\u06d6 \u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u0646\u064e\u0627\u06e0 \u0628\u0650\u0645\u064f\u0635\u06e1\u0631\u0650\u062e\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064f\u0645 \u0628\u0650\u0645\u064f\u0635\u06e1\u0631\u0650\u062e\u0650\u064a\u0651\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0643\u064e\u0641\u064e\u0631\u06e1\u062a\u064f \u0628\u0650\u0645\u064e\u0627\u0653 \u0623\u064e\u0634\u06e1\u0631\u064e\u0643\u06e1\u062a\u064f\u0645\u064f\u0648\u0646\u0650 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f\u06d7 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Dan setan berkata ketika perkara (hisab) telah diselesaikan, \"Sesungguhnya Allah telah menjanjikan kepadamu janji yang benar, dan aku pun telah menjanjikan kepadamu tetapi aku menyalahinya. Tidak ada kekuasaan bagiku terhadapmu, melainkan (sekedar) aku menyeru kamu lalu kamu mematuhi seruanku, oleh sebab itu janganlah kamu mencerca aku, tetapi cercalah dirimu sendiri. Aku tidak dapat menolongmu, dan kamu pun tidak dapat menolongku. Sesungguhnya aku tidak membenarkan perbuatanmu mempersekutukan aku (dengan Allah) sejak dahulu.\" Sungguh, orang yang zalim akan mendapat siksaan yang pedih"},{id:23,text:"\u0648\u064e\u0623\u064f\u062f\u06e1\u062e\u0650\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0656 \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0645\u0650\u0646 \u062a\u064e\u062d\u06e1\u062a\u0650\u0647\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u064f \u062e\u064e\u0670\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0628\u0650\u0625\u0650\u0630\u06e1\u0646\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1\u06d6 \u062a\u064e\u062d\u0650\u064a\u0651\u064e\u062a\u064f\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u0633\u064e\u0644\u064e\u0670\u0645\u064c",translation:"Dan orang yang beriman dan mengerjakan kebajikan dimasukkan ke dalam surga-surga yang mengalir di bawahnya sungai-sungai. Mereka kekal di dalamnya dengan seizin Tuhan mereka. Ucapan penghormatan mereka dalam (surga) itu ialah sal\u0101m"},{id:24,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0631\u064e \u0643\u064e\u064a\u06e1\u0641\u064e \u0636\u064e\u0631\u064e\u0628\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u062b\u064e\u0644\u0657\u0627 \u0643\u064e\u0644\u0650\u0645\u064e\u0629\u0657 \u0637\u064e\u064a\u0651\u0650\u0628\u064e\u0629\u0657 \u0643\u064e\u0634\u064e\u062c\u064e\u0631\u064e\u0629\u0656 \u0637\u064e\u064a\u0651\u0650\u0628\u064e\u0629\u064d \u0623\u064e\u0635\u06e1\u0644\u064f\u0647\u064e\u0627 \u062b\u064e\u0627\u0628\u0650\u062a\u065e \u0648\u064e\u0641\u064e\u0631\u06e1\u0639\u064f\u0647\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650",translation:"(Tidakkah kamu memperhatikan bagaimana Allah telah membuat perumpamaan kalimat yang baik427) seperti pohon yang baik, akarnya kuat dan cabangnya (menjulang) ke langit"},{id:25,text:"\u062a\u064f\u0624\u06e1\u062a\u0650\u064a\u0653 \u0623\u064f\u0643\u064f\u0644\u064e\u0647\u064e\u0627 \u0643\u064f\u0644\u0651\u064e \u062d\u0650\u064a\u0646\u0650\u06ed \u0628\u0650\u0625\u0650\u0630\u06e1\u0646\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u064e\u0627\u06d7 \u0648\u064e\u064a\u064e\u0636\u06e1\u0631\u0650\u0628\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u062b\u064e\u0627\u0644\u064e \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"(pohon) itu menghasilkan buahnya pada setiap waktu dengan seizin Tuhannya. Dan Allah membuat perumpamaan itu untuk manusia agar mereka selalu ingat"},{id:26,text:"\u0648\u064e\u0645\u064e\u062b\u064e\u0644\u064f \u0643\u064e\u0644\u0650\u0645\u064e\u0629\u064d \u062e\u064e\u0628\u0650\u064a\u062b\u064e\u0629\u0656 \u0643\u064e\u0634\u064e\u062c\u064e\u0631\u064e\u0629\u064d \u062e\u064e\u0628\u0650\u064a\u062b\u064e\u0629\u064d \u0671\u062c\u06e1\u062a\u064f\u062b\u0651\u064e\u062a\u06e1 \u0645\u0650\u0646 \u0641\u064e\u0648\u06e1\u0642\u0650 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0645\u064e\u0627 \u0644\u064e\u0647\u064e\u0627 \u0645\u0650\u0646 \u0642\u064e\u0631\u064e\u0627\u0631\u0656",translation:"(Dan perumpamaan kalimat yang buruk428) seperti pohon yang buruk, yang telah dicabut akar-akarnya dari permukaan bumi; tidak dapat tetap (tegak) sedikit pun"},{id:27,text:"\u064a\u064f\u062b\u064e\u0628\u0651\u0650\u062a\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0644\u0650 \u0671\u0644\u062b\u0651\u064e\u0627\u0628\u0650\u062a\u0650 \u0641\u0650\u064a \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u0650 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0648\u064e\u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650\u06d6 \u0648\u064e\u064a\u064f\u0636\u0650\u0644\u0651\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e\u06da \u0648\u064e\u064a\u064e\u0641\u06e1\u0639\u064e\u0644\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f",translation:"Allah meneguhkan (iman) orang-orang yang beriman dengan ucapan yang teguh429) (dalam kehidupan) di dunia dan di akhirat; dan Allah menyesatkan orang-orang yang zalim dan Allah berbuat apa yang Dia kehendaki"},{id:28,text:"\u06de\u0623\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0631\u064e \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0628\u064e\u062f\u0651\u064e\u0644\u064f\u0648\u0627\u0652 \u0646\u0650\u0639\u06e1\u0645\u064e\u062a\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064f\u0641\u06e1\u0631\u0657\u0627 \u0648\u064e\u0623\u064e\u062d\u064e\u0644\u0651\u064f\u0648\u0627\u0652 \u0642\u064e\u0648\u06e1\u0645\u064e\u0647\u064f\u0645\u06e1 \u062f\u064e\u0627\u0631\u064e \u0671\u0644\u06e1\u0628\u064e\u0648\u064e\u0627\u0631\u0650",translation:"Tidakkah kamu memperhatikan orang-orang yang telah menukar nikmat Allah dengan ingkar kepada Allah dan menjatuhkan kaumnya ke lembah kebinasaan"},{id:29,text:"\u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u064a\u064e\u0635\u06e1\u0644\u064e\u0648\u06e1\u0646\u064e\u0647\u064e\u0627\u06d6 \u0648\u064e\u0628\u0650\u0626\u06e1\u0633\u064e \u0671\u0644\u06e1\u0642\u064e\u0631\u064e\u0627\u0631\u064f",translation:"yaitu neraka Jahanam; mereka masuk ke dalamnya; dan itulah seburuk-buruk tempat kediaman"},{id:30,text:"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064f\u0648\u0627\u0652 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0646\u062f\u064e\u0627\u062f\u0657\u0627 \u0644\u0651\u0650\u064a\u064f\u0636\u0650\u0644\u0651\u064f\u0648\u0627\u0652 \u0639\u064e\u0646 \u0633\u064e\u0628\u0650\u064a\u0644\u0650\u0647\u0650\u06e6\u06d7 \u0642\u064f\u0644\u06e1 \u062a\u064e\u0645\u064e\u062a\u0651\u064e\u0639\u064f\u0648\u0627\u0652 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0645\u064e\u0635\u0650\u064a\u0631\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650",translation:"Dan mereka (orang kafir) itu telah menjadikan tandingan bagi Allah untuk menyesatkan (manusia) dari jalan-Nya. Katakanlah (Muhammad), \"Bersenang-senanglah kamu, karena sesungguhnya tempat kembalimu ke neraka"},{id:31,text:"\u0642\u064f\u0644 \u0644\u0651\u0650\u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u064a\u064f\u0642\u0650\u064a\u0645\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u064a\u064f\u0646\u0641\u0650\u0642\u064f\u0648\u0627\u0652 \u0645\u0650\u0645\u0651\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0633\u0650\u0631\u0651\u0657\u0627 \u0648\u064e\u0639\u064e\u0644\u064e\u0627\u0646\u0650\u064a\u064e\u0629\u0657 \u0645\u0651\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650 \u0623\u064e\u0646 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e \u064a\u064e\u0648\u06e1\u0645\u065e \u0644\u0651\u064e\u0627 \u0628\u064e\u064a\u06e1\u0639\u065e \u0641\u0650\u064a\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u062e\u0650\u0644\u064e\u0670\u0644\u064c",translation:"Katakanlah (Muhammad) kepada hamba-hamba-Ku yang telah beriman, \"Hendaklah mereka melaksanakan salat, menginfakkan sebagian rezeki yang Kami berikan secara sembunyi atau terang-terangan sebelum datang hari, ketika tidak ada lagi jual beli dan persahabatan"},{id:32,text:"\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0648\u064e\u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0645\u064e\u0627\u0653\u0621\u0657 \u0641\u064e\u0623\u064e\u062e\u06e1\u0631\u064e\u062c\u064e \u0628\u0650\u0647\u0650\u06e6 \u0645\u0650\u0646\u064e \u0671\u0644\u062b\u0651\u064e\u0645\u064e\u0631\u064e\u0670\u062a\u0650 \u0631\u0650\u0632\u06e1\u0642\u0657\u0627 \u0644\u0651\u064e\u0643\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0633\u064e\u062e\u0651\u064e\u0631\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0641\u064f\u0644\u06e1\u0643\u064e \u0644\u0650\u062a\u064e\u062c\u06e1\u0631\u0650\u064a\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0628\u064e\u062d\u06e1\u0631\u0650 \u0628\u0650\u0623\u064e\u0645\u06e1\u0631\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u0633\u064e\u062e\u0651\u064e\u0631\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u064e",translation:"Allah lah yang telah menciptakan langit dan bumi dan menurunkan air (hujan) dari langit, kemudian dengan (air hujan) itu Dia mengeluarkan berbagai buah-buahan sebagai rezeki untukmu; dan Dia telah menundukkan kapal bagimu agar berlayar di lautan dengan kehendak-Nya, dan Dia telah menundukkan sungai-sungai bagimu"},{id:33,text:"\u0648\u064e\u0633\u064e\u062e\u0651\u064e\u0631\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0634\u0651\u064e\u0645\u06e1\u0633\u064e \u0648\u064e\u0671\u0644\u06e1\u0642\u064e\u0645\u064e\u0631\u064e \u062f\u064e\u0627\u0653\u0626\u0650\u0628\u064e\u064a\u06e1\u0646\u0650\u06d6 \u0648\u064e\u0633\u064e\u062e\u0651\u064e\u0631\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u064e \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e",translation:"Dan Dia telah menundukkan matahari dan bulan bagimu yang terus menerus beredar (dalam orbitnya); dan telah menundukkan malam dan siang bagimu"},{id:34,text:"\u0648\u064e\u0621\u064e\u0627\u062a\u064e\u0649\u0670\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u0645\u064e\u0627 \u0633\u064e\u0623\u064e\u0644\u06e1\u062a\u064f\u0645\u064f\u0648\u0647\u064f\u06da \u0648\u064e\u0625\u0650\u0646 \u062a\u064e\u0639\u064f\u062f\u0651\u064f\u0648\u0627\u0652 \u0646\u0650\u0639\u06e1\u0645\u064e\u062a\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0627 \u062a\u064f\u062d\u06e1\u0635\u064f\u0648\u0647\u064e\u0627\u0653\u06d7 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064e \u0644\u064e\u0638\u064e\u0644\u064f\u0648\u0645\u065e \u0643\u064e\u0641\u0651\u064e\u0627\u0631\u065e",translation:"Dan Dia telah memberikan kepadamu segala apa yang kamu mohonkan kepada-Nya. Dan jika kamu menghitung nikmat Allah, niscaya kamu tidak dapat menghitungnya. Sungguh, manusia itu sangat zalim dan sangat mengingkari (nikmat Allah)"},{id:35,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064f \u0631\u064e\u0628\u0651\u0650 \u0671\u062c\u06e1\u0639\u064e\u0644\u06e1 \u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u06e1\u0628\u064e\u0644\u064e\u062f\u064e \u0621\u064e\u0627\u0645\u0650\u0646\u0657\u0627 \u0648\u064e\u0671\u062c\u06e1\u0646\u064f\u0628\u06e1\u0646\u0650\u064a \u0648\u064e\u0628\u064e\u0646\u0650\u064a\u0651\u064e \u0623\u064e\u0646 \u0646\u0651\u064e\u0639\u06e1\u0628\u064f\u062f\u064e \u0671\u0644\u06e1\u0623\u064e\u0635\u06e1\u0646\u064e\u0627\u0645\u064e",translation:"Dan (ingatlah), ketika Ibrahim berdoa, \"Ya Tuhan, jadikanlah negeri ini (Mekkah), negeri yang aman, dan jauhkanlah aku beserta anak cucuku agar tidak menyembah berhala"},{id:36,text:"\u0631\u064e\u0628\u0651\u0650 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0646\u0651\u064e \u0623\u064e\u0636\u06e1\u0644\u064e\u0644\u06e1\u0646\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650\u06d6 \u0641\u064e\u0645\u064e\u0646 \u062a\u064e\u0628\u0650\u0639\u064e\u0646\u0650\u064a \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646\u0651\u0650\u064a\u06d6 \u0648\u064e\u0645\u064e\u0646\u06e1 \u0639\u064e\u0635\u064e\u0627\u0646\u0650\u064a \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u065e",translation:"Ya Tuhan, berhala-berhala itu telah menyesatkan banyak manusia. Barangsiapa mengikutiku, maka orang itu termasuk golonganku, dan barangsiapa mendurhakaiku, maka Engkau Maha Pengampun, Maha Penyayang"},{id:37,text:"\u0631\u0651\u064e\u0628\u0651\u064e\u0646\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064e\u0633\u06e1\u0643\u064e\u0646\u062a\u064f \u0645\u0650\u0646 \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u062a\u0650\u064a \u0628\u0650\u0648\u064e\u0627\u062f\u064d \u063a\u064e\u064a\u06e1\u0631\u0650 \u0630\u0650\u064a \u0632\u064e\u0631\u06e1\u0639\u064d \u0639\u0650\u0646\u062f\u064e \u0628\u064e\u064a\u06e1\u062a\u0650\u0643\u064e \u0671\u0644\u06e1\u0645\u064f\u062d\u064e\u0631\u0651\u064e\u0645\u0650 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0644\u0650\u064a\u064f\u0642\u0650\u064a\u0645\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e \u0641\u064e\u0671\u062c\u06e1\u0639\u064e\u0644\u06e1 \u0623\u064e\u0641\u06e1\u0640\u0654\u0650\u062f\u064e\u0629\u0657 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u062a\u064e\u0647\u06e1\u0648\u0650\u064a\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0648\u064e\u0671\u0631\u06e1\u0632\u064f\u0642\u06e1\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u062b\u0651\u064e\u0645\u064e\u0631\u064e\u0670\u062a\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0634\u06e1\u0643\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Ya Tuhan, sesungguhnya aku telah menempatkan sebagian keturunanku di lembah yang tidak mempunyai tanam-tanaman di dekat rumah Engkau (Baitullah) yang dihormati, ya Tuhan (yang demikian itu) agar mereka melaksanakan salat, maka jadikanlah hati sebagian manusia cenderung kepada mereka dan berilah mereka rezeki dari buah-buahan, mudah-mudahan mereka bersyukur"},{id:38,text:"\u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0646\u064f\u062e\u06e1\u0641\u0650\u064a \u0648\u064e\u0645\u064e\u0627 \u0646\u064f\u0639\u06e1\u0644\u0650\u0646\u064f\u06d7 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u062e\u06e1\u0641\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0644\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650",translation:"Ya Tuhan kami, sesungguhnya Engkau mengetahui apa yang kami sembunyikan dan apa yang kami tampakkan; dan tidak ada sesuatu pun yang tersembunyi bagi Allah, baik yang ada di bumi maupun yang ada di langit"},{id:39,text:"\u0671\u0644\u06e1\u062d\u064e\u0645\u06e1\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0648\u064e\u0647\u064e\u0628\u064e \u0644\u0650\u064a \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0643\u0650\u0628\u064e\u0631\u0650 \u0625\u0650\u0633\u06e1\u0645\u064e\u0670\u0639\u0650\u064a\u0644\u064e \u0648\u064e\u0625\u0650\u0633\u06e1\u062d\u064e\u0670\u0642\u064e\u06da \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0644\u064e\u0633\u064e\u0645\u0650\u064a\u0639\u064f \u0671\u0644\u062f\u0651\u064f\u0639\u064e\u0627\u0653\u0621\u0650",translation:"Segala puji bagi Allah yang telah menganugerahkan kepadaku di hari tua(ku) Ismail dan Ishak. Sungguh, Tuhanku, benar-benar Maha Mendengar (memperkenankan) doa"},{id:40,text:"\u0631\u064e\u0628\u0651\u0650 \u0671\u062c\u06e1\u0639\u064e\u0644\u06e1\u0646\u0650\u064a \u0645\u064f\u0642\u0650\u064a\u0645\u064e \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u0650 \u0648\u064e\u0645\u0650\u0646 \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u062a\u0650\u064a\u06da \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0648\u064e\u062a\u064e\u0642\u064e\u0628\u0651\u064e\u0644\u06e1 \u062f\u064f\u0639\u064e\u0627\u0653\u0621\u0650",translation:"Ya Tuhanku, jadikanlah aku dan anak cucuku orang yang tetap melaksanakan salat, ya Tuhan kami, perkenankanlah doaku"},{id:41,text:"\u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0671\u063a\u06e1\u0641\u0650\u0631\u06e1 \u0644\u0650\u064a \u0648\u064e\u0644\u0650\u0648\u064e\u0670\u0644\u0650\u062f\u064e\u064a\u0651\u064e \u0648\u064e\u0644\u0650\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064e\u0642\u064f\u0648\u0645\u064f \u0671\u0644\u06e1\u062d\u0650\u0633\u064e\u0627\u0628\u064f",translation:"Ya Tuhan kami, ampunilah aku dan kedua ibu bapakku dan semua orang yang beriman pada hari diadakan perhitungan (hari Kiamat)"},{id:42,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062d\u06e1\u0633\u064e\u0628\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0670\u0641\u0650\u0644\u064b\u0627 \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u064f\u0648\u0646\u064e\u06da \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064f\u0624\u064e\u062e\u0651\u0650\u0631\u064f\u0647\u064f\u0645\u06e1 \u0644\u0650\u064a\u064e\u0648\u06e1\u0645\u0656 \u062a\u064e\u0634\u06e1\u062e\u064e\u0635\u064f \u0641\u0650\u064a\u0647\u0650 \u0671\u0644\u06e1\u0623\u064e\u0628\u06e1\u0635\u064e\u0670\u0631\u064f",translation:"Dan janganlah engkau mengira, bahwa Allah lengah dari apa yang diperbuat oleh orang yang zalim. Sesungguhnya Allah menangguhkan mereka sampai hari yang pada waktu itu mata (mereka) terbelalak"},{id:43,text:"\u0645\u064f\u0647\u06e1\u0637\u0650\u0639\u0650\u064a\u0646\u064e \u0645\u064f\u0642\u06e1\u0646\u0650\u0639\u0650\u064a \u0631\u064f\u0621\u064f\u0648\u0633\u0650\u0647\u0650\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0631\u06e1\u062a\u064e\u062f\u0651\u064f \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0637\u064e\u0631\u06e1\u0641\u064f\u0647\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0623\u064e\u0641\u06e1\u0640\u0654\u0650\u062f\u064e\u062a\u064f\u0647\u064f\u0645\u06e1 \u0647\u064e\u0648\u064e\u0627\u0653\u0621\u065e",translation:"mereka datang tergesa-gesa (memenuhi panggilan) dengan mengangkat kepalanya, sedang mata mereka tidak berkedip dan hati mereka kosong"},{id:44,text:"\u0648\u064e\u0623\u064e\u0646\u0630\u0650\u0631\u0650 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u0647\u0650\u0645\u064f \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0641\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627\u0652 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627\u0653 \u0623\u064e\u062e\u0651\u0650\u0631\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u062c\u064e\u0644\u0656 \u0642\u064e\u0631\u0650\u064a\u0628\u0656 \u0646\u0651\u064f\u062c\u0650\u0628\u06e1 \u062f\u064e\u0639\u06e1\u0648\u064e\u062a\u064e\u0643\u064e \u0648\u064e\u0646\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u0650 \u0671\u0644\u0631\u0651\u064f\u0633\u064f\u0644\u064e\u06d7 \u0623\u064e\u0648\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0642\u06e1\u0633\u064e\u0645\u06e1\u062a\u064f\u0645 \u0645\u0651\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f \u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0632\u064e\u0648\u064e\u0627\u0644\u0656",translation:"Dan berikanlah peringatan (Muhammad) kepada manusia pada hari (ketika) azab datang kepada mereka, maka orang yang zalim berkata, \"Ya Tuhan kami, berilah kami kesempatan (kembali ke dunia) walaupun sebentar, niscaya kami akan mematuhi seruan Engkau dan akan mengikuti rasul-rasul.\" (Kepada mereka dikatakan), \"Bukankah dahulu (di dunia) kamu telah bersumpah bahwa sekali-kali kamu tidak akan binasa"},{id:45,text:"\u0648\u064e\u0633\u064e\u0643\u064e\u0646\u062a\u064f\u0645\u06e1 \u0641\u0650\u064a \u0645\u064e\u0633\u064e\u0670\u0643\u0650\u0646\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u062a\u064e\u0628\u064e\u064a\u0651\u064e\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u06e1 \u0643\u064e\u064a\u06e1\u0641\u064e \u0641\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0628\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0636\u064e\u0631\u064e\u0628\u06e1\u0646\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u062b\u064e\u0627\u0644\u064e",translation:"dan kamu telah tinggal di tempat orang yang menzalimi diri sendiri, dan telah nyata bagimu bagaimana Kami telah berbuat terhadap mereka dan telah Kami berikan kepadamu beberapa perumpamaan"},{id:46,text:"\u0648\u064e\u0642\u064e\u062f\u06e1 \u0645\u064e\u0643\u064e\u0631\u064f\u0648\u0627\u0652 \u0645\u064e\u0643\u06e1\u0631\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0643\u06e1\u0631\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064e \u0645\u064e\u0643\u06e1\u0631\u064f\u0647\u064f\u0645\u06e1 \u0644\u0650\u062a\u064e\u0632\u064f\u0648\u0644\u064e \u0645\u0650\u0646\u06e1\u0647\u064f \u0671\u0644\u06e1\u062c\u0650\u0628\u064e\u0627\u0644\u064f",translation:"Dan sungguh, mereka telah membuat tipu daya padahal Allah (mengetahui dan akan membalas) tipu daya mereka. Dan sesungguhnya tipu daya mereka tidak mampu melenyapkan gunung-gunung"},{id:47,text:"\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062d\u06e1\u0633\u064e\u0628\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064f\u062e\u06e1\u0644\u0650\u0641\u064e \u0648\u064e\u0639\u06e1\u062f\u0650\u0647\u0650\u06e6 \u0631\u064f\u0633\u064f\u0644\u064e\u0647\u064f\u06e5\u0653\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0632\u0650\u064a\u0632\u065e \u0630\u064f\u0648 \u0671\u0646\u062a\u0650\u0642\u064e\u0627\u0645\u0656",translation:"Maka karena itu, jangan sekali-kali kamu mengira bahwa Allah mengingkari janji-Nya kepada rasul-rasul-Nya! Sungguh, Allah Mahaperkasa dan mempunyai pembalasan"},{id:48,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u062a\u064f\u0628\u064e\u062f\u0651\u064e\u0644\u064f \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064f \u063a\u064e\u064a\u06e1\u0631\u064e \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u064f\u06d6 \u0648\u064e\u0628\u064e\u0631\u064e\u0632\u064f\u0648\u0627\u0652 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u0648\u064e\u0670\u062d\u0650\u062f\u0650 \u0671\u0644\u06e1\u0642\u064e\u0647\u0651\u064e\u0627\u0631\u0650",translation:"(Yaitu) pada hari (ketika) bumi diganti dengan bumi yang lain dan (demikian pula) langit, dan mereka (manusia) berkumpul (di padang Mahsyar) menghadap Allah Yang Maha Esa, Mahaperkasa"},{id:49,text:"\u0648\u064e\u062a\u064e\u0631\u064e\u0649 \u0671\u0644\u06e1\u0645\u064f\u062c\u06e1\u0631\u0650\u0645\u0650\u064a\u0646\u064e \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u0645\u0651\u064f\u0642\u064e\u0631\u0651\u064e\u0646\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0635\u06e1\u0641\u064e\u0627\u062f\u0650",translation:"Dan pada hari itu engkau akan melihat orang yang berdosa bersama-sama diikat dengan belenggu"},{id:50,text:"\u0633\u064e\u0631\u064e\u0627\u0628\u0650\u064a\u0644\u064f\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0642\u064e\u0637\u0650\u0631\u064e\u0627\u0646\u0656 \u0648\u064e\u062a\u064e\u063a\u06e1\u0634\u064e\u0649\u0670 \u0648\u064f\u062c\u064f\u0648\u0647\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u064f",translation:"Pakaian mereka dari cairan aspal, dan wajah mereka ditutup oleh api neraka"},{id:51,text:"\u0644\u0650\u064a\u064e\u062c\u06e1\u0632\u0650\u064a\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0643\u064f\u0644\u0651\u064e \u0646\u064e\u0641\u06e1\u0633\u0656 \u0645\u0651\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064e\u062a\u06e1\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0633\u064e\u0631\u0650\u064a\u0639\u064f \u0671\u0644\u06e1\u062d\u0650\u0633\u064e\u0627\u0628\u0650",translation:"agar Allah memberi balasan kepada setiap orang atas apa yang dia usahakan. Sungguh, Allah Mahacepat perhitungan-Nya"},{id:52,text:"\u0647\u064e\u0670\u0630\u064e\u0627 \u0628\u064e\u0644\u064e\u0670\u063a\u065e \u0644\u0651\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0644\u0650\u064a\u064f\u0646\u0630\u064e\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6 \u0648\u064e\u0644\u0650\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u0647\u064f\u0648\u064e \u0625\u0650\u0644\u064e\u0670\u0647\u065e \u0648\u064e\u0670\u062d\u0650\u062f\u065e \u0648\u064e\u0644\u0650\u064a\u064e\u0630\u0651\u064e\u0643\u0651\u064e\u0631\u064e \u0623\u064f\u0648\u0652\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0623\u064e\u0644\u06e1\u0628\u064e\u0670\u0628\u0650",translation:"Dan (Alquran) ini adalah penjelasan (yang sempurna) bagi manusia, agar mereka diberi peringatan dengannya, agar mereka mengetahui bahwa Dia adalah Tuhan Yang Maha Esa dan agar orang yang berakal mengambil pelajaran"}]},{id:15,name:"\u0627\u0644\u062d\u062c\u0631",transliteration:"Al-Hijr",translation:"Bukit",type:"meccan",total_verses:99,verses:[{id:1,text:"\u0627\u0644\u0653\u0631\u06da \u062a\u0650\u0644\u06e1\u0643\u064e \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u064f \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0648\u064e\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u0656 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u0656",translation:"Alif L\u0101m R\u0101`. (Surah) ini adalah (sebagian dari) ayat-ayat Kitab (yang sempurna) yaitu (ayat-ayat) Alquran yang memberi penjelasan"},{id:2,text:"\u0631\u0651\u064f\u0628\u064e\u0645\u064e\u0627 \u064a\u064e\u0648\u064e\u062f\u0651\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0644\u064e\u0648\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0645\u064f\u0633\u06e1\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Orang kafir itu kadang-kadang (nanti di akhirat) menginginkan, sekiranya mereka dahulu (di dunia) menjadi orang muslim"},{id:3,text:"\u0630\u064e\u0631\u06e1\u0647\u064f\u0645\u06e1 \u064a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f\u0648\u0627\u0652 \u0648\u064e\u064a\u064e\u062a\u064e\u0645\u064e\u062a\u0651\u064e\u0639\u064f\u0648\u0627\u0652 \u0648\u064e\u064a\u064f\u0644\u06e1\u0647\u0650\u0647\u0650\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u0645\u064e\u0644\u064f\u06d6 \u0641\u064e\u0633\u064e\u0648\u06e1\u0641\u064e \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Biarkanlah mereka (di dunia ini) makan dan bersenang-senang dan dilalaikan oleh angan-angan (kosong) mereka, kelak mereka akan mengetahui (akibat perbuatannya)"},{id:4,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0647\u06e1\u0644\u064e\u0643\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646 \u0642\u064e\u0631\u06e1\u064a\u064e\u0629\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0648\u064e\u0644\u064e\u0647\u064e\u0627 \u0643\u0650\u062a\u064e\u0627\u0628\u065e \u0645\u0651\u064e\u0639\u06e1\u0644\u064f\u0648\u0645\u065e",translation:"Dan Kami tidak membinasakan suatu negeri, melainkan sudah ada ketentuan yang di tetapkan baginya"},{id:5,text:"\u0645\u0651\u064e\u0627 \u062a\u064e\u0633\u06e1\u0628\u0650\u0642\u064f \u0645\u0650\u0646\u06e1 \u0623\u064f\u0645\u0651\u064e\u0629\u064d \u0623\u064e\u062c\u064e\u0644\u064e\u0647\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0640\u0654\u06e1\u062e\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Tidak ada suatu umat pun yang dapat mendahului ajalnya, dan tidak (pula) dapat meminta penundaan(nya)"},{id:6,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0646\u064f\u0632\u0651\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0671\u0644\u0630\u0651\u0650\u0643\u06e1\u0631\u064f \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u0645\u064e\u062c\u06e1\u0646\u064f\u0648\u0646\u065e",translation:"Dan mereka berkata, \"Wahai orang yang kepadanya diturunkan Alquran, sesungguhnya engkau (Muhammad) benar-benar orang yang gila"},{id:7,text:"\u0644\u0651\u064e\u0648\u06e1\u0645\u064e\u0627 \u062a\u064e\u0623\u06e1\u062a\u0650\u064a\u0646\u064e\u0627 \u0628\u0650\u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u0650 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Mengapa engkau tidak mendatangkan malaikat kepada kami, jika engkau termasuk orang yang benar"},{id:8,text:"\u0645\u064e\u0627 \u0646\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u064f \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0630\u0657\u0627 \u0645\u0651\u064f\u0646\u0638\u064e\u0631\u0650\u064a\u0646\u064e",translation:"Kami tidak menurunkan malaikat melainkan dengan kebenaran (untuk membawa azab) dan mereka ketika itu tidak diberi penangguhan"},{id:9,text:"\u0625\u0650\u0646\u0651\u064e\u0627 \u0646\u064e\u062d\u06e1\u0646\u064f \u0646\u064e\u0632\u0651\u064e\u0644\u06e1\u0646\u064e\u0627 \u0671\u0644\u0630\u0651\u0650\u0643\u06e1\u0631\u064e \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0647\u064f\u06e5 \u0644\u064e\u062d\u064e\u0670\u0641\u0650\u0638\u064f\u0648\u0646\u064e",translation:"Sesungguhnya Kamilah yang menurunkan Alquran, dan pasti Kami (pula) yang memeliharanya"},{id:10,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064e \u0641\u0650\u064a \u0634\u0650\u064a\u064e\u0639\u0650 \u0671\u0644\u06e1\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",translation:"Dan sungguh, Kami telah mengutus (beberapa rasul) sebelum engkau (Muhammad) kepada umat-umat terdahulu"},{id:11,text:"\u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u0647\u0650\u0645 \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6 \u064a\u064e\u0633\u06e1\u062a\u064e\u0647\u06e1\u0632\u0650\u0621\u064f\u0648\u0646\u064e",translation:"Dan setiap kali seorang rasul datang kepada mereka, mereka selalu memperolok-olokannya"},{id:12,text:"\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u0633\u06e1\u0644\u064f\u0643\u064f\u0647\u064f\u06e5 \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650 \u0671\u0644\u06e1\u0645\u064f\u062c\u06e1\u0631\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Demikianlah, Kami memasukkannya (olok-olok itu) ke dalam hati orang yang berdosa"},{id:13,text:"\u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u0650\u06e6 \u0648\u064e\u0642\u064e\u062f\u06e1 \u062e\u064e\u0644\u064e\u062a\u06e1 \u0633\u064f\u0646\u0651\u064e\u0629\u064f \u0671\u0644\u06e1\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",translation:"mereka tidak beriman kepadanya (Alquran) padahal telah berlalu sunnatullah433) terhadap orang-orang terdahulu"},{id:14,text:"\u0648\u064e\u0644\u064e\u0648\u06e1 \u0641\u064e\u062a\u064e\u062d\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0628\u064e\u0627\u0628\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0641\u064e\u0638\u064e\u0644\u0651\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0647\u0650 \u064a\u064e\u0639\u06e1\u0631\u064f\u062c\u064f\u0648\u0646\u064e",translation:"Dan kalau Kami bukakan kepada mereka salah satu pintu langit, lalu mereka terus menerus naik ke atasnya"},{id:15,text:"\u0644\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0633\u064f\u0643\u0651\u0650\u0631\u064e\u062a\u06e1 \u0623\u064e\u0628\u06e1\u0635\u064e\u0670\u0631\u064f\u0646\u064e\u0627 \u0628\u064e\u0644\u06e1 \u0646\u064e\u062d\u06e1\u0646\u064f \u0642\u064e\u0648\u06e1\u0645\u065e \u0645\u0651\u064e\u0633\u06e1\u062d\u064f\u0648\u0631\u064f\u0648\u0646\u064e",translation:"tentulah mereka berkata, \"Sesungguhnya pandangan kamilah yang dikaburkan, bahkan kami adalah orang yang terkena sihir"},{id:16,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0628\u064f\u0631\u064f\u0648\u062c\u0657\u0627 \u0648\u064e\u0632\u064e\u064a\u0651\u064e\u0646\u0651\u064e\u0640\u0670\u0647\u064e\u0627 \u0644\u0650\u0644\u0646\u0651\u064e\u0640\u0670\u0638\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan sungguh, Kami telah menciptakan gugusan bintang di langit dan menjadikannya terasa indah bagi orang yang memandang(nya)"},{id:17,text:"\u0648\u064e\u062d\u064e\u0641\u0650\u0638\u06e1\u0646\u064e\u0670\u0647\u064e\u0627 \u0645\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u0656 \u0631\u0651\u064e\u062c\u0650\u064a\u0645\u064d",translation:"dan Kami menjaganya dari setiap (gangguan) setan yang terkutuk"},{id:18,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u0650 \u0671\u0633\u06e1\u062a\u064e\u0631\u064e\u0642\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u06e1\u0639\u064e \u0641\u064e\u0623\u064e\u062a\u06e1\u0628\u064e\u0639\u064e\u0647\u064f\u06e5 \u0634\u0650\u0647\u064e\u0627\u0628\u065e \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u065e",translation:"kecuali (setan) yang mencuri-curi (berita) yang dapat didengar (dari malaikat) lalu dikejar oleh semburan api yang terang"},{id:19,text:"\u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0645\u064e\u062f\u064e\u062f\u06e1\u0646\u064e\u0670\u0647\u064e\u0627 \u0648\u064e\u0623\u064e\u0644\u06e1\u0642\u064e\u064a\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0631\u064e\u0648\u064e\u0670\u0633\u0650\u064a\u064e \u0648\u064e\u0623\u064e\u0646\u06e2\u0628\u064e\u062a\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0645\u0651\u064e\u0648\u06e1\u0632\u064f\u0648\u0646\u0656",translation:"Dan Kami telah menghamparkan bumi dan Kami pancangkan padanya gunung-gunung serta Kami tumbuhkan di sana segala sesuatu menurut ukuran"},{id:20,text:"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u064e\u0639\u064e\u0670\u064a\u0650\u0634\u064e \u0648\u064e\u0645\u064e\u0646 \u0644\u0651\u064e\u0633\u06e1\u062a\u064f\u0645\u06e1 \u0644\u064e\u0647\u064f\u06e5 \u0628\u0650\u0631\u064e\u0670\u0632\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Dan Kami telah menjadikan padanya sumber-sumber kehidupan untuk keperluanmu, dan (Kami ciptakan pula) makhluk-makhluk yang bukan kamu pemberi rezekinya"},{id:21,text:"\u0648\u064e\u0625\u0650\u0646 \u0645\u0651\u0650\u0646 \u0634\u064e\u064a\u06e1\u0621\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u0650\u0646\u062f\u064e\u0646\u064e\u0627 \u062e\u064e\u0632\u064e\u0627\u0653\u0626\u0650\u0646\u064f\u0647\u064f\u06e5 \u0648\u064e\u0645\u064e\u0627 \u0646\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u064f\u0647\u064f\u06e5\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0642\u064e\u062f\u064e\u0631\u0656 \u0645\u0651\u064e\u0639\u06e1\u0644\u064f\u0648\u0645\u0656",translation:"(Dan tidak ada sesuatu pun, melainkan pada sisi Kamilah khazanahnya;434) Kami tidak menurunkannya melainkan dengan ukuran tertentu"},{id:22,text:"\u0648\u064e\u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0671\u0644\u0631\u0651\u0650\u064a\u064e\u0670\u062d\u064e \u0644\u064e\u0648\u064e\u0670\u0642\u0650\u062d\u064e \u0641\u064e\u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0645\u064e\u0627\u0653\u0621\u0657 \u0641\u064e\u0623\u064e\u0633\u06e1\u0642\u064e\u064a\u06e1\u0646\u064e\u0670\u0643\u064f\u0645\u064f\u0648\u0647\u064f \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0644\u064e\u0647\u064f\u06e5 \u0628\u0650\u062e\u064e\u0670\u0632\u0650\u0646\u0650\u064a\u0646\u064e",translation:"(Dan Kami telah meniupkan angin untuk mengawinkan435) dan Kami turunkan hujan dari langit, lalu Kami beri minum kamu dengan (air) itu, dan bukanlah kamu yang menyimpannya"},{id:23,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0646\u064e\u062d\u06e1\u0646\u064f \u0646\u064f\u062d\u06e1\u064a\u0650\u06e6 \u0648\u064e\u0646\u064f\u0645\u0650\u064a\u062a\u064f \u0648\u064e\u0646\u064e\u062d\u06e1\u0646\u064f \u0671\u0644\u06e1\u0648\u064e\u0670\u0631\u0650\u062b\u064f\u0648\u0646\u064e",translation:"Dan sungguh, Kamilah yang menghidupkan dan mematikan dan Kami (pulalah) yang mewarisi"},{id:24,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0639\u064e\u0644\u0650\u0645\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0645\u064f\u0633\u06e1\u062a\u064e\u0642\u06e1\u062f\u0650\u0645\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0639\u064e\u0644\u0650\u0645\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0645\u064f\u0633\u06e1\u062a\u064e\u0640\u0654\u06e1\u062e\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan sungguh, Kami mengetahui orang yang terdahulu sebelum kamu dan Kami mengetahui pula orang yang terkemudian"},{id:25,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0647\u064f\u0648\u064e \u064a\u064e\u062d\u06e1\u0634\u064f\u0631\u064f\u0647\u064f\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u062d\u064e\u0643\u0650\u064a\u0645\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Dan sesungguhnya Tuhanmu, Dialah yang akan mengumpulkan mereka. Sungguh, Dia Mahabijaksana, Maha Mengetahui"},{id:26,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u062e\u064e\u0644\u064e\u0642\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064e \u0645\u0650\u0646 \u0635\u064e\u0644\u06e1\u0635\u064e\u0670\u0644\u0656 \u0645\u0651\u0650\u0646\u06e1 \u062d\u064e\u0645\u064e\u0625\u0656 \u0645\u0651\u064e\u0633\u06e1\u0646\u064f\u0648\u0646\u0656",translation:"Dan sungguh, Kami telah menciptakan manusia (Adam) dari tanah liat kering dari lumpur hitam yang diberi bentuk"},{id:27,text:"\u0648\u064e\u0671\u0644\u06e1\u062c\u064e\u0627\u0653\u0646\u0651\u064e \u062e\u064e\u0644\u064e\u0642\u06e1\u0646\u064e\u0670\u0647\u064f \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f \u0645\u0650\u0646 \u0646\u0651\u064e\u0627\u0631\u0650 \u0671\u0644\u0633\u0651\u064e\u0645\u064f\u0648\u0645\u0650",translation:"Dan Kami telah menciptakan jin sebelum (Adam) dari api yang sangat panas"},{id:28,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0644\u0650\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u0650 \u0625\u0650\u0646\u0651\u0650\u064a \u062e\u064e\u0670\u0644\u0650\u0642\u064f\u06e2 \u0628\u064e\u0634\u064e\u0631\u0657\u0627 \u0645\u0651\u0650\u0646 \u0635\u064e\u0644\u06e1\u0635\u064e\u0670\u0644\u0656 \u0645\u0651\u0650\u0646\u06e1 \u062d\u064e\u0645\u064e\u0625\u0656 \u0645\u0651\u064e\u0633\u06e1\u0646\u064f\u0648\u0646\u0656",translation:"Dan (ingatlah), ketika Tuhanmu berfirman kepada para malaikat, \"Sungguh, Aku akan menciptakan seorang manusia dari tanah liat kering dari lumpur hitam yang diberi bentuk"},{id:29,text:"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0633\u064e\u0648\u0651\u064e\u064a\u06e1\u062a\u064f\u0647\u064f\u06e5 \u0648\u064e\u0646\u064e\u0641\u064e\u062e\u06e1\u062a\u064f \u0641\u0650\u064a\u0647\u0650 \u0645\u0650\u0646 \u0631\u0651\u064f\u0648\u062d\u0650\u064a \u0641\u064e\u0642\u064e\u0639\u064f\u0648\u0627\u0652 \u0644\u064e\u0647\u064f\u06e5 \u0633\u064e\u0670\u062c\u0650\u062f\u0650\u064a\u0646\u064e",translation:"Maka apabila Aku telah menyempurnakan (kejadian)nya, dan Aku telah meniupkan roh (ciptaan)-Ku ke dalamnya, maka tunduklah kamu kepadanya dengan bersujud"},{id:30,text:"\u0641\u064e\u0633\u064e\u062c\u064e\u062f\u064e \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u064f \u0643\u064f\u0644\u0651\u064f\u0647\u064f\u0645\u06e1 \u0623\u064e\u062c\u06e1\u0645\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Maka bersujudlah para malaikat itu semuanya bersama-sama"},{id:31,text:"\u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0625\u0650\u0628\u06e1\u0644\u0650\u064a\u0633\u064e \u0623\u064e\u0628\u064e\u0649\u0670\u0653 \u0623\u064e\u0646 \u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u064e\u0639\u064e \u0671\u0644\u0633\u0651\u064e\u0640\u0670\u062c\u0650\u062f\u0650\u064a\u0646\u064e",translation:"kecuali Iblis. Ia enggan ikut bersama-sama para (malaikat) yang sujud itu"},{id:32,text:"\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0640\u0670\u0653\u0625\u0650\u0628\u06e1\u0644\u0650\u064a\u0633\u064f \u0645\u064e\u0627 \u0644\u064e\u0643\u064e \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u064e\u0639\u064e \u0671\u0644\u0633\u0651\u064e\u0640\u0670\u062c\u0650\u062f\u0650\u064a\u0646\u064e",translation:"Dia (Allah) berfirman, \"Wahai Iblis! Apa sebabnya kamu (tidak ikut) sujud bersama mereka"},{id:33,text:"\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0645\u06e1 \u0623\u064e\u0643\u064f\u0646 \u0644\u0651\u0650\u0623\u064e\u0633\u06e1\u062c\u064f\u062f\u064e \u0644\u0650\u0628\u064e\u0634\u064e\u0631\u064d \u062e\u064e\u0644\u064e\u0642\u06e1\u062a\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646 \u0635\u064e\u0644\u06e1\u0635\u064e\u0670\u0644\u0656 \u0645\u0651\u0650\u0646\u06e1 \u062d\u064e\u0645\u064e\u0625\u0656 \u0645\u0651\u064e\u0633\u06e1\u0646\u064f\u0648\u0646\u0656",translation:"Ia (Iblis) berkata, \"Aku sekali-kali tidak akan sujud kepada manusia yang Engkau telah menciptakannya dari tanah liat kering dari lumpur hitam yang diberi bentuk"},{id:34,text:"\u0642\u064e\u0627\u0644\u064e \u0641\u064e\u0671\u062e\u06e1\u0631\u064f\u062c\u06e1 \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0631\u064e\u062c\u0650\u064a\u0645\u065e",translation:"Dia (Allah) berfirman, \"(Kalau begitu) keluarlah dari surga, karena sesungguhnya kamu terkutuk"},{id:35,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0671\u0644\u0644\u0651\u064e\u0639\u06e1\u0646\u064e\u0629\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u0650",translation:"dan sesungguhnya kutukan itu tetap menimpamu sampai hari Kiamat"},{id:36,text:"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0641\u064e\u0623\u064e\u0646\u0638\u0650\u0631\u06e1\u0646\u0650\u064a\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u06e1\u0645\u0650 \u064a\u064f\u0628\u06e1\u0639\u064e\u062b\u064f\u0648\u0646\u064e",translation:"Ia (Iblis) berkata, \"Ya Tuhanku, (kalau begitu) maka berilah penangguhan kepadaku sampai hari (manusia) dibangkitkan"},{id:37,text:"\u0642\u064e\u0627\u0644\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0646\u0638\u064e\u0631\u0650\u064a\u0646\u064e",translation:"Allah berfirman, \"(Baiklah) maka sesungguhnya kamu termasuk yang diberi penangguhan"},{id:38,text:"\u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0648\u064e\u0642\u06e1\u062a\u0650 \u0671\u0644\u06e1\u0645\u064e\u0639\u06e1\u0644\u064f\u0648\u0645\u0650",translation:"sampai hari yang telah ditentukan (Kiamat)"},{id:39,text:"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0628\u0650\u0645\u064e\u0627\u0653 \u0623\u064e\u063a\u06e1\u0648\u064e\u064a\u06e1\u062a\u064e\u0646\u0650\u064a \u0644\u064e\u0623\u064f\u0632\u064e\u064a\u0651\u0650\u0646\u064e\u0646\u0651\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0644\u064e\u0623\u064f\u063a\u06e1\u0648\u0650\u064a\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u062c\u06e1\u0645\u064e\u0639\u0650\u064a\u0646\u064e",translation:"Ia (Iblis) berkata, \"Tuhanku, oleh karena Engkau telah memutuskan bahwa aku sesat, aku pasti akan jadikan (kejahatan) tampak indah bagi mereka di bumi, dan aku akan menyesatkan mereka semuanya"},{id:40,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u0650\u0628\u064e\u0627\u062f\u064e\u0643\u064e \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064f\u062e\u06e1\u0644\u064e\u0635\u0650\u064a\u0646\u064e",translation:"kecuali hamba-hamba-Mu yang terpilih di antara mereka"},{id:41,text:"\u0642\u064e\u0627\u0644\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0635\u0650\u0631\u064e\u0670\u0637\u064c \u0639\u064e\u0644\u064e\u064a\u0651\u064e \u0645\u064f\u0633\u06e1\u062a\u064e\u0642\u0650\u064a\u0645\u064c",translation:"Dia (Allah) berfirman, \"Ini adalah jalan yang lurus (menuju) kepada-Ku"},{id:42,text:"\u0625\u0650\u0646\u0651\u064e \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a \u0644\u064e\u064a\u06e1\u0633\u064e \u0644\u064e\u0643\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0633\u064f\u0644\u06e1\u0637\u064e\u0670\u0646\u064c \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u0650 \u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u063a\u064e\u0627\u0648\u0650\u064a\u0646\u064e",translation:"Sesungguhnya kamu (Iblis) tidak kuasa atas hamba-hamba-Ku, kecuali mereka yang mengikutimu, yaitu orang yang sesat"},{id:43,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0644\u064e\u0645\u064e\u0648\u06e1\u0639\u0650\u062f\u064f\u0647\u064f\u0645\u06e1 \u0623\u064e\u062c\u06e1\u0645\u064e\u0639\u0650\u064a\u0646\u064e",translation:"Dan sungguh, Jahanam itu benar-benar (tempat) yang telah dijanjikan untuk mereka (pengikut setan) semuanya"},{id:44,text:"\u0644\u064e\u0647\u064e\u0627 \u0633\u064e\u0628\u06e1\u0639\u064e\u0629\u064f \u0623\u064e\u0628\u06e1\u0648\u064e\u0670\u0628\u0656 \u0644\u0651\u0650\u0643\u064f\u0644\u0651\u0650 \u0628\u064e\u0627\u0628\u0656 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u062c\u064f\u0632\u06e1\u0621\u065e \u0645\u0651\u064e\u0642\u06e1\u0633\u064f\u0648\u0645\u064c",translation:"(Jahanam) itu mempunyai tujuh pintu. Setiap pintu (telah ditetapkan) untuk golongan tertentu dari mereka"},{id:45,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0656 \u0648\u064e\u0639\u064f\u064a\u064f\u0648\u0646\u064d",translation:"Sesungguhnya orang yang bertakwa itu berada dalam surga-surga (taman-taman) dan (di dekat) mata air (yang mengalir)"},{id:46,text:"\u0671\u062f\u06e1\u062e\u064f\u0644\u064f\u0648\u0647\u064e\u0627 \u0628\u0650\u0633\u064e\u0644\u064e\u0670\u0645\u064d \u0621\u064e\u0627\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"(Allah berfirman), \"Masuklah ke dalamnya dengan sejahtera dan aman"},{id:47,text:"\u0648\u064e\u0646\u064e\u0632\u064e\u0639\u06e1\u0646\u064e\u0627 \u0645\u064e\u0627 \u0641\u0650\u064a \u0635\u064f\u062f\u064f\u0648\u0631\u0650\u0647\u0650\u0645 \u0645\u0651\u0650\u0646\u06e1 \u063a\u0650\u0644\u0651\u064d \u0625\u0650\u062e\u06e1\u0648\u064e\u0670\u0646\u064b\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0633\u064f\u0631\u064f\u0631\u0656 \u0645\u0651\u064f\u062a\u064e\u0642\u064e\u0670\u0628\u0650\u0644\u0650\u064a\u0646\u064e",translation:"Dan Kami lenyapkan segala rasa dendam yang ada dalam hati mereka; mereka merasa bersaudara, duduk berhadap-hadapan di atas dipan-dipan"},{id:48,text:"\u0644\u064e\u0627 \u064a\u064e\u0645\u064e\u0633\u0651\u064f\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u0646\u064e\u0635\u064e\u0628\u065e \u0648\u064e\u0645\u064e\u0627 \u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1\u0647\u064e\u0627 \u0628\u0650\u0645\u064f\u062e\u06e1\u0631\u064e\u062c\u0650\u064a\u0646\u064e",translation:"Mereka tidak merasa lelah di dalamnya dan mereka tidak akan dikeluarkan darinya"},{id:49,text:"\u06de\u0646\u064e\u0628\u0651\u0650\u0626\u06e1 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a\u0653 \u0623\u064e\u0646\u0651\u0650\u064a\u0653 \u0623\u064e\u0646\u064e\u0627 \u0671\u0644\u06e1\u063a\u064e\u0641\u064f\u0648\u0631\u064f \u0671\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",translation:"Kabarkanlah kepada hamba-hamba-Ku, bahwa Akulah Yang Maha Pengampun, Maha Penyayang"},{id:50,text:"\u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u0650\u064a \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0671\u0644\u06e1\u0623\u064e\u0644\u0650\u064a\u0645\u064f",translation:"dan sesungguhnya azab-Ku adalah azab yang sangat pedih"},{id:51,text:"\u0648\u064e\u0646\u064e\u0628\u0651\u0650\u0626\u06e1\u0647\u064f\u0645\u06e1 \u0639\u064e\u0646 \u0636\u064e\u064a\u06e1\u0641\u0650 \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064e",translation:"Dan kabarkanlah (Muhammad) kepada mereka tentang tamu Ibrahim (malaikat)"},{id:52,text:"\u0625\u0650\u0630\u06e1 \u062f\u064e\u062e\u064e\u0644\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0641\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0633\u064e\u0644\u064e\u0670\u0645\u0657\u0627 \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e\u0627 \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u0648\u064e\u062c\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Ketika mereka masuk ke tempatnya, lalu mereka mengucapkan, \"Sal\u0101m.\" Dia (Ibrahim) berkata, \"kami benar-benar merasa takut kepadamu"},{id:53,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u062a\u064e\u0648\u06e1\u062c\u064e\u0644\u06e1 \u0625\u0650\u0646\u0651\u064e\u0627 \u0646\u064f\u0628\u064e\u0634\u0651\u0650\u0631\u064f\u0643\u064e \u0628\u0650\u063a\u064f\u0644\u064e\u0670\u0645\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u0656",translation:"(Mereka) berkata, \"Janganlah engkau merasa takut, sesungguhnya kami memberi kabar gembira kepadamu dengan (kelahiran seorang) anak laki-laki (yang akan menjadi) orang yang pandai (Ishak)"},{id:54,text:"\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0628\u064e\u0634\u0651\u064e\u0631\u06e1\u062a\u064f\u0645\u064f\u0648\u0646\u0650\u064a \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0646 \u0645\u0651\u064e\u0633\u0651\u064e\u0646\u0650\u064a\u064e \u0671\u0644\u06e1\u0643\u0650\u0628\u064e\u0631\u064f \u0641\u064e\u0628\u0650\u0645\u064e \u062a\u064f\u0628\u064e\u0634\u0651\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Dia (Ibrahim) berkata, \"Benarkah kamu memberi kabar gembira kepadaku padahal usiaku telah lanjut, lalu (dengan cara) bagaimana kamu memberi (kabar gembira) tersebut"},{id:55,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0628\u064e\u0634\u0651\u064e\u0631\u06e1\u0646\u064e\u0670\u0643\u064e \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0646 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0642\u064e\u0670\u0646\u0650\u0637\u0650\u064a\u0646\u064e",translation:"(Mereka) menjawab, \"Kami menyampaikan kabar gembira kepadamu dengan benar, maka janganlah engkau termasuk orang yang berputus asa"},{id:56,text:"\u0642\u064e\u0627\u0644\u064e \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0642\u06e1\u0646\u064e\u0637\u064f \u0645\u0650\u0646 \u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0629\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0636\u0651\u064e\u0627\u0653\u0644\u0651\u064f\u0648\u0646\u064e",translation:"Dia (Ibrahim) berkata, \"Tidak ada yang berputus asa dari rahmat Tuhannya, kecuali orang yang sesat"},{id:57,text:"\u0642\u064e\u0627\u0644\u064e \u0641\u064e\u0645\u064e\u0627 \u062e\u064e\u0637\u06e1\u0628\u064f\u0643\u064f\u0645\u06e1 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u06e1\u0645\u064f\u0631\u06e1\u0633\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dia (Ibrahim) berkata, \"Apakah perkara pentingmu, wahai para utusan"},{id:58,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0623\u064f\u0631\u06e1\u0633\u0650\u0644\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u06e1\u0645\u0656 \u0645\u0651\u064f\u062c\u06e1\u0631\u0650\u0645\u0650\u064a\u0646\u064e",translation:"(Mereka) menjawab, \"Sesungguhnya kami diutus kepada kaum yang berdosa"},{id:59,text:"\u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0621\u064e\u0627\u0644\u064e \u0644\u064f\u0648\u0637\u064d \u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0645\u064f\u0646\u064e\u062c\u0651\u064f\u0648\u0647\u064f\u0645\u06e1 \u0623\u064e\u062c\u06e1\u0645\u064e\u0639\u0650\u064a\u0646\u064e",translation:"kecuali para pengikut Lu\u1e6d. Sesungguhnya kami pasti menyelamatkan mereka semuanya"},{id:60,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0645\u06e1\u0631\u064e\u0623\u064e\u062a\u064e\u0647\u064f\u06e5 \u0642\u064e\u062f\u0651\u064e\u0631\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0647\u064e\u0627 \u0644\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u063a\u064e\u0670\u0628\u0650\u0631\u0650\u064a\u0646\u064e",translation:"kecuali istrinya, kami telah menentukan, bahwa dia termasuk orang yang tertinggal (bersama orang kafir lainnya)"},{id:61,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e \u0621\u064e\u0627\u0644\u064e \u0644\u064f\u0648\u0637\u064d \u0671\u0644\u06e1\u0645\u064f\u0631\u06e1\u0633\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Maka ketika utusan itu datang kepada para pengikut Lu\u1e6d"},{id:62,text:"\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0642\u064e\u0648\u06e1\u0645\u065e \u0645\u0651\u064f\u0646\u0643\u064e\u0631\u064f\u0648\u0646\u064e",translation:"dia (Lu\u1e6d) berkata, \"Sesungguhnya kamu orang yang tidak kami kenal"},{id:63,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0628\u064e\u0644\u06e1 \u062c\u0650\u0626\u06e1\u0646\u064e\u0670\u0643\u064e \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0647\u0650 \u064a\u064e\u0645\u06e1\u062a\u064e\u0631\u064f\u0648\u0646\u064e",translation:"(Para utusan) menjawab, \"Sebenarnya kami ini datang kepadamu membawa azab yang selalu mereka dustakan"},{id:64,text:"\u0648\u064e\u0623\u064e\u062a\u064e\u064a\u06e1\u0646\u064e\u0670\u0643\u064e \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0635\u064e\u0670\u062f\u0650\u0642\u064f\u0648\u0646\u064e",translation:"Dan kami datang kepadamu membawa kebenaran dan sungguh, kami orang yang benar"},{id:65,text:"\u0641\u064e\u0623\u064e\u0633\u06e1\u0631\u0650 \u0628\u0650\u0623\u064e\u0647\u06e1\u0644\u0650\u0643\u064e \u0628\u0650\u0642\u0650\u0637\u06e1\u0639\u0656 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u0650 \u0648\u064e\u0671\u062a\u0651\u064e\u0628\u0650\u0639\u06e1 \u0623\u064e\u062f\u06e1\u0628\u064e\u0670\u0631\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0644\u06e1\u062a\u064e\u0641\u0650\u062a\u06e1 \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u0623\u064e\u062d\u064e\u062f\u065e \u0648\u064e\u0671\u0645\u06e1\u0636\u064f\u0648\u0627\u0652 \u062d\u064e\u064a\u06e1\u062b\u064f \u062a\u064f\u0624\u06e1\u0645\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Maka pergilah kamu pada akhir malam beserta keluargamu, dan ikutilah mereka dari belakang! Jangan ada di antara kamu yang menoleh ke belakang dan teruskanlah perjalanan ke tempat yang diperintahkan kepadamu"},{id:66,text:"\u0648\u064e\u0642\u064e\u0636\u064e\u064a\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0631\u064e \u0623\u064e\u0646\u0651\u064e \u062f\u064e\u0627\u0628\u0650\u0631\u064e \u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650 \u0645\u064e\u0642\u06e1\u0637\u064f\u0648\u0639\u065e \u0645\u0651\u064f\u0635\u06e1\u0628\u0650\u062d\u0650\u064a\u0646\u064e",translation:"Dan telah Kami tetapkan kepadanya (Lu\u1e6d) keputusan itu, bahwa akhirnya mereka akan ditumpas habis pada waktu subuh"},{id:67,text:"\u0648\u064e\u062c\u064e\u0627\u0653\u0621\u064e \u0623\u064e\u0647\u06e1\u0644\u064f \u0671\u0644\u06e1\u0645\u064e\u062f\u0650\u064a\u0646\u064e\u0629\u0650 \u064a\u064e\u0633\u06e1\u062a\u064e\u0628\u06e1\u0634\u0650\u0631\u064f\u0648\u0646\u064e",translation:"(Dan datanglah penduduk kota itu437) (ke rumah Lu\u1e6d) dengan gembira (karena kedatangan tamu itu)"},{id:68,text:"\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650 \u0636\u064e\u064a\u06e1\u0641\u0650\u064a \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0641\u06e1\u0636\u064e\u062d\u064f\u0648\u0646\u0650",translation:"Dia (Lu\u1e6d) berkata, \"Sesungguhnya mereka adalah tamuku; maka jangan kamu mempermalukan aku"},{id:69,text:"\u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u062e\u06e1\u0632\u064f\u0648\u0646\u0650",translation:"dan bertakwalah kepada Allah dan janganlah kamu membuat aku terhina"},{id:70,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0648\u064e\u0644\u064e\u0645\u06e1 \u0646\u064e\u0646\u06e1\u0647\u064e\u0643\u064e \u0639\u064e\u0646\u0650 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"(Mereka) berkata, \"Bukankah kami telah melarangmu dari (melindungi) manusia"},{id:71,text:"\u0642\u064e\u0627\u0644\u064e \u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650 \u0628\u064e\u0646\u064e\u0627\u062a\u0650\u064a\u0653 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0641\u064e\u0670\u0639\u0650\u0644\u0650\u064a\u0646\u064e",translation:"Dia (Lu\u1e6d) berkata, \"Mereka itulah putri-putri (negeri)ku (nikahlah dengan mereka), jika kamu hendak berbuat"},{id:72,text:"\u0644\u064e\u0639\u064e\u0645\u06e1\u0631\u064f\u0643\u064e \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0641\u0650\u064a \u0633\u064e\u0643\u06e1\u0631\u064e\u062a\u0650\u0647\u0650\u0645\u06e1 \u064a\u064e\u0639\u06e1\u0645\u064e\u0647\u064f\u0648\u0646\u064e",translation:"(Allah berfirman), \"Demi umurmu439) (Muhammad), sungguh, mereka terombang-ambing dalam kemabukan (kesesatan)"},{id:73,text:"\u0641\u064e\u0623\u064e\u062e\u064e\u0630\u064e\u062a\u06e1\u0647\u064f\u0645\u064f \u0671\u0644\u0635\u0651\u064e\u064a\u06e1\u062d\u064e\u0629\u064f \u0645\u064f\u0634\u06e1\u0631\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Maka mereka dibinasakan oleh suara keras yang mengguntur, ketika matahari akan terbit"},{id:74,text:"\u0641\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0639\u064e\u0670\u0644\u0650\u064a\u064e\u0647\u064e\u0627 \u0633\u064e\u0627\u0641\u0650\u0644\u064e\u0647\u064e\u0627 \u0648\u064e\u0623\u064e\u0645\u06e1\u0637\u064e\u0631\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u062d\u0650\u062c\u064e\u0627\u0631\u064e\u0629\u0657 \u0645\u0651\u0650\u0646 \u0633\u0650\u062c\u0651\u0650\u064a\u0644\u064d",translation:"maka Kami jungkirbalikan (negeri itu) dan Kami hujani mereka dengan batu dari tanah yang keras"},{id:75,text:"\u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0623\u0653\u064a\u064e\u0670\u062a\u0656 \u0644\u0651\u0650\u0644\u06e1\u0645\u064f\u062a\u064e\u0648\u064e\u0633\u0651\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Sungguh, pada yang demikian itu benar-benar terdapat tanda-tanda (kekuasaan Allah) bagi orang yang memperhatikan tanda-tanda"},{id:76,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064e\u0627 \u0644\u064e\u0628\u0650\u0633\u064e\u0628\u0650\u064a\u0644\u0656 \u0645\u0651\u064f\u0642\u0650\u064a\u0645\u064d",translation:"dan sungguh, (negeri) itu benar-benar terletak di jalan yang masih tetap (dilalui manusia)"},{id:77,text:"\u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0623\u0653\u064a\u064e\u0629\u0657 \u0644\u0651\u0650\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Sungguh, pada yang demikian itu benar-benar terdapat tanda (kekuasaan Allah) bagi orang yang beriman"},{id:78,text:"\u0648\u064e\u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064e \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u06e1\u0623\u064e\u064a\u06e1\u0643\u064e\u0629\u0650 \u0644\u064e\u0638\u064e\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"(Dan sesungguhnya penduduk Aikah440) itu benar-benar kaum yang zalim"},{id:79,text:"\u0641\u064e\u0671\u0646\u062a\u064e\u0642\u064e\u0645\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u064e\u0627 \u0644\u064e\u0628\u0650\u0625\u0650\u0645\u064e\u0627\u0645\u0656 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u0656",translation:"maka Kami membinasakan mereka. Dan sesungguhnya kedua (negeri)441) itu terletak di satu jalur jalan raya"},{id:80,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u06e1\u062d\u0650\u062c\u06e1\u0631\u0650 \u0671\u0644\u06e1\u0645\u064f\u0631\u06e1\u0633\u064e\u0644\u0650\u064a\u0646\u064e",translation:"(Dan sesungguhnya penduduk negeri Hijr442) benar-benar telah mendustakan para rasul (mereka)"},{id:81,text:"\u0648\u064e\u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0641\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0639\u064e\u0646\u06e1\u0647\u064e\u0627 \u0645\u064f\u0639\u06e1\u0631\u0650\u0636\u0650\u064a\u0646\u064e",translation:"dan Kami telah mendatangkan kepada mereka tanda-tanda (kekuasaan) Kami, tetapi mereka selalu berpaling darinya"},{id:82,text:"\u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0646\u06e1\u062d\u0650\u062a\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u062c\u0650\u0628\u064e\u0627\u0644\u0650 \u0628\u064f\u064a\u064f\u0648\u062a\u064b\u0627 \u0621\u064e\u0627\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"dan mereka memahat rumah-rumah dari gunung batu, (yang didiami) dengan rasa aman"},{id:83,text:"\u0641\u064e\u0623\u064e\u062e\u064e\u0630\u064e\u062a\u06e1\u0647\u064f\u0645\u064f \u0671\u0644\u0635\u0651\u064e\u064a\u06e1\u062d\u064e\u0629\u064f \u0645\u064f\u0635\u06e1\u0628\u0650\u062d\u0650\u064a\u0646\u064e",translation:"Kemudian mereka dibinasakan oleh suara keras yang mengguntur pada pagi hari"},{id:84,text:"\u0641\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u063a\u06e1\u0646\u064e\u0649\u0670 \u0639\u064e\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0643\u06e1\u0633\u0650\u0628\u064f\u0648\u0646\u064e",translation:"sehingga tidak berguna bagi mereka, apa yang telah mereka usahakan"},{id:85,text:"\u0648\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u06e1\u0646\u064e\u0627 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650\u06d7 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064e \u0644\u064e\u0623\u0653\u062a\u0650\u064a\u064e\u0629\u065e\u06d6 \u0641\u064e\u0671\u0635\u06e1\u0641\u064e\u062d\u0650 \u0671\u0644\u0635\u0651\u064e\u0641\u06e1\u062d\u064e \u0671\u0644\u06e1\u062c\u064e\u0645\u0650\u064a\u0644\u064e",translation:"Dan Kami tidak menciptakan langit dan bumi serta apa yang ada di antara keduanya, melainkan dengan kebenaran. Dan sungguh, Kiamat pasti akan datang, maka maafkanlah (mereka) dengan cara yang baik"},{id:86,text:"\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u062e\u064e\u0644\u0651\u064e\u0640\u0670\u0642\u064f \u0671\u0644\u06e1\u0639\u064e\u0644\u0650\u064a\u0645\u064f",translation:"Sungguh, Tuhanmu, Dialah Yang Maha Pencipta, Maha Mengetahui"},{id:87,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0670\u0643\u064e \u0633\u064e\u0628\u06e1\u0639\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064e\u062b\u064e\u0627\u0646\u0650\u064a \u0648\u064e\u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u064e \u0671\u0644\u06e1\u0639\u064e\u0638\u0650\u064a\u0645\u064e",translation:"Dan sungguh, Kami telah memberikan kepadamu tujuh (ayat) yang (dibaca) berulang-ulang445) dan Alquran yang agung"},{id:88,text:"\u0644\u064e\u0627 \u062a\u064e\u0645\u064f\u062f\u0651\u064e\u0646\u0651\u064e \u0639\u064e\u064a\u06e1\u0646\u064e\u064a\u06e1\u0643\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0645\u064e\u062a\u0651\u064e\u0639\u06e1\u0646\u064e\u0627 \u0628\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u0657\u0627 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062d\u06e1\u0632\u064e\u0646\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0648\u064e\u0671\u062e\u06e1\u0641\u0650\u0636\u06e1 \u062c\u064e\u0646\u064e\u0627\u062d\u064e\u0643\u064e \u0644\u0650\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Jangan sekali-kali engkau (Muhammad) tujukan pandanganmu kepada kenikmatan hidup yang telah Kami berikan kepada beberapa golongan di antara mereka (orang kafir), dan jangan engkau bersedih hati terhadap mereka dan berendah hatilah engkau terhadap orang yang beriman"},{id:89,text:"\u0648\u064e\u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064e\u0646\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0630\u0650\u064a\u0631\u064f \u0671\u0644\u06e1\u0645\u064f\u0628\u0650\u064a\u0646\u064f",translation:"Dan katakanlah (Muhammad), \"Sesungguhnya aku adalah pemberi peringatan yang jelas"},{id:90,text:"\u0643\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0645\u064f\u0642\u06e1\u062a\u064e\u0633\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Sebagaimana (Kami telah memberi peringatan), Kami telah menurunkan (azab) kepada orang yang memilah-milah (Kitab Allah)"},{id:91,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062c\u064e\u0639\u064e\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u064e \u0639\u0650\u0636\u0650\u064a\u0646\u064e",translation:"(Yaitu) orang-orang447) yang telah menjadikan Alquran itu terbagi-bagi"},{id:92,text:"\u0641\u064e\u0648\u064e\u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0644\u064e\u0646\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u062c\u06e1\u0645\u064e\u0639\u0650\u064a\u0646\u064e",translation:"Maka demi Tuhanmu, Kami pasti akan menanyai mereka semua"},{id:93,text:"\u0639\u064e\u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"tentang apa yang telah mereka kerjakan dahulu"},{id:94,text:"\u0641\u064e\u0671\u0635\u06e1\u062f\u064e\u0639\u06e1 \u0628\u0650\u0645\u064e\u0627 \u062a\u064f\u0624\u06e1\u0645\u064e\u0631\u064f \u0648\u064e\u0623\u064e\u0639\u06e1\u0631\u0650\u0636\u06e1 \u0639\u064e\u0646\u0650 \u0671\u0644\u06e1\u0645\u064f\u0634\u06e1\u0631\u0650\u0643\u0650\u064a\u0646\u064e",translation:"Maka sampaikanlah (Muhammad) secara terang-terangan segala apa yang diperintahkan (kepadamu) dan berpalinglah dari orang yang musyrik"},{id:95,text:"\u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064e\u0641\u064e\u064a\u06e1\u0646\u064e\u0670\u0643\u064e \u0671\u0644\u06e1\u0645\u064f\u0633\u06e1\u062a\u064e\u0647\u06e1\u0632\u0650\u0621\u0650\u064a\u0646\u064e",translation:"Sesungguhnya Kami memelihara engkau (Muhammad) dari (kejahatan) orang yang memperolok-olokkan (engkau)"},{id:96,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062c\u06e1\u0639\u064e\u0644\u064f\u0648\u0646\u064e \u0645\u064e\u0639\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u064e\u0670\u0647\u064b\u0627 \u0621\u064e\u0627\u062e\u064e\u0631\u064e\u06da \u0641\u064e\u0633\u064e\u0648\u06e1\u0641\u064e \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"(yaitu) orang yang menganggap adanya tuhan selain Allah; mereka kelak akan mengetahui (akibatnya)"},{id:97,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0646\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0623\u064e\u0646\u0651\u064e\u0643\u064e \u064a\u064e\u0636\u0650\u064a\u0642\u064f \u0635\u064e\u062f\u06e1\u0631\u064f\u0643\u064e \u0628\u0650\u0645\u064e\u0627 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e",translation:"Dan sungguh, Kami mengetahui bahwa dadamu menjadi sempit disebabkan apa yang mereka ucapkan"},{id:98,text:"\u0641\u064e\u0633\u064e\u0628\u0651\u0650\u062d\u06e1 \u0628\u0650\u062d\u064e\u0645\u06e1\u062f\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0648\u064e\u0643\u064f\u0646 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0640\u0670\u062c\u0650\u062f\u0650\u064a\u0646\u064e",translation:"maka bertasbihlah dengan memuji Tuhanmu dan jadilah engkau di antara orang yang bersujud (salat)"},{id:99,text:"\u0648\u064e\u0671\u0639\u06e1\u0628\u064f\u062f\u06e1 \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e\u0643\u064e \u0671\u0644\u06e1\u064a\u064e\u0642\u0650\u064a\u0646\u064f",translation:"dan sembahlah Tuhanmu sampai yakin (ajal) datang kepadamu"}]},{id:16,name:"\u0627\u0644\u0646\u062d\u0644",transliteration:"An-Nahl",translation:"Lebah Madu",type:"meccan",total_verses:128,verses:[{id:1,text:"\u0623\u064e\u062a\u064e\u0649\u0670\u0653 \u0623\u064e\u0645\u06e1\u0631\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0633\u06e1\u062a\u064e\u0639\u06e1\u062c\u0650\u0644\u064f\u0648\u0647\u064f\u06da \u0633\u064f\u0628\u06e1\u062d\u064e\u0670\u0646\u064e\u0647\u064f\u06e5 \u0648\u064e\u062a\u064e\u0639\u064e\u0670\u0644\u064e\u0649\u0670 \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064f\u0634\u06e1\u0631\u0650\u0643\u064f\u0648\u0646\u064e",translation:"(Ketetapan Allah448) pasti datang, maka janganlah kamu meminta agar dipercepat (datang)nya. Mahasuci Allah dan Mahatinggi Dia dari apa yang mereka persekutukan"},{id:2,text:"\u064a\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u064f \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u064e \u0628\u0650\u0671\u0644\u0631\u0651\u064f\u0648\u062d\u0650 \u0645\u0650\u0646\u06e1 \u0623\u064e\u0645\u06e1\u0631\u0650\u0647\u0650\u06e6 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0645\u0650\u0646\u06e1 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0646\u06e1 \u0623\u064e\u0646\u0630\u0650\u0631\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646\u064e\u0627\u06e0 \u0641\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u0650",translation:"Dia menurunkan para malaikat membawa wahyu dengan perintah-Nya kepada siapa yang Dia kehendaki di antara hamba-hamba-Nya, (dengan berfirman) yaitu, \"Peringatkanlah (hamba-hamba-Ku), bahwa tidak ada tuhan selain Aku, maka hendaklah kamu bertakwa kepada-Ku"},{id:3,text:"\u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650\u06da \u062a\u064e\u0639\u064e\u0670\u0644\u064e\u0649\u0670 \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064f\u0634\u06e1\u0631\u0650\u0643\u064f\u0648\u0646\u064e",translation:"Dia menciptakan langit dan bumi dengan kebenaran. Mahatinggi Allah dari apa yang mereka persekutukan"},{id:4,text:"\u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064e \u0645\u0650\u0646 \u0646\u0651\u064f\u0637\u06e1\u0641\u064e\u0629\u0656 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0648\u064e \u062e\u064e\u0635\u0650\u064a\u0645\u065e \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u065e",translation:"Dia telah menciptakan manusia dari mani, ternyata dia menjadi pembantah yang nyata"},{id:5,text:"\u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0639\u064e\u0670\u0645\u064e \u062e\u064e\u0644\u064e\u0642\u064e\u0647\u064e\u0627\u06d6 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u062f\u0650\u0641\u06e1\u0621\u065e \u0648\u064e\u0645\u064e\u0646\u064e\u0670\u0641\u0650\u0639\u064f \u0648\u064e\u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u062a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f\u0648\u0646\u064e",translation:"Dan hewan ternak telah diciptakan-Nya untuk kamu, padanya ada (bulu) yang menghangatkan dan berbagai manfaat, dan sebagiannya kamu makan"},{id:6,text:"\u0648\u064e\u0644\u064e\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u062c\u064e\u0645\u064e\u0627\u0644\u064c \u062d\u0650\u064a\u0646\u064e \u062a\u064f\u0631\u0650\u064a\u062d\u064f\u0648\u0646\u064e \u0648\u064e\u062d\u0650\u064a\u0646\u064e \u062a\u064e\u0633\u06e1\u0631\u064e\u062d\u064f\u0648\u0646\u064e",translation:"Dan kamu memperoleh keindahan padanya, ketika kamu membawanya kembali ke kandang dan ketika kamu melepaskannya (ke tempat penggembalaan)"},{id:7,text:"\u0648\u064e\u062a\u064e\u062d\u06e1\u0645\u0650\u0644\u064f \u0623\u064e\u062b\u06e1\u0642\u064e\u0627\u0644\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649\u0670 \u0628\u064e\u0644\u064e\u062f\u0656 \u0644\u0651\u064e\u0645\u06e1 \u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u0628\u064e\u0670\u0644\u0650\u063a\u0650\u064a\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0634\u0650\u0642\u0651\u0650 \u0671\u0644\u06e1\u0623\u064e\u0646\u0641\u064f\u0633\u0650\u06da \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u06e1 \u0644\u064e\u0631\u064e\u0621\u064f\u0648\u0641\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u065e",translation:"Dan ia mengangkut beban-bebanmu ke suatu negeri yang kamu tidak sanggup mencapainya, kecuali dengan susah payah. Sungguh, Tuhanmu Maha Pengasih, Maha Penyayang"},{id:8,text:"\u0648\u064e\u0671\u0644\u06e1\u062e\u064e\u064a\u06e1\u0644\u064e \u0648\u064e\u0671\u0644\u06e1\u0628\u0650\u063a\u064e\u0627\u0644\u064e \u0648\u064e\u0671\u0644\u06e1\u062d\u064e\u0645\u0650\u064a\u0631\u064e \u0644\u0650\u062a\u064e\u0631\u06e1\u0643\u064e\u0628\u064f\u0648\u0647\u064e\u0627 \u0648\u064e\u0632\u0650\u064a\u0646\u064e\u0629\u0657\u06da \u0648\u064e\u064a\u064e\u062e\u06e1\u0644\u064f\u0642\u064f \u0645\u064e\u0627 \u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"dan (Dia telah menciptakan) kuda, bagal,449) dan keledai, untuk kamu tunggangi dan (menjadi) perhiasan. Allah menciptakan apa yang tidak kamu ketahui"},{id:9,text:"\u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0642\u064e\u0635\u06e1\u062f\u064f \u0671\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u0650 \u0648\u064e\u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u062c\u064e\u0627\u0653\u0626\u0650\u0631\u065e\u06da \u0648\u064e\u0644\u064e\u0648\u06e1 \u0634\u064e\u0627\u0653\u0621\u064e \u0644\u064e\u0647\u064e\u062f\u064e\u0649\u0670\u0643\u064f\u0645\u06e1 \u0623\u064e\u062c\u06e1\u0645\u064e\u0639\u0650\u064a\u0646\u064e",translation:"Dan hak Allah menerangkan jalan yang lurus, dan di antaranya ada (jalan) yang menyimpang. Dan jika Dia menghendaki, tentu Dia memberi petunjuk kamu semua (ke jalan yang benar)"},{id:10,text:"\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0645\u064e\u0627\u0653\u0621\u0657\u06d6 \u0644\u0651\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f \u0634\u064e\u0631\u064e\u0627\u0628\u065e \u0648\u064e\u0645\u0650\u0646\u06e1\u0647\u064f \u0634\u064e\u062c\u064e\u0631\u065e \u0641\u0650\u064a\u0647\u0650 \u062a\u064f\u0633\u0650\u064a\u0645\u064f\u0648\u0646\u064e",translation:"Dialah yang telah menurunkan air (hujan) dari langit untuk kamu, sebagiannya menjadi minuman dan sebagiannya (menyuburkan) tumbuhan, padanya kamu menggembalakan ternakmu"},{id:11,text:"\u064a\u064f\u0646\u06e2\u0628\u0650\u062a\u064f \u0644\u064e\u0643\u064f\u0645 \u0628\u0650\u0647\u0650 \u0671\u0644\u0632\u0651\u064e\u0631\u06e1\u0639\u064e \u0648\u064e\u0671\u0644\u0632\u0651\u064e\u064a\u06e1\u062a\u064f\u0648\u0646\u064e \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u062e\u0650\u064a\u0644\u064e \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0639\u06e1\u0646\u064e\u0670\u0628\u064e \u0648\u064e\u0645\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u0671\u0644\u062b\u0651\u064e\u0645\u064e\u0631\u064e\u0670\u062a\u0650\u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0623\u0653\u064a\u064e\u0629\u0657 \u0644\u0651\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064e\u062a\u064e\u0641\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dengan (air hujan) itu Dia menumbuhkan untuk kamu tanam-tanaman, zaitun, kurma, anggur dan segala macam buah-buahan. Sungguh, pada yang demikian itu benar-benar terdapat tanda (kebesaran Allah) bagi orang yang berpikir"},{id:12,text:"\u0648\u064e\u0633\u064e\u062e\u0651\u064e\u0631\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u064e \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u0648\u064e\u0671\u0644\u0634\u0651\u064e\u0645\u06e1\u0633\u064e \u0648\u064e\u0671\u0644\u06e1\u0642\u064e\u0645\u064e\u0631\u064e\u06d6 \u0648\u064e\u0671\u0644\u0646\u0651\u064f\u062c\u064f\u0648\u0645\u064f \u0645\u064f\u0633\u064e\u062e\u0651\u064e\u0631\u064e\u0670\u062a\u064f\u06e2 \u0628\u0650\u0623\u064e\u0645\u06e1\u0631\u0650\u0647\u0650\u06e6\u0653\u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0623\u0653\u064a\u064e\u0670\u062a\u0656 \u0644\u0651\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Dan Dia menundukkan malam dan siang, matahari dan bulan untukmu, dan bintang-bintang dikendalikan dengan perintah-Nya. Sungguh, pada yang demikian itu benar-benar terdapat tanda-tanda (kebesaran Allah) bagi orang yang mengerti"},{id:13,text:"\u0648\u064e\u0645\u064e\u0627 \u0630\u064e\u0631\u064e\u0623\u064e \u0644\u064e\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0645\u064f\u062e\u06e1\u062a\u064e\u0644\u0650\u0641\u064b\u0627 \u0623\u064e\u0644\u06e1\u0648\u064e\u0670\u0646\u064f\u0647\u064f\u06e5\u0653\u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0623\u0653\u064a\u064e\u0629\u0657 \u0644\u0651\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064e\u0630\u0651\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"dan (Dia juga mengendalikan) apa yang Dia ciptakan untukmu di bumi ini dengan berbagai jenis dan macam warnanya. Sungguh pada yang demikian itu benar-benar terdapat tanda (kebesaran Allah) bagi kaum yang mengambil pelajaran"},{id:14,text:"\u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0633\u064e\u062e\u0651\u064e\u0631\u064e \u0671\u0644\u06e1\u0628\u064e\u062d\u06e1\u0631\u064e \u0644\u0650\u062a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1\u0647\u064f \u0644\u064e\u062d\u06e1\u0645\u0657\u0627 \u0637\u064e\u0631\u0650\u064a\u0651\u0657\u0627 \u0648\u064e\u062a\u064e\u0633\u06e1\u062a\u064e\u062e\u06e1\u0631\u0650\u062c\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1\u0647\u064f \u062d\u0650\u0644\u06e1\u064a\u064e\u0629\u0657 \u062a\u064e\u0644\u06e1\u0628\u064e\u0633\u064f\u0648\u0646\u064e\u0647\u064e\u0627\u06d6 \u0648\u064e\u062a\u064e\u0631\u064e\u0649 \u0671\u0644\u06e1\u0641\u064f\u0644\u06e1\u0643\u064e \u0645\u064e\u0648\u064e\u0627\u062e\u0650\u0631\u064e \u0641\u0650\u064a\u0647\u0650 \u0648\u064e\u0644\u0650\u062a\u064e\u0628\u06e1\u062a\u064e\u063a\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0641\u064e\u0636\u06e1\u0644\u0650\u0647\u0650\u06e6 \u0648\u064e\u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u0634\u06e1\u0643\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Dan Dialah yang menundukkan lautan (untukmu), agar kamu dapat memakan daging yang segar (ikan) darinya, dan (dari lautan itu) kamu mengeluarkan perhiasan yang kamu pakai. Kamu (juga) melihat perahu berlayar padanya, dan agar kamu mencari sebagian karunia-Nya, dan agar kamu bersyukur"},{id:15,text:"\u0648\u064e\u0623\u064e\u0644\u06e1\u0642\u064e\u0649\u0670 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0631\u064e\u0648\u064e\u0670\u0633\u0650\u064a\u064e \u0623\u064e\u0646 \u062a\u064e\u0645\u0650\u064a\u062f\u064e \u0628\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u0657\u0627 \u0648\u064e\u0633\u064f\u0628\u064f\u0644\u0657\u0627 \u0644\u0651\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u0647\u06e1\u062a\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Dan Dia menancapkan gunung di bumi agar bumi itu tidak goncang bersama kamu, (dan Dia menciptakan) sungai-sungai dan jalan-jalan agar kamu mendapat petunjuk"},{id:16,text:"\u0648\u064e\u0639\u064e\u0644\u064e\u0670\u0645\u064e\u0670\u062a\u0656\u06da \u0648\u064e\u0628\u0650\u0671\u0644\u0646\u0651\u064e\u062c\u06e1\u0645\u0650 \u0647\u064f\u0645\u06e1 \u064a\u064e\u0647\u06e1\u062a\u064e\u062f\u064f\u0648\u0646\u064e",translation:"dan (Dia menciptakan) tanda-tanda (penunjuk jalan). Dan dengan bintang-bintang mereka mendapat petunjuk"},{id:17,text:"\u0623\u064e\u0641\u064e\u0645\u064e\u0646 \u064a\u064e\u062e\u06e1\u0644\u064f\u0642\u064f \u0643\u064e\u0645\u064e\u0646 \u0644\u0651\u064e\u0627 \u064a\u064e\u062e\u06e1\u0644\u064f\u0642\u064f\u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Maka apakah (Allah) yang menciptakan sama dengan yang tidak dapat menciptakan (sesuatu)? Mengapa kamu tidak mengambil pelajaran"},{id:18,text:"\u0648\u064e\u0625\u0650\u0646 \u062a\u064e\u0639\u064f\u062f\u0651\u064f\u0648\u0627\u0652 \u0646\u0650\u0639\u06e1\u0645\u064e\u0629\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0627 \u062a\u064f\u062d\u06e1\u0635\u064f\u0648\u0647\u064e\u0627\u0653\u06d7 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u065e",translation:"Dan jika kamu menghitung nikmat Allah, niscaya kamu tidak akan mampu menghitungnya. Sungguh, Allah benar-benar Maha Pengampun, Maha Penyayang"},{id:19,text:"\u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u062a\u064f\u0633\u0650\u0631\u0651\u064f\u0648\u0646\u064e \u0648\u064e\u0645\u064e\u0627 \u062a\u064f\u0639\u06e1\u0644\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Dan Allah mengetahui apa yang kamu rahasiakan dan apa yang kamu tampakkan"},{id:20,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0627 \u064a\u064e\u062e\u06e1\u0644\u064f\u0642\u064f\u0648\u0646\u064e \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627 \u0648\u064e\u0647\u064f\u0645\u06e1 \u064a\u064f\u062e\u06e1\u0644\u064e\u0642\u064f\u0648\u0646\u064e",translation:"Dan (berhala-berhala) yang mereka seru selain Allah, tidak dapat membuat sesuatu apa pun, sedang berhala-berhala itu (sendiri) dibuat orang"},{id:21,text:"\u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u062a\u064c \u063a\u064e\u064a\u06e1\u0631\u064f \u0623\u064e\u062d\u06e1\u064a\u064e\u0627\u0653\u0621\u0656\u06d6 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0634\u06e1\u0639\u064f\u0631\u064f\u0648\u0646\u064e \u0623\u064e\u064a\u0651\u064e\u0627\u0646\u064e \u064a\u064f\u0628\u06e1\u0639\u064e\u062b\u064f\u0648\u0646\u064e",translation:"(Berhala-berhala itu) benda mati, tidak hidup, dan berhala-berhala itu tidak mengetahui kapankah (penyembahnya) dibangkitkan"},{id:22,text:"\u0625\u0650\u0644\u064e\u0670\u0647\u064f\u0643\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0670\u0647\u065e \u0648\u064e\u0670\u062d\u0650\u062f\u065e\u06da \u0641\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645 \u0645\u0651\u064f\u0646\u0643\u0650\u0631\u064e\u0629\u065e \u0648\u064e\u0647\u064f\u0645 \u0645\u0651\u064f\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Tuhan kamu adalah Tuhan Yang Maha Esa. Maka orang yang tidak beriman kepada akhirat, hati mereka mengingkari (keesaan Allah), dan mereka adalah orang yang sombong"},{id:23,text:"\u0644\u064e\u0627 \u062c\u064e\u0631\u064e\u0645\u064e \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u064a\u064f\u0633\u0650\u0631\u0651\u064f\u0648\u0646\u064e \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0639\u06e1\u0644\u0650\u0646\u064f\u0648\u0646\u064e\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0671\u0644\u06e1\u0645\u064f\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Tidak diragukan lagi bahwa Allah mengetahui apa yang mereka rahasiakan dan apa yang mereka tampakkan. Sesungguhnya Dia tidak menyukai orang yang sombong"},{id:24,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u0627\u0630\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u06e1 \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0633\u064e\u0670\u0637\u0650\u064a\u0631\u064f \u0671\u0644\u06e1\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",translation:"Dan apabila dikatakan kepada mereka, \"Apa yang telah diturunkan Tuhanmu?\" Mereka menjawab, \"Dongeng-dongeng orang dahulu"},{id:25,text:"\u0644\u0650\u064a\u064e\u062d\u06e1\u0645\u0650\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0648\u06e1\u0632\u064e\u0627\u0631\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0627\u0645\u0650\u0644\u064e\u0629\u0657 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u0648\u064e\u0645\u0650\u0646\u06e1 \u0623\u064e\u0648\u06e1\u0632\u064e\u0627\u0631\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0636\u0650\u0644\u0651\u064f\u0648\u0646\u064e\u0647\u064f\u0645 \u0628\u0650\u063a\u064e\u064a\u06e1\u0631\u0650 \u0639\u0650\u0644\u06e1\u0645\u064d\u06d7 \u0623\u064e\u0644\u064e\u0627 \u0633\u064e\u0627\u0653\u0621\u064e \u0645\u064e\u0627 \u064a\u064e\u0632\u0650\u0631\u064f\u0648\u0646\u064e",translation:"(ucapan mereka) menyebabkan mereka pada hari Kiamat memikul dosa-dosanya sendiri secara sempurna, dan sebagian dosa-dosa orang yang mereka sesatkan yang tidak mengetahui sedikit pun (bahwa mereka disesatkan). Ingatlah, alangkah buruknya (dosa) yang mereka pikul itu"},{id:26,text:"\u0642\u064e\u062f\u06e1 \u0645\u064e\u0643\u064e\u0631\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u0645\u06e1 \u0641\u064e\u0623\u064e\u062a\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u064f\u0646\u06e1\u064a\u064e\u0670\u0646\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0642\u064e\u0648\u064e\u0627\u0639\u0650\u062f\u0650 \u0641\u064e\u062e\u064e\u0631\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u064f \u0671\u0644\u0633\u0651\u064e\u0642\u06e1\u0641\u064f \u0645\u0650\u0646 \u0641\u064e\u0648\u06e1\u0642\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0623\u064e\u062a\u064e\u0649\u0670\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0645\u0650\u0646\u06e1 \u062d\u064e\u064a\u06e1\u062b\u064f \u0644\u064e\u0627 \u064a\u064e\u0634\u06e1\u0639\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Sungguh, orang-orang yang sebelum mereka telah mengadakan tipu daya, maka Allah menghancurkan rumah-rumah mereka mulai dari pondasinya, lalu atap (rumah itu) jatuh menimpa mereka dari atas, dan siksa itu datang kepada mereka dari arah yang tidak mereka sadari"},{id:27,text:"\u062b\u064f\u0645\u0651\u064e \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u064a\u064f\u062e\u06e1\u0632\u0650\u064a\u0647\u0650\u0645\u06e1 \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0623\u064e\u064a\u06e1\u0646\u064e \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0653\u0621\u0650\u064a\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064f\u0634\u064e\u0640\u0670\u0653\u0642\u0651\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0647\u0650\u0645\u06e1\u06da \u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0639\u0650\u0644\u06e1\u0645\u064e \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u062e\u0650\u0632\u06e1\u064a\u064e \u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e \u0648\u064e\u0671\u0644\u0633\u0651\u064f\u0648\u0653\u0621\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Kemudian Allah menghinakan mereka pada hari Kiamat, dan berfirman, \"Di manakah sekutu-sekutu-Ku itu yang (karena membelanya) kamu selalu memusuhi mereka (nabi-nabi dan orang yang beriman)?\" Orang-orang yang diberi ilmu berkata;450) \"Sesungguhnya kehinaan dan azab hari ini ditimpakan kepada orang yang kafir"},{id:28,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u062a\u064e\u0648\u064e\u0641\u0651\u064e\u0649\u0670\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u064f \u0638\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0653 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u06e1\u06d6 \u0641\u064e\u0623\u064e\u0644\u06e1\u0642\u064e\u0648\u064f\u0627\u0652 \u0671\u0644\u0633\u0651\u064e\u0644\u064e\u0645\u064e \u0645\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0646\u064e\u0639\u06e1\u0645\u064e\u0644\u064f \u0645\u0650\u0646 \u0633\u064f\u0648\u0653\u0621\u0650\u06ed\u06da \u0628\u064e\u0644\u064e\u0649\u0670\u0653\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u064f\u06e2 \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"(yaitu) orang yang dicabut nyawanya oleh para malaikat dalam keadaan (berbuat) zalim kepada diri sendiri, lalu mereka menyerahkan diri (sambil berkata), \"Kami tidak pernah mengerjakan sesuatu kejahatan pun.\" (Malaikat menjawab), \"Pernah! Sesungguhnya Allah Maha Mengetahui apa yang telah kamu kerjakan"},{id:29,text:"\u0641\u064e\u0671\u062f\u06e1\u062e\u064f\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0628\u06e1\u0648\u064e\u0670\u0628\u064e \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u062e\u064e\u0670\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627\u06d6 \u0641\u064e\u0644\u064e\u0628\u0650\u0626\u06e1\u0633\u064e \u0645\u064e\u062b\u06e1\u0648\u064e\u0649 \u0671\u0644\u06e1\u0645\u064f\u062a\u064e\u0643\u064e\u0628\u0651\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Maka masukilah pintu-pintu neraka Jahanam, kamu kekal di dalamnya. Pasti itu seburuk-buruk tempat orang yang menyombongkan diri"},{id:30,text:"\u06de\u0648\u064e\u0642\u0650\u064a\u0644\u064e \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u062a\u0651\u064e\u0642\u064e\u0648\u06e1\u0627\u0652 \u0645\u064e\u0627\u0630\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u06e1\u06da \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u062e\u064e\u064a\u06e1\u0631\u0657\u0627\u06d7 \u0644\u0651\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0647\u064e\u0670\u0630\u0650\u0647\u0650 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u062d\u064e\u0633\u064e\u0646\u064e\u0629\u065e\u06da \u0648\u064e\u0644\u064e\u062f\u064e\u0627\u0631\u064f \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u062e\u064e\u064a\u06e1\u0631\u065e\u06da \u0648\u064e\u0644\u064e\u0646\u0650\u0639\u06e1\u0645\u064e \u062f\u064e\u0627\u0631\u064f \u0671\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",translation:"Dan kemudian dikatakan kepada orang yang bertakwa, \"Apakah yang telah diturunkan oleh Tuhanmu?\"Mereka menjawab, \"Kebaikan.\" Bagi orang yang berbuat baik di dunia ini mendapat (balasan) yang baik. Dan sesungguhnya negeri akhirat pasti lebih baik. Dan itulah sebaik-baik tempat bagi orang yang bertakwa"},{id:31,text:"\u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u064f \u0639\u064e\u062f\u06e1\u0646\u0656 \u064a\u064e\u062f\u06e1\u062e\u064f\u0644\u064f\u0648\u0646\u064e\u0647\u064e\u0627 \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0645\u0650\u0646 \u062a\u064e\u062d\u06e1\u062a\u0650\u0647\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u064f\u06d6 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u0648\u0646\u064e\u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064e\u062c\u06e1\u0632\u0650\u064a \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",translation:"(yaitu) surga-surga '\u0100dn yang mereka masuki, mengalir di bawahnya sungai-sungai, di dalam (surga) itu mereka mendapat segala apa yang diinginkan. Demikianlah Allah memberi balasan kepada orang yang bertakwa"},{id:32,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u062a\u064e\u0648\u064e\u0641\u0651\u064e\u0649\u0670\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u064f \u0637\u064e\u064a\u0651\u0650\u0628\u0650\u064a\u0646\u064e \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0633\u064e\u0644\u064e\u0670\u0645\u064c \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u064f \u0671\u062f\u06e1\u062e\u064f\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u064e \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"(yaitu) orang yang ketika diwafatkan oleh para malaikat dalam keadaan baik,451) mereka (para malaikat) mengatakan (kepada mereka), \"Sal\u0101mun 'alaikum, masuklah ke dalam surga karena apa yang telah kamu kerjakan"},{id:33,text:"\u0647\u064e\u0644\u06e1 \u064a\u064e\u0646\u0638\u064f\u0631\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u062a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u064f \u0623\u064e\u0648\u06e1 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e \u0623\u064e\u0645\u06e1\u0631\u064f \u0631\u064e\u0628\u0651\u0650\u0643\u064e\u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u0639\u064e\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u0645\u06e1\u06da \u0648\u064e\u0645\u064e\u0627 \u0638\u064e\u0644\u064e\u0645\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u0643\u064e\u0627\u0646\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0638\u06e1\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Tidak ada yang ditunggu mereka (orang kafir) selain datangnya para malaikat kepada mereka452) atau datangnya perintah Tuhanmu.453) Demikianlah yang telah diperbuat oleh orang-orang (kafir) sebelum mereka. Allah tidak menzalimi mereka, justru merekalah yang (selalu) menzalimi diri mereka sendiri"},{id:34,text:"\u0641\u064e\u0623\u064e\u0635\u064e\u0627\u0628\u064e\u0647\u064f\u0645\u06e1 \u0633\u064e\u064a\u0651\u0650\u0640\u0654\u064e\u0627\u062a\u064f \u0645\u064e\u0627 \u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0648\u064e\u062d\u064e\u0627\u0642\u064e \u0628\u0650\u0647\u0650\u0645 \u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6 \u064a\u064e\u0633\u06e1\u062a\u064e\u0647\u06e1\u0632\u0650\u0621\u064f\u0648\u0646\u064e",translation:"Maka mereka ditimpa azab (akibat) perbuatan mereka dan diliputi oleh azab yang dulu selalu mereka perolok-olokkan"},{id:35,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u0634\u06e1\u0631\u064e\u0643\u064f\u0648\u0627\u0652 \u0644\u064e\u0648\u06e1 \u0634\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0627 \u0639\u064e\u0628\u064e\u062f\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u06e6 \u0645\u0650\u0646 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0646\u0651\u064e\u062d\u06e1\u0646\u064f \u0648\u064e\u0644\u064e\u0627\u0653 \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0624\u064f\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u062d\u064e\u0631\u0651\u064e\u0645\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u06e6 \u0645\u0650\u0646 \u0634\u064e\u064a\u06e1\u0621\u0656\u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u0639\u064e\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u0645\u06e1\u06da \u0641\u064e\u0647\u064e\u0644\u06e1 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0631\u0651\u064f\u0633\u064f\u0644\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u06e1\u0628\u064e\u0644\u064e\u0670\u063a\u064f \u0671\u0644\u06e1\u0645\u064f\u0628\u0650\u064a\u0646\u064f",translation:"Dan orang musyrik berkata, \"Jika Allah menghendaki, niscaya kami tidak akan menyembah sesuatu apa pun selain Dia, baik kami maupun bapak-bapak kami, dan tidak (pula) kami mengharamkan sesuatu pun tanpa (izin)-Nya.\" Demikianlah yang diperbuat oleh orang sebelum mereka. Bukankah kewajiban para rasul hanya menyampaikan (amanat Allah) dengan jelas"},{id:36,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0628\u064e\u0639\u064e\u062b\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a \u0643\u064f\u0644\u0651\u0650 \u0623\u064f\u0645\u0651\u064e\u0629\u0656 \u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064b\u0627 \u0623\u064e\u0646\u0650 \u0671\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0671\u062c\u06e1\u062a\u064e\u0646\u0650\u0628\u064f\u0648\u0627\u0652 \u0671\u0644\u0637\u0651\u064e\u0640\u0670\u063a\u064f\u0648\u062a\u064e\u06d6 \u0641\u064e\u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0646\u06e1 \u0647\u064e\u062f\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0646\u06e1 \u062d\u064e\u0642\u0651\u064e\u062a\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0671\u0644\u0636\u0651\u064e\u0644\u064e\u0670\u0644\u064e\u0629\u064f\u06da \u0641\u064e\u0633\u0650\u064a\u0631\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0641\u064e\u0671\u0646\u0638\u064f\u0631\u064f\u0648\u0627\u0652 \u0643\u064e\u064a\u06e1\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0670\u0642\u0650\u0628\u064e\u0629\u064f \u0671\u0644\u06e1\u0645\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u0650\u064a\u0646\u064e",translation:"Dan sungguh, Kami telah mengutus seorang rasul untuk setiap umat (untuk menyerukan), \"Sembahlah Allah, dan jauhilah tagut,\" kemudian di antara mereka ada yang diberi petunjuk oleh Allah dan ada pula yang tetap dalam kesesatan. Maka berjalanlah kamu di bumi dan perhatikanlah bagaimana kesudahan orang yang mendustakan (rasul-rasul)"},{id:37,text:"\u0625\u0650\u0646 \u062a\u064e\u062d\u06e1\u0631\u0650\u0635\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0647\u064f\u062f\u064e\u0649\u0670\u0647\u064f\u0645\u06e1 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064e\u0647\u06e1\u062f\u0650\u064a \u0645\u064e\u0646 \u064a\u064f\u0636\u0650\u0644\u0651\u064f\u06d6 \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0646\u0651\u064e\u0640\u0670\u0635\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Jika engkau (Muhammad) sangat mengharapkan agar mereka mendapat petunjuk, maka sesungguhnya Allah tidak akan memberi petunjuk kepada orang yang disesatkan-Nya, dan mereka tidak mempunyai penolong"},{id:38,text:"\u0648\u064e\u0623\u064e\u0642\u06e1\u0633\u064e\u0645\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062c\u064e\u0647\u06e1\u062f\u064e \u0623\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u0650\u0647\u0650\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0628\u06e1\u0639\u064e\u062b\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0646 \u064a\u064e\u0645\u064f\u0648\u062a\u064f\u06da \u0628\u064e\u0644\u064e\u0649\u0670 \u0648\u064e\u0639\u06e1\u062f\u064b\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u062d\u064e\u0642\u0651\u0657\u0627 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan mereka bersumpah atas (nama) Allah dengan sumpah yang sungguh-sungguh, \"Allah tidak akan membangkitkan orang yang mati.\" Tidak demikian (pasti Allah akan membangkitkannya), sebagai suatu janji yang benar dari-Nya, tetapi kebanyakan manusia tidak mengetahui"},{id:39,text:"\u0644\u0650\u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064e\u062e\u06e1\u062a\u064e\u0644\u0650\u0641\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0647\u0650 \u0648\u064e\u0644\u0650\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0643\u064e\u0670\u0630\u0650\u0628\u0650\u064a\u0646\u064e",translation:"agar Dia menjelaskan kepada mereka apa yang mereka perselisihkan itu, dan agar orang kafir itu mengetahui bahwa mereka adalah orang yang berdusta"},{id:40,text:"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0642\u064e\u0648\u06e1\u0644\u064f\u0646\u064e\u0627 \u0644\u0650\u0634\u064e\u064a\u06e1\u0621\u064d \u0625\u0650\u0630\u064e\u0627\u0653 \u0623\u064e\u0631\u064e\u062f\u06e1\u0646\u064e\u0670\u0647\u064f \u0623\u064e\u0646 \u0646\u0651\u064e\u0642\u064f\u0648\u0644\u064e \u0644\u064e\u0647\u064f\u06e5 \u0643\u064f\u0646 \u0641\u064e\u064a\u064e\u0643\u064f\u0648\u0646\u064f",translation:"Sesungguhnya firman Kami terhadap sesuatu apabila Kami menghendakinya, Kami hanya mengatakan kepadanya, \"Jadilah!\" Maka jadilah sesuatu itu"},{id:41,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064e\u0627\u062c\u064e\u0631\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0645\u064e\u0627 \u0638\u064f\u0644\u0650\u0645\u064f\u0648\u0627\u0652 \u0644\u064e\u0646\u064f\u0628\u064e\u0648\u0651\u0650\u0626\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u062d\u064e\u0633\u064e\u0646\u064e\u0629\u0657\u06d6 \u0648\u064e\u0644\u064e\u0623\u064e\u062c\u06e1\u0631\u064f \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0623\u064e\u0643\u06e1\u0628\u064e\u0631\u064f\u06da \u0644\u064e\u0648\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan orang yang berhijrah karena Allah setelah mereka dizalimi, pasti Kami akan memberikan tempat yang baik kepada mereka di dunia. Dan pahala di akhirat pasti lebih besar, sekiranya mereka mengetahui"},{id:42,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0635\u064e\u0628\u064e\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u064a\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u064f\u0648\u0646\u064e",translation:"(yaitu) orang yang sabar dan hanya kepada Tuhan mereka bertawakal"},{id:43,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0631\u0650\u062c\u064e\u0627\u0644\u0657\u0627 \u0646\u0651\u064f\u0648\u062d\u0650\u064a\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1\u06d6 \u0641\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0647\u06e1\u0644\u064e \u0671\u0644\u0630\u0651\u0650\u0643\u06e1\u0631\u0650 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan Kami tidak mengutus sebelum engkau (Muhammad), melainkan orang laki-laki yang Kami beri wahyu kepada mereka; maka bertanyalah kepada orang yang mempunyai pengetahuan454) jika kamu tidak mengetahui"},{id:44,text:"\u0628\u0650\u0671\u0644\u06e1\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u0632\u0651\u064f\u0628\u064f\u0631\u0650\u06d7 \u0648\u064e\u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0671\u0644\u0630\u0651\u0650\u0643\u06e1\u0631\u064e \u0644\u0650\u062a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064e \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0645\u064e\u0627 \u0646\u064f\u0632\u0651\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0648\u064e\u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u062a\u064e\u0641\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"(mereka Kami utus) dengan membawa keterangan-keterangan (mukjizat) dan kitab-kitab. Dan Kami turunkan A\u017c-\u017bikr (Alquran) kepadamu, agar engkau menerangkan kepada manusia apa yang telah diturunkan kepada mereka455) dan agar mereka memikirkan"},{id:45,text:"\u0623\u064e\u0641\u064e\u0623\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u064e\u0643\u064e\u0631\u064f\u0648\u0627\u0652 \u0671\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0640\u0654\u064e\u0627\u062a\u0650 \u0623\u064e\u0646 \u064a\u064e\u062e\u06e1\u0633\u0650\u0641\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0647\u0650\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0623\u064e\u0648\u06e1 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0645\u0650\u0646\u06e1 \u062d\u064e\u064a\u06e1\u062b\u064f \u0644\u064e\u0627 \u064a\u064e\u0634\u06e1\u0639\u064f\u0631\u064f\u0648\u0646\u064e",translation:"maka apakah orang yang membuat tipu daya yang jahat itu, merasa aman (dari bencana) dibenamkannya bumi oleh Allah bersama mereka, atau (terhadap) datangnya siksa kepada mereka dari arah yang tidak mereka sadari"},{id:46,text:"\u0623\u064e\u0648\u06e1 \u064a\u064e\u0623\u06e1\u062e\u064f\u0630\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u062a\u064e\u0642\u064e\u0644\u0651\u064f\u0628\u0650\u0647\u0650\u0645\u06e1 \u0641\u064e\u0645\u064e\u0627 \u0647\u064f\u0645 \u0628\u0650\u0645\u064f\u0639\u06e1\u062c\u0650\u0632\u0650\u064a\u0646\u064e",translation:"atau Allah mengazab mereka pada waktu mereka dalam perjalanan; sehingga mereka tidak berdaya menolak (azab itu)"},{id:47,text:"\u0623\u064e\u0648\u06e1 \u064a\u064e\u0623\u06e1\u062e\u064f\u0630\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u062a\u064e\u062e\u064e\u0648\u0651\u064f\u0641\u0656 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u06e1 \u0644\u064e\u0631\u064e\u0621\u064f\u0648\u0641\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064c",translation:"atau Allah mengazab mereka dengan berangsur-angsur (sampai binasa).456) Maka sungguh, Tuhanmu Maha Pengasih, Maha Penyayang"},{id:48,text:"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0631\u064e\u0648\u06e1\u0627\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646 \u0634\u064e\u064a\u06e1\u0621\u0656 \u064a\u064e\u062a\u064e\u0641\u064e\u064a\u0651\u064e\u0624\u064f\u0627\u0652 \u0638\u0650\u0644\u064e\u0670\u0644\u064f\u0647\u064f\u06e5 \u0639\u064e\u0646\u0650 \u0671\u0644\u06e1\u064a\u064e\u0645\u0650\u064a\u0646\u0650 \u0648\u064e\u0671\u0644\u0634\u0651\u064e\u0645\u064e\u0627\u0653\u0626\u0650\u0644\u0650 \u0633\u064f\u062c\u0651\u064e\u062f\u0657\u0627 \u0644\u0651\u0650\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0647\u064f\u0645\u06e1 \u062f\u064e\u0670\u062e\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Dan apakah mereka tidak memperhatikan suatu benda yang diciptakan Allah, bayang-bayangnya berbolak-balik ke kanan dan ke kiri, dalam keadaan sujud kepada Allah, dan mereka (bersikap) rendah hati"},{id:49,text:"\u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650\u06e4 \u064a\u064e\u0633\u06e1\u062c\u064f\u062f\u064f\u06e4 \u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0645\u0650\u0646 \u062f\u064e\u0627\u0653\u0628\u0651\u064e\u0629\u0656 \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u064f \u0648\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Dan segala apa yang ada di langit dan apa yang ada di bumi hanya bersujud kepada Allah yaitu semua makhluk bergerak (bernyawa) dan (juga) para malaikat, dan mereka (malaikat) tidak menyombongkan diri"},{id:50,text:"\u064a\u064e\u062e\u064e\u0627\u0641\u064f\u0648\u0646\u064e \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0641\u064e\u0648\u06e1\u0642\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u064a\u064e\u0641\u06e1\u0639\u064e\u0644\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u064e\u0631\u064f\u0648\u0646\u064e\u06e9",translation:"Mereka takut kepada Tuhan yang (berkuasa) di atas mereka dan melaksanakan apa yang diperintahkan (kepada mereka)"},{id:51,text:"\u06de\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u0670\u0647\u064e\u064a\u06e1\u0646\u0650 \u0671\u062b\u06e1\u0646\u064e\u064a\u06e1\u0646\u0650\u06d6 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0647\u064f\u0648\u064e \u0625\u0650\u0644\u064e\u0670\u0647\u065e \u0648\u064e\u0670\u062d\u0650\u062f\u065e \u0641\u064e\u0625\u0650\u064a\u0651\u064e\u0640\u0670\u064a\u064e \u0641\u064e\u0671\u0631\u06e1\u0647\u064e\u0628\u064f\u0648\u0646\u0650",translation:"Dan Allah berfirman, \"Janganlah kamu menyembah dua tuhan; hanyalah Dia Tuhan Yang Maha Esa. Maka hendaklah kepada-Ku saja kamu takut"},{id:52,text:"\u0648\u064e\u0644\u064e\u0647\u064f\u06e5 \u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0644\u064e\u0647\u064f \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u064f \u0648\u064e\u0627\u0635\u0650\u0628\u064b\u0627\u06da \u0623\u064e\u0641\u064e\u063a\u064e\u064a\u06e1\u0631\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",translation:"Dan milik-Nya meliputi segala apa yang ada di langit dan di bumi, dan kepada-Nyalah (ibadah dan) ketaatan selama-lamanya. Mengapa kamu takut kepada selain Allah"},{id:53,text:"\u0648\u064e\u0645\u064e\u0627 \u0628\u0650\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0646\u0651\u0650\u0639\u06e1\u0645\u064e\u0629\u0656 \u0641\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0633\u0651\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0636\u0651\u064f\u0631\u0651\u064f \u0641\u064e\u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u062a\u064e\u062c\u06e1\u0640\u0654\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan segala nikmat yang ada padamu (datangnya) dari Allah, kemudian apabila kamu ditimpa kesengsaraan, maka kepada-Nyalah kamu meminta pertolongan"},{id:54,text:"\u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0630\u064e\u0627 \u0643\u064e\u0634\u064e\u0641\u064e \u0671\u0644\u0636\u0651\u064f\u0631\u0651\u064e \u0639\u064e\u0646\u0643\u064f\u0645\u06e1 \u0625\u0650\u0630\u064e\u0627 \u0641\u064e\u0631\u0650\u064a\u0642\u065e \u0645\u0651\u0650\u0646\u0643\u064f\u0645 \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u064a\u064f\u0634\u06e1\u0631\u0650\u0643\u064f\u0648\u0646\u064e",translation:"Kemudian apabila Dia telah menghilangkan bencana dari kamu, malah sebagian kamu mempersekutukan Tuhan dengan (yang lain)"},{id:55,text:"\u0644\u0650\u064a\u064e\u0643\u06e1\u0641\u064f\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0645\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1\u06da \u0641\u064e\u062a\u064e\u0645\u064e\u062a\u0651\u064e\u0639\u064f\u0648\u0627\u0652 \u0641\u064e\u0633\u064e\u0648\u06e1\u0641\u064e \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Biarlah mereka mengingkari nikmat yang telah Kami berikan kepada mereka; bersenang-senanglah kamu. Kelak kamu akan mengetahui (akibatnya)"},{id:56,text:"\u0648\u064e\u064a\u064e\u062c\u06e1\u0639\u064e\u0644\u064f\u0648\u0646\u064e \u0644\u0650\u0645\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0646\u064e\u0635\u0650\u064a\u0628\u0657\u0627 \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1\u06d7 \u062a\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u062a\u064f\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0646\u0651\u064e \u0639\u064e\u0645\u0651\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0641\u06e1\u062a\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan mereka menyediakan sebagian dari rezeki yang telah Kami berikan kepada mereka, untuk berhala-berhala yang mereka tidak mengetahui (kekuasaannya). Demi Allah, kamu pasti akan ditanyai tentang apa yang telah kamu ada-adakan"},{id:57,text:"\u0648\u064e\u064a\u064e\u062c\u06e1\u0639\u064e\u0644\u064f\u0648\u0646\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u0628\u064e\u0646\u064e\u0670\u062a\u0650 \u0633\u064f\u0628\u06e1\u062d\u064e\u0670\u0646\u064e\u0647\u064f\u06e5 \u0648\u064e\u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u0627 \u064a\u064e\u0634\u06e1\u062a\u064e\u0647\u064f\u0648\u0646\u064e",translation:"(Dan mereka menetapkan anak perempuan bagi Allah.457) Mahasuci Dia, sedang untuk mereka sendiri apa yang mereka sukai (anak laki-laki)"},{id:58,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0628\u064f\u0634\u0651\u0650\u0631\u064e \u0623\u064e\u062d\u064e\u062f\u064f\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0623\u064f\u0646\u062b\u064e\u0649\u0670 \u0638\u064e\u0644\u0651\u064e \u0648\u064e\u062c\u06e1\u0647\u064f\u0647\u064f\u06e5 \u0645\u064f\u0633\u06e1\u0648\u064e\u062f\u0651\u0657\u0627 \u0648\u064e\u0647\u064f\u0648\u064e \u0643\u064e\u0638\u0650\u064a\u0645\u065e",translation:"Padahal apabila seseorang dari mereka diberi kabar dengan (kelahiran) anak perempuan, wajahnya menjadi hitam (merah padam), dan dia sangat marah"},{id:59,text:"\u064a\u064e\u062a\u064e\u0648\u064e\u0670\u0631\u064e\u0649\u0670 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u0650 \u0645\u0650\u0646 \u0633\u064f\u0648\u0653\u0621\u0650 \u0645\u064e\u0627 \u0628\u064f\u0634\u0651\u0650\u0631\u064e \u0628\u0650\u0647\u0650\u06e6\u0653\u06da \u0623\u064e\u064a\u064f\u0645\u06e1\u0633\u0650\u0643\u064f\u0647\u064f\u06e5 \u0639\u064e\u0644\u064e\u0649\u0670 \u0647\u064f\u0648\u0646\u064d \u0623\u064e\u0645\u06e1 \u064a\u064e\u062f\u064f\u0633\u0651\u064f\u0647\u064f\u06e5 \u0641\u0650\u064a \u0671\u0644\u062a\u0651\u064f\u0631\u064e\u0627\u0628\u0650\u06d7 \u0623\u064e\u0644\u064e\u0627 \u0633\u064e\u0627\u0653\u0621\u064e \u0645\u064e\u0627 \u064a\u064e\u062d\u06e1\u0643\u064f\u0645\u064f\u0648\u0646\u064e",translation:"Dia bersembunyi dari orang banyak, disebabkan kabar buruk yang disampaikan kepadanya. Apakah dia akan memeliharanya dengan (menanggung) kehinaan atau akan membenamkannya ke dalam tanah (hidup-hidup)? Ingatlah alangkah buruknya (putusan) yang mereka tetapkan itu"},{id:60,text:"\u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0645\u064e\u062b\u064e\u0644\u064f \u0671\u0644\u0633\u0651\u064e\u0648\u06e1\u0621\u0650\u06d6 \u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u0645\u064e\u062b\u064e\u0644\u064f \u0671\u0644\u06e1\u0623\u064e\u0639\u06e1\u0644\u064e\u0649\u0670\u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0671\u0644\u06e1\u062d\u064e\u0643\u0650\u064a\u0645\u064f",translation:"Bagi orang-orang yang tidak beriman pada (kehidupan) akhirat, (mempunyai) sifat yang buruk; dan Allah mempunyai sifat Yang Mahatinggi. Dan Dia Mahaperkasa, Mahabijaksana"},{id:61,text:"\u0648\u064e\u0644\u064e\u0648\u06e1 \u064a\u064f\u0624\u064e\u0627\u062e\u0650\u0630\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0628\u0650\u0638\u064f\u0644\u06e1\u0645\u0650\u0647\u0650\u0645 \u0645\u0651\u064e\u0627 \u062a\u064e\u0631\u064e\u0643\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627 \u0645\u0650\u0646 \u062f\u064e\u0627\u0653\u0628\u0651\u064e\u0629\u0656 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u064a\u064f\u0624\u064e\u062e\u0651\u0650\u0631\u064f\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u062c\u064e\u0644\u0656 \u0645\u0651\u064f\u0633\u064e\u0645\u0651\u0657\u0649\u06d6 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e \u0623\u064e\u062c\u064e\u0644\u064f\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0640\u0654\u06e1\u062e\u0650\u0631\u064f\u0648\u0646\u064e \u0633\u064e\u0627\u0639\u064e\u0629\u0657 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0642\u06e1\u062f\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Dan kalau Allah menghukum manusia karena kezalimannya, niscaya tidak akan ada yang ditinggalkan-Nya (di bumi) dari makhluk yang melata sekali pun, tetapi Allah menangguhkan mereka sampai waktu yang sudah ditentukan. Maka apabila ajalnya tiba, mereka tidak dapat meminta penundaan atau percepatan sesaat pun"},{id:62,text:"\u0648\u064e\u064a\u064e\u062c\u06e1\u0639\u064e\u0644\u064f\u0648\u0646\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u064a\u064e\u0643\u06e1\u0631\u064e\u0647\u064f\u0648\u0646\u064e\u06da \u0648\u064e\u062a\u064e\u0635\u0650\u0641\u064f \u0623\u064e\u0644\u06e1\u0633\u0650\u0646\u064e\u062a\u064f\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0643\u064e\u0630\u0650\u0628\u064e \u0623\u064e\u0646\u0651\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u062d\u064f\u0633\u06e1\u0646\u064e\u0649\u0670\u06da \u0644\u064e\u0627 \u062c\u064e\u0631\u064e\u0645\u064e \u0623\u064e\u0646\u0651\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u064e \u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645 \u0645\u0651\u064f\u0641\u06e1\u0631\u064e\u0637\u064f\u0648\u0646\u064e",translation:"Dan mereka menetapkan bagi Allah apa yang mereka sendiri membencinya, dan lidah mereka mengucapkan kebohongan, bahwa sesungguhnya (segala) yang baik-baik untuk mereka. Tidaklah diragukan bahwa nerakalah bagi mereka, dan sesungguhnya mereka segera akan dimasukkan (ke dalamnya)"},{id:63,text:"\u062a\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064f\u0645\u064e\u0645\u0656 \u0645\u0651\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064e \u0641\u064e\u0632\u064e\u064a\u0651\u064e\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u064f \u0623\u064e\u0639\u06e1\u0645\u064e\u0670\u0644\u064e\u0647\u064f\u0645\u06e1 \u0641\u064e\u0647\u064f\u0648\u064e \u0648\u064e\u0644\u0650\u064a\u0651\u064f\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Demi Allah, sungguh Kami telah mengutus (rasul-rasul) kepada umat-umat sebelum engkau (Muhammad), tetapi setan menjadikan terasa indah bagi mereka perbuatan mereka (yang buruk), sehingga dia (setan) menjadi pemimpin mereka pada hari ini dan mereka akan mendapat azab yang sangat pedih"},{id:64,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0644\u0650\u062a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0671\u062e\u06e1\u062a\u064e\u0644\u064e\u0641\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0647\u0650 \u0648\u064e\u0647\u064f\u062f\u0657\u0649 \u0648\u064e\u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u0657 \u0644\u0651\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Dan Kami tidak menurunkan Kitab (Alquran) ini kepadamu (Muhammad), melainkan agar engkau dapat menjelaskan kepada mereka apa yang mereka perselisihkan itu, serta menjadi petunjuk dan rahmat bagi orang-orang yang beriman"},{id:65,text:"\u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0645\u064e\u0627\u0653\u0621\u0657 \u0641\u064e\u0623\u064e\u062d\u06e1\u064a\u064e\u0627 \u0628\u0650\u0647\u0650 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0628\u064e\u0639\u06e1\u062f\u064e \u0645\u064e\u0648\u06e1\u062a\u0650\u0647\u064e\u0627\u0653\u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0623\u0653\u064a\u064e\u0629\u0657 \u0644\u0651\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064e\u0633\u06e1\u0645\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Dan Allah menurunkan air (hujan) dari langit dan dengan air itu dihidupkan-Nya bumi yang tadinya sudah mati. Sungguh, pada yang demikian itu benar-benar terdapat tanda-tanda (kebesaran Allah) bagi orang-orang yang mendengarkan (pelajaran)"},{id:66,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0644\u064e\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0639\u064e\u0670\u0645\u0650 \u0644\u064e\u0639\u0650\u0628\u06e1\u0631\u064e\u0629\u0657\u06d6 \u0646\u0651\u064f\u0633\u06e1\u0642\u0650\u064a\u0643\u064f\u0645 \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u0641\u0650\u064a \u0628\u064f\u0637\u064f\u0648\u0646\u0650\u0647\u0650\u06e6 \u0645\u0650\u0646\u06e2 \u0628\u064e\u064a\u06e1\u0646\u0650 \u0641\u064e\u0631\u06e1\u062b\u0656 \u0648\u064e\u062f\u064e\u0645\u0656 \u0644\u0651\u064e\u0628\u064e\u0646\u064b\u0627 \u062e\u064e\u0627\u0644\u0650\u0635\u0657\u0627 \u0633\u064e\u0627\u0653\u0626\u0650\u063a\u0657\u0627 \u0644\u0651\u0650\u0644\u0634\u0651\u064e\u0640\u0670\u0631\u0650\u0628\u0650\u064a\u0646\u064e",translation:"Dan sungguh, pada hewan ternak itu benar-benar terdapat pelajaran bagi kamu. Kami memberimu minum dari apa yang ada dalam perutnya (berupa) susu murni antara kotoran dan darah, yang mudah ditelan bagi orang yang meminumnya"},{id:67,text:"\u0648\u064e\u0645\u0650\u0646 \u062b\u064e\u0645\u064e\u0631\u064e\u0670\u062a\u0650 \u0671\u0644\u0646\u0651\u064e\u062e\u0650\u064a\u0644\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0639\u06e1\u0646\u064e\u0670\u0628\u0650 \u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u06e1\u0647\u064f \u0633\u064e\u0643\u064e\u0631\u0657\u0627 \u0648\u064e\u0631\u0650\u0632\u06e1\u0642\u064b\u0627 \u062d\u064e\u0633\u064e\u0646\u064b\u0627\u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0623\u0653\u064a\u064e\u0629\u0657 \u0644\u0651\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Dan dari buah kurma dan anggur, kamu membuat minuman yang memabukkan dan rezeki yang baik. Sungguh, pada yang demikian itu benar-benar terdapat tanda (kebesaran Allah) bagi orang yang mengerti"},{id:68,text:"\u0648\u064e\u0623\u064e\u0648\u06e1\u062d\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0646\u0651\u064e\u062d\u06e1\u0644\u0650 \u0623\u064e\u0646\u0650 \u0671\u062a\u0651\u064e\u062e\u0650\u0630\u0650\u064a \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u062c\u0650\u0628\u064e\u0627\u0644\u0650 \u0628\u064f\u064a\u064f\u0648\u062a\u0657\u0627 \u0648\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u0634\u0651\u064e\u062c\u064e\u0631\u0650 \u0648\u064e\u0645\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u0639\u06e1\u0631\u0650\u0634\u064f\u0648\u0646\u064e",translation:"Dan Tuhanmu mengilhamkan kepada lebah, \"Buatlah sarang di gunung-gunung, di pohon-pohon kayu, dan di tempat-tempat yang dibikin manusia"},{id:69,text:"\u062b\u064f\u0645\u0651\u064e \u0643\u064f\u0644\u0650\u064a \u0645\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u0671\u0644\u062b\u0651\u064e\u0645\u064e\u0631\u064e\u0670\u062a\u0650 \u0641\u064e\u0671\u0633\u06e1\u0644\u064f\u0643\u0650\u064a \u0633\u064f\u0628\u064f\u0644\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u0650 \u0630\u064f\u0644\u064f\u0644\u0657\u0627\u06da \u064a\u064e\u062e\u06e1\u0631\u064f\u062c\u064f \u0645\u0650\u0646\u06e2 \u0628\u064f\u0637\u064f\u0648\u0646\u0650\u0647\u064e\u0627 \u0634\u064e\u0631\u064e\u0627\u0628\u065e \u0645\u0651\u064f\u062e\u06e1\u062a\u064e\u0644\u0650\u0641\u064c \u0623\u064e\u0644\u06e1\u0648\u064e\u0670\u0646\u064f\u0647\u064f\u06e5 \u0641\u0650\u064a\u0647\u0650 \u0634\u0650\u0641\u064e\u0627\u0653\u0621\u065e \u0644\u0651\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650\u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0623\u0653\u064a\u064e\u0629\u0657 \u0644\u0651\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064e\u062a\u064e\u0641\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"kemudian makanlah dari segala (macam) buah-buahan lalu tempuhlah jalan Tuhanmu yang telah dimudahkan (bagimu).\" Dari perut lebah itu keluar minuman (madu) yang bermacam-macam warnanya, di dalamnya terdapat obat yang menyembuhkan bagi manusia. Sungguh, pada yang demikian itu benar-benar terdapat tanda (kebesaran Allah) bagi orang yang berpikir"},{id:70,text:"\u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u062e\u064e\u0644\u064e\u0642\u064e\u0643\u064f\u0645\u06e1 \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u062a\u064e\u0648\u064e\u0641\u0651\u064e\u0649\u0670\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0645\u0650\u0646\u0643\u064f\u0645 \u0645\u0651\u064e\u0646 \u064a\u064f\u0631\u064e\u062f\u0651\u064f \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0631\u06e1\u0630\u064e\u0644\u0650 \u0671\u0644\u06e1\u0639\u064f\u0645\u064f\u0631\u0650 \u0644\u0650\u0643\u064e\u064a\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064e \u0628\u064e\u0639\u06e1\u062f\u064e \u0639\u0650\u0644\u06e1\u0645\u0656 \u0634\u064e\u064a\u06e1\u0640\u0654\u064b\u0627\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u065e \u0642\u064e\u062f\u0650\u064a\u0631\u065e",translation:"Dan Allah telah menciptakan kamu, kemudian mewafatkanmu, di antara kamu ada yang dikembalikan kepada usia yang tua renta (pikun), sehingga dia tidak mengetahui lagi sesuatu yang pernah diketahuinya. Sungguh, Allah Maha Mengetahui, Mahakuasa"},{id:71,text:"\u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0636\u0651\u064e\u0644\u064e \u0628\u064e\u0639\u06e1\u0636\u064e\u0643\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u06e1\u0636\u0656 \u0641\u0650\u064a \u0671\u0644\u0631\u0651\u0650\u0632\u06e1\u0642\u0650\u06da \u0641\u064e\u0645\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0641\u064f\u0636\u0651\u0650\u0644\u064f\u0648\u0627\u0652 \u0628\u0650\u0631\u064e\u0627\u0653\u062f\u0651\u0650\u064a \u0631\u0650\u0632\u06e1\u0642\u0650\u0647\u0650\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0645\u064e\u0644\u064e\u0643\u064e\u062a\u06e1 \u0623\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u064f\u0647\u064f\u0645\u06e1 \u0641\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u0650 \u0633\u064e\u0648\u064e\u0627\u0653\u0621\u064c\u06da \u0623\u064e\u0641\u064e\u0628\u0650\u0646\u0650\u0639\u06e1\u0645\u064e\u0629\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u062c\u06e1\u062d\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Dan Allah melebihkan sebagian kamu atas sebagian yang lain dalam hal rezeki, tetapi orang yang dilebihkan (rezekinya itu) tidak mau memberikan rezekinya kepada para hamba sahaya yang mereka miliki, sehingga mereka sama-sama (merasakan) rezeki itu. Mengapa mereka mengingkari nikmat Allah"},{id:72,text:"\u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u06e1 \u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u0657\u0627 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u0650\u0643\u064f\u0645 \u0628\u064e\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u062d\u064e\u0641\u064e\u062f\u064e\u0629\u0657 \u0648\u064e\u0631\u064e\u0632\u064e\u0642\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0637\u0651\u064e\u064a\u0651\u0650\u0628\u064e\u0670\u062a\u0650\u06da \u0623\u064e\u0641\u064e\u0628\u0650\u0671\u0644\u06e1\u0628\u064e\u0670\u0637\u0650\u0644\u0650 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0648\u064e\u0628\u0650\u0646\u0650\u0639\u06e1\u0645\u064e\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0647\u064f\u0645\u06e1 \u064a\u064e\u0643\u06e1\u0641\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Dan Allah menjadikan bagimu pasangan (suami atau istri) dari jenis kamu sendiri dan menjadikan anak dan cucu bagimu dari pasanganmu, serta memberimu rezeki dari yang baik. Mengapa mereka beriman kepada yang batil dan mengingkari nikmat Allah"},{id:73,text:"\u0648\u064e\u064a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0645\u06e1\u0644\u0650\u0643\u064f \u0644\u064e\u0647\u064f\u0645\u06e1 \u0631\u0650\u0632\u06e1\u0642\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u064e",translation:"dan mereka menyembah selain Allah, sesuatu yang sama sekali tidak dapat memberikan rezeki kepada mereka, dari langit dan bumi, dan tidak akan sanggup (berbuat apa pun)"},{id:74,text:"\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0636\u06e1\u0631\u0650\u0628\u064f\u0648\u0627\u0652 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u062b\u064e\u0627\u0644\u064e\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Maka janganlah kamu mengadakan sekutu-sekutu bagi Allah. Sungguh, Allah mengetahui, sedang kamu tidak mengetahui"},{id:75,text:"\u06de\u0636\u064e\u0631\u064e\u0628\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u062b\u064e\u0644\u064b\u0627 \u0639\u064e\u0628\u06e1\u062f\u0657\u0627 \u0645\u0651\u064e\u0645\u06e1\u0644\u064f\u0648\u0643\u0657\u0627 \u0644\u0651\u064e\u0627 \u064a\u064e\u0642\u06e1\u062f\u0650\u0631\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0648\u064e\u0645\u064e\u0646 \u0631\u0651\u064e\u0632\u064e\u0642\u06e1\u0646\u064e\u0670\u0647\u064f \u0645\u0650\u0646\u0651\u064e\u0627 \u0631\u0650\u0632\u06e1\u0642\u064b\u0627 \u062d\u064e\u0633\u064e\u0646\u0657\u0627 \u0641\u064e\u0647\u064f\u0648\u064e \u064a\u064f\u0646\u0641\u0650\u0642\u064f \u0645\u0650\u0646\u06e1\u0647\u064f \u0633\u0650\u0631\u0651\u0657\u0627 \u0648\u064e\u062c\u064e\u0647\u06e1\u0631\u064b\u0627\u06d6 \u0647\u064e\u0644\u06e1 \u064a\u064e\u0633\u06e1\u062a\u064e\u0648\u064f\u06e5\u0646\u064e\u06da \u0671\u0644\u06e1\u062d\u064e\u0645\u06e1\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650\u06da \u0628\u064e\u0644\u06e1 \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064f\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Allah membuat perumpamaan seorang hamba sahaya di bawah kekuasaan orang lain, yang tak berdaya untuk berbuat sesuatu dan seorang yang Kami beri rezeki yang baik, lalu dia menginfakkan sebagian rezeki itu secara sembunyi-sembunyi dan secara terang-terangan. Samakah mereka itu? Segala puji hanya bagi Allah, tetapi kebanyakan mereka tidak mengetahui"},{id:76,text:"\u0648\u064e\u0636\u064e\u0631\u064e\u0628\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u062b\u064e\u0644\u0657\u0627 \u0631\u0651\u064e\u062c\u064f\u0644\u064e\u064a\u06e1\u0646\u0650 \u0623\u064e\u062d\u064e\u062f\u064f\u0647\u064f\u0645\u064e\u0627\u0653 \u0623\u064e\u0628\u06e1\u0643\u064e\u0645\u064f \u0644\u064e\u0627 \u064a\u064e\u0642\u06e1\u062f\u0650\u0631\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0648\u064e\u0647\u064f\u0648\u064e \u0643\u064e\u0644\u0651\u064c \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0648\u06e1\u0644\u064e\u0649\u0670\u0647\u064f \u0623\u064e\u064a\u06e1\u0646\u064e\u0645\u064e\u0627 \u064a\u064f\u0648\u064e\u062c\u0651\u0650\u0647\u0647\u0651\u064f \u0644\u064e\u0627 \u064a\u064e\u0623\u06e1\u062a\u0650 \u0628\u0650\u062e\u064e\u064a\u06e1\u0631\u064d \u0647\u064e\u0644\u06e1 \u064a\u064e\u0633\u06e1\u062a\u064e\u0648\u0650\u064a \u0647\u064f\u0648\u064e \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0623\u06e1\u0645\u064f\u0631\u064f \u0628\u0650\u0671\u0644\u06e1\u0639\u064e\u062f\u06e1\u0644\u0650 \u0648\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0670\u0637\u0656 \u0645\u0651\u064f\u0633\u06e1\u062a\u064e\u0642\u0650\u064a\u0645\u0656",translation:"Dan Allah (juga) membuat perumpamaan, dua orang laki-laki, yang seorang bisu, tidak dapat berbuat sesuatu dan dia menjadi beban penanggungnya, ke mana saja dia di suruh (oleh penanggungnya itu), dia sama sekali tidak dapat mendatangkan suatu kebaikan. Samakah orang itu dengan orang yang menyuruh berbuat keadilan, dan dia berada di jalan yang lurus"},{id:77,text:"\u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u063a\u064e\u064a\u06e1\u0628\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06da \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0645\u06e1\u0631\u064f \u0671\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064e\u0644\u064e\u0645\u06e1\u062d\u0650 \u0671\u0644\u06e1\u0628\u064e\u0635\u064e\u0631\u0650 \u0623\u064e\u0648\u06e1 \u0647\u064f\u0648\u064e \u0623\u064e\u0642\u06e1\u0631\u064e\u0628\u064f\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0642\u064e\u062f\u0650\u064a\u0631\u065e",translation:"Dan milik Allah (segala) yang tersembunyi di langit dan di bumi. Urusan kejadian Kiamat itu, hanya seperti sekejap mata atau lebih cepat (lagi). Sesungguhnya Allah Mahakuasa atas segala sesuatu"},{id:78,text:"\u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u062e\u06e1\u0631\u064e\u062c\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e2 \u0628\u064f\u0637\u064f\u0648\u0646\u0650 \u0623\u064f\u0645\u0651\u064e\u0647\u064e\u0670\u062a\u0650\u0643\u064f\u0645\u06e1 \u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u06e1\u0639\u064e \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0628\u06e1\u0635\u064e\u0670\u0631\u064e \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0641\u06e1\u0640\u0654\u0650\u062f\u064e\u0629\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u0634\u06e1\u0643\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Dan Allah mengeluarkan kamu dari perut ibumu dalam keadaan tidak mengetahui apa pun, dan Dia memberimu pendengaran, penglihatan dan hati nurani, agar kamu bersyukur"},{id:79,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0631\u064e\u0648\u06e1\u0627\u0652 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0637\u0651\u064e\u064a\u06e1\u0631\u0650 \u0645\u064f\u0633\u064e\u062e\u0651\u064e\u0631\u064e\u0670\u062a\u0656 \u0641\u0650\u064a \u062c\u064e\u0648\u0651\u0650 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0645\u064e\u0627 \u064a\u064f\u0645\u06e1\u0633\u0650\u0643\u064f\u0647\u064f\u0646\u0651\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0623\u0653\u064a\u064e\u0670\u062a\u0656 \u0644\u0651\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Tidakkah mereka memperhatikan burung-burung yang dapat terbang di angkasa dengan mudah. Tidak ada yang menahannya selain Allah. Sungguh, pada yang demikian itu benar-benar terdapat tanda-tanda (kebesaran Allah) bagi orang-orang yang beriman"},{id:80,text:"\u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e2 \u0628\u064f\u064a\u064f\u0648\u062a\u0650\u0643\u064f\u0645\u06e1 \u0633\u064e\u0643\u064e\u0646\u0657\u0627 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u062c\u064f\u0644\u064f\u0648\u062f\u0650 \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0639\u064e\u0670\u0645\u0650 \u0628\u064f\u064a\u064f\u0648\u062a\u0657\u0627 \u062a\u064e\u0633\u06e1\u062a\u064e\u062e\u0650\u0641\u0651\u064f\u0648\u0646\u064e\u0647\u064e\u0627 \u064a\u064e\u0648\u06e1\u0645\u064e \u0638\u064e\u0639\u06e1\u0646\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u064a\u064e\u0648\u06e1\u0645\u064e \u0625\u0650\u0642\u064e\u0627\u0645\u064e\u062a\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0645\u0650\u0646\u06e1 \u0623\u064e\u0635\u06e1\u0648\u064e\u0627\u0641\u0650\u0647\u064e\u0627 \u0648\u064e\u0623\u064e\u0648\u06e1\u0628\u064e\u0627\u0631\u0650\u0647\u064e\u0627 \u0648\u064e\u0623\u064e\u0634\u06e1\u0639\u064e\u0627\u0631\u0650\u0647\u064e\u0627\u0653 \u0623\u064e\u062b\u064e\u0670\u062b\u0657\u0627 \u0648\u064e\u0645\u064e\u062a\u064e\u0670\u0639\u064b\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u062d\u0650\u064a\u0646\u0656",translation:"Dan Allah menjadikan rumah-rumah bagimu sebagai tempat tinggal dan Dia menjadikan bagimu rumah-rumah (kemah-kemah) dari kulit hewan ternak yang kamu merasa ringan (membawa)nya pada waktu kamu bepergian dan pada waktu kamu bermukim dan (dijadikan-Nya pula) dari bulu domba, bulu unta, dan bulu kambing, alat-alat rumah tangga dan kesenangan sampai waktu (tertentu)"},{id:81,text:"\u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u064e \u0638\u0650\u0644\u064e\u0670\u0644\u0657\u0627 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u062c\u0650\u0628\u064e\u0627\u0644\u0650 \u0623\u064e\u0643\u06e1\u0646\u064e\u0670\u0646\u0657\u0627 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u06e1 \u0633\u064e\u0631\u064e\u0670\u0628\u0650\u064a\u0644\u064e \u062a\u064e\u0642\u0650\u064a\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u062d\u064e\u0631\u0651\u064e \u0648\u064e\u0633\u064e\u0631\u064e\u0670\u0628\u0650\u064a\u0644\u064e \u062a\u064e\u0642\u0650\u064a\u0643\u064f\u0645 \u0628\u064e\u0623\u06e1\u0633\u064e\u0643\u064f\u0645\u06e1\u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064f\u062a\u0650\u0645\u0651\u064f \u0646\u0650\u0639\u06e1\u0645\u064e\u062a\u064e\u0647\u064f\u06e5 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064f\u0633\u06e1\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Dan Allah menjadikan tempat bernaung bagimu dari apa yang telah Dia ciptakan, Dia menjadikan bagimu tempat-tempat tinggal di gunung-gunung, dan Dia menjadikan pakaian bagimu yang memeliharamu dari panas dan pakaian (baju besi) yang memelihara kamu dalam peperangan. Demikian Allah menyempurnakan nikmat-Nya kepadamu agar kamu berserah diri (kepada-Nya)"},{id:82,text:"\u0641\u064e\u0625\u0650\u0646 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u06e1\u0627\u0652 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0671\u0644\u06e1\u0628\u064e\u0644\u064e\u0670\u063a\u064f \u0671\u0644\u06e1\u0645\u064f\u0628\u0650\u064a\u0646\u064f",translation:"Jika mereka berpaling, maka ketahuilah kewajiban yang dibebankan atasmu (Muhammad) hanyalah menyampaikan (amanat Allah) dengan terang"},{id:83,text:"\u064a\u064e\u0639\u06e1\u0631\u0650\u0641\u064f\u0648\u0646\u064e \u0646\u0650\u0639\u06e1\u0645\u064e\u062a\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0646\u0643\u0650\u0631\u064f\u0648\u0646\u064e\u0647\u064e\u0627 \u0648\u064e\u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064f\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Mereka mengetahui nikmat Allah, kemudian mereka mengingkarinya dan kebanyakan mereka adalah orang yang ingkar kepada Allah"},{id:84,text:"\u0648\u064e\u064a\u064e\u0648\u06e1\u0645\u064e \u0646\u064e\u0628\u06e1\u0639\u064e\u062b\u064f \u0645\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u0623\u064f\u0645\u0651\u064e\u0629\u0656 \u0634\u064e\u0647\u0650\u064a\u062f\u0657\u0627 \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0630\u064e\u0646\u064f \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u06e1 \u064a\u064f\u0633\u06e1\u062a\u064e\u0639\u06e1\u062a\u064e\u0628\u064f\u0648\u0646\u064e",translation:"Dan (ingatlah) pada hari (ketika) Kami bangkitkan seorang saksi (rasul) dari setiap umat, kemudian tidak diizinkan kepada orang yang kafir (untuk membela diri) dan tidak (pula) dibolehkan memohon ampunan"},{id:85,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0631\u064e\u0621\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0641\u064e\u0644\u064e\u0627 \u064a\u064f\u062e\u064e\u0641\u0651\u064e\u0641\u064f \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u06e1 \u064a\u064f\u0646\u0638\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan apabila orang zalim telah menyaksikan azab, maka mereka tidak mendapat keringanan dan tidak (pula) diberi penangguhan"},{id:86,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0631\u064e\u0621\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u0634\u06e1\u0631\u064e\u0643\u064f\u0648\u0627\u0652 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u06e1 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0653\u0624\u064f\u0646\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064f\u0646\u0651\u064e\u0627 \u0646\u064e\u062f\u06e1\u0639\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0643\u064e\u06d6 \u0641\u064e\u0623\u064e\u0644\u06e1\u0642\u064e\u0648\u06e1\u0627\u0652 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u064f \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0644\u064e \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0644\u064e\u0643\u064e\u0670\u0630\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Dan apabila orang yang mempersekutukan (Allah) melihat sekutu-sekutu mereka,460) mereka berkata, \"Ya Tuhan kami, mereka inilah sekutu-sekutu kami yang dahulu kami sembah selain Engkau.\" Lalu sekutu mereka menyatakan kepada mereka, \"Kamu benar-benar pendusta"},{id:87,text:"\u0648\u064e\u0623\u064e\u0644\u06e1\u0642\u064e\u0648\u06e1\u0627\u0652 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u064d \u0671\u0644\u0633\u0651\u064e\u0644\u064e\u0645\u064e\u06d6 \u0648\u064e\u0636\u064e\u0644\u0651\u064e \u0639\u064e\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0641\u06e1\u062a\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan pada hari itu mereka menyatakan tunduk kepada Allah dan lenyaplah segala yang mereka ada-adakan"},{id:88,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u0635\u064e\u062f\u0651\u064f\u0648\u0627\u0652 \u0639\u064e\u0646 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0632\u0650\u062f\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u0657\u0627 \u0641\u064e\u0648\u06e1\u0642\u064e \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064f\u0641\u06e1\u0633\u0650\u062f\u064f\u0648\u0646\u064e",translation:"Orang yang kafir dan menghalangi (manusia) dari jalan Allah, Kami tambahkan kepada mereka siksaan demi siksaan disebabkan mereka selalu berbuat kerusakan"},{id:89,text:"\u0648\u064e\u064a\u064e\u0648\u06e1\u0645\u064e \u0646\u064e\u0628\u06e1\u0639\u064e\u062b\u064f \u0641\u0650\u064a \u0643\u064f\u0644\u0651\u0650 \u0623\u064f\u0645\u0651\u064e\u0629\u0656 \u0634\u064e\u0647\u0650\u064a\u062f\u064b\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u06e1\u06d6 \u0648\u064e\u062c\u0650\u0626\u06e1\u0646\u064e\u0627 \u0628\u0650\u0643\u064e \u0634\u064e\u0647\u0650\u064a\u062f\u064b\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650\u06da \u0648\u064e\u0646\u064e\u0632\u0651\u064e\u0644\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u062a\u0650\u0628\u06e1\u064a\u064e\u0670\u0646\u0657\u0627 \u0644\u0651\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0648\u064e\u0647\u064f\u062f\u0657\u0649 \u0648\u064e\u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u0657 \u0648\u064e\u0628\u064f\u0634\u06e1\u0631\u064e\u0649\u0670 \u0644\u0650\u0644\u06e1\u0645\u064f\u0633\u06e1\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dan (ingatlah) pada hari (ketika) Kami bangkitkan pada setiap umat seorang saksi atas mereka dari mereka sendiri, dan Kami datangkan engkau (Muhammad) menjadi saksi atas mereka. Dan Kami turunkan Kitab (Alquran) kepadamu untuk menjelaskan segala sesuatu, sebagai petunjuk, serta rahmat dan kabar gembira bagi orang yang berserah diri (muslim)"},{id:90,text:"\u06de\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0623\u06e1\u0645\u064f\u0631\u064f \u0628\u0650\u0671\u0644\u06e1\u0639\u064e\u062f\u06e1\u0644\u0650 \u0648\u064e\u0671\u0644\u06e1\u0625\u0650\u062d\u06e1\u0633\u064e\u0670\u0646\u0650 \u0648\u064e\u0625\u0650\u064a\u062a\u064e\u0627\u0653\u064a\u0655\u0650 \u0630\u0650\u064a \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0628\u064e\u0649\u0670 \u0648\u064e\u064a\u064e\u0646\u06e1\u0647\u064e\u0649\u0670 \u0639\u064e\u0646\u0650 \u0671\u0644\u06e1\u0641\u064e\u062d\u06e1\u0634\u064e\u0627\u0653\u0621\u0650 \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0646\u0643\u064e\u0631\u0650 \u0648\u064e\u0671\u0644\u06e1\u0628\u064e\u063a\u06e1\u064a\u0650\u06da \u064a\u064e\u0639\u0650\u0638\u064f\u0643\u064f\u0645\u06e1 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Sesungguhnya Allah menyuruh (kamu) berlaku adil dan berbuat kebajikan, memberi bantuan kepada kerabat, dan Dia melarang (melakukan) perbuatan keji, kemungkaran dan permusuhan. Dia memberi pengajaran kepadamu agar kamu dapat mengambil pelajaran"},{id:91,text:"\u0648\u064e\u0623\u064e\u0648\u06e1\u0641\u064f\u0648\u0627\u0652 \u0628\u0650\u0639\u064e\u0647\u06e1\u062f\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0630\u064e\u0627 \u0639\u064e\u0670\u0647\u064e\u062f\u062a\u0651\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0646\u0642\u064f\u0636\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0623\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u064e \u0628\u064e\u0639\u06e1\u062f\u064e \u062a\u064e\u0648\u06e1\u0643\u0650\u064a\u062f\u0650\u0647\u064e\u0627 \u0648\u064e\u0642\u064e\u062f\u06e1 \u062c\u064e\u0639\u064e\u0644\u06e1\u062a\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0643\u064e\u0641\u0650\u064a\u0644\u064b\u0627\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u062a\u064e\u0641\u06e1\u0639\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan tepatilah janji dengan Allah apabila kamu berjanji dan janganlah kamu melanggar sumpah setelah diikrarkan, sedang kamu telah menjadikan Allah sebagai saksimu (terhadap sumpah itu). Sesungguhnya Allah mengetahui apa yang kamu perbuat"},{id:92,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u0643\u064e\u0671\u0644\u0651\u064e\u062a\u0650\u064a \u0646\u064e\u0642\u064e\u0636\u064e\u062a\u06e1 \u063a\u064e\u0632\u06e1\u0644\u064e\u0647\u064e\u0627 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0642\u064f\u0648\u0651\u064e\u0629\u064d \u0623\u064e\u0646\u0643\u064e\u0670\u062b\u0657\u0627 \u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0646\u064e \u0623\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u064e\u0643\u064f\u0645\u06e1 \u062f\u064e\u062e\u064e\u0644\u064e\u06e2\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u0646 \u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0623\u064f\u0645\u0651\u064e\u0629\u064c \u0647\u0650\u064a\u064e \u0623\u064e\u0631\u06e1\u0628\u064e\u0649\u0670 \u0645\u0650\u0646\u06e1 \u0623\u064f\u0645\u0651\u064e\u0629\u064d\u06da \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0628\u06e1\u0644\u064f\u0648\u0643\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0647\u0650\u06e6\u06da \u0648\u064e\u0644\u064e\u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0646\u0651\u064e \u0644\u064e\u0643\u064f\u0645\u06e1 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u0650 \u062a\u064e\u062e\u06e1\u062a\u064e\u0644\u0650\u0641\u064f\u0648\u0646\u064e",translation:"Dan janganlah kamu seperti seorang perempuan yang menguraikan benangnya yang sudah dipintal dengan kuat, menjadi cerai berai kembali. Kamu menjadikan sumpah (perjanjian)mu sebagai alat penipu di antaramu, disebabkan adanya satu golongan yang lebih banyak jumlahnya dari golongan yang lain.462) Allah hanya menguji kamu dengan hal itu, dan pasti pada hari Kiamat akan dijelaskan-Nya kepadamu apa yang dahulu kamu perselisihkan"},{id:93,text:"\u0648\u064e\u0644\u064e\u0648\u06e1 \u0634\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u062c\u064e\u0639\u064e\u0644\u064e\u0643\u064f\u0645\u06e1 \u0623\u064f\u0645\u0651\u064e\u0629\u0657 \u0648\u064e\u0670\u062d\u0650\u062f\u064e\u0629\u0657 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u064a\u064f\u0636\u0650\u0644\u0651\u064f \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0648\u064e\u064a\u064e\u0647\u06e1\u062f\u0650\u064a \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06da \u0648\u064e\u0644\u064e\u062a\u064f\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0646\u0651\u064e \u0639\u064e\u0645\u0651\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan jika Allah menghendaki niscaya Dia menjadikan kamu satu umat (saja), tetapi Dia menyesatkan siapa yang Dia kehendaki dan memberi petunjuk kepada siapa yang Dia kehendaki. Tetapi kamu pasti akan ditanya tentang apa yang telah kamu kerjakan"},{id:94,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u064e\u0643\u064f\u0645\u06e1 \u062f\u064e\u062e\u064e\u0644\u064e\u06e2\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e\u0643\u064f\u0645\u06e1 \u0641\u064e\u062a\u064e\u0632\u0650\u0644\u0651\u064e \u0642\u064e\u062f\u064e\u0645\u064f\u06e2 \u0628\u064e\u0639\u06e1\u062f\u064e \u062b\u064f\u0628\u064f\u0648\u062a\u0650\u0647\u064e\u0627 \u0648\u064e\u062a\u064e\u0630\u064f\u0648\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0633\u0651\u064f\u0648\u0653\u0621\u064e \u0628\u0650\u0645\u064e\u0627 \u0635\u064e\u062f\u064e\u062f\u062a\u0651\u064f\u0645\u06e1 \u0639\u064e\u0646 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0643\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u065e",translation:"Dan janganlah kamu jadikan sumpah-sumpahmu sebagai alat penipu di antaramu, yang menyebabkan kaki(mu) tergelincir setelah tegaknya (kokoh), dan kamu akan merasakan keburukan (di dunia) karena kamu menghalangi (manusia) dari jalan Allah, dan kamu akan mendapat azab yang besar"},{id:95,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0634\u06e1\u062a\u064e\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0639\u064e\u0647\u06e1\u062f\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062b\u064e\u0645\u064e\u0646\u0657\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627\u06da \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0647\u064f\u0648\u064e \u062e\u064e\u064a\u06e1\u0631\u065e \u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan janganlah kamu jual perjanjian (dengan) Allah dengan harga murah, karena sesungguhnya apa yang ada di sisi Allah lebih baik bagimu jika kamu mengetahui"},{id:96,text:"\u0645\u064e\u0627 \u0639\u0650\u0646\u062f\u064e\u0643\u064f\u0645\u06e1 \u064a\u064e\u0646\u0641\u064e\u062f\u064f \u0648\u064e\u0645\u064e\u0627 \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u064e\u0627\u0642\u0656\u06d7 \u0648\u064e\u0644\u064e\u0646\u064e\u062c\u06e1\u0632\u0650\u064a\u064e\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0635\u064e\u0628\u064e\u0631\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u062c\u06e1\u0631\u064e\u0647\u064f\u0645 \u0628\u0650\u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u0650 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Apa yang ada di sisimu akan lenyap, dan apa yang ada di sisi Allah adalah kekal. Dan Kami pasti akan memberi balasan kepada orang yang sabar dengan pahala yang lebih baik dari apa yang telah mereka kerjakan"},{id:97,text:"\u0645\u064e\u0646\u06e1 \u0639\u064e\u0645\u0650\u0644\u064e \u0635\u064e\u0670\u0644\u0650\u062d\u0657\u0627 \u0645\u0651\u0650\u0646 \u0630\u064e\u0643\u064e\u0631\u064d \u0623\u064e\u0648\u06e1 \u0623\u064f\u0646\u062b\u064e\u0649\u0670 \u0648\u064e\u0647\u064f\u0648\u064e \u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u065e \u0641\u064e\u0644\u064e\u0646\u064f\u062d\u06e1\u064a\u0650\u064a\u064e\u0646\u0651\u064e\u0647\u064f\u06e5 \u062d\u064e\u064a\u064e\u0648\u0670\u0629\u0657 \u0637\u064e\u064a\u0651\u0650\u0628\u064e\u0629\u0657\u06d6 \u0648\u064e\u0644\u064e\u0646\u064e\u062c\u06e1\u0632\u0650\u064a\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u062c\u06e1\u0631\u064e\u0647\u064f\u0645 \u0628\u0650\u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u0650 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"(Barangsiapa mengerjakan kebajikan, baik laki-laki maupun perempuan dalam keadaan beriman, maka pasti akan Kami berikan kepadanya kehidupan yang baik463) dan akan Kami beri balasan dengan pahala yang lebih baik dari apa yang telah mereka kerjakan"},{id:98,text:"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u064e\u0631\u064e\u0623\u06e1\u062a\u064e \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u064e \u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u0639\u0650\u0630\u06e1 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646\u064e \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u0650 \u0671\u0644\u0631\u0651\u064e\u062c\u0650\u064a\u0645\u0650",translation:"Maka apabila engkau (Muhammad) hendak membaca Alquran, mohonlah perlindungan kepada Allah dari setan yang terkutuk"},{id:99,text:"\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u064a\u06e1\u0633\u064e \u0644\u064e\u0647\u064f\u06e5 \u0633\u064f\u0644\u06e1\u0637\u064e\u0670\u0646\u064c \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u064a\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Sungguh, setan itu tidak akan berpengaruh terhadap orang yang beriman dan bertawakal kepada Tuhan"},{id:100,text:"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0633\u064f\u0644\u06e1\u0637\u064e\u0670\u0646\u064f\u0647\u064f\u06e5 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u06e1\u0646\u064e\u0647\u064f\u06e5 \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6 \u0645\u064f\u0634\u06e1\u0631\u0650\u0643\u064f\u0648\u0646\u064e",translation:"Pengaruhnya hanyalah terhadap orang yang menjadikannya pemimpin dan terhadap orang yang mempersekutukannya dengan Allah"},{id:101,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0628\u064e\u062f\u0651\u064e\u0644\u06e1\u0646\u064e\u0627\u0653 \u0621\u064e\u0627\u064a\u064e\u0629\u0657 \u0645\u0651\u064e\u0643\u064e\u0627\u0646\u064e \u0621\u064e\u0627\u064a\u064e\u0629\u0656 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u064a\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u064f \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064e \u0645\u064f\u0641\u06e1\u062a\u064e\u0631\u0650\u06ed\u06da \u0628\u064e\u0644\u06e1 \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064f\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan apabila Kami mengganti suatu ayat dengan ayat yang lain, dan Allah lebih mengetahui apa yang diturunkan-Nya, mereka berkata, \"Sesungguhnya engkau (Muhammad) hanyalah mengada-ada saja.\" Sebenarnya kebanyakan mereka tidak mengetahui"},{id:102,text:"\u0642\u064f\u0644\u06e1 \u0646\u064e\u0632\u0651\u064e\u0644\u064e\u0647\u064f\u06e5 \u0631\u064f\u0648\u062d\u064f \u0671\u0644\u06e1\u0642\u064f\u062f\u064f\u0633\u0650 \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064e \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0644\u0650\u064a\u064f\u062b\u064e\u0628\u0651\u0650\u062a\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0647\u064f\u062f\u0657\u0649 \u0648\u064e\u0628\u064f\u0634\u06e1\u0631\u064e\u0649\u0670 \u0644\u0650\u0644\u06e1\u0645\u064f\u0633\u06e1\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Katakanlah, \"Rohulkudus (Jibril) menurunkan Alquran itu dari Tuhanmu dengan kebenaran, untuk meneguhkan (hati) orang yang telah beriman, dan menjadi petunjuk serta kabar gembira bagi orang yang berserah diri (kepada Allah)"},{id:103,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0646\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064f\u0639\u064e\u0644\u0651\u0650\u0645\u064f\u0647\u064f\u06e5 \u0628\u064e\u0634\u064e\u0631\u065e\u06d7 \u0644\u0651\u0650\u0633\u064e\u0627\u0646\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u0644\u06e1\u062d\u0650\u062f\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0623\u064e\u0639\u06e1\u062c\u064e\u0645\u0650\u064a\u0651\u065e \u0648\u064e\u0647\u064e\u0670\u0630\u064e\u0627 \u0644\u0650\u0633\u064e\u0627\u0646\u064c \u0639\u064e\u0631\u064e\u0628\u0650\u064a\u0651\u065e \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u064c",translation:"Dan sesungguhnya Kami mengetahui bahwa mereka berkata, \"Sesungguhnya Alquran itu hanya diajarkan oleh seorang manusia kepadanya (Muhammad).\" Bahasa orang yang mereka tuduhkan (bahwa Muhammad belajar) kepadanya adalah bahasa 'Ajam,464) padahal ini (Alquran) adalah dalam bahasa Arab yang jelas"},{id:104,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0627 \u064a\u064e\u0647\u06e1\u062f\u0650\u064a\u0647\u0650\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064c",translation:"Sesungguhnya orang yang tidak beriman kepada ayat-ayat Allah (Alquran), Allah tidak akan memberi petunjuk kepada mereka dan mereka akan mendapat azab yang pedih"},{id:105,text:"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0641\u06e1\u062a\u064e\u0631\u0650\u064a \u0671\u0644\u06e1\u0643\u064e\u0630\u0650\u0628\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0648\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0643\u064e\u0670\u0630\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Sesungguhnya yang mengada-adakan kebohongan, hanyalah orang yang tidak beriman kepada ayat-ayat Allah, dan mereka itulah pembohong"},{id:106,text:"\u0645\u064e\u0646 \u0643\u064e\u0641\u064e\u0631\u064e \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0625\u0650\u064a\u0645\u064e\u0670\u0646\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u06e1 \u0623\u064f\u0643\u06e1\u0631\u0650\u0647\u064e \u0648\u064e\u0642\u064e\u0644\u06e1\u0628\u064f\u0647\u064f\u06e5 \u0645\u064f\u0637\u06e1\u0645\u064e\u0626\u0650\u0646\u0651\u064f\u06e2 \u0628\u0650\u0671\u0644\u06e1\u0625\u0650\u064a\u0645\u064e\u0670\u0646\u0650 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u0645\u0651\u064e\u0646 \u0634\u064e\u0631\u064e\u062d\u064e \u0628\u0650\u0671\u0644\u06e1\u0643\u064f\u0641\u06e1\u0631\u0650 \u0635\u064e\u062f\u06e1\u0631\u0657\u0627 \u0641\u064e\u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u063a\u064e\u0636\u064e\u0628\u065e \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u065e",translation:"Barang siapa kafir kepada Allah setelah dia beriman (dia mendapat kemurkaan Allah), kecuali orang yang dipaksa kafir padahal hatinya tetap tenang dalam beriman (dia tidak berdosa), tetapi orang yang melapangkan dadanya untuk kekafiran, maka kemurkaan Allah menimpanya dan mereka akan mendapat azab yang besar"},{id:107,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u064f \u0671\u0633\u06e1\u062a\u064e\u062d\u064e\u0628\u0651\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u064e \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064e\u0647\u06e1\u062f\u0650\u064a \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Yang demikian itu disebabkan karena mereka lebih mencintai kehidupan dunia daripada akhirat, dan Allah tidak memberi petunjuk kepada kaum yang kafir"},{id:108,text:"\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0637\u064e\u0628\u064e\u0639\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0633\u064e\u0645\u06e1\u0639\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0623\u064e\u0628\u06e1\u0635\u064e\u0670\u0631\u0650\u0647\u0650\u0645\u06e1\u06d6 \u0648\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u063a\u064e\u0670\u0641\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Mereka itulah orang yang hati, pendengaran dan penglihatannya telah dikunci oleh Allah. Mereka itulah orang yang lalai"},{id:109,text:"\u0644\u064e\u0627 \u062c\u064e\u0631\u064e\u0645\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u062e\u064e\u0670\u0633\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Pastilah mereka termasuk orang yang rugi di akhirat nanti"},{id:110,text:"\u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064e\u0627\u062c\u064e\u0631\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0645\u064e\u0627 \u0641\u064f\u062a\u0650\u0646\u064f\u0648\u0627\u0652 \u062b\u064f\u0645\u0651\u064e \u062c\u064e\u0670\u0647\u064e\u062f\u064f\u0648\u0627\u0652 \u0648\u064e\u0635\u064e\u0628\u064e\u0631\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u0647\u064e\u0627 \u0644\u064e\u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u065e",translation:"Kemudian Tuhanmu (pelindung) bagi orang yang berhijrah setelah menderita cobaan, kemudian mereka berjihad dan bersabar, sungguh, Tuhanmu setelah itu benar-benar Maha Pengampun, Maha Penyayang"},{id:111,text:"\u06de\u064a\u064e\u0648\u06e1\u0645\u064e \u062a\u064e\u0623\u06e1\u062a\u0650\u064a \u0643\u064f\u0644\u0651\u064f \u0646\u064e\u0641\u06e1\u0633\u0656 \u062a\u064f\u062c\u064e\u0670\u062f\u0650\u0644\u064f \u0639\u064e\u0646 \u0646\u0651\u064e\u0641\u06e1\u0633\u0650\u0647\u064e\u0627 \u0648\u064e\u062a\u064f\u0648\u064e\u0641\u0651\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u064f \u0646\u064e\u0641\u06e1\u0633\u0656 \u0645\u0651\u064e\u0627 \u0639\u064e\u0645\u0650\u0644\u064e\u062a\u06e1 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064f\u0638\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"(Ingatlah) pada hari (ketika) setiap orang datang untuk membela dirinya sendiri dan bagi setiap orang diberi (balasan) penuh sesuai dengan apa yang telah dikerjakannya, dan mereka tidak dizalimi (dirugikan)"},{id:112,text:"\u0648\u064e\u0636\u064e\u0631\u064e\u0628\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u062b\u064e\u0644\u0657\u0627 \u0642\u064e\u0631\u06e1\u064a\u064e\u0629\u0657 \u0643\u064e\u0627\u0646\u064e\u062a\u06e1 \u0621\u064e\u0627\u0645\u0650\u0646\u064e\u0629\u0657 \u0645\u0651\u064f\u0637\u06e1\u0645\u064e\u0626\u0650\u0646\u0651\u064e\u0629\u0657 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u0647\u064e\u0627 \u0631\u0650\u0632\u06e1\u0642\u064f\u0647\u064e\u0627 \u0631\u064e\u063a\u064e\u062f\u0657\u0627 \u0645\u0651\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u0645\u064e\u0643\u064e\u0627\u0646\u0656 \u0641\u064e\u0643\u064e\u0641\u064e\u0631\u064e\u062a\u06e1 \u0628\u0650\u0623\u064e\u0646\u06e1\u0639\u064f\u0645\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0623\u064e\u0630\u064e\u0670\u0642\u064e\u0647\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u0628\u064e\u0627\u0633\u064e \u0671\u0644\u06e1\u062c\u064f\u0648\u0639\u0650 \u0648\u064e\u0671\u0644\u06e1\u062e\u064e\u0648\u06e1\u0641\u0650 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0635\u06e1\u0646\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Dan Allah telah membuat suatu perumpamaan (dengan) suatu negeri yang dahulunya aman lagi tenteram, rezeki datang kepadanya melimpah ruah dari segenap tempat, tetapi (penduduk)nya mengingkari nikmat-nikmat Allah, karena itu Allah menimpakan kepada mereka bencana kelaparan dan ketakutan,465) disebabkan apa yang mereka perbuat"},{id:113,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u06e1 \u0631\u064e\u0633\u064f\u0648\u0644\u065e \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0641\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0647\u064f \u0641\u064e\u0623\u064e\u062e\u064e\u0630\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0648\u064e\u0647\u064f\u0645\u06e1 \u0638\u064e\u0670\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Dan sungguh, telah datang kepada mereka seorang rasul dari (kalangan) mereka sendiri, tetapi mereka mendustakannya, karena itu mereka ditimpa azab dan mereka adalah orang yang zalim"},{id:114,text:"\u0641\u064e\u0643\u064f\u0644\u064f\u0648\u0627\u0652 \u0645\u0650\u0645\u0651\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u062d\u064e\u0644\u064e\u0670\u0644\u0657\u0627 \u0637\u064e\u064a\u0651\u0650\u0628\u0657\u0627 \u0648\u064e\u0671\u0634\u06e1\u0643\u064f\u0631\u064f\u0648\u0627\u0652 \u0646\u0650\u0639\u06e1\u0645\u064e\u062a\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0625\u0650\u064a\u0651\u064e\u0627\u0647\u064f \u062a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0646\u064e",translation:"Maka makanlah yang halal lagi baik dari rezeki yang telah diberikan Allah kepadamu; dan syukurilah nikmat Allah, jika kamu hanya menyembah kepada-Nya"},{id:115,text:"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u062d\u064e\u0631\u0651\u064e\u0645\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064e\u064a\u06e1\u062a\u064e\u0629\u064e \u0648\u064e\u0671\u0644\u062f\u0651\u064e\u0645\u064e \u0648\u064e\u0644\u064e\u062d\u06e1\u0645\u064e \u0671\u0644\u06e1\u062e\u0650\u0646\u0632\u0650\u064a\u0631\u0650 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0647\u0650\u0644\u0651\u064e \u0644\u0650\u063a\u064e\u064a\u06e1\u0631\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u0650\u0647\u0650\u06e6\u06d6 \u0641\u064e\u0645\u064e\u0646\u0650 \u0671\u0636\u06e1\u0637\u064f\u0631\u0651\u064e \u063a\u064e\u064a\u06e1\u0631\u064e \u0628\u064e\u0627\u063a\u0656 \u0648\u064e\u0644\u064e\u0627 \u0639\u064e\u0627\u062f\u0656 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u065e",translation:"Sesungguhnya Allah hanya mengharamkan atasmu bangkai, darah, daging babi dan (hewan) yang disembelih dengan (menyebut nama) selain Allah, tetapi barangsiapa terpaksa (memakannya) bukan karena menginginkannya dan tidak (pula) melampaui batas, maka sungguh, Allah Maha Pengampun, Maha Penyayang"},{id:116,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627\u0652 \u0644\u0650\u0645\u064e\u0627 \u062a\u064e\u0635\u0650\u0641\u064f \u0623\u064e\u0644\u06e1\u0633\u0650\u0646\u064e\u062a\u064f\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0643\u064e\u0630\u0650\u0628\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u062d\u064e\u0644\u064e\u0670\u0644\u065e \u0648\u064e\u0647\u064e\u0670\u0630\u064e\u0627 \u062d\u064e\u0631\u064e\u0627\u0645\u065e \u0644\u0651\u0650\u062a\u064e\u0641\u06e1\u062a\u064e\u0631\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u0643\u064e\u0630\u0650\u0628\u064e\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0641\u06e1\u062a\u064e\u0631\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u0643\u064e\u0630\u0650\u0628\u064e \u0644\u064e\u0627 \u064a\u064f\u0641\u06e1\u0644\u0650\u062d\u064f\u0648\u0646\u064e",translation:"Dan janganlah kamu mengatakan terhadap apa yang disebut-sebut oleh lidahmu secara dusta \"Ini halal dan ini haram,\" untuk mengada-adakan kebohongan terhadap Allah. Sesungguhnya orang yang mengada-adakan kebohongan terhadap Allah tidak akan beruntung"},{id:117,text:"\u0645\u064e\u062a\u064e\u0670\u0639\u065e \u0642\u064e\u0644\u0650\u064a\u0644\u065e \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u065e",translation:"(Itu adalah) kesenangan yang sedikit; dan mereka akan mendapat azab yang pedih"},{id:118,text:"\u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064e\u0627\u062f\u064f\u0648\u0627\u0652 \u062d\u064e\u0631\u0651\u064e\u0645\u06e1\u0646\u064e\u0627 \u0645\u064e\u0627 \u0642\u064e\u0635\u064e\u0635\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f\u06d6 \u0648\u064e\u0645\u064e\u0627 \u0638\u064e\u0644\u064e\u0645\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u0643\u064e\u0627\u0646\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0638\u06e1\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Dan terhadap orang Yahudi, Kami haramkan apa yang telah Kami ceritakan dahulu kepadamu (Muhammad).466) Kami tidak menzalimi mereka, justru merekalah yang menzalimi diri sendiri"},{id:119,text:"\u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0633\u0651\u064f\u0648\u0653\u0621\u064e \u0628\u0650\u062c\u064e\u0647\u064e\u0670\u0644\u064e\u0629\u0656 \u062b\u064f\u0645\u0651\u064e \u062a\u064e\u0627\u0628\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0648\u064e\u0623\u064e\u0635\u06e1\u0644\u064e\u062d\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u0647\u064e\u0627 \u0644\u064e\u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064c",translation:"Kemudian, sesungguhnya Tuhanmu (mengampuni) orang yang mengerjakan kesalahan karena kebodohannya, kemudian mereka bertobat setelah itu dan memperbaiki (dirinya), sungguh, Tuhanmu setelah itu benar-benar Maha Pengampun, Maha Penyayang"},{id:120,text:"\u0625\u0650\u0646\u0651\u064e \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064e \u0643\u064e\u0627\u0646\u064e \u0623\u064f\u0645\u0651\u064e\u0629\u0657 \u0642\u064e\u0627\u0646\u0650\u062a\u0657\u0627 \u0644\u0651\u0650\u0644\u0651\u064e\u0647\u0650 \u062d\u064e\u0646\u0650\u064a\u0641\u0657\u0627 \u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0643\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0634\u06e1\u0631\u0650\u0643\u0650\u064a\u0646\u064e",translation:"Sungguh, Ibrahim adalah seorang imam (yang dapat dijadikan teladan), patuh kepada Allah dan \u1e25an\u012bf.467) Dan dia bukanlah termasuk orang musyrik (yang mempersekutukan Allah)"},{id:121,text:"\u0634\u064e\u0627\u0643\u0650\u0631\u0657\u0627 \u0644\u0651\u0650\u0623\u064e\u0646\u06e1\u0639\u064f\u0645\u0650\u0647\u0650\u06da \u0671\u062c\u06e1\u062a\u064e\u0628\u064e\u0649\u0670\u0647\u064f \u0648\u064e\u0647\u064e\u062f\u064e\u0649\u0670\u0647\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0670\u0637\u0656 \u0645\u0651\u064f\u0633\u06e1\u062a\u064e\u0642\u0650\u064a\u0645\u0656",translation:"dia mensyukuri nikmat-nikmat-Nya. Allah telah memilihnya dan menunjukinya ke jalan yang lurus"},{id:122,text:"\u0648\u064e\u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f \u0641\u0650\u064a \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u062d\u064e\u0633\u064e\u0646\u064e\u0629\u0657\u06d6 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0644\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u0650\u064a\u0646\u064e",translation:"Dan Kami berikan kepadanya kebaikan di dunia, dan sesungguhnya di akhirat dia termasuk orang yang saleh"},{id:123,text:"\u062b\u064f\u0645\u0651\u064e \u0623\u064e\u0648\u06e1\u062d\u064e\u064a\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0623\u064e\u0646\u0650 \u0671\u062a\u0651\u064e\u0628\u0650\u0639\u06e1 \u0645\u0650\u0644\u0651\u064e\u0629\u064e \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064e \u062d\u064e\u0646\u0650\u064a\u0641\u0657\u0627\u06d6 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0634\u06e1\u0631\u0650\u0643\u0650\u064a\u0646\u064e",translation:"Kemudian Kami wahyukan kepadamu (Muhammad), \"Ikutilah agama Ibrahim yang lurus, dan dia bukanlah termasuk orang yang musyrik"},{id:124,text:"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u062c\u064f\u0639\u0650\u0644\u064e \u0671\u0644\u0633\u0651\u064e\u0628\u06e1\u062a\u064f \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u062e\u06e1\u062a\u064e\u0644\u064e\u0641\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0647\u0650\u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0644\u064e\u064a\u064e\u062d\u06e1\u0643\u064f\u0645\u064f \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u0641\u0650\u064a\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0647\u0650 \u064a\u064e\u062e\u06e1\u062a\u064e\u0644\u0650\u0641\u064f\u0648\u0646\u064e",translation:"Sesungguhnya (menghormati) hari Sabtu468)hanya diwajibkan atas orang (Yahudi) yang memperselisihkannya. Dan sesungguhnya Tuhanmu pasti akan memberi keputusan di antara mereka pada hari Kiamat terhadap apa yang telah mereka perselisihkan"},{id:125,text:"\u0671\u062f\u06e1\u0639\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0628\u0650\u0671\u0644\u06e1\u062d\u0650\u0643\u06e1\u0645\u064e\u0629\u0650 \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u0639\u0650\u0638\u064e\u0629\u0650 \u0671\u0644\u06e1\u062d\u064e\u0633\u064e\u0646\u064e\u0629\u0650\u06d6 \u0648\u064e\u062c\u064e\u0670\u062f\u0650\u0644\u06e1\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u0651\u064e\u062a\u0650\u064a \u0647\u0650\u064a\u064e \u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064f\u06da \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0647\u064f\u0648\u064e \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0646 \u0636\u064e\u0644\u0651\u064e \u0639\u064e\u0646 \u0633\u064e\u0628\u0650\u064a\u0644\u0650\u0647\u0650\u06e6 \u0648\u064e\u0647\u064f\u0648\u064e \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0628\u0650\u0671\u0644\u06e1\u0645\u064f\u0647\u06e1\u062a\u064e\u062f\u0650\u064a\u0646\u064e",translation:"Serulah (manusia) kepada jalan Tuhanmu dengan hikmah469) dan pengajaran yang baik, dan berdebatlah dengan mereka dengan cara yang baik. Sesungguhnya Tuhanmu, Dialah yang lebih mengetahui siapa yang sesat dari jalan-Nya dan Dialah yang lebih mengetahui siapa yang mendapat petunjuk"},{id:126,text:"\u0648\u064e\u0625\u0650\u0646\u06e1 \u0639\u064e\u0627\u0642\u064e\u0628\u06e1\u062a\u064f\u0645\u06e1 \u0641\u064e\u0639\u064e\u0627\u0642\u0650\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0645\u0650\u062b\u06e1\u0644\u0650 \u0645\u064e\u0627 \u0639\u064f\u0648\u0642\u0650\u0628\u06e1\u062a\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u0644\u064e\u0626\u0650\u0646 \u0635\u064e\u0628\u064e\u0631\u06e1\u062a\u064f\u0645\u06e1 \u0644\u064e\u0647\u064f\u0648\u064e \u062e\u064e\u064a\u06e1\u0631\u065e \u0644\u0651\u0650\u0644\u0635\u0651\u064e\u0640\u0670\u0628\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan jika kamu membalas, maka balaslah dengan (balasan) yang sama dengan siksaan yang ditimpakan kepadamu. Tetapi jika kamu bersabar, sesungguhnya itulah yang lebih baik bagi orang yang sabar"},{id:127,text:"\u0648\u064e\u0671\u0635\u06e1\u0628\u0650\u0631\u06e1 \u0648\u064e\u0645\u064e\u0627 \u0635\u064e\u0628\u06e1\u0631\u064f\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062d\u06e1\u0632\u064e\u0646\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f \u0641\u0650\u064a \u0636\u064e\u064a\u06e1\u0642\u0656 \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u0645\u06e1\u0643\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Dan bersabarlah (Muhammad) dan kesabaranmu itu semata-mata dengan pertolongan Allah dan janganlah engkau bersedih hati terhadap (kekafiran) mereka dan jangan (pula) bersempit dada terhadap tipu daya yang mereka rencanakan"},{id:128,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064e\u0639\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u062a\u0651\u064e\u0642\u064e\u0648\u0627\u0652 \u0648\u0651\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645 \u0645\u0651\u064f\u062d\u06e1\u0633\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Sungguh, Allah beserta orang-orang yang bertakwa dan orang-orang yang berbuat kebaikan"}]},{id:17,name:"\u0627\u0644\u0625\u0633\u0631\u0627\u0621",transliteration:"Al-Isra",translation:"Perjalanan Malam",type:"meccan",total_verses:111,verses:[{id:1,text:"\u0633\u064f\u0628\u06e1\u062d\u064e\u0670\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064e\u0633\u06e1\u0631\u064e\u0649\u0670 \u0628\u0650\u0639\u064e\u0628\u06e1\u062f\u0650\u0647\u0650\u06e6 \u0644\u064e\u064a\u06e1\u0644\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064e\u0633\u06e1\u062c\u0650\u062f\u0650 \u0671\u0644\u06e1\u062d\u064e\u0631\u064e\u0627\u0645\u0650 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u0645\u064e\u0633\u06e1\u062c\u0650\u062f\u0650 \u0671\u0644\u06e1\u0623\u064e\u0642\u06e1\u0635\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0628\u064e\u0670\u0631\u064e\u0643\u06e1\u0646\u064e\u0627 \u062d\u064e\u0648\u06e1\u0644\u064e\u0647\u064f\u06e5 \u0644\u0650\u0646\u064f\u0631\u0650\u064a\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627\u0653\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0647\u064f\u0648\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u0650\u064a\u0639\u064f \u0671\u0644\u06e1\u0628\u064e\u0635\u0650\u064a\u0631\u064f",translation:"Mahasuci (Allah), yang telah memperjalankan hamba-Nya (Muhammad) pada malam hari dari Masjidil Haram ke Masjidil Aqsa yang telah Kami berkahi sekelilingnya470) agar Kami perlihatkan kepadanya sebagian tanda-tanda (kebesaran) Kami. Sesungguhnya Dia Maha Mendengar, Maha Melihat"},{id:2,text:"\u0648\u064e\u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f \u0647\u064f\u062f\u0657\u0649 \u0644\u0651\u0650\u0628\u064e\u0646\u0650\u064a\u0653 \u0625\u0650\u0633\u06e1\u0631\u064e\u0640\u0670\u0653\u0621\u0650\u064a\u0644\u064e \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u064a \u0648\u064e\u0643\u0650\u064a\u0644\u0657\u0627",translation:"Dan Kami berikan kepada Musa, Kitab (Taurat) dan Kami menjadikannya petunjuk bagi Bani Israil (dengan firman), \"Janganlah kamu mengambil (pelindung) selain Aku"},{id:3,text:"\u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u0629\u064e \u0645\u064e\u0646\u06e1 \u062d\u064e\u0645\u064e\u0644\u06e1\u0646\u064e\u0627 \u0645\u064e\u0639\u064e \u0646\u064f\u0648\u062d\u064d\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0628\u06e1\u062f\u0657\u0627 \u0634\u064e\u0643\u064f\u0648\u0631\u0657\u0627",translation:"(Wahai) keturunan orang yang Kami bawa bersama Nuh. Sesungguhnya dia (Nuh) adalah hamba (Allah) yang banyak bersyukur"},{id:4,text:"\u0648\u064e\u0642\u064e\u0636\u064e\u064a\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u0628\u064e\u0646\u0650\u064a\u0653 \u0625\u0650\u0633\u06e1\u0631\u064e\u0640\u0670\u0653\u0621\u0650\u064a\u0644\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0644\u064e\u062a\u064f\u0641\u06e1\u0633\u0650\u062f\u064f\u0646\u0651\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0645\u064e\u0631\u0651\u064e\u062a\u064e\u064a\u06e1\u0646\u0650 \u0648\u064e\u0644\u064e\u062a\u064e\u0639\u06e1\u0644\u064f\u0646\u0651\u064e \u0639\u064f\u0644\u064f\u0648\u0651\u0657\u0627 \u0643\u064e\u0628\u0650\u064a\u0631\u0657\u0627",translation:"Dan Kami tetapkan terhadap Bani Israil dalam Kitab itu, \"Kamu pasti akan berbuat kerusakan di bumi ini dua kali dan pasti kamu akan menyombongkan diri dengan kesombongan yang besar"},{id:5,text:"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e \u0648\u064e\u0639\u06e1\u062f\u064f \u0623\u064f\u0648\u0644\u064e\u0649\u0670\u0647\u064f\u0645\u064e\u0627 \u0628\u064e\u0639\u064e\u062b\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0639\u0650\u0628\u064e\u0627\u062f\u0657\u0627 \u0644\u0651\u064e\u0646\u064e\u0627\u0653 \u0623\u064f\u0648\u0652\u0644\u0650\u064a \u0628\u064e\u0623\u06e1\u0633\u0656 \u0634\u064e\u062f\u0650\u064a\u062f\u0656 \u0641\u064e\u062c\u064e\u0627\u0633\u064f\u0648\u0627\u0652 \u062e\u0650\u0644\u064e\u0670\u0644\u064e \u0671\u0644\u062f\u0651\u0650\u064a\u064e\u0627\u0631\u0650\u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0648\u064e\u0639\u06e1\u062f\u0657\u0627 \u0645\u0651\u064e\u0641\u06e1\u0639\u064f\u0648\u0644\u0657\u0627",translation:"Maka apabila datang saat hukuman bagi (kejahatan) yang pertama dari kedua (kejahatan) itu, Kami datangkan kepadamu hamba-hamba Kami yang perkasa, lalu mereka merajalela di kampung-kampung. Dan itulah ketetapan yang pasti terlaksana"},{id:6,text:"\u062b\u064f\u0645\u0651\u064e \u0631\u064e\u062f\u064e\u062f\u06e1\u0646\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0643\u064e\u0631\u0651\u064e\u0629\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0648\u064e\u0623\u064e\u0645\u06e1\u062f\u064e\u062f\u06e1\u0646\u064e\u0670\u0643\u064f\u0645 \u0628\u0650\u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u0656 \u0648\u064e\u0628\u064e\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0670\u0643\u064f\u0645\u06e1 \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064e \u0646\u064e\u0641\u0650\u064a\u0631\u064b\u0627",translation:"Kemudian Kami berikan kepadamu giliran untuk mengalahkan mereka, Kami membantumu dengan harta kekayaan dan anak-anak dan Kami jadikan kamu kelompok yang lebih besar"},{id:7,text:"\u0625\u0650\u0646\u06e1 \u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u062a\u064f\u0645\u06e1 \u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u062a\u064f\u0645\u06e1 \u0644\u0650\u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0625\u0650\u0646\u06e1 \u0623\u064e\u0633\u064e\u0623\u06e1\u062a\u064f\u0645\u06e1 \u0641\u064e\u0644\u064e\u0647\u064e\u0627\u06da \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e \u0648\u064e\u0639\u06e1\u062f\u064f \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0644\u0650\u064a\u064e\u0633\u064f\u0640\u0654\u064f\u0648\u0627\u0652 \u0648\u064f\u062c\u064f\u0648\u0647\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u0650\u064a\u064e\u062f\u06e1\u062e\u064f\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0645\u064e\u0633\u06e1\u062c\u0650\u062f\u064e \u0643\u064e\u0645\u064e\u0627 \u062f\u064e\u062e\u064e\u0644\u064f\u0648\u0647\u064f \u0623\u064e\u0648\u0651\u064e\u0644\u064e \u0645\u064e\u0631\u0651\u064e\u0629\u0656 \u0648\u064e\u0644\u0650\u064a\u064f\u062a\u064e\u0628\u0651\u0650\u0631\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u0639\u064e\u0644\u064e\u0648\u06e1\u0627\u0652 \u062a\u064e\u062a\u06e1\u0628\u0650\u064a\u0631\u064b\u0627",translation:"Jika kamu berbuat baik (berarti) kamu berbuat baik untuk dirimu sendiri. Dan jika kamu berbuat jahat, maka (kerugian kejahatan) itu untuk dirimu sendiri. Apabila datang saat hukuman (kejahatan) yang kedua, (Kami bangkitkan musuhmu) untuk menyuramkan wajahmu lalu mereka masuk ke dalam masjid (Masjidil Aqsa), sebagaimana ketika mereka memasukinya pertama kali dan mereka membinasakan apa saja yang mereka kuasai"},{id:8,text:"\u0639\u064e\u0633\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u06e1 \u0623\u064e\u0646 \u064a\u064e\u0631\u06e1\u062d\u064e\u0645\u064e\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0625\u0650\u0646\u06e1 \u0639\u064f\u062f\u062a\u0651\u064f\u0645\u06e1 \u0639\u064f\u062f\u06e1\u0646\u064e\u0627\u06da \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0644\u0650\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u062d\u064e\u0635\u0650\u064a\u0631\u064b\u0627",translation:"Mudah-mudahan Tuhan kamu melimpahkan rahmat kepada kamu; tetapi jika kamu kembali (melakukan kejahatan), niscaya Kami kembali (mengazabmu). Dan Kami jadikan neraka Jahanam penjara bagi orang kafir"},{id:9,text:"\u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u064e \u064a\u064e\u0647\u06e1\u062f\u0650\u064a \u0644\u0650\u0644\u0651\u064e\u062a\u0650\u064a \u0647\u0650\u064a\u064e \u0623\u064e\u0642\u06e1\u0648\u064e\u0645\u064f \u0648\u064e\u064a\u064f\u0628\u064e\u0634\u0651\u0650\u0631\u064f \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0623\u064e\u0646\u0651\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u062c\u06e1\u0631\u0657\u0627 \u0643\u064e\u0628\u0650\u064a\u0631\u0657\u0627",translation:"Sungguh, Alquran ini memberi petunjuk ke (jalan) yang paling lurus dan memberi kabar gembira kepada orang mukmin yang mengerjakan kebajikan, bahwa mereka akan mendapat pahala yang besar"},{id:10,text:"\u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0623\u064e\u0639\u06e1\u062a\u064e\u062f\u06e1\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0623\u064e\u0644\u0650\u064a\u0645\u0657\u0627",translation:"dan bahwa orang yang tidak beriman kepada kehidupan akhirat, Kami sediakan bagi mereka azab yang pedih"},{id:11,text:"\u0648\u064e\u064a\u064e\u062f\u06e1\u0639\u064f \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064f \u0628\u0650\u0671\u0644\u0634\u0651\u064e\u0631\u0651\u0650 \u062f\u064f\u0639\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u06e5 \u0628\u0650\u0671\u0644\u06e1\u062e\u064e\u064a\u06e1\u0631\u0650\u06d6 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064f \u0639\u064e\u062c\u064f\u0648\u0644\u0657\u0627",translation:"Dan manusia (seringkali) berdoa untuk kejahatan sebagaimana (biasanya) dia berdoa untuk kebaikan. Dan memang manusia bersifat tergesa-gesa"},{id:12,text:"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u064e \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u0621\u064e\u0627\u064a\u064e\u062a\u064e\u064a\u06e1\u0646\u0650\u06d6 \u0641\u064e\u0645\u064e\u062d\u064e\u0648\u06e1\u0646\u064e\u0627\u0653 \u0621\u064e\u0627\u064a\u064e\u0629\u064e \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u0650 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627\u0653 \u0621\u064e\u0627\u064a\u064e\u0629\u064e \u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u0645\u064f\u0628\u06e1\u0635\u0650\u0631\u064e\u0629\u0657 \u0644\u0651\u0650\u062a\u064e\u0628\u06e1\u062a\u064e\u063a\u064f\u0648\u0627\u0652 \u0641\u064e\u0636\u06e1\u0644\u0657\u0627 \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u0650\u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0627\u0652 \u0639\u064e\u062f\u064e\u062f\u064e \u0671\u0644\u0633\u0651\u0650\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u062d\u0650\u0633\u064e\u0627\u0628\u064e\u06da \u0648\u064e\u0643\u064f\u0644\u0651\u064e \u0634\u064e\u064a\u06e1\u0621\u0656 \u0641\u064e\u0635\u0651\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f \u062a\u064e\u0641\u06e1\u0635\u0650\u064a\u0644\u0657\u0627",translation:"Dan Kami jadikan malam dan siang sebagai dua tanda (kebesaran Kami), kemudian Kami hapuskan tanda malam dan Kami jadikan tanda siang itu terang benderang, agar kamu (dapat) mencari karunia dari Tuhanmu, dan agar kamu mengetahui bilangan tahun dan perhitungan (waktu). Dan segala sesuatu telah Kami terangkan dengan jelas"},{id:13,text:"\u0648\u064e\u0643\u064f\u0644\u0651\u064e \u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064d \u0623\u064e\u0644\u06e1\u0632\u064e\u0645\u06e1\u0646\u064e\u0670\u0647\u064f \u0637\u064e\u0640\u0670\u0653\u0626\u0650\u0631\u064e\u0647\u064f\u06e5 \u0641\u0650\u064a \u0639\u064f\u0646\u064f\u0642\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u0646\u064f\u062e\u06e1\u0631\u0650\u062c\u064f \u0644\u064e\u0647\u064f\u06e5 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u0643\u0650\u062a\u064e\u0670\u0628\u0657\u0627 \u064a\u064e\u0644\u06e1\u0642\u064e\u0649\u0670\u0647\u064f \u0645\u064e\u0646\u0634\u064f\u0648\u0631\u064b\u0627",translation:"Dan setiap manusia telah Kami kalungkan (catatan) amal perbuatannya di lehernya. Dan pada hari Kiamat Kami keluarkan baginya sebuah kitab dalam keadaan terbuka"},{id:14,text:"\u0671\u0642\u06e1\u0631\u064e\u0623\u06e1 \u0643\u0650\u062a\u064e\u0670\u0628\u064e\u0643\u064e \u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0646\u064e\u0641\u06e1\u0633\u0650\u0643\u064e \u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u062d\u064e\u0633\u0650\u064a\u0628\u0657\u0627",translation:"Bacalah kitabmu, cukuplah dirimu sendiri pada hari ini sebagai penghitung atas amalmu"},{id:15,text:"\u0645\u0651\u064e\u0646\u0650 \u0671\u0647\u06e1\u062a\u064e\u062f\u064e\u0649\u0670 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0647\u06e1\u062a\u064e\u062f\u0650\u064a \u0644\u0650\u0646\u064e\u0641\u06e1\u0633\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u0645\u064e\u0646 \u0636\u064e\u0644\u0651\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0636\u0650\u0644\u0651\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627\u06da \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0632\u0650\u0631\u064f \u0648\u064e\u0627\u0632\u0650\u0631\u064e\u0629\u065e \u0648\u0650\u0632\u06e1\u0631\u064e \u0623\u064f\u062e\u06e1\u0631\u064e\u0649\u0670\u06d7 \u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0645\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u0650\u064a\u0646\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0646\u064e\u0628\u06e1\u0639\u064e\u062b\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u0657\u0627",translation:"Barang siapa berbuat sesuai dengan petunjuk (Allah), maka sesungguhnya itu untuk (keselamatan) dirinya sendiri; dan barang siapa tersesat maka sesungguhnya (kerugian) itu bagi dirinya sendiri. Dan seorang yang berdosa tidak dapat memikul dosa orang lain, tetapi Kami tidak akan menyiksa sebelum Kami mengutus seorang rasul"},{id:16,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627\u0653 \u0623\u064e\u0631\u064e\u062f\u06e1\u0646\u064e\u0627\u0653 \u0623\u064e\u0646 \u0646\u0651\u064f\u0647\u06e1\u0644\u0650\u0643\u064e \u0642\u064e\u0631\u06e1\u064a\u064e\u0629\u064b \u0623\u064e\u0645\u064e\u0631\u06e1\u0646\u064e\u0627 \u0645\u064f\u062a\u06e1\u0631\u064e\u0641\u0650\u064a\u0647\u064e\u0627 \u0641\u064e\u0641\u064e\u0633\u064e\u0642\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0641\u064e\u062d\u064e\u0642\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627 \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0644\u064f \u0641\u064e\u062f\u064e\u0645\u0651\u064e\u0631\u06e1\u0646\u064e\u0670\u0647\u064e\u0627 \u062a\u064e\u062f\u06e1\u0645\u0650\u064a\u0631\u0657\u0627",translation:"Dan jika Kami hendak membinasakan suatu negeri, maka Kami perintahkan kepada orang yang hidup mewah di negeri itu (agar menaati Allah), tetapi bila mereka melakukan kedurhakaan di dalam (negeri) itu, maka sepantasnya berlakulah terhadapnya perkataan (hukuman Kami), kemudian Kami meluluh lantakkannya (negeri itu)"},{id:17,text:"\u0648\u064e\u0643\u064e\u0645\u06e1 \u0623\u064e\u0647\u06e1\u0644\u064e\u0643\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0642\u064f\u0631\u064f\u0648\u0646\u0650 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0646\u064f\u0648\u062d\u0656\u06d7 \u0648\u064e\u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0628\u0650\u0630\u064f\u0646\u064f\u0648\u0628\u0650 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650\u06e6 \u062e\u064e\u0628\u0650\u064a\u0631\u064e\u06e2\u0627 \u0628\u064e\u0635\u0650\u064a\u0631\u0657\u0627",translation:"Dan berapa banyak kaum setelah Nuh, yang telah Kami binasakan. Dan cukuplah Tuhanmu Yang Maha Mengetahui, Maha Melihat dosa hamba-hamba-Nya"},{id:18,text:"\u0645\u0651\u064e\u0646 \u0643\u064e\u0627\u0646\u064e \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0671\u0644\u06e1\u0639\u064e\u0627\u062c\u0650\u0644\u064e\u0629\u064e \u0639\u064e\u062c\u0651\u064e\u0644\u06e1\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u06e5 \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u064e\u0627 \u0646\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0644\u0650\u0645\u064e\u0646 \u0646\u0651\u064f\u0631\u0650\u064a\u062f\u064f \u062b\u064f\u0645\u0651\u064e \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u06e5 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u064a\u064e\u0635\u06e1\u0644\u064e\u0649\u0670\u0647\u064e\u0627 \u0645\u064e\u0630\u06e1\u0645\u064f\u0648\u0645\u0657\u0627 \u0645\u0651\u064e\u062f\u06e1\u062d\u064f\u0648\u0631\u0657\u0627",translation:"Barangsiapa menghendaki kehidupan sekarang (duniawi), maka Kami segerakan baginya di (dunia) ini apa yang Kami kehendaki bagi orang yang Kami kehendaki. Kemudian Kami sediakan baginya (di akhirat) neraka Jahanam; dia akan memasukinya dalam keadaan tercela dan terusir"},{id:19,text:"\u0648\u064e\u0645\u064e\u0646\u06e1 \u0623\u064e\u0631\u064e\u0627\u062f\u064e \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u064e \u0648\u064e\u0633\u064e\u0639\u064e\u0649\u0670 \u0644\u064e\u0647\u064e\u0627 \u0633\u064e\u0639\u06e1\u064a\u064e\u0647\u064e\u0627 \u0648\u064e\u0647\u064f\u0648\u064e \u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u065e \u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0643\u064e\u0627\u0646\u064e \u0633\u064e\u0639\u06e1\u064a\u064f\u0647\u064f\u0645 \u0645\u0651\u064e\u0634\u06e1\u0643\u064f\u0648\u0631\u0657\u0627",translation:"Dan barangsiapa menghendaki kehidupan akhirat dan berusaha ke arah itu dengan sungguh-sungguh, sedangkan dia beriman, maka mereka itulah orang yang usahanya dibalas dengan baik"},{id:20,text:"\u0643\u064f\u0644\u0651\u0657\u0627 \u0646\u0651\u064f\u0645\u0650\u062f\u0651\u064f \u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650 \u0648\u064e\u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650 \u0645\u0650\u0646\u06e1 \u0639\u064e\u0637\u064e\u0627\u0653\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e\u06da \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0637\u064e\u0627\u0653\u0621\u064f \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0645\u064e\u062d\u06e1\u0638\u064f\u0648\u0631\u064b\u0627",translation:"Kepada masing-masing (golongan), baik (golongan) ini (yang menginginkan dunia) maupun (golongan) itu (yang menginginkan akhirat), Kami berikan bantuan dari kemurahan Tuhanmu. Dan kemurahan Tuhanmu tidak dapat dihalangi"},{id:21,text:"\u0671\u0646\u0638\u064f\u0631\u06e1 \u0643\u064e\u064a\u06e1\u0641\u064e \u0641\u064e\u0636\u0651\u064e\u0644\u06e1\u0646\u064e\u0627 \u0628\u064e\u0639\u06e1\u0636\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u06e1\u0636\u0656\u06da \u0648\u064e\u0644\u064e\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u064f \u0623\u064e\u0643\u06e1\u0628\u064e\u0631\u064f \u062f\u064e\u0631\u064e\u062c\u064e\u0670\u062a\u0656 \u0648\u064e\u0623\u064e\u0643\u06e1\u0628\u064e\u0631\u064f \u062a\u064e\u0641\u06e1\u0636\u0650\u064a\u0644\u0657\u0627",translation:"Perhatikanlah bagaimana Kami melebihkan sebagian mereka atas sebagian (yang lain). Dan kehidupan akhirat lebih tinggi derajatnya dan lebih besar keutamaannya"},{id:22,text:"\u0644\u0651\u064e\u0627 \u062a\u064e\u062c\u06e1\u0639\u064e\u0644\u06e1 \u0645\u064e\u0639\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u064e\u0670\u0647\u064b\u0627 \u0621\u064e\u0627\u062e\u064e\u0631\u064e \u0641\u064e\u062a\u064e\u0642\u06e1\u0639\u064f\u062f\u064e \u0645\u064e\u0630\u06e1\u0645\u064f\u0648\u0645\u0657\u0627 \u0645\u0651\u064e\u062e\u06e1\u0630\u064f\u0648\u0644\u0657\u0627",translation:"Janganlah engkau mengadakan tuhan yang lain di samping Allah, nanti engkau menjadi tercela dan terhina"},{id:23,text:"\u06de\u0648\u064e\u0642\u064e\u0636\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0625\u0650\u064a\u0651\u064e\u0627\u0647\u064f \u0648\u064e\u0628\u0650\u0671\u0644\u06e1\u0648\u064e\u0670\u0644\u0650\u062f\u064e\u064a\u06e1\u0646\u0650 \u0625\u0650\u062d\u06e1\u0633\u064e\u0670\u0646\u064b\u0627\u06da \u0625\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u0628\u06e1\u0644\u064f\u063a\u064e\u0646\u0651\u064e \u0639\u0650\u0646\u062f\u064e\u0643\u064e \u0671\u0644\u06e1\u0643\u0650\u0628\u064e\u0631\u064e \u0623\u064e\u062d\u064e\u062f\u064f\u0647\u064f\u0645\u064e\u0627\u0653 \u0623\u064e\u0648\u06e1 \u0643\u0650\u0644\u064e\u0627\u0647\u064f\u0645\u064e\u0627 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u064f\u0644 \u0644\u0651\u064e\u0647\u064f\u0645\u064e\u0627\u0653 \u0623\u064f\u0641\u0651\u0656 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0646\u06e1\u0647\u064e\u0631\u06e1\u0647\u064f\u0645\u064e\u0627 \u0648\u064e\u0642\u064f\u0644 \u0644\u0651\u064e\u0647\u064f\u0645\u064e\u0627 \u0642\u064e\u0648\u06e1\u0644\u0657\u0627 \u0643\u064e\u0631\u0650\u064a\u0645\u0657\u0627",translation:"Dan Tuhanmu telah memerintahkan agar kamu jangan menyembah selain Dia dan hendaklah berbuat baik kepada ibu bapak. Jika salah seorang di antara keduanya atau kedua-duanya sampai berusia lanjut dalam pemeliharaanmu, maka sekali-kali janganlah engkau mengatakan kepada keduanya perkataan \"ah\" dan janganlah engkau membentak keduanya, dan ucapkanlah kepada keduanya perkataan yang baik"},{id:24,text:"\u0648\u064e\u0671\u062e\u06e1\u0641\u0650\u0636\u06e1 \u0644\u064e\u0647\u064f\u0645\u064e\u0627 \u062c\u064e\u0646\u064e\u0627\u062d\u064e \u0671\u0644\u0630\u0651\u064f\u0644\u0651\u0650 \u0645\u0650\u0646\u064e \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0629\u0650 \u0648\u064e\u0642\u064f\u0644 \u0631\u0651\u064e\u0628\u0651\u0650 \u0671\u0631\u06e1\u062d\u064e\u0645\u06e1\u0647\u064f\u0645\u064e\u0627 \u0643\u064e\u0645\u064e\u0627 \u0631\u064e\u0628\u0651\u064e\u064a\u064e\u0627\u0646\u0650\u064a \u0635\u064e\u063a\u0650\u064a\u0631\u0657\u0627",translation:"Dan rendahkanlah dirimu terhadap keduanya dengan penuh kasih sayang dan ucapkanlah, \"Wahai Tuhanku! Sayangilah keduanya sebagaimana mereka berdua telah mendidik aku pada waktu kecil"},{id:25,text:"\u0631\u0651\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u06e1 \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u0641\u0650\u064a \u0646\u064f\u0641\u064f\u0648\u0633\u0650\u0643\u064f\u0645\u06e1\u06da \u0625\u0650\u0646 \u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u0635\u064e\u0670\u0644\u0650\u062d\u0650\u064a\u0646\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0644\u06e1\u0623\u064e\u0648\u0651\u064e\u0640\u0670\u0628\u0650\u064a\u0646\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u0657\u0627",translation:"Tuhanmu lebih mengetahui apa yang ada dalam hatimu; jika kamu orang yang baik, maka sungguh, Dia Maha Pengampun kepada orang yang bertobat"},{id:26,text:"\u0648\u064e\u0621\u064e\u0627\u062a\u0650 \u0630\u064e\u0627 \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0628\u064e\u0649\u0670 \u062d\u064e\u0642\u0651\u064e\u0647\u064f\u06e5 \u0648\u064e\u0671\u0644\u06e1\u0645\u0650\u0633\u06e1\u0643\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0628\u06e1\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u0650 \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0628\u064e\u0630\u0651\u0650\u0631\u06e1 \u062a\u064e\u0628\u06e1\u0630\u0650\u064a\u0631\u064b\u0627",translation:"Dan berikanlah haknya kepada kerabat dekat, juga kepada orang miskin dan orang yang dalam perjalanan; dan janganlah kamu menghambur-hamburkan (hartamu) secara boros"},{id:27,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0645\u064f\u0628\u064e\u0630\u0651\u0650\u0631\u0650\u064a\u0646\u064e \u0643\u064e\u0627\u0646\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u062e\u06e1\u0648\u064e\u0670\u0646\u064e \u0671\u0644\u0634\u0651\u064e\u064a\u064e\u0670\u0637\u0650\u064a\u0646\u0650\u06d6 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u064f \u0644\u0650\u0631\u064e\u0628\u0651\u0650\u0647\u0650\u06e6 \u0643\u064e\u0641\u064f\u0648\u0631\u0657\u0627",translation:"Sesungguhnya orang-orang yang pemboros itu adalah saudara setan dan setan itu sangat ingkar kepada Tuhannya"},{id:28,text:"\u0648\u064e\u0625\u0650\u0645\u0651\u064e\u0627 \u062a\u064f\u0639\u06e1\u0631\u0650\u0636\u064e\u0646\u0651\u064e \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u064f \u0671\u0628\u06e1\u062a\u0650\u063a\u064e\u0627\u0653\u0621\u064e \u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u0656 \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064e \u062a\u064e\u0631\u06e1\u062c\u064f\u0648\u0647\u064e\u0627 \u0641\u064e\u0642\u064f\u0644 \u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u0642\u064e\u0648\u06e1\u0644\u0657\u0627 \u0645\u0651\u064e\u064a\u06e1\u0633\u064f\u0648\u0631\u0657\u0627",translation:"Dan jika engkau berpaling dari mereka untuk memperoleh rahmat dari Tuhanmu yang engkau harapkan, maka katakanlah kepada mereka ucapan yang lemah lembut"},{id:29,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062c\u06e1\u0639\u064e\u0644\u06e1 \u064a\u064e\u062f\u064e\u0643\u064e \u0645\u064e\u063a\u06e1\u0644\u064f\u0648\u0644\u064e\u0629\u064b \u0625\u0650\u0644\u064e\u0649\u0670 \u0639\u064f\u0646\u064f\u0642\u0650\u0643\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0628\u06e1\u0633\u064f\u0637\u06e1\u0647\u064e\u0627 \u0643\u064f\u0644\u0651\u064e \u0671\u0644\u06e1\u0628\u064e\u0633\u06e1\u0637\u0650 \u0641\u064e\u062a\u064e\u0642\u06e1\u0639\u064f\u062f\u064e \u0645\u064e\u0644\u064f\u0648\u0645\u0657\u0627 \u0645\u0651\u064e\u062d\u06e1\u0633\u064f\u0648\u0631\u064b\u0627",translation:"Dan janganlah engkau jadikan tanganmu terbelenggu pada lehermu dan jangan (pula) engkau terlalu mengulurkannya (sangat pemurah) nanti kamu menjadi tercela dan menyesal"},{id:30,text:"\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u064a\u064e\u0628\u06e1\u0633\u064f\u0637\u064f \u0671\u0644\u0631\u0651\u0650\u0632\u06e1\u0642\u064e \u0644\u0650\u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0648\u064e\u064a\u064e\u0642\u06e1\u062f\u0650\u0631\u064f\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0643\u064e\u0627\u0646\u064e \u0628\u0650\u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650\u06e6 \u062e\u064e\u0628\u0650\u064a\u0631\u064e\u06e2\u0627 \u0628\u064e\u0635\u0650\u064a\u0631\u0657\u0627",translation:"Sungguh, Tuhanmu melapangkan rezeki bagi siapa yang Dia kehendaki dan membatasi (bagi siapa yang Dia kehendaki); sungguh, Dia Maha Mengetahui, Maha Melihat hamba-hamba-Nya"},{id:31,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u06e1\u062a\u064f\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0648\u06e1\u0644\u064e\u0670\u062f\u064e\u0643\u064f\u0645\u06e1 \u062e\u064e\u0634\u06e1\u064a\u064e\u0629\u064e \u0625\u0650\u0645\u06e1\u0644\u064e\u0670\u0642\u0656\u06d6 \u0646\u0651\u064e\u062d\u06e1\u0646\u064f \u0646\u064e\u0631\u06e1\u0632\u064f\u0642\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0625\u0650\u064a\u0651\u064e\u0627\u0643\u064f\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e \u0642\u064e\u062a\u06e1\u0644\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0627\u0646\u064e \u062e\u0650\u0637\u06e1\u0640\u0654\u0657\u0627 \u0643\u064e\u0628\u0650\u064a\u0631\u0657\u0627",translation:"Dan janganlah kamu membunuh anak-anakmu karena takut miskin. Kamilah yang memberi rezeki kepada mereka dan kepadamu. Membunuh mereka itu sungguh suatu dosa yang besar"},{id:32,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u06e1\u0631\u064e\u0628\u064f\u0648\u0627\u0652 \u0671\u0644\u0632\u0651\u0650\u0646\u064e\u0649\u0670\u0653\u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0643\u064e\u0627\u0646\u064e \u0641\u064e\u0670\u062d\u0650\u0634\u064e\u0629\u0657 \u0648\u064e\u0633\u064e\u0627\u0653\u0621\u064e \u0633\u064e\u0628\u0650\u064a\u0644\u0657\u0627",translation:"Dan janganlah kamu mendekati zina; (zina) itu sungguh suatu perbuatan keji, dan suatu jalan yang buruk"},{id:33,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u06e1\u062a\u064f\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0646\u0651\u064e\u0641\u06e1\u0633\u064e \u0671\u0644\u0651\u064e\u062a\u0650\u064a \u062d\u064e\u0631\u0651\u064e\u0645\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650\u06d7 \u0648\u064e\u0645\u064e\u0646 \u0642\u064f\u062a\u0650\u0644\u064e \u0645\u064e\u0638\u06e1\u0644\u064f\u0648\u0645\u0657\u0627 \u0641\u064e\u0642\u064e\u062f\u06e1 \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0644\u0650\u0648\u064e\u0644\u0650\u064a\u0651\u0650\u0647\u0650\u06e6 \u0633\u064f\u0644\u06e1\u0637\u064e\u0670\u0646\u0657\u0627 \u0641\u064e\u0644\u064e\u0627 \u064a\u064f\u0633\u06e1\u0631\u0650\u0641 \u0641\u0651\u0650\u064a \u0671\u0644\u06e1\u0642\u064e\u062a\u06e1\u0644\u0650\u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0643\u064e\u0627\u0646\u064e \u0645\u064e\u0646\u0635\u064f\u0648\u0631\u0657\u0627",translation:"Dan janganlah kamu membunuh orang yang diharamkan Allah (membunuhnya), kecuali dengan suatu (alasan) yang benar.473) Dan barangsiapa dibunuh secara zalim, maka sungguh, Kami telah memberi kekuasaan474) kepada walinya, tetapi janganlah walinya itu melampaui batas dalam pembunuhan. Sesungguhnya dia adalah orang yang mendapat pertolongan"},{id:34,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u06e1\u0631\u064e\u0628\u064f\u0648\u0627\u0652 \u0645\u064e\u0627\u0644\u064e \u0671\u0644\u06e1\u064a\u064e\u062a\u0650\u064a\u0645\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0671\u0644\u0651\u064e\u062a\u0650\u064a \u0647\u0650\u064a\u064e \u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064f \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0628\u06e1\u0644\u064f\u063a\u064e \u0623\u064e\u0634\u064f\u062f\u0651\u064e\u0647\u064f\u06e5\u06da \u0648\u064e\u0623\u064e\u0648\u06e1\u0641\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u06e1\u0639\u064e\u0647\u06e1\u062f\u0650\u06d6 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0639\u064e\u0647\u06e1\u062f\u064e \u0643\u064e\u0627\u0646\u064e \u0645\u064e\u0633\u06e1\u0640\u0654\u064f\u0648\u0644\u0657\u0627",translation:"Dan janganlah kamu mendekati harta anak yatim, kecuali dengan cara yang lebih baik (bermanfaat) sampai dia dewasa, dan penuhilah janji, karena janji itu pasti diminta pertanggungjawabannya"},{id:35,text:"\u0648\u064e\u0623\u064e\u0648\u06e1\u0641\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0643\u064e\u064a\u06e1\u0644\u064e \u0625\u0650\u0630\u064e\u0627 \u0643\u0650\u0644\u06e1\u062a\u064f\u0645\u06e1 \u0648\u064e\u0632\u0650\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u06e1\u0642\u0650\u0633\u06e1\u0637\u064e\u0627\u0633\u0650 \u0671\u0644\u06e1\u0645\u064f\u0633\u06e1\u062a\u064e\u0642\u0650\u064a\u0645\u0650\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062e\u064e\u064a\u06e1\u0631\u065e \u0648\u064e\u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064f \u062a\u064e\u0623\u06e1\u0648\u0650\u064a\u0644\u0657\u0627",translation:"Dan sempurnakanlah takaran apabila kamu menakar, dan timbanglah dengan timbangan yang benar. Itulah yang lebih utama (bagimu) dan lebih baik akibatnya"},{id:36,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u06e1\u0641\u064f \u0645\u064e\u0627 \u0644\u064e\u064a\u06e1\u0633\u064e \u0644\u064e\u0643\u064e \u0628\u0650\u0647\u0650\u06e6 \u0639\u0650\u0644\u06e1\u0645\u064c\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u06e1\u0639\u064e \u0648\u064e\u0671\u0644\u06e1\u0628\u064e\u0635\u064e\u0631\u064e \u0648\u064e\u0671\u0644\u06e1\u0641\u064f\u0624\u064e\u0627\u062f\u064e \u0643\u064f\u0644\u0651\u064f \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0646\u06e1\u0647\u064f \u0645\u064e\u0633\u06e1\u0640\u0654\u064f\u0648\u0644\u0657\u0627",translation:"Dan janganlah kamu mengikuti sesuatu yang tidak kamu ketahui. Karena pendengaran, penglihatan dan hati nurani, semua itu akan diminta pertanggungjawabannya"},{id:37,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0645\u06e1\u0634\u0650 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0645\u064e\u0631\u064e\u062d\u064b\u0627\u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u0646 \u062a\u064e\u062e\u06e1\u0631\u0650\u0642\u064e \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0648\u064e\u0644\u064e\u0646 \u062a\u064e\u0628\u06e1\u0644\u064f\u063a\u064e \u0671\u0644\u06e1\u062c\u0650\u0628\u064e\u0627\u0644\u064e \u0637\u064f\u0648\u0644\u0657\u0627",translation:"Dan janganlah engkau berjalan di bumi ini dengan sombong, karena sesungguhnya engkau tidak akan dapat menembus bumi dan tidak akan mampu menjulang setinggi gunung"},{id:38,text:"\u0643\u064f\u0644\u0651\u064f \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0643\u064e\u0627\u0646\u064e \u0633\u064e\u064a\u0651\u0650\u0626\u064f\u0647\u064f\u06e5 \u0639\u0650\u0646\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0645\u064e\u0643\u06e1\u0631\u064f\u0648\u0647\u0657\u0627",translation:"(Semua itu475) kejahatannya sangat dibenci di sisi Tuhanmu"},{id:39,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u0650\u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u0648\u06e1\u062d\u064e\u0649\u0670\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u062d\u0650\u0643\u06e1\u0645\u064e\u0629\u0650\u06d7 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062c\u06e1\u0639\u064e\u0644\u06e1 \u0645\u064e\u0639\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u064e\u0670\u0647\u064b\u0627 \u0621\u064e\u0627\u062e\u064e\u0631\u064e \u0641\u064e\u062a\u064f\u0644\u06e1\u0642\u064e\u0649\u0670 \u0641\u0650\u064a \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0645\u064e\u0644\u064f\u0648\u0645\u0657\u0627 \u0645\u0651\u064e\u062f\u06e1\u062d\u064f\u0648\u0631\u064b\u0627",translation:"Itulah sebagian hikmah yang diwahyukan Tuhan kepadamu (Muhammad). Dan janganlah engkau mengadakan tuhan yang lain di samping Allah, nanti engkau dilemparkan ke dalam neraka dalam keadaan tercela dan dijauhkan (dari rahmat Allah)"},{id:40,text:"\u0623\u064e\u0641\u064e\u0623\u064e\u0635\u06e1\u0641\u064e\u0649\u0670\u0643\u064f\u0645\u06e1 \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0628\u064e\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u0650 \u0625\u0650\u0646\u064e\u0670\u062b\u064b\u0627\u06da \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0644\u064e\u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0642\u064e\u0648\u06e1\u0644\u064b\u0627 \u0639\u064e\u0638\u0650\u064a\u0645\u0657\u0627",translation:"Maka apakah pantas Tuhan memilihkan anak laki-laki untukmu dan Dia mengambil anak perempuan dari malaikat? Sungguh, kamu benar-benar mengucapkan perkataan yang besar (dosanya)"},{id:41,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0635\u064e\u0631\u0651\u064e\u0641\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a \u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u0650 \u0644\u0650\u064a\u064e\u0630\u0651\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0632\u0650\u064a\u062f\u064f\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u0646\u064f\u0641\u064f\u0648\u0631\u0657\u0627",translation:"Dan sungguh, dalam Alquran ini telah Kami (jelaskan) berulang-ulang (peringatan), agar mereka selalu ingat. Tetapi (peringatan) itu hanya menambah mereka lari (dari kebenaran)"},{id:42,text:"\u0642\u064f\u0644 \u0644\u0651\u064e\u0648\u06e1 \u0643\u064e\u0627\u0646\u064e \u0645\u064e\u0639\u064e\u0647\u064f\u06e5\u0653 \u0621\u064e\u0627\u0644\u0650\u0647\u064e\u0629\u065e \u0643\u064e\u0645\u064e\u0627 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0625\u0650\u0630\u0657\u0627 \u0644\u0651\u064e\u0671\u0628\u06e1\u062a\u064e\u063a\u064e\u0648\u06e1\u0627\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0630\u0650\u064a \u0671\u0644\u06e1\u0639\u064e\u0631\u06e1\u0634\u0650 \u0633\u064e\u0628\u0650\u064a\u0644\u0657\u0627",translation:"Katakanlah (Muhammad), \"jika ada tuhan-tuhan disamping-Nya, sebagaimana yang mereka katakan, niscaya tuhan-tuhan itu mencari jalan kepada Tuhan yang mempunyai Arasy"},{id:43,text:"\u0633\u064f\u0628\u06e1\u062d\u064e\u0670\u0646\u064e\u0647\u064f\u06e5 \u0648\u064e\u062a\u064e\u0639\u064e\u0670\u0644\u064e\u0649\u0670 \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0639\u064f\u0644\u064f\u0648\u0651\u0657\u0627 \u0643\u064e\u0628\u0650\u064a\u0631\u0657\u0627",translation:"Mahasuci dan Mahatinggi Dia dari apa yang mereka katakan, luhur dan agung (tidak ada bandingannya)"},{id:44,text:"\u062a\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u064f \u0644\u064e\u0647\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u064f \u0671\u0644\u0633\u0651\u064e\u0628\u06e1\u0639\u064f \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064f \u0648\u064e\u0645\u064e\u0646 \u0641\u0650\u064a\u0647\u0650\u0646\u0651\u064e\u06da \u0648\u064e\u0625\u0650\u0646 \u0645\u0651\u0650\u0646 \u0634\u064e\u064a\u06e1\u0621\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u064a\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u064f \u0628\u0650\u062d\u064e\u0645\u06e1\u062f\u0650\u0647\u0650\u06e6 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u0644\u0651\u064e\u0627 \u062a\u064e\u0641\u06e1\u0642\u064e\u0647\u064f\u0648\u0646\u064e \u062a\u064e\u0633\u06e1\u0628\u0650\u064a\u062d\u064e\u0647\u064f\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0643\u064e\u0627\u0646\u064e \u062d\u064e\u0644\u0650\u064a\u0645\u064b\u0627 \u063a\u064e\u0641\u064f\u0648\u0631\u0657\u0627",translation:"Langit yang tujuh, bumi dan semua yang ada di dalamnya bertasbih kepada Allah. Dan tidak ada sesuatu pun melainkan bertasbih dengan memuji-Nya, tetapi kamu tidak mengerti tasbih mereka. Sungguh, Dia Maha Penyantun, Maha Pengampun"},{id:45,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u064e\u0631\u064e\u0623\u06e1\u062a\u064e \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u064e \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e\u0643\u064e \u0648\u064e\u0628\u064e\u064a\u06e1\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u062d\u0650\u062c\u064e\u0627\u0628\u0657\u0627 \u0645\u0651\u064e\u0633\u06e1\u062a\u064f\u0648\u0631\u0657\u0627",translation:"Dan apabila engkau (Muhammad) membaca Alquran, Kami adakan suatu dinding yang tidak terlihat antara engkau dan orang-orang yang tidak beriman kepada kehidupan akhirat"},{id:46,text:"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u06e1 \u0623\u064e\u0643\u0650\u0646\u0651\u064e\u0629\u064b \u0623\u064e\u0646 \u064a\u064e\u0641\u06e1\u0642\u064e\u0647\u064f\u0648\u0647\u064f \u0648\u064e\u0641\u0650\u064a\u0653 \u0621\u064e\u0627\u0630\u064e\u0627\u0646\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0642\u06e1\u0631\u0657\u0627\u06da \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0630\u064e\u0643\u064e\u0631\u06e1\u062a\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u0650 \u0648\u064e\u062d\u06e1\u062f\u064e\u0647\u064f\u06e5 \u0648\u064e\u0644\u0651\u064e\u0648\u06e1\u0627\u0652 \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u062f\u06e1\u0628\u064e\u0670\u0631\u0650\u0647\u0650\u0645\u06e1 \u0646\u064f\u0641\u064f\u0648\u0631\u0657\u0627",translation:"dan Kami jadikan hati mereka tertutup dan telinga mereka tersumbat, agar mereka tidak dapat memahaminya. Dan apabila engkau menyebut Tuhanmu saja dalam Alquran, mereka berpaling ke belakang melarikan diri (karena benci)"},{id:47,text:"\u0646\u0651\u064e\u062d\u06e1\u0646\u064f \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0645\u0650\u0639\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0630\u06e1 \u064a\u064e\u0633\u06e1\u062a\u064e\u0645\u0650\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0648\u064e\u0625\u0650\u0630\u06e1 \u0647\u064f\u0645\u06e1 \u0646\u064e\u062c\u06e1\u0648\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u06e1 \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u064f\u0648\u0646\u064e \u0625\u0650\u0646 \u062a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0631\u064e\u062c\u064f\u0644\u0657\u0627 \u0645\u0651\u064e\u0633\u06e1\u062d\u064f\u0648\u0631\u064b\u0627",translation:"Kami lebih mengetahui dalam keadaan bagaimana mereka mendengarkan sewaktu mereka mendengarkan engkau (Muhammad), dan sewaktu mereka berbisik-bisik (yaitu) ketika orang zalim itu berkata, \"Kamu hanyalah mengikuti seorang laki-laki yang kena sihir"},{id:48,text:"\u0671\u0646\u0638\u064f\u0631\u06e1 \u0643\u064e\u064a\u06e1\u0641\u064e \u0636\u064e\u0631\u064e\u0628\u064f\u0648\u0627\u0652 \u0644\u064e\u0643\u064e \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u062b\u064e\u0627\u0644\u064e \u0641\u064e\u0636\u064e\u0644\u0651\u064f\u0648\u0627\u0652 \u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u064e \u0633\u064e\u0628\u0650\u064a\u0644\u0657\u0627",translation:"Lihatlah bagaimana mereka membuat perumpamaan untukmu (Muhammad); karena itu mereka menjadi sesat dan tidak dapat lagi menemukan jalan (yang benar)"},{id:49,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0621\u0650\u0630\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0639\u0650\u0638\u064e\u0670\u0645\u0657\u0627 \u0648\u064e\u0631\u064f\u0641\u064e\u0670\u062a\u064b\u0627 \u0623\u064e\u0621\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0645\u064e\u0628\u06e1\u0639\u064f\u0648\u062b\u064f\u0648\u0646\u064e \u062e\u064e\u0644\u06e1\u0642\u0657\u0627 \u062c\u064e\u062f\u0650\u064a\u062f\u0657\u0627",translation:"Dan mereka berkata, \"Apabila kami telah menjadi tulang-belulang dan benda-benda yang hancur, apakah kami benar-benar akan dibangkitkan kembali sebagai makhluk yang baru"},{id:50,text:"\u06de\u0642\u064f\u0644\u06e1 \u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u062d\u0650\u062c\u064e\u0627\u0631\u064e\u0629\u064b \u0623\u064e\u0648\u06e1 \u062d\u064e\u062f\u0650\u064a\u062f\u064b\u0627",translation:"Katakanlah (Muhammad), \"Jadilah kamu batu atau besi"},{id:51,text:"\u0623\u064e\u0648\u06e1 \u062e\u064e\u0644\u06e1\u0642\u0657\u0627 \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u0643\u06e1\u0628\u064f\u0631\u064f \u0641\u0650\u064a \u0635\u064f\u062f\u064f\u0648\u0631\u0650\u0643\u064f\u0645\u06e1\u06da \u0641\u064e\u0633\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0645\u064e\u0646 \u064a\u064f\u0639\u0650\u064a\u062f\u064f\u0646\u064e\u0627\u06d6 \u0642\u064f\u0644\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0641\u064e\u0637\u064e\u0631\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u0648\u0651\u064e\u0644\u064e \u0645\u064e\u0631\u0651\u064e\u0629\u0656\u06da \u0641\u064e\u0633\u064e\u064a\u064f\u0646\u06e1\u063a\u0650\u0636\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0631\u064f\u0621\u064f\u0648\u0633\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0645\u064e\u062a\u064e\u0649\u0670 \u0647\u064f\u0648\u064e\u06d6 \u0642\u064f\u0644\u06e1 \u0639\u064e\u0633\u064e\u0649\u0670\u0653 \u0623\u064e\u0646 \u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0642\u064e\u0631\u0650\u064a\u0628\u0657\u0627",translation:"atau menjadi makhluk yang besar (yang tidak mungkin hidup kembali) menurut pikiranmu. \"Maka mereka akan bertanya, \"Siapa yang akan menghidupkan kami kembali?\" Katakanlah, \"Yang telah menciptakan kamu pertama kali.\" Lalu mereka akan menggeleng-gelengkan kepalanya kepadamu dan berkata, \"Kapan (Kiamat) itu (akan terjadi)?\" Katakanlah, \"Barangkali waktunya sudah dekat"},{id:52,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064e\u062f\u06e1\u0639\u064f\u0648\u0643\u064f\u0645\u06e1 \u0641\u064e\u062a\u064e\u0633\u06e1\u062a\u064e\u062c\u0650\u064a\u0628\u064f\u0648\u0646\u064e \u0628\u0650\u062d\u064e\u0645\u06e1\u062f\u0650\u0647\u0650\u06e6 \u0648\u064e\u062a\u064e\u0638\u064f\u0646\u0651\u064f\u0648\u0646\u064e \u0625\u0650\u0646 \u0644\u0651\u064e\u0628\u0650\u062b\u06e1\u062a\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u0657\u0627",translation:"yaitu pada hari (ketika) Dia memanggil kamu, dan kamu mematuhi-Nya sambil memuji-Nya dan kamu mengira, (rasanya) hanya sebentar saja kamu berdiam (di dalam kubur)"},{id:53,text:"\u0648\u064e\u0642\u064f\u0644 \u0644\u0651\u0650\u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0651\u064e\u062a\u0650\u064a \u0647\u0650\u064a\u064e \u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064f\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u064e \u064a\u064e\u0646\u0632\u064e\u063a\u064f \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u064e \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u0650 \u0639\u064e\u062f\u064f\u0648\u0651\u0657\u0627 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u0657\u0627",translation:"Dan katakanlah kepada hamba-hamba-Ku, \"Hendaklah mereka mengucapkan perkataan yang lebih baik (benar). Sungguh, setan itu (selalu) menimbulkan perselisihan di antara mereka. Sungguh, setan adalah musuh yang nyata bagi manusia"},{id:54,text:"\u0631\u0651\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u06e1 \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0628\u0650\u0643\u064f\u0645\u06e1\u06d6 \u0625\u0650\u0646 \u064a\u064e\u0634\u064e\u0623\u06e1 \u064a\u064e\u0631\u06e1\u062d\u064e\u0645\u06e1\u0643\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1 \u0625\u0650\u0646 \u064a\u064e\u0634\u064e\u0623\u06e1 \u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u06e1\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0670\u0643\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0648\u064e\u0643\u0650\u064a\u0644\u0657\u0627",translation:"Tuhanmu lebih mengetahui tentang kamu. Jika Dia menghendaki, niscaya Dia akan memberi rahmat kepadamu, dan jika Dia menghendaki, pasti Dia akan mengazabmu. Dan Kami tidaklah mengutusmu (Muhammad) untuk menjadi penjaga bagi mereka"},{id:55,text:"\u0648\u064e\u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0646 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d7 \u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0641\u064e\u0636\u0651\u064e\u0644\u06e1\u0646\u064e\u0627 \u0628\u064e\u0639\u06e1\u0636\u064e \u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650\u0640\u06e7\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u06e1\u0636\u0656\u06d6 \u0648\u064e\u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0627 \u062f\u064e\u0627\u0648\u064f\u06e5\u062f\u064e \u0632\u064e\u0628\u064f\u0648\u0631\u0657\u0627",translation:"Dan Tuhanmu lebih mengetahui siapa yang di langit dan di bumi. Dan sungguh, Kami telah memberikan kelebihan kepada sebagian nabi-nabi atas sebagian (yang lain), dan Kami berikan Zabur kepada Dawud"},{id:56,text:"\u0642\u064f\u0644\u0650 \u0671\u062f\u06e1\u0639\u064f\u0648\u0627\u0652 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0632\u064e\u0639\u064e\u0645\u06e1\u062a\u064f\u0645 \u0645\u0651\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u06e6 \u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0645\u06e1\u0644\u0650\u0643\u064f\u0648\u0646\u064e \u0643\u064e\u0634\u06e1\u0641\u064e \u0671\u0644\u0636\u0651\u064f\u0631\u0651\u0650 \u0639\u064e\u0646\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062d\u06e1\u0648\u0650\u064a\u0644\u064b\u0627",translation:"Katakanlah (Muhammad), \"Panggillah mereka yang kamu anggap (tuhan)476) selain Allah, mereka tidak kuasa untuk menghilangkan bahaya darimu dan tidak (pula) mampu mengubahnya"},{id:57,text:"\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e \u064a\u064e\u0628\u06e1\u062a\u064e\u063a\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u064f \u0671\u0644\u06e1\u0648\u064e\u0633\u0650\u064a\u0644\u064e\u0629\u064e \u0623\u064e\u064a\u0651\u064f\u0647\u064f\u0645\u06e1 \u0623\u064e\u0642\u06e1\u0631\u064e\u0628\u064f \u0648\u064e\u064a\u064e\u0631\u06e1\u062c\u064f\u0648\u0646\u064e \u0631\u064e\u062d\u06e1\u0645\u064e\u062a\u064e\u0647\u064f\u06e5 \u0648\u064e\u064a\u064e\u062e\u064e\u0627\u0641\u064f\u0648\u0646\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u064e\u0647\u064f\u06e5\u0653\u06da \u0625\u0650\u0646\u0651\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0643\u064e\u0627\u0646\u064e \u0645\u064e\u062d\u06e1\u0630\u064f\u0648\u0631\u0657\u0627",translation:"(Orang-orang yang mereka seru itu, mereka sendiri mencari jalan kepada Tuhan477) siapa di antara mereka yang lebih dekat (kepada Allah). Mereka mengharapkan rahmat-Nya dan takut akan azab-Nya. Sungguh, azab Tuhanmu itu sesuatu yang (harus) ditakuti"},{id:58,text:"\u0648\u064e\u0625\u0650\u0646 \u0645\u0651\u0650\u0646 \u0642\u064e\u0631\u06e1\u064a\u064e\u0629\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0646\u064e\u062d\u06e1\u0646\u064f \u0645\u064f\u0647\u06e1\u0644\u0650\u0643\u064f\u0648\u0647\u064e\u0627 \u0642\u064e\u0628\u06e1\u0644\u064e \u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u0623\u064e\u0648\u06e1 \u0645\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064f\u0648\u0647\u064e\u0627 \u0639\u064e\u0630\u064e\u0627\u0628\u0657\u0627 \u0634\u064e\u062f\u0650\u064a\u062f\u0657\u0627\u06da \u0643\u064e\u0627\u0646\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0645\u064e\u0633\u06e1\u0637\u064f\u0648\u0631\u0657\u0627",translation:"Dan tidak ada suatu negeri pun (yang durhaka penduduknya), melainkan Kami membinasakannya sebelum hari Kiamat atau Kami siksa (penduduknya) dengan siksa yang sangat keras. Yang demikian itu telah tertulis di dalam Kitab (Lau\u1e25 Ma\u1e25f\u016b\u1e93)"},{id:59,text:"\u0648\u064e\u0645\u064e\u0627 \u0645\u064e\u0646\u064e\u0639\u064e\u0646\u064e\u0627\u0653 \u0623\u064e\u0646 \u0646\u0651\u064f\u0631\u06e1\u0633\u0650\u0644\u064e \u0628\u0650\u0671\u0644\u06e1\u0623\u0653\u064a\u064e\u0670\u062a\u0650 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0628\u0650\u0647\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0648\u0651\u064e\u0644\u064f\u0648\u0646\u064e\u06da \u0648\u064e\u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0627 \u062b\u064e\u0645\u064f\u0648\u062f\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0642\u064e\u0629\u064e \u0645\u064f\u0628\u06e1\u0635\u0650\u0631\u064e\u0629\u0657 \u0641\u064e\u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u064e\u0627\u06da \u0648\u064e\u0645\u064e\u0627 \u0646\u064f\u0631\u06e1\u0633\u0650\u0644\u064f \u0628\u0650\u0671\u0644\u06e1\u0623\u0653\u064a\u064e\u0670\u062a\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u062a\u064e\u062e\u06e1\u0648\u0650\u064a\u0641\u0657\u0627",translation:"Dan tidak ada yang menghalangi Kami untuk mengirimkan (kepadamu) tanda-tanda (kekuasaan Kami), melainkan karena (tanda-tanda) itu telah didustakan oleh orang terdahulu. Dan telah Kami berikan kepada kaum Samud unta betina (sebagai mukjizat) yang dapat dilihat, tetapi mereka menganiaya (unta betina itu). Dan Kami tidak mengirimkan tanda-tanda itu melainkan untuk menakut-nakuti"},{id:60,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0642\u064f\u0644\u06e1\u0646\u064e\u0627 \u0644\u064e\u0643\u064e \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0623\u064e\u062d\u064e\u0627\u0637\u064e \u0628\u0650\u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650\u06da \u0648\u064e\u0645\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0671\u0644\u0631\u0651\u064f\u0621\u06e1\u064a\u064e\u0627 \u0671\u0644\u0651\u064e\u062a\u0650\u064a\u0653 \u0623\u064e\u0631\u064e\u064a\u06e1\u0646\u064e\u0670\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0641\u0650\u062a\u06e1\u0646\u064e\u0629\u0657 \u0644\u0651\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0671\u0644\u0634\u0651\u064e\u062c\u064e\u0631\u064e\u0629\u064e \u0671\u0644\u06e1\u0645\u064e\u0644\u06e1\u0639\u064f\u0648\u0646\u064e\u0629\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u0650\u06da \u0648\u064e\u0646\u064f\u062e\u064e\u0648\u0651\u0650\u0641\u064f\u0647\u064f\u0645\u06e1 \u0641\u064e\u0645\u064e\u0627 \u064a\u064e\u0632\u0650\u064a\u062f\u064f\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u0637\u064f\u063a\u06e1\u064a\u064e\u0670\u0646\u0657\u0627 \u0643\u064e\u0628\u0650\u064a\u0631\u0657\u0627",translation:"Dan (ingatlah) ketika Kami wahyukan kepadamu, \"Sungguh, (ilmu) Tuhanmu meliputi seluruh manusia.\" Dan Kami tidak menjadikan mimpi478) yang telah Kami perlihatkan kepadamu, melainkan sebagai ujian bagi manusia dan (begitu pula) pohon yang terkutuk (zaqq\u016bm) dalam Alquran. Dan Kami menakut-nakuti mereka, tetapi yang demikian itu hanyalah menambah besar kedurhakaan mereka"},{id:61,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0642\u064f\u0644\u06e1\u0646\u064e\u0627 \u0644\u0650\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u0650 \u0671\u0633\u06e1\u062c\u064f\u062f\u064f\u0648\u0627\u0652 \u0644\u0650\u0623\u0653\u062f\u064e\u0645\u064e \u0641\u064e\u0633\u064e\u062c\u064e\u062f\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0625\u0650\u0628\u06e1\u0644\u0650\u064a\u0633\u064e \u0642\u064e\u0627\u0644\u064e \u0621\u064e\u0623\u064e\u0633\u06e1\u062c\u064f\u062f\u064f \u0644\u0650\u0645\u064e\u0646\u06e1 \u062e\u064e\u0644\u064e\u0642\u06e1\u062a\u064e \u0637\u0650\u064a\u0646\u0657\u0627",translation:"Dan (ingatlah), ketika Kami berfirman kepada para malaikat, \"Sujudlah kamu semua kepada Adam,\" lalu mereka sujud, kecuali Iblis. Ia (iblis) berkata, \"Apakah aku harus bersujud kepada orang yang Engkau ciptakan dari tanah"},{id:62,text:"\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0631\u064e\u0621\u064e\u064a\u06e1\u062a\u064e\u0643\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0643\u064e\u0631\u0651\u064e\u0645\u06e1\u062a\u064e \u0639\u064e\u0644\u064e\u064a\u0651\u064e \u0644\u064e\u0626\u0650\u0646\u06e1 \u0623\u064e\u062e\u0651\u064e\u0631\u06e1\u062a\u064e\u0646\u0650 \u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u0644\u064e\u0623\u064e\u062d\u06e1\u062a\u064e\u0646\u0650\u0643\u064e\u0646\u0651\u064e \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u062a\u064e\u0647\u064f\u06e5\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u0657\u0627",translation:"Ia (Iblis) berkata, \"Terangkanlah kepadaku, inikah yang lebih Engkau muliakan daripada aku? Sekiranya Engkau memberi waktu kepadaku sampai hari Kiamat, pasti akan aku sesatkan keturunannya, kecuali sebagian kecil"},{id:63,text:"\u0642\u064e\u0627\u0644\u064e \u0671\u0630\u06e1\u0647\u064e\u0628\u06e1 \u0641\u064e\u0645\u064e\u0646 \u062a\u064e\u0628\u0650\u0639\u064e\u0643\u064e \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u062c\u064e\u0632\u064e\u0627\u0653\u0624\u064f\u0643\u064f\u0645\u06e1 \u062c\u064e\u0632\u064e\u0627\u0653\u0621\u0657 \u0645\u0651\u064e\u0648\u06e1\u0641\u064f\u0648\u0631\u0657\u0627",translation:"Dia (Allah) berfirman, \"Pergilah, tetapi barang siapa di antara mereka yang mengikuti kamu, maka sungguh, neraka Jahanamlah balasanmu semua, sebagai pembalasan yang cukup"},{id:64,text:"\u0648\u064e\u0671\u0633\u06e1\u062a\u064e\u0641\u06e1\u0632\u0650\u0632\u06e1 \u0645\u064e\u0646\u0650 \u0671\u0633\u06e1\u062a\u064e\u0637\u064e\u0639\u06e1\u062a\u064e \u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0628\u0650\u0635\u064e\u0648\u06e1\u062a\u0650\u0643\u064e \u0648\u064e\u0623\u064e\u062c\u06e1\u0644\u0650\u0628\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0628\u0650\u062e\u064e\u064a\u06e1\u0644\u0650\u0643\u064e \u0648\u064e\u0631\u064e\u062c\u0650\u0644\u0650\u0643\u064e \u0648\u064e\u0634\u064e\u0627\u0631\u0650\u0643\u06e1\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0648\u06e1\u0644\u064e\u0670\u062f\u0650 \u0648\u064e\u0639\u0650\u062f\u06e1\u0647\u064f\u0645\u06e1\u06da \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0639\u0650\u062f\u064f\u0647\u064f\u0645\u064f \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u063a\u064f\u0631\u064f\u0648\u0631\u064b\u0627",translation:"Dan perdayakanlah siapa saja di antara mereka yang engkau (iblis) sanggup dengan suaramu (yang memukau), kerahkanlah pasukanmu terhadap mereka, yang berkuda dan yang berjalan kaki, dan bersekutulah dengan mereka pada harta dan anak-anak lalu beri janjilah kepada mereka.\" Padahal setan itu hanya menjanjikan tipuan belaka kepada mereka"},{id:65,text:"\u0625\u0650\u0646\u0651\u064e \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a \u0644\u064e\u064a\u06e1\u0633\u064e \u0644\u064e\u0643\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0633\u064f\u0644\u06e1\u0637\u064e\u0670\u0646\u065e\u06da \u0648\u064e\u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0648\u064e\u0643\u0650\u064a\u0644\u0657\u0627",translation:"Sesungguhnya (terhadap) hamba-hamba-Ku, engkau (Iblis) tidaklah dapat berkuasa atas mereka. Dan cukuplah Tuhanmu sebagai penjaga"},{id:66,text:"\u0631\u0651\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u0632\u06e1\u062c\u0650\u064a \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0641\u064f\u0644\u06e1\u0643\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0628\u064e\u062d\u06e1\u0631\u0650 \u0644\u0650\u062a\u064e\u0628\u06e1\u062a\u064e\u063a\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0641\u064e\u0636\u06e1\u0644\u0650\u0647\u0650\u06e6\u0653\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0643\u064e\u0627\u0646\u064e \u0628\u0650\u0643\u064f\u0645\u06e1 \u0631\u064e\u062d\u0650\u064a\u0645\u0657\u0627",translation:"Tuhanmulah yang melayarkan kapal-kapal di lautan untukmu, agar kamu mencari karunia-Nya. Sungguh, Dia Maha Penyayang terhadapmu"},{id:67,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0633\u0651\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0636\u0651\u064f\u0631\u0651\u064f \u0641\u0650\u064a \u0671\u0644\u06e1\u0628\u064e\u062d\u06e1\u0631\u0650 \u0636\u064e\u0644\u0651\u064e \u0645\u064e\u0646 \u062a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0625\u0650\u064a\u0651\u064e\u0627\u0647\u064f\u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0646\u064e\u062c\u0651\u064e\u0649\u0670\u0643\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u0628\u064e\u0631\u0651\u0650 \u0623\u064e\u0639\u06e1\u0631\u064e\u0636\u06e1\u062a\u064f\u0645\u06e1\u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064f \u0643\u064e\u0641\u064f\u0648\u0631\u064b\u0627",translation:"Dan apabila kamu ditimpa bahaya di lautan, niscaya hilang semua yang (biasa) kamu seru, kecuali Dia. Tetapi ketika Dia menyelamatkan kamu ke daratan, kamu berpaling (dari-Nya). Dan manusia memang selalu ingkar (tidak bersyukur)"},{id:68,text:"\u0623\u064e\u0641\u064e\u0623\u064e\u0645\u0650\u0646\u062a\u064f\u0645\u06e1 \u0623\u064e\u0646 \u064a\u064e\u062e\u06e1\u0633\u0650\u0641\u064e \u0628\u0650\u0643\u064f\u0645\u06e1 \u062c\u064e\u0627\u0646\u0650\u0628\u064e \u0671\u0644\u06e1\u0628\u064e\u0631\u0651\u0650 \u0623\u064e\u0648\u06e1 \u064a\u064f\u0631\u06e1\u0633\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u062d\u064e\u0627\u0635\u0650\u0628\u0657\u0627 \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0627 \u062a\u064e\u062c\u0650\u062f\u064f\u0648\u0627\u0652 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0643\u0650\u064a\u0644\u064b\u0627",translation:"Maka apakah kamu merasa aman bahwa Dia tidak akan membenamkan sebagian daratan bersama kamu atau dia meniupkan (angin keras yang membawa) batu-batu kecil? Dan kamu tidak akan mendapat seorang pelindung pun"},{id:69,text:"\u0623\u064e\u0645\u06e1 \u0623\u064e\u0645\u0650\u0646\u062a\u064f\u0645\u06e1 \u0623\u064e\u0646 \u064a\u064f\u0639\u0650\u064a\u062f\u064e\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u0650 \u062a\u064e\u0627\u0631\u064e\u0629\u064b \u0623\u064f\u062e\u06e1\u0631\u064e\u0649\u0670 \u0641\u064e\u064a\u064f\u0631\u06e1\u0633\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0642\u064e\u0627\u0635\u0650\u0641\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0631\u0651\u0650\u064a\u062d\u0650 \u0641\u064e\u064a\u064f\u063a\u06e1\u0631\u0650\u0642\u064e\u0643\u064f\u0645 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0641\u064e\u0631\u06e1\u062a\u064f\u0645\u06e1 \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0627 \u062a\u064e\u062c\u0650\u062f\u064f\u0648\u0627\u0652 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0628\u0650\u0647\u0650\u06e6 \u062a\u064e\u0628\u0650\u064a\u0639\u0657\u0627",translation:"ataukah kamu merasa aman bahwa Dia tidak akan mengembalikan kamu ke laut sekali lagi, lalu Dia tiupkan angin topan kepada kamu lalu kamu ditenggelamkan-Nya disebabkan kekafiranmu? Kemudian kamu tidak akan mendapat seorang penolong pun dalam menghadapi (siksaan) Kami"},{id:70,text:"\u06de\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0643\u064e\u0631\u0651\u064e\u0645\u06e1\u0646\u064e\u0627 \u0628\u064e\u0646\u0650\u064a\u0653 \u0621\u064e\u0627\u062f\u064e\u0645\u064e \u0648\u064e\u062d\u064e\u0645\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0628\u064e\u0631\u0651\u0650 \u0648\u064e\u0671\u0644\u06e1\u0628\u064e\u062d\u06e1\u0631\u0650 \u0648\u064e\u0631\u064e\u0632\u064e\u0642\u06e1\u0646\u064e\u0670\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0637\u0651\u064e\u064a\u0651\u0650\u0628\u064e\u0670\u062a\u0650 \u0648\u064e\u0641\u064e\u0636\u0651\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064e\u062b\u0650\u064a\u0631\u0656 \u0645\u0651\u0650\u0645\u0651\u064e\u0646\u06e1 \u062e\u064e\u0644\u064e\u0642\u06e1\u0646\u064e\u0627 \u062a\u064e\u0641\u06e1\u0636\u0650\u064a\u0644\u0657\u0627",translation:"Dan sungguh, Kami telah memuliakan anak cucu Adam, dan Kami angkut mereka di darat dan di laut, dan Kami beri mereka rezeki dari yang baik-baik dan Kami lebihkan mereka di atas banyak makhluk yang Kami ciptakan dengan kelebihan yang sempurna"},{id:71,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u0646\u064e\u062f\u06e1\u0639\u064f\u0648\u0627\u0652 \u0643\u064f\u0644\u0651\u064e \u0623\u064f\u0646\u064e\u0627\u0633\u0650\u06ed \u0628\u0650\u0625\u0650\u0645\u064e\u0670\u0645\u0650\u0647\u0650\u0645\u06e1\u06d6 \u0641\u064e\u0645\u064e\u0646\u06e1 \u0623\u064f\u0648\u062a\u0650\u064a\u064e \u0643\u0650\u062a\u064e\u0670\u0628\u064e\u0647\u064f\u06e5 \u0628\u0650\u064a\u064e\u0645\u0650\u064a\u0646\u0650\u0647\u0650\u06e6 \u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u064a\u064e\u0642\u06e1\u0631\u064e\u0621\u064f\u0648\u0646\u064e \u0643\u0650\u062a\u064e\u0670\u0628\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0638\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0641\u064e\u062a\u0650\u064a\u0644\u0657\u0627",translation:"(Ingatlah), pada hari (ketika) Kami panggil setiap umat dengan pemimpinnya; dan barangsiapa diberikan catatan amalnya di tangan kanannya mereka akan membaca catatannya (dengan baik), dan mereka tidak akan dirugikan sedikit pun"},{id:72,text:"\u0648\u064e\u0645\u064e\u0646 \u0643\u064e\u0627\u0646\u064e \u0641\u0650\u064a \u0647\u064e\u0670\u0630\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0639\u06e1\u0645\u064e\u0649\u0670 \u0641\u064e\u0647\u064f\u0648\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0623\u064e\u0639\u06e1\u0645\u064e\u0649\u0670 \u0648\u064e\u0623\u064e\u0636\u064e\u0644\u0651\u064f \u0633\u064e\u0628\u0650\u064a\u0644\u0657\u0627",translation:"Dan barangsiapa buta (hatinya) di dunia ini, maka di akhirat dia akan buta dan tersesat jauh dari jalan (yang benar)"},{id:73,text:"\u0648\u064e\u0625\u0650\u0646 \u0643\u064e\u0627\u062f\u064f\u0648\u0627\u0652 \u0644\u064e\u064a\u064e\u0641\u06e1\u062a\u0650\u0646\u064f\u0648\u0646\u064e\u0643\u064e \u0639\u064e\u0646\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064e\u0648\u06e1\u062d\u064e\u064a\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0644\u0650\u062a\u064e\u0641\u06e1\u062a\u064e\u0631\u0650\u064a\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u063a\u064e\u064a\u06e1\u0631\u064e\u0647\u064f\u06e5\u06d6 \u0648\u064e\u0625\u0650\u0630\u0657\u0627 \u0644\u0651\u064e\u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0643\u064e \u062e\u064e\u0644\u0650\u064a\u0644\u0657\u0627",translation:"Dan mereka hampir memalingkan engkau (Muhammad) dari apa yang telah Kami wahyukan kepadamu, agar engkau mengada-ada yang lain terhadap Kami; dan jika demikian tentu mereka menjadikan engkau sahabat yang setia"},{id:74,text:"\u0648\u064e\u0644\u064e\u0648\u06e1\u0644\u064e\u0627\u0653 \u0623\u064e\u0646 \u062b\u064e\u0628\u0651\u064e\u062a\u06e1\u0646\u064e\u0670\u0643\u064e \u0644\u064e\u0642\u064e\u062f\u06e1 \u0643\u0650\u062f\u062a\u0651\u064e \u062a\u064e\u0631\u06e1\u0643\u064e\u0646\u064f \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627",translation:"Dan sekiranya Kami tidak memperteguh (hati)mu, niscaya engkau hampir saja condong sedikit kepada mereka"},{id:75,text:"\u0625\u0650\u0630\u0657\u0627 \u0644\u0651\u064e\u0623\u064e\u0630\u064e\u0642\u06e1\u0646\u064e\u0670\u0643\u064e \u0636\u0650\u0639\u06e1\u0641\u064e \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u0650 \u0648\u064e\u0636\u0650\u0639\u06e1\u0641\u064e \u0671\u0644\u06e1\u0645\u064e\u0645\u064e\u0627\u062a\u0650 \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0627 \u062a\u064e\u062c\u0650\u062f\u064f \u0644\u064e\u0643\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0646\u064e\u0635\u0650\u064a\u0631\u0657\u0627",translation:"Jika demikian, tentu akan Kami rasakan kepadamu (siksaan) berlipat ganda di dunia ini dan berlipat ganda setelah mati, dan engkau (Muhammad) tidak akan mendapat seorang penolong pun terhadap Kami"},{id:76,text:"\u0648\u064e\u0625\u0650\u0646 \u0643\u064e\u0627\u062f\u064f\u0648\u0627\u0652 \u0644\u064e\u064a\u064e\u0633\u06e1\u062a\u064e\u0641\u0650\u0632\u0651\u064f\u0648\u0646\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0644\u0650\u064a\u064f\u062e\u06e1\u0631\u0650\u062c\u064f\u0648\u0643\u064e \u0645\u0650\u0646\u06e1\u0647\u064e\u0627\u06d6 \u0648\u064e\u0625\u0650\u0630\u0657\u0627 \u0644\u0651\u064e\u0627 \u064a\u064e\u0644\u06e1\u0628\u064e\u062b\u064f\u0648\u0646\u064e \u062e\u0650\u0644\u064e\u0670\u0641\u064e\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u0657\u0627",translation:"Dan sungguh, mereka hampir membuatmu (Muhammad) gelisah di negeri (Mekkah) karena engkau harus keluar dari negeri itu, dan kalau terjadi demikian, niscaya sepeninggalmu mereka tidak akan tinggal (di sana), melainkan sebentar saja"},{id:77,text:"\u0633\u064f\u0646\u0651\u064e\u0629\u064e \u0645\u064e\u0646 \u0642\u064e\u062f\u06e1 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0642\u064e\u0628\u06e1\u0644\u064e\u0643\u064e \u0645\u0650\u0646 \u0631\u0651\u064f\u0633\u064f\u0644\u0650\u0646\u064e\u0627\u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062c\u0650\u062f\u064f \u0644\u0650\u0633\u064f\u0646\u0651\u064e\u062a\u0650\u0646\u064e\u0627 \u062a\u064e\u062d\u06e1\u0648\u0650\u064a\u0644\u064b\u0627",translation:"(Yang demikian itu) merupakan ketetapan bagi para rasul Kami yang Kami utus sebelum engkau,480) dan tidak akan engkau dapati perubahan atas ketetapan Kami"},{id:78,text:"\u0623\u064e\u0642\u0650\u0645\u0650 \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e \u0644\u0650\u062f\u064f\u0644\u064f\u0648\u0643\u0650 \u0671\u0644\u0634\u0651\u064e\u0645\u06e1\u0633\u0650 \u0625\u0650\u0644\u064e\u0649\u0670 \u063a\u064e\u0633\u064e\u0642\u0650 \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u0650 \u0648\u064e\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u064e \u0671\u0644\u06e1\u0641\u064e\u062c\u06e1\u0631\u0650\u06d6 \u0625\u0650\u0646\u0651\u064e \u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u064e \u0671\u0644\u06e1\u0641\u064e\u062c\u06e1\u0631\u0650 \u0643\u064e\u0627\u0646\u064e \u0645\u064e\u0634\u06e1\u0647\u064f\u0648\u062f\u0657\u0627",translation:"Laksanakanlah salat sejak matahari tergelincir sampai gelapnya malam dan (laksanakan pula salat) Subuh.481) Sungguh, salat subuh itu disaksikan (oleh malaikat)"},{id:79,text:"\u0648\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u0650 \u0641\u064e\u062a\u064e\u0647\u064e\u062c\u0651\u064e\u062f\u06e1 \u0628\u0650\u0647\u0650\u06e6 \u0646\u064e\u0627\u0641\u0650\u0644\u064e\u0629\u0657 \u0644\u0651\u064e\u0643\u064e \u0639\u064e\u0633\u064e\u0649\u0670\u0653 \u0623\u064e\u0646 \u064a\u064e\u0628\u06e1\u0639\u064e\u062b\u064e\u0643\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0645\u064e\u0642\u064e\u0627\u0645\u0657\u0627 \u0645\u0651\u064e\u062d\u06e1\u0645\u064f\u0648\u062f\u0657\u0627",translation:"Dan pada sebagian malam, lakukanlah salat tahajud (sebagai suatu ibadah) tambahan bagimu: mudah-mudahan Tuhanmu mengangkatmu ke tempat yang terpuji"},{id:80,text:"\u0648\u064e\u0642\u064f\u0644 \u0631\u0651\u064e\u0628\u0651\u0650 \u0623\u064e\u062f\u06e1\u062e\u0650\u0644\u06e1\u0646\u0650\u064a \u0645\u064f\u062f\u06e1\u062e\u064e\u0644\u064e \u0635\u0650\u062f\u06e1\u0642\u0656 \u0648\u064e\u0623\u064e\u062e\u06e1\u0631\u0650\u062c\u06e1\u0646\u0650\u064a \u0645\u064f\u062e\u06e1\u0631\u064e\u062c\u064e \u0635\u0650\u062f\u06e1\u0642\u0656 \u0648\u064e\u0671\u062c\u06e1\u0639\u064e\u0644 \u0644\u0651\u0650\u064a \u0645\u0650\u0646 \u0644\u0651\u064e\u062f\u064f\u0646\u0643\u064e \u0633\u064f\u0644\u06e1\u0637\u064e\u0670\u0646\u0657\u0627 \u0646\u0651\u064e\u0635\u0650\u064a\u0631\u0657\u0627",translation:"Dan katakanlah (Muhammad), ya Tuhanku, masukkan aku ke tempat masuk yang benar dan keluarkan (pula) aku ke tempat keluar yang benar dan berikanlah kepadaku dari sisi-Mu kekuasaan yang dapat menolong-(Ku)"},{id:81,text:"\u0648\u064e\u0642\u064f\u0644\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f \u0648\u064e\u0632\u064e\u0647\u064e\u0642\u064e \u0671\u0644\u06e1\u0628\u064e\u0670\u0637\u0650\u0644\u064f\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0628\u064e\u0670\u0637\u0650\u0644\u064e \u0643\u064e\u0627\u0646\u064e \u0632\u064e\u0647\u064f\u0648\u0642\u0657\u0627",translation:"Dan katakanlah, \"Kebenaran telah datang dan yang batil telah lenyap.\" Sungguh, yang batil itu pasti lenyap"},{id:82,text:"\u0648\u064e\u0646\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u0650 \u0645\u064e\u0627 \u0647\u064f\u0648\u064e \u0634\u0650\u0641\u064e\u0627\u0653\u0621\u065e \u0648\u064e\u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u065e \u0644\u0651\u0650\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0632\u0650\u064a\u062f\u064f \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u062e\u064e\u0633\u064e\u0627\u0631\u0657\u0627",translation:"Dan Kami turunkan dari Alquran (sesuatu) yang menjadi penawar dan rahmat bagi orang yang beriman, sedangkan bagi orang yang zalim (Alquran itu) hanya akan menambah kerugian"},{id:83,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627\u0653 \u0623\u064e\u0646\u06e1\u0639\u064e\u0645\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u0650 \u0623\u064e\u0639\u06e1\u0631\u064e\u0636\u064e \u0648\u064e\u0646\u064e\u0640\u0654\u064e\u0627 \u0628\u0650\u062c\u064e\u0627\u0646\u0650\u0628\u0650\u0647\u0650\u06e6 \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0633\u0651\u064e\u0647\u064f \u0671\u0644\u0634\u0651\u064e\u0631\u0651\u064f \u0643\u064e\u0627\u0646\u064e \u064a\u064e\u0640\u0654\u064f\u0648\u0633\u0657\u0627",translation:"Dan apabila Kami berikan kesenangan pada manusia, niscaya dia berpaling dan menjauhkan diri dengan sombong; dan apabila dia ditimpa kesusahan, niscaya dia berputus asa"},{id:84,text:"\u0642\u064f\u0644\u06e1 \u0643\u064f\u0644\u0651\u065e \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0634\u064e\u0627\u0643\u0650\u0644\u064e\u062a\u0650\u0647\u0650\u06e6 \u0641\u064e\u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u06e1 \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0646\u06e1 \u0647\u064f\u0648\u064e \u0623\u064e\u0647\u06e1\u062f\u064e\u0649\u0670 \u0633\u064e\u0628\u0650\u064a\u0644\u0657\u0627",translation:"Katakanlah (Muhammad), \"Setiap orang berbuat sesuai dengan pembawaannya masing-masing.\" Maka Tuhanmu lebih mengetahui siapa yang lebih benar jalannya"},{id:85,text:"\u0648\u064e\u064a\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u0639\u064e\u0646\u0650 \u0671\u0644\u0631\u0651\u064f\u0648\u062d\u0650\u06d6 \u0642\u064f\u0644\u0650 \u0671\u0644\u0631\u0651\u064f\u0648\u062d\u064f \u0645\u0650\u0646\u06e1 \u0623\u064e\u0645\u06e1\u0631\u0650 \u0631\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0648\u062a\u0650\u064a\u062a\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0639\u0650\u0644\u06e1\u0645\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u0657\u0627",translation:"Dan mereka bertanya kepadamu (Muhammad) tentang roh. Katakanlah, \"Roh itu termasuk urusan Tuhanku, sedangkan kamu diberi pengetahuan hanya sedikit"},{id:86,text:"\u0648\u064e\u0644\u064e\u0626\u0650\u0646 \u0634\u0650\u0626\u06e1\u0646\u064e\u0627 \u0644\u064e\u0646\u064e\u0630\u06e1\u0647\u064e\u0628\u064e\u0646\u0651\u064e \u0628\u0650\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064e\u0648\u06e1\u062d\u064e\u064a\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0627 \u062a\u064e\u062c\u0650\u062f\u064f \u0644\u064e\u0643\u064e \u0628\u0650\u0647\u0650\u06e6 \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0648\u064e\u0643\u0650\u064a\u0644\u064b\u0627",translation:"Dan sesungguhnya jika Kami menghendaki, niscaya Kami lenyapkan apa yang telah Kami wahyukan kepadamu (Muhammad), dan engkau tidak akan mendapatkan seorang pembela pun terhadap Kami"},{id:87,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u0657 \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064e\u06da \u0625\u0650\u0646\u0651\u064e \u0641\u064e\u0636\u06e1\u0644\u064e\u0647\u064f\u06e5 \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0643\u064e\u0628\u0650\u064a\u0631\u0657\u0627",translation:"kecuali karena rahmat dari Tuhanmu. Sungguh, karunia-Nya atasmu (Muhammad) sangat besar"},{id:88,text:"\u0642\u064f\u0644 \u0644\u0651\u064e\u0626\u0650\u0646\u0650 \u0671\u062c\u06e1\u062a\u064e\u0645\u064e\u0639\u064e\u062a\u0650 \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064f \u0648\u064e\u0671\u0644\u06e1\u062c\u0650\u0646\u0651\u064f \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0646 \u064a\u064e\u0623\u06e1\u062a\u064f\u0648\u0627\u0652 \u0628\u0650\u0645\u0650\u062b\u06e1\u0644\u0650 \u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u0650 \u0644\u064e\u0627 \u064a\u064e\u0623\u06e1\u062a\u064f\u0648\u0646\u064e \u0628\u0650\u0645\u0650\u062b\u06e1\u0644\u0650\u0647\u0650\u06e6 \u0648\u064e\u0644\u064e\u0648\u06e1 \u0643\u064e\u0627\u0646\u064e \u0628\u064e\u0639\u06e1\u0636\u064f\u0647\u064f\u0645\u06e1 \u0644\u0650\u0628\u064e\u0639\u06e1\u0636\u0656 \u0638\u064e\u0647\u0650\u064a\u0631\u0657\u0627",translation:"Katakanlah, \"Sesungguhnya jika manusia dan jin berkumpul untuk membuat yang serupa (dengan) Alquran ini, mereka tidak akan dapat membuat yang serupa dengannya, sekali pun mereka saling membantu satu sama lain"},{id:89,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0635\u064e\u0631\u0651\u064e\u0641\u06e1\u0646\u064e\u0627 \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0641\u0650\u064a \u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u0650 \u0645\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u0645\u064e\u062b\u064e\u0644\u0656 \u0641\u064e\u0623\u064e\u0628\u064e\u0649\u0670\u0653 \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064f\u0641\u064f\u0648\u0631\u0657\u0627",translation:"Dan sungguh, Kami telah menjelaskan berulang-ulang kepada manusia dalam Alquran ini dengan bermacam-macam perumpamaan, tetapi kebanyakan manusia tidak menyukainya bahkan mengingkari(nya)"},{id:90,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0646 \u0646\u0651\u064f\u0624\u06e1\u0645\u0650\u0646\u064e \u0644\u064e\u0643\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062a\u064e\u0641\u06e1\u062c\u064f\u0631\u064e \u0644\u064e\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u064a\u064e\u0646\u06e2\u0628\u064f\u0648\u0639\u064b\u0627",translation:"Dan mereka berkata, \"Kami tidak akan percaya kepadamu (Muhammad) sebelum engkau memancarkan mata air dari bumi untuk kami"},{id:91,text:"\u0623\u064e\u0648\u06e1 \u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0644\u064e\u0643\u064e \u062c\u064e\u0646\u0651\u064e\u0629\u065e \u0645\u0651\u0650\u0646 \u0646\u0651\u064e\u062e\u0650\u064a\u0644\u0656 \u0648\u064e\u0639\u0650\u0646\u064e\u0628\u0656 \u0641\u064e\u062a\u064f\u0641\u064e\u062c\u0651\u0650\u0631\u064e \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u064e \u062e\u0650\u0644\u064e\u0670\u0644\u064e\u0647\u064e\u0627 \u062a\u064e\u0641\u06e1\u062c\u0650\u064a\u0631\u064b\u0627",translation:"atau engkau mempunyai sebuah kebun kurma dan anggur, lalu engkau alirkan di celah-celahnya sungai yang deras alirannya"},{id:92,text:"\u0623\u064e\u0648\u06e1 \u062a\u064f\u0633\u06e1\u0642\u0650\u0637\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u064e \u0643\u064e\u0645\u064e\u0627 \u0632\u064e\u0639\u064e\u0645\u06e1\u062a\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0643\u0650\u0633\u064e\u0641\u064b\u0627 \u0623\u064e\u0648\u06e1 \u062a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u0650 \u0642\u064e\u0628\u0650\u064a\u0644\u064b\u0627",translation:"atau engkau jatuhkan langit berkeping-keping atas kami, sebagaimana engkau katakan, atau (sebelum) engkau datangkan Allah dan para malaikat berhadapan muka dengan kami"},{id:93,text:"\u0623\u064e\u0648\u06e1 \u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0644\u064e\u0643\u064e \u0628\u064e\u064a\u06e1\u062a\u065e \u0645\u0651\u0650\u0646 \u0632\u064f\u062e\u06e1\u0631\u064f\u0641\u064d \u0623\u064e\u0648\u06e1 \u062a\u064e\u0631\u06e1\u0642\u064e\u0649\u0670 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0648\u064e\u0644\u064e\u0646 \u0646\u0651\u064f\u0624\u06e1\u0645\u0650\u0646\u064e \u0644\u0650\u0631\u064f\u0642\u0650\u064a\u0651\u0650\u0643\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062a\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0643\u0650\u062a\u064e\u0670\u0628\u0657\u0627 \u0646\u0651\u064e\u0642\u06e1\u0631\u064e\u0624\u064f\u0647\u064f\u06e5\u06d7 \u0642\u064f\u0644\u06e1 \u0633\u064f\u0628\u06e1\u062d\u064e\u0627\u0646\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0647\u064e\u0644\u06e1 \u0643\u064f\u0646\u062a\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u064e\u0634\u064e\u0631\u0657\u0627 \u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0657\u0627",translation:"atau engkau mempunyai satu rumah (terbuat) dari emas, atau engkau naik ke langit. Dan kami tidak akan mempercayai kenaikanmu itu sebelum engkau turunkan kepada kami satu kitab untuk kami baca.\" Katakanlah (Muhammad), \"Mahasuci Tuhanku, bukankah aku ini hanya seorang manusia yang menjadi rasul"},{id:94,text:"\u0648\u064e\u0645\u064e\u0627 \u0645\u064e\u0646\u064e\u0639\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0623\u064e\u0646 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0630\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0647\u064f\u062f\u064e\u0649\u0670\u0653 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0628\u064e\u0639\u064e\u062b\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u064e\u0634\u064e\u0631\u0657\u0627 \u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0657\u0627",translation:"Dan tidak ada sesuatu yang menghalangi manusia untuk beriman ketika petunjuk datang kepadanya, selain perkataan mereka, \"Mengapa Allah mengutus seorang manusia menjadi rasul"},{id:95,text:"\u0642\u064f\u0644 \u0644\u0651\u064e\u0648\u06e1 \u0643\u064e\u0627\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u065e \u064a\u064e\u0645\u06e1\u0634\u064f\u0648\u0646\u064e \u0645\u064f\u0637\u06e1\u0645\u064e\u0626\u0650\u0646\u0651\u0650\u064a\u0646\u064e \u0644\u064e\u0646\u064e\u0632\u0651\u064e\u0644\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0645\u064e\u0644\u064e\u0643\u0657\u0627 \u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0657\u0627",translation:"Katakanlah (Muhammad), \"Sekiranya di bumi ada para malaikat, yang berjalan-jalan dengan tenang, niscaya Kami turunkan kepada mereka malaikat dari langit untuk menjadi rasul"},{id:96,text:"\u0642\u064f\u0644\u06e1 \u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0634\u064e\u0647\u0650\u064a\u062f\u064e\u06e2\u0627 \u0628\u064e\u064a\u06e1\u0646\u0650\u064a \u0648\u064e\u0628\u064e\u064a\u06e1\u0646\u064e\u0643\u064f\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0643\u064e\u0627\u0646\u064e \u0628\u0650\u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650\u06e6 \u062e\u064e\u0628\u0650\u064a\u0631\u064e\u06e2\u0627 \u0628\u064e\u0635\u0650\u064a\u0631\u0657\u0627",translation:"Katakanlah (Muhammad), \"Cukuplah Allah menjadi saksi antara aku dan kamu sekalian. Sungguh, Dia Maha Mengetahui, Maha Melihat akan hamba-hamba-Nya"},{id:97,text:"\u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0647\u06e1\u062f\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0645\u064f\u0647\u06e1\u062a\u064e\u062f\u0650\u06d6 \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0636\u06e1\u0644\u0650\u0644\u06e1 \u0641\u064e\u0644\u064e\u0646 \u062a\u064e\u062c\u0650\u062f\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1\u0644\u0650\u064a\u064e\u0627\u0653\u0621\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u0646\u064e\u062d\u06e1\u0634\u064f\u0631\u064f\u0647\u064f\u0645\u06e1 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u0639\u064e\u0644\u064e\u0649\u0670 \u0648\u064f\u062c\u064f\u0648\u0647\u0650\u0647\u0650\u0645\u06e1 \u0639\u064f\u0645\u06e1\u064a\u0657\u0627 \u0648\u064e\u0628\u064f\u0643\u06e1\u0645\u0657\u0627 \u0648\u064e\u0635\u064f\u0645\u0651\u0657\u0627\u06d6 \u0645\u0651\u064e\u0623\u06e1\u0648\u064e\u0649\u0670\u0647\u064f\u0645\u06e1 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064f\u06d6 \u0643\u064f\u0644\u0651\u064e\u0645\u064e\u0627 \u062e\u064e\u0628\u064e\u062a\u06e1 \u0632\u0650\u062f\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0633\u064e\u0639\u0650\u064a\u0631\u0657\u0627",translation:"Dan barangsiapa diberi petunjuk oleh Allah, dialah yang mendapat petunjuk, dan barangsiapa Dia sesatkan, maka engkau tidak akan mendapat penolong-penolong bagi mereka selain Dia. Dan Kami akan mengumpulkan mereka pada hari Kiamat dengan wajah tersungkur, dalam keadaan buta, bisu, dan tuli. Tempat kediaman mereka adalah neraka Jahanam. Setiap kali nyala api Jahanam itu akan padam, Kami tambah lagi nyalanya bagi mereka"},{id:98,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062c\u064e\u0632\u064e\u0627\u0653\u0624\u064f\u0647\u064f\u0645 \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0621\u0650\u0630\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0639\u0650\u0638\u064e\u0670\u0645\u0657\u0627 \u0648\u064e\u0631\u064f\u0641\u064e\u0670\u062a\u064b\u0627 \u0623\u064e\u0621\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0645\u064e\u0628\u06e1\u0639\u064f\u0648\u062b\u064f\u0648\u0646\u064e \u062e\u064e\u0644\u06e1\u0642\u0657\u0627 \u062c\u064e\u062f\u0650\u064a\u062f\u064b\u0627",translation:"Itulah balasan bagi mereka, karena sesungguhnya mereka kafir kepada ayat-ayat Kami dan (karena mereka) berkata, \"Apabila kami telah menjadi tulang belulang dan benda-benda yang hancur, apakah kami benar-benar akan dibangkitkan kembali sebagai makhluk baru"},{id:99,text:"\u06de\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0631\u064e\u0648\u06e1\u0627\u0652 \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0642\u064e\u0627\u062f\u0650\u0631\u064c \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0646 \u064a\u064e\u062e\u06e1\u0644\u064f\u0642\u064e \u0645\u0650\u062b\u06e1\u0644\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u062c\u064e\u0644\u0657\u0627 \u0644\u0651\u064e\u0627 \u0631\u064e\u064a\u06e1\u0628\u064e \u0641\u0650\u064a\u0647\u0650 \u0641\u064e\u0623\u064e\u0628\u064e\u0649 \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064f\u0641\u064f\u0648\u0631\u0657\u0627",translation:"Dan apakah mereka tidak memperhatikan bahwa Allah yang menciptakan langit dan bumi adalah Mahakuasa (pula) menciptakan yang serupa dengan mereka, dan Dia telah menetapkan waktu tertentu (mati atau dibangkitkan) bagi mereka, yang tidak diragukan lagi? Maka orang zalim itu tidak menolaknya kecuali dengan kekafiran"},{id:100,text:"\u0642\u064f\u0644 \u0644\u0651\u064e\u0648\u06e1 \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0645\u06e1\u0644\u0650\u0643\u064f\u0648\u0646\u064e \u062e\u064e\u0632\u064e\u0627\u0653\u0626\u0650\u0646\u064e \u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u0650 \u0631\u064e\u0628\u0651\u0650\u064a\u0653 \u0625\u0650\u0630\u0657\u0627 \u0644\u0651\u064e\u0623\u064e\u0645\u06e1\u0633\u064e\u0643\u06e1\u062a\u064f\u0645\u06e1 \u062e\u064e\u0634\u06e1\u064a\u064e\u0629\u064e \u0671\u0644\u06e1\u0625\u0650\u0646\u0641\u064e\u0627\u0642\u0650\u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064f \u0642\u064e\u062a\u064f\u0648\u0631\u0657\u0627",translation:"Katakanlah (Muhammad), \"Sekiranya kamu menguasai perbendaharaan rahmat Tuhanku, niscaya (perbendaharaan) itu kamu tahan, karena takut membelanjakannya.\" Dan manusia itu memang sangat kikir"},{id:101,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u062a\u0650\u0633\u06e1\u0639\u064e \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u06ed \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0656\u06d6 \u0641\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u06e1 \u0628\u064e\u0646\u0650\u064a\u0653 \u0625\u0650\u0633\u06e1\u0631\u064e\u0640\u0670\u0653\u0621\u0650\u064a\u0644\u064e \u0625\u0650\u0630\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u06e1 \u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f\u06e5 \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064f \u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0623\u064e\u0638\u064f\u0646\u0651\u064f\u0643\u064e \u064a\u064e\u0670\u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0645\u064e\u0633\u06e1\u062d\u064f\u0648\u0631\u0657\u0627",translation:"(Dan sungguh, Kami telah memberikan kepada Musa sembilan mukjizat yang nyata483) maka tanyakanlah kepada Bani Israil, ketika Musa datang kepada mereka lalu Fir'aun berkata kepadanya, \"Wahai Musa! Sesungguhnya aku benar-benar menduga engkau terkena sihir"},{id:102,text:"\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0642\u064e\u062f\u06e1 \u0639\u064e\u0644\u0650\u0645\u06e1\u062a\u064e \u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0631\u064e\u0628\u0651\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0628\u064e\u0635\u064e\u0627\u0653\u0626\u0650\u0631\u064e \u0648\u064e\u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0623\u064e\u0638\u064f\u0646\u0651\u064f\u0643\u064e \u064a\u064e\u0670\u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064f \u0645\u064e\u062b\u06e1\u0628\u064f\u0648\u0631\u0657\u0627",translation:"Dia (Musa) menjawab, \"Sungguh, engkau telah mengetahui, bahwa tidak ada yang menurunkan (mukjizat-mukjizat) itu kecuali Tuhan (yang memelihara) langit dan bumi sebagai bukti-bukti yang nyata; dan sungguh, aku benar-benar menduga engkau akan binasa, wahai Fir'aun"},{id:103,text:"\u0641\u064e\u0623\u064e\u0631\u064e\u0627\u062f\u064e \u0623\u064e\u0646 \u064a\u064e\u0633\u06e1\u062a\u064e\u0641\u0650\u0632\u0651\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0641\u064e\u0623\u064e\u063a\u06e1\u0631\u064e\u0642\u06e1\u0646\u064e\u0670\u0647\u064f \u0648\u064e\u0645\u064e\u0646 \u0645\u0651\u064e\u0639\u064e\u0647\u064f\u06e5 \u062c\u064e\u0645\u0650\u064a\u0639\u0657\u0627",translation:"Kemudian dia (Fir'aun) hendak mengusir mereka (Musa dan pengikutnya) dari bumi (Mesir), maka Kami tenggelamkan dia (Fir'aun) beserta orang yang bersama dia seluruhnya"},{id:104,text:"\u0648\u064e\u0642\u064f\u0644\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u0647\u0650\u06e6 \u0644\u0650\u0628\u064e\u0646\u0650\u064a\u0653 \u0625\u0650\u0633\u06e1\u0631\u064e\u0640\u0670\u0653\u0621\u0650\u064a\u0644\u064e \u0671\u0633\u06e1\u0643\u064f\u0646\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e \u0648\u064e\u0639\u06e1\u062f\u064f \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u062c\u0650\u0626\u06e1\u0646\u064e\u0627 \u0628\u0650\u0643\u064f\u0645\u06e1 \u0644\u064e\u0641\u0650\u064a\u0641\u0657\u0627",translation:"dan setelah itu Kami berfirman kepada Bani Israil, \"Tinggallah di negeri ini, tetapi apabila masa berbangkit datang, niscaya Kami kumpulkan kamu dalam keadaan bercampur baur"},{id:105,text:"\u0648\u064e\u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f \u0648\u064e\u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0646\u064e\u0632\u064e\u0644\u064e\u06d7 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0670\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064f\u0628\u064e\u0634\u0651\u0650\u0631\u0657\u0627 \u0648\u064e\u0646\u064e\u0630\u0650\u064a\u0631\u0657\u0627",translation:"Dan Kami turunkan (Alquran) itu dengan sebenarnya dan (Alquran) itu turun dengan (membawa) kebenaran. Dan Kami mengutus engkau (Muhammad), hanya sebagai pembawa berita gembira dan pemberi peringatan"},{id:106,text:"\u0648\u064e\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u0657\u0627 \u0641\u064e\u0631\u064e\u0642\u06e1\u0646\u064e\u0670\u0647\u064f \u0644\u0650\u062a\u064e\u0642\u06e1\u0631\u064e\u0623\u064e\u0647\u064f\u06e5 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064f\u0643\u06e1\u062b\u0656 \u0648\u064e\u0646\u064e\u0632\u0651\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f \u062a\u064e\u0646\u0632\u0650\u064a\u0644\u0657\u0627",translation:"Dan Alquran (kami turunkan) berangsur-angsur agar engkau (Muhammad) membacakannya kepada manusia perlahan-lahan dan Kami menurunkannya secara bertahap"},{id:107,text:"\u0642\u064f\u0644\u06e1 \u0621\u064e\u0627\u0645\u0650\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0648\u06e1 \u0644\u064e\u0627 \u062a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0653\u0627\u0652\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0639\u0650\u0644\u06e1\u0645\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0630\u064e\u0627 \u064a\u064f\u062a\u06e1\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u064a\u064e\u062e\u0650\u0631\u0651\u064f\u0648\u0646\u064e\u06e4 \u0644\u0650\u0644\u06e1\u0623\u064e\u0630\u06e1\u0642\u064e\u0627\u0646\u0650\u06e4 \u0633\u064f\u062c\u0651\u064e\u062f\u0657\u0627\u06e4",translation:"Katakanlah (Muhammad), \"Berimanlah kamu kepadanya (Alquran) atau tidak usah beriman (sama saja bagi Allah). Sesungguhnya orang yang telah diberi pengetahuan sebelumnya, apabila (Alquran) dibacakan kepada mereka, mereka menyungkurkan wajah bersujud"},{id:108,text:"\u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0633\u064f\u0628\u06e1\u062d\u064e\u0670\u0646\u064e \u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627\u0653 \u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064e \u0648\u064e\u0639\u06e1\u062f\u064f \u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627 \u0644\u064e\u0645\u064e\u0641\u06e1\u0639\u064f\u0648\u0644\u0657\u0627",translation:"dan mereka berkata, \"Mahasuci Tuhan kami; sungguh, janji Tuhan kami pasti dipenuhi"},{id:109,text:"\u0648\u064e\u064a\u064e\u062e\u0650\u0631\u0651\u064f\u0648\u0646\u064e \u0644\u0650\u0644\u06e1\u0623\u064e\u0630\u06e1\u0642\u064e\u0627\u0646\u0650 \u064a\u064e\u0628\u06e1\u0643\u064f\u0648\u0646\u064e \u0648\u064e\u064a\u064e\u0632\u0650\u064a\u062f\u064f\u0647\u064f\u0645\u06e1 \u062e\u064f\u0634\u064f\u0648\u0639\u0657\u0627\u06e9",translation:"Dan mereka menyungkurkan wajah sambil menangis dan mereka bertambah khusyuk"},{id:110,text:"\u0642\u064f\u0644\u0650 \u0671\u062f\u06e1\u0639\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0623\u064e\u0648\u0650 \u0671\u062f\u06e1\u0639\u064f\u0648\u0627\u0652 \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u064e\u06d6 \u0623\u064e\u064a\u0651\u0657\u0627 \u0645\u0651\u064e\u0627 \u062a\u064e\u062f\u06e1\u0639\u064f\u0648\u0627\u0652 \u0641\u064e\u0644\u064e\u0647\u064f \u0671\u0644\u06e1\u0623\u064e\u0633\u06e1\u0645\u064e\u0627\u0653\u0621\u064f \u0671\u0644\u06e1\u062d\u064f\u0633\u06e1\u0646\u064e\u0649\u0670\u06da \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062c\u06e1\u0647\u064e\u0631\u06e1 \u0628\u0650\u0635\u064e\u0644\u064e\u0627\u062a\u0650\u0643\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u062e\u064e\u0627\u0641\u0650\u062a\u06e1 \u0628\u0650\u0647\u064e\u0627 \u0648\u064e\u0671\u0628\u06e1\u062a\u064e\u063a\u0650 \u0628\u064e\u064a\u06e1\u0646\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0633\u064e\u0628\u0650\u064a\u0644\u0657\u0627",translation:"Katakanlah (Muhammad), \"Serulah Allah atau serulah Ar-Ra\u1e25m\u0101n. Dengan nama yang mana saja kamu dapat menyeru, karena Dia mempunyai nama-nama yang terbaik (Asm\u0101ul \u1e24usn\u0101) dan janganlah engkau mengeraskan suaramu dalam salat dan janganlah (pula) merendahkannya dan usahakan jalan tengah di antara kedua itu"},{id:111,text:"\u0648\u064e\u0642\u064f\u0644\u0650 \u0671\u0644\u06e1\u062d\u064e\u0645\u06e1\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0644\u064e\u0645\u06e1 \u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u06e1 \u0648\u064e\u0644\u064e\u062f\u0657\u0627 \u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0643\u064f\u0646 \u0644\u0651\u064e\u0647\u064f\u06e5 \u0634\u064e\u0631\u0650\u064a\u0643\u065e \u0641\u0650\u064a \u0671\u0644\u06e1\u0645\u064f\u0644\u06e1\u0643\u0650 \u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0643\u064f\u0646 \u0644\u0651\u064e\u0647\u064f\u06e5 \u0648\u064e\u0644\u0650\u064a\u0651\u065e \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0630\u0651\u064f\u0644\u0651\u0650\u06d6 \u0648\u064e\u0643\u064e\u0628\u0651\u0650\u0631\u06e1\u0647\u064f \u062a\u064e\u0643\u06e1\u0628\u0650\u064a\u0631\u064e\u06e2\u0627",translation:"Dan katakanlah, \"Segala puji bagi Allah yang tidak mempunyai anak dan tidak (pula) mempunyai sekutu dalam kerajaan-Nya dan Dia tidak memerlukan penolong dari kehinaan dan agungkanlah Dia seagung-agungnya"}]},{id:18,name:"\u0627\u0644\u0643\u0647\u0641",transliteration:"Al-Kahf",translation:"Para Penghuni Gua",type:"meccan",total_verses:110,verses:[{id:1,text:"\u0671\u0644\u06e1\u062d\u064e\u0645\u06e1\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0639\u064e\u0628\u06e1\u062f\u0650\u0647\u0650 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u062c\u06e1\u0639\u064e\u0644 \u0644\u0651\u064e\u0647\u064f\u06e5 \u0639\u0650\u0648\u064e\u062c\u064e\u0627\u06dc",translation:"Segala puji bagi Allah yang telah menurunkan Kitab (Alquran) kepada hamba-Nya dan Dia tidak menjadikannya bengkok"},{id:2,text:"\u0642\u064e\u064a\u0651\u0650\u0645\u0657\u0627 \u0644\u0651\u0650\u064a\u064f\u0646\u0630\u0650\u0631\u064e \u0628\u064e\u0623\u06e1\u0633\u0657\u0627 \u0634\u064e\u062f\u0650\u064a\u062f\u0657\u0627 \u0645\u0651\u0650\u0646 \u0644\u0651\u064e\u062f\u064f\u0646\u06e1\u0647\u064f \u0648\u064e\u064a\u064f\u0628\u064e\u0634\u0651\u0650\u0631\u064e \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0623\u064e\u0646\u0651\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u062c\u06e1\u0631\u064b\u0627 \u062d\u064e\u0633\u064e\u0646\u0657\u0627",translation:"sebagai bimbingan yang lurus, untuk memperingatkan akan siksa yang sangat pedih dari sisi-Nya dan memberikan kabar gembira kepada orang-orang mukmin yang mengerjakan kebajikan bahwa mereka akan mendapat balasan yang baik"},{id:3,text:"\u0645\u0651\u064e\u0640\u0670\u0643\u0650\u062b\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u0650 \u0623\u064e\u0628\u064e\u062f\u0657\u0627",translation:"mereka kekal di dalamnya untuk selama-lamanya"},{id:4,text:"\u0648\u064e\u064a\u064f\u0646\u0630\u0650\u0631\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0644\u064e\u062f\u0657\u0627",translation:"Dan untuk memperingatkan kepada orang yang berkata, \"Allah mengambil seorang anak"},{id:5,text:"\u0645\u0651\u064e\u0627 \u0644\u064e\u0647\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6 \u0645\u0650\u0646\u06e1 \u0639\u0650\u0644\u06e1\u0645\u0656 \u0648\u064e\u0644\u064e\u0627 \u0644\u0650\u0623\u0653\u0628\u064e\u0627\u0653\u0626\u0650\u0647\u0650\u0645\u06e1\u06da \u0643\u064e\u0628\u064f\u0631\u064e\u062a\u06e1 \u0643\u064e\u0644\u0650\u0645\u064e\u0629\u0657 \u062a\u064e\u062e\u06e1\u0631\u064f\u062c\u064f \u0645\u0650\u0646\u06e1 \u0623\u064e\u0641\u06e1\u0648\u064e\u0670\u0647\u0650\u0647\u0650\u0645\u06e1\u06da \u0625\u0650\u0646 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064e\u0630\u0650\u0628\u0657\u0627",translation:"Mereka sama sekali tidak mempunyai pengetahuan tentang hal itu, begitu pula nenek moyang mereka. Alangkah jeleknya kata-kata yang keluar dari mulut mereka; mereka hanya mengatakan (suatu) kebohongan belaka"},{id:6,text:"\u0641\u064e\u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064e \u0628\u064e\u0670\u062e\u0650\u0639\u065e \u0646\u0651\u064e\u0641\u06e1\u0633\u064e\u0643\u064e \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0621\u064e\u0627\u062b\u064e\u0670\u0631\u0650\u0647\u0650\u0645\u06e1 \u0625\u0650\u0646 \u0644\u0651\u064e\u0645\u06e1 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u06e1\u062d\u064e\u062f\u0650\u064a\u062b\u0650 \u0623\u064e\u0633\u064e\u0641\u064b\u0627",translation:"Maka barangkali engkau (Muhammad) akan mencelakakan dirimu karena bersedih hati setelah mereka berpaling, sekiranya mereka tidak beriman kepada keterangan ini (Alquran)"},{id:7,text:"\u0625\u0650\u0646\u0651\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0645\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0632\u0650\u064a\u0646\u064e\u0629\u0657 \u0644\u0651\u064e\u0647\u064e\u0627 \u0644\u0650\u0646\u064e\u0628\u06e1\u0644\u064f\u0648\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u064a\u0651\u064f\u0647\u064f\u0645\u06e1 \u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064f \u0639\u064e\u0645\u064e\u0644\u0657\u0627",translation:"Sesungguhnya Kami telah menjadikan apa yang ada di bumi sebagai perhiasan baginya, untuk Kami menguji mereka, siapakah diantaranya yang terbaik perbuatannya"},{id:8,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u062c\u064e\u0670\u0639\u0650\u0644\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627 \u0635\u064e\u0639\u0650\u064a\u062f\u0657\u0627 \u062c\u064f\u0631\u064f\u0632\u064b\u0627",translation:"Dan Kami benar-benar akan menjadikan (pula) apa yang di atasnya menjadi tanah yang tandus lagi kering"},{id:9,text:"\u0623\u064e\u0645\u06e1 \u062d\u064e\u0633\u0650\u0628\u06e1\u062a\u064e \u0623\u064e\u0646\u0651\u064e \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064e \u0671\u0644\u06e1\u0643\u064e\u0647\u06e1\u0641\u0650 \u0648\u064e\u0671\u0644\u0631\u0651\u064e\u0642\u0650\u064a\u0645\u0650 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0639\u064e\u062c\u064e\u0628\u064b\u0627",translation:"Apakah engkau mengira bahwa orang yang mendiami gua, dan (yang mempunyai) raq\u012bm485) itu, termasuk tanda-tanda (kebesaran) Kami yang menakjubkan"},{id:10,text:"\u0625\u0650\u0630\u06e1 \u0623\u064e\u0648\u064e\u0649 \u0671\u0644\u06e1\u0641\u0650\u062a\u06e1\u064a\u064e\u0629\u064f \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u0643\u064e\u0647\u06e1\u0641\u0650 \u0641\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0645\u0650\u0646 \u0644\u0651\u064e\u062f\u064f\u0646\u0643\u064e \u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u0657 \u0648\u064e\u0647\u064e\u064a\u0651\u0650\u0626\u06e1 \u0644\u064e\u0646\u064e\u0627 \u0645\u0650\u0646\u06e1 \u0623\u064e\u0645\u06e1\u0631\u0650\u0646\u064e\u0627 \u0631\u064e\u0634\u064e\u062f\u0657\u0627",translation:"(Ingatlah) ketika pemuda-pemuda itu berlindung ke dalam gua lalu mereka berdoa, \"Ya Tuhan kami. Berikanlah rahmat kepada kami dari sisi-Mu dan sempurnakanlah petunjuk yang lurus bagi kami dalam urusan kami"},{id:11,text:"\u0641\u064e\u0636\u064e\u0631\u064e\u0628\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0621\u064e\u0627\u0630\u064e\u0627\u0646\u0650\u0647\u0650\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0643\u064e\u0647\u06e1\u0641\u0650 \u0633\u0650\u0646\u0650\u064a\u0646\u064e \u0639\u064e\u062f\u064e\u062f\u0657\u0627",translation:"(Maka Kami tutup telinga mereka di dalam gua itu,486) selama beberapa tahun"},{id:12,text:"\u062b\u064f\u0645\u0651\u064e \u0628\u064e\u0639\u064e\u062b\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0644\u0650\u0646\u064e\u0639\u06e1\u0644\u064e\u0645\u064e \u0623\u064e\u064a\u0651\u064f \u0671\u0644\u06e1\u062d\u0650\u0632\u06e1\u0628\u064e\u064a\u06e1\u0646\u0650 \u0623\u064e\u062d\u06e1\u0635\u064e\u0649\u0670 \u0644\u0650\u0645\u064e\u0627 \u0644\u064e\u0628\u0650\u062b\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0645\u064e\u062f\u0657\u0627",translation:"(kemudian Kami bangunkan mereka, agar Kami mengetahui manakah di antara ke dua golongan itu487) yang lebih tepat dalam menghitung berapa lamanya mereka tinggal (dalam gua itu)"},{id:13,text:"\u0646\u0651\u064e\u062d\u06e1\u0646\u064f \u0646\u064e\u0642\u064f\u0635\u0651\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0646\u064e\u0628\u064e\u0623\u064e\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u062a\u06e1\u064a\u064e\u0629\u064c \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0632\u0650\u062f\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0647\u064f\u062f\u0657\u0649",translation:"Kami ceritakan kepadamu (Muhammad) kisah mereka dengan sebenarnya. Sesungguhnya mereka adalah pemuda-pemuda yang beriman kepada Tuhan mereka, dan Kami tambahkan petunjuk kepada mereka"},{id:14,text:"\u0648\u064e\u0631\u064e\u0628\u064e\u0637\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u06e1 \u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0645\u064f\u0648\u0627\u0652 \u0641\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0631\u064e\u0628\u0651\u064f\u0646\u064e\u0627 \u0631\u064e\u0628\u0651\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0644\u064e\u0646 \u0646\u0651\u064e\u062f\u06e1\u0639\u064f\u0648\u064e\u0627\u0652 \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u0657\u0627\u06d6 \u0644\u0651\u064e\u0642\u064e\u062f\u06e1 \u0642\u064f\u0644\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0630\u0657\u0627 \u0634\u064e\u0637\u064e\u0637\u064b\u0627",translation:"(dan Kami teguhkan hati mereka ketika mereka berdiri488)) lalu mereka berkata, \"Tuhan kami adalah Tuhan langit dan bumi; kami tidak menyeru tuhan selain Dia. Sungguh, kalau kami berbuat demikian, tentu kami telah mengucapkan perkataan yang sangat jauh dari kebenaran"},{id:15,text:"\u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650 \u0642\u064e\u0648\u06e1\u0645\u064f\u0646\u064e\u0627 \u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u06e6\u0653 \u0621\u064e\u0627\u0644\u0650\u0647\u064e\u0629\u0657\u06d6 \u0644\u0651\u064e\u0648\u06e1\u0644\u064e\u0627 \u064a\u064e\u0623\u06e1\u062a\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0628\u0650\u0633\u064f\u0644\u06e1\u0637\u064e\u0670\u0646\u0650\u06ed \u0628\u064e\u064a\u0651\u0650\u0646\u0656\u06d6 \u0641\u064e\u0645\u064e\u0646\u06e1 \u0623\u064e\u0638\u06e1\u0644\u064e\u0645\u064f \u0645\u0650\u0645\u0651\u064e\u0646\u0650 \u0671\u0641\u06e1\u062a\u064e\u0631\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u0630\u0650\u0628\u0657\u0627",translation:"Mereka itu kaum kami yang telah menjadikan tuhan-tuhan (untuk disembah) selain Dia. Mengapa mereka tidak mengemukakan alasan yang jelas (tentang kepercayaan mereka)? Maka siapakah yang lebih zalim daripada orang yang mengada-adakan kebohongan terhadap Allah"},{id:16,text:"\u0648\u064e\u0625\u0650\u0630\u0650 \u0671\u0639\u06e1\u062a\u064e\u0632\u064e\u0644\u06e1\u062a\u064f\u0645\u064f\u0648\u0647\u064f\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0641\u064e\u0623\u06e1\u0648\u064f\u06e5\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u0643\u064e\u0647\u06e1\u0641\u0650 \u064a\u064e\u0646\u0634\u064f\u0631\u06e1 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u062a\u0650\u0647\u0650\u06e6 \u0648\u064e\u064a\u064f\u0647\u064e\u064a\u0651\u0650\u0626\u06e1 \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u0645\u06e1\u0631\u0650\u0643\u064f\u0645 \u0645\u0651\u0650\u0631\u06e1\u0641\u064e\u0642\u0657\u0627",translation:"Dan apabila kamu meninggalkan mereka dan apa yang mereka sembah selain Allah, maka carilah tempat berlindung ke dalam gua itu, niscaya Tuhanmu akan melimpahkan sebagian rahmat-Nya kepadamu dan menyediakan sesuatu yang berguna bagimu dalam urusanmu"},{id:17,text:"\u06de\u0648\u064e\u062a\u064e\u0631\u064e\u0649 \u0671\u0644\u0634\u0651\u064e\u0645\u06e1\u0633\u064e \u0625\u0650\u0630\u064e\u0627 \u0637\u064e\u0644\u064e\u0639\u064e\u062a \u062a\u0651\u064e\u0632\u064e\u0670\u0648\u064e\u0631\u064f \u0639\u064e\u0646 \u0643\u064e\u0647\u06e1\u0641\u0650\u0647\u0650\u0645\u06e1 \u0630\u064e\u0627\u062a\u064e \u0671\u0644\u06e1\u064a\u064e\u0645\u0650\u064a\u0646\u0650 \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u063a\u064e\u0631\u064e\u0628\u064e\u062a \u062a\u0651\u064e\u0642\u06e1\u0631\u0650\u0636\u064f\u0647\u064f\u0645\u06e1 \u0630\u064e\u0627\u062a\u064e \u0671\u0644\u0634\u0651\u0650\u0645\u064e\u0627\u0644\u0650 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0641\u064e\u062c\u06e1\u0648\u064e\u0629\u0656 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u0650\u0646\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d7 \u0645\u064e\u0646 \u064a\u064e\u0647\u06e1\u062f\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0645\u064f\u0647\u06e1\u062a\u064e\u062f\u0650\u06d6 \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0636\u06e1\u0644\u0650\u0644\u06e1 \u0641\u064e\u0644\u064e\u0646 \u062a\u064e\u062c\u0650\u062f\u064e \u0644\u064e\u0647\u064f\u06e5 \u0648\u064e\u0644\u0650\u064a\u0651\u0657\u0627 \u0645\u0651\u064f\u0631\u06e1\u0634\u0650\u062f\u0657\u0627",translation:"Dan engkau akan melihat matahari ketika terbit, condong dari gua mereka ke sebelah kanan, dan apabila matahari itu terbenam, menjauhi mereka ke sebelah kiri sedang mereka berada dalam tempat yang luas di dalam (gua) itu. Itulah sebagian dari tanda-tanda (kebesaran) Allah. Barang siapa diberi petunjuk oleh Allah, maka dialah yang mendapat petunjuk; dan barang siapa disesatkan-Nya, maka engkau tidak akan mendapatkan seorang penolong yang dapat memberi petunjuk kepadanya"},{id:18,text:"\u0648\u064e\u062a\u064e\u062d\u06e1\u0633\u064e\u0628\u064f\u0647\u064f\u0645\u06e1 \u0623\u064e\u064a\u06e1\u0642\u064e\u0627\u0638\u0657\u0627 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0631\u064f\u0642\u064f\u0648\u062f\u065e\u06da \u0648\u064e\u0646\u064f\u0642\u064e\u0644\u0651\u0650\u0628\u064f\u0647\u064f\u0645\u06e1 \u0630\u064e\u0627\u062a\u064e \u0671\u0644\u06e1\u064a\u064e\u0645\u0650\u064a\u0646\u0650 \u0648\u064e\u0630\u064e\u0627\u062a\u064e \u0671\u0644\u0634\u0651\u0650\u0645\u064e\u0627\u0644\u0650\u06d6 \u0648\u064e\u0643\u064e\u0644\u06e1\u0628\u064f\u0647\u064f\u0645 \u0628\u064e\u0670\u0633\u0650\u0637\u065e \u0630\u0650\u0631\u064e\u0627\u0639\u064e\u064a\u06e1\u0647\u0650 \u0628\u0650\u0671\u0644\u06e1\u0648\u064e\u0635\u0650\u064a\u062f\u0650\u06da \u0644\u064e\u0648\u0650 \u0671\u0637\u0651\u064e\u0644\u064e\u0639\u06e1\u062a\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0644\u064e\u0648\u064e\u0644\u0651\u064e\u064a\u06e1\u062a\u064e \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0641\u0650\u0631\u064e\u0627\u0631\u0657\u0627 \u0648\u064e\u0644\u064e\u0645\u064f\u0644\u0650\u0626\u06e1\u062a\u064e \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0631\u064f\u0639\u06e1\u0628\u0657\u0627",translation:"Dan engkau mengira mereka itu tidak tidur, padahal mereka tidur; dan Kami bolak-balikkan mereka ke kanan dan ke kiri, sedang anjing mereka membentangkan kedua lengannya di depan pintu gua. Dan jika kamu menyaksikan mereka tentu kamu akan berpaling melarikan (diri) dari mereka dan pasti kamu akan dipenuhi rasa takut terhadap mereka"},{id:19,text:"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u064e\u0639\u064e\u062b\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0644\u0650\u064a\u064e\u062a\u064e\u0633\u064e\u0627\u0653\u0621\u064e\u0644\u064f\u0648\u0627\u0652 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1\u06da \u0642\u064e\u0627\u0644\u064e \u0642\u064e\u0627\u0653\u0626\u0650\u0644\u065e \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0643\u064e\u0645\u06e1 \u0644\u064e\u0628\u0650\u062b\u06e1\u062a\u064f\u0645\u06e1\u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0628\u0650\u062b\u06e1\u0646\u064e\u0627 \u064a\u064e\u0648\u06e1\u0645\u064b\u0627 \u0623\u064e\u0648\u06e1 \u0628\u064e\u0639\u06e1\u0636\u064e \u064a\u064e\u0648\u06e1\u0645\u0656\u06da \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u06e1 \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u0644\u064e\u0628\u0650\u062b\u06e1\u062a\u064f\u0645\u06e1 \u0641\u064e\u0671\u0628\u06e1\u0639\u064e\u062b\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u062d\u064e\u062f\u064e\u0643\u064f\u0645 \u0628\u0650\u0648\u064e\u0631\u0650\u0642\u0650\u0643\u064f\u0645\u06e1 \u0647\u064e\u0670\u0630\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u0645\u064e\u062f\u0650\u064a\u0646\u064e\u0629\u0650 \u0641\u064e\u0644\u06e1\u064a\u064e\u0646\u0638\u064f\u0631\u06e1 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627\u0653 \u0623\u064e\u0632\u06e1\u0643\u064e\u0649\u0670 \u0637\u064e\u0639\u064e\u0627\u0645\u0657\u0627 \u0641\u064e\u0644\u06e1\u064a\u064e\u0623\u06e1\u062a\u0650\u0643\u064f\u0645 \u0628\u0650\u0631\u0650\u0632\u06e1\u0642\u0656 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f \u0648\u064e\u0644\u06e1\u064a\u064e\u062a\u064e\u0644\u064e\u0637\u0651\u064e\u0641\u06e1 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0634\u06e1\u0639\u0650\u0631\u064e\u0646\u0651\u064e \u0628\u0650\u0643\u064f\u0645\u06e1 \u0623\u064e\u062d\u064e\u062f\u064b\u0627",translation:"Dan demikianlah Kami bangunkan mereka, agar di antara mereka saling bertanya. Salah seorang di antara mereka berkata, \"Sudah berapa lama kamu berada (di sini)?\" Mereka menjawab, \"Kita berada (di sini) sehari atau setengah hari.\" Berkata (yang lain lagi), \"Tuhanmu lebih mengetahui berapa lama kamu berada (di sini). Maka suruhlah salah seorang di antara kamu pergi ke kota dengan membawa uang perakmu ini, dan hendaklah dia lihat manakah makanan yang lebih baik, dan bawalah sebagian makanan itu untukmu, dan hendaklah dia berlaku lemah lembut dan jangan sekali-kali menceritakan halmu kepada siapa pun"},{id:20,text:"\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0625\u0650\u0646 \u064a\u064e\u0638\u06e1\u0647\u064e\u0631\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u064a\u064e\u0631\u06e1\u062c\u064f\u0645\u064f\u0648\u0643\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1 \u064a\u064f\u0639\u0650\u064a\u062f\u064f\u0648\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u0645\u0650\u0644\u0651\u064e\u062a\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0644\u064e\u0646 \u062a\u064f\u0641\u06e1\u0644\u0650\u062d\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0630\u064b\u0627 \u0623\u064e\u0628\u064e\u062f\u0657\u0627",translation:"Sesungguhnya jika mereka dapat mengetahui tempatmu, niscaya mereka akan melempari kamu dengan batu, atau memaksamu kembali kepada agama mereka, dan jika demikian niscaya kamu tidak akan beruntung selama-lamanya"},{id:21,text:"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0623\u064e\u0639\u06e1\u062b\u064e\u0631\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0644\u0650\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e \u0648\u064e\u0639\u06e1\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u064e\u0642\u0651\u065e \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064e \u0644\u064e\u0627 \u0631\u064e\u064a\u06e1\u0628\u064e \u0641\u0650\u064a\u0647\u064e\u0627\u0653 \u0625\u0650\u0630\u06e1 \u064a\u064e\u062a\u064e\u0646\u064e\u0670\u0632\u064e\u0639\u064f\u0648\u0646\u064e \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u0645\u06e1\u0631\u064e\u0647\u064f\u0645\u06e1\u06d6 \u0641\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0671\u0628\u06e1\u0646\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0628\u064f\u0646\u06e1\u064a\u064e\u0670\u0646\u0657\u0627\u06d6 \u0631\u0651\u064e\u0628\u0651\u064f\u0647\u064f\u0645\u06e1 \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0628\u0650\u0647\u0650\u0645\u06e1\u06da \u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u063a\u064e\u0644\u064e\u0628\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0645\u06e1\u0631\u0650\u0647\u0650\u0645\u06e1 \u0644\u064e\u0646\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064e\u0646\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0645\u0651\u064e\u0633\u06e1\u062c\u0650\u062f\u0657\u0627",translation:"Dan demikian (pula) Kami perlihatkan (manusia) dengan mereka, agar mereka tahu, bahwa janji Allah benar, dan bahwa (kedatangan) hari Kiamat tidak ada keraguan padanya. Ketika mereka berselisih tentang urusan mereka,490) maka mereka berkata, \"Dirikanlah suatu bangunan di atas (gua) mereka, Tuhan mereka lebih mengetahui tentang mereka.\" Orang yang berkuasa atas urusan mereka berkata, \"Kami pasti akan mendirikan suatu rumah ibadah di atasnya"},{id:22,text:"\u0633\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u062b\u064e\u0644\u064e\u0670\u062b\u064e\u0629\u065e \u0631\u0651\u064e\u0627\u0628\u0650\u0639\u064f\u0647\u064f\u0645\u06e1 \u0643\u064e\u0644\u06e1\u0628\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u062e\u064e\u0645\u06e1\u0633\u064e\u0629\u065e \u0633\u064e\u0627\u062f\u0650\u0633\u064f\u0647\u064f\u0645\u06e1 \u0643\u064e\u0644\u06e1\u0628\u064f\u0647\u064f\u0645\u06e1 \u0631\u064e\u062c\u06e1\u0645\u064e\u06e2\u0627 \u0628\u0650\u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u0628\u0650\u06d6 \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0633\u064e\u0628\u06e1\u0639\u064e\u0629\u065e \u0648\u064e\u062b\u064e\u0627\u0645\u0650\u0646\u064f\u0647\u064f\u0645\u06e1 \u0643\u064e\u0644\u06e1\u0628\u064f\u0647\u064f\u0645\u06e1\u06da \u0642\u064f\u0644 \u0631\u0651\u064e\u0628\u0651\u0650\u064a\u0653 \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0628\u0650\u0639\u0650\u062f\u0651\u064e\u062a\u0650\u0647\u0650\u0645 \u0645\u0651\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u065e\u06d7 \u0641\u064e\u0644\u064e\u0627 \u062a\u064f\u0645\u064e\u0627\u0631\u0650 \u0641\u0650\u064a\u0647\u0650\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u0650\u0631\u064e\u0627\u0653\u0621\u0657 \u0638\u064e\u0670\u0647\u0650\u0631\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0633\u06e1\u062a\u064e\u0641\u06e1\u062a\u0650 \u0641\u0650\u064a\u0647\u0650\u0645 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0623\u064e\u062d\u064e\u062f\u0657\u0627",translation:"Nanti (ada orang yang akan) mengatakan,491)\" (Jumlah mereka) tiga (orang), yang ke empat adalah anjingnya,\" dan (yang lain) mengatakan, \"(Jumlah mereka) lima (orang), yang ke enam adalah anjingnya,\" sebagai terkaan terhadap yang gaib; dan (yang lain lagi) mengatakan, \"(Jumlah mereka) tujuh (orang), yang ke delapan adalah anjingnya.\" Katakanlah (Muhammad), \"Tuhanku lebih mengetahui jumlah mereka; tidak ada yang mengetahui (bilangan) mereka kecuali sedikit.\" Karena itu janganlah engkau (Muhammad) berbantah tentang hal mereka, kecuali perbantahan lahir saja dan jangan engkau menanyakan tentang mereka (pemuda-pemuda itu) kepada siapa pun"},{id:23,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u064f\u0648\u0644\u064e\u0646\u0651\u064e \u0644\u0650\u0634\u064e\u0627\u0652\u064a\u06e1\u0621\u064d \u0625\u0650\u0646\u0651\u0650\u064a \u0641\u064e\u0627\u0639\u0650\u0644\u065e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u063a\u064e\u062f\u064b\u0627",translation:"Dan jangan sekali-kali engkau mengatakan terhadap sesuatu, \"Aku pasti melakukan itu besok pagi"},{id:24,text:"\u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06da \u0648\u064e\u0671\u0630\u06e1\u0643\u064f\u0631 \u0631\u0651\u064e\u0628\u0651\u064e\u0643\u064e \u0625\u0650\u0630\u064e\u0627 \u0646\u064e\u0633\u0650\u064a\u062a\u064e \u0648\u064e\u0642\u064f\u0644\u06e1 \u0639\u064e\u0633\u064e\u0649\u0670\u0653 \u0623\u064e\u0646 \u064a\u064e\u0647\u06e1\u062f\u0650\u064a\u064e\u0646\u0650 \u0631\u064e\u0628\u0651\u0650\u064a \u0644\u0650\u0623\u064e\u0642\u06e1\u0631\u064e\u0628\u064e \u0645\u0650\u0646\u06e1 \u0647\u064e\u0670\u0630\u064e\u0627 \u0631\u064e\u0634\u064e\u062f\u0657\u0627",translation:"kecuali (dengan mengatakan), \"Insy\u0101 Allah.\"492) Dan ingatlah kepada Tuhanmu apabila engkau lupa dan katakanlah, \"Mudah-mudahan Tuhanku akan memberi petunjuk kepadaku agar aku yang lebih dekat (kebenarannya) daripada ini"},{id:25,text:"\u0648\u064e\u0644\u064e\u0628\u0650\u062b\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0643\u064e\u0647\u06e1\u0641\u0650\u0647\u0650\u0645\u06e1 \u062b\u064e\u0644\u064e\u0670\u062b\u064e \u0645\u0650\u0627\u0652\u0626\u064e\u0629\u0656 \u0633\u0650\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0632\u06e1\u062f\u064e\u0627\u062f\u064f\u0648\u0627\u0652 \u062a\u0650\u0633\u06e1\u0639\u0657\u0627",translation:"Dan mereka tinggal dalam gua selama tiga ratus tahun dan ditambah sembilan tahun"},{id:26,text:"\u0642\u064f\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u0644\u064e\u0628\u0650\u062b\u064f\u0648\u0627\u0652\u06d6 \u0644\u064e\u0647\u064f\u06e5 \u063a\u064e\u064a\u06e1\u0628\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d6 \u0623\u064e\u0628\u06e1\u0635\u0650\u0631\u06e1 \u0628\u0650\u0647\u0650\u06e6 \u0648\u064e\u0623\u064e\u0633\u06e1\u0645\u0650\u0639\u06e1\u06da \u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u06e6 \u0645\u0650\u0646 \u0648\u064e\u0644\u0650\u064a\u0651\u0656 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0634\u06e1\u0631\u0650\u0643\u064f \u0641\u0650\u064a \u062d\u064f\u0643\u06e1\u0645\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u062d\u064e\u062f\u0657\u0627",translation:"Katakanlah, \"Allah lebih mengetahui berapa lamanya mereka tinggal (di gua); milik-Nya semua yang tersembunyi di langit dan di bumi. Alangkah terang penglihatan-Nya dan alangkah tajam pendengaran-Nya; tidak ada seorang pelindung pun bagi mereka selain Dia; dan Dia tidak mengambil seorang pun menjadi sekutu-Nya dalam menetapkan keputusan"},{id:27,text:"\u0648\u064e\u0671\u062a\u06e1\u0644\u064f \u0645\u064e\u0627\u0653 \u0623\u064f\u0648\u062d\u0650\u064a\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0645\u0650\u0646 \u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e\u06d6 \u0644\u064e\u0627 \u0645\u064f\u0628\u064e\u062f\u0651\u0650\u0644\u064e \u0644\u0650\u0643\u064e\u0644\u0650\u0645\u064e\u0670\u062a\u0650\u0647\u0650\u06e6 \u0648\u064e\u0644\u064e\u0646 \u062a\u064e\u062c\u0650\u062f\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u06e6 \u0645\u064f\u0644\u06e1\u062a\u064e\u062d\u064e\u062f\u0657\u0627",translation:"Dan bacakanlah (Muhammad) apa yang diwahyukan kepadamu, yaitu Kitab Tuhanmu (Alquran). Tidak ada yang dapat mengubah kalimat-kalimat-Nya. Dan engkau tidak akan dapat menemukan tempat berlindung selain kepada-Nya"},{id:28,text:"\u0648\u064e\u0671\u0635\u06e1\u0628\u0650\u0631\u06e1 \u0646\u064e\u0641\u06e1\u0633\u064e\u0643\u064e \u0645\u064e\u0639\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u063a\u064e\u062f\u064e\u0648\u0670\u0629\u0650 \u0648\u064e\u0671\u0644\u06e1\u0639\u064e\u0634\u0650\u064a\u0651\u0650 \u064a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0648\u064e\u062c\u06e1\u0647\u064e\u0647\u064f\u06e5\u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u062f\u064f \u0639\u064e\u064a\u06e1\u0646\u064e\u0627\u0643\u064e \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1 \u062a\u064f\u0631\u0650\u064a\u062f\u064f \u0632\u0650\u064a\u0646\u064e\u0629\u064e \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u0650 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627\u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0637\u0650\u0639\u06e1 \u0645\u064e\u0646\u06e1 \u0623\u064e\u063a\u06e1\u0641\u064e\u0644\u06e1\u0646\u064e\u0627 \u0642\u064e\u0644\u06e1\u0628\u064e\u0647\u064f\u06e5 \u0639\u064e\u0646 \u0630\u0650\u0643\u06e1\u0631\u0650\u0646\u064e\u0627 \u0648\u064e\u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064e \u0647\u064e\u0648\u064e\u0649\u0670\u0647\u064f \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0623\u064e\u0645\u06e1\u0631\u064f\u0647\u064f\u06e5 \u0641\u064f\u0631\u064f\u0637\u0657\u0627",translation:"Dan bersabarlah engkau (Muhammad) bersama orang yang menyeru Tuhannya pada pagi dan senja hari dengan mengharap keridaan-Nya; dan janganlah kedua matamu berpaling dari mereka (karena) mengharapkan perhiasan kehidupan dunia; dan janganlah engkau mengikuti orang yang hatinya telah Kami lalaikan dari mengingat Kami, serta menuruti keinginannya dan keadaannya sudah melewati batas"},{id:29,text:"\u0648\u064e\u0642\u064f\u0644\u0650 \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1\u06d6 \u0641\u064e\u0645\u064e\u0646 \u0634\u064e\u0627\u0653\u0621\u064e \u0641\u064e\u0644\u06e1\u064a\u064f\u0624\u06e1\u0645\u0650\u0646 \u0648\u064e\u0645\u064e\u0646 \u0634\u064e\u0627\u0653\u0621\u064e \u0641\u064e\u0644\u06e1\u064a\u064e\u0643\u06e1\u0641\u064f\u0631\u06e1\u06da \u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u0639\u06e1\u062a\u064e\u062f\u06e1\u0646\u064e\u0627 \u0644\u0650\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0646\u064e\u0627\u0631\u064b\u0627 \u0623\u064e\u062d\u064e\u0627\u0637\u064e \u0628\u0650\u0647\u0650\u0645\u06e1 \u0633\u064f\u0631\u064e\u0627\u062f\u0650\u0642\u064f\u0647\u064e\u0627\u06da \u0648\u064e\u0625\u0650\u0646 \u064a\u064e\u0633\u06e1\u062a\u064e\u063a\u0650\u064a\u062b\u064f\u0648\u0627\u0652 \u064a\u064f\u063a\u064e\u0627\u062b\u064f\u0648\u0627\u0652 \u0628\u0650\u0645\u064e\u0627\u0653\u0621\u0656 \u0643\u064e\u0671\u0644\u06e1\u0645\u064f\u0647\u06e1\u0644\u0650 \u064a\u064e\u0634\u06e1\u0648\u0650\u064a \u0671\u0644\u06e1\u0648\u064f\u062c\u064f\u0648\u0647\u064e\u06da \u0628\u0650\u0626\u06e1\u0633\u064e \u0671\u0644\u0634\u0651\u064e\u0631\u064e\u0627\u0628\u064f \u0648\u064e\u0633\u064e\u0627\u0653\u0621\u064e\u062a\u06e1 \u0645\u064f\u0631\u06e1\u062a\u064e\u0641\u064e\u0642\u064b\u0627",translation:"Dan katakanlah (Muhammad), \"Kebenaran itu datangnya dari Tuhanmu; barang siapa menghendaki (beriman) hendaklah dia beriman, dan barang siapa menghendaki (kafir) biarlah dia kafir.\" Sesungguhnya Kami telah menyediakan neraka bagi orang zalim, yang gejolaknya mengepung mereka. Jika mereka meminta pertolongan (minum), mereka akan diberi air seperti besi yang mendidih yang menghanguskan wajah. (Itulah) minuman yang paling buruk dan tempat istirahat yang paling jelek"},{id:30,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0627 \u0646\u064f\u0636\u0650\u064a\u0639\u064f \u0623\u064e\u062c\u06e1\u0631\u064e \u0645\u064e\u0646\u06e1 \u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064e \u0639\u064e\u0645\u064e\u0644\u064b\u0627",translation:"Sungguh, mereka yang beriman dan mengerjakan kebajikan, Kami benar-benar tidak akan menyia-nyiakan pahala orang yang mengerjakan perbuatan yang baik itu"},{id:31,text:"\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u064f \u0639\u064e\u062f\u06e1\u0646\u0656 \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0645\u0650\u0646 \u062a\u064e\u062d\u06e1\u062a\u0650\u0647\u0650\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u064f \u064a\u064f\u062d\u064e\u0644\u0651\u064e\u0648\u06e1\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u0650\u0646\u06e1 \u0623\u064e\u0633\u064e\u0627\u0648\u0650\u0631\u064e \u0645\u0650\u0646 \u0630\u064e\u0647\u064e\u0628\u0656 \u0648\u064e\u064a\u064e\u0644\u06e1\u0628\u064e\u0633\u064f\u0648\u0646\u064e \u062b\u0650\u064a\u064e\u0627\u0628\u064b\u0627 \u062e\u064f\u0636\u06e1\u0631\u0657\u0627 \u0645\u0651\u0650\u0646 \u0633\u064f\u0646\u062f\u064f\u0633\u0656 \u0648\u064e\u0625\u0650\u0633\u06e1\u062a\u064e\u0628\u06e1\u0631\u064e\u0642\u0656 \u0645\u0651\u064f\u062a\u0651\u064e\u0643\u0650\u0640\u0654\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0623\u064e\u0631\u064e\u0627\u0653\u0626\u0650\u0643\u0650\u06da \u0646\u0650\u0639\u06e1\u0645\u064e \u0671\u0644\u062b\u0651\u064e\u0648\u064e\u0627\u0628\u064f \u0648\u064e\u062d\u064e\u0633\u064f\u0646\u064e\u062a\u06e1 \u0645\u064f\u0631\u06e1\u062a\u064e\u0641\u064e\u0642\u0657\u0627",translation:"Mereka itulah yang memperoleh surga Aden, yang mengalir di bawahnya sungai-sungai; (dalam surga itu) mereka diberi hiasan gelang emas dan mereka memakai pakaian hijau dari sutera halus dan sutera tebal, sedang mereka duduk sambil bersandar di atas dipan-dipan yang indah. (Itulah) sebaik-baik pahala, dan tempat istirahat yang indah"},{id:32,text:"\u06de\u0648\u064e\u0671\u0636\u06e1\u0631\u0650\u0628\u06e1 \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u062b\u064e\u0644\u0657\u0627 \u0631\u0651\u064e\u062c\u064f\u0644\u064e\u064a\u06e1\u0646\u0650 \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0644\u0650\u0623\u064e\u062d\u064e\u062f\u0650\u0647\u0650\u0645\u064e\u0627 \u062c\u064e\u0646\u0651\u064e\u062a\u064e\u064a\u06e1\u0646\u0650 \u0645\u0650\u0646\u06e1 \u0623\u064e\u0639\u06e1\u0646\u064e\u0670\u0628\u0656 \u0648\u064e\u062d\u064e\u0641\u064e\u0641\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u064e\u0627 \u0628\u0650\u0646\u064e\u062e\u06e1\u0644\u0656 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0632\u064e\u0631\u06e1\u0639\u0657\u0627",translation:"Dan berikanlah (Muhammad) kepada mereka493) suatu perumpamaan, dua orang laki-laki,494) yang seorang (yang kafir) Kami beri dua buah kebun anggur dan Kami kelilingi kedua kebun itu dengan pohon-pohon kurma dan di antara keduanya (kebun itu) Kami buatkan ladang"},{id:33,text:"\u0643\u0650\u0644\u06e1\u062a\u064e\u0627 \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u062a\u064e\u064a\u06e1\u0646\u0650 \u0621\u064e\u0627\u062a\u064e\u062a\u06e1 \u0623\u064f\u0643\u064f\u0644\u064e\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0638\u06e1\u0644\u0650\u0645 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627\u06da \u0648\u064e\u0641\u064e\u062c\u0651\u064e\u0631\u06e1\u0646\u064e\u0627 \u062e\u0650\u0644\u064e\u0670\u0644\u064e\u0647\u064f\u0645\u064e\u0627 \u0646\u064e\u0647\u064e\u0631\u0657\u0627",translation:"Kedua kebun itu menghasilkan buahnya, dan tidak berkurang (buahnya) sedikit pun, dan di celah-celah kedua kebun itu Kami alirkan sungai"},{id:34,text:"\u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0647\u064f\u06e5 \u062b\u064e\u0645\u064e\u0631\u065e \u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0635\u064e\u0670\u062d\u0650\u0628\u0650\u0647\u0650\u06e6 \u0648\u064e\u0647\u064f\u0648\u064e \u064a\u064f\u062d\u064e\u0627\u0648\u0650\u0631\u064f\u0647\u064f\u06e5\u0653 \u0623\u064e\u0646\u064e\u0627\u06e0 \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064f \u0645\u0650\u0646\u0643\u064e \u0645\u064e\u0627\u0644\u0657\u0627 \u0648\u064e\u0623\u064e\u0639\u064e\u0632\u0651\u064f \u0646\u064e\u0641\u064e\u0631\u0657\u0627",translation:"dan dia memiliki kekayaan besar, maka dia berkata kepada kawannya (yang beriman) ketika bercakap-cakap dengan dia, \"Hartaku lebih banyak daripada hartamu dan pengikutku lebih kuat"},{id:35,text:"\u0648\u064e\u062f\u064e\u062e\u064e\u0644\u064e \u062c\u064e\u0646\u0651\u064e\u062a\u064e\u0647\u064f\u06e5 \u0648\u064e\u0647\u064f\u0648\u064e \u0638\u064e\u0627\u0644\u0650\u0645\u065e \u0644\u0651\u0650\u0646\u064e\u0641\u06e1\u0633\u0650\u0647\u0650\u06e6 \u0642\u064e\u0627\u0644\u064e \u0645\u064e\u0627\u0653 \u0623\u064e\u0638\u064f\u0646\u0651\u064f \u0623\u064e\u0646 \u062a\u064e\u0628\u0650\u064a\u062f\u064e \u0647\u064e\u0670\u0630\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0628\u064e\u062f\u0657\u0627",translation:"Dan dia memasuki kebunnya dengan sikap merugikan dirinya sendiri (karena angkuh dan kafir); dia berkata, \"Aku kira kebun ini tidak akan binasa selama-lamanya"},{id:36,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0638\u064f\u0646\u0651\u064f \u0671\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064e \u0642\u064e\u0627\u0653\u0626\u0650\u0645\u064e\u0629\u0657 \u0648\u064e\u0644\u064e\u0626\u0650\u0646 \u0631\u0651\u064f\u062f\u0650\u062f\u062a\u0651\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u064a \u0644\u064e\u0623\u064e\u062c\u0650\u062f\u064e\u0646\u0651\u064e \u062e\u064e\u064a\u06e1\u0631\u0657\u0627 \u0645\u0651\u0650\u0646\u06e1\u0647\u064e\u0627 \u0645\u064f\u0646\u0642\u064e\u0644\u064e\u0628\u0657\u0627",translation:"dan aku kira hari Kiamat itu tidak akan datang, dan sekiranya aku dikembalikan kepada Tuhanku, pasti aku akan mendapat tempat kembali yang lebih baik dari pada ini"},{id:37,text:"\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f\u06e5 \u0635\u064e\u0627\u062d\u0650\u0628\u064f\u0647\u064f\u06e5 \u0648\u064e\u0647\u064f\u0648\u064e \u064a\u064f\u062d\u064e\u0627\u0648\u0650\u0631\u064f\u0647\u064f\u06e5\u0653 \u0623\u064e\u0643\u064e\u0641\u064e\u0631\u06e1\u062a\u064e \u0628\u0650\u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e\u0643\u064e \u0645\u0650\u0646 \u062a\u064f\u0631\u064e\u0627\u0628\u0656 \u062b\u064f\u0645\u0651\u064e \u0645\u0650\u0646 \u0646\u0651\u064f\u0637\u06e1\u0641\u064e\u0629\u0656 \u062b\u064f\u0645\u0651\u064e \u0633\u064e\u0648\u0651\u064e\u0649\u0670\u0643\u064e \u0631\u064e\u062c\u064f\u0644\u0657\u0627",translation:"Kawannya (yang beriman) berkata kepadanya sambil bercakap-cakap dengannya, \"Apakah engkau ingkar kepada (Tuhan) yang menciptakan engkau dari tanah, kemudian dari setetes air mani, lalu Dia menjadikan engkau seorang laki-laki yang sempurna"},{id:38,text:"\u0644\u0651\u064e\u0640\u0670\u0643\u0650\u0646\u0651\u064e\u0627\u06e0 \u0647\u064f\u0648\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0631\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064f\u0634\u06e1\u0631\u0650\u0643\u064f \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u064a\u0653 \u0623\u064e\u062d\u064e\u062f\u0657\u0627",translation:"Tetapi aku (percaya bahwa), Dialah Allah, Tuhanku, dan aku tidak mempersekutukan Tuhanku dengan sesuatu pun"},{id:39,text:"\u0648\u064e\u0644\u064e\u0648\u06e1\u0644\u064e\u0627\u0653 \u0625\u0650\u0630\u06e1 \u062f\u064e\u062e\u064e\u0644\u06e1\u062a\u064e \u062c\u064e\u0646\u0651\u064e\u062a\u064e\u0643\u064e \u0642\u064f\u0644\u06e1\u062a\u064e \u0645\u064e\u0627 \u0634\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u0642\u064f\u0648\u0651\u064e\u0629\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0625\u0650\u0646 \u062a\u064e\u0631\u064e\u0646\u0650 \u0623\u064e\u0646\u064e\u0627\u06e0 \u0623\u064e\u0642\u064e\u0644\u0651\u064e \u0645\u0650\u0646\u0643\u064e \u0645\u064e\u0627\u0644\u0657\u0627 \u0648\u064e\u0648\u064e\u0644\u064e\u062f\u0657\u0627",translation:"Dan mengapa ketika engkau memasuki kebunmu tidak mengucapkan \"M\u0101sy\u0101 All\u0101h, l\u0101 quwwata ill\u0101 bill\u0101h\" (Sungguh, atas kehendak Allah, semua ini terwujud), tidak ada kekuatan kecuali dengan (pertolongan) Allah, sekalipun engkau anggap harta dan keturunanku lebih sedikit daripadamu"},{id:40,text:"\u0641\u064e\u0639\u064e\u0633\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u064a\u0653 \u0623\u064e\u0646 \u064a\u064f\u0624\u06e1\u062a\u0650\u064a\u064e\u0646\u0650 \u062e\u064e\u064a\u06e1\u0631\u0657\u0627 \u0645\u0651\u0650\u0646 \u062c\u064e\u0646\u0651\u064e\u062a\u0650\u0643\u064e \u0648\u064e\u064a\u064f\u0631\u06e1\u0633\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627 \u062d\u064f\u0633\u06e1\u0628\u064e\u0627\u0646\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0641\u064e\u062a\u064f\u0635\u06e1\u0628\u0650\u062d\u064e \u0635\u064e\u0639\u0650\u064a\u062f\u0657\u0627 \u0632\u064e\u0644\u064e\u0642\u064b\u0627",translation:"Maka mudah-mudahan Tuhanku, akan memberikan kepadaku (kebun) yang lebih baik dari kebunmu (ini); dan Dia mengirimkan petir dari langit ke kebunmu, sehingga (kebun itu) menjadi tanah yang licin"},{id:41,text:"\u0623\u064e\u0648\u06e1 \u064a\u064f\u0635\u06e1\u0628\u0650\u062d\u064e \u0645\u064e\u0627\u0653\u0624\u064f\u0647\u064e\u0627 \u063a\u064e\u0648\u06e1\u0631\u0657\u0627 \u0641\u064e\u0644\u064e\u0646 \u062a\u064e\u0633\u06e1\u062a\u064e\u0637\u0650\u064a\u0639\u064e \u0644\u064e\u0647\u064f\u06e5 \u0637\u064e\u0644\u064e\u0628\u0657\u0627",translation:"atau airnya menjadi surut ke dalam tanah, maka engkau tidak akan dapat menemukannya lagi"},{id:42,text:"\u0648\u064e\u0623\u064f\u062d\u0650\u064a\u0637\u064e \u0628\u0650\u062b\u064e\u0645\u064e\u0631\u0650\u0647\u0650\u06e6 \u0641\u064e\u0623\u064e\u0635\u06e1\u0628\u064e\u062d\u064e \u064a\u064f\u0642\u064e\u0644\u0651\u0650\u0628\u064f \u0643\u064e\u0641\u0651\u064e\u064a\u06e1\u0647\u0650 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0641\u064e\u0642\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0647\u0650\u064a\u064e \u062e\u064e\u0627\u0648\u0650\u064a\u064e\u0629\u064c \u0639\u064e\u0644\u064e\u0649\u0670 \u0639\u064f\u0631\u064f\u0648\u0634\u0650\u0647\u064e\u0627 \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u064a\u064e\u0670\u0644\u064e\u064a\u06e1\u062a\u064e\u0646\u0650\u064a \u0644\u064e\u0645\u06e1 \u0623\u064f\u0634\u06e1\u0631\u0650\u0643\u06e1 \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u064a\u0653 \u0623\u064e\u062d\u064e\u062f\u0657\u0627",translation:"Dan harta kekayaannya dibinasakan, lalu dia membolak-balikkan kedua telapak tangannya (tanda menyesal) terhadap apa yang telah dia belanjakan untuk itu, sedang pohon anggur roboh bersama penyangganya (tiangnya) lalu dia berkata, \"Betapa sekiranya dahulu aku tidak mempersekutukan Tuhanku dengan sesuatu pun"},{id:43,text:"\u0648\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0643\u064f\u0646 \u0644\u0651\u064e\u0647\u064f\u06e5 \u0641\u0650\u0626\u064e\u0629\u065e \u064a\u064e\u0646\u0635\u064f\u0631\u064f\u0648\u0646\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0645\u064f\u0646\u062a\u064e\u0635\u0650\u0631\u064b\u0627",translation:"Dan tidak ada (lagi) baginya segolongan pun yang dapat menolongnya selain Allah; dan dia pun tidak akan dapat membela dirinya"},{id:44,text:"\u0647\u064f\u0646\u064e\u0627\u0644\u0650\u0643\u064e \u0671\u0644\u06e1\u0648\u064e\u0644\u064e\u0670\u064a\u064e\u0629\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650\u06da \u0647\u064f\u0648\u064e \u062e\u064e\u064a\u06e1\u0631\u065e \u062b\u064e\u0648\u064e\u0627\u0628\u0657\u0627 \u0648\u064e\u062e\u064e\u064a\u06e1\u0631\u064c \u0639\u064f\u0642\u06e1\u0628\u0657\u0627",translation:"Di sana, pertolongan itu hanya dari Allah Yang Mahabenar. Dialah (pemberi) pahala terbaik dan (pemberi) balasan terbaik"},{id:45,text:"\u0648\u064e\u0671\u0636\u06e1\u0631\u0650\u0628\u06e1 \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u062b\u064e\u0644\u064e \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u0650 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0643\u064e\u0645\u064e\u0627\u0653\u0621\u064d \u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0641\u064e\u0671\u062e\u06e1\u062a\u064e\u0644\u064e\u0637\u064e \u0628\u0650\u0647\u0650\u06e6 \u0646\u064e\u0628\u064e\u0627\u062a\u064f \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0641\u064e\u0623\u064e\u0635\u06e1\u0628\u064e\u062d\u064e \u0647\u064e\u0634\u0650\u064a\u0645\u0657\u0627 \u062a\u064e\u0630\u06e1\u0631\u064f\u0648\u0647\u064f \u0671\u0644\u0631\u0651\u0650\u064a\u064e\u0670\u062d\u064f\u06d7 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0645\u0651\u064f\u0642\u06e1\u062a\u064e\u062f\u0650\u0631\u064b\u0627",translation:"Dan buatkanlah untuk mereka (manusia) perumpamaan kehidupan dunia ini, ibarat air (hujan) yang Kami turunkan dari langit, sehingga menyuburkan tumbuh-tumbuhan di bumi, kemudian (tumbuh-tumbuhan) itu menjadi kering yang diterbangkan oleh angin. Dan Allah Mahakuasa atas segala sesuatu"},{id:46,text:"\u0671\u0644\u06e1\u0645\u064e\u0627\u0644\u064f \u0648\u064e\u0671\u0644\u06e1\u0628\u064e\u0646\u064f\u0648\u0646\u064e \u0632\u0650\u064a\u0646\u064e\u0629\u064f \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u0650 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627\u06d6 \u0648\u064e\u0671\u0644\u06e1\u0628\u064e\u0670\u0642\u0650\u064a\u064e\u0670\u062a\u064f \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u064f \u062e\u064e\u064a\u06e1\u0631\u064c \u0639\u0650\u0646\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u062b\u064e\u0648\u064e\u0627\u0628\u0657\u0627 \u0648\u064e\u062e\u064e\u064a\u06e1\u0631\u064c \u0623\u064e\u0645\u064e\u0644\u0657\u0627",translation:"Harta dan anak-anak adalah perhiasan kehidupan dunia tetapi amal kebajikan yang terus menerus adalah lebih baik pahalanya di sisi Tuhanmu serta lebih baik untuk menjadi harapan"},{id:47,text:"\u0648\u064e\u064a\u064e\u0648\u06e1\u0645\u064e \u0646\u064f\u0633\u064e\u064a\u0651\u0650\u0631\u064f \u0671\u0644\u06e1\u062c\u0650\u0628\u064e\u0627\u0644\u064e \u0648\u064e\u062a\u064e\u0631\u064e\u0649 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0628\u064e\u0627\u0631\u0650\u0632\u064e\u0629\u0657 \u0648\u064e\u062d\u064e\u0634\u064e\u0631\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0641\u064e\u0644\u064e\u0645\u06e1 \u0646\u064f\u063a\u064e\u0627\u062f\u0650\u0631\u06e1 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0623\u064e\u062d\u064e\u062f\u0657\u0627",translation:"Dan (ingatlah) pada hari (ketika) Kami perjalankan gunung-gunung dan engkau akan melihat bumi itu rata dan Kami kumpulkan mereka (seluruh manusia), dan tidak Kami tinggalkan seorang pun dari mereka"},{id:48,text:"\u0648\u064e\u0639\u064f\u0631\u0650\u0636\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0635\u064e\u0641\u0651\u0657\u0627 \u0644\u0651\u064e\u0642\u064e\u062f\u06e1 \u062c\u0650\u0626\u06e1\u062a\u064f\u0645\u064f\u0648\u0646\u064e\u0627 \u0643\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u06e1\u0646\u064e\u0670\u0643\u064f\u0645\u06e1 \u0623\u064e\u0648\u0651\u064e\u0644\u064e \u0645\u064e\u0631\u0651\u064e\u0629\u0650\u06ed\u06da \u0628\u064e\u0644\u06e1 \u0632\u064e\u0639\u064e\u0645\u06e1\u062a\u064f\u0645\u06e1 \u0623\u064e\u0644\u0651\u064e\u0646 \u0646\u0651\u064e\u062c\u06e1\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u064e\u0648\u06e1\u0639\u0650\u062f\u0657\u0627",translation:"Dan mereka akan dibawa ke hadapan Tuhanmu dengan berbaris. (Allah berfirman), \"Sesungguhnya kamu datang kepada Kami, sebagaimana Kami menciptakan kamu pada pertama kali; bahkan kamu menganggap bahwa Kami tidak akan menetapkan bagi kamu waktu (berbangkit untuk memenuhi) perjanjian"},{id:49,text:"\u0648\u064e\u0648\u064f\u0636\u0650\u0639\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064f \u0641\u064e\u062a\u064e\u0631\u064e\u0649 \u0671\u0644\u06e1\u0645\u064f\u062c\u06e1\u0631\u0650\u0645\u0650\u064a\u0646\u064e \u0645\u064f\u0634\u06e1\u0641\u0650\u0642\u0650\u064a\u0646\u064e \u0645\u0650\u0645\u0651\u064e\u0627 \u0641\u0650\u064a\u0647\u0650 \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u064a\u064e\u0670\u0648\u064e\u064a\u06e1\u0644\u064e\u062a\u064e\u0646\u064e\u0627 \u0645\u064e\u0627\u0644\u0650 \u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0644\u064e\u0627 \u064a\u064f\u063a\u064e\u0627\u062f\u0650\u0631\u064f \u0635\u064e\u063a\u0650\u064a\u0631\u064e\u0629\u0657 \u0648\u064e\u0644\u064e\u0627 \u0643\u064e\u0628\u0650\u064a\u0631\u064e\u0629\u064b \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u062d\u06e1\u0635\u064e\u0649\u0670\u0647\u064e\u0627\u06da \u0648\u064e\u0648\u064e\u062c\u064e\u062f\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u062d\u064e\u0627\u0636\u0650\u0631\u0657\u0627\u06d7 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0638\u06e1\u0644\u0650\u0645\u064f \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0623\u064e\u062d\u064e\u062f\u0657\u0627",translation:"Dan diletakkanlah kitab (catatan amal), lalu engkau akan melihat orang yang berdosa merasa ketakutan terhadap apa yang (tertulis) di dalamnya, dan mereka berkata, \"Betapa celaka kami, kitab apakah ini, tidak ada yang tertinggal, yang kecil dan yang besar melainkan tercatat semuanya,\" dan mereka dapati (semua) apa yang telah mereka kerjakan (tertulis). Dan Tuhanmu tidak menzalimi seorang jua pun"},{id:50,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0642\u064f\u0644\u06e1\u0646\u064e\u0627 \u0644\u0650\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u0650 \u0671\u0633\u06e1\u062c\u064f\u062f\u064f\u0648\u0627\u0652 \u0644\u0650\u0623\u0653\u062f\u064e\u0645\u064e \u0641\u064e\u0633\u064e\u062c\u064e\u062f\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0625\u0650\u0628\u06e1\u0644\u0650\u064a\u0633\u064e \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u062c\u0650\u0646\u0651\u0650 \u0641\u064e\u0641\u064e\u0633\u064e\u0642\u064e \u0639\u064e\u0646\u06e1 \u0623\u064e\u0645\u06e1\u0631\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u06e6\u0653\u06d7 \u0623\u064e\u0641\u064e\u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0646\u064e\u0647\u064f\u06e5 \u0648\u064e\u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u062a\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u0648\u06e1\u0644\u0650\u064a\u064e\u0627\u0653\u0621\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u064a \u0648\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0639\u064e\u062f\u064f\u0648\u0651\u064f\u06e2\u06da \u0628\u0650\u0626\u06e1\u0633\u064e \u0644\u0650\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0628\u064e\u062f\u064e\u0644\u0657\u0627",translation:"Dan (ingatlah) ketika Kami berfirman kepada para malaikat, \"Sujudlah kamu kepada Adam!\" Maka mereka pun sujud kecuali iblis. Dia adalah dari (golongan) jin, maka dia mendurhakai perintah Tuhannya. Pantaskah kamu menjadikan dia dan keturunannya sebagai pemimpin selain Aku, padahal mereka adalah musuhmu? Sangat buruklah (iblis itu) sebagai pengganti (Allah) bagi orang yang zalim"},{id:51,text:"\u06de\u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u0634\u06e1\u0647\u064e\u062f\u062a\u0651\u064f\u0647\u064f\u0645\u06e1 \u062e\u064e\u0644\u06e1\u0642\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0644\u064e\u0627 \u062e\u064e\u0644\u06e1\u0642\u064e \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f \u0645\u064f\u062a\u0651\u064e\u062e\u0650\u0630\u064e \u0671\u0644\u06e1\u0645\u064f\u0636\u0650\u0644\u0651\u0650\u064a\u0646\u064e \u0639\u064e\u0636\u064f\u062f\u0657\u0627",translation:"Aku tidak menghadirkan mereka (iblis dan anak cucunya) untuk menyaksikan penciptaan langit dan bumi dan tidak (pula) penciptaan diri mereka sendiri; dan Aku tidak menjadikan orang yang menyesatkan itu sebagai penolong"},{id:52,text:"\u0648\u064e\u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0646\u064e\u0627\u062f\u064f\u0648\u0627\u0652 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0653\u0621\u0650\u064a\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0632\u064e\u0639\u064e\u0645\u06e1\u062a\u064f\u0645\u06e1 \u0641\u064e\u062f\u064e\u0639\u064e\u0648\u06e1\u0647\u064f\u0645\u06e1 \u0641\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0633\u06e1\u062a\u064e\u062c\u0650\u064a\u0628\u064f\u0648\u0627\u0652 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u0648\u06e1\u0628\u0650\u0642\u0657\u0627",translation:"Dan (ingatlah) pada hari (ketika) Dia berfirman, \"Panggillah olehmu sekutu-sekutu-Ku yang kamu klaim itu!\" Mereka lalu memanggilnya, tetapi mereka (sekutu-sekutu) tidak membalas (seruan) mereka dan Kami adakan untuk mereka tempat kebinasaan (neraka)"},{id:53,text:"\u0648\u064e\u0631\u064e\u0621\u064e\u0627 \u0671\u0644\u06e1\u0645\u064f\u062c\u06e1\u0631\u0650\u0645\u064f\u0648\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u064e \u0641\u064e\u0638\u064e\u0646\u0651\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645 \u0645\u0651\u064f\u0648\u064e\u0627\u0642\u0650\u0639\u064f\u0648\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u062c\u0650\u062f\u064f\u0648\u0627\u0652 \u0639\u064e\u0646\u06e1\u0647\u064e\u0627 \u0645\u064e\u0635\u06e1\u0631\u0650\u0641\u0657\u0627",translation:"Dan orang yang berdosa melihat neraka, lalu mereka menduga, bahwa mereka akan jatuh ke dalamnya, dan mereka tidak menemukan tempat berpaling darinya"},{id:54,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0635\u064e\u0631\u0651\u064e\u0641\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a \u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u0650 \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0645\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u0645\u064e\u062b\u064e\u0644\u0656\u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064f \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064e \u0634\u064e\u064a\u06e1\u0621\u0656 \u062c\u064e\u062f\u064e\u0644\u0657\u0627",translation:"Dan sesungguhnya Kami telah menjelaskan berulang-ulang kepada manusia dalam Alquran ini dengan bermacam-macam perumpamaan. Tetapi manusia adalah memang yang paling banyak membantah"},{id:55,text:"\u0648\u064e\u0645\u064e\u0627 \u0645\u064e\u0646\u064e\u0639\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0623\u064e\u0646 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0630\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0647\u064f\u062f\u064e\u0649\u0670 \u0648\u064e\u064a\u064e\u0633\u06e1\u062a\u064e\u063a\u06e1\u0641\u0650\u0631\u064f\u0648\u0627\u0652 \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u062a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e\u0647\u064f\u0645\u06e1 \u0633\u064f\u0646\u0651\u064e\u0629\u064f \u0671\u0644\u06e1\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e \u0623\u064e\u0648\u06e1 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0642\u064f\u0628\u064f\u0644\u0657\u0627",translation:"Dan tidak ada (sesuatu pun) yang menghalangi manusia untuk beriman ketika petunjuk telah datang kepada mereka dan memohon ampunan kepada Tuhannya, kecuali (keinginan menanti) datangnya hukum (Allah yang telah berlaku pada) umat yang terdahulu atau datangnya azab atas mereka dengan nyata"},{id:56,text:"\u0648\u064e\u0645\u064e\u0627 \u0646\u064f\u0631\u06e1\u0633\u0650\u0644\u064f \u0671\u0644\u06e1\u0645\u064f\u0631\u06e1\u0633\u064e\u0644\u0650\u064a\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064f\u0628\u064e\u0634\u0651\u0650\u0631\u0650\u064a\u0646\u064e \u0648\u064e\u0645\u064f\u0646\u0630\u0650\u0631\u0650\u064a\u0646\u064e\u06da \u0648\u064e\u064a\u064f\u062c\u064e\u0670\u062f\u0650\u0644\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u06e1\u0628\u064e\u0670\u0637\u0650\u0644\u0650 \u0644\u0650\u064a\u064f\u062f\u06e1\u062d\u0650\u0636\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650 \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064e\u06d6 \u0648\u064e\u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0653\u0627\u0652 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u064a \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0646\u0630\u0650\u0631\u064f\u0648\u0627\u0652 \u0647\u064f\u0632\u064f\u0648\u0657\u0627",translation:"Dan Kami tidak mengutus rasul-rasul melainkan sebagai pembawa kabar gembira dan pemberi peringatan; tetapi orang yang kafir membantah dengan (cara) yang batil agar dengan demikian mereka dapat melenyapkan yang hak (kebenaran), dan mereka menjadikan ayat-ayat-Ku dan apa yang diperingatkan terhadap mereka sebagai olok-olokan"},{id:57,text:"\u0648\u064e\u0645\u064e\u0646\u06e1 \u0623\u064e\u0638\u06e1\u0644\u064e\u0645\u064f \u0645\u0650\u0645\u0651\u064e\u0646 \u0630\u064f\u0643\u0651\u0650\u0631\u064e \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u06e6 \u0641\u064e\u0623\u064e\u0639\u06e1\u0631\u064e\u0636\u064e \u0639\u064e\u0646\u06e1\u0647\u064e\u0627 \u0648\u064e\u0646\u064e\u0633\u0650\u064a\u064e \u0645\u064e\u0627 \u0642\u064e\u062f\u0651\u064e\u0645\u064e\u062a\u06e1 \u064a\u064e\u062f\u064e\u0627\u0647\u064f\u06da \u0625\u0650\u0646\u0651\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u06e1 \u0623\u064e\u0643\u0650\u0646\u0651\u064e\u0629\u064b \u0623\u064e\u0646 \u064a\u064e\u0641\u06e1\u0642\u064e\u0647\u064f\u0648\u0647\u064f \u0648\u064e\u0641\u0650\u064a\u0653 \u0621\u064e\u0627\u0630\u064e\u0627\u0646\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0642\u06e1\u0631\u0657\u0627\u06d6 \u0648\u064e\u0625\u0650\u0646 \u062a\u064e\u062f\u06e1\u0639\u064f\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u0647\u064f\u062f\u064e\u0649\u0670 \u0641\u064e\u0644\u064e\u0646 \u064a\u064e\u0647\u06e1\u062a\u064e\u062f\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0630\u064b\u0627 \u0623\u064e\u0628\u064e\u062f\u0657\u0627",translation:"Dan siapakah yang lebih zalim daripada orang yang telah diperingatkan dengan ayat-ayat Tuhannya, lalu dia berpaling darinya dan melupakan apa yang telah dikerjakan oleh kedua tangannya? Sungguh, Kami telah menjadikan hati mereka tertutup, (sehingga mereka tidak) memahaminya, dan (Kami letakkan pula) sumbatan di telinga mereka. Kendati pun engkau (Muhammad) menyeru mereka kepada petunjuk, niscaya mereka tidak akan mendapat petunjuk untuk selama-lamanya"},{id:58,text:"\u0648\u064e\u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0671\u0644\u06e1\u063a\u064e\u0641\u064f\u0648\u0631\u064f \u0630\u064f\u0648 \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0629\u0650\u06d6 \u0644\u064e\u0648\u06e1 \u064a\u064f\u0624\u064e\u0627\u062e\u0650\u0630\u064f\u0647\u064f\u0645 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064f\u0648\u0627\u0652 \u0644\u064e\u0639\u064e\u062c\u0651\u064e\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064e\u06da \u0628\u064e\u0644 \u0644\u0651\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u0648\u06e1\u0639\u0650\u062f\u065e \u0644\u0651\u064e\u0646 \u064a\u064e\u062c\u0650\u062f\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u06e6 \u0645\u064e\u0648\u06e1\u0626\u0650\u0644\u0657\u0627",translation:"Dan Tuhanmu Maha Pengampun, memiliki kasih sayang. Jika Dia hendak menyiksa mereka karena perbuatan mereka, tentu Dia akan menyegerakan siksa bagi mereka. Tetapi bagi mereka ada waktu tertentu (untuk mendapat siksa) yang mereka tidak akan menemukan tempat berlindung dari-Nya"},{id:59,text:"\u0648\u064e\u062a\u0650\u0644\u06e1\u0643\u064e \u0671\u0644\u06e1\u0642\u064f\u0631\u064e\u0649\u0670\u0653 \u0623\u064e\u0647\u06e1\u0644\u064e\u0643\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0644\u064e\u0645\u0651\u064e\u0627 \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627\u0652 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0644\u0650\u0645\u064e\u0647\u06e1\u0644\u0650\u0643\u0650\u0647\u0650\u0645 \u0645\u0651\u064e\u0648\u06e1\u0639\u0650\u062f\u0657\u0627",translation:"Dan (penduduk) negeri itu telah Kami binasakan ketika mereka berbuat zalim, dan telah Kami tetapkan waktu tertentu bagi kebinasaan mereka"},{id:60,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0644\u0650\u0641\u064e\u062a\u064e\u0649\u0670\u0647\u064f \u0644\u064e\u0627\u0653 \u0623\u064e\u0628\u06e1\u0631\u064e\u062d\u064f \u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0623\u064e\u0628\u06e1\u0644\u064f\u063a\u064e \u0645\u064e\u062c\u06e1\u0645\u064e\u0639\u064e \u0671\u0644\u06e1\u0628\u064e\u062d\u06e1\u0631\u064e\u064a\u06e1\u0646\u0650 \u0623\u064e\u0648\u06e1 \u0623\u064e\u0645\u06e1\u0636\u0650\u064a\u064e \u062d\u064f\u0642\u064f\u0628\u0657\u0627",translation:"Dan (ingatlah) ketika Musa berkata kepada pembantunya, \"Aku tidak akan berhenti (berjalan) sebelum sampai ke pertemuan dua laut; atau aku akan berjalan (terus sampai) bertahun-tahun"},{id:61,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0628\u064e\u0644\u064e\u063a\u064e\u0627 \u0645\u064e\u062c\u06e1\u0645\u064e\u0639\u064e \u0628\u064e\u064a\u06e1\u0646\u0650\u0647\u0650\u0645\u064e\u0627 \u0646\u064e\u0633\u0650\u064a\u064e\u0627 \u062d\u064f\u0648\u062a\u064e\u0647\u064f\u0645\u064e\u0627 \u0641\u064e\u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064e \u0633\u064e\u0628\u0650\u064a\u0644\u064e\u0647\u064f\u06e5 \u0641\u0650\u064a \u0671\u0644\u06e1\u0628\u064e\u062d\u06e1\u0631\u0650 \u0633\u064e\u0631\u064e\u0628\u0657\u0627",translation:"Maka ketika mereka sampai ke pertemuan dua laut itu, mereka lupa ikannya, lalu (ikan) itu melompat mengambil jalannya ke laut itu"},{id:62,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0648\u064e\u0632\u064e\u0627 \u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0641\u064e\u062a\u064e\u0649\u0670\u0647\u064f \u0621\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u063a\u064e\u062f\u064e\u0627\u0653\u0621\u064e\u0646\u064e\u0627 \u0644\u064e\u0642\u064e\u062f\u06e1 \u0644\u064e\u0642\u0650\u064a\u0646\u064e\u0627 \u0645\u0650\u0646 \u0633\u064e\u0641\u064e\u0631\u0650\u0646\u064e\u0627 \u0647\u064e\u0670\u0630\u064e\u0627 \u0646\u064e\u0635\u064e\u0628\u0657\u0627",translation:"Maka ketika mereka telah melewati (tempat itu), Musa berkata kepada pembantunya, \"Bawalah ke mari makanan kita; sungguh kita telah merasa letih karena perjalanan kita ini"},{id:63,text:"\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0631\u064e\u0621\u064e\u064a\u06e1\u062a\u064e \u0625\u0650\u0630\u06e1 \u0623\u064e\u0648\u064e\u064a\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0635\u0651\u064e\u062e\u06e1\u0631\u064e\u0629\u0650 \u0641\u064e\u0625\u0650\u0646\u0651\u0650\u064a \u0646\u064e\u0633\u0650\u064a\u062a\u064f \u0671\u0644\u06e1\u062d\u064f\u0648\u062a\u064e \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0633\u064e\u0649\u0670\u0646\u0650\u064a\u0647\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u064f \u0623\u064e\u0646\u06e1 \u0623\u064e\u0630\u06e1\u0643\u064f\u0631\u064e\u0647\u064f\u06e5\u06da \u0648\u064e\u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064e \u0633\u064e\u0628\u0650\u064a\u0644\u064e\u0647\u064f\u06e5 \u0641\u0650\u064a \u0671\u0644\u06e1\u0628\u064e\u062d\u06e1\u0631\u0650 \u0639\u064e\u062c\u064e\u0628\u0657\u0627",translation:"Dia (pembantunya) menjawab, \"Tahukah engkau ketika kita mencari tempat berlindung di batu tadi, maka aku lupa (menceritakan tentang) ikan itu dan tidak ada yang membuat aku lupa untuk mengingatnya kecuali setan, dan (ikan) itu mengambil jalannya ke laut dengan cara yang aneh sekali"},{id:64,text:"\u0642\u064e\u0627\u0644\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0646\u064e\u0628\u06e1\u063a\u0650\u06da \u0641\u064e\u0671\u0631\u06e1\u062a\u064e\u062f\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0621\u064e\u0627\u062b\u064e\u0627\u0631\u0650\u0647\u0650\u0645\u064e\u0627 \u0642\u064e\u0635\u064e\u0635\u0657\u0627",translation:"Dia (Musa) berkata, \"Itulah (tempat) yang kita cari.\" Lalu keduanya kembali, mengikuti jejak mereka semula"},{id:65,text:"\u0641\u064e\u0648\u064e\u062c\u064e\u062f\u064e\u0627 \u0639\u064e\u0628\u06e1\u062f\u0657\u0627 \u0645\u0651\u0650\u0646\u06e1 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0646\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f \u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u0657 \u0645\u0651\u0650\u0646\u06e1 \u0639\u0650\u0646\u062f\u0650\u0646\u064e\u0627 \u0648\u064e\u0639\u064e\u0644\u0651\u064e\u0645\u06e1\u0646\u064e\u0670\u0647\u064f \u0645\u0650\u0646 \u0644\u0651\u064e\u062f\u064f\u0646\u0651\u064e\u0627 \u0639\u0650\u0644\u06e1\u0645\u0657\u0627",translation:"lalu mereka berdua bertemu dengan seorang hamba di antara hamba-hamba Kami, yang telah Kami berikan rahmat kepadanya dari sisi Kami, dan yang telah Kami ajarkan ilmu kepadanya dari sisi Kami"},{id:66,text:"\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f\u06e5 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0647\u064e\u0644\u06e1 \u0623\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0643\u064e \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0646 \u062a\u064f\u0639\u064e\u0644\u0651\u0650\u0645\u064e\u0646\u0650 \u0645\u0650\u0645\u0651\u064e\u0627 \u0639\u064f\u0644\u0651\u0650\u0645\u06e1\u062a\u064e \u0631\u064f\u0634\u06e1\u062f\u0657\u0627",translation:"Musa berkata kepadanya, \"Bolehkah aku mengikutimu agar engkau mengajarkan kepadaku (ilmu yang benar) yang telah diajarkan kepadamu (untuk menjadi) petunjuk"},{id:67,text:"\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u0646 \u062a\u064e\u0633\u06e1\u062a\u064e\u0637\u0650\u064a\u0639\u064e \u0645\u064e\u0639\u0650\u064a\u064e \u0635\u064e\u0628\u06e1\u0631\u0657\u0627",translation:"Dia menjawab, \"Sungguh, engkau tidak akan sanggup sabar bersamaku"},{id:68,text:"\u0648\u064e\u0643\u064e\u064a\u06e1\u0641\u064e \u062a\u064e\u0635\u06e1\u0628\u0650\u0631\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0644\u064e\u0645\u06e1 \u062a\u064f\u062d\u0650\u0637\u06e1 \u0628\u0650\u0647\u0650\u06e6 \u062e\u064f\u0628\u06e1\u0631\u0657\u0627",translation:"Dan bagaimana engkau akan dapat bersabar atas sesuatu, sedang engkau belum mempunyai pengetahuan yang cukup tentang hal itu"},{id:69,text:"\u0642\u064e\u0627\u0644\u064e \u0633\u064e\u062a\u064e\u062c\u0650\u062f\u064f\u0646\u0650\u064a\u0653 \u0625\u0650\u0646 \u0634\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0635\u064e\u0627\u0628\u0650\u0631\u0657\u0627 \u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064e\u0639\u06e1\u0635\u0650\u064a \u0644\u064e\u0643\u064e \u0623\u064e\u0645\u06e1\u0631\u0657\u0627",translation:"Dia (Musa) berkata, \"Insya Allah akan engkau dapati aku orang yang sabar, dan aku tidak akan menentangmu dalam urusan apa pun"},{id:70,text:"\u0642\u064e\u0627\u0644\u064e \u0641\u064e\u0625\u0650\u0646\u0650 \u0671\u062a\u0651\u064e\u0628\u064e\u0639\u06e1\u062a\u064e\u0646\u0650\u064a \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u06e1\u0646\u0650\u064a \u0639\u064e\u0646 \u0634\u064e\u064a\u06e1\u0621\u064d \u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0623\u064f\u062d\u06e1\u062f\u0650\u062b\u064e \u0644\u064e\u0643\u064e \u0645\u0650\u0646\u06e1\u0647\u064f \u0630\u0650\u0643\u06e1\u0631\u0657\u0627",translation:"Dia berkata, \"Jika engkau mengikutiku, maka janganlah engkau menanyakan kepadaku tentang sesuatu apa pun, sampai aku menerangkannya kepadamu"},{id:71,text:"\u0641\u064e\u0671\u0646\u0637\u064e\u0644\u064e\u0642\u064e\u0627 \u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u064e\u0627 \u0631\u064e\u0643\u0650\u0628\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0641\u0650\u064a\u0646\u064e\u0629\u0650 \u062e\u064e\u0631\u064e\u0642\u064e\u0647\u064e\u0627\u06d6 \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u062e\u064e\u0631\u064e\u0642\u06e1\u062a\u064e\u0647\u064e\u0627 \u0644\u0650\u062a\u064f\u063a\u06e1\u0631\u0650\u0642\u064e \u0623\u064e\u0647\u06e1\u0644\u064e\u0647\u064e\u0627 \u0644\u064e\u0642\u064e\u062f\u06e1 \u062c\u0650\u0626\u06e1\u062a\u064e \u0634\u064e\u064a\u06e1\u0640\u0654\u064b\u0627 \u0625\u0650\u0645\u06e1\u0631\u0657\u0627",translation:"Maka berjalanlah keduanya, hingga ketika keduanya menaiki perahu lalu dia melubanginya. Dia (Musa) berkata, \"Mengapa engkau melubangi perahu itu, apakah untuk menenggelamkan penumpangnya?\" Sungguh, engkau telah berbuat suatu kesalahan yang besar"},{id:72,text:"\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0644\u064e\u0645\u06e1 \u0623\u064e\u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u0646 \u062a\u064e\u0633\u06e1\u062a\u064e\u0637\u0650\u064a\u0639\u064e \u0645\u064e\u0639\u0650\u064a\u064e \u0635\u064e\u0628\u06e1\u0631\u0657\u0627",translation:"Dia berkata, \"Bukankah sudah kukatakan, bahwa engkau tidak akan mampu sabar bersamaku"},{id:73,text:"\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0627 \u062a\u064f\u0624\u064e\u0627\u062e\u0650\u0630\u06e1\u0646\u0650\u064a \u0628\u0650\u0645\u064e\u0627 \u0646\u064e\u0633\u0650\u064a\u062a\u064f \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0631\u06e1\u0647\u0650\u0642\u06e1\u0646\u0650\u064a \u0645\u0650\u0646\u06e1 \u0623\u064e\u0645\u06e1\u0631\u0650\u064a \u0639\u064f\u0633\u06e1\u0631\u0657\u0627",translation:"Dia (Musa) berkata, \"Janganlah engkau menghukum aku karena kelupaanku dan janganlah engkau membebani aku dengan suatu kesulitan dalam urusanku"},{id:74,text:"\u0641\u064e\u0671\u0646\u0637\u064e\u0644\u064e\u0642\u064e\u0627 \u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u064e\u0627 \u0644\u064e\u0642\u0650\u064a\u064e\u0627 \u063a\u064f\u0644\u064e\u0670\u0645\u0657\u0627 \u0641\u064e\u0642\u064e\u062a\u064e\u0644\u064e\u0647\u064f\u06e5 \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0642\u064e\u062a\u064e\u0644\u06e1\u062a\u064e \u0646\u064e\u0641\u06e1\u0633\u0657\u0627 \u0632\u064e\u0643\u0650\u064a\u0651\u064e\u0629\u064e\u06e2 \u0628\u0650\u063a\u064e\u064a\u06e1\u0631\u0650 \u0646\u064e\u0641\u06e1\u0633\u0656 \u0644\u0651\u064e\u0642\u064e\u062f\u06e1 \u062c\u0650\u0626\u06e1\u062a\u064e \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627 \u0646\u0651\u064f\u0643\u06e1\u0631\u0657\u0627",translation:"Maka berjalanlah keduanya; hingga ketika keduanya berjumpa dengan seorang anak muda, maka dia membunuhnya. Dia (Musa) berkata, \"Mengapa engkau bunuh jiwa yang bersih, bukan karena dia membunuh orang lain? Sungguh, engkau telah melakukan sesuatu yang sangat mungkar"},{id:75,text:"\u06de\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0644\u064e\u0645\u06e1 \u0623\u064e\u0642\u064f\u0644 \u0644\u0651\u064e\u0643\u064e \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u0646 \u062a\u064e\u0633\u06e1\u062a\u064e\u0637\u0650\u064a\u0639\u064e \u0645\u064e\u0639\u0650\u064a\u064e \u0635\u064e\u0628\u06e1\u0631\u0657\u0627",translation:"Dia berkata, \"Bukankah sudah kukatakan kepadamu, bahwa engkau tidak akan mampu sabar bersamaku"},{id:76,text:"\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646 \u0633\u064e\u0623\u064e\u0644\u06e1\u062a\u064f\u0643\u064e \u0639\u064e\u0646 \u0634\u064e\u064a\u06e1\u0621\u0650\u06ed \u0628\u064e\u0639\u06e1\u062f\u064e\u0647\u064e\u0627 \u0641\u064e\u0644\u064e\u0627 \u062a\u064f\u0635\u064e\u0670\u062d\u0650\u0628\u06e1\u0646\u0650\u064a\u06d6 \u0642\u064e\u062f\u06e1 \u0628\u064e\u0644\u064e\u063a\u06e1\u062a\u064e \u0645\u0650\u0646 \u0644\u0651\u064e\u062f\u064f\u0646\u0651\u0650\u064a \u0639\u064f\u0630\u06e1\u0631\u0657\u0627",translation:"Dia (Musa) berkata, \"Jika aku bertanya kepadamu tentang sesuatu setelah ini, maka jangan lagi engkau memperbolehkan aku menyertaimu, sesungguhnya engkau sudah cukup (bersabar) menerima alasan dariku"},{id:77,text:"\u0641\u064e\u0671\u0646\u0637\u064e\u0644\u064e\u0642\u064e\u0627 \u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u064e\u0627\u0653 \u0623\u064e\u062a\u064e\u064a\u064e\u0627\u0653 \u0623\u064e\u0647\u06e1\u0644\u064e \u0642\u064e\u0631\u06e1\u064a\u064e\u0629\u064d \u0671\u0633\u06e1\u062a\u064e\u0637\u06e1\u0639\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0647\u06e1\u0644\u064e\u0647\u064e\u0627 \u0641\u064e\u0623\u064e\u0628\u064e\u0648\u06e1\u0627\u0652 \u0623\u064e\u0646 \u064a\u064f\u0636\u064e\u064a\u0651\u0650\u0641\u064f\u0648\u0647\u064f\u0645\u064e\u0627 \u0641\u064e\u0648\u064e\u062c\u064e\u062f\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u062c\u0650\u062f\u064e\u0627\u0631\u0657\u0627 \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0623\u064e\u0646 \u064a\u064e\u0646\u0642\u064e\u0636\u0651\u064e \u0641\u064e\u0623\u064e\u0642\u064e\u0627\u0645\u064e\u0647\u064f\u06e5\u06d6 \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0648\u06e1 \u0634\u0650\u0626\u06e1\u062a\u064e \u0644\u064e\u062a\u0651\u064e\u062e\u064e\u0630\u06e1\u062a\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0623\u064e\u062c\u06e1\u0631\u0657\u0627",translation:"Maka keduanya berjalan; hingga ketika keduanya sampai kepada penduduk suatu negeri, mereka berdua meminta dijamu oleh penduduknya, tetapi mereka (penduduk negeri itu) tidak mau menjamu mereka, kemudian keduanya mendapatkan dinding rumah yang hampir roboh (di negeri itu), lalu dia menegakkannya. Dia (Musa) berkata, \"Jika engkau mau, niscaya engkau dapat meminta imbalan untuk itu"},{id:78,text:"\u0642\u064e\u0627\u0644\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0641\u0650\u0631\u064e\u0627\u0642\u064f \u0628\u064e\u064a\u06e1\u0646\u0650\u064a \u0648\u064e\u0628\u064e\u064a\u06e1\u0646\u0650\u0643\u064e\u06da \u0633\u064e\u0623\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0643\u064e \u0628\u0650\u062a\u064e\u0623\u06e1\u0648\u0650\u064a\u0644\u0650 \u0645\u064e\u0627 \u0644\u064e\u0645\u06e1 \u062a\u064e\u0633\u06e1\u062a\u064e\u0637\u0650\u0639 \u0639\u0651\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0635\u064e\u0628\u06e1\u0631\u064b\u0627",translation:"Dia berkata, \"Inilah perpisahan antara aku dengan engkau; aku akan memberikan penjelasan kepadamu atas perbuatan yang engkau tidak mampu sabar terhadapnya"},{id:79,text:"\u0623\u064e\u0645\u0651\u064e\u0627 \u0671\u0644\u0633\u0651\u064e\u0641\u0650\u064a\u0646\u064e\u0629\u064f \u0641\u064e\u0643\u064e\u0627\u0646\u064e\u062a\u06e1 \u0644\u0650\u0645\u064e\u0633\u064e\u0670\u0643\u0650\u064a\u0646\u064e \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0628\u064e\u062d\u06e1\u0631\u0650 \u0641\u064e\u0623\u064e\u0631\u064e\u062f\u062a\u0651\u064f \u0623\u064e\u0646\u06e1 \u0623\u064e\u0639\u0650\u064a\u0628\u064e\u0647\u064e\u0627 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0648\u064e\u0631\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u0644\u0650\u0643\u065e \u064a\u064e\u0623\u06e1\u062e\u064f\u0630\u064f \u0643\u064f\u0644\u0651\u064e \u0633\u064e\u0641\u0650\u064a\u0646\u064e\u0629\u064d \u063a\u064e\u0635\u06e1\u0628\u0657\u0627",translation:"Adapun perahu itu adalah milik orang miskin yang bekerja di laut; aku bermaksud merusaknya, karena di hadapan mereka ada seorang raja yang akan merampas setiap perahu"},{id:80,text:"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0671\u0644\u06e1\u063a\u064f\u0644\u064e\u0670\u0645\u064f \u0641\u064e\u0643\u064e\u0627\u0646\u064e \u0623\u064e\u0628\u064e\u0648\u064e\u0627\u0647\u064f \u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064e\u064a\u06e1\u0646\u0650 \u0641\u064e\u062e\u064e\u0634\u0650\u064a\u0646\u064e\u0627\u0653 \u0623\u064e\u0646 \u064a\u064f\u0631\u06e1\u0647\u0650\u0642\u064e\u0647\u064f\u0645\u064e\u0627 \u0637\u064f\u063a\u06e1\u064a\u064e\u0670\u0646\u0657\u0627 \u0648\u064e\u0643\u064f\u0641\u06e1\u0631\u0657\u0627",translation:"Dan adapun anak muda (kafir) itu, kedua orang tuanya mukmin, dan kami khawatir kalau dia akan memaksa kedua orang tuanya kepada kesesatan dan kekafiran"},{id:81,text:"\u0641\u064e\u0623\u064e\u0631\u064e\u062f\u06e1\u0646\u064e\u0627\u0653 \u0623\u064e\u0646 \u064a\u064f\u0628\u06e1\u062f\u0650\u0644\u064e\u0647\u064f\u0645\u064e\u0627 \u0631\u064e\u0628\u0651\u064f\u0647\u064f\u0645\u064e\u0627 \u062e\u064e\u064a\u06e1\u0631\u0657\u0627 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f \u0632\u064e\u0643\u064e\u0648\u0670\u0629\u0657 \u0648\u064e\u0623\u064e\u0642\u06e1\u0631\u064e\u0628\u064e \u0631\u064f\u062d\u06e1\u0645\u0657\u0627",translation:"Kemudian kami menghendaki, sekiranya Tuhan mereka menggantinya dengan (seorang anak lain) yang lebih baik kesuciannya daripada (anak) itu dan lebih sayang (kepada ibu bapaknya)"},{id:82,text:"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0671\u0644\u06e1\u062c\u0650\u062f\u064e\u0627\u0631\u064f \u0641\u064e\u0643\u064e\u0627\u0646\u064e \u0644\u0650\u063a\u064f\u0644\u064e\u0670\u0645\u064e\u064a\u06e1\u0646\u0650 \u064a\u064e\u062a\u0650\u064a\u0645\u064e\u064a\u06e1\u0646\u0650 \u0641\u0650\u064a \u0671\u0644\u06e1\u0645\u064e\u062f\u0650\u064a\u0646\u064e\u0629\u0650 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u062a\u064e\u062d\u06e1\u062a\u064e\u0647\u064f\u06e5 \u0643\u064e\u0646\u0632\u065e \u0644\u0651\u064e\u0647\u064f\u0645\u064e\u0627 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0623\u064e\u0628\u064f\u0648\u0647\u064f\u0645\u064e\u0627 \u0635\u064e\u0670\u0644\u0650\u062d\u0657\u0627 \u0641\u064e\u0623\u064e\u0631\u064e\u0627\u062f\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0623\u064e\u0646 \u064a\u064e\u0628\u06e1\u0644\u064f\u063a\u064e\u0627\u0653 \u0623\u064e\u0634\u064f\u062f\u0651\u064e\u0647\u064f\u0645\u064e\u0627 \u0648\u064e\u064a\u064e\u0633\u06e1\u062a\u064e\u062e\u06e1\u0631\u0650\u062c\u064e\u0627 \u0643\u064e\u0646\u0632\u064e\u0647\u064f\u0645\u064e\u0627 \u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u0657 \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064e\u06da \u0648\u064e\u0645\u064e\u0627 \u0641\u064e\u0639\u064e\u0644\u06e1\u062a\u064f\u0647\u064f\u06e5 \u0639\u064e\u0646\u06e1 \u0623\u064e\u0645\u06e1\u0631\u0650\u064a\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062a\u064e\u0623\u06e1\u0648\u0650\u064a\u0644\u064f \u0645\u064e\u0627 \u0644\u064e\u0645\u06e1 \u062a\u064e\u0633\u06e1\u0637\u0650\u0639 \u0639\u0651\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0635\u064e\u0628\u06e1\u0631\u0657\u0627",translation:"Dan adapun dinding rumah itu adalah milik dua anak yatim di kota itu, yang di bawahnya tersimpan harta bagi mereka berdua, dan ayahnya seorang yang saleh. Maka Tuhanmu menghendaki agar keduanya sampai dewasa dan keduanya mengeluarkan simpanannya itu sebagai rahmat dari Tuhanmu. Apa yang kuperbuat bukan menurut kemauanku sendiri. Itulah keterangan perbuatan-perbuatan yang engkau tidak sabar terhadapnya"},{id:83,text:"\u0648\u064e\u064a\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u0639\u064e\u0646 \u0630\u0650\u064a \u0671\u0644\u06e1\u0642\u064e\u0631\u06e1\u0646\u064e\u064a\u06e1\u0646\u0650\u06d6 \u0642\u064f\u0644\u06e1 \u0633\u064e\u0623\u064e\u062a\u06e1\u0644\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f \u0630\u0650\u0643\u06e1\u0631\u064b\u0627",translation:"Dan mereka bertanya kepadamu (Muhammad) tentang Zulkarnain. Katakanlah, \"Akan kubacakan kepadamu kisahnya"},{id:84,text:"\u0625\u0650\u0646\u0651\u064e\u0627 \u0645\u064e\u0643\u0651\u064e\u0646\u0651\u064e\u0627 \u0644\u064e\u0647\u064f\u06e5 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f \u0645\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0633\u064e\u0628\u064e\u0628\u0657\u0627",translation:"Sungguh, Kami telah memberi kedudukan kepadanya di bumi, dan Kami telah memberikan jalan kepadanya (untuk mencapai) segala sesuatu"},{id:85,text:"\u0641\u064e\u0623\u064e\u062a\u06e1\u0628\u064e\u0639\u064e \u0633\u064e\u0628\u064e\u0628\u064b\u0627",translation:"maka dia pun menempuh suatu jalan"},{id:86,text:"\u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u064e\u0627 \u0628\u064e\u0644\u064e\u063a\u064e \u0645\u064e\u063a\u06e1\u0631\u0650\u0628\u064e \u0671\u0644\u0634\u0651\u064e\u0645\u06e1\u0633\u0650 \u0648\u064e\u062c\u064e\u062f\u064e\u0647\u064e\u0627 \u062a\u064e\u063a\u06e1\u0631\u064f\u0628\u064f \u0641\u0650\u064a \u0639\u064e\u064a\u06e1\u0646\u064d \u062d\u064e\u0645\u0650\u0626\u064e\u0629\u0656 \u0648\u064e\u0648\u064e\u062c\u064e\u062f\u064e \u0639\u0650\u0646\u062f\u064e\u0647\u064e\u0627 \u0642\u064e\u0648\u06e1\u0645\u0657\u0627\u06d6 \u0642\u064f\u0644\u06e1\u0646\u064e\u0627 \u064a\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u06e1\u0642\u064e\u0631\u06e1\u0646\u064e\u064a\u06e1\u0646\u0650 \u0625\u0650\u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u062a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064e \u0648\u064e\u0625\u0650\u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064e \u0641\u0650\u064a\u0647\u0650\u0645\u06e1 \u062d\u064f\u0633\u06e1\u0646\u0657\u0627",translation:"(Hingga ketika dia telah sampai di tempat matahari terbenam,496) dia melihatnya (matahari) terbenam di dalam laut yang berlumpur hitam, dan di sana ditemukannya suatu kaum (tidak beragama). Kami berfirman, \"Wahai Zulkarnain! Engkau boleh menghukum atau berbuat kebaikan (mengajak beriman) kepada mereka"},{id:87,text:"\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0645\u0651\u064e\u0627 \u0645\u064e\u0646 \u0638\u064e\u0644\u064e\u0645\u064e \u0641\u064e\u0633\u064e\u0648\u06e1\u0641\u064e \u0646\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064f\u0647\u064f\u06e5 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0631\u064e\u062f\u0651\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u06e6 \u0641\u064e\u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064f\u0647\u064f\u06e5 \u0639\u064e\u0630\u064e\u0627\u0628\u0657\u0627 \u0646\u0651\u064f\u0643\u06e1\u0631\u0657\u0627",translation:"Dia (Zulkarnain) berkata, \"Barangsiapa berbuat zalim, Kami akan menghukumnya, lalu dia akan dikembalikan kepada Tuhannya, kemudian Tuhan mengazabnya dengan azab yang sangat keras"},{id:88,text:"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0645\u064e\u0646\u06e1 \u0621\u064e\u0627\u0645\u064e\u0646\u064e \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064e \u0635\u064e\u0670\u0644\u0650\u062d\u0657\u0627 \u0641\u064e\u0644\u064e\u0647\u064f\u06e5 \u062c\u064e\u0632\u064e\u0627\u0653\u0621\u064b \u0671\u0644\u06e1\u062d\u064f\u0633\u06e1\u0646\u064e\u0649\u0670\u06d6 \u0648\u064e\u0633\u064e\u0646\u064e\u0642\u064f\u0648\u0644\u064f \u0644\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646\u06e1 \u0623\u064e\u0645\u06e1\u0631\u0650\u0646\u064e\u0627 \u064a\u064f\u0633\u06e1\u0631\u0657\u0627",translation:"Adapun orang yang beriman dan mengerjakan kebajikan, maka dia mendapat (pahala) yang terbaik sebagai balasan, dan akan kami sampaikan kepadanya perintah kami yang mudah-mudah"},{id:89,text:"\u062b\u064f\u0645\u0651\u064e \u0623\u064e\u062a\u06e1\u0628\u064e\u0639\u064e \u0633\u064e\u0628\u064e\u0628\u064b\u0627",translation:"Kemudian dia menempuh suatu jalan (yang lain)"},{id:90,text:"\u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u064e\u0627 \u0628\u064e\u0644\u064e\u063a\u064e \u0645\u064e\u0637\u06e1\u0644\u0650\u0639\u064e \u0671\u0644\u0634\u0651\u064e\u0645\u06e1\u0633\u0650 \u0648\u064e\u062c\u064e\u062f\u064e\u0647\u064e\u0627 \u062a\u064e\u0637\u06e1\u0644\u064f\u0639\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u06e1\u0645\u0656 \u0644\u0651\u064e\u0645\u06e1 \u0646\u064e\u062c\u06e1\u0639\u064e\u0644 \u0644\u0651\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u064e\u0627 \u0633\u0650\u062a\u06e1\u0631\u0657\u0627",translation:"Hingga ketika dia sampai di tempat terbit matahari (sebelah Timur) didapatinya (matahari) bersinar di atas suatu kaum yang tidak Kami buatkan suatu pelindung bagi mereka dari (cahaya matahari)497) itu"},{id:91,text:"\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e\u06d6 \u0648\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u062d\u064e\u0637\u06e1\u0646\u064e\u0627 \u0628\u0650\u0645\u064e\u0627 \u0644\u064e\u062f\u064e\u064a\u06e1\u0647\u0650 \u062e\u064f\u0628\u06e1\u0631\u0657\u0627",translation:"demikianlah, dan sesungguhnya Kami mengetahui segala sesuatu yang ada padanya (Zulkarnain)"},{id:92,text:"\u062b\u064f\u0645\u0651\u064e \u0623\u064e\u062a\u06e1\u0628\u064e\u0639\u064e \u0633\u064e\u0628\u064e\u0628\u064b\u0627",translation:"Kemudian dia menempuh suatu jalan (yang lain lagi)"},{id:93,text:"\u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u064e\u0627 \u0628\u064e\u0644\u064e\u063a\u064e \u0628\u064e\u064a\u06e1\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u062f\u0651\u064e\u064a\u06e1\u0646\u0650 \u0648\u064e\u062c\u064e\u062f\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u0645\u064e\u0627 \u0642\u064e\u0648\u06e1\u0645\u0657\u0627 \u0644\u0651\u064e\u0627 \u064a\u064e\u0643\u064e\u0627\u062f\u064f\u0648\u0646\u064e \u064a\u064e\u0641\u06e1\u0642\u064e\u0647\u064f\u0648\u0646\u064e \u0642\u064e\u0648\u06e1\u0644\u0657\u0627",translation:"Hingga ketika dia sampai di antara dua gunung, didapatinya di belakang (kedua gunung itu) suatu kaum yang hampir tidak memahami pembicaraan"},{id:94,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u064a\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u06e1\u0642\u064e\u0631\u06e1\u0646\u064e\u064a\u06e1\u0646\u0650 \u0625\u0650\u0646\u0651\u064e \u064a\u064e\u0623\u06e1\u062c\u064f\u0648\u062c\u064e \u0648\u064e\u0645\u064e\u0623\u06e1\u062c\u064f\u0648\u062c\u064e \u0645\u064f\u0641\u06e1\u0633\u0650\u062f\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0641\u064e\u0647\u064e\u0644\u06e1 \u0646\u064e\u062c\u06e1\u0639\u064e\u0644\u064f \u0644\u064e\u0643\u064e \u062e\u064e\u0631\u06e1\u062c\u064b\u0627 \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0646 \u062a\u064e\u062c\u06e1\u0639\u064e\u0644\u064e \u0628\u064e\u064a\u06e1\u0646\u064e\u0646\u064e\u0627 \u0648\u064e\u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1 \u0633\u064e\u062f\u0651\u0657\u0627",translation:"(Mereka berkata, \"Wahai Zulkarnain! Sungguh, Ya`j\u016bj dan Ma`j\u016bj499) itu (makhluk yang) berbuat kerusakan di bumi, maka bolehkah kami membayarmu imbalan agar engkau membuatkan dinding penghalang antara kami dan mereka"},{id:95,text:"\u0642\u064e\u0627\u0644\u064e \u0645\u064e\u0627 \u0645\u064e\u0643\u0651\u064e\u0646\u0651\u0650\u064a \u0641\u0650\u064a\u0647\u0650 \u0631\u064e\u0628\u0651\u0650\u064a \u062e\u064e\u064a\u06e1\u0631\u065e \u0641\u064e\u0623\u064e\u0639\u0650\u064a\u0646\u064f\u0648\u0646\u0650\u064a \u0628\u0650\u0642\u064f\u0648\u0651\u064e\u0629\u064d \u0623\u064e\u062c\u06e1\u0639\u064e\u0644\u06e1 \u0628\u064e\u064a\u06e1\u0646\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1 \u0631\u064e\u062f\u06e1\u0645\u064b\u0627",translation:"Dia (Zulkarnain) berkata, \"Apa yang telah dianugerahkan Tuhan kepadaku lebih baik (daripada imbalanmu), maka bantulah aku dengan kekuatan, agar aku dapat membuatkan dinding penghalang antara kamu dan mereka"},{id:96,text:"\u0621\u064e\u0627\u062a\u064f\u0648\u0646\u0650\u064a \u0632\u064f\u0628\u064e\u0631\u064e \u0671\u0644\u06e1\u062d\u064e\u062f\u0650\u064a\u062f\u0650\u06d6 \u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u064e\u0627 \u0633\u064e\u0627\u0648\u064e\u0649\u0670 \u0628\u064e\u064a\u06e1\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u062f\u064e\u0641\u064e\u064a\u06e1\u0646\u0650 \u0642\u064e\u0627\u0644\u064e \u0671\u0646\u0641\u064f\u062e\u064f\u0648\u0627\u0652\u06d6 \u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u064e\u0647\u064f\u06e5 \u0646\u064e\u0627\u0631\u0657\u0627 \u0642\u064e\u0627\u0644\u064e \u0621\u064e\u0627\u062a\u064f\u0648\u0646\u0650\u064a\u0653 \u0623\u064f\u0641\u06e1\u0631\u0650\u063a\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0642\u0650\u0637\u06e1\u0631\u0657\u0627",translation:"berilah aku potongan-potongan besi!\" Hingga ketika (potongan) besi itu telah (terpasang) sama rata dengan kedua (puncak) gunung itu, dia (Zulkarnain) berkata, \"Tiuplah (api itu)!\" Ketika (besi) itu sudah menjadi (merah seperti) api, dia pun berkata, \"Berilah aku tembaga (yang mendidih) agar kutuangkan ke atasnya (besi panas itu)"},{id:97,text:"\u0641\u064e\u0645\u064e\u0627 \u0671\u0633\u06e1\u0637\u064e\u0670\u0639\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646 \u064a\u064e\u0638\u06e1\u0647\u064e\u0631\u064f\u0648\u0647\u064f \u0648\u064e\u0645\u064e\u0627 \u0671\u0633\u06e1\u062a\u064e\u0637\u064e\u0670\u0639\u064f\u0648\u0627\u0652 \u0644\u064e\u0647\u064f\u06e5 \u0646\u064e\u0642\u06e1\u0628\u0657\u0627",translation:"Maka mereka (Ya`j\u016bj dan Ma`j\u016bj) tidak dapat mendakinya dan tidak dapat (pula) melubanginya"},{id:98,text:"\u0642\u064e\u0627\u0644\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u065e \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u064a\u06d6 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e \u0648\u064e\u0639\u06e1\u062f\u064f \u0631\u064e\u0628\u0651\u0650\u064a \u062c\u064e\u0639\u064e\u0644\u064e\u0647\u064f\u06e5 \u062f\u064e\u0643\u0651\u064e\u0627\u0653\u0621\u064e\u06d6 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0648\u064e\u0639\u06e1\u062f\u064f \u0631\u064e\u0628\u0651\u0650\u064a \u062d\u064e\u0642\u0651\u0657\u0627",translation:"Dia (Zulkarnain) berkata, \"(Dinding) ini adalah rahmat dari Tuhanku, maka apabila janji Tuhanku sudah datang, Dia akan menghancurluluhkannya; dan janji Tuhanku itu benar"},{id:99,text:"\u06de\u0648\u064e\u062a\u064e\u0631\u064e\u0643\u06e1\u0646\u064e\u0627 \u0628\u064e\u0639\u06e1\u0636\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u064a\u064e\u0645\u064f\u0648\u062c\u064f \u0641\u0650\u064a \u0628\u064e\u0639\u06e1\u0636\u0656\u06d6 \u0648\u064e\u0646\u064f\u0641\u0650\u062e\u064e \u0641\u0650\u064a \u0671\u0644\u0635\u0651\u064f\u0648\u0631\u0650 \u0641\u064e\u062c\u064e\u0645\u064e\u0639\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u062c\u064e\u0645\u06e1\u0639\u0657\u0627",translation:"Dan pada hari itu Kami biarkan mereka (Ya`j\u016bj dan Ma`j\u016bj) berbaur antara satu dengan yang lain, dan (apabila) sangkakala ditiup (lagi), akan Kami kumpulkan mereka semuanya"},{id:100,text:"\u0648\u064e\u0639\u064e\u0631\u064e\u0636\u06e1\u0646\u064e\u0627 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u0644\u0651\u0650\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0639\u064e\u0631\u06e1\u0636\u064b\u0627",translation:"dan Kami perlihatkan (neraka) Jahanam dengan jelas pada hari itu kepada orang kafir"},{id:101,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0627\u0646\u064e\u062a\u06e1 \u0623\u064e\u0639\u06e1\u064a\u064f\u0646\u064f\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u063a\u0650\u0637\u064e\u0627\u0653\u0621\u064d \u0639\u064e\u0646 \u0630\u0650\u0643\u06e1\u0631\u0650\u064a \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u064e \u0633\u064e\u0645\u06e1\u0639\u064b\u0627",translation:"(yaitu) orang yang mata (hati)nya dalam keadaan tertutup (tidak mampu) dari memperhatikan tanda-tanda (kebesaran)-Ku, dan mereka tidak sanggup mendengar"},{id:102,text:"\u0623\u064e\u0641\u064e\u062d\u064e\u0633\u0650\u0628\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646 \u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0627\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u064a\u0653 \u0623\u064e\u0648\u06e1\u0644\u0650\u064a\u064e\u0627\u0653\u0621\u064e\u06da \u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u0639\u06e1\u062a\u064e\u062f\u06e1\u0646\u064e\u0627 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0644\u0650\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0646\u064f\u0632\u064f\u0644\u0657\u0627",translation:"Maka apakah orang kafir menyangka bahwa mereka (dapat) mengambil hamba-hamba-Ku menjadi penolong selain Aku? Sungguh, Kami telah menyediakan (neraka) Jahanam sebagai tempat tinggal bagi orang-orang kafir"},{id:103,text:"\u0642\u064f\u0644\u06e1 \u0647\u064e\u0644\u06e1 \u0646\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0643\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0623\u064e\u062e\u06e1\u0633\u064e\u0631\u0650\u064a\u0646\u064e \u0623\u064e\u0639\u06e1\u0645\u064e\u0670\u0644\u064b\u0627",translation:"Katakanlah (Muhammad), \"Apakah perlu Kami beritahukan kepadamu tentang orang yang paling rugi perbuatannya"},{id:104,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0636\u064e\u0644\u0651\u064e \u0633\u064e\u0639\u06e1\u064a\u064f\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u0650 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0648\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u062d\u06e1\u0633\u064e\u0628\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064f\u062d\u06e1\u0633\u0650\u0646\u064f\u0648\u0646\u064e \u0635\u064f\u0646\u06e1\u0639\u064b\u0627",translation:"(Yaitu) orang yang sia-sia perbuatannya dalam kehidupan dunia, sedangkan mereka mengira telah berbuat sebaik-baiknya"},{id:105,text:"\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0644\u0650\u0642\u064e\u0627\u0653\u0626\u0650\u0647\u0650\u06e6 \u0641\u064e\u062d\u064e\u0628\u0650\u0637\u064e\u062a\u06e1 \u0623\u064e\u0639\u06e1\u0645\u064e\u0670\u0644\u064f\u0647\u064f\u0645\u06e1 \u0641\u064e\u0644\u064e\u0627 \u0646\u064f\u0642\u0650\u064a\u0645\u064f \u0644\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u0648\u064e\u0632\u06e1\u0646\u0657\u0627",translation:"Mereka itulah orang yang mengingkari ayat-ayat Tuhan mereka dan (tidak percaya) terhadap pertemuan dengan-Nya.500) Maka sia-sia amal mereka, dan Kami tidak memberikan penimbangan terhadap (amal) mereka pada hari Kiamat"},{id:106,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062c\u064e\u0632\u064e\u0627\u0653\u0624\u064f\u0647\u064f\u0645\u06e1 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0653\u0627\u0652 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u064a \u0648\u064e\u0631\u064f\u0633\u064f\u0644\u0650\u064a \u0647\u064f\u0632\u064f\u0648\u064b\u0627",translation:"Demikianlah, balasan mereka itu neraka Jahanam, karena kekafiran mereka, dan karena mereka menjadikan ayat-ayat-Ku dan rasul-rasul-Ku sebagai bahan olok-olok"},{id:107,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0643\u064e\u0627\u0646\u064e\u062a\u06e1 \u0644\u064e\u0647\u064f\u0645\u06e1 \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u064f \u0671\u0644\u06e1\u0641\u0650\u0631\u06e1\u062f\u064e\u0648\u06e1\u0633\u0650 \u0646\u064f\u0632\u064f\u0644\u064b\u0627",translation:"Sungguh, orang yang beriman dan mengerjakan kebajikan, untuk mereka disediakan surga Firdaus sebagai tempat tinggal"},{id:108,text:"\u062e\u064e\u0670\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0628\u06e1\u063a\u064f\u0648\u0646\u064e \u0639\u064e\u0646\u06e1\u0647\u064e\u0627 \u062d\u0650\u0648\u064e\u0644\u0657\u0627",translation:"mereka kekal di dalamnya, mereka tidak ingin pindah dari sana"},{id:109,text:"\u0642\u064f\u0644 \u0644\u0651\u064e\u0648\u06e1 \u0643\u064e\u0627\u0646\u064e \u0671\u0644\u06e1\u0628\u064e\u062d\u06e1\u0631\u064f \u0645\u0650\u062f\u064e\u0627\u062f\u0657\u0627 \u0644\u0651\u0650\u0643\u064e\u0644\u0650\u0645\u064e\u0670\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u064a \u0644\u064e\u0646\u064e\u0641\u0650\u062f\u064e \u0671\u0644\u06e1\u0628\u064e\u062d\u06e1\u0631\u064f \u0642\u064e\u0628\u06e1\u0644\u064e \u0623\u064e\u0646 \u062a\u064e\u0646\u0641\u064e\u062f\u064e \u0643\u064e\u0644\u0650\u0645\u064e\u0670\u062a\u064f \u0631\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u0644\u064e\u0648\u06e1 \u062c\u0650\u0626\u06e1\u0646\u064e\u0627 \u0628\u0650\u0645\u0650\u062b\u06e1\u0644\u0650\u0647\u0650\u06e6 \u0645\u064e\u062f\u064e\u062f\u0657\u0627",translation:"Katakanlah (Muhammad), \"Seandainya lautan menjadi tinta untuk (menulis) kalimat-kalimat Tuhanku, maka pasti habislah lautan itu sebelum selesai (penulisan) kalimat-kalimat Tuhanku, meskipun Kami datangkan tambahan sebanyak itu (pula)"},{id:110,text:"\u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u064e\u0627\u06e0 \u0628\u064e\u0634\u064e\u0631\u065e \u0645\u0651\u0650\u062b\u06e1\u0644\u064f\u0643\u064f\u0645\u06e1 \u064a\u064f\u0648\u062d\u064e\u0649\u0670\u0653 \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u064f\u0643\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0670\u0647\u065e \u0648\u064e\u0670\u062d\u0650\u062f\u065e\u06d6 \u0641\u064e\u0645\u064e\u0646 \u0643\u064e\u0627\u0646\u064e \u064a\u064e\u0631\u06e1\u062c\u064f\u0648\u0627\u0652 \u0644\u0650\u0642\u064e\u0627\u0653\u0621\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u06e6 \u0641\u064e\u0644\u06e1\u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u06e1 \u0639\u064e\u0645\u064e\u0644\u0657\u0627 \u0635\u064e\u0670\u0644\u0650\u062d\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0634\u06e1\u0631\u0650\u0643\u06e1 \u0628\u0650\u0639\u0650\u0628\u064e\u0627\u062f\u064e\u0629\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u062d\u064e\u062f\u064e\u06e2\u0627",translation:"Katakanlah (Muhammad), \"Sesungguhnya aku ini hanya seorang manusia seperti kamu, yang telah menerima wahyu, bahwa sesungguhnya Tuhan kamu adalah Tuhan Yang Maha Esa.\" Maka barang siapa mengharap pertemuan dengan Tuhannya maka hendaklah dia mengerjakan kebajikan dan janganlah dia mempersekutukan dengan sesuatu pun dalam beribadah kepada Tuhannya"}]},{id:19,name:"\u0645\u0631\u064a\u0645",transliteration:"Maryam",translation:"Maryam",type:"meccan",total_verses:98,verses:[{id:1,text:"\u0643\u0653\u0647\u064a\u0639\u0653\u0635\u0653",translation:"K\u0101f H\u0101 Y\u0101` 'A\u012bn \u1e62\u0101d"},{id:2,text:"\u0630\u0650\u0643\u06e1\u0631\u064f \u0631\u064e\u062d\u06e1\u0645\u064e\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0639\u064e\u0628\u06e1\u062f\u064e\u0647\u064f\u06e5 \u0632\u064e\u0643\u064e\u0631\u0650\u064a\u0651\u064e\u0627\u0653",translation:"(Yang dibacakan ini adalah) penjelasan tentang rahmat Tuhanmu kepada hamba-Nya, Zakaria"},{id:3,text:"\u0625\u0650\u0630\u06e1 \u0646\u064e\u0627\u062f\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u06e5 \u0646\u0650\u062f\u064e\u0627\u0653\u0621\u064b \u062e\u064e\u0641\u0650\u064a\u0651\u0657\u0627",translation:"(yaitu) ketika dia berdoa kepada Tuhannya dengan suara yang lembut"},{id:4,text:"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0625\u0650\u0646\u0651\u0650\u064a \u0648\u064e\u0647\u064e\u0646\u064e \u0671\u0644\u06e1\u0639\u064e\u0638\u06e1\u0645\u064f \u0645\u0650\u0646\u0651\u0650\u064a \u0648\u064e\u0671\u0634\u06e1\u062a\u064e\u0639\u064e\u0644\u064e \u0671\u0644\u0631\u0651\u064e\u0623\u06e1\u0633\u064f \u0634\u064e\u064a\u06e1\u0628\u0657\u0627 \u0648\u064e\u0644\u064e\u0645\u06e1 \u0623\u064e\u0643\u064f\u0646\u06e2 \u0628\u0650\u062f\u064f\u0639\u064e\u0627\u0653\u0626\u0650\u0643\u064e \u0631\u064e\u0628\u0651\u0650 \u0634\u064e\u0642\u0650\u064a\u0651\u0657\u0627",translation:"Dia (Zakaria) berkata, \"Ya Tuhanku, sungguh tulangku telah melemah dan kepalaku telah dipenuhi uban, sedang aku belum pernah kecewa dalam berdoa kepada-Mu, ya Tuhanku"},{id:5,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u0650\u064a \u062e\u0650\u0641\u06e1\u062a\u064f \u0671\u0644\u06e1\u0645\u064e\u0648\u064e\u0670\u0644\u0650\u064a\u064e \u0645\u0650\u0646 \u0648\u064e\u0631\u064e\u0627\u0653\u0621\u0650\u064a \u0648\u064e\u0643\u064e\u0627\u0646\u064e\u062a\u0650 \u0671\u0645\u06e1\u0631\u064e\u0623\u064e\u062a\u0650\u064a \u0639\u064e\u0627\u0642\u0650\u0631\u0657\u0627 \u0641\u064e\u0647\u064e\u0628\u06e1 \u0644\u0650\u064a \u0645\u0650\u0646 \u0644\u0651\u064e\u062f\u064f\u0646\u0643\u064e \u0648\u064e\u0644\u0650\u064a\u0651\u0657\u0627",translation:"Dan sungguh, aku khawatir terhadap kerabatku sepeninggalku, padahal istriku seorang yang mandul, maka anugerahilah aku seorang anak dari sisi-Mu"},{id:6,text:"\u064a\u064e\u0631\u0650\u062b\u064f\u0646\u0650\u064a \u0648\u064e\u064a\u064e\u0631\u0650\u062b\u064f \u0645\u0650\u0646\u06e1 \u0621\u064e\u0627\u0644\u0650 \u064a\u064e\u0639\u06e1\u0642\u064f\u0648\u0628\u064e\u06d6 \u0648\u064e\u0671\u062c\u06e1\u0639\u064e\u0644\u06e1\u0647\u064f \u0631\u064e\u0628\u0651\u0650 \u0631\u064e\u0636\u0650\u064a\u0651\u0657\u0627",translation:"yang akan mewarisi aku dan mewarisi dari keluarga Yakub; dan jadikanlah dia, ya Tuhanku, seorang yang diridai"},{id:7,text:"\u064a\u064e\u0670\u0632\u064e\u0643\u064e\u0631\u0650\u064a\u0651\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0627 \u0646\u064f\u0628\u064e\u0634\u0651\u0650\u0631\u064f\u0643\u064e \u0628\u0650\u063a\u064f\u0644\u064e\u0670\u0645\u064d \u0671\u0633\u06e1\u0645\u064f\u0647\u064f\u06e5 \u064a\u064e\u062d\u06e1\u064a\u064e\u0649\u0670 \u0644\u064e\u0645\u06e1 \u0646\u064e\u062c\u06e1\u0639\u064e\u0644 \u0644\u0651\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f \u0633\u064e\u0645\u0650\u064a\u0651\u0657\u0627",translation:"(Allah berfirman), \"Wahai Zakaria! Kami memberi kabar gembira kepadamu dengan seorang anak laki-laki namanya Yahya, yang Kami belum pernah memberikan nama seperti itu sebelumnya"},{id:8,text:"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u064a\u064e\u0643\u064f\u0648\u0646\u064f \u0644\u0650\u064a \u063a\u064f\u0644\u064e\u0670\u0645\u065e \u0648\u064e\u0643\u064e\u0627\u0646\u064e\u062a\u0650 \u0671\u0645\u06e1\u0631\u064e\u0623\u064e\u062a\u0650\u064a \u0639\u064e\u0627\u0642\u0650\u0631\u0657\u0627 \u0648\u064e\u0642\u064e\u062f\u06e1 \u0628\u064e\u0644\u064e\u063a\u06e1\u062a\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0643\u0650\u0628\u064e\u0631\u0650 \u0639\u0650\u062a\u0650\u064a\u0651\u0657\u0627",translation:"Dia (Zakaria) berkata, \"Ya Tuhanku, bagaimana aku akan mempunyai anak, padahal istriku seorang yang mandul dan aku (sendiri) sesungguhnya sudah mencapai usia yang sangat tua"},{id:9,text:"\u0642\u064e\u0627\u0644\u064e \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u064a\u0651\u064e \u0647\u064e\u064a\u0651\u0650\u0646\u065e \u0648\u064e\u0642\u064e\u062f\u06e1 \u062e\u064e\u0644\u064e\u0642\u06e1\u062a\u064f\u0643\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f \u0648\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0643\u064f \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627",translation:"(Allah) berfirman, \"Demikianlah.\" Tuhanmu berfirman, \"Hal itu mudah bagi-Ku; sungguh, engkau telah Aku ciptakan sebelum itu, padahal (pada waktu itu) engkau belum berwujud sama sekali"},{id:10,text:"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0671\u062c\u06e1\u0639\u064e\u0644 \u0644\u0651\u0650\u064a\u0653 \u0621\u064e\u0627\u064a\u064e\u0629\u0657\u06d6 \u0642\u064e\u0627\u0644\u064e \u0621\u064e\u0627\u064a\u064e\u062a\u064f\u0643\u064e \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064f\u0643\u064e\u0644\u0651\u0650\u0645\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u062b\u064e\u0644\u064e\u0670\u062b\u064e \u0644\u064e\u064a\u064e\u0627\u0644\u0656 \u0633\u064e\u0648\u0650\u064a\u0651\u0657\u0627",translation:"Dia (Zakaria) berkata, \"Ya Tuhanku, berilah aku suatu tanda.\" (Allah) berfirman, \"Tandamu ialah engkau tidak dapat bercakap-cakap dengan manusia selama tiga malam, padahal engkau sehat"},{id:11,text:"\u0641\u064e\u062e\u064e\u0631\u064e\u062c\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u06e6 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u0650\u062d\u06e1\u0631\u064e\u0627\u0628\u0650 \u0641\u064e\u0623\u064e\u0648\u06e1\u062d\u064e\u0649\u0670\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0623\u064e\u0646 \u0633\u064e\u0628\u0651\u0650\u062d\u064f\u0648\u0627\u0652 \u0628\u064f\u0643\u06e1\u0631\u064e\u0629\u0657 \u0648\u064e\u0639\u064e\u0634\u0650\u064a\u0651\u0657\u0627",translation:"Maka dia keluar dari mihrab menuju kaumnya, lalu dia memberi isyarat kepada mereka; bertasbihlah kamu pada waktu pagi dan petang"},{id:12,text:"\u064a\u064e\u0670\u064a\u064e\u062d\u06e1\u064a\u064e\u0649\u0670 \u062e\u064f\u0630\u0650 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0628\u0650\u0642\u064f\u0648\u0651\u064e\u0629\u0656\u06d6 \u0648\u064e\u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f \u0671\u0644\u06e1\u062d\u064f\u0643\u06e1\u0645\u064e \u0635\u064e\u0628\u0650\u064a\u0651\u0657\u0627",translation:"Wahai Yahya! Ambillah (pelajarilah)501) Kitab (Taurat) itu dengan sungguh-sungguh.\" Dan Kami berikan hikmah kepadanya (Yahya)502) selagi dia masih kanak-kanak"},{id:13,text:"\u0648\u064e\u062d\u064e\u0646\u064e\u0627\u0646\u0657\u0627 \u0645\u0651\u0650\u0646 \u0644\u0651\u064e\u062f\u064f\u0646\u0651\u064e\u0627 \u0648\u064e\u0632\u064e\u0643\u064e\u0648\u0670\u0629\u0657\u06d6 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u062a\u064e\u0642\u0650\u064a\u0651\u0657\u0627",translation:"dan (Kami jadikan) rasa kasih sayang (kepada sesama) dari Kami dan bersih (dari dosa). Dan dia adalah seorang yang bertakwa"},{id:14,text:"\u0648\u064e\u0628\u064e\u0631\u0651\u064e\u06e2\u0627 \u0628\u0650\u0648\u064e\u0670\u0644\u0650\u062f\u064e\u064a\u06e1\u0647\u0650 \u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0643\u064f\u0646 \u062c\u064e\u0628\u0651\u064e\u0627\u0631\u064b\u0627 \u0639\u064e\u0635\u0650\u064a\u0651\u0657\u0627",translation:"dan sangat berbakti kepada kedua orang tuanya, dan dia bukan orang yang sombong (bukan pula) orang yang durhaka"},{id:15,text:"\u0648\u064e\u0633\u064e\u0644\u064e\u0670\u0645\u064c \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u064a\u064e\u0648\u06e1\u0645\u064e \u0648\u064f\u0644\u0650\u062f\u064e \u0648\u064e\u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064e\u0645\u064f\u0648\u062a\u064f \u0648\u064e\u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064f\u0628\u06e1\u0639\u064e\u062b\u064f \u062d\u064e\u064a\u0651\u0657\u0627",translation:"Dan kesejahteraan bagi dirinya pada hari lahirnya, pada hari wafatnya, dan pada hari dia dibangkitkan hidup kembali"},{id:16,text:"\u0648\u064e\u0671\u0630\u06e1\u0643\u064f\u0631\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0645\u064e\u0631\u06e1\u064a\u064e\u0645\u064e \u0625\u0650\u0630\u0650 \u0671\u0646\u062a\u064e\u0628\u064e\u0630\u064e\u062a\u06e1 \u0645\u0650\u0646\u06e1 \u0623\u064e\u0647\u06e1\u0644\u0650\u0647\u064e\u0627 \u0645\u064e\u0643\u064e\u0627\u0646\u0657\u0627 \u0634\u064e\u0631\u06e1\u0642\u0650\u064a\u0651\u0657\u0627",translation:"Dan ceritakanlah (Muhammad) kisah Maryam di dalam Kitab (Alquran), (yaitu) ketika dia mengasingkan diri dari keluarganya ke suatu tempat di sebelah timur (Baitul-maqdis)"},{id:17,text:"\u0641\u064e\u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064e\u062a\u06e1 \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u0645\u06e1 \u062d\u0650\u062c\u064e\u0627\u0628\u0657\u0627 \u0641\u064e\u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u064e\u0627 \u0631\u064f\u0648\u062d\u064e\u0646\u064e\u0627 \u0641\u064e\u062a\u064e\u0645\u064e\u062b\u0651\u064e\u0644\u064e \u0644\u064e\u0647\u064e\u0627 \u0628\u064e\u0634\u064e\u0631\u0657\u0627 \u0633\u064e\u0648\u0650\u064a\u0651\u0657\u0627",translation:"lalu dia memasang tabir (yang melindunginya) dari mereka; lalu Kami mengutus roh Kami (Jibril) kepadanya, maka dia menampakan diri di hadapannya dalam bentuk manusia yang sempurna"},{id:18,text:"\u0642\u064e\u0627\u0644\u064e\u062a\u06e1 \u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u0650 \u0645\u0650\u0646\u0643\u064e \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064e \u062a\u064e\u0642\u0650\u064a\u0651\u0657\u0627",translation:"Dia (Maryam) berkata, \"Sungguh, aku berlindung kepada Tuhan Yang Maha Pengasih terhadapmu, jika engkau orang yang bertakwa"},{id:19,text:"\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u064e\u0627\u06e0 \u0631\u064e\u0633\u064f\u0648\u0644\u064f \u0631\u064e\u0628\u0651\u0650\u0643\u0650 \u0644\u0650\u0623\u064e\u0647\u064e\u0628\u064e \u0644\u064e\u0643\u0650 \u063a\u064f\u0644\u064e\u0670\u0645\u0657\u0627 \u0632\u064e\u0643\u0650\u064a\u0651\u0657\u0627",translation:"Dia (Jibril) berkata, \"Sesungguhnya aku hanyalah utusan Tuhanmu, untuk menyampaikan anugerah kepadamu berupa seorang anak laki-laki yang suci"},{id:20,text:"\u0642\u064e\u0627\u0644\u064e\u062a\u06e1 \u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u064a\u064e\u0643\u064f\u0648\u0646\u064f \u0644\u0650\u064a \u063a\u064f\u0644\u064e\u0670\u0645\u065e \u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0645\u06e1\u0633\u064e\u0633\u06e1\u0646\u0650\u064a \u0628\u064e\u0634\u064e\u0631\u065e \u0648\u064e\u0644\u064e\u0645\u06e1 \u0623\u064e\u0643\u064f \u0628\u064e\u063a\u0650\u064a\u0651\u0657\u0627",translation:"Dia (Maryam) berkata, \"Bagaimana mungkin aku mempunyai anak laki-laki, padahal tidak pernah ada orang (laki-laki) yang menyentuhku dan aku bukan seorang pezina"},{id:21,text:"\u0642\u064e\u0627\u0644\u064e \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u0650 \u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u0650 \u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u064a\u0651\u064e \u0647\u064e\u064a\u0651\u0650\u0646\u065e\u06d6 \u0648\u064e\u0644\u0650\u0646\u064e\u062c\u06e1\u0639\u064e\u0644\u064e\u0647\u064f\u06e5\u0653 \u0621\u064e\u0627\u064a\u064e\u0629\u0657 \u0644\u0651\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u0657 \u0645\u0651\u0650\u0646\u0651\u064e\u0627\u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0623\u064e\u0645\u06e1\u0631\u0657\u0627 \u0645\u0651\u064e\u0642\u06e1\u0636\u0650\u064a\u0651\u0657\u0627",translation:"Dia (Jibril) berkata, \"Demikanlah.\" Tuhanmu berfirman, \"Hal itu mudah bagi-Ku, dan agar Kami menjadikannya suatu tanda (kebesaran Allah) bagi manusia dan sebagai rahmat dari Kami; dan hal itu adalah suatu urusan yang (sudah) diputuskan"},{id:22,text:"\u06de\u0641\u064e\u062d\u064e\u0645\u064e\u0644\u064e\u062a\u06e1\u0647\u064f \u0641\u064e\u0671\u0646\u062a\u064e\u0628\u064e\u0630\u064e\u062a\u06e1 \u0628\u0650\u0647\u0650\u06e6 \u0645\u064e\u0643\u064e\u0627\u0646\u0657\u0627 \u0642\u064e\u0635\u0650\u064a\u0651\u0657\u0627",translation:"Maka dia (Maryam) mengandung, lalu dia mengasingkan diri dengan kandungannya itu ke tempat yang jauh"},{id:23,text:"\u0641\u064e\u0623\u064e\u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064e\u0627 \u0671\u0644\u06e1\u0645\u064e\u062e\u064e\u0627\u0636\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u062c\u0650\u0630\u06e1\u0639\u0650 \u0671\u0644\u0646\u0651\u064e\u062e\u06e1\u0644\u064e\u0629\u0650 \u0642\u064e\u0627\u0644\u064e\u062a\u06e1 \u064a\u064e\u0670\u0644\u064e\u064a\u06e1\u062a\u064e\u0646\u0650\u064a \u0645\u0650\u062a\u0651\u064f \u0642\u064e\u0628\u06e1\u0644\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0648\u064e\u0643\u064f\u0646\u062a\u064f \u0646\u064e\u0633\u06e1\u064a\u0657\u0627 \u0645\u0651\u064e\u0646\u0633\u0650\u064a\u0651\u0657\u0627",translation:"Kemudian rasa sakit akan melahirkan memaksanya (bersandar) pada pangkal pohon kurma, dia (Maryam) berkata, \"Wahai, alangkah (baiknya) aku mati sebelum ini, dan aku menjadi seorang yang tidak diperhatikan dan dilupakan"},{id:24,text:"\u0641\u064e\u0646\u064e\u0627\u062f\u064e\u0649\u0670\u0647\u064e\u0627 \u0645\u0650\u0646 \u062a\u064e\u062d\u06e1\u062a\u0650\u0647\u064e\u0627\u0653 \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064e\u062d\u06e1\u0632\u064e\u0646\u0650\u064a \u0642\u064e\u062f\u06e1 \u062c\u064e\u0639\u064e\u0644\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u0650 \u062a\u064e\u062d\u06e1\u062a\u064e\u0643\u0650 \u0633\u064e\u0631\u0650\u064a\u0651\u0657\u0627",translation:"Maka dia (Jibril) berseru kepadanya dari tempat yang rendah, \"Janganlah engkau bersedih hati, sesungguhnya Tuhanmu telah menjadikan anak sungai di bawahmu"},{id:25,text:"\u0648\u064e\u0647\u064f\u0632\u0651\u0650\u064a\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u0650 \u0628\u0650\u062c\u0650\u0630\u06e1\u0639\u0650 \u0671\u0644\u0646\u0651\u064e\u062e\u06e1\u0644\u064e\u0629\u0650 \u062a\u064f\u0633\u064e\u0670\u0642\u0650\u0637\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u0650 \u0631\u064f\u0637\u064e\u0628\u0657\u0627 \u062c\u064e\u0646\u0650\u064a\u0651\u0657\u0627",translation:"Dan goyanglah pangkal pohon kurma itu ke arahmu, niscaya (pohon) itu akan menggugurkan buah kurma yang masak kepadamu"},{id:26,text:"\u0641\u064e\u0643\u064f\u0644\u0650\u064a \u0648\u064e\u0671\u0634\u06e1\u0631\u064e\u0628\u0650\u064a \u0648\u064e\u0642\u064e\u0631\u0651\u0650\u064a \u0639\u064e\u064a\u06e1\u0646\u0657\u0627\u06d6 \u0641\u064e\u0625\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0631\u064e\u064a\u0650\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0628\u064e\u0634\u064e\u0631\u0650 \u0623\u064e\u062d\u064e\u062f\u0657\u0627 \u0641\u064e\u0642\u064f\u0648\u0644\u0650\u064a\u0653 \u0625\u0650\u0646\u0651\u0650\u064a \u0646\u064e\u0630\u064e\u0631\u06e1\u062a\u064f \u0644\u0650\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u0650 \u0635\u064e\u0648\u06e1\u0645\u0657\u0627 \u0641\u064e\u0644\u064e\u0646\u06e1 \u0623\u064f\u0643\u064e\u0644\u0651\u0650\u0645\u064e \u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e \u0625\u0650\u0646\u0633\u0650\u064a\u0651\u0657\u0627",translation:"Maka makan, minum dan bersenanghatilah engkau. Jika engkau melihat seseorang, maka katakanlah, \"Sesungguhnya aku telah bernazar berpuasa untuk Tuhan Yang Maha Pengasih, maka aku tidak akan berbicara dengan siapa pun pada hari ini"},{id:27,text:"\u0641\u064e\u0623\u064e\u062a\u064e\u062a\u06e1 \u0628\u0650\u0647\u0650\u06e6 \u0642\u064e\u0648\u06e1\u0645\u064e\u0647\u064e\u0627 \u062a\u064e\u062d\u06e1\u0645\u0650\u0644\u064f\u0647\u064f\u06e5\u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u064a\u064e\u0670\u0645\u064e\u0631\u06e1\u064a\u064e\u0645\u064f \u0644\u064e\u0642\u064e\u062f\u06e1 \u062c\u0650\u0626\u06e1\u062a\u0650 \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627 \u0641\u064e\u0631\u0650\u064a\u0651\u0657\u0627",translation:"Kemudian dia (Maryam) membawa dia (bayi itu) kepada kaumnya dengan menggendongnya. Mereka (kaumnya) berkata, \"Wahai Maryam! Sungguh, engkau telah membawa sesuatu yang sangat mungkar"},{id:28,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064f\u062e\u06e1\u062a\u064e \u0647\u064e\u0670\u0631\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0623\u064e\u0628\u064f\u0648\u0643\u0650 \u0671\u0645\u06e1\u0631\u064e\u0623\u064e \u0633\u064e\u0648\u06e1\u0621\u0656 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e\u062a\u06e1 \u0623\u064f\u0645\u0651\u064f\u0643\u0650 \u0628\u064e\u063a\u0650\u064a\u0651\u0657\u0627",translation:"Wahai sauadara perempuan Harun (Maryam)! Ayahmu bukan seorang yang buruk perangai dan ibumu bukan seorang perempuan pezina"},{id:29,text:"\u0641\u064e\u0623\u064e\u0634\u064e\u0627\u0631\u064e\u062a\u06e1 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0643\u064e\u064a\u06e1\u0641\u064e \u0646\u064f\u0643\u064e\u0644\u0651\u0650\u0645\u064f \u0645\u064e\u0646 \u0643\u064e\u0627\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0645\u064e\u0647\u06e1\u062f\u0650 \u0635\u064e\u0628\u0650\u064a\u0651\u0657\u0627",translation:"Maka dia (Maryam) menunjuk kepada (anak)nya. Mereka berkata, \"Bagaimana kami akan berbicara dengan anak kecil yang masih dalam ayunan"},{id:30,text:"\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0639\u064e\u0628\u06e1\u062f\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0621\u064e\u0627\u062a\u064e\u0649\u0670\u0646\u0650\u064a\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e\u0646\u0650\u064a \u0646\u064e\u0628\u0650\u064a\u0651\u0657\u0627",translation:"Dia (Isa) berkata, \"Sesungguhnya aku hamba Allah, Dia memberiku Kitab (Injil) dan Dia menjadikan aku seorang Nabi"},{id:31,text:"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e\u0646\u0650\u064a \u0645\u064f\u0628\u064e\u0627\u0631\u064e\u0643\u064b\u0627 \u0623\u064e\u064a\u06e1\u0646\u064e \u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f \u0648\u064e\u0623\u064e\u0648\u06e1\u0635\u064e\u0670\u0646\u0650\u064a \u0628\u0650\u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u0650 \u0648\u064e\u0671\u0644\u0632\u0651\u064e\u0643\u064e\u0648\u0670\u0629\u0650 \u0645\u064e\u0627 \u062f\u064f\u0645\u06e1\u062a\u064f \u062d\u064e\u064a\u0651\u0657\u0627",translation:"dan Dia menjadikan aku seorang yang diberkahi di mana saja aku berada, dan Dia memerintahkan kepadaku (melaksanakan) salat dan (menunaikan) zakat selama aku hidup"},{id:32,text:"\u0648\u064e\u0628\u064e\u0631\u0651\u064e\u06e2\u0627 \u0628\u0650\u0648\u064e\u0670\u0644\u0650\u062f\u064e\u062a\u0650\u064a \u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u062c\u06e1\u0639\u064e\u0644\u06e1\u0646\u0650\u064a \u062c\u064e\u0628\u0651\u064e\u0627\u0631\u0657\u0627 \u0634\u064e\u0642\u0650\u064a\u0651\u0657\u0627",translation:"dan berbakti kepada ibuku, dan Dia tidak menjadikan aku seorang yang sombong lagi celaka"},{id:33,text:"\u0648\u064e\u0671\u0644\u0633\u0651\u064e\u0644\u064e\u0670\u0645\u064f \u0639\u064e\u0644\u064e\u064a\u0651\u064e \u064a\u064e\u0648\u06e1\u0645\u064e \u0648\u064f\u0644\u0650\u062f\u062a\u0651\u064f \u0648\u064e\u064a\u064e\u0648\u06e1\u0645\u064e \u0623\u064e\u0645\u064f\u0648\u062a\u064f \u0648\u064e\u064a\u064e\u0648\u06e1\u0645\u064e \u0623\u064f\u0628\u06e1\u0639\u064e\u062b\u064f \u062d\u064e\u064a\u0651\u0657\u0627",translation:"Dan kesejahteraan semoga dilimpahkan kepadaku, pada hari kelahiranku, pada hari wafatku, dan pada hari aku dibangkitkan hidup kembali"},{id:34,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0639\u0650\u064a\u0633\u064e\u0649 \u0671\u0628\u06e1\u0646\u064f \u0645\u064e\u0631\u06e1\u064a\u064e\u0645\u064e\u06d6 \u0642\u064e\u0648\u06e1\u0644\u064e \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0641\u0650\u064a\u0647\u0650 \u064a\u064e\u0645\u06e1\u062a\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Itulah Isa putra Maryam, (yang mengatakan) perkataan yang benar, yang mereka ragukan kebenarannya"},{id:35,text:"\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0646 \u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064e \u0645\u0650\u0646 \u0648\u064e\u0644\u064e\u062f\u0656\u06d6 \u0633\u064f\u0628\u06e1\u062d\u064e\u0670\u0646\u064e\u0647\u064f\u06e5\u0653\u06da \u0625\u0650\u0630\u064e\u0627 \u0642\u064e\u0636\u064e\u0649\u0670\u0653 \u0623\u064e\u0645\u06e1\u0631\u0657\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0644\u064e\u0647\u064f\u06e5 \u0643\u064f\u0646 \u0641\u064e\u064a\u064e\u0643\u064f\u0648\u0646\u064f",translation:"Tidak patut bagi Allah mempunyai anak, Mahasuci Dia. Apabila Dia hendak menetapkan sesuatu, maka Dia hanya berkata kepadanya, \"Jadilah!\" Maka jadilah sesuatu itu"},{id:36,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u06e1 \u0641\u064e\u0671\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0647\u064f\u06da \u0647\u064e\u0670\u0630\u064e\u0627 \u0635\u0650\u0631\u064e\u0670\u0637\u065e \u0645\u0651\u064f\u0633\u06e1\u062a\u064e\u0642\u0650\u064a\u0645\u065e",translation:"(Isa berkata), \"Dan sesungguhnya Allah itu Tuhanku dan Tuhanmu, maka sembahlah Dia. Inilah jalan yang lurus"},{id:37,text:"\u0641\u064e\u0671\u062e\u06e1\u062a\u064e\u0644\u064e\u0641\u064e \u0671\u0644\u06e1\u0623\u064e\u062d\u06e1\u0632\u064e\u0627\u0628\u064f \u0645\u0650\u0646\u06e2 \u0628\u064e\u064a\u06e1\u0646\u0650\u0647\u0650\u0645\u06e1\u06d6 \u0641\u064e\u0648\u064e\u064a\u06e1\u0644\u065e \u0644\u0651\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0645\u0651\u064e\u0634\u06e1\u0647\u064e\u062f\u0650 \u064a\u064e\u0648\u06e1\u0645\u064d \u0639\u064e\u0638\u0650\u064a\u0645\u064d",translation:"Maka berselisihlah golongan-golongan (yang ada) di antara mereka (Yahudi dan Nasrani). Maka celakalah orang-orang kafir pada waktu menyaksikan hari yang agung"},{id:38,text:"\u0623\u064e\u0633\u06e1\u0645\u0650\u0639\u06e1 \u0628\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0623\u064e\u0628\u06e1\u0635\u0650\u0631\u06e1 \u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064e\u0623\u06e1\u062a\u064f\u0648\u0646\u064e\u0646\u064e\u0627 \u0644\u064e\u0670\u0643\u0650\u0646\u0650 \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e \u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0670\u0644\u0656 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u0656",translation:"Alangkah tajam pendengaran mereka dan alangkah terang penglihatan mereka pada hari mereka datang kepada Kami. Tetapi orang-orang yang zalim pada hari ini (di dunia) berada dalam kesesatan yang nyata"},{id:39,text:"\u0648\u064e\u0623\u064e\u0646\u0630\u0650\u0631\u06e1\u0647\u064f\u0645\u06e1 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u062d\u064e\u0633\u06e1\u0631\u064e\u0629\u0650 \u0625\u0650\u0630\u06e1 \u0642\u064f\u0636\u0650\u064a\u064e \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0631\u064f \u0648\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u063a\u064e\u0641\u06e1\u0644\u064e\u0629\u0656 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Dan berilah mereka peringatan tentang hari penyesalan, (yaitu) ketika segala perkara telah diputus, sedang mereka dalam kelalaian dan mereka tidak beriman"},{id:40,text:"\u0625\u0650\u0646\u0651\u064e\u0627 \u0646\u064e\u062d\u06e1\u0646\u064f \u0646\u064e\u0631\u0650\u062b\u064f \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0648\u064e\u0645\u064e\u0646\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627 \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u064a\u064f\u0631\u06e1\u062c\u064e\u0639\u064f\u0648\u0646\u064e",translation:"(Sesungguhnya Kamilah yang mewarisi bumi503) dan semua yang ada di atasnya, dan hanya kepada Kami mereka dikembalikan"},{id:41,text:"\u0648\u064e\u0671\u0630\u06e1\u0643\u064f\u0631\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064e\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0643\u064e\u0627\u0646\u064e \u0635\u0650\u062f\u0651\u0650\u064a\u0642\u0657\u0627 \u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064b\u0627",translation:"Dan ceritakanlah (Muhammad) kisah Ibrahim di dalam Kitab (Alquran), sesungguhnya dia seorang yang sangat mencintai kebenaran,504) dan seorang nabi"},{id:42,text:"\u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0623\u064e\u0628\u0650\u064a\u0647\u0650 \u064a\u064e\u0640\u0670\u0653\u0623\u064e\u0628\u064e\u062a\u0650 \u0644\u0650\u0645\u064e \u062a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f \u0645\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u0645\u064e\u0639\u064f \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0628\u06e1\u0635\u0650\u0631\u064f \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u063a\u06e1\u0646\u0650\u064a \u0639\u064e\u0646\u0643\u064e \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627",translation:"(Ingatlah) ketika dia (Ibrahim) berkata kepada ayahnya, \"Wahai ayahku! Mengapa engkau menyembah sesuatu yang tidak mendengar, tidak melihat dan tidak dapat menolongmu sedikit pun"},{id:43,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u0628\u064e\u062a\u0650 \u0625\u0650\u0646\u0651\u0650\u064a \u0642\u064e\u062f\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u0646\u0650\u064a \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0639\u0650\u0644\u06e1\u0645\u0650 \u0645\u064e\u0627 \u0644\u064e\u0645\u06e1 \u064a\u064e\u0623\u06e1\u062a\u0650\u0643\u064e \u0641\u064e\u0671\u062a\u0651\u064e\u0628\u0650\u0639\u06e1\u0646\u0650\u064a\u0653 \u0623\u064e\u0647\u06e1\u062f\u0650\u0643\u064e \u0635\u0650\u0631\u064e\u0670\u0637\u0657\u0627 \u0633\u064e\u0648\u0650\u064a\u0651\u0657\u0627",translation:"Wahai ayahku! Sungguh, telah sampai kepadaku sebagian ilmu yang tidak diberikan kepadamu, maka ikutilah aku, niscaya aku akan menunjukkan kepadamu jalan yang lurus"},{id:44,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u0628\u064e\u062a\u0650 \u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u0628\u064f\u062f\u0650 \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u064e\u06d6 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u064e \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u0650 \u0639\u064e\u0635\u0650\u064a\u0651\u0657\u0627",translation:"Wahai ayahku! Janganlah engkau menyembah setan. Sungguh, setan itu durhaka kepada Tuhan Yang Maha Pengasih"},{id:45,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u0628\u064e\u062a\u0650 \u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0623\u064e\u0646 \u064a\u064e\u0645\u064e\u0633\u0651\u064e\u0643\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u065e \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u0650 \u0641\u064e\u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0644\u0650\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u0650 \u0648\u064e\u0644\u0650\u064a\u0651\u0657\u0627",translation:"Wahai ayahku! Sungguh aku khawatir engkau akan ditimpa azab dari Tuhan Yang Maha Pengasih, sehingga engkau menjadi teman bagi setan"},{id:46,text:"\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0631\u064e\u0627\u063a\u0650\u0628\u064c \u0623\u064e\u0646\u062a\u064e \u0639\u064e\u0646\u06e1 \u0621\u064e\u0627\u0644\u0650\u0647\u064e\u062a\u0650\u064a \u064a\u064e\u0640\u0670\u0653\u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064f\u06d6 \u0644\u064e\u0626\u0650\u0646 \u0644\u0651\u064e\u0645\u06e1 \u062a\u064e\u0646\u062a\u064e\u0647\u0650 \u0644\u064e\u0623\u064e\u0631\u06e1\u062c\u064f\u0645\u064e\u0646\u0651\u064e\u0643\u064e\u06d6 \u0648\u064e\u0671\u0647\u06e1\u062c\u064f\u0631\u06e1\u0646\u0650\u064a \u0645\u064e\u0644\u0650\u064a\u0651\u0657\u0627",translation:"Dia (ayahnya) berkata, \"Bencikah engkau kepada tuhan-tuhanku, wahai Ibrahim? Jika engkau tidak berhenti, pasti engkau akan kurajam, maka tinggalkanlah aku untuk waktu yang lama"},{id:47,text:"\u0642\u064e\u0627\u0644\u064e \u0633\u064e\u0644\u064e\u0670\u0645\u064c \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e\u06d6 \u0633\u064e\u0623\u064e\u0633\u06e1\u062a\u064e\u063a\u06e1\u0641\u0650\u0631\u064f \u0644\u064e\u0643\u064e \u0631\u064e\u0628\u0651\u0650\u064a\u0653\u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0643\u064e\u0627\u0646\u064e \u0628\u0650\u064a \u062d\u064e\u0641\u0650\u064a\u0651\u0657\u0627",translation:"Dia (Ibrahim) berkata, \"Semoga keselamatan dilimpahkan kepadamu, aku akan memohonkan ampunan bagimu kepada Tuhanku. Sesungguhnya Dia sangat baik kepadaku"},{id:48,text:"\u0648\u064e\u0623\u064e\u0639\u06e1\u062a\u064e\u0632\u0650\u0644\u064f\u0643\u064f\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0623\u064e\u062f\u06e1\u0639\u064f\u0648\u0627\u0652 \u0631\u064e\u0628\u0651\u0650\u064a \u0639\u064e\u0633\u064e\u0649\u0670\u0653 \u0623\u064e\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0643\u064f\u0648\u0646\u064e \u0628\u0650\u062f\u064f\u0639\u064e\u0627\u0653\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u064a \u0634\u064e\u0642\u0650\u064a\u0651\u0657\u0627",translation:"Dan aku akan menjauhkan diri darimu dan dari apa yang engkau sembah selain Allah, dan aku akan berdoa kepada Tuhanku, mudah-mudahan aku tidak akan kecewa dengan berdoa kepada Tuhanku"},{id:49,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0671\u0639\u06e1\u062a\u064e\u0632\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0647\u064e\u0628\u06e1\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u06e5\u0653 \u0625\u0650\u0633\u06e1\u062d\u064e\u0670\u0642\u064e \u0648\u064e\u064a\u064e\u0639\u06e1\u0642\u064f\u0648\u0628\u064e\u06d6 \u0648\u064e\u0643\u064f\u0644\u0651\u0657\u0627 \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0646\u064e\u0628\u0650\u064a\u0651\u0657\u0627",translation:"Maka ketika dia (Ibrahim) sudah menjauhkan diri dari mereka dan dari apa yang mereka sembah selain Allah, Kami anugerahkan kepadanya Ishak dan Yakub. Dan masing-masing Kami angkat menjadi nabi"},{id:50,text:"\u0648\u064e\u0648\u064e\u0647\u064e\u0628\u06e1\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u062a\u0650\u0646\u064e\u0627 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0644\u0650\u0633\u064e\u0627\u0646\u064e \u0635\u0650\u062f\u06e1\u0642\u064d \u0639\u064e\u0644\u0650\u064a\u0651\u0657\u0627",translation:"Dan Kami anugerahkan kepada mereka sebagian dari rahmat Kami dan Kami jadikan mereka buah tutur yang baik dan mulia"},{id:51,text:"\u0648\u064e\u0671\u0630\u06e1\u0643\u064f\u0631\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0645\u064f\u0648\u0633\u064e\u0649\u0670\u0653\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0643\u064e\u0627\u0646\u064e \u0645\u064f\u062e\u06e1\u0644\u064e\u0635\u0657\u0627 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u0657\u0627 \u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0657\u0627",translation:"Dan ceritakanlah (Muhammad), kisah Musa di dalam Kitab (Alquran). Dia benar benar orang yang terpilih, seorang rasul dan nabi"},{id:52,text:"\u0648\u064e\u0646\u064e\u0670\u062f\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f \u0645\u0650\u0646 \u062c\u064e\u0627\u0646\u0650\u0628\u0650 \u0671\u0644\u0637\u0651\u064f\u0648\u0631\u0650 \u0671\u0644\u06e1\u0623\u064e\u064a\u06e1\u0645\u064e\u0646\u0650 \u0648\u064e\u0642\u064e\u0631\u0651\u064e\u0628\u06e1\u0646\u064e\u0670\u0647\u064f \u0646\u064e\u062c\u0650\u064a\u0651\u0657\u0627",translation:"Dan Kami telah memanggilnya dari sebelah kanan gunung (Sinai) dan Kami dekatkan dia untuk bercakap-cakap"},{id:53,text:"\u0648\u064e\u0648\u064e\u0647\u064e\u0628\u06e1\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646 \u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u062a\u0650\u0646\u064e\u0627\u0653 \u0623\u064e\u062e\u064e\u0627\u0647\u064f \u0647\u064e\u0670\u0631\u064f\u0648\u0646\u064e \u0646\u064e\u0628\u0650\u064a\u0651\u0657\u0627",translation:"Dan Kami telah menganugerahkan sebagian rahmat Kami kepadanya, yaitu (bahwa) saudaranya, Harun, menjadi seorang nabi"},{id:54,text:"\u0648\u064e\u0671\u0630\u06e1\u0643\u064f\u0631\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0625\u0650\u0633\u06e1\u0645\u064e\u0670\u0639\u0650\u064a\u0644\u064e\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0643\u064e\u0627\u0646\u064e \u0635\u064e\u0627\u062f\u0650\u0642\u064e \u0671\u0644\u06e1\u0648\u064e\u0639\u06e1\u062f\u0650 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u0657\u0627 \u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0657\u0627",translation:"Dan ceritakanlah (Muhammad) kisah Ismail di dalam Kitab (Alquran). Dia benar-benar seorang yang benar janjinya, seorang rasul dan nabi"},{id:55,text:"\u0648\u064e\u0643\u064e\u0627\u0646\u064e \u064a\u064e\u0623\u06e1\u0645\u064f\u0631\u064f \u0623\u064e\u0647\u06e1\u0644\u064e\u0647\u064f\u06e5 \u0628\u0650\u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u0650 \u0648\u064e\u0671\u0644\u0632\u0651\u064e\u0643\u064e\u0648\u0670\u0629\u0650 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0639\u0650\u0646\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u06e6 \u0645\u064e\u0631\u06e1\u0636\u0650\u064a\u0651\u0657\u0627",translation:"(Dan dia menyuruh keluarganya505) untuk (melaksanakan) salat dan (menunaikan) zakat, dan dia seorang yang diridai di sisi Tuhannya"},{id:56,text:"\u0648\u064e\u0671\u0630\u06e1\u0643\u064f\u0631\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0625\u0650\u062f\u06e1\u0631\u0650\u064a\u0633\u064e\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0643\u064e\u0627\u0646\u064e \u0635\u0650\u062f\u0651\u0650\u064a\u0642\u0657\u0627 \u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0657\u0627",translation:"Dan ceritakanlah (Muhammad), kisah Idris di dalam Kitab (Alquran). Sesungguhnya dia seorang yang sangat mencintai kebenaran dan seorang nabi"},{id:57,text:"\u0648\u064e\u0631\u064e\u0641\u064e\u0639\u06e1\u0646\u064e\u0670\u0647\u064f \u0645\u064e\u0643\u064e\u0627\u0646\u064b\u0627 \u0639\u064e\u0644\u0650\u064a\u0651\u064b\u0627",translation:"dan Kami telah mengangkatnya ke martabat yang tinggi"},{id:58,text:"\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u0646\u06e1\u0639\u064e\u0645\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650\u0640\u06e7\u0646\u064e \u0645\u0650\u0646 \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u0629\u0650 \u0621\u064e\u0627\u062f\u064e\u0645\u064e \u0648\u064e\u0645\u0650\u0645\u0651\u064e\u0646\u06e1 \u062d\u064e\u0645\u064e\u0644\u06e1\u0646\u064e\u0627 \u0645\u064e\u0639\u064e \u0646\u064f\u0648\u062d\u0656 \u0648\u064e\u0645\u0650\u0646 \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u0629\u0650 \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064e \u0648\u064e\u0625\u0650\u0633\u06e1\u0631\u064e\u0640\u0670\u0653\u0621\u0650\u064a\u0644\u064e \u0648\u064e\u0645\u0650\u0645\u0651\u064e\u0646\u06e1 \u0647\u064e\u062f\u064e\u064a\u06e1\u0646\u064e\u0627 \u0648\u064e\u0671\u062c\u06e1\u062a\u064e\u0628\u064e\u064a\u06e1\u0646\u064e\u0627\u0653\u06da \u0625\u0650\u0630\u064e\u0627 \u062a\u064f\u062a\u06e1\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u064f \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u0650 \u062e\u064e\u0631\u0651\u064f\u0648\u0627\u0652\u06e4 \u0633\u064f\u062c\u0651\u064e\u062f\u0657\u0627\u06e4 \u0648\u064e\u0628\u064f\u0643\u0650\u064a\u0651\u0657\u0627\u06e9",translation:"Mereka itulah orang yang telah diberi nikmat oleh Allah, yaitu dari (golongan) para nabi dari keturunan Adam, dan dari orang yang Kami bawa (dalam kapal) bersama Nuh, dan dari keturunan Ibrahim dan Israil (Yakub) dan dari orang yang telah Kami beri petunjuk dan telah Kami pilih. Apabila dibacakan ayat-ayat Allah Yang Maha Pengasih kepada mereka, maka mereka tunduk sujud dan menangis"},{id:59,text:"\u06de\u0641\u064e\u062e\u064e\u0644\u064e\u0641\u064e \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u0647\u0650\u0645\u06e1 \u062e\u064e\u0644\u06e1\u0641\u064c \u0623\u064e\u0636\u064e\u0627\u0639\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0627\u0652 \u0671\u0644\u0634\u0651\u064e\u0647\u064e\u0648\u064e\u0670\u062a\u0650\u06d6 \u0641\u064e\u0633\u064e\u0648\u06e1\u0641\u064e \u064a\u064e\u0644\u06e1\u0642\u064e\u0648\u06e1\u0646\u064e \u063a\u064e\u064a\u0651\u064b\u0627",translation:"Kemudian datanglah setelah mereka, pengganti yang mengabaikan salat dan memperturutkan nafsunya, maka mereka kelak akan tersesat"},{id:60,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646 \u062a\u064e\u0627\u0628\u064e \u0648\u064e\u0621\u064e\u0627\u0645\u064e\u0646\u064e \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064e \u0635\u064e\u0670\u0644\u0650\u062d\u0657\u0627 \u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u064a\u064e\u062f\u06e1\u062e\u064f\u0644\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u064e \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0638\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627",translation:"kecuali orang yang bertobat, beriman dan mengerjakan kebajikan, maka mereka itu akan masuk surga dan tidak dizalimi (dirugikan) sedikit pun"},{id:61,text:"\u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0650 \u0639\u064e\u062f\u06e1\u0646\u064d \u0671\u0644\u0651\u064e\u062a\u0650\u064a \u0648\u064e\u0639\u064e\u062f\u064e \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u064f \u0639\u0650\u0628\u064e\u0627\u062f\u064e\u0647\u064f\u06e5 \u0628\u0650\u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u0628\u0650\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0643\u064e\u0627\u0646\u064e \u0648\u064e\u0639\u06e1\u062f\u064f\u0647\u064f\u06e5 \u0645\u064e\u0623\u06e1\u062a\u0650\u064a\u0651\u0657\u0627",translation:"yaitu surga Aden yang telah dijanjikan oleh Tuhan Yang Maha Pengasih kepada hamba-Nya, sekalipun (surga itu) tidak tampak. Sungguh, (janji Allah) itu pasti ditepati"},{id:62,text:"\u0644\u0651\u064e\u0627 \u064a\u064e\u0633\u06e1\u0645\u064e\u0639\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0644\u064e\u063a\u06e1\u0648\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0633\u064e\u0644\u064e\u0670\u0645\u0657\u0627\u06d6 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0631\u0650\u0632\u06e1\u0642\u064f\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u0628\u064f\u0643\u06e1\u0631\u064e\u0629\u0657 \u0648\u064e\u0639\u064e\u0634\u0650\u064a\u0651\u0657\u0627",translation:"Di dalamnya mereka tidak mendengar perkataan yang tidak berguna, kecuali (ucapan) salam. Dan di dalamnya bagi mereka ada rezeki pagi dan petang"},{id:63,text:"\u062a\u0650\u0644\u06e1\u0643\u064e \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u064f \u0671\u0644\u0651\u064e\u062a\u0650\u064a \u0646\u064f\u0648\u0631\u0650\u062b\u064f \u0645\u0650\u0646\u06e1 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0646\u064e\u0627 \u0645\u064e\u0646 \u0643\u064e\u0627\u0646\u064e \u062a\u064e\u0642\u0650\u064a\u0651\u0657\u0627",translation:"Itulah surga yang akan Kami wariskan kepada hamba-hamba Kami yang selalu bertakwa"},{id:64,text:"\u0648\u064e\u0645\u064e\u0627 \u0646\u064e\u062a\u064e\u0646\u064e\u0632\u0651\u064e\u0644\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0623\u064e\u0645\u06e1\u0631\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e\u06d6 \u0644\u064e\u0647\u064f\u06e5 \u0645\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u0646\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u06e1\u0641\u064e\u0646\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e\u06da \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0646\u064e\u0633\u0650\u064a\u0651\u0657\u0627",translation:"Dan tidaklah kami (Jibril) turun, kecuali atas perintah Tuhanmu. Milik-Nya segala yang ada dihadapan kita, yang ada di belakang kita dan segala yang ada di antara keduanya, dan Tuhanmu tidak lupa"},{id:65,text:"\u0631\u0651\u064e\u0628\u0651\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0641\u064e\u0671\u0639\u06e1\u0628\u064f\u062f\u06e1\u0647\u064f \u0648\u064e\u0671\u0635\u06e1\u0637\u064e\u0628\u0650\u0631\u06e1 \u0644\u0650\u0639\u0650\u0628\u064e\u0670\u062f\u064e\u062a\u0650\u0647\u0650\u06e6\u06da \u0647\u064e\u0644\u06e1 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0644\u064e\u0647\u064f\u06e5 \u0633\u064e\u0645\u0650\u064a\u0651\u0657\u0627",translation:"(Dialah) Tuhan (yang menguasai) langit dan bumi dan segala yang ada di antara keduanya, maka sembahlah Dia dan berteguh hatilah dalam beribadah kepada-Nya. Apakah engkau mengetahui ada sesuatu yang sama dengan-Nya"},{id:66,text:"\u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064f \u0623\u064e\u0621\u0650\u0630\u064e\u0627 \u0645\u064e\u0627 \u0645\u0650\u062a\u0651\u064f \u0644\u064e\u0633\u064e\u0648\u06e1\u0641\u064e \u0623\u064f\u062e\u06e1\u0631\u064e\u062c\u064f \u062d\u064e\u064a\u0651\u064b\u0627",translation:"Dan orang (kafir) berkata, \"Betulkah apabila aku telah mati, kelak aku sungguh-sungguh akan dibangkitkan hidup kembali"},{id:67,text:"\u0623\u064e\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0630\u06e1\u0643\u064f\u0631\u064f \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064f \u0623\u064e\u0646\u0651\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u06e1\u0646\u064e\u0670\u0647\u064f \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f \u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0643\u064f \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627",translation:"Dan tidakkah manusia itu memikirkan bahwa sesungguhnya Kami telah menciptakannya dahulu, padahal (sebelumnya) dia belum berwujud sama sekali"},{id:68,text:"\u0641\u064e\u0648\u064e\u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0644\u064e\u0646\u064e\u062d\u06e1\u0634\u064f\u0631\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0671\u0644\u0634\u0651\u064e\u064a\u064e\u0670\u0637\u0650\u064a\u0646\u064e \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0646\u064f\u062d\u06e1\u0636\u0650\u0631\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u062d\u064e\u0648\u06e1\u0644\u064e \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u062c\u0650\u062b\u0650\u064a\u0651\u0657\u0627",translation:"Maka demi Tuhanmu, sungguh, pasti akan Kami kumpulkan mereka bersama setan, kemudian pasti akan Kami datangkan mereka ke sekeliling Jahanam dengan berlutut"},{id:69,text:"\u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0646\u064e\u0646\u0632\u0650\u0639\u064e\u0646\u0651\u064e \u0645\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u0634\u0650\u064a\u0639\u064e\u0629\u064d \u0623\u064e\u064a\u0651\u064f\u0647\u064f\u0645\u06e1 \u0623\u064e\u0634\u064e\u062f\u0651\u064f \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u0650 \u0639\u0650\u062a\u0650\u064a\u0651\u0657\u0627",translation:"Kemudian pasti akan Kami tarik dari setiap golongan siapa di antara mereka yang sangat durhaka kepada Tuhan Yang Maha Pengasih"},{id:70,text:"\u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0646\u064e\u062d\u06e1\u0646\u064f \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0628\u0650\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1\u0644\u064e\u0649\u0670 \u0628\u0650\u0647\u064e\u0627 \u0635\u0650\u0644\u0650\u064a\u0651\u0657\u0627",translation:"Selanjutnya Kami sungguh lebih mengetahui orang yang seharusnya (dimasukkan) ke dalam neraka"},{id:71,text:"\u0648\u064e\u0625\u0650\u0646 \u0645\u0651\u0650\u0646\u0643\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u0648\u064e\u0627\u0631\u0650\u062f\u064f\u0647\u064e\u0627\u06da \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u062d\u064e\u062a\u06e1\u0645\u0657\u0627 \u0645\u0651\u064e\u0642\u06e1\u0636\u0650\u064a\u0651\u0657\u0627",translation:"Dan tidak ada seorang pun di antara kamu yang tidak mendatanginya (neraka). Hal itu bagi Tuhanmu adalah ketentuan yang sudah ditetapkan"},{id:72,text:"\u062b\u064f\u0645\u0651\u064e \u0646\u064f\u0646\u064e\u062c\u0651\u0650\u064a \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u062a\u0651\u064e\u0642\u064e\u0648\u0627\u0652 \u0648\u0651\u064e\u0646\u064e\u0630\u064e\u0631\u064f \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u062c\u0650\u062b\u0650\u064a\u0651\u0657\u0627",translation:"Kemudian Kami akan menyelamatkan orang-orang yang bertakwa dan membiarkan orang-orang yang zalim di dalam (neraka) dalam keadaan berlutut"},{id:73,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062a\u064f\u062a\u06e1\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u064f\u0646\u064e\u0627 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0656 \u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u064a\u0651\u064f \u0671\u0644\u06e1\u0641\u064e\u0631\u0650\u064a\u0642\u064e\u064a\u06e1\u0646\u0650 \u062e\u064e\u064a\u06e1\u0631\u065e \u0645\u0651\u064e\u0642\u064e\u0627\u0645\u0657\u0627 \u0648\u064e\u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064f \u0646\u064e\u062f\u0650\u064a\u0651\u0657\u0627",translation:"Dan apabila dibacakan kepada mereka ayat-ayat Kami yang jelas (maksudnya), orang-orang yang kafir berkata kepada orang-orang yang beriman, \"Manakah di antara kedua golongan yang lebih baik tempat tinggalnya dan lebih indah tempat pertemuan(nya)"},{id:74,text:"\u0648\u064e\u0643\u064e\u0645\u06e1 \u0623\u064e\u0647\u06e1\u0644\u064e\u0643\u06e1\u0646\u064e\u0627 \u0642\u064e\u0628\u06e1\u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0642\u064e\u0631\u06e1\u0646\u064d \u0647\u064f\u0645\u06e1 \u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064f \u0623\u064e\u062b\u064e\u0670\u062b\u0657\u0627 \u0648\u064e\u0631\u0650\u0621\u06e1\u064a\u0657\u0627",translation:"Dan berapa banyak umat (yang ingkar) yang telah Kami binasakan sebelum mereka, padahal mereka lebih bagus perkakas rumah tangganya dan (lebih sedap) dipandang mata"},{id:75,text:"\u0642\u064f\u0644\u06e1 \u0645\u064e\u0646 \u0643\u064e\u0627\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u0636\u0651\u064e\u0644\u064e\u0670\u0644\u064e\u0629\u0650 \u0641\u064e\u0644\u06e1\u064a\u064e\u0645\u06e1\u062f\u064f\u062f\u06e1 \u0644\u064e\u0647\u064f \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u064f \u0645\u064e\u062f\u0651\u064b\u0627\u06da \u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u064e\u0627 \u0631\u064e\u0623\u064e\u0648\u06e1\u0627\u0652 \u0645\u064e\u0627 \u064a\u064f\u0648\u0639\u064e\u062f\u064f\u0648\u0646\u064e \u0625\u0650\u0645\u0651\u064e\u0627 \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0648\u064e\u0625\u0650\u0645\u0651\u064e\u0627 \u0671\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064e \u0641\u064e\u0633\u064e\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0645\u064e\u0646\u06e1 \u0647\u064f\u0648\u064e \u0634\u064e\u0631\u0651\u065e \u0645\u0651\u064e\u0643\u064e\u0627\u0646\u0657\u0627 \u0648\u064e\u0623\u064e\u0636\u06e1\u0639\u064e\u0641\u064f \u062c\u064f\u0646\u062f\u0657\u0627",translation:"Katakanlah (Muhammad), \"Barangsiapa berada dalam kesesatan, maka biarlah Tuhan Yang Maha Pengasih memperpanjang (waktu) baginya;506) sehingga apabila mereka telah melihat apa yang diancamkan kepada mereka, baik azab maupun Kiamat, maka mereka akan mengetahui siapa yang lebih jelek kedudukannya dan lebih lemah bala tentaranya"},{id:76,text:"\u0648\u064e\u064a\u064e\u0632\u0650\u064a\u062f\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u0647\u06e1\u062a\u064e\u062f\u064e\u0648\u06e1\u0627\u0652 \u0647\u064f\u062f\u0657\u0649\u06d7 \u0648\u064e\u0671\u0644\u06e1\u0628\u064e\u0670\u0642\u0650\u064a\u064e\u0670\u062a\u064f \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u064f \u062e\u064e\u064a\u06e1\u0631\u064c \u0639\u0650\u0646\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u062b\u064e\u0648\u064e\u0627\u0628\u0657\u0627 \u0648\u064e\u062e\u064e\u064a\u06e1\u0631\u065e \u0645\u0651\u064e\u0631\u064e\u062f\u0651\u064b\u0627",translation:"Dan Allah akan menambah petunjuk kepada mereka yang telah mendapat petunjuk. Dan amal kebajikan yang kekal itu lebih baik pahalanya di sisi Tuhanmu dan lebih baik kesudahannya"},{id:77,text:"\u0623\u064e\u0641\u064e\u0631\u064e\u0621\u064e\u064a\u06e1\u062a\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0643\u064e\u0641\u064e\u0631\u064e \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0623\u064f\u0648\u062a\u064e\u064a\u064e\u0646\u0651\u064e \u0645\u064e\u0627\u0644\u0657\u0627 \u0648\u064e\u0648\u064e\u0644\u064e\u062f\u064b\u0627",translation:"Lalu apakah engkau telah melihat orang yang mengingkari ayat-ayat Kami dan dia mengatakan, \"Pasti aku akan diberi harta dan anak"},{id:78,text:"\u0623\u064e\u0637\u0651\u064e\u0644\u064e\u0639\u064e \u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u0628\u064e \u0623\u064e\u0645\u0650 \u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064e \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u0650 \u0639\u064e\u0647\u06e1\u062f\u0657\u0627",translation:"Adakah dia melihat yang gaib atau dia telah membuat perjanjian di sisi Tuhan Yang Maha Pengasih"},{id:79,text:"\u0643\u064e\u0644\u0651\u064e\u0627\u06da \u0633\u064e\u0646\u064e\u0643\u06e1\u062a\u064f\u0628\u064f \u0645\u064e\u0627 \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0648\u064e\u0646\u064e\u0645\u064f\u062f\u0651\u064f \u0644\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0645\u064e\u062f\u0651\u0657\u0627",translation:"sama sekali tidak! Kami akan menulis apa yang dia katakan, dan Kami akan memperpanjang azab untuknya secara sempurna"},{id:80,text:"\u0648\u064e\u0646\u064e\u0631\u0650\u062b\u064f\u0647\u064f\u06e5 \u0645\u064e\u0627 \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0648\u064e\u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u0646\u064e\u0627 \u0641\u064e\u0631\u06e1\u062f\u0657\u0627",translation:"(dan Kami akan mewarisi apa yang dia katakan itu,507) dan dia akan datang kepada Kami seorang diri"},{id:81,text:"\u0648\u064e\u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0621\u064e\u0627\u0644\u0650\u0647\u064e\u0629\u0657 \u0644\u0651\u0650\u064a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u0650\u0632\u0651\u0657\u0627",translation:"Dan mereka telah memilih tuhan-tuhan selain Allah, agar tuhan-tuhan itu menjadi pelindung bagi mereka"},{id:82,text:"\u0643\u064e\u0644\u0651\u064e\u0627\u06da \u0633\u064e\u064a\u064e\u0643\u06e1\u0641\u064f\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0639\u0650\u0628\u064e\u0627\u062f\u064e\u062a\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u064a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0636\u0650\u062f\u0651\u064b\u0627",translation:"sama sekali tidak! Kelak mereka (sesembahan) itu akan mengingkari penyembahan mereka terhadapnya, dan akan menjadi musuh bagi mereka"},{id:83,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0631\u064e \u0623\u064e\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0671\u0644\u0634\u0651\u064e\u064a\u064e\u0670\u0637\u0650\u064a\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u062a\u064e\u0624\u064f\u0632\u0651\u064f\u0647\u064f\u0645\u06e1 \u0623\u064e\u0632\u0651\u0657\u0627",translation:"Tidakkah engkau melihat, bahwa sesungguhnya Kami telah mengutus setan-setan itu kepada orang-orang kafir untuk mendorong mereka (berbuat maksiat) dengan sungguh-sungguh"},{id:84,text:"\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u062c\u064e\u0644\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1\u06d6 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0646\u064e\u0639\u064f\u062f\u0651\u064f \u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u062f\u0651\u0657\u0627",translation:"maka janganlah engkau (Muhammad) tergesa-gesa (memintakan azab) terhadap mereka, karena Kami menghitung dengan hitungan teliti (datangnya hari siksaan) untuk mereka"},{id:85,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u0646\u064e\u062d\u06e1\u0634\u064f\u0631\u064f \u0671\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u0650 \u0648\u064e\u0641\u06e1\u062f\u0657\u0627",translation:"(Ingatlah) pada hari (ketika) Kami mengumpulkan orang-orang yang bertakwa kepada (Allah) Yang Maha Pengasih, bagaikan kafilah yang terhormat"},{id:86,text:"\u0648\u064e\u0646\u064e\u0633\u064f\u0648\u0642\u064f \u0671\u0644\u06e1\u0645\u064f\u062c\u06e1\u0631\u0650\u0645\u0650\u064a\u0646\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0648\u0650\u0631\u06e1\u062f\u0657\u0627",translation:"dan Kami akan menggiring orang yang durhaka ke neraka Jahanam dalam keadaan dahaga"},{id:87,text:"\u0644\u0651\u064e\u0627 \u064a\u064e\u0645\u06e1\u0644\u0650\u0643\u064f\u0648\u0646\u064e \u0671\u0644\u0634\u0651\u064e\u0641\u064e\u0670\u0639\u064e\u0629\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u0650 \u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064e \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u0650 \u0639\u064e\u0647\u06e1\u062f\u0657\u0627",translation:"Mereka tidak berhak mendapat syafaat, (pertolongan) kecuali orang yang telah mengadakan perjanjian di sisi (Allah) Yang Maha Pengasih"},{id:88,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064e \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u064f \u0648\u064e\u0644\u064e\u062f\u0657\u0627",translation:"Dan mereka berkata, \"(Allah) Yang Maha Pengasih mempunyai anak"},{id:89,text:"\u0644\u0651\u064e\u0642\u064e\u062f\u06e1 \u062c\u0650\u0626\u06e1\u062a\u064f\u0645\u06e1 \u0634\u064e\u064a\u06e1\u0640\u0654\u064b\u0627 \u0625\u0650\u062f\u0651\u0657\u0627",translation:"Sungguh, kamu telah membawa sesuatu yang sangat mungkar"},{id:90,text:"\u062a\u064e\u0643\u064e\u0627\u062f\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u064f \u064a\u064e\u062a\u064e\u0641\u064e\u0637\u0651\u064e\u0631\u06e1\u0646\u064e \u0645\u0650\u0646\u06e1\u0647\u064f \u0648\u064e\u062a\u064e\u0646\u0634\u064e\u0642\u0651\u064f \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064f \u0648\u064e\u062a\u064e\u062e\u0650\u0631\u0651\u064f \u0671\u0644\u06e1\u062c\u0650\u0628\u064e\u0627\u0644\u064f \u0647\u064e\u062f\u0651\u064b\u0627",translation:"hampir saja langit pecah, dan bumi terbelah, dan gunung-gunung runtuh, (karena ucapan itu),\u2019"},{id:91,text:"\u0623\u064e\u0646 \u062f\u064e\u0639\u064e\u0648\u06e1\u0627\u0652 \u0644\u0650\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u0650 \u0648\u064e\u0644\u064e\u062f\u0657\u0627",translation:"karena mereka menganggap (Allah) Yang Maha Pengasih mempunyai anak"},{id:92,text:"\u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0646\u06e2\u0628\u064e\u063a\u0650\u064a \u0644\u0650\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u0650 \u0623\u064e\u0646 \u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064e \u0648\u064e\u0644\u064e\u062f\u064b\u0627",translation:"Dan tidak mungkin bagi (Allah) Yang Maha Pengasih mempunyai anak"},{id:93,text:"\u0625\u0650\u0646 \u0643\u064f\u0644\u0651\u064f \u0645\u064e\u0646 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u0650\u064a \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u0650 \u0639\u064e\u0628\u06e1\u062f\u0657\u0627",translation:"Tidak ada seorang pun di langit dan di bumi, melainkan akan datang kepada (Allah) Yang Maha Pengasih sebagai seorang hamba"},{id:94,text:"\u0644\u0651\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u062d\u06e1\u0635\u064e\u0649\u0670\u0647\u064f\u0645\u06e1 \u0648\u064e\u0639\u064e\u062f\u0651\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u062f\u0651\u0657\u0627",translation:"Dia (Allah) benar-benar telah menentukan jumlah mereka dan menghitung mereka dengan hitungan yang teliti"},{id:95,text:"\u0648\u064e\u0643\u064f\u0644\u0651\u064f\u0647\u064f\u0645\u06e1 \u0621\u064e\u0627\u062a\u0650\u064a\u0647\u0650 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u0641\u064e\u0631\u06e1\u062f\u064b\u0627",translation:"Dan setiap orang dari mereka akan datang kepada Allah sendiri-sendiri pada hari Kiamat"},{id:96,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0633\u064e\u064a\u064e\u062c\u06e1\u0639\u064e\u0644\u064f \u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u064f \u0648\u064f\u062f\u0651\u0657\u0627",translation:"Sungguh, orang-orang yang beriman dan mengerjakan kebajikan, kelak (Allah) Yang Maha Pengasih akan menanamkan rasa kasih sayang (dalam hati mereka)"},{id:97,text:"\u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0633\u0651\u064e\u0631\u06e1\u0646\u064e\u0670\u0647\u064f \u0628\u0650\u0644\u0650\u0633\u064e\u0627\u0646\u0650\u0643\u064e \u0644\u0650\u062a\u064f\u0628\u064e\u0634\u0651\u0650\u0631\u064e \u0628\u0650\u0647\u0650 \u0671\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e \u0648\u064e\u062a\u064f\u0646\u0630\u0650\u0631\u064e \u0628\u0650\u0647\u0650\u06e6 \u0642\u064e\u0648\u06e1\u0645\u0657\u0627 \u0644\u0651\u064f\u062f\u0651\u0657\u0627",translation:"Maka sungguh, telah Kami mudahkan (Alquran) itu dengan bahasamu (Muhammad), agar dengan itu engkau dapat memberi kabar gembira kepada orang-orang yang bertakwa, dan agar engkau dapat memberi peringatan kepada kaum yang membangkang"},{id:98,text:"\u0648\u064e\u0643\u064e\u0645\u06e1 \u0623\u064e\u0647\u06e1\u0644\u064e\u0643\u06e1\u0646\u064e\u0627 \u0642\u064e\u0628\u06e1\u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0642\u064e\u0631\u06e1\u0646\u064d \u0647\u064e\u0644\u06e1 \u062a\u064f\u062d\u0650\u0633\u0651\u064f \u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u062d\u064e\u062f\u064d \u0623\u064e\u0648\u06e1 \u062a\u064e\u0633\u06e1\u0645\u064e\u0639\u064f \u0644\u064e\u0647\u064f\u0645\u06e1 \u0631\u0650\u0643\u06e1\u0632\u064e\u06e2\u0627",translation:"Dan berapa banyak umat yang telah Kami binasakan sebelum mereka. Adakah engkau (Muhammad) melihat salah seorang dari mereka atau engkau mendengar bisikan mereka"}]},{id:20,name:"\u0637\u0647",transliteration:"Taha",translation:"Tha-Ha",type:"meccan",total_verses:135,verses:[{id:1,text:"\u0637\u0647",translation:"\u1e6c\u0101h\u0101"},{id:2,text:"\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u064e \u0644\u0650\u062a\u064e\u0634\u06e1\u0642\u064e\u0649\u0670\u0653",translation:"Kami tidak menurunkan Alquran ini kepadamu (Muhammad) agar engkau menjadi susah"},{id:3,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u062a\u064e\u0630\u06e1\u0643\u0650\u0631\u064e\u0629\u0657 \u0644\u0651\u0650\u0645\u064e\u0646 \u064a\u064e\u062e\u06e1\u0634\u064e\u0649\u0670",translation:"melainkan sebagai peringatan bagi orang yang takut (kepada Allah)"},{id:4,text:"\u062a\u064e\u0646\u0632\u0650\u064a\u0644\u0657\u0627 \u0645\u0651\u0650\u0645\u0651\u064e\u0646\u06e1 \u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0648\u064e\u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0671\u0644\u06e1\u0639\u064f\u0644\u064e\u0649",translation:"diturunkan dari (Allah) yang menciptakan bumi dan langit yang tinggi"},{id:5,text:"\u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u064f \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0639\u064e\u0631\u06e1\u0634\u0650 \u0671\u0633\u06e1\u062a\u064e\u0648\u064e\u0649\u0670",translation:"(yaitu) Yang Maha Pengasih, yang bersemayam di atas Arasy"},{id:6,text:"\u0644\u064e\u0647\u064f\u06e5 \u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u062d\u06e1\u062a\u064e \u0671\u0644\u062b\u0651\u064e\u0631\u064e\u0649\u0670",translation:"Milik-Nyalah apa yang ada di langit, apa yang ada di bumi, apa yang ada di antara keduanya, dan apa yang ada di bawah tanah"},{id:7,text:"\u0648\u064e\u0625\u0650\u0646 \u062a\u064e\u062c\u06e1\u0647\u064e\u0631\u06e1 \u0628\u0650\u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0644\u0650 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0671\u0644\u0633\u0651\u0650\u0631\u0651\u064e \u0648\u064e\u0623\u064e\u062e\u06e1\u0641\u064e\u0649",translation:"Dan jika engkau mengeraskan ucapanmu, sungguh, Dia mengetahui rahasia dan yang lebih tersembunyi"},{id:8,text:"\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e\u06d6 \u0644\u064e\u0647\u064f \u0671\u0644\u06e1\u0623\u064e\u0633\u06e1\u0645\u064e\u0627\u0653\u0621\u064f \u0671\u0644\u06e1\u062d\u064f\u0633\u06e1\u0646\u064e\u0649\u0670",translation:"(Dialah) Allah, tidak ada tuhan selain Dia, yang mempunyai nama-nama yang terbaik"},{id:9,text:"\u0648\u064e\u0647\u064e\u0644\u06e1 \u0623\u064e\u062a\u064e\u0649\u0670\u0643\u064e \u062d\u064e\u062f\u0650\u064a\u062b\u064f \u0645\u064f\u0648\u0633\u064e\u0649\u0670\u0653",translation:"Dan apakah telah sampai kepadamu kisah Musa"},{id:10,text:"\u0625\u0650\u0630\u06e1 \u0631\u064e\u0621\u064e\u0627 \u0646\u064e\u0627\u0631\u0657\u0627 \u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0623\u064e\u0647\u06e1\u0644\u0650\u0647\u0650 \u0671\u0645\u06e1\u0643\u064f\u062b\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0621\u064e\u0627\u0646\u064e\u0633\u06e1\u062a\u064f \u0646\u064e\u0627\u0631\u0657\u0627 \u0644\u0651\u064e\u0639\u064e\u0644\u0651\u0650\u064a\u0653 \u0621\u064e\u0627\u062a\u0650\u064a\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1\u0647\u064e\u0627 \u0628\u0650\u0642\u064e\u0628\u064e\u0633\u064d \u0623\u064e\u0648\u06e1 \u0623\u064e\u062c\u0650\u062f\u064f \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0647\u064f\u062f\u0657\u0649",translation:"Ketika dia (Musa) melihat api, lalu dia berkata kepada keluarganya, \"Tinggallah kamu (disini), sesungguhnya aku melihat api, mudah-mudahan aku dapat membawa sedikit nyala api kepadamu atau aku akan mendapat petunjuk di tempat api itu"},{id:11,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u062a\u064e\u0649\u0670\u0647\u064e\u0627 \u0646\u064f\u0648\u062f\u0650\u064a\u064e \u064a\u064e\u0670\u0645\u064f\u0648\u0633\u064e\u0649\u0670\u0653",translation:"Maka ketika dia mendatanginya (ke tempat api itu) dia dipanggil, \"Wahai Musa"},{id:12,text:"\u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064e\u0646\u064e\u0627\u06e0 \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0641\u064e\u0671\u062e\u06e1\u0644\u064e\u0639\u06e1 \u0646\u064e\u0639\u06e1\u0644\u064e\u064a\u06e1\u0643\u064e \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0628\u0650\u0671\u0644\u06e1\u0648\u064e\u0627\u062f\u0650 \u0671\u0644\u06e1\u0645\u064f\u0642\u064e\u062f\u0651\u064e\u0633\u0650 \u0637\u064f\u0648\u0657\u0649",translation:"Sungguh, Aku adalah Tuhanmu, maka lepaskan kedua terompahmu. Karena sesungguhnya engkau berada di lembah yang suci, \u1e6cuw\u0101"},{id:13,text:"\u0648\u064e\u0623\u064e\u0646\u064e\u0627 \u0671\u062e\u06e1\u062a\u064e\u0631\u06e1\u062a\u064f\u0643\u064e \u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u0645\u0650\u0639\u06e1 \u0644\u0650\u0645\u064e\u0627 \u064a\u064f\u0648\u062d\u064e\u0649\u0670\u0653",translation:"Dan Aku telah memilih engkau, maka dengarkanlah apa yang akan diwahyukan (kepadamu)"},{id:14,text:"\u0625\u0650\u0646\u0651\u064e\u0646\u0650\u064a\u0653 \u0623\u064e\u0646\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646\u064e\u0627\u06e0 \u0641\u064e\u0671\u0639\u06e1\u0628\u064f\u062f\u06e1\u0646\u0650\u064a \u0648\u064e\u0623\u064e\u0642\u0650\u0645\u0650 \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e \u0644\u0650\u0630\u0650\u0643\u06e1\u0631\u0650\u064a\u0653",translation:"Sungguh, Aku ini Allah, tidak ada tuhan selain Aku, maka sembahlah Aku dan laksanakanlah salat untuk mengingat Aku"},{id:15,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064e \u0621\u064e\u0627\u062a\u0650\u064a\u064e\u0629\u064c \u0623\u064e\u0643\u064e\u0627\u062f\u064f \u0623\u064f\u062e\u06e1\u0641\u0650\u064a\u0647\u064e\u0627 \u0644\u0650\u062a\u064f\u062c\u06e1\u0632\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u064f \u0646\u064e\u0641\u06e1\u0633\u0650\u06ed \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0633\u06e1\u0639\u064e\u0649\u0670",translation:"Sungguh, hari Kiamat itu akan datang, Aku merahasiakan (waktunya) agar setiap orang dibalas sesuai dengan apa yang telah dia usahakan"},{id:16,text:"\u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0635\u064f\u062f\u0651\u064e\u0646\u0651\u064e\u0643\u064e \u0639\u064e\u0646\u06e1\u0647\u064e\u0627 \u0645\u064e\u0646 \u0644\u0651\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f \u0628\u0650\u0647\u064e\u0627 \u0648\u064e\u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064e \u0647\u064e\u0648\u064e\u0649\u0670\u0647\u064f \u0641\u064e\u062a\u064e\u0631\u06e1\u062f\u064e\u0649\u0670",translation:"Maka janganlah engkau dipalingkan dari (Kiamat) oleh orang yang tidak beriman kepadanya dan oleh orang yang mengikuti keinginannya, yang menyebabkan engkau binasa"},{id:17,text:"\u0648\u064e\u0645\u064e\u0627 \u062a\u0650\u0644\u06e1\u0643\u064e \u0628\u0650\u064a\u064e\u0645\u0650\u064a\u0646\u0650\u0643\u064e \u064a\u064e\u0670\u0645\u064f\u0648\u0633\u064e\u0649\u0670",translation:"Dan apakah yang ada di tangan kananmu, wahai Musa"},{id:18,text:"\u0642\u064e\u0627\u0644\u064e \u0647\u0650\u064a\u064e \u0639\u064e\u0635\u064e\u0627\u064a\u064e \u0623\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0624\u064f\u0627\u0652 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627 \u0648\u064e\u0623\u064e\u0647\u064f\u0634\u0651\u064f \u0628\u0650\u0647\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u063a\u064e\u0646\u064e\u0645\u0650\u064a \u0648\u064e\u0644\u0650\u064a\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u064e\u0640\u0654\u064e\u0627\u0631\u0650\u0628\u064f \u0623\u064f\u062e\u06e1\u0631\u064e\u0649\u0670",translation:"Dia (Musa) berkata, \"Ini adalah tongkatku, aku bertumpu padanya, dan aku merontokkan (daun-daun) dengannya untuk (makanan) kambingku, dan bagiku masih ada lagi manfaat yang lain"},{id:19,text:"\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0644\u06e1\u0642\u0650\u0647\u064e\u0627 \u064a\u064e\u0670\u0645\u064f\u0648\u0633\u064e\u0649\u0670",translation:"Dia (Allah) berfirman, \"Lemparkanlah ia, wahai Musa"},{id:20,text:"\u0641\u064e\u0623\u064e\u0644\u06e1\u0642\u064e\u0649\u0670\u0647\u064e\u0627 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0647\u0650\u064a\u064e \u062d\u064e\u064a\u0651\u064e\u0629\u065e \u062a\u064e\u0633\u06e1\u0639\u064e\u0649\u0670",translation:"Lalu (Musa) melemparkan tongkat itu, maka tiba-tiba ia menjadi seekor ular yang merayap dengan cepat"},{id:21,text:"\u0642\u064e\u0627\u0644\u064e \u062e\u064f\u0630\u06e1\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062e\u064e\u0641\u06e1\u06d6 \u0633\u064e\u0646\u064f\u0639\u0650\u064a\u062f\u064f\u0647\u064e\u0627 \u0633\u0650\u064a\u0631\u064e\u062a\u064e\u0647\u064e\u0627 \u0671\u0644\u06e1\u0623\u064f\u0648\u0644\u064e\u0649\u0670",translation:"Dia (Allah) berfirman, \"Peganglah ia dan jangan takut, Kami akan mengembalikannya kepada keadaannya semula"},{id:22,text:"\u0648\u064e\u0671\u0636\u06e1\u0645\u064f\u0645\u06e1 \u064a\u064e\u062f\u064e\u0643\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u062c\u064e\u0646\u064e\u0627\u062d\u0650\u0643\u064e \u062a\u064e\u062e\u06e1\u0631\u064f\u062c\u06e1 \u0628\u064e\u064a\u06e1\u0636\u064e\u0627\u0653\u0621\u064e \u0645\u0650\u0646\u06e1 \u063a\u064e\u064a\u06e1\u0631\u0650 \u0633\u064f\u0648\u0653\u0621\u064d \u0621\u064e\u0627\u064a\u064e\u0629\u064b \u0623\u064f\u062e\u06e1\u0631\u064e\u0649\u0670",translation:"dan kepitlah tanganmu ke ketiakmu, niscaya ia ke luar menjadi putih (bercahaya) tanpa cacat, sebagai mukjizat yang lain"},{id:23,text:"\u0644\u0650\u0646\u064f\u0631\u0650\u064a\u064e\u0643\u064e \u0645\u0650\u0646\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0671\u0644\u06e1\u0643\u064f\u0628\u06e1\u0631\u064e\u0649",translation:"untuk Kami perlihatkan kepadamu (sebagian) dari tanda-tanda kebesaran Kami yang sangat besar"},{id:24,text:"\u0671\u0630\u06e1\u0647\u064e\u0628\u06e1 \u0625\u0650\u0644\u064e\u0649\u0670 \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0637\u064e\u063a\u064e\u0649\u0670",translation:"Pergilah kepada Fir'aun; dia benar-benar telah melampaui batas"},{id:25,text:"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0671\u0634\u06e1\u0631\u064e\u062d\u06e1 \u0644\u0650\u064a \u0635\u064e\u062f\u06e1\u0631\u0650\u064a",translation:"Dia (Musa) berkata, \"Ya Tuhanku, lapangkanlah dadaku"},{id:26,text:"\u0648\u064e\u064a\u064e\u0633\u0651\u0650\u0631\u06e1 \u0644\u0650\u064a\u0653 \u0623\u064e\u0645\u06e1\u0631\u0650\u064a",translation:"dan mudahkanlah untukku urusanku"},{id:27,text:"\u0648\u064e\u0671\u062d\u06e1\u0644\u064f\u0644\u06e1 \u0639\u064f\u0642\u06e1\u062f\u064e\u0629\u0657 \u0645\u0651\u0650\u0646 \u0644\u0651\u0650\u0633\u064e\u0627\u0646\u0650\u064a",translation:"dan lepaskanlah kekakuan dari lidahku"},{id:28,text:"\u064a\u064e\u0641\u06e1\u0642\u064e\u0647\u064f\u0648\u0627\u0652 \u0642\u064e\u0648\u06e1\u0644\u0650\u064a",translation:"agar mereka mengerti perkataanku"},{id:29,text:"\u0648\u064e\u0671\u062c\u06e1\u0639\u064e\u0644 \u0644\u0651\u0650\u064a \u0648\u064e\u0632\u0650\u064a\u0631\u0657\u0627 \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u0647\u06e1\u0644\u0650\u064a",translation:"dan jadikanlah untukku seorang pembantu dari keluargaku"},{id:30,text:"\u0647\u064e\u0670\u0631\u064f\u0648\u0646\u064e \u0623\u064e\u062e\u0650\u064a",translation:"(yaitu) Harun, saudaraku"},{id:31,text:"\u0671\u0634\u06e1\u062f\u064f\u062f\u06e1 \u0628\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0632\u06e1\u0631\u0650\u064a",translation:"teguhkanlah kekuatanku dengan (keberadaan) dia"},{id:32,text:"\u0648\u064e\u0623\u064e\u0634\u06e1\u0631\u0650\u0643\u06e1\u0647\u064f \u0641\u0650\u064a\u0653 \u0623\u064e\u0645\u06e1\u0631\u0650\u064a",translation:"dan jadikanlah dia teman dalam urusanku"},{id:33,text:"\u0643\u064e\u064a\u06e1 \u0646\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u064e\u0643\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u0657\u0627",translation:"agar kami banyak bertasbih kepada-Mu"},{id:34,text:"\u0648\u064e\u0646\u064e\u0630\u06e1\u0643\u064f\u0631\u064e\u0643\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627",translation:"dan banyak mengingat-Mu"},{id:35,text:"\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0643\u064f\u0646\u062a\u064e \u0628\u0650\u0646\u064e\u0627 \u0628\u064e\u0635\u0650\u064a\u0631\u0657\u0627",translation:"sesungguhnya Engkau Maha Melihat (keadaan) kami"},{id:36,text:"\u0642\u064e\u0627\u0644\u064e \u0642\u064e\u062f\u06e1 \u0623\u064f\u0648\u062a\u0650\u064a\u062a\u064e \u0633\u064f\u0624\u06e1\u0644\u064e\u0643\u064e \u064a\u064e\u0670\u0645\u064f\u0648\u0633\u064e\u0649\u0670",translation:"Dia (Allah) berfirman, \"Sungguh, telah diperkenankan permintaanmu, wahai Musa"},{id:37,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0645\u064e\u0646\u064e\u0646\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0645\u064e\u0631\u0651\u064e\u0629\u064b \u0623\u064f\u062e\u06e1\u0631\u064e\u0649\u0670\u0653",translation:"Dan sungguh, Kami telah memberi nikmat kepadamu pada kesempatan yang lain (sebelum ini)"},{id:38,text:"\u0625\u0650\u0630\u06e1 \u0623\u064e\u0648\u06e1\u062d\u064e\u064a\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064f\u0645\u0651\u0650\u0643\u064e \u0645\u064e\u0627 \u064a\u064f\u0648\u062d\u064e\u0649\u0670\u0653",translation:"(yaitu) ketika Kami mengilhamkan kepada ibumu sesuatu yang diilhamkan"},{id:39,text:"\u0623\u064e\u0646\u0650 \u0671\u0642\u06e1\u0630\u0650\u0641\u0650\u064a\u0647\u0650 \u0641\u0650\u064a \u0671\u0644\u062a\u0651\u064e\u0627\u0628\u064f\u0648\u062a\u0650 \u0641\u064e\u0671\u0642\u06e1\u0630\u0650\u0641\u0650\u064a\u0647\u0650 \u0641\u0650\u064a \u0671\u0644\u06e1\u064a\u064e\u0645\u0651\u0650 \u0641\u064e\u0644\u06e1\u064a\u064f\u0644\u06e1\u0642\u0650\u0647\u0650 \u0671\u0644\u06e1\u064a\u064e\u0645\u0651\u064f \u0628\u0650\u0671\u0644\u0633\u0651\u064e\u0627\u062d\u0650\u0644\u0650 \u064a\u064e\u0623\u06e1\u062e\u064f\u0630\u06e1\u0647\u064f \u0639\u064e\u062f\u064f\u0648\u0651\u065e \u0644\u0651\u0650\u064a \u0648\u064e\u0639\u064e\u062f\u064f\u0648\u0651\u065e \u0644\u0651\u064e\u0647\u064f\u06e5\u06da \u0648\u064e\u0623\u064e\u0644\u06e1\u0642\u064e\u064a\u06e1\u062a\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0645\u064e\u062d\u064e\u0628\u0651\u064e\u0629\u0657 \u0645\u0651\u0650\u0646\u0651\u0650\u064a \u0648\u064e\u0644\u0650\u062a\u064f\u0635\u06e1\u0646\u064e\u0639\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0639\u064e\u064a\u06e1\u0646\u0650\u064a\u0653",translation:"(yaitu), letakkanlah dia (Musa) di dalam peti, kemudian hanyutkanlah dia ke sungai (Nil), maka biarlah (arus) sungai itu membawanya ke tepi, dia akan diambil oleh (Fir'aun) musuh-Ku dan musuhnya. Aku telah melimpahkan kepadamu kasih sayang yang datang dari-Ku;512) dan agar engkau diasuh di bawah pengawasan-Ku"},{id:40,text:"\u0625\u0650\u0630\u06e1 \u062a\u064e\u0645\u06e1\u0634\u0650\u064a\u0653 \u0623\u064f\u062e\u06e1\u062a\u064f\u0643\u064e \u0641\u064e\u062a\u064e\u0642\u064f\u0648\u0644\u064f \u0647\u064e\u0644\u06e1 \u0623\u064e\u062f\u064f\u0644\u0651\u064f\u0643\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0646 \u064a\u064e\u0643\u06e1\u0641\u064f\u0644\u064f\u0647\u064f\u06e5\u06d6 \u0641\u064e\u0631\u064e\u062c\u064e\u0639\u06e1\u0646\u064e\u0670\u0643\u064e \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064f\u0645\u0651\u0650\u0643\u064e \u0643\u064e\u064a\u06e1 \u062a\u064e\u0642\u064e\u0631\u0651\u064e \u0639\u064e\u064a\u06e1\u0646\u064f\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062d\u06e1\u0632\u064e\u0646\u064e\u06da \u0648\u064e\u0642\u064e\u062a\u064e\u0644\u06e1\u062a\u064e \u0646\u064e\u0641\u06e1\u0633\u0657\u0627 \u0641\u064e\u0646\u064e\u062c\u0651\u064e\u064a\u06e1\u0646\u064e\u0670\u0643\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u063a\u064e\u0645\u0651\u0650 \u0648\u064e\u0641\u064e\u062a\u064e\u0646\u0651\u064e\u0640\u0670\u0643\u064e \u0641\u064f\u062a\u064f\u0648\u0646\u0657\u0627\u06da \u0641\u064e\u0644\u064e\u0628\u0650\u062b\u06e1\u062a\u064e \u0633\u0650\u0646\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0653 \u0623\u064e\u0647\u06e1\u0644\u0650 \u0645\u064e\u062f\u06e1\u064a\u064e\u0646\u064e \u062b\u064f\u0645\u0651\u064e \u062c\u0650\u0626\u06e1\u062a\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064e\u062f\u064e\u0631\u0656 \u064a\u064e\u0670\u0645\u064f\u0648\u0633\u064e\u0649\u0670",translation:"(Yaitu) ketika saudara perempuanmu berjalan, lalu dia berkata (kepada keluarga Fir'aun), \u2018Bolehkah saya menunjukkan kepadamu orang yang akan memeliharanya?\u2019 Maka Kami mengembalikanmu kepada ibumu, agar senang hatinya dan tidak bersedih hati. Dan engkau pernah membunuh seseorang,513) lalu Kami selamatkan engkau dari kesulitan (yang besar) dan Kami telah mencobamu dengan beberapa cobaan (yang berat); lalu engkau tinggal beberapa tahun di antara penduduk Madyan,514) kemudian engkau, wahai Musa, datang menurut waktu yang ditetapkan"},{id:41,text:"\u0648\u064e\u0671\u0635\u06e1\u0637\u064e\u0646\u064e\u0639\u06e1\u062a\u064f\u0643\u064e \u0644\u0650\u0646\u064e\u0641\u06e1\u0633\u0650\u064a",translation:"dan Aku telah memilihmu (menjadi rasul) untuk diri-Ku"},{id:42,text:"\u0671\u0630\u06e1\u0647\u064e\u0628\u06e1 \u0623\u064e\u0646\u062a\u064e \u0648\u064e\u0623\u064e\u062e\u064f\u0648\u0643\u064e \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u064a \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0646\u0650\u064a\u064e\u0627 \u0641\u0650\u064a \u0630\u0650\u0643\u06e1\u0631\u0650\u064a",translation:"Pergilah engkau beserta saudaramu dengan membawa tanda-tanda (kebesaran)-Ku, dan janganlah kamu berdua lalai mengingat-Ku"},{id:43,text:"\u0671\u0630\u06e1\u0647\u064e\u0628\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0637\u064e\u063a\u064e\u0649\u0670",translation:"pergilah kamu berdua kepada Fir'aun, karena dia benar-benar telah melampaui batas"},{id:44,text:"\u0641\u064e\u0642\u064f\u0648\u0644\u064e\u0627 \u0644\u064e\u0647\u064f\u06e5 \u0642\u064e\u0648\u06e1\u0644\u0657\u0627 \u0644\u0651\u064e\u064a\u0651\u0650\u0646\u0657\u0627 \u0644\u0651\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u06e5 \u064a\u064e\u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f \u0623\u064e\u0648\u06e1 \u064a\u064e\u062e\u06e1\u0634\u064e\u0649\u0670",translation:"maka berbicaralah kamu berdua kepadanya (Fir'aun) dengan kata-kata yang lemah lembut, mudah-mudahan dia sadar atau takut"},{id:45,text:"\u0642\u064e\u0627\u0644\u064e\u0627 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0646\u064e\u0627 \u0646\u064e\u062e\u064e\u0627\u0641\u064f \u0623\u064e\u0646 \u064a\u064e\u0641\u06e1\u0631\u064f\u0637\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627\u0653 \u0623\u064e\u0648\u06e1 \u0623\u064e\u0646 \u064a\u064e\u0637\u06e1\u063a\u064e\u0649\u0670",translation:"Keduanya berkata, \"Ya Tuhan kami, sungguh, kami khawatir dia akan segera menyiksa kami atau akan bertambah melampaui batas"},{id:46,text:"\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0627 \u062a\u064e\u062e\u064e\u0627\u0641\u064e\u0627\u0653\u06d6 \u0625\u0650\u0646\u0651\u064e\u0646\u0650\u064a \u0645\u064e\u0639\u064e\u0643\u064f\u0645\u064e\u0627\u0653 \u0623\u064e\u0633\u06e1\u0645\u064e\u0639\u064f \u0648\u064e\u0623\u064e\u0631\u064e\u0649\u0670",translation:"Dia (Allah) berfirman, \"Janganlah kamu berdua khawatir, sesungguhnya Aku bersama kamu berdua, Aku mendengar dan melihat"},{id:47,text:"\u0641\u064e\u0623\u06e1\u062a\u0650\u064a\u064e\u0627\u0647\u064f \u0641\u064e\u0642\u064f\u0648\u0644\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0627 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0641\u064e\u0623\u064e\u0631\u06e1\u0633\u0650\u0644\u06e1 \u0645\u064e\u0639\u064e\u0646\u064e\u0627 \u0628\u064e\u0646\u0650\u064a\u0653 \u0625\u0650\u0633\u06e1\u0631\u064e\u0640\u0670\u0653\u0621\u0650\u064a\u0644\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u06e1\u0647\u064f\u0645\u06e1\u06d6 \u0642\u064e\u062f\u06e1 \u062c\u0650\u0626\u06e1\u0646\u064e\u0670\u0643\u064e \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0629\u0656 \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064e\u06d6 \u0648\u064e\u0671\u0644\u0633\u0651\u064e\u0644\u064e\u0670\u0645\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0646\u0650 \u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064e \u0671\u0644\u06e1\u0647\u064f\u062f\u064e\u0649\u0670\u0653",translation:"Maka pergilah kamu berdua kepadanya (Fir'aun) dan katakanlah, \"Sungguh, kami berdua adalah utusan Tuhanmu, maka lepaskanlah Bani Israil bersama kami dan janganlah engkau menyiksa mereka.515) Sungguh, kami datang kepadamu dengan membawa bukti (atas kerasulan kami) dari Tuhanmu. Dan keselamatan itu dilimpahkan kepada orang yang mengikuti petunjuk"},{id:48,text:"\u0625\u0650\u0646\u0651\u064e\u0627 \u0642\u064e\u062f\u06e1 \u0623\u064f\u0648\u062d\u0650\u064a\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0646\u064e\u0627\u0653 \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0646 \u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0648\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649\u0670",translation:"Sungguh telah diwahyukan kepada kami bahwa siksa itu (ditimpakan) pada siapa pun yang mendustakan (ajaran agama yang kami bawa) dan berpaling (tidak memperdulikannya)"},{id:49,text:"\u0642\u064e\u0627\u0644\u064e \u0641\u064e\u0645\u064e\u0646 \u0631\u0651\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u064e\u0627 \u064a\u064e\u0670\u0645\u064f\u0648\u0633\u064e\u0649\u0670",translation:"Dia (Fir'aun) berkata, \"Siapakah Tuhanmu berdua, wahai Musa"},{id:50,text:"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u064f\u0646\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064e\u0639\u06e1\u0637\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u064e \u0634\u064e\u064a\u06e1\u0621\u064d \u062e\u064e\u0644\u06e1\u0642\u064e\u0647\u064f\u06e5 \u062b\u064f\u0645\u0651\u064e \u0647\u064e\u062f\u064e\u0649\u0670",translation:"Dia (Musa) menjawab, \"Tuhan kami ialah (Tuhan) yang telah memberikan bentuk kejadian kepada segala sesuatu, kemudian memberinya petunjuk"},{id:51,text:"\u0642\u064e\u0627\u0644\u064e \u0641\u064e\u0645\u064e\u0627 \u0628\u064e\u0627\u0644\u064f \u0671\u0644\u06e1\u0642\u064f\u0631\u064f\u0648\u0646\u0650 \u0671\u0644\u06e1\u0623\u064f\u0648\u0644\u064e\u0649\u0670",translation:"Dia (Fir'aun) berkata, \"Jadi bagaimana keadaan umat-umat yang dahulu"},{id:52,text:"\u0642\u064e\u0627\u0644\u064e \u0639\u0650\u0644\u06e1\u0645\u064f\u0647\u064e\u0627 \u0639\u0650\u0646\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0641\u0650\u064a \u0643\u0650\u062a\u064e\u0670\u0628\u0656\u06d6 \u0644\u0651\u064e\u0627 \u064a\u064e\u0636\u0650\u0644\u0651\u064f \u0631\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0646\u0633\u064e\u0649",translation:"Dia (Musa) menjawab, \"Pengetahuan tentang itu ada pada Tuhanku, di dalam suatu Kitab (lau\u1e25 Ma\u1e25f\u016b\u1e93), Tuhanku tidak akan salah ataupun lupa"},{id:53,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0645\u064e\u0647\u06e1\u062f\u0657\u0627 \u0648\u064e\u0633\u064e\u0644\u064e\u0643\u064e \u0644\u064e\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u0633\u064f\u0628\u064f\u0644\u0657\u0627 \u0648\u064e\u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0645\u064e\u0627\u0653\u0621\u0657 \u0641\u064e\u0623\u064e\u062e\u06e1\u0631\u064e\u062c\u06e1\u0646\u064e\u0627 \u0628\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u0657\u0627 \u0645\u0651\u0650\u0646 \u0646\u0651\u064e\u0628\u064e\u0627\u062a\u0656 \u0634\u064e\u062a\u0651\u064e\u0649\u0670",translation:"(Tuhan) yang telah menjadikan bumi sebagai hamparan bagimu, dan menjadikan jalan-jalan di atasnya bagimu, dan yang menurunkan air (hujan) dari langit.\" Kemudian Kami tumbuhkan dengannya (air hujan itu) berjenis-jenis aneka macam tumbuh-tumbuhan"},{id:54,text:"\u0643\u064f\u0644\u064f\u0648\u0627\u0652 \u0648\u064e\u0671\u0631\u06e1\u0639\u064e\u0648\u06e1\u0627\u0652 \u0623\u064e\u0646\u06e1\u0639\u064e\u0670\u0645\u064e\u0643\u064f\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0623\u0653\u064a\u064e\u0670\u062a\u0656 \u0644\u0651\u0650\u0623\u064f\u0648\u0652\u0644\u0650\u064a \u0671\u0644\u0646\u0651\u064f\u0647\u064e\u0649\u0670",translation:"Makanlah dan gembalakanlah hewan-hewanmu. Sungguh, pada yang demikian itu, terdapat tanda-tanda (kebesaran Allah) bagi orang yang berakal"},{id:55,text:"\u06de\u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u06e1\u0646\u064e\u0670\u0643\u064f\u0645\u06e1 \u0648\u064e\u0641\u0650\u064a\u0647\u064e\u0627 \u0646\u064f\u0639\u0650\u064a\u062f\u064f\u0643\u064f\u0645\u06e1 \u0648\u064e\u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0646\u064f\u062e\u06e1\u0631\u0650\u062c\u064f\u0643\u064f\u0645\u06e1 \u062a\u064e\u0627\u0631\u064e\u0629\u064b \u0623\u064f\u062e\u06e1\u0631\u064e\u0649\u0670",translation:"Darinya (tanah) itulah Kami menciptakan kamu dan kepadanyalah Kami akan mengembalikan kamu dan dari sanalah Kami akan mengeluarkan kamu pada waktu yang lain"},{id:56,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u0631\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0643\u064f\u0644\u0651\u064e\u0647\u064e\u0627 \u0641\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0648\u064e\u0623\u064e\u0628\u064e\u0649\u0670",translation:"Dan sungguh, Kami telah memperlihatkan kepadanya (Fir'aun) tanda-tanda (kebesaran) Kami semuanya,517) ternyata dia mendustakan dan enggan (menerima kebenaran)"},{id:57,text:"\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u062c\u0650\u0626\u06e1\u062a\u064e\u0646\u064e\u0627 \u0644\u0650\u062a\u064f\u062e\u06e1\u0631\u0650\u062c\u064e\u0646\u064e\u0627 \u0645\u0650\u0646\u06e1 \u0623\u064e\u0631\u06e1\u0636\u0650\u0646\u064e\u0627 \u0628\u0650\u0633\u0650\u062d\u06e1\u0631\u0650\u0643\u064e \u064a\u064e\u0670\u0645\u064f\u0648\u0633\u064e\u0649\u0670",translation:"Dia (Fir'aun) berkata, \"Apakah engkau datang kepada kami untuk mengusir kami dari negeri kami dengan sihirmu, wahai Musa"},{id:58,text:"\u0641\u064e\u0644\u064e\u0646\u064e\u0623\u06e1\u062a\u0650\u064a\u064e\u0646\u0651\u064e\u0643\u064e \u0628\u0650\u0633\u0650\u062d\u06e1\u0631\u0656 \u0645\u0651\u0650\u062b\u06e1\u0644\u0650\u0647\u0650\u06e6 \u0641\u064e\u0671\u062c\u06e1\u0639\u064e\u0644\u06e1 \u0628\u064e\u064a\u06e1\u0646\u064e\u0646\u064e\u0627 \u0648\u064e\u0628\u064e\u064a\u06e1\u0646\u064e\u0643\u064e \u0645\u064e\u0648\u06e1\u0639\u0650\u062f\u0657\u0627 \u0644\u0651\u064e\u0627 \u0646\u064f\u062e\u06e1\u0644\u0650\u0641\u064f\u0647\u064f\u06e5 \u0646\u064e\u062d\u06e1\u0646\u064f \u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064e \u0645\u064e\u0643\u064e\u0627\u0646\u0657\u0627 \u0633\u064f\u0648\u0657\u0649",translation:"Maka kami pun pasti akan mendatangkan sihir semacam itu kepadamu, maka buatlah suatu perjanjian untuk pertemuan antara kami dan engkau yang kami tidak akan menyalahinya dan tidak (pula) engkau, di suatu tempat yang terbuka"},{id:59,text:"\u0642\u064e\u0627\u0644\u064e \u0645\u064e\u0648\u06e1\u0639\u0650\u062f\u064f\u0643\u064f\u0645\u06e1 \u064a\u064e\u0648\u06e1\u0645\u064f \u0671\u0644\u0632\u0651\u0650\u064a\u0646\u064e\u0629\u0650 \u0648\u064e\u0623\u064e\u0646 \u064a\u064f\u062d\u06e1\u0634\u064e\u0631\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0636\u064f\u062d\u0657\u0649",translation:"Dia (Musa) berkata, \"(Perjanjian) waktu (untuk pertemuan kami dengan kamu itu) ialah pada hari raya dan hendaklah orang-orang dikumpulkan pada pagi hari (duha)"},{id:60,text:"\u0641\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649\u0670 \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064f \u0641\u064e\u062c\u064e\u0645\u064e\u0639\u064e \u0643\u064e\u064a\u06e1\u062f\u064e\u0647\u064f\u06e5 \u062b\u064f\u0645\u0651\u064e \u0623\u064e\u062a\u064e\u0649\u0670",translation:"Maka Fir'aun meninggalkan (tempat itu), lalu mengatur tipu dayanya, kemudian dia datang kembali (pada hari yang ditentukan)"},{id:61,text:"\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u064a\u06e1\u0644\u064e\u0643\u064f\u0645\u06e1 \u0644\u064e\u0627 \u062a\u064e\u0641\u06e1\u062a\u064e\u0631\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u0630\u0650\u0628\u0657\u0627 \u0641\u064e\u064a\u064f\u0633\u06e1\u062d\u0650\u062a\u064e\u0643\u064f\u0645 \u0628\u0650\u0639\u064e\u0630\u064e\u0627\u0628\u0656\u06d6 \u0648\u064e\u0642\u064e\u062f\u06e1 \u062e\u064e\u0627\u0628\u064e \u0645\u064e\u0646\u0650 \u0671\u0641\u06e1\u062a\u064e\u0631\u064e\u0649\u0670",translation:"Musa berkata kepada mereka (para pesihir), \"Celakalah kamu! Janganlah kamu mengada-adakan kebohongan terhadap Allah, nanti Dia membinasakan kamu dengan azab.\" Dan sungguh rugi orang yang mengada-adakan kebohongan"},{id:62,text:"\u0641\u064e\u062a\u064e\u0646\u064e\u0670\u0632\u064e\u0639\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0645\u06e1\u0631\u064e\u0647\u064f\u0645 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0633\u064e\u0631\u0651\u064f\u0648\u0627\u0652 \u0671\u0644\u0646\u0651\u064e\u062c\u06e1\u0648\u064e\u0649\u0670",translation:"Maka mereka berbantah-bantahan tentang urusan mereka dan mereka merahasiakan percakapan (mereka)"},{id:63,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u06e1 \u0647\u064e\u0670\u0630\u064e\u0670\u0646\u0650 \u0644\u064e\u0633\u064e\u0670\u062d\u0650\u0631\u064e\u0670\u0646\u0650 \u064a\u064f\u0631\u0650\u064a\u062f\u064e\u0627\u0646\u0650 \u0623\u064e\u0646 \u064a\u064f\u062e\u06e1\u0631\u0650\u062c\u064e\u0627\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u0631\u06e1\u0636\u0650\u0643\u064f\u0645 \u0628\u0650\u0633\u0650\u062d\u06e1\u0631\u0650\u0647\u0650\u0645\u064e\u0627 \u0648\u064e\u064a\u064e\u0630\u06e1\u0647\u064e\u0628\u064e\u0627 \u0628\u0650\u0637\u064e\u0631\u0650\u064a\u0642\u064e\u062a\u0650\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064f\u062b\u06e1\u0644\u064e\u0649\u0670",translation:"Mereka (para pesihir) berkata, \"Sesungguhnya dua orang ini adalah pesihir yang hendak mengusirmu (Fir'aun) dari negerimu dengan sihir mereka berdua dan hendak melenyapkan adat kebiasaanmu yang utama"},{id:64,text:"\u0641\u064e\u0623\u064e\u062c\u06e1\u0645\u0650\u0639\u064f\u0648\u0627\u0652 \u0643\u064e\u064a\u06e1\u062f\u064e\u0643\u064f\u0645\u06e1 \u062b\u064f\u0645\u0651\u064e \u0671\u0626\u06e1\u062a\u064f\u0648\u0627\u0652 \u0635\u064e\u0641\u0651\u0657\u0627\u06da \u0648\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u0641\u06e1\u0644\u064e\u062d\u064e \u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e \u0645\u064e\u0646\u0650 \u0671\u0633\u06e1\u062a\u064e\u0639\u06e1\u0644\u064e\u0649\u0670",translation:"Maka kumpulkanlah segala tipu daya (sihir) kamu, kemudian datanglah dengan berbaris, dan sungguh beruntung orang yang menang pada hari ini"},{id:65,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u064a\u064e\u0670\u0645\u064f\u0648\u0633\u064e\u0649\u0670\u0653 \u0625\u0650\u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u062a\u064f\u0644\u06e1\u0642\u0650\u064a\u064e \u0648\u064e\u0625\u0650\u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u0646\u0651\u064e\u0643\u064f\u0648\u0646\u064e \u0623\u064e\u0648\u0651\u064e\u0644\u064e \u0645\u064e\u0646\u06e1 \u0623\u064e\u0644\u06e1\u0642\u064e\u0649\u0670",translation:"Mereka berkata, \"Wahai Musa! Apakah engkau yang melemparkan (dahulu) atau kami yang lebih dahulu melemparkan"},{id:66,text:"\u0642\u064e\u0627\u0644\u064e \u0628\u064e\u0644\u06e1 \u0623\u064e\u0644\u06e1\u0642\u064f\u0648\u0627\u0652\u06d6 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u062d\u0650\u0628\u064e\u0627\u0644\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0639\u0650\u0635\u0650\u064a\u0651\u064f\u0647\u064f\u0645\u06e1 \u064a\u064f\u062e\u064e\u064a\u0651\u064e\u0644\u064f \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0645\u0650\u0646 \u0633\u0650\u062d\u06e1\u0631\u0650\u0647\u0650\u0645\u06e1 \u0623\u064e\u0646\u0651\u064e\u0647\u064e\u0627 \u062a\u064e\u0633\u06e1\u0639\u064e\u0649\u0670",translation:"Dia (Musa) berkata, \"Silakan kamu melemparkan!\" Maka tiba-tiba tali-tali dan tongkat-tongkat mereka terbayang olehnya (Musa) seakan-akan ia merayap cepat, karena sihir mereka"},{id:67,text:"\u0641\u064e\u0623\u064e\u0648\u06e1\u062c\u064e\u0633\u064e \u0641\u0650\u064a \u0646\u064e\u0641\u06e1\u0633\u0650\u0647\u0650\u06e6 \u062e\u0650\u064a\u0641\u064e\u0629\u0657 \u0645\u0651\u064f\u0648\u0633\u064e\u0649\u0670",translation:"Maka Musa merasa takut dalam hatinya"},{id:68,text:"\u0642\u064f\u0644\u06e1\u0646\u064e\u0627 \u0644\u064e\u0627 \u062a\u064e\u062e\u064e\u0641\u06e1 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0623\u064e\u0646\u062a\u064e \u0671\u0644\u06e1\u0623\u064e\u0639\u06e1\u0644\u064e\u0649\u0670",translation:"Kami berfirman, \"Jangan takut! Sungguh, engkaulah yang unggul (menang)"},{id:69,text:"\u0648\u064e\u0623\u064e\u0644\u06e1\u0642\u0650 \u0645\u064e\u0627 \u0641\u0650\u064a \u064a\u064e\u0645\u0650\u064a\u0646\u0650\u0643\u064e \u062a\u064e\u0644\u06e1\u0642\u064e\u0641\u06e1 \u0645\u064e\u0627 \u0635\u064e\u0646\u064e\u0639\u064f\u0648\u0653\u0627\u0652\u06d6 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0635\u064e\u0646\u064e\u0639\u064f\u0648\u0627\u0652 \u0643\u064e\u064a\u06e1\u062f\u064f \u0633\u064e\u0670\u062d\u0650\u0631\u0656\u06d6 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0641\u06e1\u0644\u0650\u062d\u064f \u0671\u0644\u0633\u0651\u064e\u0627\u062d\u0650\u0631\u064f \u062d\u064e\u064a\u06e1\u062b\u064f \u0623\u064e\u062a\u064e\u0649\u0670",translation:"Dan lemparkan apa yang ada di tangan kananmu, niscaya ia akan menelan apa yang mereka buat. Apa yang mereka buat itu hanyalah tipu daya pesihir (belaka). Dan tidak akan menang pesihir itu, dari mana pun ia datang"},{id:70,text:"\u0641\u064e\u0623\u064f\u0644\u06e1\u0642\u0650\u064a\u064e \u0671\u0644\u0633\u0651\u064e\u062d\u064e\u0631\u064e\u0629\u064f \u0633\u064f\u062c\u0651\u064e\u062f\u0657\u0627 \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0621\u064e\u0627\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0631\u064e\u0628\u0651\u0650 \u0647\u064e\u0670\u0631\u064f\u0648\u0646\u064e \u0648\u064e\u0645\u064f\u0648\u0633\u064e\u0649\u0670",translation:"Lalu para pesihir itu merunduk bersujud, seraya berkata, \"Kami telah percaya kepada Tuhannya Harun dan Musa"},{id:71,text:"\u0642\u064e\u0627\u0644\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u062a\u064f\u0645\u06e1 \u0644\u064e\u0647\u064f\u06e5 \u0642\u064e\u0628\u06e1\u0644\u064e \u0623\u064e\u0646\u06e1 \u0621\u064e\u0627\u0630\u064e\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u06e1\u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0643\u064e\u0628\u0650\u064a\u0631\u064f\u0643\u064f\u0645\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0639\u064e\u0644\u0651\u064e\u0645\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0633\u0651\u0650\u062d\u06e1\u0631\u064e\u06d6 \u0641\u064e\u0644\u064e\u0623\u064f\u0642\u064e\u0637\u0651\u0650\u0639\u064e\u0646\u0651\u064e \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0631\u06e1\u062c\u064f\u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u062e\u0650\u0644\u064e\u0670\u0641\u0656 \u0648\u064e\u0644\u064e\u0623\u064f\u0635\u064e\u0644\u0651\u0650\u0628\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u062c\u064f\u0630\u064f\u0648\u0639\u0650 \u0671\u0644\u0646\u0651\u064e\u062e\u06e1\u0644\u0650 \u0648\u064e\u0644\u064e\u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0646\u0651\u064e \u0623\u064e\u064a\u0651\u064f\u0646\u064e\u0627\u0653 \u0623\u064e\u0634\u064e\u062f\u0651\u064f \u0639\u064e\u0630\u064e\u0627\u0628\u0657\u0627 \u0648\u064e\u0623\u064e\u0628\u06e1\u0642\u064e\u0649\u0670",translation:"Dia (Fir'aun) berkata, \"Apakah kamu telah beriman kepadanya (Musa) sebelum aku memberi izin kepadamu? Sesungguhnya dia itu pemimpinmu yang mengajarkan sihir kepadamu. Maka sungguh, akan kupotong tangan dan kakimu secara bersilang, dan sungguh, akan aku salib kamu pada pangkal pohon kurma dan sungguh, kamu pasti akan mengetahui siapa di antara kita yang lebih pedih dan lebih kekal siksaannya"},{id:72,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0646 \u0646\u0651\u064f\u0624\u06e1\u062b\u0650\u0631\u064e\u0643\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0641\u064e\u0637\u064e\u0631\u064e\u0646\u064e\u0627\u06d6 \u0641\u064e\u0671\u0642\u06e1\u0636\u0650 \u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064e \u0642\u064e\u0627\u0636\u064d\u06d6 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u062a\u064e\u0642\u06e1\u0636\u0650\u064a \u0647\u064e\u0670\u0630\u0650\u0647\u0650 \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u064e \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627\u0653",translation:"Mereka (para pesihir) berkata, \"Kami tidak akan memilih (tunduk) kepadamu atas bukti-bukti nyata (mukjizat), yang telah datang kepada kami dan atas (Allah) yang telah menciptakan kami. Maka putuskanlah yang hendak engkau putuskan. Sesungguhnya engkau hanya dapat memutuskan pada kehidupan di dunia ini"},{id:73,text:"\u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0621\u064e\u0627\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627 \u0644\u0650\u064a\u064e\u063a\u06e1\u0641\u0650\u0631\u064e \u0644\u064e\u0646\u064e\u0627 \u062e\u064e\u0637\u064e\u0670\u064a\u064e\u0670\u0646\u064e\u0627 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0643\u06e1\u0631\u064e\u0647\u06e1\u062a\u064e\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0645\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u0650\u062d\u06e1\u0631\u0650\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u062e\u064e\u064a\u06e1\u0631\u065e \u0648\u064e\u0623\u064e\u0628\u06e1\u0642\u064e\u0649\u0670\u0653",translation:"Kami benar-benar telah beriman kepada Tuhan kami, agar Dia mengampuni kesalahan-kesalahan kami dan sihir yang telah engkau paksakan kepada kami. Dan Allah lebih baik (pahala-Nya) dan lebih kekal (azab-Nya)"},{id:74,text:"\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0645\u064e\u0646 \u064a\u064e\u0623\u06e1\u062a\u0650 \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u06e5 \u0645\u064f\u062c\u06e1\u0631\u0650\u0645\u0657\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0644\u064e\u0647\u064f\u06e5 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0644\u064e\u0627 \u064a\u064e\u0645\u064f\u0648\u062a\u064f \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062d\u06e1\u064a\u064e\u0649\u0670",translation:"Sesungguhnya barang siapa datang kepada Tuhannya dalam keadaan berdosa, maka sungguh, baginya adalah neraka Jahanam. Dia tidak mati (terus merasakan azab) di dalamnya dan tidak (pula) hidup (untuk dapat bertobat)"},{id:75,text:"\u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0623\u06e1\u062a\u0650\u0647\u0650\u06e6 \u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0657\u0627 \u0642\u064e\u062f\u06e1 \u0639\u064e\u0645\u0650\u0644\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u062f\u0651\u064e\u0631\u064e\u062c\u064e\u0670\u062a\u064f \u0671\u0644\u06e1\u0639\u064f\u0644\u064e\u0649\u0670",translation:"Tetapi barangsiapa datang kepada-Nya dalam keadaan beriman, dan telah mengerjakan kebajikan, maka mereka itulah orang yang memperoleh derajat yang tinggi (mulia)"},{id:76,text:"\u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u064f \u0639\u064e\u062f\u06e1\u0646\u0656 \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0645\u0650\u0646 \u062a\u064e\u062d\u06e1\u062a\u0650\u0647\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u064f \u062e\u064e\u0670\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627\u06da \u0648\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062c\u064e\u0632\u064e\u0627\u0653\u0621\u064f \u0645\u064e\u0646 \u062a\u064e\u0632\u064e\u0643\u0651\u064e\u0649\u0670",translation:"(yaitu) surga-surga Aden, yang mengalir di bawahnya sungai-sungai, mereka kekal di dalamnya. Itulah balasan bagi orang yang menyucikan diri"},{id:77,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u0648\u06e1\u062d\u064e\u064a\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064f\u0648\u0633\u064e\u0649\u0670\u0653 \u0623\u064e\u0646\u06e1 \u0623\u064e\u0633\u06e1\u0631\u0650 \u0628\u0650\u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a \u0641\u064e\u0671\u0636\u06e1\u0631\u0650\u0628\u06e1 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0637\u064e\u0631\u0650\u064a\u0642\u0657\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0628\u064e\u062d\u06e1\u0631\u0650 \u064a\u064e\u0628\u064e\u0633\u0657\u0627 \u0644\u0651\u064e\u0627 \u062a\u064e\u062e\u064e\u0670\u0641\u064f \u062f\u064e\u0631\u064e\u0643\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062e\u06e1\u0634\u064e\u0649\u0670",translation:"Dan sungguh, telah Kami wahyukan kepada Musa, \"Pergilah bersama hamba-hamba-Ku (Bani Israil) pada malam hari, dan pukullah (buatlah) untuk mereka jalan yang kering di laut itu,518) (engkau) tidak perlu takut akan tersusul dan tidak perlu khawatir (akan tenggelam)"},{id:78,text:"\u0641\u064e\u0623\u064e\u062a\u06e1\u0628\u064e\u0639\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064f \u0628\u0650\u062c\u064f\u0646\u064f\u0648\u062f\u0650\u0647\u0650\u06e6 \u0641\u064e\u063a\u064e\u0634\u0650\u064a\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u064a\u064e\u0645\u0651\u0650 \u0645\u064e\u0627 \u063a\u064e\u0634\u0650\u064a\u064e\u0647\u064f\u0645\u06e1",translation:"Kemudian Fir'aun dengan bala tentaranya mengejar mereka, tetapi mereka digulung ombak laut yang menenggelamkan mereka"},{id:79,text:"\u0648\u064e\u0623\u064e\u0636\u064e\u0644\u0651\u064e \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064f \u0642\u064e\u0648\u06e1\u0645\u064e\u0647\u064f\u06e5 \u0648\u064e\u0645\u064e\u0627 \u0647\u064e\u062f\u064e\u0649\u0670",translation:"Dan Fir'aun telah menyesatkan kaumnya dan tidak memberi petunjuk"},{id:80,text:"\u064a\u064e\u0670\u0628\u064e\u0646\u0650\u064a\u0653 \u0625\u0650\u0633\u06e1\u0631\u064e\u0640\u0670\u0653\u0621\u0650\u064a\u0644\u064e \u0642\u064e\u062f\u06e1 \u0623\u064e\u0646\u062c\u064e\u064a\u06e1\u0646\u064e\u0670\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0639\u064e\u062f\u064f\u0648\u0651\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0648\u064e\u0670\u0639\u064e\u062f\u06e1\u0646\u064e\u0670\u0643\u064f\u0645\u06e1 \u062c\u064e\u0627\u0646\u0650\u0628\u064e \u0671\u0644\u0637\u0651\u064f\u0648\u0631\u0650 \u0671\u0644\u06e1\u0623\u064e\u064a\u06e1\u0645\u064e\u0646\u064e \u0648\u064e\u0646\u064e\u0632\u0651\u064e\u0644\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064e\u0646\u0651\u064e \u0648\u064e\u0671\u0644\u0633\u0651\u064e\u0644\u06e1\u0648\u064e\u0649\u0670",translation:"Wahai Bani Israil! Sungguh, Kami telah menyelamatkan kamu dari musuhmu, dan Kami telah mengadakan perjanjian dengan kamu (untuk bermunajat) di sebelah kanan gunung itu (gunung Sinai) dan Kami telah menurunkan kepada kamu manna dan salw\u0101"},{id:81,text:"\u0643\u064f\u0644\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0637\u064e\u064a\u0651\u0650\u0628\u064e\u0670\u062a\u0650 \u0645\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u06e1\u0646\u064e\u0670\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0637\u06e1\u063a\u064e\u0648\u06e1\u0627\u0652 \u0641\u0650\u064a\u0647\u0650 \u0641\u064e\u064a\u064e\u062d\u0650\u0644\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u063a\u064e\u0636\u064e\u0628\u0650\u064a\u06d6 \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u062d\u06e1\u0644\u0650\u0644\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u063a\u064e\u0636\u064e\u0628\u0650\u064a \u0641\u064e\u0642\u064e\u062f\u06e1 \u0647\u064e\u0648\u064e\u0649\u0670",translation:"Makanlah dari rezeki yang baik-baik yang telah Kami berikan kepadamu, dan janganlah melampaui batas, yang menyebabkan kemurkaan-Ku menimpamu. Barangsiapa ditimpa kemurkaan-Ku, maka sungguh, binasalah dia"},{id:82,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u063a\u064e\u0641\u0651\u064e\u0627\u0631\u065e \u0644\u0651\u0650\u0645\u064e\u0646 \u062a\u064e\u0627\u0628\u064e \u0648\u064e\u0621\u064e\u0627\u0645\u064e\u0646\u064e \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064e \u0635\u064e\u0670\u0644\u0650\u062d\u0657\u0627 \u062b\u064f\u0645\u0651\u064e \u0671\u0647\u06e1\u062a\u064e\u062f\u064e\u0649\u0670",translation:"Dan sungguh, Aku Maha Pengampun bagi yang bertobat, beriman dan berbuat kebajikan, kemudian tetap dalam petunjuk"},{id:83,text:"\u06de\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0639\u06e1\u062c\u064e\u0644\u064e\u0643\u064e \u0639\u064e\u0646 \u0642\u064e\u0648\u06e1\u0645\u0650\u0643\u064e \u064a\u064e\u0670\u0645\u064f\u0648\u0633\u064e\u0649\u0670",translation:"Dan mengapa engkau datang lebih cepat daripada kaummu, wahai Musa"},{id:84,text:"\u0642\u064e\u0627\u0644\u064e \u0647\u064f\u0645\u06e1 \u0623\u064f\u0648\u0652\u0644\u064e\u0627\u0653\u0621\u0650 \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u062b\u064e\u0631\u0650\u064a \u0648\u064e\u0639\u064e\u062c\u0650\u0644\u06e1\u062a\u064f \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0631\u064e\u0628\u0651\u0650 \u0644\u0650\u062a\u064e\u0631\u06e1\u0636\u064e\u0649\u0670",translation:"Dia (Musa) berkata, \"Itu mereka sedang menyusul aku dan aku bersegera kepada-Mu, Ya Tuhanku, agar Engkau rida (kepadaku)"},{id:85,text:"\u0642\u064e\u0627\u0644\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0642\u064e\u062f\u06e1 \u0641\u064e\u062a\u064e\u0646\u0651\u064e\u0627 \u0642\u064e\u0648\u06e1\u0645\u064e\u0643\u064e \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u0643\u064e \u0648\u064e\u0623\u064e\u0636\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0633\u0651\u064e\u0627\u0645\u0650\u0631\u0650\u064a\u0651\u064f",translation:"Dia (Allah) berfirman, \"Sungguh, Kami telah menguji kaummu setelah engkau tinggalkan, dan mereka telah disesatkan oleh Samiri"},{id:86,text:"\u0641\u064e\u0631\u064e\u062c\u064e\u0639\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u06e6 \u063a\u064e\u0636\u06e1\u0628\u064e\u0670\u0646\u064e \u0623\u064e\u0633\u0650\u0641\u0657\u0627\u06da \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0623\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0639\u0650\u062f\u06e1\u0643\u064f\u0645\u06e1 \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u06e1 \u0648\u064e\u0639\u06e1\u062f\u064b\u0627 \u062d\u064e\u0633\u064e\u0646\u064b\u0627\u06da \u0623\u064e\u0641\u064e\u0637\u064e\u0627\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0639\u064e\u0647\u06e1\u062f\u064f \u0623\u064e\u0645\u06e1 \u0623\u064e\u0631\u064e\u062f\u062a\u0651\u064f\u0645\u06e1 \u0623\u064e\u0646 \u064a\u064e\u062d\u0650\u0644\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u063a\u064e\u0636\u064e\u0628\u065e \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1 \u0641\u064e\u0623\u064e\u062e\u06e1\u0644\u064e\u0641\u06e1\u062a\u064f\u0645 \u0645\u0651\u064e\u0648\u06e1\u0639\u0650\u062f\u0650\u064a",translation:"Kemudian Musa kembali kepada kaumnya dengan marah dan bersedih hati. Dia (Musa) berkata, \"Wahai kaumku! Bukankah Tuhanmu telah menjanjikan kepadamu suatu janji yang baik? Apakah terlalu lama masa perjanjian itu bagimu atau kamu menghendaki agar kemurkaan Tuhan menimpamu, mengapa kamu melanggar perjanjianmu dengan aku"},{id:87,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0645\u064e\u0627\u0653 \u0623\u064e\u062e\u06e1\u0644\u064e\u0641\u06e1\u0646\u064e\u0627 \u0645\u064e\u0648\u06e1\u0639\u0650\u062f\u064e\u0643\u064e \u0628\u0650\u0645\u064e\u0644\u06e1\u0643\u0650\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e\u0627 \u062d\u064f\u0645\u0651\u0650\u0644\u06e1\u0646\u064e\u0627\u0653 \u0623\u064e\u0648\u06e1\u0632\u064e\u0627\u0631\u0657\u0627 \u0645\u0651\u0650\u0646 \u0632\u0650\u064a\u0646\u064e\u0629\u0650 \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u0650 \u0641\u064e\u0642\u064e\u0630\u064e\u0641\u06e1\u0646\u064e\u0670\u0647\u064e\u0627 \u0641\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0623\u064e\u0644\u06e1\u0642\u064e\u0649 \u0671\u0644\u0633\u0651\u064e\u0627\u0645\u0650\u0631\u0650\u064a\u0651\u064f",translation:"Mereka berkata, \"Kami tidak melanggar perjanjianmu dengan kemauan kami sendiri, tetapi kami harus membawa beban berat dari perhiasan kaum (Fir'aun) itu, kemudian kami melemparkannya (ke dalam api), dan demikian pula Samiri melemparkannya"},{id:88,text:"\u0641\u064e\u0623\u064e\u062e\u06e1\u0631\u064e\u062c\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u0650\u062c\u06e1\u0644\u0657\u0627 \u062c\u064e\u0633\u064e\u062f\u0657\u0627 \u0644\u0651\u064e\u0647\u064f\u06e5 \u062e\u064f\u0648\u064e\u0627\u0631\u065e \u0641\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0647\u064e\u0670\u0630\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u064f\u0643\u064f\u0645\u06e1 \u0648\u064e\u0625\u0650\u0644\u064e\u0670\u0647\u064f \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0641\u064e\u0646\u064e\u0633\u0650\u064a\u064e",translation:"kemudian (dari lubang api itu) dia (Samiri) mengeluarkan (patung) anak sapi yang bertubuh dan bersuara520) untuk mereka, maka mereka berkata, \"Inilah Tuhanmu dan Tuhannya Musa, tetapi dia (Musa) telah lupa"},{id:89,text:"\u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0631\u064e\u0648\u06e1\u0646\u064e \u0623\u064e\u0644\u0651\u064e\u0627 \u064a\u064e\u0631\u06e1\u062c\u0650\u0639\u064f \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0642\u064e\u0648\u06e1\u0644\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0645\u06e1\u0644\u0650\u0643\u064f \u0644\u064e\u0647\u064f\u0645\u06e1 \u0636\u064e\u0631\u0651\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0641\u06e1\u0639\u0657\u0627",translation:"Maka tidakkah mereka memperhatikan bahwa (patung anak sapi itu) tidak dapat memberi jawaban kepada mereka, dan tidak kuasa menolak mudarat maupun mendatangkan manfaat untuk mereka"},{id:90,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0647\u064e\u0670\u0631\u064f\u0648\u0646\u064f \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f \u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0641\u064f\u062a\u0650\u0646\u062a\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u064f \u0641\u064e\u0671\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0646\u0650\u064a \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0645\u06e1\u0631\u0650\u064a",translation:"Dan sungguh, sebelumnya Harun telah berkata kepada mereka, \"Wahai kaumku! Sesungguhnya kamu hanya sekedar diberi cobaan (dengan patung anak sapi) itu dan sungguh, Tuhanmu ialah (Allah) Yang Maha Pengasih, maka ikutilah aku dan taatilah perintahku"},{id:91,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0646 \u0646\u0651\u064e\u0628\u06e1\u0631\u064e\u062d\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0639\u064e\u0670\u0643\u0650\u0641\u0650\u064a\u0646\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0631\u06e1\u062c\u0650\u0639\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670",translation:"Mereka menjawab, \"Kami tidak akan meninggalkannya (dan) tetap menyembahnya (patung anak sapi) sampai Musa kembali kepada kami"},{id:92,text:"\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0670\u0647\u064e\u0670\u0631\u064f\u0648\u0646\u064f \u0645\u064e\u0627 \u0645\u064e\u0646\u064e\u0639\u064e\u0643\u064e \u0625\u0650\u0630\u06e1 \u0631\u064e\u0623\u064e\u064a\u06e1\u062a\u064e\u0647\u064f\u0645\u06e1 \u0636\u064e\u0644\u0651\u064f\u0648\u0653\u0627\u0652",translation:"Dia (Musa) berkata, \"Wahai Harun! Apa yang menghalangimu ketika engkau melihat mereka telah sesat"},{id:93,text:"\u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064e\u0646\u0650\u06d6 \u0623\u064e\u0641\u064e\u0639\u064e\u0635\u064e\u064a\u06e1\u062a\u064e \u0623\u064e\u0645\u06e1\u0631\u0650\u064a",translation:"(sehingga) engkau tidak mengikuti aku? Apakah engkau telah (sengaja) melanggar perintahku"},{id:94,text:"\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0628\u06e1\u0646\u064e\u0624\u064f\u0645\u0651\u064e \u0644\u064e\u0627 \u062a\u064e\u0623\u06e1\u062e\u064f\u0630\u06e1 \u0628\u0650\u0644\u0650\u062d\u06e1\u064a\u064e\u062a\u0650\u064a \u0648\u064e\u0644\u064e\u0627 \u0628\u0650\u0631\u064e\u0623\u06e1\u0633\u0650\u064a\u0653\u06d6 \u0625\u0650\u0646\u0651\u0650\u064a \u062e\u064e\u0634\u0650\u064a\u062a\u064f \u0623\u064e\u0646 \u062a\u064e\u0642\u064f\u0648\u0644\u064e \u0641\u064e\u0631\u0651\u064e\u0642\u06e1\u062a\u064e \u0628\u064e\u064a\u06e1\u0646\u064e \u0628\u064e\u0646\u0650\u064a\u0653 \u0625\u0650\u0633\u06e1\u0631\u064e\u0640\u0670\u0653\u0621\u0650\u064a\u0644\u064e \u0648\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0631\u06e1\u0642\u064f\u0628\u06e1 \u0642\u064e\u0648\u06e1\u0644\u0650\u064a",translation:"Dia (Harun) menjawab, \"Wahai putra ibuku! Janganlah engkau pegang janggutku dan jangan (pula) kepalaku. Aku sungguh khawatir engkau akan berkata (kepadaku), \"Engkau telah memecah belah antara Bani Israil dan engkau tidak memelihara amanatku"},{id:95,text:"\u0642\u064e\u0627\u0644\u064e \u0641\u064e\u0645\u064e\u0627 \u062e\u064e\u0637\u06e1\u0628\u064f\u0643\u064e \u064a\u064e\u0670\u0633\u064e\u0670\u0645\u0650\u0631\u0650\u064a\u0651\u064f",translation:"Dia (Musa) berkata, \"Apakah yang mendorongmu (berbuat demikian) wahai Samiri"},{id:96,text:"\u0642\u064e\u0627\u0644\u064e \u0628\u064e\u0635\u064f\u0631\u06e1\u062a\u064f \u0628\u0650\u0645\u064e\u0627 \u0644\u064e\u0645\u06e1 \u064a\u064e\u0628\u06e1\u0635\u064f\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6 \u0641\u064e\u0642\u064e\u0628\u064e\u0636\u06e1\u062a\u064f \u0642\u064e\u0628\u06e1\u0636\u064e\u0629\u0657 \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u062b\u064e\u0631\u0650 \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0650 \u0641\u064e\u0646\u064e\u0628\u064e\u0630\u06e1\u062a\u064f\u0647\u064e\u0627 \u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0633\u064e\u0648\u0651\u064e\u0644\u064e\u062a\u06e1 \u0644\u0650\u064a \u0646\u064e\u0641\u06e1\u0633\u0650\u064a",translation:"Dia (Samiri) menjawab, \"Aku mengetahui sesuatu yang tidak mereka ketahui, jadi aku ambil segenggam (tanah dari) jejak rasul521) lalu aku melemparkannya (ke dalam api itu), demikianlah nafsuku membujukku"},{id:97,text:"\u0642\u064e\u0627\u0644\u064e \u0641\u064e\u0671\u0630\u06e1\u0647\u064e\u0628\u06e1 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0644\u064e\u0643\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u0650 \u0623\u064e\u0646 \u062a\u064e\u0642\u064f\u0648\u0644\u064e \u0644\u064e\u0627 \u0645\u0650\u0633\u064e\u0627\u0633\u064e\u06d6 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0644\u064e\u0643\u064e \u0645\u064e\u0648\u06e1\u0639\u0650\u062f\u0657\u0627 \u0644\u0651\u064e\u0646 \u062a\u064f\u062e\u06e1\u0644\u064e\u0641\u064e\u0647\u064f\u06e5\u06d6 \u0648\u064e\u0671\u0646\u0638\u064f\u0631\u06e1 \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u0650\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0638\u064e\u0644\u06e1\u062a\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0639\u064e\u0627\u0643\u0650\u0641\u0657\u0627\u06d6 \u0644\u0651\u064e\u0646\u064f\u062d\u064e\u0631\u0651\u0650\u0642\u064e\u0646\u0651\u064e\u0647\u064f\u06e5 \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0646\u064e\u0646\u0633\u0650\u0641\u064e\u0646\u0651\u064e\u0647\u064f\u06e5 \u0641\u0650\u064a \u0671\u0644\u06e1\u064a\u064e\u0645\u0651\u0650 \u0646\u064e\u0633\u06e1\u0641\u064b\u0627",translation:"Dia (Musa) berkata, \"Pergilah kau! Maka sesungguhnya di dalam kehidupan (di dunia) engkau (hanya dapat) mengatakan, \u2018Janganlah menyentuh (aku)\u2019! 522) Dan engkau pasti mendapat (hukuman) yang telah dijanjikan (di akhirat) yang tidak mungkin engkau hindari, dan lihatlah tuhanmu itu yang engkau tetap menyembahnya. Kami pasti akan membakarnya, kemudian sungguh kami akan menghamburkannya (abunya) ke dalam laut (berserakan)"},{id:98,text:"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u064f\u0643\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0644\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e\u06da \u0648\u064e\u0633\u0650\u0639\u064e \u0643\u064f\u0644\u0651\u064e \u0634\u064e\u064a\u06e1\u0621\u064d \u0639\u0650\u0644\u06e1\u0645\u0657\u0627",translation:"Sungguh, Tuhanmu hanyalah Allah, tidak ada Tuhan selain Dia. Pengetahuan-Nya meliputi segala sesuatu"},{id:99,text:"\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u0642\u064f\u0635\u0651\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0645\u0650\u0646\u06e1 \u0623\u064e\u0646\u06e2\u0628\u064e\u0627\u0653\u0621\u0650 \u0645\u064e\u0627 \u0642\u064e\u062f\u06e1 \u0633\u064e\u0628\u064e\u0642\u064e\u06da \u0648\u064e\u0642\u064e\u062f\u06e1 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0670\u0643\u064e \u0645\u0650\u0646 \u0644\u0651\u064e\u062f\u064f\u0646\u0651\u064e\u0627 \u0630\u0650\u0643\u06e1\u0631\u0657\u0627",translation:"Demikianlah Kami kisahkan kepadamu (Muhammad) sebagian kisah (umat) yang telah lalu, dan sungguh, telah Kami berikan kepadamu suatu peringatan (Alquran) dari sisi Kami"},{id:100,text:"\u0645\u0651\u064e\u0646\u06e1 \u0623\u064e\u0639\u06e1\u0631\u064e\u0636\u064e \u0639\u064e\u0646\u06e1\u0647\u064f \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u064a\u064e\u062d\u06e1\u0645\u0650\u0644\u064f \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u0648\u0650\u0632\u06e1\u0631\u064b\u0627",translation:"Barang siapa berpaling darinya (Alquran), maka sesungguhnya dia akan memikul beban yang berat (dosa) pada hari Kiamat"},{id:101,text:"\u062e\u064e\u0670\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u0650\u06d6 \u0648\u064e\u0633\u064e\u0627\u0653\u0621\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u062d\u0650\u0645\u06e1\u0644\u0657\u0627",translation:"mereka kekal di dalam keadaan itu. Dan sungguh buruk beban dosa itu bagi mereka pada hari Kiamat"},{id:102,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064f\u0646\u0641\u064e\u062e\u064f \u0641\u0650\u064a \u0671\u0644\u0635\u0651\u064f\u0648\u0631\u0650\u06da \u0648\u064e\u0646\u064e\u062d\u06e1\u0634\u064f\u0631\u064f \u0671\u0644\u06e1\u0645\u064f\u062c\u06e1\u0631\u0650\u0645\u0650\u064a\u0646\u064e \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u0632\u064f\u0631\u06e1\u0642\u0657\u0627",translation:"pada hari (Kiamat) sangkakala ditiup (yang kedua kali) 523) dan pada hari itu Kami kumpulkan orang-orang yang berdosa dengan (wajah) biru muram"},{id:103,text:"\u064a\u064e\u062a\u064e\u062e\u064e\u0670\u0641\u064e\u062a\u064f\u0648\u0646\u064e \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1 \u0625\u0650\u0646 \u0644\u0651\u064e\u0628\u0650\u062b\u06e1\u062a\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0634\u06e1\u0631\u0657\u0627",translation:"mereka saling berbisik satu sama lain, \"Kamu tinggal (di dunia) tidak lebih dari sepuluh (hari)"},{id:104,text:"\u0646\u0651\u064e\u062d\u06e1\u0646\u064f \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0625\u0650\u0630\u06e1 \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0623\u064e\u0645\u06e1\u062b\u064e\u0644\u064f\u0647\u064f\u0645\u06e1 \u0637\u064e\u0631\u0650\u064a\u0642\u064e\u0629\u064b \u0625\u0650\u0646 \u0644\u0651\u064e\u0628\u0650\u062b\u06e1\u062a\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u064a\u064e\u0648\u06e1\u0645\u0657\u0627",translation:"(Kami lebih mengetahui apa yang akan mereka katakan, ketika orang yang paling lurus jalannya524) mengatakan, \"Kamu tinggal (di dunia), tidak lebih dari sehari saja"},{id:105,text:"\u0648\u064e\u064a\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u0639\u064e\u0646\u0650 \u0671\u0644\u06e1\u062c\u0650\u0628\u064e\u0627\u0644\u0650 \u0641\u064e\u0642\u064f\u0644\u06e1 \u064a\u064e\u0646\u0633\u0650\u0641\u064f\u0647\u064e\u0627 \u0631\u064e\u0628\u0651\u0650\u064a \u0646\u064e\u0633\u06e1\u0641\u0657\u0627",translation:"Dan mereka bertanya kepadamu (Muhammad) tentang gunung-gunung, maka katakanlah, \"Tuhanku akan menghancurkannya (pada hari Kiamat) sehancur-hancurnya"},{id:106,text:"\u0641\u064e\u064a\u064e\u0630\u064e\u0631\u064f\u0647\u064e\u0627 \u0642\u064e\u0627\u0639\u0657\u0627 \u0635\u064e\u0641\u06e1\u0635\u064e\u0641\u0657\u0627",translation:"kemudian Dia akan menjadikan (bekas gunung-gunung) itu rata sama sekali"},{id:107,text:"\u0644\u0651\u064e\u0627 \u062a\u064e\u0631\u064e\u0649\u0670 \u0641\u0650\u064a\u0647\u064e\u0627 \u0639\u0650\u0648\u064e\u062c\u0657\u0627 \u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064e\u0645\u06e1\u062a\u0657\u0627",translation:"(sehingga) kamu tidak akan melihat lagi ada tempat yang rendah dan yang tinggi di sana"},{id:108,text:"\u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u064a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0646\u064e \u0671\u0644\u062f\u0651\u064e\u0627\u0639\u0650\u064a\u064e \u0644\u064e\u0627 \u0639\u0650\u0648\u064e\u062c\u064e \u0644\u064e\u0647\u064f\u06e5\u06d6 \u0648\u064e\u062e\u064e\u0634\u064e\u0639\u064e\u062a\u0650 \u0671\u0644\u06e1\u0623\u064e\u0635\u06e1\u0648\u064e\u0627\u062a\u064f \u0644\u0650\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u0650 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0633\u06e1\u0645\u064e\u0639\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064e\u0645\u06e1\u0633\u0657\u0627",translation:"Pada hari itu mereka mengikuti (panggilan) penyeru (malaikat) tanpa berbelok-belok (membantah); dan semua suara tunduk merendah kepada Tuhan Yang Maha Pengasih, sehingga yang kamu dengar hanyalah bisik-bisik"},{id:109,text:"\u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u0644\u0651\u064e\u0627 \u062a\u064e\u0646\u0641\u064e\u0639\u064f \u0671\u0644\u0634\u0651\u064e\u0641\u064e\u0670\u0639\u064e\u0629\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u06e1 \u0623\u064e\u0630\u0650\u0646\u064e \u0644\u064e\u0647\u064f \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u064f \u0648\u064e\u0631\u064e\u0636\u0650\u064a\u064e \u0644\u064e\u0647\u064f\u06e5 \u0642\u064e\u0648\u06e1\u0644\u0657\u0627",translation:"Pada hari itu tidak berguna syafaat (pertolongan), kecuali dari orang yang telah diberi izin oleh Tuhan Yang Maha Pengasih, dan Dia ridai perkataannya"},{id:110,text:"\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u0647\u0650\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u06e1\u0641\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u064a\u0637\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u0650\u06e6 \u0639\u0650\u0644\u06e1\u0645\u0657\u0627",translation:"Dia (Allah) mengetahui apa yang di hadapan mereka (yang akan terjadi) dan apa yang di belakang mereka (yang telah terjadi), sedang ilmu mereka tidak dapat meliputi ilmu-Nya"},{id:111,text:"\u06de\u0648\u064e\u0639\u064e\u0646\u064e\u062a\u0650 \u0671\u0644\u06e1\u0648\u064f\u062c\u064f\u0648\u0647\u064f \u0644\u0650\u0644\u06e1\u062d\u064e\u064a\u0651\u0650 \u0671\u0644\u06e1\u0642\u064e\u064a\u0651\u064f\u0648\u0645\u0650\u06d6 \u0648\u064e\u0642\u064e\u062f\u06e1 \u062e\u064e\u0627\u0628\u064e \u0645\u064e\u0646\u06e1 \u062d\u064e\u0645\u064e\u0644\u064e \u0638\u064f\u0644\u06e1\u0645\u0657\u0627",translation:"Dan semua wajah tertunduk di hadapan (Allah) Yang Maha Hidup dan Yang Berdiri Sendiri. Sungguh rugi orang yang melakukan kezaliman"},{id:112,text:"\u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u06e1 \u0645\u0650\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0648\u064e\u0647\u064f\u0648\u064e \u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u065e \u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u062e\u064e\u0627\u0641\u064f \u0638\u064f\u0644\u06e1\u0645\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u0647\u064e\u0636\u06e1\u0645\u0657\u0627",translation:"Dan barang siapa mengerjakan kebajikan sedang dia (dalam keadaan) beriman, maka dia tidak khawatir akan perlakuan zalim (terhadapnya) dan tidak (pula khawatir) akan pengurangan haknya"},{id:113,text:"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f \u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u064b\u0627 \u0639\u064e\u0631\u064e\u0628\u0650\u064a\u0651\u0657\u0627 \u0648\u064e\u0635\u064e\u0631\u0651\u064e\u0641\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u0650 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0648\u064e\u0639\u0650\u064a\u062f\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e \u0623\u064e\u0648\u06e1 \u064a\u064f\u062d\u06e1\u062f\u0650\u062b\u064f \u0644\u064e\u0647\u064f\u0645\u06e1 \u0630\u0650\u0643\u06e1\u0631\u0657\u0627",translation:"Dan demikianlah Kami menurunkan Alquran dalam bahasa Arab, dan Kami telah menjelaskan berulang-ulang di dalamnya sebagian dari ancaman, agar mereka bertakwa, atau agar (Alquran) itu memberi pengajaran bagi mereka"},{id:114,text:"\u0641\u064e\u062a\u064e\u0639\u064e\u0670\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u0645\u064e\u0644\u0650\u0643\u064f \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f\u06d7 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u062c\u064e\u0644\u06e1 \u0628\u0650\u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u0650 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650 \u0623\u064e\u0646 \u064a\u064f\u0642\u06e1\u0636\u064e\u0649\u0670\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0648\u064e\u062d\u06e1\u064a\u064f\u0647\u064f\u06e5\u06d6 \u0648\u064e\u0642\u064f\u0644 \u0631\u0651\u064e\u0628\u0651\u0650 \u0632\u0650\u062f\u06e1\u0646\u0650\u064a \u0639\u0650\u0644\u06e1\u0645\u0657\u0627",translation:"Maka Mahatinggi Allah, Raja yang sebenar-benarnya. Dan janganlah engkau (Muhammad) tergesa-gesa (membaca) Alquran sebelum selesai diwahyukan kepadamu,525) dan katakanlah, \"Ya Tuhanku, tambahkanlah ilmu kepadaku"},{id:115,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0639\u064e\u0647\u0650\u062f\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0621\u064e\u0627\u062f\u064e\u0645\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f \u0641\u064e\u0646\u064e\u0633\u0650\u064a\u064e \u0648\u064e\u0644\u064e\u0645\u06e1 \u0646\u064e\u062c\u0650\u062f\u06e1 \u0644\u064e\u0647\u064f\u06e5 \u0639\u064e\u0632\u06e1\u0645\u0657\u0627",translation:"(Dan sungguh telah Kami pesankan526) kepada Adam dahulu, tetapi dia lupa, dan Kami tidak dapati kemauan yang kuat padanya"},{id:116,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0642\u064f\u0644\u06e1\u0646\u064e\u0627 \u0644\u0650\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u0650 \u0671\u0633\u06e1\u062c\u064f\u062f\u064f\u0648\u0627\u0652 \u0644\u0650\u0623\u0653\u062f\u064e\u0645\u064e \u0641\u064e\u0633\u064e\u062c\u064e\u062f\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0625\u0650\u0628\u06e1\u0644\u0650\u064a\u0633\u064e \u0623\u064e\u0628\u064e\u0649\u0670",translation:"Dan (ingatlah) ketika Kami berfirman kepada para malaikat, \"Sujudlah kamu kepada Adam!\" Lalu mereka pun sujud kecuali Iblis; dia menolak"},{id:117,text:"\u0641\u064e\u0642\u064f\u0644\u06e1\u0646\u064e\u0627 \u064a\u064e\u0640\u0670\u0653\u0640\u0654\u064e\u0627\u062f\u064e\u0645\u064f \u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0639\u064e\u062f\u064f\u0648\u0651\u065e \u0644\u0651\u064e\u0643\u064e \u0648\u064e\u0644\u0650\u0632\u064e\u0648\u06e1\u062c\u0650\u0643\u064e \u0641\u064e\u0644\u064e\u0627 \u064a\u064f\u062e\u06e1\u0631\u0650\u062c\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u064e\u0627 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u0641\u064e\u062a\u064e\u0634\u06e1\u0642\u064e\u0649\u0670\u0653",translation:"Kemudian Kami berfirman, \"Wahai Adam! Sungguh ini (Iblis) musuh bagimu dan bagi istrimu, maka sekali-kali jangan sampai dia mengeluarkan kamu berdua dari surga, nanti kamu celaka"},{id:118,text:"\u0625\u0650\u0646\u0651\u064e \u0644\u064e\u0643\u064e \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064e\u062c\u064f\u0648\u0639\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u0631\u064e\u0649\u0670",translation:"Sungguh, ada (jaminan) untukmu di sana, engkau tidak akan kelaparan dan tidak akan telanjang"},{id:119,text:"\u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u0627 \u062a\u064e\u0638\u06e1\u0645\u064e\u0624\u064f\u0627\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0636\u06e1\u062d\u064e\u0649\u0670",translation:"dan sungguh, di sana engkau tidak akan merasa dahaga dan tidak akan ditimpa panas matahari"},{id:120,text:"\u0641\u064e\u0648\u064e\u0633\u06e1\u0648\u064e\u0633\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u064f \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0640\u0670\u0653\u0640\u0654\u064e\u0627\u062f\u064e\u0645\u064f \u0647\u064e\u0644\u06e1 \u0623\u064e\u062f\u064f\u0644\u0651\u064f\u0643\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0634\u064e\u062c\u064e\u0631\u064e\u0629\u0650 \u0671\u0644\u06e1\u062e\u064f\u0644\u06e1\u062f\u0650 \u0648\u064e\u0645\u064f\u0644\u06e1\u0643\u0656 \u0644\u0651\u064e\u0627 \u064a\u064e\u0628\u06e1\u0644\u064e\u0649\u0670",translation:"Kemudian setan membisikkan (pikiran jahat) kepadanya, dengan berkata, \"Wahai Adam! maukah aku tunjukkan kepadamu pohon keabadian (khuldi) dan kerajaan yang tidak akan binasa"},{id:121,text:"\u0641\u064e\u0623\u064e\u0643\u064e\u0644\u064e\u0627 \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0641\u064e\u0628\u064e\u062f\u064e\u062a\u06e1 \u0644\u064e\u0647\u064f\u0645\u064e\u0627 \u0633\u064e\u0648\u06e1\u0621\u064e\u0670\u062a\u064f\u0647\u064f\u0645\u064e\u0627 \u0648\u064e\u0637\u064e\u0641\u0650\u0642\u064e\u0627 \u064a\u064e\u062e\u06e1\u0635\u0650\u0641\u064e\u0627\u0646\u0650 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u064e\u0627 \u0645\u0650\u0646 \u0648\u064e\u0631\u064e\u0642\u0650 \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u0650\u06da \u0648\u064e\u0639\u064e\u0635\u064e\u0649\u0670\u0653 \u0621\u064e\u0627\u062f\u064e\u0645\u064f \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u06e5 \u0641\u064e\u063a\u064e\u0648\u064e\u0649\u0670",translation:"Lalu keduanya memakannya, lalu tampaklah oleh keduanya aurat mereka dan mulailah keduanya menutupinya dengan daun-daun (yang ada di) surga, dan telah durhakalah Adam kepada Tuhan-Nya, dan sesatlah dia"},{id:122,text:"\u062b\u064f\u0645\u0651\u064e \u0671\u062c\u06e1\u062a\u064e\u0628\u064e\u0670\u0647\u064f \u0631\u064e\u0628\u0651\u064f\u0647\u064f\u06e5 \u0641\u064e\u062a\u064e\u0627\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0648\u064e\u0647\u064e\u062f\u064e\u0649\u0670",translation:"(Kemudian Tuhannya memilih dia,528) maka Dia menerima tobatnya dan memberinya petunjuk"},{id:123,text:"\u0642\u064e\u0627\u0644\u064e \u0671\u0647\u06e1\u0628\u0650\u0637\u064e\u0627 \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u062c\u064e\u0645\u0650\u064a\u0639\u064e\u06e2\u0627\u06d6 \u0628\u064e\u0639\u06e1\u0636\u064f\u0643\u064f\u0645\u06e1 \u0644\u0650\u0628\u064e\u0639\u06e1\u0636\u064d \u0639\u064e\u062f\u064f\u0648\u0651\u065e\u06d6 \u0641\u064e\u0625\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e\u0646\u0651\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u0651\u0650\u064a \u0647\u064f\u062f\u0657\u0649 \u0641\u064e\u0645\u064e\u0646\u0650 \u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064e \u0647\u064f\u062f\u064e\u0627\u064a\u064e \u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0636\u0650\u0644\u0651\u064f \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0634\u06e1\u0642\u064e\u0649\u0670",translation:"Dia (Allah) berfirman, \"Turunlah kamu berdua dari surga bersama-sama, sebagian kamu menjadi musuh bagi sebagian yang lain. Jika datang kepadamu petunjuk dari-Ku, maka (ketahuilah) barang siapa mengikuti petunjuk-Ku, dia tidak akan sesat dan tidak akan celaka"},{id:124,text:"\u0648\u064e\u0645\u064e\u0646\u06e1 \u0623\u064e\u0639\u06e1\u0631\u064e\u0636\u064e \u0639\u064e\u0646 \u0630\u0650\u0643\u06e1\u0631\u0650\u064a \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0644\u064e\u0647\u064f\u06e5 \u0645\u064e\u0639\u0650\u064a\u0634\u064e\u0629\u0657 \u0636\u064e\u0646\u0643\u0657\u0627 \u0648\u064e\u0646\u064e\u062d\u06e1\u0634\u064f\u0631\u064f\u0647\u064f\u06e5 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u0623\u064e\u0639\u06e1\u0645\u064e\u0649\u0670",translation:"Dan barangsiapa berpaling dari peringatan-Ku, maka sungguh, dia akan menjalani kehidupan yang sempit, dan Kami akan mengumpulkannya pada hari Kiamat dalam keadaan buta"},{id:125,text:"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0644\u0650\u0645\u064e \u062d\u064e\u0634\u064e\u0631\u06e1\u062a\u064e\u0646\u0650\u064a\u0653 \u0623\u064e\u0639\u06e1\u0645\u064e\u0649\u0670 \u0648\u064e\u0642\u064e\u062f\u06e1 \u0643\u064f\u0646\u062a\u064f \u0628\u064e\u0635\u0650\u064a\u0631\u0657\u0627",translation:"Dia berkata, \"Ya Tuhanku, mengapa Engkau kumpulkan aku dalam keadaan buta, padahal dahulu aku dapat melihat"},{id:126,text:"\u0642\u064e\u0627\u0644\u064e \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0623\u064e\u062a\u064e\u062a\u06e1\u0643\u064e \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u064f\u0646\u064e\u0627 \u0641\u064e\u0646\u064e\u0633\u0650\u064a\u062a\u064e\u0647\u064e\u0627\u06d6 \u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e \u062a\u064f\u0646\u0633\u064e\u0649\u0670",translation:"Dia (Allah) berfirman, \"Demikianlah, dahulu telah datang kepadamu ayat-ayat Kami, dan kamu mengabaikannya, jadi begitu (pula) pada hari ini kamu diabaikan"},{id:127,text:"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u062c\u06e1\u0632\u0650\u064a \u0645\u064e\u0646\u06e1 \u0623\u064e\u0633\u06e1\u0631\u064e\u0641\u064e \u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u06e2 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u06e6\u06da \u0648\u064e\u0644\u064e\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0623\u064e\u0634\u064e\u062f\u0651\u064f \u0648\u064e\u0623\u064e\u0628\u06e1\u0642\u064e\u0649\u0670\u0653",translation:"Dan demikianlah Kami membalas orang yang melampaui batas dan tidak percaya kepada ayat-ayat Tuhannya. Sungguh, azab di akhirat itu lebih berat dan lebih kekal"},{id:128,text:"\u0623\u064e\u0641\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0647\u06e1\u062f\u0650 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0645\u06e1 \u0623\u064e\u0647\u06e1\u0644\u064e\u0643\u06e1\u0646\u064e\u0627 \u0642\u064e\u0628\u06e1\u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0642\u064f\u0631\u064f\u0648\u0646\u0650 \u064a\u064e\u0645\u06e1\u0634\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0645\u064e\u0633\u064e\u0670\u0643\u0650\u0646\u0650\u0647\u0650\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0623\u0653\u064a\u064e\u0670\u062a\u0656 \u0644\u0651\u0650\u0623\u064f\u0648\u0652\u0644\u0650\u064a \u0671\u0644\u0646\u0651\u064f\u0647\u064e\u0649\u0670",translation:"Maka tidakkah menjadi petunjuk bagi mereka (orang-orang musyrik) berapa banyak (generasi) sebelum mereka yang telah Kami binasakan, padahal mereka melewati (bekas-bekas) tempat tinggal mereka (umat-umat itu)? Sungguh, pada yang demikian itu terdapat tanda-tanda (kekuasaan Allah) bagi orang-orang yang berakal"},{id:129,text:"\u0648\u064e\u0644\u064e\u0648\u06e1\u0644\u064e\u0627 \u0643\u064e\u0644\u0650\u0645\u064e\u0629\u065e \u0633\u064e\u0628\u064e\u0642\u064e\u062a\u06e1 \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064e \u0644\u064e\u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0632\u064e\u0627\u0645\u0657\u0627 \u0648\u064e\u0623\u064e\u062c\u064e\u0644\u065e \u0645\u0651\u064f\u0633\u064e\u0645\u0651\u0657\u0649",translation:"Dan kalau tidak ada suatu ketetapan terdahulu dari Tuhanmu serta tidak ada batas yang telah ditentukan (ajal), pasti (siksaan itu) menimpa mereka"},{id:130,text:"\u0641\u064e\u0671\u0635\u06e1\u0628\u0650\u0631\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0648\u064e\u0633\u064e\u0628\u0651\u0650\u062d\u06e1 \u0628\u0650\u062d\u064e\u0645\u06e1\u062f\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0642\u064e\u0628\u06e1\u0644\u064e \u0637\u064f\u0644\u064f\u0648\u0639\u0650 \u0671\u0644\u0634\u0651\u064e\u0645\u06e1\u0633\u0650 \u0648\u064e\u0642\u064e\u0628\u06e1\u0644\u064e \u063a\u064f\u0631\u064f\u0648\u0628\u0650\u0647\u064e\u0627\u06d6 \u0648\u064e\u0645\u0650\u0646\u06e1 \u0621\u064e\u0627\u0646\u064e\u0627\u0653\u064a\u0655\u0650 \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u0650 \u0641\u064e\u0633\u064e\u0628\u0651\u0650\u062d\u06e1 \u0648\u064e\u0623\u064e\u0637\u06e1\u0631\u064e\u0627\u0641\u064e \u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064e \u062a\u064e\u0631\u06e1\u0636\u064e\u0649\u0670",translation:"Maka sabarlah engkau (Muhammad) atas apa yang mereka katakan, dan bertasbihlah dengan memuji Tuhanmu, sebelum matahari terbit, dan sebelum terbenam; dan bertasbihlah (pula) pada waktu tengah malam dan di ujung siang hari, agar engkau merasa tenang"},{id:131,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0645\u064f\u062f\u0651\u064e\u0646\u0651\u064e \u0639\u064e\u064a\u06e1\u0646\u064e\u064a\u06e1\u0643\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0645\u064e\u062a\u0651\u064e\u0639\u06e1\u0646\u064e\u0627 \u0628\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u0657\u0627 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0632\u064e\u0647\u06e1\u0631\u064e\u0629\u064e \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u0650 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0644\u0650\u0646\u064e\u0641\u06e1\u062a\u0650\u0646\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u0650\u06da \u0648\u064e\u0631\u0650\u0632\u06e1\u0642\u064f \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u062e\u064e\u064a\u06e1\u0631\u065e \u0648\u064e\u0623\u064e\u0628\u06e1\u0642\u064e\u0649\u0670",translation:"Dan janganlah engkau belalakkan pandangan matamu kepada kenikmatan yang telah Kami berikan pada beberapa golongan dari mereka, (sebagai) bunga kehidupan dunia, agar Kami uji mereka dengan (kesenangan) itu. Karunia Tuhanmu lebih baik dan lebih kekal"},{id:132,text:"\u0648\u064e\u0623\u06e1\u0645\u064f\u0631\u06e1 \u0623\u064e\u0647\u06e1\u0644\u064e\u0643\u064e \u0628\u0650\u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u0650 \u0648\u064e\u0671\u0635\u06e1\u0637\u064e\u0628\u0650\u0631\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627\u06d6 \u0644\u064e\u0627 \u0646\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0643\u064e \u0631\u0650\u0632\u06e1\u0642\u0657\u0627\u06d6 \u0646\u0651\u064e\u062d\u06e1\u0646\u064f \u0646\u064e\u0631\u06e1\u0632\u064f\u0642\u064f\u0643\u064e\u06d7 \u0648\u064e\u0671\u0644\u06e1\u0639\u064e\u0670\u0642\u0650\u0628\u064e\u0629\u064f \u0644\u0650\u0644\u062a\u0651\u064e\u0642\u06e1\u0648\u064e\u0649\u0670",translation:"Dan perintahkanlah keluargamu melaksanakan salat dan sabar dalam mengerjakannya. Kami tidak meminta rezeki kepadamu, Kamilah yang memberi rezeki kepadamu. Dan akibat (yang baik di akhirat) adalah bagi orang yang bertakwa"},{id:133,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0648\u06e1\u0644\u064e\u0627 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u0646\u064e\u0627 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0629\u0656 \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0647\u0650\u06e6\u0653\u06da \u0623\u064e\u0648\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0623\u06e1\u062a\u0650\u0647\u0650\u0645 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0629\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0635\u0651\u064f\u062d\u064f\u0641\u0650 \u0671\u0644\u06e1\u0623\u064f\u0648\u0644\u064e\u0649\u0670",translation:"Dan mereka berkata, \"Mengapa dia tidak membawa tanda (bukti) kepada kami dari Tuhannya?\" Bukankah telah datang kepada mereka bukti (yang nyata) sebagaimana yang tersebut di dalam kitab-kitab yang dahulu"},{id:134,text:"\u0648\u064e\u0644\u064e\u0648\u06e1 \u0623\u064e\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u0647\u06e1\u0644\u064e\u0643\u06e1\u0646\u064e\u0670\u0647\u064f\u0645 \u0628\u0650\u0639\u064e\u0630\u064e\u0627\u0628\u0656 \u0645\u0651\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u06e6 \u0644\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0644\u064e\u0648\u06e1\u0644\u064e\u0627\u0653 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u062a\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u0657\u0627 \u0641\u064e\u0646\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064e \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0643\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650 \u0623\u064e\u0646 \u0646\u0651\u064e\u0630\u0650\u0644\u0651\u064e \u0648\u064e\u0646\u064e\u062e\u06e1\u0632\u064e\u0649\u0670",translation:"Dan kalau mereka Kami binasakan dengan suatu siksaan sebelumnya (Alquran diturunkan), tentulah mereka berkata, \"Ya Tuhan kami, mengapa tidak Engkau utus seorang rasul kepada kami, sehingga kami mengikuti ayat-ayat-Mu sebelum kami menjadi hina dan rendah"},{id:135,text:"\u0642\u064f\u0644\u06e1 \u0643\u064f\u0644\u0651\u065e \u0645\u0651\u064f\u062a\u064e\u0631\u064e\u0628\u0651\u0650\u0635\u065e \u0641\u064e\u062a\u064e\u0631\u064e\u0628\u0651\u064e\u0635\u064f\u0648\u0627\u0652\u06d6 \u0641\u064e\u0633\u064e\u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0645\u064e\u0646\u06e1 \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u0635\u0651\u0650\u0631\u064e\u0670\u0637\u0650 \u0671\u0644\u0633\u0651\u064e\u0648\u0650\u064a\u0651\u0650 \u0648\u064e\u0645\u064e\u0646\u0650 \u0671\u0647\u06e1\u062a\u064e\u062f\u064e\u0649\u0670",translation:"Katakanlah (Muhammad), \"Masing-masing (kita) menanti, maka nantikanlah olehmu! Dan kelak kamu akan mengetahui, siapa yang menempuh jalan yang lurus, dan siapa yang telah mendapat petunjuk"}]},{id:21,name:"\u0627\u0644\u0623\u0646\u0628\u064a\u0627\u0621",transliteration:"Al-Anbya",translation:"Para Nabi",type:"meccan",total_verses:112,verses:[{id:1,text:"\u0671\u0642\u06e1\u062a\u064e\u0631\u064e\u0628\u064e \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u062d\u0650\u0633\u064e\u0627\u0628\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u063a\u064e\u0641\u06e1\u0644\u064e\u0629\u0656 \u0645\u0651\u064f\u0639\u06e1\u0631\u0650\u0636\u064f\u0648\u0646\u064e",translation:"Telah semakin dekat kepada manusia perhitungan amal mereka, sedang mereka dalam keadaan lalai (dengan dunia), berpaling (dari akhirat)"},{id:2,text:"\u0645\u064e\u0627 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u0647\u0650\u0645 \u0645\u0651\u0650\u0646 \u0630\u0650\u0643\u06e1\u0631\u0656 \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0647\u0650\u0645 \u0645\u0651\u064f\u062d\u06e1\u062f\u064e\u062b\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0633\u06e1\u062a\u064e\u0645\u064e\u0639\u064f\u0648\u0647\u064f \u0648\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0644\u06e1\u0639\u064e\u0628\u064f\u0648\u0646\u064e",translation:"Setiap diturunkan kepada mereka ayat-ayat yang baru dari Tuhan, mereka mendengarkannya sambil bermain-main"},{id:3,text:"\u0644\u064e\u0627\u0647\u0650\u064a\u064e\u0629\u0657 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u06e1\u06d7 \u0648\u064e\u0623\u064e\u0633\u064e\u0631\u0651\u064f\u0648\u0627\u0652 \u0671\u0644\u0646\u0651\u064e\u062c\u06e1\u0648\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627\u0652 \u0647\u064e\u0644\u06e1 \u0647\u064e\u0670\u0630\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u064e\u0634\u064e\u0631\u065e \u0645\u0651\u0650\u062b\u06e1\u0644\u064f\u0643\u064f\u0645\u06e1\u06d6 \u0623\u064e\u0641\u064e\u062a\u064e\u0623\u06e1\u062a\u064f\u0648\u0646\u064e \u0671\u0644\u0633\u0651\u0650\u062d\u06e1\u0631\u064e \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u062a\u064f\u0628\u06e1\u0635\u0650\u0631\u064f\u0648\u0646\u064e",translation:"hati mereka dalam keadaan lalai. Dan orang-orang yang zalim itu merahasiakan pembicaraan mereka, \"(Orang) ini (Muhammad) tidak lain hanyalah seorang manusia (juga) seperti kamu. Apakah kamu menerimanya (sihir itu),529) padahal kamu menyaksikannya"},{id:4,text:"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0644\u064e \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u0650\u064a\u0639\u064f \u0671\u0644\u06e1\u0639\u064e\u0644\u0650\u064a\u0645\u064f",translation:"Dia (Muhammad) berkata, \"Tuhanku mengetahui (semua) perkataan di langit dan di bumi, dan Dia Maha Mendengar, Maha Mengetahui"},{id:5,text:"\u0628\u064e\u0644\u06e1 \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0636\u06e1\u063a\u064e\u0670\u062b\u064f \u0623\u064e\u062d\u06e1\u0644\u064e\u0670\u0645\u0650\u06ed \u0628\u064e\u0644\u0650 \u0671\u0641\u06e1\u062a\u064e\u0631\u064e\u0649\u0670\u0647\u064f \u0628\u064e\u0644\u06e1 \u0647\u064f\u0648\u064e \u0634\u064e\u0627\u0639\u0650\u0631\u065e \u0641\u064e\u0644\u06e1\u064a\u064e\u0623\u06e1\u062a\u0650\u0646\u064e\u0627 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0629\u0656 \u0643\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0631\u06e1\u0633\u0650\u0644\u064e \u0671\u0644\u06e1\u0623\u064e\u0648\u0651\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Bahkan mereka mengatakan, \"(Alquran itu buah) mimpi-mimpi yang kacau, atau hasil rekayasanya (Muhammad), atau bahkan dia hanya seorang penyair, cobalah dia datangkan kepada kita suatu tanda (bukti), seperti halnya rasul-rasul yang diutus terdahulu"},{id:6,text:"\u0645\u064e\u0627\u0653 \u0621\u064e\u0627\u0645\u064e\u0646\u064e\u062a\u06e1 \u0642\u064e\u0628\u06e1\u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0642\u064e\u0631\u06e1\u064a\u064e\u0629\u064d \u0623\u064e\u0647\u06e1\u0644\u064e\u0643\u06e1\u0646\u064e\u0670\u0647\u064e\u0627\u0653\u06d6 \u0623\u064e\u0641\u064e\u0647\u064f\u0645\u06e1 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Penduduk suatu negeri sebelum mereka, yang telah Kami binasakan, mereka itu tidak beriman (padahal telah Kami kirimkan bukti). Apakah mereka akan beriman"},{id:7,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0642\u064e\u0628\u06e1\u0644\u064e\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0631\u0650\u062c\u064e\u0627\u0644\u0657\u0627 \u0646\u0651\u064f\u0648\u062d\u0650\u064a\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1\u06d6 \u0641\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0647\u06e1\u0644\u064e \u0671\u0644\u0630\u0651\u0650\u0643\u06e1\u0631\u0650 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan Kami tidak mengutus (rasul-rasul) sebelum engkau (Muhammad), melainkan beberapa orang laki-laki yang Kami beri wahyu kepada mereka, maka tanyakanlah kepada orang yang berilmu, jika kamu tidak mengetahui"},{id:8,text:"\u0648\u064e\u0645\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u062c\u064e\u0633\u064e\u062f\u0657\u0627 \u0644\u0651\u064e\u0627 \u064a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f\u0648\u0646\u064e \u0671\u0644\u0637\u0651\u064e\u0639\u064e\u0627\u0645\u064e \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u062e\u064e\u0670\u0644\u0650\u062f\u0650\u064a\u0646\u064e",translation:"Dan Kami tidak menjadikan mereka (para rasul-rasul) suatu tubuh yang tidak memakan makanan, dan mereka tidak (pula) hidup kekal"},{id:9,text:"\u062b\u064f\u0645\u0651\u064e \u0635\u064e\u062f\u064e\u0642\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0648\u064e\u0639\u06e1\u062f\u064e \u0641\u064e\u0623\u064e\u0646\u062c\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0648\u064e\u0645\u064e\u0646 \u0646\u0651\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0648\u064e\u0623\u064e\u0647\u06e1\u0644\u064e\u0643\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0645\u064f\u0633\u06e1\u0631\u0650\u0641\u0650\u064a\u0646\u064e",translation:"Kemudian Kami tepati janji (yang telah Kami janjikan) kepada mereka. Maka Kami selamatkan mereka dan orang-orang yang Kami kehendaki, dan Kami binasakan orang-orang yang melampaui batas"},{id:10,text:"\u0644\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0643\u0650\u062a\u064e\u0670\u0628\u0657\u0627 \u0641\u0650\u064a\u0647\u0650 \u0630\u0650\u0643\u06e1\u0631\u064f\u0643\u064f\u0645\u06e1\u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Sungguh, telah Kami turunkan kepadamu satu Kitab (Alquran) yang di dalamnya terdapat peringatan bagimu. Maka apakah kamu tidak mengerti"},{id:11,text:"\u0648\u064e\u0643\u064e\u0645\u06e1 \u0642\u064e\u0635\u064e\u0645\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646 \u0642\u064e\u0631\u06e1\u064a\u064e\u0629\u0656 \u0643\u064e\u0627\u0646\u064e\u062a\u06e1 \u0638\u064e\u0627\u0644\u0650\u0645\u064e\u0629\u0657 \u0648\u064e\u0623\u064e\u0646\u0634\u064e\u0623\u06e1\u0646\u064e\u0627 \u0628\u064e\u0639\u06e1\u062f\u064e\u0647\u064e\u0627 \u0642\u064e\u0648\u06e1\u0645\u064b\u0627 \u0621\u064e\u0627\u062e\u064e\u0631\u0650\u064a\u0646\u064e",translation:"Dan berapa banyaknya (penduduk) negeri yang zalim telah Kami binasakan, dan Kami jadikan generasi yang lain setelah mereka itu (sebagai penggantinya)"},{id:12,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u062d\u064e\u0633\u0651\u064f\u0648\u0627\u0652 \u0628\u064e\u0623\u06e1\u0633\u064e\u0646\u064e\u0627\u0653 \u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1\u0647\u064e\u0627 \u064a\u064e\u0631\u06e1\u0643\u064f\u0636\u064f\u0648\u0646\u064e",translation:"Maka ketika mereka merasakan azab Kami, tiba-tiba mereka melarikan diri dari (negerinya) itu"},{id:13,text:"\u0644\u064e\u0627 \u062a\u064e\u0631\u06e1\u0643\u064f\u0636\u064f\u0648\u0627\u0652 \u0648\u064e\u0671\u0631\u06e1\u062c\u0650\u0639\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064e\u0627\u0653 \u0623\u064f\u062a\u06e1\u0631\u0650\u0641\u06e1\u062a\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u0650 \u0648\u064e\u0645\u064e\u0633\u064e\u0670\u0643\u0650\u0646\u0650\u0643\u064f\u0645\u06e1 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064f\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Janganlah kamu lari tergesa-gesa; kembalilah kamu kepada kesenangan hidupmu dan tempat-tempat kediamanmu (yang baik), agar kamu dapat ditanya"},{id:14,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u064a\u064e\u0670\u0648\u064e\u064a\u06e1\u0644\u064e\u0646\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0638\u064e\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Mereka berkata, \"Betapa celaka kami, sungguh, kami orang-orang yang zalim"},{id:15,text:"\u0641\u064e\u0645\u064e\u0627 \u0632\u064e\u0627\u0644\u064e\u062a \u062a\u0651\u0650\u0644\u06e1\u0643\u064e \u062f\u064e\u0639\u06e1\u0648\u064e\u0649\u0670\u0647\u064f\u0645\u06e1 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u062d\u064e\u0635\u0650\u064a\u062f\u064b\u0627 \u062e\u064e\u0670\u0645\u0650\u062f\u0650\u064a\u0646\u064e",translation:"Maka demikianlah keluhan mereka berkepanjangan, sehingga mereka Kami jadikan sebagai tanaman yang telah dituai, yang tidak dapat hidup lagi"},{id:16,text:"\u0648\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u06e1\u0646\u064e\u0627 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u064e \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0644\u064e\u0670\u0639\u0650\u0628\u0650\u064a\u0646\u064e",translation:"Dan Kami tidak menciptakan langit dan bumi dan segala apa yang ada di antara keduanya dengan main-main"},{id:17,text:"\u0644\u064e\u0648\u06e1 \u0623\u064e\u0631\u064e\u062f\u06e1\u0646\u064e\u0627\u0653 \u0623\u064e\u0646 \u0646\u0651\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064e \u0644\u064e\u0647\u06e1\u0648\u0657\u0627 \u0644\u0651\u064e\u0671\u062a\u0651\u064e\u062e\u064e\u0630\u06e1\u0646\u064e\u0670\u0647\u064f \u0645\u0650\u0646 \u0644\u0651\u064e\u062f\u064f\u0646\u0651\u064e\u0627\u0653 \u0625\u0650\u0646 \u0643\u064f\u0646\u0651\u064e\u0627 \u0641\u064e\u0670\u0639\u0650\u0644\u0650\u064a\u0646\u064e",translation:"Seandainya Kami hendak membuat suatu permainan (istri dan anak), tentulah Kami membuatnya dari sisi Kami,530) jika Kami benar-benar menghendaki berbuat demikian"},{id:18,text:"\u0628\u064e\u0644\u06e1 \u0646\u064e\u0642\u06e1\u0630\u0650\u0641\u064f \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0628\u064e\u0670\u0637\u0650\u0644\u0650 \u0641\u064e\u064a\u064e\u062f\u06e1\u0645\u064e\u063a\u064f\u0647\u064f\u06e5 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0648\u064e \u0632\u064e\u0627\u0647\u0650\u0642\u065e\u06da \u0648\u064e\u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0648\u064e\u064a\u06e1\u0644\u064f \u0645\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0635\u0650\u0641\u064f\u0648\u0646\u064e",translation:"Sebenarnya Kami melemparkan yang hak (kebenaran) kepada yang batil (tidak benar) lalu yang hak itu menghancurkannya, maka seketika itu (yang batil) lenyap. Dan celaka kamu karena kamu menyifati (Allah dengan sifat-sifat yang tidak pantas bagi-Nya)"},{id:19,text:"\u0648\u064e\u0644\u064e\u0647\u064f\u06e5 \u0645\u064e\u0646 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06da \u0648\u064e\u0645\u064e\u0646\u06e1 \u0639\u0650\u0646\u062f\u064e\u0647\u064f\u06e5 \u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u0650\u0631\u064f\u0648\u0646\u064e \u0639\u064e\u0646\u06e1 \u0639\u0650\u0628\u064e\u0627\u062f\u064e\u062a\u0650\u0647\u0650\u06e6 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u062d\u06e1\u0633\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Dan milik-Nya siapa yang di langit dan di bumi. Dan (malaikat-malaikat) yang di sisi-Nya, tidak mempunyai rasa angkuh untuk menyembah-Nya dan tidak (pula) merasa letih"},{id:20,text:"\u064a\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u064f\u0648\u0646\u064e \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u064e \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u0644\u064e\u0627 \u064a\u064e\u0641\u06e1\u062a\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Mereka (malaikat-malaikat) bertasbih tidak henti-hentinya malam dan siang"},{id:21,text:"\u0623\u064e\u0645\u0650 \u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0653\u0627\u0652 \u0621\u064e\u0627\u0644\u0650\u0647\u064e\u0629\u0657 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0647\u064f\u0645\u06e1 \u064a\u064f\u0646\u0634\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Apakah mereka mengambil tuhan-tuhan dari bumi, yang dapat menghidupkan (orang-orang yang mati)"},{id:22,text:"\u0644\u064e\u0648\u06e1 \u0643\u064e\u0627\u0646\u064e \u0641\u0650\u064a\u0647\u0650\u0645\u064e\u0627\u0653 \u0621\u064e\u0627\u0644\u0650\u0647\u064e\u0629\u064c \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0641\u064e\u0633\u064e\u062f\u064e\u062a\u064e\u0627\u06da \u0641\u064e\u0633\u064f\u0628\u06e1\u062d\u064e\u0670\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0631\u064e\u0628\u0651\u0650 \u0671\u0644\u06e1\u0639\u064e\u0631\u06e1\u0634\u0650 \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064e\u0635\u0650\u0641\u064f\u0648\u0646\u064e",translation:"Seandainya pada keduanya (di langit dan di bumi) ada tuhan-tuhan selain Allah, tentu keduanya telah binasa. Mahasuci Allah yang memiliki Arasy, dari apa yang mereka sifatkan"},{id:23,text:"\u0644\u064e\u0627 \u064a\u064f\u0633\u06e1\u0640\u0654\u064e\u0644\u064f \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064e\u0641\u06e1\u0639\u064e\u0644\u064f \u0648\u064e\u0647\u064f\u0645\u06e1 \u064a\u064f\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dia (Allah) tidak ditanya tentang apa yang dikerjakan, tetapi merekalah yang akan ditanya"},{id:24,text:"\u0623\u064e\u0645\u0650 \u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u06e6\u0653 \u0621\u064e\u0627\u0644\u0650\u0647\u064e\u0629\u0657\u06d6 \u0642\u064f\u0644\u06e1 \u0647\u064e\u0627\u062a\u064f\u0648\u0627\u0652 \u0628\u064f\u0631\u06e1\u0647\u064e\u0670\u0646\u064e\u0643\u064f\u0645\u06e1\u06d6 \u0647\u064e\u0670\u0630\u064e\u0627 \u0630\u0650\u0643\u06e1\u0631\u064f \u0645\u064e\u0646 \u0645\u0651\u064e\u0639\u0650\u064a\u064e \u0648\u064e\u0630\u0650\u0643\u06e1\u0631\u064f \u0645\u064e\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u064a\u06da \u0628\u064e\u0644\u06e1 \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064f\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064e\u06d6 \u0641\u064e\u0647\u064f\u0645 \u0645\u0651\u064f\u0639\u06e1\u0631\u0650\u0636\u064f\u0648\u0646\u064e",translation:"Atau apakah mereka mengambil tuhan-tuhan selain Dia? Katakanlah (Muhammad), \"Kemukakanlah alasan-alasanmu! (Alquran) ini adalah peringatan bagi orang yang bersamaku, dan peringatan bagi orang sebelumku.\" Tetapi kebanyakan mereka tidak mengetahui yang hak (kebenaran), karena itu mereka berpaling"},{id:25,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064e \u0645\u0650\u0646 \u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0646\u064f\u0648\u062d\u0650\u064a\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646\u064e\u0627\u06e0 \u0641\u064e\u0671\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0646\u0650",translation:"Dan Kami tidak mengutus seorang rasul pun sebelum engkau (Muhammad), melainkan Kami wahyukan kepadanya, \"bahwa tidak ada tuhan (yang berhak disembah) selain Aku, maka sembahlah Aku"},{id:26,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064e \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u064f \u0648\u064e\u0644\u064e\u062f\u0657\u0627\u06d7 \u0633\u064f\u0628\u06e1\u062d\u064e\u0670\u0646\u064e\u0647\u064f\u06e5\u06da \u0628\u064e\u0644\u06e1 \u0639\u0650\u0628\u064e\u0627\u062f\u065e \u0645\u0651\u064f\u0643\u06e1\u0631\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan mereka berkata, \"Tuhan Yang Maha Pengasih telah menjadikan (malaikat) sebagai anak.\" Mahasuci Dia. Sebenarnya mereka (para malaikat itu) adalah hamba-hamba yang dimuliakan"},{id:27,text:"\u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u0628\u0650\u0642\u064f\u0648\u0646\u064e\u0647\u064f\u06e5 \u0628\u0650\u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0644\u0650 \u0648\u064e\u0647\u064f\u0645 \u0628\u0650\u0623\u064e\u0645\u06e1\u0631\u0650\u0647\u0650\u06e6 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"mereka tidak berbicara mendahului-Nya dan mereka mengerjakan perintah-perintah-Nya"},{id:28,text:"\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u0647\u0650\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u06e1\u0641\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0634\u06e1\u0641\u064e\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0644\u0650\u0645\u064e\u0646\u0650 \u0671\u0631\u06e1\u062a\u064e\u0636\u064e\u0649\u0670 \u0648\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u062e\u064e\u0634\u06e1\u064a\u064e\u062a\u0650\u0647\u0650\u06e6 \u0645\u064f\u0634\u06e1\u0641\u0650\u0642\u064f\u0648\u0646\u064e",translation:"Dia (Allah) mengetahui segala sesuatu yang dihadapan mereka (malaikat) dan yang dibelakang mereka, dan mereka tidak memberi syafaat melainkan kepada orang yang diridai (Allah), dan mereka selalu berhati-hati karena takut kepada-Nya"},{id:29,text:"\u06de\u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0642\u064f\u0644\u06e1 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u065e \u0645\u0651\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u06e6 \u0641\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u062c\u06e1\u0632\u0650\u064a\u0647\u0650 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e\u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u062c\u06e1\u0632\u0650\u064a \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dan barang siapa di antara mereka berkata, \"Sungguh, aku adalah tuhan selain Allah,\" maka orang itu Kami beri balasan dengan Jahanam. Demikianlah Kami memberikan balasan kepada orang-orang yang zalim"},{id:30,text:"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0631\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0643\u064e\u0627\u0646\u064e\u062a\u064e\u0627 \u0631\u064e\u062a\u06e1\u0642\u0657\u0627 \u0641\u064e\u0641\u064e\u062a\u064e\u0642\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u064e\u0627\u06d6 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064e\u0627\u0653\u0621\u0650 \u0643\u064f\u0644\u0651\u064e \u0634\u064e\u064a\u06e1\u0621\u064d \u062d\u064e\u064a\u0651\u064d\u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Dan apakah orang-orang kafir tidak mengetahui bahwa langit dan bumi keduanya dahulu menyatu, kemudian Kami pisahkan antara keduanya; dan Kami jadikan segala sesuatu yang hidup berasal dari air; maka mengapa mereka tidak beriman"},{id:31,text:"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0631\u064e\u0648\u064e\u0670\u0633\u0650\u064a\u064e \u0623\u064e\u0646 \u062a\u064e\u0645\u0650\u064a\u062f\u064e \u0628\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0641\u0650\u062c\u064e\u0627\u062c\u0657\u0627 \u0633\u064f\u0628\u064f\u0644\u0657\u0627 \u0644\u0651\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0647\u06e1\u062a\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Dan Kami telah menjadikan di bumi ini gunung-gunung yang kokoh agar ia (tidak) guncang bersama mereka, dan Kami jadikan (pula) di sana jalan-jalan yang luas, agar mereka mendapat petunjuk"},{id:32,text:"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u064e \u0633\u064e\u0642\u06e1\u0641\u0657\u0627 \u0645\u0651\u064e\u062d\u06e1\u0641\u064f\u0648\u0638\u0657\u0627\u06d6 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0646\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0647\u064e\u0627 \u0645\u064f\u0639\u06e1\u0631\u0650\u0636\u064f\u0648\u0646\u064e",translation:"Dan Kami menjadikan langit sebagai atap yang terpelihara, namun mereka tetap berpaling dari tanda-tanda (kebesaran Allah) itu (matahari, bulan, angin, awan, dan lain-lain)"},{id:33,text:"\u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u064e \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u0648\u064e\u0671\u0644\u0634\u0651\u064e\u0645\u06e1\u0633\u064e \u0648\u064e\u0671\u0644\u06e1\u0642\u064e\u0645\u064e\u0631\u064e\u06d6 \u0643\u064f\u0644\u0651\u065e \u0641\u0650\u064a \u0641\u064e\u0644\u064e\u0643\u0656 \u064a\u064e\u0633\u06e1\u0628\u064e\u062d\u064f\u0648\u0646\u064e",translation:"Dan Dialah yang telah menciptakan malam dan siang, matahari dan bulan. Masing-masing beredar pada garis edarnya"},{id:34,text:"\u0648\u064e\u0645\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0644\u0650\u0628\u064e\u0634\u064e\u0631\u0656 \u0645\u0651\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064e \u0671\u0644\u06e1\u062e\u064f\u0644\u06e1\u062f\u064e\u06d6 \u0623\u064e\u0641\u064e\u0625\u0650\u064a\u0652\u0646 \u0645\u0651\u0650\u062a\u0651\u064e \u0641\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u062e\u064e\u0670\u0644\u0650\u062f\u064f\u0648\u0646\u064e",translation:"Dan Kami tidak menjadikan hidup abadi bagi seorang manusia sebelum engkau (Muhammad); maka jika engkau wafat, apakah mereka akan kekal"},{id:35,text:"\u0643\u064f\u0644\u0651\u064f \u0646\u064e\u0641\u06e1\u0633\u0656 \u0630\u064e\u0627\u0653\u0626\u0650\u0642\u064e\u0629\u064f \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u0650\u06d7 \u0648\u064e\u0646\u064e\u0628\u06e1\u0644\u064f\u0648\u0643\u064f\u0645 \u0628\u0650\u0671\u0644\u0634\u0651\u064e\u0631\u0651\u0650 \u0648\u064e\u0671\u0644\u06e1\u062e\u064e\u064a\u06e1\u0631\u0650 \u0641\u0650\u062a\u06e1\u0646\u064e\u0629\u0657\u06d6 \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u062a\u064f\u0631\u06e1\u062c\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Setiap yang bernyawa akan merasakan mati. Kami akan menguji kamu dengan keburukan dan kebaikan sebagai cobaan. Dan kamu akan dikembalikan hanya kepada Kami"},{id:36,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0631\u064e\u0621\u064e\u0627\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646 \u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0646\u064e\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0632\u064f\u0648\u064b\u0627 \u0623\u064e\u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064e\u0630\u06e1\u0643\u064f\u0631\u064f \u0621\u064e\u0627\u0644\u0650\u0647\u064e\u062a\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0647\u064f\u0645 \u0628\u0650\u0630\u0650\u0643\u06e1\u0631\u0650 \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u0650 \u0647\u064f\u0645\u06e1 \u0643\u064e\u0670\u0641\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Dan apabila orang-orang kafir itu melihat engkau (Muhammad), mereka hanya memperlakukan engkau menjadi bahan ejekan. (Mereka mengatakan), \"Apakah ini orang yang mencela tuhan-tuhanmu?\" Padahal mereka orang yang ingkar mengingat Allah Yang Maha Pengasih"},{id:37,text:"\u062e\u064f\u0644\u0650\u0642\u064e \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064f \u0645\u0650\u0646\u06e1 \u0639\u064e\u062c\u064e\u0644\u0656\u06da \u0633\u064e\u0623\u064f\u0648\u0652\u0631\u0650\u064a\u0643\u064f\u0645\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u064a \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0633\u06e1\u062a\u064e\u0639\u06e1\u062c\u0650\u0644\u064f\u0648\u0646\u0650",translation:"Manusia diciptakan (bersifat) tergesa-gesa. Kelak akan Aku perlihatkan kepadamu tanda-tanda (kekuasaan)-Ku. Maka janganlah kamu meminta Aku menyegerakannya"},{id:38,text:"\u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0645\u064e\u062a\u064e\u0649\u0670 \u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u06e1\u0648\u064e\u0639\u06e1\u062f\u064f \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0635\u064e\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Dan mereka berkata, \"Kapankah janji itu (akan datang), jika kamu orang yang benar"},{id:39,text:"\u0644\u064e\u0648\u06e1 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u062d\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u0643\u064f\u0641\u0651\u064f\u0648\u0646\u064e \u0639\u064e\u0646 \u0648\u064f\u062c\u064f\u0648\u0647\u0650\u0647\u0650\u0645\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u064e \u0648\u064e\u0644\u064e\u0627 \u0639\u064e\u0646 \u0638\u064f\u0647\u064f\u0648\u0631\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u06e1 \u064a\u064f\u0646\u0635\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Seandainya orang kafir itu mengetahui, ketika mereka itu tidak mampu mengelakkan api neraka dari wajah dan punggung mereka, sedang mereka tidak mendapat pertolongan (tentulah mereka tidak meminta disegerakan)"},{id:40,text:"\u0628\u064e\u0644\u06e1 \u062a\u064e\u0623\u06e1\u062a\u0650\u064a\u0647\u0650\u0645 \u0628\u064e\u063a\u06e1\u062a\u064e\u0629\u0657 \u0641\u064e\u062a\u064e\u0628\u06e1\u0647\u064e\u062a\u064f\u0647\u064f\u0645\u06e1 \u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u064e \u0631\u064e\u062f\u0651\u064e\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u06e1 \u064a\u064f\u0646\u0638\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Sebenarnya (hari Kiamat) itu akan datang kepada mereka secara tiba-tiba, lalu mereka menjadi panik; maka mereka tidak sanggup menolaknya dan tidak (pula) diberi penangguhan (waktu)"},{id:41,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0650 \u0671\u0633\u06e1\u062a\u064f\u0647\u06e1\u0632\u0650\u0626\u064e \u0628\u0650\u0631\u064f\u0633\u064f\u0644\u0656 \u0645\u0651\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064e \u0641\u064e\u062d\u064e\u0627\u0642\u064e \u0628\u0650\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0633\u064e\u062e\u0650\u0631\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6 \u064a\u064e\u0633\u06e1\u062a\u064e\u0647\u06e1\u0632\u0650\u0621\u064f\u0648\u0646\u064e",translation:"Dan sungguh, rasul-rasul sebelum engkau (Muhammad) pun telah diperolok-olokkan, maka turunlah (siksaan) kepada orang-orang yang mencemoohkan apa (rasul-rasul) yang selalu mereka perolok-olokkan"},{id:42,text:"\u0642\u064f\u0644\u06e1 \u0645\u064e\u0646 \u064a\u064e\u0643\u06e1\u0644\u064e\u0624\u064f\u0643\u064f\u0645 \u0628\u0650\u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u0650 \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u0645\u0650\u0646\u064e \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u0650\u06da \u0628\u064e\u0644\u06e1 \u0647\u064f\u0645\u06e1 \u0639\u064e\u0646 \u0630\u0650\u0643\u06e1\u0631\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645 \u0645\u0651\u064f\u0639\u06e1\u0631\u0650\u0636\u064f\u0648\u0646\u064e",translation:"Katakanlah, \"Siapakah yang akan menjaga kamu pada waktu malam dan siang dari (siksaan) Allah Yang Maha Pengasih?\" Tetapi mereka enggan mengingat Tuhan mereka"},{id:43,text:"\u0623\u064e\u0645\u06e1 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0621\u064e\u0627\u0644\u0650\u0647\u064e\u0629\u065e \u062a\u064e\u0645\u06e1\u0646\u064e\u0639\u064f\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0646\u064e\u0627\u06da \u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u064e \u0646\u064e\u0635\u06e1\u0631\u064e \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u0651\u064e\u0627 \u064a\u064f\u0635\u06e1\u062d\u064e\u0628\u064f\u0648\u0646\u064e",translation:"Ataukah mereka mempunyai tuhan-tuhan yang dapat memelihara mereka dari (azab) Kami? Tuhan-tuhan mereka itu tidak sanggup menolong diri mereka sendiri dan tidak (pula) mereka dilindungi dari (azab) Kami"},{id:44,text:"\u0628\u064e\u0644\u06e1 \u0645\u064e\u062a\u0651\u064e\u0639\u06e1\u0646\u064e\u0627 \u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650 \u0648\u064e\u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u06e1 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0637\u064e\u0627\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u064f \u0671\u0644\u06e1\u0639\u064f\u0645\u064f\u0631\u064f\u06d7 \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0631\u064e\u0648\u06e1\u0646\u064e \u0623\u064e\u0646\u0651\u064e\u0627 \u0646\u064e\u0623\u06e1\u062a\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0646\u064e\u0646\u0642\u064f\u0635\u064f\u0647\u064e\u0627 \u0645\u0650\u0646\u06e1 \u0623\u064e\u0637\u06e1\u0631\u064e\u0627\u0641\u0650\u0647\u064e\u0627\u0653\u06da \u0623\u064e\u0641\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u063a\u064e\u0670\u0644\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Sebenarnya Kami telah memberi mereka dan nenek moyang mereka kenikmatan (hidup di dunia) hingga panjang usia mereka. Maka apakah mereka tidak melihat bahwa Kami mendatangi negeri (yang berada di bawah kekuasaan orang kafir), lalu Kami kurangi luasnya dari ujung-ujung negeri. Apakah mereka yang menang"},{id:45,text:"\u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0646\u0630\u0650\u0631\u064f\u0643\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0648\u064e\u062d\u06e1\u064a\u0650\u06da \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u0645\u064e\u0639\u064f \u0671\u0644\u0635\u0651\u064f\u0645\u0651\u064f \u0671\u0644\u062f\u0651\u064f\u0639\u064e\u0627\u0653\u0621\u064e \u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0627 \u064a\u064f\u0646\u0630\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Katakanlah (Muhammad), \"Sesungguhnya aku hanya memberimu peringatan sesuai dengan wahyu.\" Tetapi orang tuli tidak mendengar seruan apabila mereka diberi peringatan"},{id:46,text:"\u0648\u064e\u0644\u064e\u0626\u0650\u0646 \u0645\u0651\u064e\u0633\u0651\u064e\u062a\u06e1\u0647\u064f\u0645\u06e1 \u0646\u064e\u0641\u06e1\u062d\u064e\u0629\u065e \u0645\u0651\u0650\u0646\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0644\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0646\u0651\u064e \u064a\u064e\u0670\u0648\u064e\u064a\u06e1\u0644\u064e\u0646\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0638\u064e\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dan jika mereka ditimpa sedikit saja azab Tuhanmu, pastilah mereka berkata, \"Celakalah kami! Sesungguhnya kami termasuk orang yang selalu menzalimi (diri sendiri)"},{id:47,text:"\u0648\u064e\u0646\u064e\u0636\u064e\u0639\u064f \u0671\u0644\u06e1\u0645\u064e\u0648\u064e\u0670\u0632\u0650\u064a\u0646\u064e \u0671\u0644\u06e1\u0642\u0650\u0633\u06e1\u0637\u064e \u0644\u0650\u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u0641\u064e\u0644\u064e\u0627 \u062a\u064f\u0638\u06e1\u0644\u064e\u0645\u064f \u0646\u064e\u0641\u06e1\u0633\u065e \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627\u06d6 \u0648\u064e\u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u062b\u06e1\u0642\u064e\u0627\u0644\u064e \u062d\u064e\u0628\u0651\u064e\u0629\u0656 \u0645\u0651\u0650\u0646\u06e1 \u062e\u064e\u0631\u06e1\u062f\u064e\u0644\u064d \u0623\u064e\u062a\u064e\u064a\u06e1\u0646\u064e\u0627 \u0628\u0650\u0647\u064e\u0627\u06d7 \u0648\u064e\u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0646\u064e\u0627 \u062d\u064e\u0670\u0633\u0650\u0628\u0650\u064a\u0646\u064e",translation:"Dan Kami akan memasang timbangan yang tepat pada hari Kiamat, maka tidak seorang pun dirugikan walau sedikit; sekali pun hanya seberat biji sawi, pasti Kami mendatangkannya (pahala). Dan cukuplah Kami yang membuat perhitungan"},{id:48,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u0647\u064e\u0670\u0631\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0641\u064f\u0631\u06e1\u0642\u064e\u0627\u0646\u064e \u0648\u064e\u0636\u0650\u064a\u064e\u0627\u0653\u0621\u0657 \u0648\u064e\u0630\u0650\u0643\u06e1\u0631\u0657\u0627 \u0644\u0651\u0650\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",translation:"Dan sungguh, Kami telah memberikan kepada Musa dan Harun, Furqan (Kitab Taurat) dan penerangan serta pelajaran bagi orang-orang yang bertakwa"},{id:49,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062e\u06e1\u0634\u064e\u0648\u06e1\u0646\u064e \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u0628\u0650 \u0648\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u0650 \u0645\u064f\u0634\u06e1\u0641\u0650\u0642\u064f\u0648\u0646\u064e",translation:"(yaitu) orang-orang yang takut (azab) Tuhannya, sekalipun mereka tidak melihat-Nya, dan mereka merasa takut akan (tibanya) hari Kiamat"},{id:50,text:"\u0648\u064e\u0647\u064e\u0670\u0630\u064e\u0627 \u0630\u0650\u0643\u06e1\u0631\u065e \u0645\u0651\u064f\u0628\u064e\u0627\u0631\u064e\u0643\u064c \u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f\u06da \u0623\u064e\u0641\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0644\u064e\u0647\u064f\u06e5 \u0645\u064f\u0646\u0643\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Dan ini (Alquran) adalah suatu peringatan yang mempunyai berkah yang telah Kami turunkan. Maka apakah kamu mengingkarinya"},{id:51,text:"\u06de\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064e \u0631\u064f\u0634\u06e1\u062f\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f \u0648\u064e\u0643\u064f\u0646\u0651\u064e\u0627 \u0628\u0650\u0647\u0650\u06e6 \u0639\u064e\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dan sungguh, sebelum dia (Musa dan Harun) telah Kami berikan kepada Ibrahim petunjuk, dan Kami telah mengetahui dia"},{id:52,text:"\u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0623\u064e\u0628\u0650\u064a\u0647\u0650 \u0648\u064e\u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u06e6 \u0645\u064e\u0627 \u0647\u064e\u0670\u0630\u0650\u0647\u0650 \u0671\u0644\u062a\u0651\u064e\u0645\u064e\u0627\u062b\u0650\u064a\u0644\u064f \u0671\u0644\u0651\u064e\u062a\u0650\u064a\u0653 \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0644\u064e\u0647\u064e\u0627 \u0639\u064e\u0670\u0643\u0650\u0641\u064f\u0648\u0646\u064e",translation:"(Ingatlah), ketika dia (Ibrahim) berkata kepada ayahnya dan kaumnya, \"Patung-patung apakah ini yang kamu tekun menyembahnya"},{id:53,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0648\u064e\u062c\u064e\u062f\u06e1\u0646\u064e\u0627\u0653 \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0621\u064e\u0646\u064e\u0627 \u0644\u064e\u0647\u064e\u0627 \u0639\u064e\u0670\u0628\u0650\u062f\u0650\u064a\u0646\u064e",translation:"Mereka menjawab, \"Kami mendapati nenek moyang kami menyembahnya"},{id:54,text:"\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0642\u064e\u062f\u06e1 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0648\u064e\u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0624\u064f\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0670\u0644\u0656 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u0656",translation:"Dia (Ibrahim) berkata, \"Sesungguhnya kamu dan nenek moyang kamu berada dalam kesesatan yang nyata"},{id:55,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u062c\u0650\u0626\u06e1\u062a\u064e\u0646\u064e\u0627 \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0623\u064e\u0645\u06e1 \u0623\u064e\u0646\u062a\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0640\u0670\u0639\u0650\u0628\u0650\u064a\u0646\u064e",translation:"Mereka berkata, \"Apakah engkau datang kepada kami membawa kebenaran atau engkau main-main"},{id:56,text:"\u0642\u064e\u0627\u0644\u064e \u0628\u064e\u0644 \u0631\u0651\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u06e1 \u0631\u064e\u0628\u0651\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0641\u064e\u0637\u064e\u0631\u064e\u0647\u064f\u0646\u0651\u064e \u0648\u064e\u0623\u064e\u0646\u064e\u0627\u06e0 \u0639\u064e\u0644\u064e\u0649\u0670 \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0634\u0651\u064e\u0640\u0670\u0647\u0650\u062f\u0650\u064a\u0646\u064e",translation:"Dia (Ibrahim) menjawab, \"Sebenarnya Tuhan kamu ialah Tuhan (pemilik) langit dan bumi; (Dialah) yang telah menciptakannya; dan aku termasuk orang yang dapat bersaksi atas itu"},{id:57,text:"\u0648\u064e\u062a\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0623\u064e\u0643\u0650\u064a\u062f\u064e\u0646\u0651\u064e \u0623\u064e\u0635\u06e1\u0646\u064e\u0670\u0645\u064e\u0643\u064f\u0645 \u0628\u064e\u0639\u06e1\u062f\u064e \u0623\u064e\u0646 \u062a\u064f\u0648\u064e\u0644\u0651\u064f\u0648\u0627\u0652 \u0645\u064f\u062f\u06e1\u0628\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan demi Allah, sungguh, aku akan melakukan tipu daya terhadap berhala-berhalamu setelah kamu pergi meninggalkannya"},{id:58,text:"\u0641\u064e\u062c\u064e\u0639\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u062c\u064f\u0630\u064e\u0670\u0630\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064e\u0628\u0650\u064a\u0631\u0657\u0627 \u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u064a\u064e\u0631\u06e1\u062c\u0650\u0639\u064f\u0648\u0646\u064e",translation:"Maka dia (Ibrahim) menghancurkan (berhala-berhala itu) berkeping-keping, kecuali yang terbesar (induknya); agar mereka kembali (untuk bertanya) kepadanya"},{id:59,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0645\u064e\u0646 \u0641\u064e\u0639\u064e\u0644\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0628\u0650\u0640\u0654\u064e\u0627\u0644\u0650\u0647\u064e\u062a\u0650\u0646\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Mereka berkata, \"Siapakah yang melakukan (perbuatan) ini terhadap tuhan-tuhan kami? Sungguh, dia termasuk orang yang zalim"},{id:60,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0633\u064e\u0645\u0650\u0639\u06e1\u0646\u064e\u0627 \u0641\u064e\u062a\u0657\u0649 \u064a\u064e\u0630\u06e1\u0643\u064f\u0631\u064f\u0647\u064f\u0645\u06e1 \u064a\u064f\u0642\u064e\u0627\u0644\u064f \u0644\u064e\u0647\u064f\u06e5\u0653 \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064f",translation:"Mereka (yang lain) berkata, \"Kami mendengar ada seorang pemuda yang mencela (berhala-berhala ini), namanya Ibrahim"},{id:61,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0641\u064e\u0623\u06e1\u062a\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6 \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0639\u06e1\u064a\u064f\u0646\u0650 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0634\u06e1\u0647\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Mereka berkata, \"(Kalau demikian) bawalah dia dengan diperlihatkan kepada orang banyak, agar mereka menyaksikan"},{id:62,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0621\u064e\u0623\u064e\u0646\u062a\u064e \u0641\u064e\u0639\u064e\u0644\u06e1\u062a\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0628\u0650\u0640\u0654\u064e\u0627\u0644\u0650\u0647\u064e\u062a\u0650\u0646\u064e\u0627 \u064a\u064e\u0640\u0670\u0653\u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064f",translation:"Mereka bertanya, \"Apakah engkau yang melakukan (perbuatan) ini terhadap tuhan-tuhan kami, wahai Ibrahim"},{id:63,text:"\u0642\u064e\u0627\u0644\u064e \u0628\u064e\u0644\u06e1 \u0641\u064e\u0639\u064e\u0644\u064e\u0647\u064f\u06e5 \u0643\u064e\u0628\u0650\u064a\u0631\u064f\u0647\u064f\u0645\u06e1 \u0647\u064e\u0670\u0630\u064e\u0627 \u0641\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0648\u0647\u064f\u0645\u06e1 \u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0646\u0637\u0650\u0642\u064f\u0648\u0646\u064e",translation:"Dia (Ibrahim) menjawab, \"Sebenarnya (patung) besar itu yang melakukannya, maka tanyakanlah kepada mereka, jika mereka dapat berbicara"},{id:64,text:"\u0641\u064e\u0631\u064e\u062c\u064e\u0639\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u06e1 \u0641\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u0646\u062a\u064f\u0645\u064f \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Maka mereka kembali pada kesadaran mereka dan berkata, \"Sesungguhnya kamulah yang menzalimi (diri sendiri)"},{id:65,text:"\u062b\u064f\u0645\u0651\u064e \u0646\u064f\u0643\u0650\u0633\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064f\u0621\u064f\u0648\u0633\u0650\u0647\u0650\u0645\u06e1 \u0644\u064e\u0642\u064e\u062f\u06e1 \u0639\u064e\u0644\u0650\u0645\u06e1\u062a\u064e \u0645\u064e\u0627 \u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650 \u064a\u064e\u0646\u0637\u0650\u0642\u064f\u0648\u0646\u064e",translation:"Kemudian mereka menundukkan kepala (lalu berkata), \"Engkau (Ibrahim) pasti tahu bahwa (berhala-berhala) itu tidak dapat berbicara"},{id:66,text:"\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0641\u064e\u062a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0646\u0641\u064e\u0639\u064f\u0643\u064f\u0645\u06e1 \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0636\u064f\u0631\u0651\u064f\u0643\u064f\u0645\u06e1",translation:"Dia (Ibrahim) berkata, \"Mengapa kamu menyembah selain Allah, sesuatu yang tidak dapat memberi manfaat sedikit pun, dan tidak (pula) mendatangkan mudarat kepada kamu"},{id:67,text:"\u0623\u064f\u0641\u0651\u0656 \u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Celakalah kamu dan apa yang kamu sembah selain Allah! Tidakkah kamu mengerti"},{id:68,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u062d\u064e\u0631\u0651\u0650\u0642\u064f\u0648\u0647\u064f \u0648\u064e\u0671\u0646\u0635\u064f\u0631\u064f\u0648\u0653\u0627\u0652 \u0621\u064e\u0627\u0644\u0650\u0647\u064e\u062a\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0641\u064e\u0670\u0639\u0650\u0644\u0650\u064a\u0646\u064e",translation:"Mereka berkata, \"Bakarlah dia dan bantulah tuhan-tuhan kamu, jika kamu benar-benar hendak berbuat"},{id:69,text:"\u0642\u064f\u0644\u06e1\u0646\u064e\u0627 \u064a\u064e\u0670\u0646\u064e\u0627\u0631\u064f \u0643\u064f\u0648\u0646\u0650\u064a \u0628\u064e\u0631\u06e1\u062f\u0657\u0627 \u0648\u064e\u0633\u064e\u0644\u064e\u0670\u0645\u064b\u0627 \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064e",translation:"Kami (Allah) berfirman, \"Wahai api! Jadilah kamu dingin, dan penyelamat bagi Ibrahim"},{id:70,text:"\u0648\u064e\u0623\u064e\u0631\u064e\u0627\u062f\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6 \u0643\u064e\u064a\u06e1\u062f\u0657\u0627 \u0641\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u062e\u06e1\u0633\u064e\u0631\u0650\u064a\u0646\u064e",translation:"dan mereka hendak berbuat jahat terhadap Ibrahim, maka Kami menjadikan mereka itu orang-orang yang paling rugi"},{id:71,text:"\u0648\u064e\u0646\u064e\u062c\u0651\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f \u0648\u064e\u0644\u064f\u0648\u0637\u064b\u0627 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0671\u0644\u0651\u064e\u062a\u0650\u064a \u0628\u064e\u0670\u0631\u064e\u0643\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0644\u0650\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Dan Kami selamatkan dia (Ibrahim) dan Lu\u1e6d ke suatu negeri yang telah Kami berkahi untuk seluruh alam"},{id:72,text:"\u0648\u064e\u0648\u064e\u0647\u064e\u0628\u06e1\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u06e5\u0653 \u0625\u0650\u0633\u06e1\u062d\u064e\u0670\u0642\u064e \u0648\u064e\u064a\u064e\u0639\u06e1\u0642\u064f\u0648\u0628\u064e \u0646\u064e\u0627\u0641\u0650\u0644\u064e\u0629\u0657\u06d6 \u0648\u064e\u0643\u064f\u0644\u0651\u0657\u0627 \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0635\u064e\u0670\u0644\u0650\u062d\u0650\u064a\u0646\u064e",translation:"Dan Kami menganugerahkan kepadanya (Ibrahim) Ishak dan Yakub sebagai suatu anugerah. Dan masing-masing Kami jadikan orang yang saleh"},{id:73,text:"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0623\u064e\u0626\u0650\u0645\u0651\u064e\u0629\u0657 \u064a\u064e\u0647\u06e1\u062f\u064f\u0648\u0646\u064e \u0628\u0650\u0623\u064e\u0645\u06e1\u0631\u0650\u0646\u064e\u0627 \u0648\u064e\u0623\u064e\u0648\u06e1\u062d\u064e\u064a\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0641\u0650\u0639\u06e1\u0644\u064e \u0671\u0644\u06e1\u062e\u064e\u064a\u06e1\u0631\u064e\u0670\u062a\u0650 \u0648\u064e\u0625\u0650\u0642\u064e\u0627\u0645\u064e \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u0650 \u0648\u064e\u0625\u0650\u064a\u062a\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0632\u0651\u064e\u0643\u064e\u0648\u0670\u0629\u0650\u06d6 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0646\u064e\u0627 \u0639\u064e\u0670\u0628\u0650\u062f\u0650\u064a\u0646\u064e",translation:"Dan Kami menjadikan mereka itu sebagai pemimpin-pemimpin yang memberi petunjuk dengan perintah Kami, dan Kami wahyukan kepada mereka agar berbuat kebaikan, melaksanakan salat dan menunaikan zakat, dan hanya kepada Kami mereka menyembah"},{id:74,text:"\u0648\u064e\u0644\u064f\u0648\u0637\u064b\u0627 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f \u062d\u064f\u0643\u06e1\u0645\u0657\u0627 \u0648\u064e\u0639\u0650\u0644\u06e1\u0645\u0657\u0627 \u0648\u064e\u0646\u064e\u062c\u0651\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0642\u064e\u0631\u06e1\u064a\u064e\u0629\u0650 \u0671\u0644\u0651\u064e\u062a\u0650\u064a \u0643\u064e\u0627\u0646\u064e\u062a \u062a\u0651\u064e\u0639\u06e1\u0645\u064e\u0644\u064f \u0671\u0644\u06e1\u062e\u064e\u0628\u064e\u0640\u0670\u0653\u0626\u0650\u062b\u064e\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0642\u064e\u0648\u06e1\u0645\u064e \u0633\u064e\u0648\u06e1\u0621\u0656 \u0641\u064e\u0670\u0633\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Dan kepada Lu\u1e6d, Kami berikan hikmah dan ilmu, dan Kami selamatkan dia dari (azab yang telah menimpa penduduk) kota yang melakukan perbuatan keji.534) Sungguh, mereka orang-orang yang jahat lagi fasik"},{id:75,text:"\u0648\u064e\u0623\u064e\u062f\u06e1\u062e\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f \u0641\u0650\u064a \u0631\u064e\u062d\u06e1\u0645\u064e\u062a\u0650\u0646\u064e\u0627\u0653\u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u0650\u064a\u0646\u064e",translation:"dan Kami masukkan dia ke dalam rahmat Kami; sesungguhnya dia termasuk golongan orang yang saleh"},{id:76,text:"\u0648\u064e\u0646\u064f\u0648\u062d\u064b\u0627 \u0625\u0650\u0630\u06e1 \u0646\u064e\u0627\u062f\u064e\u0649\u0670 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f \u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u062c\u064e\u0628\u06e1\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u06e5 \u0641\u064e\u0646\u064e\u062c\u0651\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f \u0648\u064e\u0623\u064e\u0647\u06e1\u0644\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0643\u064e\u0631\u06e1\u0628\u0650 \u0671\u0644\u06e1\u0639\u064e\u0638\u0650\u064a\u0645\u0650",translation:"Dan (ingatlah kisah) Nuh, sebelum itu, ketika dia berdoa. Kami perkenankan (doa)nya, lalu Kami selamatkan dia bersama pengikutnya dari bencana yang besar"},{id:77,text:"\u0648\u064e\u0646\u064e\u0635\u064e\u0631\u06e1\u0646\u064e\u0670\u0647\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627\u0653\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0642\u064e\u0648\u06e1\u0645\u064e \u0633\u064e\u0648\u06e1\u0621\u0656 \u0641\u064e\u0623\u064e\u063a\u06e1\u0631\u064e\u0642\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0623\u064e\u062c\u06e1\u0645\u064e\u0639\u0650\u064a\u0646\u064e",translation:"Dan Kami menolongnya dari orang-orang yang telah mendustakan ayat-ayat Kami. Sesungguhnya mereka adalah orang-orang yang jahat, maka Kami tenggelamkan mereka semuanya"},{id:78,text:"\u0648\u064e\u062f\u064e\u0627\u0648\u064f\u06e5\u062f\u064e \u0648\u064e\u0633\u064f\u0644\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u064e \u0625\u0650\u0630\u06e1 \u064a\u064e\u062d\u06e1\u0643\u064f\u0645\u064e\u0627\u0646\u0650 \u0641\u0650\u064a \u0671\u0644\u06e1\u062d\u064e\u0631\u06e1\u062b\u0650 \u0625\u0650\u0630\u06e1 \u0646\u064e\u0641\u064e\u0634\u064e\u062a\u06e1 \u0641\u0650\u064a\u0647\u0650 \u063a\u064e\u0646\u064e\u0645\u064f \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u0650 \u0648\u064e\u0643\u064f\u0646\u0651\u064e\u0627 \u0644\u0650\u062d\u064f\u0643\u06e1\u0645\u0650\u0647\u0650\u0645\u06e1 \u0634\u064e\u0670\u0647\u0650\u062f\u0650\u064a\u0646\u064e",translation:"Dan (ingatlah kisah) Dawud dan Sulaiman, ketika keduanya memberikan keputusan mengenai ladang, karena (ladang itu) dirusak oleh kambing-kambing milik kaumnya. Dan Kami menyaksikan keputusan (yang diberikan) oleh mereka itu"},{id:79,text:"\u0641\u064e\u0641\u064e\u0647\u0651\u064e\u0645\u06e1\u0646\u064e\u0670\u0647\u064e\u0627 \u0633\u064f\u0644\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u064e\u06da \u0648\u064e\u0643\u064f\u0644\u0651\u064b\u0627 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0627 \u062d\u064f\u0643\u06e1\u0645\u0657\u0627 \u0648\u064e\u0639\u0650\u0644\u06e1\u0645\u0657\u0627\u06da \u0648\u064e\u0633\u064e\u062e\u0651\u064e\u0631\u06e1\u0646\u064e\u0627 \u0645\u064e\u0639\u064e \u062f\u064e\u0627\u0648\u064f\u06e5\u062f\u064e \u0671\u0644\u06e1\u062c\u0650\u0628\u064e\u0627\u0644\u064e \u064a\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u06e1\u0646\u064e \u0648\u064e\u0671\u0644\u0637\u0651\u064e\u064a\u06e1\u0631\u064e\u06da \u0648\u064e\u0643\u064f\u0646\u0651\u064e\u0627 \u0641\u064e\u0670\u0639\u0650\u0644\u0650\u064a\u0646\u064e",translation:"Maka Kami memberikan pengertian kepada Sulaiman (tentang hukum yang lebih tepat);535) dan kepada masing-masing Kami berikan hikmah dan ilmu, dan Kami tundukkan gunung-gunung dan burung-burung, semua bertasbih bersama Dawud. Dan Kamilah yang melakukannya"},{id:80,text:"\u0648\u064e\u0639\u064e\u0644\u0651\u064e\u0645\u06e1\u0646\u064e\u0670\u0647\u064f \u0635\u064e\u0646\u06e1\u0639\u064e\u0629\u064e \u0644\u064e\u0628\u064f\u0648\u0633\u0656 \u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u0644\u0650\u062a\u064f\u062d\u06e1\u0635\u0650\u0646\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e2 \u0628\u064e\u0623\u06e1\u0633\u0650\u0643\u064f\u0645\u06e1\u06d6 \u0641\u064e\u0647\u064e\u0644\u06e1 \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0634\u064e\u0670\u0643\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Dan Kami ajarkan (pula) kepada Dawud cara membuat baju besi untukmu, guna melindungi kamu dalam peperanganmu. Apakah kamu bersyukur (kepada Allah)"},{id:81,text:"\u0648\u064e\u0644\u0650\u0633\u064f\u0644\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u064e \u0671\u0644\u0631\u0651\u0650\u064a\u062d\u064e \u0639\u064e\u0627\u0635\u0650\u0641\u064e\u0629\u0657 \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0628\u0650\u0623\u064e\u0645\u06e1\u0631\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0671\u0644\u0651\u064e\u062a\u0650\u064a \u0628\u064e\u0670\u0631\u064e\u0643\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627\u06da \u0648\u064e\u0643\u064f\u0646\u0651\u064e\u0627 \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u064d \u0639\u064e\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dan (Kami tundukkan) untuk Sulaiman angin yang sangat kencang tiupannya yang berhembus dengan perintahnya ke negeri yang Kami beri berkah padanya. Dan Kami Maha Mengetahui segala sesuatu"},{id:82,text:"\u0648\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u0634\u0651\u064e\u064a\u064e\u0670\u0637\u0650\u064a\u0646\u0650 \u0645\u064e\u0646 \u064a\u064e\u063a\u064f\u0648\u0635\u064f\u0648\u0646\u064e \u0644\u064e\u0647\u064f\u06e5 \u0648\u064e\u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0639\u064e\u0645\u064e\u0644\u0657\u0627 \u062f\u064f\u0648\u0646\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e\u06d6 \u0648\u064e\u0643\u064f\u0646\u0651\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u06e1 \u062d\u064e\u0670\u0641\u0650\u0638\u0650\u064a\u0646\u064e",translation:"Dan (Kami tundukkan pula kepada Sulaiman) segolongan setan-setan yang menyelam (ke dalam laut) untuknya dan mereka mengerjakan pekerjaan selain itu; dan Kami yang memelihara mereka"},{id:83,text:"\u06de\u0648\u064e\u0623\u064e\u064a\u0651\u064f\u0648\u0628\u064e \u0625\u0650\u0630\u06e1 \u0646\u064e\u0627\u062f\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u0646\u0651\u0650\u064a \u0645\u064e\u0633\u0651\u064e\u0646\u0650\u064a\u064e \u0671\u0644\u0636\u0651\u064f\u0631\u0651\u064f \u0648\u064e\u0623\u064e\u0646\u062a\u064e \u0623\u064e\u0631\u06e1\u062d\u064e\u0645\u064f \u0671\u0644\u0631\u0651\u064e\u0640\u0670\u062d\u0650\u0645\u0650\u064a\u0646\u064e",translation:"dan (ingatlah kisah) Ayub, ketika dia berdoa kepada Tuhannya, \"(Ya Tuhanku), sungguh, aku telah ditimpa penyakit, padahal Engkau Tuhan Yang Maha Penyayang dari semua yang penyayang"},{id:84,text:"\u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u062c\u064e\u0628\u06e1\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u06e5 \u0641\u064e\u0643\u064e\u0634\u064e\u0641\u06e1\u0646\u064e\u0627 \u0645\u064e\u0627 \u0628\u0650\u0647\u0650\u06e6 \u0645\u0650\u0646 \u0636\u064f\u0631\u0651\u0656\u06d6 \u0648\u064e\u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f \u0623\u064e\u0647\u06e1\u0644\u064e\u0647\u064f\u06e5 \u0648\u064e\u0645\u0650\u062b\u06e1\u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u0639\u064e\u0647\u064f\u0645\u06e1 \u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u0657 \u0645\u0651\u0650\u0646\u06e1 \u0639\u0650\u0646\u062f\u0650\u0646\u064e\u0627 \u0648\u064e\u0630\u0650\u0643\u06e1\u0631\u064e\u0649\u0670 \u0644\u0650\u0644\u06e1\u0639\u064e\u0670\u0628\u0650\u062f\u0650\u064a\u0646\u064e",translation:"Maka Kami kabulkan (doa)nya, lalu Kami lenyapkan penyakit yang ada padanya dan Kami kembalikan keluarganya kepadanya, dan (Kami lipat gandakan jumlah mereka), sebagai suatu rahmat dari Kami, dan untuk menjadi peringatan bagi semua yang menyembah Kami"},{id:85,text:"\u0648\u064e\u0625\u0650\u0633\u06e1\u0645\u064e\u0670\u0639\u0650\u064a\u0644\u064e \u0648\u064e\u0625\u0650\u062f\u06e1\u0631\u0650\u064a\u0633\u064e \u0648\u064e\u0630\u064e\u0627 \u0671\u0644\u06e1\u0643\u0650\u0641\u06e1\u0644\u0650\u06d6 \u0643\u064f\u0644\u0651\u065e \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0628\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan (ingatlah kisah) Ismail, Idris dan Zulkifli. Mereka semua termasuk orang-orang yang sabar"},{id:86,text:"\u0648\u064e\u0623\u064e\u062f\u06e1\u062e\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0631\u064e\u062d\u06e1\u0645\u064e\u062a\u0650\u0646\u064e\u0627\u0653\u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u0650\u064a\u0646\u064e",translation:"dan Kami masukkan mereka ke dalam rahmat Kami. Sungguh, mereka termasuk orang-orang yang saleh"},{id:87,text:"\u0648\u064e\u0630\u064e\u0627 \u0671\u0644\u0646\u0651\u064f\u0648\u0646\u0650 \u0625\u0650\u0630 \u0630\u0651\u064e\u0647\u064e\u0628\u064e \u0645\u064f\u063a\u064e\u0670\u0636\u0650\u0628\u0657\u0627 \u0641\u064e\u0638\u064e\u0646\u0651\u064e \u0623\u064e\u0646 \u0644\u0651\u064e\u0646 \u0646\u0651\u064e\u0642\u06e1\u062f\u0650\u0631\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0641\u064e\u0646\u064e\u0627\u062f\u064e\u0649\u0670 \u0641\u0650\u064a \u0671\u0644\u0638\u0651\u064f\u0644\u064f\u0645\u064e\u0670\u062a\u0650 \u0623\u064e\u0646 \u0644\u0651\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064e \u0633\u064f\u0628\u06e1\u062d\u064e\u0670\u0646\u064e\u0643\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0643\u064f\u0646\u062a\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dan (ingatlah kisah) \u017bun N\u016bn (Yunus), ketika dia pergi dalam keadaan marah, lalu dia menyangka bahwa Kami tidak akan menyulitkannya, maka dia berdoa dalam keadaan yang sangat gelap,536) \"Tidak ada tuhan selain Engkau, Mahasuci Engkau. Sungguh, aku termasuk orang-orang yang zalim"},{id:88,text:"\u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u062c\u064e\u0628\u06e1\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u06e5 \u0648\u064e\u0646\u064e\u062c\u0651\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u063a\u064e\u0645\u0651\u0650\u06da \u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064f\u0640\u06e8\u062c\u0650\u064a \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Maka kami kabulkan (doa)nya dan Kami selamatkan dia dari kedukaan. Dan demikianlah Kami menyelamatkan orang-orang yang beriman"},{id:89,text:"\u0648\u064e\u0632\u064e\u0643\u064e\u0631\u0650\u064a\u0651\u064e\u0627\u0653 \u0625\u0650\u0630\u06e1 \u0646\u064e\u0627\u062f\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u06e5 \u0631\u064e\u0628\u0651\u0650 \u0644\u064e\u0627 \u062a\u064e\u0630\u064e\u0631\u06e1\u0646\u0650\u064a \u0641\u064e\u0631\u06e1\u062f\u0657\u0627 \u0648\u064e\u0623\u064e\u0646\u062a\u064e \u062e\u064e\u064a\u06e1\u0631\u064f \u0671\u0644\u06e1\u0648\u064e\u0670\u0631\u0650\u062b\u0650\u064a\u0646\u064e",translation:"Dan (ingatlah kisah) Zakaria, ketika dia berdoa kepada Tuhannya, \"Ya Tuhanku, janganlah Engkau biarkan aku hidup seorang diri (tanpa keturunan) dan Engkaulah ahli waris yang terbaik"},{id:90,text:"\u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u062c\u064e\u0628\u06e1\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u06e5 \u0648\u064e\u0648\u064e\u0647\u064e\u0628\u06e1\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u06e5 \u064a\u064e\u062d\u06e1\u064a\u064e\u0649\u0670 \u0648\u064e\u0623\u064e\u0635\u06e1\u0644\u064e\u062d\u06e1\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u06e5 \u0632\u064e\u0648\u06e1\u062c\u064e\u0647\u064f\u06e5\u0653\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064f\u0633\u064e\u0670\u0631\u0650\u0639\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u062e\u064e\u064a\u06e1\u0631\u064e\u0670\u062a\u0650 \u0648\u064e\u064a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e\u0646\u064e\u0627 \u0631\u064e\u063a\u064e\u0628\u0657\u0627 \u0648\u064e\u0631\u064e\u0647\u064e\u0628\u0657\u0627\u06d6 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0646\u064e\u0627 \u062e\u064e\u0670\u0634\u0650\u0639\u0650\u064a\u0646\u064e",translation:"Maka Kami kabulkan (doa)nya, dan Kami anugerahkan kepadanya Yahya, dan Kami jadikan istrinya (dapat mengandung). Sungguh, mereka selalu bersegera dalam (mengerjakan) kebaikan, dan mereka berdoa kepada Kami dengan penuh harap dan cemas. Dan mereka orang-orang yang khusyuk kepada Kami"},{id:91,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u062a\u0650\u064a\u0653 \u0623\u064e\u062d\u06e1\u0635\u064e\u0646\u064e\u062a\u06e1 \u0641\u064e\u0631\u06e1\u062c\u064e\u0647\u064e\u0627 \u0641\u064e\u0646\u064e\u0641\u064e\u062e\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u0650\u0646 \u0631\u0651\u064f\u0648\u062d\u0650\u0646\u064e\u0627 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064e\u0627 \u0648\u064e\u0671\u0628\u06e1\u0646\u064e\u0647\u064e\u0627\u0653 \u0621\u064e\u0627\u064a\u064e\u0629\u0657 \u0644\u0651\u0650\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Dan (ingatlah kisah Maryam) yang memelihara kehormatannya, lalu Kami tiupkan (roh) dari Kami ke dalam (tubuh)nya; Kami jadikan dia dan anaknya sebagai tanda (kebesaran Allah) bagi seluruh alam"},{id:92,text:"\u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0670\u0630\u0650\u0647\u0650\u06e6\u0653 \u0623\u064f\u0645\u0651\u064e\u062a\u064f\u0643\u064f\u0645\u06e1 \u0623\u064f\u0645\u0651\u064e\u0629\u0657 \u0648\u064e\u0670\u062d\u0650\u062f\u064e\u0629\u0657 \u0648\u064e\u0623\u064e\u0646\u064e\u0627\u06e0 \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u06e1 \u0641\u064e\u0671\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0646\u0650",translation:"Sungguh, (agama tauhid) inilah agama kamu, agama yang satu dan Aku adalah Tuhanmu, maka sembahlah Aku"},{id:93,text:"\u0648\u064e\u062a\u064e\u0642\u064e\u0637\u0651\u064e\u0639\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0645\u06e1\u0631\u064e\u0647\u064f\u0645 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1\u06d6 \u0643\u064f\u0644\u0651\u064c \u0625\u0650\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0631\u064e\u0670\u062c\u0650\u0639\u064f\u0648\u0646\u064e",translation:"Tetapi mereka terpecah belah dalam urusan (agama) mereka di antara mereka. Masing-masing (golongan itu semua) akan kembali kepada Kami"},{id:94,text:"\u0641\u064e\u0645\u064e\u0646 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u06e1 \u0645\u0650\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0648\u064e\u0647\u064f\u0648\u064e \u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u065e \u0641\u064e\u0644\u064e\u0627 \u0643\u064f\u0641\u06e1\u0631\u064e\u0627\u0646\u064e \u0644\u0650\u0633\u064e\u0639\u06e1\u064a\u0650\u0647\u0650\u06e6 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0647\u064f\u06e5 \u0643\u064e\u0670\u062a\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Barangsiapa yang mengerjakan kebajikan, dan dia beriman, maka usahanya tidak akan di ingkari (disia-siakan), dan sungguh, Kamilah yang mencatat untuknya"},{id:95,text:"\u0648\u064e\u062d\u064e\u0631\u064e\u0670\u0645\u064c \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064e\u0631\u06e1\u064a\u064e\u0629\u064d \u0623\u064e\u0647\u06e1\u0644\u064e\u0643\u06e1\u0646\u064e\u0670\u0647\u064e\u0627\u0653 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0631\u06e1\u062c\u0650\u0639\u064f\u0648\u0646\u064e",translation:"Dan tidak mungkin bagi (penduduk) suatu negeri yang telah Kami binasakan, bahwa mereka tidak akan kembali (kepada Kami)"},{id:96,text:"\u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u064e\u0627 \u0641\u064f\u062a\u0650\u062d\u064e\u062a\u06e1 \u064a\u064e\u0623\u06e1\u062c\u064f\u0648\u062c\u064f \u0648\u064e\u0645\u064e\u0623\u06e1\u062c\u064f\u0648\u062c\u064f \u0648\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u062d\u064e\u062f\u064e\u0628\u0656 \u064a\u064e\u0646\u0633\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Hingga apabila (tembok) Ya`j\u016bj dan Ma`j\u016bj dibukakan dan mereka turun dengan cepat dari seluruh tempat yang tinggi"},{id:97,text:"\u0648\u064e\u0671\u0642\u06e1\u062a\u064e\u0631\u064e\u0628\u064e \u0671\u0644\u06e1\u0648\u064e\u0639\u06e1\u062f\u064f \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0647\u0650\u064a\u064e \u0634\u064e\u0670\u062e\u0650\u0635\u064e\u0629\u064c \u0623\u064e\u0628\u06e1\u0635\u064e\u0670\u0631\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u064a\u064e\u0670\u0648\u064e\u064a\u06e1\u0644\u064e\u0646\u064e\u0627 \u0642\u064e\u062f\u06e1 \u0643\u064f\u0646\u0651\u064e\u0627 \u0641\u0650\u064a \u063a\u064e\u0641\u06e1\u0644\u064e\u0629\u0656 \u0645\u0651\u0650\u0646\u06e1 \u0647\u064e\u0670\u0630\u064e\u0627 \u0628\u064e\u0644\u06e1 \u0643\u064f\u0646\u0651\u064e\u0627 \u0638\u064e\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dan (apabila) janji yang benar (hari berbangkit) telah dekat, maka tiba-tiba mata orang-orang yang kafir terbelalak. (Mereka berkata), \"Alangkah celakanya kami! Kami benar-benar lengah tentang ini, bahkan kami benar-benar orang yang zalim"},{id:98,text:"\u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u064e\u0635\u064e\u0628\u064f \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0644\u064e\u0647\u064e\u0627 \u0648\u064e\u0670\u0631\u0650\u062f\u064f\u0648\u0646\u064e",translation:"Sungguh, kamu (orang kafir) dan apa yang kamu sembah selain Allah, adalah bahan bakar Jahanam. Kamu (pasti) masuk ke dalamnya"},{id:99,text:"\u0644\u064e\u0648\u06e1 \u0643\u064e\u0627\u0646\u064e \u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650 \u0621\u064e\u0627\u0644\u0650\u0647\u064e\u0629\u0657 \u0645\u0651\u064e\u0627 \u0648\u064e\u0631\u064e\u062f\u064f\u0648\u0647\u064e\u0627\u06d6 \u0648\u064e\u0643\u064f\u0644\u0651\u065e \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u0670\u0644\u0650\u062f\u064f\u0648\u0646\u064e",translation:"Seandainya (berhala-berhala) itu tuhan, tentu mereka tidak akan memasukinya (neraka). Tetapi semuanya akan kekal di dalamnya"},{id:100,text:"\u0644\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u0632\u064e\u0641\u0650\u064a\u0631\u065e \u0648\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u0645\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Mereka merintih dan menjerit di dalamnya (neraka), dan mereka di dalamnya tidak dapat mendengar"},{id:101,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0633\u064e\u0628\u064e\u0642\u064e\u062a\u06e1 \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u0651\u064e\u0627 \u0671\u0644\u06e1\u062d\u064f\u0633\u06e1\u0646\u064e\u0649\u0670\u0653 \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0639\u064e\u0646\u06e1\u0647\u064e\u0627 \u0645\u064f\u0628\u06e1\u0639\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Sungguh, sejak dahulu bagi orang-orang yang telah ada (ketetapan) yang baik dari Kami, mereka itu akan dijauhkan (dari neraka)"},{id:102,text:"\u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u0645\u064e\u0639\u064f\u0648\u0646\u064e \u062d\u064e\u0633\u0650\u064a\u0633\u064e\u0647\u064e\u0627\u06d6 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0645\u064e\u0627 \u0671\u0634\u06e1\u062a\u064e\u0647\u064e\u062a\u06e1 \u0623\u064e\u0646\u0641\u064f\u0633\u064f\u0647\u064f\u0645\u06e1 \u062e\u064e\u0670\u0644\u0650\u062f\u064f\u0648\u0646\u064e",translation:"Mereka tidak mendengar bunyi desis (api neraka), dan mereka kekal dalam (menikmati) semua yang mereka ingini"},{id:103,text:"\u0644\u064e\u0627 \u064a\u064e\u062d\u06e1\u0632\u064f\u0646\u064f\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0641\u064e\u0632\u064e\u0639\u064f \u0671\u0644\u06e1\u0623\u064e\u0643\u06e1\u0628\u064e\u0631\u064f \u0648\u064e\u062a\u064e\u062a\u064e\u0644\u064e\u0642\u0651\u064e\u0649\u0670\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u064f \u0647\u064e\u0670\u0630\u064e\u0627 \u064a\u064e\u0648\u06e1\u0645\u064f\u0643\u064f\u0645\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064f\u0648\u0639\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Kejutan yang dahsyat tidak membuat mereka merasa sedih, dan para malaikat akan menyambut mereka (dengan ucapan), \"Inilah harimu yang telah dijanjikan kepadamu"},{id:104,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u0646\u064e\u0637\u06e1\u0648\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u064e \u0643\u064e\u0637\u064e\u064a\u0651\u0650 \u0671\u0644\u0633\u0651\u0650\u062c\u0650\u0644\u0651\u0650 \u0644\u0650\u0644\u06e1\u0643\u064f\u062a\u064f\u0628\u0650\u06da \u0643\u064e\u0645\u064e\u0627 \u0628\u064e\u062f\u064e\u0623\u06e1\u0646\u064e\u0627\u0653 \u0623\u064e\u0648\u0651\u064e\u0644\u064e \u062e\u064e\u0644\u06e1\u0642\u0656 \u0646\u0651\u064f\u0639\u0650\u064a\u062f\u064f\u0647\u064f\u06e5\u06da \u0648\u064e\u0639\u06e1\u062f\u064b\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627\u0653\u06da \u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0641\u064e\u0670\u0639\u0650\u0644\u0650\u064a\u0646\u064e",translation:"(Ingatlah) pada hari langit Kami gulung seperti menggulung lembaran-lembaran kertas. Sebagaimana Kami telah memulai penciptaan pertama, begitulah Kami akan mengulanginya lagi. (Suatu) janji yang pasti Kami tepati; sungguh, Kami akan melaksanakannya"},{id:105,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0643\u064e\u062a\u064e\u0628\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0632\u0651\u064e\u0628\u064f\u0648\u0631\u0650 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0671\u0644\u0630\u0651\u0650\u0643\u06e1\u0631\u0650 \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u064a\u064e\u0631\u0650\u062b\u064f\u0647\u064e\u0627 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064f\u0648\u0646\u064e",translation:"(Dan sungguh, telah Kami tulis di dalam Zabur538) setelah (tertulis) di dalam A\u017c-\u017bikr (Lau\u1e25 Ma\u1e25f\u016b\u1e93), bahwa bumi ini akan diwarisi oleh hamba-hamba-Ku yang saleh"},{id:106,text:"\u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0647\u064e\u0670\u0630\u064e\u0627 \u0644\u064e\u0628\u064e\u0644\u064e\u0670\u063a\u0657\u0627 \u0644\u0651\u0650\u0642\u064e\u0648\u06e1\u0645\u064d \u0639\u064e\u0670\u0628\u0650\u062f\u0650\u064a\u0646\u064e",translation:"Sungguh, (apa yang disebutkan) di dalam (Alquran) ini, benar-benar menjadi petunjuk (yang lengkap) bagi orang-orang yang menyembah (Allah)"},{id:107,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0670\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u0657 \u0644\u0651\u0650\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Dan Kami tidak mengutus engkau (Muhammad) melainkan untuk (menjadi) rahmat bagi seluruh alam"},{id:108,text:"\u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064f\u0648\u062d\u064e\u0649\u0670\u0653 \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u064f\u0643\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0670\u0647\u065e \u0648\u064e\u0670\u062d\u0650\u062f\u065e\u06d6 \u0641\u064e\u0647\u064e\u0644\u06e1 \u0623\u064e\u0646\u062a\u064f\u0645 \u0645\u0651\u064f\u0633\u06e1\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Katakanlah (Muhammad), \"Sungguh, apa yang diwahyukan kepadaku ialah bahwa Tuhanmu adalah Tuhan Yang Esa, maka apakah kamu telah berserah diri (kepada-Nya)"},{id:109,text:"\u0641\u064e\u0625\u0650\u0646 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u06e1\u0627\u0652 \u0641\u064e\u0642\u064f\u0644\u06e1 \u0621\u064e\u0627\u0630\u064e\u0646\u062a\u064f\u0643\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0633\u064e\u0648\u064e\u0627\u0653\u0621\u0656\u06d6 \u0648\u064e\u0625\u0650\u0646\u06e1 \u0623\u064e\u062f\u06e1\u0631\u0650\u064a\u0653 \u0623\u064e\u0642\u064e\u0631\u0650\u064a\u0628\u064c \u0623\u064e\u0645 \u0628\u064e\u0639\u0650\u064a\u062f\u065e \u0645\u0651\u064e\u0627 \u062a\u064f\u0648\u0639\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Jika mereka berpaling, maka katakanlah (Muhammad), \"Aku telah menyampaikan kepadamu (ajaran) yang sama (antara kita) dan aku tidak tahu apakah yang diancamkan kepadamu itu sudah dekat atau masih jauh"},{id:110,text:"\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0671\u0644\u06e1\u062c\u064e\u0647\u06e1\u0631\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0644\u0650 \u0648\u064e\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u062a\u064e\u0643\u06e1\u062a\u064f\u0645\u064f\u0648\u0646\u064e",translation:"Sungguh Dia (Allah) mengetahui perkataan (yang kamu ucapkan) dengan terang-terangan, dan mengetahui (pula) apa yang kamu rahasiakan"},{id:111,text:"\u0648\u064e\u0625\u0650\u0646\u06e1 \u0623\u064e\u062f\u06e1\u0631\u0650\u064a \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u06e5 \u0641\u0650\u062a\u06e1\u0646\u064e\u0629\u065e \u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0645\u064e\u062a\u064e\u0670\u0639\u064c \u0625\u0650\u0644\u064e\u0649\u0670 \u062d\u0650\u064a\u0646\u0656",translation:"Dan aku tidak tahu, boleh jadi hal itu cobaan bagi kamu dan kesenangan sampai waktu yang ditentukan"},{id:112,text:"\u0642\u064e\u0670\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0671\u062d\u06e1\u0643\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650\u06d7 \u0648\u064e\u0631\u064e\u0628\u0651\u064f\u0646\u064e\u0627 \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u064f \u0671\u0644\u06e1\u0645\u064f\u0633\u06e1\u062a\u064e\u0639\u064e\u0627\u0646\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u062a\u064e\u0635\u0650\u0641\u064f\u0648\u0646\u064e",translation:"Dia (Muhammad) berkata, \"Ya Tuhanku, berilah keputusan dengan adil. Dan Tuhan kami Maha Pengasih, tempat memohon segala pertolongan atas semua yang kamu katakan"}]},{id:22,name:"\u0627\u0644\u062d\u062c",transliteration:"Al-Hajj",translation:"Haji",type:"medinan",total_verses:78,verses:[{id:1,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e \u0632\u064e\u0644\u06e1\u0632\u064e\u0644\u064e\u0629\u064e \u0671\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u0650 \u0634\u064e\u064a\u06e1\u0621\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u065e",translation:"Wahai manusia! Bertakwalah kepada Tuhanmu; sungguh, guncangan (hari) Kiamat itu adalah suatu (kejadian) yang sangat besar"},{id:2,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u062a\u064e\u0631\u064e\u0648\u06e1\u0646\u064e\u0647\u064e\u0627 \u062a\u064e\u0630\u06e1\u0647\u064e\u0644\u064f \u0643\u064f\u0644\u0651\u064f \u0645\u064f\u0631\u06e1\u0636\u0650\u0639\u064e\u0629\u064d \u0639\u064e\u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u0631\u06e1\u0636\u064e\u0639\u064e\u062a\u06e1 \u0648\u064e\u062a\u064e\u0636\u064e\u0639\u064f \u0643\u064f\u0644\u0651\u064f \u0630\u064e\u0627\u062a\u0650 \u062d\u064e\u0645\u06e1\u0644\u064d \u062d\u064e\u0645\u06e1\u0644\u064e\u0647\u064e\u0627 \u0648\u064e\u062a\u064e\u0631\u064e\u0649 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0633\u064f\u0643\u064e\u0670\u0631\u064e\u0649\u0670 \u0648\u064e\u0645\u064e\u0627 \u0647\u064f\u0645 \u0628\u0650\u0633\u064f\u0643\u064e\u0670\u0631\u064e\u0649\u0670 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0634\u064e\u062f\u0650\u064a\u062f\u065e",translation:"(Ingatlah) pada hari ketika kamu melihatnya (guncangan itu), semua perempuan yang menyusui anaknya akan lalai terhadap anak yang disusuinya, dan setiap perempuan yang hamil akan keguguran kandungannya, dan kamu melihat manusia dalam keadaan mabuk, padahal sebenarnya mereka tidak mabuk, tetapi azab Allah itu sangat keras"},{id:3,text:"\u0648\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0645\u064e\u0646 \u064a\u064f\u062c\u064e\u0670\u062f\u0650\u0644\u064f \u0641\u0650\u064a \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u0650\u063a\u064e\u064a\u06e1\u0631\u0650 \u0639\u0650\u0644\u06e1\u0645\u0656 \u0648\u064e\u064a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f \u0643\u064f\u0644\u0651\u064e \u0634\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u0656 \u0645\u0651\u064e\u0631\u0650\u064a\u062f\u0656",translation:"Dan di antara manusia ada yang berbantahan tentang Allah tanpa ilmu dan hanya mengikuti para setan yang sangat jahat"},{id:4,text:"\u0643\u064f\u062a\u0650\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u06e5 \u0645\u064e\u0646 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0627\u0647\u064f \u0641\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u06e5 \u064a\u064f\u0636\u0650\u0644\u0651\u064f\u0647\u064f\u06e5 \u0648\u064e\u064a\u064e\u0647\u06e1\u062f\u0650\u064a\u0647\u0650 \u0625\u0650\u0644\u064e\u0649\u0670 \u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0671\u0644\u0633\u0651\u064e\u0639\u0650\u064a\u0631\u0650",translation:"(tentang setan), telah ditetapkan bahwa siapa yang berkawan dengan dia, maka dia akan menyesatkannya, dan membawanya ke azab neraka"},{id:5,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0641\u0650\u064a \u0631\u064e\u064a\u06e1\u0628\u0656 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0628\u064e\u0639\u06e1\u062b\u0650 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u06e1\u0646\u064e\u0670\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u062a\u064f\u0631\u064e\u0627\u0628\u0656 \u062b\u064f\u0645\u0651\u064e \u0645\u0650\u0646 \u0646\u0651\u064f\u0637\u06e1\u0641\u064e\u0629\u0656 \u062b\u064f\u0645\u0651\u064e \u0645\u0650\u0646\u06e1 \u0639\u064e\u0644\u064e\u0642\u064e\u0629\u0656 \u062b\u064f\u0645\u0651\u064e \u0645\u0650\u0646 \u0645\u0651\u064f\u0636\u06e1\u063a\u064e\u0629\u0656 \u0645\u0651\u064f\u062e\u064e\u0644\u0651\u064e\u0642\u064e\u0629\u0656 \u0648\u064e\u063a\u064e\u064a\u06e1\u0631\u0650 \u0645\u064f\u062e\u064e\u0644\u0651\u064e\u0642\u064e\u0629\u0656 \u0644\u0651\u0650\u0646\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0646\u064f\u0642\u0650\u0631\u0651\u064f \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u062d\u064e\u0627\u0645\u0650 \u0645\u064e\u0627 \u0646\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u062c\u064e\u0644\u0656 \u0645\u0651\u064f\u0633\u064e\u0645\u0651\u0657\u0649 \u062b\u064f\u0645\u0651\u064e \u0646\u064f\u062e\u06e1\u0631\u0650\u062c\u064f\u0643\u064f\u0645\u06e1 \u0637\u0650\u0641\u06e1\u0644\u0657\u0627 \u062b\u064f\u0645\u0651\u064e \u0644\u0650\u062a\u064e\u0628\u06e1\u0644\u064f\u063a\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0634\u064f\u062f\u0651\u064e\u0643\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0645\u0650\u0646\u0643\u064f\u0645 \u0645\u0651\u064e\u0646 \u064a\u064f\u062a\u064e\u0648\u064e\u0641\u0651\u064e\u0649\u0670 \u0648\u064e\u0645\u0650\u0646\u0643\u064f\u0645 \u0645\u0651\u064e\u0646 \u064a\u064f\u0631\u064e\u062f\u0651\u064f \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0631\u06e1\u0630\u064e\u0644\u0650 \u0671\u0644\u06e1\u0639\u064f\u0645\u064f\u0631\u0650 \u0644\u0650\u0643\u064e\u064a\u06e1\u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064e \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0639\u0650\u0644\u06e1\u0645\u0656 \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627\u06da \u0648\u064e\u062a\u064e\u0631\u064e\u0649 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0647\u064e\u0627\u0645\u0650\u062f\u064e\u0629\u0657 \u0641\u064e\u0625\u0650\u0630\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627 \u0671\u0644\u06e1\u0645\u064e\u0627\u0653\u0621\u064e \u0671\u0647\u06e1\u062a\u064e\u0632\u0651\u064e\u062a\u06e1 \u0648\u064e\u0631\u064e\u0628\u064e\u062a\u06e1 \u0648\u064e\u0623\u064e\u0646\u06e2\u0628\u064e\u062a\u064e\u062a\u06e1 \u0645\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u0632\u064e\u0648\u06e1\u062c\u0650\u06ed \u0628\u064e\u0647\u0650\u064a\u062c\u0656",translation:"Wahai manusia! Jika kamu meragukan (hari) kebangkitan, maka sesungguhnya Kami telah menjadikan kamu dari tanah, kemudian dari setetes mani, kemudian dari segumpal darah, kemudian dari segumpal daging yang sempurna kejadiannya dan yang tidak sempurna, agar Kami jelaskan kepada kamu; dan Kami tetapkan dalam rahim menurut kehendak Kami sampai waktu yang sudah ditentukan, kemudian Kami keluarkan kamu sebagai bayi, kemudian (dengan berangsur-angsur) kamu sampai kepada usia dewasa, dan di antara kamu ada yang diwafatkan dan (ada pula) di antara kamu yang dikembalikan sampai usia sangat tua (pikun), sehingga dia tidak mengetahui lagi sesuatu yang telah diketahuinya. Dan kamu lihat bumi ini kering, kemudian apabila telah Kami turunkan air (hujan) di atasnya, hiduplah bumi itu dan menjadi subur serta menumbuhkan berbagai jenis pasangan tetumbuhan yang indah"},{id:6,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f \u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u06e5 \u064a\u064f\u062d\u06e1\u064a\u0650 \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u064e\u0649\u0670 \u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u06e5 \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0642\u064e\u062f\u0650\u064a\u0631\u065e",translation:"Yang demikian itu karena sungguh, Allah, Dialah yang hak, dan sungguh, Dialah yang menghidupkan segala yang telah mati, dan sungguh, Dia Mahakuasa atas segala sesuatu"},{id:7,text:"\u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064e \u0621\u064e\u0627\u062a\u0650\u064a\u064e\u0629\u065e \u0644\u0651\u064e\u0627 \u0631\u064e\u064a\u06e1\u0628\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0628\u06e1\u0639\u064e\u062b\u064f \u0645\u064e\u0646 \u0641\u0650\u064a \u0671\u0644\u06e1\u0642\u064f\u0628\u064f\u0648\u0631\u0650",translation:"dan sungguh, (hari) Kiamat itu pasti datang, tidak ada keraguan padanya; dan sungguh, Allah akan membangkitkan siapa pun yang di dalam kubur"},{id:8,text:"\u0648\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0645\u064e\u0646 \u064a\u064f\u062c\u064e\u0670\u062f\u0650\u0644\u064f \u0641\u0650\u064a \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u0650\u063a\u064e\u064a\u06e1\u0631\u0650 \u0639\u0650\u0644\u06e1\u0645\u0656 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u062f\u0657\u0649 \u0648\u064e\u0644\u064e\u0627 \u0643\u0650\u062a\u064e\u0670\u0628\u0656 \u0645\u0651\u064f\u0646\u0650\u064a\u0631\u0656",translation:"Dan di antara manusia ada yang berbantahan tentang Allah tanpa ilmu, tanpa petunjuk dan tanpa kitab (wahyu) yang memberi penerangan"},{id:9,text:"\u062b\u064e\u0627\u0646\u0650\u064a\u064e \u0639\u0650\u0637\u06e1\u0641\u0650\u0647\u0650\u06e6 \u0644\u0650\u064a\u064f\u0636\u0650\u0644\u0651\u064e \u0639\u064e\u0646 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0644\u064e\u0647\u064f\u06e5 \u0641\u0650\u064a \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u062e\u0650\u0632\u06e1\u064a\u065e\u06d6 \u0648\u064e\u0646\u064f\u0630\u0650\u064a\u0642\u064f\u0647\u064f\u06e5 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0671\u0644\u06e1\u062d\u064e\u0631\u0650\u064a\u0642\u0650",translation:"sambil memalingkan lambungnya (dengan congkak) untuk menyesatkan manusia dari jalan Allah. Dia mendapat kehinaan di dunia, dan pada hari Kiamat Kami berikan kepadanya rasa azab neraka yang membakar"},{id:10,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0645\u064e\u0627 \u0642\u064e\u062f\u0651\u064e\u0645\u064e\u062a\u06e1 \u064a\u064e\u062f\u064e\u0627\u0643\u064e \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u064a\u06e1\u0633\u064e \u0628\u0650\u0638\u064e\u0644\u0651\u064e\u0640\u0670\u0645\u0656 \u0644\u0651\u0650\u0644\u06e1\u0639\u064e\u0628\u0650\u064a\u062f\u0650",translation:"(Akan dikatakan kepadanya), \"Itu karena perbuatan yang dilakukan dahulu oleh kedua tanganmu, dan Allah sekali-kali tidak menzalimi hamba-hamba-Nya"},{id:11,text:"\u0648\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0645\u064e\u0646 \u064a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u062d\u064e\u0631\u06e1\u0641\u0656\u06d6 \u0641\u064e\u0625\u0650\u0646\u06e1 \u0623\u064e\u0635\u064e\u0627\u0628\u064e\u0647\u064f\u06e5 \u062e\u064e\u064a\u06e1\u0631\u064c \u0671\u0637\u06e1\u0645\u064e\u0623\u064e\u0646\u0651\u064e \u0628\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u0625\u0650\u0646\u06e1 \u0623\u064e\u0635\u064e\u0627\u0628\u064e\u062a\u06e1\u0647\u064f \u0641\u0650\u062a\u06e1\u0646\u064e\u0629\u064c \u0671\u0646\u0642\u064e\u0644\u064e\u0628\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0648\u064e\u062c\u06e1\u0647\u0650\u0647\u0650\u06e6 \u062e\u064e\u0633\u0650\u0631\u064e \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0648\u064e\u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u064e\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u062e\u064f\u0633\u06e1\u0631\u064e\u0627\u0646\u064f \u0671\u0644\u06e1\u0645\u064f\u0628\u0650\u064a\u0646\u064f",translation:"(Dan di antara manusia ada yang menyembah Allah hanya di tepi,539) maka jika dia memperoleh kebajikan, dia merasa puas, dan jika dia ditimpa suatu cobaan, dia berbalik ke belakang.540) Dia rugi di dunia dan di akhirat. Itulah kerugian yang nyata"},{id:12,text:"\u064a\u064e\u062f\u06e1\u0639\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0636\u064f\u0631\u0651\u064f\u0647\u064f\u06e5 \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0646\u0641\u064e\u0639\u064f\u0647\u064f\u06e5\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0647\u064f\u0648\u064e \u0671\u0644\u0636\u0651\u064e\u0644\u064e\u0670\u0644\u064f \u0671\u0644\u06e1\u0628\u064e\u0639\u0650\u064a\u062f\u064f",translation:"Dia menyeru kepada selain Allah sesuatu yang tidak dapat mendatangkan bencana dan tidak (pula) memberi manfaat kepadanya. Itulah kesesatan yang jauh"},{id:13,text:"\u064a\u064e\u062f\u06e1\u0639\u064f\u0648\u0627\u0652 \u0644\u064e\u0645\u064e\u0646 \u0636\u064e\u0631\u0651\u064f\u0647\u064f\u06e5\u0653 \u0623\u064e\u0642\u06e1\u0631\u064e\u0628\u064f \u0645\u0650\u0646 \u0646\u0651\u064e\u0641\u06e1\u0639\u0650\u0647\u0650\u06e6\u06da \u0644\u064e\u0628\u0650\u0626\u06e1\u0633\u064e \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u0644\u064e\u0649\u0670 \u0648\u064e\u0644\u064e\u0628\u0650\u0626\u06e1\u0633\u064e \u0671\u0644\u06e1\u0639\u064e\u0634\u0650\u064a\u0631\u064f",translation:"Dia menyeru kepada sesuatu yang (sebenarnya) bencananya lebih dekat daripada manfaatnya. Sungguh, itu seburuk-buruk penolong dan sejahat-jahat kawan"},{id:14,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u062f\u06e1\u062e\u0650\u0644\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0656 \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0645\u0650\u0646 \u062a\u064e\u062d\u06e1\u062a\u0650\u0647\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u064f\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0641\u06e1\u0639\u064e\u0644\u064f \u0645\u064e\u0627 \u064a\u064f\u0631\u0650\u064a\u062f\u064f",translation:"(Sungguh), Allah akan memasukkan orang-orang yang beriman dan mengerjakan kebajikan ke dalam surga-surga yang mengalir di bawahnya sungai-sungai. Sungguh, Allah berbuat apa yang Dia kehendaki"},{id:15,text:"\u0645\u064e\u0646 \u0643\u064e\u0627\u0646\u064e \u064a\u064e\u0638\u064f\u0646\u0651\u064f \u0623\u064e\u0646 \u0644\u0651\u064e\u0646 \u064a\u064e\u0646\u0635\u064f\u0631\u064e\u0647\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u0650\u064a \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0648\u064e\u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0641\u064e\u0644\u06e1\u064a\u064e\u0645\u06e1\u062f\u064f\u062f\u06e1 \u0628\u0650\u0633\u064e\u0628\u064e\u0628\u064d \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u062b\u064f\u0645\u0651\u064e \u0644\u06e1\u064a\u064e\u0642\u06e1\u0637\u064e\u0639\u06e1 \u0641\u064e\u0644\u06e1\u064a\u064e\u0646\u0638\u064f\u0631\u06e1 \u0647\u064e\u0644\u06e1 \u064a\u064f\u0630\u06e1\u0647\u0650\u0628\u064e\u0646\u0651\u064e \u0643\u064e\u064a\u06e1\u062f\u064f\u0647\u064f\u06e5 \u0645\u064e\u0627 \u064a\u064e\u063a\u0650\u064a\u0638\u064f",translation:"Barangsiapa menyangka bahwa Allah tidak akan menolongnya (Muhammad) di dunia dan di akhirat, maka hendaklah dia merentangkan tali ke langit-langit,541) lalu menggantung (diri), kemudian pikirkanlah apakah tipu dayanya itu dapat melenyapkan apa yang menyakitkan hatinya"},{id:16,text:"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u06ed \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0656 \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0647\u06e1\u062f\u0650\u064a \u0645\u064e\u0646 \u064a\u064f\u0631\u0650\u064a\u062f\u064f",translation:"Dan demikianlah Kami telah menurunkan (Alquran) yang merupakan ayat-ayat yang nyata; sesungguhnya Allah memberikan petunjuk kepada siapa yang Dia kehendaki"},{id:17,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064e\u0627\u062f\u064f\u0648\u0627\u0652 \u0648\u064e\u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0628\u0650\u0640\u0654\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0635\u064e\u0670\u0631\u064e\u0649\u0670 \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u062c\u064f\u0648\u0633\u064e \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u0634\u06e1\u0631\u064e\u0643\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0641\u06e1\u0635\u0650\u0644\u064f \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0634\u064e\u0647\u0650\u064a\u062f\u064c",translation:"Sesungguhnya orang-orang beriman, orang Yahudi, orang Sabiin, orang Nasrani, orang Majusi dan orang musyrik, Allah pasti memberi keputusan di antara mereka pada hari Kiamat. Sungguh, Allah menjadi saksi atas segala sesuatu"},{id:18,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0631\u064e \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0633\u06e1\u062c\u064f\u062f\u064f\u06e4 \u0644\u064e\u0647\u064f\u06e5\u06e4 \u0645\u064e\u0646 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0645\u064e\u0646 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0671\u0644\u0634\u0651\u064e\u0645\u06e1\u0633\u064f \u0648\u064e\u0671\u0644\u06e1\u0642\u064e\u0645\u064e\u0631\u064f \u0648\u064e\u0671\u0644\u0646\u0651\u064f\u062c\u064f\u0648\u0645\u064f \u0648\u064e\u0671\u0644\u06e1\u062c\u0650\u0628\u064e\u0627\u0644\u064f \u0648\u064e\u0671\u0644\u0634\u0651\u064e\u062c\u064e\u0631\u064f \u0648\u064e\u0671\u0644\u062f\u0651\u064e\u0648\u064e\u0627\u0653\u0628\u0651\u064f \u0648\u064e\u0643\u064e\u062b\u0650\u064a\u0631\u065e \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650\u06d6 \u0648\u064e\u0643\u064e\u062b\u0650\u064a\u0631\u064c \u062d\u064e\u0642\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064f\u06d7 \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0647\u0650\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646 \u0645\u0651\u064f\u0643\u06e1\u0631\u0650\u0645\u064d\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0641\u06e1\u0639\u064e\u0644\u064f \u0645\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06e9",translation:"Tidakkah engkau tahu bahwa siapa yang ada di langit dan siapa yang ada di bumi bersujud kepada Allah, juga matahari, bulan, bintang, gunung-gunung, pohon-pohon, hewan-hewan yang melata dan banyak di antara manusia? Tetapi banyak (manusia) yang pantas mendapatkan azab. Barangsiapa dihinakan Allah, tidak seorang pun yang akan memuliakannya. Sungguh, Allah berbuat apa saja yang Dia kehendaki"},{id:19,text:"\u06de\u0647\u064e\u0670\u0630\u064e\u0627\u0646\u0650 \u062e\u064e\u0635\u06e1\u0645\u064e\u0627\u0646\u0650 \u0671\u062e\u06e1\u062a\u064e\u0635\u064e\u0645\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1\u06d6 \u0641\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0642\u064f\u0637\u0651\u0650\u0639\u064e\u062a\u06e1 \u0644\u064e\u0647\u064f\u0645\u06e1 \u062b\u0650\u064a\u064e\u0627\u0628\u065e \u0645\u0651\u0650\u0646 \u0646\u0651\u064e\u0627\u0631\u0656 \u064a\u064f\u0635\u064e\u0628\u0651\u064f \u0645\u0650\u0646 \u0641\u064e\u0648\u06e1\u0642\u0650 \u0631\u064f\u0621\u064f\u0648\u0633\u0650\u0647\u0650\u0645\u064f \u0671\u0644\u06e1\u062d\u064e\u0645\u0650\u064a\u0645\u064f",translation:"Inilah dua golongan (golongan mukmin dan kafir) yang bertengkar, mereka bertengkar mengenai Tuhan mereka. Maka bagi orang kafir akan dibuatkan pakaian-pakaian dari api (neraka) untuk mereka. Ke atas kepala mereka akan disiramkan air yang mendidih"},{id:20,text:"\u064a\u064f\u0635\u06e1\u0647\u064e\u0631\u064f \u0628\u0650\u0647\u0650\u06e6 \u0645\u064e\u0627 \u0641\u0650\u064a \u0628\u064f\u0637\u064f\u0648\u0646\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0671\u0644\u06e1\u062c\u064f\u0644\u064f\u0648\u062f\u064f",translation:"Dengan (air mendidih) itu akan dihancurluluhkan apa yang ada dalam perut dan kulit mereka"},{id:21,text:"\u0648\u064e\u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u0642\u064e\u0670\u0645\u0650\u0639\u064f \u0645\u0650\u0646\u06e1 \u062d\u064e\u062f\u0650\u064a\u062f\u0656",translation:"Dan (azab) untuk mereka cambuk-cambuk dari besi"},{id:22,text:"\u0643\u064f\u0644\u0651\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0631\u064e\u0627\u062f\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646 \u064a\u064e\u062e\u06e1\u0631\u064f\u062c\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0645\u0650\u0646\u06e1 \u063a\u064e\u0645\u0651\u064d \u0623\u064f\u0639\u0650\u064a\u062f\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0630\u064f\u0648\u0642\u064f\u0648\u0627\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0671\u0644\u06e1\u062d\u064e\u0631\u0650\u064a\u0642\u0650",translation:"Setiap kali mereka hendak ke luar darinya (neraka) karena tersiksa, mereka dikembalikan (lagi) ke dalamnya. (Kepada mereka dikatakan), \"Rasakanlah azab yang membakar ini"},{id:23,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u062f\u06e1\u062e\u0650\u0644\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0656 \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0645\u0650\u0646 \u062a\u064e\u062d\u06e1\u062a\u0650\u0647\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u064f \u064a\u064f\u062d\u064e\u0644\u0651\u064e\u0648\u06e1\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u0650\u0646\u06e1 \u0623\u064e\u0633\u064e\u0627\u0648\u0650\u0631\u064e \u0645\u0650\u0646 \u0630\u064e\u0647\u064e\u0628\u0656 \u0648\u064e\u0644\u064f\u0624\u06e1\u0644\u064f\u0624\u0657\u0627\u06d6 \u0648\u064e\u0644\u0650\u0628\u064e\u0627\u0633\u064f\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u062d\u064e\u0631\u0650\u064a\u0631\u065e",translation:"Sungguh, Allah akan memasukkan orang-orang yang beriman dan mengerjakan kebajikan ke dalam surga-surga yang mengalir di bawahnya sungai-sungai. Di sana mereka diberi perhiasan gelang-gelang emas dan mutiara, dan pakaian mereka dari sutera"},{id:24,text:"\u0648\u064e\u0647\u064f\u062f\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0637\u0651\u064e\u064a\u0651\u0650\u0628\u0650 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0644\u0650 \u0648\u064e\u0647\u064f\u062f\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0670\u0637\u0650 \u0671\u0644\u06e1\u062d\u064e\u0645\u0650\u064a\u062f\u0650",translation:"Dan mereka diberi petunjuk kepada ucapan-ucapan yang baik dan diberi petunjuk (pula) kepada jalan (Allah) yang maha terpuji"},{id:25,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u064a\u064e\u0635\u064f\u062f\u0651\u064f\u0648\u0646\u064e \u0639\u064e\u0646 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u0633\u06e1\u062c\u0650\u062f\u0650 \u0671\u0644\u06e1\u062d\u064e\u0631\u064e\u0627\u0645\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0633\u064e\u0648\u064e\u0627\u0653\u0621\u064b \u0671\u0644\u06e1\u0639\u064e\u0670\u0643\u0650\u0641\u064f \u0641\u0650\u064a\u0647\u0650 \u0648\u064e\u0671\u0644\u06e1\u0628\u064e\u0627\u062f\u0650\u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0631\u0650\u062f\u06e1 \u0641\u0650\u064a\u0647\u0650 \u0628\u0650\u0625\u0650\u0644\u06e1\u062d\u064e\u0627\u062f\u0650\u06ed \u0628\u0650\u0638\u064f\u0644\u06e1\u0645\u0656 \u0646\u0651\u064f\u0630\u0650\u0642\u06e1\u0647\u064f \u0645\u0650\u0646\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064d \u0623\u064e\u0644\u0650\u064a\u0645\u0656",translation:"Sungguh, orang-orang kafir dan yang menghalangi (manusia) dari jalan Allah dan dari Masjidil Haram yang telah Kami jadikan terbuka untuk semua manusia, baik yang bermukim di sana maupun yang datang dari luar dan siapa saja yang bermaksud melakukan kejahatan secara zalim di dalamnya, niscaya akan kami rasakan kepadanya siksa yang pedih"},{id:26,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0628\u064e\u0648\u0651\u064e\u0623\u06e1\u0646\u064e\u0627 \u0644\u0650\u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064e \u0645\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u06e1\u0628\u064e\u064a\u06e1\u062a\u0650 \u0623\u064e\u0646 \u0644\u0651\u064e\u0627 \u062a\u064f\u0634\u06e1\u0631\u0650\u0643\u06e1 \u0628\u0650\u064a \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627 \u0648\u064e\u0637\u064e\u0647\u0651\u0650\u0631\u06e1 \u0628\u064e\u064a\u06e1\u062a\u0650\u064a\u064e \u0644\u0650\u0644\u0637\u0651\u064e\u0627\u0653\u0626\u0650\u0641\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u0642\u064e\u0627\u0653\u0626\u0650\u0645\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u0631\u0651\u064f\u0643\u0651\u064e\u0639\u0650 \u0671\u0644\u0633\u0651\u064f\u062c\u064f\u0648\u062f\u0650",translation:"Dan (ingatlah), ketika Kami tempatkan Ibrahim di tempat Baitullah (dengan mengatakan), \"Janganlah engkau mempersekutukan Aku dengan apa pun dan sucikanlah rumah-Ku bagi orang-orang yang tawaf, dan orang yang beribadah dan orang yang rukuk dan sujud"},{id:27,text:"\u0648\u064e\u0623\u064e\u0630\u0651\u0650\u0646 \u0641\u0650\u064a \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u062c\u0651\u0650 \u064a\u064e\u0623\u06e1\u062a\u064f\u0648\u0643\u064e \u0631\u0650\u062c\u064e\u0627\u0644\u0657\u0627 \u0648\u064e\u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0636\u064e\u0627\u0645\u0650\u0631\u0656 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u0641\u064e\u062c\u0651\u064d \u0639\u064e\u0645\u0650\u064a\u0642\u0656",translation:"Dan serulah manusia untuk mengerjakan haji, niscaya mereka akan datang kepadamu dengan berjalan kaki, atau mengendarai setiap unta yang kurus, mereka datang dari segenap penjuru yang jauh"},{id:28,text:"\u0644\u0651\u0650\u064a\u064e\u0634\u06e1\u0647\u064e\u062f\u064f\u0648\u0627\u0652 \u0645\u064e\u0646\u064e\u0670\u0641\u0650\u0639\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u064a\u064e\u0630\u06e1\u0643\u064f\u0631\u064f\u0648\u0627\u0652 \u0671\u0633\u06e1\u0645\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u0650\u064a\u0653 \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u0656 \u0645\u0651\u064e\u0639\u06e1\u0644\u064f\u0648\u0645\u064e\u0670\u062a\u064d \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u06e2 \u0628\u064e\u0647\u0650\u064a\u0645\u064e\u0629\u0650 \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0639\u064e\u0670\u0645\u0650\u06d6 \u0641\u064e\u0643\u064f\u0644\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0648\u064e\u0623\u064e\u0637\u06e1\u0639\u0650\u0645\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0628\u064e\u0627\u0653\u0626\u0650\u0633\u064e \u0671\u0644\u06e1\u0641\u064e\u0642\u0650\u064a\u0631\u064e",translation:"(Agar mereka menyaksikan berbagai manfaat untuk mereka dan agar mereka menyebut nama Allah pada beberapa hari yang telah ditentukan 542) atas rezeki yang Dia berikan kepada mereka berupa hewan ternak. Maka makanlah sebagian darinya dan (sebagian lagi) berikanlah untuk dimakan orang-orang yang sengsara dan fakir"},{id:29,text:"\u062b\u064f\u0645\u0651\u064e \u0644\u06e1\u064a\u064e\u0642\u06e1\u0636\u064f\u0648\u0627\u0652 \u062a\u064e\u0641\u064e\u062b\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u06e1\u064a\u064f\u0648\u0641\u064f\u0648\u0627\u0652 \u0646\u064f\u0630\u064f\u0648\u0631\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u06e1\u064a\u064e\u0637\u0651\u064e\u0648\u0651\u064e\u0641\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u06e1\u0628\u064e\u064a\u06e1\u062a\u0650 \u0671\u0644\u06e1\u0639\u064e\u062a\u0650\u064a\u0642\u0650",translation:"(Kemudian, hendaklah mereka menghilangkan kotoran543) (yang ada di badan) mereka, menyempurnakan nazar-nazar mereka dan melakukan tawaf sekeliling rumah tua (Baitullah)"},{id:30,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064e\u06d6 \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0639\u064e\u0638\u0651\u0650\u0645\u06e1 \u062d\u064f\u0631\u064f\u0645\u064e\u0670\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0647\u064f\u0648\u064e \u062e\u064e\u064a\u06e1\u0631\u065e \u0644\u0651\u064e\u0647\u064f\u06e5 \u0639\u0650\u0646\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u06e6\u06d7 \u0648\u064e\u0623\u064f\u062d\u0650\u0644\u0651\u064e\u062a\u06e1 \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0639\u064e\u0670\u0645\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u064a\u064f\u062a\u06e1\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1\u06d6 \u0641\u064e\u0671\u062c\u06e1\u062a\u064e\u0646\u0650\u0628\u064f\u0648\u0627\u0652 \u0671\u0644\u0631\u0651\u0650\u062c\u06e1\u0633\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u0648\u06e1\u062b\u064e\u0670\u0646\u0650 \u0648\u064e\u0671\u062c\u06e1\u062a\u064e\u0646\u0650\u0628\u064f\u0648\u0627\u0652 \u0642\u064e\u0648\u06e1\u0644\u064e \u0671\u0644\u0632\u0651\u064f\u0648\u0631\u0650",translation:"Demikianlah (perintah Allah). Dan barangsiapa mengagungkan apa yang terhormat di sisi Allah (\u1e24urum\u0101t),544) maka itu lebih baik baginya di sisi Tuhannya. Dan dihalalkan bagi kamu semua hewan ternak, kecuali yang diterangkan kepadamu (keharamannya), maka jauhilah (penyembahan) berhala-berhala yang najis itu dan jauhilah perkataan dusta"},{id:31,text:"\u062d\u064f\u0646\u064e\u0641\u064e\u0627\u0653\u0621\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u063a\u064e\u064a\u06e1\u0631\u064e \u0645\u064f\u0634\u06e1\u0631\u0650\u0643\u0650\u064a\u0646\u064e \u0628\u0650\u0647\u0650\u06e6\u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0634\u06e1\u0631\u0650\u0643\u06e1 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u062e\u064e\u0631\u0651\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0641\u064e\u062a\u064e\u062e\u06e1\u0637\u064e\u0641\u064f\u0647\u064f \u0671\u0644\u0637\u0651\u064e\u064a\u06e1\u0631\u064f \u0623\u064e\u0648\u06e1 \u062a\u064e\u0647\u06e1\u0648\u0650\u064a \u0628\u0650\u0647\u0650 \u0671\u0644\u0631\u0651\u0650\u064a\u062d\u064f \u0641\u0650\u064a \u0645\u064e\u0643\u064e\u0627\u0646\u0656 \u0633\u064e\u062d\u0650\u064a\u0642\u0656",translation:"(Beribadahlah) dengan ikhlas kepada Allah, tanpa mempersekutukan-Nya. Barangsiapa mempersekutukan Allah, maka seakan-akan dia jatuh dari langit lalu disambar oleh burung, atau diterbangkan angin ke tempat yang jauh"},{id:32,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064e\u06d6 \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0639\u064e\u0638\u0651\u0650\u0645\u06e1 \u0634\u064e\u0639\u064e\u0640\u0670\u0653\u0626\u0650\u0631\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064e\u0627 \u0645\u0650\u0646 \u062a\u064e\u0642\u06e1\u0648\u064e\u0649 \u0671\u0644\u06e1\u0642\u064f\u0644\u064f\u0648\u0628\u0650",translation:"Demikianlah (perintah Allah). Dan barangsiapa mengagungkan syiar-syiar Allah,545) maka sesungguhnya hal itu timbul dari ketakwaan hati"},{id:33,text:"\u0644\u064e\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u064e\u0646\u064e\u0670\u0641\u0650\u0639\u064f \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u062c\u064e\u0644\u0656 \u0645\u0651\u064f\u0633\u064e\u0645\u0651\u0657\u0649 \u062b\u064f\u0645\u0651\u064e \u0645\u064e\u062d\u0650\u0644\u0651\u064f\u0647\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u0628\u064e\u064a\u06e1\u062a\u0650 \u0671\u0644\u06e1\u0639\u064e\u062a\u0650\u064a\u0642\u0650",translation:"Bagi kamu padanya (hewan hadyu)546) ada beberapa manfaat,547) sampai waktu yang ditentukan, kemudian tempat penyembelihannya adalah di sekitar Baitul Atiq (Baitullah)"},{id:34,text:"\u0648\u064e\u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0623\u064f\u0645\u0651\u064e\u0629\u0656 \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0645\u064e\u0646\u0633\u064e\u0643\u0657\u0627 \u0644\u0651\u0650\u064a\u064e\u0630\u06e1\u0643\u064f\u0631\u064f\u0648\u0627\u0652 \u0671\u0633\u06e1\u0645\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u06e2 \u0628\u064e\u0647\u0650\u064a\u0645\u064e\u0629\u0650 \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0639\u064e\u0670\u0645\u0650\u06d7 \u0641\u064e\u0625\u0650\u0644\u064e\u0670\u0647\u064f\u0643\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0670\u0647\u065e \u0648\u064e\u0670\u062d\u0650\u062f\u065e \u0641\u064e\u0644\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u0633\u06e1\u0644\u0650\u0645\u064f\u0648\u0627\u0652\u06d7 \u0648\u064e\u0628\u064e\u0634\u0651\u0650\u0631\u0650 \u0671\u0644\u06e1\u0645\u064f\u062e\u06e1\u0628\u0650\u062a\u0650\u064a\u0646\u064e",translation:"Dan bagi setiap umat telah Kami syariatkan penyembelihan (kurban), agar mereka menyebut nama Allah atas rezeki yang dikaruniakan Allah kepada mereka berupa hewan ternak. Maka Tuhanmu ialah Tuhan Yang Maha Esa, karena itu berserah dirilah kamu kepada-Nya. Dan sampaikanlah (Muhammad) kabar gembira kepada orang-orang yang tunduk patuh (kepada Allah)"},{id:35,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0625\u0650\u0630\u064e\u0627 \u0630\u064f\u0643\u0650\u0631\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u062c\u0650\u0644\u064e\u062a\u06e1 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0628\u0650\u0631\u0650\u064a\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627\u0653 \u0623\u064e\u0635\u064e\u0627\u0628\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0642\u0650\u064a\u0645\u0650\u064a \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u0650 \u0648\u064e\u0645\u0650\u0645\u0651\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u064a\u064f\u0646\u0641\u0650\u0642\u064f\u0648\u0646\u064e",translation:"(yaitu) orang-orang yang apabila disebut nama Allah dihati mereka bergetar, orang yang sabar atas apa yang menimpa mereka, dan orang yang melaksanakan salat dan orang yang menginfakkan sebagian rezeki yang Kami karuniakan kepada mereka"},{id:36,text:"\u0648\u064e\u0671\u0644\u06e1\u0628\u064f\u062f\u06e1\u0646\u064e \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064e\u0627 \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0634\u064e\u0639\u064e\u0640\u0670\u0653\u0626\u0650\u0631\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u064a\u06e1\u0631\u065e\u06d6 \u0641\u064e\u0671\u0630\u06e1\u0643\u064f\u0631\u064f\u0648\u0627\u0652 \u0671\u0633\u06e1\u0645\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627 \u0635\u064e\u0648\u064e\u0627\u0653\u0641\u0651\u064e\u06d6 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0648\u064e\u062c\u064e\u0628\u064e\u062a\u06e1 \u062c\u064f\u0646\u064f\u0648\u0628\u064f\u0647\u064e\u0627 \u0641\u064e\u0643\u064f\u0644\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0648\u064e\u0623\u064e\u0637\u06e1\u0639\u0650\u0645\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0642\u064e\u0627\u0646\u0650\u0639\u064e \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0639\u06e1\u062a\u064e\u0631\u0651\u064e\u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0633\u064e\u062e\u0651\u064e\u0631\u06e1\u0646\u064e\u0670\u0647\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u0634\u06e1\u0643\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Dan unta-unta itu Kami jadikan untukmu bagian dari syiar agama Allah, kamu banyak memperoleh kebaikan padanya. Maka sebutlah nama Allah (ketika kamu akan menyembelihnya) dalam keadaan berdiri548) (dan kaki-kaki telah terikat). Kemudian apabila telah rebah (mati), maka makanlah sebagiannya dan berilah makan orang yang merasa cukup dengan apa yang ada padanya (tidak meminta-minta) dan orang yang meminta. Demikianlah Kami tundukkan (unta-unta itu) untukmu, agar kamu bersyukur"},{id:37,text:"\u0644\u064e\u0646 \u064a\u064e\u0646\u064e\u0627\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064f\u062d\u064f\u0648\u0645\u064f\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u062f\u0650\u0645\u064e\u0627\u0653\u0624\u064f\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u064a\u064e\u0646\u064e\u0627\u0644\u064f\u0647\u064f \u0671\u0644\u062a\u0651\u064e\u0642\u06e1\u0648\u064e\u0649\u0670 \u0645\u0650\u0646\u0643\u064f\u0645\u06e1\u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0633\u064e\u062e\u0651\u064e\u0631\u064e\u0647\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0644\u0650\u062a\u064f\u0643\u064e\u0628\u0651\u0650\u0631\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0647\u064e\u062f\u064e\u0649\u0670\u0643\u064f\u0645\u06e1\u06d7 \u0648\u064e\u0628\u064e\u0634\u0651\u0650\u0631\u0650 \u0671\u0644\u06e1\u0645\u064f\u062d\u06e1\u0633\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Daging (hewan kurban) dan darahnya itu sekali-kali tidak akan sampai kepada Allah, tetapi yang sampai kepada-Nya adalah ketakwaan kamu. Demikianlah dia menundukkannya untukmu agar kamu mengagungkan Allah atas petunjuk yang Dia berikan kepadamu. Dan sampaikanlah kabar gembira kepada orang-orang yang berbuat baik"},{id:38,text:"\u06de\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u062f\u064e\u0670\u0641\u0650\u0639\u064f \u0639\u064e\u0646\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0653\u0627\u0652\u06d7 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0643\u064f\u0644\u0651\u064e \u062e\u064e\u0648\u0651\u064e\u0627\u0646\u0656 \u0643\u064e\u0641\u064f\u0648\u0631\u064d",translation:"Sesungguhnya Allah membela orang yang beriman. Sungguh, Allah tidak menyukai setiap orang yang berkhianat dan kufur nikmat"},{id:39,text:"\u0623\u064f\u0630\u0650\u0646\u064e \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0642\u064e\u0670\u062a\u064e\u0644\u064f\u0648\u0646\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0638\u064f\u0644\u0650\u0645\u064f\u0648\u0627\u0652\u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0646\u064e\u0635\u06e1\u0631\u0650\u0647\u0650\u0645\u06e1 \u0644\u064e\u0642\u064e\u062f\u0650\u064a\u0631\u064c",translation:"Diizinkan (berperang) bagi orang-orang yang diperangi, karena sesungguhnya mereka dizalimi. Dan sungguh, Allah Mahakuasa menolong mereka"},{id:40,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u062e\u06e1\u0631\u0650\u062c\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u062f\u0650\u064a\u064e\u0670\u0631\u0650\u0647\u0650\u0645 \u0628\u0650\u063a\u064e\u064a\u06e1\u0631\u0650 \u062d\u064e\u0642\u0651\u064d \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627\u0652 \u0631\u064e\u0628\u0651\u064f\u0646\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06d7 \u0648\u064e\u0644\u064e\u0648\u06e1\u0644\u064e\u0627 \u062f\u064e\u0641\u06e1\u0639\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0628\u064e\u0639\u06e1\u0636\u064e\u0647\u064f\u0645 \u0628\u0650\u0628\u064e\u0639\u06e1\u0636\u0656 \u0644\u0651\u064e\u0647\u064f\u062f\u0651\u0650\u0645\u064e\u062a\u06e1 \u0635\u064e\u0648\u064e\u0670\u0645\u0650\u0639\u064f \u0648\u064e\u0628\u0650\u064a\u064e\u0639\u065e \u0648\u064e\u0635\u064e\u0644\u064e\u0648\u064e\u0670\u062a\u065e \u0648\u064e\u0645\u064e\u0633\u064e\u0670\u062c\u0650\u062f\u064f \u064a\u064f\u0630\u06e1\u0643\u064e\u0631\u064f \u0641\u0650\u064a\u0647\u064e\u0627 \u0671\u0633\u06e1\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u062b\u0650\u064a\u0631\u0657\u0627\u06d7 \u0648\u064e\u0644\u064e\u064a\u064e\u0646\u0635\u064f\u0631\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0646 \u064a\u064e\u0646\u0635\u064f\u0631\u064f\u0647\u064f\u06e5\u0653\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0642\u064e\u0648\u0650\u064a\u0651\u064c \u0639\u064e\u0632\u0650\u064a\u0632\u064c",translation:"(yaitu) orang-orang yang diusir dari kampung halamannya tanpa alasan yang benar, hanya karena mereka berkata, \"Tuhan kami ialah Allah.\" Seandainya Allah tidak menolak (keganasan) sebagian manusia dengan sebagian yang lain, tentu telah dirobohkan biara-biara Nasrani, gereja-gereja, rumah-rumah ibadah orang Yahudi dan masjid-masjid yang di dalamnya banyak disebut nama Allah. Allah pasti akan menolong orang yang menolong (agama)-Nya. Sungguh, Allah Mahakuat, Mahaperkasa"},{id:41,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0625\u0650\u0646 \u0645\u0651\u064e\u0643\u0651\u064e\u0646\u0651\u064e\u0640\u0670\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0623\u064e\u0642\u064e\u0627\u0645\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u0621\u064e\u0627\u062a\u064e\u0648\u064f\u0627\u0652 \u0671\u0644\u0632\u0651\u064e\u0643\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u0623\u064e\u0645\u064e\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u06e1\u0645\u064e\u0639\u06e1\u0631\u064f\u0648\u0641\u0650 \u0648\u064e\u0646\u064e\u0647\u064e\u0648\u06e1\u0627\u0652 \u0639\u064e\u0646\u0650 \u0671\u0644\u06e1\u0645\u064f\u0646\u0643\u064e\u0631\u0650\u06d7 \u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0670\u0642\u0650\u0628\u064e\u0629\u064f \u0671\u0644\u06e1\u0623\u064f\u0645\u064f\u0648\u0631\u0650",translation:"(Yaitu) orang-orang yang jika Kami berikan kedudukan di bumi, mereka melaksanakan salat, menunaikan zakat, dan menyuruh berbuat makruf dan mencegah dari yang mungkar; dan kepada Allah lah kembali segala urusan"},{id:42,text:"\u0648\u064e\u0625\u0650\u0646 \u064a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f\u0648\u0643\u064e \u0641\u064e\u0642\u064e\u062f\u06e1 \u0643\u064e\u0630\u0651\u064e\u0628\u064e\u062a\u06e1 \u0642\u064e\u0628\u06e1\u0644\u064e\u0647\u064f\u0645\u06e1 \u0642\u064e\u0648\u06e1\u0645\u064f \u0646\u064f\u0648\u062d\u0656 \u0648\u064e\u0639\u064e\u0627\u062f\u065e \u0648\u064e\u062b\u064e\u0645\u064f\u0648\u062f\u064f",translation:"Dan jika mereka (orang-orang musyrik) mendustakan engkau (Muhammad), begitu pulalah kaum-kaum yang sebelum mereka, kaum Nuh, '\u0100d, dan Samud (juga telah mendustakan rasul-rasul-Nya)"},{id:43,text:"\u0648\u064e\u0642\u064e\u0648\u06e1\u0645\u064f \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064e \u0648\u064e\u0642\u064e\u0648\u06e1\u0645\u064f \u0644\u064f\u0648\u0637\u0656",translation:"dan (demikian juga) kaum Ibrahim dan kaum Lu\u1e6d"},{id:44,text:"\u0648\u064e\u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0645\u064e\u062f\u06e1\u064a\u064e\u0646\u064e\u06d6 \u0648\u064e\u0643\u064f\u0630\u0651\u0650\u0628\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670\u06d6 \u0641\u064e\u0623\u064e\u0645\u06e1\u0644\u064e\u064a\u06e1\u062a\u064f \u0644\u0650\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u062b\u064f\u0645\u0651\u064e \u0623\u064e\u062e\u064e\u0630\u06e1\u062a\u064f\u0647\u064f\u0645\u06e1\u06d6 \u0641\u064e\u0643\u064e\u064a\u06e1\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0646\u064e\u0643\u0650\u064a\u0631\u0650",translation:"dan penduduk Madyan. Dan Musa (juga) telah didustakan, namun Aku beri tenggang waktu kepada orang-orang kafir, kemudian Aku siksa mereka, maka betapa hebatnya siksaan-Ku"},{id:45,text:"\u0641\u064e\u0643\u064e\u0623\u064e\u064a\u0651\u0650\u0646 \u0645\u0651\u0650\u0646 \u0642\u064e\u0631\u06e1\u064a\u064e\u0629\u064d \u0623\u064e\u0647\u06e1\u0644\u064e\u0643\u06e1\u0646\u064e\u0670\u0647\u064e\u0627 \u0648\u064e\u0647\u0650\u064a\u064e \u0638\u064e\u0627\u0644\u0650\u0645\u064e\u0629\u065e \u0641\u064e\u0647\u0650\u064a\u064e \u062e\u064e\u0627\u0648\u0650\u064a\u064e\u0629\u064c \u0639\u064e\u0644\u064e\u0649\u0670 \u0639\u064f\u0631\u064f\u0648\u0634\u0650\u0647\u064e\u0627 \u0648\u064e\u0628\u0650\u0626\u06e1\u0631\u0656 \u0645\u0651\u064f\u0639\u064e\u0637\u0651\u064e\u0644\u064e\u0629\u0656 \u0648\u064e\u0642\u064e\u0635\u06e1\u0631\u0656 \u0645\u0651\u064e\u0634\u0650\u064a\u062f\u064d",translation:"Maka betapa banyak negeri yang telah Kami binasakan karena (penduduk)nya dalam keadaan zalim, sehingga runtuh bangunan-bangunannya dan (betapa banyak pula) sumur yang telah ditinggalkan dan istana yang tinggi (tidak ada penghuninya)"},{id:46,text:"\u0623\u064e\u0641\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0633\u0650\u064a\u0631\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0641\u064e\u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0642\u064f\u0644\u064f\u0648\u0628\u065e \u064a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u064e\u0627\u0653 \u0623\u064e\u0648\u06e1 \u0621\u064e\u0627\u0630\u064e\u0627\u0646\u065e \u064a\u064e\u0633\u06e1\u0645\u064e\u0639\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u064e\u0627\u06d6 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064e\u0627 \u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0649 \u0671\u0644\u06e1\u0623\u064e\u0628\u06e1\u0635\u064e\u0670\u0631\u064f \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u062a\u064e\u0639\u06e1\u0645\u064e\u0649 \u0671\u0644\u06e1\u0642\u064f\u0644\u064f\u0648\u0628\u064f \u0671\u0644\u0651\u064e\u062a\u0650\u064a \u0641\u0650\u064a \u0671\u0644\u0635\u0651\u064f\u062f\u064f\u0648\u0631\u0650",translation:"Maka tidak pernahkah mereka berjalan di bumi, sehingga hati (akal) mereka dapat memahami, telinga mereka dapat mendengar? Sebenarnya bukan mata itu yang buta, tetapi yang buta ialah hati yang di dalam dada"},{id:47,text:"\u0648\u064e\u064a\u064e\u0633\u06e1\u062a\u064e\u0639\u06e1\u062c\u0650\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u0628\u0650\u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0648\u064e\u0644\u064e\u0646 \u064a\u064f\u062e\u06e1\u0644\u0650\u0641\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0639\u06e1\u062f\u064e\u0647\u064f\u06e5\u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u064a\u064e\u0648\u06e1\u0645\u064b\u0627 \u0639\u0650\u0646\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0643\u064e\u0623\u064e\u0644\u06e1\u0641\u0650 \u0633\u064e\u0646\u064e\u0629\u0656 \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0639\u064f\u062f\u0651\u064f\u0648\u0646\u064e",translation:"Dan mereka meminta kepadamu (Muhammad) agar azab itu disegerakan, padahal Allah tidak menyalahi janji-Nya. Dan sesungguhnya sehari di sisi Tuhanmu adalah seperti seribu tahun menurut perhitunganmu"},{id:48,text:"\u0648\u064e\u0643\u064e\u0623\u064e\u064a\u0651\u0650\u0646 \u0645\u0651\u0650\u0646 \u0642\u064e\u0631\u06e1\u064a\u064e\u0629\u064d \u0623\u064e\u0645\u06e1\u0644\u064e\u064a\u06e1\u062a\u064f \u0644\u064e\u0647\u064e\u0627 \u0648\u064e\u0647\u0650\u064a\u064e \u0638\u064e\u0627\u0644\u0650\u0645\u064e\u0629\u065e \u062b\u064f\u0645\u0651\u064e \u0623\u064e\u062e\u064e\u0630\u06e1\u062a\u064f\u0647\u064e\u0627 \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0671\u0644\u06e1\u0645\u064e\u0635\u0650\u064a\u0631\u064f",translation:"Dan berapa banyak negeri yang Aku tangguhkan (penghancuran)nya, karena penduduknya berbuat zalim, kemudian Aku azab mereka, dan hanya kepada-Kulah tempat kembali (segala sesuatu)"},{id:49,text:"\u0642\u064f\u0644\u06e1 \u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u064e\u0627\u06e0 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0646\u064e\u0630\u0650\u064a\u0631\u065e \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u065e",translation:"Katakanlah (Muhammad), \"Wahai manusia! Sesungguhnya aku (diutus) kepadamu sebagai pemberi peringatan yang nyata"},{id:50,text:"\u0641\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u063a\u06e1\u0641\u0650\u0631\u064e\u0629\u065e \u0648\u064e\u0631\u0650\u0632\u06e1\u0642\u065e \u0643\u064e\u0631\u0650\u064a\u0645\u065e",translation:"Maka orang-orang yang beriman dan mengerjakan kebajikan, mereka memperoleh ampunan dan rezeki yang mulia"},{id:51,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0633\u064e\u0639\u064e\u0648\u06e1\u0627\u0652 \u0641\u0650\u064a\u0653 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0645\u064f\u0639\u064e\u0670\u062c\u0650\u0632\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u06e1\u062c\u064e\u062d\u0650\u064a\u0645\u0650",translation:"Tetapi orang-orang yang berusaha menentang ayat-ayat Kami dengan maksud melemahkan (kemauan untuk beriman), mereka itulah penghuni-penghuni neraka Jahim"},{id:52,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064e \u0645\u0650\u0646 \u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0656 \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0628\u0650\u064a\u0651\u064d \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0625\u0650\u0630\u064e\u0627 \u062a\u064e\u0645\u064e\u0646\u0651\u064e\u0649\u0670\u0653 \u0623\u064e\u0644\u06e1\u0642\u064e\u0649 \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u064f \u0641\u0650\u064a\u0653 \u0623\u064f\u0645\u06e1\u0646\u0650\u064a\u0651\u064e\u062a\u0650\u0647\u0650\u06e6 \u0641\u064e\u064a\u064e\u0646\u0633\u064e\u062e\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0627 \u064a\u064f\u0644\u06e1\u0642\u0650\u064a \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u064f \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u062d\u06e1\u0643\u0650\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0647\u0650\u06e6\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u065e",translation:"Dan Kami tidak mengutus seorang rasul dan tidak (pula) seorang nabi sebelum engkau (Muhammad), melainkan apabila dia mempunyai suatu keinginan,549) setan pun memasukkan godaan-godaan ke dalam keinginannya itu. Tetapi Allah menghilangkan apa yang dimasukkan setan itu, dan Allah akan menguatkan ayat-ayat-Nya. Dan Allah Maha Mengetahui, Mahabijaksana"},{id:53,text:"\u0644\u0651\u0650\u064a\u064e\u062c\u06e1\u0639\u064e\u0644\u064e \u0645\u064e\u0627 \u064a\u064f\u0644\u06e1\u0642\u0650\u064a \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u064f \u0641\u0650\u062a\u06e1\u0646\u064e\u0629\u0657 \u0644\u0651\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645 \u0645\u0651\u064e\u0631\u064e\u0636\u065e \u0648\u064e\u0671\u0644\u06e1\u0642\u064e\u0627\u0633\u0650\u064a\u064e\u0629\u0650 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u06e1\u06d7 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0644\u064e\u0641\u0650\u064a \u0634\u0650\u0642\u064e\u0627\u0642\u0650\u06ed \u0628\u064e\u0639\u0650\u064a\u062f\u0656",translation:"Dia (Allah) ingin menjadikan godaan yang ditimbulkan setan itu sebagai cobaan bagi orang-orang yang dalam hatinya ada penyakit dan orang yang berhati keras. Dan orang-orang yang zalim itu benar-benar dalam permusuhan yang jauh"},{id:54,text:"\u0648\u064e\u0644\u0650\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0639\u0650\u0644\u06e1\u0645\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064e \u0641\u064e\u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6 \u0641\u064e\u062a\u064f\u062e\u06e1\u0628\u0650\u062a\u064e \u0644\u064e\u0647\u064f\u06e5 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u06e1\u06d7 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0647\u064e\u0627\u062f\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0670\u0637\u0656 \u0645\u0651\u064f\u0633\u06e1\u062a\u064e\u0642\u0650\u064a\u0645\u0656",translation:"dan agar orang-orang yang telah diberi ilmu meyakini bahwa (Alquran) itu benar dari Tuhanmu lalu mereka beriman dan hati mereka tunduk kepadanya. Dan sungguh, Allah pemberi petunjuk bagi orang-orang yang beriman kepada jalan yang lurus"},{id:55,text:"\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0632\u064e\u0627\u0644\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0645\u0650\u0631\u06e1\u064a\u064e\u0629\u0656 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064f \u0628\u064e\u063a\u06e1\u062a\u064e\u0629\u064b \u0623\u064e\u0648\u06e1 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064f \u064a\u064e\u0648\u06e1\u0645\u064d \u0639\u064e\u0642\u0650\u064a\u0645\u064d",translation:"Dan orang-orang kafir itu senantiasa ragu mengenai hal itu (Alquran), hingga saat (kematiannya) datang kepada mereka dengan tiba-tiba, atau azab hari Kiamat yang datang kepada mereka"},{id:56,text:"\u0671\u0644\u06e1\u0645\u064f\u0644\u06e1\u0643\u064f \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u0644\u0651\u0650\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u062d\u06e1\u0643\u064f\u0645\u064f \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1\u06da \u0641\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0641\u0650\u064a \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0650 \u0671\u0644\u0646\u0651\u064e\u0639\u0650\u064a\u0645\u0650",translation:"Kekuasaan pada hari itu ada pada Allah, Dia memberi keputusan di antara mereka. Maka orang-orang yang beriman dan mengerjakan kebajikan berada dalam surga-surga yang penuh kenikmatan"},{id:57,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u065e \u0645\u0651\u064f\u0647\u0650\u064a\u0646\u065e",translation:"Dan orang-orang kafir dan yang mendustakan ayat-ayat Kami, mereka akan merasakan azab yang menghinakan"},{id:58,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064e\u0627\u062c\u064e\u0631\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062b\u064f\u0645\u0651\u064e \u0642\u064f\u062a\u0650\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0648\u06e1 \u0645\u064e\u0627\u062a\u064f\u0648\u0627\u0652 \u0644\u064e\u064a\u064e\u0631\u06e1\u0632\u064f\u0642\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0631\u0650\u0632\u06e1\u0642\u064b\u0627 \u062d\u064e\u0633\u064e\u0646\u0657\u0627\u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0647\u064f\u0648\u064e \u062e\u064e\u064a\u06e1\u0631\u064f \u0671\u0644\u0631\u0651\u064e\u0640\u0670\u0632\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Dan orang-orang yang berhijrah di jalan Allah, kemudian mereka terbunuh atau mati, sungguh, Allah akan memberikan kepada mereka rezeki yang baik (surga). Dan sesungguhnya Allah adalah pemberi rezeki yang terbaik"},{id:59,text:"\u0644\u064e\u064a\u064f\u062f\u06e1\u062e\u0650\u0644\u064e\u0646\u0651\u064e\u0647\u064f\u0645 \u0645\u0651\u064f\u062f\u06e1\u062e\u064e\u0644\u0657\u0627 \u064a\u064e\u0631\u06e1\u0636\u064e\u0648\u06e1\u0646\u064e\u0647\u064f\u06e5\u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0639\u064e\u0644\u0650\u064a\u0645\u064c \u062d\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Sungguh, Dia (Allah) pasti akan memasukkan mereka ke tempat masuk (surga) yang mereka sukai. Dan sesungguhnya Allah Maha Mengetahui, Maha Penyantun"},{id:60,text:"\u06de\u0630\u064e\u0670\u0644\u0650\u0643\u064e\u06d6 \u0648\u064e\u0645\u064e\u0646\u06e1 \u0639\u064e\u0627\u0642\u064e\u0628\u064e \u0628\u0650\u0645\u0650\u062b\u06e1\u0644\u0650 \u0645\u064e\u0627 \u0639\u064f\u0648\u0642\u0650\u0628\u064e \u0628\u0650\u0647\u0650\u06e6 \u062b\u064f\u0645\u0651\u064e \u0628\u064f\u063a\u0650\u064a\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0644\u064e\u064a\u064e\u0646\u0635\u064f\u0631\u064e\u0646\u0651\u064e\u0647\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0639\u064e\u0641\u064f\u0648\u0651\u064c \u063a\u064e\u0641\u064f\u0648\u0631\u065e",translation:"Demikianlah, dan barangsiapa membalas setimpal dengan penganiayaan yang pernah dia derita kemudian dia terzalimi (lagi), pasti Allah akan menolongnya. Sungguh, Allah Maha Pemaaf, Maha Pengampun"},{id:61,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u0648\u0644\u0650\u062c\u064f \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u064e \u0641\u0650\u064a \u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u0648\u064e\u064a\u064f\u0648\u0644\u0650\u062c\u064f \u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u0641\u0650\u064a \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u0650 \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0633\u064e\u0645\u0650\u064a\u0639\u064f\u06e2 \u0628\u064e\u0635\u0650\u064a\u0631\u065e",translation:"Demikianlah karena Allah (kuasa) memasukkan malam ke dalam siang dan memasukkan siang ke dalam malam, dan sungguh, Allah Maha mendengar, Maha Melihat"},{id:62,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0645\u064e\u0627 \u064a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u06e6 \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0628\u064e\u0670\u0637\u0650\u0644\u064f \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0639\u064e\u0644\u0650\u064a\u0651\u064f \u0671\u0644\u06e1\u0643\u064e\u0628\u0650\u064a\u0631\u064f",translation:"Demikianlah (kebesaran Allah) karena Allah, Dialah (Tuhan) Yang Hak. Dan apa saja yang mereka seru selain Dia, itulah yang batil, dan sungguh Allah, Dialah Yang Mahatinggi, Mahabesar"},{id:63,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0631\u064e \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0645\u064e\u0627\u0653\u0621\u0657 \u0641\u064e\u062a\u064f\u0635\u06e1\u0628\u0650\u062d\u064f \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064f \u0645\u064f\u062e\u06e1\u0636\u064e\u0631\u0651\u064e\u0629\u064b\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0637\u0650\u064a\u0641\u064c \u062e\u064e\u0628\u0650\u064a\u0631\u065e",translation:"Tidakkah engkau memperhatikan bahwa Allah menurunkan air (hujan) dari langit, sehingga bumi menjadi hijau? Sungguh, Allah Mahahalus, Maha Mengetahui"},{id:64,text:"\u0644\u0651\u064e\u0647\u064f\u06e5 \u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u063a\u064e\u0646\u0650\u064a\u0651\u064f \u0671\u0644\u06e1\u062d\u064e\u0645\u0650\u064a\u062f\u064f",translation:"Milik-Nyalah apa yang ada di langit dan apa yang ada di bumi. Dan Allah benar-benar Mahakaya, Maha Terpuji"},{id:65,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0631\u064e \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0633\u064e\u062e\u0651\u064e\u0631\u064e \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0671\u0644\u06e1\u0641\u064f\u0644\u06e1\u0643\u064e \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0641\u0650\u064a \u0671\u0644\u06e1\u0628\u064e\u062d\u06e1\u0631\u0650 \u0628\u0650\u0623\u064e\u0645\u06e1\u0631\u0650\u0647\u0650\u06e6 \u0648\u064e\u064a\u064f\u0645\u06e1\u0633\u0650\u0643\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u064e \u0623\u064e\u0646 \u062a\u064e\u0642\u064e\u0639\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0625\u0650\u0630\u06e1\u0646\u0650\u0647\u0650\u06e6\u0653\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0631\u064e\u0621\u064f\u0648\u0641\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u065e",translation:"Tidakkah engkau memperhatikan bahwa Allah menundukkan bagimu (manusia) apa yang ada di bumi, dan kapal yang berlayar di lautan dengan perintah-Nya. Dan Dia menahan (benda-benda) langit agar tidak jatuh ke bumi, melainkan dengan izin-Nya? Sungguh, Allah Maha Pengasih, Maha Penyayang kepada manusia"},{id:66,text:"\u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064e\u062d\u06e1\u064a\u064e\u0627\u0643\u064f\u0645\u06e1 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0645\u0650\u064a\u062a\u064f\u0643\u064f\u0645\u06e1 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u062d\u06e1\u064a\u0650\u064a\u0643\u064f\u0645\u06e1\u06d7 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064e \u0644\u064e\u0643\u064e\u0641\u064f\u0648\u0631\u065e",translation:"Dan Dialah yang menghidupkan kamu, kemudian mematikan kamu, kemudian menghidupkan kamu kembali (pada hari kebangkitan). Sungguh, manusia itu sangat kufur nikmat"},{id:67,text:"\u0644\u0651\u0650\u0643\u064f\u0644\u0651\u0650 \u0623\u064f\u0645\u0651\u064e\u0629\u0656 \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0645\u064e\u0646\u0633\u064e\u0643\u064b\u0627 \u0647\u064f\u0645\u06e1 \u0646\u064e\u0627\u0633\u0650\u0643\u064f\u0648\u0647\u064f\u06d6 \u0641\u064e\u0644\u064e\u0627 \u064a\u064f\u0646\u064e\u0670\u0632\u0650\u0639\u064f\u0646\u0651\u064e\u0643\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0631\u0650\u06da \u0648\u064e\u0671\u062f\u06e1\u0639\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u064e\u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u0639\u064e\u0644\u064e\u0649\u0670 \u0647\u064f\u062f\u0657\u0649 \u0645\u0651\u064f\u0633\u06e1\u062a\u064e\u0642\u0650\u064a\u0645\u0656",translation:"Bagi setiap umat telah Kami tetapkan syariat tertentu yang (harus) mereka amalkan, maka tidak sepantasnya mereka berbantahan dengan engkau dalam urusan (syariat) ini, dan serulah (mereka) kepada Tuhanmu. Sungguh, engkau (Muhammad) berada di jalan yang lurus"},{id:68,text:"\u0648\u064e\u0625\u0650\u0646 \u062c\u064e\u0670\u062f\u064e\u0644\u064f\u0648\u0643\u064e \u0641\u064e\u0642\u064f\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan jika mereka membantah engkau, maka katakanlah, \"Allah lebih tahu tentang apa yang kamu kerjakan"},{id:69,text:"\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u062d\u06e1\u0643\u064f\u0645\u064f \u0628\u064e\u064a\u06e1\u0646\u064e\u0643\u064f\u0645\u06e1 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u0641\u0650\u064a\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u0650 \u062a\u064e\u062e\u06e1\u062a\u064e\u0644\u0650\u0641\u064f\u0648\u0646\u064e",translation:"Allah akan mengadili di antara kamu pada hari Kiamat tentang apa yang dahulu kamu perselisihkan"},{id:70,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u06e1 \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06da \u0625\u0650\u0646\u0651\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u0650\u064a \u0643\u0650\u062a\u064e\u0670\u0628\u064d\u06da \u0625\u0650\u0646\u0651\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u0633\u0650\u064a\u0631\u065e",translation:"Tidakkah engkau tahu bahwa Allah mengetahui apa yang di langit dan di bumi? Sungguh, Yang demikian itu sudah terdapat dalam suatu Kitab (Lau\u1e25 Ma\u1e25f\u016b\u1e93). Sesungguhnya yang demikian itu sangat mudah bagi Allah"},{id:71,text:"\u0648\u064e\u064a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0645\u06e1 \u064a\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u06e1 \u0628\u0650\u0647\u0650\u06e6 \u0633\u064f\u0644\u06e1\u0637\u064e\u0670\u0646\u0657\u0627 \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u064a\u06e1\u0633\u064e \u0644\u064e\u0647\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6 \u0639\u0650\u0644\u06e1\u0645\u065e\u06d7 \u0648\u064e\u0645\u064e\u0627 \u0644\u0650\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0646\u0651\u064e\u0635\u0650\u064a\u0631\u0656",translation:"Dan mereka menyembah selain Allah, tanpa dasar yang jelas tentang itu, dan mereka tidak mempunyai pengetahuan (pula) tentang itu. Bagi orang-orang yang zalim tidak ada seorang penolong pun"},{id:72,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062a\u064f\u062a\u06e1\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u064f\u0646\u064e\u0627 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0656 \u062a\u064e\u0639\u06e1\u0631\u0650\u0641\u064f \u0641\u0650\u064a \u0648\u064f\u062c\u064f\u0648\u0647\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0645\u064f\u0646\u0643\u064e\u0631\u064e\u06d6 \u064a\u064e\u0643\u064e\u0627\u062f\u064f\u0648\u0646\u064e \u064a\u064e\u0633\u06e1\u0637\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062a\u06e1\u0644\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627\u06d7 \u0642\u064f\u0644\u06e1 \u0623\u064e\u0641\u064e\u0623\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0643\u064f\u0645 \u0628\u0650\u0634\u064e\u0631\u0651\u0656 \u0645\u0651\u0650\u0646 \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u064f\u06da \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u064f \u0648\u064e\u0639\u064e\u062f\u064e\u0647\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652\u06d6 \u0648\u064e\u0628\u0650\u0626\u06e1\u0633\u064e \u0671\u0644\u06e1\u0645\u064e\u0635\u0650\u064a\u0631\u064f",translation:"Dan apabila dibacakan di hadapan mereka ayat-ayat Kami yang terang, niscaya engkau akan melihat (tanda-tanda) keingkaran pada wajah orang-orang kafir itu. Hampir-hampir mereka menyerang orang-orang yang membacakan ayat-ayat Kami kepada mereka. Katakanlah (Muhammad), \"Apakah akan aku kabarkan kepadamu (mengenai sesuatu) yang lebih buruk daripada itu, (yaitu) neraka?\" Allah telah mengancamkannya (neraka) kepada orang-orang kafir. Dan (neraka itu) seburuk-buruk tempat kembali"},{id:73,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0636\u064f\u0631\u0650\u0628\u064e \u0645\u064e\u062b\u064e\u0644\u065e \u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u0645\u0650\u0639\u064f\u0648\u0627\u0652 \u0644\u064e\u0647\u064f\u06e5\u0653\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0646 \u064a\u064e\u062e\u06e1\u0644\u064f\u0642\u064f\u0648\u0627\u0652 \u0630\u064f\u0628\u064e\u0627\u0628\u0657\u0627 \u0648\u064e\u0644\u064e\u0648\u0650 \u0671\u062c\u06e1\u062a\u064e\u0645\u064e\u0639\u064f\u0648\u0627\u0652 \u0644\u064e\u0647\u064f\u06e5\u06d6 \u0648\u064e\u0625\u0650\u0646 \u064a\u064e\u0633\u06e1\u0644\u064f\u0628\u06e1\u0647\u064f\u0645\u064f \u0671\u0644\u0630\u0651\u064f\u0628\u064e\u0627\u0628\u064f \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627 \u0644\u0651\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0646\u0642\u0650\u0630\u064f\u0648\u0647\u064f \u0645\u0650\u0646\u06e1\u0647\u064f\u06da \u0636\u064e\u0639\u064f\u0641\u064e \u0671\u0644\u0637\u0651\u064e\u0627\u0644\u0650\u0628\u064f \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u0637\u06e1\u0644\u064f\u0648\u0628\u064f",translation:"Wahai manusia! Telah dibuat suatu perumpamaan. Maka dengarkanlah! Sesungguhnya segala yang kamu seru selain Allah tidak dapat menciptakan seekor lalat pun, walaupun mereka bersatu untuk menciptakannya. Dan jika lalat itu merampas sesuatu dari mereka, mereka tidak akan dapat merebutnya kembali dari lalat itu. Sama lemahnya yang menyembah dan yang di sembah"},{id:74,text:"\u0645\u064e\u0627 \u0642\u064e\u062f\u064e\u0631\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u062d\u064e\u0642\u0651\u064e \u0642\u064e\u062f\u06e1\u0631\u0650\u0647\u0650\u06e6\u0653\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0642\u064e\u0648\u0650\u064a\u0651\u064c \u0639\u064e\u0632\u0650\u064a\u0632\u064c",translation:"Mereka tidak mengagungkan Allah dengan sebenar-benarnya. Sungguh, Allah Mahakuat, Mahaperkasa"},{id:75,text:"\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0635\u06e1\u0637\u064e\u0641\u0650\u064a \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u0650 \u0631\u064f\u0633\u064f\u0644\u0657\u0627 \u0648\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0633\u064e\u0645\u0650\u064a\u0639\u064f\u06e2 \u0628\u064e\u0635\u0650\u064a\u0631\u065e",translation:"Allah memilih para utusan(-Nya) dari malaikat dan dari manusia. Sesungguhnya Allah Maha Mendengar, Maha Melihat"},{id:76,text:"\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u0647\u0650\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u06e1\u0641\u064e\u0647\u064f\u0645\u06e1\u06da \u0648\u064e\u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064f\u0631\u06e1\u062c\u064e\u0639\u064f \u0671\u0644\u06e1\u0623\u064f\u0645\u064f\u0648\u0631\u064f",translation:"Dia (Allah) mengetahui apa yang di hadapan mereka dan apa yang di belakang mereka. Dan hanya kepada Allah dikembalikan segala urusan"},{id:77,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0671\u0631\u06e1\u0643\u064e\u0639\u064f\u0648\u0627\u0652 \u0648\u064e\u0671\u0633\u06e1\u062c\u064f\u062f\u064f\u0648\u0627\u0652\u06e4 \u0648\u064e\u0671\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0627\u0652 \u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0671\u0641\u06e1\u0639\u064e\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u062e\u064e\u064a\u06e1\u0631\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064f\u0641\u06e1\u0644\u0650\u062d\u064f\u0648\u0646\u064e\u06e9",translation:"Wahai orang-orang yang beriman! Rukuklah, sujudlah, dan sembahlah Tuhanmu; dan berbuatlah kebaikan, agar kamu beruntung"},{id:78,text:"\u0648\u064e\u062c\u064e\u0670\u0647\u0650\u062f\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u064e\u0642\u0651\u064e \u062c\u0650\u0647\u064e\u0627\u062f\u0650\u0647\u0650\u06e6\u06da \u0647\u064f\u0648\u064e \u0671\u062c\u06e1\u062a\u064e\u0628\u064e\u0649\u0670\u0643\u064f\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u0650 \u0645\u0650\u0646\u06e1 \u062d\u064e\u0631\u064e\u062c\u0656\u06da \u0645\u0651\u0650\u0644\u0651\u064e\u0629\u064e \u0623\u064e\u0628\u0650\u064a\u0643\u064f\u0645\u06e1 \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064e\u06da \u0647\u064f\u0648\u064e \u0633\u064e\u0645\u0651\u064e\u0649\u0670\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064f\u0633\u06e1\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f \u0648\u064e\u0641\u0650\u064a \u0647\u064e\u0670\u0630\u064e\u0627 \u0644\u0650\u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064f \u0634\u064e\u0647\u0650\u064a\u062f\u064b\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0648\u064e\u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u0634\u064f\u0647\u064e\u062f\u064e\u0627\u0653\u0621\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650\u06da \u0641\u064e\u0623\u064e\u0642\u0650\u064a\u0645\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u0621\u064e\u0627\u062a\u064f\u0648\u0627\u0652 \u0671\u0644\u0632\u0651\u064e\u0643\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u0671\u0639\u06e1\u062a\u064e\u0635\u0650\u0645\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0647\u064f\u0648\u064e \u0645\u064e\u0648\u06e1\u0644\u064e\u0649\u0670\u0643\u064f\u0645\u06e1\u06d6 \u0641\u064e\u0646\u0650\u0639\u06e1\u0645\u064e \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u0644\u064e\u0649\u0670 \u0648\u064e\u0646\u0650\u0639\u06e1\u0645\u064e \u0671\u0644\u0646\u0651\u064e\u0635\u0650\u064a\u0631\u064f",translation:"Dan berjihadlah kamu di jalan Allah dengan jihad yang sebenar-benarnya. Dia telah memilih kamu, dan Dia tidak menjadikan kesukaran untukmu dalam agama. (Ikutilah) agama nenek moyangmu Ibrahim. Dia (Allah) telah menamakan kamu orang-orang muslim sejak dahulu, dan (begitu pula) dalam (Alquran) ini, agar Rasul (Muhammad) itu menjadi saksi atas dirimu dan agar kamu semua menjadi saksi atas segenap manusia. Maka laksanakanlah salat dan tunaikanlah zakat, dan berpegang teguhlah kepada Allah. Dialah Pelindungmu; Dia sebaik-baik pelindung dan sebaik-baik penolong"}]},{id:23,name:"\u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646",transliteration:"Al-Mu'minun",translation:"Orang-orang Mukmin",type:"meccan",total_verses:118,verses:[{id:1,text:"\u0642\u064e\u062f\u06e1 \u0623\u064e\u0641\u06e1\u0644\u064e\u062d\u064e \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Sungguh beruntung orang-orang yang beriman"},{id:2,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0635\u064e\u0644\u064e\u0627\u062a\u0650\u0647\u0650\u0645\u06e1 \u062e\u064e\u0670\u0634\u0650\u0639\u064f\u0648\u0646\u064e",translation:"(yaitu) orang yang khusyuk dalam salatnya"},{id:3,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645\u06e1 \u0639\u064e\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u063a\u06e1\u0648\u0650 \u0645\u064f\u0639\u06e1\u0631\u0650\u0636\u064f\u0648\u0646\u064e",translation:"dan orang yang menjauhkan diri dari (perbuatan dan perkataan) yang tidak berguna"},{id:4,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645\u06e1 \u0644\u0650\u0644\u0632\u0651\u064e\u0643\u064e\u0648\u0670\u0629\u0650 \u0641\u064e\u0670\u0639\u0650\u0644\u064f\u0648\u0646\u064e",translation:"dan orang yang menunaikan zakat"},{id:5,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645\u06e1 \u0644\u0650\u0641\u064f\u0631\u064f\u0648\u062c\u0650\u0647\u0650\u0645\u06e1 \u062d\u064e\u0670\u0641\u0650\u0638\u064f\u0648\u0646\u064e",translation:"dan orang yang memelihara kemaluannya"},{id:6,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u0650\u0647\u0650\u0645\u06e1 \u0623\u064e\u0648\u06e1 \u0645\u064e\u0627 \u0645\u064e\u0644\u064e\u0643\u064e\u062a\u06e1 \u0623\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u064f\u0647\u064f\u0645\u06e1 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u063a\u064e\u064a\u06e1\u0631\u064f \u0645\u064e\u0644\u064f\u0648\u0645\u0650\u064a\u0646\u064e",translation:"(kecuali terhadap istri-istri mereka atau hamba sahaya yang mereka miliki;550)maka sesungguhnya mereka tidak tercela"},{id:7,text:"\u0641\u064e\u0645\u064e\u0646\u0650 \u0671\u0628\u06e1\u062a\u064e\u063a\u064e\u0649\u0670 \u0648\u064e\u0631\u064e\u0627\u0653\u0621\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0639\u064e\u0627\u062f\u064f\u0648\u0646\u064e",translation:"Tetapi barang siapa mencari di balik itu (zina, dan sebagainya), maka mereka itulah orang-orang yang melampaui batas"},{id:8,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645\u06e1 \u0644\u0650\u0623\u064e\u0645\u064e\u0670\u0646\u064e\u0670\u062a\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0639\u064e\u0647\u06e1\u062f\u0650\u0647\u0650\u0645\u06e1 \u0631\u064e\u0670\u0639\u064f\u0648\u0646\u064e",translation:"Dan (sungguh beruntung) orang yang memelihara amanat-amanat dan janjinya"},{id:9,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0635\u064e\u0644\u064e\u0648\u064e\u0670\u062a\u0650\u0647\u0650\u0645\u06e1 \u064a\u064f\u062d\u064e\u0627\u0641\u0650\u0638\u064f\u0648\u0646\u064e",translation:"serta orang yang memelihara salatnya"},{id:10,text:"\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0648\u064e\u0670\u0631\u0650\u062b\u064f\u0648\u0646\u064e",translation:"Mereka itulah orang yang akan mewarisi"},{id:11,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0631\u0650\u062b\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0641\u0650\u0631\u06e1\u062f\u064e\u0648\u06e1\u0633\u064e \u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u0670\u0644\u0650\u062f\u064f\u0648\u0646\u064e",translation:"(yakni) yang akan mewarisi (surga) Firdaus. Mereka kekal di dalamnya"},{id:12,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u062e\u064e\u0644\u064e\u0642\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064e \u0645\u0650\u0646 \u0633\u064f\u0644\u064e\u0670\u0644\u064e\u0629\u0656 \u0645\u0651\u0650\u0646 \u0637\u0650\u064a\u0646\u0656",translation:"Dan sungguh, Kami telah menciptakan manusia dari saripati (berasal) dari tanah"},{id:13,text:"\u062b\u064f\u0645\u0651\u064e \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f \u0646\u064f\u0637\u06e1\u0641\u064e\u0629\u0657 \u0641\u0650\u064a \u0642\u064e\u0631\u064e\u0627\u0631\u0656 \u0645\u0651\u064e\u0643\u0650\u064a\u0646\u0656",translation:"Kemudian Kami menjadikannya air mani (yang disimpan) dalam tempat yang kokoh (rahim)"},{id:14,text:"\u062b\u064f\u0645\u0651\u064e \u062e\u064e\u0644\u064e\u0642\u06e1\u0646\u064e\u0627 \u0671\u0644\u0646\u0651\u064f\u0637\u06e1\u0641\u064e\u0629\u064e \u0639\u064e\u0644\u064e\u0642\u064e\u0629\u0657 \u0641\u064e\u062e\u064e\u0644\u064e\u0642\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0639\u064e\u0644\u064e\u0642\u064e\u0629\u064e \u0645\u064f\u0636\u06e1\u063a\u064e\u0629\u0657 \u0641\u064e\u062e\u064e\u0644\u064e\u0642\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0645\u064f\u0636\u06e1\u063a\u064e\u0629\u064e \u0639\u0650\u0638\u064e\u0670\u0645\u0657\u0627 \u0641\u064e\u0643\u064e\u0633\u064e\u0648\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0639\u0650\u0638\u064e\u0670\u0645\u064e \u0644\u064e\u062d\u06e1\u0645\u0657\u0627 \u062b\u064f\u0645\u0651\u064e \u0623\u064e\u0646\u0634\u064e\u0623\u06e1\u0646\u064e\u0670\u0647\u064f \u062e\u064e\u0644\u06e1\u0642\u064b\u0627 \u0621\u064e\u0627\u062e\u064e\u0631\u064e\u06da \u0641\u064e\u062a\u064e\u0628\u064e\u0627\u0631\u064e\u0643\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064f \u0671\u0644\u06e1\u062e\u064e\u0670\u0644\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Kemudian, air mani itu Kami jadikan sesuatu yang melekat, lalu sesuatu yang melekat itu Kami jadikan segumpal daging, dan segumpal daging itu lalu Kami jadikan tulang belulang, lalu tulang belulang itu Kami bungkus dengan daging. Kemudian, Kami menjadikannya makhluk yang (berbentuk) lain. Mahasuci Allah, Pencipta yang paling baik"},{id:15,text:"\u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645 \u0628\u064e\u0639\u06e1\u062f\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0645\u064e\u064a\u0651\u0650\u062a\u064f\u0648\u0646\u064e",translation:"Kemudian setelah itu, sungguh kamu pasti mati"},{id:16,text:"\u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u062a\u064f\u0628\u06e1\u0639\u064e\u062b\u064f\u0648\u0646\u064e",translation:"Kemudian, sungguh kamu akan dibangkitkan (dari kuburmu) pada hari Kiamat"},{id:17,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u062e\u064e\u0644\u064e\u0642\u06e1\u0646\u064e\u0627 \u0641\u064e\u0648\u06e1\u0642\u064e\u0643\u064f\u0645\u06e1 \u0633\u064e\u0628\u06e1\u0639\u064e \u0637\u064e\u0631\u064e\u0627\u0653\u0626\u0650\u0642\u064e \u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0639\u064e\u0646\u0650 \u0671\u0644\u06e1\u062e\u064e\u0644\u06e1\u0642\u0650 \u063a\u064e\u0670\u0641\u0650\u0644\u0650\u064a\u0646\u064e",translation:"Dan sungguh, kami telah menciptakan tujuh (lapis) langit di atas kamu, dan Kami tidaklah lengah terhadap ciptaan (Kami)"},{id:18,text:"\u0648\u064e\u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0645\u064e\u0627\u0653\u0621\u064e\u06e2 \u0628\u0650\u0642\u064e\u062f\u064e\u0631\u0656 \u0641\u064e\u0623\u064e\u0633\u06e1\u0643\u064e\u0646\u0651\u064e\u0640\u0670\u0647\u064f \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d6 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0630\u064e\u0647\u064e\u0627\u0628\u0650\u06ed \u0628\u0650\u0647\u0650\u06e6 \u0644\u064e\u0642\u064e\u0670\u062f\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Dan Kami turunkan air dari langit dengan suatu ukuran; lalu Kami jadikan air itu menetap di bumi, dan pasti Kami berkuasa melenyapkannya"},{id:19,text:"\u0641\u064e\u0623\u064e\u0646\u0634\u064e\u0623\u06e1\u0646\u064e\u0627 \u0644\u064e\u0643\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6 \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0656 \u0645\u0651\u0650\u0646 \u0646\u0651\u064e\u062e\u0650\u064a\u0644\u0656 \u0648\u064e\u0623\u064e\u0639\u06e1\u0646\u064e\u0670\u0628\u0656 \u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u0641\u064e\u0648\u064e\u0670\u0643\u0650\u0647\u064f \u0643\u064e\u062b\u0650\u064a\u0631\u064e\u0629\u065e \u0648\u064e\u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u062a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f\u0648\u0646\u064e",translation:"Lalu dengan (air) itu, Kami tumbuhkan untukmu kebun-kebun kurma dan anggur; di sana kamu memperoleh buah-buahan yang banyak dan sebagian dari (buah-buahan) itu kamu makan"},{id:20,text:"\u0648\u064e\u0634\u064e\u062c\u064e\u0631\u064e\u0629\u0657 \u062a\u064e\u062e\u06e1\u0631\u064f\u062c\u064f \u0645\u0650\u0646 \u0637\u064f\u0648\u0631\u0650 \u0633\u064e\u064a\u06e1\u0646\u064e\u0627\u0653\u0621\u064e \u062a\u064e\u0646\u06e2\u0628\u064f\u062a\u064f \u0628\u0650\u0671\u0644\u062f\u0651\u064f\u0647\u06e1\u0646\u0650 \u0648\u064e\u0635\u0650\u0628\u06e1\u063a\u0656 \u0644\u0651\u0650\u0644\u06e1\u0623\u0653\u0643\u0650\u0644\u0650\u064a\u0646\u064e",translation:"dan (Kami tumbuhkan) pohon (zaitun) yang tumbuh dari gunung Sinai, yang menghasilkan minyak, dan bahan pembangkit selera bagi orang-orang yang makan"},{id:21,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0644\u064e\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0639\u064e\u0670\u0645\u0650 \u0644\u064e\u0639\u0650\u0628\u06e1\u0631\u064e\u0629\u0657\u06d6 \u0646\u0651\u064f\u0633\u06e1\u0642\u0650\u064a\u0643\u064f\u0645 \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u0641\u0650\u064a \u0628\u064f\u0637\u064f\u0648\u0646\u0650\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u064e\u0646\u064e\u0670\u0641\u0650\u0639\u064f \u0643\u064e\u062b\u0650\u064a\u0631\u064e\u0629\u065e \u0648\u064e\u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u062a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f\u0648\u0646\u064e",translation:"Dan sungguh pada hewan-hewan ternak terdapat suatu pelajaran bagimu. Kami memberi minum kamu dari (air susu) yang ada dalam perutnya, dan padanya juga terdapat banyak manfaat untukmu, dan sebagian darinya kamu makan"},{id:22,text:"\u0648\u064e\u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627 \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0641\u064f\u0644\u06e1\u0643\u0650 \u062a\u064f\u062d\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"atasnya (hewan-hewan ternak), dan di atas kapal-kapal kamu diangkut"},{id:23,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0646\u064f\u0648\u062d\u064b\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u06e6 \u0641\u064e\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0625\u0650\u0644\u064e\u0670\u0647\u064d \u063a\u064e\u064a\u06e1\u0631\u064f\u0647\u064f\u06e5\u0653\u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",translation:"Dan sungguh, Kami telah mengutus Nuh kepada kaumnya, lalu dia berkata, \"Wahai kaumku! Sembahlah Allah, (karena) tidak ada tuhan (yang berhak disembah) bagimu selain Dia. Maka mengapa kamu tidak bertakwa (kepada-Nya)"},{id:24,text:"\u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0624\u064f\u0627\u0652 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u06e6 \u0645\u064e\u0627 \u0647\u064e\u0670\u0630\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u064e\u0634\u064e\u0631\u065e \u0645\u0651\u0650\u062b\u06e1\u0644\u064f\u0643\u064f\u0645\u06e1 \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0623\u064e\u0646 \u064a\u064e\u062a\u064e\u0641\u064e\u0636\u0651\u064e\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0648\u06e1 \u0634\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u0657 \u0645\u0651\u064e\u0627 \u0633\u064e\u0645\u0650\u0639\u06e1\u0646\u064e\u0627 \u0628\u0650\u0647\u064e\u0670\u0630\u064e\u0627 \u0641\u0650\u064a\u0653 \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0626\u0650\u0646\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",translation:"Maka berkatalah para pemuka orang kafir dari kaumnya, \"Orang ini tidak lain hanyalah manusia seperti kamu, yang ingin menjadi orang yang lebih mulia dari kamu. Dan seandainya Allah menghendaki, tentu Dia mengutus malaikat. Belum pernah kami mendengar (seruan yang seperti) ini pada (masa) nenek moyang kami yang dahulu"},{id:25,text:"\u0625\u0650\u0646\u06e1 \u0647\u064f\u0648\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0631\u064e\u062c\u064f\u0644\u064f\u06e2 \u0628\u0650\u0647\u0650\u06e6 \u062c\u0650\u0646\u0651\u064e\u0629\u065e \u0641\u064e\u062a\u064e\u0631\u064e\u0628\u0651\u064e\u0635\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062d\u0650\u064a\u0646\u0656",translation:"Dia hanyalah seorang laki-laki yang gila, maka tunggulah (sabarlah) terhadapnya sampai waktu yang ditentukan"},{id:26,text:"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0671\u0646\u0635\u064f\u0631\u06e1\u0646\u0650\u064a \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0646\u0650",translation:"Dia (Nuh) berdoa, \"Ya Tuhanku, tolonglah aku, karena mereka mendustakan aku"},{id:27,text:"\u0641\u064e\u0623\u064e\u0648\u06e1\u062d\u064e\u064a\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0623\u064e\u0646\u0650 \u0671\u0635\u06e1\u0646\u064e\u0639\u0650 \u0671\u0644\u06e1\u0641\u064f\u0644\u06e1\u0643\u064e \u0628\u0650\u0623\u064e\u0639\u06e1\u064a\u064f\u0646\u0650\u0646\u064e\u0627 \u0648\u064e\u0648\u064e\u062d\u06e1\u064a\u0650\u0646\u064e\u0627 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e \u0623\u064e\u0645\u06e1\u0631\u064f\u0646\u064e\u0627 \u0648\u064e\u0641\u064e\u0627\u0631\u064e \u0671\u0644\u062a\u0651\u064e\u0646\u0651\u064f\u0648\u0631\u064f \u0641\u064e\u0671\u0633\u06e1\u0644\u064f\u0643\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u0650\u0646 \u0643\u064f\u0644\u0651\u0656 \u0632\u064e\u0648\u06e1\u062c\u064e\u064a\u06e1\u0646\u0650 \u0671\u062b\u06e1\u0646\u064e\u064a\u06e1\u0646\u0650 \u0648\u064e\u0623\u064e\u0647\u06e1\u0644\u064e\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646 \u0633\u064e\u0628\u064e\u0642\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0644\u064f \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u062e\u064e\u0670\u0637\u0650\u0628\u06e1\u0646\u0650\u064a \u0641\u0650\u064a \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645 \u0645\u0651\u064f\u063a\u06e1\u0631\u064e\u0642\u064f\u0648\u0646\u064e",translation:"Lalu Kami wahyukan kepadanya, \"Buatlah kapal di bawah pengawasan dan petunjuk Kami, maka apabila perintah Kami datang dan tanur (dapur) telah memancarkan air, maka masukkanlah ke dalam (kapal) itu sepasang-sepasang dari setiap jenis, juga keluargamu, kecuali orang yang lebih dahulu ditetapkan (akan ditimpa siksaan) di antara mereka. Dan janganlah engkau bicarakan dengan-Ku tentang orang-orang yang zalim, sesungguhnya mereka itu akan ditenggelamkan"},{id:28,text:"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0671\u0633\u06e1\u062a\u064e\u0648\u064e\u064a\u06e1\u062a\u064e \u0623\u064e\u0646\u062a\u064e \u0648\u064e\u0645\u064e\u0646 \u0645\u0651\u064e\u0639\u064e\u0643\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0641\u064f\u0644\u06e1\u0643\u0650 \u0641\u064e\u0642\u064f\u0644\u0650 \u0671\u0644\u06e1\u062d\u064e\u0645\u06e1\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0646\u064e\u062c\u0651\u064e\u0649\u0670\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dan apabila engkau dan orang-orang yang bersamamu telah berada di atas kapal, maka ucapkanlah, \"Segala puji bagi Allah yang telah menyelamatkan kami dari orang-orang yang zalim"},{id:29,text:"\u0648\u064e\u0642\u064f\u0644 \u0631\u0651\u064e\u0628\u0651\u0650 \u0623\u064e\u0646\u0632\u0650\u0644\u06e1\u0646\u0650\u064a \u0645\u064f\u0646\u0632\u064e\u0644\u0657\u0627 \u0645\u0651\u064f\u0628\u064e\u0627\u0631\u064e\u0643\u0657\u0627 \u0648\u064e\u0623\u064e\u0646\u062a\u064e \u062e\u064e\u064a\u06e1\u0631\u064f \u0671\u0644\u06e1\u0645\u064f\u0646\u0632\u0650\u0644\u0650\u064a\u0646\u064e",translation:"Dan berdoalah, \"Ya Tuhanku, tempatkanlah aku pada tempat yang diberkahi, dan Engkau adalah sebaik-baik pemberi tempat"},{id:30,text:"\u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0623\u0653\u064a\u064e\u0670\u062a\u0656 \u0648\u064e\u0625\u0650\u0646 \u0643\u064f\u0646\u0651\u064e\u0627 \u0644\u064e\u0645\u064f\u0628\u06e1\u062a\u064e\u0644\u0650\u064a\u0646\u064e",translation:"Sungguh, pada (kejadian) itu benar-benar terdapat tanda-tanda (kebesaran Allah); dan sesungguhnya Kami benar-benar menimpakan siksaan (kepada kaum Nuh)"},{id:31,text:"\u062b\u064f\u0645\u0651\u064e \u0623\u064e\u0646\u0634\u064e\u0623\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u0647\u0650\u0645\u06e1 \u0642\u064e\u0631\u06e1\u0646\u064b\u0627 \u0621\u064e\u0627\u062e\u064e\u0631\u0650\u064a\u0646\u064e",translation:"Kemudian setelah mereka, Kami ciptakan umat yang lain (kaum '\u0100d)"},{id:32,text:"\u0641\u064e\u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u0650\u0645\u06e1 \u0631\u064e\u0633\u064f\u0648\u0644\u0657\u0627 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0623\u064e\u0646\u0650 \u0671\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0625\u0650\u0644\u064e\u0670\u0647\u064d \u063a\u064e\u064a\u06e1\u0631\u064f\u0647\u064f\u06e5\u0653\u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",translation:"Lalu Kami utus kepada mereka seorang rasul dari kalangan mereka sendiri (yang berkata), \"Sembahlah Allah! Tidak ada tuhan (yang berhak disembah) bagimu selain Dia. Maka mengapa kamu tidak bertakwa (kepada-Nya)"},{id:33,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0623\u064f \u0645\u0650\u0646 \u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0644\u0650\u0642\u064e\u0627\u0653\u0621\u0650 \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0648\u064e\u0623\u064e\u062a\u06e1\u0631\u064e\u0641\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u0650 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0645\u064e\u0627 \u0647\u064e\u0670\u0630\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u064e\u0634\u064e\u0631\u065e \u0645\u0651\u0650\u062b\u06e1\u0644\u064f\u0643\u064f\u0645\u06e1 \u064a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f \u0645\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u06e1\u0647\u064f \u0648\u064e\u064a\u064e\u0634\u06e1\u0631\u064e\u0628\u064f \u0645\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0634\u06e1\u0631\u064e\u0628\u064f\u0648\u0646\u064e",translation:"Dan berkatalah para pemuka orang kafir dari kaumnya dan yang mendustakan pertemuan hari akhirat serta mereka yang telah Kami beri kemewahan dan kesenangan dalam kehidupan di dunia, \"(Orang) ini tidak lain hanyalah manusia seperti kamu, dia makan apa yang kamu makan, dan dia minum apa yang kamu minum"},{id:34,text:"\u0648\u064e\u0644\u064e\u0626\u0650\u0646\u06e1 \u0623\u064e\u0637\u064e\u0639\u06e1\u062a\u064f\u0645 \u0628\u064e\u0634\u064e\u0631\u0657\u0627 \u0645\u0651\u0650\u062b\u06e1\u0644\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0630\u0657\u0627 \u0644\u0651\u064e\u062e\u064e\u0670\u0633\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Dan sungguh, jika kamu menaati manusia yang seperti kamu, niscaya kamu merugi"},{id:35,text:"\u0623\u064e\u064a\u064e\u0639\u0650\u062f\u064f\u0643\u064f\u0645\u06e1 \u0623\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0630\u064e\u0627 \u0645\u0650\u062a\u0651\u064f\u0645\u06e1 \u0648\u064e\u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064f\u0631\u064e\u0627\u0628\u0657\u0627 \u0648\u064e\u0639\u0650\u0638\u064e\u0670\u0645\u064b\u0627 \u0623\u064e\u0646\u0651\u064e\u0643\u064f\u0645 \u0645\u0651\u064f\u062e\u06e1\u0631\u064e\u062c\u064f\u0648\u0646\u064e",translation:"adakah dia menjanjikan kepada kamu, bahwa apabila kamu telah mati dan menjadi tanah dan tulang belulang, sesungguhnya kamu akan dikeluarkan (dari kuburmu)"},{id:36,text:"\u06de\u0647\u064e\u064a\u06e1\u0647\u064e\u0627\u062a\u064e \u0647\u064e\u064a\u06e1\u0647\u064e\u0627\u062a\u064e \u0644\u0650\u0645\u064e\u0627 \u062a\u064f\u0648\u0639\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Jauh! Jauh sekali (dari kebenaran) apa yang diancamkan kepada kamu"},{id:37,text:"\u0625\u0650\u0646\u06e1 \u0647\u0650\u064a\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u062d\u064e\u064a\u064e\u0627\u062a\u064f\u0646\u064e\u0627 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0646\u064e\u0645\u064f\u0648\u062a\u064f \u0648\u064e\u0646\u064e\u062d\u06e1\u064a\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u0646\u064e\u062d\u06e1\u0646\u064f \u0628\u0650\u0645\u064e\u0628\u06e1\u0639\u064f\u0648\u062b\u0650\u064a\u0646\u064e",translation:"(kehidupan itu) tidak lain hanyalah kehidupan kita di dunia ini, (di sanalah) kita mati dan hidup551) dan tidak akan dibangkitkan (lagi)"},{id:38,text:"\u0625\u0650\u0646\u06e1 \u0647\u064f\u0648\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0631\u064e\u062c\u064f\u0644\u064c \u0671\u0641\u06e1\u062a\u064e\u0631\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u0630\u0650\u0628\u0657\u0627 \u0648\u064e\u0645\u064e\u0627 \u0646\u064e\u062d\u06e1\u0646\u064f \u0644\u064e\u0647\u064f\u06e5 \u0628\u0650\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dia tidak lain hanyalah seorang laki-laki yang mengada-adakan kebohongan terhadap Allah, dan kita tidak akan mempercayainya"},{id:39,text:"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0671\u0646\u0635\u064f\u0631\u06e1\u0646\u0650\u064a \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0646\u0650",translation:"Dia (Hud) berdoa, \"Ya Tuhanku, tolonglah aku karena mereka mendustakan aku"},{id:40,text:"\u0642\u064e\u0627\u0644\u064e \u0639\u064e\u0645\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u0656 \u0644\u0651\u064e\u064a\u064f\u0635\u06e1\u0628\u0650\u062d\u064f\u0646\u0651\u064e \u0646\u064e\u0670\u062f\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dia (Allah) berfirman, \"Tidak lama lagi mereka pasti akan menyesal"},{id:41,text:"\u0641\u064e\u0623\u064e\u062e\u064e\u0630\u064e\u062a\u06e1\u0647\u064f\u0645\u064f \u0671\u0644\u0635\u0651\u064e\u064a\u06e1\u062d\u064e\u0629\u064f \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0641\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u063a\u064f\u062b\u064e\u0627\u0653\u0621\u0657\u06da \u0641\u064e\u0628\u064f\u0639\u06e1\u062f\u0657\u0627 \u0644\u0651\u0650\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Lalu mereka benar-benar dimusnahkan oleh suara yang mengguntur, dan Kami jadikan mereka (seperti) sampah yang dibawa banjir.552) Maka binasalah orang-orang yang zalim"},{id:42,text:"\u062b\u064f\u0645\u0651\u064e \u0623\u064e\u0646\u0634\u064e\u0623\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u0647\u0650\u0645\u06e1 \u0642\u064f\u0631\u064f\u0648\u0646\u064b\u0627 \u0621\u064e\u0627\u062e\u064e\u0631\u0650\u064a\u0646\u064e",translation:"Kemudian setelah mereka Kami ciptakan umat-umat yang lain"},{id:43,text:"\u0645\u064e\u0627 \u062a\u064e\u0633\u06e1\u0628\u0650\u0642\u064f \u0645\u0650\u0646\u06e1 \u0623\u064f\u0645\u0651\u064e\u0629\u064d \u0623\u064e\u062c\u064e\u0644\u064e\u0647\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0640\u0654\u06e1\u062e\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Tidak ada satu umat pun yang dapat menyegerakan ajalnya, dan tidak (pula) menangguhkannya"},{id:44,text:"\u062b\u064f\u0645\u0651\u064e \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0631\u064f\u0633\u064f\u0644\u064e\u0646\u064e\u0627 \u062a\u064e\u062a\u06e1\u0631\u064e\u0627\u06d6 \u0643\u064f\u0644\u0651\u064e \u0645\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e \u0623\u064f\u0645\u0651\u064e\u0629\u0657 \u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064f\u0647\u064e\u0627 \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0647\u064f\u06d6 \u0641\u064e\u0623\u064e\u062a\u06e1\u0628\u064e\u0639\u06e1\u0646\u064e\u0627 \u0628\u064e\u0639\u06e1\u0636\u064e\u0647\u064f\u0645 \u0628\u064e\u0639\u06e1\u0636\u0657\u0627 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0623\u064e\u062d\u064e\u0627\u062f\u0650\u064a\u062b\u064e\u06da \u0641\u064e\u0628\u064f\u0639\u06e1\u062f\u0657\u0627 \u0644\u0651\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u0644\u0651\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Kemudian, Kami utus rasul-rasul Kami berturut-turut. Setiap kali seorang rasul datang kepada suatu umat, mereka mendustakannya, maka Kami silihgantikan sebagian mereka dengan sebagian yang lain (dalam kebinasaan). Dan Kami jadikan mereka bahan cerita (bagi manusia). Maka binasalah kaum yang tidak beriman"},{id:45,text:"\u062b\u064f\u0645\u0651\u064e \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u0623\u064e\u062e\u064e\u0627\u0647\u064f \u0647\u064e\u0670\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0648\u064e\u0633\u064f\u0644\u06e1\u0637\u064e\u0670\u0646\u0656 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u064d",translation:"Kemudian Kami utus Musa dan saudaranya Harun dengan membawa tanda-tanda (kebesaran) Kami, dan bukti yang nyata"},{id:46,text:"\u0625\u0650\u0644\u064e\u0649\u0670 \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0648\u064e\u0645\u064e\u0644\u064e\u0625\u0650\u064a\u0652\u0647\u0650\u06e6 \u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u064e\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0642\u064e\u0648\u06e1\u0645\u064b\u0627 \u0639\u064e\u0627\u0644\u0650\u064a\u0646\u064e",translation:"kepada Fir'aun dan para pemuka kaumnya, tetapi mereka angkuh dan mereka memang kaum yang sombong"},{id:47,text:"\u0641\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u064f\u0624\u06e1\u0645\u0650\u0646\u064f \u0644\u0650\u0628\u064e\u0634\u064e\u0631\u064e\u064a\u06e1\u0646\u0650 \u0645\u0650\u062b\u06e1\u0644\u0650\u0646\u064e\u0627 \u0648\u064e\u0642\u064e\u0648\u06e1\u0645\u064f\u0647\u064f\u0645\u064e\u0627 \u0644\u064e\u0646\u064e\u0627 \u0639\u064e\u0670\u0628\u0650\u062f\u064f\u0648\u0646\u064e",translation:"Maka mereka berkata, \"Apakah (pantas) kita percaya kepada dua orang manusia seperti kita, padahal kaum mereka (Bani Israil) adalah orang-orang yang menghambakan diri kepada kita"},{id:48,text:"\u0641\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0647\u064f\u0645\u064e\u0627 \u0641\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0647\u06e1\u0644\u064e\u0643\u0650\u064a\u0646\u064e",translation:"Maka mereka mendustakan keduanya, karena itu mereka termasuk orang yang dibinasakan"},{id:49,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0647\u06e1\u062a\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Dan sungguh, telah Kami anugerahkan kepada Musa Kitab (Taurat), agar mereka (Bani Israil) mendapat petunjuk"},{id:50,text:"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0671\u0628\u06e1\u0646\u064e \u0645\u064e\u0631\u06e1\u064a\u064e\u0645\u064e \u0648\u064e\u0623\u064f\u0645\u0651\u064e\u0647\u064f\u06e5\u0653 \u0621\u064e\u0627\u064a\u064e\u0629\u0657 \u0648\u064e\u0621\u064e\u0627\u0648\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u06e1\u0648\u064e\u0629\u0656 \u0630\u064e\u0627\u062a\u0650 \u0642\u064e\u0631\u064e\u0627\u0631\u0656 \u0648\u064e\u0645\u064e\u0639\u0650\u064a\u0646\u0656",translation:"Dan telah Kami jadikan (Isa) putra Maryam bersama ibunya sebagai suatu bukti yang nyata (bagi kebesaran Kami), dan Kami melindungi mereka di suatu dataran tinggi, (tempat yang tenang, rindang dan banyak buah-buahan) dengan mata air yang mengalir"},{id:51,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0631\u0651\u064f\u0633\u064f\u0644\u064f \u0643\u064f\u0644\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u064e \u0671\u0644\u0637\u0651\u064e\u064a\u0651\u0650\u0628\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0627\u0652 \u0635\u064e\u0670\u0644\u0650\u062d\u064b\u0627\u06d6 \u0625\u0650\u0646\u0651\u0650\u064a \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Allah berfirman, \"Wahai para rasul! Makanlah dari (makanan) yang baik-baik, dan kerjakanlah kebajikan. Sungguh, Aku Maha Mengetahui apa yang kamu kerjakan"},{id:52,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0670\u0630\u0650\u0647\u0650\u06e6\u0653 \u0623\u064f\u0645\u0651\u064e\u062a\u064f\u0643\u064f\u0645\u06e1 \u0623\u064f\u0645\u0651\u064e\u0629\u0657 \u0648\u064e\u0670\u062d\u0650\u062f\u064e\u0629\u0657 \u0648\u064e\u0623\u064e\u0646\u064e\u0627\u06e0 \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u06e1 \u0641\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u0650",translation:"Dan sungguh, (agama tauhid) inilah agama kamu, agama yang satu dan Aku adalah Tuhanmu, maka bertakwalah kepada-Ku"},{id:53,text:"\u0641\u064e\u062a\u064e\u0642\u064e\u0637\u0651\u064e\u0639\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0645\u06e1\u0631\u064e\u0647\u064f\u0645 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1 \u0632\u064f\u0628\u064f\u0631\u0657\u0627\u06d6 \u0643\u064f\u0644\u0651\u064f \u062d\u0650\u0632\u06e1\u0628\u0650\u06ed \u0628\u0650\u0645\u064e\u0627 \u0644\u064e\u062f\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0641\u064e\u0631\u0650\u062d\u064f\u0648\u0646\u064e",translation:"Kemudian mereka terpecah belah dalam urusan (agama)nya menjadi beberapa golongan. Setiap golongan (merasa) bangga dengan apa yang ada pada mereka (masing-masing)"},{id:54,text:"\u0641\u064e\u0630\u064e\u0631\u06e1\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u063a\u064e\u0645\u06e1\u0631\u064e\u062a\u0650\u0647\u0650\u0645\u06e1 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062d\u0650\u064a\u0646\u064d",translation:"Maka biarkanlah mereka dalam kesesatannya sampai waktu yang ditentukan"},{id:55,text:"\u0623\u064e\u064a\u064e\u062d\u06e1\u0633\u064e\u0628\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u0646\u064f\u0645\u0650\u062f\u0651\u064f\u0647\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6 \u0645\u0650\u0646 \u0645\u0651\u064e\u0627\u0644\u0656 \u0648\u064e\u0628\u064e\u0646\u0650\u064a\u0646\u064e",translation:"Apakah mereka mengira bahwa Kami memberikan harta dan anak-anak kepada mereka itu (berarti bahwa)"},{id:56,text:"\u0646\u064f\u0633\u064e\u0627\u0631\u0650\u0639\u064f \u0644\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u062e\u064e\u064a\u06e1\u0631\u064e\u0670\u062a\u0650\u06da \u0628\u064e\u0644 \u0644\u0651\u064e\u0627 \u064a\u064e\u0634\u06e1\u0639\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Kami segera memberikan kebaikan-kebaikan kepada mereka? (Tidak), tetapi mereka tidak menyadarinya"},{id:57,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u062e\u064e\u0634\u06e1\u064a\u064e\u0629\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645 \u0645\u0651\u064f\u0634\u06e1\u0641\u0650\u0642\u064f\u0648\u0646\u064e",translation:"Sungguh, orang-orang yang karena takut (azab) Tuhannya, mereka sangat berhati-hati"},{id:58,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"dan mereka yang beriman dengan tanda-tanda (kekuasaan) Tuhannya"},{id:59,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645 \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064f\u0634\u06e1\u0631\u0650\u0643\u064f\u0648\u0646\u064e",translation:"dan mereka tidak mempersekutukan Tuhannya"},{id:60,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0624\u06e1\u062a\u064f\u0648\u0646\u064e \u0645\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u064e\u0648\u0627\u0652 \u0648\u0651\u064e\u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u062c\u0650\u0644\u064e\u0629\u064c \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0631\u064e\u0670\u062c\u0650\u0639\u064f\u0648\u0646\u064e",translation:"dan mereka yang memberikan apa yang mereka berikan (sedekah) dengan hati penuh rasa takut (karena mereka tahu) bahwa sesungguhnya mereka akan kembali kepada Tuhannya"},{id:61,text:"\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u064a\u064f\u0633\u064e\u0670\u0631\u0650\u0639\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u062e\u064e\u064a\u06e1\u0631\u064e\u0670\u062a\u0650 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0647\u064e\u0627 \u0633\u064e\u0670\u0628\u0650\u0642\u064f\u0648\u0646\u064e",translation:"mereka itu bersegera dalam kebaikan-kebaikan, dan merekalah orang-orang yang lebih dahulu memperolehnya"},{id:62,text:"\u0648\u064e\u0644\u064e\u0627 \u0646\u064f\u0643\u064e\u0644\u0651\u0650\u0641\u064f \u0646\u064e\u0641\u06e1\u0633\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0648\u064f\u0633\u06e1\u0639\u064e\u0647\u064e\u0627\u06da \u0648\u064e\u0644\u064e\u062f\u064e\u064a\u06e1\u0646\u064e\u0627 \u0643\u0650\u062a\u064e\u0670\u0628\u065e \u064a\u064e\u0646\u0637\u0650\u0642\u064f \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064f\u0638\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan Kami tidak membebani seseorang melainkan menurut kesanggupannya, dan pada Kami ada suatu catatan yang menuturkan dengan sebenarnya, dan mereka tidak dizalimi (dirugikan)"},{id:63,text:"\u0628\u064e\u0644\u06e1 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u063a\u064e\u0645\u06e1\u0631\u064e\u0629\u0656 \u0645\u0651\u0650\u0646\u06e1 \u0647\u064e\u0670\u0630\u064e\u0627 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u0639\u06e1\u0645\u064e\u0670\u0644\u065e \u0645\u0651\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0647\u064f\u0645\u06e1 \u0644\u064e\u0647\u064e\u0627 \u0639\u064e\u0670\u0645\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Tetapi, hati mereka (orang-orang kafir) itu dalam kesesatan dari (memahami Alquran) ini, dan mereka mempunyai (kebiasaan banyak mengerjakan) perbuatan-perbuatan lain (buruk) yang terus mereka kerjakan"},{id:64,text:"\u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u064e\u0627\u0653 \u0623\u064e\u062e\u064e\u0630\u06e1\u0646\u064e\u0627 \u0645\u064f\u062a\u06e1\u0631\u064e\u0641\u0650\u064a\u0647\u0650\u0645 \u0628\u0650\u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0645\u06e1 \u064a\u064e\u062c\u06e1\u0640\u0654\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Sehingga apabila Kami timpakan siksaan kepada orang-orang yang hidup bermewah-mewah di antara mereka, seketika itu mereka berteriak-teriak meminta tolong"},{id:65,text:"\u0644\u064e\u0627 \u062a\u064e\u062c\u06e1\u0640\u0654\u064e\u0631\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e\u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0627 \u062a\u064f\u0646\u0635\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Janganlah kamu berteriak-teriak meminta tolong pada hari ini! Sungguh, kamu tidak akan mendapat pertolongan dari Kami"},{id:66,text:"\u0642\u064e\u062f\u06e1 \u0643\u064e\u0627\u0646\u064e\u062a\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u064a \u062a\u064f\u062a\u06e1\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0641\u064e\u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0639\u06e1\u0642\u064e\u0670\u0628\u0650\u0643\u064f\u0645\u06e1 \u062a\u064e\u0646\u0643\u0650\u0635\u064f\u0648\u0646\u064e",translation:"Sungguh ayat-ayat-Ku (Alquran) selalu dibacakan kepada kamu, tetapi kamu selalu berpaling ke belakang"},{id:67,text:"\u0645\u064f\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u0650\u0631\u0650\u064a\u0646\u064e \u0628\u0650\u0647\u0650\u06e6 \u0633\u064e\u0670\u0645\u0650\u0631\u0657\u0627 \u062a\u064e\u0647\u06e1\u062c\u064f\u0631\u064f\u0648\u0646\u064e",translation:"dengan menyombongkan diri dan mengucapkan perkataan-perkataan keji terhadapnya (Alquran) pada waktu kamu bercakap-cakap pada malam hari"},{id:68,text:"\u0623\u064e\u0641\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u062f\u0651\u064e\u0628\u0651\u064e\u0631\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0644\u064e \u0623\u064e\u0645\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u0627 \u0644\u064e\u0645\u06e1 \u064a\u064e\u0623\u06e1\u062a\u0650 \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",translation:"Maka tidaklah mereka menghayati firman (Allah), atau adakah telah datang kepada mereka apa yang tidak pernah datang kepada nenek moyang mereka dahulu"},{id:69,text:"\u0623\u064e\u0645\u06e1 \u0644\u064e\u0645\u06e1 \u064a\u064e\u0639\u06e1\u0631\u0650\u0641\u064f\u0648\u0627\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f\u0645\u06e1 \u0641\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0647\u064f\u06e5 \u0645\u064f\u0646\u0643\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Ataukah mereka tidak mengenal Rasul mereka (Muhammad), karena itu mereka mengingkarinya"},{id:70,text:"\u0623\u064e\u0645\u06e1 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u0650\u06e6 \u062c\u0650\u0646\u0651\u064e\u0629\u064f\u06e2\u06da \u0628\u064e\u0644\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064f\u0647\u064f\u0645\u06e1 \u0644\u0650\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0643\u064e\u0670\u0631\u0650\u0647\u064f\u0648\u0646\u064e",translation:"Atau mereka berkata, \"Orang itu (Muhammad) gila.\" Padahal, dia telah datang membawa kebenaran kepada mereka, tetapi kebanyakan mereka membenci kebenaran"},{id:71,text:"\u0648\u064e\u0644\u064e\u0648\u0650 \u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064e \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f \u0623\u064e\u0647\u06e1\u0648\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0641\u064e\u0633\u064e\u062f\u064e\u062a\u0650 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u064f \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064f \u0648\u064e\u0645\u064e\u0646 \u0641\u0650\u064a\u0647\u0650\u0646\u0651\u064e\u06da \u0628\u064e\u0644\u06e1 \u0623\u064e\u062a\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f\u0645 \u0628\u0650\u0630\u0650\u0643\u06e1\u0631\u0650\u0647\u0650\u0645\u06e1 \u0641\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0646 \u0630\u0650\u0643\u06e1\u0631\u0650\u0647\u0650\u0645 \u0645\u0651\u064f\u0639\u06e1\u0631\u0650\u0636\u064f\u0648\u0646\u064e",translation:"Dan seandainya kebenaran itu menuruti keinginan mereka, pasti binasalah langit dan bumi, dan semua yang ada di dalamnya. Bahkan Kami telah memberikan peringatan kepada mereka, tetapi mereka berpaling dari peringatan itu"},{id:72,text:"\u0623\u064e\u0645\u06e1 \u062a\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0647\u064f\u0645\u06e1 \u062e\u064e\u0631\u06e1\u062c\u0657\u0627 \u0641\u064e\u062e\u064e\u0631\u064e\u0627\u062c\u064f \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u062e\u064e\u064a\u06e1\u0631\u065e\u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u062e\u064e\u064a\u06e1\u0631\u064f \u0671\u0644\u0631\u0651\u064e\u0640\u0670\u0632\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Atau engkau (Muhammad) meminta imbalan kepada mereka? Sedangkan imbalan dari Tuhanmu lebih baik, karena Dia pemberi rezeki yang terbaik"},{id:73,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u062a\u064e\u062f\u06e1\u0639\u064f\u0648\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0670\u0637\u0656 \u0645\u0651\u064f\u0633\u06e1\u062a\u064e\u0642\u0650\u064a\u0645\u0656",translation:"Dan sungguh engkau pasti telah menyeru mereka kepada jalan yang lurus"},{id:74,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0639\u064e\u0646\u0650 \u0671\u0644\u0635\u0651\u0650\u0631\u064e\u0670\u0637\u0650 \u0644\u064e\u0646\u064e\u0670\u0643\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Dan sungguh orang-orang yang tidak beriman kepada akhirat benar-benar telah menyimpang jauh dari jalan (yang lurus)"},{id:75,text:"\u06de\u0648\u064e\u0644\u064e\u0648\u06e1 \u0631\u064e\u062d\u0650\u0645\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0648\u064e\u0643\u064e\u0634\u064e\u0641\u06e1\u0646\u064e\u0627 \u0645\u064e\u0627 \u0628\u0650\u0647\u0650\u0645 \u0645\u0651\u0650\u0646 \u0636\u064f\u0631\u0651\u0656 \u0644\u0651\u064e\u0644\u064e\u062c\u0651\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0637\u064f\u063a\u06e1\u064a\u064e\u0670\u0646\u0650\u0647\u0650\u0645\u06e1 \u064a\u064e\u0639\u06e1\u0645\u064e\u0647\u064f\u0648\u0646\u064e",translation:"(Dan sekiranya mereka Kami kasihani, dan Kami lenyapkan malapetaka yang menimpa mereka,554) pasti mereka akan terus menerus terombang-ambing dalam kesesatan mereka"},{id:76,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u062e\u064e\u0630\u06e1\u0646\u064e\u0670\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0641\u064e\u0645\u064e\u0627 \u0671\u0633\u06e1\u062a\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0644\u0650\u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u062a\u064e\u0636\u064e\u0631\u0651\u064e\u0639\u064f\u0648\u0646\u064e",translation:"(Dan sungguh Kami telah menimpakan siksaan kepada mereka,555) tetapi mereka tidak mau tunduk kepada Tuhannya, dan (juga) tidak merendahkan diri"},{id:77,text:"\u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u064e\u0627 \u0641\u064e\u062a\u064e\u062d\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0628\u064e\u0627\u0628\u0657\u0627 \u0630\u064e\u0627 \u0639\u064e\u0630\u064e\u0627\u0628\u0656 \u0634\u064e\u062f\u0650\u064a\u062f\u064d \u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u0650 \u0645\u064f\u0628\u06e1\u0644\u0650\u0633\u064f\u0648\u0646\u064e",translation:"Sehingga apabila Kami bukakan untuk mereka pintu azab yang sangat keras, seketika itu mereka menjadi putus asa"},{id:78,text:"\u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064e\u0646\u0634\u064e\u0623\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u06e1\u0639\u064e \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0628\u06e1\u0635\u064e\u0670\u0631\u064e \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0641\u06e1\u0640\u0654\u0650\u062f\u064e\u0629\u064e\u06da \u0642\u064e\u0644\u0650\u064a\u0644\u0657\u0627 \u0645\u0651\u064e\u0627 \u062a\u064e\u0634\u06e1\u0643\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Dan Dialah yang telah menciptakan bagimu pendengaran, penglihatan dan hati nurani, tetapi sedikit sekali kamu yang bersyukur"},{id:79,text:"\u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0630\u064e\u0631\u064e\u0623\u064e\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u062a\u064f\u062d\u06e1\u0634\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan Dialah yang menciptakan dan mengembangbiakkan kamu di bumi dan kepada-Nyalah kamu akan dikumpulkankan"},{id:80,text:"\u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u062d\u06e1\u064a\u0650\u06e6 \u0648\u064e\u064a\u064f\u0645\u0650\u064a\u062a\u064f \u0648\u064e\u0644\u064e\u0647\u064f \u0671\u062e\u06e1\u062a\u0650\u0644\u064e\u0670\u0641\u064f \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u0650 \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650\u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Dan Dialah yang menghidupkan dan mematikan, dan Dialah yang (mengatur) pergantian malam dan siang. Tidakkah kamu mengerti"},{id:81,text:"\u0628\u064e\u0644\u06e1 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0645\u0650\u062b\u06e1\u0644\u064e \u0645\u064e\u0627 \u0642\u064e\u0627\u0644\u064e \u0671\u0644\u06e1\u0623\u064e\u0648\u0651\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Bahkan mereka mengucapkan perkataan yang serupa dengan apa yang diucapkan oleh orang-orang terdahulu"},{id:82,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0621\u0650\u0630\u064e\u0627 \u0645\u0650\u062a\u06e1\u0646\u064e\u0627 \u0648\u064e\u0643\u064f\u0646\u0651\u064e\u0627 \u062a\u064f\u0631\u064e\u0627\u0628\u0657\u0627 \u0648\u064e\u0639\u0650\u0638\u064e\u0670\u0645\u064b\u0627 \u0623\u064e\u0621\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0645\u064e\u0628\u06e1\u0639\u064f\u0648\u062b\u064f\u0648\u0646\u064e",translation:"Mereka berkata, \"Apakah betul, apabila kami telah mati dan telah menjadi tanah dan tulang belulang, kami benar-benar akan dibangkitkan kembali"},{id:83,text:"\u0644\u064e\u0642\u064e\u062f\u06e1 \u0648\u064f\u0639\u0650\u062f\u06e1\u0646\u064e\u0627 \u0646\u064e\u062d\u06e1\u0646\u064f \u0648\u064e\u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0624\u064f\u0646\u064e\u0627 \u0647\u064e\u0670\u0630\u064e\u0627 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f \u0625\u0650\u0646\u06e1 \u0647\u064e\u0670\u0630\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0633\u064e\u0670\u0637\u0650\u064a\u0631\u064f \u0671\u0644\u06e1\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",translation:"(Sungguh, yang demikian ini sudah dijanjikan kepada kami dan kepada nenek moyang kami dahulu,556) ini hanyalah dongeng orang-orang terdahulu"},{id:84,text:"\u0642\u064f\u0644 \u0644\u0651\u0650\u0645\u064e\u0646\u0650 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064f \u0648\u064e\u0645\u064e\u0646 \u0641\u0650\u064a\u0647\u064e\u0627\u0653 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Katakanlah (Muhammad), \"Milik siapakah bumi, dan semua yang ada di dalamnya, jika kamu mengetahui"},{id:85,text:"\u0633\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650\u06da \u0642\u064f\u0644\u06e1 \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Mereka akan menjawab, \"Milik Allah.\" Katakanlah, \"Maka apakah kamu tidak ingat"},{id:86,text:"\u0642\u064f\u0644\u06e1 \u0645\u064e\u0646 \u0631\u0651\u064e\u0628\u0651\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0671\u0644\u0633\u0651\u064e\u0628\u06e1\u0639\u0650 \u0648\u064e\u0631\u064e\u0628\u0651\u064f \u0671\u0644\u06e1\u0639\u064e\u0631\u06e1\u0634\u0650 \u0671\u0644\u06e1\u0639\u064e\u0638\u0650\u064a\u0645\u0650",translation:"Katakanlah, \"Siapakah Tuhan yang memiliki langit yang tujuh dan yang memiliki Arasy yang agung"},{id:87,text:"\u0633\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650\u06da \u0642\u064f\u0644\u06e1 \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",translation:"Mereka akan menjawab, \"(Milik) Allah.\" Katakanlah, \"Maka mengapa kamu tidak bertakwa"},{id:88,text:"\u0642\u064f\u0644\u06e1 \u0645\u064e\u0646\u06e2 \u0628\u0650\u064a\u064e\u062f\u0650\u0647\u0650\u06e6 \u0645\u064e\u0644\u064e\u0643\u064f\u0648\u062a\u064f \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0648\u064e\u0647\u064f\u0648\u064e \u064a\u064f\u062c\u0650\u064a\u0631\u064f \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u062c\u064e\u0627\u0631\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Katakanlah, \"Siapakah yang di tangan-Nya berada kekuasaan segala sesuatu. Dia melindungi, dan tidak ada yang dapat dilindungi (dari azab-Nya), jika kamu mengetahui"},{id:89,text:"\u0633\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650\u06da \u0642\u064f\u0644\u06e1 \u0641\u064e\u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u062a\u064f\u0633\u06e1\u062d\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Mereka akan menjawab, \"(Milik) Allah.\" Katakanlah, \"(Kalau demikian), maka bagaimana kamu sampai tertipu"},{id:90,text:"\u0628\u064e\u0644\u06e1 \u0623\u064e\u062a\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0643\u064e\u0670\u0630\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Padahal Kami telah membawa kebenaran kepada mereka, tetapi mereka benar-benar pendusta"},{id:91,text:"\u0645\u064e\u0627 \u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646 \u0648\u064e\u0644\u064e\u062f\u0656 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0645\u064e\u0639\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646\u06e1 \u0625\u0650\u0644\u064e\u0670\u0647\u064d\u06da \u0625\u0650\u0630\u0657\u0627 \u0644\u0651\u064e\u0630\u064e\u0647\u064e\u0628\u064e \u0643\u064f\u0644\u0651\u064f \u0625\u0650\u0644\u064e\u0670\u0647\u0650\u06ed \u0628\u0650\u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u064e \u0648\u064e\u0644\u064e\u0639\u064e\u0644\u064e\u0627 \u0628\u064e\u0639\u06e1\u0636\u064f\u0647\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u06e1\u0636\u0656\u06da \u0633\u064f\u0628\u06e1\u062d\u064e\u0670\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064e\u0635\u0650\u0641\u064f\u0648\u0646\u064e",translation:"Allah tidak mempunyai anak, tidak ada tuhan (yang lain) bersama-Nya, (sekiranya tuhan banyak), maka masing-masing tuhan itu akan membawa apa (makhluk) yang diciptakannya, dan sebagian dari tuhan-tuhan itu akan mengalahkan sebagian yang lain. Mahasuci Allah dari apa yang mereka sifatkan itu"},{id:92,text:"\u0639\u064e\u0670\u0644\u0650\u0645\u0650 \u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u0628\u0650 \u0648\u064e\u0671\u0644\u0634\u0651\u064e\u0647\u064e\u0670\u062f\u064e\u0629\u0650 \u0641\u064e\u062a\u064e\u0639\u064e\u0670\u0644\u064e\u0649\u0670 \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064f\u0634\u06e1\u0631\u0650\u0643\u064f\u0648\u0646\u064e",translation:"(Dialah Tuhan) yang mengetahui semua yang gaib dan semua yang tampak. Mahatinggi (Allah) dari apa yang mereka persekutukan"},{id:93,text:"\u0642\u064f\u0644 \u0631\u0651\u064e\u0628\u0651\u0650 \u0625\u0650\u0645\u0651\u064e\u0627 \u062a\u064f\u0631\u0650\u064a\u064e\u0646\u0651\u0650\u064a \u0645\u064e\u0627 \u064a\u064f\u0648\u0639\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Katakanlah (Muhammad), \"Ya Tuhanku, seandainya Engkau hendak memperlihatkan kepadaku apa (azab) yang diancamkan kepada mereka"},{id:94,text:"\u0631\u064e\u0628\u0651\u0650 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062c\u06e1\u0639\u064e\u0644\u06e1\u0646\u0650\u064a \u0641\u0650\u064a \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Ya Tuhanku, maka janganlah Engkau jadikan aku dalam golongan orang-orang zalim"},{id:95,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0646 \u0646\u0651\u064f\u0631\u0650\u064a\u064e\u0643\u064e \u0645\u064e\u0627 \u0646\u064e\u0639\u0650\u062f\u064f\u0647\u064f\u0645\u06e1 \u0644\u064e\u0642\u064e\u0670\u062f\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Dan sungguh, Kami kuasa untuk memperlihatkan kepadamu (Muhammad) apa yang Kami ancamkan kepada mereka"},{id:96,text:"\u0671\u062f\u06e1\u0641\u064e\u0639\u06e1 \u0628\u0650\u0671\u0644\u0651\u064e\u062a\u0650\u064a \u0647\u0650\u064a\u064e \u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064f \u0671\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u064e\u06da \u0646\u064e\u062d\u06e1\u0646\u064f \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u064a\u064e\u0635\u0650\u0641\u064f\u0648\u0646\u064e",translation:"Tolaklah perbuatan buruk mereka dengan (cara) yang lebih baik, Kami lebih mengetahui apa yang mereka sifatkan (kepada Allah)"},{id:97,text:"\u0648\u064e\u0642\u064f\u0644 \u0631\u0651\u064e\u0628\u0651\u0650 \u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646\u06e1 \u0647\u064e\u0645\u064e\u0632\u064e\u0670\u062a\u0650 \u0671\u0644\u0634\u0651\u064e\u064a\u064e\u0670\u0637\u0650\u064a\u0646\u0650",translation:"Dan katakanlah, \"Ya Tuhanku, aku berlindung kepada Engkau dari bisikan-bisikan setan"},{id:98,text:"\u0648\u064e\u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0643\u064e \u0631\u064e\u0628\u0651\u0650 \u0623\u064e\u0646 \u064a\u064e\u062d\u06e1\u0636\u064f\u0631\u064f\u0648\u0646\u0650",translation:"dan aku berlindung (pula) kepada Engkau ya Tuhanku, agar mereka tidak mendekati aku"},{id:99,text:"\u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e \u0623\u064e\u062d\u064e\u062f\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u064f \u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0671\u0631\u06e1\u062c\u0650\u0639\u064f\u0648\u0646\u0650",translation:"(Demikianlah keadaan orang-orang kafir itu), hingga apabila datang kematian kepada seseorang dari mereka, dia berkata, \"Ya Tuhanku, kembalikanlah aku (ke dunia)"},{id:100,text:"\u0644\u064e\u0639\u064e\u0644\u0651\u0650\u064a\u0653 \u0623\u064e\u0639\u06e1\u0645\u064e\u0644\u064f \u0635\u064e\u0670\u0644\u0650\u062d\u0657\u0627 \u0641\u0650\u064a\u0645\u064e\u0627 \u062a\u064e\u0631\u064e\u0643\u06e1\u062a\u064f\u06da \u0643\u064e\u0644\u0651\u064e\u0627\u0653\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064e\u0627 \u0643\u064e\u0644\u0650\u0645\u064e\u0629\u064c \u0647\u064f\u0648\u064e \u0642\u064e\u0627\u0653\u0626\u0650\u0644\u064f\u0647\u064e\u0627\u06d6 \u0648\u064e\u0645\u0650\u0646 \u0648\u064e\u0631\u064e\u0627\u0653\u0626\u0650\u0647\u0650\u0645 \u0628\u064e\u0631\u06e1\u0632\u064e\u062e\u064c \u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u06e1\u0645\u0650 \u064a\u064f\u0628\u06e1\u0639\u064e\u062b\u064f\u0648\u0646\u064e",translation:"(agar aku dapat berbuat kebajikan yang telah aku tinggalkan.\" Sekali-kali tidak! Sungguh itu adalah dalih yang diucapkannya saja. Dan dihadapan mereka ada barzakh557) sampai pada hari mereka dibangkitkan"},{id:101,text:"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0646\u064f\u0641\u0650\u062e\u064e \u0641\u0650\u064a \u0671\u0644\u0635\u0651\u064f\u0648\u0631\u0650 \u0641\u064e\u0644\u064e\u0627\u0653 \u0623\u064e\u0646\u0633\u064e\u0627\u0628\u064e \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062a\u064e\u0633\u064e\u0627\u0653\u0621\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Apabila sangkakala ditiup, maka tidak ada lagi pertalian keluarga di antara mereka pada hari itu (Kiamat), dan tidak (pula) mereka saling bertanya"},{id:102,text:"\u0641\u064e\u0645\u064e\u0646 \u062b\u064e\u0642\u064f\u0644\u064e\u062a\u06e1 \u0645\u064e\u0648\u064e\u0670\u0632\u0650\u064a\u0646\u064f\u0647\u064f\u06e5 \u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064f\u0641\u06e1\u0644\u0650\u062d\u064f\u0648\u0646\u064e",translation:"Barang siapa berat timbangan (kebaikan)-nya, maka mereka itulah orang-orang yang beruntung"},{id:103,text:"\u0648\u064e\u0645\u064e\u0646\u06e1 \u062e\u064e\u0641\u0651\u064e\u062a\u06e1 \u0645\u064e\u0648\u064e\u0670\u0632\u0650\u064a\u0646\u064f\u0647\u064f\u06e5 \u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062e\u064e\u0633\u0650\u0631\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u062e\u064e\u0670\u0644\u0650\u062f\u064f\u0648\u0646\u064e",translation:"Dan barang siapa ringan timbangan (kebaikan)nya, maka mereka itulah orang-orang yang merugikan dirinya sendiri, mereka kekal di dalam neraka Jahanam"},{id:104,text:"\u062a\u064e\u0644\u06e1\u0641\u064e\u062d\u064f \u0648\u064f\u062c\u064f\u0648\u0647\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u064f \u0648\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u0643\u064e\u0670\u0644\u0650\u062d\u064f\u0648\u0646\u064e",translation:"Wajah mereka dibakar api neraka, dan mereka di neraka dalam keadaan muram dengan bibir yang cacat"},{id:105,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0643\u064f\u0646\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u064a \u062a\u064f\u062a\u06e1\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0641\u064e\u0643\u064f\u0646\u062a\u064f\u0645 \u0628\u0650\u0647\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Bukankah ayat-ayat-Ku telah dibacakan kepadamu, tetapi kamu selalu mendustakannya"},{id:106,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u063a\u064e\u0644\u064e\u0628\u064e\u062a\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0634\u0650\u0642\u06e1\u0648\u064e\u062a\u064f\u0646\u064e\u0627 \u0648\u064e\u0643\u064f\u0646\u0651\u064e\u0627 \u0642\u064e\u0648\u06e1\u0645\u0657\u0627 \u0636\u064e\u0627\u0653\u0644\u0651\u0650\u064a\u0646\u064e",translation:"Mereka berkata, \"Ya Tuhan kami, kami telah dikuasai oleh kejahatan kami, dan kami adalah orang-orang yang sesat"},{id:107,text:"\u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627\u0653 \u0623\u064e\u062e\u06e1\u0631\u0650\u062c\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0641\u064e\u0625\u0650\u0646\u06e1 \u0639\u064f\u062f\u06e1\u0646\u064e\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0638\u064e\u0670\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Ya Tuhan kami, keluarkanlah kami darinya (kembalikanlah kami ke dunia), jika kami masih juga kembali (kepada kekafiran), sungguh, kami adalah orang-orang yang zalim"},{id:108,text:"\u0642\u064e\u0627\u0644\u064e \u0671\u062e\u06e1\u0633\u064e\u0640\u0654\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0643\u064e\u0644\u0651\u0650\u0645\u064f\u0648\u0646\u0650",translation:"Dia (Allah) berfirman, \"Tinggallah dengan hina di dalamnya, dan janganlah kamu berbicara dengan Aku"},{id:109,text:"\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0643\u064e\u0627\u0646\u064e \u0641\u064e\u0631\u0650\u064a\u0642\u065e \u0645\u0651\u0650\u0646\u06e1 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627\u0653 \u0621\u064e\u0627\u0645\u064e\u0646\u0651\u064e\u0627 \u0641\u064e\u0671\u063a\u06e1\u0641\u0650\u0631\u06e1 \u0644\u064e\u0646\u064e\u0627 \u0648\u064e\u0671\u0631\u06e1\u062d\u064e\u0645\u06e1\u0646\u064e\u0627 \u0648\u064e\u0623\u064e\u0646\u062a\u064e \u062e\u064e\u064a\u06e1\u0631\u064f \u0671\u0644\u0631\u0651\u064e\u0640\u0670\u062d\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Sungguh ada segolongan dari hamba-hamba-Ku berdoa, \"Ya Tuhan kami, kami telah beriman, maka ampunilah kami dan berilah kami rahmat, Engkau adalah pemberi rahmat yang terbaik"},{id:110,text:"\u0641\u064e\u0671\u062a\u0651\u064e\u062e\u064e\u0630\u06e1\u062a\u064f\u0645\u064f\u0648\u0647\u064f\u0645\u06e1 \u0633\u0650\u062e\u06e1\u0631\u0650\u064a\u0651\u064b\u0627 \u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0623\u064e\u0646\u0633\u064e\u0648\u06e1\u0643\u064f\u0645\u06e1 \u0630\u0650\u0643\u06e1\u0631\u0650\u064a \u0648\u064e\u0643\u064f\u0646\u062a\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u062a\u064e\u0636\u06e1\u062d\u064e\u0643\u064f\u0648\u0646\u064e",translation:"Lalu kamu jadikan mereka buah ejekan, sehingga kamu lupa mengingat Aku, dan kamu (selalu) mentertawakan mereka"},{id:111,text:"\u0625\u0650\u0646\u0651\u0650\u064a \u062c\u064e\u0632\u064e\u064a\u06e1\u062a\u064f\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e \u0628\u0650\u0645\u064e\u0627 \u0635\u064e\u0628\u064e\u0631\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0641\u064e\u0627\u0653\u0626\u0650\u0632\u064f\u0648\u0646\u064e",translation:"Sungguh pada hari ini Aku memberi balasan kepada mereka, karena kesabaran mereka; sungguh mereka itulah orang-orang yang memperoleh kemenangan"},{id:112,text:"\u0642\u064e\u0670\u0644\u064e \u0643\u064e\u0645\u06e1 \u0644\u064e\u0628\u0650\u062b\u06e1\u062a\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0639\u064e\u062f\u064e\u062f\u064e \u0633\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dia (Allah) berfirman, \"Berapa tahunkah lamanya kamu tinggal di bumi"},{id:113,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0628\u0650\u062b\u06e1\u0646\u064e\u0627 \u064a\u064e\u0648\u06e1\u0645\u064b\u0627 \u0623\u064e\u0648\u06e1 \u0628\u064e\u0639\u06e1\u0636\u064e \u064a\u064e\u0648\u06e1\u0645\u0656 \u0641\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u0650 \u0671\u0644\u06e1\u0639\u064e\u0627\u0653\u062f\u0651\u0650\u064a\u0646\u064e",translation:"Mereka menjawab, \"Kami tinggal (di bumi) sehari atau setengah hari, maka tanyakanlah kepada mereka yang menghitung"},{id:114,text:"\u0642\u064e\u0670\u0644\u064e \u0625\u0650\u0646 \u0644\u0651\u064e\u0628\u0650\u062b\u06e1\u062a\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u0657\u0627\u06d6 \u0644\u0651\u064e\u0648\u06e1 \u0623\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dia (Allah) berfirman, \"Kamu tinggal (di bumi) hanya sebentar saja, jika kamu benar-benar mengetahui"},{id:115,text:"\u0623\u064e\u0641\u064e\u062d\u064e\u0633\u0650\u0628\u06e1\u062a\u064f\u0645\u06e1 \u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u06e1\u0646\u064e\u0670\u0643\u064f\u0645\u06e1 \u0639\u064e\u0628\u064e\u062b\u0657\u0627 \u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0644\u064e\u0627 \u062a\u064f\u0631\u06e1\u062c\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Maka apakah kamu mengira bahwa Kami menciptakan kamu main-main (tanpa ada maksud) dan bahwa kamu tidak akan dikembalikan kepada Kami"},{id:116,text:"\u0641\u064e\u062a\u064e\u0639\u064e\u0670\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u0645\u064e\u0644\u0650\u0643\u064f \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f\u06d6 \u0644\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u0631\u064e\u0628\u0651\u064f \u0671\u0644\u06e1\u0639\u064e\u0631\u06e1\u0634\u0650 \u0671\u0644\u06e1\u0643\u064e\u0631\u0650\u064a\u0645\u0650",translation:"Maka Mahatinggi Allah, Raja yang sebenarnya; tidak ada tuhan (yang berhak disembah) selain Dia, Tuhan (yang memiliki) Arasy yang mulia"},{id:117,text:"\u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u062f\u06e1\u0639\u064f \u0645\u064e\u0639\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u064e\u0670\u0647\u064b\u0627 \u0621\u064e\u0627\u062e\u064e\u0631\u064e \u0644\u064e\u0627 \u0628\u064f\u0631\u06e1\u0647\u064e\u0670\u0646\u064e \u0644\u064e\u0647\u064f\u06e5 \u0628\u0650\u0647\u0650\u06e6 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u062d\u0650\u0633\u064e\u0627\u0628\u064f\u0647\u064f\u06e5 \u0639\u0650\u0646\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u06e6\u0653\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0627 \u064a\u064f\u0641\u06e1\u0644\u0650\u062d\u064f \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Dan barangsiapa menyembah tuhan yang lain selain Allah, padahal tidak ada suatu bukti pun baginya tentang itu, maka perhitungannya hanya pada Tuhannya. Sungguh orang-orang kafir itu tidak akan beruntung"},{id:118,text:"\u0648\u064e\u0642\u064f\u0644 \u0631\u0651\u064e\u0628\u0651\u0650 \u0671\u063a\u06e1\u0641\u0650\u0631\u06e1 \u0648\u064e\u0671\u0631\u06e1\u062d\u064e\u0645\u06e1 \u0648\u064e\u0623\u064e\u0646\u062a\u064e \u062e\u064e\u064a\u06e1\u0631\u064f \u0671\u0644\u0631\u0651\u064e\u0640\u0670\u062d\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dan katakanlah (Muhammad), \"Ya Tuhanku, berilah ampunan dan (berilah) rahmat, Engkaulah pemberi rahmat yang terbaik"}]},{id:24,name:"\u0627\u0644\u0646\u0648\u0631",transliteration:"An-Nur",translation:"Cahaya",type:"medinan",total_verses:64,verses:[{id:1,text:"\u0633\u064f\u0648\u0631\u064e\u0629\u064c \u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064e\u0627 \u0648\u064e\u0641\u064e\u0631\u064e\u0636\u06e1\u0646\u064e\u0670\u0647\u064e\u0627 \u0648\u064e\u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627\u0653 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u06ed \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0656 \u0644\u0651\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"(Inilah) suatu surah yang Kami turunkan dan Kami wajibkan (menjalankan hukum-hukumnya), dan Kami turunkan di dalamnya tanda-tanda (kebesaran Allah) yang jelas, agar kamu ingat"},{id:2,text:"\u0671\u0644\u0632\u0651\u064e\u0627\u0646\u0650\u064a\u064e\u0629\u064f \u0648\u064e\u0671\u0644\u0632\u0651\u064e\u0627\u0646\u0650\u064a \u0641\u064e\u0671\u062c\u06e1\u0644\u0650\u062f\u064f\u0648\u0627\u0652 \u0643\u064f\u0644\u0651\u064e \u0648\u064e\u0670\u062d\u0650\u062f\u0656 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u064e\u0627 \u0645\u0650\u0627\u0652\u0626\u064e\u0629\u064e \u062c\u064e\u0644\u06e1\u062f\u064e\u0629\u0656\u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0623\u06e1\u062e\u064f\u0630\u06e1\u0643\u064f\u0645 \u0628\u0650\u0647\u0650\u0645\u064e\u0627 \u0631\u064e\u0623\u06e1\u0641\u064e\u0629\u065e \u0641\u0650\u064a \u062f\u0650\u064a\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u0650\u06d6 \u0648\u064e\u0644\u06e1\u064a\u064e\u0634\u06e1\u0647\u064e\u062f\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064e\u0647\u064f\u0645\u064e\u0627 \u0637\u064e\u0627\u0653\u0626\u0650\u0641\u064e\u0629\u065e \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Pezina perempuan dan pezina laki-laki, deralah masing-masing dari keduanya seratus kali, dan janganlah rasa belas kasihan kepada keduanya mencegah kamu untuk (menjalankan) agama (hukum) Allah, jika kamu beriman kepada Allah dan hari kemudian; dan hendaklah (pelaksanaan) hukuman mereka disaksikan oleh sebagian orang-orang yang beriman"},{id:3,text:"\u0671\u0644\u0632\u0651\u064e\u0627\u0646\u0650\u064a \u0644\u064e\u0627 \u064a\u064e\u0646\u0643\u0650\u062d\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0632\u064e\u0627\u0646\u0650\u064a\u064e\u0629\u064b \u0623\u064e\u0648\u06e1 \u0645\u064f\u0634\u06e1\u0631\u0650\u0643\u064e\u0629\u0657 \u0648\u064e\u0671\u0644\u0632\u0651\u064e\u0627\u0646\u0650\u064a\u064e\u0629\u064f \u0644\u064e\u0627 \u064a\u064e\u0646\u0643\u0650\u062d\u064f\u0647\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0632\u064e\u0627\u0646\u064d \u0623\u064e\u0648\u06e1 \u0645\u064f\u0634\u06e1\u0631\u0650\u0643\u065e\u06da \u0648\u064e\u062d\u064f\u0631\u0651\u0650\u0645\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Pezina laki-laki tidak boleh menikah kecuali dengan pezina perempuan, atau dengan perempuan musyrik; dan pezina perempuan tidak boleh menikah kecuali dengan pezina laki-laki atau dengan laki-laki musyrik; dan yang demikian itu diharamkan bagi orang-orang mukmin"},{id:4,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0631\u06e1\u0645\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u062d\u06e1\u0635\u064e\u0646\u064e\u0670\u062a\u0650 \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0645\u06e1 \u064a\u064e\u0623\u06e1\u062a\u064f\u0648\u0627\u0652 \u0628\u0650\u0623\u064e\u0631\u06e1\u0628\u064e\u0639\u064e\u0629\u0650 \u0634\u064f\u0647\u064e\u062f\u064e\u0627\u0653\u0621\u064e \u0641\u064e\u0671\u062c\u06e1\u0644\u0650\u062f\u064f\u0648\u0647\u064f\u0645\u06e1 \u062b\u064e\u0645\u064e\u0670\u0646\u0650\u064a\u0646\u064e \u062c\u064e\u0644\u06e1\u062f\u064e\u0629\u0657 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u06e1\u0628\u064e\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0634\u064e\u0647\u064e\u0670\u062f\u064e\u0629\u064b \u0623\u064e\u0628\u064e\u062f\u0657\u0627\u06da \u0648\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0641\u064e\u0670\u0633\u0650\u0642\u064f\u0648\u0646\u064e",translation:"Dan orang-orang yang menuduh perempuan-perempuan yang baik (berzina) dan mereka tidak mendatangkan empat orang saksi, maka deralah mereka delapan puluh kali, dan janganlah kamu terima kesaksian mereka untuk selama-lamanya. Mereka itulah orang-orang yang fasik"},{id:5,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u0627\u0628\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0648\u064e\u0623\u064e\u0635\u06e1\u0644\u064e\u062d\u064f\u0648\u0627\u0652 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u065e",translation:"kecuali mereka yang bertobat setelah itu dan memperbaiki (dirinya), maka sungguh, Allah Maha Pengampun, Maha Penyayang"},{id:6,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0631\u06e1\u0645\u064f\u0648\u0646\u064e \u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0643\u064f\u0646 \u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u0634\u064f\u0647\u064e\u062f\u064e\u0627\u0653\u0621\u064f \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646\u0641\u064f\u0633\u064f\u0647\u064f\u0645\u06e1 \u0641\u064e\u0634\u064e\u0647\u064e\u0670\u062f\u064e\u0629\u064f \u0623\u064e\u062d\u064e\u062f\u0650\u0647\u0650\u0645\u06e1 \u0623\u064e\u0631\u06e1\u0628\u064e\u0639\u064f \u0634\u064e\u0647\u064e\u0670\u062f\u064e\u0670\u062a\u0650\u06ed \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Dan orang-orang yang menuduh istrinya (berzina), padahal mereka tidak mempunyai saksi-saksi selain diri mereka sendiri, maka kesaksian masing-masing orang itu ialah empat kali bersumpah dengan (nama) Allah, bahwa sesungguhnya dia termasuk orang yang berkata benar"},{id:7,text:"\u0648\u064e\u0671\u0644\u06e1\u062e\u064e\u0670\u0645\u0650\u0633\u064e\u0629\u064f \u0623\u064e\u0646\u0651\u064e \u0644\u064e\u0639\u06e1\u0646\u064e\u062a\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0643\u064e\u0670\u0630\u0650\u0628\u0650\u064a\u0646\u064e",translation:"Dan (sumpah) yang kelima bahwa laknat Allah akan menimpanya, jika dia termasuk orang yang berdusta"},{id:8,text:"\u0648\u064e\u064a\u064e\u062f\u06e1\u0631\u064e\u0624\u064f\u0627\u0652 \u0639\u064e\u0646\u06e1\u0647\u064e\u0627 \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0623\u064e\u0646 \u062a\u064e\u0634\u06e1\u0647\u064e\u062f\u064e \u0623\u064e\u0631\u06e1\u0628\u064e\u0639\u064e \u0634\u064e\u0647\u064e\u0670\u062f\u064e\u0670\u062a\u0650\u06ed \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0643\u064e\u0670\u0630\u0650\u0628\u0650\u064a\u0646\u064e",translation:"Dan istri itu terhindar dari hukuman apabila dia bersumpah empat kali atas (nama) Allah bahwa dia (suaminya) benar-benar termasuk orang-orang yang berdusta"},{id:9,text:"\u0648\u064e\u0671\u0644\u06e1\u062e\u064e\u0670\u0645\u0650\u0633\u064e\u0629\u064e \u0623\u064e\u0646\u0651\u064e \u063a\u064e\u0636\u064e\u0628\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627\u0653 \u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e",translation:"dan (sumpah) yang kelima bahwa kemurkaan Allah akan menimpanya (istri), jika dia (suaminya) itu termasuk orang yang berkata benar"},{id:10,text:"\u0648\u064e\u0644\u064e\u0648\u06e1\u0644\u064e\u0627 \u0641\u064e\u0636\u06e1\u0644\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0648\u064e\u0631\u064e\u062d\u06e1\u0645\u064e\u062a\u064f\u0647\u064f\u06e5 \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u062a\u064e\u0648\u0651\u064e\u0627\u0628\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u064c",translation:"Dan sekiranya bukan karena karunia Allah dan rahmat-Nya kepadamu (niscaya kamu akan menemui kesulitan). Dan sesungguhnya Allah Maha Penerima Tobat, Mahabijaksana"},{id:11,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062c\u064e\u0627\u0653\u0621\u064f\u0648 \u0628\u0650\u0671\u0644\u06e1\u0625\u0650\u0641\u06e1\u0643\u0650 \u0639\u064f\u0635\u06e1\u0628\u064e\u0629\u065e \u0645\u0651\u0650\u0646\u0643\u064f\u0645\u06e1\u06da \u0644\u064e\u0627 \u062a\u064e\u062d\u06e1\u0633\u064e\u0628\u064f\u0648\u0647\u064f \u0634\u064e\u0631\u0651\u0657\u0627 \u0644\u0651\u064e\u0643\u064f\u0645\u06d6 \u0628\u064e\u0644\u06e1 \u0647\u064f\u0648\u064e \u062e\u064e\u064a\u06e1\u0631\u065e \u0644\u0651\u064e\u0643\u064f\u0645\u06e1\u06da \u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0671\u0645\u06e1\u0631\u0650\u064a\u0655\u0656 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0627 \u0671\u0643\u06e1\u062a\u064e\u0633\u064e\u0628\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0625\u0650\u062b\u06e1\u0645\u0650\u06da \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649\u0670 \u0643\u0650\u0628\u06e1\u0631\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0644\u064e\u0647\u064f\u06e5 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u065e",translation:"Sesungguhnya orang-orang yang membawa berita bohong itu adalah dari golongan kamu (juga). Janganlah kamu mengira berita itu buruk bagi kamu bahkan itu baik bagi kamu. Setiap orang dari mereka mendapat balasan dari dosa yang diperbuatnya. Dan barangsiapa di antara mereka yang mengambil bagian terbesar (dari dosa yang diperbuatnya), dia mendapat azab yang besar (pula)"},{id:12,text:"\u0644\u0651\u064e\u0648\u06e1\u0644\u064e\u0627\u0653 \u0625\u0650\u0630\u06e1 \u0633\u064e\u0645\u0650\u0639\u06e1\u062a\u064f\u0645\u064f\u0648\u0647\u064f \u0638\u064e\u0646\u0651\u064e \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064e\u0670\u062a\u064f \u0628\u0650\u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u06e1 \u062e\u064e\u064a\u06e1\u0631\u0657\u0627 \u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0647\u064e\u0670\u0630\u064e\u0627\u0653 \u0625\u0650\u0641\u06e1\u0643\u065e \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u065e",translation:"Mengapa orang-orang mukmin dan mukminat tidak berbaik sangka terhadap diri mereka sendiri, ketika kamu mendengar berita bohong itu dan berkata, \"Ini adalah (suatu berita) bohong yang nyata"},{id:13,text:"\u0644\u0651\u064e\u0648\u06e1\u0644\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064f\u0648 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0628\u0650\u0623\u064e\u0631\u06e1\u0628\u064e\u0639\u064e\u0629\u0650 \u0634\u064f\u0647\u064e\u062f\u064e\u0627\u0653\u0621\u064e\u06da \u0641\u064e\u0625\u0650\u0630\u06e1 \u0644\u064e\u0645\u06e1 \u064a\u064e\u0623\u06e1\u062a\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u0634\u0651\u064f\u0647\u064e\u062f\u064e\u0627\u0653\u0621\u0650 \u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0643\u064e\u0670\u0630\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Mengapa mereka (yang menuduh itu) tidak datang membawa empat saksi? Oleh karena mereka tidak membawa saksi-saksi, maka mereka itu dalam pandangan Allah adalah orang-orang yang berdusta"},{id:14,text:"\u0648\u064e\u0644\u064e\u0648\u06e1\u0644\u064e\u0627 \u0641\u064e\u0636\u06e1\u0644\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0648\u064e\u0631\u064e\u062d\u06e1\u0645\u064e\u062a\u064f\u0647\u064f\u06e5 \u0641\u0650\u064a \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0648\u064e\u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0644\u064e\u0645\u064e\u0633\u0651\u064e\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u0645\u064e\u0627\u0653 \u0623\u064e\u0641\u064e\u0636\u06e1\u062a\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u0650 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u064c",translation:"Dan seandainya bukan karena karunia Allah dan rahmat-Nya kepadamu di dunia dan di akhirat, niscaya kamu ditimpa azab yang besar, disebabkan oleh pembicaraan kamu tentang hal itu (berita bohong itu)"},{id:15,text:"\u0625\u0650\u0630\u06e1 \u062a\u064e\u0644\u064e\u0642\u0651\u064e\u0648\u06e1\u0646\u064e\u0647\u064f\u06e5 \u0628\u0650\u0623\u064e\u0644\u06e1\u0633\u0650\u0646\u064e\u062a\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0628\u0650\u0623\u064e\u0641\u06e1\u0648\u064e\u0627\u0647\u0650\u0643\u064f\u0645 \u0645\u0651\u064e\u0627 \u0644\u064e\u064a\u06e1\u0633\u064e \u0644\u064e\u0643\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6 \u0639\u0650\u0644\u06e1\u0645\u065e \u0648\u064e\u062a\u064e\u062d\u06e1\u0633\u064e\u0628\u064f\u0648\u0646\u064e\u0647\u064f\u06e5 \u0647\u064e\u064a\u0651\u0650\u0646\u0657\u0627 \u0648\u064e\u0647\u064f\u0648\u064e \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0638\u0650\u064a\u0645\u065e",translation:"(Ingatlah) ketika kamu menerima (berita bohong) itu dari mulut ke mulut dan kamu katakan dengan mulutmu apa yang tidak kamu ketahui sedikit pun, dan kamu menganggapnya remeh, padahal dalam pandangan Allah itu perkara besar"},{id:16,text:"\u0648\u064e\u0644\u064e\u0648\u06e1\u0644\u064e\u0627\u0653 \u0625\u0650\u0630\u06e1 \u0633\u064e\u0645\u0650\u0639\u06e1\u062a\u064f\u0645\u064f\u0648\u0647\u064f \u0642\u064f\u0644\u06e1\u062a\u064f\u0645 \u0645\u0651\u064e\u0627 \u064a\u064e\u0643\u064f\u0648\u0646\u064f \u0644\u064e\u0646\u064e\u0627\u0653 \u0623\u064e\u0646 \u0646\u0651\u064e\u062a\u064e\u0643\u064e\u0644\u0651\u064e\u0645\u064e \u0628\u0650\u0647\u064e\u0670\u0630\u064e\u0627 \u0633\u064f\u0628\u06e1\u062d\u064e\u0670\u0646\u064e\u0643\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0628\u064f\u0647\u06e1\u062a\u064e\u0670\u0646\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u065e",translation:"Dan mengapa kamu tidak berkata ketika mendengarnya, \"Tidak pantas bagi kita membicarakan ini. Mahasuci Engkau, ini adalah kebohongan yang besar"},{id:17,text:"\u064a\u064e\u0639\u0650\u0638\u064f\u0643\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0646 \u062a\u064e\u0639\u064f\u0648\u062f\u064f\u0648\u0627\u0652 \u0644\u0650\u0645\u0650\u062b\u06e1\u0644\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0628\u064e\u062f\u064b\u0627 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645 \u0645\u0651\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Allah memperingatkan kamu agar (jangan) kembali mengulangi seperti itu selama-lamanya, jika kamu orang beriman"},{id:18,text:"\u0648\u064e\u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0623\u0653\u064a\u064e\u0670\u062a\u0650\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u064c",translation:"dan Allah menjelaskan ayat-ayat(-Nya) kepada kamu. Dan Allah Maha Mengetahui, Mahabijaksana"},{id:19,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u062d\u0650\u0628\u0651\u064f\u0648\u0646\u064e \u0623\u064e\u0646 \u062a\u064e\u0634\u0650\u064a\u0639\u064e \u0671\u0644\u06e1\u0641\u064e\u0670\u062d\u0650\u0634\u064e\u0629\u064f \u0641\u0650\u064a \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u065e \u0641\u0650\u064a \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0648\u064e\u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Sesungguhnya orang-orang yang ingin agar perbuatan yang sangat keji itu (berita bohong) tersiar di kalangan orang-orang yang beriman, mereka mendapat azab yang pedih di dunia dan di akhirat. Dan Allah mengetahui, sedang kamu tidak mengetahui"},{id:20,text:"\u0648\u064e\u0644\u064e\u0648\u06e1\u0644\u064e\u0627 \u0641\u064e\u0636\u06e1\u0644\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0648\u064e\u0631\u064e\u062d\u06e1\u0645\u064e\u062a\u064f\u0647\u064f\u06e5 \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0631\u064e\u0621\u064f\u0648\u0641\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u065e",translation:"Dan kalau bukan karena karunia Allah dan rahmat-Nya kepadamu (niscaya kamu akan ditimpa azab yang besar). Sungguh, Allah Maha Penyantun, Maha Penyayang"},{id:21,text:"\u06de\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0627\u0652 \u062e\u064f\u0637\u064f\u0648\u064e\u0670\u062a\u0650 \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u0650\u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u06e1 \u062e\u064f\u0637\u064f\u0648\u064e\u0670\u062a\u0650 \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u0650 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u064a\u064e\u0623\u06e1\u0645\u064f\u0631\u064f \u0628\u0650\u0671\u0644\u06e1\u0641\u064e\u062d\u06e1\u0634\u064e\u0627\u0653\u0621\u0650 \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0646\u0643\u064e\u0631\u0650\u06da \u0648\u064e\u0644\u064e\u0648\u06e1\u0644\u064e\u0627 \u0641\u064e\u0636\u06e1\u0644\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0648\u064e\u0631\u064e\u062d\u06e1\u0645\u064e\u062a\u064f\u0647\u064f\u06e5 \u0645\u064e\u0627 \u0632\u064e\u0643\u064e\u0649\u0670 \u0645\u0650\u0646\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u062d\u064e\u062f\u064d \u0623\u064e\u0628\u064e\u062f\u0657\u0627 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u0632\u064e\u0643\u0651\u0650\u064a \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0633\u064e\u0645\u0650\u064a\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Wahai orang-orang yang beriman! Janganlah kamu mengikuti langkah-langkah setan. Barang siapa mengikuti langkah-langkah setan, maka sesungguhnya dia (setan) menyuruh mengerjakan perbuatan yang keji dan mungkar. Kalau bukan karena karunia Allah dan rahmat-Nya kepadamu, niscaya tidak seorang pun di antara kamu bersih (dari perbuatan keji dan mungkar itu) selama-lamanya, tetapi Allah membersihkan siapa yang Dia kehendaki. Dan Allah Maha Mendengar, Maha Mengetahui"},{id:22,text:"\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0623\u06e1\u062a\u064e\u0644\u0650 \u0623\u064f\u0648\u0652\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0641\u064e\u0636\u06e1\u0644\u0650 \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u0648\u064e\u0671\u0644\u0633\u0651\u064e\u0639\u064e\u0629\u0650 \u0623\u064e\u0646 \u064a\u064f\u0624\u06e1\u062a\u064f\u0648\u0653\u0627\u0652 \u0623\u064f\u0648\u0652\u0644\u0650\u064a \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0628\u064e\u0649\u0670 \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u0633\u064e\u0670\u0643\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0647\u064e\u0670\u062c\u0650\u0631\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0648\u064e\u0644\u06e1\u064a\u064e\u0639\u06e1\u0641\u064f\u0648\u0627\u0652 \u0648\u064e\u0644\u06e1\u064a\u064e\u0635\u06e1\u0641\u064e\u062d\u064f\u0648\u0653\u0627\u0652\u06d7 \u0623\u064e\u0644\u064e\u0627 \u062a\u064f\u062d\u0650\u0628\u0651\u064f\u0648\u0646\u064e \u0623\u064e\u0646 \u064a\u064e\u063a\u06e1\u0641\u0650\u0631\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064c",translation:"Dan janganlah orang-orang yang mempunyai kelebihan dan kelapangan di antara kamu bersumpah bahwa mereka (tidak) akan memberi (bantuan) kepada kerabat(nya), orang-orang miskin dan orang-orang yang berhijrah di jalan Allah, dan hendaklah mereka memaafkan dan berlapang dada. Apakah kamu tidak suka kalau Allah mengampunimu? Dan Allah Maha Pengampun, Maha Penyayang"},{id:23,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0631\u06e1\u0645\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u062d\u06e1\u0635\u064e\u0646\u064e\u0670\u062a\u0650 \u0671\u0644\u06e1\u063a\u064e\u0670\u0641\u0650\u0644\u064e\u0670\u062a\u0650 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064e\u0670\u062a\u0650 \u0644\u064f\u0639\u0650\u0646\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0648\u064e\u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u065e",translation:"(Sungguh, orang-orang yang menuduh perempuan-perempuan baik, yang lengah561) dan beriman (dengan tuduhan berzina), mereka dilaknat di dunia dan di akhirat, dan mereka akan mendapat azab yang besar"},{id:24,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u062a\u064e\u0634\u06e1\u0647\u064e\u062f\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0623\u064e\u0644\u06e1\u0633\u0650\u0646\u064e\u062a\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u0647\u0650\u0645\u06e1 \u0648\u064e\u0623\u064e\u0631\u06e1\u062c\u064f\u0644\u064f\u0647\u064f\u0645 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"pada hari, (ketika) lidah, tangan dan kaki mereka menjadi saksi atas mereka terhadap apa yang dahulu mereka kerjakan"},{id:25,text:"\u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u064a\u064f\u0648\u064e\u0641\u0651\u0650\u064a\u0647\u0650\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u062f\u0650\u064a\u0646\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064e \u0648\u064e\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f \u0671\u0644\u06e1\u0645\u064f\u0628\u0650\u064a\u0646\u064f",translation:"Pada hari itu Allah menyempurnakan balasan yang sebenarnya bagi mereka, dan mereka tahu bahwa Allah Mahabenar, Maha Menjelaskan"},{id:26,text:"\u0671\u0644\u06e1\u062e\u064e\u0628\u0650\u064a\u062b\u064e\u0670\u062a\u064f \u0644\u0650\u0644\u06e1\u062e\u064e\u0628\u0650\u064a\u062b\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u062e\u064e\u0628\u0650\u064a\u062b\u064f\u0648\u0646\u064e \u0644\u0650\u0644\u06e1\u062e\u064e\u0628\u0650\u064a\u062b\u064e\u0670\u062a\u0650\u06d6 \u0648\u064e\u0671\u0644\u0637\u0651\u064e\u064a\u0651\u0650\u0628\u064e\u0670\u062a\u064f \u0644\u0650\u0644\u0637\u0651\u064e\u064a\u0651\u0650\u0628\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u0637\u0651\u064e\u064a\u0651\u0650\u0628\u064f\u0648\u0646\u064e \u0644\u0650\u0644\u0637\u0651\u064e\u064a\u0651\u0650\u0628\u064e\u0670\u062a\u0650\u06da \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0645\u064f\u0628\u064e\u0631\u0651\u064e\u0621\u064f\u0648\u0646\u064e \u0645\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e\u06d6 \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u063a\u06e1\u0641\u0650\u0631\u064e\u0629\u065e \u0648\u064e\u0631\u0650\u0632\u06e1\u0642\u065e \u0643\u064e\u0631\u0650\u064a\u0645\u065e",translation:"Perempuan-perempuan yang keji untuk laki-laki yang keji, dan laki-laki yang keji untuk perempuan-perempuan yang keji (pula), sedangkan perempuan-perempuan yang baik untuk laki-laki yang baik dan laki-laki yang baik untuk perempuan-perempuan yang baik (pula). Mereka itu bersih dari apa yang dituduhkan orang. Mereka memperoleh ampunan dan rezeki yang mulia (surga)"},{id:27,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u062a\u064e\u062f\u06e1\u062e\u064f\u0644\u064f\u0648\u0627\u0652 \u0628\u064f\u064a\u064f\u0648\u062a\u064b\u0627 \u063a\u064e\u064a\u06e1\u0631\u064e \u0628\u064f\u064a\u064f\u0648\u062a\u0650\u0643\u064f\u0645\u06e1 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062a\u064e\u0633\u06e1\u062a\u064e\u0623\u06e1\u0646\u0650\u0633\u064f\u0648\u0627\u0652 \u0648\u064e\u062a\u064f\u0633\u064e\u0644\u0651\u0650\u0645\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0647\u06e1\u0644\u0650\u0647\u064e\u0627\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u06e1 \u062e\u064e\u064a\u06e1\u0631\u065e \u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Wahai orang-orang yang beriman! Janganlah kamu memasuki rumah yang bukan rumahmu sebelum meminta izin dan memberi salam kepada penghuninya. Yang demikian itu lebih baik bagimu, agar kamu (selalu) ingat"},{id:28,text:"\u0641\u064e\u0625\u0650\u0646 \u0644\u0651\u064e\u0645\u06e1 \u062a\u064e\u062c\u0650\u062f\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0647\u064e\u0627\u0653 \u0623\u064e\u062d\u064e\u062f\u0657\u0627 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062f\u06e1\u062e\u064f\u0644\u064f\u0648\u0647\u064e\u0627 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064f\u0624\u06e1\u0630\u064e\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0625\u0650\u0646 \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0631\u06e1\u062c\u0650\u0639\u064f\u0648\u0627\u0652 \u0641\u064e\u0671\u0631\u06e1\u062c\u0650\u0639\u064f\u0648\u0627\u0652\u06d6 \u0647\u064f\u0648\u064e \u0623\u064e\u0632\u06e1\u0643\u064e\u0649\u0670 \u0644\u064e\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Dan jika kamu tidak menemui seorang pun di dalamnya, maka janganlah kamu masuk sebelum kamu mendapat izin. Dan jika dikatakan kepadamu, \"Kembalilah!\" Maka (hendaklah) kamu kembali. Itu lebih suci bagimu, dan Allah Maha Mengetahui apa yang kamu kerjakan"},{id:29,text:"\u0644\u0651\u064e\u064a\u06e1\u0633\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u062c\u064f\u0646\u064e\u0627\u062d\u064c \u0623\u064e\u0646 \u062a\u064e\u062f\u06e1\u062e\u064f\u0644\u064f\u0648\u0627\u0652 \u0628\u064f\u064a\u064f\u0648\u062a\u064b\u0627 \u063a\u064e\u064a\u06e1\u0631\u064e \u0645\u064e\u0633\u06e1\u0643\u064f\u0648\u0646\u064e\u0629\u0656 \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u064e\u062a\u064e\u0670\u0639\u065e \u0644\u0651\u064e\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u062a\u064f\u0628\u06e1\u062f\u064f\u0648\u0646\u064e \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0643\u06e1\u062a\u064f\u0645\u064f\u0648\u0646\u064e",translation:"Tidak ada dosa atasmu memasuki rumah yang tidak dihuni, yang di dalamnya ada keperluan kamu; Allah mengetahui apa yang kamu nyatakan dan apa yang kamu sembunyikan"},{id:30,text:"\u0642\u064f\u0644 \u0644\u0651\u0650\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u064a\u064e\u063a\u064f\u0636\u0651\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1 \u0623\u064e\u0628\u06e1\u0635\u064e\u0670\u0631\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u064a\u064e\u062d\u06e1\u0641\u064e\u0638\u064f\u0648\u0627\u0652 \u0641\u064f\u0631\u064f\u0648\u062c\u064e\u0647\u064f\u0645\u06e1\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0623\u064e\u0632\u06e1\u0643\u064e\u0649\u0670 \u0644\u064e\u0647\u064f\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u062e\u064e\u0628\u0650\u064a\u0631\u064f\u06e2 \u0628\u0650\u0645\u064e\u0627 \u064a\u064e\u0635\u06e1\u0646\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Katakanlah kepada laki-laki yang beriman, agar mereka menjaga pandangannya, dan memelihara kemaluannya; yang demikian itu lebih suci bagi mereka. Sungguh, Allah Maha Mengetahui apa yang mereka perbuat"},{id:31,text:"\u0648\u064e\u0642\u064f\u0644 \u0644\u0651\u0650\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064e\u0670\u062a\u0650 \u064a\u064e\u063a\u06e1\u0636\u064f\u0636\u06e1\u0646\u064e \u0645\u0650\u0646\u06e1 \u0623\u064e\u0628\u06e1\u0635\u064e\u0670\u0631\u0650\u0647\u0650\u0646\u0651\u064e \u0648\u064e\u064a\u064e\u062d\u06e1\u0641\u064e\u0638\u06e1\u0646\u064e \u0641\u064f\u0631\u064f\u0648\u062c\u064e\u0647\u064f\u0646\u0651\u064e \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0628\u06e1\u062f\u0650\u064a\u0646\u064e \u0632\u0650\u064a\u0646\u064e\u062a\u064e\u0647\u064f\u0646\u0651\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0638\u064e\u0647\u064e\u0631\u064e \u0645\u0650\u0646\u06e1\u0647\u064e\u0627\u06d6 \u0648\u064e\u0644\u06e1\u064a\u064e\u0636\u06e1\u0631\u0650\u0628\u06e1\u0646\u064e \u0628\u0650\u062e\u064f\u0645\u064f\u0631\u0650\u0647\u0650\u0646\u0651\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u062c\u064f\u064a\u064f\u0648\u0628\u0650\u0647\u0650\u0646\u0651\u064e\u06d6 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0628\u06e1\u062f\u0650\u064a\u0646\u064e \u0632\u0650\u064a\u0646\u064e\u062a\u064e\u0647\u064f\u0646\u0651\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0644\u0650\u0628\u064f\u0639\u064f\u0648\u0644\u064e\u062a\u0650\u0647\u0650\u0646\u0651\u064e \u0623\u064e\u0648\u06e1 \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0626\u0650\u0647\u0650\u0646\u0651\u064e \u0623\u064e\u0648\u06e1 \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0621\u0650 \u0628\u064f\u0639\u064f\u0648\u0644\u064e\u062a\u0650\u0647\u0650\u0646\u0651\u064e \u0623\u064e\u0648\u06e1 \u0623\u064e\u0628\u06e1\u0646\u064e\u0627\u0653\u0626\u0650\u0647\u0650\u0646\u0651\u064e \u0623\u064e\u0648\u06e1 \u0623\u064e\u0628\u06e1\u0646\u064e\u0627\u0653\u0621\u0650 \u0628\u064f\u0639\u064f\u0648\u0644\u064e\u062a\u0650\u0647\u0650\u0646\u0651\u064e \u0623\u064e\u0648\u06e1 \u0625\u0650\u062e\u06e1\u0648\u064e\u0670\u0646\u0650\u0647\u0650\u0646\u0651\u064e \u0623\u064e\u0648\u06e1 \u0628\u064e\u0646\u0650\u064a\u0653 \u0625\u0650\u062e\u06e1\u0648\u064e\u0670\u0646\u0650\u0647\u0650\u0646\u0651\u064e \u0623\u064e\u0648\u06e1 \u0628\u064e\u0646\u0650\u064a\u0653 \u0623\u064e\u062e\u064e\u0648\u064e\u0670\u062a\u0650\u0647\u0650\u0646\u0651\u064e \u0623\u064e\u0648\u06e1 \u0646\u0650\u0633\u064e\u0627\u0653\u0626\u0650\u0647\u0650\u0646\u0651\u064e \u0623\u064e\u0648\u06e1 \u0645\u064e\u0627 \u0645\u064e\u0644\u064e\u0643\u064e\u062a\u06e1 \u0623\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u064f\u0647\u064f\u0646\u0651\u064e \u0623\u064e\u0648\u0650 \u0671\u0644\u062a\u0651\u064e\u0640\u0670\u0628\u0650\u0639\u0650\u064a\u0646\u064e \u063a\u064e\u064a\u06e1\u0631\u0650 \u0623\u064f\u0648\u0652\u0644\u0650\u064a \u0671\u0644\u06e1\u0625\u0650\u0631\u06e1\u0628\u064e\u0629\u0650 \u0645\u0650\u0646\u064e \u0671\u0644\u0631\u0651\u0650\u062c\u064e\u0627\u0644\u0650 \u0623\u064e\u0648\u0650 \u0671\u0644\u0637\u0651\u0650\u0641\u06e1\u0644\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0645\u06e1 \u064a\u064e\u0638\u06e1\u0647\u064e\u0631\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0639\u064e\u0648\u06e1\u0631\u064e\u0670\u062a\u0650 \u0671\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0653\u0621\u0650\u06d6 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0636\u06e1\u0631\u0650\u0628\u06e1\u0646\u064e \u0628\u0650\u0623\u064e\u0631\u06e1\u062c\u064f\u0644\u0650\u0647\u0650\u0646\u0651\u064e \u0644\u0650\u064a\u064f\u0639\u06e1\u0644\u064e\u0645\u064e \u0645\u064e\u0627 \u064a\u064f\u062e\u06e1\u0641\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0632\u0650\u064a\u0646\u064e\u062a\u0650\u0647\u0650\u0646\u0651\u064e\u06da \u0648\u064e\u062a\u064f\u0648\u0628\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064f\u0641\u06e1\u0644\u0650\u062d\u064f\u0648\u0646\u064e",translation:"Dan katakanlah kepada para perempuan yang beriman, agar mereka menjaga pandangannya, dan memelihara kemaluannya, dan janganlah menampakkan perhiasannya (auratnya), kecuali yang (biasa) terlihat. Dan hendaklah mereka menutupkan kain kerudung ke dadanya, dan janganlah menampakkan perhiasannya (auratnya), kecuali kepada suami mereka, atau ayah mereka, atau ayah suami mereka, atau putra-putra mereka, atau putra-putra suami mereka, atau saudara-saudara laki-laki mereka, atau putra-putra saudara laki-laki mereka, atau putra-putra saudara perempuan mereka, atau para perempuan (sesama Islam) mereka, atau hamba sahaya yang mereka miliki, atau para pelayan laki-laki (tua) yang tidak mempunyai hasrat (terhadap perempuan), atau anak-anak yang belum mengerti tentang aurat perempuan. Dan janganlah mereka menghentakkan kakinya agar diketahui perhiasan yang mereka sembunyikan. Dan bertobatlah kamu semua kepada Allah, wahai orang-orang yang beriman, agar kamu beruntung"},{id:32,text:"\u0648\u064e\u0623\u064e\u0646\u0643\u0650\u062d\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0623\u064e\u064a\u064e\u0670\u0645\u064e\u0649\u0670 \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u0648\u064e\u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u06e1 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0625\u0650\u0645\u064e\u0627\u0653\u0626\u0650\u0643\u064f\u0645\u06e1\u06da \u0625\u0650\u0646 \u064a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u0641\u064f\u0642\u064e\u0631\u064e\u0627\u0653\u0621\u064e \u064a\u064f\u063a\u06e1\u0646\u0650\u0647\u0650\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646 \u0641\u064e\u0636\u06e1\u0644\u0650\u0647\u0650\u06e6\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0670\u0633\u0650\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Dan nikahkanlah orang-orang yang masih membujang di antara kamu, dan juga orang-orang yang layak (menikah) dari hamba-hamba sahayamu yang laki-laki dan perempuan. Jika mereka miskin, Allah akan memberi kemampuan kepada mereka dengan karunia-Nya. Dan Allah Mahaluas (pemberian-Nya), Maha Mengetahui"},{id:33,text:"\u0648\u064e\u0644\u06e1\u064a\u064e\u0633\u06e1\u062a\u064e\u0639\u06e1\u0641\u0650\u0641\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u062c\u0650\u062f\u064f\u0648\u0646\u064e \u0646\u0650\u0643\u064e\u0627\u062d\u064b\u0627 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064f\u063a\u06e1\u0646\u0650\u064a\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646 \u0641\u064e\u0636\u06e1\u0644\u0650\u0647\u0650\u06e6\u06d7 \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0628\u06e1\u062a\u064e\u063a\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0645\u0650\u0645\u0651\u064e\u0627 \u0645\u064e\u0644\u064e\u0643\u064e\u062a\u06e1 \u0623\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u064f\u0643\u064f\u0645\u06e1 \u0641\u064e\u0643\u064e\u0627\u062a\u0650\u0628\u064f\u0648\u0647\u064f\u0645\u06e1 \u0625\u0650\u0646\u06e1 \u0639\u064e\u0644\u0650\u0645\u06e1\u062a\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u0650\u0645\u06e1 \u062e\u064e\u064a\u06e1\u0631\u0657\u0627\u06d6 \u0648\u064e\u0621\u064e\u0627\u062a\u064f\u0648\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0645\u0651\u064e\u0627\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0621\u064e\u0627\u062a\u064e\u0649\u0670\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0643\u06e1\u0631\u0650\u0647\u064f\u0648\u0627\u0652 \u0641\u064e\u062a\u064e\u064a\u064e\u0670\u062a\u0650\u0643\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0628\u0650\u063a\u064e\u0627\u0653\u0621\u0650 \u0625\u0650\u0646\u06e1 \u0623\u064e\u0631\u064e\u062f\u06e1\u0646\u064e \u062a\u064e\u062d\u064e\u0635\u0651\u064f\u0646\u0657\u0627 \u0644\u0651\u0650\u062a\u064e\u0628\u06e1\u062a\u064e\u063a\u064f\u0648\u0627\u0652 \u0639\u064e\u0631\u064e\u0636\u064e \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u0650 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627\u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0643\u06e1\u0631\u0650\u0647\u0647\u0651\u064f\u0646\u0651\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0625\u0650\u0643\u06e1\u0631\u064e\u0670\u0647\u0650\u0647\u0650\u0646\u0651\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u065e",translation:"Dan orang-orang yang tidak mampu menikah hendaklah menjaga kesucian (dirinya), sampai Allah memberi kemampuan kepada mereka dengan karunia-Nya. Dan jika hamba sahaya yang kamu miliki menginginkan perjanjian (kebebasan), hendaklah kamu buat perjanjian kepada mereka, jika kamu mengetahui ada kebaikan pada mereka, dan berikanlah kepada mereka sebagian dari harta Allah yang dikaruniakan-Nya kepadamu. Dan janganlah kamu paksa hamba sahaya perempuanmu untuk melakukan pelacuran, sedang mereka sendiri menginginkan kesucian, karena kamu hendak mencari keuntungan kehidupan duniawi. Barangsiapa memaksa mereka, maka sungguh, Allah Maha Pengampun, Maha Penyayang (kepada mereka) setelah mereka dipaksa"},{id:34,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0656 \u0645\u0651\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0656 \u0648\u064e\u0645\u064e\u062b\u064e\u0644\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062e\u064e\u0644\u064e\u0648\u06e1\u0627\u0652 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0645\u064e\u0648\u06e1\u0639\u0650\u0638\u064e\u0629\u0657 \u0644\u0651\u0650\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",translation:"Dan sungguh, Kami telah menurunkan kepada kamu ayat-ayat yang memberi penjelasan, dan contoh-contoh dari orang-orang yang terdahulu sebelum kamu dan sebagai pelajaran bagi orang-orang yang bertakwa"},{id:35,text:"\u06de\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0646\u064f\u0648\u0631\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06da \u0645\u064e\u062b\u064e\u0644\u064f \u0646\u064f\u0648\u0631\u0650\u0647\u0650\u06e6 \u0643\u064e\u0645\u0650\u0634\u06e1\u0643\u064e\u0648\u0670\u0629\u0656 \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u0650\u0635\u06e1\u0628\u064e\u0627\u062d\u064c\u06d6 \u0671\u0644\u06e1\u0645\u0650\u0635\u06e1\u0628\u064e\u0627\u062d\u064f \u0641\u0650\u064a \u0632\u064f\u062c\u064e\u0627\u062c\u064e\u0629\u064d\u06d6 \u0671\u0644\u0632\u0651\u064f\u062c\u064e\u0627\u062c\u064e\u0629\u064f \u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064e\u0627 \u0643\u064e\u0648\u06e1\u0643\u064e\u0628\u065e \u062f\u064f\u0631\u0651\u0650\u064a\u0651\u065e \u064a\u064f\u0648\u0642\u064e\u062f\u064f \u0645\u0650\u0646 \u0634\u064e\u062c\u064e\u0631\u064e\u0629\u0656 \u0645\u0651\u064f\u0628\u064e\u0670\u0631\u064e\u0643\u064e\u0629\u0656 \u0632\u064e\u064a\u06e1\u062a\u064f\u0648\u0646\u064e\u0629\u0656 \u0644\u0651\u064e\u0627 \u0634\u064e\u0631\u06e1\u0642\u0650\u064a\u0651\u064e\u0629\u0656 \u0648\u064e\u0644\u064e\u0627 \u063a\u064e\u0631\u06e1\u0628\u0650\u064a\u0651\u064e\u0629\u0656 \u064a\u064e\u0643\u064e\u0627\u062f\u064f \u0632\u064e\u064a\u06e1\u062a\u064f\u0647\u064e\u0627 \u064a\u064f\u0636\u0650\u064a\u0653\u0621\u064f \u0648\u064e\u0644\u064e\u0648\u06e1 \u0644\u064e\u0645\u06e1 \u062a\u064e\u0645\u06e1\u0633\u064e\u0633\u06e1\u0647\u064f \u0646\u064e\u0627\u0631\u065e\u06da \u0646\u0651\u064f\u0648\u0631\u064c \u0639\u064e\u0644\u064e\u0649\u0670 \u0646\u064f\u0648\u0631\u0656\u06da \u064a\u064e\u0647\u06e1\u062f\u0650\u064a \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u0646\u064f\u0648\u0631\u0650\u0647\u0650\u06e6 \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06da \u0648\u064e\u064a\u064e\u0636\u06e1\u0631\u0650\u0628\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u062b\u064e\u0670\u0644\u064e \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Allah (pemberi) cahaya (kepada) langit dan bumi. Perumpamaan cahaya-Nya, seperti sebuah lubang yang tidak tembus,563) yang di dalamnya ada pelita besar. Pelita itu di dalam tabung kaca, (dan) tabung kaca itu bagaikan bintang yang berkilauan, yang dinyalakan dengan minyak dari pohon yang diberkahi, (yaitu) pohon zaitun yang tumbuh tidak di timur dan tidak pula di barat,564) yang minyaknya (saja) hampir-hampir menerangi, walaupun tidak disentuh api. Cahaya di atas cahaya (berlapis-lapis), Allah memberi petunjuk kepada cahaya-Nya bagi orang yang Dia kehendaki, dan Allah membuat perumpamaan-perumpamaan bagi manusia. Dan Allah Maha Mengetahui segala sesuatu"},{id:36,text:"\u0641\u0650\u064a \u0628\u064f\u064a\u064f\u0648\u062a\u064d \u0623\u064e\u0630\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0646 \u062a\u064f\u0631\u06e1\u0641\u064e\u0639\u064e \u0648\u064e\u064a\u064f\u0630\u06e1\u0643\u064e\u0631\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0671\u0633\u06e1\u0645\u064f\u0647\u064f\u06e5 \u064a\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u064f \u0644\u064e\u0647\u064f\u06e5 \u0641\u0650\u064a\u0647\u064e\u0627 \u0628\u0650\u0671\u0644\u06e1\u063a\u064f\u062f\u064f\u0648\u0651\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u0653\u0635\u064e\u0627\u0644\u0650",translation:"(Cahaya itu) di rumah-rumah yang di sana telah diperintahkan Allah untuk memuliakan dan menyebut nama-Nya, di sana bertasbih (menyucikan)565) nama-Nya pada waktu pagi dan petang"},{id:37,text:"\u0631\u0650\u062c\u064e\u0627\u0644\u065e \u0644\u0651\u064e\u0627 \u062a\u064f\u0644\u06e1\u0647\u0650\u064a\u0647\u0650\u0645\u06e1 \u062a\u0650\u062c\u064e\u0670\u0631\u064e\u0629\u065e \u0648\u064e\u0644\u064e\u0627 \u0628\u064e\u064a\u06e1\u0639\u064c \u0639\u064e\u0646 \u0630\u0650\u0643\u06e1\u0631\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0625\u0650\u0642\u064e\u0627\u0645\u0650 \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u0650 \u0648\u064e\u0625\u0650\u064a\u062a\u064e\u0627\u0653\u0621\u0650 \u0671\u0644\u0632\u0651\u064e\u0643\u064e\u0648\u0670\u0629\u0650 \u064a\u064e\u062e\u064e\u0627\u0641\u064f\u0648\u0646\u064e \u064a\u064e\u0648\u06e1\u0645\u0657\u0627 \u062a\u064e\u062a\u064e\u0642\u064e\u0644\u0651\u064e\u0628\u064f \u0641\u0650\u064a\u0647\u0650 \u0671\u0644\u06e1\u0642\u064f\u0644\u064f\u0648\u0628\u064f \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0628\u06e1\u0635\u064e\u0670\u0631\u064f",translation:"orang yang tidak dilalaikan oleh perdagangan dan jual beli dari mengingat Allah, melaksanakan salat, dan menunaikan zakat. Mereka takut kepada hari ketika hati dan penglihatan menjadi guncang (hari Kiamat)"},{id:38,text:"\u0644\u0650\u064a\u064e\u062c\u06e1\u0632\u0650\u064a\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064e \u0645\u064e\u0627 \u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0648\u064e\u064a\u064e\u0632\u0650\u064a\u062f\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0641\u064e\u0636\u06e1\u0644\u0650\u0647\u0650\u06e6\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0631\u06e1\u0632\u064f\u0642\u064f \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0628\u0650\u063a\u064e\u064a\u06e1\u0631\u0650 \u062d\u0650\u0633\u064e\u0627\u0628\u0656",translation:"(mereka melakukan itu) agar Allah memberi balasan kepada mereka dengan yang lebih baik daripada apa yang telah mereka kerjakan, dan agar Dia menambah karunia-Nya kepada mereka. Dan Allah memberi rezeki kepada siapa saja yang Dia kehendaki tanpa batas"},{id:39,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0639\u06e1\u0645\u064e\u0670\u0644\u064f\u0647\u064f\u0645\u06e1 \u0643\u064e\u0633\u064e\u0631\u064e\u0627\u0628\u0650\u06ed \u0628\u0650\u0642\u0650\u064a\u0639\u064e\u0629\u0656 \u064a\u064e\u062d\u06e1\u0633\u064e\u0628\u064f\u0647\u064f \u0671\u0644\u0638\u0651\u064e\u0645\u06e1\u0640\u0654\u064e\u0627\u0646\u064f \u0645\u064e\u0627\u0653\u0621\u064b \u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u06e5 \u0644\u064e\u0645\u06e1 \u064a\u064e\u062c\u0650\u062f\u06e1\u0647\u064f \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627 \u0648\u064e\u0648\u064e\u062c\u064e\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u0650\u0646\u062f\u064e\u0647\u064f\u06e5 \u0641\u064e\u0648\u064e\u0641\u0651\u064e\u0649\u0670\u0647\u064f \u062d\u0650\u0633\u064e\u0627\u0628\u064e\u0647\u064f\u06e5\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0633\u064e\u0631\u0650\u064a\u0639\u064f \u0671\u0644\u06e1\u062d\u0650\u0633\u064e\u0627\u0628\u0650",translation:"Dan orang-orang yang kafir, perbuatan mereka seperti fatamorgana di tanah yang datar, yang disangka air oleh orang-orang yang dahaga, tetapi apabila didatangi tidak ada apa pun. Dan didapatinya (ketetapan) Allah baginya. Lalu Allah memberikan kepadanya perhitungan (amal-amal) dengan sempurna, dan Allah sangat cepat perhitungan-Nya"},{id:40,text:"\u0623\u064e\u0648\u06e1 \u0643\u064e\u0638\u064f\u0644\u064f\u0645\u064e\u0670\u062a\u0656 \u0641\u0650\u064a \u0628\u064e\u062d\u06e1\u0631\u0656 \u0644\u0651\u064f\u062c\u0651\u0650\u064a\u0651\u0656 \u064a\u064e\u063a\u06e1\u0634\u064e\u0649\u0670\u0647\u064f \u0645\u064e\u0648\u06e1\u062c\u065e \u0645\u0651\u0650\u0646 \u0641\u064e\u0648\u06e1\u0642\u0650\u0647\u0650\u06e6 \u0645\u064e\u0648\u06e1\u062c\u065e \u0645\u0651\u0650\u0646 \u0641\u064e\u0648\u06e1\u0642\u0650\u0647\u0650\u06e6 \u0633\u064e\u062d\u064e\u0627\u0628\u065e\u06da \u0638\u064f\u0644\u064f\u0645\u064e\u0670\u062a\u064f\u06e2 \u0628\u064e\u0639\u06e1\u0636\u064f\u0647\u064e\u0627 \u0641\u064e\u0648\u06e1\u0642\u064e \u0628\u064e\u0639\u06e1\u0636\u064d \u0625\u0650\u0630\u064e\u0627\u0653 \u0623\u064e\u062e\u06e1\u0631\u064e\u062c\u064e \u064a\u064e\u062f\u064e\u0647\u064f\u06e5 \u0644\u064e\u0645\u06e1 \u064a\u064e\u0643\u064e\u062f\u06e1 \u064a\u064e\u0631\u064e\u0649\u0670\u0647\u064e\u0627\u06d7 \u0648\u064e\u0645\u064e\u0646 \u0644\u0651\u064e\u0645\u06e1 \u064a\u064e\u062c\u06e1\u0639\u064e\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0647\u064f\u06e5 \u0646\u064f\u0648\u0631\u0657\u0627 \u0641\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646 \u0646\u0651\u064f\u0648\u0631\u064d",translation:"atau (keadaan orang-orang kafir) seperti gelap gulita di lautan yang dalam, yang diliputi oleh gelombang demi gelombang, di atasnya ada (lagi) awan gelap. Itulah gelap gulita yang berlapis-lapis. Apabila dia mengeluarkan tangannya hampir tidak dapat melihatnya. Barang siapa tidak diberi cahaya (petunjuk) oleh Allah, maka dia tidak mempunyai cahaya sedikit pun"},{id:41,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0631\u064e \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u064f \u0644\u064e\u0647\u064f\u06e5 \u0645\u064e\u0646 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0671\u0644\u0637\u0651\u064e\u064a\u06e1\u0631\u064f \u0635\u064e\u0640\u0670\u0653\u0641\u0651\u064e\u0640\u0670\u062a\u0656\u06d6 \u0643\u064f\u0644\u0651\u065e \u0642\u064e\u062f\u06e1 \u0639\u064e\u0644\u0650\u0645\u064e \u0635\u064e\u0644\u064e\u0627\u062a\u064e\u0647\u064f\u06e5 \u0648\u064e\u062a\u064e\u0633\u06e1\u0628\u0650\u064a\u062d\u064e\u0647\u064f\u06e5\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064f\u06e2 \u0628\u0650\u0645\u064e\u0627 \u064a\u064e\u0641\u06e1\u0639\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Tidakkah engkau (Muhammad) tahu bahwa kepada Allah lah bertasbih apa yang di langit dan di bumi, dan juga burung yang mengembangkan sayapnya. Masing-masing sungguh telah mengetahui (cara) berdoa dan bertasbih. Allah Maha Mengetahui apa yang mereka kerjakan"},{id:42,text:"\u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064f\u0644\u06e1\u0643\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d6 \u0648\u064e\u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u0645\u064e\u0635\u0650\u064a\u0631\u064f",translation:"Dan milik Allah lah kerajaan langit dan bumi, dan hanya kepada Allah lah kembali (seluruh makhluk)"},{id:43,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0631\u064e \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u0632\u06e1\u062c\u0650\u064a \u0633\u064e\u062d\u064e\u0627\u0628\u0657\u0627 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0624\u064e\u0644\u0651\u0650\u0641\u064f \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u06e5 \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u062c\u06e1\u0639\u064e\u0644\u064f\u0647\u064f\u06e5 \u0631\u064f\u0643\u064e\u0627\u0645\u0657\u0627 \u0641\u064e\u062a\u064e\u0631\u064e\u0649 \u0671\u0644\u06e1\u0648\u064e\u062f\u06e1\u0642\u064e \u064a\u064e\u062e\u06e1\u0631\u064f\u062c\u064f \u0645\u0650\u0646\u06e1 \u062e\u0650\u0644\u064e\u0670\u0644\u0650\u0647\u0650\u06e6 \u0648\u064e\u064a\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0645\u0650\u0646 \u062c\u0650\u0628\u064e\u0627\u0644\u0656 \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0631\u064e\u062f\u0656 \u0641\u064e\u064a\u064f\u0635\u0650\u064a\u0628\u064f \u0628\u0650\u0647\u0650\u06e6 \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0648\u064e\u064a\u064e\u0635\u06e1\u0631\u0650\u0641\u064f\u0647\u064f\u06e5 \u0639\u064e\u0646 \u0645\u0651\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06d6 \u064a\u064e\u0643\u064e\u0627\u062f\u064f \u0633\u064e\u0646\u064e\u0627 \u0628\u064e\u0631\u06e1\u0642\u0650\u0647\u0650\u06e6 \u064a\u064e\u0630\u06e1\u0647\u064e\u0628\u064f \u0628\u0650\u0671\u0644\u06e1\u0623\u064e\u0628\u06e1\u0635\u064e\u0670\u0631\u0650",translation:"Tidakkah engkau melihat bahwa Allah menjadikan awan bergerak perlahan, kemudian mengumpulkannya, lalu dia menjadikannya bertumpuk-tumpuk, lalu engkau lihat hujan ke luar dari celah-celahnya, dan Dia (juga) menurunkan (butiran-butiran) es dari langit, (yaitu) dari (gumpalan-gumpalan awan seperti) gunung-gunung, maka ditimpakan-Nya (butiran-butiran es) itu kepada siapa yang Dia kehendaki dan dihindarkan-Nya dari siapa yang Dia kehendaki. Kilauan kilatnya hampir-hampir menghilangkan penglihatan"},{id:44,text:"\u064a\u064f\u0642\u064e\u0644\u0651\u0650\u0628\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u064e \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e\u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0639\u0650\u0628\u06e1\u0631\u064e\u0629\u0657 \u0644\u0651\u0650\u0623\u064f\u0648\u0652\u0644\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0628\u06e1\u0635\u064e\u0670\u0631\u0650",translation:"Allah mempergantikan malam dan siang. Sungguh pada yang demikian itu, pasti terdapat pelajaran bagi orang-orang yang mempunyai penglihatan (yang tajam)"},{id:45,text:"\u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u062e\u064e\u0644\u064e\u0642\u064e \u0643\u064f\u0644\u0651\u064e \u062f\u064e\u0627\u0653\u0628\u0651\u064e\u0629\u0656 \u0645\u0651\u0650\u0646 \u0645\u0651\u064e\u0627\u0653\u0621\u0656\u06d6 \u0641\u064e\u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0646 \u064a\u064e\u0645\u06e1\u0634\u0650\u064a \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0637\u06e1\u0646\u0650\u0647\u0650\u06e6 \u0648\u064e\u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0646 \u064a\u064e\u0645\u06e1\u0634\u0650\u064a \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u0650\u062c\u06e1\u0644\u064e\u064a\u06e1\u0646\u0650 \u0648\u064e\u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0646 \u064a\u064e\u0645\u06e1\u0634\u0650\u064a \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0631\u06e1\u0628\u064e\u0639\u0656\u06da \u064a\u064e\u062e\u06e1\u0644\u064f\u0642\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0642\u064e\u062f\u0650\u064a\u0631\u065e",translation:"Dan Allah menciptakan semua jenis hewan dari air, maka sebagian ada yang berjalan di atas perutnya dan sebagian berjalan dengan dua kaki, sedang sebagian (yang lain) berjalan dengan empat kaki. Allah menciptakan apa yang Dia kehendaki. Sungguh, Allah Mahakuasa atas segala sesuatu"},{id:46,text:"\u0644\u0651\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0627\u0653 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0656 \u0645\u0651\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0656\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0647\u06e1\u062f\u0650\u064a \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0670\u0637\u0656 \u0645\u0651\u064f\u0633\u06e1\u062a\u064e\u0642\u0650\u064a\u0645\u0656",translation:"Sungguh, Kami telah menurunkan ayat-ayat yang memberi penjelasan. Dan Allah memberi petunjuk siapa yang Dia kehendaki ke jalan yang lurus"},{id:47,text:"\u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0628\u0650\u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0650 \u0648\u064e\u0623\u064e\u0637\u064e\u0639\u06e1\u0646\u064e\u0627 \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649\u0670 \u0641\u064e\u0631\u0650\u064a\u0642\u065e \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0630\u064e\u0670\u0644\u0650\u0643\u064e\u06da \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0628\u0650\u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dan mereka (orang-orang munafik) berkata, \"Kami telah beriman kepada Allah dan Rasul (Muhammad), dan kami menaati (keduanya).\" Kemudian sebagian dari mereka berpaling setelah itu. Mereka itu bukanlah orang-orang beriman"},{id:48,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062f\u064f\u0639\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650\u06e6 \u0644\u0650\u064a\u064e\u062d\u06e1\u0643\u064f\u0645\u064e \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1 \u0625\u0650\u0630\u064e\u0627 \u0641\u064e\u0631\u0650\u064a\u0642\u065e \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064f\u0639\u06e1\u0631\u0650\u0636\u064f\u0648\u0646\u064e",translation:"Dan apabila mereka diajak kepada Allah dan Rasul-Nya, agar (Rasul) memutuskan perkara di antara mereka, tiba-tiba sebagian dari mereka menolak (untuk datang)"},{id:49,text:"\u0648\u064e\u0625\u0650\u0646 \u064a\u064e\u0643\u064f\u0646 \u0644\u0651\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f \u064a\u064e\u0623\u06e1\u062a\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0645\u064f\u0630\u06e1\u0639\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Tetapi, jika kebenaran dipihak mereka, mereka datang kepadanya (Rasul) dengan patuh"},{id:50,text:"\u0623\u064e\u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645 \u0645\u0651\u064e\u0631\u064e\u0636\u064c \u0623\u064e\u0645\u0650 \u0671\u0631\u06e1\u062a\u064e\u0627\u0628\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0645\u06e1 \u064a\u064e\u062e\u064e\u0627\u0641\u064f\u0648\u0646\u064e \u0623\u064e\u0646 \u064a\u064e\u062d\u0650\u064a\u0641\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0647\u064f\u06e5\u06da \u0628\u064e\u0644\u06e1 \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Apakah (ketidakhadiran mereka karena) dalam hati mereka ada penyakit, atau (karena) mereka ragu-ragu ataukah (karena) takut kalau-kalau Allah dan Rasul-Nya berlaku zalim kepada mereka? Sebenarnya, mereka itulah orang-orang yang zalim"},{id:51,text:"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0642\u064e\u0648\u06e1\u0644\u064e \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0625\u0650\u0630\u064e\u0627 \u062f\u064f\u0639\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650\u06e6 \u0644\u0650\u064a\u064e\u062d\u06e1\u0643\u064f\u0645\u064e \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u0646 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627\u0652 \u0633\u064e\u0645\u0650\u0639\u06e1\u0646\u064e\u0627 \u0648\u064e\u0623\u064e\u0637\u064e\u0639\u06e1\u0646\u064e\u0627\u06da \u0648\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064f\u0641\u06e1\u0644\u0650\u062d\u064f\u0648\u0646\u064e",translation:"Hanya ucapan orang-orang mukmin, yang apabila mereka diajak kepada Allah dan Rasul-Nya agar Rasul memutuskan (perkara) di antara mereka,567) mereka berkata, \"Kami mendengar, dan kami taat.\" Dan mereka itulah orang-orang yang beruntung"},{id:52,text:"\u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0637\u0650\u0639\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f\u06e5 \u0648\u064e\u064a\u064e\u062e\u06e1\u0634\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u064a\u064e\u062a\u0651\u064e\u0642\u06e1\u0647\u0650 \u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0641\u064e\u0627\u0653\u0626\u0650\u0632\u064f\u0648\u0646\u064e",translation:"Dan barangsiapa taat kepada Allah dan Rasul-Nya serta takut kepada Allah dan bertakwa kepada-Nya, mereka itulah orang-orang yang mendapat kemenangan"},{id:53,text:"\u06de\u0648\u064e\u0623\u064e\u0642\u06e1\u0633\u064e\u0645\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062c\u064e\u0647\u06e1\u062f\u064e \u0623\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u0650\u0647\u0650\u0645\u06e1 \u0644\u064e\u0626\u0650\u0646\u06e1 \u0623\u064e\u0645\u064e\u0631\u06e1\u062a\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u064a\u064e\u062e\u06e1\u0631\u064f\u062c\u064f\u0646\u0651\u064e\u06d6 \u0642\u064f\u0644 \u0644\u0651\u064e\u0627 \u062a\u064f\u0642\u06e1\u0633\u0650\u0645\u064f\u0648\u0627\u0652\u06d6 \u0637\u064e\u0627\u0639\u064e\u0629\u065e \u0645\u0651\u064e\u0639\u06e1\u0631\u064f\u0648\u0641\u064e\u0629\u064c\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u062e\u064e\u0628\u0650\u064a\u0631\u064f\u06e2 \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan mereka bersumpah dengan (nama) Allah dengan sumpah sungguh-sungguh, bahwa jika engkau suruh mereka berperang, pastilah mereka akan pergi. Katakanlah (Muhammad), \"Janganlah kamu bersumpah, (karena yang diminta) adalah ketaatan yang baik. Sungguh, Allah Mahateliti terhadap apa yang kamu kerjakan"},{id:54,text:"\u0642\u064f\u0644\u06e1 \u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0627\u0652 \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e\u06d6 \u0641\u064e\u0625\u0650\u0646 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u06e1\u0627\u0652 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0645\u064e\u0627 \u062d\u064f\u0645\u0651\u0650\u0644\u064e \u0648\u064e\u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645 \u0645\u0651\u064e\u0627 \u062d\u064f\u0645\u0651\u0650\u0644\u06e1\u062a\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0625\u0650\u0646 \u062a\u064f\u0637\u0650\u064a\u0639\u064f\u0648\u0647\u064f \u062a\u064e\u0647\u06e1\u062a\u064e\u062f\u064f\u0648\u0627\u0652\u06da \u0648\u064e\u0645\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u06e1\u0628\u064e\u0644\u064e\u0670\u063a\u064f \u0671\u0644\u06e1\u0645\u064f\u0628\u0650\u064a\u0646\u064f",translation:"Katakanlah, \"Taatlah kepada Allah dan taatlah kepada Rasul; jika kamu berpaling, maka sesungguhnya kewajiban Rasul (Muhammad) itu hanyalah apa yang dibebankan kepadanya, dan kewajiban kamu hanyalah apa yang dibebankan kepadamu. Jika kamu taat kepadanya, niscaya kamu mendapat petunjuk. Kewajiban Rasul hanyalah menyampaikan (amanat Allah) dengan jelas"},{id:55,text:"\u0648\u064e\u0639\u064e\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0644\u064e\u064a\u064e\u0633\u06e1\u062a\u064e\u062e\u06e1\u0644\u0650\u0641\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0643\u064e\u0645\u064e\u0627 \u0671\u0633\u06e1\u062a\u064e\u062e\u06e1\u0644\u064e\u0641\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0644\u064e\u064a\u064f\u0645\u064e\u0643\u0651\u0650\u0646\u064e\u0646\u0651\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u062f\u0650\u064a\u0646\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0671\u0631\u06e1\u062a\u064e\u0636\u064e\u0649\u0670 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u064a\u064f\u0628\u064e\u062f\u0651\u0650\u0644\u064e\u0646\u0651\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u062e\u064e\u0648\u06e1\u0641\u0650\u0647\u0650\u0645\u06e1 \u0623\u064e\u0645\u06e1\u0646\u0657\u0627\u06da \u064a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0646\u064e\u0646\u0650\u064a \u0644\u064e\u0627 \u064a\u064f\u0634\u06e1\u0631\u0650\u0643\u064f\u0648\u0646\u064e \u0628\u0650\u064a \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627\u06da \u0648\u064e\u0645\u064e\u0646 \u0643\u064e\u0641\u064e\u0631\u064e \u0628\u064e\u0639\u06e1\u062f\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0641\u064e\u0670\u0633\u0650\u0642\u064f\u0648\u0646\u064e",translation:"Allah telah menjanjikan kepada orang-orang di antara kamu yang beriman dan yang mengerjakan kebajikan, bahwa Dia sungguh akan menjadikan mereka berkuasa di bumi sebagaimana Dia telah menjadikan orang-orang sebelum mereka berkuasa, dan sungguh Dia akan meneguhkan bagi mereka dengan agama yang telah Dia ridai. Dan Dia benar-benar mengubah (keadaan) mereka, setelah berada dalam ketakutan menjadi aman sentosa. Mereka (tetap) menyembah-Ku dengan tidak mempersekutukan-Ku dengan sesuatu pun. Tetapi barangsiapa (tetap) kafir setelah (janji) itu, maka mereka itulah orang-orang yang fasik"},{id:56,text:"\u0648\u064e\u0623\u064e\u0642\u0650\u064a\u0645\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u0621\u064e\u0627\u062a\u064f\u0648\u0627\u0652 \u0671\u0644\u0632\u0651\u064e\u0643\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0627\u0652 \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064f\u0631\u06e1\u062d\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan laksanakanlah salat, tunaikanlah zakat dan taatlah kepada Rasul (Muhammad), agar kamu diberi rahmat"},{id:57,text:"\u0644\u064e\u0627 \u062a\u064e\u062d\u06e1\u0633\u064e\u0628\u064e\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0645\u064f\u0639\u06e1\u062c\u0650\u0632\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06da \u0648\u064e\u0645\u064e\u0623\u06e1\u0648\u064e\u0649\u0670\u0647\u064f\u0645\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u064f\u06d6 \u0648\u064e\u0644\u064e\u0628\u0650\u0626\u06e1\u0633\u064e \u0671\u0644\u06e1\u0645\u064e\u0635\u0650\u064a\u0631\u064f",translation:"Janganlah engkau mengira bahwa orang-orang yang kafir itu dapat luput dari siksaan Allah di bumi; sedang tempat kembali mereka (di akhirat) adalah neraka. Dan itulah seburuk-buruk tempat kembali"},{id:58,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0644\u0650\u064a\u064e\u0633\u06e1\u062a\u064e\u0640\u0654\u06e1\u0630\u0650\u0646\u0643\u064f\u0645\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u064e\u0644\u064e\u0643\u064e\u062a\u06e1 \u0623\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u064f\u0643\u064f\u0645\u06e1 \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0645\u06e1 \u064a\u064e\u0628\u06e1\u0644\u064f\u063a\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u062d\u064f\u0644\u064f\u0645\u064e \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u062b\u064e\u0644\u064e\u0670\u062b\u064e \u0645\u064e\u0631\u0651\u064e\u0640\u0670\u062a\u0656\u06da \u0645\u0651\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650 \u0635\u064e\u0644\u064e\u0648\u0670\u0629\u0650 \u0671\u0644\u06e1\u0641\u064e\u062c\u06e1\u0631\u0650 \u0648\u064e\u062d\u0650\u064a\u0646\u064e \u062a\u064e\u0636\u064e\u0639\u064f\u0648\u0646\u064e \u062b\u0650\u064a\u064e\u0627\u0628\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0638\u0651\u064e\u0647\u0650\u064a\u0631\u064e\u0629\u0650 \u0648\u064e\u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0635\u064e\u0644\u064e\u0648\u0670\u0629\u0650 \u0671\u0644\u06e1\u0639\u0650\u0634\u064e\u0627\u0653\u0621\u0650\u06da \u062b\u064e\u0644\u064e\u0670\u062b\u064f \u0639\u064e\u0648\u06e1\u0631\u064e\u0670\u062a\u0656 \u0644\u0651\u064e\u0643\u064f\u0645\u06e1\u06da \u0644\u064e\u064a\u06e1\u0633\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u062c\u064f\u0646\u064e\u0627\u062d\u064f\u06e2 \u0628\u064e\u0639\u06e1\u062f\u064e\u0647\u064f\u0646\u0651\u064e\u06da \u0637\u064e\u0648\u0651\u064e\u0640\u0670\u0641\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645 \u0628\u064e\u0639\u06e1\u0636\u064f\u0643\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u06e1\u0636\u0656\u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0623\u0653\u064a\u064e\u0670\u062a\u0650\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u065e",translation:"Wahai orang-orang yang beriman! Hendaklah hamba sahaya (laki-laki dan perempuan) yang kamu miliki, dan orang-orang yang belum balig (dewasa) di antara kamu, meminta izin kepada kamu pada tiga kali (kesempatan), yaitu sebelum salat Subuh, ketika kamu menanggalkan pakaian (luar)mu di tengah hari dan setelah salat Isya. (Itulah) tiga aurat (waktu) bagi kamu.568) Tidak ada dosa bagimu dan tidak (pula) bagi mereka selain dari (tiga waktu) itu, mereka keluar masuk melayani kamu, sebagian kamu atas sebagian yang lain. Demikianlah Allah menjelaskan ayat-ayat itu kepadamu. Dan Allah Maha Mengetahui, Mahabijaksana"},{id:59,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0628\u064e\u0644\u064e\u063a\u064e \u0671\u0644\u06e1\u0623\u064e\u0637\u06e1\u0641\u064e\u0670\u0644\u064f \u0645\u0650\u0646\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u062d\u064f\u0644\u064f\u0645\u064e \u0641\u064e\u0644\u06e1\u064a\u064e\u0633\u06e1\u062a\u064e\u0640\u0654\u06e1\u0630\u0650\u0646\u064f\u0648\u0627\u0652 \u0643\u064e\u0645\u064e\u0627 \u0671\u0633\u06e1\u062a\u064e\u0640\u0654\u06e1\u0630\u064e\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u0645\u06e1\u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0647\u0650\u06e6\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u065e",translation:"Dan apabila anak-anakmu telah sampai umur dewasa, maka hendaklah mereka (juga) meminta izin, seperti orang-orang yang lebih dewasa meminta izin.569) Demikianlah Allah menjelaskan ayat-ayat-Nya kepadamu. Allah Maha Mengetahui, Mahabijaksana"},{id:60,text:"\u0648\u064e\u0671\u0644\u06e1\u0642\u064e\u0648\u064e\u0670\u0639\u0650\u062f\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0653\u0621\u0650 \u0671\u0644\u0651\u064e\u0640\u0670\u062a\u0650\u064a \u0644\u064e\u0627 \u064a\u064e\u0631\u06e1\u062c\u064f\u0648\u0646\u064e \u0646\u0650\u0643\u064e\u0627\u062d\u0657\u0627 \u0641\u064e\u0644\u064e\u064a\u06e1\u0633\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0646\u0651\u064e \u062c\u064f\u0646\u064e\u0627\u062d\u064c \u0623\u064e\u0646 \u064a\u064e\u0636\u064e\u0639\u06e1\u0646\u064e \u062b\u0650\u064a\u064e\u0627\u0628\u064e\u0647\u064f\u0646\u0651\u064e \u063a\u064e\u064a\u06e1\u0631\u064e \u0645\u064f\u062a\u064e\u0628\u064e\u0631\u0651\u0650\u062c\u064e\u0670\u062a\u0650\u06ed \u0628\u0650\u0632\u0650\u064a\u0646\u064e\u0629\u0656\u06d6 \u0648\u064e\u0623\u064e\u0646 \u064a\u064e\u0633\u06e1\u062a\u064e\u0639\u06e1\u0641\u0650\u0641\u06e1\u0646\u064e \u062e\u064e\u064a\u06e1\u0631\u065e \u0644\u0651\u064e\u0647\u064f\u0646\u0651\u064e\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0633\u064e\u0645\u0650\u064a\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Dan para perempuan tua yang telah berhenti (dari haid dan mengandung) yang tidak ingin menikah (lagi), maka tidak ada dosa menanggalkan pakaian (luar)570) mereka dengan tidak (bermaksud) menampakkan perhiasan; tetapi memelihara kehormatan adalah lebih baik bagi mereka. Allah Maha Mendengar, Maha Mengetahui"},{id:61,text:"\u0644\u0651\u064e\u064a\u06e1\u0633\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0623\u064e\u0639\u06e1\u0645\u064e\u0649\u0670 \u062d\u064e\u0631\u064e\u062c\u065e \u0648\u064e\u0644\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0623\u064e\u0639\u06e1\u0631\u064e\u062c\u0650 \u062d\u064e\u0631\u064e\u062c\u065e \u0648\u064e\u0644\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0645\u064e\u0631\u0650\u064a\u0636\u0650 \u062d\u064e\u0631\u064e\u062c\u065e \u0648\u064e\u0644\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u06e1 \u0623\u064e\u0646 \u062a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e2 \u0628\u064f\u064a\u064f\u0648\u062a\u0650\u0643\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1 \u0628\u064f\u064a\u064f\u0648\u062a\u0650 \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0626\u0650\u0643\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1 \u0628\u064f\u064a\u064f\u0648\u062a\u0650 \u0623\u064f\u0645\u0651\u064e\u0647\u064e\u0670\u062a\u0650\u0643\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1 \u0628\u064f\u064a\u064f\u0648\u062a\u0650 \u0625\u0650\u062e\u06e1\u0648\u064e\u0670\u0646\u0650\u0643\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1 \u0628\u064f\u064a\u064f\u0648\u062a\u0650 \u0623\u064e\u062e\u064e\u0648\u064e\u0670\u062a\u0650\u0643\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1 \u0628\u064f\u064a\u064f\u0648\u062a\u0650 \u0623\u064e\u0639\u06e1\u0645\u064e\u0670\u0645\u0650\u0643\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1 \u0628\u064f\u064a\u064f\u0648\u062a\u0650 \u0639\u064e\u0645\u0651\u064e\u0640\u0670\u062a\u0650\u0643\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1 \u0628\u064f\u064a\u064f\u0648\u062a\u0650 \u0623\u064e\u062e\u06e1\u0648\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1 \u0628\u064f\u064a\u064f\u0648\u062a\u0650 \u062e\u064e\u0670\u0644\u064e\u0670\u062a\u0650\u0643\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1 \u0645\u064e\u0627 \u0645\u064e\u0644\u064e\u0643\u06e1\u062a\u064f\u0645 \u0645\u0651\u064e\u0641\u064e\u0627\u062a\u0650\u062d\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u0648\u06e1 \u0635\u064e\u062f\u0650\u064a\u0642\u0650\u0643\u064f\u0645\u06e1\u06da \u0644\u064e\u064a\u06e1\u0633\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u062c\u064f\u0646\u064e\u0627\u062d\u064c \u0623\u064e\u0646 \u062a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f\u0648\u0627\u0652 \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u0623\u064e\u0648\u06e1 \u0623\u064e\u0634\u06e1\u062a\u064e\u0627\u062a\u0657\u0627\u06da \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u062f\u064e\u062e\u064e\u0644\u06e1\u062a\u064f\u0645 \u0628\u064f\u064a\u064f\u0648\u062a\u0657\u0627 \u0641\u064e\u0633\u064e\u0644\u0651\u0650\u0645\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u06e1 \u062a\u064e\u062d\u0650\u064a\u0651\u064e\u0629\u0657 \u0645\u0651\u0650\u0646\u06e1 \u0639\u0650\u0646\u062f\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064f\u0628\u064e\u0670\u0631\u064e\u0643\u064e\u0629\u0657 \u0637\u064e\u064a\u0651\u0650\u0628\u064e\u0629\u0657\u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0623\u0653\u064a\u064e\u0670\u062a\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Tidak ada halangan bagi orang buta, tidak (pula) bagi orang pincang, tidak (pula) bagi orang sakit, dan tidak (pula) bagi dirimu, makan (bersama-sama mereka) di rumah kamu atau di rumah bapak-bapakmu, di rumah ibu-ibumu, di rumah saudara-saudaramu yang laki-laki, di rumah saudara-saudaramu yang perempuan, di rumah saudara-saudara bapakmu yang laki-laki, di rumah saudara-saudara bapakmu yang perempuan, di rumah saudara-saudara ibumu yang laki-laki, di rumah saudara-saudara ibumu yang perempuan, (di rumah) yang kamu miliki kuncinya571) atau (di rumah) kawan-kawanmu. Tidak ada halangan bagi kamu makan bersama-sama mereka atau sendiri-sendiri. Apabila kamu memasuki rumah-rumah hendaklah kamu memberi salam (kepada penghuninya, yang berarti memberi salam) kepada dirimu sendiri, dengan salam yang penuh berkah dan baik dari sisi Allah. Demikianlah Allah menjelaskan ayat-ayat(-Nya) bagimu, agar kamu mengerti"},{id:62,text:"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650\u06e6 \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0645\u064e\u0639\u064e\u0647\u064f\u06e5 \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0645\u06e1\u0631\u0656 \u062c\u064e\u0627\u0645\u0650\u0639\u0656 \u0644\u0651\u064e\u0645\u06e1 \u064a\u064e\u0630\u06e1\u0647\u064e\u0628\u064f\u0648\u0627\u0652 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0633\u06e1\u062a\u064e\u0640\u0654\u06e1\u0630\u0650\u0646\u064f\u0648\u0647\u064f\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0633\u06e1\u062a\u064e\u0640\u0654\u06e1\u0630\u0650\u0646\u064f\u0648\u0646\u064e\u0643\u064e \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650\u06e6\u06da \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0671\u0633\u06e1\u062a\u064e\u0640\u0654\u06e1\u0630\u064e\u0646\u064f\u0648\u0643\u064e \u0644\u0650\u0628\u064e\u0639\u06e1\u0636\u0650 \u0634\u064e\u0623\u06e1\u0646\u0650\u0647\u0650\u0645\u06e1 \u0641\u064e\u0623\u06e1\u0630\u064e\u0646 \u0644\u0651\u0650\u0645\u064e\u0646 \u0634\u0650\u0626\u06e1\u062a\u064e \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0648\u064e\u0671\u0633\u06e1\u062a\u064e\u063a\u06e1\u0641\u0650\u0631\u06e1 \u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064e\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u065e",translation:"(Yang disebut) orang mukmin hanyalah orang yang beriman kepada Allah dan Rasul-Nya (Muhammad), dan apabila mereka berada bersama-sama dengan dia (Muhammad) dalam suatu urusan bersama, mereka tidak meninggalkan (Rasulullah) sebelum meminta izin kepadanya. Sungguh orang-orang yang meminta izin kepadamu (Muhammad), mereka itulah orang-orang yang (benar-benar) beriman kepada Allah dan Rasul-nya. Maka apabila mereka meminta izin kepadamu karena suatu keperluan, berilah izin kepada siapa yang engkau kehendaki di antara mereka, dan mohonkanlah ampunan untuk mereka kepada Allah. Sungguh, Allah Maha Pengampun, Maha Penyayang"},{id:63,text:"\u0644\u0651\u064e\u0627 \u062a\u064e\u062c\u06e1\u0639\u064e\u0644\u064f\u0648\u0627\u0652 \u062f\u064f\u0639\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0650 \u0628\u064e\u064a\u06e1\u0646\u064e\u0643\u064f\u0645\u06e1 \u0643\u064e\u062f\u064f\u0639\u064e\u0627\u0653\u0621\u0650 \u0628\u064e\u0639\u06e1\u0636\u0650\u0643\u064f\u0645 \u0628\u064e\u0639\u06e1\u0636\u0657\u0627\u06da \u0642\u064e\u062f\u06e1 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062a\u064e\u0633\u064e\u0644\u0651\u064e\u0644\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u0644\u0650\u0648\u064e\u0627\u0630\u0657\u0627\u06da \u0641\u064e\u0644\u06e1\u064a\u064e\u062d\u06e1\u0630\u064e\u0631\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u062e\u064e\u0627\u0644\u0650\u0641\u064f\u0648\u0646\u064e \u0639\u064e\u0646\u06e1 \u0623\u064e\u0645\u06e1\u0631\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0646 \u062a\u064f\u0635\u0650\u064a\u0628\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u062a\u06e1\u0646\u064e\u0629\u064c \u0623\u064e\u0648\u06e1 \u064a\u064f\u0635\u0650\u064a\u0628\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064c",translation:"Janganlah kamu jadikan panggilan Rasul (Muhammad) di antara kamu seperti panggilan sebagian kamu kepada sebagian (yang lain). Sungguh, Allah mengetahui orang-orang yang keluar (secara) sembunyi-sembunyi di antara kamu dengan berlindung (kepada kawannya), maka hendaklah orang-orang yang menyalahi perintah Rasul-Nya takut akan mendapat cobaan atau ditimpa azab yang pedih"},{id:64,text:"\u0623\u064e\u0644\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d6 \u0642\u064e\u062f\u06e1 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0648\u064e\u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064f\u0631\u06e1\u062c\u064e\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0641\u064e\u064a\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0647\u064f\u0645 \u0628\u0650\u0645\u064e\u0627 \u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u064f\u06e2",translation:"Ketahuilah, sesungguhnya milik Allah lah apa yang ada di langit dan di bumi. Dia mengetahui keadaan kamu sekarang. Dan (mengetahui pula) hari (ketika mereka) dikembalikan kepada-Nya, lalu diterangkan-Nya kepada mereka apa yang telah mereka kerjakan. Dan Allah Maha Mengetahui segala sesuatu"}]},{id:25,name:"\u0627\u0644\u0641\u0631\u0642\u0627\u0646",transliteration:"Al-Furqan",translation:"Pembeda",type:"meccan",total_verses:77,verses:[{id:1,text:"\u062a\u064e\u0628\u064e\u0627\u0631\u064e\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0646\u064e\u0632\u0651\u064e\u0644\u064e \u0671\u0644\u06e1\u0641\u064f\u0631\u06e1\u0642\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0639\u064e\u0628\u06e1\u062f\u0650\u0647\u0650\u06e6 \u0644\u0650\u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0644\u0650\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e \u0646\u064e\u0630\u0650\u064a\u0631\u064b\u0627",translation:"Mahasuci Allah yang telah menurunkan Furqan (Alquran) kepada hamba-Nya (Muhammad), agar dia menjadi pemberi peringatan kepada seluruh alam (jin dan manusia)"},{id:2,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0644\u064e\u0647\u064f\u06e5 \u0645\u064f\u0644\u06e1\u0643\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u06e1 \u0648\u064e\u0644\u064e\u062f\u0657\u0627 \u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0643\u064f\u0646 \u0644\u0651\u064e\u0647\u064f\u06e5 \u0634\u064e\u0631\u0650\u064a\u0643\u065e \u0641\u0650\u064a \u0671\u0644\u06e1\u0645\u064f\u0644\u06e1\u0643\u0650 \u0648\u064e\u062e\u064e\u0644\u064e\u0642\u064e \u0643\u064f\u0644\u0651\u064e \u0634\u064e\u064a\u06e1\u0621\u0656 \u0641\u064e\u0642\u064e\u062f\u0651\u064e\u0631\u064e\u0647\u064f\u06e5 \u062a\u064e\u0642\u06e1\u062f\u0650\u064a\u0631\u0657\u0627",translation:"Yang memiliki kerajaan langit dan bumi, tidak mempunyai anak, tidak ada sekutu bagi-Nya dalam kekusaan (-Nya), dan Dia menciptakan segala sesuatu, lalu menetapkan ukuran-ukurannya dengan tepat"},{id:3,text:"\u0648\u064e\u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u06e6\u0653 \u0621\u064e\u0627\u0644\u0650\u0647\u064e\u0629\u0657 \u0644\u0651\u064e\u0627 \u064a\u064e\u062e\u06e1\u0644\u064f\u0642\u064f\u0648\u0646\u064e \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627 \u0648\u064e\u0647\u064f\u0645\u06e1 \u064a\u064f\u062e\u06e1\u0644\u064e\u0642\u064f\u0648\u0646\u064e \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0645\u06e1\u0644\u0650\u0643\u064f\u0648\u0646\u064e \u0644\u0650\u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u06e1 \u0636\u064e\u0631\u0651\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0641\u06e1\u0639\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0645\u06e1\u0644\u0650\u0643\u064f\u0648\u0646\u064e \u0645\u064e\u0648\u06e1\u062a\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u062d\u064e\u064a\u064e\u0648\u0670\u0629\u0657 \u0648\u064e\u0644\u064e\u0627 \u0646\u064f\u0634\u064f\u0648\u0631\u0657\u0627",translation:"Namun mereka mengambil tuhan-tuhan selain Dia (untuk disembah), padahal mereka (tuhan-tuhan itu) tidak menciptakan apa pun, bahkan mereka sendiri diciptakan dan tidak kuasa untuk (menolak) bahaya terhadap dirinya dan tidak dapat (mendatangkan) manfaat serta tidak kuasa mematikan, menghidupkan dan tidak (pula) membangkitkan"},{id:4,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u06e1 \u0647\u064e\u0670\u0630\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0625\u0650\u0641\u06e1\u0643\u064c \u0671\u0641\u06e1\u062a\u064e\u0631\u064e\u0649\u0670\u0647\u064f \u0648\u064e\u0623\u064e\u0639\u064e\u0627\u0646\u064e\u0647\u064f\u06e5 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0642\u064e\u0648\u06e1\u0645\u064c \u0621\u064e\u0627\u062e\u064e\u0631\u064f\u0648\u0646\u064e\u06d6 \u0641\u064e\u0642\u064e\u062f\u06e1 \u062c\u064e\u0627\u0653\u0621\u064f\u0648 \u0638\u064f\u0644\u06e1\u0645\u0657\u0627 \u0648\u064e\u0632\u064f\u0648\u0631\u0657\u0627",translation:"Dan orang-orang kafir berkata, \"(Alquran) ini tidak lain hanyalah kebohongan yang diada-adakan oleh dia (Muhammad), dibantu oleh orang-orang lain.\" Sungguh, mereka telah berbuat zalim dan dusta yang besar"},{id:5,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0633\u064e\u0670\u0637\u0650\u064a\u0631\u064f \u0671\u0644\u06e1\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e \u0671\u0643\u06e1\u062a\u064e\u062a\u064e\u0628\u064e\u0647\u064e\u0627 \u0641\u064e\u0647\u0650\u064a\u064e \u062a\u064f\u0645\u06e1\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0628\u064f\u0643\u06e1\u0631\u064e\u0629\u0657 \u0648\u064e\u0623\u064e\u0635\u0650\u064a\u0644\u0657\u0627",translation:"Dan mereka berkata, \"(Itu hanya) dongeng-dongeng orang-orang terdahulu, yang diminta agar dituliskan, lalu dibacakanlah dongeng itu kepadanya setiap pagi dan petang"},{id:6,text:"\u0642\u064f\u0644\u06e1 \u0623\u064e\u0646\u0632\u064e\u0644\u064e\u0647\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0671\u0644\u0633\u0651\u0650\u0631\u0651\u064e \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0643\u064e\u0627\u0646\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u0657\u0627 \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0657\u0627",translation:"Katakanlah (Muhammad), \"(Alquran) itu diturunkan oleh (Allah) yang mengetahui rahasia di langit dan di bumi. Sungguh, Dia Maha Pengampun, Maha Penyayang"},{id:7,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0645\u064e\u0627\u0644\u0650 \u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0650 \u064a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f \u0671\u0644\u0637\u0651\u064e\u0639\u064e\u0627\u0645\u064e \u0648\u064e\u064a\u064e\u0645\u06e1\u0634\u0650\u064a \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0633\u06e1\u0648\u064e\u0627\u0642\u0650 \u0644\u064e\u0648\u06e1\u0644\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0645\u064e\u0644\u064e\u0643\u065e \u0641\u064e\u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u064e\u0639\u064e\u0647\u064f\u06e5 \u0646\u064e\u0630\u0650\u064a\u0631\u064b\u0627",translation:"Dan mereka berkata, \"Mengapa Rasul (Muhammad) ini memakan makanan dan berjalan di pasar-pasar? Mengapa malaikat tidak diturunkan kepadanya (agar malaikat) itu memberikan peringatan bersama dia"},{id:8,text:"\u0623\u064e\u0648\u06e1 \u064a\u064f\u0644\u06e1\u0642\u064e\u0649\u0670\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0643\u064e\u0646\u0632\u064c \u0623\u064e\u0648\u06e1 \u062a\u064e\u0643\u064f\u0648\u0646\u064f \u0644\u064e\u0647\u064f\u06e5 \u062c\u064e\u0646\u0651\u064e\u0629\u065e \u064a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f \u0645\u0650\u0646\u06e1\u0647\u064e\u0627\u06da \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u064f\u0648\u0646\u064e \u0625\u0650\u0646 \u062a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0631\u064e\u062c\u064f\u0644\u0657\u0627 \u0645\u0651\u064e\u0633\u06e1\u062d\u064f\u0648\u0631\u064b\u0627",translation:"atau (mengapa tidak) diturunkan kepadanya harta kekayaan atau (mengapa tidak ada) kebun baginya, sehingga dia dapat makan dari(hasil)nya?\" Dan orang-orang zalim itu berkata, \"Kamu hanyalah mengikuti seorang laki-laki yang kena sihir"},{id:9,text:"\u0671\u0646\u0638\u064f\u0631\u06e1 \u0643\u064e\u064a\u06e1\u0641\u064e \u0636\u064e\u0631\u064e\u0628\u064f\u0648\u0627\u0652 \u0644\u064e\u0643\u064e \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u062b\u064e\u0670\u0644\u064e \u0641\u064e\u0636\u064e\u0644\u0651\u064f\u0648\u0627\u0652 \u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u064e \u0633\u064e\u0628\u0650\u064a\u0644\u0657\u0627",translation:"Perhatikanlah, bagaimana mereka membuat perumpamaan-perumpamaan tentang engkau, maka sesatlah mereka, mereka tidak sanggup (mendapatkan) jalan (untuk menentang kerasulanmu)"},{id:10,text:"\u062a\u064e\u0628\u064e\u0627\u0631\u064e\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0625\u0650\u0646 \u0634\u064e\u0627\u0653\u0621\u064e \u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064e \u062e\u064e\u064a\u06e1\u0631\u0657\u0627 \u0645\u0651\u0650\u0646 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0656 \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0645\u0650\u0646 \u062a\u064e\u062d\u06e1\u062a\u0650\u0647\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u064f \u0648\u064e\u064a\u064e\u062c\u06e1\u0639\u064e\u0644 \u0644\u0651\u064e\u0643\u064e \u0642\u064f\u0635\u064f\u0648\u0631\u064e\u06e2\u0627",translation:"Mahasuci (Allah) yang jika Dia menghendaki, niscaya Dia jadikan bagimu yang lebih baik daripada itu, (yaitu) surga-surga yang mengalir di bawahnya sungai-sungai, dan Dia jadikan (pula) istana-istana untukmu"},{id:11,text:"\u0628\u064e\u0644\u06e1 \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u0650\u06d6 \u0648\u064e\u0623\u064e\u0639\u06e1\u062a\u064e\u062f\u06e1\u0646\u064e\u0627 \u0644\u0650\u0645\u064e\u0646 \u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0628\u0650\u0671\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u0650 \u0633\u064e\u0639\u0650\u064a\u0631\u064b\u0627",translation:"Bahkan mereka mendustakan hari Kiamat. Dan kami menyediakan neraka yang menyala-nyala bagi siapa yang mendustakan hari Kiamat"},{id:12,text:"\u0625\u0650\u0630\u064e\u0627 \u0631\u064e\u0623\u064e\u062a\u06e1\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0645\u0651\u064e\u0643\u064e\u0627\u0646\u0650\u06ed \u0628\u064e\u0639\u0650\u064a\u062f\u0656 \u0633\u064e\u0645\u0650\u0639\u064f\u0648\u0627\u0652 \u0644\u064e\u0647\u064e\u0627 \u062a\u064e\u063a\u064e\u064a\u0651\u064f\u0638\u0657\u0627 \u0648\u064e\u0632\u064e\u0641\u0650\u064a\u0631\u0657\u0627",translation:"Apabila ia (neraka) melihat mereka dari tempat yang jauh, mereka mendengar suaranya yang gemuruh karena marahnya"},{id:13,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627\u0653 \u0623\u064f\u0644\u06e1\u0642\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0645\u064e\u0643\u064e\u0627\u0646\u0657\u0627 \u0636\u064e\u064a\u0651\u0650\u0642\u0657\u0627 \u0645\u0651\u064f\u0642\u064e\u0631\u0651\u064e\u0646\u0650\u064a\u0646\u064e \u062f\u064e\u0639\u064e\u0648\u06e1\u0627\u0652 \u0647\u064f\u0646\u064e\u0627\u0644\u0650\u0643\u064e \u062b\u064f\u0628\u064f\u0648\u0631\u0657\u0627",translation:"Dan apabila mereka dilemparkan ke tempat yang sempit di neraka dengan dibelenggu, mereka di sana berteriak mengharapkan kebinasaan"},{id:14,text:"\u0644\u0651\u064e\u0627 \u062a\u064e\u062f\u06e1\u0639\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e \u062b\u064f\u0628\u064f\u0648\u0631\u0657\u0627 \u0648\u064e\u0670\u062d\u0650\u062f\u0657\u0627 \u0648\u064e\u0671\u062f\u06e1\u0639\u064f\u0648\u0627\u0652 \u062b\u064f\u0628\u064f\u0648\u0631\u0657\u0627 \u0643\u064e\u062b\u0650\u064a\u0631\u0657\u0627",translation:"(Akan dikatakan kepada mereka), \"Janganlah kamu mengharapkan pada hari ini satu kebinasaan, melainkan harapkanlah kebinasaan yang berulang-ulang"},{id:15,text:"\u0642\u064f\u0644\u06e1 \u0623\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062e\u064e\u064a\u06e1\u0631\u064c \u0623\u064e\u0645\u06e1 \u062c\u064e\u0646\u0651\u064e\u0629\u064f \u0671\u0644\u06e1\u062e\u064f\u0644\u06e1\u062f\u0650 \u0671\u0644\u0651\u064e\u062a\u0650\u064a \u0648\u064f\u0639\u0650\u062f\u064e \u0671\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e\u06da \u0643\u064e\u0627\u0646\u064e\u062a\u06e1 \u0644\u064e\u0647\u064f\u0645\u06e1 \u062c\u064e\u0632\u064e\u0627\u0653\u0621\u0657 \u0648\u064e\u0645\u064e\u0635\u0650\u064a\u0631\u0657\u0627",translation:"Katakanlah (Muhammad), \"Apakah (azab) seperti itu yang baik, atau surga yang kekal yang dijanjikan kepada orang-orang yang bertakwa sebagai balasan, dan tempat kembali bagi mereka"},{id:16,text:"\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u0648\u0646\u064e \u062e\u064e\u0670\u0644\u0650\u062f\u0650\u064a\u0646\u064e\u06da \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0648\u064e\u0639\u06e1\u062f\u0657\u0627 \u0645\u0651\u064e\u0633\u06e1\u0640\u0654\u064f\u0648\u0644\u0657\u0627",translation:"Bagi mereka segala yang mereka kehendaki ada di dalamnya (surga), mereka kekal (di dalamnya). Itulah janji Tuhanmu yang pantas dimohonkan (kepada-Nya)"},{id:17,text:"\u0648\u064e\u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064e\u062d\u06e1\u0634\u064f\u0631\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0621\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0623\u064e\u0636\u06e1\u0644\u064e\u0644\u06e1\u062a\u064f\u0645\u06e1 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a \u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650 \u0623\u064e\u0645\u06e1 \u0647\u064f\u0645\u06e1 \u0636\u064e\u0644\u0651\u064f\u0648\u0627\u0652 \u0671\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u064e",translation:"Dan (ingatlah) pada hari (ketika) Allah mengumpulkan mereka bersama apa yang mereka sembah selain Allah, lalu Dia berfirman (kepada yang disembah), \"Apakah kamu yang menyesatkan hamba-hamba-Ku itu, atau mereka sendirikah yang sesat dari jalan (yang benar)"},{id:18,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0633\u064f\u0628\u06e1\u062d\u064e\u0670\u0646\u064e\u0643\u064e \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u064a\u064e\u0646\u06e2\u0628\u064e\u063a\u0650\u064a \u0644\u064e\u0646\u064e\u0627\u0653 \u0623\u064e\u0646 \u0646\u0651\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0643\u064e \u0645\u0650\u0646\u06e1 \u0623\u064e\u0648\u06e1\u0644\u0650\u064a\u064e\u0627\u0653\u0621\u064e \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u0645\u0651\u064e\u062a\u0651\u064e\u0639\u06e1\u062a\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u06e1 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0646\u064e\u0633\u064f\u0648\u0627\u0652 \u0671\u0644\u0630\u0651\u0650\u0643\u06e1\u0631\u064e \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0642\u064e\u0648\u06e1\u0645\u064e\u06e2\u0627 \u0628\u064f\u0648\u0631\u0657\u0627",translation:"Mereka (yang disembah itu) menjawab, \"Mahasuci Engkau, tidaklah pantas bagi kami mengambil pelindung selain Engkau,573) tetapi Engkau telah memberi mereka dan nenek moyang mereka kenikmatan hidup, sehingga mereka melupakan peringatan; dan mereka kaum yang binasa"},{id:19,text:"\u0641\u064e\u0642\u064e\u062f\u06e1 \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0643\u064f\u0645 \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0641\u064e\u0645\u064e\u0627 \u062a\u064e\u0633\u06e1\u062a\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u064e \u0635\u064e\u0631\u06e1\u0641\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0635\u06e1\u0631\u0657\u0627\u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0638\u06e1\u0644\u0650\u0645 \u0645\u0651\u0650\u0646\u0643\u064f\u0645\u06e1 \u0646\u064f\u0630\u0650\u0642\u06e1\u0647\u064f \u0639\u064e\u0630\u064e\u0627\u0628\u0657\u0627 \u0643\u064e\u0628\u0650\u064a\u0631\u0657\u0627",translation:"Maka sungguh, mereka (yang disembah itu) telah mengingkari apa yang kamu katakan, maka kamu tidak akan dapat menolak (azab) dan tidak dapat (pula) menolong (dirimu), dan barang siapa di antara kamu berbuat zalim, niscaya Kami timpakan kepadanya rasa azab yang besar"},{id:20,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0642\u064e\u0628\u06e1\u0644\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0631\u06e1\u0633\u064e\u0644\u0650\u064a\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u064a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f\u0648\u0646\u064e \u0671\u0644\u0637\u0651\u064e\u0639\u064e\u0627\u0645\u064e \u0648\u064e\u064a\u064e\u0645\u06e1\u0634\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0633\u06e1\u0648\u064e\u0627\u0642\u0650\u06d7 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0628\u064e\u0639\u06e1\u0636\u064e\u0643\u064f\u0645\u06e1 \u0644\u0650\u0628\u064e\u0639\u06e1\u0636\u0656 \u0641\u0650\u062a\u06e1\u0646\u064e\u0629\u064b \u0623\u064e\u062a\u064e\u0635\u06e1\u0628\u0650\u0631\u064f\u0648\u0646\u064e\u06d7 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0628\u064e\u0635\u0650\u064a\u0631\u0657\u0627",translation:"Dan Kami tidak mengutus rasul-rasul sebelummu (Muhammad), melainkan mereka pasti memakan makanan dan berjalan di pasar-pasar. Dan Kami jadikan sebagian kamu sebagai cobaan bagi sebagian yang lain. Maukah kamu bersabar? Dan Tuhanmu Maha Melihat"},{id:21,text:"\u06de\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u0631\u06e1\u062c\u064f\u0648\u0646\u064e \u0644\u0650\u0642\u064e\u0627\u0653\u0621\u064e\u0646\u064e\u0627 \u0644\u064e\u0648\u06e1\u0644\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u064f \u0623\u064e\u0648\u06e1 \u0646\u064e\u0631\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627\u06d7 \u0644\u064e\u0642\u064e\u062f\u0650 \u0671\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u064e\u0631\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0653 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0639\u064e\u062a\u064e\u0648\u06e1 \u0639\u064f\u062a\u064f\u0648\u0651\u0657\u0627 \u0643\u064e\u0628\u0650\u064a\u0631\u0657\u0627",translation:"Dan orang-orang yang tidak mengharapkan pertemuan dengan Kami (di akhirat) berkata, \"Mengapa bukan para malaikat yang diturunkan kepada kita atau (mengapa) kita (tidak) melihat Tuhan kita?\" Sungguh, mereka telah menyombongkan diri mereka dan benar-benar telah melampaui batas (dalam melakukan kezaliman)"},{id:22,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064e\u0631\u064e\u0648\u06e1\u0646\u064e \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u064e \u0644\u064e\u0627 \u0628\u064f\u0634\u06e1\u0631\u064e\u0649\u0670 \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u0644\u0651\u0650\u0644\u06e1\u0645\u064f\u062c\u06e1\u0631\u0650\u0645\u0650\u064a\u0646\u064e \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u062d\u0650\u062c\u06e1\u0631\u0657\u0627 \u0645\u0651\u064e\u062d\u06e1\u062c\u064f\u0648\u0631\u0657\u0627",translation:"(Ingatlah) pada hari (ketika) mereka melihat para malaikat, pada hari itu tidak ada kabar gembira bagi orang-orang yang berdosa dan mereka berkata, \"\u1e25ijran ma\u1e25j\u016br\u0101"},{id:23,text:"\u0648\u064e\u0642\u064e\u062f\u0650\u0645\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1 \u0639\u064e\u0645\u064e\u0644\u0656 \u0641\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f \u0647\u064e\u0628\u064e\u0627\u0653\u0621\u0657 \u0645\u0651\u064e\u0646\u062b\u064f\u0648\u0631\u064b\u0627",translation:"(Dan Kami akan perlihatkan segala amal575) yang mereka kerjakan, lalu Kami akan jadikan amal itu (bagaikan) debu yang beterbangan"},{id:24,text:"\u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u064d \u062e\u064e\u064a\u06e1\u0631\u065e \u0645\u0651\u064f\u0633\u06e1\u062a\u064e\u0642\u064e\u0631\u0651\u0657\u0627 \u0648\u064e\u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064f \u0645\u064e\u0642\u0650\u064a\u0644\u0657\u0627",translation:"Penghuni-penghuni surga pada hari itu paling baik tempat tinggalnya dan paling indah tempat istirahatnya"},{id:25,text:"\u0648\u064e\u064a\u064e\u0648\u06e1\u0645\u064e \u062a\u064e\u0634\u064e\u0642\u0651\u064e\u0642\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u064f \u0628\u0650\u0671\u0644\u06e1\u063a\u064e\u0645\u064e\u0670\u0645\u0650 \u0648\u064e\u0646\u064f\u0632\u0651\u0650\u0644\u064e \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u064f \u062a\u064e\u0646\u0632\u0650\u064a\u0644\u064b\u0627",translation:"Dan (ingatlah) pada hari (ketika) langit pecah mengeluarkan kabut putih dan para malaikat diturunkan (secara) bergelombang"},{id:26,text:"\u0671\u0644\u06e1\u0645\u064f\u0644\u06e1\u0643\u064f \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u064d \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f \u0644\u0650\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u0650\u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u064a\u064e\u0648\u06e1\u0645\u064b\u0627 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0639\u064e\u0633\u0650\u064a\u0631\u0657\u0627",translation:"(Kerajaan yang hak576) pada hari itu adalah milik Tuhan Yang Maha Pengasih. Dan itulah hari yang sulit bagi orang-orang kafir"},{id:27,text:"\u0648\u064e\u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064e\u0639\u064e\u0636\u0651\u064f \u0671\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u064a\u064e\u062f\u064e\u064a\u06e1\u0647\u0650 \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u064a\u064e\u0670\u0644\u064e\u064a\u06e1\u062a\u064e\u0646\u0650\u064a \u0671\u062a\u0651\u064e\u062e\u064e\u0630\u06e1\u062a\u064f \u0645\u064e\u0639\u064e \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0650 \u0633\u064e\u0628\u0650\u064a\u0644\u0657\u0627",translation:"Dan (ingatlah) pada hari (ketika) orang-orang zalim menggigit kedua tangannya, (menyesali perbuatannya) seraya berkata, \"Wahai! Sekiranya (dulu) aku mengambil jalan bersama Rasul"},{id:28,text:"\u064a\u064e\u0670\u0648\u064e\u064a\u06e1\u0644\u064e\u062a\u064e\u0649\u0670 \u0644\u064e\u064a\u06e1\u062a\u064e\u0646\u0650\u064a \u0644\u064e\u0645\u06e1 \u0623\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u06e1 \u0641\u064f\u0644\u064e\u0627\u0646\u064b\u0627 \u062e\u064e\u0644\u0650\u064a\u0644\u0657\u0627",translation:"Wahai celaka aku! Sekiranya (dulu) aku tidak menjadikan si fulan 577) itu teman akrab(ku)"},{id:29,text:"\u0644\u0651\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u0636\u064e\u0644\u0651\u064e\u0646\u0650\u064a \u0639\u064e\u0646\u0650 \u0671\u0644\u0630\u0651\u0650\u0643\u06e1\u0631\u0650 \u0628\u064e\u0639\u06e1\u062f\u064e \u0625\u0650\u0630\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u0646\u0650\u064a\u06d7 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u064f \u0644\u0650\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u0650 \u062e\u064e\u0630\u064f\u0648\u0644\u0657\u0627",translation:"sungguh, dia telah menyesatkan aku dari peringatan (Alquran) ketika (Alquran) itu telah datang kepadaku. Dan setan memang pengkhianat manusia"},{id:30,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064f \u064a\u064e\u0670\u0631\u064e\u0628\u0651\u0650 \u0625\u0650\u0646\u0651\u064e \u0642\u064e\u0648\u06e1\u0645\u0650\u064a \u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627\u0652 \u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u064e \u0645\u064e\u0647\u06e1\u062c\u064f\u0648\u0631\u0657\u0627",translation:"Dan Rasul (Muhammad) berkata, \"Ya Tuhanku, sesungguhnya kaumku telah menjadikan Alquran ini diabaikan"},{id:31,text:"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0646\u064e\u0628\u0650\u064a\u0651\u064d \u0639\u064e\u062f\u064f\u0648\u0651\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u062c\u06e1\u0631\u0650\u0645\u0650\u064a\u0646\u064e\u06d7 \u0648\u064e\u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0647\u064e\u0627\u062f\u0650\u064a\u0657\u0627 \u0648\u064e\u0646\u064e\u0635\u0650\u064a\u0631\u0657\u0627",translation:"Begitulah, bagi setiap nabi, telah Kami adakan musuh dari orang-orang yang berdosa. Tetapi cukuplah Tuhanmu menjadi pemberi petunjuk dan penolong"},{id:32,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0644\u064e\u0648\u06e1\u0644\u064e\u0627 \u0646\u064f\u0632\u0651\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u064f \u062c\u064f\u0645\u06e1\u0644\u064e\u0629\u0657 \u0648\u064e\u0670\u062d\u0650\u062f\u064e\u0629\u0657\u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u0650\u0646\u064f\u062b\u064e\u0628\u0651\u0650\u062a\u064e \u0628\u0650\u0647\u0650\u06e6 \u0641\u064f\u0624\u064e\u0627\u062f\u064e\u0643\u064e\u06d6 \u0648\u064e\u0631\u064e\u062a\u0651\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f \u062a\u064e\u0631\u06e1\u062a\u0650\u064a\u0644\u0657\u0627",translation:"(Dan orang-orang kafir berkata, \"Mengapa Alquran itu tidak diturunkan kepadanya sekaligus?\" Demikianlah,578) agar Kami memperteguh hatimu (Muhammad) dengannya dan Kami membacakannya secara tartil\xb3 (berangsur-angsur, perlahan dan benar)"},{id:33,text:"\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0623\u06e1\u062a\u064f\u0648\u0646\u064e\u0643\u064e \u0628\u0650\u0645\u064e\u062b\u064e\u0644\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u062c\u0650\u0626\u06e1\u0646\u064e\u0670\u0643\u064e \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064e \u062a\u064e\u0641\u06e1\u0633\u0650\u064a\u0631\u064b\u0627",translation:"Dan mereka (orang-orang kafir itu) tidak datang kepadamu (membawa) sesuatu yang aneh, melainkan Kami datangkan kepadamu yang benar dan penjelasan yang paling baik"},{id:34,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u062d\u06e1\u0634\u064e\u0631\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0648\u064f\u062c\u064f\u0648\u0647\u0650\u0647\u0650\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649\u0670 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0634\u064e\u0631\u0651\u065e \u0645\u0651\u064e\u0643\u064e\u0627\u0646\u0657\u0627 \u0648\u064e\u0623\u064e\u0636\u064e\u0644\u0651\u064f \u0633\u064e\u0628\u0650\u064a\u0644\u0657\u0627",translation:"Orang-orang yang dikumpulkan di neraka Jahanam dengan diseret wajahnya, mereka itulah yang paling buruk tempatnya dan paling sesat jalannya"},{id:35,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0645\u064e\u0639\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u062e\u064e\u0627\u0647\u064f \u0647\u064e\u0670\u0631\u064f\u0648\u0646\u064e \u0648\u064e\u0632\u0650\u064a\u0631\u0657\u0627",translation:"Dan sungguh, Kami telah memberikan Kitab (Taurat) kepada Musa dan Kami telah menjadikan Harun saudaranya, menyertai dia sebagai wazir (pembantu)"},{id:36,text:"\u0641\u064e\u0642\u064f\u0644\u06e1\u0646\u064e\u0627 \u0671\u0630\u06e1\u0647\u064e\u0628\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0641\u064e\u062f\u064e\u0645\u0651\u064e\u0631\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u062a\u064e\u062f\u06e1\u0645\u0650\u064a\u0631\u0657\u0627",translation:"Kemudian Kami berfirman (kepada keduanya), \"Pergilah kamu berdua kepada kaum yang mendustakan ayat-ayat Kami.\" Lalu Kami hancurkan mereka dengan sehancur-hancurnya"},{id:37,text:"\u0648\u064e\u0642\u064e\u0648\u06e1\u0645\u064e \u0646\u064f\u0648\u062d\u0656 \u0644\u0651\u064e\u0645\u0651\u064e\u0627 \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0671\u0644\u0631\u0651\u064f\u0633\u064f\u0644\u064e \u0623\u064e\u063a\u06e1\u0631\u064e\u0642\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0621\u064e\u0627\u064a\u064e\u0629\u0657\u06d6 \u0648\u064e\u0623\u064e\u0639\u06e1\u062a\u064e\u062f\u06e1\u0646\u064e\u0627 \u0644\u0650\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0623\u064e\u0644\u0650\u064a\u0645\u0657\u0627",translation:"Dan (telah Kami binasakan) kaum Nuh ketika mereka mendustakan para rasul. Kami tenggelamkam mereka dan Kami jadikan (cerita) mereka itu pelajaran bagi manusia. Dan Kami telah sediakan bagi orang-orang zalim azab yang pedih"},{id:38,text:"\u0648\u064e\u0639\u064e\u0627\u062f\u0657\u0627 \u0648\u064e\u062b\u064e\u0645\u064f\u0648\u062f\u064e\u0627\u0652 \u0648\u064e\u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064e \u0671\u0644\u0631\u0651\u064e\u0633\u0651\u0650 \u0648\u064e\u0642\u064f\u0631\u064f\u0648\u0646\u064e\u06e2\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u0657\u0627",translation:"dan (telah Kami binasakan) kaum '\u0100d dan Samud dan penduduk Rass579) serta banyak (lagi) generasi di antara (kaum-kaum) itu"},{id:39,text:"\u0648\u064e\u0643\u064f\u0644\u0651\u0657\u0627 \u0636\u064e\u0631\u064e\u0628\u06e1\u0646\u064e\u0627 \u0644\u064e\u0647\u064f \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u062b\u064e\u0670\u0644\u064e\u06d6 \u0648\u064e\u0643\u064f\u0644\u0651\u0657\u0627 \u062a\u064e\u0628\u0651\u064e\u0631\u06e1\u0646\u064e\u0627 \u062a\u064e\u062a\u06e1\u0628\u0650\u064a\u0631\u0657\u0627",translation:"Dan masing-masing telah Kami jadikan perumpamaan dan masing-masing telah Kami hancurkan sehancur-hancurnya"},{id:40,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u062a\u064e\u0648\u06e1\u0627\u0652 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0642\u064e\u0631\u06e1\u064a\u064e\u0629\u0650 \u0671\u0644\u0651\u064e\u062a\u0650\u064a\u0653 \u0623\u064f\u0645\u06e1\u0637\u0650\u0631\u064e\u062a\u06e1 \u0645\u064e\u0637\u064e\u0631\u064e \u0671\u0644\u0633\u0651\u064e\u0648\u06e1\u0621\u0650\u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0631\u064e\u0648\u06e1\u0646\u064e\u0647\u064e\u0627\u06da \u0628\u064e\u0644\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u064a\u064e\u0631\u06e1\u062c\u064f\u0648\u0646\u064e \u0646\u064f\u0634\u064f\u0648\u0631\u0657\u0627",translation:"Dan sungguh, mereka (kaum musyrik Mekkah) telah melalui negeri (Sodom) yang (dulu) dijatuhi hujan yang buruk (hujan batu). Tidakkah mereka menyaksikannya? Bahkan mereka itu sebenarnya tidak mengharapkan hari kebangkitan"},{id:41,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0631\u064e\u0623\u064e\u0648\u06e1\u0643\u064e \u0625\u0650\u0646 \u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0646\u064e\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0632\u064f\u0648\u064b\u0627 \u0623\u064e\u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0628\u064e\u0639\u064e\u062b\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0631\u064e\u0633\u064f\u0648\u0644\u064b\u0627",translation:"Dan apabila mereka melihat engkau (Muhammad), mereka hanyalah menjadikan engkau sebagai ejekan (dengan mengatakan), \"Inikah orangnya yang diutus Allah sebagai Rasul"},{id:42,text:"\u0625\u0650\u0646 \u0643\u064e\u0627\u062f\u064e \u0644\u064e\u064a\u064f\u0636\u0650\u0644\u0651\u064f\u0646\u064e\u0627 \u0639\u064e\u0646\u06e1 \u0621\u064e\u0627\u0644\u0650\u0647\u064e\u062a\u0650\u0646\u064e\u0627 \u0644\u064e\u0648\u06e1\u0644\u064e\u0627\u0653 \u0623\u064e\u0646 \u0635\u064e\u0628\u064e\u0631\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627\u06da \u0648\u064e\u0633\u064e\u0648\u06e1\u0641\u064e \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u062d\u0650\u064a\u0646\u064e \u064a\u064e\u0631\u064e\u0648\u06e1\u0646\u064e \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0645\u064e\u0646\u06e1 \u0623\u064e\u0636\u064e\u0644\u0651\u064f \u0633\u064e\u0628\u0650\u064a\u0644\u064b\u0627",translation:"Sungguh, hampir saja dia menyesatkan kita dari sesembahan kita, seandainya kita tidak tetap bertahan (menyembah)nya.\" Dan kelak mereka akan mengetahui pada saat mereka melihat azab, siapa yang paling sesat jalannya"},{id:43,text:"\u0623\u064e\u0631\u064e\u0621\u064e\u064a\u06e1\u062a\u064e \u0645\u064e\u0646\u0650 \u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064e \u0625\u0650\u0644\u064e\u0670\u0647\u064e\u0647\u064f\u06e5 \u0647\u064e\u0648\u064e\u0649\u0670\u0647\u064f \u0623\u064e\u0641\u064e\u0623\u064e\u0646\u062a\u064e \u062a\u064e\u0643\u064f\u0648\u0646\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0648\u064e\u0643\u0650\u064a\u0644\u064b\u0627",translation:"Sudahkah engkau (Muhammad) melihat orang yang menjadikan keinginannya sebagai tuhannya. Apakah engkau akan menjadi pelindungnya"},{id:44,text:"\u0623\u064e\u0645\u06e1 \u062a\u064e\u062d\u06e1\u0633\u064e\u0628\u064f \u0623\u064e\u0646\u0651\u064e \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0633\u06e1\u0645\u064e\u0639\u064f\u0648\u0646\u064e \u0623\u064e\u0648\u06e1 \u064a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e\u06da \u0625\u0650\u0646\u06e1 \u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064e\u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0639\u064e\u0670\u0645\u0650 \u0628\u064e\u0644\u06e1 \u0647\u064f\u0645\u06e1 \u0623\u064e\u0636\u064e\u0644\u0651\u064f \u0633\u064e\u0628\u0650\u064a\u0644\u064b\u0627",translation:"atau apakah engkau mengira bahwa kebanyakan mereka itu mendengar atau memahami? Mereka itu hanyalah seperti hewan ternak, bahkan lebih sesat jalannya"},{id:45,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0631\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0643\u064e\u064a\u06e1\u0641\u064e \u0645\u064e\u062f\u0651\u064e \u0671\u0644\u0638\u0651\u0650\u0644\u0651\u064e \u0648\u064e\u0644\u064e\u0648\u06e1 \u0634\u064e\u0627\u0653\u0621\u064e \u0644\u064e\u062c\u064e\u0639\u064e\u0644\u064e\u0647\u064f\u06e5 \u0633\u064e\u0627\u0643\u0650\u0646\u0657\u0627 \u062b\u064f\u0645\u0651\u064e \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0671\u0644\u0634\u0651\u064e\u0645\u06e1\u0633\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u062f\u064e\u0644\u0650\u064a\u0644\u0657\u0627",translation:"Tidakkah engkau memperhatikan (penciptaan) Tuhanmu, bagaimana Dia memanjangkan (dan memendekkan) bayang-bayang; dan sekiranya Dia menghendaki, niscaya Dia menjadikannya (bayang-bayang itu) tetap, kemudian Kami jadikan matahari sebagai petunjuk"},{id:46,text:"\u062b\u064f\u0645\u0651\u064e \u0642\u064e\u0628\u064e\u0636\u06e1\u0646\u064e\u0670\u0647\u064f \u0625\u0650\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0642\u064e\u0628\u06e1\u0636\u0657\u0627 \u064a\u064e\u0633\u0650\u064a\u0631\u0657\u0627",translation:"kemudian Kami menariknya (bayang-bayang itu) kepada Kami580) sedikit demi sedikit"},{id:47,text:"\u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u064e \u0644\u0650\u0628\u064e\u0627\u0633\u0657\u0627 \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0648\u06e1\u0645\u064e \u0633\u064f\u0628\u064e\u0627\u062a\u0657\u0627 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u0646\u064f\u0634\u064f\u0648\u0631\u0657\u0627",translation:"Dan Dialah yang menjadikan malam untukmu (sebagai) pakaian, dan tidur untuk istirahat, dan Dia menjadikan siang untuk bangkit berusaha"},{id:48,text:"\u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u064e \u0671\u0644\u0631\u0651\u0650\u064a\u064e\u0670\u062d\u064e \u0628\u064f\u0634\u06e1\u0631\u064e\u06e2\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u06e1 \u0631\u064e\u062d\u06e1\u0645\u064e\u062a\u0650\u0647\u0650\u06e6\u06da \u0648\u064e\u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0645\u064e\u0627\u0653\u0621\u0657 \u0637\u064e\u0647\u064f\u0648\u0631\u0657\u0627",translation:"Dan Dialah yang meniupkan angin (sebagai) pembawa kabar gembira sebelum kedatangan rahmat-Nya (hujan); dan Kami turunkan dari langit air yang sangat bersih"},{id:49,text:"\u0644\u0651\u0650\u0646\u064f\u062d\u06e1\u0640\u06e7\u0650\u064a\u064e \u0628\u0650\u0647\u0650\u06e6 \u0628\u064e\u0644\u06e1\u062f\u064e\u0629\u0657 \u0645\u0651\u064e\u064a\u06e1\u062a\u0657\u0627 \u0648\u064e\u0646\u064f\u0633\u06e1\u0642\u0650\u064a\u064e\u0647\u064f\u06e5 \u0645\u0650\u0645\u0651\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u06e1\u0646\u064e\u0627\u0653 \u0623\u064e\u0646\u06e1\u0639\u064e\u0670\u0645\u0657\u0627 \u0648\u064e\u0623\u064e\u0646\u064e\u0627\u0633\u0650\u064a\u0651\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u0657\u0627",translation:"agar (dengan air itu) Kami menghidupkan negeri yang mati (tandus), dan Kami memberi minum kepada sebagian apa yang telah Kami ciptakan, (berupa) hewan-hewan ternak dan manusia yang banyak"},{id:50,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0635\u064e\u0631\u0651\u064e\u0641\u06e1\u0646\u064e\u0670\u0647\u064f \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1 \u0644\u0650\u064a\u064e\u0630\u0651\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0627\u0652 \u0641\u064e\u0623\u064e\u0628\u064e\u0649\u0670\u0653 \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064f\u0641\u064f\u0648\u0631\u0657\u0627",translation:"Dan sungguh, Kami telah mempergilirkan (hujan) itu di antara mereka agar mereka mengambil pelajaran; tetapi kebanyakan manusia tidak mau (bersyukur), bahkan mereka mengingkari (nikmat)"},{id:51,text:"\u0648\u064e\u0644\u064e\u0648\u06e1 \u0634\u0650\u0626\u06e1\u0646\u064e\u0627 \u0644\u064e\u0628\u064e\u0639\u064e\u062b\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a \u0643\u064f\u0644\u0651\u0650 \u0642\u064e\u0631\u06e1\u064a\u064e\u0629\u0656 \u0646\u0651\u064e\u0630\u0650\u064a\u0631\u0657\u0627",translation:"Dan sekiranya Kami menghendaki, niscaya Kami utus seorang pemberi peringatan pada setiap negeri"},{id:52,text:"\u0641\u064e\u0644\u064e\u0627 \u062a\u064f\u0637\u0650\u0639\u0650 \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0648\u064e\u062c\u064e\u0670\u0647\u0650\u062f\u06e1\u0647\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6 \u062c\u0650\u0647\u064e\u0627\u062f\u0657\u0627 \u0643\u064e\u0628\u0650\u064a\u0631\u0657\u0627",translation:"Maka janganlah engkau taati orang-orang kafir, dan berjuanglah terhadap mereka dengannya (Alquran) dengan (semangat) perjuangan yang besar"},{id:53,text:"\u06de\u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0645\u064e\u0631\u064e\u062c\u064e \u0671\u0644\u06e1\u0628\u064e\u062d\u06e1\u0631\u064e\u064a\u06e1\u0646\u0650 \u0647\u064e\u0670\u0630\u064e\u0627 \u0639\u064e\u0630\u06e1\u0628\u065e \u0641\u064f\u0631\u064e\u0627\u062a\u065e \u0648\u064e\u0647\u064e\u0670\u0630\u064e\u0627 \u0645\u0650\u0644\u06e1\u062d\u064c \u0623\u064f\u062c\u064e\u0627\u062c\u065e \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0628\u064e\u0631\u06e1\u0632\u064e\u062e\u0657\u0627 \u0648\u064e\u062d\u0650\u062c\u06e1\u0631\u0657\u0627 \u0645\u0651\u064e\u062d\u06e1\u062c\u064f\u0648\u0631\u0657\u0627",translation:"Dan Dialah yang membiarkan dua laut mengalir (berdampingan); yang ini tawar dan segar dan yang lain sangat asin lagi pahit; dan Dia jadikan antara keduanya dinding dan batas yang tidak tembus"},{id:54,text:"\u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064e\u0627\u0653\u0621\u0650 \u0628\u064e\u0634\u064e\u0631\u0657\u0627 \u0641\u064e\u062c\u064e\u0639\u064e\u0644\u064e\u0647\u064f\u06e5 \u0646\u064e\u0633\u064e\u0628\u0657\u0627 \u0648\u064e\u0635\u0650\u0647\u06e1\u0631\u0657\u0627\u06d7 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0642\u064e\u062f\u0650\u064a\u0631\u0657\u0627",translation:"Dan Dia (pula) yang menciptakan manusia dari air, lalu Dia jadikan manusia itu (mempunyai) keturunan dan mu\u1e63\u0101harah581) dan Tuhanmu adalah Mahakuasa"},{id:55,text:"\u0648\u064e\u064a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0646\u0641\u064e\u0639\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0636\u064f\u0631\u0651\u064f\u0647\u064f\u0645\u06e1\u06d7 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u06e1\u0643\u064e\u0627\u0641\u0650\u0631\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u06e6 \u0638\u064e\u0647\u0650\u064a\u0631\u0657\u0627",translation:"Dan mereka menyembah selain Allah apa yang tidak memberi manfaat kepada mereka dan tidak (pula) mendatangkan bencana kepada mereka. Orang-orang kafir adalah penolong (setan untuk berbuat durhaka) terhadap Tuhannya"},{id:56,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0670\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064f\u0628\u064e\u0634\u0651\u0650\u0631\u0657\u0627 \u0648\u064e\u0646\u064e\u0630\u0650\u064a\u0631\u0657\u0627",translation:"Dan tidaklah Kami mengutus engkau (Muhammad) melainkan hanya sebagai pembawa kabar gembira dan pemberi peringatan"},{id:57,text:"\u0642\u064f\u0644\u06e1 \u0645\u064e\u0627\u0653 \u0623\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0643\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0645\u0650\u0646\u06e1 \u0623\u064e\u062c\u06e1\u0631\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646 \u0634\u064e\u0627\u0653\u0621\u064e \u0623\u064e\u0646 \u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u06e6 \u0633\u064e\u0628\u0650\u064a\u0644\u0657\u0627",translation:"Katakanlah, \"Aku tidak meminta imbalan apa pun dari kamu dalam menyampaikan (risalah) itu, melainkan (mengharapkan agar) orang-orang mau mengambil jalan kepada Tuhannya"},{id:58,text:"\u0648\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u06e1 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u062d\u064e\u064a\u0651\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0644\u064e\u0627 \u064a\u064e\u0645\u064f\u0648\u062a\u064f \u0648\u064e\u0633\u064e\u0628\u0651\u0650\u062d\u06e1 \u0628\u0650\u062d\u064e\u0645\u06e1\u062f\u0650\u0647\u0650\u06e6\u06da \u0648\u064e\u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0647\u0650\u06e6 \u0628\u0650\u0630\u064f\u0646\u064f\u0648\u0628\u0650 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650\u06e6 \u062e\u064e\u0628\u0650\u064a\u0631\u064b\u0627",translation:"Dan bertawakallah kepada Allah Yang Hidup, Yang tidak mati, dan bertasbihlah dengan memuji-Nya. Dan cukuplah Dia Maha Mengetahui dosa hamba-hamba-Nya"},{id:59,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0641\u0650\u064a \u0633\u0650\u062a\u0651\u064e\u0629\u0650 \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u0656 \u062b\u064f\u0645\u0651\u064e \u0671\u0633\u06e1\u062a\u064e\u0648\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0639\u064e\u0631\u06e1\u0634\u0650\u06d6 \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u064f \u0641\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u06e1 \u0628\u0650\u0647\u0650\u06e6 \u062e\u064e\u0628\u0650\u064a\u0631\u0657\u0627",translation:"yang menciptakan langit dan bumi dan apa yang ada di antara keduanya dalam enam masa, kemudian Dia bersemayam di atas Arasy, (Dialah) Yang Maha Pengasih, maka tanyakanlah (tentang Allah) kepada orang yang lebih mengetahui (Muhammad)"},{id:60,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0633\u06e1\u062c\u064f\u062f\u064f\u0648\u0627\u0652\u06e4 \u0644\u0650\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u0650 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0648\u064e\u0645\u064e\u0627 \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u064f \u0623\u064e\u0646\u064e\u0633\u06e1\u062c\u064f\u062f\u064f \u0644\u0650\u0645\u064e\u0627 \u062a\u064e\u0623\u06e1\u0645\u064f\u0631\u064f\u0646\u064e\u0627 \u0648\u064e\u0632\u064e\u0627\u062f\u064e\u0647\u064f\u0645\u06e1 \u0646\u064f\u0641\u064f\u0648\u0631\u0657\u0627\u06e9",translation:"Dan apabila dikatakan kepada mereka, \"Sujudlah kepada Yang Maha Pengasih\", mereka menjawab, \"Siapakah Yang Maha Pengasih itu? Apakah kami harus sujud kepada Allah yang engkau (Muhammad) perintahkan kepada kami (bersujud kepada-Nya)?\" Dan mereka makin jauh lari (dari kebenaran)"},{id:61,text:"\u062a\u064e\u0628\u064e\u0627\u0631\u064e\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0639\u064e\u0644\u064e \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0628\u064f\u0631\u064f\u0648\u062c\u0657\u0627 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0633\u0650\u0631\u064e\u0670\u062c\u0657\u0627 \u0648\u064e\u0642\u064e\u0645\u064e\u0631\u0657\u0627 \u0645\u0651\u064f\u0646\u0650\u064a\u0631\u0657\u0627",translation:"Mahasuci Allah yang menjadikan di langit gugusan bintang-bintang dan Dia juga menjadikan padanya matahari dan bulan yang bersinar"},{id:62,text:"\u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0639\u064e\u0644\u064e \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u064e \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u062e\u0650\u0644\u06e1\u0641\u064e\u0629\u0657 \u0644\u0651\u0650\u0645\u064e\u0646\u06e1 \u0623\u064e\u0631\u064e\u0627\u062f\u064e \u0623\u064e\u0646 \u064a\u064e\u0630\u0651\u064e\u0643\u0651\u064e\u0631\u064e \u0623\u064e\u0648\u06e1 \u0623\u064e\u0631\u064e\u0627\u062f\u064e \u0634\u064f\u0643\u064f\u0648\u0631\u0657\u0627",translation:"Dan Dia (pula) yang menjadikan malam dan siang silih berganti bagi orang yang ingin mengambil pelajaran atau yang ingin bersyukur"},{id:63,text:"\u0648\u064e\u0639\u0650\u0628\u064e\u0627\u062f\u064f \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0645\u06e1\u0634\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0647\u064e\u0648\u06e1\u0646\u0657\u0627 \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062e\u064e\u0627\u0637\u064e\u0628\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u062c\u064e\u0670\u0647\u0650\u0644\u064f\u0648\u0646\u064e \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0633\u064e\u0644\u064e\u0670\u0645\u0657\u0627",translation:"Adapun hamba-hamba Tuhan Yang Maha Pengasih itu adalah orang-orang yang berjalan di bumi dengan rendah hati dan apabila orang-orang bodoh menyapa mereka (dengan kata-kata yang menghina), mereka mengucapkan, \"sal\u0101m"},{id:64,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0628\u0650\u064a\u062a\u064f\u0648\u0646\u064e \u0644\u0650\u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0633\u064f\u062c\u0651\u064e\u062f\u0657\u0627 \u0648\u064e\u0642\u0650\u064a\u064e\u0670\u0645\u0657\u0627",translation:"dan orang-orang yang menghabiskan waktu malam untuk beribadah kepada Tuhan mereka dengan bersujud dan berdiri"},{id:65,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0671\u0635\u06e1\u0631\u0650\u0641\u06e1 \u0639\u064e\u0646\u0651\u064e\u0627 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e\u06d6 \u0625\u0650\u0646\u0651\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u064e\u0647\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u063a\u064e\u0631\u064e\u0627\u0645\u064b\u0627",translation:"Dan orang-orang yang berkata, \"Ya Tuhan kami, jauhkanlah azab Jahanam dari kami, karena sesungguhnya azabnya itu membuat kebinasaan yang kekal"},{id:66,text:"\u0625\u0650\u0646\u0651\u064e\u0647\u064e\u0627 \u0633\u064e\u0627\u0653\u0621\u064e\u062a\u06e1 \u0645\u064f\u0633\u06e1\u062a\u064e\u0642\u064e\u0631\u0651\u0657\u0627 \u0648\u064e\u0645\u064f\u0642\u064e\u0627\u0645\u0657\u0627",translation:"Sungguh, Jahanam itu seburuk-buruk tempat menetap dan tempat kediaman"},{id:67,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0625\u0650\u0630\u064e\u0627\u0653 \u0623\u064e\u0646\u0641\u064e\u0642\u064f\u0648\u0627\u0652 \u0644\u064e\u0645\u06e1 \u064a\u064f\u0633\u06e1\u0631\u0650\u0641\u064f\u0648\u0627\u0652 \u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0642\u06e1\u062a\u064f\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0628\u064e\u064a\u06e1\u0646\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0642\u064e\u0648\u064e\u0627\u0645\u0657\u0627",translation:"Dan (termasuk hamba-hamba Tuhan Yang Maha Pengasih) orang-orang yang apabila menginfakkan (harta), mereka tidak berlebihan, dan tidak (pula) kikir, di antara keduanya secara wajar"},{id:68,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e \u0645\u064e\u0639\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u064e\u0670\u0647\u064b\u0627 \u0621\u064e\u0627\u062e\u064e\u0631\u064e \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0642\u06e1\u062a\u064f\u0644\u064f\u0648\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0641\u06e1\u0633\u064e \u0671\u0644\u0651\u064e\u062a\u0650\u064a \u062d\u064e\u0631\u0651\u064e\u0645\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0632\u06e1\u0646\u064f\u0648\u0646\u064e\u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0641\u06e1\u0639\u064e\u0644\u06e1 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064e\u0644\u06e1\u0642\u064e \u0623\u064e\u062b\u064e\u0627\u0645\u0657\u0627",translation:"dan orang-orang yang tidak mempersekutukan Allah dengan sembahan lain dan tidak membunuh orang yang diharamkan Allah kecuali dengan (alasan) yang benar, dan tidak berzina; dan barang siapa melakukan demikian itu, niscaya dia mendapat hukuman yang berat"},{id:69,text:"\u064a\u064f\u0636\u064e\u0670\u0639\u064e\u0641\u06e1 \u0644\u064e\u0647\u064f \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u0648\u064e\u064a\u064e\u062e\u06e1\u0644\u064f\u062f\u06e1 \u0641\u0650\u064a\u0647\u0650\u06e6 \u0645\u064f\u0647\u064e\u0627\u0646\u064b\u0627",translation:"(yakni) akan dilipatgandakan azab untuknya pada hari Kiamat dan dia akan kekal dalam azab itu, dalam keadaan terhina"},{id:70,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646 \u062a\u064e\u0627\u0628\u064e \u0648\u064e\u0621\u064e\u0627\u0645\u064e\u0646\u064e \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064e \u0639\u064e\u0645\u064e\u0644\u0657\u0627 \u0635\u064e\u0670\u0644\u0650\u062d\u0657\u0627 \u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u064a\u064f\u0628\u064e\u062f\u0651\u0650\u0644\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0633\u064e\u064a\u0651\u0650\u0640\u0654\u064e\u0627\u062a\u0650\u0647\u0650\u0645\u06e1 \u062d\u064e\u0633\u064e\u0646\u064e\u0670\u062a\u0656\u06d7 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u0657\u0627 \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0657\u0627",translation:"kecuali orang-orang yang bertobat dan beriman dan mengerjakan kebajikan; maka kejahatan mereka diganti Allah dengan kebaikan. Allah Maha Pengampun, Maha Penyayang"},{id:71,text:"\u0648\u064e\u0645\u064e\u0646 \u062a\u064e\u0627\u0628\u064e \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064e \u0635\u064e\u0670\u0644\u0650\u062d\u0657\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u064a\u064e\u062a\u064f\u0648\u0628\u064f \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u062a\u064e\u0627\u0628\u0657\u0627",translation:"Dan barang siapa bertobat dan mengerjakan kebajikan, maka sesungguhnya dia bertobat kepada Allah dengan tobat yang sebenar-benarnya"},{id:72,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u0634\u06e1\u0647\u064e\u062f\u064f\u0648\u0646\u064e \u0671\u0644\u0632\u0651\u064f\u0648\u0631\u064e \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0631\u0651\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u063a\u06e1\u0648\u0650 \u0645\u064e\u0631\u0651\u064f\u0648\u0627\u0652 \u0643\u0650\u0631\u064e\u0627\u0645\u0657\u0627",translation:"Dan orang-orang yang tidak memberikan kesaksian palsu, dan apabila mereka bertemu dengan (orang-orang) yang mengerjakan perbuatan-perbuatan yang tidak berguna, mereka berlalu dengan menjaga kehormatan dirinya"},{id:73,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0625\u0650\u0630\u064e\u0627 \u0630\u064f\u0643\u0651\u0650\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0644\u064e\u0645\u06e1 \u064a\u064e\u062e\u0650\u0631\u0651\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627 \u0635\u064f\u0645\u0651\u0657\u0627 \u0648\u064e\u0639\u064f\u0645\u06e1\u064a\u064e\u0627\u0646\u0657\u0627",translation:"dan orang-orang yang apabila diberi peringatan dengan ayat-ayat Tuhan mereka, mereka tidak bersikap sebagai orang-orang yang tuli dan buta"},{id:74,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0647\u064e\u0628\u06e1 \u0644\u064e\u0646\u064e\u0627 \u0645\u0650\u0646\u06e1 \u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u0650\u0646\u064e\u0627 \u0648\u064e\u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u0640\u0670\u062a\u0650\u0646\u064e\u0627 \u0642\u064f\u0631\u0651\u064e\u0629\u064e \u0623\u064e\u0639\u06e1\u064a\u064f\u0646\u0656 \u0648\u064e\u0671\u062c\u06e1\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0644\u0650\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e \u0625\u0650\u0645\u064e\u0627\u0645\u064b\u0627",translation:"Dan orang-orang yang berkata, \"Ya Tuhan kami, anugerahkanlah kepada kami pasangan kami dan keturunan kami sebagai penyenang hati (kami), dan jadikanlah kami pemimpin bagi orang-orang yang bertakwa"},{id:75,text:"\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u064a\u064f\u062c\u06e1\u0632\u064e\u0648\u06e1\u0646\u064e \u0671\u0644\u06e1\u063a\u064f\u0631\u06e1\u0641\u064e\u0629\u064e \u0628\u0650\u0645\u064e\u0627 \u0635\u064e\u0628\u064e\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u064a\u064f\u0644\u064e\u0642\u0651\u064e\u0648\u06e1\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u062a\u064e\u062d\u0650\u064a\u0651\u064e\u0629\u0657 \u0648\u064e\u0633\u064e\u0644\u064e\u0670\u0645\u064b\u0627",translation:"Mereka itu akan diberi balasan dengan tempat yang tinggi (dalam surga) atas kesabaran mereka, dan di sana mereka akan disambut dengan penghormatan dan salam"},{id:76,text:"\u062e\u064e\u0670\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627\u06da \u062d\u064e\u0633\u064f\u0646\u064e\u062a\u06e1 \u0645\u064f\u0633\u06e1\u062a\u064e\u0642\u064e\u0631\u0651\u0657\u0627 \u0648\u064e\u0645\u064f\u0642\u064e\u0627\u0645\u0657\u0627",translation:"mereka kekal di dalamnya. Surga itu sebaik-baik tempat menetap dan tempat kediaman"},{id:77,text:"\u0642\u064f\u0644\u06e1 \u0645\u064e\u0627 \u064a\u064e\u0639\u06e1\u0628\u064e\u0624\u064f\u0627\u0652 \u0628\u0650\u0643\u064f\u0645\u06e1 \u0631\u064e\u0628\u0651\u0650\u064a \u0644\u064e\u0648\u06e1\u0644\u064e\u0627 \u062f\u064f\u0639\u064e\u0627\u0653\u0624\u064f\u0643\u064f\u0645\u06e1\u06d6 \u0641\u064e\u0642\u064e\u062f\u06e1 \u0643\u064e\u0630\u0651\u064e\u0628\u06e1\u062a\u064f\u0645\u06e1 \u0641\u064e\u0633\u064e\u0648\u06e1\u0641\u064e \u064a\u064e\u0643\u064f\u0648\u0646\u064f \u0644\u0650\u0632\u064e\u0627\u0645\u064e\u06e2\u0627",translation:"Katakanlah (Muhammad, kepada orang-orang musyrik), \"Tuhanku tidak akan mengindahkan kamu, kalau tidak karena ibadahmu. (Tetapi bagaimana kamu beribadah kepada-Nya), padahal sungguh, kamu telah mendustakan-Nya? Karena itu kelak (azab) pasti (menimpamu)"}]},{id:26,name:"\u0627\u0644\u0634\u0639\u0631\u0627\u0621",transliteration:"Ash-Shu'ara",translation:"Penyair",type:"meccan",total_verses:227,verses:[{id:1,text:"\u0637\u0633\u0653\u0645\u0653",translation:"\u1e6c\u0101 S\u012bn M\u012bm"},{id:2,text:"\u062a\u0650\u0644\u06e1\u0643\u064e \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u064f \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0671\u0644\u06e1\u0645\u064f\u0628\u0650\u064a\u0646\u0650",translation:"Inilah ayat-ayat Kitab (Alquran) yang jelas"},{id:3,text:"\u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064e \u0628\u064e\u0670\u062e\u0650\u0639\u065e \u0646\u0651\u064e\u0641\u06e1\u0633\u064e\u0643\u064e \u0623\u064e\u0644\u0651\u064e\u0627 \u064a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Boleh jadi engkau (Muhammad) akan membinasakan dirimu (dengan kesedihan), karena mereka (penduduk Mekkah) tidak beriman"},{id:4,text:"\u0625\u0650\u0646 \u0646\u0651\u064e\u0634\u064e\u0623\u06e1 \u0646\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0621\u064e\u0627\u064a\u064e\u0629\u0657 \u0641\u064e\u0638\u064e\u0644\u0651\u064e\u062a\u06e1 \u0623\u064e\u0639\u06e1\u0646\u064e\u0670\u0642\u064f\u0647\u064f\u0645\u06e1 \u0644\u064e\u0647\u064e\u0627 \u062e\u064e\u0670\u0636\u0650\u0639\u0650\u064a\u0646\u064e",translation:"Jika Kami menghendaki, niscaya Kami turunkan kepada mereka mukjizat dari langit, yang akan membuat tengkuk mereka tunduk dengan rendah hati kepadanya"},{id:5,text:"\u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u0647\u0650\u0645 \u0645\u0651\u0650\u0646 \u0630\u0650\u0643\u06e1\u0631\u0656 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u0650 \u0645\u064f\u062d\u06e1\u062f\u064e\u062b\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0639\u064e\u0646\u06e1\u0647\u064f \u0645\u064f\u0639\u06e1\u0631\u0650\u0636\u0650\u064a\u0646\u064e",translation:"Dan setiap kali disampaikan kepada mereka suatu peringatan baru (ayat Alquran yang diturunkan) dari Tuhan Yang Maha Pengasih, mereka selalu berpaling darinya"},{id:6,text:"\u0641\u064e\u0642\u064e\u062f\u06e1 \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0641\u064e\u0633\u064e\u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u0647\u0650\u0645\u06e1 \u0623\u064e\u0646\u06e2\u0628\u064e\u0640\u0670\u0653\u0624\u064f\u0627\u0652 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6 \u064a\u064e\u0633\u06e1\u062a\u064e\u0647\u06e1\u0632\u0650\u0621\u064f\u0648\u0646\u064e",translation:"Sungguh, mereka telah mendustakan (Alquran), maka kelak akan datang kepada mereka (kebenaran) berita-berita mengenai apa (azab) yang dulu mereka perolok-olokkan"},{id:7,text:"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0631\u064e\u0648\u06e1\u0627\u0652 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0643\u064e\u0645\u06e1 \u0623\u064e\u0646\u06e2\u0628\u064e\u062a\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u0632\u064e\u0648\u06e1\u062c\u0656 \u0643\u064e\u0631\u0650\u064a\u0645\u064d",translation:"Dan apakah mereka tidak memperhatikan bumi, betapa banyak Kami tumbuhkan di bumi itu berbagai macam (tumbuh-tumbuhan) yang baik"},{id:8,text:"\u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0623\u0653\u064a\u064e\u0629\u0657\u06d6 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064f\u0647\u064f\u0645 \u0645\u0651\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Sungguh, pada yang demikian itu terdapat tanda (kebesaran Allah), tetapi kebanyakan mereka tidak beriman"},{id:9,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0644\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0671\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",translation:"Dan sungguh, Tuhanmu Dialah Yang Mahaperkasa, Maha Penyayang"},{id:10,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0646\u064e\u0627\u062f\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670\u0653 \u0623\u064e\u0646\u0650 \u0671\u0626\u06e1\u062a\u0650 \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dan (ingatlah) ketika Tuhanmu menyeru Musa (dengan firman-Nya), \"Datangilah kaum yang zalim itu"},{id:11,text:"\u0642\u064e\u0648\u06e1\u0645\u064e \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e\u06da \u0623\u064e\u0644\u064e\u0627 \u064a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",translation:"(yaitu) kaum Fir'aun. Mengapa mereka tidak bertakwa"},{id:12,text:"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0623\u064e\u0646 \u064a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f\u0648\u0646\u0650",translation:"Dia (Musa) berkata, \"Ya Tuhanku, sungguh, aku takut mereka akan mendustakan aku"},{id:13,text:"\u0648\u064e\u064a\u064e\u0636\u0650\u064a\u0642\u064f \u0635\u064e\u062f\u06e1\u0631\u0650\u064a \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0646\u0637\u064e\u0644\u0650\u0642\u064f \u0644\u0650\u0633\u064e\u0627\u0646\u0650\u064a \u0641\u064e\u0623\u064e\u0631\u06e1\u0633\u0650\u0644\u06e1 \u0625\u0650\u0644\u064e\u0649\u0670 \u0647\u064e\u0670\u0631\u064f\u0648\u0646\u064e",translation:"(sehingga dadaku terasa sempit dan lidahku tidak lancar maka utuslah Harun582) (bersamaku)"},{id:14,text:"\u0648\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u064a\u0651\u064e \u0630\u064e\u0646\u06e2\u0628\u065e \u0641\u064e\u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0623\u064e\u0646 \u064a\u064e\u0642\u06e1\u062a\u064f\u0644\u064f\u0648\u0646\u0650",translation:"(Sebab aku berdosa terhadap mereka,583) maka aku takut mereka akan membunuhku"},{id:15,text:"\u0642\u064e\u0627\u0644\u064e \u0643\u064e\u0644\u0651\u064e\u0627\u06d6 \u0641\u064e\u0671\u0630\u06e1\u0647\u064e\u0628\u064e\u0627 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627\u0653\u06d6 \u0625\u0650\u0646\u0651\u064e\u0627 \u0645\u064e\u0639\u064e\u0643\u064f\u0645 \u0645\u0651\u064f\u0633\u06e1\u062a\u064e\u0645\u0650\u0639\u064f\u0648\u0646\u064e",translation:"(Allah) berfirman, \"Jangan takut (mereka tidak akan dapat membunuhmu)! Maka pergilah kamu berdua dengan membawa ayat-ayat Kami (mukjizat-mukjizat); sungguh, Kami bersamamu mendengarkan (apa yang mereka katakan)"},{id:16,text:"\u0641\u064e\u0623\u06e1\u062a\u0650\u064a\u064e\u0627 \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0641\u064e\u0642\u064f\u0648\u0644\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u064f \u0631\u064e\u0628\u0651\u0650 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"maka datanglah kamu berdua kepada Fir'aun dan katakan, \"Sesungguhnya kami adalah rasul-rasul Tuhan seluruh alam"},{id:17,text:"\u0623\u064e\u0646\u06e1 \u0623\u064e\u0631\u06e1\u0633\u0650\u0644\u06e1 \u0645\u064e\u0639\u064e\u0646\u064e\u0627 \u0628\u064e\u0646\u0650\u064a\u0653 \u0625\u0650\u0633\u06e1\u0631\u064e\u0640\u0670\u0653\u0621\u0650\u064a\u0644\u064e",translation:"lepaskanlah Bani Israil (pergi) bersama kami"},{id:18,text:"\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0644\u064e\u0645\u06e1 \u0646\u064f\u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0641\u0650\u064a\u0646\u064e\u0627 \u0648\u064e\u0644\u0650\u064a\u062f\u0657\u0627 \u0648\u064e\u0644\u064e\u0628\u0650\u062b\u06e1\u062a\u064e \u0641\u0650\u064a\u0646\u064e\u0627 \u0645\u0650\u0646\u06e1 \u0639\u064f\u0645\u064f\u0631\u0650\u0643\u064e \u0633\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dia (Fir'aun) menjawab, \"Bukankah kami telah mengasuhmu dalam lingkungan (keluarga) kami, waktu engkau masih kanak-kanak dan engkau tinggal bersama kami beberapa tahun dari umurmu"},{id:19,text:"\u0648\u064e\u0641\u064e\u0639\u064e\u0644\u06e1\u062a\u064e \u0641\u064e\u0639\u06e1\u0644\u064e\u062a\u064e\u0643\u064e \u0671\u0644\u0651\u064e\u062a\u0650\u064a \u0641\u064e\u0639\u064e\u0644\u06e1\u062a\u064e \u0648\u064e\u0623\u064e\u0646\u062a\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan engkau (Musa) telah melakukan (kesalahan dari) perbuatan yang telah engkau lakukan585) dan engkau termasuk orang yang tidak tahu berterima kasih"},{id:20,text:"\u0642\u064e\u0627\u0644\u064e \u0641\u064e\u0639\u064e\u0644\u06e1\u062a\u064f\u0647\u064e\u0627\u0653 \u0625\u0650\u0630\u0657\u0627 \u0648\u064e\u0623\u064e\u0646\u064e\u0627\u06e0 \u0645\u0650\u0646\u064e \u0671\u0644\u0636\u0651\u064e\u0627\u0653\u0644\u0651\u0650\u064a\u0646\u064e",translation:"Dia (Musa) berkata, \"Aku telah melakukannya, dan ketika itu aku termasuk orang yang khilaf"},{id:21,text:"\u0641\u064e\u0641\u064e\u0631\u064e\u0631\u06e1\u062a\u064f \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u0644\u064e\u0645\u0651\u064e\u0627 \u062e\u0650\u0641\u06e1\u062a\u064f\u0643\u064f\u0645\u06e1 \u0641\u064e\u0648\u064e\u0647\u064e\u0628\u064e \u0644\u0650\u064a \u0631\u064e\u0628\u0651\u0650\u064a \u062d\u064f\u0643\u06e1\u0645\u0657\u0627 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e\u0646\u0650\u064a \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0631\u06e1\u0633\u064e\u0644\u0650\u064a\u0646\u064e",translation:"Lalu aku lari darimu karena aku takut kepadamu, kemudian Tuhanku menganugerahkan ilmu kepadaku serta Dia menjadikan aku salah seorang di antara rasul-rasul"},{id:22,text:"\u0648\u064e\u062a\u0650\u0644\u06e1\u0643\u064e \u0646\u0650\u0639\u06e1\u0645\u064e\u0629\u065e \u062a\u064e\u0645\u064f\u0646\u0651\u064f\u0647\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0651\u064e \u0623\u064e\u0646\u06e1 \u0639\u064e\u0628\u0651\u064e\u062f\u062a\u0651\u064e \u0628\u064e\u0646\u0650\u064a\u0653 \u0625\u0650\u0633\u06e1\u0631\u064e\u0640\u0670\u0653\u0621\u0650\u064a\u0644\u064e",translation:"Dan itulah kebaikan yang telah engkau berikan kepadaku, (sementara) itu engkau telah memperbudak Bani Israil"},{id:23,text:"\u0642\u064e\u0627\u0644\u064e \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064f \u0648\u064e\u0645\u064e\u0627 \u0631\u064e\u0628\u0651\u064f \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Fir'aun bertanya, \"Siapa Tuhan seluruh alam itu"},{id:24,text:"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u064e\u0627\u0653\u06d6 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645 \u0645\u0651\u064f\u0648\u0642\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dia (Musa) menjawab, \"Tuhan Pencipta langit dan bumi dan apa yang ada di antara keduanya (itulah Tuhanmu), jika kamu mempercayai-Nya"},{id:25,text:"\u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0645\u064e\u0646\u06e1 \u062d\u064e\u0648\u06e1\u0644\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u0644\u064e\u0627 \u062a\u064e\u0633\u06e1\u062a\u064e\u0645\u0650\u0639\u064f\u0648\u0646\u064e",translation:"Dia (Fir'aun) berkata kepada orang-orang di sekelilingnya, \"Apakah kamu tidak mendengar (apa yang dikatakannya)"},{id:26,text:"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u06e1 \u0648\u064e\u0631\u064e\u0628\u0651\u064f \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0626\u0650\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",translation:"Dia (Musa) berkata, \"(Dia) Tuhanmu dan dan juga Tuhan nenek moyangmu terdahulu"},{id:27,text:"\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064f\u0631\u06e1\u0633\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0644\u064e\u0645\u064e\u062c\u06e1\u0646\u064f\u0648\u0646\u065e",translation:"Dia (Fir'aun) berkata, \"Sungguh, Rasulmu yang diutus kepada kamu benar-benar orang gila"},{id:28,text:"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u064f \u0671\u0644\u06e1\u0645\u064e\u0634\u06e1\u0631\u0650\u0642\u0650 \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u063a\u06e1\u0631\u0650\u0628\u0650 \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u064e\u0627\u0653\u06d6 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Dia (Musa) berkata, \"(Dialah) Tuhan (yang menguasai) timur dan barat dan apa yang ada di antara keduanya; jika kamu mengerti"},{id:29,text:"\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0626\u0650\u0646\u0650 \u0671\u062a\u0651\u064e\u062e\u064e\u0630\u06e1\u062a\u064e \u0625\u0650\u0644\u064e\u0670\u0647\u064b\u0627 \u063a\u064e\u064a\u06e1\u0631\u0650\u064a \u0644\u064e\u0623\u064e\u062c\u06e1\u0639\u064e\u0644\u064e\u0646\u0651\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064e\u0633\u06e1\u062c\u064f\u0648\u0646\u0650\u064a\u0646\u064e",translation:"Dia (Fir'aun) berkata, \"Sungguh, jika engkau menyembah Tuhan selain aku, pasti aku masukkan engkau ke dalam penjara"},{id:30,text:"\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0648\u064e\u0644\u064e\u0648\u06e1 \u062c\u0650\u0626\u06e1\u062a\u064f\u0643\u064e \u0628\u0650\u0634\u064e\u064a\u06e1\u0621\u0656 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u0656",translation:"Dia (Musa) berkata, \"Apakah (engkau akan melakukan itu) sekalipun aku tunjukkan kepadamu suatu (bukti) yang nyata"},{id:31,text:"\u0642\u064e\u0627\u0644\u064e \u0641\u064e\u0623\u06e1\u062a\u0650 \u0628\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Dia (Fir'aun) berkata, \"Tunjukkan sesuatu (bukti yang nyata) itu, jika engkau termasuk orang yang benar"},{id:32,text:"\u0641\u064e\u0623\u064e\u0644\u06e1\u0642\u064e\u0649\u0670 \u0639\u064e\u0635\u064e\u0627\u0647\u064f \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0647\u0650\u064a\u064e \u062b\u064f\u0639\u06e1\u0628\u064e\u0627\u0646\u065e \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u065e",translation:"Maka dia (Musa) melemparkan tongkatnya, tiba-tiba tongkat itu menjadi ular besar yang nyata"},{id:33,text:"\u0648\u064e\u0646\u064e\u0632\u064e\u0639\u064e \u064a\u064e\u062f\u064e\u0647\u064f\u06e5 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0647\u0650\u064a\u064e \u0628\u064e\u064a\u06e1\u0636\u064e\u0627\u0653\u0621\u064f \u0644\u0650\u0644\u0646\u0651\u064e\u0640\u0670\u0638\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan dia mengeluarkan tangannya (dari dalam bajunya), tiba-tiba tangan itu menjadi putih (bercahaya) bagi orang-orang yang melihatnya"},{id:34,text:"\u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0644\u06e1\u0645\u064e\u0644\u064e\u0625\u0650 \u062d\u064e\u0648\u06e1\u0644\u064e\u0647\u064f\u06e5\u0653 \u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0644\u064e\u0633\u064e\u0670\u062d\u0650\u0631\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Dia (Fir'aun) berkata kepada para pemuka di sekelilingnya, \"Sesungguhnya dia (Musa) ini pasti seorang penyihir yang pandai"},{id:35,text:"\u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0623\u064e\u0646 \u064a\u064f\u062e\u06e1\u0631\u0650\u062c\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u0631\u06e1\u0636\u0650\u0643\u064f\u0645 \u0628\u0650\u0633\u0650\u062d\u06e1\u0631\u0650\u0647\u0650\u06e6 \u0641\u064e\u0645\u064e\u0627\u0630\u064e\u0627 \u062a\u064e\u0623\u06e1\u0645\u064f\u0631\u064f\u0648\u0646\u064e",translation:"dia hendak mengusir kamu dari negerimu dengan sihirnya; karena itu apakah yang kamu sarankan"},{id:36,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0631\u06e1\u062c\u0650\u0647\u06e1 \u0648\u064e\u0623\u064e\u062e\u064e\u0627\u0647\u064f \u0648\u064e\u0671\u0628\u06e1\u0639\u064e\u062b\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0645\u064e\u062f\u064e\u0627\u0653\u0626\u0650\u0646\u0650 \u062d\u064e\u0670\u0634\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Mereka menjawab, \"Tahanlah (untuk sementara) dia dan saudaranya, dan utuslah ke seluruh negeri orang-orang yang akan mengumpulkan (pesihir)"},{id:37,text:"\u064a\u064e\u0623\u06e1\u062a\u064f\u0648\u0643\u064e \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0633\u064e\u062d\u0651\u064e\u0627\u0631\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u0656",translation:"niscaya mereka akan mendatangkan semua pesihir yang pandai kepadamu"},{id:38,text:"\u0641\u064e\u062c\u064f\u0645\u0650\u0639\u064e \u0671\u0644\u0633\u0651\u064e\u062d\u064e\u0631\u064e\u0629\u064f \u0644\u0650\u0645\u0650\u064a\u0642\u064e\u0670\u062a\u0650 \u064a\u064e\u0648\u06e1\u0645\u0656 \u0645\u0651\u064e\u0639\u06e1\u0644\u064f\u0648\u0645\u0656",translation:"Lalu dikumpulkanlah para pesihir pada waktu (yang ditetapkan) di hari yang telah ditentukan"},{id:39,text:"\u0648\u064e\u0642\u0650\u064a\u0644\u064e \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0647\u064e\u0644\u06e1 \u0623\u064e\u0646\u062a\u064f\u0645 \u0645\u0651\u064f\u062c\u06e1\u062a\u064e\u0645\u0650\u0639\u064f\u0648\u0646\u064e",translation:"dan diumumkan kepada orang banyak, \"Berkumpullah kamu semua"},{id:40,text:"\u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0646\u064e\u0627 \u0646\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f \u0671\u0644\u0633\u0651\u064e\u062d\u064e\u0631\u064e\u0629\u064e \u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u063a\u064e\u0670\u0644\u0650\u0628\u0650\u064a\u0646\u064e",translation:"agar kita mengikuti para pesihir itu, jika mereka yang menang"},{id:41,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0633\u0651\u064e\u062d\u064e\u0631\u064e\u0629\u064f \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u0650\u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0623\u064e\u0626\u0650\u0646\u0651\u064e \u0644\u064e\u0646\u064e\u0627 \u0644\u064e\u0623\u064e\u062c\u06e1\u0631\u064b\u0627 \u0625\u0650\u0646 \u0643\u064f\u0646\u0651\u064e\u0627 \u0646\u064e\u062d\u06e1\u0646\u064f \u0671\u0644\u06e1\u063a\u064e\u0670\u0644\u0650\u0628\u0650\u064a\u0646\u064e",translation:"Maka ketika para pesihir datang, mereka berkata kepada Fir'aun, \"Apakah kami benar-benar akan mendapat imbalan yang besar jika kami yang menang"},{id:42,text:"\u0642\u064e\u0627\u0644\u064e \u0646\u064e\u0639\u064e\u0645\u06e1 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0630\u0657\u0627 \u0644\u0651\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0642\u064e\u0631\u0651\u064e\u0628\u0650\u064a\u0646\u064e",translation:"Dia (Fir'aun) menjawab, \"Ya, dan bahkan kamu pasti akan mendapat kedudukan yang dekat (dariku)"},{id:43,text:"\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u064f\u0648\u0633\u064e\u0649\u0670\u0653 \u0623\u064e\u0644\u06e1\u0642\u064f\u0648\u0627\u0652 \u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064f\u0645 \u0645\u0651\u064f\u0644\u06e1\u0642\u064f\u0648\u0646\u064e",translation:"Dia (Musa) berkata kepada mereka, \"Lemparkanlah apa yang hendak kamu lemparkan"},{id:44,text:"\u0641\u064e\u0623\u064e\u0644\u06e1\u0642\u064e\u0648\u06e1\u0627\u0652 \u062d\u0650\u0628\u064e\u0627\u0644\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0639\u0650\u0635\u0650\u064a\u0651\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0628\u0650\u0639\u0650\u0632\u0651\u064e\u0629\u0650 \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0646\u064e\u062d\u06e1\u0646\u064f \u0671\u0644\u06e1\u063a\u064e\u0670\u0644\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Lalu mereka melemparkan tali-temali dan tongkat-tongkat mereka seraya berkata, \"Demi kemuliaan Fir'aun, pasti kamilah yang akan menang"},{id:45,text:"\u0641\u064e\u0623\u064e\u0644\u06e1\u0642\u064e\u0649\u0670 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0639\u064e\u0635\u064e\u0627\u0647\u064f \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0647\u0650\u064a\u064e \u062a\u064e\u0644\u06e1\u0642\u064e\u0641\u064f \u0645\u064e\u0627 \u064a\u064e\u0623\u06e1\u0641\u0650\u0643\u064f\u0648\u0646\u064e",translation:"Kemudian Musa melemparkan tongkatnya, maka tiba-tiba ia menelan benda-benda palsu yang mereka ada-adakan itu"},{id:46,text:"\u0641\u064e\u0623\u064f\u0644\u06e1\u0642\u0650\u064a\u064e \u0671\u0644\u0633\u0651\u064e\u062d\u064e\u0631\u064e\u0629\u064f \u0633\u064e\u0670\u062c\u0650\u062f\u0650\u064a\u0646\u064e",translation:"Maka menyungkurlah para pesihir itu, bersujud"},{id:47,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0621\u064e\u0627\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0631\u064e\u0628\u0651\u0650 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"mereka berkata, \"Kami beriman kepada Tuhan seluruh alam"},{id:48,text:"\u0631\u064e\u0628\u0651\u0650 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u0647\u064e\u0670\u0631\u064f\u0648\u0646\u064e",translation:"(yaitu) Tuhannya Musa dan Harun"},{id:49,text:"\u0642\u064e\u0627\u0644\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u062a\u064f\u0645\u06e1 \u0644\u064e\u0647\u064f\u06e5 \u0642\u064e\u0628\u06e1\u0644\u064e \u0623\u064e\u0646\u06e1 \u0621\u064e\u0627\u0630\u064e\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u06e1\u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0643\u064e\u0628\u0650\u064a\u0631\u064f\u0643\u064f\u0645\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0639\u064e\u0644\u0651\u064e\u0645\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0633\u0651\u0650\u062d\u06e1\u0631\u064e \u0641\u064e\u0644\u064e\u0633\u064e\u0648\u06e1\u0641\u064e \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e\u06da \u0644\u064e\u0623\u064f\u0642\u064e\u0637\u0651\u0650\u0639\u064e\u0646\u0651\u064e \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0631\u06e1\u062c\u064f\u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u062e\u0650\u0644\u064e\u0670\u0641\u0656 \u0648\u064e\u0644\u064e\u0623\u064f\u0635\u064e\u0644\u0651\u0650\u0628\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u062c\u06e1\u0645\u064e\u0639\u0650\u064a\u0646\u064e",translation:"Dia (Fir'aun) berkata, \"Mengapa kamu beriman kepada Musa sebelum aku memberi izin kepadamu? Sesungguhnya dia pemimpinmu yang mengajarkan sihir kepadamu. Nanti kamu pasti akan tahu (akibat perbuatanmu). Pasti akan kupotong tangan dan kakimu bersilang dan sungguh akan aku salib semuanya"},{id:50,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u0636\u064e\u064a\u06e1\u0631\u064e\u06d6 \u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627 \u0645\u064f\u0646\u0642\u064e\u0644\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Mereka berkata, \"Tidak ada yang kami takutkan, karena kami akan kembali kepada Tuhan kami"},{id:51,text:"\u0625\u0650\u0646\u0651\u064e\u0627 \u0646\u064e\u0637\u06e1\u0645\u064e\u0639\u064f \u0623\u064e\u0646 \u064a\u064e\u063a\u06e1\u0641\u0650\u0631\u064e \u0644\u064e\u0646\u064e\u0627 \u0631\u064e\u0628\u0651\u064f\u0646\u064e\u0627 \u062e\u064e\u0637\u064e\u0670\u064a\u064e\u0670\u0646\u064e\u0627\u0653 \u0623\u064e\u0646 \u0643\u064f\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u0648\u0651\u064e\u0644\u064e \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Sesungguhnya kami sangat menginginkan sekiranya Tuhan kami akan mengampuni kesalahan kami, karena menjadi orang yang pertama-tama beriman"},{id:52,text:"\u06de\u0648\u064e\u0623\u064e\u0648\u06e1\u062d\u064e\u064a\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064f\u0648\u0633\u064e\u0649\u0670\u0653 \u0623\u064e\u0646\u06e1 \u0623\u064e\u0633\u06e1\u0631\u0650 \u0628\u0650\u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a\u0653 \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645 \u0645\u0651\u064f\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Dan Kami wahyukan (perintahkan) kepada Musa, \"Pergilah pada malam hari dengan membawa hamba-hamba-Ku (Bani Israil), sebab pasti kamu akan dikejar"},{id:53,text:"\u0641\u064e\u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u064e \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064f \u0641\u0650\u064a \u0671\u0644\u06e1\u0645\u064e\u062f\u064e\u0627\u0653\u0626\u0650\u0646\u0650 \u062d\u064e\u0670\u0634\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Kemudian Fir'aun mengirimkan orang ke kota-kota untuk mengumpulkan (bala tentaranya)"},{id:54,text:"\u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650 \u0644\u064e\u0634\u0650\u0631\u06e1\u0630\u0650\u0645\u064e\u0629\u065e \u0642\u064e\u0644\u0650\u064a\u0644\u064f\u0648\u0646\u064e",translation:"(Fir'aun berkata), \"Sesungguhnya mereka (Bani Israil) hanya sekelompok kecil"},{id:55,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0646\u064e\u0627 \u0644\u064e\u063a\u064e\u0627\u0653\u0626\u0650\u0638\u064f\u0648\u0646\u064e",translation:"dan sesungguhnya mereka telah berbuat hal-hal yang menimbulkan amarah kita"},{id:56,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u062c\u064e\u0645\u0650\u064a\u0639\u064c \u062d\u064e\u0670\u0630\u0650\u0631\u064f\u0648\u0646\u064e",translation:"dan sesungguhnya kita semua tanpa kecuali harus selalu waspada"},{id:57,text:"\u0641\u064e\u0623\u064e\u062e\u06e1\u0631\u064e\u062c\u06e1\u0646\u064e\u0670\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0656 \u0648\u064e\u0639\u064f\u064a\u064f\u0648\u0646\u0656",translation:"Kemudian, Kami keluarkan mereka (Fir'aun dan kaumnya) dari taman-taman dan mata air"},{id:58,text:"\u0648\u064e\u0643\u064f\u0646\u064f\u0648\u0632\u0656 \u0648\u064e\u0645\u064e\u0642\u064e\u0627\u0645\u0656 \u0643\u064e\u0631\u0650\u064a\u0645\u0656",translation:"dan (dari) harta kekayaan dan kedudukan yang mulia"},{id:59,text:"\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e\u06d6 \u0648\u064e\u0623\u064e\u0648\u06e1\u0631\u064e\u062b\u06e1\u0646\u064e\u0670\u0647\u064e\u0627 \u0628\u064e\u0646\u0650\u064a\u0653 \u0625\u0650\u0633\u06e1\u0631\u064e\u0640\u0670\u0653\u0621\u0650\u064a\u0644\u064e",translation:"demikianlah, dan Kami anugerahkan semuanya (itu) kepada Bani Israil"},{id:60,text:"\u0641\u064e\u0623\u064e\u062a\u06e1\u0628\u064e\u0639\u064f\u0648\u0647\u064f\u0645 \u0645\u0651\u064f\u0634\u06e1\u0631\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Lalu (Fir'aun dan bala tentaranya) dapat menyusul mereka pada waktu matahari terbit"},{id:61,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062a\u064e\u0631\u064e\u0640\u0670\u0653\u0621\u064e\u0627 \u0671\u0644\u06e1\u062c\u064e\u0645\u06e1\u0639\u064e\u0627\u0646\u0650 \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0645\u064f\u0648\u0633\u064e\u0649\u0670\u0653 \u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0645\u064f\u062f\u06e1\u0631\u064e\u0643\u064f\u0648\u0646\u064e",translation:"Maka ketika kedua golongan itu saling melihat, berkatalah pengikut-pengikut Musa, \"Kita benar-benar akan tersusul"},{id:62,text:"\u0642\u064e\u0627\u0644\u064e \u0643\u064e\u0644\u0651\u064e\u0627\u0653\u06d6 \u0625\u0650\u0646\u0651\u064e \u0645\u064e\u0639\u0650\u064a\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0633\u064e\u064a\u064e\u0647\u06e1\u062f\u0650\u064a\u0646\u0650",translation:"Dia (Musa) menjawab, \"Sekali-kali tidak akan (tersusul); sesungguhnya Tuhanku bersamaku, Dia akan memberi petunjuk kepadaku"},{id:63,text:"\u0641\u064e\u0623\u064e\u0648\u06e1\u062d\u064e\u064a\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064f\u0648\u0633\u064e\u0649\u0670\u0653 \u0623\u064e\u0646\u0650 \u0671\u0636\u06e1\u0631\u0650\u0628 \u0628\u0651\u0650\u0639\u064e\u0635\u064e\u0627\u0643\u064e \u0671\u0644\u06e1\u0628\u064e\u062d\u06e1\u0631\u064e\u06d6 \u0641\u064e\u0671\u0646\u0641\u064e\u0644\u064e\u0642\u064e \u0641\u064e\u0643\u064e\u0627\u0646\u064e \u0643\u064f\u0644\u0651\u064f \u0641\u0650\u0631\u06e1\u0642\u0656 \u0643\u064e\u0671\u0644\u0637\u0651\u064e\u0648\u06e1\u062f\u0650 \u0671\u0644\u06e1\u0639\u064e\u0638\u0650\u064a\u0645\u0650",translation:"Lalu Kami wahyukan kepada Musa, \"Pukullah laut itu dengan tongkatmu.\" Maka terbelahlah lautan itu, dan setiap belahan seperti gunung yang besar"},{id:64,text:"\u0648\u064e\u0623\u064e\u0632\u06e1\u0644\u064e\u0641\u06e1\u0646\u064e\u0627 \u062b\u064e\u0645\u0651\u064e \u0671\u0644\u06e1\u0623\u0653\u062e\u064e\u0631\u0650\u064a\u0646\u064e",translation:"Dan di sanalah Kami dekatkan golongan yang lain"},{id:65,text:"\u0648\u064e\u0623\u064e\u0646\u062c\u064e\u064a\u06e1\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u0645\u064e\u0646 \u0645\u0651\u064e\u0639\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u062c\u06e1\u0645\u064e\u0639\u0650\u064a\u0646\u064e",translation:"Dan Kami selamatkan Musa dan orang-orang yang bersamanya"},{id:66,text:"\u062b\u064f\u0645\u0651\u064e \u0623\u064e\u063a\u06e1\u0631\u064e\u0642\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0623\u0653\u062e\u064e\u0631\u0650\u064a\u0646\u064e",translation:"Kemudian Kami tenggelamkan golongan yang lain"},{id:67,text:"\u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0623\u0653\u064a\u064e\u0629\u0657\u06d6 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064f\u0647\u064f\u0645 \u0645\u0651\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Sungguh, pada yang demikian itu terdapat suatu tanda (kekuasaan Allah), tetapi kebanyakan mereka tidak beriman"},{id:68,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0644\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0671\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",translation:"Dan sesungguhnya Tuhanmu Dialah Yang Mahaperkasa, Maha Penyayang"},{id:69,text:"\u0648\u064e\u0671\u062a\u06e1\u0644\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0646\u064e\u0628\u064e\u0623\u064e \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064e",translation:"Dan bacakanlah kepada mereka kisah Ibrahim"},{id:70,text:"\u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0623\u064e\u0628\u0650\u064a\u0647\u0650 \u0648\u064e\u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u06e6 \u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0646\u064e",translation:"Ketika dia (Ibrahim) berkata kepada ayahnya dan kaumnya, \"Apakah yang kamu sembah"},{id:71,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0646\u064e\u0639\u06e1\u0628\u064f\u062f\u064f \u0623\u064e\u0635\u06e1\u0646\u064e\u0627\u0645\u0657\u0627 \u0641\u064e\u0646\u064e\u0638\u064e\u0644\u0651\u064f \u0644\u064e\u0647\u064e\u0627 \u0639\u064e\u0670\u0643\u0650\u0641\u0650\u064a\u0646\u064e",translation:"Mereka menjawab, \"Kami menyembah berhala-berhala dan kami senantiasa tekun menyembahnya"},{id:72,text:"\u0642\u064e\u0627\u0644\u064e \u0647\u064e\u0644\u06e1 \u064a\u064e\u0633\u06e1\u0645\u064e\u0639\u064f\u0648\u0646\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0630\u06e1 \u062a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e",translation:"Dia (Ibrahim) berkata, \"Apakah mereka mendengarmu ketika kamu berdoa (kepadanya)"},{id:73,text:"\u0623\u064e\u0648\u06e1 \u064a\u064e\u0646\u0641\u064e\u0639\u064f\u0648\u0646\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1 \u064a\u064e\u0636\u064f\u0631\u0651\u064f\u0648\u0646\u064e",translation:"atau (dapatkah) mereka memberi manfaat atau mencelakakan kamu"},{id:74,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0628\u064e\u0644\u06e1 \u0648\u064e\u062c\u064e\u062f\u06e1\u0646\u064e\u0627\u0653 \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0621\u064e\u0646\u064e\u0627 \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064e\u0641\u06e1\u0639\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Mereka menjawab, \"Tidak, tetapi kami dapati nenek moyang kami berbuat begitu"},{id:75,text:"\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0641\u064e\u0631\u064e\u0621\u064e\u064a\u06e1\u062a\u064f\u0645 \u0645\u0651\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0646\u064e",translation:"Dia (Ibrahim) berkata, \"Apakah kamu memperhatikan apa yang kamu sembah"},{id:76,text:"\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0648\u064e\u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0624\u064f\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u0642\u06e1\u062f\u064e\u0645\u064f\u0648\u0646\u064e",translation:"kamu dan nenek moyang kamu yang terdahulu"},{id:77,text:"\u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u062f\u064f\u0648\u0651\u065e \u0644\u0651\u0650\u064a\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0631\u064e\u0628\u0651\u064e \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"sesungguhnya mereka (apa yang kamu sembah) itu musuhku, lain halnya Tuhan seluruh alam"},{id:78,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e\u0646\u0650\u064a \u0641\u064e\u0647\u064f\u0648\u064e \u064a\u064e\u0647\u06e1\u062f\u0650\u064a\u0646\u0650",translation:"(yaitu) Yang telah menciptakan aku, maka Dia yang memberi petunjuk kepadaku"},{id:79,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0647\u064f\u0648\u064e \u064a\u064f\u0637\u06e1\u0639\u0650\u0645\u064f\u0646\u0650\u064a \u0648\u064e\u064a\u064e\u0633\u06e1\u0642\u0650\u064a\u0646\u0650",translation:"dan Yang memberi makan dan minum kepadaku"},{id:80,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0631\u0650\u0636\u06e1\u062a\u064f \u0641\u064e\u0647\u064f\u0648\u064e \u064a\u064e\u0634\u06e1\u0641\u0650\u064a\u0646\u0650",translation:"dan apabila aku sakit, Dialah yang menyembuhkan aku"},{id:81,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u0645\u0650\u064a\u062a\u064f\u0646\u0650\u064a \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u062d\u06e1\u064a\u0650\u064a\u0646\u0650",translation:"dan Yang akan mematikan aku, kemudian akan menghidupkan aku (kembali)"},{id:82,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064e\u0637\u06e1\u0645\u064e\u0639\u064f \u0623\u064e\u0646 \u064a\u064e\u063a\u06e1\u0641\u0650\u0631\u064e \u0644\u0650\u064a \u062e\u064e\u0637\u0650\u064a\u0653\u0640\u0654\u064e\u062a\u0650\u064a \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u0650",translation:"dan Yang sangat ku inginkan akan mengampuni kesalahanku pada hari Kiamat"},{id:83,text:"\u0631\u064e\u0628\u0651\u0650 \u0647\u064e\u0628\u06e1 \u0644\u0650\u064a \u062d\u064f\u0643\u06e1\u0645\u0657\u0627 \u0648\u064e\u0623\u064e\u0644\u06e1\u062d\u0650\u0642\u06e1\u0646\u0650\u064a \u0628\u0650\u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u0650\u064a\u0646\u064e",translation:"(Ibrahim berdoa), \"Ya Tuhanku, berikanlah kepadaku ilmu dan masukkanlah aku ke dalam golongan orang-orang yang saleh"},{id:84,text:"\u0648\u064e\u0671\u062c\u06e1\u0639\u064e\u0644 \u0644\u0651\u0650\u064a \u0644\u0650\u0633\u064e\u0627\u0646\u064e \u0635\u0650\u062f\u06e1\u0642\u0656 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u0650\u064a\u0646\u064e",translation:"dan jadikanlah aku buah tutur yang baik bagi orang-orang (yang datang) kemudian"},{id:85,text:"\u0648\u064e\u0671\u062c\u06e1\u0639\u064e\u0644\u06e1\u0646\u0650\u064a \u0645\u0650\u0646 \u0648\u064e\u0631\u064e\u062b\u064e\u0629\u0650 \u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u0671\u0644\u0646\u0651\u064e\u0639\u0650\u064a\u0645\u0650",translation:"dan jadikanlah aku termasuk orang yang mewarisi surga yang penuh kenikmatan"},{id:86,text:"\u0648\u064e\u0671\u063a\u06e1\u0641\u0650\u0631\u06e1 \u0644\u0650\u0623\u064e\u0628\u0650\u064a\u0653 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0636\u0651\u064e\u0627\u0653\u0644\u0651\u0650\u064a\u0646\u064e",translation:"dan ampunilah ayahku, sesungguhnya dia termasuk orang yang sesat"},{id:87,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u062e\u06e1\u0632\u0650\u0646\u0650\u064a \u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064f\u0628\u06e1\u0639\u064e\u062b\u064f\u0648\u0646\u064e",translation:"dan janganlah Engkau hinakan aku pada hari mereka dibangkitkan"},{id:88,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u0644\u064e\u0627 \u064a\u064e\u0646\u0641\u064e\u0639\u064f \u0645\u064e\u0627\u0644\u065e \u0648\u064e\u0644\u064e\u0627 \u0628\u064e\u0646\u064f\u0648\u0646\u064e",translation:"(yaitu) pada hari (ketika) harta dan anak-anak tidak berguna"},{id:89,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u06e1 \u0623\u064e\u062a\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u0642\u064e\u0644\u06e1\u0628\u0656 \u0633\u064e\u0644\u0650\u064a\u0645\u0656",translation:"kecuali orang-orang yang menghadap Allah dengan hati yang bersih"},{id:90,text:"\u0648\u064e\u0623\u064f\u0632\u06e1\u0644\u0650\u0641\u064e\u062a\u0650 \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u064f \u0644\u0650\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",translation:"dan surga didekatkan kepada orang-orang yang bertakwa"},{id:91,text:"\u0648\u064e\u0628\u064f\u0631\u0651\u0650\u0632\u064e\u062a\u0650 \u0671\u0644\u06e1\u062c\u064e\u062d\u0650\u064a\u0645\u064f \u0644\u0650\u0644\u06e1\u063a\u064e\u0627\u0648\u0650\u064a\u0646\u064e",translation:"dan neraka Jahim diperlihatkan dengan jelas kepada orang-orang yang sesat"},{id:92,text:"\u0648\u064e\u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u064a\u06e1\u0646\u064e \u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0646\u064e",translation:"dan dikatakan kepada mereka, \"Di mana berhala-berhala yang dahulu kamu sembah"},{id:93,text:"\u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0647\u064e\u0644\u06e1 \u064a\u064e\u0646\u0635\u064f\u0631\u064f\u0648\u0646\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1 \u064a\u064e\u0646\u062a\u064e\u0635\u0650\u0631\u064f\u0648\u0646\u064e",translation:"selain Allah? Dapatkah mereka menolong kamu atau menolong diri mereka sendiri"},{id:94,text:"\u0641\u064e\u0643\u064f\u0628\u06e1\u0643\u0650\u0628\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0647\u064f\u0645\u06e1 \u0648\u064e\u0671\u0644\u06e1\u063a\u064e\u0627\u0648\u064f\u06e5\u0646\u064e",translation:"Maka mereka (sesembahan itu) dijungkirkan ke dalam neraka bersama orang-orang yang sesat"},{id:95,text:"\u0648\u064e\u062c\u064f\u0646\u064f\u0648\u062f\u064f \u0625\u0650\u0628\u06e1\u0644\u0650\u064a\u0633\u064e \u0623\u064e\u062c\u06e1\u0645\u064e\u0639\u064f\u0648\u0646\u064e",translation:"dan bala tentara Iblis semuanya"},{id:96,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u064a\u064e\u062e\u06e1\u062a\u064e\u0635\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Mereka berkata sambil bertengkar di dalamnya (neraka)"},{id:97,text:"\u062a\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0646 \u0643\u064f\u0646\u0651\u064e\u0627 \u0644\u064e\u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0670\u0644\u0656 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u064d",translation:"Demi Allah, sesungguhnya kita dahulu (di dunia) dalam kesesatan yang nyata"},{id:98,text:"\u0625\u0650\u0630\u06e1 \u0646\u064f\u0633\u064e\u0648\u0651\u0650\u064a\u0643\u064f\u0645 \u0628\u0650\u0631\u064e\u0628\u0651\u0650 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"karena kita mempersamakan kamu (berhala-berhala) dengan Tuhan seluruh alam"},{id:99,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0636\u064e\u0644\u0651\u064e\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u06e1\u0645\u064f\u062c\u06e1\u0631\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Dan tidak ada yang menyesatkan kita kecuali orang-orang yang berdosa"},{id:100,text:"\u0641\u064e\u0645\u064e\u0627 \u0644\u064e\u0646\u064e\u0627 \u0645\u0650\u0646 \u0634\u064e\u0670\u0641\u0650\u0639\u0650\u064a\u0646\u064e",translation:"Maka (sekarang) kita tidak mempunyai seorang pun pemberi syafaat (penolong)"},{id:101,text:"\u0648\u064e\u0644\u064e\u0627 \u0635\u064e\u062f\u0650\u064a\u0642\u064d \u062d\u064e\u0645\u0650\u064a\u0645\u0656",translation:"dan tidak pula mempunyai teman yang akrab"},{id:102,text:"\u0641\u064e\u0644\u064e\u0648\u06e1 \u0623\u064e\u0646\u0651\u064e \u0644\u064e\u0646\u064e\u0627 \u0643\u064e\u0631\u0651\u064e\u0629\u0657 \u0641\u064e\u0646\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Maka seandainya kita dapat kembali (ke dunia) niscaya kita menjadi orang-orang yang beriman"},{id:103,text:"\u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0623\u0653\u064a\u064e\u0629\u0657\u06d6 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064f\u0647\u064f\u0645 \u0645\u0651\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Sungguh, pada yang demikian itu terdapat tanda (kekuasaan Allah), tetapi kebanyakan mereka tidak beriman"},{id:104,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0644\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0671\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",translation:"Dan sungguh, Tuhanmu benar-benar Dialah Mahaperkasa, Maha Penyayang"},{id:105,text:"\u0643\u064e\u0630\u0651\u064e\u0628\u064e\u062a\u06e1 \u0642\u064e\u0648\u06e1\u0645\u064f \u0646\u064f\u0648\u062d\u064d \u0671\u0644\u06e1\u0645\u064f\u0631\u06e1\u0633\u064e\u0644\u0650\u064a\u0646\u064e",translation:"Kaum Nuh telah mendustakan para rasul"},{id:106,text:"\u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u062e\u064f\u0648\u0647\u064f\u0645\u06e1 \u0646\u064f\u0648\u062d\u064c \u0623\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",translation:"Ketika saudara mereka (Nuh) berkata kepada mereka, \"Mengapa kamu tidak bertakwa"},{id:107,text:"\u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0643\u064f\u0645\u06e1 \u0631\u064e\u0633\u064f\u0648\u0644\u064c \u0623\u064e\u0645\u0650\u064a\u0646\u065e",translation:"Sesungguhnya aku ini seorang rasul kepercayaan (yang diutus) kepadamu"},{id:108,text:"\u0641\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u0650",translation:"maka bertakwalah kamu kepada Allah dan taatlah kepadaku"},{id:109,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0643\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0645\u0650\u0646\u06e1 \u0623\u064e\u062c\u06e1\u0631\u064d\u06d6 \u0625\u0650\u0646\u06e1 \u0623\u064e\u062c\u06e1\u0631\u0650\u064a\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Dan aku tidak meminta imbalan kepadamu atas ajakan ini; imbalanku hanyalah dari Tuhan seluruh alam"},{id:110,text:"\u0641\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u0650",translation:"maka bertakwalah kamu kepada Allah dan taatlah kepadaku"},{id:111,text:"\u06de\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u064f\u0624\u06e1\u0645\u0650\u0646\u064f \u0644\u064e\u0643\u064e \u0648\u064e\u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064e\u0643\u064e \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0630\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Mereka berkata, \"Apakah kami harus beriman kepadamu, padahal pengikut-pengikutmu orang-orang yang hina"},{id:112,text:"\u0642\u064e\u0627\u0644\u064e \u0648\u064e\u0645\u064e\u0627 \u0639\u0650\u0644\u06e1\u0645\u0650\u064a \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dia (Nuh) menjawab, \"Tidak ada pengetahuanku tentang apa yang mereka kerjakan"},{id:113,text:"\u0625\u0650\u0646\u06e1 \u062d\u0650\u0633\u064e\u0627\u0628\u064f\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u064a\u06d6 \u0644\u064e\u0648\u06e1 \u062a\u064e\u0634\u06e1\u0639\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Perhitungan (amal perbuatan) mereka tidak lain hanyalah kepada Tuhanku, jika kamu menyadari"},{id:114,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u064e\u0627\u06e0 \u0628\u0650\u0637\u064e\u0627\u0631\u0650\u062f\u0650 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dan aku tidak akan mengusir orang-orang yang beriman"},{id:115,text:"\u0625\u0650\u0646\u06e1 \u0623\u064e\u0646\u064e\u0627\u06e0 \u0625\u0650\u0644\u0651\u064e\u0627 \u0646\u064e\u0630\u0650\u064a\u0631\u065e \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u065e",translation:"Aku (ini) hanyalah pemberi peringatan yang jelas"},{id:116,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0626\u0650\u0646 \u0644\u0651\u064e\u0645\u06e1 \u062a\u064e\u0646\u062a\u064e\u0647\u0650 \u064a\u064e\u0670\u0646\u064f\u0648\u062d\u064f \u0644\u064e\u062a\u064e\u0643\u064f\u0648\u0646\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064e\u0631\u06e1\u062c\u064f\u0648\u0645\u0650\u064a\u0646\u064e",translation:"Mereka berkata, \"Wahai Nuh! Sungguh, jika engkau tidak (mau) berhenti, niscaya engkau termasuk orang yang dirajam (dilempari batu sampai mati)"},{id:117,text:"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0625\u0650\u0646\u0651\u064e \u0642\u064e\u0648\u06e1\u0645\u0650\u064a \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0646\u0650",translation:"Dia (Nuh) berkata, \"Ya Tuhanku, sungguh kaumku telah mendustakan aku"},{id:118,text:"\u0641\u064e\u0671\u0641\u06e1\u062a\u064e\u062d\u06e1 \u0628\u064e\u064a\u06e1\u0646\u0650\u064a \u0648\u064e\u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1 \u0641\u064e\u062a\u06e1\u062d\u0657\u0627 \u0648\u064e\u0646\u064e\u062c\u0651\u0650\u0646\u0650\u064a \u0648\u064e\u0645\u064e\u0646 \u0645\u0651\u064e\u0639\u0650\u064a\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"maka berilah keputusan antara aku dengan mereka, dan selamatkanlah aku dan mereka yang beriman bersamaku"},{id:119,text:"\u0641\u064e\u0623\u064e\u0646\u062c\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f \u0648\u064e\u0645\u064e\u0646 \u0645\u0651\u064e\u0639\u064e\u0647\u064f\u06e5 \u0641\u0650\u064a \u0671\u0644\u06e1\u0641\u064f\u0644\u06e1\u0643\u0650 \u0671\u0644\u06e1\u0645\u064e\u0634\u06e1\u062d\u064f\u0648\u0646\u0650",translation:"Kemudian Kami menyelamatkan Nuh dan orang-orang yang bersamanya di dalam kapal yang penuh muatan"},{id:120,text:"\u062b\u064f\u0645\u0651\u064e \u0623\u064e\u063a\u06e1\u0631\u064e\u0642\u06e1\u0646\u064e\u0627 \u0628\u064e\u0639\u06e1\u062f\u064f \u0671\u0644\u06e1\u0628\u064e\u0627\u0642\u0650\u064a\u0646\u064e",translation:"Kemudian setelah itu Kami tenggelamkan orang-orang yang tinggal"},{id:121,text:"\u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0623\u0653\u064a\u064e\u0629\u0657\u06d6 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064f\u0647\u064f\u0645 \u0645\u0651\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Sungguh, pada yang demikian itu benar-benar terdapat tanda (kekuasaan Allah), tetapi kebanyakan mereka tidak beriman"},{id:122,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0644\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0671\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",translation:"Dan sungguh, Tuhanmu, Dialah Yang Mahaperkasa, Maha penyayang"},{id:123,text:"\u0643\u064e\u0630\u0651\u064e\u0628\u064e\u062a\u06e1 \u0639\u064e\u0627\u062f\u064c \u0671\u0644\u06e1\u0645\u064f\u0631\u06e1\u0633\u064e\u0644\u0650\u064a\u0646\u064e",translation:"(Kaum) '\u0100d telah mendustakan para rasul"},{id:124,text:"\u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u062e\u064f\u0648\u0647\u064f\u0645\u06e1 \u0647\u064f\u0648\u062f\u064c \u0623\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",translation:"Ketika saudara mereka Hud berkata kepada mereka, \"Mengapa kamu tidak bertakwa"},{id:125,text:"\u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0643\u064f\u0645\u06e1 \u0631\u064e\u0633\u064f\u0648\u0644\u064c \u0623\u064e\u0645\u0650\u064a\u0646\u065e",translation:"Sungguh, aku ini seorang rasul kepercayaan (yang diutus) kepadamu"},{id:126,text:"\u0641\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u0650",translation:"maka bertakwalah kepada Allah dan taatlah kepadaku"},{id:127,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0643\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0645\u0650\u0646\u06e1 \u0623\u064e\u062c\u06e1\u0631\u064d\u06d6 \u0625\u0650\u0646\u06e1 \u0623\u064e\u062c\u06e1\u0631\u0650\u064a\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Dan aku tidak minta imbalan kepadamu atas ajakan itu; imbalanku hanyalah dari Tuhan seluruh alam"},{id:128,text:"\u0623\u064e\u062a\u064e\u0628\u06e1\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0631\u0650\u064a\u0639\u064d \u0621\u064e\u0627\u064a\u064e\u0629\u0657 \u062a\u064e\u0639\u06e1\u0628\u064e\u062b\u064f\u0648\u0646\u064e",translation:"Apakah kamu mendirikan istana-istana pada setiap tanah yang tinggi untuk kemegahan tanpa ditempati"},{id:129,text:"\u0648\u064e\u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0646\u064e \u0645\u064e\u0635\u064e\u0627\u0646\u0650\u0639\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u062e\u06e1\u0644\u064f\u062f\u064f\u0648\u0646\u064e",translation:"dan kamu membuat benteng-benteng dengan harapan kamu hidup kekal"},{id:130,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0628\u064e\u0637\u064e\u0634\u06e1\u062a\u064f\u0645 \u0628\u064e\u0637\u064e\u0634\u06e1\u062a\u064f\u0645\u06e1 \u062c\u064e\u0628\u0651\u064e\u0627\u0631\u0650\u064a\u0646\u064e",translation:"Dan apabila kamu menyiksa, maka kamu lakukan secara kejam dan bengis"},{id:131,text:"\u0641\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u0650",translation:"Maka bertakwalah kepada Allah dan taatlah kepadaku"},{id:132,text:"\u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064e\u0645\u064e\u062f\u0651\u064e\u0643\u064f\u0645 \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"dan tetaplah kamu bertakwa kepada-Nya yang telah menganugerahkan kepadamu apa yang kamu ketahui"},{id:133,text:"\u0623\u064e\u0645\u064e\u062f\u0651\u064e\u0643\u064f\u0645 \u0628\u0650\u0623\u064e\u0646\u06e1\u0639\u064e\u0670\u0645\u0656 \u0648\u064e\u0628\u064e\u0646\u0650\u064a\u0646\u064e",translation:"Dia (Allah) telah menganugerahkan kepadamu hewan ternak dan anak-anak"},{id:134,text:"\u0648\u064e\u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0656 \u0648\u064e\u0639\u064f\u064a\u064f\u0648\u0646\u064d",translation:"dan kebun-kebun, dan mata air"},{id:135,text:"\u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u064a\u064e\u0648\u06e1\u0645\u064d \u0639\u064e\u0638\u0650\u064a\u0645\u0656",translation:"sesungguhnya aku takut kamu akan ditimpa azab pada hari yang besar"},{id:136,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0633\u064e\u0648\u064e\u0627\u0653\u0621\u064c \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627\u0653 \u0623\u064e\u0648\u064e\u0639\u064e\u0638\u06e1\u062a\u064e \u0623\u064e\u0645\u06e1 \u0644\u064e\u0645\u06e1 \u062a\u064e\u0643\u064f\u0646 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0648\u064e\u0670\u0639\u0650\u0638\u0650\u064a\u0646\u064e",translation:"Mereka menjawab, \"Sama saja bagi kami, apakah engkau memberi nasihat atau tidak memberi nasihat"},{id:137,text:"\u0625\u0650\u0646\u06e1 \u0647\u064e\u0670\u0630\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u062e\u064f\u0644\u064f\u0642\u064f \u0671\u0644\u06e1\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",translation:"(agama kami) ini tidak lain hanyalah adat kebiasaan orang-orang terdahulu"},{id:138,text:"\u0648\u064e\u0645\u064e\u0627 \u0646\u064e\u062d\u06e1\u0646\u064f \u0628\u0650\u0645\u064f\u0639\u064e\u0630\u0651\u064e\u0628\u0650\u064a\u0646\u064e",translation:"dan kami (sama sekali) tidak akan di azab"},{id:139,text:"\u0641\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0647\u064f \u0641\u064e\u0623\u064e\u0647\u06e1\u0644\u064e\u0643\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0623\u0653\u064a\u064e\u0629\u0657\u06d6 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064f\u0647\u064f\u0645 \u0645\u0651\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Maka mereka mendustakannya (Hud), lalu Kami binasakan mereka. Sungguh, pada yang demikian itu terdapat tanda (kekuasaan Allah), tetapi kebanyakan mereka tidak beriman"},{id:140,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0644\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0671\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",translation:"Dan sungguh, Tuhanmu, Dialah Yang Mahaperkasa, Maha Penyayang"},{id:141,text:"\u0643\u064e\u0630\u0651\u064e\u0628\u064e\u062a\u06e1 \u062b\u064e\u0645\u064f\u0648\u062f\u064f \u0671\u0644\u06e1\u0645\u064f\u0631\u06e1\u0633\u064e\u0644\u0650\u064a\u0646\u064e",translation:"Kaum Samud telah mendustakan para rasul"},{id:142,text:"\u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u062e\u064f\u0648\u0647\u064f\u0645\u06e1 \u0635\u064e\u0670\u0644\u0650\u062d\u064c \u0623\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",translation:"Ketika saudara mereka Saleh berkata kepada mereka, \"Mengapa kamu tidak bertakwa"},{id:143,text:"\u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0643\u064f\u0645\u06e1 \u0631\u064e\u0633\u064f\u0648\u0644\u064c \u0623\u064e\u0645\u0650\u064a\u0646\u065e",translation:"Sungguh, aku ini seorang rasul kepercayaan (yang diutus) kepadamu"},{id:144,text:"\u0641\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u0650",translation:"maka bertakwalah kepada Allah dan taatlah kepadaku"},{id:145,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0643\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0645\u0650\u0646\u06e1 \u0623\u064e\u062c\u06e1\u0631\u064d\u06d6 \u0625\u0650\u0646\u06e1 \u0623\u064e\u062c\u06e1\u0631\u0650\u064a\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Dan aku tidak meminta sesuatu imbalan kepadamu atas ajakan ini, imbalanku hanyalah dari Tuhan seluruh alam"},{id:146,text:"\u0623\u064e\u062a\u064f\u062a\u06e1\u0631\u064e\u0643\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0645\u064e\u0627 \u0647\u064e\u0670\u0647\u064f\u0646\u064e\u0627\u0653 \u0621\u064e\u0627\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Apakah kamu (mengira) akan dibiarkan tinggal di sini (di negeri kamu ini) dengan aman"},{id:147,text:"\u0641\u0650\u064a \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0656 \u0648\u064e\u0639\u064f\u064a\u064f\u0648\u0646\u0656",translation:"di dalam kebun-kebun dan mata air"},{id:148,text:"\u0648\u064e\u0632\u064f\u0631\u064f\u0648\u0639\u0656 \u0648\u064e\u0646\u064e\u062e\u06e1\u0644\u0656 \u0637\u064e\u0644\u06e1\u0639\u064f\u0647\u064e\u0627 \u0647\u064e\u0636\u0650\u064a\u0645\u065e",translation:"dan tanaman-tanaman dan pohon-pohon kurma yang mayangnya lembut"},{id:149,text:"\u0648\u064e\u062a\u064e\u0646\u06e1\u062d\u0650\u062a\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u062c\u0650\u0628\u064e\u0627\u0644\u0650 \u0628\u064f\u064a\u064f\u0648\u062a\u0657\u0627 \u0641\u064e\u0670\u0631\u0650\u0647\u0650\u064a\u0646\u064e",translation:"Dan kamu pahat dengan terampil sebagian gunung-gunung untuk dijadikan rumah-rumah"},{id:150,text:"\u0641\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u0650",translation:"maka bertakwalah kepada Allah dan taatlah kepadaku"},{id:151,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0637\u0650\u064a\u0639\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0645\u06e1\u0631\u064e \u0671\u0644\u06e1\u0645\u064f\u0633\u06e1\u0631\u0650\u0641\u0650\u064a\u0646\u064e",translation:"dan janganlah kamu menaati perintah orang-orang yang melampaui batas"},{id:152,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0641\u06e1\u0633\u0650\u062f\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0635\u06e1\u0644\u0650\u062d\u064f\u0648\u0646\u064e",translation:"yang berbuat kerusakan di bumi dan tidak mengadakan perbaikan"},{id:153,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0633\u064e\u062d\u0651\u064e\u0631\u0650\u064a\u0646\u064e",translation:"Mereka berkata, \"Sungguh, engkau hanyalah termasuk orang yang kena sihir"},{id:154,text:"\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u064e\u0634\u064e\u0631\u065e \u0645\u0651\u0650\u062b\u06e1\u0644\u064f\u0646\u064e\u0627 \u0641\u064e\u0623\u06e1\u062a\u0650 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0629\u064d \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e",translation:"engkau hanyalah manusia seperti kami; maka datangkanlah suatu mukjizat jika engkau termasuk orang yang benar"},{id:155,text:"\u0642\u064e\u0627\u0644\u064e \u0647\u064e\u0670\u0630\u0650\u0647\u0650\u06e6 \u0646\u064e\u0627\u0642\u064e\u0629\u065e \u0644\u0651\u064e\u0647\u064e\u0627 \u0634\u0650\u0631\u06e1\u0628\u065e \u0648\u064e\u0644\u064e\u0643\u064f\u0645\u06e1 \u0634\u0650\u0631\u06e1\u0628\u064f \u064a\u064e\u0648\u06e1\u0645\u0656 \u0645\u0651\u064e\u0639\u06e1\u0644\u064f\u0648\u0645\u0656",translation:"Dia (Saleh) menjawab, \"Ini seekor unta betina, yang berhak mendapatkan (giliran) minum, dan kamu juga berhak mendapatkan minum pada hari yang ditentukan"},{id:156,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0645\u064e\u0633\u0651\u064f\u0648\u0647\u064e\u0627 \u0628\u0650\u0633\u064f\u0648\u0653\u0621\u0656 \u0641\u064e\u064a\u064e\u0623\u06e1\u062e\u064f\u0630\u064e\u0643\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064f \u064a\u064e\u0648\u06e1\u0645\u064d \u0639\u064e\u0638\u0650\u064a\u0645\u0656",translation:"Dan jangan kamu menyentuhnya (unta itu) dengan jahat, nanti kamu akan ditimpa azab pada hari yang dahsyat"},{id:157,text:"\u0641\u064e\u0639\u064e\u0642\u064e\u0631\u064f\u0648\u0647\u064e\u0627 \u0641\u064e\u0623\u064e\u0635\u06e1\u0628\u064e\u062d\u064f\u0648\u0627\u0652 \u0646\u064e\u0670\u062f\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Kemudian mereka membunuhnya, lalu mereka merasa menyesal"},{id:158,text:"\u0641\u064e\u0623\u064e\u062e\u064e\u0630\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064f\u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0623\u0653\u064a\u064e\u0629\u0657\u06d6 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064f\u0647\u064f\u0645 \u0645\u0651\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"maka mereka ditimpa azab. Sungguh, pada yang demikian itu terdapat tanda (kekuasaan Allah), tetapi kebanyakan mereka tidak beriman"},{id:159,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0644\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0671\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",translation:"Dan sungguh, Tuhanmu, Dialah Yang Mahaperkasa, Maha Penyayang"},{id:160,text:"\u0643\u064e\u0630\u0651\u064e\u0628\u064e\u062a\u06e1 \u0642\u064e\u0648\u06e1\u0645\u064f \u0644\u064f\u0648\u0637\u064d \u0671\u0644\u06e1\u0645\u064f\u0631\u06e1\u0633\u064e\u0644\u0650\u064a\u0646\u064e",translation:"Kaum Lu\u1e6d telah mendustakan para rasul"},{id:161,text:"\u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u062e\u064f\u0648\u0647\u064f\u0645\u06e1 \u0644\u064f\u0648\u0637\u064c \u0623\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",translation:"ketika saudara mereka Lu\u1e6d berkata kepada mereka, \"Mengapa kamu tidak bertakwa"},{id:162,text:"\u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0643\u064f\u0645\u06e1 \u0631\u064e\u0633\u064f\u0648\u0644\u064c \u0623\u064e\u0645\u0650\u064a\u0646\u065e",translation:"Sungguh, aku ini seorang rasul kepercayaan (yang diutus) kepadamu"},{id:163,text:"\u0641\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u0650",translation:"maka bertakwalah kepada Allah dan taatlah kepadaku"},{id:164,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0643\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0645\u0650\u0646\u06e1 \u0623\u064e\u062c\u06e1\u0631\u064d\u06d6 \u0625\u0650\u0646\u06e1 \u0623\u064e\u062c\u06e1\u0631\u0650\u064a\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Dan aku tidak meminta imbalan kepadamu atas ajakan ini; imbalanku hanyalah dari Tuhan seluruh alam"},{id:165,text:"\u0623\u064e\u062a\u064e\u0623\u06e1\u062a\u064f\u0648\u0646\u064e \u0671\u0644\u0630\u0651\u064f\u0643\u06e1\u0631\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Mengapa kamu mendatangi kaum laki-laki dari manusia (berbuat homoseks)"},{id:166,text:"\u0648\u064e\u062a\u064e\u0630\u064e\u0631\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u064e \u0644\u064e\u0643\u064f\u0645\u06e1 \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u0650\u0643\u064f\u0645\u06da \u0628\u064e\u0644\u06e1 \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0642\u064e\u0648\u06e1\u0645\u064c \u0639\u064e\u0627\u062f\u064f\u0648\u0646\u064e",translation:"dan kamu tinggalkan (perempuan) yang diciptakan Tuhan untuk menjadi istri-istri kamu? Kamu (memang) orang-orang yang melampaui batas"},{id:167,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0626\u0650\u0646 \u0644\u0651\u064e\u0645\u06e1 \u062a\u064e\u0646\u062a\u064e\u0647\u0650 \u064a\u064e\u0670\u0644\u064f\u0648\u0637\u064f \u0644\u064e\u062a\u064e\u0643\u064f\u0648\u0646\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u062e\u06e1\u0631\u064e\u062c\u0650\u064a\u0646\u064e",translation:"Mereka menjawab, \"Wahai Lu\u1e6d! Jika engkau tidak berhenti, tentu engkau termasuk orang-orang yang terusir"},{id:168,text:"\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0644\u0650\u0639\u064e\u0645\u064e\u0644\u0650\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0642\u064e\u0627\u0644\u0650\u064a\u0646\u064e",translation:"Dia (Lu\u1e6d) berkata, \"Aku sungguh benci kepada perbuatanmu"},{id:169,text:"\u0631\u064e\u0628\u0651\u0650 \u0646\u064e\u062c\u0651\u0650\u0646\u0650\u064a \u0648\u064e\u0623\u064e\u0647\u06e1\u0644\u0650\u064a \u0645\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"(Lu\u1e6d berdoa), \"Ya Tuhanku, selamatkanlah aku dan keluargaku dari (akibat) perbuatan yang mereka kerjakan"},{id:170,text:"\u0641\u064e\u0646\u064e\u062c\u0651\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f \u0648\u064e\u0623\u064e\u0647\u06e1\u0644\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u062c\u06e1\u0645\u064e\u0639\u0650\u064a\u0646\u064e",translation:"Lalu Kami selamatkan dia bersama keluarganya semua"},{id:171,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u062c\u064f\u0648\u0632\u0657\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u063a\u064e\u0670\u0628\u0650\u0631\u0650\u064a\u0646\u064e",translation:"kecuali seorang perempuan tua (istrinya), yang termasuk dalam golongan yang ditinggal"},{id:172,text:"\u062b\u064f\u0645\u0651\u064e \u062f\u064e\u0645\u0651\u064e\u0631\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0623\u0653\u062e\u064e\u0631\u0650\u064a\u0646\u064e",translation:"Kemudian Kami binasakan yang lain"},{id:173,text:"\u0648\u064e\u0623\u064e\u0645\u06e1\u0637\u064e\u0631\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0645\u0651\u064e\u0637\u064e\u0631\u0657\u0627\u06d6 \u0641\u064e\u0633\u064e\u0627\u0653\u0621\u064e \u0645\u064e\u0637\u064e\u0631\u064f \u0671\u0644\u06e1\u0645\u064f\u0646\u0630\u064e\u0631\u0650\u064a\u0646\u064e",translation:"Dan Kami hujani mereka (dengan hujan batu), maka betapa buruk hujan yang menimpa orang-orang yang telah diberi peringatan itu"},{id:174,text:"\u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0623\u0653\u064a\u064e\u0629\u0657\u06d6 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064f\u0647\u064f\u0645 \u0645\u0651\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Sungguh, pada yang demikian itu terdapat tanda (kekuasaan Allah), tetapi kebanyakan mereka tidak beriman"},{id:175,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0644\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0671\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",translation:"Dan sungguh, Tuhanmu, Dialah Yang Mahaperkasa, Maha Penyayang"},{id:176,text:"\u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0644\u06e1\u0640\u0654\u064e\u064a\u06e1\u0643\u064e\u0629\u0650 \u0671\u0644\u06e1\u0645\u064f\u0631\u06e1\u0633\u064e\u0644\u0650\u064a\u0646\u064e",translation:"(Penduduk Aikah590) telah mendustakan para rasul"},{id:177,text:"\u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0634\u064f\u0639\u064e\u064a\u06e1\u0628\u064c \u0623\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",translation:"ketika Syu'aib berkata kepada mereka, \"Mengapa kamu tidak bertakwa"},{id:178,text:"\u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0643\u064f\u0645\u06e1 \u0631\u064e\u0633\u064f\u0648\u0644\u064c \u0623\u064e\u0645\u0650\u064a\u0646\u065e",translation:"Sungguh, aku adalah rasul kepercayaan (yang diutus) kepadamu"},{id:179,text:"\u0641\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u0650",translation:"maka bertakwalah kepada Allah dan taatlah kepadaku"},{id:180,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0643\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0645\u0650\u0646\u06e1 \u0623\u064e\u062c\u06e1\u0631\u064d\u06d6 \u0625\u0650\u0646\u06e1 \u0623\u064e\u062c\u06e1\u0631\u0650\u064a\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"dan aku tidak meminta imbalan kepadamu atas ajakan ini; imbalanku hanyalah dari Tuhan seluruh alam"},{id:181,text:"\u06de\u0623\u064e\u0648\u06e1\u0641\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0643\u064e\u064a\u06e1\u0644\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u062e\u06e1\u0633\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Sempurnakanlah takaran dan janganlah kamu merugikan orang lain"},{id:182,text:"\u0648\u064e\u0632\u0650\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u06e1\u0642\u0650\u0633\u06e1\u0637\u064e\u0627\u0633\u0650 \u0671\u0644\u06e1\u0645\u064f\u0633\u06e1\u062a\u064e\u0642\u0650\u064a\u0645\u0650",translation:"dan timbanglah dengan timbangan yang benar"},{id:183,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0628\u06e1\u062e\u064e\u0633\u064f\u0648\u0627\u0652 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0623\u064e\u0634\u06e1\u064a\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u062b\u064e\u0648\u06e1\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0645\u064f\u0641\u06e1\u0633\u0650\u062f\u0650\u064a\u0646\u064e",translation:"Dan janganlah kamu merugikan manusia dengan mengurangi hak-haknya dan janganlah membuat kerusakan di bumi"},{id:184,text:"\u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0671\u0644\u06e1\u062c\u0650\u0628\u0650\u0644\u0651\u064e\u0629\u064e \u0671\u0644\u06e1\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",translation:"dan bertakwalah kepada Allah yang telah menciptakan kamu dan umat-umat yang terdahulu"},{id:185,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0633\u064e\u062d\u0651\u064e\u0631\u0650\u064a\u0646\u064e",translation:"Mereka berkata, \"Engkau tidak lain hanyalah orang-orang yang kena sihir"},{id:186,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u064e\u0634\u064e\u0631\u065e \u0645\u0651\u0650\u062b\u06e1\u0644\u064f\u0646\u064e\u0627 \u0648\u064e\u0625\u0650\u0646 \u0646\u0651\u064e\u0638\u064f\u0646\u0651\u064f\u0643\u064e \u0644\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0643\u064e\u0670\u0630\u0650\u0628\u0650\u064a\u0646\u064e",translation:"dan engkau hanyalah manusia seperti kami, dan sesungguhnya kami yakin engkau termasuk orang-orang yang berdusta"},{id:187,text:"\u0641\u064e\u0623\u064e\u0633\u06e1\u0642\u0650\u0637\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0643\u0650\u0633\u064e\u0641\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Maka jatuhkanlah kepada kami gumpalan dari langit, jika engkau termasuk orang-orang yang benar"},{id:188,text:"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650\u064a\u0653 \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dia (Syu'aib) berkata, \"Tuhanku lebih mengetahui apa yang kamu kerjakan"},{id:189,text:"\u0641\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0647\u064f \u0641\u064e\u0623\u064e\u062e\u064e\u0630\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064f \u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u0638\u0651\u064f\u0644\u0651\u064e\u0629\u0650\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u064a\u064e\u0648\u06e1\u0645\u064d \u0639\u064e\u0638\u0650\u064a\u0645\u064d",translation:"Kemudian mereka mendustakannya (Syu'aib), lalu mereka ditimpa azab pada hari yang gelap. Sungguh, itulah azab pada hari yang dahsyat"},{id:190,text:"\u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0623\u0653\u064a\u064e\u0629\u0657\u06d6 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064f\u0647\u064f\u0645 \u0645\u0651\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Sungguh, pada yang demikian itu benar-benar terdapat tanda (kekuasaan Allah), tetapi kebanyakan mereka tidak beriman"},{id:191,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0644\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0671\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",translation:"Dan sungguh, Tuhanmu, Dialah yang Mahaperkasa, Maha Penyayang"},{id:192,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u062a\u064e\u0646\u0632\u0650\u064a\u0644\u064f \u0631\u064e\u0628\u0651\u0650 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Dan sungguh, (Alquran) ini benar-benar diturunkan oleh Tuhan seluruh alam"},{id:193,text:"\u0646\u064e\u0632\u064e\u0644\u064e \u0628\u0650\u0647\u0650 \u0671\u0644\u0631\u0651\u064f\u0648\u062d\u064f \u0671\u0644\u06e1\u0623\u064e\u0645\u0650\u064a\u0646\u064f",translation:"Yang dibawa turun oleh Ar-R\u016b\u1e25 Al-Am\u012bn (Jibril)"},{id:194,text:"\u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064e\u0644\u06e1\u0628\u0650\u0643\u064e \u0644\u0650\u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0646\u0630\u0650\u0631\u0650\u064a\u0646\u064e",translation:"ke dalam hatimu (Muhammad) agar engkau termasuk orang yang memberi peringatan"},{id:195,text:"\u0628\u0650\u0644\u0650\u0633\u064e\u0627\u0646\u064d \u0639\u064e\u0631\u064e\u0628\u0650\u064a\u0651\u0656 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u0656",translation:"dengan bahasa Arab yang jelas"},{id:196,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0641\u0650\u064a \u0632\u064f\u0628\u064f\u0631\u0650 \u0671\u0644\u06e1\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",translation:"Dan sungguh, (Alquran) itu (disebut) dalam kitab-kitab orang yang terdahulu"},{id:197,text:"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0643\u064f\u0646 \u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u0621\u064e\u0627\u064a\u064e\u0629\u064b \u0623\u064e\u0646 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064e\u0647\u064f\u06e5 \u0639\u064f\u0644\u064e\u0645\u064e\u0640\u0670\u0653\u0624\u064f\u0627\u0652 \u0628\u064e\u0646\u0650\u064a\u0653 \u0625\u0650\u0633\u06e1\u0631\u064e\u0640\u0670\u0653\u0621\u0650\u064a\u0644\u064e",translation:"Apakah tidak (cukup) menjadi bukti bagi mereka, bahwa para ulama Bani Israil mengetahuinya"},{id:198,text:"\u0648\u064e\u0644\u064e\u0648\u06e1 \u0646\u064e\u0632\u0651\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u06e1\u0636\u0650 \u0671\u0644\u06e1\u0623\u064e\u0639\u06e1\u062c\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Dan seandainya (Alquran) itu Kami turunkan kepada sebagian dari golongan bukan Arab"},{id:199,text:"\u0641\u064e\u0642\u064e\u0631\u064e\u0623\u064e\u0647\u064f\u06e5 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6 \u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"lalu dia membacakannya kepada mereka (orang-orang kafir); niscaya mereka tidak juga akan beriman kepadanya"},{id:200,text:"\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0633\u064e\u0644\u064e\u0643\u06e1\u0646\u064e\u0670\u0647\u064f \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650 \u0671\u0644\u06e1\u0645\u064f\u062c\u06e1\u0631\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Demikianlah, Kami masukkan (sifat dusta dan ingkar) ke dalam hati orang-orang yang berdosa"},{id:201,text:"\u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u0650\u06e6 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0631\u064e\u0648\u064f\u0627\u0652 \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0671\u0644\u06e1\u0623\u064e\u0644\u0650\u064a\u0645\u064e",translation:"mereka tidak akan beriman kepadanya, hingga mereka melihat azab yang pedih"},{id:202,text:"\u0641\u064e\u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e\u0647\u064f\u0645 \u0628\u064e\u063a\u06e1\u062a\u064e\u0629\u0657 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0634\u06e1\u0639\u064f\u0631\u064f\u0648\u0646\u064e",translation:"maka datang azab kepada mereka secara mendadak, ketika mereka tidak menyadarinya"},{id:203,text:"\u0641\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627\u0652 \u0647\u064e\u0644\u06e1 \u0646\u064e\u062d\u06e1\u0646\u064f \u0645\u064f\u0646\u0638\u064e\u0631\u064f\u0648\u0646\u064e",translation:"lalu mereka berkata, \"Apakah kami diberi penangguhan waktu"},{id:204,text:"\u0623\u064e\u0641\u064e\u0628\u0650\u0639\u064e\u0630\u064e\u0627\u0628\u0650\u0646\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0639\u06e1\u062c\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Bukankah mereka yang meminta agar azab Kami dipercepat"},{id:205,text:"\u0623\u064e\u0641\u064e\u0631\u064e\u0621\u064e\u064a\u06e1\u062a\u064e \u0625\u0650\u0646 \u0645\u0651\u064e\u062a\u0651\u064e\u0639\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0633\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Maka bagaimana pendapatmu jika kepada mereka Kami berikan kenikmatan hidup beberapa tahun"},{id:206,text:"\u062b\u064f\u0645\u0651\u064e \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064f\u0648\u0639\u064e\u062f\u064f\u0648\u0646\u064e",translation:"kemudian datang kepada mereka azab yang diancamkan kepada mereka"},{id:207,text:"\u0645\u064e\u0627\u0653 \u0623\u064e\u063a\u06e1\u0646\u064e\u0649\u0670 \u0639\u064e\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064f\u0645\u064e\u062a\u0651\u064e\u0639\u064f\u0648\u0646\u064e",translation:"niscaya tidak berguna bagi mereka kenikmatan yang mereka rasakan"},{id:208,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0647\u06e1\u0644\u064e\u0643\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646 \u0642\u064e\u0631\u06e1\u064a\u064e\u0629\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0644\u064e\u0647\u064e\u0627 \u0645\u064f\u0646\u0630\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Dan Kami tidak membinasakan suatu negeri, kecuali setelah ada orang-orang yang memberi peringatan kepadanya"},{id:209,text:"\u0630\u0650\u0643\u06e1\u0631\u064e\u0649\u0670 \u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0638\u064e\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"untuk (menjadi) peringatan. Dan Kami tidak berlaku zalim"},{id:210,text:"\u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0646\u064e\u0632\u0651\u064e\u0644\u064e\u062a\u06e1 \u0628\u0650\u0647\u0650 \u0671\u0644\u0634\u0651\u064e\u064a\u064e\u0670\u0637\u0650\u064a\u0646\u064f",translation:"Dan (Alquran) itu tidaklah dibawa turun oleh setan-setan"},{id:211,text:"\u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0646\u06e2\u0628\u064e\u063a\u0650\u064a \u0644\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u064e",translation:"Dan tidaklah pantas bagi mereka (Alquran itu), dan mereka pun tidak akan sanggup"},{id:212,text:"\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0646\u0650 \u0671\u0644\u0633\u0651\u064e\u0645\u06e1\u0639\u0650 \u0644\u064e\u0645\u064e\u0639\u06e1\u0632\u064f\u0648\u0644\u064f\u0648\u0646\u064e",translation:"Sesungguhnya untuk mendengarkannya pun mereka dijauhkan"},{id:213,text:"\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062f\u06e1\u0639\u064f \u0645\u064e\u0639\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u064e\u0670\u0647\u064b\u0627 \u0621\u064e\u0627\u062e\u064e\u0631\u064e \u0641\u064e\u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0639\u064e\u0630\u0651\u064e\u0628\u0650\u064a\u0646\u064e",translation:"Maka janganlah kamu menyeru (menyembah) tuhan selain Allah, nanti kamu termasuk orang-orang yang di azab"},{id:214,text:"\u0648\u064e\u0623\u064e\u0646\u0630\u0650\u0631\u06e1 \u0639\u064e\u0634\u0650\u064a\u0631\u064e\u062a\u064e\u0643\u064e \u0671\u0644\u06e1\u0623\u064e\u0642\u06e1\u0631\u064e\u0628\u0650\u064a\u0646\u064e",translation:"Dan berilah peringatan kepada kerabat-kerabatmu (Muhammad) yang terdekat"},{id:215,text:"\u0648\u064e\u0671\u062e\u06e1\u0641\u0650\u0636\u06e1 \u062c\u064e\u0646\u064e\u0627\u062d\u064e\u0643\u064e \u0644\u0650\u0645\u064e\u0646\u0650 \u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"dan rendahkanlah dirimu terhadap orang-orang yang beriman yang mengikutimu"},{id:216,text:"\u0641\u064e\u0625\u0650\u0646\u06e1 \u0639\u064e\u0635\u064e\u0648\u06e1\u0643\u064e \u0641\u064e\u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u0650\u064a \u0628\u064e\u0631\u0650\u064a\u0653\u0621\u065e \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Kemudian jika mereka mendurhakaimu maka katakanlah (Muhammad), \"Sesungguhnya aku tidak bertanggung jawab terhadap apa yang kamu kerjakan"},{id:217,text:"\u0648\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u06e1 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u0650 \u0671\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650",translation:"Dan bertawakallah kepada (Allah) Yang Mahaperkasa, Maha penyayang"},{id:218,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064e\u0631\u064e\u0649\u0670\u0643\u064e \u062d\u0650\u064a\u0646\u064e \u062a\u064e\u0642\u064f\u0648\u0645\u064f",translation:"Yang melihat engkau ketika engkau berdiri (untuk salat)"},{id:219,text:"\u0648\u064e\u062a\u064e\u0642\u064e\u0644\u0651\u064f\u0628\u064e\u0643\u064e \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0640\u0670\u062c\u0650\u062f\u0650\u064a\u0646\u064e",translation:"dan (melihat) perubahan gerakan badanmu di antara orang-orang yang sujud"},{id:220,text:"\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0647\u064f\u0648\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u0650\u064a\u0639\u064f \u0671\u0644\u06e1\u0639\u064e\u0644\u0650\u064a\u0645\u064f",translation:"Sungguh, Dia Maha Mendengar, Maha Mengetahui"},{id:221,text:"\u0647\u064e\u0644\u06e1 \u0623\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0643\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0646 \u062a\u064e\u0646\u064e\u0632\u0651\u064e\u0644\u064f \u0671\u0644\u0634\u0651\u064e\u064a\u064e\u0670\u0637\u0650\u064a\u0646\u064f",translation:"Maukah Aku beritakan kepadamu, kepada siapa setan-setan itu turun"},{id:222,text:"\u062a\u064e\u0646\u064e\u0632\u0651\u064e\u0644\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0623\u064e\u0641\u0651\u064e\u0627\u0643\u064d \u0623\u064e\u062b\u0650\u064a\u0645\u0656",translation:"Mereka (setan) turun kepada setiap pendusta yang banyak berdosa"},{id:223,text:"\u064a\u064f\u0644\u06e1\u0642\u064f\u0648\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u06e1\u0639\u064e \u0648\u064e\u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064f\u0647\u064f\u0645\u06e1 \u0643\u064e\u0670\u0630\u0650\u0628\u064f\u0648\u0646\u064e",translation:"mereka menyampaikan hasil pendengaran mereka, sedangkan kebanyakan mereka orang-orang pendusta"},{id:224,text:"\u0648\u064e\u0671\u0644\u0634\u0651\u064f\u0639\u064e\u0631\u064e\u0627\u0653\u0621\u064f \u064a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u063a\u064e\u0627\u0648\u064f\u06e5\u0646\u064e",translation:"Dan penyair-penyair itu diikuti oleh orang-orang yang sesat"},{id:225,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0631\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0643\u064f\u0644\u0651\u0650 \u0648\u064e\u0627\u062f\u0656 \u064a\u064e\u0647\u0650\u064a\u0645\u064f\u0648\u0646\u064e",translation:"Tidakkah engkau melihat bahwa mereka mengembara di setiap lembah"},{id:226,text:"\u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0641\u06e1\u0639\u064e\u0644\u064f\u0648\u0646\u064e",translation:"dan bahwa mereka mengatakan apa yang mereka sendiri tidak mengerjakan(nya)"},{id:227,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0648\u064e\u0630\u064e\u0643\u064e\u0631\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u0657\u0627 \u0648\u064e\u0671\u0646\u062a\u064e\u0635\u064e\u0631\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0645\u064e\u0627 \u0638\u064f\u0644\u0650\u0645\u064f\u0648\u0627\u0652\u06d7 \u0648\u064e\u0633\u064e\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u064a\u0651\u064e \u0645\u064f\u0646\u0642\u064e\u0644\u064e\u0628\u0656 \u064a\u064e\u0646\u0642\u064e\u0644\u0650\u0628\u064f\u0648\u0646\u064e",translation:"kecuali orang-orang (penyair-penyair) yang beriman dan berbuat kebajikan dan banyak mengingat Allah dan mendapat kemenangan setelah terzalimi (karena menjawab puisi-puisi orang-orang kafir). Dan orang-orang yang zalim kelak akan tahu ke tempat mana mereka akan kembali"}]},{id:27,name:"\u0627\u0644\u0646\u0645\u0644",transliteration:"An-Naml",translation:"Semut",type:"meccan",total_verses:93,verses:[{id:1,text:"\u0637\u0633\u0653\u06da \u062a\u0650\u0644\u06e1\u0643\u064e \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u064f \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u0650 \u0648\u064e\u0643\u0650\u062a\u064e\u0627\u0628\u0656 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u064d",translation:"\u1e6c\u0101 S\u012bn. Inilah ayat-ayat Alquran, dan Kitab yang jelas"},{id:2,text:"\u0647\u064f\u062f\u0657\u0649 \u0648\u064e\u0628\u064f\u0634\u06e1\u0631\u064e\u0649\u0670 \u0644\u0650\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"petunjuk dan berita gembira bagi orang-orang yang beriman"},{id:3,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0642\u0650\u064a\u0645\u064f\u0648\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u064a\u064f\u0624\u06e1\u062a\u064f\u0648\u0646\u064e \u0671\u0644\u0632\u0651\u064e\u0643\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0647\u064f\u0645\u06e1 \u064a\u064f\u0648\u0642\u0650\u0646\u064f\u0648\u0646\u064e",translation:"(yaitu) orang-orang yang melaksanakan salat dan menunaikan zakat, dan mereka meyakini adanya akhirat"},{id:4,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0632\u064e\u064a\u0651\u064e\u0646\u0651\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u0639\u06e1\u0645\u064e\u0670\u0644\u064e\u0647\u064f\u0645\u06e1 \u0641\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0639\u06e1\u0645\u064e\u0647\u064f\u0648\u0646\u064e",translation:"Sesungguhnya orang-orang yang tidak beriman kepada akhirat, Kami jadikan terasa indah bagi mereka (yang buruk), sehingga mereka bergelimang dalam kesesatan"},{id:5,text:"\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0633\u064f\u0648\u0653\u0621\u064f \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u062e\u06e1\u0633\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Mereka itulah orang-orang yang mendapat siksaan buruk (di dunia) dan mereka di akhirat adalah orang-orang yang paling rugi"},{id:6,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u062a\u064f\u0644\u064e\u0642\u0651\u064e\u0649 \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u064e \u0645\u0650\u0646 \u0644\u0651\u064e\u062f\u064f\u0646\u06e1 \u062d\u064e\u0643\u0650\u064a\u0645\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u064d",translation:"Dan sesungguhnya engkau (Muhammad) benar-benar telah diberi Alquran dari sisi (Allah) Yang Mahabijaksana, Maha Mengetahui"},{id:7,text:"\u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0644\u0650\u0623\u064e\u0647\u06e1\u0644\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0621\u064e\u0627\u0646\u064e\u0633\u06e1\u062a\u064f \u0646\u064e\u0627\u0631\u0657\u0627 \u0633\u064e\u0640\u0654\u064e\u0627\u062a\u0650\u064a\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1\u0647\u064e\u0627 \u0628\u0650\u062e\u064e\u0628\u064e\u0631\u064d \u0623\u064e\u0648\u06e1 \u0621\u064e\u0627\u062a\u0650\u064a\u0643\u064f\u0645 \u0628\u0650\u0634\u0650\u0647\u064e\u0627\u0628\u0656 \u0642\u064e\u0628\u064e\u0633\u0656 \u0644\u0651\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u0635\u06e1\u0637\u064e\u0644\u064f\u0648\u0646\u064e",translation:"(Ingatlah) ketika Musa berkata kepada keluarganya, \"Sungguh, aku melihat api. Aku akan membawa kabar tentang itu kepadamu, atau aku akan membawa suluh api (obor) kepadamu agar kamu dapat berdiang (menghangatkan badan dekat api)"},{id:8,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064e\u0627 \u0646\u064f\u0648\u062f\u0650\u064a\u064e \u0623\u064e\u0646\u06e2 \u0628\u064f\u0648\u0631\u0650\u0643\u064e \u0645\u064e\u0646 \u0641\u0650\u064a \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0648\u064e\u0645\u064e\u0646\u06e1 \u062d\u064e\u0648\u06e1\u0644\u064e\u0647\u064e\u0627 \u0648\u064e\u0633\u064f\u0628\u06e1\u062d\u064e\u0670\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0631\u064e\u0628\u0651\u0650 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Maka ketika dia tiba di sana (tempat api itu), dia diseru, \"Telah diberkahi orang-orang yang berada di dekat api, dan orang-orang yang berada di sekitarnya. Mahasuci Allah, Tuhan seluruh alam"},{id:9,text:"\u064a\u064e\u0670\u0645\u064f\u0648\u0633\u064e\u0649\u0670\u0653 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u0646\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0671\u0644\u06e1\u062d\u064e\u0643\u0650\u064a\u0645\u064f",translation:"(Allah berfirman), \"Wahai Musa! Sesungguhnya Aku adalah Allah, Yang Mahaperkasa, Mahabijaksana"},{id:10,text:"\u0648\u064e\u0623\u064e\u0644\u06e1\u0642\u0650 \u0639\u064e\u0635\u064e\u0627\u0643\u064e\u06da \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0631\u064e\u0621\u064e\u0627\u0647\u064e\u0627 \u062a\u064e\u0647\u06e1\u062a\u064e\u0632\u0651\u064f \u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064e\u0627 \u062c\u064e\u0627\u0653\u0646\u0651\u065e \u0648\u064e\u0644\u0651\u064e\u0649\u0670 \u0645\u064f\u062f\u06e1\u0628\u0650\u0631\u0657\u0627 \u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064f\u0639\u064e\u0642\u0651\u0650\u0628\u06e1\u06da \u064a\u064e\u0670\u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0644\u064e\u0627 \u062a\u064e\u062e\u064e\u0641\u06e1 \u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0627 \u064a\u064e\u062e\u064e\u0627\u0641\u064f \u0644\u064e\u062f\u064e\u064a\u0651\u064e \u0671\u0644\u06e1\u0645\u064f\u0631\u06e1\u0633\u064e\u0644\u064f\u0648\u0646\u064e",translation:"dan lemparkanlah tongkatmu!\" Maka ketika (tongkat itu menjadi ular dan) Musa melihatnya bergerak-gerak seperti seekor ular yang gesit, larilah dia berbalik ke belakang tanpa menoleh. \"Wahai Musa! Jangan takut! Sesungguhnya dihadapan-Ku para rasul tidak perlu takut"},{id:11,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646 \u0638\u064e\u0644\u064e\u0645\u064e \u062b\u064f\u0645\u0651\u064e \u0628\u064e\u062f\u0651\u064e\u0644\u064e \u062d\u064f\u0633\u06e1\u0646\u064e\u06e2\u0627 \u0628\u064e\u0639\u06e1\u062f\u064e \u0633\u064f\u0648\u0653\u0621\u0656 \u0641\u064e\u0625\u0650\u0646\u0651\u0650\u064a \u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u065e",translation:"kecuali orang yang berlaku zalim yang kemudian mengubah (dirinya) dengan kebaikan setelah kejahatan (bertobat); maka sungguh, Aku Maha Pengampun, Maha Penyayang"},{id:12,text:"\u0648\u064e\u0623\u064e\u062f\u06e1\u062e\u0650\u0644\u06e1 \u064a\u064e\u062f\u064e\u0643\u064e \u0641\u0650\u064a \u062c\u064e\u064a\u06e1\u0628\u0650\u0643\u064e \u062a\u064e\u062e\u06e1\u0631\u064f\u062c\u06e1 \u0628\u064e\u064a\u06e1\u0636\u064e\u0627\u0653\u0621\u064e \u0645\u0650\u0646\u06e1 \u063a\u064e\u064a\u06e1\u0631\u0650 \u0633\u064f\u0648\u0653\u0621\u0656\u06d6 \u0641\u0650\u064a \u062a\u0650\u0633\u06e1\u0639\u0650 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u064d \u0625\u0650\u0644\u064e\u0649\u0670 \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0648\u064e\u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u06e6\u0653\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0642\u064e\u0648\u06e1\u0645\u0657\u0627 \u0641\u064e\u0670\u0633\u0650\u0642\u0650\u064a\u0646\u064e",translation:"(Dan masukkanlah tanganmu ke leher bajumu,592) niscaya ia akan ke luar menjadi putih (bersinar) tanpa cacat. (Kedua mukjizat ini) termasuk sembilan macam mukjizat (yang akan dikemukakan) kepada Fir'aun dan kaumnya. Mereka benar-benar orang-orang yang fasik"},{id:13,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u062a\u06e1\u0647\u064f\u0645\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u064f\u0646\u064e\u0627 \u0645\u064f\u0628\u06e1\u0635\u0650\u0631\u064e\u0629\u0657 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0647\u064e\u0670\u0630\u064e\u0627 \u0633\u0650\u062d\u06e1\u0631\u065e \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u065e",translation:"Maka ketika mukjizat-mukjizat Kami yang terang itu sampai kepada mereka, mereka berkata, \"Ini sihir yang nyata"},{id:14,text:"\u0648\u064e\u062c\u064e\u062d\u064e\u062f\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u064e\u0627 \u0648\u064e\u0671\u0633\u06e1\u062a\u064e\u064a\u06e1\u0642\u064e\u0646\u064e\u062a\u06e1\u0647\u064e\u0627\u0653 \u0623\u064e\u0646\u0641\u064f\u0633\u064f\u0647\u064f\u0645\u06e1 \u0638\u064f\u0644\u06e1\u0645\u0657\u0627 \u0648\u064e\u0639\u064f\u0644\u064f\u0648\u0651\u0657\u0627\u06da \u0641\u064e\u0671\u0646\u0638\u064f\u0631\u06e1 \u0643\u064e\u064a\u06e1\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0670\u0642\u0650\u0628\u064e\u0629\u064f \u0671\u0644\u06e1\u0645\u064f\u0641\u06e1\u0633\u0650\u062f\u0650\u064a\u0646\u064e",translation:"Dan mereka mengingkarinya karena kezaliman dan kesombongannya, padahal hati mereka meyakini (kebenaran)nya. Maka perhatikanlah bagaimana kesudahan orang-orang yang berbuat kerusakan"},{id:15,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0627 \u062f\u064e\u0627\u0648\u064f\u06e5\u062f\u064e \u0648\u064e\u0633\u064f\u0644\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u064e \u0639\u0650\u0644\u06e1\u0645\u0657\u0627\u06d6 \u0648\u064e\u0642\u064e\u0627\u0644\u064e\u0627 \u0671\u0644\u06e1\u062d\u064e\u0645\u06e1\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0641\u064e\u0636\u0651\u064e\u0644\u064e\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064e\u062b\u0650\u064a\u0631\u0656 \u0645\u0651\u0650\u0646\u06e1 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dan sungguh, Kami telah memberikan ilmu kepada Dawud dan Sulaiman, dan keduanya berkata, \"Segala puji bagi Allah yang melebihkan kami dari banyak hamba-hamba-Nya yang beriman"},{id:16,text:"\u0648\u064e\u0648\u064e\u0631\u0650\u062b\u064e \u0633\u064f\u0644\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u064f \u062f\u064e\u0627\u0648\u064f\u06e5\u062f\u064e\u06d6 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0639\u064f\u0644\u0651\u0650\u0645\u06e1\u0646\u064e\u0627 \u0645\u064e\u0646\u0637\u0650\u0642\u064e \u0671\u0644\u0637\u0651\u064e\u064a\u06e1\u0631\u0650 \u0648\u064e\u0623\u064f\u0648\u062a\u0650\u064a\u0646\u064e\u0627 \u0645\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u064d\u06d6 \u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0644\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0641\u064e\u0636\u06e1\u0644\u064f \u0671\u0644\u06e1\u0645\u064f\u0628\u0650\u064a\u0646\u064f",translation:"(Dan Sulaiman telah mewarisi Dawud,593) dan dia (Sulaiman) berkata, \"Wahai manusia! Kami telah diajari bahasa burung dan kami diberi segala sesuatu. Sungguh, (semua) ini benar-benar karunia yang nyata"},{id:17,text:"\u0648\u064e\u062d\u064f\u0634\u0650\u0631\u064e \u0644\u0650\u0633\u064f\u0644\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u064e \u062c\u064f\u0646\u064f\u0648\u062f\u064f\u0647\u064f\u06e5 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u062c\u0650\u0646\u0651\u0650 \u0648\u064e\u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u0650 \u0648\u064e\u0671\u0644\u0637\u0651\u064e\u064a\u06e1\u0631\u0650 \u0641\u064e\u0647\u064f\u0645\u06e1 \u064a\u064f\u0648\u0632\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Dan untuk Sulaiman dikumpulkan bala tentaranya dari jin, manusia dan burung, lalu mereka berbaris dengan tertib"},{id:18,text:"\u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u064e\u0627\u0653 \u0623\u064e\u062a\u064e\u0648\u06e1\u0627\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0648\u064e\u0627\u062f\u0650 \u0671\u0644\u0646\u0651\u064e\u0645\u06e1\u0644\u0650 \u0642\u064e\u0627\u0644\u064e\u062a\u06e1 \u0646\u064e\u0645\u06e1\u0644\u064e\u0629\u065e \u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0645\u06e1\u0644\u064f \u0671\u062f\u06e1\u062e\u064f\u0644\u064f\u0648\u0627\u0652 \u0645\u064e\u0633\u064e\u0670\u0643\u0650\u0646\u064e\u0643\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u062d\u06e1\u0637\u0650\u0645\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0633\u064f\u0644\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u064f \u0648\u064e\u062c\u064f\u0646\u064f\u0648\u062f\u064f\u0647\u064f\u06e5 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0634\u06e1\u0639\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Hingga ketika mereka sampai di lembah semut, berkatalah seekor semut, \"Wahai semut-semut! Masuklah ke dalam sarang-sarangmu, agar kamu tidak diinjak oleh Sulaiman dan bala tentaranya, sedangkan mereka tidak menyadari"},{id:19,text:"\u0641\u064e\u062a\u064e\u0628\u064e\u0633\u0651\u064e\u0645\u064e \u0636\u064e\u0627\u062d\u0650\u0643\u0657\u0627 \u0645\u0651\u0650\u0646 \u0642\u064e\u0648\u06e1\u0644\u0650\u0647\u064e\u0627 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0623\u064e\u0648\u06e1\u0632\u0650\u0639\u06e1\u0646\u0650\u064a\u0653 \u0623\u064e\u0646\u06e1 \u0623\u064e\u0634\u06e1\u0643\u064f\u0631\u064e \u0646\u0650\u0639\u06e1\u0645\u064e\u062a\u064e\u0643\u064e \u0671\u0644\u0651\u064e\u062a\u0650\u064a\u0653 \u0623\u064e\u0646\u06e1\u0639\u064e\u0645\u06e1\u062a\u064e \u0639\u064e\u0644\u064e\u064a\u0651\u064e \u0648\u064e\u0639\u064e\u0644\u064e\u0649\u0670 \u0648\u064e\u0670\u0644\u0650\u062f\u064e\u064a\u0651\u064e \u0648\u064e\u0623\u064e\u0646\u06e1 \u0623\u064e\u0639\u06e1\u0645\u064e\u0644\u064e \u0635\u064e\u0670\u0644\u0650\u062d\u0657\u0627 \u062a\u064e\u0631\u06e1\u0636\u064e\u0649\u0670\u0647\u064f \u0648\u064e\u0623\u064e\u062f\u06e1\u062e\u0650\u0644\u06e1\u0646\u0650\u064a \u0628\u0650\u0631\u064e\u062d\u06e1\u0645\u064e\u062a\u0650\u0643\u064e \u0641\u0650\u064a \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0643\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u0650\u064a\u0646\u064e",translation:"Maka dia (Sulaiman) tersenyum lalu tertawa karena (mendengar) perkataan semut itu. Dan dia berdoa, \"Ya Tuhanku, anugerahkanlah aku ilham untuk tetap mensyukuri nikmat-Mu yang telah Engkau anugerahkan kepadaku dan kepada kedua orang tuaku dan agar aku mengerjakan kebajikan yang Engkau ridai; dan masukkanlah aku dengan rahmat-Mu ke dalam golongan hamba-hamba-Mu yang saleh"},{id:20,text:"\u0648\u064e\u062a\u064e\u0641\u064e\u0642\u0651\u064e\u062f\u064e \u0671\u0644\u0637\u0651\u064e\u064a\u06e1\u0631\u064e \u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0645\u064e\u0627\u0644\u0650\u064a\u064e \u0644\u064e\u0627\u0653 \u0623\u064e\u0631\u064e\u0649 \u0671\u0644\u06e1\u0647\u064f\u062f\u06e1\u0647\u064f\u062f\u064e \u0623\u064e\u0645\u06e1 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u063a\u064e\u0627\u0653\u0626\u0650\u0628\u0650\u064a\u0646\u064e",translation:"(Dan dia memeriksa burung-burung lalu berkata, \"Mengapa aku tidak melihat Hud-hud,594) apakah ia termasuk yang absen (tidak hadir)"},{id:21,text:"\u0644\u064e\u0623\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064e\u0646\u0651\u064e\u0647\u064f\u06e5 \u0639\u064e\u0630\u064e\u0627\u0628\u0657\u0627 \u0634\u064e\u062f\u0650\u064a\u062f\u064b\u0627 \u0623\u064e\u0648\u06e1 \u0644\u064e\u0623\u064e\u0627\u0652\u0630\u06e1\u0628\u064e\u062d\u064e\u0646\u0651\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u0648\u06e1 \u0644\u064e\u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e\u0646\u0651\u0650\u064a \u0628\u0650\u0633\u064f\u0644\u06e1\u0637\u064e\u0670\u0646\u0656 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u0656",translation:"Pasti akan ku hukum ia dengan hukuman yang berat atau ku sembelih ia, kecuali jika ia datang kepadaku dengan alasan yang jelas"},{id:22,text:"\u0641\u064e\u0645\u064e\u0643\u064e\u062b\u064e \u063a\u064e\u064a\u06e1\u0631\u064e \u0628\u064e\u0639\u0650\u064a\u062f\u0656 \u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u062d\u064e\u0637\u062a\u064f \u0628\u0650\u0645\u064e\u0627 \u0644\u064e\u0645\u06e1 \u062a\u064f\u062d\u0650\u0637\u06e1 \u0628\u0650\u0647\u0650\u06e6 \u0648\u064e\u062c\u0650\u0626\u06e1\u062a\u064f\u0643\u064e \u0645\u0650\u0646 \u0633\u064e\u0628\u064e\u0625\u0650\u06ed \u0628\u0650\u0646\u064e\u0628\u064e\u0625\u0656 \u064a\u064e\u0642\u0650\u064a\u0646\u064d",translation:"Maka tidak lama kemudian (datanglah Hud-hud), lalu ia berkata, \"Aku telah mengetahui sesuatu yang belum engkau ketahui. Aku datang kepadamu dari negeri Saba`595) membawa suatu berita yang meyakinkan"},{id:23,text:"\u0625\u0650\u0646\u0651\u0650\u064a \u0648\u064e\u062c\u064e\u062f\u062a\u0651\u064f \u0671\u0645\u06e1\u0631\u064e\u0623\u064e\u0629\u0657 \u062a\u064e\u0645\u06e1\u0644\u0650\u0643\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0623\u064f\u0648\u062a\u0650\u064a\u064e\u062a\u06e1 \u0645\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0648\u064e\u0644\u064e\u0647\u064e\u0627 \u0639\u064e\u0631\u06e1\u0634\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u065e",translation:"(Sungguh, ku dapati ada seorang perempuan596) yang memerintah mereka, dan dia dianugerahi segala sesuatu serta memiliki singgasana yang besar"},{id:24,text:"\u0648\u064e\u062c\u064e\u062f\u062a\u0651\u064f\u0647\u064e\u0627 \u0648\u064e\u0642\u064e\u0648\u06e1\u0645\u064e\u0647\u064e\u0627 \u064a\u064e\u0633\u06e1\u062c\u064f\u062f\u064f\u0648\u0646\u064e \u0644\u0650\u0644\u0634\u0651\u064e\u0645\u06e1\u0633\u0650 \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0632\u064e\u064a\u0651\u064e\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u064f \u0623\u064e\u0639\u06e1\u0645\u064e\u0670\u0644\u064e\u0647\u064f\u0645\u06e1 \u0641\u064e\u0635\u064e\u062f\u0651\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0646\u0650 \u0671\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u0650 \u0641\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0647\u06e1\u062a\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Aku (burung Hud) dapati dia dan kaumnya menyembah matahari, bukan kepada Allah; dan setan telah menjadikan tampak indah bagi mereka perbuatan-perbuatan (buruk) mereka, sehingga menghalangi mereka dari jalan (Allah), maka mereka tidak mendapat petunjuk"},{id:25,text:"\u0623\u064e\u0644\u0651\u064e\u0627\u06e4 \u064a\u064e\u0633\u06e1\u062c\u064f\u062f\u064f\u0648\u0627\u0652\u06e4 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u062e\u06e1\u0631\u0650\u062c\u064f \u0671\u0644\u06e1\u062e\u064e\u0628\u06e1\u0621\u064e \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u062a\u064f\u062e\u06e1\u0641\u064f\u0648\u0646\u064e \u0648\u064e\u0645\u064e\u0627 \u062a\u064f\u0639\u06e1\u0644\u0650\u0646\u064f\u0648\u0646\u064e",translation:"mereka (juga) tidak menyembah Allah yang mengeluarkan apa yang terpendam di langit dan di bumi597) dan yang mengetahui apa yang kamu sembunyikan dan yang kamu tampakkan"},{id:26,text:"\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u0631\u064e\u0628\u0651\u064f \u0671\u0644\u06e1\u0639\u064e\u0631\u06e1\u0634\u0650 \u0671\u0644\u06e1\u0639\u064e\u0638\u0650\u064a\u0645\u0650\u06e9",translation:"Allah, tidak ada tuhan melainkan Dia, Tuhan Yang mempunyai Arasy yang agung"},{id:27,text:"\u06de\u0642\u064e\u0627\u0644\u064e \u0633\u064e\u0646\u064e\u0646\u0638\u064f\u0631\u064f \u0623\u064e\u0635\u064e\u062f\u064e\u0642\u06e1\u062a\u064e \u0623\u064e\u0645\u06e1 \u0643\u064f\u0646\u062a\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0643\u064e\u0670\u0630\u0650\u0628\u0650\u064a\u0646\u064e",translation:"Dia (Sulaiman) berkata, \"Akan kami lihat, apa kamu benar, atau termasuk yang berdusta"},{id:28,text:"\u0671\u0630\u06e1\u0647\u064e\u0628 \u0628\u0651\u0650\u0643\u0650\u062a\u064e\u0670\u0628\u0650\u064a \u0647\u064e\u0670\u0630\u064e\u0627 \u0641\u064e\u0623\u064e\u0644\u06e1\u0642\u0650\u0647\u06e1 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u062b\u064f\u0645\u0651\u064e \u062a\u064e\u0648\u064e\u0644\u0651\u064e \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0641\u064e\u0671\u0646\u0638\u064f\u0631\u06e1 \u0645\u064e\u0627\u0630\u064e\u0627 \u064a\u064e\u0631\u06e1\u062c\u0650\u0639\u064f\u0648\u0646\u064e",translation:"Pergilah dengan (membawa) suratku ini, lalu jatuhkanlah kepada mereka, kemudian berpalinglah dari mereka, lalu perhatikanlah apa yang mereka bicarakan"},{id:29,text:"\u0642\u064e\u0627\u0644\u064e\u062a\u06e1 \u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0624\u064f\u0627\u0652 \u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064f\u0644\u06e1\u0642\u0650\u064a\u064e \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0643\u0650\u062a\u064e\u0670\u0628\u065e \u0643\u064e\u0631\u0650\u064a\u0645\u064c",translation:"Dia (Balqis) berkata, \"Wahai para pembesar! Sesungguhnya telah disampaikan kepadaku sepucuk surat yang mulia"},{id:30,text:"\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646 \u0633\u064f\u0644\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u064e \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0628\u0650\u0633\u06e1\u0645\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u0650 \u0671\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650",translation:"Sesungguhnya (surat) itu dari Sulaiman yang isinya, \"Dengan nama Allah Yang Maha Pengasih, Maha Penyayang"},{id:31,text:"\u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064e\u0639\u06e1\u0644\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u064a\u0651\u064e \u0648\u064e\u0623\u06e1\u062a\u064f\u0648\u0646\u0650\u064a \u0645\u064f\u0633\u06e1\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"janganlah engkau berlaku sombong terhadapku dan datanglah kepadaku sebagai orang-orang yang berserah diri"},{id:32,text:"\u0642\u064e\u0627\u0644\u064e\u062a\u06e1 \u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0624\u064f\u0627\u0652 \u0623\u064e\u0641\u06e1\u062a\u064f\u0648\u0646\u0650\u064a \u0641\u0650\u064a\u0653 \u0623\u064e\u0645\u06e1\u0631\u0650\u064a \u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f \u0642\u064e\u0627\u0637\u0650\u0639\u064e\u0629\u064b \u0623\u064e\u0645\u06e1\u0631\u064b\u0627 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062a\u064e\u0634\u06e1\u0647\u064e\u062f\u064f\u0648\u0646\u0650",translation:"Dia (Balqis) berkata, \"Wahai para pembesar! Berilah aku pertimbangan dalam perkaraku (ini). Aku tidak pernah memutuskan suatu perkara sebelum kamu hadir dalam majelis(ku)"},{id:33,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0646\u064e\u062d\u06e1\u0646\u064f \u0623\u064f\u0648\u0652\u0644\u064f\u0648\u0627\u0652 \u0642\u064f\u0648\u0651\u064e\u0629\u0656 \u0648\u064e\u0623\u064f\u0648\u0652\u0644\u064f\u0648\u0627\u0652 \u0628\u064e\u0623\u06e1\u0633\u0656 \u0634\u064e\u062f\u0650\u064a\u062f\u0656 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0631\u064f \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u0650 \u0641\u064e\u0671\u0646\u0638\u064f\u0631\u0650\u064a \u0645\u064e\u0627\u0630\u064e\u0627 \u062a\u064e\u0623\u06e1\u0645\u064f\u0631\u0650\u064a\u0646\u064e",translation:"Mereka menjawab, \"Kita memiliki kekuatan dan keberanian yang luar biasa (untuk berperang), tetapi keputusan berada di tanganmu; maka pertimbangankanlah apa yang akan engkau perintahkan"},{id:34,text:"\u0642\u064e\u0627\u0644\u064e\u062a\u06e1 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0645\u064f\u0644\u064f\u0648\u0643\u064e \u0625\u0650\u0630\u064e\u0627 \u062f\u064e\u062e\u064e\u0644\u064f\u0648\u0627\u0652 \u0642\u064e\u0631\u06e1\u064a\u064e\u0629\u064b \u0623\u064e\u0641\u06e1\u0633\u064e\u062f\u064f\u0648\u0647\u064e\u0627 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0639\u0650\u0632\u0651\u064e\u0629\u064e \u0623\u064e\u0647\u06e1\u0644\u0650\u0647\u064e\u0627\u0653 \u0623\u064e\u0630\u0650\u0644\u0651\u064e\u0629\u0657\u06da \u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064e\u0641\u06e1\u0639\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dia (Balqis) berkata, \"Sesungguhnya raja-raja apabila menaklukkan suatu negeri, mereka tentu membinasakannya, dan menjadikan penduduknya yang mulia jadi hina; dan demikian yang akan mereka perbuat"},{id:35,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u0650\u064a \u0645\u064f\u0631\u06e1\u0633\u0650\u0644\u064e\u0629\u064c \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0628\u0650\u0647\u064e\u062f\u0650\u064a\u0651\u064e\u0629\u0656 \u0641\u064e\u0646\u064e\u0627\u0638\u0650\u0631\u064e\u0629\u064f\u06e2 \u0628\u0650\u0645\u064e \u064a\u064e\u0631\u06e1\u062c\u0650\u0639\u064f \u0671\u0644\u06e1\u0645\u064f\u0631\u06e1\u0633\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan sungguh, aku akan mengirim utusan kepada mereka dengan (membawa) hadiah, dan (aku) akan menunggu apa yang akan dibawa kembali oleh para utusan itu"},{id:36,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e \u0633\u064f\u0644\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u064e \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u062a\u064f\u0645\u0650\u062f\u0651\u064f\u0648\u0646\u064e\u0646\u0650 \u0628\u0650\u0645\u064e\u0627\u0644\u0656 \u0641\u064e\u0645\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u064e\u0649\u0670\u0646\u0650\u06e6\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u062e\u064e\u064a\u06e1\u0631\u065e \u0645\u0651\u0650\u0645\u0651\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u064e\u0649\u0670\u0643\u064f\u0645\u06da \u0628\u064e\u0644\u06e1 \u0623\u064e\u0646\u062a\u064f\u0645 \u0628\u0650\u0647\u064e\u062f\u0650\u064a\u0651\u064e\u062a\u0650\u0643\u064f\u0645\u06e1 \u062a\u064e\u0641\u06e1\u0631\u064e\u062d\u064f\u0648\u0646\u064e",translation:"Maka ketika para (utusan itu) sampai kepada Sulaiman, dia (Sulaiman) berkata, \"Apakah kamu akan memberi harta kepadaku? Apa yang Allah berikan kepadaku lebih baik daripada apa yang Allah berikan kepadamu; tetapi kamu merasa bangga dengan hadiahmu"},{id:37,text:"\u0671\u0631\u06e1\u062c\u0650\u0639\u06e1 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0641\u064e\u0644\u064e\u0646\u064e\u0623\u06e1\u062a\u0650\u064a\u064e\u0646\u0651\u064e\u0647\u064f\u0645 \u0628\u0650\u062c\u064f\u0646\u064f\u0648\u062f\u0656 \u0644\u0651\u064e\u0627 \u0642\u0650\u0628\u064e\u0644\u064e \u0644\u064e\u0647\u064f\u0645 \u0628\u0650\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0646\u064f\u062e\u06e1\u0631\u0650\u062c\u064e\u0646\u0651\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1\u0647\u064e\u0627\u0653 \u0623\u064e\u0630\u0650\u0644\u0651\u064e\u0629\u0657 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0635\u064e\u0670\u063a\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Kembalilah kepada mereka! Sungguh, Kami pasti akan mendatangi mereka dengan bala tentara yang mereka tidak mampu melawannya, dan akan kami usir mereka dari negeri itu (Saba`) secara terhina dan mereka akan menjadi (tawanan) yang hina dina"},{id:38,text:"\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0624\u064f\u0627\u0652 \u0623\u064e\u064a\u0651\u064f\u0643\u064f\u0645\u06e1 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u0646\u0650\u064a \u0628\u0650\u0639\u064e\u0631\u06e1\u0634\u0650\u0647\u064e\u0627 \u0642\u064e\u0628\u06e1\u0644\u064e \u0623\u064e\u0646 \u064a\u064e\u0623\u06e1\u062a\u064f\u0648\u0646\u0650\u064a \u0645\u064f\u0633\u06e1\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dia (Sulaiman) berkata, \"Wahai para pembesar! Siapakah di antara kamu yang sanggup membawa singgasananya kepadaku sebelum mereka datang kepadaku menyerahkan diri"},{id:39,text:"\u0642\u064e\u0627\u0644\u064e \u0639\u0650\u0641\u06e1\u0631\u0650\u064a\u062a\u065e \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u062c\u0650\u0646\u0651\u0650 \u0623\u064e\u0646\u064e\u0627\u06e0 \u0621\u064e\u0627\u062a\u0650\u064a\u0643\u064e \u0628\u0650\u0647\u0650\u06e6 \u0642\u064e\u0628\u06e1\u0644\u064e \u0623\u064e\u0646 \u062a\u064e\u0642\u064f\u0648\u0645\u064e \u0645\u0650\u0646 \u0645\u0651\u064e\u0642\u064e\u0627\u0645\u0650\u0643\u064e\u06d6 \u0648\u064e\u0625\u0650\u0646\u0651\u0650\u064a \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0644\u064e\u0642\u064e\u0648\u0650\u064a\u0651\u064c \u0623\u064e\u0645\u0650\u064a\u0646\u065e",translation:"Ifrit dalam golongan jin berkata, \"Akulah yang akan membawanya kepadamu sebelum engkau berdiri dari tempat dudukmu; dan sungguh, aku kuat melakukannya dan dapat dipercaya"},{id:40,text:"\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0639\u0650\u0646\u062f\u064e\u0647\u064f\u06e5 \u0639\u0650\u0644\u06e1\u0645\u065e \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0623\u064e\u0646\u064e\u0627\u06e0 \u0621\u064e\u0627\u062a\u0650\u064a\u0643\u064e \u0628\u0650\u0647\u0650\u06e6 \u0642\u064e\u0628\u06e1\u0644\u064e \u0623\u064e\u0646 \u064a\u064e\u0631\u06e1\u062a\u064e\u062f\u0651\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0637\u064e\u0631\u06e1\u0641\u064f\u0643\u064e\u06da \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0631\u064e\u0621\u064e\u0627\u0647\u064f \u0645\u064f\u0633\u06e1\u062a\u064e\u0642\u0650\u0631\u0651\u064b\u0627 \u0639\u0650\u0646\u062f\u064e\u0647\u064f\u06e5 \u0642\u064e\u0627\u0644\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0645\u0650\u0646 \u0641\u064e\u0636\u06e1\u0644\u0650 \u0631\u064e\u0628\u0651\u0650\u064a \u0644\u0650\u064a\u064e\u0628\u06e1\u0644\u064f\u0648\u064e\u0646\u0650\u064a\u0653 \u0621\u064e\u0623\u064e\u0634\u06e1\u0643\u064f\u0631\u064f \u0623\u064e\u0645\u06e1 \u0623\u064e\u0643\u06e1\u0641\u064f\u0631\u064f\u06d6 \u0648\u064e\u0645\u064e\u0646 \u0634\u064e\u0643\u064e\u0631\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0634\u06e1\u0643\u064f\u0631\u064f \u0644\u0650\u0646\u064e\u0641\u06e1\u0633\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u0645\u064e\u0646 \u0643\u064e\u0641\u064e\u0631\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u063a\u064e\u0646\u0650\u064a\u0651\u065e \u0643\u064e\u0631\u0650\u064a\u0645\u065e",translation:"(Seorang yang mempunyai ilmu dari Kitab598) berkata, \"Aku akan membawa singgasana itu kepadamu sebelum matamu berkedip.\" Maka ketika dia (Sulaiman) melihat singgasana itu terletak di hadapannya, dia pun berkata, \"Ini termasuk karunia Tuhanku untuk mengujiku, apakah aku bersyukur atau mengingkari (nikmat-Nya). Barang siapa bersyukur, maka sesungguhnya dia bersyukur untuk (kebaikan) dirinya sendiri, dan barang siapa ingkar, maka sesungguhnya Tuhanku Mahakaya, Mahamulia"},{id:41,text:"\u0642\u064e\u0627\u0644\u064e \u0646\u064e\u0643\u0651\u0650\u0631\u064f\u0648\u0627\u0652 \u0644\u064e\u0647\u064e\u0627 \u0639\u064e\u0631\u06e1\u0634\u064e\u0647\u064e\u0627 \u0646\u064e\u0646\u0638\u064f\u0631\u06e1 \u0623\u064e\u062a\u064e\u0647\u06e1\u062a\u064e\u062f\u0650\u064a\u0653 \u0623\u064e\u0645\u06e1 \u062a\u064e\u0643\u064f\u0648\u0646\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u0647\u06e1\u062a\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Dia (Sulaiman) berkata, \"Ubahlah untuknya singgasananya; kita akan melihat apakah dia (Balqis) mengenal; atau tidak mengenalnya lagi"},{id:42,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u062a\u06e1 \u0642\u0650\u064a\u0644\u064e \u0623\u064e\u0647\u064e\u0670\u0643\u064e\u0630\u064e\u0627 \u0639\u064e\u0631\u06e1\u0634\u064f\u0643\u0650\u06d6 \u0642\u064e\u0627\u0644\u064e\u062a\u06e1 \u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u06e5 \u0647\u064f\u0648\u064e\u06da \u0648\u064e\u0623\u064f\u0648\u062a\u0650\u064a\u0646\u064e\u0627 \u0671\u0644\u06e1\u0639\u0650\u0644\u06e1\u0645\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u064e\u0627 \u0648\u064e\u0643\u064f\u0646\u0651\u064e\u0627 \u0645\u064f\u0633\u06e1\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Maka ketika dia (Balqis) datang, ditanyakanlah (kepadanya), \"Serupa inikah singgasanamu?\" Dia (Balqis) menjawab, \"Seakan-akan itulah dia.\" (Dan dia Balqis berkata), \"Kami telah diberi pengetahuan sebelumnya599) dan kami adalah orang-orang yang berserah diri (kepada Allah)"},{id:43,text:"\u0648\u064e\u0635\u064e\u062f\u0651\u064e\u0647\u064e\u0627 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e\u062a \u062a\u0651\u064e\u0639\u06e1\u0628\u064f\u062f\u064f \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064e\u0627 \u0643\u064e\u0627\u0646\u064e\u062a\u06e1 \u0645\u0650\u0646 \u0642\u064e\u0648\u06e1\u0645\u0656 \u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan kebiasaannya menyembah selain Allah mencegahnya (untuk menampakkan keislamannya), sesungguhnya dia (Balqis) dahulu termasuk orang-orang kafir"},{id:44,text:"\u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064e\u0627 \u0671\u062f\u06e1\u062e\u064f\u0644\u0650\u064a \u0671\u0644\u0635\u0651\u064e\u0631\u06e1\u062d\u064e\u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0631\u064e\u0623\u064e\u062a\u06e1\u0647\u064f \u062d\u064e\u0633\u0650\u0628\u064e\u062a\u06e1\u0647\u064f \u0644\u064f\u062c\u0651\u064e\u0629\u0657 \u0648\u064e\u0643\u064e\u0634\u064e\u0641\u064e\u062a\u06e1 \u0639\u064e\u0646 \u0633\u064e\u0627\u0642\u064e\u064a\u06e1\u0647\u064e\u0627\u06da \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0635\u064e\u0631\u06e1\u062d\u065e \u0645\u0651\u064f\u0645\u064e\u0631\u0651\u064e\u062f\u065e \u0645\u0651\u0650\u0646 \u0642\u064e\u0648\u064e\u0627\u0631\u0650\u064a\u0631\u064e\u06d7 \u0642\u064e\u0627\u0644\u064e\u062a\u06e1 \u0631\u064e\u0628\u0651\u0650 \u0625\u0650\u0646\u0651\u0650\u064a \u0638\u064e\u0644\u064e\u0645\u06e1\u062a\u064f \u0646\u064e\u0641\u06e1\u0633\u0650\u064a \u0648\u064e\u0623\u064e\u0633\u06e1\u0644\u064e\u0645\u06e1\u062a\u064f \u0645\u064e\u0639\u064e \u0633\u064f\u0644\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0631\u064e\u0628\u0651\u0650 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Dikatakan kepadanya (Balqis), \"Masuklah ke dalam istana.\" Maka ketika dia (Balqis) melihat (lantai istana) itu, dikiranya kolam air yang besar, dan disingkapkannya (penutup) kedua betisnya, Dia (Sulaiman) berkata, \"Sesungguhnya ini hanyalah lantai istana yang dilapisi kaca.\" Dia (Balqis) berkata, \"Ya Tuhanku, sungguh, aku telah berbuat zalim terhadap diriku. Aku berserah diri bersama Sulaiman kepada Allah, Tuhan seluruh alam"},{id:45,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u062b\u064e\u0645\u064f\u0648\u062f\u064e \u0623\u064e\u062e\u064e\u0627\u0647\u064f\u0645\u06e1 \u0635\u064e\u0670\u0644\u0650\u062d\u064b\u0627 \u0623\u064e\u0646\u0650 \u0671\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0645\u06e1 \u0641\u064e\u0631\u0650\u064a\u0642\u064e\u0627\u0646\u0650 \u064a\u064e\u062e\u06e1\u062a\u064e\u0635\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Dan sungguh, Kami telah mengutus kepada (kaum) Samud saudara mereka yaitu Saleh (yang menyeru), \"Sembahlah Allah!\" Tetapi tiba-tiba mereka (menjadi) dua golongan yang bermusuhan"},{id:46,text:"\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0644\u0650\u0645\u064e \u062a\u064e\u0633\u06e1\u062a\u064e\u0639\u06e1\u062c\u0650\u0644\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u0650 \u0642\u064e\u0628\u06e1\u0644\u064e \u0671\u0644\u06e1\u062d\u064e\u0633\u064e\u0646\u064e\u0629\u0650\u06d6 \u0644\u064e\u0648\u06e1\u0644\u064e\u0627 \u062a\u064e\u0633\u06e1\u062a\u064e\u063a\u06e1\u0641\u0650\u0631\u064f\u0648\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064f\u0631\u06e1\u062d\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dia (Saleh) berkata, \"Wahai kaumku! Mengapa kamu meminta disegerakan keburukan sebelum (kamu meminta) kebaikan? Mengapa kamu tidak memohon ampunan kepada Allah, agar kamu mendapat rahmat"},{id:47,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0671\u0637\u0651\u064e\u064a\u0651\u064e\u0631\u06e1\u0646\u064e\u0627 \u0628\u0650\u0643\u064e \u0648\u064e\u0628\u0650\u0645\u064e\u0646 \u0645\u0651\u064e\u0639\u064e\u0643\u064e\u06da \u0642\u064e\u0627\u0644\u064e \u0637\u064e\u0640\u0670\u0653\u0626\u0650\u0631\u064f\u0643\u064f\u0645\u06e1 \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0628\u064e\u0644\u06e1 \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0642\u064e\u0648\u06e1\u0645\u065e \u062a\u064f\u0641\u06e1\u062a\u064e\u0646\u064f\u0648\u0646\u064e",translation:"Mereka menjawab, \"Kami mendapat nasib yang malang disebabkan oleh kamu dan orang-orang yang bersamamu.\" Dia (Saleh) berkata, \"Nasibmu ada pada Allah (bukan kami yang menjadi sebab), tetapi kamu adalah kaum yang sedang diuji"},{id:48,text:"\u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0645\u064e\u062f\u0650\u064a\u0646\u064e\u0629\u0650 \u062a\u0650\u0633\u06e1\u0639\u064e\u0629\u064f \u0631\u064e\u0647\u06e1\u0637\u0656 \u064a\u064f\u0641\u06e1\u0633\u0650\u062f\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0635\u06e1\u0644\u0650\u062d\u064f\u0648\u0646\u064e",translation:"(Dan di kota itu600) ada sembilan orang laki-laki yang berbuat kerusakan di bumi, mereka tidak melakukan perbaikan"},{id:49,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u062a\u064e\u0642\u064e\u0627\u0633\u064e\u0645\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0646\u064f\u0628\u064e\u064a\u0651\u0650\u062a\u064e\u0646\u0651\u064e\u0647\u064f\u06e5 \u0648\u064e\u0623\u064e\u0647\u06e1\u0644\u064e\u0647\u064f\u06e5 \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0646\u064e\u0642\u064f\u0648\u0644\u064e\u0646\u0651\u064e \u0644\u0650\u0648\u064e\u0644\u0650\u064a\u0651\u0650\u0647\u0650\u06e6 \u0645\u064e\u0627 \u0634\u064e\u0647\u0650\u062f\u06e1\u0646\u064e\u0627 \u0645\u064e\u0647\u06e1\u0644\u0650\u0643\u064e \u0623\u064e\u0647\u06e1\u0644\u0650\u0647\u0650\u06e6 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0635\u064e\u0670\u062f\u0650\u0642\u064f\u0648\u0646\u064e",translation:"Mereka berkata, \"Bersumpahlah kamu dengan (nama) Allah, bahwa kita pasti akan menyerang dia bersama keluarganya pada malam hari, kemudian kita akan mengatakan kepada ahli warisnya (bahwa) kita tidak menyaksikan kebinasaan keluarganya itu, dan sungguh, kita orang yang benar"},{id:50,text:"\u0648\u064e\u0645\u064e\u0643\u064e\u0631\u064f\u0648\u0627\u0652 \u0645\u064e\u0643\u06e1\u0631\u0657\u0627 \u0648\u064e\u0645\u064e\u0643\u064e\u0631\u06e1\u0646\u064e\u0627 \u0645\u064e\u0643\u06e1\u0631\u0657\u0627 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0634\u06e1\u0639\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Dan mereka membuat tipu daya, dan Kami pun menyusun tipu daya, sedang mereka tidak menyadari"},{id:51,text:"\u0641\u064e\u0671\u0646\u0638\u064f\u0631\u06e1 \u0643\u064e\u064a\u06e1\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0670\u0642\u0650\u0628\u064e\u0629\u064f \u0645\u064e\u0643\u06e1\u0631\u0650\u0647\u0650\u0645\u06e1 \u0623\u064e\u0646\u0651\u064e\u0627 \u062f\u064e\u0645\u0651\u064e\u0631\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0648\u064e\u0642\u064e\u0648\u06e1\u0645\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u062c\u06e1\u0645\u064e\u0639\u0650\u064a\u0646\u064e",translation:"Maka perhatikanlah bagaimana akibat dari tipu daya mereka, bahwa Kami membinasakan mereka dan kaum mereka semuanya"},{id:52,text:"\u0641\u064e\u062a\u0650\u0644\u06e1\u0643\u064e \u0628\u064f\u064a\u064f\u0648\u062a\u064f\u0647\u064f\u0645\u06e1 \u062e\u064e\u0627\u0648\u0650\u064a\u064e\u0629\u064e\u06e2 \u0628\u0650\u0645\u064e\u0627 \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652\u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0623\u0653\u064a\u064e\u0629\u0657 \u0644\u0651\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Maka itulah rumah-rumah mereka yang runtuh karena kezaliman mereka. Sungguh, pada yang demikian itu benar-benar terdapat tanda (kekuasaan Allah) bagi orang-orang yang mengetahui"},{id:53,text:"\u0648\u064e\u0623\u064e\u0646\u062c\u064e\u064a\u06e1\u0646\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",translation:"(Dan Kami selamatkan orang-orang yang beriman601) dan mereka selalu bertakwa"},{id:54,text:"\u0648\u064e\u0644\u064f\u0648\u0637\u064b\u0627 \u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u062a\u064e\u0623\u06e1\u062a\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0641\u064e\u0670\u062d\u0650\u0634\u064e\u0629\u064e \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u062a\u064f\u0628\u06e1\u0635\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Dan (ingatlah kisah) Lu\u1e6d, ketika dia berkata kepada kaumnya, \"Mengapa kamu mengerjakan perbuatan f\u0101\u1e25isyah (keji),602) padahal kamu melihatnya (kekejian perbuatan maksiat itu)"},{id:55,text:"\u0623\u064e\u0626\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0644\u064e\u062a\u064e\u0623\u06e1\u062a\u064f\u0648\u0646\u064e \u0671\u0644\u0631\u0651\u0650\u062c\u064e\u0627\u0644\u064e \u0634\u064e\u0647\u06e1\u0648\u064e\u0629\u0657 \u0645\u0651\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0653\u0621\u0650\u06da \u0628\u064e\u0644\u06e1 \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0642\u064e\u0648\u06e1\u0645\u065e \u062a\u064e\u062c\u06e1\u0647\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Mengapa kamu mendatangi laki-laki untuk (memenuhi) syahwat(mu), bukan (mendatangi) perempuan? Sungguh, kamu adalah kaum yang tidak mengetahui (akibat perbuatanmu)"},{id:56,text:"\u06de\u0641\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u062c\u064e\u0648\u064e\u0627\u0628\u064e \u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u062e\u06e1\u0631\u0650\u062c\u064f\u0648\u0653\u0627\u0652 \u0621\u064e\u0627\u0644\u064e \u0644\u064f\u0648\u0637\u0656 \u0645\u0651\u0650\u0646 \u0642\u064e\u0631\u06e1\u064a\u064e\u062a\u0650\u0643\u064f\u0645\u06e1\u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0623\u064f\u0646\u064e\u0627\u0633\u065e \u064a\u064e\u062a\u064e\u0637\u064e\u0647\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Jawaban kaumnya tidak lain hanya dengan mengatakan, \"Usirlah Lu\u1e6d dan keluarganya dari negerimu; sesungguhnya mereka adalah orang-orang yang (menganggap dirinya) suci"},{id:57,text:"\u0641\u064e\u0623\u064e\u0646\u062c\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f \u0648\u064e\u0623\u064e\u0647\u06e1\u0644\u064e\u0647\u064f\u06e5\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0645\u06e1\u0631\u064e\u0623\u064e\u062a\u064e\u0647\u064f\u06e5 \u0642\u064e\u062f\u0651\u064e\u0631\u06e1\u0646\u064e\u0670\u0647\u064e\u0627 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u063a\u064e\u0670\u0628\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Maka Kami selamatkan dia dan keluarganya, kecuali istrinya. Kami telah menentukan dia termasuk orang-orang yang tertinggal (dibinasakan)"},{id:58,text:"\u0648\u064e\u0623\u064e\u0645\u06e1\u0637\u064e\u0631\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0645\u0651\u064e\u0637\u064e\u0631\u0657\u0627\u06d6 \u0641\u064e\u0633\u064e\u0627\u0653\u0621\u064e \u0645\u064e\u0637\u064e\u0631\u064f \u0671\u0644\u06e1\u0645\u064f\u0646\u0630\u064e\u0631\u0650\u064a\u0646\u064e",translation:"Dan Kami hujani mereka dengan hujan (batu), maka sangat buruklah hujan (yang ditimpakan) pada orang-orang yang diberi peringatan itu (tetapi tidak mengindahkan)"},{id:59,text:"\u0642\u064f\u0644\u0650 \u0671\u0644\u06e1\u062d\u064e\u0645\u06e1\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0633\u064e\u0644\u064e\u0670\u0645\u064c \u0639\u064e\u0644\u064e\u0649\u0670 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u0635\u06e1\u0637\u064e\u0641\u064e\u0649\u0670\u0653\u06d7 \u0621\u064e\u0627\u0653\u0644\u0644\u0651\u064e\u0647\u064f \u062e\u064e\u064a\u06e1\u0631\u064c \u0623\u064e\u0645\u0651\u064e\u0627 \u064a\u064f\u0634\u06e1\u0631\u0650\u0643\u064f\u0648\u0646\u064e",translation:"Katakanlah (Muhammad), \"Segala puji bagi Allah dan salam sejahtera atas hamba-hamba-Nya yang dipilih-Nya. Apakah Allah yang lebih baik, ataukah apa yang mereka persekutukan (dengan Dia)"},{id:60,text:"\u0623\u064e\u0645\u0651\u064e\u0646\u06e1 \u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0648\u064e\u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0645\u064e\u0627\u0653\u0621\u0657 \u0641\u064e\u0623\u064e\u0646\u06e2\u0628\u064e\u062a\u06e1\u0646\u064e\u0627 \u0628\u0650\u0647\u0650\u06e6 \u062d\u064e\u062f\u064e\u0627\u0653\u0626\u0650\u0642\u064e \u0630\u064e\u0627\u062a\u064e \u0628\u064e\u0647\u06e1\u062c\u064e\u0629\u0656 \u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u0646 \u062a\u064f\u0646\u06e2\u0628\u0650\u062a\u064f\u0648\u0627\u0652 \u0634\u064e\u062c\u064e\u0631\u064e\u0647\u064e\u0627\u0653\u06d7 \u0623\u064e\u0621\u0650\u0644\u064e\u0670\u0647\u065e \u0645\u0651\u064e\u0639\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0628\u064e\u0644\u06e1 \u0647\u064f\u0645\u06e1 \u0642\u064e\u0648\u06e1\u0645\u065e \u064a\u064e\u0639\u06e1\u062f\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Bukankah Dia (Allah) yang menciptakan langit dan bumi dan yang menurunkan air dari langit untukmu, lalu Kami tumbuhkan dengan air itu kebun-kebun yang berpemandangan indah? Kamu tidak akan mampu menumbuhkan pohon-pohonnya. Apakah di samping Allah ada tuhan (yang lain)? Sebenarnya mereka adalah orang-orang yang menyimpang (dari kebenaran)"},{id:61,text:"\u0623\u064e\u0645\u0651\u064e\u0646 \u062c\u064e\u0639\u064e\u0644\u064e \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0642\u064e\u0631\u064e\u0627\u0631\u0657\u0627 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u062e\u0650\u0644\u064e\u0670\u0644\u064e\u0647\u064e\u0627\u0653 \u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u0657\u0627 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0647\u064e\u0627 \u0631\u064e\u0648\u064e\u0670\u0633\u0650\u064a\u064e \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0628\u064e\u064a\u06e1\u0646\u064e \u0671\u0644\u06e1\u0628\u064e\u062d\u06e1\u0631\u064e\u064a\u06e1\u0646\u0650 \u062d\u064e\u0627\u062c\u0650\u0632\u064b\u0627\u06d7 \u0623\u064e\u0621\u0650\u0644\u064e\u0670\u0647\u065e \u0645\u0651\u064e\u0639\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0628\u064e\u0644\u06e1 \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064f\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Bukankah Dia (Allah) telah menjadikan bumi sebagai tempat berdiam, yang menjadikan sungai-sungai di celah-celahnya, yang menjadikan gunung-gunung untuk (mengkokohkan)nya dan menjadikan suatu pemisah antara dua laut?603) Apakah di samping Allah ada tuhan (yang lain)? Sebenarnya kebanyakan mereka tidak mengetahui"},{id:62,text:"\u0623\u064e\u0645\u0651\u064e\u0646 \u064a\u064f\u062c\u0650\u064a\u0628\u064f \u0671\u0644\u06e1\u0645\u064f\u0636\u06e1\u0637\u064e\u0631\u0651\u064e \u0625\u0650\u0630\u064e\u0627 \u062f\u064e\u0639\u064e\u0627\u0647\u064f \u0648\u064e\u064a\u064e\u0643\u06e1\u0634\u0650\u0641\u064f \u0671\u0644\u0633\u0651\u064f\u0648\u0653\u0621\u064e \u0648\u064e\u064a\u064e\u062c\u06e1\u0639\u064e\u0644\u064f\u0643\u064f\u0645\u06e1 \u062e\u064f\u0644\u064e\u0641\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d7 \u0623\u064e\u0621\u0650\u0644\u064e\u0670\u0647\u065e \u0645\u0651\u064e\u0639\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0642\u064e\u0644\u0650\u064a\u0644\u0657\u0627 \u0645\u0651\u064e\u0627 \u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Bukankah Dia (Allah) yang memperkenankan (doa) orang yang dalam kesulitan apabila dia berdoa kepada-Nya, dan menghilangkan kesusahan dan menjadikan kamu (manusia) sebagai khalifah (pemimpin) di bumi? Apakah di samping Allah ada tuhan (yang lain)? Sedikit sekali (nikmat Allah) yang kamu ingat"},{id:63,text:"\u0623\u064e\u0645\u0651\u064e\u0646 \u064a\u064e\u0647\u06e1\u062f\u0650\u064a\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u0638\u064f\u0644\u064f\u0645\u064e\u0670\u062a\u0650 \u0671\u0644\u06e1\u0628\u064e\u0631\u0651\u0650 \u0648\u064e\u0671\u0644\u06e1\u0628\u064e\u062d\u06e1\u0631\u0650 \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0631\u06e1\u0633\u0650\u0644\u064f \u0671\u0644\u0631\u0651\u0650\u064a\u064e\u0670\u062d\u064e \u0628\u064f\u0634\u06e1\u0631\u064e\u06e2\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u06e1 \u0631\u064e\u062d\u06e1\u0645\u064e\u062a\u0650\u0647\u0650\u06e6\u0653\u06d7 \u0623\u064e\u0621\u0650\u0644\u064e\u0670\u0647\u065e \u0645\u0651\u064e\u0639\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u062a\u064e\u0639\u064e\u0670\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064f\u0634\u06e1\u0631\u0650\u0643\u064f\u0648\u0646\u064e",translation:"Bukankah Dia (Allah) yang memberi petunjuk kepada kamu dalam kegelapan di daratan dan lautan dan yang mendatangkan angin sebagai kabar gembira sebelum (kedatangan) rahmat-Nya? Apakah di samping Allah ada tuhan (yang lain)? Mahatinggi Allah terhadap apa yang mereka persekutukan"},{id:64,text:"\u0623\u064e\u0645\u0651\u064e\u0646 \u064a\u064e\u0628\u06e1\u062f\u064e\u0624\u064f\u0627\u0652 \u0671\u0644\u06e1\u062e\u064e\u0644\u06e1\u0642\u064e \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0639\u0650\u064a\u062f\u064f\u0647\u064f\u06e5 \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0631\u06e1\u0632\u064f\u0642\u064f\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d7 \u0623\u064e\u0621\u0650\u0644\u064e\u0670\u0647\u065e \u0645\u0651\u064e\u0639\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0642\u064f\u0644\u06e1 \u0647\u064e\u0627\u062a\u064f\u0648\u0627\u0652 \u0628\u064f\u0631\u06e1\u0647\u064e\u0670\u0646\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0635\u064e\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Bukankah Dia (Allah) yang menciptakan (makhluk) dari permulaannya, kemudian mengulanginya (lagi) dan yang memberikan rezeki kepadamu dari langit dan bumi? Apakah di samping Allah ada tuhan (yang lain)? Katakanlah, \"Kemukakanlah bukti kebenaranmu, jika kamu orang yang benar"},{id:65,text:"\u0642\u064f\u0644 \u0644\u0651\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0646 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u0628\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06da \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0634\u06e1\u0639\u064f\u0631\u064f\u0648\u0646\u064e \u0623\u064e\u064a\u0651\u064e\u0627\u0646\u064e \u064a\u064f\u0628\u06e1\u0639\u064e\u062b\u064f\u0648\u0646\u064e",translation:"Katakanlah (Muhammad), \"Tidak ada sesuatu pun di langit dan di bumi yang mengetahui perkara yang gaib, kecuali Allah. Dan mereka tidak mengetahui kapan mereka akan dibangkitkan"},{id:66,text:"\u0628\u064e\u0644\u0650 \u0671\u062f\u0651\u064e\u0640\u0670\u0631\u064e\u0643\u064e \u0639\u0650\u0644\u06e1\u0645\u064f\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650\u06da \u0628\u064e\u0644\u06e1 \u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0634\u064e\u0643\u0651\u0656 \u0645\u0651\u0650\u0646\u06e1\u0647\u064e\u0627\u06d6 \u0628\u064e\u0644\u06e1 \u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1\u0647\u064e\u0627 \u0639\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Bahkan pengetahuan mereka tentang akhirat tidak sampai (ke sana). Bahkan mereka ragu-ragu tentangnya (akhirat). Bahkan mereka buta tentang itu"},{id:67,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0621\u0650\u0630\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u062a\u064f\u0631\u064e\u0670\u0628\u0657\u0627 \u0648\u064e\u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0624\u064f\u0646\u064e\u0627\u0653 \u0623\u064e\u0626\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0645\u064f\u062e\u06e1\u0631\u064e\u062c\u064f\u0648\u0646\u064e",translation:"Dan orang-orang yang kafir berkata, \"Setelah kita menjadi tanah dan (begitu pula) nenek moyang kita, apakah benar kita akan dikeluarkan (dari kubur)"},{id:68,text:"\u0644\u064e\u0642\u064e\u062f\u06e1 \u0648\u064f\u0639\u0650\u062f\u06e1\u0646\u064e\u0627 \u0647\u064e\u0670\u0630\u064e\u0627 \u0646\u064e\u062d\u06e1\u0646\u064f \u0648\u064e\u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0624\u064f\u0646\u064e\u0627 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f \u0625\u0650\u0646\u06e1 \u0647\u064e\u0670\u0630\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0633\u064e\u0670\u0637\u0650\u064a\u0631\u064f \u0671\u0644\u06e1\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",translation:"Sejak dahulu kami telah diberi ancaman dengan ini (hari kebangkitan); kami dan nenek moyang kami. Sebenarnya ini hanyalah dongeng orang-orang terdahulu"},{id:69,text:"\u0642\u064f\u0644\u06e1 \u0633\u0650\u064a\u0631\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0641\u064e\u0671\u0646\u0638\u064f\u0631\u064f\u0648\u0627\u0652 \u0643\u064e\u064a\u06e1\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0670\u0642\u0650\u0628\u064e\u0629\u064f \u0671\u0644\u06e1\u0645\u064f\u062c\u06e1\u0631\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Katakanlah (Muhammad), \"Berjalanlah kamu di bumi, lalu perhatikanlah bagaimana kesudahan orang-orang yang berdosa"},{id:70,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062d\u06e1\u0632\u064e\u0646\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0646 \u0641\u0650\u064a \u0636\u064e\u064a\u06e1\u0642\u0656 \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u0645\u06e1\u0643\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Dan janganlah engkau bersedih hati terhadap mereka, dan janganlah (dadamu) merasa sempit terhadap upaya tipu daya mereka"},{id:71,text:"\u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0645\u064e\u062a\u064e\u0649\u0670 \u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u06e1\u0648\u064e\u0639\u06e1\u062f\u064f \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0635\u064e\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Dan mereka (orang kafir) berkata, \"Kapankah datangnya janji (azab) itu, jika kamu orang yang benar"},{id:72,text:"\u0642\u064f\u0644\u06e1 \u0639\u064e\u0633\u064e\u0649\u0670\u0653 \u0623\u064e\u0646 \u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0631\u064e\u062f\u0650\u0641\u064e \u0644\u064e\u0643\u064f\u0645 \u0628\u064e\u0639\u06e1\u0636\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062a\u064e\u0633\u06e1\u062a\u064e\u0639\u06e1\u062c\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Katakanlah (Muhammad), \"Boleh jadi sebagian dari (azab) yang kamu minta disegerakan itu telah hampir sampai kepadamu"},{id:73,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0644\u064e\u0630\u064f\u0648 \u0641\u064e\u0636\u06e1\u0644\u064d \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0634\u06e1\u0643\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Dan Sungguh, Tuhanmu benar-benar memiliki karunia (yang diberikan-Nya) kepada manusia, tetapi kebanyakan mereka tidak mensyukuri(nya)"},{id:74,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0644\u064e\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u062a\u064f\u0643\u0650\u0646\u0651\u064f \u0635\u064f\u062f\u064f\u0648\u0631\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0639\u06e1\u0644\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Dan sungguh, Tuhanmu mengetahui apa yang disembunyikan dalam dada mereka dan apa yang mereka nyatakan"},{id:75,text:"\u0648\u064e\u0645\u064e\u0627 \u0645\u0650\u0646\u06e1 \u063a\u064e\u0627\u0653\u0626\u0650\u0628\u064e\u0629\u0656 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0641\u0650\u064a \u0643\u0650\u062a\u064e\u0670\u0628\u0656 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u064d",translation:"Dan tidak ada sesuatu pun yang tersembunyi di langit dan di bumi, melainkan (tercatat) dalam Kitab yang jelas (Lau\u1e25 Ma\u1e25f\u016b\u1e93)"},{id:76,text:"\u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u064e \u064a\u064e\u0642\u064f\u0635\u0651\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0646\u0650\u064a\u0653 \u0625\u0650\u0633\u06e1\u0631\u064e\u0640\u0670\u0653\u0621\u0650\u064a\u0644\u064e \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u0650 \u064a\u064e\u062e\u06e1\u062a\u064e\u0644\u0650\u0641\u064f\u0648\u0646\u064e",translation:"Sungguh, Alquran ini menjelaskan kepada Bani Israil sebagian besar dari (perkara) yang mereka perselisihkan"},{id:77,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0647\u064f\u062f\u0657\u0649 \u0648\u064e\u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u065e \u0644\u0651\u0650\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dan Sungguh, (Alquran) itu benar-benar menjadi petunjuk dan rahmat bagi orang-orang yang beriman"},{id:78,text:"\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u064a\u064e\u0642\u06e1\u0636\u0650\u064a \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645 \u0628\u0650\u062d\u064f\u0643\u06e1\u0645\u0650\u0647\u0650\u06e6\u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0671\u0644\u06e1\u0639\u064e\u0644\u0650\u064a\u0645\u064f",translation:"Sungguh, Tuhanmu akan menyelesaikannya (perkara) di antara mereka dengan hukum-Nya, dan Dia Mahaperkasa, Maha Mengetahui"},{id:79,text:"\u0641\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u06e1 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0671\u0644\u06e1\u0645\u064f\u0628\u0650\u064a\u0646\u0650",translation:"Maka bertawakallah kepada Allah, sungguh engkau (Muhammad) berada di atas kebenaran yang nyata"},{id:80,text:"\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u0627 \u062a\u064f\u0633\u06e1\u0645\u0650\u0639\u064f \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u064e\u0649\u0670 \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0633\u06e1\u0645\u0650\u0639\u064f \u0671\u0644\u0635\u0651\u064f\u0645\u0651\u064e \u0671\u0644\u062f\u0651\u064f\u0639\u064e\u0627\u0653\u0621\u064e \u0625\u0650\u0630\u064e\u0627 \u0648\u064e\u0644\u0651\u064e\u0648\u06e1\u0627\u0652 \u0645\u064f\u062f\u06e1\u0628\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Sungguh, engkau tidak dapat menjadikan orang yang mati dapat mendengar dan (tidak pula) menjadikan orang yang tuli dapat mendengar seruan, apabila mereka telah berpaling ke belakang"},{id:81,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064e \u0628\u0650\u0647\u064e\u0670\u062f\u0650\u064a \u0671\u0644\u06e1\u0639\u064f\u0645\u06e1\u064a\u0650 \u0639\u064e\u0646 \u0636\u064e\u0644\u064e\u0670\u0644\u064e\u062a\u0650\u0647\u0650\u0645\u06e1\u06d6 \u0625\u0650\u0646 \u062a\u064f\u0633\u06e1\u0645\u0650\u0639\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0641\u064e\u0647\u064f\u0645 \u0645\u0651\u064f\u0633\u06e1\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Dan engkau tidak akan dapat memberi petunjuk orang buta dari kesesatannya. Engkau tidak dapat menjadikan (seorang pun) mendengar, kecuali orang-orang yang beriman kepada ayat-ayat Kami, lalu mereka berserah diri"},{id:82,text:"\u06de\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0648\u064e\u0642\u064e\u0639\u064e \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0644\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0623\u064e\u062e\u06e1\u0631\u064e\u062c\u06e1\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u06e1 \u062f\u064e\u0627\u0653\u0628\u0651\u064e\u0629\u0657 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u062a\u064f\u0643\u064e\u0644\u0651\u0650\u0645\u064f\u0647\u064f\u0645\u06e1 \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0644\u064e\u0627 \u064a\u064f\u0648\u0642\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Dan apabila perkataan (ketentuan masa kehancuran alam) telah berlaku atas mereka, Kami keluarkan makhluk bergerak yang bernyawa dari bumi yang akan mengatakan kepada mereka bahwa manusia dahulu tidak yakin kepada ayat-ayat Kami"},{id:83,text:"\u0648\u064e\u064a\u064e\u0648\u06e1\u0645\u064e \u0646\u064e\u062d\u06e1\u0634\u064f\u0631\u064f \u0645\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u0623\u064f\u0645\u0651\u064e\u0629\u0656 \u0641\u064e\u0648\u06e1\u062c\u0657\u0627 \u0645\u0651\u0650\u0645\u0651\u064e\u0646 \u064a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0641\u064e\u0647\u064f\u0645\u06e1 \u064a\u064f\u0648\u0632\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Dan (ingatlah) pada hari (ketika) Kami mengumpulkan dari setiap umat, segolongan orang yang mendustakan ayat-ayat Kami, lalu mereka dibagi-bagi (dalam kelompok-kelompok)"},{id:84,text:"\u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064f\u0648 \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u06e1\u062a\u064f\u0645 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u064a \u0648\u064e\u0644\u064e\u0645\u06e1 \u062a\u064f\u062d\u0650\u064a\u0637\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u064e\u0627 \u0639\u0650\u0644\u06e1\u0645\u064b\u0627 \u0623\u064e\u0645\u0651\u064e\u0627\u0630\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Hingga apabila mereka datang, Dia (Allah) berfirman, \"Mengapa kamu dulu mendustakan ayat-ayat-Ku, padahal kamu tidak mempunyai pengetahuan tentang itu,604) atau apakah yang telah kamu kerjakan"},{id:85,text:"\u0648\u064e\u0648\u064e\u0642\u064e\u0639\u064e \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0644\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0628\u0650\u0645\u064e\u0627 \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627\u0652 \u0641\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0646\u0637\u0650\u0642\u064f\u0648\u0646\u064e",translation:"Dan berlakulah perkataan (janji azab) atas mereka karena kezaliman mereka, maka mereka tidak dapat berkata"},{id:86,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0631\u064e\u0648\u06e1\u0627\u0652 \u0623\u064e\u0646\u0651\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u064e \u0644\u0650\u064a\u064e\u0633\u06e1\u0643\u064f\u0646\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0647\u0650 \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u0645\u064f\u0628\u06e1\u0635\u0650\u0631\u064b\u0627\u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0623\u0653\u064a\u064e\u0670\u062a\u0656 \u0644\u0651\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Apakah mereka tidak memperhatikan bahwa Kami telah menjadikan malam agar mereka beristirahat padanya dan (menjadikan) siang yang menerangi? Sungguh, pada yang demikian itu terdapat tanda-tanda (kebesaran Allah) bagi orang-orang yang beriman"},{id:87,text:"\u0648\u064e\u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064f\u0646\u0641\u064e\u062e\u064f \u0641\u0650\u064a \u0671\u0644\u0635\u0651\u064f\u0648\u0631\u0650 \u0641\u064e\u0641\u064e\u0632\u0650\u0639\u064e \u0645\u064e\u0646 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0645\u064e\u0646 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646 \u0634\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06da \u0648\u064e\u0643\u064f\u0644\u0651\u064c \u0623\u064e\u062a\u064e\u0648\u06e1\u0647\u064f \u062f\u064e\u0670\u062e\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan (ingatlah) pada hari (ketika) sangkakala ditiup, maka terkejutlah apa yang ada di langit dan apa yang ada di bumi, kecuali siapa yang dikehendaki Allah. Dan semua mereka datang menghadap-Nya dengan merendahkan diri"},{id:88,text:"\u0648\u064e\u062a\u064e\u0631\u064e\u0649 \u0671\u0644\u06e1\u062c\u0650\u0628\u064e\u0627\u0644\u064e \u062a\u064e\u062d\u06e1\u0633\u064e\u0628\u064f\u0647\u064e\u0627 \u062c\u064e\u0627\u0645\u0650\u062f\u064e\u0629\u0657 \u0648\u064e\u0647\u0650\u064a\u064e \u062a\u064e\u0645\u064f\u0631\u0651\u064f \u0645\u064e\u0631\u0651\u064e \u0671\u0644\u0633\u0651\u064e\u062d\u064e\u0627\u0628\u0650\u06da \u0635\u064f\u0646\u06e1\u0639\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064e\u062a\u06e1\u0642\u064e\u0646\u064e \u0643\u064f\u0644\u0651\u064e \u0634\u064e\u064a\u06e1\u0621\u064d\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u062e\u064e\u0628\u0650\u064a\u0631\u064f\u06e2 \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0641\u06e1\u0639\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan engkau akan melihat gunung-gunung, yang engkau kira tetap di tempatnya, padahal ia berjalan (seperti) awan berjalan. (Itulah) ciptaan Allah yang mencipta dengan sempurna segala sesuatu. Sungguh, Dia Mahateliti atas apa yang kamu kerjakan"},{id:89,text:"\u0645\u064e\u0646 \u062c\u064e\u0627\u0653\u0621\u064e \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0633\u064e\u0646\u064e\u0629\u0650 \u0641\u064e\u0644\u064e\u0647\u064f\u06e5 \u062e\u064e\u064a\u06e1\u0631\u065e \u0645\u0651\u0650\u0646\u06e1\u0647\u064e\u0627 \u0648\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0641\u064e\u0632\u064e\u0639\u0656 \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u064d \u0621\u064e\u0627\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Barangsiapa membawa kebaikan, maka dia memperoleh (balasan) yang lebih baik daripadanya, sedang mereka merasa aman dari kejutan (yang dahsyat) pada hari itu"},{id:90,text:"\u0648\u064e\u0645\u064e\u0646 \u062c\u064e\u0627\u0653\u0621\u064e \u0628\u0650\u0671\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u0650 \u0641\u064e\u0643\u064f\u0628\u0651\u064e\u062a\u06e1 \u0648\u064f\u062c\u064f\u0648\u0647\u064f\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0647\u064e\u0644\u06e1 \u062a\u064f\u062c\u06e1\u0632\u064e\u0648\u06e1\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan barangsiapa membawa kejahatan, maka disungkurkanlah wajah mereka ke dalam neraka. Kamu tidak diberi balasan, melainkan (setimpal) dengan apa yang telah kamu kerjakan"},{id:91,text:"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0645\u0650\u0631\u06e1\u062a\u064f \u0623\u064e\u0646\u06e1 \u0623\u064e\u0639\u06e1\u0628\u064f\u062f\u064e \u0631\u064e\u0628\u0651\u064e \u0647\u064e\u0670\u0630\u0650\u0647\u0650 \u0671\u0644\u06e1\u0628\u064e\u0644\u06e1\u062f\u064e\u0629\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062d\u064e\u0631\u0651\u064e\u0645\u064e\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0647\u064f\u06e5 \u0643\u064f\u0644\u0651\u064f \u0634\u064e\u064a\u06e1\u0621\u0656\u06d6 \u0648\u064e\u0623\u064f\u0645\u0650\u0631\u06e1\u062a\u064f \u0623\u064e\u0646\u06e1 \u0623\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0633\u06e1\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Aku (Muhammad) hanya diperintahkan menyembah Tuhan negeri ini (Mekkah) yang Dia telah menjadikan suci padanya dan segala sesuatu adalah milik-Nya. Dan aku diperintahkan agar aku termasuk orang muslim"},{id:92,text:"\u0648\u064e\u0623\u064e\u0646\u06e1 \u0623\u064e\u062a\u06e1\u0644\u064f\u0648\u064e\u0627\u0652 \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u064e\u06d6 \u0641\u064e\u0645\u064e\u0646\u0650 \u0671\u0647\u06e1\u062a\u064e\u062f\u064e\u0649\u0670 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0647\u06e1\u062a\u064e\u062f\u0650\u064a \u0644\u0650\u0646\u064e\u0641\u06e1\u0633\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u0645\u064e\u0646 \u0636\u064e\u0644\u0651\u064e \u0641\u064e\u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u064e\u0627\u06e0 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0646\u0630\u0650\u0631\u0650\u064a\u0646\u064e",translation:"dan agar aku membacakan Alquran (kepada manusia). Maka barangsiapa mendapat petunjuk, sesungguhnya dia mendapat petunjuk untuk (kebaikan) dirinya, dan barang siapa sesat, maka katakanlah, \"Sesungguhnya aku (ini) tidak lain hanyalah salah seorang pemberi peringatan"},{id:93,text:"\u0648\u064e\u0642\u064f\u0644\u0650 \u0671\u0644\u06e1\u062d\u064e\u0645\u06e1\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0633\u064e\u064a\u064f\u0631\u0650\u064a\u0643\u064f\u0645\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0647\u0650\u06e6 \u0641\u064e\u062a\u064e\u0639\u06e1\u0631\u0650\u0641\u064f\u0648\u0646\u064e\u0647\u064e\u0627\u06da \u0648\u064e\u0645\u064e\u0627 \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0628\u0650\u063a\u064e\u0670\u0641\u0650\u0644\u064d \u0639\u064e\u0645\u0651\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan katakanlah (Muhammad), \"Segala puji bagi Allah, Dia akan memperlihatkan kepadamu tanda-tanda (kebesaran)-Nya, maka kamu akan mengetahuinya. Dan Tuhanmu tidak lengah terhadap apa yang kamu kerjakan"}]},{id:28,name:"\u0627\u0644\u0642\u0635\u0635",transliteration:"Al-Qasas",translation:"Kisah-kisah",type:"meccan",total_verses:88,verses:[{id:1,text:"\u0637\u0633\u0653\u0645\u0653",translation:"\u1e6c\u0101 S\u012bn M\u012bm"},{id:2,text:"\u062a\u0650\u0644\u06e1\u0643\u064e \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u064f \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0671\u0644\u06e1\u0645\u064f\u0628\u0650\u064a\u0646\u0650",translation:"Ini ayat-ayat Kitab (Alquran) yang jelas (dari Allah)"},{id:3,text:"\u0646\u064e\u062a\u06e1\u0644\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0645\u0650\u0646 \u0646\u0651\u064e\u0628\u064e\u0625\u0650 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0644\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Kami membacakan kepadamu sebagian dari kisah Musa dan Fir'aun dengan sebenarnya untuk orang-orang yang beriman"},{id:4,text:"\u0625\u0650\u0646\u0651\u064e \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0639\u064e\u0644\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0623\u064e\u0647\u06e1\u0644\u064e\u0647\u064e\u0627 \u0634\u0650\u064a\u064e\u0639\u0657\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0636\u06e1\u0639\u0650\u0641\u064f \u0637\u064e\u0627\u0653\u0626\u0650\u0641\u064e\u0629\u0657 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u064a\u064f\u0630\u064e\u0628\u0651\u0650\u062d\u064f \u0623\u064e\u0628\u06e1\u0646\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u064a\u064e\u0633\u06e1\u062a\u064e\u062d\u06e1\u064a\u0650\u06e6 \u0646\u0650\u0633\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0641\u06e1\u0633\u0650\u062f\u0650\u064a\u0646\u064e",translation:"Sungguh, Fir'aun telah berbuat sewenang-wenang di bumi dan menjadikan penduduknya berpecah belah, dia menindas segolongan dari mereka (Bani Israil), dia menyembelih anak laki-laki mereka dan membiarkan hidup anak perempuan mereka. Sungguh, dia (Fir'aun) termasuk orang yang berbuat kerusakan"},{id:5,text:"\u0648\u064e\u0646\u064f\u0631\u0650\u064a\u062f\u064f \u0623\u064e\u0646 \u0646\u0651\u064e\u0645\u064f\u0646\u0651\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u0633\u06e1\u062a\u064f\u0636\u06e1\u0639\u0650\u0641\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0646\u064e\u062c\u06e1\u0639\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u0626\u0650\u0645\u0651\u064e\u0629\u0657 \u0648\u064e\u0646\u064e\u062c\u06e1\u0639\u064e\u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0648\u064e\u0670\u0631\u0650\u062b\u0650\u064a\u0646\u064e",translation:"Dan Kami hendak memberi karunia kepada orang-orang yang tertindas di bumi (Mesir) itu, dan hendak menjadikan mereka pemimpin dan menjadikan mereka orang-orang yang mewarisi (bumi)"},{id:6,text:"\u0648\u064e\u0646\u064f\u0645\u064e\u0643\u0651\u0650\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0646\u064f\u0631\u0650\u064a\u064e \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0648\u064e\u0647\u064e\u0670\u0645\u064e\u0670\u0646\u064e \u0648\u064e\u062c\u064f\u0646\u064f\u0648\u062f\u064e\u0647\u064f\u0645\u064e\u0627 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u062d\u06e1\u0630\u064e\u0631\u064f\u0648\u0646\u064e",translation:"dan Kami teguhkan kedudukan mereka di bumi dan Kami perlihatkan kepada Fir'aun dan Haman bersama bala tentaranya apa yang selalu mereka takutkan dari mereka"},{id:7,text:"\u0648\u064e\u0623\u064e\u0648\u06e1\u062d\u064e\u064a\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064f\u0645\u0651\u0650 \u0645\u064f\u0648\u0633\u064e\u0649\u0670\u0653 \u0623\u064e\u0646\u06e1 \u0623\u064e\u0631\u06e1\u0636\u0650\u0639\u0650\u064a\u0647\u0650\u06d6 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u062e\u0650\u0641\u06e1\u062a\u0650 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0641\u064e\u0623\u064e\u0644\u06e1\u0642\u0650\u064a\u0647\u0650 \u0641\u0650\u064a \u0671\u0644\u06e1\u064a\u064e\u0645\u0651\u0650 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062e\u064e\u0627\u0641\u0650\u064a \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062d\u06e1\u0632\u064e\u0646\u0650\u064a\u0653\u06d6 \u0625\u0650\u0646\u0651\u064e\u0627 \u0631\u064e\u0627\u0653\u062f\u0651\u064f\u0648\u0647\u064f \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u0650 \u0648\u064e\u062c\u064e\u0627\u0639\u0650\u0644\u064f\u0648\u0647\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0631\u06e1\u0633\u064e\u0644\u0650\u064a\u0646\u064e",translation:"Dan Kami ilhamkan kepada ibu Musa, \"Susuilah dia (Musa), dan apabila engkau khawatir terhadapnya maka hanyutkanlah dia ke sungai (Nil). Dan janganlah engkau takut dan jangan (pula) bersedih hati, sesungguhnya Kami akan mengembalikannya kepadamu, dan menjadikannya salah seorang rasul"},{id:8,text:"\u0641\u064e\u0671\u0644\u06e1\u062a\u064e\u0642\u064e\u0637\u064e\u0647\u064f\u06e5\u0653 \u0621\u064e\u0627\u0644\u064f \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0644\u0650\u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u062f\u064f\u0648\u0651\u0657\u0627 \u0648\u064e\u062d\u064e\u0632\u064e\u0646\u064b\u0627\u06d7 \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0648\u064e\u0647\u064e\u0670\u0645\u064e\u0670\u0646\u064e \u0648\u064e\u062c\u064f\u0646\u064f\u0648\u062f\u064e\u0647\u064f\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u062e\u064e\u0670\u0637\u0650\u0640\u0654\u0650\u064a\u0646\u064e",translation:"Maka dia dipungut oleh keluarga Fir'aun agar (kelak) dia menjadi musuh dan kesedihan bagi mereka. Sungguh, Fir'aun dan Haman bersama bala tentaranya adalah orang-orang yang bersalah"},{id:9,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e\u062a\u0650 \u0671\u0645\u06e1\u0631\u064e\u0623\u064e\u062a\u064f \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0642\u064f\u0631\u0651\u064e\u062a\u064f \u0639\u064e\u064a\u06e1\u0646\u0656 \u0644\u0651\u0650\u064a \u0648\u064e\u0644\u064e\u0643\u064e\u06d6 \u0644\u064e\u0627 \u062a\u064e\u0642\u06e1\u062a\u064f\u0644\u064f\u0648\u0647\u064f \u0639\u064e\u0633\u064e\u0649\u0670\u0653 \u0623\u064e\u0646 \u064a\u064e\u0646\u0641\u064e\u0639\u064e\u0646\u064e\u0627\u0653 \u0623\u064e\u0648\u06e1 \u0646\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064e\u0647\u064f\u06e5 \u0648\u064e\u0644\u064e\u062f\u0657\u0627 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0634\u06e1\u0639\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Dan istri Fir'aun berkata, \"(Dia) adalah penyejuk mata hati bagiku dan bagimu. Janganlah engkau membunuhnya, mudah-mudahan dia bermanfaat kepada kita atau kita ambil dia menjadi anak,\" sedang mereka tidak menyadari"},{id:10,text:"\u0648\u064e\u0623\u064e\u0635\u06e1\u0628\u064e\u062d\u064e \u0641\u064f\u0624\u064e\u0627\u062f\u064f \u0623\u064f\u0645\u0651\u0650 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0641\u064e\u0670\u0631\u0650\u063a\u064b\u0627\u06d6 \u0625\u0650\u0646 \u0643\u064e\u0627\u062f\u064e\u062a\u06e1 \u0644\u064e\u062a\u064f\u0628\u06e1\u062f\u0650\u064a \u0628\u0650\u0647\u0650\u06e6 \u0644\u064e\u0648\u06e1\u0644\u064e\u0627\u0653 \u0623\u064e\u0646 \u0631\u0651\u064e\u0628\u064e\u0637\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064e\u0644\u06e1\u0628\u0650\u0647\u064e\u0627 \u0644\u0650\u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"(Dan hati ibu Musa menjadi kosong.606) Sungguh, hampir saja dia menyatakannya (rahasia tentang Musa), seandainya tidak Kami teguhkan hatinya, agar dia termasuk orang-orang yang beriman (kepada janji Allah)"},{id:11,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e\u062a\u06e1 \u0644\u0650\u0623\u064f\u062e\u06e1\u062a\u0650\u0647\u0650\u06e6 \u0642\u064f\u0635\u0651\u0650\u064a\u0647\u0650\u06d6 \u0641\u064e\u0628\u064e\u0635\u064f\u0631\u064e\u062a\u06e1 \u0628\u0650\u0647\u0650\u06e6 \u0639\u064e\u0646 \u062c\u064f\u0646\u064f\u0628\u0656 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0634\u06e1\u0639\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Dan dia (ibunya Musa) berkata kepada saudara perempuan Musa, \"Ikutilah dia (Musa).\" Maka dia melihatnya (Musa) dari jauh, sedang mereka tidak menyadarinya"},{id:12,text:"\u06de\u0648\u064e\u062d\u064e\u0631\u0651\u064e\u0645\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0671\u0644\u06e1\u0645\u064e\u0631\u064e\u0627\u0636\u0650\u0639\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f \u0641\u064e\u0642\u064e\u0627\u0644\u064e\u062a\u06e1 \u0647\u064e\u0644\u06e1 \u0623\u064e\u062f\u064f\u0644\u0651\u064f\u0643\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0647\u06e1\u0644\u0650 \u0628\u064e\u064a\u06e1\u062a\u0656 \u064a\u064e\u0643\u06e1\u0641\u064f\u0644\u064f\u0648\u0646\u064e\u0647\u064f\u06e5 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0647\u064f\u06e5 \u0646\u064e\u0670\u0635\u0650\u062d\u064f\u0648\u0646\u064e",translation:"dan Kami cegah dia (Musa) menyusu kepada perempuan-perempuan yang mau menyususi(nya) sebelum itu; maka berkatalah dia (saudaranya Musa), \"Maukah aku tunjukkan kepadamu, keluarga yang akan memeliharanya untukmu dan mereka dapat berlaku baik padanya"},{id:13,text:"\u0641\u064e\u0631\u064e\u062f\u064e\u062f\u06e1\u0646\u064e\u0670\u0647\u064f \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064f\u0645\u0651\u0650\u0647\u0650\u06e6 \u0643\u064e\u064a\u06e1 \u062a\u064e\u0642\u064e\u0631\u0651\u064e \u0639\u064e\u064a\u06e1\u0646\u064f\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062d\u06e1\u0632\u064e\u0646\u064e \u0648\u064e\u0644\u0650\u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064e \u0623\u064e\u0646\u0651\u064e \u0648\u064e\u0639\u06e1\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u064e\u0642\u0651\u065e \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Maka kami kembalikan dia (Musa) kepada ibunya, agar senang hatinya dan tidak bersedih hati, dan agar dia mengetahui bahwa janji Allah adalah benar, tetapi kebanyakan mereka tidak mengetahuinya"},{id:14,text:"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0628\u064e\u0644\u064e\u063a\u064e \u0623\u064e\u0634\u064f\u062f\u0651\u064e\u0647\u064f\u06e5 \u0648\u064e\u0671\u0633\u06e1\u062a\u064e\u0648\u064e\u0649\u0670\u0653 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f \u062d\u064f\u0643\u06e1\u0645\u0657\u0627 \u0648\u064e\u0639\u0650\u0644\u06e1\u0645\u0657\u0627\u06da \u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u062c\u06e1\u0632\u0650\u064a \u0671\u0644\u06e1\u0645\u064f\u062d\u06e1\u0633\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dan setelah dia (Musa) dewasa dan sempurna akalnya, kami anugerahkan kepadanya hikmah (kenabian) dan pengetahuan. Dan demikianlah Kami memberi balasan kepada orang-orang yang berbuat baik"},{id:15,text:"\u0648\u064e\u062f\u064e\u062e\u064e\u0644\u064e \u0671\u0644\u06e1\u0645\u064e\u062f\u0650\u064a\u0646\u064e\u0629\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u062d\u0650\u064a\u0646\u0650 \u063a\u064e\u0641\u06e1\u0644\u064e\u0629\u0656 \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u0647\u06e1\u0644\u0650\u0647\u064e\u0627 \u0641\u064e\u0648\u064e\u062c\u064e\u062f\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0631\u064e\u062c\u064f\u0644\u064e\u064a\u06e1\u0646\u0650 \u064a\u064e\u0642\u06e1\u062a\u064e\u062a\u0650\u0644\u064e\u0627\u0646\u0650 \u0647\u064e\u0670\u0630\u064e\u0627 \u0645\u0650\u0646 \u0634\u0650\u064a\u0639\u064e\u062a\u0650\u0647\u0650\u06e6 \u0648\u064e\u0647\u064e\u0670\u0630\u064e\u0627 \u0645\u0650\u0646\u06e1 \u0639\u064e\u062f\u064f\u0648\u0651\u0650\u0647\u0650\u06e6\u06d6 \u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u063a\u064e\u0670\u062b\u064e\u0647\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0645\u0650\u0646 \u0634\u0650\u064a\u0639\u064e\u062a\u0650\u0647\u0650\u06e6 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0645\u0650\u0646\u06e1 \u0639\u064e\u062f\u064f\u0648\u0651\u0650\u0647\u0650\u06e6 \u0641\u064e\u0648\u064e\u0643\u064e\u0632\u064e\u0647\u064f\u06e5 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0641\u064e\u0642\u064e\u0636\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u06d6 \u0642\u064e\u0627\u0644\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0645\u0650\u0646\u06e1 \u0639\u064e\u0645\u064e\u0644\u0650 \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u0650\u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0639\u064e\u062f\u064f\u0648\u0651\u065e \u0645\u0651\u064f\u0636\u0650\u0644\u0651\u065e \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u065e",translation:"Dan dia (Musa) masuk ke kota (Memphis) ketika penduduknya sedang lengah, maka dia mendapati di dalam kota itu dua orang laki-laki sedang berkelahi; yang seorang dari kaumnya (Bani Israil) dan yang seorang (lagi) dari pihak musuhnya (kaum Fir'aun). Orang yang dari golongannya meminta pertolongan kepadanya, untuk (mengalahkan) orang yang dari pihak musuhnya, lalu Musa meninjunya, dan matilah musuhnya itu. Dia (Musa) berkata, \"Ini adalah perbuatan setan.607) Sungguh, dia (setan itu) adalah musuh yang jelas menyesatkan"},{id:16,text:"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0625\u0650\u0646\u0651\u0650\u064a \u0638\u064e\u0644\u064e\u0645\u06e1\u062a\u064f \u0646\u064e\u0641\u06e1\u0633\u0650\u064a \u0641\u064e\u0671\u063a\u06e1\u0641\u0650\u0631\u06e1 \u0644\u0650\u064a \u0641\u064e\u063a\u064e\u0641\u064e\u0631\u064e \u0644\u064e\u0647\u064f\u06e5\u0653\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u063a\u064e\u0641\u064f\u0648\u0631\u064f \u0671\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",translation:"Dia (Musa) berdoa, \"Ya Tuhanku, sesungguhnya aku telah menzalimi diriku sendiri, maka ampunilah aku.\" Maka Dia (Allah) mengampuninya. Sungguh, Allah, Dialah Yang Maha Pengampun, Maha Penyayang"},{id:17,text:"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0628\u0650\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u06e1\u0639\u064e\u0645\u06e1\u062a\u064e \u0639\u064e\u0644\u064e\u064a\u0651\u064e \u0641\u064e\u0644\u064e\u0646\u06e1 \u0623\u064e\u0643\u064f\u0648\u0646\u064e \u0638\u064e\u0647\u0650\u064a\u0631\u0657\u0627 \u0644\u0651\u0650\u0644\u06e1\u0645\u064f\u062c\u06e1\u0631\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dia (Musa) berkata, \"Ya Tuhanku! Demi nikmat yang telah Engkau anugerahkan kepadaku, maka aku tidak akan menjadi penolong bagi orang-orang yang berdosa"},{id:18,text:"\u0641\u064e\u0623\u064e\u0635\u06e1\u0628\u064e\u062d\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0645\u064e\u062f\u0650\u064a\u0646\u064e\u0629\u0650 \u062e\u064e\u0627\u0653\u0626\u0650\u0641\u0657\u0627 \u064a\u064e\u062a\u064e\u0631\u064e\u0642\u0651\u064e\u0628\u064f \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0671\u0633\u06e1\u062a\u064e\u0646\u0635\u064e\u0631\u064e\u0647\u064f\u06e5 \u0628\u0650\u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0633\u0650 \u064a\u064e\u0633\u06e1\u062a\u064e\u0635\u06e1\u0631\u0650\u062e\u064f\u0647\u064f\u06e5\u06da \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f\u06e5 \u0645\u064f\u0648\u0633\u064e\u0649\u0670\u0653 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u063a\u064e\u0648\u0650\u064a\u0651\u065e \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u065e",translation:"Karena itu, dia (Musa) menjadi ketakutan berada di kota sambil menunggu (akibat perbuatannya), tiba-tiba orang yang kemarin meminta pertolongan berteriak meminta pertolongan kepadanya. Musa berkata kepadanya, \"Engkau Sungguh, orang yang nyata-nyata sesat"},{id:19,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u0646\u06e1 \u0623\u064e\u0631\u064e\u0627\u062f\u064e \u0623\u064e\u0646 \u064a\u064e\u0628\u06e1\u0637\u0650\u0634\u064e \u0628\u0650\u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0647\u064f\u0648\u064e \u0639\u064e\u062f\u064f\u0648\u0651\u065e \u0644\u0651\u064e\u0647\u064f\u0645\u064e\u0627 \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0670\u0645\u064f\u0648\u0633\u064e\u0649\u0670\u0653 \u0623\u064e\u062a\u064f\u0631\u0650\u064a\u062f\u064f \u0623\u064e\u0646 \u062a\u064e\u0642\u06e1\u062a\u064f\u0644\u064e\u0646\u0650\u064a \u0643\u064e\u0645\u064e\u0627 \u0642\u064e\u062a\u064e\u0644\u06e1\u062a\u064e \u0646\u064e\u0641\u06e1\u0633\u064e\u06e2\u0627 \u0628\u0650\u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0633\u0650\u06d6 \u0625\u0650\u0646 \u062a\u064f\u0631\u0650\u064a\u062f\u064f \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u062a\u064e\u0643\u064f\u0648\u0646\u064e \u062c\u064e\u0628\u0651\u064e\u0627\u0631\u0657\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u062a\u064f\u0631\u0650\u064a\u062f\u064f \u0623\u064e\u0646 \u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0635\u06e1\u0644\u0650\u062d\u0650\u064a\u0646\u064e",translation:"Maka ketika dia (Musa) hendak memukul dengan keras orang yang menjadi musuh mereka berdua, dia (musuhnya) berkata, \"Wahai Musa! Apakah engkau bermaksud membunuhku, sebagaimana kemarin engkau telah membunuh seseorang? Engkau hanya bermaksud menjadi orang yang berbuat sewenang-wenang di negeri (ini), dan engkau tidak bermaksud menjadi salah seorang dari orang-orang yang mengadakan perdamaian"},{id:20,text:"\u0648\u064e\u062c\u064e\u0627\u0653\u0621\u064e \u0631\u064e\u062c\u064f\u0644\u065e \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u0642\u06e1\u0635\u064e\u0627 \u0671\u0644\u06e1\u0645\u064e\u062f\u0650\u064a\u0646\u064e\u0629\u0650 \u064a\u064e\u0633\u06e1\u0639\u064e\u0649\u0670 \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0670\u0645\u064f\u0648\u0633\u064e\u0649\u0670\u0653 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0623\u064e \u064a\u064e\u0623\u06e1\u062a\u064e\u0645\u0650\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0643\u064e \u0644\u0650\u064a\u064e\u0642\u06e1\u062a\u064f\u0644\u064f\u0648\u0643\u064e \u0641\u064e\u0671\u062e\u06e1\u0631\u064f\u062c\u06e1 \u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0640\u0670\u0635\u0650\u062d\u0650\u064a\u0646\u064e",translation:"Dan seorang laki-laki datang bergegas dari ujung kota seraya berkata, \"Wahai Musa! Sesungguhnya para pembesar negeri sedang berunding tentang engkau untuk membunuhmu, maka keluarlah (dari kota ini), sesungguhnya aku termasuk orang-orang yang memberi nasihat kepadamu"},{id:21,text:"\u0641\u064e\u062e\u064e\u0631\u064e\u062c\u064e \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u062e\u064e\u0627\u0653\u0626\u0650\u0641\u0657\u0627 \u064a\u064e\u062a\u064e\u0631\u064e\u0642\u0651\u064e\u0628\u064f\u06d6 \u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0646\u064e\u062c\u0651\u0650\u0646\u0650\u064a \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Maka keluarlah dia (Musa) dari kota itu dengan rasa takut, waspada (kalau ada yang menyusul atau menangkapnya), dia berdoa, \"Ya Tuhanku, selamatkanlah aku dari orang-orang yang zalim itu"},{id:22,text:"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062a\u064e\u0648\u064e\u062c\u0651\u064e\u0647\u064e \u062a\u0650\u0644\u06e1\u0642\u064e\u0627\u0653\u0621\u064e \u0645\u064e\u062f\u06e1\u064a\u064e\u0646\u064e \u0642\u064e\u0627\u0644\u064e \u0639\u064e\u0633\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u064a\u0653 \u0623\u064e\u0646 \u064a\u064e\u0647\u06e1\u062f\u0650\u064a\u064e\u0646\u0650\u064a \u0633\u064e\u0648\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u0650",translation:"Dan ketika dia menuju ke arah negeri madyan dia berdoa lagi, \"Mudah-mudahan Tuhanku menunjuki aku ke jalan yang benar"},{id:23,text:"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0648\u064e\u0631\u064e\u062f\u064e \u0645\u064e\u0627\u0653\u0621\u064e \u0645\u064e\u062f\u06e1\u064a\u064e\u0646\u064e \u0648\u064e\u062c\u064e\u062f\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0623\u064f\u0645\u0651\u064e\u0629\u0657 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u064a\u064e\u0633\u06e1\u0642\u064f\u0648\u0646\u064e \u0648\u064e\u0648\u064e\u062c\u064e\u062f\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u0645\u064f \u0671\u0645\u06e1\u0631\u064e\u0623\u064e\u062a\u064e\u064a\u06e1\u0646\u0650 \u062a\u064e\u0630\u064f\u0648\u062f\u064e\u0627\u0646\u0650\u06d6 \u0642\u064e\u0627\u0644\u064e \u0645\u064e\u0627 \u062e\u064e\u0637\u06e1\u0628\u064f\u0643\u064f\u0645\u064e\u0627\u06d6 \u0642\u064e\u0627\u0644\u064e\u062a\u064e\u0627 \u0644\u064e\u0627 \u0646\u064e\u0633\u06e1\u0642\u0650\u064a \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064f\u0635\u06e1\u062f\u0650\u0631\u064e \u0671\u0644\u0631\u0651\u0650\u0639\u064e\u0627\u0653\u0621\u064f\u06d6 \u0648\u064e\u0623\u064e\u0628\u064f\u0648\u0646\u064e\u0627 \u0634\u064e\u064a\u06e1\u062e\u065e \u0643\u064e\u0628\u0650\u064a\u0631\u065e",translation:"Dan ketika dia sampai di sumber air negeri Madyan, dia menjumpai di sana sekumpulan orang yang sedang memberi minum (ternaknya), dan dia menjumpai di belakang orang banyak itu, dua orang perempuan sedang menghambat (ternaknya). Dia (Musa) berkata, \"Apakah maksudmu (dengan berbuat begitu)?\" Kedua (perempuan) itu menjawab, \"Kami tidak dapat memberi minum (ternak kami), sebelum penggembala-penggembala itu memulangkan (ternaknya), sedang ayah kami adalah orang tua yang telah lanjut usianya"},{id:24,text:"\u0641\u064e\u0633\u064e\u0642\u064e\u0649\u0670 \u0644\u064e\u0647\u064f\u0645\u064e\u0627 \u062b\u064f\u0645\u0651\u064e \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649\u0670\u0653 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0638\u0651\u0650\u0644\u0651\u0650 \u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0625\u0650\u0646\u0651\u0650\u064a \u0644\u0650\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u062a\u064e \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0645\u0650\u0646\u06e1 \u062e\u064e\u064a\u06e1\u0631\u0656 \u0641\u064e\u0642\u0650\u064a\u0631\u065e",translation:"Maka dia (Musa) memberi minum (ternak) kedua perempuan itu, kemudian dia kembali ke tempat yang teduh lalu berdoa, \"Ya Tuhanku, sesungguhnya aku sangat memerlukan kebaikan apa pun yang Engkau turunkan kepadaku"},{id:25,text:"\u0641\u064e\u062c\u064e\u0627\u0653\u0621\u064e\u062a\u06e1\u0647\u064f \u0625\u0650\u062d\u06e1\u062f\u064e\u0649\u0670\u0647\u064f\u0645\u064e\u0627 \u062a\u064e\u0645\u06e1\u0634\u0650\u064a \u0639\u064e\u0644\u064e\u0649 \u0671\u0633\u06e1\u062a\u0650\u062d\u06e1\u064a\u064e\u0627\u0653\u0621\u0656 \u0642\u064e\u0627\u0644\u064e\u062a\u06e1 \u0625\u0650\u0646\u0651\u064e \u0623\u064e\u0628\u0650\u064a \u064a\u064e\u062f\u06e1\u0639\u064f\u0648\u0643\u064e \u0644\u0650\u064a\u064e\u062c\u06e1\u0632\u0650\u064a\u064e\u0643\u064e \u0623\u064e\u062c\u06e1\u0631\u064e \u0645\u064e\u0627 \u0633\u064e\u0642\u064e\u064a\u06e1\u062a\u064e \u0644\u064e\u0646\u064e\u0627\u06da \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u06e5 \u0648\u064e\u0642\u064e\u0635\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0671\u0644\u06e1\u0642\u064e\u0635\u064e\u0635\u064e \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0627 \u062a\u064e\u062e\u064e\u0641\u06e1\u06d6 \u0646\u064e\u062c\u064e\u0648\u06e1\u062a\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Kemudian datanglah kepada Musa salah seorang dari kedua perempuan itu berjalan sambil malu-malu, dia berkata, \"Sesungguhnya ayahku mengundangmu untuk memberi balasan sebagai imbalan atas (kebaikan)mu memberi minum (ternak) kami.\" Ketika (Musa) mendatangi ayahnya (Syu'aib) dan dia menceritakan kepadanya kisah (mengenai dirinya), dia (Syu'aib) berkata, \"Janganlah engkau takut! Engkau telah selamat dari orang-orang yang zalim itu"},{id:26,text:"\u0642\u064e\u0627\u0644\u064e\u062a\u06e1 \u0625\u0650\u062d\u06e1\u062f\u064e\u0649\u0670\u0647\u064f\u0645\u064e\u0627 \u064a\u064e\u0640\u0670\u0653\u0623\u064e\u0628\u064e\u062a\u0650 \u0671\u0633\u06e1\u062a\u064e\u0640\u0654\u06e1\u062c\u0650\u0631\u06e1\u0647\u064f\u06d6 \u0625\u0650\u0646\u0651\u064e \u062e\u064e\u064a\u06e1\u0631\u064e \u0645\u064e\u0646\u0650 \u0671\u0633\u06e1\u062a\u064e\u0640\u0654\u06e1\u062c\u064e\u0631\u06e1\u062a\u064e \u0671\u0644\u06e1\u0642\u064e\u0648\u0650\u064a\u0651\u064f \u0671\u0644\u06e1\u0623\u064e\u0645\u0650\u064a\u0646\u064f",translation:"Dan salah seorang dari kedua (perempuan) itu berkata, \"Wahai ayahku! Jadikanlah dia sebagai pekerja (pada kita), sesungguhnya orang paling baik yang engkau ambil sebagai pekerja (pada kita) ialah orang yang kuat dan dapat dipercaya"},{id:27,text:"\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064f\u0631\u0650\u064a\u062f\u064f \u0623\u064e\u0646\u06e1 \u0623\u064f\u0646\u0643\u0650\u062d\u064e\u0643\u064e \u0625\u0650\u062d\u06e1\u062f\u064e\u0649 \u0671\u0628\u06e1\u0646\u064e\u062a\u064e\u064a\u0651\u064e \u0647\u064e\u0670\u062a\u064e\u064a\u06e1\u0646\u0650 \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0646 \u062a\u064e\u0623\u06e1\u062c\u064f\u0631\u064e\u0646\u0650\u064a \u062b\u064e\u0645\u064e\u0670\u0646\u0650\u064a\u064e \u062d\u0650\u062c\u064e\u062c\u0656\u06d6 \u0641\u064e\u0625\u0650\u0646\u06e1 \u0623\u064e\u062a\u06e1\u0645\u064e\u0645\u06e1\u062a\u064e \u0639\u064e\u0634\u06e1\u0631\u0657\u0627 \u0641\u064e\u0645\u0650\u0646\u06e1 \u0639\u0650\u0646\u062f\u0650\u0643\u064e\u06d6 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0631\u0650\u064a\u062f\u064f \u0623\u064e\u0646\u06e1 \u0623\u064e\u0634\u064f\u0642\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e\u06da \u0633\u064e\u062a\u064e\u062c\u0650\u062f\u064f\u0646\u0650\u064a\u0653 \u0625\u0650\u0646 \u0634\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u0650\u064a\u0646\u064e",translation:"Dia (Syu'aib) berkata, \"Sesungguhnya aku bermaksud ingin menikahkan engkau dengan salah seorang dari kedua anak perempuanku ini, dengan ketentuan bahwa engkau bekerja padaku selama delapan tahun dan jika engkau sempurnakan sepuluh tahun maka itu adalah (suatu kebaikan) darimu, dan aku tidak bermaksud memberatkan engkau. Insy\u0101 Allah engkau akan mendapatiku termasuk orang yang baik"},{id:28,text:"\u0642\u064e\u0627\u0644\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u064e\u064a\u06e1\u0646\u0650\u064a \u0648\u064e\u0628\u064e\u064a\u06e1\u0646\u064e\u0643\u064e\u06d6 \u0623\u064e\u064a\u0651\u064e\u0645\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u062c\u064e\u0644\u064e\u064a\u06e1\u0646\u0650 \u0642\u064e\u0636\u064e\u064a\u06e1\u062a\u064f \u0641\u064e\u0644\u064e\u0627 \u0639\u064f\u062f\u06e1\u0648\u064e\u0670\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u0651\u064e\u06d6 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0646\u064e\u0642\u064f\u0648\u0644\u064f \u0648\u064e\u0643\u0650\u064a\u0644\u065e",translation:"Dia (Musa) berkata, \"Itu (perjanjian) antara aku dan engkau. Yang mana saja dari kedua waktu yang ditentukan itu yang aku sempurnakan, maka tidak ada tuntutan (tambahan) atas diriku (lagi). Dan Allah menjadi saksi atas apa yang kita ucapkan"},{id:29,text:"\u06de\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0642\u064e\u0636\u064e\u0649\u0670 \u0645\u064f\u0648\u0633\u064e\u0649 \u0671\u0644\u06e1\u0623\u064e\u062c\u064e\u0644\u064e \u0648\u064e\u0633\u064e\u0627\u0631\u064e \u0628\u0650\u0623\u064e\u0647\u06e1\u0644\u0650\u0647\u0650\u06e6\u0653 \u0621\u064e\u0627\u0646\u064e\u0633\u064e \u0645\u0650\u0646 \u062c\u064e\u0627\u0646\u0650\u0628\u0650 \u0671\u0644\u0637\u0651\u064f\u0648\u0631\u0650 \u0646\u064e\u0627\u0631\u0657\u0627\u06d6 \u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0623\u064e\u0647\u06e1\u0644\u0650\u0647\u0650 \u0671\u0645\u06e1\u0643\u064f\u062b\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0621\u064e\u0627\u0646\u064e\u0633\u06e1\u062a\u064f \u0646\u064e\u0627\u0631\u0657\u0627 \u0644\u0651\u064e\u0639\u064e\u0644\u0651\u0650\u064a\u0653 \u0621\u064e\u0627\u062a\u0650\u064a\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1\u0647\u064e\u0627 \u0628\u0650\u062e\u064e\u0628\u064e\u0631\u064d \u0623\u064e\u0648\u06e1 \u062c\u064e\u0630\u06e1\u0648\u064e\u0629\u0656 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u0635\u06e1\u0637\u064e\u0644\u064f\u0648\u0646\u064e",translation:"(Maka ketika Musa telah menyelesaikan waktu yang ditentukan itu dan dia berangkat dengan keluarganya, dia melihat api di lereng gunung.608) dia berkata kepada keluarganya, \"Tunggulah (di sini), sesungguhnya aku melihat api, mudah-mudahan aku dapat membawa suatu berita kepadamu dari (tempat) api itu atau (membawa) sepercik api, agar kamu dapat menghangatkan badan"},{id:30,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u062a\u064e\u0649\u0670\u0647\u064e\u0627 \u0646\u064f\u0648\u062f\u0650\u064a\u064e \u0645\u0650\u0646 \u0634\u064e\u0670\u0637\u0650\u064a\u0655\u0650 \u0671\u0644\u06e1\u0648\u064e\u0627\u062f\u0650 \u0671\u0644\u06e1\u0623\u064e\u064a\u06e1\u0645\u064e\u0646\u0650 \u0641\u0650\u064a \u0671\u0644\u06e1\u0628\u064f\u0642\u06e1\u0639\u064e\u0629\u0650 \u0671\u0644\u06e1\u0645\u064f\u0628\u064e\u0670\u0631\u064e\u0643\u064e\u0629\u0650 \u0645\u0650\u0646\u064e \u0671\u0644\u0634\u0651\u064e\u062c\u064e\u0631\u064e\u0629\u0650 \u0623\u064e\u0646 \u064a\u064e\u0670\u0645\u064f\u0648\u0633\u064e\u0649\u0670\u0653 \u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064e\u0646\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0631\u064e\u0628\u0651\u064f \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Maka ketika dia (Musa) sampai ke (tempat) api itu, dia diseru dari (arah) pinggir sebelah kanan lembah, dari sebatang pohon, di sebidang tanah yang diberkahi, \"Wahai Musa! Sungguh, Aku adalah Allah, Tuhan seluruh alam"},{id:31,text:"\u0648\u064e\u0623\u064e\u0646\u06e1 \u0623\u064e\u0644\u06e1\u0642\u0650 \u0639\u064e\u0635\u064e\u0627\u0643\u064e\u06da \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0631\u064e\u0621\u064e\u0627\u0647\u064e\u0627 \u062a\u064e\u0647\u06e1\u062a\u064e\u0632\u0651\u064f \u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064e\u0627 \u062c\u064e\u0627\u0653\u0646\u0651\u065e \u0648\u064e\u0644\u0651\u064e\u0649\u0670 \u0645\u064f\u062f\u06e1\u0628\u0650\u0631\u0657\u0627 \u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064f\u0639\u064e\u0642\u0651\u0650\u0628\u06e1\u06da \u064a\u064e\u0670\u0645\u064f\u0648\u0633\u064e\u0649\u0670\u0653 \u0623\u064e\u0642\u06e1\u0628\u0650\u0644\u06e1 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062e\u064e\u0641\u06e1\u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u0653\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"dan lemparkanlah tongkatmu.\"Maka ketika dia (Musa) melihatnya bergerak-gerak seakan-akan seekor ular yang (gesit), dia lari berbalik ke belakang tanpa menoleh. (Allah berfirman), \"Wahai Musa! Kemarilah dan jangan takut. Sesungguhnya engkau termasuk orang yang aman"},{id:32,text:"\u0671\u0633\u06e1\u0644\u064f\u0643\u06e1 \u064a\u064e\u062f\u064e\u0643\u064e \u0641\u0650\u064a \u062c\u064e\u064a\u06e1\u0628\u0650\u0643\u064e \u062a\u064e\u062e\u06e1\u0631\u064f\u062c\u06e1 \u0628\u064e\u064a\u06e1\u0636\u064e\u0627\u0653\u0621\u064e \u0645\u0650\u0646\u06e1 \u063a\u064e\u064a\u06e1\u0631\u0650 \u0633\u064f\u0648\u0653\u0621\u0656 \u0648\u064e\u0671\u0636\u06e1\u0645\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u062c\u064e\u0646\u064e\u0627\u062d\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0631\u0651\u064e\u0647\u06e1\u0628\u0650\u06d6 \u0641\u064e\u0630\u064e\u0670\u0646\u0650\u0643\u064e \u0628\u064f\u0631\u06e1\u0647\u064e\u0670\u0646\u064e\u0627\u0646\u0650 \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0648\u064e\u0645\u064e\u0644\u064e\u0625\u0650\u064a\u0652\u0647\u0650\u06e6\u0653\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0642\u064e\u0648\u06e1\u0645\u0657\u0627 \u0641\u064e\u0670\u0633\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Masukkanlah tanganmu ke leher bajumu, dia akan keluar putih (bercahaya) tanpa cacat, dan dekapkanlah kedua tanganmu ke dadamu apabila ketakutan. Itulah dua mukjizat dari Tuhanmu (yang akan engkau pertunjukkan) kepada Fir'aun dan para pembesarnya. Sungguh, mereka adalah orang-orang fasik"},{id:33,text:"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0625\u0650\u0646\u0651\u0650\u064a \u0642\u064e\u062a\u064e\u0644\u06e1\u062a\u064f \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0646\u064e\u0641\u06e1\u0633\u0657\u0627 \u0641\u064e\u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0623\u064e\u0646 \u064a\u064e\u0642\u06e1\u062a\u064f\u0644\u064f\u0648\u0646\u0650",translation:"Dia (Musa) berkata, \"Ya Tuhanku, sungguh aku telah membunuh seorang dari golongan mereka, sehingga aku takut mereka akan membunuhku"},{id:34,text:"\u0648\u064e\u0623\u064e\u062e\u0650\u064a \u0647\u064e\u0670\u0631\u064f\u0648\u0646\u064f \u0647\u064f\u0648\u064e \u0623\u064e\u0641\u06e1\u0635\u064e\u062d\u064f \u0645\u0650\u0646\u0651\u0650\u064a \u0644\u0650\u0633\u064e\u0627\u0646\u0657\u0627 \u0641\u064e\u0623\u064e\u0631\u06e1\u0633\u0650\u0644\u06e1\u0647\u064f \u0645\u064e\u0639\u0650\u064a\u064e \u0631\u0650\u062f\u06e1\u0621\u0657\u0627 \u064a\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u064f\u0646\u0650\u064a\u0653\u06d6 \u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0623\u064e\u0646 \u064a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f\u0648\u0646\u0650",translation:"(Dan saudaraku Harun, dia lebih fasih lidahnya daripada aku,610) maka utuslah dia bersamaku sebagai pembantuku untuk membenarkan (perkataan)ku; sungguh, aku takut mereka akan mendustakanku"},{id:35,text:"\u0642\u064e\u0627\u0644\u064e \u0633\u064e\u0646\u064e\u0634\u064f\u062f\u0651\u064f \u0639\u064e\u0636\u064f\u062f\u064e\u0643\u064e \u0628\u0650\u0623\u064e\u062e\u0650\u064a\u0643\u064e \u0648\u064e\u0646\u064e\u062c\u06e1\u0639\u064e\u0644\u064f \u0644\u064e\u0643\u064f\u0645\u064e\u0627 \u0633\u064f\u0644\u06e1\u0637\u064e\u0670\u0646\u0657\u0627 \u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0635\u0650\u0644\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u064e\u0627 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627\u0653\u06da \u0623\u064e\u0646\u062a\u064f\u0645\u064e\u0627 \u0648\u064e\u0645\u064e\u0646\u0650 \u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064e\u0643\u064f\u0645\u064e\u0627 \u0671\u0644\u06e1\u063a\u064e\u0670\u0644\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Dia (Allah) berfirman, \"Kami akan menguatkan engkau (membantumu) dengan saudaramu, dan Kami berikan kepadamu berdua kekuasaan yang besar, maka mereka tidak akan dapat mencapaimu; (berangkatlah kamu berdua) dengan membawa mukjizat Kami, kamu berdua dan orang yang mengikuti kamu yang akan menang"},{id:36,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645 \u0645\u0651\u064f\u0648\u0633\u064e\u0649\u0670 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0656 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u0647\u064e\u0670\u0630\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0633\u0650\u062d\u06e1\u0631\u065e \u0645\u0651\u064f\u0641\u06e1\u062a\u064e\u0631\u0657\u0649 \u0648\u064e\u0645\u064e\u0627 \u0633\u064e\u0645\u0650\u0639\u06e1\u0646\u064e\u0627 \u0628\u0650\u0647\u064e\u0670\u0630\u064e\u0627 \u0641\u0650\u064a\u0653 \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0626\u0650\u0646\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",translation:"Maka ketika Musa datang kepada mereka dengan (membawa) mukjizat Kami yang nyata, mereka berkata, \"Ini hanyalah sihir yang dibuat-buat, dan kami tidak pernah mendengar (yang seperti) ini pada nenek moyang kami dahulu"},{id:37,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u064a\u0653 \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0646 \u062c\u064e\u0627\u0653\u0621\u064e \u0628\u0650\u0671\u0644\u06e1\u0647\u064f\u062f\u064e\u0649\u0670 \u0645\u0650\u0646\u06e1 \u0639\u0650\u0646\u062f\u0650\u0647\u0650\u06e6 \u0648\u064e\u0645\u064e\u0646 \u062a\u064e\u0643\u064f\u0648\u0646\u064f \u0644\u064e\u0647\u064f\u06e5 \u0639\u064e\u0670\u0642\u0650\u0628\u064e\u0629\u064f \u0671\u0644\u062f\u0651\u064e\u0627\u0631\u0650\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0627 \u064a\u064f\u0641\u06e1\u0644\u0650\u062d\u064f \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Dan dia (Musa) menjawab, \"Tuhanku lebih mengetahui siapa yang (pantas) membawa petunjuk dari sisi-Nya dan siapa yang akan mendapat kesudahan (yang baik) di akhirat. Sesungguhnya orang-orang yang zalim tidak akan mendapat kemenangan"},{id:38,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064f \u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0623\u064f \u0645\u064e\u0627 \u0639\u064e\u0644\u0650\u0645\u06e1\u062a\u064f \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0625\u0650\u0644\u064e\u0670\u0647\u064d \u063a\u064e\u064a\u06e1\u0631\u0650\u064a \u0641\u064e\u0623\u064e\u0648\u06e1\u0642\u0650\u062f\u06e1 \u0644\u0650\u064a \u064a\u064e\u0670\u0647\u064e\u0670\u0645\u064e\u0670\u0646\u064f \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0637\u0651\u0650\u064a\u0646\u0650 \u0641\u064e\u0671\u062c\u06e1\u0639\u064e\u0644 \u0644\u0651\u0650\u064a \u0635\u064e\u0631\u06e1\u062d\u0657\u0627 \u0644\u0651\u064e\u0639\u064e\u0644\u0651\u0650\u064a\u0653 \u0623\u064e\u0637\u0651\u064e\u0644\u0650\u0639\u064f \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u0650 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0623\u064e\u0638\u064f\u0646\u0651\u064f\u0647\u064f\u06e5 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0643\u064e\u0670\u0630\u0650\u0628\u0650\u064a\u0646\u064e",translation:"Dia Fir'aun berkata, \"Wahai para pembesar kaumku! Aku tidak mengetahui ada Tuhan bagimu selain aku. Maka bakarkanlah tanah liat untukku wahai Haman (untuk membuat batu bata), kemudian buatkanlah bangunan yang tinggi untukku agar aku dapat naik melihat Tuhannya Musa, dan aku yakin bahwa dia termasuk pendusta"},{id:39,text:"\u0648\u064e\u0671\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u064e\u0631\u064e \u0647\u064f\u0648\u064e \u0648\u064e\u062c\u064f\u0646\u064f\u0648\u062f\u064f\u0647\u064f\u06e5 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0628\u0650\u063a\u064e\u064a\u06e1\u0631\u0650 \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0638\u064e\u0646\u0651\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0644\u064e\u0627 \u064a\u064f\u0631\u06e1\u062c\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Dan dia (Fir'aun) dan bala tentaranya berlaku sombong, di bumi tanpa alasan yang benar, dan mereka mengira bahwa mereka tidak akan dikembalikan kepada Kami"},{id:40,text:"\u0641\u064e\u0623\u064e\u062e\u064e\u0630\u06e1\u0646\u064e\u0670\u0647\u064f \u0648\u064e\u062c\u064f\u0646\u064f\u0648\u062f\u064e\u0647\u064f\u06e5 \u0641\u064e\u0646\u064e\u0628\u064e\u0630\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u064a\u064e\u0645\u0651\u0650\u06d6 \u0641\u064e\u0671\u0646\u0638\u064f\u0631\u06e1 \u0643\u064e\u064a\u06e1\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0670\u0642\u0650\u0628\u064e\u0629\u064f \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Maka Kami siksa dia (Fir'aun) dan bala tentaranya, lalu Kami lemparkan mereka ke dalam laut. Maka perhatikanlah bagaimana kesudahan orang yang zalim"},{id:41,text:"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0623\u064e\u0626\u0650\u0645\u0651\u064e\u0629\u0657 \u064a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650\u06d6 \u0648\u064e\u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u0644\u064e\u0627 \u064a\u064f\u0646\u0635\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan Kami jadikan mereka para pemimpin yang mengajak (manusia) ke neraka dan pada hari Kiamat mereka tidak akan ditolong"},{id:42,text:"\u0648\u064e\u0623\u064e\u062a\u06e1\u0628\u064e\u0639\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0647\u064e\u0670\u0630\u0650\u0647\u0650 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0644\u064e\u0639\u06e1\u0646\u064e\u0629\u0657\u06d6 \u0648\u064e\u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064e\u0642\u06e1\u0628\u064f\u0648\u062d\u0650\u064a\u0646\u064e",translation:"Dan Kami susulkan laknat kepada mereka di dunia ini; sedangkan pada hari Kiamat kelak mereka termasuk orang-orang yang dijauhkan (dari rahmat Allah)"},{id:43,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0645\u064e\u0627\u0653 \u0623\u064e\u0647\u06e1\u0644\u064e\u0643\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0642\u064f\u0631\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0623\u064f\u0648\u0644\u064e\u0649\u0670 \u0628\u064e\u0635\u064e\u0627\u0653\u0626\u0650\u0631\u064e \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0647\u064f\u062f\u0657\u0649 \u0648\u064e\u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u0657 \u0644\u0651\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan sungguh, telah Kami berikan kepada Musa Kitab (Taurat) setelah Kami binasakan umat-umat terdahulu, untuk menjadi pelita bagi manusia dan petunjuk serta rahmat, agar mereka mendapat pelajaran"},{id:44,text:"\u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064e \u0628\u0650\u062c\u064e\u0627\u0646\u0650\u0628\u0650 \u0671\u0644\u06e1\u063a\u064e\u0631\u06e1\u0628\u0650\u064a\u0651\u0650 \u0625\u0650\u0630\u06e1 \u0642\u064e\u0636\u064e\u064a\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064f\u0648\u0633\u064e\u0649 \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0631\u064e \u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0634\u0651\u064e\u0640\u0670\u0647\u0650\u062f\u0650\u064a\u0646\u064e",translation:"Dan engkau (Muhammad) tidak berada di sebelah barat (lembah suci \u1e6cuwa) ketika Kami menyampaikan perintah kepada Musa, dan engkau tidak (pula) termasuk orang-orang yang menyaksikan (kejadian itu)"},{id:45,text:"\u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u0646\u0634\u064e\u0623\u06e1\u0646\u064e\u0627 \u0642\u064f\u0631\u064f\u0648\u0646\u0657\u0627 \u0641\u064e\u062a\u064e\u0637\u064e\u0627\u0648\u064e\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u064f \u0671\u0644\u06e1\u0639\u064f\u0645\u064f\u0631\u064f\u06da \u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064e \u062b\u064e\u0627\u0648\u0650\u064a\u0657\u0627 \u0641\u0650\u064a\u0653 \u0623\u064e\u0647\u06e1\u0644\u0650 \u0645\u064e\u062f\u06e1\u064a\u064e\u0646\u064e \u062a\u064e\u062a\u06e1\u0644\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0645\u064f\u0631\u06e1\u0633\u0650\u0644\u0650\u064a\u0646\u064e",translation:"tetapi Kami telah menciptakan beberapa umat, dan telah berlalu atas mereka masa yang panjang, dan engkau (Muhammad) tidak tinggal bersama-sama penduduk Madyan dengan membacakan ayat-ayat Kami kepada mereka, tetapi Kami telah mengutus rasul-rasul"},{id:46,text:"\u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064e \u0628\u0650\u062c\u064e\u0627\u0646\u0650\u0628\u0650 \u0671\u0644\u0637\u0651\u064f\u0648\u0631\u0650 \u0625\u0650\u0630\u06e1 \u0646\u064e\u0627\u062f\u064e\u064a\u06e1\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0629\u0657 \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064e \u0644\u0650\u062a\u064f\u0646\u0630\u0650\u0631\u064e \u0642\u064e\u0648\u06e1\u0645\u0657\u0627 \u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u062a\u064e\u0649\u0670\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0646\u0651\u064e\u0630\u0650\u064a\u0631\u0656 \u0645\u0651\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan engkau (Muhammad) tidak berada di dekat Tur (gunung) ketika Kami menyeru (Musa), tetapi (Kami utus engkau) sebagai rahmat dari Tuhanmu, agar engkau memberi peringatan kepada kaum (Quraisy) yang tidak didatangi oleh pemberi peringatan sebelum engkau agar mereka mendapat pelajaran"},{id:47,text:"\u0648\u064e\u0644\u064e\u0648\u06e1\u0644\u064e\u0627\u0653 \u0623\u064e\u0646 \u062a\u064f\u0635\u0650\u064a\u0628\u064e\u0647\u064f\u0645 \u0645\u0651\u064f\u0635\u0650\u064a\u0628\u064e\u0629\u064f\u06e2 \u0628\u0650\u0645\u064e\u0627 \u0642\u064e\u062f\u0651\u064e\u0645\u064e\u062a\u06e1 \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u0647\u0650\u0645\u06e1 \u0641\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627\u0652 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0644\u064e\u0648\u06e1\u0644\u064e\u0627\u0653 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u062a\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u0657\u0627 \u0641\u064e\u0646\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064e \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0643\u064e \u0648\u064e\u0646\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dan agar mereka tidak mengatakan ketika azab menimpa mereka disebabkan apa yang mereka kerjakan, \"Ya Tuhan kami, mengapa Engkau tidak mengutus seorang rasul kepada kami, agar kami mengikuti ayat-ayat Engkau dan termasuk orang mukmin"},{id:48,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f \u0645\u0650\u0646\u06e1 \u0639\u0650\u0646\u062f\u0650\u0646\u064e\u0627 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0648\u06e1\u0644\u064e\u0627\u0653 \u0623\u064f\u0648\u062a\u0650\u064a\u064e \u0645\u0650\u062b\u06e1\u0644\u064e \u0645\u064e\u0627\u0653 \u0623\u064f\u0648\u062a\u0650\u064a\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670\u0653\u06da \u0623\u064e\u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0643\u06e1\u0641\u064f\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0645\u064e\u0627\u0653 \u0623\u064f\u0648\u062a\u0650\u064a\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f\u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0633\u0650\u062d\u06e1\u0631\u064e\u0627\u0646\u0650 \u062a\u064e\u0638\u064e\u0670\u0647\u064e\u0631\u064e\u0627 \u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e\u0627 \u0628\u0650\u0643\u064f\u0644\u0651\u0656 \u0643\u064e\u0670\u0641\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Maka ketika telah datang kepada mereka kebenaran (Alquran) dari sisi Kami, mereka berkata, \"Mengapa tidak diberikan kepadanya (Muhammad) seperti apa yang telah diberikan kepada Musa dahulu?\" Bukankah mereka itu telah ingkar (juga) kepada apa yang diberikan kepada Musa dahulu? Mereka dahulu berkata, \"(Musa dan Harun adalah) dua pesihir611) yang bantu membantu.\" Dan mereka (juga) berkata, \"Sesungguhnya kami sama sekali tidak mempercayai masing-masing mereka itu"},{id:49,text:"\u0642\u064f\u0644\u06e1 \u0641\u064e\u0623\u06e1\u062a\u064f\u0648\u0627\u0652 \u0628\u0650\u0643\u0650\u062a\u064e\u0670\u0628\u0656 \u0645\u0651\u0650\u0646\u06e1 \u0639\u0650\u0646\u062f\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0647\u064f\u0648\u064e \u0623\u064e\u0647\u06e1\u062f\u064e\u0649\u0670 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u064e\u0627\u0653 \u0623\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u06e1\u0647\u064f \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0635\u064e\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Katakanlah (Muhammad), \"Datangkanlah olehmu satu kitab dari sisi Allah yang kitab itu lebih memberi petunjuk daripada keduanya (Taurat dan Alquran), niscaya aku mengikutinya, jika kamu orang yang benar"},{id:50,text:"\u0641\u064e\u0625\u0650\u0646 \u0644\u0651\u064e\u0645\u06e1 \u064a\u064e\u0633\u06e1\u062a\u064e\u062c\u0650\u064a\u0628\u064f\u0648\u0627\u0652 \u0644\u064e\u0643\u064e \u0641\u064e\u0671\u0639\u06e1\u0644\u064e\u0645\u06e1 \u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0646\u064e \u0623\u064e\u0647\u06e1\u0648\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u06e1\u06da \u0648\u064e\u0645\u064e\u0646\u06e1 \u0623\u064e\u0636\u064e\u0644\u0651\u064f \u0645\u0650\u0645\u0651\u064e\u0646\u0650 \u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064e \u0647\u064e\u0648\u064e\u0649\u0670\u0647\u064f \u0628\u0650\u063a\u064e\u064a\u06e1\u0631\u0650 \u0647\u064f\u062f\u0657\u0649 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064e\u0647\u06e1\u062f\u0650\u064a \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Maka jika mereka tidak menjawab (tantanganmu), ketahuilah bahwa mereka hanyalah mengikuti keinginan mereka. Dan siapakah yang lebih sesat daripada orang yang mengikuti keinginannya tanpa mendapat petunjuk dari Allah sedikit pun? Sungguh, Allah tidak memberi petunjuk kepada orang-orang yang zalim"},{id:51,text:"\u06de\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0648\u064e\u0635\u0651\u064e\u0644\u06e1\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0644\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan sungguh, Kami telah menyampaikan perkataan ini (Alquran) kepada mereka agar mereka selalu mengingatnya"},{id:52,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u06e6 \u0647\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Orang-orang yang telah Kami berikan kepada mereka Al-Kitab sebelum Alquran, mereka beriman (pula) kepadanya (Alquran)"},{id:53,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u064a\u064f\u062a\u06e1\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0621\u064e\u0627\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0646\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u06e6 \u0645\u064f\u0633\u06e1\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dan apabila (Alquran) dibacakan kepada mereka, mereka berkata, \"Kami beriman kepadanya, sesungguhnya (Alquran) itu adalah suatu kebenaran dari Tuhan kami. Sungguh, sebelumnya kami adalah orang muslim"},{id:54,text:"\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u064a\u064f\u0624\u06e1\u062a\u064e\u0648\u06e1\u0646\u064e \u0623\u064e\u062c\u06e1\u0631\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u0631\u0651\u064e\u062a\u064e\u064a\u06e1\u0646\u0650 \u0628\u0650\u0645\u064e\u0627 \u0635\u064e\u0628\u064e\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u064a\u064e\u062f\u06e1\u0631\u064e\u0621\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0633\u064e\u0646\u064e\u0629\u0650 \u0671\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u064e \u0648\u064e\u0645\u0650\u0645\u0651\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u064a\u064f\u0646\u0641\u0650\u0642\u064f\u0648\u0646\u064e",translation:"Mereka itu diberi pahala dua kali (karena beriman kepada Taurat dan Alquran) disebabkan kesabaran mereka, dan mereka menolak kejahatan dengan kebaikan, dan menginfakkan sebagian dari rezeki yang telah Kami berikan kepada mereka"},{id:55,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0633\u064e\u0645\u0650\u0639\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u063a\u06e1\u0648\u064e \u0623\u064e\u0639\u06e1\u0631\u064e\u0636\u064f\u0648\u0627\u0652 \u0639\u064e\u0646\u06e1\u0647\u064f \u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0646\u064e\u0627\u0653 \u0623\u064e\u0639\u06e1\u0645\u064e\u0670\u0644\u064f\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u0639\u06e1\u0645\u064e\u0670\u0644\u064f\u0643\u064f\u0645\u06e1 \u0633\u064e\u0644\u064e\u0670\u0645\u064c \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0644\u064e\u0627 \u0646\u064e\u0628\u06e1\u062a\u064e\u063a\u0650\u064a \u0671\u0644\u06e1\u062c\u064e\u0670\u0647\u0650\u0644\u0650\u064a\u0646\u064e",translation:"Dan apabila mereka mendengar perkataan yang buruk, mereka berpaling darinya dan berkata, \"Bagi kami amal-amal kami dan bagimu amal-amal kamu, semoga selamatlah kamu, kami tidak ingin (bergaul) dengan orang-orang bodoh"},{id:56,text:"\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u0627 \u062a\u064e\u0647\u06e1\u062f\u0650\u064a \u0645\u064e\u0646\u06e1 \u0623\u064e\u062d\u06e1\u0628\u064e\u0628\u06e1\u062a\u064e \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0647\u06e1\u062f\u0650\u064a \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0628\u0650\u0671\u0644\u06e1\u0645\u064f\u0647\u06e1\u062a\u064e\u062f\u0650\u064a\u0646\u064e",translation:"Sungguh, engkau (Muhammad) tidak dapat memberi petunjuk kepada orang yang engkau kasihi, tetapi Allah memberi petunjuk kepada orang yang Dia kehendaki, dan Dia lebih mengetahui orang-orang yang mau menerima petunjuk"},{id:57,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646 \u0646\u0651\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u0650 \u0671\u0644\u06e1\u0647\u064f\u062f\u064e\u0649\u0670 \u0645\u064e\u0639\u064e\u0643\u064e \u0646\u064f\u062a\u064e\u062e\u064e\u0637\u0651\u064e\u0641\u06e1 \u0645\u0650\u0646\u06e1 \u0623\u064e\u0631\u06e1\u0636\u0650\u0646\u064e\u0627\u0653\u06da \u0623\u064e\u0648\u064e\u0644\u064e\u0645\u06e1 \u0646\u064f\u0645\u064e\u0643\u0651\u0650\u0646 \u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u062d\u064e\u0631\u064e\u0645\u064b\u0627 \u0621\u064e\u0627\u0645\u0650\u0646\u0657\u0627 \u064a\u064f\u062c\u06e1\u0628\u064e\u0649\u0670\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u062b\u064e\u0645\u064e\u0631\u064e\u0670\u062a\u064f \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0631\u0651\u0650\u0632\u06e1\u0642\u0657\u0627 \u0645\u0651\u0650\u0646 \u0644\u0651\u064e\u062f\u064f\u0646\u0651\u064e\u0627 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan mereka berkata, \"Jika kami mengikuti petunjuk bersama engkau, niscaya kami akan diusir dari negeri kami.\" (Allah berfirman) Bukankah Kami telah meneguhkan kedudukan mereka dalam tanah haram (tanah suci) yang aman, yang didatangkan ke tempat itu buah-buahan dari segala macam (tumbuh-tumbuhan) sebagai rezeki (bagimu) dari sisi Kami? Tetapi kebanyakan mereka tidak mengetahui"},{id:58,text:"\u0648\u064e\u0643\u064e\u0645\u06e1 \u0623\u064e\u0647\u06e1\u0644\u064e\u0643\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646 \u0642\u064e\u0631\u06e1\u064a\u064e\u0629\u0650\u06ed \u0628\u064e\u0637\u0650\u0631\u064e\u062a\u06e1 \u0645\u064e\u0639\u0650\u064a\u0634\u064e\u062a\u064e\u0647\u064e\u0627\u06d6 \u0641\u064e\u062a\u0650\u0644\u06e1\u0643\u064e \u0645\u064e\u0633\u064e\u0670\u0643\u0650\u0646\u064f\u0647\u064f\u0645\u06e1 \u0644\u064e\u0645\u06e1 \u062a\u064f\u0633\u06e1\u0643\u064e\u0646 \u0645\u0651\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u0647\u0650\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u0657\u0627\u06d6 \u0648\u064e\u0643\u064f\u0646\u0651\u064e\u0627 \u0646\u064e\u062d\u06e1\u0646\u064f \u0671\u0644\u06e1\u0648\u064e\u0670\u0631\u0650\u062b\u0650\u064a\u0646\u064e",translation:"Dan betapa banyak (penduduk) negeri yang sudah bersenang-senang dalam kehidupannya yang telah Kami binasakan, maka itulah tempat kediaman mereka yang tidak didiami (lagi) setelah mereka, kecuali sebagian kecil. Dan Kamilah yang mewarisinya"},{id:59,text:"\u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0645\u064f\u0647\u06e1\u0644\u0650\u0643\u064e \u0671\u0644\u06e1\u0642\u064f\u0631\u064e\u0649\u0670 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0628\u06e1\u0639\u064e\u062b\u064e \u0641\u0650\u064a\u0653 \u0623\u064f\u0645\u0651\u0650\u0647\u064e\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u0657\u0627 \u064a\u064e\u062a\u06e1\u0644\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627\u06da \u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0645\u064f\u0647\u06e1\u0644\u0650\u0643\u0650\u064a \u0671\u0644\u06e1\u0642\u064f\u0631\u064e\u0649\u0670\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0648\u064e\u0623\u064e\u0647\u06e1\u0644\u064f\u0647\u064e\u0627 \u0638\u064e\u0670\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Dan Tuhanmu tidak akan membinasakan negeri-negeri, sebelum Dia mengutus seorang rasul di ibukotanya yang membacakan ayat-ayat Kami kepada mereka; dan tidak pernah (pula) Kami membinasakan (penduduk) negeri; kecuali penduduknya melakukan kezaliman"},{id:60,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0648\u062a\u0650\u064a\u062a\u064f\u0645 \u0645\u0651\u0650\u0646 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0641\u064e\u0645\u064e\u062a\u064e\u0670\u0639\u064f \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u0650 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0648\u064e\u0632\u0650\u064a\u0646\u064e\u062a\u064f\u0647\u064e\u0627\u06da \u0648\u064e\u0645\u064e\u0627 \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062e\u064e\u064a\u06e1\u0631\u065e \u0648\u064e\u0623\u064e\u0628\u06e1\u0642\u064e\u0649\u0670\u0653\u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Dan apa saja (kekayaan, jabatan, keturunan) yang diberikan kepada kamu, maka itu adalah kesenangan hidup duniawi dan perhiasannya; sedang apa yang di sisi Allah adalah lebih baik dan lebih kekal. Tidakkah kamu mengerti"},{id:61,text:"\u0623\u064e\u0641\u064e\u0645\u064e\u0646 \u0648\u064e\u0639\u064e\u062f\u06e1\u0646\u064e\u0670\u0647\u064f \u0648\u064e\u0639\u06e1\u062f\u064b\u0627 \u062d\u064e\u0633\u064e\u0646\u0657\u0627 \u0641\u064e\u0647\u064f\u0648\u064e \u0644\u064e\u0670\u0642\u0650\u064a\u0647\u0650 \u0643\u064e\u0645\u064e\u0646 \u0645\u0651\u064e\u062a\u0651\u064e\u0639\u06e1\u0646\u064e\u0670\u0647\u064f \u0645\u064e\u062a\u064e\u0670\u0639\u064e \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u0650 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u062b\u064f\u0645\u0651\u064e \u0647\u064f\u0648\u064e \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u062d\u06e1\u0636\u064e\u0631\u0650\u064a\u0646\u064e",translation:"Maka apakah sama orang yang Kami janjikan kepadanya suatu janji yang baik (surga) lalu dia memperolehnya, dengan orang yang Kami berikan kepadanya kesenangan hidup duniawi;613) kemudian pada hari Kiamat dia termasuk orang-orang yang diseret (ke dalam neraka)"},{id:62,text:"\u0648\u064e\u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064f\u0646\u064e\u0627\u062f\u0650\u064a\u0647\u0650\u0645\u06e1 \u0641\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0623\u064e\u064a\u06e1\u0646\u064e \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0653\u0621\u0650\u064a\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0632\u06e1\u0639\u064f\u0645\u064f\u0648\u0646\u064e",translation:"Dan (ingatlah) pada hari ketika Dia (Allah) menyeru mereka dan berfirman, \"Di manakah sekutu-sekutu-Ku yang dahulu kamu klaim"},{id:63,text:"\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062d\u064e\u0642\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u064f \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0644\u064f \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u063a\u06e1\u0648\u064e\u064a\u06e1\u0646\u064e\u0627\u0653 \u0623\u064e\u063a\u06e1\u0648\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0643\u064e\u0645\u064e\u0627 \u063a\u064e\u0648\u064e\u064a\u06e1\u0646\u064e\u0627\u06d6 \u062a\u064e\u0628\u064e\u0631\u0651\u064e\u0623\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e\u06d6 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u064a\u0651\u064e\u0627\u0646\u064e\u0627 \u064a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0646\u064e",translation:"Orang-orang yang sudah pasti akan mendapatkan hukuman berkata, \"Ya Tuhan kami, mereka inilah orang-orang yang kami sesatkan; kami telah menyesatkan mereka sebagaimana kami (sendiri) sesat, kami menyatakan kepada Engkau berlepas diri (dari mereka), mereka sekali-kali tidak menyembah kami"},{id:64,text:"\u0648\u064e\u0642\u0650\u064a\u0644\u064e \u0671\u062f\u06e1\u0639\u064f\u0648\u0627\u0652 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u06e1 \u0641\u064e\u062f\u064e\u0639\u064e\u0648\u06e1\u0647\u064f\u0645\u06e1 \u0641\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0633\u06e1\u062a\u064e\u062c\u0650\u064a\u0628\u064f\u0648\u0627\u0652 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0631\u064e\u0623\u064e\u0648\u064f\u0627\u0652 \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064e\u06da \u0644\u064e\u0648\u06e1 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0647\u06e1\u062a\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Dan dikatakan (kepada mereka), \"Serulah sekutu-sekutumu,\" lalu mereka menyerunya, tetapi yang diseru tidak menyambutnya, dan mereka melihat azab. (Mereka itu berkeinginan) sekiranya mereka dahulu menerima petunjuk"},{id:65,text:"\u0648\u064e\u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064f\u0646\u064e\u0627\u062f\u0650\u064a\u0647\u0650\u0645\u06e1 \u0641\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0645\u064e\u0627\u0630\u064e\u0627\u0653 \u0623\u064e\u062c\u064e\u0628\u06e1\u062a\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064f\u0631\u06e1\u0633\u064e\u0644\u0650\u064a\u0646\u064e",translation:"Dan (Ingatlah) pada hari ketika Dia (Allah) menyeru mereka, dan berfirman, \"Apakah jawabanmu terhadap para rasul"},{id:66,text:"\u0641\u064e\u0639\u064e\u0645\u0650\u064a\u064e\u062a\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u0646\u06e2\u0628\u064e\u0627\u0653\u0621\u064f \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u0641\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u062a\u064e\u0633\u064e\u0627\u0653\u0621\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Maka gelaplah bagi mereka segala macam alasan pada hari itu, karena itu mereka tidak saling bertanya"},{id:67,text:"\u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0645\u064e\u0646 \u062a\u064e\u0627\u0628\u064e \u0648\u064e\u0621\u064e\u0627\u0645\u064e\u0646\u064e \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064e \u0635\u064e\u0670\u0644\u0650\u062d\u0657\u0627 \u0641\u064e\u0639\u064e\u0633\u064e\u0649\u0670\u0653 \u0623\u064e\u0646 \u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0641\u06e1\u0644\u0650\u062d\u0650\u064a\u0646\u064e",translation:"Maka adapun orang yang bertobat dan beriman, serta mengerjakan kebajikan, maka mudah-mudahan dia termasuk orang yang beruntung"},{id:68,text:"\u0648\u064e\u0631\u064e\u0628\u0651\u064f\u0643\u064e \u064a\u064e\u062e\u06e1\u0644\u064f\u0642\u064f \u0645\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0648\u064e\u064a\u064e\u062e\u06e1\u062a\u064e\u0627\u0631\u064f\u06d7 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u062e\u0650\u064a\u064e\u0631\u064e\u0629\u064f\u06da \u0633\u064f\u0628\u06e1\u062d\u064e\u0670\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u062a\u064e\u0639\u064e\u0670\u0644\u064e\u0649\u0670 \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064f\u0634\u06e1\u0631\u0650\u0643\u064f\u0648\u0646\u064e",translation:"DanTuhanmu menciptakan dan memilih apa yang Dia kehendaki. Bagi mereka (manusia) tidak ada pilihan. Mahasuci Allah dan Mahatinggi Dia dari apa yang mereka persekutukan"},{id:69,text:"\u0648\u064e\u0631\u064e\u0628\u0651\u064f\u0643\u064e \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u062a\u064f\u0643\u0650\u0646\u0651\u064f \u0635\u064f\u062f\u064f\u0648\u0631\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0639\u06e1\u0644\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Dan Tuhanmu mengetahui apa yang disembunyikan dalam dada mereka dan apa yang mereka tampakkan"},{id:70,text:"\u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e\u06d6 \u0644\u064e\u0647\u064f \u0671\u0644\u06e1\u062d\u064e\u0645\u06e1\u062f\u064f \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064f\u0648\u0644\u064e\u0649\u0670 \u0648\u064e\u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650\u06d6 \u0648\u064e\u0644\u064e\u0647\u064f \u0671\u0644\u06e1\u062d\u064f\u0643\u06e1\u0645\u064f \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u062a\u064f\u0631\u06e1\u062c\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Dan Dialah Allah, tidak ada tuhan (yang berhak disembah) selain Dia, segala puji bagi-Nya di dunia dan di akhirat, dan bagi-Nya segala penentuan dan kepada-Nya kamu dikembalikan"},{id:71,text:"\u0642\u064f\u0644\u06e1 \u0623\u064e\u0631\u064e\u0621\u064e\u064a\u06e1\u062a\u064f\u0645\u06e1 \u0625\u0650\u0646 \u062c\u064e\u0639\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u064f \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u064e \u0633\u064e\u0631\u06e1\u0645\u064e\u062f\u064b\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u0645\u064e\u0646\u06e1 \u0625\u0650\u0644\u064e\u0670\u0647\u064c \u063a\u064e\u064a\u06e1\u0631\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u0643\u064f\u0645 \u0628\u0650\u0636\u0650\u064a\u064e\u0627\u0653\u0621\u064d\u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0633\u06e1\u0645\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Katakanlah (Muhammad), \"Bagaimana pendapatmu, jika Allah menjadikan untukmu malam itu terus menerus sampai hari Kiamat. Siapakah tuhan selain Allah yang akan mendatangkan sinar terang kepadamu? Apakah kamu tidak mendengar"},{id:72,text:"\u0642\u064f\u0644\u06e1 \u0623\u064e\u0631\u064e\u0621\u064e\u064a\u06e1\u062a\u064f\u0645\u06e1 \u0625\u0650\u0646 \u062c\u064e\u0639\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u064f \u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u0633\u064e\u0631\u06e1\u0645\u064e\u062f\u064b\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u0645\u064e\u0646\u06e1 \u0625\u0650\u0644\u064e\u0670\u0647\u064c \u063a\u064e\u064a\u06e1\u0631\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u0643\u064f\u0645 \u0628\u0650\u0644\u064e\u064a\u06e1\u0644\u0656 \u062a\u064e\u0633\u06e1\u0643\u064f\u0646\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0647\u0650\u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064f\u0628\u06e1\u0635\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Katakanlah (Muhammad), \"Bagaimana pendapatmu, jika Allah menjadikan untukmu siang itu terus menerus sampai hari Kiamat. Siapakah tuhan selain Allah yang akan mendatangkan malam kepadamu sebagai waktu istirahatmu? Apakah kamu tidak memperhatikan"},{id:73,text:"\u0648\u064e\u0645\u0650\u0646 \u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u062a\u0650\u0647\u0650\u06e6 \u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u064e \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u0644\u0650\u062a\u064e\u0633\u06e1\u0643\u064f\u0646\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0647\u0650 \u0648\u064e\u0644\u0650\u062a\u064e\u0628\u06e1\u062a\u064e\u063a\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0641\u064e\u0636\u06e1\u0644\u0650\u0647\u0650\u06e6 \u0648\u064e\u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u0634\u06e1\u0643\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Dan adalah karena rahmat-Nya, Dia jadikan untukmu malam dan siang, agar kamu beristirahat pada malam hari dan agar kamu mencari sebagian karunia-Nya (pada siang hari) dan agar kamu bersyukur kepada-Nya"},{id:74,text:"\u0648\u064e\u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064f\u0646\u064e\u0627\u062f\u0650\u064a\u0647\u0650\u0645\u06e1 \u0641\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0623\u064e\u064a\u06e1\u0646\u064e \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0653\u0621\u0650\u064a\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0632\u06e1\u0639\u064f\u0645\u064f\u0648\u0646\u064e",translation:"Dan (ingatlah) pada hari ketika Dia (Allah) menyeru mereka, dan berfirman, \"Di manakah sekutu-sekutu-Ku yang dahulu kamu klaim"},{id:75,text:"\u0648\u064e\u0646\u064e\u0632\u064e\u0639\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u0623\u064f\u0645\u0651\u064e\u0629\u0656 \u0634\u064e\u0647\u0650\u064a\u062f\u0657\u0627 \u0641\u064e\u0642\u064f\u0644\u06e1\u0646\u064e\u0627 \u0647\u064e\u0627\u062a\u064f\u0648\u0627\u0652 \u0628\u064f\u0631\u06e1\u0647\u064e\u0670\u0646\u064e\u0643\u064f\u0645\u06e1 \u0641\u064e\u0639\u064e\u0644\u0650\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0636\u064e\u0644\u0651\u064e \u0639\u064e\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0641\u06e1\u062a\u064e\u0631\u064f\u0648\u0646\u064e",translation:"(Dan Kami datangkan dari setiap umat seorang saksi,614) lalu Kami katakan, \"Kemukakanlah bukti kebenaranmu,\" maka tahulah mereka bahwa yang hak (kebenaran) itu milik Allah dan lenyaplah dari mereka apa yang dahulu mereka ada-adakan"},{id:76,text:"\u06de\u0625\u0650\u0646\u0651\u064e \u0642\u064e\u0670\u0631\u064f\u0648\u0646\u064e \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0648\u06e1\u0645\u0650 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0641\u064e\u0628\u064e\u063a\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1\u06d6 \u0648\u064e\u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0643\u064f\u0646\u064f\u0648\u0632\u0650 \u0645\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e \u0645\u064e\u0641\u064e\u0627\u062a\u0650\u062d\u064e\u0647\u064f\u06e5 \u0644\u064e\u062a\u064e\u0646\u064f\u0648\u0653\u0623\u064f \u0628\u0650\u0671\u0644\u06e1\u0639\u064f\u0635\u06e1\u0628\u064e\u0629\u0650 \u0623\u064f\u0648\u0652\u0644\u0650\u064a \u0671\u0644\u06e1\u0642\u064f\u0648\u0651\u064e\u0629\u0650 \u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f\u06e5 \u0642\u064e\u0648\u06e1\u0645\u064f\u0647\u064f\u06e5 \u0644\u064e\u0627 \u062a\u064e\u0641\u06e1\u0631\u064e\u062d\u06e1\u06d6 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0671\u0644\u06e1\u0641\u064e\u0631\u0650\u062d\u0650\u064a\u0646\u064e",translation:"(Sesungguhnya Karun termasuk kaum Musa,615) tetapi dia berlaku zalim terhadap mereka, dan Kami telah menganugerahkan kepadanya perbendaraan harta yang kunci-kuncinya sungguh berat dipikul oleh sejumlah orang yang kuat-kuat. (Ingatlah) ketika kaumnya berkata kepadanya, \"Janganlah engkau terlalu bangga. Sungguh, Allah tidak menyukai orang yang membanggakan diri"},{id:77,text:"\u0648\u064e\u0671\u0628\u06e1\u062a\u064e\u063a\u0650 \u0641\u0650\u064a\u0645\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u064e\u0649\u0670\u0643\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u062f\u0651\u064e\u0627\u0631\u064e \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u064e\u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0646\u0633\u064e \u0646\u064e\u0635\u0650\u064a\u0628\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627\u06d6 \u0648\u064e\u0623\u064e\u062d\u06e1\u0633\u0650\u0646 \u0643\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e\u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0628\u06e1\u063a\u0650 \u0671\u0644\u06e1\u0641\u064e\u0633\u064e\u0627\u062f\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d6 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0671\u0644\u06e1\u0645\u064f\u0641\u06e1\u0633\u0650\u062f\u0650\u064a\u0646\u064e",translation:"Dan carilah (pahala) negeri akhirat dengan apa yang telah dianugerahkan Allah kepadamu, tetapi janganlah kamu lupakan bagianmu di dunia dan berbuat baiklah (kepada orang lain) sebagaimana Allah telah berbuat baik kepadamu, dan janganlah kamu berbuat kerusakan di bumi. Sungguh, Allah tidak menyukai orang yang berbuat kerusakan"},{id:78,text:"\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0648\u062a\u0650\u064a\u062a\u064f\u0647\u064f\u06e5 \u0639\u064e\u0644\u064e\u0649\u0670 \u0639\u0650\u0644\u06e1\u0645\u064d \u0639\u0650\u0646\u062f\u0650\u064a\u0653\u06da \u0623\u064e\u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u06e1 \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0642\u064e\u062f\u06e1 \u0623\u064e\u0647\u06e1\u0644\u064e\u0643\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u06e6 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0642\u064f\u0631\u064f\u0648\u0646\u0650 \u0645\u064e\u0646\u06e1 \u0647\u064f\u0648\u064e \u0623\u064e\u0634\u064e\u062f\u0651\u064f \u0645\u0650\u0646\u06e1\u0647\u064f \u0642\u064f\u0648\u0651\u064e\u0629\u0657 \u0648\u064e\u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064f \u062c\u064e\u0645\u06e1\u0639\u0657\u0627\u06da \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0633\u06e1\u0640\u0654\u064e\u0644\u064f \u0639\u064e\u0646 \u0630\u064f\u0646\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u064f \u0671\u0644\u06e1\u0645\u064f\u062c\u06e1\u0631\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Dia (Karun) berkata, \"Sesungguhnya aku diberi (harta itu), semata-mata karena ilmu yang ada padaku.\" Tidakkah dia tahu, bahwa Allah telah membinasakan umat-umat sebelumnya yang lebih kuat daripadanya, dan lebih banyak mengumpulkan harta? Dan orang-orang yang berdosa itu tidak perlu ditanya tentang dosa-dosa mereka"},{id:79,text:"\u0641\u064e\u062e\u064e\u0631\u064e\u062c\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u06e6 \u0641\u0650\u064a \u0632\u0650\u064a\u0646\u064e\u062a\u0650\u0647\u0650\u06e6\u06d6 \u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u064e \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u064a\u064e\u0670\u0644\u064e\u064a\u06e1\u062a\u064e \u0644\u064e\u0646\u064e\u0627 \u0645\u0650\u062b\u06e1\u0644\u064e \u0645\u064e\u0627\u0653 \u0623\u064f\u0648\u062a\u0650\u064a\u064e \u0642\u064e\u0670\u0631\u064f\u0648\u0646\u064f \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0630\u064f\u0648 \u062d\u064e\u0638\u0651\u064d \u0639\u064e\u0638\u0650\u064a\u0645\u0656",translation:"Maka keluarlah dia (Karun) kepada kaumnya dengan kemegahannya. Orang-orang yang menginginkan kehidupan dunia berkata, \"Mudah-mudahan kita mempunyai harta kekayaan seperti apa yang telah diberikan kepada Karun, sesungguhnya dia benar-benar mempunyai keberuntungan yang besar"},{id:80,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0639\u0650\u0644\u06e1\u0645\u064e \u0648\u064e\u064a\u06e1\u0644\u064e\u0643\u064f\u0645\u06e1 \u062b\u064e\u0648\u064e\u0627\u0628\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062e\u064e\u064a\u06e1\u0631\u065e \u0644\u0651\u0650\u0645\u064e\u0646\u06e1 \u0621\u064e\u0627\u0645\u064e\u0646\u064e \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064e \u0635\u064e\u0670\u0644\u0650\u062d\u0657\u0627\u06da \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0644\u064e\u0642\u0651\u064e\u0649\u0670\u0647\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0628\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Tetapi orang-orang yang dianugerahi ilmu berkata, \"Celakalah kamu! Ketahuilah, pahala Allah lebih baik bagi orang-orang yang beriman dan mengerjakan kebajikan, dan (pahala yang besar) itu hanya diperoleh oleh orang-orang yang sabar"},{id:81,text:"\u0641\u064e\u062e\u064e\u0633\u064e\u0641\u06e1\u0646\u064e\u0627 \u0628\u0650\u0647\u0650\u06e6 \u0648\u064e\u0628\u0650\u062f\u064e\u0627\u0631\u0650\u0647\u0650 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0641\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646 \u0641\u0650\u0626\u064e\u0629\u0656 \u064a\u064e\u0646\u0635\u064f\u0631\u064f\u0648\u0646\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0646\u062a\u064e\u0635\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Maka Kami benamkan dia (Karun) bersama rumahnya ke dalam bumi. Maka tidak ada baginya satu golongan pun yang akan menolongnya selain Allah, dan dia tidak termasuk orang-orang yang dapat membela diri"},{id:82,text:"\u0648\u064e\u0623\u064e\u0635\u06e1\u0628\u064e\u062d\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u0645\u064e\u0646\u0651\u064e\u0648\u06e1\u0627\u0652 \u0645\u064e\u0643\u064e\u0627\u0646\u064e\u0647\u064f\u06e5 \u0628\u0650\u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0633\u0650 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0648\u064e\u064a\u06e1\u0643\u064e\u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0628\u06e1\u0633\u064f\u0637\u064f \u0671\u0644\u0631\u0651\u0650\u0632\u06e1\u0642\u064e \u0644\u0650\u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0645\u0650\u0646\u06e1 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650\u06e6 \u0648\u064e\u064a\u064e\u0642\u06e1\u062f\u0650\u0631\u064f\u06d6 \u0644\u064e\u0648\u06e1\u0644\u064e\u0627\u0653 \u0623\u064e\u0646 \u0645\u0651\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0644\u064e\u062e\u064e\u0633\u064e\u0641\u064e \u0628\u0650\u0646\u064e\u0627\u06d6 \u0648\u064e\u064a\u06e1\u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0627 \u064a\u064f\u0641\u06e1\u0644\u0650\u062d\u064f \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Dan orang-orang yang kemarin mengangan-angankan kedudukannya (Karun) itu berkata, \"Aduhai, benarlah kiranya Allah yang melapangkan rezeki bagi siapa yang Dia kehendaki di antara hamba-hamba-Nya dan membatasi (bagi siapa yang Dia kehendaki di antara hamba-hamba-Nya). Sekiranya Allah tidak melimpahkan karunia-Nya pada kita, tentu Dia telah membenamkan kita pula. Aduhai, benarlah kiranya tidak akan beruntung orang-orang yang mengingkari (nikmat Allah)"},{id:83,text:"\u062a\u0650\u0644\u06e1\u0643\u064e \u0671\u0644\u062f\u0651\u064e\u0627\u0631\u064f \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u064f \u0646\u064e\u062c\u06e1\u0639\u064e\u0644\u064f\u0647\u064e\u0627 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0639\u064f\u0644\u064f\u0648\u0651\u0657\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0644\u064e\u0627 \u0641\u064e\u0633\u064e\u0627\u062f\u0657\u0627\u06da \u0648\u064e\u0671\u0644\u06e1\u0639\u064e\u0670\u0642\u0650\u0628\u064e\u0629\u064f \u0644\u0650\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",translation:"Negeri akhirat itu Kami jadikan bagi orang-orang yang tidak menyombongkan diri dan tidak berbuat kerusakan di bumi. Dan kesudahan (yang baik)616) itu bagi orang-orang yang bertakwa"},{id:84,text:"\u0645\u064e\u0646 \u062c\u064e\u0627\u0653\u0621\u064e \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0633\u064e\u0646\u064e\u0629\u0650 \u0641\u064e\u0644\u064e\u0647\u064f\u06e5 \u062e\u064e\u064a\u06e1\u0631\u065e \u0645\u0651\u0650\u0646\u06e1\u0647\u064e\u0627\u06d6 \u0648\u064e\u0645\u064e\u0646 \u062c\u064e\u0627\u0653\u0621\u064e \u0628\u0650\u0671\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u0650 \u0641\u064e\u0644\u064e\u0627 \u064a\u064f\u062c\u06e1\u0632\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0640\u0654\u064e\u0627\u062a\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Barang siapa yang datang dengan (membawa) kebaikan, maka dia akan mendapat (pahala) yang lebih baik daripada kebaikannya itu; dan barang siapa datang dengan (membawa) kejahatan, maka orang-orang yang telah mengerjakan kejahatan itu hanya diberi balasan (seimbang) dengan apa yang dahulu mereka kerjakan"},{id:85,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0641\u064e\u0631\u064e\u0636\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u064e \u0644\u064e\u0631\u064e\u0627\u0653\u062f\u0651\u064f\u0643\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064e\u0639\u064e\u0627\u062f\u0656\u06da \u0642\u064f\u0644 \u0631\u0651\u064e\u0628\u0651\u0650\u064a\u0653 \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0646 \u062c\u064e\u0627\u0653\u0621\u064e \u0628\u0650\u0671\u0644\u06e1\u0647\u064f\u062f\u064e\u0649\u0670 \u0648\u064e\u0645\u064e\u0646\u06e1 \u0647\u064f\u0648\u064e \u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0670\u0644\u0656 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u0656",translation:"Sesungguhnya (Allah) yang mewajibkan engkau (Muhammad) untuk (melaksanakan hukum-hukum) Alquran, benar-benar akan mengembalikanmu ke tempat kembali.617) Katakanlah (Muhammad), \"Tuhanku mengetahui orang yang membawa petunjuk dan orang yang berada dalam kesesatan yang nyata"},{id:86,text:"\u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064e \u062a\u064e\u0631\u06e1\u062c\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646 \u064a\u064f\u0644\u06e1\u0642\u064e\u0649\u0670\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u0657 \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064e\u06d6 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064e\u0646\u0651\u064e \u0638\u064e\u0647\u0650\u064a\u0631\u0657\u0627 \u0644\u0651\u0650\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan engkau (Muhammad) tidak pernah mengharap agar Kitab (Alquran) itu diturunkan kepadamu, tetapi ia (diturunkan) sebagai rahmat dari Tuhanmu, sebab itu janganlah sekali-kali engkau menjadi penolong bagi orang-orang kafir"},{id:87,text:"\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0635\u064f\u062f\u0651\u064f\u0646\u0651\u064e\u0643\u064e \u0639\u064e\u0646\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u064e\u0639\u06e1\u062f\u064e \u0625\u0650\u0630\u06e1 \u0623\u064f\u0646\u0632\u0650\u0644\u064e\u062a\u06e1 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e\u06d6 \u0648\u064e\u0671\u062f\u06e1\u0639\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u064e\u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0634\u06e1\u0631\u0650\u0643\u0650\u064a\u0646\u064e",translation:"dan jangan sampai mereka menghalang-halangi engkau (Muhammad) untuk (menyampaikan) ayat-ayat Allah, setelah ayat-ayat itu diturunkan kepadamu, dan serulah (manusia) agar (beriman) kepada Tuhanmu, dan janganlah engkau termasuk orang-orang musyrik"},{id:88,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062f\u06e1\u0639\u064f \u0645\u064e\u0639\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u064e\u0670\u0647\u064b\u0627 \u0621\u064e\u0627\u062e\u064e\u0631\u064e\u06d8 \u0644\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e\u06da \u0643\u064f\u0644\u0651\u064f \u0634\u064e\u064a\u06e1\u0621\u064d \u0647\u064e\u0627\u0644\u0650\u0643\u064c \u0625\u0650\u0644\u0651\u064e\u0627 \u0648\u064e\u062c\u06e1\u0647\u064e\u0647\u064f\u06e5\u06da \u0644\u064e\u0647\u064f \u0671\u0644\u06e1\u062d\u064f\u0643\u06e1\u0645\u064f \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u062a\u064f\u0631\u06e1\u062c\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Dan Jangan (pula) engkau sembah tuhan yang lain selain Allah. Tidak ada tuhan (yang berhak disembah) selain Dia. Segala sesuatu pasti binasa, kecuali Allah. Segala keputusan menjadi wewenang-Nya, dan hanya kepada-Nya kamu dikembalikan"}]},{id:29,name:"\u0627\u0644\u0639\u0646\u0643\u0628\u0648\u062a",transliteration:"Al-'Ankabut",translation:"Laba-laba",type:"meccan",total_verses:69,verses:[{id:1,text:"\u0627\u0644\u0653\u0645\u0653",translation:"Alif l\u0101m m\u012bm"},{id:2,text:"\u0623\u064e\u062d\u064e\u0633\u0650\u0628\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0623\u064e\u0646 \u064a\u064f\u062a\u06e1\u0631\u064e\u0643\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0653\u0627\u0652 \u0621\u064e\u0627\u0645\u064e\u0646\u0651\u064e\u0627 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064f\u0641\u06e1\u062a\u064e\u0646\u064f\u0648\u0646\u064e",translation:"Apakah manusia mengira bahwa mereka akan dibiarkan hanya dengan mengatakan, \"Kami telah beriman,\" dan mereka tidak diuji"},{id:3,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0641\u064e\u062a\u064e\u0646\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u0645\u06e1\u06d6 \u0641\u064e\u0644\u064e\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0635\u064e\u062f\u064e\u0642\u064f\u0648\u0627\u0652 \u0648\u064e\u0644\u064e\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064e\u0646\u0651\u064e \u0671\u0644\u06e1\u0643\u064e\u0670\u0630\u0650\u0628\u0650\u064a\u0646\u064e",translation:"Dan sungguh, Kami telah menguji orang-orang sebelum mereka, maka Allah pasti mengetahui orang-orang yang benar dan pasti mengetahui orang-orang yang dusta"},{id:4,text:"\u0623\u064e\u0645\u06e1 \u062d\u064e\u0633\u0650\u0628\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0640\u0654\u064e\u0627\u062a\u0650 \u0623\u064e\u0646 \u064a\u064e\u0633\u06e1\u0628\u0650\u0642\u064f\u0648\u0646\u064e\u0627\u06da \u0633\u064e\u0627\u0653\u0621\u064e \u0645\u064e\u0627 \u064a\u064e\u062d\u06e1\u0643\u064f\u0645\u064f\u0648\u0646\u064e",translation:"Ataukah orang-orang yang mengerjakan kejahatan itu mengira bahwa mereka akan luput dari (azab) Kami? Sangatlah buruk apa yang mereka tetapkan itu"},{id:5,text:"\u0645\u064e\u0646 \u0643\u064e\u0627\u0646\u064e \u064a\u064e\u0631\u06e1\u062c\u064f\u0648\u0627\u0652 \u0644\u0650\u0642\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0623\u064e\u062c\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0623\u0653\u062a\u0656\u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u0650\u064a\u0639\u064f \u0671\u0644\u06e1\u0639\u064e\u0644\u0650\u064a\u0645\u064f",translation:"Barang siapa mengharap pertemuan dengan Allah, maka sesungguhnya waktu (yang dijanjikan) Allah pasti datang. Dan Dia Yang Maha Mendengar, Maha Mengetahui"},{id:6,text:"\u0648\u064e\u0645\u064e\u0646 \u062c\u064e\u0670\u0647\u064e\u062f\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064f\u062c\u064e\u0670\u0647\u0650\u062f\u064f \u0644\u0650\u0646\u064e\u0641\u06e1\u0633\u0650\u0647\u0650\u06e6\u0653\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u063a\u064e\u0646\u0650\u064a\u0651\u064c \u0639\u064e\u0646\u0650 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Dan barangsiapa berjihad, maka sesungguhnya jihadnya itu untuk dirinya sendiri. Sungguh, Allah Mahakaya (tidak memerlukan sesuatu) dari seluruh alam"},{id:7,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0644\u064e\u0646\u064f\u0643\u064e\u0641\u0651\u0650\u0631\u064e\u0646\u0651\u064e \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0633\u064e\u064a\u0651\u0650\u0640\u0654\u064e\u0627\u062a\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0644\u064e\u0646\u064e\u062c\u06e1\u0632\u0650\u064a\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan orang-orang yang beriman dan mengerjakan kebajikan, pasti akan Kami hapus kesalahan-kesalahannya dan mereka pasti akan Kami beri balasan yang lebih baik dari apa yang mereka kerjakan"},{id:8,text:"\u0648\u064e\u0648\u064e\u0635\u0651\u064e\u064a\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064e \u0628\u0650\u0648\u064e\u0670\u0644\u0650\u062f\u064e\u064a\u06e1\u0647\u0650 \u062d\u064f\u0633\u06e1\u0646\u0657\u0627\u06d6 \u0648\u064e\u0625\u0650\u0646 \u062c\u064e\u0670\u0647\u064e\u062f\u064e\u0627\u0643\u064e \u0644\u0650\u062a\u064f\u0634\u06e1\u0631\u0650\u0643\u064e \u0628\u0650\u064a \u0645\u064e\u0627 \u0644\u064e\u064a\u06e1\u0633\u064e \u0644\u064e\u0643\u064e \u0628\u0650\u0647\u0650\u06e6 \u0639\u0650\u0644\u06e1\u0645\u065e \u0641\u064e\u0644\u064e\u0627 \u062a\u064f\u0637\u0650\u0639\u06e1\u0647\u064f\u0645\u064e\u0627\u0653\u06da \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0645\u064e\u0631\u06e1\u062c\u0650\u0639\u064f\u0643\u064f\u0645\u06e1 \u0641\u064e\u0623\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0643\u064f\u0645 \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan Kami wajibkan kepada manusia agar (berbuat) kebaikan kepada kedua orang tuanya. Dan jika keduanya memaksamu untuk mempersekutukan Aku dengan sesuatu yang engkau tidak mempunyai ilmu tentang itu, maka janganlah engkau patuhi keduanya. Hanya kepada-Ku tempat kembalimu, dan akan Aku beritakan kepadamu apa yang telah kamu kerjakan"},{id:9,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0644\u064e\u0646\u064f\u062f\u06e1\u062e\u0650\u0644\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u0650\u064a\u0646\u064e",translation:"Dan orang-orang yang beriman dan mengerjakan kebajikan, mereka pasti akan Kami masukkan ke dalam (golongan) orang yang saleh"},{id:10,text:"\u0648\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0645\u064e\u0646 \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0621\u064e\u0627\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0625\u0650\u0630\u064e\u0627\u0653 \u0623\u064f\u0648\u0630\u0650\u064a\u064e \u0641\u0650\u064a \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062c\u064e\u0639\u064e\u0644\u064e \u0641\u0650\u062a\u06e1\u0646\u064e\u0629\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0643\u064e\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0648\u064e\u0644\u064e\u0626\u0650\u0646 \u062c\u064e\u0627\u0653\u0621\u064e \u0646\u064e\u0635\u06e1\u0631\u065e \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064e \u0644\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0646\u0651\u064e \u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0645\u064e\u0639\u064e\u0643\u064f\u0645\u06e1\u06da \u0623\u064e\u0648\u064e\u0644\u064e\u064a\u06e1\u0633\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064e \u0628\u0650\u0645\u064e\u0627 \u0641\u0650\u064a \u0635\u064f\u062f\u064f\u0648\u0631\u0650 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Dan di antara manusia ada sebagian yang berkata, \"Kami beriman kepada Allah,\" tetapi apabila dia disakiti (karena dia beriman) kepada Allah, dia menganggap cobaan manusia itu sebagai siksaan Allah.618) Dan jika datang pertolongan dari Tuhanmu, niscaya mereka akan berkata, \"Sesungguhnya kami bersama kamu.\" Bukankah Allah lebih mengetahui apa yang ada di dalam dada semua manusia"},{id:11,text:"\u0648\u064e\u0644\u064e\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0644\u064e\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064e\u0646\u0651\u064e \u0671\u0644\u06e1\u0645\u064f\u0646\u064e\u0670\u0641\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Dan Allah pasti mengetahui orang-orang yang beriman dan Dia pasti mengetahui orang-orang yang munafik"},{id:12,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0671\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0627\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u064e\u0646\u064e\u0627 \u0648\u064e\u0644\u06e1\u0646\u064e\u062d\u06e1\u0645\u0650\u0644\u06e1 \u062e\u064e\u0637\u064e\u0670\u064a\u064e\u0670\u0643\u064f\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627 \u0647\u064f\u0645 \u0628\u0650\u062d\u064e\u0670\u0645\u0650\u0644\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u06e1 \u062e\u064e\u0637\u064e\u0670\u064a\u064e\u0670\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0634\u064e\u064a\u06e1\u0621\u064d\u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0643\u064e\u0670\u0630\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Dan orang-orang yang kafir berkata kepada orang-orang yang beriman, \"Ikutilah jalan kami, dan kami akan memikul dosa-dosamu,\" padahal mereka sedikit pun tidak (sanggup) memikul dosa-dosa mereka sendiri. Sesungguhnya mereka benar-benar pendusta"},{id:13,text:"\u0648\u064e\u0644\u064e\u064a\u064e\u062d\u06e1\u0645\u0650\u0644\u064f\u0646\u0651\u064e \u0623\u064e\u062b\u06e1\u0642\u064e\u0627\u0644\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u062b\u06e1\u0642\u064e\u0627\u0644\u0657\u0627 \u0645\u0651\u064e\u0639\u064e \u0623\u064e\u062b\u06e1\u0642\u064e\u0627\u0644\u0650\u0647\u0650\u0645\u06e1\u06d6 \u0648\u064e\u0644\u064e\u064a\u064f\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0646\u0651\u064e \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u0639\u064e\u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0641\u06e1\u062a\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan mereka benar-benar akan memikul dosa-dosa mereka sendiri, dan dosa-dosa yang lain bersama dosa mereka, dan pada hari Kiamat mereka pasti akan ditanya tentang kebohongan yang selalu mereka ada-adakan"},{id:14,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0646\u064f\u0648\u062d\u064b\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u06e6 \u0641\u064e\u0644\u064e\u0628\u0650\u062b\u064e \u0641\u0650\u064a\u0647\u0650\u0645\u06e1 \u0623\u064e\u0644\u06e1\u0641\u064e \u0633\u064e\u0646\u064e\u0629\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u062e\u064e\u0645\u06e1\u0633\u0650\u064a\u0646\u064e \u0639\u064e\u0627\u0645\u0657\u0627 \u0641\u064e\u0623\u064e\u062e\u064e\u0630\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0637\u0651\u064f\u0648\u0641\u064e\u0627\u0646\u064f \u0648\u064e\u0647\u064f\u0645\u06e1 \u0638\u064e\u0670\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Dan sungguh, Kami telah mengutus Nuh kepada kaumnya, maka dia tinggal bersama mereka seribu tahun kurang lima puluh tahun. Kemudian mereka dilanda banjir besar, sedangkan mereka adalah orang-orang yang zalim"},{id:15,text:"\u0641\u064e\u0623\u064e\u0646\u062c\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f \u0648\u064e\u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064e \u0671\u0644\u0633\u0651\u064e\u0641\u0650\u064a\u0646\u064e\u0629\u0650 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064e\u0627\u0653 \u0621\u064e\u0627\u064a\u064e\u0629\u0657 \u0644\u0651\u0650\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Maka Kami selamatkan Nuh dan orang-orang yang berada di kapal itu, dan Kami jadikan (peristiwa) itu sebagai pelajaran bagi semua manusia"},{id:16,text:"\u0648\u064e\u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064e \u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650 \u0671\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0647\u064f\u06d6 \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u06e1 \u062e\u064e\u064a\u06e1\u0631\u065e \u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan (ingatlah) Ibrahim, ketika dia berkata kepada kaumnya, \"Sembahlah Allah dan bertakwalah kepada-Nya. Yang demikian itu lebih baik bagimu, jika kamu mengetahui"},{id:17,text:"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0648\u06e1\u062b\u064e\u0670\u0646\u0657\u0627 \u0648\u064e\u062a\u064e\u062e\u06e1\u0644\u064f\u0642\u064f\u0648\u0646\u064e \u0625\u0650\u0641\u06e1\u0643\u064b\u0627\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0627 \u064a\u064e\u0645\u06e1\u0644\u0650\u0643\u064f\u0648\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u06e1 \u0631\u0650\u0632\u06e1\u0642\u0657\u0627 \u0641\u064e\u0671\u0628\u06e1\u062a\u064e\u063a\u064f\u0648\u0627\u0652 \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u0631\u0651\u0650\u0632\u06e1\u0642\u064e \u0648\u064e\u0671\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0647\u064f \u0648\u064e\u0671\u0634\u06e1\u0643\u064f\u0631\u064f\u0648\u0627\u0652 \u0644\u064e\u0647\u064f\u06e5\u0653\u06d6 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u062a\u064f\u0631\u06e1\u062c\u064e\u0639\u064f\u0648\u0646\u064e",translation:"(Sesungguhnya yang kamu sembah selain Allah hanyalah berhala-berhala, dan kamu membuat kebohongan.619) Sesungguhnya apa yang kamu sembah selain Allah itu tidak mampu memberikan rezeki kepadamu; maka mintalah rezeki dari Allah, dan sembahlah Dia dan bersyukurlah kepada-Nya. Hanya kepada-Nya kamu akan dikembalikan"},{id:18,text:"\u0648\u064e\u0625\u0650\u0646 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f\u0648\u0627\u0652 \u0641\u064e\u0642\u064e\u062f\u06e1 \u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0623\u064f\u0645\u064e\u0645\u065e \u0645\u0651\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0645\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u06e1\u0628\u064e\u0644\u064e\u0670\u063a\u064f \u0671\u0644\u06e1\u0645\u064f\u0628\u0650\u064a\u0646\u064f",translation:"Dan jika kamu (orang kafir) mendustakan, maka sungguh, umat sebelum kamu juga telah mendustakan (para rasul). Dan kewajiban rasul itu hanyalah menyampaikan (agama Allah) dengan jelas"},{id:19,text:"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0631\u064e\u0648\u06e1\u0627\u0652 \u0643\u064e\u064a\u06e1\u0641\u064e \u064a\u064f\u0628\u06e1\u062f\u0650\u0626\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u062e\u064e\u0644\u06e1\u0642\u064e \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0639\u0650\u064a\u062f\u064f\u0647\u064f\u06e5\u0653\u06da \u0625\u0650\u0646\u0651\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u0633\u0650\u064a\u0631\u065e",translation:"Dan apakah mereka tidak memperhatikan bagaimana Allah memulai penciptaan (makhluk), kemudian Dia mengulanginya (kembali). Sungguh, yang demikian itu mudah bagi Allah"},{id:20,text:"\u0642\u064f\u0644\u06e1 \u0633\u0650\u064a\u0631\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0641\u064e\u0671\u0646\u0638\u064f\u0631\u064f\u0648\u0627\u0652 \u0643\u064e\u064a\u06e1\u0641\u064e \u0628\u064e\u062f\u064e\u0623\u064e \u0671\u0644\u06e1\u062e\u064e\u0644\u06e1\u0642\u064e\u06da \u062b\u064f\u0645\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064f\u0646\u0634\u0650\u0626\u064f \u0671\u0644\u0646\u0651\u064e\u0634\u06e1\u0623\u064e\u0629\u064e \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u064e\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0642\u064e\u062f\u0650\u064a\u0631\u065e",translation:"Katakanlah, \"Berjalanlah di bumi, maka perhatikanlah bagaimana (Allah) memulai penciptaan (makhluk), kemudian Allah menjadikan kejadian yang akhir.620) Sungguh, Allah Mahakuasa atas segala sesuatu"},{id:21,text:"\u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064f \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0648\u064e\u064a\u064e\u0631\u06e1\u062d\u064e\u0645\u064f \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06d6 \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u062a\u064f\u0642\u06e1\u0644\u064e\u0628\u064f\u0648\u0646\u064e",translation:"Dia (Allah) mengazab siapa yang Dia kehendaki dan memberi rahmat kepada siapa yang Dia kehendaki, dan hanya kepada-Nya kamu akan dikembalikan"},{id:22,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064f\u0645 \u0628\u0650\u0645\u064f\u0639\u06e1\u062c\u0650\u0632\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0644\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650\u06d6 \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646 \u0648\u064e\u0644\u0650\u064a\u0651\u0656 \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0635\u0650\u064a\u0631\u0656",translation:"Dan kamu sama sekali tidak dapat melepaskan diri (dari azab Allah) baik di bumi maupun di langit, dan tidak ada pelindung dan penolong bagimu selain Allah"},{id:23,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u0650\u0642\u064e\u0627\u0653\u0626\u0650\u0647\u0650\u06e6\u0653 \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u064a\u064e\u0626\u0650\u0633\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u062a\u0650\u064a \u0648\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Dan orang-orang yang mengingkari ayat-ayat Allah dan pertemuan dengan-Nya, mereka putus asa dari rahmat-Ku, dan mereka itu akan mendapat azab yang pedih"},{id:24,text:"\u0641\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u062c\u064e\u0648\u064e\u0627\u0628\u064e \u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0671\u0642\u06e1\u062a\u064f\u0644\u064f\u0648\u0647\u064f \u0623\u064e\u0648\u06e1 \u062d\u064e\u0631\u0651\u0650\u0642\u064f\u0648\u0647\u064f \u0641\u064e\u0623\u064e\u0646\u062c\u064e\u0649\u0670\u0647\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650\u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0623\u0653\u064a\u064e\u0670\u062a\u0656 \u0644\u0651\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Maka tidak ada jawaban kaumnya (Ibrahim), selain mengatakan, \"Bunuhlah atau bakarlah dia,\" lalu Allah menyelamatkannya dari api. Sungguh, pada yang demikian itu pasti terdapat tanda-tanda (kebesaran Allah) bagi orang yang beriman"},{id:25,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0671\u062a\u0651\u064e\u062e\u064e\u0630\u06e1\u062a\u064f\u0645 \u0645\u0651\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0648\u06e1\u062b\u064e\u0670\u0646\u0657\u0627 \u0645\u0651\u064e\u0648\u064e\u062f\u0651\u064e\u0629\u064e \u0628\u064e\u064a\u06e1\u0646\u0650\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u0650 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627\u06d6 \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u064a\u064e\u0643\u06e1\u0641\u064f\u0631\u064f \u0628\u064e\u0639\u06e1\u0636\u064f\u0643\u064f\u0645 \u0628\u0650\u0628\u064e\u0639\u06e1\u0636\u0656 \u0648\u064e\u064a\u064e\u0644\u06e1\u0639\u064e\u0646\u064f \u0628\u064e\u0639\u06e1\u0636\u064f\u0643\u064f\u0645 \u0628\u064e\u0639\u06e1\u0636\u0657\u0627 \u0648\u064e\u0645\u064e\u0623\u06e1\u0648\u064e\u0649\u0670\u0643\u064f\u0645\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u064f \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0646\u0651\u064e\u0640\u0670\u0635\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan dia (Ibrahim) berkata, \"Sesungguhnya berhala-berhala yang kamu sembah selain Allah, hanya untuk menciptakan perasaan kasih sayang di antara kamu dalam kehidupan di dunia, kemudian pada hari Kiamat sebagian kamu akan saling mengingkari dan saling mengutuk; dan tempat kembalimu ialah neraka, dan sama sekali tidak ada penolong bagimu"},{id:26,text:"\u06de\u0641\u064e\u0640\u0654\u064e\u0627\u0645\u064e\u0646\u064e \u0644\u064e\u0647\u064f\u06e5 \u0644\u064f\u0648\u0637\u065e\u06d8 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0645\u064f\u0647\u064e\u0627\u062c\u0650\u0631\u064c \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u064a\u0653\u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0671\u0644\u06e1\u062d\u064e\u0643\u0650\u064a\u0645\u064f",translation:"Maka Lu\u1e6d membenarkan (kenabian Ibrahim). Dan dia (Ibrahim) berkata, \"Sesungguhnya aku harus berpindah ke (tempat yang diperintahkan) Tuhanku; sungguh, Dialah Yang Mahaperkasa, Mahabijaksana"},{id:27,text:"\u0648\u064e\u0648\u064e\u0647\u064e\u0628\u06e1\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u06e5\u0653 \u0625\u0650\u0633\u06e1\u062d\u064e\u0670\u0642\u064e \u0648\u064e\u064a\u064e\u0639\u06e1\u0642\u064f\u0648\u0628\u064e \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u062a\u0650\u0647\u0650 \u0671\u0644\u0646\u0651\u064f\u0628\u064f\u0648\u0651\u064e\u0629\u064e \u0648\u064e\u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0648\u064e\u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f \u0623\u064e\u062c\u06e1\u0631\u064e\u0647\u064f\u06e5 \u0641\u0650\u064a \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627\u06d6 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0644\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u0650\u064a\u0646\u064e",translation:"(Dan Kami anugerahkan kepada Ibrahim, Ishak dan Yakub, dan Kami jadikan kenabian dan kitab kepada keturunannya, dan Kami berikan kepadanya balasannya di dunia;621) dan sesungguhnya dia di akhirat, termasuk orang yang saleh"},{id:28,text:"\u0648\u064e\u0644\u064f\u0648\u0637\u064b\u0627 \u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0644\u064e\u062a\u064e\u0623\u06e1\u062a\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0641\u064e\u0670\u062d\u0650\u0634\u064e\u0629\u064e \u0645\u064e\u0627 \u0633\u064e\u0628\u064e\u0642\u064e\u0643\u064f\u0645 \u0628\u0650\u0647\u064e\u0627 \u0645\u0650\u0646\u06e1 \u0623\u064e\u062d\u064e\u062f\u0656 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Dan (ingatlah) ketika Lu\u1e6d berkata kepada kaumnya, \"Kamu benar-benar melakukan perbuatan yang sangat keji (homoseksual) yang belum pernah dilakukan oleh seorang pun dari umat-umat sebelum kamu"},{id:29,text:"\u0623\u064e\u0626\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0644\u064e\u062a\u064e\u0623\u06e1\u062a\u064f\u0648\u0646\u064e \u0671\u0644\u0631\u0651\u0650\u062c\u064e\u0627\u0644\u064e \u0648\u064e\u062a\u064e\u0642\u06e1\u0637\u064e\u0639\u064f\u0648\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u064e \u0648\u064e\u062a\u064e\u0623\u06e1\u062a\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0646\u064e\u0627\u062f\u0650\u064a\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064f\u0646\u0643\u064e\u0631\u064e\u06d6 \u0641\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u062c\u064e\u0648\u064e\u0627\u0628\u064e \u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0671\u0626\u06e1\u062a\u0650\u0646\u064e\u0627 \u0628\u0650\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e",translation:"(Apakah pantas kamu mendatangi laki-laki, menyamun622) dan mengerjakan kemungkaran di tempat-tempat pertemuanmu?\" Maka jawaban kaumnya tidak lain hanya mengatakan, \"Datangkanlah kepada kami azab Allah, jika engkau termasuk orang-orang yang benar"},{id:30,text:"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0671\u0646\u0635\u064f\u0631\u06e1\u0646\u0650\u064a \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0645\u064f\u0641\u06e1\u0633\u0650\u062f\u0650\u064a\u0646\u064e",translation:"Dia (Lu\u1e6d) berdoa, \"Ya Tuhanku, tolonglah aku (dengan menimpakan azab) atas golongan yang berbuat kerusakan itu"},{id:31,text:"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u062a\u06e1 \u0631\u064f\u0633\u064f\u0644\u064f\u0646\u064e\u0627\u0653 \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064e \u0628\u0650\u0671\u0644\u06e1\u0628\u064f\u0634\u06e1\u0631\u064e\u0649\u0670 \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e\u0627 \u0645\u064f\u0647\u06e1\u0644\u0650\u0643\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0647\u06e1\u0644\u0650 \u0647\u064e\u0670\u0630\u0650\u0647\u0650 \u0671\u0644\u06e1\u0642\u064e\u0631\u06e1\u064a\u064e\u0629\u0650\u06d6 \u0625\u0650\u0646\u0651\u064e \u0623\u064e\u0647\u06e1\u0644\u064e\u0647\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0638\u064e\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dan ketika utusan Kami (para malaikat) datang kepada Ibrahim dengan membawa kabar gembira,623) mereka mengatakan, \"Sungguh, kami akan membinasakan penduduk kota (Sodom) ini karena penduduknya sungguh orang-orang zalim"},{id:32,text:"\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0644\u064f\u0648\u0637\u0657\u0627\u06da \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0646\u064e\u062d\u06e1\u0646\u064f \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0646 \u0641\u0650\u064a\u0647\u064e\u0627\u06d6 \u0644\u064e\u0646\u064f\u0646\u064e\u062c\u0651\u0650\u064a\u064e\u0646\u0651\u064e\u0647\u064f\u06e5 \u0648\u064e\u0623\u064e\u0647\u06e1\u0644\u064e\u0647\u064f\u06e5\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0645\u06e1\u0631\u064e\u0623\u064e\u062a\u064e\u0647\u064f\u06e5 \u0643\u064e\u0627\u0646\u064e\u062a\u06e1 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u063a\u064e\u0670\u0628\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Ibrahim berkata, \"Sesungguhnya di kota itu ada Lu\u1e6d.\" Mereka (para malaikat) berkata, \"Kami lebih mengetahui siapa yang ada di kota itu. Kami pasti akan menyelamatkan dia dan pengikut-pengikutnya kecuali istrinya. Dia termasuk orang-orang yang tertinggal (dibinasakan)"},{id:33,text:"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u062c\u064e\u0627\u0653\u0621\u064e\u062a\u06e1 \u0631\u064f\u0633\u064f\u0644\u064f\u0646\u064e\u0627 \u0644\u064f\u0648\u0637\u0657\u0627 \u0633\u0650\u064a\u0653\u0621\u064e \u0628\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0636\u064e\u0627\u0642\u064e \u0628\u0650\u0647\u0650\u0645\u06e1 \u0630\u064e\u0631\u06e1\u0639\u0657\u0627\u06d6 \u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u062a\u064e\u062e\u064e\u0641\u06e1 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062d\u06e1\u0632\u064e\u0646\u06e1 \u0625\u0650\u0646\u0651\u064e\u0627 \u0645\u064f\u0646\u064e\u062c\u0651\u064f\u0648\u0643\u064e \u0648\u064e\u0623\u064e\u0647\u06e1\u0644\u064e\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0645\u06e1\u0631\u064e\u0623\u064e\u062a\u064e\u0643\u064e \u0643\u064e\u0627\u0646\u064e\u062a\u06e1 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u063a\u064e\u0670\u0628\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan ketika para utusan Kami (para malaikat) datang kepada Lu\u1e6d, dia merasa bersedih hati karena (kedatangan) mereka,624) dan (merasa) tidak mempunyai kekuatan untuk melindungi mereka, dan mereka (para utusan) berkata, \"Janganlah engkau takut dan jangan (pula) bersedih hati. Sesungguhnya Kami akan menyelamatkanmu dan pengikut-pengikutmu, kecuali istrimu, dia termasuk orang-orang yang ditinggal (dibinasakan)"},{id:34,text:"\u0625\u0650\u0646\u0651\u064e\u0627 \u0645\u064f\u0646\u0632\u0650\u0644\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0647\u06e1\u0644\u0650 \u0647\u064e\u0670\u0630\u0650\u0647\u0650 \u0671\u0644\u06e1\u0642\u064e\u0631\u06e1\u064a\u064e\u0629\u0650 \u0631\u0650\u062c\u06e1\u0632\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0641\u06e1\u0633\u064f\u0642\u064f\u0648\u0646\u064e",translation:"Sesungguhnya Kami akan menurunkan azab dari langit kepada penduduk kota ini karena mereka berbuat fasik"},{id:35,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f \u062a\u0651\u064e\u0631\u064e\u0643\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646\u06e1\u0647\u064e\u0627\u0653 \u0621\u064e\u0627\u064a\u064e\u0629\u064e\u06e2 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0629\u0657 \u0644\u0651\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e",translation:"(Dan sungguh, tentang itu telah Kami tinggalkan suatu tanda yang nyata625) bagi orang-orang yang mengerti"},{id:36,text:"\u0648\u064e\u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064e\u062f\u06e1\u064a\u064e\u0646\u064e \u0623\u064e\u062e\u064e\u0627\u0647\u064f\u0645\u06e1 \u0634\u064f\u0639\u064e\u064a\u06e1\u0628\u0657\u0627 \u0641\u064e\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0671\u0631\u06e1\u062c\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u062b\u064e\u0648\u06e1\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0645\u064f\u0641\u06e1\u0633\u0650\u062f\u0650\u064a\u0646\u064e",translation:"Dan kepada penduduk Madyan, (Kami telah mengutus) saudara mereka Syu'aib, dia berkata, \"Wahai kaumku! Sembahlah Allah, harapkanlah (pahala) hari akhir, dan jangan kamu berkeliaran di bumi berbuat kerusakan"},{id:37,text:"\u0641\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0647\u064f \u0641\u064e\u0623\u064e\u062e\u064e\u0630\u064e\u062a\u06e1\u0647\u064f\u0645\u064f \u0671\u0644\u0631\u0651\u064e\u062c\u06e1\u0641\u064e\u0629\u064f \u0641\u064e\u0623\u064e\u0635\u06e1\u0628\u064e\u062d\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u062f\u064e\u0627\u0631\u0650\u0647\u0650\u0645\u06e1 \u062c\u064e\u0670\u062b\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Mereka mendustakannya (Syu'aib), maka mereka ditimpa gempa yang dahsyat, lalu jadilah mereka mayat-mayat yang bergelimpangan di tempat-tempat tinggal mereka"},{id:38,text:"\u0648\u064e\u0639\u064e\u0627\u062f\u0657\u0627 \u0648\u064e\u062b\u064e\u0645\u064f\u0648\u062f\u064e\u0627\u0652 \u0648\u064e\u0642\u064e\u062f \u062a\u0651\u064e\u0628\u064e\u064a\u0651\u064e\u0646\u064e \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0645\u0651\u064e\u0633\u064e\u0670\u0643\u0650\u0646\u0650\u0647\u0650\u0645\u06e1\u06d6 \u0648\u064e\u0632\u064e\u064a\u0651\u064e\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u064f \u0623\u064e\u0639\u06e1\u0645\u064e\u0670\u0644\u064e\u0647\u064f\u0645\u06e1 \u0641\u064e\u0635\u064e\u062f\u0651\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0646\u0650 \u0671\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u0650 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0645\u064f\u0633\u06e1\u062a\u064e\u0628\u06e1\u0635\u0650\u0631\u0650\u064a\u0646\u064e",translation:"juga (ingatlah) kaum '\u0100d dan Samud, sungguh telah nyata bagi kamu (kehancuran mereka) dari (puing-puing) tempat tinggal mereka. Setan telah menjadikan terasa indah bagi mereka perbuatan (buruk) mereka, sehingga menghalangi mereka dari jalan (Allah), sedangkan mereka adalah orang-orang yang berpandangan tajam"},{id:39,text:"\u0648\u064e\u0642\u064e\u0670\u0631\u064f\u0648\u0646\u064e \u0648\u064e\u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0648\u064e\u0647\u064e\u0670\u0645\u064e\u0670\u0646\u064e\u06d6 \u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645 \u0645\u0651\u064f\u0648\u0633\u064e\u0649\u0670 \u0628\u0650\u0671\u0644\u06e1\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0650 \u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u064e\u0631\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0633\u064e\u0670\u0628\u0650\u0642\u0650\u064a\u0646\u064e",translation:"dan (juga) Karun, Fir'aun dan Haman. Sungguh, telah datang kepada mereka Musa dengan (membawa) keterangan-keterangan yang nyata. Tetapi mereka berlaku sombong di bumi, dan mereka orang-orang yang tidak luput (dari azab Allah)"},{id:40,text:"\u0641\u064e\u0643\u064f\u0644\u0651\u064b\u0627 \u0623\u064e\u062e\u064e\u0630\u06e1\u0646\u064e\u0627 \u0628\u0650\u0630\u064e\u0646\u06e2\u0628\u0650\u0647\u0650\u06e6\u06d6 \u0641\u064e\u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0646\u06e1 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u062d\u064e\u0627\u0635\u0650\u0628\u0657\u0627 \u0648\u064e\u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0646\u06e1 \u0623\u064e\u062e\u064e\u0630\u064e\u062a\u06e1\u0647\u064f \u0671\u0644\u0635\u0651\u064e\u064a\u06e1\u062d\u064e\u0629\u064f \u0648\u064e\u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0646\u06e1 \u062e\u064e\u0633\u064e\u0641\u06e1\u0646\u064e\u0627 \u0628\u0650\u0647\u0650 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0648\u064e\u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0646\u06e1 \u0623\u064e\u063a\u06e1\u0631\u064e\u0642\u06e1\u0646\u064e\u0627\u06da \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u064a\u064e\u0638\u06e1\u0644\u0650\u0645\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u0643\u064e\u0627\u0646\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0638\u06e1\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Maka masing-masing (mereka itu) Kami azab karena dosa-dosanya, di antara mereka ada yang Kami timpakan kepadanya hujan batu kerikil, ada yang ditimpa suara keras yang mengguntur, ada yang Kami benamkan ke dalam bumi, dan ada pula yang Kami tenggelamkan. Allah sama sekali tidak hendak menzalimi mereka, akan tetapi merekalah yang menzalimi diri mereka sendiri"},{id:41,text:"\u0645\u064e\u062b\u064e\u0644\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0648\u06e1\u0644\u0650\u064a\u064e\u0627\u0653\u0621\u064e \u0643\u064e\u0645\u064e\u062b\u064e\u0644\u0650 \u0671\u0644\u06e1\u0639\u064e\u0646\u0643\u064e\u0628\u064f\u0648\u062a\u0650 \u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064e\u062a\u06e1 \u0628\u064e\u064a\u06e1\u062a\u0657\u0627\u06d6 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0623\u064e\u0648\u06e1\u0647\u064e\u0646\u064e \u0671\u0644\u06e1\u0628\u064f\u064a\u064f\u0648\u062a\u0650 \u0644\u064e\u0628\u064e\u064a\u06e1\u062a\u064f \u0671\u0644\u06e1\u0639\u064e\u0646\u0643\u064e\u0628\u064f\u0648\u062a\u0650\u06da \u0644\u064e\u0648\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Perumpamaan orang-orang yang mengambil pelindung selain Allah adalah seperti laba-laba yang membuat rumah. Dan sesungguhnya rumah yang paling lemah ialah rumah laba-laba, sekiranya mereka mengetahui"},{id:42,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u064a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u06e6 \u0645\u0650\u0646 \u0634\u064e\u064a\u06e1\u0621\u0656\u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0671\u0644\u06e1\u062d\u064e\u0643\u0650\u064a\u0645\u064f",translation:"Sungguh, Allah mengetahui apa saja yang mereka sembah selain Dia. Dan Dia Mahaperkasa, Mahabijaksana"},{id:43,text:"\u0648\u064e\u062a\u0650\u0644\u06e1\u0643\u064e \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u062b\u064e\u0670\u0644\u064f \u0646\u064e\u0636\u06e1\u0631\u0650\u0628\u064f\u0647\u064e\u0627 \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650\u06d6 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0647\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Dan perumpamaan-perumpamaan ini Kami buat untuk manusia; dan tidak ada yang akan memahaminya kecuali mereka yang berilmu"},{id:44,text:"\u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650\u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0623\u0653\u064a\u064e\u0629\u0657 \u0644\u0651\u0650\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"(Allah menciptakan langit dan bumi dengan hak.626) Sungguh, pada yang demikian itu pasti terdapat tanda-tanda (kebesaran Allah) bagi orang-orang yang beriman"},{id:45,text:"\u0671\u062a\u06e1\u0644\u064f \u0645\u064e\u0627\u0653 \u0623\u064f\u0648\u062d\u0650\u064a\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0648\u064e\u0623\u064e\u0642\u0650\u0645\u0650 \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e\u06d6 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e \u062a\u064e\u0646\u06e1\u0647\u064e\u0649\u0670 \u0639\u064e\u0646\u0650 \u0671\u0644\u06e1\u0641\u064e\u062d\u06e1\u0634\u064e\u0627\u0653\u0621\u0650 \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0646\u0643\u064e\u0631\u0650\u06d7 \u0648\u064e\u0644\u064e\u0630\u0650\u0643\u06e1\u0631\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0643\u06e1\u0628\u064e\u0631\u064f\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u062a\u064e\u0635\u06e1\u0646\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Bacalah Kitab (Alquran) yang telah diwahyukan kepadamu (Muhammad) dan laksanakanlah salat. Sesungguhnya salat itu mencegah dari (perbuatan) keji dan mungkar. Dan (ketahuilah) mengingat Allah (salat) itu lebih besar (keutamaannya dari ibadah yang lain). Allah mengetahui apa yang kamu kerjakan"},{id:46,text:"\u06de\u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u062c\u064e\u0670\u062f\u0650\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0647\u06e1\u0644\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0671\u0644\u0651\u064e\u062a\u0650\u064a \u0647\u0650\u064a\u064e \u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0653\u0627\u0652 \u0621\u064e\u0627\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0648\u064e\u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0648\u064e\u0625\u0650\u0644\u064e\u0670\u0647\u064f\u0646\u064e\u0627 \u0648\u064e\u0625\u0650\u0644\u064e\u0670\u0647\u064f\u0643\u064f\u0645\u06e1 \u0648\u064e\u0670\u062d\u0650\u062f\u065e \u0648\u064e\u0646\u064e\u062d\u06e1\u0646\u064f \u0644\u064e\u0647\u064f\u06e5 \u0645\u064f\u0633\u06e1\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"(Dan janganlah kamu berdebat dengan Ahli Kitab, melainkan dengan cara yang baik, kecuali dengan orang-orang yang zalim diantara mereka,627) dan katakanlah, \"Kami telah beriman kepada (kitab-kitab) yang diturunkan kepada kami dan yang diturunkan kepadamu; Tuhan kami dan Tuhan kamu satu; dan hanya kepada-Nya kami berserah diri"},{id:47,text:"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e\u06da \u0641\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u0645\u0650\u0646\u06e1 \u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650 \u0645\u064e\u0646 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f \u0628\u0650\u0647\u0650\u06e6\u06da \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u062c\u06e1\u062d\u064e\u062f\u064f \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Dan demikianlah Kami turunkan Kitab (Alquran) kepadamu. Adapun orang-orang yang telah Kami berikan Kitab (Taurat dan Injil) mereka beriman kepadanya (Alquran); dan di antara mereka (orang-orang kafir Mekkah) ada yang beriman kepadanya. Dan hanya orang-orang kafir yang mengingkari ayat-ayat Kami"},{id:48,text:"\u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064e \u062a\u064e\u062a\u06e1\u0644\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u06e6 \u0645\u0650\u0646 \u0643\u0650\u062a\u064e\u0670\u0628\u0656 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062e\u064f\u0637\u0651\u064f\u0647\u064f\u06e5 \u0628\u0650\u064a\u064e\u0645\u0650\u064a\u0646\u0650\u0643\u064e\u06d6 \u0625\u0650\u0630\u0657\u0627 \u0644\u0651\u064e\u0671\u0631\u06e1\u062a\u064e\u0627\u0628\u064e \u0671\u0644\u06e1\u0645\u064f\u0628\u06e1\u0637\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Dan engkau (Muhammad) tidak pernah membaca sesuatu kitab sebelum (Alquran) dan engkau tidak (pernah) menulis suatu kitab dengan tangan kananmu; sekiranya (engkau pernah membaca dan menulis), niscaya ragu orang-orang yang mengingkarinya"},{id:49,text:"\u0628\u064e\u0644\u06e1 \u0647\u064f\u0648\u064e \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u064f\u06e2 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u065e \u0641\u0650\u064a \u0635\u064f\u062f\u064f\u0648\u0631\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0639\u0650\u0644\u06e1\u0645\u064e\u06da \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u062c\u06e1\u062d\u064e\u062f\u064f \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Sebenarnya, (Alquran) itu adalah ayat-ayat yang jelas di dalam dada orang-orang yang berilmu.628) Hanya orang-orang zalim yang mengingkari ayat-ayat Kami"},{id:50,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0648\u06e1\u0644\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u065e \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0647\u0650\u06e6\u06da \u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0671\u0644\u06e1\u0623\u0653\u064a\u064e\u0670\u062a\u064f \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u064e\u0627\u06e0 \u0646\u064e\u0630\u0650\u064a\u0631\u065e \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u064c",translation:"Dan mereka (orang-orang kafir Mekkah) berkata, \"Mengapa tidak diturunkan mukjizat-mukjizat dari Tuhannya?\" Katakanlah (Muhammad), \"Mukjizat-mukjizat itu terserah kepada Allah. Aku hanya seorang pemberi peringatan yang jelas"},{id:51,text:"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0643\u06e1\u0641\u0650\u0647\u0650\u0645\u06e1 \u0623\u064e\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u064a\u064f\u062a\u06e1\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u0657 \u0648\u064e\u0630\u0650\u0643\u06e1\u0631\u064e\u0649\u0670 \u0644\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Apakah tidak cukup bagi mereka bahwa Kami telah menurunkan kepadamu Kitab (Alquran) yang dibacakan kepada mereka? Sungguh, dalam (Alquran) itu terdapat rahmat yang besar dan pelajaran bagi orang-orang yang beriman"},{id:52,text:"\u0642\u064f\u0644\u06e1 \u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u064e\u064a\u06e1\u0646\u0650\u064a \u0648\u064e\u0628\u064e\u064a\u06e1\u0646\u064e\u0643\u064f\u0645\u06e1 \u0634\u064e\u0647\u0650\u064a\u062f\u0657\u0627\u06d6 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d7 \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u06e1\u0628\u064e\u0670\u0637\u0650\u0644\u0650 \u0648\u064e\u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u062e\u064e\u0670\u0633\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Katakanlah (Muhammad), \"Cukuplah Allah menjadi saksi antara aku dan kamu. Dia mengetahui apa yang di langit dan di bumi. Dan orang yang percaya kepada yang batil dan ingkar kepada Allah, mereka itulah orang-orang yang rugi"},{id:53,text:"\u0648\u064e\u064a\u064e\u0633\u06e1\u062a\u064e\u0639\u06e1\u062c\u0650\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u0628\u0650\u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0648\u064e\u0644\u064e\u0648\u06e1\u0644\u064e\u0627\u0653 \u0623\u064e\u062c\u064e\u0644\u065e \u0645\u0651\u064f\u0633\u064e\u0645\u0651\u0657\u0649 \u0644\u0651\u064e\u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064f\u06da \u0648\u064e\u0644\u064e\u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e\u0646\u0651\u064e\u0647\u064f\u0645 \u0628\u064e\u063a\u06e1\u062a\u064e\u0629\u0657 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0634\u06e1\u0639\u064f\u0631\u064f\u0648\u0646\u064e",translation:"(Dan mereka meminta kepadamu agar segera diturunkan azab. Kalau bukan karena waktunya yang telah ditetapkan,629) niscaya datang azab kepada mereka, dan (azab itu) pasti akan datang kepada mereka dengan tiba-tiba, sedang mereka tidak menyadarinya"},{id:54,text:"\u064a\u064e\u0633\u06e1\u062a\u064e\u0639\u06e1\u062c\u0650\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u0628\u0650\u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0644\u064e\u0645\u064f\u062d\u0650\u064a\u0637\u064e\u0629\u064f\u06e2 \u0628\u0650\u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Mereka meminta kepadamu agar segera diturunkan azab. Dan sesungguhnya neraka Jahanam itu pasti meliputi orang-orang kafir"},{id:55,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064e\u063a\u06e1\u0634\u064e\u0649\u0670\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0645\u0650\u0646 \u0641\u064e\u0648\u06e1\u0642\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0645\u0650\u0646 \u062a\u064e\u062d\u06e1\u062a\u0650 \u0623\u064e\u0631\u06e1\u062c\u064f\u0644\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0630\u064f\u0648\u0642\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Pada hari (ketika) azab menutup mereka dari atas dan dari bawah kaki mereka dan (Allah) berkata (kepada mereka), \"Rasakanlah (balasan dari) apa yang telah kamu kerjakan"},{id:56,text:"\u064a\u064e\u0670\u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e \u0623\u064e\u0631\u06e1\u0636\u0650\u064a \u0648\u064e\u0670\u0633\u0650\u0639\u064e\u0629\u065e \u0641\u064e\u0625\u0650\u064a\u0651\u064e\u0640\u0670\u064a\u064e \u0641\u064e\u0671\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0646\u0650",translation:"Wahai hamba-hamba-Ku yang beriman! Sungguh, bumi-Ku luas, maka sembahlah Aku (saja)"},{id:57,text:"\u0643\u064f\u0644\u0651\u064f \u0646\u064e\u0641\u06e1\u0633\u0656 \u0630\u064e\u0627\u0653\u0626\u0650\u0642\u064e\u0629\u064f \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u0650\u06d6 \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u062a\u064f\u0631\u06e1\u062c\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Setiap yang bernyawa akan merasakan mati. Kemudian hanya kepada Kami kamu dikembalikan"},{id:58,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0644\u064e\u0646\u064f\u0628\u064e\u0648\u0651\u0650\u0626\u064e\u0646\u0651\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u063a\u064f\u0631\u064e\u0641\u0657\u0627 \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0645\u0650\u0646 \u062a\u064e\u062d\u06e1\u062a\u0650\u0647\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u064f \u062e\u064e\u0670\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627\u06da \u0646\u0650\u0639\u06e1\u0645\u064e \u0623\u064e\u062c\u06e1\u0631\u064f \u0671\u0644\u06e1\u0639\u064e\u0670\u0645\u0650\u0644\u0650\u064a\u0646\u064e",translation:"Dan orang-orang yang beriman dan mengerjakan kebajikan, sungguh, mereka akan Kami tempatkan pada tempat-tempat yang tinggi (di dalam surga), yang mengalir di bawahnya sungai-sungai, mereka kekal di dalamnya. Itulah sebaik-baik balasan bagi orang yang berbuat kebajikan"},{id:59,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0635\u064e\u0628\u064e\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u064a\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u064f\u0648\u0646\u064e",translation:"(yaitu) orang-orang yang sabar dan bertawakal kepada Tuhannya"},{id:60,text:"\u0648\u064e\u0643\u064e\u0623\u064e\u064a\u0651\u0650\u0646 \u0645\u0651\u0650\u0646 \u062f\u064e\u0627\u0653\u0628\u0651\u064e\u0629\u0656 \u0644\u0651\u064e\u0627 \u062a\u064e\u062d\u06e1\u0645\u0650\u0644\u064f \u0631\u0650\u0632\u06e1\u0642\u064e\u0647\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0631\u06e1\u0632\u064f\u0642\u064f\u0647\u064e\u0627 \u0648\u064e\u0625\u0650\u064a\u0651\u064e\u0627\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u0650\u064a\u0639\u064f \u0671\u0644\u06e1\u0639\u064e\u0644\u0650\u064a\u0645\u064f",translation:"Dan berapa banyak makhluk bergerak yang bernyawa yang tidak (dapat) membawa (mengurus) rezekinya sendiri. Allah lah yang memberi rezeki kepadanya dan kepadamu. Dia Maha Mendengar, Maha Mengetahui"},{id:61,text:"\u0648\u064e\u0644\u064e\u0626\u0650\u0646 \u0633\u064e\u0623\u064e\u0644\u06e1\u062a\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u0646\u06e1 \u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0648\u064e\u0633\u064e\u062e\u0651\u064e\u0631\u064e \u0671\u0644\u0634\u0651\u064e\u0645\u06e1\u0633\u064e \u0648\u064e\u0671\u0644\u06e1\u0642\u064e\u0645\u064e\u0631\u064e \u0644\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06d6 \u0641\u064e\u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u064a\u064f\u0624\u06e1\u0641\u064e\u0643\u064f\u0648\u0646\u064e",translation:"Dan jika engkau bertanya kepada mereka, \"Siapakah yang menciptakan langit dan bumi dan menundukkan matahari dan bulan?\" Pasti mereka akan menjawab, \"Allah.\" Maka mengapa mereka bisa dipalingkan (dari kebenaran)"},{id:62,text:"\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0628\u06e1\u0633\u064f\u0637\u064f \u0671\u0644\u0631\u0651\u0650\u0632\u06e1\u0642\u064e \u0644\u0650\u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0645\u0650\u0646\u06e1 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650\u06e6 \u0648\u064e\u064a\u064e\u0642\u06e1\u062f\u0650\u0631\u064f \u0644\u064e\u0647\u064f\u06e5\u0653\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Allah melapangkan rezeki bagi orang yang Dia kehendaki di antara hamba-hamba-Nya dan Dia (pula) yang membatasi baginya. Sungguh, Allah Maha Mengetahui segala sesuatu"},{id:63,text:"\u0648\u064e\u0644\u064e\u0626\u0650\u0646 \u0633\u064e\u0623\u064e\u0644\u06e1\u062a\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u0646 \u0646\u0651\u064e\u0632\u0651\u064e\u0644\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0645\u064e\u0627\u0653\u0621\u0657 \u0641\u064e\u0623\u064e\u062d\u06e1\u064a\u064e\u0627 \u0628\u0650\u0647\u0650 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0645\u064e\u0648\u06e1\u062a\u0650\u0647\u064e\u0627 \u0644\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06da \u0642\u064f\u0644\u0650 \u0671\u0644\u06e1\u062d\u064e\u0645\u06e1\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650\u06da \u0628\u064e\u0644\u06e1 \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064f\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Dan jika kamu bertanya kepada mereka, \"Siapakah yang menurunkan air dari langit lalu dengan (air) itu dihidupkannya bumi yang sudah mati?\" Pasti mereka akan menjawab, \"Allah.\" Katakanlah, \"Segala puji bagi Allah,\" tetapi kebanyakan mereka tidak mengerti"},{id:64,text:"\u0648\u064e\u0645\u064e\u0627 \u0647\u064e\u0670\u0630\u0650\u0647\u0650 \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u064f \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0644\u064e\u0647\u06e1\u0648\u065e \u0648\u064e\u0644\u064e\u0639\u0650\u0628\u065e\u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u062f\u0651\u064e\u0627\u0631\u064e \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u064e \u0644\u064e\u0647\u0650\u064a\u064e \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u064e\u0627\u0646\u064f\u06da \u0644\u064e\u0648\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan kehidupan dunia ini hanya senda gurau dan permainan. Dan sesungguhnya negeri akhirat itulah kehidupan yang sebenarnya, sekiranya mereka mengetahui"},{id:65,text:"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0631\u064e\u0643\u0650\u0628\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u06e1\u0641\u064f\u0644\u06e1\u0643\u0650 \u062f\u064e\u0639\u064e\u0648\u064f\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064f\u062e\u06e1\u0644\u0650\u0635\u0650\u064a\u0646\u064e \u0644\u064e\u0647\u064f \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u064e \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0646\u064e\u062c\u0651\u064e\u0649\u0670\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u0628\u064e\u0631\u0651\u0650 \u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0645\u06e1 \u064a\u064f\u0634\u06e1\u0631\u0650\u0643\u064f\u0648\u0646\u064e",translation:"Maka apabila mereka naik kapal, mereka berdoa kepada Allah dengan penuh rasa pengabdian (ikhlas) kepada-Nya,630) tetapi ketika Allah menyelamatkan mereka sampai ke darat, malah mereka (kembali) mempersekutukan (Allah)"},{id:66,text:"\u0644\u0650\u064a\u064e\u0643\u06e1\u0641\u064f\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0645\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u0650\u064a\u064e\u062a\u064e\u0645\u064e\u062a\u0651\u064e\u0639\u064f\u0648\u0627\u0652\u06da \u0641\u064e\u0633\u064e\u0648\u06e1\u0641\u064e \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"biarlah mereka mengingkari nikmat yang telah Kami berikan kepada mereka dan silahkan mereka (hidup) bersenang-senang (dalam kekafiran). Maka kelak mereka akan mengetahui (akibat perbuatannya)"},{id:67,text:"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0631\u064e\u0648\u06e1\u0627\u0652 \u0623\u064e\u0646\u0651\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u062d\u064e\u0631\u064e\u0645\u064b\u0627 \u0621\u064e\u0627\u0645\u0650\u0646\u0657\u0627 \u0648\u064e\u064a\u064f\u062a\u064e\u062e\u064e\u0637\u0651\u064e\u0641\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0645\u0650\u0646\u06e1 \u062d\u064e\u0648\u06e1\u0644\u0650\u0647\u0650\u0645\u06e1\u06da \u0623\u064e\u0641\u064e\u0628\u0650\u0671\u0644\u06e1\u0628\u064e\u0670\u0637\u0650\u0644\u0650 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0648\u064e\u0628\u0650\u0646\u0650\u0639\u06e1\u0645\u064e\u0629\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u0643\u06e1\u0641\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Tidakkah mereka memperhatikan, bahwa Kami telah menjadikan (negeri mereka) tanah suci yang aman, padahal manusia di sekitarnya saling merampok. Mengapa (setelah nyata kebenaran) mereka masih percaya kepada yang batil dan ingkar kepada nikmat Allah"},{id:68,text:"\u0648\u064e\u0645\u064e\u0646\u06e1 \u0623\u064e\u0638\u06e1\u0644\u064e\u0645\u064f \u0645\u0650\u0645\u0651\u064e\u0646\u0650 \u0671\u0641\u06e1\u062a\u064e\u0631\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u0630\u0650\u0628\u064b\u0627 \u0623\u064e\u0648\u06e1 \u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u06e5\u0653\u06da \u0623\u064e\u0644\u064e\u064a\u06e1\u0633\u064e \u0641\u0650\u064a \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0645\u064e\u062b\u06e1\u0648\u0657\u0649 \u0644\u0651\u0650\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"(Dan siapakah yang lebih zalim daripada orang yang mengada-adakan kebohongan kepada Allah atau orang yang mendustakan yang hak631) ketika (yang hak) itu datang kepadanya? Bukankah dalam neraka Jahanam ada tempat bagi orang-orang kafir"},{id:69,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062c\u064e\u0670\u0647\u064e\u062f\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0646\u064e\u0627 \u0644\u064e\u0646\u064e\u0647\u06e1\u062f\u0650\u064a\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0633\u064f\u0628\u064f\u0644\u064e\u0646\u064e\u0627\u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0645\u064e\u0639\u064e \u0671\u0644\u06e1\u0645\u064f\u062d\u06e1\u0633\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dan orang-orang yang berjihad untuk (mencari keridaan) Kami, Kami akan tunjukkan kepada mereka jalan-jalan Kami. Dan sungguh, Allah bersama orang-orang yang berbuat baik"}]},{id:30,name:"\u0627\u0644\u0631\u0648\u0645",transliteration:"Ar-Rum",translation:"Bangsa Romawi",type:"meccan",total_verses:60,verses:[{id:1,text:"\u0627\u0644\u0653\u0645\u0653",translation:"Alif L\u0101m M\u012bm"},{id:2,text:"\u063a\u064f\u0644\u0650\u0628\u064e\u062a\u0650 \u0671\u0644\u0631\u0651\u064f\u0648\u0645\u064f",translation:"Bangsa Romawi telah dikalahkan"},{id:3,text:"\u0641\u0650\u064a\u0653 \u0623\u064e\u062f\u06e1\u0646\u064e\u0649 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u063a\u064e\u0644\u064e\u0628\u0650\u0647\u0650\u0645\u06e1 \u0633\u064e\u064a\u064e\u063a\u06e1\u0644\u0650\u0628\u064f\u0648\u0646\u064e",translation:"(di negeri yang terdekat633) dan mereka setelah kekalahannya itu akan menang"},{id:4,text:"\u0641\u0650\u064a \u0628\u0650\u0636\u06e1\u0639\u0650 \u0633\u0650\u0646\u0650\u064a\u0646\u064e\u06d7 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0631\u064f \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f \u0648\u064e\u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u064f\u06da \u0648\u064e\u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u064a\u064e\u0641\u06e1\u0631\u064e\u062d\u064f \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"dalam beberapa tahun (lagi).635) Bagi Allah lah urusan sebelum dan setelah (mereka menang). Dan pada hari (kemenangan bangsa Romawi) itu bergembiralah orang-orang yang beriman"},{id:5,text:"\u0628\u0650\u0646\u064e\u0635\u06e1\u0631\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u064a\u064e\u0646\u0635\u064f\u0631\u064f \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0671\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",translation:"karena pertolongan Allah. Dia menolong siapa yang Dia kehendaki. Dia Mahaperkasa, Maha Penyayang"},{id:6,text:"\u0648\u064e\u0639\u06e1\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0644\u064e\u0627 \u064a\u064f\u062e\u06e1\u0644\u0650\u0641\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0639\u06e1\u062f\u064e\u0647\u064f\u06e5 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"(Itulah) janji Allah. Allah tidak akan menyalahi janji-Nya, tetapi kebanyakan manusia tidak mengetahui"},{id:7,text:"\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0638\u064e\u0670\u0647\u0650\u0631\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u0650 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0646\u0650 \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0647\u064f\u0645\u06e1 \u063a\u064e\u0670\u0641\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Mereka mengetahui yang lahir (tampak) dari kehidupan dunia; sedangkan terhadap (kehidupan) akhirat mereka lalai"},{id:8,text:"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u062a\u064e\u0641\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0653 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u06d7 \u0645\u0651\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0623\u064e\u062c\u064e\u0644\u0656 \u0645\u0651\u064f\u0633\u064e\u0645\u0651\u0657\u0649\u06d7 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0628\u0650\u0644\u0650\u0642\u064e\u0627\u0653\u064a\u0655\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0644\u064e\u0643\u064e\u0670\u0641\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Dan mengapa mereka tidak memikirkan tentang (kejadian) diri mereka? Allah tidak menciptakan langit dan bumi dan apa yang ada di antara keduanya melainkan dengan (tujuan) yang benar dan dalam waktu yang ditentukan. Dan sesungguhnya banyak di antara manusia benar-benar mengingkari pertemuan dengan Tuhannya"},{id:9,text:"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0633\u0650\u064a\u0631\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0641\u064e\u064a\u064e\u0646\u0638\u064f\u0631\u064f\u0648\u0627\u0652 \u0643\u064e\u064a\u06e1\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0670\u0642\u0650\u0628\u064e\u0629\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u0645\u06e1\u06da \u0643\u064e\u0627\u0646\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0634\u064e\u062f\u0651\u064e \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0642\u064f\u0648\u0651\u064e\u0629\u0657 \u0648\u064e\u0623\u064e\u062b\u064e\u0627\u0631\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0648\u064e\u0639\u064e\u0645\u064e\u0631\u064f\u0648\u0647\u064e\u0627\u0653 \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064e \u0645\u0650\u0645\u0651\u064e\u0627 \u0639\u064e\u0645\u064e\u0631\u064f\u0648\u0647\u064e\u0627 \u0648\u064e\u062c\u064e\u0627\u0653\u0621\u064e\u062a\u06e1\u0647\u064f\u0645\u06e1 \u0631\u064f\u0633\u064f\u0644\u064f\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0650\u06d6 \u0641\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u064a\u064e\u0638\u06e1\u0644\u0650\u0645\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u0643\u064e\u0627\u0646\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0638\u06e1\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Dan tidakkah mereka bepergian di bumi lalu melihat bagaimana kesudahan orang-orang sebelum mereka (yang mendustakan rasul)? Orang-orang itu lebih kuat dari mereka (sendiri) dan mereka telah mengolah bumi (tanah) serta memakmurkannya melebihi apa yang telah mereka makmurkan. Dan telah datang kepada mereka rasul-rasul mereka dengan membawa bukti-bukti yang jelas. Maka Allah sama sekali tidak berlaku zalim kepada mereka, tetapi merekalah yang berlaku zalim kepada diri mereka sendiri"},{id:10,text:"\u062b\u064f\u0645\u0651\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0670\u0642\u0650\u0628\u064e\u0629\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u0633\u064e\u0640\u0670\u0653\u0640\u0654\u064f\u0648\u0627\u0652 \u0671\u0644\u0633\u0651\u064f\u0648\u0653\u0623\u064e\u0649\u0670\u0653 \u0623\u064e\u0646 \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0647\u06e1\u0632\u0650\u0621\u064f\u0648\u0646\u064e",translation:"Kemudian, azab yang lebih buruk adalah kesudahan bagi orang-orang yang mengerjakan kejahatan. Karena mereka mendustakan ayat-ayat Allah dan mereka selalu memperolok-olokkannya"},{id:11,text:"\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0628\u06e1\u062f\u064e\u0624\u064f\u0627\u0652 \u0671\u0644\u06e1\u062e\u064e\u0644\u06e1\u0642\u064e \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0639\u0650\u064a\u062f\u064f\u0647\u064f\u06e5 \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u062a\u064f\u0631\u06e1\u062c\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Allah yang memulai penciptaan (makhluk), kemudian mengulanginya kembali; kemudian kepada-Nya kamu dikembalikan"},{id:12,text:"\u0648\u064e\u064a\u064e\u0648\u06e1\u0645\u064e \u062a\u064e\u0642\u064f\u0648\u0645\u064f \u0671\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064f \u064a\u064f\u0628\u06e1\u0644\u0650\u0633\u064f \u0671\u0644\u06e1\u0645\u064f\u062c\u06e1\u0631\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Dan pada hari (ketika) terjadi Kiamat, orang-orang yang berdosa (kaum musyrik) terdiam berputus asa"},{id:13,text:"\u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0643\u064f\u0646 \u0644\u0651\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0653\u0626\u0650\u0647\u0650\u0645\u06e1 \u0634\u064f\u0641\u064e\u0639\u064e\u0640\u0670\u0653\u0624\u064f\u0627\u0652 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0653\u0626\u0650\u0647\u0650\u0645\u06e1 \u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan tidak mungkin ada pemberi syafaat (pertolongan) bagi mereka dari berhala-berhala mereka, sedangkan mereka mengingkari berhala-berhala mereka itu"},{id:14,text:"\u0648\u064e\u064a\u064e\u0648\u06e1\u0645\u064e \u062a\u064e\u0642\u064f\u0648\u0645\u064f \u0671\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064f \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u064a\u064e\u062a\u064e\u0641\u064e\u0631\u0651\u064e\u0642\u064f\u0648\u0646\u064e",translation:"Dan pada hari (ketika) terjadi Kiamat, pada hari itu manusia terpecah-pecah (dalam kelompok)"},{id:15,text:"\u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0641\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0631\u064e\u0648\u06e1\u0636\u064e\u0629\u0656 \u064a\u064f\u062d\u06e1\u0628\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Adapun orang-orang yang beriman dan mengerjakan kebajikan, maka mereka di dalam taman (surga) bergembira"},{id:16,text:"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0648\u064e\u0644\u0650\u0642\u064e\u0627\u0653\u064a\u0655\u0650 \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0645\u064f\u062d\u06e1\u0636\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Sedangkan orang-orang yang kafir dan mendustakan ayat-ayat Kami serta (mendustakan) pertemuan hari akhirat, maka mereka tetap berada di dalam azab (neraka)"},{id:17,text:"\u0641\u064e\u0633\u064f\u0628\u06e1\u062d\u064e\u0670\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u0650\u064a\u0646\u064e \u062a\u064f\u0645\u06e1\u0633\u064f\u0648\u0646\u064e \u0648\u064e\u062d\u0650\u064a\u0646\u064e \u062a\u064f\u0635\u06e1\u0628\u0650\u062d\u064f\u0648\u0646\u064e",translation:"Maka bertasbihlah kepada Allah pada petang hari dan pada pagi hari (waktu subuh)"},{id:18,text:"\u0648\u064e\u0644\u064e\u0647\u064f \u0671\u0644\u06e1\u062d\u064e\u0645\u06e1\u062f\u064f \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0639\u064e\u0634\u0650\u064a\u0651\u0657\u0627 \u0648\u064e\u062d\u0650\u064a\u0646\u064e \u062a\u064f\u0638\u06e1\u0647\u0650\u0631\u064f\u0648\u0646\u064e",translation:"dan segala puji bagi-Nya di langit, di bumi, pada malam hari dan pada waktu zuhur (tengah hari)"},{id:19,text:"\u064a\u064f\u062e\u06e1\u0631\u0650\u062c\u064f \u0671\u0644\u06e1\u062d\u064e\u064a\u0651\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064e\u064a\u0651\u0650\u062a\u0650 \u0648\u064e\u064a\u064f\u062e\u06e1\u0631\u0650\u062c\u064f \u0671\u0644\u06e1\u0645\u064e\u064a\u0651\u0650\u062a\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u062d\u064e\u064a\u0651\u0650 \u0648\u064e\u064a\u064f\u062d\u06e1\u064a\u0650 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0628\u064e\u0639\u06e1\u062f\u064e \u0645\u064e\u0648\u06e1\u062a\u0650\u0647\u064e\u0627\u06da \u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062a\u064f\u062e\u06e1\u0631\u064e\u062c\u064f\u0648\u0646\u064e",translation:"Dia mengeluarkan yang hidup dari yang mati dan mengeluarkan yang mati dari yang hidup dan menghidupkan bumi setelah mati (kering). Dan seperti itulah kamu akan dikeluarkan (dari kubur)"},{id:20,text:"\u0648\u064e\u0645\u0650\u0646\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0646\u06e1 \u062e\u064e\u0644\u064e\u0642\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u062a\u064f\u0631\u064e\u0627\u0628\u0656 \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0630\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064f\u0645 \u0628\u064e\u0634\u064e\u0631\u065e \u062a\u064e\u0646\u062a\u064e\u0634\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Dan di antara tanda-tanda (kebesaran)-Nya ialah Dia menciptakan kamu dari tanah, kemudian tiba-tiba kamu (menjadi) manusia yang berkembang biak"},{id:21,text:"\u0648\u064e\u0645\u0650\u0646\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0646\u06e1 \u062e\u064e\u0644\u064e\u0642\u064e \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u06e1 \u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u0657\u0627 \u0644\u0651\u0650\u062a\u064e\u0633\u06e1\u0643\u064f\u0646\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u064e\u0627 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0628\u064e\u064a\u06e1\u0646\u064e\u0643\u064f\u0645 \u0645\u0651\u064e\u0648\u064e\u062f\u0651\u064e\u0629\u0657 \u0648\u064e\u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u064b\u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0623\u0653\u064a\u064e\u0670\u062a\u0656 \u0644\u0651\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064e\u062a\u064e\u0641\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan di antara tanda-tanda (kebesaran)-Nya ialah Dia menciptakan pasangan-pasangan untukmu dari jenismu sendiri, agar kamu cenderung dan merasa tenteram kepadanya, dan Dia menjadikan diantaramu rasa kasih dan sayang. Sungguh, pada yang demikian itu benar-benar terdapat tanda-tanda (kebesaran Allah) bagi kaum yang berpikir"},{id:22,text:"\u0648\u064e\u0645\u0650\u0646\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0647\u0650\u06e6 \u062e\u064e\u0644\u06e1\u0642\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0671\u062e\u06e1\u062a\u0650\u0644\u064e\u0670\u0641\u064f \u0623\u064e\u0644\u06e1\u0633\u0650\u0646\u064e\u062a\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0644\u06e1\u0648\u064e\u0670\u0646\u0650\u0643\u064f\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0623\u0653\u064a\u064e\u0670\u062a\u0656 \u0644\u0651\u0650\u0644\u06e1\u0639\u064e\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dan di antara tanda-tanda (kebesaran)-Nya ialah penciptaan langit dan bumi, perbedaan bahasamu dan warna kulitmu. Sungguh, pada yang demikian itu benar-benar terdapat tanda-tanda bagi orang-orang yang mengetahui"},{id:23,text:"\u0648\u064e\u0645\u0650\u0646\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0647\u0650\u06e6 \u0645\u064e\u0646\u064e\u0627\u0645\u064f\u0643\u064f\u0645 \u0628\u0650\u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u0650 \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u0648\u064e\u0671\u0628\u06e1\u062a\u0650\u063a\u064e\u0627\u0653\u0624\u064f\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0641\u064e\u0636\u06e1\u0644\u0650\u0647\u0650\u06e6\u0653\u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0623\u0653\u064a\u064e\u0670\u062a\u0656 \u0644\u0651\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064e\u0633\u06e1\u0645\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Dan di antara tanda-tanda (kebesaran)-Nya ialah tidurmu pada waktu malam dan siang hari serta usahamu mencari sebagian dari karunia-Nya. Sungguh, pada yang demikian itu benar-benar terdapat tanda-tanda bagi kaum yang mendengarkan"},{id:24,text:"\u0648\u064e\u0645\u0650\u0646\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0647\u0650\u06e6 \u064a\u064f\u0631\u0650\u064a\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0628\u064e\u0631\u06e1\u0642\u064e \u062e\u064e\u0648\u06e1\u0641\u0657\u0627 \u0648\u064e\u0637\u064e\u0645\u064e\u0639\u0657\u0627 \u0648\u064e\u064a\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0645\u064e\u0627\u0653\u0621\u0657 \u0641\u064e\u064a\u064f\u062d\u06e1\u064a\u0650\u06e6 \u0628\u0650\u0647\u0650 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0628\u064e\u0639\u06e1\u062f\u064e \u0645\u064e\u0648\u06e1\u062a\u0650\u0647\u064e\u0627\u0653\u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0623\u0653\u064a\u064e\u0670\u062a\u0656 \u0644\u0651\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Dan di antara tanda-tanda (kebesaran)-Nya, Dia memperlihatkan kilat kepadamu untuk (menimbulkan) ketakutan dan harapan, dan Dia menurunkan air (hujan) dari langit, lalu dengan air itu dihidupkannya bumi setelah mati (kering). Sungguh, pada yang demikian itu benar-benar terdapat tanda-tanda bagi kaum yang mengerti"},{id:25,text:"\u0648\u064e\u0645\u0650\u0646\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0646 \u062a\u064e\u0642\u064f\u0648\u0645\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u064f \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064f \u0628\u0650\u0623\u064e\u0645\u06e1\u0631\u0650\u0647\u0650\u06e6\u06da \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0630\u064e\u0627 \u062f\u064e\u0639\u064e\u0627\u0643\u064f\u0645\u06e1 \u062f\u064e\u0639\u06e1\u0648\u064e\u0629\u0657 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0625\u0650\u0630\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u062e\u06e1\u0631\u064f\u062c\u064f\u0648\u0646\u064e",translation:"Dan di antara tanda-tanda (kebesaran)-Nya ialah berdirinya langit dan bumi dengan kehendak-Nya. Kemudian apabila Dia memanggil kamu sekali panggil dari bumi, seketika itu kamu keluar (dari kubur)"},{id:26,text:"\u0648\u064e\u0644\u064e\u0647\u064f\u06e5 \u0645\u064e\u0646 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d6 \u0643\u064f\u0644\u0651\u065e \u0644\u0651\u064e\u0647\u064f\u06e5 \u0642\u064e\u0670\u0646\u0650\u062a\u064f\u0648\u0646\u064e",translation:"Dan milik-Nya apa yang di langit dan di bumi. Semuanya hanya kepada-Nya tunduk"},{id:27,text:"\u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064e\u0628\u06e1\u062f\u064e\u0624\u064f\u0627\u0652 \u0671\u0644\u06e1\u062e\u064e\u0644\u06e1\u0642\u064e \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0639\u0650\u064a\u062f\u064f\u0647\u064f\u06e5 \u0648\u064e\u0647\u064f\u0648\u064e \u0623\u064e\u0647\u06e1\u0648\u064e\u0646\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u06da \u0648\u064e\u0644\u064e\u0647\u064f \u0671\u0644\u06e1\u0645\u064e\u062b\u064e\u0644\u064f \u0671\u0644\u06e1\u0623\u064e\u0639\u06e1\u0644\u064e\u0649\u0670 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0671\u0644\u06e1\u062d\u064e\u0643\u0650\u064a\u0645\u064f",translation:"Dan Dialah yang memulai penciptaan, kemudian mengulanginya kembali, dan itu lebih mudah bagi-Nya. Dia memiliki sifat yang Mahatinggi di langit dan di bumi. Dan Dialah Yang Mahaperkasa, Mahabijaksana"},{id:28,text:"\u0636\u064e\u0631\u064e\u0628\u064e \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u064e\u062b\u064e\u0644\u0657\u0627 \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u06e1\u06d6 \u0647\u064e\u0644 \u0644\u0651\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0645\u0651\u064e\u0627 \u0645\u064e\u0644\u064e\u0643\u064e\u062a\u06e1 \u0623\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u064f\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0653\u0621\u064e \u0641\u0650\u064a \u0645\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u06e1\u0646\u064e\u0670\u0643\u064f\u0645\u06e1 \u0641\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u0650 \u0633\u064e\u0648\u064e\u0627\u0653\u0621\u065e \u062a\u064e\u062e\u064e\u0627\u0641\u064f\u0648\u0646\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u062e\u0650\u064a\u0641\u064e\u062a\u0650\u0643\u064f\u0645\u06e1 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0643\u064f\u0645\u06e1\u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064f\u0641\u064e\u0635\u0651\u0650\u0644\u064f \u0671\u0644\u06e1\u0623\u0653\u064a\u064e\u0670\u062a\u0650 \u0644\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Dia membuat perumpamaan bagimu dari dirimu sendiri. Apakah (kamu rela jika) ada di antara hamba sahaya yang kamu miliki, menjadi sekutu bagimu dalam (memiliki) rezeki yang telah Kami berikan kepadamu, sehingga kamu menjadi setara dengan mereka dalam hal ini, lalu kamu takut kepada mereka sebagaimana kamu takut kepada sesamamu.638) Demikianlah Kami jelaskan ayat-ayat itu bagi kaum yang mengerti"},{id:29,text:"\u0628\u064e\u0644\u0650 \u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0647\u06e1\u0648\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645 \u0628\u0650\u063a\u064e\u064a\u06e1\u0631\u0650 \u0639\u0650\u0644\u06e1\u0645\u0656\u06d6 \u0641\u064e\u0645\u064e\u0646 \u064a\u064e\u0647\u06e1\u062f\u0650\u064a \u0645\u064e\u0646\u06e1 \u0623\u064e\u0636\u064e\u0644\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06d6 \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0646\u0651\u064e\u0640\u0670\u0635\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Tetapi orang-orang yang zalim, mengikuti hawa nafsunya tanpa ilmu pengetahuan; maka siapakah yang dapat memberi petunjuk kepada orang yang telah disesatkan Allah. Dan tidak ada seorang penolong pun bagi mereka"},{id:30,text:"\u0641\u064e\u0623\u064e\u0642\u0650\u0645\u06e1 \u0648\u064e\u062c\u06e1\u0647\u064e\u0643\u064e \u0644\u0650\u0644\u062f\u0651\u0650\u064a\u0646\u0650 \u062d\u064e\u0646\u0650\u064a\u0641\u0657\u0627\u06da \u0641\u0650\u0637\u06e1\u0631\u064e\u062a\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u0651\u064e\u062a\u0650\u064a \u0641\u064e\u0637\u064e\u0631\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627\u06da \u0644\u064e\u0627 \u062a\u064e\u0628\u06e1\u062f\u0650\u064a\u0644\u064e \u0644\u0650\u062e\u064e\u0644\u06e1\u0642\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u064f \u0671\u0644\u06e1\u0642\u064e\u064a\u0651\u0650\u0645\u064f \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Maka hadapkanlah wajahmu dengan lurus kepada agama (Islam); (sesuai) fitrah Allah disebabkan Dia telah menciptakan manusia menurut (fitrah) itu.639) Tidak ada perubahan pada ciptaan Allah. (Itulah) agama yang lurus, tetapi kebanyakan manusia tidak mengetahui"},{id:31,text:"\u06de\u0645\u064f\u0646\u0650\u064a\u0628\u0650\u064a\u0646\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0647\u064f \u0648\u064e\u0623\u064e\u0642\u0650\u064a\u0645\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0634\u06e1\u0631\u0650\u0643\u0650\u064a\u0646\u064e",translation:"dengan kembali bertobat kepada-Nya dan bertakwalah kepada-Nya serta laksanakanlah salat dan janganlah kamu termasuk orang-orang yang mempersekutukan Allah"},{id:32,text:"\u0645\u0650\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0641\u064e\u0631\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u062f\u0650\u064a\u0646\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0634\u0650\u064a\u064e\u0639\u0657\u0627\u06d6 \u0643\u064f\u0644\u0651\u064f \u062d\u0650\u0632\u06e1\u0628\u0650\u06ed \u0628\u0650\u0645\u064e\u0627 \u0644\u064e\u062f\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0641\u064e\u0631\u0650\u062d\u064f\u0648\u0646\u064e",translation:"(yaitu orang-orang yang memecah belah agama mereka640) dan mereka menjadi beberapa golongan. Setiap golongan merasa bangga dengan apa yang ada pada golongan mereka"},{id:33,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0633\u0651\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0636\u064f\u0631\u0651\u065e \u062f\u064e\u0639\u064e\u0648\u06e1\u0627\u0652 \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u0645 \u0645\u0651\u064f\u0646\u0650\u064a\u0628\u0650\u064a\u0646\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0630\u064e\u0627\u0653 \u0623\u064e\u0630\u064e\u0627\u0642\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f \u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u064b \u0625\u0650\u0630\u064e\u0627 \u0641\u064e\u0631\u0650\u064a\u0642\u065e \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645 \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u064a\u064f\u0634\u06e1\u0631\u0650\u0643\u064f\u0648\u0646\u064e",translation:"Dan apabila manusia ditimpa oleh suatu bahaya, mereka menyeru Tuhannya dengan kembali (bertobat) kepada-Nya, kemudian apabila Dia memberikan sedikit rahmat-Nya641) kepada mereka, tiba-tiba sebagian mereka mempersekutukan Allah"},{id:34,text:"\u0644\u0650\u064a\u064e\u0643\u06e1\u0641\u064f\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0645\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1\u06da \u0641\u064e\u062a\u064e\u0645\u064e\u062a\u0651\u064e\u0639\u064f\u0648\u0627\u0652 \u0641\u064e\u0633\u064e\u0648\u06e1\u0641\u064e \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"biarkan mereka mengingkari rahmat yang telah Kami berikan. Dan bersenang-senanglah kamu, maka kelak kamu akan mengetahui (akibat perbuatanmu)"},{id:35,text:"\u0623\u064e\u0645\u06e1 \u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0633\u064f\u0644\u06e1\u0637\u064e\u0670\u0646\u0657\u0627 \u0641\u064e\u0647\u064f\u0648\u064e \u064a\u064e\u062a\u064e\u0643\u064e\u0644\u0651\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6 \u064a\u064f\u0634\u06e1\u0631\u0650\u0643\u064f\u0648\u0646\u064e",translation:"Atau pernahkah Kami menurunkan kepada mereka keterangan, yang menjelaskan (membenarkan) apa yang (selalu) mereka persekutukan dengan Tuhan"},{id:36,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627\u0653 \u0623\u064e\u0630\u064e\u0642\u06e1\u0646\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u0657 \u0641\u064e\u0631\u0650\u062d\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u064e\u0627\u06d6 \u0648\u064e\u0625\u0650\u0646 \u062a\u064f\u0635\u0650\u0628\u06e1\u0647\u064f\u0645\u06e1 \u0633\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u064f\u06e2 \u0628\u0650\u0645\u064e\u0627 \u0642\u064e\u062f\u0651\u064e\u0645\u064e\u062a\u06e1 \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u0647\u0650\u0645\u06e1 \u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0645\u06e1 \u064a\u064e\u0642\u06e1\u0646\u064e\u0637\u064f\u0648\u0646\u064e",translation:"Dan apabila Kami berikan suatu rahmat kepada manusia, niscaya mereka gembira dengan (rahmat) itu. Tetapi apabila mereka ditimpa suatu musibah (bahaya) karena kesalahan mereka sendiri, seketika itu mereka berputus asa"},{id:37,text:"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0631\u064e\u0648\u06e1\u0627\u0652 \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0628\u06e1\u0633\u064f\u0637\u064f \u0671\u0644\u0631\u0651\u0650\u0632\u06e1\u0642\u064e \u0644\u0650\u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0648\u064e\u064a\u064e\u0642\u06e1\u062f\u0650\u0631\u064f\u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0623\u0653\u064a\u064e\u0670\u062a\u0656 \u0644\u0651\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Dan tidakkah mereka memperhatikan bahwa Allah yang melapangkan rezeki bagi siapa yang Dia kehendaki dan Dia (pula) yang membatasi (bagi siapa yang Dia kehendaki). Sungguh, pada yang demikian itu benar-benar terdapat tanda-tanda (kebesaran Allah) bagi kaum yang beriman"},{id:38,text:"\u0641\u064e\u0640\u0654\u064e\u0627\u062a\u0650 \u0630\u064e\u0627 \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0628\u064e\u0649\u0670 \u062d\u064e\u0642\u0651\u064e\u0647\u064f\u06e5 \u0648\u064e\u0671\u0644\u06e1\u0645\u0650\u0633\u06e1\u0643\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0628\u06e1\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u0650\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062e\u064e\u064a\u06e1\u0631\u065e \u0644\u0651\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0648\u064e\u062c\u06e1\u0647\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0648\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064f\u0641\u06e1\u0644\u0650\u062d\u064f\u0648\u0646\u064e",translation:"Maka berikanlah haknya kepada kerabat dekat, juga kepada orang miskin dan orang-orang yang dalam perjalanan. Itulah yang lebih baik bagi orang-orang yang mencari keridaan Allah. Dan mereka itulah orang-orang yang beruntung"},{id:39,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u062a\u064f\u0645 \u0645\u0651\u0650\u0646 \u0631\u0651\u0650\u0628\u0657\u0627 \u0644\u0651\u0650\u064a\u064e\u0631\u06e1\u0628\u064f\u0648\u064e\u0627\u0652 \u0641\u0650\u064a\u0653 \u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u0650 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0631\u06e1\u0628\u064f\u0648\u0627\u0652 \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0648\u064e\u0645\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u062a\u064f\u0645 \u0645\u0651\u0650\u0646 \u0632\u064e\u0643\u064e\u0648\u0670\u0629\u0656 \u062a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0648\u064e\u062c\u06e1\u0647\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064f\u0636\u06e1\u0639\u0650\u0641\u064f\u0648\u0646\u064e",translation:"Dan suatu riba (tambahan) yang kamu berikan agar harta manusia bertambah, maka tidak bertambah dalam pandangan Allah. Dan apa yang kamu berikan berupa zakat yang kamu maksudkan untuk memperoleh keridaan Allah, maka itulah orang-orang yang melipatgandakan (pahalanya)"},{id:40,text:"\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e\u0643\u064f\u0645\u06e1 \u062b\u064f\u0645\u0651\u064e \u0631\u064e\u0632\u064e\u0642\u064e\u0643\u064f\u0645\u06e1 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0645\u0650\u064a\u062a\u064f\u0643\u064f\u0645\u06e1 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u062d\u06e1\u064a\u0650\u064a\u0643\u064f\u0645\u06e1\u06d6 \u0647\u064e\u0644\u06e1 \u0645\u0650\u0646 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0653\u0626\u0650\u0643\u064f\u0645 \u0645\u0651\u064e\u0646 \u064a\u064e\u0641\u06e1\u0639\u064e\u0644\u064f \u0645\u0650\u0646 \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0634\u064e\u064a\u06e1\u0621\u0656\u06da \u0633\u064f\u0628\u06e1\u062d\u064e\u0670\u0646\u064e\u0647\u064f\u06e5 \u0648\u064e\u062a\u064e\u0639\u064e\u0670\u0644\u064e\u0649\u0670 \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064f\u0634\u06e1\u0631\u0650\u0643\u064f\u0648\u0646\u064e",translation:"Allah yang menciptakan kamu, kemudian memberimu rezeki, lalu mematikanmu, kemudian menghidupkanmu (kembali). Adakah di antara mereka yang kamu sekutukan dengan Allah yang dapat berbuat hal yang demikian? Mahasuci Dia dan Mahatinggi dari apa yang mereka persekutukan"},{id:41,text:"\u0638\u064e\u0647\u064e\u0631\u064e \u0671\u0644\u06e1\u0641\u064e\u0633\u064e\u0627\u062f\u064f \u0641\u0650\u064a \u0671\u0644\u06e1\u0628\u064e\u0631\u0651\u0650 \u0648\u064e\u0671\u0644\u06e1\u0628\u064e\u062d\u06e1\u0631\u0650 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064e\u062a\u06e1 \u0623\u064e\u064a\u06e1\u062f\u0650\u064a \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u0650\u064a\u064f\u0630\u0650\u064a\u0642\u064e\u0647\u064f\u0645 \u0628\u064e\u0639\u06e1\u0636\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0631\u06e1\u062c\u0650\u0639\u064f\u0648\u0646\u064e",translation:"Telah tampak kerusakan di darat dan di laut disebabkan karena perbuatan tangan manusia; Allah menghendaki agar mereka merasakan sebagian dari (akibat) perbuatan mereka, agar mereka kembali (ke jalan yang benar)"},{id:42,text:"\u0642\u064f\u0644\u06e1 \u0633\u0650\u064a\u0631\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0641\u064e\u0671\u0646\u0638\u064f\u0631\u064f\u0648\u0627\u0652 \u0643\u064e\u064a\u06e1\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0670\u0642\u0650\u0628\u064e\u0629\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f\u06da \u0643\u064e\u0627\u0646\u064e \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064f\u0647\u064f\u0645 \u0645\u0651\u064f\u0634\u06e1\u0631\u0650\u0643\u0650\u064a\u0646\u064e",translation:"Katakanlah (Muhammad), \"Bepergianlah di bumi lalu lihatlah bagaimana kesudahan orang-orang dahulu. Kebanyakan dari mereka adalah orang-orang yang mempersekutukan (Allah)"},{id:43,text:"\u0641\u064e\u0623\u064e\u0642\u0650\u0645\u06e1 \u0648\u064e\u062c\u06e1\u0647\u064e\u0643\u064e \u0644\u0650\u0644\u062f\u0651\u0650\u064a\u0646\u0650 \u0671\u0644\u06e1\u0642\u064e\u064a\u0651\u0650\u0645\u0650 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650 \u0623\u064e\u0646 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e \u064a\u064e\u0648\u06e1\u0645\u065e \u0644\u0651\u064e\u0627 \u0645\u064e\u0631\u064e\u062f\u0651\u064e \u0644\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u064a\u064e\u0635\u0651\u064e\u062f\u0651\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Oleh karena itu, hadapkanlah wajahmu kepada agama yang lurus (Islam) sebelum datang dari Allah suatu hari (Kiamat) yang tidak dapat ditolak, pada hari itu mereka terpisah-pisah"},{id:44,text:"\u0645\u064e\u0646 \u0643\u064e\u0641\u064e\u0631\u064e \u0641\u064e\u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0643\u064f\u0641\u06e1\u0631\u064f\u0647\u064f\u06e5\u06d6 \u0648\u064e\u0645\u064e\u0646\u06e1 \u0639\u064e\u0645\u0650\u0644\u064e \u0635\u064e\u0670\u0644\u0650\u062d\u0657\u0627 \u0641\u064e\u0644\u0650\u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u06e1 \u064a\u064e\u0645\u06e1\u0647\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Barangsiapa kafir maka dia sendirilah yang menanggung (akibat) kekafirannya; dan barangsiapa mengerjakan kebajikan maka mereka menyiapkan untuk diri mereka sendiri (tempat yang menyenangkan)"},{id:45,text:"\u0644\u0650\u064a\u064e\u062c\u06e1\u0632\u0650\u064a\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0645\u0650\u0646 \u0641\u064e\u0636\u06e1\u0644\u0650\u0647\u0650\u06e6\u0653\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"agar Allah memberi balasan (pahala) kepada orang-orang yang beriman dan mengerjakan kebajikan dari karunia-Nya. Sungguh, Dia tidak menyukai orang-orang yang ingkar (kafir)"},{id:46,text:"\u0648\u064e\u0645\u0650\u0646\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0646 \u064a\u064f\u0631\u06e1\u0633\u0650\u0644\u064e \u0671\u0644\u0631\u0651\u0650\u064a\u064e\u0627\u062d\u064e \u0645\u064f\u0628\u064e\u0634\u0651\u0650\u0631\u064e\u0670\u062a\u0656 \u0648\u064e\u0644\u0650\u064a\u064f\u0630\u0650\u064a\u0642\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u062a\u0650\u0647\u0650\u06e6 \u0648\u064e\u0644\u0650\u062a\u064e\u062c\u06e1\u0631\u0650\u064a\u064e \u0671\u0644\u06e1\u0641\u064f\u0644\u06e1\u0643\u064f \u0628\u0650\u0623\u064e\u0645\u06e1\u0631\u0650\u0647\u0650\u06e6 \u0648\u064e\u0644\u0650\u062a\u064e\u0628\u06e1\u062a\u064e\u063a\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0641\u064e\u0636\u06e1\u0644\u0650\u0647\u0650\u06e6 \u0648\u064e\u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u0634\u06e1\u0643\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Dan di antara tanda-tanda (kebesaran)-Nya adalah bahwa Dia mengirimkan angin sebagai pembawa berita gembira643) dan agar kamu merasakan sebagian dari rahmat-Nya dan agar kapal dapat berlayar dengan perintah-Nya dan (juga) agar kamu dapat mencari sebagian dari karunia-Nya, dan agar kamu bersyukur"},{id:47,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064e \u0631\u064f\u0633\u064f\u0644\u064b\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u0645\u06e1 \u0641\u064e\u062c\u064e\u0627\u0653\u0621\u064f\u0648\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0650 \u0641\u064e\u0671\u0646\u062a\u064e\u0642\u064e\u0645\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u062c\u06e1\u0631\u064e\u0645\u064f\u0648\u0627\u0652\u06d6 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u062d\u064e\u0642\u0651\u064b\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0646\u064e\u0635\u06e1\u0631\u064f \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dan sungguh, Kami telah mengutus sebelum engkau (Muhammad) beberapa orang rasul kepada kaumnya, mereka datang kepadanya dengan membawa keterangan-keterangan (yang cukup), lalu Kami melakukan pembalasan terhadap orang-orang yang berdosa.644) Dan merupakan hak Kami untuk menolong orang-orang yang beriman"},{id:48,text:"\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u0631\u06e1\u0633\u0650\u0644\u064f \u0671\u0644\u0631\u0651\u0650\u064a\u064e\u0670\u062d\u064e \u0641\u064e\u062a\u064f\u062b\u0650\u064a\u0631\u064f \u0633\u064e\u062d\u064e\u0627\u0628\u0657\u0627 \u0641\u064e\u064a\u064e\u0628\u06e1\u0633\u064f\u0637\u064f\u0647\u064f\u06e5 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0643\u064e\u064a\u06e1\u0641\u064e \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0648\u064e\u064a\u064e\u062c\u06e1\u0639\u064e\u0644\u064f\u0647\u064f\u06e5 \u0643\u0650\u0633\u064e\u0641\u0657\u0627 \u0641\u064e\u062a\u064e\u0631\u064e\u0649 \u0671\u0644\u06e1\u0648\u064e\u062f\u06e1\u0642\u064e \u064a\u064e\u062e\u06e1\u0631\u064f\u062c\u064f \u0645\u0650\u0646\u06e1 \u062e\u0650\u0644\u064e\u0670\u0644\u0650\u0647\u0650\u06e6\u06d6 \u0641\u064e\u0625\u0650\u0630\u064e\u0627\u0653 \u0623\u064e\u0635\u064e\u0627\u0628\u064e \u0628\u0650\u0647\u0650\u06e6 \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0645\u0650\u0646\u06e1 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0645\u06e1 \u064a\u064e\u0633\u06e1\u062a\u064e\u0628\u06e1\u0634\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Allah lah yang mengirimkan angin, lalu angin itu menggerakkan awan dan Allah membentangkannya di langit menurut yang Dia kehendaki, dan menjadikannya bergumpal-gumpal, lalu engkau lihat hujan keluar dari celah-celahnya, maka apabila Dia menurunkannya kepada hamba-hamba-Nya yang Dia kehendaki tiba-tiba mereka bergembira"},{id:49,text:"\u0648\u064e\u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650 \u0623\u064e\u0646 \u064a\u064f\u0646\u064e\u0632\u0651\u064e\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0645\u0651\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u06e6 \u0644\u064e\u0645\u064f\u0628\u06e1\u0644\u0650\u0633\u0650\u064a\u0646\u064e",translation:"Padahal sebelum hujan diturunkan kepada mereka, sungguh mereka benar-benar telah berputus asa"},{id:50,text:"\u0641\u064e\u0671\u0646\u0638\u064f\u0631\u06e1 \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0621\u064e\u0627\u062b\u064e\u0670\u0631\u0650 \u0631\u064e\u062d\u06e1\u0645\u064e\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u064a\u06e1\u0641\u064e \u064a\u064f\u062d\u06e1\u064a\u0650 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0628\u064e\u0639\u06e1\u062f\u064e \u0645\u064e\u0648\u06e1\u062a\u0650\u0647\u064e\u0627\u0653\u06da \u0625\u0650\u0646\u0651\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0645\u064f\u062d\u06e1\u064a\u0650 \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u064e\u0649\u0670\u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0642\u064e\u062f\u0650\u064a\u0631\u065e",translation:"Maka perhatikanlah bekas-bekas rahmat Allah, bagaimana Allah menghidupkan bumi setelah mati (kering). Sungguh, itu berarti Dia pasti (berkuasa) menghidupkan yang telah mati. Dan Dia Mahakuasa atas segala sesuatu"},{id:51,text:"\u0648\u064e\u0644\u064e\u0626\u0650\u0646\u06e1 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0631\u0650\u064a\u062d\u0657\u0627 \u0641\u064e\u0631\u064e\u0623\u064e\u0648\u06e1\u0647\u064f \u0645\u064f\u0635\u06e1\u0641\u064e\u0631\u0651\u0657\u0627 \u0644\u0651\u064e\u0638\u064e\u0644\u0651\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u0647\u0650\u06e6 \u064a\u064e\u0643\u06e1\u0641\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Dan sungguh, jika Kami mengirimkan angin lalu mereka melihat (tumbuh-tumbuhan itu) menjadi kuning (kering), niscaya setelah itu mereka tetap ingkar"},{id:52,text:"\u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u0627 \u062a\u064f\u0633\u06e1\u0645\u0650\u0639\u064f \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u064e\u0649\u0670 \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0633\u06e1\u0645\u0650\u0639\u064f \u0671\u0644\u0635\u0651\u064f\u0645\u0651\u064e \u0671\u0644\u062f\u0651\u064f\u0639\u064e\u0627\u0653\u0621\u064e \u0625\u0650\u0630\u064e\u0627 \u0648\u064e\u0644\u0651\u064e\u0648\u06e1\u0627\u0652 \u0645\u064f\u062f\u06e1\u0628\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Maka sungguh, engkau tidak akan sanggup menjadikan orang-orang yang mati itu dapat mendengar, dan menjadikan orang-orang yang tuli dapat mendengar seruan, apabila mereka berpaling ke belakang"},{id:53,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064e \u0628\u0650\u0647\u064e\u0670\u062f\u0650 \u0671\u0644\u06e1\u0639\u064f\u0645\u06e1\u064a\u0650 \u0639\u064e\u0646 \u0636\u064e\u0644\u064e\u0670\u0644\u064e\u062a\u0650\u0647\u0650\u0645\u06e1\u06d6 \u0625\u0650\u0646 \u062a\u064f\u0633\u06e1\u0645\u0650\u0639\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0641\u064e\u0647\u064f\u0645 \u0645\u0651\u064f\u0633\u06e1\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Dan engkau tidak akan dapat memberi petunjuk kepada orang-orang yang buta (mata hatinya) dari kesesatannya. Dan engkau tidak dapat memperdengarkan (petunjuk Tuhan) kecuali kepada orang-orang yang beriman dengan ayat-ayat Kami, maka mereka itulah orang-orang yang berserah diri (kepada Kami)"},{id:54,text:"\u06de\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0636\u064e\u0639\u06e1\u0641\u0656 \u062b\u064f\u0645\u0651\u064e \u062c\u064e\u0639\u064e\u0644\u064e \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0636\u064e\u0639\u06e1\u0641\u0656 \u0642\u064f\u0648\u0651\u064e\u0629\u0657 \u062b\u064f\u0645\u0651\u064e \u062c\u064e\u0639\u064e\u0644\u064e \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0642\u064f\u0648\u0651\u064e\u0629\u0656 \u0636\u064e\u0639\u06e1\u0641\u0657\u0627 \u0648\u064e\u0634\u064e\u064a\u06e1\u0628\u064e\u0629\u0657\u06da \u064a\u064e\u062e\u06e1\u0644\u064f\u0642\u064f \u0645\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0639\u064e\u0644\u0650\u064a\u0645\u064f \u0671\u0644\u06e1\u0642\u064e\u062f\u0650\u064a\u0631\u064f",translation:"Allah lah yang menciptakan kamu dari keadaan lemah, kemudian Dia menjadikan (kamu) setelah keadaan lemah itu menjadi kuat, kemudian Dia menjadikan (kamu) setelah kuat itu lemah (kembali) dan beruban. Dia menciptakan apa yang Dia kehendaki. Dan Dia Maha Mengetahui, Mahakuasa"},{id:55,text:"\u0648\u064e\u064a\u064e\u0648\u06e1\u0645\u064e \u062a\u064e\u0642\u064f\u0648\u0645\u064f \u0671\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064f \u064a\u064f\u0642\u06e1\u0633\u0650\u0645\u064f \u0671\u0644\u06e1\u0645\u064f\u062c\u06e1\u0631\u0650\u0645\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u0644\u064e\u0628\u0650\u062b\u064f\u0648\u0627\u0652 \u063a\u064e\u064a\u06e1\u0631\u064e \u0633\u064e\u0627\u0639\u064e\u0629\u0656\u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064f\u0624\u06e1\u0641\u064e\u0643\u064f\u0648\u0646\u064e",translation:"Dan pada hari (ketika) terjadinya Kiamat, orang-orang yang berdosa bersumpah, bahwa mereka berdiam (dalam kubur) hanya sesaat (saja). Begitulah dahulu mereka dipalingkan (dari kebenaran)"},{id:56,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0639\u0650\u0644\u06e1\u0645\u064e \u0648\u064e\u0671\u0644\u06e1\u0625\u0650\u064a\u0645\u064e\u0670\u0646\u064e \u0644\u064e\u0642\u064e\u062f\u06e1 \u0644\u064e\u0628\u0650\u062b\u06e1\u062a\u064f\u0645\u06e1 \u0641\u0650\u064a \u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0628\u064e\u0639\u06e1\u062b\u0650\u06d6 \u0641\u064e\u0647\u064e\u0670\u0630\u064e\u0627 \u064a\u064e\u0648\u06e1\u0645\u064f \u0671\u0644\u06e1\u0628\u064e\u0639\u06e1\u062b\u0650 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan orang-orang yang diberi ilmu dan keimanan berkata (kepada orang-orang kafir), \"Sungguh, kamu telah berdiam (dalam kubur) menurut ketetapan Allah, sampai hari berbangkit. Maka inilah hari berbangkit itu, tetapi (dahulu) kamu tidak meyakini(nya)"},{id:57,text:"\u0641\u064e\u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u0644\u0651\u064e\u0627 \u064a\u064e\u0646\u0641\u064e\u0639\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627\u0652 \u0645\u064e\u0639\u06e1\u0630\u0650\u0631\u064e\u062a\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u06e1 \u064a\u064f\u0633\u06e1\u062a\u064e\u0639\u06e1\u062a\u064e\u0628\u064f\u0648\u0646\u064e",translation:"Maka pada hari itu tidak bermanfaat (lagi) permintaan maaf orang-orang yang zalim, dan mereka tidak pula diberi kesempatan bertobat lagi"},{id:58,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0636\u064e\u0631\u064e\u0628\u06e1\u0646\u064e\u0627 \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0641\u0650\u064a \u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u0650 \u0645\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u0645\u064e\u062b\u064e\u0644\u0656\u06da \u0648\u064e\u0644\u064e\u0626\u0650\u0646 \u062c\u0650\u0626\u06e1\u062a\u064e\u0647\u064f\u0645 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0629\u0656 \u0644\u0651\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064e\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u06e1 \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064f\u0628\u06e1\u0637\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Dan sesungguhnya telah Kami jelaskan kepada manusia segala macam perumpamaan dalam Alquran ini. Dan jika engkau membawa suatu ayat kepada mereka, pastilah orang-orang kafir itu akan berkata, \"Kamu hanyalah orang-orang yang membuat kepalsuan belaka"},{id:59,text:"\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064e\u0637\u06e1\u0628\u064e\u0639\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064f\u0644\u064f\u0648\u0628\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Demikianlah Allah mengunci hati orang-orang yang tidak (mau) memahami"},{id:60,text:"\u0641\u064e\u0671\u0635\u06e1\u0628\u0650\u0631\u06e1 \u0625\u0650\u0646\u0651\u064e \u0648\u064e\u0639\u06e1\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u064e\u0642\u0651\u065e\u06d6 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u062e\u0650\u0641\u0651\u064e\u0646\u0651\u064e\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0648\u0642\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Maka bersabarlah engkau (Muhammad), sungguh, janji Allah itu benar dan sekali-kali jangan sampai orang-orang yang tidak meyakini (kebenaran ayat-ayat Allah) itu menggelisahkan engkau"}]},{id:31,name:"\u0644\u0642\u0645\u0627\u0646",transliteration:"Luqman",translation:"Luqman",type:"meccan",total_verses:34,verses:[{id:1,text:"\u0627\u0644\u0653\u0645\u0653",translation:"Alif L\u0101m M\u012bm"},{id:2,text:"\u062a\u0650\u0644\u06e1\u0643\u064e \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u064f \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0671\u0644\u06e1\u062d\u064e\u0643\u0650\u064a\u0645\u0650",translation:"Inilah ayat-ayat Alquran yang mengandung hikmah"},{id:3,text:"\u0647\u064f\u062f\u0657\u0649 \u0648\u064e\u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u0657 \u0644\u0651\u0650\u0644\u06e1\u0645\u064f\u062d\u06e1\u0633\u0650\u0646\u0650\u064a\u0646\u064e",translation:"sebagai petunjuk dan rahmat bagi orang-orang yang berbuat kebaikan"},{id:4,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0642\u0650\u064a\u0645\u064f\u0648\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u064a\u064f\u0624\u06e1\u062a\u064f\u0648\u0646\u064e \u0671\u0644\u0632\u0651\u064e\u0643\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0647\u064f\u0645\u06e1 \u064a\u064f\u0648\u0642\u0650\u0646\u064f\u0648\u0646\u064e",translation:"(yaitu) orang-orang yang melaksanakan salat, menunaikan zakat dan mereka meyakini adanya akhirat"},{id:5,text:"\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0647\u064f\u062f\u0657\u0649 \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1\u06d6 \u0648\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064f\u0641\u06e1\u0644\u0650\u062d\u064f\u0648\u0646\u064e",translation:"Merekalah orang-orang yang tetap mendapat petunjuk dari Tuhannya dan mereka itulah orang-orang yang beruntung"},{id:6,text:"\u0648\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0645\u064e\u0646 \u064a\u064e\u0634\u06e1\u062a\u064e\u0631\u0650\u064a \u0644\u064e\u0647\u06e1\u0648\u064e \u0671\u0644\u06e1\u062d\u064e\u062f\u0650\u064a\u062b\u0650 \u0644\u0650\u064a\u064f\u0636\u0650\u0644\u0651\u064e \u0639\u064e\u0646 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u0650\u063a\u064e\u064a\u06e1\u0631\u0650 \u0639\u0650\u0644\u06e1\u0645\u0656 \u0648\u064e\u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064e\u0647\u064e\u0627 \u0647\u064f\u0632\u064f\u0648\u064b\u0627\u06da \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u065e \u0645\u0651\u064f\u0647\u0650\u064a\u0646\u065e",translation:"Dan di antara manusia (ada) orang yang mempergunakan percakapan kosong untuk menyesatkan (manusia) dari jalan Allah tanpa ilmu dan menjadikannya olok-olokan. Mereka itu akan memperoleh azab yang menghinakan"},{id:7,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062a\u064f\u062a\u06e1\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u064f\u0646\u064e\u0627 \u0648\u064e\u0644\u0651\u064e\u0649\u0670 \u0645\u064f\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u0650\u0631\u0657\u0627 \u0643\u064e\u0623\u064e\u0646 \u0644\u0651\u064e\u0645\u06e1 \u064a\u064e\u0633\u06e1\u0645\u064e\u0639\u06e1\u0647\u064e\u0627 \u0643\u064e\u0623\u064e\u0646\u0651\u064e \u0641\u0650\u064a\u0653 \u0623\u064f\u0630\u064f\u0646\u064e\u064a\u06e1\u0647\u0650 \u0648\u064e\u0642\u06e1\u0631\u0657\u0627\u06d6 \u0641\u064e\u0628\u064e\u0634\u0651\u0650\u0631\u06e1\u0647\u064f \u0628\u0650\u0639\u064e\u0630\u064e\u0627\u0628\u064d \u0623\u064e\u0644\u0650\u064a\u0645\u064d",translation:"(Dan apabila dibacakan kepadanya647) ayat-ayat Kami, dia berpaling dengan menyombongkan diri seolah-olah dia belum mendengarnya, seakan-akan ada sumbatan di kedua telinganya, maka gembirakanlah dia dengan azab yang pedih"},{id:8,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0644\u064e\u0647\u064f\u0645\u06e1 \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u064f \u0671\u0644\u0646\u0651\u064e\u0639\u0650\u064a\u0645\u0650",translation:"Sesungguhnya orang-orang yang beriman dan mengerjakan kebajikan, mereka akan mendapat surga-surga yang penuh kenikmatan"},{id:9,text:"\u062e\u064e\u0670\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627\u06d6 \u0648\u064e\u0639\u06e1\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u064e\u0642\u0651\u0657\u0627\u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0671\u0644\u06e1\u062d\u064e\u0643\u0650\u064a\u0645\u064f",translation:"mereka kekal di dalamnya, sebagai janji Allah yang benar. Dan Dia Mahaperkasa, Mahabijaksana"},{id:10,text:"\u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0628\u0650\u063a\u064e\u064a\u06e1\u0631\u0650 \u0639\u064e\u0645\u064e\u062f\u0656 \u062a\u064e\u0631\u064e\u0648\u06e1\u0646\u064e\u0647\u064e\u0627\u06d6 \u0648\u064e\u0623\u064e\u0644\u06e1\u0642\u064e\u0649\u0670 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0631\u064e\u0648\u064e\u0670\u0633\u0650\u064a\u064e \u0623\u064e\u0646 \u062a\u064e\u0645\u0650\u064a\u062f\u064e \u0628\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0628\u064e\u062b\u0651\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u062f\u064e\u0627\u0653\u0628\u0651\u064e\u0629\u0656\u06da \u0648\u064e\u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0645\u064e\u0627\u0653\u0621\u0657 \u0641\u064e\u0623\u064e\u0646\u06e2\u0628\u064e\u062a\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u0632\u064e\u0648\u06e1\u062c\u0656 \u0643\u064e\u0631\u0650\u064a\u0645\u064d",translation:"Dia menciptakan langit tanpa tiang sebagaimana kamu melihatnya, dan Dia meletakkan gunung-gunung (di permukaan) bumi agar ia (bumi) tidak menggoyangkan kamu; dan memperkembangbiakkan segala macam jenis makhluk bergerak yang bernyawa di bumi. Dan Kami turunkan air hujan dari langit, lalu Kami tumbuhkan padanya segala macam tumbuh-tumbuhan yang baik"},{id:11,text:"\u0647\u064e\u0670\u0630\u064e\u0627 \u062e\u064e\u0644\u06e1\u0642\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0623\u064e\u0631\u064f\u0648\u0646\u0650\u064a \u0645\u064e\u0627\u0630\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u06e6\u06da \u0628\u064e\u0644\u0650 \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0670\u0644\u0656 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u0656",translation:"Inilah ciptaan Allah, maka perlihatkanlah olehmu kepadaku apa yang telah diciptakan oleh (sesembahanmu) selain Allah. Sebenarnya orang-orang yang zalim itu berada di dalam kesesatan yang nyata"},{id:12,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0627 \u0644\u064f\u0642\u06e1\u0645\u064e\u0670\u0646\u064e \u0671\u0644\u06e1\u062d\u0650\u0643\u06e1\u0645\u064e\u0629\u064e \u0623\u064e\u0646\u0650 \u0671\u0634\u06e1\u0643\u064f\u0631\u06e1 \u0644\u0650\u0644\u0651\u064e\u0647\u0650\u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0634\u06e1\u0643\u064f\u0631\u06e1 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0634\u06e1\u0643\u064f\u0631\u064f \u0644\u0650\u0646\u064e\u0641\u06e1\u0633\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u0645\u064e\u0646 \u0643\u064e\u0641\u064e\u0631\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0646\u0650\u064a\u0651\u064c \u062d\u064e\u0645\u0650\u064a\u062f\u065e",translation:"Dan sungguh, telah Kami berikan hikmah kepada Lukman, yaitu, \"Bersyukurlah kepada Allah! Dan barangsiapa bersyukur (kepada Allah), maka sesungguhnya dia bersyukur untuk dirinya sendiri; dan barangsiapa tidak bersyukur (kufur), maka sesungguhnya Allah Mahakaya, Maha Terpuji"},{id:13,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e \u0644\u064f\u0642\u06e1\u0645\u064e\u0670\u0646\u064f \u0644\u0650\u0671\u0628\u06e1\u0646\u0650\u0647\u0650\u06e6 \u0648\u064e\u0647\u064f\u0648\u064e \u064a\u064e\u0639\u0650\u0638\u064f\u0647\u064f\u06e5 \u064a\u064e\u0670\u0628\u064f\u0646\u064e\u064a\u0651\u064e \u0644\u064e\u0627 \u062a\u064f\u0634\u06e1\u0631\u0650\u0643\u06e1 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0634\u0651\u0650\u0631\u06e1\u0643\u064e \u0644\u064e\u0638\u064f\u0644\u06e1\u0645\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u065e",translation:"Dan (ingatlah) ketika Lukman berkata kepada anaknya, ketika dia memberi pelajaran kepadanya, \"Wahai anakku! Janganlah engkau mempersekutukan Allah, sesungguhnya mempersekutukan (Allah) adalah benar-benar kezaliman yang besar"},{id:14,text:"\u0648\u064e\u0648\u064e\u0635\u0651\u064e\u064a\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064e \u0628\u0650\u0648\u064e\u0670\u0644\u0650\u062f\u064e\u064a\u06e1\u0647\u0650 \u062d\u064e\u0645\u064e\u0644\u064e\u062a\u06e1\u0647\u064f \u0623\u064f\u0645\u0651\u064f\u0647\u064f\u06e5 \u0648\u064e\u0647\u06e1\u0646\u064b\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0648\u064e\u0647\u06e1\u0646\u0656 \u0648\u064e\u0641\u0650\u0635\u064e\u0670\u0644\u064f\u0647\u064f\u06e5 \u0641\u0650\u064a \u0639\u064e\u0627\u0645\u064e\u064a\u06e1\u0646\u0650 \u0623\u064e\u0646\u0650 \u0671\u0634\u06e1\u0643\u064f\u0631\u06e1 \u0644\u0650\u064a \u0648\u064e\u0644\u0650\u0648\u064e\u0670\u0644\u0650\u062f\u064e\u064a\u06e1\u0643\u064e \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0671\u0644\u06e1\u0645\u064e\u0635\u0650\u064a\u0631\u064f",translation:"Dan Kami perintahkan kepada manusia (agar berbuat baik) kepada kedua orang tuanya. Ibunya telah mengandungnya dalam keadaan lemah yang bertambah-tambah, dan menyapihnya dalam usia dua tahun.648) Bersyukurlah kepada-Ku dan kepada kedua orang tuamu. Hanya kepada Aku kembalimu"},{id:15,text:"\u0648\u064e\u0625\u0650\u0646 \u062c\u064e\u0670\u0647\u064e\u062f\u064e\u0627\u0643\u064e \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0646 \u062a\u064f\u0634\u06e1\u0631\u0650\u0643\u064e \u0628\u0650\u064a \u0645\u064e\u0627 \u0644\u064e\u064a\u06e1\u0633\u064e \u0644\u064e\u0643\u064e \u0628\u0650\u0647\u0650\u06e6 \u0639\u0650\u0644\u06e1\u0645\u065e \u0641\u064e\u0644\u064e\u0627 \u062a\u064f\u0637\u0650\u0639\u06e1\u0647\u064f\u0645\u064e\u0627\u06d6 \u0648\u064e\u0635\u064e\u0627\u062d\u0650\u0628\u06e1\u0647\u064f\u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0645\u064e\u0639\u06e1\u0631\u064f\u0648\u0641\u0657\u0627\u06d6 \u0648\u064e\u0671\u062a\u0651\u064e\u0628\u0650\u0639\u06e1 \u0633\u064e\u0628\u0650\u064a\u0644\u064e \u0645\u064e\u0646\u06e1 \u0623\u064e\u0646\u064e\u0627\u0628\u064e \u0625\u0650\u0644\u064e\u064a\u0651\u064e\u06da \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0645\u064e\u0631\u06e1\u062c\u0650\u0639\u064f\u0643\u064f\u0645\u06e1 \u0641\u064e\u0623\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0643\u064f\u0645 \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan jika keduanya memaksamu untuk mempersekutukan Aku dengan sesuatu yang engkau tidak mempunyai ilmu tentang itu, maka janganlah engkau menaati keduanya, dan pergaulilah keduanya di dunia dengan baik, dan ikutilah jalan orang yang kembali kepada-Ku. Kemudian hanya kepada-Ku tempat kembalimu, maka akan Aku beritahukan kepadamu apa yang telah kamu kerjakan"},{id:16,text:"\u064a\u064e\u0670\u0628\u064f\u0646\u064e\u064a\u0651\u064e \u0625\u0650\u0646\u0651\u064e\u0647\u064e\u0627\u0653 \u0625\u0650\u0646 \u062a\u064e\u0643\u064f \u0645\u0650\u062b\u06e1\u0642\u064e\u0627\u0644\u064e \u062d\u064e\u0628\u0651\u064e\u0629\u0656 \u0645\u0651\u0650\u0646\u06e1 \u062e\u064e\u0631\u06e1\u062f\u064e\u0644\u0656 \u0641\u064e\u062a\u064e\u0643\u064f\u0646 \u0641\u0650\u064a \u0635\u064e\u062e\u06e1\u0631\u064e\u0629\u064d \u0623\u064e\u0648\u06e1 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0623\u064e\u0648\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u064a\u064e\u0623\u06e1\u062a\u0650 \u0628\u0650\u0647\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0637\u0650\u064a\u0641\u064c \u062e\u064e\u0628\u0650\u064a\u0631\u065e",translation:"(Lukman berkata), \"Wahai anakku! Sungguh, jika ada (suatu perbuatan) seberat biji sawi, dan berada dalam batu atau di langit atau di bumi, niscaya Allah akan memberinya (balasan). Sesungguhnya Allah Mahahalus,649) Mahateliti"},{id:17,text:"\u064a\u064e\u0670\u0628\u064f\u0646\u064e\u064a\u0651\u064e \u0623\u064e\u0642\u0650\u0645\u0650 \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u0623\u06e1\u0645\u064f\u0631\u06e1 \u0628\u0650\u0671\u0644\u06e1\u0645\u064e\u0639\u06e1\u0631\u064f\u0648\u0641\u0650 \u0648\u064e\u0671\u0646\u06e1\u0647\u064e \u0639\u064e\u0646\u0650 \u0671\u0644\u06e1\u0645\u064f\u0646\u0643\u064e\u0631\u0650 \u0648\u064e\u0671\u0635\u06e1\u0628\u0650\u0631\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627\u0653 \u0623\u064e\u0635\u064e\u0627\u0628\u064e\u0643\u064e\u06d6 \u0625\u0650\u0646\u0651\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u0650\u0646\u06e1 \u0639\u064e\u0632\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0623\u064f\u0645\u064f\u0648\u0631\u0650",translation:"Wahai anakku! Laksanakanlah salat dan suruhlah (manusia) berbuat yang makruf dan cegahlah (mereka) dari yang mungkar dan bersabarlah terhadap apa yang menimpamu, sesungguhnya yang demikian itu termasuk perkara yang penting"},{id:18,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0635\u064e\u0639\u0651\u0650\u0631\u06e1 \u062e\u064e\u062f\u0651\u064e\u0643\u064e \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0645\u06e1\u0634\u0650 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0645\u064e\u0631\u064e\u062d\u064b\u0627\u06d6 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0643\u064f\u0644\u0651\u064e \u0645\u064f\u062e\u06e1\u062a\u064e\u0627\u0644\u0656 \u0641\u064e\u062e\u064f\u0648\u0631\u0656",translation:"Dan janganlah kamu memalingkan wajah dari manusia (karena sombong) dan janganlah berjalan di bumi dengan angkuh. Sungguh, Allah tidak menyukai orang-orang yang sombong dan membanggakan diri"},{id:19,text:"\u0648\u064e\u0671\u0642\u06e1\u0635\u0650\u062f\u06e1 \u0641\u0650\u064a \u0645\u064e\u0634\u06e1\u064a\u0650\u0643\u064e \u0648\u064e\u0671\u063a\u06e1\u0636\u064f\u0636\u06e1 \u0645\u0650\u0646 \u0635\u064e\u0648\u06e1\u062a\u0650\u0643\u064e\u06da \u0625\u0650\u0646\u0651\u064e \u0623\u064e\u0646\u0643\u064e\u0631\u064e \u0671\u0644\u06e1\u0623\u064e\u0635\u06e1\u0648\u064e\u0670\u062a\u0650 \u0644\u064e\u0635\u064e\u0648\u06e1\u062a\u064f \u0671\u0644\u06e1\u062d\u064e\u0645\u0650\u064a\u0631\u0650",translation:"(Dan sederhanakanlah dalam berjalan650) dan lunakkanlah suaramu, Sesungguhnya seburuk-buruk suara ialah suara keledai"},{id:20,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0631\u064e\u0648\u06e1\u0627\u0652 \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0633\u064e\u062e\u0651\u064e\u0631\u064e \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0623\u064e\u0633\u06e1\u0628\u064e\u063a\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0646\u0650\u0639\u064e\u0645\u064e\u0647\u064f\u06e5 \u0638\u064e\u0670\u0647\u0650\u0631\u064e\u0629\u0657 \u0648\u064e\u0628\u064e\u0627\u0637\u0650\u0646\u064e\u0629\u0657\u06d7 \u0648\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0645\u064e\u0646 \u064a\u064f\u062c\u064e\u0670\u062f\u0650\u0644\u064f \u0641\u0650\u064a \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u0650\u063a\u064e\u064a\u06e1\u0631\u0650 \u0639\u0650\u0644\u06e1\u0645\u0656 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u062f\u0657\u0649 \u0648\u064e\u0644\u064e\u0627 \u0643\u0650\u062a\u064e\u0670\u0628\u0656 \u0645\u0651\u064f\u0646\u0650\u064a\u0631\u0656",translation:"Tidakkah kamu memperhatikan bahwa Allah telah menundukkan apa yang ada di langit dan apa yang ada di bumi untuk (kepentingan)mu dan menyempurnakan nikmat-Nya untukmu lahir dan batin. Tetapi di antara manusia ada yang membantah tentang (keesaan) Allah tanpa ilmu atau petunjuk dan tanpa Kitab yang memberi penerangan"},{id:21,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0671\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0627\u0652 \u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0628\u064e\u0644\u06e1 \u0646\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f \u0645\u064e\u0627 \u0648\u064e\u062c\u064e\u062f\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0621\u064e\u0646\u064e\u0627\u0653\u06da \u0623\u064e\u0648\u064e\u0644\u064e\u0648\u06e1 \u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u064f \u064a\u064e\u062f\u06e1\u0639\u064f\u0648\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649\u0670 \u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0671\u0644\u0633\u0651\u064e\u0639\u0650\u064a\u0631\u0650",translation:"Dan apabila dikatakan kepada mereka, \"Ikutilah apa yang diturunkan Allah!\" Mereka menjawab, \"(Tidak), tetapi kami (hanya) mengikuti kebiasaan yang kami dapati dari nenek moyang kami.\" Apakah mereka (akan mengikuti nenek moyang mereka) walaupun sebenarnya setan menyeru mereka ke dalam azab api yang menyala-nyala (neraka)"},{id:22,text:"\u06de\u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0633\u06e1\u0644\u0650\u0645\u06e1 \u0648\u064e\u062c\u06e1\u0647\u064e\u0647\u064f\u06e5\u0653 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0647\u064f\u0648\u064e \u0645\u064f\u062d\u06e1\u0633\u0650\u0646\u065e \u0641\u064e\u0642\u064e\u062f\u0650 \u0671\u0633\u06e1\u062a\u064e\u0645\u06e1\u0633\u064e\u0643\u064e \u0628\u0650\u0671\u0644\u06e1\u0639\u064f\u0631\u06e1\u0648\u064e\u0629\u0650 \u0671\u0644\u06e1\u0648\u064f\u062b\u06e1\u0642\u064e\u0649\u0670\u06d7 \u0648\u064e\u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0670\u0642\u0650\u0628\u064e\u0629\u064f \u0671\u0644\u06e1\u0623\u064f\u0645\u064f\u0648\u0631\u0650",translation:"Dan barang siapa berserah diri kepada Allah, sedang dia orang yang berbuat kebaikan, maka sesungguhnya dia telah berpegang kepada buhul (tali) yang kokoh. Hanya kepada Allah kesudahan segala urusan"},{id:23,text:"\u0648\u064e\u0645\u064e\u0646 \u0643\u064e\u0641\u064e\u0631\u064e \u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u062d\u06e1\u0632\u064f\u0646\u0643\u064e \u0643\u064f\u0641\u06e1\u0631\u064f\u0647\u064f\u06e5\u0653\u06da \u0625\u0650\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0645\u064e\u0631\u06e1\u062c\u0650\u0639\u064f\u0647\u064f\u0645\u06e1 \u0641\u064e\u0646\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0647\u064f\u0645 \u0628\u0650\u0645\u064e\u0627 \u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0653\u0627\u0652\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u064f\u06e2 \u0628\u0650\u0630\u064e\u0627\u062a\u0650 \u0671\u0644\u0635\u0651\u064f\u062f\u064f\u0648\u0631\u0650",translation:"Dan barang siapa kafir maka kekafirannya itu janganlah menyedihkanmu (Muhammad). Hanya kepada Kami tempat kembali mereka, lalu Kami beritakan kepada mereka apa yang telah mereka kerjakan. Sesungguhnya Allah Maha Mengetahui segala isi hati"},{id:24,text:"\u0646\u064f\u0645\u064e\u062a\u0651\u0650\u0639\u064f\u0647\u064f\u0645\u06e1 \u0642\u064e\u0644\u0650\u064a\u0644\u0657\u0627 \u062b\u064f\u0645\u0651\u064e \u0646\u064e\u0636\u06e1\u0637\u064e\u0631\u0651\u064f\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649\u0670 \u0639\u064e\u0630\u064e\u0627\u0628\u064d \u063a\u064e\u0644\u0650\u064a\u0638\u0656",translation:"Kami biarkan mereka bersenang-senang sebentar, kemudian Kami paksa mereka (masuk) ke dalam azab yang keras"},{id:25,text:"\u0648\u064e\u0644\u064e\u0626\u0650\u0646 \u0633\u064e\u0623\u064e\u0644\u06e1\u062a\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u0646\u06e1 \u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0644\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06da \u0642\u064f\u0644\u0650 \u0671\u0644\u06e1\u062d\u064e\u0645\u06e1\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650\u06da \u0628\u064e\u0644\u06e1 \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064f\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan sungguh, jika engkau (Muhammad) tanyakan kepada mereka, \"Siapakah yang menciptakan langit dan bumi?\" Tentu mereka akan menjawab, \"Allah.\" Katakanlah, \"Segala puji bagi Allah,\" tetapi kebanyakan mereka tidak mengetahui"},{id:26,text:"\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u063a\u064e\u0646\u0650\u064a\u0651\u064f \u0671\u0644\u06e1\u062d\u064e\u0645\u0650\u064a\u062f\u064f",translation:"Milik Allah lah apa yang di langit dan di bumi. Sesungguhnya Allah, Dialah Yang Mahakaya, Maha Terpuji"},{id:27,text:"\u0648\u064e\u0644\u064e\u0648\u06e1 \u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0645\u0650\u0646 \u0634\u064e\u062c\u064e\u0631\u064e\u0629\u064d \u0623\u064e\u0642\u06e1\u0644\u064e\u0670\u0645\u065e \u0648\u064e\u0671\u0644\u06e1\u0628\u064e\u062d\u06e1\u0631\u064f \u064a\u064e\u0645\u064f\u062f\u0651\u064f\u0647\u064f\u06e5 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u0647\u0650\u06e6 \u0633\u064e\u0628\u06e1\u0639\u064e\u0629\u064f \u0623\u064e\u0628\u06e1\u062d\u064f\u0631\u0656 \u0645\u0651\u064e\u0627 \u0646\u064e\u0641\u0650\u062f\u064e\u062a\u06e1 \u0643\u064e\u0644\u0650\u0645\u064e\u0670\u062a\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0632\u0650\u064a\u0632\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u065e",translation:"Dan seandainya pohon-pohon di bumi menjadi pena dan lautan (menjadi tinta), ditambahkan kepadanya tujuh lautan (lagi) setelah (kering)nya, niscaya tidak akan habis-habisnya (dituliskan) kalimat-kalimat Allah.651) Sesungguhnya Allah Mahaperkasa, Mahabijaksana"},{id:28,text:"\u0645\u0651\u064e\u0627 \u062e\u064e\u0644\u06e1\u0642\u064f\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u0628\u064e\u0639\u06e1\u062b\u064f\u0643\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064e\u0646\u064e\u0641\u06e1\u0633\u0656 \u0648\u064e\u0670\u062d\u0650\u062f\u064e\u0629\u064d\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0633\u064e\u0645\u0650\u064a\u0639\u064f\u06e2 \u0628\u064e\u0635\u0650\u064a\u0631\u064c",translation:"Menciptakan dan membangkitkan kamu (bagi Allah) hanyalah seperti (menciptakan dan membangkitkan) satu jiwa saja (mudah). Sesungguhnya Allah Maha Mendengar, Maha Melihat"},{id:29,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0631\u064e \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u0648\u0644\u0650\u062c\u064f \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u064e \u0641\u0650\u064a \u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u0648\u064e\u064a\u064f\u0648\u0644\u0650\u062c\u064f \u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u0641\u0650\u064a \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u0650 \u0648\u064e\u0633\u064e\u062e\u0651\u064e\u0631\u064e \u0671\u0644\u0634\u0651\u064e\u0645\u06e1\u0633\u064e \u0648\u064e\u0671\u0644\u06e1\u0642\u064e\u0645\u064e\u0631\u064e\u06d6 \u0643\u064f\u0644\u0651\u065e \u064a\u064e\u062c\u06e1\u0631\u0650\u064a\u0653 \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u062c\u064e\u0644\u0656 \u0645\u0651\u064f\u0633\u064e\u0645\u0651\u0657\u0649 \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u062e\u064e\u0628\u0650\u064a\u0631\u065e",translation:"Tidakkah engkau memperhatikan, bahwa Allah memasukkan malam ke dalam siang dan memasukkan siang ke dalam malam dan Dia menundukkan matahari dan bulan, masing-masing beredar sampai kepada waktu yang ditentukan. Sungguh, Allah Mahateliti atas apa yang kamu kerjakan"},{id:30,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0645\u064e\u0627 \u064a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650 \u0671\u0644\u06e1\u0628\u064e\u0670\u0637\u0650\u0644\u064f \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0639\u064e\u0644\u0650\u064a\u0651\u064f \u0671\u0644\u06e1\u0643\u064e\u0628\u0650\u064a\u0631\u064f",translation:"Demikianlah, karena sesungguhnya Allah, Dialah (Tuhan) yang sebenarnya dan apa saja yang mereka seru selain Allah adalah batil. Dan sesungguhnya Allah, Dialah Yang Mahatinggi, Mahabesar"},{id:31,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0631\u064e \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u06e1\u0641\u064f\u0644\u06e1\u0643\u064e \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0641\u0650\u064a \u0671\u0644\u06e1\u0628\u064e\u062d\u06e1\u0631\u0650 \u0628\u0650\u0646\u0650\u0639\u06e1\u0645\u064e\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u0650\u064a\u064f\u0631\u0650\u064a\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0647\u0650\u06e6\u0653\u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0623\u0653\u064a\u064e\u0670\u062a\u0656 \u0644\u0651\u0650\u0643\u064f\u0644\u0651\u0650 \u0635\u064e\u0628\u0651\u064e\u0627\u0631\u0656 \u0634\u064e\u0643\u064f\u0648\u0631\u0656",translation:"Tidakkah engkau memperhatikan bahwa sesungguhnya kapal itu berlayar di laut dengan nikmat Allah, agar diperlihatkan-Nya kepadamu sebagian dari tanda-tanda (kebesaran)-Nya. Sungguh, pada yang demikian itu terdapat tanda-tanda (kebesaran)-Nya bagi setiap orang yang sangat sabar dan banyak bersyukur"},{id:32,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u063a\u064e\u0634\u0650\u064a\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u0648\u06e1\u062c\u065e \u0643\u064e\u0671\u0644\u0638\u0651\u064f\u0644\u064e\u0644\u0650 \u062f\u064e\u0639\u064e\u0648\u064f\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064f\u062e\u06e1\u0644\u0650\u0635\u0650\u064a\u0646\u064e \u0644\u064e\u0647\u064f \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u064e \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0646\u064e\u062c\u0651\u064e\u0649\u0670\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u0628\u064e\u0631\u0651\u0650 \u0641\u064e\u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064f\u0642\u06e1\u062a\u064e\u0635\u0650\u062f\u065e\u06da \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u062c\u06e1\u062d\u064e\u062f\u064f \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064f\u0644\u0651\u064f \u062e\u064e\u062a\u0651\u064e\u0627\u0631\u0656 \u0643\u064e\u0641\u064f\u0648\u0631\u0656",translation:"(Dan apabila mereka digulung ombak yang besar seperti gunung, mereka menyeru Allah dengan tulus ikhlas beragama kepada-Nya. Tetapi ketika Allah menyelamatkan mereka sampai di daratan, lalu sebagian mereka tetap menempuh jalan yang lurus.652) Adapun yang mengingkari ayat-ayat Kami hanyalah pengkhianat yang tidak berterima kasih"},{id:33,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0671\u062e\u06e1\u0634\u064e\u0648\u06e1\u0627\u0652 \u064a\u064e\u0648\u06e1\u0645\u0657\u0627 \u0644\u0651\u064e\u0627 \u064a\u064e\u062c\u06e1\u0632\u0650\u064a \u0648\u064e\u0627\u0644\u0650\u062f\u064c \u0639\u064e\u0646 \u0648\u064e\u0644\u064e\u062f\u0650\u0647\u0650\u06e6 \u0648\u064e\u0644\u064e\u0627 \u0645\u064e\u0648\u06e1\u0644\u064f\u0648\u062f\u064c \u0647\u064f\u0648\u064e \u062c\u064e\u0627\u0632\u064d \u0639\u064e\u0646 \u0648\u064e\u0627\u0644\u0650\u062f\u0650\u0647\u0650\u06e6 \u0634\u064e\u064a\u06e1\u0640\u0654\u064b\u0627\u06da \u0625\u0650\u0646\u0651\u064e \u0648\u064e\u0639\u06e1\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u064e\u0642\u0651\u065e\u06d6 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u063a\u064f\u0631\u0651\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u064f \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u063a\u064f\u0631\u0651\u064e\u0646\u0651\u064e\u0643\u064f\u0645 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u063a\u064e\u0631\u064f\u0648\u0631\u064f",translation:"Wahai manusia! Bertakwalah kepada Tuhanmu dan takutlah pada hari yang (ketika itu) seorang bapak tidak dapat menolong anaknya, dan seorang anak tidak dapat (pula) menolong bapaknya sedikit pun. Sungguh, janji Allah pasti benar, maka janganlah sekali-kali kamu terpedaya oleh kehidupan dunia, dan jangan sampai kamu terpedaya oleh penipu dalam (menaati) Allah"},{id:34,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u0650\u0646\u062f\u064e\u0647\u064f\u06e5 \u0639\u0650\u0644\u06e1\u0645\u064f \u0671\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u0650 \u0648\u064e\u064a\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u064f \u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u062b\u064e \u0648\u064e\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u062d\u064e\u0627\u0645\u0650\u06d6 \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u062f\u06e1\u0631\u0650\u064a \u0646\u064e\u0641\u06e1\u0633\u065e \u0645\u0651\u064e\u0627\u0630\u064e\u0627 \u062a\u064e\u0643\u06e1\u0633\u0650\u0628\u064f \u063a\u064e\u062f\u0657\u0627\u06d6 \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u062f\u06e1\u0631\u0650\u064a \u0646\u064e\u0641\u06e1\u0633\u064f\u06e2 \u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0623\u064e\u0631\u06e1\u0636\u0656 \u062a\u064e\u0645\u064f\u0648\u062a\u064f\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u062e\u064e\u0628\u0650\u064a\u0631\u064f\u06e2",translation:"Sesungguhnya hanya di sisi Allah ilmu tentang hari Kiamat; dan Dia yang menurunkan hujan, dan mengetahui apa yang ada dalam rahim. Dan tidak ada seorang pun yang dapat mengetahui (dengan pasti) apa yang akan dikerjakannya besok.653) Dan tidak ada seorang pun yang dapat mengetahui di bumi mana dia akan mati. Sungguh, Allah Maha Mengetahui, Maha Mengenal"}]},{id:32,name:"\u0627\u0644\u0633\u062c\u062f\u0629",transliteration:"As-Sajdah",translation:"Sujud",type:"meccan",total_verses:30,verses:[{id:1,text:"\u0627\u0644\u0653\u0645\u0653",translation:"Alif L\u0101m M\u012bm"},{id:2,text:"\u062a\u064e\u0646\u0632\u0650\u064a\u0644\u064f \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0644\u064e\u0627 \u0631\u064e\u064a\u06e1\u0628\u064e \u0641\u0650\u064a\u0647\u0650 \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Turunnya Alquran itu tidak ada keraguan padanya, (yaitu) dari Tuhan seluruh alam"},{id:3,text:"\u0623\u064e\u0645\u06e1 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0671\u0641\u06e1\u062a\u064e\u0631\u064e\u0649\u0670\u0647\u064f\u06da \u0628\u064e\u0644\u06e1 \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064e \u0644\u0650\u062a\u064f\u0646\u0630\u0650\u0631\u064e \u0642\u064e\u0648\u06e1\u0645\u0657\u0627 \u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u062a\u064e\u0649\u0670\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0646\u0651\u064e\u0630\u0650\u064a\u0631\u0656 \u0645\u0651\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0647\u06e1\u062a\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Tetapi mengapa mereka (orang kafir) mengatakan, \"Dia (Muhammad) telah mengada-adakannya.\" Tidak, Alquran itu kebenaran (yang datang) dari Tuhanmu, agar engkau memberi peringatan kepada kaum yang belum pernah didatangi orang yang memberi peringatan sebelum engkau; agar mereka mendapat petunjuk"},{id:4,text:"\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0641\u0650\u064a \u0633\u0650\u062a\u0651\u064e\u0629\u0650 \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u0656 \u062b\u064f\u0645\u0651\u064e \u0671\u0633\u06e1\u062a\u064e\u0648\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0639\u064e\u0631\u06e1\u0634\u0650\u06d6 \u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u06e6 \u0645\u0650\u0646 \u0648\u064e\u0644\u0650\u064a\u0651\u0656 \u0648\u064e\u0644\u064e\u0627 \u0634\u064e\u0641\u0650\u064a\u0639\u064d\u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"(Allah yang menciptakan langit dan bumi dan apa yang ada di antara keduanya dalam enam masa, kemudian Dia bersemayam di atas Arasy.654) Bagimu tidak ada seorang pun penolong maupun pemberi syafaat655) selain Dia. Maka apakah kamu tidak memperhatikan"},{id:5,text:"\u064a\u064f\u062f\u064e\u0628\u0651\u0650\u0631\u064f \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0631\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u0639\u06e1\u0631\u064f\u062c\u064f \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0641\u0650\u064a \u064a\u064e\u0648\u06e1\u0645\u0656 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0642\u06e1\u062f\u064e\u0627\u0631\u064f\u0647\u064f\u06e5\u0653 \u0623\u064e\u0644\u06e1\u0641\u064e \u0633\u064e\u0646\u064e\u0629\u0656 \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0639\u064f\u062f\u0651\u064f\u0648\u0646\u064e",translation:"Dia mengatur segala urusan dari langit ke bumi, kemudian (urusan) itu naik kepada-Nya656) dalam satu hari yang kadarnya (lamanya) adalah seribu tahun menurut perhitunganmu"},{id:6,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0639\u064e\u0670\u0644\u0650\u0645\u064f \u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u0628\u0650 \u0648\u064e\u0671\u0644\u0634\u0651\u064e\u0647\u064e\u0670\u062f\u064e\u0629\u0650 \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0671\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",translation:"Yang demikian itu, ialah Tuhan yang mengetahui yang gaib dan yang nyata, Yang Mahaperkasa, Maha Penyayang"},{id:7,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064e \u0643\u064f\u0644\u0651\u064e \u0634\u064e\u064a\u06e1\u0621\u064d \u062e\u064e\u0644\u064e\u0642\u064e\u0647\u064f\u06e5\u06d6 \u0648\u064e\u0628\u064e\u062f\u064e\u0623\u064e \u062e\u064e\u0644\u06e1\u0642\u064e \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u0650 \u0645\u0650\u0646 \u0637\u0650\u064a\u0646\u0656",translation:"Yang memperindah segala sesuatu yang Dia ciptakan dan yang memulai penciptaan manusia dari tanah"},{id:8,text:"\u062b\u064f\u0645\u0651\u064e \u062c\u064e\u0639\u064e\u0644\u064e \u0646\u064e\u0633\u06e1\u0644\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646 \u0633\u064f\u0644\u064e\u0670\u0644\u064e\u0629\u0656 \u0645\u0651\u0650\u0646 \u0645\u0651\u064e\u0627\u0653\u0621\u0656 \u0645\u0651\u064e\u0647\u0650\u064a\u0646\u0656",translation:"kemudian Dia menjadikan keturunannya dari saripati air yang hina (air mani)"},{id:9,text:"\u062b\u064f\u0645\u0651\u064e \u0633\u064e\u0648\u0651\u064e\u0649\u0670\u0647\u064f \u0648\u064e\u0646\u064e\u0641\u064e\u062e\u064e \u0641\u0650\u064a\u0647\u0650 \u0645\u0650\u0646 \u0631\u0651\u064f\u0648\u062d\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u06e1\u0639\u064e \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0628\u06e1\u0635\u064e\u0670\u0631\u064e \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0641\u06e1\u0640\u0654\u0650\u062f\u064e\u0629\u064e\u06da \u0642\u064e\u0644\u0650\u064a\u0644\u0657\u0627 \u0645\u0651\u064e\u0627 \u062a\u064e\u0634\u06e1\u0643\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Kemudian Dia menyempurnakannya dan meniupkan roh (ciptaan)-Nya ke dalam (tubuh)nya dan Dia menjadikan pendengaran, penglihatan dan hati bagimu, (tetapi) sedikit sekali dari kamu yang bersyukur"},{id:10,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0621\u0650\u0630\u064e\u0627 \u0636\u064e\u0644\u064e\u0644\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0623\u064e\u0621\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0641\u0650\u064a \u062e\u064e\u0644\u06e1\u0642\u0656 \u062c\u064e\u062f\u0650\u064a\u062f\u0650\u06ed\u06da \u0628\u064e\u0644\u06e1 \u0647\u064f\u0645 \u0628\u0650\u0644\u0650\u0642\u064e\u0627\u0653\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0643\u064e\u0670\u0641\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Dan mereka berkata, \"Apakah apabila kami telah lenyap (hancur) di dalam tanah, kami akan berada dalam ciptaan yang baru?\"657) Bahkan mereka mengingkari pertemuan dengan Tuhannya"},{id:11,text:"\u06de\u0642\u064f\u0644\u06e1 \u064a\u064e\u062a\u064e\u0648\u064e\u0641\u0651\u064e\u0649\u0670\u0643\u064f\u0645 \u0645\u0651\u064e\u0644\u064e\u0643\u064f \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0648\u064f\u0643\u0651\u0650\u0644\u064e \u0628\u0650\u0643\u064f\u0645\u06e1 \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1 \u062a\u064f\u0631\u06e1\u062c\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Katakanlah, \"Malaikat maut yang diserahi untuk (mencabut nyawa) mu akan mematikan kamu, kemudian kepada Tuhanmu, kamu akan dikembalikan"},{id:12,text:"\u0648\u064e\u0644\u064e\u0648\u06e1 \u062a\u064e\u0631\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u0650 \u0671\u0644\u06e1\u0645\u064f\u062c\u06e1\u0631\u0650\u0645\u064f\u0648\u0646\u064e \u0646\u064e\u0627\u0643\u0650\u0633\u064f\u0648\u0627\u0652 \u0631\u064f\u0621\u064f\u0648\u0633\u0650\u0647\u0650\u0645\u06e1 \u0639\u0650\u0646\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627\u0653 \u0623\u064e\u0628\u06e1\u0635\u064e\u0631\u06e1\u0646\u064e\u0627 \u0648\u064e\u0633\u064e\u0645\u0650\u0639\u06e1\u0646\u064e\u0627 \u0641\u064e\u0671\u0631\u06e1\u062c\u0650\u0639\u06e1\u0646\u064e\u0627 \u0646\u064e\u0639\u06e1\u0645\u064e\u0644\u06e1 \u0635\u064e\u0670\u0644\u0650\u062d\u064b\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0645\u064f\u0648\u0642\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Dan (alangkah ngerinya), jika sekiranya kamu melihat orang-orang yang berdosa itu menundukkan kepalanya di hadapan Tuhannya, (mereka berkata), \"Ya Tuhan kami, kami telah melihat dan mendengar, maka kembalikanlah kami (ke dunia), niscaya kami akan mengerjakan kebajikan. Sungguh, kami adalah orang-orang yang yakin"},{id:13,text:"\u0648\u064e\u0644\u064e\u0648\u06e1 \u0634\u0650\u0626\u06e1\u0646\u064e\u0627 \u0644\u064e\u0623\u0653\u062a\u064e\u064a\u06e1\u0646\u064e\u0627 \u0643\u064f\u0644\u0651\u064e \u0646\u064e\u0641\u06e1\u0633\u064d \u0647\u064f\u062f\u064e\u0649\u0670\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u06e1 \u062d\u064e\u0642\u0651\u064e \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0644\u064f \u0645\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0623\u064e\u0645\u06e1\u0644\u064e\u0623\u064e\u0646\u0651\u064e \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u062c\u0650\u0646\u0651\u064e\u0629\u0650 \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0623\u064e\u062c\u06e1\u0645\u064e\u0639\u0650\u064a\u0646\u064e",translation:"Dan jika Kami menghendaki niscaya Kami berikan kepada setiap jiwa petunjuk (bagi)nya, tetapi telah ditetapkan perkataan (ketetapan) dari-Ku, \"Pasti akan Aku penuhi neraka Jahanam dengan jin dan manusia bersama-sama"},{id:14,text:"\u0641\u064e\u0630\u064f\u0648\u0642\u064f\u0648\u0627\u0652 \u0628\u0650\u0645\u064e\u0627 \u0646\u064e\u0633\u0650\u064a\u062a\u064f\u0645\u06e1 \u0644\u0650\u0642\u064e\u0627\u0653\u0621\u064e \u064a\u064e\u0648\u06e1\u0645\u0650\u0643\u064f\u0645\u06e1 \u0647\u064e\u0670\u0630\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0627 \u0646\u064e\u0633\u0650\u064a\u0646\u064e\u0670\u0643\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0630\u064f\u0648\u0642\u064f\u0648\u0627\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0671\u0644\u06e1\u062e\u064f\u0644\u06e1\u062f\u0650 \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Maka rasakanlah olehmu (azab ini) disebabkan kamu melalaikan pertemuan dengan harimu ini (hari Kiamat), sesungguhnya Kami pun melalaikan kamu dan rasakanlah azab yang kekal, atas apa yang telah kamu kerjakan"},{id:15,text:"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0625\u0650\u0630\u064e\u0627 \u0630\u064f\u0643\u0651\u0650\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u064e\u0627 \u062e\u064e\u0631\u0651\u064f\u0648\u0627\u0652\u06e4 \u0633\u064f\u062c\u0651\u064e\u062f\u0657\u0627\u06e4 \u0648\u064e\u0633\u064e\u0628\u0651\u064e\u062d\u064f\u0648\u0627\u0652 \u0628\u0650\u062d\u064e\u0645\u06e1\u062f\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u0650\u0631\u064f\u0648\u0646\u064e\u06e9",translation:"Orang-orang yang beriman dengan ayat-ayat Kami, hanyalah orang-orang yang apabila diperingatkan dengannya (ayat-ayat Kami), mereka menyungkur sujud658) dan bertasbih serta memuji Tuhannya, dan mereka tidak menyombongkan diri"},{id:16,text:"\u062a\u064e\u062a\u064e\u062c\u064e\u0627\u0641\u064e\u0649\u0670 \u062c\u064f\u0646\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u06e1 \u0639\u064e\u0646\u0650 \u0671\u0644\u06e1\u0645\u064e\u0636\u064e\u0627\u062c\u0650\u0639\u0650 \u064a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u0645\u06e1 \u062e\u064e\u0648\u06e1\u0641\u0657\u0627 \u0648\u064e\u0637\u064e\u0645\u064e\u0639\u0657\u0627 \u0648\u064e\u0645\u0650\u0645\u0651\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u064a\u064f\u0646\u0641\u0650\u0642\u064f\u0648\u0646\u064e",translation:"(Lambung mereka jauh dari tempat tidurnya,659) mereka berdoa kepada Tuhannya dengan rasa takut dan penuh harap, dan mereka menginfakkan sebagian dari rezeki yang Kami berikan kepada mereka"},{id:17,text:"\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0646\u064e\u0641\u06e1\u0633\u065e \u0645\u0651\u064e\u0627\u0653 \u0623\u064f\u062e\u06e1\u0641\u0650\u064a\u064e \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0642\u064f\u0631\u0651\u064e\u0629\u0650 \u0623\u064e\u0639\u06e1\u064a\u064f\u0646\u0656 \u062c\u064e\u0632\u064e\u0627\u0653\u0621\u064e\u06e2 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Maka tidak seorang pun mengetahui apa yang disembunyikan untuk mereka yaitu (bermacam-macam nikmat) yang menyenangkan hati sebagai balasan terhadap apa yang mereka kerjakan"},{id:18,text:"\u0623\u064e\u0641\u064e\u0645\u064e\u0646 \u0643\u064e\u0627\u0646\u064e \u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0657\u0627 \u0643\u064e\u0645\u064e\u0646 \u0643\u064e\u0627\u0646\u064e \u0641\u064e\u0627\u0633\u0650\u0642\u0657\u0627\u06da \u0644\u0651\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0648\u064f\u06e5\u0646\u064e",translation:"Maka apakah orang yang beriman seperti orang yang fasik (kafir)? Mereka tidak sama"},{id:19,text:"\u0623\u064e\u0645\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0641\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u064f \u0671\u0644\u06e1\u0645\u064e\u0623\u06e1\u0648\u064e\u0649\u0670 \u0646\u064f\u0632\u064f\u0644\u064e\u06e2\u0627 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Adapun orang-orang yang beriman dan mengerjakan kebajikan, maka mereka akan mendapat surga-surga tempat kediaman, sebagai pahala atas apa yang telah mereka kerjakan"},{id:20,text:"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0641\u064e\u0633\u064e\u0642\u064f\u0648\u0627\u0652 \u0641\u064e\u0645\u064e\u0623\u06e1\u0648\u064e\u0649\u0670\u0647\u064f\u0645\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u064f\u06d6 \u0643\u064f\u0644\u0651\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0631\u064e\u0627\u062f\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646 \u064a\u064e\u062e\u06e1\u0631\u064f\u062c\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1\u0647\u064e\u0627\u0653 \u0623\u064f\u0639\u0650\u064a\u062f\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0630\u064f\u0648\u0642\u064f\u0648\u0627\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0643\u064f\u0646\u062a\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Dan adapun orang-orang yang fasik (kafir), maka tempat kediaman mereka adalah neraka. Setiap kali mereka hendak keluar darinya, mereka dikembalikan (lagi) ke dalamnya dan dikatakan kepada mereka, \"Rasakanlah azab neraka yang dahulu kamu dustakan"},{id:21,text:"\u0648\u064e\u0644\u064e\u0646\u064f\u0630\u0650\u064a\u0642\u064e\u0646\u0651\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0671\u0644\u06e1\u0623\u064e\u062f\u06e1\u0646\u064e\u0649\u0670 \u062f\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0671\u0644\u06e1\u0623\u064e\u0643\u06e1\u0628\u064e\u0631\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0631\u06e1\u062c\u0650\u0639\u064f\u0648\u0646\u064e",translation:"Dan pasti Kami timpakan kepada mereka sebagian siksa yang dekat (di dunia) sebelum azab yang lebih besar (di akhirat); agar mereka kembali (ke jalan yang benar)"},{id:22,text:"\u0648\u064e\u0645\u064e\u0646\u06e1 \u0623\u064e\u0638\u06e1\u0644\u064e\u0645\u064f \u0645\u0650\u0645\u0651\u064e\u0646 \u0630\u064f\u0643\u0651\u0650\u0631\u064e \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u06e6 \u062b\u064f\u0645\u0651\u064e \u0623\u064e\u0639\u06e1\u0631\u064e\u0636\u064e \u0639\u064e\u0646\u06e1\u0647\u064e\u0627\u0653\u06da \u0625\u0650\u0646\u0651\u064e\u0627 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u062c\u06e1\u0631\u0650\u0645\u0650\u064a\u0646\u064e \u0645\u064f\u0646\u062a\u064e\u0642\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Dan siapakah yang lebih zalim daripada orang yang telah diperingatkan dengan ayat-ayat Tuhannya, kemudian dia berpaling darinya? Sungguh, Kami akan memberikan balasan kepada orang-orang yang berdosa"},{id:23,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0646 \u0641\u0650\u064a \u0645\u0650\u0631\u06e1\u064a\u064e\u0629\u0656 \u0645\u0651\u0650\u0646 \u0644\u0651\u0650\u0642\u064e\u0627\u0653\u0626\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f \u0647\u064f\u062f\u0657\u0649 \u0644\u0651\u0650\u0628\u064e\u0646\u0650\u064a\u0653 \u0625\u0650\u0633\u06e1\u0631\u064e\u0640\u0670\u0653\u0621\u0650\u064a\u0644\u064e",translation:"Dan sungguh, telah Kami anugerahkan Kitab (Taurat) kepada Musa, maka janganlah engkau (Muhammad) ragu-ragu menerimanya (Alquran) dan Kami jadikan Kitab (Taurat) itu petunjuk bagi Bani Israil"},{id:24,text:"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0623\u064e\u0626\u0650\u0645\u0651\u064e\u0629\u0657 \u064a\u064e\u0647\u06e1\u062f\u064f\u0648\u0646\u064e \u0628\u0650\u0623\u064e\u0645\u06e1\u0631\u0650\u0646\u064e\u0627 \u0644\u064e\u0645\u0651\u064e\u0627 \u0635\u064e\u0628\u064e\u0631\u064f\u0648\u0627\u0652\u06d6 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u064a\u064f\u0648\u0642\u0650\u0646\u064f\u0648\u0646\u064e",translation:"(Dan Kami jadikan diantara mereka itu pemimpin-pemimpin yang memberi petunjuk dengan perintah Kami selama mereka sabar.661) Mereka meyakini ayat-ayat Kami"},{id:25,text:"\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0647\u064f\u0648\u064e \u064a\u064e\u0641\u06e1\u0635\u0650\u0644\u064f \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u0641\u0650\u064a\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0647\u0650 \u064a\u064e\u062e\u06e1\u062a\u064e\u0644\u0650\u0641\u064f\u0648\u0646\u064e",translation:"Sungguh Tuhanmu, Dia yang memberikan keputusan di antara mereka pada hari Kiamat tentang apa yang dahulu mereka perselisihkan padanya"},{id:26,text:"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0647\u06e1\u062f\u0650 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0645\u06e1 \u0623\u064e\u0647\u06e1\u0644\u064e\u0643\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0642\u064f\u0631\u064f\u0648\u0646\u0650 \u064a\u064e\u0645\u06e1\u0634\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0645\u064e\u0633\u064e\u0670\u0643\u0650\u0646\u0650\u0647\u0650\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0623\u0653\u064a\u064e\u0670\u062a\u064d\u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u0645\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Dan tidakkah menjadi petunjuk bagi mereka, betapa banyak umat-umat sebelum mereka yang telah Kami binasakan, sedangkan mereka sendiri berjalan di tempat-tempat kediaman mereka. Sungguh, pada yang demikian itu terdapat tanda-tanda (kekuasaan Allah). Apakah mereka tidak mendengarkan (memperhatikan)"},{id:27,text:"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0631\u064e\u0648\u06e1\u0627\u0652 \u0623\u064e\u0646\u0651\u064e\u0627 \u0646\u064e\u0633\u064f\u0648\u0642\u064f \u0671\u0644\u06e1\u0645\u064e\u0627\u0653\u0621\u064e \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0671\u0644\u06e1\u062c\u064f\u0631\u064f\u0632\u0650 \u0641\u064e\u0646\u064f\u062e\u06e1\u0631\u0650\u062c\u064f \u0628\u0650\u0647\u0650\u06e6 \u0632\u064e\u0631\u06e1\u0639\u0657\u0627 \u062a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f \u0645\u0650\u0646\u06e1\u0647\u064f \u0623\u064e\u0646\u06e1\u0639\u064e\u0670\u0645\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0646\u0641\u064f\u0633\u064f\u0647\u064f\u0645\u06e1\u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u064a\u064f\u0628\u06e1\u0635\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Dan tidakkah mereka memperhatikan, bahwa Kami mengarahkan (awan yang mengandung) air ke bumi yang tandus, lalu Kami tumbuhkan (dengan air hujan itu) tanam-tanaman sehingga hewan-hewan ternak mereka dan mereka sendiri dapat makan darinya. Maka mengapa mereka tidak memperhatikan"},{id:28,text:"\u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0645\u064e\u062a\u064e\u0649\u0670 \u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u06e1\u0641\u064e\u062a\u06e1\u062d\u064f \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0635\u064e\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Dan mereka bertanya, \"Kapankah kemenangan itu (datang) jika engkau orang yang benar"},{id:29,text:"\u0642\u064f\u0644\u06e1 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0641\u064e\u062a\u06e1\u062d\u0650 \u0644\u064e\u0627 \u064a\u064e\u0646\u0641\u064e\u0639\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u064a\u0645\u064e\u0670\u0646\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u06e1 \u064a\u064f\u0646\u0638\u064e\u0631\u064f\u0648\u0646\u064e",translation:"(Katakanlah, \"Pada hari kemenangan662) itu, tidak berguna lagi bagi orang-orang kafir keimanan mereka dan mereka tidak diberi penangguhan"},{id:30,text:"\u0641\u064e\u0623\u064e\u0639\u06e1\u0631\u0650\u0636\u06e1 \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0648\u064e\u0671\u0646\u062a\u064e\u0638\u0650\u0631\u06e1 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645 \u0645\u0651\u064f\u0646\u062a\u064e\u0638\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Maka berpalinglah engkau dari mereka dan tunggulah, sesungguhnya mereka (juga) menunggu"}]},{id:33,name:"\u0627\u0644\u0623\u062d\u0632\u0627\u0628",transliteration:"Al-Ahzab",translation:"Golongan yang Bersekutu",type:"medinan",total_verses:73,verses:[{id:1,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064f \u0671\u062a\u0651\u064e\u0642\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0637\u0650\u0639\u0650 \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0646\u064e\u0670\u0641\u0650\u0642\u0650\u064a\u0646\u064e\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u064b\u0627 \u062d\u064e\u0643\u0650\u064a\u0645\u0657\u0627",translation:"Wahai Nabi! Bertakwalah kepada Allah dan janganlah engkau menuruti (keinginan) orang-orang kafir dan orang-orang munafik. Sesungguhnya Allah Maha Mengetahui, Mahabijaksana"},{id:2,text:"\u0648\u064e\u0671\u062a\u0651\u064e\u0628\u0650\u0639\u06e1 \u0645\u064e\u0627 \u064a\u064f\u0648\u062d\u064e\u0649\u0670\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064e\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u062e\u064e\u0628\u0650\u064a\u0631\u0657\u0627",translation:"dan ikutilah apa yang diwahyukan Tuhanmu kepadamu. Sungguh, Allah Mahateliti terhadap apa yang kamu kerjakan"},{id:3,text:"\u0648\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u06e1 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0648\u064e\u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0643\u0650\u064a\u0644\u0657\u0627",translation:"dan bertawakallah kepada Allah. Dan cukuplah Allah sebagai Pemelihara"},{id:4,text:"\u0645\u0651\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u0631\u064e\u062c\u064f\u0644\u0656 \u0645\u0651\u0650\u0646 \u0642\u064e\u0644\u06e1\u0628\u064e\u064a\u06e1\u0646\u0650 \u0641\u0650\u064a \u062c\u064e\u0648\u06e1\u0641\u0650\u0647\u0650\u06e6\u06da \u0648\u064e\u0645\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u064e \u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0651\u064e\u0640\u0670\u0653\u0640\u0654\u0650\u064a \u062a\u064f\u0638\u064e\u0670\u0647\u0650\u0631\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u06e1\u0647\u064f\u0646\u0651\u064e \u0623\u064f\u0645\u0651\u064e\u0647\u064e\u0670\u062a\u0650\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0645\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u064e \u0623\u064e\u062f\u06e1\u0639\u0650\u064a\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u0628\u06e1\u0646\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u06e1\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u06e1 \u0642\u064e\u0648\u06e1\u0644\u064f\u0643\u064f\u0645 \u0628\u0650\u0623\u064e\u0641\u06e1\u0648\u064e\u0670\u0647\u0650\u0643\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064e \u0648\u064e\u0647\u064f\u0648\u064e \u064a\u064e\u0647\u06e1\u062f\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u064e",translation:"(Allah tidak menjadikan bagi seseorang dua hati dalam rongganya; dan Dia tidak menjadikan istri-istrimu yang kamu zihar664) itu sebagai ibumu, dan Dia tidak menjadikan anak angkatmu sebagai anak kandungmu (sendiri). Yang demikian itu hanyalah perkataan di mulutmu saja. Allah mengatakan yang sebenarnya dan Dia menujukkan jalan (yang benar)"},{id:5,text:"\u0671\u062f\u06e1\u0639\u064f\u0648\u0647\u064f\u0645\u06e1 \u0644\u0650\u0623\u0653\u0628\u064e\u0627\u0653\u0626\u0650\u0647\u0650\u0645\u06e1 \u0647\u064f\u0648\u064e \u0623\u064e\u0642\u06e1\u0633\u064e\u0637\u064f \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0641\u064e\u0625\u0650\u0646 \u0644\u0651\u064e\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u06e1 \u0641\u064e\u0625\u0650\u062e\u06e1\u0648\u064e\u0670\u0646\u064f\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u0650 \u0648\u064e\u0645\u064e\u0648\u064e\u0670\u0644\u0650\u064a\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0644\u064e\u064a\u06e1\u0633\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u062c\u064f\u0646\u064e\u0627\u062d\u065e \u0641\u0650\u064a\u0645\u064e\u0627\u0653 \u0623\u064e\u062e\u06e1\u0637\u064e\u0623\u06e1\u062a\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u0645\u0651\u064e\u0627 \u062a\u064e\u0639\u064e\u0645\u0651\u064e\u062f\u064e\u062a\u06e1 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u0657\u0627 \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064b\u0627",translation:"Panggillah mereka (anak angkat itu) dengan (memakai) nama bapak-bapak mereka; itulah yang adil di sisi Allah, dan jika kamu tidak mengetahui bapak mereka, maka (panggillah mereka sebagai) saudara-saudaramu seagama dan maula-maulamu.665) Dan tidak ada dosa atasmu jika kamu khilaf tentang itu, tetapi (yang ada dosanya) apa yang disengaja oleh hatimu. Allah Maha Pengampun, Maha Penyayang"},{id:6,text:"\u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064f \u0623\u064e\u0648\u06e1\u0644\u064e\u0649\u0670 \u0628\u0650\u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u06e1 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u06e1\u06d6 \u0648\u064e\u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u064f\u0647\u064f\u06e5\u0653 \u0623\u064f\u0645\u0651\u064e\u0647\u064e\u0670\u062a\u064f\u0647\u064f\u0645\u06e1\u06d7 \u0648\u064e\u0623\u064f\u0648\u0652\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u062d\u064e\u0627\u0645\u0650 \u0628\u064e\u0639\u06e1\u0636\u064f\u0647\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1\u0644\u064e\u0649\u0670 \u0628\u0650\u0628\u064e\u0639\u06e1\u0636\u0656 \u0641\u0650\u064a \u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0647\u064e\u0670\u062c\u0650\u0631\u0650\u064a\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u062a\u064e\u0641\u06e1\u0639\u064e\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0648\u06e1\u0644\u0650\u064a\u064e\u0627\u0653\u0626\u0650\u0643\u064f\u0645 \u0645\u0651\u064e\u0639\u06e1\u0631\u064f\u0648\u0641\u0657\u0627\u06da \u0643\u064e\u0627\u0646\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0645\u064e\u0633\u06e1\u0637\u064f\u0648\u0631\u0657\u0627",translation:"(Nabi itu lebih utama bagi orang-orang mukmin dibandingkan diri mereka sendiri666) dan istri-istrinya adalah ibu-ibu mereka. Orang-orang yang mempunyai hubungan darah satu sama lain lebih berhak (waris-mewarisi) di dalam Kitab Allah daripada orang-orang mukmin dan orang-orang Muhajirin, kecuali kalau kamu hendak berbuat baik667) kepada saudara-saudaramu (seagama). Demikianlah telah tertulis dalam Kitab (Allah)"},{id:7,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0623\u064e\u062e\u064e\u0630\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650\u0640\u06e7\u0646\u064e \u0645\u0650\u064a\u062b\u064e\u0670\u0642\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0645\u0650\u0646\u0643\u064e \u0648\u064e\u0645\u0650\u0646 \u0646\u0651\u064f\u0648\u062d\u0656 \u0648\u064e\u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064e \u0648\u064e\u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u0639\u0650\u064a\u0633\u064e\u0649 \u0671\u0628\u06e1\u0646\u0650 \u0645\u064e\u0631\u06e1\u064a\u064e\u0645\u064e\u06d6 \u0648\u064e\u0623\u064e\u062e\u064e\u0630\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u0650\u064a\u062b\u064e\u0670\u0642\u064b\u0627 \u063a\u064e\u0644\u0650\u064a\u0638\u0657\u0627",translation:"Dan (ingatlah) ketika Kami mengambil perjanjian dari para nabi dan dari engkau (sendiri), dari Nuh, Ibrahim, Musa dan Isa putra Maryam, dan Kami telah mengambil dari mereka perjanjian yang teguh"},{id:8,text:"\u0644\u0651\u0650\u064a\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e \u0639\u064e\u0646 \u0635\u0650\u062f\u06e1\u0642\u0650\u0647\u0650\u0645\u06e1\u06da \u0648\u064e\u0623\u064e\u0639\u064e\u062f\u0651\u064e \u0644\u0650\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0623\u064e\u0644\u0650\u064a\u0645\u0657\u0627",translation:"(agar Dia menanyakan kepada orang-orang yang benar tentang kebenaran mereka.669) Dia menyediakan azab yang pedih bagi orang-orang kafir"},{id:9,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0671\u0630\u06e1\u0643\u064f\u0631\u064f\u0648\u0627\u0652 \u0646\u0650\u0639\u06e1\u0645\u064e\u0629\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0625\u0650\u0630\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u062a\u06e1\u0643\u064f\u0645\u06e1 \u062c\u064f\u0646\u064f\u0648\u062f\u065e \u0641\u064e\u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0631\u0650\u064a\u062d\u0657\u0627 \u0648\u064e\u062c\u064f\u0646\u064f\u0648\u062f\u0657\u0627 \u0644\u0651\u064e\u0645\u06e1 \u062a\u064e\u0631\u064e\u0648\u06e1\u0647\u064e\u0627\u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0628\u064e\u0635\u0650\u064a\u0631\u064b\u0627",translation:"Wahai orang-orang yang beriman! Ingatlah akan nikmat Allah (yang telah dikaruniakan) kepadamu ketika bala tentara datang kepadamu, lalu Kami kirimkan kepada mereka angin topan dan bala tentara yang tidak dapat terlihat olehmu.670) Allah Maha Melihat apa yang kamu kerjakan"},{id:10,text:"\u0625\u0650\u0630\u06e1 \u062c\u064e\u0627\u0653\u0621\u064f\u0648\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0641\u064e\u0648\u06e1\u0642\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0645\u0650\u0646\u06e1 \u0623\u064e\u0633\u06e1\u0641\u064e\u0644\u064e \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u0648\u064e\u0625\u0650\u0630\u06e1 \u0632\u064e\u0627\u063a\u064e\u062a\u0650 \u0671\u0644\u06e1\u0623\u064e\u0628\u06e1\u0635\u064e\u0670\u0631\u064f \u0648\u064e\u0628\u064e\u0644\u064e\u063a\u064e\u062a\u0650 \u0671\u0644\u06e1\u0642\u064f\u0644\u064f\u0648\u0628\u064f \u0671\u0644\u06e1\u062d\u064e\u0646\u064e\u0627\u062c\u0650\u0631\u064e \u0648\u064e\u062a\u064e\u0638\u064f\u0646\u0651\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u0638\u0651\u064f\u0646\u064f\u0648\u0646\u064e\u0627\u06e0",translation:"(Yaitu) ketika mereka datang kepadamu dari atas dan dari bawahmu, dan ketika penglihatan(mu) terpana dan hatimu menyesak sampai ke tenggorokan671) dan kamu berprasangka yang bukan-bukan terhadap Allah"},{id:11,text:"\u0647\u064f\u0646\u064e\u0627\u0644\u0650\u0643\u064e \u0671\u0628\u06e1\u062a\u064f\u0644\u0650\u064a\u064e \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0648\u064e\u0632\u064f\u0644\u06e1\u0632\u0650\u0644\u064f\u0648\u0627\u0652 \u0632\u0650\u0644\u06e1\u0632\u064e\u0627\u0644\u0657\u0627 \u0634\u064e\u062f\u0650\u064a\u062f\u0657\u0627",translation:"Disitulah diuji orang-orang mukmin dan digoncangkan (hatinya) dengan goncangan yang dahsyat"},{id:12,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0671\u0644\u06e1\u0645\u064f\u0646\u064e\u0670\u0641\u0650\u0642\u064f\u0648\u0646\u064e \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645 \u0645\u0651\u064e\u0631\u064e\u0636\u065e \u0645\u0651\u064e\u0627 \u0648\u064e\u0639\u064e\u062f\u064e\u0646\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0647\u064f\u06e5\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u063a\u064f\u0631\u064f\u0648\u0631\u0657\u0627",translation:"Dan (ingatlah) ketika orang-orang munafik dan orang-orang yang hatinya berpenyakit berkata, \"Yang dijanjikan Allah dan Rasul-Nya kepada kami hanya tipu daya belaka"},{id:13,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e\u062a \u0637\u0651\u064e\u0627\u0653\u0626\u0650\u0641\u064e\u0629\u065e \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u064a\u064e\u0640\u0670\u0653\u0623\u064e\u0647\u06e1\u0644\u064e \u064a\u064e\u062b\u06e1\u0631\u0650\u0628\u064e \u0644\u064e\u0627 \u0645\u064f\u0642\u064e\u0627\u0645\u064e \u0644\u064e\u0643\u064f\u0645\u06e1 \u0641\u064e\u0671\u0631\u06e1\u062c\u0650\u0639\u064f\u0648\u0627\u0652\u06da \u0648\u064e\u064a\u064e\u0633\u06e1\u062a\u064e\u0640\u0654\u06e1\u0630\u0650\u0646\u064f \u0641\u064e\u0631\u0650\u064a\u0642\u065e \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u064f \u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064e \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0625\u0650\u0646\u0651\u064e \u0628\u064f\u064a\u064f\u0648\u062a\u064e\u0646\u064e\u0627 \u0639\u064e\u0648\u06e1\u0631\u064e\u0629\u065e \u0648\u064e\u0645\u064e\u0627 \u0647\u0650\u064a\u064e \u0628\u0650\u0639\u064e\u0648\u06e1\u0631\u064e\u0629\u064d\u06d6 \u0625\u0650\u0646 \u064a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0641\u0650\u0631\u064e\u0627\u0631\u0657\u0627",translation:"Dan (ingatlah) ketika segolongan di antara mereka berkata, \"Wahai penduduk Yasrib (Madinah)! Tidak ada tempat bagimu, maka kembalilah kamu.\" Dan sebagian dari mereka meminta izin kepada Nabi (untuk kembali pulang) dengan berkata, \"Sesungguhnya rumah-rumah kami terbuka (tidak ada penjaga).\" Padahal rumah-rumah itu tidak terbuka, mereka hanyalah hendak lari"},{id:14,text:"\u0648\u064e\u0644\u064e\u0648\u06e1 \u062f\u064f\u062e\u0650\u0644\u064e\u062a\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u0642\u06e1\u0637\u064e\u0627\u0631\u0650\u0647\u064e\u0627 \u062b\u064f\u0645\u0651\u064e \u0633\u064f\u0626\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0641\u0650\u062a\u06e1\u0646\u064e\u0629\u064e \u0644\u064e\u0623\u0653\u062a\u064e\u0648\u06e1\u0647\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0644\u064e\u0628\u0651\u064e\u062b\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u064a\u064e\u0633\u0650\u064a\u0631\u0657\u0627",translation:"Dan kalau (Yasrib) diserang dari segala penjuru, dan mereka diminta agar membuat kekacauan, niscaya mereka mengerjakannya; dan hanya sebentar saja mereka menunggu"},{id:15,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0639\u064e\u0670\u0647\u064e\u062f\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f \u0644\u064e\u0627 \u064a\u064f\u0648\u064e\u0644\u0651\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u062f\u06e1\u0628\u064e\u0670\u0631\u064e\u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0647\u06e1\u062f\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0633\u06e1\u0640\u0654\u064f\u0648\u0644\u0657\u0627",translation:"Dan sungguh, mereka sebelum itu telah berjanji kepada Allah, tidak akan berbalik ke belakang (mundur). Dan perjanjian dengan Allah akan diminta pertanggung jawabannya"},{id:16,text:"\u0642\u064f\u0644 \u0644\u0651\u064e\u0646 \u064a\u064e\u0646\u0641\u064e\u0639\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0641\u0650\u0631\u064e\u0627\u0631\u064f \u0625\u0650\u0646 \u0641\u064e\u0631\u064e\u0631\u06e1\u062a\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u0650 \u0623\u064e\u0648\u0650 \u0671\u0644\u06e1\u0642\u064e\u062a\u06e1\u0644\u0650 \u0648\u064e\u0625\u0650\u0630\u0657\u0627 \u0644\u0651\u064e\u0627 \u062a\u064f\u0645\u064e\u062a\u0651\u064e\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u0657\u0627",translation:"Katakanlah (Muhammad), \"Lari tidaklah berguna bagimu, jika kamu melarikan diri dari kematian atau pembunuhan, dan jika demikian (kamu terhindar dari kematian) kamu hanya akan mengecap kesenangan sebentar saja"},{id:17,text:"\u0642\u064f\u0644\u06e1 \u0645\u064e\u0646 \u0630\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064e\u0639\u06e1\u0635\u0650\u0645\u064f\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0646\u06e1 \u0623\u064e\u0631\u064e\u0627\u062f\u064e \u0628\u0650\u0643\u064f\u0645\u06e1 \u0633\u064f\u0648\u0653\u0621\u064b\u0627 \u0623\u064e\u0648\u06e1 \u0623\u064e\u0631\u064e\u0627\u062f\u064e \u0628\u0650\u0643\u064f\u0645\u06e1 \u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u0657\u06da \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062c\u0650\u062f\u064f\u0648\u0646\u064e \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u0650\u064a\u0651\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0635\u0650\u064a\u0631\u0657\u0627",translation:"Katakanlah, \"Siapakah yang dapat melindungi kamu dari (ketentuan) Allah jika Dia menghendaki bencana atasmu atau menghendaki rahmat untuk dirimu?\" Mereka itu tidak akan mendapatkan pelindung dan penolong selain Allah"},{id:18,text:"\u06de\u0642\u064e\u062f\u06e1 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u0645\u064f\u0639\u064e\u0648\u0651\u0650\u0642\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u0648\u064e\u0671\u0644\u06e1\u0642\u064e\u0627\u0653\u0626\u0650\u0644\u0650\u064a\u0646\u064e \u0644\u0650\u0625\u0650\u062e\u06e1\u0648\u064e\u0670\u0646\u0650\u0647\u0650\u0645\u06e1 \u0647\u064e\u0644\u064f\u0645\u0651\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0646\u064e\u0627\u06d6 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0623\u06e1\u062a\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0628\u064e\u0623\u06e1\u0633\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627",translation:"Sungguh, Allah mengetahui orang-orang yang menghalang-halangi di antara kamu dan orang yang berkata kepada saudara-saudaranya, \"Marilah bersama kami.\" Tetapi mereka datang berperang hanya sebentar"},{id:19,text:"\u0623\u064e\u0634\u0650\u062d\u0651\u064e\u0629\u064b \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1\u06d6 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u06e1\u062e\u064e\u0648\u06e1\u0641\u064f \u0631\u064e\u0623\u064e\u064a\u06e1\u062a\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0646\u0638\u064f\u0631\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u062a\u064e\u062f\u064f\u0648\u0631\u064f \u0623\u064e\u0639\u06e1\u064a\u064f\u0646\u064f\u0647\u064f\u0645\u06e1 \u0643\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u063a\u06e1\u0634\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u0650\u06d6 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0630\u064e\u0647\u064e\u0628\u064e \u0671\u0644\u06e1\u062e\u064e\u0648\u06e1\u0641\u064f \u0633\u064e\u0644\u064e\u0642\u064f\u0648\u0643\u064f\u0645 \u0628\u0650\u0623\u064e\u0644\u06e1\u0633\u0650\u0646\u064e\u0629\u064d \u062d\u0650\u062f\u064e\u0627\u062f\u064d \u0623\u064e\u0634\u0650\u062d\u0651\u064e\u0629\u064b \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u062e\u064e\u064a\u06e1\u0631\u0650\u06da \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0644\u064e\u0645\u06e1 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0627\u0652 \u0641\u064e\u0623\u064e\u062d\u06e1\u0628\u064e\u0637\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0639\u06e1\u0645\u064e\u0670\u0644\u064e\u0647\u064f\u0645\u06e1\u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u0633\u0650\u064a\u0631\u0657\u0627",translation:"mereka kikir terhadapmu. Apabila datang ketakutan (bahaya), kamu lihat mereka itu memandang kepadamu dengan mata yang terbalik-balik seperti orang yang pingsan karena akan mati, dan apabila ketakutan telah hilang, mereka mencaci kamu dengan lidah yang tajam, sedang mereka kikir untuk berbuat kebaikan. Mereka itu tidak beriman, maka Allah menghapus amalnya. Dan yang demikian itu mudah bagi Allah"},{id:20,text:"\u064a\u064e\u062d\u06e1\u0633\u064e\u0628\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u062d\u06e1\u0632\u064e\u0627\u0628\u064e \u0644\u064e\u0645\u06e1 \u064a\u064e\u0630\u06e1\u0647\u064e\u0628\u064f\u0648\u0627\u0652\u06d6 \u0648\u064e\u0625\u0650\u0646 \u064a\u064e\u0623\u06e1\u062a\u0650 \u0671\u0644\u06e1\u0623\u064e\u062d\u06e1\u0632\u064e\u0627\u0628\u064f \u064a\u064e\u0648\u064e\u062f\u0651\u064f\u0648\u0627\u0652 \u0644\u064e\u0648\u06e1 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645 \u0628\u064e\u0627\u062f\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0639\u06e1\u0631\u064e\u0627\u0628\u0650 \u064a\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0648\u0646\u064e \u0639\u064e\u0646\u06e1 \u0623\u064e\u0646\u06e2\u0628\u064e\u0627\u0653\u0626\u0650\u0643\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0644\u064e\u0648\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0643\u064f\u0645 \u0645\u0651\u064e\u0627 \u0642\u064e\u0670\u062a\u064e\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u0657\u0627",translation:"Mereka mengira (bahwa) golongan-golongan (yang bersekutu) itu belum pergi, dan jika golongan-golongan (yang bersekutu) itu datang kembali, niscaya mereka ingin berada di dusun-dusun bersama-sama orang Arab Badui, sambil menanyakan berita tentang kamu. Dan sekiranya mereka berada bersamamu, mereka tidak akan berperang, melainkan sebentar saja"},{id:21,text:"\u0644\u0651\u064e\u0642\u064e\u062f\u06e1 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u0631\u064e\u0633\u064f\u0648\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064f\u0633\u06e1\u0648\u064e\u0629\u064c \u062d\u064e\u0633\u064e\u0646\u064e\u0629\u065e \u0644\u0651\u0650\u0645\u064e\u0646 \u0643\u064e\u0627\u0646\u064e \u064a\u064e\u0631\u06e1\u062c\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e \u0648\u064e\u0630\u064e\u0643\u064e\u0631\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u0657\u0627",translation:"Sungguh, telah ada pada (diri) Rasulullah itu suri teladan yang baik bagimu (yaitu) bagi orang yang mengharap (rahmat) Allah dan (kedatangan) hari Kiamat dan yang banyak mengingat Allah"},{id:22,text:"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0631\u064e\u0621\u064e\u0627 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u062d\u06e1\u0632\u064e\u0627\u0628\u064e \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0647\u064e\u0670\u0630\u064e\u0627 \u0645\u064e\u0627 \u0648\u064e\u0639\u064e\u062f\u064e\u0646\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0647\u064f\u06e5 \u0648\u064e\u0635\u064e\u062f\u064e\u0642\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0647\u064f\u06e5\u06da \u0648\u064e\u0645\u064e\u0627 \u0632\u064e\u0627\u062f\u064e\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0625\u0650\u064a\u0645\u064e\u0670\u0646\u0657\u0627 \u0648\u064e\u062a\u064e\u0633\u06e1\u0644\u0650\u064a\u0645\u0657\u0627",translation:"Dan ketika orang-orang mukmin melihat golongan-golongan (yang bersekutu) itu, mereka berkata, \"Inilah yang dijanjikan Allah dan Rasul-Nya672) kepada kita.\" Dan benarlah Allah dan Rasul-Nya. Dan yang demikian itu menambah keimanan dan keislaman mereka"},{id:23,text:"\u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0631\u0650\u062c\u064e\u0627\u0644\u065e \u0635\u064e\u062f\u064e\u0642\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u0639\u064e\u0670\u0647\u064e\u062f\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u06d6 \u0641\u064e\u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0646 \u0642\u064e\u0636\u064e\u0649\u0670 \u0646\u064e\u062d\u06e1\u0628\u064e\u0647\u064f\u06e5 \u0648\u064e\u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0646 \u064a\u064e\u0646\u062a\u064e\u0638\u0650\u0631\u064f\u06d6 \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u062f\u0651\u064e\u0644\u064f\u0648\u0627\u0652 \u062a\u064e\u0628\u06e1\u062f\u0650\u064a\u0644\u0657\u0627",translation:"Di antara orang-orang mukmin itu ada orang-orang yang menepati apa yang telah mereka janjikan kepada Allah. Dan di antara mereka ada yang gugur, dan di antara mereka ada (pula) yang menunggu-nunggu673) dan mereka sedikit pun tidak mengubah (janjinya)"},{id:24,text:"\u0644\u0651\u0650\u064a\u064e\u062c\u06e1\u0632\u0650\u064a\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e \u0628\u0650\u0635\u0650\u062f\u06e1\u0642\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064e \u0671\u0644\u06e1\u0645\u064f\u0646\u064e\u0670\u0641\u0650\u0642\u0650\u064a\u0646\u064e \u0625\u0650\u0646 \u0634\u064e\u0627\u0653\u0621\u064e \u0623\u064e\u0648\u06e1 \u064a\u064e\u062a\u064f\u0648\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u0657\u0627 \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0657\u0627",translation:"agar Allah memberikan balasan kepada orang-orang yang benar itu karena kebenarannya, dan mengazab orang munafik jika Dia kehendaki, atau menerima tobat mereka. Sungguh, Allah Maha Pengampun, Maha Penyayang"},{id:25,text:"\u0648\u064e\u0631\u064e\u062f\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u063a\u064e\u064a\u06e1\u0638\u0650\u0647\u0650\u0645\u06e1 \u0644\u064e\u0645\u06e1 \u064a\u064e\u0646\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u062e\u064e\u064a\u06e1\u0631\u0657\u0627\u06da \u0648\u064e\u0643\u064e\u0641\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0671\u0644\u06e1\u0642\u0650\u062a\u064e\u0627\u0644\u064e\u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0642\u064e\u0648\u0650\u064a\u0651\u064b\u0627 \u0639\u064e\u0632\u0650\u064a\u0632\u0657\u0627",translation:"Dan Allah menghalau orang-orang kafir itu yang mereka penuh memendam kejengkelan, karena mereka (juga) tidak memperoleh keuntungan apa pun. Cukuplah Allah (yang menolong) menghindarkan orang-orang mukmin dalam peperangan.674) Dan Allah Mahakuat, Mahaperkasa"},{id:26,text:"\u0648\u064e\u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0670\u0647\u064e\u0631\u064f\u0648\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u0647\u06e1\u0644\u0650 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0645\u0650\u0646 \u0635\u064e\u064a\u064e\u0627\u0635\u0650\u064a\u0647\u0650\u0645\u06e1 \u0648\u064e\u0642\u064e\u0630\u064e\u0641\u064e \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u064f \u0671\u0644\u0631\u0651\u064f\u0639\u06e1\u0628\u064e \u0641\u064e\u0631\u0650\u064a\u0642\u0657\u0627 \u062a\u064e\u0642\u06e1\u062a\u064f\u0644\u064f\u0648\u0646\u064e \u0648\u064e\u062a\u064e\u0623\u06e1\u0633\u0650\u0631\u064f\u0648\u0646\u064e \u0641\u064e\u0631\u0650\u064a\u0642\u0657\u0627",translation:"Dan Dia menurunkan orang-orang Ahli Kitab (Bani Qurai\u1e93ah) yang membantu mereka (golongan-golongan yang bersekutu) dari benteng-benteng mereka, dan Dia memasukkan rasa takut ke dalam hati mereka. Sebagian mereka kamu bunuh dan sebagian yang lain kamu tawan"},{id:27,text:"\u0648\u064e\u0623\u064e\u0648\u06e1\u0631\u064e\u062b\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u0631\u06e1\u0636\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u062f\u0650\u064a\u064e\u0670\u0631\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0631\u06e1\u0636\u0657\u0627 \u0644\u0651\u064e\u0645\u06e1 \u062a\u064e\u0637\u064e\u0640\u0654\u064f\u0648\u0647\u064e\u0627\u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0642\u064e\u062f\u0650\u064a\u0631\u0657\u0627",translation:"Dan Dia mewariskan kepadamu tanah-tanah, rumah-rumah dan harta benda mereka, dan (begitu pula) tanah yang belum kamu injak.676) Dan Allah Mahakuasa terhadap segala sesuatu"},{id:28,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064f \u0642\u064f\u0644 \u0644\u0651\u0650\u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u0650\u0643\u064e \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0646\u0651\u064e \u062a\u064f\u0631\u0650\u062f\u06e1\u0646\u064e \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u064e \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0648\u064e\u0632\u0650\u064a\u0646\u064e\u062a\u064e\u0647\u064e\u0627 \u0641\u064e\u062a\u064e\u0639\u064e\u0627\u0644\u064e\u064a\u06e1\u0646\u064e \u0623\u064f\u0645\u064e\u062a\u0651\u0650\u0639\u06e1\u0643\u064f\u0646\u0651\u064e \u0648\u064e\u0623\u064f\u0633\u064e\u0631\u0651\u0650\u062d\u06e1\u0643\u064f\u0646\u0651\u064e \u0633\u064e\u0631\u064e\u0627\u062d\u0657\u0627 \u062c\u064e\u0645\u0650\u064a\u0644\u0657\u0627",translation:"Wahai Nabi! Katakanlah kepada istri-istrimu, \"Jika kamu menginginkan kehidupan di dunia dan perhiasannya, maka kemarilah agar kuberikan kepadamu mut'ah dan aku ceraikan kamu dengan cara yang baik"},{id:29,text:"\u0648\u064e\u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0646\u0651\u064e \u062a\u064f\u0631\u0650\u062f\u06e1\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f\u06e5 \u0648\u064e\u0671\u0644\u062f\u0651\u064e\u0627\u0631\u064e \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0623\u064e\u0639\u064e\u062f\u0651\u064e \u0644\u0650\u0644\u06e1\u0645\u064f\u062d\u06e1\u0633\u0650\u0646\u064e\u0670\u062a\u0650 \u0645\u0650\u0646\u0643\u064f\u0646\u0651\u064e \u0623\u064e\u062c\u06e1\u0631\u064b\u0627 \u0639\u064e\u0638\u0650\u064a\u0645\u0657\u0627",translation:"Dan jika kamu menginginkan Allah dan Rasul-Nya dan negeri akhirat, maka sesungguhnya Allah menyediakan pahala yang besar bagi siapa yang berbuat baik diantara kamu"},{id:30,text:"\u064a\u064e\u0670\u0646\u0650\u0633\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650 \u0645\u064e\u0646 \u064a\u064e\u0623\u06e1\u062a\u0650 \u0645\u0650\u0646\u0643\u064f\u0646\u0651\u064e \u0628\u0650\u0641\u064e\u0670\u062d\u0650\u0634\u064e\u0629\u0656 \u0645\u0651\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0629\u0656 \u064a\u064f\u0636\u064e\u0670\u0639\u064e\u0641\u06e1 \u0644\u064e\u0647\u064e\u0627 \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0636\u0650\u0639\u06e1\u0641\u064e\u064a\u06e1\u0646\u0650\u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u0633\u0650\u064a\u0631\u0657\u0627",translation:"Wahai istri-istri Nabi! Barangsiapa di antara kamu yang mengerjakan perbuatan keji yang nyata, niscaya azabnya akan dilipatgandakan dua kali lipat kepadanya. Dan yang demikian itu, mudah bagi Allah"},{id:31,text:"\u06de\u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0642\u06e1\u0646\u064f\u062a\u06e1 \u0645\u0650\u0646\u0643\u064f\u0646\u0651\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650\u06e6 \u0648\u064e\u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u06e1 \u0635\u064e\u0670\u0644\u0650\u062d\u0657\u0627 \u0646\u0651\u064f\u0624\u06e1\u062a\u0650\u0647\u064e\u0627\u0653 \u0623\u064e\u062c\u06e1\u0631\u064e\u0647\u064e\u0627 \u0645\u064e\u0631\u0651\u064e\u062a\u064e\u064a\u06e1\u0646\u0650 \u0648\u064e\u0623\u064e\u0639\u06e1\u062a\u064e\u062f\u06e1\u0646\u064e\u0627 \u0644\u064e\u0647\u064e\u0627 \u0631\u0650\u0632\u06e1\u0642\u0657\u0627 \u0643\u064e\u0631\u0650\u064a\u0645\u0657\u0627",translation:"Dan barangsiapa di antara kamu (istri-istri Nabi) tetap taat kepada Allah dan Rasul-Nya dan mengerjakan kebajikan, niscaya Kami berikan pahala kepadanya dua kali lipat dan Kami sediakan rezeki yang mulia baginya"},{id:32,text:"\u064a\u064e\u0670\u0646\u0650\u0633\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650 \u0644\u064e\u0633\u06e1\u062a\u064f\u0646\u0651\u064e \u0643\u064e\u0623\u064e\u062d\u064e\u062f\u0656 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0653\u0621\u0650 \u0625\u0650\u0646\u0650 \u0671\u062a\u0651\u064e\u0642\u064e\u064a\u06e1\u062a\u064f\u0646\u0651\u064e\u06da \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062e\u06e1\u0636\u064e\u0639\u06e1\u0646\u064e \u0628\u0650\u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0644\u0650 \u0641\u064e\u064a\u064e\u0637\u06e1\u0645\u064e\u0639\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0641\u0650\u064a \u0642\u064e\u0644\u06e1\u0628\u0650\u0647\u0650\u06e6 \u0645\u064e\u0631\u064e\u0636\u065e \u0648\u064e\u0642\u064f\u0644\u06e1\u0646\u064e \u0642\u064e\u0648\u06e1\u0644\u0657\u0627 \u0645\u0651\u064e\u0639\u06e1\u0631\u064f\u0648\u0641\u0657\u0627",translation:"Wahai istri-istri Nabi! Kamu tidak seperti perempuan-perempuan yang lain, jika kamu bertakwa. Maka janganlah kamu tunduk (melemah lembutkan suara)677) dalam berbicara sehingga bangkit nafsu orang yang ada penyakit dalam hatinya,678) dan ucapkanlah perkataan yang baik"},{id:33,text:"\u0648\u064e\u0642\u064e\u0631\u06e1\u0646\u064e \u0641\u0650\u064a \u0628\u064f\u064a\u064f\u0648\u062a\u0650\u0643\u064f\u0646\u0651\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0628\u064e\u0631\u0651\u064e\u062c\u06e1\u0646\u064e \u062a\u064e\u0628\u064e\u0631\u0651\u064f\u062c\u064e \u0671\u0644\u06e1\u062c\u064e\u0670\u0647\u0650\u0644\u0650\u064a\u0651\u064e\u0629\u0650 \u0671\u0644\u06e1\u0623\u064f\u0648\u0644\u064e\u0649\u0670\u06d6 \u0648\u064e\u0623\u064e\u0642\u0650\u0645\u06e1\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u0621\u064e\u0627\u062a\u0650\u064a\u0646\u064e \u0671\u0644\u0632\u0651\u064e\u0643\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u0623\u064e\u0637\u0650\u0639\u06e1\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f\u06e5\u0653\u06da \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u064a\u064f\u0630\u06e1\u0647\u0650\u0628\u064e \u0639\u064e\u0646\u0643\u064f\u0645\u064f \u0671\u0644\u0631\u0651\u0650\u062c\u06e1\u0633\u064e \u0623\u064e\u0647\u06e1\u0644\u064e \u0671\u0644\u06e1\u0628\u064e\u064a\u06e1\u062a\u0650 \u0648\u064e\u064a\u064f\u0637\u064e\u0647\u0651\u0650\u0631\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u0637\u06e1\u0647\u0650\u064a\u0631\u0657\u0627",translation:"(Dan hendaklah kamu tetap di rumahmu679) dan janganlah kamu berhias dan (bertingkah laku) seperti orang-orang jahiliah dahulu,680) dan laksanakanlah salat, tunaikanlah zakat dan taatilah Allah dan Rasul-Nya. Sesungguhnya Allah bermaksud hendak menghilangkan dosa dari kamu, wahai ahlulbait681) dan membersihkan kamu sebersih-bersihnya"},{id:34,text:"\u0648\u064e\u0671\u0630\u06e1\u0643\u064f\u0631\u06e1\u0646\u064e \u0645\u064e\u0627 \u064a\u064f\u062a\u06e1\u0644\u064e\u0649\u0670 \u0641\u0650\u064a \u0628\u064f\u064a\u064f\u0648\u062a\u0650\u0643\u064f\u0646\u0651\u064e \u0645\u0650\u0646\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0671\u0644\u06e1\u062d\u0650\u0643\u06e1\u0645\u064e\u0629\u0650\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0637\u0650\u064a\u0641\u064b\u0627 \u062e\u064e\u0628\u0650\u064a\u0631\u064b\u0627",translation:"Dan ingatlah apa yang dibacakan di rumahmu dari ayat-ayat Allah dan hikmah (sunah Nabimu). Sungguh, Allah Mahalembut, Maha Mengetahui"},{id:35,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0645\u064f\u0633\u06e1\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0633\u06e1\u0644\u0650\u0645\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0642\u064e\u0670\u0646\u0650\u062a\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u0642\u064e\u0670\u0646\u0650\u062a\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u0635\u0651\u064e\u0640\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u0635\u0651\u064e\u0640\u0670\u062f\u0650\u0642\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0628\u0650\u0631\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0628\u0650\u0631\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u062e\u064e\u0670\u0634\u0650\u0639\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u062e\u064e\u0670\u0634\u0650\u0639\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u062a\u064e\u0635\u064e\u062f\u0651\u0650\u0642\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u062a\u064e\u0635\u064e\u062f\u0651\u0650\u0642\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0653\u0626\u0650\u0645\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0653\u0626\u0650\u0645\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u062d\u064e\u0670\u0641\u0650\u0638\u0650\u064a\u0646\u064e \u0641\u064f\u0631\u064f\u0648\u062c\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0671\u0644\u06e1\u062d\u064e\u0670\u0641\u0650\u0638\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u0630\u0651\u064e\u0640\u0670\u0643\u0650\u0631\u0650\u064a\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u0657\u0627 \u0648\u064e\u0671\u0644\u0630\u0651\u064e\u0640\u0670\u0643\u0650\u0631\u064e\u0670\u062a\u0650 \u0623\u064e\u0639\u064e\u062f\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u063a\u06e1\u0641\u0650\u0631\u064e\u0629\u0657 \u0648\u064e\u0623\u064e\u062c\u06e1\u0631\u064b\u0627 \u0639\u064e\u0638\u0650\u064a\u0645\u0657\u0627",translation:"Sungguh, laki-laki dan perempuan muslim, laki-laki dan perempuan mukmin, laki-laki dan perempuan yang tetap dalam ketaatannya, laki-laki dan perempuan yang benar, laki-laki dan perempuan yang sabar, laki-laki dan perempuan yang khusyuk, laki-laki dan perempuan yang bersedekah, laki-laki dan perempuan yang berpuasa, laki-laki dan perempuan yang memelihara kehormatannya, laki-laki dan perempuan yang banyak menyebut (nama) Allah, Allah telah menyediakan untuk mereka ampunan dan pahala yang besar"},{id:36,text:"\u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0656 \u0648\u064e\u0644\u064e\u0627 \u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064e\u0629\u064d \u0625\u0650\u0630\u064e\u0627 \u0642\u064e\u0636\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0647\u064f\u06e5\u0653 \u0623\u064e\u0645\u06e1\u0631\u064b\u0627 \u0623\u064e\u0646 \u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u062e\u0650\u064a\u064e\u0631\u064e\u0629\u064f \u0645\u0650\u0646\u06e1 \u0623\u064e\u0645\u06e1\u0631\u0650\u0647\u0650\u0645\u06e1\u06d7 \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0639\u06e1\u0635\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f\u06e5 \u0641\u064e\u0642\u064e\u062f\u06e1 \u0636\u064e\u0644\u0651\u064e \u0636\u064e\u0644\u064e\u0670\u0644\u0657\u0627 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u0657\u0627",translation:"Dan tidaklah pantas bagi laki-laki yang mukmin dan perempuan yang mukmin, apabila Allah dan Rasul-Nya telah menetapkan suatu ketetapan, akan ada pilihan (yang lain) bagi mereka tentang urusan mereka. Dan barangsiapa mendurhakai Allah dan Rasul-Nya, maka sungguh, dia telah tersesat, dengan kesesatan yang nyata"},{id:37,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u062a\u064e\u0642\u064f\u0648\u0644\u064f \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064e\u0646\u06e1\u0639\u064e\u0645\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0648\u064e\u0623\u064e\u0646\u06e1\u0639\u064e\u0645\u06e1\u062a\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0623\u064e\u0645\u06e1\u0633\u0650\u0643\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0632\u064e\u0648\u06e1\u062c\u064e\u0643\u064e \u0648\u064e\u0671\u062a\u0651\u064e\u0642\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u062a\u064f\u062e\u06e1\u0641\u0650\u064a \u0641\u0650\u064a \u0646\u064e\u0641\u06e1\u0633\u0650\u0643\u064e \u0645\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064f\u0628\u06e1\u062f\u0650\u064a\u0647\u0650 \u0648\u064e\u062a\u064e\u062e\u06e1\u0634\u064e\u0649 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u062d\u064e\u0642\u0651\u064f \u0623\u064e\u0646 \u062a\u064e\u062e\u06e1\u0634\u064e\u0649\u0670\u0647\u064f\u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0642\u064e\u0636\u064e\u0649\u0670 \u0632\u064e\u064a\u06e1\u062f\u065e \u0645\u0651\u0650\u0646\u06e1\u0647\u064e\u0627 \u0648\u064e\u0637\u064e\u0631\u0657\u0627 \u0632\u064e\u0648\u0651\u064e\u062c\u06e1\u0646\u064e\u0670\u0643\u064e\u0647\u064e\u0627 \u0644\u0650\u0643\u064e\u064a\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u062d\u064e\u0631\u064e\u062c\u065e \u0641\u0650\u064a\u0653 \u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u0650 \u0623\u064e\u062f\u06e1\u0639\u0650\u064a\u064e\u0627\u0653\u0626\u0650\u0647\u0650\u0645\u06e1 \u0625\u0650\u0630\u064e\u0627 \u0642\u064e\u0636\u064e\u0648\u06e1\u0627\u0652 \u0645\u0650\u0646\u06e1\u0647\u064f\u0646\u0651\u064e \u0648\u064e\u0637\u064e\u0631\u0657\u0627\u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0623\u064e\u0645\u06e1\u0631\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0641\u06e1\u0639\u064f\u0648\u0644\u0657\u0627",translation:"Dan (ingatlah), ketika engkau (Muhammad) berkata kepada orang yang telah diberi nikmat oleh Allah dan engkau (juga) telah memberi nikmat kepadanya, \"Pertahankanlah terus istrimu dan bertakwalah kepada Allah,\" sedang engkau menyembunyikan di dalam hatimu apa yang akan ditampakkan oleh Allah, dan engkau takut kepada manusia, padahal Allah lebih berhak engkau takuti. Maka ketika Zaid telah mengakhiri keperluan terhadap istrinya (menceraikannya), Kami nikahkan engkau dengan dia (Zainab)682) agar tidak ada keberatan bagi orang mukmin untuk (menikahi) istri-istri anak-anak angkat mereka, apabila anak-anak angkat itu telah menyelesaikan keperluannya terhadap istrinya. Dan ketetapan Allah itu pasti terjadi"},{id:38,text:"\u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650 \u0645\u0650\u0646\u06e1 \u062d\u064e\u0631\u064e\u062c\u0656 \u0641\u0650\u064a\u0645\u064e\u0627 \u0641\u064e\u0631\u064e\u0636\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0647\u064f\u06e5\u06d6 \u0633\u064f\u0646\u0651\u064e\u0629\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u0650\u064a \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062e\u064e\u0644\u064e\u0648\u06e1\u0627\u0652 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f\u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0623\u064e\u0645\u06e1\u0631\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0642\u064e\u062f\u064e\u0631\u0657\u0627 \u0645\u0651\u064e\u0642\u06e1\u062f\u064f\u0648\u0631\u064b\u0627",translation:"Tidak ada keberatan apa pun pada Nabi tentang apa yang telah ditetapkan Allah baginya. (Allah telah menetapkan yang demikian) sebagai sunah Allah pada nabi-nabi yang telah terdahulu. Dan ketetapan Allah itu suatu ketetapan yang pasti berlaku"},{id:39,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0628\u064e\u0644\u0651\u0650\u063a\u064f\u0648\u0646\u064e \u0631\u0650\u0633\u064e\u0670\u0644\u064e\u0670\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u064a\u064e\u062e\u06e1\u0634\u064e\u0648\u06e1\u0646\u064e\u0647\u064f\u06e5 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062e\u06e1\u0634\u064e\u0648\u06e1\u0646\u064e \u0623\u064e\u062d\u064e\u062f\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064e\u06d7 \u0648\u064e\u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u064e\u0633\u0650\u064a\u0628\u0657\u0627",translation:"(yaitu) orang-orang yang menyampaikan risalah-risalah Allah,683) mereka takut kepada-Nya dan tidak merasa takut kepada siapa pun selain kepada Allah. Dan cukuplah Allah sebagai pembuat perhitungan"},{id:40,text:"\u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0645\u064f\u062d\u064e\u0645\u0651\u064e\u062f\u064c \u0623\u064e\u0628\u064e\u0627\u0653 \u0623\u064e\u062d\u064e\u062f\u0656 \u0645\u0651\u0650\u0646 \u0631\u0651\u0650\u062c\u064e\u0627\u0644\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u062e\u064e\u0627\u062a\u064e\u0645\u064e \u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650\u0640\u06e7\u0646\u064e\u06d7 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u0657\u0627",translation:"(Muhammad itu bukanlah bapak dari seseorang di antara kamu,684) tetapi dia adalah utusan Allah dan penutup para nabi. Dan Allah Maha Mengetahui segala sesuatu"},{id:41,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0671\u0630\u06e1\u0643\u064f\u0631\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0630\u0650\u0643\u06e1\u0631\u0657\u0627 \u0643\u064e\u062b\u0650\u064a\u0631\u0657\u0627",translation:"Wahai orang-orang yang beriman! Ingatlah kepada Allah, dengan mengingat (nama-Nya) sebanyak-banyaknya"},{id:42,text:"\u0648\u064e\u0633\u064e\u0628\u0651\u0650\u062d\u064f\u0648\u0647\u064f \u0628\u064f\u0643\u06e1\u0631\u064e\u0629\u0657 \u0648\u064e\u0623\u064e\u0635\u0650\u064a\u0644\u064b\u0627",translation:"dan bertasbihlah kepada-Nya pada waktu pagi dan petang"},{id:43,text:"\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u0635\u064e\u0644\u0651\u0650\u064a \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0648\u064e\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u062a\u064f\u0647\u064f\u06e5 \u0644\u0650\u064a\u064f\u062e\u06e1\u0631\u0650\u062c\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0638\u0651\u064f\u0644\u064f\u0645\u064e\u0670\u062a\u0650 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0646\u0651\u064f\u0648\u0631\u0650\u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0628\u0650\u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0631\u064e\u062d\u0650\u064a\u0645\u0657\u0627",translation:"Dialah yang memberi rahmat kepadamu dan para malaikat-Nya (memohonkan ampunan untukmu), agar Dia mengeluarkan kamu dari kegelapan kepada cahaya (yang terang). Dan Dia Maha Penyayang kepada orang-orang yang beriman"},{id:44,text:"\u062a\u064e\u062d\u0650\u064a\u0651\u064e\u062a\u064f\u0647\u064f\u0645\u06e1 \u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064e\u0644\u06e1\u0642\u064e\u0648\u06e1\u0646\u064e\u0647\u064f\u06e5 \u0633\u064e\u0644\u064e\u0670\u0645\u065e\u06da \u0648\u064e\u0623\u064e\u0639\u064e\u062f\u0651\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u062c\u06e1\u0631\u0657\u0627 \u0643\u064e\u0631\u0650\u064a\u0645\u0657\u0627",translation:"Penghormatan mereka (orang-orang mukmin itu) ketika mereka menemui-Nya ialah, \"Salam,\"685) dan Dia menyediakan pahala yang mulia bagi mereka"},{id:45,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064f \u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0670\u0643\u064e \u0634\u064e\u0670\u0647\u0650\u062f\u0657\u0627 \u0648\u064e\u0645\u064f\u0628\u064e\u0634\u0651\u0650\u0631\u0657\u0627 \u0648\u064e\u0646\u064e\u0630\u0650\u064a\u0631\u0657\u0627",translation:"Wahai Nabi! Sesungguhnya Kami mengutusmu untuk menjadi saksi, pembawa kabar gembira dan pemberi peringatan"},{id:46,text:"\u0648\u064e\u062f\u064e\u0627\u0639\u0650\u064a\u064b\u0627 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u0650\u0625\u0650\u0630\u06e1\u0646\u0650\u0647\u0650\u06e6 \u0648\u064e\u0633\u0650\u0631\u064e\u0627\u062c\u0657\u0627 \u0645\u0651\u064f\u0646\u0650\u064a\u0631\u0657\u0627",translation:"dan untuk menjadi penyeru kepada (agama) Allah dengan izin-Nya dan sebagai cahaya yang menerangi"},{id:47,text:"\u0648\u064e\u0628\u064e\u0634\u0651\u0650\u0631\u0650 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0636\u06e1\u0644\u0657\u0627 \u0643\u064e\u0628\u0650\u064a\u0631\u0657\u0627",translation:"Dan sampaikanlah kabar gembira kepada orang-orang mukmin bahwa sesungguhnya bagi mereka karunia yang besar dari Allah"},{id:48,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0637\u0650\u0639\u0650 \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0646\u064e\u0670\u0641\u0650\u0642\u0650\u064a\u0646\u064e \u0648\u064e\u062f\u064e\u0639\u06e1 \u0623\u064e\u0630\u064e\u0649\u0670\u0647\u064f\u0645\u06e1 \u0648\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u06e1 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0648\u064e\u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0643\u0650\u064a\u0644\u0657\u0627",translation:"Dan janganlah engkau (Muhammad) menuruti orang-orang kafir dan orang-orang munafik itu, janganlah engkau hiraukan gangguan mereka dan bertawakallah kepada Allah. Dan cukuplah Allah sebagai pelindung"},{id:49,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0630\u064e\u0627 \u0646\u064e\u0643\u064e\u062d\u06e1\u062a\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064e\u0670\u062a\u0650 \u062b\u064f\u0645\u0651\u064e \u0637\u064e\u0644\u0651\u064e\u0642\u06e1\u062a\u064f\u0645\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650 \u0623\u064e\u0646 \u062a\u064e\u0645\u064e\u0633\u0651\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0641\u064e\u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0646\u0651\u064e \u0645\u0650\u0646\u06e1 \u0639\u0650\u062f\u0651\u064e\u0629\u0656 \u062a\u064e\u0639\u06e1\u062a\u064e\u062f\u0651\u064f\u0648\u0646\u064e\u0647\u064e\u0627\u06d6 \u0641\u064e\u0645\u064e\u062a\u0651\u0650\u0639\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0648\u064e\u0633\u064e\u0631\u0651\u0650\u062d\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0633\u064e\u0631\u064e\u0627\u062d\u0657\u0627 \u062c\u064e\u0645\u0650\u064a\u0644\u0657\u0627",translation:"Wahai orang-orang yang beriman! Apabila kamu menikahi perempuan-perempuan mukmin, kemudian kamu ceraikan mereka sebelum kamu mencampurinya maka tidak ada masa idah atas mereka yang perlu kamu perhitungkan. Namun berilah mereka mut'ah dan lepaskanlah mereka itu dengan cara yang sebaik-baiknya"},{id:50,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064f \u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u062d\u06e1\u0644\u064e\u0644\u06e1\u0646\u064e\u0627 \u0644\u064e\u0643\u064e \u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u064e\u0643\u064e \u0671\u0644\u0651\u064e\u0640\u0670\u062a\u0650\u064a\u0653 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u062a\u064e \u0623\u064f\u062c\u064f\u0648\u0631\u064e\u0647\u064f\u0646\u0651\u064e \u0648\u064e\u0645\u064e\u0627 \u0645\u064e\u0644\u064e\u0643\u064e\u062a\u06e1 \u064a\u064e\u0645\u0650\u064a\u0646\u064f\u0643\u064e \u0645\u0650\u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u0641\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0648\u064e\u0628\u064e\u0646\u064e\u0627\u062a\u0650 \u0639\u064e\u0645\u0651\u0650\u0643\u064e \u0648\u064e\u0628\u064e\u0646\u064e\u0627\u062a\u0650 \u0639\u064e\u0645\u0651\u064e\u0640\u0670\u062a\u0650\u0643\u064e \u0648\u064e\u0628\u064e\u0646\u064e\u0627\u062a\u0650 \u062e\u064e\u0627\u0644\u0650\u0643\u064e \u0648\u064e\u0628\u064e\u0646\u064e\u0627\u062a\u0650 \u062e\u064e\u0670\u0644\u064e\u0670\u062a\u0650\u0643\u064e \u0671\u0644\u0651\u064e\u0640\u0670\u062a\u0650\u064a \u0647\u064e\u0627\u062c\u064e\u0631\u06e1\u0646\u064e \u0645\u064e\u0639\u064e\u0643\u064e \u0648\u064e\u0671\u0645\u06e1\u0631\u064e\u0623\u064e\u0629\u0657 \u0645\u0651\u064f\u0624\u06e1\u0645\u0650\u0646\u064e\u0629\u064b \u0625\u0650\u0646 \u0648\u064e\u0647\u064e\u0628\u064e\u062a\u06e1 \u0646\u064e\u0641\u06e1\u0633\u064e\u0647\u064e\u0627 \u0644\u0650\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650 \u0625\u0650\u0646\u06e1 \u0623\u064e\u0631\u064e\u0627\u062f\u064e \u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064f \u0623\u064e\u0646 \u064a\u064e\u0633\u06e1\u062a\u064e\u0646\u0643\u0650\u062d\u064e\u0647\u064e\u0627 \u062e\u064e\u0627\u0644\u0650\u0635\u064e\u0629\u0657 \u0644\u0651\u064e\u0643\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e\u06d7 \u0642\u064e\u062f\u06e1 \u0639\u064e\u0644\u0650\u0645\u06e1\u0646\u064e\u0627 \u0645\u064e\u0627 \u0641\u064e\u0631\u064e\u0636\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0641\u0650\u064a\u0653 \u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627 \u0645\u064e\u0644\u064e\u0643\u064e\u062a\u06e1 \u0623\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u064f\u0647\u064f\u0645\u06e1 \u0644\u0650\u0643\u064e\u064a\u06e1\u0644\u064e\u0627 \u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u062d\u064e\u0631\u064e\u062c\u065e\u06d7 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u0657\u0627 \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0657\u0627",translation:"Wahai Nabi! Sesungguhnya Kami telah menghalalkan bagimu istri-istrimu yang telah engkau berikan maskawinnya dan hamba sahaya yang engkau miliki, termasuk apa yang engkau peroleh dalam peperangan yang dikaruniakan Allah untukmu, dan (demikian pula) anak-anak perempuan dari saudara laki-laki bapakmu, anak-anak perempuan dari saudara perempuan bapakmu, anak-anak perempuan dari saudara laki-laki ibumu dan anak-anak perempuan dari saudara perempuan ibumu yang turut hijrah bersamamu, dan perempuan mukmin yang menyerahkan dirinya kepada Nabi kalau Nabi ingin menikahinya, sebagai kekhususan bagimu, bukan untuk semua orang mukmin. Kami telah mengetahui apa yang Kami wajibkan kepada mereka tentang istri-istri mereka dan hamba sahaya yang mereka miliki agar tidak menjadi kesempitan bagimu. Dan Allah Maha Pengampun, Maha Penyayang"},{id:51,text:"\u06de\u062a\u064f\u0631\u06e1\u062c\u0650\u064a \u0645\u064e\u0646 \u062a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0645\u0650\u0646\u06e1\u0647\u064f\u0646\u0651\u064e \u0648\u064e\u062a\u064f\u0640\u0654\u06e1\u0648\u0650\u064a\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0645\u064e\u0646 \u062a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06d6 \u0648\u064e\u0645\u064e\u0646\u0650 \u0671\u0628\u06e1\u062a\u064e\u063a\u064e\u064a\u06e1\u062a\u064e \u0645\u0650\u0645\u0651\u064e\u0646\u06e1 \u0639\u064e\u0632\u064e\u0644\u06e1\u062a\u064e \u0641\u064e\u0644\u064e\u0627 \u062c\u064f\u0646\u064e\u0627\u062d\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0623\u064e\u062f\u06e1\u0646\u064e\u0649\u0670\u0653 \u0623\u064e\u0646 \u062a\u064e\u0642\u064e\u0631\u0651\u064e \u0623\u064e\u0639\u06e1\u064a\u064f\u0646\u064f\u0647\u064f\u0646\u0651\u064e \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062d\u06e1\u0632\u064e\u0646\u0651\u064e \u0648\u064e\u064a\u064e\u0631\u06e1\u0636\u064e\u064a\u06e1\u0646\u064e \u0628\u0650\u0645\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u062a\u064e\u0647\u064f\u0646\u0651\u064e \u0643\u064f\u0644\u0651\u064f\u0647\u064f\u0646\u0651\u064e\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064b\u0627 \u062d\u064e\u0644\u0650\u064a\u0645\u0657\u0627",translation:"Engkau boleh menangguhkan (menggauli) siapa yang engkau kehendaki di antara mereka (para istrimu) dan (boleh pula) menggauli siapa (di antara mereka) yang engkau kehendaki. Dan siapa yang engkau ingini untuk menggaulinya kembali dari istri-istrimu yang telah engkau sisihkan, maka tidak ada dosa bagimu. Yang demikian itu lebih dekat untuk ketenangan hati mereka, dan mereka tidak merasa sedih, dan mereka rela dengan apa yang telah engkau berikan kepada mereka semuanya. Dan Allah mengetahui apa yang (tersimpan) dalam hatimu. Dan Allah Maha Mengetahui, Maha Penyantun"},{id:52,text:"\u0644\u0651\u064e\u0627 \u064a\u064e\u062d\u0650\u0644\u0651\u064f \u0644\u064e\u0643\u064e \u0671\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0653\u0621\u064f \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u064f \u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064e\u0646 \u062a\u064e\u0628\u064e\u062f\u0651\u064e\u0644\u064e \u0628\u0650\u0647\u0650\u0646\u0651\u064e \u0645\u0650\u0646\u06e1 \u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u0656 \u0648\u064e\u0644\u064e\u0648\u06e1 \u0623\u064e\u0639\u06e1\u062c\u064e\u0628\u064e\u0643\u064e \u062d\u064f\u0633\u06e1\u0646\u064f\u0647\u064f\u0646\u0651\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0645\u064e\u0644\u064e\u0643\u064e\u062a\u06e1 \u064a\u064e\u0645\u0650\u064a\u0646\u064f\u0643\u064e\u06d7 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0631\u0651\u064e\u0642\u0650\u064a\u0628\u0657\u0627",translation:"Tidak halal bagimu (Muhammad) menikahi perempuan-perempuan (lain) setelah itu, dan tidak boleh (pula) mengganti mereka dengan istri-istri (yang lain), meskipun kecantikannya menarik hatimu kecuali perempuan-perempuan (hamba sahaya) yang engkau miliki. Dan Allah Maha Mengawasi segala sesuatu"},{id:53,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u062a\u064e\u062f\u06e1\u062e\u064f\u0644\u064f\u0648\u0627\u0652 \u0628\u064f\u064a\u064f\u0648\u062a\u064e \u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u064a\u064f\u0624\u06e1\u0630\u064e\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649\u0670 \u0637\u064e\u0639\u064e\u0627\u0645\u064d \u063a\u064e\u064a\u06e1\u0631\u064e \u0646\u064e\u0670\u0638\u0650\u0631\u0650\u064a\u0646\u064e \u0625\u0650\u0646\u064e\u0649\u0670\u0647\u064f \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u06e1 \u0625\u0650\u0630\u064e\u0627 \u062f\u064f\u0639\u0650\u064a\u062a\u064f\u0645\u06e1 \u0641\u064e\u0671\u062f\u06e1\u062e\u064f\u0644\u064f\u0648\u0627\u0652 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0637\u064e\u0639\u0650\u0645\u06e1\u062a\u064f\u0645\u06e1 \u0641\u064e\u0671\u0646\u062a\u064e\u0634\u0650\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u0644\u064e\u0627 \u0645\u064f\u0633\u06e1\u062a\u064e\u0640\u0654\u06e1\u0646\u0650\u0633\u0650\u064a\u0646\u064e \u0644\u0650\u062d\u064e\u062f\u0650\u064a\u062b\u064d\u06da \u0625\u0650\u0646\u0651\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u06e1 \u0643\u064e\u0627\u0646\u064e \u064a\u064f\u0624\u06e1\u0630\u0650\u064a \u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064e \u0641\u064e\u064a\u064e\u0633\u06e1\u062a\u064e\u062d\u06e1\u064a\u0650\u06e6 \u0645\u0650\u0646\u0643\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u062d\u06e1\u064a\u0650\u06e6 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650\u06da \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0633\u064e\u0623\u064e\u0644\u06e1\u062a\u064f\u0645\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0645\u064e\u062a\u064e\u0670\u0639\u0657\u0627 \u0641\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0645\u0650\u0646 \u0648\u064e\u0631\u064e\u0627\u0653\u0621\u0650 \u062d\u0650\u062c\u064e\u0627\u0628\u0656\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u06e1 \u0623\u064e\u0637\u06e1\u0647\u064e\u0631\u064f \u0644\u0650\u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0646\u0651\u064e\u06da \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u0646 \u062a\u064f\u0624\u06e1\u0630\u064f\u0648\u0627\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064e\u0646 \u062a\u064e\u0646\u0643\u0650\u062d\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0628\u064e\u062f\u064b\u0627\u06da \u0625\u0650\u0646\u0651\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u06e1 \u0643\u064e\u0627\u0646\u064e \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0638\u0650\u064a\u0645\u064b\u0627",translation:"Wahai orang-orang yang beriman! Janganlah kamu memasuki rumah-rumah Nabi kecuali jika kamu diizinkan untuk makan tanpa menunggu waktu masak (makanannya),687) tetapi jika kamu dipanggil maka masuklah dan apabila kamu selesai makan, keluarlah kamu tanpa memperpanjang percakapan. Sesungguhnya yang demikian itu adalah mengganggu Nabi sehingga dia (Nabi) malu kepadamu (untuk menyuruhmu keluar), dan Allah tidak malu (menerangkan) yang benar. Apabila kamu meminta sesuatu (keperluan) kepada mereka (istri-istri Nabi), maka mintalah dari balik tabir. (Cara) yang demikian itu lebih suci bagi hatimu dan hati mereka. Dan tidak boleh kamu menyakiti (hati) Rasulullah dan tidak boleh (pula) menikahi istri-istrinya selama-lamanya setelahnya (Nabi wafat). Sungguh, yang demikian itu sangat besar (dosanya) di sisi Allah"},{id:54,text:"\u0625\u0650\u0646 \u062a\u064f\u0628\u06e1\u062f\u064f\u0648\u0627\u0652 \u0634\u064e\u064a\u06e1\u0640\u0654\u064b\u0627 \u0623\u064e\u0648\u06e1 \u062a\u064f\u062e\u06e1\u0641\u064f\u0648\u0647\u064f \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u0657\u0627",translation:"Jika kamu menyatakan sesuatu atau menyembunyikannya, maka sesungguhnya Allah Maha Mengetahui segala sesuatu"},{id:55,text:"\u0644\u0651\u064e\u0627 \u062c\u064f\u0646\u064e\u0627\u062d\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0646\u0651\u064e \u0641\u0650\u064a\u0653 \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0626\u0650\u0647\u0650\u0646\u0651\u064e \u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064e\u0628\u06e1\u0646\u064e\u0627\u0653\u0626\u0650\u0647\u0650\u0646\u0651\u064e \u0648\u064e\u0644\u064e\u0627\u0653 \u0625\u0650\u062e\u06e1\u0648\u064e\u0670\u0646\u0650\u0647\u0650\u0646\u0651\u064e \u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064e\u0628\u06e1\u0646\u064e\u0627\u0653\u0621\u0650 \u0625\u0650\u062e\u06e1\u0648\u064e\u0670\u0646\u0650\u0647\u0650\u0646\u0651\u064e \u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064e\u0628\u06e1\u0646\u064e\u0627\u0653\u0621\u0650 \u0623\u064e\u062e\u064e\u0648\u064e\u0670\u062a\u0650\u0647\u0650\u0646\u0651\u064e \u0648\u064e\u0644\u064e\u0627 \u0646\u0650\u0633\u064e\u0627\u0653\u0626\u0650\u0647\u0650\u0646\u0651\u064e \u0648\u064e\u0644\u064e\u0627 \u0645\u064e\u0627 \u0645\u064e\u0644\u064e\u0643\u064e\u062a\u06e1 \u0623\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u064f\u0647\u064f\u0646\u0651\u064e\u06d7 \u0648\u064e\u0671\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0634\u064e\u0647\u0650\u064a\u062f\u064b\u0627",translation:"Tidak ada dosa atas istri-istri Nabi (untuk berjumpa tanpa tabir) dengan bapak-bapak mereka, anak laki-laki mereka, saudara laki-laki mereka, anak laki-laki dari saudara laki-laki mereka, anak laki-laki dari saudara perempuan mereka, perempuan-perempuan mereka (yang beriman) dan hamba sahaya yang mereka miliki, dan bertakwalah kamu (istri-istri Nabi) kepada Allah. Sungguh, Allah Maha Menyaksikan segala sesuatu"},{id:56,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u062a\u064e\u0647\u064f\u06e5 \u064a\u064f\u0635\u064e\u0644\u0651\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650\u06da \u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0635\u064e\u0644\u0651\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0648\u064e\u0633\u064e\u0644\u0651\u0650\u0645\u064f\u0648\u0627\u0652 \u062a\u064e\u0633\u06e1\u0644\u0650\u064a\u0645\u064b\u0627",translation:"(Sesungguhnya Allah dan para malaikat-Nya berselawat untuk Nabi.688) Wahai orang-orang yang beriman! Berselawatlah kamu untuk Nabi dan ucapkanlah salam dengan penuh penghormatan kepadanya"},{id:57,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0624\u06e1\u0630\u064f\u0648\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f\u06e5 \u0644\u064e\u0639\u064e\u0646\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u0650\u064a \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0648\u064e\u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0648\u064e\u0623\u064e\u0639\u064e\u062f\u0651\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u0657\u0627 \u0645\u0651\u064f\u0647\u0650\u064a\u0646\u0657\u0627",translation:"Sesungguhnya (terhadap) orang-orang yang menyakiti Allah dan Rasul-Nya, Allah akan melaknatnya di dunia dan di akhirat, dan menyediakan azab yang menghinakan bagi mereka"},{id:58,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0624\u06e1\u0630\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064e\u0670\u062a\u0650 \u0628\u0650\u063a\u064e\u064a\u06e1\u0631\u0650 \u0645\u064e\u0627 \u0671\u0643\u06e1\u062a\u064e\u0633\u064e\u0628\u064f\u0648\u0627\u0652 \u0641\u064e\u0642\u064e\u062f\u0650 \u0671\u062d\u06e1\u062a\u064e\u0645\u064e\u0644\u064f\u0648\u0627\u0652 \u0628\u064f\u0647\u06e1\u062a\u064e\u0670\u0646\u0657\u0627 \u0648\u064e\u0625\u0650\u062b\u06e1\u0645\u0657\u0627 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u0657\u0627",translation:"Dan orang-orang yang menyakiti orang-orang mukmin laki-laki dan perempuan, tanpa ada kesalahan yang mereka perbuat, maka sungguh, mereka telah memikul kebohongan dan dosa yang nyata"},{id:59,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064f \u0642\u064f\u0644 \u0644\u0651\u0650\u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u0650\u0643\u064e \u0648\u064e\u0628\u064e\u0646\u064e\u0627\u062a\u0650\u0643\u064e \u0648\u064e\u0646\u0650\u0633\u064e\u0627\u0653\u0621\u0650 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u064a\u064f\u062f\u06e1\u0646\u0650\u064a\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0646\u0651\u064e \u0645\u0650\u0646 \u062c\u064e\u0644\u064e\u0670\u0628\u0650\u064a\u0628\u0650\u0647\u0650\u0646\u0651\u064e\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0623\u064e\u062f\u06e1\u0646\u064e\u0649\u0670\u0653 \u0623\u064e\u0646 \u064a\u064f\u0639\u06e1\u0631\u064e\u0641\u06e1\u0646\u064e \u0641\u064e\u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0630\u064e\u064a\u06e1\u0646\u064e\u06d7 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u0657\u0627 \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0657\u0627",translation:"(Wahai Nabi! Katakanlah kepada istri-istrimu, anak-anak perempuanmu dan istri-istri orang mukmin, \"Hendaklah mereka menutupkan jilbabnya690) ke seluruh tubuh mereka.\" Yang demikian itu agar mereka lebih mudah untuk dikenali, sehingga mereka tidak diganggu. Dan Allah Maha Pengampun, Maha Penyayang"},{id:60,text:"\u06de\u0644\u0651\u064e\u0626\u0650\u0646 \u0644\u0651\u064e\u0645\u06e1 \u064a\u064e\u0646\u062a\u064e\u0647\u0650 \u0671\u0644\u06e1\u0645\u064f\u0646\u064e\u0670\u0641\u0650\u0642\u064f\u0648\u0646\u064e \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645 \u0645\u0651\u064e\u0631\u064e\u0636\u065e \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0631\u06e1\u062c\u0650\u0641\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0645\u064e\u062f\u0650\u064a\u0646\u064e\u0629\u0650 \u0644\u064e\u0646\u064f\u063a\u06e1\u0631\u0650\u064a\u064e\u0646\u0651\u064e\u0643\u064e \u0628\u0650\u0647\u0650\u0645\u06e1 \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0627 \u064a\u064f\u062c\u064e\u0627\u0648\u0650\u0631\u064f\u0648\u0646\u064e\u0643\u064e \u0641\u0650\u064a\u0647\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u0657\u0627",translation:"Sungguh, jika orang-orang munafik, orang-orang yang berpenyakit dalam hatinya dan orang-orang yang menyebarkan kabar bohong di Madinah tidak berhenti (dari menyakitimu), niscaya Kami perintahkan engkau (untuk memerangi) mereka, kemudian mereka tidak lagi menjadi tetanggamu (di Madinah) kecuali sebentar"},{id:61,text:"\u0645\u0651\u064e\u0644\u06e1\u0639\u064f\u0648\u0646\u0650\u064a\u0646\u064e\u06d6 \u0623\u064e\u064a\u06e1\u0646\u064e\u0645\u064e\u0627 \u062b\u064f\u0642\u0650\u0641\u064f\u0648\u0653\u0627\u0652 \u0623\u064f\u062e\u0650\u0630\u064f\u0648\u0627\u0652 \u0648\u064e\u0642\u064f\u062a\u0651\u0650\u0644\u064f\u0648\u0627\u0652 \u062a\u064e\u0642\u06e1\u062a\u0650\u064a\u0644\u0657\u0627",translation:"dalam keadaan terlaknat. Di mana saja mereka dijumpai, mereka akan ditangkap dan dibunuh tanpa ampun"},{id:62,text:"\u0633\u064f\u0646\u0651\u064e\u0629\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u0650\u064a \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062e\u064e\u0644\u064e\u0648\u06e1\u0627\u0652 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f\u06d6 \u0648\u064e\u0644\u064e\u0646 \u062a\u064e\u062c\u0650\u062f\u064e \u0644\u0650\u0633\u064f\u0646\u0651\u064e\u0629\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064e\u0628\u06e1\u062f\u0650\u064a\u0644\u0657\u0627",translation:"Sebagai sunnah Allah yang (berlaku juga) bagi orang-orang yang telah terdahulu sebelum(mu), dan engkau tidak akan mendapati perubahan pada sunah Allah"},{id:63,text:"\u064a\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0643\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0639\u064e\u0646\u0650 \u0671\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u0650\u06d6 \u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0639\u0650\u0644\u06e1\u0645\u064f\u0647\u064e\u0627 \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u062f\u06e1\u0631\u0650\u064a\u0643\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e \u0671\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064e \u062a\u064e\u0643\u064f\u0648\u0646\u064f \u0642\u064e\u0631\u0650\u064a\u0628\u064b\u0627",translation:"Manusia bertanya kepadamu (Muhammad) tentang hari Kiamat. Katakanlah, \"Ilmu tentang hari Kiamat itu hanya di sisi Allah.\" Dan tahukah engkau, boleh jadi hari Kiamat itu sudah dekat waktunya"},{id:64,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0639\u064e\u0646\u064e \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0648\u064e\u0623\u064e\u0639\u064e\u062f\u0651\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0633\u064e\u0639\u0650\u064a\u0631\u064b\u0627",translation:"Sungguh, Allah melaknat orang-orang kafir dan menyediakan bagi mereka api yang menyala-nyala (neraka)"},{id:65,text:"\u062e\u064e\u0670\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627\u0653 \u0623\u064e\u0628\u064e\u062f\u0657\u0627\u06d6 \u0644\u0651\u064e\u0627 \u064a\u064e\u062c\u0650\u062f\u064f\u0648\u0646\u064e \u0648\u064e\u0644\u0650\u064a\u0651\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0635\u0650\u064a\u0631\u0657\u0627",translation:"mereka kekal di dalamnya selama-lamanya; mereka tidak akan mendapatkan pelindung dan penolong"},{id:66,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u062a\u064f\u0642\u064e\u0644\u0651\u064e\u0628\u064f \u0648\u064f\u062c\u064f\u0648\u0647\u064f\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u064a\u064e\u0670\u0644\u064e\u064a\u06e1\u062a\u064e\u0646\u064e\u0627\u0653 \u0623\u064e\u0637\u064e\u0639\u06e1\u0646\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0623\u064e\u0637\u064e\u0639\u06e1\u0646\u064e\u0627 \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e\u0627\u06e0",translation:"Pada hari (ketika) wajah mereka dibolak-balikkan dalam neraka, mereka berkata, \"Duhai, kiranya dahulu kami taat kepada Allah dan taat (pula) kepada Rasul"},{id:67,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u0637\u064e\u0639\u06e1\u0646\u064e\u0627 \u0633\u064e\u0627\u062f\u064e\u062a\u064e\u0646\u064e\u0627 \u0648\u064e\u0643\u064f\u0628\u064e\u0631\u064e\u0627\u0653\u0621\u064e\u0646\u064e\u0627 \u0641\u064e\u0623\u064e\u0636\u064e\u0644\u0651\u064f\u0648\u0646\u064e\u0627 \u0671\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u064e\u0627\u06e0",translation:"Dan mereka berkata, \"Ya Tuhan kami, sesungguhnya kami telah menaati para pemimpin dan para pembesar kami, lalu mereka menyesatkan kami dari jalan (yang benar)"},{id:68,text:"\u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u0650\u0647\u0650\u0645\u06e1 \u0636\u0650\u0639\u06e1\u0641\u064e\u064a\u06e1\u0646\u0650 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0648\u064e\u0671\u0644\u06e1\u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0644\u064e\u0639\u06e1\u0646\u0657\u0627 \u0643\u064e\u0628\u0650\u064a\u0631\u0657\u0627",translation:"Ya Tuhan kami, timpakanlah kepada mereka azab dua kali lipat dan laknatlah mereka dengan laknat yang besar"},{id:69,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u0643\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0630\u064e\u0648\u06e1\u0627\u0652 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0641\u064e\u0628\u064e\u0631\u0651\u064e\u0623\u064e\u0647\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0645\u0651\u064e\u0627 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652\u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u062c\u0650\u064a\u0647\u0657\u0627",translation:"Wahai orang-orang yang beriman! Janganlah kamu seperti orang-orang yang menyakiti Musa, maka Allah membersihkannya dari tuduhan-tuduhan yang mereka lontarkan. Dan dia seorang yang mempunyai kedudukan terhormat di sisi Allah"},{id:70,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627\u0652 \u0642\u064e\u0648\u06e1\u0644\u0657\u0627 \u0633\u064e\u062f\u0650\u064a\u062f\u0657\u0627",translation:"Wahai orang-orang yang beriman! Bertakwalah kamu kepada Allah dan ucapkanlah perkataan yang benar"},{id:71,text:"\u064a\u064f\u0635\u06e1\u0644\u0650\u062d\u06e1 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u0639\u06e1\u0645\u064e\u0670\u0644\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u064a\u064e\u063a\u06e1\u0641\u0650\u0631\u06e1 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0630\u064f\u0646\u064f\u0648\u0628\u064e\u0643\u064f\u0645\u06e1\u06d7 \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0637\u0650\u0639\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f\u06e5 \u0641\u064e\u0642\u064e\u062f\u06e1 \u0641\u064e\u0627\u0632\u064e \u0641\u064e\u0648\u06e1\u0632\u064b\u0627 \u0639\u064e\u0638\u0650\u064a\u0645\u064b\u0627",translation:"niscaya Allah akan memperbaiki amal-amalmu dan mengampuni dosa-dosamu. Dan barang siapa menaati Allah dan Rasul-Nya, maka sungguh, dia menang dengan kemenangan yang agung"},{id:72,text:"\u0625\u0650\u0646\u0651\u064e\u0627 \u0639\u064e\u0631\u064e\u0636\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0645\u064e\u0627\u0646\u064e\u0629\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0671\u0644\u06e1\u062c\u0650\u0628\u064e\u0627\u0644\u0650 \u0641\u064e\u0623\u064e\u0628\u064e\u064a\u06e1\u0646\u064e \u0623\u064e\u0646 \u064a\u064e\u062d\u06e1\u0645\u0650\u0644\u06e1\u0646\u064e\u0647\u064e\u0627 \u0648\u064e\u0623\u064e\u0634\u06e1\u0641\u064e\u0642\u06e1\u0646\u064e \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0648\u064e\u062d\u064e\u0645\u064e\u0644\u064e\u0647\u064e\u0627 \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064f\u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0643\u064e\u0627\u0646\u064e \u0638\u064e\u0644\u064f\u0648\u0645\u0657\u0627 \u062c\u064e\u0647\u064f\u0648\u0644\u0657\u0627",translation:"Sesungguhnya Kami telah menawarkan amanat kepada langit, bumi dan gunung-gunung; tetapi semuanya enggan untuk memikul amanat itu dan mereka khawatir tidak akan melaksanakannya (berat), lalu dipikullah amanat itu oleh manusia. Sungguh, manusia itu sangat zalim dan sangat bodoh"},{id:73,text:"\u0644\u0651\u0650\u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u0645\u064f\u0646\u064e\u0670\u0641\u0650\u0642\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0646\u064e\u0670\u0641\u0650\u0642\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0634\u06e1\u0631\u0650\u0643\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0634\u06e1\u0631\u0650\u0643\u064e\u0670\u062a\u0650 \u0648\u064e\u064a\u064e\u062a\u064f\u0648\u0628\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064e\u0670\u062a\u0650\u06d7 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u0657\u0627 \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064e\u06e2\u0627",translation:"sehingga Allah akan mengazab orang-orang munafik laki-laki dan perempuan, orang-orang musyrik laki-laki dan perempuan; dan Allah akan menerima tobat orang-orang mukmin laki-laki dan perempuan. Dan Allah Maha Pengampun, Maha Penyayang"}]},{id:34,name:"\u0633\u0628\u0625",transliteration:"Saba",translation:"Saba\\'",type:"meccan",total_verses:54,verses:[{id:1,text:"\u0671\u0644\u06e1\u062d\u064e\u0645\u06e1\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0644\u064e\u0647\u064f\u06e5 \u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0644\u064e\u0647\u064f \u0671\u0644\u06e1\u062d\u064e\u0645\u06e1\u062f\u064f \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650\u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u062d\u064e\u0643\u0650\u064a\u0645\u064f \u0671\u0644\u06e1\u062e\u064e\u0628\u0650\u064a\u0631\u064f",translation:"Segala puji bagi Allah yang memiliki apa yang ada di langit dan apa yang ada di bumi dan segala puji di akhirat bagi Allah. Dan Dialah Yang Mahabijaksana, Mahateliti"},{id:2,text:"\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u064a\u064e\u0644\u0650\u062c\u064f \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u062e\u06e1\u0631\u064f\u062c\u064f \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0646\u0632\u0650\u0644\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0639\u06e1\u0631\u064f\u062c\u064f \u0641\u0650\u064a\u0647\u064e\u0627\u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f \u0671\u0644\u06e1\u063a\u064e\u0641\u064f\u0648\u0631\u064f",translation:"Dia mengetahui apa yang masuk ke dalam bumi, apa yang keluar darinya, apa yang turun dari langit dan apa yang naik kepadanya. Dan Dialah Yang Maha Penyayang, Maha Pengampun"},{id:3,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u062a\u064e\u0623\u06e1\u062a\u0650\u064a\u0646\u064e\u0627 \u0671\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064f\u06d6 \u0642\u064f\u0644\u06e1 \u0628\u064e\u0644\u064e\u0649\u0670 \u0648\u064e\u0631\u064e\u0628\u0651\u0650\u064a \u0644\u064e\u062a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0639\u064e\u0670\u0644\u0650\u0645\u0650 \u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u0628\u0650\u06d6 \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0632\u064f\u0628\u064f \u0639\u064e\u0646\u06e1\u0647\u064f \u0645\u0650\u062b\u06e1\u0642\u064e\u0627\u0644\u064f \u0630\u064e\u0631\u0651\u064e\u0629\u0656 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0644\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064e\u0635\u06e1\u063a\u064e\u0631\u064f \u0645\u0650\u0646 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064e\u0643\u06e1\u0628\u064e\u0631\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0641\u0650\u064a \u0643\u0650\u062a\u064e\u0670\u0628\u0656 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u0656",translation:"(Dan orang-orang yang kafir berkata, \"Hari Kiamat itu tidak akan datang kepada kami.\" Katakanlah, \"Pasti datang, demi Tuhanku Yang mengetahui yang gaib, Kiamat itu pasti akan datang kepadamu. Tidak ada yang tersembunyi bagi-Nya sekalipun seberat zarah691)baik yang di langit maupun yang di bumi, yang lebih kecil dari itu atau yang lebih besar, semuanya (tertulis) dalam Kitab yang jelas (Lau\u1e25 Ma\u1e25f\u016b\u1e93)"},{id:4,text:"\u0644\u0651\u0650\u064a\u064e\u062c\u06e1\u0632\u0650\u064a\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650\u06da \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u063a\u06e1\u0641\u0650\u0631\u064e\u0629\u065e \u0648\u064e\u0631\u0650\u0632\u06e1\u0642\u065e \u0643\u064e\u0631\u0650\u064a\u0645\u065e",translation:"agar Dia (Allah) memberi balasan kepada orang-orang yang beriman dan mengerjakan kebajikan. Mereka memperoleh ampunan dan rezeki yang mulia (surga)"},{id:5,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0633\u064e\u0639\u064e\u0648\u06e1 \u0641\u0650\u064a\u0653 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0645\u064f\u0639\u064e\u0670\u062c\u0650\u0632\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u065e \u0645\u0651\u0650\u0646 \u0631\u0651\u0650\u062c\u06e1\u0632\u064d \u0623\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Dan orang-orang yang berusaha untuk (menentang) ayat-ayat Kami dengan anggapan mereka dapat melemahkan (menggagalkan azab Kami), mereka itu akan memperoleh azab, yaitu azab yang sangat pedih"},{id:6,text:"\u0648\u064e\u064a\u064e\u0631\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0639\u0650\u0644\u06e1\u0645\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064e \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064e \u0648\u064e\u064a\u064e\u0647\u06e1\u062f\u0650\u064a\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0670\u0637\u0650 \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u0650 \u0671\u0644\u06e1\u062d\u064e\u0645\u0650\u064a\u062f\u0650",translation:"Dan orang-orang yang diberi ilmu (Ahli Kitab) berpendapat bahwa (wahyu) yang diturunkan kepadamu (Muhammad) dari Tuhanmu itulah yang benar dan memberi petunjuk (bagi manusia) kepada jalan (Allah) Yang Mahaperkasa, Maha Terpuji"},{id:7,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0647\u064e\u0644\u06e1 \u0646\u064e\u062f\u064f\u0644\u0651\u064f\u0643\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u062c\u064f\u0644\u0656 \u064a\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0643\u064f\u0645\u06e1 \u0625\u0650\u0630\u064e\u0627 \u0645\u064f\u0632\u0651\u0650\u0642\u06e1\u062a\u064f\u0645\u06e1 \u0643\u064f\u0644\u0651\u064e \u0645\u064f\u0645\u064e\u0632\u0651\u064e\u0642\u064d \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0644\u064e\u0641\u0650\u064a \u062e\u064e\u0644\u06e1\u0642\u0656 \u062c\u064e\u062f\u0650\u064a\u062f\u064d",translation:"Dan orang-orang kafir berkata (kepada teman-temannya), \"Maukah kami tunjukkan kepadamu seorang laki-laki692) yang memberitakan kepadamu bahwa apabila badanmu telah hancur sehancur-hancurnya, kamu pasti (akan dibangkitkan kembali) dalam ciptaan yang baru"},{id:8,text:"\u0623\u064e\u0641\u06e1\u062a\u064e\u0631\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u0630\u0650\u0628\u064b\u0627 \u0623\u064e\u0645 \u0628\u0650\u0647\u0650\u06e6 \u062c\u0650\u0646\u0651\u064e\u0629\u064f\u06e2\u06d7 \u0628\u064e\u0644\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0641\u0650\u064a \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0648\u064e\u0671\u0644\u0636\u0651\u064e\u0644\u064e\u0670\u0644\u0650 \u0671\u0644\u06e1\u0628\u064e\u0639\u0650\u064a\u062f\u0650",translation:"Apakah dia mengada-adakan kebohongan terhadap Allah atau sakit gila?\" (Tidak), tetapi orang-orang yang tidak beriman kepada akhirat itu berada dalam siksaan dan kesesatan yang jauh"},{id:9,text:"\u0623\u064e\u0641\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0631\u064e\u0648\u06e1\u0627\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u0647\u0650\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u06e1\u0641\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06da \u0625\u0650\u0646 \u0646\u0651\u064e\u0634\u064e\u0623\u06e1 \u0646\u064e\u062e\u06e1\u0633\u0650\u0641\u06e1 \u0628\u0650\u0647\u0650\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0623\u064e\u0648\u06e1 \u0646\u064f\u0633\u06e1\u0642\u0650\u0637\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0643\u0650\u0633\u064e\u0641\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650\u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0623\u0653\u064a\u064e\u0629\u0657 \u0644\u0651\u0650\u0643\u064f\u0644\u0651\u0650 \u0639\u064e\u0628\u06e1\u062f\u0656 \u0645\u0651\u064f\u0646\u0650\u064a\u0628\u0656",translation:"Maka apakah mereka tidak memperhatikan langit dan bumi yang ada di hadapan dan di belakang mereka? Jika Kami menghendaki, niscaya Kami benamkan mereka di bumi atau Kami jatuhkan kepada mereka kepingan-kepingan dari langit. Sungguh, pada yang demikian itu benar-benar terdapat tanda (kekuasaan Allah) bagi setiap hamba yang kembali (kepada-Nya)"},{id:10,text:"\u06de\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0627 \u062f\u064e\u0627\u0648\u064f\u06e5\u062f\u064e \u0645\u0650\u0646\u0651\u064e\u0627 \u0641\u064e\u0636\u06e1\u0644\u0657\u0627\u06d6 \u064a\u064e\u0670\u062c\u0650\u0628\u064e\u0627\u0644\u064f \u0623\u064e\u0648\u0651\u0650\u0628\u0650\u064a \u0645\u064e\u0639\u064e\u0647\u064f\u06e5 \u0648\u064e\u0671\u0644\u0637\u0651\u064e\u064a\u06e1\u0631\u064e\u06d6 \u0648\u064e\u0623\u064e\u0644\u064e\u0646\u0651\u064e\u0627 \u0644\u064e\u0647\u064f \u0671\u0644\u06e1\u062d\u064e\u062f\u0650\u064a\u062f\u064e",translation:"Dan sungguh, Telah Kami berikan kepada Dawud karunia dari Kami. (Kami berfirman), \"Wahai gunung-gunung dan burung-burung! Bertasbihlah berulang-ulang bersama Dawud,\" dan Kami telah melunakkan besi untuknya"},{id:11,text:"\u0623\u064e\u0646\u0650 \u0671\u0639\u06e1\u0645\u064e\u0644\u06e1 \u0633\u064e\u0670\u0628\u0650\u063a\u064e\u0670\u062a\u0656 \u0648\u064e\u0642\u064e\u062f\u0651\u0650\u0631\u06e1 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0631\u06e1\u062f\u0650\u06d6 \u0648\u064e\u0671\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0627\u0652 \u0635\u064e\u0670\u0644\u0650\u062d\u064b\u0627\u06d6 \u0625\u0650\u0646\u0651\u0650\u064a \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0628\u064e\u0635\u0650\u064a\u0631\u065e",translation:"(yaitu) buatlah baju besi yang besar-besar dan ukurlah anyamannya; dan kerjakanlah kebajikan. Sungguh, Aku Maha Melihat apa yang kamu kerjakan"},{id:12,text:"\u0648\u064e\u0644\u0650\u0633\u064f\u0644\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u064e \u0671\u0644\u0631\u0651\u0650\u064a\u062d\u064e \u063a\u064f\u062f\u064f\u0648\u0651\u064f\u0647\u064e\u0627 \u0634\u064e\u0647\u06e1\u0631\u065e \u0648\u064e\u0631\u064e\u0648\u064e\u0627\u062d\u064f\u0647\u064e\u0627 \u0634\u064e\u0647\u06e1\u0631\u065e\u06d6 \u0648\u064e\u0623\u064e\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u06e5 \u0639\u064e\u064a\u06e1\u0646\u064e \u0671\u0644\u06e1\u0642\u0650\u0637\u06e1\u0631\u0650\u06d6 \u0648\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u062c\u0650\u0646\u0651\u0650 \u0645\u064e\u0646 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f \u0628\u064e\u064a\u06e1\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u06e1\u0647\u0650 \u0628\u0650\u0625\u0650\u0630\u06e1\u0646\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0632\u0650\u063a\u06e1 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0639\u064e\u0646\u06e1 \u0623\u064e\u0645\u06e1\u0631\u0650\u0646\u064e\u0627 \u0646\u064f\u0630\u0650\u0642\u06e1\u0647\u064f \u0645\u0650\u0646\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0671\u0644\u0633\u0651\u064e\u0639\u0650\u064a\u0631\u0650",translation:"Dan Kami (tundukkan) angin bagi Sulaiman, yang perjalanannya pada waktu pagi sama dengan perjalanan sebulan dan perjalanannya pada waktu sore sama dengan perjalanan sebulan (pula)693) dan Kami alirkan cairan tembaga baginya. Dan sebagian dari jin ada yang bekerja di hadapannya (di bawah kekuasaannya) dengan izin Tuhannya. Dan siapa yang menyimpang di antara mereka dari perintah Kami, Kami rasakan kepadanya azab neraka yang apinya menyala-nyala"},{id:13,text:"\u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0644\u064e\u0647\u064f\u06e5 \u0645\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0645\u0650\u0646 \u0645\u0651\u064e\u062d\u064e\u0670\u0631\u0650\u064a\u0628\u064e \u0648\u064e\u062a\u064e\u0645\u064e\u0670\u062b\u0650\u064a\u0644\u064e \u0648\u064e\u062c\u0650\u0641\u064e\u0627\u0646\u0656 \u0643\u064e\u0671\u0644\u06e1\u062c\u064e\u0648\u064e\u0627\u0628\u0650 \u0648\u064e\u0642\u064f\u062f\u064f\u0648\u0631\u0656 \u0631\u0651\u064e\u0627\u0633\u0650\u064a\u064e\u0670\u062a\u064d\u06da \u0671\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0653\u0627\u0652 \u0621\u064e\u0627\u0644\u064e \u062f\u064e\u0627\u0648\u064f\u06e5\u062f\u064e \u0634\u064f\u0643\u06e1\u0631\u0657\u0627\u06da \u0648\u064e\u0642\u064e\u0644\u0650\u064a\u0644\u065e \u0645\u0651\u0650\u0646\u06e1 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a\u064e \u0671\u0644\u0634\u0651\u064e\u0643\u064f\u0648\u0631\u064f",translation:"Mereka (para jin itu) bekerja untuk Sulaiman sesuai dengan apa yang dikehendakinya di antaranya (membuat) gedung-gedung yang tinggi, patung-patung, piring-piring yang (besarnya) seperti kolam dan periuk-periuk yang tetap (berada di atas tungku). Bekerjalah wahai keluarga Dawud untuk bersyukur (kepada Allah). Dan sedikit sekali dari hamba-hamba-Ku yang bersyukur"},{id:14,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0642\u064e\u0636\u064e\u064a\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u064e \u0645\u064e\u0627 \u062f\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0648\u06e1\u062a\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u062f\u064e\u0627\u0653\u0628\u0651\u064e\u0629\u064f \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u062a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f \u0645\u0650\u0646\u0633\u064e\u0623\u064e\u062a\u064e\u0647\u064f\u06e5\u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062e\u064e\u0631\u0651\u064e \u062a\u064e\u0628\u064e\u064a\u0651\u064e\u0646\u064e\u062a\u0650 \u0671\u0644\u06e1\u062c\u0650\u0646\u0651\u064f \u0623\u064e\u0646 \u0644\u0651\u064e\u0648\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u0628\u064e \u0645\u064e\u0627 \u0644\u064e\u0628\u0650\u062b\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0671\u0644\u06e1\u0645\u064f\u0647\u0650\u064a\u0646\u0650",translation:"Maka ketika Kami telah menetapkan kematian atasnya (Sulaiman), tidak ada yang menunjukkan kepada mereka kematiannya itu kecuali rayap yang memakan tongkatnya. Maka ketika dia telah tersungkur, tahulah jin itu bahwa sekiranya mereka mengetahui hal yang gaib tentu mereka tidak menetap dalam siksa yang menghinakan"},{id:15,text:"\u0644\u064e\u0642\u064e\u062f\u06e1 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0633\u064e\u0628\u064e\u0625\u0656 \u0641\u0650\u064a \u0645\u064e\u0633\u06e1\u0643\u064e\u0646\u0650\u0647\u0650\u0645\u06e1 \u0621\u064e\u0627\u064a\u064e\u0629\u065e\u06d6 \u062c\u064e\u0646\u0651\u064e\u062a\u064e\u0627\u0646\u0650 \u0639\u064e\u0646 \u064a\u064e\u0645\u0650\u064a\u0646\u0656 \u0648\u064e\u0634\u0650\u0645\u064e\u0627\u0644\u0656\u06d6 \u0643\u064f\u0644\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0631\u0651\u0650\u0632\u06e1\u0642\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0671\u0634\u06e1\u0643\u064f\u0631\u064f\u0648\u0627\u0652 \u0644\u064e\u0647\u064f\u06e5\u06da \u0628\u064e\u0644\u06e1\u062f\u064e\u0629\u065e \u0637\u064e\u064a\u0651\u0650\u0628\u064e\u0629\u065e \u0648\u064e\u0631\u064e\u0628\u0651\u064c \u063a\u064e\u0641\u064f\u0648\u0631\u065e",translation:"Sungguh, bagi kaum Saba` ada tanda (kebesaran Tuhan) di tempat kediaman mereka yaitu dua buah kebun di sebelah kanan dan di sebeleh kiri, (kepada mereka dikatakan), \"Makanlah olehmu dari rezeki yang (dianugerahkan) Tuhanmu dan bersyukurlah kepada-Nya. (Negerimu) adalah negeri yang baik (nyaman) sedang (Tuhanmu) adalah Tuhan Yang Maha Pengampun"},{id:16,text:"\u0641\u064e\u0623\u064e\u0639\u06e1\u0631\u064e\u0636\u064f\u0648\u0627\u0652 \u0641\u064e\u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0633\u064e\u064a\u06e1\u0644\u064e \u0671\u0644\u06e1\u0639\u064e\u0631\u0650\u0645\u0650 \u0648\u064e\u0628\u064e\u062f\u0651\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f\u0645 \u0628\u0650\u062c\u064e\u0646\u0651\u064e\u062a\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u062c\u064e\u0646\u0651\u064e\u062a\u064e\u064a\u06e1\u0646\u0650 \u0630\u064e\u0648\u064e\u0627\u062a\u064e\u064a\u06e1 \u0623\u064f\u0643\u064f\u0644\u064d \u062e\u064e\u0645\u06e1\u0637\u0656 \u0648\u064e\u0623\u064e\u062b\u06e1\u0644\u0656 \u0648\u064e\u0634\u064e\u064a\u06e1\u0621\u0656 \u0645\u0651\u0650\u0646 \u0633\u0650\u062f\u06e1\u0631\u0656 \u0642\u064e\u0644\u0650\u064a\u0644\u0656",translation:"(Tetapi mereka berpaling, maka Kami kirim kepada mereka banjir yang besar694) dan Kami ganti kedua kebun mereka dengan dua kebun yang ditumbuhi (pohon-pohon) yang berbuah pahit, pohon A\u1e61l dan sedikit pohon Sidr"},{id:17,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062c\u064e\u0632\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f\u0645 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652\u06d6 \u0648\u064e\u0647\u064e\u0644\u06e1 \u0646\u064f\u062c\u064e\u0670\u0632\u0650\u064a\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u06e1\u0643\u064e\u0641\u064f\u0648\u0631\u064e",translation:"Demikianlah Kami memberi balasan kepada mereka karena kekafiran mereka. Dan Kami tidak menjatuhkan azab (yang demikian itu), melainkan hanya kepada orang-orang yang sangat kafir"},{id:18,text:"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0628\u064e\u064a\u06e1\u0646\u064e \u0671\u0644\u06e1\u0642\u064f\u0631\u064e\u0649 \u0671\u0644\u0651\u064e\u062a\u0650\u064a \u0628\u064e\u0670\u0631\u064e\u0643\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0642\u064f\u0631\u0657\u0649 \u0638\u064e\u0670\u0647\u0650\u0631\u064e\u0629\u0657 \u0648\u064e\u0642\u064e\u062f\u0651\u064e\u0631\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0671\u0644\u0633\u0651\u064e\u064a\u06e1\u0631\u064e\u06d6 \u0633\u0650\u064a\u0631\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0644\u064e\u064a\u064e\u0627\u0644\u0650\u064a\u064e \u0648\u064e\u0623\u064e\u064a\u0651\u064e\u0627\u0645\u064b\u0627 \u0621\u064e\u0627\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dan Kami jadikan antara mereka (penduduk Saba`) dan negeri-negeri yang Kami berkahi (Syam), beberapa negeri yang berdekatan dan Kami tetapkan antara negeri-negeri itu (jarak-jarak) perjalanan. Berjalanlah kamu di negeri-negeri itu pada malam dan siang hari dengan aman"},{id:19,text:"\u0641\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0628\u064e\u0670\u0639\u0650\u062f\u06e1 \u0628\u064e\u064a\u06e1\u0646\u064e \u0623\u064e\u0633\u06e1\u0641\u064e\u0627\u0631\u0650\u0646\u064e\u0627 \u0648\u064e\u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u06e1 \u0641\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0623\u064e\u062d\u064e\u0627\u062f\u0650\u064a\u062b\u064e \u0648\u064e\u0645\u064e\u0632\u0651\u064e\u0642\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0643\u064f\u0644\u0651\u064e \u0645\u064f\u0645\u064e\u0632\u0651\u064e\u0642\u064d\u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0623\u0653\u064a\u064e\u0670\u062a\u0656 \u0644\u0651\u0650\u0643\u064f\u0644\u0651\u0650 \u0635\u064e\u0628\u0651\u064e\u0627\u0631\u0656 \u0634\u064e\u0643\u064f\u0648\u0631\u0656",translation:"(Maka mereka berkata, \"Ya Tuhan kami, jauhkanlah jarak perjalanan kami,\"697) dan (berarti mereka) menzalimi diri mereka sendiri; maka Kami jadikan mereka bahan pembicaraan dan Kami hancurkan mereka sehancur-hancurnya. Sungguh, pada yang demikian itu benar-benar terdapat tanda-tanda (kekuasaan Allah) bagi setiap orang yang sabar dan bersyukur"},{id:20,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0635\u064e\u062f\u0651\u064e\u0642\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0625\u0650\u0628\u06e1\u0644\u0650\u064a\u0633\u064f \u0638\u064e\u0646\u0651\u064e\u0647\u064f\u06e5 \u0641\u064e\u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0647\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0641\u064e\u0631\u0650\u064a\u0642\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dan sungguh, Iblis telah dapat meyakinkan terhadap mereka kebenaran sangkaannya, lalu mereka mengikutinya, kecuali sebagian dari orang-orang mukmin"},{id:21,text:"\u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0647\u064f\u06e5 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0645\u0651\u0650\u0646 \u0633\u064f\u0644\u06e1\u0637\u064e\u0670\u0646\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0644\u0650\u0646\u064e\u0639\u06e1\u0644\u064e\u0645\u064e \u0645\u064e\u0646 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f \u0628\u0650\u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0645\u0650\u0645\u0651\u064e\u0646\u06e1 \u0647\u064f\u0648\u064e \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0641\u0650\u064a \u0634\u064e\u0643\u0651\u0656\u06d7 \u0648\u064e\u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u064d \u062d\u064e\u0641\u0650\u064a\u0638\u065e",translation:"Dan tidak ada kekuasaan (Iblis) terhadap mereka, melainkan hanya agar Kami dapat membedakan siapa yang beriman kepada adanya akhirat dan siapa yang ragu-ragu tentang (akhirat) itu. Dan Tuhanmu Maha Memelihara segala sesuatu"},{id:22,text:"\u0642\u064f\u0644\u0650 \u0671\u062f\u06e1\u0639\u064f\u0648\u0627\u0652 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0632\u064e\u0639\u064e\u0645\u06e1\u062a\u064f\u0645 \u0645\u0651\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0627 \u064a\u064e\u0645\u06e1\u0644\u0650\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u062b\u06e1\u0642\u064e\u0627\u0644\u064e \u0630\u064e\u0631\u0651\u064e\u0629\u0656 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0644\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u0650\u0645\u064e\u0627 \u0645\u0650\u0646 \u0634\u0650\u0631\u06e1\u0643\u0656 \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0638\u064e\u0647\u0650\u064a\u0631\u0656",translation:"Katakanlah (Muhammad), \"Serulah mereka yang kamu anggap (sebagai tuhan) selain Allah! Mereka tidak memiliki (kekuasaan) seberat zarah pun di langit dan di bumi, dan mereka sama sekali tidak mempunyai peran serta dalam (penciptaan) langit dan bumi dan tidak ada di antara mereka yang menjadi pembantu bagi-Nya"},{id:23,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0646\u0641\u064e\u0639\u064f \u0671\u0644\u0634\u0651\u064e\u0641\u064e\u0670\u0639\u064e\u0629\u064f \u0639\u0650\u0646\u062f\u064e\u0647\u064f\u06e5\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0644\u0650\u0645\u064e\u0646\u06e1 \u0623\u064e\u0630\u0650\u0646\u064e \u0644\u064e\u0647\u064f\u06e5\u06da \u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u064e\u0627 \u0641\u064f\u0632\u0651\u0650\u0639\u064e \u0639\u064e\u0646 \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u06e1 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0645\u064e\u0627\u0630\u064e\u0627 \u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u06e1\u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064e\u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0639\u064e\u0644\u0650\u064a\u0651\u064f \u0671\u0644\u06e1\u0643\u064e\u0628\u0650\u064a\u0631\u064f",translation:"Dan syafaat (pertolongan) di sisi-Nya hanya berguna bagi orang yang telah diizinkan-Nya (memperoleh syafaat itu). Sehingga apabila telah dihilangkan ketakutan dari hati mereka, mereka berkata, \"Apakah yang telah difirmankan oleh Tuhanmu?\" Mereka menjawab, \"(Perkataan) yang benar,\" dan Dialah Yang Mahatinggi, Mahabesar"},{id:24,text:"\u06de\u0642\u064f\u0644\u06e1 \u0645\u064e\u0646 \u064a\u064e\u0631\u06e1\u0632\u064f\u0642\u064f\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d6 \u0642\u064f\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06d6 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u0648\u06e1 \u0625\u0650\u064a\u0651\u064e\u0627\u0643\u064f\u0645\u06e1 \u0644\u064e\u0639\u064e\u0644\u064e\u0649\u0670 \u0647\u064f\u062f\u064b\u0649 \u0623\u064e\u0648\u06e1 \u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0670\u0644\u0656 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u0656",translation:"Katakanlah (Muhammad), \"Siapakah yang memberi rezeki kepadamu dari langit dan dari bumi?\" Katakanlah, \"Allah,\" dan sesungguhnya kami atau kamu (orang-orang musyrik), pasti berada dalam kebenaran atau dalam kesesatan yang nyata"},{id:25,text:"\u0642\u064f\u0644 \u0644\u0651\u064e\u0627 \u062a\u064f\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0648\u0646\u064e \u0639\u064e\u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u062c\u06e1\u0631\u064e\u0645\u06e1\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u0646\u064f\u0633\u06e1\u0640\u0654\u064e\u0644\u064f \u0639\u064e\u0645\u0651\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Katakanlah, \"Kamu tidak akan dimintai tanggung jawab atas apa yang kami kerjakan dan kami juga tidak akan dimintai tanggung jawab atas apa yang kamu kerjakan"},{id:26,text:"\u0642\u064f\u0644\u06e1 \u064a\u064e\u062c\u06e1\u0645\u064e\u0639\u064f \u0628\u064e\u064a\u06e1\u0646\u064e\u0646\u064e\u0627 \u0631\u064e\u0628\u0651\u064f\u0646\u064e\u0627 \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u0641\u06e1\u062a\u064e\u062d\u064f \u0628\u064e\u064a\u06e1\u0646\u064e\u0646\u064e\u0627 \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0641\u064e\u062a\u0651\u064e\u0627\u062d\u064f \u0671\u0644\u06e1\u0639\u064e\u0644\u0650\u064a\u0645\u064f",translation:"Katakanlah, \"Tuhan kita akan mengumpulkan kita semua, kemudian Dia memberi keputusan antara kita dengan benar. Dan Dia Yang Maha Pemberi keputusan, Maha Mengetahui"},{id:27,text:"\u0642\u064f\u0644\u06e1 \u0623\u064e\u0631\u064f\u0648\u0646\u0650\u064a\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u0644\u06e1\u062d\u064e\u0642\u06e1\u062a\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0653\u0621\u064e\u06d6 \u0643\u064e\u0644\u0651\u064e\u0627\u06da \u0628\u064e\u0644\u06e1 \u0647\u064f\u0648\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0671\u0644\u06e1\u062d\u064e\u0643\u0650\u064a\u0645\u064f",translation:"Katakanlah, \"Perlihatkanlah kepadaku sembahan-sembahan yang kamu hubungkan dengan Dia sebagai sekutu-sekutu(-Nya), tidak mungkin! Sebenarnya Dialah Allah Yang Mahaperkasa, Mahabijaksana"},{id:28,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0670\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064e\u0627\u0653\u0641\u0651\u064e\u0629\u0657 \u0644\u0651\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0628\u064e\u0634\u0650\u064a\u0631\u0657\u0627 \u0648\u064e\u0646\u064e\u0630\u0650\u064a\u0631\u0657\u0627 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan Kami tidak mengutus engkau (Muhammad), melainkan kepada semua umat manusia sebagai pembawa berita gembira dan sebagai pemberi peringatan, tetapi kebanyakan manusia tidak mengetahui"},{id:29,text:"\u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0645\u064e\u062a\u064e\u0649\u0670 \u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u06e1\u0648\u064e\u0639\u06e1\u062f\u064f \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0635\u064e\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Dan mereka berkata, \"Kapankah (datangnya) janji ini, jika kamu orang yang benar"},{id:30,text:"\u0642\u064f\u0644 \u0644\u0651\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u064a\u0639\u064e\u0627\u062f\u064f \u064a\u064e\u0648\u06e1\u0645\u0656 \u0644\u0651\u064e\u0627 \u062a\u064e\u0633\u06e1\u062a\u064e\u0640\u0654\u06e1\u062e\u0650\u0631\u064f\u0648\u0646\u064e \u0639\u064e\u0646\u06e1\u0647\u064f \u0633\u064e\u0627\u0639\u064e\u0629\u0657 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0633\u06e1\u062a\u064e\u0642\u06e1\u062f\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Katakanlah, \"Bagimu ada hari yang telah dijanjikan (hari Kiamat), kamu tidak dapat meminta penundaan atau percepatannya sesaat pun"},{id:31,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0644\u064e\u0646 \u0646\u0651\u064f\u0624\u06e1\u0645\u0650\u0646\u064e \u0628\u0650\u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u0650 \u0648\u064e\u0644\u064e\u0627 \u0628\u0650\u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0628\u064e\u064a\u06e1\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u06e1\u0647\u0650\u06d7 \u0648\u064e\u0644\u064e\u0648\u06e1 \u062a\u064e\u0631\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u0650 \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u064f\u0648\u0646\u064e \u0645\u064e\u0648\u06e1\u0642\u064f\u0648\u0641\u064f\u0648\u0646\u064e \u0639\u0650\u0646\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u064a\u064e\u0631\u06e1\u062c\u0650\u0639\u064f \u0628\u064e\u0639\u06e1\u0636\u064f\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u06e1\u0636\u064d \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0644\u064e \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u0633\u06e1\u062a\u064f\u0636\u06e1\u0639\u0650\u0641\u064f\u0648\u0627\u0652 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u064e\u0631\u064f\u0648\u0627\u0652 \u0644\u064e\u0648\u06e1\u0644\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0644\u064e\u0643\u064f\u0646\u0651\u064e\u0627 \u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dan orang-orang kafir berkata, \"Kami tidak akan beriman kepada Alquran ini dan tidak (pula) kepada kitab yang sebelumnya.\" Dan (alangkah mengerikan) kalau kamu melihat ketika orang-orang yang zalim itu dihadapkan kepada Tuhannya, sebagian mereka mengembalikan perkataan kepada sebagian yang lain; orang-orang yang dianggap lemah berkata kepada orang-orang yang menyombongkan diri, \"Kalau tidaklah karena kamu tentulah kami menjadi orang-orang mukmin"},{id:32,text:"\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u064e\u0631\u064f\u0648\u0627\u0652 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u0633\u06e1\u062a\u064f\u0636\u06e1\u0639\u0650\u0641\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u064e\u062d\u06e1\u0646\u064f \u0635\u064e\u062f\u064e\u062f\u06e1\u0646\u064e\u0670\u0643\u064f\u0645\u06e1 \u0639\u064e\u0646\u0650 \u0671\u0644\u06e1\u0647\u064f\u062f\u064e\u0649\u0670 \u0628\u064e\u0639\u06e1\u062f\u064e \u0625\u0650\u0630\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u06d6 \u0628\u064e\u0644\u06e1 \u0643\u064f\u0646\u062a\u064f\u0645 \u0645\u0651\u064f\u062c\u06e1\u0631\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Orang-orang yang menyombongkan diri berkata kepada orang-orang yang dianggap lemah, \"Kamikah yang telah menghalangimu untuk memperoleh petunjuk setelah petunjuk itu datang kepadamu? (Tidak!) Sebenarnya kamu sendirilah orang-orang yang berbuat dosa"},{id:33,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u0633\u06e1\u062a\u064f\u0636\u06e1\u0639\u0650\u0641\u064f\u0648\u0627\u0652 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u064e\u0631\u064f\u0648\u0627\u0652 \u0628\u064e\u0644\u06e1 \u0645\u064e\u0643\u06e1\u0631\u064f \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u0650 \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u0625\u0650\u0630\u06e1 \u062a\u064e\u0623\u06e1\u0645\u064f\u0631\u064f\u0648\u0646\u064e\u0646\u064e\u0627\u0653 \u0623\u064e\u0646 \u0646\u0651\u064e\u0643\u06e1\u0641\u064f\u0631\u064e \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0646\u064e\u062c\u06e1\u0639\u064e\u0644\u064e \u0644\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u0646\u062f\u064e\u0627\u062f\u0657\u0627\u06da \u0648\u064e\u0623\u064e\u0633\u064e\u0631\u0651\u064f\u0648\u0627\u0652 \u0671\u0644\u0646\u0651\u064e\u062f\u064e\u0627\u0645\u064e\u0629\u064e \u0644\u064e\u0645\u0651\u064e\u0627 \u0631\u064e\u0623\u064e\u0648\u064f\u0627\u0652 \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064e\u06da \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u063a\u06e1\u0644\u064e\u0670\u0644\u064e \u0641\u0650\u064a\u0653 \u0623\u064e\u0639\u06e1\u0646\u064e\u0627\u0642\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652\u06d6 \u0647\u064e\u0644\u06e1 \u064a\u064f\u062c\u06e1\u0632\u064e\u0648\u06e1\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan orang-orang yang dianggap lemah berkata kepada orang-orang yang menyombongkan diri, \"(Tidak!) Sebenarnya tipu daya(mu) pada waktu malam dan siang (yang menghalangi kami), ketika kamu menyeru kami agar kami kafir kepada Allah dan menjadikan sekutu-sekutu bagi-Nya.\" Mereka menyatakan penyesalan ketika mereka melihat azab. Dan Kami pasangkan belenggu di leher orang-orang yang kafir. Mereka tidak dibalas melainkan sesuai dengan apa yang telah mereka kerjakan"},{id:34,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a \u0642\u064e\u0631\u06e1\u064a\u064e\u0629\u0656 \u0645\u0651\u0650\u0646 \u0646\u0651\u064e\u0630\u0650\u064a\u0631\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0627\u0644\u064e \u0645\u064f\u062a\u06e1\u0631\u064e\u0641\u064f\u0648\u0647\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0627 \u0628\u0650\u0645\u064e\u0627\u0653 \u0623\u064f\u0631\u06e1\u0633\u0650\u0644\u06e1\u062a\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6 \u0643\u064e\u0670\u0641\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Dan setiap Kami mengutus seorang pemberi peringatan kepada suatu negeri, orang-orang yang hidup mewah (di negeri itu) berkata, \"Kami benar-benar mengingkari apa yang kamu sampaikan sebagai utusan"},{id:35,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0646\u064e\u062d\u06e1\u0646\u064f \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064f \u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u0657\u0627 \u0648\u064e\u0623\u064e\u0648\u06e1\u0644\u064e\u0670\u062f\u0657\u0627 \u0648\u064e\u0645\u064e\u0627 \u0646\u064e\u062d\u06e1\u0646\u064f \u0628\u0650\u0645\u064f\u0639\u064e\u0630\u0651\u064e\u0628\u0650\u064a\u0646\u064e",translation:"Dan mereka berkata, \"Kami memiliki lebih banyak harta dan anak-anak (daripada kamu) dan kami tidak akan diazab"},{id:36,text:"\u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u064a\u064e\u0628\u06e1\u0633\u064f\u0637\u064f \u0671\u0644\u0631\u0651\u0650\u0632\u06e1\u0642\u064e \u0644\u0650\u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0648\u064e\u064a\u064e\u0642\u06e1\u062f\u0650\u0631\u064f \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Katakanlah, \"Sungguh, Tuhanku melapangkan rezeki bagi siapa yang Dia kehendaki dan membatasinya (bagi siapa yang Dia kehendaki), tetapi kebanyakan manusia tidak mengetahui"},{id:37,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u064f\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064e\u0648\u06e1\u0644\u064e\u0670\u062f\u064f\u0643\u064f\u0645 \u0628\u0650\u0671\u0644\u0651\u064e\u062a\u0650\u064a \u062a\u064f\u0642\u064e\u0631\u0651\u0650\u0628\u064f\u0643\u064f\u0645\u06e1 \u0639\u0650\u0646\u062f\u064e\u0646\u064e\u0627 \u0632\u064f\u0644\u06e1\u0641\u064e\u0649\u0670\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u06e1 \u0621\u064e\u0627\u0645\u064e\u0646\u064e \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064e \u0635\u064e\u0670\u0644\u0650\u062d\u0657\u0627 \u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u062c\u064e\u0632\u064e\u0627\u0653\u0621\u064f \u0671\u0644\u0636\u0651\u0650\u0639\u06e1\u0641\u0650 \u0628\u0650\u0645\u064e\u0627 \u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u063a\u064f\u0631\u064f\u0641\u064e\u0670\u062a\u0650 \u0621\u064e\u0627\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Dan bukanlah harta dan anak-anakmu yang mendekatkan kamu kepada Kami; melainkan orang-orang yang beriman dan mengerjakan kebajikan, mereka itulah yang memperoleh balasan yang berlipat ganda atas apa yang telah mereka kerjakan; dan mereka aman sentosa di tempat-tempat yang tinggi (dalam surga)"},{id:38,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0633\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0641\u0650\u064a\u0653 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0645\u064f\u0639\u064e\u0670\u062c\u0650\u0632\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0645\u064f\u062d\u06e1\u0636\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan orang-orang yang berusaha menentang ayat-ayat Kami melemahkan (menggagalkan azab Kami), mereka itu dimasukkan ke dalam azab"},{id:39,text:"\u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u064a\u064e\u0628\u06e1\u0633\u064f\u0637\u064f \u0671\u0644\u0631\u0651\u0650\u0632\u06e1\u0642\u064e \u0644\u0650\u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0645\u0650\u0646\u06e1 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650\u06e6 \u0648\u064e\u064a\u064e\u0642\u06e1\u062f\u0650\u0631\u064f \u0644\u064e\u0647\u064f\u06e5\u06da \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0641\u064e\u0642\u06e1\u062a\u064f\u0645 \u0645\u0651\u0650\u0646 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0641\u064e\u0647\u064f\u0648\u064e \u064a\u064f\u062e\u06e1\u0644\u0650\u0641\u064f\u0647\u064f\u06e5\u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u062e\u064e\u064a\u06e1\u0631\u064f \u0671\u0644\u0631\u0651\u064e\u0640\u0670\u0632\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Katakanlah, \"Sungguh, Tuhanku melapangkan rezeki dan membatasinya bagi siapa yang Dia kehendaki di antara hamba-hamba-Nya.\" Dan apa saja yang kamu infakkan, Allah akan menggantinya dan Dialah pemberi rezeki yang terbaik"},{id:40,text:"\u0648\u064e\u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064e\u062d\u06e1\u0634\u064f\u0631\u064f\u0647\u064f\u0645\u06e1 \u062c\u064e\u0645\u0650\u064a\u0639\u0657\u0627 \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0644\u0650\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u0650 \u0623\u064e\u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650 \u0625\u0650\u064a\u0651\u064e\u0627\u0643\u064f\u0645\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0646\u064e",translation:"Dan (ingatlah) pada hari (ketika) Allah mengumpulkan mereka semuanya kemudian Dia berfirman kepada para malaikat, \"Apakah kepadamu mereka ini dahulu menyembah"},{id:41,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0633\u064f\u0628\u06e1\u062d\u064e\u0670\u0646\u064e\u0643\u064e \u0623\u064e\u0646\u062a\u064e \u0648\u064e\u0644\u0650\u064a\u0651\u064f\u0646\u064e\u0627 \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u0645\u06d6 \u0628\u064e\u0644\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u062c\u0650\u0646\u0651\u064e\u06d6 \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064f\u0647\u064f\u0645 \u0628\u0650\u0647\u0650\u0645 \u0645\u0651\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"(Para malaikat itu menjawab, \"Mahasuci Engkau. Engkaulah pelindung kami, bukan mereka; bahkan mereka telah menyembah jin;700) kebanyakan mereka beriman kepada jin"},{id:42,text:"\u0641\u064e\u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e \u0644\u064e\u0627 \u064a\u064e\u0645\u06e1\u0644\u0650\u0643\u064f \u0628\u064e\u0639\u06e1\u0636\u064f\u0643\u064f\u0645\u06e1 \u0644\u0650\u0628\u064e\u0639\u06e1\u0636\u0656 \u0646\u0651\u064e\u0641\u06e1\u0639\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u0636\u064e\u0631\u0651\u0657\u0627 \u0648\u064e\u0646\u064e\u0642\u064f\u0648\u0644\u064f \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627\u0652 \u0630\u064f\u0648\u0642\u064f\u0648\u0627\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0671\u0644\u0651\u064e\u062a\u0650\u064a \u0643\u064f\u0646\u062a\u064f\u0645 \u0628\u0650\u0647\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Maka pada hari ini sebagian kamu tidak kuasa (mendatangkan) manfaat maupun (menolak) mudarat kepada sebagian yang lain. Dan Kami katakan kepada orang-orang yang zalim, \"Rasakanlah olehmu azab neraka yang dahulu kamu dustakan"},{id:43,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062a\u064f\u062a\u06e1\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u064f\u0646\u064e\u0627 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0656 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u0647\u064e\u0670\u0630\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0631\u064e\u062c\u064f\u0644\u065e \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0623\u064e\u0646 \u064a\u064e\u0635\u064f\u062f\u0651\u064e\u0643\u064f\u0645\u06e1 \u0639\u064e\u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u064a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0624\u064f\u0643\u064f\u0645\u06e1 \u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u0647\u064e\u0670\u0630\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0625\u0650\u0641\u06e1\u0643\u065e \u0645\u0651\u064f\u0641\u06e1\u062a\u064e\u0631\u0657\u0649\u06da \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0644\u0650\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u06e1 \u0625\u0650\u0646\u06e1 \u0647\u064e\u0670\u0630\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0633\u0650\u062d\u06e1\u0631\u065e \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u065e",translation:"Dan apabila dibacakan kepada mereka ayat-ayat Kami yang terang, mereka berkata, \"Orang ini tidak lain hanya ingin menghalang-halangi kamu dari apa yang disembah oleh nenek moyangmu,\" dan mereka berkata, \"(Alquran) ini tidak lain hanyalah kebohongan yang diada-adakan saja.\" Dan orang-orang kafir berkata terhadap kebenaran ketika kebenaran (Alquran) itu datang kepada mereka, \"Ini tidak lain hanyalah sihir yang nyata"},{id:44,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0643\u064f\u062a\u064f\u0628\u0656 \u064a\u064e\u062f\u06e1\u0631\u064f\u0633\u064f\u0648\u0646\u064e\u0647\u064e\u0627\u06d6 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0642\u064e\u0628\u06e1\u0644\u064e\u0643\u064e \u0645\u0650\u0646 \u0646\u0651\u064e\u0630\u0650\u064a\u0631\u0656",translation:"Dan Kami tidak pernah memberikan kepada mereka kitab-kitab yang mereka baca dan Kami tidak pernah mengutus seorang pemberi peringatan kepada mereka sebelum engkau (Muhammad)"},{id:45,text:"\u0648\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u0644\u064e\u063a\u064f\u0648\u0627\u0652 \u0645\u0650\u0639\u06e1\u0634\u064e\u0627\u0631\u064e \u0645\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0641\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0631\u064f\u0633\u064f\u0644\u0650\u064a\u06d6 \u0641\u064e\u0643\u064e\u064a\u06e1\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0646\u064e\u0643\u0650\u064a\u0631\u0650",translation:"Dan orang-orang yang sebelum mereka telah mendustakan (para rasul) sedang orang-orang (kafir Mekkah) itu belum sampai menerima sepersepuluh dari apa701) yang telah Kami berikan kepada orang-orang terdahulu, namun mereka mendustakan para rasul-Ku. Maka (lihatlah) bagaimana dahsyatnya akibat kemurkaan-Ku"},{id:46,text:"\u06de\u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0639\u0650\u0638\u064f\u0643\u064f\u0645 \u0628\u0650\u0648\u064e\u0670\u062d\u0650\u062f\u064e\u0629\u064d\u06d6 \u0623\u064e\u0646 \u062a\u064e\u0642\u064f\u0648\u0645\u064f\u0648\u0627\u0652 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u062b\u06e1\u0646\u064e\u0649\u0670 \u0648\u064e\u0641\u064f\u0631\u064e\u0670\u062f\u064e\u0649\u0670 \u062b\u064f\u0645\u0651\u064e \u062a\u064e\u062a\u064e\u0641\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0627\u0652\u06da \u0645\u064e\u0627 \u0628\u0650\u0635\u064e\u0627\u062d\u0650\u0628\u0650\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u062c\u0650\u0646\u0651\u064e\u0629\u064d\u06da \u0625\u0650\u0646\u06e1 \u0647\u064f\u0648\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0646\u064e\u0630\u0650\u064a\u0631\u065e \u0644\u0651\u064e\u0643\u064f\u0645 \u0628\u064e\u064a\u06e1\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u0656 \u0634\u064e\u062f\u0650\u064a\u062f\u0656",translation:"Katakanlah, \"Aku hendak memperingatkan kepadamu satu hal saja, yaitu agar kamu menghadap Allah (dengan ikhlas) berdua-dua atau sendiri-sendiri;702) kemudian agar kamu pikirkan (tentang Muhammad). Kawanmu itu tidak gila sedikit pun. Dia tidak lain hanyalah seorang pemberi peringatan bagi kamu sebelum (menghadapi) azab yang keras"},{id:47,text:"\u0642\u064f\u0644\u06e1 \u0645\u064e\u0627 \u0633\u064e\u0623\u064e\u0644\u06e1\u062a\u064f\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u062c\u06e1\u0631\u0656 \u0641\u064e\u0647\u064f\u0648\u064e \u0644\u064e\u0643\u064f\u0645\u06e1\u06d6 \u0625\u0650\u0646\u06e1 \u0623\u064e\u062c\u06e1\u0631\u0650\u064a\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0634\u064e\u0647\u0650\u064a\u062f\u065e",translation:"Katakanlah (Muhammad), \"Imbalan apa pun yang aku minta kepadamu, maka itu untuk kamu.703) Imbalanku hanyalah dari Allah, dan Dia Maha Mengetahui segala sesuatu"},{id:48,text:"\u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u064a\u064e\u0642\u06e1\u0630\u0650\u0641\u064f \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0639\u064e\u0644\u0651\u064e\u0640\u0670\u0645\u064f \u0671\u0644\u06e1\u063a\u064f\u064a\u064f\u0648\u0628\u0650",translation:"Katakanlah, \"Sesungguhnya Tuhanku mewahyukan kebenaran. Dia Maha Mengetahui segala yang gaib"},{id:49,text:"\u0642\u064f\u0644\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0628\u06e1\u062f\u0650\u0626\u064f \u0671\u0644\u06e1\u0628\u064e\u0670\u0637\u0650\u0644\u064f \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0639\u0650\u064a\u062f\u064f",translation:"Katakanlah, \"Kebenaran telah datang dan yang batil itu tidak akan memulai dan tidak (pula) akan mengulangi"},{id:50,text:"\u0642\u064f\u0644\u06e1 \u0625\u0650\u0646 \u0636\u064e\u0644\u064e\u0644\u06e1\u062a\u064f \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0636\u0650\u0644\u0651\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0646\u064e\u0641\u06e1\u0633\u0650\u064a\u06d6 \u0648\u064e\u0625\u0650\u0646\u0650 \u0671\u0647\u06e1\u062a\u064e\u062f\u064e\u064a\u06e1\u062a\u064f \u0641\u064e\u0628\u0650\u0645\u064e\u0627 \u064a\u064f\u0648\u062d\u0650\u064a\u0653 \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0631\u064e\u0628\u0651\u0650\u064a\u0653\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0633\u064e\u0645\u0650\u064a\u0639\u065e \u0642\u064e\u0631\u0650\u064a\u0628\u065e",translation:"Katakanlah, \"Jika aku sesat maka sesungguhnya aku sesat untuk diriku sendiri; dan jika aku mendapat petunjuk maka itu disebabkan apa yang diwahyukan Tuhanku kepadaku. Sungguh, Dia Maha Mendengar, Mahadekat"},{id:51,text:"\u0648\u064e\u0644\u064e\u0648\u06e1 \u062a\u064e\u0631\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u06e1 \u0641\u064e\u0632\u0650\u0639\u064f\u0648\u0627\u0652 \u0641\u064e\u0644\u064e\u0627 \u0641\u064e\u0648\u06e1\u062a\u064e \u0648\u064e\u0623\u064f\u062e\u0650\u0630\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0645\u0651\u064e\u0643\u064e\u0627\u0646\u0656 \u0642\u064e\u0631\u0650\u064a\u0628\u0656",translation:"Dan (alangkah mengerikan) sekiranya engkau melihat mereka (orang-orang kafir) ketika terperanjat ketakutan (pada hari Kiamat); lalu mereka tidak dapat melepaskan diri dan mereka ditangkap dari tempat yang dekat (untuk dibawa ke neraka)"},{id:52,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0621\u064e\u0627\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0647\u0650\u06e6 \u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u062a\u0651\u064e\u0646\u064e\u0627\u0648\u064f\u0634\u064f \u0645\u0650\u0646 \u0645\u0651\u064e\u0643\u064e\u0627\u0646\u0650\u06ed \u0628\u064e\u0639\u0650\u064a\u062f\u0656",translation:"dan (ketika) mereka berkata, \"Kami beriman kepada-Nya.\" Namun bagaimana mereka dapat mencapai (keimanan) dari tempat yang jauh"},{id:53,text:"\u0648\u064e\u0642\u064e\u062f\u06e1 \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f\u06d6 \u0648\u064e\u064a\u064e\u0642\u06e1\u0630\u0650\u0641\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u0628\u0650 \u0645\u0650\u0646 \u0645\u0651\u064e\u0643\u064e\u0627\u0646\u0650\u06ed \u0628\u064e\u0639\u0650\u064a\u062f\u0656",translation:"Dan sungguh, mereka telah mengingkari Allah sebelum itu; dan mereka mendustakan tentang yang gaib dari tempat yang jauh"},{id:54,text:"\u0648\u064e\u062d\u0650\u064a\u0644\u064e \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0628\u064e\u064a\u06e1\u0646\u064e \u0645\u064e\u0627 \u064a\u064e\u0634\u06e1\u062a\u064e\u0647\u064f\u0648\u0646\u064e \u0643\u064e\u0645\u064e\u0627 \u0641\u064f\u0639\u0650\u0644\u064e \u0628\u0650\u0623\u064e\u0634\u06e1\u064a\u064e\u0627\u0639\u0650\u0647\u0650\u0645 \u0645\u0651\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0634\u064e\u0643\u0651\u0656 \u0645\u0651\u064f\u0631\u0650\u064a\u0628\u0650\u06ed",translation:"(Dan diberi penghalang antara mereka dengan apa yang mereka inginkan706) sebagaimana yang dilakukan terhadap orang-orang yang sepaham dengan mereka yang terdahulu. Sesungguhnya mereka dahulu (di dunia) dalam keraguan yang mendalam"}]},{id:35,name:"\u0641\u0627\u0637\u0631",transliteration:"Fatir",translation:"Pencipta",type:"meccan",total_verses:45,verses:[{id:1,text:"\u0671\u0644\u06e1\u062d\u064e\u0645\u06e1\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0627\u0637\u0650\u0631\u0650 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u062c\u064e\u0627\u0639\u0650\u0644\u0650 \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u0650 \u0631\u064f\u0633\u064f\u0644\u064b\u0627 \u0623\u064f\u0648\u0652\u0644\u0650\u064a\u0653 \u0623\u064e\u062c\u06e1\u0646\u0650\u062d\u064e\u0629\u0656 \u0645\u0651\u064e\u062b\u06e1\u0646\u064e\u0649\u0670 \u0648\u064e\u062b\u064f\u0644\u064e\u0670\u062b\u064e \u0648\u064e\u0631\u064f\u0628\u064e\u0670\u0639\u064e\u06da \u064a\u064e\u0632\u0650\u064a\u062f\u064f \u0641\u0650\u064a \u0671\u0644\u06e1\u062e\u064e\u0644\u06e1\u0642\u0650 \u0645\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0642\u064e\u062f\u0650\u064a\u0631\u065e",translation:"Segala puji bagi Allah Pencipta langit dan bumi, yang menjadikan malaikat sebagai utusan-utusan (untuk mengurus berbagai macam urusan) yang mempunyai sayap, masing-masing (ada yang) dua, tiga dan empat. Allah menambahkan pada ciptaan-Nya apa yang Dia kehendaki. Sungguh, Allah Mahakuasa atas segala sesuatu"},{id:2,text:"\u0645\u0651\u064e\u0627 \u064a\u064e\u0641\u06e1\u062a\u064e\u062d\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0645\u0650\u0646 \u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0629\u0656 \u0641\u064e\u0644\u064e\u0627 \u0645\u064f\u0645\u06e1\u0633\u0650\u0643\u064e \u0644\u064e\u0647\u064e\u0627\u06d6 \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0645\u06e1\u0633\u0650\u0643\u06e1 \u0641\u064e\u0644\u064e\u0627 \u0645\u064f\u0631\u06e1\u0633\u0650\u0644\u064e \u0644\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u0647\u0650\u06e6\u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0671\u0644\u06e1\u062d\u064e\u0643\u0650\u064a\u0645\u064f",translation:"Apa saja di antara rahmat Allah yang dianugerahkan kepada manusia, maka tidak ada yang dapat menahannya; dan apa saja yang ditahan-Nya maka tidak ada yang sanggup untuk melepaskannya setelah itu. Dan Dia lah Yang Mahaperkasa, Mahabijaksana"},{id:3,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0671\u0630\u06e1\u0643\u064f\u0631\u064f\u0648\u0627\u0652 \u0646\u0650\u0639\u06e1\u0645\u064e\u062a\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1\u06da \u0647\u064e\u0644\u06e1 \u0645\u0650\u0646\u06e1 \u062e\u064e\u0670\u0644\u0650\u0642\u064d \u063a\u064e\u064a\u06e1\u0631\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u0631\u06e1\u0632\u064f\u0642\u064f\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06da \u0644\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e\u06d6 \u0641\u064e\u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u062a\u064f\u0624\u06e1\u0641\u064e\u0643\u064f\u0648\u0646\u064e",translation:"Wahai manusia! Ingatlah akan nikmat Allah kepadamu. Adakah pencipta selain Allah yang dapat memberikan rezeki kepadamu dari langit dan bumi? Tidak ada tuhan selain Dia; maka mengapa kamu berpaling (dari ketauhidan)"},{id:4,text:"\u0648\u064e\u0625\u0650\u0646 \u064a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f\u0648\u0643\u064e \u0641\u064e\u0642\u064e\u062f\u06e1 \u0643\u064f\u0630\u0651\u0650\u0628\u064e\u062a\u06e1 \u0631\u064f\u0633\u064f\u0644\u065e \u0645\u0651\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064e\u06da \u0648\u064e\u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064f\u0631\u06e1\u062c\u064e\u0639\u064f \u0671\u0644\u06e1\u0623\u064f\u0645\u064f\u0648\u0631\u064f",translation:"Dan jika mereka mendustakan engkau (setelah engkau beri peringatan), maka sungguh, rasul-rasul sebelum engkau telah didustakan pula. Dan hanya kepada Allah segala urusan dikembalikan"},{id:5,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0625\u0650\u0646\u0651\u064e \u0648\u064e\u0639\u06e1\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u064e\u0642\u0651\u065e\u06d6 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u063a\u064f\u0631\u0651\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u064f \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u063a\u064f\u0631\u0651\u064e\u0646\u0651\u064e\u0643\u064f\u0645 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u063a\u064e\u0631\u064f\u0648\u0631\u064f",translation:"Wahai manusia! Sungguh, janji Allah itu benar, maka janganlah kehidupan dunia memperdayakan kamu dan janganlah (setan) yang pandai menipu, memperdayakan kamu tentang Allah"},{id:6,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u06e1 \u0639\u064e\u062f\u064f\u0648\u0651\u065e \u0641\u064e\u0671\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0647\u064f \u0639\u064e\u062f\u064f\u0648\u0651\u064b\u0627\u06da \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u062f\u06e1\u0639\u064f\u0648\u0627\u0652 \u062d\u0650\u0632\u06e1\u0628\u064e\u0647\u064f\u06e5 \u0644\u0650\u064a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1 \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u0650 \u0671\u0644\u0633\u0651\u064e\u0639\u0650\u064a\u0631\u0650",translation:"Sungguh, setan itu musuh bagimu, maka perlakukanlah ia sebagai musuh, karena sesungguhnya setan itu hanya mengajak golongannya agar mereka menjadi penghuni neraka yang menyala-nyala"},{id:7,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u065e \u0634\u064e\u062f\u0650\u064a\u062f\u065e\u06d6 \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u063a\u06e1\u0641\u0650\u0631\u064e\u0629\u065e \u0648\u064e\u0623\u064e\u062c\u06e1\u0631\u065e \u0643\u064e\u0628\u0650\u064a\u0631\u064c",translation:"Orang-orang yang kafir, mereka akan mendapat azab yang sangat keras. Dan orang-orang yang beriman dan mengerjakan kebajikan, mereka memperoleh ampunan dan pahala yang besar"},{id:8,text:"\u0623\u064e\u0641\u064e\u0645\u064e\u0646 \u0632\u064f\u064a\u0651\u0650\u0646\u064e \u0644\u064e\u0647\u064f\u06e5 \u0633\u064f\u0648\u0653\u0621\u064f \u0639\u064e\u0645\u064e\u0644\u0650\u0647\u0650\u06e6 \u0641\u064e\u0631\u064e\u0621\u064e\u0627\u0647\u064f \u062d\u064e\u0633\u064e\u0646\u0657\u0627\u06d6 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u0636\u0650\u0644\u0651\u064f \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0648\u064e\u064a\u064e\u0647\u06e1\u062f\u0650\u064a \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06d6 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0630\u06e1\u0647\u064e\u0628\u06e1 \u0646\u064e\u0641\u06e1\u0633\u064f\u0643\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u062d\u064e\u0633\u064e\u0631\u064e\u0670\u062a\u064d\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u064f\u06e2 \u0628\u0650\u0645\u064e\u0627 \u064a\u064e\u0635\u06e1\u0646\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Maka apakah pantas orang yang dijadikan terasa indah perbuatan buruknya, lalu menganggap baik perbuatannya itu? Sesungguhnya Allah menyesatkan siapa yang Dia kehendaki dan memberi petunjuk kepada siapa yang Dia kehendaki. Maka janganlah engkau (Muhammad) biarkan dirimu binasa karena kesedihan terhadap mereka. Sesungguhnya Allah Maha Mengetahui apa yang mereka perbuat"},{id:9,text:"\u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u064e \u0671\u0644\u0631\u0651\u0650\u064a\u064e\u0670\u062d\u064e \u0641\u064e\u062a\u064f\u062b\u0650\u064a\u0631\u064f \u0633\u064e\u062d\u064e\u0627\u0628\u0657\u0627 \u0641\u064e\u0633\u064f\u0642\u06e1\u0646\u064e\u0670\u0647\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0628\u064e\u0644\u064e\u062f\u0656 \u0645\u0651\u064e\u064a\u0651\u0650\u062a\u0656 \u0641\u064e\u0623\u064e\u062d\u06e1\u064a\u064e\u064a\u06e1\u0646\u064e\u0627 \u0628\u0650\u0647\u0650 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0628\u064e\u0639\u06e1\u062f\u064e \u0645\u064e\u0648\u06e1\u062a\u0650\u0647\u064e\u0627\u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0671\u0644\u0646\u0651\u064f\u0634\u064f\u0648\u0631\u064f",translation:"Dan Allah lah yang mengirimkan angin; lalu (angin itu) menggerakkan awan, maka Kami arahkan awan itu ke suatu negeri yang mati (tandus) lalu dengan hujan itu Kami hidupkan bumi setelah mati (kering). Seperti itulah kebangkitan"},{id:10,text:"\u0645\u064e\u0646 \u0643\u064e\u0627\u0646\u064e \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0671\u0644\u06e1\u0639\u0650\u0632\u0651\u064e\u0629\u064e \u0641\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u0639\u0650\u0632\u0651\u064e\u0629\u064f \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627\u06da \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u064a\u064e\u0635\u06e1\u0639\u064e\u062f\u064f \u0671\u0644\u06e1\u0643\u064e\u0644\u0650\u0645\u064f \u0671\u0644\u0637\u0651\u064e\u064a\u0651\u0650\u0628\u064f \u0648\u064e\u0671\u0644\u06e1\u0639\u064e\u0645\u064e\u0644\u064f \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064f \u064a\u064e\u0631\u06e1\u0641\u064e\u0639\u064f\u0647\u064f\u06e5\u06da \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0645\u06e1\u0643\u064f\u0631\u064f\u0648\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0640\u0654\u064e\u0627\u062a\u0650 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u065e \u0634\u064e\u062f\u0650\u064a\u062f\u065e\u06d6 \u0648\u064e\u0645\u064e\u0643\u06e1\u0631\u064f \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0648\u064e \u064a\u064e\u0628\u064f\u0648\u0631\u064f",translation:"Barangsiapa menghendaki kemuliaan, maka (ketahuilah) kemuliaan itu semuanya milik Allah. Kepada-Nyalah akan naik perkataan-perkataan yang baik,707) dan amal kebajikan Dia akan mengangkatnya.708) Adapun orang-orang yang merencanakan kejahatan mereka akan mendapat azab yang sangat keras, dan rencana jahat mereka akan hancur"},{id:11,text:"\u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u062e\u064e\u0644\u064e\u0642\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u062a\u064f\u0631\u064e\u0627\u0628\u0656 \u062b\u064f\u0645\u0651\u064e \u0645\u0650\u0646 \u0646\u0651\u064f\u0637\u06e1\u0641\u064e\u0629\u0656 \u062b\u064f\u0645\u0651\u064e \u062c\u064e\u0639\u064e\u0644\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u0657\u0627\u06da \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u062d\u06e1\u0645\u0650\u0644\u064f \u0645\u0650\u0646\u06e1 \u0623\u064f\u0646\u062b\u064e\u0649\u0670 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0636\u064e\u0639\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0639\u0650\u0644\u06e1\u0645\u0650\u0647\u0650\u06e6\u06da \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0639\u064e\u0645\u0651\u064e\u0631\u064f \u0645\u0650\u0646 \u0645\u0651\u064f\u0639\u064e\u0645\u0651\u064e\u0631\u0656 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0646\u0642\u064e\u0635\u064f \u0645\u0650\u0646\u06e1 \u0639\u064f\u0645\u064f\u0631\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0641\u0650\u064a \u0643\u0650\u062a\u064e\u0670\u0628\u064d\u06da \u0625\u0650\u0646\u0651\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u0633\u0650\u064a\u0631\u065e",translation:"Dan Allah menciptakan kamu dari tanah kemudian dari air mani, kemudian Dia menjadikan kamu berpasangan (laki-laki dan perempuan). Tidak ada seorang wanita pun yang mengandung dan melahirkan, melainkan dengan sepengetahuan-Nya. Dan tidak dipanjangkan umur seseorang dan tidak pula dikurangi umurnya, melainkan (sudah ditetapkan) dalam Kitab (Lau\u1e25 Ma\u1e25f\u016b\u1e93). Sungguh, yang demikian itu mudah bagi Allah"},{id:12,text:"\u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0648\u0650\u064a \u0671\u0644\u06e1\u0628\u064e\u062d\u06e1\u0631\u064e\u0627\u0646\u0650 \u0647\u064e\u0670\u0630\u064e\u0627 \u0639\u064e\u0630\u06e1\u0628\u065e \u0641\u064f\u0631\u064e\u0627\u062a\u065e \u0633\u064e\u0627\u0653\u0626\u0650\u063a\u065e \u0634\u064e\u0631\u064e\u0627\u0628\u064f\u0647\u064f\u06e5 \u0648\u064e\u0647\u064e\u0670\u0630\u064e\u0627 \u0645\u0650\u0644\u06e1\u062d\u064c \u0623\u064f\u062c\u064e\u0627\u062c\u065e\u06d6 \u0648\u064e\u0645\u0650\u0646 \u0643\u064f\u0644\u0651\u0656 \u062a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f\u0648\u0646\u064e \u0644\u064e\u062d\u06e1\u0645\u0657\u0627 \u0637\u064e\u0631\u0650\u064a\u0651\u0657\u0627 \u0648\u064e\u062a\u064e\u0633\u06e1\u062a\u064e\u062e\u06e1\u0631\u0650\u062c\u064f\u0648\u0646\u064e \u062d\u0650\u0644\u06e1\u064a\u064e\u0629\u0657 \u062a\u064e\u0644\u06e1\u0628\u064e\u0633\u064f\u0648\u0646\u064e\u0647\u064e\u0627\u06d6 \u0648\u064e\u062a\u064e\u0631\u064e\u0649 \u0671\u0644\u06e1\u0641\u064f\u0644\u06e1\u0643\u064e \u0641\u0650\u064a\u0647\u0650 \u0645\u064e\u0648\u064e\u0627\u062e\u0650\u0631\u064e \u0644\u0650\u062a\u064e\u0628\u06e1\u062a\u064e\u063a\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0641\u064e\u0636\u06e1\u0644\u0650\u0647\u0650\u06e6 \u0648\u064e\u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u0634\u06e1\u0643\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Dan tidak sama (antara) dua lautan; yang ini tawar, segar, sedap diminum dan yang lain asin lagi pahit. Dan dari (masing-masing lautan) itu kamu dapat memakan daging yang segar dan kamu dapat mengeluarkan perhiasan yang kamu pakai, dan di sana kamu melihat kapal-kapal berlayar membelah laut agar kamu dapat mencari karunia-Nya dan agar kamu bersyukur"},{id:13,text:"\u064a\u064f\u0648\u0644\u0650\u062c\u064f \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u064e \u0641\u0650\u064a \u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u0648\u064e\u064a\u064f\u0648\u0644\u0650\u062c\u064f \u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u0641\u0650\u064a \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u0650 \u0648\u064e\u0633\u064e\u062e\u0651\u064e\u0631\u064e \u0671\u0644\u0634\u0651\u064e\u0645\u06e1\u0633\u064e \u0648\u064e\u0671\u0644\u06e1\u0642\u064e\u0645\u064e\u0631\u064e\u06d6 \u0643\u064f\u0644\u0651\u065e \u064a\u064e\u062c\u06e1\u0631\u0650\u064a \u0644\u0650\u0623\u064e\u062c\u064e\u0644\u0656 \u0645\u0651\u064f\u0633\u064e\u0645\u0651\u0657\u0649\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u06e1 \u0644\u064e\u0647\u064f \u0671\u0644\u06e1\u0645\u064f\u0644\u06e1\u0643\u064f\u06da \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u06e6 \u0645\u064e\u0627 \u064a\u064e\u0645\u06e1\u0644\u0650\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u0642\u0650\u0637\u06e1\u0645\u0650\u064a\u0631\u064d",translation:"Dia memasukkan malam ke dalam siang dan memasukkan siang ke dalam malam dan menundukkan matahari dan bulan, masing-masing beredar menurut waktu yang ditentukan. Yang (berbuat) demikian itulah Allah Tuhanmu, milik-Nyalah segala kerajaan. Dan orang-orang yang kamu seru (sembah) selain Allah tidak mempunyai apa-apa walaupun setipis kulit ari"},{id:14,text:"\u0625\u0650\u0646 \u062a\u064e\u062f\u06e1\u0639\u064f\u0648\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u0645\u064e\u0639\u064f\u0648\u0627\u0652 \u062f\u064f\u0639\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0648\u06e1 \u0633\u064e\u0645\u0650\u0639\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u0671\u0633\u06e1\u062a\u064e\u062c\u064e\u0627\u0628\u064f\u0648\u0627\u0652 \u0644\u064e\u0643\u064f\u0645\u06e1\u06d6 \u0648\u064e\u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u064a\u064e\u0643\u06e1\u0641\u064f\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0634\u0650\u0631\u06e1\u0643\u0650\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0643\u064e \u0645\u0650\u062b\u06e1\u0644\u064f \u062e\u064e\u0628\u0650\u064a\u0631\u0656",translation:"Jika kamu menyeru mereka, mereka tidak mendengar seruanmu, dan sekiranya mereka mendengar, mereka juga tidak memperkenankan permintaanmu. Dan pada hari Kiamat mereka akan mengingkari kemusyrikanmu dan tidak ada yang dapat memberikan keterangan kepadamu seperti yang diberikan oleh (Allah) Yang Mahateliti"},{id:15,text:"\u06de\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0623\u064e\u0646\u062a\u064f\u0645\u064f \u0671\u0644\u06e1\u0641\u064f\u0642\u064e\u0631\u064e\u0627\u0653\u0621\u064f \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u063a\u064e\u0646\u0650\u064a\u0651\u064f \u0671\u0644\u06e1\u062d\u064e\u0645\u0650\u064a\u062f\u064f",translation:"Wahai manusia! Kamulah yang memerlukan Allah; dan Allah Dialah Yang Mahakaya (tidak memerlukan apa pun), Maha Terpuji"},{id:16,text:"\u0625\u0650\u0646 \u064a\u064e\u0634\u064e\u0623\u06e1 \u064a\u064f\u0630\u06e1\u0647\u0650\u0628\u06e1\u0643\u064f\u0645\u06e1 \u0648\u064e\u064a\u064e\u0623\u06e1\u062a\u0650 \u0628\u0650\u062e\u064e\u0644\u06e1\u0642\u0656 \u062c\u064e\u062f\u0650\u064a\u062f\u0656",translation:"Jika Dia menghendaki, niscaya Dia membinasakan kamu dan mendatangkan makhluk yang baru (untuk menggantikan kamu)"},{id:17,text:"\u0648\u064e\u0645\u064e\u0627 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u0650\u0639\u064e\u0632\u0650\u064a\u0632\u0656",translation:"Dan yang demikian itu tidak sulit bagi Allah"},{id:18,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0632\u0650\u0631\u064f \u0648\u064e\u0627\u0632\u0650\u0631\u064e\u0629\u065e \u0648\u0650\u0632\u06e1\u0631\u064e \u0623\u064f\u062e\u06e1\u0631\u064e\u0649\u0670\u06da \u0648\u064e\u0625\u0650\u0646 \u062a\u064e\u062f\u06e1\u0639\u064f \u0645\u064f\u062b\u06e1\u0642\u064e\u0644\u064e\u0629\u064c \u0625\u0650\u0644\u064e\u0649\u0670 \u062d\u0650\u0645\u06e1\u0644\u0650\u0647\u064e\u0627 \u0644\u064e\u0627 \u064a\u064f\u062d\u06e1\u0645\u064e\u0644\u06e1 \u0645\u0650\u0646\u06e1\u0647\u064f \u0634\u064e\u064a\u06e1\u0621\u065e \u0648\u064e\u0644\u064e\u0648\u06e1 \u0643\u064e\u0627\u0646\u064e \u0630\u064e\u0627 \u0642\u064f\u0631\u06e1\u0628\u064e\u0649\u0670\u0653\u06d7 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u062a\u064f\u0646\u0630\u0650\u0631\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062e\u06e1\u0634\u064e\u0648\u06e1\u0646\u064e \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u0628\u0650 \u0648\u064e\u0623\u064e\u0642\u064e\u0627\u0645\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e\u06da \u0648\u064e\u0645\u064e\u0646 \u062a\u064e\u0632\u064e\u0643\u0651\u064e\u0649\u0670 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u062a\u064e\u0632\u064e\u0643\u0651\u064e\u0649\u0670 \u0644\u0650\u0646\u064e\u0641\u06e1\u0633\u0650\u0647\u0650\u06e6\u06da \u0648\u064e\u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u0645\u064e\u0635\u0650\u064a\u0631\u064f",translation:"Dan orang yang berdosa tidak akan memikul dosa orang lain. Dan jika seseorang yang dibebani berat dosanya memanggil (orang lain) untuk memikul bebannya itu tidak akan dipikulkan sedikit pun, meskipun (yang dipanggilnya itu) kaum kerabatnya. Sesunggunya yang dapat engkau beri peringatan hanya orang-orang yang takut kepada (azab) Tuhannya (sekalipun) mereka tidak melihat-Nya709) dan mereka yang melaksanakan salat. Barangsiapa yang menyucikan dirinya, sesungguhnya dia menyucikan diri untuk kebaikan dirinya sendiri. Dan kepada Allah lah tempat kembali"},{id:19,text:"\u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0648\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0639\u06e1\u0645\u064e\u0649\u0670 \u0648\u064e\u0671\u0644\u06e1\u0628\u064e\u0635\u0650\u064a\u0631\u064f",translation:"Dan tidaklah sama orang yang buta dengan orang yang melihat"},{id:20,text:"\u0648\u064e\u0644\u064e\u0627 \u0671\u0644\u0638\u0651\u064f\u0644\u064f\u0645\u064e\u0670\u062a\u064f \u0648\u064e\u0644\u064e\u0627 \u0671\u0644\u0646\u0651\u064f\u0648\u0631\u064f",translation:"dan tidak (pula) sama gelap gulita dengan cahaya"},{id:21,text:"\u0648\u064e\u0644\u064e\u0627 \u0671\u0644\u0638\u0651\u0650\u0644\u0651\u064f \u0648\u064e\u0644\u064e\u0627 \u0671\u0644\u06e1\u062d\u064e\u0631\u064f\u0648\u0631\u064f",translation:"dan tidak (pula) sama yang teduh dengan yang panas"},{id:22,text:"\u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0648\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u062d\u06e1\u064a\u064e\u0627\u0653\u0621\u064f \u0648\u064e\u0644\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u062a\u064f\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u0633\u06e1\u0645\u0650\u0639\u064f \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06d6 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064e \u0628\u0650\u0645\u064f\u0633\u06e1\u0645\u0650\u0639\u0656 \u0645\u0651\u064e\u0646 \u0641\u0650\u064a \u0671\u0644\u06e1\u0642\u064f\u0628\u064f\u0648\u0631\u0650",translation:"dan tidak (pula) sama orang yang hidup dengan orang yang mati. Sungguh, Allah memberikan pendengaran kepada siapa yang Dia kehendaki dan engkau (Muhammad) tidak akan sanggup menjadikan orang yang di dalam kubur dapat mendengar"},{id:23,text:"\u0625\u0650\u0646\u06e1 \u0623\u064e\u0646\u062a\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0646\u064e\u0630\u0650\u064a\u0631\u064c",translation:"Engkau tidak lain hanyalah seorang pemberi peringatan"},{id:24,text:"\u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0670\u0643\u064e \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0628\u064e\u0634\u0650\u064a\u0631\u0657\u0627 \u0648\u064e\u0646\u064e\u0630\u0650\u064a\u0631\u0657\u0627\u06da \u0648\u064e\u0625\u0650\u0646 \u0645\u0651\u0650\u0646\u06e1 \u0623\u064f\u0645\u0651\u064e\u0629\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u062e\u064e\u0644\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0646\u064e\u0630\u0650\u064a\u0631\u065e",translation:"(Sungguh, Kami mengutus engkau dengan membawa kebenaran711) sebagai pembawa berita gembira dan sebagai pemberi peringatan. Dan tidak ada satu pun umat melainkan di sana telah datang seorang pemberi peringatan"},{id:25,text:"\u0648\u064e\u0625\u0650\u0646 \u064a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f\u0648\u0643\u064e \u0641\u064e\u0642\u064e\u062f\u06e1 \u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u0645\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u062a\u06e1\u0647\u064f\u0645\u06e1 \u0631\u064f\u0633\u064f\u0644\u064f\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0650 \u0648\u064e\u0628\u0650\u0671\u0644\u0632\u0651\u064f\u0628\u064f\u0631\u0650 \u0648\u064e\u0628\u0650\u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0671\u0644\u06e1\u0645\u064f\u0646\u0650\u064a\u0631\u0650",translation:"Dan jika mereka mendustakanmu, maka sungguh, orang-orang yang sebelum mereka pun telah mendustakan (rasul-rasul); ketika rasul-rasulnya datang dengan membawa keterangan yang nyata (mukjizat), zubur, dan kitab yang memberi penjelasan yang sempurna"},{id:26,text:"\u062b\u064f\u0645\u0651\u064e \u0623\u064e\u062e\u064e\u0630\u06e1\u062a\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652\u06d6 \u0641\u064e\u0643\u064e\u064a\u06e1\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0646\u064e\u0643\u0650\u064a\u0631\u0650",translation:"Kemudian Aku azab orang-orang yang kafir; maka (lihatlah) bagaimana akibat kemurkaan-Ku"},{id:27,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0631\u064e \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0645\u064e\u0627\u0653\u0621\u0657 \u0641\u064e\u0623\u064e\u062e\u06e1\u0631\u064e\u062c\u06e1\u0646\u064e\u0627 \u0628\u0650\u0647\u0650\u06e6 \u062b\u064e\u0645\u064e\u0631\u064e\u0670\u062a\u0656 \u0645\u0651\u064f\u062e\u06e1\u062a\u064e\u0644\u0650\u0641\u064b\u0627 \u0623\u064e\u0644\u06e1\u0648\u064e\u0670\u0646\u064f\u0647\u064e\u0627\u06da \u0648\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u062c\u0650\u0628\u064e\u0627\u0644\u0650 \u062c\u064f\u062f\u064e\u062f\u064f\u06e2 \u0628\u0650\u064a\u0636\u065e \u0648\u064e\u062d\u064f\u0645\u06e1\u0631\u065e \u0645\u0651\u064f\u062e\u06e1\u062a\u064e\u0644\u0650\u0641\u064c \u0623\u064e\u0644\u06e1\u0648\u064e\u0670\u0646\u064f\u0647\u064e\u0627 \u0648\u064e\u063a\u064e\u0631\u064e\u0627\u0628\u0650\u064a\u0628\u064f \u0633\u064f\u0648\u062f\u065e",translation:"Tidakkah engkau melihat bahwa Allah menurunkan air dari langit lalu dengan air itu Kami hasilkan buah-buahan yang beraneka macam jenisnya. Dan di antara gunung-gunung itu ada garis-garis putih dan merah yang beraneka macam warnanya dan ada (pula) yang hitam pekat"},{id:28,text:"\u0648\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0671\u0644\u062f\u0651\u064e\u0648\u064e\u0627\u0653\u0628\u0651\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0639\u064e\u0670\u0645\u0650 \u0645\u064f\u062e\u06e1\u062a\u064e\u0644\u0650\u0641\u064c \u0623\u064e\u0644\u06e1\u0648\u064e\u0670\u0646\u064f\u0647\u064f\u06e5 \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e\u06d7 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u062e\u06e1\u0634\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u0650\u0646\u06e1 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650 \u0671\u0644\u06e1\u0639\u064f\u0644\u064e\u0645\u064e\u0640\u0670\u0653\u0624\u064f\u0627\u0652\u06d7 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0632\u0650\u064a\u0632\u064c \u063a\u064e\u0641\u064f\u0648\u0631\u064c",translation:"Dan demikian (pula) di antara manusia, makhluk bergerak yang bernyawa dan hewan-hewan ternak ada yang bermacam-macam warnanya (dan jenisnya). Di antara hamba-hamba Allah yang takut kepada-Nya, hanyalah para ulama.713) Sungguh, Allah Mahaperkasa, Maha Pengampun"},{id:29,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062a\u06e1\u0644\u064f\u0648\u0646\u064e \u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0623\u064e\u0642\u064e\u0627\u0645\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u0623\u064e\u0646\u0641\u064e\u0642\u064f\u0648\u0627\u0652 \u0645\u0650\u0645\u0651\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0633\u0650\u0631\u0651\u0657\u0627 \u0648\u064e\u0639\u064e\u0644\u064e\u0627\u0646\u0650\u064a\u064e\u0629\u0657 \u064a\u064e\u0631\u06e1\u062c\u064f\u0648\u0646\u064e \u062a\u0650\u062c\u064e\u0670\u0631\u064e\u0629\u0657 \u0644\u0651\u064e\u0646 \u062a\u064e\u0628\u064f\u0648\u0631\u064e",translation:"Sesungguhnya orang-orang yang selalu membaca Kitab Allah (Alquran) dan melak\xadsana\xadkan salat dan menginfakkan sebagian rezeki yang Kami anugerahkan kepadanya dengan diam-diam dan terang-terangan, mereka itu mengharapkan perdagangan yang tidak akan rugi"},{id:30,text:"\u0644\u0650\u064a\u064f\u0648\u064e\u0641\u0651\u0650\u064a\u064e\u0647\u064f\u0645\u06e1 \u0623\u064f\u062c\u064f\u0648\u0631\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u064a\u064e\u0632\u0650\u064a\u062f\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0641\u064e\u0636\u06e1\u0644\u0650\u0647\u0650\u06e6\u0653\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0634\u064e\u0643\u064f\u0648\u0631\u065e",translation:"agar Allah menyempurnakan pahalanya kepada mereka dan menambah karunia-Nya. Sungguh, Allah Maha Pengampun, Maha Mensyukuri"},{id:31,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064e\u0648\u06e1\u062d\u064e\u064a\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f \u0645\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u0657\u0627 \u0644\u0651\u0650\u0645\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u06e1\u0647\u0650\u06d7 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650\u06e6 \u0644\u064e\u062e\u064e\u0628\u0650\u064a\u0631\u064f\u06e2 \u0628\u064e\u0635\u0650\u064a\u0631\u065e",translation:"Dan apa yang telah Kami wahyukan kepadamu (Muhammad) yaitu Kitab (Alquran) itulah yang benar, membenarkan kitab-kitab yang sebelumnya. Sungguh, Allah benar-benar Maha Mengetahui, Maha Melihat (keadaan) hamba-hamba-Nya"},{id:32,text:"\u062b\u064f\u0645\u0651\u064e \u0623\u064e\u0648\u06e1\u0631\u064e\u062b\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u0635\u06e1\u0637\u064e\u0641\u064e\u064a\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646\u06e1 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0646\u064e\u0627\u06d6 \u0641\u064e\u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0638\u064e\u0627\u0644\u0650\u0645\u065e \u0644\u0651\u0650\u0646\u064e\u0641\u06e1\u0633\u0650\u0647\u0650\u06e6 \u0648\u064e\u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064f\u0642\u06e1\u062a\u064e\u0635\u0650\u062f\u065e \u0648\u064e\u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0633\u064e\u0627\u0628\u0650\u0642\u064f\u06e2 \u0628\u0650\u0671\u0644\u06e1\u062e\u064e\u064a\u06e1\u0631\u064e\u0670\u062a\u0650 \u0628\u0650\u0625\u0650\u0630\u06e1\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0641\u064e\u0636\u06e1\u0644\u064f \u0671\u0644\u06e1\u0643\u064e\u0628\u0650\u064a\u0631\u064f",translation:"Kemudian Kitab itu Kami wariskan kepada orang-orang yang Kami pilih di antara hamba-hamba Kami, lalu di antara mereka ada yang menzalimi diri sendiri, ada yang pertengahan dan ada (pula) yang berlomba dalam berbuat kebaikan715) dengan izin Allah. Yang demikian itu adalah karunia yang besar"},{id:33,text:"\u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u064f \u0639\u064e\u062f\u06e1\u0646\u0656 \u064a\u064e\u062f\u06e1\u062e\u064f\u0644\u064f\u0648\u0646\u064e\u0647\u064e\u0627 \u064a\u064f\u062d\u064e\u0644\u0651\u064e\u0648\u06e1\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u0650\u0646\u06e1 \u0623\u064e\u0633\u064e\u0627\u0648\u0650\u0631\u064e \u0645\u0650\u0646 \u0630\u064e\u0647\u064e\u0628\u0656 \u0648\u064e\u0644\u064f\u0624\u06e1\u0644\u064f\u0624\u0657\u0627\u06d6 \u0648\u064e\u0644\u0650\u0628\u064e\u0627\u0633\u064f\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u062d\u064e\u0631\u0650\u064a\u0631\u065e",translation:"(Mereka akan mendapat) surga 'Adn, mereka masuk ke dalamnya, di dalamnya mereka diberi perhiasan gelang-gelang dari emas dan mutiara, dan pakaian mereka di dalamnya adalah sutera"},{id:34,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u062d\u064e\u0645\u06e1\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064e\u0630\u06e1\u0647\u064e\u0628\u064e \u0639\u064e\u0646\u0651\u064e\u0627 \u0671\u0644\u06e1\u062d\u064e\u0632\u064e\u0646\u064e\u06d6 \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0644\u064e\u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0634\u064e\u0643\u064f\u0648\u0631\u064c",translation:"Dan mereka berkata, \"Segala puji bagi Allah yang telah menghilangkan kesedihan dari kami. Sungguh, Tuhan kami benar-benar Maha Pengampun, Maha Mensyukuri"},{id:35,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064e\u062d\u064e\u0644\u0651\u064e\u0646\u064e\u0627 \u062f\u064e\u0627\u0631\u064e \u0671\u0644\u06e1\u0645\u064f\u0642\u064e\u0627\u0645\u064e\u0629\u0650 \u0645\u0650\u0646 \u0641\u064e\u0636\u06e1\u0644\u0650\u0647\u0650\u06e6 \u0644\u064e\u0627 \u064a\u064e\u0645\u064e\u0633\u0651\u064f\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0646\u064e\u0635\u064e\u0628\u065e \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0645\u064e\u0633\u0651\u064f\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0644\u064f\u063a\u064f\u0648\u0628\u065e",translation:"yang dengan karunia-Nya menempatkan kami dalam tempat yang kekal (surga); di dalamnya kami tidak merasa lelah dan tidak pula merasa lesu"},{id:36,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0646\u064e\u0627\u0631\u064f \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0644\u064e\u0627 \u064a\u064f\u0642\u06e1\u0636\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0641\u064e\u064a\u064e\u0645\u064f\u0648\u062a\u064f\u0648\u0627\u0652 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u062e\u064e\u0641\u0651\u064e\u0641\u064f \u0639\u064e\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u0650\u0647\u064e\u0627\u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u062c\u06e1\u0632\u0650\u064a \u0643\u064f\u0644\u0651\u064e \u0643\u064e\u0641\u064f\u0648\u0631\u0656",translation:"Dan orang-orang yang kafir, bagi mereka neraka Jahanam. Mereka tidak dibinasakan hingga mereka mati, dan tidak diringankan dari mereka azabnya. Demikianlah Kami membalas setiap orang yang sangat kafir"},{id:37,text:"\u0648\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0635\u06e1\u0637\u064e\u0631\u0650\u062e\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627\u0653 \u0623\u064e\u062e\u06e1\u0631\u0650\u062c\u06e1\u0646\u064e\u0627 \u0646\u064e\u0639\u06e1\u0645\u064e\u0644\u06e1 \u0635\u064e\u0670\u0644\u0650\u062d\u064b\u0627 \u063a\u064e\u064a\u06e1\u0631\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0643\u064f\u0646\u0651\u064e\u0627 \u0646\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u06da \u0623\u064e\u0648\u064e\u0644\u064e\u0645\u06e1 \u0646\u064f\u0639\u064e\u0645\u0651\u0650\u0631\u06e1\u0643\u064f\u0645 \u0645\u0651\u064e\u0627 \u064a\u064e\u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f \u0641\u0650\u064a\u0647\u0650 \u0645\u064e\u0646 \u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064e \u0648\u064e\u062c\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0646\u0651\u064e\u0630\u0650\u064a\u0631\u064f\u06d6 \u0641\u064e\u0630\u064f\u0648\u0642\u064f\u0648\u0627\u0652 \u0641\u064e\u0645\u064e\u0627 \u0644\u0650\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0646\u0651\u064e\u0635\u0650\u064a\u0631\u064d",translation:"Dan mereka berteriak di dalam neraka, \"Ya Tuhan kami, keluarkanlah kami (dari neraka), niscaya kami akan mengerjakan kebajikan, yang berlainan dengan yang telah kami kerjakan dahulu.\" (Dikatakan kepada mereka), \"Bukankah Kami telah memanjangkan umurmu untuk dapat berpikir bagi orang yang mau berpikir, padahal telah datang kepadamu seorang pemberi peringatan? Maka rasakanlah (azab Kami), dan bagi orang-orang zalim tidak ada seorang penolong pun"},{id:38,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0670\u0644\u0650\u0645\u064f \u063a\u064e\u064a\u06e1\u0628\u0650 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0639\u064e\u0644\u0650\u064a\u0645\u064f\u06e2 \u0628\u0650\u0630\u064e\u0627\u062a\u0650 \u0671\u0644\u0635\u0651\u064f\u062f\u064f\u0648\u0631\u0650",translation:"Sungguh, Allah mengetahui yang gaib (tersembunyi) di langit dan di bumi. Sungguh, Dia Maha Mengetahui segala isi hati"},{id:39,text:"\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0639\u064e\u0644\u064e\u0643\u064f\u0645\u06e1 \u062e\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0641\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06da \u0641\u064e\u0645\u064e\u0646 \u0643\u064e\u0641\u064e\u0631\u064e \u0641\u064e\u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0643\u064f\u0641\u06e1\u0631\u064f\u0647\u064f\u06e5\u06d6 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0632\u0650\u064a\u062f\u064f \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0643\u064f\u0641\u06e1\u0631\u064f\u0647\u064f\u0645\u06e1 \u0639\u0650\u0646\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0642\u06e1\u062a\u0657\u0627\u06d6 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0632\u0650\u064a\u062f\u064f \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0643\u064f\u0641\u06e1\u0631\u064f\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u062e\u064e\u0633\u064e\u0627\u0631\u0657\u0627",translation:"Dialah yang menjadikan kamu sebagai khalifah-khalifah di bumi. Barangsiapa kafir, maka (akibat) kekafirannya akan menimpa dirinya sendiri. Dan kekafiran orang-orang kafir itu hanya akan menambah kemurkaan di sisi Tuhan mereka. Dan kekafiran orang-orang kafir itu hanya akan menambah kerugian mereka belaka"},{id:40,text:"\u0642\u064f\u0644\u06e1 \u0623\u064e\u0631\u064e\u0621\u064e\u064a\u06e1\u062a\u064f\u0645\u06e1 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0631\u064f\u0648\u0646\u0650\u064a \u0645\u064e\u0627\u0630\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0623\u064e\u0645\u06e1 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0634\u0650\u0631\u06e1\u0643\u065e \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0623\u064e\u0645\u06e1 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0643\u0650\u062a\u064e\u0670\u0628\u0657\u0627 \u0641\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u062a\u0656 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u06da \u0628\u064e\u0644\u06e1 \u0625\u0650\u0646 \u064a\u064e\u0639\u0650\u062f\u064f \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u064f\u0648\u0646\u064e \u0628\u064e\u0639\u06e1\u0636\u064f\u0647\u064f\u0645 \u0628\u064e\u0639\u06e1\u0636\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u063a\u064f\u0631\u064f\u0648\u0631\u064b\u0627",translation:"Katakanlah, \"Terangkanlah olehmu tentang sekutu-sekutumu yang kamu seru selain Allah.\" Perlihatkanlah kepada-Ku (bagian) manakah dari bumi ini yang telah mereka ciptakan; ataukah mereka mempunyai peran serta dalam (penciptaan) langit; atau adakah Kami memberikan kitab kepada mereka sehingga mereka mendapat keterangan-keterangan yang jelas darinya? Sebenarnya orang-orang zalim itu, sebagian mereka hanya menjanjikan tipuan belaka kepada sebagian yang lain"},{id:41,text:"\u06de\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u0645\u06e1\u0633\u0650\u0643\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0623\u064e\u0646 \u062a\u064e\u0632\u064f\u0648\u0644\u064e\u0627\u06da \u0648\u064e\u0644\u064e\u0626\u0650\u0646 \u0632\u064e\u0627\u0644\u064e\u062a\u064e\u0627\u0653 \u0625\u0650\u0646\u06e1 \u0623\u064e\u0645\u06e1\u0633\u064e\u0643\u064e\u0647\u064f\u0645\u064e\u0627 \u0645\u0650\u0646\u06e1 \u0623\u064e\u062d\u064e\u062f\u0656 \u0645\u0651\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u0647\u0650\u06e6\u0653\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0643\u064e\u0627\u0646\u064e \u062d\u064e\u0644\u0650\u064a\u0645\u064b\u0627 \u063a\u064e\u0641\u064f\u0648\u0631\u0657\u0627",translation:"Sungguh, Allah yang menahan langit dan bumi agar tidak lenyap; dan jika keduanya akan lenyap tidak ada seorang pun yang mampu menahannya selain Allah. Sungguh, Dia Maha Penyantun, Maha Pengampun"},{id:42,text:"\u0648\u064e\u0623\u064e\u0642\u06e1\u0633\u064e\u0645\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062c\u064e\u0647\u06e1\u062f\u064e \u0623\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u0650\u0647\u0650\u0645\u06e1 \u0644\u064e\u0626\u0650\u0646 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u06e1 \u0646\u064e\u0630\u0650\u064a\u0631\u065e \u0644\u0651\u064e\u064a\u064e\u0643\u064f\u0648\u0646\u064f\u0646\u0651\u064e \u0623\u064e\u0647\u06e1\u062f\u064e\u0649\u0670 \u0645\u0650\u0646\u06e1 \u0625\u0650\u062d\u06e1\u062f\u064e\u0649 \u0671\u0644\u06e1\u0623\u064f\u0645\u064e\u0645\u0650\u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u06e1 \u0646\u064e\u0630\u0650\u064a\u0631\u065e \u0645\u0651\u064e\u0627 \u0632\u064e\u0627\u062f\u064e\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u0646\u064f\u0641\u064f\u0648\u0631\u064b\u0627",translation:"Dan mereka bersumpah atas nama Allah dengan sungguh-sungguh bahwa jika datang kepada mereka seorang pemberi peringatan, niscaya mereka akan lebih mendapat petunjuk daripada umat-umat (yang lain). Tetapi ketika pemberi peringatan datang kepada mereka, tidak menambah (apa-apa) kepada mereka, bahkan semakin jauh mereka dari (kebenaran)"},{id:43,text:"\u0671\u0633\u06e1\u062a\u0650\u0643\u06e1\u0628\u064e\u0627\u0631\u0657\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0645\u064e\u0643\u06e1\u0631\u064e \u0671\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u064a\u0655\u0650\u06da \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062d\u0650\u064a\u0642\u064f \u0671\u0644\u06e1\u0645\u064e\u0643\u06e1\u0631\u064f \u0671\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0626\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0623\u064e\u0647\u06e1\u0644\u0650\u0647\u0650\u06e6\u06da \u0641\u064e\u0647\u064e\u0644\u06e1 \u064a\u064e\u0646\u0638\u064f\u0631\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0633\u064f\u0646\u0651\u064e\u062a\u064e \u0671\u0644\u06e1\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e\u06da \u0641\u064e\u0644\u064e\u0646 \u062a\u064e\u062c\u0650\u062f\u064e \u0644\u0650\u0633\u064f\u0646\u0651\u064e\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064e\u0628\u06e1\u062f\u0650\u064a\u0644\u0657\u0627\u06d6 \u0648\u064e\u0644\u064e\u0646 \u062a\u064e\u062c\u0650\u062f\u064e \u0644\u0650\u0633\u064f\u0646\u0651\u064e\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064e\u062d\u06e1\u0648\u0650\u064a\u0644\u064b\u0627",translation:"karena kesombongan (mereka) di bumi dan karena rencana (mereka) yang jahat. Rencana yang jahat itu hanya akan menimpa pencetus rencananya sendiri. Mereka hanyalah menunggu (berlakunya) ketentuan pada orang-orang yang terdahulu.716) Maka kamu tidak akan mendapatkan perubahan bagi Allah, dan tidak (pula) akan menemui penyimpangan bagi ketentuan Allah"},{id:44,text:"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0633\u0650\u064a\u0631\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0641\u064e\u064a\u064e\u0646\u0638\u064f\u0631\u064f\u0648\u0627\u0652 \u0643\u064e\u064a\u06e1\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0670\u0642\u0650\u0628\u064e\u0629\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0634\u064e\u062f\u0651\u064e \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0642\u064f\u0648\u0651\u064e\u0629\u0657\u06da \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u064a\u064f\u0639\u06e1\u062c\u0650\u0632\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0644\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u0657\u0627 \u0642\u064e\u062f\u0650\u064a\u0631\u0657\u0627",translation:"Dan tidakkah mereka bepergian di bumi lalu melihat bagaimana kesudahan orang-orang sebelum mereka (yang mendustakan rasul), padahal orang-orang itu lebih besar kekuatannya dari mereka? Dan tidak ada sesuatu pun yang dapat melemahkan Allah baik di langit maupun di bumi. Sungguh, Dia Maha Mengetahui, Mahakuasa"},{id:45,text:"\u0648\u064e\u0644\u064e\u0648\u06e1 \u064a\u064f\u0624\u064e\u0627\u062e\u0650\u0630\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u062a\u064e\u0631\u064e\u0643\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0638\u064e\u0647\u06e1\u0631\u0650\u0647\u064e\u0627 \u0645\u0650\u0646 \u062f\u064e\u0627\u0653\u0628\u0651\u064e\u0629\u0656 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u064a\u064f\u0624\u064e\u062e\u0651\u0650\u0631\u064f\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u062c\u064e\u0644\u0656 \u0645\u0651\u064f\u0633\u064e\u0645\u0651\u0657\u0649\u06d6 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e \u0623\u064e\u062c\u064e\u0644\u064f\u0647\u064f\u0645\u06e1 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0628\u0650\u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650\u06e6 \u0628\u064e\u0635\u0650\u064a\u0631\u064e\u06e2\u0627",translation:"Dan sekiranya Allah menghukum manusia disebabkan apa yang telah mereka perbuat, niscaya Dia tidak akan menyisakan satu pun makhluk bergerak yang bernyawa di bumi ini, tetapi Dia menangguhkan (hukuman)-nya, sampai waktu yang sudah ditentukan. Nanti apabila ajal mereka tiba, maka Allah Maha Melihat (keadaan) hamba-hamba-Nya"}]},{id:36,name:"\u064a\u0633",transliteration:"Ya-Sin",translation:"Yas Sin",type:"meccan",total_verses:83,verses:[{id:1,text:"\u064a\u0633\u0653",translation:"Y\u0101 S\u012bn"},{id:2,text:"\u0648\u064e\u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u0650 \u0671\u0644\u06e1\u062d\u064e\u0643\u0650\u064a\u0645\u0650",translation:"Demi Alquran yang penuh hikmah"},{id:3,text:"\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0631\u06e1\u0633\u064e\u0644\u0650\u064a\u0646\u064e",translation:"sungguh, engkau (Muhammad) adalah salah seorang dari rasul-rasul"},{id:4,text:"\u0639\u064e\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0670\u0637\u0656 \u0645\u0651\u064f\u0633\u06e1\u062a\u064e\u0642\u0650\u064a\u0645\u0656",translation:"(yang berada) di atas jalan yang lurus"},{id:5,text:"\u062a\u064e\u0646\u0632\u0650\u064a\u0644\u064e \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u0650 \u0671\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650",translation:"(sebagai wahyu) yang diturunkan oleh (Allah) Yang Mahaperkasa, Maha Penyayang"},{id:6,text:"\u0644\u0650\u062a\u064f\u0646\u0630\u0650\u0631\u064e \u0642\u064e\u0648\u06e1\u0645\u0657\u0627 \u0645\u0651\u064e\u0627\u0653 \u0623\u064f\u0646\u0630\u0650\u0631\u064e \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0624\u064f\u0647\u064f\u0645\u06e1 \u0641\u064e\u0647\u064f\u0645\u06e1 \u063a\u064e\u0670\u0641\u0650\u0644\u064f\u0648\u0646\u064e",translation:"agar engkau memberi peringatan kepada suatu kaum yang nenek moyangnya belum pernah diberi peringatan, karena itu mereka lalai"},{id:7,text:"\u0644\u064e\u0642\u064e\u062f\u06e1 \u062d\u064e\u0642\u0651\u064e \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0644\u064f \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u0650\u0647\u0650\u0645\u06e1 \u0641\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Sungguh, pasti berlaku perkataan (hukuman) terhadap kebanyakan mereka, karena mereka tidak beriman"},{id:8,text:"\u0625\u0650\u0646\u0651\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a\u0653 \u0623\u064e\u0639\u06e1\u0646\u064e\u0670\u0642\u0650\u0647\u0650\u0645\u06e1 \u0623\u064e\u063a\u06e1\u0644\u064e\u0670\u0644\u0657\u0627 \u0641\u064e\u0647\u0650\u064a\u064e \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u0623\u064e\u0630\u06e1\u0642\u064e\u0627\u0646\u0650 \u0641\u064e\u0647\u064f\u0645 \u0645\u0651\u064f\u0642\u06e1\u0645\u064e\u062d\u064f\u0648\u0646\u064e",translation:"Sungguh, Kami telah memasang belenggu di leher mereka, lalu tangan mereka (diangkat) ke dagu, karena itu mereka tertengadah"},{id:9,text:"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646\u06e2 \u0628\u064e\u064a\u06e1\u0646\u0650 \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u0647\u0650\u0645\u06e1 \u0633\u064e\u062f\u0651\u0657\u0627 \u0648\u064e\u0645\u0650\u0646\u06e1 \u062e\u064e\u0644\u06e1\u0641\u0650\u0647\u0650\u0645\u06e1 \u0633\u064e\u062f\u0651\u0657\u0627 \u0641\u064e\u0623\u064e\u063a\u06e1\u0634\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0641\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064f\u0628\u06e1\u0635\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Dan Kami jadikan di hadapan mereka sekat (dinding) dan di belakang mereka juga sekat, dan Kami tutup (mata) mereka sehingga mereka tidak dapat melihat"},{id:10,text:"\u0648\u064e\u0633\u064e\u0648\u064e\u0627\u0653\u0621\u064c \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0621\u064e\u0623\u064e\u0646\u0630\u064e\u0631\u06e1\u062a\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u0645\u06e1 \u0644\u064e\u0645\u06e1 \u062a\u064f\u0646\u0630\u0650\u0631\u06e1\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Dan sama saja bagi mereka, apakah engkau memberi peringatan kepada mereka atau engkau tidak memberi peringatan kepada mereka, mereka tidak akan beriman juga"},{id:11,text:"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u062a\u064f\u0646\u0630\u0650\u0631\u064f \u0645\u064e\u0646\u0650 \u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064e \u0671\u0644\u0630\u0651\u0650\u0643\u06e1\u0631\u064e \u0648\u064e\u062e\u064e\u0634\u0650\u064a\u064e \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u064e \u0628\u0650\u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u0628\u0650\u06d6 \u0641\u064e\u0628\u064e\u0634\u0651\u0650\u0631\u06e1\u0647\u064f \u0628\u0650\u0645\u064e\u063a\u06e1\u0641\u0650\u0631\u064e\u0629\u0656 \u0648\u064e\u0623\u064e\u062c\u06e1\u0631\u0656 \u0643\u064e\u0631\u0650\u064a\u0645\u064d",translation:"(Sesungguhnya engkau hanya memberi peringatan kepada orang-orang yang mau mengikuti peringatan717) dan yang takut kepada Tuhan Yang Maha Pengasih, walaupun mereka tidak melihat-Nya. Maka berilah mereka kabar gembira dengan ampunan dan pahala yang mulia"},{id:12,text:"\u0625\u0650\u0646\u0651\u064e\u0627 \u0646\u064e\u062d\u06e1\u0646\u064f \u0646\u064f\u062d\u06e1\u064a\u0650 \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u064e\u0649\u0670 \u0648\u064e\u0646\u064e\u0643\u06e1\u062a\u064f\u0628\u064f \u0645\u064e\u0627 \u0642\u064e\u062f\u0651\u064e\u0645\u064f\u0648\u0627\u0652 \u0648\u064e\u0621\u064e\u0627\u062b\u064e\u0670\u0631\u064e\u0647\u064f\u0645\u06e1\u06da \u0648\u064e\u0643\u064f\u0644\u0651\u064e \u0634\u064e\u064a\u06e1\u0621\u064d \u0623\u064e\u062d\u06e1\u0635\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f \u0641\u0650\u064a\u0653 \u0625\u0650\u0645\u064e\u0627\u0645\u0656 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u0656",translation:"Sungguh, Kamilah yang menghidupkan orang-orang yang mati, dan Kamilah yang mencatat apa yang telah mereka kerjakan dan bekas-bekas yang mereka (tinggalkan). Dan segala sesuatu Kami kumpulkan dalam Kitab yang jelas (Lau\u1e25 Ma\u1e25f\u016b\u1e93)"},{id:13,text:"\u0648\u064e\u0671\u0636\u06e1\u0631\u0650\u0628\u06e1 \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u062b\u064e\u0644\u064b\u0627 \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064e \u0671\u0644\u06e1\u0642\u064e\u0631\u06e1\u064a\u064e\u0629\u0650 \u0625\u0650\u0630\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064e\u0627 \u0671\u0644\u06e1\u0645\u064f\u0631\u06e1\u0633\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan buatlah suatu perumpamaan bagi mereka, yaitu penduduk suatu negeri, ketika utusan-utusan datang kepada mereka"},{id:14,text:"\u0625\u0650\u0630\u06e1 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u064f \u0671\u062b\u06e1\u0646\u064e\u064a\u06e1\u0646\u0650 \u0641\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0647\u064f\u0645\u064e\u0627 \u0641\u064e\u0639\u064e\u0632\u0651\u064e\u0632\u06e1\u0646\u064e\u0627 \u0628\u0650\u062b\u064e\u0627\u0644\u0650\u062b\u0656 \u0641\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064f\u0645 \u0645\u0651\u064f\u0631\u06e1\u0633\u064e\u0644\u064f\u0648\u0646\u064e",translation:"(yaitu) ketika Kami mengutus kepada mereka dua orang utusan, lalu mereka mendustakan keduanya; kemudian Kami kuatkan dengan (utusan) yang ketiga, maka ketiga (utusan itu) berkata, \"Sungguh, kami adalah orang-orang yang diutus kepadamu"},{id:15,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u064e\u0634\u064e\u0631\u065e \u0645\u0651\u0650\u062b\u06e1\u0644\u064f\u0646\u064e\u0627 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u064f \u0645\u0650\u0646 \u0634\u064e\u064a\u06e1\u0621\u064d \u0625\u0650\u0646\u06e1 \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u062a\u064e\u0643\u06e1\u0630\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Mereka (penduduk negeri) menjawab, \"Kamu ini hanyalah manusia seperti kami, dan (Allah) Yang Maha Pengasih tidak menurunkan sesuatu apa pun; kamu hanyalah pendusta belaka"},{id:16,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0631\u064e\u0628\u0651\u064f\u0646\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0644\u064e\u0645\u064f\u0631\u06e1\u0633\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Mereka berkata, \"Tuhan kami mengetahui sesungguhnya kami adalah utusan-utusan (-Nya) kepada kamu"},{id:17,text:"\u0648\u064e\u0645\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u06e1\u0628\u064e\u0644\u064e\u0670\u063a\u064f \u0671\u0644\u06e1\u0645\u064f\u0628\u0650\u064a\u0646\u064f",translation:"Dan kewajiban kami hanyalah meyampaikan (perintah Allah) dengan jelas"},{id:18,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e\u0627 \u062a\u064e\u0637\u064e\u064a\u0651\u064e\u0631\u06e1\u0646\u064e\u0627 \u0628\u0650\u0643\u064f\u0645\u06e1\u06d6 \u0644\u064e\u0626\u0650\u0646 \u0644\u0651\u064e\u0645\u06e1 \u062a\u064e\u0646\u062a\u064e\u0647\u064f\u0648\u0627\u0652 \u0644\u064e\u0646\u064e\u0631\u06e1\u062c\u064f\u0645\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u064a\u064e\u0645\u064e\u0633\u0651\u064e\u0646\u0651\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u0651\u064e\u0627 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Mereka menjawab, \"Sesungguhnya kami bernasib malang karena kamu. Sungguh, jika kamu tidak berhenti (menyeru kami), niscaya kami rajam kamu dan kamu pasti akan merasakan siksaan yang pedih dari kami"},{id:19,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0637\u064e\u0640\u0670\u0653\u0626\u0650\u0631\u064f\u0643\u064f\u0645 \u0645\u0651\u064e\u0639\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u0626\u0650\u0646 \u0630\u064f\u0643\u0651\u0650\u0631\u06e1\u062a\u064f\u0645\u06da \u0628\u064e\u0644\u06e1 \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0642\u064e\u0648\u06e1\u0645\u065e \u0645\u0651\u064f\u0633\u06e1\u0631\u0650\u0641\u064f\u0648\u0646\u064e",translation:"Mereka (utusan-utusan) itu berkata, \"Kemalangan kamu itu adalah karena kamu sendiri. Apakah kamu diberi peringatan? Sebenarnya kamu adalah kaum yang melampaui batas"},{id:20,text:"\u0648\u064e\u062c\u064e\u0627\u0653\u0621\u064e \u0645\u0650\u0646\u06e1 \u0623\u064e\u0642\u06e1\u0635\u064e\u0627 \u0671\u0644\u06e1\u0645\u064e\u062f\u0650\u064a\u0646\u064e\u0629\u0650 \u0631\u064e\u062c\u064f\u0644\u065e \u064a\u064e\u0633\u06e1\u0639\u064e\u0649\u0670 \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0645\u064f\u0631\u06e1\u0633\u064e\u0644\u0650\u064a\u0646\u064e",translation:"(Dan datanglah dari ujung kota, seorang laki-laki718) dengan bergegas dia berkata, \"Wahai kaumku! Ikutilah utusan-utusan itu"},{id:21,text:"\u0671\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0627\u0652 \u0645\u064e\u0646 \u0644\u0651\u064e\u0627 \u064a\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0643\u064f\u0645\u06e1 \u0623\u064e\u062c\u06e1\u0631\u0657\u0627 \u0648\u064e\u0647\u064f\u0645 \u0645\u0651\u064f\u0647\u06e1\u062a\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Ikutilah orang yang tidak meminta imbalan kepadamu; dan mereka adalah orang-orang yang mendapat petunjuk"},{id:22,text:"\u0648\u064e\u0645\u064e\u0627\u0644\u0650\u064a\u064e \u0644\u064e\u0627\u0653 \u0623\u064e\u0639\u06e1\u0628\u064f\u062f\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0641\u064e\u0637\u064e\u0631\u064e\u0646\u0650\u064a \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u062a\u064f\u0631\u06e1\u062c\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Dan tidak ada alasan bagiku untuk tidak menyembah (Allah) yang telah menciptakanku dan hanya kepada-Nyalah kamu akan dikembalikan"},{id:23,text:"\u0621\u064e\u0623\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u06e6\u0653 \u0621\u064e\u0627\u0644\u0650\u0647\u064e\u0629\u064b \u0625\u0650\u0646 \u064a\u064f\u0631\u0650\u062f\u06e1\u0646\u0650 \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u064f \u0628\u0650\u0636\u064f\u0631\u0651\u0656 \u0644\u0651\u064e\u0627 \u062a\u064f\u063a\u06e1\u0646\u0650 \u0639\u064e\u0646\u0651\u0650\u064a \u0634\u064e\u0641\u064e\u0670\u0639\u064e\u062a\u064f\u0647\u064f\u0645\u06e1 \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0646\u0642\u0650\u0630\u064f\u0648\u0646\u0650",translation:"Mengapa aku akan menyembah tuhan-tuhan selain-Nya? Jika (Allah) Yang Maha Pengasih menghendaki bencana terhadapku, pasti pertolongan mereka tidak berguna sama sekali bagi diriku dan mereka (juga) tidak dapat menyelamatkanku"},{id:24,text:"\u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0625\u0650\u0630\u0657\u0627 \u0644\u0651\u064e\u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0670\u0644\u0656 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u064d",translation:"Sesungguhnya jika aku (berbuat) begitu, pasti aku berada dalam kesesatan yang nyata"},{id:25,text:"\u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0621\u064e\u0627\u0645\u064e\u0646\u062a\u064f \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1 \u0641\u064e\u0671\u0633\u06e1\u0645\u064e\u0639\u064f\u0648\u0646\u0650",translation:"Sesungguhnya aku telah beriman kepada Tuhanmu; maka dengarkanlah (pengakuan keimanan)ku"},{id:26,text:"\u0642\u0650\u064a\u0644\u064e \u0671\u062f\u06e1\u062e\u064f\u0644\u0650 \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u064e\u06d6 \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0670\u0644\u064e\u064a\u06e1\u062a\u064e \u0642\u064e\u0648\u06e1\u0645\u0650\u064a \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dikatakan (kepadanya), \"Masuklah ke surga.\"719) Dia (laki-laki itu) berkata, \"Alangkah baiknya sekiranya kaumku mengetahui"},{id:27,text:"\u0628\u0650\u0645\u064e\u0627 \u063a\u064e\u0641\u064e\u0631\u064e \u0644\u0650\u064a \u0631\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e\u0646\u0650\u064a \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0643\u06e1\u0631\u064e\u0645\u0650\u064a\u0646\u064e",translation:"apa yang menyebabkan Tuhanku memberi ampun kepadaku dan menjadikan aku termasuk orang-orang yang telah dimuliakan"},{id:28,text:"\u06de\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u06e6 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u0647\u0650\u06e6 \u0645\u0650\u0646 \u062c\u064f\u0646\u062f\u0656 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0645\u064f\u0646\u0632\u0650\u0644\u0650\u064a\u0646\u064e",translation:"Dan setelah dia (meninggal), Kami tidak menurunkan suatu pasukan pun dari langit kepada kaumnya, dan Kami tidak perlu menurunkannya"},{id:29,text:"\u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064e\u062a\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u0635\u064e\u064a\u06e1\u062d\u064e\u0629\u0657 \u0648\u064e\u0670\u062d\u0650\u062f\u064e\u0629\u0657 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0645\u06e1 \u062e\u064e\u0670\u0645\u0650\u062f\u064f\u0648\u0646\u064e",translation:"Tidak ada siksaan terhadap mereka melainkan dengan satu teriakan saja; maka seketika itu mereka mati"},{id:30,text:"\u064a\u064e\u0670\u062d\u064e\u0633\u06e1\u0631\u064e\u0629\u064b \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0639\u0650\u0628\u064e\u0627\u062f\u0650\u06da \u0645\u064e\u0627 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u0647\u0650\u0645 \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6 \u064a\u064e\u0633\u06e1\u062a\u064e\u0647\u06e1\u0632\u0650\u0621\u064f\u0648\u0646\u064e",translation:"Alangkah besar penyesalan terhadap hamba-hamba itu, setiap datang seorang rasul kepada mereka, mereka selalu memperolok-olokkannya"},{id:31,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0631\u064e\u0648\u06e1\u0627\u0652 \u0643\u064e\u0645\u06e1 \u0623\u064e\u0647\u06e1\u0644\u064e\u0643\u06e1\u0646\u064e\u0627 \u0642\u064e\u0628\u06e1\u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0642\u064f\u0631\u064f\u0648\u0646\u0650 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0631\u06e1\u062c\u0650\u0639\u064f\u0648\u0646\u064e",translation:"Tidakkah mereka mengetahui berapa banyak umat-umat sebelum mereka yang telah Kami binasakan. Orang-orang (yang telah Kami binasakan) itu tidak ada yang kembali kepada mereka"},{id:32,text:"\u0648\u064e\u0625\u0650\u0646 \u0643\u064f\u0644\u0651\u065e \u0644\u0651\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0645\u0650\u064a\u0639\u065e \u0644\u0651\u064e\u062f\u064e\u064a\u06e1\u0646\u064e\u0627 \u0645\u064f\u062d\u06e1\u0636\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan setiap (umat), semuanya akan dihadapkan kepada Kami"},{id:33,text:"\u0648\u064e\u0621\u064e\u0627\u064a\u064e\u0629\u065e \u0644\u0651\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064f \u0671\u0644\u06e1\u0645\u064e\u064a\u06e1\u062a\u064e\u0629\u064f \u0623\u064e\u062d\u06e1\u064a\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064e\u0627 \u0648\u064e\u0623\u064e\u062e\u06e1\u0631\u064e\u062c\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u062d\u064e\u0628\u0651\u0657\u0627 \u0641\u064e\u0645\u0650\u0646\u06e1\u0647\u064f \u064a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f\u0648\u0646\u064e",translation:"Dan suatu tanda (kebesaran Allah) bagi mereka adalah bumi yang mati (tandus). Kami hidupkan bumi itu dan Kami keluarkan darinya biji-bijian, maka dari (biji-bijian) itu mereka makan"},{id:34,text:"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0656 \u0645\u0651\u0650\u0646 \u0646\u0651\u064e\u062e\u0650\u064a\u0644\u0656 \u0648\u064e\u0623\u064e\u0639\u06e1\u0646\u064e\u0670\u0628\u0656 \u0648\u064e\u0641\u064e\u062c\u0651\u064e\u0631\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0639\u064f\u064a\u064f\u0648\u0646\u0650",translation:"Dan Kami jadikan padanya di bumi itu kebun-kebun kurma dan anggur dan Kami pancarkan padanya beberapa mata air"},{id:35,text:"\u0644\u0650\u064a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u062b\u064e\u0645\u064e\u0631\u0650\u0647\u0650\u06e6 \u0648\u064e\u0645\u064e\u0627 \u0639\u064e\u0645\u0650\u0644\u064e\u062a\u06e1\u0647\u064f \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u0647\u0650\u0645\u06e1\u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0634\u06e1\u0643\u064f\u0631\u064f\u0648\u0646\u064e",translation:"agar mereka dapat makan dari buahnya, dan dari hasil usaha tangan mereka. Maka mengapa mereka tidak bersyukur"},{id:36,text:"\u0633\u064f\u0628\u06e1\u062d\u064e\u0670\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u06e1\u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u064e \u0643\u064f\u0644\u0651\u064e\u0647\u064e\u0627 \u0645\u0650\u0645\u0651\u064e\u0627 \u062a\u064f\u0646\u06e2\u0628\u0650\u062a\u064f \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064f \u0648\u064e\u0645\u0650\u0646\u06e1 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0645\u0650\u0645\u0651\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Mahasuci (Allah) yang telah menciptakan semuanya berpasang-pasangan, baik dari apa yang ditumbuhkan oleh bumi dan dari diri mereka sendiri, maupun dari apa yang tidak mereka ketahui"},{id:37,text:"\u0648\u064e\u0621\u064e\u0627\u064a\u064e\u0629\u065e \u0644\u0651\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u064f \u0646\u064e\u0633\u06e1\u0644\u064e\u062e\u064f \u0645\u0650\u0646\u06e1\u0647\u064f \u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0645 \u0645\u0651\u064f\u0638\u06e1\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Dan suatu tanda (kebesaran Allah) bagi mereka adalah malam; Kami tanggalkan siang dari (malam) itu, maka seketika itu mereka (berada dalam) kegelapan"},{id:38,text:"\u0648\u064e\u0671\u0644\u0634\u0651\u064e\u0645\u06e1\u0633\u064f \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0644\u0650\u0645\u064f\u0633\u06e1\u062a\u064e\u0642\u064e\u0631\u0651\u0656 \u0644\u0651\u064e\u0647\u064e\u0627\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062a\u064e\u0642\u06e1\u062f\u0650\u064a\u0631\u064f \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u0650 \u0671\u0644\u06e1\u0639\u064e\u0644\u0650\u064a\u0645\u0650",translation:"dan matahari berjalan di tempat peredarannya. Demikianlah ketetapan (Allah) Yang Mahaperkasa, Maha Mengetahui"},{id:39,text:"\u0648\u064e\u0671\u0644\u06e1\u0642\u064e\u0645\u064e\u0631\u064e \u0642\u064e\u062f\u0651\u064e\u0631\u06e1\u0646\u064e\u0670\u0647\u064f \u0645\u064e\u0646\u064e\u0627\u0632\u0650\u0644\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0639\u064e\u0627\u062f\u064e \u0643\u064e\u0671\u0644\u06e1\u0639\u064f\u0631\u06e1\u062c\u064f\u0648\u0646\u0650 \u0671\u0644\u06e1\u0642\u064e\u062f\u0650\u064a\u0645\u0650",translation:"Dan telah Kami tetapkan tempat peredaran bagi bulan, sehingga (setelah ia sampai ke tempat peredaran yang terakhir) kembalilah ia seperti bentuk tandan yang tua"},{id:40,text:"\u0644\u064e\u0627 \u0671\u0644\u0634\u0651\u064e\u0645\u06e1\u0633\u064f \u064a\u064e\u0646\u06e2\u0628\u064e\u063a\u0650\u064a \u0644\u064e\u0647\u064e\u0627\u0653 \u0623\u064e\u0646 \u062a\u064f\u062f\u06e1\u0631\u0650\u0643\u064e \u0671\u0644\u06e1\u0642\u064e\u0645\u064e\u0631\u064e \u0648\u064e\u0644\u064e\u0627 \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u064f \u0633\u064e\u0627\u0628\u0650\u0642\u064f \u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650\u06da \u0648\u064e\u0643\u064f\u0644\u0651\u065e \u0641\u0650\u064a \u0641\u064e\u0644\u064e\u0643\u0656 \u064a\u064e\u0633\u06e1\u0628\u064e\u062d\u064f\u0648\u0646\u064e",translation:"Tidaklah mungkin bagi matahari mengejar bulan dan malam pun tidak dapat mendahului siang. Masing-masing beredar pada garis edarnya"},{id:41,text:"\u0648\u064e\u0621\u064e\u0627\u064a\u064e\u0629\u065e \u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u0646\u0651\u064e\u0627 \u062d\u064e\u0645\u064e\u0644\u06e1\u0646\u064e\u0627 \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u062a\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0641\u064f\u0644\u06e1\u0643\u0650 \u0671\u0644\u06e1\u0645\u064e\u0634\u06e1\u062d\u064f\u0648\u0646\u0650",translation:"Dan suatu tanda (kebesaran Allah) bagi mereka adalah bahwa Kami angkut keturunan mereka dalam kapal yang penuh muatan"},{id:42,text:"\u0648\u064e\u062e\u064e\u0644\u064e\u0642\u06e1\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0645\u0651\u0650\u062b\u06e1\u0644\u0650\u0647\u0650\u06e6 \u0645\u064e\u0627 \u064a\u064e\u0631\u06e1\u0643\u064e\u0628\u064f\u0648\u0646\u064e",translation:"dan Kami ciptakan (juga) untuk mereka (angkutan lain) seperti apa yang mereka kendarai"},{id:43,text:"\u0648\u064e\u0625\u0650\u0646 \u0646\u0651\u064e\u0634\u064e\u0623\u06e1 \u0646\u064f\u063a\u06e1\u0631\u0650\u0642\u06e1\u0647\u064f\u0645\u06e1 \u0641\u064e\u0644\u064e\u0627 \u0635\u064e\u0631\u0650\u064a\u062e\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u06e1 \u064a\u064f\u0646\u0642\u064e\u0630\u064f\u0648\u0646\u064e",translation:"Dan jika Kami menghendaki, Kami tenggelamkan mereka. Maka tidak ada penolong bagi mereka dan tidak (pula) mereka diselamatkan"},{id:44,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u0657 \u0645\u0651\u0650\u0646\u0651\u064e\u0627 \u0648\u064e\u0645\u064e\u062a\u064e\u0670\u0639\u064b\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u062d\u0650\u064a\u0646\u0656",translation:"melainkan (Kami selamatkan mereka) karena rahmat yang besar dari Kami dan untuk memberikan kesenangan hidup sampai waktu tertentu"},{id:45,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u0643\u064f\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u06e1\u0641\u064e\u0643\u064f\u0645\u06e1 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064f\u0631\u06e1\u062d\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan apabila dikatakan kepada mereka, \"Takutlah kamu akan siksa yang dihadapanmu (di dunia) dan azab yang akan datang (akhirat) agar kamu mendapat rahmat"},{id:46,text:"\u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0623\u06e1\u062a\u0650\u064a\u0647\u0650\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0621\u064e\u0627\u064a\u064e\u0629\u0656 \u0645\u0651\u0650\u0646\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0639\u064e\u0646\u06e1\u0647\u064e\u0627 \u0645\u064f\u0639\u06e1\u0631\u0650\u0636\u0650\u064a\u0646\u064e",translation:"Dan setiap kali suatu tanda dari tanda-tanda (kebesaran) Tuhan datang kepada mereka, mereka selalu berpaling darinya"},{id:47,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u0646\u0641\u0650\u0642\u064f\u0648\u0627\u0652 \u0645\u0650\u0645\u0651\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u064f\u0637\u06e1\u0639\u0650\u0645\u064f \u0645\u064e\u0646 \u0644\u0651\u064e\u0648\u06e1 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0637\u06e1\u0639\u064e\u0645\u064e\u0647\u064f\u06e5\u0653 \u0625\u0650\u0646\u06e1 \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0670\u0644\u0656 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u0656",translation:"Dan apabila dikatakan kepada mereka, \"Infakkanlah sebagian rezeki yang diberikan Allah kepadamu,\" orang-orang yang kafir itu berkata kepada orang-orang yang beriman, \"Apakah pantas kami memberi makan kepada orang-orang yang jika Allah menghendaki Dia akan memberinya makan? Kamu benar-benar dalam kesesatan yang nyata"},{id:48,text:"\u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0645\u064e\u062a\u064e\u0649\u0670 \u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u06e1\u0648\u064e\u0639\u06e1\u062f\u064f \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0635\u064e\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Dan mereka (orang-orang kafir) berkata, \"Kapan janji (hari berbangkit) itu (terjadi) jika kamu orang-orang yang benar"},{id:49,text:"\u0645\u064e\u0627 \u064a\u064e\u0646\u0638\u064f\u0631\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0635\u064e\u064a\u06e1\u062d\u064e\u0629\u0657 \u0648\u064e\u0670\u062d\u0650\u062f\u064e\u0629\u0657 \u062a\u064e\u0623\u06e1\u062e\u064f\u0630\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u062e\u0650\u0635\u0651\u0650\u0645\u064f\u0648\u0646\u064e",translation:"(Mereka hanya menunggu satu teriakan,723) yang akan membinasakan mereka ketika mereka sedang bertengkar"},{id:50,text:"\u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u064e \u062a\u064e\u0648\u06e1\u0635\u0650\u064a\u064e\u0629\u0657 \u0648\u064e\u0644\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0647\u06e1\u0644\u0650\u0647\u0650\u0645\u06e1 \u064a\u064e\u0631\u06e1\u062c\u0650\u0639\u064f\u0648\u0646\u064e",translation:"Sehingga mereka tidak mampu membuat suatu wasiat dan mereka (juga) tidak dapat kembali kepada keluarganya"},{id:51,text:"\u0648\u064e\u0646\u064f\u0641\u0650\u062e\u064e \u0641\u0650\u064a \u0671\u0644\u0635\u0651\u064f\u0648\u0631\u0650 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u062c\u06e1\u062f\u064e\u0627\u062b\u0650 \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u064a\u064e\u0646\u0633\u0650\u0644\u064f\u0648\u0646\u064e",translation:"(Lalu ditiuplah sangkakala,724) maka seketika itu mereka keluar dari kuburnya (dalam keadaan hidup), menuju kepada Tuhannya"},{id:52,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u064a\u064e\u0670\u0648\u064e\u064a\u06e1\u0644\u064e\u0646\u064e\u0627 \u0645\u064e\u0646\u06e2 \u0628\u064e\u0639\u064e\u062b\u064e\u0646\u064e\u0627 \u0645\u0650\u0646 \u0645\u0651\u064e\u0631\u06e1\u0642\u064e\u062f\u0650\u0646\u064e\u0627\u06dc\u06d7 \u0647\u064e\u0670\u0630\u064e\u0627 \u0645\u064e\u0627 \u0648\u064e\u0639\u064e\u062f\u064e \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u064f \u0648\u064e\u0635\u064e\u062f\u064e\u0642\u064e \u0671\u0644\u06e1\u0645\u064f\u0631\u06e1\u0633\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Mereka berkata, \"Celakalah kami! Siapakah yang membangkitkan kami dari tempat tidur kami (kubur)?\" Inilah yang dijanjikan (Allah) Yang Maha Pengasih dan benarlah rasul-rasul(-Nya)"},{id:53,text:"\u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064e\u062a\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u0635\u064e\u064a\u06e1\u062d\u064e\u0629\u0657 \u0648\u064e\u0670\u062d\u0650\u062f\u064e\u0629\u0657 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0645\u06e1 \u062c\u064e\u0645\u0650\u064a\u0639\u065e \u0644\u0651\u064e\u062f\u064e\u064a\u06e1\u0646\u064e\u0627 \u0645\u064f\u062d\u06e1\u0636\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Teriakan itu hanya sekali saja, maka seketika itu mereka semua dihadapkan kepada Kami (untuk dihisab)"},{id:54,text:"\u0641\u064e\u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e \u0644\u064e\u0627 \u062a\u064f\u0638\u06e1\u0644\u064e\u0645\u064f \u0646\u064e\u0641\u06e1\u0633\u065e \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u062c\u06e1\u0632\u064e\u0648\u06e1\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Maka pada hari itu seseorang tidak akan dirugikan sedikit pun dan kamu tidak akan diberi balasan, kecuali sesuai dengan apa yang telah kamu kerjakan"},{id:55,text:"\u0625\u0650\u0646\u0651\u064e \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064e \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e \u0641\u0650\u064a \u0634\u064f\u063a\u064f\u0644\u0656 \u0641\u064e\u0670\u0643\u0650\u0647\u064f\u0648\u0646\u064e",translation:"Sesungguhnya penghuni surga pada hari itu bersenang-senang dalam kesibukan (mereka)"},{id:56,text:"\u0647\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u064f\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0638\u0650\u0644\u064e\u0670\u0644\u064d \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0623\u064e\u0631\u064e\u0627\u0653\u0626\u0650\u0643\u0650 \u0645\u064f\u062a\u0651\u064e\u0643\u0650\u0640\u0654\u064f\u0648\u0646\u064e",translation:"Mereka dan pasangan-pasangannya berada dalam tempat yang teduh, bersandar di atas dipan-dipan"},{id:57,text:"\u0644\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u0641\u064e\u0670\u0643\u0650\u0647\u064e\u0629\u065e \u0648\u064e\u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u0627 \u064a\u064e\u062f\u0651\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Di surga itu mereka memperoleh buah-buahan dan memperoleh apa saja yang mereka inginkan"},{id:58,text:"\u0633\u064e\u0644\u064e\u0670\u0645\u065e \u0642\u064e\u0648\u06e1\u0644\u0657\u0627 \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0656 \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0656",translation:"(Kepada mereka dikatakan), \"Sal\u0101m,\" sebagai ucapan selamat dari Tuhan Yang Maha Penyayang"},{id:59,text:"\u0648\u064e\u0671\u0645\u06e1\u062a\u064e\u0670\u0632\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u06e1\u0645\u064f\u062c\u06e1\u0631\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Dan (dikatakan kepada orang-orang kafir), \"Berpisahlah kamu (dari orang-orang mukmin) pada hari ini, wahai orang-orang yang berdosa"},{id:60,text:"\u06de\u0623\u064e\u0644\u064e\u0645\u06e1 \u0623\u064e\u0639\u06e1\u0647\u064e\u062f\u06e1 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u064a\u064e\u0670\u0628\u064e\u0646\u0650\u064a\u0653 \u0621\u064e\u0627\u062f\u064e\u0645\u064e \u0623\u064e\u0646 \u0644\u0651\u064e\u0627 \u062a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0627\u0652 \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u064e\u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0639\u064e\u062f\u064f\u0648\u0651\u065e \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u065e",translation:"Bukankah Aku telah memerintahkan kepadamu wahai anak cucu Adam agar kamu tidak menyembah setan? Sungguh, setan itu musuh yang nyata bagi kamu"},{id:61,text:"\u0648\u064e\u0623\u064e\u0646\u0650 \u0671\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0646\u0650\u064a\u06da \u0647\u064e\u0670\u0630\u064e\u0627 \u0635\u0650\u0631\u064e\u0670\u0637\u065e \u0645\u0651\u064f\u0633\u06e1\u062a\u064e\u0642\u0650\u064a\u0645\u065e",translation:"dan hendaklah kamu menyembah-Ku. Inilah jalan yang lurus"},{id:62,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u0636\u064e\u0644\u0651\u064e \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u062c\u0650\u0628\u0650\u0644\u0651\u0657\u0627 \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627\u06d6 \u0623\u064e\u0641\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u062a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Dan sungguh, ia (setan itu) telah menyesatkan sebagian besar di antara kamu. Maka apakah kamu tidak mengerti"},{id:63,text:"\u0647\u064e\u0670\u0630\u0650\u0647\u0650\u06e6 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064f \u0671\u0644\u0651\u064e\u062a\u0650\u064a \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064f\u0648\u0639\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Inilah (neraka) Jahanam yang dahulu telah diperingatkan kepadamu"},{id:64,text:"\u0671\u0635\u06e1\u0644\u064e\u0648\u06e1\u0647\u064e\u0627 \u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0643\u06e1\u0641\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Masuklah ke dalamnya pada hari ini karena dahulu kamu mengingkarinya"},{id:65,text:"\u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e \u0646\u064e\u062e\u06e1\u062a\u0650\u0645\u064f \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0641\u06e1\u0648\u064e\u0670\u0647\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u062a\u064f\u0643\u064e\u0644\u0651\u0650\u0645\u064f\u0646\u064e\u0627\u0653 \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u0647\u0650\u0645\u06e1 \u0648\u064e\u062a\u064e\u0634\u06e1\u0647\u064e\u062f\u064f \u0623\u064e\u0631\u06e1\u062c\u064f\u0644\u064f\u0647\u064f\u0645 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0643\u06e1\u0633\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Pada hari ini Kami tutup mulut mereka; tangan mereka akan berkata kepada Kami dan kaki mereka akan memberi kesaksian terhadap apa yang dahulu mereka kerjakan"},{id:66,text:"\u0648\u064e\u0644\u064e\u0648\u06e1 \u0646\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0644\u064e\u0637\u064e\u0645\u064e\u0633\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0639\u06e1\u064a\u064f\u0646\u0650\u0647\u0650\u0645\u06e1 \u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u0628\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u0650\u0631\u064e\u0670\u0637\u064e \u0641\u064e\u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u064a\u064f\u0628\u06e1\u0635\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Dan jika Kami menghendaki, pastilah Kami hapuskan penglihatan mata mereka; sehingga mereka berlomba-lomba (mencari) jalan. Maka bagaimana mungkin mereka dapat melihat"},{id:67,text:"\u0648\u064e\u0644\u064e\u0648\u06e1 \u0646\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0644\u064e\u0645\u064e\u0633\u064e\u062e\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0643\u064e\u0627\u0646\u064e\u062a\u0650\u0647\u0650\u0645\u06e1 \u0641\u064e\u0645\u064e\u0627 \u0671\u0633\u06e1\u062a\u064e\u0637\u064e\u0670\u0639\u064f\u0648\u0627\u0652 \u0645\u064f\u0636\u0650\u064a\u0651\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0631\u06e1\u062c\u0650\u0639\u064f\u0648\u0646\u064e",translation:"Dan jika Kami menghendaki, pastilah Kami ubah bentuk mereka di tempat mereka berada; sehingga mereka tidak sanggup berjalan lagi dan juga tidak sanggup kembali"},{id:68,text:"\u0648\u064e\u0645\u064e\u0646 \u0646\u0651\u064f\u0639\u064e\u0645\u0651\u0650\u0631\u06e1\u0647\u064f \u0646\u064f\u0646\u064e\u0643\u0651\u0650\u0633\u06e1\u0647\u064f \u0641\u0650\u064a \u0671\u0644\u06e1\u062e\u064e\u0644\u06e1\u0642\u0650\u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Dan barang siapa Kami panjangkan umurnya niscaya Kami kembalikan dia kepada awal kejadian(nya).725) Maka mengapa mereka tidak mengerti"},{id:69,text:"\u0648\u064e\u0645\u064e\u0627 \u0639\u064e\u0644\u0651\u064e\u0645\u06e1\u0646\u064e\u0670\u0647\u064f \u0671\u0644\u0634\u0651\u0650\u0639\u06e1\u0631\u064e \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0646\u06e2\u0628\u064e\u063a\u0650\u064a \u0644\u064e\u0647\u064f\u06e5\u0653\u06da \u0625\u0650\u0646\u06e1 \u0647\u064f\u0648\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0630\u0650\u0643\u06e1\u0631\u065e \u0648\u064e\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u065e \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u065e",translation:"Dan Kami tidak mengajarkan syair kepadanya (Muhammad) dan bersyair itu tidaklah pantas baginya. Alquran itu tidak lain hanyalah pelajaran dan Kitab yang jelas"},{id:70,text:"\u0644\u0651\u0650\u064a\u064f\u0646\u0630\u0650\u0631\u064e \u0645\u064e\u0646 \u0643\u064e\u0627\u0646\u064e \u062d\u064e\u064a\u0651\u0657\u0627 \u0648\u064e\u064a\u064e\u062d\u0650\u0642\u0651\u064e \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0644\u064f \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"agar dia (Muhammad) memberi peringatan kepada orang-orang yang hidup (hatinya) dan agar pasti ketetapan (azab) terhadap orang-orang kafir"},{id:71,text:"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0631\u064e\u0648\u06e1\u0627\u0652 \u0623\u064e\u0646\u0651\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u06e1\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u0639\u064e\u0645\u0650\u0644\u064e\u062a\u06e1 \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u0646\u064e\u0627\u0653 \u0623\u064e\u0646\u06e1\u0639\u064e\u0670\u0645\u0657\u0627 \u0641\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0647\u064e\u0627 \u0645\u064e\u0670\u0644\u0650\u0643\u064f\u0648\u0646\u064e",translation:"Dan tidakkah mereka melihat bahwa Kami telah meciptakan hewan ternak untuk mereka, yaitu sebagian dari apa yang telah Kami ciptakan dengan kekuasaan Kami, lalu mereka menguasainya"},{id:72,text:"\u0648\u064e\u0630\u064e\u0644\u0651\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0641\u064e\u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0631\u064e\u0643\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u064a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f\u0648\u0646\u064e",translation:"Dan Kami menundukkannya (hewan-hewan itu) untuk mereka; lalu sebagiannya untuk menjadi tunggangan mereka dan sebagian untuk mereka makan"},{id:73,text:"\u0648\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u064e\u0646\u064e\u0670\u0641\u0650\u0639\u064f \u0648\u064e\u0645\u064e\u0634\u064e\u0627\u0631\u0650\u0628\u064f\u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0634\u06e1\u0643\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Dan mereka memperoleh berbagai manfaat dan minuman darinya. Maka mengapa mereka tidak bersyukur"},{id:74,text:"\u0648\u064e\u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0621\u064e\u0627\u0644\u0650\u0647\u064e\u0629\u0657 \u0644\u0651\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064f\u0646\u0635\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan mereka mengangkat sesembahan selain Allah agar mereka mendapat pertolongan"},{id:75,text:"\u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u064e \u0646\u064e\u0635\u06e1\u0631\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0647\u064f\u0645\u06e1 \u062c\u064f\u0646\u062f\u065e \u0645\u0651\u064f\u062d\u06e1\u0636\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Mereka (sesembahan) itu tidak dapat menolong mereka; padahal mereka itu menjadi tentara yang disiapkan untuk menjaga (sesembahan) itu"},{id:76,text:"\u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u062d\u06e1\u0632\u064f\u0646\u0643\u064e \u0642\u064e\u0648\u06e1\u0644\u064f\u0647\u064f\u0645\u06e1\u06d8 \u0625\u0650\u0646\u0651\u064e\u0627 \u0646\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u064a\u064f\u0633\u0650\u0631\u0651\u064f\u0648\u0646\u064e \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0639\u06e1\u0644\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Maka jangan sampai ucapan mereka membuat engkau (Muhammad) bersedih hati. Sungguhnya, Kami mengetahui apa yang mereka rahasiakan dan apa yang mereka tampakkan"},{id:77,text:"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0631\u064e \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064f \u0623\u064e\u0646\u0651\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u06e1\u0646\u064e\u0670\u0647\u064f \u0645\u0650\u0646 \u0646\u0651\u064f\u0637\u06e1\u0641\u064e\u0629\u0656 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0648\u064e \u062e\u064e\u0635\u0650\u064a\u0645\u065e \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u065e",translation:"Dan tidakkah manusia memperhatikan bahwa Kami menciptakannya dari setetes mani, ternyata dia menjadi musuh yang nyata"},{id:78,text:"\u0648\u064e\u0636\u064e\u0631\u064e\u0628\u064e \u0644\u064e\u0646\u064e\u0627 \u0645\u064e\u062b\u064e\u0644\u0657\u0627 \u0648\u064e\u0646\u064e\u0633\u0650\u064a\u064e \u062e\u064e\u0644\u06e1\u0642\u064e\u0647\u064f\u06e5\u06d6 \u0642\u064e\u0627\u0644\u064e \u0645\u064e\u0646 \u064a\u064f\u062d\u06e1\u064a\u0650 \u0671\u0644\u06e1\u0639\u0650\u0638\u064e\u0670\u0645\u064e \u0648\u064e\u0647\u0650\u064a\u064e \u0631\u064e\u0645\u0650\u064a\u0645\u065e",translation:"Dan dia membuat perumpamaan bagi Kami dan melupakan asal kejadiannya; dia berkata, \"Siapakah yang dapat menghidupkan tulang-belulang, yang telah hancur luluh"},{id:79,text:"\u0642\u064f\u0644\u06e1 \u064a\u064f\u062d\u06e1\u064a\u0650\u064a\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064e\u0646\u0634\u064e\u0623\u064e\u0647\u064e\u0627\u0653 \u0623\u064e\u0648\u0651\u064e\u0644\u064e \u0645\u064e\u0631\u0651\u064e\u0629\u0656\u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u062e\u064e\u0644\u06e1\u0642\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u064c",translation:"Katakanlah (Muhammad), \"Yang akan menghidupkannya ialah (Allah) yang menciptakannya pertama kali. Dan Dia Maha Mengetahui tentang segala makhluk"},{id:80,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0634\u0651\u064e\u062c\u064e\u0631\u0650 \u0671\u0644\u06e1\u0623\u064e\u062e\u06e1\u0636\u064e\u0631\u0650 \u0646\u064e\u0627\u0631\u0657\u0627 \u0641\u064e\u0625\u0650\u0630\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f \u062a\u064f\u0648\u0642\u0650\u062f\u064f\u0648\u0646\u064e",translation:"yaitu (Allah) yang menjadikan api untukmu dari kayu yang hijau, maka seketika itu kamu nyalakan (api) dari kayu itu"},{id:81,text:"\u0623\u064e\u0648\u064e\u0644\u064e\u064a\u06e1\u0633\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0628\u0650\u0642\u064e\u0670\u062f\u0650\u0631\u064d \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0646 \u064a\u064e\u062e\u06e1\u0644\u064f\u0642\u064e \u0645\u0650\u062b\u06e1\u0644\u064e\u0647\u064f\u0645\u06da \u0628\u064e\u0644\u064e\u0649\u0670 \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u062e\u064e\u0644\u0651\u064e\u0640\u0670\u0642\u064f \u0671\u0644\u06e1\u0639\u064e\u0644\u0650\u064a\u0645\u064f",translation:"Dan bukankah (Allah) yang menciptakan langit dan bumi, mampu menciptakan kembali yang serupa itu (jasad mereka yang sudah hancur)? Benar, dan Dia Maha Pencipta, Maha Mengetahui"},{id:82,text:"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0645\u06e1\u0631\u064f\u0647\u064f\u06e5\u0653 \u0625\u0650\u0630\u064e\u0627\u0653 \u0623\u064e\u0631\u064e\u0627\u062f\u064e \u0634\u064e\u064a\u06e1\u0640\u0654\u064b\u0627 \u0623\u064e\u0646 \u064a\u064e\u0642\u064f\u0648\u0644\u064e \u0644\u064e\u0647\u064f\u06e5 \u0643\u064f\u0646 \u0641\u064e\u064a\u064e\u0643\u064f\u0648\u0646\u064f",translation:"Sesungguhnya urusan-Nya apabila Dia menghendaki sesuatu Dia hanya berkata kepadanya, \"Jadilah!\" Maka jadilah sesuatu itu"},{id:83,text:"\u0641\u064e\u0633\u064f\u0628\u06e1\u062d\u064e\u0670\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0628\u0650\u064a\u064e\u062f\u0650\u0647\u0650\u06e6 \u0645\u064e\u0644\u064e\u0643\u064f\u0648\u062a\u064f \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u062a\u064f\u0631\u06e1\u062c\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Maka Mahasuci (Allah) yang ditangan-Nya kekuasaan atas segala sesuatu dan kepada-Nya kamu dikembalikan"}]},{id:37,name:"\u0627\u0644\u0635\u0627\u0641\u0627\u062a",transliteration:"As-Saffat",translation:"Barisan-barisan",type:"meccan",total_verses:182,verses:[{id:1,text:"\u0648\u064e\u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0653\u0641\u0651\u064e\u0640\u0670\u062a\u0650 \u0635\u064e\u0641\u0651\u0657\u0627",translation:"Demi (rombongan malaikat) yang berbaris bersaf-saf"},{id:2,text:"\u0641\u064e\u0671\u0644\u0632\u0651\u064e\u0640\u0670\u062c\u0650\u0631\u064e\u0670\u062a\u0650 \u0632\u064e\u062c\u06e1\u0631\u0657\u0627",translation:"demi (rombongan) yang mencegah dengan sungguh-sungguh"},{id:3,text:"\u0641\u064e\u0671\u0644\u062a\u0651\u064e\u0640\u0670\u0644\u0650\u064a\u064e\u0670\u062a\u0650 \u0630\u0650\u0643\u06e1\u0631\u064b\u0627",translation:"demi (rombongan) yang membacakan peringatan"},{id:4,text:"\u0625\u0650\u0646\u0651\u064e \u0625\u0650\u0644\u064e\u0670\u0647\u064e\u0643\u064f\u0645\u06e1 \u0644\u064e\u0648\u064e\u0670\u062d\u0650\u062f\u065e",translation:"sungguh, Tuhanmu benar-benar Esa"},{id:5,text:"\u0631\u0651\u064e\u0628\u0651\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0648\u064e\u0631\u064e\u0628\u0651\u064f \u0671\u0644\u06e1\u0645\u064e\u0634\u064e\u0670\u0631\u0650\u0642\u0650",translation:"Tuhan langit dan bumi dan apa yang berada di antara keduanya dan Tuhan tempat-tempat terbitnya matahari"},{id:6,text:"\u0625\u0650\u0646\u0651\u064e\u0627 \u0632\u064e\u064a\u0651\u064e\u0646\u0651\u064e\u0627 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0628\u0650\u0632\u0650\u064a\u0646\u064e\u0629\u064d \u0671\u0644\u06e1\u0643\u064e\u0648\u064e\u0627\u0643\u0650\u0628\u0650",translation:"Sesungguhnya Kami telah menghias langit dunia (yang terdekat), dengan hiasan bintang-bintang"},{id:7,text:"\u0648\u064e\u062d\u0650\u0641\u06e1\u0638\u0657\u0627 \u0645\u0651\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u0656 \u0645\u0651\u064e\u0627\u0631\u0650\u062f\u0656",translation:"Dan (Kami) telah menjaganya dari setiap setan yang durhaka"},{id:8,text:"\u0644\u0651\u064e\u0627 \u064a\u064e\u0633\u0651\u064e\u0645\u0651\u064e\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0625\u0650 \u0671\u0644\u06e1\u0623\u064e\u0639\u06e1\u0644\u064e\u0649\u0670 \u0648\u064e\u064a\u064f\u0642\u06e1\u0630\u064e\u0641\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u062c\u064e\u0627\u0646\u0650\u0628\u0656",translation:"mereka (setan-setan itu) tidak dapat mendengar (pembicaraan) para malaikat dan mereka dilempari dari segala penjuru"},{id:9,text:"\u062f\u064f\u062d\u064f\u0648\u0631\u0657\u0627\u06d6 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u065e \u0648\u064e\u0627\u0635\u0650\u0628\u064c",translation:"untuk mengusir mereka dan mereka akan mendapat azab yang kekal"},{id:10,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u06e1 \u062e\u064e\u0637\u0650\u0641\u064e \u0671\u0644\u06e1\u062e\u064e\u0637\u06e1\u0641\u064e\u0629\u064e \u0641\u064e\u0623\u064e\u062a\u06e1\u0628\u064e\u0639\u064e\u0647\u064f\u06e5 \u0634\u0650\u0647\u064e\u0627\u0628\u065e \u062b\u064e\u0627\u0642\u0650\u0628\u065e",translation:"kecuali (setan) yang mencuri (pembicaraan); maka ia dikejar oleh bintang yang menyala"},{id:11,text:"\u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u0641\u06e1\u062a\u0650\u0647\u0650\u0645\u06e1 \u0623\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u0634\u064e\u062f\u0651\u064f \u062e\u064e\u0644\u06e1\u0642\u064b\u0627 \u0623\u064e\u0645 \u0645\u0651\u064e\u0646\u06e1 \u062e\u064e\u0644\u064e\u0642\u06e1\u0646\u064e\u0627\u0653\u06da \u0625\u0650\u0646\u0651\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u06e1\u0646\u064e\u0670\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0637\u0650\u064a\u0646\u0656 \u0644\u0651\u064e\u0627\u0632\u0650\u0628\u0650\u06ed",translation:"Maka tanyakanlah kepada mereka (musyrik Mekkah), \"Apakah penciptaan mereka yang lebih sulit ataukah apa726) yang telah Kami ciptakan?\" Sesungguhnya Kami telah menciptakan mereka dari tanah liat"},{id:12,text:"\u0628\u064e\u0644\u06e1 \u0639\u064e\u062c\u0650\u0628\u06e1\u062a\u064e \u0648\u064e\u064a\u064e\u0633\u06e1\u062e\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Bahkan engkau (Muhammad) menjadi heran (terhadap keingkaran mereka) dan mereka menghinakan (engkau)"},{id:13,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0630\u064f\u0643\u0651\u0650\u0631\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u064a\u064e\u0630\u06e1\u0643\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Dan apabila mereka diberi peringatan, mereka tidak mengindahkannya"},{id:14,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0631\u064e\u0623\u064e\u0648\u06e1\u0627\u0652 \u0621\u064e\u0627\u064a\u064e\u0629\u0657 \u064a\u064e\u0633\u06e1\u062a\u064e\u0633\u06e1\u062e\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Dan apabila mereka melihat suatu tanda (kebesaran) Allah, mereka memperolok-olokan"},{id:15,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u06e1 \u0647\u064e\u0670\u0630\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0633\u0650\u062d\u06e1\u0631\u065e \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u064c",translation:"Dan mereka berkata, \"ini tidak lain hanyalah sihir yang nyata"},{id:16,text:"\u0623\u064e\u0621\u0650\u0630\u064e\u0627 \u0645\u0650\u062a\u06e1\u0646\u064e\u0627 \u0648\u064e\u0643\u064f\u0646\u0651\u064e\u0627 \u062a\u064f\u0631\u064e\u0627\u0628\u0657\u0627 \u0648\u064e\u0639\u0650\u0638\u064e\u0670\u0645\u064b\u0627 \u0623\u064e\u0621\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0645\u064e\u0628\u06e1\u0639\u064f\u0648\u062b\u064f\u0648\u0646\u064e",translation:"Apabila kami telah mati dan telah menjadi tanah dan tulang-belulang, apakah benar kami akan dibangkitkan (kembali)"},{id:17,text:"\u0623\u064e\u0648\u064e\u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0624\u064f\u0646\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0648\u0651\u064e\u0644\u064f\u0648\u0646\u064e",translation:"dan apakah nenek moyang kami yang telah terdahulu (akan dibangkitkan pula)"},{id:18,text:"\u0642\u064f\u0644\u06e1 \u0646\u064e\u0639\u064e\u0645\u06e1 \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u062f\u064e\u0670\u062e\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Katakanlah (Muhammad), \"Ya, dan kamu akan terhina"},{id:19,text:"\u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0647\u0650\u064a\u064e \u0632\u064e\u062c\u06e1\u0631\u064e\u0629\u065e \u0648\u064e\u0670\u062d\u0650\u062f\u064e\u0629\u065e \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0645\u06e1 \u064a\u064e\u0646\u0638\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Maka sesungguhnya kebangkitan itu hanya dengan satu teriakan saja; maka seketika itu mereka melihatnya"},{id:20,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u064a\u064e\u0670\u0648\u064e\u064a\u06e1\u0644\u064e\u0646\u064e\u0627 \u0647\u064e\u0670\u0630\u064e\u0627 \u064a\u064e\u0648\u06e1\u0645\u064f \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u0650",translation:"Dan mereka berkata, \"Alangkah celaka kami! (Kiranya) inilah hari pembalasan itu"},{id:21,text:"\u0647\u064e\u0670\u0630\u064e\u0627 \u064a\u064e\u0648\u06e1\u0645\u064f \u0671\u0644\u06e1\u0641\u064e\u0635\u06e1\u0644\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0643\u064f\u0646\u062a\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f\u0648\u0646\u064e",translation:"(Inilah hari keputusan727) yang dahulu kamu dustakan"},{id:22,text:"\u06de\u0671\u062d\u06e1\u0634\u064f\u0631\u064f\u0648\u0627\u0652 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627\u0652 \u0648\u064e\u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0646\u064e",translation:"(Diperintahkan kepada malaikat), \"Kumpulkanlah orang-orang yang zalim beserta teman sejawat mereka dan apa yang dahulu mereka sembah"},{id:23,text:"\u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0671\u0647\u06e1\u062f\u064f\u0648\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0670\u0637\u0650 \u0671\u0644\u06e1\u062c\u064e\u062d\u0650\u064a\u0645\u0650",translation:"selain Allah, lalu tunjukkanlah kepada mereka jalan ke nereka"},{id:24,text:"\u0648\u064e\u0642\u0650\u0641\u064f\u0648\u0647\u064f\u0645\u06e1\u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u0633\u06e1\u0640\u0654\u064f\u0648\u0644\u064f\u0648\u0646\u064e",translation:"Tahanlah mereka (di tempat perhentian), sesungguhnya mereka akan ditanya"},{id:25,text:"\u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0644\u064e\u0627 \u062a\u064e\u0646\u064e\u0627\u0635\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Mengapa kamu tidak tolong-menolong"},{id:26,text:"\u0628\u064e\u0644\u06e1 \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e \u0645\u064f\u0633\u06e1\u062a\u064e\u0633\u06e1\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Bahkan mereka pada hari itu menyerah (kepada keputusan Allah)"},{id:27,text:"\u0648\u064e\u0623\u064e\u0642\u06e1\u0628\u064e\u0644\u064e \u0628\u064e\u0639\u06e1\u0636\u064f\u0647\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u06e1\u0636\u0656 \u064a\u064e\u062a\u064e\u0633\u064e\u0627\u0653\u0621\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan sebagian mereka menghadap kepada sebagian yang lain saling berbantah-bantahan"},{id:28,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0623\u06e1\u062a\u064f\u0648\u0646\u064e\u0646\u064e\u0627 \u0639\u064e\u0646\u0650 \u0671\u0644\u06e1\u064a\u064e\u0645\u0650\u064a\u0646\u0650",translation:"Sesungguhnya (pengikut-pengikut) mereka berkata (kepada pemimpin-pemimpin mereka), \"Kamulah yang dahulu datang kepada kami dari kanan"},{id:29,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0628\u064e\u0644 \u0644\u0651\u064e\u0645\u06e1 \u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"(Pemimpin-pemimpin) mereka menjawab, \"(Tidak), bahkan kamulah yang tidak (mau) menjadi orang mukmin"},{id:30,text:"\u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0633\u064f\u0644\u06e1\u0637\u064e\u0670\u0646\u0650\u06ed\u06d6 \u0628\u064e\u0644\u06e1 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0642\u064e\u0648\u06e1\u0645\u0657\u0627 \u0637\u064e\u0670\u063a\u0650\u064a\u0646\u064e",translation:"sedangkan kami tidak berkuasa terhadapmu, bahkan kamu menjadi kaum yang melampaui batas"},{id:31,text:"\u0641\u064e\u062d\u064e\u0642\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0642\u064e\u0648\u06e1\u0644\u064f \u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627\u0653\u06d6 \u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0630\u064e\u0627\u0653\u0626\u0650\u0642\u064f\u0648\u0646\u064e",translation:"Maka pantas putusan (azab) Tuhan menimpa kita; pasti kita akan merasakan (azab itu)"},{id:32,text:"\u0641\u064e\u0623\u064e\u063a\u06e1\u0648\u064e\u064a\u06e1\u0646\u064e\u0670\u0643\u064f\u0645\u06e1 \u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u063a\u064e\u0670\u0648\u0650\u064a\u0646\u064e",translation:"Maka kami telah menyesatkan kamu, sesungguhnya kami sendiri, orang-orang yang sesat"},{id:33,text:"\u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u0641\u0650\u064a \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0645\u064f\u0634\u06e1\u062a\u064e\u0631\u0650\u0643\u064f\u0648\u0646\u064e",translation:"Maka sesunguhnya mereka pada hari itu bersama-sama merasakan azab"},{id:34,text:"\u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u0641\u06e1\u0639\u064e\u0644\u064f \u0628\u0650\u0671\u0644\u06e1\u0645\u064f\u062c\u06e1\u0631\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Sungguh, demikianlah Kami memperlakukan terhadap orang-orang yang berbuat dosa"},{id:35,text:"\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0630\u064e\u0627 \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Sungguh, dahulu apabila dikatakan kepada mereka, \"L\u0101 il\u0101ha illall\u0101h\" (Tidak ada tuhan selain Allah), mereka menyombongkan diri"},{id:36,text:"\u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0623\u064e\u0626\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u062a\u064e\u0627\u0631\u0650\u0643\u064f\u0648\u0653\u0627\u0652 \u0621\u064e\u0627\u0644\u0650\u0647\u064e\u062a\u0650\u0646\u064e\u0627 \u0644\u0650\u0634\u064e\u0627\u0639\u0650\u0631\u0656 \u0645\u0651\u064e\u062c\u06e1\u0646\u064f\u0648\u0646\u0650\u06ed",translation:"dan mereka berkata, \"Apakah kami harus meninggalkan sesembahan kami karena seorang penyair gila"},{id:37,text:"\u0628\u064e\u0644\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0635\u064e\u062f\u0651\u064e\u0642\u064e \u0671\u0644\u06e1\u0645\u064f\u0631\u06e1\u0633\u064e\u0644\u0650\u064a\u0646\u064e",translation:"Padahal dia (Muhammad) datang dengan membawa kebenaran dan membenarkan rasul-rasul (sebelumnya)"},{id:38,text:"\u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0644\u064e\u0630\u064e\u0627\u0653\u0626\u0650\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0671\u0644\u06e1\u0623\u064e\u0644\u0650\u064a\u0645\u0650",translation:"Sungguh, kamu pasti akan merasakan azab yang pedih"},{id:39,text:"\u0648\u064e\u0645\u064e\u0627 \u062a\u064f\u062c\u06e1\u0632\u064e\u0648\u06e1\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan kamu tidak diberi balasan melainkan terhadap apa yang telah kamu kerjakan"},{id:40,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u0650\u0628\u064e\u0627\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u0645\u064f\u062e\u06e1\u0644\u064e\u0635\u0650\u064a\u0646\u064e",translation:"tetapi hamba-hamba Allah yang dibersihkan (dari dosa)"},{id:41,text:"\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0631\u0650\u0632\u06e1\u0642\u065e \u0645\u0651\u064e\u0639\u06e1\u0644\u064f\u0648\u0645\u065e",translation:"mereka itu memperoleh rezeki yang sudah ditentukan"},{id:42,text:"\u0641\u064e\u0648\u064e\u0670\u0643\u0650\u0647\u064f \u0648\u064e\u0647\u064f\u0645 \u0645\u0651\u064f\u0643\u06e1\u0631\u064e\u0645\u064f\u0648\u0646\u064e",translation:"(yaitu) buah-buahan. Dan mereka orang yang dimuliakan"},{id:43,text:"\u0641\u0650\u064a \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0650 \u0671\u0644\u0646\u0651\u064e\u0639\u0650\u064a\u0645\u0650",translation:"di dalam surga-surga yang penuh kenikmatan"},{id:44,text:"\u0639\u064e\u0644\u064e\u0649\u0670 \u0633\u064f\u0631\u064f\u0631\u0656 \u0645\u0651\u064f\u062a\u064e\u0642\u064e\u0670\u0628\u0650\u0644\u0650\u064a\u0646\u064e",translation:"(mereka duduk) berhadap-hadapan di atas dipan-dipan"},{id:45,text:"\u064a\u064f\u0637\u064e\u0627\u0641\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0628\u0650\u0643\u064e\u0623\u06e1\u0633\u0656 \u0645\u0651\u0650\u0646 \u0645\u0651\u064e\u0639\u0650\u064a\u0646\u0650\u06ed",translation:"Kepada mereka diedarkan gelas (yang berisi air) dari mata air (surga)"},{id:46,text:"\u0628\u064e\u064a\u06e1\u0636\u064e\u0627\u0653\u0621\u064e \u0644\u064e\u0630\u0651\u064e\u0629\u0656 \u0644\u0651\u0650\u0644\u0634\u0651\u064e\u0640\u0670\u0631\u0650\u0628\u0650\u064a\u0646\u064e",translation:"(warnanya) putih bersih, sedap rasanya bagi orang-orang yang minum"},{id:47,text:"\u0644\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u063a\u064e\u0648\u06e1\u0644\u065e \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u06e1 \u0639\u064e\u0646\u06e1\u0647\u064e\u0627 \u064a\u064f\u0646\u0632\u064e\u0641\u064f\u0648\u0646\u064e",translation:"Tidak ada di dalamnya (unsur) yang memabukkan dan mereka tidak mabuk karenanya"},{id:48,text:"\u0648\u064e\u0639\u0650\u0646\u062f\u064e\u0647\u064f\u0645\u06e1 \u0642\u064e\u0670\u0635\u0650\u0631\u064e\u0670\u062a\u064f \u0671\u0644\u0637\u0651\u064e\u0631\u06e1\u0641\u0650 \u0639\u0650\u064a\u0646\u065e",translation:"Dan di sisi mereka ada (bidadari-bidadari) yang bermata indah, dan membatasi pandangannya"},{id:49,text:"\u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0646\u0651\u064e \u0628\u064e\u064a\u06e1\u0636\u065e \u0645\u0651\u064e\u0643\u06e1\u0646\u064f\u0648\u0646\u065e",translation:"seakan-akan mereka adalah telur yang tersimpan dengan baik"},{id:50,text:"\u0641\u064e\u0623\u064e\u0642\u06e1\u0628\u064e\u0644\u064e \u0628\u064e\u0639\u06e1\u0636\u064f\u0647\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u06e1\u0636\u0656 \u064a\u064e\u062a\u064e\u0633\u064e\u0627\u0653\u0621\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Lalu mereka berhadap-hadapan satu sama lain sambil bercakap-cakap"},{id:51,text:"\u0642\u064e\u0627\u0644\u064e \u0642\u064e\u0627\u0653\u0626\u0650\u0644\u065e \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0625\u0650\u0646\u0651\u0650\u064a \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u064a \u0642\u064e\u0631\u0650\u064a\u0646\u065e",translation:"Berkatalah salah seorang di antara mereka, \"Sesungguhnya aku dahulu (di dunia) pernah mempunyai seorang teman"},{id:52,text:"\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0623\u064e\u0621\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u0650\u064a\u0646\u064e",translation:"yang berkata, \"Apakah sesungguhnya kamu termasuk orang-orang yang membenarkan (hari berbangkit)"},{id:53,text:"\u0623\u064e\u0621\u0650\u0630\u064e\u0627 \u0645\u0650\u062a\u06e1\u0646\u064e\u0627 \u0648\u064e\u0643\u064f\u0646\u0651\u064e\u0627 \u062a\u064f\u0631\u064e\u0627\u0628\u0657\u0627 \u0648\u064e\u0639\u0650\u0638\u064e\u0670\u0645\u064b\u0627 \u0623\u064e\u0621\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0645\u064e\u062f\u0650\u064a\u0646\u064f\u0648\u0646\u064e",translation:"Apabila kita telah mati dan telah menjadi tanah dan tulang-belulang, apakah kita benar-benar (akan dibangkitkan) untuk diberi pembalasan"},{id:54,text:"\u0642\u064e\u0627\u0644\u064e \u0647\u064e\u0644\u06e1 \u0623\u064e\u0646\u062a\u064f\u0645 \u0645\u0651\u064f\u0637\u0651\u064e\u0644\u0650\u0639\u064f\u0648\u0646\u064e",translation:"Dia berkata, \"Maukah kamu meninjau (temanku itu)"},{id:55,text:"\u0641\u064e\u0671\u0637\u0651\u064e\u0644\u064e\u0639\u064e \u0641\u064e\u0631\u064e\u0621\u064e\u0627\u0647\u064f \u0641\u0650\u064a \u0633\u064e\u0648\u064e\u0627\u0653\u0621\u0650 \u0671\u0644\u06e1\u062c\u064e\u062d\u0650\u064a\u0645\u0650",translation:"Maka dia meninjaunya, lalu dia melihat (teman)nya itu di tengah-tengah neraka yang menyala-nyala"},{id:56,text:"\u0642\u064e\u0627\u0644\u064e \u062a\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0646 \u0643\u0650\u062f\u062a\u0651\u064e \u0644\u064e\u062a\u064f\u0631\u06e1\u062f\u0650\u064a\u0646\u0650",translation:"Dia berkata, \"Demi Allah, engkau hampir saja mencelakakanku"},{id:57,text:"\u0648\u064e\u0644\u064e\u0648\u06e1\u0644\u064e\u0627 \u0646\u0650\u0639\u06e1\u0645\u064e\u0629\u064f \u0631\u064e\u0628\u0651\u0650\u064a \u0644\u064e\u0643\u064f\u0646\u062a\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u062d\u06e1\u0636\u064e\u0631\u0650\u064a\u0646\u064e",translation:"dan sekiranya bukan karena nikmat Tuhanku pastilah aku termasuk orang-orang yang diseret (ke neraka)"},{id:58,text:"\u0623\u064e\u0641\u064e\u0645\u064e\u0627 \u0646\u064e\u062d\u06e1\u0646\u064f \u0628\u0650\u0645\u064e\u064a\u0651\u0650\u062a\u0650\u064a\u0646\u064e",translation:"Maka apakah kita tidak akan mati"},{id:59,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0648\u06e1\u062a\u064e\u062a\u064e\u0646\u064e\u0627 \u0671\u0644\u06e1\u0623\u064f\u0648\u0644\u064e\u0649\u0670 \u0648\u064e\u0645\u064e\u0627 \u0646\u064e\u062d\u06e1\u0646\u064f \u0628\u0650\u0645\u064f\u0639\u064e\u0630\u0651\u064e\u0628\u0650\u064a\u0646\u064e",translation:"Kecuali kematian kita yang pertama saja (di dunia), dan kita tidak akan diazab (di akhirat ini)"},{id:60,text:"\u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0644\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0641\u064e\u0648\u06e1\u0632\u064f \u0671\u0644\u06e1\u0639\u064e\u0638\u0650\u064a\u0645\u064f",translation:"Sungguh, ini benar-benar kemenangan yang agung"},{id:61,text:"\u0644\u0650\u0645\u0650\u062b\u06e1\u0644\u0650 \u0647\u064e\u0670\u0630\u064e\u0627 \u0641\u064e\u0644\u06e1\u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u0650 \u0671\u0644\u06e1\u0639\u064e\u0670\u0645\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Untuk (kemenangan) serupa ini, hendaklah beramal orang-orang yang mampu beramal"},{id:62,text:"\u0623\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062e\u064e\u064a\u06e1\u0631\u065e \u0646\u0651\u064f\u0632\u064f\u0644\u064b\u0627 \u0623\u064e\u0645\u06e1 \u0634\u064e\u062c\u064e\u0631\u064e\u0629\u064f \u0671\u0644\u0632\u0651\u064e\u0642\u0651\u064f\u0648\u0645\u0650",translation:"Apakah (makanan surga) itu hidangan yang lebih baik ataukah pohon zaqqum"},{id:63,text:"\u0625\u0650\u0646\u0651\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064e\u0627 \u0641\u0650\u062a\u06e1\u0646\u064e\u0629\u0657 \u0644\u0651\u0650\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Sungguh, Kami menjadikannya (pohon zaqqum) sebagai azab bagi orang-orang zalim"},{id:64,text:"\u0625\u0650\u0646\u0651\u064e\u0647\u064e\u0627 \u0634\u064e\u062c\u064e\u0631\u064e\u0629\u065e \u062a\u064e\u062e\u06e1\u0631\u064f\u062c\u064f \u0641\u0650\u064a\u0653 \u0623\u064e\u0635\u06e1\u0644\u0650 \u0671\u0644\u06e1\u062c\u064e\u062d\u0650\u064a\u0645\u0650",translation:"Sungguh, itu adalah pohon yang keluar dari dasar neraka Jahim"},{id:65,text:"\u0637\u064e\u0644\u06e1\u0639\u064f\u0647\u064e\u0627 \u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u06e5 \u0631\u064f\u0621\u064f\u0648\u0633\u064f \u0671\u0644\u0634\u0651\u064e\u064a\u064e\u0670\u0637\u0650\u064a\u0646\u0650",translation:"mayangnya seperti kepala-kepala setan"},{id:66,text:"\u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0623\u0653\u0643\u0650\u0644\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0641\u064e\u0645\u064e\u0627\u0644\u0650\u0640\u0654\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0671\u0644\u06e1\u0628\u064f\u0637\u064f\u0648\u0646\u064e",translation:"Maka sungguh, mereka benar-benar memakan sebagian darinya (buah pohon itu), dan mereka memenuhi perutnya dengan buahnya (zaqqum)"},{id:67,text:"\u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627 \u0644\u064e\u0634\u064e\u0648\u06e1\u0628\u0657\u0627 \u0645\u0651\u0650\u0646\u06e1 \u062d\u064e\u0645\u0650\u064a\u0645\u0656",translation:"Kemudian sungguh, setelah makan (buah zaqqum) mereka mendapat minuman yang dicampur dengan air yang sangat panas"},{id:68,text:"\u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u064e \u0645\u064e\u0631\u06e1\u062c\u0650\u0639\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u062c\u064e\u062d\u0650\u064a\u0645\u0650",translation:"Kemudian pasti tempat kembali mereka ke neraka Jahim"},{id:69,text:"\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u0644\u06e1\u0641\u064e\u0648\u06e1\u0627\u0652 \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u06e1 \u0636\u064e\u0627\u0653\u0644\u0651\u0650\u064a\u0646\u064e",translation:"Sesungguhnya mereka mendapati nenek moyang mereka dalam keadaan sesat"},{id:70,text:"\u0641\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0621\u064e\u0627\u062b\u064e\u0670\u0631\u0650\u0647\u0650\u0645\u06e1 \u064a\u064f\u0647\u06e1\u0631\u064e\u0639\u064f\u0648\u0646\u064e",translation:"lalu mereka tergesa-gesa mengikuti jejak (nenek moyang) mereka"},{id:71,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0636\u064e\u0644\u0651\u064e \u0642\u064e\u0628\u06e1\u0644\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064f \u0671\u0644\u06e1\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",translation:"Dan sungguh, sebelum mereka (suku Quraisy), telah sesat sebagian besar dari orang-orang yang dahulu"},{id:72,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u0650\u0645 \u0645\u0651\u064f\u0646\u0630\u0650\u0631\u0650\u064a\u0646\u064e",translation:"dan sungguh, Kami telah mengutus (rasul) pemberi peringatan di kalangan mereka"},{id:73,text:"\u0641\u064e\u0671\u0646\u0638\u064f\u0631\u06e1 \u0643\u064e\u064a\u06e1\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0670\u0642\u0650\u0628\u064e\u0629\u064f \u0671\u0644\u06e1\u0645\u064f\u0646\u0630\u064e\u0631\u0650\u064a\u0646\u064e",translation:"Maka perhatikanlah bagaimana kesudahan orang-orang yang diberi peringatan itu"},{id:74,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u0650\u0628\u064e\u0627\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u0645\u064f\u062e\u06e1\u0644\u064e\u0635\u0650\u064a\u0646\u064e",translation:"kecuali hamba-hamba Allah yang disucikan (dari dosa)"},{id:75,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0646\u064e\u0627\u062f\u064e\u0649\u0670\u0646\u064e\u0627 \u0646\u064f\u0648\u062d\u065e \u0641\u064e\u0644\u064e\u0646\u0650\u0639\u06e1\u0645\u064e \u0671\u0644\u06e1\u0645\u064f\u062c\u0650\u064a\u0628\u064f\u0648\u0646\u064e",translation:"Dan sungguh, Nuh telah berdoa kepada Kami, maka sungguh, Kamilah sebaik-baik yang memperkenankan doa"},{id:76,text:"\u0648\u064e\u0646\u064e\u062c\u0651\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f \u0648\u064e\u0623\u064e\u0647\u06e1\u0644\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0643\u064e\u0631\u06e1\u0628\u0650 \u0671\u0644\u06e1\u0639\u064e\u0638\u0650\u064a\u0645\u0650",translation:"Kami telah menyelamatkan dia dan pengikutnya dari bencana yang besar"},{id:77,text:"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u062a\u064e\u0647\u064f\u06e5 \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0628\u064e\u0627\u0642\u0650\u064a\u0646\u064e",translation:"Dan Kami jadikan anak cucunya orang-orang yang melanjutkan keturunan"},{id:78,text:"\u0648\u064e\u062a\u064e\u0631\u064e\u0643\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan Kami abadikan untuk Nuh (pujian) di kalangan orang-orang yang datang kemudian"},{id:79,text:"\u0633\u064e\u0644\u064e\u0670\u0645\u064c \u0639\u064e\u0644\u064e\u0649\u0670 \u0646\u064f\u0648\u062d\u0656 \u0641\u0650\u064a \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Kesejahteraan (Kami limpahkan) atas Nuh di seluruh alam"},{id:80,text:"\u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u062c\u06e1\u0632\u0650\u064a \u0671\u0644\u06e1\u0645\u064f\u062d\u06e1\u0633\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Sungguh, demikianlah Kami memberi balasan kepada orang-orang yang berbuat baik"},{id:81,text:"\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646\u06e1 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0646\u064e\u0627 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Sungguh, dia termasuk di antara hamba-hamba Kami yang beriman"},{id:82,text:"\u062b\u064f\u0645\u0651\u064e \u0623\u064e\u063a\u06e1\u0631\u064e\u0642\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0623\u0653\u062e\u064e\u0631\u0650\u064a\u0646\u064e",translation:"Kemudian Kami tenggelamkan yang lain"},{id:83,text:"\u06de\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0645\u0650\u0646 \u0634\u0650\u064a\u0639\u064e\u062a\u0650\u0647\u0650\u06e6 \u0644\u064e\u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064e",translation:"Dan sungguh, Ibrahim termasuk golongannya (Nuh)"},{id:84,text:"\u0625\u0650\u0630\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u06e5 \u0628\u0650\u0642\u064e\u0644\u06e1\u0628\u0656 \u0633\u064e\u0644\u0650\u064a\u0645\u064d",translation:"(Ingatlah) ketika dia datang kepada Tuhannya dengan hati yang suci"},{id:85,text:"\u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0623\u064e\u0628\u0650\u064a\u0647\u0650 \u0648\u064e\u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u06e6 \u0645\u064e\u0627\u0630\u064e\u0627 \u062a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0646\u064e",translation:"(ingatlah) ketika dia berkata kepada ayahnya dan kaumnya, \"Apakah yang kamu sembah itu"},{id:86,text:"\u0623\u064e\u0626\u0650\u0641\u06e1\u0643\u064b\u0627 \u0621\u064e\u0627\u0644\u0650\u0647\u064e\u0629\u0657 \u062f\u064f\u0648\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e",translation:"Apakah kamu menghendaki kebohongan dengan sesembahan selain Allah itu"},{id:87,text:"\u0641\u064e\u0645\u064e\u0627 \u0638\u064e\u0646\u0651\u064f\u0643\u064f\u0645 \u0628\u0650\u0631\u064e\u0628\u0651\u0650 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Maka bagaimana anggapanmu terhadap Tuhan seluruh alam"},{id:88,text:"\u0641\u064e\u0646\u064e\u0638\u064e\u0631\u064e \u0646\u064e\u0638\u06e1\u0631\u064e\u0629\u0657 \u0641\u0650\u064a \u0671\u0644\u0646\u0651\u064f\u062c\u064f\u0648\u0645\u0650",translation:"Lalu dia memandang sekilas ke bintang-bintang"},{id:89,text:"\u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0633\u064e\u0642\u0650\u064a\u0645\u065e",translation:"kemudian dia (Ibrahim) berkata, \"Sesungguhnya aku sakit"},{id:90,text:"\u0641\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u06e1\u0627\u0652 \u0639\u064e\u0646\u06e1\u0647\u064f \u0645\u064f\u062f\u06e1\u0628\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Lalu mereka berpaling dari dia dan pergi meninggalkannya"},{id:91,text:"\u0641\u064e\u0631\u064e\u0627\u063a\u064e \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0621\u064e\u0627\u0644\u0650\u0647\u064e\u062a\u0650\u0647\u0650\u0645\u06e1 \u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0644\u064e\u0627 \u062a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f\u0648\u0646\u064e",translation:"Kemudian dia (Ibrahim) pergi dengan diam-diam kepada berhala-berhala mereka; lalu dia berkata, \"Mengapa kamu tidak makan"},{id:92,text:"\u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0644\u064e\u0627 \u062a\u064e\u0646\u0637\u0650\u0642\u064f\u0648\u0646\u064e",translation:"Mengapa kamu tidak menjawab"},{id:93,text:"\u0641\u064e\u0631\u064e\u0627\u063a\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0636\u064e\u0631\u06e1\u0628\u064e\u06e2\u0627 \u0628\u0650\u0671\u0644\u06e1\u064a\u064e\u0645\u0650\u064a\u0646\u0650",translation:"Lalu dihadapinya (berhala-berhala) itu sambil memukulnya dengan tangan kanannya"},{id:94,text:"\u0641\u064e\u0623\u064e\u0642\u06e1\u0628\u064e\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u064a\u064e\u0632\u0650\u0641\u0651\u064f\u0648\u0646\u064e",translation:"Kemudian mereka (kaumnya) datang bergegas kepadanya"},{id:95,text:"\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u062a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u062a\u064e\u0646\u06e1\u062d\u0650\u062a\u064f\u0648\u0646\u064e",translation:"Dia (Ibrahim) berkata, \"Apakah kamu menyembah patung-patung yang kamu pahat itu"},{id:96,text:"\u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u062e\u064e\u0644\u064e\u0642\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"padahal Allah lah yang menciptakan kamu dan apa yang kamu perbuat"},{id:97,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0671\u0628\u06e1\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0647\u064f\u06e5 \u0628\u064f\u0646\u06e1\u064a\u064e\u0670\u0646\u0657\u0627 \u0641\u064e\u0623\u064e\u0644\u06e1\u0642\u064f\u0648\u0647\u064f \u0641\u0650\u064a \u0671\u0644\u06e1\u062c\u064e\u062d\u0650\u064a\u0645\u0650",translation:"Mereka berkata, \"Buatlah bangunan (perapian) untuknya (membakar Ibrahim); lalu lemparkan dia ke dalam api yang menyala-nyala itu"},{id:98,text:"\u0641\u064e\u0623\u064e\u0631\u064e\u0627\u062f\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6 \u0643\u064e\u064a\u06e1\u062f\u0657\u0627 \u0641\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u0633\u06e1\u0641\u064e\u0644\u0650\u064a\u0646\u064e",translation:"Maka mereka bermaksud memperdayainya dengan (membakar)nya, (namun Allah menyelamatkannya), lalu Kami jadikan mereka orang-orang yang hina"},{id:99,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0630\u064e\u0627\u0647\u0650\u0628\u064c \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u064a \u0633\u064e\u064a\u064e\u0647\u06e1\u062f\u0650\u064a\u0646\u0650",translation:"Dan dia (Ibrahim) berkata, \"Sesungguhnya aku harus pergi (menghadap) kepada Tuhanku, Dia akan memberi petunjuk kepadaku"},{id:100,text:"\u0631\u064e\u0628\u0651\u0650 \u0647\u064e\u0628\u06e1 \u0644\u0650\u064a \u0645\u0650\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u0650\u064a\u0646\u064e",translation:"Ya Tuhanku, anugerahkanlah kepadaku (seorang anak) yang saleh"},{id:101,text:"\u0641\u064e\u0628\u064e\u0634\u0651\u064e\u0631\u06e1\u0646\u064e\u0670\u0647\u064f \u0628\u0650\u063a\u064f\u0644\u064e\u0670\u0645\u064d \u062d\u064e\u0644\u0650\u064a\u0645\u0656",translation:"Maka Kami beri kabar gembira kepadanya dengan (kelahiran) seorang anak yang sangat sabar (Ismail)"},{id:102,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0628\u064e\u0644\u064e\u063a\u064e \u0645\u064e\u0639\u064e\u0647\u064f \u0671\u0644\u0633\u0651\u064e\u0639\u06e1\u064a\u064e \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0670\u0628\u064f\u0646\u064e\u064a\u0651\u064e \u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064e\u0631\u064e\u0649\u0670 \u0641\u0650\u064a \u0671\u0644\u06e1\u0645\u064e\u0646\u064e\u0627\u0645\u0650 \u0623\u064e\u0646\u0651\u0650\u064a\u0653 \u0623\u064e\u0630\u06e1\u0628\u064e\u062d\u064f\u0643\u064e \u0641\u064e\u0671\u0646\u0638\u064f\u0631\u06e1 \u0645\u064e\u0627\u0630\u064e\u0627 \u062a\u064e\u0631\u064e\u0649\u0670\u06da \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0640\u0670\u0653\u0623\u064e\u0628\u064e\u062a\u0650 \u0671\u0641\u06e1\u0639\u064e\u0644\u06e1 \u0645\u064e\u0627 \u062a\u064f\u0624\u06e1\u0645\u064e\u0631\u064f\u06d6 \u0633\u064e\u062a\u064e\u062c\u0650\u062f\u064f\u0646\u0650\u064a\u0653 \u0625\u0650\u0646 \u0634\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0628\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Maka ketika anak itu sampai (pada umur) sanggup berusaha bersamanya, (Ibrahim) berkata, \"Wahai anakku! Sesungguhnya aku bermimpi bahwa aku menyembelihmu. Maka bagaimanakah pendapatmu!\" Dia (Ismail) menjawab, \"Wahai ayahku! Lakukanlah apa yang diperintahkan (Allah) kepadamu; insy\u0101 Allah engkau akan mendapatiku termasuk orang yang sabar"},{id:103,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u0633\u06e1\u0644\u064e\u0645\u064e\u0627 \u0648\u064e\u062a\u064e\u0644\u0651\u064e\u0647\u064f\u06e5 \u0644\u0650\u0644\u06e1\u062c\u064e\u0628\u0650\u064a\u0646\u0650",translation:"Maka ketika keduanya telah berserah diri dan dia (Ibrahim) membaringkan anaknya atas pelipisnya, (untuk melaksanakan perintah Allah)"},{id:104,text:"\u0648\u064e\u0646\u064e\u0670\u062f\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f \u0623\u064e\u0646 \u064a\u064e\u0640\u0670\u0653\u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064f",translation:"Lalu Kami panggil dia, \"Wahai Ibrahim"},{id:105,text:"\u0642\u064e\u062f\u06e1 \u0635\u064e\u062f\u0651\u064e\u0642\u06e1\u062a\u064e \u0671\u0644\u0631\u0651\u064f\u0621\u06e1\u064a\u064e\u0627\u0653\u06da \u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u062c\u06e1\u0632\u0650\u064a \u0671\u0644\u06e1\u0645\u064f\u062d\u06e1\u0633\u0650\u0646\u0650\u064a\u0646\u064e",translation:"(Sungguh, engkau telah membenarkan mimpi itu.\"733) Sungguh, demikianlah Kami memberi balasan kepada orang-orang yang berbuat baik"},{id:106,text:"\u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0644\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0628\u064e\u0644\u064e\u0640\u0670\u0653\u0624\u064f\u0627\u0652 \u0671\u0644\u06e1\u0645\u064f\u0628\u0650\u064a\u0646\u064f",translation:"Sesungguhnya ini benar-benar suatu ujian yang nyata"},{id:107,text:"\u0648\u064e\u0641\u064e\u062f\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f \u0628\u0650\u0630\u0650\u0628\u06e1\u062d\u064d \u0639\u064e\u0638\u0650\u064a\u0645\u0656",translation:"Dan Kami tebus anak itu dengan seekor sembelihan yang besar"},{id:108,text:"\u0648\u064e\u062a\u064e\u0631\u064e\u0643\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan Kami abadikan untuk Ibrahim (pujian) di kalangan orang-orang yang datang kemudian"},{id:109,text:"\u0633\u064e\u0644\u064e\u0670\u0645\u064c \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064e",translation:"Selamat sejahtera bagi Ibrahim"},{id:110,text:"\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u062c\u06e1\u0632\u0650\u064a \u0671\u0644\u06e1\u0645\u064f\u062d\u06e1\u0633\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Demikianlah Kami memberi balasan kepada orang-orang yang berbuat baik"},{id:111,text:"\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646\u06e1 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0646\u064e\u0627 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Sungguh, dia termasuk hamba-hamba Kami yang beriman"},{id:112,text:"\u0648\u064e\u0628\u064e\u0634\u0651\u064e\u0631\u06e1\u0646\u064e\u0670\u0647\u064f \u0628\u0650\u0625\u0650\u0633\u06e1\u062d\u064e\u0670\u0642\u064e \u0646\u064e\u0628\u0650\u064a\u0651\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u0650\u064a\u0646\u064e",translation:"Dan Kami beri dia kabar gembira dengan (kelahiran) Ishak seorang nabi yang termasuk orang-orang yang saleh"},{id:113,text:"\u0648\u064e\u0628\u064e\u0670\u0631\u064e\u0643\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0648\u064e\u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0625\u0650\u0633\u06e1\u062d\u064e\u0670\u0642\u064e\u06da \u0648\u064e\u0645\u0650\u0646 \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u062a\u0650\u0647\u0650\u0645\u064e\u0627 \u0645\u064f\u062d\u06e1\u0633\u0650\u0646\u065e \u0648\u064e\u0638\u064e\u0627\u0644\u0650\u0645\u065e \u0644\u0651\u0650\u0646\u064e\u0641\u06e1\u0633\u0650\u0647\u0650\u06e6 \u0645\u064f\u0628\u0650\u064a\u0646\u065e",translation:"Dan Kami limpahkan keberkahan kepadanya dan kepada Ishak. Dan di antara keturunan keduanya ada yang berbuat baik dan ada (pula) yang terang-terangan berbuat zalim terhadap dirinya sendiri"},{id:114,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0645\u064e\u0646\u064e\u0646\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u0647\u064e\u0670\u0631\u064f\u0648\u0646\u064e",translation:"Dan sungguh, Kami telah melimpahkan nikmat kepada Musa dan Harun"},{id:115,text:"\u0648\u064e\u0646\u064e\u062c\u0651\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u064e\u0627 \u0648\u064e\u0642\u064e\u0648\u06e1\u0645\u064e\u0647\u064f\u0645\u064e\u0627 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0643\u064e\u0631\u06e1\u0628\u0650 \u0671\u0644\u06e1\u0639\u064e\u0638\u0650\u064a\u0645\u0650",translation:"Dan Kami selamatkan keduanya dan kaumnya dari bencana yang besar"},{id:116,text:"\u0648\u064e\u0646\u064e\u0635\u064e\u0631\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0641\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u063a\u064e\u0670\u0644\u0650\u0628\u0650\u064a\u0646\u064e",translation:"dan Kami tolong mereka, sehingga jadilah mereka orang-orang yang menang"},{id:117,text:"\u0648\u064e\u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u064e\u0627 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0671\u0644\u06e1\u0645\u064f\u0633\u06e1\u062a\u064e\u0628\u0650\u064a\u0646\u064e",translation:"Dan Kami berikan kepada keduanya Kitab yang sangat jelas"},{id:118,text:"\u0648\u064e\u0647\u064e\u062f\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u064e\u0627 \u0671\u0644\u0635\u0651\u0650\u0631\u064e\u0670\u0637\u064e \u0671\u0644\u06e1\u0645\u064f\u0633\u06e1\u062a\u064e\u0642\u0650\u064a\u0645\u064e",translation:"dan Kami tunjukkan keduanya jalan yang lurus"},{id:119,text:"\u0648\u064e\u062a\u064e\u0631\u064e\u0643\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan Kami abadikan untuk keduanya (pujian) di kalangan orang-orang yang datang kemudian"},{id:120,text:"\u0633\u064e\u0644\u064e\u0670\u0645\u064c \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u0647\u064e\u0670\u0631\u064f\u0648\u0646\u064e",translation:"Selamat sejahtera bagi Musa dan Harun"},{id:121,text:"\u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u062c\u06e1\u0632\u0650\u064a \u0671\u0644\u06e1\u0645\u064f\u062d\u06e1\u0633\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Demikianlah Kami memberi balasan kepada orang-orang yang berbuat baik"},{id:122,text:"\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u064e\u0627 \u0645\u0650\u0646\u06e1 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0646\u064e\u0627 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Sungguh, keduanya termasuk hamba-hamba Kami yang beriman"},{id:123,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0625\u0650\u0644\u06e1\u064a\u064e\u0627\u0633\u064e \u0644\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0631\u06e1\u0633\u064e\u0644\u0650\u064a\u0646\u064e",translation:"Dan sungguh, Ilyas benar-benar termasuk salah seorang rasul"},{id:124,text:"\u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",translation:"(Ingatlah) ketika dia berkata kepada kaumnya, \"Mengapa kamu tidak bertakwa"},{id:125,text:"\u0623\u064e\u062a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e \u0628\u064e\u0639\u06e1\u0644\u0657\u0627 \u0648\u064e\u062a\u064e\u0630\u064e\u0631\u064f\u0648\u0646\u064e \u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064e \u0671\u0644\u06e1\u062e\u064e\u0670\u0644\u0650\u0642\u0650\u064a\u0646\u064e",translation:"(Patutkah kamu menyembah Ba'l 735) dan kamu tinggalkan (Allah) sebaik-baik Pencipta"},{id:126,text:"\u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0631\u064e\u0628\u0651\u064e \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0626\u0650\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",translation:"(yaitu) Allah Tuhanmu dan Tuhan nenek moyangmu yang terdahulu"},{id:127,text:"\u0641\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0647\u064f \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0645\u064f\u062d\u06e1\u0636\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Tetapi mereka mendustakannya (Ilyas), maka sungguh, mereka akan diseret (ke neraka)"},{id:128,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u0650\u0628\u064e\u0627\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u0645\u064f\u062e\u06e1\u0644\u064e\u0635\u0650\u064a\u0646\u064e",translation:"kecuali hamba-hamba Allah yang disucikan (dari dosa)"},{id:129,text:"\u0648\u064e\u062a\u064e\u0631\u064e\u0643\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan Kami abadikan untuk Ilyas (pujian) di kalangan orang-orang yang datang kemudian"},{id:130,text:"\u0633\u064e\u0644\u064e\u0670\u0645\u064c \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0625\u0650\u0644\u06e1 \u064a\u064e\u0627\u0633\u0650\u064a\u0646\u064e",translation:"selamat sejahtera bagi Ilyas"},{id:131,text:"\u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u062c\u06e1\u0632\u0650\u064a \u0671\u0644\u06e1\u0645\u064f\u062d\u06e1\u0633\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Demikianlah Kami memberi balasan kepada orang-orang yang berbuat baik"},{id:132,text:"\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646\u06e1 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0646\u064e\u0627 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Sungguh, dia termasuk hamba-hamba Kami yang beriman"},{id:133,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0644\u064f\u0648\u0637\u0657\u0627 \u0644\u0651\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0631\u06e1\u0633\u064e\u0644\u0650\u064a\u0646\u064e",translation:"Dan sungguh, Lu\u1e6d benar-benar termasuk salah seorang rasul"},{id:134,text:"\u0625\u0650\u0630\u06e1 \u0646\u064e\u062c\u0651\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f \u0648\u064e\u0623\u064e\u0647\u06e1\u0644\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u062c\u06e1\u0645\u064e\u0639\u0650\u064a\u0646\u064e",translation:"(Ingatlah) ketika Kami telah menyelamatkan dia dan pengikutnya semua"},{id:135,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u062c\u064f\u0648\u0632\u0657\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u063a\u064e\u0670\u0628\u0650\u0631\u0650\u064a\u0646\u064e",translation:"kecuali seorang perempuan tua (istrinya) bersama-sama orang yang tinggal (di kota)"},{id:136,text:"\u062b\u064f\u0645\u0651\u064e \u062f\u064e\u0645\u0651\u064e\u0631\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0623\u0653\u062e\u064e\u0631\u0650\u064a\u0646\u064e",translation:"Kemudian Kami binasakan orang-orang yang lain"},{id:137,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0644\u064e\u062a\u064e\u0645\u064f\u0631\u0651\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0645\u0651\u064f\u0635\u06e1\u0628\u0650\u062d\u0650\u064a\u0646\u064e",translation:"Dan sesungguhnya kamu (penduduk Mekkah) benar-benar akan melalui (bekas-bekas) mereka pada waktu pagi"},{id:138,text:"\u0648\u064e\u0628\u0650\u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u0650\u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e",translation:"dan pada waktu malam. Maka mengapa kamu tidak mengerti"},{id:139,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u064a\u064f\u0648\u0646\u064f\u0633\u064e \u0644\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0631\u06e1\u0633\u064e\u0644\u0650\u064a\u0646\u064e",translation:"Dan sungguh, Yunus benar-benar termasuk salah seorang rasul"},{id:140,text:"\u0625\u0650\u0630\u06e1 \u0623\u064e\u0628\u064e\u0642\u064e \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u0641\u064f\u0644\u06e1\u0643\u0650 \u0671\u0644\u06e1\u0645\u064e\u0634\u06e1\u062d\u064f\u0648\u0646\u0650",translation:"(ingatlah) ketika dia lari,737) ke kapal yang penuh muatan"},{id:141,text:"\u0641\u064e\u0633\u064e\u0627\u0647\u064e\u0645\u064e \u0641\u064e\u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u062f\u06e1\u062d\u064e\u0636\u0650\u064a\u0646\u064e",translation:"(kemudian dia ikut diundi738) ternyata dia termasuk orang-orang yang kalah (dalam undian)"},{id:142,text:"\u0641\u064e\u0671\u0644\u06e1\u062a\u064e\u0642\u064e\u0645\u064e\u0647\u064f \u0671\u0644\u06e1\u062d\u064f\u0648\u062a\u064f \u0648\u064e\u0647\u064f\u0648\u064e \u0645\u064f\u0644\u0650\u064a\u0645\u065e",translation:"Maka dia ditelan oleh ikan besar dalam keadaan tercela"},{id:143,text:"\u0641\u064e\u0644\u064e\u0648\u06e1\u0644\u064e\u0627\u0653 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u06e5 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u0650\u064a\u0646\u064e",translation:"Maka sekiranya dia tidak termasuk orang yang banyak berzikir (bertasbih) kepada Allah"},{id:144,text:"\u0644\u064e\u0644\u064e\u0628\u0650\u062b\u064e \u0641\u0650\u064a \u0628\u064e\u0637\u06e1\u0646\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u06e1\u0645\u0650 \u064a\u064f\u0628\u06e1\u0639\u064e\u062b\u064f\u0648\u0646\u064e",translation:"niscaya dia akan tetap tinggal di perut (ikan itu) sampai Hari Berbangkit"},{id:145,text:"\u06de\u0641\u064e\u0646\u064e\u0628\u064e\u0630\u06e1\u0646\u064e\u0670\u0647\u064f \u0628\u0650\u0671\u0644\u06e1\u0639\u064e\u0631\u064e\u0627\u0653\u0621\u0650 \u0648\u064e\u0647\u064f\u0648\u064e \u0633\u064e\u0642\u0650\u064a\u0645\u065e",translation:"Kemudian Kami lemparkan dia ke daratan yang tandus, sedang dia dalam keadaan sakit"},{id:146,text:"\u0648\u064e\u0623\u064e\u0646\u06e2\u0628\u064e\u062a\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0634\u064e\u062c\u064e\u0631\u064e\u0629\u0657 \u0645\u0651\u0650\u0646 \u064a\u064e\u0642\u06e1\u0637\u0650\u064a\u0646\u0656",translation:"Kemudian untuk dia Kami tumbuhkan sebatang pohon dari jenis labu"},{id:147,text:"\u0648\u064e\u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u0650\u0627\u0652\u0626\u064e\u0629\u0650 \u0623\u064e\u0644\u06e1\u0641\u064d \u0623\u064e\u0648\u06e1 \u064a\u064e\u0632\u0650\u064a\u062f\u064f\u0648\u0646\u064e",translation:"Dan Kami utus dia kepada seratus ribu (orang) atau lebih"},{id:148,text:"\u0641\u064e\u0640\u0654\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0641\u064e\u0645\u064e\u062a\u0651\u064e\u0639\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649\u0670 \u062d\u0650\u064a\u0646\u0656",translation:"sehingga mereka beriman, karena itu Kami anugerahkan kenikmatan hidup kepada mereka hingga waktu tertentu"},{id:149,text:"\u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u0641\u06e1\u062a\u0650\u0647\u0650\u0645\u06e1 \u0623\u064e\u0644\u0650\u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0671\u0644\u06e1\u0628\u064e\u0646\u064e\u0627\u062a\u064f \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0628\u064e\u0646\u064f\u0648\u0646\u064e",translation:"Maka tanyakanlah (Muhammad) kepada mereka (orang-orang kafir Mekkah), \"Apakah anak-anak perempuan itu untuk Tuhanmu sedangkan untuk mereka anak laki-laki"},{id:150,text:"\u0623\u064e\u0645\u06e1 \u062e\u064e\u0644\u064e\u0642\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u064e \u0625\u0650\u0646\u064e\u0670\u062b\u0657\u0627 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0634\u064e\u0670\u0647\u0650\u062f\u064f\u0648\u0646\u064e",translation:"atau apakah Kami menciptakan malaikat-malaikat berupa perempuan sedangkan mereka menyaksikan(nya)"},{id:151,text:"\u0623\u064e\u0644\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0625\u0650\u0641\u06e1\u0643\u0650\u0647\u0650\u0645\u06e1 \u0644\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e",translation:"Ingatlah, sesungguhnya di antara kebohongannya mereka benar-benar mengatakan"},{id:152,text:"\u0648\u064e\u0644\u064e\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0643\u064e\u0670\u0630\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Allah mempunyai anak.\" Dan sungguh, mereka benar-benar pendusta"},{id:153,text:"\u0623\u064e\u0635\u06e1\u0637\u064e\u0641\u064e\u0649 \u0671\u0644\u06e1\u0628\u064e\u0646\u064e\u0627\u062a\u0650 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0628\u064e\u0646\u0650\u064a\u0646\u064e",translation:"apakah Dia (Allah) memilih anak-anak perempuan daripada anak-anak laki-laki"},{id:154,text:"\u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0643\u064e\u064a\u06e1\u0641\u064e \u062a\u064e\u062d\u06e1\u0643\u064f\u0645\u064f\u0648\u0646\u064e",translation:"Mengapa kamu ini? Bagaimana (caranya) kamu menetapkan"},{id:155,text:"\u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Maka mengapa kamu tidak memikirkan"},{id:156,text:"\u0623\u064e\u0645\u06e1 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0633\u064f\u0644\u06e1\u0637\u064e\u0670\u0646\u065e \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u065e",translation:"Ataukah kamu mempunyai bukti yang jelas"},{id:157,text:"\u0641\u064e\u0623\u06e1\u062a\u064f\u0648\u0627\u0652 \u0628\u0650\u0643\u0650\u062a\u064e\u0670\u0628\u0650\u0643\u064f\u0645\u06e1 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0635\u064e\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e",translation:"(kalau begitu) maka bawalah kitabmu jika kamu orang yang benar"},{id:158,text:"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064f\u0648\u0627\u0652 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u06e5 \u0648\u064e\u0628\u064e\u064a\u06e1\u0646\u064e \u0671\u0644\u06e1\u062c\u0650\u0646\u0651\u064e\u0629\u0650 \u0646\u064e\u0633\u064e\u0628\u0657\u0627\u06da \u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0639\u064e\u0644\u0650\u0645\u064e\u062a\u0650 \u0671\u0644\u06e1\u062c\u0650\u0646\u0651\u064e\u0629\u064f \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0645\u064f\u062d\u06e1\u0636\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan mereka mengadakan (hubungan) nasab (keluarga) antara Dia (Allah) dan jin. Dan sungguh, jin telah mengetahui bahwa mereka pasti akan diseret (ke neraka)"},{id:159,text:"\u0633\u064f\u0628\u06e1\u062d\u064e\u0670\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064e\u0635\u0650\u0641\u064f\u0648\u0646\u064e",translation:"Mahasuci Allah dari apa yang mereka sifatkan"},{id:160,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u0650\u0628\u064e\u0627\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u0645\u064f\u062e\u06e1\u0644\u064e\u0635\u0650\u064a\u0646\u064e",translation:"(kecuali hamba-hamba Allah741) yang disucikan (dari dosa)"},{id:161,text:"\u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0646\u064e",translation:"Maka sesungguhnya kamu dan apa yang kamu sembah itu"},{id:162,text:"\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0628\u0650\u0641\u064e\u0670\u062a\u0650\u0646\u0650\u064a\u0646\u064e",translation:"tidak akan dapat menyesatkan (seseorang) terhadap Allah"},{id:163,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u06e1 \u0647\u064f\u0648\u064e \u0635\u064e\u0627\u0644\u0650 \u0671\u0644\u06e1\u062c\u064e\u062d\u0650\u064a\u0645\u0650",translation:"kecuali orang-orang yang akan masuk ke neraka Jahim"},{id:164,text:"\u0648\u064e\u0645\u064e\u0627\u0645\u0650\u0646\u0651\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0644\u064e\u0647\u064f\u06e5 \u0645\u064e\u0642\u064e\u0627\u0645\u065e \u0645\u0651\u064e\u0639\u06e1\u0644\u064f\u0648\u0645\u065e",translation:"Dan tidak satu pun di antara kami (malaikat) melainkan masing-masing mempunyai kedudukan tertentu"},{id:165,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0646\u064e\u062d\u06e1\u0646\u064f \u0671\u0644\u0635\u0651\u064e\u0627\u0653\u0641\u0651\u064f\u0648\u0646\u064e",translation:"dan sesungguhnya kami selalu teratur dalam barisan (dalam melaksanakan perintah Allah)"},{id:166,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0646\u064e\u062d\u06e1\u0646\u064f \u0671\u0644\u06e1\u0645\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u064f\u0648\u0646\u064e",translation:"Dan sungguh, kami benar-benar terus bertasbih (kepada Allah)"},{id:167,text:"\u0648\u064e\u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e",translation:"Dan sesungguhnya mereka (orang kafir Mekkah) benar-benar pernah berkata"},{id:168,text:"\u0644\u064e\u0648\u06e1 \u0623\u064e\u0646\u0651\u064e \u0639\u0650\u0646\u062f\u064e\u0646\u064e\u0627 \u0630\u0650\u0643\u06e1\u0631\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",translation:"Sekiranya di sisi kami ada suatu kitab dari (kitab-kitab yang diturunkan) kepada orang-orang dahulu"},{id:169,text:"\u0644\u064e\u0643\u064f\u0646\u0651\u064e\u0627 \u0639\u0650\u0628\u064e\u0627\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u0645\u064f\u062e\u06e1\u0644\u064e\u0635\u0650\u064a\u0646\u064e",translation:"tentu kami akan menjadi hamba Allah yang disucikan (dari dosa)"},{id:170,text:"\u0641\u064e\u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6\u06d6 \u0641\u064e\u0633\u064e\u0648\u06e1\u0641\u064e \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Tetapi ternyata mereka mengingkarinya (Alquran); maka kelak mereka akan mengetahui (akibat keingkarannya itu)"},{id:171,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0633\u064e\u0628\u064e\u0642\u064e\u062a\u06e1 \u0643\u064e\u0644\u0650\u0645\u064e\u062a\u064f\u0646\u064e\u0627 \u0644\u0650\u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0646\u064e\u0627 \u0671\u0644\u06e1\u0645\u064f\u0631\u06e1\u0633\u064e\u0644\u0650\u064a\u0646\u064e",translation:"Dan sungguh, janji Kami telah tetap bagi hamba-hamba Kami yang menjadi rasul"},{id:172,text:"\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064e\u0646\u0635\u064f\u0648\u0631\u064f\u0648\u0646\u064e",translation:"(yaitu) mereka itu pasti akan mendapat pertolongan"},{id:173,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u062c\u064f\u0646\u062f\u064e\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u063a\u064e\u0670\u0644\u0650\u0628\u064f\u0648\u0646\u064e",translation:"(Dan sesungguhnya bala tentara Kami742) itulah yang pasti menang"},{id:174,text:"\u0641\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062d\u0650\u064a\u0646\u0656",translation:"Maka berpalinglah engkau (Muhammad) dari mereka sampai waktu tertentu"},{id:175,text:"\u0648\u064e\u0623\u064e\u0628\u06e1\u0635\u0650\u0631\u06e1\u0647\u064f\u0645\u06e1 \u0641\u064e\u0633\u064e\u0648\u06e1\u0641\u064e \u064a\u064f\u0628\u06e1\u0635\u0650\u0631\u064f\u0648\u0646\u064e",translation:"dan perlihatkanlah kepada mereka, maka kelak mereka akan melihat (azab itu)"},{id:176,text:"\u0623\u064e\u0641\u064e\u0628\u0650\u0639\u064e\u0630\u064e\u0627\u0628\u0650\u0646\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0639\u06e1\u062c\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Maka apakah mereka meminta agar azab Kami disegerakan"},{id:177,text:"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0646\u064e\u0632\u064e\u0644\u064e \u0628\u0650\u0633\u064e\u0627\u062d\u064e\u062a\u0650\u0647\u0650\u0645\u06e1 \u0641\u064e\u0633\u064e\u0627\u0653\u0621\u064e \u0635\u064e\u0628\u064e\u0627\u062d\u064f \u0671\u0644\u06e1\u0645\u064f\u0646\u0630\u064e\u0631\u0650\u064a\u0646\u064e",translation:"Maka apabila (siksaan) itu turun di halaman mereka, maka sangat buruklah pagi hari bagi orang-orang yang diperingatkan"},{id:178,text:"\u0648\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062d\u0650\u064a\u0646\u0656",translation:"Dan berpalinglah engkau dari mereka sampai waktu tertentu"},{id:179,text:"\u0648\u064e\u0623\u064e\u0628\u06e1\u0635\u0650\u0631\u06e1 \u0641\u064e\u0633\u064e\u0648\u06e1\u0641\u064e \u064a\u064f\u0628\u06e1\u0635\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Dan perlihatkanlah, maka kelak mereka akan melihat (azab itu)"},{id:180,text:"\u0633\u064f\u0628\u06e1\u062d\u064e\u0670\u0646\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0631\u064e\u0628\u0651\u0650 \u0671\u0644\u06e1\u0639\u0650\u0632\u0651\u064e\u0629\u0650 \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064e\u0635\u0650\u0641\u064f\u0648\u0646\u064e",translation:"Mahasuci Tuhanmu, Tuhan Yang Mahaperkasa dari sifat yang mereka katakan"},{id:181,text:"\u0648\u064e\u0633\u064e\u0644\u064e\u0670\u0645\u064c \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0645\u064f\u0631\u06e1\u0633\u064e\u0644\u0650\u064a\u0646\u064e",translation:"Dan selamat sejahtera bagi para rasul"},{id:182,text:"\u0648\u064e\u0671\u0644\u06e1\u062d\u064e\u0645\u06e1\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0631\u064e\u0628\u0651\u0650 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Dan segala puji bagi Allah Tuhan seluruh alam"}]},{id:38,name:"\u0635",transliteration:"Sad",translation:"Shad",type:"meccan",total_verses:88,verses:[{id:1,text:"\u0635\u0653\u06da \u0648\u064e\u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u0650 \u0630\u0650\u064a \u0671\u0644\u0630\u0651\u0650\u0643\u06e1\u0631\u0650",translation:"\u1e62\u0101d, demi Alquran yang mengandung peringatan"},{id:2,text:"\u0628\u064e\u0644\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0639\u0650\u0632\u0651\u064e\u0629\u0656 \u0648\u064e\u0634\u0650\u0642\u064e\u0627\u0642\u0656",translation:"Tetapi orang-orang yang kafir (berada) dalam kesombongan dan permusuhan"},{id:3,text:"\u0643\u064e\u0645\u06e1 \u0623\u064e\u0647\u06e1\u0644\u064e\u0643\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u0645 \u0645\u0651\u0650\u0646 \u0642\u064e\u0631\u06e1\u0646\u0656 \u0641\u064e\u0646\u064e\u0627\u062f\u064e\u0648\u0627\u0652 \u0648\u0651\u064e\u0644\u064e\u0627\u062a\u064e \u062d\u0650\u064a\u0646\u064e \u0645\u064e\u0646\u064e\u0627\u0635\u0656",translation:"Betapa banyak umat sebelum mereka yang telah Kami binasakan, lalu mereka meminta tolong padahal (waktu itu) bukanlah saat untuk lari melepaskan diri"},{id:4,text:"\u0648\u064e\u0639\u064e\u062c\u0650\u0628\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645 \u0645\u0651\u064f\u0646\u0630\u0650\u0631\u065e \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u064f\u0648\u0646\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0633\u064e\u0670\u062d\u0650\u0631\u065e \u0643\u064e\u0630\u0651\u064e\u0627\u0628\u064c",translation:"Dan mereka heran karena mereka kedatangan seorang pemberi peringatan (rasul) dari kalangan mereka; dan orang-orang kafir berkata, \"Orang ini adalah pesihir yang banyak berdusta"},{id:5,text:"\u0623\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0671\u0644\u06e1\u0623\u0653\u0644\u0650\u0647\u064e\u0629\u064e \u0625\u0650\u0644\u064e\u0670\u0647\u0657\u0627 \u0648\u064e\u0670\u062d\u0650\u062f\u064b\u0627\u06d6 \u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0644\u064e\u0634\u064e\u064a\u06e1\u0621\u064c \u0639\u064f\u062c\u064e\u0627\u0628\u065e",translation:"Apakah dia menjadikan tuhan-tuhan itu Tuhan yang satu saja? Sungguh, ini benar-benar sesuatu yang sangat mengherankan"},{id:6,text:"\u0648\u064e\u0671\u0646\u0637\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0623\u064f \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0623\u064e\u0646\u0650 \u0671\u0645\u06e1\u0634\u064f\u0648\u0627\u0652 \u0648\u064e\u0671\u0635\u06e1\u0628\u0650\u0631\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0621\u064e\u0627\u0644\u0650\u0647\u064e\u062a\u0650\u0643\u064f\u0645\u06e1\u06d6 \u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0644\u064e\u0634\u064e\u064a\u06e1\u0621\u065e \u064a\u064f\u0631\u064e\u0627\u062f\u064f",translation:"Lalu pergilah pemimpin-pemimpin mereka (seraya berkata), \"Pergilah kamu dan tetaplah (menyembah) tuhan-tuhanmu, sesungguhnya ini benar-benar suatu hal yang dikehendaki"},{id:7,text:"\u0645\u064e\u0627 \u0633\u064e\u0645\u0650\u0639\u06e1\u0646\u064e\u0627 \u0628\u0650\u0647\u064e\u0670\u0630\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0645\u0650\u0644\u0651\u064e\u0629\u0650 \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0625\u0650\u0646\u06e1 \u0647\u064e\u0670\u0630\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u062e\u06e1\u062a\u0650\u0644\u064e\u0670\u0642\u064c",translation:"(Kami tidak pernah mendengar hal ini dalam agama yang terakhir,746) ini (mengesakan Allah), tidak lain hanyalah (dusta) yang diada-adakan"},{id:8,text:"\u0623\u064e\u0621\u064f\u0646\u0632\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0671\u0644\u0630\u0651\u0650\u0643\u06e1\u0631\u064f \u0645\u0650\u0646\u06e2 \u0628\u064e\u064a\u06e1\u0646\u0650\u0646\u064e\u0627\u06da \u0628\u064e\u0644\u06e1 \u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0634\u064e\u0643\u0651\u0656 \u0645\u0651\u0650\u0646 \u0630\u0650\u0643\u06e1\u0631\u0650\u064a\u06da \u0628\u064e\u0644 \u0644\u0651\u064e\u0645\u0651\u064e\u0627 \u064a\u064e\u0630\u064f\u0648\u0642\u064f\u0648\u0627\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u0650",translation:"mengapa Alquran itu diturunkan kepada Dia di antara kita?\" Sebenarnya mereka ragu-ragu terhadap Alquran-Ku, tetapi mereka belum merasakan azab(-Ku)"},{id:9,text:"\u0623\u064e\u0645\u06e1 \u0639\u0650\u0646\u062f\u064e\u0647\u064f\u0645\u06e1 \u062e\u064e\u0632\u064e\u0627\u0653\u0626\u0650\u0646\u064f \u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u0650 \u0671\u0644\u06e1\u0648\u064e\u0647\u0651\u064e\u0627\u0628\u0650",translation:"Atau apakah mereka itu mempunyai perbendaharaan rahmat Tuhanmu Yang Mahaperkasa, Maha Pemberi"},{id:10,text:"\u0623\u064e\u0645\u06e1 \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u064f\u0644\u06e1\u0643\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u064e\u0627\u06d6 \u0641\u064e\u0644\u06e1\u064a\u064e\u0631\u06e1\u062a\u064e\u0642\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0633\u06e1\u0628\u064e\u0670\u0628\u0650",translation:"Atau apakah mereka mempunyai kerajaan langit dan bumi dan apa yang ada di antara keduanya? (Jika ada), maka biarlah mereka menaiki tangga-tangga (ke langit)"},{id:11,text:"\u062c\u064f\u0646\u062f\u065e \u0645\u0651\u064e\u0627 \u0647\u064f\u0646\u064e\u0627\u0644\u0650\u0643\u064e \u0645\u064e\u0647\u06e1\u0632\u064f\u0648\u0645\u065e \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u062d\u06e1\u0632\u064e\u0627\u0628\u0650",translation:"(Mereka itu) kelompok besar bala tentara yang berada di sana yang akan dikalahkan"},{id:12,text:"\u0643\u064e\u0630\u0651\u064e\u0628\u064e\u062a\u06e1 \u0642\u064e\u0628\u06e1\u0644\u064e\u0647\u064f\u0645\u06e1 \u0642\u064e\u0648\u06e1\u0645\u064f \u0646\u064f\u0648\u062d\u0656 \u0648\u064e\u0639\u064e\u0627\u062f\u065e \u0648\u064e\u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064f \u0630\u064f\u0648 \u0671\u0644\u06e1\u0623\u064e\u0648\u06e1\u062a\u064e\u0627\u062f\u0650",translation:"Sebelum mereka itu, kaum Nuh, '\u0100d dan Fir'aun yang mempunyai bala tentara yang banyak, juga telah mendustakan (rasul-rasul)"},{id:13,text:"\u0648\u064e\u062b\u064e\u0645\u064f\u0648\u062f\u064f \u0648\u064e\u0642\u064e\u0648\u06e1\u0645\u064f \u0644\u064f\u0648\u0637\u0656 \u0648\u064e\u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0644\u06e1\u0640\u0654\u064e\u064a\u06e1\u0643\u064e\u0629\u0650\u06da \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0671\u0644\u06e1\u0623\u064e\u062d\u06e1\u0632\u064e\u0627\u0628\u064f",translation:"dan (begitu juga) Samud, kaum Lu\u1e6d dan penduduk Aikah.748) Mereka itulah golongan-golongan yang bersekutu (menentang rasul-rasul)"},{id:14,text:"\u0625\u0650\u0646 \u0643\u064f\u0644\u0651\u064c \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0671\u0644\u0631\u0651\u064f\u0633\u064f\u0644\u064e \u0641\u064e\u062d\u064e\u0642\u0651\u064e \u0639\u0650\u0642\u064e\u0627\u0628\u0650",translation:"Semua mereka itu mendustakan rasul-rasul, maka pantas mereka merasakan azab-Ku"},{id:15,text:"\u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0646\u0638\u064f\u0631\u064f \u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0635\u064e\u064a\u06e1\u062d\u064e\u0629\u0657 \u0648\u064e\u0670\u062d\u0650\u062f\u064e\u0629\u0657 \u0645\u0651\u064e\u0627 \u0644\u064e\u0647\u064e\u0627 \u0645\u0650\u0646 \u0641\u064e\u0648\u064e\u0627\u0642\u0656",translation:"Dan sebenarnya yang mereka tunggu adalah satu teriakan saja, yang tidak ada selanya"},{id:16,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0639\u064e\u062c\u0651\u0650\u0644 \u0644\u0651\u064e\u0646\u064e\u0627 \u0642\u0650\u0637\u0651\u064e\u0646\u064e\u0627 \u0642\u064e\u0628\u06e1\u0644\u064e \u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u062d\u0650\u0633\u064e\u0627\u0628\u0650",translation:"Dan mereka berkata, \"Ya Tuhan kami, segerakanlah azab yang diperuntukkan bagi kami sebelum hari perhitungan"},{id:17,text:"\u0671\u0635\u06e1\u0628\u0650\u0631\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0648\u064e\u0671\u0630\u06e1\u0643\u064f\u0631\u06e1 \u0639\u064e\u0628\u06e1\u062f\u064e\u0646\u064e\u0627 \u062f\u064e\u0627\u0648\u064f\u06e5\u062f\u064e \u0630\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u064a\u06e1\u062f\u0650\u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u0648\u0651\u064e\u0627\u0628\u064c",translation:"Bersabarlah atas apa yang mereka katakan; dan ingatlah akan hamba Kami Dawud yang mempunyai kekuatan; sungguh dia sangat taat (kepada Allah)"},{id:18,text:"\u0625\u0650\u0646\u0651\u064e\u0627 \u0633\u064e\u062e\u0651\u064e\u0631\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u062c\u0650\u0628\u064e\u0627\u0644\u064e \u0645\u064e\u0639\u064e\u0647\u064f\u06e5 \u064a\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u06e1\u0646\u064e \u0628\u0650\u0671\u0644\u06e1\u0639\u064e\u0634\u0650\u064a\u0651\u0650 \u0648\u064e\u0671\u0644\u06e1\u0625\u0650\u0634\u06e1\u0631\u064e\u0627\u0642\u0650",translation:"Sungguh, Kamilah yang menundukkan gunung-gunung untuk bertasbih bersama dia (Dawud) pada waktu petang dan pagi"},{id:19,text:"\u0648\u064e\u0671\u0644\u0637\u0651\u064e\u064a\u06e1\u0631\u064e \u0645\u064e\u062d\u06e1\u0634\u064f\u0648\u0631\u064e\u0629\u0657\u06d6 \u0643\u064f\u0644\u0651\u065e \u0644\u0651\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u0648\u0651\u064e\u0627\u0628\u065e",translation:"dan (Kami tundukkan pula) burung-burung dalam keadaan terkumpul. Masing-masing sangat taat (kepada Allah)"},{id:20,text:"\u0648\u064e\u0634\u064e\u062f\u064e\u062f\u06e1\u0646\u064e\u0627 \u0645\u064f\u0644\u06e1\u0643\u064e\u0647\u064f\u06e5 \u0648\u064e\u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f \u0671\u0644\u06e1\u062d\u0650\u0643\u06e1\u0645\u064e\u0629\u064e \u0648\u064e\u0641\u064e\u0635\u06e1\u0644\u064e \u0671\u0644\u06e1\u062e\u0650\u0637\u064e\u0627\u0628\u0650",translation:"(Dan Kami kuatkan kerajaannya dan Kami berikan hikmah kepadanya750) serta kebijaksanaan dalam memutuskan perkara"},{id:21,text:"\u06de\u0648\u064e\u0647\u064e\u0644\u06e1 \u0623\u064e\u062a\u064e\u0649\u0670\u0643\u064e \u0646\u064e\u0628\u064e\u0624\u064f\u0627\u0652 \u0671\u0644\u06e1\u062e\u064e\u0635\u06e1\u0645\u0650 \u0625\u0650\u0630\u06e1 \u062a\u064e\u0633\u064e\u0648\u0651\u064e\u0631\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0645\u0650\u062d\u06e1\u0631\u064e\u0627\u0628\u064e",translation:"Dan apakah telah sampai kepadamu berita orang-orang yang berselisih ketika mereka memanjat dinding mihrab"},{id:22,text:"\u0625\u0650\u0630\u06e1 \u062f\u064e\u062e\u064e\u0644\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u062f\u064e\u0627\u0648\u064f\u06e5\u062f\u064e \u0641\u064e\u0641\u064e\u0632\u0650\u0639\u064e \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1\u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u062a\u064e\u062e\u064e\u0641\u06e1\u06d6 \u062e\u064e\u0635\u06e1\u0645\u064e\u0627\u0646\u0650 \u0628\u064e\u063a\u064e\u0649\u0670 \u0628\u064e\u0639\u06e1\u0636\u064f\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u06e1\u0636\u0656 \u0641\u064e\u0671\u062d\u06e1\u0643\u064f\u0645 \u0628\u064e\u064a\u06e1\u0646\u064e\u0646\u064e\u0627 \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0634\u06e1\u0637\u0650\u0637\u06e1 \u0648\u064e\u0671\u0647\u06e1\u062f\u0650\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u0633\u064e\u0648\u064e\u0627\u0653\u0621\u0650 \u0671\u0644\u0635\u0651\u0650\u0631\u064e\u0670\u0637\u0650",translation:"ketika mereka masuk menemui Dawud lalu dia terkejut karena (kedatangan) mereka. Mereka berkata, \"Janganlah takut! (Kami) berdua sedang berselisih, sebagian dari kami berbuat zalim kepada yang lain; maka berilah keputusan di antara kami secara adil dan janganlah menyimpang dari kebenaran serta tunjukilah kami ke jalan yang lurus"},{id:23,text:"\u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0670\u0630\u064e\u0627\u0653 \u0623\u064e\u062e\u0650\u064a \u0644\u064e\u0647\u064f\u06e5 \u062a\u0650\u0633\u06e1\u0639\u065e \u0648\u064e\u062a\u0650\u0633\u06e1\u0639\u064f\u0648\u0646\u064e \u0646\u064e\u0639\u06e1\u062c\u064e\u0629\u0657 \u0648\u064e\u0644\u0650\u064a\u064e \u0646\u064e\u0639\u06e1\u062c\u064e\u0629\u065e \u0648\u064e\u0670\u062d\u0650\u062f\u064e\u0629\u065e \u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0643\u06e1\u0641\u0650\u0644\u06e1\u0646\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0639\u064e\u0632\u0651\u064e\u0646\u0650\u064a \u0641\u0650\u064a \u0671\u0644\u06e1\u062e\u0650\u0637\u064e\u0627\u0628\u0650",translation:"Sesungguhnya saudaraku ini mempunyai sembilan puluh sembilan ekor kambing betina dan aku mempunyai seekor saja, lalu dia berkata, \"Serahkanlah (kambingmu) itu kepadaku! Dan dia mengalahkan aku dalam perdebatan"},{id:24,text:"\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0642\u064e\u062f\u06e1 \u0638\u064e\u0644\u064e\u0645\u064e\u0643\u064e \u0628\u0650\u0633\u064f\u0624\u064e\u0627\u0644\u0650 \u0646\u064e\u0639\u06e1\u062c\u064e\u062a\u0650\u0643\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0646\u0650\u0639\u064e\u0627\u062c\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u062e\u064f\u0644\u064e\u0637\u064e\u0627\u0653\u0621\u0650 \u0644\u064e\u064a\u064e\u0628\u06e1\u063a\u0650\u064a \u0628\u064e\u0639\u06e1\u0636\u064f\u0647\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u06e1\u0636\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0648\u064e\u0642\u064e\u0644\u0650\u064a\u0644\u065e \u0645\u0651\u064e\u0627 \u0647\u064f\u0645\u06e1\u06d7 \u0648\u064e\u0638\u064e\u0646\u0651\u064e \u062f\u064e\u0627\u0648\u064f\u06e5\u062f\u064f \u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u0641\u064e\u062a\u064e\u0646\u0651\u064e\u0640\u0670\u0647\u064f \u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u063a\u06e1\u0641\u064e\u0631\u064e \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u06e5 \u0648\u064e\u062e\u064e\u0631\u0651\u064e\u06e4 \u0631\u064e\u0627\u0643\u0650\u0639\u0657\u0627\u06e4 \u0648\u064e\u0623\u064e\u0646\u064e\u0627\u0628\u064e\u06e9",translation:"Dia (Dawud) berkata, \"Sungguh, dia telah berbuat zalim kepadamu dengan meminta kambingmu itu untuk (ditambahkan) kepada kambingnya. Memang banyak di antara orang-orang yang bersekutu itu berbuat zalim kepada yang lain, kecuali orang-orang yang beriman dan mengerjakan kebajikan; dan hanya sedikitlah mereka yang begitu.\" Dan Dawud menduga bahwa Kami mengujinya; maka dia memohon ampunan kepada Tuhannya lalu menyungkur sujud dan bertobat"},{id:25,text:"\u0641\u064e\u063a\u064e\u0641\u064e\u0631\u06e1\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u06e5 \u0630\u064e\u0670\u0644\u0650\u0643\u064e\u06d6 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0644\u064e\u0647\u064f\u06e5 \u0639\u0650\u0646\u062f\u064e\u0646\u064e\u0627 \u0644\u064e\u0632\u064f\u0644\u06e1\u0641\u064e\u0649\u0670 \u0648\u064e\u062d\u064f\u0633\u06e1\u0646\u064e \u0645\u064e\u0640\u0654\u064e\u0627\u0628\u0656",translation:"Lalu Kami mengampuni (kesalahannya) itu. Dan sungguh, dia mempunyai kedudukan yang benar-benar dekat di sisi Kami dan tempat kembali yang baik"},{id:26,text:"\u064a\u064e\u0670\u062f\u064e\u0627\u0648\u064f\u06e5\u062f\u064f \u0625\u0650\u0646\u0651\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0670\u0643\u064e \u062e\u064e\u0644\u0650\u064a\u0641\u064e\u0629\u0657 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0641\u064e\u0671\u062d\u06e1\u0643\u064f\u0645 \u0628\u064e\u064a\u06e1\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u0650 \u0671\u0644\u06e1\u0647\u064e\u0648\u064e\u0649\u0670 \u0641\u064e\u064a\u064f\u0636\u0650\u0644\u0651\u064e\u0643\u064e \u0639\u064e\u0646 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0636\u0650\u0644\u0651\u064f\u0648\u0646\u064e \u0639\u064e\u0646 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u065e \u0634\u064e\u062f\u0650\u064a\u062f\u064f\u06e2 \u0628\u0650\u0645\u064e\u0627 \u0646\u064e\u0633\u064f\u0648\u0627\u0652 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u062d\u0650\u0633\u064e\u0627\u0628\u0650",translation:"(Allah berfirman), \"Wahai Dawud! Sesungguhnya engkau Kami jadikan khalifah (penguasa) di bumi, maka berilah keputusan (perkara) di antara manusia dengan adil dan janganlah engkau mengikuti hawa nafsu, karena akan menyesatkan engkau dari jalan Allah. Sungguh, orang-orang yang sesat dari jalan Allah akan mendapat azab yang berat, karena mereka melupakan hari perhitungan"},{id:27,text:"\u0648\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u06e1\u0646\u064e\u0627 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u064e \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0628\u064e\u0670\u0637\u0650\u0644\u0657\u0627\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0638\u064e\u0646\u0651\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652\u06da \u0641\u064e\u0648\u064e\u064a\u06e1\u0644\u065e \u0644\u0651\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650",translation:"Dan Kami tidak menciptakan langit dan bumi dan apa yang ada di antara keduanya dengan sia-sia. Itu anggapan orang-orang kafir, maka celakalah orang-orang yang kafir itu karena mereka akan masuk neraka"},{id:28,text:"\u0623\u064e\u0645\u06e1 \u0646\u064e\u062c\u06e1\u0639\u064e\u0644\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0643\u064e\u0671\u0644\u06e1\u0645\u064f\u0641\u06e1\u0633\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0623\u064e\u0645\u06e1 \u0646\u064e\u062c\u06e1\u0639\u064e\u0644\u064f \u0671\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e \u0643\u064e\u0671\u0644\u06e1\u0641\u064f\u062c\u0651\u064e\u0627\u0631\u0650",translation:"Pantaskah Kami memperlakukan orang-orang yang beriman dan mengerjakan kebajikan sama dengan orang-orang yang berbuat kerusakan di bumi? Atau pantaskah Kami mengangggap orang-orang yang bertakwa sama dengan orang-orang yang jahat"},{id:29,text:"\u0643\u0650\u062a\u064e\u0670\u0628\u064c \u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0645\u064f\u0628\u064e\u0670\u0631\u064e\u0643\u065e \u0644\u0651\u0650\u064a\u064e\u062f\u0651\u064e\u0628\u0651\u064e\u0631\u064f\u0648\u0653\u0627\u0652 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0647\u0650\u06e6 \u0648\u064e\u0644\u0650\u064a\u064e\u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064e \u0623\u064f\u0648\u0652\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0623\u064e\u0644\u06e1\u0628\u064e\u0670\u0628\u0650",translation:"Kitab (Alquran) yang Kami turunkan kepadamu penuh berkah agar mereka menghayati ayat-ayatnya dan agar orang-orang yang berakal sehat mendapat pelajaran"},{id:30,text:"\u0648\u064e\u0648\u064e\u0647\u064e\u0628\u06e1\u0646\u064e\u0627 \u0644\u0650\u062f\u064e\u0627\u0648\u064f\u06e5\u062f\u064e \u0633\u064f\u0644\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u064e\u06da \u0646\u0650\u0639\u06e1\u0645\u064e \u0671\u0644\u06e1\u0639\u064e\u0628\u06e1\u062f\u064f \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u0648\u0651\u064e\u0627\u0628\u064c",translation:"Dan kepada Dawud Kami karuniakan (anak bernama) Sulaiman; dia adalah sebaik-baik hamba. Sungguh, dia sangat taat (kepada Allah)"},{id:31,text:"\u0625\u0650\u0630\u06e1 \u0639\u064f\u0631\u0650\u0636\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0628\u0650\u0671\u0644\u06e1\u0639\u064e\u0634\u0650\u064a\u0651\u0650 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0641\u0650\u0646\u064e\u0670\u062a\u064f \u0671\u0644\u06e1\u062c\u0650\u064a\u064e\u0627\u062f\u064f",translation:"(Ingatlah) ketika suatu sore dipertunjukkan kepadanya (kuda-kuda) yang jinak, (tetapi) sangat cepat larinya"},{id:32,text:"\u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064e\u062d\u06e1\u0628\u064e\u0628\u06e1\u062a\u064f \u062d\u064f\u0628\u0651\u064e \u0671\u0644\u06e1\u062e\u064e\u064a\u06e1\u0631\u0650 \u0639\u064e\u0646 \u0630\u0650\u0643\u06e1\u0631\u0650 \u0631\u064e\u0628\u0651\u0650\u064a \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062a\u064e\u0648\u064e\u0627\u0631\u064e\u062a\u06e1 \u0628\u0650\u0671\u0644\u06e1\u062d\u0650\u062c\u064e\u0627\u0628\u0650",translation:"maka dia berkata, \"Sesungguhnya aku menyukai segala yang baik (kuda), yang membuat aku ingat akan (kebesaran) Tuhanku, sampai matahari terbenam"},{id:33,text:"\u0631\u064f\u062f\u0651\u064f\u0648\u0647\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0651\u064e\u06d6 \u0641\u064e\u0637\u064e\u0641\u0650\u0642\u064e \u0645\u064e\u0633\u06e1\u062d\u064e\u06e2\u0627 \u0628\u0650\u0671\u0644\u0633\u0651\u064f\u0648\u0642\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0639\u06e1\u0646\u064e\u0627\u0642\u0650",translation:"Bawalah semua kuda itu kembali kepadaku.\" Lalu dia mengusap-usap kaki dan leher kuda itu"},{id:34,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0641\u064e\u062a\u064e\u0646\u0651\u064e\u0627 \u0633\u064f\u0644\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u064e \u0648\u064e\u0623\u064e\u0644\u06e1\u0642\u064e\u064a\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0631\u06e1\u0633\u0650\u064a\u0651\u0650\u0647\u0650\u06e6 \u062c\u064e\u0633\u064e\u062f\u0657\u0627 \u062b\u064f\u0645\u0651\u064e \u0623\u064e\u0646\u064e\u0627\u0628\u064e",translation:"Dan sungguh, Kami telah menguji Sulaiman dan Kami jadikan (dia) tergeletak di atas kursinya sebagai tubuh (yang lemah karena sakit), kemudian dia bertobat"},{id:35,text:"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0671\u063a\u06e1\u0641\u0650\u0631\u06e1 \u0644\u0650\u064a \u0648\u064e\u0647\u064e\u0628\u06e1 \u0644\u0650\u064a \u0645\u064f\u0644\u06e1\u0643\u0657\u0627 \u0644\u0651\u064e\u0627 \u064a\u064e\u0646\u06e2\u0628\u064e\u063a\u0650\u064a \u0644\u0650\u0623\u064e\u062d\u064e\u062f\u0656 \u0645\u0651\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u064a\u0653\u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0623\u064e\u0646\u062a\u064e \u0671\u0644\u06e1\u0648\u064e\u0647\u0651\u064e\u0627\u0628\u064f",translation:"Dia berkata, \"Ya Tuhanku, ampunilah aku dan anugerahkanlah kepadaku kerajaan yang tidak dimiliki oleh siapa pun setelahku. Sungguh, Engkaulah Yang Maha Pemberi"},{id:36,text:"\u0641\u064e\u0633\u064e\u062e\u0651\u064e\u0631\u06e1\u0646\u064e\u0627 \u0644\u064e\u0647\u064f \u0671\u0644\u0631\u0651\u0650\u064a\u062d\u064e \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0628\u0650\u0623\u064e\u0645\u06e1\u0631\u0650\u0647\u0650\u06e6 \u0631\u064f\u062e\u064e\u0627\u0653\u0621\u064b \u062d\u064e\u064a\u06e1\u062b\u064f \u0623\u064e\u0635\u064e\u0627\u0628\u064e",translation:"Kemudian Kami tundukkan kepadanya angin yang berhembus dengan baik menurut perintahnya ke mana saja yang dikehendakinya"},{id:37,text:"\u0648\u064e\u0671\u0644\u0634\u0651\u064e\u064a\u064e\u0670\u0637\u0650\u064a\u0646\u064e \u0643\u064f\u0644\u0651\u064e \u0628\u064e\u0646\u0651\u064e\u0627\u0653\u0621\u0656 \u0648\u064e\u063a\u064e\u0648\u0651\u064e\u0627\u0635\u0656",translation:"dan (Kami tundukkan pula kepadanya) setan-setan, semuanya ahli bangunan dan penyelam"},{id:38,text:"\u0648\u064e\u0621\u064e\u0627\u062e\u064e\u0631\u0650\u064a\u0646\u064e \u0645\u064f\u0642\u064e\u0631\u0651\u064e\u0646\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0635\u06e1\u0641\u064e\u0627\u062f\u0650",translation:"dan (setan) lain yang terikat dalam belenggu"},{id:39,text:"\u0647\u064e\u0670\u0630\u064e\u0627 \u0639\u064e\u0637\u064e\u0627\u0653\u0624\u064f\u0646\u064e\u0627 \u0641\u064e\u0671\u0645\u06e1\u0646\u064f\u0646\u06e1 \u0623\u064e\u0648\u06e1 \u0623\u064e\u0645\u06e1\u0633\u0650\u0643\u06e1 \u0628\u0650\u063a\u064e\u064a\u06e1\u0631\u0650 \u062d\u0650\u0633\u064e\u0627\u0628\u0656",translation:"Inilah anugerah Kami; maka berikanlah (kepada orang lain) atau tahanlah (untuk dirimu sendiri) tanpa perhitungan"},{id:40,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0644\u064e\u0647\u064f\u06e5 \u0639\u0650\u0646\u062f\u064e\u0646\u064e\u0627 \u0644\u064e\u0632\u064f\u0644\u06e1\u0641\u064e\u0649\u0670 \u0648\u064e\u062d\u064f\u0633\u06e1\u0646\u064e \u0645\u064e\u0640\u0654\u064e\u0627\u0628\u0656",translation:"Dan sungguh, dia mempunyai kedudukan yang dekat pada sisi Kami dan tempat kembali yang baik"},{id:41,text:"\u0648\u064e\u0671\u0630\u06e1\u0643\u064f\u0631\u06e1 \u0639\u064e\u0628\u06e1\u062f\u064e\u0646\u064e\u0627\u0653 \u0623\u064e\u064a\u0651\u064f\u0648\u0628\u064e \u0625\u0650\u0630\u06e1 \u0646\u064e\u0627\u062f\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u0646\u0651\u0650\u064a \u0645\u064e\u0633\u0651\u064e\u0646\u0650\u064a\u064e \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u064f \u0628\u0650\u0646\u064f\u0635\u06e1\u0628\u0656 \u0648\u064e\u0639\u064e\u0630\u064e\u0627\u0628\u064d",translation:"Dan ingatlah akan hamba Kami Ayyub ketika dia menyeru Tuhannya, \"Sesungguhnya aku diganggu setan dengan penderitaan dan bencana"},{id:42,text:"\u0671\u0631\u06e1\u0643\u064f\u0636\u06e1 \u0628\u0650\u0631\u0650\u062c\u06e1\u0644\u0650\u0643\u064e\u06d6 \u0647\u064e\u0670\u0630\u064e\u0627 \u0645\u064f\u063a\u06e1\u062a\u064e\u0633\u064e\u0644\u064f\u06e2 \u0628\u064e\u0627\u0631\u0650\u062f\u065e \u0648\u064e\u0634\u064e\u0631\u064e\u0627\u0628\u065e",translation:"(Allah berfirman), \"Hentakkanlah kakimu; inilah air yang sejuk untuk mandi dan untuk minum"},{id:43,text:"\u0648\u064e\u0648\u064e\u0647\u064e\u0628\u06e1\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u0647\u06e1\u0644\u064e\u0647\u064f\u06e5 \u0648\u064e\u0645\u0650\u062b\u06e1\u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u0639\u064e\u0647\u064f\u0645\u06e1 \u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u0657 \u0645\u0651\u0650\u0646\u0651\u064e\u0627 \u0648\u064e\u0630\u0650\u0643\u06e1\u0631\u064e\u0649\u0670 \u0644\u0650\u0623\u064f\u0648\u0652\u0644\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0644\u06e1\u0628\u064e\u0670\u0628\u0650",translation:"Dan Kami anugerahi dia (dengan mengumpulkan kembali) keluarganya dan Kami lipat gandakan jumlah mereka, sebagai rahmat dari Kami dan pelajaran bagi orang-orang yang berpikiran sehat"},{id:44,text:"\u0648\u064e\u062e\u064f\u0630\u06e1 \u0628\u0650\u064a\u064e\u062f\u0650\u0643\u064e \u0636\u0650\u063a\u06e1\u062b\u0657\u0627 \u0641\u064e\u0671\u0636\u06e1\u0631\u0650\u0628 \u0628\u0651\u0650\u0647\u0650\u06e6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062d\u06e1\u0646\u064e\u062b\u06e1\u06d7 \u0625\u0650\u0646\u0651\u064e\u0627 \u0648\u064e\u062c\u064e\u062f\u06e1\u0646\u064e\u0670\u0647\u064f \u0635\u064e\u0627\u0628\u0650\u0631\u0657\u0627\u06da \u0646\u0651\u0650\u0639\u06e1\u0645\u064e \u0671\u0644\u06e1\u0639\u064e\u0628\u06e1\u062f\u064f \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u0648\u0651\u064e\u0627\u0628\u065e",translation:"Dan ambillah seikat (rumput) dengan tanganmu, lalu pukullah dengan itu dan janganlah engkau melanggar sumpah. Sesungguhnya Kami dapati dia (Ayyub) seorang yang sabar. Dialah sebaik-baik hamba. Sungguh, dia sangat taat (kepada Allah)"},{id:45,text:"\u0648\u064e\u0671\u0630\u06e1\u0643\u064f\u0631\u06e1 \u0639\u0650\u0628\u064e\u0670\u062f\u064e\u0646\u064e\u0627\u0653 \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064e \u0648\u064e\u0625\u0650\u0633\u06e1\u062d\u064e\u0670\u0642\u064e \u0648\u064e\u064a\u064e\u0639\u06e1\u0642\u064f\u0648\u0628\u064e \u0623\u064f\u0648\u0652\u0644\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u064a\u06e1\u062f\u0650\u064a \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0628\u06e1\u0635\u064e\u0670\u0631\u0650",translation:"Dan ingatlah hamba-hamba Kami: Ibrahim, Ishak dan Yakub yang mempunyai kekuatan-kekuatan yang besar dan ilmu-ilmu (yang tinggi)"},{id:46,text:"\u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u062e\u06e1\u0644\u064e\u0635\u06e1\u0646\u064e\u0670\u0647\u064f\u0645 \u0628\u0650\u062e\u064e\u0627\u0644\u0650\u0635\u064e\u0629\u0656 \u0630\u0650\u0643\u06e1\u0631\u064e\u0649 \u0671\u0644\u062f\u0651\u064e\u0627\u0631\u0650",translation:"Sungguh, Kami telah menyucikan mereka dengan (menganugerahkan) akhlak yang tinggi kepadanya yaitu selalu mengingatkan (manusia) kepada negeri akhirat"},{id:47,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0639\u0650\u0646\u062f\u064e\u0646\u064e\u0627 \u0644\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0635\u06e1\u0637\u064e\u0641\u064e\u064a\u06e1\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u062e\u06e1\u064a\u064e\u0627\u0631\u0650",translation:"Dan sungguh, di sisi Kami mereka termasuk orang-orang pilihan yang paling baik"},{id:48,text:"\u0648\u064e\u0671\u0630\u06e1\u0643\u064f\u0631\u06e1 \u0625\u0650\u0633\u06e1\u0645\u064e\u0670\u0639\u0650\u064a\u0644\u064e \u0648\u064e\u0671\u0644\u06e1\u064a\u064e\u0633\u064e\u0639\u064e \u0648\u064e\u0630\u064e\u0627 \u0671\u0644\u06e1\u0643\u0650\u0641\u06e1\u0644\u0650\u06d6 \u0648\u064e\u0643\u064f\u0644\u0651\u065e \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u062e\u06e1\u064a\u064e\u0627\u0631\u0650",translation:"Dan ingatlah Ismail, Ilyasa' dan Zulkifli. Semuanya termasuk orang-orang yang terbaik"},{id:49,text:"\u0647\u064e\u0670\u0630\u064e\u0627 \u0630\u0650\u0643\u06e1\u0631\u065e\u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0644\u0650\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e \u0644\u064e\u062d\u064f\u0633\u06e1\u0646\u064e \u0645\u064e\u0640\u0654\u064e\u0627\u0628\u0656",translation:"Ini adalah kehormatan (bagi mereka). Dan sungguh, bagi orang-orang yang bertakwa (disediakan) tempat kembali yang terbaik"},{id:50,text:"\u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0650 \u0639\u064e\u062f\u06e1\u0646\u0656 \u0645\u0651\u064f\u0641\u064e\u062a\u0651\u064e\u062d\u064e\u0629\u0657 \u0644\u0651\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u0628\u06e1\u0648\u064e\u0670\u0628\u064f",translation:"(yaitu) surga 'Adn yang pintu-pintunya terbuka bagi mereka"},{id:51,text:"\u0645\u064f\u062a\u0651\u064e\u0643\u0650\u0640\u0654\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u064a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0628\u0650\u0641\u064e\u0670\u0643\u0650\u0647\u064e\u0629\u0656 \u0643\u064e\u062b\u0650\u064a\u0631\u064e\u0629\u0656 \u0648\u064e\u0634\u064e\u0631\u064e\u0627\u0628\u0656",translation:"di dalamnya mereka bersandar (di atas dipan-dipan) sambil meminta buah-buahan yang banyak dan minuman (di surga itu)"},{id:52,text:"\u06de\u0648\u064e\u0639\u0650\u0646\u062f\u064e\u0647\u064f\u0645\u06e1 \u0642\u064e\u0670\u0635\u0650\u0631\u064e\u0670\u062a\u064f \u0671\u0644\u0637\u0651\u064e\u0631\u06e1\u0641\u0650 \u0623\u064e\u062a\u06e1\u0631\u064e\u0627\u0628\u064c",translation:"dan di samping mereka (ada bidadari-bidadari) yang redup pandangannya dan sebaya umurnya"},{id:53,text:"\u0647\u064e\u0670\u0630\u064e\u0627 \u0645\u064e\u0627 \u062a\u064f\u0648\u0639\u064e\u062f\u064f\u0648\u0646\u064e \u0644\u0650\u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u062d\u0650\u0633\u064e\u0627\u0628\u0650",translation:"Inilah apa yang dijanjikan kepadamu pada hari perhitungan"},{id:54,text:"\u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0644\u064e\u0631\u0650\u0632\u06e1\u0642\u064f\u0646\u064e\u0627 \u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646 \u0646\u0651\u064e\u0641\u064e\u0627\u062f\u064d",translation:"Sungguh, inilah rezeki dari Kami yang tidak ada habis-habisnya"},{id:55,text:"\u0647\u064e\u0670\u0630\u064e\u0627\u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0644\u0650\u0644\u0637\u0651\u064e\u0640\u0670\u063a\u0650\u064a\u0646\u064e \u0644\u064e\u0634\u064e\u0631\u0651\u064e \u0645\u064e\u0640\u0654\u064e\u0627\u0628\u0656",translation:"Beginilah (keadaan mereka). Dan sungguh, bagi orang-orang yang durhaka pasti (disediakan) tempat kembali yang buruk"},{id:56,text:"\u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u064a\u064e\u0635\u06e1\u0644\u064e\u0648\u06e1\u0646\u064e\u0647\u064e\u0627 \u0641\u064e\u0628\u0650\u0626\u06e1\u0633\u064e \u0671\u0644\u06e1\u0645\u0650\u0647\u064e\u0627\u062f\u064f",translation:"(yaitu) neraka Jahanam yang mereka masuki; maka itulah seburuk-buruk tempat tinggal"},{id:57,text:"\u0647\u064e\u0670\u0630\u064e\u0627 \u0641\u064e\u0644\u06e1\u064a\u064e\u0630\u064f\u0648\u0642\u064f\u0648\u0647\u064f \u062d\u064e\u0645\u0650\u064a\u0645\u065e \u0648\u064e\u063a\u064e\u0633\u0651\u064e\u0627\u0642\u065e",translation:"Inilah (azab neraka), maka biarlah mereka merasakannya, (minuman mereka) air yang sangat panas dan air yang sangat dingin"},{id:58,text:"\u0648\u064e\u0621\u064e\u0627\u062e\u064e\u0631\u064f \u0645\u0650\u0646 \u0634\u064e\u0643\u06e1\u0644\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u064c",translation:"dan berbagai macam (azab) yang lain yang serupa itu"},{id:59,text:"\u0647\u064e\u0670\u0630\u064e\u0627 \u0641\u064e\u0648\u06e1\u062c\u065e \u0645\u0651\u064f\u0642\u06e1\u062a\u064e\u062d\u0650\u0645\u065e \u0645\u0651\u064e\u0639\u064e\u0643\u064f\u0645\u06e1 \u0644\u064e\u0627 \u0645\u064e\u0631\u06e1\u062d\u064e\u0628\u064e\u06e2\u0627 \u0628\u0650\u0647\u0650\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0635\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650",translation:"(Dikatakan kepada mereka), \"Ini rombongan besar (pengikut-pengikutmu) yang masuk berdesak-desak bersama kamu (ke neraka).\" Tidak ada ucapan selamat datang bagi mereka karena sesungguhnya mereka akan masuk neraka (kata pemimpin-pemimpin mereka)"},{id:60,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0628\u064e\u0644\u06e1 \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0644\u064e\u0627 \u0645\u064e\u0631\u06e1\u062d\u064e\u0628\u064e\u06e2\u0627 \u0628\u0650\u0643\u064f\u0645\u06e1\u06d6 \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0642\u064e\u062f\u0651\u064e\u0645\u06e1\u062a\u064f\u0645\u064f\u0648\u0647\u064f \u0644\u064e\u0646\u064e\u0627\u06d6 \u0641\u064e\u0628\u0650\u0626\u06e1\u0633\u064e \u0671\u0644\u06e1\u0642\u064e\u0631\u064e\u0627\u0631\u064f",translation:"(Para pengikut mereka menjawab), \"Sebenarnya kamulah yang (lebih pantas) tidak menerima ucapan selamat datang, karena kamulah yang menjerumuskan kami ke dalam azab, maka itulah seburuk-buruk tempat menetap"},{id:61,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0645\u064e\u0646 \u0642\u064e\u062f\u0651\u064e\u0645\u064e \u0644\u064e\u0646\u064e\u0627 \u0647\u064e\u0670\u0630\u064e\u0627 \u0641\u064e\u0632\u0650\u062f\u06e1\u0647\u064f \u0639\u064e\u0630\u064e\u0627\u0628\u0657\u0627 \u0636\u0650\u0639\u06e1\u0641\u0657\u0627 \u0641\u0650\u064a \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650",translation:"Mereka berkata (lagi), \"Ya Tuhan kami, barangsiapa menjerumuskan kami ke dalam (azab) ini, maka tambahkanlah azab kepadanya dua kali lipat di dalam neraka"},{id:62,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u0644\u064e\u0646\u064e\u0627 \u0644\u064e\u0627 \u0646\u064e\u0631\u064e\u0649\u0670 \u0631\u0650\u062c\u064e\u0627\u0644\u0657\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0646\u064e\u0639\u064f\u062f\u0651\u064f\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u0634\u06e1\u0631\u064e\u0627\u0631\u0650",translation:"Dan (orang-orang durhaka) berkata, \"Mengapa kami tidak melihat orang-orang yang dahulu (di dunia) kami anggap sebagai orang-orang yang jahat (hina)"},{id:63,text:"\u0623\u064e\u062a\u0651\u064e\u062e\u064e\u0630\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0633\u0650\u062e\u06e1\u0631\u0650\u064a\u0651\u064b\u0627 \u0623\u064e\u0645\u06e1 \u0632\u064e\u0627\u063a\u064e\u062a\u06e1 \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u0628\u06e1\u0635\u064e\u0670\u0631\u064f",translation:"Dahulu kami menjadikan mereka olok-olokan, ataukah karena penglihatan kami yang tidak melihat mereka"},{id:64,text:"\u0625\u0650\u0646\u0651\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u062d\u064e\u0642\u0651\u065e \u062a\u064e\u062e\u064e\u0627\u0635\u064f\u0645\u064f \u0623\u064e\u0647\u06e1\u0644\u0650 \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650",translation:"Sungguh, yang demikian benar-benar terjadi, (yaitu) pertengkaran di antara penghuni neraka"},{id:65,text:"\u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u064e\u0627\u06e0 \u0645\u064f\u0646\u0630\u0650\u0631\u065e\u06d6 \u0648\u064e\u0645\u064e\u0627 \u0645\u0650\u0646\u06e1 \u0625\u0650\u0644\u064e\u0670\u0647\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u0648\u064e\u0670\u062d\u0650\u062f\u064f \u0671\u0644\u06e1\u0642\u064e\u0647\u0651\u064e\u0627\u0631\u064f",translation:"Katakanlah (Muhammad), \"Sesungguhnya aku hanya seorang pemberi peringatan, tidak ada tuhan selain Allah Yang Maha Esa, Mahaperkasa"},{id:66,text:"\u0631\u064e\u0628\u0651\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0671\u0644\u06e1\u063a\u064e\u0641\u0651\u064e\u0640\u0670\u0631\u064f",translation:"(yaitu) Tuhan langit dan bumi dan apa yang ada di antara keduanya, Yang Mahaperkasa, Maha Pengampun"},{id:67,text:"\u0642\u064f\u0644\u06e1 \u0647\u064f\u0648\u064e \u0646\u064e\u0628\u064e\u0624\u064c\u0627\u0652 \u0639\u064e\u0638\u0650\u064a\u0645\u064c",translation:"Katakanlah, \"Itu (Alquran) adalah berita besar"},{id:68,text:"\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0639\u064e\u0646\u06e1\u0647\u064f \u0645\u064f\u0639\u06e1\u0631\u0650\u0636\u064f\u0648\u0646\u064e",translation:"yang kamu berpaling darinya"},{id:69,text:"\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u064a\u064e \u0645\u0650\u0646\u06e1 \u0639\u0650\u0644\u06e1\u0645\u0650\u06ed \u0628\u0650\u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0625\u0650 \u0671\u0644\u06e1\u0623\u064e\u0639\u06e1\u0644\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u06e1 \u064a\u064e\u062e\u06e1\u062a\u064e\u0635\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Aku tidak mempunyai pengetahuan sedikit pun tentang al-malaul a'l\u0101 (malaikat) ketika mereka berbantah-bantahan"},{id:70,text:"\u0625\u0650\u0646 \u064a\u064f\u0648\u062d\u064e\u0649\u0670\u0653 \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u064e\u0627\u06e0 \u0646\u064e\u0630\u0650\u064a\u0631\u065e \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u064c",translation:"Yang diwahyukan kepadaku, bahwa aku hanyalah seorang pemberi peringatan yang nyata"},{id:71,text:"\u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0644\u0650\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u0650 \u0625\u0650\u0646\u0651\u0650\u064a \u062e\u064e\u0670\u0644\u0650\u0642\u064f\u06e2 \u0628\u064e\u0634\u064e\u0631\u0657\u0627 \u0645\u0651\u0650\u0646 \u0637\u0650\u064a\u0646\u0656",translation:"(Ingatlah) ketika Tuhanmu berfirman kepada malaikat, \"Sesungguhnya Aku akan menciptakan manusia dari tanah"},{id:72,text:"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0633\u064e\u0648\u0651\u064e\u064a\u06e1\u062a\u064f\u0647\u064f\u06e5 \u0648\u064e\u0646\u064e\u0641\u064e\u062e\u06e1\u062a\u064f \u0641\u0650\u064a\u0647\u0650 \u0645\u0650\u0646 \u0631\u0651\u064f\u0648\u062d\u0650\u064a \u0641\u064e\u0642\u064e\u0639\u064f\u0648\u0627\u0652 \u0644\u064e\u0647\u064f\u06e5 \u0633\u064e\u0670\u062c\u0650\u062f\u0650\u064a\u0646\u064e",translation:"Kemudian apabila telah Aku sempurnakan kejadiannya dan Aku tiupkan roh (ciptaan)-Ku kepadanya; maka tunduklah kamu dengan bersujud kepadanya"},{id:73,text:"\u0641\u064e\u0633\u064e\u062c\u064e\u062f\u064e \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u064f \u0643\u064f\u0644\u0651\u064f\u0647\u064f\u0645\u06e1 \u0623\u064e\u062c\u06e1\u0645\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Lalu para malaikat itu bersujud semuanya"},{id:74,text:"\u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0625\u0650\u0628\u06e1\u0644\u0650\u064a\u0633\u064e \u0671\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u064e\u0631\u064e \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"kecuali iblis; ia menyombongkan diri dan ia termasuk golongan yang kafir"},{id:75,text:"\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0640\u0670\u0653\u0625\u0650\u0628\u06e1\u0644\u0650\u064a\u0633\u064f \u0645\u064e\u0627 \u0645\u064e\u0646\u064e\u0639\u064e\u0643\u064e \u0623\u064e\u0646 \u062a\u064e\u0633\u06e1\u062c\u064f\u062f\u064e \u0644\u0650\u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u06e1\u062a\u064f \u0628\u0650\u064a\u064e\u062f\u064e\u064a\u0651\u064e\u06d6 \u0623\u064e\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u064e\u0631\u06e1\u062a\u064e \u0623\u064e\u0645\u06e1 \u0643\u064f\u0646\u062a\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0639\u064e\u0627\u0644\u0650\u064a\u0646\u064e",translation:"(Allah) berfirman, \"Wahai iblis, apakah yang menghalangi kamu sujud kepada yang telah Aku ciptakan dengan kedua tangan-Ku. Apakah kamu menyombongkan diri atau kamu (merasa) termasuk golongan yang (lebih) tinggi"},{id:76,text:"\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0646\u064e\u0627\u06e0 \u062e\u064e\u064a\u06e1\u0631\u065e \u0645\u0651\u0650\u0646\u06e1\u0647\u064f \u062e\u064e\u0644\u064e\u0642\u06e1\u062a\u064e\u0646\u0650\u064a \u0645\u0650\u0646 \u0646\u0651\u064e\u0627\u0631\u0656 \u0648\u064e\u062e\u064e\u0644\u064e\u0642\u06e1\u062a\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646 \u0637\u0650\u064a\u0646\u0656",translation:"(Iblis) berkata, \"Aku lebih baik darinya, karena Engkau ciptakan aku dari api, sedangkan dia Engkau ciptakan dari tanah"},{id:77,text:"\u0642\u064e\u0627\u0644\u064e \u0641\u064e\u0671\u062e\u06e1\u0631\u064f\u062c\u06e1 \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0631\u064e\u062c\u0650\u064a\u0645\u065e",translation:"(Allah) berfirman, \"Kalau begitu keluarlah kamu dari surga! Sesungguhnya kamu adalah makhluk yang terkutuk"},{id:78,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0644\u064e\u0639\u06e1\u0646\u064e\u062a\u0650\u064a\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u0650",translation:"Dan sungguh, kutukan-Ku tetap atasmu sampai hari pembalasan"},{id:79,text:"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0641\u064e\u0623\u064e\u0646\u0638\u0650\u0631\u06e1\u0646\u0650\u064a\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u06e1\u0645\u0650 \u064a\u064f\u0628\u06e1\u0639\u064e\u062b\u064f\u0648\u0646\u064e",translation:"(Iblis) berkata, \"Ya Tuhanku, tangguhkanlah aku sampai pada hari mereka dibangkitkan"},{id:80,text:"\u0642\u064e\u0627\u0644\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0646\u0638\u064e\u0631\u0650\u064a\u0646\u064e",translation:"(Allah) berfirman, \"Maka sesungguhnya kamu termasuk golongan yang diberi penangguhan"},{id:81,text:"\u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0648\u064e\u0642\u06e1\u062a\u0650 \u0671\u0644\u06e1\u0645\u064e\u0639\u06e1\u0644\u064f\u0648\u0645\u0650",translation:"sampai pada hari yang telah ditentukan waktunya (hari Kiamat)"},{id:82,text:"\u0642\u064e\u0627\u0644\u064e \u0641\u064e\u0628\u0650\u0639\u0650\u0632\u0651\u064e\u062a\u0650\u0643\u064e \u0644\u064e\u0623\u064f\u063a\u06e1\u0648\u0650\u064a\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u062c\u06e1\u0645\u064e\u0639\u0650\u064a\u0646\u064e",translation:"(Iblis) menjawab, \"Demi kemuliaan-Mu, pasti aku akan menyesatkan mereka semuanya"},{id:83,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u0650\u0628\u064e\u0627\u062f\u064e\u0643\u064e \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064f\u062e\u06e1\u0644\u064e\u0635\u0650\u064a\u0646\u064e",translation:"kecuali hamba-hamba-Mu yang terpilih di antara mereka"},{id:84,text:"\u0642\u064e\u0627\u0644\u064e \u0641\u064e\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f \u0648\u064e\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064e \u0623\u064e\u0642\u064f\u0648\u0644\u064f",translation:"(Allah) berfirman, \"Maka yang benar (adalah sumpahku), dan hanya kebenaran itulah yang Aku katakan"},{id:85,text:"\u0644\u064e\u0623\u064e\u0645\u06e1\u0644\u064e\u0623\u064e\u0646\u0651\u064e \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0645\u0650\u0646\u0643\u064e \u0648\u064e\u0645\u0650\u0645\u0651\u064e\u0646 \u062a\u064e\u0628\u0650\u0639\u064e\u0643\u064e \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0623\u064e\u062c\u06e1\u0645\u064e\u0639\u0650\u064a\u0646\u064e",translation:"Sungguh, Aku akan memenuhi neraka Jahanam dengan kamu dan dengan orang-orang yang mengikutimu di antara mereka semuanya"},{id:86,text:"\u0642\u064f\u0644\u06e1 \u0645\u064e\u0627\u0653 \u0623\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0643\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0645\u0650\u0646\u06e1 \u0623\u064e\u062c\u06e1\u0631\u0656 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u064e\u0627\u06e0 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u062a\u064e\u0643\u064e\u0644\u0651\u0650\u0641\u0650\u064a\u0646\u064e",translation:"Katakanlah (Muhammad), \"Aku tidak meminta imbalan sedikit pun kepadamu atasnya (dakwahku); dan aku bukanlah termasuk orang yang mengada-ada"},{id:87,text:"\u0625\u0650\u0646\u06e1 \u0647\u064f\u0648\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0630\u0650\u0643\u06e1\u0631\u065e \u0644\u0651\u0650\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"(Alquran) ini tidak lain hanyalah peringatan bagi seluruh alam"},{id:88,text:"\u0648\u064e\u0644\u064e\u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0646\u0651\u064e \u0646\u064e\u0628\u064e\u0623\u064e\u0647\u064f\u06e5 \u0628\u064e\u0639\u06e1\u062f\u064e \u062d\u0650\u064a\u0646\u0650\u06ed",translation:"Dan sungguh, kamu akan mengetahui (kebenaran) beritanya Alquran setelah beberapa waktu lagi"}]},{id:39,name:"\u0627\u0644\u0632\u0645\u0631",transliteration:"Az-Zumar",translation:"Para Rombongan",type:"meccan",total_verses:75,verses:[{id:1,text:"\u062a\u064e\u0646\u0632\u0650\u064a\u0644\u064f \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0645\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u0650 \u0671\u0644\u06e1\u062d\u064e\u0643\u0650\u064a\u0645\u0650",translation:"Kitab (Alquran) ini diturunkan oleh Allah Yang Mahamulia, Mahabijaksana"},{id:2,text:"\u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0641\u064e\u0671\u0639\u06e1\u0628\u064f\u062f\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064f\u062e\u06e1\u0644\u0650\u0635\u0657\u0627 \u0644\u0651\u064e\u0647\u064f \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u064e",translation:"Sesungguhnya Kami menurunkan Kitab (Alquran) kepadamu (Muhammad) dengan (membawa) kebenaran. Maka sembahlah Allah dengan tulus ikhlas beragama kepada-Nya"},{id:3,text:"\u0623\u064e\u0644\u064e\u0627 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u064f \u0671\u0644\u06e1\u062e\u064e\u0627\u0644\u0650\u0635\u064f\u06da \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0648\u06e1\u0644\u0650\u064a\u064e\u0627\u0653\u0621\u064e \u0645\u064e\u0627 \u0646\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u0644\u0650\u064a\u064f\u0642\u064e\u0631\u0651\u0650\u0628\u064f\u0648\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0632\u064f\u0644\u06e1\u0641\u064e\u0649\u0670\u0653 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u062d\u06e1\u0643\u064f\u0645\u064f \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0645\u064e\u0627 \u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u0650 \u064a\u064e\u062e\u06e1\u062a\u064e\u0644\u0650\u0641\u064f\u0648\u0646\u064e\u06d7 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064e\u0647\u06e1\u062f\u0650\u064a \u0645\u064e\u0646\u06e1 \u0647\u064f\u0648\u064e \u0643\u064e\u0670\u0630\u0650\u0628\u065e \u0643\u064e\u0641\u0651\u064e\u0627\u0631\u065e",translation:"Ingatlah! Hanya milik Allah agama yang murni (dari syirik). Dan orang-orang yang mengambil pelindung selain Dia (berkata), \"Kami tidak menyembah mereka melainkan (berharap) agar mereka mendekatkan kami kepada Allah dengan sedekat-dekatnya.\" Sungguh, Allah akan memberi putusan di antara mereka tentang apa yang mereka perselisihkan. Sungguh, Allah tidak memberi petunjuk kepada pendusta dan orang yang sangat ingkar"},{id:4,text:"\u0644\u0651\u064e\u0648\u06e1 \u0623\u064e\u0631\u064e\u0627\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0646 \u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064e \u0648\u064e\u0644\u064e\u062f\u0657\u0627 \u0644\u0651\u064e\u0671\u0635\u06e1\u0637\u064e\u0641\u064e\u0649\u0670 \u0645\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u062e\u06e1\u0644\u064f\u0642\u064f \u0645\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06da \u0633\u064f\u0628\u06e1\u062d\u064e\u0670\u0646\u064e\u0647\u064f\u06e5\u06d6 \u0647\u064f\u0648\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u0648\u064e\u0670\u062d\u0650\u062f\u064f \u0671\u0644\u06e1\u0642\u064e\u0647\u0651\u064e\u0627\u0631\u064f",translation:"Sekiranya Allah hendak mengambil anak, tentu Dia akan memilih apa yang Dia kehendaki dari apa yang telah diciptakan-Nya. Mahasuci Dia. Dialah Yang Maha Esa, Mahaperkasa"},{id:5,text:"\u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650\u06d6 \u064a\u064f\u0643\u064e\u0648\u0651\u0650\u0631\u064f \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u0648\u064e\u064a\u064f\u0643\u064e\u0648\u0651\u0650\u0631\u064f \u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u0650\u06d6 \u0648\u064e\u0633\u064e\u062e\u0651\u064e\u0631\u064e \u0671\u0644\u0634\u0651\u064e\u0645\u06e1\u0633\u064e \u0648\u064e\u0671\u0644\u06e1\u0642\u064e\u0645\u064e\u0631\u064e\u06d6 \u0643\u064f\u0644\u0651\u065e \u064a\u064e\u062c\u06e1\u0631\u0650\u064a \u0644\u0650\u0623\u064e\u062c\u064e\u0644\u0656 \u0645\u0651\u064f\u0633\u064e\u0645\u0651\u064b\u0649\u06d7 \u0623\u064e\u0644\u064e\u0627 \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0671\u0644\u06e1\u063a\u064e\u0641\u0651\u064e\u0640\u0670\u0631\u064f",translation:"Dia menciptakan langit dan bumi dengan (tujuan) yang benar; Dia memasukkan malam atas siang dan memasukkan siang atas malam dan menundukkan matahari dan bulan, masing-masing berjalan menurut waktu yang ditentukan. Ingatlah! Dialah Yang Mahamulia, Maha Pengampun"},{id:6,text:"\u062e\u064e\u0644\u064e\u0642\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0646\u0651\u064e\u0641\u06e1\u0633\u0656 \u0648\u064e\u0670\u062d\u0650\u062f\u064e\u0629\u0656 \u062b\u064f\u0645\u0651\u064e \u062c\u064e\u0639\u064e\u0644\u064e \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0632\u064e\u0648\u06e1\u062c\u064e\u0647\u064e\u0627 \u0648\u064e\u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0639\u064e\u0670\u0645\u0650 \u062b\u064e\u0645\u064e\u0670\u0646\u0650\u064a\u064e\u0629\u064e \u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u0656\u06da \u064a\u064e\u062e\u06e1\u0644\u064f\u0642\u064f\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u0628\u064f\u0637\u064f\u0648\u0646\u0650 \u0623\u064f\u0645\u0651\u064e\u0647\u064e\u0670\u062a\u0650\u0643\u064f\u0645\u06e1 \u062e\u064e\u0644\u06e1\u0642\u0657\u0627 \u0645\u0651\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u062e\u064e\u0644\u06e1\u0642\u0656 \u0641\u0650\u064a \u0638\u064f\u0644\u064f\u0645\u064e\u0670\u062a\u0656 \u062b\u064e\u0644\u064e\u0670\u062b\u0656\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u06e1 \u0644\u064e\u0647\u064f \u0671\u0644\u06e1\u0645\u064f\u0644\u06e1\u0643\u064f\u06d6 \u0644\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e\u06d6 \u0641\u064e\u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u062a\u064f\u0635\u06e1\u0631\u064e\u0641\u064f\u0648\u0646\u064e",translation:"Dia menciptakan kamu dari diri yang satu (Adam) kemudian darinya Dia jadikan pasangannya dan Dia menurunkan delapan pasang hewan ternak untukmu. Dia menjadikan kamu dalam perut ibumu kejadian demi kejadian dalam tiga kegelapan.757) Yang (berbuat) demikian itu adalah Allah, Tuhan kamu, Tuhan Yang memiliki kerajaan. Tidak ada tuhan selain Dia; maka mengapa kamu dapat dipalingkan"},{id:7,text:"\u0625\u0650\u0646 \u062a\u064e\u0643\u06e1\u0641\u064f\u0631\u064f\u0648\u0627\u0652 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0646\u0650\u064a\u0651\u064c \u0639\u064e\u0646\u0643\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0631\u06e1\u0636\u064e\u0649\u0670 \u0644\u0650\u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650 \u0671\u0644\u06e1\u0643\u064f\u0641\u06e1\u0631\u064e\u06d6 \u0648\u064e\u0625\u0650\u0646 \u062a\u064e\u0634\u06e1\u0643\u064f\u0631\u064f\u0648\u0627\u0652 \u064a\u064e\u0631\u06e1\u0636\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u06e1\u06d7 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0632\u0650\u0631\u064f \u0648\u064e\u0627\u0632\u0650\u0631\u064e\u0629\u065e \u0648\u0650\u0632\u06e1\u0631\u064e \u0623\u064f\u062e\u06e1\u0631\u064e\u0649\u0670\u06da \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645 \u0645\u0651\u064e\u0631\u06e1\u062c\u0650\u0639\u064f\u0643\u064f\u0645\u06e1 \u0641\u064e\u064a\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0643\u064f\u0645 \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0639\u064e\u0644\u0650\u064a\u0645\u064f\u06e2 \u0628\u0650\u0630\u064e\u0627\u062a\u0650 \u0671\u0644\u0635\u0651\u064f\u062f\u064f\u0648\u0631\u0650",translation:"Jika kamu kafir (ketahuilah) maka sesungguhnya Allah tidak memerlukanmu758) dan Dia tidak meridai kekafiran hamba-hamba-Nya. Jika kamu bersyukur, Dia meridai kesyukuranmu itu. Seseorang yang berdosa tidak memikul dosa orang lain.759) Kemudian kepada Tuhanmulah kembalimu lalu Dia beritakan kepadamu apa yang telah kamu kerjakan. Sungguh, Dia Maha Mengetahui apa yang tersimpan dalam dada(mu)"},{id:8,text:"\u06de\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0633\u0651\u064e \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064e \u0636\u064f\u0631\u0651\u065e \u062f\u064e\u0639\u064e\u0627 \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u06e5 \u0645\u064f\u0646\u0650\u064a\u0628\u064b\u0627 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0630\u064e\u0627 \u062e\u064e\u0648\u0651\u064e\u0644\u064e\u0647\u064f\u06e5 \u0646\u0650\u0639\u06e1\u0645\u064e\u0629\u0657 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f \u0646\u064e\u0633\u0650\u064a\u064e \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u064a\u064e\u062f\u06e1\u0639\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0646\u062f\u064e\u0627\u062f\u0657\u0627 \u0644\u0651\u0650\u064a\u064f\u0636\u0650\u0644\u0651\u064e \u0639\u064e\u0646 \u0633\u064e\u0628\u0650\u064a\u0644\u0650\u0647\u0650\u06e6\u06da \u0642\u064f\u0644\u06e1 \u062a\u064e\u0645\u064e\u062a\u0651\u064e\u0639\u06e1 \u0628\u0650\u0643\u064f\u0641\u06e1\u0631\u0650\u0643\u064e \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0645\u0650\u0646\u06e1 \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u0650 \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650",translation:"Dan apabila manusia ditimpa bencana, dia memohon (pertolongan) kepada Tuhannya dengan kembali (taat) kepada-Nya; tetapi apabila Dia memberikan nikmat kepadanya dia lupa (akan bencana) yang pernah dia berdoa kepada Allah sebelum itu, dan diadakannya sekutu-sekutu bagi Allah untuk menyesatkan (manusia) dari jalan-Nya. Katakanlah, \"Bersenang-senanglah kamu dengan kekafiranmu itu untuk sementara waktu. Sungguh, kamu termasuk penghuni neraka"},{id:9,text:"\u0623\u064e\u0645\u0651\u064e\u0646\u06e1 \u0647\u064f\u0648\u064e \u0642\u064e\u0670\u0646\u0650\u062a\u064c \u0621\u064e\u0627\u0646\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u0650 \u0633\u064e\u0627\u062c\u0650\u062f\u0657\u0627 \u0648\u064e\u0642\u064e\u0627\u0653\u0626\u0650\u0645\u0657\u0627 \u064a\u064e\u062d\u06e1\u0630\u064e\u0631\u064f \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u064e \u0648\u064e\u064a\u064e\u0631\u06e1\u062c\u064f\u0648\u0627\u0652 \u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u06e6\u06d7 \u0642\u064f\u0644\u06e1 \u0647\u064e\u0644\u06e1 \u064a\u064e\u0633\u06e1\u062a\u064e\u0648\u0650\u064a \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e\u06d7 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f \u0623\u064f\u0648\u0652\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0623\u064e\u0644\u06e1\u0628\u064e\u0670\u0628\u0650",translation:"(Apakah kamu orang musyrik yang lebih beruntung) ataukah orang yang beribadah pada waktu malam dengan sujud dan berdiri, karena takut kepada (azab) akhirat dan mengharapkan rahmat Tuhannya? Katakanlah, \"Apakah sama orang-orang yang mengetahui dengan orang-orang yang tidak mengetahui?\" Sebenarnya hanya orang yang berakal sehat yang dapat menerima pelajaran"},{id:10,text:"\u0642\u064f\u0644\u06e1 \u064a\u064e\u0670\u0639\u0650\u0628\u064e\u0627\u062f\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u06e1\u06da \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0647\u064e\u0670\u0630\u0650\u0647\u0650 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u062d\u064e\u0633\u064e\u0646\u064e\u0629\u065e\u06d7 \u0648\u064e\u0623\u064e\u0631\u06e1\u0636\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0670\u0633\u0650\u0639\u064e\u0629\u064c\u06d7 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064f\u0648\u064e\u0641\u0651\u064e\u0649 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0628\u0650\u0631\u064f\u0648\u0646\u064e \u0623\u064e\u062c\u06e1\u0631\u064e\u0647\u064f\u0645 \u0628\u0650\u063a\u064e\u064a\u06e1\u0631\u0650 \u062d\u0650\u0633\u064e\u0627\u0628\u0656",translation:"Katakanlah (Muhammad), \"Wahai hamba-hamba-Ku yang beriman! Bertakwalah kepada Tuhanmu.\" Bagi orang-orang yang berbuat baik di dunia ini akan memperoleh kebaikan. Dan bumi Allah itu luas. Hanya orang-orang yang bersabarlah yang disempurnakan pahalanya tanpa batas"},{id:11,text:"\u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064f\u0645\u0650\u0631\u06e1\u062a\u064f \u0623\u064e\u0646\u06e1 \u0623\u064e\u0639\u06e1\u0628\u064f\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064f\u062e\u06e1\u0644\u0650\u0635\u0657\u0627 \u0644\u0651\u064e\u0647\u064f \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u064e",translation:"Katakanlah, \"Sesungguhnya aku diperintahkan agar menyembah Allah dengan penuh ketaatan kepada-Nya dalam (menjalankan) agama"},{id:12,text:"\u0648\u064e\u0623\u064f\u0645\u0650\u0631\u06e1\u062a\u064f \u0644\u0650\u0623\u064e\u0646\u06e1 \u0623\u064e\u0643\u064f\u0648\u0646\u064e \u0623\u064e\u0648\u0651\u064e\u0644\u064e \u0671\u0644\u06e1\u0645\u064f\u0633\u06e1\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dan aku diperintahkan agar menjadi orang yang pertama-tama berserah diri"},{id:13,text:"\u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0625\u0650\u0646\u06e1 \u0639\u064e\u0635\u064e\u064a\u06e1\u062a\u064f \u0631\u064e\u0628\u0651\u0650\u064a \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u064a\u064e\u0648\u06e1\u0645\u064d \u0639\u064e\u0638\u0650\u064a\u0645\u0656",translation:"Katakanlah, \"Sesungguhnya aku takut akan azab pada hari yang besar jika aku durhaka kepada Tuhanku"},{id:14,text:"\u0642\u064f\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0623\u064e\u0639\u06e1\u0628\u064f\u062f\u064f \u0645\u064f\u062e\u06e1\u0644\u0650\u0635\u0657\u0627 \u0644\u0651\u064e\u0647\u064f\u06e5 \u062f\u0650\u064a\u0646\u0650\u064a",translation:"Katakanlah, \"Hanya Allah yang aku sembah dengan penuh ketaatan kepada-Nya dalam (menjalankan) agamaku"},{id:15,text:"\u0641\u064e\u0671\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u0634\u0650\u0626\u06e1\u062a\u064f\u0645 \u0645\u0651\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u06e6\u06d7 \u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u062e\u064e\u0670\u0633\u0650\u0631\u0650\u064a\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062e\u064e\u0633\u0650\u0631\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0647\u06e1\u0644\u0650\u064a\u0647\u0650\u0645\u06e1 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650\u06d7 \u0623\u064e\u0644\u064e\u0627 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u062e\u064f\u0633\u06e1\u0631\u064e\u0627\u0646\u064f \u0671\u0644\u06e1\u0645\u064f\u0628\u0650\u064a\u0646\u064f",translation:"Maka sembahlah selain Dia sesukamu! (wahai orang-orang musyrik).760) Katakanlah, \"Sesungguhnya orang-orang yang rugi ialah orang-orang yang merugikan diri mereka sendiri dan keluarganya pada hari Kiamat.\" Ingatlah! Yang demikian itu adalah kerugian yang nyata"},{id:16,text:"\u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0641\u064e\u0648\u06e1\u0642\u0650\u0647\u0650\u0645\u06e1 \u0638\u064f\u0644\u064e\u0644\u065e \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0648\u064e\u0645\u0650\u0646 \u062a\u064e\u062d\u06e1\u062a\u0650\u0647\u0650\u0645\u06e1 \u0638\u064f\u0644\u064e\u0644\u065e\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064f\u062e\u064e\u0648\u0651\u0650\u0641\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0647\u0650\u06e6 \u0639\u0650\u0628\u064e\u0627\u062f\u064e\u0647\u064f\u06e5\u06da \u064a\u064e\u0670\u0639\u0650\u0628\u064e\u0627\u062f\u0650 \u0641\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u0650",translation:"Di atas mereka ada lapisan-lapisan dari api dan di bawahnya juga ada lapisan-lapisan yang disediakan bagi mereka. Demikianlah Allah mengancam hamba-hamba-Nya (dengan azab itu). \"Wahai hamba-hamba-Ku, maka bertakwalah kepada-Ku"},{id:17,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u062c\u06e1\u062a\u064e\u0646\u064e\u0628\u064f\u0648\u0627\u0652 \u0671\u0644\u0637\u0651\u064e\u0640\u0670\u063a\u064f\u0648\u062a\u064e \u0623\u064e\u0646 \u064a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0647\u064e\u0627 \u0648\u064e\u0623\u064e\u0646\u064e\u0627\u0628\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0628\u064f\u0634\u06e1\u0631\u064e\u0649\u0670\u06da \u0641\u064e\u0628\u064e\u0634\u0651\u0650\u0631\u06e1 \u0639\u0650\u0628\u064e\u0627\u062f\u0650",translation:"Dan orang-orang yang menjauhi Tagut (yaitu) tidak menyembahnya761) dan kembali kepada Allah, mereka pantas mendapat berita gembira; sebab itu sampaikanlah kabar gembira itu kepada hamba-hamba-Ku"},{id:18,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0633\u06e1\u062a\u064e\u0645\u0650\u0639\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0644\u064e \u0641\u064e\u064a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0646\u064e \u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064e\u0647\u064f\u06e5\u0653\u06da \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064e\u062f\u064e\u0649\u0670\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06d6 \u0648\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u06e1 \u0623\u064f\u0648\u0652\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0623\u064e\u0644\u06e1\u0628\u064e\u0670\u0628\u0650",translation:"(yaitu) mereka yang mendengarkan perkataan lalu mengikuti apa yang paling baik di antaranya.762) Mereka itulah orang-orang yang telah diberi petunjuk oleh Allah dan mereka itulah orang-orang yang mempunyai akal sehat"},{id:19,text:"\u0623\u064e\u0641\u064e\u0645\u064e\u0646\u06e1 \u062d\u064e\u0642\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0643\u064e\u0644\u0650\u0645\u064e\u0629\u064f \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0623\u064e\u0641\u064e\u0623\u064e\u0646\u062a\u064e \u062a\u064f\u0646\u0642\u0650\u0630\u064f \u0645\u064e\u0646 \u0641\u0650\u064a \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650",translation:"Maka apakah (engkau hendak mengubah nasib) orang-orang yang telah dipastikan mendapat azab? Apakah engkau (Muhammad) akan menyelamatkan orang yang berada dalam api neraka"},{id:20,text:"\u0644\u064e\u0670\u0643\u0650\u0646\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u062a\u0651\u064e\u0642\u064e\u0648\u06e1\u0627\u0652 \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0647\u064f\u0645\u06e1 \u063a\u064f\u0631\u064e\u0641\u065e \u0645\u0651\u0650\u0646 \u0641\u064e\u0648\u06e1\u0642\u0650\u0647\u064e\u0627 \u063a\u064f\u0631\u064e\u0641\u065e \u0645\u0651\u064e\u0628\u06e1\u0646\u0650\u064a\u0651\u064e\u0629\u065e \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0645\u0650\u0646 \u062a\u064e\u062d\u06e1\u062a\u0650\u0647\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u064f\u06d6 \u0648\u064e\u0639\u06e1\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0627 \u064a\u064f\u062e\u06e1\u0644\u0650\u0641\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u0645\u0650\u064a\u0639\u064e\u0627\u062f\u064e",translation:"Tetapi orang-orang yang bertakwa kepada Tuhannya, mereka mendapat kamar-kamar (di surga), di atasnya terdapat pula kamar-kamar yang dibangun (bertingkat-tingkat), yang mengalir di bawahnya sungai-sungai. (Itulah) janji Allah. Allah tidak akan memungkiri janji(-Nya)"},{id:21,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0631\u064e \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0645\u064e\u0627\u0653\u0621\u0657 \u0641\u064e\u0633\u064e\u0644\u064e\u0643\u064e\u0647\u064f\u06e5 \u064a\u064e\u0646\u064e\u0670\u0628\u0650\u064a\u0639\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u062e\u06e1\u0631\u0650\u062c\u064f \u0628\u0650\u0647\u0650\u06e6 \u0632\u064e\u0631\u06e1\u0639\u0657\u0627 \u0645\u0651\u064f\u062e\u06e1\u062a\u064e\u0644\u0650\u0641\u064b\u0627 \u0623\u064e\u0644\u06e1\u0648\u064e\u0670\u0646\u064f\u0647\u064f\u06e5 \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u0647\u0650\u064a\u062c\u064f \u0641\u064e\u062a\u064e\u0631\u064e\u0649\u0670\u0647\u064f \u0645\u064f\u0635\u06e1\u0641\u064e\u0631\u0651\u0657\u0627 \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u062c\u06e1\u0639\u064e\u0644\u064f\u0647\u064f\u06e5 \u062d\u064f\u0637\u064e\u0670\u0645\u064b\u0627\u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0630\u0650\u0643\u06e1\u0631\u064e\u0649\u0670 \u0644\u0650\u0623\u064f\u0648\u0652\u0644\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0644\u06e1\u0628\u064e\u0670\u0628\u0650",translation:"Apakah engkau tidak memperhatikan, bahwa Allah menurunkan air dari langit, lalu diaturnya menjadi sumber-sumber air di bumi, kemudian dengan air itu ditumbuhkan-Nya tanam-tanaman yang bermacam-macam warnanya, kemudian menjadi kering, lalu engkau melihatnya kekuning-kuningan, kemudian dijadikan-Nya hancur berkeping-keping. Sungguh, pada yang demikian itu terdapat pelajaran bagi orang-orang yang mempunyai akal sehat"},{id:22,text:"\u0623\u064e\u0641\u064e\u0645\u064e\u0646 \u0634\u064e\u0631\u064e\u062d\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0635\u064e\u062f\u06e1\u0631\u064e\u0647\u064f\u06e5 \u0644\u0650\u0644\u06e1\u0625\u0650\u0633\u06e1\u0644\u064e\u0670\u0645\u0650 \u0641\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0646\u064f\u0648\u0631\u0656 \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0647\u0650\u06e6\u06da \u0641\u064e\u0648\u064e\u064a\u06e1\u0644\u065e \u0644\u0651\u0650\u0644\u06e1\u0642\u064e\u0670\u0633\u0650\u064a\u064e\u0629\u0650 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0630\u0650\u0643\u06e1\u0631\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0670\u0644\u0656 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u064d",translation:"Maka apakah orang-orang yang dibukakan hatinya oleh Allah untuk (menerima) agama Islam lalu dia mendapat cahaya dari Tuhannya (sama dengan orang yang hatinya membatu)? Maka celakalah mereka yang hatinya telah membatu untuk mengingat Allah. Mereka itu dalam kesesatan yang nyata"},{id:23,text:"\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0646\u064e\u0632\u0651\u064e\u0644\u064e \u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064e \u0671\u0644\u06e1\u062d\u064e\u062f\u0650\u064a\u062b\u0650 \u0643\u0650\u062a\u064e\u0670\u0628\u0657\u0627 \u0645\u0651\u064f\u062a\u064e\u0634\u064e\u0670\u0628\u0650\u0647\u0657\u0627 \u0645\u0651\u064e\u062b\u064e\u0627\u0646\u0650\u064a\u064e \u062a\u064e\u0642\u06e1\u0634\u064e\u0639\u0650\u0631\u0651\u064f \u0645\u0650\u0646\u06e1\u0647\u064f \u062c\u064f\u0644\u064f\u0648\u062f\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062e\u06e1\u0634\u064e\u0648\u06e1\u0646\u064e \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u0645\u06e1 \u062b\u064f\u0645\u0651\u064e \u062a\u064e\u0644\u0650\u064a\u0646\u064f \u062c\u064f\u0644\u064f\u0648\u062f\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649\u0670 \u0630\u0650\u0643\u06e1\u0631\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0647\u064f\u062f\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u0647\u06e1\u062f\u0650\u064a \u0628\u0650\u0647\u0650\u06e6 \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0636\u06e1\u0644\u0650\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646\u06e1 \u0647\u064e\u0627\u062f\u064d",translation:"Allah telah menurunkan perkataan yang paling baik (yaitu) Alquran yang serupa (ayat-ayatnya) lagi berulang-ulang,763) gemetar karenanya kulit orang-orang yang takut kepada Tuhannya, kemudian menjadi tenang kulit dan hati mereka ketika mengingat Allah. Itulah petunjuk Allah, dengan Kitab itu Dia memberi petunjuk kepada siapa yang Dia kehendaki. Dan barang siapa dibiarkan sesat oleh Allah, maka tidak seorang pun yang dapat memberi petunjuk"},{id:24,text:"\u0623\u064e\u0641\u064e\u0645\u064e\u0646 \u064a\u064e\u062a\u0651\u064e\u0642\u0650\u064a \u0628\u0650\u0648\u064e\u062c\u06e1\u0647\u0650\u0647\u0650\u06e6 \u0633\u064f\u0648\u0653\u0621\u064e \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650\u06da \u0648\u064e\u0642\u0650\u064a\u0644\u064e \u0644\u0650\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0630\u064f\u0648\u0642\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0643\u06e1\u0633\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Maka apakah orang-orang yang melindungi wajahnya menghindari azab yang buruk pada hari Kiamat (sama dengan orang mukmin yang tidak kena azab)? Dan dikatakan kepada orang-orang yang zalim, \"Rasakanlah olehmu balasan apa yang telah kamu kerjakan"},{id:25,text:"\u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u0645\u06e1 \u0641\u064e\u0623\u064e\u062a\u064e\u0649\u0670\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0645\u0650\u0646\u06e1 \u062d\u064e\u064a\u06e1\u062b\u064f \u0644\u064e\u0627 \u064a\u064e\u0634\u06e1\u0639\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Orang-orang yang sebelum mereka telah mendustakan (rasul-rasul), maka datanglah kepada mereka azab dari arah yang tidak mereka sangka"},{id:26,text:"\u0641\u064e\u0623\u064e\u0630\u064e\u0627\u0642\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u062e\u0650\u0632\u06e1\u064a\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u0650 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627\u06d6 \u0648\u064e\u0644\u064e\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0623\u064e\u0643\u06e1\u0628\u064e\u0631\u064f\u06da \u0644\u064e\u0648\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Maka Allah menimpakan kepada mereka kehinaan pada kehidupan dunia. Dan sungguh, azab akhirat lebih besar, kalau (saja) mereka mengetahui"},{id:27,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0636\u064e\u0631\u064e\u0628\u06e1\u0646\u064e\u0627 \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0641\u0650\u064a \u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u0650 \u0645\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u0645\u064e\u062b\u064e\u0644\u0656 \u0644\u0651\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan sungguh, telah Kami buatkan dalam Alquran ini segala macam perumpamaan bagi manusia agar mereka dapat pelajaran"},{id:28,text:"\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u064b\u0627 \u0639\u064e\u0631\u064e\u0628\u0650\u064a\u0651\u064b\u0627 \u063a\u064e\u064a\u06e1\u0631\u064e \u0630\u0650\u064a \u0639\u0650\u0648\u064e\u062c\u0656 \u0644\u0651\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",translation:"(Yaitu) Alquran dalam bahasa Arab, tidak ada kebengkokan (di dalamnya) agar mereka bertakwa"},{id:29,text:"\u0636\u064e\u0631\u064e\u0628\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u062b\u064e\u0644\u0657\u0627 \u0631\u0651\u064e\u062c\u064f\u0644\u0657\u0627 \u0641\u0650\u064a\u0647\u0650 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0653\u0621\u064f \u0645\u064f\u062a\u064e\u0634\u064e\u0670\u0643\u0650\u0633\u064f\u0648\u0646\u064e \u0648\u064e\u0631\u064e\u062c\u064f\u0644\u0657\u0627 \u0633\u064e\u0644\u064e\u0645\u0657\u0627 \u0644\u0651\u0650\u0631\u064e\u062c\u064f\u0644\u064d \u0647\u064e\u0644\u06e1 \u064a\u064e\u0633\u06e1\u062a\u064e\u0648\u0650\u064a\u064e\u0627\u0646\u0650 \u0645\u064e\u062b\u064e\u0644\u064b\u0627\u06da \u0671\u0644\u06e1\u062d\u064e\u0645\u06e1\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650\u06da \u0628\u064e\u0644\u06e1 \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064f\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Allah membuat perumpamaan (yaitu) seorang laki-laki (hamba sahaya) yang dimiliki oleh beberapa orang berserikat yang dalam perselisihan, dan seorang hamba sahaya yang menjadi milik penuh dari seorang (saja). Adakah kedua hamba sahaya itu sama keadaannya? Segala puji bagi Allah, tetapi kebanyakan mereka tidak mengetahui"},{id:30,text:"\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0645\u064e\u064a\u0651\u0650\u062a\u065e \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u064a\u0651\u0650\u062a\u064f\u0648\u0646\u064e",translation:"Sesungguhnya engkau (Muhammad) akan mati dan mereka akan mati (pula)"},{id:31,text:"\u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u0639\u0650\u0646\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1 \u062a\u064e\u062e\u06e1\u062a\u064e\u0635\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Kemudian sesungguhnya kamu pada hari Kiamat akan berbantah-bantahan di hadapan Tuhanmu"},{id:32,text:"\u06de\u0641\u064e\u0645\u064e\u0646\u06e1 \u0623\u064e\u0638\u06e1\u0644\u064e\u0645\u064f \u0645\u0650\u0645\u0651\u064e\u0646 \u0643\u064e\u0630\u064e\u0628\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0628\u0650\u0671\u0644\u0635\u0651\u0650\u062f\u06e1\u0642\u0650 \u0625\u0650\u0630\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u06e5\u0653\u06da \u0623\u064e\u0644\u064e\u064a\u06e1\u0633\u064e \u0641\u0650\u064a \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0645\u064e\u062b\u06e1\u0648\u0657\u0649 \u0644\u0651\u0650\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Maka siapakah yang lebih zalim daripada orang yang membuat-buat kebohongan terhadap Allah dan mendustakan kebenaran yang datang kepadanya? Bukankah di neraka Jahanam tempat tinggal bagi orang-orang kafir"},{id:33,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0627\u0653\u0621\u064e \u0628\u0650\u0671\u0644\u0635\u0651\u0650\u062f\u06e1\u0642\u0650 \u0648\u064e\u0635\u064e\u062f\u0651\u064e\u0642\u064e \u0628\u0650\u0647\u0650\u06e6\u0653 \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",translation:"Dan orang yang membawa kebenaran (Muhammad) dan orang yang membenarkannya, mereka itulah orang yang bertakwa"},{id:34,text:"\u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u0648\u0646\u064e \u0639\u0650\u0646\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062c\u064e\u0632\u064e\u0627\u0653\u0621\u064f \u0671\u0644\u06e1\u0645\u064f\u062d\u06e1\u0633\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Mereka memperoleh apa yang mereka kehendaki di sisi Tuhannya. Demikianlah balasan bagi orang-orang yang berbuat baik"},{id:35,text:"\u0644\u0650\u064a\u064f\u0643\u064e\u0641\u0651\u0650\u0631\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0623\u064e\u0633\u06e1\u0648\u064e\u0623\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0648\u064e\u064a\u064e\u062c\u06e1\u0632\u0650\u064a\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u062c\u06e1\u0631\u064e\u0647\u064f\u0645 \u0628\u0650\u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"agar Allah menghapus perbuatan mereka yang paling buruk yang pernah mereka lakukan dan memberi pahala kepada mereka dengan yang lebih baik daripada apa yang mereka kerjakan"},{id:36,text:"\u0623\u064e\u0644\u064e\u064a\u06e1\u0633\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0643\u064e\u0627\u0641\u064d \u0639\u064e\u0628\u06e1\u062f\u064e\u0647\u064f\u06e5\u06d6 \u0648\u064e\u064a\u064f\u062e\u064e\u0648\u0651\u0650\u0641\u064f\u0648\u0646\u064e\u0643\u064e \u0628\u0650\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u06e6\u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0636\u06e1\u0644\u0650\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646\u06e1 \u0647\u064e\u0627\u062f\u0656",translation:"Bukankah Allah yang mencukupi hamba-Nya? Mereka menakut-nakutimu dengan sesembahan yang selain Dia. Barangsiapa dibiarkan sesat oleh Allah maka tidak seorang pun yang dapat memberi petunjuk kepadanya"},{id:37,text:"\u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0647\u06e1\u062f\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646 \u0645\u0651\u064f\u0636\u0650\u0644\u0651\u064d\u06d7 \u0623\u064e\u0644\u064e\u064a\u06e1\u0633\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0639\u064e\u0632\u0650\u064a\u0632\u0656 \u0630\u0650\u064a \u0671\u0646\u062a\u0650\u0642\u064e\u0627\u0645\u0656",translation:"Dan barangsiapa diberi petunjuk oleh Allah, maka tidak seorang pun yang dapat menyesatkannya. Bukankah Allah Mahaperkasa dan mempunyai (kekuasaan untuk) menghukum"},{id:38,text:"\u0648\u064e\u0644\u064e\u0626\u0650\u0646 \u0633\u064e\u0623\u064e\u0644\u06e1\u062a\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u0646\u06e1 \u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0644\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06da \u0642\u064f\u0644\u06e1 \u0623\u064e\u0641\u064e\u0631\u064e\u0621\u064e\u064a\u06e1\u062a\u064f\u0645 \u0645\u0651\u064e\u0627 \u062a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0646\u06e1 \u0623\u064e\u0631\u064e\u0627\u062f\u064e\u0646\u0650\u064a\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0636\u064f\u0631\u0651\u064d \u0647\u064e\u0644\u06e1 \u0647\u064f\u0646\u0651\u064e \u0643\u064e\u0670\u0634\u0650\u0641\u064e\u0670\u062a\u064f \u0636\u064f\u0631\u0651\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0648\u06e1 \u0623\u064e\u0631\u064e\u0627\u062f\u064e\u0646\u0650\u064a \u0628\u0650\u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u064d \u0647\u064e\u0644\u06e1 \u0647\u064f\u0646\u0651\u064e \u0645\u064f\u0645\u06e1\u0633\u0650\u0643\u064e\u0670\u062a\u064f \u0631\u064e\u062d\u06e1\u0645\u064e\u062a\u0650\u0647\u0650\u06e6\u06da \u0642\u064f\u0644\u06e1 \u062d\u064e\u0633\u06e1\u0628\u0650\u064a\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06d6 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u064a\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u064f \u0671\u0644\u06e1\u0645\u064f\u062a\u064e\u0648\u064e\u0643\u0651\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Dan sungguh, jika engkau tanyakan kepada mereka, \"Siapakah yang menciptakan langit dan bumi?\" Niscaya mereka menjawab, \"Allah.\" Katakanlah, \"Kalau begitu tahukah kamu tentang apa yang kamu sembah selain Allah, jika Allah hendak mendatangkan bencana kepadaku, apakah mereka mampu menghilangkan bencana itu, atau jika Allah hendak memberi rahmat kepadaku, apakah mereka dapat mencegah rahmat-Nya?\" Katakanlah, \"Cukuplah Allah bagiku. Kepada-Nyalah orang-orang yang bertawakal berserah diri"},{id:39,text:"\u0642\u064f\u0644\u06e1 \u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0643\u064e\u0627\u0646\u064e\u062a\u0650\u0643\u064f\u0645\u06e1 \u0625\u0650\u0646\u0651\u0650\u064a \u0639\u064e\u0670\u0645\u0650\u0644\u065e\u06d6 \u0641\u064e\u0633\u064e\u0648\u06e1\u0641\u064e \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Katakanlah (Muhammad), \"Wahai kaumku! Berbuatlah menurut kedudukanmu, aku pun berbuat (demikian). Kelak kamu akan mengetahui"},{id:40,text:"\u0645\u064e\u0646 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u0647\u0650 \u0639\u064e\u0630\u064e\u0627\u0628\u065e \u064a\u064f\u062e\u06e1\u0632\u0650\u064a\u0647\u0650 \u0648\u064e\u064a\u064e\u062d\u0650\u0644\u0651\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0639\u064e\u0630\u064e\u0627\u0628\u065e \u0645\u0651\u064f\u0642\u0650\u064a\u0645\u064c",translation:"siapa yang mendapat siksa yang menghinakan dan kepadanya ditimpakan azab yang kekal"},{id:41,text:"\u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650\u06d6 \u0641\u064e\u0645\u064e\u0646\u0650 \u0671\u0647\u06e1\u062a\u064e\u062f\u064e\u0649\u0670 \u0641\u064e\u0644\u0650\u0646\u064e\u0641\u06e1\u0633\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u0645\u064e\u0646 \u0636\u064e\u0644\u0651\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0636\u0650\u0644\u0651\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627\u06d6 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0628\u0650\u0648\u064e\u0643\u0650\u064a\u0644\u064d",translation:"Sungguh, Kami menurunkan kepadamu Kitab (Alquran) dengan membawa kebenaran untuk manusia; barang siapa mendapat petunjuk maka (petunjuk itu) untuk dirinya sendiri, dan siapa sesat maka sesungguhnya kesesatan itu untuk dirinya sendiri, dan engkau bukanlah orang yang bertanggung jawab terhadap mereka"},{id:42,text:"\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u062a\u064e\u0648\u064e\u0641\u0651\u064e\u0649 \u0671\u0644\u06e1\u0623\u064e\u0646\u0641\u064f\u0633\u064e \u062d\u0650\u064a\u0646\u064e \u0645\u064e\u0648\u06e1\u062a\u0650\u0647\u064e\u0627 \u0648\u064e\u0671\u0644\u0651\u064e\u062a\u0650\u064a \u0644\u064e\u0645\u06e1 \u062a\u064e\u0645\u064f\u062a\u06e1 \u0641\u0650\u064a \u0645\u064e\u0646\u064e\u0627\u0645\u0650\u0647\u064e\u0627\u06d6 \u0641\u064e\u064a\u064f\u0645\u06e1\u0633\u0650\u0643\u064f \u0671\u0644\u0651\u064e\u062a\u0650\u064a \u0642\u064e\u0636\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627 \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u064e \u0648\u064e\u064a\u064f\u0631\u06e1\u0633\u0650\u0644\u064f \u0671\u0644\u06e1\u0623\u064f\u062e\u06e1\u0631\u064e\u0649\u0670\u0653 \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u062c\u064e\u0644\u0656 \u0645\u0651\u064f\u0633\u064e\u0645\u0651\u064b\u0649\u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0623\u0653\u064a\u064e\u0670\u062a\u0656 \u0644\u0651\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064e\u062a\u064e\u0641\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Allah memegang nyawa (seseorang) pada saat kematiannya dan nyawa (seseorang) yang belum mati ketika dia tidur; maka Dia tahan nyawa (orang) yang telah Dia tetapkan kematiannya dan Dia lepaskan nyawa yang lain sampai waktu yang ditentukan.764) Sungguh, pada yang demikian itu terdapat tanda-tanda (kebesaran) Allah bagi kaum yang berpikir"},{id:43,text:"\u0623\u064e\u0645\u0650 \u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0634\u064f\u0641\u064e\u0639\u064e\u0627\u0653\u0621\u064e\u06da \u0642\u064f\u0644\u06e1 \u0623\u064e\u0648\u064e\u0644\u064e\u0648\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u064a\u064e\u0645\u06e1\u0644\u0650\u0643\u064f\u0648\u0646\u064e \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Ataukah mereka mengambil penolong selain Allah. Katakanlah, \"Apakah (kamu mengambilnya juga) meskipun mereka tidak memiliki sesuatu apa pun dan tidak mengerti"},{id:44,text:"\u0642\u064f\u0644 \u0644\u0651\u0650\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u0634\u0651\u064e\u0641\u064e\u0670\u0639\u064e\u0629\u064f \u062c\u064e\u0645\u0650\u064a\u0639\u0657\u0627\u06d6 \u0644\u0651\u064e\u0647\u064f\u06e5 \u0645\u064f\u0644\u06e1\u0643\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d6 \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u062a\u064f\u0631\u06e1\u062c\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Katakanlah, \"Pertolongan itu hanya milik Allah semuanya. Dia memiliki kerajaan langit dan bumi. Kemudian kepada-Nya kamu dikembalikan"},{id:45,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0630\u064f\u0643\u0650\u0631\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u062d\u06e1\u062f\u064e\u0647\u064f \u0671\u0634\u06e1\u0645\u064e\u0623\u064e\u0632\u0651\u064e\u062a\u06e1 \u0642\u064f\u0644\u064f\u0648\u0628\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650\u06d6 \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0630\u064f\u0643\u0650\u0631\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0645\u06e1 \u064a\u064e\u0633\u06e1\u062a\u064e\u0628\u06e1\u0634\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Dan apabila yang disebut hanya nama Allah, kesal sekali hati orang-orang yang tidak beriman kepada akhirat. Namun apabila nama-nama sembahan selain Allah yang disebut, tiba-tiba mereka menjadi bergembira"},{id:46,text:"\u0642\u064f\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0641\u064e\u0627\u0637\u0650\u0631\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0639\u064e\u0670\u0644\u0650\u0645\u064e \u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u0628\u0650 \u0648\u064e\u0671\u0644\u0634\u0651\u064e\u0647\u064e\u0670\u062f\u064e\u0629\u0650 \u0623\u064e\u0646\u062a\u064e \u062a\u064e\u062d\u06e1\u0643\u064f\u0645\u064f \u0628\u064e\u064a\u06e1\u0646\u064e \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0643\u064e \u0641\u0650\u064a \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0647\u0650 \u064a\u064e\u062e\u06e1\u062a\u064e\u0644\u0650\u0641\u064f\u0648\u0646\u064e",translation:"Katakanlah, \"Ya Allah, Pencipta langit dan bumi, yang mengetahui segala yang gaib dan yang nyata, Engkaulah yang memutuskan di antara hamba-hamba-Mu tentang apa yang selalu mereka perselisihkan"},{id:47,text:"\u0648\u064e\u0644\u064e\u0648\u06e1 \u0623\u064e\u0646\u0651\u064e \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u062c\u064e\u0645\u0650\u064a\u0639\u0657\u0627 \u0648\u064e\u0645\u0650\u062b\u06e1\u0644\u064e\u0647\u064f\u06e5 \u0645\u064e\u0639\u064e\u0647\u064f\u06e5 \u0644\u064e\u0671\u0641\u06e1\u062a\u064e\u062f\u064e\u0648\u06e1\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6 \u0645\u0650\u0646 \u0633\u064f\u0648\u0653\u0621\u0650 \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650\u06da \u0648\u064e\u0628\u064e\u062f\u064e\u0627 \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0644\u064e\u0645\u06e1 \u064a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u062d\u06e1\u062a\u064e\u0633\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Dan sekiranya orang-orang yang zalim mempunyai segala apa yang ada di bumi dan ditambah lagi sebanyak itu, niscaya mereka akan menebus dirinya dengan itu dari azab yang buruk pada hari Kiamat. Dan jelaslah bagi mereka azab dari Allah yang dahulu tidak pernah mereka perkirakan"},{id:48,text:"\u0648\u064e\u0628\u064e\u062f\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0633\u064e\u064a\u0651\u0650\u0640\u0654\u064e\u0627\u062a\u064f \u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064f\u0648\u0627\u0652 \u0648\u064e\u062d\u064e\u0627\u0642\u064e \u0628\u0650\u0647\u0650\u0645 \u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6 \u064a\u064e\u0633\u06e1\u062a\u064e\u0647\u06e1\u0632\u0650\u0621\u064f\u0648\u0646\u064e",translation:"Dan jelaslah bagi mereka kejahatan apa yang telah mereka kerjakan dan mereka diliputi oleh apa yang dahulu mereka selalu memperolok-olokkannya"},{id:49,text:"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0633\u0651\u064e \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064e \u0636\u064f\u0631\u0651\u065e \u062f\u064e\u0639\u064e\u0627\u0646\u064e\u0627 \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0630\u064e\u0627 \u062e\u064e\u0648\u0651\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f \u0646\u0650\u0639\u06e1\u0645\u064e\u0629\u0657 \u0645\u0651\u0650\u0646\u0651\u064e\u0627 \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0648\u062a\u0650\u064a\u062a\u064f\u0647\u064f\u06e5 \u0639\u064e\u0644\u064e\u0649\u0670 \u0639\u0650\u0644\u06e1\u0645\u0650\u06ed\u06da \u0628\u064e\u0644\u06e1 \u0647\u0650\u064a\u064e \u0641\u0650\u062a\u06e1\u0646\u064e\u0629\u065e \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Maka apabila manusia ditimpa bencana dia menyeru Kami, kemudian apabila Kami berikan nikmat Kami kepadanya dia berkata, \"Sesungguhnya aku diberi nikmat ini hanyalah karena kepintaranku.\" Sebenarnya, itu adalah ujian, tetapi kebanyakan mereka tidak mengetahui"},{id:50,text:"\u0642\u064e\u062f\u06e1 \u0642\u064e\u0627\u0644\u064e\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u0645\u06e1 \u0641\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u063a\u06e1\u0646\u064e\u0649\u0670 \u0639\u064e\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0643\u06e1\u0633\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Sungguh, orang-orang yang sebelum mereka pun telah mengatakan hal itu, maka tidak berguna lagi bagi mereka apa yang dahulu mereka kerjakan"},{id:51,text:"\u0641\u064e\u0623\u064e\u0635\u064e\u0627\u0628\u064e\u0647\u064f\u0645\u06e1 \u0633\u064e\u064a\u0651\u0650\u0640\u0654\u064e\u0627\u062a\u064f \u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064f\u0648\u0627\u0652\u06da \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1 \u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650 \u0633\u064e\u064a\u064f\u0635\u0650\u064a\u0628\u064f\u0647\u064f\u0645\u06e1 \u0633\u064e\u064a\u0651\u0650\u0640\u0654\u064e\u0627\u062a\u064f \u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064f\u0648\u0627\u0652 \u0648\u064e\u0645\u064e\u0627 \u0647\u064f\u0645 \u0628\u0650\u0645\u064f\u0639\u06e1\u062c\u0650\u0632\u0650\u064a\u0646\u064e",translation:"Lalu mereka ditimpa (bencana) dari akibat buruk apa yang mereka perbuat. Dan orang-orang yang zalim di antara mereka juga akan ditimpa (bencana) dari akibat buruk apa yang mereka kerjakan dan mereka tidak dapat melepaskan diri"},{id:52,text:"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0628\u06e1\u0633\u064f\u0637\u064f \u0671\u0644\u0631\u0651\u0650\u0632\u06e1\u0642\u064e \u0644\u0650\u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0648\u064e\u064a\u064e\u0642\u06e1\u062f\u0650\u0631\u064f\u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0623\u0653\u064a\u064e\u0670\u062a\u0656 \u0644\u0651\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Dan tidakkah mereka mengetahui bahwa Allah melapangkan rezeki bagi siapa yang Dia kehendaki dan membatasinya (bagi siapa yang Dia kehendaki)? Sesungguhnya pada yang demikian itu terdapat tanda-tanda (kekuasaan Allah) bagi kaum yang beriman"},{id:53,text:"\u06de\u0642\u064f\u0644\u06e1 \u064a\u064e\u0670\u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u0633\u06e1\u0631\u064e\u0641\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u06e1 \u0644\u064e\u0627 \u062a\u064e\u0642\u06e1\u0646\u064e\u0637\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0629\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u063a\u06e1\u0641\u0650\u0631\u064f \u0671\u0644\u0630\u0651\u064f\u0646\u064f\u0648\u0628\u064e \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u063a\u064e\u0641\u064f\u0648\u0631\u064f \u0671\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",translation:"(Katakanlah, \"Wahai hamba-hamba-Ku yang melampaui batas terhadap diri mereka sendiri! Janganlah kamu berputus asa dari rahmat Allah. Sesungguhnya Allah mengampuni dosa-dosa765) semuanya. Sungguh, Dialah Yang Maha Pengampun, Maha Penyayang"},{id:54,text:"\u0648\u064e\u0623\u064e\u0646\u0650\u064a\u0628\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0633\u06e1\u0644\u0650\u0645\u064f\u0648\u0627\u0652 \u0644\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650 \u0623\u064e\u0646 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0627 \u062a\u064f\u0646\u0635\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan kembalilah kamu kepada Tuhanmu, dan berserah dirilah kepada-Nya sebelum datang azab kepadamu, kemudian kamu tidak dapat ditolong"},{id:55,text:"\u0648\u064e\u0671\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064e \u0645\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650 \u0623\u064e\u0646 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0628\u064e\u063a\u06e1\u062a\u064e\u0629\u0657 \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0644\u064e\u0627 \u062a\u064e\u0634\u06e1\u0639\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Dan ikutilah sebaik-baik apa yang telah diturunkan kepadamu (Alquran) dari Tuhanmu sebelum datang azab kepadamu secara mendadak, sedang kamu tidak menyadarinya"},{id:56,text:"\u0623\u064e\u0646 \u062a\u064e\u0642\u064f\u0648\u0644\u064e \u0646\u064e\u0641\u06e1\u0633\u065e \u064a\u064e\u0670\u062d\u064e\u0633\u06e1\u0631\u064e\u062a\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0641\u064e\u0631\u0651\u064e\u0637\u062a\u064f \u0641\u0650\u064a \u062c\u064e\u0646\u06e2\u0628\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f \u0644\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0640\u0670\u062e\u0650\u0631\u0650\u064a\u0646\u064e",translation:"agar jangan ada orang yang mengatakan, \"Alangkah besar penyesalanku atas kelalaianku dalam (menunaikan kewajiban) terhadap Allah, dan sesungguhnya aku termasuk orang-orang yang memperolok-olokkan (agama Allah)"},{id:57,text:"\u0623\u064e\u0648\u06e1 \u062a\u064e\u0642\u064f\u0648\u0644\u064e \u0644\u064e\u0648\u06e1 \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0647\u064e\u062f\u064e\u0649\u0670\u0646\u0650\u064a \u0644\u064e\u0643\u064f\u0646\u062a\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",translation:"atau (agar jangan) ada yang berkata, \u2018Sekiranya Allah memberi petunjuk kepadaku tentulah aku termasuk orang-orang yang bertakwa"},{id:58,text:"\u0623\u064e\u0648\u06e1 \u062a\u064e\u0642\u064f\u0648\u0644\u064e \u062d\u0650\u064a\u0646\u064e \u062a\u064e\u0631\u064e\u0649 \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0644\u064e\u0648\u06e1 \u0623\u064e\u0646\u0651\u064e \u0644\u0650\u064a \u0643\u064e\u0631\u0651\u064e\u0629\u0657 \u0641\u064e\u0623\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u062d\u06e1\u0633\u0650\u0646\u0650\u064a\u0646\u064e",translation:"atau (agar jangan) ada yang berkata ketika melihat azab, \"Sekiranya aku dapat kembali (ke dunia), tentu aku termasuk orang-orang yang berbuat baik"},{id:59,text:"\u0628\u064e\u0644\u064e\u0649\u0670 \u0642\u064e\u062f\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u062a\u06e1\u0643\u064e \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u064a \u0641\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u06e1\u062a\u064e \u0628\u0650\u0647\u064e\u0627 \u0648\u064e\u0671\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u064e\u0631\u06e1\u062a\u064e \u0648\u064e\u0643\u064f\u0646\u062a\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Sungguh, \"sebenarnya keterangan-keterangan-Ku telah datang kepadamu, tetapi kamu mendustakannya, malah kamu menyombongkan diri dan termasuk orang kafir"},{id:60,text:"\u0648\u064e\u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u062a\u064e\u0631\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u064e\u0628\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064f\u062c\u064f\u0648\u0647\u064f\u0647\u064f\u0645 \u0645\u0651\u064f\u0633\u06e1\u0648\u064e\u062f\u0651\u064e\u0629\u064c\u06da \u0623\u064e\u0644\u064e\u064a\u06e1\u0633\u064e \u0641\u0650\u064a \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0645\u064e\u062b\u06e1\u0648\u0657\u0649 \u0644\u0651\u0650\u0644\u06e1\u0645\u064f\u062a\u064e\u0643\u064e\u0628\u0651\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan pada hari Kiamat engkau akan melihat orang-orang yang berbuat dusta terhadap Allah, wajahnya menghitam. Bukankah neraka Jahanam itu tempat tinggal bagi orang yang menyombongkan diri"},{id:61,text:"\u0648\u064e\u064a\u064f\u0646\u064e\u062c\u0651\u0650\u064a \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u062a\u0651\u064e\u0642\u064e\u0648\u06e1\u0627\u0652 \u0628\u0650\u0645\u064e\u0641\u064e\u0627\u0632\u064e\u062a\u0650\u0647\u0650\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0645\u064e\u0633\u0651\u064f\u0647\u064f\u0645\u064f \u0671\u0644\u0633\u0651\u064f\u0648\u0653\u0621\u064f \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u06e1 \u064a\u064e\u062d\u06e1\u0632\u064e\u0646\u064f\u0648\u0646\u064e",translation:"Dan Allah menyelamatkan orang-orang yang bertakwa karena kemenangan mereka. Mereka tidak disentuh oleh azab dan tidak bersedih hati"},{id:62,text:"\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u062e\u064e\u0670\u0644\u0650\u0642\u064f \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656\u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0648\u064e\u0643\u0650\u064a\u0644\u065e",translation:"Allah pencipta segala sesuatu dan Dia Maha Pemelihara atas segala sesuatu"},{id:63,text:"\u0644\u0651\u064e\u0647\u064f\u06e5 \u0645\u064e\u0642\u064e\u0627\u0644\u0650\u064a\u062f\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d7 \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u062e\u064e\u0670\u0633\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Milik-Nyalah kunci-kunci (perbendaharaan) langit dan bumi. Dan orang-orang yang kafir terhadap ayat-ayat Allah, mereka itulah orang yang rugi"},{id:64,text:"\u0642\u064f\u0644\u06e1 \u0623\u064e\u0641\u064e\u063a\u064e\u064a\u06e1\u0631\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064e\u0623\u06e1\u0645\u064f\u0631\u064f\u0648\u0653\u0646\u0651\u0650\u064a\u0653 \u0623\u064e\u0639\u06e1\u0628\u064f\u062f\u064f \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u06e1\u062c\u064e\u0670\u0647\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Katakanlah (Muhammad), \"Apakah kamu menyuruh aku menyembah selain Allah, wahai orang-orang yang bodoh"},{id:65,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0623\u064f\u0648\u062d\u0650\u064a\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0648\u064e\u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064e \u0644\u064e\u0626\u0650\u0646\u06e1 \u0623\u064e\u0634\u06e1\u0631\u064e\u0643\u06e1\u062a\u064e \u0644\u064e\u064a\u064e\u062d\u06e1\u0628\u064e\u0637\u064e\u0646\u0651\u064e \u0639\u064e\u0645\u064e\u0644\u064f\u0643\u064e \u0648\u064e\u0644\u064e\u062a\u064e\u0643\u064f\u0648\u0646\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u062e\u064e\u0670\u0633\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan sungguh, telah diwahyukan kepadamu dan kepada (nabi-nabi) yang sebelummu, \"Sungguh, jika engkau mempersekutukan (Allah), niscaya akan terhapuslah amalmu dan tentulah engkau termasuk orang yang rugi"},{id:66,text:"\u0628\u064e\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0641\u064e\u0671\u0639\u06e1\u0628\u064f\u062f\u06e1 \u0648\u064e\u0643\u064f\u0646 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0634\u0651\u064e\u0640\u0670\u0643\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Karena itu, hendaklah Allah saja yang engkau sembah dan hendaklah engkau termasuk orang yang bersyukur"},{id:67,text:"\u0648\u064e\u0645\u064e\u0627 \u0642\u064e\u062f\u064e\u0631\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u062d\u064e\u0642\u0651\u064e \u0642\u064e\u062f\u06e1\u0631\u0650\u0647\u0650\u06e6 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064f \u062c\u064e\u0645\u0650\u064a\u0639\u0657\u0627 \u0642\u064e\u0628\u06e1\u0636\u064e\u062a\u064f\u0647\u064f\u06e5 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u0648\u064e\u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u064f \u0645\u064e\u0637\u06e1\u0648\u0650\u064a\u0651\u064e\u0640\u0670\u062a\u064f\u06e2 \u0628\u0650\u064a\u064e\u0645\u0650\u064a\u0646\u0650\u0647\u0650\u06e6\u06da \u0633\u064f\u0628\u06e1\u062d\u064e\u0670\u0646\u064e\u0647\u064f\u06e5 \u0648\u064e\u062a\u064e\u0639\u064e\u0670\u0644\u064e\u0649\u0670 \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064f\u0634\u06e1\u0631\u0650\u0643\u064f\u0648\u0646\u064e",translation:"(Dan mereka tidak mengagungkan Allah sebagaimana mestinya padahal bumi seluruhnya dalam genggaman-Nya pada hari Kiamat dan langit digulung dengan tangan kanan-Nya.766) Mahasuci Dia dan Mahatinggi Dia dari apa yang mereka persekutukan"},{id:68,text:"\u0648\u064e\u0646\u064f\u0641\u0650\u062e\u064e \u0641\u0650\u064a \u0671\u0644\u0635\u0651\u064f\u0648\u0631\u0650 \u0641\u064e\u0635\u064e\u0639\u0650\u0642\u064e \u0645\u064e\u0646 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0645\u064e\u0646 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646 \u0634\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06d6 \u062b\u064f\u0645\u0651\u064e \u0646\u064f\u0641\u0650\u062e\u064e \u0641\u0650\u064a\u0647\u0650 \u0623\u064f\u062e\u06e1\u0631\u064e\u0649\u0670 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0645\u06e1 \u0642\u0650\u064a\u064e\u0627\u0645\u065e \u064a\u064e\u0646\u0638\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Dan sangkakala pun ditiup, maka matilah semua (makhluk) yang di langit dan di bumi kecuali mereka yang dikehendaki Allah. Kemudian ditiup sekali lagi (sangkakala itu) maka seketika itu mereka bangun (dari kuburnya) menunggu (keputusan Allah)"},{id:69,text:"\u0648\u064e\u0623\u064e\u0634\u06e1\u0631\u064e\u0642\u064e\u062a\u0650 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064f \u0628\u0650\u0646\u064f\u0648\u0631\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u064e\u0627 \u0648\u064e\u0648\u064f\u0636\u0650\u0639\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064f \u0648\u064e\u062c\u0650\u0627\u0652\u064a\u0653\u0621\u064e \u0628\u0650\u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650\u0640\u06e7\u0646\u064e \u0648\u064e\u0671\u0644\u0634\u0651\u064f\u0647\u064e\u062f\u064e\u0627\u0653\u0621\u0650 \u0648\u064e\u0642\u064f\u0636\u0650\u064a\u064e \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064f\u0638\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan bumi (padang Mahsyar) menjadi terang benderang dengan cahaya (keadilan) Tuhannya; dan buku-buku (perhitungan perbuatan mereka) diberikan (kepada masing-masing), nabi-nabi dan saksi-saksi pun dihadirkan, lalu diberikan keputusan di antara mereka secara adil, sedang mereka tidak dirugikan"},{id:70,text:"\u0648\u064e\u0648\u064f\u0641\u0651\u0650\u064a\u064e\u062a\u06e1 \u0643\u064f\u0644\u0651\u064f \u0646\u064e\u0641\u06e1\u0633\u0656 \u0645\u0651\u064e\u0627 \u0639\u064e\u0645\u0650\u0644\u064e\u062a\u06e1 \u0648\u064e\u0647\u064f\u0648\u064e \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u064a\u064e\u0641\u06e1\u0639\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan kepada setiap jiwa diberi balasan dengan sempurna sesuai dengan apa yang telah dikerjakannya dan Dia lebih mengetahui apa yang mereka kerjakan"},{id:71,text:"\u0648\u064e\u0633\u0650\u064a\u0642\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0632\u064f\u0645\u064e\u0631\u064b\u0627\u06d6 \u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064f\u0648\u0647\u064e\u0627 \u0641\u064f\u062a\u0650\u062d\u064e\u062a\u06e1 \u0623\u064e\u0628\u06e1\u0648\u064e\u0670\u0628\u064f\u0647\u064e\u0627 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u062e\u064e\u0632\u064e\u0646\u064e\u062a\u064f\u0647\u064e\u0627\u0653 \u0623\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0623\u06e1\u062a\u0650\u0643\u064f\u0645\u06e1 \u0631\u064f\u0633\u064f\u0644\u065e \u0645\u0651\u0650\u0646\u0643\u064f\u0645\u06e1 \u064a\u064e\u062a\u06e1\u0644\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u064a\u064f\u0646\u0630\u0650\u0631\u064f\u0648\u0646\u064e\u0643\u064f\u0645\u06e1 \u0644\u0650\u0642\u064e\u0627\u0653\u0621\u064e \u064a\u064e\u0648\u06e1\u0645\u0650\u0643\u064f\u0645\u06e1 \u0647\u064e\u0670\u0630\u064e\u0627\u06da \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0628\u064e\u0644\u064e\u0649\u0670 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u06e1 \u062d\u064e\u0642\u0651\u064e\u062a\u06e1 \u0643\u064e\u0644\u0650\u0645\u064e\u0629\u064f \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Orang-orang yang kafir digiring ke neraka Jahanam secara berombongan. Sehingga apabila mereka sampai kepadanya (neraka) pintu-pintunya dibukakan dan penjaga-penjaga berkata kepada mereka, \"Apakah belum pernah datang kepadamu rasul-rasul dari kalangan kamu yang membacakan ayat-ayat Tuhanmu dan memperingatkan kepadamu akan pertemuan (dengan) harimu ini?\" Mereka menjawab, \"Benar, ada,\" tetapi ketetapan azab pasti berlaku terhadap orang-orang kafir"},{id:72,text:"\u0642\u0650\u064a\u0644\u064e \u0671\u062f\u06e1\u062e\u064f\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0628\u06e1\u0648\u064e\u0670\u0628\u064e \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u062e\u064e\u0670\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627\u06d6 \u0641\u064e\u0628\u0650\u0626\u06e1\u0633\u064e \u0645\u064e\u062b\u06e1\u0648\u064e\u0649 \u0671\u0644\u06e1\u0645\u064f\u062a\u064e\u0643\u064e\u0628\u0651\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dikatakan (kepada mereka), \"Masukilah pintu-pintu neraka Jahanam itu, (kamu) kekal di dalamnya.\" Maka (neraka Jahanam) itulah seburuk-buruk tempat tinggal bagi orang-orang yang menyombongkan diri"},{id:73,text:"\u0648\u064e\u0633\u0650\u064a\u0642\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u062a\u0651\u064e\u0642\u064e\u0648\u06e1\u0627\u0652 \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u0632\u064f\u0645\u064e\u0631\u064b\u0627\u06d6 \u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064f\u0648\u0647\u064e\u0627 \u0648\u064e\u0641\u064f\u062a\u0650\u062d\u064e\u062a\u06e1 \u0623\u064e\u0628\u06e1\u0648\u064e\u0670\u0628\u064f\u0647\u064e\u0627 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u062e\u064e\u0632\u064e\u0646\u064e\u062a\u064f\u0647\u064e\u0627 \u0633\u064e\u0644\u064e\u0670\u0645\u064c \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0637\u0650\u0628\u06e1\u062a\u064f\u0645\u06e1 \u0641\u064e\u0671\u062f\u06e1\u062e\u064f\u0644\u064f\u0648\u0647\u064e\u0627 \u062e\u064e\u0670\u0644\u0650\u062f\u0650\u064a\u0646\u064e",translation:"Dan orang-orang yang bertakwa kepada Tuhannya diantar ke dalam surga secara berombongan. Sehingga apabila mereka sampai kepadanya (surga) dan pintu-pintunya telah dibukakan, penjaga-penjaganya berkata kepada mereka, \"Kesejahteraan (dilimpahkan) atasmu, berbahagialah kamu! Maka masuklah, kamu kekal di dalamnya"},{id:74,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u062d\u064e\u0645\u06e1\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0635\u064e\u062f\u064e\u0642\u064e\u0646\u064e\u0627 \u0648\u064e\u0639\u06e1\u062f\u064e\u0647\u064f\u06e5 \u0648\u064e\u0623\u064e\u0648\u06e1\u0631\u064e\u062b\u064e\u0646\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0646\u064e\u062a\u064e\u0628\u064e\u0648\u0651\u064e\u0623\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u062d\u064e\u064a\u06e1\u062b\u064f \u0646\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06d6 \u0641\u064e\u0646\u0650\u0639\u06e1\u0645\u064e \u0623\u064e\u062c\u06e1\u0631\u064f \u0671\u0644\u06e1\u0639\u064e\u0670\u0645\u0650\u0644\u0650\u064a\u0646\u064e",translation:"Dan mereka berkata, \"Segala puji bagi Allah yang telah memenuhi janji-Nya kepada kami dan telah memberikan tempat ini kepada kami sedang kami (diperkenankan) menempati surga di mana saja yang kami kehendaki.\" Maka (surga itulah) sebaik-baik balasan bagi orang-orang yang beramal"},{id:75,text:"\u0648\u064e\u062a\u064e\u0631\u064e\u0649 \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u064e \u062d\u064e\u0627\u0653\u0641\u0651\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u06e1 \u062d\u064e\u0648\u06e1\u0644\u0650 \u0671\u0644\u06e1\u0639\u064e\u0631\u06e1\u0634\u0650 \u064a\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u064f\u0648\u0646\u064e \u0628\u0650\u062d\u064e\u0645\u06e1\u062f\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1\u06da \u0648\u064e\u0642\u064f\u0636\u0650\u064a\u064e \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650\u06da \u0648\u064e\u0642\u0650\u064a\u0644\u064e \u0671\u0644\u06e1\u062d\u064e\u0645\u06e1\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0631\u064e\u0628\u0651\u0650 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Dan engkau (Muhammad) akan melihat malaikat-malaikat melingkar di sekeliling Arasy, bertasbih sambil memuji Tuhannya; lalu diberikan keputusan di antara mereka (hamba-hamba Allah) secara adil dan dikatakan, \"Segala puji bagi Allah, Tuhan seluruh alam"}]},{id:40,name:"\u063a\u0627\u0641\u0631",transliteration:"Ghafir",translation:"Sang Maha Pengampun",type:"meccan",total_verses:85,verses:[{id:1,text:"\u062d\u0645\u0653",translation:"\u1e24\u0101 M\u012bm"},{id:2,text:"\u062a\u064e\u0646\u0632\u0650\u064a\u0644\u064f \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0645\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u0650 \u0671\u0644\u06e1\u0639\u064e\u0644\u0650\u064a\u0645\u0650",translation:"Kitab ini (Alquran) di turunkan dari Allah Yang Mahaperkasa, Maha Mengetahui"},{id:3,text:"\u063a\u064e\u0627\u0641\u0650\u0631\u0650 \u0671\u0644\u0630\u0651\u064e\u0646\u06e2\u0628\u0650 \u0648\u064e\u0642\u064e\u0627\u0628\u0650\u0644\u0650 \u0671\u0644\u062a\u0651\u064e\u0648\u06e1\u0628\u0650 \u0634\u064e\u062f\u0650\u064a\u062f\u0650 \u0671\u0644\u06e1\u0639\u0650\u0642\u064e\u0627\u0628\u0650 \u0630\u0650\u064a \u0671\u0644\u0637\u0651\u064e\u0648\u06e1\u0644\u0650\u06d6 \u0644\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e\u06d6 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0671\u0644\u06e1\u0645\u064e\u0635\u0650\u064a\u0631\u064f",translation:"yang mengampuni dosa dan menerima tobat dan keras hukuman-Nya; yang memiliki karunia. Tidak ada tuhan selain Dia. Hanya kepada-Nyalah (semua makhluk) kembali"},{id:4,text:"\u0645\u064e\u0627 \u064a\u064f\u062c\u064e\u0670\u062f\u0650\u0644\u064f \u0641\u0650\u064a\u0653 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u063a\u06e1\u0631\u064f\u0631\u06e1\u0643\u064e \u062a\u064e\u0642\u064e\u0644\u0651\u064f\u0628\u064f\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0628\u0650\u0644\u064e\u0670\u062f\u0650",translation:"Tidak ada yang memperdebatkan tentang ayat-ayat Allah, kecuali orang-orang yang kafir. Karena itu janganlah engkau (Muhammad) tertipu oleh keberhasilan usaha mereka di seluruh negeri"},{id:5,text:"\u0643\u064e\u0630\u0651\u064e\u0628\u064e\u062a\u06e1 \u0642\u064e\u0628\u06e1\u0644\u064e\u0647\u064f\u0645\u06e1 \u0642\u064e\u0648\u06e1\u0645\u064f \u0646\u064f\u0648\u062d\u0656 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u062d\u06e1\u0632\u064e\u0627\u0628\u064f \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u0647\u0650\u0645\u06e1\u06d6 \u0648\u064e\u0647\u064e\u0645\u0651\u064e\u062a\u06e1 \u0643\u064f\u0644\u0651\u064f \u0623\u064f\u0645\u0651\u064e\u0629\u0650\u06ed \u0628\u0650\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650\u0645\u06e1 \u0644\u0650\u064a\u064e\u0623\u06e1\u062e\u064f\u0630\u064f\u0648\u0647\u064f\u06d6 \u0648\u064e\u062c\u064e\u0670\u062f\u064e\u0644\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u06e1\u0628\u064e\u0670\u0637\u0650\u0644\u0650 \u0644\u0650\u064a\u064f\u062f\u06e1\u062d\u0650\u0636\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650 \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064e \u0641\u064e\u0623\u064e\u062e\u064e\u0630\u06e1\u062a\u064f\u0647\u064f\u0645\u06e1\u06d6 \u0641\u064e\u0643\u064e\u064a\u06e1\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u0650\u0642\u064e\u0627\u0628\u0650",translation:"Sebelum mereka, kaum Nuh dan golongan-golongan yang bersekutu setelah mereka telah mendustakan (rasul) dan setiap umat telah merencanakan (tipu daya) terhadap rasul mereka untuk menawannya dan mereka membantah dengan (alasan) yang batil untuk melenyapkan kebenaran; karena itu Aku tawan mereka (dengan azab). Maka betapa (pedihnya) azab-Ku"},{id:6,text:"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062d\u064e\u0642\u0651\u064e\u062a\u06e1 \u0643\u064e\u0644\u0650\u0645\u064e\u062a\u064f \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650",translation:"Dan demikianlah telah pasti berlaku ketetapan Tuhanmu terhadap orang-orang kafir, (yaitu) sesungguhnya mereka adalah penghuni neraka"},{id:7,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062d\u06e1\u0645\u0650\u0644\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0639\u064e\u0631\u06e1\u0634\u064e \u0648\u064e\u0645\u064e\u0646\u06e1 \u062d\u064e\u0648\u06e1\u0644\u064e\u0647\u064f\u06e5 \u064a\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u064f\u0648\u0646\u064e \u0628\u0650\u062d\u064e\u0645\u06e1\u062f\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u0650\u06e6 \u0648\u064e\u064a\u064e\u0633\u06e1\u062a\u064e\u063a\u06e1\u0641\u0650\u0631\u064f\u0648\u0646\u064e \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652\u06d6 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0648\u064e\u0633\u0650\u0639\u06e1\u062a\u064e \u0643\u064f\u0644\u0651\u064e \u0634\u064e\u064a\u06e1\u0621\u0656 \u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0629\u0657 \u0648\u064e\u0639\u0650\u0644\u06e1\u0645\u0657\u0627 \u0641\u064e\u0671\u063a\u06e1\u0641\u0650\u0631\u06e1 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u0627\u0628\u064f\u0648\u0627\u0652 \u0648\u064e\u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0627\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u064e\u0643\u064e \u0648\u064e\u0642\u0650\u0647\u0650\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0671\u0644\u06e1\u062c\u064e\u062d\u0650\u064a\u0645\u0650",translation:"(Malaikat-malaikat) yang memikul Arasy dan (malaikat) yang berada di sekelilingnya bertasbih dengan memuji Tuhannya dan mereka beriman kepada-Nya serta memohonkan ampunan untuk orang-orang yang beriman (seraya berkata), \"Ya Tuhan kami, rahmat dan ilmu yang ada pada-Mu meliputi segala sesuatu, maka berilah ampunan kepada orang-orang yang bertobat dan mengikuti jalan (agama)-Mu dan peliharalah mereka dari azab neraka"},{id:8,text:"\u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0648\u064e\u0623\u064e\u062f\u06e1\u062e\u0650\u0644\u06e1\u0647\u064f\u0645\u06e1 \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0650 \u0639\u064e\u062f\u06e1\u0646\u064d \u0671\u0644\u0651\u064e\u062a\u0650\u064a \u0648\u064e\u0639\u064e\u062f\u062a\u0651\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0645\u064e\u0646 \u0635\u064e\u0644\u064e\u062d\u064e \u0645\u0650\u0646\u06e1 \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0626\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u0640\u0670\u062a\u0650\u0647\u0650\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0623\u064e\u0646\u062a\u064e \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0671\u0644\u06e1\u062d\u064e\u0643\u0650\u064a\u0645\u064f",translation:"Ya Tuhan kami, masukkanlah mereka ke dalam surga 'Adn yang telah Engkau janjikan kepada mereka, dan orang yang saleh di antara nenek moyang mereka, istri-istri, dan keturunan mereka. Sungguh, Engkaulah Yang Mahaperkasa, Mahabijaksana"},{id:9,text:"\u0648\u064e\u0642\u0650\u0647\u0650\u0645\u064f \u0671\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0640\u0654\u064e\u0627\u062a\u0650\u06da \u0648\u064e\u0645\u064e\u0646 \u062a\u064e\u0642\u0650 \u0671\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0640\u0654\u064e\u0627\u062a\u0650 \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u0641\u064e\u0642\u064e\u062f\u06e1 \u0631\u064e\u062d\u0650\u0645\u06e1\u062a\u064e\u0647\u064f\u06e5\u06da \u0648\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0641\u064e\u0648\u06e1\u0632\u064f \u0671\u0644\u06e1\u0639\u064e\u0638\u0650\u064a\u0645\u064f",translation:"dan peliharalah mereka dari (bencana) kejahatan. Dan orang-orang yang Engkau pelihara dari (bencana) kejahatan pada hari itu, maka sungguh, Engkau telah menganugerahkan rahmat kepadanya dan demikian itulah kemenangan yang agung"},{id:10,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u064a\u064f\u0646\u064e\u0627\u062f\u064e\u0648\u06e1\u0646\u064e \u0644\u064e\u0645\u064e\u0642\u06e1\u062a\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0643\u06e1\u0628\u064e\u0631\u064f \u0645\u0650\u0646 \u0645\u0651\u064e\u0642\u06e1\u062a\u0650\u0643\u064f\u0645\u06e1 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0630\u06e1 \u062a\u064f\u062f\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u0625\u0650\u064a\u0645\u064e\u0670\u0646\u0650 \u0641\u064e\u062a\u064e\u0643\u06e1\u0641\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Sesungguhnya orang-orang yang kafir, kepada mereka (pada hari Kiamat) diserukan, \"Sungguh, kebencian Allah (kepadamu) jauh lebih besar daripada kebencianmu kepada dirimu sendiri, ketika kamu diseru untuk beriman lalu kamu mengingkarinya"},{id:11,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627\u0653 \u0623\u064e\u0645\u064e\u062a\u0651\u064e\u0646\u064e\u0627 \u0671\u062b\u06e1\u0646\u064e\u062a\u064e\u064a\u06e1\u0646\u0650 \u0648\u064e\u0623\u064e\u062d\u06e1\u064a\u064e\u064a\u06e1\u062a\u064e\u0646\u064e\u0627 \u0671\u062b\u06e1\u0646\u064e\u062a\u064e\u064a\u06e1\u0646\u0650 \u0641\u064e\u0671\u0639\u06e1\u062a\u064e\u0631\u064e\u0641\u06e1\u0646\u064e\u0627 \u0628\u0650\u0630\u064f\u0646\u064f\u0648\u0628\u0650\u0646\u064e\u0627 \u0641\u064e\u0647\u064e\u0644\u06e1 \u0625\u0650\u0644\u064e\u0649\u0670 \u062e\u064f\u0631\u064f\u0648\u062c\u0656 \u0645\u0651\u0650\u0646 \u0633\u064e\u0628\u0650\u064a\u0644\u0656",translation:"Mereka menjawab, \"Ya Tuhan kami, Engkau telah mematikan kami dua kali dan telah menghidupkan kami dua kali (pula), lalu kami mengakui dosa-dosa kami. Maka adakah jalan (bagi kami) untuk keluar (dari neraka)"},{id:12,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645 \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u06e5\u0653 \u0625\u0650\u0630\u064e\u0627 \u062f\u064f\u0639\u0650\u064a\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u062d\u06e1\u062f\u064e\u0647\u064f\u06e5 \u0643\u064e\u0641\u064e\u0631\u06e1\u062a\u064f\u0645\u06e1 \u0648\u064e\u0625\u0650\u0646 \u064a\u064f\u0634\u06e1\u0631\u064e\u0643\u06e1 \u0628\u0650\u0647\u0650\u06e6 \u062a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0627\u0652\u06da \u0641\u064e\u0671\u0644\u06e1\u062d\u064f\u0643\u06e1\u0645\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u0639\u064e\u0644\u0650\u064a\u0651\u0650 \u0671\u0644\u06e1\u0643\u064e\u0628\u0650\u064a\u0631\u0650",translation:"Yang demikian itu karena sesungguhnya kamu mengingkari apabila diseru untuk menyembah Allah saja. Dan jika Allah dipersekutukan, kamu percaya. Maka keputusan (sekarang ini) adalah pada Allah Yang Mahatinggi, Mahabesar"},{id:13,text:"\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u0631\u0650\u064a\u0643\u064f\u0645\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0647\u0650\u06e6 \u0648\u064e\u064a\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u064f \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0631\u0650\u0632\u06e1\u0642\u0657\u0627\u06da \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646 \u064a\u064f\u0646\u0650\u064a\u0628\u064f",translation:"Dialah yang memperlihatkan tanda-tanda (kekuasaan)-Nya kepadamu dan menurunkan rezeki dari langit untukmu. Dan tidak lain yang mendapat pelajaran hanyalah orang-orang yang kembali (kepada Allah)"},{id:14,text:"\u0641\u064e\u0671\u062f\u06e1\u0639\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064f\u062e\u06e1\u0644\u0650\u0635\u0650\u064a\u0646\u064e \u0644\u064e\u0647\u064f \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u064e \u0648\u064e\u0644\u064e\u0648\u06e1 \u0643\u064e\u0631\u0650\u0647\u064e \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Maka sembahlah Allah dengan tulus ikhlas beragama kepada-Nya, meskipun orang-orang kafir tidak menyukai(nya)"},{id:15,text:"\u0631\u064e\u0641\u0650\u064a\u0639\u064f \u0671\u0644\u062f\u0651\u064e\u0631\u064e\u062c\u064e\u0670\u062a\u0650 \u0630\u064f\u0648 \u0671\u0644\u06e1\u0639\u064e\u0631\u06e1\u0634\u0650 \u064a\u064f\u0644\u06e1\u0642\u0650\u064a \u0671\u0644\u0631\u0651\u064f\u0648\u062d\u064e \u0645\u0650\u0646\u06e1 \u0623\u064e\u0645\u06e1\u0631\u0650\u0647\u0650\u06e6 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0645\u0650\u0646\u06e1 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650\u06e6 \u0644\u0650\u064a\u064f\u0646\u0630\u0650\u0631\u064e \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u062a\u0651\u064e\u0644\u064e\u0627\u0642\u0650",translation:"(Dialah) Yang Mahatinggi derajat-Nya, yang memiliki Arasy, yang menurunkan wahyu dengan perintah-Nya kepada siapa yang Dia kehendaki di antara hamba-hamba-Nya, agar memperingatkan (manusia) tentang hari pertemuan (hari Kiamat)"},{id:16,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u0647\u064f\u0645 \u0628\u064e\u0670\u0631\u0650\u0632\u064f\u0648\u0646\u064e\u06d6 \u0644\u064e\u0627 \u064a\u064e\u062e\u06e1\u0641\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0634\u064e\u064a\u06e1\u0621\u065e\u06da \u0644\u0651\u0650\u0645\u064e\u0646\u0650 \u0671\u0644\u06e1\u0645\u064f\u0644\u06e1\u0643\u064f \u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e\u06d6 \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u0648\u064e\u0670\u062d\u0650\u062f\u0650 \u0671\u0644\u06e1\u0642\u064e\u0647\u0651\u064e\u0627\u0631\u0650",translation:"(yaitu) pada hari (ketika) mereka keluar (dari kubur); tidak sesuatu pun keadaan mereka yang tersembunyi di sisi Allah. (Lalu Allah berfirman), \"Milik siapakah kerajaan pada hari ini?\" Milik Allah Yang Maha Esa, Maha Mengalahkan"},{id:17,text:"\u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e \u062a\u064f\u062c\u06e1\u0632\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u064f \u0646\u064e\u0641\u06e1\u0633\u0650\u06ed \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064e\u062a\u06e1\u06da \u0644\u064e\u0627 \u0638\u064f\u0644\u06e1\u0645\u064e \u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0633\u064e\u0631\u0650\u064a\u0639\u064f \u0671\u0644\u06e1\u062d\u0650\u0633\u064e\u0627\u0628\u0650",translation:"Pada hari ini setiap jiwa diberi balasan sesuai dengan apa yang telah dikerjakannya. Tidak ada yang dirugikan pada hari ini. Sungguh, Allah sangat cepat perhitungan-Nya"},{id:18,text:"\u0648\u064e\u0623\u064e\u0646\u0630\u0650\u0631\u06e1\u0647\u064f\u0645\u06e1 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0623\u0653\u0632\u0650\u0641\u064e\u0629\u0650 \u0625\u0650\u0630\u0650 \u0671\u0644\u06e1\u0642\u064f\u0644\u064f\u0648\u0628\u064f \u0644\u064e\u062f\u064e\u0649 \u0671\u0644\u06e1\u062d\u064e\u0646\u064e\u0627\u062c\u0650\u0631\u0650 \u0643\u064e\u0670\u0638\u0650\u0645\u0650\u064a\u0646\u064e\u06da \u0645\u064e\u0627 \u0644\u0650\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u06e1 \u062d\u064e\u0645\u0650\u064a\u0645\u0656 \u0648\u064e\u0644\u064e\u0627 \u0634\u064e\u0641\u0650\u064a\u0639\u0656 \u064a\u064f\u0637\u064e\u0627\u0639\u064f",translation:"Dan berilah mereka peringatan akan hari yang semakin dekat (hari Kiamat, yaitu) ketika hati (menyesak) sampai di kerongkongan karena menahan kesedihan. Tidak ada seorang pun teman setia bagi orang yang zalim dan tidak ada baginya seorang penolong yang diterima (pertolongannya)"},{id:19,text:"\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u062e\u064e\u0627\u0653\u0626\u0650\u0646\u064e\u0629\u064e \u0671\u0644\u06e1\u0623\u064e\u0639\u06e1\u064a\u064f\u0646\u0650 \u0648\u064e\u0645\u064e\u0627 \u062a\u064f\u062e\u06e1\u0641\u0650\u064a \u0671\u0644\u0635\u0651\u064f\u062f\u064f\u0648\u0631\u064f",translation:"Dia mengetahui (pandangan) mata yang khianat767) dan apa yang tersembunyi dalam dada"},{id:20,text:"\u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0642\u06e1\u0636\u0650\u064a \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650\u06d6 \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u06e6 \u0644\u064e\u0627 \u064a\u064e\u0642\u06e1\u0636\u064f\u0648\u0646\u064e \u0628\u0650\u0634\u064e\u064a\u06e1\u0621\u064d\u06d7 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0647\u064f\u0648\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u0650\u064a\u0639\u064f \u0671\u0644\u06e1\u0628\u064e\u0635\u0650\u064a\u0631\u064f",translation:"Dan Allah memutuskan dengan kebenaran. Sedang mereka yang disembah selain-Nya tidak mampu memutuskan dengan sesuatu apa pun. Sesungguhnya Allah, Dialah Yang Maha Mendengar, Maha Melihat"},{id:21,text:"\u06de\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0633\u0650\u064a\u0631\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0641\u064e\u064a\u064e\u0646\u0638\u064f\u0631\u064f\u0648\u0627\u0652 \u0643\u064e\u064a\u06e1\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0670\u0642\u0650\u0628\u064e\u0629\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u0645\u06e1\u06da \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0647\u064f\u0645\u06e1 \u0623\u064e\u0634\u064e\u062f\u0651\u064e \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0642\u064f\u0648\u0651\u064e\u0629\u0657 \u0648\u064e\u0621\u064e\u0627\u062b\u064e\u0627\u0631\u0657\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0641\u064e\u0623\u064e\u062e\u064e\u0630\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0630\u064f\u0646\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646 \u0648\u064e\u0627\u0642\u0656",translation:"Dan apakah mereka tidak mengadakan perjalanan di bumi, lalu memperhatikan bagaimana kesudahan orang-orang yang sebelum mereka? Orang-orang itu lebih hebat kekuatannya daripada mereka dan (lebih banyak) peninggalan-peninggalan (peradaban)nya di bumi, tetapi Allah mengazab mereka karena dosa-dosanya. Dan tidak akan ada sesuatu pun yang melindungi mereka dari (azab) Allah"},{id:22,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0627\u0646\u064e\u062a \u062a\u0651\u064e\u0623\u06e1\u062a\u0650\u064a\u0647\u0650\u0645\u06e1 \u0631\u064f\u0633\u064f\u0644\u064f\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0650 \u0641\u064e\u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0641\u064e\u0623\u064e\u062e\u064e\u0630\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0642\u064e\u0648\u0650\u064a\u0651\u065e \u0634\u064e\u062f\u0650\u064a\u062f\u064f \u0671\u0644\u06e1\u0639\u0650\u0642\u064e\u0627\u0628\u0650",translation:"(Yang demikian itu adalah karena sesungguhnya rasul-rasul telah datang kepada mereka dengan membawa bukti-bukti yang nyata768) lalu mereka ingkar; maka Allah mengazab mereka. Sungguh, Dia Mahakuat, Mahakeras hukuman-Nya"},{id:23,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0648\u064e\u0633\u064f\u0644\u06e1\u0637\u064e\u0670\u0646\u0656 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u064d",translation:"Dan sungguh, Kami telah mengutus Musa dengan membawa ayat-ayat Kami dan keterangan yang nyata"},{id:24,text:"\u0625\u0650\u0644\u064e\u0649\u0670 \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0648\u064e\u0647\u064e\u0670\u0645\u064e\u0670\u0646\u064e \u0648\u064e\u0642\u064e\u0670\u0631\u064f\u0648\u0646\u064e \u0641\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0633\u064e\u0670\u062d\u0650\u0631\u065e \u0643\u064e\u0630\u0651\u064e\u0627\u0628\u065e",translation:"kepada Fir'aun, Haman dan Karun; lalu mereka berkata, \"(Musa) itu seorang pesihir dan pendusta"},{id:25,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0645\u0650\u0646\u06e1 \u0639\u0650\u0646\u062f\u0650\u0646\u064e\u0627 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0671\u0642\u06e1\u062a\u064f\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0628\u06e1\u0646\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0645\u064e\u0639\u064e\u0647\u064f\u06e5 \u0648\u064e\u0671\u0633\u06e1\u062a\u064e\u062d\u06e1\u064a\u064f\u0648\u0627\u0652 \u0646\u0650\u0633\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u06e1\u06da \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u064a\u06e1\u062f\u064f \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0670\u0644\u0656",translation:"Maka ketika dia (Musa) datang kepada mereka membawa kebenaran dari Kami, mereka berkata, \"Bunuhlah anak-anak laki-laki dari orang-orang yang beriman bersama dia dan biarkan hidup perempuan-perempuan mereka.\" Namun tipu daya orang-orang kafir itu sia-sia belaka"},{id:26,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064f \u0630\u064e\u0631\u064f\u0648\u0646\u0650\u064a\u0653 \u0623\u064e\u0642\u06e1\u062a\u064f\u0644\u06e1 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u0644\u06e1\u064a\u064e\u062f\u06e1\u0639\u064f \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u06e5\u0653\u06d6 \u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0623\u064e\u0646 \u064a\u064f\u0628\u064e\u062f\u0651\u0650\u0644\u064e \u062f\u0650\u064a\u0646\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1 \u0623\u064e\u0646 \u064a\u064f\u0638\u06e1\u0647\u0650\u0631\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0671\u0644\u06e1\u0641\u064e\u0633\u064e\u0627\u062f\u064e",translation:"Dan Fir'aun berkata (kepada pembesar-pembesarnya), \"Biar aku yang membunuh Musa dan suruh dia memohon kepada Tuhannya. Sesungguhnya aku khawatir dia akan menukar agamamu atau menimbulkan kerusakan di bumi"},{id:27,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670\u0653 \u0625\u0650\u0646\u0651\u0650\u064a \u0639\u064f\u0630\u06e1\u062a\u064f \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u0645\u064f\u062a\u064e\u0643\u064e\u0628\u0651\u0650\u0631\u0656 \u0644\u0651\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f \u0628\u0650\u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u062d\u0650\u0633\u064e\u0627\u0628\u0650",translation:"Dan (Musa) berkata, \"Sesungguhnya aku berlindung kepada Tuhanku dan Tuhanmu dari setiap orang yang menyombongkan diri yang tidak beriman kepada hari perhitungan"},{id:28,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u062c\u064f\u0644\u065e \u0645\u0651\u064f\u0624\u06e1\u0645\u0650\u0646\u065e \u0645\u0651\u0650\u0646\u06e1 \u0621\u064e\u0627\u0644\u0650 \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u064a\u064e\u0643\u06e1\u062a\u064f\u0645\u064f \u0625\u0650\u064a\u0645\u064e\u0670\u0646\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u062a\u064e\u0642\u06e1\u062a\u064f\u0644\u064f\u0648\u0646\u064e \u0631\u064e\u062c\u064f\u0644\u064b\u0627 \u0623\u064e\u0646 \u064a\u064e\u0642\u064f\u0648\u0644\u064e \u0631\u064e\u0628\u0651\u0650\u064a\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0642\u064e\u062f\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0650 \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0625\u0650\u0646 \u064a\u064e\u0643\u064f \u0643\u064e\u0670\u0630\u0650\u0628\u0657\u0627 \u0641\u064e\u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0643\u064e\u0630\u0650\u0628\u064f\u0647\u064f\u06e5\u06d6 \u0648\u064e\u0625\u0650\u0646 \u064a\u064e\u0643\u064f \u0635\u064e\u0627\u062f\u0650\u0642\u0657\u0627 \u064a\u064f\u0635\u0650\u0628\u06e1\u0643\u064f\u0645 \u0628\u064e\u0639\u06e1\u0636\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064e\u0639\u0650\u062f\u064f\u0643\u064f\u0645\u06e1\u06d6 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064e\u0647\u06e1\u062f\u0650\u064a \u0645\u064e\u0646\u06e1 \u0647\u064f\u0648\u064e \u0645\u064f\u0633\u06e1\u0631\u0650\u0641\u065e \u0643\u064e\u0630\u0651\u064e\u0627\u0628\u065e",translation:"Dan seseorang yang beriman di antara keluarga Fir'aun yang menyembunyikan imannya berkata, \"Apakah kamu akan membunuh seseorang karena dia berkata, \"Tuhanku adalah Allah,\" padahal sungguh, dia telah datang kepadamu dengan membawa bukti-bukti yang nyata dari Tuhanmu. Dan jika dia seorang pendusta maka dialah yang akan menanggung (dosa) dustanya; dan jika dia seorang yang benar, niscaya sebagian (bencana) yang diancamkannya kepadamu akan menimpamu. Sesungguhnya Allah tidak memberi petunjuk kepada orang yang melampaui batas dan pendusta"},{id:29,text:"\u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064f\u0644\u06e1\u0643\u064f \u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e \u0638\u064e\u0670\u0647\u0650\u0631\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0641\u064e\u0645\u064e\u0646 \u064a\u064e\u0646\u0635\u064f\u0631\u064f\u0646\u064e\u0627 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0623\u06e1\u0633\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0646 \u062c\u064e\u0627\u0653\u0621\u064e\u0646\u064e\u0627\u06da \u0642\u064e\u0627\u0644\u064e \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064f \u0645\u064e\u0627\u0653 \u0623\u064f\u0631\u0650\u064a\u0643\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627\u0653 \u0623\u064e\u0631\u064e\u0649\u0670 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0647\u06e1\u062f\u0650\u064a\u0643\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u0633\u064e\u0628\u0650\u064a\u0644\u064e \u0671\u0644\u0631\u0651\u064e\u0634\u064e\u0627\u062f\u0650",translation:"Wahai kaumku!\" Pada hari ini kerajaan ada padamu dengan berkuasa di bumi, tetapi siapa yang akan menolong kita dari azab Allah jika (azab itu) menimpa kita?\" Fir'aun berkata, \"Aku hanya mengemukakan kepadamu, apa yang aku pandang baik; dan aku hanya menunjukkan kepadamu jalan yang benar"},{id:30,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0621\u064e\u0627\u0645\u064e\u0646\u064e \u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645 \u0645\u0651\u0650\u062b\u06e1\u0644\u064e \u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0623\u064e\u062d\u06e1\u0632\u064e\u0627\u0628\u0650",translation:"Dan orang yang beriman itu berkata, \"Wahai kaumku! Sesungguhnya aku khawatir kamu akan ditimpa (bencana) seperti hari kehancuran golongan yang bersekutu"},{id:31,text:"\u0645\u0650\u062b\u06e1\u0644\u064e \u062f\u064e\u0623\u06e1\u0628\u0650 \u0642\u064e\u0648\u06e1\u0645\u0650 \u0646\u064f\u0648\u062d\u0656 \u0648\u064e\u0639\u064e\u0627\u062f\u0656 \u0648\u064e\u062b\u064e\u0645\u064f\u0648\u062f\u064e \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u0647\u0650\u0645\u06e1\u06da \u0648\u064e\u0645\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0638\u064f\u0644\u06e1\u0645\u0657\u0627 \u0644\u0651\u0650\u0644\u06e1\u0639\u0650\u0628\u064e\u0627\u062f\u0650",translation:"(yakni) seperti kebiasaan kaum Nuh, 'Ad, Samud dan orang-orang yang datang setelah mereka. Padahal Allah tidak menghendaki kezaliman terhadap hamba-hamba-Nya"},{id:32,text:"\u0648\u064e\u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u062a\u0651\u064e\u0646\u064e\u0627\u062f\u0650",translation:"Dan wahai kaumku!\"Sesungguhnya aku benar-benar khawatir terhadapmu akan (siksaan) hari saling memanggil"},{id:33,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u062a\u064f\u0648\u064e\u0644\u0651\u064f\u0648\u0646\u064e \u0645\u064f\u062f\u06e1\u0628\u0650\u0631\u0650\u064a\u0646\u064e \u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646\u06e1 \u0639\u064e\u0627\u0635\u0650\u0645\u0656\u06d7 \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0636\u06e1\u0644\u0650\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646\u06e1 \u0647\u064e\u0627\u062f\u0656",translation:"(yaitu) pada hari (ketika) kamu berpaling ke belakang (lari), tidak ada seorang pun yang mampu menyelamatkan kamu dari (azab) Allah. Dan barangsiapa dibiarkan sesat oleh Allah, niscaya tidak ada sesuatu pun yang mampu memberi petunjuk"},{id:34,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u06e1 \u064a\u064f\u0648\u0633\u064f\u0641\u064f \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f \u0628\u0650\u0671\u0644\u06e1\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0650 \u0641\u064e\u0645\u064e\u0627 \u0632\u0650\u0644\u06e1\u062a\u064f\u0645\u06e1 \u0641\u0650\u064a \u0634\u064e\u0643\u0651\u0656 \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6\u06d6 \u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u064e\u0627 \u0647\u064e\u0644\u064e\u0643\u064e \u0642\u064f\u0644\u06e1\u062a\u064f\u0645\u06e1 \u0644\u064e\u0646 \u064a\u064e\u0628\u06e1\u0639\u064e\u062b\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u0647\u0650\u06e6 \u0631\u064e\u0633\u064f\u0648\u0644\u0657\u0627\u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064f\u0636\u0650\u0644\u0651\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0646\u06e1 \u0647\u064f\u0648\u064e \u0645\u064f\u0633\u06e1\u0631\u0650\u0641\u065e \u0645\u0651\u064f\u0631\u06e1\u062a\u064e\u0627\u0628\u064c",translation:"Dan sungguh, sebelum itu Yusuf telah datang kepadamu dengan membawa bukti-bukti yang nyata, tetapi kamu senantiasa meragukan apa yang dibawanya, bahkan ketika dia wafat, kamu berkata, \"Allah tidak akan mengirim seorang rasul pun setelahnya.\" Demikianlah Allah membiarkan sesat orang yang melampaui batas dan ragu-ragu"},{id:35,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u062c\u064e\u0670\u062f\u0650\u0644\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0653 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u0650\u063a\u064e\u064a\u06e1\u0631\u0650 \u0633\u064f\u0644\u06e1\u0637\u064e\u0670\u0646\u064d \u0623\u064e\u062a\u064e\u0649\u0670\u0647\u064f\u0645\u06e1\u06d6 \u0643\u064e\u0628\u064f\u0631\u064e \u0645\u064e\u0642\u06e1\u062a\u064b\u0627 \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652\u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064e\u0637\u06e1\u0628\u064e\u0639\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0642\u064e\u0644\u06e1\u0628\u0650 \u0645\u064f\u062a\u064e\u0643\u064e\u0628\u0651\u0650\u0631\u0656 \u062c\u064e\u0628\u0651\u064e\u0627\u0631\u0656",translation:"(yaitu) orang-orang yang memperdebatkan ayat-ayat Allah tanpa alasan yang sampai kepada mereka.770) Sangat besar kemurkaan (bagi mereka) di sisi Allah dan orang-orang yang beriman. Demikianlah Allah mengunci hati setiap orang yang sombong dan berlaku sewenang-wenang"},{id:36,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064f \u064a\u064e\u0670\u0647\u064e\u0670\u0645\u064e\u0670\u0646\u064f \u0671\u0628\u06e1\u0646\u0650 \u0644\u0650\u064a \u0635\u064e\u0631\u06e1\u062d\u0657\u0627 \u0644\u0651\u064e\u0639\u064e\u0644\u0651\u0650\u064a\u0653 \u0623\u064e\u0628\u06e1\u0644\u064f\u063a\u064f \u0671\u0644\u06e1\u0623\u064e\u0633\u06e1\u0628\u064e\u0670\u0628\u064e",translation:"Dan Fir'aun berkata, \"Wahai Haman! Buatkanlah untukku suatu bangunan yang tinggi agar aku sampai ke pintu-pintu"},{id:37,text:"\u0623\u064e\u0633\u06e1\u0628\u064e\u0670\u0628\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0641\u064e\u0623\u064e\u0637\u0651\u064e\u0644\u0650\u0639\u064e \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u0650 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0623\u064e\u0638\u064f\u0646\u0651\u064f\u0647\u064f\u06e5 \u0643\u064e\u0670\u0630\u0650\u0628\u0657\u0627\u06da \u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0632\u064f\u064a\u0651\u0650\u0646\u064e \u0644\u0650\u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0633\u064f\u0648\u0653\u0621\u064f \u0639\u064e\u0645\u064e\u0644\u0650\u0647\u0650\u06e6 \u0648\u064e\u0635\u064f\u062f\u0651\u064e \u0639\u064e\u0646\u0650 \u0671\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u0650\u06da \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u064a\u06e1\u062f\u064f \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0641\u0650\u064a \u062a\u064e\u0628\u064e\u0627\u0628\u0656",translation:"(yaitu) pintu-pintu langit, agar aku dapat melihat Tuhannya Musa, tetapi aku tetap memandangnya seorang pendusta.\" Dan demikianlah dijadikan terasa indah bagi Fir'aun perbuatan buruknya itu, dan dia tertutup dari jalan (yang benar); dan tipu daya Fir'aun itu tidak lain hanyalah membawa kerugian"},{id:38,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0621\u064e\u0627\u0645\u064e\u0646\u064e \u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0646\u0650 \u0623\u064e\u0647\u06e1\u062f\u0650\u0643\u064f\u0645\u06e1 \u0633\u064e\u0628\u0650\u064a\u0644\u064e \u0671\u0644\u0631\u0651\u064e\u0634\u064e\u0627\u062f\u0650",translation:"Dan orang yang beriman itu berkata, \"Wahai kaumku! Ikutilah aku, aku akan menunjukkan kepadamu jalan yang benar"},{id:39,text:"\u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0647\u064e\u0670\u0630\u0650\u0647\u0650 \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u064f \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0645\u064e\u062a\u064e\u0670\u0639\u065e \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u064e \u0647\u0650\u064a\u064e \u062f\u064e\u0627\u0631\u064f \u0671\u0644\u06e1\u0642\u064e\u0631\u064e\u0627\u0631\u0650",translation:"Wahai kaumku! Sesungguhnya kehidupan dunia ini hanyalah kesenangan (sementara) dan sesungguhnya akhirat itulah negeri yang kekal"},{id:40,text:"\u0645\u064e\u0646\u06e1 \u0639\u064e\u0645\u0650\u0644\u064e \u0633\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u0657 \u0641\u064e\u0644\u064e\u0627 \u064a\u064f\u062c\u06e1\u0632\u064e\u0649\u0670\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u0650\u062b\u06e1\u0644\u064e\u0647\u064e\u0627\u06d6 \u0648\u064e\u0645\u064e\u0646\u06e1 \u0639\u064e\u0645\u0650\u0644\u064e \u0635\u064e\u0670\u0644\u0650\u062d\u0657\u0627 \u0645\u0651\u0650\u0646 \u0630\u064e\u0643\u064e\u0631\u064d \u0623\u064e\u0648\u06e1 \u0623\u064f\u0646\u062b\u064e\u0649\u0670 \u0648\u064e\u0647\u064f\u0648\u064e \u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u065e \u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u064a\u064e\u062f\u06e1\u062e\u064f\u0644\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u064e \u064a\u064f\u0631\u06e1\u0632\u064e\u0642\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0628\u0650\u063a\u064e\u064a\u06e1\u0631\u0650 \u062d\u0650\u0633\u064e\u0627\u0628\u0656",translation:"Barangsiapa mengerjakan perbuatan jahat, maka dia akan dibalas sebanding dengan kejahatan itu. Dan barangsiapa mengerjakan kebajikan, baik laki-laki maupun perempuan sedangkan dia dalam keadaan beriman, maka mereka akan masuk surga, mereka diberi rezeki didalamnya tidak terhingga"},{id:41,text:"\u06de\u0648\u064e\u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0645\u064e\u0627 \u0644\u0650\u064a\u0653 \u0623\u064e\u062f\u06e1\u0639\u064f\u0648\u0643\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0646\u0651\u064e\u062c\u064e\u0648\u0670\u0629\u0650 \u0648\u064e\u062a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e\u0646\u0650\u064a\u0653 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650",translation:"Dan wahai kaumku! Bagaimanakah ini, aku menyerumu kepada keselamatan, tetapi kamu menyeruku ke neraka"},{id:42,text:"\u062a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e\u0646\u0650\u064a \u0644\u0650\u0623\u064e\u0643\u06e1\u0641\u064f\u0631\u064e \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0623\u064f\u0634\u06e1\u0631\u0650\u0643\u064e \u0628\u0650\u0647\u0650\u06e6 \u0645\u064e\u0627 \u0644\u064e\u064a\u06e1\u0633\u064e \u0644\u0650\u064a \u0628\u0650\u0647\u0650\u06e6 \u0639\u0650\u0644\u06e1\u0645\u065e \u0648\u064e\u0623\u064e\u0646\u064e\u0627\u06e0 \u0623\u064e\u062f\u06e1\u0639\u064f\u0648\u0643\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u0650 \u0671\u0644\u06e1\u063a\u064e\u0641\u0651\u064e\u0640\u0670\u0631\u0650",translation:"(Mengapa) kamu menyeruku agar kafir kepada Allah dan mempersekutukan-Nya dengan sesuatu yang aku tidak mempunyai ilmu tentang itu, padahal aku menyerumu (beriman) kepada Yang Mahaperkasa, Maha Pengampun"},{id:43,text:"\u0644\u064e\u0627 \u062c\u064e\u0631\u064e\u0645\u064e \u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u062a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e\u0646\u0650\u064a\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0644\u064e\u064a\u06e1\u0633\u064e \u0644\u064e\u0647\u064f\u06e5 \u062f\u064e\u0639\u06e1\u0648\u064e\u0629\u065e \u0641\u0650\u064a \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0645\u064e\u0631\u064e\u062f\u0651\u064e\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0671\u0644\u06e1\u0645\u064f\u0633\u06e1\u0631\u0650\u0641\u0650\u064a\u0646\u064e \u0647\u064f\u0645\u06e1 \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650",translation:"Sudah pasti bahwa apa yang kamu serukan aku kepadanya bukanlah suatu seruan yang berguna baik di dunia maupun di akhirat. Dan sesungguhnya tempat kembali kita pasti kepada Allah, dan sesungguhnya orang-orang yang melampaui batas, mereka itu akan menjadi penghuni neraka"},{id:44,text:"\u0641\u064e\u0633\u064e\u062a\u064e\u0630\u06e1\u0643\u064f\u0631\u064f\u0648\u0646\u064e \u0645\u064e\u0627\u0653 \u0623\u064e\u0642\u064f\u0648\u0644\u064f \u0644\u064e\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0623\u064f\u0641\u064e\u0648\u0651\u0650\u0636\u064f \u0623\u064e\u0645\u06e1\u0631\u0650\u064a\u0653 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u064e\u0635\u0650\u064a\u0631\u064f\u06e2 \u0628\u0650\u0671\u0644\u06e1\u0639\u0650\u0628\u064e\u0627\u062f\u0650",translation:"Maka kelak kamu akan ingat kepada apa yang kukatakan kepadamu. Dan aku menyerahkan urusanku kepada Allah. Sungguh, Allah Maha Melihat akan hamba-hamba-Nya"},{id:45,text:"\u0641\u064e\u0648\u064e\u0642\u064e\u0649\u0670\u0647\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0633\u064e\u064a\u0651\u0650\u0640\u0654\u064e\u0627\u062a\u0650 \u0645\u064e\u0627 \u0645\u064e\u0643\u064e\u0631\u064f\u0648\u0627\u0652\u06d6 \u0648\u064e\u062d\u064e\u0627\u0642\u064e \u0628\u0650\u0640\u0654\u064e\u0627\u0644\u0650 \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0633\u064f\u0648\u0653\u0621\u064f \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u0650",translation:"Maka Allah memeliharanya dari kejahatan tipu daya mereka, sedangkan Fir'aun beserta kaumnya dikepung oleh azab yang sangat buruk"},{id:46,text:"\u0671\u0644\u0646\u0651\u064e\u0627\u0631\u064f \u064a\u064f\u0639\u06e1\u0631\u064e\u0636\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627 \u063a\u064f\u062f\u064f\u0648\u0651\u0657\u0627 \u0648\u064e\u0639\u064e\u0634\u0650\u064a\u0651\u0657\u0627\u06da \u0648\u064e\u064a\u064e\u0648\u06e1\u0645\u064e \u062a\u064e\u0642\u064f\u0648\u0645\u064f \u0671\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064f \u0623\u064e\u062f\u06e1\u062e\u0650\u0644\u064f\u0648\u0653\u0627\u0652 \u0621\u064e\u0627\u0644\u064e \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0623\u064e\u0634\u064e\u062f\u0651\u064e \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u0650",translation:"Kepada mereka diperlihatkan neraka, pada pagi dan petang, dan pada hari terjadinya Kiamat. (Lalu kepada malaikat diperintahkan), \"Masukkanlah Fir'aun dan kaumnya ke dalam azab yang sangat keras"},{id:47,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u064a\u064e\u062a\u064e\u062d\u064e\u0627\u0653\u062c\u0651\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0641\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0671\u0644\u0636\u0651\u064f\u0639\u064e\u0641\u064e\u0640\u0670\u0653\u0624\u064f\u0627\u0652 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u064e\u0631\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u0628\u064e\u0639\u0657\u0627 \u0641\u064e\u0647\u064e\u0644\u06e1 \u0623\u064e\u0646\u062a\u064f\u0645 \u0645\u0651\u064f\u063a\u06e1\u0646\u064f\u0648\u0646\u064e \u0639\u064e\u0646\u0651\u064e\u0627 \u0646\u064e\u0635\u0650\u064a\u0628\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650",translation:"Dan (ingatlah), ketika mereka berbantah-bantah dalam neraka, maka orang yang lemah berkata kepada orang-orang yang menyombongkan diri, \"Sesungguhnya kami dahulu adalah pengikut-pengikutmu, maka dapatkah kamu melepaskan sebagian (azab) api neraka yang menimpa kami"},{id:48,text:"\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u064e\u0631\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064f\u0644\u0651\u065e \u0641\u0650\u064a\u0647\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0642\u064e\u062f\u06e1 \u062d\u064e\u0643\u064e\u0645\u064e \u0628\u064e\u064a\u06e1\u0646\u064e \u0671\u0644\u06e1\u0639\u0650\u0628\u064e\u0627\u062f\u0650",translation:"Orang-orang yang menyombongkan diri menjawab, \"Sesungguhnya kita semua sama-sama dalam neraka karena Allah telah menetapkan keputusan antara hamba-hamba-(Nya)"},{id:49,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0644\u0650\u062e\u064e\u0632\u064e\u0646\u064e\u0629\u0650 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0671\u062f\u06e1\u0639\u064f\u0648\u0627\u0652 \u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u06e1 \u064a\u064f\u062e\u064e\u0641\u0651\u0650\u0641\u06e1 \u0639\u064e\u0646\u0651\u064e\u0627 \u064a\u064e\u0648\u06e1\u0645\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u0650",translation:"Dan orang-orang yang berada dalam nereka berkata kepada penjaga-penjaga neraka Jahanam, \"Mohonkanlah kepada Tuhanmu agar Dia meringankan azab atas kami sehari saja"},{id:50,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0648\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0643\u064f \u062a\u064e\u0623\u06e1\u062a\u0650\u064a\u0643\u064f\u0645\u06e1 \u0631\u064f\u0633\u064f\u0644\u064f\u0643\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0650\u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0628\u064e\u0644\u064e\u0649\u0670\u06da \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0641\u064e\u0671\u062f\u06e1\u0639\u064f\u0648\u0627\u0652\u06d7 \u0648\u064e\u0645\u064e\u0627 \u062f\u064f\u0639\u064e\u0640\u0670\u0653\u0624\u064f\u0627\u0652 \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0670\u0644\u064d",translation:"Maka (penjaga-penjaga Jahanam) berkata, \"Apakah rasul-rasul belum datang kepadamu dengan membawa bukti-bukti yang nyata?\" Mereka menjawab, \"Benar, sudah datang.\" (Penjaga-penjaga Jahanam) berkata, 'Berdoalah kamu (sendiri!)\" Namun doa orang-orang kafir itu sia-sia belaka"},{id:51,text:"\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0646\u064e\u0646\u0635\u064f\u0631\u064f \u0631\u064f\u0633\u064f\u0644\u064e\u0646\u064e\u0627 \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u0650 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0648\u064e\u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064e\u0642\u064f\u0648\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u0634\u06e1\u0647\u064e\u0670\u062f\u064f",translation:"Sesungguhnya Kami akan menolong rasul-rasul Kami dan orang-orang yang beriman dalam kehidupan dunia dan pada hari tampilnya para saksi (hari Kiamat)"},{id:52,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u0644\u064e\u0627 \u064a\u064e\u0646\u0641\u064e\u0639\u064f \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0645\u064e\u0639\u06e1\u0630\u0650\u0631\u064e\u062a\u064f\u0647\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0639\u06e1\u0646\u064e\u0629\u064f \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0633\u064f\u0648\u0653\u0621\u064f \u0671\u0644\u062f\u0651\u064e\u0627\u0631\u0650",translation:"(yaitu) hari ketika permintaan maaf tidak berguna bagi orang-orang zalim dan mereka mendapat laknat dan tempat tinggal yang buruk"},{id:53,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649 \u0671\u0644\u06e1\u0647\u064f\u062f\u064e\u0649\u0670 \u0648\u064e\u0623\u064e\u0648\u06e1\u0631\u064e\u062b\u06e1\u0646\u064e\u0627 \u0628\u064e\u0646\u0650\u064a\u0653 \u0625\u0650\u0633\u06e1\u0631\u064e\u0640\u0670\u0653\u0621\u0650\u064a\u0644\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e",translation:"Dan sungguh, Kami telah memberikan petunjuk kepada Musa; dan mewariskan Kitab (Taurat) kepada Bani Israil"},{id:54,text:"\u0647\u064f\u062f\u0657\u0649 \u0648\u064e\u0630\u0650\u0643\u06e1\u0631\u064e\u0649\u0670 \u0644\u0650\u0623\u064f\u0648\u0652\u0644\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0644\u06e1\u0628\u064e\u0670\u0628\u0650",translation:"untuk menjadi petunjuk dan peringatan bagi orang-orang yang berpikiran sehat"},{id:55,text:"\u0641\u064e\u0671\u0635\u06e1\u0628\u0650\u0631\u06e1 \u0625\u0650\u0646\u0651\u064e \u0648\u064e\u0639\u06e1\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u064e\u0642\u0651\u065e \u0648\u064e\u0671\u0633\u06e1\u062a\u064e\u063a\u06e1\u0641\u0650\u0631\u06e1 \u0644\u0650\u0630\u064e\u0646\u06e2\u0628\u0650\u0643\u064e \u0648\u064e\u0633\u064e\u0628\u0651\u0650\u062d\u06e1 \u0628\u0650\u062d\u064e\u0645\u06e1\u062f\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0628\u0650\u0671\u0644\u06e1\u0639\u064e\u0634\u0650\u064a\u0651\u0650 \u0648\u064e\u0671\u0644\u06e1\u0625\u0650\u0628\u06e1\u0643\u064e\u0670\u0631\u0650",translation:"Maka bersabarlah kamu, sesungguhnya janji Allah itu benar, dan mohonlah ampun untuk dosamu dan bertasbihlah seraya memuji Tuhanmu pada waktu petang dan pagi"},{id:56,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u062c\u064e\u0670\u062f\u0650\u0644\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0653 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u0650\u063a\u064e\u064a\u06e1\u0631\u0650 \u0633\u064f\u0644\u06e1\u0637\u064e\u0670\u0646\u064d \u0623\u064e\u062a\u064e\u0649\u0670\u0647\u064f\u0645\u06e1 \u0625\u0650\u0646 \u0641\u0650\u064a \u0635\u064f\u062f\u064f\u0648\u0631\u0650\u0647\u0650\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u0650\u0628\u06e1\u0631\u065e \u0645\u0651\u064e\u0627 \u0647\u064f\u0645 \u0628\u0650\u0628\u064e\u0670\u0644\u0650\u063a\u0650\u064a\u0647\u0650\u06da \u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u0639\u0650\u0630\u06e1 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0647\u064f\u0648\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u0650\u064a\u0639\u064f \u0671\u0644\u06e1\u0628\u064e\u0635\u0650\u064a\u0631\u064f",translation:"Sesungguhnya orang-orang yang memperdebatkan ayat-ayat Allah tanpa alasan (bukti) yang sampai kepada mereka, yang ada dalam dada mereka hanyalah (keinginan akan) kebesaran yang tidak akan mereka capai, maka mintalah perlindungan kepada Allah. Sungguh, Dia Maha Mendengar, Maha Melihat"},{id:57,text:"\u0644\u064e\u062e\u064e\u0644\u06e1\u0642\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0623\u064e\u0643\u06e1\u0628\u064e\u0631\u064f \u0645\u0650\u0646\u06e1 \u062e\u064e\u0644\u06e1\u0642\u0650 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Sungguh, penciptaan langit dan bumi itu lebih besar daripada penciptaan manusia, akan tetapi kebanyakan manusia tidak mengetahui"},{id:58,text:"\u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0648\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0639\u06e1\u0645\u064e\u0649\u0670 \u0648\u064e\u0671\u0644\u06e1\u0628\u064e\u0635\u0650\u064a\u0631\u064f \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0648\u064e\u0644\u064e\u0627 \u0671\u0644\u06e1\u0645\u064f\u0633\u0650\u064a\u0653\u0621\u064f\u06da \u0642\u064e\u0644\u0650\u064a\u0644\u0657\u0627 \u0645\u0651\u064e\u0627 \u062a\u064e\u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan tidak sama orang yang buta dengan orang yang melihat, dan tidak (sama) pula orang-orang yang beriman dan mengerjakan kebajikan dengan orang-orang yang berbuat kejahatan. Hanya sedikit sekali yang kamu ambil pelajaran"},{id:59,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064e \u0644\u064e\u0623\u0653\u062a\u0650\u064a\u064e\u0629\u065e \u0644\u0651\u064e\u0627 \u0631\u064e\u064a\u06e1\u0628\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Sesungguhnya hari Kiamat pasti akan datang, tidak ada keraguan tentangnya, akan tetapi kebanyakan manusia tidak beriman"},{id:60,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u064f \u0671\u062f\u06e1\u0639\u064f\u0648\u0646\u0650\u064a\u0653 \u0623\u064e\u0633\u06e1\u062a\u064e\u062c\u0650\u0628\u06e1 \u0644\u064e\u0643\u064f\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u0650\u0631\u064f\u0648\u0646\u064e \u0639\u064e\u0646\u06e1 \u0639\u0650\u0628\u064e\u0627\u062f\u064e\u062a\u0650\u064a \u0633\u064e\u064a\u064e\u062f\u06e1\u062e\u064f\u0644\u064f\u0648\u0646\u064e \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u062f\u064e\u0627\u062e\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan Tuhanmu berfirman, \"Berdoalah kepada-Ku, niscaya akan Aku perkenankan bagimu. Sesungguhnya orang-orang yang sombong tidak mau menyembah-Ku akan masuk neraka Jahanam dalam keadaan hina dina"},{id:61,text:"\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u064e \u0644\u0650\u062a\u064e\u0633\u06e1\u0643\u064f\u0646\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0647\u0650 \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u0645\u064f\u0628\u06e1\u0635\u0650\u0631\u064b\u0627\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0630\u064f\u0648 \u0641\u064e\u0636\u06e1\u0644\u064d \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0627 \u064a\u064e\u0634\u06e1\u0643\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Allah lah yang menjadikan malam untukmu agar kamu beristirahat padanya; (dan menjadikan) siang terang benderang. Sungguh, Allah benar-benar memiliki karunia yang dilimpahkan kepada manusia, tetapi kebanyakan manusia tidak bersyukur"},{id:62,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u06e1 \u062e\u064e\u0670\u0644\u0650\u0642\u064f \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0644\u0651\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e\u06d6 \u0641\u064e\u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u062a\u064f\u0624\u06e1\u0641\u064e\u0643\u064f\u0648\u0646\u064e",translation:"Demikianlah Allah, Tuhanmu, Pencipta segala sesuatu, tidak ada tuhan selain Dia; maka bagaimanakah kamu dapat dipalingkan"},{id:63,text:"\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064f\u0624\u06e1\u0641\u064e\u0643\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u062c\u06e1\u062d\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Demikianlah orang-orang yang selalu mengingkari ayat-ayat Allah dipalingkan"},{id:64,text:"\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0642\u064e\u0631\u064e\u0627\u0631\u0657\u0627 \u0648\u064e\u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u064e \u0628\u0650\u0646\u064e\u0627\u0653\u0621\u0657 \u0648\u064e\u0635\u064e\u0648\u0651\u064e\u0631\u064e\u0643\u064f\u0645\u06e1 \u0641\u064e\u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064e \u0635\u064f\u0648\u064e\u0631\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0631\u064e\u0632\u064e\u0642\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0637\u0651\u064e\u064a\u0651\u0650\u0628\u064e\u0670\u062a\u0650\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u06e1\u06d6 \u0641\u064e\u062a\u064e\u0628\u064e\u0627\u0631\u064e\u0643\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0631\u064e\u0628\u0651\u064f \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Allah lah yang menjadikan bumi untukmu sebagai tempat menetap dan langit sebagai atap, dan membentukmu lalu memperindah rupamu serta memberimu rezeki dari yang baik-baik. Demikianlah Allah, Tuhanmu, Mahasuci Allah, Tuhan seluruh alam"},{id:65,text:"\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u062d\u064e\u064a\u0651\u064f \u0644\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u0641\u064e\u0671\u062f\u06e1\u0639\u064f\u0648\u0647\u064f \u0645\u064f\u062e\u06e1\u0644\u0650\u0635\u0650\u064a\u0646\u064e \u0644\u064e\u0647\u064f \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u064e\u06d7 \u0671\u0644\u06e1\u062d\u064e\u0645\u06e1\u062f\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0631\u064e\u0628\u0651\u0650 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Dialah yang hidup kekal, tidak ada tuhan selain Dia; maka sembahlah Dia dengan tulus ikhlas beragama kepada-Nya. Segala puji bagi Allah Tuhan seluruh alam"},{id:66,text:"\u06de\u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u0650\u064a \u0646\u064f\u0647\u0650\u064a\u062a\u064f \u0623\u064e\u0646\u06e1 \u0623\u064e\u0639\u06e1\u0628\u064f\u062f\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u0646\u0650\u064a\u064e \u0671\u0644\u06e1\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u064f \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u0623\u064f\u0645\u0650\u0631\u06e1\u062a\u064f \u0623\u064e\u0646\u06e1 \u0623\u064f\u0633\u06e1\u0644\u0650\u0645\u064e \u0644\u0650\u0631\u064e\u0628\u0651\u0650 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Katakanlah (Muhammad), \"Sungguh, aku dilarang menyembah sembahan yang kamu sembah selain Allah, setelah datang kepadaku keterangan-keterangan dari Tuhanku; dan aku diperintahkan agar berserah diri kepada Tuhan seluruh alam"},{id:67,text:"\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u062a\u064f\u0631\u064e\u0627\u0628\u0656 \u062b\u064f\u0645\u0651\u064e \u0645\u0650\u0646 \u0646\u0651\u064f\u0637\u06e1\u0641\u064e\u0629\u0656 \u062b\u064f\u0645\u0651\u064e \u0645\u0650\u0646\u06e1 \u0639\u064e\u0644\u064e\u0642\u064e\u0629\u0656 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u062e\u06e1\u0631\u0650\u062c\u064f\u0643\u064f\u0645\u06e1 \u0637\u0650\u0641\u06e1\u0644\u0657\u0627 \u062b\u064f\u0645\u0651\u064e \u0644\u0650\u062a\u064e\u0628\u06e1\u0644\u064f\u063a\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0634\u064f\u062f\u0651\u064e\u0643\u064f\u0645\u06e1 \u062b\u064f\u0645\u0651\u064e \u0644\u0650\u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u0634\u064f\u064a\u064f\u0648\u062e\u0657\u0627\u06da \u0648\u064e\u0645\u0650\u0646\u0643\u064f\u0645 \u0645\u0651\u064e\u0646 \u064a\u064f\u062a\u064e\u0648\u064e\u0641\u0651\u064e\u0649\u0670 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f\u06d6 \u0648\u064e\u0644\u0650\u062a\u064e\u0628\u06e1\u0644\u064f\u063a\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u062c\u064e\u0644\u0657\u0627 \u0645\u0651\u064f\u0633\u064e\u0645\u0651\u0657\u0649 \u0648\u064e\u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Dialah yang menciptakanmu dari tanah, kemudian dari setetes mani, lalu dari segumpal darah, kemudian kamu dilahirkan sebagai seorang anak, kemudian dibiarkan kamu sampai dewasa, lalu menjadi tua. Tetapi di antara kamu ada yang dimatikan sebelum itu. (Kami perbuat demikian) agar kamu sampai kepada kurun waktu yang ditentukan, agar kamu mengerti"},{id:68,text:"\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u062d\u06e1\u064a\u0650\u06e6 \u0648\u064e\u064a\u064f\u0645\u0650\u064a\u062a\u064f\u06d6 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u064e\u0636\u064e\u0649\u0670\u0653 \u0623\u064e\u0645\u06e1\u0631\u0657\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0644\u064e\u0647\u064f\u06e5 \u0643\u064f\u0646 \u0641\u064e\u064a\u064e\u0643\u064f\u0648\u0646\u064f",translation:"Dialah yang menghidupkan dan mematikan. Maka apabila Dia hendak menetapkan suatu urusan, Dia hanya berkata kepadanya, \"Jadilah!\" Maka jadilah sesuatu itu"},{id:69,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0631\u064e \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u062c\u064e\u0670\u062f\u0650\u0644\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0653 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u064a\u064f\u0635\u06e1\u0631\u064e\u0641\u064f\u0648\u0646\u064e",translation:"Apakah kamu tidak memperhatikan orang-orang yang (selalu) membantah ayat-ayat Allah? Bagaimana mereka dapat dipalingkan"},{id:70,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0648\u064e\u0628\u0650\u0645\u064e\u0627\u0653 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0628\u0650\u0647\u0650\u06e6 \u0631\u064f\u0633\u064f\u0644\u064e\u0646\u064e\u0627\u06d6 \u0641\u064e\u0633\u064e\u0648\u06e1\u0641\u064e \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"(Yaitu) orang-orang yang mendustakan Kitab (Alquran) dan wahyu yang dibawa oleh rasul-rasul Kami yang telah Kami utus. Kelak mereka akan mengetahui"},{id:71,text:"\u0625\u0650\u0630\u0650 \u0671\u0644\u06e1\u0623\u064e\u063a\u06e1\u0644\u064e\u0670\u0644\u064f \u0641\u0650\u064a\u0653 \u0623\u064e\u0639\u06e1\u0646\u064e\u0670\u0642\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0671\u0644\u0633\u0651\u064e\u0644\u064e\u0670\u0633\u0650\u0644\u064f \u064a\u064f\u0633\u06e1\u062d\u064e\u0628\u064f\u0648\u0646\u064e",translation:"ketika belenggu dan rantai dipasang di leher mereka, seraya mereka diseret"},{id:72,text:"\u0641\u0650\u064a \u0671\u0644\u06e1\u062d\u064e\u0645\u0650\u064a\u0645\u0650 \u062b\u064f\u0645\u0651\u064e \u0641\u0650\u064a \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u064a\u064f\u0633\u06e1\u062c\u064e\u0631\u064f\u0648\u0646\u064e",translation:"ke dalam air yang sangat panas, kemudian mereka dibakar dalam api"},{id:73,text:"\u062b\u064f\u0645\u0651\u064e \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u064a\u06e1\u0646\u064e \u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064f\u0634\u06e1\u0631\u0650\u0643\u064f\u0648\u0646\u064e",translation:"kemudian dikatakan kepada mereka, \"Manakah berhala-berhala yang selalu kamu persekutukan"},{id:74,text:"\u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0636\u064e\u0644\u0651\u064f\u0648\u0627\u0652 \u0639\u064e\u0646\u0651\u064e\u0627 \u0628\u064e\u0644 \u0644\u0651\u064e\u0645\u06e1 \u0646\u064e\u0643\u064f\u0646 \u0646\u0651\u064e\u062f\u06e1\u0639\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627\u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064f\u0636\u0650\u0644\u0651\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"(yang kamu sembah) selain Allah?\" Mereka menjawab, \"Mereka telah hilang lenyap dari kami, bahkan kami dahulu tidak pernah menyembah sesuatu.\" Demikianlah Allah membiarkan sesat orang-orang kafir"},{id:75,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645 \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0641\u06e1\u0631\u064e\u062d\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0628\u0650\u063a\u064e\u064a\u06e1\u0631\u0650 \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0645\u06e1\u0631\u064e\u062d\u064f\u0648\u0646\u064e",translation:"Yang demikian itu disebabkan karena kamu bersuka ria di bumi (tanpa) mengindahkan kebenaran dan karena kamu selalu bersuka ria (dalam kemaksiatan)"},{id:76,text:"\u0671\u062f\u06e1\u062e\u064f\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0628\u06e1\u0648\u064e\u0670\u0628\u064e \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u062e\u064e\u0670\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627\u06d6 \u0641\u064e\u0628\u0650\u0626\u06e1\u0633\u064e \u0645\u064e\u062b\u06e1\u0648\u064e\u0649 \u0671\u0644\u06e1\u0645\u064f\u062a\u064e\u0643\u064e\u0628\u0651\u0650\u0631\u0650\u064a\u0646\u064e",translation:"(Dikatakan kepada mereka), \"Masuklah kamu ke pintu-pintu neraka Jahanam, dan kamu kekal di dalamnya. Maka itulah seburuk-buruk tempat bagi orang-orang yang sombong"},{id:77,text:"\u0641\u064e\u0671\u0635\u06e1\u0628\u0650\u0631\u06e1 \u0625\u0650\u0646\u0651\u064e \u0648\u064e\u0639\u06e1\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u064e\u0642\u0651\u065e\u06da \u0641\u064e\u0625\u0650\u0645\u0651\u064e\u0627 \u0646\u064f\u0631\u0650\u064a\u064e\u0646\u0651\u064e\u0643\u064e \u0628\u064e\u0639\u06e1\u0636\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0646\u064e\u0639\u0650\u062f\u064f\u0647\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1 \u0646\u064e\u062a\u064e\u0648\u064e\u0641\u0651\u064e\u064a\u064e\u0646\u0651\u064e\u0643\u064e \u0641\u064e\u0625\u0650\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u064a\u064f\u0631\u06e1\u062c\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Maka bersabarlah engkau (Muhammad), sesungguhnya janji Allah itu benar. Meskipun Kami perlihatkan kepadamu sebagian siksa yang Kami ancamkan kepada mereka, atau pun Kami wafatkan engkau (sebelum ajal menimpa mereka), namun kepada Kamilah mereka dikembalikan"},{id:78,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0631\u064f\u0633\u064f\u0644\u0657\u0627 \u0645\u0651\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064e \u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0646 \u0642\u064e\u0635\u064e\u0635\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0648\u064e\u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0646 \u0644\u0651\u064e\u0645\u06e1 \u0646\u064e\u0642\u06e1\u0635\u064f\u0635\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e\u06d7 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0631\u064e\u0633\u064f\u0648\u0644\u064d \u0623\u064e\u0646 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0629\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0625\u0650\u0630\u06e1\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e \u0623\u064e\u0645\u06e1\u0631\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0642\u064f\u0636\u0650\u064a\u064e \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u062e\u064e\u0633\u0650\u0631\u064e \u0647\u064f\u0646\u064e\u0627\u0644\u0650\u0643\u064e \u0671\u0644\u06e1\u0645\u064f\u0628\u06e1\u0637\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Dan sungguh, Kami telah mengutus beberapa rasul sebelum engkau (Muhammad), di antara mereka ada yang Kami ceritakan kepadamu dan di antaranya ada (pula) yang tidak Kami ceritakan kepadamu. Tidak ada seorang rasul membawa suatu mukjizat, kecuali seizin Allah. Maka apabila telah datang perintah Allah, (untuk semua perkara) diputuskan dengan adil. Dan ketika itu rugilah orang-orang yang berpegang kepada yang batil"},{id:79,text:"\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0639\u064e\u0670\u0645\u064e \u0644\u0650\u062a\u064e\u0631\u06e1\u0643\u064e\u0628\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0648\u064e\u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u062a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f\u0648\u0646\u064e",translation:"Allah lah yang menjadikan hewan ternak untukmu, sebagian untuk kamu kendarai dan sebagian lagi kamu makan"},{id:80,text:"\u0648\u064e\u0644\u064e\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u064e\u0646\u064e\u0670\u0641\u0650\u0639\u064f \u0648\u064e\u0644\u0650\u062a\u064e\u0628\u06e1\u0644\u064f\u063a\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627 \u062d\u064e\u0627\u062c\u064e\u0629\u0657 \u0641\u0650\u064a \u0635\u064f\u062f\u064f\u0648\u0631\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627 \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0641\u064f\u0644\u06e1\u0643\u0650 \u062a\u064f\u062d\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan bagi kamu (ada lagi) manfaat-manfaat yang lain padanya (hewan ternak itu) dan agar kamu mencapai suatu keperluan (tujuan) yang tersimpan dalam hatimu (dengan mengendarainya). Dan dengan mengendarai binatang-binatang itu, dan di atas kapal mereka diangkut"},{id:81,text:"\u0648\u064e\u064a\u064f\u0631\u0650\u064a\u0643\u064f\u0645\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0647\u0650\u06e6 \u0641\u064e\u0623\u064e\u064a\u0651\u064e \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064f\u0646\u0643\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Dan Dia memperlihatkan tanda-tanda (kebesaran-Nya) kepadamu. Lalu tanda-tanda (kebesaran) Allah yang mana yang kamu ingkari"},{id:82,text:"\u0623\u064e\u0641\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0633\u0650\u064a\u0631\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0641\u064e\u064a\u064e\u0646\u0638\u064f\u0631\u064f\u0648\u0627\u0652 \u0643\u064e\u064a\u06e1\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0670\u0642\u0650\u0628\u064e\u0629\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u0645\u06e1\u06da \u0643\u064e\u0627\u0646\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064e \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0634\u064e\u062f\u0651\u064e \u0642\u064f\u0648\u0651\u064e\u0629\u0657 \u0648\u064e\u0621\u064e\u0627\u062b\u064e\u0627\u0631\u0657\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0641\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u063a\u06e1\u0646\u064e\u0649\u0670 \u0639\u064e\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0643\u06e1\u0633\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Maka apakah mereka tidak mengadakan perjalanan di bumi, lalu mereka memperhatikan bagaimana kesudahan orang-orang yang sebelum mereka. Mereka itu lebih banyak dan lebih hebat kekuatannya serta (lebih banyak) peninggalan-peninggalan peradabannya di bumi,771) maka apa yang mereka usahakan itu tidak dapat menolong mereka"},{id:83,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u062a\u06e1\u0647\u064f\u0645\u06e1 \u0631\u064f\u0633\u064f\u0644\u064f\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0650 \u0641\u064e\u0631\u0650\u062d\u064f\u0648\u0627\u0652 \u0628\u0650\u0645\u064e\u0627 \u0639\u0650\u0646\u062f\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0639\u0650\u0644\u06e1\u0645\u0650 \u0648\u064e\u062d\u064e\u0627\u0642\u064e \u0628\u0650\u0647\u0650\u0645 \u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6 \u064a\u064e\u0633\u06e1\u062a\u064e\u0647\u06e1\u0632\u0650\u0621\u064f\u0648\u0646\u064e",translation:"(Maka ketika para rasul datang kepada mereka dengan membawa bukti-bukti yang nyata, mereka merasa senang dengan ilmu yang ada pada mereka772) dan mereka dikepung oleh (azab) yang dahulu mereka memperolok-olokkannya"},{id:84,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0631\u064e\u0623\u064e\u0648\u06e1\u0627\u0652 \u0628\u064e\u0623\u06e1\u0633\u064e\u0646\u064e\u0627 \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0621\u064e\u0627\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u062d\u06e1\u062f\u064e\u0647\u064f\u06e5 \u0648\u064e\u0643\u064e\u0641\u064e\u0631\u06e1\u0646\u064e\u0627 \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0628\u0650\u0647\u0650\u06e6 \u0645\u064f\u0634\u06e1\u0631\u0650\u0643\u0650\u064a\u0646\u064e",translation:"Maka ketika mereka melihat azab Kami, mereka berkata, \"Kami hanya beriman kepada Allah saja dan kami ingkar kepada sembahan-sembahan yang telah kami persekutukan dengan Allah"},{id:85,text:"\u0641\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0643\u064f \u064a\u064e\u0646\u0641\u064e\u0639\u064f\u0647\u064f\u0645\u06e1 \u0625\u0650\u064a\u0645\u064e\u0670\u0646\u064f\u0647\u064f\u0645\u06e1 \u0644\u064e\u0645\u0651\u064e\u0627 \u0631\u064e\u0623\u064e\u0648\u06e1\u0627\u0652 \u0628\u064e\u0623\u06e1\u0633\u064e\u0646\u064e\u0627\u06d6 \u0633\u064f\u0646\u0651\u064e\u062a\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u0651\u064e\u062a\u0650\u064a \u0642\u064e\u062f\u06e1 \u062e\u064e\u0644\u064e\u062a\u06e1 \u0641\u0650\u064a \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u062e\u064e\u0633\u0650\u0631\u064e \u0647\u064f\u0646\u064e\u0627\u0644\u0650\u0643\u064e \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Maka iman mereka ketika mereka telah melihat azab Kami tidak berguna lagi bagi mereka. Itulah (ketentuan) Allah yang telah berlaku terhadap hamba-hamba-Nya. Dan ketika itu rugilah orang-orang kafir"}]},{id:41,name:"\u0641\u0635\u0644\u062a",transliteration:"Fussilat",translation:"Yang Dijelaskan",type:"meccan",total_verses:54,verses:[{id:1,text:"\u062d\u0645\u0653",translation:"\u1e24\u0101 M\u012bm"},{id:2,text:"\u062a\u064e\u0646\u0632\u0650\u064a\u0644\u065e \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u0650 \u0671\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650",translation:"(Alquran ini) diturunkah dari Tuhan Yang Maha Pengasih, Maha Penyayang"},{id:3,text:"\u0643\u0650\u062a\u064e\u0670\u0628\u065e \u0641\u064f\u0635\u0651\u0650\u0644\u064e\u062a\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u064f\u0647\u064f\u06e5 \u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u064b\u0627 \u0639\u064e\u0631\u064e\u0628\u0650\u064a\u0651\u0657\u0627 \u0644\u0651\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Kitab yang ayat-ayatnya djelaskan, bacaan dalam bahasa Arab, untuk kaum yang mengetahui"},{id:4,text:"\u0628\u064e\u0634\u0650\u064a\u0631\u0657\u0627 \u0648\u064e\u0646\u064e\u0630\u0650\u064a\u0631\u0657\u0627 \u0641\u064e\u0623\u064e\u0639\u06e1\u0631\u064e\u0636\u064e \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064f\u0647\u064f\u0645\u06e1 \u0641\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u0645\u064e\u0639\u064f\u0648\u0646\u064e",translation:"yang membawa berita gembira dan peringatan, tetapi kebanyakan mereka berpaling (darinya) serta tidak mendengarkan"},{id:5,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0646\u064e\u0627 \u0641\u0650\u064a\u0653 \u0623\u064e\u0643\u0650\u0646\u0651\u064e\u0629\u0656 \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0648\u064e\u0641\u0650\u064a\u0653 \u0621\u064e\u0627\u0630\u064e\u0627\u0646\u0650\u0646\u064e\u0627 \u0648\u064e\u0642\u06e1\u0631\u065e \u0648\u064e\u0645\u0650\u0646\u06e2 \u0628\u064e\u064a\u06e1\u0646\u0650\u0646\u064e\u0627 \u0648\u064e\u0628\u064e\u064a\u06e1\u0646\u0650\u0643\u064e \u062d\u0650\u062c\u064e\u0627\u0628\u065e \u0641\u064e\u0671\u0639\u06e1\u0645\u064e\u0644\u06e1 \u0625\u0650\u0646\u0651\u064e\u0646\u064e\u0627 \u0639\u064e\u0670\u0645\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Dan mereka berkata, \"Hati kami sudah tertutup dari apa yang engkau seru kami kepadanya dan telinga kami sudah tersumbat, dan di antara kami dan engkau ada dinding, karena itu lakukanlah (sesuai kehendakmu), sesungguhnya kami akan melakukan (sesuai kehendak kami)"},{id:6,text:"\u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u064e\u0627\u06e0 \u0628\u064e\u0634\u064e\u0631\u065e \u0645\u0651\u0650\u062b\u06e1\u0644\u064f\u0643\u064f\u0645\u06e1 \u064a\u064f\u0648\u062d\u064e\u0649\u0670\u0653 \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u064f\u0643\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0670\u0647\u065e \u0648\u064e\u0670\u062d\u0650\u062f\u065e \u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u0642\u0650\u064a\u0645\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0648\u064e\u0671\u0633\u06e1\u062a\u064e\u063a\u06e1\u0641\u0650\u0631\u064f\u0648\u0647\u064f\u06d7 \u0648\u064e\u0648\u064e\u064a\u06e1\u0644\u065e \u0644\u0651\u0650\u0644\u06e1\u0645\u064f\u0634\u06e1\u0631\u0650\u0643\u0650\u064a\u0646\u064e",translation:"Katakanlah (Muhammad), \"Aku ini hanyalah seorang manusia seperti kamu, yang diwahyukan kepadaku bahwa Tuhan kamu adalah Tuhan Yang Maha Esa, karena itu tetaplah kamu (beribadah) kepada-Nya dan mohonlah ampunan kepada-Nya. Dan celakalah bagi orang-orang yang mempersekutukan-(Nya)"},{id:7,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u062a\u064f\u0648\u0646\u064e \u0671\u0644\u0632\u0651\u064e\u0643\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0647\u064f\u0645\u06e1 \u0643\u064e\u0670\u0641\u0650\u0631\u064f\u0648\u0646\u064e",translation:"(yaitu) orang-orang yang tidak menunaikan zakat dan mereka ingkar terhadap kehidupan akhirat"},{id:8,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u062c\u06e1\u0631\u064c \u063a\u064e\u064a\u06e1\u0631\u064f \u0645\u064e\u0645\u06e1\u0646\u064f\u0648\u0646\u0656",translation:"Sesungguhnya orang-orang yang beriman dan mengerjakan kebajikan, mereka mendapat pahala yang tidak ada putus-putusnya"},{id:9,text:"\u06de\u0642\u064f\u0644\u06e1 \u0623\u064e\u0626\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0644\u064e\u062a\u064e\u0643\u06e1\u0641\u064f\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0641\u0650\u064a \u064a\u064e\u0648\u06e1\u0645\u064e\u064a\u06e1\u0646\u0650 \u0648\u064e\u062a\u064e\u062c\u06e1\u0639\u064e\u0644\u064f\u0648\u0646\u064e \u0644\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u0646\u062f\u064e\u0627\u062f\u0657\u0627\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0631\u064e\u0628\u0651\u064f \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Katakanlah, \"Pantaskah kamu ingkar kepada Tuhan yang menciptakan bumi dalam dua masa dan kamu adakan pula sekutu-sekutu bagi-Nya? Itulah Tuhan seluruh alam"},{id:10,text:"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0631\u064e\u0648\u064e\u0670\u0633\u0650\u064a\u064e \u0645\u0650\u0646 \u0641\u064e\u0648\u06e1\u0642\u0650\u0647\u064e\u0627 \u0648\u064e\u0628\u064e\u0670\u0631\u064e\u0643\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0642\u064e\u062f\u0651\u064e\u0631\u064e \u0641\u0650\u064a\u0647\u064e\u0627\u0653 \u0623\u064e\u0642\u06e1\u0648\u064e\u0670\u062a\u064e\u0647\u064e\u0627 \u0641\u0650\u064a\u0653 \u0623\u064e\u0631\u06e1\u0628\u064e\u0639\u064e\u0629\u0650 \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u0656 \u0633\u064e\u0648\u064e\u0627\u0653\u0621\u0657 \u0644\u0651\u0650\u0644\u0633\u0651\u064e\u0627\u0653\u0626\u0650\u0644\u0650\u064a\u0646\u064e",translation:"Dan Dia ciptakan padanya gunung-gunung yang kokoh di atasnya. Dan kemudian Dia berkahi, dan Dia tentukan makanan-makanan (bagi penghuni)nya dalam empat masa, memadai untuk (memenuhi kebutuhan) mereka yang memerlukannya"},{id:11,text:"\u062b\u064f\u0645\u0651\u064e \u0671\u0633\u06e1\u062a\u064e\u0648\u064e\u0649\u0670\u0653 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0648\u064e\u0647\u0650\u064a\u064e \u062f\u064f\u062e\u064e\u0627\u0646\u065e \u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064e\u0627 \u0648\u064e\u0644\u0650\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0671\u0626\u06e1\u062a\u0650\u064a\u064e\u0627 \u0637\u064e\u0648\u06e1\u0639\u064b\u0627 \u0623\u064e\u0648\u06e1 \u0643\u064e\u0631\u06e1\u0647\u0657\u0627 \u0642\u064e\u0627\u0644\u064e\u062a\u064e\u0627\u0653 \u0623\u064e\u062a\u064e\u064a\u06e1\u0646\u064e\u0627 \u0637\u064e\u0627\u0653\u0626\u0650\u0639\u0650\u064a\u0646\u064e",translation:"Kemudian Dia menuju ke langit dan (langit) itu masih berupa asap, lalu Dia berfirman kepadanya dan kepada bumi, \"Datanglah kamu berdua menurut perintah-Ku dengan patuh atau terpaksa.\" Keduanya menjawab, \"Kami datang dengan patuh"},{id:12,text:"\u0641\u064e\u0642\u064e\u0636\u064e\u0649\u0670\u0647\u064f\u0646\u0651\u064e \u0633\u064e\u0628\u06e1\u0639\u064e \u0633\u064e\u0645\u064e\u0670\u0648\u064e\u0627\u062a\u0656 \u0641\u0650\u064a \u064a\u064e\u0648\u06e1\u0645\u064e\u064a\u06e1\u0646\u0650 \u0648\u064e\u0623\u064e\u0648\u06e1\u062d\u064e\u0649\u0670 \u0641\u0650\u064a \u0643\u064f\u0644\u0651\u0650 \u0633\u064e\u0645\u064e\u0627\u0653\u0621\u064d \u0623\u064e\u0645\u06e1\u0631\u064e\u0647\u064e\u0627\u06da \u0648\u064e\u0632\u064e\u064a\u0651\u064e\u0646\u0651\u064e\u0627 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0628\u0650\u0645\u064e\u0635\u064e\u0670\u0628\u0650\u064a\u062d\u064e \u0648\u064e\u062d\u0650\u0641\u06e1\u0638\u0657\u0627\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062a\u064e\u0642\u06e1\u062f\u0650\u064a\u0631\u064f \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u0650 \u0671\u0644\u06e1\u0639\u064e\u0644\u0650\u064a\u0645\u0650",translation:"Lalu diciptakan-Nya tujuh langit dalam dua masa dan pada setiap langit Dia mewahyukan urusan masing-masing. Kemudian langit yang dekat (dengan bumi), Kami hiasi dengan bintang-bintang, dan (Kami ciptakan itu) untuk memelihara. Demikianlah ketentuan (Allah) Yang Mahaperkasa, Maha Mengetahui"},{id:13,text:"\u0641\u064e\u0625\u0650\u0646\u06e1 \u0623\u064e\u0639\u06e1\u0631\u064e\u0636\u064f\u0648\u0627\u0652 \u0641\u064e\u0642\u064f\u0644\u06e1 \u0623\u064e\u0646\u0630\u064e\u0631\u06e1\u062a\u064f\u0643\u064f\u0645\u06e1 \u0635\u064e\u0670\u0639\u0650\u0642\u064e\u0629\u0657 \u0645\u0651\u0650\u062b\u06e1\u0644\u064e \u0635\u064e\u0670\u0639\u0650\u0642\u064e\u0629\u0650 \u0639\u064e\u0627\u062f\u0656 \u0648\u064e\u062b\u064e\u0645\u064f\u0648\u062f\u064e",translation:"Jika mereka berpaling maka katakanlah, \"Aku telah memperingatkan kamu akan (bencana) petir seperti petir yang menimpa kaum '\u0100d dan kaum Samud"},{id:14,text:"\u0625\u0650\u0630\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u062a\u06e1\u0647\u064f\u0645\u064f \u0671\u0644\u0631\u0651\u064f\u0633\u064f\u0644\u064f \u0645\u0650\u0646\u06e2 \u0628\u064e\u064a\u06e1\u0646\u0650 \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u0647\u0650\u0645\u06e1 \u0648\u064e\u0645\u0650\u0646\u06e1 \u062e\u064e\u0644\u06e1\u0641\u0650\u0647\u0650\u0645\u06e1 \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064e\u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0648\u06e1 \u0634\u064e\u0627\u0653\u0621\u064e \u0631\u064e\u0628\u0651\u064f\u0646\u064e\u0627 \u0644\u064e\u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u0657 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0628\u0650\u0645\u064e\u0627\u0653 \u0623\u064f\u0631\u06e1\u0633\u0650\u0644\u06e1\u062a\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6 \u0643\u064e\u0670\u0641\u0650\u0631\u064f\u0648\u0646\u064e",translation:"(Ketika para rasul datang kepada mereka dari depan dan dari belakang mereka773) (dengan menyerukan), \"Janganlah kamu menyembah selain Allah!\" Mereka menjawab, \"Kalau Tuhan kami menghendaki tentu Dia menurunkan malaikat-malaikat-Nya, maka sesungguhnya kami mengingkari wahyu yang engkau diutus menyampaikannya"},{id:15,text:"\u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0639\u064e\u0627\u062f\u065e \u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u064e\u0631\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0628\u0650\u063a\u064e\u064a\u06e1\u0631\u0650 \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0645\u064e\u0646\u06e1 \u0623\u064e\u0634\u064e\u062f\u0651\u064f \u0645\u0650\u0646\u0651\u064e\u0627 \u0642\u064f\u0648\u0651\u064e\u0629\u064b\u06d6 \u0623\u064e\u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0631\u064e\u0648\u06e1\u0627\u0652 \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e\u0647\u064f\u0645\u06e1 \u0647\u064f\u0648\u064e \u0623\u064e\u0634\u064e\u062f\u0651\u064f \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0642\u064f\u0648\u0651\u064e\u0629\u0657\u06d6 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u064a\u064e\u062c\u06e1\u062d\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Maka adapun kaum '\u0100d, mereka menyombongkan diri di bumi tanpa (mengindahkan) kebenaran dan mereka berkata, \"Siapakah yang lebih hebat kekuatannya dari kami?\" Tidakkah mereka memperhatikan bahwa sesungguhnya Allah yang menciptakan mereka. Dia lebih hebat kekuatan-Nya dari mereka? Dan mereka telah mengingkari tanda-tanda (kebesaran) Kami"},{id:16,text:"\u0641\u064e\u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0631\u0650\u064a\u062d\u0657\u0627 \u0635\u064e\u0631\u06e1\u0635\u064e\u0631\u0657\u0627 \u0641\u0650\u064a\u0653 \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u0656 \u0646\u0651\u064e\u062d\u0650\u0633\u064e\u0627\u062a\u0656 \u0644\u0651\u0650\u0646\u064f\u0630\u0650\u064a\u0642\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0671\u0644\u06e1\u062e\u0650\u0632\u06e1\u064a\u0650 \u0641\u0650\u064a \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u0650 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627\u06d6 \u0648\u064e\u0644\u064e\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0623\u064e\u062e\u06e1\u0632\u064e\u0649\u0670\u06d6 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064f\u0646\u0635\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Maka Kami tiupkan angin yang sangat bergemuruh kepada mereka dalam beberapa hari yang nahas, karena Kami ingin agar mereka itu merasakan siksaan yang menghinakan dalam kehidupan di dunia. Sedangkan azab akhirat pasti lebih menghinakan dan mereka tidak diberi pertolongan"},{id:17,text:"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u062b\u064e\u0645\u064f\u0648\u062f\u064f \u0641\u064e\u0647\u064e\u062f\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u062d\u064e\u0628\u0651\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0639\u064e\u0645\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0647\u064f\u062f\u064e\u0649\u0670 \u0641\u064e\u0623\u064e\u062e\u064e\u0630\u064e\u062a\u06e1\u0647\u064f\u0645\u06e1 \u0635\u064e\u0670\u0639\u0650\u0642\u064e\u0629\u064f \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0671\u0644\u06e1\u0647\u064f\u0648\u0646\u0650 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0643\u06e1\u0633\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Dan adapun kaum Samud, mereka telah Kami beri petunjuk tetapi mereka lebih menyukai kebutaan (kesesatan) daripada petunjuk itu, maka mereka disambar petir sebagai azab yang menghinakan disebabkan apa yang telah mereka kerjakan"},{id:18,text:"\u0648\u064e\u0646\u064e\u062c\u0651\u064e\u064a\u06e1\u0646\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",translation:"Dan Kami selamatkan orang-orang yang beriman karena mereka adalah orang-orang yang bertakwa"},{id:19,text:"\u0648\u064e\u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064f\u062d\u06e1\u0634\u064e\u0631\u064f \u0623\u064e\u0639\u06e1\u062f\u064e\u0627\u0653\u0621\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0641\u064e\u0647\u064f\u0645\u06e1 \u064a\u064f\u0648\u0632\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Dan (ingatlah) pada hari (ketika) musuh-musuh Allah digiring ke neraka lalu mereka dipisah-pisahkan"},{id:20,text:"\u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064f\u0648\u0647\u064e\u0627 \u0634\u064e\u0647\u0650\u062f\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0633\u064e\u0645\u06e1\u0639\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0628\u06e1\u0635\u064e\u0670\u0631\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u062c\u064f\u0644\u064f\u0648\u062f\u064f\u0647\u064f\u0645 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Sehingga apabila mereka sampai ke neraka, pendengaran, penglihatan dan kulit mereka menjadi saksi terhadap apa yang telah mereka lakukan"},{id:21,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u0650\u062c\u064f\u0644\u064f\u0648\u062f\u0650\u0647\u0650\u0645\u06e1 \u0644\u0650\u0645\u064e \u0634\u064e\u0647\u0650\u062f\u062a\u0651\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627\u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0637\u064e\u0642\u064e\u0646\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064e\u0646\u0637\u064e\u0642\u064e \u0643\u064f\u0644\u0651\u064e \u0634\u064e\u064a\u06e1\u0621\u0656\u06da \u0648\u064e\u0647\u064f\u0648\u064e \u062e\u064e\u0644\u064e\u0642\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u0648\u0651\u064e\u0644\u064e \u0645\u064e\u0631\u0651\u064e\u0629\u0656 \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u062a\u064f\u0631\u06e1\u062c\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Dan mereka berkata kepada kulit mereka, \"Mengapa kamu menjadi saksi terhadap kami?\" Kulit mereka menjawab, \"Yang menjadikan kami dapat berbicara adalah Allah, yang (juga) menjadikan segala sesuatu dapat berbicara, dan Dialah yang menciptakan kamu yang pertama kali dan hanya kepada-Nya kamu dikembalikan"},{id:22,text:"\u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0633\u06e1\u062a\u064e\u062a\u0650\u0631\u064f\u0648\u0646\u064e \u0623\u064e\u0646 \u064a\u064e\u0634\u06e1\u0647\u064e\u062f\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0633\u064e\u0645\u06e1\u0639\u064f\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064e\u0628\u06e1\u0635\u064e\u0670\u0631\u064f\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u062c\u064f\u0644\u064f\u0648\u062f\u064f\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u0638\u064e\u0646\u064e\u0646\u062a\u064f\u0645\u06e1 \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0643\u064e\u062b\u0650\u064a\u0631\u0657\u0627 \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"(Dan kamu tidak dapat bersembunyi dari kesaksian pendengaran, penglihatan dan kulitmu terhadapmu774) bahkan kamu mengira Allah tidak mengetahui banyak tentang apa yang kamu lakukan"},{id:23,text:"\u0648\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u06e1 \u0638\u064e\u0646\u0651\u064f\u0643\u064f\u0645\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0638\u064e\u0646\u064e\u0646\u062a\u064f\u0645 \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1 \u0623\u064e\u0631\u06e1\u062f\u064e\u0649\u0670\u0643\u064f\u0645\u06e1 \u0641\u064e\u0623\u064e\u0635\u06e1\u0628\u064e\u062d\u06e1\u062a\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u062e\u064e\u0670\u0633\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan itulah dugaanmu yang telah kamu sangkakan terhadap Tuhanmu, (dugaan itu) telah membinasakan kamu, sehingga jadilah kamu termasuk orang yang rugi"},{id:24,text:"\u0641\u064e\u0625\u0650\u0646 \u064a\u064e\u0635\u06e1\u0628\u0650\u0631\u064f\u0648\u0627\u0652 \u0641\u064e\u0671\u0644\u0646\u0651\u064e\u0627\u0631\u064f \u0645\u064e\u062b\u06e1\u0648\u0657\u0649 \u0644\u0651\u064e\u0647\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0625\u0650\u0646 \u064a\u064e\u0633\u06e1\u062a\u064e\u0639\u06e1\u062a\u0650\u0628\u064f\u0648\u0627\u0652 \u0641\u064e\u0645\u064e\u0627 \u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0639\u06e1\u062a\u064e\u0628\u0650\u064a\u0646\u064e",translation:"Meskipun mereka bersabar (atas azab neraka) maka nerakalah tempat tinggal mereka dan jika mereka minta belas kasihan, maka mereka itu tidak termasuk orang yang pantas dikasihani"},{id:25,text:"\u06de\u0648\u064e\u0642\u064e\u064a\u0651\u064e\u0636\u06e1\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0642\u064f\u0631\u064e\u0646\u064e\u0627\u0653\u0621\u064e \u0641\u064e\u0632\u064e\u064a\u0651\u064e\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u0647\u0650\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u06e1\u0641\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u062d\u064e\u0642\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u064f \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0644\u064f \u0641\u0650\u064a\u0653 \u0623\u064f\u0645\u064e\u0645\u0656 \u0642\u064e\u062f\u06e1 \u062e\u064e\u0644\u064e\u062a\u06e1 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u062c\u0650\u0646\u0651\u0650 \u0648\u064e\u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u0650\u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u062e\u064e\u0670\u0633\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan Kami tetapkan bagi mereka teman-teman (setan) yang memuji-muji apa saja yang ada di hadapan dan di belakang mereka775) dan tetaplah atas mereka putusan azab bersama umat-umat yang terdahulu sebelum mereka dari (golongan) jin dan manusia. Sungguh, mereka adalah orang-orang yang rugi"},{id:26,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u062a\u064e\u0633\u06e1\u0645\u064e\u0639\u064f\u0648\u0627\u0652 \u0644\u0650\u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u0650 \u0648\u064e\u0671\u0644\u06e1\u063a\u064e\u0648\u06e1\u0627\u0652 \u0641\u0650\u064a\u0647\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u063a\u06e1\u0644\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Dan orang-orang yang kafir berkata, \"Janganlah kamu mendengarkan (bacaan) Alquran ini dan buatlah kegaduhan terhadapnya, agar kamu dapat mengalahkan (mereka)"},{id:27,text:"\u0641\u064e\u0644\u064e\u0646\u064f\u0630\u0650\u064a\u0642\u064e\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u0657\u0627 \u0634\u064e\u062f\u0650\u064a\u062f\u0657\u0627 \u0648\u064e\u0644\u064e\u0646\u064e\u062c\u06e1\u0632\u0650\u064a\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u0633\u06e1\u0648\u064e\u0623\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Maka sungguh, akan Kami timpakan azab yang keras kepada orang-orang yang kafir itu dan sungguh, akan Kami beri balasan mereka dengan seburuk-buruk balasan terhadap apa yang telah mereka kerjakan"},{id:28,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062c\u064e\u0632\u064e\u0627\u0653\u0621\u064f \u0623\u064e\u0639\u06e1\u062f\u064e\u0627\u0653\u0621\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u064f\u06d6 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u062f\u064e\u0627\u0631\u064f \u0671\u0644\u06e1\u062e\u064f\u0644\u06e1\u062f\u0650 \u062c\u064e\u0632\u064e\u0627\u0653\u0621\u064e\u06e2 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u064a\u064e\u062c\u06e1\u062d\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Demikianlah balasan (terhadap) musuh-musuh Allah (yaitu) neraka; mereka mendapat tempat tinggal yang kekal di dalamnya sebagai balasan atas keingkaran mereka terhadap ayat-ayat Kami"},{id:29,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627\u0653 \u0623\u064e\u0631\u0650\u0646\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u064e\u064a\u06e1\u0646\u0650 \u0623\u064e\u0636\u064e\u0644\u0651\u064e\u0627\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u062c\u0650\u0646\u0651\u0650 \u0648\u064e\u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u0650 \u0646\u064e\u062c\u06e1\u0639\u064e\u0644\u06e1\u0647\u064f\u0645\u064e\u0627 \u062a\u064e\u062d\u06e1\u062a\u064e \u0623\u064e\u0642\u06e1\u062f\u064e\u0627\u0645\u0650\u0646\u064e\u0627 \u0644\u0650\u064a\u064e\u0643\u064f\u0648\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u0633\u06e1\u0641\u064e\u0644\u0650\u064a\u0646\u064e",translation:"Dan orang-orang yang kafir berkata, \"Ya Tuhan kami, perlihatkanlah kepada kami dua golongan yang telah menyesatkan kami yaitu (golongan) jin dan manusia, agar kami letakkan keduanya di bawah telapak kaki agar kedua golongan itu menjadi yang paling bawah (hina)"},{id:30,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0631\u064e\u0628\u0651\u064f\u0646\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u062b\u064f\u0645\u0651\u064e \u0671\u0633\u06e1\u062a\u064e\u0642\u064e\u0670\u0645\u064f\u0648\u0627\u0652 \u062a\u064e\u062a\u064e\u0646\u064e\u0632\u0651\u064e\u0644\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u064f \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u064f \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064e\u062e\u064e\u0627\u0641\u064f\u0648\u0627\u0652 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062d\u06e1\u0632\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0623\u064e\u0628\u06e1\u0634\u0650\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u0671\u0644\u0651\u064e\u062a\u0650\u064a \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064f\u0648\u0639\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Sesungguhnya orang-orang yang berkata, \"Tuhan kami adalah Allah\" kemudian mereka meneguhkan pendirian mereka, maka malaikat-malaikat akan turun kepada mereka (dengan berkata), \"Janganlah kamu merasa takut dan janganlah kamu bersedih hati; dan bergembiralah kamu dengan (memperoleh) surga yang telah dijanjikan kepadamu"},{id:31,text:"\u0646\u064e\u062d\u06e1\u0646\u064f \u0623\u064e\u0648\u06e1\u0644\u0650\u064a\u064e\u0627\u0653\u0624\u064f\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u0650 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0648\u064e\u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650\u06d6 \u0648\u064e\u0644\u064e\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u064e\u0627 \u062a\u064e\u0634\u06e1\u062a\u064e\u0647\u0650\u064a\u0653 \u0623\u064e\u0646\u0641\u064f\u0633\u064f\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u064e\u0627 \u062a\u064e\u062f\u0651\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Kamilah pelindung-pelindungmu dalam kehidupan dunia dan akhirat; di dalamnya (surga) kamu memperoleh apa yang kamu inginkan dan memperoleh apa yang kamu minta"},{id:32,text:"\u0646\u064f\u0632\u064f\u0644\u0657\u0627 \u0645\u0651\u0650\u0646\u06e1 \u063a\u064e\u0641\u064f\u0648\u0631\u0656 \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0656",translation:"Sebagai penghormatan (bagimu) dari (Allah) Yang Maha Pengampun, Maha Penyayang"},{id:33,text:"\u0648\u064e\u0645\u064e\u0646\u06e1 \u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064f \u0642\u064e\u0648\u06e1\u0644\u0657\u0627 \u0645\u0651\u0650\u0645\u0651\u064e\u0646 \u062f\u064e\u0639\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064e \u0635\u064e\u0670\u0644\u0650\u062d\u0657\u0627 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e\u0646\u0650\u064a \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0633\u06e1\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dan siapakah yang lebih baik perkataannya daripada orang yang menyeru kepada Allah dan mengerjakan kebajikan dan berkata, \"Sungguh, aku termasuk orang-orang muslim (yang berserah diri)"},{id:34,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0633\u06e1\u062a\u064e\u0648\u0650\u064a \u0671\u0644\u06e1\u062d\u064e\u0633\u064e\u0646\u064e\u0629\u064f \u0648\u064e\u0644\u064e\u0627 \u0671\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u064f\u06da \u0671\u062f\u06e1\u0641\u064e\u0639\u06e1 \u0628\u0650\u0671\u0644\u0651\u064e\u062a\u0650\u064a \u0647\u0650\u064a\u064e \u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064f \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0628\u064e\u064a\u06e1\u0646\u064e\u0643\u064e \u0648\u064e\u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u06e5 \u0639\u064e\u062f\u064e\u0670\u0648\u064e\u0629\u065e \u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u06e5 \u0648\u064e\u0644\u0650\u064a\u0651\u064c \u062d\u064e\u0645\u0650\u064a\u0645\u065e",translation:"Dan tidaklah sama kebaikan dan kejahatan. Tolaklah (kejahatan itu) dengan cara yang lebih baik, sehingga orang yang ada rasa permusuhan antara kamu dan dia akan seperti teman yang setia"},{id:35,text:"\u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0644\u064e\u0642\u0651\u064e\u0649\u0670\u0647\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0635\u064e\u0628\u064e\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0644\u064e\u0642\u0651\u064e\u0649\u0670\u0647\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0630\u064f\u0648 \u062d\u064e\u0638\u0651\u064d \u0639\u064e\u0638\u0650\u064a\u0645\u0656",translation:"Dan (sifat-sifat yang baik itu) tidak akan dianugerahkan kecuali kepada orang-orang yang sabar dan tidak dianugerahkan kecuali kepada orang-orang yang mempunyai keberuntungan yang besar"},{id:36,text:"\u0648\u064e\u0625\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u0646\u0632\u064e\u063a\u064e\u0646\u0651\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u0650 \u0646\u064e\u0632\u06e1\u063a\u065e \u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u0639\u0650\u0630\u06e1 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0647\u064f\u0648\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u0650\u064a\u0639\u064f \u0671\u0644\u06e1\u0639\u064e\u0644\u0650\u064a\u0645\u064f",translation:"Dan jika setan mengganggumu dengan suatu godaan, maka mohonlah perlindungan kepada Allah. Sungguh, Dialah Yang Maha Mendengar, Maha Mengetahui"},{id:37,text:"\u0648\u064e\u0645\u0650\u0646\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0647\u0650 \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u064f \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064f \u0648\u064e\u0671\u0644\u0634\u0651\u064e\u0645\u06e1\u0633\u064f \u0648\u064e\u0671\u0644\u06e1\u0642\u064e\u0645\u064e\u0631\u064f\u06da \u0644\u064e\u0627 \u062a\u064e\u0633\u06e1\u062c\u064f\u062f\u064f\u0648\u0627\u0652 \u0644\u0650\u0644\u0634\u0651\u064e\u0645\u06e1\u0633\u0650 \u0648\u064e\u0644\u064e\u0627 \u0644\u0650\u0644\u06e1\u0642\u064e\u0645\u064e\u0631\u0650 \u0648\u064e\u0671\u0633\u06e1\u062c\u064f\u062f\u064f\u0648\u0627\u0652\u06e4 \u0644\u0650\u0644\u0651\u064e\u0647\u0650\u06e4 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e\u0647\u064f\u0646\u0651\u064e \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0625\u0650\u064a\u0651\u064e\u0627\u0647\u064f \u062a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0646\u064e",translation:"Dan sebagian dari tanda-tanda kebesaran-Nya ialah malam, siang, matahari dan bulan. Janganlah bersujud kepada matahari dan jangan (pula) kepada bulan, tetapi bersujudlah kepada Allah yang menciptakannya, jika kamu hanya menyembah kepada-Nya"},{id:38,text:"\u0641\u064e\u0625\u0650\u0646\u0650 \u0671\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u064e\u0631\u064f\u0648\u0627\u0652 \u0641\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0639\u0650\u0646\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u064a\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u064f\u0648\u0646\u064e \u0644\u064e\u0647\u064f\u06e5 \u0628\u0650\u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u0650 \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u0640\u0654\u064e\u0645\u064f\u0648\u0646\u064e\u06e9",translation:"Jika mereka menyombongkan diri, maka mereka (malaikat) yang di sisi Tuhanmu bertasbih kepada-Nya pada malam dan siang hari, sedang mereka tidak pernah jemu"},{id:39,text:"\u0648\u064e\u0645\u0650\u0646\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0646\u0651\u064e\u0643\u064e \u062a\u064e\u0631\u064e\u0649 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u062e\u064e\u0670\u0634\u0650\u0639\u064e\u0629\u0657 \u0641\u064e\u0625\u0650\u0630\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627 \u0671\u0644\u06e1\u0645\u064e\u0627\u0653\u0621\u064e \u0671\u0647\u06e1\u062a\u064e\u0632\u0651\u064e\u062a\u06e1 \u0648\u064e\u0631\u064e\u0628\u064e\u062a\u06e1\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064e\u062d\u06e1\u064a\u064e\u0627\u0647\u064e\u0627 \u0644\u064e\u0645\u064f\u062d\u06e1\u064a\u0650 \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u064e\u0649\u0670\u0653\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0642\u064e\u062f\u0650\u064a\u0631\u064c",translation:"Dan sebagian dari tanda-tanda (kebesaran)-Nya, engkau melihat bumi itu kering dan tandus, tetapi apabila Kami turunkan hujan di atasnya, niscaya ia bergerak dan subur. Sesungguhnya (Allah) yang menghidupkannya pasti dapat menghidupkan yang mati; sesungguhnya Dia Mahakuasa atas segala sesuatu"},{id:40,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0644\u06e1\u062d\u0650\u062f\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0653 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u062e\u06e1\u0641\u064e\u0648\u06e1\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627\u0653\u06d7 \u0623\u064e\u0641\u064e\u0645\u064e\u0646 \u064a\u064f\u0644\u06e1\u0642\u064e\u0649\u0670 \u0641\u0650\u064a \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u062e\u064e\u064a\u06e1\u0631\u064c \u0623\u064e\u0645 \u0645\u0651\u064e\u0646 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u0653 \u0621\u064e\u0627\u0645\u0650\u0646\u0657\u0627 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650\u06da \u0671\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u0634\u0650\u0626\u06e1\u062a\u064f\u0645\u06e1 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0628\u064e\u0635\u0650\u064a\u0631\u064c",translation:"Sesungguhnya orang-orang yang mengingkari tanda-tanda (kebesaran) Kami, mereka tidak tersembunyi dari Kami. Apakah orang-orang yang dilemparkan ke dalam neraka yang lebih baik ataukah mereka yang datang dengan aman sentosa pada hari Kiamat? Lakukanlah apa yang kamu kehendaki! Sungguh, Dia Maha Melihat apa yang kamu kerjakan"},{id:41,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u0630\u0651\u0650\u0643\u06e1\u0631\u0650 \u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0643\u0650\u062a\u064e\u0670\u0628\u064c \u0639\u064e\u0632\u0650\u064a\u0632\u065e",translation:"Sesungguhnya orang-orang yang mengingkari Alquran ketika (Alquran) itu disampaikan kepada mereka (mereka itu pasti akan celaka), dan sesungguhnya (Alquran) itu adalah Kitab yang mulia"},{id:42,text:"\u0644\u0651\u064e\u0627 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u0647\u0650 \u0671\u0644\u06e1\u0628\u064e\u0670\u0637\u0650\u0644\u064f \u0645\u0650\u0646\u06e2 \u0628\u064e\u064a\u06e1\u0646\u0650 \u064a\u064e\u062f\u064e\u064a\u06e1\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u0645\u0650\u0646\u06e1 \u062e\u064e\u0644\u06e1\u0641\u0650\u0647\u0650\u06e6\u06d6 \u062a\u064e\u0646\u0632\u0650\u064a\u0644\u065e \u0645\u0651\u0650\u0646\u06e1 \u062d\u064e\u0643\u0650\u064a\u0645\u064d \u062d\u064e\u0645\u0650\u064a\u062f\u0656",translation:"(yang) tidak akan didatangi oleh kebatilan baik dari depan maupun dari belakang (pada masa lalu dan yang akan datang), yang diturunkan dari Tuhan Yang Mahabijaksana, Maha Terpuji"},{id:43,text:"\u0645\u0651\u064e\u0627 \u064a\u064f\u0642\u064e\u0627\u0644\u064f \u0644\u064e\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0642\u064e\u062f\u06e1 \u0642\u0650\u064a\u0644\u064e \u0644\u0650\u0644\u0631\u0651\u064f\u0633\u064f\u0644\u0650 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064e\u06da \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0644\u064e\u0630\u064f\u0648 \u0645\u064e\u063a\u06e1\u0641\u0650\u0631\u064e\u0629\u0656 \u0648\u064e\u0630\u064f\u0648 \u0639\u0650\u0642\u064e\u0627\u0628\u064d \u0623\u064e\u0644\u0650\u064a\u0645\u0656",translation:"Apa yang dikatakan (oleh orang-orang kafir) kepadamu tidak lain adalah apa yang telah dikatakan kepada rasul-rasul sebelummu. Sungguh, Tuhanmu mempunyai ampunan dan azab yang pedih"},{id:44,text:"\u0648\u064e\u0644\u064e\u0648\u06e1 \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f \u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u064b\u0627 \u0623\u064e\u0639\u06e1\u062c\u064e\u0645\u0650\u064a\u0651\u0657\u0627 \u0644\u0651\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0648\u06e1\u0644\u064e\u0627 \u0641\u064f\u0635\u0651\u0650\u0644\u064e\u062a\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u064f\u0647\u064f\u06e5\u0653\u06d6 \u0621\u064e\u0627\u06ec\u0639\u06e1\u062c\u064e\u0645\u0650\u064a\u0651\u065e \u0648\u064e\u0639\u064e\u0631\u064e\u0628\u0650\u064a\u0651\u065e\u06d7 \u0642\u064f\u0644\u06e1 \u0647\u064f\u0648\u064e \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0647\u064f\u062f\u0657\u0649 \u0648\u064e\u0634\u0650\u0641\u064e\u0627\u0653\u0621\u065e\u06da \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0653 \u0621\u064e\u0627\u0630\u064e\u0627\u0646\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0642\u06e1\u0631\u065e \u0648\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0639\u064e\u0645\u064b\u0649\u06da \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u064a\u064f\u0646\u064e\u0627\u062f\u064e\u0648\u06e1\u0646\u064e \u0645\u0650\u0646 \u0645\u0651\u064e\u0643\u064e\u0627\u0646\u0650\u06ed \u0628\u064e\u0639\u0650\u064a\u062f\u0656",translation:"Dan sekiranya Alquran Kami jadikan sebagai bacaan dalam bahasa selain bahasa Arab niscaya mereka mengatakan, \"Mengapa tidak dijelaskan ayat-ayatnya?\" Apakah patut (Alquran) dalam bahasa selain bahasa Arab sedang (rasul), orang Arab? Katakanlah, \"Alquran adalah petunjuk dan penyembuh bagi orang-orang yang beriman. Dan orang-orang yang tidak beriman pada telinga mereka ada sumbatan, dan (Alquran) itu merupakan kegelapan bagi mereka.776) Mereka itu (seperti) orang-orang yang dipanggil dari tempat yang jauh"},{id:45,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0641\u064e\u0671\u062e\u06e1\u062a\u064f\u0644\u0650\u0641\u064e \u0641\u0650\u064a\u0647\u0650\u06da \u0648\u064e\u0644\u064e\u0648\u06e1\u0644\u064e\u0627 \u0643\u064e\u0644\u0650\u0645\u064e\u0629\u065e \u0633\u064e\u0628\u064e\u0642\u064e\u062a\u06e1 \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064e \u0644\u064e\u0642\u064f\u0636\u0650\u064a\u064e \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1\u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0641\u0650\u064a \u0634\u064e\u0643\u0651\u0656 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f \u0645\u064f\u0631\u0650\u064a\u0628\u0656",translation:"Dan sungguh, telah Kami berikan kepada Musa Kitab (Taurat) lalu diperselisihkan. Sekiranya tidak ada keputusan yang terdahulu dari Tuhanmu, orang-orang kafir itu pasti sudah dibinasakan. Dan sesungguhnya mereka benar-benar dalam keraguan yang mendalam terhadapnya"},{id:46,text:"\u0645\u0651\u064e\u0646\u06e1 \u0639\u064e\u0645\u0650\u0644\u064e \u0635\u064e\u0670\u0644\u0650\u062d\u0657\u0627 \u0641\u064e\u0644\u0650\u0646\u064e\u0641\u06e1\u0633\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u0645\u064e\u0646\u06e1 \u0623\u064e\u0633\u064e\u0627\u0653\u0621\u064e \u0641\u064e\u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627\u06d7 \u0648\u064e\u0645\u064e\u0627 \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0628\u0650\u0638\u064e\u0644\u0651\u064e\u0640\u0670\u0645\u0656 \u0644\u0651\u0650\u0644\u06e1\u0639\u064e\u0628\u0650\u064a\u062f\u0650",translation:"Barangsiapa mengerjakan kebajikan maka (pahalanya) untuk dirinya sendiri dan barangsiapa berbuat jahat maka (dosanya) menjadi tanggungan dirinya sendiri. Dan Tuhanmu sama sekali tidak menzalimi hamba-hamba(Nya)"},{id:47,text:"\u06de\u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u064a\u064f\u0631\u064e\u062f\u0651\u064f \u0639\u0650\u0644\u06e1\u0645\u064f \u0671\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u0650\u06da \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u062e\u06e1\u0631\u064f\u062c\u064f \u0645\u0650\u0646 \u062b\u064e\u0645\u064e\u0631\u064e\u0670\u062a\u0656 \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u0643\u06e1\u0645\u064e\u0627\u0645\u0650\u0647\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u062d\u06e1\u0645\u0650\u0644\u064f \u0645\u0650\u0646\u06e1 \u0623\u064f\u0646\u062b\u064e\u0649\u0670 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0636\u064e\u0639\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0639\u0650\u0644\u06e1\u0645\u0650\u0647\u0650\u06e6\u06da \u0648\u064e\u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064f\u0646\u064e\u0627\u062f\u0650\u064a\u0647\u0650\u0645\u06e1 \u0623\u064e\u064a\u06e1\u0646\u064e \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0653\u0621\u0650\u064a \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0621\u064e\u0627\u0630\u064e\u0646\u0651\u064e\u0640\u0670\u0643\u064e \u0645\u064e\u0627\u0645\u0650\u0646\u0651\u064e\u0627 \u0645\u0650\u0646 \u0634\u064e\u0647\u0650\u064a\u062f\u0656",translation:"(Kepada-Nyalah ilmu tentang hari Kiamat itu dikembalikan.777) Tidak ada buah-buahan yang keluar dari kelopaknya dan tidak seorang perempuan pun yang mengandung dan yang melahirkan, melainkan semuanya dengan sepengetahuan-Nya. Pada hari ketika Dia (Allah) menyeru mereka, \"Di manakah sekutu-sekutu-Ku itu?\"778) Mereka menjawab, \"Kami nyatakan kepada Engkau bahwa tidak ada seorang pun di antara kami yang dapat memberi kesaksian (bahwa Engkau mempunyai sekutu)"},{id:48,text:"\u0648\u064e\u0636\u064e\u0644\u0651\u064e \u0639\u064e\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f\u06d6 \u0648\u064e\u0638\u064e\u0646\u0651\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0645\u0651\u064e\u062d\u0650\u064a\u0635\u0656",translation:"Dan lenyaplah dari mereka apa yang dahulu selalu mereka sembah, dan mereka pun tahu bahwa tidak ada jalan keluar (dari azab Allah) bagi mereka"},{id:49,text:"\u0644\u0651\u064e\u0627 \u064a\u064e\u0633\u06e1\u0640\u0654\u064e\u0645\u064f \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064f \u0645\u0650\u0646 \u062f\u064f\u0639\u064e\u0627\u0653\u0621\u0650 \u0671\u0644\u06e1\u062e\u064e\u064a\u06e1\u0631\u0650 \u0648\u064e\u0625\u0650\u0646 \u0645\u0651\u064e\u0633\u0651\u064e\u0647\u064f \u0671\u0644\u0634\u0651\u064e\u0631\u0651\u064f \u0641\u064e\u064a\u064e\u0640\u0654\u064f\u0648\u0633\u065e \u0642\u064e\u0646\u064f\u0648\u0637\u065e",translation:"Manusia tidak jemu memohon kebaikan, dan jika ditimpa malapetaka, mereka berputus asa dan hilang harapannya"},{id:50,text:"\u0648\u064e\u0644\u064e\u0626\u0650\u0646\u06e1 \u0623\u064e\u0630\u064e\u0642\u06e1\u0646\u064e\u0670\u0647\u064f \u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u0657 \u0645\u0651\u0650\u0646\u0651\u064e\u0627 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0636\u064e\u0631\u0651\u064e\u0627\u0653\u0621\u064e \u0645\u064e\u0633\u0651\u064e\u062a\u06e1\u0647\u064f \u0644\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064e\u0646\u0651\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0644\u0650\u064a \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0638\u064f\u0646\u0651\u064f \u0671\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064e \u0642\u064e\u0627\u0653\u0626\u0650\u0645\u064e\u0629\u0657 \u0648\u064e\u0644\u064e\u0626\u0650\u0646 \u0631\u0651\u064f\u062c\u0650\u0639\u06e1\u062a\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u064a\u0653 \u0625\u0650\u0646\u0651\u064e \u0644\u0650\u064a \u0639\u0650\u0646\u062f\u064e\u0647\u064f\u06e5 \u0644\u064e\u0644\u06e1\u062d\u064f\u0633\u06e1\u0646\u064e\u0649\u0670\u06da \u0641\u064e\u0644\u064e\u0646\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064e\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0645\u064e\u0627 \u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0648\u064e\u0644\u064e\u0646\u064f\u0630\u0650\u064a\u0642\u064e\u0646\u0651\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064d \u063a\u064e\u0644\u0650\u064a\u0638\u0656",translation:"Dan jika Kami berikan kepadanya suatu rahmat dari Kami setelah ditimpa kesusahan, pastilah dia berkata, \"Ini adalah hakku, dan aku tidak yakin bahwa hari Kiamat itu akan terjadi. Dan jika aku dikembalikan kepada Tuhanku, sesungguhnya aku akan memperoleh kebaikan di sisi-Nya.\" Maka sungguh, akan Kami beritahukan kepada orang-orang kafir tentang apa yang telah mereka kerjakan, dan sungguh, akan Kami timpakan kepada mereka azab yang berat"},{id:51,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627\u0653 \u0623\u064e\u0646\u06e1\u0639\u064e\u0645\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u0650 \u0623\u064e\u0639\u06e1\u0631\u064e\u0636\u064e \u0648\u064e\u0646\u064e\u0640\u0654\u064e\u0627 \u0628\u0650\u062c\u064e\u0627\u0646\u0650\u0628\u0650\u0647\u0650\u06e6 \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0633\u0651\u064e\u0647\u064f \u0671\u0644\u0634\u0651\u064e\u0631\u0651\u064f \u0641\u064e\u0630\u064f\u0648 \u062f\u064f\u0639\u064e\u0627\u0653\u0621\u064d \u0639\u064e\u0631\u0650\u064a\u0636\u0656",translation:"Dan apabila Kami berikan nikmat kepada manusia, dia berpaling dan menjauhkan diri (dengan sombong); tetapi apabila ditimpa malapetaka maka dia banyak berdoa"},{id:52,text:"\u0642\u064f\u0644\u06e1 \u0623\u064e\u0631\u064e\u0621\u064e\u064a\u06e1\u062a\u064f\u0645\u06e1 \u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u06e1 \u0639\u0650\u0646\u062f\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062b\u064f\u0645\u0651\u064e \u0643\u064e\u0641\u064e\u0631\u06e1\u062a\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6 \u0645\u064e\u0646\u06e1 \u0623\u064e\u0636\u064e\u0644\u0651\u064f \u0645\u0650\u0645\u0651\u064e\u0646\u06e1 \u0647\u064f\u0648\u064e \u0641\u0650\u064a \u0634\u0650\u0642\u064e\u0627\u0642\u0650\u06ed \u0628\u064e\u0639\u0650\u064a\u062f\u0656",translation:"Katakanlah, \"Bagaimana pendapatmu jika (Alquran) itu datang dari sisi Allah, kemudian kamu mengingkarinya. Siapakah yang lebih sesat daripada orang yang selalu berada dalam penyimpangan yang jauh (dari kebenaran)"},{id:53,text:"\u0633\u064e\u0646\u064f\u0631\u0650\u064a\u0647\u0650\u0645\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u0653\u0641\u064e\u0627\u0642\u0650 \u0648\u064e\u0641\u0650\u064a\u0653 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u06e1 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u062a\u064e\u0628\u064e\u064a\u0651\u064e\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f\u06d7 \u0623\u064e\u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0643\u06e1\u0641\u0650 \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u06e5 \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0634\u064e\u0647\u0650\u064a\u062f\u064c",translation:"Kami akan memperlihatkan kepada mereka tanda-tanda (kebesaran) Kami di segenap penjuru dan pada diri mereka sendiri, sehingga jelaslah bagi mereka bahwa Alquran itu adalah benar. Tidak cukupkah (bagi kamu) bahwa Tuhanmu menjadi saksi atas segala sesuatu"},{id:54,text:"\u0623\u064e\u0644\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0645\u0650\u0631\u06e1\u064a\u064e\u0629\u0656 \u0645\u0651\u0650\u0646 \u0644\u0651\u0650\u0642\u064e\u0627\u0653\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1\u06d7 \u0623\u064e\u0644\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0645\u0651\u064f\u062d\u0650\u064a\u0637\u064f\u06e2",translation:"Ingatlah, sesungguhnya mereka dalam keraguan tentang pertemuan dengan Tuhan mereka. Ingatlah, sesungguhnya Dia Maha Meliputi segala sesuatu"}]},{id:42,name:"\u0627\u0644\u0634\u0648\u0631\u0649",transliteration:"Ash-Shuraa",translation:"Musyawarah",type:"meccan",total_verses:53,verses:[{id:1,text:"\u062d\u0645\u0653",translation:"\u1e24\u0101 M\u012bm"},{id:2,text:"\u0639\u0653\u0633\u0653\u0642\u0653",translation:"A\u012bn S\u012bn Q\u0101f"},{id:3,text:"\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064f\u0648\u062d\u0650\u064a\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0648\u064e\u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0671\u0644\u06e1\u062d\u064e\u0643\u0650\u064a\u0645\u064f",translation:"Demikianlah Allah Yang Mahaperkasa, Mahabijaksana mewahyukan kepadamu (Muhammad) dan kepada orang-orang yang sebelummu"},{id:4,text:"\u0644\u064e\u0647\u064f\u06e5 \u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0639\u064e\u0644\u0650\u064a\u0651\u064f \u0671\u0644\u06e1\u0639\u064e\u0638\u0650\u064a\u0645\u064f",translation:"Milik-Nyalah apa yang ada di langit dan apa yang ada di bumi. Dan Dialah Yang Mahaagung, Mahabesar"},{id:5,text:"\u062a\u064e\u0643\u064e\u0627\u062f\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u064f \u064a\u064e\u062a\u064e\u0641\u064e\u0637\u0651\u064e\u0631\u06e1\u0646\u064e \u0645\u0650\u0646 \u0641\u064e\u0648\u06e1\u0642\u0650\u0647\u0650\u0646\u0651\u064e\u06da \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u064f \u064a\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u064f\u0648\u0646\u064e \u0628\u0650\u062d\u064e\u0645\u06e1\u062f\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u064a\u064e\u0633\u06e1\u062a\u064e\u063a\u06e1\u0641\u0650\u0631\u064f\u0648\u0646\u064e \u0644\u0650\u0645\u064e\u0646 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d7 \u0623\u064e\u0644\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u063a\u064e\u0641\u064f\u0648\u0631\u064f \u0671\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",translation:"Hampir saja langit itu pecah dari sebelah atasnya (karena kebesaran Allah) dan malaikat-malaikat bertasbih memuji Tuhannya dan memohonkan ampunan untuk orang yang ada di bumi. Ingatlah, sesungguhnya Allah Dialah Yang Maha Pengampun, Maha Penyayang"},{id:6,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0648\u06e1\u0644\u0650\u064a\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u062d\u064e\u0641\u0650\u064a\u0638\u064c \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0628\u0650\u0648\u064e\u0643\u0650\u064a\u0644\u0656",translation:"Dan orang-orang yang mengambil pelindung-pelindung selain-Nya, Allah mengawasi (perbuatan) mereka; adapun engkau (Muhammad) bukanlah orang yang diserahi mengawasi mereka"},{id:7,text:"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0623\u064e\u0648\u06e1\u062d\u064e\u064a\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u064b\u0627 \u0639\u064e\u0631\u064e\u0628\u0650\u064a\u0651\u0657\u0627 \u0644\u0651\u0650\u062a\u064f\u0646\u0630\u0650\u0631\u064e \u0623\u064f\u0645\u0651\u064e \u0671\u0644\u06e1\u0642\u064f\u0631\u064e\u0649\u0670 \u0648\u064e\u0645\u064e\u0646\u06e1 \u062d\u064e\u0648\u06e1\u0644\u064e\u0647\u064e\u0627 \u0648\u064e\u062a\u064f\u0646\u0630\u0650\u0631\u064e \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u062c\u064e\u0645\u06e1\u0639\u0650 \u0644\u064e\u0627 \u0631\u064e\u064a\u06e1\u0628\u064e \u0641\u0650\u064a\u0647\u0650\u06da \u0641\u064e\u0631\u0650\u064a\u0642\u065e \u0641\u0650\u064a \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u0648\u064e\u0641\u064e\u0631\u0650\u064a\u0642\u065e \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0639\u0650\u064a\u0631\u0650",translation:"Dan demikianlah Kami wahyukan Alquran kepadamu dalam bahasa Arab, agar engkau memberi peringatan kepada penduduk ibukota (Mekkah) dan penduduk (negeri-negeri) di sekelilingnya serta memberi peringatan tentang hari berkumpul (Kiamat) yang tidak diragukan adanya. Segolongan masuk surga dan segolongan masuk neraka"},{id:8,text:"\u0648\u064e\u0644\u064e\u0648\u06e1 \u0634\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u062c\u064e\u0639\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0623\u064f\u0645\u0651\u064e\u0629\u0657 \u0648\u064e\u0670\u062d\u0650\u062f\u064e\u0629\u0657 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u064a\u064f\u062f\u06e1\u062e\u0650\u0644\u064f \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0641\u0650\u064a \u0631\u064e\u062d\u06e1\u0645\u064e\u062a\u0650\u0647\u0650\u06e6\u06da \u0648\u064e\u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0648\u064e\u0644\u0650\u064a\u0651\u0656 \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0635\u0650\u064a\u0631\u064d",translation:"Dan sekiranya Allah menghendaki, niscaya Dia jadikan mereka satu umat, tetapi Dia memasukkan orang-orang yang Dia kehendaki ke dalam rahmat-Nya. Dan orang-orang yang zalim tidak ada bagi mereka pelindung dan penolong"},{id:9,text:"\u0623\u064e\u0645\u0650 \u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0648\u06e1\u0644\u0650\u064a\u064e\u0627\u0653\u0621\u064e\u06d6 \u0641\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0648\u064e\u0644\u0650\u064a\u0651\u064f \u0648\u064e\u0647\u064f\u0648\u064e \u064a\u064f\u062d\u06e1\u064a\u0650 \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u064e\u0649\u0670 \u0648\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0642\u064e\u062f\u0650\u064a\u0631\u065e",translation:"Atau mereka mengambil pelindung-pelindung selain Dia? Padahal Allah, Dialah pelindung (yang sebenarnya). Dan Dia menghidupkan orang yang mati, dan Dia Mahakuasa atas segala sesuatu"},{id:10,text:"\u0648\u064e\u0645\u064e\u0627 \u0671\u062e\u06e1\u062a\u064e\u0644\u064e\u0641\u06e1\u062a\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u0650 \u0645\u0650\u0646 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0641\u064e\u062d\u064f\u0643\u06e1\u0645\u064f\u0647\u064f\u06e5\u0653 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0631\u064e\u0628\u0651\u0650\u064a \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u06e1\u062a\u064f \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0623\u064f\u0646\u0650\u064a\u0628\u064f",translation:"Dan apa pun yang kamu perselisihkan padanya tentang sesuatu, keputusannya (terserah) kepada Allah. (Yang memiliki sifat-sifat demikian) itulah Allah Tuhanku. Kepada-Nya aku bertawakal dan kepada-Nya aku kembali"},{id:11,text:"\u0641\u064e\u0627\u0637\u0650\u0631\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06da \u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u06e1 \u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u0657\u0627 \u0648\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0639\u064e\u0670\u0645\u0650 \u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u0657\u0627 \u064a\u064e\u0630\u06e1\u0631\u064e\u0624\u064f\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u0650\u06da \u0644\u064e\u064a\u06e1\u0633\u064e \u0643\u064e\u0645\u0650\u062b\u06e1\u0644\u0650\u0647\u0650\u06e6 \u0634\u064e\u064a\u06e1\u0621\u065e\u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u0650\u064a\u0639\u064f \u0671\u0644\u06e1\u0628\u064e\u0635\u0650\u064a\u0631\u064f",translation:"(Allah) Pencipta langit dan bumi. Dia menjadikan bagi kamu pasangan-pasangan dari jenis kamu sendiri, dan dari jenis hewan ternak pasangan-pasangan (juga). Dijadikan-Nya kamu berkembang biak dengan jalan itu. Tidak ada sesuatu pun yang serupa dengan Dia. Dan Dia Yang Maha Mendengar, Maha Melihat"},{id:12,text:"\u0644\u064e\u0647\u064f\u06e5 \u0645\u064e\u0642\u064e\u0627\u0644\u0650\u064a\u062f\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d6 \u064a\u064e\u0628\u06e1\u0633\u064f\u0637\u064f \u0671\u0644\u0631\u0651\u0650\u0632\u06e1\u0642\u064e \u0644\u0650\u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0648\u064e\u064a\u064e\u0642\u06e1\u062f\u0650\u0631\u064f\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Milik-Nyalah perbendaharaan langit dan bumi; Dia melapangkan rezeki dan membatasinya bagi siapa yang Dia kehendaki. Sungguh, Dia Maha Mengetahui segala sesuatu"},{id:13,text:"\u06de\u0634\u064e\u0631\u064e\u0639\u064e \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u0650 \u0645\u064e\u0627 \u0648\u064e\u0635\u0651\u064e\u0649\u0670 \u0628\u0650\u0647\u0650\u06e6 \u0646\u064f\u0648\u062d\u0657\u0627 \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064e\u0648\u06e1\u062d\u064e\u064a\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0648\u064e\u0645\u064e\u0627 \u0648\u064e\u0635\u0651\u064e\u064a\u06e1\u0646\u064e\u0627 \u0628\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064e \u0648\u064e\u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u0639\u0650\u064a\u0633\u064e\u0649\u0670\u0653\u06d6 \u0623\u064e\u0646\u06e1 \u0623\u064e\u0642\u0650\u064a\u0645\u064f\u0648\u0627\u0652 \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u064e\u0641\u064e\u0631\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0647\u0650\u06da \u0643\u064e\u0628\u064f\u0631\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0645\u064f\u0634\u06e1\u0631\u0650\u0643\u0650\u064a\u0646\u064e \u0645\u064e\u0627 \u062a\u064e\u062f\u06e1\u0639\u064f\u0648\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u06da \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u062c\u06e1\u062a\u064e\u0628\u0650\u064a\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0648\u064e\u064a\u064e\u0647\u06e1\u062f\u0650\u064a\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0645\u064e\u0646 \u064a\u064f\u0646\u0650\u064a\u0628\u064f",translation:"Dia (Allah) telah mensyariatkan kepadamu agama yang telah diwasiatkan-Nya kepada Nuh dan apa yang telah Kami wahyukan kepadamu (Muhammad) dan apa yang telah Kami wasiatkan kepada Ibrahim, Musa dan Isa, yaitu tegakkanlah agama (keimanan dan ketakwaan) dan janganlah kamu berpecah belah di dalamnya. Sangat berat bagi orang-orang musyrik (untuk mengikuti) agama yang kamu serukan kepada mereka. Allah memilih orang yang Dia kehendaki kepada agama tauhid dan memberi petunjuk kepada (agama)-Nya bagi orang yang kembali (kepada-Nya)"},{id:14,text:"\u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0641\u064e\u0631\u0651\u064e\u0642\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0645\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0639\u0650\u0644\u06e1\u0645\u064f \u0628\u064e\u063a\u06e1\u064a\u064e\u06e2\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1\u06da \u0648\u064e\u0644\u064e\u0648\u06e1\u0644\u064e\u0627 \u0643\u064e\u0644\u0650\u0645\u064e\u0629\u065e \u0633\u064e\u0628\u064e\u0642\u064e\u062a\u06e1 \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064e \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u062c\u064e\u0644\u0656 \u0645\u0651\u064f\u0633\u064e\u0645\u0651\u0657\u0649 \u0644\u0651\u064e\u0642\u064f\u0636\u0650\u064a\u064e \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1\u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u0631\u0650\u062b\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u0647\u0650\u0645\u06e1 \u0644\u064e\u0641\u0650\u064a \u0634\u064e\u0643\u0651\u0656 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f \u0645\u064f\u0631\u0650\u064a\u0628\u0656",translation:"Dan mereka (Ahli Kitab) tidak berpecah belah kecuali setelah datang kepada mereka ilmu (kebenaran yang disampaikan oleh para nabi), karena kedengkian antara sesama mereka. Jika tidaklah karena suatu ketetapan yang telah ada dahulunya dari Tuhanmu (untuk menangguhkan azab) sampai batas waktu yang ditentukan, pastilah hukuman bagi mereka telah dilaksanakan. Dan sesungguhnya orang-orang yang mewarisi Kitab (Taurat dan Injil) setelah mereka (pada zaman Muhammad), benar-benar berada dalam keraguan yang mendalam tentang Kitab (Alquran) itu"},{id:15,text:"\u0641\u064e\u0644\u0650\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u0671\u062f\u06e1\u0639\u064f\u06d6 \u0648\u064e\u0671\u0633\u06e1\u062a\u064e\u0642\u0650\u0645\u06e1 \u0643\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0645\u0650\u0631\u06e1\u062a\u064e\u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u06e1 \u0623\u064e\u0647\u06e1\u0648\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0642\u064f\u0644\u06e1 \u0621\u064e\u0627\u0645\u064e\u0646\u062a\u064f \u0628\u0650\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646 \u0643\u0650\u062a\u064e\u0670\u0628\u0656\u06d6 \u0648\u064e\u0623\u064f\u0645\u0650\u0631\u06e1\u062a\u064f \u0644\u0650\u0623\u064e\u0639\u06e1\u062f\u0650\u0644\u064e \u0628\u064e\u064a\u06e1\u0646\u064e\u0643\u064f\u0645\u064f\u06d6 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0631\u064e\u0628\u0651\u064f\u0646\u064e\u0627 \u0648\u064e\u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u06e1\u06d6 \u0644\u064e\u0646\u064e\u0627\u0653 \u0623\u064e\u0639\u06e1\u0645\u064e\u0670\u0644\u064f\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u0639\u06e1\u0645\u064e\u0670\u0644\u064f\u0643\u064f\u0645\u06e1\u06d6 \u0644\u064e\u0627 \u062d\u064f\u062c\u0651\u064e\u0629\u064e \u0628\u064e\u064a\u06e1\u0646\u064e\u0646\u064e\u0627 \u0648\u064e\u0628\u064e\u064a\u06e1\u0646\u064e\u0643\u064f\u0645\u064f\u06d6 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u062c\u06e1\u0645\u064e\u0639\u064f \u0628\u064e\u064a\u06e1\u0646\u064e\u0646\u064e\u0627\u06d6 \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0671\u0644\u06e1\u0645\u064e\u0635\u0650\u064a\u0631\u064f",translation:"Karena itu, serulah (mereka beriman) dan tetaplah (beriman dan berdakwah) sebagaimana diperintahkan kepadamu (Muhammad) dan janganlah mengikuti keinginan mereka dan katakanlah, \"Aku beriman kepada Kitab yang diturunkan Allah dan aku diperintahkan agar berlaku adil di antara kamu. Allah Tuhan kami dan Tuhan kamu. Bagi kami perbuatan kami dan bagi kamu perbuatan kamu. Tidak (perlu) ada pertengkaran antara kami dan kamu, Allah mengumpulkan antara kita dan kepada-Nyalah (kita) kembali"},{id:16,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u062d\u064e\u0627\u0653\u062c\u0651\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0645\u064e\u0627 \u0671\u0633\u06e1\u062a\u064f\u062c\u0650\u064a\u0628\u064e \u0644\u064e\u0647\u064f\u06e5 \u062d\u064f\u062c\u0651\u064e\u062a\u064f\u0647\u064f\u0645\u06e1 \u062f\u064e\u0627\u062d\u0650\u0636\u064e\u0629\u064c \u0639\u0650\u0646\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u063a\u064e\u0636\u064e\u0628\u065e \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u065e \u0634\u064e\u062f\u0650\u064a\u062f\u064c",translation:"Dan orang-orang yang berbantah-bantah tentang (agama) Allah setelah (agama itu) diterima, perbantahan mereka itu sia-sia di sisi Tuhan mereka. Mereka mendapat kemurkaan (Allah) dan mereka mendapat azab yang sangat keras"},{id:17,text:"\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0671\u0644\u06e1\u0645\u0650\u064a\u0632\u064e\u0627\u0646\u064e\u06d7 \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u062f\u06e1\u0631\u0650\u064a\u0643\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e \u0671\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064e \u0642\u064e\u0631\u0650\u064a\u0628\u065e",translation:"Allah yang menurunkan kitab (Alquran) dengan (membawa) kebenaran dan neraca (keadilan). Dan tahukah kamu, boleh jadi hari Kiamat itu sudah dekat"},{id:18,text:"\u064a\u064e\u0633\u06e1\u062a\u064e\u0639\u06e1\u062c\u0650\u0644\u064f \u0628\u0650\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u064e\u0627\u06d6 \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0645\u064f\u0634\u06e1\u0641\u0650\u0642\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0648\u064e\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064e\u0627 \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f\u06d7 \u0623\u064e\u0644\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0645\u064e\u0627\u0631\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u0650 \u0644\u064e\u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0670\u0644\u0650\u06ed \u0628\u064e\u0639\u0650\u064a\u062f\u064d",translation:"Orang-orang yang tidak percaya adanya hari Kiamat meminta agar hari itu segera terjadi, dan orang-orang yang beriman merasa takut kepadanya dan mereka yakin bahwa Kiamat itu adalah benar (akan terjadi). Ketahuilah bahwa sesungguhnya orang-orang yang membantah tentang terjadinya Kiamat itu benar-benar telah tersesat jauh"},{id:19,text:"\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0637\u0650\u064a\u0641\u064f\u06e2 \u0628\u0650\u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650\u06e6 \u064a\u064e\u0631\u06e1\u0632\u064f\u0642\u064f \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0642\u064e\u0648\u0650\u064a\u0651\u064f \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f",translation:"Allah Mahalembut terhadap hamba-hamba-Nya; Dia memberi rezeki kepada siapa yang Dia kehendaki, dan Dia Mahakuat, Mahaperkasa"},{id:20,text:"\u0645\u064e\u0646 \u0643\u064e\u0627\u0646\u064e \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u062d\u064e\u0631\u06e1\u062b\u064e \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0646\u064e\u0632\u0650\u062f\u06e1 \u0644\u064e\u0647\u064f\u06e5 \u0641\u0650\u064a \u062d\u064e\u0631\u06e1\u062b\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u0645\u064e\u0646 \u0643\u064e\u0627\u0646\u064e \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u062d\u064e\u0631\u06e1\u062b\u064e \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0646\u064f\u0624\u06e1\u062a\u0650\u0647\u0650\u06e6 \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u06e5 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0645\u0650\u0646 \u0646\u0651\u064e\u0635\u0650\u064a\u0628\u064d",translation:"Barangsiapa menghendaki keuntungan di akhirat akan Kami tambahkan keuntungan itu baginya, dan barangsiapa menghendaki keuntungan di dunia Kami berikan kepadanya sebagian darinya (keuntungan dunia), tetapi dia tidak akan mendapat bagian di akhirat"},{id:21,text:"\u0623\u064e\u0645\u06e1 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0634\u064f\u0631\u064e\u0643\u064e\u0640\u0670\u0653\u0624\u064f\u0627\u0652 \u0634\u064e\u0631\u064e\u0639\u064f\u0648\u0627\u0652 \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u0650 \u0645\u064e\u0627 \u0644\u064e\u0645\u06e1 \u064a\u064e\u0623\u06e1\u0630\u064e\u0646\u06e2 \u0628\u0650\u0647\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06da \u0648\u064e\u0644\u064e\u0648\u06e1\u0644\u064e\u0627 \u0643\u064e\u0644\u0650\u0645\u064e\u0629\u064f \u0671\u0644\u06e1\u0641\u064e\u0635\u06e1\u0644\u0650 \u0644\u064e\u0642\u064f\u0636\u0650\u064a\u064e \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1\u06d7 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Apakah mereka mempunyai sesembahan selain Allah yang menetapkan aturan agama bagi mereka yang tidak diizinkan (diridai) Allah? Dan sekiranya tidak ada ketetapan yang menunda (hukuman dari Allah) tentulah hukuman di antara mereka telah dilaksanakan. Dan sungguh, orang-orang zalim itu akan mendapatkan azab yang sangat pedih"},{id:22,text:"\u062a\u064e\u0631\u064e\u0649 \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0645\u064f\u0634\u06e1\u0641\u0650\u0642\u0650\u064a\u0646\u064e \u0645\u0650\u0645\u0651\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064f\u0648\u0627\u0652 \u0648\u064e\u0647\u064f\u0648\u064e \u0648\u064e\u0627\u0642\u0650\u0639\u064f\u06e2 \u0628\u0650\u0647\u0650\u0645\u06e1\u06d7 \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0641\u0650\u064a \u0631\u064e\u0648\u06e1\u0636\u064e\u0627\u062a\u0650 \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0627\u062a\u0650\u06d6 \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u0648\u0646\u064e \u0639\u0650\u0646\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0641\u064e\u0636\u06e1\u0644\u064f \u0671\u0644\u06e1\u0643\u064e\u0628\u0650\u064a\u0631\u064f",translation:"Kamu akan melihat orang-orang zalim itu sangat ketakutan karena (kejahatan-kejahatan) yang telah mereka lakukan, dan (azab) menimpa mereka. Dan orang-orang yang beriman dan mengerjakan kebajikan (berada) di dalam taman-taman surga, mereka memperoleh apa yang mereka kehendaki di sisi Tuhan. Yang demikian itu adalah karunia yang besar"},{id:23,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u0628\u064e\u0634\u0651\u0650\u0631\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u0650\u0628\u064e\u0627\u062f\u064e\u0647\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650\u06d7 \u0642\u064f\u0644 \u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0643\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0623\u064e\u062c\u06e1\u0631\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u06e1\u0645\u064e\u0648\u064e\u062f\u0651\u064e\u0629\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0628\u064e\u0649\u0670\u06d7 \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0642\u06e1\u062a\u064e\u0631\u0650\u0641\u06e1 \u062d\u064e\u0633\u064e\u0646\u064e\u0629\u0657 \u0646\u0651\u064e\u0632\u0650\u062f\u06e1 \u0644\u064e\u0647\u064f\u06e5 \u0641\u0650\u064a\u0647\u064e\u0627 \u062d\u064f\u0633\u06e1\u0646\u064b\u0627\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0634\u064e\u0643\u064f\u0648\u0631\u064c",translation:"Itulah (karunia) yang diberitahukan Allah untuk menggembirakan hamba-hamba-Nya yang beriman dan mengerjakan kebajikan. Katakanlah (Muhammad), \"Aku tidak meminta kepadamu sesuatu imbalan pun atas seruanku kecuali kasih sayang dalam kekeluargaan.\" Dan barangsiapa mengerjakan kebaikan akan Kami tambahkan kebaikan baginya. Sungguh, Allah Maha Pengampun, Maha Mensyukuri"},{id:24,text:"\u0623\u064e\u0645\u06e1 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0671\u0641\u06e1\u062a\u064e\u0631\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u0630\u0650\u0628\u0657\u0627\u06d6 \u0641\u064e\u0625\u0650\u0646 \u064a\u064e\u0634\u064e\u0625\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u062e\u06e1\u062a\u0650\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064e\u0644\u06e1\u0628\u0650\u0643\u064e\u06d7 \u0648\u064e\u064a\u064e\u0645\u06e1\u062d\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u0628\u064e\u0670\u0637\u0650\u0644\u064e \u0648\u064e\u064a\u064f\u062d\u0650\u0642\u0651\u064f \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064e \u0628\u0650\u0643\u064e\u0644\u0650\u0645\u064e\u0670\u062a\u0650\u0647\u0650\u06e6\u0653\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0639\u064e\u0644\u0650\u064a\u0645\u064f\u06e2 \u0628\u0650\u0630\u064e\u0627\u062a\u0650 \u0671\u0644\u0635\u0651\u064f\u062f\u064f\u0648\u0631\u0650",translation:"Ataukah mereka mengatakan, \"Dia (Muhammad) telah mengada-adakan kebohongan tentang Allah.\" Sekiranya Allah menghendaki niscaya Dia kunci hatimu. Dan Allah menghapus yang batil dan membenarkan yang benar dengan firman-Nya (Alquran). Sungguh, Dia Maha Mengetahui segala isi hati"},{id:25,text:"\u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064e\u0642\u06e1\u0628\u064e\u0644\u064f \u0671\u0644\u062a\u0651\u064e\u0648\u06e1\u0628\u064e\u0629\u064e \u0639\u064e\u0646\u06e1 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650\u06e6 \u0648\u064e\u064a\u064e\u0639\u06e1\u0641\u064f\u0648\u0627\u0652 \u0639\u064e\u0646\u0650 \u0671\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0640\u0654\u064e\u0627\u062a\u0650 \u0648\u064e\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u062a\u064e\u0641\u06e1\u0639\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan Dialah yang menerima tobat dari hamba-hamba-Nya dan memaafkan kesalahan-kesalahan dan mengetahui apa yang kamu kerjakan"},{id:26,text:"\u0648\u064e\u064a\u064e\u0633\u06e1\u062a\u064e\u062c\u0650\u064a\u0628\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0648\u064e\u064a\u064e\u0632\u0650\u064a\u062f\u064f\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0641\u064e\u0636\u06e1\u0644\u0650\u0647\u0650\u06e6\u06da \u0648\u064e\u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u064f\u0648\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u065e \u0634\u064e\u062f\u0650\u064a\u062f\u065e",translation:"dan Dia memperkenankan (doa) orang-orang yang beriman dan mengerjakan kebajikan serta menambah (pahala) kepada mereka dari karunia-Nya. Orang-orang yang ingkar akan mendapat azab yang sangat keras"},{id:27,text:"\u06de\u0648\u064e\u0644\u064e\u0648\u06e1 \u0628\u064e\u0633\u064e\u0637\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0631\u0651\u0650\u0632\u06e1\u0642\u064e \u0644\u0650\u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650\u06e6 \u0644\u064e\u0628\u064e\u063a\u064e\u0648\u06e1\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u064a\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u064f \u0628\u0650\u0642\u064e\u062f\u064e\u0631\u0656 \u0645\u0651\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0628\u0650\u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650\u06e6 \u062e\u064e\u0628\u0650\u064a\u0631\u064f\u06e2 \u0628\u064e\u0635\u0650\u064a\u0631\u065e",translation:"Dan sekiranya Allah melapangkan rezeki kepada hamba-hamba-Nya niscaya mereka akan berbuat melampaui batas di bumi, tetapi Dia menurunkan dengan ukuran yang Dia kehendaki. Sungguh, Dia Mahateliti terhadap (keadaan) hamba-hamba-Nya, Maha Melihat"},{id:28,text:"\u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u064f \u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u062b\u064e \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0645\u064e\u0627 \u0642\u064e\u0646\u064e\u0637\u064f\u0648\u0627\u0652 \u0648\u064e\u064a\u064e\u0646\u0634\u064f\u0631\u064f \u0631\u064e\u062d\u06e1\u0645\u064e\u062a\u064e\u0647\u064f\u06e5\u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0648\u064e\u0644\u0650\u064a\u0651\u064f \u0671\u0644\u06e1\u062d\u064e\u0645\u0650\u064a\u062f\u064f",translation:"Dan Dialah yang menurunkan hujan setelah mereka berputus asa dan menyebarkan rahmat-Nya. Dan Dialah Maha Pelindung, Maha Terpuji"},{id:29,text:"\u0648\u064e\u0645\u0650\u0646\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0647\u0650\u06e6 \u062e\u064e\u0644\u06e1\u0642\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u062b\u0651\u064e \u0641\u0650\u064a\u0647\u0650\u0645\u064e\u0627 \u0645\u0650\u0646 \u062f\u064e\u0627\u0653\u0628\u0651\u064e\u0629\u0656\u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u062c\u064e\u0645\u06e1\u0639\u0650\u0647\u0650\u0645\u06e1 \u0625\u0650\u0630\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0642\u064e\u062f\u0650\u064a\u0631\u065e",translation:"Dan di antara tanda-tanda (kebesaran)-Nya adalah penciptaan langit dan bumi dan makhluk-makhluk melata yang Dia sebarkan pada keduanya. Dan Dia Mahakuasa mengumpulkan semuanya apabila Dia kehendaki"},{id:30,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0635\u064e\u0670\u0628\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0645\u0651\u064f\u0635\u0650\u064a\u0628\u064e\u0629\u0656 \u0641\u064e\u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064e\u062a\u06e1 \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u0643\u064f\u0645\u06e1 \u0648\u064e\u064a\u064e\u0639\u06e1\u0641\u064f\u0648\u0627\u0652 \u0639\u064e\u0646 \u0643\u064e\u062b\u0650\u064a\u0631\u0656",translation:"Dan musibah apapun yang menimpa kamu adalah karena perbuatan tanganmu sendiri, dan Allah memaafkan banyak (dari kesalahan-kesalahanmu)"},{id:31,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064f\u0645 \u0628\u0650\u0645\u064f\u0639\u06e1\u062c\u0650\u0632\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d6 \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646 \u0648\u064e\u0644\u0650\u064a\u0651\u0656 \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0635\u0650\u064a\u0631\u0656",translation:"Dan Kamu tidak dapat melepaskan diri (dari siksaan Allah) di bumi, dan kamu tidak memperoleh pelindung atau penolong selain Allah"},{id:32,text:"\u0648\u064e\u0645\u0650\u0646\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0647\u0650 \u0671\u0644\u06e1\u062c\u064e\u0648\u064e\u0627\u0631\u0650 \u0641\u0650\u064a \u0671\u0644\u06e1\u0628\u064e\u062d\u06e1\u0631\u0650 \u0643\u064e\u0671\u0644\u06e1\u0623\u064e\u0639\u06e1\u0644\u064e\u0670\u0645\u0650",translation:"Dan di antara tanda-tanda (kebesaran)-Nya ialah kapal-kapal (yang berlayar) di laut seperti gunung-gunung"},{id:33,text:"\u0625\u0650\u0646 \u064a\u064e\u0634\u064e\u0623\u06e1 \u064a\u064f\u0633\u06e1\u0643\u0650\u0646\u0650 \u0671\u0644\u0631\u0651\u0650\u064a\u062d\u064e \u0641\u064e\u064a\u064e\u0638\u06e1\u0644\u064e\u0644\u06e1\u0646\u064e \u0631\u064e\u0648\u064e\u0627\u0643\u0650\u062f\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0638\u064e\u0647\u06e1\u0631\u0650\u0647\u0650\u06e6\u0653\u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0623\u0653\u064a\u064e\u0670\u062a\u0656 \u0644\u0651\u0650\u0643\u064f\u0644\u0651\u0650 \u0635\u064e\u0628\u0651\u064e\u0627\u0631\u0656 \u0634\u064e\u0643\u064f\u0648\u0631\u064d",translation:"Jika Dia menghendaki, Dia akan menghentikan angin, sehingga jadilah (kapal-kapal) itu terhenti di permukaan laut. Sungguh, pada yang demikian itu terdapat tanda-tanda (kekuasaan Allah) bagi orang yang selalu bersabar dan banyak bersyukur"},{id:34,text:"\u0623\u064e\u0648\u06e1 \u064a\u064f\u0648\u0628\u0650\u0642\u06e1\u0647\u064f\u0646\u0651\u064e \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064f\u0648\u0627\u0652 \u0648\u064e\u064a\u064e\u0639\u06e1\u0641\u064f \u0639\u064e\u0646 \u0643\u064e\u062b\u0650\u064a\u0631\u0656",translation:"atau (Dia akan) menghancurkan kapal-kapal itu karena perbuatan (dosa) mereka, dan Dia memaafkan banyak (dari mereka)"},{id:35,text:"\u0648\u064e\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u062c\u064e\u0670\u062f\u0650\u0644\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0653 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0645\u0651\u064e\u062d\u0650\u064a\u0635\u0656",translation:"dan agar orang-orang yang membantah tanda-tanda (kekuasaan) Kami mengetahui bahwa mereka tidak akan memperoleh jalan ke luar (dari siksaan)"},{id:36,text:"\u0641\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0648\u062a\u0650\u064a\u062a\u064f\u0645 \u0645\u0651\u0650\u0646 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0641\u064e\u0645\u064e\u062a\u064e\u0670\u0639\u064f \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u0650 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627\u06da \u0648\u064e\u0645\u064e\u0627 \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062e\u064e\u064a\u06e1\u0631\u065e \u0648\u064e\u0623\u064e\u0628\u06e1\u0642\u064e\u0649\u0670 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u064a\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Apa pun (kenikmatan) yang diberikan kepadamu, maka itu adalah kesenangan hidup di dunia. Sedangkan apa (kenikmatan) yang ada di sisi Allah lebih baik dan lebih kekal bagi orang-orang yang beriman, dan hanya kepada Tuhan mereka bertawakal"},{id:37,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062c\u06e1\u062a\u064e\u0646\u0650\u0628\u064f\u0648\u0646\u064e \u0643\u064e\u0628\u064e\u0640\u0670\u0653\u0626\u0650\u0631\u064e \u0671\u0644\u06e1\u0625\u0650\u062b\u06e1\u0645\u0650 \u0648\u064e\u0671\u0644\u06e1\u0641\u064e\u0648\u064e\u0670\u062d\u0650\u0634\u064e \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0627 \u063a\u064e\u0636\u0650\u0628\u064f\u0648\u0627\u0652 \u0647\u064f\u0645\u06e1 \u064a\u064e\u063a\u06e1\u0641\u0650\u0631\u064f\u0648\u0646\u064e",translation:"dan juga (bagi) orang-orang yang menjauhi dosa-dosa besar dan perbuatan-perbuatan keji, dan apabila mereka marah segera memberi maaf"},{id:38,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u0633\u06e1\u062a\u064e\u062c\u064e\u0627\u0628\u064f\u0648\u0627\u0652 \u0644\u0650\u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0623\u064e\u0642\u064e\u0627\u0645\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u0623\u064e\u0645\u06e1\u0631\u064f\u0647\u064f\u0645\u06e1 \u0634\u064f\u0648\u0631\u064e\u0649\u0670 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0645\u0650\u0645\u0651\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u064a\u064f\u0646\u0641\u0650\u0642\u064f\u0648\u0646\u064e",translation:"dan (bagi) orang-orang yang menerima (mematuhi) seruan Tuhan dan melaksanakan salat, sedang urusan mereka (diputuskan) dengan musyawarah antara mereka; dan mereka menginfakkan sebagian dari rezeki yang Kami berikan kepada mereka"},{id:39,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0625\u0650\u0630\u064e\u0627\u0653 \u0623\u064e\u0635\u064e\u0627\u0628\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0628\u064e\u063a\u06e1\u064a\u064f \u0647\u064f\u0645\u06e1 \u064a\u064e\u0646\u062a\u064e\u0635\u0650\u0631\u064f\u0648\u0646\u064e",translation:"dan (bagi) orang-orang yang apabila mereka diperlakukan dengan zalim, mereka membela diri"},{id:40,text:"\u0648\u064e\u062c\u064e\u0632\u064e\u0640\u0670\u0653\u0624\u064f\u0627\u0652 \u0633\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u0656 \u0633\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u065e \u0645\u0651\u0650\u062b\u06e1\u0644\u064f\u0647\u064e\u0627\u06d6 \u0641\u064e\u0645\u064e\u0646\u06e1 \u0639\u064e\u0641\u064e\u0627 \u0648\u064e\u0623\u064e\u0635\u06e1\u0644\u064e\u062d\u064e \u0641\u064e\u0623\u064e\u062c\u06e1\u0631\u064f\u0647\u064f\u06e5 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dan balasan suatu kejahatan adalah kejahatan yang setimpal, tetapi barangsiapa memaafkan dan berbuat baik (kepada orang yang berbuat jahat) maka pahalanya dari Allah. Sungguh, Dia tidak menyukai orang-orang zalim"},{id:41,text:"\u0648\u064e\u0644\u064e\u0645\u064e\u0646\u0650 \u0671\u0646\u062a\u064e\u0635\u064e\u0631\u064e \u0628\u064e\u0639\u06e1\u062f\u064e \u0638\u064f\u0644\u06e1\u0645\u0650\u0647\u0650\u06e6 \u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0645\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0645\u0651\u0650\u0646 \u0633\u064e\u0628\u0650\u064a\u0644\u064d",translation:"Tetapi orang-orang yang membela diri setelah dizalimi, tidak ada alasan untuk menyalahkan mereka"},{id:42,text:"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0671\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u064f \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0638\u06e1\u0644\u0650\u0645\u064f\u0648\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0648\u064e\u064a\u064e\u0628\u06e1\u063a\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0628\u0650\u063a\u064e\u064a\u06e1\u0631\u0650 \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650\u06da \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Sesungguhnya kesalahan hanya ada pada orang-orang yang berbuat zalim kepada manusia dan melampaui batas di bumi tanpa (mengindahkan) kebenaran. Mereka itu mendapat siksaan yang pedih"},{id:43,text:"\u0648\u064e\u0644\u064e\u0645\u064e\u0646 \u0635\u064e\u0628\u064e\u0631\u064e \u0648\u064e\u063a\u064e\u0641\u064e\u0631\u064e \u0625\u0650\u0646\u0651\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0645\u0650\u0646\u06e1 \u0639\u064e\u0632\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0623\u064f\u0645\u064f\u0648\u0631\u0650",translation:"Tetapi barangsiapa bersabar dan memaafkan, sungguh yang demikian itu termasuk perbuatan yang mulia"},{id:44,text:"\u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0636\u06e1\u0644\u0650\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646 \u0648\u064e\u0644\u0650\u064a\u0651\u0656 \u0645\u0651\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u0647\u0650\u06e6\u06d7 \u0648\u064e\u062a\u064e\u0631\u064e\u0649 \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0644\u064e\u0645\u0651\u064e\u0627 \u0631\u064e\u0623\u064e\u0648\u064f\u0627\u0652 \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0647\u064e\u0644\u06e1 \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064e\u0631\u064e\u062f\u0651\u0656 \u0645\u0651\u0650\u0646 \u0633\u064e\u0628\u0650\u064a\u0644\u0656",translation:"Dan barangsiapa dibiarkan sesat oleh Allah, maka tidak ada baginya pelindung setelah itu. Kamu akan melihat orang-orang zalim ketika mereka melihat azab berkata, \"Adakah kiranya jalan untuk kembali (ke dunia)"},{id:45,text:"\u0648\u064e\u062a\u064e\u0631\u064e\u0649\u0670\u0647\u064f\u0645\u06e1 \u064a\u064f\u0639\u06e1\u0631\u064e\u0636\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627 \u062e\u064e\u0670\u0634\u0650\u0639\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0630\u0651\u064f\u0644\u0651\u0650 \u064a\u064e\u0646\u0638\u064f\u0631\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u0637\u064e\u0631\u06e1\u0641\u064d \u062e\u064e\u0641\u0650\u064a\u0651\u0656\u06d7 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u062e\u064e\u0670\u0633\u0650\u0631\u0650\u064a\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062e\u064e\u0633\u0650\u0631\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0647\u06e1\u0644\u0650\u064a\u0647\u0650\u0645\u06e1 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650\u06d7 \u0623\u064e\u0644\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0639\u064e\u0630\u064e\u0627\u0628\u0656 \u0645\u0651\u064f\u0642\u0650\u064a\u0645\u0656",translation:"Dan kamu akan melihat mereka dihadapkan ke neraka dalam keadaan tertunduk karena (merasa) hina, mereka melihat dengan pandangan yang lesu. Dan orang-orang yang beriman berkata, \"Sesungguhnya orang-orang yang rugi ialah orang-orang yang merugikan diri mereka sendiri dan keluarganya pada hari Kiamat.\" Ingatlah, sesungguhnya orang-orang zalim itu berada dalam azab yang kekal"},{id:46,text:"\u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u0648\u06e1\u0644\u0650\u064a\u064e\u0627\u0653\u0621\u064e \u064a\u064e\u0646\u0635\u064f\u0631\u064f\u0648\u0646\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d7 \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0636\u06e1\u0644\u0650\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646 \u0633\u064e\u0628\u0650\u064a\u0644\u064d",translation:"Dan mereka tidak akan mempunyai pelindung yang dapat menolong mereka selain Allah. Barang siapa dibiarkan sesat oleh Allah tidak akan ada jalan keluar baginya (untuk mendapat petunjuk)"},{id:47,text:"\u0671\u0633\u06e1\u062a\u064e\u062c\u0650\u064a\u0628\u064f\u0648\u0627\u0652 \u0644\u0650\u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650 \u0623\u064e\u0646 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e \u064a\u064e\u0648\u06e1\u0645\u065e \u0644\u0651\u064e\u0627 \u0645\u064e\u0631\u064e\u062f\u0651\u064e \u0644\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0645\u0651\u064e\u0644\u06e1\u062c\u064e\u0625\u0656 \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0646\u0651\u064e\u0643\u0650\u064a\u0631\u0656",translation:"Patuhilah seruan Tuhanmu sebelum datang dari Allah suatu hari yang tidak dapat ditolak (atas perintah dari Allah). Pada hari itu kamu tidak memperoleh tempat berlindung dan tidak (pula) dapat mengingkari (dosa-dosamu)"},{id:48,text:"\u0641\u064e\u0625\u0650\u0646\u06e1 \u0623\u064e\u0639\u06e1\u0631\u064e\u0636\u064f\u0648\u0627\u0652 \u0641\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0670\u0643\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u062d\u064e\u0641\u0650\u064a\u0638\u064b\u0627\u06d6 \u0625\u0650\u0646\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u06e1\u0628\u064e\u0644\u064e\u0670\u063a\u064f\u06d7 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0625\u0650\u0630\u064e\u0627\u0653 \u0623\u064e\u0630\u064e\u0642\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064e \u0645\u0650\u0646\u0651\u064e\u0627 \u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u0657 \u0641\u064e\u0631\u0650\u062d\u064e \u0628\u0650\u0647\u064e\u0627\u06d6 \u0648\u064e\u0625\u0650\u0646 \u062a\u064f\u0635\u0650\u0628\u06e1\u0647\u064f\u0645\u06e1 \u0633\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u064f\u06e2 \u0628\u0650\u0645\u064e\u0627 \u0642\u064e\u062f\u0651\u064e\u0645\u064e\u062a\u06e1 \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u0647\u0650\u0645\u06e1 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064e \u0643\u064e\u0641\u064f\u0648\u0631\u065e",translation:"Jika mereka berpaling, maka (ingatlah) Kami tidak mengutus engkau sebagai pengawas bagi mereka. Kewajibanmu tidak lain hanyalah menyampaikan (risalah). Dan sungguh, apabila Kami merasakan kepada manusia suatu rahmat dari Kami, dia menyambutnya dengan gembira; tetapi jika mereka ditimpa kesusahan karena perbuatan tangan mereka sendiri (niscaya mereka ingkar), sungguh, manusia itu sangat ingkar (kepada nikmat)"},{id:49,text:"\u0644\u0651\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064f\u0644\u06e1\u0643\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06da \u064a\u064e\u062e\u06e1\u0644\u064f\u0642\u064f \u0645\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06da \u064a\u064e\u0647\u064e\u0628\u064f \u0644\u0650\u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0625\u0650\u0646\u064e\u0670\u062b\u0657\u0627 \u0648\u064e\u064a\u064e\u0647\u064e\u0628\u064f \u0644\u0650\u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0671\u0644\u0630\u0651\u064f\u0643\u064f\u0648\u0631\u064e",translation:"Milik Allah lah kerajaan langit dan bumi; Dia menciptakan apa yang Dia kehendaki, memberikan anak perempuan kepada siapa yang Dia kehendaki, dan memberikan anak laki-laki kepada siapa yang Dia kehendaki"},{id:50,text:"\u0623\u064e\u0648\u06e1 \u064a\u064f\u0632\u064e\u0648\u0651\u0650\u062c\u064f\u0647\u064f\u0645\u06e1 \u0630\u064f\u0643\u06e1\u0631\u064e\u0627\u0646\u0657\u0627 \u0648\u064e\u0625\u0650\u0646\u064e\u0670\u062b\u0657\u0627\u06d6 \u0648\u064e\u064a\u064e\u062c\u06e1\u0639\u064e\u0644\u064f \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0639\u064e\u0642\u0650\u064a\u0645\u064b\u0627\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0639\u064e\u0644\u0650\u064a\u0645\u065e \u0642\u064e\u062f\u0650\u064a\u0631\u065e",translation:"atau Dia menganugerahkan jenis laki-laki dan perempuan, dan menjadikan mandul siapa yang Dia kehendaki. Dia Maha Mengetahui, Mahakuasa"},{id:51,text:"\u06de\u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0628\u064e\u0634\u064e\u0631\u064d \u0623\u064e\u0646 \u064a\u064f\u0643\u064e\u0644\u0651\u0650\u0645\u064e\u0647\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0648\u064e\u062d\u06e1\u064a\u064b\u0627 \u0623\u064e\u0648\u06e1 \u0645\u0650\u0646 \u0648\u064e\u0631\u064e\u0627\u0653\u064a\u0655\u0650 \u062d\u0650\u062c\u064e\u0627\u0628\u064d \u0623\u064e\u0648\u06e1 \u064a\u064f\u0631\u06e1\u0633\u0650\u0644\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u0657\u0627 \u0641\u064e\u064a\u064f\u0648\u062d\u0650\u064a\u064e \u0628\u0650\u0625\u0650\u0630\u06e1\u0646\u0650\u0647\u0650\u06e6 \u0645\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0639\u064e\u0644\u0650\u064a\u0651\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u065e",translation:"(Dan tidaklah patut bagi seorang manusia bahwa Allah akan berbicara kepadanya kecuali dengan perantaraan wahyu atau dari belakang tabir780) atau dengan mengutus utusan (malaikat) lalu diwahyukan kepadanya dengan izin-Nya apa yang Dia kehendaki. Sungguh, Dia Mahatinggi, Mahabijaksana"},{id:52,text:"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0623\u064e\u0648\u06e1\u062d\u064e\u064a\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0631\u064f\u0648\u062d\u0657\u0627 \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u0645\u06e1\u0631\u0650\u0646\u064e\u0627\u06da \u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064e \u062a\u064e\u062f\u06e1\u0631\u0650\u064a \u0645\u064e\u0627 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064f \u0648\u064e\u0644\u064e\u0627 \u0671\u0644\u06e1\u0625\u0650\u064a\u0645\u064e\u0670\u0646\u064f \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f \u0646\u064f\u0648\u0631\u0657\u0627 \u0646\u0651\u064e\u0647\u06e1\u062f\u0650\u064a \u0628\u0650\u0647\u0650\u06e6 \u0645\u064e\u0646 \u0646\u0651\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0645\u0650\u0646\u06e1 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0646\u064e\u0627\u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u062a\u064e\u0647\u06e1\u062f\u0650\u064a\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0670\u0637\u0656 \u0645\u0651\u064f\u0633\u06e1\u062a\u064e\u0642\u0650\u064a\u0645\u0656",translation:"Dan demikianlah Kami wahyukan kepadamu (Muhammad) r\u016bh (Alquran) dengan perintah Kami. Sebelumnya engkau tidaklah mengetahui apakah Kitab (Alquran) dan apakah iman itu, tetapi Kami jadikan Alquran itu cahaya, dengan itu Kami memberi petunjuk pada siapa yang Kami kehendaki di antara hamba-hamba Kami. Dan sungguh, engkau benar-benar membimbing (manusia) ke jalan yang lurus"},{id:53,text:"\u0635\u0650\u0631\u064e\u0670\u0637\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0644\u064e\u0647\u064f\u06e5 \u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d7 \u0623\u064e\u0644\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064e\u0635\u0650\u064a\u0631\u064f \u0671\u0644\u06e1\u0623\u064f\u0645\u064f\u0648\u0631\u064f",translation:"(Yaitu) jalan Allah yang milik-Nyalah apa yang ada di langit dan apa yang ada di bumi. Ingatlah, segala urusan kembali kepada Allah"}]},{id:43,name:"\u0627\u0644\u0632\u062e\u0631\u0641",transliteration:"Az-Zukhruf",translation:"Perhiasan",type:"meccan",total_verses:89,verses:[{id:1,text:"\u062d\u0645\u0653",translation:"\u1e24\u0101 M\u012bm"},{id:2,text:"\u0648\u064e\u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0671\u0644\u06e1\u0645\u064f\u0628\u0650\u064a\u0646\u0650",translation:"Demi Kitab (Alquran) yang jelas"},{id:3,text:"\u0625\u0650\u0646\u0651\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f \u0642\u064f\u0631\u06e1\u0621\u064e\u0670\u0646\u064b\u0627 \u0639\u064e\u0631\u064e\u0628\u0650\u064a\u0651\u0657\u0627 \u0644\u0651\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Kami menjadikan Alquran dalam bahasa Arab agar kamu mengerti"},{id:4,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0641\u0650\u064a\u0653 \u0623\u064f\u0645\u0651\u0650 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0644\u064e\u062f\u064e\u064a\u06e1\u0646\u064e\u0627 \u0644\u064e\u0639\u064e\u0644\u0650\u064a\u0651\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u064c",translation:"Dan sesungguhnya Alquran itu dalam ummul Kit\u0101b (Lau\u1e25 Ma\u1e25f\u016b\u1e93) di sisi Kami, benar-benar (bernilai) tinggi dan penuh hikmah"},{id:5,text:"\u0623\u064e\u0641\u064e\u0646\u064e\u0636\u06e1\u0631\u0650\u0628\u064f \u0639\u064e\u0646\u0643\u064f\u0645\u064f \u0671\u0644\u0630\u0651\u0650\u0643\u06e1\u0631\u064e \u0635\u064e\u0641\u06e1\u062d\u064b\u0627 \u0623\u064e\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0642\u064e\u0648\u06e1\u0645\u0657\u0627 \u0645\u0651\u064f\u0633\u06e1\u0631\u0650\u0641\u0650\u064a\u0646\u064e",translation:"Maka apakah Kami akan berhenti menurunkan ayat-ayat (sebagai peringatan) Alquran kepadamu, karena kamu kaum yang melampuai batas"},{id:6,text:"\u0648\u064e\u0643\u064e\u0645\u06e1 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646 \u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0656 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",translation:"Dan betapa banyak nabi-nabi yang telah Kami utus kepada umat-umat yang terdahulu"},{id:7,text:"\u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u0647\u0650\u0645 \u0645\u0651\u0650\u0646 \u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6 \u064a\u064e\u0633\u06e1\u062a\u064e\u0647\u06e1\u0632\u0650\u0621\u064f\u0648\u0646\u064e",translation:"Dan setiap kali seorang nabi datang kepada mereka, mereka selalu memperolok-olokkannya"},{id:8,text:"\u0641\u064e\u0623\u064e\u0647\u06e1\u0644\u064e\u0643\u06e1\u0646\u064e\u0627\u0653 \u0623\u064e\u0634\u064e\u062f\u0651\u064e \u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0628\u064e\u0637\u06e1\u0634\u0657\u0627 \u0648\u064e\u0645\u064e\u0636\u064e\u0649\u0670 \u0645\u064e\u062b\u064e\u0644\u064f \u0671\u0644\u06e1\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",translation:"Karena itu, Kami binasakan orang-orang yang lebih besar kekuatannya di antara mereka dan telah berlalu contoh umat-umat terdahulu"},{id:9,text:"\u0648\u064e\u0644\u064e\u0626\u0650\u0646 \u0633\u064e\u0623\u064e\u0644\u06e1\u062a\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u0646\u06e1 \u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0644\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0646\u0651\u064e \u062e\u064e\u0644\u064e\u0642\u064e\u0647\u064f\u0646\u0651\u064e \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0671\u0644\u06e1\u0639\u064e\u0644\u0650\u064a\u0645\u064f",translation:"Dan jika kamu tanyakan kepada mereka, \"Siapakah yang menciptakan langit dan bumi?\" pastilah mereka akan menjawab, \"Semuanya diciptakan oleh Yang Mahaperkasa, Maha Mengetahui"},{id:10,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0645\u064e\u0647\u06e1\u062f\u0657\u0627 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u0633\u064f\u0628\u064f\u0644\u0657\u0627 \u0644\u0651\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u0647\u06e1\u062a\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Yang menjadikan bumi sebagai tempat menetap bagimu dan Dia menjadikan jalan-jalan di atas bumi untukmu agar kamu mendapat petunjuk"},{id:11,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0646\u064e\u0632\u0651\u064e\u0644\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0645\u064e\u0627\u0653\u0621\u064e\u06e2 \u0628\u0650\u0642\u064e\u062f\u064e\u0631\u0656 \u0641\u064e\u0623\u064e\u0646\u0634\u064e\u0631\u06e1\u0646\u064e\u0627 \u0628\u0650\u0647\u0650\u06e6 \u0628\u064e\u0644\u06e1\u062f\u064e\u0629\u0657 \u0645\u0651\u064e\u064a\u06e1\u062a\u0657\u0627\u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062a\u064f\u062e\u06e1\u0631\u064e\u062c\u064f\u0648\u0646\u064e",translation:"Dan yang menurunkan air dari langit menurut ukuran (yang diperlukan), lalu dengan air itu Kami hidupkan negeri yang mati (tandus). Seperti itulah kamu akan dikeluarkan (dari kubur)"},{id:12,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u06e1\u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u064e \u0643\u064f\u0644\u0651\u064e\u0647\u064e\u0627 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0641\u064f\u0644\u06e1\u0643\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0639\u064e\u0670\u0645\u0650 \u0645\u064e\u0627 \u062a\u064e\u0631\u06e1\u0643\u064e\u0628\u064f\u0648\u0646\u064e",translation:"Dan yang menciptakan semua berpasangan-pasangan dan menjadikan kapal untukmu dan hewan ternak yang kamu tunggangi"},{id:13,text:"\u0644\u0650\u062a\u064e\u0633\u06e1\u062a\u064e\u0648\u064f\u06e5\u0627\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0638\u064f\u0647\u064f\u0648\u0631\u0650\u0647\u0650\u06e6 \u062b\u064f\u0645\u0651\u064e \u062a\u064e\u0630\u06e1\u0643\u064f\u0631\u064f\u0648\u0627\u0652 \u0646\u0650\u0639\u06e1\u0645\u064e\u0629\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1 \u0625\u0650\u0630\u064e\u0627 \u0671\u0633\u06e1\u062a\u064e\u0648\u064e\u064a\u06e1\u062a\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0648\u064e\u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627\u0652 \u0633\u064f\u0628\u06e1\u062d\u064e\u0670\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0633\u064e\u062e\u0651\u064e\u0631\u064e \u0644\u064e\u0646\u064e\u0627 \u0647\u064e\u0670\u0630\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0644\u064e\u0647\u064f\u06e5 \u0645\u064f\u0642\u06e1\u0631\u0650\u0646\u0650\u064a\u0646\u064e",translation:"agar kamu duduk di atas punggungnya kemudian kamu ingat nikmat Tuhanmu apabila kamu telah duduk di atasnya; dan agar kamu mengucapkan, \"Mahasuci (Allah) yang telah menundukkan semua ini bagi kami, padahal kami sebelumnya tidak mampu menguasainya"},{id:14,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627 \u0644\u064e\u0645\u064f\u0646\u0642\u064e\u0644\u0650\u0628\u064f\u0648\u0646\u064e",translation:"dan sesungguhnya kami akan kembali kepada Tuhan kami"},{id:15,text:"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646\u06e1 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650\u06e6 \u062c\u064f\u0632\u06e1\u0621\u064b\u0627\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064e \u0644\u064e\u0643\u064e\u0641\u064f\u0648\u0631\u065e \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u064c",translation:"(Dan mereka menjadikan sebagian dari hamba-hamba-Nya sebagai bagian dari-Nya.781) Sungguh, manusia itu pengingkar (nikmat Tuhan) yang nyata"},{id:16,text:"\u0623\u064e\u0645\u0650 \u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064e \u0645\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u062e\u06e1\u0644\u064f\u0642\u064f \u0628\u064e\u0646\u064e\u0627\u062a\u0656 \u0648\u064e\u0623\u064e\u0635\u06e1\u0641\u064e\u0649\u0670\u0643\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0628\u064e\u0646\u0650\u064a\u0646\u064e",translation:"Pantaskah Dia mengambil anak perempuan dari yang diciptakan-Nya dan memberikan anak laki-laki kepadamu"},{id:17,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0628\u064f\u0634\u0651\u0650\u0631\u064e \u0623\u064e\u062d\u064e\u062f\u064f\u0647\u064f\u0645 \u0628\u0650\u0645\u064e\u0627 \u0636\u064e\u0631\u064e\u0628\u064e \u0644\u0650\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u0650 \u0645\u064e\u062b\u064e\u0644\u0657\u0627 \u0638\u064e\u0644\u0651\u064e \u0648\u064e\u062c\u06e1\u0647\u064f\u0647\u064f\u06e5 \u0645\u064f\u0633\u06e1\u0648\u064e\u062f\u0651\u0657\u0627 \u0648\u064e\u0647\u064f\u0648\u064e \u0643\u064e\u0638\u0650\u064a\u0645\u064c",translation:"Dan apabila salah seorang di antara mereka diberi kabar gembira dengan apa (kelahiran anak perempuan) yang dijadikan sebagai perumpamaan bagi (Allah) Yang Maha Pengasih, jadilah wajahnya hitam pekat karena menahan sedih (dan marah)"},{id:18,text:"\u0623\u064e\u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0646\u064e\u0634\u0651\u064e\u0624\u064f\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u06e1\u062d\u0650\u0644\u06e1\u064a\u064e\u0629\u0650 \u0648\u064e\u0647\u064f\u0648\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u062e\u0650\u0635\u064e\u0627\u0645\u0650 \u063a\u064e\u064a\u06e1\u0631\u064f \u0645\u064f\u0628\u0650\u064a\u0646\u0656",translation:"Dan apakah patut (menjadi anak Allah) orang yang dibesarkan sebagai perhiasan sedang dia tidak mampu memberi alasan yang tegas dan jelas dalam pertengkaran"},{id:19,text:"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645\u06e1 \u0639\u0650\u0628\u064e\u0670\u062f\u064f \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u0650 \u0625\u0650\u0646\u064e\u0670\u062b\u064b\u0627\u06da \u0623\u064e\u0634\u064e\u0647\u0650\u062f\u064f\u0648\u0627\u0652 \u062e\u064e\u0644\u06e1\u0642\u064e\u0647\u064f\u0645\u06e1\u06da \u0633\u064e\u062a\u064f\u0643\u06e1\u062a\u064e\u0628\u064f \u0634\u064e\u0647\u064e\u0670\u062f\u064e\u062a\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u064a\u064f\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan mereka menjadikan malaikat-malaikat hamba-hamba (Allah) Yang Maha Pengasih itu sebagai jenis perempuan. Apakah mereka menyaksikan penciptaan (malaikat-malaikat itu)? Kelak akan dituliskan kesaksian mereka dan akan dimintakan pertanggungjawaban"},{id:20,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0648\u06e1 \u0634\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u064f \u0645\u064e\u0627 \u0639\u064e\u0628\u064e\u062f\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06d7 \u0645\u0651\u064e\u0627 \u0644\u064e\u0647\u064f\u0645 \u0628\u0650\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u0650\u0646\u06e1 \u0639\u0650\u0644\u06e1\u0645\u064d\u06d6 \u0625\u0650\u0646\u06e1 \u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u064a\u064e\u062e\u06e1\u0631\u064f\u0635\u064f\u0648\u0646\u064e",translation:"Dan mereka berkata, \"Sekiranya (Allah) Yang Mahapengasih menghendaki, tentulah kami tidak menyembah mereka (malaikat).\" Mereka tidak mempunyai ilmu sedikit pun tentang itu. Tidak lain mereka hanyalah menduga-duga belaka"},{id:21,text:"\u0623\u064e\u0645\u06e1 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0643\u0650\u062a\u064e\u0670\u0628\u0657\u0627 \u0645\u0651\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u06e6 \u0641\u064e\u0647\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6 \u0645\u064f\u0633\u06e1\u062a\u064e\u0645\u06e1\u0633\u0650\u0643\u064f\u0648\u0646\u064e",translation:"Atau apakah pernah Kami berikan suatu kitab kepada mereka sebelumnya, lalu mereka berpegang (pada kitab itu)"},{id:22,text:"\u0628\u064e\u0644\u06e1 \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e\u0627 \u0648\u064e\u062c\u064e\u062f\u06e1\u0646\u064e\u0627\u0653 \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0621\u064e\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064f\u0645\u0651\u064e\u0629\u0656 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0621\u064e\u0627\u062b\u064e\u0670\u0631\u0650\u0647\u0650\u0645 \u0645\u0651\u064f\u0647\u06e1\u062a\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Bahkan mereka berkata, \"Sesungguhnya kami mendapati nenek moyang kami menganut suatu agama, dan kami mendapat petunjuk untuk mengikuti jejak mereka"},{id:23,text:"\u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u064e\u0627\u0653 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064e \u0641\u0650\u064a \u0642\u064e\u0631\u06e1\u064a\u064e\u0629\u0656 \u0645\u0651\u0650\u0646 \u0646\u0651\u064e\u0630\u0650\u064a\u0631\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0627\u0644\u064e \u0645\u064f\u062a\u06e1\u0631\u064e\u0641\u064f\u0648\u0647\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0627 \u0648\u064e\u062c\u064e\u062f\u06e1\u0646\u064e\u0627\u0653 \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0621\u064e\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064f\u0645\u0651\u064e\u0629\u0656 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0621\u064e\u0627\u062b\u064e\u0670\u0631\u0650\u0647\u0650\u0645 \u0645\u0651\u064f\u0642\u06e1\u062a\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Dan demikian juga ketika Kami mengutus seorang pemberi peringatan sebelum engkau (Muhammad) dalam suatu negeri, orang-orang yang hidup mewah (di negeri itu) selalu berkata, \"Sesungguhnya kami mendapati nenek moyang kami menganut suatu (agama) dan sesungguhnya kami sekedar pengikut jejak-jejak mereka"},{id:24,text:"\u06de\u0642\u064e\u0670\u0644\u064e \u0623\u064e\u0648\u064e\u0644\u064e\u0648\u06e1 \u062c\u0650\u0626\u06e1\u062a\u064f\u0643\u064f\u0645 \u0628\u0650\u0623\u064e\u0647\u06e1\u062f\u064e\u0649\u0670 \u0645\u0650\u0645\u0651\u064e\u0627 \u0648\u064e\u062c\u064e\u062f\u062a\u0651\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u06e1\u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e\u0627 \u0628\u0650\u0645\u064e\u0627\u0653 \u0623\u064f\u0631\u06e1\u0633\u0650\u0644\u06e1\u062a\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6 \u0643\u064e\u0670\u0641\u0650\u0631\u064f\u0648\u0646\u064e",translation:"(Rasul itu) berkata, \"Apakah (kamu akan mengikutinya juga) sekalipun aku membawa untukmu (agama) yang lebih baik daripada apa yang kamu peroleh dari (agama) yang dianut nenek moyangmu.\" Mereka menjawab, \"Sesungguhnya kami mengingkari (agama) yang kamu diperintahkan untuk menyampaikannya"},{id:25,text:"\u0641\u064e\u0671\u0646\u062a\u064e\u0642\u064e\u0645\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1\u06d6 \u0641\u064e\u0671\u0646\u0638\u064f\u0631\u06e1 \u0643\u064e\u064a\u06e1\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0670\u0642\u0650\u0628\u064e\u0629\u064f \u0671\u0644\u06e1\u0645\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u0650\u064a\u0646\u064e",translation:"Lalu Kami binasakan mereka, maka perhatikanlah bagaimana kesudahan orang-orang yang mendustakan (kebenaran)"},{id:26,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064f \u0644\u0650\u0623\u064e\u0628\u0650\u064a\u0647\u0650 \u0648\u064e\u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0646\u0651\u064e\u0646\u0650\u064a \u0628\u064e\u0631\u064e\u0627\u0653\u0621\u065e \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0646\u064e",translation:"Dan (ingatlah) ketika Ibrahim berkata kepada ayahnya dan kaumnya, \"Sesungguhnya aku berlepas diri dari apa yang kamu sembah"},{id:27,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0641\u064e\u0637\u064e\u0631\u064e\u0646\u0650\u064a \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0633\u064e\u064a\u064e\u0647\u06e1\u062f\u0650\u064a\u0646\u0650",translation:"kecuali (kamu menyembah) Allah yang menciptakanku; karena sungguh, Dia akan memberi petunjuk kepadaku"},{id:28,text:"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e\u0647\u064e\u0627 \u0643\u064e\u0644\u0650\u0645\u064e\u0629\u064e\u06e2 \u0628\u064e\u0627\u0642\u0650\u064a\u064e\u0629\u0657 \u0641\u0650\u064a \u0639\u064e\u0642\u0650\u0628\u0650\u0647\u0650\u06e6 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0631\u06e1\u062c\u0650\u0639\u064f\u0648\u0646\u064e",translation:"Dan (Ibrahim) menjadikan (kalimat tauhid) itu kalimat yang kekal pada keturunannya agar mereka kembali (kepada kalimat tauhid itu)"},{id:29,text:"\u0628\u064e\u0644\u06e1 \u0645\u064e\u062a\u0651\u064e\u0639\u06e1\u062a\u064f \u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650 \u0648\u064e\u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u06e1 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u065e \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u065e",translation:"Bahkan Aku telah memberikan kenikmatan hidup kepada mereka dan nenek moyang mereka sampai kebenaran (Alquran) datang kepada mereka bersama seorang Rasul yang memberi penjelasan"},{id:30,text:"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0647\u064e\u0670\u0630\u064e\u0627 \u0633\u0650\u062d\u06e1\u0631\u065e \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0628\u0650\u0647\u0650\u06e6 \u0643\u064e\u0670\u0641\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Tetapi ketika kebenaran (Alquran) itu datang kepada mereka, mereka berkata, \"Ini adalah sihir, dan sesungguhnya kami mengingkarinya"},{id:31,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0648\u06e1\u0644\u064e\u0627 \u0646\u064f\u0632\u0651\u0650\u0644\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u062c\u064f\u0644\u0656 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0642\u064e\u0631\u06e1\u064a\u064e\u062a\u064e\u064a\u06e1\u0646\u0650 \u0639\u064e\u0638\u0650\u064a\u0645\u064d",translation:"Dan mereka (juga) berkata, \"Mengapa Alquran ini tidak diturunkan kepada orang besar (kaya dan berpengaruh) dari salah satu dua negeri ini (Mekkah dan Taif)"},{id:32,text:"\u0623\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0642\u06e1\u0633\u0650\u0645\u064f\u0648\u0646\u064e \u0631\u064e\u062d\u06e1\u0645\u064e\u062a\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064e\u06da \u0646\u064e\u062d\u06e1\u0646\u064f \u0642\u064e\u0633\u064e\u0645\u06e1\u0646\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u0639\u0650\u064a\u0634\u064e\u062a\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u0650 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627\u06da \u0648\u064e\u0631\u064e\u0641\u064e\u0639\u06e1\u0646\u064e\u0627 \u0628\u064e\u0639\u06e1\u0636\u064e\u0647\u064f\u0645\u06e1 \u0641\u064e\u0648\u06e1\u0642\u064e \u0628\u064e\u0639\u06e1\u0636\u0656 \u062f\u064e\u0631\u064e\u062c\u064e\u0670\u062a\u0656 \u0644\u0651\u0650\u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064e \u0628\u064e\u0639\u06e1\u0636\u064f\u0647\u064f\u0645 \u0628\u064e\u0639\u06e1\u0636\u0657\u0627 \u0633\u064f\u062e\u06e1\u0631\u0650\u064a\u0651\u0657\u0627\u06d7 \u0648\u064e\u0631\u064e\u062d\u06e1\u0645\u064e\u062a\u064f \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u062e\u064e\u064a\u06e1\u0631\u065e \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u062c\u06e1\u0645\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Apakah mereka yang membagi-bagi rahmat Tuhanmu? Kamilah yang menentukan penghidupan mereka dalam kehidupan dunia, dan Kami telah meninggikan sebagian mereka atas sebagian yang lain beberapa derajat, agar sebagian mereka dapat memanfaatkan sebagian yang lain. Dan rahmat Tuhanmu lebih baik dari apa yang mereka kumpulkan"},{id:33,text:"\u0648\u064e\u0644\u064e\u0648\u06e1\u0644\u064e\u0627\u0653 \u0623\u064e\u0646 \u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0623\u064f\u0645\u0651\u064e\u0629\u0657 \u0648\u064e\u0670\u062d\u0650\u062f\u064e\u0629\u0657 \u0644\u0651\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0644\u0650\u0645\u064e\u0646 \u064a\u064e\u0643\u06e1\u0641\u064f\u0631\u064f \u0628\u0650\u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u0650 \u0644\u0650\u0628\u064f\u064a\u064f\u0648\u062a\u0650\u0647\u0650\u0645\u06e1 \u0633\u064f\u0642\u064f\u0641\u0657\u0627 \u0645\u0651\u0650\u0646 \u0641\u0650\u0636\u0651\u064e\u0629\u0656 \u0648\u064e\u0645\u064e\u0639\u064e\u0627\u0631\u0650\u062c\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627 \u064a\u064e\u0638\u06e1\u0647\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan sekiranya bukan karena menghindarkan manusia menjadi umat yang satu (dalam kekafiran), pastilah sudah Kami buatkan bagi orang-orang yang kafir kepada (Allah) Yang Maha Pengasih, loteng-loteng rumah mereka dari perak, demikian pula tangga-tangga yang mereka naiki"},{id:34,text:"\u0648\u064e\u0644\u0650\u0628\u064f\u064a\u064f\u0648\u062a\u0650\u0647\u0650\u0645\u06e1 \u0623\u064e\u0628\u06e1\u0648\u064e\u0670\u0628\u0657\u0627 \u0648\u064e\u0633\u064f\u0631\u064f\u0631\u064b\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627 \u064a\u064e\u062a\u0651\u064e\u0643\u0650\u0640\u0654\u064f\u0648\u0646\u064e",translation:"dan (Kami buatkan pula) pintu-pintu (perak) bagi rumah-rumah mereka, dan (begitu pula) dipan-dipan tempat mereka bersandar"},{id:35,text:"\u0648\u064e\u0632\u064f\u062e\u06e1\u0631\u064f\u0641\u0657\u0627\u06da \u0648\u064e\u0625\u0650\u0646 \u0643\u064f\u0644\u0651\u064f \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0645\u0651\u064e\u0627 \u0645\u064e\u062a\u064e\u0670\u0639\u064f \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u0650 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627\u06da \u0648\u064e\u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u064f \u0639\u0650\u0646\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0644\u0650\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",translation:"dan (Kami buatkan pula) perhiasan-perhiasan dari emas. Dan semuanya itu tidak lain hanyalah kesenangan kehidupan dunia, sedangkan kehidupan akhirat di sisi Tuhanmu disediakan bagi orang-orang yang bertakwa"},{id:36,text:"\u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0639\u06e1\u0634\u064f \u0639\u064e\u0646 \u0630\u0650\u0643\u06e1\u0631\u0650 \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u0650 \u0646\u064f\u0642\u064e\u064a\u0651\u0650\u0636\u06e1 \u0644\u064e\u0647\u064f\u06e5 \u0634\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u0657\u0627 \u0641\u064e\u0647\u064f\u0648\u064e \u0644\u064e\u0647\u064f\u06e5 \u0642\u064e\u0631\u0650\u064a\u0646\u065e",translation:"Dan barangsiapa yang berpaling dari pengajaran Allah Yang Maha Pengasih (Alquran), Kami biarkan setan (menyesatkannya) dan menjadi teman karibnya"},{id:37,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u064a\u064e\u0635\u064f\u062f\u0651\u064f\u0648\u0646\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0646\u0650 \u0671\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u0650 \u0648\u064e\u064a\u064e\u062d\u06e1\u0633\u064e\u0628\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645 \u0645\u0651\u064f\u0647\u06e1\u062a\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Dan sungguh, mereka (setan-setan itu) benar-benar menghalang-halangi mereka dari jalan yang benar, sedang mereka menyangka bahwa mereka mendapat petunjuk"},{id:38,text:"\u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u0646\u064e\u0627 \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0670\u0644\u064e\u064a\u06e1\u062a\u064e \u0628\u064e\u064a\u06e1\u0646\u0650\u064a \u0648\u064e\u0628\u064e\u064a\u06e1\u0646\u064e\u0643\u064e \u0628\u064f\u0639\u06e1\u062f\u064e \u0671\u0644\u06e1\u0645\u064e\u0634\u06e1\u0631\u0650\u0642\u064e\u064a\u06e1\u0646\u0650 \u0641\u064e\u0628\u0650\u0626\u06e1\u0633\u064e \u0671\u0644\u06e1\u0642\u064e\u0631\u0650\u064a\u0646\u064f",translation:"Sehingga apabila orang\u2013orang yang berpaling itu datang kepada Kami (pada hari Kiamat) dia berkata, \"Wahai! Sekiranya (jarak) antara aku dan kamu seperti jarak antara timur dan barat! Memang (setan itu) teman yang paling jahat (bagi manusia)"},{id:39,text:"\u0648\u064e\u0644\u064e\u0646 \u064a\u064e\u0646\u0641\u064e\u0639\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e \u0625\u0650\u0630 \u0638\u0651\u064e\u0644\u064e\u0645\u06e1\u062a\u064f\u0645\u06e1 \u0623\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0645\u064f\u0634\u06e1\u062a\u064e\u0631\u0650\u0643\u064f\u0648\u0646\u064e",translation:"Dan (harapanmu itu) sekali-kali tidak akan memberi manfaat kepadamu pada hari itu karena kamu telah menzalimi (dirimu sendiri). Sesungguhnya kamu pantas bersama-sama dalam azab itu"},{id:40,text:"\u0623\u064e\u0641\u064e\u0623\u064e\u0646\u062a\u064e \u062a\u064f\u0633\u06e1\u0645\u0650\u0639\u064f \u0671\u0644\u0635\u0651\u064f\u0645\u0651\u064e \u0623\u064e\u0648\u06e1 \u062a\u064e\u0647\u06e1\u062f\u0650\u064a \u0671\u0644\u06e1\u0639\u064f\u0645\u06e1\u064a\u064e \u0648\u064e\u0645\u064e\u0646 \u0643\u064e\u0627\u0646\u064e \u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0670\u0644\u0656 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u0656",translation:"Maka apakah engkau (Muhammad) dapat menjadikan orang yang tuli bisa mendengar, atau (dapatkah) engkau memberi petunjuk kepada orang yang buta (hatinya), dan kepada orang yang tetap dalam kesesatan yang nyata"},{id:41,text:"\u0641\u064e\u0625\u0650\u0645\u0651\u064e\u0627 \u0646\u064e\u0630\u06e1\u0647\u064e\u0628\u064e\u0646\u0651\u064e \u0628\u0650\u0643\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064f\u0646\u062a\u064e\u0642\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Maka sungguh, sekiranya Kami mewafatkanmu (sebelum engkau mencapai kemenangan), maka sesungguhnya Kami akan tetap memberikan azab kepada mereka (di akhirat)"},{id:42,text:"\u0623\u064e\u0648\u06e1 \u0646\u064f\u0631\u0650\u064a\u064e\u0646\u0651\u064e\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0648\u064e\u0639\u064e\u062f\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0645\u0651\u064f\u0642\u06e1\u062a\u064e\u062f\u0650\u0631\u064f\u0648\u0646\u064e",translation:"atau Kami perlihatkan kepadamu (azab) yang telah Kami ancamkan kepada mereka.785) Maka sungguh, Kami berkuasa atas mereka"},{id:43,text:"\u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u0645\u06e1\u0633\u0650\u0643\u06e1 \u0628\u0650\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064f\u0648\u062d\u0650\u064a\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e\u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0670\u0637\u0656 \u0645\u0651\u064f\u0633\u06e1\u062a\u064e\u0642\u0650\u064a\u0645\u0656",translation:"Maka berpegang teguhlah engkau kepada (agama) yang telah diwahyukan kepadamu. Sungguh, engkau berada di jalan yang lurus"},{id:44,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0630\u0650\u0643\u06e1\u0631\u065e \u0644\u0651\u064e\u0643\u064e \u0648\u064e\u0644\u0650\u0642\u064e\u0648\u06e1\u0645\u0650\u0643\u064e\u06d6 \u0648\u064e\u0633\u064e\u0648\u06e1\u0641\u064e \u062a\u064f\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan sungguh, Alquran itu benar-benar suatu peringatan bagimu dan bagi kaummu, dan kelak kamu akan diminta pertanggungjawaban"},{id:45,text:"\u0648\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u06e1 \u0645\u064e\u0646\u06e1 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0643\u064e \u0645\u0650\u0646 \u0631\u0651\u064f\u0633\u064f\u0644\u0650\u0646\u064e\u0627\u0653 \u0623\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u0650 \u0621\u064e\u0627\u0644\u0650\u0647\u064e\u0629\u0657 \u064a\u064f\u0639\u06e1\u0628\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Dan tanyakanlah (Muhammad) kepada rasul-rasul Kami yang telah Kami utus sebelum engkau, \"Apakah Kami menentukan tuhan-tuhan selain (Allah) Yang Maha Pengasih untuk disembah"},{id:46,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0648\u064e\u0645\u064e\u0644\u064e\u0625\u0650\u064a\u0652\u0647\u0650\u06e6 \u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0631\u064e\u0633\u064f\u0648\u0644\u064f \u0631\u064e\u0628\u0651\u0650 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Dan sungguh, Kami telah mengutus Musa dengan membawa mukjizat-mukjizat Kami kepada Fir'aun dan pemuka-pemuka kaumnya. Maka dia (Musa) berkata, \"Sesungguhnya aku adalah utusan dari Tuhan seluruh alam"},{id:47,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627\u0653 \u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1\u0647\u064e\u0627 \u064a\u064e\u0636\u06e1\u062d\u064e\u0643\u064f\u0648\u0646\u064e",translation:"Maka ketika dia (Musa) datang kepada mereka membawa mukjizat-mukjizat Kami, seketika itu mereka menertawakannya"},{id:48,text:"\u0648\u064e\u0645\u064e\u0627 \u0646\u064f\u0631\u0650\u064a\u0647\u0650\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0621\u064e\u0627\u064a\u064e\u0629\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u0650\u064a\u064e \u0623\u064e\u0643\u06e1\u0628\u064e\u0631\u064f \u0645\u0650\u0646\u06e1 \u0623\u064f\u062e\u06e1\u062a\u0650\u0647\u064e\u0627\u06d6 \u0648\u064e\u0623\u064e\u062e\u064e\u0630\u06e1\u0646\u064e\u0670\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0631\u06e1\u062c\u0650\u0639\u064f\u0648\u0646\u064e",translation:"Dan tidaklah Kami perlihatkan suatu mukjizat kepada mereka kecuali (mukjizat itu) lebih besar dari mukjizat-mukjizat (yang sebelumnya). Dan Kami timpakan kepada mereka azab786) agar mereka kembali (ke jalan yang benar)"},{id:49,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e \u0671\u0644\u0633\u0651\u064e\u0627\u062d\u0650\u0631\u064f \u0671\u062f\u06e1\u0639\u064f \u0644\u064e\u0646\u064e\u0627 \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0628\u0650\u0645\u064e\u0627 \u0639\u064e\u0647\u0650\u062f\u064e \u0639\u0650\u0646\u062f\u064e\u0643\u064e \u0625\u0650\u0646\u0651\u064e\u0646\u064e\u0627 \u0644\u064e\u0645\u064f\u0647\u06e1\u062a\u064e\u062f\u064f\u0648\u0646\u064e",translation:"(Dan mereka berkata, \"Wahai pesihir!787) berdoalah kepada Tuhanmu untuk (melepaskan) kami sesuai dengan apa yang telah dijanjikan-Nya kepadamu; sesungguhnya kami (jika doamu dikabulkan) akan menjadi orang yang mendapat petunjuk"},{id:50,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0643\u064e\u0634\u064e\u0641\u06e1\u0646\u064e\u0627 \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0645\u06e1 \u064a\u064e\u0646\u0643\u064f\u062b\u064f\u0648\u0646\u064e",translation:"Maka ketika Kami hilangkan azab itu dari mereka, seketika itu (juga) mereka ingkar janji"},{id:51,text:"\u0648\u064e\u0646\u064e\u0627\u062f\u064e\u0649\u0670 \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064f \u0641\u0650\u064a \u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u06e6 \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0623\u064e\u0644\u064e\u064a\u06e1\u0633\u064e \u0644\u0650\u064a \u0645\u064f\u0644\u06e1\u0643\u064f \u0645\u0650\u0635\u06e1\u0631\u064e \u0648\u064e\u0647\u064e\u0670\u0630\u0650\u0647\u0650 \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u064f \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0645\u0650\u0646 \u062a\u064e\u062d\u06e1\u062a\u0650\u064a\u0653\u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064f\u0628\u06e1\u0635\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Dan Firaun berseru kepada kaumnya (seraya) berkata, \"Wahai kaumku! Bukankah kerajaan Mesir itu milikku dan (bukankah) sungai-sungai ini mengalir di bawahku; apakah kamu tidak melihat"},{id:52,text:"\u0623\u064e\u0645\u06e1 \u0623\u064e\u0646\u064e\u0627\u06e0 \u062e\u064e\u064a\u06e1\u0631\u065e \u0645\u0651\u0650\u0646\u06e1 \u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0647\u064f\u0648\u064e \u0645\u064e\u0647\u0650\u064a\u0646\u065e \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0643\u064e\u0627\u062f\u064f \u064a\u064f\u0628\u0650\u064a\u0646\u064f",translation:"Bukankah aku lebih baik dari orang (Musa) yang hina ini dan yang hampir tidak dapat menjelaskan (perkataannya)"},{id:53,text:"\u0641\u064e\u0644\u064e\u0648\u06e1\u0644\u064e\u0627\u0653 \u0623\u064f\u0644\u06e1\u0642\u0650\u064a\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0623\u064e\u0633\u06e1\u0648\u0650\u0631\u064e\u0629\u065e \u0645\u0651\u0650\u0646 \u0630\u064e\u0647\u064e\u0628\u064d \u0623\u064e\u0648\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e \u0645\u064e\u0639\u064e\u0647\u064f \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u064f \u0645\u064f\u0642\u06e1\u062a\u064e\u0631\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Maka mengapa dia (Musa) tidak dipakaikan gelang dari emas, atau malaikat datang bersama-sama dia untuk mengiringkannya"},{id:54,text:"\u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u062e\u064e\u0641\u0651\u064e \u0642\u064e\u0648\u06e1\u0645\u064e\u0647\u064f\u06e5 \u0641\u064e\u0623\u064e\u0637\u064e\u0627\u0639\u064f\u0648\u0647\u064f\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0642\u064e\u0648\u06e1\u0645\u0657\u0627 \u0641\u064e\u0670\u0633\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Maka (Firaun) dengan perkataan itu telah mempengaruhi kaumnya, sehingga mereka patuh kepadanya. Sungguh, mereka adalah kaum yang fasik"},{id:55,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627\u0653 \u0621\u064e\u0627\u0633\u064e\u0641\u064f\u0648\u0646\u064e\u0627 \u0671\u0646\u062a\u064e\u0642\u064e\u0645\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0641\u064e\u0623\u064e\u063a\u06e1\u0631\u064e\u0642\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0623\u064e\u062c\u06e1\u0645\u064e\u0639\u0650\u064a\u0646\u064e",translation:"Maka ketika mereka membuat Kami murka, Kami hukum mereka, lalu Kami tenggelamkan mereka semuanya (di laut)"},{id:56,text:"\u0641\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0633\u064e\u0644\u064e\u0641\u0657\u0627 \u0648\u064e\u0645\u064e\u062b\u064e\u0644\u0657\u0627 \u0644\u0651\u0650\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u0650\u064a\u0646\u064e",translation:"maka Kami jadikan mereka sebagai (kaum) terdahulu, dan pelajaran bagi orang-orang yang kemudian"},{id:57,text:"\u06de\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0636\u064f\u0631\u0650\u0628\u064e \u0671\u0628\u06e1\u0646\u064f \u0645\u064e\u0631\u06e1\u064a\u064e\u0645\u064e \u0645\u064e\u062b\u064e\u0644\u064b\u0627 \u0625\u0650\u0630\u064e\u0627 \u0642\u064e\u0648\u06e1\u0645\u064f\u0643\u064e \u0645\u0650\u0646\u06e1\u0647\u064f \u064a\u064e\u0635\u0650\u062f\u0651\u064f\u0648\u0646\u064e",translation:"Dan ketika putra Maryam (Isa) dijadikan perumpamaan, tiba-tiba kaummu (Suku Quraisy) bersorak karenanya"},{id:58,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0621\u064e\u0623\u064e\u0670\u0644\u0650\u0647\u064e\u062a\u064f\u0646\u064e\u0627 \u062e\u064e\u064a\u06e1\u0631\u064c \u0623\u064e\u0645\u06e1 \u0647\u064f\u0648\u064e\u06da \u0645\u064e\u0627 \u0636\u064e\u0631\u064e\u0628\u064f\u0648\u0647\u064f \u0644\u064e\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u062c\u064e\u062f\u064e\u0644\u064e\u06e2\u0627\u06da \u0628\u064e\u0644\u06e1 \u0647\u064f\u0645\u06e1 \u0642\u064e\u0648\u06e1\u0645\u064c \u062e\u064e\u0635\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Dan mereka berkata, \"Manakah yang lebih baik, tuhan-tuhan kami atau dia (Isa)?\" Mereka tidak memberikan (perumpamaan itu) kepadamu melainkan dengan maksud membantah saja; sebenarnya mereka adalah kaum yang suka bertengkar"},{id:59,text:"\u0625\u0650\u0646\u06e1 \u0647\u064f\u0648\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0628\u06e1\u062f\u064c \u0623\u064e\u0646\u06e1\u0639\u064e\u0645\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f \u0645\u064e\u062b\u064e\u0644\u0657\u0627 \u0644\u0651\u0650\u0628\u064e\u0646\u0650\u064a\u0653 \u0625\u0650\u0633\u06e1\u0631\u064e\u0640\u0670\u0653\u0621\u0650\u064a\u0644\u064e",translation:"Dia (Isa) tidak lain hanyalah seorang hamba yang Kami berikan nikmat (kenabian) kepadanya, dan Kami jadikan dia sebagai contoh bagi Bani Israil"},{id:60,text:"\u0648\u064e\u0644\u064e\u0648\u06e1 \u0646\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0644\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646\u0643\u064f\u0645 \u0645\u0651\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u0657 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u064a\u064e\u062e\u06e1\u0644\u064f\u0641\u064f\u0648\u0646\u064e",translation:"Dan sekiranya Kami menghendaki, niscaya ada di antara kamu yang Kami jadikan malaikat-malaikat (yang turun temurun) sebagai pengganti kamu di bumi"},{id:61,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0639\u0650\u0644\u06e1\u0645\u065e \u0644\u0651\u0650\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u0650 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0645\u06e1\u062a\u064e\u0631\u064f\u0646\u0651\u064e \u0628\u0650\u0647\u064e\u0627 \u0648\u064e\u0671\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0646\u0650\u06da \u0647\u064e\u0670\u0630\u064e\u0627 \u0635\u0650\u0631\u064e\u0670\u0637\u065e \u0645\u0651\u064f\u0633\u06e1\u062a\u064e\u0642\u0650\u064a\u0645\u065e",translation:"Dan sungguh, dia (Isa) benar-benar menjadi pertanda akan datangnya hari Kiamat. Karena itu, janganlah kamu ragu-ragu tentang (Kiamat) itu dan ikutilah Aku. Inilah jalan yang lurus"},{id:62,text:"\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0635\u064f\u062f\u0651\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u064f\u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0639\u064e\u062f\u064f\u0648\u0651\u065e \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u065e",translation:"Dan janganlah kamu sekali-kali dipalingkan oleh setan; sungguh, setan itu musuh yang nyata bagimu"},{id:63,text:"\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e \u0639\u0650\u064a\u0633\u064e\u0649\u0670 \u0628\u0650\u0671\u0644\u06e1\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0650 \u0642\u064e\u0627\u0644\u064e \u0642\u064e\u062f\u06e1 \u062c\u0650\u0626\u06e1\u062a\u064f\u0643\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u062d\u0650\u0643\u06e1\u0645\u064e\u0629\u0650 \u0648\u064e\u0644\u0650\u0623\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064e \u0644\u064e\u0643\u064f\u0645 \u0628\u064e\u0639\u06e1\u0636\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062a\u064e\u062e\u06e1\u062a\u064e\u0644\u0650\u0641\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0647\u0650\u06d6 \u0641\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u0650",translation:"(Dan ketika Isa datang membawa keterangan, dia berkata, \"Sungguh, aku datang kepadamu dengan membawa hikmah,789) dan untuk menjelaskan kepadamu sebagian dari apa yang kamu perselisihkan; maka bertakwalah kepada Allah dan taatlah kepadaku"},{id:64,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0647\u064f\u0648\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u06e1 \u0641\u064e\u0671\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0647\u064f\u06da \u0647\u064e\u0670\u0630\u064e\u0627 \u0635\u0650\u0631\u064e\u0670\u0637\u065e \u0645\u0651\u064f\u0633\u06e1\u062a\u064e\u0642\u0650\u064a\u0645\u065e",translation:"Sungguh, Allah, Dia Tuhanku dan Tuhanmu, maka sembahlah Dia. Ini adalah jalan yang lurus"},{id:65,text:"\u0641\u064e\u0671\u062e\u06e1\u062a\u064e\u0644\u064e\u0641\u064e \u0671\u0644\u06e1\u0623\u064e\u062d\u06e1\u0632\u064e\u0627\u0628\u064f \u0645\u0650\u0646\u06e2 \u0628\u064e\u064a\u06e1\u0646\u0650\u0647\u0650\u0645\u06e1\u06d6 \u0641\u064e\u0648\u064e\u064a\u06e1\u0644\u065e \u0644\u0651\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u064a\u064e\u0648\u06e1\u0645\u064d \u0623\u064e\u0644\u0650\u064a\u0645\u064d",translation:"Tetapi golongan-golongan (yang ada) saling berselisih di antara mereka; maka celakalah orang-orang yang zalim karena azab pada hari yang pedih (Kiamat)"},{id:66,text:"\u0647\u064e\u0644\u06e1 \u064a\u064e\u0646\u0638\u064f\u0631\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064e \u0623\u064e\u0646 \u062a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e\u0647\u064f\u0645 \u0628\u064e\u063a\u06e1\u062a\u064e\u0629\u0657 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0634\u06e1\u0639\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Apakah mereka hanya menunggu saja kedatangan hari Kiamat yang datang kepada mereka secara mendadak, sedang mereka tidak menyadarinya"},{id:67,text:"\u0671\u0644\u06e1\u0623\u064e\u062e\u0650\u0644\u0651\u064e\u0627\u0653\u0621\u064f \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0650\u06ed \u0628\u064e\u0639\u06e1\u0636\u064f\u0647\u064f\u0645\u06e1 \u0644\u0650\u0628\u064e\u0639\u06e1\u0636\u064d \u0639\u064e\u062f\u064f\u0648\u0651\u064c \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",translation:"Teman-teman karib pada hari itu saling bermusuhan satu sama lain, kecuali mereka yang bertakwa"},{id:68,text:"\u064a\u064e\u0670\u0639\u0650\u0628\u064e\u0627\u062f\u0650 \u0644\u064e\u0627 \u062e\u064e\u0648\u06e1\u0641\u064c \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e \u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u062d\u06e1\u0632\u064e\u0646\u064f\u0648\u0646\u064e",translation:"Wahai hamba-hamba-Ku! Tidak ada ketakutan bagimu pada hari itu, dan tidak pula kamu bersedih hati"},{id:69,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0645\u064f\u0633\u06e1\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"(Yaitu) orang-orang yang beriman kepada ayat-ayat Kami dan mereka berserah diri"},{id:70,text:"\u0671\u062f\u06e1\u062e\u064f\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u064e \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u064f\u0643\u064f\u0645\u06e1 \u062a\u064f\u062d\u06e1\u0628\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Masuklah kamu ke dalam surga, kamu dan pasanganmu akan digembirakan"},{id:71,text:"\u064a\u064f\u0637\u064e\u0627\u0641\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0628\u0650\u0635\u0650\u062d\u064e\u0627\u0641\u0656 \u0645\u0651\u0650\u0646 \u0630\u064e\u0647\u064e\u0628\u0656 \u0648\u064e\u0623\u064e\u0643\u06e1\u0648\u064e\u0627\u0628\u0656\u06d6 \u0648\u064e\u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u064e\u0627 \u062a\u064e\u0634\u06e1\u062a\u064e\u0647\u0650\u064a\u0647\u0650 \u0671\u0644\u06e1\u0623\u064e\u0646\u0641\u064f\u0633\u064f \u0648\u064e\u062a\u064e\u0644\u064e\u0630\u0651\u064f \u0671\u0644\u06e1\u0623\u064e\u0639\u06e1\u064a\u064f\u0646\u064f\u06d6 \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u0670\u0644\u0650\u062f\u064f\u0648\u0646\u064e",translation:"Kepada mereka diedarkan piring-piring dan gelas-gelas dari emas, dan di dalam surga itu terdapat apa yang diingini oleh hati dan segala yang sedap (dipandang) mata. Dan kamu kekal di dalamnya"},{id:72,text:"\u0648\u064e\u062a\u0650\u0644\u06e1\u0643\u064e \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u064f \u0671\u0644\u0651\u064e\u062a\u0650\u064a\u0653 \u0623\u064f\u0648\u0631\u0650\u062b\u06e1\u062a\u064f\u0645\u064f\u0648\u0647\u064e\u0627 \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan itulah surga yang diwariskan kepada kamu karena perbuatan yang telah kamu kerjakan"},{id:73,text:"\u0644\u064e\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u0641\u064e\u0670\u0643\u0650\u0647\u064e\u0629\u065e \u0643\u064e\u062b\u0650\u064a\u0631\u064e\u0629\u065e \u0645\u0651\u0650\u0646\u06e1\u0647\u064e\u0627 \u062a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f\u0648\u0646\u064e",translation:"Di dalam surga itu terdapat banyak buah-buahan untukmu yang sebagiannya kamu makan"},{id:74,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0645\u064f\u062c\u06e1\u0631\u0650\u0645\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u062e\u064e\u0670\u0644\u0650\u062f\u064f\u0648\u0646\u064e",translation:"Sungguh, orang-orang yang berdosa itu kekal di dalam azab neraka Jahanam"},{id:75,text:"\u0644\u064e\u0627 \u064a\u064f\u0641\u064e\u062a\u0651\u064e\u0631\u064f \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u0650 \u0645\u064f\u0628\u06e1\u0644\u0650\u0633\u064f\u0648\u0646\u064e",translation:"Tidak diringankan (azab) itu dari mereka, dan mereka berputus asa di dalamnya"},{id:76,text:"\u0648\u064e\u0645\u064e\u0627 \u0638\u064e\u0644\u064e\u0645\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0647\u064f\u0645\u064f \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dan tidaklah Kami menzalimi mereka, tetapi merekalah yang menzalimi diri mereka sendiri"},{id:77,text:"\u0648\u064e\u0646\u064e\u0627\u062f\u064e\u0648\u06e1\u0627\u0652 \u064a\u064e\u0670\u0645\u064e\u0670\u0644\u0650\u0643\u064f \u0644\u0650\u064a\u064e\u0642\u06e1\u0636\u0650 \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0631\u064e\u0628\u0651\u064f\u0643\u064e\u06d6 \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645 \u0645\u0651\u064e\u0640\u0670\u0643\u0650\u062b\u064f\u0648\u0646\u064e",translation:"Dan mereka berseru, \"Wahai (Malaikat) Malik! Biarlah Tuhanmu mematikan kami saja.\" Dia menjawab, \"Sungguh, kamu akan tetap tinggal (di neraka ini)"},{id:78,text:"\u0644\u064e\u0642\u064e\u062f\u06e1 \u062c\u0650\u0626\u06e1\u0646\u064e\u0670\u0643\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064e\u0643\u064f\u0645\u06e1 \u0644\u0650\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0643\u064e\u0670\u0631\u0650\u0647\u064f\u0648\u0646\u064e",translation:"Sungguh, Kami telah datang membawa kebenaran kepada kamu, tetapi kebanyakan di antara kamu benci pada kebenaran itu"},{id:79,text:"\u0623\u064e\u0645\u06e1 \u0623\u064e\u0628\u06e1\u0631\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0645\u06e1\u0631\u0657\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0645\u064f\u0628\u06e1\u0631\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Ataukah mereka telah merencanakan suatu tipu daya (jahat), maka sesungguhnya Kami telah berencana (mengatasi tipu daya mereka)"},{id:80,text:"\u0623\u064e\u0645\u06e1 \u064a\u064e\u062d\u06e1\u0633\u064e\u0628\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0651\u064e\u0627 \u0644\u064e\u0627 \u0646\u064e\u0633\u06e1\u0645\u064e\u0639\u064f \u0633\u0650\u0631\u0651\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0646\u064e\u062c\u06e1\u0648\u064e\u0649\u0670\u0647\u064f\u0645\u06da \u0628\u064e\u0644\u064e\u0649\u0670 \u0648\u064e\u0631\u064f\u0633\u064f\u0644\u064f\u0646\u064e\u0627 \u0644\u064e\u062f\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u064a\u064e\u0643\u06e1\u062a\u064f\u0628\u064f\u0648\u0646\u064e",translation:"Ataukah mereka mengira bahwa Kami tidak mendengar rahasia dan bisikan-bisikan mereka? Sebenarnya (Kami mendengar), dan utusan-utusan Kami (malaikat) selalu mencatat di sisi mereka"},{id:81,text:"\u0642\u064f\u0644\u06e1 \u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u0650 \u0648\u064e\u0644\u064e\u062f\u065e \u0641\u064e\u0623\u064e\u0646\u064e\u0627\u06e0 \u0623\u064e\u0648\u0651\u064e\u0644\u064f \u0671\u0644\u06e1\u0639\u064e\u0670\u0628\u0650\u062f\u0650\u064a\u0646\u064e",translation:"Katakanlah (Muhammad), \"Jika benar Tuhan Yang Maha Pengasih mempunyai anak, maka akulah orang yang mula-mula memuliakan (anak itu)"},{id:82,text:"\u0633\u064f\u0628\u06e1\u062d\u064e\u0670\u0646\u064e \u0631\u064e\u0628\u0651\u0650 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0631\u064e\u0628\u0651\u0650 \u0671\u0644\u06e1\u0639\u064e\u0631\u06e1\u0634\u0650 \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064e\u0635\u0650\u0641\u064f\u0648\u0646\u064e",translation:"Mahasuci Tuhan pemilik langit dan bumi, Tuhan pemilik Arasy, dari apa yang mereka sifatkan itu"},{id:83,text:"\u0641\u064e\u0630\u064e\u0631\u06e1\u0647\u064f\u0645\u06e1 \u064a\u064e\u062e\u064f\u0648\u0636\u064f\u0648\u0627\u0652 \u0648\u064e\u064a\u064e\u0644\u06e1\u0639\u064e\u0628\u064f\u0648\u0627\u0652 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064f\u0644\u064e\u0670\u0642\u064f\u0648\u0627\u0652 \u064a\u064e\u0648\u06e1\u0645\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u0648\u0639\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Maka biarkanlah mereka tenggelam (dalam kesesatan) dan bermain-main sampai mereka menemui hari yang dijanjikan kepada mereka"},{id:84,text:"\u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0625\u0650\u0644\u064e\u0670\u0647\u065e \u0648\u064e\u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0625\u0650\u0644\u064e\u0670\u0647\u065e\u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u062d\u064e\u0643\u0650\u064a\u0645\u064f \u0671\u0644\u06e1\u0639\u064e\u0644\u0650\u064a\u0645\u064f",translation:"Dan Dialah Tuhan (yang disembah) di langit dan Tuhan (yang disembah) di bumi, dan Dialah Yang Mahabijaksana, Maha Mengetahui"},{id:85,text:"\u0648\u064e\u062a\u064e\u0628\u064e\u0627\u0631\u064e\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0644\u064e\u0647\u064f\u06e5 \u0645\u064f\u0644\u06e1\u0643\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0648\u064e\u0639\u0650\u0646\u062f\u064e\u0647\u064f\u06e5 \u0639\u0650\u0644\u06e1\u0645\u064f \u0671\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u0650 \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u062a\u064f\u0631\u06e1\u062c\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Dan Mahasuci (Allah) yang memiliki kerajaan langit dan bumi, dan apa yang ada di antara keduanya; dan di sisi-Nyalah ilmu tentang hari Kiamat, dan hanya kepada-Nyalah kamu dikembalikan"},{id:86,text:"\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0645\u06e1\u0644\u0650\u0643\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650 \u0671\u0644\u0634\u0651\u064e\u0641\u064e\u0670\u0639\u064e\u0629\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646 \u0634\u064e\u0647\u0650\u062f\u064e \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan orang-orang yang menyeru kepada selain Allah tidak mendapat syafaat (pertolongan di akhirat); kecuali orang yang mengakui yang hak (tauhid) dan mereka meyakini"},{id:87,text:"\u0648\u064e\u0644\u064e\u0626\u0650\u0646 \u0633\u064e\u0623\u064e\u0644\u06e1\u062a\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u0646\u06e1 \u062e\u064e\u0644\u064e\u0642\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06d6 \u0641\u064e\u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u064a\u064f\u0624\u06e1\u0641\u064e\u0643\u064f\u0648\u0646\u064e",translation:"Dan jika engkau bertanya kepada mereka, siapakah yang menciptakan mereka, niscaya mereka menjawab, Allah; jadi bagaimana mereka dapat dipalingkan (dari menyembah Allah)"},{id:88,text:"\u0648\u064e\u0642\u0650\u064a\u0644\u0650\u0647\u0650\u06e6 \u064a\u064e\u0670\u0631\u064e\u0628\u0651\u0650 \u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650 \u0642\u064e\u0648\u06e1\u0645\u065e \u0644\u0651\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"dan (Allah mengetahui) ucapannya (Muhammad), \"Ya Tuhanku, sesungguhnya mereka itu adalah kaum yang tidak beriman"},{id:89,text:"\u0641\u064e\u0671\u0635\u06e1\u0641\u064e\u062d\u06e1 \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0648\u064e\u0642\u064f\u0644\u06e1 \u0633\u064e\u0644\u064e\u0670\u0645\u065e\u06da \u0641\u064e\u0633\u064e\u0648\u06e1\u0641\u064e \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Maka berpalinglah dari mereka dan katakanlah, \"Salam (selamat tinggal).\" Kelak mereka akan mengetahui (nasib mereka yang buruk)"}]},{id:44,name:"\u0627\u0644\u062f\u062e\u0627\u0646",transliteration:"Ad-Dukhan",translation:"Kabut",type:"meccan",total_verses:59,verses:[{id:1,text:"\u062d\u0645\u0653",translation:"\u1e24\u0101 M\u012bm"},{id:2,text:"\u0648\u064e\u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0671\u0644\u06e1\u0645\u064f\u0628\u0650\u064a\u0646\u0650",translation:"Demi Kitab (Alquran) yang jelas"},{id:3,text:"\u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f \u0641\u0650\u064a \u0644\u064e\u064a\u06e1\u0644\u064e\u0629\u0656 \u0645\u0651\u064f\u0628\u064e\u0670\u0631\u064e\u0643\u064e\u0629\u064d\u06da \u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0645\u064f\u0646\u0630\u0650\u0631\u0650\u064a\u0646\u064e",translation:"(Sesungguhnya Kami menurunkannya pada malam yang diberkahi.791) Sungguh, Kamilah yang memberi peringatan"},{id:4,text:"\u0641\u0650\u064a\u0647\u064e\u0627 \u064a\u064f\u0641\u06e1\u0631\u064e\u0642\u064f \u0643\u064f\u0644\u0651\u064f \u0623\u064e\u0645\u06e1\u0631\u064d \u062d\u064e\u0643\u0650\u064a\u0645\u064d",translation:"Pada (malam itu) dijelaskan segala urusan yang penuh hikmah"},{id:5,text:"\u0623\u064e\u0645\u06e1\u0631\u0657\u0627 \u0645\u0651\u0650\u0646\u06e1 \u0639\u0650\u0646\u062f\u0650\u0646\u064e\u0627\u0653\u06da \u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0645\u064f\u0631\u06e1\u0633\u0650\u0644\u0650\u064a\u0646\u064e",translation:"(yaitu) urusan dari sisi Kami. Sungguh, Kamilah yang mengutus rasul-rasul"},{id:6,text:"\u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u0657 \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064e\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0647\u064f\u0648\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u0650\u064a\u0639\u064f \u0671\u0644\u06e1\u0639\u064e\u0644\u0650\u064a\u0645\u064f",translation:"sebagai rahmat dari Tuhanmu. Sungguh, Dia Maha Mendengar, Maha Mengetahui"},{id:7,text:"\u0631\u064e\u0628\u0651\u0650 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u064e\u0627\u0653\u06d6 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645 \u0645\u0651\u064f\u0648\u0642\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Tuhan (yang memelihara) langit dan bumi dan apa yang ada di antara keduanya; jika kamu orang-orang yang meyakini"},{id:8,text:"\u0644\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u064a\u064f\u062d\u06e1\u064a\u0650\u06e6 \u0648\u064e\u064a\u064f\u0645\u0650\u064a\u062a\u064f\u06d6 \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u06e1 \u0648\u064e\u0631\u064e\u0628\u0651\u064f \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0626\u0650\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",translation:"Tidak ada tuhan selain Dia, Dia yang menghidupkan dan mematikan. (Dialah) Tuhanmu dan Tuhan nenek moyangmu dahulu"},{id:9,text:"\u0628\u064e\u0644\u06e1 \u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0634\u064e\u0643\u0651\u0656 \u064a\u064e\u0644\u06e1\u0639\u064e\u0628\u064f\u0648\u0646\u064e",translation:"Tetapi mereka dalam keraguan, mereka bermain-main"},{id:10,text:"\u0641\u064e\u0671\u0631\u06e1\u062a\u064e\u0642\u0650\u0628\u06e1 \u064a\u064e\u0648\u06e1\u0645\u064e \u062a\u064e\u0623\u06e1\u062a\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u064f \u0628\u0650\u062f\u064f\u062e\u064e\u0627\u0646\u0656 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u0656",translation:"Maka tunggulah pada hari ketika langit membawa kabut yang tampak jelas"},{id:11,text:"\u064a\u064e\u063a\u06e1\u0634\u064e\u0649 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e\u06d6 \u0647\u064e\u0670\u0630\u064e\u0627 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u065e",translation:"yang meliputi manusia. Inilah azab yang pedih"},{id:12,text:"\u0631\u0651\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0671\u0643\u06e1\u0634\u0650\u0641\u06e1 \u0639\u064e\u0646\u0651\u064e\u0627 \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0625\u0650\u0646\u0651\u064e\u0627 \u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"(Mereka berdoa), \"Ya Tuhan kami, lenyapkanlah azab itu dari kami. Sungguh, kami akan beriman"},{id:13,text:"\u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0630\u0651\u0650\u0643\u06e1\u0631\u064e\u0649\u0670 \u0648\u064e\u0642\u064e\u062f\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u06e1 \u0631\u064e\u0633\u064f\u0648\u0644\u065e \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u065e",translation:"Bagaimana mereka dapat menerima peringatan, padahal (sebelumnya pun) seorang Rasul telah datang memberi penjelasan kepada mereka"},{id:14,text:"\u062b\u064f\u0645\u0651\u064e \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u06e1\u0627\u0652 \u0639\u064e\u0646\u06e1\u0647\u064f \u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0645\u064f\u0639\u064e\u0644\u0651\u064e\u0645\u065e \u0645\u0651\u064e\u062c\u06e1\u0646\u064f\u0648\u0646\u064c",translation:"kemudian mereka berpaling darinya dan berkata, \"Dia itu orang yang menerima ajaran (dari orang lain) dan orang gila"},{id:15,text:"\u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064e\u0627\u0634\u0650\u0641\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627\u06da \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0639\u064e\u0627\u0653\u0626\u0650\u062f\u064f\u0648\u0646\u064e",translation:"Sungguh, (kalau) Kami melenyapkan azab itu sedikit saja, tentu kamu akan kembali (ingkar)"},{id:16,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u0646\u064e\u0628\u06e1\u0637\u0650\u0634\u064f \u0671\u0644\u06e1\u0628\u064e\u0637\u06e1\u0634\u064e\u0629\u064e \u0671\u0644\u06e1\u0643\u064f\u0628\u06e1\u0631\u064e\u0649\u0670\u0653 \u0625\u0650\u0646\u0651\u064e\u0627 \u0645\u064f\u0646\u062a\u064e\u0642\u0650\u0645\u064f\u0648\u0646\u064e",translation:"(Ingatlah) pada hari (ketika) Kami menghantam mereka dengan keras.795) Kami pasti memberi balasan"},{id:17,text:"\u06de\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0641\u064e\u062a\u064e\u0646\u0651\u064e\u0627 \u0642\u064e\u0628\u06e1\u0644\u064e\u0647\u064f\u0645\u06e1 \u0642\u064e\u0648\u06e1\u0645\u064e \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0648\u064e\u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u06e1 \u0631\u064e\u0633\u064f\u0648\u0644\u065e \u0643\u064e\u0631\u0650\u064a\u0645\u064c",translation:"Dan sungguh, sebelum mereka, Kami benar-benar telah menguji kaum Fir'aun dan telah datang kepada mereka seorang Rasul yang mulia"},{id:18,text:"\u0623\u064e\u0646\u06e1 \u0623\u064e\u062f\u0651\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0639\u0650\u0628\u064e\u0627\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0643\u064f\u0645\u06e1 \u0631\u064e\u0633\u064f\u0648\u0644\u064c \u0623\u064e\u0645\u0650\u064a\u0646\u065e",translation:"(dengan berkata), \"Serahkanlah kepadaku hamba-hamba Allah (Bani Israil). Sesungguhnya aku adalah utusan (Allah) yang dapat kamu percaya"},{id:19,text:"\u0648\u064e\u0623\u064e\u0646 \u0644\u0651\u064e\u0627 \u062a\u064e\u0639\u06e1\u0644\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0621\u064e\u0627\u062a\u0650\u064a\u0643\u064f\u0645 \u0628\u0650\u0633\u064f\u0644\u06e1\u0637\u064e\u0670\u0646\u0656 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u0656",translation:"dan jangalah kamu menyombongkan diri terhadap Allah. Sungguh, aku datang kepadamu dengan membawa bukti yang nyata"},{id:20,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u0650\u064a \u0639\u064f\u0630\u06e1\u062a\u064f \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1 \u0623\u064e\u0646 \u062a\u064e\u0631\u06e1\u062c\u064f\u0645\u064f\u0648\u0646\u0650",translation:"Dan sesungguhnya aku berlindung kepada Tuhanku dan Tuhanmu, dari ancamanmu untuk merajamku"},{id:21,text:"\u0648\u064e\u0625\u0650\u0646 \u0644\u0651\u064e\u0645\u06e1 \u062a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0627\u0652 \u0644\u0650\u064a \u0641\u064e\u0671\u0639\u06e1\u062a\u064e\u0632\u0650\u0644\u064f\u0648\u0646\u0650",translation:"dan jika kamu tidak beriman kepadaku, maka biarkanlah aku (memimpin Bani Israil)"},{id:22,text:"\u0641\u064e\u062f\u064e\u0639\u064e\u0627 \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u0646\u0651\u064e \u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650 \u0642\u064e\u0648\u06e1\u0645\u065e \u0645\u0651\u064f\u062c\u06e1\u0631\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Kemudian dia (Musa) berdoa kepada Tuhannya, \"Sungguh, mereka ini adalah kaum yang berdosa (segerakanlah azab kepada mereka)"},{id:23,text:"\u0641\u064e\u0623\u064e\u0633\u06e1\u0631\u0650 \u0628\u0650\u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a \u0644\u064e\u064a\u06e1\u0644\u064b\u0627 \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645 \u0645\u0651\u064f\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0646\u064e",translation:"(Allah berfirman), \"Karena itu berjalanlah dengan hamba-hamba-Ku pada malam hari, sesungguhnya kamu akan dikejar"},{id:24,text:"\u0648\u064e\u0671\u062a\u06e1\u0631\u064f\u0643\u0650 \u0671\u0644\u06e1\u0628\u064e\u062d\u06e1\u0631\u064e \u0631\u064e\u0647\u06e1\u0648\u064b\u0627\u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u062c\u064f\u0646\u062f\u065e \u0645\u0651\u064f\u063a\u06e1\u0631\u064e\u0642\u064f\u0648\u0646\u064e",translation:"dan biarkanlah laut itu terbelah. Sesungguhnya mereka bala tentara yang akan ditenggelamkan"},{id:25,text:"\u0643\u064e\u0645\u06e1 \u062a\u064e\u0631\u064e\u0643\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0656 \u0648\u064e\u0639\u064f\u064a\u064f\u0648\u0646\u0656",translation:"Betapa banyak taman-taman dan mata air-mata air yang mereka tinggalkan"},{id:26,text:"\u0648\u064e\u0632\u064f\u0631\u064f\u0648\u0639\u0656 \u0648\u064e\u0645\u064e\u0642\u064e\u0627\u0645\u0656 \u0643\u064e\u0631\u0650\u064a\u0645\u0656",translation:"juga kebun-kebun serta tempat-tempat kediaman yang indah"},{id:27,text:"\u0648\u064e\u0646\u064e\u0639\u06e1\u0645\u064e\u0629\u0656 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0641\u064e\u0670\u0643\u0650\u0647\u0650\u064a\u0646\u064e",translation:"dan kesenangan-kesenangan yang dapat mereka nikmati di sana"},{id:28,text:"\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e\u06d6 \u0648\u064e\u0623\u064e\u0648\u06e1\u0631\u064e\u062b\u06e1\u0646\u064e\u0670\u0647\u064e\u0627 \u0642\u064e\u0648\u06e1\u0645\u064b\u0627 \u0621\u064e\u0627\u062e\u064e\u0631\u0650\u064a\u0646\u064e",translation:"demikianlah, dan Kami wariskan (semua) itu kepada kaum yang lain"},{id:29,text:"\u0641\u064e\u0645\u064e\u0627 \u0628\u064e\u0643\u064e\u062a\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u064f \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064f \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0645\u064f\u0646\u0638\u064e\u0631\u0650\u064a\u0646\u064e",translation:"Maka langit dan bumi tidak menangisi mereka dan mereka pun tidak diberi penangguhan waktu"},{id:30,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0646\u064e\u062c\u0651\u064e\u064a\u06e1\u0646\u064e\u0627 \u0628\u064e\u0646\u0650\u064a\u0653 \u0625\u0650\u0633\u06e1\u0631\u064e\u0640\u0670\u0653\u0621\u0650\u064a\u0644\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0671\u0644\u06e1\u0645\u064f\u0647\u0650\u064a\u0646\u0650",translation:"Dan sungguh, telah Kami selamatkan Bani Israil dari siksaan yang menghinakan"},{id:31,text:"\u0645\u0650\u0646 \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0627\u0644\u0650\u064a\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0633\u06e1\u0631\u0650\u0641\u0650\u064a\u0646\u064e",translation:"dari (siksaan) Fir'aun, sungguh, dia itu orang yang sombong, termasuk orang-orang yang melampaui batas"},{id:32,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0650 \u0671\u062e\u06e1\u062a\u064e\u0631\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0639\u0650\u0644\u06e1\u0645\u064d \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Dan sungguh, Kami pilih mereka (Bani Israil) dengan ilmu (Kami) di atas semua bangsa (pada masa itu)"},{id:33,text:"\u0648\u064e\u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u0653\u064a\u064e\u0670\u062a\u0650 \u0645\u064e\u0627 \u0641\u0650\u064a\u0647\u0650 \u0628\u064e\u0644\u064e\u0640\u0670\u0653\u0624\u065e\u0627\u0652 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u064c",translation:"Dan telah Kami berikan kepada mereka di antara tanda-tanda (kebesaran Kami) sesuatu yang di dalamnya terdapat nikmat yang nyata"},{id:34,text:"\u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650 \u0644\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e",translation:"Sesungguhnya mereka (kaum musyrik) itu pasti akan berkata"},{id:35,text:"\u0625\u0650\u0646\u06e1 \u0647\u0650\u064a\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0648\u06e1\u062a\u064e\u062a\u064f\u0646\u064e\u0627 \u0671\u0644\u06e1\u0623\u064f\u0648\u0644\u064e\u0649\u0670 \u0648\u064e\u0645\u064e\u0627 \u0646\u064e\u062d\u06e1\u0646\u064f \u0628\u0650\u0645\u064f\u0646\u0634\u064e\u0631\u0650\u064a\u0646\u064e",translation:"Tidak ada kematian selain kematian di dunia ini. Dan kami tidak akan dibangkitkan"},{id:36,text:"\u0641\u064e\u0623\u06e1\u062a\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u0628\u064e\u0627\u0653\u0626\u0650\u0646\u064e\u0627\u0653 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0635\u064e\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e",translation:"maka hadirkanlah (kembali) nenek moyang kami jika kamu orang yang benar"},{id:37,text:"\u0623\u064e\u0647\u064f\u0645\u06e1 \u062e\u064e\u064a\u06e1\u0631\u064c \u0623\u064e\u0645\u06e1 \u0642\u064e\u0648\u06e1\u0645\u064f \u062a\u064f\u0628\u0651\u064e\u0639\u0656 \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u0645\u06e1 \u0623\u064e\u0647\u06e1\u0644\u064e\u0643\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0645\u064f\u062c\u06e1\u0631\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Apakah mereka (kaum musyrikin) yang lebih baik atau kaum Tubba',798) dan orang-orang sebelum mereka yang telah Kami binasakan karena mereka adalah orang-orang yang sungguh berdosa"},{id:38,text:"\u0648\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u06e1\u0646\u064e\u0627 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0644\u064e\u0670\u0639\u0650\u0628\u0650\u064a\u0646\u064e",translation:"Dan tidaklah Kami bermain-main menciptakan langit dan bumi dan apa yang ada di antara keduanya"},{id:39,text:"\u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Tidaklah Kami ciptakan keduanya melainkan dengan hak (benar), tetapi kebanyakan mereka tidak mengetahui"},{id:40,text:"\u0625\u0650\u0646\u0651\u064e \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0641\u064e\u0635\u06e1\u0644\u0650 \u0645\u0650\u064a\u0642\u064e\u0670\u062a\u064f\u0647\u064f\u0645\u06e1 \u0623\u064e\u062c\u06e1\u0645\u064e\u0639\u0650\u064a\u0646\u064e",translation:"Sungguh, hari keputusan (hari Kiamat) adalah waktu yang dijanjikan bagi mereka semuanya"},{id:41,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u0644\u064e\u0627 \u064a\u064f\u063a\u06e1\u0646\u0650\u064a \u0645\u064e\u0648\u06e1\u0644\u064b\u0649 \u0639\u064e\u0646 \u0645\u0651\u064e\u0648\u06e1\u0644\u0657\u0649 \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u06e1 \u064a\u064f\u0646\u0635\u064e\u0631\u064f\u0648\u0646\u064e",translation:"(yaitu) pada hari (ketika) seorang teman sama sekali tidak dapat memberi manfaat kepada teman lainnya, dan mereka tidak akan mendapat pertolongan"},{id:42,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646 \u0631\u0651\u064e\u062d\u0650\u0645\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0671\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",translation:"kecuali orang yang diberi rahmat oleh Allah. Sungguh, Dia Mahaperkasa, Maha Penyayang"},{id:43,text:"\u0625\u0650\u0646\u0651\u064e \u0634\u064e\u062c\u064e\u0631\u064e\u062a\u064e \u0671\u0644\u0632\u0651\u064e\u0642\u0651\u064f\u0648\u0645\u0650",translation:"Sungguh pohon zaqq\u016bm itu"},{id:44,text:"\u0637\u064e\u0639\u064e\u0627\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u062b\u0650\u064a\u0645\u0650",translation:"makanan bagi orang yang banyak dosa"},{id:45,text:"\u0643\u064e\u0671\u0644\u06e1\u0645\u064f\u0647\u06e1\u0644\u0650 \u064a\u064e\u063a\u06e1\u0644\u0650\u064a \u0641\u0650\u064a \u0671\u0644\u06e1\u0628\u064f\u0637\u064f\u0648\u0646\u0650",translation:"Seperti cairan tembaga yang mendidih di dalam perut"},{id:46,text:"\u0643\u064e\u063a\u064e\u0644\u06e1\u064a\u0650 \u0671\u0644\u06e1\u062d\u064e\u0645\u0650\u064a\u0645\u0650",translation:"seperti mendidihnya air yang sangat panas"},{id:47,text:"\u062e\u064f\u0630\u064f\u0648\u0647\u064f \u0641\u064e\u0671\u0639\u06e1\u062a\u0650\u0644\u064f\u0648\u0647\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0633\u064e\u0648\u064e\u0627\u0653\u0621\u0650 \u0671\u0644\u06e1\u062c\u064e\u062d\u0650\u064a\u0645\u0650",translation:"Peganglah dia, kemudian seretlah dia sampai ke tengah-tengah neraka"},{id:48,text:"\u062b\u064f\u0645\u0651\u064e \u0635\u064f\u0628\u0651\u064f\u0648\u0627\u0652 \u0641\u064e\u0648\u06e1\u0642\u064e \u0631\u064e\u0623\u06e1\u0633\u0650\u0647\u0650\u06e6 \u0645\u0650\u0646\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0671\u0644\u06e1\u062d\u064e\u0645\u0650\u064a\u0645\u0650",translation:"kemudian tuangkanlah di atas kepalanya azab (dari) air yang sangat panas"},{id:49,text:"\u0630\u064f\u0642\u06e1 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0623\u064e\u0646\u062a\u064e \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0671\u0644\u06e1\u0643\u064e\u0631\u0650\u064a\u0645\u064f",translation:"Rasakanlah, sesungguhnya engkau benar-benar orang yang perkasa lagi mulia (di tengah kaummu)"},{id:50,text:"\u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6 \u062a\u064e\u0645\u06e1\u062a\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Sungguh, inilah azab yang dahulu kamu ragukan"},{id:51,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0645\u064e\u0642\u064e\u0627\u0645\u064d \u0623\u064e\u0645\u0650\u064a\u0646\u0656",translation:"Sungguh, orang-orang yang bertakwa berada dalam tempat yang aman"},{id:52,text:"\u0641\u0650\u064a \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0656 \u0648\u064e\u0639\u064f\u064a\u064f\u0648\u0646\u0656",translation:"(yaitu) di dalam taman-taman dan mata air-mata air"},{id:53,text:"\u064a\u064e\u0644\u06e1\u0628\u064e\u0633\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u0633\u064f\u0646\u062f\u064f\u0633\u0656 \u0648\u064e\u0625\u0650\u0633\u06e1\u062a\u064e\u0628\u06e1\u0631\u064e\u0642\u0656 \u0645\u0651\u064f\u062a\u064e\u0642\u064e\u0670\u0628\u0650\u0644\u0650\u064a\u0646\u064e",translation:"mereka memakai sutera yang halus dan sutera yang tebal, (duduk) berhadapan"},{id:54,text:"\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0648\u064e\u0632\u064e\u0648\u0651\u064e\u062c\u06e1\u0646\u064e\u0670\u0647\u064f\u0645 \u0628\u0650\u062d\u064f\u0648\u0631\u064d \u0639\u0650\u064a\u0646\u0656",translation:"demikianlah, kemudian Kami berikan kepada mereka pasangan bidadari yang bermata indah"},{id:55,text:"\u064a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0641\u064e\u0670\u0643\u0650\u0647\u064e\u0629\u064d \u0621\u064e\u0627\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Di dalamnya mereka dapat meminta segala macam buah-buahan dengan aman dan tenteram"},{id:56,text:"\u0644\u064e\u0627 \u064a\u064e\u0630\u064f\u0648\u0642\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u064e\u0629\u064e \u0671\u0644\u06e1\u0623\u064f\u0648\u0644\u064e\u0649\u0670\u06d6 \u0648\u064e\u0648\u064e\u0642\u064e\u0649\u0670\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0671\u0644\u06e1\u062c\u064e\u062d\u0650\u064a\u0645\u0650",translation:"mereka tidak akan merasakan mati di dalamnya, selain kematian pertama (di dunia). Allah melindungi mereka dari azab neraka"},{id:57,text:"\u0641\u064e\u0636\u06e1\u0644\u0657\u0627 \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064e\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0641\u064e\u0648\u06e1\u0632\u064f \u0671\u0644\u06e1\u0639\u064e\u0638\u0650\u064a\u0645\u064f",translation:"itu merupakan karunia dari Tuhanmu. Demikian itulah kemenangan yang agung"},{id:58,text:"\u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0633\u0651\u064e\u0631\u06e1\u0646\u064e\u0670\u0647\u064f \u0628\u0650\u0644\u0650\u0633\u064e\u0627\u0646\u0650\u0643\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Sungguh, Kami mudahkan Alquran itu dengan bahasamu agar mereka mendapat pelajaran"},{id:59,text:"\u0641\u064e\u0671\u0631\u06e1\u062a\u064e\u0642\u0650\u0628\u06e1 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645 \u0645\u0651\u064f\u0631\u06e1\u062a\u064e\u0642\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Maka tunggulah; sungguh, mereka itu (juga sedang) menunggu"}]},{id:45,name:"\u0627\u0644\u062c\u0627\u062b\u064a\u0629",transliteration:"Al-Jathiyah",translation:"Yang Bertekuk Lutut",type:"meccan",total_verses:37,verses:[{id:1,text:"\u062d\u0645\u0653",translation:"\u1e24\u0101 M\u012bm"},{id:2,text:"\u062a\u064e\u0646\u0632\u0650\u064a\u0644\u064f \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0645\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u0650 \u0671\u0644\u06e1\u062d\u064e\u0643\u0650\u064a\u0645\u0650",translation:"Kitab (ini) diturunkan dari Allah Yang Mahaperkasa, Mahabijaksana"},{id:3,text:"\u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0644\u064e\u0623\u0653\u064a\u064e\u0670\u062a\u0656 \u0644\u0651\u0650\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Sungguh, pada langit dan bumi benar-benar terdapat tanda-tanda (kebesaran Allah) bagi orang-orang mukmin"},{id:4,text:"\u0648\u064e\u0641\u0650\u064a \u062e\u064e\u0644\u06e1\u0642\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0628\u064f\u062b\u0651\u064f \u0645\u0650\u0646 \u062f\u064e\u0627\u0653\u0628\u0651\u064e\u0629\u064d \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u065e \u0644\u0651\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064f\u0648\u0642\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Dan pada penciptaan dirimu dan pada makhluk bergerak yang bernyawa yang bertebaran (di bumi) terdapat tanda-tanda (kebesaran Allah) untuk kaum yang meyakini"},{id:5,text:"\u0648\u064e\u0671\u062e\u06e1\u062a\u0650\u0644\u064e\u0670\u0641\u0650 \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u0650 \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0645\u0650\u0646 \u0631\u0651\u0650\u0632\u06e1\u0642\u0656 \u0641\u064e\u0623\u064e\u062d\u06e1\u064a\u064e\u0627 \u0628\u0650\u0647\u0650 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0628\u064e\u0639\u06e1\u062f\u064e \u0645\u064e\u0648\u06e1\u062a\u0650\u0647\u064e\u0627 \u0648\u064e\u062a\u064e\u0635\u06e1\u0631\u0650\u064a\u0641\u0650 \u0671\u0644\u0631\u0651\u0650\u064a\u064e\u0670\u062d\u0650 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u065e \u0644\u0651\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e",translation:"dan pada pergantian malam dan siang, dan hujan yang diturunkan Allah dari langit, lalu dengan (air hujan) itu dihidupkan-Nya bumi setelah mati (kering); dan pada perkisaran angin terdapat pula tanda-tanda (kebesaran Allah) bagi kaum yang mengerti"},{id:6,text:"\u062a\u0650\u0644\u06e1\u0643\u064e \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0646\u064e\u062a\u06e1\u0644\u064f\u0648\u0647\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650\u06d6 \u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u062d\u064e\u062f\u0650\u064a\u062b\u0650\u06ed \u0628\u064e\u0639\u06e1\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0647\u0650\u06e6 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Itulah ayat-ayat Allah yang Kami bacakan kepadamu dengan sebenarnya; maka dengan perkataan mana lagi mereka akan beriman setelah Allah dan ayat-ayat-Nya"},{id:7,text:"\u0648\u064e\u064a\u06e1\u0644\u065e \u0644\u0651\u0650\u0643\u064f\u0644\u0651\u0650 \u0623\u064e\u0641\u0651\u064e\u0627\u0643\u064d \u0623\u064e\u062b\u0650\u064a\u0645\u0656",translation:"Celakalah bagi setiap orang yang banyak berdusta lagi banyak berdosa"},{id:8,text:"\u064a\u064e\u0633\u06e1\u0645\u064e\u0639\u064f \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064f\u062a\u06e1\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0635\u0650\u0631\u0651\u064f \u0645\u064f\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u0650\u0631\u0657\u0627 \u0643\u064e\u0623\u064e\u0646 \u0644\u0651\u064e\u0645\u06e1 \u064a\u064e\u0633\u06e1\u0645\u064e\u0639\u06e1\u0647\u064e\u0627\u06d6 \u0641\u064e\u0628\u064e\u0634\u0651\u0650\u0631\u06e1\u0647\u064f \u0628\u0650\u0639\u064e\u0630\u064e\u0627\u0628\u064d \u0623\u064e\u0644\u0650\u064a\u0645\u0656",translation:"(yaitu) orang yang mendengar ayat-ayat Allah ketika dibacakan kepadanya, namun dia tetap menyombongkan diri seakan-akan dia tidak mendengarnya. Maka peringatkanlah dia dengan azab yang pedih"},{id:9,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0639\u064e\u0644\u0650\u0645\u064e \u0645\u0650\u0646\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0634\u064e\u064a\u06e1\u0640\u0654\u064b\u0627 \u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064e\u0647\u064e\u0627 \u0647\u064f\u0632\u064f\u0648\u064b\u0627\u06da \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u065e \u0645\u0651\u064f\u0647\u0650\u064a\u0646\u065e",translation:"Dan apabila dia mengetahui sedikit tentang ayat-ayat Kami, maka (ayat-ayat itu) dijadikan olok-olok. Merekalah yang akan menerima azab yang menghinakan"},{id:10,text:"\u0645\u0651\u0650\u0646 \u0648\u064e\u0631\u064e\u0627\u0653\u0626\u0650\u0647\u0650\u0645\u06e1 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064f\u06d6 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u063a\u06e1\u0646\u0650\u064a \u0639\u064e\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064f\u0648\u0627\u0652 \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u0645\u064e\u0627 \u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0648\u06e1\u0644\u0650\u064a\u064e\u0627\u0653\u0621\u064e\u06d6 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u064c",translation:"Di hadapan mereka neraka Jahanam, dan tidak akan berguna bagi mereka sedikit pun apa yang telah mereka kerjakan, dan tidak pula (bermanfaat) apa yang mereka jadikan sebagai pelindung-pelindung (mereka) selain Allah. Dan mereka akan mendapat azab yang besar"},{id:11,text:"\u0647\u064e\u0670\u0630\u064e\u0627 \u0647\u064f\u062f\u0657\u0649\u06d6 \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u065e \u0645\u0651\u0650\u0646 \u0631\u0651\u0650\u062c\u06e1\u0632\u064d \u0623\u064e\u0644\u0650\u064a\u0645\u064c",translation:"Ini (Alquran) adalah petunjuk. Dan orang-orang yang mengingkari ayat-ayat Tuhannya, mereka akan mendapat azab berupa siksaan yang sangat pedih"},{id:12,text:"\u06de\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0633\u064e\u062e\u0651\u064e\u0631\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0628\u064e\u062d\u06e1\u0631\u064e \u0644\u0650\u062a\u064e\u062c\u06e1\u0631\u0650\u064a\u064e \u0671\u0644\u06e1\u0641\u064f\u0644\u06e1\u0643\u064f \u0641\u0650\u064a\u0647\u0650 \u0628\u0650\u0623\u064e\u0645\u06e1\u0631\u0650\u0647\u0650\u06e6 \u0648\u064e\u0644\u0650\u062a\u064e\u0628\u06e1\u062a\u064e\u063a\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0641\u064e\u0636\u06e1\u0644\u0650\u0647\u0650\u06e6 \u0648\u064e\u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u0634\u06e1\u0643\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Allah lah yang menundukkan laut untukmu agar kapal-kapal dapat berlayar di atasnya dengan perintah-Nya, dan agar kamu dapat mencari sebagian karunia-Nya, dan agar kamu bersyukur"},{id:13,text:"\u0648\u064e\u0633\u064e\u062e\u0651\u064e\u0631\u064e \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u062c\u064e\u0645\u0650\u064a\u0639\u0657\u0627 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u06da \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0623\u0653\u064a\u064e\u0670\u062a\u0656 \u0644\u0651\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064e\u062a\u064e\u0641\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan Dia menundukkan apa yang ada di langit dan apa yang ada di bumi untukmu semuanya (sebagai rahmat) dari-Nya. Sungguh, dalam hal yang demikian itu benar-benar terdapat tanda-tanda (kebesaran Allah) bagi orang-orang yang berpikir"},{id:14,text:"\u0642\u064f\u0644 \u0644\u0651\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u063a\u06e1\u0641\u0650\u0631\u064f\u0648\u0627\u0652 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u0631\u06e1\u062c\u064f\u0648\u0646\u064e \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u0650\u064a\u064e\u062c\u06e1\u0632\u0650\u064a\u064e \u0642\u064e\u0648\u06e1\u0645\u064e\u06e2\u0627 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0643\u06e1\u0633\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Katakanlah (Muhammad) kepada orang-orang yang beriman, hendaklah mereka memaafkan orang-orang yang tidak takut akan hari-hari Allah,800) karena Dia akan membalas suatu kaum sesuai dengan apa yang telah mereka kerjakan"},{id:15,text:"\u0645\u064e\u0646\u06e1 \u0639\u064e\u0645\u0650\u0644\u064e \u0635\u064e\u0670\u0644\u0650\u062d\u0657\u0627 \u0641\u064e\u0644\u0650\u0646\u064e\u0641\u06e1\u0633\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u0645\u064e\u0646\u06e1 \u0623\u064e\u0633\u064e\u0627\u0653\u0621\u064e \u0641\u064e\u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627\u06d6 \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1 \u062a\u064f\u0631\u06e1\u062c\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Barangsiapa mengerjakan kebajikan, maka itu untuk dirinya sendiri, dan barangsiapa mengerjakan kejahatan, maka itu akan menimpa dirinya sendiri; kemudian kepada Tuhanmu kamu dikembalikan"},{id:16,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0627 \u0628\u064e\u0646\u0650\u064a\u0653 \u0625\u0650\u0633\u06e1\u0631\u064e\u0640\u0670\u0653\u0621\u0650\u064a\u0644\u064e \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0648\u064e\u0671\u0644\u06e1\u062d\u064f\u0643\u06e1\u0645\u064e \u0648\u064e\u0671\u0644\u0646\u0651\u064f\u0628\u064f\u0648\u0651\u064e\u0629\u064e \u0648\u064e\u0631\u064e\u0632\u064e\u0642\u06e1\u0646\u064e\u0670\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0637\u0651\u064e\u064a\u0651\u0650\u0628\u064e\u0670\u062a\u0650 \u0648\u064e\u0641\u064e\u0636\u0651\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Dan sungguh, kepada Bani Israil telah Kami berikan Kitab (Taurat), kekuasaan dan kenabian, Kami anugerahkan kepada mereka rezeki yang baik, dan Kami lebihkan mereka atas bangsa-bangsa (pada masa itu)"},{id:17,text:"\u0648\u064e\u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f\u0645 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0656 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0631\u0650\u06d6 \u0641\u064e\u0645\u064e\u0627 \u0671\u062e\u06e1\u062a\u064e\u0644\u064e\u0641\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0645\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0639\u0650\u0644\u06e1\u0645\u064f \u0628\u064e\u063a\u06e1\u064a\u064e\u06e2\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u064a\u064e\u0642\u06e1\u0636\u0650\u064a \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u0641\u0650\u064a\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0647\u0650 \u064a\u064e\u062e\u06e1\u062a\u064e\u0644\u0650\u0641\u064f\u0648\u0646\u064e",translation:"Dan Kami berikan kepada mereka keterangan-keterangan yang jelas tentang urusan (agama); maka mereka tidak berselisih kecuali setelah datang ilmu kepada mereka, karena kedengkian (yang ada) di antara mereka. Sungguh, Tuhanmu akan memberi putusan kepada mereka pada hari Kiamat terhadap apa yang selalu mereka perselisihkan"},{id:18,text:"\u062b\u064f\u0645\u0651\u064e \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0670\u0643\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0634\u064e\u0631\u0650\u064a\u0639\u064e\u0629\u0656 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0631\u0650 \u0641\u064e\u0671\u062a\u0651\u064e\u0628\u0650\u0639\u06e1\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u06e1 \u0623\u064e\u0647\u06e1\u0648\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Kemudian Kami jadikan engkau (Muhammad) mengikuti syariat (peraturan) dari agama itu, maka ikutilah (syariat itu) dan janganlah engkau ikuti keinginan orang-orang yang tidak tahu"},{id:19,text:"\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0646 \u064a\u064f\u063a\u06e1\u0646\u064f\u0648\u0627\u0652 \u0639\u064e\u0646\u0643\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627\u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0628\u064e\u0639\u06e1\u0636\u064f\u0647\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1\u0644\u0650\u064a\u064e\u0627\u0653\u0621\u064f \u0628\u064e\u0639\u06e1\u0636\u0656\u06d6 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0644\u0650\u064a\u0651\u064f \u0671\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",translation:"Sungguh, mereka tidak akan dapat menghindarkan engkau sedikit pun dari (azab) Allah. Dan sungguh, orang-orang yang zalim itu sebagian menjadi pelindung atas sebagian yang lain; sedang Allah pelindung bagi orang-orang yang bertakwa"},{id:20,text:"\u0647\u064e\u0670\u0630\u064e\u0627 \u0628\u064e\u0635\u064e\u0640\u0670\u0653\u0626\u0650\u0631\u064f \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0647\u064f\u062f\u0657\u0649 \u0648\u064e\u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u065e \u0644\u0651\u0650\u0642\u064e\u0648\u06e1\u0645\u0656 \u064a\u064f\u0648\u0642\u0650\u0646\u064f\u0648\u0646\u064e",translation:"(Alquran) ini adalah pedoman bagi manusia, petunjuk dan rahmat bagi kaum yang meyakini"},{id:21,text:"\u0623\u064e\u0645\u06e1 \u062d\u064e\u0633\u0650\u0628\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u062c\u06e1\u062a\u064e\u0631\u064e\u062d\u064f\u0648\u0627\u0652 \u0671\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0640\u0654\u064e\u0627\u062a\u0650 \u0623\u064e\u0646 \u0646\u0651\u064e\u062c\u06e1\u0639\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0633\u064e\u0648\u064e\u0627\u0653\u0621\u0657 \u0645\u0651\u064e\u062d\u06e1\u064a\u064e\u0627\u0647\u064f\u0645\u06e1 \u0648\u064e\u0645\u064e\u0645\u064e\u0627\u062a\u064f\u0647\u064f\u0645\u06e1\u06da \u0633\u064e\u0627\u0653\u0621\u064e \u0645\u064e\u0627 \u064a\u064e\u062d\u06e1\u0643\u064f\u0645\u064f\u0648\u0646\u064e",translation:"Apakah orang-orang yang melakukan kejahatan itu mengira bahwa Kami akan memperlakukan mereka seperti orang-orang yang beriman dan yang mengerjakan kebajikan, yaitu sama dalam kehidupan dan kematian mereka? Alangkah buruknya penilaian mereka itu"},{id:22,text:"\u0648\u064e\u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0644\u0650\u062a\u064f\u062c\u06e1\u0632\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u064f \u0646\u064e\u0641\u06e1\u0633\u0650\u06ed \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064e\u062a\u06e1 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064f\u0638\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan Allah menciptakan langit dan bumi dengan tujuan yang benar, dan agar setiap jiwa diberi balasan sesuai dengan apa yang dikerjakannya, dan mereka tidak akan dirugikan"},{id:23,text:"\u0623\u064e\u0641\u064e\u0631\u064e\u0621\u064e\u064a\u06e1\u062a\u064e \u0645\u064e\u0646\u0650 \u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064e \u0625\u0650\u0644\u064e\u0670\u0647\u064e\u0647\u064f\u06e5 \u0647\u064e\u0648\u064e\u0649\u0670\u0647\u064f \u0648\u064e\u0623\u064e\u0636\u064e\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0639\u0650\u0644\u06e1\u0645\u0656 \u0648\u064e\u062e\u064e\u062a\u064e\u0645\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0633\u064e\u0645\u06e1\u0639\u0650\u0647\u0650\u06e6 \u0648\u064e\u0642\u064e\u0644\u06e1\u0628\u0650\u0647\u0650\u06e6 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0635\u064e\u0631\u0650\u0647\u0650\u06e6 \u063a\u0650\u0634\u064e\u0670\u0648\u064e\u0629\u0657 \u0641\u064e\u0645\u064e\u0646 \u064a\u064e\u0647\u06e1\u062f\u0650\u064a\u0647\u0650 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"(Maka pernahkah kamu melihat orang yang menjadikan hawa nafsunya sebagai tuhannya dan Allah membiarkannya sesat dengan sepengetahuan-Nya,801) dan Allah telah mengunci pendengaran dan hatinya serta meletakkan tutup atas penglihatannya? Maka siapakah yang mampu memberinya petunjuk setelah Allah (membiarkannya sesat)? Mengapa kamu tidak mengambil pelajaran"},{id:24,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u0647\u0650\u064a\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u062d\u064e\u064a\u064e\u0627\u062a\u064f\u0646\u064e\u0627 \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0646\u064e\u0645\u064f\u0648\u062a\u064f \u0648\u064e\u0646\u064e\u062d\u06e1\u064a\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0647\u06e1\u0644\u0650\u0643\u064f\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u062f\u0651\u064e\u0647\u06e1\u0631\u064f\u06da \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u0645 \u0628\u0650\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u0650\u0646\u06e1 \u0639\u0650\u0644\u06e1\u0645\u064d\u06d6 \u0625\u0650\u0646\u06e1 \u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u064a\u064e\u0638\u064f\u0646\u0651\u064f\u0648\u0646\u064e",translation:"Dan mereka berkata, \"Kehidupan ini tidak lain hanyalah kehidupan di dunia saja, kita mati dan kita hidup, dan tidak ada yang membinasakan kita selain masa.\" Tetapi mereka tidak mempunyai ilmu tentang itu, mereka hanyalah menduga-duga saja"},{id:25,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062a\u064f\u062a\u06e1\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u064f\u0646\u064e\u0627 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0656 \u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u062d\u064f\u062c\u0651\u064e\u062a\u064e\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0671\u0626\u06e1\u062a\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u0628\u064e\u0627\u0653\u0626\u0650\u0646\u064e\u0627\u0653 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0635\u064e\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Dan apabila kepada mereka dibacakan ayat-ayat Kami yang jelas, tidak ada bantahan mereka selain mengatakan, \"Hidupkanlah kembali nenek moyang kami, jika kamu orang yang benar"},{id:26,text:"\u0642\u064f\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064f\u062d\u06e1\u064a\u0650\u064a\u0643\u064f\u0645\u06e1 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0645\u0650\u064a\u062a\u064f\u0643\u064f\u0645\u06e1 \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u062c\u06e1\u0645\u064e\u0639\u064f\u0643\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u0644\u064e\u0627 \u0631\u064e\u064a\u06e1\u0628\u064e \u0641\u0650\u064a\u0647\u0650 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Katakanlah, \"Allah yang menghidupkan kemudian mematikan kamu, setelah itu mengumpulkan kamu pada hari Kiamat yang tidak diragukan lagi; tetapi kebanyakan manusia tidak mengetahui"},{id:27,text:"\u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064f\u0644\u06e1\u0643\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06da \u0648\u064e\u064a\u064e\u0648\u06e1\u0645\u064e \u062a\u064e\u0642\u064f\u0648\u0645\u064f \u0671\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064f \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u064a\u064e\u062e\u06e1\u0633\u064e\u0631\u064f \u0671\u0644\u06e1\u0645\u064f\u0628\u06e1\u0637\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Dan milik Allah lah kerajaan langit dan bumi. Dan pada hari terjadinya Kiamat, akan rugilah pada hari itu orang-orang yang mengerjakan kebatilan (dosa)"},{id:28,text:"\u0648\u064e\u062a\u064e\u0631\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u064e \u0623\u064f\u0645\u0651\u064e\u0629\u0656 \u062c\u064e\u0627\u062b\u0650\u064a\u064e\u0629\u0657\u06da \u0643\u064f\u0644\u0651\u064f \u0623\u064f\u0645\u0651\u064e\u0629\u0656 \u062a\u064f\u062f\u06e1\u0639\u064e\u0649\u0670\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u0643\u0650\u062a\u064e\u0670\u0628\u0650\u0647\u064e\u0627 \u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e \u062a\u064f\u062c\u06e1\u0632\u064e\u0648\u06e1\u0646\u064e \u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan (pada hari itu) engkau akan melihat setiap umat berlutut. Setiap umat dipanggil untuk (melihat) buku catatan amalnya. Pada hari itu kamu diberi balasan atas apa yang telah kamu kerjakan"},{id:29,text:"\u0647\u064e\u0670\u0630\u064e\u0627 \u0643\u0650\u062a\u064e\u0670\u0628\u064f\u0646\u064e\u0627 \u064a\u064e\u0646\u0637\u0650\u0642\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650\u06da \u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0646\u064e\u0633\u06e1\u062a\u064e\u0646\u0633\u0650\u062e\u064f \u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"(Allah berfirman), \"Inilah kitab (catatan) Kami yang menuturkan kepadamu dengan sebenar-benarnya. Sesungguhnya Kami telah menyuruh mencatat apa yang telah kamu kerjakan"},{id:30,text:"\u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0641\u064e\u064a\u064f\u062f\u06e1\u062e\u0650\u0644\u064f\u0647\u064f\u0645\u06e1 \u0631\u064e\u0628\u0651\u064f\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0631\u064e\u062d\u06e1\u0645\u064e\u062a\u0650\u0647\u0650\u06e6\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0641\u064e\u0648\u06e1\u0632\u064f \u0671\u0644\u06e1\u0645\u064f\u0628\u0650\u064a\u0646\u064f",translation:"Adapun orang-orang yang beriman dan mengerjakan kebajikan, maka Tuhan memasukkan mereka ke dalam rahmat-Nya (surga). Demikian itulah kemenangan yang nyata"},{id:31,text:"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0641\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0643\u064f\u0646\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u064a \u062a\u064f\u062a\u06e1\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u064e\u0631\u06e1\u062a\u064f\u0645\u06e1 \u0648\u064e\u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0642\u064e\u0648\u06e1\u0645\u0657\u0627 \u0645\u0651\u064f\u062c\u06e1\u0631\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Sedangkan (kepada) orang-orang yang kafir (difirmankan), \"Bukankah ayat-ayat-Ku telah dibacakan kepadamu, tetapi kamu menyombongkan diri dan kamu menjadi orang-orang yang berbuat dosa"},{id:32,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u0650\u064a\u0644\u064e \u0625\u0650\u0646\u0651\u064e \u0648\u064e\u0639\u06e1\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u064e\u0642\u0651\u065e \u0648\u064e\u0671\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064f \u0644\u064e\u0627 \u0631\u064e\u064a\u06e1\u0628\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0642\u064f\u0644\u06e1\u062a\u064f\u0645 \u0645\u0651\u064e\u0627 \u0646\u064e\u062f\u06e1\u0631\u0650\u064a \u0645\u064e\u0627 \u0671\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064f \u0625\u0650\u0646 \u0646\u0651\u064e\u0638\u064f\u0646\u0651\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0638\u064e\u0646\u0651\u0657\u0627 \u0648\u064e\u0645\u064e\u0627 \u0646\u064e\u062d\u06e1\u0646\u064f \u0628\u0650\u0645\u064f\u0633\u06e1\u062a\u064e\u064a\u06e1\u0642\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dan apabila dikatakan (kepadamu), \"Sungguh, janji Allah itu benar, dan hari Kiamat itu tidak diragukan adanya,\" kamu menjawab, \"Kami tidak tahu apakah hari Kiamat itu, kami hanyalah menduga-duga saja, dan kami tidak yakin"},{id:33,text:"\u0648\u064e\u0628\u064e\u062f\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0633\u064e\u064a\u0651\u0650\u0640\u0654\u064e\u0627\u062a\u064f \u0645\u064e\u0627 \u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0648\u064e\u062d\u064e\u0627\u0642\u064e \u0628\u0650\u0647\u0650\u0645 \u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6 \u064a\u064e\u0633\u06e1\u062a\u064e\u0647\u06e1\u0632\u0650\u0621\u064f\u0648\u0646\u064e",translation:"Dan nyatalah bagi mereka keburukan-keburukan yang mereka kerjakan, dan berlakulah (azab) terhadap mereka yang dahulu mereka perolok-olokkan"},{id:34,text:"\u0648\u064e\u0642\u0650\u064a\u0644\u064e \u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e \u0646\u064e\u0646\u0633\u064e\u0649\u0670\u0643\u064f\u0645\u06e1 \u0643\u064e\u0645\u064e\u0627 \u0646\u064e\u0633\u0650\u064a\u062a\u064f\u0645\u06e1 \u0644\u0650\u0642\u064e\u0627\u0653\u0621\u064e \u064a\u064e\u0648\u06e1\u0645\u0650\u0643\u064f\u0645\u06e1 \u0647\u064e\u0670\u0630\u064e\u0627 \u0648\u064e\u0645\u064e\u0623\u06e1\u0648\u064e\u0649\u0670\u0643\u064f\u0645\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u064f \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0646\u0651\u064e\u0640\u0670\u0635\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan kepada mereka dikatakan, \"Pada hari ini Kami melupakan kamu sebagaimana kamu telah melupakan pertemuan (dengan) harimu ini; dan tempat kembalimu ialah neraka, dan sekali-kali tidak akan ada penolong bagimu"},{id:35,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645 \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u064f \u0671\u062a\u0651\u064e\u062e\u064e\u0630\u06e1\u062a\u064f\u0645\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0647\u064f\u0632\u064f\u0648\u0657\u0627 \u0648\u064e\u063a\u064e\u0631\u0651\u064e\u062a\u06e1\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u064f \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627\u06da \u0641\u064e\u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e \u0644\u064e\u0627 \u064a\u064f\u062e\u06e1\u0631\u064e\u062c\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u06e1 \u064a\u064f\u0633\u06e1\u062a\u064e\u0639\u06e1\u062a\u064e\u0628\u064f\u0648\u0646\u064e",translation:"Yang demikian itu karena sesungguhnya kamu telah menjadikan ayat-ayat Allah sebagai olok-olokkan, dan kamu telah ditipu oleh kehidupan dunia.\" Maka pada hari ini mereka tidak dikeluarkan dari neraka dan tidak pula mereka diberi kesempatan untuk bertobat"},{id:36,text:"\u0641\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u062d\u064e\u0645\u06e1\u062f\u064f \u0631\u064e\u0628\u0651\u0650 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0631\u064e\u0628\u0651\u0650 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0631\u064e\u0628\u0651\u0650 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Segala puji hanya bagi Allah, Tuhan (pemilik) langit dan bumi, Tuhan seluruh alam"},{id:37,text:"\u0648\u064e\u0644\u064e\u0647\u064f \u0671\u0644\u06e1\u0643\u0650\u0628\u06e1\u0631\u0650\u064a\u064e\u0627\u0653\u0621\u064f \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0671\u0644\u06e1\u062d\u064e\u0643\u0650\u064a\u0645\u064f",translation:"Dan hanya bagi-Nya segala keagungan di langit dan di bumi, dan Dialah Yang Mahaperkasa, Mahabijaksana"}]},{id:46,name:"\u0627\u0644\u0623\u062d\u0642\u0627\u0641",transliteration:"Al-Ahqaf",translation:"Bukit-bukir Pasir",type:"meccan",total_verses:35,verses:[{id:1,text:"\u062d\u0645\u0653",translation:"\u1e24\u0101 M\u012bm"},{id:2,text:"\u062a\u064e\u0646\u0632\u0650\u064a\u0644\u064f \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0645\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u0650 \u0671\u0644\u06e1\u062d\u064e\u0643\u0650\u064a\u0645\u0650",translation:"Kitab ini diturunkan dari Allah Yang Mahaperkasa, Mahabijaksana"},{id:3,text:"\u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u06e1\u0646\u064e\u0627 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0623\u064e\u062c\u064e\u0644\u0656 \u0645\u0651\u064f\u0633\u064e\u0645\u0651\u0657\u0649\u06da \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0639\u064e\u0645\u0651\u064e\u0627\u0653 \u0623\u064f\u0646\u0630\u0650\u0631\u064f\u0648\u0627\u0652 \u0645\u064f\u0639\u06e1\u0631\u0650\u0636\u064f\u0648\u0646\u064e",translation:"Kami tidak menciptakan langit dan bumi dan apa yang ada di antara keduanya melainkan dengan (tujuan) yang benar dan dalam waktu yang ditentukan. Namun orang-orang yang kafir berpaling dari peringatan yang diberikan kepada mereka"},{id:4,text:"\u0642\u064f\u0644\u06e1 \u0623\u064e\u0631\u064e\u0621\u064e\u064a\u06e1\u062a\u064f\u0645 \u0645\u0651\u064e\u0627 \u062a\u064e\u062f\u06e1\u0639\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0631\u064f\u0648\u0646\u0650\u064a \u0645\u064e\u0627\u0630\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0623\u064e\u0645\u06e1 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0634\u0650\u0631\u06e1\u0643\u065e \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650\u06d6 \u0671\u0626\u06e1\u062a\u064f\u0648\u0646\u0650\u064a \u0628\u0650\u0643\u0650\u062a\u064e\u0670\u0628\u0656 \u0645\u0651\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650 \u0647\u064e\u0670\u0630\u064e\u0627\u0653 \u0623\u064e\u0648\u06e1 \u0623\u064e\u062b\u064e\u0670\u0631\u064e\u0629\u0656 \u0645\u0651\u0650\u0646\u06e1 \u0639\u0650\u0644\u06e1\u0645\u064d \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0635\u064e\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Katakanlah (Muhammad), \"Terangkanlah (kepadaku) tentang apa yang kamu sembah selain Allah; perlihatkan kepadaku apa yang telah mereka ciptakan dari bumi, atau adakah peran serta mereka dalam (penciptaan) langit? Bawalah kepadaku kitab sebelum (Alquran) ini atau peninggalan dari pengetahuan (orang-orang dahulu), jika kamu orang yang benar"},{id:5,text:"\u0648\u064e\u0645\u064e\u0646\u06e1 \u0623\u064e\u0636\u064e\u0644\u0651\u064f \u0645\u0650\u0645\u0651\u064e\u0646 \u064a\u064e\u062f\u06e1\u0639\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0646 \u0644\u0651\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u062c\u0650\u064a\u0628\u064f \u0644\u064e\u0647\u064f\u06e5\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0646 \u062f\u064f\u0639\u064e\u0627\u0653\u0626\u0650\u0647\u0650\u0645\u06e1 \u063a\u064e\u0670\u0641\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Dan siapakah yang lebih sesat daripada orang-orang yang menyembah selain Allah, (sembahan) yang tidak dapat memperkenankan (doa)nya sampai hari Kiamat dan mereka lalai dari (memperhatikan) doa mereka"},{id:6,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062d\u064f\u0634\u0650\u0631\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u0639\u06e1\u062f\u064e\u0627\u0653\u0621\u0657 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0639\u0650\u0628\u064e\u0627\u062f\u064e\u062a\u0650\u0647\u0650\u0645\u06e1 \u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan apabila manusia dikumpulkan (pada hari Kiamat), sesembahan itu menjadi musuh mereka, dan mengingkari pemujaan-pemujaan yang mereka lakukan kepadanya"},{id:7,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062a\u064f\u062a\u06e1\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u064f\u0646\u064e\u0627 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0656 \u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0644\u0650\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u06e1 \u0647\u064e\u0670\u0630\u064e\u0627 \u0633\u0650\u062d\u06e1\u0631\u065e \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u064c",translation:"Dan apabila dibacakan ayat-ayat Kami yang jelas kepada mereka, orang-orang yang kafir berkata, ketika kebenaran itu datang kepada mereka, \"Ini adalah sihir yang nyata"},{id:8,text:"\u0623\u064e\u0645\u06e1 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0671\u0641\u06e1\u062a\u064e\u0631\u064e\u0649\u0670\u0647\u064f\u06d6 \u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0650 \u0671\u0641\u06e1\u062a\u064e\u0631\u064e\u064a\u06e1\u062a\u064f\u0647\u064f\u06e5 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0645\u06e1\u0644\u0650\u0643\u064f\u0648\u0646\u064e \u0644\u0650\u064a \u0645\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0634\u064e\u064a\u06e1\u0640\u0654\u064b\u0627\u06d6 \u0647\u064f\u0648\u064e \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064f\u0641\u0650\u064a\u0636\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0647\u0650\u06da \u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0647\u0650\u06e6 \u0634\u064e\u0647\u0650\u064a\u062f\u064e\u06e2\u0627 \u0628\u064e\u064a\u06e1\u0646\u0650\u064a \u0648\u064e\u0628\u064e\u064a\u06e1\u0646\u064e\u0643\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u063a\u064e\u0641\u064f\u0648\u0631\u064f \u0671\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",translation:"Bahkan mereka berkata, \"Dia (Muhammad) telah mengada-adakannya (Alquran).\" Katakanlah, \"Jika aku mengada-adakannya, maka kamu tidak kuasa sedikit pun menghindarkan aku dari (azab) Allah. Dia lebih tahu apa yang kamu percakapkan tentang Alquran ini. Cukuplah Dia menjadi saksi antara aku dengan kamu. Dia Maha Pengampun, Maha Penyayang"},{id:9,text:"\u0642\u064f\u0644\u06e1 \u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f \u0628\u0650\u062f\u06e1\u0639\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0631\u0651\u064f\u0633\u064f\u0644\u0650 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u062f\u06e1\u0631\u0650\u064a \u0645\u064e\u0627 \u064a\u064f\u0641\u06e1\u0639\u064e\u0644\u064f \u0628\u0650\u064a \u0648\u064e\u0644\u064e\u0627 \u0628\u0650\u0643\u064f\u0645\u06e1\u06d6 \u0625\u0650\u0646\u06e1 \u0623\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u064a\u064f\u0648\u062d\u064e\u0649\u0670\u0653 \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u064e\u0627\u06e0 \u0625\u0650\u0644\u0651\u064e\u0627 \u0646\u064e\u0630\u0650\u064a\u0631\u065e \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u065e",translation:"Katakanlah (Muhammad), \"Aku bukanlah Rasul yang pertama di antara rasul-rasul, dan aku tidak tahu apa yang akan diperbuat terhadapku dan terhadapmu. Aku hanyalah mengikuti apa yang diwahyukan kepadaku, dan aku hanyalah pemberi peringatan yang menjelaskan"},{id:10,text:"\u0642\u064f\u0644\u06e1 \u0623\u064e\u0631\u064e\u0621\u064e\u064a\u06e1\u062a\u064f\u0645\u06e1 \u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u06e1 \u0639\u0650\u0646\u062f\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0643\u064e\u0641\u064e\u0631\u06e1\u062a\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6 \u0648\u064e\u0634\u064e\u0647\u0650\u062f\u064e \u0634\u064e\u0627\u0647\u0650\u062f\u065e \u0645\u0651\u0650\u0646\u06e2 \u0628\u064e\u0646\u0650\u064a\u0653 \u0625\u0650\u0633\u06e1\u0631\u064e\u0640\u0670\u0653\u0621\u0650\u064a\u0644\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u0650\u062b\u06e1\u0644\u0650\u0647\u0650\u06e6 \u0641\u064e\u0640\u0654\u064e\u0627\u0645\u064e\u0646\u064e \u0648\u064e\u0671\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u064e\u0631\u06e1\u062a\u064f\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064e\u0647\u06e1\u062f\u0650\u064a \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Katakanlah, \"Terangkan kepadaku, bagaimana pendapatmu jika sebenarnya (Alquran) ini datang dari Allah, dan kamu mengingkarinya, padahal ada seorang saksi dari Bani Israil802) yang mengakui (kebenaran) yang serupa dengan (yang disebut dalam) Alquran lalu dia beriman; kamu menyombongkan diri. Sungguh, Allah tidak memberi petunjuk kepada orang-orang yang zalim"},{id:11,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0648\u06e1 \u0643\u064e\u0627\u0646\u064e \u062e\u064e\u064a\u06e1\u0631\u0657\u0627 \u0645\u0651\u064e\u0627 \u0633\u064e\u0628\u064e\u0642\u064f\u0648\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u06da \u0648\u064e\u0625\u0650\u0630\u06e1 \u0644\u064e\u0645\u06e1 \u064a\u064e\u0647\u06e1\u062a\u064e\u062f\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6 \u0641\u064e\u0633\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0647\u064e\u0670\u0630\u064e\u0627\u0653 \u0625\u0650\u0641\u06e1\u0643\u065e \u0642\u064e\u062f\u0650\u064a\u0645\u065e",translation:"Dan orang-orang yang kafir berkata kepada orang-orang yang beriman, \"Sekiranya Alquran itu sesuatu yang baik, tentu mereka tidak pantas mendahului kami (beriman) kepadanya.803) Tetapi karena mereka tidak mendapat petunjuk dengannya, maka mereka akan berkata, \"Ini adalah dusta yang lama"},{id:12,text:"\u0648\u064e\u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u06e6 \u0643\u0650\u062a\u064e\u0670\u0628\u064f \u0645\u064f\u0648\u0633\u064e\u0649\u0670\u0653 \u0625\u0650\u0645\u064e\u0627\u0645\u0657\u0627 \u0648\u064e\u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u0657\u06da \u0648\u064e\u0647\u064e\u0670\u0630\u064e\u0627 \u0643\u0650\u062a\u064e\u0670\u0628\u065e \u0645\u0651\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u065e \u0644\u0651\u0650\u0633\u064e\u0627\u0646\u064b\u0627 \u0639\u064e\u0631\u064e\u0628\u0650\u064a\u0651\u0657\u0627 \u0644\u0651\u0650\u064a\u064f\u0646\u0630\u0650\u0631\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627\u0652 \u0648\u064e\u0628\u064f\u0634\u06e1\u0631\u064e\u0649\u0670 \u0644\u0650\u0644\u06e1\u0645\u064f\u062d\u06e1\u0633\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dan sebelum (Alquran) itu telah ada Kitab Musa sebagai petunjuk dan rahmat. Dan (Alquran) ini adalah Kitab yang membenarkannya dalam bahasa Arab untuk memberi peringatan kepada orang-orang yang zalim dan memberi kabar gembira kepada orang-orang yang berbuat baik"},{id:13,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0631\u064e\u0628\u0651\u064f\u0646\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u062b\u064f\u0645\u0651\u064e \u0671\u0633\u06e1\u062a\u064e\u0642\u064e\u0670\u0645\u064f\u0648\u0627\u0652 \u0641\u064e\u0644\u064e\u0627 \u062e\u064e\u0648\u06e1\u0641\u064c \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u06e1 \u064a\u064e\u062d\u06e1\u0632\u064e\u0646\u064f\u0648\u0646\u064e",translation:"(Sesungguhnya orang-orang yang berkata, \"Tuhan kami adalah Allah,\" kemudian mereka tetap istikamah,804) tidak ada rasa khawatir pada mereka, dan mereka tidak (pula) bersedih hati"},{id:14,text:"\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u062e\u064e\u0670\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u062c\u064e\u0632\u064e\u0627\u0653\u0621\u064e\u06e2 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Mereka itulah para penghuni surga, kekal di dalamnya; sebagai balasan atas apa yang telah mereka kerjakan"},{id:15,text:"\u0648\u064e\u0648\u064e\u0635\u0651\u064e\u064a\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064e \u0628\u0650\u0648\u064e\u0670\u0644\u0650\u062f\u064e\u064a\u06e1\u0647\u0650 \u0625\u0650\u062d\u06e1\u0633\u064e\u0670\u0646\u064b\u0627\u06d6 \u062d\u064e\u0645\u064e\u0644\u064e\u062a\u06e1\u0647\u064f \u0623\u064f\u0645\u0651\u064f\u0647\u064f\u06e5 \u0643\u064f\u0631\u06e1\u0647\u0657\u0627 \u0648\u064e\u0648\u064e\u0636\u064e\u0639\u064e\u062a\u06e1\u0647\u064f \u0643\u064f\u0631\u06e1\u0647\u0657\u0627\u06d6 \u0648\u064e\u062d\u064e\u0645\u06e1\u0644\u064f\u0647\u064f\u06e5 \u0648\u064e\u0641\u0650\u0635\u064e\u0670\u0644\u064f\u0647\u064f\u06e5 \u062b\u064e\u0644\u064e\u0670\u062b\u064f\u0648\u0646\u064e \u0634\u064e\u0647\u06e1\u0631\u064b\u0627\u06da \u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u064e\u0627 \u0628\u064e\u0644\u064e\u063a\u064e \u0623\u064e\u0634\u064f\u062f\u0651\u064e\u0647\u064f\u06e5 \u0648\u064e\u0628\u064e\u0644\u064e\u063a\u064e \u0623\u064e\u0631\u06e1\u0628\u064e\u0639\u0650\u064a\u0646\u064e \u0633\u064e\u0646\u064e\u0629\u0657 \u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0623\u064e\u0648\u06e1\u0632\u0650\u0639\u06e1\u0646\u0650\u064a\u0653 \u0623\u064e\u0646\u06e1 \u0623\u064e\u0634\u06e1\u0643\u064f\u0631\u064e \u0646\u0650\u0639\u06e1\u0645\u064e\u062a\u064e\u0643\u064e \u0671\u0644\u0651\u064e\u062a\u0650\u064a\u0653 \u0623\u064e\u0646\u06e1\u0639\u064e\u0645\u06e1\u062a\u064e \u0639\u064e\u0644\u064e\u064a\u0651\u064e \u0648\u064e\u0639\u064e\u0644\u064e\u0649\u0670 \u0648\u064e\u0670\u0644\u0650\u062f\u064e\u064a\u0651\u064e \u0648\u064e\u0623\u064e\u0646\u06e1 \u0623\u064e\u0639\u06e1\u0645\u064e\u0644\u064e \u0635\u064e\u0670\u0644\u0650\u062d\u0657\u0627 \u062a\u064e\u0631\u06e1\u0636\u064e\u0649\u0670\u0647\u064f \u0648\u064e\u0623\u064e\u0635\u06e1\u0644\u0650\u062d\u06e1 \u0644\u0650\u064a \u0641\u0650\u064a \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u062a\u0650\u064a\u0653\u06d6 \u0625\u0650\u0646\u0651\u0650\u064a \u062a\u064f\u0628\u06e1\u062a\u064f \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0648\u064e\u0625\u0650\u0646\u0651\u0650\u064a \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0633\u06e1\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dan Kami perintahkan kepada manusia agar berbuat baik kepada kedua orang tuanya. Ibunya telah mengandungnya dengan susah payah, dan melahirkannya dengan susah payah (pula). Masa mengandung sampai menyapihnya selama tiga puluh bulan, sehingga apabila dia (anak itu) telah dewasa dan umurnya mencapai empat puluh tahun dia berdoa, \"Ya Tuhanku, berilah aku petunjuk agar aku dapat mensyukuri nikmat-Mu yang telah Engkau limpahkan kepadaku dan kepada kedua orang tuaku, dan agar aku dapat berbuat kebajikan yang Engkau ridai; dan berilah aku kebaikan yang akan mengalir sampai kepada anak cucuku. Sungguh, aku bertobat kepada Engkau, dan sungguh aku termasuk orang muslim"},{id:16,text:"\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0646\u064e\u062a\u064e\u0642\u064e\u0628\u0651\u064e\u0644\u064f \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064e \u0645\u064e\u0627 \u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0648\u064e\u0646\u064e\u062a\u064e\u062c\u064e\u0627\u0648\u064e\u0632\u064f \u0639\u064e\u0646 \u0633\u064e\u064a\u0651\u0650\u0640\u0654\u064e\u0627\u062a\u0650\u0647\u0650\u0645\u06e1 \u0641\u0650\u064a\u0653 \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u0650 \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u0650\u06d6 \u0648\u064e\u0639\u06e1\u062f\u064e \u0671\u0644\u0635\u0651\u0650\u062f\u06e1\u0642\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064f\u0648\u0639\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Mereka itulah orang-orang yang Kami terima amal baiknya yang telah mereka kerjakan, dan (orang-orang) yang Kami maafkan kesalahan-kesalahannya, (mereka akan menjadi) penghuni-penghuni surga. Itu adalah janji benar yang telah dijanjikan kepada mereka"},{id:17,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0648\u064e\u0670\u0644\u0650\u062f\u064e\u064a\u06e1\u0647\u0650 \u0623\u064f\u0641\u0651\u0656 \u0644\u0651\u064e\u0643\u064f\u0645\u064e\u0627\u0653 \u0623\u064e\u062a\u064e\u0639\u0650\u062f\u064e\u0627\u0646\u0650\u0646\u0650\u064a\u0653 \u0623\u064e\u0646\u06e1 \u0623\u064f\u062e\u06e1\u0631\u064e\u062c\u064e \u0648\u064e\u0642\u064e\u062f\u06e1 \u062e\u064e\u0644\u064e\u062a\u0650 \u0671\u0644\u06e1\u0642\u064f\u0631\u064f\u0648\u0646\u064f \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u064a \u0648\u064e\u0647\u064f\u0645\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u063a\u0650\u064a\u062b\u064e\u0627\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u064a\u06e1\u0644\u064e\u0643\u064e \u0621\u064e\u0627\u0645\u0650\u0646\u06e1 \u0625\u0650\u0646\u0651\u064e \u0648\u064e\u0639\u06e1\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u064e\u0642\u0651\u065e \u0641\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0645\u064e\u0627 \u0647\u064e\u0670\u0630\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0633\u064e\u0670\u0637\u0650\u064a\u0631\u064f \u0671\u0644\u06e1\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",translation:"(Dan orang yang berkata kepada kedua orang tuanya, \"Ah.\"805) Apakah kamu berdua memperingatkan kepadaku bahwa aku akan dibangkitkan (dari kubur), padahal beberapa umat sebelumku telah berlalu? Lalu kedua orang tuanya itu memohon pertolongan kepada Allah (seraya berkata), \"Celaka kamu, berimanlah! Sungguh, janji Allah itu benar.\" Lalu dia (anak itu) berkata, \"Ini hanyalah dongeng orang-orang dahulu"},{id:18,text:"\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062d\u064e\u0642\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u064f \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0644\u064f \u0641\u0650\u064a\u0653 \u0623\u064f\u0645\u064e\u0645\u0656 \u0642\u064e\u062f\u06e1 \u062e\u064e\u0644\u064e\u062a\u06e1 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u062c\u0650\u0646\u0651\u0650 \u0648\u064e\u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u0650\u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u062e\u064e\u0670\u0633\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Mereka itu orang-orang yang telah pasti terkena ketetapan (azab) bersama umat-umat dahulu sebelum mereka, dari (golongan) jin dan manusia. Mereka adalah orang-orang yang rugi"},{id:19,text:"\u0648\u064e\u0644\u0650\u0643\u064f\u0644\u0651\u0656 \u062f\u064e\u0631\u064e\u062c\u064e\u0670\u062a\u065e \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652\u06d6 \u0648\u064e\u0644\u0650\u064a\u064f\u0648\u064e\u0641\u0651\u0650\u064a\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u0639\u06e1\u0645\u064e\u0670\u0644\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064f\u0638\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan setiap orang memperoleh tingkatan sesuai dengan apa yang telah mereka kerjakan, dan agar Allah mencukupkan balasan perbuatan mereka, dan mereka tidak dirugikan"},{id:20,text:"\u0648\u064e\u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064f\u0639\u06e1\u0631\u064e\u0636\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0623\u064e\u0630\u06e1\u0647\u064e\u0628\u06e1\u062a\u064f\u0645\u06e1 \u0637\u064e\u064a\u0651\u0650\u0628\u064e\u0670\u062a\u0650\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u062d\u064e\u064a\u064e\u0627\u062a\u0650\u0643\u064f\u0645\u064f \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0648\u064e\u0671\u0633\u06e1\u062a\u064e\u0645\u06e1\u062a\u064e\u0639\u06e1\u062a\u064f\u0645 \u0628\u0650\u0647\u064e\u0627 \u0641\u064e\u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e \u062a\u064f\u062c\u06e1\u0632\u064e\u0648\u06e1\u0646\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0671\u0644\u06e1\u0647\u064f\u0648\u0646\u0650 \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u0650\u0631\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0628\u0650\u063a\u064e\u064a\u06e1\u0631\u0650 \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0641\u06e1\u0633\u064f\u0642\u064f\u0648\u0646\u064e",translation:"Dan (ingatlah) pada hari (ketika) orang-orang kafir dihadapkan ke neraka (seraya dikatakan kepada mereka), \"Kamu telah menghabiskan (rezeki) yang baik untuk kehidupan duniamu, dan kamu telah bersenang-senang (menikmati)nya; maka pada hari ini kamu dibalas dengan azab yang menghinakan, karena kamu sombong di bumi tanpa mengindahkan kebenaran, dan karena kamu berbuat durhaka (tidak taat kepada Allah)"},{id:21,text:"\u06de\u0648\u064e\u0671\u0630\u06e1\u0643\u064f\u0631\u06e1 \u0623\u064e\u062e\u064e\u0627 \u0639\u064e\u0627\u062f\u064d \u0625\u0650\u0630\u06e1 \u0623\u064e\u0646\u0630\u064e\u0631\u064e \u0642\u064e\u0648\u06e1\u0645\u064e\u0647\u064f\u06e5 \u0628\u0650\u0671\u0644\u06e1\u0623\u064e\u062d\u06e1\u0642\u064e\u0627\u0641\u0650 \u0648\u064e\u0642\u064e\u062f\u06e1 \u062e\u064e\u0644\u064e\u062a\u0650 \u0671\u0644\u0646\u0651\u064f\u0630\u064f\u0631\u064f \u0645\u0650\u0646\u06e2 \u0628\u064e\u064a\u06e1\u0646\u0650 \u064a\u064e\u062f\u064e\u064a\u06e1\u0647\u0650 \u0648\u064e\u0645\u0650\u0646\u06e1 \u062e\u064e\u0644\u06e1\u0641\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u064a\u064e\u0648\u06e1\u0645\u064d \u0639\u064e\u0638\u0650\u064a\u0645\u0656",translation:"Dan ingatlah (Hud) saudara kaum '\u0100d, yaitu ketika dia mengingatkan kaumnya tentang bukit-bukit pasir, dan sesungguhnya telah berlalu beberapa orang pemberi peringatan sebelumnya dan setelahnya (dengan berkata), \"Janganlah kamu menyembah selain Allah, aku sungguh khawatir nanti kamu ditimpa azab pada hari yang besar"},{id:22,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u062c\u0650\u0626\u06e1\u062a\u064e\u0646\u064e\u0627 \u0644\u0650\u062a\u064e\u0623\u06e1\u0641\u0650\u0643\u064e\u0646\u064e\u0627 \u0639\u064e\u0646\u06e1 \u0621\u064e\u0627\u0644\u0650\u0647\u064e\u062a\u0650\u0646\u064e\u0627 \u0641\u064e\u0623\u06e1\u062a\u0650\u0646\u064e\u0627 \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0650\u062f\u064f\u0646\u064e\u0627\u0653 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Mereka menjawab, \"Apakah engkau datang kepada kami untuk memalingkan kami dari (menyembah) tuhan-tuhan kami? Maka datangkanlah kepada kami azab yang telah engkau ancamkan kepada kami, jika engkau termasuk orang yang benar"},{id:23,text:"\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0671\u0644\u06e1\u0639\u0650\u0644\u06e1\u0645\u064f \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0623\u064f\u0628\u064e\u0644\u0651\u0650\u063a\u064f\u0643\u064f\u0645 \u0645\u0651\u064e\u0627\u0653 \u0623\u064f\u0631\u06e1\u0633\u0650\u0644\u06e1\u062a\u064f \u0628\u0650\u0647\u0650\u06e6 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064e\u0631\u064e\u0649\u0670\u0643\u064f\u0645\u06e1 \u0642\u064e\u0648\u06e1\u0645\u0657\u0627 \u062a\u064e\u062c\u06e1\u0647\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dia (Hud) berkata, \"Sesungguhnya ilmu (tentang itu) hanya pada Allah, dan aku (hanya) menyampaikan kepadamu apa yang diwahyukan kepadaku, tetapi aku melihat kamu adalah kaum yang berlaku bodoh"},{id:24,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0631\u064e\u0623\u064e\u0648\u06e1\u0647\u064f \u0639\u064e\u0627\u0631\u0650\u0636\u0657\u0627 \u0645\u0651\u064f\u0633\u06e1\u062a\u064e\u0642\u06e1\u0628\u0650\u0644\u064e \u0623\u064e\u0648\u06e1\u062f\u0650\u064a\u064e\u062a\u0650\u0647\u0650\u0645\u06e1 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0647\u064e\u0670\u0630\u064e\u0627 \u0639\u064e\u0627\u0631\u0650\u0636\u065e \u0645\u0651\u064f\u0645\u06e1\u0637\u0650\u0631\u064f\u0646\u064e\u0627\u06da \u0628\u064e\u0644\u06e1 \u0647\u064f\u0648\u064e \u0645\u064e\u0627 \u0671\u0633\u06e1\u062a\u064e\u0639\u06e1\u062c\u064e\u0644\u06e1\u062a\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6\u06d6 \u0631\u0650\u064a\u062d\u065e \u0641\u0650\u064a\u0647\u064e\u0627 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Maka ketika mereka melihat azab itu berupa awan yang menuju ke lembah-lembah mereka, mereka berkata, \"Inilah awan yang akan menurunkan hujan kepada kita.\" (Bukan!) Tetapi itulah azab yang kamu minta agar disegerakan datangnya, (yaitu) angin yang mengandung azab yang pedih"},{id:25,text:"\u062a\u064f\u062f\u064e\u0645\u0651\u0650\u0631\u064f \u0643\u064f\u0644\u0651\u064e \u0634\u064e\u064a\u06e1\u0621\u0650\u06ed \u0628\u0650\u0623\u064e\u0645\u06e1\u0631\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u064e\u0627 \u0641\u064e\u0623\u064e\u0635\u06e1\u0628\u064e\u062d\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u064a\u064f\u0631\u064e\u0649\u0670\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0633\u064e\u0670\u0643\u0650\u0646\u064f\u0647\u064f\u0645\u06e1\u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u062c\u06e1\u0632\u0650\u064a \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0645\u064f\u062c\u06e1\u0631\u0650\u0645\u0650\u064a\u0646\u064e",translation:"yang menghancurkan segala sesuatu dengan perintah Tuhannya, sehingga mereka (kaum '\u0100d) menjadi tidak tampak lagi (di bumi) kecuali hanya (bekas-bekas) tempat tinggal mereka. Demikianlah Kami memberi balasan kepada kaum yang berdosa"},{id:26,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0645\u064e\u0643\u0651\u064e\u0646\u0651\u064e\u0640\u0670\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0645\u064e\u0627\u0653 \u0625\u0650\u0646 \u0645\u0651\u064e\u0643\u0651\u064e\u0646\u0651\u064e\u0640\u0670\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u0650 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0633\u064e\u0645\u06e1\u0639\u0657\u0627 \u0648\u064e\u0623\u064e\u0628\u06e1\u0635\u064e\u0670\u0631\u0657\u0627 \u0648\u064e\u0623\u064e\u0641\u06e1\u0640\u0654\u0650\u062f\u064e\u0629\u0657 \u0641\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u063a\u06e1\u0646\u064e\u0649\u0670 \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0633\u064e\u0645\u06e1\u0639\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064e\u0628\u06e1\u0635\u064e\u0670\u0631\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064e\u0641\u06e1\u0640\u0654\u0650\u062f\u064e\u062a\u064f\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0634\u064e\u064a\u06e1\u0621\u064d \u0625\u0650\u0630\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u062c\u06e1\u062d\u064e\u062f\u064f\u0648\u0646\u064e \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u062d\u064e\u0627\u0642\u064e \u0628\u0650\u0647\u0650\u0645 \u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6 \u064a\u064e\u0633\u06e1\u062a\u064e\u0647\u06e1\u0632\u0650\u0621\u064f\u0648\u0646\u064e",translation:"Dan sungguh, Kami telah meneguhkan kedudukan mereka (dengan kemakmuran dan kekuatan) yang belum pernah Kami berikan kepada kamu dan Kami telah memberikan kepada mereka pendengaran, penglihatan, dan hati; tetapi pendengaran, penglihatan, dan hati mereka itu tidak berguna sedikit pun bagi mereka, karena mereka (selalu) mengingkari ayat-ayat Allah, dan (ancaman) azab yang dahulu mereka perolok-olokkan telah mengepung mereka"},{id:27,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u0647\u06e1\u0644\u064e\u0643\u06e1\u0646\u064e\u0627 \u0645\u064e\u0627 \u062d\u064e\u0648\u06e1\u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0642\u064f\u0631\u064e\u0649\u0670 \u0648\u064e\u0635\u064e\u0631\u0651\u064e\u0641\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0623\u0653\u064a\u064e\u0670\u062a\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0631\u06e1\u062c\u0650\u0639\u064f\u0648\u0646\u064e",translation:"Dan sungguh, telah Kami binasakan negeri-negeri di sekitarmu, dan juga telah Kami jelaskan berulang-ulang tanda-tanda (kebesaran Kami), agar mereka kembali (bertobat)"},{id:28,text:"\u0641\u064e\u0644\u064e\u0648\u06e1\u0644\u064e\u0627 \u0646\u064e\u0635\u064e\u0631\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0642\u064f\u0631\u06e1\u0628\u064e\u0627\u0646\u064b\u0627 \u0621\u064e\u0627\u0644\u0650\u0647\u064e\u0629\u064e\u06e2\u06d6 \u0628\u064e\u0644\u06e1 \u0636\u064e\u0644\u0651\u064f\u0648\u0627\u0652 \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1\u06da \u0648\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0625\u0650\u0641\u06e1\u0643\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0641\u06e1\u062a\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Maka mengapa (berhala-berhala dan tuhan-tuhan) yang mereka sembah selain Allah untuk mendekatkan diri (kepada-Nya) tidak dapat menolong mereka? Bahkan tuhan-tuhan itu telah lenyap dari mereka; dan itulah akibat kebohongan mereka dan apa yang dahulu mereka ada-adakan"},{id:29,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0635\u064e\u0631\u064e\u0641\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0646\u064e\u0641\u064e\u0631\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u062c\u0650\u0646\u0651\u0650 \u064a\u064e\u0633\u06e1\u062a\u064e\u0645\u0650\u0639\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u064e \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062d\u064e\u0636\u064e\u0631\u064f\u0648\u0647\u064f \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0635\u0650\u062a\u064f\u0648\u0627\u0652\u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0642\u064f\u0636\u0650\u064a\u064e \u0648\u064e\u0644\u0651\u064e\u0648\u06e1\u0627\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u0645 \u0645\u0651\u064f\u0646\u0630\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan (ingatlah) ketika Kami hadapkan kepadamu (Muhammad) serombongan jin yang mendengarkan (bacaan) Alquran, maka ketika mereka menghadiri (pembacaan)nya mereka berkata, \"Diamlah kamu! (untuk mendengarkannya)\" Maka ketika telah selesai, mereka kembali kepada kaumnya (untuk) memberi peringatan"},{id:30,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u064e\u0646\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0627 \u0633\u064e\u0645\u0650\u0639\u06e1\u0646\u064e\u0627 \u0643\u0650\u062a\u064e\u0670\u0628\u064b\u0627 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0645\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u0657\u0627 \u0644\u0651\u0650\u0645\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u06e1\u0647\u0650 \u064a\u064e\u0647\u06e1\u062f\u0650\u064a\u0653 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0625\u0650\u0644\u064e\u0649\u0670 \u0637\u064e\u0631\u0650\u064a\u0642\u0656 \u0645\u0651\u064f\u0633\u06e1\u062a\u064e\u0642\u0650\u064a\u0645\u0656",translation:"Mereka berkata, \"Wahai kaum kami! Sungguh, kami telah mendengarkan Kitab (Alquran) yang diturunkan setelah Musa, membenarkan (kitab-kitab) yang datang sebelumnya, membimbing kepada kebenaran, dan kepada jalan yang lurus"},{id:31,text:"\u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u064e\u0646\u064e\u0627\u0653 \u0623\u064e\u062c\u0650\u064a\u0628\u064f\u0648\u0627\u0652 \u062f\u064e\u0627\u0639\u0650\u064a\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0621\u064e\u0627\u0645\u0650\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6 \u064a\u064e\u063a\u06e1\u0641\u0650\u0631\u06e1 \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0630\u064f\u0646\u064f\u0648\u0628\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u064a\u064f\u062c\u0650\u0631\u06e1\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064d \u0623\u064e\u0644\u0650\u064a\u0645\u0656",translation:"Wahai kaum kami! Terimalah (seruan) orang (Muhammad) yang menyeru kepada Allah. Dan berimanlah kepada-Nya, niscaya Dia akan mengampuni dosa-dosamu, dan melepaskan kamu dari azab yang pedih"},{id:32,text:"\u0648\u064e\u0645\u064e\u0646 \u0644\u0651\u064e\u0627 \u064a\u064f\u062c\u0650\u0628\u06e1 \u062f\u064e\u0627\u0639\u0650\u064a\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0644\u064e\u064a\u06e1\u0633\u064e \u0628\u0650\u0645\u064f\u0639\u06e1\u062c\u0650\u0632\u0656 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0644\u064e\u064a\u06e1\u0633\u064e \u0644\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0648\u06e1\u0644\u0650\u064a\u064e\u0627\u0653\u0621\u064f\u06da \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0670\u0644\u0656 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u064d",translation:"Dan barangsiapa tidak menerima (seruan) orang yang menyeru kepada Allah (Muhammad) maka dia tidak akan dapat melepaskan diri dari siksaan Allah di bumi, padahal tidak ada pelindung baginya selain Allah. Mereka berada dalam kesesatan yang nyata"},{id:33,text:"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0631\u064e\u0648\u06e1\u0627\u0652 \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0639\u06e1\u064a\u064e \u0628\u0650\u062e\u064e\u0644\u06e1\u0642\u0650\u0647\u0650\u0646\u0651\u064e \u0628\u0650\u0642\u064e\u0670\u062f\u0650\u0631\u064d \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0646 \u064a\u064f\u062d\u06e1\u0640\u06e7\u0650\u064a\u064e \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u064e\u0649\u0670\u06da \u0628\u064e\u0644\u064e\u0649\u0670\u0653\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0642\u064e\u062f\u0650\u064a\u0631\u065e",translation:"Dan tidakkah mereka memperhatikan bahwa sesungguhnya Allah yang menciptakan langit dan bumi, dan Dia tidak merasa payah karena menciptakannya, dan Dia kuasa menghidupkan yang mati? Begitulah, sungguh, Dia Mahakuasa atas segala sesuatu"},{id:34,text:"\u0648\u064e\u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064f\u0639\u06e1\u0631\u064e\u0636\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0623\u064e\u0644\u064e\u064a\u06e1\u0633\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650\u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0628\u064e\u0644\u064e\u0649\u0670 \u0648\u064e\u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627\u06da \u0642\u064e\u0627\u0644\u064e \u0641\u064e\u0630\u064f\u0648\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0643\u06e1\u0641\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Dan (ingatlah) pada hari (ketika) orang-orang yang kafir dihadapkan kepada neraka, (mereka akan ditanya), \"Bukankah (azab) ini benar?\" Mereka menjawab, \"Ya benar, demi Tuhan kami.\" Allah berfirman, \"Maka rasakanlah azab ini, karena dahulu kamu mengingkarinya"},{id:35,text:"\u0641\u064e\u0671\u0635\u06e1\u0628\u0650\u0631\u06e1 \u0643\u064e\u0645\u064e\u0627 \u0635\u064e\u0628\u064e\u0631\u064e \u0623\u064f\u0648\u0652\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0639\u064e\u0632\u06e1\u0645\u0650 \u0645\u0650\u0646\u064e \u0671\u0644\u0631\u0651\u064f\u0633\u064f\u0644\u0650 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0633\u06e1\u062a\u064e\u0639\u06e1\u062c\u0650\u0644 \u0644\u0651\u064e\u0647\u064f\u0645\u06e1\u06da \u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064e\u0631\u064e\u0648\u06e1\u0646\u064e \u0645\u064e\u0627 \u064a\u064f\u0648\u0639\u064e\u062f\u064f\u0648\u0646\u064e \u0644\u064e\u0645\u06e1 \u064a\u064e\u0644\u06e1\u0628\u064e\u062b\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0633\u064e\u0627\u0639\u064e\u0629\u0657 \u0645\u0651\u0650\u0646 \u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650\u06ed\u06da \u0628\u064e\u0644\u064e\u0670\u063a\u065e\u06da \u0641\u064e\u0647\u064e\u0644\u06e1 \u064a\u064f\u0647\u06e1\u0644\u064e\u0643\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u064f \u0671\u0644\u06e1\u0641\u064e\u0670\u0633\u0650\u0642\u064f\u0648\u0646\u064e",translation:"Maka bersabarlah engkau (Muhammad) sebagaimana kesabaran rasul-rasul yang memiliki keteguhan hati, dan janganlah engkau meminta agar azab disegerakan untuk mereka. Pada hari mereka melihat azab yang dijanjikan, mereka merasa seolah-olah tinggal (di dunia) hanya sesaat saja dari siang hari. Tugasmu hanya menyampaikan. Maka tidak ada yang dibinasakan, kecuali kaum yang fasik (tidak taat kepada Allah)"}]},{id:47,name:"\u0645\u062d\u0645\u062f",transliteration:"Muhammad",translation:"Muhammad",type:"medinan",total_verses:38,verses:[{id:1,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u0635\u064e\u062f\u0651\u064f\u0648\u0627\u0652 \u0639\u064e\u0646 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0636\u064e\u0644\u0651\u064e \u0623\u064e\u0639\u06e1\u0645\u064e\u0670\u0644\u064e\u0647\u064f\u0645\u06e1",translation:"Orang-orang yang kafir dan menghalang-halangi (manusia) dari jalan Allah, maka Allah menghapus segala amal mereka"},{id:2,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0648\u064e\u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0645\u064e\u0627 \u0646\u064f\u0632\u0651\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064f\u062d\u064e\u0645\u0651\u064e\u062f\u0656 \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0643\u064e\u0641\u0651\u064e\u0631\u064e \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0633\u064e\u064a\u0651\u0650\u0640\u0654\u064e\u0627\u062a\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0623\u064e\u0635\u06e1\u0644\u064e\u062d\u064e \u0628\u064e\u0627\u0644\u064e\u0647\u064f\u0645\u06e1",translation:"Dan orang-orang yang beriman (kepada Allah) dan mengerjakan kebajikan serta beriman kepada apa yang diturunkan kepada Muhammad, dan itulah kebenaran dari Tuhan mereka; Allah menghapus kesalahan-kesalahan mereka, dan memperbaiki keadaan mereka"},{id:3,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0628\u064e\u0670\u0637\u0650\u0644\u064e \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064e \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1\u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064e\u0636\u06e1\u0631\u0650\u0628\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0623\u064e\u0645\u06e1\u062b\u064e\u0670\u0644\u064e\u0647\u064f\u0645\u06e1",translation:"Yang demikian itu, karena sesungguhnya orang-orang kafir mengikuti yang batil (sesat), dan sesungguhnya orang-orang yang beriman mengikuti kebenaran dari Tuhan mereka. Demikianlah Allah membuat perumpamaan-perumpamaan bagi manusia"},{id:4,text:"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0644\u064e\u0642\u0650\u064a\u062a\u064f\u0645\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0641\u064e\u0636\u064e\u0631\u06e1\u0628\u064e \u0671\u0644\u0631\u0651\u0650\u0642\u064e\u0627\u0628\u0650 \u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u064e\u0627\u0653 \u0623\u064e\u062b\u06e1\u062e\u064e\u0646\u062a\u064f\u0645\u064f\u0648\u0647\u064f\u0645\u06e1 \u0641\u064e\u0634\u064f\u062f\u0651\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0648\u064e\u062b\u064e\u0627\u0642\u064e \u0641\u064e\u0625\u0650\u0645\u0651\u064e\u0627 \u0645\u064e\u0646\u0651\u064e\u06e2\u0627 \u0628\u064e\u0639\u06e1\u062f\u064f \u0648\u064e\u0625\u0650\u0645\u0651\u064e\u0627 \u0641\u0650\u062f\u064e\u0627\u0653\u0621\u064b \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062a\u064e\u0636\u064e\u0639\u064e \u0671\u0644\u06e1\u062d\u064e\u0631\u06e1\u0628\u064f \u0623\u064e\u0648\u06e1\u0632\u064e\u0627\u0631\u064e\u0647\u064e\u0627\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e\u06d6 \u0648\u064e\u0644\u064e\u0648\u06e1 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0671\u0646\u062a\u064e\u0635\u064e\u0631\u064e \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u0644\u0651\u0650\u064a\u064e\u0628\u06e1\u0644\u064f\u0648\u064e\u0627\u0652 \u0628\u064e\u0639\u06e1\u0636\u064e\u0643\u064f\u0645 \u0628\u0650\u0628\u064e\u0639\u06e1\u0636\u0656\u06d7 \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0642\u064f\u062a\u0650\u0644\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0644\u064e\u0646 \u064a\u064f\u0636\u0650\u0644\u0651\u064e \u0623\u064e\u0639\u06e1\u0645\u064e\u0670\u0644\u064e\u0647\u064f\u0645\u06e1",translation:"Maka apabila kamu bertemu dengan orang-orang kafir (di medan perang), maka pukullah batang leher mereka. Selanjutnya apabila kamu telah mengalahkan mereka, tawanlah mereka, dan setelah itu kamu boleh membebaskan mereka atau menerima tebusan, sampai perang selesai. Demikianlah, dan sekiranya Allah menghendaki, niscaya Dia membinasakan mereka, tetapi Dia hendak menguji kamu satu sama lain. Dan orang-orang yang gugur di jalan Allah, maka Allah tidak akan menyia-nyiakan amal mereka"},{id:5,text:"\u0633\u064e\u064a\u064e\u0647\u06e1\u062f\u0650\u064a\u0647\u0650\u0645\u06e1 \u0648\u064e\u064a\u064f\u0635\u06e1\u0644\u0650\u062d\u064f \u0628\u064e\u0627\u0644\u064e\u0647\u064f\u0645\u06e1",translation:"Allah akan memberi petunjuk kepada mereka dan memperbaiki keadaan mereka"},{id:6,text:"\u0648\u064e\u064a\u064f\u062f\u06e1\u062e\u0650\u0644\u064f\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u064e \u0639\u064e\u0631\u0651\u064e\u0641\u064e\u0647\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u06e1",translation:"dan memasukkan mereka ke dalam surga yang telah diperkenalkan-Nya kepada mereka"},{id:7,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646 \u062a\u064e\u0646\u0635\u064f\u0631\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0646\u0635\u064f\u0631\u06e1\u0643\u064f\u0645\u06e1 \u0648\u064e\u064a\u064f\u062b\u064e\u0628\u0651\u0650\u062a\u06e1 \u0623\u064e\u0642\u06e1\u062f\u064e\u0627\u0645\u064e\u0643\u064f\u0645\u06e1",translation:"Wahai orang-orang yang beriman! Jika kamu menolong (agama) Allah, niscaya Dia akan menolongmu dan meneguhkan kedudukanmu"},{id:8,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0641\u064e\u062a\u064e\u0639\u06e1\u0633\u0657\u0627 \u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0636\u064e\u0644\u0651\u064e \u0623\u064e\u0639\u06e1\u0645\u064e\u0670\u0644\u064e\u0647\u064f\u0645\u06e1",translation:"Dan orang-orang yang kafir, maka celakalah mereka, dan Allah menghapus segala amalnya"},{id:9,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0631\u0650\u0647\u064f\u0648\u0627\u0652 \u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0623\u064e\u062d\u06e1\u0628\u064e\u0637\u064e \u0623\u064e\u0639\u06e1\u0645\u064e\u0670\u0644\u064e\u0647\u064f\u0645\u06e1",translation:"Yang demikian itu karena mereka membenci apa (Alquran) yang diturunkan Allah, maka Allah menghapus segala amal mereka"},{id:10,text:"\u06de\u0623\u064e\u0641\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0633\u0650\u064a\u0631\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0641\u064e\u064a\u064e\u0646\u0638\u064f\u0631\u064f\u0648\u0627\u0652 \u0643\u064e\u064a\u06e1\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0670\u0642\u0650\u0628\u064e\u0629\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u0645\u06e1\u06d6 \u062f\u064e\u0645\u0651\u064e\u0631\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1\u06d6 \u0648\u064e\u0644\u0650\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0623\u064e\u0645\u06e1\u062b\u064e\u0670\u0644\u064f\u0647\u064e\u0627",translation:"Maka apakah mereka tidak pernah mengadakan perjalanan di bumi, sehingga dapat memperhatikan bagaimana kesudahan orang-orang yang sebelum mereka. Allah telah membinasakan mereka, dan bagi orang-orang kafir akan menerima (nasib) yang serupa"},{id:11,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064e\u0648\u06e1\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u0645\u064e\u0648\u06e1\u0644\u064e\u0649\u0670 \u0644\u064e\u0647\u064f\u0645\u06e1",translation:"Yang demikian itu karena Allah pelindung bagi orang-orang yang beriman; sedang orang-orang kafir tidak ada pelindung bagi mereka"},{id:12,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u062f\u06e1\u062e\u0650\u0644\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0656 \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0645\u0650\u0646 \u062a\u064e\u062d\u06e1\u062a\u0650\u0647\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u064f\u06d6 \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u064a\u064e\u062a\u064e\u0645\u064e\u062a\u0651\u064e\u0639\u064f\u0648\u0646\u064e \u0648\u064e\u064a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f\u0648\u0646\u064e \u0643\u064e\u0645\u064e\u0627 \u062a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0639\u064e\u0670\u0645\u064f \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0627\u0631\u064f \u0645\u064e\u062b\u06e1\u0648\u0657\u0649 \u0644\u0651\u064e\u0647\u064f\u0645\u06e1",translation:"Sungguh, Allah akan memasukkan orang-orang yang beriman dan mengerjakan kebajikan ke dalam surga yang mengalir di bawahnya sungai-sungai. Dan orang-orang yang kafir menikmati kesenangan (dunia), dan mereka makan seperti hewan makan; dan (kelak) nerakalah tempat tinggal bagi mereka"},{id:13,text:"\u0648\u064e\u0643\u064e\u0623\u064e\u064a\u0651\u0650\u0646 \u0645\u0651\u0650\u0646 \u0642\u064e\u0631\u06e1\u064a\u064e\u0629\u064d \u0647\u0650\u064a\u064e \u0623\u064e\u0634\u064e\u062f\u0651\u064f \u0642\u064f\u0648\u0651\u064e\u0629\u0657 \u0645\u0651\u0650\u0646 \u0642\u064e\u0631\u06e1\u064a\u064e\u062a\u0650\u0643\u064e \u0671\u0644\u0651\u064e\u062a\u0650\u064a\u0653 \u0623\u064e\u062e\u06e1\u0631\u064e\u062c\u064e\u062a\u06e1\u0643\u064e \u0623\u064e\u0647\u06e1\u0644\u064e\u0643\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0641\u064e\u0644\u064e\u0627 \u0646\u064e\u0627\u0635\u0650\u0631\u064e \u0644\u064e\u0647\u064f\u0645\u06e1",translation:"Dan betapa banyak negeri yang (penduduknya) lebih kuat dari (penduduk) negerimu (Muhammad) yang telah mengusirmu. Kami telah membinasakan mereka; maka tidak ada seorang pun yang menolong mereka"},{id:14,text:"\u0623\u064e\u0641\u064e\u0645\u064e\u0646 \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0629\u0656 \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0647\u0650\u06e6 \u0643\u064e\u0645\u064e\u0646 \u0632\u064f\u064a\u0651\u0650\u0646\u064e \u0644\u064e\u0647\u064f\u06e5 \u0633\u064f\u0648\u0653\u0621\u064f \u0639\u064e\u0645\u064e\u0644\u0650\u0647\u0650\u06e6 \u0648\u064e\u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0647\u06e1\u0648\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645",translation:"Maka apakah orang yang berpegang pada keterangan yang datang dari Tuhannya sama dengan orang yang dijadikan terasa indah baginya perbuatan buruknya dan mengikuti keinginannya"},{id:15,text:"\u0645\u0651\u064e\u062b\u064e\u0644\u064f \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u0671\u0644\u0651\u064e\u062a\u0650\u064a \u0648\u064f\u0639\u0650\u062f\u064e \u0671\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e\u06d6 \u0641\u0650\u064a\u0647\u064e\u0627\u0653 \u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u065e \u0645\u0651\u0650\u0646 \u0645\u0651\u064e\u0627\u0653\u0621\u064d \u063a\u064e\u064a\u06e1\u0631\u0650 \u0621\u064e\u0627\u0633\u0650\u0646\u0656 \u0648\u064e\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u065e \u0645\u0651\u0650\u0646 \u0644\u0651\u064e\u0628\u064e\u0646\u0656 \u0644\u0651\u064e\u0645\u06e1 \u064a\u064e\u062a\u064e\u063a\u064e\u064a\u0651\u064e\u0631\u06e1 \u0637\u064e\u0639\u06e1\u0645\u064f\u0647\u064f\u06e5 \u0648\u064e\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u065e \u0645\u0651\u0650\u0646\u06e1 \u062e\u064e\u0645\u06e1\u0631\u0656 \u0644\u0651\u064e\u0630\u0651\u064e\u0629\u0656 \u0644\u0651\u0650\u0644\u0634\u0651\u064e\u0640\u0670\u0631\u0650\u0628\u0650\u064a\u0646\u064e \u0648\u064e\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u065e \u0645\u0651\u0650\u0646\u06e1 \u0639\u064e\u0633\u064e\u0644\u0656 \u0645\u0651\u064f\u0635\u064e\u0641\u0651\u0657\u0649\u06d6 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u0671\u0644\u062b\u0651\u064e\u0645\u064e\u0631\u064e\u0670\u062a\u0650 \u0648\u064e\u0645\u064e\u063a\u06e1\u0641\u0650\u0631\u064e\u0629\u065e \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1\u06d6 \u0643\u064e\u0645\u064e\u0646\u06e1 \u0647\u064f\u0648\u064e \u062e\u064e\u0670\u0644\u0650\u062f\u065e \u0641\u0650\u064a \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0648\u064e\u0633\u064f\u0642\u064f\u0648\u0627\u0652 \u0645\u064e\u0627\u0653\u0621\u064b \u062d\u064e\u0645\u0650\u064a\u0645\u0657\u0627 \u0641\u064e\u0642\u064e\u0637\u0651\u064e\u0639\u064e \u0623\u064e\u0645\u06e1\u0639\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u06e1",translation:"Perumpamaan taman surga yang dijanjikan kepada orang-orang yang bertakwa; di sana ada sungai-sungai yang airnya tidak payau, dan sungai-sungai air susu yang tidak berubah rasanya, dan sungai-sungai khamar (anggur yang tidak memabukkan) yang lezat rasanya bagi peminumnya, dan sungai-sungai madu yang murni. Di dalamnya mereka memperoleh segala macam buah-buahan, dan ampunan dari Tuhan mereka. Samakah mereka dengan orang yang kekal dalam neraka, dan diberi minuman dengan air yang mendidih, sehingga ususnya terpotong-potong"},{id:16,text:"\u0648\u064e\u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0646 \u064a\u064e\u0633\u06e1\u062a\u064e\u0645\u0650\u0639\u064f \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u064e\u0627 \u062e\u064e\u0631\u064e\u062c\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1 \u0639\u0650\u0646\u062f\u0650\u0643\u064e \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0639\u0650\u0644\u06e1\u0645\u064e \u0645\u064e\u0627\u0630\u064e\u0627 \u0642\u064e\u0627\u0644\u064e \u0621\u064e\u0627\u0646\u0650\u0641\u064b\u0627\u06da \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0637\u064e\u0628\u064e\u0639\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0647\u06e1\u0648\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u06e1",translation:"Dan di antara mereka ada orang yang mendengarkan perkataanmu (Muhammad), tetapi apabila mereka telah keluar dari sisimu, mereka berkata kepada orang yang telah diberi ilmu (sahabat-sahabat Nabi), \"Apakah yang dikatakannya tadi?\" Mereka itulah orang-orang yang dikunci hatinya oleh Allah, dan mengikuti keinginannya"},{id:17,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u0647\u06e1\u062a\u064e\u062f\u064e\u0648\u06e1\u0627\u0652 \u0632\u064e\u0627\u062f\u064e\u0647\u064f\u0645\u06e1 \u0647\u064f\u062f\u0657\u0649 \u0648\u064e\u0621\u064e\u0627\u062a\u064e\u0649\u0670\u0647\u064f\u0645\u06e1 \u062a\u064e\u0642\u06e1\u0648\u064e\u0649\u0670\u0647\u064f\u0645\u06e1",translation:"Dan orang-orang yang mendapat petunjuk, Allah akan menambah petunjuk kepada mereka dan menganugerahi ketakwaan pada mereka"},{id:18,text:"\u0641\u064e\u0647\u064e\u0644\u06e1 \u064a\u064e\u0646\u0638\u064f\u0631\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064e \u0623\u064e\u0646 \u062a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e\u0647\u064f\u0645 \u0628\u064e\u063a\u06e1\u062a\u064e\u0629\u0657\u06d6 \u0641\u064e\u0642\u064e\u062f\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e \u0623\u064e\u0634\u06e1\u0631\u064e\u0627\u0637\u064f\u0647\u064e\u0627\u06da \u0641\u064e\u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u062a\u06e1\u0647\u064f\u0645\u06e1 \u0630\u0650\u0643\u06e1\u0631\u064e\u0649\u0670\u0647\u064f\u0645\u06e1",translation:"Maka apalagi yang mereka tunggu-tunggu selain hari Kiamat, yang akan datang kepada mereka secara tiba-tiba, karena tanda-tandanya sungguh telah datang. Maka apa gunanya bagi mereka kesadaran mereka itu, apabila (hari Kiamat) itu sudah datang"},{id:19,text:"\u0641\u064e\u0671\u0639\u06e1\u0644\u064e\u0645\u06e1 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0671\u0633\u06e1\u062a\u064e\u063a\u06e1\u0641\u0650\u0631\u06e1 \u0644\u0650\u0630\u064e\u0646\u06e2\u0628\u0650\u0643\u064e \u0648\u064e\u0644\u0650\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064e\u0670\u062a\u0650\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064f\u062a\u064e\u0642\u064e\u0644\u0651\u064e\u0628\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0645\u064e\u062b\u06e1\u0648\u064e\u0649\u0670\u0643\u064f\u0645\u06e1",translation:"Maka ketahuilah, bahwa tidak ada tuhan (yang patut disembah) selain Allah, dan mohonlah ampunan atas dosamu dan atas (dosa) orang-orang mukmin, laki-laki dan perempuan. Dan Allah mengetahui tempat usaha dan tempat tinggalmu"},{id:20,text:"\u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0648\u06e1\u0644\u064e\u0627 \u0646\u064f\u0632\u0651\u0650\u0644\u064e\u062a\u06e1 \u0633\u064f\u0648\u0631\u064e\u0629\u065e\u06d6 \u0641\u064e\u0625\u0650\u0630\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e\u062a\u06e1 \u0633\u064f\u0648\u0631\u064e\u0629\u065e \u0645\u0651\u064f\u062d\u06e1\u0643\u064e\u0645\u064e\u0629\u065e \u0648\u064e\u0630\u064f\u0643\u0650\u0631\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0671\u0644\u06e1\u0642\u0650\u062a\u064e\u0627\u0644\u064f \u0631\u064e\u0623\u064e\u064a\u06e1\u062a\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645 \u0645\u0651\u064e\u0631\u064e\u0636\u065e \u064a\u064e\u0646\u0638\u064f\u0631\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0646\u064e\u0638\u064e\u0631\u064e \u0671\u0644\u06e1\u0645\u064e\u063a\u06e1\u0634\u0650\u064a\u0651\u0650 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u0650\u06d6 \u0641\u064e\u0623\u064e\u0648\u06e1\u0644\u064e\u0649\u0670 \u0644\u064e\u0647\u064f\u0645\u06e1",translation:"Dan orang-orang yang beriman berkata, \"Mengapa tidak ada suatu surah (tentang perintah jihad) yang diturunkan?\" Maka apabila ada suatu surah diturunkan yang jelas maksudnya dan di dalamnya terdapat (perintah) perang, engkau melihat orang-orang yang di dalam hatinya ada penyakit akan memandang kepadamu seperti pandangan orang yang pingsan karena takut mati. Tetapi itu lebih pantas bagi mereka"},{id:21,text:"\u0637\u064e\u0627\u0639\u064e\u0629\u065e \u0648\u064e\u0642\u064e\u0648\u06e1\u0644\u065e \u0645\u0651\u064e\u0639\u06e1\u0631\u064f\u0648\u0641\u065e\u06da \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0639\u064e\u0632\u064e\u0645\u064e \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0631\u064f \u0641\u064e\u0644\u064e\u0648\u06e1 \u0635\u064e\u062f\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0643\u064e\u0627\u0646\u064e \u062e\u064e\u064a\u06e1\u0631\u0657\u0627 \u0644\u0651\u064e\u0647\u064f\u0645\u06e1",translation:"(Yang lebih baik bagi mereka adalah) taat (kepada Allah) dan bertutur kata yang baik. Sebab apabila perintah (perang) ditetapkan (mereka tidak menyukainya). Padahal jika mereka benar-benar (beriman) kepada Allah, niscaya yang demikian itu lebih baik bagi mereka"},{id:22,text:"\u0641\u064e\u0647\u064e\u0644\u06e1 \u0639\u064e\u0633\u064e\u064a\u06e1\u062a\u064f\u0645\u06e1 \u0625\u0650\u0646 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u064a\u06e1\u062a\u064f\u0645\u06e1 \u0623\u064e\u0646 \u062a\u064f\u0641\u06e1\u0633\u0650\u062f\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u062a\u064f\u0642\u064e\u0637\u0651\u0650\u0639\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0631\u06e1\u062d\u064e\u0627\u0645\u064e\u0643\u064f\u0645\u06e1",translation:"Maka apakah sekiranya kamu berkuasa, lalu kamu akan berbuat kerusakan di bumi dan memutuskan hubungan kekeluargaan"},{id:23,text:"\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0639\u064e\u0646\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0623\u064e\u0635\u064e\u0645\u0651\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0639\u06e1\u0645\u064e\u0649\u0670\u0653 \u0623\u064e\u0628\u06e1\u0635\u064e\u0670\u0631\u064e\u0647\u064f\u0645\u06e1",translation:"Mereka itulah orang-orang yang dikutuk Allah; lalu dibuat tuli (pendengarannya) dan dibutakan penglihatannya"},{id:24,text:"\u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u062a\u064e\u062f\u064e\u0628\u0651\u064e\u0631\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u064e \u0623\u064e\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064f\u0644\u064f\u0648\u0628\u064d \u0623\u064e\u0642\u06e1\u0641\u064e\u0627\u0644\u064f\u0647\u064e\u0627\u0653",translation:"Maka tidakkah mereka menghayati Alquran, ataukah hati mereka sudah terkunci"},{id:25,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u0631\u06e1\u062a\u064e\u062f\u0651\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u062f\u06e1\u0628\u064e\u0670\u0631\u0650\u0647\u0650\u0645 \u0645\u0651\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0645\u064e\u0627 \u062a\u064e\u0628\u064e\u064a\u0651\u064e\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0647\u064f\u062f\u064e\u0649 \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u064f \u0633\u064e\u0648\u0651\u064e\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0645\u06e1\u0644\u064e\u0649\u0670 \u0644\u064e\u0647\u064f\u0645\u06e1",translation:"Sesungguhnya orang-orang yang berbalik (kepada kekafiran) setelah petunjuk itu jelas bagi mereka, setanlah yang merayu mereka dan memanjangkan angan-angan mereka"},{id:26,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0631\u0650\u0647\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u0646\u064e\u0632\u0651\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0633\u064e\u0646\u064f\u0637\u0650\u064a\u0639\u064f\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u0628\u064e\u0639\u06e1\u0636\u0650 \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0631\u0650\u06d6 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0625\u0650\u0633\u06e1\u0631\u064e\u0627\u0631\u064e\u0647\u064f\u0645\u06e1",translation:"Yang demikian itu, karena sesungguhnya mereka telah mengatakan kepada orang-orang (Yahudi) yang tidak senang kepada apa yang diturunkan Allah, \"Kami akan mematuhi kamu dalam beberapa urusan,\" tetapi Allah mengetahui rahasia mereka"},{id:27,text:"\u0641\u064e\u0643\u064e\u064a\u06e1\u0641\u064e \u0625\u0650\u0630\u064e\u0627 \u062a\u064e\u0648\u064e\u0641\u0651\u064e\u062a\u06e1\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u064f \u064a\u064e\u0636\u06e1\u0631\u0650\u0628\u064f\u0648\u0646\u064e \u0648\u064f\u062c\u064f\u0648\u0647\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u062f\u06e1\u0628\u064e\u0670\u0631\u064e\u0647\u064f\u0645\u06e1",translation:"Maka bagaimana (nasib mereka) apabila malaikat (maut) mencabut nyawa mereka, memukul wajah dan punggung mereka"},{id:28,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u064f \u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0627\u0652 \u0645\u064e\u0627\u0653 \u0623\u064e\u0633\u06e1\u062e\u064e\u0637\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0643\u064e\u0631\u0650\u0647\u064f\u0648\u0627\u0652 \u0631\u0650\u0636\u06e1\u0648\u064e\u0670\u0646\u064e\u0647\u064f\u06e5 \u0641\u064e\u0623\u064e\u062d\u06e1\u0628\u064e\u0637\u064e \u0623\u064e\u0639\u06e1\u0645\u064e\u0670\u0644\u064e\u0647\u064f\u0645\u06e1",translation:"Yang demikian itu, karena sesungguhnya mereka mengikuti apa yang menimbulkan kemurkaan Allah dan membenci (apa yang menimbulkan) keridaan-Nya; sebab itu Allah menghapus segala amal mereka"},{id:29,text:"\u0623\u064e\u0645\u06e1 \u062d\u064e\u0633\u0650\u0628\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645 \u0645\u0651\u064e\u0631\u064e\u0636\u064c \u0623\u064e\u0646 \u0644\u0651\u064e\u0646 \u064a\u064f\u062e\u06e1\u0631\u0650\u062c\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0636\u06e1\u063a\u064e\u0670\u0646\u064e\u0647\u064f\u0645\u06e1",translation:"Atau apakah orang-orang yang dalam hatinya ada penyakit mengira bahwa Allah tidak akan menampakkan kedengkian mereka"},{id:30,text:"\u0648\u064e\u0644\u064e\u0648\u06e1 \u0646\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0644\u064e\u0623\u064e\u0631\u064e\u064a\u06e1\u0646\u064e\u0670\u0643\u064e\u0647\u064f\u0645\u06e1 \u0641\u064e\u0644\u064e\u0639\u064e\u0631\u064e\u0641\u06e1\u062a\u064e\u0647\u064f\u0645 \u0628\u0650\u0633\u0650\u064a\u0645\u064e\u0670\u0647\u064f\u0645\u06e1\u06da \u0648\u064e\u0644\u064e\u062a\u064e\u0639\u06e1\u0631\u0650\u0641\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0644\u064e\u062d\u06e1\u0646\u0650 \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0644\u0650\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0623\u064e\u0639\u06e1\u0645\u064e\u0670\u0644\u064e\u0643\u064f\u0645\u06e1",translation:"Dan sekiranya Kami menghendaki, niscaya Kami perlihatkan mereka kepadamu (Muhammad) sehingga engkau benar-benar dapat mengenal mereka dengan tanda-tandanya. Dan engkau benar-benar akan mengenal mereka dari nada bicaranya, dan Allah mengetahui segala perbuatan kamu"},{id:31,text:"\u0648\u064e\u0644\u064e\u0646\u064e\u0628\u06e1\u0644\u064f\u0648\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0646\u064e\u0639\u06e1\u0644\u064e\u0645\u064e \u0671\u0644\u06e1\u0645\u064f\u062c\u064e\u0670\u0647\u0650\u062f\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u0648\u064e\u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0628\u0650\u0631\u0650\u064a\u0646\u064e \u0648\u064e\u0646\u064e\u0628\u06e1\u0644\u064f\u0648\u064e\u0627\u0652 \u0623\u064e\u062e\u06e1\u0628\u064e\u0627\u0631\u064e\u0643\u064f\u0645\u06e1",translation:"Dan sungguh, Kami benar-benar akan menguji kamu sehingga Kami mengetahui orang-orang yang benar-benar berjihad dan bersabar di antara kamu; dan akan Kami uji perihal kamu"},{id:32,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u0635\u064e\u062f\u0651\u064f\u0648\u0627\u0652 \u0639\u064e\u0646 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0634\u064e\u0627\u0653\u0642\u0651\u064f\u0648\u0627\u0652 \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0645\u064e\u0627 \u062a\u064e\u0628\u064e\u064a\u0651\u064e\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0647\u064f\u062f\u064e\u0649\u0670 \u0644\u064e\u0646 \u064a\u064e\u0636\u064f\u0631\u0651\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627 \u0648\u064e\u0633\u064e\u064a\u064f\u062d\u06e1\u0628\u0650\u0637\u064f \u0623\u064e\u0639\u06e1\u0645\u064e\u0670\u0644\u064e\u0647\u064f\u0645\u06e1",translation:"Sesungguhnya orang-orang yang kafir dan menghalang-halangi (orang lain) dari jalan Allah serta memusuhi rasul setelah ada petunjuk yang jelas bagi mereka, mereka tidak akan dapat memberi mudarat (bahaya) kepada Allah sedikit pun. Dan kelak Allah akan menghapus segala amal mereka"},{id:33,text:"\u06de\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0627\u0652 \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0628\u06e1\u0637\u0650\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0639\u06e1\u0645\u064e\u0670\u0644\u064e\u0643\u064f\u0645\u06e1",translation:"Wahai orang-orang yang beriman! Taatlah kepada Allah dan taatlah kepada Rasul, dan janganlah kamu merusakkan segala amalmu"},{id:34,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u0635\u064e\u062f\u0651\u064f\u0648\u0627\u0652 \u0639\u064e\u0646 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062b\u064f\u0645\u0651\u064e \u0645\u064e\u0627\u062a\u064f\u0648\u0627\u0652 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0643\u064f\u0641\u0651\u064e\u0627\u0631\u065e \u0641\u064e\u0644\u064e\u0646 \u064a\u064e\u063a\u06e1\u0641\u0650\u0631\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0647\u064f\u0645\u06e1",translation:"Sesungguhnya orang-orang yang kafir dan menghalang-halangi (orang lain) dari jalan Allah, kemudian mereka mati dalam keadaan kafir, maka Allah tidak akan mengampuni mereka"},{id:35,text:"\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0647\u0650\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u062a\u064e\u062f\u06e1\u0639\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0633\u0651\u064e\u0644\u06e1\u0645\u0650 \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u0639\u06e1\u0644\u064e\u0648\u06e1\u0646\u064e \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0639\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0646 \u064a\u064e\u062a\u0650\u0631\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u0639\u06e1\u0645\u064e\u0670\u0644\u064e\u0643\u064f\u0645\u06e1",translation:"Maka janganlah kamu lemah dan mengajak damai, karena kamulah yang lebih unggul, dan Allah (pun) bersama kamu, dan Dia tidak akan mengurangi segala amalmu"},{id:36,text:"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u064f \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0644\u064e\u0639\u0650\u0628\u065e \u0648\u064e\u0644\u064e\u0647\u06e1\u0648\u065e\u06da \u0648\u064e\u0625\u0650\u0646 \u062a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u064a\u064f\u0624\u06e1\u062a\u0650\u0643\u064f\u0645\u06e1 \u0623\u064f\u062c\u064f\u0648\u0631\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u06e1\u0643\u064f\u0645\u06e1 \u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u064e\u0643\u064f\u0645\u06e1",translation:"Sesungguhnya kehidupan dunia itu hanyalah permainan dan senda gurau. Jika kamu beriman serta bertakwa, Allah akan memberikan pahala kepadamu, dan Dia tidak akan meminta hartamu"},{id:37,text:"\u0625\u0650\u0646 \u064a\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u06e1\u0643\u064f\u0645\u064f\u0648\u0647\u064e\u0627 \u0641\u064e\u064a\u064f\u062d\u06e1\u0641\u0650\u0643\u064f\u0645\u06e1 \u062a\u064e\u0628\u06e1\u062e\u064e\u0644\u064f\u0648\u0627\u0652 \u0648\u064e\u064a\u064f\u062e\u06e1\u0631\u0650\u062c\u06e1 \u0623\u064e\u0636\u06e1\u063a\u064e\u0670\u0646\u064e\u0643\u064f\u0645\u06e1",translation:"Sekiranya Dia meminta harta kepadamu lalu mendesak kamu (agar memberikan semuanya) niscaya kamu akan kikir, dan Dia akan menampakkan kedengkianmu"},{id:38,text:"\u0647\u064e\u0640\u0670\u0653\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650 \u062a\u064f\u062f\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0644\u0650\u062a\u064f\u0646\u0641\u0650\u0642\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0645\u0650\u0646\u0643\u064f\u0645 \u0645\u0651\u064e\u0646 \u064a\u064e\u0628\u06e1\u062e\u064e\u0644\u064f\u06d6 \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0628\u06e1\u062e\u064e\u0644\u06e1 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0628\u06e1\u062e\u064e\u0644\u064f \u0639\u064e\u0646 \u0646\u0651\u064e\u0641\u06e1\u0633\u0650\u0647\u0650\u06e6\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u063a\u064e\u0646\u0650\u064a\u0651\u064f \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u064f \u0671\u0644\u06e1\u0641\u064f\u0642\u064e\u0631\u064e\u0627\u0653\u0621\u064f\u06da \u0648\u064e\u0625\u0650\u0646 \u062a\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u06e1\u0627\u0652 \u064a\u064e\u0633\u06e1\u062a\u064e\u0628\u06e1\u062f\u0650\u0644\u06e1 \u0642\u064e\u0648\u06e1\u0645\u064b\u0627 \u063a\u064e\u064a\u06e1\u0631\u064e\u0643\u064f\u0645\u06e1 \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0627 \u064a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0645\u06e1\u062b\u064e\u0670\u0644\u064e\u0643\u064f\u0645",translation:"Ingatlah, kamu adalah orang-orang yang diajak untuk menginfakkan (hartamu) di jalan Allah. Lalu di antara kamu ada orang yang kikir, dan barangsiapa kikir maka sesungguhnya dia kikir terhadap dirinya sendiri. Dan Allah lah Yang Mahakaya, dan kamulah yang membutuhkan (karunia-Nya). Dan jika kamu berpaling (dari jalan yang benar) Dia akan menggantikan (kamu) dengan kaum yang lain, dan mereka tidak akan (durhaka) seperti kamu"}]},{id:48,name:"\u0627\u0644\u0641\u062a\u062d",transliteration:"Al-Fath",translation:"Kemenangan",type:"medinan",total_verses:29,verses:[{id:1,text:"\u0625\u0650\u0646\u0651\u064e\u0627 \u0641\u064e\u062a\u064e\u062d\u06e1\u0646\u064e\u0627 \u0644\u064e\u0643\u064e \u0641\u064e\u062a\u06e1\u062d\u0657\u0627 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u0657\u0627",translation:"Sungguh, Kami telah memberikan kepadamu kemenangan yang nyata"},{id:2,text:"\u0644\u0651\u0650\u064a\u064e\u063a\u06e1\u0641\u0650\u0631\u064e \u0644\u064e\u0643\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0627 \u062a\u064e\u0642\u064e\u062f\u0651\u064e\u0645\u064e \u0645\u0650\u0646 \u0630\u064e\u0646\u06e2\u0628\u0650\u0643\u064e \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0623\u064e\u062e\u0651\u064e\u0631\u064e \u0648\u064e\u064a\u064f\u062a\u0650\u0645\u0651\u064e \u0646\u0650\u0639\u06e1\u0645\u064e\u062a\u064e\u0647\u064f\u06e5 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0648\u064e\u064a\u064e\u0647\u06e1\u062f\u0650\u064a\u064e\u0643\u064e \u0635\u0650\u0631\u064e\u0670\u0637\u0657\u0627 \u0645\u0651\u064f\u0633\u06e1\u062a\u064e\u0642\u0650\u064a\u0645\u0657\u0627",translation:"Agar Allah memberikan ampunan kepadamu (Muhammad) atas dosamu yang lalu dan yang akan datang, serta menyempurnakan nikmat-Nya atasmu dan menunjukimu ke jalan yang lurus"},{id:3,text:"\u0648\u064e\u064a\u064e\u0646\u0635\u064f\u0631\u064e\u0643\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0646\u064e\u0635\u06e1\u0631\u064b\u0627 \u0639\u064e\u0632\u0650\u064a\u0632\u064b\u0627",translation:"dan agar Allah menolongmu dengan pertolongan yang kuat (banyak)"},{id:4,text:"\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0671\u0644\u0633\u0651\u064e\u0643\u0650\u064a\u0646\u064e\u0629\u064e \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0644\u0650\u064a\u064e\u0632\u06e1\u062f\u064e\u0627\u062f\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u064a\u0645\u064e\u0670\u0646\u0657\u0627 \u0645\u0651\u064e\u0639\u064e \u0625\u0650\u064a\u0645\u064e\u0670\u0646\u0650\u0647\u0650\u0645\u06e1\u06d7 \u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u062c\u064f\u0646\u064f\u0648\u062f\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064b\u0627 \u062d\u064e\u0643\u0650\u064a\u0645\u0657\u0627",translation:"Dialah yang telah menurunkan ketenangan ke dalam hati orang-orang mukmin untuk menambah keimanan atas keimanan mereka (yang telah ada). Dan milik Allah lah bala tentara langit dan bumi,806) dan Allah Maha Mengetahui, Mahabijaksana"},{id:5,text:"\u0644\u0651\u0650\u064a\u064f\u062f\u06e1\u062e\u0650\u0644\u064e \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064e\u0670\u062a\u0650 \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0656 \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0645\u0650\u0646 \u062a\u064e\u062d\u06e1\u062a\u0650\u0647\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u064f \u062e\u064e\u0670\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u064a\u064f\u0643\u064e\u0641\u0651\u0650\u0631\u064e \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0633\u064e\u064a\u0651\u0650\u0640\u0654\u064e\u0627\u062a\u0650\u0647\u0650\u0645\u06e1\u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0648\u06e1\u0632\u064b\u0627 \u0639\u064e\u0638\u0650\u064a\u0645\u0657\u0627",translation:"Agar Dia masukkan orang-orang mukmin laki-laki dan perempuan ke dalam surga yang mengalir di bawahnya sungai-sungai. Mereka kekal di dalamnya dan Dia akan menghapus kesalahan-kesalahan mereka. Dan yang demikian itu menurut Allah suatu keuntungan yang besar"},{id:6,text:"\u0648\u064e\u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064e \u0671\u0644\u06e1\u0645\u064f\u0646\u064e\u0670\u0641\u0650\u0642\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0646\u064e\u0670\u0641\u0650\u0642\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0634\u06e1\u0631\u0650\u0643\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0634\u06e1\u0631\u0650\u0643\u064e\u0670\u062a\u0650 \u0671\u0644\u0638\u0651\u064e\u0627\u0653\u0646\u0651\u0650\u064a\u0646\u064e \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0638\u064e\u0646\u0651\u064e \u0671\u0644\u0633\u0651\u064e\u0648\u06e1\u0621\u0650\u06da \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u062f\u064e\u0627\u0653\u0626\u0650\u0631\u064e\u0629\u064f \u0671\u0644\u0633\u0651\u064e\u0648\u06e1\u0621\u0650\u06d6 \u0648\u064e\u063a\u064e\u0636\u0650\u0628\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0648\u064e\u0644\u064e\u0639\u064e\u0646\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0639\u064e\u062f\u0651\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e\u06d6 \u0648\u064e\u0633\u064e\u0627\u0653\u0621\u064e\u062a\u06e1 \u0645\u064e\u0635\u0650\u064a\u0631\u0657\u0627",translation:"dan Dia mengazab orang-orang munafik laki-laki dan perempuan, dan (juga) orang-orang musyrik laki-laki dan perempuan yang berprasangka buruk terhadap Allah. Mereka akan mendapat giliran (azab) yang buruk, dan Allah murka kepada mereka dan mengutuk mereka, serta menyediakan neraka Jahanam bagi mereka. Dan (neraka Jahanam) itu seburuk-buruk tempat kembali"},{id:7,text:"\u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u062c\u064f\u0646\u064f\u0648\u062f\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0632\u0650\u064a\u0632\u064b\u0627 \u062d\u064e\u0643\u0650\u064a\u0645\u064b\u0627",translation:"Dan milik Allah bala tentara langit dan bumi. Dan Allah Mahaperkasa, Mahabijaksana"},{id:8,text:"\u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0670\u0643\u064e \u0634\u064e\u0670\u0647\u0650\u062f\u0657\u0627 \u0648\u064e\u0645\u064f\u0628\u064e\u0634\u0651\u0650\u0631\u0657\u0627 \u0648\u064e\u0646\u064e\u0630\u0650\u064a\u0631\u0657\u0627",translation:"Sungguh, Kami mengutus engkau (Muhammad) sebagai saksi, pembawa berita gembira dan pemberi peringatan"},{id:9,text:"\u0644\u0651\u0650\u062a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650\u06e6 \u0648\u064e\u062a\u064f\u0639\u064e\u0632\u0651\u0650\u0631\u064f\u0648\u0647\u064f \u0648\u064e\u062a\u064f\u0648\u064e\u0642\u0651\u0650\u0631\u064f\u0648\u0647\u064f\u06da \u0648\u064e\u062a\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u064f\u0648\u0647\u064f \u0628\u064f\u0643\u06e1\u0631\u064e\u0629\u0657 \u0648\u064e\u0623\u064e\u0635\u0650\u064a\u0644\u064b\u0627",translation:"agar kamu semua beriman kepada Allah dan Rasul-Nya, menguatkan (agama)-Nya, membesarkan-Nya, dan bertasbih kepada-Nya pagi dan petang"},{id:10,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0628\u064e\u0627\u064a\u0650\u0639\u064f\u0648\u0646\u064e\u0643\u064e \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064f\u0628\u064e\u0627\u064a\u0650\u0639\u064f\u0648\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u062f\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0648\u06e1\u0642\u064e \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u0647\u0650\u0645\u06e1\u06da \u0641\u064e\u0645\u064e\u0646 \u0646\u0651\u064e\u0643\u064e\u062b\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0646\u0643\u064f\u062b\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0646\u064e\u0641\u06e1\u0633\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u0645\u064e\u0646\u06e1 \u0623\u064e\u0648\u06e1\u0641\u064e\u0649\u0670 \u0628\u0650\u0645\u064e\u0627 \u0639\u064e\u0670\u0647\u064e\u062f\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0641\u064e\u0633\u064e\u064a\u064f\u0624\u06e1\u062a\u0650\u064a\u0647\u0650 \u0623\u064e\u062c\u06e1\u0631\u064b\u0627 \u0639\u064e\u0638\u0650\u064a\u0645\u0657\u0627",translation:"Bahwa orang-orang yang berjanji setia kepadamu (Muhammad), sesungguhnya mereka hanya berjanji setia kepada Allah. Tangan Allah di atas tangan-tangan mereka, maka barangsiapa melanggar janji, maka sesungguhnya dia melanggar atas (janji) sendiri; dan barangsiapa menepati janjinya kepada Allah, maka Dia akan memberinya pahala yang besar"},{id:11,text:"\u0633\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0644\u064e\u0643\u064e \u0671\u0644\u06e1\u0645\u064f\u062e\u064e\u0644\u0651\u064e\u0641\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u0639\u06e1\u0631\u064e\u0627\u0628\u0650 \u0634\u064e\u063a\u064e\u0644\u064e\u062a\u06e1\u0646\u064e\u0627\u0653 \u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u064f\u0646\u064e\u0627 \u0648\u064e\u0623\u064e\u0647\u06e1\u0644\u064f\u0648\u0646\u064e\u0627 \u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u063a\u06e1\u0641\u0650\u0631\u06e1 \u0644\u064e\u0646\u064e\u0627\u06da \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0628\u0650\u0623\u064e\u0644\u06e1\u0633\u0650\u0646\u064e\u062a\u0650\u0647\u0650\u0645 \u0645\u0651\u064e\u0627 \u0644\u064e\u064a\u06e1\u0633\u064e \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u06e1\u06da \u0642\u064f\u0644\u06e1 \u0641\u064e\u0645\u064e\u0646 \u064a\u064e\u0645\u06e1\u0644\u0650\u0643\u064f \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0634\u064e\u064a\u06e1\u0640\u0654\u064b\u0627 \u0625\u0650\u0646\u06e1 \u0623\u064e\u0631\u064e\u0627\u062f\u064e \u0628\u0650\u0643\u064f\u0645\u06e1 \u0636\u064e\u0631\u0651\u064b\u0627 \u0623\u064e\u0648\u06e1 \u0623\u064e\u0631\u064e\u0627\u062f\u064e \u0628\u0650\u0643\u064f\u0645\u06e1 \u0646\u064e\u0641\u06e1\u0639\u064e\u06e2\u0627\u06da \u0628\u064e\u0644\u06e1 \u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u062e\u064e\u0628\u0650\u064a\u0631\u064e\u06e2\u0627",translation:"Orang-orang Badui yang tertinggal (tidak turut ke Hudaibiyah) akan berkata kepadamu, \"Kami telah disibukkan oleh harta dan keluarga kami, maka mohonkanlah ampunan untuk kami.\" Mereka mengucapkan sesuatu dengan mulutnya apa yang tidak ada dalam hatinya. Katakanlah, \"Maka siapakah yang dapat menghalang-halangi kehendak Allah jika Dia menghendaki bencana terhadap kamu atau jika Dia menghendaki keuntungan bagimu? Sungguh, Allah Mahateliti dengan apa yang kamu kerjakan"},{id:12,text:"\u0628\u064e\u0644\u06e1 \u0638\u064e\u0646\u064e\u0646\u062a\u064f\u0645\u06e1 \u0623\u064e\u0646 \u0644\u0651\u064e\u0646 \u064a\u064e\u0646\u0642\u064e\u0644\u0650\u0628\u064e \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064f \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0647\u06e1\u0644\u0650\u064a\u0647\u0650\u0645\u06e1 \u0623\u064e\u0628\u064e\u062f\u0657\u0627 \u0648\u064e\u0632\u064f\u064a\u0651\u0650\u0646\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0638\u064e\u0646\u064e\u0646\u062a\u064f\u0645\u06e1 \u0638\u064e\u0646\u0651\u064e \u0671\u0644\u0633\u0651\u064e\u0648\u06e1\u0621\u0650 \u0648\u064e\u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0642\u064e\u0648\u06e1\u0645\u064e\u06e2\u0627 \u0628\u064f\u0648\u0631\u0657\u0627",translation:"Bahkan (semula) kamu menyangka bahwa Rasul dan orang-orang mukmin sekali-kali tidak akan kembali lagi kepada keluarga mereka selama-lamanya, dan dijadikan terasa indah yang demikian itu di dalam hatimu, dan kamu telah berprasangka dengan prasangka yang buruk, karena itu kamu menjadi kaum yang binasa"},{id:13,text:"\u0648\u064e\u0645\u064e\u0646 \u0644\u0651\u064e\u0645\u06e1 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u06e2 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650\u06e6 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u0639\u06e1\u062a\u064e\u062f\u06e1\u0646\u064e\u0627 \u0644\u0650\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0633\u064e\u0639\u0650\u064a\u0631\u0657\u0627",translation:"Dan barangsiapa tidak beriman kepada Allah dan Rasul-Nya, maka sesungguhnya Kami telah menyediakan untuk orang-orang kafir itu neraka yang menyala-nyala"},{id:14,text:"\u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064f\u0644\u06e1\u0643\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06da \u064a\u064e\u063a\u06e1\u0641\u0650\u0631\u064f \u0644\u0650\u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0648\u064e\u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064f \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u0657\u0627 \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0657\u0627",translation:"Dan hanya milik Allah kerajaan langit dan bumi. Dia mengampuni siapa yang Dia kehendaki, dan akan mengazab siapa yang Dia kehendaki. Dan Allah Maha Pengampun, Maha Penyayang"},{id:15,text:"\u0633\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0671\u0644\u06e1\u0645\u064f\u062e\u064e\u0644\u0651\u064e\u0641\u064f\u0648\u0646\u064e \u0625\u0650\u0630\u064e\u0627 \u0671\u0646\u0637\u064e\u0644\u064e\u0642\u06e1\u062a\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064e\u063a\u064e\u0627\u0646\u0650\u0645\u064e \u0644\u0650\u062a\u064e\u0623\u06e1\u062e\u064f\u0630\u064f\u0648\u0647\u064e\u0627 \u0630\u064e\u0631\u064f\u0648\u0646\u064e\u0627 \u0646\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u06e1\u0643\u064f\u0645\u06e1\u06d6 \u064a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0623\u064e\u0646 \u064a\u064f\u0628\u064e\u062f\u0651\u0650\u0644\u064f\u0648\u0627\u0652 \u0643\u064e\u0644\u064e\u0670\u0645\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0642\u064f\u0644 \u0644\u0651\u064e\u0646 \u062a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0646\u064e\u0627 \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u06e1 \u0642\u064e\u0627\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f\u06d6 \u0641\u064e\u0633\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0628\u064e\u0644\u06e1 \u062a\u064e\u062d\u06e1\u0633\u064f\u062f\u064f\u0648\u0646\u064e\u0646\u064e\u0627\u06da \u0628\u064e\u0644\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u064a\u064e\u0641\u06e1\u0642\u064e\u0647\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u0657\u0627",translation:"Apabila kamu berangkat untuk mengambil barang rampasan, orang-orang Badui yang tertinggal itu akan berkata, \"Biarkanlah kami mengikuti kamu.\" Mereka hendak mengubah janji Allah. Katakanlah, \"Kamu sekali-kali tidak (boleh) mengikuti kami. Demikianlah yang telah ditetapkan Allah sejak semula.\" Maka mereka akan berkata, \"Sebenarnya kamu dengki kepada kami.\" Padahal mereka tidak mengerti melainkan sedikit sekali"},{id:16,text:"\u0642\u064f\u0644 \u0644\u0651\u0650\u0644\u06e1\u0645\u064f\u062e\u064e\u0644\u0651\u064e\u0641\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u0639\u06e1\u0631\u064e\u0627\u0628\u0650 \u0633\u064e\u062a\u064f\u062f\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u06e1\u0645\u064d \u0623\u064f\u0648\u0652\u0644\u0650\u064a \u0628\u064e\u0623\u06e1\u0633\u0656 \u0634\u064e\u062f\u0650\u064a\u062f\u0656 \u062a\u064f\u0642\u064e\u0670\u062a\u0650\u0644\u064f\u0648\u0646\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1 \u064a\u064f\u0633\u06e1\u0644\u0650\u0645\u064f\u0648\u0646\u064e\u06d6 \u0641\u064e\u0625\u0650\u0646 \u062a\u064f\u0637\u0650\u064a\u0639\u064f\u0648\u0627\u0652 \u064a\u064f\u0624\u06e1\u062a\u0650\u0643\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u062c\u06e1\u0631\u064b\u0627 \u062d\u064e\u0633\u064e\u0646\u0657\u0627\u06d6 \u0648\u064e\u0625\u0650\u0646 \u062a\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u06e1\u0627\u0652 \u0643\u064e\u0645\u064e\u0627 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u064a\u06e1\u062a\u064f\u0645 \u0645\u0651\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f \u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u06e1\u0643\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0623\u064e\u0644\u0650\u064a\u0645\u0657\u0627",translation:"Katakanlah kepada orang-orang Badui yang tertinggal, \"Kamu akan diajak untuk (memerangi) kaum yang mempunyai kekuatan yang besar, kamu harus memerangi mereka kecuali mereka menyerah. Jika kamu patuhi (ajakan itu), Allah akan memberimu pahala yang baik; tetapi jika kamu berpaling seperti yang kamu perbuat sebelumnya, Dia akan mengazab kamu dengan azab yang pedih"},{id:17,text:"\u0644\u0651\u064e\u064a\u06e1\u0633\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0623\u064e\u0639\u06e1\u0645\u064e\u0649\u0670 \u062d\u064e\u0631\u064e\u062c\u065e \u0648\u064e\u0644\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0623\u064e\u0639\u06e1\u0631\u064e\u062c\u0650 \u062d\u064e\u0631\u064e\u062c\u065e \u0648\u064e\u0644\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0645\u064e\u0631\u0650\u064a\u0636\u0650 \u062d\u064e\u0631\u064e\u062c\u065e\u06d7 \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0637\u0650\u0639\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f\u06e5 \u064a\u064f\u062f\u06e1\u062e\u0650\u0644\u06e1\u0647\u064f \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0656 \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0645\u0650\u0646 \u062a\u064e\u062d\u06e1\u062a\u0650\u0647\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u064f\u06d6 \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e \u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u06e1\u0647\u064f \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0623\u064e\u0644\u0650\u064a\u0645\u0657\u0627",translation:"Tidak ada dosa atas orang-orang yang buta, atas orang-orang yang pincang, dan atas orang-orang yang sakit (apabila tidak ikut berperang). Barangsiapa taat kepada Allah dan Rasul-Nya, Dia akan memasukkannya ke dalam surga yang mengalir di bawahnya sungai-sungai; tetapi barangsiapa berpaling, Dia akan mengazabnya dengan azab yang pedih"},{id:18,text:"\u06de\u0644\u0651\u064e\u0642\u064e\u062f\u06e1 \u0631\u064e\u0636\u0650\u064a\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0646\u0650 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0625\u0650\u0630\u06e1 \u064a\u064f\u0628\u064e\u0627\u064a\u0650\u0639\u064f\u0648\u0646\u064e\u0643\u064e \u062a\u064e\u062d\u06e1\u062a\u064e \u0671\u0644\u0634\u0651\u064e\u062c\u064e\u0631\u064e\u0629\u0650 \u0641\u064e\u0639\u064e\u0644\u0650\u0645\u064e \u0645\u064e\u0627 \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u06e1 \u0641\u064e\u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0671\u0644\u0633\u0651\u064e\u0643\u0650\u064a\u0646\u064e\u0629\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0648\u064e\u0623\u064e\u062b\u064e\u0670\u0628\u064e\u0647\u064f\u0645\u06e1 \u0641\u064e\u062a\u06e1\u062d\u0657\u0627 \u0642\u064e\u0631\u0650\u064a\u0628\u0657\u0627",translation:"Sungguh, Allah telah meridai orang-orang mukmin ketika mereka berjanji setia kepadamu (Muhammad) di bawah pohon, Dia mengetahui apa yang ada dalam hati mereka, lalu Dia memberikan ketenangan atas mereka dan memberi balasan dengan kemenangan yang dekat"},{id:19,text:"\u0648\u064e\u0645\u064e\u063a\u064e\u0627\u0646\u0650\u0645\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u064e\u0629\u0657 \u064a\u064e\u0623\u06e1\u062e\u064f\u0630\u064f\u0648\u0646\u064e\u0647\u064e\u0627\u06d7 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0632\u0650\u064a\u0632\u064b\u0627 \u062d\u064e\u0643\u0650\u064a\u0645\u0657\u0627",translation:"dan harta rampasan perang yang banyak yang akan mereka peroleh. Dan Allah Mahaperkasa, Mahabijaksana"},{id:20,text:"\u0648\u064e\u0639\u064e\u062f\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u063a\u064e\u0627\u0646\u0650\u0645\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u064e\u0629\u0657 \u062a\u064e\u0623\u06e1\u062e\u064f\u0630\u064f\u0648\u0646\u064e\u0647\u064e\u0627 \u0641\u064e\u0639\u064e\u062c\u0651\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u06e1 \u0647\u064e\u0670\u0630\u0650\u0647\u0650\u06e6 \u0648\u064e\u0643\u064e\u0641\u0651\u064e \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0639\u064e\u0646\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u0650\u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0621\u064e\u0627\u064a\u064e\u0629\u0657 \u0644\u0651\u0650\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u064a\u064e\u0647\u06e1\u062f\u0650\u064a\u064e\u0643\u064f\u0645\u06e1 \u0635\u0650\u0631\u064e\u0670\u0637\u0657\u0627 \u0645\u0651\u064f\u0633\u06e1\u062a\u064e\u0642\u0650\u064a\u0645\u0657\u0627",translation:"Allah menjanjikan kepadamu harta rampasan perang yang banyak yang dapat kamu ambil, maka Dia segerakan (harta rampasan perang) ini untukmu,807) dan Dia menahan tangan manusia dari (membinasakan)mu (agar kamu mensyukuri-Nya), dan agar menjadi bukti bagi orang-orang mukmin, dan agar Dia menunjukkan kamu ke jalan yang lurus"},{id:21,text:"\u0648\u064e\u0623\u064f\u062e\u06e1\u0631\u064e\u0649\u0670 \u0644\u064e\u0645\u06e1 \u062a\u064e\u0642\u06e1\u062f\u0650\u0631\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627 \u0642\u064e\u062f\u06e1 \u0623\u064e\u062d\u064e\u0627\u0637\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0647\u064e\u0627\u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0642\u064e\u062f\u0650\u064a\u0631\u0657\u0627",translation:"dan (kemenangan-kemenangan) atas negeri-negeri lain yang tidak dapat kamu perkirakan, tetapi sesungguhnya Allah telah menentukannya. Dan Allah Mahakuasa atas segala sesuatu"},{id:22,text:"\u0648\u064e\u0644\u064e\u0648\u06e1 \u0642\u064e\u0670\u062a\u064e\u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0644\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u064f\u0627\u0652 \u0671\u0644\u06e1\u0623\u064e\u062f\u06e1\u0628\u064e\u0670\u0631\u064e \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0627 \u064a\u064e\u062c\u0650\u062f\u064f\u0648\u0646\u064e \u0648\u064e\u0644\u0650\u064a\u0651\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0635\u0650\u064a\u0631\u0657\u0627",translation:"Dan sekiranya orang-orang yang kafir itu memerangi kamu, pastilah mereka akan berbalik melarikan diri (kalah), dan mereka tidak akan mendapatkan pelindung dan penolong"},{id:23,text:"\u0633\u064f\u0646\u0651\u064e\u0629\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u0651\u064e\u062a\u0650\u064a \u0642\u064e\u062f\u06e1 \u062e\u064e\u0644\u064e\u062a\u06e1 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f\u06d6 \u0648\u064e\u0644\u064e\u0646 \u062a\u064e\u062c\u0650\u062f\u064e \u0644\u0650\u0633\u064f\u0646\u0651\u064e\u0629\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064e\u0628\u06e1\u062f\u0650\u064a\u0644\u0657\u0627",translation:"(Demikianlah) hukum Allah yang telah berlaku sejak dahulu, kamu sekali-kali tidak akan menemukan perubahan pada hukum Allah"},{id:24,text:"\u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0643\u064e\u0641\u0651\u064e \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0646\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u064e\u0643\u064f\u0645\u06e1 \u0639\u064e\u0646\u06e1\u0647\u064f\u0645 \u0628\u0650\u0628\u064e\u0637\u06e1\u0646\u0650 \u0645\u064e\u0643\u0651\u064e\u0629\u064e \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0623\u064e\u0646\u06e1 \u0623\u064e\u0638\u06e1\u0641\u064e\u0631\u064e\u0643\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1\u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0628\u064e\u0635\u0650\u064a\u0631\u064b\u0627",translation:"Dan Dialah yang mencegah tangan mereka dari (membinasakan) kamu dan (mencegah) tangan kamu dari (membinasakan) mereka di tengah (kota) Mekkah, setelah Allah memenangkan kamu atas mereka. Dan Allah Maha Melihat apa yang kamu kerjakan"},{id:25,text:"\u0647\u064f\u0645\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u0635\u064e\u062f\u0651\u064f\u0648\u0643\u064f\u0645\u06e1 \u0639\u064e\u0646\u0650 \u0671\u0644\u06e1\u0645\u064e\u0633\u06e1\u062c\u0650\u062f\u0650 \u0671\u0644\u06e1\u062d\u064e\u0631\u064e\u0627\u0645\u0650 \u0648\u064e\u0671\u0644\u06e1\u0647\u064e\u062f\u06e1\u064a\u064e \u0645\u064e\u0639\u06e1\u0643\u064f\u0648\u0641\u064b\u0627 \u0623\u064e\u0646 \u064a\u064e\u0628\u06e1\u0644\u064f\u063a\u064e \u0645\u064e\u062d\u0650\u0644\u0651\u064e\u0647\u064f\u06e5\u06da \u0648\u064e\u0644\u064e\u0648\u06e1\u0644\u064e\u0627 \u0631\u0650\u062c\u064e\u0627\u0644\u065e \u0645\u0651\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0648\u064e\u0646\u0650\u0633\u064e\u0627\u0653\u0621\u065e \u0645\u0651\u064f\u0624\u06e1\u0645\u0650\u0646\u064e\u0670\u062a\u065e \u0644\u0651\u064e\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0647\u064f\u0645\u06e1 \u0623\u064e\u0646 \u062a\u064e\u0637\u064e\u0640\u0654\u064f\u0648\u0647\u064f\u0645\u06e1 \u0641\u064e\u062a\u064f\u0635\u0650\u064a\u0628\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0639\u064e\u0631\u0651\u064e\u0629\u064f\u06e2 \u0628\u0650\u063a\u064e\u064a\u06e1\u0631\u0650 \u0639\u0650\u0644\u06e1\u0645\u0656\u06d6 \u0644\u0651\u0650\u064a\u064f\u062f\u06e1\u062e\u0650\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u0650\u064a \u0631\u064e\u062d\u06e1\u0645\u064e\u062a\u0650\u0647\u0650\u06e6 \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06da \u0644\u064e\u0648\u06e1 \u062a\u064e\u0632\u064e\u064a\u0651\u064e\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0639\u064e\u0630\u0651\u064e\u0628\u06e1\u0646\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0623\u064e\u0644\u0650\u064a\u0645\u064b\u0627",translation:"Merekalah orang-orang kafir yang menghalang-halangi kamu (masuk) Masjidilharam dan menghambat hewan-hewan kurban sampai ke tempat (penyembelihan)nya. Dan kalau bukanlah karena ada beberapa orang beriman laki-laki dan perempuan yang tidak kamu ketahui, tentulah kamu akan membunuh mereka yang menyebabkan kamu ditimpa kesulitan tanpa kamu sadari; karena Allah hendak memasukkan siapa yang Dia kehendaki ke dalam rahmat-Nya. Sekiranya mereka terpisah, tentu Kami akan mengazab orang-orang yang kafir di antara mereka dengan azab yang pedih"},{id:26,text:"\u0625\u0650\u0630\u06e1 \u062c\u064e\u0639\u064e\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u064f \u0671\u0644\u06e1\u062d\u064e\u0645\u0650\u064a\u0651\u064e\u0629\u064e \u062d\u064e\u0645\u0650\u064a\u0651\u064e\u0629\u064e \u0671\u0644\u06e1\u062c\u064e\u0670\u0647\u0650\u0644\u0650\u064a\u0651\u064e\u0629\u0650 \u0641\u064e\u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0633\u064e\u0643\u0650\u064a\u0646\u064e\u062a\u064e\u0647\u064f\u06e5 \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650\u06e6 \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0623\u064e\u0644\u06e1\u0632\u064e\u0645\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0644\u0650\u0645\u064e\u0629\u064e \u0671\u0644\u062a\u0651\u064e\u0642\u06e1\u0648\u064e\u0649\u0670 \u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u062d\u064e\u0642\u0651\u064e \u0628\u0650\u0647\u064e\u0627 \u0648\u064e\u0623\u064e\u0647\u06e1\u0644\u064e\u0647\u064e\u0627\u06da \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u0657\u0627",translation:"Ketika orang-orang yang kafir menanamkan kesombongan dalam hati mereka (yaitu) kesombongan jahiliah, maka Allah menurunkan ketenangan kepada Rasul-Nya, dan kepada orang-orang mukmin dan (Allah) mewajibkan kepada mereka tetap taat menjalankan kalimat takwa,808) dan mereka lebih berhak dengan itu dan patut memilikinya. Dan Allah Maha Mengetahui segala sesuatu"},{id:27,text:"\u0644\u0651\u064e\u0642\u064e\u062f\u06e1 \u0635\u064e\u062f\u064e\u0642\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f \u0671\u0644\u0631\u0651\u064f\u0621\u06e1\u064a\u064e\u0627 \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650\u06d6 \u0644\u064e\u062a\u064e\u062f\u06e1\u062e\u064f\u0644\u064f\u0646\u0651\u064e \u0671\u0644\u06e1\u0645\u064e\u0633\u06e1\u062c\u0650\u062f\u064e \u0671\u0644\u06e1\u062d\u064e\u0631\u064e\u0627\u0645\u064e \u0625\u0650\u0646 \u0634\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0621\u064e\u0627\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0645\u064f\u062d\u064e\u0644\u0651\u0650\u0642\u0650\u064a\u0646\u064e \u0631\u064f\u0621\u064f\u0648\u0633\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0645\u064f\u0642\u064e\u0635\u0651\u0650\u0631\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u062a\u064e\u062e\u064e\u0627\u0641\u064f\u0648\u0646\u064e\u06d6 \u0641\u064e\u0639\u064e\u0644\u0650\u0645\u064e \u0645\u064e\u0627 \u0644\u064e\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0627\u0652 \u0641\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u062a\u06e1\u062d\u0657\u0627 \u0642\u064e\u0631\u0650\u064a\u0628\u064b\u0627",translation:"Sungguh, Allah akan membuktikan kepada Rasul-Nya tentang kebenaran mimpinya bahwa kamu pasti akan memasuki Masjidilharam, jika Allah menghendaki dalam keadaan aman, dengan menggundul rambut kepala dan memendekkannya, sedang kamu tidak merasa takut. Maka Allah mengetahui apa yang tidak kamu ketahui, dan selain itu Dia telah memberikan kemenangan yang dekat"},{id:28,text:"\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f\u06e5 \u0628\u0650\u0671\u0644\u06e1\u0647\u064f\u062f\u064e\u0649\u0670 \u0648\u064e\u062f\u0650\u064a\u0646\u0650 \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0644\u0650\u064a\u064f\u0638\u06e1\u0647\u0650\u0631\u064e\u0647\u064f\u06e5 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u0650 \u0643\u064f\u0644\u0651\u0650\u0647\u0650\u06e6\u06da \u0648\u064e\u0643\u064e\u0641\u064e\u0649\u0670 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0634\u064e\u0647\u0650\u064a\u062f\u0657\u0627",translation:"Dialah yang mengutus Rasul-Nya dengan membawa petunjuk dan agama yang benar, agar dimenangkan-Nya terhadap semua agama. Dan cukuplah Allah sebagai saksi"},{id:29,text:"\u0645\u0651\u064f\u062d\u064e\u0645\u0651\u064e\u062f\u065e \u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u064e\u0639\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u0634\u0650\u062f\u0651\u064e\u0627\u0653\u0621\u064f \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0643\u064f\u0641\u0651\u064e\u0627\u0631\u0650 \u0631\u064f\u062d\u064e\u0645\u064e\u0627\u0653\u0621\u064f \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1\u06d6 \u062a\u064e\u0631\u064e\u0649\u0670\u0647\u064f\u0645\u06e1 \u0631\u064f\u0643\u0651\u064e\u0639\u0657\u0627 \u0633\u064f\u062c\u0651\u064e\u062f\u0657\u0627 \u064a\u064e\u0628\u06e1\u062a\u064e\u063a\u064f\u0648\u0646\u064e \u0641\u064e\u0636\u06e1\u0644\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u0650\u0636\u06e1\u0648\u064e\u0670\u0646\u0657\u0627\u06d6 \u0633\u0650\u064a\u0645\u064e\u0627\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0648\u064f\u062c\u064f\u0648\u0647\u0650\u0647\u0650\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u062b\u064e\u0631\u0650 \u0671\u0644\u0633\u0651\u064f\u062c\u064f\u0648\u062f\u0650\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u064e\u062b\u064e\u0644\u064f\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u062a\u0651\u064e\u0648\u06e1\u0631\u064e\u0649\u0670\u0629\u0650\u06da \u0648\u064e\u0645\u064e\u062b\u064e\u0644\u064f\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0625\u0650\u0646\u062c\u0650\u064a\u0644\u0650 \u0643\u064e\u0632\u064e\u0631\u06e1\u0639\u064d \u0623\u064e\u062e\u06e1\u0631\u064e\u062c\u064e \u0634\u064e\u0637\u06e1\u0640\u0654\u064e\u0647\u064f\u06e5 \u0641\u064e\u0640\u0654\u064e\u0627\u0632\u064e\u0631\u064e\u0647\u064f\u06e5 \u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u063a\u06e1\u0644\u064e\u0638\u064e \u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u0648\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649\u0670 \u0633\u064f\u0648\u0642\u0650\u0647\u0650\u06e6 \u064a\u064f\u0639\u06e1\u062c\u0650\u0628\u064f \u0671\u0644\u0632\u0651\u064f\u0631\u0651\u064e\u0627\u0639\u064e \u0644\u0650\u064a\u064e\u063a\u0650\u064a\u0638\u064e \u0628\u0650\u0647\u0650\u0645\u064f \u0671\u0644\u06e1\u0643\u064f\u0641\u0651\u064e\u0627\u0631\u064e\u06d7 \u0648\u064e\u0639\u064e\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u063a\u06e1\u0641\u0650\u0631\u064e\u0629\u0657 \u0648\u064e\u0623\u064e\u062c\u06e1\u0631\u064b\u0627 \u0639\u064e\u0638\u0650\u064a\u0645\u064e\u06e2\u0627",translation:"Muhammad adalah utusan Allah, dan orang-orang yang bersama dengan dia bersikap keras terhadap orang-orang kafir, tetapi berkasih sayang dengan sesama mereka. Kamu melihat mereka rukuk dan sujud mencari karunia Allah dan keridaan-Nya. Pada wajah mereka tampak tanda-tanda bekas sujud. Demikianlah sifat-sifat mereka (yang diungkapkan) dalam Taurat dan sifat-sifat mereka (yang diungkapkan) dalam Injil, yaitu seperti benih yang mengeluarkan tunasnya, kemudian tunas itu semakin kuat, lalu menjadi besar dan tegak lurus di atas batangnya; tanaman itu menyenangkan hati penanam-penanamnya karena Allah hendak menjengkelkan hati orang-orang kafir (dengan kekuatan orang-orang mukmin). Allah menjanjikan kepada orang-orang yang beriman dan mengerjakan kebajikan di antara mereka, ampunan dan pahala yang besar"}]},{id:49,name:"\u0627\u0644\u062d\u062c\u0631\u0627\u062a",transliteration:"Al-Hujurat",translation:"Kamar-kamar",type:"medinan",total_verses:18,verses:[{id:1,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u062a\u064f\u0642\u064e\u062f\u0651\u0650\u0645\u064f\u0648\u0627\u0652 \u0628\u064e\u064a\u06e1\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0633\u064e\u0645\u0650\u064a\u0639\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u065e",translation:"(Wahai orang-orang yang beriman! Janganlah kamu mendahului Allah dan Rasul-Nya,810) dan bertakwalah kepada Allah. Sungguh, Allah Maha Mendengar, Maha Mengetahui"},{id:2,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u062a\u064e\u0631\u06e1\u0641\u064e\u0639\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0635\u06e1\u0648\u064e\u0670\u062a\u064e\u0643\u064f\u0645\u06e1 \u0641\u064e\u0648\u06e1\u0642\u064e \u0635\u064e\u0648\u06e1\u062a\u0650 \u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062c\u06e1\u0647\u064e\u0631\u064f\u0648\u0627\u0652 \u0644\u064e\u0647\u064f\u06e5 \u0628\u0650\u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0644\u0650 \u0643\u064e\u062c\u064e\u0647\u06e1\u0631\u0650 \u0628\u064e\u0639\u06e1\u0636\u0650\u0643\u064f\u0645\u06e1 \u0644\u0650\u0628\u064e\u0639\u06e1\u0636\u064d \u0623\u064e\u0646 \u062a\u064e\u062d\u06e1\u0628\u064e\u0637\u064e \u0623\u064e\u0639\u06e1\u0645\u064e\u0670\u0644\u064f\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0644\u064e\u0627 \u062a\u064e\u0634\u06e1\u0639\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Wahai orang-orang yang beriman! Janganlah kamu meninggikan suaramu melebihi suara Nabi, dan janganlah kamu berkata kepadanya dengan suara keras sebagaimana kerasnya (suara) sebagian kamu terhadap yang lain, nanti (pahala) segala amalmu bisa terhapus sedangkan kamu tidak menyadari"},{id:3,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u063a\u064f\u0636\u0651\u064f\u0648\u0646\u064e \u0623\u064e\u0635\u06e1\u0648\u064e\u0670\u062a\u064e\u0647\u064f\u0645\u06e1 \u0639\u0650\u0646\u062f\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u0645\u06e1\u062a\u064e\u062d\u064e\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0642\u064f\u0644\u064f\u0648\u0628\u064e\u0647\u064f\u0645\u06e1 \u0644\u0650\u0644\u062a\u0651\u064e\u0642\u06e1\u0648\u064e\u0649\u0670\u06da \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u063a\u06e1\u0641\u0650\u0631\u064e\u0629\u065e \u0648\u064e\u0623\u064e\u062c\u06e1\u0631\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u064c",translation:"Sesungguhnya orang-orang yang merendahkan suaranya di sisi Rasulullah, mereka itulah orang-orang yang telah diuji hatinya oleh Allah untuk bertakwa. Mereka akan memperoleh ampunan dan pahala yang besar"},{id:4,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0646\u064e\u0627\u062f\u064f\u0648\u0646\u064e\u0643\u064e \u0645\u0650\u0646 \u0648\u064e\u0631\u064e\u0627\u0653\u0621\u0650 \u0671\u0644\u06e1\u062d\u064f\u062c\u064f\u0631\u064e\u0670\u062a\u0650 \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064f\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Sesungguhnya orang-orang yang memanggil engkau (Muhammad) dari luar kamar(mu) kebanyakan mereka tidak mengerti"},{id:5,text:"\u0648\u064e\u0644\u064e\u0648\u06e1 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0635\u064e\u0628\u064e\u0631\u064f\u0648\u0627\u0652 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062a\u064e\u062e\u06e1\u0631\u064f\u062c\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0644\u064e\u0643\u064e\u0627\u0646\u064e \u062e\u064e\u064a\u06e1\u0631\u0657\u0627 \u0644\u0651\u064e\u0647\u064f\u0645\u06e1\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u065e",translation:"Dan sekiranya mereka bersabar sampai engkau keluar menemui mereka, tentu akan lebih baik bagi mereka. Dan Allah Maha Pengampun, Maha Penyayang"},{id:6,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646 \u062c\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u06e1 \u0641\u064e\u0627\u0633\u0650\u0642\u064f\u06e2 \u0628\u0650\u0646\u064e\u0628\u064e\u0625\u0656 \u0641\u064e\u062a\u064e\u0628\u064e\u064a\u0651\u064e\u0646\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646 \u062a\u064f\u0635\u0650\u064a\u0628\u064f\u0648\u0627\u0652 \u0642\u064e\u0648\u06e1\u0645\u064e\u06e2\u0627 \u0628\u0650\u062c\u064e\u0647\u064e\u0670\u0644\u064e\u0629\u0656 \u0641\u064e\u062a\u064f\u0635\u06e1\u0628\u0650\u062d\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0641\u064e\u0639\u064e\u0644\u06e1\u062a\u064f\u0645\u06e1 \u0646\u064e\u0670\u062f\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Wahai orang-orang yang beriman! Jika seorang yang fasik datang kepadamu membawa suatu berita, maka telitilah kebenarannya, agar kamu tidak mencelakakan suatu kaum karena kebodohan (kecerobohan), yang akhirnya kamu menyesali perbuatanmu itu"},{id:7,text:"\u0648\u064e\u0671\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e \u0641\u0650\u064a\u0643\u064f\u0645\u06e1 \u0631\u064e\u0633\u064f\u0648\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0644\u064e\u0648\u06e1 \u064a\u064f\u0637\u0650\u064a\u0639\u064f\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u0643\u064e\u062b\u0650\u064a\u0631\u0656 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0631\u0650 \u0644\u064e\u0639\u064e\u0646\u0650\u062a\u0651\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u062d\u064e\u0628\u0651\u064e\u0628\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0625\u0650\u064a\u0645\u064e\u0670\u0646\u064e \u0648\u064e\u0632\u064e\u064a\u0651\u064e\u0646\u064e\u0647\u064f\u06e5 \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0643\u064e\u0631\u0651\u064e\u0647\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0643\u064f\u0641\u06e1\u0631\u064e \u0648\u064e\u0671\u0644\u06e1\u0641\u064f\u0633\u064f\u0648\u0642\u064e \u0648\u064e\u0671\u0644\u06e1\u0639\u0650\u0635\u06e1\u064a\u064e\u0627\u0646\u064e\u06da \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u0631\u0651\u064e\u0640\u0670\u0634\u0650\u062f\u064f\u0648\u0646\u064e",translation:"Dan ketahuilah bahwa di tengah-tengah kamu ada Rasulullah. Kalau dia menuruti (kemauan) kamu dalam banyak hal, pasti kamu akan mendapatkan kesusahan. Tetapi Allah menjadikan kamu cinta kepada keimanan, dan menjadikan (iman) itu indah dalam hatimu, serta menjadikan kamu benci kepada kekafiran, kefasikan dan kedurhakaan. Mereka itulah orang-orang yang mengikuti jalan yang lurus"},{id:8,text:"\u0641\u064e\u0636\u06e1\u0644\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0646\u0650\u0639\u06e1\u0645\u064e\u0629\u0657\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u065e",translation:"sebagai karunia dan nikmat dari Allah. Dan Allah Maha Mengetahui, Mahabijaksana"},{id:9,text:"\u0648\u064e\u0625\u0650\u0646 \u0637\u064e\u0627\u0653\u0626\u0650\u0641\u064e\u062a\u064e\u0627\u0646\u0650 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0671\u0642\u06e1\u062a\u064e\u062a\u064e\u0644\u064f\u0648\u0627\u0652 \u0641\u064e\u0623\u064e\u0635\u06e1\u0644\u0650\u062d\u064f\u0648\u0627\u0652 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u064e\u0627\u06d6 \u0641\u064e\u0625\u0650\u0646\u06e2 \u0628\u064e\u063a\u064e\u062a\u06e1 \u0625\u0650\u062d\u06e1\u062f\u064e\u0649\u0670\u0647\u064f\u0645\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0623\u064f\u062e\u06e1\u0631\u064e\u0649\u0670 \u0641\u064e\u0642\u064e\u0670\u062a\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0651\u064e\u062a\u0650\u064a \u062a\u064e\u0628\u06e1\u063a\u0650\u064a \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062a\u064e\u0641\u0650\u064a\u0653\u0621\u064e \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0645\u06e1\u0631\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0641\u064e\u0625\u0650\u0646 \u0641\u064e\u0627\u0653\u0621\u064e\u062a\u06e1 \u0641\u064e\u0623\u064e\u0635\u06e1\u0644\u0650\u062d\u064f\u0648\u0627\u0652 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0628\u0650\u0671\u0644\u06e1\u0639\u064e\u062f\u06e1\u0644\u0650 \u0648\u064e\u0623\u064e\u0642\u06e1\u0633\u0650\u0637\u064f\u0648\u0653\u0627\u0652\u06d6 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0671\u0644\u06e1\u0645\u064f\u0642\u06e1\u0633\u0650\u0637\u0650\u064a\u0646\u064e",translation:"Dan apabila ada dua golongan orang mukmin berperang, maka damaikanlah antara keduanya. Jika salah satu dari keduanya berbuat zalim terhadap (golongan) yang lain, maka perangilah (golongan) yang berbuat zalim itu, sehingga golongan itu kembali kepada perintah Allah. Jika golongan itu telah kembali (kepada perintah Allah), maka damaikanlah antara keduanya dengan adil, dan berlakulah adil. Sungguh, Allah mencintai orang-orang yang berlaku adil"},{id:10,text:"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0625\u0650\u062e\u06e1\u0648\u064e\u0629\u065e \u0641\u064e\u0623\u064e\u0635\u06e1\u0644\u0650\u062d\u064f\u0648\u0627\u0652 \u0628\u064e\u064a\u06e1\u0646\u064e \u0623\u064e\u062e\u064e\u0648\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064f\u0631\u06e1\u062d\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Sesungguhnya orang-orang mukmin itu bersaudara, karena itu damaikanlah antara kedua saudaramu (yang berselisih) dan bertakwalah kepada Allah agar kamu mendapat rahmat"},{id:11,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u062e\u064e\u0631\u06e1 \u0642\u064e\u0648\u06e1\u0645\u065e \u0645\u0651\u0650\u0646 \u0642\u064e\u0648\u06e1\u0645\u064d \u0639\u064e\u0633\u064e\u0649\u0670\u0653 \u0623\u064e\u0646 \u064a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u062e\u064e\u064a\u06e1\u0631\u0657\u0627 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u0646\u0650\u0633\u064e\u0627\u0653\u0621\u065e \u0645\u0651\u0650\u0646 \u0646\u0651\u0650\u0633\u064e\u0627\u0653\u0621\u064d \u0639\u064e\u0633\u064e\u0649\u0670\u0653 \u0623\u064e\u0646 \u064a\u064e\u0643\u064f\u0646\u0651\u064e \u062e\u064e\u064a\u06e1\u0631\u0657\u0627 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0646\u0651\u064e\u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0644\u06e1\u0645\u0650\u0632\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0646\u064e\u0627\u0628\u064e\u0632\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u06e1\u0623\u064e\u0644\u06e1\u0642\u064e\u0670\u0628\u0650\u06d6 \u0628\u0650\u0626\u06e1\u0633\u064e \u0671\u0644\u0650\u0671\u0633\u06e1\u0645\u064f \u0671\u0644\u06e1\u0641\u064f\u0633\u064f\u0648\u0642\u064f \u0628\u064e\u0639\u06e1\u062f\u064e \u0671\u0644\u06e1\u0625\u0650\u064a\u0645\u064e\u0670\u0646\u0650\u06da \u0648\u064e\u0645\u064e\u0646 \u0644\u0651\u064e\u0645\u06e1 \u064a\u064e\u062a\u064f\u0628\u06e1 \u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Wahai orang-orang yang beriman! Janganlah suatu kaum mengolok-olok kaum yang lain, (karena) boleh jadi mereka (yang diperolok-olokkan) lebih baik dari mereka (yang mengolok-olok), dan jangan pula perempuan-perempuan (mengolok-olokkan) perempuan lain, (karena) boleh jadi perempuan (yang diperolok-olokkan) lebih baik dari perempuan (yang mengolok-olok). Janganlah kamu saling mencela satu sama lain, dan janganlah saling memanggil dengan gelar-gelar yang buruk. Seburuk-buruk panggilan adalah (panggilan) yang buruk (fasik) setelah beriman. Dan barangsiapa tidak bertobat, maka mereka itulah orang-orang yang zalim"},{id:12,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0671\u062c\u06e1\u062a\u064e\u0646\u0650\u0628\u064f\u0648\u0627\u0652 \u0643\u064e\u062b\u0650\u064a\u0631\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0638\u0651\u064e\u0646\u0651\u0650 \u0625\u0650\u0646\u0651\u064e \u0628\u064e\u0639\u06e1\u0636\u064e \u0671\u0644\u0638\u0651\u064e\u0646\u0651\u0650 \u0625\u0650\u062b\u06e1\u0645\u065e\u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062c\u064e\u0633\u0651\u064e\u0633\u064f\u0648\u0627\u0652 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u063a\u06e1\u062a\u064e\u0628 \u0628\u0651\u064e\u0639\u06e1\u0636\u064f\u0643\u064f\u0645 \u0628\u064e\u0639\u06e1\u0636\u064b\u0627\u06da \u0623\u064e\u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0623\u064e\u062d\u064e\u062f\u064f\u0643\u064f\u0645\u06e1 \u0623\u064e\u0646 \u064a\u064e\u0623\u06e1\u0643\u064f\u0644\u064e \u0644\u064e\u062d\u06e1\u0645\u064e \u0623\u064e\u062e\u0650\u064a\u0647\u0650 \u0645\u064e\u064a\u06e1\u062a\u0657\u0627 \u0641\u064e\u0643\u064e\u0631\u0650\u0647\u06e1\u062a\u064f\u0645\u064f\u0648\u0647\u064f\u06da \u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u062a\u064e\u0648\u0651\u064e\u0627\u0628\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u065e",translation:"Wahai orang-orang yang beriman! Jauhilah banyak dari prasangka, sesungguhnya sebagian prasangka itu dosa, dan janganlah kamu mencari-cari kesalahan orang lain, dan janganlah ada di antara kamu yang menggunjing sebagian yang lain. Apakah ada di antara kamu yang suka memakan daging saudaranya yang sudah mati? Tentu kamu merasa jijik. Dan bertakwalah kepada Allah, sungguh Allah Maha Penerima tobat, Maha Penyayang"},{id:13,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0625\u0650\u0646\u0651\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u06e1\u0646\u064e\u0670\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0630\u064e\u0643\u064e\u0631\u0656 \u0648\u064e\u0623\u064f\u0646\u062b\u064e\u0649\u0670 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0670\u0643\u064f\u0645\u06e1 \u0634\u064f\u0639\u064f\u0648\u0628\u0657\u0627 \u0648\u064e\u0642\u064e\u0628\u064e\u0627\u0653\u0626\u0650\u0644\u064e \u0644\u0650\u062a\u064e\u0639\u064e\u0627\u0631\u064e\u0641\u064f\u0648\u0653\u0627\u0652\u06da \u0625\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u06e1\u0631\u064e\u0645\u064e\u0643\u064f\u0645\u06e1 \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u062a\u06e1\u0642\u064e\u0649\u0670\u0643\u064f\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u062e\u064e\u0628\u0650\u064a\u0631\u065e",translation:"Wahai manusia! Sungguh, Kami telah menciptakan kamu dari seorang laki-laki dan seorang perempuan, kemudian Kami jadikan kamu berbangsa-bangsa dan bersuku-suku agar kamu saling mengenal. Sungguh, yang paling mulia di antara kamu di sisi Allah ialah orang yang paling bertakwa. Sungguh, Allah Maha Mengetahui, Mahateliti"},{id:14,text:"\u06de\u0642\u064e\u0627\u0644\u064e\u062a\u0650 \u0671\u0644\u06e1\u0623\u064e\u0639\u06e1\u0631\u064e\u0627\u0628\u064f \u0621\u064e\u0627\u0645\u064e\u0646\u0651\u064e\u0627\u06d6 \u0642\u064f\u0644 \u0644\u0651\u064e\u0645\u06e1 \u062a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u0642\u064f\u0648\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0633\u06e1\u0644\u064e\u0645\u06e1\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u064a\u064e\u062f\u06e1\u062e\u064f\u0644\u0650 \u0671\u0644\u06e1\u0625\u0650\u064a\u0645\u064e\u0670\u0646\u064f \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0643\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0625\u0650\u0646 \u062a\u064f\u0637\u0650\u064a\u0639\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f\u06e5 \u0644\u064e\u0627 \u064a\u064e\u0644\u0650\u062a\u06e1\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u0639\u06e1\u0645\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u06e1 \u0634\u064e\u064a\u06e1\u0640\u0654\u064b\u0627\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064c",translation:"Orang-orang Arab Badui berkata, \"Kami telah beriman.\" Katakanlah (kepada mereka), \"Kamu belum beriman, tetapi katakanlah 'Kami telah tunduk (Islam)', karena iman belum masuk ke dalam hatimu. Dan jika kamu taat kepada Allah dan Rasul-Nya, Dia tidak akan mengurangi sedikit pun (pahala) amalmu. Sungguh, Allah Maha Pengampun, Maha Penyayang"},{id:15,text:"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650\u06e6 \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0645\u06e1 \u064a\u064e\u0631\u06e1\u062a\u064e\u0627\u0628\u064f\u0648\u0627\u0652 \u0648\u064e\u062c\u064e\u0670\u0647\u064e\u062f\u064f\u0648\u0627\u0652 \u0628\u0650\u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u06e1 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u062f\u0650\u0642\u064f\u0648\u0646\u064e",translation:"Sesungguhnya orang-orang mukmin yang sebenarnya adalah mereka yang beriman kepada Allah dan Rasul-Nya, kemudian mereka tidak ragu-ragu, dan mereka berjihad dengan harta dan jiwanya di jalan Allah. Mereka itulah orang-orang yang benar"},{id:16,text:"\u0642\u064f\u0644\u06e1 \u0623\u064e\u062a\u064f\u0639\u064e\u0644\u0651\u0650\u0645\u064f\u0648\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u062f\u0650\u064a\u0646\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Katakanlah (kepada mereka), \"Apakah kamu akan memberitahukan kepada Allah tentang agamamu (keyakinanmu), padahal Allah mengetahui apa yang ada di langit dan apa yang ada di bumi; dan Allah Maha Mengetahui segala sesuatu"},{id:17,text:"\u064a\u064e\u0645\u064f\u0646\u0651\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0623\u064e\u0646\u06e1 \u0623\u064e\u0633\u06e1\u0644\u064e\u0645\u064f\u0648\u0627\u0652\u06d6 \u0642\u064f\u0644 \u0644\u0651\u064e\u0627 \u062a\u064e\u0645\u064f\u0646\u0651\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u064a\u0651\u064e \u0625\u0650\u0633\u06e1\u0644\u064e\u0670\u0645\u064e\u0643\u064f\u0645\u06d6 \u0628\u064e\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0645\u064f\u0646\u0651\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0623\u064e\u0646\u06e1 \u0647\u064e\u062f\u064e\u0649\u0670\u0643\u064f\u0645\u06e1 \u0644\u0650\u0644\u06e1\u0625\u0650\u064a\u0645\u064e\u0670\u0646\u0650 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0635\u064e\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Mereka merasa berjasa kepadamu dengan keislaman mereka. Katakanlah, \"Janganlah kamu merasa berjasa kepadaku dengan keislamanmu, sebenarnya Allah yang melimpahkan nikmat kepadamu dengan menunjukkan kamu kepada keimanan, jika kamu orang yang benar"},{id:18,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u063a\u064e\u064a\u06e1\u0628\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u064e\u0635\u0650\u064a\u0631\u064f\u06e2 \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Sungguh, Allah mengetahui apa yang gaib di langit dan di bumi. Dan Allah Maha Melihat apa yang kamu kerjakan"}]},{id:50,name:"\u0642",transliteration:"Qaf",translation:"Qaf",type:"meccan",total_verses:45,verses:[{id:1,text:"\u0642\u0653\u06da \u0648\u064e\u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u0650 \u0671\u0644\u06e1\u0645\u064e\u062c\u0650\u064a\u062f\u0650",translation:"Q\u0101f. Demi Alquran yang mulia"},{id:2,text:"\u0628\u064e\u0644\u06e1 \u0639\u064e\u062c\u0650\u0628\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645 \u0645\u0651\u064f\u0646\u0630\u0650\u0631\u065e \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u064f\u0648\u0646\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0634\u064e\u064a\u06e1\u0621\u064c \u0639\u064e\u062c\u0650\u064a\u0628\u064c",translation:"(Mereka tidak menerimanya) bahkan mereka tercengang karena telah datang kepada mereka seorang pemberi peringatan dari (kalangan) mereka sendiri, maka berkatalah orang-orang kafir, \"Ini adalah sesuatu yang sangat ajaib"},{id:3,text:"\u0623\u064e\u0621\u0650\u0630\u064e\u0627 \u0645\u0650\u062a\u06e1\u0646\u064e\u0627 \u0648\u064e\u0643\u064f\u0646\u0651\u064e\u0627 \u062a\u064f\u0631\u064e\u0627\u0628\u0657\u0627\u06d6 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0631\u064e\u062c\u06e1\u0639\u064f\u06e2 \u0628\u064e\u0639\u0650\u064a\u062f\u065e",translation:"Apakah apabila kami telah mati dan sudah menjadi tanah (akan kembali lagi)? Itu adalah suatu pengembalian yang tidak mungkin"},{id:4,text:"\u0642\u064e\u062f\u06e1 \u0639\u064e\u0644\u0650\u0645\u06e1\u0646\u064e\u0627 \u0645\u064e\u0627 \u062a\u064e\u0646\u0642\u064f\u0635\u064f \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064f \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0639\u0650\u0646\u062f\u064e\u0646\u064e\u0627 \u0643\u0650\u062a\u064e\u0670\u0628\u064c \u062d\u064e\u0641\u0650\u064a\u0638\u064f\u06e2",translation:"Sungguh, Kami telah mengetahui apa yang ditelan bumi dari (tubuh) mereka, sebab pada Kami ada kitab (catatan) yang terpelihara baik"},{id:5,text:"\u0628\u064e\u0644\u06e1 \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u06e1 \u0641\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0653 \u0623\u064e\u0645\u06e1\u0631\u0656 \u0645\u0651\u064e\u0631\u0650\u064a\u062c\u064d",translation:"Bahkan mereka telah mendustakan kebenaran ketika (kebenaran itu) datang kepada mereka, maka mereka berada dalam keadaan kacau balau"},{id:6,text:"\u0623\u064e\u0641\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0646\u0638\u064f\u0631\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0641\u064e\u0648\u06e1\u0642\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u064a\u06e1\u0641\u064e \u0628\u064e\u0646\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064e\u0627 \u0648\u064e\u0632\u064e\u064a\u0651\u064e\u0646\u0651\u064e\u0640\u0670\u0647\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064e\u0627 \u0645\u0650\u0646 \u0641\u064f\u0631\u064f\u0648\u062c\u0656",translation:"Maka tidakkah mereka memperhatikan langit yang ada di atas mereka, bagaimana cara Kami membangunnya dan menghiasinya, dan tidak terdapat retak-retak sedikit pun"},{id:7,text:"\u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0645\u064e\u062f\u064e\u062f\u06e1\u0646\u064e\u0670\u0647\u064e\u0627 \u0648\u064e\u0623\u064e\u0644\u06e1\u0642\u064e\u064a\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0631\u064e\u0648\u064e\u0670\u0633\u0650\u064a\u064e \u0648\u064e\u0623\u064e\u0646\u06e2\u0628\u064e\u062a\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u0632\u064e\u0648\u06e1\u062c\u0650\u06ed \u0628\u064e\u0647\u0650\u064a\u062c\u0656",translation:"Dan bumi yang Kami hamparkan dan Kami pancangkan di atasnya gunung-gunung yang kokoh, dan Kami tumbuhkan di atasnya tanam-tanaman yang indah"},{id:8,text:"\u062a\u064e\u0628\u06e1\u0635\u0650\u0631\u064e\u0629\u0657 \u0648\u064e\u0630\u0650\u0643\u06e1\u0631\u064e\u0649\u0670 \u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0639\u064e\u0628\u06e1\u062f\u0656 \u0645\u0651\u064f\u0646\u0650\u064a\u0628\u0656",translation:"untuk menjadi pelajaran dan peringatan bagi setiap hamba yang kembali (tunduk kepada Allah)"},{id:9,text:"\u0648\u064e\u0646\u064e\u0632\u0651\u064e\u0644\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0645\u064e\u0627\u0653\u0621\u0657 \u0645\u0651\u064f\u0628\u064e\u0670\u0631\u064e\u0643\u0657\u0627 \u0641\u064e\u0623\u064e\u0646\u06e2\u0628\u064e\u062a\u06e1\u0646\u064e\u0627 \u0628\u0650\u0647\u0650\u06e6 \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0656 \u0648\u064e\u062d\u064e\u0628\u0651\u064e \u0671\u0644\u06e1\u062d\u064e\u0635\u0650\u064a\u062f\u0650",translation:"Dan dari langit Kami turunkan air yang memberi berkah, lalu Kami tumbuhkan dengan (air) itu pepohonan yang rindang dan biji-bijian yang dapat dipanen"},{id:10,text:"\u0648\u064e\u0671\u0644\u0646\u0651\u064e\u062e\u06e1\u0644\u064e \u0628\u064e\u0627\u0633\u0650\u0642\u064e\u0670\u062a\u0656 \u0644\u0651\u064e\u0647\u064e\u0627 \u0637\u064e\u0644\u06e1\u0639\u065e \u0646\u0651\u064e\u0636\u0650\u064a\u062f\u065e",translation:"dan pohon kurma yang tinggi-tinggi yang mempunyai mayang yang bersusun-susun"},{id:11,text:"\u0631\u0651\u0650\u0632\u06e1\u0642\u0657\u0627 \u0644\u0651\u0650\u0644\u06e1\u0639\u0650\u0628\u064e\u0627\u062f\u0650\u06d6 \u0648\u064e\u0623\u064e\u062d\u06e1\u064a\u064e\u064a\u06e1\u0646\u064e\u0627 \u0628\u0650\u0647\u0650\u06e6 \u0628\u064e\u0644\u06e1\u062f\u064e\u0629\u0657 \u0645\u0651\u064e\u064a\u06e1\u062a\u0657\u0627\u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0671\u0644\u06e1\u062e\u064f\u0631\u064f\u0648\u062c\u064f",translation:"(sebagai) rezeki bagi hamba-hamba (Kami), dan Kami hidupkan dengan (air) itu negeri yang mati (tandus). Seperti itulah terjadinya kebangkitan (dari kubur)"},{id:12,text:"\u0643\u064e\u0630\u0651\u064e\u0628\u064e\u062a\u06e1 \u0642\u064e\u0628\u06e1\u0644\u064e\u0647\u064f\u0645\u06e1 \u0642\u064e\u0648\u06e1\u0645\u064f \u0646\u064f\u0648\u062d\u0656 \u0648\u064e\u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u0631\u0651\u064e\u0633\u0651\u0650 \u0648\u064e\u062b\u064e\u0645\u064f\u0648\u062f\u064f",translation:"Sebelum mereka, kaum Nuh, penduduk Rass dan Samud telah mendustakan (rasul-rasul)"},{id:13,text:"\u0648\u064e\u0639\u064e\u0627\u062f\u065e \u0648\u064e\u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064f \u0648\u064e\u0625\u0650\u062e\u06e1\u0648\u064e\u0670\u0646\u064f \u0644\u064f\u0648\u0637\u0656",translation:"dan (demikian juga) kaum '\u0100d, kaum Fir'aun dan kaum Lu\u1e6d"},{id:14,text:"\u0648\u064e\u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u06e1\u0623\u064e\u064a\u06e1\u0643\u064e\u0629\u0650 \u0648\u064e\u0642\u064e\u0648\u06e1\u0645\u064f \u062a\u064f\u0628\u0651\u064e\u0639\u0656\u06da \u0643\u064f\u0644\u0651\u065e \u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0671\u0644\u0631\u0651\u064f\u0633\u064f\u0644\u064e \u0641\u064e\u062d\u064e\u0642\u0651\u064e \u0648\u064e\u0639\u0650\u064a\u062f\u0650",translation:"dan (juga) penduduk Aikah serta kaum Tubba'. Semuanya telah mendustakan rasul-rasul, maka berlakulah ancaman-Ku (atas mereka)"},{id:15,text:"\u0623\u064e\u0641\u064e\u0639\u064e\u064a\u0650\u064a\u0646\u064e\u0627 \u0628\u0650\u0671\u0644\u06e1\u062e\u064e\u0644\u06e1\u0642\u0650 \u0671\u0644\u06e1\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u06da \u0628\u064e\u0644\u06e1 \u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0644\u064e\u0628\u06e1\u0633\u0656 \u0645\u0651\u0650\u0646\u06e1 \u062e\u064e\u0644\u06e1\u0642\u0656 \u062c\u064e\u062f\u0650\u064a\u062f\u0656",translation:"Maka apakah Kami letih dengan penciptaan yang pertama? (Sama sekali tidak), bahkan mereka dalam keadaan ragu-ragu tentang penciptaan yang baru"},{id:16,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u062e\u064e\u0644\u064e\u0642\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064e \u0648\u064e\u0646\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u062a\u064f\u0648\u064e\u0633\u06e1\u0648\u0650\u0633\u064f \u0628\u0650\u0647\u0650\u06e6 \u0646\u064e\u0641\u06e1\u0633\u064f\u0647\u064f\u06e5\u06d6 \u0648\u064e\u0646\u064e\u062d\u06e1\u0646\u064f \u0623\u064e\u0642\u06e1\u0631\u064e\u0628\u064f \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0645\u0650\u0646\u06e1 \u062d\u064e\u0628\u06e1\u0644\u0650 \u0671\u0644\u06e1\u0648\u064e\u0631\u0650\u064a\u062f\u0650",translation:"Dan sungguh, Kami telah menciptakan manusia dan mengetahui apa yang dibisikkan oleh hatinya, dan Kami lebih dekat kepadanya daripada urat lehernya"},{id:17,text:"\u0625\u0650\u0630\u06e1 \u064a\u064e\u062a\u064e\u0644\u064e\u0642\u0651\u064e\u0649 \u0671\u0644\u06e1\u0645\u064f\u062a\u064e\u0644\u064e\u0642\u0651\u0650\u064a\u064e\u0627\u0646\u0650 \u0639\u064e\u0646\u0650 \u0671\u0644\u06e1\u064a\u064e\u0645\u0650\u064a\u0646\u0650 \u0648\u064e\u0639\u064e\u0646\u0650 \u0671\u0644\u0634\u0651\u0650\u0645\u064e\u0627\u0644\u0650 \u0642\u064e\u0639\u0650\u064a\u062f\u065e",translation:"(Ingatlah) ketika dua malaikat mencatat (perbuatannya), yang satu duduk di sebelah kanan dan yang lain di sebelah kiri"},{id:18,text:"\u0645\u0651\u064e\u0627 \u064a\u064e\u0644\u06e1\u0641\u0650\u0638\u064f \u0645\u0650\u0646 \u0642\u064e\u0648\u06e1\u0644\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0644\u064e\u062f\u064e\u064a\u06e1\u0647\u0650 \u0631\u064e\u0642\u0650\u064a\u0628\u064c \u0639\u064e\u062a\u0650\u064a\u062f\u065e",translation:"Tidak ada suatu kata yang diucapkannya melainkan ada di sisinya malaikat pengawas yang selalu siap (mencatat)"},{id:19,text:"\u0648\u064e\u062c\u064e\u0627\u0653\u0621\u064e\u062a\u06e1 \u0633\u064e\u0643\u06e1\u0631\u064e\u0629\u064f \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u0650 \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650\u06d6 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064e \u0645\u0650\u0646\u06e1\u0647\u064f \u062a\u064e\u062d\u0650\u064a\u062f\u064f",translation:"Dan datanglah sakaratulmaut dengan sebenar-benarnya. Itulah yang dahulu hendak kamu hindari"},{id:20,text:"\u0648\u064e\u0646\u064f\u0641\u0650\u062e\u064e \u0641\u0650\u064a \u0671\u0644\u0635\u0651\u064f\u0648\u0631\u0650\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064e\u0648\u06e1\u0645\u064f \u0671\u0644\u06e1\u0648\u064e\u0639\u0650\u064a\u062f\u0650",translation:"Dan ditiuplah sangkakala. Itulah hari yang diancamkan"},{id:21,text:"\u0648\u064e\u062c\u064e\u0627\u0653\u0621\u064e\u062a\u06e1 \u0643\u064f\u0644\u0651\u064f \u0646\u064e\u0641\u06e1\u0633\u0656 \u0645\u0651\u064e\u0639\u064e\u0647\u064e\u0627 \u0633\u064e\u0627\u0653\u0626\u0650\u0642\u065e \u0648\u064e\u0634\u064e\u0647\u0650\u064a\u062f\u065e",translation:"Setiap orang akan datang bersama (malaikat) penggiring dan (malaikat) saksi"},{id:22,text:"\u0644\u0651\u064e\u0642\u064e\u062f\u06e1 \u0643\u064f\u0646\u062a\u064e \u0641\u0650\u064a \u063a\u064e\u0641\u06e1\u0644\u064e\u0629\u0656 \u0645\u0651\u0650\u0646\u06e1 \u0647\u064e\u0670\u0630\u064e\u0627 \u0641\u064e\u0643\u064e\u0634\u064e\u0641\u06e1\u0646\u064e\u0627 \u0639\u064e\u0646\u0643\u064e \u063a\u0650\u0637\u064e\u0627\u0653\u0621\u064e\u0643\u064e \u0641\u064e\u0628\u064e\u0635\u064e\u0631\u064f\u0643\u064e \u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e \u062d\u064e\u062f\u0650\u064a\u062f\u065e",translation:"Sungguh, kamu dahulu lalai tentang (peristiwa) ini, maka Kami singkapkan tutup (yang menutupi) matamu, sehingga penglihatanmu pada hari ini sangat tajam"},{id:23,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0642\u064e\u0631\u0650\u064a\u0646\u064f\u0647\u064f\u06e5 \u0647\u064e\u0670\u0630\u064e\u0627 \u0645\u064e\u0627 \u0644\u064e\u062f\u064e\u064a\u0651\u064e \u0639\u064e\u062a\u0650\u064a\u062f\u064c",translation:"Dan (malaikat) yang menyertainya berkata, \"Inilah (catatan perbuatan) yang ada padaku"},{id:24,text:"\u0623\u064e\u0644\u06e1\u0642\u0650\u064a\u064e\u0627 \u0641\u0650\u064a \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0643\u064f\u0644\u0651\u064e \u0643\u064e\u0641\u0651\u064e\u0627\u0631\u064d \u0639\u064e\u0646\u0650\u064a\u062f\u0656",translation:"(Allah berfirman), \"Lemparkanlah olehmu berdua ke dalam neraka Jahanam, semua orang yang sangat ingkar dan keras kepala"},{id:25,text:"\u0645\u0651\u064e\u0646\u0651\u064e\u0627\u0639\u0656 \u0644\u0651\u0650\u0644\u06e1\u062e\u064e\u064a\u06e1\u0631\u0650 \u0645\u064f\u0639\u06e1\u062a\u064e\u062f\u0656 \u0645\u0651\u064f\u0631\u0650\u064a\u0628\u064d",translation:"yang sangat enggan melakukan kebajikan, melampaui batas, dan bersikap ragu-ragu"},{id:26,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0639\u064e\u0644\u064e \u0645\u064e\u0639\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u064e\u0670\u0647\u064b\u0627 \u0621\u064e\u0627\u062e\u064e\u0631\u064e \u0641\u064e\u0623\u064e\u0644\u06e1\u0642\u0650\u064a\u064e\u0627\u0647\u064f \u0641\u0650\u064a \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0671\u0644\u0634\u0651\u064e\u062f\u0650\u064a\u062f\u0650",translation:"yang mempersekutukan Allah dengan tuhan lain, maka lemparkanlah dia ke dalam azab yang keras"},{id:27,text:"\u06de\u0642\u064e\u0627\u0644\u064e \u0642\u064e\u0631\u0650\u064a\u0646\u064f\u0647\u064f\u06e5 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0645\u064e\u0627\u0653 \u0623\u064e\u0637\u06e1\u063a\u064e\u064a\u06e1\u062a\u064f\u0647\u064f\u06e5 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u0643\u064e\u0627\u0646\u064e \u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0670\u0644\u0650\u06ed \u0628\u064e\u0639\u0650\u064a\u062f\u0656",translation:"(Setan) yang menyertainya berkata (pula), \"Ya Tuhan kami, aku tidak menyesatkannya, tetapi dia sendiri yang berada dalam kesesatan yang jauh"},{id:28,text:"\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0627 \u062a\u064e\u062e\u06e1\u062a\u064e\u0635\u0650\u0645\u064f\u0648\u0627\u0652 \u0644\u064e\u062f\u064e\u064a\u0651\u064e \u0648\u064e\u0642\u064e\u062f\u06e1 \u0642\u064e\u062f\u0651\u064e\u0645\u06e1\u062a\u064f \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0648\u064e\u0639\u0650\u064a\u062f\u0650",translation:"(Allah) berfirman, \"Janganlah kamu bertengkar di hadapan-Ku, dan sungguh, dahulu Aku telah memberikan ancaman kepadamu"},{id:29,text:"\u0645\u064e\u0627 \u064a\u064f\u0628\u064e\u062f\u0651\u064e\u0644\u064f \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0644\u064f \u0644\u064e\u062f\u064e\u064a\u0651\u064e \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u064e\u0627\u06e0 \u0628\u0650\u0638\u064e\u0644\u0651\u064e\u0640\u0670\u0645\u0656 \u0644\u0651\u0650\u0644\u06e1\u0639\u064e\u0628\u0650\u064a\u062f\u0650",translation:"Keputusan-Ku tidak dapat diubah, dan Aku tidak menzalimi hamba-hamba-Ku"},{id:30,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u0646\u064e\u0642\u064f\u0648\u0644\u064f \u0644\u0650\u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0647\u064e\u0644\u0650 \u0671\u0645\u06e1\u062a\u064e\u0644\u064e\u0623\u06e1\u062a\u0650 \u0648\u064e\u062a\u064e\u0642\u064f\u0648\u0644\u064f \u0647\u064e\u0644\u06e1 \u0645\u0650\u0646 \u0645\u0651\u064e\u0632\u0650\u064a\u062f\u0656",translation:"(Ingatlah) pada hari (ketika) Kami bertanya kepada Jahanam, \"Apakah kamu sudah penuh?\" Ia menjawab, \"Masih adakah tambahan"},{id:31,text:"\u0648\u064e\u0623\u064f\u0632\u06e1\u0644\u0650\u0641\u064e\u062a\u0650 \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u064f \u0644\u0650\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e \u063a\u064e\u064a\u06e1\u0631\u064e \u0628\u064e\u0639\u0650\u064a\u062f\u064d",translation:"Sedangkan surga didekatkan kepada orang-orang yang bertakwa pada tempat yang tidak jauh (dari mereka)"},{id:32,text:"\u0647\u064e\u0670\u0630\u064e\u0627 \u0645\u064e\u0627 \u062a\u064f\u0648\u0639\u064e\u062f\u064f\u0648\u0646\u064e \u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0623\u064e\u0648\u0651\u064e\u0627\u0628\u064d \u062d\u064e\u0641\u0650\u064a\u0638\u0656",translation:"(Kepada mereka dikatakan), \"Inilah nikmat yang dijanjikan kepadamu, (yaitu) kepada setiap hamba yang senantiasa bertobat (kepada Allah) dan memelihara (semua peraturan-peraturan-Nya)"},{id:33,text:"\u0645\u0651\u064e\u0646\u06e1 \u062e\u064e\u0634\u0650\u064a\u064e \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u064e \u0628\u0650\u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u0628\u0650 \u0648\u064e\u062c\u064e\u0627\u0653\u0621\u064e \u0628\u0650\u0642\u064e\u0644\u06e1\u0628\u0656 \u0645\u0651\u064f\u0646\u0650\u064a\u0628\u064d",translation:"(Yaitu) orang yang takut kepada Allah Yang Maha Pengasih, sekalipun tidak kelihatan (olehnya) dan dia datang dengan hati yang bertobat"},{id:34,text:"\u0671\u062f\u06e1\u062e\u064f\u0644\u064f\u0648\u0647\u064e\u0627 \u0628\u0650\u0633\u064e\u0644\u064e\u0670\u0645\u0656\u06d6 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064e\u0648\u06e1\u0645\u064f \u0671\u0644\u06e1\u062e\u064f\u0644\u064f\u0648\u062f\u0650",translation:"masuklah ke (dalam surga) dengan aman dan damai, itulah hari yang abadi"},{id:35,text:"\u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u062f\u064e\u064a\u06e1\u0646\u064e\u0627 \u0645\u064e\u0632\u0650\u064a\u062f\u065e",translation:"Mereka di dalamnya memperoleh apa yang mereka kehendaki, dan pada Kami ada tambahannya"},{id:36,text:"\u0648\u064e\u0643\u064e\u0645\u06e1 \u0623\u064e\u0647\u06e1\u0644\u064e\u0643\u06e1\u0646\u064e\u0627 \u0642\u064e\u0628\u06e1\u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0642\u064e\u0631\u06e1\u0646\u064d \u0647\u064f\u0645\u06e1 \u0623\u064e\u0634\u064e\u062f\u0651\u064f \u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0628\u064e\u0637\u06e1\u0634\u0657\u0627 \u0641\u064e\u0646\u064e\u0642\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u06e1\u0628\u0650\u0644\u064e\u0670\u062f\u0650 \u0647\u064e\u0644\u06e1 \u0645\u0650\u0646 \u0645\u0651\u064e\u062d\u0650\u064a\u0635\u064d",translation:"Dan betapa banyak umat yang telah Kami binasakan sebelum mereka, (padahal) mereka lebih hebat kekuatannya daripada mereka (umat yang belakangan) ini. Mereka pernah menjelajah di beberapa negeri. Adakah tempat pelarian (dari kebinasaan bagi mereka)"},{id:37,text:"\u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0630\u0650\u0643\u06e1\u0631\u064e\u0649\u0670 \u0644\u0650\u0645\u064e\u0646 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0647\u064f\u06e5 \u0642\u064e\u0644\u06e1\u0628\u064c \u0623\u064e\u0648\u06e1 \u0623\u064e\u0644\u06e1\u0642\u064e\u0649 \u0671\u0644\u0633\u0651\u064e\u0645\u06e1\u0639\u064e \u0648\u064e\u0647\u064f\u0648\u064e \u0634\u064e\u0647\u0650\u064a\u062f\u065e",translation:"Sungguh, pada yang demikian itu pasti terdapat peringatan bagi orang-orang yang mempunyai hati atau yang menggunakan pendengarannya, sedang dia menyaksikannya"},{id:38,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u062e\u064e\u0644\u064e\u0642\u06e1\u0646\u064e\u0627 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0641\u0650\u064a \u0633\u0650\u062a\u0651\u064e\u0629\u0650 \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u0656 \u0648\u064e\u0645\u064e\u0627 \u0645\u064e\u0633\u0651\u064e\u0646\u064e\u0627 \u0645\u0650\u0646 \u0644\u0651\u064f\u063a\u064f\u0648\u0628\u0656",translation:"Dan sungguh, Kami telah menciptakan langit dan bumi dan apa yang ada di antara keduanya dalam enam masa, dan Kami tidak merasa letih sedikit pun"},{id:39,text:"\u0641\u064e\u0671\u0635\u06e1\u0628\u0650\u0631\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0648\u064e\u0633\u064e\u0628\u0651\u0650\u062d\u06e1 \u0628\u0650\u062d\u064e\u0645\u06e1\u062f\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0642\u064e\u0628\u06e1\u0644\u064e \u0637\u064f\u0644\u064f\u0648\u0639\u0650 \u0671\u0644\u0634\u0651\u064e\u0645\u06e1\u0633\u0650 \u0648\u064e\u0642\u064e\u0628\u06e1\u0644\u064e \u0671\u0644\u06e1\u063a\u064f\u0631\u064f\u0648\u0628\u0650",translation:"Maka bersabarlah engkau (Muhammad) terhadap apa yang mereka katakan, dan bertasbihlah dengan memuji Tuhanmu sebelum matahari terbit dan sebelum terbenam"},{id:40,text:"\u0648\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u0650 \u0641\u064e\u0633\u064e\u0628\u0651\u0650\u062d\u06e1\u0647\u064f \u0648\u064e\u0623\u064e\u062f\u06e1\u0628\u064e\u0670\u0631\u064e \u0671\u0644\u0633\u0651\u064f\u062c\u064f\u0648\u062f\u0650",translation:"Dan bertasbihlah kepada-Nya pada malam hari dan setiap selesai salat"},{id:41,text:"\u0648\u064e\u0671\u0633\u06e1\u062a\u064e\u0645\u0650\u0639\u06e1 \u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064f\u0646\u064e\u0627\u062f\u0650 \u0671\u0644\u06e1\u0645\u064f\u0646\u064e\u0627\u062f\u0650 \u0645\u0650\u0646 \u0645\u0651\u064e\u0643\u064e\u0627\u0646\u0656 \u0642\u064e\u0631\u0650\u064a\u0628\u0656",translation:"Dan dengarkanlah (seruan) pada hari (ketika) penyeru (malaikat) menyeru dari tempat yang dekat"},{id:42,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064e\u0633\u06e1\u0645\u064e\u0639\u064f\u0648\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u064a\u06e1\u062d\u064e\u0629\u064e \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064e\u0648\u06e1\u0645\u064f \u0671\u0644\u06e1\u062e\u064f\u0631\u064f\u0648\u062c\u0650",translation:"(Yaitu) pada hari (ketika) mereka mendengar suara dahsyat dengan sebenarnya. Itulah hari keluar (dari kubur)"},{id:43,text:"\u0625\u0650\u0646\u0651\u064e\u0627 \u0646\u064e\u062d\u06e1\u0646\u064f \u0646\u064f\u062d\u06e1\u064a\u0650\u06e6 \u0648\u064e\u0646\u064f\u0645\u0650\u064a\u062a\u064f \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0645\u064e\u0635\u0650\u064a\u0631\u064f",translation:"Sungguh, Kami yang menghidupkan dan mematikan, dan kepada Kami tempat kembali (semua makhluk)"},{id:44,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u062a\u064e\u0634\u064e\u0642\u0651\u064e\u0642\u064f \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064f \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0633\u0650\u0631\u064e\u0627\u0639\u0657\u0627\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062d\u064e\u0634\u06e1\u0631\u064c \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u064a\u064e\u0633\u0650\u064a\u0631\u065e",translation:"(Yaitu) pada hari (ketika) bumi terbelah, mereka keluar dengan cepat. Yang demikian itu adalah pengumpulan yang mudah bagi Kami"},{id:45,text:"\u0646\u0651\u064e\u062d\u06e1\u0646\u064f \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e\u06d6 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0628\u0650\u062c\u064e\u0628\u0651\u064e\u0627\u0631\u0656\u06d6 \u0641\u064e\u0630\u064e\u0643\u0651\u0650\u0631\u06e1 \u0628\u0650\u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u0650 \u0645\u064e\u0646 \u064a\u064e\u062e\u064e\u0627\u0641\u064f \u0648\u064e\u0639\u0650\u064a\u062f\u0650",translation:"Kami lebih mengetahui tentang apa yang mereka katakan, dan engkau (Muhammad) bukanlah seorang pemaksa terhadap mereka. Maka berilah peringatan dengan Alquran kepada siapa pun yang takut kepada ancaman-Ku"}]},{id:51,name:"\u0627\u0644\u0630\u0627\u0631\u064a\u0627\u062a",transliteration:"Adh-Dhariyat",translation:"Angin yang Menerbangkan",type:"meccan",total_verses:60,verses:[{id:1,text:"\u0648\u064e\u0671\u0644\u0630\u0651\u064e\u0640\u0670\u0631\u0650\u064a\u064e\u0670\u062a\u0650 \u0630\u064e\u0631\u06e1\u0648\u0657\u0627",translation:"Demi (angin) yang menerbangkan debu"},{id:2,text:"\u0641\u064e\u0671\u0644\u06e1\u062d\u064e\u0670\u0645\u0650\u0644\u064e\u0670\u062a\u0650 \u0648\u0650\u0642\u06e1\u0631\u0657\u0627",translation:"dan awan yang mengandung (hujan)"},{id:3,text:"\u0641\u064e\u0671\u0644\u06e1\u062c\u064e\u0670\u0631\u0650\u064a\u064e\u0670\u062a\u0650 \u064a\u064f\u0633\u06e1\u0631\u0657\u0627",translation:"dan (kapal-kapal) yang berlayar dengan mudah"},{id:4,text:"\u0641\u064e\u0671\u0644\u06e1\u0645\u064f\u0642\u064e\u0633\u0651\u0650\u0645\u064e\u0670\u062a\u0650 \u0623\u064e\u0645\u06e1\u0631\u064b\u0627",translation:"dan (malaikat-malaikat) yang membagi-bagi urusan"},{id:5,text:"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u062a\u064f\u0648\u0639\u064e\u062f\u064f\u0648\u0646\u064e \u0644\u064e\u0635\u064e\u0627\u062f\u0650\u0642\u065e",translation:"sungguh, apa yang dijanjikan kepadamu pasti benar"},{id:6,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u064e \u0644\u064e\u0648\u064e\u0670\u0642\u0650\u0639\u065e",translation:"dan sungguh, (hari) pembalasan pasti terjadi"},{id:7,text:"\u0648\u064e\u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0630\u064e\u0627\u062a\u0650 \u0671\u0644\u06e1\u062d\u064f\u0628\u064f\u0643\u0650",translation:"Demi langit yang mempunyai jalan-jalan"},{id:8,text:"\u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0644\u064e\u0641\u0650\u064a \u0642\u064e\u0648\u06e1\u0644\u0656 \u0645\u0651\u064f\u062e\u06e1\u062a\u064e\u0644\u0650\u0641\u0656",translation:"sungguh, kamu benar-benar dalam keadaan berbeda-beda pendapat"},{id:9,text:"\u064a\u064f\u0624\u06e1\u0641\u064e\u0643\u064f \u0639\u064e\u0646\u06e1\u0647\u064f \u0645\u064e\u0646\u06e1 \u0623\u064f\u0641\u0650\u0643\u064e",translation:"dipalingkan darinya (Alquran dan Rasul) orang yang dipalingkan"},{id:10,text:"\u0642\u064f\u062a\u0650\u0644\u064e \u0671\u0644\u06e1\u062e\u064e\u0631\u0651\u064e\u0640\u0670\u0635\u064f\u0648\u0646\u064e",translation:"Terkutuklah orang-orang yang banyak berdusta"},{id:11,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u063a\u064e\u0645\u06e1\u0631\u064e\u0629\u0656 \u0633\u064e\u0627\u0647\u064f\u0648\u0646\u064e",translation:"(yaitu) orang-orang yang terbenam dalam kebodohan dan kelalaian"},{id:12,text:"\u064a\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0648\u0646\u064e \u0623\u064e\u064a\u0651\u064e\u0627\u0646\u064e \u064a\u064e\u0648\u06e1\u0645\u064f \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u0650",translation:"mereka bertanya, \"Kapankah hari pembalasan itu"},{id:13,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u0647\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u064a\u064f\u0641\u06e1\u062a\u064e\u0646\u064f\u0648\u0646\u064e",translation:"(Hari pembalasan itu ialah) pada hari (ketika) mereka diazab di dalam api neraka"},{id:14,text:"\u0630\u064f\u0648\u0642\u064f\u0648\u0627\u0652 \u0641\u0650\u062a\u06e1\u0646\u064e\u062a\u064e\u0643\u064f\u0645\u06e1 \u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0643\u064f\u0646\u062a\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6 \u062a\u064e\u0633\u06e1\u062a\u064e\u0639\u06e1\u062c\u0650\u0644\u064f\u0648\u0646\u064e",translation:"(Dikatakan kepada mereka), \"Rasakanlah azabmu itu. Inilah azab yang dahulu kamu minta agar disegerakan"},{id:15,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0656 \u0648\u064e\u0639\u064f\u064a\u064f\u0648\u0646\u064d",translation:"Sesungguhnya orang-orang yang bertakwa berada di dalam taman-taman (surga) dan mata air"},{id:16,text:"\u0621\u064e\u0627\u062e\u0650\u0630\u0650\u064a\u0646\u064e \u0645\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u064e\u0649\u0670\u0647\u064f\u0645\u06e1 \u0631\u064e\u0628\u0651\u064f\u0647\u064f\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0642\u064e\u0628\u06e1\u0644\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u064f\u062d\u06e1\u0633\u0650\u0646\u0650\u064a\u0646\u064e",translation:"mereka mengambil apa yang diberikan Tuhan kepada mereka. Sesungguhnya mereka sebelum itu (di dunia) adalah orang-orang yang berbuat baik"},{id:17,text:"\u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0642\u064e\u0644\u0650\u064a\u0644\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u0650 \u0645\u064e\u0627 \u064a\u064e\u0647\u06e1\u062c\u064e\u0639\u064f\u0648\u0646\u064e",translation:"mereka sedikit sekali tidur pada waktu malam"},{id:18,text:"\u0648\u064e\u0628\u0650\u0671\u0644\u06e1\u0623\u064e\u0633\u06e1\u062d\u064e\u0627\u0631\u0650 \u0647\u064f\u0645\u06e1 \u064a\u064e\u0633\u06e1\u062a\u064e\u063a\u06e1\u0641\u0650\u0631\u064f\u0648\u0646\u064e",translation:"dan pada akhir malam mereka memohon ampunan (kepada Allah)"},{id:19,text:"\u0648\u064e\u0641\u0650\u064a\u0653 \u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u0650\u0647\u0650\u0645\u06e1 \u062d\u064e\u0642\u0651\u065e \u0644\u0651\u0650\u0644\u0633\u0651\u064e\u0627\u0653\u0626\u0650\u0644\u0650 \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u062d\u06e1\u0631\u064f\u0648\u0645\u0650",translation:"Dan pada harta benda mereka ada hak untuk orang miskin yang meminta, dan orang miskin yang tidak meminta"},{id:20,text:"\u0648\u064e\u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u065e \u0644\u0651\u0650\u0644\u06e1\u0645\u064f\u0648\u0642\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dan di bumi terdapat tanda-tanda (kebesaran Allah) bagi orang-orang yang yakin"},{id:21,text:"\u0648\u064e\u0641\u0650\u064a\u0653 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u06e1\u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064f\u0628\u06e1\u0635\u0650\u0631\u064f\u0648\u0646\u064e",translation:"dan (juga) pada dirimu sendiri. Maka apakah kamu tidak memperhatikan"},{id:22,text:"\u0648\u064e\u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0631\u0650\u0632\u06e1\u0642\u064f\u0643\u064f\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627 \u062a\u064f\u0648\u0639\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Dan di langit terdapat (sebab-sebab) rezekimu dan apa yang dijanjikan kepadamu"},{id:23,text:"\u0641\u064e\u0648\u064e\u0631\u064e\u0628\u0651\u0650 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u062d\u064e\u0642\u0651\u065e \u0645\u0651\u0650\u062b\u06e1\u0644\u064e \u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u0646\u0637\u0650\u0642\u064f\u0648\u0646\u064e",translation:"Maka demi Tuhan langit dan bumi, sungguh, apa yang dijanjikan itu pasti terjadi seperti apa yang kamu ucapkan"},{id:24,text:"\u0647\u064e\u0644\u06e1 \u0623\u064e\u062a\u064e\u0649\u0670\u0643\u064e \u062d\u064e\u062f\u0650\u064a\u062b\u064f \u0636\u064e\u064a\u06e1\u0641\u0650 \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064e \u0671\u0644\u06e1\u0645\u064f\u0643\u06e1\u0631\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Sudahkah sampai kepadamu (Muhammad) cerita tamu Ibrahim (malaikat-malaikat) yang dimuliakan"},{id:25,text:"\u0625\u0650\u0630\u06e1 \u062f\u064e\u062e\u064e\u0644\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0641\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0633\u064e\u0644\u064e\u0670\u0645\u0657\u0627\u06d6 \u0642\u064e\u0627\u0644\u064e \u0633\u064e\u0644\u064e\u0670\u0645\u065e \u0642\u064e\u0648\u06e1\u0645\u065e \u0645\u0651\u064f\u0646\u0643\u064e\u0631\u064f\u0648\u0646\u064e",translation:"(Ingatlah) ketika mereka masuk ke tempatnya lalu mengucapkan, \"Sal\u0101man (salam)\", Ibrahim menjawab, \"Sal\u0101mun (salam)\". (Mereka itu) orang-orang yang belum dikenalnya"},{id:26,text:"\u0641\u064e\u0631\u064e\u0627\u063a\u064e \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0647\u06e1\u0644\u0650\u0647\u0650\u06e6 \u0641\u064e\u062c\u064e\u0627\u0653\u0621\u064e \u0628\u0650\u0639\u0650\u062c\u06e1\u0644\u0656 \u0633\u064e\u0645\u0650\u064a\u0646\u0656",translation:"Maka diam-diam dia (Ibrahim) pergi menemui keluarganya, kemudian dibawanya daging anak sapi gemuk (yang dibakar)"},{id:27,text:"\u0641\u064e\u0642\u064e\u0631\u0651\u064e\u0628\u064e\u0647\u064f\u06e5\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0644\u064e\u0627 \u062a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f\u0648\u0646\u064e",translation:"lalu dihidangkannya kepada mereka (tetapi mereka tidak mau makan). Ibrahim berkata, \"Mengapa tidak kamu makan"},{id:28,text:"\u0641\u064e\u0623\u064e\u0648\u06e1\u062c\u064e\u0633\u064e \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u062e\u0650\u064a\u0641\u064e\u0629\u0657\u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u062a\u064e\u062e\u064e\u0641\u06e1\u06d6 \u0648\u064e\u0628\u064e\u0634\u0651\u064e\u0631\u064f\u0648\u0647\u064f \u0628\u0650\u063a\u064f\u0644\u064e\u0670\u0645\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u0656",translation:"Maka dia (Ibrahim) merasa takut terhadap mereka. Mereka berkata, \"Janganlah kamu takut,\" dan mereka memberi kabar gembira kepadanya dengan (kelahiran) seorang anak yang alim (Ishak)"},{id:29,text:"\u0641\u064e\u0623\u064e\u0642\u06e1\u0628\u064e\u0644\u064e\u062a\u0650 \u0671\u0645\u06e1\u0631\u064e\u0623\u064e\u062a\u064f\u0647\u064f\u06e5 \u0641\u0650\u064a \u0635\u064e\u0631\u0651\u064e\u0629\u0656 \u0641\u064e\u0635\u064e\u0643\u0651\u064e\u062a\u06e1 \u0648\u064e\u062c\u06e1\u0647\u064e\u0647\u064e\u0627 \u0648\u064e\u0642\u064e\u0627\u0644\u064e\u062a\u06e1 \u0639\u064e\u062c\u064f\u0648\u0632\u064c \u0639\u064e\u0642\u0650\u064a\u0645\u065e",translation:"Kemudian istrinya datang memekik (tercengang) lalu menepuk wajahnya sendiri seraya bekata, \"(Aku ini) seorang perempuan tua yang mandul"},{id:30,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u0650 \u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u0650\u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u062d\u064e\u0643\u0650\u064a\u0645\u064f \u0671\u0644\u06e1\u0639\u064e\u0644\u0650\u064a\u0645\u064f",translation:"Mereka berkata, \"Demikianlah Tuhanmu berfirman. Sungguh, Dialah Yang Mahabijaksana, Maha Mengetahui"},{id:31,text:"\u06de\u0642\u064e\u0627\u0644\u064e \u0641\u064e\u0645\u064e\u0627 \u062e\u064e\u0637\u06e1\u0628\u064f\u0643\u064f\u0645\u06e1 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u06e1\u0645\u064f\u0631\u06e1\u0633\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dia (Ibrahim) berkata, \"Apakah urusanmu yang penting wahai para utusan"},{id:32,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0623\u064f\u0631\u06e1\u0633\u0650\u0644\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u06e1\u0645\u0656 \u0645\u0651\u064f\u062c\u06e1\u0631\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Mereka menjawab, \"Sesungguhnya kami diutus kepada kaum yang berdosa (kaum Lu\u1e6d)"},{id:33,text:"\u0644\u0650\u0646\u064f\u0631\u06e1\u0633\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u062d\u0650\u062c\u064e\u0627\u0631\u064e\u0629\u0657 \u0645\u0651\u0650\u0646 \u0637\u0650\u064a\u0646\u0656",translation:"agar kami menimpa mereka dengan batu-batu dari tanah (yang keras)"},{id:34,text:"\u0645\u0651\u064f\u0633\u064e\u0648\u0651\u064e\u0645\u064e\u0629\u064b \u0639\u0650\u0646\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0644\u0650\u0644\u06e1\u0645\u064f\u0633\u06e1\u0631\u0650\u0641\u0650\u064a\u0646\u064e",translation:"yang ditandai dari Tuhanmu untuk (membinasakan) orang-orang yang melampaui batas"},{id:35,text:"\u0641\u064e\u0623\u064e\u062e\u06e1\u0631\u064e\u062c\u06e1\u0646\u064e\u0627 \u0645\u064e\u0646 \u0643\u064e\u0627\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Lalu Kami keluarkan orang-orang yang beriman yang berada di dalamnya (negeri kaum Lu\u1e6d)"},{id:36,text:"\u0641\u064e\u0645\u064e\u0627 \u0648\u064e\u062c\u064e\u062f\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u063a\u064e\u064a\u06e1\u0631\u064e \u0628\u064e\u064a\u06e1\u062a\u0656 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0633\u06e1\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Maka Kami tidak mendapati di dalamnya (negeri itu), kecuali satu rumah dari orang-orang muslim (Lu\u1e6d)"},{id:37,text:"\u0648\u064e\u062a\u064e\u0631\u064e\u0643\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627\u0653 \u0621\u064e\u0627\u064a\u064e\u0629\u0657 \u0644\u0651\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062e\u064e\u0627\u0641\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0671\u0644\u06e1\u0623\u064e\u0644\u0650\u064a\u0645\u064e",translation:"Dan Kami tinggalkan padanya (negeri itu) suatu tanda814) bagi orang-orang yang takut kepada azab yang pedih"},{id:38,text:"\u0648\u064e\u0641\u0650\u064a \u0645\u064f\u0648\u0633\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u06e1 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0628\u0650\u0633\u064f\u0644\u06e1\u0637\u064e\u0670\u0646\u0656 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u0656",translation:"Dan pada Musa (terdapat tanda-tanda kekuasaan Allah) ketika Kami mengutusnya kepada Fir'aun dengan membawa mukjizat yang nyata"},{id:39,text:"\u0641\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649\u0670 \u0628\u0650\u0631\u064f\u0643\u06e1\u0646\u0650\u0647\u0650\u06e6 \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0633\u064e\u0670\u062d\u0650\u0631\u064c \u0623\u064e\u0648\u06e1 \u0645\u064e\u062c\u06e1\u0646\u064f\u0648\u0646\u065e",translation:"Tetapi dia (Fir'aun) bersama bala tentaranya berpaling dan berkata, \"Dia adalah seorang pesihir atau orang gila"},{id:40,text:"\u0641\u064e\u0623\u064e\u062e\u064e\u0630\u06e1\u0646\u064e\u0670\u0647\u064f \u0648\u064e\u062c\u064f\u0646\u064f\u0648\u062f\u064e\u0647\u064f\u06e5 \u0641\u064e\u0646\u064e\u0628\u064e\u0630\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u064a\u064e\u0645\u0651\u0650 \u0648\u064e\u0647\u064f\u0648\u064e \u0645\u064f\u0644\u0650\u064a\u0645\u065e",translation:"Maka Kami siksa dia beserta bala tentaranya, lalu Kami lemparkan mereka ke dalam laut, dalam keadaan tercela"},{id:41,text:"\u0648\u064e\u0641\u0650\u064a \u0639\u064e\u0627\u062f\u064d \u0625\u0650\u0630\u06e1 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u064f \u0671\u0644\u0631\u0651\u0650\u064a\u062d\u064e \u0671\u0644\u06e1\u0639\u064e\u0642\u0650\u064a\u0645\u064e",translation:"Dan (juga) pada (kisah kaum) '\u0100d, ketika Kami kirimkan kepada mereka angin yang membinasakan"},{id:42,text:"\u0645\u064e\u0627 \u062a\u064e\u0630\u064e\u0631\u064f \u0645\u0650\u0646 \u0634\u064e\u064a\u06e1\u0621\u064d \u0623\u064e\u062a\u064e\u062a\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u064e\u062a\u06e1\u0647\u064f \u0643\u064e\u0671\u0644\u0631\u0651\u064e\u0645\u0650\u064a\u0645\u0650",translation:"(angin itu) tidak membiarkan suatu apa pun yang dilandanya, bahkan dijadikannya seperti serbuk"},{id:43,text:"\u0648\u064e\u0641\u0650\u064a \u062b\u064e\u0645\u064f\u0648\u062f\u064e \u0625\u0650\u0630\u06e1 \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u062a\u064e\u0645\u064e\u062a\u0651\u064e\u0639\u064f\u0648\u0627\u0652 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062d\u0650\u064a\u0646\u0656",translation:"Dan pada (kisah kaum) Samud, ketika dikatakan kepada mereka, \"Bersenang-senanglah kamu sampai waktu yang ditentukan"},{id:44,text:"\u0641\u064e\u0639\u064e\u062a\u064e\u0648\u06e1\u0627\u0652 \u0639\u064e\u0646\u06e1 \u0623\u064e\u0645\u06e1\u0631\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0641\u064e\u0623\u064e\u062e\u064e\u0630\u064e\u062a\u06e1\u0647\u064f\u0645\u064f \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0639\u0650\u0642\u064e\u0629\u064f \u0648\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0646\u0638\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Lalu mereka berlaku angkuh terhadap perintah Tuhannya, maka mereka disambar petir sedang mereka melihatnya"},{id:45,text:"\u0641\u064e\u0645\u064e\u0627 \u0671\u0633\u06e1\u062a\u064e\u0637\u064e\u0670\u0639\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0642\u0650\u064a\u064e\u0627\u0645\u0656 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0645\u064f\u0646\u062a\u064e\u0635\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Maka mereka tidak mampu bangun dan juga tidak mendapat pertolongan"},{id:46,text:"\u0648\u064e\u0642\u064e\u0648\u06e1\u0645\u064e \u0646\u064f\u0648\u062d\u0656 \u0645\u0651\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f\u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0642\u064e\u0648\u06e1\u0645\u0657\u0627 \u0641\u064e\u0670\u0633\u0650\u0642\u0650\u064a\u0646\u064e",translation:"dan sebelum itu (telah Kami binasakan) kaum Nuh. Sungguh, mereka adalah kaum yang fasik"},{id:47,text:"\u0648\u064e\u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u064e \u0628\u064e\u0646\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064e\u0627 \u0628\u0650\u0623\u064e\u064a\u06e1\u064a\u0652\u062f\u0656 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0645\u064f\u0648\u0633\u0650\u0639\u064f\u0648\u0646\u064e",translation:"Dan langit Kami bangun dengan kekuasaan (Kami), dan Kami benar-benar meluaskannya"},{id:48,text:"\u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0641\u064e\u0631\u064e\u0634\u06e1\u0646\u064e\u0670\u0647\u064e\u0627 \u0641\u064e\u0646\u0650\u0639\u06e1\u0645\u064e \u0671\u0644\u06e1\u0645\u064e\u0670\u0647\u0650\u062f\u064f\u0648\u0646\u064e",translation:"Dan bumi telah Kami hamparkan; maka (Kami) sebaik-baik yang menghamparkan"},{id:49,text:"\u0648\u064e\u0645\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u064d \u062e\u064e\u0644\u064e\u0642\u06e1\u0646\u064e\u0627 \u0632\u064e\u0648\u06e1\u062c\u064e\u064a\u06e1\u0646\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan segala sesuatu Kami ciptakan berpasang-pasangan agar kamu mengingat (kebesaran Allah)"},{id:50,text:"\u0641\u064e\u0641\u0650\u0631\u0651\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f \u0646\u064e\u0630\u0650\u064a\u0631\u065e \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u065e",translation:"Maka segeralah kembali kepada (menaati) Allah. Sungguh, aku seorang pemberi peringatan yang jelas dari Allah untukmu"},{id:51,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062c\u06e1\u0639\u064e\u0644\u064f\u0648\u0627\u0652 \u0645\u064e\u0639\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u064e\u0670\u0647\u064b\u0627 \u0621\u064e\u0627\u062e\u064e\u0631\u064e\u06d6 \u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f \u0646\u064e\u0630\u0650\u064a\u0631\u065e \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u065e",translation:"Dan janganlah kamu mengadakan tuhan yang lain selain Allah. Sungguh, aku seorang pemberi peringatan yang jelas dari Allah untukmu"},{id:52,text:"\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u064e\u0627\u0653 \u0623\u064e\u062a\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u0645 \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0633\u064e\u0627\u062d\u0650\u0631\u064c \u0623\u064e\u0648\u06e1 \u0645\u064e\u062c\u06e1\u0646\u064f\u0648\u0646\u064c",translation:"Demikianlah setiap kali seorang rasul yang datang kepada orang-orang yang sebelum mereka, mereka (kaumnya) pasti mengatakan, \"Dia itu pesihir atau orang gila"},{id:53,text:"\u0623\u064e\u062a\u064e\u0648\u064e\u0627\u0635\u064e\u0648\u06e1\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6\u06da \u0628\u064e\u0644\u06e1 \u0647\u064f\u0645\u06e1 \u0642\u064e\u0648\u06e1\u0645\u065e \u0637\u064e\u0627\u063a\u064f\u0648\u0646\u064e",translation:"Apakah mereka saling berpesan tentang apa yang dikatakan itu. Sebenarnya mereka adalah kaum yang melampaui batas"},{id:54,text:"\u0641\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0641\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064e \u0628\u0650\u0645\u064e\u0644\u064f\u0648\u0645\u0656",translation:"Maka berpalinglah engkau dari mereka, dan engkau sama sekali tidak tercela"},{id:55,text:"\u0648\u064e\u0630\u064e\u0643\u0651\u0650\u0631\u06e1 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0630\u0651\u0650\u0643\u06e1\u0631\u064e\u0649\u0670 \u062a\u064e\u0646\u0641\u064e\u0639\u064f \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dan tetaplah memberi peringatan, karena sesungguhnya peringatan itu bermanfaat bagi orang-orang mukmin"},{id:56,text:"\u0648\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u06e1\u062a\u064f \u0671\u0644\u06e1\u062c\u0650\u0646\u0651\u064e \u0648\u064e\u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0644\u0650\u064a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0646\u0650",translation:"Aku tidak menciptakan jin dan manusia melainkan agar mereka beribadah kepada-Ku"},{id:57,text:"\u0645\u064e\u0627\u0653 \u0623\u064f\u0631\u0650\u064a\u062f\u064f \u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0631\u0651\u0650\u0632\u06e1\u0642\u0656 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0631\u0650\u064a\u062f\u064f \u0623\u064e\u0646 \u064a\u064f\u0637\u06e1\u0639\u0650\u0645\u064f\u0648\u0646\u0650",translation:"Aku tidak menghendaki rezeki sedikit pun dari mereka dan Aku tidak menghendaki agar mereka memberi makan kepada-Ku"},{id:58,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0647\u064f\u0648\u064e \u0671\u0644\u0631\u0651\u064e\u0632\u0651\u064e\u0627\u0642\u064f \u0630\u064f\u0648 \u0671\u0644\u06e1\u0642\u064f\u0648\u0651\u064e\u0629\u0650 \u0671\u0644\u06e1\u0645\u064e\u062a\u0650\u064a\u0646\u064f",translation:"Sungguh Allah, Dialah Pemberi rezeki yang mempunyai kekuatan lagi sangat kokoh"},{id:59,text:"\u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627\u0652 \u0630\u064e\u0646\u064f\u0648\u0628\u0657\u0627 \u0645\u0651\u0650\u062b\u06e1\u0644\u064e \u0630\u064e\u0646\u064f\u0648\u0628\u0650 \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u0650\u0647\u0650\u0645\u06e1 \u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0639\u06e1\u062c\u0650\u0644\u064f\u0648\u0646\u0650",translation:"Maka sungguh, untuk orang-orang yang zalim ada bagian (azab) seperti bagian teman-teman mereka (dahulu); maka janganlah mereka meminta kepada-Ku untuk menyegerakannya"},{id:60,text:"\u0641\u064e\u0648\u064e\u064a\u06e1\u0644\u065e \u0644\u0651\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u064a\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u0645\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u0648\u0639\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Maka celakalah orang-orang yang kafir pada hari yang telah dijanjikan kepada mereka (hari Kiamat)"}]},{id:52,name:"\u0627\u0644\u0637\u0648\u0631",transliteration:"At-Tur",translation:"Bukit",type:"meccan",total_verses:49,verses:[{id:1,text:"\u0648\u064e\u0671\u0644\u0637\u0651\u064f\u0648\u0631\u0650",translation:"Demi gunung (Sinai)"},{id:2,text:"\u0648\u064e\u0643\u0650\u062a\u064e\u0670\u0628\u0656 \u0645\u0651\u064e\u0633\u06e1\u0637\u064f\u0648\u0631\u0656",translation:"dan demi Kitab yang ditulis"},{id:3,text:"\u0641\u0650\u064a \u0631\u064e\u0642\u0651\u0656 \u0645\u0651\u064e\u0646\u0634\u064f\u0648\u0631\u0656",translation:"pada lembaran yang terbuka"},{id:4,text:"\u0648\u064e\u0671\u0644\u06e1\u0628\u064e\u064a\u06e1\u062a\u0650 \u0671\u0644\u06e1\u0645\u064e\u0639\u06e1\u0645\u064f\u0648\u0631\u0650",translation:"demi Baitulma'mur (Ka'bah)"},{id:5,text:"\u0648\u064e\u0671\u0644\u0633\u0651\u064e\u0642\u06e1\u0641\u0650 \u0671\u0644\u06e1\u0645\u064e\u0631\u06e1\u0641\u064f\u0648\u0639\u0650",translation:"demi atap yang ditinggikan (langit)"},{id:6,text:"\u0648\u064e\u0671\u0644\u06e1\u0628\u064e\u062d\u06e1\u0631\u0650 \u0671\u0644\u06e1\u0645\u064e\u0633\u06e1\u062c\u064f\u0648\u0631\u0650",translation:"demi lautan yang penuh gelombang"},{id:7,text:"\u0625\u0650\u0646\u0651\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0644\u064e\u0648\u064e\u0670\u0642\u0650\u0639\u065e",translation:"sungguh, azab Tuhanmu pasti terjadi"},{id:8,text:"\u0645\u0651\u064e\u0627 \u0644\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646 \u062f\u064e\u0627\u0641\u0650\u0639\u0656",translation:"tidak sesuatu pun yang dapat menolaknya"},{id:9,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u062a\u064e\u0645\u064f\u0648\u0631\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u064f \u0645\u064e\u0648\u06e1\u0631\u0657\u0627",translation:"pada hari (ketika) langit berguncang sekeras-kerasnya"},{id:10,text:"\u0648\u064e\u062a\u064e\u0633\u0650\u064a\u0631\u064f \u0671\u0644\u06e1\u062c\u0650\u0628\u064e\u0627\u0644\u064f \u0633\u064e\u064a\u06e1\u0631\u0657\u0627",translation:"dan gunung berjalan (berpindah-pindah)"},{id:11,text:"\u0641\u064e\u0648\u064e\u064a\u06e1\u0644\u065e \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u0644\u0651\u0650\u0644\u06e1\u0645\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u0650\u064a\u0646\u064e",translation:"Maka celakalah pada hari itu orang-orang yang mendustakan"},{id:12,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u062e\u064e\u0648\u06e1\u0636\u0656 \u064a\u064e\u0644\u06e1\u0639\u064e\u0628\u064f\u0648\u0646\u064e",translation:"Orang-orang yang bermain-main dalam kebatilan (perbuatan dosa)"},{id:13,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064f\u062f\u064e\u0639\u0651\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0646\u064e\u0627\u0631\u0650 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u062f\u064e\u0639\u0651\u064b\u0627",translation:"pada hari (ketika) itu mereka di dorong ke neraka Jahanam dengan sekuat-kuatnya"},{id:14,text:"\u0647\u064e\u0670\u0630\u0650\u0647\u0650 \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u064f \u0671\u0644\u0651\u064e\u062a\u0650\u064a \u0643\u064f\u0646\u062a\u064f\u0645 \u0628\u0650\u0647\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f\u0648\u0646\u064e",translation:"(Dikatakan kepada mereka), \"Inilah neraka yang dahulu kamu mendustakannya"},{id:15,text:"\u0623\u064e\u0641\u064e\u0633\u0650\u062d\u06e1\u0631\u064c \u0647\u064e\u0670\u0630\u064e\u0627\u0653 \u0623\u064e\u0645\u06e1 \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0644\u064e\u0627 \u062a\u064f\u0628\u06e1\u0635\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Maka apakah ini sihir? Ataukah kamu tidak melihat"},{id:16,text:"\u0671\u0635\u06e1\u0644\u064e\u0648\u06e1\u0647\u064e\u0627 \u0641\u064e\u0671\u0635\u06e1\u0628\u0650\u0631\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0648\u06e1 \u0644\u064e\u0627 \u062a\u064e\u0635\u06e1\u0628\u0650\u0631\u064f\u0648\u0627\u0652 \u0633\u064e\u0648\u064e\u0627\u0653\u0621\u064c \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1\u06d6 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u062a\u064f\u062c\u06e1\u0632\u064e\u0648\u06e1\u0646\u064e \u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Masuklah ke dalamnya (rasakanlah panas apinya); baik kamu bersabar atau tidak, sama saja bagimu; sesungguhnya kamu hanya diberi balasan atas apa yang telah kamu kerjakan"},{id:17,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0656 \u0648\u064e\u0646\u064e\u0639\u0650\u064a\u0645\u0656",translation:"Sesungguhnya orang-orang yang bertakwa berada dalam surga dan kenikmatan"},{id:18,text:"\u0641\u064e\u0670\u0643\u0650\u0647\u0650\u064a\u0646\u064e \u0628\u0650\u0645\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u064e\u0649\u0670\u0647\u064f\u0645\u06e1 \u0631\u064e\u0628\u0651\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0648\u064e\u0642\u064e\u0649\u0670\u0647\u064f\u0645\u06e1 \u0631\u064e\u0628\u0651\u064f\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0671\u0644\u06e1\u062c\u064e\u062d\u0650\u064a\u0645\u0650",translation:"mereka bersuka ria dengan apa yang diberikan Tuhan kepada mereka; dan Tuhan memelihara mereka dari azab neraka"},{id:19,text:"\u0643\u064f\u0644\u064f\u0648\u0627\u0652 \u0648\u064e\u0671\u0634\u06e1\u0631\u064e\u0628\u064f\u0648\u0627\u0652 \u0647\u064e\u0646\u0650\u064a\u0653\u0640\u0654\u064e\u06e2\u0627 \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"(Dikatakan kepada mereka), \"Makan dan minumlah dengan rasa nikmat sebagai balasan dari apa yang telah kamu kerjakan"},{id:20,text:"\u0645\u064f\u062a\u0651\u064e\u0643\u0650\u0640\u0654\u0650\u064a\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0633\u064f\u0631\u064f\u0631\u0656 \u0645\u0651\u064e\u0635\u06e1\u0641\u064f\u0648\u0641\u064e\u0629\u0656\u06d6 \u0648\u064e\u0632\u064e\u0648\u0651\u064e\u062c\u06e1\u0646\u064e\u0670\u0647\u064f\u0645 \u0628\u0650\u062d\u064f\u0648\u0631\u064d \u0639\u0650\u064a\u0646\u0656",translation:"Mereka bersandar di atas dipan-dipan yang tersusun dan Kami berikan kepada mereka pasangan bidadari yang bermata indah"},{id:21,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064e\u062a\u06e1\u0647\u064f\u0645\u06e1 \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u062a\u064f\u0647\u064f\u0645 \u0628\u0650\u0625\u0650\u064a\u0645\u064e\u0670\u0646\u064d \u0623\u064e\u0644\u06e1\u062d\u064e\u0642\u06e1\u0646\u064e\u0627 \u0628\u0650\u0647\u0650\u0645\u06e1 \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u062a\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0644\u064e\u062a\u06e1\u0646\u064e\u0670\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0639\u064e\u0645\u064e\u0644\u0650\u0647\u0650\u0645 \u0645\u0651\u0650\u0646 \u0634\u064e\u064a\u06e1\u0621\u0656\u06da \u0643\u064f\u0644\u0651\u064f \u0671\u0645\u06e1\u0631\u0650\u064a\u0655\u0650\u06ed \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064e \u0631\u064e\u0647\u0650\u064a\u0646\u065e",translation:"Dan orang-orang yang beriman, beserta anak cucu mereka yang mengikuti mereka dalam keimanan, Kami pertemukan mereka dengan anak cucu mereka (di dalam surga), dan Kami tidak mengurangi sedikit pun pahala amal (kebajikan) mereka. Setiap orang terikat dengan apa yang dikerjakannya"},{id:22,text:"\u0648\u064e\u0623\u064e\u0645\u06e1\u062f\u064e\u062f\u06e1\u0646\u064e\u0670\u0647\u064f\u0645 \u0628\u0650\u0641\u064e\u0670\u0643\u0650\u0647\u064e\u0629\u0656 \u0648\u064e\u0644\u064e\u062d\u06e1\u0645\u0656 \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u0634\u06e1\u062a\u064e\u0647\u064f\u0648\u0646\u064e",translation:"Dan Kami berikan kepada mereka tambahan berupa buah-buahan dan daging dari segala jenis yang mereka ingini"},{id:23,text:"\u064a\u064e\u062a\u064e\u0646\u064e\u0670\u0632\u064e\u0639\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0643\u064e\u0623\u06e1\u0633\u0657\u0627 \u0644\u0651\u064e\u0627 \u0644\u064e\u063a\u06e1\u0648\u065e \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0623\u06e1\u062b\u0650\u064a\u0645\u065e",translation:"(Di dalam surga itu) mereka saling mengulurkan gelas yang isinya tidak (menimbulkan) ucapan sia-sia ataupun perbuatan dosa"},{id:24,text:"\u06de\u0648\u064e\u064a\u064e\u0637\u064f\u0648\u0641\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u063a\u0650\u0644\u06e1\u0645\u064e\u0627\u0646\u065e \u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0644\u064f\u0624\u06e1\u0644\u064f\u0624\u065e \u0645\u0651\u064e\u0643\u06e1\u0646\u064f\u0648\u0646\u065e",translation:"Dan di sekitar mereka ada anak-anak muda yang berkeliling untuk (melayani) mereka, seakan-akan mereka itu mutiara yang tersimpan"},{id:25,text:"\u0648\u064e\u0623\u064e\u0642\u06e1\u0628\u064e\u0644\u064e \u0628\u064e\u0639\u06e1\u0636\u064f\u0647\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u06e1\u0636\u0656 \u064a\u064e\u062a\u064e\u0633\u064e\u0627\u0653\u0621\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan sebagian mereka berhadap-hadapan satu sama lain saling bertegur sapa"},{id:26,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0642\u064e\u0628\u06e1\u0644\u064f \u0641\u0650\u064a\u0653 \u0623\u064e\u0647\u06e1\u0644\u0650\u0646\u064e\u0627 \u0645\u064f\u0634\u06e1\u0641\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Mereka berkata, \"Sesungguhnya kami dahulu, sewaktu berada di tengah-tengah keluarga kami merasa takut (akan diazab)"},{id:27,text:"\u0641\u064e\u0645\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0648\u064e\u0648\u064e\u0642\u064e\u0649\u0670\u0646\u064e\u0627 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064f\u0648\u0645\u0650",translation:"Maka Allah memberikan karunia kepada kami dan memelihara kami dari azab neraka"},{id:28,text:"\u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f \u0646\u064e\u062f\u06e1\u0639\u064f\u0648\u0647\u064f\u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0628\u064e\u0631\u0651\u064f \u0671\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",translation:"Sesungguhnya kami menyembah-Nya sejak dahulu. Dialah Yang Maha Melimpahkan Kebaikan, Maha Penyayang"},{id:29,text:"\u0641\u064e\u0630\u064e\u0643\u0651\u0650\u0631\u06e1 \u0641\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064e \u0628\u0650\u0646\u0650\u0639\u06e1\u0645\u064e\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0628\u0650\u0643\u064e\u0627\u0647\u0650\u0646\u0656 \u0648\u064e\u0644\u064e\u0627 \u0645\u064e\u062c\u06e1\u0646\u064f\u0648\u0646\u064d",translation:"Maka peringatkanlah, karena dengan nikmat Tuhanmu engkau (Muhammad) bukanlah seorang tukang tenung dan bukan pula orang gila"},{id:30,text:"\u0623\u064e\u0645\u06e1 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0634\u064e\u0627\u0639\u0650\u0631\u065e \u0646\u0651\u064e\u062a\u064e\u0631\u064e\u0628\u0651\u064e\u0635\u064f \u0628\u0650\u0647\u0650\u06e6 \u0631\u064e\u064a\u06e1\u0628\u064e \u0671\u0644\u06e1\u0645\u064e\u0646\u064f\u0648\u0646\u0650",translation:"Bahkan mereka berkata, \"Dia adalah seorang penyair yang kami tunggu-tunggu kecelakaan menimpanya"},{id:31,text:"\u0642\u064f\u0644\u06e1 \u062a\u064e\u0631\u064e\u0628\u0651\u064e\u0635\u064f\u0648\u0627\u0652 \u0641\u064e\u0625\u0650\u0646\u0651\u0650\u064a \u0645\u064e\u0639\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u062a\u064e\u0631\u064e\u0628\u0651\u0650\u0635\u0650\u064a\u0646\u064e",translation:"Katakanlah (Muhammad), \"Tunggulah! Sesungguhnya aku pun termasuk orang yang sedang menunggu bersama kamu"},{id:32,text:"\u0623\u064e\u0645\u06e1 \u062a\u064e\u0623\u06e1\u0645\u064f\u0631\u064f\u0647\u064f\u0645\u06e1 \u0623\u064e\u062d\u06e1\u0644\u064e\u0670\u0645\u064f\u0647\u064f\u0645 \u0628\u0650\u0647\u064e\u0670\u0630\u064e\u0627\u0653\u06da \u0623\u064e\u0645\u06e1 \u0647\u064f\u0645\u06e1 \u0642\u064e\u0648\u06e1\u0645\u065e \u0637\u064e\u0627\u063a\u064f\u0648\u0646\u064e",translation:"Apakah mereka diperintah oleh pikiran-pikiran mereka untuk mengucapkan (tuduhan-tuduhan) ini ataukah mereka kaum yang melampaui batas"},{id:33,text:"\u0623\u064e\u0645\u06e1 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u062a\u064e\u0642\u064e\u0648\u0651\u064e\u0644\u064e\u0647\u064f\u06e5\u06da \u0628\u064e\u0644 \u0644\u0651\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Ataukah mereka berkata, \"Dia (Muhammad) mereka-rekanya.\" Tidak! Merekalah yang tidak beriman"},{id:34,text:"\u0641\u064e\u0644\u06e1\u064a\u064e\u0623\u06e1\u062a\u064f\u0648\u0627\u0652 \u0628\u0650\u062d\u064e\u062f\u0650\u064a\u062b\u0656 \u0645\u0651\u0650\u062b\u06e1\u0644\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0635\u064e\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Maka cobalah mereka membuat yang semisal dengannya (Alquran) jika mereka orang-orang yang benar"},{id:35,text:"\u0623\u064e\u0645\u06e1 \u062e\u064f\u0644\u0650\u0642\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1 \u063a\u064e\u064a\u06e1\u0631\u0650 \u0634\u064e\u064a\u06e1\u0621\u064d \u0623\u064e\u0645\u06e1 \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u062e\u064e\u0670\u0644\u0650\u0642\u064f\u0648\u0646\u064e",translation:"Atau apakah mereka tercipta tanpa asal-usul ataukah mereka yang menciptakan (diri mereka sendiri)"},{id:36,text:"\u0623\u064e\u0645\u06e1 \u062e\u064e\u0644\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e\u06da \u0628\u064e\u0644 \u0644\u0651\u064e\u0627 \u064a\u064f\u0648\u0642\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Ataukah mereka telah menciptakan langit dan bumi? Sebenarnya mereka tidak meyakini (apa yang mereka katakan)"},{id:37,text:"\u0623\u064e\u0645\u06e1 \u0639\u0650\u0646\u062f\u064e\u0647\u064f\u0645\u06e1 \u062e\u064e\u0632\u064e\u0627\u0653\u0626\u0650\u0646\u064f \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0623\u064e\u0645\u06e1 \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064f\u0635\u06dc\u064e\u064a\u06e1\u0637\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Ataukah di sisi mereka ada perbendaharaan Tuhanmu ataukah mereka yang berkuasa"},{id:38,text:"\u0623\u064e\u0645\u06e1 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0633\u064f\u0644\u0651\u064e\u0645\u065e \u064a\u064e\u0633\u06e1\u062a\u064e\u0645\u0650\u0639\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0647\u0650\u06d6 \u0641\u064e\u0644\u06e1\u064a\u064e\u0623\u06e1\u062a\u0650 \u0645\u064f\u0633\u06e1\u062a\u064e\u0645\u0650\u0639\u064f\u0647\u064f\u0645 \u0628\u0650\u0633\u064f\u0644\u06e1\u0637\u064e\u0670\u0646\u0656 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u064d",translation:"Atau apakah mereka mempunyai tangga (ke langit) untuk mendengarkan (hal-hal yang gaib)? Maka hendaklah orang yang mendengarkan di antara mereka itu datang membawa keterangan yang nyata"},{id:39,text:"\u0623\u064e\u0645\u06e1 \u0644\u064e\u0647\u064f \u0671\u0644\u06e1\u0628\u064e\u0646\u064e\u0670\u062a\u064f \u0648\u064e\u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0628\u064e\u0646\u064f\u0648\u0646\u064e",translation:"Ataukah (pantas) untuk Dia anak-anak perempuan sedangkan untuk kamu anak-anak laki-laki"},{id:40,text:"\u0623\u064e\u0645\u06e1 \u062a\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0647\u064f\u0645\u06e1 \u0623\u064e\u062c\u06e1\u0631\u0657\u0627 \u0641\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0645\u0651\u064e\u063a\u06e1\u0631\u064e\u0645\u0656 \u0645\u0651\u064f\u062b\u06e1\u0642\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Ataukah engkau (Muhammad) meminta imbalan kepada mereka sehingga mereka dibebani dengan hutang"},{id:41,text:"\u0623\u064e\u0645\u06e1 \u0639\u0650\u0646\u062f\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u0628\u064f \u0641\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0643\u06e1\u062a\u064f\u0628\u064f\u0648\u0646\u064e",translation:"Ataukah di sisi mereka mempunyai (pengetahuan) tentang yang gaib lalu mereka menuliskannya"},{id:42,text:"\u0623\u064e\u0645\u06e1 \u064a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0643\u064e\u064a\u06e1\u062f\u0657\u0627\u06d6 \u0641\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064e\u0643\u0650\u064a\u062f\u064f\u0648\u0646\u064e",translation:"Ataukah mereka hendak melakukan tipu daya? Tetapi orang-orang yang kafir itu, justru merekalah yang terkena tipu daya"},{id:43,text:"\u0623\u064e\u0645\u06e1 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0670\u0647\u064c \u063a\u064e\u064a\u06e1\u0631\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0633\u064f\u0628\u06e1\u062d\u064e\u0670\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064f\u0634\u06e1\u0631\u0650\u0643\u064f\u0648\u0646\u064e",translation:"Ataukah mereka mempunyai tuhan selain Allah? Mahasuci Allah dari apa yang mereka persekutukan"},{id:44,text:"\u0648\u064e\u0625\u0650\u0646 \u064a\u064e\u0631\u064e\u0648\u06e1\u0627\u0652 \u0643\u0650\u0633\u06e1\u0641\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0633\u064e\u0627\u0642\u0650\u0637\u0657\u0627 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627\u0652 \u0633\u064e\u062d\u064e\u0627\u0628\u065e \u0645\u0651\u064e\u0631\u06e1\u0643\u064f\u0648\u0645\u065e",translation:"Dan jika mereka melihat gumpalan-gumpalan awan berjatuhan dari langit, mereka berkata, \"Itu adalah awan yang bertumpuk-tumpuk"},{id:45,text:"\u0641\u064e\u0630\u064e\u0631\u06e1\u0647\u064f\u0645\u06e1 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064f\u0644\u064e\u0670\u0642\u064f\u0648\u0627\u0652 \u064a\u064e\u0648\u06e1\u0645\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0641\u0650\u064a\u0647\u0650 \u064a\u064f\u0635\u06e1\u0639\u064e\u0642\u064f\u0648\u0646\u064e",translation:"Maka biarkanlah mereka hingga mereka menemui hari (yang dijanjikan kepada) mereka, pada hari itu mereka dibinasakan"},{id:46,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u0644\u064e\u0627 \u064a\u064f\u063a\u06e1\u0646\u0650\u064a \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0643\u064e\u064a\u06e1\u062f\u064f\u0647\u064f\u0645\u06e1 \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u06e1 \u064a\u064f\u0646\u0635\u064e\u0631\u064f\u0648\u0646\u064e",translation:"(yaitu) pada hari (ketika) tipu daya mereka tidak berguna sedikit pun bagi mereka dan mereka tidak akan diberi pertolongan"},{id:47,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u0657\u0627 \u062f\u064f\u0648\u0646\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Dan sesungguhnya bagi orang-orang yang zalim masih ada azab selain itu. Tetapi kebanyakan mereka tidak mengetahui"},{id:48,text:"\u0648\u064e\u0671\u0635\u06e1\u0628\u0650\u0631\u06e1 \u0644\u0650\u062d\u064f\u0643\u06e1\u0645\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0628\u0650\u0623\u064e\u0639\u06e1\u064a\u064f\u0646\u0650\u0646\u064e\u0627\u06d6 \u0648\u064e\u0633\u064e\u0628\u0651\u0650\u062d\u06e1 \u0628\u0650\u062d\u064e\u0645\u06e1\u062f\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u062d\u0650\u064a\u0646\u064e \u062a\u064e\u0642\u064f\u0648\u0645\u064f",translation:"Dan bersabarlah (Muhammad) menunggu ketetapan Tuhanmu, karena sesungguhnya engkau berada dalam pengawasan Kami, dan bertasbihlah dengan memuji Tuhanmu ketika engkau bangun"},{id:49,text:"\u0648\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u0650 \u0641\u064e\u0633\u064e\u0628\u0651\u0650\u062d\u06e1\u0647\u064f \u0648\u064e\u0625\u0650\u062f\u06e1\u0628\u064e\u0670\u0631\u064e \u0671\u0644\u0646\u0651\u064f\u062c\u064f\u0648\u0645\u0650",translation:"dan pada sebagian malam bertasbihlah kepada-Nya dan (juga) pada waktu terbenamnya bintang-bintang (pada waktu fajar)"}]},{id:53,name:"\u0627\u0644\u0646\u062c\u0645",transliteration:"An-Najm",translation:"Bintang",type:"meccan",total_verses:62,verses:[{id:1,text:"\u0648\u064e\u0671\u0644\u0646\u0651\u064e\u062c\u06e1\u0645\u0650 \u0625\u0650\u0630\u064e\u0627 \u0647\u064e\u0648\u064e\u0649\u0670",translation:"Demi bintang ketika terbenam"},{id:2,text:"\u0645\u064e\u0627 \u0636\u064e\u0644\u0651\u064e \u0635\u064e\u0627\u062d\u0650\u0628\u064f\u0643\u064f\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627 \u063a\u064e\u0648\u064e\u0649\u0670",translation:"kawanmu (Muhammad) tidak sesat dan tidak (pula) keliru"},{id:3,text:"\u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0646\u0637\u0650\u0642\u064f \u0639\u064e\u0646\u0650 \u0671\u0644\u06e1\u0647\u064e\u0648\u064e\u0649\u0670\u0653",translation:"dan tidaklah yang diucapkannya itu (Alquran) menurut keinginannya"},{id:4,text:"\u0625\u0650\u0646\u06e1 \u0647\u064f\u0648\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0648\u064e\u062d\u06e1\u064a\u065e \u064a\u064f\u0648\u062d\u064e\u0649\u0670",translation:"Tidak lain (Alquran itu) adalah wahyu yang diwahyukan (kepadanya)"},{id:5,text:"\u0639\u064e\u0644\u0651\u064e\u0645\u064e\u0647\u064f\u06e5 \u0634\u064e\u062f\u0650\u064a\u062f\u064f \u0671\u0644\u06e1\u0642\u064f\u0648\u064e\u0649\u0670",translation:"yang diajarkan kepadanya oleh (Jibril) yang sangat kuat"},{id:6,text:"\u0630\u064f\u0648 \u0645\u0650\u0631\u0651\u064e\u0629\u0656 \u0641\u064e\u0671\u0633\u06e1\u062a\u064e\u0648\u064e\u0649\u0670",translation:"yang mempunyai keteguhan; maka (Jibril itu) menampakkan diri dengan rupa yang asli (rupa yang bagus dan perkasa)"},{id:7,text:"\u0648\u064e\u0647\u064f\u0648\u064e \u0628\u0650\u0671\u0644\u06e1\u0623\u064f\u0641\u064f\u0642\u0650 \u0671\u0644\u06e1\u0623\u064e\u0639\u06e1\u0644\u064e\u0649\u0670",translation:"Sedang dia berada di ufuk yang tinggi"},{id:8,text:"\u062b\u064f\u0645\u0651\u064e \u062f\u064e\u0646\u064e\u0627 \u0641\u064e\u062a\u064e\u062f\u064e\u0644\u0651\u064e\u0649\u0670",translation:"Kemudian dia mendekat (pada Muhammad), lalu bertambah dekat"},{id:9,text:"\u0641\u064e\u0643\u064e\u0627\u0646\u064e \u0642\u064e\u0627\u0628\u064e \u0642\u064e\u0648\u06e1\u0633\u064e\u064a\u06e1\u0646\u0650 \u0623\u064e\u0648\u06e1 \u0623\u064e\u062f\u06e1\u0646\u064e\u0649\u0670",translation:"sehingga jaraknya (sekitar) dua busur panah atau lebih dekat (lagi)"},{id:10,text:"\u0641\u064e\u0623\u064e\u0648\u06e1\u062d\u064e\u0649\u0670\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u0639\u064e\u0628\u06e1\u062f\u0650\u0647\u0650\u06e6 \u0645\u064e\u0627\u0653 \u0623\u064e\u0648\u06e1\u062d\u064e\u0649\u0670",translation:"Lalu disampaikannya wahyu kepada hamba-Nya (Muhammad) apa yang telah diwahyukan Allah"},{id:11,text:"\u0645\u064e\u0627 \u0643\u064e\u0630\u064e\u0628\u064e \u0671\u0644\u06e1\u0641\u064f\u0624\u064e\u0627\u062f\u064f \u0645\u064e\u0627 \u0631\u064e\u0623\u064e\u0649\u0670\u0653",translation:"Hatinya tidak mendustakan apa yang telah dilihatnya"},{id:12,text:"\u0623\u064e\u0641\u064e\u062a\u064f\u0645\u064e\u0670\u0631\u064f\u0648\u0646\u064e\u0647\u064f\u06e5 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u064a\u064e\u0631\u064e\u0649\u0670",translation:"Maka apakah kamu (musyrikin Mekkah) hendak membantahnya tentang apa yang dilihatnya itu"},{id:13,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0631\u064e\u0621\u064e\u0627\u0647\u064f \u0646\u064e\u0632\u06e1\u0644\u064e\u0629\u064b \u0623\u064f\u062e\u06e1\u0631\u064e\u0649\u0670",translation:"Dan sungguh, dia (Muhammad) telah melihatnya (dalam rupanya yang asli) pada waktu yang lain"},{id:14,text:"\u0639\u0650\u0646\u062f\u064e \u0633\u0650\u062f\u06e1\u0631\u064e\u0629\u0650 \u0671\u0644\u06e1\u0645\u064f\u0646\u062a\u064e\u0647\u064e\u0649\u0670",translation:"(yaitu) di Sidratilmuntah\u0101"},{id:15,text:"\u0639\u0650\u0646\u062f\u064e\u0647\u064e\u0627 \u062c\u064e\u0646\u0651\u064e\u0629\u064f \u0671\u0644\u06e1\u0645\u064e\u0623\u06e1\u0648\u064e\u0649\u0670\u0653",translation:"di dekatnya ada surga tempat tinggal"},{id:16,text:"\u0625\u0650\u0630\u06e1 \u064a\u064e\u063a\u06e1\u0634\u064e\u0649 \u0671\u0644\u0633\u0651\u0650\u062f\u06e1\u0631\u064e\u0629\u064e \u0645\u064e\u0627 \u064a\u064e\u063a\u06e1\u0634\u064e\u0649\u0670",translation:"(Muhammad melihat Jibril) ketika Sidratilmuntah\u0101 diliputi oleh sesuatu yang meliputinya"},{id:17,text:"\u0645\u064e\u0627 \u0632\u064e\u0627\u063a\u064e \u0671\u0644\u06e1\u0628\u064e\u0635\u064e\u0631\u064f \u0648\u064e\u0645\u064e\u0627 \u0637\u064e\u063a\u064e\u0649\u0670",translation:"penglihatannya (Muhammad) tidak menyimpang dari yang dilihatnya itu dan tidak (pula) melampauinya"},{id:18,text:"\u0644\u064e\u0642\u064e\u062f\u06e1 \u0631\u064e\u0623\u064e\u0649\u0670 \u0645\u0650\u0646\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u0671\u0644\u06e1\u0643\u064f\u0628\u06e1\u0631\u064e\u0649\u0670\u0653",translation:"Sungguh, dia telah melihat sebagian tanda-tanda (kebesaran) Tuhannya yang paling besar"},{id:19,text:"\u0623\u064e\u0641\u064e\u0631\u064e\u0621\u064e\u064a\u06e1\u062a\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0640\u0670\u062a\u064e \u0648\u064e\u0671\u0644\u06e1\u0639\u064f\u0632\u0651\u064e\u0649\u0670",translation:"Maka apakah patut kamu (orang-orang musyrik) menganggap (berhala) Al-L\u0101ta dan Al-'Uzz\u0101"},{id:20,text:"\u0648\u064e\u0645\u064e\u0646\u064e\u0648\u0670\u0629\u064e \u0671\u0644\u062b\u0651\u064e\u0627\u0644\u0650\u062b\u064e\u0629\u064e \u0671\u0644\u06e1\u0623\u064f\u062e\u06e1\u0631\u064e\u0649\u0670\u0653",translation:"dan Man\u0101t, yang ketiga yang paling kemudian (sebagai anak perempuan Allah)"},{id:21,text:"\u0623\u064e\u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0630\u0651\u064e\u0643\u064e\u0631\u064f \u0648\u064e\u0644\u064e\u0647\u064f \u0671\u0644\u06e1\u0623\u064f\u0646\u062b\u064e\u0649\u0670",translation:"Apakah (pantas) untuk kamu yang laki-laki dan untuk-Nya yang perempuan"},{id:22,text:"\u062a\u0650\u0644\u06e1\u0643\u064e \u0625\u0650\u0630\u0657\u0627 \u0642\u0650\u0633\u06e1\u0645\u064e\u0629\u065e \u0636\u0650\u064a\u0632\u064e\u0649\u0670\u0653",translation:"Yang demikian itu tentulah suatu pembagian yang timpang"},{id:23,text:"\u0625\u0650\u0646\u06e1 \u0647\u0650\u064a\u064e \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0633\u06e1\u0645\u064e\u0627\u0653\u0621\u065e \u0633\u064e\u0645\u0651\u064e\u064a\u06e1\u062a\u064f\u0645\u064f\u0648\u0647\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0648\u064e\u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0624\u064f\u0643\u064f\u0645 \u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0647\u064e\u0627 \u0645\u0650\u0646 \u0633\u064f\u0644\u06e1\u0637\u064e\u0670\u0646\u064d\u06da \u0625\u0650\u0646 \u064a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0638\u0651\u064e\u0646\u0651\u064e \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0647\u06e1\u0648\u064e\u0649 \u0671\u0644\u06e1\u0623\u064e\u0646\u0641\u064f\u0633\u064f\u06d6 \u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u064f \u0671\u0644\u06e1\u0647\u064f\u062f\u064e\u0649\u0670\u0653",translation:"Itu tidak lain hanyalah nama-nama yang kamu dan nenek moyangmu mengada-adakannya; Allah tidak menurunkan suatu keterangan apa pun untuk (menyembah)nya. Mereka hanya mengikuti dugaan, dan apa yang diingini oleh keinginannya. Padahal sungguh, telah datang petunjuk dari Tuhan mereka"},{id:24,text:"\u0623\u064e\u0645\u06e1 \u0644\u0650\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u0650 \u0645\u064e\u0627 \u062a\u064e\u0645\u064e\u0646\u0651\u064e\u0649\u0670",translation:"Atau apakah manusia akan mendapat segala yang dicita-citakannya"},{id:25,text:"\u0641\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u064f \u0648\u064e\u0671\u0644\u06e1\u0623\u064f\u0648\u0644\u064e\u0649\u0670",translation:"(Tidak!) Maka milik Allah lah kehidupan akhirat dan kehidupan dunia"},{id:26,text:"\u06de\u0648\u064e\u0643\u064e\u0645 \u0645\u0651\u0650\u0646 \u0645\u0651\u064e\u0644\u064e\u0643\u0656 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0644\u064e\u0627 \u062a\u064f\u063a\u06e1\u0646\u0650\u064a \u0634\u064e\u0641\u064e\u0670\u0639\u064e\u062a\u064f\u0647\u064f\u0645\u06e1 \u0634\u064e\u064a\u06e1\u0640\u0654\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0623\u064e\u0646 \u064a\u064e\u0623\u06e1\u0630\u064e\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0648\u064e\u064a\u064e\u0631\u06e1\u0636\u064e\u0649\u0670\u0653",translation:"Dan betapa banyak malaikat di langit, syafaat (pertolongan) mereka sedikit pun tidak berguna kecuali apabila Allah telah mengizinkan (dan hanya) bagi siapa yang Dia kehendaki dan Dia ridai"},{id:27,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0644\u064e\u064a\u064f\u0633\u064e\u0645\u0651\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u064e \u062a\u064e\u0633\u06e1\u0645\u0650\u064a\u064e\u0629\u064e \u0671\u0644\u06e1\u0623\u064f\u0646\u062b\u064e\u0649\u0670",translation:"Sesungguhnya orang-orang yang tidak beriman kepada kehidupan akhirat, sungguh mereka menamakan para malaikat dengan nama perempuan"},{id:28,text:"\u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6 \u0645\u0650\u0646\u06e1 \u0639\u0650\u0644\u06e1\u0645\u064d\u06d6 \u0625\u0650\u0646 \u064a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0638\u0651\u064e\u0646\u0651\u064e\u06d6 \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0638\u0651\u064e\u0646\u0651\u064e \u0644\u064e\u0627 \u064a\u064f\u063a\u06e1\u0646\u0650\u064a \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627",translation:"Dan mereka tidak mempunyai ilmu tentang itu. Mereka tidak lain hanyalah mengikuti dugaan, dan sesungguhnya dugaan itu tidak berfaedah sedikit pun terhadap kebenaran"},{id:29,text:"\u0641\u064e\u0623\u064e\u0639\u06e1\u0631\u0650\u0636\u06e1 \u0639\u064e\u0646 \u0645\u0651\u064e\u0646 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649\u0670 \u0639\u064e\u0646 \u0630\u0650\u0643\u06e1\u0631\u0650\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064f\u0631\u0650\u062f\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u064e \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627",translation:"Maka tinggalkanlah (Muhammad) orang yang berpaling dari peringatan Kami, dan dia hanya mengingini kehidupan dunia"},{id:30,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u064e\u0628\u06e1\u0644\u064e\u063a\u064f\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0639\u0650\u0644\u06e1\u0645\u0650\u06da \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0647\u064f\u0648\u064e \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0646 \u0636\u064e\u0644\u0651\u064e \u0639\u064e\u0646 \u0633\u064e\u0628\u0650\u064a\u0644\u0650\u0647\u0650\u06e6 \u0648\u064e\u0647\u064f\u0648\u064e \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0646\u0650 \u0671\u0647\u06e1\u062a\u064e\u062f\u064e\u0649\u0670",translation:"Itulah kadar ilmu mereka. Sungguh, Tuhanmu, Dia lebih mengetahui siapa yang tersesat dari jalan-Nya dan Dia pula yang lebih mengetahui siapa yang mendapat petunjuk"},{id:31,text:"\u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0644\u0650\u064a\u064e\u062c\u06e1\u0632\u0650\u064a\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u0633\u064e\u0640\u0670\u0653\u0640\u0654\u064f\u0648\u0627\u0652 \u0628\u0650\u0645\u064e\u0627 \u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0648\u064e\u064a\u064e\u062c\u06e1\u0632\u0650\u064a\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u06e1\u062d\u064f\u0633\u06e1\u0646\u064e\u0649",translation:"Dan milik Allah lah apa yang ada di langit dan apa yang ada di bumi. (Dengan demikian) Dia akan memberi balasan kepada orang-orang yang berbuat jahat sesuai dengan apa yang telah mereka kerjakan dan Dia akan memberi balasan kepada orang-orang yang berbuat baik dengan pahala yang lebih baik (surga)"},{id:32,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062c\u06e1\u062a\u064e\u0646\u0650\u0628\u064f\u0648\u0646\u064e \u0643\u064e\u0628\u064e\u0640\u0670\u0653\u0626\u0650\u0631\u064e \u0671\u0644\u06e1\u0625\u0650\u062b\u06e1\u0645\u0650 \u0648\u064e\u0671\u0644\u06e1\u0641\u064e\u0648\u064e\u0670\u062d\u0650\u0634\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0645\u064e\u0645\u064e\u06da \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0648\u064e\u0670\u0633\u0650\u0639\u064f \u0671\u0644\u06e1\u0645\u064e\u063a\u06e1\u0641\u0650\u0631\u064e\u0629\u0650\u06da \u0647\u064f\u0648\u064e \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0628\u0650\u0643\u064f\u0645\u06e1 \u0625\u0650\u0630\u06e1 \u0623\u064e\u0646\u0634\u064e\u0623\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0625\u0650\u0630\u06e1 \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0623\u064e\u062c\u0650\u0646\u0651\u064e\u0629\u065e \u0641\u0650\u064a \u0628\u064f\u0637\u064f\u0648\u0646\u0650 \u0623\u064f\u0645\u0651\u064e\u0647\u064e\u0670\u062a\u0650\u0643\u064f\u0645\u06e1\u06d6 \u0641\u064e\u0644\u064e\u0627 \u062a\u064f\u0632\u064e\u0643\u0651\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0643\u064f\u0645\u06e1\u06d6 \u0647\u064f\u0648\u064e \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0646\u0650 \u0671\u062a\u0651\u064e\u0642\u064e\u0649\u0670\u0653",translation:"(Yaitu) mereka yang menjauhi dosa-dosa besar dan perbuatan keji, kecuali kesalahan-kesalahan kecil. Sungguh, Tuhanmu Mahaluas ampunan-Nya. Dia mengetahui tentang kamu, sejak Dia menjadikan kamu dari tanah lalu ketika kamu masih janin dalam perut ibumu. Maka janganlah kamu menganggap dirimu suci. Dia mengetahui tentang orang yang bertakwa"},{id:33,text:"\u0623\u064e\u0641\u064e\u0631\u064e\u0621\u064e\u064a\u06e1\u062a\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649\u0670",translation:"Maka tidakkah engkau melihat orang yang berpaling (dari Alquran)"},{id:34,text:"\u0648\u064e\u0623\u064e\u0639\u06e1\u0637\u064e\u0649\u0670 \u0642\u064e\u0644\u0650\u064a\u0644\u0657\u0627 \u0648\u064e\u0623\u064e\u0643\u06e1\u062f\u064e\u0649\u0670\u0653",translation:"dan dia memberikan sedikit (dari apa yang dijanjikan) lalu menahan sisanya"},{id:35,text:"\u0623\u064e\u0639\u0650\u0646\u062f\u064e\u0647\u064f\u06e5 \u0639\u0650\u0644\u06e1\u0645\u064f \u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u0628\u0650 \u0641\u064e\u0647\u064f\u0648\u064e \u064a\u064e\u0631\u064e\u0649\u0670\u0653",translation:"Apakah dia mempunyai ilmu tentang yang gaib sehingga dia dapat melihat(nya)"},{id:36,text:"\u0623\u064e\u0645\u06e1 \u0644\u064e\u0645\u06e1 \u064a\u064f\u0646\u064e\u0628\u0651\u064e\u0623\u06e1 \u0628\u0650\u0645\u064e\u0627 \u0641\u0650\u064a \u0635\u064f\u062d\u064f\u0641\u0650 \u0645\u064f\u0648\u0633\u064e\u0649\u0670",translation:"Ataukah belum diberitakan (kepadanya) apa yang ada dalam lembaran-lembaran (Kitab Suci yang diturunkan kepada) Musa"},{id:37,text:"\u0648\u064e\u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0648\u064e\u0641\u0651\u064e\u0649\u0670\u0653",translation:"Dan (lembaran-lembaran) Ibrahim yang selalu menyempurnakan janji"},{id:38,text:"\u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064e\u0632\u0650\u0631\u064f \u0648\u064e\u0627\u0632\u0650\u0631\u064e\u0629\u065e \u0648\u0650\u0632\u06e1\u0631\u064e \u0623\u064f\u062e\u06e1\u0631\u064e\u0649\u0670",translation:"(yaitu) bahwa seseorang yang berdosa tidak akan memikul dosa orang lain"},{id:39,text:"\u0648\u064e\u0623\u064e\u0646 \u0644\u0651\u064e\u064a\u06e1\u0633\u064e \u0644\u0650\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0633\u064e\u0639\u064e\u0649\u0670",translation:"dan bahwa manusia hanya memperoleh apa yang telah diusahakannya"},{id:40,text:"\u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0633\u064e\u0639\u06e1\u064a\u064e\u0647\u064f\u06e5 \u0633\u064e\u0648\u06e1\u0641\u064e \u064a\u064f\u0631\u064e\u0649\u0670",translation:"dan sesungguhnya usahanya itu kelak akan diperlihatkan (kepadanya)"},{id:41,text:"\u062b\u064f\u0645\u0651\u064e \u064a\u064f\u062c\u06e1\u0632\u064e\u0649\u0670\u0647\u064f \u0671\u0644\u06e1\u062c\u064e\u0632\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u06e1\u0623\u064e\u0648\u06e1\u0641\u064e\u0649\u0670",translation:"kemudian akan diberi balasan kepadanya dengan balasan yang paling sempurna"},{id:42,text:"\u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0671\u0644\u06e1\u0645\u064f\u0646\u062a\u064e\u0647\u064e\u0649\u0670",translation:"dan sesungguhnya kepada Tuhanmulah kesudahannya (segala sesuatu)"},{id:43,text:"\u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u06e5 \u0647\u064f\u0648\u064e \u0623\u064e\u0636\u06e1\u062d\u064e\u0643\u064e \u0648\u064e\u0623\u064e\u0628\u06e1\u0643\u064e\u0649\u0670",translation:"dan sesungguhnya Dialah yang menjadikan orang tertawa dan menangis"},{id:44,text:"\u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u06e5 \u0647\u064f\u0648\u064e \u0623\u064e\u0645\u064e\u0627\u062a\u064e \u0648\u064e\u0623\u064e\u062d\u06e1\u064a\u064e\u0627",translation:"dan sesungguhnya Dialah yang mematikan dan menghidupkan"},{id:45,text:"\u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u06e5 \u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u0632\u0651\u064e\u0648\u06e1\u062c\u064e\u064a\u06e1\u0646\u0650 \u0671\u0644\u0630\u0651\u064e\u0643\u064e\u0631\u064e \u0648\u064e\u0671\u0644\u06e1\u0623\u064f\u0646\u062b\u064e\u0649\u0670",translation:"dan sesungguhnya Dialah yang menciptakan pasangan laki-laki dan perempuan"},{id:46,text:"\u0645\u0650\u0646 \u0646\u0651\u064f\u0637\u06e1\u0641\u064e\u0629\u064d \u0625\u0650\u0630\u064e\u0627 \u062a\u064f\u0645\u06e1\u0646\u064e\u0649\u0670",translation:"dari mani, apabila dipancarkan"},{id:47,text:"\u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0671\u0644\u0646\u0651\u064e\u0634\u06e1\u0623\u064e\u0629\u064e \u0671\u0644\u06e1\u0623\u064f\u062e\u06e1\u0631\u064e\u0649\u0670",translation:"dan sesungguhnya Dialah yang menetapkan penciptaan yang lain (kebangkitan setelah mati)"},{id:48,text:"\u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u06e5 \u0647\u064f\u0648\u064e \u0623\u064e\u063a\u06e1\u0646\u064e\u0649\u0670 \u0648\u064e\u0623\u064e\u0642\u06e1\u0646\u064e\u0649\u0670",translation:"dan sesungguhnya Dialah yang memberikan kekayaan dan kecukupan"},{id:49,text:"\u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u06e5 \u0647\u064f\u0648\u064e \u0631\u064e\u0628\u0651\u064f \u0671\u0644\u0634\u0651\u0650\u0639\u06e1\u0631\u064e\u0649\u0670",translation:"dan sesungguhnya Dialah Tuhan (yang memiliki) bintang Syi'r\u0101"},{id:50,text:"\u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u0647\u06e1\u0644\u064e\u0643\u064e \u0639\u064e\u0627\u062f\u064b\u0627 \u0671\u0644\u06e1\u0623\u064f\u0648\u0644\u064e\u0649\u0670",translation:"dan sesungguhnya Dialah yang telah membinasakan kaum '\u0100d dahulu kala"},{id:51,text:"\u0648\u064e\u062b\u064e\u0645\u064f\u0648\u062f\u064e\u0627\u0652 \u0641\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0628\u06e1\u0642\u064e\u0649\u0670",translation:"dan kaum Samud, tidak seorang pun yang ditinggalkan-Nya (hidup)"},{id:52,text:"\u0648\u064e\u0642\u064e\u0648\u06e1\u0645\u064e \u0646\u064f\u0648\u062d\u0656 \u0645\u0651\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f\u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0647\u064f\u0645\u06e1 \u0623\u064e\u0638\u06e1\u0644\u064e\u0645\u064e \u0648\u064e\u0623\u064e\u0637\u06e1\u063a\u064e\u0649\u0670",translation:"dan (juga) kaum Nuh sebelum itu. Sungguh, mereka adalah orang-orang yang paling zalim dan paling durhaka"},{id:53,text:"\u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u062a\u064e\u0641\u0650\u0643\u064e\u0629\u064e \u0623\u064e\u0647\u06e1\u0648\u064e\u0649\u0670",translation:"Dan prahara angin telah meruntuhkan (negeri kaum Lu\u1e6d)"},{id:54,text:"\u0641\u064e\u063a\u064e\u0634\u0651\u064e\u0649\u0670\u0647\u064e\u0627 \u0645\u064e\u0627 \u063a\u064e\u0634\u0651\u064e\u0649\u0670",translation:"lalu menimbuni negeri itu (sebagai azab) dengan (puing-puing) yang menimpanya"},{id:55,text:"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0621\u064e\u0627\u0644\u064e\u0627\u0653\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u062a\u064e\u062a\u064e\u0645\u064e\u0627\u0631\u064e\u0649\u0670",translation:"Maka terhadap nikmat Tuhanmu yang manakah yang masih kamu ragukan"},{id:56,text:"\u0647\u064e\u0670\u0630\u064e\u0627 \u0646\u064e\u0630\u0650\u064a\u0631\u065e \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064f\u0630\u064f\u0631\u0650 \u0671\u0644\u06e1\u0623\u064f\u0648\u0644\u064e\u0649\u0670\u0653",translation:"Ini (Muhammad) salah seorang pemberi peringatan di antara para pemberi peringatan yang telah terdahulu"},{id:57,text:"\u0623\u064e\u0632\u0650\u0641\u064e\u062a\u0650 \u0671\u0644\u06e1\u0623\u0653\u0632\u0650\u0641\u064e\u0629\u064f",translation:"Yang dekat (hari Kiamat) telah makin mendekat"},{id:58,text:"\u0644\u064e\u064a\u06e1\u0633\u064e \u0644\u064e\u0647\u064e\u0627 \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u0627\u0634\u0650\u0641\u064e\u0629\u064c",translation:"Tidak ada yang akan dapat mengungkapkan (terjadinya hari itu) selain Allah"},{id:59,text:"\u0623\u064e\u0641\u064e\u0645\u0650\u0646\u06e1 \u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u06e1\u062d\u064e\u062f\u0650\u064a\u062b\u0650 \u062a\u064e\u0639\u06e1\u062c\u064e\u0628\u064f\u0648\u0646\u064e",translation:"Maka apakah kamu merasa heran terhadap pemberitaan ini"},{id:60,text:"\u0648\u064e\u062a\u064e\u0636\u06e1\u062d\u064e\u0643\u064f\u0648\u0646\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0628\u06e1\u0643\u064f\u0648\u0646\u064e",translation:"dan kamu tertawakan dan tidak menangis"},{id:61,text:"\u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0633\u064e\u0670\u0645\u0650\u062f\u064f\u0648\u0646\u064e",translation:"sedang kamu lengah (darinya)"},{id:62,text:"\u0641\u064e\u0671\u0633\u06e1\u062c\u064f\u062f\u064f\u0648\u0627\u0652\u06e4 \u0644\u0650\u0644\u0651\u064e\u0647\u0650\u06e4 \u0648\u064e\u0671\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0627\u0652\u06e9",translation:"Maka bersujudlah kepada Allah dan sembahlah (Dia)"}]},{id:54,name:"\u0627\u0644\u0642\u0645\u0631",transliteration:"Al-Qamar",translation:"Bulan",type:"meccan",total_verses:55,verses:[{id:1,text:"\u0671\u0642\u06e1\u062a\u064e\u0631\u064e\u0628\u064e\u062a\u0650 \u0671\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064f \u0648\u064e\u0671\u0646\u0634\u064e\u0642\u0651\u064e \u0671\u0644\u06e1\u0642\u064e\u0645\u064e\u0631\u064f",translation:"Saat (hari Kiamat) semakin dekat, bulan pun terbelah"},{id:2,text:"\u0648\u064e\u0625\u0650\u0646 \u064a\u064e\u0631\u064e\u0648\u06e1\u0627\u0652 \u0621\u064e\u0627\u064a\u064e\u0629\u0657 \u064a\u064f\u0639\u06e1\u0631\u0650\u0636\u064f\u0648\u0627\u0652 \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627\u0652 \u0633\u0650\u062d\u06e1\u0631\u065e \u0645\u0651\u064f\u0633\u06e1\u062a\u064e\u0645\u0650\u0631\u0651\u065e",translation:"Dan jika mereka (orang-orang musyrikin) melihat suatu tanda (mukjizat), mereka berpaling dan berkata, \"(Ini adalah) sihir yang terus menerus"},{id:3,text:"\u0648\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0648\u064e\u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0647\u06e1\u0648\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u06e1\u06da \u0648\u064e\u0643\u064f\u0644\u0651\u064f \u0623\u064e\u0645\u06e1\u0631\u0656 \u0645\u0651\u064f\u0633\u06e1\u062a\u064e\u0642\u0650\u0631\u0651\u065e",translation:"Dan mereka mendustakan (Muhammad) dan mengikuti nafsu mereka, padahal setiap urusan telah ada ketetapannya"},{id:4,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u0646\u06e2\u0628\u064e\u0627\u0653\u0621\u0650 \u0645\u064e\u0627 \u0641\u0650\u064a\u0647\u0650 \u0645\u064f\u0632\u06e1\u062f\u064e\u062c\u064e\u0631\u064c",translation:"Dan sungguh, telah datang kepada mereka beberapa kisah yang di dalamnya terdapat ancaman (terhadap kekafiran)"},{id:5,text:"\u062d\u0650\u0643\u06e1\u0645\u064e\u0629\u064f\u06e2 \u0628\u064e\u0670\u0644\u0650\u063a\u064e\u0629\u065e\u06d6 \u0641\u064e\u0645\u064e\u0627 \u062a\u064f\u063a\u06e1\u0646\u0650 \u0671\u0644\u0646\u0651\u064f\u0630\u064f\u0631\u064f",translation:"(itulah) suatu hikmah yang sempurna, tetapi peringatan-peringatan itu tidak berguna (bagi mereka)"},{id:6,text:"\u0641\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1\u06d8 \u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064e\u062f\u06e1\u0639\u064f \u0671\u0644\u062f\u0651\u064e\u0627\u0639\u0650 \u0625\u0650\u0644\u064e\u0649\u0670 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0646\u0651\u064f\u0643\u064f\u0631\u064d",translation:"maka berpalinglah engkau (Muhammad) dari mereka pada hari (ketika) penyeru (malaikat) mengajak (mereka) kepada sesuatu yang tidak menyenangkan (hari pembalasan)"},{id:7,text:"\u062e\u064f\u0634\u0651\u064e\u0639\u064b\u0627 \u0623\u064e\u0628\u06e1\u0635\u064e\u0670\u0631\u064f\u0647\u064f\u0645\u06e1 \u064a\u064e\u062e\u06e1\u0631\u064f\u062c\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u062c\u06e1\u062f\u064e\u0627\u062b\u0650 \u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u062c\u064e\u0631\u064e\u0627\u062f\u065e \u0645\u0651\u064f\u0646\u062a\u064e\u0634\u0650\u0631\u065e",translation:"pandangan mereka tertunduk, ketika mereka keluar dari kuburan, seakan-akan mereka belalang yang beterbangan"},{id:8,text:"\u0645\u0651\u064f\u0647\u06e1\u0637\u0650\u0639\u0650\u064a\u0646\u064e \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u062f\u0651\u064e\u0627\u0639\u0650\u06d6 \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u064f\u0648\u0646\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u064a\u064e\u0648\u06e1\u0645\u064c \u0639\u064e\u0633\u0650\u0631\u065e",translation:"dengan patuh mereka segera datang kepada penyeru itu. Orang-orang kafir berkata, \"Ini adalah hari yang sulit"},{id:9,text:"\u06de\u0643\u064e\u0630\u0651\u064e\u0628\u064e\u062a\u06e1 \u0642\u064e\u0628\u06e1\u0644\u064e\u0647\u064f\u0645\u06e1 \u0642\u064e\u0648\u06e1\u0645\u064f \u0646\u064f\u0648\u062d\u0656 \u0641\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0639\u064e\u0628\u06e1\u062f\u064e\u0646\u064e\u0627 \u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0645\u064e\u062c\u06e1\u0646\u064f\u0648\u0646\u065e \u0648\u064e\u0671\u0632\u06e1\u062f\u064f\u062c\u0650\u0631\u064e",translation:"Sebelum mereka, kaum Nuh juga telah mendustakan (rasul), maka mereka mendustakan hamba Kami (Nuh) dan mengatakan, \"Dia orang gila!\" Lalu diusirnya dengan ancaman"},{id:10,text:"\u0641\u064e\u062f\u064e\u0639\u064e\u0627 \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u0646\u0651\u0650\u064a \u0645\u064e\u063a\u06e1\u0644\u064f\u0648\u0628\u065e \u0641\u064e\u0671\u0646\u062a\u064e\u0635\u0650\u0631\u06e1",translation:"Maka dia (Nuh) mengadu kepada Tuhannya, \"Sesungguhnya aku telah dikalahkan, maka tolonglah (aku)"},{id:11,text:"\u0641\u064e\u0641\u064e\u062a\u064e\u062d\u06e1\u0646\u064e\u0627\u0653 \u0623\u064e\u0628\u06e1\u0648\u064e\u0670\u0628\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0628\u0650\u0645\u064e\u0627\u0653\u0621\u0656 \u0645\u0651\u064f\u0646\u06e1\u0647\u064e\u0645\u0650\u0631\u0656",translation:"Lalu Kami bukakan pintu-pintu langit dengan (menurunkan) air yang tercurah"},{id:12,text:"\u0648\u064e\u0641\u064e\u062c\u0651\u064e\u0631\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0639\u064f\u064a\u064f\u0648\u0646\u0657\u0627 \u0641\u064e\u0671\u0644\u06e1\u062a\u064e\u0642\u064e\u0649 \u0671\u0644\u06e1\u0645\u064e\u0627\u0653\u0621\u064f \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0645\u06e1\u0631\u0656 \u0642\u064e\u062f\u06e1 \u0642\u064f\u062f\u0650\u0631\u064e",translation:"dan Kami jadikan bumi menyemburkan mata-mata air maka bertemulah (air-air) itu sehinggga (meluap menimbulkan) keadaaan (bencana) yang telah ditetapkan"},{id:13,text:"\u0648\u064e\u062d\u064e\u0645\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0630\u064e\u0627\u062a\u0650 \u0623\u064e\u0644\u06e1\u0648\u064e\u0670\u062d\u0656 \u0648\u064e\u062f\u064f\u0633\u064f\u0631\u0656",translation:"Dan Kami angkut dia (Nuh) ke atas (kapal) yang terbuat dari papan dan pasak"},{id:14,text:"\u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0628\u0650\u0623\u064e\u0639\u06e1\u064a\u064f\u0646\u0650\u0646\u064e\u0627 \u062c\u064e\u0632\u064e\u0627\u0653\u0621\u0657 \u0644\u0651\u0650\u0645\u064e\u0646 \u0643\u064e\u0627\u0646\u064e \u0643\u064f\u0641\u0650\u0631\u064e",translation:"yang berlayar dengan pemeliharaan (pengawasan) Kami sebagai balasan bagi orang yang telah diingkari (kaumnya)"},{id:15,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f \u062a\u0651\u064e\u0631\u064e\u0643\u06e1\u0646\u064e\u0670\u0647\u064e\u0627\u0653 \u0621\u064e\u0627\u064a\u064e\u0629\u0657 \u0641\u064e\u0647\u064e\u0644\u06e1 \u0645\u0650\u0646 \u0645\u0651\u064f\u062f\u0651\u064e\u0643\u0650\u0631\u0656",translation:"Dan sungguh, kapal itu telah Kami jadikan sebagai tanda (pelajaran). Maka adakah orang yang mau mengambil pelajaran"},{id:16,text:"\u0641\u064e\u0643\u064e\u064a\u06e1\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u0650\u064a \u0648\u064e\u0646\u064f\u0630\u064f\u0631\u0650",translation:"Maka betapa dahsyatnya azab-Ku dan peringatan-Ku"},{id:17,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u064a\u064e\u0633\u0651\u064e\u0631\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u064e \u0644\u0650\u0644\u0630\u0651\u0650\u0643\u06e1\u0631\u0650 \u0641\u064e\u0647\u064e\u0644\u06e1 \u0645\u0650\u0646 \u0645\u0651\u064f\u062f\u0651\u064e\u0643\u0650\u0631\u0656",translation:"Dan sungguh, telah Kami mudahkan Alquran untuk peringatan, maka adakah orang yang mau mengambil pelajaran"},{id:18,text:"\u0643\u064e\u0630\u0651\u064e\u0628\u064e\u062a\u06e1 \u0639\u064e\u0627\u062f\u065e \u0641\u064e\u0643\u064e\u064a\u06e1\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u0650\u064a \u0648\u064e\u0646\u064f\u0630\u064f\u0631\u0650",translation:"Kaum '\u0100d pun telah mendustakan. Maka betapa dahsyatnya azab-Ku dan peringatan-Ku"},{id:19,text:"\u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0631\u0650\u064a\u062d\u0657\u0627 \u0635\u064e\u0631\u06e1\u0635\u064e\u0631\u0657\u0627 \u0641\u0650\u064a \u064a\u064e\u0648\u06e1\u0645\u0650 \u0646\u064e\u062d\u06e1\u0633\u0656 \u0645\u0651\u064f\u0633\u06e1\u062a\u064e\u0645\u0650\u0631\u0651\u0656",translation:"Sesungguhnya Kami telah menghembuskan angin yang sangat kencang kepada mereka pada hari nahas yang terus menerus"},{id:20,text:"\u062a\u064e\u0646\u0632\u0650\u0639\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u0639\u06e1\u062c\u064e\u0627\u0632\u064f \u0646\u064e\u062e\u06e1\u0644\u0656 \u0645\u0651\u064f\u0646\u0642\u064e\u0639\u0650\u0631\u0656",translation:"yang membuat manusia bergelimpangan, mereka bagaikan pohon-pohon kurma yang tumbang dengan akar-akarnya"},{id:21,text:"\u0641\u064e\u0643\u064e\u064a\u06e1\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u0650\u064a \u0648\u064e\u0646\u064f\u0630\u064f\u0631\u0650",translation:"Maka betapa dahsyatnya azab-Ku dan peringatan-Ku"},{id:22,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u064a\u064e\u0633\u0651\u064e\u0631\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u064e \u0644\u0650\u0644\u0630\u0651\u0650\u0643\u06e1\u0631\u0650 \u0641\u064e\u0647\u064e\u0644\u06e1 \u0645\u0650\u0646 \u0645\u0651\u064f\u062f\u0651\u064e\u0643\u0650\u0631\u0656",translation:"Dan sungguh, telah Kami mudahkan Alquran untuk peringatan, maka adakah orang yang mau mengambil pelajaran"},{id:23,text:"\u0643\u064e\u0630\u0651\u064e\u0628\u064e\u062a\u06e1 \u062b\u064e\u0645\u064f\u0648\u062f\u064f \u0628\u0650\u0671\u0644\u0646\u0651\u064f\u0630\u064f\u0631\u0650",translation:"Kaum Samud pun telah mendustakan peringatan itu"},{id:24,text:"\u0641\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0628\u064e\u0634\u064e\u0631\u0657\u0627 \u0645\u0651\u0650\u0646\u0651\u064e\u0627 \u0648\u064e\u0670\u062d\u0650\u062f\u0657\u0627 \u0646\u0651\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0647\u064f\u06e5\u0653 \u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0625\u0650\u0630\u0657\u0627 \u0644\u0651\u064e\u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0670\u0644\u0656 \u0648\u064e\u0633\u064f\u0639\u064f\u0631\u064d",translation:"Maka mereka berkata, \"Bagaimana kita akan mengikuti seorang manusia (biasa) di antara kita? Sungguh, kalau begitu kita benar-benar telah sesat dan gila"},{id:25,text:"\u0623\u064e\u0621\u064f\u0644\u06e1\u0642\u0650\u064a\u064e \u0671\u0644\u0630\u0651\u0650\u0643\u06e1\u0631\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0645\u0650\u0646\u06e2 \u0628\u064e\u064a\u06e1\u0646\u0650\u0646\u064e\u0627 \u0628\u064e\u0644\u06e1 \u0647\u064f\u0648\u064e \u0643\u064e\u0630\u0651\u064e\u0627\u0628\u064c \u0623\u064e\u0634\u0650\u0631\u065e",translation:"Apakah wahyu itu diturunkan kepadanya di antara kita? Pastilah dia (Saleh) seorang yang sangat pendusta (dan) sombong"},{id:26,text:"\u0633\u064e\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u063a\u064e\u062f\u0657\u0627 \u0645\u0651\u064e\u0646\u0650 \u0671\u0644\u06e1\u0643\u064e\u0630\u0651\u064e\u0627\u0628\u064f \u0671\u0644\u06e1\u0623\u064e\u0634\u0650\u0631\u064f",translation:"Kelak mereka akan mengetahui siapa yang sebenarnya sangat pendusta (dan) sombong itu"},{id:27,text:"\u0625\u0650\u0646\u0651\u064e\u0627 \u0645\u064f\u0631\u06e1\u0633\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0646\u0651\u064e\u0627\u0642\u064e\u0629\u0650 \u0641\u0650\u062a\u06e1\u0646\u064e\u0629\u0657 \u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u0641\u064e\u0671\u0631\u06e1\u062a\u064e\u0642\u0650\u0628\u06e1\u0647\u064f\u0645\u06e1 \u0648\u064e\u0671\u0635\u06e1\u0637\u064e\u0628\u0650\u0631\u06e1",translation:"Sesungguhnya Kami akan mengirimkan unta betina sebagai cobaan bagi mereka, maka tunggulah mereka dan bersabarlah (Saleh)"},{id:28,text:"\u0648\u064e\u0646\u064e\u0628\u0651\u0650\u0626\u06e1\u0647\u064f\u0645\u06e1 \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u06e1\u0645\u064e\u0627\u0653\u0621\u064e \u0642\u0650\u0633\u06e1\u0645\u064e\u0629\u064f\u06e2 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1\u06d6 \u0643\u064f\u0644\u0651\u064f \u0634\u0650\u0631\u06e1\u0628\u0656 \u0645\u0651\u064f\u062d\u06e1\u062a\u064e\u0636\u064e\u0631\u065e",translation:"Dan beritahukanlah kepada mereka bahwa air itu dibagi di antara mereka (dengan unta betina itu); setiap orang berhak mendapat giliran minum"},{id:29,text:"\u0641\u064e\u0646\u064e\u0627\u062f\u064e\u0648\u06e1\u0627\u0652 \u0635\u064e\u0627\u062d\u0650\u0628\u064e\u0647\u064f\u0645\u06e1 \u0641\u064e\u062a\u064e\u0639\u064e\u0627\u0637\u064e\u0649\u0670 \u0641\u064e\u0639\u064e\u0642\u064e\u0631\u064e",translation:"Maka mereka memanggil kawannya, lalu dia menangkap (unta itu) dan memotongnya"},{id:30,text:"\u0641\u064e\u0643\u064e\u064a\u06e1\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u0650\u064a \u0648\u064e\u0646\u064f\u0630\u064f\u0631\u0650",translation:"Maka betapa dahsyatnya azab-Ku dan peringatan-Ku"},{id:31,text:"\u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0635\u064e\u064a\u06e1\u062d\u064e\u0629\u0657 \u0648\u064e\u0670\u062d\u0650\u062f\u064e\u0629\u0657 \u0641\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0643\u064e\u0647\u064e\u0634\u0650\u064a\u0645\u0650 \u0671\u0644\u06e1\u0645\u064f\u062d\u06e1\u062a\u064e\u0638\u0650\u0631\u0650",translation:"Kami kirimkan atas mereka satu suara yang keras mengguntur, maka jadilah mereka seperti batang-batang kering yang lapuk"},{id:32,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u064a\u064e\u0633\u0651\u064e\u0631\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u064e \u0644\u0650\u0644\u0630\u0651\u0650\u0643\u06e1\u0631\u0650 \u0641\u064e\u0647\u064e\u0644\u06e1 \u0645\u0650\u0646 \u0645\u0651\u064f\u062f\u0651\u064e\u0643\u0650\u0631\u0656",translation:"Dan sungguh, telah Kami mudahkan Alquran untuk peringatan, maka adakah orang yang mau mengambil pelajaran"},{id:33,text:"\u0643\u064e\u0630\u0651\u064e\u0628\u064e\u062a\u06e1 \u0642\u064e\u0648\u06e1\u0645\u064f \u0644\u064f\u0648\u0637\u0650\u06ed \u0628\u0650\u0671\u0644\u0646\u0651\u064f\u0630\u064f\u0631\u0650",translation:"Kaum Lu\u1e6d pun telah mendustakan peringatan itu"},{id:34,text:"\u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u062d\u064e\u0627\u0635\u0650\u0628\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0621\u064e\u0627\u0644\u064e \u0644\u064f\u0648\u0637\u0656\u06d6 \u0646\u0651\u064e\u062c\u0651\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f\u0645 \u0628\u0650\u0633\u064e\u062d\u064e\u0631\u0656",translation:"Sesungguhnya Kami kirimkan kepada mereka badai yang membawa batu-batu (yang menimpa mereka), kecuali keluarga Lu\u1e6d. Kami selamatkan mereka sebelum fajar menyingsing"},{id:35,text:"\u0646\u0651\u0650\u0639\u06e1\u0645\u064e\u0629\u0657 \u0645\u0651\u0650\u0646\u06e1 \u0639\u0650\u0646\u062f\u0650\u0646\u064e\u0627\u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u062c\u06e1\u0632\u0650\u064a \u0645\u064e\u0646 \u0634\u064e\u0643\u064e\u0631\u064e",translation:"sebagai nikmat dari Kami. Demikianlah Kami memberi balasan kepada orang-orang yang bersyukur"},{id:36,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u0646\u0630\u064e\u0631\u064e\u0647\u064f\u0645 \u0628\u064e\u0637\u06e1\u0634\u064e\u062a\u064e\u0646\u064e\u0627 \u0641\u064e\u062a\u064e\u0645\u064e\u0627\u0631\u064e\u0648\u06e1\u0627\u0652 \u0628\u0650\u0671\u0644\u0646\u0651\u064f\u0630\u064f\u0631\u0650",translation:"Dan sungguh, dia (Lu\u1e6d) telah memperingatkan mereka akan hukuman Kami, tetapi mereka mendustakan peringatan-Ku"},{id:37,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0631\u064e\u0670\u0648\u064e\u062f\u064f\u0648\u0647\u064f \u0639\u064e\u0646 \u0636\u064e\u064a\u06e1\u0641\u0650\u0647\u0650\u06e6 \u0641\u064e\u0637\u064e\u0645\u064e\u0633\u06e1\u0646\u064e\u0627\u0653 \u0623\u064e\u0639\u06e1\u064a\u064f\u0646\u064e\u0647\u064f\u0645\u06e1 \u0641\u064e\u0630\u064f\u0648\u0642\u064f\u0648\u0627\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u0650\u064a \u0648\u064e\u0646\u064f\u0630\u064f\u0631\u0650",translation:"Dan sungguh, mereka telah membujuknya (agar menyerahkan) tamunya (kepada mereka), lalu Kami butakan mata mereka, maka rasakanlah azab-Ku dan peringatan-Ku"},{id:38,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0635\u064e\u0628\u0651\u064e\u062d\u064e\u0647\u064f\u0645 \u0628\u064f\u0643\u06e1\u0631\u064e\u0629\u064b \u0639\u064e\u0630\u064e\u0627\u0628\u065e \u0645\u0651\u064f\u0633\u06e1\u062a\u064e\u0642\u0650\u0631\u0651\u065e",translation:"Dan sungguh, pada esok harinya mereka benar-benar ditimpa azab yang tetap"},{id:39,text:"\u0641\u064e\u0630\u064f\u0648\u0642\u064f\u0648\u0627\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u0650\u064a \u0648\u064e\u0646\u064f\u0630\u064f\u0631\u0650",translation:"Maka rasakanlah azab-Ku dan peringatan-Ku"},{id:40,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u064a\u064e\u0633\u0651\u064e\u0631\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u064e \u0644\u0650\u0644\u0630\u0651\u0650\u0643\u06e1\u0631\u0650 \u0641\u064e\u0647\u064e\u0644\u06e1 \u0645\u0650\u0646 \u0645\u0651\u064f\u062f\u0651\u064e\u0643\u0650\u0631\u0656",translation:"Dan sungguh, telah Kami mudahkan Alquran untuk peringatan, maka adakah orang yang mau mengambil pelajaran"},{id:41,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e \u0621\u064e\u0627\u0644\u064e \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0671\u0644\u0646\u0651\u064f\u0630\u064f\u0631\u064f",translation:"Dan sungguh, peringatan telah datang kepada keluarga Fir'aun"},{id:42,text:"\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0643\u064f\u0644\u0651\u0650\u0647\u064e\u0627 \u0641\u064e\u0623\u064e\u062e\u064e\u0630\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0623\u064e\u062e\u06e1\u0630\u064e \u0639\u064e\u0632\u0650\u064a\u0632\u0656 \u0645\u0651\u064f\u0642\u06e1\u062a\u064e\u062f\u0650\u0631\u064d",translation:"Mereka mendustakan mukjizat-mukjizat Kami semuanya, maka Kami azab mereka dengan azab dari \u017bat Yang Mahaperkasa, Mahakuasa"},{id:43,text:"\u0623\u064e\u0643\u064f\u0641\u0651\u064e\u0627\u0631\u064f\u0643\u064f\u0645\u06e1 \u062e\u064e\u064a\u06e1\u0631\u065e \u0645\u0651\u0650\u0646\u06e1 \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064f\u0645\u06e1 \u0623\u064e\u0645\u06e1 \u0644\u064e\u0643\u064f\u0645 \u0628\u064e\u0631\u064e\u0627\u0653\u0621\u064e\u0629\u065e \u0641\u0650\u064a \u0671\u0644\u0632\u0651\u064f\u0628\u064f\u0631\u0650",translation:"Apakah orang-orang kafir di lingkunganmu (kaum musyrikin) lebih baik dari mereka, ataukah kamu telah mempunyai jaminan kebebasan (dari azab) dalam kitab-kitab terdahulu"},{id:44,text:"\u0623\u064e\u0645\u06e1 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0646\u064e\u062d\u06e1\u0646\u064f \u062c\u064e\u0645\u0650\u064a\u0639\u065e \u0645\u0651\u064f\u0646\u062a\u064e\u0635\u0650\u0631\u065e",translation:"Atau mereka mengatakan, \"Kami ini golongan yang bersatu yang pasti menang"},{id:45,text:"\u0633\u064e\u064a\u064f\u0647\u06e1\u0632\u064e\u0645\u064f \u0671\u0644\u06e1\u062c\u064e\u0645\u06e1\u0639\u064f \u0648\u064e\u064a\u064f\u0648\u064e\u0644\u0651\u064f\u0648\u0646\u064e \u0671\u0644\u062f\u0651\u064f\u0628\u064f\u0631\u064e",translation:"Golongan itu pasti akan dikalahkan dan mereka akan mundur ke belakang"},{id:46,text:"\u0628\u064e\u0644\u0650 \u0671\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064f \u0645\u064e\u0648\u06e1\u0639\u0650\u062f\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0671\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064f \u0623\u064e\u062f\u06e1\u0647\u064e\u0649\u0670 \u0648\u064e\u0623\u064e\u0645\u064e\u0631\u0651\u064f",translation:"Bahkan hari Kiamat itulah hari yang dijanjikan kepada mereka dan hari Kiamat itu lebih dahsyat dan lebih pahit"},{id:47,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0645\u064f\u062c\u06e1\u0631\u0650\u0645\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0670\u0644\u0656 \u0648\u064e\u0633\u064f\u0639\u064f\u0631\u0656",translation:"Sungguh, orang-orang yang berdosa berada dalam kesesatan (di dunia) dan akan berada dalam neraka (di akhirat)"},{id:48,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064f\u0633\u06e1\u062d\u064e\u0628\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0639\u064e\u0644\u064e\u0649\u0670 \u0648\u064f\u062c\u064f\u0648\u0647\u0650\u0647\u0650\u0645\u06e1 \u0630\u064f\u0648\u0642\u064f\u0648\u0627\u0652 \u0645\u064e\u0633\u0651\u064e \u0633\u064e\u0642\u064e\u0631\u064e",translation:"Pada hari mereka diseret ke neraka pada wajahnya. (Dikatakan kepada mereka), \"Rasakanlah sentuhan api neraka"},{id:49,text:"\u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064f\u0644\u0651\u064e \u0634\u064e\u064a\u06e1\u0621\u064d \u062e\u064e\u0644\u064e\u0642\u06e1\u0646\u064e\u0670\u0647\u064f \u0628\u0650\u0642\u064e\u062f\u064e\u0631\u0656",translation:"Sungguh, Kami menciptakan segala sesuatu menurut ukuran"},{id:50,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0645\u06e1\u0631\u064f\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0648\u064e\u0670\u062d\u0650\u062f\u064e\u0629\u065e \u0643\u064e\u0644\u064e\u0645\u06e1\u062d\u0650\u06ed \u0628\u0650\u0671\u0644\u06e1\u0628\u064e\u0635\u064e\u0631\u0650",translation:"Dan perintah Kami hanyalah (dengan) satu perkataan seperti kejapan mata"},{id:51,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u0647\u06e1\u0644\u064e\u0643\u06e1\u0646\u064e\u0627\u0653 \u0623\u064e\u0634\u06e1\u064a\u064e\u0627\u0639\u064e\u0643\u064f\u0645\u06e1 \u0641\u064e\u0647\u064e\u0644\u06e1 \u0645\u0650\u0646 \u0645\u0651\u064f\u062f\u0651\u064e\u0643\u0650\u0631\u0656",translation:"Dan sungguh, telah Kami binasakan orang yang serupa dengan kamu (kekafirannya). Maka adakah orang yang mau mengambil pelajaran"},{id:52,text:"\u0648\u064e\u0643\u064f\u0644\u0651\u064f \u0634\u064e\u064a\u06e1\u0621\u0656 \u0641\u064e\u0639\u064e\u0644\u064f\u0648\u0647\u064f \u0641\u0650\u064a \u0671\u0644\u0632\u0651\u064f\u0628\u064f\u0631\u0650",translation:"Dan segala sesuatu yang telah mereka perbuat tercatat dalam buku-buku catatan"},{id:53,text:"\u0648\u064e\u0643\u064f\u0644\u0651\u064f \u0635\u064e\u063a\u0650\u064a\u0631\u0656 \u0648\u064e\u0643\u064e\u0628\u0650\u064a\u0631\u0656 \u0645\u0651\u064f\u0633\u06e1\u062a\u064e\u0637\u064e\u0631\u064c",translation:"Dan segala (sesuatu) yang kecil maupun yang besar (semuanya) tertulis"},{id:54,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0656 \u0648\u064e\u0646\u064e\u0647\u064e\u0631\u0656",translation:"Sungguh, orang-orang yang bertakwa berada di taman-taman dan sungai-sungai"},{id:55,text:"\u0641\u0650\u064a \u0645\u064e\u0642\u06e1\u0639\u064e\u062f\u0650 \u0635\u0650\u062f\u06e1\u0642\u064d \u0639\u0650\u0646\u062f\u064e \u0645\u064e\u0644\u0650\u064a\u0643\u0656 \u0645\u0651\u064f\u0642\u06e1\u062a\u064e\u062f\u0650\u0631\u0650\u06ed",translation:"di tempat yang disenangi di sisi Tuhan Yang Mahakuasa"}]},{id:55,name:"\u0627\u0644\u0631\u062d\u0645\u0646",transliteration:"Ar-Rahman",translation:"Yang Maha Pemurah",type:"medinan",total_verses:78,verses:[{id:1,text:"\u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u064f",translation:"(Allah) Yang Maha Pengasih"},{id:2,text:"\u0639\u064e\u0644\u0651\u064e\u0645\u064e \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u064e",translation:"Yang telah mengajarkan Alquran"},{id:3,text:"\u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064e",translation:"Dia menciptakan manusia"},{id:4,text:"\u0639\u064e\u0644\u0651\u064e\u0645\u064e\u0647\u064f \u0671\u0644\u06e1\u0628\u064e\u064a\u064e\u0627\u0646\u064e",translation:"mengajarnya pandai berbicara"},{id:5,text:"\u0671\u0644\u0634\u0651\u064e\u0645\u06e1\u0633\u064f \u0648\u064e\u0671\u0644\u06e1\u0642\u064e\u0645\u064e\u0631\u064f \u0628\u0650\u062d\u064f\u0633\u06e1\u0628\u064e\u0627\u0646\u0656",translation:"Matahari dan bulan beredar menurut perhitungan"},{id:6,text:"\u0648\u064e\u0671\u0644\u0646\u0651\u064e\u062c\u06e1\u0645\u064f \u0648\u064e\u0671\u0644\u0634\u0651\u064e\u062c\u064e\u0631\u064f \u064a\u064e\u0633\u06e1\u062c\u064f\u062f\u064e\u0627\u0646\u0650",translation:"Bintang dan pepohonan, keduanya tunduk (kepada-Nya)"},{id:7,text:"\u0648\u064e\u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u064e \u0631\u064e\u0641\u064e\u0639\u064e\u0647\u064e\u0627 \u0648\u064e\u0648\u064e\u0636\u064e\u0639\u064e \u0671\u0644\u06e1\u0645\u0650\u064a\u0632\u064e\u0627\u0646\u064e",translation:"Dan langit telah ditinggikan-Nya dan Dia ciptakan keseimbangan"},{id:8,text:"\u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064e\u0637\u06e1\u063a\u064e\u0648\u06e1\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u06e1\u0645\u0650\u064a\u0632\u064e\u0627\u0646\u0650",translation:"agar kamu jangan merusak keseimbangan itu"},{id:9,text:"\u0648\u064e\u0623\u064e\u0642\u0650\u064a\u0645\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0648\u064e\u0632\u06e1\u0646\u064e \u0628\u0650\u0671\u0644\u06e1\u0642\u0650\u0633\u06e1\u0637\u0650 \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u062e\u06e1\u0633\u0650\u0631\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0645\u0650\u064a\u0632\u064e\u0627\u0646\u064e",translation:"Dan tegakkanlah keseimbangan itu dengan adil dan janganlah kamu mengurangi keseimbangan itu"},{id:10,text:"\u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0648\u064e\u0636\u064e\u0639\u064e\u0647\u064e\u0627 \u0644\u0650\u0644\u06e1\u0623\u064e\u0646\u064e\u0627\u0645\u0650",translation:"Dan bumi telah dibentangkan-Nya untuk makhluk(-Nya)"},{id:11,text:"\u0641\u0650\u064a\u0647\u064e\u0627 \u0641\u064e\u0670\u0643\u0650\u0647\u064e\u0629\u065e \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u062e\u06e1\u0644\u064f \u0630\u064e\u0627\u062a\u064f \u0671\u0644\u06e1\u0623\u064e\u0643\u06e1\u0645\u064e\u0627\u0645\u0650",translation:"di dalamnya ada buah-buahan dan pohon kurma yang mempunyai kelopak mayang"},{id:12,text:"\u0648\u064e\u0671\u0644\u06e1\u062d\u064e\u0628\u0651\u064f \u0630\u064f\u0648 \u0671\u0644\u06e1\u0639\u064e\u0635\u06e1\u0641\u0650 \u0648\u064e\u0671\u0644\u0631\u0651\u064e\u064a\u06e1\u062d\u064e\u0627\u0646\u064f",translation:"dan biji-bijian yang berkulit dan bunga-bunga yang harum baunya"},{id:13,text:"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0621\u064e\u0627\u0644\u064e\u0627\u0653\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",translation:"Maka nikmat Tuhanmu yang manakah yang kamu dustakan"},{id:14,text:"\u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064e \u0645\u0650\u0646 \u0635\u064e\u0644\u06e1\u0635\u064e\u0670\u0644\u0656 \u0643\u064e\u0671\u0644\u06e1\u0641\u064e\u062e\u0651\u064e\u0627\u0631\u0650",translation:"Dia menciptakan manusia dari tanah kering seperti tembikar"},{id:15,text:"\u0648\u064e\u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u06e1\u062c\u064e\u0627\u0653\u0646\u0651\u064e \u0645\u0650\u0646 \u0645\u0651\u064e\u0627\u0631\u0650\u062c\u0656 \u0645\u0651\u0650\u0646 \u0646\u0651\u064e\u0627\u0631\u0656",translation:"dan Dia menciptakan jin dari nyala api tanpa asap"},{id:16,text:"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0621\u064e\u0627\u0644\u064e\u0627\u0653\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",translation:"Maka nikmat Tuhanmu yang manakah yang kamu dustakan"},{id:17,text:"\u0631\u064e\u0628\u0651\u064f \u0671\u0644\u06e1\u0645\u064e\u0634\u06e1\u0631\u0650\u0642\u064e\u064a\u06e1\u0646\u0650 \u0648\u064e\u0631\u064e\u0628\u0651\u064f \u0671\u0644\u06e1\u0645\u064e\u063a\u06e1\u0631\u0650\u0628\u064e\u064a\u06e1\u0646\u0650",translation:"Tuhan (yang memelihara) dua Timur dan Tuhan (yang memelihara) dua Barat"},{id:18,text:"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0621\u064e\u0627\u0644\u064e\u0627\u0653\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",translation:"Maka nikmat Tuhanmu yang manakah yang kamu dustakan"},{id:19,text:"\u0645\u064e\u0631\u064e\u062c\u064e \u0671\u0644\u06e1\u0628\u064e\u062d\u06e1\u0631\u064e\u064a\u06e1\u0646\u0650 \u064a\u064e\u0644\u06e1\u062a\u064e\u0642\u0650\u064a\u064e\u0627\u0646\u0650",translation:"Dia membiarkan dua laut mengalir yang (kemudian) keduanya bertemu"},{id:20,text:"\u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0628\u064e\u0631\u06e1\u0632\u064e\u062e\u065e \u0644\u0651\u064e\u0627 \u064a\u064e\u0628\u06e1\u063a\u0650\u064a\u064e\u0627\u0646\u0650",translation:"di antara keduanya ada batas yang tidak dilampaui oleh masing-masing"},{id:21,text:"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0621\u064e\u0627\u0644\u064e\u0627\u0653\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",translation:"Maka nikmat Tuhanmu yang manakah yang kamu dustakan"},{id:22,text:"\u064a\u064e\u062e\u06e1\u0631\u064f\u062c\u064f \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u064e\u0627 \u0671\u0644\u0644\u0651\u064f\u0624\u06e1\u0644\u064f\u0624\u064f \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u0631\u06e1\u062c\u064e\u0627\u0646\u064f",translation:"Dari keduanya keluar mutiara dan marjan"},{id:23,text:"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0621\u064e\u0627\u0644\u064e\u0627\u0653\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",translation:"Maka nikmat Tuhanmu yang manakah yang kamu dustakan"},{id:24,text:"\u0648\u064e\u0644\u064e\u0647\u064f \u0671\u0644\u06e1\u062c\u064e\u0648\u064e\u0627\u0631\u0650 \u0671\u0644\u06e1\u0645\u064f\u0646\u0634\u064e\u0640\u0654\u064e\u0627\u062a\u064f \u0641\u0650\u064a \u0671\u0644\u06e1\u0628\u064e\u062d\u06e1\u0631\u0650 \u0643\u064e\u0671\u0644\u06e1\u0623\u064e\u0639\u06e1\u0644\u064e\u0670\u0645\u0650",translation:"Milik-Nyalah kapal-kapal yang berlayar di lautan bagaikan gunung-gunung"},{id:25,text:"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0621\u064e\u0627\u0644\u064e\u0627\u0653\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",translation:"Maka nikmat Tuhanmu yang manakah yang kamu dustakan"},{id:26,text:"\u0643\u064f\u0644\u0651\u064f \u0645\u064e\u0646\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627 \u0641\u064e\u0627\u0646\u0656",translation:"Semua yang ada di bumi itu akan binasa"},{id:27,text:"\u0648\u064e\u064a\u064e\u0628\u06e1\u0642\u064e\u0649\u0670 \u0648\u064e\u062c\u06e1\u0647\u064f \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0630\u064f\u0648 \u0671\u0644\u06e1\u062c\u064e\u0644\u064e\u0670\u0644\u0650 \u0648\u064e\u0671\u0644\u06e1\u0625\u0650\u0643\u06e1\u0631\u064e\u0627\u0645\u0650",translation:"tetapi wajah Tuhanmu yang memiliki kebesaran dan kemuliaan tetap kekal"},{id:28,text:"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0621\u064e\u0627\u0644\u064e\u0627\u0653\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",translation:"Maka nikmat Tuhanmu yang manakah yang kamu dustakan"},{id:29,text:"\u064a\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0647\u064f\u06e5 \u0645\u064e\u0646 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06da \u0643\u064f\u0644\u0651\u064e \u064a\u064e\u0648\u06e1\u0645\u064d \u0647\u064f\u0648\u064e \u0641\u0650\u064a \u0634\u064e\u0623\u06e1\u0646\u0656",translation:"Apa yang di langit dan di bumi selalu meminta kepada-Nya. Setiap waktu Dia dalam kesibukan"},{id:30,text:"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0621\u064e\u0627\u0644\u064e\u0627\u0653\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",translation:"Maka nikmat Tuhanmu yang manakah yang kamu dustakan"},{id:31,text:"\u0633\u064e\u0646\u064e\u0641\u06e1\u0631\u064f\u063a\u064f \u0644\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u064a\u0651\u064f\u0647\u064e \u0671\u0644\u062b\u0651\u064e\u0642\u064e\u0644\u064e\u0627\u0646\u0650",translation:"Kami akan memberi perhatian sepenuhnya kepadamu wahai (golongan) manusia dan jin"},{id:32,text:"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0621\u064e\u0627\u0644\u064e\u0627\u0653\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",translation:"Maka nikmat Tuhanmu yang manakah yang kamu dustakan"},{id:33,text:"\u064a\u064e\u0670\u0645\u064e\u0639\u06e1\u0634\u064e\u0631\u064e \u0671\u0644\u06e1\u062c\u0650\u0646\u0651\u0650 \u0648\u064e\u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u0650 \u0625\u0650\u0646\u0650 \u0671\u0633\u06e1\u062a\u064e\u0637\u064e\u0639\u06e1\u062a\u064f\u0645\u06e1 \u0623\u064e\u0646 \u062a\u064e\u0646\u0641\u064f\u0630\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1 \u0623\u064e\u0642\u06e1\u0637\u064e\u0627\u0631\u0650 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0641\u064e\u0671\u0646\u0641\u064f\u0630\u064f\u0648\u0627\u0652\u06da \u0644\u064e\u0627 \u062a\u064e\u0646\u0641\u064f\u0630\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0633\u064f\u0644\u06e1\u0637\u064e\u0670\u0646\u0656",translation:"Wahai golongan jin dan manusia! Jika kamu sanggup menembus (melintasi) penjuru langit dan bumi, maka tembuslah. Kamu tidak akan mampu menembusnya kecuali dengan kekuatan (dari Allah)"},{id:34,text:"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0621\u064e\u0627\u0644\u064e\u0627\u0653\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",translation:"Maka nikmat Tuhanmu yang manakah yang kamu dustakan"},{id:35,text:"\u064a\u064f\u0631\u06e1\u0633\u064e\u0644\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u064e\u0627 \u0634\u064f\u0648\u064e\u0627\u0638\u065e \u0645\u0651\u0650\u0646 \u0646\u0651\u064e\u0627\u0631\u0656 \u0648\u064e\u0646\u064f\u062d\u064e\u0627\u0633\u065e \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0646\u062a\u064e\u0635\u0650\u0631\u064e\u0627\u0646\u0650",translation:"Kepada kamu (jin dan manusia), akan dikirim nyala api dan cairan tembaga (panas) sehingga kamu tidak dapat menyelamatkan diri (darinya)"},{id:36,text:"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0621\u064e\u0627\u0644\u064e\u0627\u0653\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",translation:"Maka nikmat Tuhanmu yang manakah yang kamu dustakan"},{id:37,text:"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0671\u0646\u0634\u064e\u0642\u0651\u064e\u062a\u0650 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u064f \u0641\u064e\u0643\u064e\u0627\u0646\u064e\u062a\u06e1 \u0648\u064e\u0631\u06e1\u062f\u064e\u0629\u0657 \u0643\u064e\u0671\u0644\u062f\u0651\u0650\u0647\u064e\u0627\u0646\u0650",translation:"Maka apabila langit telah terbelah dan menjadi merah mawar seperti (kilauan) minyak"},{id:38,text:"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0621\u064e\u0627\u0644\u064e\u0627\u0653\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",translation:"Maka nikmat Tuhanmu yang manakah yang kamu dustakan"},{id:39,text:"\u0641\u064e\u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u0644\u0651\u064e\u0627 \u064a\u064f\u0633\u06e1\u0640\u0654\u064e\u0644\u064f \u0639\u064e\u0646 \u0630\u064e\u0646\u06e2\u0628\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0646\u0633\u065e \u0648\u064e\u0644\u064e\u0627 \u062c\u064e\u0627\u0653\u0646\u0651\u065e",translation:"Maka pada hari itu manusia dan jin tidak ditanya tentang dosanya"},{id:40,text:"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0621\u064e\u0627\u0644\u064e\u0627\u0653\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",translation:"Maka nikmat Tuhanmu yang manakah yang kamu dustakan"},{id:41,text:"\u064a\u064f\u0639\u06e1\u0631\u064e\u0641\u064f \u0671\u0644\u06e1\u0645\u064f\u062c\u06e1\u0631\u0650\u0645\u064f\u0648\u0646\u064e \u0628\u0650\u0633\u0650\u064a\u0645\u064e\u0670\u0647\u064f\u0645\u06e1 \u0641\u064e\u064a\u064f\u0624\u06e1\u062e\u064e\u0630\u064f \u0628\u0650\u0671\u0644\u0646\u0651\u064e\u0648\u064e\u0670\u0635\u0650\u064a \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0642\u06e1\u062f\u064e\u0627\u0645\u0650",translation:"Orang-orang yang berdosa itu diketahui dengan tanda-tandanya, lalu direnggut ubun-ubun dan kakinya"},{id:42,text:"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0621\u064e\u0627\u0644\u064e\u0627\u0653\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",translation:"Maka nikmat Tuhanmu yang manakah yang kamu dustakan"},{id:43,text:"\u0647\u064e\u0670\u0630\u0650\u0647\u0650\u06e6 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064f \u0671\u0644\u0651\u064e\u062a\u0650\u064a \u064a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f \u0628\u0650\u0647\u064e\u0627 \u0671\u0644\u06e1\u0645\u064f\u062c\u06e1\u0631\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Inilah neraka Jahanam yang didustakan oleh orang-orang yang berdosa"},{id:44,text:"\u064a\u064e\u0637\u064f\u0648\u0641\u064f\u0648\u0646\u064e \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064e\u0627 \u0648\u064e\u0628\u064e\u064a\u06e1\u0646\u064e \u062d\u064e\u0645\u0650\u064a\u0645\u064d \u0621\u064e\u0627\u0646\u0656",translation:"Mereka berkeliling di sana dan di antara air yang mendidih"},{id:45,text:"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0621\u064e\u0627\u0644\u064e\u0627\u0653\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",translation:"Maka nikmat Tuhanmu yang manakah yang kamu dustakan"},{id:46,text:"\u0648\u064e\u0644\u0650\u0645\u064e\u0646\u06e1 \u062e\u064e\u0627\u0641\u064e \u0645\u064e\u0642\u064e\u0627\u0645\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u06e6 \u062c\u064e\u0646\u0651\u064e\u062a\u064e\u0627\u0646\u0650",translation:"Dan bagi siapa yang takut akan saat menghadap Tuhannya ada dua surga"},{id:47,text:"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0621\u064e\u0627\u0644\u064e\u0627\u0653\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",translation:"Maka nikmat Tuhanmu yang manakah yang kamu dustakan"},{id:48,text:"\u0630\u064e\u0648\u064e\u0627\u062a\u064e\u0627\u0653 \u0623\u064e\u0641\u06e1\u0646\u064e\u0627\u0646\u0656",translation:"kedua surga itu mempunyai aneka pepohonan dan buah-buahan"},{id:49,text:"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0621\u064e\u0627\u0644\u064e\u0627\u0653\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",translation:"Maka nikmat Tuhanmu yang manakah yang kamu dustakan"},{id:50,text:"\u0641\u0650\u064a\u0647\u0650\u0645\u064e\u0627 \u0639\u064e\u064a\u06e1\u0646\u064e\u0627\u0646\u0650 \u062a\u064e\u062c\u06e1\u0631\u0650\u064a\u064e\u0627\u0646\u0650",translation:"Di dalam kedua surga itu ada dua buah mata air yang memancar"},{id:51,text:"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0621\u064e\u0627\u0644\u064e\u0627\u0653\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",translation:"Maka nikmat Tuhanmu yang manakah yang kamu dustakan"},{id:52,text:"\u0641\u0650\u064a\u0647\u0650\u0645\u064e\u0627 \u0645\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u0641\u064e\u0670\u0643\u0650\u0647\u064e\u0629\u0656 \u0632\u064e\u0648\u06e1\u062c\u064e\u0627\u0646\u0650",translation:"Di dalam kedua surga itu terdapat aneka buah-buahan yang berpasang-pasangan"},{id:53,text:"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0621\u064e\u0627\u0644\u064e\u0627\u0653\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",translation:"Maka nikmat Tuhanmu yang manakah yang kamu dustakan"},{id:54,text:"\u0645\u064f\u062a\u0651\u064e\u0643\u0650\u0640\u0654\u0650\u064a\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0641\u064f\u0631\u064f\u0634\u0650\u06ed \u0628\u064e\u0637\u064e\u0627\u0653\u0626\u0650\u0646\u064f\u0647\u064e\u0627 \u0645\u0650\u0646\u06e1 \u0625\u0650\u0633\u06e1\u062a\u064e\u0628\u06e1\u0631\u064e\u0642\u0656\u06da \u0648\u064e\u062c\u064e\u0646\u064e\u0649 \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u062a\u064e\u064a\u06e1\u0646\u0650 \u062f\u064e\u0627\u0646\u0656",translation:"Mereka bersandar di atas permadani yang bagian dalamnya dari sutera tebal. Dan buah-buahan di kedua surga itu dapat (dipetik) dari dekat"},{id:55,text:"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0621\u064e\u0627\u0644\u064e\u0627\u0653\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",translation:"Maka nikmat Tuhanmu yang manakah yang kamu dustakan"},{id:56,text:"\u0641\u0650\u064a\u0647\u0650\u0646\u0651\u064e \u0642\u064e\u0670\u0635\u0650\u0631\u064e\u0670\u062a\u064f \u0671\u0644\u0637\u0651\u064e\u0631\u06e1\u0641\u0650 \u0644\u064e\u0645\u06e1 \u064a\u064e\u0637\u06e1\u0645\u0650\u062b\u06e1\u0647\u064f\u0646\u0651\u064e \u0625\u0650\u0646\u0633\u065e \u0642\u064e\u0628\u06e1\u0644\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u062c\u064e\u0627\u0653\u0646\u0651\u065e",translation:"Di dalam surga itu ada bidadari-bidadari yang membatasi pandangan, yang tidak pernah disentuh oleh manusia maupun jin sebelumnya"},{id:57,text:"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0621\u064e\u0627\u0644\u064e\u0627\u0653\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",translation:"Maka nikmat Tuhanmu yang manakah yang kamu dustakan"},{id:58,text:"\u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0646\u0651\u064e \u0671\u0644\u06e1\u064a\u064e\u0627\u0642\u064f\u0648\u062a\u064f \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u0631\u06e1\u062c\u064e\u0627\u0646\u064f",translation:"Seakan-akan mereka itu permata yakut dan marjan"},{id:59,text:"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0621\u064e\u0627\u0644\u064e\u0627\u0653\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",translation:"Maka nikmat Tuhanmu yang manakah yang kamu dustakan"},{id:60,text:"\u0647\u064e\u0644\u06e1 \u062c\u064e\u0632\u064e\u0627\u0653\u0621\u064f \u0671\u0644\u06e1\u0625\u0650\u062d\u06e1\u0633\u064e\u0670\u0646\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u06e1\u0625\u0650\u062d\u06e1\u0633\u064e\u0670\u0646\u064f",translation:"Tidak ada balasan untuk kebaikan selain kebaikan (pula)"},{id:61,text:"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0621\u064e\u0627\u0644\u064e\u0627\u0653\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",translation:"Maka nikmat Tuhanmu yang manakah yang kamu dustakan"},{id:62,text:"\u0648\u064e\u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u0645\u064e\u0627 \u062c\u064e\u0646\u0651\u064e\u062a\u064e\u0627\u0646\u0650",translation:"Dan selain dari dua surga itu ada dua surga lagi"},{id:63,text:"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0621\u064e\u0627\u0644\u064e\u0627\u0653\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",translation:"Maka nikmat Tuhanmu yang manakah yang kamu dustakan"},{id:64,text:"\u0645\u064f\u062f\u06e1\u0647\u064e\u0627\u0653\u0645\u0651\u064e\u062a\u064e\u0627\u0646\u0650",translation:"kedua surga itu (kelihatan) hijau tua warnanya"},{id:65,text:"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0621\u064e\u0627\u0644\u064e\u0627\u0653\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",translation:"Maka nikmat Tuhanmu yang manakah yang kamu dustakan"},{id:66,text:"\u0641\u0650\u064a\u0647\u0650\u0645\u064e\u0627 \u0639\u064e\u064a\u06e1\u0646\u064e\u0627\u0646\u0650 \u0646\u064e\u0636\u0651\u064e\u0627\u062e\u064e\u062a\u064e\u0627\u0646\u0650",translation:"Di dalam keduanya (surga itu) ada dua mata air yang memancar"},{id:67,text:"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0621\u064e\u0627\u0644\u064e\u0627\u0653\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",translation:"Maka nikmat Tuhanmu yang manakah yang kamu dustakan"},{id:68,text:"\u0641\u0650\u064a\u0647\u0650\u0645\u064e\u0627 \u0641\u064e\u0670\u0643\u0650\u0647\u064e\u0629\u065e \u0648\u064e\u0646\u064e\u062e\u06e1\u0644\u065e \u0648\u064e\u0631\u064f\u0645\u0651\u064e\u0627\u0646\u065e",translation:"Di dalam kedua surga itu ada buah-buahan, kurma dan delima"},{id:69,text:"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0621\u064e\u0627\u0644\u064e\u0627\u0653\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",translation:"Maka nikmat Tuhanmu yang manakah yang kamu dustakan"},{id:70,text:"\u0641\u0650\u064a\u0647\u0650\u0646\u0651\u064e \u062e\u064e\u064a\u06e1\u0631\u064e\u0670\u062a\u064c \u062d\u0650\u0633\u064e\u0627\u0646\u065e",translation:"Di dalam surga-surga itu ada bidadari-bidadari yang baik-baik dan jelita"},{id:71,text:"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0621\u064e\u0627\u0644\u064e\u0627\u0653\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",translation:"Maka nikmat Tuhanmu yang manakah yang kamu dustakan"},{id:72,text:"\u062d\u064f\u0648\u0631\u065e \u0645\u0651\u064e\u0642\u06e1\u0635\u064f\u0648\u0631\u064e\u0670\u062a\u065e \u0641\u0650\u064a \u0671\u0644\u06e1\u062e\u0650\u064a\u064e\u0627\u0645\u0650",translation:"Bidadari-bidadari yang dipelihara di dalam kemah-kemah"},{id:73,text:"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0621\u064e\u0627\u0644\u064e\u0627\u0653\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",translation:"Maka nikmat Tuhanmu yang manakah yang kamu dustakan"},{id:74,text:"\u0644\u064e\u0645\u06e1 \u064a\u064e\u0637\u06e1\u0645\u0650\u062b\u06e1\u0647\u064f\u0646\u0651\u064e \u0625\u0650\u0646\u0633\u065e \u0642\u064e\u0628\u06e1\u0644\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u062c\u064e\u0627\u0653\u0646\u0651\u065e",translation:"Mereka sebelumnya tidak pernah disentuh oleh manusia maupun oleh jin"},{id:75,text:"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0621\u064e\u0627\u0644\u064e\u0627\u0653\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",translation:"Maka nikmat Tuhanmu yang manakah yang kamu dustakan"},{id:76,text:"\u0645\u064f\u062a\u0651\u064e\u0643\u0650\u0640\u0654\u0650\u064a\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0641\u06e1\u0631\u064e\u0641\u064d \u062e\u064f\u0636\u06e1\u0631\u0656 \u0648\u064e\u0639\u064e\u0628\u06e1\u0642\u064e\u0631\u0650\u064a\u0651\u064d \u062d\u0650\u0633\u064e\u0627\u0646\u0656",translation:"Mereka bersandar pada bantal-bantal yang hijau dan permadani-permadani yang indah"},{id:77,text:"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0621\u064e\u0627\u0644\u064e\u0627\u0653\u0621\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u064e\u0627 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064e\u0627\u0646\u0650",translation:"Maka nikmat Tuhanmu yang manakah yang kamu dustakan"},{id:78,text:"\u062a\u064e\u0628\u064e\u0670\u0631\u064e\u0643\u064e \u0671\u0633\u06e1\u0645\u064f \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0630\u0650\u064a \u0671\u0644\u06e1\u062c\u064e\u0644\u064e\u0670\u0644\u0650 \u0648\u064e\u0671\u0644\u06e1\u0625\u0650\u0643\u06e1\u0631\u064e\u0627\u0645\u0650",translation:"Mahasuci nama Tuhanmu Pemilik Keagungan dan Kemuliaan"}]},{id:56,name:"\u0627\u0644\u0648\u0627\u0642\u0639\u0629",transliteration:"Al-Waqi'ah",translation:"Hari Kiamat",type:"meccan",total_verses:96,verses:[{id:1,text:"\u0625\u0650\u0630\u064e\u0627 \u0648\u064e\u0642\u064e\u0639\u064e\u062a\u0650 \u0671\u0644\u06e1\u0648\u064e\u0627\u0642\u0650\u0639\u064e\u0629\u064f",translation:"Apabila terjadi hari Kiamat"},{id:2,text:"\u0644\u064e\u064a\u06e1\u0633\u064e \u0644\u0650\u0648\u064e\u0642\u06e1\u0639\u064e\u062a\u0650\u0647\u064e\u0627 \u0643\u064e\u0627\u0630\u0650\u0628\u064e\u0629\u064c",translation:"terjadinya tidak dapat didustakan (disangkal)"},{id:3,text:"\u062e\u064e\u0627\u0641\u0650\u0636\u064e\u0629\u065e \u0631\u0651\u064e\u0627\u0641\u0650\u0639\u064e\u0629\u064c",translation:"(Kejadian itu) merendahkan (satu golongan) dan meninggikan (golongan yang lain)"},{id:4,text:"\u0625\u0650\u0630\u064e\u0627 \u0631\u064f\u062c\u0651\u064e\u062a\u0650 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064f \u0631\u064e\u062c\u0651\u0657\u0627",translation:"Apabila bumi diguncangkan sedahsyat-dahsyatnya"},{id:5,text:"\u0648\u064e\u0628\u064f\u0633\u0651\u064e\u062a\u0650 \u0671\u0644\u06e1\u062c\u0650\u0628\u064e\u0627\u0644\u064f \u0628\u064e\u0633\u0651\u0657\u0627",translation:"dan gunung-gunung dihancur luluhkan sehancur-hancurnya"},{id:6,text:"\u0641\u064e\u0643\u064e\u0627\u0646\u064e\u062a\u06e1 \u0647\u064e\u0628\u064e\u0627\u0653\u0621\u0657 \u0645\u0651\u064f\u0646\u06e2\u0628\u064e\u062b\u0651\u0657\u0627",translation:"maka jadilah ia debu yang berterbangan"},{id:7,text:"\u0648\u064e\u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u0657\u0627 \u062b\u064e\u0644\u064e\u0670\u062b\u064e\u0629\u0657",translation:"dan kamu menjadi tiga golongan"},{id:8,text:"\u0641\u064e\u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u06e1\u0645\u064e\u064a\u06e1\u0645\u064e\u0646\u064e\u0629\u0650 \u0645\u064e\u0627\u0653 \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u06e1\u0645\u064e\u064a\u06e1\u0645\u064e\u0646\u064e\u0629\u0650",translation:"(yaitu golongan kanan,825) alangkah mulianya golongan kanan itu"},{id:9,text:"\u0648\u064e\u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u06e1\u0645\u064e\u0634\u06e1\u0640\u0654\u064e\u0645\u064e\u0629\u0650 \u0645\u064e\u0627\u0653 \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u06e1\u0645\u064e\u0634\u06e1\u0640\u0654\u064e\u0645\u064e\u0629\u0650",translation:"(dan golongan kiri,826) alangkah sengsaranya golongan kiri itu"},{id:10,text:"\u0648\u064e\u0671\u0644\u0633\u0651\u064e\u0640\u0670\u0628\u0650\u0642\u064f\u0648\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0640\u0670\u0628\u0650\u0642\u064f\u0648\u0646\u064e",translation:"dan orang-orang yang paling dahulu (beriman), merekalah yang paling dahulu (masuk surga)"},{id:11,text:"\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0671\u0644\u06e1\u0645\u064f\u0642\u064e\u0631\u0651\u064e\u0628\u064f\u0648\u0646\u064e",translation:"mereka itulah orang yang dekat (kepada Allah)"},{id:12,text:"\u0641\u0650\u064a \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0650 \u0671\u0644\u0646\u0651\u064e\u0639\u0650\u064a\u0645\u0650",translation:"Berada dalam surga kenikmatan"},{id:13,text:"\u062b\u064f\u0644\u0651\u064e\u0629\u065e \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",translation:"segolongan besar dari orang-orang yang terdahulu"},{id:14,text:"\u0648\u064e\u0642\u064e\u0644\u0650\u064a\u0644\u065e \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u0650\u064a\u0646\u064e",translation:"dan segolongan kecil dari orang-orang yang kemudian"},{id:15,text:"\u0639\u064e\u0644\u064e\u0649\u0670 \u0633\u064f\u0631\u064f\u0631\u0656 \u0645\u0651\u064e\u0648\u06e1\u0636\u064f\u0648\u0646\u064e\u0629\u0656",translation:"mereka berada di atas dipan-dipan yang bertahtakan emas dan permata"},{id:16,text:"\u0645\u0651\u064f\u062a\u0651\u064e\u0643\u0650\u0640\u0654\u0650\u064a\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627 \u0645\u064f\u062a\u064e\u0642\u064e\u0670\u0628\u0650\u0644\u0650\u064a\u0646\u064e",translation:"mereka bersandar di atasnya berhadap-hadapan"},{id:17,text:"\u064a\u064e\u0637\u064f\u0648\u0641\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0648\u0650\u0644\u06e1\u062f\u064e\u0670\u0646\u065e \u0645\u0651\u064f\u062e\u064e\u0644\u0651\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Mereka dikelilingi oleh anak-anak muda yang tetap muda"},{id:18,text:"\u0628\u0650\u0623\u064e\u0643\u06e1\u0648\u064e\u0627\u0628\u0656 \u0648\u064e\u0623\u064e\u0628\u064e\u0627\u0631\u0650\u064a\u0642\u064e \u0648\u064e\u0643\u064e\u0623\u06e1\u0633\u0656 \u0645\u0651\u0650\u0646 \u0645\u0651\u064e\u0639\u0650\u064a\u0646\u0656",translation:"dengan membawa gelas, cerek dan gelas besar (piala) berisi minuman yang diambil dari air yang mengalir"},{id:19,text:"\u0644\u0651\u064e\u0627 \u064a\u064f\u0635\u064e\u062f\u0651\u064e\u0639\u064f\u0648\u0646\u064e \u0639\u064e\u0646\u06e1\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0646\u0632\u0650\u0641\u064f\u0648\u0646\u064e",translation:"mereka tidak pening karenanya dan tidak pula mabuk"},{id:20,text:"\u0648\u064e\u0641\u064e\u0670\u0643\u0650\u0647\u064e\u0629\u0656 \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u062a\u064e\u062e\u064e\u064a\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"dan buah-buahan apa pun yang mereka pilih"},{id:21,text:"\u0648\u064e\u0644\u064e\u062d\u06e1\u0645\u0650 \u0637\u064e\u064a\u06e1\u0631\u0656 \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u0634\u06e1\u062a\u064e\u0647\u064f\u0648\u0646\u064e",translation:"dan daging burung apa pun yang mereka inginkan"},{id:22,text:"\u0648\u064e\u062d\u064f\u0648\u0631\u064c \u0639\u0650\u064a\u0646\u065e",translation:"dan ada bidadari-bidadari yang bermata indah"},{id:23,text:"\u0643\u064e\u0623\u064e\u0645\u06e1\u062b\u064e\u0670\u0644\u0650 \u0671\u0644\u0644\u0651\u064f\u0624\u06e1\u0644\u064f\u0648\u0655\u0650 \u0671\u0644\u06e1\u0645\u064e\u0643\u06e1\u0646\u064f\u0648\u0646\u0650",translation:"laksana mutiara yang tersimpan baik"},{id:24,text:"\u062c\u064e\u0632\u064e\u0627\u0653\u0621\u064e\u06e2 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Sebagai balasan atas apa yang mereka kerjakan"},{id:25,text:"\u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u0645\u064e\u0639\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0644\u064e\u063a\u06e1\u0648\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0623\u06e1\u062b\u0650\u064a\u0645\u064b\u0627",translation:"Di sana mereka tidak mendengar percakapan yang sia-sia maupun yang menimbulkan dosa"},{id:26,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u0650\u064a\u0644\u0657\u0627 \u0633\u064e\u0644\u064e\u0670\u0645\u0657\u0627 \u0633\u064e\u0644\u064e\u0670\u0645\u0657\u0627",translation:"tetapi mereka mendengar ucapan salam"},{id:27,text:"\u0648\u064e\u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u06e1\u064a\u064e\u0645\u0650\u064a\u0646\u0650 \u0645\u064e\u0627\u0653 \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u06e1\u064a\u064e\u0645\u0650\u064a\u0646\u0650",translation:"Dan golongan kanan, alangkah mulianya golongan kanan itu"},{id:28,text:"\u0641\u0650\u064a \u0633\u0650\u062f\u06e1\u0631\u0656 \u0645\u0651\u064e\u062e\u06e1\u0636\u064f\u0648\u062f\u0656",translation:"(Mereka) berada di antara pohon bidara yang tidak berduri"},{id:29,text:"\u0648\u064e\u0637\u064e\u0644\u06e1\u062d\u0656 \u0645\u0651\u064e\u0646\u0636\u064f\u0648\u062f\u0656",translation:"dan pohon pisang yang bersusun-susun (buahnya)"},{id:30,text:"\u0648\u064e\u0638\u0650\u0644\u0651\u0656 \u0645\u0651\u064e\u0645\u06e1\u062f\u064f\u0648\u062f\u0656",translation:"dan naungan yang terbentang luas"},{id:31,text:"\u0648\u064e\u0645\u064e\u0627\u0653\u0621\u0656 \u0645\u0651\u064e\u0633\u06e1\u0643\u064f\u0648\u0628\u0656",translation:"dan air yang mengalir terus-menerus"},{id:32,text:"\u0648\u064e\u0641\u064e\u0670\u0643\u0650\u0647\u064e\u0629\u0656 \u0643\u064e\u062b\u0650\u064a\u0631\u064e\u0629\u0656",translation:"dan buah-buahan yang banyak"},{id:33,text:"\u0644\u0651\u064e\u0627 \u0645\u064e\u0642\u06e1\u0637\u064f\u0648\u0639\u064e\u0629\u0656 \u0648\u064e\u0644\u064e\u0627 \u0645\u064e\u0645\u06e1\u0646\u064f\u0648\u0639\u064e\u0629\u0656",translation:"yang tidak berhenti berbuah dan tidak terlarang mengambilnya"},{id:34,text:"\u0648\u064e\u0641\u064f\u0631\u064f\u0634\u0656 \u0645\u0651\u064e\u0631\u06e1\u0641\u064f\u0648\u0639\u064e\u0629\u064d",translation:"dan kasur-kasur yang tebal lagi empuk"},{id:35,text:"\u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u0646\u0634\u064e\u0623\u06e1\u0646\u064e\u0670\u0647\u064f\u0646\u0651\u064e \u0625\u0650\u0646\u0634\u064e\u0627\u0653\u0621\u0657",translation:"Kami menciptakan mereka (bidadari-bidadari itu) secara langsung"},{id:36,text:"\u0641\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f\u0646\u0651\u064e \u0623\u064e\u0628\u06e1\u0643\u064e\u0627\u0631\u064b\u0627",translation:"lalu Kami jadikan mereka perawan-perawan"},{id:37,text:"\u0639\u064f\u0631\u064f\u0628\u064b\u0627 \u0623\u064e\u062a\u06e1\u0631\u064e\u0627\u0628\u0657\u0627",translation:"yang penuh cinta (dan) sebaya umurnya"},{id:38,text:"\u0644\u0651\u0650\u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u0650 \u0671\u0644\u06e1\u064a\u064e\u0645\u0650\u064a\u0646\u0650",translation:"untuk golongan kanan"},{id:39,text:"\u062b\u064f\u0644\u0651\u064e\u0629\u065e \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",translation:"segolongan besar dari orang-orang yang terdahulu"},{id:40,text:"\u0648\u064e\u062b\u064f\u0644\u0651\u064e\u0629\u065e \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u0650\u064a\u0646\u064e",translation:"dan segolongan besar pula dari orang yang kemudian"},{id:41,text:"\u0648\u064e\u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u0634\u0651\u0650\u0645\u064e\u0627\u0644\u0650 \u0645\u064e\u0627\u0653 \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u0634\u0651\u0650\u0645\u064e\u0627\u0644\u0650",translation:"Dan golongan kiri, alangkah sengsaranya golongan kiri itu"},{id:42,text:"\u0641\u0650\u064a \u0633\u064e\u0645\u064f\u0648\u0645\u0656 \u0648\u064e\u062d\u064e\u0645\u0650\u064a\u0645\u0656",translation:"(Mereka) dalam siksaan angin yang sangat panas dan air yang mendidih"},{id:43,text:"\u0648\u064e\u0638\u0650\u0644\u0651\u0656 \u0645\u0651\u0650\u0646 \u064a\u064e\u062d\u06e1\u0645\u064f\u0648\u0645\u0656",translation:"dan naungan asap yang hitam"},{id:44,text:"\u0644\u0651\u064e\u0627 \u0628\u064e\u0627\u0631\u0650\u062f\u0656 \u0648\u064e\u0644\u064e\u0627 \u0643\u064e\u0631\u0650\u064a\u0645\u064d",translation:"tidak sejuk dan tidak menyenangkan"},{id:45,text:"\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0642\u064e\u0628\u06e1\u0644\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0645\u064f\u062a\u06e1\u0631\u064e\u0641\u0650\u064a\u0646\u064e",translation:"Sesungguhnya mereka sebelum itu (dahulu) hidup bermewah-mewah"},{id:46,text:"\u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064f\u0635\u0650\u0631\u0651\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u062d\u0650\u0646\u062b\u0650 \u0671\u0644\u06e1\u0639\u064e\u0638\u0650\u064a\u0645\u0650",translation:"dan mereka terus-menerus mengerjakan dosa yang besar"},{id:47,text:"\u0648\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0623\u064e\u0626\u0650\u0630\u064e\u0627 \u0645\u0650\u062a\u06e1\u0646\u064e\u0627 \u0648\u064e\u0643\u064f\u0646\u0651\u064e\u0627 \u062a\u064f\u0631\u064e\u0627\u0628\u0657\u0627 \u0648\u064e\u0639\u0650\u0638\u064e\u0670\u0645\u064b\u0627 \u0623\u064e\u0621\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0645\u064e\u0628\u06e1\u0639\u064f\u0648\u062b\u064f\u0648\u0646\u064e",translation:"dan mereka berkata, \"Apabila kami sudah mati, menjadi tanah dan tulang-belulang, apakah kami benar-benar akan dibangkitkan kembali"},{id:48,text:"\u0623\u064e\u0648\u064e\u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0624\u064f\u0646\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0648\u0651\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Apakah nenek moyang kami yang terdahulu (dibangkitkan pula)"},{id:49,text:"\u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Katakanlah, \"(Ya), sesungguhnya orang-orang yang terdahulu dan yang kemudian"},{id:50,text:"\u0644\u064e\u0645\u064e\u062c\u06e1\u0645\u064f\u0648\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u0650\u064a\u0642\u064e\u0670\u062a\u0650 \u064a\u064e\u0648\u06e1\u0645\u0656 \u0645\u0651\u064e\u0639\u06e1\u0644\u064f\u0648\u0645\u0656",translation:"pasti semua akan dikumpulkan pada waktu tertentu, pada hari yang sudah dimaklumi"},{id:51,text:"\u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0636\u0651\u064e\u0627\u0653\u0644\u0651\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Kemudian sesungguhnya kamu, wahai orang-orang yang sesat lagi mendustakan"},{id:52,text:"\u0644\u064e\u0623\u0653\u0643\u0650\u0644\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u0634\u064e\u062c\u064e\u0631\u0656 \u0645\u0651\u0650\u0646 \u0632\u064e\u0642\u0651\u064f\u0648\u0645\u0656",translation:"pasti akan memakan pohon zaqqum"},{id:53,text:"\u0641\u064e\u0645\u064e\u0627\u0644\u0650\u0640\u0654\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0671\u0644\u06e1\u0628\u064f\u0637\u064f\u0648\u0646\u064e",translation:"Maka akan penuh perutmu dengannya"},{id:54,text:"\u0641\u064e\u0634\u064e\u0670\u0631\u0650\u0628\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u062d\u064e\u0645\u0650\u064a\u0645\u0650",translation:"Setelah itu kamu akan memimun air yang sangat panas"},{id:55,text:"\u0641\u064e\u0634\u064e\u0670\u0631\u0650\u0628\u064f\u0648\u0646\u064e \u0634\u064f\u0631\u06e1\u0628\u064e \u0671\u0644\u06e1\u0647\u0650\u064a\u0645\u0650",translation:"Maka kamu minum seperti unta (yang sangat haus) minum"},{id:56,text:"\u0647\u064e\u0670\u0630\u064e\u0627 \u0646\u064f\u0632\u064f\u0644\u064f\u0647\u064f\u0645\u06e1 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u0650",translation:"Itulah hidangan untuk mereka pada hari pembalasan"},{id:57,text:"\u0646\u064e\u062d\u06e1\u0646\u064f \u062e\u064e\u0644\u064e\u0642\u06e1\u0646\u064e\u0670\u0643\u064f\u0645\u06e1 \u0641\u064e\u0644\u064e\u0648\u06e1\u0644\u064e\u0627 \u062a\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u064f\u0648\u0646\u064e",translation:"Kami telah menciptakan kamu, mengapa kamu tidak membenarkan (hari berbangkit)"},{id:58,text:"\u0623\u064e\u0641\u064e\u0631\u064e\u0621\u064e\u064a\u06e1\u062a\u064f\u0645 \u0645\u0651\u064e\u0627 \u062a\u064f\u0645\u06e1\u0646\u064f\u0648\u0646\u064e",translation:"Maka adakah kamu perhatikan, tentang (benih manusia) yang kamu pancarkan"},{id:59,text:"\u0621\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u062e\u06e1\u0644\u064f\u0642\u064f\u0648\u0646\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u0645\u06e1 \u0646\u064e\u062d\u06e1\u0646\u064f \u0671\u0644\u06e1\u062e\u064e\u0670\u0644\u0650\u0642\u064f\u0648\u0646\u064e",translation:"Kamukah yang menciptakannya, ataukah Kami penciptanya"},{id:60,text:"\u0646\u064e\u062d\u06e1\u0646\u064f \u0642\u064e\u062f\u0651\u064e\u0631\u06e1\u0646\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u064e \u0648\u064e\u0645\u064e\u0627 \u0646\u064e\u062d\u06e1\u0646\u064f \u0628\u0650\u0645\u064e\u0633\u06e1\u0628\u064f\u0648\u0642\u0650\u064a\u0646\u064e",translation:"Kami telah menentukan kematian masing-masing kamu dan Kami tidak lemah"},{id:61,text:"\u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0646 \u0646\u0651\u064f\u0628\u064e\u062f\u0651\u0650\u0644\u064e \u0623\u064e\u0645\u06e1\u062b\u064e\u0670\u0644\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0646\u064f\u0646\u0634\u0650\u0626\u064e\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u0645\u064e\u0627 \u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"untuk menggantikan kamu dengan orang-orang yang seperti kamu (di dunia) dan membangkitkan kamu kelak (di akhirat) dalam keadaan yang tidak kamu ketahui"},{id:62,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0639\u064e\u0644\u0650\u0645\u06e1\u062a\u064f\u0645\u064f \u0671\u0644\u0646\u0651\u064e\u0634\u06e1\u0623\u064e\u0629\u064e \u0671\u0644\u06e1\u0623\u064f\u0648\u0644\u064e\u0649\u0670 \u0641\u064e\u0644\u064e\u0648\u06e1\u0644\u064e\u0627 \u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan sungguh, kamu telah tahu penciptaan yang pertama, mengapa kamu tidak mengambil pelajaran"},{id:63,text:"\u0623\u064e\u0641\u064e\u0631\u064e\u0621\u064e\u064a\u06e1\u062a\u064f\u0645 \u0645\u0651\u064e\u0627 \u062a\u064e\u062d\u06e1\u0631\u064f\u062b\u064f\u0648\u0646\u064e",translation:"Pernahkah kamu perhatikan benih yang kamu tanam"},{id:64,text:"\u0621\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0632\u06e1\u0631\u064e\u0639\u064f\u0648\u0646\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u0645\u06e1 \u0646\u064e\u062d\u06e1\u0646\u064f \u0671\u0644\u0632\u0651\u064e\u0640\u0670\u0631\u0650\u0639\u064f\u0648\u0646\u064e",translation:"Kamukah yang menumbuhkannya ataukah Kami yang menumbuhkan"},{id:65,text:"\u0644\u064e\u0648\u06e1 \u0646\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0644\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f \u062d\u064f\u0637\u064e\u0670\u0645\u0657\u0627 \u0641\u064e\u0638\u064e\u0644\u06e1\u062a\u064f\u0645\u06e1 \u062a\u064e\u0641\u064e\u0643\u0651\u064e\u0647\u064f\u0648\u0646\u064e",translation:"Sekiranya Kami kehendaki, niscaya Kami hancurkan sampai lumat; maka kamu akan heran tercengang"},{id:66,text:"\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0645\u064f\u063a\u06e1\u0631\u064e\u0645\u064f\u0648\u0646\u064e",translation:"(sambil berkata), \"Sungguh, kami benar-benar menderita kerugian"},{id:67,text:"\u0628\u064e\u0644\u06e1 \u0646\u064e\u062d\u06e1\u0646\u064f \u0645\u064e\u062d\u06e1\u0631\u064f\u0648\u0645\u064f\u0648\u0646\u064e",translation:"bahkan kami tidak mendapat hasil apa pun"},{id:68,text:"\u0623\u064e\u0641\u064e\u0631\u064e\u0621\u064e\u064a\u06e1\u062a\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062a\u064e\u0634\u06e1\u0631\u064e\u0628\u064f\u0648\u0646\u064e",translation:"Pernahkah kamu memperhatikan air yang kamu minum"},{id:69,text:"\u0621\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u062a\u064f\u0645\u064f\u0648\u0647\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0632\u06e1\u0646\u0650 \u0623\u064e\u0645\u06e1 \u0646\u064e\u062d\u06e1\u0646\u064f \u0671\u0644\u06e1\u0645\u064f\u0646\u0632\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Kamukah yang menurunkannya dari awan ataukah Kami yang menurunkan"},{id:70,text:"\u0644\u064e\u0648\u06e1 \u0646\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f \u0623\u064f\u062c\u064e\u0627\u062c\u0657\u0627 \u0641\u064e\u0644\u064e\u0648\u06e1\u0644\u064e\u0627 \u062a\u064e\u0634\u06e1\u0643\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Sekiranya Kami menghendaki, niscaya Kami menjadikannya asin, mengapa kamu tidak bersyukur"},{id:71,text:"\u0623\u064e\u0641\u064e\u0631\u064e\u0621\u064e\u064a\u06e1\u062a\u064f\u0645\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u064e \u0671\u0644\u0651\u064e\u062a\u0650\u064a \u062a\u064f\u0648\u0631\u064f\u0648\u0646\u064e",translation:"Maka pernahkah kamu memperhatikan tentang api yang kamu nyalakan (dengan kayu)"},{id:72,text:"\u0621\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0623\u064e\u0646\u0634\u064e\u0623\u06e1\u062a\u064f\u0645\u06e1 \u0634\u064e\u062c\u064e\u0631\u064e\u062a\u064e\u0647\u064e\u0627\u0653 \u0623\u064e\u0645\u06e1 \u0646\u064e\u062d\u06e1\u0646\u064f \u0671\u0644\u06e1\u0645\u064f\u0646\u0634\u0650\u0640\u0654\u064f\u0648\u0646\u064e",translation:"Kamukah yang menumbuhkan kayu itu ataukah Kami yang menumbuhkan"},{id:73,text:"\u0646\u064e\u062d\u06e1\u0646\u064f \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064e\u0627 \u062a\u064e\u0630\u06e1\u0643\u0650\u0631\u064e\u0629\u0657 \u0648\u064e\u0645\u064e\u062a\u064e\u0670\u0639\u0657\u0627 \u0644\u0651\u0650\u0644\u06e1\u0645\u064f\u0642\u06e1\u0648\u0650\u064a\u0646\u064e",translation:"Kami menjadikannya (api itu) untuk peringatan dan bahan yang berguna bagi musafir"},{id:74,text:"\u0641\u064e\u0633\u064e\u0628\u0651\u0650\u062d\u06e1 \u0628\u0650\u0671\u0633\u06e1\u0645\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0671\u0644\u06e1\u0639\u064e\u0638\u0650\u064a\u0645\u0650",translation:"Maka bertasbihlah dengan (menyebut) nama Tuhanmu Yang Mahabesar"},{id:75,text:"\u06de\u0641\u064e\u0644\u064e\u0627\u0653 \u0623\u064f\u0642\u06e1\u0633\u0650\u0645\u064f \u0628\u0650\u0645\u064e\u0648\u064e\u0670\u0642\u0650\u0639\u0650 \u0671\u0644\u0646\u0651\u064f\u062c\u064f\u0648\u0645\u0650",translation:"Lalu Aku bersumpah dengan tempat beredarnya bintang-bintang"},{id:76,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0642\u064e\u0633\u064e\u0645\u065e \u0644\u0651\u064e\u0648\u06e1 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0639\u064e\u0638\u0650\u064a\u0645\u064c",translation:"Dan sesungguhnya itu benar-benar sumpah yang besar sekiranya kamu mengetahui"},{id:77,text:"\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u065e \u0643\u064e\u0631\u0650\u064a\u0645\u065e",translation:"dan (ini) sesungguhnya Alquran yang sangat mulia"},{id:78,text:"\u0641\u0650\u064a \u0643\u0650\u062a\u064e\u0670\u0628\u0656 \u0645\u0651\u064e\u0643\u06e1\u0646\u064f\u0648\u0646\u0656",translation:"dalam Kitab yang terpelihara (Lau\u1e25 Ma\u1e25f\u016b\u1e93)"},{id:79,text:"\u0644\u0651\u064e\u0627 \u064a\u064e\u0645\u064e\u0633\u0651\u064f\u0647\u064f\u06e5\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u06e1\u0645\u064f\u0637\u064e\u0647\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"tidak ada yang menyentuhnya selain hamba-hamba yang disucikan"},{id:80,text:"\u062a\u064e\u0646\u0632\u0650\u064a\u0644\u065e \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Diturunkan dari Tuhan seluruh alam"},{id:81,text:"\u0623\u064e\u0641\u064e\u0628\u0650\u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u06e1\u062d\u064e\u062f\u0650\u064a\u062b\u0650 \u0623\u064e\u0646\u062a\u064f\u0645 \u0645\u0651\u064f\u062f\u06e1\u0647\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Apakah kamu menganggap remeh berita ini (Alquran)"},{id:82,text:"\u0648\u064e\u062a\u064e\u062c\u06e1\u0639\u064e\u0644\u064f\u0648\u0646\u064e \u0631\u0650\u0632\u06e1\u0642\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f\u0648\u0646\u064e",translation:"dan kamu menjadikan rezeki yang kamu terima (dari Allah) justru untuk mendustakan(-Nya)"},{id:83,text:"\u0641\u064e\u0644\u064e\u0648\u06e1\u0644\u064e\u0627\u0653 \u0625\u0650\u0630\u064e\u0627 \u0628\u064e\u0644\u064e\u063a\u064e\u062a\u0650 \u0671\u0644\u06e1\u062d\u064f\u0644\u06e1\u0642\u064f\u0648\u0645\u064e",translation:"Maka kalau begitu mengapa (tidak mencegah) ketika (nyawa) telah sampai di kerongkongan"},{id:84,text:"\u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u062d\u0650\u064a\u0646\u064e\u0626\u0650\u0630\u0656 \u062a\u064e\u0646\u0638\u064f\u0631\u064f\u0648\u0646\u064e",translation:"dan kamu ketika itu melihat"},{id:85,text:"\u0648\u064e\u0646\u064e\u062d\u06e1\u0646\u064f \u0623\u064e\u0642\u06e1\u0631\u064e\u0628\u064f \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u0644\u0651\u064e\u0627 \u062a\u064f\u0628\u06e1\u0635\u0650\u0631\u064f\u0648\u0646\u064e",translation:"dan Kami lebih dekat kepadanya daripada kamu, tetapi kamu tidak melihat"},{id:86,text:"\u0641\u064e\u0644\u064e\u0648\u06e1\u0644\u064e\u0627\u0653 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u063a\u064e\u064a\u06e1\u0631\u064e \u0645\u064e\u062f\u0650\u064a\u0646\u0650\u064a\u0646\u064e",translation:"maka mengapa jika kamu memang tidak dikuasai (oleh Allah)"},{id:87,text:"\u062a\u064e\u0631\u06e1\u062c\u0650\u0639\u064f\u0648\u0646\u064e\u0647\u064e\u0627\u0653 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0635\u064e\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e",translation:"kamu tidak mengembalikannya (nyawa itu) jika kamu orang yang benar"},{id:88,text:"\u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627\u0653 \u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0642\u064e\u0631\u0651\u064e\u0628\u0650\u064a\u0646\u064e",translation:"Jika dia (orang yang mati) itu termasuk yang didekatkan (kepada Allah)"},{id:89,text:"\u0641\u064e\u0631\u064e\u0648\u06e1\u062d\u065e \u0648\u064e\u0631\u064e\u064a\u06e1\u062d\u064e\u0627\u0646\u065e \u0648\u064e\u062c\u064e\u0646\u0651\u064e\u062a\u064f \u0646\u064e\u0639\u0650\u064a\u0645\u0656",translation:"maka dia memperoleh ketenteraman dan rezeki serta surga (yang penuh) kenikmatan"},{id:90,text:"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627\u0653 \u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u06e1 \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u0650 \u0671\u0644\u06e1\u064a\u064e\u0645\u0650\u064a\u0646\u0650",translation:"Dan jika dia termasuk golongan kanan"},{id:91,text:"\u0641\u064e\u0633\u064e\u0644\u064e\u0670\u0645\u065e \u0644\u0651\u064e\u0643\u064e \u0645\u0650\u0646\u06e1 \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u0650 \u0671\u0644\u06e1\u064a\u064e\u0645\u0650\u064a\u0646\u0650",translation:"maka, \"Salam bagimu (wahai) dari golongan kanan!\" (sambut malaikat)"},{id:92,text:"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627\u0653 \u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u0650\u064a\u0646\u064e \u0671\u0644\u0636\u0651\u064e\u0627\u0653\u0644\u0651\u0650\u064a\u0646\u064e",translation:"Namun jika dia termasuk golongan yang mendustakan dan sesat"},{id:93,text:"\u0641\u064e\u0646\u064f\u0632\u064f\u0644\u065e \u0645\u0651\u0650\u0646\u06e1 \u062d\u064e\u0645\u0650\u064a\u0645\u0656",translation:"maka dia disambut siraman air yang mendidih"},{id:94,text:"\u0648\u064e\u062a\u064e\u0635\u06e1\u0644\u0650\u064a\u064e\u0629\u064f \u062c\u064e\u062d\u0650\u064a\u0645\u064d",translation:"dan dibakar di dalam neraka"},{id:95,text:"\u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0644\u064e\u0647\u064f\u0648\u064e \u062d\u064e\u0642\u0651\u064f \u0671\u0644\u06e1\u064a\u064e\u0642\u0650\u064a\u0646\u0650",translation:"Sungguh, inilah keyakinan yang benar"},{id:96,text:"\u0641\u064e\u0633\u064e\u0628\u0651\u0650\u062d\u06e1 \u0628\u0650\u0671\u0633\u06e1\u0645\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0671\u0644\u06e1\u0639\u064e\u0638\u0650\u064a\u0645\u0650",translation:"Maka bertasbihlah dengan (menyebut) nama Tuhanmu Yang Mahabesar"}]},{id:57,name:"\u0627\u0644\u062d\u062f\u064a\u062f",transliteration:"Al-Hadid",translation:"Besi",type:"medinan",total_verses:29,verses:[{id:1,text:"\u0633\u064e\u0628\u0651\u064e\u062d\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0671\u0644\u06e1\u062d\u064e\u0643\u0650\u064a\u0645\u064f",translation:"Apa yang di langit dan di bumi bertasbih kepada Allah. Dialah Yang Mahaperkasa, Mahabijaksana"},{id:2,text:"\u0644\u064e\u0647\u064f\u06e5 \u0645\u064f\u0644\u06e1\u0643\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d6 \u064a\u064f\u062d\u06e1\u064a\u0650\u06e6 \u0648\u064e\u064a\u064f\u0645\u0650\u064a\u062a\u064f\u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0642\u064e\u062f\u0650\u064a\u0631\u064c",translation:"Milik-Nyalah kerajaan langit dan bumi, Dia menghidupkan dan mematikan, dan Dia Mahakuasa atas segala sesuatu"},{id:3,text:"\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0623\u064e\u0648\u0651\u064e\u0644\u064f \u0648\u064e\u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064f \u0648\u064e\u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0647\u0650\u0631\u064f \u0648\u064e\u0671\u0644\u06e1\u0628\u064e\u0627\u0637\u0650\u0646\u064f\u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u064c",translation:"(Dialah Yang Awal, Yang Akhir, Yang Zahir dan Yang Batin;830) dan Dia Maha Mengetahui segala sesuatu"},{id:4,text:"\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0641\u0650\u064a \u0633\u0650\u062a\u0651\u064e\u0629\u0650 \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u0656 \u062b\u064f\u0645\u0651\u064e \u0671\u0633\u06e1\u062a\u064e\u0648\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0639\u064e\u0631\u06e1\u0634\u0650\u06d6 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u064a\u064e\u0644\u0650\u062c\u064f \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u062e\u06e1\u0631\u064f\u062c\u064f \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0646\u0632\u0650\u0644\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0639\u06e1\u0631\u064f\u062c\u064f \u0641\u0650\u064a\u0647\u064e\u0627\u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0645\u064e\u0639\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u064a\u06e1\u0646\u064e \u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0628\u064e\u0635\u0650\u064a\u0631\u065e",translation:"(Dialah yang menciptakan langit dan bumi dalam enam masa; kemudian Dia bersemayam di atas Arasy. Dia mengetahui apa yang masuk ke dalam bumi dan apa yang keluar dari dalamnya, apa yang turun dari langit dan apa yang naik ke sana .831) Dan Dia bersama kamu di mana saja kamu berada. Dan Allah Maha Melihat apa yang kamu kerjakan"},{id:5,text:"\u0644\u0651\u064e\u0647\u064f\u06e5 \u0645\u064f\u0644\u06e1\u0643\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06da \u0648\u064e\u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064f\u0631\u06e1\u062c\u064e\u0639\u064f \u0671\u0644\u06e1\u0623\u064f\u0645\u064f\u0648\u0631\u064f",translation:"Milik-Nyalah kerajaan langit dan bumi. Dan hanya kepada Allah segala urusan dikembali\xadkan"},{id:6,text:"\u064a\u064f\u0648\u0644\u0650\u062c\u064f \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u064e \u0641\u0650\u064a \u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u0648\u064e\u064a\u064f\u0648\u0644\u0650\u062c\u064f \u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u0641\u0650\u064a \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u0650\u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u064f\u06e2 \u0628\u0650\u0630\u064e\u0627\u062a\u0650 \u0671\u0644\u0635\u0651\u064f\u062f\u064f\u0648\u0631\u0650",translation:"Dia memasukkan malam ke dalam siang dan memasukkan siang ke dalam malam. Dan Dia Maha Mengetahui segala isi hati"},{id:7,text:"\u0621\u064e\u0627\u0645\u0650\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650\u06e6 \u0648\u064e\u0623\u064e\u0646\u0641\u0650\u0642\u064f\u0648\u0627\u0652 \u0645\u0650\u0645\u0651\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u064f\u0633\u06e1\u062a\u064e\u062e\u06e1\u0644\u064e\u0641\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u0650\u06d6 \u0641\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0646\u0641\u064e\u0642\u064f\u0648\u0627\u0652 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u062c\u06e1\u0631\u065e \u0643\u064e\u0628\u0650\u064a\u0631\u065e",translation:"Berimanlah kamu kepada Allah dan Rasul-Nya dan infakkanlah (di jalan Allah) sebagian dari harta yang Dia telah menjadikan kamu sebagai penguasanya (amanah). Maka orang-orang yang beriman di antara kamu dan menginfakkan (hartanya di jalan Allah) memperoleh pahala yang besar"},{id:8,text:"\u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0644\u064e\u0627 \u062a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064f \u064a\u064e\u062f\u06e1\u0639\u064f\u0648\u0643\u064f\u0645\u06e1 \u0644\u0650\u062a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u062e\u064e\u0630\u064e \u0645\u0650\u064a\u062b\u064e\u0670\u0642\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645 \u0645\u0651\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dan mengapa kamu tidak beriman kepada Allah, padahal Rasul mengajak kamu beriman kepada Tuhanmu? Dan Dia telah mengambil janji (setia)mu, jika kamu orang-orang mukmin"},{id:9,text:"\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u0646\u064e\u0632\u0651\u0650\u0644\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0639\u064e\u0628\u06e1\u062f\u0650\u0647\u0650\u06e6\u0653 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u06ed \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0656 \u0644\u0651\u0650\u064a\u064f\u062e\u06e1\u0631\u0650\u062c\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0638\u0651\u064f\u0644\u064f\u0645\u064e\u0670\u062a\u0650 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0646\u0651\u064f\u0648\u0631\u0650\u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u0643\u064f\u0645\u06e1 \u0644\u064e\u0631\u064e\u0621\u064f\u0648\u0641\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u065e",translation:"Dialah yang menurunkan ayat-ayat yang terang (Alquran) kepada hamba-Nya (Muhammad) untuk mengeluarkan kamu dari kegelapan kepada cahaya. Dan sungguh, terhadap kamu Allah Maha Penyantun, Maha Penyayang"},{id:10,text:"\u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064f\u0646\u0641\u0650\u0642\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u064a\u0631\u064e\u0670\u062b\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06da \u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0648\u0650\u064a \u0645\u0650\u0646\u0643\u064f\u0645 \u0645\u0651\u064e\u0646\u06e1 \u0623\u064e\u0646\u0641\u064e\u0642\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650 \u0671\u0644\u06e1\u0641\u064e\u062a\u06e1\u062d\u0650 \u0648\u064e\u0642\u064e\u0670\u062a\u064e\u0644\u064e\u06da \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0623\u064e\u0639\u06e1\u0638\u064e\u0645\u064f \u062f\u064e\u0631\u064e\u062c\u064e\u0629\u0657 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u0646\u0641\u064e\u0642\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u064f \u0648\u064e\u0642\u064e\u0670\u062a\u064e\u0644\u064f\u0648\u0627\u0652\u06da \u0648\u064e\u0643\u064f\u0644\u0651\u0657\u0627 \u0648\u064e\u0639\u064e\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u062d\u064f\u0633\u06e1\u0646\u064e\u0649\u0670\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u062e\u064e\u0628\u0650\u064a\u0631\u065e",translation:"Dan mengapa kamu tidak menginfakkan hartamu di jalan Allah, padahal milik Allah semua pusaka langit dan bumi? Tidak sama orang yang menginfakkan (hartanya di jalan Allah) di antara kamu dan berperang sebelum penaklukan (Mekkah). Mereka lebih tinggi derajatnya daripada orang-orang yang menginfakkan (hartanya) dan berperang setelah itu. Dan Allah menjanjikan kepada masing-masing mereka (balasan) yang lebih baik. Dan Allah Mahateliti atas apa yang kamu kerjakan"},{id:11,text:"\u0645\u0651\u064e\u0646 \u0630\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u0642\u06e1\u0631\u0650\u0636\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0642\u064e\u0631\u06e1\u0636\u064b\u0627 \u062d\u064e\u0633\u064e\u0646\u0657\u0627 \u0641\u064e\u064a\u064f\u0636\u064e\u0670\u0639\u0650\u0641\u064e\u0647\u064f\u06e5 \u0644\u064e\u0647\u064f\u06e5 \u0648\u064e\u0644\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u062c\u06e1\u0631\u065e \u0643\u064e\u0631\u0650\u064a\u0645\u065e",translation:"Barangsiapa meminjamkan kepada Allah dengan pinjaman yang baik, maka Allah akan mengembalikannya berlipat ganda untuknya, dan baginya pahala yang mulia"},{id:12,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u062a\u064e\u0631\u064e\u0649 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064e\u0670\u062a\u0650 \u064a\u064e\u0633\u06e1\u0639\u064e\u0649\u0670 \u0646\u064f\u0648\u0631\u064f\u0647\u064f\u0645 \u0628\u064e\u064a\u06e1\u0646\u064e \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u0647\u0650\u0645\u06e1 \u0648\u064e\u0628\u0650\u0623\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u0650\u0647\u0650\u0645\u06d6 \u0628\u064f\u0634\u06e1\u0631\u064e\u0649\u0670\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u065e \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0645\u0650\u0646 \u062a\u064e\u062d\u06e1\u062a\u0650\u0647\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u064f \u062e\u064e\u0670\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0641\u064e\u0648\u06e1\u0632\u064f \u0671\u0644\u06e1\u0639\u064e\u0638\u0650\u064a\u0645\u064f",translation:"pada hari engkau akan melihat orang-orang yang beriman laki-laki dan perempuan, betapa cahaya mereka bersinar di depan dan di samping kanan mereka, (dikatakan kepada mereka), \"Pada hari ini ada berita gembira untukmu, (yaitu) surga-surga yang mengalir di bawahnya sungai-sungai, mereka kekal di dalamnya. Demikianlah kemenangan yang agung"},{id:13,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0671\u0644\u06e1\u0645\u064f\u0646\u064e\u0670\u0641\u0650\u0642\u064f\u0648\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0646\u064e\u0670\u0641\u0650\u0642\u064e\u0670\u062a\u064f \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0671\u0646\u0638\u064f\u0631\u064f\u0648\u0646\u064e\u0627 \u0646\u064e\u0642\u06e1\u062a\u064e\u0628\u0650\u0633\u06e1 \u0645\u0650\u0646 \u0646\u0651\u064f\u0648\u0631\u0650\u0643\u064f\u0645\u06e1 \u0642\u0650\u064a\u0644\u064e \u0671\u0631\u06e1\u062c\u0650\u0639\u064f\u0648\u0627\u0652 \u0648\u064e\u0631\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u06e1 \u0641\u064e\u0671\u0644\u06e1\u062a\u064e\u0645\u0650\u0633\u064f\u0648\u0627\u0652 \u0646\u064f\u0648\u0631\u0657\u0627\u06d6 \u0641\u064e\u0636\u064f\u0631\u0650\u0628\u064e \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645 \u0628\u0650\u0633\u064f\u0648\u0631\u0656 \u0644\u0651\u064e\u0647\u064f\u06e5 \u0628\u064e\u0627\u0628\u064f\u06e2 \u0628\u064e\u0627\u0637\u0650\u0646\u064f\u0647\u064f\u06e5 \u0641\u0650\u064a\u0647\u0650 \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0629\u064f \u0648\u064e\u0638\u064e\u0670\u0647\u0650\u0631\u064f\u0647\u064f\u06e5 \u0645\u0650\u0646 \u0642\u0650\u0628\u064e\u0644\u0650\u0647\u0650 \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064f",translation:"Pada hari orang-orang munafik laki-laki dan perempuan berkata kepada orang-orang yang beriman, \"Tunggulah kami! Kami ingin mengambil cahayamu.\" (Kepada mereka) dikatakan, \"Kembalilah kamu ke belakang dan carilah sendiri cahaya (untukmu).\" Lalu di antara mereka dipasang dinding (pemisah) yang berpintu. Di bagian dalam ada rahmat dan di luarnya hanya ada azab"},{id:14,text:"\u064a\u064f\u0646\u064e\u0627\u062f\u064f\u0648\u0646\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u0644\u064e\u0645\u06e1 \u0646\u064e\u0643\u064f\u0646 \u0645\u0651\u064e\u0639\u064e\u0643\u064f\u0645\u06e1\u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0628\u064e\u0644\u064e\u0649\u0670 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0641\u064e\u062a\u064e\u0646\u062a\u064f\u0645\u06e1 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u062a\u064e\u0631\u064e\u0628\u0651\u064e\u0635\u06e1\u062a\u064f\u0645\u06e1 \u0648\u064e\u0671\u0631\u06e1\u062a\u064e\u0628\u06e1\u062a\u064f\u0645\u06e1 \u0648\u064e\u063a\u064e\u0631\u0651\u064e\u062a\u06e1\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u0645\u064e\u0627\u0646\u0650\u064a\u0651\u064f \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062c\u064e\u0627\u0653\u0621\u064e \u0623\u064e\u0645\u06e1\u0631\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u063a\u064e\u0631\u0651\u064e\u0643\u064f\u0645 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u063a\u064e\u0631\u064f\u0648\u0631\u064f",translation:"Orang-orang munafik memanggil orang-orang mukmin, \"Bukankah kami dahulu bersama kamu?\" Mereka menjawab, \"Benar, tetapi kamu mencelakakan dirimu sendiri, dan kamu hanya menunggu, meragukan (janji Allah) dan ditipu oleh angan-angan kosong sampai datang ketetapan Allah; dan penipu (setan) datang memperdaya kamu tentang Allah"},{id:15,text:"\u0641\u064e\u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u062e\u064e\u0630\u064f \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u0641\u0650\u062f\u06e1\u064a\u064e\u0629\u065e \u0648\u064e\u0644\u064e\u0627 \u0645\u0650\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652\u06da \u0645\u064e\u0623\u06e1\u0648\u064e\u0649\u0670\u0643\u064f\u0645\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u064f\u06d6 \u0647\u0650\u064a\u064e \u0645\u064e\u0648\u06e1\u0644\u064e\u0649\u0670\u0643\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0628\u0650\u0626\u06e1\u0633\u064e \u0671\u0644\u06e1\u0645\u064e\u0635\u0650\u064a\u0631\u064f",translation:"Maka pada hari ini tidak akan diterima tebusan dari kamu maupun dari orang-orang kafir. Tempat kamu di neraka. Itulah tempat berlindungmu, dan itulah seburuk-buruk tempat kembali"},{id:16,text:"\u06de\u0623\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0623\u06e1\u0646\u0650 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646 \u062a\u064e\u062e\u06e1\u0634\u064e\u0639\u064e \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u06e1 \u0644\u0650\u0630\u0650\u0643\u06e1\u0631\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u064e\u0627 \u0646\u064e\u0632\u064e\u0644\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u0643\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f \u0641\u064e\u0637\u064e\u0627\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u0645\u064e\u062f\u064f \u0641\u064e\u0642\u064e\u0633\u064e\u062a\u06e1 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0643\u064e\u062b\u0650\u064a\u0631\u065e \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0641\u064e\u0670\u0633\u0650\u0642\u064f\u0648\u0646\u064e",translation:"Belum tibakah waktunya bagi orang-orang yang beriman, untuk secara khusyuk mengingat Allah dan mematuhi kebenaran yang telah diwahyukan (kepada mereka), dan janganlah mereka (berlaku) seperti orang-orang yang telah menerima kitab sebelum itu, kemudian mereka melalui masa yang panjang sehingga hati mereka menjadi keras. Dan banyak di antara mereka menjadi orang-orang fasik"},{id:17,text:"\u0671\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u062d\u06e1\u064a\u0650 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0628\u064e\u0639\u06e1\u062f\u064e \u0645\u064e\u0648\u06e1\u062a\u0650\u0647\u064e\u0627\u06da \u0642\u064e\u062f\u06e1 \u0628\u064e\u064a\u0651\u064e\u0646\u0651\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0623\u0653\u064a\u064e\u0670\u062a\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Ketahuilah bahwa Allah yang menghidupkan bumi setelah matinya (kering). Sungguh, telah Kami jelaskan kepadamu tanda-tanda (kebesaran Kami) agar kamu mengerti"},{id:18,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0645\u064f\u0635\u0651\u064e\u062f\u0651\u0650\u0642\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0635\u0651\u064e\u062f\u0651\u0650\u0642\u064e\u0670\u062a\u0650 \u0648\u064e\u0623\u064e\u0642\u06e1\u0631\u064e\u0636\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0642\u064e\u0631\u06e1\u0636\u064b\u0627 \u062d\u064e\u0633\u064e\u0646\u0657\u0627 \u064a\u064f\u0636\u064e\u0670\u0639\u064e\u0641\u064f \u0644\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u062c\u06e1\u0631\u065e \u0643\u064e\u0631\u0650\u064a\u0645\u065e",translation:"Sesungguhnya orang-orang yang bersedekah baik laki-laki maupun perempuan dan meminjamkan kepada Allah dengan pinjaman yang baik, akan dilipatgandakan (balasannya) bagi mereka; dan mereka akan mendapat pahala yang mulia"},{id:19,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064f\u0633\u064f\u0644\u0650\u0647\u0650\u06e6\u0653 \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u0635\u0651\u0650\u062f\u0651\u0650\u064a\u0642\u064f\u0648\u0646\u064e\u06d6 \u0648\u064e\u0671\u0644\u0634\u0651\u064f\u0647\u064e\u062f\u064e\u0627\u0653\u0621\u064f \u0639\u0650\u0646\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u062c\u06e1\u0631\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0646\u064f\u0648\u0631\u064f\u0647\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627\u0653 \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u06e1\u062c\u064e\u062d\u0650\u064a\u0645\u0650",translation:"Dan orang-orang yang beriman kepada Allah dan rasul-rasul-Nya, mereka itu orang-orang yang tulus hati (pecinta kebenaran) dan saksi-saksi di sisi Tuhan mereka. Mereka berhak mendapat pahala dan cahaya. Tetapi orang-orang yang kafir dan mendustakan ayat-ayat Kami, mereka itu penghuni-penghuni neraka"},{id:20,text:"\u0671\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u064f \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0644\u064e\u0639\u0650\u0628\u065e \u0648\u064e\u0644\u064e\u0647\u06e1\u0648\u065e \u0648\u064e\u0632\u0650\u064a\u0646\u064e\u0629\u065e \u0648\u064e\u062a\u064e\u0641\u064e\u0627\u062e\u064f\u0631\u064f\u06e2 \u0628\u064e\u064a\u06e1\u0646\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u062a\u064e\u0643\u064e\u0627\u062b\u064f\u0631\u065e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0648\u06e1\u0644\u064e\u0670\u062f\u0650\u06d6 \u0643\u064e\u0645\u064e\u062b\u064e\u0644\u0650 \u063a\u064e\u064a\u06e1\u062b\u064d \u0623\u064e\u0639\u06e1\u062c\u064e\u0628\u064e \u0671\u0644\u06e1\u0643\u064f\u0641\u0651\u064e\u0627\u0631\u064e \u0646\u064e\u0628\u064e\u0627\u062a\u064f\u0647\u064f\u06e5 \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u0647\u0650\u064a\u062c\u064f \u0641\u064e\u062a\u064e\u0631\u064e\u0649\u0670\u0647\u064f \u0645\u064f\u0635\u06e1\u0641\u064e\u0631\u0651\u0657\u0627 \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u0643\u064f\u0648\u0646\u064f \u062d\u064f\u0637\u064e\u0670\u0645\u0657\u0627\u06d6 \u0648\u064e\u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0639\u064e\u0630\u064e\u0627\u0628\u065e \u0634\u064e\u062f\u0650\u064a\u062f\u065e \u0648\u064e\u0645\u064e\u063a\u06e1\u0641\u0650\u0631\u064e\u0629\u065e \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u0650\u0636\u06e1\u0648\u064e\u0670\u0646\u065e\u06da \u0648\u064e\u0645\u064e\u0627 \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u064f \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u062a\u064e\u0670\u0639\u064f \u0671\u0644\u06e1\u063a\u064f\u0631\u064f\u0648\u0631\u0650",translation:"Ketahuilah, sesungguhnya kehidupan dunia itu hanyalah permainan dan senda gurauan, perhiasan dan saling berbangga di antara kamu serta berlomba dalam kekayaan dan anak keturunan, seperti hujan yang tanam-tanamannya mengagumkan para petani; kemudian (tanaman) itu menjadi kering dan kamu lihat warnanya kuning kemudian menjadi hancur. Dan di akhirat (nanti) ada azab yang keras dan ampunan dari Allah serta keridaan-Nya. Dan kehidupan dunia tidak lain hanyalah kesenangan yang palsu"},{id:21,text:"\u0633\u064e\u0627\u0628\u0650\u0642\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064e\u063a\u06e1\u0641\u0650\u0631\u064e\u0629\u0656 \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u062c\u064e\u0646\u0651\u064e\u0629\u064d \u0639\u064e\u0631\u06e1\u0636\u064f\u0647\u064e\u0627 \u0643\u064e\u0639\u064e\u0631\u06e1\u0636\u0650 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0623\u064f\u0639\u0650\u062f\u0651\u064e\u062a\u06e1 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064f\u0633\u064f\u0644\u0650\u0647\u0650\u06e6\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u0636\u06e1\u0644\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064f\u0624\u06e1\u062a\u0650\u064a\u0647\u0650 \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0630\u064f\u0648 \u0671\u0644\u06e1\u0641\u064e\u0636\u06e1\u0644\u0650 \u0671\u0644\u06e1\u0639\u064e\u0638\u0650\u064a\u0645\u0650",translation:"Berlomba-lombalah kamu untuk mendapatkan ampunan dari Tuhanmu dan surga yang luasnya seluas langit dan bumi, yang disediakan bagi orang-orang yang beriman kepada Allah dan rasul-rasul-Nya. Itulah karunia Allah, yang diberikan kepada siapa yang Dia kehendaki. Dan Allah mempunyai karunia yang besar"},{id:22,text:"\u0645\u064e\u0627\u0653 \u0623\u064e\u0635\u064e\u0627\u0628\u064e \u0645\u0650\u0646 \u0645\u0651\u064f\u0635\u0650\u064a\u0628\u064e\u0629\u0656 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0644\u064e\u0627 \u0641\u0650\u064a\u0653 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u0641\u0650\u064a \u0643\u0650\u062a\u064e\u0670\u0628\u0656 \u0645\u0651\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650 \u0623\u064e\u0646 \u0646\u0651\u064e\u0628\u06e1\u0631\u064e\u0623\u064e\u0647\u064e\u0627\u0653\u06da \u0625\u0650\u0646\u0651\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u0633\u0650\u064a\u0631\u065e",translation:"Setiap bencana yang menimpa di bumi dan yang menimpa dirimu sendiri, semuanya telah tertulis dalam Kitab (Lau\u1e25 Ma\u1e25f\u016b\u1e93) sebelum Kami mewujudkannya. Sungguh, yang demikian itu mudah bagi Allah"},{id:23,text:"\u0644\u0651\u0650\u0643\u064e\u064a\u06e1\u0644\u064e\u0627 \u062a\u064e\u0623\u06e1\u0633\u064e\u0648\u06e1\u0627\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0641\u064e\u0627\u062a\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0641\u06e1\u0631\u064e\u062d\u064f\u0648\u0627\u0652 \u0628\u0650\u0645\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u064e\u0649\u0670\u0643\u064f\u0645\u06e1\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0643\u064f\u0644\u0651\u064e \u0645\u064f\u062e\u06e1\u062a\u064e\u0627\u0644\u0656 \u0641\u064e\u062e\u064f\u0648\u0631\u064d",translation:"Agar kamu tidak bersedih hati terhadap apa yang luput dari kamu, dan tidak pula terlalu gembira terhadap apa yang diberikan-Nya kepadamu. Dan Allah tidak menyukai setiap orang yang sombong dan membanggakan diri"},{id:24,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0628\u06e1\u062e\u064e\u0644\u064f\u0648\u0646\u064e \u0648\u064e\u064a\u064e\u0623\u06e1\u0645\u064f\u0631\u064f\u0648\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0628\u0650\u0671\u0644\u06e1\u0628\u064f\u062e\u06e1\u0644\u0650\u06d7 \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u063a\u064e\u0646\u0650\u064a\u0651\u064f \u0671\u0644\u06e1\u062d\u064e\u0645\u0650\u064a\u062f\u064f",translation:"yaitu orang-orang yang kikir dan menyuruh orang lain berbuat kikir. Barangsiapa berpaling (dari perintah-perintah Allah), maka sesungguhnya Allah, Dia Mahakaya, Maha Terpuji"},{id:25,text:"\u0644\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0631\u064f\u0633\u064f\u0644\u064e\u0646\u064e\u0627 \u0628\u0650\u0671\u0644\u06e1\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0650 \u0648\u064e\u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0627 \u0645\u064e\u0639\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0648\u064e\u0671\u0644\u06e1\u0645\u0650\u064a\u0632\u064e\u0627\u0646\u064e \u0644\u0650\u064a\u064e\u0642\u064f\u0648\u0645\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0628\u0650\u0671\u0644\u06e1\u0642\u0650\u0633\u06e1\u0637\u0650\u06d6 \u0648\u064e\u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u062d\u064e\u062f\u0650\u064a\u062f\u064e \u0641\u0650\u064a\u0647\u0650 \u0628\u064e\u0623\u06e1\u0633\u065e \u0634\u064e\u062f\u0650\u064a\u062f\u065e \u0648\u064e\u0645\u064e\u0646\u064e\u0670\u0641\u0650\u0639\u064f \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0644\u0650\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0646 \u064a\u064e\u0646\u0635\u064f\u0631\u064f\u0647\u064f\u06e5 \u0648\u064e\u0631\u064f\u0633\u064f\u0644\u064e\u0647\u064f\u06e5 \u0628\u0650\u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u0628\u0650\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0642\u064e\u0648\u0650\u064a\u0651\u064c \u0639\u064e\u0632\u0650\u064a\u0632\u065e",translation:"Sungguh, Kami telah mengutus rasul-rasul Kami dengan bukti-bukti yang nyata dan Kami turunkan bersama mereka Kitab dan neraca (keadilan) agar manusia dapat berlaku adil. Dan Kami menciptakan besi yang mempunyai kekuatan hebat dan banyak manfaat bagi manusia, dan agar Allah mengetahui siapa yang menolong (agama)-Nya dan rasul-rasul-Nya walaupun (Allah) tidak dilihatnya. Sesungguhnya Allah Mahakuat, Mahaperkasa"},{id:26,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0646\u064f\u0648\u062d\u0657\u0627 \u0648\u064e\u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064e \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a \u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u062a\u0650\u0647\u0650\u0645\u064e\u0627 \u0671\u0644\u0646\u0651\u064f\u0628\u064f\u0648\u0651\u064e\u0629\u064e \u0648\u064e\u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e\u06d6 \u0641\u064e\u0645\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064f\u0647\u06e1\u062a\u064e\u062f\u0656\u06d6 \u0648\u064e\u0643\u064e\u062b\u0650\u064a\u0631\u065e \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0641\u064e\u0670\u0633\u0650\u0642\u064f\u0648\u0646\u064e",translation:"Dan sungguh, Kami telah mengutus Nuh dan Ibrahim dan Kami berikan kenabian dan kitab (wahyu) kepada keturunan keduanya, di antara mereka ada yang menerima petunjuk dan banyak di antara mereka yang fasik"},{id:27,text:"\u062b\u064f\u0645\u0651\u064e \u0642\u064e\u0641\u0651\u064e\u064a\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0621\u064e\u0627\u062b\u064e\u0670\u0631\u0650\u0647\u0650\u0645 \u0628\u0650\u0631\u064f\u0633\u064f\u0644\u0650\u0646\u064e\u0627 \u0648\u064e\u0642\u064e\u0641\u0651\u064e\u064a\u06e1\u0646\u064e\u0627 \u0628\u0650\u0639\u0650\u064a\u0633\u064e\u0649 \u0671\u0628\u06e1\u0646\u0650 \u0645\u064e\u0631\u06e1\u064a\u064e\u0645\u064e \u0648\u064e\u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f \u0671\u0644\u06e1\u0625\u0650\u0646\u062c\u0650\u064a\u0644\u064e\u06d6 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0647\u064f \u0631\u064e\u0623\u06e1\u0641\u064e\u0629\u0657 \u0648\u064e\u0631\u064e\u062d\u06e1\u0645\u064e\u0629\u0657\u06da \u0648\u064e\u0631\u064e\u0647\u06e1\u0628\u064e\u0627\u0646\u0650\u064a\u0651\u064e\u0629\u064b \u0671\u0628\u06e1\u062a\u064e\u062f\u064e\u0639\u064f\u0648\u0647\u064e\u0627 \u0645\u064e\u0627 \u0643\u064e\u062a\u064e\u0628\u06e1\u0646\u064e\u0670\u0647\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0628\u06e1\u062a\u0650\u063a\u064e\u0627\u0653\u0621\u064e \u0631\u0650\u0636\u06e1\u0648\u064e\u0670\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0645\u064e\u0627 \u0631\u064e\u0639\u064e\u0648\u06e1\u0647\u064e\u0627 \u062d\u064e\u0642\u0651\u064e \u0631\u0650\u0639\u064e\u0627\u064a\u064e\u062a\u0650\u0647\u064e\u0627\u06d6 \u0641\u064e\u0640\u0654\u064e\u0627\u062a\u064e\u064a\u06e1\u0646\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0623\u064e\u062c\u06e1\u0631\u064e\u0647\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0643\u064e\u062b\u0650\u064a\u0631\u065e \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0641\u064e\u0670\u0633\u0650\u0642\u064f\u0648\u0646\u064e",translation:"Kemudian Kami susulkan rasul-rasul Kami mengikuti jejak mereka dan Kami susulkan (pula) Isa putra Maryam; Dan Kami berikan Injil kepadanya dan Kami jadikan rasa santun dan kasih sayang dalam hati orang-orang yang mengikutinya. Mereka mengada-adakan ra\u1e25b\u0101niyyah,832) padahal Kami tidak mewajibkannya kepada mereka (yang Kami wajibkan hanyalah) mencari keridaan Allah, tetapi tidak mereka pelihara dengan semestinya. Maka kepada orang-orang yang beriman di antara mereka Kami berikan pahalanya, dan banyak di antara mereka yang fasik"},{id:28,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0621\u064e\u0627\u0645\u0650\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650\u06e6 \u064a\u064f\u0624\u06e1\u062a\u0650\u0643\u064f\u0645\u06e1 \u0643\u0650\u0641\u06e1\u0644\u064e\u064a\u06e1\u0646\u0650 \u0645\u0650\u0646 \u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u062a\u0650\u0647\u0650\u06e6 \u0648\u064e\u064a\u064e\u062c\u06e1\u0639\u064e\u0644 \u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u0646\u064f\u0648\u0631\u0657\u0627 \u062a\u064e\u0645\u06e1\u0634\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u0650\u06e6 \u0648\u064e\u064a\u064e\u063a\u06e1\u0641\u0650\u0631\u06e1 \u0644\u064e\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u065e",translation:"Wahai orang-orang yang beriman! Bertakwalah kepada Allah dan berimanlah kepada Rasul-Nya (Muhammad), niscaya Allah memberikan rahmat-Nya kepada dua bagian, dan menjadikan cahaya untukmu yang dengan cahaya itu kamu dapat berjalan serta Dia mengampuni kamu. Dan Allah Maha Pengampun, Maha Penyayang"},{id:29,text:"\u0644\u0651\u0650\u0626\u064e\u0644\u0651\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064e \u0623\u064e\u0647\u06e1\u0644\u064f \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0623\u064e\u0644\u0651\u064e\u0627 \u064a\u064e\u0642\u06e1\u062f\u0650\u0631\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0645\u0651\u0650\u0646 \u0641\u064e\u0636\u06e1\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0671\u0644\u06e1\u0641\u064e\u0636\u06e1\u0644\u064e \u0628\u0650\u064a\u064e\u062f\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064f\u0624\u06e1\u062a\u0650\u064a\u0647\u0650 \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0630\u064f\u0648 \u0671\u0644\u06e1\u0641\u064e\u0636\u06e1\u0644\u0650 \u0671\u0644\u06e1\u0639\u064e\u0638\u0650\u064a\u0645\u0650",translation:"agar Ahli Kitab mengetahui bahwa sedikit pun mereka tidak akan mendapat karunia Allah (jika mereka tidak beriman kepada Muhammad), dan bahwa karunia itu ada di tangan Allah, Dia memberikannya kepada siapa yang Dia kehendaki. Dan Allah mempunyai karunia yang besar"}]},{id:58,name:"\u0627\u0644\u0645\u062c\u0627\u062f\u0644\u0629",transliteration:"Al-Mujadila",translation:"Wanita yang Menggugat",type:"medinan",total_verses:22,verses:[{id:1,text:"\u0642\u064e\u062f\u06e1 \u0633\u064e\u0645\u0650\u0639\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0642\u064e\u0648\u06e1\u0644\u064e \u0671\u0644\u0651\u064e\u062a\u0650\u064a \u062a\u064f\u062c\u064e\u0670\u062f\u0650\u0644\u064f\u0643\u064e \u0641\u0650\u064a \u0632\u064e\u0648\u06e1\u062c\u0650\u0647\u064e\u0627 \u0648\u064e\u062a\u064e\u0634\u06e1\u062a\u064e\u0643\u0650\u064a\u0653 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0633\u06e1\u0645\u064e\u0639\u064f \u062a\u064e\u062d\u064e\u0627\u0648\u064f\u0631\u064e\u0643\u064f\u0645\u064e\u0627\u0653\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0633\u064e\u0645\u0650\u064a\u0639\u064f\u06e2 \u0628\u064e\u0635\u0650\u064a\u0631\u064c",translation:"Sungguh, Allah telah mendengar ucapan perempuan yang mengajukan gugatan kepadamu (Muhammad) tentang suaminya, dan mengadukan (halnya) kepada Allah, dan Allah mendengar percakapan antara kamu berdua. Sesungguhnya Allah Maha Mendengar, Maha Melihat"},{id:2,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0638\u064e\u0670\u0647\u0650\u0631\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0646\u0651\u0650\u0633\u064e\u0627\u0653\u0626\u0650\u0647\u0650\u0645 \u0645\u0651\u064e\u0627 \u0647\u064f\u0646\u0651\u064e \u0623\u064f\u0645\u0651\u064e\u0647\u064e\u0670\u062a\u0650\u0647\u0650\u0645\u06e1\u06d6 \u0625\u0650\u0646\u06e1 \u0623\u064f\u0645\u0651\u064e\u0647\u064e\u0670\u062a\u064f\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0640\u0670\u0653\u0640\u0654\u0650\u064a \u0648\u064e\u0644\u064e\u062f\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1\u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0645\u064f\u0646\u0643\u064e\u0631\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0644\u0650 \u0648\u064e\u0632\u064f\u0648\u0631\u0657\u0627\u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0639\u064e\u0641\u064f\u0648\u0651\u064c \u063a\u064e\u0641\u064f\u0648\u0631\u065e",translation:"Orang-orang di antara kamu yang menzihar istrinya, (menganggap istrinya sebagai ibunya, padahal) istri mereka itu bukanlah ibunya. Ibu-ibu mereka hanyalah perempuan yang melahirkannya. Dan sesungguhnya mereka benar-benar telah mengucapkan suatu perkataan yang mungkar dan dusta. Dan sesungguhnya Allah Maha Pemaaf, Maha Pengampun"},{id:3,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0638\u064e\u0670\u0647\u0650\u0631\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u0646\u0651\u0650\u0633\u064e\u0627\u0653\u0626\u0650\u0647\u0650\u0645\u06e1 \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u0639\u064f\u0648\u062f\u064f\u0648\u0646\u064e \u0644\u0650\u0645\u064e\u0627 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0641\u064e\u062a\u064e\u062d\u06e1\u0631\u0650\u064a\u0631\u064f \u0631\u064e\u0642\u064e\u0628\u064e\u0629\u0656 \u0645\u0651\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650 \u0623\u064e\u0646 \u064a\u064e\u062a\u064e\u0645\u064e\u0627\u0653\u0633\u0651\u064e\u0627\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u06e1 \u062a\u064f\u0648\u0639\u064e\u0638\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u0650\u06e6\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u062e\u064e\u0628\u0650\u064a\u0631\u065e",translation:"Dan mereka yang menzihar istrinya, kemudian menarik kembali apa yang telah mereka ucapkan, maka (mereka diwajibkan) memerdekakan seorang budak sebelum kedua suami istri itu bercampur. Demikianlah yang diajarkan kepadamu, dan Allah Mahateliti atas apa yang kamu kerjakan"},{id:4,text:"\u0641\u064e\u0645\u064e\u0646 \u0644\u0651\u064e\u0645\u06e1 \u064a\u064e\u062c\u0650\u062f\u06e1 \u0641\u064e\u0635\u0650\u064a\u064e\u0627\u0645\u064f \u0634\u064e\u0647\u06e1\u0631\u064e\u064a\u06e1\u0646\u0650 \u0645\u064f\u062a\u064e\u062a\u064e\u0627\u0628\u0650\u0639\u064e\u064a\u06e1\u0646\u0650 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650 \u0623\u064e\u0646 \u064a\u064e\u062a\u064e\u0645\u064e\u0627\u0653\u0633\u0651\u064e\u0627\u06d6 \u0641\u064e\u0645\u064e\u0646 \u0644\u0651\u064e\u0645\u06e1 \u064a\u064e\u0633\u06e1\u062a\u064e\u0637\u0650\u0639\u06e1 \u0641\u064e\u0625\u0650\u0637\u06e1\u0639\u064e\u0627\u0645\u064f \u0633\u0650\u062a\u0651\u0650\u064a\u0646\u064e \u0645\u0650\u0633\u06e1\u0643\u0650\u064a\u0646\u0657\u0627\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u0650\u062a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650\u06e6\u06da \u0648\u064e\u062a\u0650\u0644\u06e1\u0643\u064e \u062d\u064f\u062f\u064f\u0648\u062f\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d7 \u0648\u064e\u0644\u0650\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064c",translation:"Maka barangsiapa tidak dapat (memerdekakan hamba sahaya), maka (dia wajib) berpuasa dua bulan berturut-turut sebelum keduanya bercampur. Tetapi barangsiapa tidak mampu, maka (wajib) memberi makan enam puluh orang miskin. Demikianlah agar kamu beriman kepada Allah dan Rasul-Nya. Itulah hukum-hukum Allah, dan bagi orang-orang yang mengingkarinya akan mendapat azab yang sangat pedih"},{id:5,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u062d\u064e\u0627\u0653\u062f\u0651\u064f\u0648\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f\u06e5 \u0643\u064f\u0628\u0650\u062a\u064f\u0648\u0627\u0652 \u0643\u064e\u0645\u064e\u0627 \u0643\u064f\u0628\u0650\u062a\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u0645\u06e1\u06da \u0648\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0627\u0653 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u06ed \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0656\u06da \u0648\u064e\u0644\u0650\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u065e \u0645\u0651\u064f\u0647\u0650\u064a\u0646\u065e",translation:"Sesungguhnya orang-orang yang menentang Allah dan Rasul-Nya pasti mendapat kehinaan sebagaimana kehinaan yang telah didapat oleh orang-orang sebelum mereka. Dan sungguh, kami telah menurunkan bukti-bukti yang nyata. Dan bagi orang-orang yang mengingkarinya akan mendapat azab yang menghinakan"},{id:6,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064e\u0628\u06e1\u0639\u064e\u062b\u064f\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u062c\u064e\u0645\u0650\u064a\u0639\u0657\u0627 \u0641\u064e\u064a\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0647\u064f\u0645 \u0628\u0650\u0645\u064e\u0627 \u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0653\u0627\u0652\u06da \u0623\u064e\u062d\u06e1\u0635\u064e\u0649\u0670\u0647\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0646\u064e\u0633\u064f\u0648\u0647\u064f\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0634\u064e\u0647\u0650\u064a\u062f\u064c",translation:"Pada hari itu mereka semuanya dibangkitkan Allah, lalu diberitakan-Nya kepada mereka apa yang telah mereka kerjakan. Allah menghitungnya (semua amal perbuatan itu), meskipun mereka telah melupakannya. Dan Allah Maha Menyaksikan segala sesuatu"},{id:7,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0631\u064e \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d6 \u0645\u064e\u0627 \u064a\u064e\u0643\u064f\u0648\u0646\u064f \u0645\u0650\u0646 \u0646\u0651\u064e\u062c\u06e1\u0648\u064e\u0649\u0670 \u062b\u064e\u0644\u064e\u0670\u062b\u064e\u0629\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u0631\u064e\u0627\u0628\u0650\u0639\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u062e\u064e\u0645\u06e1\u0633\u064e\u0629\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u0633\u064e\u0627\u062f\u0650\u0633\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064e\u062f\u06e1\u0646\u064e\u0649\u0670 \u0645\u0650\u0646 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u0645\u064e\u0639\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u064a\u06e1\u0646\u064e \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652\u06d6 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0647\u064f\u0645 \u0628\u0650\u0645\u064e\u0627 \u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u064c",translation:"Tidakkah engkau perhatikan, bahwa Allah mengetahui apa yang ada di langit dan apa yang ada di bumi? Tidak ada pembicaraan rahasia antara tiga orang, melainkan Dialah yang keempatnya. Dan tidak ada lima orang, melainkan Dialah yang keenamnya. Dan tidak ada yang kurang dari itu atau lebih banyak, melainkan Dia pasti ada bersama mereka di mana pun mereka berada. Kemudian Dia akan memberitakan kepada mereka pada hari Kiamat apa yang telah mereka kerjakan. Sesungguhnya Allah Maha Mengetahui segala sesuatu"},{id:8,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0631\u064e \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0646\u064f\u0647\u064f\u0648\u0627\u0652 \u0639\u064e\u0646\u0650 \u0671\u0644\u0646\u0651\u064e\u062c\u06e1\u0648\u064e\u0649\u0670 \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u0639\u064f\u0648\u062f\u064f\u0648\u0646\u064e \u0644\u0650\u0645\u064e\u0627 \u0646\u064f\u0647\u064f\u0648\u0627\u0652 \u0639\u064e\u0646\u06e1\u0647\u064f \u0648\u064e\u064a\u064e\u062a\u064e\u0646\u064e\u0670\u062c\u064e\u0648\u06e1\u0646\u064e \u0628\u0650\u0671\u0644\u06e1\u0625\u0650\u062b\u06e1\u0645\u0650 \u0648\u064e\u0671\u0644\u06e1\u0639\u064f\u062f\u06e1\u0648\u064e\u0670\u0646\u0650 \u0648\u064e\u0645\u064e\u0639\u06e1\u0635\u0650\u064a\u064e\u062a\u0650 \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0650\u06d6 \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064f\u0648\u0643\u064e \u062d\u064e\u064a\u0651\u064e\u0648\u06e1\u0643\u064e \u0628\u0650\u0645\u064e\u0627 \u0644\u064e\u0645\u06e1 \u064a\u064f\u062d\u064e\u064a\u0651\u0650\u0643\u064e \u0628\u0650\u0647\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0653 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u06e1 \u0644\u064e\u0648\u06e1\u0644\u064e\u0627 \u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064f\u0646\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u0646\u064e\u0642\u064f\u0648\u0644\u064f\u06da \u062d\u064e\u0633\u06e1\u0628\u064f\u0647\u064f\u0645\u06e1 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064f \u064a\u064e\u0635\u06e1\u0644\u064e\u0648\u06e1\u0646\u064e\u0647\u064e\u0627\u06d6 \u0641\u064e\u0628\u0650\u0626\u06e1\u0633\u064e \u0671\u0644\u06e1\u0645\u064e\u0635\u0650\u064a\u0631\u064f",translation:"Tidakkah engkau perhatikan orang-orang yang telah dilarang mengadakan pembicaraan rahasia, kemudian mereka kembali (mengerjakan) larangan itu dan mereka mengadakan pembicaraan rahasia untuk berbuat dosa, permusuhan dan durhaka kepada Rasul. Dan apabila mereka datang kepadamu (Muhammad), mereka mengucapkan salam dengan cara yang bukan seperti yang ditentukan Allah untukmu. Dan mereka mengatakan pada diri mereka sendiri, \"Mengapa Allah tidak menyiksa kita atas apa yang kita katakan itu?\" Cukuplah bagi mereka neraka Jahanam yang akan mereka masuki. Maka neraka itu seburuk-buruk tempat kembali"},{id:9,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0630\u064e\u0627 \u062a\u064e\u0646\u064e\u0670\u062c\u064e\u064a\u06e1\u062a\u064f\u0645\u06e1 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u064e\u0646\u064e\u0670\u062c\u064e\u0648\u06e1\u0627\u0652 \u0628\u0650\u0671\u0644\u06e1\u0625\u0650\u062b\u06e1\u0645\u0650 \u0648\u064e\u0671\u0644\u06e1\u0639\u064f\u062f\u06e1\u0648\u064e\u0670\u0646\u0650 \u0648\u064e\u0645\u064e\u0639\u06e1\u0635\u0650\u064a\u064e\u062a\u0650 \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0650 \u0648\u064e\u062a\u064e\u0646\u064e\u0670\u062c\u064e\u0648\u06e1\u0627\u0652 \u0628\u0650\u0671\u0644\u06e1\u0628\u0650\u0631\u0651\u0650 \u0648\u064e\u0671\u0644\u062a\u0651\u064e\u0642\u06e1\u0648\u064e\u0649\u0670\u06d6 \u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u062a\u064f\u062d\u06e1\u0634\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Wahai orang-orang yang beriman! Apabila kamu mengadakan pembicaraan rahasia, janganlah kamu membicarakan perbuatan dosa, permusuhan dan durhaka kepada Rasul. Tetapi bicarakanlah tentang perbuatan kebajikan dan takwa. Dan bertakwalah kepada Allah yang kepada-Nya kamu akan dikumpulkan kembali"},{id:10,text:"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u062c\u06e1\u0648\u064e\u0649\u0670 \u0645\u0650\u0646\u064e \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u0650 \u0644\u0650\u064a\u064e\u062d\u06e1\u0632\u064f\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0644\u064e\u064a\u06e1\u0633\u064e \u0628\u0650\u0636\u064e\u0627\u0653\u0631\u0651\u0650\u0647\u0650\u0645\u06e1 \u0634\u064e\u064a\u06e1\u0640\u0654\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0625\u0650\u0630\u06e1\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0644\u06e1\u064a\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u0650 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Sesungguhnya pembicaraan rahasia itu termasuk (perbuatan) setan, agar orang-orang yang beriman itu bersedih hati, sedang (pembicaraan) itu tidaklah memberi bencana sedikit pun kepada mereka, kecuali dengan izin Allah. Dan kepada Allah hendaknya orang-orang yang beriman bertawakal"},{id:11,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0630\u064e\u0627 \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u0641\u064e\u0633\u0651\u064e\u062d\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u06e1\u0645\u064e\u062c\u064e\u0670\u0644\u0650\u0633\u0650 \u0641\u064e\u0671\u0641\u06e1\u0633\u064e\u062d\u064f\u0648\u0627\u0652 \u064a\u064e\u0641\u06e1\u0633\u064e\u062d\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u0650\u064a\u0644\u064e \u0671\u0646\u0634\u064f\u0632\u064f\u0648\u0627\u0652 \u0641\u064e\u0671\u0646\u0634\u064f\u0632\u064f\u0648\u0627\u0652 \u064a\u064e\u0631\u06e1\u0641\u064e\u0639\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0639\u0650\u0644\u06e1\u0645\u064e \u062f\u064e\u0631\u064e\u062c\u064e\u0670\u062a\u0656\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u062e\u064e\u0628\u0650\u064a\u0631\u065e",translation:"Wahai orang-orang yang beriman! Apabila dikatakan kepadamu, \"Berilah kelapangan di dalam majelis-majelis,\" maka lapangkanlah, niscaya Allah akan memberi kelapangan untukmu. Dan apabila dikatakan, \"Berdirilah kamu,\" maka berdirilah, niscaya Allah akan mengangkat (derajat) orang-orang yang beriman di antaramu dan orang-orang yang diberi ilmu beberapa derajat. Dan Allah Mahateliti atas apa yang kamu kerjakan"},{id:12,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0630\u064e\u0627 \u0646\u064e\u0670\u062c\u064e\u064a\u06e1\u062a\u064f\u0645\u064f \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e \u0641\u064e\u0642\u064e\u062f\u0651\u0650\u0645\u064f\u0648\u0627\u0652 \u0628\u064e\u064a\u06e1\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u06e1 \u0646\u064e\u062c\u06e1\u0648\u064e\u0649\u0670\u0643\u064f\u0645\u06e1 \u0635\u064e\u062f\u064e\u0642\u064e\u0629\u0657\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062e\u064e\u064a\u06e1\u0631\u065e \u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0637\u06e1\u0647\u064e\u0631\u064f\u06da \u0641\u064e\u0625\u0650\u0646 \u0644\u0651\u064e\u0645\u06e1 \u062a\u064e\u062c\u0650\u062f\u064f\u0648\u0627\u0652 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064c",translation:"Wahai orang-orang yang beriman! Apabila kamu mengadakan pembicaraan khusus dengan Rasul, hendaklah kamu mengeluarkan sedekah (kepada orang miskin) sebelum (melakukan) pembicaraan itu. Yang demikian itu lebih baik bagimu dan lebih bersih. Tetapi jika kamu tidak memperoleh (yang akan disedekahkan) maka sungguh, Allah Maha Pengampun, Maha Penyayang"},{id:13,text:"\u0621\u064e\u0623\u064e\u0634\u06e1\u0641\u064e\u0642\u06e1\u062a\u064f\u0645\u06e1 \u0623\u064e\u0646 \u062a\u064f\u0642\u064e\u062f\u0651\u0650\u0645\u064f\u0648\u0627\u0652 \u0628\u064e\u064a\u06e1\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u06e1 \u0646\u064e\u062c\u06e1\u0648\u064e\u0649\u0670\u0643\u064f\u0645\u06e1 \u0635\u064e\u062f\u064e\u0642\u064e\u0670\u062a\u0656\u06da \u0641\u064e\u0625\u0650\u0630\u06e1 \u0644\u064e\u0645\u06e1 \u062a\u064e\u0641\u06e1\u0639\u064e\u0644\u064f\u0648\u0627\u0652 \u0648\u064e\u062a\u064e\u0627\u0628\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0641\u064e\u0623\u064e\u0642\u0650\u064a\u0645\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u0621\u064e\u0627\u062a\u064f\u0648\u0627\u0652 \u0671\u0644\u0632\u0651\u064e\u0643\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f\u06e5\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u062e\u064e\u0628\u0650\u064a\u0631\u064f\u06e2 \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Apakah kamu takut akan (menjadi miskin) karena kamu memberikan sedekah sebelum (melakukan) pembicaraan dengan Rasul? Tetapi jika kamu tidak melakukannya dan Allah telah memberi ampun kepadamu, maka laksanakanlah salat, dan tunaikanlah zakat serta taatlah kepada Allah dan Rasul-Nya! Dan Allah Mahateliti atas apa yang kamu kerjakan"},{id:14,text:"\u06de\u0623\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0631\u064e \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u06e1\u0627\u0652 \u0642\u064e\u0648\u06e1\u0645\u064b\u0627 \u063a\u064e\u0636\u0650\u0628\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0645\u0651\u064e\u0627 \u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0648\u064e\u064a\u064e\u062d\u06e1\u0644\u0650\u0641\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0643\u064e\u0630\u0650\u0628\u0650 \u0648\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Tidakkah engkau perhatikan orang-orang (munafik) yang menjadikan suatu kaum yang telah dimurkai Allah sebagai sahabat? Orang-orang itu bukan dari (kaum) kamu dan bukan dari (kaum) mereka. Dan mereka bersumpah atas kebohongan, sedang mereka mengetahuinya"},{id:15,text:"\u0623\u064e\u0639\u064e\u062f\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u0657\u0627 \u0634\u064e\u062f\u0650\u064a\u062f\u064b\u0627\u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0633\u064e\u0627\u0653\u0621\u064e \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Allah telah menyediakan azab yang sangat keras bagi mereka. Sungguh, betapa buruknya apa yang telah mereka kerjakan"},{id:16,text:"\u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u064e\u0647\u064f\u0645\u06e1 \u062c\u064f\u0646\u0651\u064e\u0629\u0657 \u0641\u064e\u0635\u064e\u062f\u0651\u064f\u0648\u0627\u0652 \u0639\u064e\u0646 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u065e \u0645\u0651\u064f\u0647\u0650\u064a\u0646\u065e",translation:"Mereka menjadikan sumpah-sumpah mereka sebagai perisai, lalu mereka menghalang-halangi (manusia) dari jalan Allah; maka bagi mereka azab yang menghinakan"},{id:17,text:"\u0644\u0651\u064e\u0646 \u062a\u064f\u063a\u06e1\u0646\u0650\u064a\u064e \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u064f\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064e\u0648\u06e1\u0644\u064e\u0670\u062f\u064f\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0634\u064e\u064a\u06e1\u0640\u0654\u064b\u0627\u06da \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650\u06d6 \u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u0670\u0644\u0650\u062f\u064f\u0648\u0646\u064e",translation:"Harta benda dan anak-anak mereka tidak berguna sedikit pun (untuk menolong) mereka dari azab Allah. Mereka itulah penghuni neraka, mereka kekal di dalamnya"},{id:18,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064e\u0628\u06e1\u0639\u064e\u062b\u064f\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u062c\u064e\u0645\u0650\u064a\u0639\u0657\u0627 \u0641\u064e\u064a\u064e\u062d\u06e1\u0644\u0650\u0641\u064f\u0648\u0646\u064e \u0644\u064e\u0647\u064f\u06e5 \u0643\u064e\u0645\u064e\u0627 \u064a\u064e\u062d\u06e1\u0644\u0650\u0641\u064f\u0648\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u064a\u064e\u062d\u06e1\u0633\u064e\u0628\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0634\u064e\u064a\u06e1\u0621\u064d\u06da \u0623\u064e\u0644\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0643\u064e\u0670\u0630\u0650\u0628\u064f\u0648\u0646\u064e",translation:"(Ingatlah) pada hari (ketika) mereka semua dibangkitkan Allah, lalu mereka bersumpah kepada-Nya (bahwa mereka bukan orang musyrik) sebagaimana mereka bersumpah kepadamu; dan mereka menyangka bahwa mereka akan memperoleh sesuatu (manfaat). Ketahuilah, bahwa mereka orang-orang pendusta"},{id:19,text:"\u0671\u0633\u06e1\u062a\u064e\u062d\u06e1\u0648\u064e\u0630\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u064f \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u064f \u0641\u064e\u0623\u064e\u0646\u0633\u064e\u0649\u0670\u0647\u064f\u0645\u06e1 \u0630\u0650\u0643\u06e1\u0631\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u062d\u0650\u0632\u06e1\u0628\u064f \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u0650\u06da \u0623\u064e\u0644\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e \u062d\u0650\u0632\u06e1\u0628\u064e \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u0650 \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u062e\u064e\u0670\u0633\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Setan telah menguasai mereka, lalu menjadikan mereka lupa mengingat Allah; mereka itulah golongan setan. Ketahuilah, bahwa golongan setan itulah golongan yang merugi"},{id:20,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u062d\u064e\u0627\u0653\u062f\u0651\u064f\u0648\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f\u06e5\u0653 \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0630\u064e\u0644\u0651\u0650\u064a\u0646\u064e",translation:"Sesungguhnya orang-orang yang menentang Allah dan Rasul-Nya, mereka termasuk orang-orang yang sangat hina"},{id:21,text:"\u0643\u064e\u062a\u064e\u0628\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0623\u064e\u063a\u06e1\u0644\u0650\u0628\u064e\u0646\u0651\u064e \u0623\u064e\u0646\u064e\u0627\u06e0 \u0648\u064e\u0631\u064f\u0633\u064f\u0644\u0650\u064a\u0653\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0642\u064e\u0648\u0650\u064a\u0651\u064c \u0639\u064e\u0632\u0650\u064a\u0632\u065e",translation:"Allah telah menetapkan, \"Aku dan rasul-rasul-Ku pasti menang.\" Sungguh, Allah Mahakuat, Mahaperkasa"},{id:22,text:"\u0644\u0651\u064e\u0627 \u062a\u064e\u062c\u0650\u062f\u064f \u0642\u064e\u0648\u06e1\u0645\u0657\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u0650 \u064a\u064f\u0648\u064e\u0627\u0653\u062f\u0651\u064f\u0648\u0646\u064e \u0645\u064e\u0646\u06e1 \u062d\u064e\u0627\u0653\u062f\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f\u06e5 \u0648\u064e\u0644\u064e\u0648\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0653\u0627\u0652 \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1 \u0623\u064e\u0628\u06e1\u0646\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1 \u0625\u0650\u062e\u06e1\u0648\u064e\u0670\u0646\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1 \u0639\u064e\u0634\u0650\u064a\u0631\u064e\u062a\u064e\u0647\u064f\u0645\u06e1\u06da \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0643\u064e\u062a\u064e\u0628\u064e \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u064f \u0671\u0644\u06e1\u0625\u0650\u064a\u0645\u064e\u0670\u0646\u064e \u0648\u064e\u0623\u064e\u064a\u0651\u064e\u062f\u064e\u0647\u064f\u0645 \u0628\u0650\u0631\u064f\u0648\u062d\u0656 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u06d6 \u0648\u064e\u064a\u064f\u062f\u06e1\u062e\u0650\u0644\u064f\u0647\u064f\u0645\u06e1 \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0656 \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0645\u0650\u0646 \u062a\u064e\u062d\u06e1\u062a\u0650\u0647\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u064f \u062e\u064e\u0670\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627\u06da \u0631\u064e\u0636\u0650\u064a\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0648\u064e\u0631\u064e\u0636\u064f\u0648\u0627\u0652 \u0639\u064e\u0646\u06e1\u0647\u064f\u06da \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u062d\u0650\u0632\u06e1\u0628\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0623\u064e\u0644\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e \u062d\u0650\u0632\u06e1\u0628\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064f\u0641\u06e1\u0644\u0650\u062d\u064f\u0648\u0646\u064e",translation:"Engkau (Muhammad) tidak akan mendapatkan suatu kaum yang beriman kepada Allah dan hari akhirat, saling berkasih sayang dengan orang-orang yang menentang Allah dan Rasul-Nya, sekalipun orang-orang itu bapaknya, anaknya, saudaranya atau keluarganya. Mereka itulah orang-orang yang dalam hatinya telah ditanamkan Allah keimanan dan Allah telah menguatkan mereka dengan pertolongan834) yang datang dari Dia. Lalu dimasukkan-Nya mereka ke dalam surga yang mengalir di bawahnya sungai-sungai, mereka kekal di dalamnya. Allah rida terhadap mereka dan mereka pun merasa puas terhadap (limpahan rahmat)-Nya. Merekalah golongan Allah. Ingatlah, sesungguhnya golongan Allah itulah yang beruntung"}]},{id:59,name:"\u0627\u0644\u062d\u0634\u0631",transliteration:"Al-Hashr",translation:"Pengusiran",type:"medinan",total_verses:24,verses:[{id:1,text:"\u0633\u064e\u0628\u0651\u064e\u062d\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0671\u0644\u06e1\u062d\u064e\u0643\u0650\u064a\u0645\u064f",translation:"Apa yang ada di langit dan apa yang ada di bumi bertasbih kepada Allah; dan Dialah Yang Mahaperkasa, Mahabijaksana"},{id:2,text:"\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064e\u062e\u06e1\u0631\u064e\u062c\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1 \u0623\u064e\u0647\u06e1\u0644\u0650 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0645\u0650\u0646 \u062f\u0650\u064a\u064e\u0670\u0631\u0650\u0647\u0650\u0645\u06e1 \u0644\u0650\u0623\u064e\u0648\u0651\u064e\u0644\u0650 \u0671\u0644\u06e1\u062d\u064e\u0634\u06e1\u0631\u0650\u06da \u0645\u064e\u0627 \u0638\u064e\u0646\u064e\u0646\u062a\u064f\u0645\u06e1 \u0623\u064e\u0646 \u064a\u064e\u062e\u06e1\u0631\u064f\u062c\u064f\u0648\u0627\u0652\u06d6 \u0648\u064e\u0638\u064e\u0646\u0651\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u0627\u0646\u0650\u0639\u064e\u062a\u064f\u0647\u064f\u0645\u06e1 \u062d\u064f\u0635\u064f\u0648\u0646\u064f\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0623\u064e\u062a\u064e\u0649\u0670\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u06e1 \u062d\u064e\u064a\u06e1\u062b\u064f \u0644\u064e\u0645\u06e1 \u064a\u064e\u062d\u06e1\u062a\u064e\u0633\u0650\u0628\u064f\u0648\u0627\u0652\u06d6 \u0648\u064e\u0642\u064e\u0630\u064e\u0641\u064e \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u064f \u0671\u0644\u0631\u0651\u064f\u0639\u06e1\u0628\u064e\u06da \u064a\u064f\u062e\u06e1\u0631\u0650\u0628\u064f\u0648\u0646\u064e \u0628\u064f\u064a\u064f\u0648\u062a\u064e\u0647\u064f\u0645 \u0628\u0650\u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u0647\u0650\u0645\u06e1 \u0648\u064e\u0623\u064e\u064a\u06e1\u062f\u0650\u064a \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0641\u064e\u0671\u0639\u06e1\u062a\u064e\u0628\u0650\u0631\u064f\u0648\u0627\u0652 \u064a\u064e\u0640\u0670\u0653\u0623\u064f\u0648\u0652\u0644\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0628\u06e1\u0635\u064e\u0670\u0631\u0650",translation:"(Dialah yang mengeluarkan orang-orang kafir di antara Ahli Kitab dari kampung halamannya pada saat pengusiran yang pertama.835) Kamu tidak menyangka, bahwa mereka akan keluar dan mereka pun yakin, benteng-benteng mereka akan dapat mempertahankan mereka dari (siksaan) Allah; maka Allah mendatangkan (siksaan) kepada mereka dari arah yang tidak mereka sangka-sangka. Dan Allah menanamkan rasa takut ke dalam hati mereka; sehingga mereka memusnahkan rumah-rumah mereka dengan tangannya sendiri dan tangan orang-orang mukmin. Maka ambillah (kejadian itu) untuk menjadi pelajaran, wahai orang-orang yang mempunyai pandangan"},{id:3,text:"\u0648\u064e\u0644\u064e\u0648\u06e1\u0644\u064e\u0627\u0653 \u0623\u064e\u0646 \u0643\u064e\u062a\u064e\u0628\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u064f \u0671\u0644\u06e1\u062c\u064e\u0644\u064e\u0627\u0653\u0621\u064e \u0644\u064e\u0639\u064e\u0630\u0651\u064e\u0628\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627\u06d6 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650",translation:"Dan sekiranya tidak karena Allah telah menetapkan pengusiran terhadap mereka, pasti Allah mengazab mereka di dunia. Dan di akhirat mereka akan mendapat azab neraka"},{id:4,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0634\u064e\u0627\u0653\u0642\u0651\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f\u06e5\u06d6 \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0634\u064e\u0627\u0653\u0642\u0651\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0634\u064e\u062f\u0650\u064a\u062f\u064f \u0671\u0644\u06e1\u0639\u0650\u0642\u064e\u0627\u0628\u0650",translation:"Yang demikian itu karena sesungguhnya mereka menentang Allah dan Rasul-Nya. Barangsiapa menentang Allah, maka sesungguhnya Allah sangat keras hukuman-Nya"},{id:5,text:"\u0645\u064e\u0627 \u0642\u064e\u0637\u064e\u0639\u06e1\u062a\u064f\u0645 \u0645\u0651\u0650\u0646 \u0644\u0651\u0650\u064a\u0646\u064e\u0629\u064d \u0623\u064e\u0648\u06e1 \u062a\u064e\u0631\u064e\u0643\u06e1\u062a\u064f\u0645\u064f\u0648\u0647\u064e\u0627 \u0642\u064e\u0627\u0653\u0626\u0650\u0645\u064e\u0629\u064b \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064f\u0635\u064f\u0648\u0644\u0650\u0647\u064e\u0627 \u0641\u064e\u0628\u0650\u0625\u0650\u0630\u06e1\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u0650\u064a\u064f\u062e\u06e1\u0632\u0650\u064a\u064e \u0671\u0644\u06e1\u0641\u064e\u0670\u0633\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Apa yang kamu tebang di antara pohon kurma (milik orang-orang kafir) atau yang kamu biarkan (tumbuh) berdiri di atas pokoknya, maka (itu terjadi) dengan izin Allah; dan karena Dia hendak memberikan kehinaan kepada orang-orang fasik"},{id:6,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0641\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650\u06e6 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0641\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0648\u06e1\u062c\u064e\u0641\u06e1\u062a\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0645\u0650\u0646\u06e1 \u062e\u064e\u064a\u06e1\u0644\u0656 \u0648\u064e\u0644\u064e\u0627 \u0631\u0650\u0643\u064e\u0627\u0628\u0656 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u0633\u064e\u0644\u0651\u0650\u0637\u064f \u0631\u064f\u0633\u064f\u0644\u064e\u0647\u064f\u06e5 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0642\u064e\u062f\u0650\u064a\u0631\u065e",translation:"(Dan harta rampasan fai`836) dari mereka yang diberikan Allah kepada Rasul-Nya, kamu tidak memerlukan kuda atau unta untuk mendapatkannya, tetapi Allah memberikan kekuasaan kepada rasul-rasul-Nya terhadap siapa yang Dia kehendaki. Dan Allah Mahakuasa atas segala sesuatu"},{id:7,text:"\u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u0641\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650\u06e6 \u0645\u0650\u0646\u06e1 \u0623\u064e\u0647\u06e1\u0644\u0650 \u0671\u0644\u06e1\u0642\u064f\u0631\u064e\u0649\u0670 \u0641\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0644\u0650\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0650 \u0648\u064e\u0644\u0650\u0630\u0650\u064a \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0628\u064e\u0649\u0670 \u0648\u064e\u0671\u0644\u06e1\u064a\u064e\u062a\u064e\u0670\u0645\u064e\u0649\u0670 \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u0633\u064e\u0670\u0643\u0650\u064a\u0646\u0650 \u0648\u064e\u0671\u0628\u06e1\u0646\u0650 \u0671\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u0650 \u0643\u064e\u064a\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0643\u064f\u0648\u0646\u064e \u062f\u064f\u0648\u0644\u064e\u0629\u064e\u06e2 \u0628\u064e\u064a\u06e1\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u063a\u06e1\u0646\u0650\u064a\u064e\u0627\u0653\u0621\u0650 \u0645\u0650\u0646\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0645\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u064e\u0649\u0670\u0643\u064f\u0645\u064f \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064f \u0641\u064e\u062e\u064f\u0630\u064f\u0648\u0647\u064f \u0648\u064e\u0645\u064e\u0627 \u0646\u064e\u0647\u064e\u0649\u0670\u0643\u064f\u0645\u06e1 \u0639\u064e\u0646\u06e1\u0647\u064f \u0641\u064e\u0671\u0646\u062a\u064e\u0647\u064f\u0648\u0627\u0652\u06da \u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e\u06d6 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0634\u064e\u062f\u0650\u064a\u062f\u064f \u0671\u0644\u06e1\u0639\u0650\u0642\u064e\u0627\u0628\u0650",translation:"Harta rampasan fai` yang diberikan Allah kepada Rasul-Nya (yang berasal) dari penduduk beberapa negeri, adalah untuk Allah, Rasul, kerabat (Rasul), anak-anak yatim, orang-orang miskin dan untuk orang-orang yang dalam perjalanan, agar harta itu jangan hanya beredar di antara orang-orang kaya saja di antara kamu. Apa yang diberikan Rasul kepadamu maka terimalah. Dan apa yang dilarangnya bagimu maka tinggalkanlah. Dan bertakwalah kepada Allah. Sungguh, Allah sangat keras hukuman-Nya"},{id:8,text:"\u0644\u0650\u0644\u06e1\u0641\u064f\u0642\u064e\u0631\u064e\u0627\u0653\u0621\u0650 \u0671\u0644\u06e1\u0645\u064f\u0647\u064e\u0670\u062c\u0650\u0631\u0650\u064a\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u062e\u06e1\u0631\u0650\u062c\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u062f\u0650\u064a\u064e\u0670\u0631\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u0650\u0647\u0650\u0645\u06e1 \u064a\u064e\u0628\u06e1\u062a\u064e\u063a\u064f\u0648\u0646\u064e \u0641\u064e\u0636\u06e1\u0644\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u0650\u0636\u06e1\u0648\u064e\u0670\u0646\u0657\u0627 \u0648\u064e\u064a\u064e\u0646\u0635\u064f\u0631\u064f\u0648\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f\u06e5\u0653\u06da \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u062f\u0650\u0642\u064f\u0648\u0646\u064e",translation:"(Harta rampasan itu juga) untuk orang-orang fakir yang berhijrah837) yang terusir dari kampung halamannya dan meninggalkan harta bendanya demi mencari karunia dari Allah dan keridaan(-Nya) dan (demi) menolong (agama) Allah dan Rasul-Nya. Mereka itulah orang-orang yang benar"},{id:9,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u0628\u064e\u0648\u0651\u064e\u0621\u064f\u0648 \u0671\u0644\u062f\u0651\u064e\u0627\u0631\u064e \u0648\u064e\u0671\u0644\u06e1\u0625\u0650\u064a\u0645\u064e\u0670\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u0645\u06e1 \u064a\u064f\u062d\u0650\u0628\u0651\u064f\u0648\u0646\u064e \u0645\u064e\u0646\u06e1 \u0647\u064e\u0627\u062c\u064e\u0631\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062c\u0650\u062f\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0635\u064f\u062f\u064f\u0648\u0631\u0650\u0647\u0650\u0645\u06e1 \u062d\u064e\u0627\u062c\u064e\u0629\u0657 \u0645\u0651\u0650\u0645\u0651\u064e\u0627\u0653 \u0623\u064f\u0648\u062a\u064f\u0648\u0627\u0652 \u0648\u064e\u064a\u064f\u0624\u06e1\u062b\u0650\u0631\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0644\u064e\u0648\u06e1 \u0643\u064e\u0627\u0646\u064e \u0628\u0650\u0647\u0650\u0645\u06e1 \u062e\u064e\u0635\u064e\u0627\u0635\u064e\u0629\u065e\u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0648\u0642\u064e \u0634\u064f\u062d\u0651\u064e \u0646\u064e\u0641\u06e1\u0633\u0650\u0647\u0650\u06e6 \u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064f\u0641\u06e1\u0644\u0650\u062d\u064f\u0648\u0646\u064e",translation:"Dan orang-orang (Ansar) yang telah menempati kota Madinah dan telah beriman sebelum (kedatangan) mereka (Muhajirin), mereka mencintai orang yang berhijrah ke tempat mereka. Dan mereka tidak menaruh keinginan dalam hati mereka terhadap apa yang diberikan kepada mereka (Muhajirin); dan mereka mengutamakan (Muhajirin), atas dirinya sendiri, meskipun mereka juga memerlukan. Dan siapa yang dijaga dirinya dari kekikiran, maka mereka itulah orang-orang yang beruntung"},{id:10,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062c\u064e\u0627\u0653\u0621\u064f\u0648 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u0647\u0650\u0645\u06e1 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0671\u063a\u06e1\u0641\u0650\u0631\u06e1 \u0644\u064e\u0646\u064e\u0627 \u0648\u064e\u0644\u0650\u0625\u0650\u062e\u06e1\u0648\u064e\u0670\u0646\u0650\u0646\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0633\u064e\u0628\u064e\u0642\u064f\u0648\u0646\u064e\u0627 \u0628\u0650\u0671\u0644\u06e1\u0625\u0650\u064a\u0645\u064e\u0670\u0646\u0650 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062c\u06e1\u0639\u064e\u0644\u06e1 \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0646\u064e\u0627 \u063a\u0650\u0644\u0651\u0657\u0627 \u0644\u0651\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0631\u064e\u0621\u064f\u0648\u0641\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064c",translation:"Dan orang-orang yang datang sesudah mereka (Muhajirin dan Ansar), mereka berdoa, \"Ya Tuhan kami, ampunilah kami dan saudara-saudara kami yang telah beriman lebih dahulu dari kami, dan janganlah Engkau tanamkan kedengkian dalam hati kami terhadap orang-orang yang beriman. Ya Tuhan kami, sungguh, Engkau Maha Penyantun, Maha Penyayang"},{id:11,text:"\u06de\u0623\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0631\u064e \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0646\u064e\u0627\u0641\u064e\u0642\u064f\u0648\u0627\u0652 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0644\u0650\u0625\u0650\u062e\u06e1\u0648\u064e\u0670\u0646\u0650\u0647\u0650\u0645\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1 \u0623\u064e\u0647\u06e1\u0644\u0650 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0644\u064e\u0626\u0650\u0646\u06e1 \u0623\u064f\u062e\u06e1\u0631\u0650\u062c\u06e1\u062a\u064f\u0645\u06e1 \u0644\u064e\u0646\u064e\u062e\u06e1\u0631\u064f\u062c\u064e\u0646\u0651\u064e \u0645\u064e\u0639\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u0646\u064f\u0637\u0650\u064a\u0639\u064f \u0641\u0650\u064a\u0643\u064f\u0645\u06e1 \u0623\u064e\u062d\u064e\u062f\u064b\u0627 \u0623\u064e\u0628\u064e\u062f\u0657\u0627 \u0648\u064e\u0625\u0650\u0646 \u0642\u064f\u0648\u062a\u0650\u0644\u06e1\u062a\u064f\u0645\u06e1 \u0644\u064e\u0646\u064e\u0646\u0635\u064f\u0631\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0634\u06e1\u0647\u064e\u062f\u064f \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0643\u064e\u0670\u0630\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Tidakkah engkau memperhatikan orang-orang munafik yang berkata kepada saudara-saudaranya yang kafir di antara Ahli Kitab, \"Sungguh, jika kamu diusir niscaya kami pun akan keluar bersama kamu; dan kami selama-lamanya tidak akan patuh kepada siapa pun demi kamu, dan jika kamu diperangi pasti kami akan membantumu.\" Dan Allah menyaksikan, bahwa mereka benar-benar pendusta"},{id:12,text:"\u0644\u064e\u0626\u0650\u0646\u06e1 \u0623\u064f\u062e\u06e1\u0631\u0650\u062c\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u064a\u064e\u062e\u06e1\u0631\u064f\u062c\u064f\u0648\u0646\u064e \u0645\u064e\u0639\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0626\u0650\u0646 \u0642\u064f\u0648\u062a\u0650\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u064a\u064e\u0646\u0635\u064f\u0631\u064f\u0648\u0646\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0626\u0650\u0646 \u0646\u0651\u064e\u0635\u064e\u0631\u064f\u0648\u0647\u064f\u0645\u06e1 \u0644\u064e\u064a\u064f\u0648\u064e\u0644\u0651\u064f\u0646\u0651\u064e \u0671\u0644\u06e1\u0623\u064e\u062f\u06e1\u0628\u064e\u0670\u0631\u064e \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0627 \u064a\u064f\u0646\u0635\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Sungguh, jika mereka diusir, orang-orang munafik itu tidak akan keluar bersama mereka, dan jika mereka diperangi; mereka (juga) tidak akan menolongnya; dan kalau pun mereka menolongnya pastilah mereka akan berpaling lari ke belakang, kemudian mereka tidak akan mendapat pertolongan"},{id:13,text:"\u0644\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0623\u064e\u0634\u064e\u062f\u0651\u064f \u0631\u064e\u0647\u06e1\u0628\u064e\u0629\u0657 \u0641\u0650\u064a \u0635\u064f\u062f\u064f\u0648\u0631\u0650\u0647\u0650\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0642\u064e\u0648\u06e1\u0645\u065e \u0644\u0651\u064e\u0627 \u064a\u064e\u0641\u06e1\u0642\u064e\u0647\u064f\u0648\u0646\u064e",translation:"Sesungguhnya dalam hati mereka, kamu (muslimin) lebih ditakuti daripada Allah. Yang demikian itu karena mereka orang-orang yang tidak mengerti"},{id:14,text:"\u0644\u064e\u0627 \u064a\u064f\u0642\u064e\u0670\u062a\u0650\u0644\u064f\u0648\u0646\u064e\u0643\u064f\u0645\u06e1 \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0641\u0650\u064a \u0642\u064f\u0631\u0657\u0649 \u0645\u0651\u064f\u062d\u064e\u0635\u0651\u064e\u0646\u064e\u0629\u064d \u0623\u064e\u0648\u06e1 \u0645\u0650\u0646 \u0648\u064e\u0631\u064e\u0627\u0653\u0621\u0650 \u062c\u064f\u062f\u064f\u0631\u0650\u06ed\u06da \u0628\u064e\u0623\u06e1\u0633\u064f\u0647\u064f\u0645 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u06e1 \u0634\u064e\u062f\u0650\u064a\u062f\u065e\u06da \u062a\u064e\u062d\u06e1\u0633\u064e\u0628\u064f\u0647\u064f\u0645\u06e1 \u062c\u064e\u0645\u0650\u064a\u0639\u0657\u0627 \u0648\u064e\u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u06e1 \u0634\u064e\u062a\u0651\u064e\u0649\u0670\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0642\u064e\u0648\u06e1\u0645\u065e \u0644\u0651\u064e\u0627 \u064a\u064e\u0639\u06e1\u0642\u0650\u0644\u064f\u0648\u0646\u064e",translation:"Mereka tidak akan memerangi kamu (secara) bersama-sama, kecuali di negeri-negeri yang berbenteng atau di balik tembok. Permusuhan antara sesama mereka sangat hebat. Kamu kira mereka itu bersatu padahal hati mereka terpecah belah. Yang demikian itu karena mereka orang-orang yang tidak mengerti"},{id:15,text:"\u0643\u064e\u0645\u064e\u062b\u064e\u0644\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u0645\u06e1 \u0642\u064e\u0631\u0650\u064a\u0628\u0657\u0627\u06d6 \u0630\u064e\u0627\u0642\u064f\u0648\u0627\u0652 \u0648\u064e\u0628\u064e\u0627\u0644\u064e \u0623\u064e\u0645\u06e1\u0631\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u065e",translation:"(Mereka) seperti orang-orang yang sebelum mereka (Yahudi) belum lama berselang, telah merasakan akibat buruk (terusir) disebabkan perbuatan mereka sendiri. Dan mereka akan mendapat azab yang pedih"},{id:16,text:"\u0643\u064e\u0645\u064e\u062b\u064e\u0644\u0650 \u0671\u0644\u0634\u0651\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u0650 \u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u0650 \u0671\u0643\u06e1\u0641\u064f\u0631\u06e1 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0643\u064e\u0641\u064e\u0631\u064e \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0628\u064e\u0631\u0650\u064a\u0653\u0621\u065e \u0645\u0651\u0650\u0646\u0643\u064e \u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0631\u064e\u0628\u0651\u064e \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"(Bujukan orang-orang munafik itu) seperti (bujukan) setan ketika ia berkata kepada manusia, \"Kafirlah kamu!\" Kemudian setelah manusia itu menjadi kafir ia berkata, \"Sesungguhnya aku berlepas diri dari kamu, karena sesungguhnya aku takut kepada Allah, Tuhan seluruh alam"},{id:17,text:"\u0641\u064e\u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0670\u0642\u0650\u0628\u064e\u062a\u064e\u0647\u064f\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u062e\u064e\u0670\u0644\u0650\u062f\u064e\u064a\u06e1\u0646\u0650 \u0641\u0650\u064a\u0647\u064e\u0627\u06da \u0648\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062c\u064e\u0632\u064e\u0640\u0670\u0653\u0624\u064f\u0627\u0652 \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Maka kesudahan bagi keduanya, bahwa keduanya masuk ke dalam neraka, kekal di dalamnya. Demikianlah balasan bagi orang-orang zalim"},{id:18,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0644\u06e1\u062a\u064e\u0646\u0638\u064f\u0631\u06e1 \u0646\u064e\u0641\u06e1\u0633\u065e \u0645\u0651\u064e\u0627 \u0642\u064e\u062f\u0651\u064e\u0645\u064e\u062a\u06e1 \u0644\u0650\u063a\u064e\u062f\u0656\u06d6 \u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u062e\u064e\u0628\u0650\u064a\u0631\u064f\u06e2 \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Wahai orang-orang yang beriman! Bertakwalah kepada Allah dan hendaklah setiap orang memperhatikan apa yang telah diperbuatnya untuk hari esok (akhirat), dan bertakwalah kepada Allah. Sungguh, Allah Mahateliti terhadap apa yang kamu kerjakan"},{id:19,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u0643\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0646\u064e\u0633\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0641\u064e\u0623\u064e\u0646\u0633\u064e\u0649\u0670\u0647\u064f\u0645\u06e1 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0647\u064f\u0645\u06e1\u06da \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0641\u064e\u0670\u0633\u0650\u0642\u064f\u0648\u0646\u064e",translation:"Dan janganlah kamu seperti orang-orang yang lupa kepada Allah, sehingga Allah menjadikan mereka lupa akan diri sendiri. Mereka itulah orang-orang fasik"},{id:20,text:"\u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0648\u0650\u064a\u0653 \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0648\u064e\u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u0650\u06da \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0641\u064e\u0627\u0653\u0626\u0650\u0632\u064f\u0648\u0646\u064e",translation:"Tidak sama para penghuni neraka dengan para penghuni surga; para penghuni surga itulah orang-orang yang memperoleh kemenangan"},{id:21,text:"\u0644\u064e\u0648\u06e1 \u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0627 \u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u062c\u064e\u0628\u064e\u0644\u0656 \u0644\u0651\u064e\u0631\u064e\u0623\u064e\u064a\u06e1\u062a\u064e\u0647\u064f\u06e5 \u062e\u064e\u0670\u0634\u0650\u0639\u0657\u0627 \u0645\u0651\u064f\u062a\u064e\u0635\u064e\u062f\u0651\u0650\u0639\u0657\u0627 \u0645\u0651\u0650\u0646\u06e1 \u062e\u064e\u0634\u06e1\u064a\u064e\u0629\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0648\u064e\u062a\u0650\u0644\u06e1\u0643\u064e \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u062b\u064e\u0670\u0644\u064f \u0646\u064e\u0636\u06e1\u0631\u0650\u0628\u064f\u0647\u064e\u0627 \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u062a\u064e\u0641\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Sekiranya Kami turunkan Alquran ini kepada sebuah gunung, pasti kamu akan melihatnya tunduk terpecah belah disebabkan takut kepada Allah. Dan perumpamaan-perumpamaan itu Kami buat untuk manusia agar mereka berpikir"},{id:22,text:"\u0647\u064f\u0648\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0644\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e\u06d6 \u0639\u064e\u0670\u0644\u0650\u0645\u064f \u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u0628\u0650 \u0648\u064e\u0671\u0644\u0634\u0651\u064e\u0647\u064e\u0670\u062f\u064e\u0629\u0650\u06d6 \u0647\u064f\u0648\u064e \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u064f \u0671\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",translation:"Dialah Allah, tidak ada tuhan selain Dia. Mengetahui yang gaib dan yang nyata, Dialah Yang Maha Pengasih, Maha Penyayang"},{id:23,text:"\u0647\u064f\u0648\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0644\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0645\u064e\u0644\u0650\u0643\u064f \u0671\u0644\u06e1\u0642\u064f\u062f\u0651\u064f\u0648\u0633\u064f \u0671\u0644\u0633\u0651\u064e\u0644\u064e\u0670\u0645\u064f \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064f \u0671\u0644\u06e1\u0645\u064f\u0647\u064e\u064a\u06e1\u0645\u0650\u0646\u064f \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0671\u0644\u06e1\u062c\u064e\u0628\u0651\u064e\u0627\u0631\u064f \u0671\u0644\u06e1\u0645\u064f\u062a\u064e\u0643\u064e\u0628\u0651\u0650\u0631\u064f\u06da \u0633\u064f\u0628\u06e1\u062d\u064e\u0670\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064f\u0634\u06e1\u0631\u0650\u0643\u064f\u0648\u0646\u064e",translation:"Dialah Allah, tidak ada tuhan selain Dia. Maha Raja Yang Mahasuci, Yang Mahasejahtera, Yang Menjaga Keamanan, Pemelihara Keselamatan, Yang Mahaperkasa, Yang Mahakuasa, Yang Memiliki Segala Keagungan. Mahasuci Allah dari apa yang mereka persekutukan"},{id:24,text:"\u0647\u064f\u0648\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u062e\u064e\u0670\u0644\u0650\u0642\u064f \u0671\u0644\u06e1\u0628\u064e\u0627\u0631\u0650\u0626\u064f \u0671\u0644\u06e1\u0645\u064f\u0635\u064e\u0648\u0651\u0650\u0631\u064f\u06d6 \u0644\u064e\u0647\u064f \u0671\u0644\u06e1\u0623\u064e\u0633\u06e1\u0645\u064e\u0627\u0653\u0621\u064f \u0671\u0644\u06e1\u062d\u064f\u0633\u06e1\u0646\u064e\u0649\u0670\u06da \u064a\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u064f \u0644\u064e\u0647\u064f\u06e5 \u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0671\u0644\u06e1\u062d\u064e\u0643\u0650\u064a\u0645\u064f",translation:"Dialah Allah Yang Menciptakan, Yang Mengadakan, Yang Membentuk Rupa, Dia memiliki nama-nama yang indah. Apa yang di langit dan di bumi bertasbih kepada-Nya. Dan Dialah Yang Mahaperkasa, Mahabijaksana"}]},{id:60,name:"\u0627\u0644\u0645\u0645\u062a\u062d\u0646\u0629",transliteration:"Al-Mumtahanah",translation:"Wanita yang Diuji",type:"medinan",total_verses:13,verses:[{id:1,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0627\u0652 \u0639\u064e\u062f\u064f\u0648\u0651\u0650\u064a \u0648\u064e\u0639\u064e\u062f\u064f\u0648\u0651\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1\u0644\u0650\u064a\u064e\u0627\u0653\u0621\u064e \u062a\u064f\u0644\u06e1\u0642\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0628\u0650\u0671\u0644\u06e1\u0645\u064e\u0648\u064e\u062f\u0651\u064e\u0629\u0650 \u0648\u064e\u0642\u064e\u062f\u06e1 \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0645\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u064a\u064f\u062e\u06e1\u0631\u0650\u062c\u064f\u0648\u0646\u064e \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e \u0648\u064e\u0625\u0650\u064a\u0651\u064e\u0627\u0643\u064f\u0645\u06e1 \u0623\u064e\u0646 \u062a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u06e1 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062e\u064e\u0631\u064e\u062c\u06e1\u062a\u064f\u0645\u06e1 \u062c\u0650\u0647\u064e\u0670\u062f\u0657\u0627 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650\u064a \u0648\u064e\u0671\u0628\u06e1\u062a\u0650\u063a\u064e\u0627\u0653\u0621\u064e \u0645\u064e\u0631\u06e1\u0636\u064e\u0627\u062a\u0650\u064a\u06da \u062a\u064f\u0633\u0650\u0631\u0651\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0628\u0650\u0671\u0644\u06e1\u0645\u064e\u0648\u064e\u062f\u0651\u064e\u0629\u0650 \u0648\u064e\u0623\u064e\u0646\u064e\u0627\u06e0 \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627\u0653 \u0623\u064e\u062e\u06e1\u0641\u064e\u064a\u06e1\u062a\u064f\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0639\u06e1\u0644\u064e\u0646\u062a\u064f\u0645\u06e1\u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0641\u06e1\u0639\u064e\u0644\u06e1\u0647\u064f \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u0641\u064e\u0642\u064e\u062f\u06e1 \u0636\u064e\u0644\u0651\u064e \u0633\u064e\u0648\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u0650",translation:"Wahai orang-orang yang beriman! Janganlah kamu menjadikan musuh-Ku dan musuhmu sebagai teman-teman setia sehingga kamu sampaikan kepada mereka (berita-berita Muhammad), karena rasa kasih sayang; padahal mereka telah ingkar kepada kebenaran yang disampaikan kepadamu. Mereka mengusir Rasul dan kamu sendiri karena kamu beriman kepada Allah, Tuhanmu. Jika kamu benar-benar keluar untuk berjihad pada jalan-Ku dan mencari keridaan-Ku (janganlah kamu berbuat demikian). Kamu memberitahukan secara rahasia (berita-berita Muhammad) kepada mereka, karena rasa kasih sayang, dan Aku lebih mengetahui apa yang kamu sembunyikan dan apa yang kamu nyatakan. Dan barangsiapa di antara kamu yang melakukannya, maka sungguh dia telah tersesat dari jalan yang lurus"},{id:2,text:"\u0625\u0650\u0646 \u064a\u064e\u062b\u06e1\u0642\u064e\u0641\u064f\u0648\u0643\u064f\u0645\u06e1 \u064a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u0639\u06e1\u062f\u064e\u0627\u0653\u0621\u0657 \u0648\u064e\u064a\u064e\u0628\u06e1\u0633\u064f\u0637\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0644\u06e1\u0633\u0650\u0646\u064e\u062a\u064e\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u0633\u0651\u064f\u0648\u0653\u0621\u0650 \u0648\u064e\u0648\u064e\u062f\u0651\u064f\u0648\u0627\u0652 \u0644\u064e\u0648\u06e1 \u062a\u064e\u0643\u06e1\u0641\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Jika mereka menangkapmu, niscaya mereka bertindak sebagai musuh bagimu lalu melepaskan tangan dan lidahnya kepadamu untuk menyakiti dan mereka ingin agar kamu (kembali) kafir"},{id:3,text:"\u0644\u064e\u0646 \u062a\u064e\u0646\u0641\u064e\u0639\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u0631\u06e1\u062d\u064e\u0627\u0645\u064f\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064e\u0648\u06e1\u0644\u064e\u0670\u062f\u064f\u0643\u064f\u0645\u06e1\u06da \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u064a\u064e\u0641\u06e1\u0635\u0650\u0644\u064f \u0628\u064e\u064a\u06e1\u0646\u064e\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0628\u064e\u0635\u0650\u064a\u0631\u065e",translation:"Kaum kerabatmu dan anak-anakmu tidak akan bermanfaat bagimu pada hari Kiamat. Dia akan memisahkan antara kamu. Dan Allah Maha Melihat apa yang kamu kerjakan"},{id:4,text:"\u0642\u064e\u062f\u06e1 \u0643\u064e\u0627\u0646\u064e\u062a\u06e1 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0623\u064f\u0633\u06e1\u0648\u064e\u0629\u064c \u062d\u064e\u0633\u064e\u0646\u064e\u0629\u065e \u0641\u0650\u064a\u0653 \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064e \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u064e\u0639\u064e\u0647\u064f\u06e5\u0653 \u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u0650\u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u0645\u06e1 \u0625\u0650\u0646\u0651\u064e\u0627 \u0628\u064f\u0631\u064e\u0621\u064e\u0640\u0670\u0653\u0624\u064f\u0627\u0652 \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u0648\u064e\u0645\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u0641\u064e\u0631\u06e1\u0646\u064e\u0627 \u0628\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0628\u064e\u062f\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e\u0646\u064e\u0627 \u0648\u064e\u0628\u064e\u064a\u06e1\u0646\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0639\u064e\u062f\u064e\u0670\u0648\u064e\u0629\u064f \u0648\u064e\u0671\u0644\u06e1\u0628\u064e\u063a\u06e1\u0636\u064e\u0627\u0653\u0621\u064f \u0623\u064e\u0628\u064e\u062f\u064b\u0627 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u062d\u06e1\u062f\u064e\u0647\u064f\u06e5\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0648\u06e1\u0644\u064e \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064e \u0644\u0650\u0623\u064e\u0628\u0650\u064a\u0647\u0650 \u0644\u064e\u0623\u064e\u0633\u06e1\u062a\u064e\u063a\u06e1\u0641\u0650\u0631\u064e\u0646\u0651\u064e \u0644\u064e\u0643\u064e \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0645\u06e1\u0644\u0650\u0643\u064f \u0644\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646 \u0634\u064e\u064a\u06e1\u0621\u0656\u06d6 \u0631\u0651\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u06e1\u0646\u064e\u0627 \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0623\u064e\u0646\u064e\u0628\u06e1\u0646\u064e\u0627 \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0671\u0644\u06e1\u0645\u064e\u0635\u0650\u064a\u0631\u064f",translation:"Sungguh, telah ada suri teladan yang baik bagimu pada Ibrahim dan orang-orang yang bersama dengannya, ketika mereka berkata kepada kaumnya, \"Sesungguhnya kami berlepas diri dari kamu dan dari apa yang kamu sembah selain Allah, kami mengingkari (kekafiran)mu dan telah nyata antara kami dan kamu ada permusuhan dan kebencian buat selama-lamanya sampai kamu beriman kepada Allah saja,\" kecuali perkataan Ibrahim kepada ayahnya,838) \"Sungguh, aku akan memohonkan ampunan bagimu, namun aku sama sekali tidak dapat menolak (siksaan) Allah terhadapmu.\" (Ibrahim berkata), \"Ya Tuhan kami, hanya kepada Engkau kami bertawakal dan hanya kepada Engkau kami bertobat dan hanya kepada Engkaulah kami kembali"},{id:5,text:"\u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0644\u064e\u0627 \u062a\u064e\u062c\u06e1\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0641\u0650\u062a\u06e1\u0646\u064e\u0629\u0657 \u0644\u0651\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u0671\u063a\u06e1\u0641\u0650\u0631\u06e1 \u0644\u064e\u0646\u064e\u0627 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627\u0653\u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0623\u064e\u0646\u062a\u064e \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0671\u0644\u06e1\u062d\u064e\u0643\u0650\u064a\u0645\u064f",translation:"Ya Tuhan kami, janganlah Engkau jadikan kami (sasaran) fitnah bagi orang-orang kafir. Dan ampunilah kami, ya Tuhan kami. Sesungguhnya Engkau \u017bat Yang Mahaperkasa, Mahabijaksana"},{id:6,text:"\u0644\u064e\u0642\u064e\u062f\u06e1 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u0650\u0645\u06e1 \u0623\u064f\u0633\u06e1\u0648\u064e\u0629\u064c \u062d\u064e\u0633\u064e\u0646\u064e\u0629\u065e \u0644\u0651\u0650\u0645\u064e\u0646 \u0643\u064e\u0627\u0646\u064e \u064a\u064e\u0631\u06e1\u062c\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u063a\u064e\u0646\u0650\u064a\u0651\u064f \u0671\u0644\u06e1\u062d\u064e\u0645\u0650\u064a\u062f\u064f",translation:"Sungguh, pada mereka itu (Ibrahim dan umatnya) terdapat suri teladan yang baik bagimu; (yaitu) bagi orang yang mengharap (pahala) Allah dan (keselamatan pada) hari kemudian, dan barangsiapa berpaling, maka sesungguhnya Allah, Dialah Yang Mahakaya, Maha Terpuji"},{id:7,text:"\u06de\u0639\u064e\u0633\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0646 \u064a\u064e\u062c\u06e1\u0639\u064e\u0644\u064e \u0628\u064e\u064a\u06e1\u0646\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0628\u064e\u064a\u06e1\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0639\u064e\u0627\u062f\u064e\u064a\u06e1\u062a\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645 \u0645\u0651\u064e\u0648\u064e\u062f\u0651\u064e\u0629\u0657\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0642\u064e\u062f\u0650\u064a\u0631\u065e\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u065e",translation:"Mudah-mudahan Allah menumbuhkan kasih sayang di antara kamu dengan orang-orang yang pernah kamu musuhi di antara mereka. Allah Mahakuasa. Dan Allah Maha Pengampun, Maha Penyayang"},{id:8,text:"\u0644\u0651\u064e\u0627 \u064a\u064e\u0646\u06e1\u0647\u064e\u0649\u0670\u0643\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0646\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0645\u06e1 \u064a\u064f\u0642\u064e\u0670\u062a\u0650\u0644\u064f\u0648\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u0650 \u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064f\u062e\u06e1\u0631\u0650\u062c\u064f\u0648\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u062f\u0650\u064a\u064e\u0670\u0631\u0650\u0643\u064f\u0645\u06e1 \u0623\u064e\u0646 \u062a\u064e\u0628\u064e\u0631\u0651\u064f\u0648\u0647\u064f\u0645\u06e1 \u0648\u064e\u062a\u064f\u0642\u06e1\u0633\u0650\u0637\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0671\u0644\u06e1\u0645\u064f\u0642\u06e1\u0633\u0650\u0637\u0650\u064a\u0646\u064e",translation:"Allah tidak melarang kamu berbuat baik dan berlaku adil terhadap orang-orang yang tidak memerangimu dalam urusan agama dan tidak mengusir kamu dari kampung halamanmu. Sesungguhnya Allah mencintai orang-orang yang berlaku adil"},{id:9,text:"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0646\u06e1\u0647\u064e\u0649\u0670\u0643\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0646\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0642\u064e\u0670\u062a\u064e\u0644\u064f\u0648\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u0650 \u0648\u064e\u0623\u064e\u062e\u06e1\u0631\u064e\u062c\u064f\u0648\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u062f\u0650\u064a\u064e\u0670\u0631\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0638\u064e\u0670\u0647\u064e\u0631\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0625\u0650\u062e\u06e1\u0631\u064e\u0627\u062c\u0650\u0643\u064f\u0645\u06e1 \u0623\u064e\u0646 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u06e1\u0647\u064f\u0645\u06e1\u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Sesungguhnya Allah hanya melarang kamu menjadikan mereka sebagai kawanmu orang-orang yang memerangi kamu dalam urusan agama dan mengusir kamu dari kampung halamanmu dan membantu (orang lain) untuk mengusirmu. Barangsiapa menjadikan mereka sebagai kawan, mereka itulah orang yang zalim"},{id:10,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064e\u0670\u062a\u064f \u0645\u064f\u0647\u064e\u0670\u062c\u0650\u0631\u064e\u0670\u062a\u0656 \u0641\u064e\u0671\u0645\u06e1\u062a\u064e\u062d\u0650\u0646\u064f\u0648\u0647\u064f\u0646\u0651\u064e\u06d6 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0628\u0650\u0625\u0650\u064a\u0645\u064e\u0670\u0646\u0650\u0647\u0650\u0646\u0651\u064e\u06d6 \u0641\u064e\u0625\u0650\u0646\u06e1 \u0639\u064e\u0644\u0650\u0645\u06e1\u062a\u064f\u0645\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064e\u0670\u062a\u0656 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0631\u06e1\u062c\u0650\u0639\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u0643\u064f\u0641\u0651\u064e\u0627\u0631\u0650\u06d6 \u0644\u064e\u0627 \u0647\u064f\u0646\u0651\u064e \u062d\u0650\u0644\u0651\u065e \u0644\u0651\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u06e1 \u064a\u064e\u062d\u0650\u0644\u0651\u064f\u0648\u0646\u064e \u0644\u064e\u0647\u064f\u0646\u0651\u064e\u06d6 \u0648\u064e\u0621\u064e\u0627\u062a\u064f\u0648\u0647\u064f\u0645 \u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u0646\u0641\u064e\u0642\u064f\u0648\u0627\u0652\u06da \u0648\u064e\u0644\u064e\u0627 \u062c\u064f\u0646\u064e\u0627\u062d\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0623\u064e\u0646 \u062a\u064e\u0646\u0643\u0650\u062d\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0625\u0650\u0630\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u064e\u064a\u06e1\u062a\u064f\u0645\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0623\u064f\u062c\u064f\u0648\u0631\u064e\u0647\u064f\u0646\u0651\u064e\u06da \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0645\u06e1\u0633\u0650\u0643\u064f\u0648\u0627\u0652 \u0628\u0650\u0639\u0650\u0635\u064e\u0645\u0650 \u0671\u0644\u06e1\u0643\u064e\u0648\u064e\u0627\u0641\u0650\u0631\u0650 \u0648\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0648\u0627\u0652 \u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0641\u064e\u0642\u06e1\u062a\u064f\u0645\u06e1 \u0648\u064e\u0644\u06e1\u064a\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0648\u0627\u0652 \u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0641\u064e\u0642\u064f\u0648\u0627\u0652\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u06e1 \u062d\u064f\u0643\u06e1\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u062d\u06e1\u0643\u064f\u0645\u064f \u0628\u064e\u064a\u06e1\u0646\u064e\u0643\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064c \u062d\u064e\u0643\u0650\u064a\u0645\u065e",translation:"Wahai orang-orang yang beriman! Apabila perempuan-perempuan mukmin datang berhijrah kepadamu, maka hendaklah kamu uji (keimanan) mereka. Allah lebih mengetahui tentang keimanan mereka; jika kamu telah mengetahui bahwa mereka (benar-benar) beriman maka janganlah kamu kembalikan mereka kepada orang-orang kafir (suami-suami mereka). Mereka tidak halal bagi orang-orang kafir itu dan orang-orang kafir itu tidak halal bagi mereka. Dan berikanlah kepada (suami) mereka mahar yang telah mereka berikan. Dan tidak ada dosa bagimu menikahi mereka apabila kamu bayarkan kepada mereka maharnya. Dan janganlah kamu tetap berpegang pada tali (pernikahan) dengan perempuan-perempuan kafir; dan hendaklah kamu minta kembali mahar yang telah kamu berikan; dan (jika suaminya tetap kafir) biarkan mereka meminta kembali mahar yang telah mereka bayarkan (kepada mantan istrinya yang telah beriman). Demikianlah hukum Allah yang ditetapkan-Nya di antara kamu. Dan Allah Maha Mengetahui, Mahabijaksana"},{id:11,text:"\u0648\u064e\u0625\u0650\u0646 \u0641\u064e\u0627\u062a\u064e\u0643\u064f\u0645\u06e1 \u0634\u064e\u064a\u06e1\u0621\u065e \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u0650\u0643\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u0643\u064f\u0641\u0651\u064e\u0627\u0631\u0650 \u0641\u064e\u0639\u064e\u0627\u0642\u064e\u0628\u06e1\u062a\u064f\u0645\u06e1 \u0641\u064e\u0640\u0654\u064e\u0627\u062a\u064f\u0648\u0627\u0652 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0630\u064e\u0647\u064e\u0628\u064e\u062a\u06e1 \u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u064f\u0647\u064f\u0645 \u0645\u0651\u0650\u062b\u06e1\u0644\u064e \u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0641\u064e\u0642\u064f\u0648\u0627\u0652\u06da \u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064e\u0646\u062a\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6 \u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Dan jika ada sesuatu (pengembalian mahar) yang belum kamu selesaikan dari istri-istrimu yang lari kepada orang-orang kafir, lalu kamu dapat mengalahkan mereka maka berikanlah (dari harta rampasan) kepada orang-orang yang istrinya lari itu sebanyak mahar yang telah mereka berikan.839) Dan bertakwalah kamu kepada Allah yang kepada-Nya kamu beriman"},{id:12,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064f \u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u0643\u064e \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064e\u0670\u062a\u064f \u064a\u064f\u0628\u064e\u0627\u064a\u0650\u0639\u06e1\u0646\u064e\u0643\u064e \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0646 \u0644\u0651\u064e\u0627 \u064a\u064f\u0634\u06e1\u0631\u0650\u0643\u06e1\u0646\u064e \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u0631\u0650\u0642\u06e1\u0646\u064e \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0632\u06e1\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0642\u06e1\u062a\u064f\u0644\u06e1\u0646\u064e \u0623\u064e\u0648\u06e1\u0644\u064e\u0670\u062f\u064e\u0647\u064f\u0646\u0651\u064e \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u0646\u064e \u0628\u0650\u0628\u064f\u0647\u06e1\u062a\u064e\u0670\u0646\u0656 \u064a\u064e\u0641\u06e1\u062a\u064e\u0631\u0650\u064a\u0646\u064e\u0647\u064f\u06e5 \u0628\u064e\u064a\u06e1\u0646\u064e \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u0647\u0650\u0646\u0651\u064e \u0648\u064e\u0623\u064e\u0631\u06e1\u062c\u064f\u0644\u0650\u0647\u0650\u0646\u0651\u064e \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0635\u0650\u064a\u0646\u064e\u0643\u064e \u0641\u0650\u064a \u0645\u064e\u0639\u06e1\u0631\u064f\u0648\u0641\u0656 \u0641\u064e\u0628\u064e\u0627\u064a\u0650\u0639\u06e1\u0647\u064f\u0646\u0651\u064e \u0648\u064e\u0671\u0633\u06e1\u062a\u064e\u063a\u06e1\u0641\u0650\u0631\u06e1 \u0644\u064e\u0647\u064f\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u065e",translation:"Wahai Nabi! Apabila perempuan-perempuan mukmin datang kepadamu untuk mengadakan baiat (janji setia), bahwa mereka tidak akan mempersekutukan sesuatu apa pun dengan Allah; tidak akan mencuri, tidak akan berzina, tidak akan membunuh anak-anaknya, tidak akan berbuat dusta yang mereka ada-adakan antara tangan dan kaki mereka840) dan tidak akan mendurhakaimu dalam urusan yang baik, maka terimalah janji setia mereka dan mohonkanlah ampunan untuk mereka kepada Allah. Sungguh, Allah Maha Pengampun, Maha Penyayang"},{id:13,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u062a\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u06e1\u0627\u0652 \u0642\u064e\u0648\u06e1\u0645\u064b\u0627 \u063a\u064e\u0636\u0650\u0628\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0642\u064e\u062f\u06e1 \u064a\u064e\u0626\u0650\u0633\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0643\u064e\u0645\u064e\u0627 \u064a\u064e\u0626\u0650\u0633\u064e \u0671\u0644\u06e1\u0643\u064f\u0641\u0651\u064e\u0627\u0631\u064f \u0645\u0650\u0646\u06e1 \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u0650 \u0671\u0644\u06e1\u0642\u064f\u0628\u064f\u0648\u0631\u0650",translation:"Wahai orang-orang yang beriman! Janganlah kamu jadikan orang-orang yang dimurkai Allah sebagai penolongmu, sungguh, mereka telah putus asa terhadap akhirat sebagaimana orang-orang kafir yang telah berada dalam kubur juga berputus asa"}]},{id:61,name:"\u0627\u0644\u0635\u0641",transliteration:"As-Saf",translation:"Barisan",type:"medinan",total_verses:14,verses:[{id:1,text:"\u0633\u064e\u0628\u0651\u064e\u062d\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0671\u0644\u06e1\u062d\u064e\u0643\u0650\u064a\u0645\u064f",translation:"Apa yang ada di langit dan apa yang ada di bumi bertasbih kepada Allah; dan Dialah Yang Mahaperkasa, Mahabijaksana"},{id:2,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0644\u0650\u0645\u064e \u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u0644\u064e\u0627 \u062a\u064e\u0641\u06e1\u0639\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Wahai orang-orang yang beriman! Mengapa kamu mengatakan sesuatu yang tidak kamu kerjakan"},{id:3,text:"\u0643\u064e\u0628\u064f\u0631\u064e \u0645\u064e\u0642\u06e1\u062a\u064b\u0627 \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0646 \u062a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u0644\u064e\u0627 \u062a\u064e\u0641\u06e1\u0639\u064e\u0644\u064f\u0648\u0646\u064e",translation:"(Itu) sangatlah dibenci di sisi Allah jika kamu mengatakan apa-apa yang tidak kamu kerjakan"},{id:4,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0642\u064e\u0670\u062a\u0650\u0644\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650\u0647\u0650\u06e6 \u0635\u064e\u0641\u0651\u0657\u0627 \u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645 \u0628\u064f\u0646\u06e1\u064a\u064e\u0670\u0646\u065e \u0645\u0651\u064e\u0631\u06e1\u0635\u064f\u0648\u0635\u065e",translation:"Sesungguhnya Allah mencintai orang-orang yang berperang di jalan-Nya dalam barisan yang teratur, mereka seakan-akan seperti suatu bangunan yang tersusun kokoh"},{id:5,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0644\u0650\u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u06e6 \u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0644\u0650\u0645\u064e \u062a\u064f\u0624\u06e1\u0630\u064f\u0648\u0646\u064e\u0646\u0650\u064a \u0648\u064e\u0642\u064e\u062f \u062a\u0651\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0651\u0650\u064a \u0631\u064e\u0633\u064f\u0648\u0644\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1\u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0632\u064e\u0627\u063a\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0632\u064e\u0627\u063a\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0642\u064f\u0644\u064f\u0648\u0628\u064e\u0647\u064f\u0645\u06e1\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064e\u0647\u06e1\u062f\u0650\u064a \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0641\u064e\u0670\u0633\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Dan (ingatlah) ketika Musa berkata kepada kaumnya, \"Wahai kaumku! Mengapa kamu menyakitiku, padahal kamu sungguh mengetahui bahwa sesungguhnya aku utusan Allah kepadamu?\" Maka ketika mereka berpaling (dari kebenaran), Allah memalingkan hati mereka.841) Dan Allah tidak memberi petunjuk kepada kaum yang fasik"},{id:6,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e \u0639\u0650\u064a\u0633\u064e\u0649 \u0671\u0628\u06e1\u0646\u064f \u0645\u064e\u0631\u06e1\u064a\u064e\u0645\u064e \u064a\u064e\u0670\u0628\u064e\u0646\u0650\u064a\u0653 \u0625\u0650\u0633\u06e1\u0631\u064e\u0640\u0670\u0653\u0621\u0650\u064a\u0644\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0631\u064e\u0633\u064f\u0648\u0644\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064f\u0645 \u0645\u0651\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u0657\u0627 \u0644\u0651\u0650\u0645\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e \u064a\u064e\u062f\u064e\u064a\u0651\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u062a\u0651\u064e\u0648\u06e1\u0631\u064e\u0649\u0670\u0629\u0650 \u0648\u064e\u0645\u064f\u0628\u064e\u0634\u0651\u0650\u0631\u064e\u06e2\u0627 \u0628\u0650\u0631\u064e\u0633\u064f\u0648\u0644\u0656 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650\u064a \u0671\u0633\u06e1\u0645\u064f\u0647\u064f\u06e5\u0653 \u0623\u064e\u062d\u06e1\u0645\u064e\u062f\u064f\u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0650 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0647\u064e\u0670\u0630\u064e\u0627 \u0633\u0650\u062d\u06e1\u0631\u065e \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u065e",translation:"Dan (ingatlah) ketika Isa Putra Maryam berkata, \"Wahai Bani Israil! Sesungguhnya aku utusan Allah kepadamu, yang membenarkan kitab (yang turun) sebelumku, yaitu Taurat dan memberi kabar gembira dengan seorang rasul yang akan datang setelahku, yang namanya Ahmad (Muhammad).\" Namun ketika Rasul itu datang kepada mereka dengan membawa bukti-bukti yang nyata, mereka berkata, \"Ini adalah sihir yang nyata"},{id:7,text:"\u0648\u064e\u0645\u064e\u0646\u06e1 \u0623\u064e\u0638\u06e1\u0644\u064e\u0645\u064f \u0645\u0650\u0645\u0651\u064e\u0646\u0650 \u0671\u0641\u06e1\u062a\u064e\u0631\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u0643\u064e\u0630\u0650\u0628\u064e \u0648\u064e\u0647\u064f\u0648\u064e \u064a\u064f\u062f\u06e1\u0639\u064e\u0649\u0670\u0653 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u0625\u0650\u0633\u06e1\u0644\u064e\u0670\u0645\u0650\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064e\u0647\u06e1\u062f\u0650\u064a \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dan siapakah yang lebih zalim daripada orang yang mengada-adakan kebohongan terhadap Allah padahal dia diajak kepada (agama) Islam? Dan Allah tidak memberi petunjuk kepada orang-orang yang zalim"},{id:8,text:"\u064a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0644\u0650\u064a\u064f\u0637\u06e1\u0641\u0650\u0640\u0654\u064f\u0648\u0627\u0652 \u0646\u064f\u0648\u0631\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u0650\u0623\u064e\u0641\u06e1\u0648\u064e\u0670\u0647\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064f\u062a\u0650\u0645\u0651\u064f \u0646\u064f\u0648\u0631\u0650\u0647\u0650\u06e6 \u0648\u064e\u0644\u064e\u0648\u06e1 \u0643\u064e\u0631\u0650\u0647\u064e \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Mereka hendak memadamkan cahaya (agama) Allah dengan mulut (ucapan-ucapan) mereka, tetapi Allah tetap menyempurnakan cahaya-Nya meskipun orang-orang kafir membencinya"},{id:9,text:"\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f\u06e5 \u0628\u0650\u0671\u0644\u06e1\u0647\u064f\u062f\u064e\u0649\u0670 \u0648\u064e\u062f\u0650\u064a\u0646\u0650 \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0644\u0650\u064a\u064f\u0638\u06e1\u0647\u0650\u0631\u064e\u0647\u064f\u06e5 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u0650 \u0643\u064f\u0644\u0651\u0650\u0647\u0650\u06e6 \u0648\u064e\u0644\u064e\u0648\u06e1 \u0643\u064e\u0631\u0650\u0647\u064e \u0671\u0644\u06e1\u0645\u064f\u0634\u06e1\u0631\u0650\u0643\u064f\u0648\u0646\u064e",translation:"Dialah yang mengutus Rasul-Nya dengan membawa petunjuk dan agama yang benar, untuk memenangkannya di atas segala agama meskipun orang-orang musyrik membencinya"},{id:10,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0647\u064e\u0644\u06e1 \u0623\u064e\u062f\u064f\u0644\u0651\u064f\u0643\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u062a\u0650\u062c\u064e\u0670\u0631\u064e\u0629\u0656 \u062a\u064f\u0646\u062c\u0650\u064a\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064d \u0623\u064e\u0644\u0650\u064a\u0645\u0656",translation:"Wahai orang-orang yang beriman! Maukah kamu Aku tunjukkan suatu perdagangan yang dapat menyelamatkan kamu dari azab yang pedih"},{id:11,text:"\u062a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650\u06e6 \u0648\u064e\u062a\u064f\u062c\u064e\u0670\u0647\u0650\u062f\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u0650\u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u06e1\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u06e1 \u062e\u064e\u064a\u06e1\u0631\u065e \u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"(Yaitu) kamu beriman kepada Allah dan Rasul-Nya dan berjihad di jalan Allah dengan harta dan jiwamu. Itulah yang lebih baik bagi kamu jika kamu mengetahui"},{id:12,text:"\u064a\u064e\u063a\u06e1\u0641\u0650\u0631\u06e1 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0630\u064f\u0646\u064f\u0648\u0628\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u064a\u064f\u062f\u06e1\u062e\u0650\u0644\u06e1\u0643\u064f\u0645\u06e1 \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0656 \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0645\u0650\u0646 \u062a\u064e\u062d\u06e1\u062a\u0650\u0647\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u064f \u0648\u064e\u0645\u064e\u0633\u064e\u0670\u0643\u0650\u0646\u064e \u0637\u064e\u064a\u0651\u0650\u0628\u064e\u0629\u0657 \u0641\u0650\u064a \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0650 \u0639\u064e\u062f\u06e1\u0646\u0656\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0671\u0644\u06e1\u0641\u064e\u0648\u06e1\u0632\u064f \u0671\u0644\u06e1\u0639\u064e\u0638\u0650\u064a\u0645\u064f",translation:"niscaya Allah mengampuni dosa-dosamu dan memasukkan kamu ke dalam surga yang mengalir di bawahnya sungai-sungai, dan ke tempat-tempat tinggal yang baik di dalam surga '\u0100dn. Itulah kemenangan yang agung"},{id:13,text:"\u0648\u064e\u0623\u064f\u062e\u06e1\u0631\u064e\u0649\u0670 \u062a\u064f\u062d\u0650\u0628\u0651\u064f\u0648\u0646\u064e\u0647\u064e\u0627\u06d6 \u0646\u064e\u0635\u06e1\u0631\u065e \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0641\u064e\u062a\u06e1\u062d\u065e \u0642\u064e\u0631\u0650\u064a\u0628\u065e\u06d7 \u0648\u064e\u0628\u064e\u0634\u0651\u0650\u0631\u0650 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Dan (ada lagi) karunia lain yang kamu sukai (yaitu) pertolongan dari Allah dan kemenangan yang dekat (waktunya). Dan sampaikanlah berita gembira kepada orang-orang mukmin"},{id:14,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0643\u064f\u0648\u0646\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0635\u064e\u0627\u0631\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u0645\u064e\u0627 \u0642\u064e\u0627\u0644\u064e \u0639\u0650\u064a\u0633\u064e\u0649 \u0671\u0628\u06e1\u0646\u064f \u0645\u064e\u0631\u06e1\u064a\u064e\u0645\u064e \u0644\u0650\u0644\u06e1\u062d\u064e\u0648\u064e\u0627\u0631\u0650\u064a\u0651\u0650\u0640\u06e7\u0646\u064e \u0645\u064e\u0646\u06e1 \u0623\u064e\u0646\u0635\u064e\u0627\u0631\u0650\u064a\u0653 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0642\u064e\u0627\u0644\u064e \u0671\u0644\u06e1\u062d\u064e\u0648\u064e\u0627\u0631\u0650\u064a\u0651\u064f\u0648\u0646\u064e \u0646\u064e\u062d\u06e1\u0646\u064f \u0623\u064e\u0646\u0635\u064e\u0627\u0631\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0641\u064e\u0640\u0654\u064e\u0627\u0645\u064e\u0646\u064e\u062a \u0637\u0651\u064e\u0627\u0653\u0626\u0650\u0641\u064e\u0629\u065e \u0645\u0651\u0650\u0646\u06e2 \u0628\u064e\u0646\u0650\u064a\u0653 \u0625\u0650\u0633\u06e1\u0631\u064e\u0640\u0670\u0653\u0621\u0650\u064a\u0644\u064e \u0648\u064e\u0643\u064e\u0641\u064e\u0631\u064e\u062a \u0637\u0651\u064e\u0627\u0653\u0626\u0650\u0641\u064e\u0629\u065e\u06d6 \u0641\u064e\u0623\u064e\u064a\u0651\u064e\u062f\u06e1\u0646\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0639\u064e\u062f\u064f\u0648\u0651\u0650\u0647\u0650\u0645\u06e1 \u0641\u064e\u0623\u064e\u0635\u06e1\u0628\u064e\u062d\u064f\u0648\u0627\u0652 \u0638\u064e\u0670\u0647\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Wahai orang-orang yang beriman! Jadilah kamu penolong-penolong (agama) Allah sebagaimana Isa putra Maryam telah berkata kepada pengikut-pengikutnya yang setia, \"Siapakah yang akan menjadi penolong-penolongku (untuk menegakkan agama) Allah?\" Pengikut-pengikutnya yang setia itu berkata, \"Kamilah penolong-penolong (agama) Allah,\" lalu segolongan dari Bani Israil beriman dan segolongan (yang lain) kafir; lalu Kami berikan kekuatan kepada orang-orang yang beriman terhadap musuh-musuh mereka, sehingga mereka menjadi orang-orang yang menang"}]},{id:62,name:"\u0627\u0644\u062c\u0645\u0639\u0629",transliteration:"Al-Jumu'ah",translation:"Hari Jum\\'at",type:"medinan",total_verses:11,verses:[{id:1,text:"\u064a\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0671\u0644\u06e1\u0645\u064e\u0644\u0650\u0643\u0650 \u0671\u0644\u06e1\u0642\u064f\u062f\u0651\u064f\u0648\u0633\u0650 \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u0650 \u0671\u0644\u06e1\u062d\u064e\u0643\u0650\u064a\u0645\u0650",translation:"Apa yang ada di langit dan apa yang ada di bumi senantiasa bertasbih kepada Allah. Maharaja, Yang Mahasuci, Yang Mahaperkasa, Mahabijaksana"},{id:2,text:"\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0628\u064e\u0639\u064e\u062b\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064f\u0645\u0651\u0650\u064a\u0651\u0650\u0640\u06e7\u0646\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u0657\u0627 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u064a\u064e\u062a\u06e1\u0644\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0647\u0650\u06e6 \u0648\u064e\u064a\u064f\u0632\u064e\u0643\u0651\u0650\u064a\u0647\u0650\u0645\u06e1 \u0648\u064e\u064a\u064f\u0639\u064e\u0644\u0651\u0650\u0645\u064f\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0648\u064e\u0671\u0644\u06e1\u062d\u0650\u0643\u06e1\u0645\u064e\u0629\u064e \u0648\u064e\u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f \u0644\u064e\u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0670\u0644\u0656 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u0656",translation:"Dialah yang mengutus seorang Rasul kepada kaum yang buta huruf dari kalangan mereka sendiri, yang membacakan kepada mereka ayat-ayat-Nya, menyucikan (jiwa) mereka dan mengajarkan kepada mereka Kitab dan Hikmah (Sunah), meskipun sebelumnya, mereka benar-benar dalam kesesatan yang nyata"},{id:3,text:"\u0648\u064e\u0621\u064e\u0627\u062e\u064e\u0631\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0644\u064e\u0645\u0651\u064e\u0627 \u064a\u064e\u0644\u06e1\u062d\u064e\u0642\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u0645\u06e1\u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0671\u0644\u06e1\u062d\u064e\u0643\u0650\u064a\u0645\u064f",translation:"dan (juga) kepada kaum yang lain dari mereka yang belum bertemu dengan mereka. Dan Dialah Yang Mahaperkasa, Mahabijaksana"},{id:4,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u0636\u06e1\u0644\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064f\u0624\u06e1\u062a\u0650\u064a\u0647\u0650 \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0630\u064f\u0648 \u0671\u0644\u06e1\u0641\u064e\u0636\u06e1\u0644\u0650 \u0671\u0644\u06e1\u0639\u064e\u0638\u0650\u064a\u0645\u0650",translation:"Demikianlah karunia Allah, yang diberikan kepada siapa yang Dia kehendaki; dan Allah memiliki karunia yang besar"},{id:5,text:"\u0645\u064e\u062b\u064e\u0644\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062d\u064f\u0645\u0651\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u062a\u0651\u064e\u0648\u06e1\u0631\u064e\u0649\u0670\u0629\u064e \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0645\u06e1 \u064a\u064e\u062d\u06e1\u0645\u0650\u0644\u064f\u0648\u0647\u064e\u0627 \u0643\u064e\u0645\u064e\u062b\u064e\u0644\u0650 \u0671\u0644\u06e1\u062d\u0650\u0645\u064e\u0627\u0631\u0650 \u064a\u064e\u062d\u06e1\u0645\u0650\u0644\u064f \u0623\u064e\u0633\u06e1\u0641\u064e\u0627\u0631\u064e\u06e2\u0627\u06da \u0628\u0650\u0626\u06e1\u0633\u064e \u0645\u064e\u062b\u064e\u0644\u064f \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064e\u0647\u06e1\u062f\u0650\u064a \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Perumpamaan orang-orang yang diberi tugas membawa Taurat, kemudian mereka tidak membawanya (tidak mengamalkannya) adalah seperti keledai yang membawa kitab-kitab yang tebal. Sangat buruk perumpamaan kaum yang mendustakan ayat-ayat Allah. Dan Allah tidak memberi petunjuk kepada orang-orang yang zalim"},{id:6,text:"\u0642\u064f\u0644\u06e1 \u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064e\u0627\u062f\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646 \u0632\u064e\u0639\u064e\u0645\u06e1\u062a\u064f\u0645\u06e1 \u0623\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u0648\u06e1\u0644\u0650\u064a\u064e\u0627\u0653\u0621\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0641\u064e\u062a\u064e\u0645\u064e\u0646\u0651\u064e\u0648\u064f\u0627\u0652 \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u064e \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0635\u064e\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Katakanlah (Muhammad), \"Wahai orang-orang Yahudi! Jika kamu mengira bahwa kamulah kekasih Allah, bukan orang-orang yang lain, maka harapkanlah kematianmu, jika kamu orang yang benar"},{id:7,text:"\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062a\u064e\u0645\u064e\u0646\u0651\u064e\u0648\u06e1\u0646\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u0628\u064e\u062f\u064e\u06e2\u0627 \u0628\u0650\u0645\u064e\u0627 \u0642\u064e\u062f\u0651\u064e\u0645\u064e\u062a\u06e1 \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u0647\u0650\u0645\u06e1\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064f\u06e2 \u0628\u0650\u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dan mereka tidak akan mengharapkan kematian itu selamanya disebabkan kejahatan yang telah mereka perbuat dengan tangan mereka sendiri. Dan Allah Maha Mengetahui orang-orang yang zalim"},{id:8,text:"\u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062a\u064e\u0641\u0650\u0631\u0651\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u06e1\u0647\u064f \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0645\u064f\u0644\u064e\u0670\u0642\u0650\u064a\u0643\u064f\u0645\u06e1\u06d6 \u062b\u064f\u0645\u0651\u064e \u062a\u064f\u0631\u064e\u062f\u0651\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0639\u064e\u0670\u0644\u0650\u0645\u0650 \u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u0628\u0650 \u0648\u064e\u0671\u0644\u0634\u0651\u064e\u0647\u064e\u0670\u062f\u064e\u0629\u0650 \u0641\u064e\u064a\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0643\u064f\u0645 \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Katakanlah, \"Sesungguhnya kematian yang kamu lari dari padanya, ia pasti menemui kamu, kemudian kamu akan dikembalikan kepada (Allah), yang mengetahui yang gaib dan yang nyata, lalu Dia beritakan kepadamu apa yang telah kamu kerjakan"},{id:9,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0630\u064e\u0627 \u0646\u064f\u0648\u062f\u0650\u064a\u064e \u0644\u0650\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u0650 \u0645\u0650\u0646 \u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u062c\u064f\u0645\u064f\u0639\u064e\u0629\u0650 \u0641\u064e\u0671\u0633\u06e1\u0639\u064e\u0648\u06e1\u0627\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0630\u0650\u0643\u06e1\u0631\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0630\u064e\u0631\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0628\u064e\u064a\u06e1\u0639\u064e\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u06e1 \u062e\u064e\u064a\u06e1\u0631\u065e \u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Wahai orang-orang yang beriman! Apabila telah diseru untuk melaksanakan salat pada hari Jumat, maka segeralah kamu mengingat Allah dan tinggalkanlah jual beli. Yang demikian itu lebih baik bagimu jika kamu mengetahui"},{id:10,text:"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u064f\u0636\u0650\u064a\u064e\u062a\u0650 \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064f \u0641\u064e\u0671\u0646\u062a\u064e\u0634\u0650\u0631\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0671\u0628\u06e1\u062a\u064e\u063a\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0641\u064e\u0636\u06e1\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0671\u0630\u06e1\u0643\u064f\u0631\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u0657\u0627 \u0644\u0651\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062a\u064f\u0641\u06e1\u0644\u0650\u062d\u064f\u0648\u0646\u064e",translation:"Apabila salat telah dilaksanakan, maka bertebaranlah kamu di bumi; carilah karunia Allah dan ingatlah Allah banyak-banyak agar kamu beruntung"},{id:11,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0631\u064e\u0623\u064e\u0648\u06e1\u0627\u0652 \u062a\u0650\u062c\u064e\u0670\u0631\u064e\u0629\u064b \u0623\u064e\u0648\u06e1 \u0644\u064e\u0647\u06e1\u0648\u064b\u0627 \u0671\u0646\u0641\u064e\u0636\u0651\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u064e\u0627 \u0648\u064e\u062a\u064e\u0631\u064e\u0643\u064f\u0648\u0643\u064e \u0642\u064e\u0627\u0653\u0626\u0650\u0645\u0657\u0627\u06da \u0642\u064f\u0644\u06e1 \u0645\u064e\u0627 \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062e\u064e\u064a\u06e1\u0631\u065e \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u06e1\u0648\u0650 \u0648\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u062a\u0651\u0650\u062c\u064e\u0670\u0631\u064e\u0629\u0650\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u062e\u064e\u064a\u06e1\u0631\u064f \u0671\u0644\u0631\u0651\u064e\u0640\u0670\u0632\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Dan apabila mereka melihat perdagangan atau permainan, mereka segera menuju kepadanya dan mereka tinggalkan engkau (Muhammad) sedang berdiri (berkhotbah). Katakanlah, \"Apa yang ada di sisi Allah lebih baik daripada permainan dan perdagangan,\" dan Allah Pemberi rezeki yang terbaik"}]},{id:63,name:"\u0627\u0644\u0645\u0646\u0627\u0641\u0642\u0648\u0646",transliteration:"Al-Munafiqun",translation:"Kaum Munafik",type:"medinan",total_verses:11,verses:[{id:1,text:"\u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u0643\u064e \u0671\u0644\u06e1\u0645\u064f\u0646\u064e\u0670\u0641\u0650\u0642\u064f\u0648\u0646\u064e \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0646\u064e\u0634\u06e1\u0647\u064e\u062f\u064f \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d7 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0647\u064f\u06e5 \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064e\u0634\u06e1\u0647\u064e\u062f\u064f \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0645\u064f\u0646\u064e\u0670\u0641\u0650\u0642\u0650\u064a\u0646\u064e \u0644\u064e\u0643\u064e\u0670\u0630\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Apabila orang-orang munafik datang kepadamu (Muhammad), mereka berkata, \"Kami mengakui, bahwa engkau adalah Rasul Allah.\" Dan Allah mengetahui bahwa engkau benar-benar Rasul-Nya; dan Allah menyaksikan bahwa orang-orang munafik itu benar-benar pendusta"},{id:2,text:"\u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u064e\u0647\u064f\u0645\u06e1 \u062c\u064f\u0646\u0651\u064e\u0629\u0657 \u0641\u064e\u0635\u064e\u062f\u0651\u064f\u0648\u0627\u0652 \u0639\u064e\u0646 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0633\u064e\u0627\u0653\u0621\u064e \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"(Mereka menjadikan sumpah-sumpah mereka sebagai perisai,842) lalu mereka menghalang-halangi (manusia) dari jalan Allah. Sungguh, betapa buruknya apa yang telah mereka kerjakan"},{id:3,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u062b\u064f\u0645\u0651\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0641\u064e\u0637\u064f\u0628\u0650\u0639\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u06e1 \u0641\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064e\u0641\u06e1\u0642\u064e\u0647\u064f\u0648\u0646\u064e",translation:"Yang demikian itu karena sesungguhnya mereka telah beriman, kemudian menjadi kafir, maka hati mereka dikunci, sehingga mereka tidak dapat mengerti"},{id:4,text:"\u06de\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0631\u064e\u0623\u064e\u064a\u06e1\u062a\u064e\u0647\u064f\u0645\u06e1 \u062a\u064f\u0639\u06e1\u062c\u0650\u0628\u064f\u0643\u064e \u0623\u064e\u062c\u06e1\u0633\u064e\u0627\u0645\u064f\u0647\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0625\u0650\u0646 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627\u0652 \u062a\u064e\u0633\u06e1\u0645\u064e\u0639\u06e1 \u0644\u0650\u0642\u064e\u0648\u06e1\u0644\u0650\u0647\u0650\u0645\u06e1\u06d6 \u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u062e\u064f\u0634\u064f\u0628\u065e \u0645\u0651\u064f\u0633\u064e\u0646\u0651\u064e\u062f\u064e\u0629\u065e\u06d6 \u064a\u064e\u062d\u06e1\u0633\u064e\u0628\u064f\u0648\u0646\u064e \u0643\u064f\u0644\u0651\u064e \u0635\u064e\u064a\u06e1\u062d\u064e\u0629\u064d \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1\u06da \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0639\u064e\u062f\u064f\u0648\u0651\u064f \u0641\u064e\u0671\u062d\u06e1\u0630\u064e\u0631\u06e1\u0647\u064f\u0645\u06e1\u06da \u0642\u064e\u0670\u062a\u064e\u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06d6 \u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u064a\u064f\u0624\u06e1\u0641\u064e\u0643\u064f\u0648\u0646\u064e",translation:"(Dan apabila engkau melihat mereka, tubuh mereka mengagumkanmu. Dan jika mereka berkata, engkau mendengarkan tutur katanya. Mereka seakan-akan kayu yang tersandar.843) Mereka mengira bahwa setiap teriakan ditujukan kepada mereka. Mereka itulah musuh (yang sebenarnya), maka waspadalah terhadap mereka; semoga Allah membinasakan mereka. Bagaimanakah mereka dapat dipalingkan (dari kebenaran)"},{id:5,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0648\u06e1\u0627\u0652 \u064a\u064e\u0633\u06e1\u062a\u064e\u063a\u06e1\u0641\u0650\u0631\u06e1 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0631\u064e\u0633\u064f\u0648\u0644\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0648\u0651\u064e\u0648\u06e1\u0627\u0652 \u0631\u064f\u0621\u064f\u0648\u0633\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0631\u064e\u0623\u064e\u064a\u06e1\u062a\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0635\u064f\u062f\u0651\u064f\u0648\u0646\u064e \u0648\u064e\u0647\u064f\u0645 \u0645\u0651\u064f\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Dan apabila dikatakan kepada mereka, \"Marilah (beriman), agar Rasulullah memohonkan ampunan bagimu,\" mereka membuang muka dan engkau lihat mereka berpaling dengan menyombongkan diri"},{id:6,text:"\u0633\u064e\u0648\u064e\u0627\u0653\u0621\u064c \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0623\u064e\u0633\u06e1\u062a\u064e\u063a\u06e1\u0641\u064e\u0631\u06e1\u062a\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u0645\u06e1 \u0644\u064e\u0645\u06e1 \u062a\u064e\u0633\u06e1\u062a\u064e\u063a\u06e1\u0641\u0650\u0631\u06e1 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0646 \u064a\u064e\u063a\u06e1\u0641\u0650\u0631\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0647\u064f\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064e\u0647\u06e1\u062f\u0650\u064a \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0641\u064e\u0670\u0633\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Sama saja bagi mereka, engkau (Muhammad) mohonkan ampunan untuk mereka atau tidak engkau mohonkan ampunan bagi mereka, Allah tidak akan mengampuni mereka; sesungguhnya Allah tidak akan memberi petunjuk kepada orang-orang yang fasik"},{id:7,text:"\u0647\u064f\u0645\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0644\u064e\u0627 \u062a\u064f\u0646\u0641\u0650\u0642\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0646\u06e1 \u0639\u0650\u0646\u062f\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0646\u0641\u064e\u0636\u0651\u064f\u0648\u0627\u0652\u06d7 \u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u062e\u064e\u0632\u064e\u0627\u0653\u0626\u0650\u0646\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0645\u064f\u0646\u064e\u0670\u0641\u0650\u0642\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u0641\u06e1\u0642\u064e\u0647\u064f\u0648\u0646\u064e",translation:"Mereka yang berkata (kepada orang-orang Ansar), \"Janganlah kamu bersedekah kepada orang-orang (Muhajirin) yang ada di sisi Rasulullah sampai mereka bubar (meninggalkan Rasulullah).\" Padahal milik Allah lah perbendaharaan langit dan bumi, tetapi orang-orang munafik itu tidak memahami"},{id:8,text:"\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0644\u064e\u0626\u0650\u0646 \u0631\u0651\u064e\u062c\u064e\u0639\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u0645\u064e\u062f\u0650\u064a\u0646\u064e\u0629\u0650 \u0644\u064e\u064a\u064f\u062e\u06e1\u0631\u0650\u062c\u064e\u0646\u0651\u064e \u0671\u0644\u06e1\u0623\u064e\u0639\u064e\u0632\u0651\u064f \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0630\u064e\u0644\u0651\u064e\u06da \u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u0639\u0650\u0632\u0651\u064e\u0629\u064f \u0648\u064e\u0644\u0650\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650\u06e6 \u0648\u064e\u0644\u0650\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0645\u064f\u0646\u064e\u0670\u0641\u0650\u0642\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Mereka berkata, \"Sungguh, jika kita kembali ke Madinah (kembali dari perang Bani Mustalik), pastilah orang yang kuat akan mengusir orang-orang yang lemah dari sana.\" Padahal kekuatan itu hanyalah bagi Allah, Rasul-Nya dan bagi orang-orang mukmin, tetapi orang-orang munafik itu tidak mengetahui"},{id:9,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u062a\u064f\u0644\u06e1\u0647\u0650\u0643\u064f\u0645\u06e1 \u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u064f\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064e\u0648\u06e1\u0644\u064e\u0670\u062f\u064f\u0643\u064f\u0645\u06e1 \u0639\u064e\u0646 \u0630\u0650\u0643\u06e1\u0631\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0641\u06e1\u0639\u064e\u0644\u06e1 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u062e\u064e\u0670\u0633\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Wahai orang-orang yang beriman! Janganlah harta bendamu dan anak-anakmu melalaikan kamu dari mengingat Allah. Dan barangsiapa berbuat demikian, maka mereka itulah orang-orang yang rugi"},{id:10,text:"\u0648\u064e\u0623\u064e\u0646\u0641\u0650\u0642\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0645\u0651\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u06e1\u0646\u064e\u0670\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650 \u0623\u064e\u0646 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e \u0623\u064e\u062d\u064e\u062f\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u064f \u0641\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0644\u064e\u0648\u06e1\u0644\u064e\u0627\u0653 \u0623\u064e\u062e\u0651\u064e\u0631\u06e1\u062a\u064e\u0646\u0650\u064a\u0653 \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u062c\u064e\u0644\u0656 \u0642\u064e\u0631\u0650\u064a\u0628\u0656 \u0641\u064e\u0623\u064e\u0635\u0651\u064e\u062f\u0651\u064e\u0642\u064e \u0648\u064e\u0623\u064e\u0643\u064f\u0646 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u0650\u064a\u0646\u064e",translation:"Dan infakkanlah sebagian dari apa yang telah Kami berikan kepadamu sebelum kematian datang kepada salah seorang di antara kamu; lalu dia berkata (menyesali), \"Ya Tuhanku, sekiranya Engkau berkenan menunda (kematian)ku sedikit waktu lagi, maka aku dapat bersedekah dan aku akan termasuk orang-orang yang saleh"},{id:11,text:"\u0648\u064e\u0644\u064e\u0646 \u064a\u064f\u0624\u064e\u062e\u0651\u0650\u0631\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0646\u064e\u0641\u06e1\u0633\u064b\u0627 \u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e \u0623\u064e\u062c\u064e\u0644\u064f\u0647\u064e\u0627\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u062e\u064e\u0628\u0650\u064a\u0631\u064f\u06e2 \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Dan Allah tidak akan menunda (kematian) seseorang apabila waktu kematiannya telah datang. Dan Allah Mahateliti terhadap apa yang kamu kerjakan"}]},{id:64,name:"\u0627\u0644\u062a\u063a\u0627\u0628\u0646",transliteration:"At-Taghabun",translation:"Hari Dinampakkan Kesalahan",type:"medinan",total_verses:18,verses:[{id:1,text:"\u064a\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u064f \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06d6 \u0644\u064e\u0647\u064f \u0671\u0644\u06e1\u0645\u064f\u0644\u06e1\u0643\u064f \u0648\u064e\u0644\u064e\u0647\u064f \u0671\u0644\u06e1\u062d\u064e\u0645\u06e1\u062f\u064f\u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0642\u064e\u062f\u0650\u064a\u0631\u064c",translation:"Apa yang ada di langit dan apa yang ada di bumi senantiasa bertasbih kepada Allah; milik-Nya semua kerajaan dan bagi-Nya (pula) segala puji; dan Dia Mahakuasa atas segala sesuatu"},{id:2,text:"\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e\u0643\u064f\u0645\u06e1 \u0641\u064e\u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u0643\u064e\u0627\u0641\u0650\u0631\u065e \u0648\u064e\u0645\u0650\u0646\u0643\u064f\u0645 \u0645\u0651\u064f\u0624\u06e1\u0645\u0650\u0646\u065e\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u0628\u064e\u0635\u0650\u064a\u0631\u064c",translation:"Dialah yang menciptakan kamu, lalu di antara kamu ada yang kafir dan di antara kamu (juga) ada yang mukmin. Dan Allah Maha Melihat apa yang kamu kerjakan"},{id:3,text:"\u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0635\u064e\u0648\u0651\u064e\u0631\u064e\u0643\u064f\u0645\u06e1 \u0641\u064e\u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064e \u0635\u064f\u0648\u064e\u0631\u064e\u0643\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0671\u0644\u06e1\u0645\u064e\u0635\u0650\u064a\u0631\u064f",translation:"Dia menciptakan langit dan bumi dengan (tujuan) yang benar, Dia membentuk rupamu lalu memperbagus rupamu, dan kepada-Nya tempat kembali"},{id:4,text:"\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u062a\u064f\u0633\u0650\u0631\u0651\u064f\u0648\u0646\u064e \u0648\u064e\u0645\u064e\u0627 \u062a\u064f\u0639\u06e1\u0644\u0650\u0646\u064f\u0648\u0646\u064e\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u0650\u064a\u0645\u064f\u06e2 \u0628\u0650\u0630\u064e\u0627\u062a\u0650 \u0671\u0644\u0635\u0651\u064f\u062f\u064f\u0648\u0631\u0650",translation:"Dia mengetahui apa yang ada di langit dan di bumi, dan mengetahui apa yang kamu rahasiakan dan apa yang kamu nyatakan. Dan Allah Maha Mengetahui segala isi hati"},{id:5,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0623\u06e1\u062a\u0650\u0643\u064f\u0645\u06e1 \u0646\u064e\u0628\u064e\u0624\u064f\u0627\u0652 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u064f \u0641\u064e\u0630\u064e\u0627\u0642\u064f\u0648\u0627\u0652 \u0648\u064e\u0628\u064e\u0627\u0644\u064e \u0623\u064e\u0645\u06e1\u0631\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Apakah belum sampai kepadamu (orang-orang kafir) berita orang-orang kafir dahulu? Maka mereka telah merasakan akibat buruk dari perbuatannya dan mereka memperoleh azab yang pedih"},{id:6,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u06e5 \u0643\u064e\u0627\u0646\u064e\u062a \u062a\u0651\u064e\u0623\u06e1\u062a\u0650\u064a\u0647\u0650\u0645\u06e1 \u0631\u064f\u0633\u064f\u0644\u064f\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0650 \u0641\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0628\u064e\u0634\u064e\u0631\u065e \u064a\u064e\u0647\u06e1\u062f\u064f\u0648\u0646\u064e\u0646\u064e\u0627 \u0641\u064e\u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0648\u0627\u0652\u06d6 \u0648\u0651\u064e\u0671\u0633\u06e1\u062a\u064e\u063a\u06e1\u0646\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0646\u0650\u064a\u0651\u064c \u062d\u064e\u0645\u0650\u064a\u062f\u065e",translation:"Yang demikian itu karena sesungguhnya ketika rasul-rasul datang kepada mereka membawa keterangan-keterangan, lalu mereka berkata, \"Apakah (pantas) manusia yang memberi petunjuk kepada kami?\" Lalu mereka ingkar dan berpaling; padahal Allah tidak memerlukan (mereka). Dan Allah Mahakaya, Maha Terpuji"},{id:7,text:"\u0632\u064e\u0639\u064e\u0645\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646 \u0644\u0651\u064e\u0646 \u064a\u064f\u0628\u06e1\u0639\u064e\u062b\u064f\u0648\u0627\u0652\u06da \u0642\u064f\u0644\u06e1 \u0628\u064e\u0644\u064e\u0649\u0670 \u0648\u064e\u0631\u064e\u0628\u0651\u0650\u064a \u0644\u064e\u062a\u064f\u0628\u06e1\u0639\u064e\u062b\u064f\u0646\u0651\u064e \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u062a\u064f\u0646\u064e\u0628\u0651\u064e\u0624\u064f\u0646\u0651\u064e \u0628\u0650\u0645\u064e\u0627 \u0639\u064e\u0645\u0650\u0644\u06e1\u062a\u064f\u0645\u06e1\u06da \u0648\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u0633\u0650\u064a\u0631\u065e",translation:"Orang-orang yang kafir mengira, bahwa mereka tidak akan dibangkitkan. Katakanlah (Muhammad), \"Tidak demikian, demi Tuhanku, kamu pasti dibangkitkan, kemudian diberitakan semua yang telah kamu kerjakan.\" Dan yang demikian itu mudah bagi Allah"},{id:8,text:"\u0641\u064e\u0640\u0654\u064e\u0627\u0645\u0650\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650\u06e6 \u0648\u064e\u0671\u0644\u0646\u0651\u064f\u0648\u0631\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0627\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e \u062e\u064e\u0628\u0650\u064a\u0631\u065e",translation:"Maka berimanlah kamu kepada Allah dan Rasul-Nya dan kepada cahaya (Alquran) yang telah Kami turunkan. Dan Allah Mahateliti terhadap apa yang kamu kerjakan"},{id:9,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064e\u062c\u06e1\u0645\u064e\u0639\u064f\u0643\u064f\u0645\u06e1 \u0644\u0650\u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u062c\u064e\u0645\u06e1\u0639\u0650\u06d6 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064e\u0648\u06e1\u0645\u064f \u0671\u0644\u062a\u0651\u064e\u063a\u064e\u0627\u0628\u064f\u0646\u0650\u06d7 \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u06e2 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u06e1 \u0635\u064e\u0670\u0644\u0650\u062d\u0657\u0627 \u064a\u064f\u0643\u064e\u0641\u0651\u0650\u0631\u06e1 \u0639\u064e\u0646\u06e1\u0647\u064f \u0633\u064e\u064a\u0651\u0650\u0640\u0654\u064e\u0627\u062a\u0650\u0647\u0650\u06e6 \u0648\u064e\u064a\u064f\u062f\u06e1\u062e\u0650\u0644\u06e1\u0647\u064f \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0656 \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0645\u0650\u0646 \u062a\u064e\u062d\u06e1\u062a\u0650\u0647\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u064f \u062e\u064e\u0670\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627\u0653 \u0623\u064e\u0628\u064e\u062f\u0657\u0627\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0671\u0644\u06e1\u0641\u064e\u0648\u06e1\u0632\u064f \u0671\u0644\u06e1\u0639\u064e\u0638\u0650\u064a\u0645\u064f",translation:"(Ingatlah) pada hari (ketika) Allah mengumpulkan kamu pada hari berhimpun, itulah hari pengungkapan kesalahan-kesalahan. Dan barangsiapa beriman kepada Allah dan mengerjakan kebajikan niscaya Allah akan menghapus kesalahan-kesalahannya dan memasukkannya ke dalam surga yang mengalir di bawahnya sungai-sungai, mereka kekal di dalamnya selama-lamanya. Itulah kemenangan yang agung"},{id:10,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627\u0653 \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u062e\u064e\u0670\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627\u06d6 \u0648\u064e\u0628\u0650\u0626\u06e1\u0633\u064e \u0671\u0644\u06e1\u0645\u064e\u0635\u0650\u064a\u0631\u064f",translation:"Dan orang-orang yang kafir dan mendustakan ayat-ayat Kami, mereka itulah penghuni neraka, mereka kekal di dalamnya. Dan itulah seburuk-buruk tempat kembali"},{id:11,text:"\u0645\u064e\u0627\u0653 \u0623\u064e\u0635\u064e\u0627\u0628\u064e \u0645\u0650\u0646 \u0645\u0651\u064f\u0635\u0650\u064a\u0628\u064e\u0629\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0625\u0650\u0630\u06e1\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d7 \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u06e2 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u0647\u06e1\u062f\u0650 \u0642\u064e\u0644\u06e1\u0628\u064e\u0647\u064f\u06e5\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Tidak ada suatu musibah yang menimpa (seseorang), kecuali dengan izin Allah; dan barangsiapa beriman kepada Allah, niscaya Allah akan memberi petunjuk kepada hatinya. Dan Allah Maha Mengetahui segala sesuatu"},{id:12,text:"\u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0627\u0652 \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e\u06da \u0641\u064e\u0625\u0650\u0646 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u064a\u06e1\u062a\u064f\u0645\u06e1 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0646\u064e\u0627 \u0671\u0644\u06e1\u0628\u064e\u0644\u064e\u0670\u063a\u064f \u0671\u0644\u06e1\u0645\u064f\u0628\u0650\u064a\u0646\u064f",translation:"Dan taatlah kepada Allah dan taatlah kepada Rasul. Jika kamu berpaling maka sesungguhnya kewajiban Rasul Kami hanyalah menyampaikan (amanah Allah) dengan terang"},{id:13,text:"\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e\u06da \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0644\u06e1\u064a\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u0650 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"(Dialah) Allah, tidak ada tuhan selain Dia. Dan hendaklah orang-orang mukmin bertawakal kepada Allah"},{id:14,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e \u0645\u0650\u0646\u06e1 \u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0648\u06e1\u0644\u064e\u0670\u062f\u0650\u0643\u064f\u0645\u06e1 \u0639\u064e\u062f\u064f\u0648\u0651\u0657\u0627 \u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u0641\u064e\u0671\u062d\u06e1\u0630\u064e\u0631\u064f\u0648\u0647\u064f\u0645\u06e1\u06da \u0648\u064e\u0625\u0650\u0646 \u062a\u064e\u0639\u06e1\u0641\u064f\u0648\u0627\u0652 \u0648\u064e\u062a\u064e\u0635\u06e1\u0641\u064e\u062d\u064f\u0648\u0627\u0652 \u0648\u064e\u062a\u064e\u063a\u06e1\u0641\u0650\u0631\u064f\u0648\u0627\u0652 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064c",translation:"(Wahai orang-orang yang beriman! Sesungguhnya di antara istri-istrimu dan anak-anakmu ada yang menjadi musuh bagimu,844) maka berhati-hatilah kamu terhadap mereka; dan jika kamu maafkan dan kamu santuni serta ampuni (mereka), maka sungguh, Allah Maha Pengampun, Maha Penyayang"},{id:15,text:"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u064f\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0648\u06e1\u0644\u064e\u0670\u062f\u064f\u0643\u064f\u0645\u06e1 \u0641\u0650\u062a\u06e1\u0646\u064e\u0629\u065e\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u0650\u0646\u062f\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u062c\u06e1\u0631\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u065e",translation:"Sesungguhnya hartamu dan anak-anakmu hanyalah cobaan (bagimu), dan di sisi Allah pahala yang besar"},{id:16,text:"\u0641\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064e\u0627 \u0671\u0633\u06e1\u062a\u064e\u0637\u064e\u0639\u06e1\u062a\u064f\u0645\u06e1 \u0648\u064e\u0671\u0633\u06e1\u0645\u064e\u0639\u064f\u0648\u0627\u0652 \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0627\u0652 \u0648\u064e\u0623\u064e\u0646\u0641\u0650\u0642\u064f\u0648\u0627\u0652 \u062e\u064e\u064a\u06e1\u0631\u0657\u0627 \u0644\u0651\u0650\u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0643\u064f\u0645\u06e1\u06d7 \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0648\u0642\u064e \u0634\u064f\u062d\u0651\u064e \u0646\u064e\u0641\u06e1\u0633\u0650\u0647\u0650\u06e6 \u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064f\u0641\u06e1\u0644\u0650\u062d\u064f\u0648\u0646\u064e",translation:"Maka bertakwalah kamu kepada Allah menurut kesanggupanmu dan dengarlah serta taatlah; dan infakkanlah harta yang baik untuk dirimu. Dan barangsiapa dijaga dirinya dari kekikiran, mereka itulah orang-orang yang beruntung"},{id:17,text:"\u0625\u0650\u0646 \u062a\u064f\u0642\u06e1\u0631\u0650\u0636\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0642\u064e\u0631\u06e1\u0636\u064b\u0627 \u062d\u064e\u0633\u064e\u0646\u0657\u0627 \u064a\u064f\u0636\u064e\u0670\u0639\u0650\u0641\u06e1\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u064a\u064e\u063a\u06e1\u0641\u0650\u0631\u06e1 \u0644\u064e\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0634\u064e\u0643\u064f\u0648\u0631\u064c \u062d\u064e\u0644\u0650\u064a\u0645\u064c",translation:"Jika kamu meminjamkan kepada Allah dengan pinjaman yang baik, niscaya Dia melipatgandakan (balasan) untukmu dan mengampuni kamu. Dan Allah Maha Mensyukuri, Maha Penyantun"},{id:18,text:"\u0639\u064e\u0670\u0644\u0650\u0645\u064f \u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u0628\u0650 \u0648\u064e\u0671\u0644\u0634\u0651\u064e\u0647\u064e\u0670\u062f\u064e\u0629\u0650 \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0671\u0644\u06e1\u062d\u064e\u0643\u0650\u064a\u0645\u064f",translation:"Yang Mengetahui yang gaib dan yang nyata. Yang Mahaperkasa, Mahabijaksana"}]},{id:65,name:"\u0627\u0644\u0637\u0644\u0627\u0642",transliteration:"At-Talaq",translation:"Perceraian",type:"medinan",total_verses:12,verses:[{id:1,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064f \u0625\u0650\u0630\u064e\u0627 \u0637\u064e\u0644\u0651\u064e\u0642\u06e1\u062a\u064f\u0645\u064f \u0671\u0644\u0646\u0651\u0650\u0633\u064e\u0627\u0653\u0621\u064e \u0641\u064e\u0637\u064e\u0644\u0651\u0650\u0642\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0644\u0650\u0639\u0650\u062f\u0651\u064e\u062a\u0650\u0647\u0650\u0646\u0651\u064e \u0648\u064e\u0623\u064e\u062d\u06e1\u0635\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0639\u0650\u062f\u0651\u064e\u0629\u064e\u06d6 \u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u06e1\u06d6 \u0644\u064e\u0627 \u062a\u064f\u062e\u06e1\u0631\u0650\u062c\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0645\u0650\u0646\u06e2 \u0628\u064f\u064a\u064f\u0648\u062a\u0650\u0647\u0650\u0646\u0651\u064e \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062e\u06e1\u0631\u064f\u062c\u06e1\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u0646\u064e \u0628\u0650\u0641\u064e\u0670\u062d\u0650\u0634\u064e\u0629\u0656 \u0645\u0651\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0629\u0656\u06da \u0648\u064e\u062a\u0650\u0644\u06e1\u0643\u064e \u062d\u064f\u062f\u064f\u0648\u062f\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u062a\u064e\u0639\u064e\u062f\u0651\u064e \u062d\u064f\u062f\u064f\u0648\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0642\u064e\u062f\u06e1 \u0638\u064e\u0644\u064e\u0645\u064e \u0646\u064e\u0641\u06e1\u0633\u064e\u0647\u064f\u06e5\u06da \u0644\u064e\u0627 \u062a\u064e\u062f\u06e1\u0631\u0650\u064a \u0644\u064e\u0639\u064e\u0644\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u062d\u06e1\u062f\u0650\u062b\u064f \u0628\u064e\u0639\u06e1\u062f\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0623\u064e\u0645\u06e1\u0631\u0657\u0627",translation:"Wahai Nabi! Apabila kamu menceraikan istri-istrimu maka hendaklah kamu ceraikan mereka pada waktu mereka dapat (menghadapi) idahnya (yang wajar), dan hitunglah waktu idah itu, serta bertakwalah kepada Allah Tuhanmu. Janganlah kamu keluarkan mereka dari rumahnya dan janganlah (diizinkan) keluar kecuali jika mereka mengerjakan perbuatan keji yang jelas. Itulah hukum-hukum Allah, dan barangsiapa melanggar hukum-hukum Allah, maka sungguh, dia telah berbuat zalim terhadap dirinya sendiri. Kamu tidak mengetahui barangkali setelah itu Allah mengadakan suatu ketentuan yang baru"},{id:2,text:"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0628\u064e\u0644\u064e\u063a\u06e1\u0646\u064e \u0623\u064e\u062c\u064e\u0644\u064e\u0647\u064f\u0646\u0651\u064e \u0641\u064e\u0623\u064e\u0645\u06e1\u0633\u0650\u0643\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0628\u0650\u0645\u064e\u0639\u06e1\u0631\u064f\u0648\u0641\u064d \u0623\u064e\u0648\u06e1 \u0641\u064e\u0627\u0631\u0650\u0642\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0628\u0650\u0645\u064e\u0639\u06e1\u0631\u064f\u0648\u0641\u0656 \u0648\u064e\u0623\u064e\u0634\u06e1\u0647\u0650\u062f\u064f\u0648\u0627\u0652 \u0630\u064e\u0648\u064e\u064a\u06e1 \u0639\u064e\u062f\u06e1\u0644\u0656 \u0645\u0651\u0650\u0646\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0642\u0650\u064a\u0645\u064f\u0648\u0627\u0652 \u0671\u0644\u0634\u0651\u064e\u0647\u064e\u0670\u062f\u064e\u0629\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645\u06e1 \u064a\u064f\u0648\u0639\u064e\u0638\u064f \u0628\u0650\u0647\u0650\u06e6 \u0645\u064e\u0646 \u0643\u064e\u0627\u0646\u064e \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u0650\u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u062a\u0651\u064e\u0642\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u062c\u06e1\u0639\u064e\u0644 \u0644\u0651\u064e\u0647\u064f\u06e5 \u0645\u064e\u062e\u06e1\u0631\u064e\u062c\u0657\u0627",translation:"Maka apabila mereka telah mendekati akhir idahnya, maka rujuklah (kembali kepada) mereka dengan baik atau lepaskanlah mereka dengan baik dan persaksikanlah dengan dua orang saksi yang adil di antara kamu dan hendaklah kamu tegakkan kesaksian itu karena Allah. Demikianlah pengajaran itu diberikan bagi orang yang beriman kepada Allah dan hari akhirat. Barangsiapa bertakwa kepada Allah niscaya Dia akan membukakan jalan keluar baginya"},{id:3,text:"\u0648\u064e\u064a\u064e\u0631\u06e1\u0632\u064f\u0642\u06e1\u0647\u064f \u0645\u0650\u0646\u06e1 \u062d\u064e\u064a\u06e1\u062b\u064f \u0644\u064e\u0627 \u064a\u064e\u062d\u06e1\u062a\u064e\u0633\u0650\u0628\u064f\u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u06e1 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0647\u064f\u0648\u064e \u062d\u064e\u0633\u06e1\u0628\u064f\u0647\u064f\u06e5\u0653\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u064e\u0670\u0644\u0650\u063a\u064f \u0623\u064e\u0645\u06e1\u0631\u0650\u0647\u0650\u06e6\u06da \u0642\u064e\u062f\u06e1 \u062c\u064e\u0639\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0642\u064e\u062f\u06e1\u0631\u0657\u0627",translation:"Dan Dia memberinya rezeki dari arah yang tidak disangka-sangkanya. Dan barangsiapa bertawakal kepada Allah, niscaya Allah akan mencukupkan (keperluan)nya. Sesungguhnya Allah melaksanakan urusan-Nya. Sungguh, Allah telah mengadakan ketentuan bagi setiap sesuatu"},{id:4,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0640\u0670\u0653\u0640\u0654\u0650\u064a \u064a\u064e\u0626\u0650\u0633\u06e1\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064e\u062d\u0650\u064a\u0636\u0650 \u0645\u0650\u0646 \u0646\u0651\u0650\u0633\u064e\u0627\u0653\u0626\u0650\u0643\u064f\u0645\u06e1 \u0625\u0650\u0646\u0650 \u0671\u0631\u06e1\u062a\u064e\u0628\u06e1\u062a\u064f\u0645\u06e1 \u0641\u064e\u0639\u0650\u062f\u0651\u064e\u062a\u064f\u0647\u064f\u0646\u0651\u064e \u062b\u064e\u0644\u064e\u0670\u062b\u064e\u0629\u064f \u0623\u064e\u0634\u06e1\u0647\u064f\u0631\u0656 \u0648\u064e\u0671\u0644\u0651\u064e\u0640\u0670\u0653\u0640\u0654\u0650\u064a \u0644\u064e\u0645\u06e1 \u064a\u064e\u062d\u0650\u0636\u06e1\u0646\u064e\u06da \u0648\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0670\u062a\u064f \u0671\u0644\u06e1\u0623\u064e\u062d\u06e1\u0645\u064e\u0627\u0644\u0650 \u0623\u064e\u062c\u064e\u0644\u064f\u0647\u064f\u0646\u0651\u064e \u0623\u064e\u0646 \u064a\u064e\u0636\u064e\u0639\u06e1\u0646\u064e \u062d\u064e\u0645\u06e1\u0644\u064e\u0647\u064f\u0646\u0651\u064e\u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u062a\u0651\u064e\u0642\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u062c\u06e1\u0639\u064e\u0644 \u0644\u0651\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646\u06e1 \u0623\u064e\u0645\u06e1\u0631\u0650\u0647\u0650\u06e6 \u064a\u064f\u0633\u06e1\u0631\u0657\u0627",translation:"Perempuan-perempuan yang tidak haid lagi (menopause) di antara istri-istrimu jika kamu ragu-ragu (tentang masa idahnya) maka idahnya adalah tiga bulan; dan begitu (pula) perempuan-perempuan yang tidak haid. Sedangkan perempuan-perempuan yang hamil, waktu idah mereka itu sampai mereka melahirkan kandungannya. Dan barangsiapa bertakwa kepada Allah, niscaya Dia menjadikan kemudahan baginya dalam urusannya"},{id:5,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0623\u064e\u0645\u06e1\u0631\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0646\u0632\u064e\u0644\u064e\u0647\u064f\u06e5\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u062a\u0651\u064e\u0642\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064f\u0643\u064e\u0641\u0651\u0650\u0631\u06e1 \u0639\u064e\u0646\u06e1\u0647\u064f \u0633\u064e\u064a\u0651\u0650\u0640\u0654\u064e\u0627\u062a\u0650\u0647\u0650\u06e6 \u0648\u064e\u064a\u064f\u0639\u06e1\u0638\u0650\u0645\u06e1 \u0644\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u062c\u06e1\u0631\u064b\u0627",translation:"Itulah perintah Allah yang diturunkan-Nya kepada kamu; barangsiapa bertakwa kepada Allah, niscaya Allah akan menghapus kesalahan-kesalahannya dan akan melipatgandakan pahala baginya"},{id:6,text:"\u0623\u064e\u0633\u06e1\u0643\u0650\u0646\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0645\u0650\u0646\u06e1 \u062d\u064e\u064a\u06e1\u062b\u064f \u0633\u064e\u0643\u064e\u0646\u062a\u064f\u0645 \u0645\u0651\u0650\u0646 \u0648\u064f\u062c\u06e1\u062f\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0636\u064e\u0627\u0653\u0631\u0651\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0644\u0650\u062a\u064f\u0636\u064e\u064a\u0651\u0650\u0642\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0646\u0651\u064e\u06da \u0648\u064e\u0625\u0650\u0646 \u0643\u064f\u0646\u0651\u064e \u0623\u064f\u0648\u0652\u0644\u064e\u0670\u062a\u0650 \u062d\u064e\u0645\u06e1\u0644\u0656 \u0641\u064e\u0623\u064e\u0646\u0641\u0650\u0642\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0646\u0651\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0636\u064e\u0639\u06e1\u0646\u064e \u062d\u064e\u0645\u06e1\u0644\u064e\u0647\u064f\u0646\u0651\u064e\u06da \u0641\u064e\u0625\u0650\u0646\u06e1 \u0623\u064e\u0631\u06e1\u0636\u064e\u0639\u06e1\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u06e1 \u0641\u064e\u0640\u0654\u064e\u0627\u062a\u064f\u0648\u0647\u064f\u0646\u0651\u064e \u0623\u064f\u062c\u064f\u0648\u0631\u064e\u0647\u064f\u0646\u0651\u064e \u0648\u064e\u0623\u06e1\u062a\u064e\u0645\u0650\u0631\u064f\u0648\u0627\u0652 \u0628\u064e\u064a\u06e1\u0646\u064e\u0643\u064f\u0645 \u0628\u0650\u0645\u064e\u0639\u06e1\u0631\u064f\u0648\u0641\u0656\u06d6 \u0648\u064e\u0625\u0650\u0646 \u062a\u064e\u0639\u064e\u0627\u0633\u064e\u0631\u06e1\u062a\u064f\u0645\u06e1 \u0641\u064e\u0633\u064e\u062a\u064f\u0631\u06e1\u0636\u0650\u0639\u064f \u0644\u064e\u0647\u064f\u06e5\u0653 \u0623\u064f\u062e\u06e1\u0631\u064e\u0649\u0670",translation:"Tempatkanlah mereka (para istri) di mana kamu bertempat tinggal menurut kemampuanmu dan janganlah kamu menyusahkan mereka untuk menyempitkan (hati) mereka. Dan jika mereka (istri-istri yang sudah ditalak) itu sedang hamil, maka berikanlah kepada mereka nafkahnya sampai mereka melahirkan kandungannya, kemudian jika mereka menyusukan (anak-anak)mu maka berikanlah imbalannya kepada mereka; dan musyawarahkanlah di antara kamu (segala sesuatu) dengan baik; dan jika kamu menemui kesulitan, maka perempuan lain boleh menyusukan (anak itu) untuknya"},{id:7,text:"\u0644\u0650\u064a\u064f\u0646\u0641\u0650\u0642\u06e1 \u0630\u064f\u0648 \u0633\u064e\u0639\u064e\u0629\u0656 \u0645\u0651\u0650\u0646 \u0633\u064e\u0639\u064e\u062a\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u0645\u064e\u0646 \u0642\u064f\u062f\u0650\u0631\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0631\u0650\u0632\u06e1\u0642\u064f\u0647\u064f\u06e5 \u0641\u064e\u0644\u06e1\u064a\u064f\u0646\u0641\u0650\u0642\u06e1 \u0645\u0650\u0645\u0651\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u064e\u0649\u0670\u0647\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06da \u0644\u064e\u0627 \u064a\u064f\u0643\u064e\u0644\u0651\u0650\u0641\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0646\u064e\u0641\u06e1\u0633\u064b\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u064e\u0649\u0670\u0647\u064e\u0627\u06da \u0633\u064e\u064a\u064e\u062c\u06e1\u0639\u064e\u0644\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u064e\u0639\u06e1\u062f\u064e \u0639\u064f\u0633\u06e1\u0631\u0656 \u064a\u064f\u0633\u06e1\u0631\u0657\u0627",translation:"Hendaklah orang yang mempunyai keluasan memberi nafkah menurut kemampuannya, dan orang yang terbatas rezekinya, hendaklah memberi nafkah dari harta yang diberikan Allah kepadanya. Allah tidak membebani seseorang melainkan (sesuai) dengan apa yang diberikan Allah kepadanya. Allah kelak akan memberikan kelapangan setelah kesempitan"},{id:8,text:"\u0648\u064e\u0643\u064e\u0623\u064e\u064a\u0651\u0650\u0646 \u0645\u0651\u0650\u0646 \u0642\u064e\u0631\u06e1\u064a\u064e\u0629\u064d \u0639\u064e\u062a\u064e\u062a\u06e1 \u0639\u064e\u0646\u06e1 \u0623\u064e\u0645\u06e1\u0631\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u064e\u0627 \u0648\u064e\u0631\u064f\u0633\u064f\u0644\u0650\u0647\u0650\u06e6 \u0641\u064e\u062d\u064e\u0627\u0633\u064e\u0628\u06e1\u0646\u064e\u0670\u0647\u064e\u0627 \u062d\u0650\u0633\u064e\u0627\u0628\u0657\u0627 \u0634\u064e\u062f\u0650\u064a\u062f\u0657\u0627 \u0648\u064e\u0639\u064e\u0630\u0651\u064e\u0628\u06e1\u0646\u064e\u0670\u0647\u064e\u0627 \u0639\u064e\u0630\u064e\u0627\u0628\u0657\u0627 \u0646\u0651\u064f\u0643\u06e1\u0631\u0657\u0627",translation:"Dan betapa banyak (penduduk) negeri yang mendurhakai perintah Tuhan mereka dan rasul-rasul-Nya, maka Kami buat perhitungan terhadap penduduk negeri itu dengan perhitungan yang ketat, dan Kami azab mereka dengan azab yang mengerikan (di akhirat)"},{id:9,text:"\u0641\u064e\u0630\u064e\u0627\u0642\u064e\u062a\u06e1 \u0648\u064e\u0628\u064e\u0627\u0644\u064e \u0623\u064e\u0645\u06e1\u0631\u0650\u0647\u064e\u0627 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0670\u0642\u0650\u0628\u064e\u0629\u064f \u0623\u064e\u0645\u06e1\u0631\u0650\u0647\u064e\u0627 \u062e\u064f\u0633\u06e1\u0631\u064b\u0627",translation:"Sehingga mereka merasakan akibat yang buruk dari perbuatannya, dan akibat perbuatan mereka itu adalah kerugian yang besar"},{id:10,text:"\u0623\u064e\u0639\u064e\u062f\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u0657\u0627 \u0634\u064e\u062f\u0650\u064a\u062f\u0657\u0627\u06d6 \u0641\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0640\u0670\u0653\u0623\u064f\u0648\u0652\u0644\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0644\u06e1\u0628\u064e\u0670\u0628\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652\u06da \u0642\u064e\u062f\u06e1 \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0630\u0650\u0643\u06e1\u0631\u0657\u0627",translation:"Allah menyediakan azab yang keras bagi mereka, maka bertakwalah kepada Allah wahai orang-orang yang mempunyai akal! (Yaitu) orang-orang yang beriman. Sungguh, Allah telah menurunkan peringatan kepadamu"},{id:11,text:"\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0657\u0627 \u064a\u064e\u062a\u06e1\u0644\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064f\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0670\u062a\u0656 \u0644\u0651\u0650\u064a\u064f\u062e\u06e1\u0631\u0650\u062c\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0645\u0650\u0646\u064e \u0671\u0644\u0638\u0651\u064f\u0644\u064f\u0645\u064e\u0670\u062a\u0650 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0646\u0651\u064f\u0648\u0631\u0650\u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u06e2 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u06e1 \u0635\u064e\u0670\u0644\u0650\u062d\u0657\u0627 \u064a\u064f\u062f\u06e1\u062e\u0650\u0644\u06e1\u0647\u064f \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0656 \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0645\u0650\u0646 \u062a\u064e\u062d\u06e1\u062a\u0650\u0647\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u064f \u062e\u064e\u0670\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627\u0653 \u0623\u064e\u0628\u064e\u062f\u0657\u0627\u06d6 \u0642\u064e\u062f\u06e1 \u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0647\u064f\u06e5 \u0631\u0650\u0632\u06e1\u0642\u064b\u0627",translation:"(dengan mengutus) seorang Rasul yang membacakan ayat-ayat Allah kepadamu yang menerangkan (bermacam-macam hukum), agar Dia mengeluarkan orang-orang yang beriman dan mengerjakan kebajikan, dari kegelapan kepada cahaya. Dan barangsiapa beriman kepada Allah dan mengerjakan kebajikan, niscaya Dia akan memasukkannya ke dalam surga-surga yang mengalir di bawahnya sungai-sungai; mereka kekal di dalamnya selama-lamanya. Sungguh, Allah memberikan rezeki yang baik kepadanya"},{id:12,text:"\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e \u0633\u064e\u0628\u06e1\u0639\u064e \u0633\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0656 \u0648\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0645\u0650\u062b\u06e1\u0644\u064e\u0647\u064f\u0646\u0651\u064e\u06d6 \u064a\u064e\u062a\u064e\u0646\u064e\u0632\u0651\u064e\u0644\u064f \u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0631\u064f \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0646\u0651\u064e \u0644\u0650\u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0642\u064e\u062f\u0650\u064a\u0631\u065e \u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0642\u064e\u062f\u06e1 \u0623\u064e\u062d\u064e\u0627\u0637\u064e \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u064d \u0639\u0650\u0644\u06e1\u0645\u064e\u06e2\u0627",translation:"Allah yang menciptakan tujuh langit dan dari (penciptaan) bumi juga serupa. Perintah Allah berlaku padanya, agar kamu mengetahui bahwa Allah Mahakuasa atas segala sesuatu, dan ilmu Allah benar-benar meliputi segala sesuatu"}]},{id:66,name:"\u0627\u0644\u062a\u062d\u0631\u064a\u0645",transliteration:"At-Tahrim",translation:"Mengharamkan",type:"medinan",total_verses:12,verses:[{id:1,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064f \u0644\u0650\u0645\u064e \u062a\u064f\u062d\u064e\u0631\u0651\u0650\u0645\u064f \u0645\u064e\u0627\u0653 \u0623\u064e\u062d\u064e\u0644\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064e\u06d6 \u062a\u064e\u0628\u06e1\u062a\u064e\u063a\u0650\u064a \u0645\u064e\u0631\u06e1\u0636\u064e\u0627\u062a\u064e \u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u0650\u0643\u064e\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u065e",translation:"Wahai Nabi! Mengapa engkau mengharamkan apa yang dihalalkan Allah bagimu? Engkau ingin menyenangkan hati istri-istrimu? Dan Allah Maha Pengampun, Maha Penyayang"},{id:2,text:"\u0642\u064e\u062f\u06e1 \u0641\u064e\u0631\u064e\u0636\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u062d\u0650\u0644\u0651\u064e\u0629\u064e \u0623\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u0650\u0643\u064f\u0645\u06e1\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0648\u06e1\u0644\u064e\u0649\u0670\u0643\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0639\u064e\u0644\u0650\u064a\u0645\u064f \u0671\u0644\u06e1\u062d\u064e\u0643\u0650\u064a\u0645\u064f",translation:"Sungguh, Allah telah mewajibkan kepadamu membebaskan diri dari sumpahmu; dan Allah adalah pelindungmu dan Dia Maha Mengetahui, Mahabijaksana"},{id:3,text:"\u0648\u064e\u0625\u0650\u0630\u06e1 \u0623\u064e\u0633\u064e\u0631\u0651\u064e \u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u06e1\u0636\u0650 \u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u0650\u0647\u0650\u06e6 \u062d\u064e\u062f\u0650\u064a\u062b\u0657\u0627 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0646\u064e\u0628\u0651\u064e\u0623\u064e\u062a\u06e1 \u0628\u0650\u0647\u0650\u06e6 \u0648\u064e\u0623\u064e\u0638\u06e1\u0647\u064e\u0631\u064e\u0647\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0639\u064e\u0631\u0651\u064e\u0641\u064e \u0628\u064e\u0639\u06e1\u0636\u064e\u0647\u064f\u06e5 \u0648\u064e\u0623\u064e\u0639\u06e1\u0631\u064e\u0636\u064e \u0639\u064e\u0646\u06e2 \u0628\u064e\u0639\u06e1\u0636\u0656\u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0646\u064e\u0628\u0651\u064e\u0623\u064e\u0647\u064e\u0627 \u0628\u0650\u0647\u0650\u06e6 \u0642\u064e\u0627\u0644\u064e\u062a\u06e1 \u0645\u064e\u0646\u06e1 \u0623\u064e\u0646\u06e2\u0628\u064e\u0623\u064e\u0643\u064e \u0647\u064e\u0670\u0630\u064e\u0627\u06d6 \u0642\u064e\u0627\u0644\u064e \u0646\u064e\u0628\u0651\u064e\u0623\u064e\u0646\u0650\u064a\u064e \u0671\u0644\u06e1\u0639\u064e\u0644\u0650\u064a\u0645\u064f \u0671\u0644\u06e1\u062e\u064e\u0628\u0650\u064a\u0631\u064f",translation:"Dan ingatlah ketika secara rahasia Nabi membicarakan suatu peristiwa kepada salah seorang istrinya (Hafsah). Lalu dia menceritakan peristiwa itu (kepada Aisyah) dan Allah memberitahukan peristiwa itu kepadanya (Nabi), lalu (Nabi) memberitahukan (kepada Hafsah) sebagian dan menyembunyikan sebagian yang lain. Maka ketika dia (Nabi) memberitahukan pembicaraan itu kepadanya (Hafsah), dia bertanya, \"Siapa yang telah memberitahukan hal ini kepadamu?\" Nabi menjawab, \"Yang memberitahukan kepadaku adalah Allah Yang Maha Mengetahui, Mahateliti"},{id:4,text:"\u0625\u0650\u0646 \u062a\u064e\u062a\u064f\u0648\u0628\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0642\u064e\u062f\u06e1 \u0635\u064e\u063a\u064e\u062a\u06e1 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0643\u064f\u0645\u064e\u0627\u06d6 \u0648\u064e\u0625\u0650\u0646 \u062a\u064e\u0638\u064e\u0670\u0647\u064e\u0631\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0647\u064f\u0648\u064e \u0645\u064e\u0648\u06e1\u0644\u064e\u0649\u0670\u0647\u064f \u0648\u064e\u062c\u0650\u0628\u06e1\u0631\u0650\u064a\u0644\u064f \u0648\u064e\u0635\u064e\u0670\u0644\u0650\u062d\u064f \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e\u06d6 \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u064f \u0628\u064e\u0639\u06e1\u062f\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0638\u064e\u0647\u0650\u064a\u0631\u064c",translation:"Jika kamu berdua bertobat kepada Allah, maka sungguh, hati kamu berdua telah condong (untuk menerima kebenaran); dan jika kamu berdua saling bantu membantu menyusahkan Nabi, maka sungguh, Allah menjadi pelindungnya dan (juga) Jibril dan orang-orang mukmin yang baik; dan selain itu malaikat-malaikat adalah penolongnya"},{id:5,text:"\u0639\u064e\u0633\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u064f\u0647\u064f\u06e5\u0653 \u0625\u0650\u0646 \u0637\u064e\u0644\u0651\u064e\u0642\u064e\u0643\u064f\u0646\u0651\u064e \u0623\u064e\u0646 \u064a\u064f\u0628\u06e1\u062f\u0650\u0644\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u064b\u0627 \u062e\u064e\u064a\u06e1\u0631\u0657\u0627 \u0645\u0651\u0650\u0646\u0643\u064f\u0646\u0651\u064e \u0645\u064f\u0633\u06e1\u0644\u0650\u0645\u064e\u0670\u062a\u0656 \u0645\u0651\u064f\u0624\u06e1\u0645\u0650\u0646\u064e\u0670\u062a\u0656 \u0642\u064e\u0670\u0646\u0650\u062a\u064e\u0670\u062a\u0656 \u062a\u064e\u0640\u0670\u0653\u0626\u0650\u0628\u064e\u0670\u062a\u064d \u0639\u064e\u0670\u0628\u0650\u062f\u064e\u0670\u062a\u0656 \u0633\u064e\u0640\u0670\u0653\u0626\u0650\u062d\u064e\u0670\u062a\u0656 \u062b\u064e\u064a\u0651\u0650\u0628\u064e\u0670\u062a\u0656 \u0648\u064e\u0623\u064e\u0628\u06e1\u0643\u064e\u0627\u0631\u0657\u0627",translation:"Jika dia (Nabi) menceraikan kamu, boleh jadi Tuhan akan memberi ganti kepadanya dengan istri-istri yang lebih baik dari kamu, perempuan-perempuan yang patuh, yang beriman, yang taat, yang bertobat, yang beribadah, yang berpuasa, yang janda dan yang perawan"},{id:6,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0642\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0647\u06e1\u0644\u0650\u064a\u0643\u064f\u0645\u06e1 \u0646\u064e\u0627\u0631\u0657\u0627 \u0648\u064e\u0642\u064f\u0648\u062f\u064f\u0647\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0648\u064e\u0671\u0644\u06e1\u062d\u0650\u062c\u064e\u0627\u0631\u064e\u0629\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627 \u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u064c \u063a\u0650\u0644\u064e\u0627\u0638\u065e \u0634\u0650\u062f\u064e\u0627\u062f\u065e \u0644\u0651\u064e\u0627 \u064a\u064e\u0639\u06e1\u0635\u064f\u0648\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064e\u0627\u0653 \u0623\u064e\u0645\u064e\u0631\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u064a\u064e\u0641\u06e1\u0639\u064e\u0644\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Wahai orang-orang yang beriman! Peliharalah dirimu dan keluargamu dari api neraka yang bahan bakarnya adalah manusia dan batu; penjaganya malaikat-malaikat yang kasar, dan keras, yang tidak durhaka kepada apa yang Allah perintahkan kepada mereka dan selalu mengerjakan apa yang diperintahkan"},{id:7,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u062a\u064e\u0639\u06e1\u062a\u064e\u0630\u0650\u0631\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e\u06d6 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u062a\u064f\u062c\u06e1\u0632\u064e\u0648\u06e1\u0646\u064e \u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Wahai orang-orang kafir! Janganlah kamu mengemukakan alasan pada hari ini. Sesungguhnya kamu hanya diberi balasan menurut apa yang telah kamu kerjakan"},{id:8,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u062a\u064f\u0648\u0628\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062a\u064e\u0648\u06e1\u0628\u064e\u0629\u0657 \u0646\u0651\u064e\u0635\u064f\u0648\u062d\u064b\u0627 \u0639\u064e\u0633\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u06e1 \u0623\u064e\u0646 \u064a\u064f\u0643\u064e\u0641\u0651\u0650\u0631\u064e \u0639\u064e\u0646\u0643\u064f\u0645\u06e1 \u0633\u064e\u064a\u0651\u0650\u0640\u0654\u064e\u0627\u062a\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u064a\u064f\u062f\u06e1\u062e\u0650\u0644\u064e\u0643\u064f\u0645\u06e1 \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0656 \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0645\u0650\u0646 \u062a\u064e\u062d\u06e1\u062a\u0650\u0647\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u064f \u064a\u064e\u0648\u06e1\u0645\u064e \u0644\u064e\u0627 \u064a\u064f\u062e\u06e1\u0632\u0650\u064a \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064e \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0645\u064e\u0639\u064e\u0647\u064f\u06e5\u06d6 \u0646\u064f\u0648\u0631\u064f\u0647\u064f\u0645\u06e1 \u064a\u064e\u0633\u06e1\u0639\u064e\u0649\u0670 \u0628\u064e\u064a\u06e1\u0646\u064e \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u0647\u0650\u0645\u06e1 \u0648\u064e\u0628\u0650\u0623\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u0650\u0647\u0650\u0645\u06e1 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627\u0653 \u0623\u064e\u062a\u06e1\u0645\u0650\u0645\u06e1 \u0644\u064e\u0646\u064e\u0627 \u0646\u064f\u0648\u0631\u064e\u0646\u064e\u0627 \u0648\u064e\u0671\u063a\u06e1\u0641\u0650\u0631\u06e1 \u0644\u064e\u0646\u064e\u0627\u0653\u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0642\u064e\u062f\u0650\u064a\u0631\u065e",translation:"Wahai orang-orang yang beriman! Bertobatlah kepada Allah dengan tobat yang semurni-murninya, mudah-mudahan Tuhan kamu akan menghapus kesalahan-kesalahanmu dan memasukkan kamu ke dalam surga-surga yang mengalir di bawahnya sungai-sungai, pada hari ketika Allah tidak mengecewakan Nabi dan orang-orang yang beriman bersama dengannya; sedang cahaya mereka memancar di hadapan dan di sebelah kanan mereka, sambil mereka berkata, \"Ya Tuhan kami, sempurnakanlah untuk kami cahaya kami dan ampunilah kami; sungguh, Engkau Mahakuasa atas segala sesuatu"},{id:9,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u064f \u062c\u064e\u0670\u0647\u0650\u062f\u0650 \u0671\u0644\u06e1\u0643\u064f\u0641\u0651\u064e\u0627\u0631\u064e \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0646\u064e\u0670\u0641\u0650\u0642\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u063a\u06e1\u0644\u064f\u0638\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1\u06da \u0648\u064e\u0645\u064e\u0623\u06e1\u0648\u064e\u0649\u0670\u0647\u064f\u0645\u06e1 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064f\u06d6 \u0648\u064e\u0628\u0650\u0626\u06e1\u0633\u064e \u0671\u0644\u06e1\u0645\u064e\u0635\u0650\u064a\u0631\u064f",translation:"Wahai Nabi! Perangilah orang-orang kafir dan orang-orang munafik dan bersikap keraslah terhadap mereka. Tempat mereka adalah neraka Jahanam dan itulah seburuk-buruk tempat kembali"},{id:10,text:"\u0636\u064e\u0631\u064e\u0628\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u062b\u064e\u0644\u0657\u0627 \u0644\u0651\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0671\u0645\u06e1\u0631\u064e\u0623\u064e\u062a\u064e \u0646\u064f\u0648\u062d\u0656 \u0648\u064e\u0671\u0645\u06e1\u0631\u064e\u0623\u064e\u062a\u064e \u0644\u064f\u0648\u0637\u0656\u06d6 \u0643\u064e\u0627\u0646\u064e\u062a\u064e\u0627 \u062a\u064e\u062d\u06e1\u062a\u064e \u0639\u064e\u0628\u06e1\u062f\u064e\u064a\u06e1\u0646\u0650 \u0645\u0650\u0646\u06e1 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0646\u064e\u0627 \u0635\u064e\u0670\u0644\u0650\u062d\u064e\u064a\u06e1\u0646\u0650 \u0641\u064e\u062e\u064e\u0627\u0646\u064e\u062a\u064e\u0627\u0647\u064f\u0645\u064e\u0627 \u0641\u064e\u0644\u064e\u0645\u06e1 \u064a\u064f\u063a\u06e1\u0646\u0650\u064a\u064e\u0627 \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u064e\u0627 \u0645\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627 \u0648\u064e\u0642\u0650\u064a\u0644\u064e \u0671\u062f\u06e1\u062e\u064f\u0644\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u064e \u0645\u064e\u0639\u064e \u0671\u0644\u062f\u0651\u064e\u0640\u0670\u062e\u0650\u0644\u0650\u064a\u0646\u064e",translation:"Allah membuat perumpamaan bagi orang-orang kafir, istri Nuh dan istri Lu\u1e6d. Keduanya berada di bawah pengawasan dua orang hamba yang saleh di antara hamba-hamba Kami; lalu kedua istri itu berkhianat kepada kedua suaminya, tetapi kedua suaminya itu tidak dapat membantu mereka sedikit pun dari (siksa) Allah; dan dikatakan (kepada kedua istri itu), \"Masuklah kamu berdua ke neraka bersama orang-orang yang masuk (neraka)"},{id:11,text:"\u0648\u064e\u0636\u064e\u0631\u064e\u0628\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u062b\u064e\u0644\u0657\u0627 \u0644\u0651\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0671\u0645\u06e1\u0631\u064e\u0623\u064e\u062a\u064e \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0625\u0650\u0630\u06e1 \u0642\u064e\u0627\u0644\u064e\u062a\u06e1 \u0631\u064e\u0628\u0651\u0650 \u0671\u0628\u06e1\u0646\u0650 \u0644\u0650\u064a \u0639\u0650\u0646\u062f\u064e\u0643\u064e \u0628\u064e\u064a\u06e1\u062a\u0657\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u0648\u064e\u0646\u064e\u062c\u0651\u0650\u0646\u0650\u064a \u0645\u0650\u0646 \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0648\u064e\u0639\u064e\u0645\u064e\u0644\u0650\u0647\u0650\u06e6 \u0648\u064e\u0646\u064e\u062c\u0651\u0650\u0646\u0650\u064a \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Dan Allah membuat perumpamaan bagi orang-orang yang beriman, istri Fir'aun, ketika dia berkata, \"Ya Tuhanku, bangunkanlah untukku satu rumah di sisi-Mu dalam surga dan selamatkanlah aku dari Fir'aun dan perbuatannya, dan selamatkanlah aku dari kaum yang zalim"},{id:12,text:"\u0648\u064e\u0645\u064e\u0631\u06e1\u064a\u064e\u0645\u064e \u0671\u0628\u06e1\u0646\u064e\u062a\u064e \u0639\u0650\u0645\u06e1\u0631\u064e\u0670\u0646\u064e \u0671\u0644\u0651\u064e\u062a\u0650\u064a\u0653 \u0623\u064e\u062d\u06e1\u0635\u064e\u0646\u064e\u062a\u06e1 \u0641\u064e\u0631\u06e1\u062c\u064e\u0647\u064e\u0627 \u0641\u064e\u0646\u064e\u0641\u064e\u062e\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u0650 \u0645\u0650\u0646 \u0631\u0651\u064f\u0648\u062d\u0650\u0646\u064e\u0627 \u0648\u064e\u0635\u064e\u062f\u0651\u064e\u0642\u064e\u062a\u06e1 \u0628\u0650\u0643\u064e\u0644\u0650\u0645\u064e\u0670\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u064e\u0627 \u0648\u064e\u0643\u064f\u062a\u064f\u0628\u0650\u0647\u0650\u06e6 \u0648\u064e\u0643\u064e\u0627\u0646\u064e\u062a\u06e1 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0642\u064e\u0670\u0646\u0650\u062a\u0650\u064a\u0646\u064e",translation:"dan Maryam putri Imran yang memelihara kehormatannya, maka Kami tiupkan ke dalam rahimnya sebagian dari roh (ciptaan) Kami; dan dia membenarkan kalimat-kalimat Tuhannya dan kitab-kitab-Nya; dan dia termasuk orang-orang yang taat"}]},{id:67,name:"\u0627\u0644\u0645\u0644\u0643",transliteration:"Al-Mulk",translation:"Kerajaan",type:"meccan",total_verses:30,verses:[{id:1,text:"\u062a\u064e\u0628\u064e\u0670\u0631\u064e\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0628\u0650\u064a\u064e\u062f\u0650\u0647\u0650 \u0671\u0644\u06e1\u0645\u064f\u0644\u06e1\u0643\u064f \u0648\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0642\u064e\u062f\u0650\u064a\u0631\u064c",translation:"Mahasuci Allah yang menguasai (segala) kerajaan, Dan Dia Mahakuasa atas segala sesuatu"},{id:2,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u064e \u0648\u064e\u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u064e \u0644\u0650\u064a\u064e\u0628\u06e1\u0644\u064f\u0648\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u064a\u0651\u064f\u0643\u064f\u0645\u06e1 \u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u064f \u0639\u064e\u0645\u064e\u0644\u0657\u0627\u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0671\u0644\u06e1\u063a\u064e\u0641\u064f\u0648\u0631\u064f",translation:"Yang menciptakan mati dan hidup, untuk menguji kamu, siapa di antara kamu yang lebih baik amalnya. Dan Dia Mahaperkasa, Maha Pengampun"},{id:3,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e \u0633\u064e\u0628\u06e1\u0639\u064e \u0633\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0656 \u0637\u0650\u0628\u064e\u0627\u0642\u0657\u0627\u06d6 \u0645\u0651\u064e\u0627 \u062a\u064e\u0631\u064e\u0649\u0670 \u0641\u0650\u064a \u062e\u064e\u0644\u06e1\u0642\u0650 \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u0650 \u0645\u0650\u0646 \u062a\u064e\u0641\u064e\u0670\u0648\u064f\u062a\u0656\u06d6 \u0641\u064e\u0671\u0631\u06e1\u062c\u0650\u0639\u0650 \u0671\u0644\u06e1\u0628\u064e\u0635\u064e\u0631\u064e \u0647\u064e\u0644\u06e1 \u062a\u064e\u0631\u064e\u0649\u0670 \u0645\u0650\u0646 \u0641\u064f\u0637\u064f\u0648\u0631\u0656",translation:"Yang menciptakan tujuh langit berlapis-lapis. Tidak akan kamu lihat sesuatu yang tidak seimbang pada ciptaan Tuhan Yang Maha Pengasih. Maka lihatlah sekali lagi, adakah kamu lihat sesuatu yang cacat"},{id:4,text:"\u062b\u064f\u0645\u0651\u064e \u0671\u0631\u06e1\u062c\u0650\u0639\u0650 \u0671\u0644\u06e1\u0628\u064e\u0635\u064e\u0631\u064e \u0643\u064e\u0631\u0651\u064e\u062a\u064e\u064a\u06e1\u0646\u0650 \u064a\u064e\u0646\u0642\u064e\u0644\u0650\u0628\u06e1 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064e \u0671\u0644\u06e1\u0628\u064e\u0635\u064e\u0631\u064f \u062e\u064e\u0627\u0633\u0650\u0626\u0657\u0627 \u0648\u064e\u0647\u064f\u0648\u064e \u062d\u064e\u0633\u0650\u064a\u0631\u065e",translation:"Kemudian ulangi pandangan(mu) sekali lagi (dan) sekali lagi, niscaya pandanganmu akan kembali kepadamu tanpa menemukan cacat dan ia (pandanganmu) dalam keadaan letih"},{id:5,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0632\u064e\u064a\u0651\u064e\u0646\u0651\u064e\u0627 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627 \u0628\u0650\u0645\u064e\u0635\u064e\u0670\u0628\u0650\u064a\u062d\u064e \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064e\u0627 \u0631\u064f\u062c\u064f\u0648\u0645\u0657\u0627 \u0644\u0651\u0650\u0644\u0634\u0651\u064e\u064a\u064e\u0670\u0637\u0650\u064a\u0646\u0650\u06d6 \u0648\u064e\u0623\u064e\u0639\u06e1\u062a\u064e\u062f\u06e1\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0671\u0644\u0633\u0651\u064e\u0639\u0650\u064a\u0631\u0650",translation:"Dan sungguh, telah Kami hiasi langit yang dekat, dengan bintang-bintang dan Kami jadikannya (bintang-bintang itu) sebagai alat-alat pelempar setan, dan Kami sediakan bagi mereka azab neraka yang menyala-nyala"},{id:6,text:"\u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064f \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e\u06d6 \u0648\u064e\u0628\u0650\u0626\u06e1\u0633\u064e \u0671\u0644\u06e1\u0645\u064e\u0635\u0650\u064a\u0631\u064f",translation:"Dan orang-orang yang ingkar kepada Tuhannya, akan mendapat azab Jahanam. Dan itulah seburuk-buruk tempat kembali"},{id:7,text:"\u0625\u0650\u0630\u064e\u0627\u0653 \u0623\u064f\u0644\u06e1\u0642\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0633\u064e\u0645\u0650\u0639\u064f\u0648\u0627\u0652 \u0644\u064e\u0647\u064e\u0627 \u0634\u064e\u0647\u0650\u064a\u0642\u0657\u0627 \u0648\u064e\u0647\u0650\u064a\u064e \u062a\u064e\u0641\u064f\u0648\u0631\u064f",translation:"Apabila mereka dilemparkan ke dalamnya mereka mendengar suara neraka yang mengerikan, sedang neraka itu membara"},{id:8,text:"\u062a\u064e\u0643\u064e\u0627\u062f\u064f \u062a\u064e\u0645\u064e\u064a\u0651\u064e\u0632\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u0638\u0650\u06d6 \u0643\u064f\u0644\u0651\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0644\u06e1\u0642\u0650\u064a\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0641\u064e\u0648\u06e1\u062c\u065e \u0633\u064e\u0623\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u062e\u064e\u0632\u064e\u0646\u064e\u062a\u064f\u0647\u064e\u0627\u0653 \u0623\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0623\u06e1\u062a\u0650\u0643\u064f\u0645\u06e1 \u0646\u064e\u0630\u0650\u064a\u0631\u065e",translation:"hampir meledak karena marah. Setiap kali ada sekumpulan (orang-orang kafir) dilemparkan ke dalamnya, penjaga-penjaga (neraka itu) bertanya kepada mereka, \"Apakah belum pernah ada orang yang datang memberi peringatan kepadamu (di dunia)"},{id:9,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0628\u064e\u0644\u064e\u0649\u0670 \u0642\u064e\u062f\u06e1 \u062c\u064e\u0627\u0653\u0621\u064e\u0646\u064e\u0627 \u0646\u064e\u0630\u0650\u064a\u0631\u065e \u0641\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u06e1\u0646\u064e\u0627 \u0648\u064e\u0642\u064f\u0644\u06e1\u0646\u064e\u0627 \u0645\u064e\u0627 \u0646\u064e\u0632\u0651\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646 \u0634\u064e\u064a\u06e1\u0621\u064d \u0625\u0650\u0646\u06e1 \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0670\u0644\u0656 \u0643\u064e\u0628\u0650\u064a\u0631\u0656",translation:"Mereka menjawab, \"Benar, sungguh, seorang pemberi peringatan telah datang kepada kami, tetapi kami mendustakan(nya) dan kami katakan, \"Allah tidak menurunkan sesuatu apa pun, kamu sebenarnya di dalam kesesatan yang besar"},{id:10,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0648\u06e1 \u0643\u064f\u0646\u0651\u064e\u0627 \u0646\u064e\u0633\u06e1\u0645\u064e\u0639\u064f \u0623\u064e\u0648\u06e1 \u0646\u064e\u0639\u06e1\u0642\u0650\u0644\u064f \u0645\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0641\u0650\u064a\u0653 \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u0650 \u0671\u0644\u0633\u0651\u064e\u0639\u0650\u064a\u0631\u0650",translation:"Dan mereka berkata, \"Sekiranya (dahulu) kami mendengarkan atau memikirkan (peringatan itu) tentulah kami tidak termasuk penghuni neraka yang menyala-nyala"},{id:11,text:"\u0641\u064e\u0671\u0639\u06e1\u062a\u064e\u0631\u064e\u0641\u064f\u0648\u0627\u0652 \u0628\u0650\u0630\u064e\u0646\u06e2\u0628\u0650\u0647\u0650\u0645\u06e1 \u0641\u064e\u0633\u064f\u062d\u06e1\u0642\u0657\u0627 \u0644\u0651\u0650\u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u0650 \u0671\u0644\u0633\u0651\u064e\u0639\u0650\u064a\u0631\u0650",translation:"Maka mereka mengakui dosanya. Tetapi jauhlah (dari rahmat Allah) bagi penghuni neraka yang menyala-nyala itu"},{id:12,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062e\u06e1\u0634\u064e\u0648\u06e1\u0646\u064e \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u0628\u0650 \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u063a\u06e1\u0641\u0650\u0631\u064e\u0629\u065e \u0648\u064e\u0623\u064e\u062c\u06e1\u0631\u065e \u0643\u064e\u0628\u0650\u064a\u0631\u065e",translation:"Sesungguhnya orang-orang yang takut kepada Tuhannya yang tidak terlihat oleh mereka, mereka memperoleh ampunan dan pahala yang besar"},{id:13,text:"\u0648\u064e\u0623\u064e\u0633\u0650\u0631\u0651\u064f\u0648\u0627\u0652 \u0642\u064e\u0648\u06e1\u0644\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u0648\u0650 \u0671\u062c\u06e1\u0647\u064e\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u06e6\u0653\u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0639\u064e\u0644\u0650\u064a\u0645\u064f\u06e2 \u0628\u0650\u0630\u064e\u0627\u062a\u0650 \u0671\u0644\u0635\u0651\u064f\u062f\u064f\u0648\u0631\u0650",translation:"Dan rahasiakanlah perkataanmu atau nyatakanlah. Sungguh, Dia Maha Mengetahui segala isi hati"},{id:14,text:"\u0623\u064e\u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0645\u064e\u0646\u06e1 \u062e\u064e\u0644\u064e\u0642\u064e \u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u0644\u0651\u064e\u0637\u0650\u064a\u0641\u064f \u0671\u0644\u06e1\u062e\u064e\u0628\u0650\u064a\u0631\u064f",translation:"Apakah (pantas) Allah yang menciptakan itu tidak mengetahui? Dan Dia Mahahalus, Maha Mengetahui"},{id:15,text:"\u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0630\u064e\u0644\u064f\u0648\u0644\u0657\u0627 \u0641\u064e\u0671\u0645\u06e1\u0634\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0645\u064e\u0646\u064e\u0627\u0643\u0650\u0628\u0650\u0647\u064e\u0627 \u0648\u064e\u0643\u064f\u0644\u064f\u0648\u0627\u0652 \u0645\u0650\u0646 \u0631\u0651\u0650\u0632\u06e1\u0642\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0671\u0644\u0646\u0651\u064f\u0634\u064f\u0648\u0631\u064f",translation:"Dialah yang menjadikan bumi untuk kamu yang mudah dijelajahi, maka jelajahilah di segala penjurunya dan makanlah sebagian dari rezeki-Nya. Dan hanya kepada-Nyalah kamu (kembali setelah) dibangkitkan"},{id:16,text:"\u0621\u064e\u0623\u064e\u0645\u0650\u0646\u062a\u064f\u0645 \u0645\u0651\u064e\u0646 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0623\u064e\u0646 \u064a\u064e\u062e\u06e1\u0633\u0650\u0641\u064e \u0628\u0650\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0647\u0650\u064a\u064e \u062a\u064e\u0645\u064f\u0648\u0631\u064f",translation:"Sudah merasa amankah kamu, bahwa Dia yang di langit tidak akan membuat kamu ditelan bumi ketika tiba-tiba ia terguncang"},{id:17,text:"\u0623\u064e\u0645\u06e1 \u0623\u064e\u0645\u0650\u0646\u062a\u064f\u0645 \u0645\u0651\u064e\u0646 \u0641\u0650\u064a \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0623\u064e\u0646 \u064a\u064f\u0631\u06e1\u0633\u0650\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u062d\u064e\u0627\u0635\u0650\u0628\u0657\u0627\u06d6 \u0641\u064e\u0633\u064e\u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0643\u064e\u064a\u06e1\u0641\u064e \u0646\u064e\u0630\u0650\u064a\u0631\u0650",translation:"atau sudah merasa amankah kamu, bahwa Dia yang di langit tidak akan mengirimkan badai yang berbatu kepadamu? Namun kelak kamu akan mengetahui bagaimana (akibat mendustakan) peringatan-Ku"},{id:18,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650\u0647\u0650\u0645\u06e1 \u0641\u064e\u0643\u064e\u064a\u06e1\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0646\u064e\u0643\u0650\u064a\u0631\u0650",translation:"Dan sungguh, orang-orang yang sebelum mereka pun telah mendustakan (rasul-rasul-Nya). Maka betapa hebatnya kemurkaan-Ku"},{id:19,text:"\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0631\u064e\u0648\u06e1\u0627\u0652 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0637\u0651\u064e\u064a\u06e1\u0631\u0650 \u0641\u064e\u0648\u06e1\u0642\u064e\u0647\u064f\u0645\u06e1 \u0635\u064e\u0640\u0670\u0653\u0641\u0651\u064e\u0640\u0670\u062a\u0656 \u0648\u064e\u064a\u064e\u0642\u06e1\u0628\u0650\u0636\u06e1\u0646\u064e\u06da \u0645\u064e\u0627 \u064a\u064f\u0645\u06e1\u0633\u0650\u0643\u064f\u0647\u064f\u0646\u0651\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u064f\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0650\u06ed \u0628\u064e\u0635\u0650\u064a\u0631\u064c",translation:"Tidakkah mereka memperhatikan burung-burung yang mengembangkan dan mengatupkan sayapnya di atas mereka? Tidak ada yang menahannya (di udara) selain Yang Maha Pengasih. Sungguh, Dia Maha Melihat segala sesuatu"},{id:20,text:"\u0623\u064e\u0645\u0651\u064e\u0646\u06e1 \u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0647\u064f\u0648\u064e \u062c\u064f\u0646\u062f\u065e \u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u064a\u064e\u0646\u0635\u064f\u0631\u064f\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u0650\u06da \u0625\u0650\u0646\u0650 \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0641\u0650\u064a \u063a\u064f\u0631\u064f\u0648\u0631\u064d",translation:"Atau siapakah yang akan menjadi bala tentara bagimu yang dapat membelamu selain (Allah) Yang Maha Pengasih? Orang-orang kafir itu hanyalah dalam (keadaan) tertipu"},{id:21,text:"\u0623\u064e\u0645\u0651\u064e\u0646\u06e1 \u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064e\u0631\u06e1\u0632\u064f\u0642\u064f\u0643\u064f\u0645\u06e1 \u0625\u0650\u0646\u06e1 \u0623\u064e\u0645\u06e1\u0633\u064e\u0643\u064e \u0631\u0650\u0632\u06e1\u0642\u064e\u0647\u064f\u06e5\u06da \u0628\u064e\u0644 \u0644\u0651\u064e\u062c\u0651\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u0639\u064f\u062a\u064f\u0648\u0651\u0656 \u0648\u064e\u0646\u064f\u0641\u064f\u0648\u0631\u064d",translation:"Atau siapakah yang dapat memberimu rezeki jika Dia menahan rezeki-Nya? Bahkan mereka terus-menerus dalam kesombongan dan menjauhkan diri (dari kebenaran)"},{id:22,text:"\u0623\u064e\u0641\u064e\u0645\u064e\u0646 \u064a\u064e\u0645\u06e1\u0634\u0650\u064a \u0645\u064f\u0643\u0650\u0628\u0651\u064b\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0648\u064e\u062c\u06e1\u0647\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0647\u06e1\u062f\u064e\u0649\u0670\u0653 \u0623\u064e\u0645\u0651\u064e\u0646 \u064a\u064e\u0645\u06e1\u0634\u0650\u064a \u0633\u064e\u0648\u0650\u064a\u0651\u064b\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0670\u0637\u0656 \u0645\u0651\u064f\u0633\u06e1\u062a\u064e\u0642\u0650\u064a\u0645\u0656",translation:"Apakah orang yang merangkak dengan wajah tertelungkup yang lebih terpimpin (dalam kebenaran) ataukah orang yang berjalan tegap di atas jalan yang lurus"},{id:23,text:"\u0642\u064f\u0644\u06e1 \u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064e\u0646\u0634\u064e\u0623\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u06e1\u0639\u064e \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0628\u06e1\u0635\u064e\u0670\u0631\u064e \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0641\u06e1\u0640\u0654\u0650\u062f\u064e\u0629\u064e\u06da \u0642\u064e\u0644\u0650\u064a\u0644\u0657\u0627 \u0645\u0651\u064e\u0627 \u062a\u064e\u0634\u06e1\u0643\u064f\u0631\u064f\u0648\u0646\u064e",translation:"Katakanlah, \"Dialah yang menciptakan kamu dan menjadikan pendengaran, penglihatan dan hati nurani bagi kamu. (Tetapi) sedikit sekali kamu bersyukur"},{id:24,text:"\u0642\u064f\u0644\u06e1 \u0647\u064f\u0648\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0630\u064e\u0631\u064e\u0623\u064e\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u062a\u064f\u062d\u06e1\u0634\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Katakanlah, \"Dialah yang menjadikan kamu berkembang biak di muka bumi, dan hanya kepada-Nya kamu akan dikumpulkan"},{id:25,text:"\u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0645\u064e\u062a\u064e\u0649\u0670 \u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u06e1\u0648\u064e\u0639\u06e1\u062f\u064f \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0635\u064e\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Dan mereka berkata, \"Kapan (datangnya) ancaman itu jika kamu orang yang benar"},{id:26,text:"\u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0671\u0644\u06e1\u0639\u0650\u0644\u06e1\u0645\u064f \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u064e\u0627\u06e0 \u0646\u064e\u0630\u0650\u064a\u0631\u065e \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u065e",translation:"Katakanlah (Muhammad), \"Sesungguhnya ilmu (tentang hari Kiamat itu) hanya ada pada Allah. Dan aku hanyalah seorang pemberi peringatan yang menjelaskan"},{id:27,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0631\u064e\u0623\u064e\u0648\u06e1\u0647\u064f \u0632\u064f\u0644\u06e1\u0641\u064e\u0629\u0657 \u0633\u0650\u064a\u0653\u0640\u0654\u064e\u062a\u06e1 \u0648\u064f\u062c\u064f\u0648\u0647\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0648\u064e\u0642\u0650\u064a\u0644\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0643\u064f\u0646\u062a\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6 \u062a\u064e\u062f\u0651\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Maka ketika mereka melihat azab (pada hari Kiamat) sudah dekat, wajah orang-orang kafir itu menjadi muram. Dan dikatakan (kepada mereka), \"Inilah (azab) yang dahulu kamu memintanya"},{id:28,text:"\u0642\u064f\u0644\u06e1 \u0623\u064e\u0631\u064e\u0621\u064e\u064a\u06e1\u062a\u064f\u0645\u06e1 \u0625\u0650\u0646\u06e1 \u0623\u064e\u0647\u06e1\u0644\u064e\u0643\u064e\u0646\u0650\u064a\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0645\u064e\u0646 \u0645\u0651\u064e\u0639\u0650\u064a\u064e \u0623\u064e\u0648\u06e1 \u0631\u064e\u062d\u0650\u0645\u064e\u0646\u064e\u0627 \u0641\u064e\u0645\u064e\u0646 \u064a\u064f\u062c\u0650\u064a\u0631\u064f \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064d \u0623\u064e\u0644\u0650\u064a\u0645\u0656",translation:"Katakanlah (Muhammad), \"Tahukah kamu jika Allah mematikan aku dan orang-orang yang bersamaku atau memberi rahmat kepada kami, (maka kami akan masuk surga), lalu siapa yang dapat melindungi orang-orang kafir dari azab yang pedih"},{id:29,text:"\u0642\u064f\u0644\u06e1 \u0647\u064f\u0648\u064e \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u064f \u0621\u064e\u0627\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0647\u0650\u06e6 \u0648\u064e\u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u06e1\u0646\u064e\u0627\u06d6 \u0641\u064e\u0633\u064e\u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0645\u064e\u0646\u06e1 \u0647\u064f\u0648\u064e \u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0670\u0644\u0656 \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u0656",translation:"Katakanlah, \"Dialah Yang Maha Pengasih, kami beriman kepada-Nya dan kepada-Nya kami bertawakal. Maka kelak kamu akan tahu siapa yang berada dalam kesesatan yang nyata"},{id:30,text:"\u0642\u064f\u0644\u06e1 \u0623\u064e\u0631\u064e\u0621\u064e\u064a\u06e1\u062a\u064f\u0645\u06e1 \u0625\u0650\u0646\u06e1 \u0623\u064e\u0635\u06e1\u0628\u064e\u062d\u064e \u0645\u064e\u0627\u0653\u0624\u064f\u0643\u064f\u0645\u06e1 \u063a\u064e\u0648\u06e1\u0631\u0657\u0627 \u0641\u064e\u0645\u064e\u0646 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u0643\u064f\u0645 \u0628\u0650\u0645\u064e\u0627\u0653\u0621\u0656 \u0645\u0651\u064e\u0639\u0650\u064a\u0646\u0650\u06ed",translation:"Katakanlah (Muhammad), \"Terangkanlah kepadaku jika sumber air kamu menjadi kering; maka siapa yang akan memberimu air yang mengalir"}]},{id:68,name:"\u0627\u0644\u0642\u0644\u0645",transliteration:"Al-Qalam",translation:"Pena",type:"meccan",total_verses:52,verses:[{id:1,text:"\u0646\u0653\u06da \u0648\u064e\u0671\u0644\u06e1\u0642\u064e\u0644\u064e\u0645\u0650 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0633\u06e1\u0637\u064f\u0631\u064f\u0648\u0646\u064e",translation:"N\u016bn. Demi pena dan apa yang mereka tuliskan"},{id:2,text:"\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064e \u0628\u0650\u0646\u0650\u0639\u06e1\u0645\u064e\u0629\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0628\u0650\u0645\u064e\u062c\u06e1\u0646\u064f\u0648\u0646\u0656",translation:"dengan karunia Tuhanmu engkau (Muhammad) bukanlah orang gila"},{id:3,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0644\u064e\u0643\u064e \u0644\u064e\u0623\u064e\u062c\u06e1\u0631\u064b\u0627 \u063a\u064e\u064a\u06e1\u0631\u064e \u0645\u064e\u0645\u06e1\u0646\u064f\u0648\u0646\u0656",translation:"Dan sesungguhnya engkau pasti mendapat pahala yang besar yang tidak putus-putusnya"},{id:4,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u0639\u064e\u0644\u064e\u0649\u0670 \u062e\u064f\u0644\u064f\u0642\u064d \u0639\u064e\u0638\u0650\u064a\u0645\u0656",translation:"Dan sesungguhnya engkau benar-benar, berbudi pekerti yang luhur"},{id:5,text:"\u0641\u064e\u0633\u064e\u062a\u064f\u0628\u06e1\u0635\u0650\u0631\u064f \u0648\u064e\u064a\u064f\u0628\u06e1\u0635\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Maka kelak engkau akan melihat dan mereka (orang-orang kafir) pun akan melihat"},{id:6,text:"\u0628\u0650\u0623\u064e\u064a\u064a\u0651\u0650\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064e\u0641\u06e1\u062a\u064f\u0648\u0646\u064f",translation:"siapa diantara kamu yang gila"},{id:7,text:"\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0647\u064f\u0648\u064e \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0646 \u0636\u064e\u0644\u0651\u064e \u0639\u064e\u0646 \u0633\u064e\u0628\u0650\u064a\u0644\u0650\u0647\u0650\u06e6 \u0648\u064e\u0647\u064f\u0648\u064e \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0628\u0650\u0671\u0644\u06e1\u0645\u064f\u0647\u06e1\u062a\u064e\u062f\u0650\u064a\u0646\u064e",translation:"Sungguh, Tuhanmu, Dialah yang paling mengetahui siapa yang sesat dari jalan-Nya; dan Dialah yang paling mengetahui siapa orang yang mendapat petunjuk"},{id:8,text:"\u0641\u064e\u0644\u064e\u0627 \u062a\u064f\u0637\u0650\u0639\u0650 \u0671\u0644\u06e1\u0645\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u0650\u064a\u0646\u064e",translation:"Maka janganlah engkau patuhi orang-orang yang mendustakan (ayat-ayat Allah)"},{id:9,text:"\u0648\u064e\u062f\u0651\u064f\u0648\u0627\u0652 \u0644\u064e\u0648\u06e1 \u062a\u064f\u062f\u06e1\u0647\u0650\u0646\u064f \u0641\u064e\u064a\u064f\u062f\u06e1\u0647\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Mereka menginginkan agar engkau bersikap lunak maka mereka bersikap lunak (pula)"},{id:10,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0637\u0650\u0639\u06e1 \u0643\u064f\u0644\u0651\u064e \u062d\u064e\u0644\u0651\u064e\u0627\u0641\u0656 \u0645\u0651\u064e\u0647\u0650\u064a\u0646\u064d",translation:"Dan janganlah engkau patuhi setiap orang yang suka bersumpah dan suka menghina"},{id:11,text:"\u0647\u064e\u0645\u0651\u064e\u0627\u0632\u0656 \u0645\u0651\u064e\u0634\u0651\u064e\u0627\u0653\u0621\u0650\u06ed \u0628\u0650\u0646\u064e\u0645\u0650\u064a\u0645\u0656",translation:"suka mencela, yang kian ke mari menyebarkan fitnah"},{id:12,text:"\u0645\u0651\u064e\u0646\u0651\u064e\u0627\u0639\u0656 \u0644\u0651\u0650\u0644\u06e1\u062e\u064e\u064a\u06e1\u0631\u0650 \u0645\u064f\u0639\u06e1\u062a\u064e\u062f\u064d \u0623\u064e\u062b\u0650\u064a\u0645\u064d",translation:"yang merintangi segala yang baik, yang melampaui batas dan banyak dosa"},{id:13,text:"\u0639\u064f\u062a\u064f\u0644\u0651\u0650\u06ed \u0628\u064e\u0639\u06e1\u062f\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0632\u064e\u0646\u0650\u064a\u0645\u064d",translation:"yang bertabiat kasar, selain itu juga terkenal kejahatannya"},{id:14,text:"\u0623\u064e\u0646 \u0643\u064e\u0627\u0646\u064e \u0630\u064e\u0627 \u0645\u064e\u0627\u0644\u0656 \u0648\u064e\u0628\u064e\u0646\u0650\u064a\u0646\u064e",translation:"karena dia kaya dan banyak anak"},{id:15,text:"\u0625\u0650\u0630\u064e\u0627 \u062a\u064f\u062a\u06e1\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u064f\u0646\u064e\u0627 \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0633\u064e\u0670\u0637\u0650\u064a\u0631\u064f \u0671\u0644\u06e1\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",translation:"Apabila ayat-ayat Kami dibacakan kepadanya, dia berkata, \"(Ini adalah) dongeng-dongeng orang dahulu"},{id:16,text:"\u0633\u064e\u0646\u064e\u0633\u0650\u0645\u064f\u0647\u064f\u06e5 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u062e\u064f\u0631\u06e1\u0637\u064f\u0648\u0645\u0650",translation:"Kelak dia akan Kami beri tanda pada belalai(nya)"},{id:17,text:"\u0625\u0650\u0646\u0651\u064e\u0627 \u0628\u064e\u0644\u064e\u0648\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0643\u064e\u0645\u064e\u0627 \u0628\u064e\u0644\u064e\u0648\u06e1\u0646\u064e\u0627\u0653 \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064e \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u0625\u0650\u0630\u06e1 \u0623\u064e\u0642\u06e1\u0633\u064e\u0645\u064f\u0648\u0627\u0652 \u0644\u064e\u064a\u064e\u0635\u06e1\u0631\u0650\u0645\u064f\u0646\u0651\u064e\u0647\u064e\u0627 \u0645\u064f\u0635\u06e1\u0628\u0650\u062d\u0650\u064a\u0646\u064e",translation:"Sungguh, Kami telah menguji mereka (orang musyrik Mekkah) sebagaimana Kami telah menguji pemilik-pemilik kebun, ketika mereka bersumpah pasti akan memetik (hasil)nya pada pagi hari"},{id:18,text:"\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u062b\u06e1\u0646\u064f\u0648\u0646\u064e",translation:"tetapi mereka tidak mengecualikan (dengan mengucapkan, \"Insya Allah)"},{id:19,text:"\u0641\u064e\u0637\u064e\u0627\u0641\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627 \u0637\u064e\u0627\u0653\u0626\u0650\u0641\u065e \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064e \u0648\u064e\u0647\u064f\u0645\u06e1 \u0646\u064e\u0627\u0653\u0626\u0650\u0645\u064f\u0648\u0646\u064e",translation:"Lalu kebun itu ditimpa bencana (yang datang) dari Tuhanmu ketika mereka sedang tidur"},{id:20,text:"\u0641\u064e\u0623\u064e\u0635\u06e1\u0628\u064e\u062d\u064e\u062a\u06e1 \u0643\u064e\u0671\u0644\u0635\u0651\u064e\u0631\u0650\u064a\u0645\u0650",translation:"Maka jadilah kebun itu hitam seperti malam yang gelap gulita"},{id:21,text:"\u0641\u064e\u062a\u064e\u0646\u064e\u0627\u062f\u064e\u0648\u06e1\u0627\u0652 \u0645\u064f\u0635\u06e1\u0628\u0650\u062d\u0650\u064a\u0646\u064e",translation:"lalu pada pagi hari mereka saling memanggil"},{id:22,text:"\u0623\u064e\u0646\u0650 \u0671\u063a\u06e1\u062f\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u062d\u064e\u0631\u06e1\u062b\u0650\u0643\u064f\u0645\u06e1 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u0635\u064e\u0670\u0631\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Pergilah pagi-pagi ke kebunmu jika kamu hendak memetik hasil"},{id:23,text:"\u0641\u064e\u0671\u0646\u0637\u064e\u0644\u064e\u0642\u064f\u0648\u0627\u0652 \u0648\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u062a\u064e\u062e\u064e\u0670\u0641\u064e\u062a\u064f\u0648\u0646\u064e",translation:"Maka mereka pun berangkat sambil berbisik-bisik"},{id:24,text:"\u0623\u064e\u0646 \u0644\u0651\u064e\u0627 \u064a\u064e\u062f\u06e1\u062e\u064f\u0644\u064e\u0646\u0651\u064e\u0647\u064e\u0627 \u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645 \u0645\u0651\u0650\u0633\u06e1\u0643\u0650\u064a\u0646\u065e",translation:"Pada hari ini jangan sampai ada orang miskin masuk ke dalam kebunmu"},{id:25,text:"\u0648\u064e\u063a\u064e\u062f\u064e\u0648\u06e1\u0627\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u062d\u064e\u0631\u06e1\u062f\u0656 \u0642\u064e\u0670\u062f\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan berangkatlah mereka di pagi hari dengan niat menghalangi (orang-orang miskin) padahal mereka mampu (menolongnya)"},{id:26,text:"\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0631\u064e\u0623\u064e\u0648\u06e1\u0647\u064e\u0627 \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0636\u064e\u0627\u0653\u0644\u0651\u064f\u0648\u0646\u064e",translation:"Maka ketika mereka melihat kebun itu, mereka berkata, \"Sungguh, kita ini benar-benar orang-orang yang sesat"},{id:27,text:"\u0628\u064e\u0644\u06e1 \u0646\u064e\u062d\u06e1\u0646\u064f \u0645\u064e\u062d\u06e1\u0631\u064f\u0648\u0645\u064f\u0648\u0646\u064e",translation:"bahkan kita tak memperoleh apa pun"},{id:28,text:"\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0648\u06e1\u0633\u064e\u0637\u064f\u0647\u064f\u0645\u06e1 \u0623\u064e\u0644\u064e\u0645\u06e1 \u0623\u064e\u0642\u064f\u0644 \u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u0644\u064e\u0648\u06e1\u0644\u064e\u0627 \u062a\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u064f\u0648\u0646\u064e",translation:"Berkatalah seorang yang paling bijak di antara mereka, \"Bukankah aku telah mengatakan kepadamu, mengapa kamu tidak bertasbih (kepada Tuhanmu)"},{id:29,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0633\u064f\u0628\u06e1\u062d\u064e\u0670\u0646\u064e \u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0638\u064e\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Mereka mengucapkan, \"Mahasuci Tuhan kami, sungguh, kami adalah orang-orang yang zalim"},{id:30,text:"\u0641\u064e\u0623\u064e\u0642\u06e1\u0628\u064e\u0644\u064e \u0628\u064e\u0639\u06e1\u0636\u064f\u0647\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u06e1\u0636\u0656 \u064a\u064e\u062a\u064e\u0644\u064e\u0670\u0648\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Lalu mereka saling berhadapan dan saling menyalahkan"},{id:31,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u064a\u064e\u0670\u0648\u064e\u064a\u06e1\u0644\u064e\u0646\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0637\u064e\u0670\u063a\u0650\u064a\u0646\u064e",translation:"Mereka berkata, \"Celaka kita! Sesungguhnya kita orang-orang yang melampaui batas"},{id:32,text:"\u0639\u064e\u0633\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u064f\u0646\u064e\u0627\u0653 \u0623\u064e\u0646 \u064a\u064f\u0628\u06e1\u062f\u0650\u0644\u064e\u0646\u064e\u0627 \u062e\u064e\u064a\u06e1\u0631\u0657\u0627 \u0645\u0651\u0650\u0646\u06e1\u0647\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627 \u0631\u064e\u0670\u063a\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Mudah-mudahan Tuhan memberikan ganti kepada kita dengan (kebun) yang lebih baik daripada yang ini, sungguh, kita mengharapkan ampunan dari Tuhan kita"},{id:33,text:"\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064f\u06d6 \u0648\u064e\u0644\u064e\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0623\u064e\u0643\u06e1\u0628\u064e\u0631\u064f\u06da \u0644\u064e\u0648\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Seperti itulah azab (di dunia). Dan sungguh, azab akhirat lebih besar sekiranya mereka mengetahui"},{id:34,text:"\u0625\u0650\u0646\u0651\u064e \u0644\u0650\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e \u0639\u0650\u0646\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0650 \u0671\u0644\u0646\u0651\u064e\u0639\u0650\u064a\u0645\u0650",translation:"Sungguh, bagi orang-orang yang bertakwa (disediakan) surga yang penuh kenikmatan di sisi Tuhannya"},{id:35,text:"\u0623\u064e\u0641\u064e\u0646\u064e\u062c\u06e1\u0639\u064e\u0644\u064f \u0671\u0644\u06e1\u0645\u064f\u0633\u06e1\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0643\u064e\u0671\u0644\u06e1\u0645\u064f\u062c\u06e1\u0631\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Apakah patut Kami memperlakukan orang-orang Islam itu seperti orang-orang yang berdosa (orang kafir)"},{id:36,text:"\u0645\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0643\u064e\u064a\u06e1\u0641\u064e \u062a\u064e\u062d\u06e1\u0643\u064f\u0645\u064f\u0648\u0646\u064e",translation:"Mengapa kamu (berbuat demikian)? Bagaimana kamu mengambil keputusan"},{id:37,text:"\u0623\u064e\u0645\u06e1 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0643\u0650\u062a\u064e\u0670\u0628\u065e \u0641\u0650\u064a\u0647\u0650 \u062a\u064e\u062f\u06e1\u0631\u064f\u0633\u064f\u0648\u0646\u064e",translation:"Atau apakah kamu mempunyai kitab (yang diturunkan Allah) yang kamu pelajari"},{id:38,text:"\u0625\u0650\u0646\u0651\u064e \u0644\u064e\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u0650 \u0644\u064e\u0645\u064e\u0627 \u062a\u064e\u062e\u064e\u064a\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"sesungguhnya kamu dapat memilih apa saja yang ada di dalamnya"},{id:39,text:"\u0623\u064e\u0645\u06e1 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u064c \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0628\u064e\u0670\u0644\u0650\u063a\u064e\u0629\u064c \u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650 \u0625\u0650\u0646\u0651\u064e \u0644\u064e\u0643\u064f\u0645\u06e1 \u0644\u064e\u0645\u064e\u0627 \u062a\u064e\u062d\u06e1\u0643\u064f\u0645\u064f\u0648\u0646\u064e",translation:"Atau apakah kamu memperoleh (janji-janji yang diperkuat dengan) sumpah dari Kami, yang tetap berlaku sampai hari Kiamat; bahwa kamu dapat mengambil keputusan (sekehendakmu)"},{id:40,text:"\u0633\u064e\u0644\u06e1\u0647\u064f\u0645\u06e1 \u0623\u064e\u064a\u0651\u064f\u0647\u064f\u0645 \u0628\u0650\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0632\u064e\u0639\u0650\u064a\u0645\u064c",translation:"Tanyakanlah kepada mereka, \"Siapakah di antara mereka yang bertanggung jawab terhadap (keputusan yang diambil itu)"},{id:41,text:"\u0623\u064e\u0645\u06e1 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0653\u0621\u064f \u0641\u064e\u0644\u06e1\u064a\u064e\u0623\u06e1\u062a\u064f\u0648\u0627\u0652 \u0628\u0650\u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0653\u0626\u0650\u0647\u0650\u0645\u06e1 \u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0635\u064e\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e",translation:"Atau apakah mereka mempunyai sekutu-sekutu? Kalau begitu hendaklah mereka mendatangkan sekutu-sekutunya jika mereka orang-orang yang benar"},{id:42,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064f\u0643\u06e1\u0634\u064e\u0641\u064f \u0639\u064e\u0646 \u0633\u064e\u0627\u0642\u0656 \u0648\u064e\u064a\u064f\u062f\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0633\u0651\u064f\u062c\u064f\u0648\u062f\u0650 \u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u062a\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u064e",translation:"(Ingatlah) pada hari ketika betis disingkapkan851) dan mereka diseru untuk bersujud; maka mereka tidak mampu"},{id:43,text:"\u062e\u064e\u0670\u0634\u0650\u0639\u064e\u0629\u064b \u0623\u064e\u0628\u06e1\u0635\u064e\u0670\u0631\u064f\u0647\u064f\u0645\u06e1 \u062a\u064e\u0631\u06e1\u0647\u064e\u0642\u064f\u0647\u064f\u0645\u06e1 \u0630\u0650\u0644\u0651\u064e\u0629\u065e\u06d6 \u0648\u064e\u0642\u064e\u062f\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064f\u062f\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0633\u0651\u064f\u062c\u064f\u0648\u062f\u0650 \u0648\u064e\u0647\u064f\u0645\u06e1 \u0633\u064e\u0670\u0644\u0650\u0645\u064f\u0648\u0646\u064e",translation:"pandangan mereka tertunduk ke bawah, diliputi kehinaan. Dan sungguh, dahulu (di dunia) mereka telah diseru untuk bersujud waktu mereka sehat (tetapi mereka tidak melakukan)"},{id:44,text:"\u0641\u064e\u0630\u064e\u0631\u06e1\u0646\u0650\u064a \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f \u0628\u0650\u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u06e1\u062d\u064e\u062f\u0650\u064a\u062b\u0650\u06d6 \u0633\u064e\u0646\u064e\u0633\u06e1\u062a\u064e\u062f\u06e1\u0631\u0650\u062c\u064f\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u062d\u064e\u064a\u06e1\u062b\u064f \u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Maka serahkanlah kepada-Ku (urusannya) dan orang-orang yang mendustakan perkataan ini (Alquran). Kelak akan Kami hukum mereka berangsur-angsur dari arah yang tidak mereka ketahui"},{id:45,text:"\u0648\u064e\u0623\u064f\u0645\u06e1\u0644\u0650\u064a \u0644\u064e\u0647\u064f\u0645\u06e1\u06da \u0625\u0650\u0646\u0651\u064e \u0643\u064e\u064a\u06e1\u062f\u0650\u064a \u0645\u064e\u062a\u0650\u064a\u0646\u064c",translation:"dan Aku memberi tenggang waktu kepada mereka. Sungguh, rencana-Ku sangat teguh"},{id:46,text:"\u0623\u064e\u0645\u06e1 \u062a\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0647\u064f\u0645\u06e1 \u0623\u064e\u062c\u06e1\u0631\u0657\u0627 \u0641\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0645\u0651\u064e\u063a\u06e1\u0631\u064e\u0645\u0656 \u0645\u0651\u064f\u062b\u06e1\u0642\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Ataukah engkau (Muhammad) meminta imbalan kepada mereka, sehingga mereka dibebani dengan hutang"},{id:47,text:"\u0623\u064e\u0645\u06e1 \u0639\u0650\u0646\u062f\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u0628\u064f \u0641\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0643\u06e1\u062a\u064f\u0628\u064f\u0648\u0646\u064e",translation:"Ataukah mereka mengetahui yang gaib, lalu mereka menuliskannya"},{id:48,text:"\u0641\u064e\u0671\u0635\u06e1\u0628\u0650\u0631\u06e1 \u0644\u0650\u062d\u064f\u0643\u06e1\u0645\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0646 \u0643\u064e\u0635\u064e\u0627\u062d\u0650\u0628\u0650 \u0671\u0644\u06e1\u062d\u064f\u0648\u062a\u0650 \u0625\u0650\u0630\u06e1 \u0646\u064e\u0627\u062f\u064e\u0649\u0670 \u0648\u064e\u0647\u064f\u0648\u064e \u0645\u064e\u0643\u06e1\u0638\u064f\u0648\u0645\u065e",translation:"Maka bersabarlah engkau (Muhammad) terhadap ketetapan Tuhanmu, dan janganlah engkau seperti (Yunus) orang yang berada dalam (perut) ikan ketika dia berdoa dengan hati sedih"},{id:49,text:"\u0644\u0651\u064e\u0648\u06e1\u0644\u064e\u0627\u0653 \u0623\u064e\u0646 \u062a\u064e\u062f\u064e\u0670\u0631\u064e\u0643\u064e\u0647\u064f\u06e5 \u0646\u0650\u0639\u06e1\u0645\u064e\u0629\u065e \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0647\u0650\u06e6 \u0644\u064e\u0646\u064f\u0628\u0650\u0630\u064e \u0628\u0650\u0671\u0644\u06e1\u0639\u064e\u0631\u064e\u0627\u0653\u0621\u0650 \u0648\u064e\u0647\u064f\u0648\u064e \u0645\u064e\u0630\u06e1\u0645\u064f\u0648\u0645\u065e",translation:"Sekiranya dia tidak segera mendapat nikmat dari Tuhannya, pastilah dia dicampakkan ke tanah tandus dalam keadaan tercela"},{id:50,text:"\u0641\u064e\u0671\u062c\u06e1\u062a\u064e\u0628\u064e\u0670\u0647\u064f \u0631\u064e\u0628\u0651\u064f\u0647\u064f\u06e5 \u0641\u064e\u062c\u064e\u0639\u064e\u0644\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u0650\u064a\u0646\u064e",translation:"Lalu Tuhannya memilihnya dan menjadikannya termasuk orang yang saleh"},{id:51,text:"\u0648\u064e\u0625\u0650\u0646 \u064a\u064e\u0643\u064e\u0627\u062f\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0644\u064e\u064a\u064f\u0632\u06e1\u0644\u0650\u0642\u064f\u0648\u0646\u064e\u0643\u064e \u0628\u0650\u0623\u064e\u0628\u06e1\u0635\u064e\u0670\u0631\u0650\u0647\u0650\u0645\u06e1 \u0644\u064e\u0645\u0651\u064e\u0627 \u0633\u064e\u0645\u0650\u0639\u064f\u0648\u0627\u0652 \u0671\u0644\u0630\u0651\u0650\u0643\u06e1\u0631\u064e \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0645\u064e\u062c\u06e1\u0646\u064f\u0648\u0646\u065e",translation:"Dan sungguh, orang-orang kafir itu hampir-hampir menggelincirkanmu dengan pandangan mata mereka, ketika mereka mendengar Alquran dan mereka berkata, \"Dia (Muhammad) itu benar-benar orang gila"},{id:52,text:"\u0648\u064e\u0645\u064e\u0627 \u0647\u064f\u0648\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0630\u0650\u0643\u06e1\u0631\u065e \u0644\u0651\u0650\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Padahal Alquran itu tidak lain adalah peringatan bagi seluruh alam"}]},{id:69,name:"\u0627\u0644\u062d\u0627\u0642\u0629",transliteration:"Al-Haqqah",translation:"Kenyataan (Hari Kiamat)",type:"meccan",total_verses:52,verses:[{id:1,text:"\u0671\u0644\u06e1\u062d\u064e\u0627\u0653\u0642\u0651\u064e\u0629\u064f",translation:"Hari kiamat"},{id:2,text:"\u0645\u064e\u0627 \u0671\u0644\u06e1\u062d\u064e\u0627\u0653\u0642\u0651\u064e\u0629\u064f",translation:"apakah hari Kiamat itu"},{id:3,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u062f\u06e1\u0631\u064e\u0649\u0670\u0643\u064e \u0645\u064e\u0627 \u0671\u0644\u06e1\u062d\u064e\u0627\u0653\u0642\u0651\u064e\u0629\u064f",translation:"Dan tahukah kamu apakah hari Kiamat itu"},{id:4,text:"\u0643\u064e\u0630\u0651\u064e\u0628\u064e\u062a\u06e1 \u062b\u064e\u0645\u064f\u0648\u062f\u064f \u0648\u064e\u0639\u064e\u0627\u062f\u064f\u06e2 \u0628\u0650\u0671\u0644\u06e1\u0642\u064e\u0627\u0631\u0650\u0639\u064e\u0629\u0650",translation:"Kaum Samud, dan '\u0100d telah mendustakan hari Kiamat"},{id:5,text:"\u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u062b\u064e\u0645\u064f\u0648\u062f\u064f \u0641\u064e\u0623\u064f\u0647\u06e1\u0644\u0650\u0643\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u0637\u0651\u064e\u0627\u063a\u0650\u064a\u064e\u0629\u0650",translation:"Maka adapun kaum Samud, mereka telah dibinasakan dengan suara yang sangat keras"},{id:6,text:"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0639\u064e\u0627\u062f\u065e \u0641\u064e\u0623\u064f\u0647\u06e1\u0644\u0650\u0643\u064f\u0648\u0627\u0652 \u0628\u0650\u0631\u0650\u064a\u062d\u0656 \u0635\u064e\u0631\u06e1\u0635\u064e\u0631\u064d \u0639\u064e\u0627\u062a\u0650\u064a\u064e\u0629\u0656",translation:"sedangkan kaum '\u0100d, mereka telah dibinasakan dengan angin topan yang sangat dingin"},{id:7,text:"\u0633\u064e\u062e\u0651\u064e\u0631\u064e\u0647\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0633\u064e\u0628\u06e1\u0639\u064e \u0644\u064e\u064a\u064e\u0627\u0644\u0656 \u0648\u064e\u062b\u064e\u0645\u064e\u0670\u0646\u0650\u064a\u064e\u0629\u064e \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u064d \u062d\u064f\u0633\u064f\u0648\u0645\u0657\u0627\u06d6 \u0641\u064e\u062a\u064e\u0631\u064e\u0649 \u0671\u0644\u06e1\u0642\u064e\u0648\u06e1\u0645\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0635\u064e\u0631\u06e1\u0639\u064e\u0649\u0670 \u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u0639\u06e1\u062c\u064e\u0627\u0632\u064f \u0646\u064e\u062e\u06e1\u0644\u064d \u062e\u064e\u0627\u0648\u0650\u064a\u064e\u0629\u0656",translation:"Allah menimpakan angin itu kepada mereka selama tujuh malam delapan hari terus-menerus; maka kamu melihat kaum '\u0100d pada waktu itu mati bergelimpangan seperti batang-batang pohon kurma yang telah kosong (lapuk)"},{id:8,text:"\u0641\u064e\u0647\u064e\u0644\u06e1 \u062a\u064e\u0631\u064e\u0649\u0670 \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u06e2 \u0628\u064e\u0627\u0642\u0650\u064a\u064e\u0629\u0656",translation:"Maka adakah kamu melihat seorang pun yang masih tersisa di antara mereka"},{id:9,text:"\u0648\u064e\u062c\u064e\u0627\u0653\u0621\u064e \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064f \u0648\u064e\u0645\u064e\u0646 \u0642\u064e\u0628\u06e1\u0644\u064e\u0647\u064f\u06e5 \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u062a\u064e\u0641\u0650\u0643\u064e\u0670\u062a\u064f \u0628\u0650\u0671\u0644\u06e1\u062e\u064e\u0627\u0637\u0650\u0626\u064e\u0629\u0650",translation:"Kemudian datang Fir'aun dan orang-orang yang sebelumnya dan (penduduk) negeri-negeri yang dijungkir balikkan karena kesalahan yang besar"},{id:10,text:"\u0641\u064e\u0639\u064e\u0635\u064e\u0648\u06e1\u0627\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0641\u064e\u0623\u064e\u062e\u064e\u0630\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u062e\u06e1\u0630\u064e\u0629\u0657 \u0631\u0651\u064e\u0627\u0628\u0650\u064a\u064e\u0629\u064b",translation:"Maka mereka mendurhakai utusan Tuhannya, Allah menyiksa mereka dengan siksaan yang sangat keras"},{id:11,text:"\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0645\u0651\u064e\u0627 \u0637\u064e\u063a\u064e\u0627 \u0671\u0644\u06e1\u0645\u064e\u0627\u0653\u0621\u064f \u062d\u064e\u0645\u064e\u0644\u06e1\u0646\u064e\u0670\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u062c\u064e\u0627\u0631\u0650\u064a\u064e\u0629\u0650",translation:"Sesungguhnya ketika air naik (sampai ke gunung), Kami membawa (nenek moyang) kamu859) ke dalam kapal"},{id:12,text:"\u0644\u0650\u0646\u064e\u062c\u06e1\u0639\u064e\u0644\u064e\u0647\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u06e1 \u062a\u064e\u0630\u06e1\u0643\u0650\u0631\u064e\u0629\u0657 \u0648\u064e\u062a\u064e\u0639\u0650\u064a\u064e\u0647\u064e\u0627\u0653 \u0623\u064f\u0630\u064f\u0646\u065e \u0648\u064e\u0670\u0639\u0650\u064a\u064e\u0629\u065e",translation:"agar Kami jadikan (peristiwa itu) sebagai peringatan bagi kamu dan agar diperhatikan oleh telinga yang mau mendengar"},{id:13,text:"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0646\u064f\u0641\u0650\u062e\u064e \u0641\u0650\u064a \u0671\u0644\u0635\u0651\u064f\u0648\u0631\u0650 \u0646\u064e\u0641\u06e1\u062e\u064e\u0629\u065e \u0648\u064e\u0670\u062d\u0650\u062f\u064e\u0629\u065e",translation:"Maka apabila sangkakala ditiup sekali tiup"},{id:14,text:"\u0648\u064e\u062d\u064f\u0645\u0650\u0644\u064e\u062a\u0650 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064f \u0648\u064e\u0671\u0644\u06e1\u062c\u0650\u0628\u064e\u0627\u0644\u064f \u0641\u064e\u062f\u064f\u0643\u0651\u064e\u062a\u064e\u0627 \u062f\u064e\u0643\u0651\u064e\u0629\u0657 \u0648\u064e\u0670\u062d\u0650\u062f\u064e\u0629\u0657",translation:"dan diangkatlah bumi dan gunung-gunung, lalu dibenturkan keduanya sekali benturan"},{id:15,text:"\u0641\u064e\u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u0648\u064e\u0642\u064e\u0639\u064e\u062a\u0650 \u0671\u0644\u06e1\u0648\u064e\u0627\u0642\u0650\u0639\u064e\u0629\u064f",translation:"Maka pada hari itu terjadilah hari Kiamat"},{id:16,text:"\u0648\u064e\u0671\u0646\u0634\u064e\u0642\u0651\u064e\u062a\u0650 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u064f \u0641\u064e\u0647\u0650\u064a\u064e \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u0648\u064e\u0627\u0647\u0650\u064a\u064e\u0629\u065e",translation:"dan terbelahlah langit, karena pada hari itu langit menjadi rapuh"},{id:17,text:"\u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0643\u064f \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0631\u06e1\u062c\u064e\u0627\u0653\u0626\u0650\u0647\u064e\u0627\u06da \u0648\u064e\u064a\u064e\u062d\u06e1\u0645\u0650\u0644\u064f \u0639\u064e\u0631\u06e1\u0634\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0641\u064e\u0648\u06e1\u0642\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u062b\u064e\u0645\u064e\u0670\u0646\u0650\u064a\u064e\u0629\u065e",translation:"Dan para malaikat berada di berbagai penjuru langit. Pada hari itu delapan malaikat menjunjung Arasy (singgasana) Tuhanmu di atas (kepala) mereka"},{id:18,text:"\u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u062a\u064f\u0639\u06e1\u0631\u064e\u0636\u064f\u0648\u0646\u064e \u0644\u064e\u0627 \u062a\u064e\u062e\u06e1\u0641\u064e\u0649\u0670 \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u062e\u064e\u0627\u0641\u0650\u064a\u064e\u0629\u065e",translation:"Pada hari itu kamu dihadapkan (kepada Tuhanmu), tidak ada sesuatu pun dari kamu yang tersembunyi (bagi Allah)"},{id:19,text:"\u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0645\u064e\u0646\u06e1 \u0623\u064f\u0648\u062a\u0650\u064a\u064e \u0643\u0650\u062a\u064e\u0670\u0628\u064e\u0647\u064f\u06e5 \u0628\u0650\u064a\u064e\u0645\u0650\u064a\u0646\u0650\u0647\u0650\u06e6 \u0641\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0647\u064e\u0627\u0653\u0624\u064f\u0645\u064f \u0671\u0642\u06e1\u0631\u064e\u0621\u064f\u0648\u0627\u0652 \u0643\u0650\u062a\u064e\u0670\u0628\u0650\u064a\u064e\u0647\u06e1",translation:"(Adapun orang yang kitabnya861) diberikan di tangan kanannya, maka dia berkata, \"Ambillah, bacalah kitabku (ini)"},{id:20,text:"\u0625\u0650\u0646\u0651\u0650\u064a \u0638\u064e\u0646\u064e\u0646\u062a\u064f \u0623\u064e\u0646\u0651\u0650\u064a \u0645\u064f\u0644\u064e\u0670\u0642\u064d \u062d\u0650\u0633\u064e\u0627\u0628\u0650\u064a\u064e\u0647\u06e1",translation:"Sesungguhnya aku yakin, bahwa (suatu saat) aku akan menerima perhitungan terhadap diriku"},{id:21,text:"\u0641\u064e\u0647\u064f\u0648\u064e \u0641\u0650\u064a \u0639\u0650\u064a\u0634\u064e\u0629\u0656 \u0631\u0651\u064e\u0627\u0636\u0650\u064a\u064e\u0629\u0656",translation:"Maka orang itu berada dalam kehidupan yang diridai"},{id:22,text:"\u0641\u0650\u064a \u062c\u064e\u0646\u0651\u064e\u0629\u064d \u0639\u064e\u0627\u0644\u0650\u064a\u064e\u0629\u0656",translation:"dalam surga yang tinggi"},{id:23,text:"\u0642\u064f\u0637\u064f\u0648\u0641\u064f\u0647\u064e\u0627 \u062f\u064e\u0627\u0646\u0650\u064a\u064e\u0629\u065e",translation:"buah-buahannya dekat"},{id:24,text:"\u0643\u064f\u0644\u064f\u0648\u0627\u0652 \u0648\u064e\u0671\u0634\u06e1\u0631\u064e\u0628\u064f\u0648\u0627\u0652 \u0647\u064e\u0646\u0650\u064a\u0653\u0640\u0654\u064e\u06e2\u0627 \u0628\u0650\u0645\u064e\u0627\u0653 \u0623\u064e\u0633\u06e1\u0644\u064e\u0641\u06e1\u062a\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u064a\u0651\u064e\u0627\u0645\u0650 \u0671\u0644\u06e1\u062e\u064e\u0627\u0644\u0650\u064a\u064e\u0629\u0650",translation:"(kepada mereka dikatakan), \"Makan dan minumlah dengan nikmat karena amal yang telah kamu kerjakan pada hari-hari yang telah lalu"},{id:25,text:"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0645\u064e\u0646\u06e1 \u0623\u064f\u0648\u062a\u0650\u064a\u064e \u0643\u0650\u062a\u064e\u0670\u0628\u064e\u0647\u064f\u06e5 \u0628\u0650\u0634\u0650\u0645\u064e\u0627\u0644\u0650\u0647\u0650\u06e6 \u0641\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u064a\u064e\u0670\u0644\u064e\u064a\u06e1\u062a\u064e\u0646\u0650\u064a \u0644\u064e\u0645\u06e1 \u0623\u064f\u0648\u062a\u064e \u0643\u0650\u062a\u064e\u0670\u0628\u0650\u064a\u064e\u0647\u06e1",translation:"Dan adapun orang yang kitabnya diberikan di tangan kirinya, maka dia berkata, \"Alangkah baiknya jika kitabku (ini) tidak diberikan kepadaku"},{id:26,text:"\u0648\u064e\u0644\u064e\u0645\u06e1 \u0623\u064e\u062f\u06e1\u0631\u0650 \u0645\u064e\u0627 \u062d\u0650\u0633\u064e\u0627\u0628\u0650\u064a\u064e\u0647\u06e1",translation:"Sehingga aku tidak mengetahui bagaimana perhitunganku"},{id:27,text:"\u064a\u064e\u0670\u0644\u064e\u064a\u06e1\u062a\u064e\u0647\u064e\u0627 \u0643\u064e\u0627\u0646\u064e\u062a\u0650 \u0671\u0644\u06e1\u0642\u064e\u0627\u0636\u0650\u064a\u064e\u0629\u064e",translation:"Wahai, kiranya (kematian) itulah yang menyudahi segala sesuatu"},{id:28,text:"\u0645\u064e\u0627\u0653 \u0623\u064e\u063a\u06e1\u0646\u064e\u0649\u0670 \u0639\u064e\u0646\u0651\u0650\u064a \u0645\u064e\u0627\u0644\u0650\u064a\u064e\u0647\u06e1\u06dc",translation:"Hartaku sama sekali tidak berguna bagiku"},{id:29,text:"\u0647\u064e\u0644\u064e\u0643\u064e \u0639\u064e\u0646\u0651\u0650\u064a \u0633\u064f\u0644\u06e1\u0637\u064e\u0670\u0646\u0650\u064a\u064e\u0647\u06e1",translation:"Kekuasaanku telah hilang dariku"},{id:30,text:"\u062e\u064f\u0630\u064f\u0648\u0647\u064f \u0641\u064e\u063a\u064f\u0644\u0651\u064f\u0648\u0647\u064f",translation:"(Allah berfirman), \"Tangkaplah dia lalu belenggulah tangannya ke lehernya"},{id:31,text:"\u062b\u064f\u0645\u0651\u064e \u0671\u0644\u06e1\u062c\u064e\u062d\u0650\u064a\u0645\u064e \u0635\u064e\u0644\u0651\u064f\u0648\u0647\u064f",translation:"Kemudian masukkanlah dia ke dalam api neraka yang menyala-nyala"},{id:32,text:"\u062b\u064f\u0645\u0651\u064e \u0641\u0650\u064a \u0633\u0650\u0644\u06e1\u0633\u0650\u0644\u064e\u0629\u0656 \u0630\u064e\u0631\u06e1\u0639\u064f\u0647\u064e\u0627 \u0633\u064e\u0628\u06e1\u0639\u064f\u0648\u0646\u064e \u0630\u0650\u0631\u064e\u0627\u0639\u0657\u0627 \u0641\u064e\u0671\u0633\u06e1\u0644\u064f\u0643\u064f\u0648\u0647\u064f",translation:"Kemudian belitlah dia dengan rantai yang panjangnya tujuh puluh hasta"},{id:33,text:"\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u0639\u064e\u0638\u0650\u064a\u0645\u0650",translation:"Sesungguhnya dialah orang yang tidak beriman kepada Allah Yang Mahabesar"},{id:34,text:"\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062d\u064f\u0636\u0651\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0637\u064e\u0639\u064e\u0627\u0645\u0650 \u0671\u0644\u06e1\u0645\u0650\u0633\u06e1\u0643\u0650\u064a\u0646\u0650",translation:"Dan juga dia tidak mendorong (orang lain) untuk memberi makan orang miskin"},{id:35,text:"\u0641\u064e\u0644\u064e\u064a\u06e1\u0633\u064e \u0644\u064e\u0647\u064f \u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e \u0647\u064e\u0670\u0647\u064f\u0646\u064e\u0627 \u062d\u064e\u0645\u0650\u064a\u0645\u065e",translation:"Maka pada hari ini di sini tidak ada seorang teman pun baginya"},{id:36,text:"\u0648\u064e\u0644\u064e\u0627 \u0637\u064e\u0639\u064e\u0627\u0645\u064c \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u0650\u0646\u06e1 \u063a\u0650\u0633\u06e1\u0644\u0650\u064a\u0646\u0656",translation:"Dan tidak ada makanan (baginya) kecuali dari darah dan nanah"},{id:37,text:"\u0644\u0651\u064e\u0627 \u064a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f\u0647\u064f\u06e5\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u06e1\u062e\u064e\u0670\u0637\u0650\u0640\u0654\u064f\u0648\u0646\u064e",translation:"Tidak ada yang memakannya kecuali orang-orang yang berdosa"},{id:38,text:"\u0641\u064e\u0644\u064e\u0627\u0653 \u0623\u064f\u0642\u06e1\u0633\u0650\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064f\u0628\u06e1\u0635\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Maka Aku bersumpah demi apa yang kamu lihat"},{id:39,text:"\u0648\u064e\u0645\u064e\u0627 \u0644\u064e\u0627 \u062a\u064f\u0628\u06e1\u0635\u0650\u0631\u064f\u0648\u0646\u064e",translation:"dan demi apa yang tidak kamu lihat"},{id:40,text:"\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0642\u064e\u0648\u06e1\u0644\u064f \u0631\u064e\u0633\u064f\u0648\u0644\u0656 \u0643\u064e\u0631\u0650\u064a\u0645\u0656",translation:"Sesungguhnya ia (Alquran) benar-benar wahyu (yang diturunkan kepada) Rasul yang mulia"},{id:41,text:"\u0648\u064e\u0645\u064e\u0627 \u0647\u064f\u0648\u064e \u0628\u0650\u0642\u064e\u0648\u06e1\u0644\u0650 \u0634\u064e\u0627\u0639\u0650\u0631\u0656\u06da \u0642\u064e\u0644\u0650\u064a\u0644\u0657\u0627 \u0645\u0651\u064e\u0627 \u062a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"dan ia (Alquran) bukanlah perkataan seorang penyair. Sedikit sekali kamu yang beriman kepadanya"},{id:42,text:"\u0648\u064e\u0644\u064e\u0627 \u0628\u0650\u0642\u064e\u0648\u06e1\u0644\u0650 \u0643\u064e\u0627\u0647\u0650\u0646\u0656\u06da \u0642\u064e\u0644\u0650\u064a\u0644\u0657\u0627 \u0645\u0651\u064e\u0627 \u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",translation:"Dan bukan pula perkataan tukang tenung. Sedikit sekali kamu yang mengambil pelajaran darinya"},{id:43,text:"\u062a\u064e\u0646\u0632\u0650\u064a\u0644\u065e \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Ia (Alquran) adalah wahyu yang diturunkan dari Tuhan seluruh alam"},{id:44,text:"\u0648\u064e\u0644\u064e\u0648\u06e1 \u062a\u064e\u0642\u064e\u0648\u0651\u064e\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0628\u064e\u0639\u06e1\u0636\u064e \u0671\u0644\u06e1\u0623\u064e\u0642\u064e\u0627\u0648\u0650\u064a\u0644\u0650",translation:"Dan sekiranya dia (Muhammad) mengada-adakan sebagian perkataan atas (nama) Kami"},{id:45,text:"\u0644\u064e\u0623\u064e\u062e\u064e\u0630\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646\u06e1\u0647\u064f \u0628\u0650\u0671\u0644\u06e1\u064a\u064e\u0645\u0650\u064a\u0646\u0650",translation:"pasti Kami pegang dia pada tangan kanannya"},{id:46,text:"\u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0642\u064e\u0637\u064e\u0639\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646\u06e1\u0647\u064f \u0671\u0644\u06e1\u0648\u064e\u062a\u0650\u064a\u0646\u064e",translation:"Kemudian Kami potong pembuluh jantungnya"},{id:47,text:"\u0641\u064e\u0645\u064e\u0627 \u0645\u0650\u0646\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u062d\u064e\u062f\u064d \u0639\u064e\u0646\u06e1\u0647\u064f \u062d\u064e\u0670\u062c\u0650\u0632\u0650\u064a\u0646\u064e",translation:"Maka tidak seorang pun dari kamu yang dapat menghalangi (Kami untuk menghukumnya)"},{id:48,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u062a\u064e\u0630\u06e1\u0643\u0650\u0631\u064e\u0629\u065e \u0644\u0651\u0650\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",translation:"Dan sungguh, Alquran itu pelajaran bagi orang-orang yang bertakwa"},{id:49,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0646\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0623\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u0643\u064f\u0645 \u0645\u0651\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u0650\u064a\u0646\u064e",translation:"Dan sungguh, Kami mengetahui bahwa di antara kamu ada orang yang mendustakan"},{id:50,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u062d\u064e\u0633\u06e1\u0631\u064e\u0629\u064c \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Dan sungguh, Alquran itu akan menimbulkan penyesalan bagi orang-orang kafir (di akhirat)"},{id:51,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u062d\u064e\u0642\u0651\u064f \u0671\u0644\u06e1\u064a\u064e\u0642\u0650\u064a\u0646\u0650",translation:"Dan sungguh, Alquran itu kebenaran yang meyakinkan"},{id:52,text:"\u0641\u064e\u0633\u064e\u0628\u0651\u0650\u062d\u06e1 \u0628\u0650\u0671\u0633\u06e1\u0645\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0671\u0644\u06e1\u0639\u064e\u0638\u0650\u064a\u0645\u0650",translation:"Maka bertasbihlah dengan (menyebut) nama Tuhanmu Yang Mahaagung"}]},{id:70,name:"\u0627\u0644\u0645\u0639\u0627\u0631\u062c",transliteration:"Al-Ma'arij",translation:"Tempat yang Naik",type:"meccan",total_verses:44,verses:[{id:1,text:"\u0633\u064e\u0623\u064e\u0644\u064e \u0633\u064e\u0627\u0653\u0626\u0650\u0644\u064f\u06e2 \u0628\u0650\u0639\u064e\u0630\u064e\u0627\u0628\u0656 \u0648\u064e\u0627\u0642\u0650\u0639\u0656",translation:"Seseorang bertanya tentang azab yang pasti terjadi"},{id:2,text:"\u0644\u0651\u0650\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0644\u064e\u064a\u06e1\u0633\u064e \u0644\u064e\u0647\u064f\u06e5 \u062f\u064e\u0627\u0641\u0650\u0639\u065e",translation:"Bagi orang-orang kafir, yang tidak seorang pun dapat menolaknya"},{id:3,text:"\u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0630\u0650\u064a \u0671\u0644\u06e1\u0645\u064e\u0639\u064e\u0627\u0631\u0650\u062c\u0650",translation:"(Azab) dari Allah, yang memiliki tempat-tempat naik"},{id:4,text:"\u062a\u064e\u0639\u06e1\u0631\u064f\u062c\u064f \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u064f \u0648\u064e\u0671\u0644\u0631\u0651\u064f\u0648\u062d\u064f \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u0641\u0650\u064a \u064a\u064e\u0648\u06e1\u0645\u0656 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0642\u06e1\u062f\u064e\u0627\u0631\u064f\u0647\u064f\u06e5 \u062e\u064e\u0645\u06e1\u0633\u0650\u064a\u0646\u064e \u0623\u064e\u0644\u06e1\u0641\u064e \u0633\u064e\u0646\u064e\u0629\u0656",translation:"Para malaikat dan Jibril naik (menghadap) kepada Tuhan, dalam sehari setara dengan lima puluh ribu tahun"},{id:5,text:"\u0641\u064e\u0671\u0635\u06e1\u0628\u0650\u0631\u06e1 \u0635\u064e\u0628\u06e1\u0631\u0657\u0627 \u062c\u064e\u0645\u0650\u064a\u0644\u064b\u0627",translation:"Maka bersabarlah engkau (Muhammad) dengan kesabaran yang baik"},{id:6,text:"\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0631\u064e\u0648\u06e1\u0646\u064e\u0647\u064f\u06e5 \u0628\u064e\u0639\u0650\u064a\u062f\u0657\u0627",translation:"Mereka memandang (azab) itu jauh (mustahil)"},{id:7,text:"\u0648\u064e\u0646\u064e\u0631\u064e\u0649\u0670\u0647\u064f \u0642\u064e\u0631\u0650\u064a\u0628\u0657\u0627",translation:"Sedang Kami memandangnya dekat (pasti terjadi)"},{id:8,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u062a\u064e\u0643\u064f\u0648\u0646\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u064f \u0643\u064e\u0671\u0644\u06e1\u0645\u064f\u0647\u06e1\u0644\u0650",translation:"(Ingatlah) pada hari ketika langit menjadi bagaikan cairan tembaga"},{id:9,text:"\u0648\u064e\u062a\u064e\u0643\u064f\u0648\u0646\u064f \u0671\u0644\u06e1\u062c\u0650\u0628\u064e\u0627\u0644\u064f \u0643\u064e\u0671\u0644\u06e1\u0639\u0650\u0647\u06e1\u0646\u0650",translation:"dan gunung-gunung bagaikan bulu (yang beterbangan)"},{id:10,text:"\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f \u062d\u064e\u0645\u0650\u064a\u0645\u064c \u062d\u064e\u0645\u0650\u064a\u0645\u0657\u0627",translation:"dan tidak ada seorang teman karib pun menanyakan temannya"},{id:11,text:"\u064a\u064f\u0628\u064e\u0635\u0651\u064e\u0631\u064f\u0648\u0646\u064e\u0647\u064f\u0645\u06e1\u06da \u064a\u064e\u0648\u064e\u062f\u0651\u064f \u0671\u0644\u06e1\u0645\u064f\u062c\u06e1\u0631\u0650\u0645\u064f \u0644\u064e\u0648\u06e1 \u064a\u064e\u0641\u06e1\u062a\u064e\u062f\u0650\u064a \u0645\u0650\u0646\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u064a\u064e\u0648\u06e1\u0645\u0650\u0626\u0650\u0630\u0650\u06ed \u0628\u0650\u0628\u064e\u0646\u0650\u064a\u0647\u0650",translation:"sedang mereka saling melihat. Pada hari itu, orang yang berdosa ingin sekiranya dia dapat menebus (dirinya) dari azab dengan anak-anaknya"},{id:12,text:"\u0648\u064e\u0635\u064e\u0670\u062d\u0650\u0628\u064e\u062a\u0650\u0647\u0650\u06e6 \u0648\u064e\u0623\u064e\u062e\u0650\u064a\u0647\u0650",translation:"dan istrinya juga saudaranya"},{id:13,text:"\u0648\u064e\u0641\u064e\u0635\u0650\u064a\u0644\u064e\u062a\u0650\u0647\u0650 \u0671\u0644\u0651\u064e\u062a\u0650\u064a \u062a\u064f\u0640\u0654\u06e1\u0648\u0650\u064a\u0647\u0650",translation:"dan keluarga yang melindunginya (di dunia)"},{id:14,text:"\u0648\u064e\u0645\u064e\u0646 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u062c\u064e\u0645\u0650\u064a\u0639\u0657\u0627 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0646\u062c\u0650\u064a\u0647\u0650",translation:"dan orang-orang di bumi seluruhnya, kemudian mengharapkan (tebusan) itu dapat menyelamatkannya"},{id:15,text:"\u0643\u064e\u0644\u0651\u064e\u0627\u0653\u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064e\u0627 \u0644\u064e\u0638\u064e\u0649\u0670",translation:"Sama sekali tidak! Sungguh, neraka itu api yang bergejolak"},{id:16,text:"\u0646\u064e\u0632\u0651\u064e\u0627\u0639\u064e\u0629\u0657 \u0644\u0651\u0650\u0644\u0634\u0651\u064e\u0648\u064e\u0649\u0670",translation:"yang mengelupaskan kulit kepala"},{id:17,text:"\u062a\u064e\u062f\u06e1\u0639\u064f\u0648\u0627\u0652 \u0645\u064e\u0646\u06e1 \u0623\u064e\u062f\u06e1\u0628\u064e\u0631\u064e \u0648\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649\u0670",translation:"Yang memanggil orang yang membelakangi dan yang berpaling (dari agama)"},{id:18,text:"\u0648\u064e\u062c\u064e\u0645\u064e\u0639\u064e \u0641\u064e\u0623\u064e\u0648\u06e1\u0639\u064e\u0649\u0670\u0653",translation:"dan orang yang mengumpulkan (harta benda) lalu menyimpannya"},{id:19,text:"\u06de\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064e \u062e\u064f\u0644\u0650\u0642\u064e \u0647\u064e\u0644\u064f\u0648\u0639\u064b\u0627",translation:"Sungguh, manusia diciptakan bersifat suka mengeluh"},{id:20,text:"\u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0633\u0651\u064e\u0647\u064f \u0671\u0644\u0634\u0651\u064e\u0631\u0651\u064f \u062c\u064e\u0632\u064f\u0648\u0639\u0657\u0627",translation:"Apabila dia ditimpa kesusahan dia berkeluh kesah"},{id:21,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0633\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u062e\u064e\u064a\u06e1\u0631\u064f \u0645\u064e\u0646\u064f\u0648\u0639\u064b\u0627",translation:"dan apabila mendapat kebaikan (harta) dia jadi kikir"},{id:22,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u06e1\u0645\u064f\u0635\u064e\u0644\u0651\u0650\u064a\u0646\u064e",translation:"kecuali orang-orang yang melaksanakan salat"},{id:23,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0635\u064e\u0644\u064e\u0627\u062a\u0650\u0647\u0650\u0645\u06e1 \u062f\u064e\u0627\u0653\u0626\u0650\u0645\u064f\u0648\u0646\u064e",translation:"mereka yang tetap setia melaksanakan salatnya"},{id:24,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0653 \u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u0650\u0647\u0650\u0645\u06e1 \u062d\u064e\u0642\u0651\u065e \u0645\u0651\u064e\u0639\u06e1\u0644\u064f\u0648\u0645\u065e",translation:"dan orang-orang yang dalam hartanya disiapkan bagian tertentu"},{id:25,text:"\u0644\u0651\u0650\u0644\u0633\u0651\u064e\u0627\u0653\u0626\u0650\u0644\u0650 \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u062d\u06e1\u0631\u064f\u0648\u0645\u0650",translation:"bagi orang (miskin) yang meminta dan yang tidak meminta"},{id:26,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u064f\u0648\u0646\u064e \u0628\u0650\u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u0650",translation:"dan orang-orang yang mempercayai hari pembalasan"},{id:27,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645 \u0645\u0651\u064f\u0634\u06e1\u0641\u0650\u0642\u064f\u0648\u0646\u064e",translation:"dan orang-orang yang takut terhadap azab Tuhannya"},{id:28,text:"\u0625\u0650\u0646\u0651\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u063a\u064e\u064a\u06e1\u0631\u064f \u0645\u064e\u0623\u06e1\u0645\u064f\u0648\u0646\u0656",translation:"sesungguhnya terhadap azab Tuhan mereka, tidak ada seseorang yang merasa aman (dari kedatangannya)"},{id:29,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645\u06e1 \u0644\u0650\u0641\u064f\u0631\u064f\u0648\u062c\u0650\u0647\u0650\u0645\u06e1 \u062d\u064e\u0670\u0641\u0650\u0638\u064f\u0648\u0646\u064e",translation:"dan orang-orang yang memelihara kemaluannya"},{id:30,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u0650\u0647\u0650\u0645\u06e1 \u0623\u064e\u0648\u06e1 \u0645\u064e\u0627 \u0645\u064e\u0644\u064e\u0643\u064e\u062a\u06e1 \u0623\u064e\u064a\u06e1\u0645\u064e\u0670\u0646\u064f\u0647\u064f\u0645\u06e1 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u063a\u064e\u064a\u06e1\u0631\u064f \u0645\u064e\u0644\u064f\u0648\u0645\u0650\u064a\u0646\u064e",translation:"(kecuali terhadap istri-istri mereka atau hamba sahaya yang mereka miliki865) maka sesungguhnya mereka tidak tercela"},{id:31,text:"\u0641\u064e\u0645\u064e\u0646\u0650 \u0671\u0628\u06e1\u062a\u064e\u063a\u064e\u0649\u0670 \u0648\u064e\u0631\u064e\u0627\u0653\u0621\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0639\u064e\u0627\u062f\u064f\u0648\u0646\u064e",translation:"Maka barangsiapa mencari di luar itu (seperti zina, homoseks, dan lesbian), mereka itulah orang-orang yang melampaui batas"},{id:32,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645\u06e1 \u0644\u0650\u0623\u064e\u0645\u064e\u0670\u0646\u064e\u0670\u062a\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0639\u064e\u0647\u06e1\u062f\u0650\u0647\u0650\u0645\u06e1 \u0631\u064e\u0670\u0639\u064f\u0648\u0646\u064e",translation:"Dan orang-orang yang memelihara amanat dan janjinya"},{id:33,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645 \u0628\u0650\u0634\u064e\u0647\u064e\u0670\u062f\u064e\u0670\u062a\u0650\u0647\u0650\u0645\u06e1 \u0642\u064e\u0627\u0653\u0626\u0650\u0645\u064f\u0648\u0646\u064e",translation:"dan orang-orang yang berpegang teguh pada kesaksiannya"},{id:34,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0635\u064e\u0644\u064e\u0627\u062a\u0650\u0647\u0650\u0645\u06e1 \u064a\u064f\u062d\u064e\u0627\u0641\u0650\u0638\u064f\u0648\u0646\u064e",translation:"dan orang-orang yang memelihara salatnya"},{id:35,text:"\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0641\u0650\u064a \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0656 \u0645\u0651\u064f\u0643\u06e1\u0631\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Mereka itu dimuliakan di dalam surga"},{id:36,text:"\u0641\u064e\u0645\u064e\u0627\u0644\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0642\u0650\u0628\u064e\u0644\u064e\u0643\u064e \u0645\u064f\u0647\u06e1\u0637\u0650\u0639\u0650\u064a\u0646\u064e",translation:"Maka mengapa orang-orang kafir itu datang bergegas ke hadapanmu (Muhammad)"},{id:37,text:"\u0639\u064e\u0646\u0650 \u0671\u0644\u06e1\u064a\u064e\u0645\u0650\u064a\u0646\u0650 \u0648\u064e\u0639\u064e\u0646\u0650 \u0671\u0644\u0634\u0651\u0650\u0645\u064e\u0627\u0644\u0650 \u0639\u0650\u0632\u0650\u064a\u0646\u064e",translation:"dari kanan dan dari kiri dengan berkelompok-kelompok"},{id:38,text:"\u0623\u064e\u064a\u064e\u0637\u06e1\u0645\u064e\u0639\u064f \u0643\u064f\u0644\u0651\u064f \u0671\u0645\u06e1\u0631\u0650\u064a\u0655\u0656 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0623\u064e\u0646 \u064a\u064f\u062f\u06e1\u062e\u064e\u0644\u064e \u062c\u064e\u0646\u0651\u064e\u0629\u064e \u0646\u064e\u0639\u0650\u064a\u0645\u0656",translation:"Apakah setiap orang dari orang-orang kafir itu ingin masuk surga yang penuh kenikmatan"},{id:39,text:"\u0643\u064e\u0644\u0651\u064e\u0627\u0653\u06d6 \u0625\u0650\u0646\u0651\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u06e1\u0646\u064e\u0670\u0647\u064f\u0645 \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"tidak mungkin! Sesungguhnya Kami menciptakan mereka dari apa yang mereka ketahui"},{id:40,text:"\u0641\u064e\u0644\u064e\u0627\u0653 \u0623\u064f\u0642\u06e1\u0633\u0650\u0645\u064f \u0628\u0650\u0631\u064e\u0628\u0651\u0650 \u0671\u0644\u06e1\u0645\u064e\u0634\u064e\u0670\u0631\u0650\u0642\u0650 \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u063a\u064e\u0670\u0631\u0650\u0628\u0650 \u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0642\u064e\u0670\u062f\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Maka Aku bersumpah demi Tuhan yang mengatur tempat-tempat terbit dan terbenamnya (matahari, bulan dan bintang), sungguh, Kami pasti mampu"},{id:41,text:"\u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0646 \u0646\u0651\u064f\u0628\u064e\u062f\u0651\u0650\u0644\u064e \u062e\u064e\u064a\u06e1\u0631\u0657\u0627 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0648\u064e\u0645\u064e\u0627 \u0646\u064e\u062d\u06e1\u0646\u064f \u0628\u0650\u0645\u064e\u0633\u06e1\u0628\u064f\u0648\u0642\u0650\u064a\u0646\u064e",translation:"untuk mengganti (mereka) dengan kaum yang lebih baik dari mereka, dan Kami tidak dapat dikalahkan"},{id:42,text:"\u0641\u064e\u0630\u064e\u0631\u06e1\u0647\u064f\u0645\u06e1 \u064a\u064e\u062e\u064f\u0648\u0636\u064f\u0648\u0627\u0652 \u0648\u064e\u064a\u064e\u0644\u06e1\u0639\u064e\u0628\u064f\u0648\u0627\u0652 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064f\u0644\u064e\u0670\u0642\u064f\u0648\u0627\u0652 \u064a\u064e\u0648\u06e1\u0645\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u0648\u0639\u064e\u062f\u064f\u0648\u0646\u064e",translation:"Maka biarkanlah mereka tenggelam dan bermain-main (dalam kesesatan) sampai mereka menjumpai hari yang diancamkan kepada mereka"},{id:43,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064e\u062e\u06e1\u0631\u064f\u062c\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u062c\u06e1\u062f\u064e\u0627\u062b\u0650 \u0633\u0650\u0631\u064e\u0627\u0639\u0657\u0627 \u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649\u0670 \u0646\u064f\u0635\u064f\u0628\u0656 \u064a\u064f\u0648\u0641\u0650\u0636\u064f\u0648\u0646\u064e",translation:"(yaitu) pada hari ketika mereka keluar dari kubur dengan cepat seakan-akan mereka pergi dengan segera kepada berhala-berhala (sewaktu di dunia)"},{id:44,text:"\u062e\u064e\u0670\u0634\u0650\u0639\u064e\u0629\u064b \u0623\u064e\u0628\u06e1\u0635\u064e\u0670\u0631\u064f\u0647\u064f\u0645\u06e1 \u062a\u064e\u0631\u06e1\u0647\u064e\u0642\u064f\u0647\u064f\u0645\u06e1 \u0630\u0650\u0644\u0651\u064e\u0629\u065e\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064f \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064f\u0648\u0639\u064e\u062f\u064f\u0648\u0646\u064e",translation:"pandangan mereka tertunduk ke bawah diliputi kehinaan. Itulah hari yang diancamkan kepada mereka"}]},{id:71,name:"\u0646\u0648\u062d",transliteration:"Nuh",translation:"Nuh",type:"meccan",total_verses:28,verses:[{id:1,text:"\u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627 \u0646\u064f\u0648\u062d\u064b\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u06e1\u0645\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u0646\u06e1 \u0623\u064e\u0646\u0630\u0650\u0631\u06e1 \u0642\u064e\u0648\u06e1\u0645\u064e\u0643\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u06e1\u0644\u0650 \u0623\u064e\u0646 \u064a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u065e",translation:"Sesungguhnya Kami telah mengutus Nuh kepada kaumnya (dengan perintah), \"Berilah kaummu peringatan sebelum datang kepadanya azab yang pedih"},{id:2,text:"\u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0670\u0642\u064e\u0648\u06e1\u0645\u0650 \u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0643\u064f\u0645\u06e1 \u0646\u064e\u0630\u0650\u064a\u0631\u065e \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u064c",translation:"Dia (Nuh) berkata, \"Wahai kaumku! Sesungguhnya aku ini seorang pemberi peringatan yang menjelaskan kepada kamu"},{id:3,text:"\u0623\u064e\u0646\u0650 \u0671\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0647\u064f \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u0650",translation:"(yaitu) sembahlah Allah, bertakwalah kepada-Nya dan taatlah kepadaku"},{id:4,text:"\u064a\u064e\u063a\u06e1\u0641\u0650\u0631\u06e1 \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0630\u064f\u0646\u064f\u0648\u0628\u0650\u0643\u064f\u0645\u06e1 \u0648\u064e\u064a\u064f\u0624\u064e\u062e\u0651\u0650\u0631\u06e1\u0643\u064f\u0645\u06e1 \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u062c\u064e\u0644\u0656 \u0645\u0651\u064f\u0633\u064e\u0645\u0651\u064b\u0649\u06da \u0625\u0650\u0646\u0651\u064e \u0623\u064e\u062c\u064e\u0644\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e \u0644\u064e\u0627 \u064a\u064f\u0624\u064e\u062e\u0651\u064e\u0631\u064f\u06da \u0644\u064e\u0648\u06e1 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"niscaya Dia mengampuni sebagian dosa-dosamu dan menangguhkan kamu (memanjangkan umurmu) sampai pada batas waktu yang ditentukan. Sungguh, ketetapan Allah itu apabila telah datang tidak dapat ditunda, seandainya kamu mengetahui"},{id:5,text:"\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0625\u0650\u0646\u0651\u0650\u064a \u062f\u064e\u0639\u064e\u0648\u06e1\u062a\u064f \u0642\u064e\u0648\u06e1\u0645\u0650\u064a \u0644\u064e\u064a\u06e1\u0644\u0657\u0627 \u0648\u064e\u0646\u064e\u0647\u064e\u0627\u0631\u0657\u0627",translation:"Dia (Nuh) berkata, \"Ya Tuhanku, sesungguhnya aku telah menyeru kaumku siang dan malam"},{id:6,text:"\u0641\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0632\u0650\u062f\u06e1\u0647\u064f\u0645\u06e1 \u062f\u064f\u0639\u064e\u0627\u0653\u0621\u0650\u064a\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0641\u0650\u0631\u064e\u0627\u0631\u0657\u0627",translation:"tetapi seruanku itu tidak menambah (iman) mereka, justru mereka lari (dari kebenaran)"},{id:7,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u0650\u064a \u0643\u064f\u0644\u0651\u064e\u0645\u064e\u0627 \u062f\u064e\u0639\u064e\u0648\u06e1\u062a\u064f\u0647\u064f\u0645\u06e1 \u0644\u0650\u062a\u064e\u063a\u06e1\u0641\u0650\u0631\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u062c\u064e\u0639\u064e\u0644\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0635\u064e\u0670\u0628\u0650\u0639\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0653 \u0621\u064e\u0627\u0630\u064e\u0627\u0646\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0671\u0633\u06e1\u062a\u064e\u063a\u06e1\u0634\u064e\u0648\u06e1\u0627\u0652 \u062b\u0650\u064a\u064e\u0627\u0628\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0635\u064e\u0631\u0651\u064f\u0648\u0627\u0652 \u0648\u064e\u0671\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u064e\u0631\u064f\u0648\u0627\u0652 \u0671\u0633\u06e1\u062a\u0650\u0643\u06e1\u0628\u064e\u0627\u0631\u0657\u0627",translation:"Dan sesungguhnya aku setiap kali menyeru mereka (untuk beriman) agar Engkau mengampuni mereka, mereka memasukkan anak jarinya ke telinganya dan menutupkan bajunya (ke wajahnya) dan mereka tetap (mengingkari) dan sangat menyombongkan diri"},{id:8,text:"\u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u062f\u064e\u0639\u064e\u0648\u06e1\u062a\u064f\u0647\u064f\u0645\u06e1 \u062c\u0650\u0647\u064e\u0627\u0631\u0657\u0627",translation:"Lalu sesungguhnya aku menyeru mereka dengan cara terang-terangan"},{id:9,text:"\u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u0650\u064a\u0653 \u0623\u064e\u0639\u06e1\u0644\u064e\u0646\u062a\u064f \u0644\u064e\u0647\u064f\u0645\u06e1 \u0648\u064e\u0623\u064e\u0633\u06e1\u0631\u064e\u0631\u06e1\u062a\u064f \u0644\u064e\u0647\u064f\u0645\u06e1 \u0625\u0650\u0633\u06e1\u0631\u064e\u0627\u0631\u0657\u0627",translation:"Kemudian aku menyeru mereka secara terbuka dan dengan diam-diam"},{id:10,text:"\u0641\u064e\u0642\u064f\u0644\u06e1\u062a\u064f \u0671\u0633\u06e1\u062a\u064e\u063a\u06e1\u0641\u0650\u0631\u064f\u0648\u0627\u0652 \u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0643\u064e\u0627\u0646\u064e \u063a\u064e\u0641\u0651\u064e\u0627\u0631\u0657\u0627",translation:"maka aku berkata (kepada mereka), \"Mohonlah ampunan kepada Tuhanmu, Sungguh, Dia Maha Pengampun"},{id:11,text:"\u064a\u064f\u0631\u06e1\u0633\u0650\u0644\u0650 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645 \u0645\u0651\u0650\u062f\u06e1\u0631\u064e\u0627\u0631\u0657\u0627",translation:"niscaya Dia akan menurunkan hujan yang lebat dari langit kepadamu"},{id:12,text:"\u0648\u064e\u064a\u064f\u0645\u06e1\u062f\u0650\u062f\u06e1\u0643\u064f\u0645 \u0628\u0650\u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u0644\u0656 \u0648\u064e\u0628\u064e\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u064a\u064e\u062c\u06e1\u0639\u064e\u0644 \u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0656 \u0648\u064e\u064a\u064e\u062c\u06e1\u0639\u064e\u0644 \u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u0657\u0627",translation:"dan Dia memperbanyak harta dan anak-anakmu, dan mengadakan kebun-kebun untukmu dan mengadakan sungai-sungai untukmu"},{id:13,text:"\u0645\u0651\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u06e1 \u0644\u064e\u0627 \u062a\u064e\u0631\u06e1\u062c\u064f\u0648\u0646\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0642\u064e\u0627\u0631\u0657\u0627",translation:"Mengapa kamu tidak takut akan kebesaran Allah"},{id:14,text:"\u0648\u064e\u0642\u064e\u062f\u06e1 \u062e\u064e\u0644\u064e\u0642\u064e\u0643\u064f\u0645\u06e1 \u0623\u064e\u0637\u06e1\u0648\u064e\u0627\u0631\u064b\u0627",translation:"Dan sungguh, Dia telah menciptakan kamu dalam beberapa fase (kejadian)"},{id:15,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0631\u064e\u0648\u06e1\u0627\u0652 \u0643\u064e\u064a\u06e1\u0641\u064e \u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0633\u064e\u0628\u06e1\u0639\u064e \u0633\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0656 \u0637\u0650\u0628\u064e\u0627\u0642\u0657\u0627",translation:"Tidakkah kamu memperhatikan bagaimana Allah telah menciptakan tujuh langit berlapis-lapis"},{id:16,text:"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0671\u0644\u06e1\u0642\u064e\u0645\u064e\u0631\u064e \u0641\u0650\u064a\u0647\u0650\u0646\u0651\u064e \u0646\u064f\u0648\u0631\u0657\u0627 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0671\u0644\u0634\u0651\u064e\u0645\u06e1\u0633\u064e \u0633\u0650\u0631\u064e\u0627\u062c\u0657\u0627",translation:"Dan di sana Dia menciptakan bulan yang bercahaya dan menjadikan matahari sebagai pelita (yang cemerlang)"},{id:17,text:"\u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0646\u06e2\u0628\u064e\u062a\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0646\u064e\u0628\u064e\u0627\u062a\u0657\u0627",translation:"Dan Allah menumbuhkan kamu dari tanah, tumbuh (berangsur-angsur)"},{id:18,text:"\u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0639\u0650\u064a\u062f\u064f\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u064a\u064f\u062e\u06e1\u0631\u0650\u062c\u064f\u0643\u064f\u0645\u06e1 \u0625\u0650\u062e\u06e1\u0631\u064e\u0627\u062c\u0657\u0627",translation:"kemudian Dia akan mengembalikan kamu ke dalamnya (tanah) dan mengeluarkan kamu (pada hari Kiamat) dengan pasti"},{id:19,text:"\u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0628\u0650\u0633\u064e\u0627\u0637\u0657\u0627",translation:"Dan Allah menjadikan bumi untukmu sebagai hamparan"},{id:20,text:"\u0644\u0651\u0650\u062a\u064e\u0633\u06e1\u0644\u064f\u0643\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0633\u064f\u0628\u064f\u0644\u0657\u0627 \u0641\u0650\u062c\u064e\u0627\u062c\u0657\u0627",translation:"agar kamu dapat pergi kian kemari di jalan-jalan yang luas"},{id:21,text:"\u0642\u064e\u0627\u0644\u064e \u0646\u064f\u0648\u062d\u065e \u0631\u0651\u064e\u0628\u0651\u0650 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0635\u064e\u0648\u06e1\u0646\u0650\u064a \u0648\u064e\u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0627\u0652 \u0645\u064e\u0646 \u0644\u0651\u064e\u0645\u06e1 \u064a\u064e\u0632\u0650\u062f\u06e1\u0647\u064f \u0645\u064e\u0627\u0644\u064f\u0647\u064f\u06e5 \u0648\u064e\u0648\u064e\u0644\u064e\u062f\u064f\u0647\u064f\u06e5\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u062e\u064e\u0633\u064e\u0627\u0631\u0657\u0627",translation:"Nuh berkata, \"Ya Tuhanku, sesungguhnya mereka durhaka kepadaku, dan mereka mengikuti orang-orang yang harta dan anak-anaknya hanya menambah kerugian baginya"},{id:22,text:"\u0648\u064e\u0645\u064e\u0643\u064e\u0631\u064f\u0648\u0627\u0652 \u0645\u064e\u0643\u06e1\u0631\u0657\u0627 \u0643\u064f\u0628\u0651\u064e\u0627\u0631\u0657\u0627",translation:"dan mereka melakukan tipu daya yang sangat besar"},{id:23,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u062a\u064e\u0630\u064e\u0631\u064f\u0646\u0651\u064e \u0621\u064e\u0627\u0644\u0650\u0647\u064e\u062a\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0630\u064e\u0631\u064f\u0646\u0651\u064e \u0648\u064e\u062f\u0651\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u0633\u064f\u0648\u064e\u0627\u0639\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u063a\u064f\u0648\u062b\u064e \u0648\u064e\u064a\u064e\u0639\u064f\u0648\u0642\u064e \u0648\u064e\u0646\u064e\u0633\u06e1\u0631\u0657\u0627",translation:"Dan mereka berkata, \"Jangan sekali-kali kamu meninggalkan (penyembahan) tuhan-tuhan kamu dan jangan pula sekali-kali kamu meninggalkan (penyembahan) Wadd, dan jangan pula Suw\u0101', Yag\u016b\u1e61, Ya'\u016bq dan Nasr"},{id:24,text:"\u0648\u064e\u0642\u064e\u062f\u06e1 \u0623\u064e\u0636\u064e\u0644\u0651\u064f\u0648\u0627\u0652 \u0643\u064e\u062b\u0650\u064a\u0631\u0657\u0627\u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0632\u0650\u062f\u0650 \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0636\u064e\u0644\u064e\u0670\u0644\u0657\u0627",translation:"Dan sungguh, mereka telah menyesatkan orang banyak; dan janganlah Engkau tambahkan bagi orang-orang yang zalim itu selain kesesatan"},{id:25,text:"\u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u062e\u064e\u0637\u0650\u064a\u0653\u0640\u0654\u064e\u0670\u062a\u0650\u0647\u0650\u0645\u06e1 \u0623\u064f\u063a\u06e1\u0631\u0650\u0642\u064f\u0648\u0627\u0652 \u0641\u064e\u0623\u064f\u062f\u06e1\u062e\u0650\u0644\u064f\u0648\u0627\u0652 \u0646\u064e\u0627\u0631\u0657\u0627 \u0641\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u062c\u0650\u062f\u064f\u0648\u0627\u0652 \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0646\u0635\u064e\u0627\u0631\u0657\u0627",translation:"Disebabkan kesalahan-kesalahan mereka, mereka ditenggelamkan lalu dimasukkan ke neraka, maka mereka tidak mendapat penolong selain Allah"},{id:26,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0646\u064f\u0648\u062d\u065e \u0631\u0651\u064e\u0628\u0651\u0650 \u0644\u064e\u0627 \u062a\u064e\u0630\u064e\u0631\u06e1 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u062f\u064e\u064a\u0651\u064e\u0627\u0631\u064b\u0627",translation:"Dan Nuh berkata, \"Ya Tuhanku, janganlah Engkau biarkan seorang pun di antara orang-orang kafir itu tinggal di atas bumi"},{id:27,text:"\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0625\u0650\u0646 \u062a\u064e\u0630\u064e\u0631\u06e1\u0647\u064f\u0645\u06e1 \u064a\u064f\u0636\u0650\u0644\u0651\u064f\u0648\u0627\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u064e\u0643\u064e \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0644\u0650\u062f\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0641\u064e\u0627\u062c\u0650\u0631\u0657\u0627 \u0643\u064e\u0641\u0651\u064e\u0627\u0631\u0657\u0627",translation:"Sesungguhnya jika Engkau biarkan mereka tinggal, niscaya mereka akan menyesatkan hamba-hamba-Mu, dan mereka hanya akan melahirkan anak-anak yang jahat dan tidak tahu bersyukur"},{id:28,text:"\u0631\u0651\u064e\u0628\u0651\u0650 \u0671\u063a\u06e1\u0641\u0650\u0631\u06e1 \u0644\u0650\u064a \u0648\u064e\u0644\u0650\u0648\u064e\u0670\u0644\u0650\u062f\u064e\u064a\u0651\u064e \u0648\u064e\u0644\u0650\u0645\u064e\u0646 \u062f\u064e\u062e\u064e\u0644\u064e \u0628\u064e\u064a\u06e1\u062a\u0650\u064a\u064e \u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0657\u0627 \u0648\u064e\u0644\u0650\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064e\u0670\u062a\u0650\u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0632\u0650\u062f\u0650 \u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u062a\u064e\u0628\u064e\u0627\u0631\u064e\u06e2\u0627",translation:"Ya Tuhanku, ampunilah aku, ibu bapakku, dan siapa pun yang memasuki rumahku dengan beriman dan semua orang yang beriman laki-laki dan perempuan. Dan janganlah Engkau tambahkan bagi orang-orang yang zalim itu selain kehancuran"}]},{id:72,name:"\u0627\u0644\u062c\u0646",transliteration:"Al-Jinn",translation:"Jin",type:"meccan",total_verses:28,verses:[{id:1,text:"\u0642\u064f\u0644\u06e1 \u0623\u064f\u0648\u062d\u0650\u064a\u064e \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0671\u0633\u06e1\u062a\u064e\u0645\u064e\u0639\u064e \u0646\u064e\u0641\u064e\u0631\u065e \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u062c\u0650\u0646\u0651\u0650 \u0641\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e\u0627 \u0633\u064e\u0645\u0650\u0639\u06e1\u0646\u064e\u0627 \u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u064b\u0627 \u0639\u064e\u062c\u064e\u0628\u0657\u0627",translation:"Katakanlah (Muhammad), \"Telah diwahyukan kepadaku bahwa sekumpulan jin telah mendengarkan (bacaan),\" lalu mereka berkata, \"Kami telah mendengarkan bacaan yang menakjubkan (Alquran)"},{id:2,text:"\u064a\u064e\u0647\u06e1\u062f\u0650\u064a\u0653 \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0631\u0651\u064f\u0634\u06e1\u062f\u0650 \u0641\u064e\u0640\u0654\u064e\u0627\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0647\u0650\u06e6\u06d6 \u0648\u064e\u0644\u064e\u0646 \u0646\u0651\u064f\u0634\u06e1\u0631\u0650\u0643\u064e \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627\u0653 \u0623\u064e\u062d\u064e\u062f\u0657\u0627",translation:"(yang) memberi petunjuk kepada jalan yang benar, lalu kami beriman kepadanya. Dan kami sekali-kali tidak akan mempersekutukan sesuatu pun dengan Tuhan kami"},{id:3,text:"\u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u06e5 \u062a\u064e\u0639\u064e\u0670\u0644\u064e\u0649\u0670 \u062c\u064e\u062f\u0651\u064f \u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627 \u0645\u064e\u0627 \u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064e \u0635\u064e\u0670\u062d\u0650\u0628\u064e\u0629\u0657 \u0648\u064e\u0644\u064e\u0627 \u0648\u064e\u0644\u064e\u062f\u0657\u0627",translation:"dan sesungguhnya Mahatinggi keagungan Tuhan kami, Dia tidak beristri dan tidak beranak"},{id:4,text:"\u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u06e5 \u0643\u064e\u0627\u0646\u064e \u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0633\u064e\u0641\u0650\u064a\u0647\u064f\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0634\u064e\u0637\u064e\u0637\u0657\u0627",translation:"Dan sesungguhnya orang yang bodoh di antara kami dahulu selalu mengucapkan (perkataan) yang melampaui batas terhadap Allah"},{id:5,text:"\u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0627 \u0638\u064e\u0646\u064e\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u0644\u0651\u064e\u0646 \u062a\u064e\u0642\u064f\u0648\u0644\u064e \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064f \u0648\u064e\u0671\u0644\u06e1\u062c\u0650\u0646\u0651\u064f \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0643\u064e\u0630\u0650\u0628\u0657\u0627",translation:"dan sesungguhnya kami mengira, bahwa manusia dan jin itu tidak akan mengatakan perkataan yang dusta terhadap Allah"},{id:6,text:"\u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u06e5 \u0643\u064e\u0627\u0646\u064e \u0631\u0650\u062c\u064e\u0627\u0644\u065e \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u0650 \u064a\u064e\u0639\u064f\u0648\u0630\u064f\u0648\u0646\u064e \u0628\u0650\u0631\u0650\u062c\u064e\u0627\u0644\u0656 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u06e1\u062c\u0650\u0646\u0651\u0650 \u0641\u064e\u0632\u064e\u0627\u062f\u064f\u0648\u0647\u064f\u0645\u06e1 \u0631\u064e\u0647\u064e\u0642\u0657\u0627",translation:"(dan sesungguhnya ada beberapa orang laki-laki dari kalangan manusia yang meminta perlindungan873) kepada beberapa laki-laki dari jin, tetapi mereka (jin) menjadikan mereka (manusia) bertambah sesat"},{id:7,text:"\u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0638\u064e\u0646\u0651\u064f\u0648\u0627\u0652 \u0643\u064e\u0645\u064e\u0627 \u0638\u064e\u0646\u064e\u0646\u062a\u064f\u0645\u06e1 \u0623\u064e\u0646 \u0644\u0651\u064e\u0646 \u064a\u064e\u0628\u06e1\u0639\u064e\u062b\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u062d\u064e\u062f\u0657\u0627",translation:"Dan sesungguhnya mereka (jin) mengira seperti kamu (orang musyrik Mekkah) yang juga mengira bahwa Allah tidak akan membangkitkan kembali siapa pun (pada hari Kiamat)"},{id:8,text:"\u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0627 \u0644\u064e\u0645\u064e\u0633\u06e1\u0646\u064e\u0627 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u064e \u0641\u064e\u0648\u064e\u062c\u064e\u062f\u06e1\u0646\u064e\u0670\u0647\u064e\u0627 \u0645\u064f\u0644\u0650\u0626\u064e\u062a\u06e1 \u062d\u064e\u0631\u064e\u0633\u0657\u0627 \u0634\u064e\u062f\u0650\u064a\u062f\u0657\u0627 \u0648\u064e\u0634\u064f\u0647\u064f\u0628\u0657\u0627",translation:"Dan sesungguhnya kami (jin) telah mencoba mengetahui (rahasia) langit, maka kami mendapatinya penuh dengan penjagaan yang kuat dan panah-panah api"},{id:9,text:"\u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0646\u064e\u0642\u06e1\u0639\u064f\u062f\u064f \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0645\u064e\u0642\u064e\u0670\u0639\u0650\u062f\u064e \u0644\u0650\u0644\u0633\u0651\u064e\u0645\u06e1\u0639\u0650\u06d6 \u0641\u064e\u0645\u064e\u0646 \u064a\u064e\u0633\u06e1\u062a\u064e\u0645\u0650\u0639\u0650 \u0671\u0644\u06e1\u0623\u0653\u0646\u064e \u064a\u064e\u062c\u0650\u062f\u06e1 \u0644\u064e\u0647\u064f\u06e5 \u0634\u0650\u0647\u064e\u0627\u0628\u0657\u0627 \u0631\u0651\u064e\u0635\u064e\u062f\u0657\u0627",translation:"dan sesungguhnya kami (jin) dahulu dapat menduduki beberapa tempat di langit itu untuk mencuri dengar (berita-beritanya). Tetapi sekarang874) siapa (mencoba) mencuri dengar (seperti itu) pasti akan menjumpai panah-panah api yang mengintai (untuk membakarnya)"},{id:10,text:"\u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0627 \u0644\u064e\u0627 \u0646\u064e\u062f\u06e1\u0631\u0650\u064a\u0653 \u0623\u064e\u0634\u064e\u0631\u0651\u064c \u0623\u064f\u0631\u0650\u064a\u062f\u064e \u0628\u0650\u0645\u064e\u0646 \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0623\u064e\u0645\u06e1 \u0623\u064e\u0631\u064e\u0627\u062f\u064e \u0628\u0650\u0647\u0650\u0645\u06e1 \u0631\u064e\u0628\u0651\u064f\u0647\u064f\u0645\u06e1 \u0631\u064e\u0634\u064e\u062f\u0657\u0627",translation:"Dan sesungguhnya kami (jin) tidak mengetahui (adanya penjagaan itu) apakah keburukan yang dikehendaki orang yang di bumi ataukah Tuhan mereka menghendaki kebaikan baginya"},{id:11,text:"\u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0627 \u0645\u0650\u0646\u0651\u064e\u0627 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064f\u0648\u0646\u064e \u0648\u064e\u0645\u0650\u0646\u0651\u064e\u0627 \u062f\u064f\u0648\u0646\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e\u06d6 \u0643\u064f\u0646\u0651\u064e\u0627 \u0637\u064e\u0631\u064e\u0627\u0653\u0626\u0650\u0642\u064e \u0642\u0650\u062f\u064e\u062f\u0657\u0627",translation:"Dan sesungguhnya di antara kami (jin) ada yang saleh dan ada (pula) kebalikannya. Kami menempuh jalan yang berbeda-beda"},{id:12,text:"\u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0627 \u0638\u064e\u0646\u064e\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u0644\u0651\u064e\u0646 \u0646\u0651\u064f\u0639\u06e1\u062c\u0650\u0632\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0644\u064e\u0646 \u0646\u0651\u064f\u0639\u06e1\u062c\u0650\u0632\u064e\u0647\u064f\u06e5 \u0647\u064e\u0631\u064e\u0628\u0657\u0627",translation:"Dan sesungguhnya kami (jin) telah menduga, bahwa kami tidak akan mampu melepaskan diri (dari kekuasaan) Allah di bumi dan tidak (pula) dapat lari melepaskan diri (dari)-Nya"},{id:13,text:"\u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0627 \u0644\u064e\u0645\u0651\u064e\u0627 \u0633\u064e\u0645\u0650\u0639\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0647\u064f\u062f\u064e\u0649\u0670\u0653 \u0621\u064e\u0627\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0647\u0650\u06e6\u06d6 \u0641\u064e\u0645\u064e\u0646 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u06e2 \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u0647\u0650\u06e6 \u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u062e\u064e\u0627\u0641\u064f \u0628\u064e\u062e\u06e1\u0633\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u0631\u064e\u0647\u064e\u0642\u0657\u0627",translation:"Dan sesungguhnya ketika kami (jin) mendengar petunjuk (Alquran), kami beriman kepadanya. Maka barangsiapa beriman kepada Tuhan, maka tidak perlu ia takut rugi atau berdosa"},{id:14,text:"\u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0627 \u0645\u0650\u0646\u0651\u064e\u0627 \u0671\u0644\u06e1\u0645\u064f\u0633\u06e1\u0644\u0650\u0645\u064f\u0648\u0646\u064e \u0648\u064e\u0645\u0650\u0646\u0651\u064e\u0627 \u0671\u0644\u06e1\u0642\u064e\u0670\u0633\u0650\u0637\u064f\u0648\u0646\u064e\u06d6 \u0641\u064e\u0645\u064e\u0646\u06e1 \u0623\u064e\u0633\u06e1\u0644\u064e\u0645\u064e \u0641\u064e\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u062a\u064e\u062d\u064e\u0631\u0651\u064e\u0648\u06e1\u0627\u0652 \u0631\u064e\u0634\u064e\u062f\u0657\u0627",translation:"Dan di antara kami ada yang Islam dan ada yang menyimpang dari kebenaran. Siapa yang Islam, maka mereka itu telah memilih jalan yang lurus"},{id:15,text:"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0671\u0644\u06e1\u0642\u064e\u0670\u0633\u0650\u0637\u064f\u0648\u0646\u064e \u0641\u064e\u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0644\u0650\u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u062d\u064e\u0637\u064e\u0628\u0657\u0627",translation:"Dan adapun yang menyimpang dari kebenaran, maka mereka menjadi bahan bakar bagi neraka Jahanam"},{id:16,text:"\u0648\u064e\u0623\u064e\u0644\u0651\u064e\u0648\u0650 \u0671\u0633\u06e1\u062a\u064e\u0642\u064e\u0670\u0645\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0637\u0651\u064e\u0631\u0650\u064a\u0642\u064e\u0629\u0650 \u0644\u064e\u0623\u064e\u0633\u06e1\u0642\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f\u0645 \u0645\u0651\u064e\u0627\u0653\u0621\u064b \u063a\u064e\u062f\u064e\u0642\u0657\u0627",translation:"Dan sekiranya mereka tetap berjalan lurus di atas jalan itu (agama Islam), niscaya Kami akan mencurahkan kepada mereka air yang cukup"},{id:17,text:"\u0644\u0651\u0650\u0646\u064e\u0641\u06e1\u062a\u0650\u0646\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u0650\u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0639\u06e1\u0631\u0650\u0636\u06e1 \u0639\u064e\u0646 \u0630\u0650\u0643\u06e1\u0631\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u06e6 \u064a\u064e\u0633\u06e1\u0644\u064f\u0643\u06e1\u0647\u064f \u0639\u064e\u0630\u064e\u0627\u0628\u0657\u0627 \u0635\u064e\u0639\u064e\u062f\u0657\u0627",translation:"Dengan (cara) itu Kami hendak menguji mereka. Dan barangsiapa berpaling dari peringatan Tuhannya, niscaya akan dimasukkan-Nya ke dalam azab yang sangat berat"},{id:18,text:"\u0648\u064e\u0623\u064e\u0646\u0651\u064e \u0671\u0644\u06e1\u0645\u064e\u0633\u064e\u0670\u062c\u0650\u062f\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062f\u06e1\u0639\u064f\u0648\u0627\u0652 \u0645\u064e\u0639\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u062d\u064e\u062f\u0657\u0627",translation:"Dan sesungguhnya masjid-masjid itu adalah untuk Allah. Maka janganlah kamu menyembah apa pun di dalamnya selain Allah"},{id:19,text:"\u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0645\u0651\u064e\u0627 \u0642\u064e\u0627\u0645\u064e \u0639\u064e\u0628\u06e1\u062f\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u062f\u06e1\u0639\u064f\u0648\u0647\u064f \u0643\u064e\u0627\u062f\u064f\u0648\u0627\u0652 \u064a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0644\u0650\u0628\u064e\u062f\u0657\u0627",translation:"Dan sesungguhnya ketika hamba Allah (Muhammad) berdiri menyembah-Nya (melaksanakan salat), mereka (jin-jin) itu berdesakan mengerumuninya"},{id:20,text:"\u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u062f\u06e1\u0639\u064f\u0648\u0627\u0652 \u0631\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064f\u0634\u06e1\u0631\u0650\u0643\u064f \u0628\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u062d\u064e\u062f\u0657\u0627",translation:"Katakanlah (Muhammad), \"Sesungguhnya aku hanya menyembah Tuhanku dan aku tidak mempersekutukan sesuatu pun dengan-Nya"},{id:21,text:"\u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0627\u0653 \u0623\u064e\u0645\u06e1\u0644\u0650\u0643\u064f \u0644\u064e\u0643\u064f\u0645\u06e1 \u0636\u064e\u0631\u0651\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u0631\u064e\u0634\u064e\u062f\u0657\u0627",translation:"Katakanlah (Muhammad), \"Aku tidak kuasa menolak mudarat maupun mendatangkan kebaikan kepadamu"},{id:22,text:"\u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0646 \u064a\u064f\u062c\u0650\u064a\u0631\u064e\u0646\u0650\u064a \u0645\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u062d\u064e\u062f\u065e \u0648\u064e\u0644\u064e\u0646\u06e1 \u0623\u064e\u062c\u0650\u062f\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u06e6 \u0645\u064f\u0644\u06e1\u062a\u064e\u062d\u064e\u062f\u064b\u0627",translation:"Katakanlah (Muhammad), \"Sesungguhnya tidak ada sesuatu pun yang dapat melindungiku dari (azab) Allah dan aku tidak akan memperoleh tempat berlindung selain dari-Nya"},{id:23,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u064e\u0644\u064e\u0670\u063a\u0657\u0627 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0631\u0650\u0633\u064e\u0670\u0644\u064e\u0670\u062a\u0650\u0647\u0650\u06e6\u06da \u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0639\u06e1\u0635\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f\u06e5 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0644\u064e\u0647\u064f\u06e5 \u0646\u064e\u0627\u0631\u064e \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u062e\u064e\u0670\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627\u0653 \u0623\u064e\u0628\u064e\u062f\u064b\u0627",translation:"(Aku hanya) menyampaikan (peringatan) dari Allah dan risalah-Nya. Dan barangsiapa mendurhakai Allah dan Rasul-Nya maka sesungguhnya dia akan mendapat (azab) neraka Jahanam, mereka kekal di dalamnya selama-lamanya"},{id:24,text:"\u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0625\u0650\u0630\u064e\u0627 \u0631\u064e\u0623\u064e\u0648\u06e1\u0627\u0652 \u0645\u064e\u0627 \u064a\u064f\u0648\u0639\u064e\u062f\u064f\u0648\u0646\u064e \u0641\u064e\u0633\u064e\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0645\u064e\u0646\u06e1 \u0623\u064e\u0636\u06e1\u0639\u064e\u0641\u064f \u0646\u064e\u0627\u0635\u0650\u0631\u0657\u0627 \u0648\u064e\u0623\u064e\u0642\u064e\u0644\u0651\u064f \u0639\u064e\u062f\u064e\u062f\u0657\u0627",translation:"Sehingga apabila mereka melihat (azab) yang diancamkan kepadanya, maka mereka akan mengetahui siapakah yang lebih lemah penolongnya dan lebih sedikit jumlahnya"},{id:25,text:"\u0642\u064f\u0644\u06e1 \u0625\u0650\u0646\u06e1 \u0623\u064e\u062f\u06e1\u0631\u0650\u064a\u0653 \u0623\u064e\u0642\u064e\u0631\u0650\u064a\u0628\u065e \u0645\u0651\u064e\u0627 \u062a\u064f\u0648\u0639\u064e\u062f\u064f\u0648\u0646\u064e \u0623\u064e\u0645\u06e1 \u064a\u064e\u062c\u06e1\u0639\u064e\u0644\u064f \u0644\u064e\u0647\u064f\u06e5 \u0631\u064e\u0628\u0651\u0650\u064a\u0653 \u0623\u064e\u0645\u064e\u062f\u064b\u0627",translation:"Katakanlah (Muhammad), \"Aku tidak mengetahui, apakah azab yang diancamkan kepadamu itu sudah dekat ataukah Tuhanku menetapkan waktunya masih lama"},{id:26,text:"\u0639\u064e\u0670\u0644\u0650\u0645\u064f \u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u0628\u0650 \u0641\u064e\u0644\u064e\u0627 \u064a\u064f\u0638\u06e1\u0647\u0650\u0631\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u063a\u064e\u064a\u06e1\u0628\u0650\u0647\u0650\u06e6\u0653 \u0623\u064e\u062d\u064e\u062f\u064b\u0627",translation:"Dia Mengetahui yang gaib, tetapi Dia tidak memperlihatkan kepada siapa pun tentang yang gaib itu"},{id:27,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u0650 \u0671\u0631\u06e1\u062a\u064e\u0636\u064e\u0649\u0670 \u0645\u0650\u0646 \u0631\u0651\u064e\u0633\u064f\u0648\u0644\u0656 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u064a\u064e\u0633\u06e1\u0644\u064f\u0643\u064f \u0645\u0650\u0646\u06e2 \u0628\u064e\u064a\u06e1\u0646\u0650 \u064a\u064e\u062f\u064e\u064a\u06e1\u0647\u0650 \u0648\u064e\u0645\u0650\u0646\u06e1 \u062e\u064e\u0644\u06e1\u0641\u0650\u0647\u0650\u06e6 \u0631\u064e\u0635\u064e\u062f\u0657\u0627",translation:"Kecuali kepada rasul yang diridai-Nya, maka sesungguhnya Dia mengadakan penjaga-penjaga (malaikat) di depan dan di belakangnya"},{id:28,text:"\u0644\u0651\u0650\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064e \u0623\u064e\u0646 \u0642\u064e\u062f\u06e1 \u0623\u064e\u0628\u06e1\u0644\u064e\u063a\u064f\u0648\u0627\u0652 \u0631\u0650\u0633\u064e\u0670\u0644\u064e\u0670\u062a\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u0648\u064e\u0623\u064e\u062d\u064e\u0627\u0637\u064e \u0628\u0650\u0645\u064e\u0627 \u0644\u064e\u062f\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0648\u064e\u0623\u064e\u062d\u06e1\u0635\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u064e \u0634\u064e\u064a\u06e1\u0621\u064d \u0639\u064e\u062f\u064e\u062f\u064e\u06e2\u0627",translation:"Agar Dia mengetahui, bahwa rasul-rasul itu sungguh, telah menyampaikan risalah Tuhannya, sedang (ilmu-Nya) meliputi apa yang ada pada mereka, dan Dia menghitung segala sesuatu satu persatu"}]},{id:73,name:"\u0627\u0644\u0645\u0632\u0645\u0644",transliteration:"Al-Muzzammil",translation:"Orang yang Berselimut",type:"meccan",total_verses:20,verses:[{id:1,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u06e1\u0645\u064f\u0632\u0651\u064e\u0645\u0651\u0650\u0644\u064f",translation:"Wahai orang yang berselimut (Muhammad)"},{id:2,text:"\u0642\u064f\u0645\u0650 \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u0657\u0627",translation:"bangunlah (untuk salat) pada malam hari, kecuali875) sebagian kecil"},{id:3,text:"\u0646\u0651\u0650\u0635\u06e1\u0641\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u0648\u0650 \u0671\u0646\u0642\u064f\u0635\u06e1 \u0645\u0650\u0646\u06e1\u0647\u064f \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627",translation:"(yaitu) separuhnya atau kurang sedikit dari itu"},{id:4,text:"\u0623\u064e\u0648\u06e1 \u0632\u0650\u062f\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0648\u064e\u0631\u064e\u062a\u0651\u0650\u0644\u0650 \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u064e \u062a\u064e\u0631\u06e1\u062a\u0650\u064a\u0644\u064b\u0627",translation:"atau lebih dari (seperdua) itu, dan bacalah Alquran itu dengan perlahan-lahan"},{id:5,text:"\u0625\u0650\u0646\u0651\u064e\u0627 \u0633\u064e\u0646\u064f\u0644\u06e1\u0642\u0650\u064a \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0642\u064e\u0648\u06e1\u0644\u0657\u0627 \u062b\u064e\u0642\u0650\u064a\u0644\u064b\u0627",translation:"Sesungguhnya Kami akan menurunkan perkataan yang berat kepadamu"},{id:6,text:"\u0625\u0650\u0646\u0651\u064e \u0646\u064e\u0627\u0634\u0650\u0626\u064e\u0629\u064e \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u0650 \u0647\u0650\u064a\u064e \u0623\u064e\u0634\u064e\u062f\u0651\u064f \u0648\u064e\u0637\u06e1\u0640\u0654\u0657\u0627 \u0648\u064e\u0623\u064e\u0642\u06e1\u0648\u064e\u0645\u064f \u0642\u0650\u064a\u0644\u064b\u0627",translation:"Sungguh, bangun malam itu lebih kuat (mengisi jiwa); dan (bacaan di waktu itu) lebih berkesan"},{id:7,text:"\u0625\u0650\u0646\u0651\u064e \u0644\u064e\u0643\u064e \u0641\u0650\u064a \u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u0633\u064e\u0628\u06e1\u062d\u0657\u0627 \u0637\u064e\u0648\u0650\u064a\u0644\u0657\u0627",translation:"Sesungguhnya pada siang hari engkau sangat sibuk dengan urusan-urusan yang panjang"},{id:8,text:"\u0648\u064e\u0671\u0630\u06e1\u0643\u064f\u0631\u0650 \u0671\u0633\u06e1\u0645\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0648\u064e\u062a\u064e\u0628\u064e\u062a\u0651\u064e\u0644\u06e1 \u0625\u0650\u0644\u064e\u064a\u06e1\u0647\u0650 \u062a\u064e\u0628\u06e1\u062a\u0650\u064a\u0644\u0657\u0627",translation:"Dan sebutlah nama Tuhanmu, dan beribadahlah kepada-Nya dengan sepenuh hati"},{id:9,text:"\u0631\u0651\u064e\u0628\u0651\u064f \u0671\u0644\u06e1\u0645\u064e\u0634\u06e1\u0631\u0650\u0642\u0650 \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u063a\u06e1\u0631\u0650\u0628\u0650 \u0644\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u0641\u064e\u0671\u062a\u0651\u064e\u062e\u0650\u0630\u06e1\u0647\u064f \u0648\u064e\u0643\u0650\u064a\u0644\u0657\u0627",translation:"(Dialah) Tuhan timur dan barat, tidak ada tuhan selain Dia, maka jadikanlah Dia sebagai pelindung"},{id:10,text:"\u0648\u064e\u0671\u0635\u06e1\u0628\u0650\u0631\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0648\u064e\u0671\u0647\u06e1\u062c\u064f\u0631\u06e1\u0647\u064f\u0645\u06e1 \u0647\u064e\u062c\u06e1\u0631\u0657\u0627 \u062c\u064e\u0645\u0650\u064a\u0644\u0657\u0627",translation:"Dan bersabarlah (Muhammad) terhadap apa yang mereka katakan dan tinggalkanlah mereka dengan cara yang baik"},{id:11,text:"\u0648\u064e\u0630\u064e\u0631\u06e1\u0646\u0650\u064a \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u0652\u0644\u0650\u064a \u0671\u0644\u0646\u0651\u064e\u0639\u06e1\u0645\u064e\u0629\u0650 \u0648\u064e\u0645\u064e\u0647\u0651\u0650\u0644\u06e1\u0647\u064f\u0645\u06e1 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627",translation:"Dan biarkanlah Aku (yang bertindak) terhadap orang-orang yang mendustakan, yang memiliki segala kenikmatan hidup, dan berilah mereka penangguhan sebentar"},{id:12,text:"\u0625\u0650\u0646\u0651\u064e \u0644\u064e\u062f\u064e\u064a\u06e1\u0646\u064e\u0627\u0653 \u0623\u064e\u0646\u0643\u064e\u0627\u0644\u0657\u0627 \u0648\u064e\u062c\u064e\u062d\u0650\u064a\u0645\u0657\u0627",translation:"Sungguh, di sisi Kami ada belenggu-belenggu (yang berat) dan neraka yang menyala-nyala"},{id:13,text:"\u0648\u064e\u0637\u064e\u0639\u064e\u0627\u0645\u0657\u0627 \u0630\u064e\u0627 \u063a\u064f\u0635\u0651\u064e\u0629\u0656 \u0648\u064e\u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0623\u064e\u0644\u0650\u064a\u0645\u0657\u0627",translation:"dan (ada) makanan yang menyumbat di kerongkongan dan azab yang pedih"},{id:14,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u062a\u064e\u0631\u06e1\u062c\u064f\u0641\u064f \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064f \u0648\u064e\u0671\u0644\u06e1\u062c\u0650\u0628\u064e\u0627\u0644\u064f \u0648\u064e\u0643\u064e\u0627\u0646\u064e\u062a\u0650 \u0671\u0644\u06e1\u062c\u0650\u0628\u064e\u0627\u0644\u064f \u0643\u064e\u062b\u0650\u064a\u0628\u0657\u0627 \u0645\u0651\u064e\u0647\u0650\u064a\u0644\u064b\u0627",translation:"(Ingatlah) pada hari (ketika) bumi dan gunung-gunung berguncang keras, dan menjadilah gunung-gunung itu seperti onggokan pasir yang dicurahkan"},{id:15,text:"\u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0631\u064e\u0633\u064f\u0648\u0644\u0657\u0627 \u0634\u064e\u0670\u0647\u0650\u062f\u064b\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0643\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u0657\u0627",translation:"Sesungguhnya Kami telah mengutus seorang Rasul (Muhammad) kepada kamu, yang menjadi saksi terhadapmu, sebagaimana Kami telah mengutus seorang Rasul kepada Fir'aun"},{id:16,text:"\u0641\u064e\u0639\u064e\u0635\u064e\u0649\u0670 \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064f \u0671\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e \u0641\u064e\u0623\u064e\u062e\u064e\u0630\u06e1\u0646\u064e\u0670\u0647\u064f \u0623\u064e\u062e\u06e1\u0630\u0657\u0627 \u0648\u064e\u0628\u0650\u064a\u0644\u0657\u0627",translation:"Namun Fir'aun mendurhakai Rasul itu, maka Kami siksa dia dengan siksaan yang berat"},{id:17,text:"\u0641\u064e\u0643\u064e\u064a\u06e1\u0641\u064e \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e \u0625\u0650\u0646 \u0643\u064e\u0641\u064e\u0631\u06e1\u062a\u064f\u0645\u06e1 \u064a\u064e\u0648\u06e1\u0645\u0657\u0627 \u064a\u064e\u062c\u06e1\u0639\u064e\u0644\u064f \u0671\u0644\u06e1\u0648\u0650\u0644\u06e1\u062f\u064e\u0670\u0646\u064e \u0634\u0650\u064a\u0628\u064b\u0627",translation:"Lalu bagaimanakah kamu akan dapat menjaga dirimu jika kamu tetap kafir kepada hari yang menjadikan anak-anak beruban"},{id:18,text:"\u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u064f \u0645\u064f\u0646\u0641\u064e\u0637\u0650\u0631\u064f\u06e2 \u0628\u0650\u0647\u0650\u06e6\u06da \u0643\u064e\u0627\u0646\u064e \u0648\u064e\u0639\u06e1\u062f\u064f\u0647\u064f\u06e5 \u0645\u064e\u0641\u06e1\u0639\u064f\u0648\u0644\u064b\u0627",translation:"Langit terbelah pada hari itu. Janji Allah pasti terlaksana"},{id:19,text:"\u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0670\u0630\u0650\u0647\u0650\u06e6 \u062a\u064e\u0630\u06e1\u0643\u0650\u0631\u064e\u0629\u065e\u06d6 \u0641\u064e\u0645\u064e\u0646 \u0634\u064e\u0627\u0653\u0621\u064e \u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u06e6 \u0633\u064e\u0628\u0650\u064a\u0644\u064b\u0627",translation:"Sungguh, ini adalah peringatan. Barangsiapa menghendaki, niscaya dia mengambil jalan (yang lurus) kepada Tuhannya"},{id:20,text:"\u06de\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0623\u064e\u0646\u0651\u064e\u0643\u064e \u062a\u064e\u0642\u064f\u0648\u0645\u064f \u0623\u064e\u062f\u06e1\u0646\u064e\u0649\u0670 \u0645\u0650\u0646 \u062b\u064f\u0644\u064f\u062b\u064e\u064a\u0650 \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u0650 \u0648\u064e\u0646\u0650\u0635\u06e1\u0641\u064e\u0647\u064f\u06e5 \u0648\u064e\u062b\u064f\u0644\u064f\u062b\u064e\u0647\u064f\u06e5 \u0648\u064e\u0637\u064e\u0627\u0653\u0626\u0650\u0641\u064e\u0629\u065e \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0645\u064e\u0639\u064e\u0643\u064e\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u064a\u064f\u0642\u064e\u062f\u0651\u0650\u0631\u064f \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u064e \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e\u06da \u0639\u064e\u0644\u0650\u0645\u064e \u0623\u064e\u0646 \u0644\u0651\u064e\u0646 \u062a\u064f\u062d\u06e1\u0635\u064f\u0648\u0647\u064f \u0641\u064e\u062a\u064e\u0627\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1\u06d6 \u0641\u064e\u0671\u0642\u06e1\u0631\u064e\u0621\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u062a\u064e\u064a\u064e\u0633\u0651\u064e\u0631\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u0650\u06da \u0639\u064e\u0644\u0650\u0645\u064e \u0623\u064e\u0646 \u0633\u064e\u064a\u064e\u0643\u064f\u0648\u0646\u064f \u0645\u0650\u0646\u0643\u064f\u0645 \u0645\u0651\u064e\u0631\u06e1\u0636\u064e\u0649\u0670 \u0648\u064e\u0621\u064e\u0627\u062e\u064e\u0631\u064f\u0648\u0646\u064e \u064a\u064e\u0636\u06e1\u0631\u0650\u0628\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u064a\u064e\u0628\u06e1\u062a\u064e\u063a\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u0641\u064e\u0636\u06e1\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0621\u064e\u0627\u062e\u064e\u0631\u064f\u0648\u0646\u064e \u064a\u064f\u0642\u064e\u0670\u062a\u0650\u0644\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650\u06d6 \u0641\u064e\u0671\u0642\u06e1\u0631\u064e\u0621\u064f\u0648\u0627\u0652 \u0645\u064e\u0627 \u062a\u064e\u064a\u064e\u0633\u0651\u064e\u0631\u064e \u0645\u0650\u0646\u06e1\u0647\u064f\u06da \u0648\u064e\u0623\u064e\u0642\u0650\u064a\u0645\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u0621\u064e\u0627\u062a\u064f\u0648\u0627\u0652 \u0671\u0644\u0632\u0651\u064e\u0643\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u0623\u064e\u0642\u06e1\u0631\u0650\u0636\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0642\u064e\u0631\u06e1\u0636\u064b\u0627 \u062d\u064e\u0633\u064e\u0646\u0657\u0627\u06da \u0648\u064e\u0645\u064e\u0627 \u062a\u064f\u0642\u064e\u062f\u0651\u0650\u0645\u064f\u0648\u0627\u0652 \u0644\u0650\u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u062e\u064e\u064a\u06e1\u0631\u0656 \u062a\u064e\u062c\u0650\u062f\u064f\u0648\u0647\u064f \u0639\u0650\u0646\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0647\u064f\u0648\u064e \u062e\u064e\u064a\u06e1\u0631\u0657\u0627 \u0648\u064e\u0623\u064e\u0639\u06e1\u0638\u064e\u0645\u064e \u0623\u064e\u062c\u06e1\u0631\u0657\u0627\u06da \u0648\u064e\u0671\u0633\u06e1\u062a\u064e\u063a\u06e1\u0641\u0650\u0631\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e\u06d6 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u063a\u064e\u0641\u064f\u0648\u0631\u065e \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f\u06e2",translation:"Sesungguhnya Tuhanmu mengetahui bahwa engkau (Muhammad) berdiri (salat) kurang dari dua pertiga malam, atau seperdua malam atau sepertiganya dan (demikian pula) segolongan dari orang-orang yang bersamamu. Allah menetapkan ukuran malam dan siang. Allah mengetahui bahwa kamu tidak dapat menentukan batas-batas waktu itu, maka Dia memberi keringanan kepadamu, karena itu bacalah apa yang mudah (bagimu) dari Alquran; Dia mengetahui bahwa akan ada di antara kamu orang-orang yang sakit, dan yang lain berjalan di bumi mencari sebagian karunia Allah; dan yang lain berperang di jalan Allah, maka bacalah apa yang mudah (bagimu) dari Alquran dan laksanakanlah salat, tunaikanlah zakat dan berikanlah pinjaman kepada Allah pinjaman yang baik. Kebaikan apa saja yang kamu perbuat untuk dirimu niscaya kamu memperoleh (balasan)nya di sisi Allah sebagai balasan yang paling baik dan yang paling besar pahalanya. Dan mohonlah ampunan kepada Allah; sungguh, Allah Maha Pengampun, Maha Penyayang"}]},{id:74,name:"\u0627\u0644\u0645\u062f\u062b\u0631",transliteration:"Al-Muddaththir",translation:"Orang yang Berkemul",type:"meccan",total_verses:56,verses:[{id:1,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u06e1\u0645\u064f\u062f\u0651\u064e\u062b\u0651\u0650\u0631\u064f",translation:"Wahai orang yang berkemul (berselimut)"},{id:2,text:"\u0642\u064f\u0645\u06e1 \u0641\u064e\u0623\u064e\u0646\u0630\u0650\u0631\u06e1",translation:"bangunlah, lalu berilah peringatan"},{id:3,text:"\u0648\u064e\u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0641\u064e\u0643\u064e\u0628\u0651\u0650\u0631\u06e1",translation:"dan agungkanlah Tuhanmu"},{id:4,text:"\u0648\u064e\u062b\u0650\u064a\u064e\u0627\u0628\u064e\u0643\u064e \u0641\u064e\u0637\u064e\u0647\u0651\u0650\u0631\u06e1",translation:"dan bersihkanlah pakaianmu"},{id:5,text:"\u0648\u064e\u0671\u0644\u0631\u0651\u064f\u062c\u06e1\u0632\u064e \u0641\u064e\u0671\u0647\u06e1\u062c\u064f\u0631\u06e1",translation:"dan tinggalkanlah segala (perbuatan) yang keji"},{id:6,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0645\u06e1\u0646\u064f\u0646 \u062a\u064e\u0633\u06e1\u062a\u064e\u0643\u06e1\u062b\u0650\u0631\u064f",translation:"dan janganlah engkau (Muhammad) memberi (dengan maksud) memperoleh (balasan) yang lebih banyak"},{id:7,text:"\u0648\u064e\u0644\u0650\u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0641\u064e\u0671\u0635\u06e1\u0628\u0650\u0631\u06e1",translation:"Dan karena Tuhanmu, bersabarlah"},{id:8,text:"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0646\u064f\u0642\u0650\u0631\u064e \u0641\u0650\u064a \u0671\u0644\u0646\u0651\u064e\u0627\u0642\u064f\u0648\u0631\u0650",translation:"Maka apabila sangkakala ditiup"},{id:9,text:"\u0641\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u064a\u064e\u0648\u06e1\u0645\u064c \u0639\u064e\u0633\u0650\u064a\u0631\u064c",translation:"maka itulah hari yang serba sulit"},{id:10,text:"\u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u063a\u064e\u064a\u06e1\u0631\u064f \u064a\u064e\u0633\u0650\u064a\u0631\u0656",translation:"bagi orang-orang kafir tidak mudah"},{id:11,text:"\u0630\u064e\u0631\u06e1\u0646\u0650\u064a \u0648\u064e\u0645\u064e\u0646\u06e1 \u062e\u064e\u0644\u064e\u0642\u06e1\u062a\u064f \u0648\u064e\u062d\u0650\u064a\u062f\u0657\u0627",translation:"Biarkanlah Aku (yang bertindak) terhadap orang yang Aku sendiri telah menciptakannya"},{id:12,text:"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u062a\u064f \u0644\u064e\u0647\u064f\u06e5 \u0645\u064e\u0627\u0644\u0657\u0627 \u0645\u0651\u064e\u0645\u06e1\u062f\u064f\u0648\u062f\u0657\u0627",translation:"dan Aku berikan baginya kekayaan yang melimpah"},{id:13,text:"\u0648\u064e\u0628\u064e\u0646\u0650\u064a\u0646\u064e \u0634\u064f\u0647\u064f\u0648\u062f\u0657\u0627",translation:"dan anak-anak yang selalu bersamanya"},{id:14,text:"\u0648\u064e\u0645\u064e\u0647\u0651\u064e\u062f\u062a\u0651\u064f \u0644\u064e\u0647\u064f\u06e5 \u062a\u064e\u0645\u06e1\u0647\u0650\u064a\u062f\u0657\u0627",translation:"dan Aku berikan baginya kelapangan (hidup) seluas-luasnya"},{id:15,text:"\u062b\u064f\u0645\u0651\u064e \u064a\u064e\u0637\u06e1\u0645\u064e\u0639\u064f \u0623\u064e\u0646\u06e1 \u0623\u064e\u0632\u0650\u064a\u062f\u064e",translation:"kemudian dia ingin sekali agar Aku menambahnya"},{id:16,text:"\u0643\u064e\u0644\u0651\u064e\u0627\u0653\u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0623\u0653\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0639\u064e\u0646\u0650\u064a\u062f\u0657\u0627",translation:"Tidak bisa! Sesungguhnya dia telah menentang ayat-ayat Kami (Alquran)"},{id:17,text:"\u0633\u064e\u0623\u064f\u0631\u06e1\u0647\u0650\u0642\u064f\u0647\u064f\u06e5 \u0635\u064e\u0639\u064f\u0648\u062f\u064b\u0627",translation:"Aku akan membebaninya dengan pendakian yang meletihkan"},{id:18,text:"\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0641\u064e\u0643\u0651\u064e\u0631\u064e \u0648\u064e\u0642\u064e\u062f\u0651\u064e\u0631\u064e",translation:"Sesungguhnya dia telah memikirkan dan menetapkan (apa yang ditetapkannya)"},{id:19,text:"\u0641\u064e\u0642\u064f\u062a\u0650\u0644\u064e \u0643\u064e\u064a\u06e1\u0641\u064e \u0642\u064e\u062f\u0651\u064e\u0631\u064e",translation:"maka celakalah dia! Bagaimana dia menetapkan"},{id:20,text:"\u062b\u064f\u0645\u0651\u064e \u0642\u064f\u062a\u0650\u0644\u064e \u0643\u064e\u064a\u06e1\u0641\u064e \u0642\u064e\u062f\u0651\u064e\u0631\u064e",translation:"sekali lagi, celakalah dia! Bagaimana dia menetapkan"},{id:21,text:"\u062b\u064f\u0645\u0651\u064e \u0646\u064e\u0638\u064e\u0631\u064e",translation:"kemudian dia (merenung) memikirkan"},{id:22,text:"\u062b\u064f\u0645\u0651\u064e \u0639\u064e\u0628\u064e\u0633\u064e \u0648\u064e\u0628\u064e\u0633\u064e\u0631\u064e",translation:"lalu berwajah masam dan cemberut"},{id:23,text:"\u062b\u064f\u0645\u0651\u064e \u0623\u064e\u062f\u06e1\u0628\u064e\u0631\u064e \u0648\u064e\u0671\u0633\u06e1\u062a\u064e\u0643\u06e1\u0628\u064e\u0631\u064e",translation:"kemudian berpaling (dari kebenaran) dan menyombongkan diri"},{id:24,text:"\u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u06e1 \u0647\u064e\u0670\u0630\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0633\u0650\u062d\u06e1\u0631\u065e \u064a\u064f\u0624\u06e1\u062b\u064e\u0631\u064f",translation:"lalu dia berkata, \"(Alquran) ini hanyalah sihir yang dipelajari (dari orang-orang dahulu)"},{id:25,text:"\u0625\u0650\u0646\u06e1 \u0647\u064e\u0670\u0630\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0648\u06e1\u0644\u064f \u0671\u0644\u06e1\u0628\u064e\u0634\u064e\u0631\u0650",translation:"Ini hanyalah perkataan manusia"},{id:26,text:"\u0633\u064e\u0623\u064f\u0635\u06e1\u0644\u0650\u064a\u0647\u0650 \u0633\u064e\u0642\u064e\u0631\u064e",translation:"Kelak, Aku akan memasukkannya ke dalam (neraka) Saqar"},{id:27,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u062f\u06e1\u0631\u064e\u0649\u0670\u0643\u064e \u0645\u064e\u0627 \u0633\u064e\u0642\u064e\u0631\u064f",translation:"Dan tahukah kamu apa (neraka) Saqar itu"},{id:28,text:"\u0644\u064e\u0627 \u062a\u064f\u0628\u06e1\u0642\u0650\u064a \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0630\u064e\u0631\u064f",translation:"Ia (Saqar itu) tidak meninggalkan dan tidak membiarkan"},{id:29,text:"\u0644\u064e\u0648\u0651\u064e\u0627\u062d\u064e\u0629\u065e \u0644\u0651\u0650\u0644\u06e1\u0628\u064e\u0634\u064e\u0631\u0650",translation:"yang menghanguskan kulit manusia"},{id:30,text:"\u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627 \u062a\u0650\u0633\u06e1\u0639\u064e\u0629\u064e \u0639\u064e\u0634\u064e\u0631\u064e",translation:"Di atasnya ada sembilan belas (malaikat penjaga)"},{id:31,text:"\u0648\u064e\u0645\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627\u0653 \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u0657\u06d6 \u0648\u064e\u0645\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0639\u0650\u062f\u0651\u064e\u062a\u064e\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u0641\u0650\u062a\u06e1\u0646\u064e\u0629\u0657 \u0644\u0651\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0644\u0650\u064a\u064e\u0633\u06e1\u062a\u064e\u064a\u06e1\u0642\u0650\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0648\u064e\u064a\u064e\u0632\u06e1\u062f\u064e\u0627\u062f\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u064a\u0645\u064e\u0670\u0646\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0631\u06e1\u062a\u064e\u0627\u0628\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0648\u064e\u0644\u0650\u064a\u064e\u0642\u064f\u0648\u0644\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645 \u0645\u0651\u064e\u0631\u064e\u0636\u065e \u0648\u064e\u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u064f\u0648\u0646\u064e \u0645\u064e\u0627\u0630\u064e\u0627\u0653 \u0623\u064e\u0631\u064e\u0627\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0647\u064e\u0670\u0630\u064e\u0627 \u0645\u064e\u062b\u064e\u0644\u0657\u0627\u06da \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064f\u0636\u0650\u0644\u0651\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0648\u064e\u064a\u064e\u0647\u06e1\u062f\u0650\u064a \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u06da \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u062c\u064f\u0646\u064f\u0648\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e\u06da \u0648\u064e\u0645\u064e\u0627 \u0647\u0650\u064a\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0630\u0650\u0643\u06e1\u0631\u064e\u0649\u0670 \u0644\u0650\u0644\u06e1\u0628\u064e\u0634\u064e\u0631\u0650",translation:"Dan yang Kami jadikan penjaga neraka itu hanya dari malaikat; dan Kami menentukan bilangan mereka itu hanya sebagai cobaan bagi orang-orang kafir, agar orang-orang yang diberi kitab menjadi yakin, agar orang yang beriman bertambah imannya, agar orang-orang yang diberi kitab dan orang-orang mukmin itu tidak ragu-ragu; dan agar orang-orang yang di dalam hatinya ada penyakit dan orang-orang kafir (berkata), \"Apakah yang dikehendaki Allah dengan (bilangan) ini sebagai suatu perumpamaan?\" Demikianlah Allah membiarkan sesat orang-orang yang Dia kehendaki dan memberi petunjuk kepada orang-orang yang Dia kehendaki. Dan tidak ada yang mengetahui bala tentara Tuhanmu kecuali Dia sendiri. Dan Saqar itu tidak lain hanyalah peringatan bagi manusia"},{id:32,text:"\u0643\u064e\u0644\u0651\u064e\u0627 \u0648\u064e\u0671\u0644\u06e1\u0642\u064e\u0645\u064e\u0631\u0650",translation:"(Tidak!878) Demi bulan"},{id:33,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u0650 \u0625\u0650\u0630\u06e1 \u0623\u064e\u062f\u06e1\u0628\u064e\u0631\u064e",translation:"dan demi malam ketika telah berlalu"},{id:34,text:"\u0648\u064e\u0671\u0644\u0635\u0651\u064f\u0628\u06e1\u062d\u0650 \u0625\u0650\u0630\u064e\u0627\u0653 \u0623\u064e\u0633\u06e1\u0641\u064e\u0631\u064e",translation:"dan demi subuh apabila mulai terang"},{id:35,text:"\u0625\u0650\u0646\u0651\u064e\u0647\u064e\u0627 \u0644\u064e\u0625\u0650\u062d\u06e1\u062f\u064e\u0649 \u0671\u0644\u06e1\u0643\u064f\u0628\u064e\u0631\u0650",translation:"sesungguhnya (Saqar itu) adalah salah satu (bencana) yang sangat besar"},{id:36,text:"\u0646\u064e\u0630\u0650\u064a\u0631\u0657\u0627 \u0644\u0651\u0650\u0644\u06e1\u0628\u064e\u0634\u064e\u0631\u0650",translation:"sebagai peringatan bagi manusia"},{id:37,text:"\u0644\u0650\u0645\u064e\u0646 \u0634\u064e\u0627\u0653\u0621\u064e \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u0623\u064e\u0646 \u064a\u064e\u062a\u064e\u0642\u064e\u062f\u0651\u064e\u0645\u064e \u0623\u064e\u0648\u06e1 \u064a\u064e\u062a\u064e\u0623\u064e\u062e\u0651\u064e\u0631\u064e",translation:"(yaitu) bagi siapa di antara kamu yang ingin maju atau mundur"},{id:38,text:"\u0643\u064f\u0644\u0651\u064f \u0646\u064e\u0641\u06e1\u0633\u0650\u06ed \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064e\u062a\u06e1 \u0631\u064e\u0647\u0650\u064a\u0646\u064e\u0629\u064c",translation:"Setiap orang bertanggung jawab atas apa yang telah dilakukannya"},{id:39,text:"\u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064e \u0671\u0644\u06e1\u064a\u064e\u0645\u0650\u064a\u0646\u0650",translation:"kecuali golongan kanan"},{id:40,text:"\u0641\u0650\u064a \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u0656 \u064a\u064e\u062a\u064e\u0633\u064e\u0627\u0653\u0621\u064e\u0644\u064f\u0648\u0646\u064e",translation:"berada di dalam surga, mereka saling menanyakan"},{id:41,text:"\u0639\u064e\u0646\u0650 \u0671\u0644\u06e1\u0645\u064f\u062c\u06e1\u0631\u0650\u0645\u0650\u064a\u0646\u064e",translation:"tentang (keadaan) orang-orang yang berdosa"},{id:42,text:"\u0645\u064e\u0627 \u0633\u064e\u0644\u064e\u0643\u064e\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u0633\u064e\u0642\u064e\u0631\u064e",translation:"Apa yang menyebabkan kamu masuk ke dalam (neraka) Saqar"},{id:43,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0644\u064e\u0645\u06e1 \u0646\u064e\u0643\u064f \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0635\u064e\u0644\u0651\u0650\u064a\u0646\u064e",translation:"Mereka menjawab, \"Dahulu kami tidak termasuk orang-orang yang melaksanakan salat"},{id:44,text:"\u0648\u064e\u0644\u064e\u0645\u06e1 \u0646\u064e\u0643\u064f \u0646\u064f\u0637\u06e1\u0639\u0650\u0645\u064f \u0671\u0644\u06e1\u0645\u0650\u0633\u06e1\u0643\u0650\u064a\u0646\u064e",translation:"dan kami (juga) tidak memberi makan orang miskin"},{id:45,text:"\u0648\u064e\u0643\u064f\u0646\u0651\u064e\u0627 \u0646\u064e\u062e\u064f\u0648\u0636\u064f \u0645\u064e\u0639\u064e \u0671\u0644\u06e1\u062e\u064e\u0627\u0653\u0626\u0650\u0636\u0650\u064a\u0646\u064e",translation:"bahkan kami biasa berbincang (untuk tujuan yang batil), bersama orang-orang yang membicarakannya"},{id:46,text:"\u0648\u064e\u0643\u064f\u0646\u0651\u064e\u0627 \u0646\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f \u0628\u0650\u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u0650",translation:"dan kami mendustakan hari pembalasan"},{id:47,text:"\u062d\u064e\u062a\u0651\u064e\u0649\u0670\u0653 \u0623\u064e\u062a\u064e\u0649\u0670\u0646\u064e\u0627 \u0671\u0644\u06e1\u064a\u064e\u0642\u0650\u064a\u0646\u064f",translation:"sampai datang kepada kami kematian"},{id:48,text:"\u0641\u064e\u0645\u064e\u0627 \u062a\u064e\u0646\u0641\u064e\u0639\u064f\u0647\u064f\u0645\u06e1 \u0634\u064e\u0641\u064e\u0670\u0639\u064e\u0629\u064f \u0671\u0644\u0634\u0651\u064e\u0640\u0670\u0641\u0650\u0639\u0650\u064a\u0646\u064e",translation:"Maka tidak berguna lagi bagi mereka syafaat (pertolongan) dari orang-orang yang memberikan syafaat"},{id:49,text:"\u0641\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0646\u0650 \u0671\u0644\u062a\u0651\u064e\u0630\u06e1\u0643\u0650\u0631\u064e\u0629\u0650 \u0645\u064f\u0639\u06e1\u0631\u0650\u0636\u0650\u064a\u0646\u064e",translation:"Lalu mengapa mereka (orang-orang kafir) berpaling dari peringatan (Allah)"},{id:50,text:"\u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u062d\u064f\u0645\u064f\u0631\u065e \u0645\u0651\u064f\u0633\u06e1\u062a\u064e\u0646\u0641\u0650\u0631\u064e\u0629\u065e",translation:"seakan-akan mereka keledai liar yang lari terkejut"},{id:51,text:"\u0641\u064e\u0631\u0651\u064e\u062a\u06e1 \u0645\u0650\u0646 \u0642\u064e\u0633\u06e1\u0648\u064e\u0631\u064e\u0629\u0650\u06ed",translation:"lari dari singa"},{id:52,text:"\u0628\u064e\u0644\u06e1 \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0643\u064f\u0644\u0651\u064f \u0671\u0645\u06e1\u0631\u0650\u064a\u0655\u0656 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0623\u064e\u0646 \u064a\u064f\u0624\u06e1\u062a\u064e\u0649\u0670 \u0635\u064f\u062d\u064f\u0641\u0657\u0627 \u0645\u0651\u064f\u0646\u064e\u0634\u0651\u064e\u0631\u064e\u0629\u0657",translation:"Bahkan setiap orang dari mereka ingin agar diberikan kepadanya lembaran-lembaran (kitab) yang terbuka"},{id:53,text:"\u0643\u064e\u0644\u0651\u064e\u0627\u06d6 \u0628\u064e\u0644 \u0644\u0651\u064e\u0627 \u064a\u064e\u062e\u064e\u0627\u0641\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u064e",translation:"Tidak! Sebenarnya mereka tidak takut kepada akhirat"},{id:54,text:"\u0643\u064e\u0644\u0651\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u062a\u064e\u0630\u06e1\u0643\u0650\u0631\u064e\u0629\u065e",translation:"Tidak! Sesungguhnya (Alquran) itu benar-benar suatu peringatan"},{id:55,text:"\u0641\u064e\u0645\u064e\u0646 \u0634\u064e\u0627\u0653\u0621\u064e \u0630\u064e\u0643\u064e\u0631\u064e\u0647\u064f\u06e5",translation:"Maka barangsiapa menghendaki, tentu dia mengambil pelajaran darinya"},{id:56,text:"\u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0630\u06e1\u0643\u064f\u0631\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06da \u0647\u064f\u0648\u064e \u0623\u064e\u0647\u06e1\u0644\u064f \u0671\u0644\u062a\u0651\u064e\u0642\u06e1\u0648\u064e\u0649\u0670 \u0648\u064e\u0623\u064e\u0647\u06e1\u0644\u064f \u0671\u0644\u06e1\u0645\u064e\u063a\u06e1\u0641\u0650\u0631\u064e\u0629\u0650",translation:"Dan mereka tidak akan mengambil pelajaran darinya (Alquran) kecuali (jika) Allah menghendakinya. Dialah Tuhan yang patut (kita) bertakwa kepada-Nya dan yang berhak memberi ampun"}]},{id:75,name:"\u0627\u0644\u0642\u064a\u0627\u0645\u0629",transliteration:"Al-Qiyamah",translation:"Hari Berbangkit",type:"meccan",total_verses:40,verses:[{id:1,text:"\u0644\u064e\u0627\u0653 \u0623\u064f\u0642\u06e1\u0633\u0650\u0645\u064f \u0628\u0650\u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650",translation:"Aku bersumpah dengan hari Kiamat"},{id:2,text:"\u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064f\u0642\u06e1\u0633\u0650\u0645\u064f \u0628\u0650\u0671\u0644\u0646\u0651\u064e\u0641\u06e1\u0633\u0650 \u0671\u0644\u0644\u0651\u064e\u0648\u0651\u064e\u0627\u0645\u064e\u0629\u0650",translation:"dan aku bersumpah demi jiwa yang selalu menyesali (dirinya sendiri)"},{id:3,text:"\u0623\u064e\u064a\u064e\u062d\u06e1\u0633\u064e\u0628\u064f \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064f \u0623\u064e\u0644\u0651\u064e\u0646 \u0646\u0651\u064e\u062c\u06e1\u0645\u064e\u0639\u064e \u0639\u0650\u0638\u064e\u0627\u0645\u064e\u0647\u064f\u06e5",translation:"Apakah manusia mengira, bahwa Kami tidak akan mengumpulkan (kembali) tulang belulangnya"},{id:4,text:"\u0628\u064e\u0644\u064e\u0649\u0670 \u0642\u064e\u0670\u062f\u0650\u0631\u0650\u064a\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0646 \u0646\u0651\u064f\u0633\u064e\u0648\u0651\u0650\u064a\u064e \u0628\u064e\u0646\u064e\u0627\u0646\u064e\u0647\u064f\u06e5",translation:"(Bahkan) Kami mampu menyusun (kembali) jari jemarinya dengan sempurna"},{id:5,text:"\u0628\u064e\u0644\u06e1 \u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064f \u0644\u0650\u064a\u064e\u0641\u06e1\u062c\u064f\u0631\u064e \u0623\u064e\u0645\u064e\u0627\u0645\u064e\u0647\u064f\u06e5",translation:"Tetapi manusia hendak membuat maksiat terus menerus"},{id:6,text:"\u064a\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f \u0623\u064e\u064a\u0651\u064e\u0627\u0646\u064e \u064a\u064e\u0648\u06e1\u0645\u064f \u0671\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u0645\u064e\u0629\u0650",translation:"Dia bertanya, \"Kapankah hari Kiamat itu"},{id:7,text:"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0628\u064e\u0631\u0650\u0642\u064e \u0671\u0644\u06e1\u0628\u064e\u0635\u064e\u0631\u064f",translation:"Maka apabila mata terbelalak (ketakutan)"},{id:8,text:"\u0648\u064e\u062e\u064e\u0633\u064e\u0641\u064e \u0671\u0644\u06e1\u0642\u064e\u0645\u064e\u0631\u064f",translation:"dan bulan pun telah hilang cahayanya"},{id:9,text:"\u0648\u064e\u062c\u064f\u0645\u0650\u0639\u064e \u0671\u0644\u0634\u0651\u064e\u0645\u06e1\u0633\u064f \u0648\u064e\u0671\u0644\u06e1\u0642\u064e\u0645\u064e\u0631\u064f",translation:"lalu matahari dan bulan dikumpulkan"},{id:10,text:"\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064f \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u064d \u0623\u064e\u064a\u06e1\u0646\u064e \u0671\u0644\u06e1\u0645\u064e\u0641\u064e\u0631\u0651\u064f",translation:"pada hari itu manusia berkata, \"Ke mana tempat pelarian"},{id:11,text:"\u0643\u064e\u0644\u0651\u064e\u0627 \u0644\u064e\u0627 \u0648\u064e\u0632\u064e\u0631\u064e",translation:"Tidak! Tidak ada tempat berlindung"},{id:12,text:"\u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u064d \u0671\u0644\u06e1\u0645\u064f\u0633\u06e1\u062a\u064e\u0642\u064e\u0631\u0651\u064f",translation:"Hanya kepada Tuhanmu tempat kembali pada hari itu"},{id:13,text:"\u064a\u064f\u0646\u064e\u0628\u0651\u064e\u0624\u064f\u0627\u0652 \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064f \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0650\u06ed \u0628\u0650\u0645\u064e\u0627 \u0642\u064e\u062f\u0651\u064e\u0645\u064e \u0648\u064e\u0623\u064e\u062e\u0651\u064e\u0631\u064e",translation:"Pada hari itu diberitakan kepada manusia apa yang telah dikerjakannya dan apa yang dilalaikannya"},{id:14,text:"\u0628\u064e\u0644\u0650 \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0646\u064e\u0641\u06e1\u0633\u0650\u0647\u0650\u06e6 \u0628\u064e\u0635\u0650\u064a\u0631\u064e\u0629\u065e",translation:"Bahkan manusia menjadi saksi atas dirinya sendiri"},{id:15,text:"\u0648\u064e\u0644\u064e\u0648\u06e1 \u0623\u064e\u0644\u06e1\u0642\u064e\u0649\u0670 \u0645\u064e\u0639\u064e\u0627\u0630\u0650\u064a\u0631\u064e\u0647\u064f\u06e5",translation:"dan meskipun dia mengemukakan alasan-alasannya"},{id:16,text:"\u0644\u064e\u0627 \u062a\u064f\u062d\u064e\u0631\u0651\u0650\u0643\u06e1 \u0628\u0650\u0647\u0650\u06e6 \u0644\u0650\u0633\u064e\u0627\u0646\u064e\u0643\u064e \u0644\u0650\u062a\u064e\u0639\u06e1\u062c\u064e\u0644\u064e \u0628\u0650\u0647\u0650\u06e6\u0653",translation:"Jangan engkau (Muhammad) gerakkan lidahmu (untuk membaca Alquran) karena hendak cepat-cepat (menguasai)nya"},{id:17,text:"\u0625\u0650\u0646\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u062c\u064e\u0645\u06e1\u0639\u064e\u0647\u064f\u06e5 \u0648\u064e\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u064e\u0647\u064f\u06e5",translation:"Sesungguhnya Kami yang akan mengumpulkannya (di dadamu) dan membacakannya"},{id:18,text:"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u064e\u0631\u064e\u0623\u06e1\u0646\u064e\u0670\u0647\u064f \u0641\u064e\u0671\u062a\u0651\u064e\u0628\u0650\u0639\u06e1 \u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u064e\u0647\u064f\u06e5",translation:"Apabila Kami telah selesai membacakannya maka ikutilah bacaannya itu"},{id:19,text:"\u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0628\u064e\u064a\u064e\u0627\u0646\u064e\u0647\u064f\u06e5",translation:"Kemudian sesungguhnya Kami yang akan menjelaskannya"},{id:20,text:"\u0643\u064e\u0644\u0651\u064e\u0627 \u0628\u064e\u0644\u06e1 \u062a\u064f\u062d\u0650\u0628\u0651\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0639\u064e\u0627\u062c\u0650\u0644\u064e\u0629\u064e",translation:"Tidak! Bahkan Kamu mencintai kehidupan dunia"},{id:21,text:"\u0648\u064e\u062a\u064e\u0630\u064e\u0631\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u064e",translation:"dan mengabaikan (kehidupan) akhirat"},{id:22,text:"\u0648\u064f\u062c\u064f\u0648\u0647\u065e \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u0646\u0651\u064e\u0627\u0636\u0650\u0631\u064e\u0629\u064c",translation:"Wajah-wajah (orang mukmin) pada hari itu berseri-seri"},{id:23,text:"\u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0647\u064e\u0627 \u0646\u064e\u0627\u0638\u0650\u0631\u064e\u0629\u065e",translation:"Memandang Tuhannya"},{id:24,text:"\u0648\u064e\u0648\u064f\u062c\u064f\u0648\u0647\u065e \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0650\u06ed \u0628\u064e\u0627\u0633\u0650\u0631\u064e\u0629\u065e",translation:"Dan wajah-wajah (orang kafir) pada hari itu muram"},{id:25,text:"\u062a\u064e\u0638\u064f\u0646\u0651\u064f \u0623\u064e\u0646 \u064a\u064f\u0641\u06e1\u0639\u064e\u0644\u064e \u0628\u0650\u0647\u064e\u0627 \u0641\u064e\u0627\u0642\u0650\u0631\u064e\u0629\u065e",translation:"mereka yakin bahwa akan ditimpakan kepadanya malapetaka yang sangat dahsyat"},{id:26,text:"\u0643\u064e\u0644\u0651\u064e\u0627\u0653 \u0625\u0650\u0630\u064e\u0627 \u0628\u064e\u0644\u064e\u063a\u064e\u062a\u0650 \u0671\u0644\u062a\u0651\u064e\u0631\u064e\u0627\u0642\u0650\u064a\u064e",translation:"Tidak! Apabila (nyawa) telah sampai ke kerongkongan"},{id:27,text:"\u0648\u064e\u0642\u0650\u064a\u0644\u064e \u0645\u064e\u0646\u06e1\u06dc \u0631\u064e\u0627\u0642\u0656",translation:"dan dikatakan (kepadanya), \"Siapa yang dapat menyembuhkan"},{id:28,text:"\u0648\u064e\u0638\u064e\u0646\u0651\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u0641\u0650\u0631\u064e\u0627\u0642\u064f",translation:"dan dia yakin bahwa itulah waktu perpisahan (dengan dunia)"},{id:29,text:"\u0648\u064e\u0671\u0644\u06e1\u062a\u064e\u0641\u0651\u064e\u062a\u0650 \u0671\u0644\u0633\u0651\u064e\u0627\u0642\u064f \u0628\u0650\u0671\u0644\u0633\u0651\u064e\u0627\u0642\u0650",translation:"dan bertaut betis (kiri) dengan betis (kanan)"},{id:30,text:"\u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u064d \u0671\u0644\u06e1\u0645\u064e\u0633\u064e\u0627\u0642\u064f",translation:"kepada Tuhanmu lah pada hari itu kamu dihalau"},{id:31,text:"\u0641\u064e\u0644\u064e\u0627 \u0635\u064e\u062f\u0651\u064e\u0642\u064e \u0648\u064e\u0644\u064e\u0627 \u0635\u064e\u0644\u0651\u064e\u0649\u0670",translation:"Karena dia (dahulu) tidak mau membenarkan (Alquran dan Rasul) dan tidak mau melaksanakan salat"},{id:32,text:"\u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0648\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649\u0670",translation:"tetapi justru dia mendustakan (Rasul) dan berpaling (dari kebenaran)"},{id:33,text:"\u062b\u064f\u0645\u0651\u064e \u0630\u064e\u0647\u064e\u0628\u064e \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0647\u06e1\u0644\u0650\u0647\u0650\u06e6 \u064a\u064e\u062a\u064e\u0645\u064e\u0637\u0651\u064e\u0649\u0670\u0653",translation:"kemudian dia pergi kepada keluarganya dengan sombong"},{id:34,text:"\u0623\u064e\u0648\u06e1\u0644\u064e\u0649\u0670 \u0644\u064e\u0643\u064e \u0641\u064e\u0623\u064e\u0648\u06e1\u0644\u064e\u0649\u0670",translation:"Celakalah kamu! Maka celakalah"},{id:35,text:"\u062b\u064f\u0645\u0651\u064e \u0623\u064e\u0648\u06e1\u0644\u064e\u0649\u0670 \u0644\u064e\u0643\u064e \u0641\u064e\u0623\u064e\u0648\u06e1\u0644\u064e\u0649\u0670\u0653",translation:"sekali lagi, celakalah kamu (manusia)! Maka celakalah"},{id:36,text:"\u0623\u064e\u064a\u064e\u062d\u06e1\u0633\u064e\u0628\u064f \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064f \u0623\u064e\u0646 \u064a\u064f\u062a\u06e1\u0631\u064e\u0643\u064e \u0633\u064f\u062f\u064b\u0649",translation:"Apakah manusia mengira, dia akan dibiarkan begitu saja (tanpa pertanggung-jawaban)"},{id:37,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0643\u064f \u0646\u064f\u0637\u06e1\u0641\u064e\u0629\u0657 \u0645\u0651\u0650\u0646 \u0645\u0651\u064e\u0646\u0650\u064a\u0651\u0656 \u064a\u064f\u0645\u06e1\u0646\u064e\u0649\u0670",translation:"Bukankah dia mulanya hanya setetes mani yang ditumpahkan (ke dalam rahim)"},{id:38,text:"\u062b\u064f\u0645\u0651\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u064e\u0642\u064e\u0629\u0657 \u0641\u064e\u062e\u064e\u0644\u064e\u0642\u064e \u0641\u064e\u0633\u064e\u0648\u0651\u064e\u0649\u0670",translation:"kemudian (mani itu) menjadi sesuatu yang melekat, lalu Allah menciptakannya dan menyempurnakannya"},{id:39,text:"\u0641\u064e\u062c\u064e\u0639\u064e\u0644\u064e \u0645\u0650\u0646\u06e1\u0647\u064f \u0671\u0644\u0632\u0651\u064e\u0648\u06e1\u062c\u064e\u064a\u06e1\u0646\u0650 \u0671\u0644\u0630\u0651\u064e\u0643\u064e\u0631\u064e \u0648\u064e\u0671\u0644\u06e1\u0623\u064f\u0646\u062b\u064e\u0649\u0670\u0653",translation:"lalu Dia menjadikan darinya sepasang laki-laki dan perempuan"},{id:40,text:"\u0623\u064e\u0644\u064e\u064a\u06e1\u0633\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u0650\u0642\u064e\u0670\u062f\u0650\u0631\u064d \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0646 \u064a\u064f\u062d\u06e1\u0640\u06e7\u0650\u064a\u064e \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u062a\u064e\u0649\u0670",translation:"Bukankah (Allah yang berbuat) demikian berkuasa (pula) menghidupkan orang mati"}]},{id:76,name:"\u0627\u0644\u0627\u0646\u0633\u0627\u0646",transliteration:"Al-Insan",translation:"Manusia",type:"medinan",total_verses:31,verses:[{id:1,text:"\u0647\u064e\u0644\u06e1 \u0623\u064e\u062a\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u0650 \u062d\u0650\u064a\u0646\u065e \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u062f\u0651\u064e\u0647\u06e1\u0631\u0650 \u0644\u064e\u0645\u06e1 \u064a\u064e\u0643\u064f\u0646 \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627 \u0645\u0651\u064e\u0630\u06e1\u0643\u064f\u0648\u0631\u064b\u0627",translation:"Bukankah pernah datang kepada manusia waktu dari masa, yang ketika itu belum merupakan sesuatu yang dapat disebut"},{id:2,text:"\u0625\u0650\u0646\u0651\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064e \u0645\u0650\u0646 \u0646\u0651\u064f\u0637\u06e1\u0641\u064e\u0629\u064d \u0623\u064e\u0645\u06e1\u0634\u064e\u0627\u062c\u0656 \u0646\u0651\u064e\u0628\u06e1\u062a\u064e\u0644\u0650\u064a\u0647\u0650 \u0641\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f \u0633\u064e\u0645\u0650\u064a\u0639\u064e\u06e2\u0627 \u0628\u064e\u0635\u0650\u064a\u0631\u064b\u0627",translation:"(Sungguh, Kami telah menciptakan manusia dari setetes mani yang bercampur882) yang Kami hendak mengujinya (dengan perintah dan larangan), karena itu Kami jadikan dia mendengar dan melihat"},{id:3,text:"\u0625\u0650\u0646\u0651\u064e\u0627 \u0647\u064e\u062f\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f \u0671\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u064e \u0625\u0650\u0645\u0651\u064e\u0627 \u0634\u064e\u0627\u0643\u0650\u0631\u0657\u0627 \u0648\u064e\u0625\u0650\u0645\u0651\u064e\u0627 \u0643\u064e\u0641\u064f\u0648\u0631\u064b\u0627",translation:"Sungguh, Kami telah menunjukkan kepadanya jalan yang lurus; ada yang bersyukur dan ada pula yang kufur"},{id:4,text:"\u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u0639\u06e1\u062a\u064e\u062f\u06e1\u0646\u064e\u0627 \u0644\u0650\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0633\u064e\u0644\u064e\u0670\u0633\u0650\u0644\u064e\u0627\u0652 \u0648\u064e\u0623\u064e\u063a\u06e1\u0644\u064e\u0670\u0644\u0657\u0627 \u0648\u064e\u0633\u064e\u0639\u0650\u064a\u0631\u064b\u0627",translation:"Sungguh, Kami telah menyediakan bagi orang-orang kafir rantai, belenggu dan neraka yang menyala-nyala"},{id:5,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0623\u064e\u0628\u06e1\u0631\u064e\u0627\u0631\u064e \u064a\u064e\u0634\u06e1\u0631\u064e\u0628\u064f\u0648\u0646\u064e \u0645\u0650\u0646 \u0643\u064e\u0623\u06e1\u0633\u0656 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0632\u064e\u0627\u062c\u064f\u0647\u064e\u0627 \u0643\u064e\u0627\u0641\u064f\u0648\u0631\u064b\u0627",translation:"Sungguh, orang-orang yang berbuat kebajikan akan minum dari gelas (berisi minuman) yang campurannya adalah air kafur"},{id:6,text:"\u0639\u064e\u064a\u06e1\u0646\u0657\u0627 \u064a\u064e\u0634\u06e1\u0631\u064e\u0628\u064f \u0628\u0650\u0647\u064e\u0627 \u0639\u0650\u0628\u064e\u0627\u062f\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064f\u0641\u064e\u062c\u0651\u0650\u0631\u064f\u0648\u0646\u064e\u0647\u064e\u0627 \u062a\u064e\u0641\u06e1\u062c\u0650\u064a\u0631\u0657\u0627",translation:"(yaitu) mata air (dalam surga) yang di minum oleh hamba-hamba Allah dan mereka dapat memancarkannya dengan sebaik-baiknya"},{id:7,text:"\u064a\u064f\u0648\u0641\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u0646\u0651\u064e\u0630\u06e1\u0631\u0650 \u0648\u064e\u064a\u064e\u062e\u064e\u0627\u0641\u064f\u0648\u0646\u064e \u064a\u064e\u0648\u06e1\u0645\u0657\u0627 \u0643\u064e\u0627\u0646\u064e \u0634\u064e\u0631\u0651\u064f\u0647\u064f\u06e5 \u0645\u064f\u0633\u06e1\u062a\u064e\u0637\u0650\u064a\u0631\u0657\u0627",translation:"(Mereka memenuhi nazar884) dan takut akan suatu hari yang azabnya merata di mana-mana"},{id:8,text:"\u0648\u064e\u064a\u064f\u0637\u06e1\u0639\u0650\u0645\u064f\u0648\u0646\u064e \u0671\u0644\u0637\u0651\u064e\u0639\u064e\u0627\u0645\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u062d\u064f\u0628\u0651\u0650\u0647\u0650\u06e6 \u0645\u0650\u0633\u06e1\u0643\u0650\u064a\u0646\u0657\u0627 \u0648\u064e\u064a\u064e\u062a\u0650\u064a\u0645\u0657\u0627 \u0648\u064e\u0623\u064e\u0633\u0650\u064a\u0631\u064b\u0627",translation:"Dan mereka memberikan makanan yang disukainya kepada orang miskin, anak yatim dan orang yang ditawan"},{id:9,text:"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0646\u064f\u0637\u06e1\u0639\u0650\u0645\u064f\u0643\u064f\u0645\u06e1 \u0644\u0650\u0648\u064e\u062c\u06e1\u0647\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u064e\u0627 \u0646\u064f\u0631\u0650\u064a\u062f\u064f \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u062c\u064e\u0632\u064e\u0627\u0653\u0621\u0657 \u0648\u064e\u0644\u064e\u0627 \u0634\u064f\u0643\u064f\u0648\u0631\u064b\u0627",translation:"(sambil berkata), \"Sesungguhnya kami memberi makanan kepadamu hanyalah karena mengharapkan keridaan Allah, kami tidak mengharap balasan dan terima kasih dari kamu"},{id:10,text:"\u0625\u0650\u0646\u0651\u064e\u0627 \u0646\u064e\u062e\u064e\u0627\u0641\u064f \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0646\u064e\u0627 \u064a\u064e\u0648\u06e1\u0645\u064b\u0627 \u0639\u064e\u0628\u064f\u0648\u0633\u0657\u0627 \u0642\u064e\u0645\u06e1\u0637\u064e\u0631\u0650\u064a\u0631\u0657\u0627",translation:"Sungguh, kami takut akan (azab) Tuhan pada hari (ketika) orang-orang berwajah masam penuh kesulitan"},{id:11,text:"\u0641\u064e\u0648\u064e\u0642\u064e\u0649\u0670\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0634\u064e\u0631\u0651\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u0650 \u0648\u064e\u0644\u064e\u0642\u0651\u064e\u0649\u0670\u0647\u064f\u0645\u06e1 \u0646\u064e\u0636\u06e1\u0631\u064e\u0629\u0657 \u0648\u064e\u0633\u064f\u0631\u064f\u0648\u0631\u0657\u0627",translation:"Maka Allah melindungi mereka dari kesusahan hari itu, dan memberikan kepada mereka keceriaan dan kegembiraan"},{id:12,text:"\u0648\u064e\u062c\u064e\u0632\u064e\u0649\u0670\u0647\u064f\u0645 \u0628\u0650\u0645\u064e\u0627 \u0635\u064e\u0628\u064e\u0631\u064f\u0648\u0627\u0652 \u062c\u064e\u0646\u0651\u064e\u0629\u0657 \u0648\u064e\u062d\u064e\u0631\u0650\u064a\u0631\u0657\u0627",translation:"Dan Dia memberi balasan kepada mereka karena kesabarannya (berupa) surga dan (pakaian) sutera"},{id:13,text:"\u0645\u0651\u064f\u062a\u0651\u064e\u0643\u0650\u0640\u0654\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0623\u064e\u0631\u064e\u0627\u0653\u0626\u0650\u0643\u0650\u06d6 \u0644\u064e\u0627 \u064a\u064e\u0631\u064e\u0648\u06e1\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0634\u064e\u0645\u06e1\u0633\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u0632\u064e\u0645\u06e1\u0647\u064e\u0631\u0650\u064a\u0631\u0657\u0627",translation:"di sana mereka duduk bersandar di atas dipan, di sana mereka tidak melihat (merasakan teriknya) matahari dan tidak pula dingin yang berlebihan"},{id:14,text:"\u0648\u064e\u062f\u064e\u0627\u0646\u0650\u064a\u064e\u0629\u064b \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0638\u0650\u0644\u064e\u0670\u0644\u064f\u0647\u064e\u0627 \u0648\u064e\u0630\u064f\u0644\u0651\u0650\u0644\u064e\u062a\u06e1 \u0642\u064f\u0637\u064f\u0648\u0641\u064f\u0647\u064e\u0627 \u062a\u064e\u0630\u06e1\u0644\u0650\u064a\u0644\u0657\u0627",translation:"Dan naungan (pepohonan)nya dekat di atas mereka dan dimudahkan semudah-mudahnya untuk memetik (buah)nya"},{id:15,text:"\u0648\u064e\u064a\u064f\u0637\u064e\u0627\u0641\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0628\u0650\u0640\u0654\u064e\u0627\u0646\u0650\u064a\u064e\u0629\u0656 \u0645\u0651\u0650\u0646 \u0641\u0650\u0636\u0651\u064e\u0629\u0656 \u0648\u064e\u0623\u064e\u0643\u06e1\u0648\u064e\u0627\u0628\u0656 \u0643\u064e\u0627\u0646\u064e\u062a\u06e1 \u0642\u064e\u0648\u064e\u0627\u0631\u0650\u064a\u0631\u064e\u0627\u06e0",translation:"Dan kepada mereka diedarkan bejana-bejana dari perak dan piala-piala yang bening laksana kristal"},{id:16,text:"\u0642\u064e\u0648\u064e\u0627\u0631\u0650\u064a\u0631\u064e\u0627\u0652 \u0645\u0650\u0646 \u0641\u0650\u0636\u0651\u064e\u0629\u0656 \u0642\u064e\u062f\u0651\u064e\u0631\u064f\u0648\u0647\u064e\u0627 \u062a\u064e\u0642\u06e1\u062f\u0650\u064a\u0631\u0657\u0627",translation:"kristal yang jernih terbuat dari perak, mereka tentukan ukurannya yang sesuai (dengan kehendak mereka)"},{id:17,text:"\u0648\u064e\u064a\u064f\u0633\u06e1\u0642\u064e\u0648\u06e1\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0643\u064e\u0623\u06e1\u0633\u0657\u0627 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0632\u064e\u0627\u062c\u064f\u0647\u064e\u0627 \u0632\u064e\u0646\u062c\u064e\u0628\u0650\u064a\u0644\u064b\u0627",translation:"Dan di sana mereka diberi segelas minuman bercampur jahe"},{id:18,text:"\u0639\u064e\u064a\u06e1\u0646\u0657\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u062a\u064f\u0633\u064e\u0645\u0651\u064e\u0649\u0670 \u0633\u064e\u0644\u06e1\u0633\u064e\u0628\u0650\u064a\u0644\u0657\u0627",translation:"(Yang didatangkan dari) suatu mata air (di surga) yang dinamakan Salsab\u012bl"},{id:19,text:"\u06de\u0648\u064e\u064a\u064e\u0637\u064f\u0648\u0641\u064f \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0648\u0650\u0644\u06e1\u062f\u064e\u0670\u0646\u065e \u0645\u0651\u064f\u062e\u064e\u0644\u0651\u064e\u062f\u064f\u0648\u0646\u064e \u0625\u0650\u0630\u064e\u0627 \u0631\u064e\u0623\u064e\u064a\u06e1\u062a\u064e\u0647\u064f\u0645\u06e1 \u062d\u064e\u0633\u0650\u0628\u06e1\u062a\u064e\u0647\u064f\u0645\u06e1 \u0644\u064f\u0624\u06e1\u0644\u064f\u0624\u0657\u0627 \u0645\u0651\u064e\u0646\u062b\u064f\u0648\u0631\u0657\u0627",translation:"Dan mereka dikelilingi oleh para pemuda-pemuda yang tetap muda. Apabila kamu melihatnya, akan kamu kira mereka, mutiara yang bertaburan"},{id:20,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0631\u064e\u0623\u064e\u064a\u06e1\u062a\u064e \u062b\u064e\u0645\u0651\u064e \u0631\u064e\u0623\u064e\u064a\u06e1\u062a\u064e \u0646\u064e\u0639\u0650\u064a\u0645\u0657\u0627 \u0648\u064e\u0645\u064f\u0644\u06e1\u0643\u0657\u0627 \u0643\u064e\u0628\u0650\u064a\u0631\u064b\u0627",translation:"Dan apabila engkau melihat (keadaan) di sana (surga), niscaya engkau akan melihat berbagai macam kenikmatan dan kerajaan yang besar"},{id:21,text:"\u0639\u064e\u0670\u0644\u0650\u064a\u064e\u0647\u064f\u0645\u06e1 \u062b\u0650\u064a\u064e\u0627\u0628\u064f \u0633\u064f\u0646\u062f\u064f\u0633\u064d \u062e\u064f\u0636\u06e1\u0631\u065e \u0648\u064e\u0625\u0650\u0633\u06e1\u062a\u064e\u0628\u06e1\u0631\u064e\u0642\u065e\u06d6 \u0648\u064e\u062d\u064f\u0644\u0651\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0633\u064e\u0627\u0648\u0650\u0631\u064e \u0645\u0650\u0646 \u0641\u0650\u0636\u0651\u064e\u0629\u0656 \u0648\u064e\u0633\u064e\u0642\u064e\u0649\u0670\u0647\u064f\u0645\u06e1 \u0631\u064e\u0628\u0651\u064f\u0647\u064f\u0645\u06e1 \u0634\u064e\u0631\u064e\u0627\u0628\u0657\u0627 \u0637\u064e\u0647\u064f\u0648\u0631\u064b\u0627",translation:"Mereka berpakaian sutera halus yang hijau dan sutera tebal dan memakai gelang terbuat dari perak, dan Tuhan memberikan kepada mereka minuman yang bersih (dan suci)"},{id:22,text:"\u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u06e1 \u062c\u064e\u0632\u064e\u0627\u0653\u0621\u0657 \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0633\u064e\u0639\u06e1\u064a\u064f\u0643\u064f\u0645 \u0645\u0651\u064e\u0634\u06e1\u0643\u064f\u0648\u0631\u064b\u0627",translation:"Inilah balasan untukmu, dan segala usahamu diterima dan diakui (Allah)"},{id:23,text:"\u0625\u0650\u0646\u0651\u064e\u0627 \u0646\u064e\u062d\u06e1\u0646\u064f \u0646\u064e\u0632\u0651\u064e\u0644\u06e1\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u064e \u062a\u064e\u0646\u0632\u0650\u064a\u0644\u0657\u0627",translation:"Sesungguhnya Kamilah yang menurunkan Alquran kepadamu (Muhammad) secara berangsur-angsur"},{id:24,text:"\u0641\u064e\u0671\u0635\u06e1\u0628\u0650\u0631\u06e1 \u0644\u0650\u062d\u064f\u0643\u06e1\u0645\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0637\u0650\u0639\u06e1 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0621\u064e\u0627\u062b\u0650\u0645\u064b\u0627 \u0623\u064e\u0648\u06e1 \u0643\u064e\u0641\u064f\u0648\u0631\u0657\u0627",translation:"Maka bersabarlah untuk (melaksanakan) ketetapan Tuhanmu, dan janganlah engkau ikuti orang yang berdosa dan orang yang kafir di antara mereka"},{id:25,text:"\u0648\u064e\u0671\u0630\u06e1\u0643\u064f\u0631\u0650 \u0671\u0633\u06e1\u0645\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0628\u064f\u0643\u06e1\u0631\u064e\u0629\u0657 \u0648\u064e\u0623\u064e\u0635\u0650\u064a\u0644\u0657\u0627",translation:"Dan sebutlah nama Tuhanmu pada (waktu) pagi dan petang"},{id:26,text:"\u0648\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u0650 \u0641\u064e\u0671\u0633\u06e1\u062c\u064f\u062f\u06e1 \u0644\u064e\u0647\u064f\u06e5 \u0648\u064e\u0633\u064e\u0628\u0651\u0650\u062d\u06e1\u0647\u064f \u0644\u064e\u064a\u06e1\u0644\u0657\u0627 \u0637\u064e\u0648\u0650\u064a\u0644\u064b\u0627",translation:"Dan pada sebagian dari malam, maka bersujudlah kepada-Nya dan bertasbihlah kepada-Nya pada bagian yang panjang di malam hari"},{id:27,text:"\u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650 \u064a\u064f\u062d\u0650\u0628\u0651\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0639\u064e\u0627\u062c\u0650\u0644\u064e\u0629\u064e \u0648\u064e\u064a\u064e\u0630\u064e\u0631\u064f\u0648\u0646\u064e \u0648\u064e\u0631\u064e\u0627\u0653\u0621\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0648\u06e1\u0645\u0657\u0627 \u062b\u064e\u0642\u0650\u064a\u0644\u0657\u0627",translation:"Sesungguhnya mereka (orang kafir) itu mencintai kehidupan (dunia) dan meningggalkan hari yang berat (hari akhirat) di belakangnya"},{id:28,text:"\u0646\u0651\u064e\u062d\u06e1\u0646\u064f \u062e\u064e\u0644\u064e\u0642\u06e1\u0646\u064e\u0670\u0647\u064f\u0645\u06e1 \u0648\u064e\u0634\u064e\u062f\u064e\u062f\u06e1\u0646\u064e\u0627\u0653 \u0623\u064e\u0633\u06e1\u0631\u064e\u0647\u064f\u0645\u06e1\u06d6 \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0634\u0650\u0626\u06e1\u0646\u064e\u0627 \u0628\u064e\u062f\u0651\u064e\u0644\u06e1\u0646\u064e\u0627\u0653 \u0623\u064e\u0645\u06e1\u062b\u064e\u0670\u0644\u064e\u0647\u064f\u0645\u06e1 \u062a\u064e\u0628\u06e1\u062f\u0650\u064a\u0644\u064b\u0627",translation:"Kami telah menciptakan mereka dan menguatkan persendian tubuh mereka. Tetapi, jika Kami menghendaki, Kami dapat mengganti dengan yang serupa mereka"},{id:29,text:"\u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0670\u0630\u0650\u0647\u0650\u06e6 \u062a\u064e\u0630\u06e1\u0643\u0650\u0631\u064e\u0629\u065e\u06d6 \u0641\u064e\u0645\u064e\u0646 \u0634\u064e\u0627\u0653\u0621\u064e \u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u06e6 \u0633\u064e\u0628\u0650\u064a\u0644\u0657\u0627",translation:"Sungguh, (ayat-ayat) ini adalah peringatan, maka barang siapa menghendaki (kebaikan bagi dirinya) tentu dia mengambil jalan menuju kepada Tuhannya"},{id:30,text:"\u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06da \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u0650\u064a\u0645\u064b\u0627 \u062d\u064e\u0643\u0650\u064a\u0645\u0657\u0627",translation:"Tetapi kamu tidak mampu (menempuh jalan itu), kecuali apabila dikehendaki Allah. Sungguh, Allah Maha Mengetahui, Mahabijaksana"},{id:31,text:"\u064a\u064f\u062f\u06e1\u062e\u0650\u0644\u064f \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064f \u0641\u0650\u064a \u0631\u064e\u062d\u06e1\u0645\u064e\u062a\u0650\u0647\u0650\u06e6\u06da \u0648\u064e\u0671\u0644\u0638\u0651\u064e\u0640\u0670\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0623\u064e\u0639\u064e\u062f\u0651\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627 \u0623\u064e\u0644\u0650\u064a\u0645\u064e\u06e2\u0627",translation:"Dia memasukkan siapa pun yang Dia kehendaki ke dalam rahmat-Nya (surga). Adapun bagi orang-orang zalim disediakan-Nya azab yang pedih"}]},{id:77,name:"\u0627\u0644\u0645\u0631\u0633\u0644\u0627\u062a",transliteration:"Al-Mursalat",translation:"Malaikat-malaikan yang Diutus",type:"meccan",total_verses:50,verses:[{id:1,text:"\u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0631\u06e1\u0633\u064e\u0644\u064e\u0670\u062a\u0650 \u0639\u064f\u0631\u06e1\u0641\u0657\u0627",translation:"Demi (malaikat-malaikat)885) yang diutus untuk membawa kebaikan"},{id:2,text:"\u0641\u064e\u0671\u0644\u06e1\u0639\u064e\u0670\u0635\u0650\u0641\u064e\u0670\u062a\u0650 \u0639\u064e\u0635\u06e1\u0641\u0657\u0627",translation:"dan (malaikat-malaikat) yang terbang dengan kencangnya"},{id:3,text:"\u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0640\u0670\u0634\u0650\u0631\u064e\u0670\u062a\u0650 \u0646\u064e\u0634\u06e1\u0631\u0657\u0627",translation:"dan (malaikat-malaikat) yang menyebarkan (rahmat Allah) dengan seluas-luasnya"},{id:4,text:"\u0641\u064e\u0671\u0644\u06e1\u0641\u064e\u0670\u0631\u0650\u0642\u064e\u0670\u062a\u0650 \u0641\u064e\u0631\u06e1\u0642\u0657\u0627",translation:"dan (malaikat-malaikat) yang membedakan (antara yang baik dan yang buruk) dengan sejelas-jelasnya"},{id:5,text:"\u0641\u064e\u0671\u0644\u06e1\u0645\u064f\u0644\u06e1\u0642\u0650\u064a\u064e\u0670\u062a\u0650 \u0630\u0650\u0643\u06e1\u0631\u064b\u0627",translation:"dan (malaikat-malaikat) yang menyampaikan wahyu"},{id:6,text:"\u0639\u064f\u0630\u06e1\u0631\u064b\u0627 \u0623\u064e\u0648\u06e1 \u0646\u064f\u0630\u06e1\u0631\u064b\u0627",translation:"untuk menolak alasan-alasan atau memberi peringatan"},{id:7,text:"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u062a\u064f\u0648\u0639\u064e\u062f\u064f\u0648\u0646\u064e \u0644\u064e\u0648\u064e\u0670\u0642\u0650\u0639\u065e",translation:"Sungguh, apa yang dijanjikan kepadamu pasti terjadi"},{id:8,text:"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0671\u0644\u0646\u0651\u064f\u062c\u064f\u0648\u0645\u064f \u0637\u064f\u0645\u0650\u0633\u064e\u062a\u06e1",translation:"Maka apabila bintang-bintang dihapuskan"},{id:9,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u064f \u0641\u064f\u0631\u0650\u062c\u064e\u062a\u06e1",translation:"dan apabila langit terbelah"},{id:10,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0671\u0644\u06e1\u062c\u0650\u0628\u064e\u0627\u0644\u064f \u0646\u064f\u0633\u0650\u0641\u064e\u062a\u06e1",translation:"dan apabila gunung-gunung dihancurkan menjadi debu"},{id:11,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0671\u0644\u0631\u0651\u064f\u0633\u064f\u0644\u064f \u0623\u064f\u0642\u0651\u0650\u062a\u064e\u062a\u06e1",translation:"dan apabila rasul-rasul telah ditetapkan waktunya"},{id:12,text:"\u0644\u0650\u0623\u064e\u064a\u0651\u0650 \u064a\u064e\u0648\u06e1\u0645\u064d \u0623\u064f\u062c\u0651\u0650\u0644\u064e\u062a\u06e1",translation:"(Niscaya dikatakan kepada mereka), \"Sampai hari apakah ditangguhkan (azab orang-orang kafir itu)"},{id:13,text:"\u0644\u0650\u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0641\u064e\u0635\u06e1\u0644\u0650",translation:"Sampai hari keputusan"},{id:14,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u062f\u06e1\u0631\u064e\u0649\u0670\u0643\u064e \u0645\u064e\u0627 \u064a\u064e\u0648\u06e1\u0645\u064f \u0671\u0644\u06e1\u0641\u064e\u0635\u06e1\u0644\u0650",translation:"Dan tahukah kamu apakah hari keputusan itu"},{id:15,text:"\u0648\u064e\u064a\u06e1\u0644\u065e \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u0644\u0651\u0650\u0644\u06e1\u0645\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u0650\u064a\u0646\u064e",translation:"Celakalah pada hari itu, bagi mereka yang mendustakan (kebenaran)"},{id:16,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u0646\u064f\u0647\u06e1\u0644\u0650\u0643\u0650 \u0671\u0644\u06e1\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",translation:"Bukankah telah Kami binasakan orang-orang yang dahulu"},{id:17,text:"\u062b\u064f\u0645\u0651\u064e \u0646\u064f\u062a\u06e1\u0628\u0650\u0639\u064f\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u0650\u064a\u0646\u064e",translation:"Lalu Kami susulkan (azab Kami terhadap) orang-orang yang datang kemudian"},{id:18,text:"\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u0641\u06e1\u0639\u064e\u0644\u064f \u0628\u0650\u0671\u0644\u06e1\u0645\u064f\u062c\u06e1\u0631\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Demikianlah Kami perlakukan orang-orang yang berdosa"},{id:19,text:"\u0648\u064e\u064a\u06e1\u0644\u065e \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u0644\u0651\u0650\u0644\u06e1\u0645\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u0650\u064a\u0646\u064e",translation:"Celakalah pada hari itu, bagi mereka yang mendustakan (kebenaran)"},{id:20,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u0646\u064e\u062e\u06e1\u0644\u064f\u0642\u0643\u0651\u064f\u0645 \u0645\u0651\u0650\u0646 \u0645\u0651\u064e\u0627\u0653\u0621\u0656 \u0645\u0651\u064e\u0647\u0650\u064a\u0646\u0656",translation:"Bukankah Kami menciptakan kamu dari air yang hina (mani)"},{id:21,text:"\u0641\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f \u0641\u0650\u064a \u0642\u064e\u0631\u064e\u0627\u0631\u0656 \u0645\u0651\u064e\u0643\u0650\u064a\u0646\u064d",translation:"kemudian Kami letakkan ia dalam tempat yang kokoh (rahim)"},{id:22,text:"\u0625\u0650\u0644\u064e\u0649\u0670 \u0642\u064e\u062f\u064e\u0631\u0656 \u0645\u0651\u064e\u0639\u06e1\u0644\u064f\u0648\u0645\u0656",translation:"sampai waktu yang ditentukan"},{id:23,text:"\u0641\u064e\u0642\u064e\u062f\u064e\u0631\u06e1\u0646\u064e\u0627 \u0641\u064e\u0646\u0650\u0639\u06e1\u0645\u064e \u0671\u0644\u06e1\u0642\u064e\u0670\u062f\u0650\u0631\u064f\u0648\u0646\u064e",translation:"lalu Kami tentukan (bentuknya), maka (Kamilah) sebaik-baik yang menentukan"},{id:24,text:"\u0648\u064e\u064a\u06e1\u0644\u065e \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u0644\u0651\u0650\u0644\u06e1\u0645\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u0650\u064a\u0646\u064e",translation:"Celakalah pada hari itu, bagi mereka yang mendustakan (kebenaran)"},{id:25,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u0646\u064e\u062c\u06e1\u0639\u064e\u0644\u0650 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0643\u0650\u0641\u064e\u0627\u062a\u064b\u0627",translation:"Bukankah Kami jadikan bumi untuk (tempat) berkumpul"},{id:26,text:"\u0623\u064e\u062d\u06e1\u064a\u064e\u0627\u0653\u0621\u0657 \u0648\u064e\u0623\u064e\u0645\u06e1\u0648\u064e\u0670\u062a\u0657\u0627",translation:"bagi yang masih hidup dan yang sudah mati"},{id:27,text:"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0631\u064e\u0648\u064e\u0670\u0633\u0650\u064a\u064e \u0634\u064e\u0670\u0645\u0650\u062e\u064e\u0670\u062a\u0656 \u0648\u064e\u0623\u064e\u0633\u06e1\u0642\u064e\u064a\u06e1\u0646\u064e\u0670\u0643\u064f\u0645 \u0645\u0651\u064e\u0627\u0653\u0621\u0657 \u0641\u064f\u0631\u064e\u0627\u062a\u0657\u0627",translation:"Dan Kami jadikan padanya gunung-gunung yang tinggi, dan Kami beri minum kamu dengan air tawar"},{id:28,text:"\u0648\u064e\u064a\u06e1\u0644\u065e \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u0644\u0651\u0650\u0644\u06e1\u0645\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u0650\u064a\u0646\u064e",translation:"Celakalah pada hari itu, bagi mereka yang mendustakan (kebenaran)"},{id:29,text:"\u0671\u0646\u0637\u064e\u0644\u0650\u0642\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f\u0648\u0646\u064e",translation:"(Akan dikatakan), \"Pergilah kamu guna mendapatkan apa (azab) yang dahulu kamu dustakan"},{id:30,text:"\u0671\u0646\u0637\u064e\u0644\u0650\u0642\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u0649\u0670 \u0638\u0650\u0644\u0651\u0656 \u0630\u0650\u064a \u062b\u064e\u0644\u064e\u0670\u062b\u0650 \u0634\u064f\u0639\u064e\u0628\u0656",translation:"Pergilah kamu mendapatkan naungan (asap api neraka) yang mempunyai tiga cabang"},{id:31,text:"\u0644\u0651\u064e\u0627 \u0638\u064e\u0644\u0650\u064a\u0644\u0656 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u063a\u06e1\u0646\u0650\u064a \u0645\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e\u0628\u0650",translation:"yang tidak melindungi dan tidak pula menolak nyala api neraka"},{id:32,text:"\u0625\u0650\u0646\u0651\u064e\u0647\u064e\u0627 \u062a\u064e\u0631\u06e1\u0645\u0650\u064a \u0628\u0650\u0634\u064e\u0631\u064e\u0631\u0656 \u0643\u064e\u0671\u0644\u06e1\u0642\u064e\u0635\u06e1\u0631\u0650",translation:"Sungguh, (neraka) itu menyemburkan bunga api (sebesar dan setinggi) istana"},{id:33,text:"\u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u06e5 \u062c\u0650\u0645\u064e\u0670\u0644\u064e\u062a\u065e \u0635\u064f\u0641\u06e1\u0631\u065e",translation:"seakan-akan iring-iringan unta yang kuning"},{id:34,text:"\u0648\u064e\u064a\u06e1\u0644\u065e \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u0644\u0651\u0650\u0644\u06e1\u0645\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u0650\u064a\u0646\u064e",translation:"Celakalah pada hari itu, bagi mereka yang mendustakan (kebenaran)"},{id:35,text:"\u0647\u064e\u0670\u0630\u064e\u0627 \u064a\u064e\u0648\u06e1\u0645\u064f \u0644\u064e\u0627 \u064a\u064e\u0646\u0637\u0650\u0642\u064f\u0648\u0646\u064e",translation:"Inilah hari, saat mereka tidak dapat berbicara"},{id:36,text:"\u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0630\u064e\u0646\u064f \u0644\u064e\u0647\u064f\u0645\u06e1 \u0641\u064e\u064a\u064e\u0639\u06e1\u062a\u064e\u0630\u0650\u0631\u064f\u0648\u0646\u064e",translation:"dan tidak diizinkan kepada mereka mengemukakan alasan agar mereka dimaafkan"},{id:37,text:"\u0648\u064e\u064a\u06e1\u0644\u065e \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u0644\u0651\u0650\u0644\u06e1\u0645\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u0650\u064a\u0646\u064e",translation:"Celakalah pada hari itu, bagi mereka yang mendustakan (kebenaran)"},{id:38,text:"\u0647\u064e\u0670\u0630\u064e\u0627 \u064a\u064e\u0648\u06e1\u0645\u064f \u0671\u0644\u06e1\u0641\u064e\u0635\u06e1\u0644\u0650\u06d6 \u062c\u064e\u0645\u064e\u0639\u06e1\u0646\u064e\u0670\u0643\u064f\u0645\u06e1 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",translation:"Inilah hari keputusan; (pada hari ini) Kami kumpulkan kamu dan orang-orang yang terdahulu"},{id:39,text:"\u0641\u064e\u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u06e1 \u0643\u064e\u064a\u06e1\u062f\u065e \u0641\u064e\u0643\u0650\u064a\u062f\u064f\u0648\u0646\u0650",translation:"Maka jika kamu punya tipu daya, maka lakukanlah (tipu daya) itu terhadap-Ku"},{id:40,text:"\u0648\u064e\u064a\u06e1\u0644\u065e \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u0644\u0651\u0650\u0644\u06e1\u0645\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u0650\u064a\u0646\u064e",translation:"Celakalah pada hari itu, bagi mereka yang mendustakan (kebenaran)"},{id:41,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0638\u0650\u0644\u064e\u0670\u0644\u0656 \u0648\u064e\u0639\u064f\u064a\u064f\u0648\u0646\u0656",translation:"Sungguh, orang-orang yang bertakwa berada dalam naungan (pepohonan surga yang teduh) dan (di sekitar) mata air"},{id:42,text:"\u0648\u064e\u0641\u064e\u0648\u064e\u0670\u0643\u0650\u0647\u064e \u0645\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u0634\u06e1\u062a\u064e\u0647\u064f\u0648\u0646\u064e",translation:"dan buah-buahan yang mereka sukai"},{id:43,text:"\u0643\u064f\u0644\u064f\u0648\u0627\u0652 \u0648\u064e\u0671\u0634\u06e1\u0631\u064e\u0628\u064f\u0648\u0627\u0652 \u0647\u064e\u0646\u0650\u064a\u0653\u0640\u0654\u064e\u06e2\u0627 \u0628\u0650\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u06e1 \u062a\u064e\u0639\u06e1\u0645\u064e\u0644\u064f\u0648\u0646\u064e",translation:"(Katakan kepada mereka), \"Makan dan minumlah dengan rasa nikmat sebagai balasan dari apa yang telah kamu kerjakan"},{id:44,text:"\u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u062c\u06e1\u0632\u0650\u064a \u0671\u0644\u06e1\u0645\u064f\u062d\u06e1\u0633\u0650\u0646\u0650\u064a\u0646\u064e",translation:"Sungguh, demikianlah Kami memberi balasan kepada orang-orang yang berbuat baik"},{id:45,text:"\u0648\u064e\u064a\u06e1\u0644\u065e \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u0644\u0651\u0650\u0644\u06e1\u0645\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u0650\u064a\u0646\u064e",translation:"Celakalah pada hari itu, bagi mereka yang mendustakan (kebenaran)"},{id:46,text:"\u0643\u064f\u0644\u064f\u0648\u0627\u0652 \u0648\u064e\u062a\u064e\u0645\u064e\u062a\u0651\u064e\u0639\u064f\u0648\u0627\u0652 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645 \u0645\u0651\u064f\u062c\u06e1\u0631\u0650\u0645\u064f\u0648\u0646\u064e",translation:"(Katakan kepada orang-orang kafir), \"Makan dan bersenang-senanglah kamu (di dunia) sebentar, sesungguhnya kamu orang-orang durhaka"},{id:47,text:"\u0648\u064e\u064a\u06e1\u0644\u065e \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u0644\u0651\u0650\u0644\u06e1\u0645\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u0650\u064a\u0646\u064e",translation:"Celakalah pada hari itu, bagi mereka yang mendustakan (kebenaran)"},{id:48,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0671\u0631\u06e1\u0643\u064e\u0639\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u064a\u064e\u0631\u06e1\u0643\u064e\u0639\u064f\u0648\u0646\u064e",translation:"Dan apabila dikatakan kepada mereka, \"Rukuklah,\" mereka tidak mau rukuk"},{id:49,text:"\u0648\u064e\u064a\u06e1\u0644\u065e \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u0644\u0651\u0650\u0644\u06e1\u0645\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u0650\u064a\u0646\u064e",translation:"Celakalah pada hari itu, bagi mereka yang mendustakan (kebenaran)"},{id:50,text:"\u0641\u064e\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u062d\u064e\u062f\u0650\u064a\u062b\u0650\u06ed \u0628\u064e\u0639\u06e1\u062f\u064e\u0647\u064f\u06e5 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Maka kepada ajaran manakah (selain Alquran) ini mereka akan beriman"}]},{id:78,name:"\u0627\u0644\u0646\u0628\u0625",transliteration:"An-Naba",translation:"Berita Besar",type:"meccan",total_verses:40,verses:[{id:1,text:"\u0639\u064e\u0645\u0651\u064e \u064a\u064e\u062a\u064e\u0633\u064e\u0627\u0653\u0621\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Tentang apakah mereka saling bertanya-tanya"},{id:2,text:"\u0639\u064e\u0646\u0650 \u0671\u0644\u0646\u0651\u064e\u0628\u064e\u0625\u0650 \u0671\u0644\u06e1\u0639\u064e\u0638\u0650\u064a\u0645\u0650",translation:"Tentang berita yang besar (hari berbangkit)"},{id:3,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0647\u064f\u0645\u06e1 \u0641\u0650\u064a\u0647\u0650 \u0645\u064f\u062e\u06e1\u062a\u064e\u0644\u0650\u0641\u064f\u0648\u0646\u064e",translation:"yang dalam hal itu mereka berselisih"},{id:4,text:"\u0643\u064e\u0644\u0651\u064e\u0627 \u0633\u064e\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"(Tidak!892) Kelak mereka akan mengetahui"},{id:5,text:"\u062b\u064f\u0645\u0651\u064e \u0643\u064e\u0644\u0651\u064e\u0627 \u0633\u064e\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"sekali lagi tidak! Kelak mereka akan mengetahui"},{id:6,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u0646\u064e\u062c\u06e1\u0639\u064e\u0644\u0650 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0645\u0650\u0647\u064e\u0670\u062f\u0657\u0627",translation:"Bukankah Kami telah menjadikan bumi sebagai hamparan"},{id:7,text:"\u0648\u064e\u0671\u0644\u06e1\u062c\u0650\u0628\u064e\u0627\u0644\u064e \u0623\u064e\u0648\u06e1\u062a\u064e\u0627\u062f\u0657\u0627",translation:"dan gunung-gunung sebagai pasak"},{id:8,text:"\u0648\u064e\u062e\u064e\u0644\u064e\u0642\u06e1\u0646\u064e\u0670\u0643\u064f\u0645\u06e1 \u0623\u064e\u0632\u06e1\u0648\u064e\u0670\u062c\u0657\u0627",translation:"Dan Kami menciptakan kamu berpasang-pasangan"},{id:9,text:"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0646\u064e\u0648\u06e1\u0645\u064e\u0643\u064f\u0645\u06e1 \u0633\u064f\u0628\u064e\u0627\u062a\u0657\u0627",translation:"dan Kami menjadikan tidurmu untuk istirahat"},{id:10,text:"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u064e \u0644\u0650\u0628\u064e\u0627\u0633\u0657\u0627",translation:"dan Kami menjadikan malam sebagai pakaian"},{id:11,text:"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u0645\u064e\u0639\u064e\u0627\u0634\u0657\u0627",translation:"dan Kami menjadikan siang untuk mencari penghidupan"},{id:12,text:"\u0648\u064e\u0628\u064e\u0646\u064e\u064a\u06e1\u0646\u064e\u0627 \u0641\u064e\u0648\u06e1\u0642\u064e\u0643\u064f\u0645\u06e1 \u0633\u064e\u0628\u06e1\u0639\u0657\u0627 \u0634\u0650\u062f\u064e\u0627\u062f\u0657\u0627",translation:"dan Kami membangun di atas kamu tujuh (lapis langit) yang kokoh"},{id:13,text:"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u06e1\u0646\u064e\u0627 \u0633\u0650\u0631\u064e\u0627\u062c\u0657\u0627 \u0648\u064e\u0647\u0651\u064e\u0627\u062c\u0657\u0627",translation:"dan Kami menjadikan pelita yang terang-benderang (matahari)"},{id:14,text:"\u0648\u064e\u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0645\u064f\u0639\u06e1\u0635\u0650\u0631\u064e\u0670\u062a\u0650 \u0645\u064e\u0627\u0653\u0621\u0657 \u062b\u064e\u062c\u0651\u064e\u0627\u062c\u0657\u0627",translation:"dan Kami turunkan dari awan, air hujan yang tercurah dengan lebatnya"},{id:15,text:"\u0644\u0651\u0650\u0646\u064f\u062e\u06e1\u0631\u0650\u062c\u064e \u0628\u0650\u0647\u0650\u06e6 \u062d\u064e\u0628\u0651\u0657\u0627 \u0648\u064e\u0646\u064e\u0628\u064e\u0627\u062a\u0657\u0627",translation:"untuk Kami tumbuhkan dengan air itu biji-bijian dan tanam-tanaman"},{id:16,text:"\u0648\u064e\u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u064d \u0623\u064e\u0644\u06e1\u0641\u064e\u0627\u0641\u064b\u0627",translation:"dan kebun-kebun yang rindang"},{id:17,text:"\u0625\u0650\u0646\u0651\u064e \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u06e1\u0641\u064e\u0635\u06e1\u0644\u0650 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u064a\u0642\u064e\u0670\u062a\u0657\u0627",translation:"Sungguh, hari keputusan adalah suatu waktu yang telah ditetapkan"},{id:18,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064f\u0646\u0641\u064e\u062e\u064f \u0641\u0650\u064a \u0671\u0644\u0635\u0651\u064f\u0648\u0631\u0650 \u0641\u064e\u062a\u064e\u0623\u06e1\u062a\u064f\u0648\u0646\u064e \u0623\u064e\u0641\u06e1\u0648\u064e\u0627\u062c\u0657\u0627",translation:"(yaitu) pada hari (ketika) sangkakala ditiup, lalu kamu datang berbondong-bondong"},{id:19,text:"\u0648\u064e\u0641\u064f\u062a\u0650\u062d\u064e\u062a\u0650 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u064f \u0641\u064e\u0643\u064e\u0627\u0646\u064e\u062a\u06e1 \u0623\u064e\u0628\u06e1\u0648\u064e\u0670\u0628\u0657\u0627",translation:"dan langit pun dibukalah, maka terdapatlah beberapa pintu"},{id:20,text:"\u0648\u064e\u0633\u064f\u064a\u0651\u0650\u0631\u064e\u062a\u0650 \u0671\u0644\u06e1\u062c\u0650\u0628\u064e\u0627\u0644\u064f \u0641\u064e\u0643\u064e\u0627\u0646\u064e\u062a\u06e1 \u0633\u064e\u0631\u064e\u0627\u0628\u064b\u0627",translation:"dan gunung-gunungpun dijalankan sehingga menjadi fatamorgana"},{id:21,text:"\u0625\u0650\u0646\u0651\u064e \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0643\u064e\u0627\u0646\u064e\u062a\u06e1 \u0645\u0650\u0631\u06e1\u0635\u064e\u0627\u062f\u0657\u0627",translation:"Sungguh, (neraka) Jahanam itu (sebagai) tempat mengintai (bagi penjaga yang mengawasi isi neraka)"},{id:22,text:"\u0644\u0651\u0650\u0644\u0637\u0651\u064e\u0640\u0670\u063a\u0650\u064a\u0646\u064e \u0645\u064e\u0640\u0654\u064e\u0627\u0628\u0657\u0627",translation:"menjadi tempat kembali bagi orang-orang yang melampaui batas"},{id:23,text:"\u0644\u0651\u064e\u0640\u0670\u0628\u0650\u062b\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627\u0653 \u0623\u064e\u062d\u06e1\u0642\u064e\u0627\u0628\u0657\u0627",translation:"Mereka tinggal di sana dalam masa yang lama"},{id:24,text:"\u0644\u0651\u064e\u0627 \u064a\u064e\u0630\u064f\u0648\u0642\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0628\u064e\u0631\u06e1\u062f\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u0634\u064e\u0631\u064e\u0627\u0628\u064b\u0627",translation:"mereka tidak merasakan kesejukan di dalamnya dan tidak (pula mendapat) minuman"},{id:25,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u062d\u064e\u0645\u0650\u064a\u0645\u0657\u0627 \u0648\u064e\u063a\u064e\u0633\u0651\u064e\u0627\u0642\u0657\u0627",translation:"selain air yang mendidih dan nanah"},{id:26,text:"\u062c\u064e\u0632\u064e\u0627\u0653\u0621\u0657 \u0648\u0650\u0641\u064e\u0627\u0642\u064b\u0627",translation:"sebagai pembalasan yang setimpal"},{id:27,text:"\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u064a\u064e\u0631\u06e1\u062c\u064f\u0648\u0646\u064e \u062d\u0650\u0633\u064e\u0627\u0628\u0657\u0627",translation:"Sesungguhnya dahulu mereka tidak pernah mengharapkan perhitungan"},{id:28,text:"\u0648\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0643\u0650\u0630\u0651\u064e\u0627\u0628\u0657\u0627",translation:"dan mereka benar-benar mendustakan ayat-ayat Kami"},{id:29,text:"\u0648\u064e\u0643\u064f\u0644\u0651\u064e \u0634\u064e\u064a\u06e1\u0621\u064d \u0623\u064e\u062d\u06e1\u0635\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f \u0643\u0650\u062a\u064e\u0670\u0628\u0657\u0627",translation:"Dan segala sesuatu telah Kami catat dalam suatu Kitab (buku catatan amalan manusia)"},{id:30,text:"\u0641\u064e\u0630\u064f\u0648\u0642\u064f\u0648\u0627\u0652 \u0641\u064e\u0644\u064e\u0646 \u0646\u0651\u064e\u0632\u0650\u064a\u062f\u064e\u0643\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0630\u064e\u0627\u0628\u064b\u0627",translation:"Maka karena itu rasakanlah! Maka tidak ada yang akan Kami tambahkan kepadamu selain azab"},{id:31,text:"\u0625\u0650\u0646\u0651\u064e \u0644\u0650\u0644\u06e1\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e \u0645\u064e\u0641\u064e\u0627\u0632\u064b\u0627",translation:"Sungguh, orang-orang yang bertakwa mendapat kemenangan"},{id:32,text:"\u062d\u064e\u062f\u064e\u0627\u0653\u0626\u0650\u0642\u064e \u0648\u064e\u0623\u064e\u0639\u06e1\u0646\u064e\u0670\u0628\u0657\u0627",translation:"(yaitu) kebun-kebun dan buah anggur"},{id:33,text:"\u0648\u064e\u0643\u064e\u0648\u064e\u0627\u0639\u0650\u0628\u064e \u0623\u064e\u062a\u06e1\u0631\u064e\u0627\u0628\u0657\u0627",translation:"dan gadis-gadis belia yang sebaya"},{id:34,text:"\u0648\u064e\u0643\u064e\u0623\u06e1\u0633\u0657\u0627 \u062f\u0650\u0647\u064e\u0627\u0642\u0657\u0627",translation:"dan gelas-gelas yang penuh (berisi minuman)"},{id:35,text:"\u0644\u0651\u064e\u0627 \u064a\u064e\u0633\u06e1\u0645\u064e\u0639\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0644\u064e\u063a\u06e1\u0648\u0657\u0627 \u0648\u064e\u0644\u064e\u0627 \u0643\u0650\u0630\u0651\u064e\u0640\u0670\u0628\u0657\u0627",translation:"Di sana mereka tidak mendengar percakapan yang sia-sia maupun (perkataan dusta)"},{id:36,text:"\u062c\u064e\u0632\u064e\u0627\u0653\u0621\u0657 \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064e \u0639\u064e\u0637\u064e\u0627\u0653\u0621\u064b \u062d\u0650\u0633\u064e\u0627\u0628\u0657\u0627",translation:"Sebagai balasan dan pemberian yang cukup banyak dari Tuhanmu"},{id:37,text:"\u0631\u0651\u064e\u0628\u0651\u0650 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u06e1\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u0650\u06d6 \u0644\u064e\u0627 \u064a\u064e\u0645\u06e1\u0644\u0650\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u06e1\u0647\u064f \u062e\u0650\u0637\u064e\u0627\u0628\u0657\u0627",translation:"Tuhan (yang memelihara) langit dan bumi serta apa yang ada di antara keduanya; Yang Maha Pengasih, mereka tidak mampu berbicara dengan Dia"},{id:38,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064e\u0642\u064f\u0648\u0645\u064f \u0671\u0644\u0631\u0651\u064f\u0648\u062d\u064f \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u064f \u0635\u064e\u0641\u0651\u0657\u0627\u06d6 \u0644\u0651\u064e\u0627 \u064a\u064e\u062a\u064e\u0643\u064e\u0644\u0651\u064e\u0645\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u06e1 \u0623\u064e\u0630\u0650\u0646\u064e \u0644\u064e\u0647\u064f \u0671\u0644\u0631\u0651\u064e\u062d\u06e1\u0645\u064e\u0670\u0646\u064f \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0635\u064e\u0648\u064e\u0627\u0628\u0657\u0627",translation:"(Pada hari, ketika r\u016b\u1e25894) dan para malaikat berdiri bersaf-saf, mereka tidak berkata-kata, kecuali siapa yang telah diberi izin kepadanya oleh Tuhan Yang Maha Pengasih dan dia hanya mengatakan yang benar"},{id:39,text:"\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064f \u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u064f\u06d6 \u0641\u064e\u0645\u064e\u0646 \u0634\u064e\u0627\u0653\u0621\u064e \u0671\u062a\u0651\u064e\u062e\u064e\u0630\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u06e6 \u0645\u064e\u0640\u0654\u064e\u0627\u0628\u064b\u0627",translation:"Itulah hari yang pasti terjadi. Maka barangsiapa menghendaki, niscaya dia menempuh jalan kembali kepada Tuhannya"},{id:40,text:"\u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u0646\u0630\u064e\u0631\u06e1\u0646\u064e\u0670\u0643\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u0657\u0627 \u0642\u064e\u0631\u0650\u064a\u0628\u0657\u0627 \u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064e\u0646\u0638\u064f\u0631\u064f \u0671\u0644\u06e1\u0645\u064e\u0631\u06e1\u0621\u064f \u0645\u064e\u0627 \u0642\u064e\u062f\u0651\u064e\u0645\u064e\u062a\u06e1 \u064a\u064e\u062f\u064e\u0627\u0647\u064f \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0671\u0644\u06e1\u0643\u064e\u0627\u0641\u0650\u0631\u064f \u064a\u064e\u0670\u0644\u064e\u064a\u06e1\u062a\u064e\u0646\u0650\u064a \u0643\u064f\u0646\u062a\u064f \u062a\u064f\u0631\u064e\u0670\u0628\u064e\u06e2\u0627",translation:"Sesungguhnya Kami telah memperingatkan kepadamu (orang kafir) azab yang dekat, pada hari manusia melihat apa yang telah diperbuat oleh kedua tangannya; dan orang kafir berkata, \"Alangkah baiknya seandainya dahulu aku jadi tanah"}]},{id:79,name:"\u0627\u0644\u0646\u0627\u0632\u0639\u0627\u062a",transliteration:"An-Nazi'at",translation:"Malaikat yang Mencabut",type:"meccan",total_verses:46,verses:[{id:1,text:"\u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0640\u0670\u0632\u0650\u0639\u064e\u0670\u062a\u0650 \u063a\u064e\u0631\u06e1\u0642\u0657\u0627",translation:"Demi (malaikat) yang mencabut (nyawa) dengan keras"},{id:2,text:"\u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0640\u0670\u0634\u0650\u0637\u064e\u0670\u062a\u0650 \u0646\u064e\u0634\u06e1\u0637\u0657\u0627",translation:"Demi (malaikat) yang mencabut (nyawa) dengan lemah lembut"},{id:3,text:"\u0648\u064e\u0671\u0644\u0633\u0651\u064e\u0640\u0670\u0628\u0650\u062d\u064e\u0670\u062a\u0650 \u0633\u064e\u0628\u06e1\u062d\u0657\u0627",translation:"Demi (malaikat) yang turun dari langit dengan cepat"},{id:4,text:"\u0641\u064e\u0671\u0644\u0633\u0651\u064e\u0640\u0670\u0628\u0650\u0642\u064e\u0670\u062a\u0650 \u0633\u064e\u0628\u06e1\u0642\u0657\u0627",translation:"dan (malaikat) yang mendahului dengan kencang"},{id:5,text:"\u0641\u064e\u0671\u0644\u06e1\u0645\u064f\u062f\u064e\u0628\u0651\u0650\u0631\u064e\u0670\u062a\u0650 \u0623\u064e\u0645\u06e1\u0631\u0657\u0627",translation:"dan (malaikat) yang mengatur urusan (dunia)"},{id:6,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u062a\u064e\u0631\u06e1\u062c\u064f\u0641\u064f \u0671\u0644\u0631\u0651\u064e\u0627\u062c\u0650\u0641\u064e\u0629\u064f",translation:"(Sungguh, kamu akan dibangkitkan) pada hari ketika tiupan pertama mengguncangkan alam"},{id:7,text:"\u062a\u064e\u062a\u06e1\u0628\u064e\u0639\u064f\u0647\u064e\u0627 \u0671\u0644\u0631\u0651\u064e\u0627\u062f\u0650\u0641\u064e\u0629\u064f",translation:"(tiupan pertama) itu diiringi oleh tiupan kedua"},{id:8,text:"\u0642\u064f\u0644\u064f\u0648\u0628\u065e \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u0648\u064e\u0627\u062c\u0650\u0641\u064e\u0629\u064c",translation:"Hati manusia pada waktu itu merasa sangat takut"},{id:9,text:"\u0623\u064e\u0628\u06e1\u0635\u064e\u0670\u0631\u064f\u0647\u064e\u0627 \u062e\u064e\u0670\u0634\u0650\u0639\u064e\u0629\u065e",translation:"pandangannya tunduk"},{id:10,text:"\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0623\u064e\u0621\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0645\u064e\u0631\u06e1\u062f\u064f\u0648\u062f\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u062d\u064e\u0627\u0641\u0650\u0631\u064e\u0629\u0650",translation:"(orang-orang kafir) berkata, \"Apakah kita benar-benar akan dikembalikan kepada kehidupan yang semula"},{id:11,text:"\u0623\u064e\u0621\u0650\u0630\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0639\u0650\u0638\u064e\u0670\u0645\u0657\u0627 \u0646\u0651\u064e\u062e\u0650\u0631\u064e\u0629\u0657",translation:"Apakah (akan dibangkitkan juga) apabila kita telah menjadi tulang belulang yang hancur"},{id:12,text:"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u062a\u0650\u0644\u06e1\u0643\u064e \u0625\u0650\u0630\u0657\u0627 \u0643\u064e\u0631\u0651\u064e\u0629\u064c \u062e\u064e\u0627\u0633\u0650\u0631\u064e\u0629\u065e",translation:"Mereka berkata, \"Kalau demikian, itu adalah suatu pengembalian yang merugikan"},{id:13,text:"\u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0647\u0650\u064a\u064e \u0632\u064e\u062c\u06e1\u0631\u064e\u0629\u065e \u0648\u064e\u0670\u062d\u0650\u062f\u064e\u0629\u065e",translation:"Maka pengembalian itu hanyalah dengan sekali tiupan saja"},{id:14,text:"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0647\u064f\u0645 \u0628\u0650\u0671\u0644\u0633\u0651\u064e\u0627\u0647\u0650\u0631\u064e\u0629\u0650",translation:"Maka seketika itu mereka hidup kembali di bumi (yang baru)"},{id:15,text:"\u0647\u064e\u0644\u06e1 \u0623\u064e\u062a\u064e\u0649\u0670\u0643\u064e \u062d\u064e\u062f\u0650\u064a\u062b\u064f \u0645\u064f\u0648\u0633\u064e\u0649\u0670\u0653",translation:"Sudahkah sampai kepadamu (Muhammad) kisah Musa"},{id:16,text:"\u0625\u0650\u0630\u06e1 \u0646\u064e\u0627\u062f\u064e\u0649\u0670\u0647\u064f \u0631\u064e\u0628\u0651\u064f\u0647\u064f\u06e5 \u0628\u0650\u0671\u0644\u06e1\u0648\u064e\u0627\u062f\u0650 \u0671\u0644\u06e1\u0645\u064f\u0642\u064e\u062f\u0651\u064e\u0633\u0650 \u0637\u064f\u0648\u064b\u0649",translation:"Ketika Tuhan memanggilnya (Musa) di lembah suci yaitu Lembah Tuwa"},{id:17,text:"\u0671\u0630\u06e1\u0647\u064e\u0628\u06e1 \u0625\u0650\u0644\u064e\u0649\u0670 \u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0637\u064e\u063a\u064e\u0649\u0670",translation:"pergilah engkau kepada Fir'aun! Sesungguhnya dia telah melampaui batas"},{id:18,text:"\u0641\u064e\u0642\u064f\u0644\u06e1 \u0647\u064e\u0644 \u0644\u0651\u064e\u0643\u064e \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0646 \u062a\u064e\u0632\u064e\u0643\u0651\u064e\u0649\u0670",translation:"Maka katakanlah (kepada Fir'aun), \"Adakah keinginanmu untuk membersihkan diri (dari kesesatan)"},{id:19,text:"\u0648\u064e\u0623\u064e\u0647\u06e1\u062f\u0650\u064a\u064e\u0643\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0641\u064e\u062a\u064e\u062e\u06e1\u0634\u064e\u0649\u0670",translation:"dan engkau akan kubimbing ke jalan Tuhanmu agar engkau takut kepada-Nya"},{id:20,text:"\u0641\u064e\u0623\u064e\u0631\u064e\u0649\u0670\u0647\u064f \u0671\u0644\u06e1\u0623\u0653\u064a\u064e\u0629\u064e \u0671\u0644\u06e1\u0643\u064f\u0628\u06e1\u0631\u064e\u0649\u0670",translation:"Lalu (Musa) memperlihatkan kepadanya mukjizat yang besar"},{id:21,text:"\u0641\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0648\u064e\u0639\u064e\u0635\u064e\u0649\u0670",translation:"Tetapi dia (Fir'aun) mendustakan dan mendurhakai"},{id:22,text:"\u062b\u064f\u0645\u0651\u064e \u0623\u064e\u062f\u06e1\u0628\u064e\u0631\u064e \u064a\u064e\u0633\u06e1\u0639\u064e\u0649\u0670",translation:"Kemudian dia berpaling seraya berusaha menantang (Musa)"},{id:23,text:"\u0641\u064e\u062d\u064e\u0634\u064e\u0631\u064e \u0641\u064e\u0646\u064e\u0627\u062f\u064e\u0649\u0670",translation:"Kemudian dia mengumpulkan (pembesar-pembesarnya) lalu berseru (memanggil kaumnya)"},{id:24,text:"\u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0646\u064e\u0627\u06e0 \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u064f \u0671\u0644\u06e1\u0623\u064e\u0639\u06e1\u0644\u064e\u0649\u0670",translation:"(Seraya) berkata, \"Akulah tuhanmu yang paling tinggi"},{id:25,text:"\u0641\u064e\u0623\u064e\u062e\u064e\u0630\u064e\u0647\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0646\u064e\u0643\u064e\u0627\u0644\u064e \u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064f\u0648\u0644\u064e\u0649\u0670\u0653",translation:"Maka Allah menghukumnya dengan azab di akhirat dan siksaan di dunia"},{id:26,text:"\u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0639\u0650\u0628\u06e1\u0631\u064e\u0629\u0657 \u0644\u0651\u0650\u0645\u064e\u0646 \u064a\u064e\u062e\u06e1\u0634\u064e\u0649\u0670\u0653",translation:"Sungguh, pada yang demikian itu terdapat pelajaran bagi orang yang takut (kepada Allah)"},{id:27,text:"\u0621\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0623\u064e\u0634\u064e\u062f\u0651\u064f \u062e\u064e\u0644\u06e1\u0642\u064b\u0627 \u0623\u064e\u0645\u0650 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u064f\u06da \u0628\u064e\u0646\u064e\u0649\u0670\u0647\u064e\u0627",translation:"Apakah penciptaan kamu yang lebih hebat ataukah langit yang telah dibangun-Nya"},{id:28,text:"\u0631\u064e\u0641\u064e\u0639\u064e \u0633\u064e\u0645\u06e1\u0643\u064e\u0647\u064e\u0627 \u0641\u064e\u0633\u064e\u0648\u0651\u064e\u0649\u0670\u0647\u064e\u0627",translation:"Dia telah meninggikan bangunannya lalu menyempurnakannya"},{id:29,text:"\u0648\u064e\u0623\u064e\u063a\u06e1\u0637\u064e\u0634\u064e \u0644\u064e\u064a\u06e1\u0644\u064e\u0647\u064e\u0627 \u0648\u064e\u0623\u064e\u062e\u06e1\u0631\u064e\u062c\u064e \u0636\u064f\u062d\u064e\u0649\u0670\u0647\u064e\u0627",translation:"dan Dia menjadikan malamnya (gelap gulita), dan menjadikan siangnya (terang benderang)"},{id:30,text:"\u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0628\u064e\u0639\u06e1\u062f\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062f\u064e\u062d\u064e\u0649\u0670\u0647\u064e\u0627\u0653",translation:"Dan setelah itu bumi Dia hamparkan"},{id:31,text:"\u0623\u064e\u062e\u06e1\u0631\u064e\u062c\u064e \u0645\u0650\u0646\u06e1\u0647\u064e\u0627 \u0645\u064e\u0627\u0653\u0621\u064e\u0647\u064e\u0627 \u0648\u064e\u0645\u064e\u0631\u06e1\u0639\u064e\u0649\u0670\u0647\u064e\u0627",translation:"Darinya Dia pancarkan mata air, dan (ditumbuhkan) tumbuh-tumbuhannya"},{id:32,text:"\u0648\u064e\u0671\u0644\u06e1\u062c\u0650\u0628\u064e\u0627\u0644\u064e \u0623\u064e\u0631\u06e1\u0633\u064e\u0649\u0670\u0647\u064e\u0627",translation:"Dan gunung-gunung Dia pancangkan dengan kokoh"},{id:33,text:"\u0645\u064e\u062a\u064e\u0670\u0639\u0657\u0627 \u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u0650\u0623\u064e\u0646\u06e1\u0639\u064e\u0670\u0645\u0650\u0643\u064f\u0645\u06e1",translation:"(Semua itu) untuk kesenanganmu dan untuk hewan-hewan ternakmu"},{id:34,text:"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u062a\u0650 \u0671\u0644\u0637\u0651\u064e\u0627\u0653\u0645\u0651\u064e\u0629\u064f \u0671\u0644\u06e1\u0643\u064f\u0628\u06e1\u0631\u064e\u0649\u0670",translation:"Maka apabila malapetaka besar (hari Kiamat) telah datang"},{id:35,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064e\u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064f \u0645\u064e\u0627 \u0633\u064e\u0639\u064e\u0649\u0670",translation:"yaitu pada hari (ketika) manusia teringat akan apa yang telah dikerjakannya"},{id:36,text:"\u0648\u064e\u0628\u064f\u0631\u0651\u0650\u0632\u064e\u062a\u0650 \u0671\u0644\u06e1\u062c\u064e\u062d\u0650\u064a\u0645\u064f \u0644\u0650\u0645\u064e\u0646 \u064a\u064e\u0631\u064e\u0649\u0670",translation:"dan neraka diperlihatkan dengan jelas kepada setiap orang yang melihat"},{id:37,text:"\u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0645\u064e\u0646 \u0637\u064e\u063a\u064e\u0649\u0670",translation:"Maka adapun orang yang melampaui batas"},{id:38,text:"\u0648\u064e\u0621\u064e\u0627\u062b\u064e\u0631\u064e \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u064e \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627",translation:"dan lebih mengutamakan kehidupan dunia"},{id:39,text:"\u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u062c\u064e\u062d\u0650\u064a\u0645\u064e \u0647\u0650\u064a\u064e \u0671\u0644\u06e1\u0645\u064e\u0623\u06e1\u0648\u064e\u0649\u0670",translation:"maka sungguh, nerakalah tempat tinggalnya"},{id:40,text:"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0645\u064e\u0646\u06e1 \u062e\u064e\u0627\u0641\u064e \u0645\u064e\u0642\u064e\u0627\u0645\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u06e6 \u0648\u064e\u0646\u064e\u0647\u064e\u0649 \u0671\u0644\u0646\u0651\u064e\u0641\u06e1\u0633\u064e \u0639\u064e\u0646\u0650 \u0671\u0644\u06e1\u0647\u064e\u0648\u064e\u0649\u0670",translation:"Dan adapun orang-orang yang takut kepada kebesaran Tuhannya dan menahan diri dari (keinginan) hawa nafsunya"},{id:41,text:"\u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u064e \u0647\u0650\u064a\u064e \u0671\u0644\u06e1\u0645\u064e\u0623\u06e1\u0648\u064e\u0649\u0670",translation:"maka sungguh, surgalah tempat tinggal-(nya)"},{id:42,text:"\u064a\u064e\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u0639\u064e\u0646\u0650 \u0671\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u0650 \u0623\u064e\u064a\u0651\u064e\u0627\u0646\u064e \u0645\u064f\u0631\u06e1\u0633\u064e\u0649\u0670\u0647\u064e\u0627",translation:"Mereka (orang-orang kafir) bertanya kepadamu (Muhammad) tentang hari Kiamat, \"Kapankah terjadinya"},{id:43,text:"\u0641\u0650\u064a\u0645\u064e \u0623\u064e\u0646\u062a\u064e \u0645\u0650\u0646 \u0630\u0650\u0643\u06e1\u0631\u064e\u0649\u0670\u0647\u064e\u0627\u0653",translation:"Untuk apa engkau perlu menyebutkannya (waktunya)"},{id:44,text:"\u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0645\u064f\u0646\u062a\u064e\u0647\u064e\u0649\u0670\u0647\u064e\u0627\u0653",translation:"Kepada Tuhanmulah (dikembalikan) kesudahannya (ketentuan waktunya)"},{id:45,text:"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064e \u0645\u064f\u0646\u0630\u0650\u0631\u064f \u0645\u064e\u0646 \u064a\u064e\u062e\u06e1\u0634\u064e\u0649\u0670\u0647\u064e\u0627",translation:"Engkau (Muhammad) hanyalah pemberi peringatan bagi siapa yang takut kepadanya (hari Kiamat)"},{id:46,text:"\u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064e\u0631\u064e\u0648\u06e1\u0646\u064e\u0647\u064e\u0627 \u0644\u064e\u0645\u06e1 \u064a\u064e\u0644\u06e1\u0628\u064e\u062b\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0634\u0650\u064a\u0651\u064e\u0629\u064b \u0623\u064e\u0648\u06e1 \u0636\u064f\u062d\u064e\u0649\u0670\u0647\u064e\u0627",translation:"Pada hari ketika mereka melihat hari Kiamat itu (karena suasananya hebat), mereka merasa seakan-akan hanya (sebentar saja) tinggal (di dunia) pada waktu sore atau pagi hari"}]},{id:80,name:"\u0639\u0628\u0633",transliteration:"'Abasa",translation:"Ia Bermuka Masam",type:"meccan",total_verses:42,verses:[{id:1,text:"\u0639\u064e\u0628\u064e\u0633\u064e \u0648\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649\u0670\u0653",translation:"Dia (Muhammad) berwajah masam dan berpaling"},{id:2,text:"\u0623\u064e\u0646 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064f \u0671\u0644\u06e1\u0623\u064e\u0639\u06e1\u0645\u064e\u0649\u0670",translation:"karena seorang buta telah datang kepadanya (Abdullah bin Ummi Maktum)"},{id:3,text:"\u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u062f\u06e1\u0631\u0650\u064a\u0643\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u06e5 \u064a\u064e\u0632\u0651\u064e\u0643\u0651\u064e\u0649\u0670\u0653",translation:"Dan tahukah engkau (Muhammad) barangkali dia ingin menyucikan dirinya (dari dosa)"},{id:4,text:"\u0623\u064e\u0648\u06e1 \u064a\u064e\u0630\u0651\u064e\u0643\u0651\u064e\u0631\u064f \u0641\u064e\u062a\u064e\u0646\u0641\u064e\u0639\u064e\u0647\u064f \u0671\u0644\u0630\u0651\u0650\u0643\u06e1\u0631\u064e\u0649\u0670\u0653",translation:"atau dia (ingin) mendapatkan pengajaran, yang memberi manfaat kepadanya"},{id:5,text:"\u0623\u064e\u0645\u0651\u064e\u0627 \u0645\u064e\u0646\u0650 \u0671\u0633\u06e1\u062a\u064e\u063a\u06e1\u0646\u064e\u0649\u0670",translation:"Adapun orang yang merasa dirinya serba cukup (pembesar-pembesar Quraisy)"},{id:6,text:"\u0641\u064e\u0623\u064e\u0646\u062a\u064e \u0644\u064e\u0647\u064f\u06e5 \u062a\u064e\u0635\u064e\u062f\u0651\u064e\u0649\u0670",translation:"maka engkau (Muhammad) memberi perhatian kepadanya"},{id:7,text:"\u0648\u064e\u0645\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064e \u0623\u064e\u0644\u0651\u064e\u0627 \u064a\u064e\u0632\u0651\u064e\u0643\u0651\u064e\u0649\u0670",translation:"padahal tidak ada (cela) atasmu kalau dia tidak menyucikan diri (beriman)"},{id:8,text:"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0645\u064e\u0646 \u062c\u064e\u0627\u0653\u0621\u064e\u0643\u064e \u064a\u064e\u0633\u06e1\u0639\u064e\u0649\u0670",translation:"Dan adapun orang yang datang kepadamu dengan bersegera (untuk mendapatkan pengajaran)"},{id:9,text:"\u0648\u064e\u0647\u064f\u0648\u064e \u064a\u064e\u062e\u06e1\u0634\u064e\u0649\u0670",translation:"sedang dia takut (kepada Allah)"},{id:10,text:"\u0641\u064e\u0623\u064e\u0646\u062a\u064e \u0639\u064e\u0646\u06e1\u0647\u064f \u062a\u064e\u0644\u064e\u0647\u0651\u064e\u0649\u0670",translation:"engkau (Muhammad) malah mengabaikannya"},{id:11,text:"\u0643\u064e\u0644\u0651\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0647\u064e\u0627 \u062a\u064e\u0630\u06e1\u0643\u0650\u0631\u064e\u0629\u065e",translation:"Sekali-kali jangan (begitu)! Sungguh, (ajaran-ajaran Allah) itu suatu peringatan"},{id:12,text:"\u0641\u064e\u0645\u064e\u0646 \u0634\u064e\u0627\u0653\u0621\u064e \u0630\u064e\u0643\u064e\u0631\u064e\u0647\u064f\u06e5",translation:"maka barangsiapa menghendaki, tentulah dia akan memperhatikannya"},{id:13,text:"\u0641\u0650\u064a \u0635\u064f\u062d\u064f\u0641\u0656 \u0645\u0651\u064f\u0643\u064e\u0631\u0651\u064e\u0645\u064e\u0629\u0656",translation:"di dalam kitab-kitab yang dimuliakan (di sisi Allah)"},{id:14,text:"\u0645\u0651\u064e\u0631\u06e1\u0641\u064f\u0648\u0639\u064e\u0629\u0656 \u0645\u0651\u064f\u0637\u064e\u0647\u0651\u064e\u0631\u064e\u0629\u0650\u06ed",translation:"yang ditinggikan (dan) disucikan"},{id:15,text:"\u0628\u0650\u0623\u064e\u064a\u06e1\u062f\u0650\u064a \u0633\u064e\u0641\u064e\u0631\u064e\u0629\u0656",translation:"di tangan para utusan (malaikat)"},{id:16,text:"\u0643\u0650\u0631\u064e\u0627\u0645\u0650\u06ed \u0628\u064e\u0631\u064e\u0631\u064e\u0629\u0656",translation:"yang mulia lagi berbakti"},{id:17,text:"\u0642\u064f\u062a\u0650\u0644\u064e \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064f \u0645\u064e\u0627\u0653 \u0623\u064e\u0643\u06e1\u0641\u064e\u0631\u064e\u0647\u064f\u06e5",translation:"Celakalah manusia! Alangkah kufurnya dia"},{id:18,text:"\u0645\u0650\u0646\u06e1 \u0623\u064e\u064a\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u064d \u062e\u064e\u0644\u064e\u0642\u064e\u0647\u064f\u06e5",translation:"Dari apakah Dia (Allah) menciptakannya"},{id:19,text:"\u0645\u0650\u0646 \u0646\u0651\u064f\u0637\u06e1\u0641\u064e\u0629\u064d \u062e\u064e\u0644\u064e\u0642\u064e\u0647\u064f\u06e5 \u0641\u064e\u0642\u064e\u062f\u0651\u064e\u0631\u064e\u0647\u064f\u06e5",translation:"Dari setetes mani, Dia menciptakannya lalu menentukannya"},{id:20,text:"\u062b\u064f\u0645\u0651\u064e \u0671\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u064e \u064a\u064e\u0633\u0651\u064e\u0631\u064e\u0647\u064f\u06e5",translation:"Kemudian jalannya Dia mudahkan"},{id:21,text:"\u062b\u064f\u0645\u0651\u064e \u0623\u064e\u0645\u064e\u0627\u062a\u064e\u0647\u064f\u06e5 \u0641\u064e\u0623\u064e\u0642\u06e1\u0628\u064e\u0631\u064e\u0647\u064f\u06e5",translation:"kemudian Dia mematikannya lalu menguburkannya"},{id:22,text:"\u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0630\u064e\u0627 \u0634\u064e\u0627\u0653\u0621\u064e \u0623\u064e\u0646\u0634\u064e\u0631\u064e\u0647\u064f\u06e5",translation:"kemudian jika Dia menghendaki, Dia membangkitkannya kembali"},{id:23,text:"\u0643\u064e\u0644\u0651\u064e\u0627 \u0644\u064e\u0645\u0651\u064e\u0627 \u064a\u064e\u0642\u06e1\u0636\u0650 \u0645\u064e\u0627\u0653 \u0623\u064e\u0645\u064e\u0631\u064e\u0647\u064f\u06e5",translation:"Sekali-kali jangan (begitu)! Dia (manusia) itu belum melaksanakan apa yang Dia (Allah) perintahkan kepadanya"},{id:24,text:"\u0641\u064e\u0644\u06e1\u064a\u064e\u0646\u0638\u064f\u0631\u0650 \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0637\u064e\u0639\u064e\u0627\u0645\u0650\u0647\u0650\u06e6\u0653",translation:"Maka hendaklah manusia itu memperhatikan makanannya"},{id:25,text:"\u0623\u064e\u0646\u0651\u064e\u0627 \u0635\u064e\u0628\u064e\u0628\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0645\u064e\u0627\u0653\u0621\u064e \u0635\u064e\u0628\u0651\u0657\u0627",translation:"Kamilah yang telah mencurahkan air melimpah (dari langit)"},{id:26,text:"\u062b\u064f\u0645\u0651\u064e \u0634\u064e\u0642\u064e\u0642\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064e \u0634\u064e\u0642\u0651\u0657\u0627",translation:"kemudian Kami belah bumi dengan sebaik-baiknya"},{id:27,text:"\u0641\u064e\u0623\u064e\u0646\u06e2\u0628\u064e\u062a\u06e1\u0646\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u062d\u064e\u0628\u0651\u0657\u0627",translation:"lalu di sana Kami tumbuhkan biji-bijian"},{id:28,text:"\u0648\u064e\u0639\u0650\u0646\u064e\u0628\u0657\u0627 \u0648\u064e\u0642\u064e\u0636\u06e1\u0628\u0657\u0627",translation:"dan anggur dan sayur-sayuran"},{id:29,text:"\u0648\u064e\u0632\u064e\u064a\u06e1\u062a\u064f\u0648\u0646\u0657\u0627 \u0648\u064e\u0646\u064e\u062e\u06e1\u0644\u0657\u0627",translation:"dan zaitun dan pohon kurma"},{id:30,text:"\u0648\u064e\u062d\u064e\u062f\u064e\u0627\u0653\u0626\u0650\u0642\u064e \u063a\u064f\u0644\u06e1\u0628\u0657\u0627",translation:"dan kebun-kebun (yang) rindang"},{id:31,text:"\u0648\u064e\u0641\u064e\u0670\u0643\u0650\u0647\u064e\u0629\u0657 \u0648\u064e\u0623\u064e\u0628\u0651\u0657\u0627",translation:"dan buah-buahan serta rerumputan"},{id:32,text:"\u0645\u0651\u064e\u062a\u064e\u0670\u0639\u0657\u0627 \u0644\u0651\u064e\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u0650\u0623\u064e\u0646\u06e1\u0639\u064e\u0670\u0645\u0650\u0643\u064f\u0645\u06e1",translation:"(Semua itu) untuk kesenanganmu dan untuk hewan-hewan ternakmu"},{id:33,text:"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u062a\u0650 \u0671\u0644\u0635\u0651\u064e\u0627\u0653\u062e\u0651\u064e\u0629\u064f",translation:"Maka apabila datang suara yang memekakkan (tiupan sangkakala yang kedua)"},{id:34,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064e\u0641\u0650\u0631\u0651\u064f \u0671\u0644\u06e1\u0645\u064e\u0631\u06e1\u0621\u064f \u0645\u0650\u0646\u06e1 \u0623\u064e\u062e\u0650\u064a\u0647\u0650",translation:"pada hari itu manusia lari dari saudaranya"},{id:35,text:"\u0648\u064e\u0623\u064f\u0645\u0651\u0650\u0647\u0650\u06e6 \u0648\u064e\u0623\u064e\u0628\u0650\u064a\u0647\u0650",translation:"dan dari ibu dan bapaknya"},{id:36,text:"\u0648\u064e\u0635\u064e\u0670\u062d\u0650\u0628\u064e\u062a\u0650\u0647\u0650\u06e6 \u0648\u064e\u0628\u064e\u0646\u0650\u064a\u0647\u0650",translation:"dan dari istri dan anak-anaknya"},{id:37,text:"\u0644\u0650\u0643\u064f\u0644\u0651\u0650 \u0671\u0645\u06e1\u0631\u0650\u064a\u0655\u0656 \u0645\u0651\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u0634\u064e\u0623\u06e1\u0646\u065e \u064a\u064f\u063a\u06e1\u0646\u0650\u064a\u0647\u0650",translation:"Setiap orang dari mereka pada hari itu mempunyai urusan yang menyibukkannya"},{id:38,text:"\u0648\u064f\u062c\u064f\u0648\u0647\u065e \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u0645\u0651\u064f\u0633\u06e1\u0641\u0650\u0631\u064e\u0629\u065e",translation:"Pada hari itu ada wajah-wajah yang berseri-seri"},{id:39,text:"\u0636\u064e\u0627\u062d\u0650\u0643\u064e\u0629\u065e \u0645\u0651\u064f\u0633\u06e1\u062a\u064e\u0628\u06e1\u0634\u0650\u0631\u064e\u0629\u065e",translation:"tertawa dan gembira ria"},{id:40,text:"\u0648\u064e\u0648\u064f\u062c\u064f\u0648\u0647\u065e \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u064d \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627 \u063a\u064e\u0628\u064e\u0631\u064e\u0629\u065e",translation:"dan pada hari itu ada (pula) wajah-wajah yang tertutup debu (suram)"},{id:41,text:"\u062a\u064e\u0631\u06e1\u0647\u064e\u0642\u064f\u0647\u064e\u0627 \u0642\u064e\u062a\u064e\u0631\u064e\u0629\u064c",translation:"tertutup oleh kegelapan (ditimpa kehinaan dan kesusahan)"},{id:42,text:"\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0643\u064e\u0641\u064e\u0631\u064e\u0629\u064f \u0671\u0644\u06e1\u0641\u064e\u062c\u064e\u0631\u064e\u0629\u064f",translation:"Mereka itulah orang-orang kafir yang durhaka"}]},{id:81,name:"\u0627\u0644\u062a\u0643\u0648\u064a\u0631",transliteration:"At-Takwir",translation:"Menggulung",type:"meccan",total_verses:29,verses:[{id:1,text:"\u0625\u0650\u0630\u064e\u0627 \u0671\u0644\u0634\u0651\u064e\u0645\u06e1\u0633\u064f \u0643\u064f\u0648\u0651\u0650\u0631\u064e\u062a\u06e1",translation:"Apabila matahari digulung"},{id:2,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0671\u0644\u0646\u0651\u064f\u062c\u064f\u0648\u0645\u064f \u0671\u0646\u0643\u064e\u062f\u064e\u0631\u064e\u062a\u06e1",translation:"dan apabila bintang-bintang berjatuhan"},{id:3,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0671\u0644\u06e1\u062c\u0650\u0628\u064e\u0627\u0644\u064f \u0633\u064f\u064a\u0651\u0650\u0631\u064e\u062a\u06e1",translation:"dan apabila gunung-gunung dihancurkan"},{id:4,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0671\u0644\u06e1\u0639\u0650\u0634\u064e\u0627\u0631\u064f \u0639\u064f\u0637\u0651\u0650\u0644\u064e\u062a\u06e1",translation:"dan apabila unta-unta yang bunting ditinggalkan (tidak terurus)"},{id:5,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0671\u0644\u06e1\u0648\u064f\u062d\u064f\u0648\u0634\u064f \u062d\u064f\u0634\u0650\u0631\u064e\u062a\u06e1",translation:"dan apabila binatang-binatang liar dikumpulkan"},{id:6,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0671\u0644\u06e1\u0628\u0650\u062d\u064e\u0627\u0631\u064f \u0633\u064f\u062c\u0651\u0650\u0631\u064e\u062a\u06e1",translation:"dan apabila lautan dipanaskan"},{id:7,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0671\u0644\u0646\u0651\u064f\u0641\u064f\u0648\u0633\u064f \u0632\u064f\u0648\u0651\u0650\u062c\u064e\u062a\u06e1",translation:"dan apabila roh-roh dipertemukan (dengan tubuh)"},{id:8,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u0621\u064f\u06e5\u062f\u064e\u0629\u064f \u0633\u064f\u0626\u0650\u0644\u064e\u062a\u06e1",translation:"dan apabila bayi-bayi perempuan yang dikubur hidup-hidup ditanya"},{id:9,text:"\u0628\u0650\u0623\u064e\u064a\u0651\u0650 \u0630\u064e\u0646\u06e2\u0628\u0656 \u0642\u064f\u062a\u0650\u0644\u064e\u062a\u06e1",translation:"karena dosa apa dia dibunuh"},{id:10,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0671\u0644\u0635\u0651\u064f\u062d\u064f\u0641\u064f \u0646\u064f\u0634\u0650\u0631\u064e\u062a\u06e1",translation:"Dan apabila lembaran-lembaran (catatan amal) telah dibuka lebar-lebar"},{id:11,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u064f \u0643\u064f\u0634\u0650\u0637\u064e\u062a\u06e1",translation:"dan apabila langit dilenyapkan"},{id:12,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0671\u0644\u06e1\u062c\u064e\u062d\u0650\u064a\u0645\u064f \u0633\u064f\u0639\u0651\u0650\u0631\u064e\u062a\u06e1",translation:"dan apabila neraka Jahim dinyalakan"},{id:13,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0671\u0644\u06e1\u062c\u064e\u0646\u0651\u064e\u0629\u064f \u0623\u064f\u0632\u06e1\u0644\u0650\u0641\u064e\u062a\u06e1",translation:"dan apabila surga didekatkan"},{id:14,text:"\u0639\u064e\u0644\u0650\u0645\u064e\u062a\u06e1 \u0646\u064e\u0641\u06e1\u0633\u065e \u0645\u0651\u064e\u0627\u0653 \u0623\u064e\u062d\u06e1\u0636\u064e\u0631\u064e\u062a\u06e1",translation:"setiap jiwa akan mengetahui apa yang telah dikerjakannya"},{id:15,text:"\u0641\u064e\u0644\u064e\u0627\u0653 \u0623\u064f\u0642\u06e1\u0633\u0650\u0645\u064f \u0628\u0650\u0671\u0644\u06e1\u062e\u064f\u0646\u0651\u064e\u0633\u0650",translation:"Aku bersumpah demi bintang-bintang"},{id:16,text:"\u0671\u0644\u06e1\u062c\u064e\u0648\u064e\u0627\u0631\u0650 \u0671\u0644\u06e1\u0643\u064f\u0646\u0651\u064e\u0633\u0650",translation:"yang beredar dan terbenam"},{id:17,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u0650 \u0625\u0650\u0630\u064e\u0627 \u0639\u064e\u0633\u06e1\u0639\u064e\u0633\u064e",translation:"demi malam apabila telah larut"},{id:18,text:"\u0648\u064e\u0671\u0644\u0635\u0651\u064f\u0628\u06e1\u062d\u0650 \u0625\u0650\u0630\u064e\u0627 \u062a\u064e\u0646\u064e\u0641\u0651\u064e\u0633\u064e",translation:"dan demi subuh apabila telah menyinsing"},{id:19,text:"\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0642\u064e\u0648\u06e1\u0644\u064f \u0631\u064e\u0633\u064f\u0648\u0644\u0656 \u0643\u064e\u0631\u0650\u064a\u0645\u0656",translation:"sesungguhnya (Alquran) itu benar-benar firman (Allah yang dibawa oleh) utusan yang mulia (Jibril)"},{id:20,text:"\u0630\u0650\u064a \u0642\u064f\u0648\u0651\u064e\u0629\u064d \u0639\u0650\u0646\u062f\u064e \u0630\u0650\u064a \u0671\u0644\u06e1\u0639\u064e\u0631\u06e1\u0634\u0650 \u0645\u064e\u0643\u0650\u064a\u0646\u0656",translation:"yang memiliki kekuatan, memiliki kedudukan tinggi di sisi (Allah) yang memiliki Arasy"},{id:21,text:"\u0645\u0651\u064f\u0637\u064e\u0627\u0639\u0656 \u062b\u064e\u0645\u0651\u064e \u0623\u064e\u0645\u0650\u064a\u0646\u0656",translation:"yang di sana (di alam malaikat) ditaati dan dipercaya"},{id:22,text:"\u0648\u064e\u0645\u064e\u0627 \u0635\u064e\u0627\u062d\u0650\u0628\u064f\u0643\u064f\u0645 \u0628\u0650\u0645\u064e\u062c\u06e1\u0646\u064f\u0648\u0646\u0656",translation:"Dan temanmu (Muhammad) itu bukanlah orang gila"},{id:23,text:"\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u06e1 \u0631\u064e\u0621\u064e\u0627\u0647\u064f \u0628\u0650\u0671\u0644\u06e1\u0623\u064f\u0641\u064f\u0642\u0650 \u0671\u0644\u06e1\u0645\u064f\u0628\u0650\u064a\u0646\u0650",translation:"Dan sungguh, dia (Muhammad) telah melihatnya (Jibril) di ufuk yang terang"},{id:24,text:"\u0648\u064e\u0645\u064e\u0627 \u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u0628\u0650 \u0628\u0650\u0636\u064e\u0646\u0650\u064a\u0646\u0656",translation:"Dan Dia (Muhammad) bukanlah seorang yang kikir (enggan) untuk menerangkan yang gaib"},{id:25,text:"\u0648\u064e\u0645\u064e\u0627 \u0647\u064f\u0648\u064e \u0628\u0650\u0642\u064e\u0648\u06e1\u0644\u0650 \u0634\u064e\u064a\u06e1\u0637\u064e\u0670\u0646\u0656 \u0631\u0651\u064e\u062c\u0650\u064a\u0645\u0656",translation:"Dan (Alquran) itu bukanlah perkataan setan yang terkutuk"},{id:26,text:"\u0641\u064e\u0623\u064e\u064a\u06e1\u0646\u064e \u062a\u064e\u0630\u06e1\u0647\u064e\u0628\u064f\u0648\u0646\u064e",translation:"maka ke manakah kamu akan pergi"},{id:27,text:"\u0625\u0650\u0646\u06e1 \u0647\u064f\u0648\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0630\u0650\u0643\u06e1\u0631\u065e \u0644\u0651\u0650\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"(Alquran) itu tidak lain adalah peringatan bagi seluruh alam"},{id:28,text:"\u0644\u0650\u0645\u064e\u0646 \u0634\u064e\u0627\u0653\u0621\u064e \u0645\u0650\u0646\u0643\u064f\u0645\u06e1 \u0623\u064e\u0646 \u064a\u064e\u0633\u06e1\u062a\u064e\u0642\u0650\u064a\u0645\u064e",translation:"(yaitu) bagi siapa di antara kamu yang menghendaki menempuh jalan yang lurus"},{id:29,text:"\u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0634\u064e\u0627\u0653\u0621\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0631\u064e\u0628\u0651\u064f \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"Dan kamu tidak dapat menghendaki (menempuh jalan itu) kecuali apabila dikehendaki Allah, Tuhan seluruh alam"}]},{id:82,name:"\u0627\u0644\u0625\u0646\u0641\u0637\u0627\u0631",transliteration:"Al-Infitar",translation:"Terbelah",type:"meccan",total_verses:19,verses:[{id:1,text:"\u0625\u0650\u0630\u064e\u0627 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u064f \u0671\u0646\u0641\u064e\u0637\u064e\u0631\u064e\u062a\u06e1",translation:"Apabila langit terbelah"},{id:2,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0671\u0644\u06e1\u0643\u064e\u0648\u064e\u0627\u0643\u0650\u0628\u064f \u0671\u0646\u062a\u064e\u062b\u064e\u0631\u064e\u062a\u06e1",translation:"dan apabila bintang-bintang jatuh berserakan"},{id:3,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0671\u0644\u06e1\u0628\u0650\u062d\u064e\u0627\u0631\u064f \u0641\u064f\u062c\u0651\u0650\u0631\u064e\u062a\u06e1",translation:"dan apabila lautan dijadikan meluap"},{id:4,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0671\u0644\u06e1\u0642\u064f\u0628\u064f\u0648\u0631\u064f \u0628\u064f\u0639\u06e1\u062b\u0650\u0631\u064e\u062a\u06e1",translation:"dan apabila kuburan-kuburan dibongkar"},{id:5,text:"\u0639\u064e\u0644\u0650\u0645\u064e\u062a\u06e1 \u0646\u064e\u0641\u06e1\u0633\u065e \u0645\u0651\u064e\u0627 \u0642\u064e\u062f\u0651\u064e\u0645\u064e\u062a\u06e1 \u0648\u064e\u0623\u064e\u062e\u0651\u064e\u0631\u064e\u062a\u06e1",translation:"(maka) setiap jiwa akan mengetahui apa yang telah dikerjakan dan yang dilalaikan(nya)"},{id:6,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064f \u0645\u064e\u0627 \u063a\u064e\u0631\u0651\u064e\u0643\u064e \u0628\u0650\u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0671\u0644\u06e1\u0643\u064e\u0631\u0650\u064a\u0645\u0650",translation:"Wahai manusia! Apakah yang telah memperdayakan kamu (berbuat durhaka) terhadap Tuhanmu Yang Maha Pengasih"},{id:7,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e\u0643\u064e \u0641\u064e\u0633\u064e\u0648\u0651\u064e\u0649\u0670\u0643\u064e \u0641\u064e\u0639\u064e\u062f\u064e\u0644\u064e\u0643\u064e",translation:"Yang telah menciptakanmu lalu menyempurnakan kejadianmu dan menjadikan (susunan tubuh)mu seimbang"},{id:8,text:"\u0641\u0650\u064a\u0653 \u0623\u064e\u064a\u0651\u0650 \u0635\u064f\u0648\u0631\u064e\u0629\u0656 \u0645\u0651\u064e\u0627 \u0634\u064e\u0627\u0653\u0621\u064e \u0631\u064e\u0643\u0651\u064e\u0628\u064e\u0643\u064e",translation:"dalam bentuk apa saja yang dikehendaki, Dia menyusun tubuhmu"},{id:9,text:"\u0643\u064e\u0644\u0651\u064e\u0627 \u0628\u064e\u0644\u06e1 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u062f\u0651\u0650\u064a\u0646\u0650",translation:"Sekali-kali jangan begitu! Bahkan kamu mendustakan hari pembalasan"},{id:10,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0643\u064f\u0645\u06e1 \u0644\u064e\u062d\u064e\u0670\u0641\u0650\u0638\u0650\u064a\u0646\u064e",translation:"Dan sesungguhnya bagi kamu ada (malaikat-malaikat) yang mengawasi (pekerjaanmu)"},{id:11,text:"\u0643\u0650\u0631\u064e\u0627\u0645\u0657\u0627 \u0643\u064e\u0670\u062a\u0650\u0628\u0650\u064a\u0646\u064e",translation:"yang mulia (di sisi Allah) dan yang mencatat (perbuatanmu)"},{id:12,text:"\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u062a\u064e\u0641\u06e1\u0639\u064e\u0644\u064f\u0648\u0646\u064e",translation:"mereka mengetahui apa yang kamu kerjakan"},{id:13,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0623\u064e\u0628\u06e1\u0631\u064e\u0627\u0631\u064e \u0644\u064e\u0641\u0650\u064a \u0646\u064e\u0639\u0650\u064a\u0645\u0656",translation:"Sesungguhnya orang-orang yang berbakti benar-benar berada dalam (surga yang penuh) kenikmatan"},{id:14,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0641\u064f\u062c\u0651\u064e\u0627\u0631\u064e \u0644\u064e\u0641\u0650\u064a \u062c\u064e\u062d\u0650\u064a\u0645\u0656",translation:"dan sesungguhnya orang-orang yang durhaka benar-benar berada dalam neraka"},{id:15,text:"\u064a\u064e\u0635\u06e1\u0644\u064e\u0648\u06e1\u0646\u064e\u0647\u064e\u0627 \u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u0650",translation:"Mereka masuk ke dalamnya pada hari pembalasan"},{id:16,text:"\u0648\u064e\u0645\u064e\u0627 \u0647\u064f\u0645\u06e1 \u0639\u064e\u0646\u06e1\u0647\u064e\u0627 \u0628\u0650\u063a\u064e\u0627\u0653\u0626\u0650\u0628\u0650\u064a\u0646\u064e",translation:"Dan mereka tidak mungkin keluar dari neraka itu"},{id:17,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u062f\u06e1\u0631\u064e\u0649\u0670\u0643\u064e \u0645\u064e\u0627 \u064a\u064e\u0648\u06e1\u0645\u064f \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u0650",translation:"Dan tahukah kamu apakah hari pembalasan itu"},{id:18,text:"\u062b\u064f\u0645\u0651\u064e \u0645\u064e\u0627\u0653 \u0623\u064e\u062f\u06e1\u0631\u064e\u0649\u0670\u0643\u064e \u0645\u064e\u0627 \u064a\u064e\u0648\u06e1\u0645\u064f \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u0650",translation:"Sekali lagi, tahukah kamu apakah hari pembalasan itu"},{id:19,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u0644\u064e\u0627 \u062a\u064e\u0645\u06e1\u0644\u0650\u0643\u064f \u0646\u064e\u0641\u06e1\u0633\u065e \u0644\u0651\u0650\u0646\u064e\u0641\u06e1\u0633\u0656 \u0634\u064e\u064a\u06e1\u0640\u0654\u0657\u0627\u06d6 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0645\u06e1\u0631\u064f \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u0644\u0651\u0650\u0644\u0651\u064e\u0647\u0650",translation:"(Yaitu) pada hari (ketika) seseorang sama sekali tidak berdaya (menolong) orang lain. Dan segala urusan pada hari itu dalam kekuasaan Allah"}]},{id:83,name:"\u0627\u0644\u0645\u0637\u0641\u0641\u064a\u0646",transliteration:"Al-Mutaffifin",translation:"Orang-orang Curang",type:"meccan",total_verses:36,verses:[{id:1,text:"\u0648\u064e\u064a\u06e1\u0644\u065e \u0644\u0651\u0650\u0644\u06e1\u0645\u064f\u0637\u064e\u0641\u0651\u0650\u0641\u0650\u064a\u0646\u064e",translation:"Celakalah bagi orang-orang yang curang (dalam menakar dan menimbang)"},{id:2,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0625\u0650\u0630\u064e\u0627 \u0671\u0643\u06e1\u062a\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u064a\u064e\u0633\u06e1\u062a\u064e\u0648\u06e1\u0641\u064f\u0648\u0646\u064e",translation:"(yaitu) orang-orang yang apabila menerima takaran dari orang lain mereka minta dicukupkan"},{id:3,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0643\u064e\u0627\u0644\u064f\u0648\u0647\u064f\u0645\u06e1 \u0623\u064e\u0648 \u0648\u0651\u064e\u0632\u064e\u0646\u064f\u0648\u0647\u064f\u0645\u06e1 \u064a\u064f\u062e\u06e1\u0633\u0650\u0631\u064f\u0648\u0646\u064e",translation:"dan apabila mereka menakar atau menimbang (untuk orang lain), mereka mengurangi"},{id:4,text:"\u0623\u064e\u0644\u064e\u0627 \u064a\u064e\u0638\u064f\u0646\u0651\u064f \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u0628\u06e1\u0639\u064f\u0648\u062b\u064f\u0648\u0646\u064e",translation:"Tidakkah mereka itu mengira, bahwa sesungguhnya mereka akan dibangkitkan"},{id:5,text:"\u0644\u0650\u064a\u064e\u0648\u06e1\u0645\u064d \u0639\u064e\u0638\u0650\u064a\u0645\u0656",translation:"pada suatu hari yang besar"},{id:6,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064e\u0642\u064f\u0648\u0645\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0644\u0650\u0631\u064e\u0628\u0651\u0650 \u0671\u0644\u06e1\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e",translation:"(yaitu) pada hari (ketika) semua orang bangkit menghadap Tuhan seluruh alam"},{id:7,text:"\u0643\u064e\u0644\u0651\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e \u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0671\u0644\u06e1\u0641\u064f\u062c\u0651\u064e\u0627\u0631\u0650 \u0644\u064e\u0641\u0650\u064a \u0633\u0650\u062c\u0651\u0650\u064a\u0646\u0656",translation:"Sekali-kali jangan begitu! Sesungguhnya catatan orang yang durhaka benar-benar tersimpan dalam Sijj\u012bn"},{id:8,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u062f\u06e1\u0631\u064e\u0649\u0670\u0643\u064e \u0645\u064e\u0627 \u0633\u0650\u062c\u0651\u0650\u064a\u0646\u065e",translation:"Dan tahukah engkau apakah Sijj\u012bn itu"},{id:9,text:"\u0643\u0650\u062a\u064e\u0670\u0628\u065e \u0645\u0651\u064e\u0631\u06e1\u0642\u064f\u0648\u0645\u065e",translation:"(Yaitu) Kitab yang berisi catatan (amal)"},{id:10,text:"\u0648\u064e\u064a\u06e1\u0644\u065e \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u0644\u0651\u0650\u0644\u06e1\u0645\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u0650\u064a\u0646\u064e",translation:"Celakalah pada hari itu, bagi orang-orang yang mendustakan"},{id:11,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f\u0648\u0646\u064e \u0628\u0650\u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u0650",translation:"(yaitu) orang-orang yang mendustakannya (hari pembalasan)"},{id:12,text:"\u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f \u0628\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0643\u064f\u0644\u0651\u064f \u0645\u064f\u0639\u06e1\u062a\u064e\u062f\u064d \u0623\u064e\u062b\u0650\u064a\u0645\u064d",translation:"Dan tidak ada yang mendustakannya (hari pembalasan) kecuali setiap orang yang melampaui batas dan berdosa"},{id:13,text:"\u0625\u0650\u0630\u064e\u0627 \u062a\u064f\u062a\u06e1\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0621\u064e\u0627\u064a\u064e\u0670\u062a\u064f\u0646\u064e\u0627 \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0633\u064e\u0670\u0637\u0650\u064a\u0631\u064f \u0671\u0644\u06e1\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",translation:"yang apabila dibacakan kepadanya ayat-ayat Kami, dia berkata, \"Itu adalah dongeng orang-orang dahulu"},{id:14,text:"\u0643\u064e\u0644\u0651\u064e\u0627\u06d6 \u0628\u064e\u0644\u06e1\u06dc \u0631\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645 \u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0643\u06e1\u0633\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Sekali-kali tidak! Bahkan apa yang mereka kerjakan itu telah menutupi hati mereka"},{id:15,text:"\u0643\u064e\u0644\u0651\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u0644\u0651\u064e\u0645\u064e\u062d\u06e1\u062c\u064f\u0648\u0628\u064f\u0648\u0646\u064e",translation:"(Sekali-kali tidak!901) Sesungguhnya mereka pada hari itu benar-benar terhalang dari (melihat) Tuhannya"},{id:16,text:"\u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0635\u064e\u0627\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u062c\u064e\u062d\u0650\u064a\u0645\u0650",translation:"Kemudian, sesungguhnya mereka benar-benar masuk neraka"},{id:17,text:"\u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0642\u064e\u0627\u0644\u064f \u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0643\u064f\u0646\u062a\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6 \u062a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f\u0648\u0646\u064e",translation:"Kemudian, dikatakan (kepada mereka), \"Inilah (azab) yang dahulu kamu dustakan"},{id:18,text:"\u0643\u064e\u0644\u0651\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e \u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0671\u0644\u06e1\u0623\u064e\u0628\u06e1\u0631\u064e\u0627\u0631\u0650 \u0644\u064e\u0641\u0650\u064a \u0639\u0650\u0644\u0651\u0650\u064a\u0651\u0650\u064a\u0646\u064e",translation:"Sekali-kali tidak! Sesungguhnya catatan orang-orang yang berbakti benar-benar tersimpan dalam 'Illiyy\u012bn"},{id:19,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u062f\u06e1\u0631\u064e\u0649\u0670\u0643\u064e \u0645\u064e\u0627 \u0639\u0650\u0644\u0651\u0650\u064a\u0651\u064f\u0648\u0646\u064e",translation:"Dan tahukah engkau apakah 'Illiyy\u012bn itu"},{id:20,text:"\u0643\u0650\u062a\u064e\u0670\u0628\u065e \u0645\u0651\u064e\u0631\u06e1\u0642\u064f\u0648\u0645\u065e",translation:"(Yaitu) Kitab yang berisi catatan (amal)"},{id:21,text:"\u064a\u064e\u0634\u06e1\u0647\u064e\u062f\u064f\u0647\u064f \u0671\u0644\u06e1\u0645\u064f\u0642\u064e\u0631\u0651\u064e\u0628\u064f\u0648\u0646\u064e",translation:"yang disaksikan oleh (malaikat-malaikat) yang didekatkan (kepada Allah)"},{id:22,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0623\u064e\u0628\u06e1\u0631\u064e\u0627\u0631\u064e \u0644\u064e\u0641\u0650\u064a \u0646\u064e\u0639\u0650\u064a\u0645\u064d",translation:"Sesungguhnya orang-orang yang berbakti benar-benar berada dalam (surga yang penuh) kenikmatan"},{id:23,text:"\u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0623\u064e\u0631\u064e\u0627\u0653\u0626\u0650\u0643\u0650 \u064a\u064e\u0646\u0638\u064f\u0631\u064f\u0648\u0646\u064e",translation:"mereka (duduk) di atas dipan-dipan melepas pandangan"},{id:24,text:"\u062a\u064e\u0639\u06e1\u0631\u0650\u0641\u064f \u0641\u0650\u064a \u0648\u064f\u062c\u064f\u0648\u0647\u0650\u0647\u0650\u0645\u06e1 \u0646\u064e\u0636\u06e1\u0631\u064e\u0629\u064e \u0671\u0644\u0646\u0651\u064e\u0639\u0650\u064a\u0645\u0650",translation:"Kamu dapat mengetahui dari wajah mereka kesenangan hidup yang penuh kenikmatan"},{id:25,text:"\u064a\u064f\u0633\u06e1\u0642\u064e\u0648\u06e1\u0646\u064e \u0645\u0650\u0646 \u0631\u0651\u064e\u062d\u0650\u064a\u0642\u0656 \u0645\u0651\u064e\u062e\u06e1\u062a\u064f\u0648\u0645\u064d",translation:"Mereka diberi minum dari khamar murni (tidak memabukkan) yang (tempatnya) masih dilak (disegel)"},{id:26,text:"\u062e\u0650\u062a\u064e\u0670\u0645\u064f\u0647\u064f\u06e5 \u0645\u0650\u0633\u06e1\u0643\u065e\u06da \u0648\u064e\u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u0644\u06e1\u064a\u064e\u062a\u064e\u0646\u064e\u0627\u0641\u064e\u0633\u0650 \u0671\u0644\u06e1\u0645\u064f\u062a\u064e\u0646\u064e\u0670\u0641\u0650\u0633\u064f\u0648\u0646\u064e",translation:"laknya dari kasturi. Dan untuk yang demikian itu hendaknya orang berlomba-lomba"},{id:27,text:"\u0648\u064e\u0645\u0650\u0632\u064e\u0627\u062c\u064f\u0647\u064f\u06e5 \u0645\u0650\u0646 \u062a\u064e\u0633\u06e1\u0646\u0650\u064a\u0645\u064d",translation:"Dan campurannya dari tasn\u012bm"},{id:28,text:"\u0639\u064e\u064a\u06e1\u0646\u0657\u0627 \u064a\u064e\u0634\u06e1\u0631\u064e\u0628\u064f \u0628\u0650\u0647\u064e\u0627 \u0671\u0644\u06e1\u0645\u064f\u0642\u064e\u0631\u0651\u064e\u0628\u064f\u0648\u0646\u064e",translation:"(yaitu) mata air yang diminum oleh mereka yang dekat (kepada Allah)"},{id:29,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u062c\u06e1\u0631\u064e\u0645\u064f\u0648\u0627\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0636\u06e1\u062d\u064e\u0643\u064f\u0648\u0646\u064e",translation:"Sesungguhnya orang-orang yang berdosa, adalah mereka yang dahulu menertawakan orang-orang yang beriman"},{id:30,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0631\u0651\u064f\u0648\u0627\u0652 \u0628\u0650\u0647\u0650\u0645\u06e1 \u064a\u064e\u062a\u064e\u063a\u064e\u0627\u0645\u064e\u0632\u064f\u0648\u0646\u064e",translation:"Dan apabila mereka (orang-orang yang beriman) melintas di hadapan mereka, mereka saling mengedip-ngedipkan matanya"},{id:31,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0671\u0646\u0642\u064e\u0644\u064e\u0628\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0647\u06e1\u0644\u0650\u0647\u0650\u0645\u064f \u0671\u0646\u0642\u064e\u0644\u064e\u0628\u064f\u0648\u0627\u0652 \u0641\u064e\u0643\u0650\u0647\u0650\u064a\u0646\u064e",translation:"dan apabila kembali kepada kaumnya, mereka kembali dengan gembira ria"},{id:32,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0631\u064e\u0623\u064e\u0648\u06e1\u0647\u064f\u0645\u06e1 \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0640\u0670\u0653\u0624\u064f\u0644\u064e\u0627\u0653\u0621\u0650 \u0644\u064e\u0636\u064e\u0627\u0653\u0644\u0651\u064f\u0648\u0646\u064e",translation:"Dan apabila mereka melihat (orang-orang mukmin), mereka mengatakan, \"Sesungguhnya mereka benar-benar orang-orang sesat"},{id:33,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0631\u06e1\u0633\u0650\u0644\u064f\u0648\u0627\u0652 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u062d\u064e\u0670\u0641\u0650\u0638\u0650\u064a\u0646\u064e",translation:"padahal (orang-orang yang berdosa itu), mereka tidak diutus sebagai penjaga (orang-orang mukmin)"},{id:34,text:"\u0641\u064e\u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0643\u064f\u0641\u0651\u064e\u0627\u0631\u0650 \u064a\u064e\u0636\u06e1\u062d\u064e\u0643\u064f\u0648\u0646\u064e",translation:"Maka pada hari ini, orang-orang yang beriman yang menertawakan orang-orang kafir"},{id:35,text:"\u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0623\u064e\u0631\u064e\u0627\u0653\u0626\u0650\u0643\u0650 \u064a\u064e\u0646\u0638\u064f\u0631\u064f\u0648\u0646\u064e",translation:"mereka (duduk) di atas dipan-dipan melepas pandangan"},{id:36,text:"\u0647\u064e\u0644\u06e1 \u062b\u064f\u0648\u0651\u0650\u0628\u064e \u0671\u0644\u06e1\u0643\u064f\u0641\u0651\u064e\u0627\u0631\u064f \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u0652 \u064a\u064e\u0641\u06e1\u0639\u064e\u0644\u064f\u0648\u0646\u064e",translation:"Apakah orang-orang kafir itu diberi balasan (hukuman) terhadap apa yang telah mereka perbuat"}]},{id:84,name:"\u0627\u0644\u0625\u0646\u0634\u0642\u0627\u0642",transliteration:"Al-Inshiqaq",translation:"Terbelah",type:"meccan",total_verses:25,verses:[{id:1,text:"\u0625\u0650\u0630\u064e\u0627 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u064f \u0671\u0646\u0634\u064e\u0642\u0651\u064e\u062a\u06e1",translation:"Apabila langit terbelah"},{id:2,text:"\u0648\u064e\u0623\u064e\u0630\u0650\u0646\u064e\u062a\u06e1 \u0644\u0650\u0631\u064e\u0628\u0651\u0650\u0647\u064e\u0627 \u0648\u064e\u062d\u064f\u0642\u0651\u064e\u062a\u06e1",translation:"dan patuh kepada Tuhannya, dan sudah semestinya patuh"},{id:3,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064f \u0645\u064f\u062f\u0651\u064e\u062a\u06e1",translation:"dan apabila bumi diratakan"},{id:4,text:"\u0648\u064e\u0623\u064e\u0644\u06e1\u0642\u064e\u062a\u06e1 \u0645\u064e\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u062a\u064e\u062e\u064e\u0644\u0651\u064e\u062a\u06e1",translation:"dan memuntahkan apa yang ada di dalamnya dan menjadi kosong"},{id:5,text:"\u0648\u064e\u0623\u064e\u0630\u0650\u0646\u064e\u062a\u06e1 \u0644\u0650\u0631\u064e\u0628\u0651\u0650\u0647\u064e\u0627 \u0648\u064e\u062d\u064f\u0642\u0651\u064e\u062a\u06e1",translation:"dan patuh kepada Tuhannya, dan sudah semestinya patuh"},{id:6,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064f \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0643\u064e\u0627\u062f\u0650\u062d\u064c \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0643\u064e\u062f\u06e1\u062d\u0657\u0627 \u0641\u064e\u0645\u064f\u0644\u064e\u0670\u0642\u0650\u064a\u0647\u0650",translation:"Wahai manusia! Sesungguhnya kamu telah bekerja keras menuju Tuhanmu, maka kamu akan menemui-Nya"},{id:7,text:"\u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0645\u064e\u0646\u06e1 \u0623\u064f\u0648\u062a\u0650\u064a\u064e \u0643\u0650\u062a\u064e\u0670\u0628\u064e\u0647\u064f\u06e5 \u0628\u0650\u064a\u064e\u0645\u0650\u064a\u0646\u0650\u0647\u0650\u06e6",translation:"Maka adapun orang yang catatanya diberikan dari sebelah kanannya"},{id:8,text:"\u0641\u064e\u0633\u064e\u0648\u06e1\u0641\u064e \u064a\u064f\u062d\u064e\u0627\u0633\u064e\u0628\u064f \u062d\u0650\u0633\u064e\u0627\u0628\u0657\u0627 \u064a\u064e\u0633\u0650\u064a\u0631\u0657\u0627",translation:"maka dia akan diperiksa dengan pemeriksaan yang mudah"},{id:9,text:"\u0648\u064e\u064a\u064e\u0646\u0642\u064e\u0644\u0650\u0628\u064f \u0625\u0650\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0647\u06e1\u0644\u0650\u0647\u0650\u06e6 \u0645\u064e\u0633\u06e1\u0631\u064f\u0648\u0631\u0657\u0627",translation:"dan dia akan kembali kepada keluarganya (yang sama-sama beriman) dengan gembira"},{id:10,text:"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0645\u064e\u0646\u06e1 \u0623\u064f\u0648\u062a\u0650\u064a\u064e \u0643\u0650\u062a\u064e\u0670\u0628\u064e\u0647\u064f\u06e5 \u0648\u064e\u0631\u064e\u0627\u0653\u0621\u064e \u0638\u064e\u0647\u06e1\u0631\u0650\u0647\u0650\u06e6",translation:"Dan adapun orang yang catatannya diberikan dari arah belakang"},{id:11,text:"\u0641\u064e\u0633\u064e\u0648\u06e1\u0641\u064e \u064a\u064e\u062f\u06e1\u0639\u064f\u0648\u0627\u0652 \u062b\u064f\u0628\u064f\u0648\u0631\u0657\u0627",translation:"maka dia akan berteriak, \"Celakalah aku"},{id:12,text:"\u0648\u064e\u064a\u064e\u0635\u06e1\u0644\u064e\u0649\u0670 \u0633\u064e\u0639\u0650\u064a\u0631\u064b\u0627",translation:"Dan dia akan masuk ke dalam api yang menyala-nyala (neraka)"},{id:13,text:"\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0643\u064e\u0627\u0646\u064e \u0641\u0650\u064a\u0653 \u0623\u064e\u0647\u06e1\u0644\u0650\u0647\u0650\u06e6 \u0645\u064e\u0633\u06e1\u0631\u064f\u0648\u0631\u064b\u0627",translation:"Sungguh, dia dahulu (di dunia) bergembira di kalangan keluarganya (yang sama-sama kafir)"},{id:14,text:"\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0638\u064e\u0646\u0651\u064e \u0623\u064e\u0646 \u0644\u0651\u064e\u0646 \u064a\u064e\u062d\u064f\u0648\u0631\u064e",translation:"Sesungguhnya dia mengira bahwa dia tidak akan kembali (kepada Tuhannya)"},{id:15,text:"\u0628\u064e\u0644\u064e\u0649\u0670\u0653\u06da \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u06e5 \u0643\u064e\u0627\u0646\u064e \u0628\u0650\u0647\u0650\u06e6 \u0628\u064e\u0635\u0650\u064a\u0631\u0657\u0627",translation:"Tidak demikian, sesungguhnya Tuhannya selalu melihatnya"},{id:16,text:"\u0641\u064e\u0644\u064e\u0627\u0653 \u0623\u064f\u0642\u06e1\u0633\u0650\u0645\u064f \u0628\u0650\u0671\u0644\u0634\u0651\u064e\u0641\u064e\u0642\u0650",translation:"Maka Aku bersumpah demi cahaya merah pada waktu senja"},{id:17,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u0650 \u0648\u064e\u0645\u064e\u0627 \u0648\u064e\u0633\u064e\u0642\u064e",translation:"demi malam dan apa yang diselubunginya"},{id:18,text:"\u0648\u064e\u0671\u0644\u06e1\u0642\u064e\u0645\u064e\u0631\u0650 \u0625\u0650\u0630\u064e\u0627 \u0671\u062a\u0651\u064e\u0633\u064e\u0642\u064e",translation:"demi bulan apabila jadi purnama"},{id:19,text:"\u0644\u064e\u062a\u064e\u0631\u06e1\u0643\u064e\u0628\u064f\u0646\u0651\u064e \u0637\u064e\u0628\u064e\u0642\u064b\u0627 \u0639\u064e\u0646 \u0637\u064e\u0628\u064e\u0642\u0656",translation:"sungguh, akan kamu jalani tingkat demi tingkat (dalam kehidupan)"},{id:20,text:"\u0641\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0644\u064e\u0627 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0646\u064e",translation:"Maka mengapa mereka tidak mau beriman"},{id:21,text:"\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u064f\u0631\u0650\u0626\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u064f \u0671\u0644\u06e1\u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u064f \u0644\u064e\u0627 \u064a\u064e\u0633\u06e1\u062c\u064f\u062f\u064f\u0648\u0646\u064e\u06e4\u06e9",translation:"Dan apabila Alquran dibacakan kepada mereka, mereka tidak (mau) bersujud"},{id:22,text:"\u0628\u064e\u0644\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u064a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f\u0648\u0646\u064e",translation:"bahkan orang-orang kafir itu mendustakan-(nya)"},{id:23,text:"\u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u064a\u064f\u0648\u0639\u064f\u0648\u0646\u064e",translation:"Dan Allah lebih mengetahui apa yang mereka sembunyikan (dalam hati mereka)"},{id:24,text:"\u0641\u064e\u0628\u064e\u0634\u0651\u0650\u0631\u06e1\u0647\u064f\u0645 \u0628\u0650\u0639\u064e\u0630\u064e\u0627\u0628\u064d \u0623\u064e\u0644\u0650\u064a\u0645\u064d",translation:"Maka sampaikanlah kepada mereka (ancaman) azab yang pedih"},{id:25,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0644\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u062c\u06e1\u0631\u064c \u063a\u064e\u064a\u06e1\u0631\u064f \u0645\u064e\u0645\u06e1\u0646\u064f\u0648\u0646\u0650\u06ed",translation:"kecuali orang-orang yang beriman dan mengerjakan kebajikan, mereka akan mendapat pahala yang tidak putus-putusnya"}]},{id:85,name:"\u0627\u0644\u0628\u0631\u0648\u062c",transliteration:"Al-Buruj",translation:"Gugusan Bintang",type:"meccan",total_verses:22,verses:[{id:1,text:"\u0648\u064e\u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0630\u064e\u0627\u062a\u0650 \u0671\u0644\u06e1\u0628\u064f\u0631\u064f\u0648\u062c\u0650",translation:"Demi langit yang mempunyai gugusan bintang"},{id:2,text:"\u0648\u064e\u0671\u0644\u06e1\u064a\u064e\u0648\u06e1\u0645\u0650 \u0671\u0644\u06e1\u0645\u064e\u0648\u06e1\u0639\u064f\u0648\u062f\u0650",translation:"dan demi hari yang dijanjikan"},{id:3,text:"\u0648\u064e\u0634\u064e\u0627\u0647\u0650\u062f\u0656 \u0648\u064e\u0645\u064e\u0634\u06e1\u0647\u064f\u0648\u062f\u0656",translation:"Demi yang menyaksikan dan yang disaksikan"},{id:4,text:"\u0642\u064f\u062a\u0650\u0644\u064e \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u06e1\u0623\u064f\u062e\u06e1\u062f\u064f\u0648\u062f\u0650",translation:"Binasalah orang-orang yang membuat parit (yaitu para pembesar Najran di Yaman)"},{id:5,text:"\u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0630\u064e\u0627\u062a\u0650 \u0671\u0644\u06e1\u0648\u064e\u0642\u064f\u0648\u062f\u0650",translation:"yang berapi (yang mempunyai) kayu bakar"},{id:6,text:"\u0625\u0650\u0630\u06e1 \u0647\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627 \u0642\u064f\u0639\u064f\u0648\u062f\u065e",translation:"ketika mereka duduk di sekitarnya"},{id:7,text:"\u0648\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u064a\u064e\u0641\u06e1\u0639\u064e\u0644\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0634\u064f\u0647\u064f\u0648\u062f\u065e",translation:"sedang mereka menyaksikan apa yang mereka perbuat terhadap orang-orang mukmin"},{id:8,text:"\u0648\u064e\u0645\u064e\u0627 \u0646\u064e\u0642\u064e\u0645\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0646 \u064a\u064f\u0624\u06e1\u0645\u0650\u0646\u064f\u0648\u0627\u0652 \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u0639\u064e\u0632\u0650\u064a\u0632\u0650 \u0671\u0644\u06e1\u062d\u064e\u0645\u0650\u064a\u062f\u0650",translation:"Dan mereka menyiksa orang-orang mukmin itu hanya karena (orang-orang mukmin itu) beriman kepada Allah Yang Mahaperkasa, Maha Terpuji"},{id:9,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0644\u064e\u0647\u064f\u06e5 \u0645\u064f\u0644\u06e1\u0643\u064f \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0670\u0648\u064e\u0670\u062a\u0650 \u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u06e1\u0621\u0656 \u0634\u064e\u0647\u0650\u064a\u062f\u064c",translation:"yang memiliki kerajaan langit dan bumi. Dan Allah Maha Menyaksikan segala sesuatu"},{id:10,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0641\u064e\u062a\u064e\u0646\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0624\u06e1\u0645\u0650\u0646\u064e\u0670\u062a\u0650 \u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0645\u06e1 \u064a\u064e\u062a\u064f\u0648\u0628\u064f\u0648\u0627\u0652 \u0641\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064f \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0639\u064e\u0630\u064e\u0627\u0628\u064f \u0671\u0644\u06e1\u062d\u064e\u0631\u0650\u064a\u0642\u0650",translation:"Sungguh, orang-orang yang mendatangkan cobaan (bencana, membunuh, menyiksa) kepada orang-orang mukmin laki-laki dan perempuan lalu mereka tidak bertobat, maka mereka akan mendapat azab Jahanam dan mereka akan mendapat azab (neraka) yang membakar"},{id:11,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0644\u064e\u0647\u064f\u0645\u06e1 \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u065e \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0645\u0650\u0646 \u062a\u064e\u062d\u06e1\u062a\u0650\u0647\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u064f\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0671\u0644\u06e1\u0641\u064e\u0648\u06e1\u0632\u064f \u0671\u0644\u06e1\u0643\u064e\u0628\u0650\u064a\u0631\u064f",translation:"Sungguh, orang-orang yang beriman dan mengerjakan kebajikan, mereka akan mendapat surga yang mengalir di bawahnya sungai-sungai, itulah kemenangan yang agung"},{id:12,text:"\u0625\u0650\u0646\u0651\u064e \u0628\u064e\u0637\u06e1\u0634\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0644\u064e\u0634\u064e\u062f\u0650\u064a\u062f\u064c",translation:"Sungguh, azab Tuhanmu sangat keras"},{id:13,text:"\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0647\u064f\u0648\u064e \u064a\u064f\u0628\u06e1\u062f\u0650\u0626\u064f \u0648\u064e\u064a\u064f\u0639\u0650\u064a\u062f\u064f",translation:"Sungguh, Dialah yang memulai penciptaan (makhluk) dan yang menghidupkannya (kembali)"},{id:14,text:"\u0648\u064e\u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u063a\u064e\u0641\u064f\u0648\u0631\u064f \u0671\u0644\u06e1\u0648\u064e\u062f\u064f\u0648\u062f\u064f",translation:"Dan Dialah Yang Maha Pengampun, Maha Pengasih"},{id:15,text:"\u0630\u064f\u0648 \u0671\u0644\u06e1\u0639\u064e\u0631\u06e1\u0634\u0650 \u0671\u0644\u06e1\u0645\u064e\u062c\u0650\u064a\u062f\u064f",translation:"Yang memiliki Arasy, lagi Mahamulia"},{id:16,text:"\u0641\u064e\u0639\u0651\u064e\u0627\u0644\u065e \u0644\u0651\u0650\u0645\u064e\u0627 \u064a\u064f\u0631\u0650\u064a\u062f\u064f",translation:"Mahakuasa berbuat apa yang Dia kehendaki"},{id:17,text:"\u0647\u064e\u0644\u06e1 \u0623\u064e\u062a\u064e\u0649\u0670\u0643\u064e \u062d\u064e\u062f\u0650\u064a\u062b\u064f \u0671\u0644\u06e1\u062c\u064f\u0646\u064f\u0648\u062f\u0650",translation:"Sudahkah sampai kepadamu berita tentang bala tentara (penentang)"},{id:18,text:"\u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0648\u064e\u062b\u064e\u0645\u064f\u0648\u062f\u064e",translation:"(yaitu) Fir'aun dan Samud"},{id:19,text:"\u0628\u064e\u0644\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0641\u0650\u064a \u062a\u064e\u0643\u06e1\u0630\u0650\u064a\u0628\u0656",translation:"Memang orang-orang kafir (selalu) mendustakan"},{id:20,text:"\u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646 \u0648\u064e\u0631\u064e\u0627\u0653\u0626\u0650\u0647\u0650\u0645 \u0645\u0651\u064f\u062d\u0650\u064a\u0637\u064f\u06e2",translation:"padahal Allah mengepung dari belakang mereka (sehingga tidak dapat lolos)"},{id:21,text:"\u0628\u064e\u0644\u06e1 \u0647\u064f\u0648\u064e \u0642\u064f\u0631\u06e1\u0621\u064e\u0627\u0646\u065e \u0645\u0651\u064e\u062c\u0650\u064a\u062f\u065e",translation:"Bahkan (yang didustakan itu) ialah Alquran yang mulia"},{id:22,text:"\u0641\u0650\u064a \u0644\u064e\u0648\u06e1\u062d\u0656 \u0645\u0651\u064e\u062d\u06e1\u0641\u064f\u0648\u0638\u0650\u06ed",translation:"yang (tersimpan) dalam (tempat) yang terjaga (Lau\u1e25 Ma\u1e25f\u016b\u1e93)"}]},{id:86,name:"\u0627\u0644\u0637\u0627\u0631\u0642",transliteration:"At-Tariq",translation:"Yang Datang di Malam Hari",type:"meccan",total_verses:17,verses:[{id:1,text:"\u0648\u064e\u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0648\u064e\u0671\u0644\u0637\u0651\u064e\u0627\u0631\u0650\u0642\u0650",translation:"Demi langit dan yang datang pada malam hari"},{id:2,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u062f\u06e1\u0631\u064e\u0649\u0670\u0643\u064e \u0645\u064e\u0627 \u0671\u0644\u0637\u0651\u064e\u0627\u0631\u0650\u0642\u064f",translation:"Dan tahukah kamu apakah yang datang pada malam hari itu"},{id:3,text:"\u0671\u0644\u0646\u0651\u064e\u062c\u06e1\u0645\u064f \u0671\u0644\u062b\u0651\u064e\u0627\u0642\u0650\u0628\u064f",translation:"(Yaitu) bintang yang bersinar tajam"},{id:4,text:"\u0625\u0650\u0646 \u0643\u064f\u0644\u0651\u064f \u0646\u064e\u0641\u06e1\u0633\u0656 \u0644\u0651\u064e\u0645\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u064e\u0627 \u062d\u064e\u0627\u0641\u0650\u0638\u065e",translation:"setiap orang pasti ada penjaganya"},{id:5,text:"\u0641\u064e\u0644\u06e1\u064a\u064e\u0646\u0638\u064f\u0631\u0650 \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064f \u0645\u0650\u0645\u0651\u064e \u062e\u064f\u0644\u0650\u0642\u064e",translation:"Maka hendaklah manusia memperhatikan dari apa dia diciptakan"},{id:6,text:"\u062e\u064f\u0644\u0650\u0642\u064e \u0645\u0650\u0646 \u0645\u0651\u064e\u0627\u0653\u0621\u0656 \u062f\u064e\u0627\u0641\u0650\u0642\u0656",translation:"Dia diciptakan dari air (mani) yang terpancar"},{id:7,text:"\u064a\u064e\u062e\u06e1\u0631\u064f\u062c\u064f \u0645\u0650\u0646\u06e2 \u0628\u064e\u064a\u06e1\u0646\u0650 \u0671\u0644\u0635\u0651\u064f\u0644\u06e1\u0628\u0650 \u0648\u064e\u0671\u0644\u062a\u0651\u064e\u0631\u064e\u0627\u0653\u0626\u0650\u0628\u0650",translation:"yang keluar dari antara tulang punggung (sulbi) dan tulang dada"},{id:8,text:"\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u062c\u06e1\u0639\u0650\u0647\u0650\u06e6 \u0644\u064e\u0642\u064e\u0627\u062f\u0650\u0631\u065e",translation:"Sungguh, Allah benar-benar kuasa untuk mengembalikannya (hidup setelah mati)"},{id:9,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u062a\u064f\u0628\u06e1\u0644\u064e\u0649 \u0671\u0644\u0633\u0651\u064e\u0631\u064e\u0627\u0653\u0626\u0650\u0631\u064f",translation:"Pada hari ditampakkan segala rahasia"},{id:10,text:"\u0641\u064e\u0645\u064e\u0627 \u0644\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646 \u0642\u064f\u0648\u0651\u064e\u0629\u0656 \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0627\u0635\u0650\u0631\u0656",translation:"maka manusia tidak lagi mempunyai suatu kekuatan dan tidak (pula) ada penolong"},{id:11,text:"\u0648\u064e\u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0630\u064e\u0627\u062a\u0650 \u0671\u0644\u0631\u0651\u064e\u062c\u06e1\u0639\u0650",translation:"Demi langit yang mengandung hujan"},{id:12,text:"\u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0630\u064e\u0627\u062a\u0650 \u0671\u0644\u0635\u0651\u064e\u062f\u06e1\u0639\u0650",translation:"dan bumi yang mempunyai tumbuh-tumbuhan"},{id:13,text:"\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u064e\u0642\u064e\u0648\u06e1\u0644\u065e \u0641\u064e\u0635\u06e1\u0644\u065e",translation:"sungguh, (Alquran) itu benar-benar firman pemisah (antara yang hak dan yang batil)"},{id:14,text:"\u0648\u064e\u0645\u064e\u0627 \u0647\u064f\u0648\u064e \u0628\u0650\u0671\u0644\u06e1\u0647\u064e\u0632\u06e1\u0644\u0650",translation:"dan (Alquran) itu bukanlah senda gurauan"},{id:15,text:"\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u06e1 \u064a\u064e\u0643\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0643\u064e\u064a\u06e1\u062f\u0657\u0627",translation:"Sungguh, mereka (orang kafir) merencanakan tipu daya yang jahat"},{id:16,text:"\u0648\u064e\u0623\u064e\u0643\u0650\u064a\u062f\u064f \u0643\u064e\u064a\u06e1\u062f\u0657\u0627",translation:"dan Aku pun membuat rencana (tipu daya) yang jitu"},{id:17,text:"\u0641\u064e\u0645\u064e\u0647\u0651\u0650\u0644\u0650 \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u0623\u064e\u0645\u06e1\u0647\u0650\u0644\u06e1\u0647\u064f\u0645\u06e1 \u0631\u064f\u0648\u064e\u064a\u06e1\u062f\u064e\u06e2\u0627",translation:"Karena itu berilah penangguhan kepada orang-orang kafir. Berilah mereka kesempatan untuk sementara waktu"}]},{id:87,name:"\u0627\u0644\u0623\u0639\u0644\u0649",transliteration:"Al-A'la",translation:"Yang Paling Tinggi",type:"meccan",total_verses:19,verses:[{id:1,text:"\u0633\u064e\u0628\u0651\u0650\u062d\u0650 \u0671\u0633\u06e1\u0645\u064e \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0671\u0644\u06e1\u0623\u064e\u0639\u06e1\u0644\u064e\u0649",translation:"Sucikanlah nama Tuhanmu Yang Mahatinggi"},{id:2,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e \u0641\u064e\u0633\u064e\u0648\u0651\u064e\u0649\u0670",translation:"yang menciptakan, lalu menyempurnakan (penciptaan-Nya)"},{id:3,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0642\u064e\u062f\u0651\u064e\u0631\u064e \u0641\u064e\u0647\u064e\u062f\u064e\u0649\u0670",translation:"yang menentukan kadar (masing-masing) dan memberi petunjuk"},{id:4,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064e\u062e\u06e1\u0631\u064e\u062c\u064e \u0671\u0644\u06e1\u0645\u064e\u0631\u06e1\u0639\u064e\u0649\u0670",translation:"dan Yang menumbuhkan rerumputan"},{id:5,text:"\u0641\u064e\u062c\u064e\u0639\u064e\u0644\u064e\u0647\u064f\u06e5 \u063a\u064f\u062b\u064e\u0627\u0653\u0621\u064b \u0623\u064e\u062d\u06e1\u0648\u064e\u0649\u0670",translation:"lalu dijadikan-Nya (rumput-rumput) itu kering kehitam-hitaman"},{id:6,text:"\u0633\u064e\u0646\u064f\u0642\u06e1\u0631\u0650\u0626\u064f\u0643\u064e \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0646\u0633\u064e\u0649\u0670\u0653",translation:"Kami akan membacakan (Alquran) kepadamu (Muhammad) sehingga engkau tidak akan lupa"},{id:7,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0634\u064e\u0627\u0653\u0621\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0671\u0644\u06e1\u062c\u064e\u0647\u06e1\u0631\u064e \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u062e\u06e1\u0641\u064e\u0649\u0670",translation:"kecuali jika Allah menghendaki. Sungguh, Dia mengetahui yang terang dan yang tersembunyi"},{id:8,text:"\u0648\u064e\u0646\u064f\u064a\u064e\u0633\u0651\u0650\u0631\u064f\u0643\u064e \u0644\u0650\u0644\u06e1\u064a\u064f\u0633\u06e1\u0631\u064e\u0649\u0670",translation:"Dan Kami akan memudahkan bagimu ke jalan kemudahan (mencapai kebahagian dunia dan akhirat)"},{id:9,text:"\u0641\u064e\u0630\u064e\u0643\u0651\u0650\u0631\u06e1 \u0625\u0650\u0646 \u0646\u0651\u064e\u0641\u064e\u0639\u064e\u062a\u0650 \u0671\u0644\u0630\u0651\u0650\u0643\u06e1\u0631\u064e\u0649\u0670",translation:"oleh sebab itu berikanlah peringatan, karena peringatan itu bermanfaat"},{id:10,text:"\u0633\u064e\u064a\u064e\u0630\u0651\u064e\u0643\u0651\u064e\u0631\u064f \u0645\u064e\u0646 \u064a\u064e\u062e\u06e1\u0634\u064e\u0649\u0670",translation:"orang yang takut (kepada Allah) akan mendapat pelajaran"},{id:11,text:"\u0648\u064e\u064a\u064e\u062a\u064e\u062c\u064e\u0646\u0651\u064e\u0628\u064f\u0647\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0634\u06e1\u0642\u064e\u0649",translation:"dan orang yang celaka (kafir) akan menjauhinya"},{id:12,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064e\u0635\u06e1\u0644\u064e\u0649 \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u064e \u0671\u0644\u06e1\u0643\u064f\u0628\u06e1\u0631\u064e\u0649\u0670",translation:"(yaitu) orang yang akan memasuki api yang besar (neraka)"},{id:13,text:"\u062b\u064f\u0645\u0651\u064e \u0644\u064e\u0627 \u064a\u064e\u0645\u064f\u0648\u062a\u064f \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062d\u06e1\u064a\u064e\u0649\u0670",translation:"selanjutnya dia di sana tidak mati dan tidak (pula) hidup"},{id:14,text:"\u0642\u064e\u062f\u06e1 \u0623\u064e\u0641\u06e1\u0644\u064e\u062d\u064e \u0645\u064e\u0646 \u062a\u064e\u0632\u064e\u0643\u0651\u064e\u0649\u0670",translation:"Sungguh beruntung orang yang menyucikan diri (dengan beriman)"},{id:15,text:"\u0648\u064e\u0630\u064e\u0643\u064e\u0631\u064e \u0671\u0633\u06e1\u0645\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u06e6 \u0641\u064e\u0635\u064e\u0644\u0651\u064e\u0649\u0670",translation:"dan mengingat nama Tuhannya, lalu dia salat"},{id:16,text:"\u0628\u064e\u0644\u06e1 \u062a\u064f\u0624\u06e1\u062b\u0650\u0631\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u062d\u064e\u064a\u064e\u0648\u0670\u0629\u064e \u0671\u0644\u062f\u0651\u064f\u0646\u06e1\u064a\u064e\u0627",translation:"Sedangkan kamu (orang-orang kafir) memilih kehidupan dunia"},{id:17,text:"\u0648\u064e\u0671\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u064f \u062e\u064e\u064a\u06e1\u0631\u065e \u0648\u064e\u0623\u064e\u0628\u06e1\u0642\u064e\u0649\u0670\u0653",translation:"padahal kehidupan akhirat itu lebih baik dan lebih kekal"},{id:18,text:"\u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0644\u064e\u0641\u0650\u064a \u0671\u0644\u0635\u0651\u064f\u062d\u064f\u0641\u0650 \u0671\u0644\u06e1\u0623\u064f\u0648\u0644\u064e\u0649\u0670",translation:"Sesungguhnya ini terdapat dalam kitab-kitab yang dahulu"},{id:19,text:"\u0635\u064f\u062d\u064f\u0641\u0650 \u0625\u0650\u0628\u06e1\u0631\u064e\u0670\u0647\u0650\u064a\u0645\u064e \u0648\u064e\u0645\u064f\u0648\u0633\u064e\u0649\u0670",translation:"(yaitu) kitab-kitab Ibrahim dan Musa"}]},{id:88,name:"\u0627\u0644\u063a\u0627\u0634\u064a\u0629",transliteration:"Al-Ghashiyah",translation:"Hari Pembalasan",type:"meccan",total_verses:26,verses:[{id:1,text:"\u0647\u064e\u0644\u06e1 \u0623\u064e\u062a\u064e\u0649\u0670\u0643\u064e \u062d\u064e\u062f\u0650\u064a\u062b\u064f \u0671\u0644\u06e1\u063a\u064e\u0670\u0634\u0650\u064a\u064e\u0629\u0650",translation:"Sudahkah sampai kepadamu berita tentang (hari Kiamat)"},{id:2,text:"\u0648\u064f\u062c\u064f\u0648\u0647\u065e \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u064d \u062e\u064e\u0670\u0634\u0650\u0639\u064e\u0629\u064c",translation:"Pada hari itu banyak wajah yang tertunduk hina"},{id:3,text:"\u0639\u064e\u0627\u0645\u0650\u0644\u064e\u0629\u065e \u0646\u0651\u064e\u0627\u0635\u0650\u0628\u064e\u0629\u065e",translation:"(karena) bekerja keras lagi kepayahan"},{id:4,text:"\u062a\u064e\u0635\u06e1\u0644\u064e\u0649\u0670 \u0646\u064e\u0627\u0631\u064b\u0627 \u062d\u064e\u0627\u0645\u0650\u064a\u064e\u0629\u0657",translation:"mereka memasuki api yang sangat panas (neraka)"},{id:5,text:"\u062a\u064f\u0633\u06e1\u0642\u064e\u0649\u0670 \u0645\u0650\u0646\u06e1 \u0639\u064e\u064a\u06e1\u0646\u064d \u0621\u064e\u0627\u0646\u0650\u064a\u064e\u0629\u0656",translation:"diberi minum dari sumber mata air yang sangat panas"},{id:6,text:"\u0644\u0651\u064e\u064a\u06e1\u0633\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0637\u064e\u0639\u064e\u0627\u0645\u064c \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u0650\u0646 \u0636\u064e\u0631\u0650\u064a\u0639\u0656",translation:"Tidak ada makanan bagi mereka selain dari pohon yang berduri"},{id:7,text:"\u0644\u0651\u064e\u0627 \u064a\u064f\u0633\u06e1\u0645\u0650\u0646\u064f \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u063a\u06e1\u0646\u0650\u064a \u0645\u0650\u0646 \u062c\u064f\u0648\u0639\u0656",translation:"yang tidak menggemukkan dan tidak menghilangkan lapar"},{id:8,text:"\u0648\u064f\u062c\u064f\u0648\u0647\u065e \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u0646\u0651\u064e\u0627\u0639\u0650\u0645\u064e\u0629\u065e",translation:"Pada hari itu banyak (pula) wajah yang berseri-seri"},{id:9,text:"\u0644\u0651\u0650\u0633\u064e\u0639\u06e1\u064a\u0650\u0647\u064e\u0627 \u0631\u064e\u0627\u0636\u0650\u064a\u064e\u0629\u065e",translation:"merasa senang karena usahanya (sendiri)"},{id:10,text:"\u0641\u0650\u064a \u062c\u064e\u0646\u0651\u064e\u0629\u064d \u0639\u064e\u0627\u0644\u0650\u064a\u064e\u0629\u0656",translation:"(mereka) dalam surga yang tinggi"},{id:11,text:"\u0644\u0651\u064e\u0627 \u062a\u064e\u0633\u06e1\u0645\u064e\u0639\u064f \u0641\u0650\u064a\u0647\u064e\u0627 \u0644\u064e\u0670\u063a\u0650\u064a\u064e\u0629\u0657",translation:"di sana (kamu) tidak mendengar perkataan yang tidak berguna"},{id:12,text:"\u0641\u0650\u064a\u0647\u064e\u0627 \u0639\u064e\u064a\u06e1\u0646\u065e \u062c\u064e\u0627\u0631\u0650\u064a\u064e\u0629\u065e",translation:"Di sana ada mata air yang mengalir"},{id:13,text:"\u0641\u0650\u064a\u0647\u064e\u0627 \u0633\u064f\u0631\u064f\u0631\u065e \u0645\u0651\u064e\u0631\u06e1\u0641\u064f\u0648\u0639\u064e\u0629\u065e",translation:"Di sana ada dipan-dipan yang ditinggikan"},{id:14,text:"\u0648\u064e\u0623\u064e\u0643\u06e1\u0648\u064e\u0627\u0628\u065e \u0645\u0651\u064e\u0648\u06e1\u0636\u064f\u0648\u0639\u064e\u0629\u065e",translation:"dan gelas-gelas yang tersedia (di dekatnya)"},{id:15,text:"\u0648\u064e\u0646\u064e\u0645\u064e\u0627\u0631\u0650\u0642\u064f \u0645\u064e\u0635\u06e1\u0641\u064f\u0648\u0641\u064e\u0629\u065e",translation:"dan bantal-bantal sandaran yang tersusun"},{id:16,text:"\u0648\u064e\u0632\u064e\u0631\u064e\u0627\u0628\u0650\u064a\u0651\u064f \u0645\u064e\u0628\u06e1\u062b\u064f\u0648\u062b\u064e\u0629\u064c",translation:"dan permadani-permadani yang terhampar"},{id:17,text:"\u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0646\u0638\u064f\u0631\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u0625\u0650\u0628\u0650\u0644\u0650 \u0643\u064e\u064a\u06e1\u0641\u064e \u062e\u064f\u0644\u0650\u0642\u064e\u062a\u06e1",translation:"Maka tidakkah mereka memperhatikan unta, bagaimana diciptakan"},{id:18,text:"\u0648\u064e\u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0643\u064e\u064a\u06e1\u0641\u064e \u0631\u064f\u0641\u0650\u0639\u064e\u062a\u06e1",translation:"Dan langit, bagaimana ditinggikan"},{id:19,text:"\u0648\u064e\u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u062c\u0650\u0628\u064e\u0627\u0644\u0650 \u0643\u064e\u064a\u06e1\u0641\u064e \u0646\u064f\u0635\u0650\u0628\u064e\u062a\u06e1",translation:"Dan gunung-gunung bagaimana ditegakkan"},{id:20,text:"\u0648\u064e\u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0643\u064e\u064a\u06e1\u0641\u064e \u0633\u064f\u0637\u0650\u062d\u064e\u062a\u06e1",translation:"Dan bumi bagaimana dihamparkan"},{id:21,text:"\u0641\u064e\u0630\u064e\u0643\u0651\u0650\u0631\u06e1 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064e \u0645\u064f\u0630\u064e\u0643\u0651\u0650\u0631\u065e",translation:"Maka berilah peringatan, karena sesungguhnya engkau (Muhammad) hanyalah pemberi peringatan"},{id:22,text:"\u0644\u0651\u064e\u0633\u06e1\u062a\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0628\u0650\u0645\u064f\u0635\u064e\u064a\u06e1\u0637\u0650\u0631\u064d",translation:"Engkau bukanlah orang yang berkuasa atas mereka"},{id:23,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649\u0670 \u0648\u064e\u0643\u064e\u0641\u064e\u0631\u064e",translation:"kecuali (jika ada) orang yang berpaling dan kafir"},{id:24,text:"\u0641\u064e\u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064f\u0647\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u06e1\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0671\u0644\u06e1\u0623\u064e\u0643\u06e1\u0628\u064e\u0631\u064e",translation:"maka Allah akan mengazabnya dengan azab yang besar"},{id:25,text:"\u0625\u0650\u0646\u0651\u064e \u0625\u0650\u0644\u064e\u064a\u06e1\u0646\u064e\u0627\u0653 \u0625\u0650\u064a\u064e\u0627\u0628\u064e\u0647\u064f\u0645\u06e1",translation:"Sungguh, kepada Kami lah mereka kembali"},{id:26,text:"\u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u062d\u0650\u0633\u064e\u0627\u0628\u064e\u0647\u064f\u0645",translation:"kemudian sesungguhnya (kewajiban) Kami lah membuat perhitungan atas mereka"}]},{id:89,name:"\u0627\u0644\u0641\u062c\u0631",transliteration:"Al-Fajr",translation:"Fajar",type:"meccan",total_verses:30,verses:[{id:1,text:"\u0648\u064e\u0671\u0644\u06e1\u0641\u064e\u062c\u06e1\u0631\u0650",translation:"Demi fajar"},{id:2,text:"\u0648\u064e\u0644\u064e\u064a\u064e\u0627\u0644\u064d \u0639\u064e\u0634\u06e1\u0631\u0656",translation:"demi malam yang sepuluh"},{id:3,text:"\u0648\u064e\u0671\u0644\u0634\u0651\u064e\u0641\u06e1\u0639\u0650 \u0648\u064e\u0671\u0644\u06e1\u0648\u064e\u062a\u06e1\u0631\u0650",translation:"demi yang genap dan yang ganjil"},{id:4,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u0650 \u0625\u0650\u0630\u064e\u0627 \u064a\u064e\u0633\u06e1\u0631\u0650",translation:"demi malam apabila berlalu"},{id:5,text:"\u0647\u064e\u0644\u06e1 \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0642\u064e\u0633\u064e\u0645\u065e \u0644\u0651\u0650\u0630\u0650\u064a \u062d\u0650\u062c\u06e1\u0631\u064d",translation:"Adakah pada yang demikian itu terdapat sumpah (yang dapat diterima) bagi orang-orang yang berakal"},{id:6,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0631\u064e \u0643\u064e\u064a\u06e1\u0641\u064e \u0641\u064e\u0639\u064e\u0644\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0628\u0650\u0639\u064e\u0627\u062f\u064d",translation:"Tidakkah engkau (Muhammad) memperhatikan bagaimana Tuhanmu berbuat terhadap (kaum) '\u0100d"},{id:7,text:"\u0625\u0650\u0631\u064e\u0645\u064e \u0630\u064e\u0627\u062a\u0650 \u0671\u0644\u06e1\u0639\u0650\u0645\u064e\u0627\u062f\u0650",translation:"(yaitu) penduduk Iram (ibukota kaum '\u0100d) yang mempunyai bangunan-bangunan yang tinggi"},{id:8,text:"\u0671\u0644\u0651\u064e\u062a\u0650\u064a \u0644\u064e\u0645\u06e1 \u064a\u064f\u062e\u06e1\u0644\u064e\u0642\u06e1 \u0645\u0650\u062b\u06e1\u0644\u064f\u0647\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0628\u0650\u0644\u064e\u0670\u062f\u0650",translation:"yang belum pernah dibangun (suatu kota) seperti itu, di negeri-negeri lain"},{id:9,text:"\u0648\u064e\u062b\u064e\u0645\u064f\u0648\u062f\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062c\u064e\u0627\u0628\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u062e\u06e1\u0631\u064e \u0628\u0650\u0671\u0644\u06e1\u0648\u064e\u0627\u062f\u0650",translation:"dan (terhadap) kaum Samud yang memotong batu-batu besar di lembah"},{id:10,text:"\u0648\u064e\u0641\u0650\u0631\u06e1\u0639\u064e\u0648\u06e1\u0646\u064e \u0630\u0650\u064a \u0671\u0644\u06e1\u0623\u064e\u0648\u06e1\u062a\u064e\u0627\u062f\u0650",translation:"dan (terhadap) Fir'aun yang mempunyai pasak-pasak (bangunan yang besar)"},{id:11,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0637\u064e\u063a\u064e\u0648\u06e1\u0627\u0652 \u0641\u0650\u064a \u0671\u0644\u06e1\u0628\u0650\u0644\u064e\u0670\u062f\u0650",translation:"yang berbuat sewenang-wenang dalam negeri"},{id:12,text:"\u0641\u064e\u0623\u064e\u0643\u06e1\u062b\u064e\u0631\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u0671\u0644\u06e1\u0641\u064e\u0633\u064e\u0627\u062f\u064e",translation:"lalu mereka banyak berbuat kerusakan dalam negeri itu"},{id:13,text:"\u0641\u064e\u0635\u064e\u0628\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0633\u064e\u0648\u06e1\u0637\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u064d",translation:"karena itu Tuhanmu menimpakan cemeti azab kepada mereka"},{id:14,text:"\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0644\u064e\u0628\u0650\u0671\u0644\u06e1\u0645\u0650\u0631\u06e1\u0635\u064e\u0627\u062f\u0650",translation:"sungguh, Tuhanmu benar-benar mengawasi"},{id:15,text:"\u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064f \u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0627 \u0671\u0628\u06e1\u062a\u064e\u0644\u064e\u0649\u0670\u0647\u064f \u0631\u064e\u0628\u0651\u064f\u0647\u064f\u06e5 \u0641\u064e\u0623\u064e\u0643\u06e1\u0631\u064e\u0645\u064e\u0647\u064f\u06e5 \u0648\u064e\u0646\u064e\u0639\u0651\u064e\u0645\u064e\u0647\u064f\u06e5 \u0641\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0631\u064e\u0628\u0651\u0650\u064a\u0653 \u0623\u064e\u0643\u06e1\u0631\u064e\u0645\u064e\u0646\u0650",translation:"Adapun manusia, apabila Tuhan mengujinya lalu memuliakannya dan memberinya kesenangan, maka dia berkata, \"Tuhanku telah memuliakanku"},{id:16,text:"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627\u0653 \u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0627 \u0671\u0628\u06e1\u062a\u064e\u0644\u064e\u0649\u0670\u0647\u064f \u0641\u064e\u0642\u064e\u062f\u064e\u0631\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0631\u0650\u0632\u06e1\u0642\u064e\u0647\u064f\u06e5 \u0641\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0631\u064e\u0628\u0651\u0650\u064a\u0653 \u0623\u064e\u0647\u064e\u0670\u0646\u064e\u0646\u0650",translation:"Namun apabila Tuhan mengujinya lalu membatasi rezekinya, maka dia berkata, \"Tuhanku telah menghinaku"},{id:17,text:"\u0643\u064e\u0644\u0651\u064e\u0627\u06d6 \u0628\u064e\u0644 \u0644\u0651\u064e\u0627 \u062a\u064f\u0643\u06e1\u0631\u0650\u0645\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u064a\u064e\u062a\u0650\u064a\u0645\u064e",translation:"Sekali-kali tidak! Bahkan kamu tidak memuliakan anak yatim"},{id:18,text:"\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062d\u064e\u0640\u0670\u0653\u0636\u0651\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0637\u064e\u0639\u064e\u0627\u0645\u0650 \u0671\u0644\u06e1\u0645\u0650\u0633\u06e1\u0643\u0650\u064a\u0646\u0650",translation:"dan kamu tidak saling mengajak memberi makan orang miskin"},{id:19,text:"\u0648\u064e\u062a\u064e\u0623\u06e1\u0643\u064f\u0644\u064f\u0648\u0646\u064e \u0671\u0644\u062a\u0651\u064f\u0631\u064e\u0627\u062b\u064e \u0623\u064e\u0643\u06e1\u0644\u0657\u0627 \u0644\u0651\u064e\u0645\u0651\u0657\u0627",translation:"sedangkan kamu memakan harta warisan dengan cara mencampurbaurkan (yang halal dan yang haram)"},{id:20,text:"\u0648\u064e\u062a\u064f\u062d\u0650\u0628\u0651\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0645\u064e\u0627\u0644\u064e \u062d\u064f\u0628\u0651\u0657\u0627 \u062c\u064e\u0645\u0651\u0657\u0627",translation:"dan kamu mencintai harta dengan kecintaan yang berlebihan"},{id:21,text:"\u0643\u064e\u0644\u0651\u064e\u0627\u0653\u06d6 \u0625\u0650\u0630\u064e\u0627 \u062f\u064f\u0643\u0651\u064e\u062a\u0650 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064f \u062f\u064e\u0643\u0651\u0657\u0627 \u062f\u064e\u0643\u0651\u0657\u0627",translation:"Sekali-kali tidak! Apabila bumi diguncangkan berturut-turut (berbenturan)"},{id:22,text:"\u0648\u064e\u062c\u064e\u0627\u0653\u0621\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0648\u064e\u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0643\u064f \u0635\u064e\u0641\u0651\u0657\u0627 \u0635\u064e\u0641\u0651\u0657\u0627",translation:"dan datanglah Tuhanmu; dan malaikat berbaris-baris"},{id:23,text:"\u0648\u064e\u062c\u0650\u0627\u0652\u064a\u0653\u0621\u064e \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0650\u06ed \u0628\u0650\u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e\u06da \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u064a\u064e\u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064f \u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0649\u0670 \u0644\u064e\u0647\u064f \u0671\u0644\u0630\u0651\u0650\u0643\u06e1\u0631\u064e\u0649\u0670",translation:"dan pada hari itu diperlihatkan neraka Jahanam; pada hari itu sadarlah manusia, tetapi tidak berguna lagi baginya kesadaran itu"},{id:24,text:"\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u064a\u064e\u0670\u0644\u064e\u064a\u06e1\u062a\u064e\u0646\u0650\u064a \u0642\u064e\u062f\u0651\u064e\u0645\u06e1\u062a\u064f \u0644\u0650\u062d\u064e\u064a\u064e\u0627\u062a\u0650\u064a",translation:"Dia berkata, \"Alangkah baiknya sekiranya dahulu aku mengerjakan (kebajikan) untuk hidupku ini"},{id:25,text:"\u0641\u064e\u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u0644\u0651\u064e\u0627 \u064a\u064f\u0639\u064e\u0630\u0651\u0650\u0628\u064f \u0639\u064e\u0630\u064e\u0627\u0628\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u062d\u064e\u062f\u065e",translation:"Maka pada hari itu tidak ada seorang pun yang mengazab seperti azab-Nya (yang adil)"},{id:26,text:"\u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0648\u062b\u0650\u0642\u064f \u0648\u064e\u062b\u064e\u0627\u0642\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u062d\u064e\u062f\u065e",translation:"dan tidak ada seorang pun yang mengikat seperti ikatan-Nya"},{id:27,text:"\u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064e\u062a\u064f\u0647\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0641\u06e1\u0633\u064f \u0671\u0644\u06e1\u0645\u064f\u0637\u06e1\u0645\u064e\u0626\u0650\u0646\u0651\u064e\u0629\u064f",translation:"Wahai jiwa yang tenang"},{id:28,text:"\u0671\u0631\u06e1\u062c\u0650\u0639\u0650\u064a\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u0650 \u0631\u064e\u0627\u0636\u0650\u064a\u064e\u0629\u0657 \u0645\u0651\u064e\u0631\u06e1\u0636\u0650\u064a\u0651\u064e\u0629\u0657",translation:"Kembalilah kepada Tuhanmu dengan hati yang rida dan diridai-Nya"},{id:29,text:"\u0641\u064e\u0671\u062f\u06e1\u062e\u064f\u0644\u0650\u064a \u0641\u0650\u064a \u0639\u0650\u0628\u064e\u0670\u062f\u0650\u064a",translation:"Maka masuklah ke dalam golongan hamba-hamba-Ku"},{id:30,text:"\u0648\u064e\u0671\u062f\u06e1\u062e\u064f\u0644\u0650\u064a \u062c\u064e\u0646\u0651\u064e\u062a\u0650\u064a",translation:"dan masuklah ke dalam surga-Ku"}]},{id:90,name:"\u0627\u0644\u0628\u0644\u062f",transliteration:"Al-Balad",translation:"Negeri",type:"meccan",total_verses:20,verses:[{id:1,text:"\u0644\u064e\u0627\u0653 \u0623\u064f\u0642\u06e1\u0633\u0650\u0645\u064f \u0628\u0650\u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u06e1\u0628\u064e\u0644\u064e\u062f\u0650",translation:"Aku bersumpah dengan negeri ini (Mekkah)"},{id:2,text:"\u0648\u064e\u0623\u064e\u0646\u062a\u064e \u062d\u0650\u0644\u0651\u064f\u06e2 \u0628\u0650\u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u06e1\u0628\u064e\u0644\u064e\u062f\u0650",translation:"dan engkau (Muhammad), bertempat di negeri (Mekkah) ini"},{id:3,text:"\u0648\u064e\u0648\u064e\u0627\u0644\u0650\u062f\u0656 \u0648\u064e\u0645\u064e\u0627 \u0648\u064e\u0644\u064e\u062f\u064e",translation:"dan demi (pertalian) bapak dan anaknya"},{id:4,text:"\u0644\u064e\u0642\u064e\u062f\u06e1 \u062e\u064e\u0644\u064e\u0642\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064e \u0641\u0650\u064a \u0643\u064e\u0628\u064e\u062f\u064d",translation:"Sungguh, Kami telah menciptakan manusia berada dalam susah payah"},{id:5,text:"\u0623\u064e\u064a\u064e\u062d\u06e1\u0633\u064e\u0628\u064f \u0623\u064e\u0646 \u0644\u0651\u064e\u0646 \u064a\u064e\u0642\u06e1\u062f\u0650\u0631\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650 \u0623\u064e\u062d\u064e\u062f\u065e",translation:"Apakah dia (manusia) itu mengira bahwa tidak ada sesuatu pun yang berkuasa atasnya"},{id:6,text:"\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0623\u064e\u0647\u06e1\u0644\u064e\u0643\u06e1\u062a\u064f \u0645\u064e\u0627\u0644\u0657\u0627 \u0644\u0651\u064f\u0628\u064e\u062f\u064b\u0627",translation:"Dia mengatakan, \"Aku telah menghabiskan harta yang banyak"},{id:7,text:"\u0623\u064e\u064a\u064e\u062d\u06e1\u0633\u064e\u0628\u064f \u0623\u064e\u0646 \u0644\u0651\u064e\u0645\u06e1 \u064a\u064e\u0631\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u062d\u064e\u062f\u064c",translation:"Apakah dia mengira bahwa tidak ada sesuatu pun yang melihatnya"},{id:8,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u0646\u064e\u062c\u06e1\u0639\u064e\u0644 \u0644\u0651\u064e\u0647\u064f\u06e5 \u0639\u064e\u064a\u06e1\u0646\u064e\u064a\u06e1\u0646\u0650",translation:"Bukankah Kami telah menjadikan untuknya sepasang mata"},{id:9,text:"\u0648\u064e\u0644\u0650\u0633\u064e\u0627\u0646\u0657\u0627 \u0648\u064e\u0634\u064e\u0641\u064e\u062a\u064e\u064a\u06e1\u0646\u0650",translation:"dan lidah dan sepasang bibir"},{id:10,text:"\u0648\u064e\u0647\u064e\u062f\u064e\u064a\u06e1\u0646\u064e\u0670\u0647\u064f \u0671\u0644\u0646\u0651\u064e\u062c\u06e1\u062f\u064e\u064a\u06e1\u0646\u0650",translation:"Dan Kami telah menunjukkan kepadanya dua jalan (kebajikkan dan kejahatan)"},{id:11,text:"\u0641\u064e\u0644\u064e\u0627 \u0671\u0642\u06e1\u062a\u064e\u062d\u064e\u0645\u064e \u0671\u0644\u06e1\u0639\u064e\u0642\u064e\u0628\u064e\u0629\u064e",translation:"Tetapi dia tidak menempuh jalan yang mendaki dan sukar"},{id:12,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u062f\u06e1\u0631\u064e\u0649\u0670\u0643\u064e \u0645\u064e\u0627 \u0671\u0644\u06e1\u0639\u064e\u0642\u064e\u0628\u064e\u0629\u064f",translation:"Dan tahukah kamu apakah jalan yang mendaki dan sukar itu"},{id:13,text:"\u0641\u064e\u0643\u0651\u064f \u0631\u064e\u0642\u064e\u0628\u064e\u0629\u064d",translation:"(Yaitu) membebaskan budak (hamba sahaya)"},{id:14,text:"\u0623\u064e\u0648\u06e1 \u0625\u0650\u0637\u06e1\u0639\u064e\u0670\u0645\u065e \u0641\u0650\u064a \u064a\u064e\u0648\u06e1\u0645\u0656 \u0630\u0650\u064a \u0645\u064e\u0633\u06e1\u063a\u064e\u0628\u064e\u0629\u0656",translation:"atau memberi makan pada hari terjadi kelaparan"},{id:15,text:"\u064a\u064e\u062a\u0650\u064a\u0645\u0657\u0627 \u0630\u064e\u0627 \u0645\u064e\u0642\u06e1\u0631\u064e\u0628\u064e\u0629\u064d",translation:"(kepada) anak yatim yang ada hubungan kerabat"},{id:16,text:"\u0623\u064e\u0648\u06e1 \u0645\u0650\u0633\u06e1\u0643\u0650\u064a\u0646\u0657\u0627 \u0630\u064e\u0627 \u0645\u064e\u062a\u06e1\u0631\u064e\u0628\u064e\u0629\u0656",translation:"atau orang miskin yang sangat fakir"},{id:17,text:"\u062b\u064f\u0645\u0651\u064e \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u062a\u064e\u0648\u064e\u0627\u0635\u064e\u0648\u06e1\u0627\u0652 \u0628\u0650\u0671\u0644\u0635\u0651\u064e\u0628\u06e1\u0631\u0650 \u0648\u064e\u062a\u064e\u0648\u064e\u0627\u0635\u064e\u0648\u06e1\u0627\u0652 \u0628\u0650\u0671\u0644\u06e1\u0645\u064e\u0631\u06e1\u062d\u064e\u0645\u064e\u0629\u0650",translation:"Kemudian dia termasuk orang-orang yang beriman, dan saling berpesan untuk bersabar dan saling berpesan untuk berkasih sayang"},{id:18,text:"\u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u06e1\u0645\u064e\u064a\u06e1\u0645\u064e\u0646\u064e\u0629\u0650",translation:"Mereka (orang-orang yang beriman dan saling berpesan itu) adalah golongan kanan"},{id:19,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627 \u0647\u064f\u0645\u06e1 \u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u06e1\u0645\u064e\u0634\u06e1\u0640\u0654\u064e\u0645\u064e\u0629\u0650",translation:"Dan orang-orang yang kafir kepada ayat-ayat Kami, mereka itu adalah golongan kiri"},{id:20,text:"\u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0646\u064e\u0627\u0631\u065e \u0645\u0651\u064f\u0624\u06e1\u0635\u064e\u062f\u064e\u0629\u064f\u06e2",translation:"Mereka berada dalam neraka yang ditutup rapat"}]},{id:91,name:"\u0627\u0644\u0634\u0645\u0633",transliteration:"Ash-Shams",translation:"Matahari",type:"meccan",total_verses:15,verses:[{id:1,text:"\u0648\u064e\u0671\u0644\u0634\u0651\u064e\u0645\u06e1\u0633\u0650 \u0648\u064e\u0636\u064f\u062d\u064e\u0649\u0670\u0647\u064e\u0627",translation:"Demi matahari dan sinarnya pada pagi hari"},{id:2,text:"\u0648\u064e\u0671\u0644\u06e1\u0642\u064e\u0645\u064e\u0631\u0650 \u0625\u0650\u0630\u064e\u0627 \u062a\u064e\u0644\u064e\u0649\u0670\u0647\u064e\u0627",translation:"demi bulan apabila mengiringinya"},{id:3,text:"\u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0644\u0651\u064e\u0649\u0670\u0647\u064e\u0627",translation:"demi siang apabila menampakkannya"},{id:4,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u0650 \u0625\u0650\u0630\u064e\u0627 \u064a\u064e\u063a\u06e1\u0634\u064e\u0649\u0670\u0647\u064e\u0627",translation:"demi malam apabila menutupinya (gelap gulita)"},{id:5,text:"\u0648\u064e\u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u0646\u064e\u0649\u0670\u0647\u064e\u0627",translation:"demi langit serta perancangannya (yang menakjubkan)"},{id:6,text:"\u0648\u064e\u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u0637\u064e\u062d\u064e\u0649\u0670\u0647\u064e\u0627",translation:"demi bumi serta penghamparannya"},{id:7,text:"\u0648\u064e\u0646\u064e\u0641\u06e1\u0633\u0656 \u0648\u064e\u0645\u064e\u0627 \u0633\u064e\u0648\u0651\u064e\u0649\u0670\u0647\u064e\u0627",translation:"demi jiwa serta penyempurnaan (ciptaan)nya"},{id:8,text:"\u0641\u064e\u0623\u064e\u0644\u06e1\u0647\u064e\u0645\u064e\u0647\u064e\u0627 \u0641\u064f\u062c\u064f\u0648\u0631\u064e\u0647\u064e\u0627 \u0648\u064e\u062a\u064e\u0642\u06e1\u0648\u064e\u0649\u0670\u0647\u064e\u0627",translation:"maka Dia mengilhamkan kepadanya (jalan) kejahatan dan ketakwaannya"},{id:9,text:"\u0642\u064e\u062f\u06e1 \u0623\u064e\u0641\u06e1\u0644\u064e\u062d\u064e \u0645\u064e\u0646 \u0632\u064e\u0643\u0651\u064e\u0649\u0670\u0647\u064e\u0627",translation:"sungguh beruntung orang yang menyucikannya (jiwa itu)"},{id:10,text:"\u0648\u064e\u0642\u064e\u062f\u06e1 \u062e\u064e\u0627\u0628\u064e \u0645\u064e\u0646 \u062f\u064e\u0633\u0651\u064e\u0649\u0670\u0647\u064e\u0627",translation:"dan sungguh rugi orang yang mengotorinya"},{id:11,text:"\u0643\u064e\u0630\u0651\u064e\u0628\u064e\u062a\u06e1 \u062b\u064e\u0645\u064f\u0648\u062f\u064f \u0628\u0650\u0637\u064e\u063a\u06e1\u0648\u064e\u0649\u0670\u0647\u064e\u0627\u0653",translation:"(Kaum) Samud telah mendustakan (rasulnya) karena mereka melampaui batas (zalim)"},{id:12,text:"\u0625\u0650\u0630\u0650 \u0671\u0646\u06e2\u0628\u064e\u0639\u064e\u062b\u064e \u0623\u064e\u0634\u06e1\u0642\u064e\u0649\u0670\u0647\u064e\u0627",translation:"ketika bangkit orang yang paling celaka di antara mereka"},{id:13,text:"\u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u06e1 \u0631\u064e\u0633\u064f\u0648\u0644\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0646\u064e\u0627\u0642\u064e\u0629\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0633\u064f\u0642\u06e1\u064a\u064e\u0670\u0647\u064e\u0627",translation:"lalu Rasul Allah (Saleh) berkata kepada mereka, \"(Biarkanlah) unta betina dari Allah ini dengan minumannya"},{id:14,text:"\u0641\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0647\u064f \u0641\u064e\u0639\u064e\u0642\u064e\u0631\u064f\u0648\u0647\u064e\u0627 \u0641\u064e\u062f\u064e\u0645\u06e1\u062f\u064e\u0645\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0631\u064e\u0628\u0651\u064f\u0647\u064f\u0645 \u0628\u0650\u0630\u064e\u0646\u06e2\u0628\u0650\u0647\u0650\u0645\u06e1 \u0641\u064e\u0633\u064e\u0648\u0651\u064e\u0649\u0670\u0647\u064e\u0627",translation:"Namun mereka mendustakannya dan menyembelihnya, karena itu Tuhan membinasakan mereka karena dosanya, lalu diratakan-Nya (dengan tanah)"},{id:15,text:"\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062e\u064e\u0627\u0641\u064f \u0639\u064f\u0642\u06e1\u0628\u064e\u0670\u0647\u064e\u0627",translation:"Dan Dia tidak takut terhadap akibatnya"}]},{id:92,name:"\u0627\u0644\u0644\u064a\u0644",transliteration:"Al-Layl",translation:"Malam",type:"meccan",total_verses:21,verses:[{id:1,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u0650 \u0625\u0650\u0630\u064e\u0627 \u064a\u064e\u063a\u06e1\u0634\u064e\u0649\u0670",translation:"Demi malam apabila menutupi (cahaya siang)"},{id:2,text:"\u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u0650 \u0625\u0650\u0630\u064e\u0627 \u062a\u064e\u062c\u064e\u0644\u0651\u064e\u0649\u0670",translation:"demi siang bila terang benderang"},{id:3,text:"\u0648\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u0630\u0651\u064e\u0643\u064e\u0631\u064e \u0648\u064e\u0671\u0644\u06e1\u0623\u064f\u0646\u062b\u064e\u0649\u0670\u0653",translation:"demi penciptaan laki-laki dan perempuan"},{id:4,text:"\u0625\u0650\u0646\u0651\u064e \u0633\u064e\u0639\u06e1\u064a\u064e\u0643\u064f\u0645\u06e1 \u0644\u064e\u0634\u064e\u062a\u0651\u064e\u0649\u0670",translation:"sungguh, usahamu memang beraneka macam"},{id:5,text:"\u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0645\u064e\u0646\u06e1 \u0623\u064e\u0639\u06e1\u0637\u064e\u0649\u0670 \u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064e\u0649\u0670",translation:"Maka barangsiapa memberikan (hartanya di jalan Allah) dan bertakwa"},{id:6,text:"\u0648\u064e\u0635\u064e\u062f\u0651\u064e\u0642\u064e \u0628\u0650\u0671\u0644\u06e1\u062d\u064f\u0633\u06e1\u0646\u064e\u0649\u0670",translation:"dan membenarkan (adanya pahala) yang terbaik (surga)"},{id:7,text:"\u0641\u064e\u0633\u064e\u0646\u064f\u064a\u064e\u0633\u0651\u0650\u0631\u064f\u0647\u064f\u06e5 \u0644\u0650\u0644\u06e1\u064a\u064f\u0633\u06e1\u0631\u064e\u0649\u0670",translation:"maka akan Kami mudahkan baginya jalan menuju kemudahan (kebahagiaan)"},{id:8,text:"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0645\u064e\u0646\u06e2 \u0628\u064e\u062e\u0650\u0644\u064e \u0648\u064e\u0671\u0633\u06e1\u062a\u064e\u063a\u06e1\u0646\u064e\u0649\u0670",translation:"Dan adapun orang yang kikir dan merasa dirinya cukup (tidak perlu pertolongan Allah)"},{id:9,text:"\u0648\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0628\u0650\u0671\u0644\u06e1\u062d\u064f\u0633\u06e1\u0646\u064e\u0649\u0670",translation:"serta mendustakan (pahala) yang terbaik"},{id:10,text:"\u0641\u064e\u0633\u064e\u0646\u064f\u064a\u064e\u0633\u0651\u0650\u0631\u064f\u0647\u064f\u06e5 \u0644\u0650\u0644\u06e1\u0639\u064f\u0633\u06e1\u0631\u064e\u0649\u0670",translation:"maka akan Kami mudahkan baginya jalan menuju kesukaran (kesengsaraan)"},{id:11,text:"\u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u063a\u06e1\u0646\u0650\u064a \u0639\u064e\u0646\u06e1\u0647\u064f \u0645\u064e\u0627\u0644\u064f\u0647\u064f\u06e5\u0653 \u0625\u0650\u0630\u064e\u0627 \u062a\u064e\u0631\u064e\u062f\u0651\u064e\u0649\u0670\u0653",translation:"Dan hartanya tidak bermanfaat baginya apabila dia telah binasa"},{id:12,text:"\u0625\u0650\u0646\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0646\u064e\u0627 \u0644\u064e\u0644\u06e1\u0647\u064f\u062f\u064e\u0649\u0670",translation:"Sesungguhnya Kami lah yang memberi petunjuk"},{id:13,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0644\u064e\u0646\u064e\u0627 \u0644\u064e\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u064e \u0648\u064e\u0671\u0644\u06e1\u0623\u064f\u0648\u0644\u064e\u0649\u0670",translation:"dan sesungguhnya milik Kami lah akhirat dan dunia"},{id:14,text:"\u0641\u064e\u0623\u064e\u0646\u0630\u064e\u0631\u06e1\u062a\u064f\u0643\u064f\u0645\u06e1 \u0646\u064e\u0627\u0631\u0657\u0627 \u062a\u064e\u0644\u064e\u0638\u0651\u064e\u0649\u0670",translation:"Maka aku memperingatkan kamu dengan neraka yang menyala-nyala"},{id:15,text:"\u0644\u064e\u0627 \u064a\u064e\u0635\u06e1\u0644\u064e\u0649\u0670\u0647\u064e\u0627\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0634\u06e1\u0642\u064e\u0649",translation:"yang hanya dimasuki oleh orang yang paling celaka"},{id:16,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0648\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649\u0670",translation:"yang mendustakan (kebenaran) dan berpaling (dari iman)"},{id:17,text:"\u0648\u064e\u0633\u064e\u064a\u064f\u062c\u064e\u0646\u0651\u064e\u0628\u064f\u0647\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u062a\u06e1\u0642\u064e\u0649",translation:"Dan akan dijauhkan darinya (neraka) orang yang paling bertakwa"},{id:18,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u0624\u06e1\u062a\u0650\u064a \u0645\u064e\u0627\u0644\u064e\u0647\u064f\u06e5 \u064a\u064e\u062a\u064e\u0632\u064e\u0643\u0651\u064e\u0649\u0670",translation:"yang menginfakkan hartanya (di jalan Allah) untuk membersihkan (dirinya)"},{id:19,text:"\u0648\u064e\u0645\u064e\u0627 \u0644\u0650\u0623\u064e\u062d\u064e\u062f\u064d \u0639\u0650\u0646\u062f\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646 \u0646\u0651\u0650\u0639\u06e1\u0645\u064e\u0629\u0656 \u062a\u064f\u062c\u06e1\u0632\u064e\u0649\u0670\u0653",translation:"dan tidak ada seorang pun memberikan suatu nikmat padanya yang harus dibalasnya"},{id:20,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0628\u06e1\u062a\u0650\u063a\u064e\u0627\u0653\u0621\u064e \u0648\u064e\u062c\u06e1\u0647\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650 \u0671\u0644\u06e1\u0623\u064e\u0639\u06e1\u0644\u064e\u0649\u0670",translation:"tetapi (dia memberikan itu semata-mata) karena mencari keridaan Tuhannya Yang Mahatinggi"},{id:21,text:"\u0648\u064e\u0644\u064e\u0633\u064e\u0648\u06e1\u0641\u064e \u064a\u064e\u0631\u06e1\u0636\u064e\u0649\u0670",translation:"Dan niscaya kelak dia akan mendapat kesenangan (yang sempurna)"}]},{id:93,name:"\u0627\u0644\u0636\u062d\u0649",transliteration:"Ad-Duhaa",translation:"Waktu Dhuha",type:"meccan",total_verses:11,verses:[{id:1,text:"\u0648\u064e\u0671\u0644\u0636\u0651\u064f\u062d\u064e\u0649\u0670",translation:"Demi waktu duha (ketika matahari naik sepenggalan)"},{id:2,text:"\u0648\u064e\u0671\u0644\u0651\u064e\u064a\u06e1\u0644\u0650 \u0625\u0650\u0630\u064e\u0627 \u0633\u064e\u062c\u064e\u0649\u0670",translation:"dan demi malam apabila telah sunyi"},{id:3,text:"\u0645\u064e\u0627 \u0648\u064e\u062f\u0651\u064e\u0639\u064e\u0643\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0648\u064e\u0645\u064e\u0627 \u0642\u064e\u0644\u064e\u0649\u0670",translation:"Tuhanmu tidak meninggalkan engkau (Muhammad) dan tidak (pula) membencimu"},{id:4,text:"\u0648\u064e\u0644\u064e\u0644\u06e1\u0623\u0653\u062e\u0650\u0631\u064e\u0629\u064f \u062e\u064e\u064a\u06e1\u0631\u065e \u0644\u0651\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u0623\u064f\u0648\u0644\u064e\u0649\u0670",translation:"dan sungguh, yang kemudian itu lebih baik bagimu daripada yang permulaan"},{id:5,text:"\u0648\u064e\u0644\u064e\u0633\u064e\u0648\u06e1\u0641\u064e \u064a\u064f\u0639\u06e1\u0637\u0650\u064a\u0643\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0641\u064e\u062a\u064e\u0631\u06e1\u0636\u064e\u0649\u0670\u0653",translation:"Dan sungguh, kelak Tuhanmu pasti memberikan karunia-Nya kepadamu, sehingga engkau menjadi puas"},{id:6,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u062c\u0650\u062f\u06e1\u0643\u064e \u064a\u064e\u062a\u0650\u064a\u0645\u0657\u0627 \u0641\u064e\u0640\u0654\u064e\u0627\u0648\u064e\u0649\u0670",translation:"Bukankah Dia mendapatimu sebagai seorang yatim, lalu Dia melindungi(mu)"},{id:7,text:"\u0648\u064e\u0648\u064e\u062c\u064e\u062f\u064e\u0643\u064e \u0636\u064e\u0627\u0653\u0644\u0651\u0657\u0627 \u0641\u064e\u0647\u064e\u062f\u064e\u0649\u0670",translation:"(Dan Dia mendapatimu sebagai seorang yang bingung,912) lalu Dia memberikan petunjuk"},{id:8,text:"\u0648\u064e\u0648\u064e\u062c\u064e\u062f\u064e\u0643\u064e \u0639\u064e\u0627\u0653\u0626\u0650\u0644\u0657\u0627 \u0641\u064e\u0623\u064e\u063a\u06e1\u0646\u064e\u0649\u0670",translation:"Dan Dia mendapatimu sebagai seorang yang kekurangan, lalu Dia memberikan kecukupan"},{id:9,text:"\u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0671\u0644\u06e1\u064a\u064e\u062a\u0650\u064a\u0645\u064e \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u06e1\u0647\u064e\u0631\u06e1",translation:"Maka terhadap anak yatim janganlah engkau berlaku sewenang-wenang"},{id:10,text:"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0671\u0644\u0633\u0651\u064e\u0627\u0653\u0626\u0650\u0644\u064e \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0646\u06e1\u0647\u064e\u0631\u06e1",translation:"Dan terhadap orang yang meminta-minta, janganlah engkau menghardik(nya)"},{id:11,text:"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0628\u0650\u0646\u0650\u0639\u06e1\u0645\u064e\u0629\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0641\u064e\u062d\u064e\u062f\u0651\u0650\u062b\u06e1",translation:"Dan terhadap nikmat Tuhanmu, hendaklah engkau nyatakan (dengan bersyukur)"}]},{id:94,name:"\u0627\u0644\u0634\u0631\u062d",transliteration:"Ash-Sharh",translation:"Melapangkan",type:"meccan",total_verses:8,verses:[{id:1,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u0646\u064e\u0634\u06e1\u0631\u064e\u062d\u06e1 \u0644\u064e\u0643\u064e \u0635\u064e\u062f\u06e1\u0631\u064e\u0643\u064e",translation:"Bukankah kami telah melapangkan dadamu (Muhammad)"},{id:2,text:"\u0648\u064e\u0648\u064e\u0636\u064e\u0639\u06e1\u0646\u064e\u0627 \u0639\u064e\u0646\u0643\u064e \u0648\u0650\u0632\u06e1\u0631\u064e\u0643\u064e",translation:"dan kami pun telah menurunkan beban darimu"},{id:3,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064e\u0646\u0642\u064e\u0636\u064e \u0638\u064e\u0647\u06e1\u0631\u064e\u0643\u064e",translation:"yang memberatkan punggungmu"},{id:4,text:"\u0648\u064e\u0631\u064e\u0641\u064e\u0639\u06e1\u0646\u064e\u0627 \u0644\u064e\u0643\u064e \u0630\u0650\u0643\u06e1\u0631\u064e\u0643\u064e",translation:"dan kami tinggikan sebutan (nama)mu914) bagimu"},{id:5,text:"\u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0645\u064e\u0639\u064e \u0671\u0644\u06e1\u0639\u064f\u0633\u06e1\u0631\u0650 \u064a\u064f\u0633\u06e1\u0631\u064b\u0627",translation:"Maka sesungguhnya bersama kesulitan ada kemudahan"},{id:6,text:"\u0625\u0650\u0646\u0651\u064e \u0645\u064e\u0639\u064e \u0671\u0644\u06e1\u0639\u064f\u0633\u06e1\u0631\u0650 \u064a\u064f\u0633\u06e1\u0631\u0657\u0627",translation:"sesungguhnya bersama kesulitan ada kemudahan"},{id:7,text:"\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0641\u064e\u0631\u064e\u063a\u06e1\u062a\u064e \u0641\u064e\u0671\u0646\u0635\u064e\u0628\u06e1",translation:"Maka apabila engkau telah selesai (dari suatu urusan), tetaplah bekerja keras (untuk urusan yang lain)"},{id:8,text:"\u0648\u064e\u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0641\u064e\u0671\u0631\u06e1\u063a\u064e\u0628",translation:"dan hanya kepada Tuhanmulah engkau berharap"}]},{id:95,name:"\u0627\u0644\u062a\u064a\u0646",transliteration:"At-Tin",translation:"Buah Tin",type:"meccan",total_verses:8,verses:[{id:1,text:"\u0648\u064e\u0671\u0644\u062a\u0651\u0650\u064a\u0646\u0650 \u0648\u064e\u0671\u0644\u0632\u0651\u064e\u064a\u06e1\u062a\u064f\u0648\u0646\u0650",translation:"Demi (buah) Tin dan (buah) Zaitun"},{id:2,text:"\u0648\u064e\u0637\u064f\u0648\u0631\u0650 \u0633\u0650\u064a\u0646\u0650\u064a\u0646\u064e",translation:"demi gunung Sinai"},{id:3,text:"\u0648\u064e\u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u06e1\u0628\u064e\u0644\u064e\u062f\u0650 \u0671\u0644\u06e1\u0623\u064e\u0645\u0650\u064a\u0646\u0650",translation:"dan demi negeri (Mekkah) yang aman ini"},{id:4,text:"\u0644\u064e\u0642\u064e\u062f\u06e1 \u062e\u064e\u0644\u064e\u0642\u06e1\u0646\u064e\u0627 \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064e \u0641\u0650\u064a\u0653 \u0623\u064e\u062d\u06e1\u0633\u064e\u0646\u0650 \u062a\u064e\u0642\u06e1\u0648\u0650\u064a\u0645\u0656",translation:"Sungguh, Kami telah menciptakan manusia dalam bentuk yang sebaik-baiknya"},{id:5,text:"\u062b\u064f\u0645\u0651\u064e \u0631\u064e\u062f\u064e\u062f\u06e1\u0646\u064e\u0670\u0647\u064f \u0623\u064e\u0633\u06e1\u0641\u064e\u0644\u064e \u0633\u064e\u0670\u0641\u0650\u0644\u0650\u064a\u0646\u064e",translation:"kemudian Kami kembalikan dia ke tempat yang serendah-rendahnya"},{id:6,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0641\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0623\u064e\u062c\u06e1\u0631\u064c \u063a\u064e\u064a\u06e1\u0631\u064f \u0645\u064e\u0645\u06e1\u0646\u064f\u0648\u0646\u0656",translation:"kecuali orang-orang yang beriman dan mengerjakan kebajikan; maka mereka akan mendapat pahala yang tidak ada putus-putusnya"},{id:7,text:"\u0641\u064e\u0645\u064e\u0627 \u064a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f\u0643\u064e \u0628\u064e\u0639\u06e1\u062f\u064f \u0628\u0650\u0671\u0644\u062f\u0651\u0650\u064a\u0646\u0650",translation:"Maka apa yang menyebabkan (mereka) mendustakanmu (tentang) hari pembalasan setelah (adanya keterangan-keterangan) itu"},{id:8,text:"\u0623\u064e\u0644\u064e\u064a\u06e1\u0633\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0623\u064e\u062d\u06e1\u0643\u064e\u0645\u0650 \u0671\u0644\u06e1\u062d\u064e\u0670\u0643\u0650\u0645\u0650\u064a\u0646\u064e",translation:"Bukankah Allah Hakim yang paling adil"}]},{id:96,name:"\u0627\u0644\u0639\u0644\u0642",transliteration:"Al-'Alaq",translation:"Segumpal Darah",type:"meccan",total_verses:19,verses:[{id:1,text:"\u0671\u0642\u06e1\u0631\u064e\u0623\u06e1 \u0628\u0650\u0671\u0633\u06e1\u0645\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e",translation:"Bacalah dengan (menyebut) nama Tuhanmu yang menciptakan"},{id:2,text:"\u062e\u064e\u0644\u064e\u0642\u064e \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064e \u0645\u0650\u0646\u06e1 \u0639\u064e\u0644\u064e\u0642\u064d",translation:"Dia telah menciptakan manusia dari segumpal darah"},{id:3,text:"\u0671\u0642\u06e1\u0631\u064e\u0623\u06e1 \u0648\u064e\u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0671\u0644\u06e1\u0623\u064e\u0643\u06e1\u0631\u064e\u0645\u064f",translation:"Bacalah, dan Tuhanmulah Yang Mahamulia"},{id:4,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a \u0639\u064e\u0644\u0651\u064e\u0645\u064e \u0628\u0650\u0671\u0644\u06e1\u0642\u064e\u0644\u064e\u0645\u0650",translation:"Yang mengajar (manusia) dengan pena"},{id:5,text:"\u0639\u064e\u0644\u0651\u064e\u0645\u064e \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064e \u0645\u064e\u0627 \u0644\u064e\u0645\u06e1 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u06e1",translation:"Dia mengajarkan manusia apa yang tidak diketahuinya"},{id:6,text:"\u0643\u064e\u0644\u0651\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064e \u0644\u064e\u064a\u064e\u0637\u06e1\u063a\u064e\u0649\u0670\u0653",translation:"Sekali-sekali tidak! Sungguh, manusia itu benar-benar melampaui batas"},{id:7,text:"\u0623\u064e\u0646 \u0631\u0651\u064e\u0621\u064e\u0627\u0647\u064f \u0671\u0633\u06e1\u062a\u064e\u063a\u06e1\u0646\u064e\u0649\u0670\u0653",translation:"apabila melihat dirinya serba cukup"},{id:8,text:"\u0625\u0650\u0646\u0651\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0671\u0644\u0631\u0651\u064f\u062c\u06e1\u0639\u064e\u0649\u0670\u0653",translation:"Sungguh, hanya kepada Tuhanmulah tempat kembali(mu)"},{id:9,text:"\u0623\u064e\u0631\u064e\u0621\u064e\u064a\u06e1\u062a\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064e\u0646\u06e1\u0647\u064e\u0649\u0670",translation:"Bagaimana pendapatmu tentang orang yang melarang"},{id:10,text:"\u0639\u064e\u0628\u06e1\u062f\u064b\u0627 \u0625\u0650\u0630\u064e\u0627 \u0635\u064e\u0644\u0651\u064e\u0649\u0670\u0653",translation:"seorang hamba ketika dia melaksanakan salat"},{id:11,text:"\u0623\u064e\u0631\u064e\u0621\u064e\u064a\u06e1\u062a\u064e \u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0647\u064f\u062f\u064e\u0649\u0670\u0653",translation:"bagaimana pendapatmu jika dia (yang dilarang salat itu) berada di atas kebenaran (petunjuk)"},{id:12,text:"\u0623\u064e\u0648\u06e1 \u0623\u064e\u0645\u064e\u0631\u064e \u0628\u0650\u0671\u0644\u062a\u0651\u064e\u0642\u06e1\u0648\u064e\u0649\u0670\u0653",translation:"atau dia menyuruh bertakwa (kepada Allah)"},{id:13,text:"\u0623\u064e\u0631\u064e\u0621\u064e\u064a\u06e1\u062a\u064e \u0625\u0650\u0646 \u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0648\u064e\u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649\u0670\u0653",translation:"Bagaimana pendapatmu jika dia (yang melarang) itu mendustakan dan berpaling"},{id:14,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645 \u0628\u0650\u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0631\u064e\u0649\u0670",translation:"Tidakkah dia mengetahui bahwa sesungguhnya Allah melihat (segala perbuatannya)"},{id:15,text:"\u0643\u064e\u0644\u0651\u064e\u0627 \u0644\u064e\u0626\u0650\u0646 \u0644\u0651\u064e\u0645\u06e1 \u064a\u064e\u0646\u062a\u064e\u0647\u0650 \u0644\u064e\u0646\u064e\u0633\u06e1\u0641\u064e\u0639\u064e\u06e2\u0627 \u0628\u0650\u0671\u0644\u0646\u0651\u064e\u0627\u0635\u0650\u064a\u064e\u0629\u0650",translation:"Sekali-kali tidak! Sungguh, jika dia tidak berhenti (berbuat demikian) niscaya Kami tarik ubun-ubunnya (ke dalam neraka)"},{id:16,text:"\u0646\u064e\u0627\u0635\u0650\u064a\u064e\u0629\u0656 \u0643\u064e\u0670\u0630\u0650\u0628\u064e\u0629\u064d \u062e\u064e\u0627\u0637\u0650\u0626\u064e\u0629\u0656",translation:"(yaitu) ubun-ubun orang yang mendustakan dan durhaka"},{id:17,text:"\u0641\u064e\u0644\u06e1\u064a\u064e\u062f\u06e1\u0639\u064f \u0646\u064e\u0627\u062f\u0650\u064a\u064e\u0647\u064f\u06e5",translation:"Maka biarlah dia memanggil golongannya (untuk menolongnya)"},{id:18,text:"\u0633\u064e\u0646\u064e\u062f\u06e1\u0639\u064f \u0671\u0644\u0632\u0651\u064e\u0628\u064e\u0627\u0646\u0650\u064a\u064e\u0629\u064e",translation:"kelak Kami akan memanggil Malaikat Zabaniyah (penyiksa orang-orang yang berdosa)"},{id:19,text:"\u0643\u064e\u0644\u0651\u064e\u0627 \u0644\u064e\u0627 \u062a\u064f\u0637\u0650\u0639\u06e1\u0647\u064f \u0648\u064e\u0671\u0633\u06e1\u062c\u064f\u062f\u06e1\u06e4 \u0648\u064e\u0671\u0642\u06e1\u062a\u064e\u0631\u0650\u0628\u06e9",translation:"sekali-kali tidak! Janganlah kamu patuh kepadanya; dan sujudlah serta dekatkanlah (dirimu kepada Allah)"}]},{id:97,name:"\u0627\u0644\u0642\u062f\u0631",transliteration:"Al-Qadr",translation:"Kemuliaan",type:"meccan",total_verses:5,verses:[{id:1,text:"\u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u06e1\u0646\u064e\u0670\u0647\u064f \u0641\u0650\u064a \u0644\u064e\u064a\u06e1\u0644\u064e\u0629\u0650 \u0671\u0644\u06e1\u0642\u064e\u062f\u06e1\u0631\u0650",translation:"Sesungguhnya Kami telah menurunkannya (Alquran) pada malam qadar"},{id:2,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u062f\u06e1\u0631\u064e\u0649\u0670\u0643\u064e \u0645\u064e\u0627 \u0644\u064e\u064a\u06e1\u0644\u064e\u0629\u064f \u0671\u0644\u06e1\u0642\u064e\u062f\u06e1\u0631\u0650",translation:"Dan tahukah kamu apakah malam kemuliaan itu"},{id:3,text:"\u0644\u064e\u064a\u06e1\u0644\u064e\u0629\u064f \u0671\u0644\u06e1\u0642\u064e\u062f\u06e1\u0631\u0650 \u062e\u064e\u064a\u06e1\u0631\u065e \u0645\u0651\u0650\u0646\u06e1 \u0623\u064e\u0644\u06e1\u0641\u0650 \u0634\u064e\u0647\u06e1\u0631\u0656",translation:"Malam kemuliaan itu lebih baik daripada seribu bulan"},{id:4,text:"\u062a\u064e\u0646\u064e\u0632\u0651\u064e\u0644\u064f \u0671\u0644\u06e1\u0645\u064e\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u064f \u0648\u064e\u0671\u0644\u0631\u0651\u064f\u0648\u062d\u064f \u0641\u0650\u064a\u0647\u064e\u0627 \u0628\u0650\u0625\u0650\u0630\u06e1\u0646\u0650 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645 \u0645\u0651\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u0623\u064e\u0645\u06e1\u0631\u0656",translation:"Pada malam itu turun para malaikat dan Ruh (Jibril) dengan izin Tuhannya untuk mengatur semua urusan"},{id:5,text:"\u0633\u064e\u0644\u064e\u0670\u0645\u064c \u0647\u0650\u064a\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0645\u064e\u0637\u06e1\u0644\u064e\u0639\u0650 \u0671\u0644\u06e1\u0641\u064e\u062c\u06e1\u0631\u0650",translation:"Sejahteralah (malam itu) sampai terbit fajar"}]},{id:98,name:"\u0627\u0644\u0628\u064a\u0646\u0629",transliteration:"Al-Bayyinah",translation:"Pembuktian",type:"medinan",total_verses:8,verses:[{id:1,text:"\u0644\u064e\u0645\u06e1 \u064a\u064e\u0643\u064f\u0646\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1 \u0623\u064e\u0647\u06e1\u0644\u0650 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0634\u06e1\u0631\u0650\u0643\u0650\u064a\u0646\u064e \u0645\u064f\u0646\u0641\u064e\u0643\u0651\u0650\u064a\u0646\u064e \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u062a\u064e\u0623\u06e1\u062a\u0650\u064a\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0629\u064f",translation:"Orang-orang yang kafir dari golongan Ahli Kitab dan orang-orang musyrik tidak akan meninggalkan (agama mereka) sampai datang kepada mereka bukti yang nyata"},{id:2,text:"\u0631\u064e\u0633\u064f\u0648\u0644\u065e \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u062a\u06e1\u0644\u064f\u0648\u0627\u0652 \u0635\u064f\u062d\u064f\u0641\u0657\u0627 \u0645\u0651\u064f\u0637\u064e\u0647\u0651\u064e\u0631\u064e\u0629\u0657",translation:"(yaitu) seorang Rasul dari Allah (Muhammad) yang membacakan lembaran-lembaran yang suci (Alquran)"},{id:3,text:"\u0641\u0650\u064a\u0647\u064e\u0627 \u0643\u064f\u062a\u064f\u0628\u065e \u0642\u064e\u064a\u0651\u0650\u0645\u064e\u0629\u065e",translation:"di dalamnya terdapat (isi) kitab-kitab yang lurus (benar)"},{id:4,text:"\u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0641\u064e\u0631\u0651\u064e\u0642\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627\u0652 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u06e1\u062f\u0650 \u0645\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e\u062a\u06e1\u0647\u064f\u0645\u064f \u0671\u0644\u06e1\u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0629\u064f",translation:"Dan tidaklah terpecah belah orang-orang Ahli Kitab melainkan setelah datang kepada mereka bukti yang nyata"},{id:5,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0645\u0650\u0631\u064f\u0648\u0653\u0627\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0644\u0650\u064a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0627\u0652 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0645\u064f\u062e\u06e1\u0644\u0650\u0635\u0650\u064a\u0646\u064e \u0644\u064e\u0647\u064f \u0671\u0644\u062f\u0651\u0650\u064a\u0646\u064e \u062d\u064f\u0646\u064e\u0641\u064e\u0627\u0653\u0621\u064e \u0648\u064e\u064a\u064f\u0642\u0650\u064a\u0645\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u064a\u064f\u0624\u06e1\u062a\u064f\u0648\u0627\u0652 \u0671\u0644\u0632\u0651\u064e\u0643\u064e\u0648\u0670\u0629\u064e\u06da \u0648\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u062f\u0650\u064a\u0646\u064f \u0671\u0644\u06e1\u0642\u064e\u064a\u0651\u0650\u0645\u064e\u0629\u0650",translation:"Padahal mereka hanya diperintah menyembah Allah dengan ikhlas menaati-Nya semata-mata karena (menjalankan) agama, dan juga agar melaksanakan salat dan menunaikan zakat; dan yang demikian itulah agama yang lurus (benar)"},{id:6,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u0652 \u0645\u0650\u0646\u06e1 \u0623\u064e\u0647\u06e1\u0644\u0650 \u0671\u0644\u06e1\u0643\u0650\u062a\u064e\u0670\u0628\u0650 \u0648\u064e\u0671\u0644\u06e1\u0645\u064f\u0634\u06e1\u0631\u0650\u0643\u0650\u064a\u0646\u064e \u0641\u0650\u064a \u0646\u064e\u0627\u0631\u0650 \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u062e\u064e\u0670\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627\u0653\u06da \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u06e1 \u0634\u064e\u0631\u0651\u064f \u0671\u0644\u06e1\u0628\u064e\u0631\u0650\u064a\u0651\u064e\u0629\u0650",translation:"Sungguh, orang-orang yang kafir dari golongan Ahli Kitab dan orang-orang musyrik (akan masuk) ke neraka Jahanam; mereka kekal di dalamnya selama-lamanya. Mereka itu adalah sejahat-jahat makhluk"},{id:7,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0623\u064f\u0648\u0652\u0644\u064e\u0640\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u06e1 \u062e\u064e\u064a\u06e1\u0631\u064f \u0671\u0644\u06e1\u0628\u064e\u0631\u0650\u064a\u0651\u064e\u0629\u0650",translation:"Sungguh, orang-orang yang beriman dan mengerjakan kebajikan, mereka itulah sebaik-baik makhluk"},{id:8,text:"\u062c\u064e\u0632\u064e\u0627\u0653\u0624\u064f\u0647\u064f\u0645\u06e1 \u0639\u0650\u0646\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u06e1 \u062c\u064e\u0646\u0651\u064e\u0640\u0670\u062a\u064f \u0639\u064e\u062f\u06e1\u0646\u0656 \u062a\u064e\u062c\u06e1\u0631\u0650\u064a \u0645\u0650\u0646 \u062a\u064e\u062d\u06e1\u062a\u0650\u0647\u064e\u0627 \u0671\u0644\u06e1\u0623\u064e\u0646\u06e1\u0647\u064e\u0670\u0631\u064f \u062e\u064e\u0670\u0644\u0650\u062f\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627\u0653 \u0623\u064e\u0628\u064e\u062f\u0657\u0627\u06d6 \u0631\u0651\u064e\u0636\u0650\u064a\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0646\u06e1\u0647\u064f\u0645\u06e1 \u0648\u064e\u0631\u064e\u0636\u064f\u0648\u0627\u0652 \u0639\u064e\u0646\u06e1\u0647\u064f\u06da \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u0650\u0645\u064e\u0646\u06e1 \u062e\u064e\u0634\u0650\u064a\u064e \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u06e5",translation:"Balasan mereka di sisi Tuhan mereka ialah surga '\u0100dn yang mengalir di bawahnya sungai-sungai; mereka kekal di dalamnya selama-lamanya. Allah rida terhadap mereka dan mereka pun rida kepada-Nya. Yang demikian itu adalah (balasan) bagi orang yang takut kepada Tuhannya"}]},{id:99,name:"\u0627\u0644\u0632\u0644\u0632\u0644\u0629",transliteration:"Az-Zalzalah",translation:"Kegoncangan",type:"medinan",total_verses:8,verses:[{id:1,text:"\u0625\u0650\u0630\u064e\u0627 \u0632\u064f\u0644\u06e1\u0632\u0650\u0644\u064e\u062a\u0650 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064f \u0632\u0650\u0644\u06e1\u0632\u064e\u0627\u0644\u064e\u0647\u064e\u0627",translation:"Apabila bumi diguncangkan dengan guncangan yang dahsyat"},{id:2,text:"\u0648\u064e\u0623\u064e\u062e\u06e1\u0631\u064e\u062c\u064e\u062a\u0650 \u0671\u0644\u06e1\u0623\u064e\u0631\u06e1\u0636\u064f \u0623\u064e\u062b\u06e1\u0642\u064e\u0627\u0644\u064e\u0647\u064e\u0627",translation:"dan bumi telah mengeluarkan beban-beban berat (yang dikandung)nya"},{id:3,text:"\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064f \u0645\u064e\u0627 \u0644\u064e\u0647\u064e\u0627",translation:"dan manusia bertanya, \"Apa yang terjadi pada bumi ini"},{id:4,text:"\u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u062a\u064f\u062d\u064e\u062f\u0651\u0650\u062b\u064f \u0623\u064e\u062e\u06e1\u0628\u064e\u0627\u0631\u064e\u0647\u064e\u0627",translation:"Pada hari itu bumi menyampaikan beritanya"},{id:5,text:"\u0628\u0650\u0623\u064e\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0623\u064e\u0648\u06e1\u062d\u064e\u0649\u0670 \u0644\u064e\u0647\u064e\u0627",translation:"karena sesungguhnya Tuhanmu telah memerintahkan (yang sedemikian itu) padanya"},{id:6,text:"\u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u064a\u064e\u0635\u06e1\u062f\u064f\u0631\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0623\u064e\u0634\u06e1\u062a\u064e\u0627\u062a\u0657\u0627 \u0644\u0651\u0650\u064a\u064f\u0631\u064e\u0648\u06e1\u0627\u0652 \u0623\u064e\u0639\u06e1\u0645\u064e\u0670\u0644\u064e\u0647\u064f\u0645\u06e1",translation:"(Pada hari itu manusia keluar dari kuburnya dalam keadaan berkelompok-kelompok,922) untuk diperlihatkan kepada mereka (balasan) semua amal perbuatannya"},{id:7,text:"\u0641\u064e\u0645\u064e\u0646 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u06e1 \u0645\u0650\u062b\u06e1\u0642\u064e\u0627\u0644\u064e \u0630\u064e\u0631\u0651\u064e\u0629\u064d \u062e\u064e\u064a\u06e1\u0631\u0657\u0627 \u064a\u064e\u0631\u064e\u0647\u064f\u06e5",translation:"Maka barangsiapa mengerjakan kebaikan seberat zarah, niscaya dia akan melihat (balasan)nya"},{id:8,text:"\u0648\u064e\u0645\u064e\u0646 \u064a\u064e\u0639\u06e1\u0645\u064e\u0644\u06e1 \u0645\u0650\u062b\u06e1\u0642\u064e\u0627\u0644\u064e \u0630\u064e\u0631\u0651\u064e\u0629\u0656 \u0634\u064e\u0631\u0651\u0657\u0627 \u064a\u064e\u0631\u064e\u0647\u064f\u06e5",translation:"Dan barangsiapa mengerjakan kejahatan seberat zarah, niscaya dia akan melihat (balasan)nya"}]},{id:100,name:"\u0627\u0644\u0639\u0627\u062f\u064a\u0627\u062a",transliteration:"Al-'Adiyat",translation:"Berlari Kencang",type:"meccan",total_verses:11,verses:[{id:1,text:"\u0648\u064e\u0671\u0644\u06e1\u0639\u064e\u0670\u062f\u0650\u064a\u064e\u0670\u062a\u0650 \u0636\u064e\u0628\u06e1\u062d\u0657\u0627",translation:"Demi kuda perang yang berlari kencang terengah-engah"},{id:2,text:"\u0641\u064e\u0671\u0644\u06e1\u0645\u064f\u0648\u0631\u0650\u064a\u064e\u0670\u062a\u0650 \u0642\u064e\u062f\u06e1\u062d\u0657\u0627",translation:"dan kuda yang memercikkan bunga api (dengan pukulan kuku kakinya)"},{id:3,text:"\u0641\u064e\u0671\u0644\u06e1\u0645\u064f\u063a\u0650\u064a\u0631\u064e\u0670\u062a\u0650 \u0635\u064f\u0628\u06e1\u062d\u0657\u0627",translation:"dan kuda yang menyerang (dengan tiba-tiba) pada waktu pagi"},{id:4,text:"\u0641\u064e\u0623\u064e\u062b\u064e\u0631\u06e1\u0646\u064e \u0628\u0650\u0647\u0650\u06e6 \u0646\u064e\u0642\u06e1\u0639\u0657\u0627",translation:"sehingga menerbangkan debu"},{id:5,text:"\u0641\u064e\u0648\u064e\u0633\u064e\u0637\u06e1\u0646\u064e \u0628\u0650\u0647\u0650\u06e6 \u062c\u064e\u0645\u06e1\u0639\u064b\u0627",translation:"lalu menyerbu ke tengah-tengah kumpulan musuh"},{id:6,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064e \u0644\u0650\u0631\u064e\u0628\u0651\u0650\u0647\u0650\u06e6 \u0644\u064e\u0643\u064e\u0646\u064f\u0648\u062f\u065e",translation:"sungguh, manusia itu sangat ingkar, (tidak bersyukur) kepada Tuhannya"},{id:7,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0639\u064e\u0644\u064e\u0649\u0670 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0634\u064e\u0647\u0650\u064a\u062f\u065e",translation:"dan sesungguhnya dia (manusia) menyaksikan (mengakui) keingkarannya"},{id:8,text:"\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0644\u0650\u062d\u064f\u0628\u0651\u0650 \u0671\u0644\u06e1\u062e\u064e\u064a\u06e1\u0631\u0650 \u0644\u064e\u0634\u064e\u062f\u0650\u064a\u062f\u064c",translation:"dan sesungguhnya cintanya kepada harta benar-benar berlebihan"},{id:9,text:"\u06de\u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f \u0625\u0650\u0630\u064e\u0627 \u0628\u064f\u0639\u06e1\u062b\u0650\u0631\u064e \u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u06e1\u0642\u064f\u0628\u064f\u0648\u0631\u0650",translation:"Maka tidakkah dia mengetahui apabila apa yang di dalam kubur dikeluarkan"},{id:10,text:"\u0648\u064e\u062d\u064f\u0635\u0651\u0650\u0644\u064e \u0645\u064e\u0627 \u0641\u0650\u064a \u0671\u0644\u0635\u0651\u064f\u062f\u064f\u0648\u0631\u0650",translation:"dan apa yang tersimpan di dalam dada dikeluarkan"},{id:11,text:"\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u0645 \u0628\u0650\u0647\u0650\u0645\u06e1 \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u0656 \u0644\u0651\u064e\u062e\u064e\u0628\u0650\u064a\u0631\u064f\u06e2",translation:"sungguh, Tuhan mereka pada hari itu Mahateliti terhadap keadaan mereka"}]},{id:101,name:"\u0627\u0644\u0642\u0627\u0631\u0639\u0629",transliteration:"Al-Qari'ah",translation:"Hari Kiamat",type:"meccan",total_verses:11,verses:[{id:1,text:"\u0671\u0644\u06e1\u0642\u064e\u0627\u0631\u0650\u0639\u064e\u0629\u064f",translation:"Hari Kiamat"},{id:2,text:"\u0645\u064e\u0627 \u0671\u0644\u06e1\u0642\u064e\u0627\u0631\u0650\u0639\u064e\u0629\u064f",translation:"Apakah hari Kiamat itu"},{id:3,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u062f\u06e1\u0631\u064e\u0649\u0670\u0643\u064e \u0645\u064e\u0627 \u0671\u0644\u06e1\u0642\u064e\u0627\u0631\u0650\u0639\u064e\u0629\u064f",translation:"Dan tahukah kamu apakah hari Kiamat itu"},{id:4,text:"\u064a\u064e\u0648\u06e1\u0645\u064e \u064a\u064e\u0643\u064f\u0648\u0646\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0643\u064e\u0671\u0644\u06e1\u0641\u064e\u0631\u064e\u0627\u0634\u0650 \u0671\u0644\u06e1\u0645\u064e\u0628\u06e1\u062b\u064f\u0648\u062b\u0650",translation:"Pada hari itu manusia seperti laron yang beterbangan"},{id:5,text:"\u0648\u064e\u062a\u064e\u0643\u064f\u0648\u0646\u064f \u0671\u0644\u06e1\u062c\u0650\u0628\u064e\u0627\u0644\u064f \u0643\u064e\u0671\u0644\u06e1\u0639\u0650\u0647\u06e1\u0646\u0650 \u0671\u0644\u06e1\u0645\u064e\u0646\u0641\u064f\u0648\u0634\u0650",translation:"dan gunung-gunung seperti bulu yang dihambur-hamburkan"},{id:6,text:"\u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0645\u064e\u0646 \u062b\u064e\u0642\u064f\u0644\u064e\u062a\u06e1 \u0645\u064e\u0648\u064e\u0670\u0632\u0650\u064a\u0646\u064f\u0647\u064f\u06e5",translation:"Maka adapun orang yang berat timbangan (kebaikan)nya"},{id:7,text:"\u0641\u064e\u0647\u064f\u0648\u064e \u0641\u0650\u064a \u0639\u0650\u064a\u0634\u064e\u0629\u0656 \u0631\u0651\u064e\u0627\u0636\u0650\u064a\u064e\u0629\u0656",translation:"maka dia berada dalam kehidupan yang memuaskan (senang)"},{id:8,text:"\u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0645\u064e\u0646\u06e1 \u062e\u064e\u0641\u0651\u064e\u062a\u06e1 \u0645\u064e\u0648\u064e\u0670\u0632\u0650\u064a\u0646\u064f\u0647\u064f\u06e5",translation:"Dan adapun orang yang ringan timbangan (kebaikan)nya"},{id:9,text:"\u0641\u064e\u0623\u064f\u0645\u0651\u064f\u0647\u064f\u06e5 \u0647\u064e\u0627\u0648\u0650\u064a\u064e\u0629\u065e",translation:"maka tempat kembalinya adalah neraka H\u0101wiyah"},{id:10,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u062f\u06e1\u0631\u064e\u0649\u0670\u0643\u064e \u0645\u064e\u0627 \u0647\u0650\u064a\u064e\u0647\u06e1",translation:"Dan tahukah kamu apakah neraka H\u0101wiyah itu"},{id:11,text:"\u0646\u064e\u0627\u0631\u064c \u062d\u064e\u0627\u0645\u0650\u064a\u064e\u0629\u064f\u06e2",translation:"(Yaitu) api yang sangat panas"}]},{id:102,name:"\u0627\u0644\u062a\u0643\u0627\u062b\u0631",transliteration:"At-Takathur",translation:"Bermegah-megahan",type:"meccan",total_verses:8,verses:[{id:1,text:"\u0623\u064e\u0644\u06e1\u0647\u064e\u0649\u0670\u0643\u064f\u0645\u064f \u0671\u0644\u062a\u0651\u064e\u0643\u064e\u0627\u062b\u064f\u0631\u064f",translation:"Bermegah-megahan telah melalaikan kamu"},{id:2,text:"\u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u0632\u064f\u0631\u06e1\u062a\u064f\u0645\u064f \u0671\u0644\u06e1\u0645\u064e\u0642\u064e\u0627\u0628\u0650\u0631\u064e",translation:"sampai kamu masuk ke dalam kubur"},{id:3,text:"\u0643\u064e\u0644\u0651\u064e\u0627 \u0633\u064e\u0648\u06e1\u0641\u064e \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"Sekali-kali tidak! Kelak kamu akan mengetahui (akibat perbuatanmu itu)"},{id:4,text:"\u062b\u064f\u0645\u0651\u064e \u0643\u064e\u0644\u0651\u064e\u0627 \u0633\u064e\u0648\u06e1\u0641\u064e \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e",translation:"kemudian sekali-kali tidak! Kelak kamu akan mengetahui"},{id:5,text:"\u0643\u064e\u0644\u0651\u064e\u0627 \u0644\u064e\u0648\u06e1 \u062a\u064e\u0639\u06e1\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0639\u0650\u0644\u06e1\u0645\u064e \u0671\u0644\u06e1\u064a\u064e\u0642\u0650\u064a\u0646\u0650",translation:"Sekali-kali tidak! Sekiranya kamu mengetahui dengan pasti"},{id:6,text:"\u0644\u064e\u062a\u064e\u0631\u064e\u0648\u064f\u0646\u0651\u064e \u0671\u0644\u06e1\u062c\u064e\u062d\u0650\u064a\u0645\u064e",translation:"niscaya kamu benar-benar akan melihat neraka Jahim"},{id:7,text:"\u062b\u064f\u0645\u0651\u064e \u0644\u064e\u062a\u064e\u0631\u064e\u0648\u064f\u0646\u0651\u064e\u0647\u064e\u0627 \u0639\u064e\u064a\u06e1\u0646\u064e \u0671\u0644\u06e1\u064a\u064e\u0642\u0650\u064a\u0646\u0650",translation:"kemudian kamu benar-benar akan melihatnya dengan mata kepala sendiri"},{id:8,text:"\u062b\u064f\u0645\u0651\u064e \u0644\u064e\u062a\u064f\u0633\u06e1\u0640\u0654\u064e\u0644\u064f\u0646\u0651\u064e \u064a\u064e\u0648\u06e1\u0645\u064e\u0626\u0650\u0630\u064d \u0639\u064e\u0646\u0650 \u0671\u0644\u0646\u0651\u064e\u0639\u0650\u064a\u0645\u0650",translation:"kemudian kamu benar-benar akan ditanya pada hari itu tentang kenikmatan (yang megah di dunia itu)"}]},{id:103,name:"\u0627\u0644\u0639\u0635\u0631",transliteration:"Al-'Asr",translation:"Waktu Sore",type:"meccan",total_verses:3,verses:[{id:1,text:"\u0648\u064e\u0671\u0644\u06e1\u0639\u064e\u0635\u06e1\u0631\u0650",translation:"Demi masa"},{id:2,text:"\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u06e1\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064e \u0644\u064e\u0641\u0650\u064a \u062e\u064f\u0633\u06e1\u0631\u064d",translation:"Sungguh, manusia berada dalam kerugian"},{id:3,text:"\u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u0640\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0648\u064e\u062a\u064e\u0648\u064e\u0627\u0635\u064e\u0648\u06e1\u0627\u0652 \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u062a\u064e\u0648\u064e\u0627\u0635\u064e\u0648\u06e1\u0627\u0652 \u0628\u0650\u0671\u0644\u0635\u0651\u064e\u0628\u06e1\u0631\u0650",translation:"kecuali orang-orang yang beriman dan mengerjakan kebajikan serta saling menasihati untuk kebenaran dan saling menasihati untuk kesabaran"}]},{id:104,name:"\u0627\u0644\u0647\u0645\u0632\u0629",transliteration:"Al-Humazah",translation:"Pengumpat",type:"meccan",total_verses:9,verses:[{id:1,text:"\u0648\u064e\u064a\u06e1\u0644\u065e \u0644\u0651\u0650\u0643\u064f\u0644\u0651\u0650 \u0647\u064f\u0645\u064e\u0632\u064e\u0629\u0656 \u0644\u0651\u064f\u0645\u064e\u0632\u064e\u0629\u064d",translation:"Celakalah bagi setiap pengumpat dan pencela"},{id:2,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0645\u064e\u0639\u064e \u0645\u064e\u0627\u0644\u0657\u0627 \u0648\u064e\u0639\u064e\u062f\u0651\u064e\u062f\u064e\u0647\u064f\u06e5",translation:"yang mengumpulkan harta dan menghitung-hitungnya"},{id:3,text:"\u064a\u064e\u062d\u06e1\u0633\u064e\u0628\u064f \u0623\u064e\u0646\u0651\u064e \u0645\u064e\u0627\u0644\u064e\u0647\u064f\u06e5\u0653 \u0623\u064e\u062e\u06e1\u0644\u064e\u062f\u064e\u0647\u064f\u06e5",translation:"dia (manusia) mengira bahwa hartanya itu dapat mengekalkannya"},{id:4,text:"\u0643\u064e\u0644\u0651\u064e\u0627\u06d6 \u0644\u064e\u064a\u064f\u0646\u06e2\u0628\u064e\u0630\u064e\u0646\u0651\u064e \u0641\u0650\u064a \u0671\u0644\u06e1\u062d\u064f\u0637\u064e\u0645\u064e\u0629\u0650",translation:"Sekali-kali tidak! Pasti dia akan dilemparkan ke dalam (neraka) \u1e24u\u1e6damah"},{id:5,text:"\u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u062f\u06e1\u0631\u064e\u0649\u0670\u0643\u064e \u0645\u064e\u0627 \u0671\u0644\u06e1\u062d\u064f\u0637\u064e\u0645\u064e\u0629\u064f",translation:"Dan tahukah kamu apakah (neraka) \u1e24u\u1e6damah itu"},{id:6,text:"\u0646\u064e\u0627\u0631\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0671\u0644\u06e1\u0645\u064f\u0648\u0642\u064e\u062f\u064e\u0629\u064f",translation:"(Yaitu) api (azab) Allah yang dinyalakan"},{id:7,text:"\u0671\u0644\u0651\u064e\u062a\u0650\u064a \u062a\u064e\u0637\u0651\u064e\u0644\u0650\u0639\u064f \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u06e1\u0623\u064e\u0641\u06e1\u0640\u0654\u0650\u062f\u064e\u0629\u0650",translation:"yang (membakar) sampai ke hati"},{id:8,text:"\u0625\u0650\u0646\u0651\u064e\u0647\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645 \u0645\u0651\u064f\u0624\u06e1\u0635\u064e\u062f\u064e\u0629\u065e",translation:"Sungguh, api itu ditutup rapat atas (diri) mereka"},{id:9,text:"\u0641\u0650\u064a \u0639\u064e\u0645\u064e\u062f\u0656 \u0645\u0651\u064f\u0645\u064e\u062f\u0651\u064e\u062f\u064e\u0629\u0650\u06ed",translation:"(sedang mereka itu) diikat pada tiang-tiang yang panjang"}]},{id:105,name:"\u0627\u0644\u0641\u064a\u0644",transliteration:"Al-Fil",translation:"Gajah",type:"meccan",total_verses:5,verses:[{id:1,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u062a\u064e\u0631\u064e \u0643\u064e\u064a\u06e1\u0641\u064e \u0641\u064e\u0639\u064e\u0644\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0628\u0650\u0623\u064e\u0635\u06e1\u062d\u064e\u0670\u0628\u0650 \u0671\u0644\u06e1\u0641\u0650\u064a\u0644\u0650",translation:"Tidakkah engkau (Muhammad) perhatikan bagaimana Tuhanmu telah bertindak terhadap pasukan bergajah"},{id:2,text:"\u0623\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u062c\u06e1\u0639\u064e\u0644\u06e1 \u0643\u064e\u064a\u06e1\u062f\u064e\u0647\u064f\u0645\u06e1 \u0641\u0650\u064a \u062a\u064e\u0636\u06e1\u0644\u0650\u064a\u0644\u0656",translation:"Bukankah Dia telah menjadikan tipu daya mereka itu sia-sia"},{id:3,text:"\u0648\u064e\u0623\u064e\u0631\u06e1\u0633\u064e\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u06e1\u0647\u0650\u0645\u06e1 \u0637\u064e\u064a\u06e1\u0631\u064b\u0627 \u0623\u064e\u0628\u064e\u0627\u0628\u0650\u064a\u0644\u064e",translation:"dan Dia mengirimkan kepada mereka burung yang berbondong-bondong"},{id:4,text:"\u062a\u064e\u0631\u06e1\u0645\u0650\u064a\u0647\u0650\u0645 \u0628\u0650\u062d\u0650\u062c\u064e\u0627\u0631\u064e\u0629\u0656 \u0645\u0651\u0650\u0646 \u0633\u0650\u062c\u0651\u0650\u064a\u0644\u0656",translation:"yang melempari mereka dengan batu dari tanah liat yang dibakar"},{id:5,text:"\u0641\u064e\u062c\u064e\u0639\u064e\u0644\u064e\u0647\u064f\u0645\u06e1 \u0643\u064e\u0639\u064e\u0635\u06e1\u0641\u0656 \u0645\u0651\u064e\u0623\u06e1\u0643\u064f\u0648\u0644\u0650\u06ed",translation:"sehingga mereka dijadikan-Nya seperti daun-daun yang dimakan (ulat)"}]},{id:106,name:"\u0642\u0631\u064a\u0634",transliteration:"Quraysh",translation:"Suku Quraisy",type:"meccan",total_verses:4,verses:[{id:1,text:"\u0644\u0650\u0625\u0650\u064a\u0644\u064e\u0670\u0641\u0650 \u0642\u064f\u0631\u064e\u064a\u06e1\u0634\u064d",translation:"Karena kebiasaan orang-orang Quraisy"},{id:2,text:"\u0625\u0650\u06e6\u0644\u064e\u0670\u0641\u0650\u0647\u0650\u0645\u06e1 \u0631\u0650\u062d\u06e1\u0644\u064e\u0629\u064e \u0671\u0644\u0634\u0651\u0650\u062a\u064e\u0627\u0653\u0621\u0650 \u0648\u064e\u0671\u0644\u0635\u0651\u064e\u064a\u06e1\u0641\u0650",translation:"(yaitu) kebiasaan mereka bepergian pada musim dingin dan musim panas"},{id:3,text:"\u0641\u064e\u0644\u06e1\u064a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0627\u0652 \u0631\u064e\u0628\u0651\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u06e1\u0628\u064e\u064a\u06e1\u062a\u0650",translation:"Maka hendaklah mereka menyembah Tuhan (pemilik) rumah ini (Ka'bah)"},{id:4,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0653 \u0623\u064e\u0637\u06e1\u0639\u064e\u0645\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u062c\u064f\u0648\u0639\u0656 \u0648\u064e\u0621\u064e\u0627\u0645\u064e\u0646\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u06e1 \u062e\u064e\u0648\u06e1\u0641\u0650\u06ed",translation:"yang telah memberi makanan kepada mereka untuk menghilangkan lapar dan mengamankan mereka dari rasa ketakutan"}]},{id:107,name:"\u0627\u0644\u0645\u0627\u0639\u0648\u0646",transliteration:"Al-Ma'un",translation:"Barang yang Berguna",type:"meccan",total_verses:7,verses:[{id:1,text:"\u0623\u064e\u0631\u064e\u0621\u064e\u064a\u06e1\u062a\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f \u0628\u0650\u0671\u0644\u062f\u0651\u0650\u064a\u0646\u0650",translation:"Tahukah kamu (orang) yang mendustakan agama"},{id:2,text:"\u0641\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064e\u062f\u064f\u0639\u0651\u064f \u0671\u0644\u06e1\u064a\u064e\u062a\u0650\u064a\u0645\u064e",translation:"Maka itulah orang yang menghardik anak yatim"},{id:3,text:"\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062d\u064f\u0636\u0651\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0637\u064e\u0639\u064e\u0627\u0645\u0650 \u0671\u0644\u06e1\u0645\u0650\u0633\u06e1\u0643\u0650\u064a\u0646\u0650",translation:"dan tidak mengajak memberi makan orang miskin"},{id:4,text:"\u0641\u064e\u0648\u064e\u064a\u06e1\u0644\u065e \u0644\u0651\u0650\u0644\u06e1\u0645\u064f\u0635\u064e\u0644\u0651\u0650\u064a\u0646\u064e",translation:"Maka celakalah orang yang salat"},{id:5,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645\u06e1 \u0639\u064e\u0646 \u0635\u064e\u0644\u064e\u0627\u062a\u0650\u0647\u0650\u0645\u06e1 \u0633\u064e\u0627\u0647\u064f\u0648\u0646\u064e",translation:"(yaitu) orang-orang yang lalai terhadap salatnya"},{id:6,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064f\u0645\u06e1 \u064a\u064f\u0631\u064e\u0627\u0653\u0621\u064f\u0648\u0646\u064e",translation:"yang berbuat riya"},{id:7,text:"\u0648\u064e\u064a\u064e\u0645\u06e1\u0646\u064e\u0639\u064f\u0648\u0646\u064e \u0671\u0644\u06e1\u0645\u064e\u0627\u0639\u064f\u0648\u0646\u064e",translation:"dan enggan (memberikan) bantuan"}]},{id:108,name:"\u0627\u0644\u0643\u0648\u062b\u0631",transliteration:"Al-Kawthar",translation:"Nikmat Berlimpah",type:"meccan",total_verses:3,verses:[{id:1,text:"\u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u0639\u06e1\u0637\u064e\u064a\u06e1\u0646\u064e\u0670\u0643\u064e \u0671\u0644\u06e1\u0643\u064e\u0648\u06e1\u062b\u064e\u0631\u064e",translation:"Sungguh, Kami telah memberimu (Muhammad) nikmat yang banyak"},{id:2,text:"\u0641\u064e\u0635\u064e\u0644\u0651\u0650 \u0644\u0650\u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0648\u064e\u0671\u0646\u06e1\u062d\u064e\u0631\u06e1",translation:"Maka laksanakanlah salat karena Tuhanmu, dan berkurbanlah (sebagai ibadah dan mendekatkan diri kepada Allah)"},{id:3,text:"\u0625\u0650\u0646\u0651\u064e \u0634\u064e\u0627\u0646\u0650\u0626\u064e\u0643\u064e \u0647\u064f\u0648\u064e \u0671\u0644\u06e1\u0623\u064e\u0628\u06e1\u062a\u064e\u0631\u064f",translation:"Sungguh, orang-orang yang membencimu dialah yang terputus (dari rahmat Allah)"}]},{id:109,name:"\u0627\u0644\u0643\u0627\u0641\u0631\u0648\u0646",transliteration:"Al-Kafirun",translation:"Orang-orang Kafir",type:"meccan",total_verses:6,verses:[{id:1,text:"\u0642\u064f\u0644\u06e1 \u064a\u064e\u0640\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u06e1\u0643\u064e\u0670\u0641\u0650\u0631\u064f\u0648\u0646\u064e",translation:"Katakanlah (Muhammad), \"Wahai orang-orang kafir"},{id:2,text:"\u0644\u064e\u0627\u0653 \u0623\u064e\u0639\u06e1\u0628\u064f\u062f\u064f \u0645\u064e\u0627 \u062a\u064e\u0639\u06e1\u0628\u064f\u062f\u064f\u0648\u0646\u064e",translation:"aku tidak akan menyembah apa yang kamu sembah"},{id:3,text:"\u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0639\u064e\u0670\u0628\u0650\u062f\u064f\u0648\u0646\u064e \u0645\u064e\u0627\u0653 \u0623\u064e\u0639\u06e1\u0628\u064f\u062f\u064f",translation:"dan kamu bukan penyembah apa yang aku sembah"},{id:4,text:"\u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064e\u0646\u064e\u0627\u06e0 \u0639\u064e\u0627\u0628\u0650\u062f\u065e \u0645\u0651\u064e\u0627 \u0639\u064e\u0628\u064e\u062f\u062a\u0651\u064f\u0645\u06e1",translation:"dan aku tidak pernah menjadi penyembah apa yang kamu sembah"},{id:5,text:"\u0648\u064e\u0644\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u0639\u064e\u0670\u0628\u0650\u062f\u064f\u0648\u0646\u064e \u0645\u064e\u0627\u0653 \u0623\u064e\u0639\u06e1\u0628\u064f\u062f\u064f",translation:"dan kamu tidak pernah (pula) menjadi penyembah apa yang aku sembah"},{id:6,text:"\u0644\u064e\u0643\u064f\u0645\u06e1 \u062f\u0650\u064a\u0646\u064f\u0643\u064f\u0645\u06e1 \u0648\u064e\u0644\u0650\u064a\u064e \u062f\u0650\u064a\u0646\u0650",translation:"Untukmu agamamu, dan untukku agamaku"}]},{id:110,name:"\u0627\u0644\u0646\u0635\u0631",transliteration:"An-Nasr",translation:"Pertolongan",type:"medinan",total_verses:3,verses:[{id:1,text:"\u0625\u0650\u0630\u064e\u0627 \u062c\u064e\u0627\u0653\u0621\u064e \u0646\u064e\u0635\u06e1\u0631\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0671\u0644\u06e1\u0641\u064e\u062a\u06e1\u062d\u064f",translation:"Apabila telah datang pertolongan Allah dan kemenangan"},{id:2,text:"\u0648\u064e\u0631\u064e\u0623\u064e\u064a\u06e1\u062a\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u064a\u064e\u062f\u06e1\u062e\u064f\u0644\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u062f\u0650\u064a\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0641\u06e1\u0648\u064e\u0627\u062c\u0657\u0627",translation:"dan engkau melihat manusia berbondong-bondong masuk agama Allah"},{id:3,text:"\u0641\u064e\u0633\u064e\u0628\u0651\u0650\u062d\u06e1 \u0628\u0650\u062d\u064e\u0645\u06e1\u062f\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0648\u064e\u0671\u0633\u06e1\u062a\u064e\u063a\u06e1\u0641\u0650\u0631\u06e1\u0647\u064f\u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0643\u064e\u0627\u0646\u064e \u062a\u064e\u0648\u0651\u064e\u0627\u0628\u064e\u06e2\u0627",translation:"maka bertasbihlah dengan memuji Tuhanmu dan mohonlah ampunan kepada-Nya. Sungguh, Dia Maha Penerima tobat"}]},{id:111,name:"\u0627\u0644\u0645\u0633\u062f",transliteration:"Al-Masad",translation:"Gejolak Api (Sabut)",type:"meccan",total_verses:5,verses:[{id:1,text:"\u062a\u064e\u0628\u0651\u064e\u062a\u06e1 \u064a\u064e\u062f\u064e\u0627\u0653 \u0623\u064e\u0628\u0650\u064a \u0644\u064e\u0647\u064e\u0628\u0656 \u0648\u064e\u062a\u064e\u0628\u0651\u064e",translation:"Binasalah kedua tangan Abu Lahab dan benar-benar binasa dia"},{id:2,text:"\u0645\u064e\u0627\u0653 \u0623\u064e\u063a\u06e1\u0646\u064e\u0649\u0670 \u0639\u064e\u0646\u06e1\u0647\u064f \u0645\u064e\u0627\u0644\u064f\u0647\u064f\u06e5 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0633\u064e\u0628\u064e",translation:"Tidaklah berguna baginya hartanya dan apa yang dia usahakan"},{id:3,text:"\u0633\u064e\u064a\u064e\u0635\u06e1\u0644\u064e\u0649\u0670 \u0646\u064e\u0627\u0631\u0657\u0627 \u0630\u064e\u0627\u062a\u064e \u0644\u064e\u0647\u064e\u0628\u0656",translation:"Kelak dia akan masuk ke dalam api yang bergejolak (neraka)"},{id:4,text:"\u0648\u064e\u0671\u0645\u06e1\u0631\u064e\u0623\u064e\u062a\u064f\u0647\u064f\u06e5 \u062d\u064e\u0645\u0651\u064e\u0627\u0644\u064e\u0629\u064e \u0671\u0644\u06e1\u062d\u064e\u0637\u064e\u0628\u0650",translation:"Dan (begitu pula) istrinya, pembawa kayu bakar (penyebar fitnah)"},{id:5,text:"\u0641\u0650\u064a \u062c\u0650\u064a\u062f\u0650\u0647\u064e\u0627 \u062d\u064e\u0628\u06e1\u0644\u065e \u0645\u0651\u0650\u0646 \u0645\u0651\u064e\u0633\u064e\u062f\u0650\u06ed",translation:"Di lehernya ada tali dari sabut yang dipintal"}]},{id:112,name:"\u0627\u0644\u0625\u062e\u0644\u0627\u0635",transliteration:"Al-Ikhlas",translation:"Ikhlash",type:"meccan",total_verses:4,verses:[{id:1,text:"\u0642\u064f\u0644\u06e1 \u0647\u064f\u0648\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u062d\u064e\u062f\u064c",translation:"Katakanlah (Muhammad), \"Dialah Allah, Yang Maha Esa"},{id:2,text:"\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0671\u0644\u0635\u0651\u064e\u0645\u064e\u062f\u064f",translation:"Allah tempat meminta segala sesuatu"},{id:3,text:"\u0644\u064e\u0645\u06e1 \u064a\u064e\u0644\u0650\u062f\u06e1 \u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064f\u0648\u0644\u064e\u062f\u06e1",translation:"(Allah) tidak beranak dan tidak pula diperanakkan"},{id:4,text:"\u0648\u064e\u0644\u064e\u0645\u06e1 \u064a\u064e\u0643\u064f\u0646 \u0644\u0651\u064e\u0647\u064f\u06e5 \u0643\u064f\u0641\u064f\u0648\u064b\u0627 \u0623\u064e\u062d\u064e\u062f\u064f\u06e2",translation:"Dan tidak ada sesuatu yang setara dengan Dia"}]},{id:113,name:"\u0627\u0644\u0641\u0644\u0642",transliteration:"Al-Falaq",translation:"Waktu Shubuh",type:"meccan",total_verses:5,verses:[{id:1,text:"\u0642\u064f\u0644\u06e1 \u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0631\u064e\u0628\u0651\u0650 \u0671\u0644\u06e1\u0641\u064e\u0644\u064e\u0642\u0650",translation:"Katakanlah, \"Aku berlindung kepada Tuhan yang menguasai subuh (fajar)"},{id:2,text:"\u0645\u0650\u0646 \u0634\u064e\u0631\u0651\u0650 \u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u064e",translation:"dari kejahatan (makhluk yang) Dia ciptakan"},{id:3,text:"\u0648\u064e\u0645\u0650\u0646 \u0634\u064e\u0631\u0651\u0650 \u063a\u064e\u0627\u0633\u0650\u0642\u064d \u0625\u0650\u0630\u064e\u0627 \u0648\u064e\u0642\u064e\u0628\u064e",translation:"dan dari kejahatan malam apabila telah gelap gulita"},{id:4,text:"\u0648\u064e\u0645\u0650\u0646 \u0634\u064e\u0631\u0651\u0650 \u0671\u0644\u0646\u0651\u064e\u0641\u0651\u064e\u0640\u0670\u062b\u064e\u0670\u062a\u0650 \u0641\u0650\u064a \u0671\u0644\u06e1\u0639\u064f\u0642\u064e\u062f\u0650",translation:"dan dari kejahatan (perempuan-perempuan) penyihir yang meniup pada buhul-buhul (talinya)"},{id:5,text:"\u0648\u064e\u0645\u0650\u0646 \u0634\u064e\u0631\u0651\u0650 \u062d\u064e\u0627\u0633\u0650\u062f\u064d \u0625\u0650\u0630\u064e\u0627 \u062d\u064e\u0633\u064e\u062f\u064e",translation:"dan dari kejahatan orang yang dengki apabila dia dengki"}]},{id:114,name:"\u0627\u0644\u0646\u0627\u0633",transliteration:"An-Nas",translation:"Umat Manusia",type:"meccan",total_verses:6,verses:[{id:1,text:"\u0642\u064f\u0644\u06e1 \u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0631\u064e\u0628\u0651\u0650 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650",translation:"Katakanlah, \"Aku berlindung kepada Tuhannya manusia"},{id:2,text:"\u0645\u064e\u0644\u0650\u0643\u0650 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650",translation:"Raja manusia"},{id:3,text:"\u0625\u0650\u0644\u064e\u0670\u0647\u0650 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650",translation:"sembahan manusia"},{id:4,text:"\u0645\u0650\u0646 \u0634\u064e\u0631\u0651\u0650 \u0671\u0644\u06e1\u0648\u064e\u0633\u06e1\u0648\u064e\u0627\u0633\u0650 \u0671\u0644\u06e1\u062e\u064e\u0646\u0651\u064e\u0627\u0633\u0650",translation:"dari kejahatan (bisikan) setan yang bersembunyi"},{id:5,text:"\u0671\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u0648\u064e\u0633\u06e1\u0648\u0650\u0633\u064f \u0641\u0650\u064a \u0635\u064f\u062f\u064f\u0648\u0631\u0650 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650",translation:"yang membisikkan (kejahatan) ke dalam dada manusia"},{id:6,text:"\u0645\u0650\u0646\u064e \u0671\u0644\u06e1\u062c\u0650\u0646\u0651\u064e\u0629\u0650 \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650",translation:"dari (golongan) jin dan manusia"}]}]},1284,[]);